INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1668926,58,1,1,1,'Alussa loi Jumala taivaan ja maan.'),
(1668927,58,1,1,2,'Ja maa oli autio ja tyhjä, ja pimeys oli syvyyden päällä, ja Jumalan Henki liikkui vetten päällä.'),
(1668928,58,1,1,3,'Ja Jumala sanoi: "Tulkoon valkeus". Ja valkeus tuli.'),
(1668929,58,1,1,4,'Ja Jumala näki, että valkeus oli hyvä; ja Jumala erotti valkeuden pimeydestä.'),
(1668930,58,1,1,5,'Ja Jumala kutsui valkeuden päiväksi, ja pimeyden hän kutsui yöksi. Ja tuli ehtoo, ja tuli aamu, ensimmäinen päivä.'),
(1668931,58,1,1,6,'Ja Jumala sanoi: "Tulkoon taivaanvahvuus vetten välille erottamaan vedet vesistä".'),
(1668932,58,1,1,7,'Ja Jumala teki taivaanvahvuuden ja erotti vedet, jotka olivat taivaanvahvuuden alla, vesistä, jotka olivat taivaanvahvuuden päällä; ja tapahtui niin.'),
(1668933,58,1,1,8,'Ja Jumala kutsui vahvuuden taivaaksi. Ja tuli ehtoo, ja tuli aamu, toinen päivä.'),
(1668934,58,1,1,9,'Ja Jumala sanoi: "Kokoontukoot vedet, jotka ovat taivaan alla, yhteen paikkaan, niin että kuiva tulee näkyviin". Ja tapahtui niin.'),
(1668935,58,1,1,10,'Ja Jumala kutsui kuivan maaksi, ja paikan, mihin vedet olivat kokoontuneet, hän kutsui mereksi. Ja Jumala näki, että se oli hyvä.'),
(1668936,58,1,1,11,'Ja Jumala sanoi: "Kasvakoon maa vihantaa, ruohoja, jotka tekevät siementä, ja hedelmäpuita, jotka lajiensa mukaan kantavat maan päällä hedelmää, jossa niiden siemen on". Ja tapahtui niin:'),
(1668937,58,1,1,12,'maa tuotti vihantaa, ruohoja, jotka tekivät siementä lajiensa mukaan, ja puita, jotka lajiensa mukaan kantoivat hedelmää, jossa niiden siemen oli. Ja Jumala näki, että se oli hyvä.'),
(1668938,58,1,1,13,'Ja tuli ehtoo, ja tuli aamu, kolmas päivä.'),
(1668939,58,1,1,14,'Ja Jumala sanoi: "Tulkoot valot taivaanvahvuuteen erottamaan päivää yöstä, ja olkoot ne merkkeinä osoittamassa aikoja, päiviä ja vuosia,'),
(1668940,58,1,1,15,'ja olkoot valoina taivaanvahvuudella paistamassa maan päälle". Ja tapahtui niin:'),
(1668941,58,1,1,16,'Jumala teki kaksi suurta valoa, suuremman valon hallitsemaan päivää ja pienemmän valon hallitsemaan yötä, sekä tähdet.'),
(1668942,58,1,1,17,'Ja Jumala pani ne taivaanvahvuuteen, paistamaan maan päälle'),
(1668943,58,1,1,18,'ja hallitsemaan päivää ja yötä ja erottamaan valon pimeästä. Ja Jumala näki, että se oli hyvä.'),
(1668944,58,1,1,19,'Ja tuli ehtoo, ja tuli aamu, neljäs päivä.'),
(1668945,58,1,1,20,'Ja Jumala sanoi: "Viliskööt vedet eläviä olentoja, ja lentäkööt linnut maan päällä, taivaanvahvuuden alla".'),
(1668946,58,1,1,21,'Ja Jumala loi suuret merieläimet ja kaikkinaiset liikkuvat, vesissä vilisevät elävät olennot, kunkin lajinsa mukaan, ja kaikkinaiset siivekkäät linnut, kunkin lajinsa mukaan. Ja Jumala näki, että se oli hyvä.'),
(1668947,58,1,1,22,'Ja Jumala siunasi ne sanoen: "Olkaa hedelmälliset ja lisääntykää ja täyttäkää meren vedet, ja linnut lisääntykööt maan päällä".'),
(1668948,58,1,1,23,'Ja tuli ehtoo, ja tuli aamu, viides päivä.'),
(1668949,58,1,1,24,'Ja Jumala sanoi: "Tuottakoon maa elävät olennot, kunkin lajinsa mukaan, karjaeläimet ja matelijat ja metsäeläimet, kunkin lajinsa mukaan". Ja tapahtui niin:'),
(1668950,58,1,1,25,'Jumala teki metsäeläimet, kunkin lajinsa mukaan, ja karjaeläimet, kunkin lajinsa mukaan, ja kaikki maan matelijat, kunkin lajinsa mukaan. Ja Jumala näki, että se oli hyvä.'),
(1668951,58,1,1,26,'Ja Jumala sanoi: "Tehkäämme ihminen kuvaksemme, kaltaiseksemme; ja vallitkoot he meren kalat ja taivaan linnut ja karjaeläimet ja koko maan ja kaikki matelijat, jotka maassa matelevat".'),
(1668952,58,1,1,27,'Ja Jumala loi ihmisen omaksi kuvaksensa, Jumalan kuvaksi hän hänet loi; mieheksi ja naiseksi hän loi heidät.'),
(1668953,58,1,1,28,'Ja Jumala siunasi heidät, ja Jumala sanoi heille: "Olkaa hedelmälliset ja lisääntykää ja täyttäkää maa ja tehkää se itsellenne alamaiseksi; ja vallitkaa meren kalat ja taivaan linnut ja kaikki maan päällä liikkuvat eläimet".'),
(1668954,58,1,1,29,'Ja Jumala sanoi: "Katso, minä annan teille kaikkinaiset siementä tekevät ruohot, joita kasvaa kaikkialla maan päällä, ja kaikki puut, joissa on siementä tekevä hedelmä; olkoot ne teille ravinnoksi.'),
(1668955,58,1,1,30,'Ja kaikille metsäeläimille ja kaikille taivaan linnuille ja kaikille, jotka maassa matelevat ja joissa on elävä henki, minä annan kaikkinaiset viheriät ruohot ravinnoksi". Ja tapahtui niin.'),
(1668956,58,1,1,31,'Ja Jumala katsoi kaikkea, mitä hän tehnyt oli, ja katso, se oli sangen hyvää. Ja tuli ehtoo, ja tuli aamu, kuudes päivä.'),
(1668957,58,1,2,1,'Niin tulivat valmiiksi taivas ja maa kaikkine joukkoinensa.'),
(1668958,58,1,2,2,'Ja Jumala päätti seitsemäntenä päivänä työnsä, jonka hän oli tehnyt, ja lepäsi seitsemäntenä päivänä kaikesta työstänsä, jonka hän oli tehnyt.'),
(1668959,58,1,2,3,'Ja Jumala siunasi seitsemännen päivän ja pyhitti sen, koska hän sinä päivänä lepäsi kaikesta luomistyöstänsä, jonka hän oli tehnyt.'),
(1668960,58,1,2,4,'Tämä on kertomus taivaan ja maan synnystä, kun ne luotiin. Siihen aikaan kun Herra Jumala teki maan ja taivaan,'),
(1668961,58,1,2,5,'ei ollut vielä yhtään kedon pensasta maan päällä, eikä vielä kasvanut mitään ruohoa kedolla, koska Herra Jumala ei vielä ollut antanut sataa maan päälle eikä ollut ihmistä maata viljelemässä,'),
(1668962,58,1,2,6,'vaan sumu nousi maasta ja kasteli koko maan pinnan.'),
(1668963,58,1,2,7,'Silloin Herra Jumala teki maan tomusta ihmisen ja puhalsi hänen sieramiinsa elämän hengen, ja niin ihmisestä tuli elävä sielu.'),
(1668964,58,1,2,8,'Ja Herra Jumala istutti paratiisin Eedeniin, itään, ja asetti sinne ihmisen, jonka hän oli tehnyt.'),
(1668965,58,1,2,9,'Ja Herra Jumala kasvatti maasta kaikkinaisia puita, ihania nähdä ja hyviä syödä, ja elämän puun keskelle paratiisia, niin myös hyvän- ja pahantiedon puun.'),
(1668966,58,1,2,10,'Ja Eedenistä lähti joki, joka kasteli paratiisia, ja se jakaantui sieltä neljään haaraan.'),
(1668967,58,1,2,11,'Ensimmäisen nimi on Piison; se kiertää koko Havilan maan, jossa on kultaa;'),
(1668968,58,1,2,12,'ja sen maan kulta on hyvää. Siellä on myös bedellion-pihkaa ja onyks-kiveä.'),
(1668969,58,1,2,13,'Toisen virran nimi on Giihon; se kiertää koko Kuusin maan.'),
(1668970,58,1,2,14,'Kolmannen virran nimi on Hiddekel; se juoksee Assurin editse. Ja neljäs virta on Eufrat.'),
(1668971,58,1,2,15,'Ja Herra Jumala otti ihmisen ja pani hänet Eedenin paratiisiin viljelemään ja varjelemaan sitä.'),
(1668972,58,1,2,16,'Ja Herra Jumala käski ihmistä sanoen: "Syö vapaasti kaikista muista paratiisin puista,'),
(1668973,58,1,2,17,'mutta hyvän- ja pahantiedon puusta älä syö, sillä sinä päivänä, jona sinä siitä syöt, pitää sinun kuolemalla kuoleman".'),
(1668974,58,1,2,18,'Ja Herra Jumala sanoi: "Ei ole ihmisen hyvä olla yksinänsä, minä teen hänelle avun, joka on hänelle sopiva".'),
(1668975,58,1,2,19,'Ja Herra Jumala teki maasta kaikki metsän eläimet ja kaikki taivaan linnut ja toi ne ihmisen eteen nähdäkseen, kuinka hän ne nimittäisi; ja niinkuin ihminen nimitti kunkin elävän olennon, niin oli sen nimi oleva.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1668976,58,1,2,20,'Ja ihminen antoi nimet kaikille karjaeläimille ja taivaan linnuille ja kaikille metsän eläimille. Mutta Aadamille ei löytynyt apua, joka olisi hänelle sopinut.'),
(1668977,58,1,2,21,'Niin Herra Jumala vaivutti ihmisen raskaaseen uneen, ja kun hän nukkui, otti hän yhden hänen kylkiluistaan ja täytti sen paikan lihalla.'),
(1668978,58,1,2,22,'Ja Herra Jumala rakensi vaimon siitä kylkiluusta, jonka hän oli ottanut miehestä, ja toi hänet miehen luo.'),
(1668979,58,1,2,23,'Ja mies sanoi: "Tämä on nyt luu minun luistani ja liha minun lihastani; hän kutsuttakoon miehettäreksi, sillä hän on miehestä otettu".'),
(1668980,58,1,2,24,'Sentähden mies luopukoon isästänsä ja äidistänsä ja liittyköön vaimoonsa, ja he tulevat yhdeksi lihaksi.'),
(1668981,58,1,2,25,'Ja he olivat molemmat, mies ja hänen vaimonsa, alasti eivätkä hävenneet toisiansa.'),
(1668982,58,1,3,1,'Mutta käärme oli kavalin kaikista kedon eläimistä, jotka Herra Jumala oli tehnyt; ja se sanoi vaimolle: "Onko Jumala todellakin sanonut: ''Älkää syökö kaikista paratiisin puista''?"'),
(1668983,58,1,3,2,'Niin vaimo vastasi käärmeelle: "Me saamme syödä muiden puiden hedelmiä paratiisissa,'),
(1668984,58,1,3,3,'mutta sen puun hedelmästä, joka on keskellä paratiisia, on Jumala sanonut: ''Älkää syökö siitä älkääkä koskeko siihen, ettette kuolisi''."'),
(1668985,58,1,3,4,'Niin käärme sanoi vaimolle: "Ette suinkaan kuole;'),
(1668986,58,1,3,5,'vaan Jumala tietää, että sinä päivänä, jona te siitä syötte, aukenevat teidän silmänne, ja te tulette niinkuin Jumala tietämään hyvän ja pahan".'),
(1668987,58,1,3,6,'Ja vaimo näki, että siitä puusta oli hyvä syödä ja että se oli ihana katsella ja suloinen puu antamaan ymmärrystä; ja hän otti sen hedelmästä ja söi ja antoi myös miehellensä, joka oli hänen kanssansa, ja hänkin söi.'),
(1668988,58,1,3,7,'Silloin aukenivat heidän molempain silmät, ja he huomasivat olevansa alasti; ja he sitoivat yhteen viikunapuun lehtiä ja tekivät itselleen vyöverhot.'),
(1668989,58,1,3,8,'Ja he kuulivat, kuinka Herra Jumala käyskenteli paratiisissa illan viileydessä. Ja mies vaimoineen lymysi Herran Jumalan kasvojen edestä paratiisin puiden sekaan.'),
(1668990,58,1,3,9,'Mutta Herra Jumala huusi miestä ja sanoi hänelle: "Missä olet?"'),
(1668991,58,1,3,10,'Hän vastasi: "Minä kuulin sinun askeleesi paratiisissa ja pelkäsin, sillä minä olen alasti, ja sentähden minä lymysin".'),
(1668992,58,1,3,11,'Ja hän sanoi: "Kuka sinulle ilmoitti, että olet alasti? Etkö syönyt siitä puusta, josta minä kielsin sinua syömästä?"'),
(1668993,58,1,3,12,'Mies vastasi: "Vaimo, jonka annoit olemaan minun kanssani, antoi minulle siitä puusta, ja minä söin".'),
(1668994,58,1,3,13,'Niin Herra Jumala sanoi vaimolle: "Mitäs olet tehnyt?" Vaimo vastasi: "Käärme petti minut, ja minä söin".'),
(1668995,58,1,3,14,'Ja Herra Jumala sanoi käärmeelle: "Koska tämän teit, kirottu ole sinä kaikkien karjaeläinten ja kaikkien metsän eläinten joukossa. Vatsallasi sinun pitää käymän ja tomua syömän koko elinaikasi.'),
(1668996,58,1,3,15,'Ja minä panen vainon sinun ja vaimon välille ja sinun siemenesi ja hänen siemenensä välille; se on polkeva rikki sinun pääsi, ja sinä olet pistävä sitä kantapäähän."'),
(1668997,58,1,3,16,'Ja vaimolle hän sanoi: "Minä teen suuriksi sinun raskautesi vaivat, kivulla sinun pitää synnyttämän lapsia; mutta mieheesi on sinun halusi oleva, ja hän on sinua vallitseva".'),
(1668998,58,1,3,17,'Ja Aadamille hän sanoi: "Koska kuulit vaimoasi ja söit puusta, josta minä kielsin sinua sanoen: ''Älä syö siitä'', niin kirottu olkoon maa sinun tähtesi. Vaivaa nähden sinun pitää elättämän itseäsi siitä koko elinaikasi;'),
(1668999,58,1,3,18,'orjantappuroita ja ohdakkeita se on kasvava sinulle, ja kedon ruohoja sinun on syötävä.'),
(1669000,58,1,3,19,'Otsasi hiessä sinun pitää syömän leipäsi, kunnes tulet maaksi jälleen, sillä siitä sinä olet otettu. Sillä maasta sinä olet, ja maaksi pitää sinun jälleen tuleman."'),
(1669001,58,1,3,20,'Ja mies antoi vaimolleen nimen Eeva, sillä hänestä tuli kaiken elävän äiti.'),
(1669002,58,1,3,21,'Ja Herra Jumala teki Aadamille ja hänen vaimollensa puvut nahasta ja puki ne heidän yllensä.'),
(1669003,58,1,3,22,'Ja Herra Jumala sanoi: "Katso, ihminen on tullut sellaiseksi kuin joku meistä, niin että hän tietää hyvän ja pahan. Kun ei hän nyt vain ojentaisi kättänsä ja ottaisi myös elämän puusta ja söisi ja eläisi iankaikkisesti!"'),
(1669004,58,1,3,23,'Niin Herra Jumala ajoi hänet pois Eedenin paratiisista viljelemään maata, josta hän oli otettu.'),
(1669005,58,1,3,24,'Ja hän karkoitti ihmisen ja asetti Eedenin paratiisin itäpuolelle kerubit ynnä välkkyvän, leimuavan miekan vartioitsemaan elämän puun tietä.'),
(1669006,58,1,4,1,'Ja mies yhtyi vaimoonsa Eevaan; ja tämä tuli raskaaksi ja synnytti Kainin ja sanoi: "Minä olen saanut pojan Herran avulla".'),
(1669007,58,1,4,2,'Ja taas hän synnytti pojan, veljen Kainille, Aabelin. Ja Aabelista tuli lampuri, mutta Kainista peltomies.'),
(1669008,58,1,4,3,'Ja jonkun ajan kuluttua tapahtui, että Kain toi maan hedelmistä uhrilahjan Herralle;'),
(1669009,58,1,4,4,'ja myöskin Aabel toi uhrilahjan laumansa esikoisista, niiden rasvoista. Ja Herra katsoi Aabelin ja hänen uhrilahjansa puoleen;'),
(1669010,58,1,4,5,'mutta Kainin ja hänen uhrilahjansa puoleen hän ei katsonut. Silloin Kain vihastui kovin, ja hänen hahmonsa synkistyi.'),
(1669011,58,1,4,6,'Ja Herra sanoi Kainille: "Miksi olet vihastunut, ja miksi hahmosi synkistyy?'),
(1669012,58,1,4,7,'Eikö niin: jos teet hyvin, voit kohottaa katseesi; mutta jos et hyvin tee, niin väijyy synti ovella, ja sen halu on sinuun, mutta hallitse sinä sitä!"'),
(1669013,58,1,4,8,'Ja Kain sanoi veljellensä Aabelille: "Menkäämme kedolle". Ja heidän kedolla ollessansa Kain karkasi veljensä Aabelin kimppuun ja tappoi hänet.'),
(1669014,58,1,4,9,'Niin Herra sanoi Kainille: "Missä on veljesi Aabel?" Hän vastasi: "En tiedä; olenko minä veljeni vartija?"'),
(1669015,58,1,4,10,'Ja hän sanoi: "Mitä olet tehnyt? Kuule, veljesi veri huutaa minulle maasta.'),
(1669016,58,1,4,11,'Ja nyt ole kirottu ja karkoitettu pois tältä vainiolta, joka avasi suunsa ottamaan veljesi veren sinun kädestäsi.'),
(1669017,58,1,4,12,'Kun maata viljelet, ei se ole enää sinulle satoansa antava; kulkija ja pakolainen pitää sinun oleman maan päällä."'),
(1669018,58,1,4,13,'Ja Kain sanoi Herralle: "Syyllisyyteni on suurempi, kuin että sen kantaa voisin.'),
(1669019,58,1,4,14,'Katso, sinä karkoitat minut nyt pois vainiolta, ja minun täytyy lymytä sinun kasvojesi edestä ja olla kulkija ja pakolainen maan päällä; ja kuka ikinä minut kohtaa, se tappaa minut."'),
(1669020,58,1,4,15,'Mutta Herra sanoi hänelle: "Sentähden, kuka ikinä tappaa Kainin, hänelle se pitää seitsenkertaisesti kostettaman". Ja Herra pani Kainiin merkin, ettei kukaan, joka hänet kohtaisi, tappaisi häntä.'),
(1669021,58,1,4,16,'Niin Kain poistui Herran kasvojen edestä ja asettui asumaan Noodin maahan, itään päin Eedenistä.'),
(1669022,58,1,4,17,'Ja Kain yhtyi vaimoonsa, ja tämä tuli raskaaksi ja synnytti Hanokin. Ja hän rakensi kaupungin ja antoi sille kaupungille poikansa nimen Hanok.'),
(1669023,58,1,4,18,'Ja Hanokille syntyi Iirad, Iiradille syntyi Mehujael, Mehujaelille syntyi Metusael, Metusaelille syntyi Lemek.'),
(1669024,58,1,4,19,'Lemek otti itselleen kaksi vaimoa, toisen nimi oli Aada ja toisen nimi Silla.'),
(1669025,58,1,4,20,'Ja Aada synnytti Jaabalin; hänestä tuli niiden kantaisä, jotka teltoissa asuvat ja karjanhoitoa harjoittavat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669026,58,1,4,21,'Ja hänen veljensä nimi oli Juubal; hänestä tuli kaikkien niiden kantaisä, jotka kannelta ja huilua soittavat.'),
(1669027,58,1,4,22,'Myöskin Silla synnytti pojan, Tuubal-Kainin; hänestä tuli kaikkinaisten vaski- ja rauta-aseiden takoja. Ja Tuubal-Kainin sisar oli Naema.'),
(1669028,58,1,4,23,'Ja Lemek lausui vaimoillensa: "Aada ja Silla, kuulkaa puhettani, te Lemekin emännät, ottakaa sanani korviinne: minä surmaan miehen haavastani ja nuorukaisen mustelmastani.'),
(1669029,58,1,4,24,'Niin, Kain kostetaan seitsenkertaisesti, mutta Lemek seitsemänkymmentä seitsemän kertaa."'),
(1669030,58,1,4,25,'Ja Aadam yhtyi taas vaimoonsa, ja tämä synnytti pojan ja antoi hänelle nimen Seet, sanoen: "Jumala on suonut minulle toisen pojan Aabelin sijaan, koska Kain hänet surmasi".'),
(1669031,58,1,4,26,'Ja myöskin Seetille syntyi poika, ja hän antoi hänelle nimen Enos. Siihen aikaan ruvettiin avuksi huutamaan Herran nimeä.'),
(1669032,58,1,5,1,'Tämä on Aadamin sukuluettelo. Kun Jumala loi ihmisen, teki hän hänet Jumalan kaltaiseksi.'),
(1669033,58,1,5,2,'Mieheksi ja naiseksi hän heidät loi ja siunasi heidät ja antoi heille nimen ihminen, silloin kun heidät luotiin.'),
(1669034,58,1,5,3,'Kun Aadam oli sadan kolmenkymmenen vuoden vanha, syntyi hänelle poika, joka oli hänen kaltaisensa, hänen kuvansa, ja hän antoi hänelle nimen Seet.'),
(1669035,58,1,5,4,'Ja Aadam eli Seetin syntymän jälkeen kahdeksansataa vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669036,58,1,5,5,'Niin oli Aadamin koko elinaika yhdeksänsataa kolmekymmentä vuotta; sitten hän kuoli.'),
(1669037,58,1,5,6,'Kun Seet oli sadan viiden vuoden vanha, syntyi hänelle Enos.'),
(1669038,58,1,5,7,'Ja Seet eli Enoksen syntymän jälkeen kahdeksansataa seitsemän vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669039,58,1,5,8,'Niin oli Seetin koko elinaika yhdeksänsataa kaksitoista vuotta; sitten hän kuoli.'),
(1669040,58,1,5,9,'Kun Enos oli yhdeksänkymmenen vuoden vanha, syntyi hänelle Keenan.'),
(1669041,58,1,5,10,'Ja Enos eli Keenanin syntymän jälkeen kahdeksansataa viisitoista vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669042,58,1,5,11,'Niin oli Enoksen koko elinaika yhdeksänsataa viisi vuotta; sitten hän kuoli.'),
(1669043,58,1,5,12,'Kun Keenan oli seitsemänkymmenen vuoden vanha, syntyi hänelle Mahalalel.'),
(1669044,58,1,5,13,'Ja Keenan eli Mahalalelin syntymän jälkeen kahdeksansataa neljäkymmentä vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669045,58,1,5,14,'Niin oli Keenanin koko elinaika yhdeksänsataa kymmenen vuotta; sitten hän kuoli.'),
(1669046,58,1,5,15,'Kun Mahalalel oli kuudenkymmenen viiden vuoden vanha, syntyi hänelle Jered.'),
(1669047,58,1,5,16,'Ja Mahalalel eli Jeredin syntymän jälkeen kahdeksansataa kolmekymmentä vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669048,58,1,5,17,'Niin oli Mahalalelin koko elinaika kahdeksansataa yhdeksänkymmentä viisi vuotta; sitten hän kuoli.'),
(1669049,58,1,5,18,'Kun Jered oli sadan kuudenkymmenen kahden vuoden vanha, syntyi hänelle Hanok.'),
(1669050,58,1,5,19,'Ja Jered eli Hanokin syntymän jälkeen kahdeksansataa vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669051,58,1,5,20,'Niin oli Jeredin koko elinaika yhdeksänsataa kuusikymmentä kaksi vuotta; sitten hän kuoli.'),
(1669052,58,1,5,21,'Kun Hanok oli kuudenkymmenen viiden vuoden vanha, syntyi hänelle Metusalah.'),
(1669053,58,1,5,22,'Ja Hanok vaelsi Metusalahin syntymän jälkeen Jumalan yhteydessä kolmesataa vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669054,58,1,5,23,'Niin oli Hanokin koko elinaika kolmesataa kuusikymmentä viisi vuotta.'),
(1669055,58,1,5,24,'Ja kun Hanok oli vaeltanut Jumalan yhteydessä, ei häntä enää ollut, sillä Jumala oli ottanut hänet pois.'),
(1669056,58,1,5,25,'Kun Metusalah oli sadan kahdeksankymmenen seitsemän vuoden vanha, syntyi hänelle Lemek.'),
(1669057,58,1,5,26,'Ja Metusalah eli Lemekin syntymän jälkeen seitsemänsataa kahdeksankymmentä kaksi vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669058,58,1,5,27,'Niin oli Metusalahin koko elinaika yhdeksänsataa kuusikymmentä yhdeksän vuotta; sitten hän kuoli.'),
(1669059,58,1,5,28,'Kun Lemek oli sadan kahdeksankymmenen kahden vuoden vanha, syntyi hänelle poika.'),
(1669060,58,1,5,29,'Ja hän antoi hänelle nimen Nooa, sanoen: "Tämä lohduttaa meitä työssämme ja kättemme vaivoissa viljellessämme maata, jonka Herra on kironnut".'),
(1669061,58,1,5,30,'Ja Lemek eli Nooan syntymän jälkeen viisisataa yhdeksänkymmentä viisi vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669062,58,1,5,31,'Niin oli Lemekin koko elinaika seitsemänsataa seitsemänkymmentä seitsemän vuotta; sitten hän kuoli.'),
(1669063,58,1,5,32,'Kun Nooa oli viidensadan vuoden vanha, syntyivät hänelle Seem, Haam ja Jaafet.'),
(1669064,58,1,6,1,'Kun ihmiset alkoivat lisääntyä maan päällä ja heille syntyi tyttäriä,'),
(1669065,58,1,6,2,'huomasivat Jumalan pojat ihmisten tyttäret ihaniksi ja ottivat vaimoikseen kaikki, jotka he parhaiksi katsoivat.'),
(1669066,58,1,6,3,'Silloin Herra sanoi: "Minun Henkeni ei ole vallitseva ihmisessä iankaikkisesti, koska hän on liha. Niin olkoon hänen aikansa sata kaksikymmentä vuotta."'),
(1669067,58,1,6,4,'Siihen aikaan eli maan päällä jättiläisiä, ja myöhemminkin, kun Jumalan pojat yhtyivät ihmisten tyttäriin ja nämä synnyttivät heille lapsia; nämä olivat noita muinaisajan kuuluisia sankareita.'),
(1669068,58,1,6,5,'Mutta kun Herra näki, että ihmisten pahuus oli suuri maan päällä ja että kaikki heidän sydämensä aivoitukset ja ajatukset olivat kaiken aikaa ainoastaan pahat,'),
(1669069,58,1,6,6,'niin Herra katui tehneensä ihmiset maan päälle, ja hän tuli murheelliseksi sydämessänsä.'),
(1669070,58,1,6,7,'Ja Herra sanoi: "Minä hävitän maan päältä ihmiset, jotka minä loin, sekä ihmiset että karjan, matelijat ja taivaan linnut; sillä minä kadun ne tehneeni".'),
(1669071,58,1,6,8,'Mutta Nooa sai armon Herran silmien edessä.'),
(1669072,58,1,6,9,'Tämä on kertomus Nooan suvusta. Nooa oli aikalaistensa keskuudessa hurskas ja nuhteeton mies ja vaelsi Jumalan yhteydessä.'),
(1669073,58,1,6,10,'Ja Nooalle syntyi kolme poikaa, Seem, Haam ja Jaafet.'),
(1669074,58,1,6,11,'Mutta maa turmeltui Jumalan edessä, ja maa tuli täyteen väkivaltaa.'),
(1669075,58,1,6,12,'Niin Jumala näki, että maa oli turmeltunut; sillä kaikki liha oli turmellut vaelluksensa maan päällä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669076,58,1,6,13,'Silloin Jumala sanoi Nooalle: "Minä olen päättänyt tehdä lopun kaikesta lihasta, sillä maa on heidän tähtensä täynnä väkivaltaa; katso, minä hävitän heidät ynnä maan.'),
(1669077,58,1,6,14,'Tee itsellesi arkki honkapuista, rakenna arkki täyteen kammioita, ja tervaa se sisältä ja ulkoa.'),
(1669078,58,1,6,15,'Ja näin on sinun se rakennettava: kolmesataa kyynärää olkoon arkin pituus, viisikymmentä kyynärää sen leveys ja kolmekymmentä kyynärää sen korkeus.'),
(1669079,58,1,6,16,'Tee arkkiin valoaukko, ja tee se kyynärän korkuiseksi, ja sijoita arkin ovi sen kylkeen; rakenna siihen kolme kerrosta, alimmainen, keskimmäinen ja ylimmäinen.'),
(1669080,58,1,6,17,'Sillä katso, minä annan vedenpaisumuksen tulla yli maan hävittämään taivaan alta kaiken lihan, kaiken, jossa on elämän henki; kaikki, mikä on maan päällä, on hukkuva.'),
(1669081,58,1,6,18,'Mutta sinun kanssasi minä teen liiton, ja sinun on mentävä arkkiin, sinun ja sinun poikiesi, vaimosi ja miniäisi sinun kanssasi.'),
(1669082,58,1,6,19,'Ja kaikista eläimistä, kaikesta lihasta, sinun on vietävä arkkiin kaksi kutakin lajia säilyttääksesi ne hengissä kanssasi; niitä olkoon koiras ja naaras.'),
(1669083,58,1,6,20,'Lintuja lajiensa mukaan, karjaeläimiä lajiensa mukaan ja kaikkia maan matelijoita lajiensa mukaan tulkoon kaksi kutakin lajia sinun luoksesi, säilyttääksesi ne hengissä.'),
(1669084,58,1,6,21,'Ja hanki itsellesi kaikkinaista ravintoa, syötäväksi kelpaavaa, ja kokoa sitä talteesi, että se olisi ruuaksi sinulle ja heille."'),
(1669085,58,1,6,22,'Ja Nooa teki näin; aivan niin kuin Jumala hänen käski tehdä, niin hän teki.'),
(1669086,58,1,7,1,'Ja Herra sanoi Nooalle: "Mene sinä ja koko perheesi arkkiin, sillä sinut minä olen tässä sukukunnassa havainnut hurskaaksi edessäni.'),
(1669087,58,1,7,2,'Kaikkia puhtaita eläimiä ota luoksesi seitsemän paria, koiraita ja naaraita, mutta epäpuhtaita eläimiä kutakin yksi pari, koiras ja naaras.'),
(1669088,58,1,7,3,'Niin myös taivaan lintuja seitsemän paria, koiraita ja naaraita, että siemen säilyisi elossa koko maan päällä.'),
(1669089,58,1,7,4,'Sillä seitsemän päivän kuluttua minä annan sataa maan päälle neljäkymmentä päivää ja neljäkymmentä yötä ja hävitän maan päältä kaikki olennot, jotka olen tehnyt."'),
(1669090,58,1,7,5,'Ja Nooa teki näin, aivan niin kuin Herra oli hänen käskenyt tehdä.'),
(1669091,58,1,7,6,'Nooa oli kuudensadan vuoden vanha, kun vedenpaisumus tuli maan päälle.'),
(1669092,58,1,7,7,'Ja Nooa ja hänen poikansa, vaimonsa ja miniänsä hänen kanssaan menivät arkkiin vedenpaisumusta pakoon.'),
(1669093,58,1,7,8,'Puhtaita eläimiä ja epäpuhtaita eläimiä, lintuja ja kaikkia, joita maassa matelee,'),
(1669094,58,1,7,9,'meni Nooan luo arkkiin kaksittain, koiras ja naaras, niinkuin Jumala oli Nooalle käskyn antanut.'),
(1669095,58,1,7,10,'Ja niiden seitsemän päivän kuluttua tuli vedenpaisumus maan päälle.'),
(1669096,58,1,7,11,'Ja sinä vuonna, jona Nooa oli kuudensadan vuoden vanha, sen toisena kuukautena, kuukauden seitsemäntenätoista päivänä, sinä päivänä puhkesivat kaikki suuren syvyyden lähteet, ja taivaan akkunat aukenivat.'),
(1669097,58,1,7,12,'Ja satoi rankasti maan päälle neljäkymmentä päivää ja neljäkymmentä yötä.'),
(1669098,58,1,7,13,'Juuri sinä päivänä menivät Nooa sekä Seem, Haam ja Jaafet, Nooan pojat, ja Nooan vaimo ja hänen kolme miniäänsä heidän kanssaan arkkiin;'),
(1669099,58,1,7,14,'he ja kaikki metsäeläimet lajiensa mukaan ja kaikki karjaeläimet lajiensa mukaan ja kaikki matelijat, jotka maan päällä matelevat, lajiensa mukaan ja kaikki linnut lajiensa mukaan, kaikki lintuset, kaikki, mikä siivekästä on.'),
(1669100,58,1,7,15,'Ja ne menivät Nooan luo arkkiin kaksittain, kaikki liha, kaikki, jossa oli elämän henki.'),
(1669101,58,1,7,16,'Ja ne, jotka menivät sisälle, olivat koiras ja naaras kaikesta lihasta, niinkuin Jumala oli hänelle käskyn antanut. Ja Herra sulki oven hänen jälkeensä.'),
(1669102,58,1,7,17,'Silloin tuli vedenpaisumus maan päälle, tuli neljänäkymmenenä päivänä; ja vedet paisuivat ja nostivat arkin, niin että se kohosi korkealle maasta.'),
(1669103,58,1,7,18,'Ja vedet saivat vallan ja paisuivat suuresti maan päällä, ja arkki ajelehti veden pinnalla.'),
(1669104,58,1,7,19,'Ja vedet nousivat nousemistaan maan päällä, niin että kaikki korkeat vuoret kaiken taivaan alla peittyivät.'),
(1669105,58,1,7,20,'Viisitoista kyynärää vesi nousi vuorten yli, niin että ne peittyivät.'),
(1669106,58,1,7,21,'Silloin hukkui kaikki liha, joka maan päällä liikkui: linnut, karjaeläimet, metsäeläimet ja kaikki pikkueläimet, joita maassa vilisi, sekä kaikki ihmiset.'),
(1669107,58,1,7,22,'Kaikki, joiden sieramissa oli elämän hengen henkäys, kaikki, jotka elivät kuivalla maalla, kuolivat.'),
(1669108,58,1,7,23,'Niin Herra hävitti kaikki olennot, jotka maan päällä olivat, niin hyvin ihmiset kuin myös karjaeläimet, matelijat ja taivaan linnut; ne hävisivät maan päältä. Ainoastaan Nooa sekä ne, jotka olivat hänen kanssansa arkissa, jäivät henkiin.'),
(1669109,58,1,7,24,'Ja vedet vallitsivat maan päällä sata viisikymmentä päivää.'),
(1669110,58,1,8,1,'Silloin Jumala muisti Nooaa ja kaikkia metsäeläimiä ja kaikkia karjaeläimiä, jotka olivat hänen kanssansa arkissa. Ja Jumala nosti tuulen puhaltamaan yli maan, niin että vesi laskeutui.'),
(1669111,58,1,8,2,'Ja syvyyden lähteet ja taivaan akkunat sulkeutuivat, ja sade taivaasta taukosi.'),
(1669112,58,1,8,3,'Ja vesi väistyi väistymistään maan päältä; sadan viidenkymmenen päivän kuluttua alkoi vesi vähentyä.'),
(1669113,58,1,8,4,'Niin arkki pysähtyi seitsemäntenä kuukautena, kuukauden seitsemäntenätoista päivänä, Araratin vuorille.'),
(1669114,58,1,8,5,'Ja vesi väheni vähenemistään aina kymmenenteen kuukauteen asti. Kymmenentenä kuukautena, kuukauden ensimmäisenä päivänä, tulivat vuorten huiput näkyviin.'),
(1669115,58,1,8,6,'Neljänkymmenen päivän kuluttua Nooa avasi arkin ikkunan, jonka hän oli tehnyt,'),
(1669116,58,1,8,7,'ja laski kaarneen lentoon, ja se lenteli edestakaisin, kunnes vesi maan päältä kuivui.'),
(1669117,58,1,8,8,'Sitten hän laski luotansa kyyhkysen nähdäksensä, oliko vesi vähentynyt maan pinnalta.'),
(1669118,58,1,8,9,'Mutta kyyhkynen ei löytänyt paikkaa, missä lepuuttaa jalkaansa, vaan palasi hänen luoksensa arkkiin, sillä koko maa oli vielä veden peitossa; niin hän ojensi kätensä ja otti sen luoksensa arkkiin.'),
(1669119,58,1,8,10,'Ja hän odotti vielä toiset seitsemän päivää ja laski taas kyyhkysen arkista.'),
(1669120,58,1,8,11,'Ja kyyhkynen tuli hänen luoksensa ehtoopuolella, ja katso, sen suussa oli tuore öljypuun lehti. Niin Nooa ymmärsi, että vesi oli vähentynyt maan päältä.'),
(1669121,58,1,8,12,'Mutta hän odotti vielä toiset seitsemän päivää ja laski kyyhkysen lentoon, eikä se enää palannut hänen luoksensa.'),
(1669122,58,1,8,13,'Ja Nooan kuudentenasadantena yhdentenä ikävuotena, vuoden ensimmäisenä kuukautena, kuukauden ensimmäisenä päivänä, oli vesi kuivunut maan päältä. Niin Nooa poisti katon arkista ja katseli; ja katso, maan pinta oli kuivunut.'),
(1669123,58,1,8,14,'Ja toisena kuukautena, kuukauden kahdentenakymmenentenä seitsemäntenä päivänä, oli maa aivan kuiva.'),
(1669124,58,1,8,15,'Ja Jumala puhui Nooalle sanoen:'),
(1669125,58,1,8,16,'"Lähde arkista, sinä ja vaimosi, poikasi ja miniäsi sinun kanssasi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669126,58,1,8,17,'Ja kaikki eläimet, jotka ovat luonasi, kaikki liha, linnut ja karjaeläimet ja kaikki matelijat, jotka maan päällä matelevat, vie ne ulos kanssasi. Niitä vilisköön maassa, ja ne olkoot hedelmälliset ja lisääntykööt maan päällä."'),
(1669127,58,1,8,18,'Ja Nooa ja hänen poikansa, vaimonsa ja miniänsä hänen kanssaan lähtivät ulos,'),
(1669128,58,1,8,19,'niin myös kaikki metsäeläimet, kaikki matelijat ja kaikki linnut, kaikki, mikä liikkuu maan päällä, lähtivät arkista suvuittain.'),
(1669129,58,1,8,20,'Ja Nooa rakensi alttarin Herralle ja otti kaikkia puhtaita karjaeläimiä ja kaikkia puhtaita lintuja ja uhrasi polttouhreja alttarilla.'),
(1669130,58,1,8,21,'Ja Herra tunsi suloisen tuoksun ja sanoi sydämessänsä: "En minä koskaan enää kiroa maata ihmisen tähden; sillä ihmisen sydämen aivoitukset ovat pahat nuoruudesta saakka. Enkä minä koskaan enää tuhoa kaikkea, mikä elää, niinkuin nyt olen tehnyt.'),
(1669131,58,1,8,22,'Niin kauan kuin maa pysyy, ei lakkaa kylväminen eikä leikkaaminen, ei vilu eikä helle, ei kesä eikä talvi, ei päivä eikä yö."'),
(1669132,58,1,9,1,'Ja Jumala siunasi Nooan ja hänen poikansa ja sanoi heille: "Olkaa hedelmälliset ja lisääntykää ja täyttäkää maa.'),
(1669133,58,1,9,2,'Ja peljätkööt ja vaviskoot teitä kaikki eläimet maan päällä ja kaikki taivaan linnut ja kaikki, jotka maassa matelevat, ja kaikki meren kalat; ne olkoot teidän valtaanne annetut.'),
(1669134,58,1,9,3,'Kaikki, mikä liikkuu ja elää, olkoon teille ravinnoksi; niinkuin minä olen antanut teille viheriäiset kasvit, niin minä annan teille myös tämän kaiken.'),
(1669135,58,1,9,4,'Älkää vain syökö lihaa, jossa sen sielu, sen veri, vielä on.'),
(1669136,58,1,9,5,'Mutta teidän oman verenne minä kostan; jokaiselle eläimelle minä sen kostan, ja myöskin ihmisille minä kostan ihmisen sielun, toiselle toisen sielun.'),
(1669137,58,1,9,6,'Joka ihmisen veren vuodattaa, hänen verensä on ihminen vuodattava, sillä Jumala on tehnyt ihmisen kuvaksensa.'),
(1669138,58,1,9,7,'Ja te olkaa hedelmälliset ja lisääntykää, enentykää maassa ja lisääntykää siinä."'),
(1669139,58,1,9,8,'Ja Jumala puhui Nooalle ja hänen pojillensa, jotka olivat hänen kanssansa, sanoen:'),
(1669140,58,1,9,9,'"Katso, minä teen liiton teidän ja teidän jälkeläistenne kanssa'),
(1669141,58,1,9,10,'ja kaikkien elävien olentojen kanssa, jotka luonanne ovat, lintujen, karjaeläinten ja kaikkien metsäeläinten kanssa, jotka luonanne ovat, kaikkien kanssa, jotka arkista lähtivät, kaikkien maan eläinten kanssa.'),
(1669142,58,1,9,11,'Minä teen liiton teidän kanssanne: ei koskaan enää pidä kaikkea lihaa hukutettaman vedenpaisumuksella, eikä vedenpaisumus koskaan enää maata turmele."'),
(1669143,58,1,9,12,'Ja Jumala sanoi: "Tämä on sen liiton merkki, jonka minä ikuisiksi ajoiksi teen itseni ja teidän ja kaikkien elävien olentojen välillä, jotka teidän luonanne ovat:'),
(1669144,58,1,9,13,'minä panen kaareni pilviin, ja se on oleva liiton merkkinä minun ja maan välillä.'),
(1669145,58,1,9,14,'Ja kun minä kokoan pilviä maan päälle ja kaari näkyy pilvissä,'),
(1669146,58,1,9,15,'muistan minä liittoni, joka on minun ja teidän ja kaikkien elävien olentojen, kaiken lihan välillä, eikä vesi enää paisu tulvaksi hävittämään kaikkea lihaa.'),
(1669147,58,1,9,16,'Niin kaari on oleva pilvissä, ja minä katselen sitä muistaakseni iankaikkista liittoa Jumalan ja kaikkien elävien olentojen, kaiken lihan välillä, joka maan päällä on."'),
(1669148,58,1,9,17,'Ja Jumala sanoi Nooalle: "Tämä on sen liiton merkki, jonka minä olen tehnyt itseni ja kaiken lihan välillä, joka maan päällä on".'),
(1669149,58,1,9,18,'Ja Nooan pojat, jotka lähtivät arkista, olivat Seem, Haam ja Jaafet. Ja Haam oli Kanaanin isä.'),
(1669150,58,1,9,19,'Nämä kolme ovat Nooan pojat, ja heistä kaikki maan asukkaat polveutuvat.'),
(1669151,58,1,9,20,'Ja Nooa oli peltomies ja ensimmäinen, joka istutti viinitarhan.'),
(1669152,58,1,9,21,'Mutta kun hän joi viiniä, niin hän juopui ja makasi alasti majassansa.'),
(1669153,58,1,9,22,'Ja Haam, Kanaanin isä, näki isänsä hävyn ja kertoi siitä molemmille veljillensä ulkona.'),
(1669154,58,1,9,23,'Niin Seem ja Jaafet ottivat vaipan ja panivat molemmat sen hartioilleen ja menivät selin sisään ja peittivät isänsä hävyn; ja heidän kasvonsa olivat käännetyt toisaalle, niin etteivät he nähneet isänsä häpyä.'),
(1669155,58,1,9,24,'Kun Nooa heräsi päihtymyksestänsä ja sai tietää, mitä hänen nuorin poikansa oli hänelle tehnyt,'),
(1669156,58,1,9,25,'niin hän sanoi: "Kirottu olkoon Kanaan, olkoon hän veljiensä orjain orja".'),
(1669157,58,1,9,26,'Vielä hän sanoi: "Kiitetty olkoon Herra, Seemin Jumala, ja olkoon Kanaan heidän orjansa.'),
(1669158,58,1,9,27,'Jumala laajentakoon Jaafetin, ja asukoon hän Seemin majoissa, ja Kanaan olkoon heidän orjansa."'),
(1669159,58,1,9,28,'Ja Nooa eli vedenpaisumuksen jälkeen kolmesataa viisikymmentä vuotta.'),
(1669160,58,1,9,29,'Niin Nooan koko ikä oli yhdeksänsataa viisikymmentä vuotta; sitten hän kuoli.'),
(1669161,58,1,10,1,'Tämä on kertomus Nooan poikien, Seemin, Haamin ja Jaafetin, suvusta. Heille syntyi poikia vedenpaisumuksen jälkeen.'),
(1669162,58,1,10,2,'Jaafetin pojat olivat Goomer, Maagog, Maadai, Jaavan, Tuubal, Mesek ja Tiiras.'),
(1669163,58,1,10,3,'Ja Goomerin pojat olivat Askenas, Riifat ja Toogarma.'),
(1669164,58,1,10,4,'Ja Jaavanin pojat olivat Elisa, Tarsis, kittiläiset ja doodanilaiset;'),
(1669165,58,1,10,5,'heistä haarautuivat pakanoiden saarten asukkaat maittensa, eri kieltensä, heimojensa ja kansakuntiensa mukaan.'),
(1669166,58,1,10,6,'Ja Haamin pojat olivat Kuus, Misraim, Puut ja Kanaan.'),
(1669167,58,1,10,7,'Ja Kuusin pojat olivat Seba, Havila, Sabta, Raema ja Sabteka. Ja Raeman pojat olivat Saba ja Dedan.'),
(1669168,58,1,10,8,'Ja Kuusille syntyi Nimrod. Hän oli ensimmäinen valtias maan päällä.'),
(1669169,58,1,10,9,'Hän oli mahtava metsämies Herran edessä. Siitä on sananparsi: "Mahtava metsämies Herran edessä niinkuin Nimrod".'),
(1669170,58,1,10,10,'Ja hänen valtakuntansa alkuna olivat Baabel, Erek, Akkad ja Kalne Sinearin maassa.'),
(1669171,58,1,10,11,'Siitä maasta hän lähti Assuriin ja rakensi Niiniven, Rehobot-Iirin ja Kelahin,'),
(1669172,58,1,10,12,'sekä Resenin Niiniven ja Kelahin välille; se on tuo suuri kaupunki.'),
(1669173,58,1,10,13,'Ja Misraimille syntyivät luudilaiset, anamilaiset, lehabilaiset, naftuhilaiset,'),
(1669174,58,1,10,14,'patrokselaiset, kasluhilaiset, joista filistealaiset ovat lähteneet, sekä kaftorilaiset.'),
(1669175,58,1,10,15,'Ja Kanaanille syntyivät Siidon, hänen esikoisensa, ja Heet,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669176,58,1,10,16,'sekä jebusilaiset, amorilaiset, girgasilaiset,'),
(1669177,58,1,10,17,'hivviläiset, arkilaiset, siiniläiset,'),
(1669178,58,1,10,18,'arvadilaiset, semarilaiset ja hamatilaiset. Sittemmin hajaantuivat kanaanilaisten heimot.'),
(1669179,58,1,10,19,'Ja kanaanilaisten alue ulottui Siidonista Gerariin päin aina Gassaan asti sekä Sodomaan, Gomorraan, Admaan ja Seboimiin päin aina Lesaan asti.'),
(1669180,58,1,10,20,'Nämä olivat Haamin pojat heimojensa, kieltensä, maittensa ja kansakuntiensa mukaan.'),
(1669181,58,1,10,21,'Myöskin Seemille, Jaafetin vanhimmalle veljelle, josta tuli kaikkien Eeberin poikien kantaisä, syntyi poikia.'),
(1669182,58,1,10,22,'Seemin pojat olivat Eelam, Assur, Arpaksad, Luud ja Aram.'),
(1669183,58,1,10,23,'Ja Aramin pojat olivat Uus, Huul, Geter ja Mas.'),
(1669184,58,1,10,24,'Arpaksadille syntyi Selah, ja Selahille syntyi Eeber.'),
(1669185,58,1,10,25,'Ja Eeberille syntyi kaksi poikaa: toisen nimi oli Peleg, sillä hänen aikanansa jakaantuivat maan asukkaat, ja hänen veljensä nimi oli Joktan.'),
(1669186,58,1,10,26,'Ja Joktanille syntyi Almodad, Selef, Hasarmavet, Jerah,'),
(1669187,58,1,10,27,'Hadoram, Uusal, Dikla,'),
(1669188,58,1,10,28,'Oobal, Abimael, Saba,'),
(1669189,58,1,10,29,'Oofir, Havila ja Joobab. Kaikki nämä olivat Joktanin poikia.'),
(1669190,58,1,10,30,'Ja heidän asumasijansa ulottuivat Meesasta aina Sefariin, Itävuorelle asti.'),
(1669191,58,1,10,31,'Nämä olivat Seemin pojat heimojensa, kieltensä, maittensa ja kansakuntiensa mukaan.'),
(1669192,58,1,10,32,'Nämä olivat Nooan poikien heimot sukukuntiensa ja kansakuntiensa mukaan; ja niistä haarautuivat kansat maan päälle vedenpaisumuksen jälkeen.'),
(1669193,58,1,11,1,'Ja kaikessa maassa oli yksi kieli ja yksi puheenparsi.'),
(1669194,58,1,11,2,'Kun he lähtivät liikkeelle itään päin, löysivät he lakeuden Sinearin maassa ja asettuivat sinne.'),
(1669195,58,1,11,3,'Ja he sanoivat toisillensa: "Tulkaa, tehkäämme tiiliä ja polttakaamme ne koviksi". Ja tiiltä he käyttivät kivenä, ja maapihkaa he käyttivät laastina.'),
(1669196,58,1,11,4,'Ja he sanoivat: "Tulkaa, rakentakaamme itsellemme kaupunki ja torni, jonka huippu ulottuu taivaaseen, ja tehkäämme itsellemme nimi, ettemme hajaantuisi yli kaiken maan".'),
(1669197,58,1,11,5,'Niin Herra astui alas katsomaan kaupunkia ja tornia, jonka ihmislapset olivat rakentaneet.'),
(1669198,58,1,11,6,'Ja Herra sanoi: "Katso, he ovat yksi kansa, ja heillä kaikilla on yksi kieli, ja tämä on heidän ensimmäinen yrityksensä. Ja nyt ei heille ole mahdotonta mikään, mitä aikovatkin tehdä.'),
(1669199,58,1,11,7,'Tulkaa, astukaamme alas ja sekoittakaamme siellä heidän kielensä, niin ettei toinen ymmärrä toisen kieltä."'),
(1669200,58,1,11,8,'Ja niin Herra hajotti heidät sieltä yli kaiken maan, niin että he lakkasivat kaupunkia rakentamasta.'),
(1669201,58,1,11,9,'Siitä tuli sen nimeksi Baabel, koska Herra siellä sekoitti kaiken maan kielen; ja sieltä Herra hajotti heidät yli kaiken maan.'),
(1669202,58,1,11,10,'Tämä on kertomus Seemin suvusta. Kun Seem oli sadan vuoden vanha, syntyi hänelle Arpaksad kaksi vuotta vedenpaisumuksen jälkeen.'),
(1669203,58,1,11,11,'Ja Seem eli Arpaksadin syntymän jälkeen viisisataa vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669204,58,1,11,12,'Kun Arpaksad oli kolmenkymmenen viiden vuoden vanha, syntyi hänelle Selah.'),
(1669205,58,1,11,13,'Ja Arpaksad eli Selahin syntymän jälkeen neljäsataa kolme vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669206,58,1,11,14,'Kun Selah oli kolmenkymmenen vuoden vanha, syntyi hänelle Eeber.'),
(1669207,58,1,11,15,'Ja Selah eli Eeberin syntymän jälkeen neljäsataa kolme vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669208,58,1,11,16,'Kun Eeber oli kolmenkymmenen neljän vuoden vanha, syntyi hänelle Peleg.'),
(1669209,58,1,11,17,'Ja Eeber eli Pelegin syntymän jälkeen neljäsataa kolmekymmentä vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669210,58,1,11,18,'Kun Peleg oli kolmenkymmenen vuoden vanha, syntyi hänelle Regu.'),
(1669211,58,1,11,19,'Ja Peleg eli Regun syntymän jälkeen kaksisataa yhdeksän vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669212,58,1,11,20,'Kun Regu oli kolmenkymmenen kahden vuoden vanha, syntyi hänelle Serug.'),
(1669213,58,1,11,21,'Ja Regu eli Serugin syntymän jälkeen kaksisataa seitsemän vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669214,58,1,11,22,'Kun Serug oli kolmenkymmenen vuoden vanha, syntyi hänelle Naahor.'),
(1669215,58,1,11,23,'Ja Serug eli Naahorin syntymän jälkeen kaksisataa vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669216,58,1,11,24,'Kun Naahor oli kahdenkymmenen yhdeksän vuoden vanha, syntyi hänelle Terah.'),
(1669217,58,1,11,25,'Ja Naahor eli Terahin syntymän jälkeen sata yhdeksäntoista vuotta, ja hänelle syntyi poikia ja tyttäriä.'),
(1669218,58,1,11,26,'Kun Terah oli seitsemänkymmenen vuoden vanha, syntyivät hänelle Abram, Naahor ja Haaran.'),
(1669219,58,1,11,27,'Ja tämä on kertomus Terahin suvusta. Terahille syntyivät Abram, Naahor ja Haaran. Ja Haaranille syntyi Loot.'),
(1669220,58,1,11,28,'Ja Haaran kuoli ennen isäänsä Terahia synnyinmaassansa, Kaldean Uurissa.'),
(1669221,58,1,11,29,'Ja Abram ja Naahor ottivat itsellensä vaimot; Abramin vaimon nimi oli Saarai, ja Naahorin vaimon nimi oli Milka, Haaranin tytär; Haaran oli Milkan ja Jiskan isä.'),
(1669222,58,1,11,30,'Mutta Saarai oli hedelmätön, hänellä ei ollut lasta.'),
(1669223,58,1,11,31,'Ja Terah otti poikansa Abramin ja poikansa pojan Lootin, Haaranin pojan, ja miniänsä Saarain, poikansa Abramin vaimon, ja he lähtivät heidän kanssaan Kaldean Uurista mennäksensä Kanaanin maahan, ja he saapuivat Harraniin asti ja asuivat siellä.'),
(1669224,58,1,11,32,'Ja Terahin ikä oli kaksisataa viisi vuotta; sitten Terah kuoli Harranissa.'),
(1669225,58,1,12,1,'Ja Herra sanoi Abramille: "Lähde maastasi, suvustasi ja isäsi kodista siihen maahan, jonka minä sinulle osoitan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669226,58,1,12,2,'Niin minä teen sinusta suuren kansan, siunaan sinut ja teen sinun nimesi suureksi, ja sinä olet tuleva siunaukseksi.'),
(1669227,58,1,12,3,'Ja minä siunaan niitä, jotka sinua siunaavat, ja kiroan ne, jotka sinua kiroavat, ja sinussa tulevat siunatuiksi kaikki sukukunnat maan päällä."'),
(1669228,58,1,12,4,'Niin Abram lähti, niinkuin Herra oli hänelle puhunut, ja Loot meni hänen kanssansa. Abram oli Harranista lähtiessänsä seitsemänkymmenen viiden vuoden vanha.'),
(1669229,58,1,12,5,'Ja Abram otti vaimonsa Saarain ja veljensä pojan Lootin sekä kaiken omaisuuden, jonka he olivat koonneet, ja ne palvelijat, jotka he olivat hankkineet Harranissa, ja he lähtivät menemään Kanaanin maahan. Ja he tulivat Kanaanin maahan.'),
(1669230,58,1,12,6,'Ja Abram kulki maan läpi aina Sikemin paikkakunnalle, Mooren tammelle asti. Ja siihen aikaan kanaanilaiset asuivat siinä maassa.'),
(1669231,58,1,12,7,'Silloin Herra ilmestyi Abramille ja sanoi: "Sinun jälkeläisillesi minä annan tämän maan". Niin hän rakensi sinne alttarin Herralle, joka oli hänelle ilmestynyt.'),
(1669232,58,1,12,8,'Sieltä hän siirtyi edemmäksi vuoristoon, itään päin Beetelistä, ja pystytti telttansa, niin että Beetel oli lännessä ja Ai idässä, ja hän rakensi sinne alttarin Herralle ja huusi avuksi Herran nimeä.'),
(1669233,58,1,12,9,'Ja sieltä Abram lähti ja vaelsi yhä edemmäksi Etelämaahan päin.'),
(1669234,58,1,12,10,'Niin tuli nälänhätä maahan, ja Abram meni Egyptiin, asuakseen siellä jonkun aikaa, sillä nälänhätä maassa oli kova.'),
(1669235,58,1,12,11,'Ja kun hän lähestyi Egyptiä, puhui hän vaimollensa Saaraille: "Katso, minä tiedän, että sinä olet kaunis nainen.'),
(1669236,58,1,12,12,'Kun egyptiläiset saavat nähdä sinut, niin he sanovat: ''Hän on hänen vaimonsa'', ja tappavat minut, mutta antavat sinun elää.'),
(1669237,58,1,12,13,'Sano siis olevasi minun sisareni, että minun kävisi hyvin sinun tähtesi ja minä sinun takiasi saisin jäädä henkiin."'),
(1669238,58,1,12,14,'Kun Abram tuli Egyptiin, näkivät egyptiläiset, että Saarai oli hyvin kaunis nainen.'),
(1669239,58,1,12,15,'Ja kun faraon ruhtinaat olivat nähneet hänet, ylistelivät he häntä faraolle; ja vaimo vietiin faraon hoviin.'),
(1669240,58,1,12,16,'Ja Abramia hän kohteli hyvin hänen tähtensä. Ja hän sai pikkukarjaa, raavaskarjaa ja aaseja, palvelijoita ja palvelijattaria, aasintammoja ja kameleja.'),
(1669241,58,1,12,17,'Mutta Herra antoi kovien vitsausten kohdata faraota ja hänen hoviansa Saarain, Abramin vaimon, tähden.'),
(1669242,58,1,12,18,'Silloin farao kutsui Abramin luoksensa ja sanoi: "Mitä olet minulle tehnyt? Miksi et ilmoittanut minulle, että hän on sinun vaimosi?'),
(1669243,58,1,12,19,'Miksi sanoit: ''Hän on minun sisareni'', niin että minä otin hänet vaimokseni? Katso, tässä on vaimosi, ota hänet ja mene."'),
(1669244,58,1,12,20,'Ja farao antoi hänestä käskyn miehillensä, että he saattaisivat hänet pois, hänet ja hänen vaimonsa sekä kaiken, mitä hänellä oli.'),
(1669245,58,1,13,1,'Niin Abram lähti pois Egyptistä, hän ja hänen vaimonsa ja kaikki, mitä hänellä oli, ja Loot hänen kanssaan, Etelämaahan.'),
(1669246,58,1,13,2,'Abram oli hyvin rikas: hänellä oli karjaa, hopeata ja kultaa.'),
(1669247,58,1,13,3,'Ja hän vaelsi, kulkien levähdyspaikasta toiseen, Etelämaasta Beeteliin asti, aina siihen paikkaan, missä hänen majansa oli ensi kerralla ollut, Beetelin ja Ain välillä,'),
(1669248,58,1,13,4,'siihen paikkaan, johon hän ennen oli rakentanut alttarin; ja Abram huusi siinä avuksi Herran nimeä.'),
(1669249,58,1,13,5,'Ja myöskin Lootilla, joka vaelsi Abramin kanssa, oli pikkukarjaa, raavaskarjaa ja telttoja.'),
(1669250,58,1,13,6,'Eikä maa riittänyt heidän asuakseen yhdessä, sillä heillä oli paljon omaisuutta, niin etteivät voineet yhdessä asua.'),
(1669251,58,1,13,7,'Niin syntyi riitaa Abramin karjapaimenten ja Lootin karjapaimenten välillä. Ja siihen aikaan asuivat siinä maassa kanaanilaiset ja perissiläiset.'),
(1669252,58,1,13,8,'Silloin Abram sanoi Lootille: "Älköön olko riitaa meidän välillämme, minun ja sinun, älköönkä minun paimenteni ja sinun paimentesi välillä, sillä olemmehan veljeksiä.'),
(1669253,58,1,13,9,'Eikö koko maa ole avoinna edessäsi? Eroa minusta. Jos sinä menet vasemmalle, niin minä menen oikealle, tahi jos sinä menet oikealle, niin minä menen vasemmalle."'),
(1669254,58,1,13,10,'Ja Loot nosti silmänsä ja näki koko Jordanin lakeuden olevan runsasvetistä seutua; ennenkuin Herra hävitti Sodoman ja Gomorran, oli se Sooariin saakka niinkuin Herran puutarha, niinkuin Egyptin maa.'),
(1669255,58,1,13,11,'Niin Loot valitsi itselleen koko Jordanin lakeuden ja siirtyi itään päin, ja he erkanivat toisistaan.'),
(1669256,58,1,13,12,'Abram asettui Kanaanin maahan, Loot asettui lakeuden kaupunkeihin ja siirtyi siirtymistään telttoineen Sodomaan asti.'),
(1669257,58,1,13,13,'Mutta Sodoman kansa oli kovin pahaa ja syntistä Herran edessä.'),
(1669258,58,1,13,14,'Ja Herra sanoi Abramille, sen jälkeen kuin Loot oli hänestä eronnut: "Nosta silmäsi ja katso siitä paikasta, missä olet, pohjoiseen, etelään, itään ja länteen.'),
(1669259,58,1,13,15,'Sillä kaiken maan, jonka näet, minä annan sinulle ja sinun jälkeläisillesi ikuisiksi ajoiksi.'),
(1669260,58,1,13,16,'Ja minä teen sinun jälkeläistesi luvun paljoksi kuin maan tomun. Jos voidaan lukea maan tomu, niin voidaan lukea myöskin sinun jälkeläisesi.'),
(1669261,58,1,13,17,'Nouse ja vaella maata pitkin ja poikin, sillä sinulle minä sen annan."'),
(1669262,58,1,13,18,'Ja Abram siirtyi siirtymistään telttoineen ja tuli ja asettui Mamren tammistoon, joka on Hebronin luona, ja rakensi sinne alttarin Herralle.'),
(1669263,58,1,14,1,'Ja tapahtui siihen aikaan, kun Amrafel oli Sinearin kuninkaana, Arjok Ellasarin kuninkaana, Kedorlaomer Eelamin kuninkaana ja Tidal Goojimin kuninkaana,'),
(1669264,58,1,14,2,'että he alottivat sodan Beraa, Sodoman kuningasta, Birsaa, Gomorran kuningasta, Sinabia, Adman kuningasta, Semeberiä, Seboimin kuningasta, ja Belan, se on Sooarin, kuningasta vastaan.'),
(1669265,58,1,14,3,'Nämä kaikki liittoutuivat kokoontuen Siddimin laaksoon, jossa Suolameri nyt on.'),
(1669266,58,1,14,4,'Kaksitoista vuotta he olivat olleet Kedorlaomerille alamaiset, mutta kolmantenatoista vuotena he tekivät kapinan.'),
(1669267,58,1,14,5,'Neljäntenätoista vuotena tulivat Kedorlaomer ja ne kuninkaat, jotka olivat hänen kanssaan; ja he voittivat refalaiset Astarot-Karnaimissa ja suusilaiset Haamissa, niin myös eemiläiset Kirjataimin tasangolla'),
(1669268,58,1,14,6,'ja hoorilaiset heidän vuoristossaan, Seirissä, aina Eel-Paaraniin asti, joka on erämaan laidassa.'),
(1669269,58,1,14,7,'Ja he palasivat ja tulivat Mispatin lähteelle, se on Kaadekseen, ja valloittivat koko amalekilaisten maan ja voittivat myöskin amorilaiset, jotka asuivat Hasason-Taamarissa.'),
(1669270,58,1,14,8,'Silloin lähtivät Sodoman kuningas, Gomorran kuningas, Adman kuningas, Seboimin kuningas ja Belan, se on Sooarin, kuningas ja asettuivat Siddimin laaksossa sotarintaan heitä vastaan -'),
(1669271,58,1,14,9,'Eelamin kuningasta Kedorlaomeria, Goojimin kuningasta Tidalia, Sinearin kuningasta Amrafelia ja Ellasarin kuningasta Arjokia vastaan, neljä kuningasta viittä vastaan.'),
(1669272,58,1,14,10,'Mutta Siddimin laakso oli täynnä maapihkakuoppia. Ja Sodoman ja Gomorran kuninkaat pakenivat ja putosivat niihin; mutta henkiin jääneet pakenivat vuoristoon.'),
(1669273,58,1,14,11,'Ja he ottivat Sodomasta ja Gomorrasta kaiken tavaran ja kaikki ruokavarat ja menivät matkaansa.'),
(1669274,58,1,14,12,'Ja lähtiessään he ottivat mukaansa myöskin Lootin, Abramin veljenpojan, ja hänen omaisuutensa; hän näet asui Sodomassa.'),
(1669275,58,1,14,13,'Mutta muuan pakolainen tuli ja ilmoitti siitä Abramille, hebrealaiselle; tämä asui tammistossa, joka oli amorilaisen Mamren, Eskolin ja Aanerin veljen, oma, ja he olivat Abramin liittolaisia.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669276,58,1,14,14,'Kun Abram kuuli, että hänen sukulaisensa oli otettu vangiksi, aseisti hän luotettavimmat palvelijansa, jotka olivat hänen kodissaan syntyneet, kolmesataa kahdeksantoista miestä, ja ajoi vihollisia takaa aina Daaniin saakka.'),
(1669277,58,1,14,15,'Ja hän jakoi väkensä ja hyökkäsi palvelijoineen yöllä vihollisten kimppuun ja voitti heidät ja ajoi heitä takaa aina Hoobaan saakka, joka on Damaskosta pohjoiseen.'),
(1669278,58,1,14,16,'Ja hän toi takaisin kaiken tavaran; myöskin sukulaisensa Lootin ja hänen tavaransa hän toi takaisin, niin myös vaimot ja muun väen.'),
(1669279,58,1,14,17,'Kun hän oli paluumatkalla, voitettuaan Kedorlaomerin ja ne kuninkaat, jotka olivat tämän kanssa, meni Sodoman kuningas häntä vastaan Saaven laaksoon, jota sanotaan "Kuninkaan laaksoksi".'),
(1669280,58,1,14,18,'Ja Melkisedek, Saalemin kuningas, toi leipää ja viiniä; hän oli Jumalan, Korkeimman, pappi.'),
(1669281,58,1,14,19,'Ja hän siunasi hänet sanoen: "Siunatkoon Abramia Jumala, Korkein, taivaan ja maan luoja.'),
(1669282,58,1,14,20,'Ja kiitetty olkoon Jumala, Korkein, joka antoi vihollisesi sinun käsiisi." Ja Abram antoi hänelle kymmenykset kaikesta.'),
(1669283,58,1,14,21,'Ja Sodoman kuningas sanoi Abramille: "Anna minulle väki ja pidä sinä tavara".'),
(1669284,58,1,14,22,'Mutta Abram sanoi Sodoman kuninkaalle: "Minä nostan käteni Herran, Jumalan, Korkeimman, taivaan ja maan luojan, puoleen ja vannon:'),
(1669285,58,1,14,23,'En totisesti ota, en langan päätä, en kengän paulaa enkä mitään muuta, mikä on sinun, ettet sanoisi: ''Minä olen tehnyt Abramin rikkaaksi''.'),
(1669286,58,1,14,24,'En tahdo mitään, paitsi mitä palvelijat ovat kuluttaneet ja mikä on niille miehille tuleva, jotka minua seurasivat, Aanerille, Eskolille ja Mamrelle; he saakoot osansa."'),
(1669287,58,1,15,1,'Näiden tapausten jälkeen tuli Abramille näyssä tämä Herran sana: "Älä pelkää, Abram! Minä olen sinun kilpesi; sinun palkkasi on oleva sangen suuri."'),
(1669288,58,1,15,2,'Mutta Abram sanoi: "Oi Herra, Herra, mitä sinä minulle annat? Minä lähden täältä lapsetonna, ja omaisuuteni haltijaksi tulee damaskolainen mies, Elieser."'),
(1669289,58,1,15,3,'Ja Abram sanoi vielä: "Sinä et ole antanut minulle jälkeläistä; katso, talossani syntynyt palvelija on minut perivä".'),
(1669290,58,1,15,4,'Mutta katso, hänelle tuli tämä Herran sana: "Hän ei ole sinua perivä, vaan joka lähtee sinun omasta ruumiistasi, hän on sinut perivä".'),
(1669291,58,1,15,5,'Ja hän vei hänet ulos ja sanoi: "Katso taivaalle ja lue tähdet, jos ne taidat lukea". Ja hän sanoi hänelle: "Niin paljon on sinulla oleva jälkeläisiä".'),
(1669292,58,1,15,6,'Ja Abram uskoi Herraan, ja Herra luki sen hänelle vanhurskaudeksi.'),
(1669293,58,1,15,7,'Ja hän sanoi hänelle: "Minä olen Herra, joka toin sinut Kaldean Uurista, antaakseni sinulle tämän maan omaksesi".'),
(1669294,58,1,15,8,'Mutta hän sanoi: "Oi Herra, Herra, mistä minä tiedän, että saan sen omakseni?"'),
(1669295,58,1,15,9,'Ja hän sanoi hänelle: "Tuo minulle kolmivuotias hieho, kolmivuotias vuohi ja kolmivuotias oinas sekä metsäkyyhkynen ja nuori kyyhkynen".'),
(1669296,58,1,15,10,'Ja hän toi nämä kaikki ja halkaisi ne ja asetti puolikkaat vastakkain; lintuja hän ei kuitenkaan halkaissut.'),
(1669297,58,1,15,11,'Niin laskeutui petolintuja ruumiiden päälle, mutta Abram karkoitti ne pois.'),
(1669298,58,1,15,12,'Kun aurinko oli laskemaisillaan, valtasi raskas uni Abramin, ja katso, kauhu ja suuri pimeys valtasi hänet.'),
(1669299,58,1,15,13,'Ja Herra sanoi Abramille: "Niin tiedä totisesti, että sinun jälkeläisesi tulevat elämään muukalaisina maassa, joka ei ole heidän omansa, ja heidän on niitä palveleminen, ja ne sortavat heitä neljäsataa vuotta.'),
(1669300,58,1,15,14,'Mutta myös sen kansan, jota he palvelevat, minä tuomitsen; ja sitten he pääsevät lähtemään, mukanaan paljon tavaraa.'),
(1669301,58,1,15,15,'Mutta sinä saat mennä isiesi tykö rauhassa, ja sinut haudataan päästyäsi korkeaan ikään.'),
(1669302,58,1,15,16,'Ja neljännessä polvessa sinun jälkeläisesi palaavat tänne takaisin; sillä amorilaisten syntivelka ei ole vielä täysi."'),
(1669303,58,1,15,17,'Ja kun aurinko oli laskenut ja oli tullut pilkkopimeä, näkyi suitsuava pätsi ja liekehtivä tuli, joka liikkui uhrikappaleiden välissä.'),
(1669304,58,1,15,18,'Sinä päivänä Herra teki Abramin kanssa liiton, sanoen: "Sinun jälkeläisillesi minä annan tämän maan, Egyptin virrasta aina suureen virtaan, Eufrat-virtaan saakka:'),
(1669305,58,1,15,19,'keeniläiset, kenissiläiset, kadmonilaiset,'),
(1669306,58,1,15,20,'heettiläiset, perissiläiset, refalaiset,'),
(1669307,58,1,15,21,'amorilaiset, kanaanilaiset, girgasilaiset ja jebusilaiset".'),
(1669308,58,1,16,1,'Saarai, Abramin vaimo, ei synnyttänyt hänelle lasta. Mutta Saarailla oli egyptiläinen orjatar, jonka nimi oli Haagar.'),
(1669309,58,1,16,2,'Ja Saarai sanoi Abramille: "Katso, Herra on sulkenut minut synnyttämästä; yhdy siis minun orjattareeni, ehkä minä saisin lapsia hänestä". Ja Abram kuuli Saaraita.'),
(1669310,58,1,16,3,'Ja Saarai, Abramin vaimo, otti egyptiläisen orjattarensa Haagarin, sitten kuin Abram oli asunut kymmenen vuotta Kanaanin maassa, ja antoi hänet miehellensä Abramille vaimoksi.'),
(1669311,58,1,16,4,'Ja hän yhtyi Haagariin, ja Haagar tuli raskaaksi. Kun hän huomasi olevansa raskaana, tuli hänen emäntänsä halvaksi hänen silmissään.'),
(1669312,58,1,16,5,'Silloin Saarai sanoi Abramille: "Minun kärsimäni vääryys kohdatkoon sinua; minä annoin orjattareni sinun syliisi, mutta kun hän huomasi olevansa raskaana, tulin minä halvaksi hänen silmissään. Herra tuomitkoon meidän välillämme, minun ja sinun."'),
(1669313,58,1,16,6,'Abram sanoi Saaraille: "Katso, orjattaresi on sinun vallassasi, tee hänelle, mitä tahdot". Niin Saarai kuritti häntä, ja hän pakeni hänen luotaan.'),
(1669314,58,1,16,7,'Ja Herran enkeli tapasi hänet vesilähteeltä erämaassa, sen lähteen luota, joka on Suurin tien varressa.'),
(1669315,58,1,16,8,'Ja hän sanoi: "Haagar, Saarain orjatar, mistä tulet ja mihin menet?" Hän vastasi: "Olen paossa emäntääni Saaraita".'),
(1669316,58,1,16,9,'Ja Herran enkeli sanoi hänelle: "Palaa emäntäsi tykö ja nöyrry hänen kätensä alle".'),
(1669317,58,1,16,10,'Ja Herran enkeli sanoi hänelle: "Minä teen sinun jälkeläistesi luvun niin suureksi, ettei heitä voida lukea heidän paljoutensa tähden".'),
(1669318,58,1,16,11,'Vielä Herran enkeli puhui hänelle: "Katso, sinä olet raskaana ja synnytät pojan ja kutsut hänet Ismaeliksi, sillä Herra on kuullut sinun hätäsi.'),
(1669319,58,1,16,12,'Hänestä tulee mies kuin villiaasi: hänen kätensä on kaikkia vastaan, ja kaikkien käsi on häntä vastaan, ja hän on kaikkien veljiensä niskassa."'),
(1669320,58,1,16,13,'Ja Haagar nimitti Herraa, joka oli häntä puhutellut, nimellä: "Sinä olet ilmestyksen Jumala". Sillä hän sanoi: "Olenko minä tässä vilaukselta saanut nähdä hänet, joka minut näkee?"'),
(1669321,58,1,16,14,'Sentähden kutsutaan kaivoa nimellä Lahai-Roin kaivo; se on Kaadeksen ja Beredin välillä.'),
(1669322,58,1,16,15,'Ja Haagar synnytti Abramille pojan, ja Abram antoi pojallensa, jonka Haagar oli hänelle synnyttänyt, nimen Ismael.'),
(1669323,58,1,16,16,'Ja Abram oli kahdeksankymmenen kuuden vuoden vanha, kun Haagar synnytti hänelle Ismaelin.'),
(1669324,58,1,17,1,'Kun Abram oli yhdeksänkymmenen yhdeksän vuoden vanha, ilmestyi Herra hänelle ja sanoi hänelle: "Minä olen Jumala, Kaikkivaltias; vaella minun edessäni ja ole nuhteeton.'),
(1669325,58,1,17,2,'Ja minä teen liittoni meidän välillemme, minun ja sinun, ja lisään sinut ylen runsaasti."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669326,58,1,17,3,'Ja Abram lankesi kasvoilleen, ja Jumala puhui hänelle sanoen:'),
(1669327,58,1,17,4,'"Katso, tämä on minun liittoni sinun kanssasi: sinusta tulee kansojen paljouden isä.'),
(1669328,58,1,17,5,'Niin älköön sinua enää kutsuttako Abramiksi, vaan nimesi olkoon Aabraham, sillä minä teen sinusta kansojen paljouden isän.'),
(1669329,58,1,17,6,'Minä teen sinut sangen hedelmälliseksi ja annan sinusta tulla kansoja, ja sinusta on polveutuva kuninkaita.'),
(1669330,58,1,17,7,'Ja minä teen liiton sinun kanssasi ja sinun jälkeläistesi kanssa, sukupolvesta sukupolveen, iankaikkisen liiton, ollakseni sinun ja sinun jälkeläistesi Jumala,'),
(1669331,58,1,17,8,'ja minä annan sinulle ja sinun jälkeläisillesi sen maan, jossa sinä muukalaisena asut, koko Kanaanin maan, ikuiseksi omaisuudeksi; ja minä olen heidän Jumalansa."'),
(1669332,58,1,17,9,'Ja Jumala sanoi Aabrahamille: "Mutta sinä pidä minun liittoni, sinä ja sinun jälkeläisesi, sukupolvesta sukupolveen.'),
(1669333,58,1,17,10,'Ja tämä on minun liittoni sinun ja sinun jälkeläistesi kanssa; pitäkää se: ympärileikatkaa jokainen miehenpuoli keskuudessanne.'),
(1669334,58,1,17,11,'Ympärileikatkaa esinahkanne liha, ja se olkoon liiton merkki meidän välillämme, minun ja teidän.'),
(1669335,58,1,17,12,'Sukupolvesta sukupolveen ympärileikattakoon jokainen poikalapsi teidän keskuudessanne kahdeksan päivän vanhana, niin hyvin kotona syntynyt palvelija kuin muukalaiselta, keneltä tahansa, rahalla ostettu, joka ei ole sinun jälkeläisiäsi.'),
(1669336,58,1,17,13,'Ympärileikattakoon sekä kotonasi syntynyt että rahalla ostamasi; ja niin minun liittoni on oleva merkitty teidän lihaanne iankaikkiseksi liitoksi.'),
(1669337,58,1,17,14,'Mutta ympärileikkaamaton miehenpuoli, jonka esinahan liha ei ole ympärileikattu, hävitettäköön kansastansa; hän on rikkonut minun liittoni."'),
(1669338,58,1,17,15,'Ja Jumala sanoi Aabrahamille: "Älä kutsu vaimoasi Saaraita enää Saaraiksi, vaan Saara olkoon hänen nimensä.'),
(1669339,58,1,17,16,'Ja minä siunaan häntä ja annan hänestäkin sinulle pojan; niin, minä siunaan häntä, ja hänestä tulee kansakuntia, polveutuu kansojen kuninkaita."'),
(1669340,58,1,17,17,'Aabraham lankesi kasvoillensa ja naurahti, sillä hän ajatteli sydämessään: "Voiko satavuotiaalle syntyä poika, ja voiko Saara, joka on yhdeksänkymmenen vuoden vanha, vielä synnyttää?"'),
(1669341,58,1,17,18,'Ja Aabraham sanoi Jumalalle: "Kunpa edes Ismael saisi elää sinun edessäsi!"'),
(1669342,58,1,17,19,'Niin Jumala sanoi: "Totisesti, sinun vaimosi Saara synnyttää sinulle pojan, ja sinun on pantava hänen nimekseen Iisak, ja minä teen liittoni hänen kanssaan iankaikkiseksi liitoksi hänen jälkeläisillensä.'),
(1669343,58,1,17,20,'Mutta myös Ismaelista minä olen kuullut sinun rukouksesi; katso, minä siunaan häntä ja teen hänet hedelmälliseksi ja annan hänen lisääntyä ylen runsaasti. Hänestä on polveutuva kaksitoista ruhtinasta, ja minä teen hänestä suuren kansan.'),
(1669344,58,1,17,21,'Mutta liittoni minä teen Iisakin kanssa, jonka Saara sinulle synnyttää tähän aikaan tulevana vuonna."'),
(1669345,58,1,17,22,'Kun Jumala oli lakannut puhumasta Aabrahamin kanssa, kohosi hän ylös hänen luotansa.'),
(1669346,58,1,17,23,'Ja Aabraham otti poikansa Ismaelin sekä kaikki kotona syntyneet ja kaikki rahalla ostamansa palvelijat, kaikki Aabrahamin perheen miehenpuolet, ja ympärileikkasi sinä samana päivänä heidän esinahkansa lihan, niinkuin Jumala oli hänelle sanonut.'),
(1669347,58,1,17,24,'Aabraham oli yhdeksänkymmenen yhdeksän vuoden vanha, kun hänen esinahkansa liha ympärileikattiin.'),
(1669348,58,1,17,25,'Ja hänen poikansa Ismael oli kolmentoista vuoden vanha, kun hänen esinahkansa liha ympärileikattiin.'),
(1669349,58,1,17,26,'Aabraham ja hänen poikansa Ismael ympärileikattiin sinä samana päivänä;'),
(1669350,58,1,17,27,'ja kaikki hänen perheensä miehet, sekä kotona syntyneet että muukalaisilta rahalla ostetut, ympärileikattiin hänen kanssaan.'),
(1669351,58,1,18,1,'Ja Herra ilmestyi hänelle Mamren tammistossa, jossa hän istui telttamajansa ovella päivän ollessa palavimmillaan.'),
(1669352,58,1,18,2,'Kun hän nosti silmänsä ja katseli, niin katso, kolme miestä seisoi hänen edessänsä; nähdessään heidät hän riensi heitä vastaan majan ovelta ja kumartui maahan'),
(1669353,58,1,18,3,'ja sanoi: "Herrani, jos olen saanut armon sinun silmiesi edessä, älä mene palvelijasi ohitse.'),
(1669354,58,1,18,4,'Sallikaa tuoda vähän vettä pestäksenne jalkanne ja levätkää puun siimeksessä.'),
(1669355,58,1,18,5,'Minä tuon palasen leipää virkistääksenne itseänne, ennenkuin jatkatte matkaanne, sillä kaiketi sitä varten olette poikenneet palvelijanne luo." He sanoivat: "Tee, niinkuin olet puhunut".'),
(1669356,58,1,18,6,'Ja Aabraham kiiruhti majaan Saaran tykö ja sanoi: "Hae joutuin kolme vakallista lestyjä jauhoja, sotke ja leivo kaltiaisia".'),
(1669357,58,1,18,7,'Sitten Aabraham riensi karjaan, otti nuoren ja kauniin vasikan ja antoi palvelijalle, joka ryhtyi nopeasti sitä valmistamaan.'),
(1669358,58,1,18,8,'Ja hän otti voita ja maitoa sekä vasikan, jonka hän oli valmistuttanut, ja pani ne heidän eteensä; itse hän seisoi heidän luonansa puun alla sillä aikaa, kuin he söivät.'),
(1669359,58,1,18,9,'Ja he kysyivät häneltä: "Missä vaimosi Saara on?" Hän vastasi: "Tuolla majassa".'),
(1669360,58,1,18,10,'Ja hän sanoi: "Minä palaan luoksesi tulevana vuonna tähän aikaan, ja katso, vaimollasi Saaralla on silloin oleva poika". Mutta Saara kuunteli majan ovella hänen takanansa.'),
(1669361,58,1,18,11,'Mutta Aabraham ja Saara olivat iäkkäät, eikä Saaran enää ollut, niinkuin naisten tavallisesti on.'),
(1669362,58,1,18,12,'Sentähden Saara naurahti itseksensä ja ajatteli: "Heräisikö minussa, näin kuihduttuani, vielä halu? Ja myös minun herrani on vanha."'),
(1669363,58,1,18,13,'Mutta Herra sanoi Aabrahamille: "Miksi Saara nauroi ajatellen: ''Synnyttäisinkö minä todella, minä, joka olen näin vanha?'''),
(1669364,58,1,18,14,'Onko mikään Herralle mahdotonta? Tähän aikaan minä palaan luoksesi tulevana vuonna, ja Saaralla on silloin poika."'),
(1669365,58,1,18,15,'Ja Saara kielsi sanoen: "En minä nauranut"; sillä hän pelkäsi. Mutta hän sanoi: "Ei ole niin; sinä nauroit".'),
(1669366,58,1,18,16,'Silloin miehet nousivat siitä ja kääntyivät Sodomaan päin, ja Aabraham kulki heidän kanssaan saattaaksensa heitä.'),
(1669367,58,1,18,17,'Ja Herra sanoi: "Salaisinko minä Aabrahamilta, mitä olen tekevä?'),
(1669368,58,1,18,18,'Onhan Aabrahamista tuleva suuri ja väkevä kansa, ja kaikki kansakunnat maan päällä tulevat hänessä siunatuiksi.'),
(1669369,58,1,18,19,'Sillä minä olen valinnut hänet, että hän käskisi lapsiansa ja perhettänsä, joka jää hänen jälkeensä, noudattamaan Herran tietä ja tekemään sitä, mikä vanhurskaus ja oikeus on, jotta Herra antaisi Aabrahamille tapahtua, mitä hän on hänelle luvannut."'),
(1669370,58,1,18,20,'Niin Herra sanoi: "Valitushuuto Sodoman ja Gomorran tähden on suuri, ja heidän syntinsä ovat ylen raskaat.'),
(1669371,58,1,18,21,'Sentähden minä menen alas katsomaan, ovatko he todella tehneet kaiken sen, josta huuto on minun eteeni tullut, vai eivätkö; minä tahdon sen tietää."'),
(1669372,58,1,18,22,'Ja miehet kääntyivät sieltä ja kulkivat Sodomaan päin, mutta Aabraham jäi vielä seisomaan Herran eteen.'),
(1669373,58,1,18,23,'Ja Aabraham lähestyi häntä ja sanoi: "Aiotko siis hukuttaa vanhurskaan yhdessä jumalattoman kanssa?'),
(1669374,58,1,18,24,'Entä jos kaupungissa on viisikymmentä vanhurskasta; aiotko hukuttaa heidät etkä säästä paikkaa siellä olevain viidenkymmenen vanhurskaan tähden?'),
(1669375,58,1,18,25,'Pois se, että sinä näin tekisit: surmaisit vanhurskaan yhdessä jumalattoman kanssa, niin että vanhurskaan kävisi samoin kuin jumalattoman! Pois se sinusta! Eikö kaiken maan tuomari tekisi oikeutta?"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669376,58,1,18,26,'Ja Herra sanoi: "Jos löydän Sodoman kaupungista viisikymmentä vanhurskasta, niin minä heidän tähtensä säästän koko paikan".'),
(1669377,58,1,18,27,'Aabraham vastasi ja sanoi: "Katso, olen rohjennut puhua Herralleni, vaikka olen tomu ja tuhka.'),
(1669378,58,1,18,28,'Entä jos viidestäkymmenestä vanhurskaasta puuttuu viisi; hävitätkö viiden tähden koko kaupungin?" Hän sanoi: "En hävitä, jos löydän sieltä neljäkymmentä viisi".'),
(1669379,58,1,18,29,'Ja hän puhui vielä hänelle sanoen: "Entä jos siellä on neljäkymmentä?" Hän vastasi: "Niiden neljänkymmenen tähden jätän sen tekemättä".'),
(1669380,58,1,18,30,'Aabraham sanoi: "Älköön Herrani vihastuko, että vielä puhun. Entä jos siellä on kolmekymmentä?" Hän vastasi: "En tee sitä, jos löydän sieltä kolmekymmentä".'),
(1669381,58,1,18,31,'Mutta hän sanoi: "Katso, minä olen rohjennut puhua Herralleni. Entä jos siellä on kaksikymmentä?" Hän vastasi: "Niiden kahdenkymmenen tähden jätän hävittämättä".'),
(1669382,58,1,18,32,'Ja hän sanoi: "Älköön Herrani vihastuko, että puhun vielä tämän ainoan kerran. Entä jos siellä on kymmenen?" Hän vastasi: "Niiden kymmenen tähden jätän hävittämättä".'),
(1669383,58,1,18,33,'Ja Herra lähti pois, senjälkeen kuin hän oli lakannut puhumasta Aabrahamin kanssa, ja Aabraham palasi kotiinsa.'),
(1669384,58,1,19,1,'Ja ne kaksi enkeliä tulivat Sodomaan illalla, ja Loot istui Sodoman portissa; ja nähtyänsä heidät Loot nousi heitä vastaan ja kumartui maahan kasvoillensa.'),
(1669385,58,1,19,2,'Ja hän sanoi: "Oi herrani, poiketkaa palvelijanne taloon yöksi ja peskää jalkanne! Aamulla varhain voitte jatkaa matkaanne." He sanoivat: "Emme, vaan me jäämme yöksi taivasalle".'),
(1669386,58,1,19,3,'Mutta hän pyysi heitä pyytämällä, ja he poikkesivat hänen luoksensa ja tulivat hänen taloonsa. Ja hän valmisti heille aterian ja leipoi happamattomia leipiä, ja he söivät.'),
(1669387,58,1,19,4,'Ennenkuin he olivat laskeutuneet levolle, piirittivät kaupungin miehet, sodomalaiset, sekä nuoret että vanhat, koko kansa kaikkialta, talon.'),
(1669388,58,1,19,5,'Ja he huusivat Lootia sanoen hänelle: "Missä ne miehet ovat, jotka tulivat luoksesi yöllä? Tuo heidät tänne meidän luoksemme, ryhtyäksemme heihin."'),
(1669389,58,1,19,6,'Silloin Loot meni ulos heidän luokseen portille ja sulki oven jälkeensä'),
(1669390,58,1,19,7,'ja sanoi: "Älkää, veljeni, tehkö niin pahoin.'),
(1669391,58,1,19,8,'Katsokaa, minulla on kaksi tytärtä, jotka eivät vielä miehestä tiedä. Ne minä tuon teille, tehkää heille, mitä tahdotte. Älkää vain tehkö näille miehille mitään pahaa, sillä he ovat tulleet minun kattoni suojaan."'),
(1669392,58,1,19,9,'Mutta he vastasivat: "Mene tiehesi!" Ja he sanoivat: "Tuo yksi on tullut tänne asumaan muukalaisena, ja yhtäkaikki hän alati pyrkii hallitsemaan. Nytpä me pitelemmekin sinua pahemmin kuin heitä." Ja he tunkeutuivat väkivaltaisesti miehen, Lootin, kimppuun ja kävivät murtamaan ovea.'),
(1669393,58,1,19,10,'Silloin miehet ojensivat kätensä, vetivät Lootin luoksensa huoneeseen ja sulkivat oven.'),
(1669394,58,1,19,11,'Ja he sokaisivat ne miehet, jotka olivat talon ovella, sekä nuoret että vanhat, niin että he turhaan koettivat löytää ovea.'),
(1669395,58,1,19,12,'Ja miehet sanoivat Lootille: "Vieläkö sinulla on ketään omaista täällä? Vie pois täältä vävysi, poikasi, tyttäresi ja kaikki, keitä sinulla kaupungissa on,'),
(1669396,58,1,19,13,'sillä me hävitämme tämän paikan. Koska huuto heistä on käynyt suureksi Herran edessä, lähetti Herra meidät hävittämään sen."'),
(1669397,58,1,19,14,'Silloin Loot meni puhuttelemaan vävyjänsä, joiden oli aikomus ottaa hänen tyttärensä, ja sanoi: "Nouskaa, lähtekää pois tästä paikasta, sillä Herra hävittää tämän kaupungin". Mutta hänen vävynsä luulivat hänen laskevan leikkiä.'),
(1669398,58,1,19,15,'Aamun sarastaessa enkelit kiirehtivät Lootia sanoen: "Nouse, ota vaimosi ja molemmat tyttäresi, jotka ovat luonasi, ettet hukkuisi kaupungin syntivelan tähden".'),
(1669399,58,1,19,16,'Ja kun hän vielä vitkasteli, tarttuivat miehet hänen käteensä sekä hänen vaimonsa ja molempien tyttäriensä käteen, sillä Herra tahtoi säästää hänet, ja veivät hänet ulos ja jättivät hänet ulkopuolelle kaupunkia.'),
(1669400,58,1,19,17,'Ja viedessään heitä ulos sanoi mies: "Pakene henkesi tähden, älä katso taaksesi äläkä pysähdy mihinkään lakeudella. Pakene vuorille, ettet hukkuisi."'),
(1669401,58,1,19,18,'Mutta Loot sanoi heille: "Oi herrani, ei niin!'),
(1669402,58,1,19,19,'Katso, palvelijasi on saanut armon sinun silmiesi edessä, ja suuri on sinun laupeutesi, jota olet minulle osoittanut pelastaaksesi henkeni, mutta minä en voi päästä pakoon vuorille; pelkään, että onnettomuus saavuttaa minut ja minä kuolen.'),
(1669403,58,1,19,20,'Katso, tuolla on kaupunki lähellä, vähän matkan päässä, paetakseni sinne; salli minun pelastua sinne - onhan se vähän matkan päässä - jäädäkseni eloon."'),
(1669404,58,1,19,21,'Ja hän sanoi hänelle: "Katso, minä teen sinulle mieliksi tässäkin kohden; en hävitä kaupunkia, josta puhut.'),
(1669405,58,1,19,22,'Pakene nopeasti sinne, sillä minä en voi tehdä mitään, ennenkuin olet sinne saapunut." Siitä kaupunki sai nimekseen Sooar.'),
(1669406,58,1,19,23,'Aurinko oli noussut, kun Loot saapui Sooariin.'),
(1669407,58,1,19,24,'Ja Herra antoi sataa Sodoman ja Gomorran päälle tulikiveä ja tulta, Herran tyköä taivaasta,'),
(1669408,58,1,19,25,'ja hävitti nämä kaupungit ynnä koko lakeuden sekä kaikki niiden kaupunkien asukkaat ja maan kasvullisuuden.'),
(1669409,58,1,19,26,'Ja Lootin vaimo, joka tuli hänen jäljessään, katsoi taaksensa, ja niin hän muuttui suolapatsaaksi.'),
(1669410,58,1,19,27,'Aabraham nousi varhain aamulla ja meni siihen paikkaan, jossa hän oli seisonut Herran edessä,'),
(1669411,58,1,19,28,'katseli Sodomaan ja Gomorraan päin ja yli koko lakeuden, ja katso, maasta nousi savu niinkuin pätsin savu.'),
(1669412,58,1,19,29,'Kun Jumala tuhosi sen lakeuden kaupungit, muisti Jumala Aabrahamia ja johdatti Lootin pois hävityksen keskeltä, hävittäessään ne kaupungit, joissa Loot oli asunut.'),
(1669413,58,1,19,30,'Ja Loot lähti Sooarista ja asettui vuoristoon molempien tyttäriensä kanssa, sillä hän pelkäsi asua Sooarissa; ja hän asui luolassa, hän ja hänen molemmat tyttärensä.'),
(1669414,58,1,19,31,'Niin vanhempi sanoi nuoremmalle: "Isämme on vanha, eikä tässä maassa ole ketään miestä, joka voisi tulla luoksemme siten, kuin on kaiken maan tapa.'),
(1669415,58,1,19,32,'Tule, juottakaamme isällemme viiniä ja maatkaamme hänen kanssaan, saadaksemme isästämme jälkeläisen."'),
(1669416,58,1,19,33,'Niin he juottivat sinä yönä isällensä viiniä. Ja vanhempi meni ja makasi hänen kanssaan, eikä tämä huomannut, milloin hän tuli hänen viereensä ja milloin hän nousi.'),
(1669417,58,1,19,34,'Seuraavana päivänä sanoi vanhempi nuoremmalle: "Katso, minä makasin viime yönä isäni kanssa; juottakaamme hänelle tänäkin yönä viiniä, ja mene sinä ja makaa hänen kanssaan, saadaksemme isästämme jälkeläisen".'),
(1669418,58,1,19,35,'Niin he juottivat sinäkin yönä isällensä viiniä; ja nuorempi meni ja makasi hänen kanssaan, eikä tämä huomannut, milloin hän tuli hänen viereensä ja milloin hän nousi.'),
(1669419,58,1,19,36,'Ja niin Lootin molemmat tyttäret tulivat isästänsä raskaiksi.'),
(1669420,58,1,19,37,'Ja vanhempi synnytti pojan ja antoi hänelle nimen Mooab; hänestä polveutuvat mooabilaiset aina tähän päivään saakka.'),
(1669421,58,1,19,38,'Ja myöskin nuorempi synnytti pojan ja antoi hänelle nimen Ben-Ammi; hänestä polveutuvat ammonilaiset aina tähän päivään saakka.'),
(1669422,58,1,20,1,'Ja Aabraham siirtyi sieltä Etelämaahan ja asettui Kaadeksen ja Suurin välimaille; ja hän asui jonkun aikaa Gerarissa.'),
(1669423,58,1,20,2,'Ja Aabraham sanoi vaimostansa Saarasta: "Hän on minun sisareni". Niin Abimelek, Gerarin kuningas, lähetti noutamaan Saaran luoksensa.'),
(1669424,58,1,20,3,'Mutta Jumala tuli Abimelekin tykö yöllä unessa ja sanoi hänelle: "Katso, sinun on kuoltava sen vaimon tähden, jonka olet ottanut, sillä hän on toisen miehen aviovaimo".'),
(1669425,58,1,20,4,'Mutta Abimelek ei ollut ryhtynyt häneen, ja hän sanoi: "Herra, surmaatko syyttömänkin?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669426,58,1,20,5,'Eikö hän itse sanonut minulle: ''Hän on minun sisareni''? Ja samoin tämäkin sanoi: ''Hän on minun veljeni''. Olen tehnyt tämän vilpittömin sydämin ja viattomin käsin."'),
(1669427,58,1,20,6,'Ja Jumala sanoi hänelle unessa: "Niin, minä tiedän, että sinä teit sen vilpittömin sydämin. Sentähden minä estinkin sinut tekemästä syntiä minua vastaan enkä sallinut sinun kajota häneen.'),
(1669428,58,1,20,7,'Niin anna nyt miehelle hänen vaimonsa takaisin, sillä hän on profeetta, ja hän on rukoileva sinun puolestasi, että saisit elää. Mutta jollet anna häntä takaisin, niin tiedä, että olet kuolemalla kuoleva, sinä ja kaikki sinun omaisesi."'),
(1669429,58,1,20,8,'Niin Abimelek nousi varhain aamulla ja kutsui kaikki palvelijansa ja kertoi heille tämän kaiken; ja miehet olivat kovin peloissaan.'),
(1669430,58,1,20,9,'Ja Abimelek kutsui Aabrahamin ja sanoi hänelle: "Mitä oletkaan meille tehnyt! Mitä minä olen rikkonut sinua vastaan, koska olet saattanut minut ja minun valtakuntani syypääksi näin suureen rikokseen? Sinä olet tehnyt minulle, mitä ei sovi tehdä."'),
(1669431,58,1,20,10,'Ja Abimelek sanoi vielä Aabrahamille: "Mikä oli tarkoituksesi, kun tämän teit?"'),
(1669432,58,1,20,11,'Aabraham vastasi: "Minä ajattelin näin: ''Tällä paikkakunnalla ei varmaankaan peljätä Jumalaa; he surmaavat minut vaimoni tähden''.'),
(1669433,58,1,20,12,'Ja hän onkin todella minun sisareni, isäni tytär, vaikkei olekaan äitini tytär; ja niin hänestä tuli minun vaimoni.'),
(1669434,58,1,20,13,'Mutta kun Jumala lähetti minut kulkemaan pois isäni kodista, sanoin minä hänelle: ''Osoita minulle se rakkaus, että, mihin paikkaan ikinä tulemmekin, sanot minusta: hän on minun veljeni''."'),
(1669435,58,1,20,14,'Silloin Abimelek otti pikkukarjaa ja raavaskarjaa, palvelijoita ja palvelijattaria ja antoi ne Aabrahamille. Ja hän lähetti hänelle takaisin hänen vaimonsa Saaran.'),
(1669436,58,1,20,15,'Ja Abimelek sanoi: "Katso, minun maani on avoinna edessäsi; asu, missä mielesi tekee!"'),
(1669437,58,1,20,16,'Ja Saaralle hän sanoi: "Katso, minä annan veljellesi tuhat sekeliä hopeata. Olkoot ne sinulle hyvitykseksi kaikkien niiden edessä, jotka sinun kanssasi ovat; niin olet kaikkien edessä todistettu viattomaksi."'),
(1669438,58,1,20,17,'Mutta Aabraham rukoili Jumalaa, ja Jumala paransi Abimelekin ja hänen vaimonsa ja hänen orjattarensa, niin että he synnyttivät lapsia.'),
(1669439,58,1,20,18,'Sillä Herra oli sulkenut jokaisen kohdun Abimelekin huoneessa Saaran, Aabrahamin vaimon, tähden.'),
(1669440,58,1,21,1,'Ja Herra piti Saarasta huolen, niinkuin oli luvannut; ja Herra teki Saaralle, niinkuin oli puhunut.'),
(1669441,58,1,21,2,'Ja Saara tuli raskaaksi ja synnytti Aabrahamille pojan hänen vanhoilla päivillään, juuri sinä aikana, jonka Jumala oli hänelle sanonut.'),
(1669442,58,1,21,3,'Ja Aabraham nimitti poikansa, joka hänelle oli syntynyt, sen, jonka Saara oli hänelle synnyttänyt, Iisakiksi.'),
(1669443,58,1,21,4,'Ja Aabraham ympärileikkasi poikansa Iisakin, tämän ollessa kahdeksan päivän vanha, niinkuin Jumala oli hänen käskenyt tehdä.'),
(1669444,58,1,21,5,'Aabraham oli sadan vuoden vanha, kun hänen poikansa Iisak syntyi hänelle.'),
(1669445,58,1,21,6,'Ja Saara sanoi: "Jumala on saattanut minut naurunalaiseksi; kuka ikinä saa tämän kuulla, se nauraa minulle".'),
(1669446,58,1,21,7,'Ja hän sanoi vielä: "Kuka olisi tiennyt sanoa Aabrahamille: Saara on imettävä lapsia? Ja nyt minä kuitenkin olen synnyttänyt hänelle pojan hänen vanhoilla päivillään."'),
(1669447,58,1,21,8,'Ja poika kasvoi, ja hänet vieroitettiin. Ja Aabraham laittoi suuret pidot siksi päiväksi, jona Iisak vieroitettiin.'),
(1669448,58,1,21,9,'Ja Saara näki egyptiläisen Haagarin pojan, jonka tämä oli Aabrahamille synnyttänyt, ilvehtivän'),
(1669449,58,1,21,10,'ja sanoi Aabrahamille: "Aja pois tuo orjatar poikinensa, sillä ei tuon orjattaren poika saa periä minun poikani, Iisakin, kanssa".'),
(1669450,58,1,21,11,'Aabraham pahastui suuresti tästä puheesta poikansa tähden.'),
(1669451,58,1,21,12,'Mutta Jumala sanoi Aabrahamille: "Älä pahastu siitä poikasi ja orjattaresi tähden. Kuule Saaraa kaikessa, mitä hän sinulle sanoo, sillä ainoastaan Iisakista sinä saat nimellesi jälkeläiset.'),
(1669452,58,1,21,13,'Mutta myöskin orjattaren pojasta minä teen suuren kansan, koska hän on sinun jälkeläisesi."'),
(1669453,58,1,21,14,'Varhain seuraavana aamuna Aabraham otti leipää ja vesileilin ja antoi ne Haagarille, pannen ne hänen olalleen, sekä pojan, ja lähetti hänet menemään. Hän lähti ja harhaili Beerseban erämaassa.'),
(1669454,58,1,21,15,'Mutta kun vesi loppui leilistä, heitti hän pojan pensaan alle,'),
(1669455,58,1,21,16,'meni ja istui syrjään jousenkantaman päähän, sillä hän ajatteli: "En voi nähdä pojan kuolevan". Ja istuessaan siinä syrjässä hän korotti äänensä ja itki.'),
(1669456,58,1,21,17,'Silloin Jumala kuuli pojan valituksen, ja Jumalan enkeli huusi taivaasta Haagarille sanoen: "Mikä sinun on, Haagar? Älä pelkää, sillä Jumala on kuullut pojan valituksen, siinä missä hän makaa.'),
(1669457,58,1,21,18,'Nouse, nosta poika maasta ja tartu hänen käteensä, sillä minä teen hänestä suuren kansan."'),
(1669458,58,1,21,19,'Ja Jumala avasi hänen silmänsä, niin että hän huomasi vesikaivon. Ja hän meni ja täytti leilin vedellä ja antoi pojan juoda.'),
(1669459,58,1,21,20,'Ja Jumala oli pojan kanssa, ja hän kasvoi ja asui erämaassa, ja hänestä tuli jousimies.'),
(1669460,58,1,21,21,'Ja hän asui Paaranin erämaassa; ja hänen äitinsä otti hänelle vaimon Egyptin maasta.'),
(1669461,58,1,21,22,'Siihen aikaan puhui Abimelek ja hänen sotapäällikkönsä Piikol Aabrahamille sanoen: "Jumala on sinun kanssasi kaikessa, mitä teet.'),
(1669462,58,1,21,23,'Vanno nyt tässä minulle Jumalan kautta, ettet ole oleva petollinen minulle etkä minun suvulleni etkä jälkeläisilleni, vaan tee sinäkin laupeus minulle ja sille maalle, jossa muukalaisena asut, niinkuin minä olen sinulle tehnyt."'),
(1669463,58,1,21,24,'Aabraham sanoi: "Minä vannon".'),
(1669464,58,1,21,25,'Aabraham nuhteli kuitenkin Abimelekia vesikaivon tähden, jonka Abimelekin palvelijat olivat vallanneet.'),
(1669465,58,1,21,26,'Mutta Abimelek vastasi: "En tiedä, kuka sen on tehnyt; et ole itse minulle mitään ilmoittanut, enkä ole siitä kuullut ennen kuin tänään".'),
(1669466,58,1,21,27,'Silloin Aabraham otti pikkukarjaa ja raavaskarjaa ja antoi Abimelekille; ja he tekivät molemmat keskenänsä liiton.'),
(1669467,58,1,21,28,'Ja Aabraham asetti laumasta seitsemän uuhikaritsaa erilleen muista.'),
(1669468,58,1,21,29,'Silloin Abimelek sanoi Aabrahamille: "Mitä tarkoittavat nuo seitsemän karitsaa, jotka olet asettanut tuonne erilleen?"'),
(1669469,58,1,21,30,'Hän vastasi: "Nämä seitsemän karitsaa on sinun otettava minun kädestäni, todistukseksi minulle siitä, että tämä kaivo on minun kaivamani".'),
(1669470,58,1,21,31,'Siitä kutsuttiin paikkaa Beersebaksi, koska he molemmat vannoivat siinä toisilleen valan.'),
(1669471,58,1,21,32,'Niin he tekivät liiton Beersebassa. Ja Abimelek nousi ja Piikol, hänen sotapäällikkönsä, ja he palasivat filistealaisten maahan.'),
(1669472,58,1,21,33,'Ja Aabraham istutti tamariskipuun Beersebaan ja huusi siinä avuksi Herran, iankaikkisen Jumalan, nimeä.'),
(1669473,58,1,21,34,'Ja Aabraham asui kauan muukalaisena filistealaisten maassa.'),
(1669474,58,1,22,1,'Näiden tapausten jälkeen Jumala koetteli Aabrahamia ja sanoi hänelle: "Aabraham!" Hän vastasi: "Tässä olen".'),
(1669475,58,1,22,2,'Ja hän sanoi: "Ota Iisak, ainokainen poikasi, jota rakastat, ja mene Moorian maahan ja uhraa hänet siellä polttouhriksi vuorella, jonka minä sinulle sanon".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669476,58,1,22,3,'Varhain seuraavana aamuna Aabraham satuloi aasinsa ja otti mukaansa kaksi palvelijaansa sekä poikansa Iisakin, ja halottuaan polttouhripuita hän lähti menemään siihen paikkaan, jonka Jumala oli hänelle sanonut.'),
(1669477,58,1,22,4,'Kolmantena päivänä Aabraham nosti silmänsä ja näki sen paikan kaukaa.'),
(1669478,58,1,22,5,'Silloin Aabraham sanoi palvelijoilleen: "Jääkää tähän aasin kanssa. Minä ja poika menemme tuonne rukoilemaan; sitten me palaamme luoksenne."'),
(1669479,58,1,22,6,'Ja Aabraham otti polttouhripuut ja sälytti ne poikansa Iisakin selkään; itse hän otti käteensä tulen ja veitsen, ja niin he astuivat molemmat yhdessä.'),
(1669480,58,1,22,7,'Iisak puhui isällensä Aabrahamille sanoen: "Isäni!" Tämä vastasi: "Tässä olen, poikani". Ja hän sanoi: "Katso, tässä on tuli ja halot, mutta missä on lammas polttouhriksi?"'),
(1669481,58,1,22,8,'Aabraham vastasi: "Jumala on katsova itselleen lampaan polttouhriksi, poikani". Ja he astuivat molemmat yhdessä.'),
(1669482,58,1,22,9,'Ja kun he olivat tulleet siihen paikkaan, jonka Jumala oli hänelle sanonut, rakensi Aabraham siihen alttarin, latoi sille halot, sitoi poikansa Iisakin ja pani hänet alttarille halkojen päälle.'),
(1669483,58,1,22,10,'Ja Aabraham ojensi kätensä ja tarttui veitseen teurastaakseen poikansa.'),
(1669484,58,1,22,11,'Silloin Herran enkeli huusi hänelle taivaasta sanoen: "Aabraham, Aabraham!" Hän vastasi: "Tässä olen".'),
(1669485,58,1,22,12,'Niin hän sanoi: "Älä satuta kättäsi poikaan äläkä tee hänelle mitään, sillä nyt minä tiedän, että sinä pelkäät Jumalaa, kun et kieltänyt minulta ainokaista poikaasi".'),
(1669486,58,1,22,13,'Niin Aabraham nosti silmänsä ja huomasi takanansa oinaan, joka oli sarvistaan takertunut pensaikkoon. Ja Aabraham meni, otti oinaan ja uhrasi sen polttouhriksi poikansa sijasta.'),
(1669487,58,1,22,14,'Ja Aabraham pani sen paikan nimeksi "Herra näkee". Niinpä vielä tänä päivänä sanotaan: "Vuorella, missä Herra ilmestyy".'),
(1669488,58,1,22,15,'Ja Herran enkeli huusi Aabrahamille toistamiseen taivaasta'),
(1669489,58,1,22,16,'ja sanoi: "Minä vannon itse kauttani, sanoo Herra: Sentähden että tämän teit etkä kieltänyt minulta ainokaista poikaasi,'),
(1669490,58,1,22,17,'minä runsaasti siunaan sinua ja teen sinun jälkeläistesi luvun paljoksi kuin taivaan tähdet ja hiekka, joka on meren rannalla, ja sinun jälkeläisesi valtaavat vihollistensa portit.'),
(1669491,58,1,22,18,'Ja sinun siemenessäsi tulevat siunatuiksi kaikki kansakunnat maan päällä, sentähden että olit minun äänelleni kuuliainen."'),
(1669492,58,1,22,19,'Sitten Aabraham palasi palvelijainsa luo, ja he nousivat ja kulkivat yhdessä Beersebaan. Ja Aabraham jäi asumaan Beersebaan.'),
(1669493,58,1,22,20,'Näiden tapausten jälkeen ilmoitettiin Aabrahamille: "Katso, myöskin Milka on synnyttänyt poikia sinun veljellesi Naahorille".'),
(1669494,58,1,22,21,'Nämä olivat Uus, hänen esikoisensa, tämän veli Buus, Kemuel, Aramin isä,'),
(1669495,58,1,22,22,'Kesed, Haso, Pildas, Jidlaf ja Betuel;'),
(1669496,58,1,22,23,'ja Betuelille syntyi Rebekka. Nämä kahdeksan synnytti Milka Naahorille, Aabrahamin veljelle.'),
(1669497,58,1,22,24,'Ja hänen sivuvaimonsa, nimeltä Reuma, synnytti myös lapsia: Tebahin, Gahamin, Tahaan ja Maakan.'),
(1669498,58,1,23,1,'Ja Saara eli sadan kahdenkymmenen seitsemän vuoden vanhaksi; niin vanhaksi eli Saara.'),
(1669499,58,1,23,2,'Ja Saara kuoli Kirjat-Arbassa, se on Hebronissa, Kanaanin maassa. Ja Aabraham meni murehtimaan Saaraa ja itkemään häntä.'),
(1669500,58,1,23,3,'Senjälkeen Aabraham nousi ja lähti vainajan luota ja puhui heettiläisille sanoen:'),
(1669501,58,1,23,4,'"Minä olen muukalainen ja vieras teidän keskuudessanne; antakaa minulle perintöhauta maassanne, haudatakseni ja kätkeäkseni siihen vainajani".'),
(1669502,58,1,23,5,'Heettiläiset vastasivat Aabrahamille, sanoen hänelle:'),
(1669503,58,1,23,6,'"Kuule meitä, herra. Sinä olet Jumalan ruhtinas meidän keskuudessamme; hautaa vainajasi parhaaseen hautaamme. Ei kukaan meistä kiellä sinua hautaamasta vainajaasi hautaansa."'),
(1669504,58,1,23,7,'Niin Aabraham nousi ja kumarsi maan kansalle, heettiläisille,'),
(1669505,58,1,23,8,'ja puhui heille sanoen: "Jos teidän mieleenne on, että minä hautaan ja kätken vainajani, niin kuulkaa minua ja taivuttakaa Efron, Sooharin poika,'),
(1669506,58,1,23,9,'antamaan minulle Makpelan luola, joka on hänen omansa ja on hänen vainionsa perällä. Täydestä hinnasta hän antakoon sen minulle perintöhaudaksi teidän keskuudessanne."'),
(1669507,58,1,23,10,'Mutta Efron istui siellä heettiläisten joukossa. Ja Efron, heettiläinen, vastasi Aabrahamille heettiläisten kuullen, kaikkien, jotka kulkivat hänen kaupunkinsa portista, sanoen:'),
(1669508,58,1,23,11,'"Ei, herrani, vaan kuule minua. Vainion minä lahjoitan sinulle ja myöskin luolan, joka siinä on, minä lahjoitan sinulle; kansalaisteni nähden minä sen sinulle lahjoitan. Hautaa vainajasi."'),
(1669509,58,1,23,12,'Ja Aabraham kumarsi maan kansalle'),
(1669510,58,1,23,13,'ja puhui Efronille, maan kansan kuullen, sanoen: "Jospa kuitenkin - oi, kuule minua! Minä maksan vainion hinnan; ota se minulta ja anna minun haudata siihen vainajani."'),
(1669511,58,1,23,14,'Efron vastasi Aabrahamille, sanoen hänelle:'),
(1669512,58,1,23,15,'"Herrani, kuule minua. Neljänsadan hopeasekelin maa, mitä se minulle ja sinulle merkitsee? Hautaa vainajasi."'),
(1669513,58,1,23,16,'Kuultuaan Efronin sanat Aabraham punnitsi Efronille sen rahasumman, jonka tämä oli maininnut heettiläisten kuullen, neljäsataa hopeasekeliä, kaupassa käypää.'),
(1669514,58,1,23,17,'Niin Efronin vainio, joka on Makpelassa itään päin Mamresta, sekä vainio että siellä oleva luola ynnä kaikki puut, jotka kasvoivat vainiolla, koko sillä alueella,'),
(1669515,58,1,23,18,'joutuivat Aabrahamin omaksi kaikkien heettiläisten nähden, jotka kulkivat hänen kaupunkinsa portista.'),
(1669516,58,1,23,19,'Senjälkeen Aabraham hautasi vaimonsa Saaran luolaan, joka on Makpelan vainiolla, itään päin Mamresta, se on Hebronista, Kanaanin maassa.'),
(1669517,58,1,23,20,'Niin vainio ja siellä oleva luola siirtyi heettiläisiltä Aabrahamille, perintöhaudaksi.'),
(1669518,58,1,24,1,'Ja Aabraham oli vanha ja iälliseksi tullut, ja Herra oli siunannut Aabrahamia kaikessa.'),
(1669519,58,1,24,2,'Niin Aabraham sanoi palvelijallensa, talonsa vanhimmalle, joka hallitsi kaikkea, mitä hänellä oli: "Pane kätesi kupeeni alle.'),
(1669520,58,1,24,3,'Minä vannotan sinua Herran, taivaan ja maan Jumalan, kautta, ettet ota pojalleni vaimoa kanaanilaisten tyttäristä, joiden keskuudessa minä asun,'),
(1669521,58,1,24,4,'vaan menet minun omaan maahani ja sukuni luo ja otat sieltä vaimon pojalleni Iisakille."'),
(1669522,58,1,24,5,'Palvelija sanoi hänelle: "Entä jos tyttö ei tahdo seurata minua tähän maahan, onko minun silloin vietävä poikasi takaisin siihen maahan, josta olet lähtenyt?"'),
(1669523,58,1,24,6,'Aabraham vastasi hänelle: "Varo, ettet vie poikaani takaisin sinne.'),
(1669524,58,1,24,7,'Herra, taivaan Jumala, joka otti minut pois isäni kodista ja synnyinmaastani, hän, joka puhui minulle ja vannoi minulle sanoen: ''Sinun jälkeläisillesi minä annan tämän maan'', hän lähettää enkelinsä sinun edelläsi, niin että saat sieltä vaimon pojalleni.'),
(1669525,58,1,24,8,'Mutta jos tyttö ei tahdo seurata sinua, niin olet tästä valasta vapaa. Älä vain vie poikaani sinne takaisin."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669526,58,1,24,9,'Niin palvelija pani kätensä herransa Aabrahamin kupeen alle ja lupasi sen hänelle valalla vannoen.'),
(1669527,58,1,24,10,'Ja palvelija otti herransa kameleista kymmenen sekä kaikkinaisia kalleuksia herransa tavaroista; ja hän nousi ja lähti Mesopotamiaan, Naahorin kaupunkiin.'),
(1669528,58,1,24,11,'Ja hän antoi kamelien asettua kaupungin ulkopuolelle vesikaivon ääreen lepäämään, illan suussa, jolloin naiset tulivat vettä ammentamaan.'),
(1669529,58,1,24,12,'Ja hän sanoi: "Herra, minun herrani Aabrahamin Jumala, suo minulle tänään menestystä ja tee laupeus herralleni Aabrahamille.'),
(1669530,58,1,24,13,'Katso, minä seison tässä lähteellä, ja kaupunkilaisten tyttäret tulevat ammentamaan vettä.'),
(1669531,58,1,24,14,'Niin tapahtukoon, että se tyttö, jolle minä sanon: ''Kallista tänne vesiastiaasi juodakseni'', ja joka vastaa: ''Juo, minä juotan kamelisikin'', on juuri se, jonka sinä olet määrännyt palvelijallesi Iisakille; ja siitä minä tiedän, että olet tehnyt laupeuden herralleni."'),
(1669532,58,1,24,15,'Tuskin hän oli lakannut puhumasta, niin tuli siihen Rebekka, joka oli Aabrahamin veljen Naahorin ja hänen vaimonsa Milkan pojan, Betuelin, tytär; ja hänellä oli vesiastia olallaan.'),
(1669533,58,1,24,16,'Ja tyttö oli näöltään hyvin ihana, neitsyt, johon ei mies ollut koskenut. Ja hän astui alas lähteelle, täytti astiansa ja tuli ylös.'),
(1669534,58,1,24,17,'Silloin palvelija riensi häntä vastaan ja sanoi: "Anna minun juoda vähän vettä astiastasi".'),
(1669535,58,1,24,18,'Hän vastasi: "Juo, herrani". Ja hän laski nopeasti astiansa alas kädelleen ja antoi hänen juoda.'),
(1669536,58,1,24,19,'Ja annettuaan hänen juoda hän sanoi: "Minä ammennan vettä myös sinun kameleillesi, kunnes ne ovat juoneet kyllikseen".'),
(1669537,58,1,24,20,'Niin hän tyhjensi nopeasti astiansa kaukaloon ja riensi jälleen kaivolle ammentamaan vettä ja ammensi kaikille hänen kameleilleen.'),
(1669538,58,1,24,21,'Ja mies katseli häntä ääneti saadakseen tietää, oliko Herra antanut hänen matkansa onnistua vai ei.'),
(1669539,58,1,24,22,'Kun kamelit olivat juoneet, otti mies kultaisen nenärenkaan, joka painoi puolen sekeliä, ja hänen käsiinsä kaksi rannerengasta, jotka painoivat kymmenen kultasekeliä.'),
(1669540,58,1,24,23,'Ja hän kysyi: "Kenenkä tytär olet? Sano minulle. Onko isäsi talossa tilaa yötä ollaksemme?"'),
(1669541,58,1,24,24,'Hän vastasi hänelle: "Olen Betuelin, Naahorin ja Milkan pojan, tytär".'),
(1669542,58,1,24,25,'Ja hän sanoi hänelle vielä: "Meillä on runsaasti olkia ja rehua; myöskin yösijaa on meillä antaa".'),
(1669543,58,1,24,26,'Silloin mies kumartui maahan ja rukoili Herraa'),
(1669544,58,1,24,27,'ja sanoi: "Kiitetty olkoon Herra, minun herrani Aabrahamin Jumala, joka ei ole ottanut pois armoansa ja totuuttansa minun herraltani. Herra on johdattanut minut tätä tietä herrani veljen kotiin."'),
(1669545,58,1,24,28,'Mutta tyttö riensi ilmoittamaan äitinsä perheelle, mitä oli tapahtunut.'),
(1669546,58,1,24,29,'Rebekalla oli veli, jonka nimi oli Laaban; ja Laaban riensi ulos miehen luo lähteelle.'),
(1669547,58,1,24,30,'Sillä kun hän näki nenärenkaan ja rannerenkaat sisarensa käsissä ja kuuli sisarensa Rebekan kertovan ja sanovan: "Näin mies puhui minulle", meni hän miehen luo; ja katso, hän seisoi vielä kamelien luona lähteellä.'),
(1669548,58,1,24,31,'Ja hän sanoi hänelle: "Tule sisään, sinä Herran siunattu. Minkätähden seisot ulkona? Minä olen valmistanut tilaa talossa ja sijaa kameleille."'),
(1669549,58,1,24,32,'Niin mies tuli taloon, ja Laaban riisui kamelit ja antoi kameleille olkia ja rehua sekä hänelle ja hänen seuralaisilleen vettä jalkojen pesemiseksi.'),
(1669550,58,1,24,33,'Sitten pantiin ruokaa hänen eteensä, mutta hän sanoi: "En syö, ennenkuin olen puhunut asiani". Laaban vastasi: "Puhu".'),
(1669551,58,1,24,34,'Hän sanoi: "Minä olen Aabrahamin palvelija.'),
(1669552,58,1,24,35,'Herra on suuresti siunannut minun herraani, niin että hänestä on tullut mahtava mies; hän on antanut hänelle pikkukarjaa ja raavaskarjaa, hopeata ja kultaa, palvelijoita ja palvelijattaria, kameleja ja aaseja.'),
(1669553,58,1,24,36,'Ja Saara, herrani vaimo, on vanhalla iällänsä synnyttänyt herralleni pojan; ja tälle hän on antanut kaiken omaisuutensa.'),
(1669554,58,1,24,37,'Ja herrani vannotti minua sanoen: ''Älä ota pojalleni vaimoa kanaanilaisten tyttäristä, joiden maassa minä asun,'),
(1669555,58,1,24,38,'vaan mene minun isäni kotiin ja sukuni luo ja ota sieltä pojalleni vaimo''.'),
(1669556,58,1,24,39,'Silloin minä sanoin herralleni: ''Entä jos tyttö ei seuraa minua?'''),
(1669557,58,1,24,40,'Hän vastasi minulle: ''Herra, jonka edessä minä olen vaeltanut, lähettää enkelinsä sinun kanssasi ja antaa matkasi onnistua, niin että saat pojalleni vaimon minun suvustani ja isäni perheestä.'),
(1669558,58,1,24,41,'Silloin, kun saavut sukuni luo, olet vapaa valasta, jonka minulle vannoit; jos he eivät häntä sinulle anna, olet valasta vapaa''.'),
(1669559,58,1,24,42,'Niin minä tänään tulin lähteelle ja sanoin: ''Herra, minun herrani Aabrahamin Jumala, jos annat onnistua sen matkan, jolla olen,'),
(1669560,58,1,24,43,'salli tapahtua niin, että se neitonen, joka minun seisoessani tässä vesilähteellä tulee ammentamaan vettä ja sanoessani hänelle: ''Anna minun juoda vähän vettä astiastasi'','),
(1669561,58,1,24,44,'vastaa minulle: ''Juo itse, ja minä ammennan myös sinun kameleillesi'' - että hän on se vaimo, jonka Herra on määrännyt minun herrani pojalle.'),
(1669562,58,1,24,45,'Tuskin olin lakannut näin puhumasta itsekseni, niin katso, Rebekka tuli sinne, vesiastia olallansa, astui alas lähteelle ja ammensi. Ja minä sanoin hänelle: ''Anna minun juoda''.'),
(1669563,58,1,24,46,'Hän laski nopeasti astian alas olaltansa ja sanoi: ''Juo, minä juotan myös sinun kamelisi''. Niin minä join, ja hän juotti myös kamelit.'),
(1669564,58,1,24,47,'Ja minä kysyin häneltä sanoen: ''Kenenkä tytär sinä olet?'' Hän vastasi: ''Olen Betuelin, Naahorin ja Milkan pojan, tytär''. Niin minä panin nenärenkaan hänen nenäänsä ja rannerenkaat hänen käsiinsä.'),
(1669565,58,1,24,48,'Ja minä kumarruin maahan ja rukoilin Herraa, kiittäen Herraa, minun herrani Aabrahamin Jumalaa, joka oli johdattanut minut oikeata tietä saamaan herrani veljen tyttären hänen pojalleen.'),
(1669566,58,1,24,49,'Ja jos nyt tahdotte osoittaa suosiota ja uskollisuutta minun herralleni, niin ilmoittakaa se minulle; jollette, niin ilmoittakaa minulle sekin, kääntyäkseni toisaalle, oikealle tai vasemmalle."'),
(1669567,58,1,24,50,'Laaban ja Betuel vastasivat sanoen: "Herralta tämä on tullut; emme voi tässä asiassa puhua sinulle hyvää emmekä pahaa.'),
(1669568,58,1,24,51,'Katso, siinä on Rebekka edessäsi, ota hänet ja mene. Tulkoon hän herrasi pojan vaimoksi, niinkuin Herra on sanonut."'),
(1669569,58,1,24,52,'Kuultuaan heidän sanansa Aabrahamin palvelija kumartui maahan Herran eteen.'),
(1669570,58,1,24,53,'Sitten palvelija otti esille hopea- ja kultakaluja sekä vaatteita ja antoi ne Rebekalle. Myöskin hänen veljelleen ja äidilleen hän antoi kallisarvoisia lahjoja.'),
(1669571,58,1,24,54,'Ja he söivät ja joivat, hän ja hänen seuralaisensa, ja olivat siellä yötä. Mutta kun he olivat nousseet seuraavana aamuna, sanoi hän: "Päästäkää minut menemään herrani luo".'),
(1669572,58,1,24,55,'Tytön veli ja äiti vastasivat: "Anna tytön viipyä luonamme vielä joku aika, edes kymmenen päivää. Sitten saat lähteä."'),
(1669573,58,1,24,56,'Mutta hän sanoi heille: "Älkää viivyttäkö minua, koska Herra on antanut matkani onnistua. Päästäkää minut menemään, tahdon lähteä herrani luo."'),
(1669574,58,1,24,57,'He vastasivat: "Kutsukaamme tänne tyttö ja kysykäämme häneltä itseltään".'),
(1669575,58,1,24,58,'Ja he kutsuivat Rebekan ja sanoivat hänelle: "Tahdotko lähteä tämän miehen kanssa?" Hän vastasi: "Tahdon".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669576,58,1,24,59,'Niin he lähettivät sisarensa Rebekan imettäjineen matkalle Aabrahamin palvelijan ja hänen miestensä mukana.'),
(1669577,58,1,24,60,'Ja he siunasivat Rebekan ja lausuivat hänelle: "Oi sisaremme, tulkoon sinusta tuhat kertaa kymmenentuhatta, ja vallatkoot sinun jälkeläisesi vihamiestensä portit!"'),
(1669578,58,1,24,61,'Ja Rebekka nousi palvelijattarineen, ja he istuivat kamelien selkään ja seurasivat miestä. Niin palvelija otti Rebekan mukaansa ja lähti matkalle.'),
(1669579,58,1,24,62,'Ja Iisak oli tulossa Lahai-Roin kaivon tienoilta; hän asui näet Etelämaassa.'),
(1669580,58,1,24,63,'Ja Iisak oli illan suussa lähtenyt kedolle käyskentelemään, ja kun hän nosti silmänsä, näki hän kamelien lähestyvän.'),
(1669581,58,1,24,64,'Kun Rebekka nosti silmänsä ja näki Iisakin, laskeutui hän nopeasti maahan kamelin selästä'),
(1669582,58,1,24,65,'ja kysyi palvelijalta: "Kuka on tuo mies, joka tulee kedolla meitä vastaan?" Palvelija vastasi: "Hän on minun herrani". Niin hän otti hunnun ja verhoutui siihen.'),
(1669583,58,1,24,66,'Ja palvelija kertoi Iisakille kaikki, mitä hän oli toimittanut.'),
(1669584,58,1,24,67,'Ja Iisak vei Rebekan äitinsä Saaran majaan ja otti hänet luokseen, ja hänestä tuli hänen vaimonsa, ja hän rakasti häntä. Niin Iisak sai lohdutuksen äitinsä kuoltua.'),
(1669585,58,1,25,1,'Ja Aabraham otti vielä vaimon, ja hänen nimensä oli Ketura.'),
(1669586,58,1,25,2,'Ja hän synnytti hänelle Simranin ja Joksanin, Medanin ja Midianin, Jisbakin ja Suuahin.'),
(1669587,58,1,25,3,'Mutta Joksanille syntyi Seba ja Dedan. Dedanin jälkeläisiä olivat: assurilaiset, letusilaiset ja leummilaiset.'),
(1669588,58,1,25,4,'Ja Midianin pojat olivat Eefa, Eefer, Hanok, Abida ja Eldaa. Kaikki nämä ovat Keturan jälkeläisiä.'),
(1669589,58,1,25,5,'Ja Aabraham antoi kaiken omaisuutensa Iisakille.'),
(1669590,58,1,25,6,'Mutta sivuvaimojensa pojille Aabraham antoi lahjoja; ja hän lähetti heidät vielä eläessänsä pois poikansa Iisakin luota itään päin, Itäiselle maalle.'),
(1669591,58,1,25,7,'Tämä on Aabrahamin elinvuosien luku: sata seitsemänkymmentä viisi vuotta.'),
(1669592,58,1,25,8,'Ja Aabraham vaipui kuolemaan korkeassa iässä, vanhana ja elämästä kyllänsä saaneena, ja tuli otetuksi heimonsa tykö.'),
(1669593,58,1,25,9,'Ja hänen poikansa Iisak ja Ismael hautasivat hänet Makpelan luolaan, heettiläisen Efronin, Sooharin pojan, vainiolle, joka on itään päin Mamresta,'),
(1669594,58,1,25,10,'sille vainiolle, jonka Aabraham oli ostanut heettiläisiltä; siihen haudattiin Aabraham ja hänen vaimonsa Saara.'),
(1669595,58,1,25,11,'Ja Aabrahamin kuoltua Jumala siunasi hänen poikaansa Iisakia. Ja Iisak asui Lahai-Roin kaivon tienoilla.'),
(1669596,58,1,25,12,'Ja tämä on kertomus Ismaelin suvusta, Aabrahamin pojan, jonka Saaran egyptiläinen orjatar Haagar synnytti Aabrahamille.'),
(1669597,58,1,25,13,'Nämä ovat Ismaelin poikien nimet heidän nimiensä ja polveutumisensa mukaan: Nebajot, Ismaelin esikoinen, Keedar, Adbeel, Mibsam,'),
(1669598,58,1,25,14,'Misma, Duuma, Massa,'),
(1669599,58,1,25,15,'Hadad, Teema, Jetur, Naafis ja Keedma.'),
(1669600,58,1,25,16,'Nämä ovat Ismaelin pojat ja nämä heidän nimensä heidän kyliensä ja leiripaikkojensa mukaan, kaksitoista ruhtinasta heimokuntineen.'),
(1669601,58,1,25,17,'Ja tämä on Ismaelin elinvuosien luku: sata kolmekymmentä seitsemän vuotta; ja hän vaipui kuolemaan ja tuli otetuksi heimonsa tykö.'),
(1669602,58,1,25,18,'Ja he asuivat Havilasta aina Suuriin asti, joka on Egyptistä itään päin Assyriaan mentäessä. Hän kävi kaikkien veljiensä kimppuun.'),
(1669603,58,1,25,19,'Ja tämä on kertomus Iisakin, Aabrahamin pojan, suvusta. Aabrahamille syntyi Iisak.'),
(1669604,58,1,25,20,'Ja Iisak oli neljänkymmenen vuoden vanha, kun hän otti vaimokseen Rebekan, joka oli aramilaisen Betuelin tytär Mesopotamiasta ja aramilaisen Laabanin sisar.'),
(1669605,58,1,25,21,'Ja Iisak rukoili Herraa vaimonsa puolesta, sillä tämä oli hedelmätön. Ja Herra kuuli hänen rukouksensa, ja hänen vaimonsa Rebekka tuli raskaaksi.'),
(1669606,58,1,25,22,'Ja lapset sysäsivät toisiaan hänen kohdussansa. Niin hän sanoi: "Jos näin käy, minkätähden minä elän?" Ja hän meni kysymään Herralta.'),
(1669607,58,1,25,23,'Ja Herra sanoi hänelle: "Kaksi kansaa on sinun kohdussasi, kaksi heimoa erkanee sinun ruumiistasi, toinen heimo on toista voimakkaampi, vanhempi palvelee nuorempaa".'),
(1669608,58,1,25,24,'Kun hänen synnyttämisensä aika oli tullut, katso, hänen kohdussaan oli kaksoiset.'),
(1669609,58,1,25,25,'Joka ensiksi tuli hänen kohdustaan, oli ruskea ja yliyltään niinkuin karvainen vaippa; sentähden pantiin hänelle nimeksi Eesau.'),
(1669610,58,1,25,26,'Senjälkeen tuli ulos hänen veljensä, ja hän piti kädellään Eesaun kantapäästä. Ja hänelle pantiin nimeksi Jaakob. Iisak oli kuudenkymmenen vuoden vanha heidän syntyessänsä.'),
(1669611,58,1,25,27,'Ja pojat kasvoivat suuriksi, ja Eesausta tuli taitava metsästäjä, aron mies; Jaakob sitä vastoin oli hiljainen mies, joka pysyi kotosalla.'),
(1669612,58,1,25,28,'Iisak rakasti enemmän Eesauta, sillä hän söi mielellänsä metsänriistaa, mutta Rebekka rakasti enemmän Jaakobia.'),
(1669613,58,1,25,29,'Kerran, kun Jaakob oli keittänyt itselleen keiton, tuli Eesau kedolta nälästä nääntyneenä.'),
(1669614,58,1,25,30,'Ja Eesau sanoi Jaakobille: "Anna minun särpiä tuota ruskeata, tuota ruskeata keittoa, sillä minä olen nälästä nääntynyt". Sentähden hän sai nimen Edom.'),
(1669615,58,1,25,31,'Mutta Jaakob sanoi: "Myy minulle ensin esikoisuutesi".'),
(1669616,58,1,25,32,'Eesau vastasi: "Katso, minä kuolen kuitenkin, mitä minä esikoisuudellani teen?"'),
(1669617,58,1,25,33,'Jaakob sanoi: "Vanno minulle ensin". Ja hän vannoi hänelle ja myi esikoisuutensa Jaakobille.'),
(1669618,58,1,25,34,'Ja Jaakob antoi Eesaulle leipää ja hernekeittoa. Ja hän söi ja joi, nousi ja meni matkoihinsa. Niin halpana Eesau piti esikoisuutensa.'),
(1669619,58,1,26,1,'Mutta maahan tuli nälänhätä, toinen kuin se nälänhätä, joka oli ollut aikaisemmin, Aabrahamin päivinä. Silloin Iisak meni Abimelekin, filistealaisten kuninkaan, luo Gerariin.'),
(1669620,58,1,26,2,'Ja Herra ilmestyi hänelle ja sanoi: "Älä mene Egyptiin, vaan jää asumaan maahan, jonka minä sinulle sanon.'),
(1669621,58,1,26,3,'Oleskele muukalaisena tässä maassa, ja minä olen sinun kanssasi ja siunaan sinua. Sillä sinulle ja sinun jälkeläisillesi minä annan kaikki nämä maat ja pidän valan, jonka minä olen vannonut sinun isällesi Aabrahamille.'),
(1669622,58,1,26,4,'Ja minä teen sinun jälkeläistesi luvun paljoksi kuin taivaan tähdet ja annan jälkeläisillesi kaikki nämä maat, ja sinun siemenessäsi tulevat siunatuiksi kaikki kansakunnat maan päällä,'),
(1669623,58,1,26,5,'sentähden että Aabraham kuuli minua ja noudatti, mitä minä noudatettavaksi annoin, minun käskyjäni, säädöksiäni ja opetuksiani."'),
(1669624,58,1,26,6,'Niin Iisak asettui Gerariin.'),
(1669625,58,1,26,7,'Ja kun sen paikkakunnan miehet kysyivät hänen vaimostansa, sanoi hän: "Hän on minun sisareni". Hän näet pelkäsi sanoa: "Hän on minun vaimoni", sillä hän ajatteli: "Nuo miehet voivat tappaa minut Rebekan tähden, sillä hän on näöltään kaunis".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669626,58,1,26,8,'Kun hän oli viipynyt siellä jonkun aikaa, niin tapahtui, että Abimelek, filistealaisten kuningas, kerran katsellessaan ulos akkunasta näki Iisakin hyväilevän vaimoansa.'),
(1669627,58,1,26,9,'Niin Abimelek kutsutti Iisakin ja sanoi: "Katso, hänhän on sinun vaimosi! Miksi olet sanonut: ''Hän on minun sisareni''?" Iisak vastasi hänelle: "Minä ajattelin, että minut muuten ehkä tapetaan hänen tähtensä".'),
(1669628,58,1,26,10,'Abimelek sanoi: "Mitä oletkaan meille tehnyt! Kuinka helposti olisikaan voinut tapahtua, että joku kansasta olisi maannut sinun vaimosi kanssa, ja niin sinä olisit saattanut meidät syyhyn!"'),
(1669629,58,1,26,11,'Ja Abimelek antoi käskyn kaikelle kansalle, sanoen: "Joka koskee tähän mieheen tai hänen vaimoonsa, se on kuolemalla rangaistava".'),
(1669630,58,1,26,12,'Ja Iisak kylvi siinä maassa ja sai sinä vuonna satakertaisesti, sillä Herra siunasi häntä.'),
(1669631,58,1,26,13,'Ja hän rikastui ja hyötyi hyötymistään, kunnes hänestä tuli hyvin rikas.'),
(1669632,58,1,26,14,'Ja hänellä oli laumoittain sekä pikkukarjaa että raavaskarjaa ja paljon palvelijoita, niin että filistealaiset alkoivat kadehtia häntä.'),
(1669633,58,1,26,15,'Ja filistealaiset tukkivat kaikki ne kaivot, jotka hänen isänsä palvelijat olivat kaivaneet hänen isänsä Aabrahamin päivinä, ja täyttivät ne mullalla.'),
(1669634,58,1,26,16,'Silloin Abimelek sanoi Iisakille: "Mene pois luotamme, sillä sinä olet tullut paljon väkevämmäksi meitä".'),
(1669635,58,1,26,17,'Niin Iisak lähti sieltä ja leiriytyi Gerarin laaksoon ja asui siellä.'),
(1669636,58,1,26,18,'Ja Iisak kaivatti uudelleen auki ne vesikaivot, jotka hänen isänsä Aabrahamin päivinä olivat kaivetut, mutta jotka filistealaiset olivat Aabrahamin kuoltua tukkineet, ja antoi niille jälleen ne nimet, jotka hänen isänsä oli niille antanut.'),
(1669637,58,1,26,19,'Ja Iisakin palvelijat kaivoivat laaksossa ja löysivät sieltä kaivon, jossa oli juoksevaa vettä.'),
(1669638,58,1,26,20,'Mutta Gerarin paimenet alkoivat riidellä Iisakin paimenten kanssa, sanoen: "Vesi on meidän". Niin hän kutsui kaivon Eesekiksi, koska he olivat riidelleet hänen kanssaan.'),
(1669639,58,1,26,21,'Senjälkeen he kaivoivat toisen kaivon ja joutuivat riitaan siitäkin; niin hän antoi sille nimen Sitna.'),
(1669640,58,1,26,22,'Sitten hän muutti sieltä pois ja kaivoi vielä yhden kaivon. Siitä ei syntynyt riitaa. Sentähden hän nimitti sen Rehobotiksi ja sanoi: "Nyt Herra on antanut meille tilaa, niin että voimme lisääntyä maassa".'),
(1669641,58,1,26,23,'Sieltä hän meni Beersebaan.'),
(1669642,58,1,26,24,'Ja Herra ilmestyi hänelle sinä yönä ja sanoi: "Minä olen sinun isäsi Aabrahamin Jumala; älä pelkää, sillä minä olen sinun kanssasi ja siunaan sinua ja teen sinun jälkeläistesi luvun suureksi palvelijani Aabrahamin tähden".'),
(1669643,58,1,26,25,'Silloin hän rakensi sinne alttarin, huusi avuksi Herran nimeä ja pystytti sinne telttansa. Ja Iisakin palvelijat kaivoivat siihen kaivon.'),
(1669644,58,1,26,26,'Niin Abimelek lähti hänen luokseen Gerarista ystävänsä Ahusatin ja sotapäällikkönsä Piikolin seuraamana.'),
(1669645,58,1,26,27,'Mutta Iisak sanoi heille: "Minkätähden tulette minun luokseni, vaikka olette minulle vihamieliset ja karkoititte minut luotanne?"'),
(1669646,58,1,26,28,'He vastasivat: "Me olemme selvästi nähneet, että Herra on sinun kanssasi. Sentähden ajattelimme: ''Olkoon sinun ja meidän välillämme valallinen sopimus; me tahdomme tehdä sinun kanssasi liiton,'),
(1669647,58,1,26,29,'ettet tee meille mitään pahaa, niinkuin emme mekään ole sinuun koskeneet, vaan olemme tehneet sinulle ainoastaan hyvää ja sallineet sinun lähteä rauhassa''. Sinä olet nyt Herran siunattu."'),
(1669648,58,1,26,30,'Silloin hän laittoi heille pidot, ja he söivät ja joivat.'),
(1669649,58,1,26,31,'Varhain seuraavana aamuna he vannoivat valan toisillensa; senjälkeen Iisak päästi heidät menemään, ja he lähtivät hänen luotaan rauhassa.'),
(1669650,58,1,26,32,'Samana päivänä Iisakin palvelijat tulivat ja kertoivat hänelle kaivosta, jonka olivat kaivaneet, sanoen hänelle:'),
(1669651,58,1,26,33,'"Me löysimme vettä". Ja hän antoi sille nimen Siba. Sentähden on kaupungin nimi vielä tänäkin päivänä Beerseba.'),
(1669652,58,1,26,34,'Kun Eesau oli neljänkymmenen vuoden vanha, otti hän vaimoikseen Jehuditin, heettiläisen Beerin tyttären, ja Baasematin, heettiläisen Eelonin tyttären.'),
(1669653,58,1,26,35,'Näistä tuli Iisakille ja Rebekalle katkera suru.'),
(1669654,58,1,27,1,'Kun Iisak oli tullut vanhaksi ja hänen silmänsä olivat hämärtyneet, niin ettei hän enää voinut nähdä, kutsui hän Eesaun, vanhemman poikansa, ja sanoi hänelle: "Poikani!" Tämä vastasi hänelle: "Tässä olen".'),
(1669655,58,1,27,2,'Niin hän sanoi: "Katso, minä olen tullut vanhaksi enkä tiedä, milloin kuolen.'),
(1669656,58,1,27,3,'Ota siis aseesi, viinesi ja jousesi, ja mene kedolle ja pyydystä minulle riistaa.'),
(1669657,58,1,27,4,'Ja laita minulle herkkuruoka, minun mieliruokani, ja tuo se syödäkseni, että minä siunaisin sinut, ennenkuin kuolen."'),
(1669658,58,1,27,5,'Mutta Rebekka kuuli, kuinka Iisak puhui pojallensa Eesaulle. Ja kun Eesau oli lähtenyt kedolle pyydystämään riistaa, tuodakseen isällensä,'),
(1669659,58,1,27,6,'puhui Rebekka pojalleen Jaakobille sanoen: "Katso, minä kuulin sinun isäsi puhuvan veljellesi Eesaulle ja sanovan:'),
(1669660,58,1,27,7,'''Tuo minulle riistaa ja laita minulle herkkuruoka syödäkseni, että siunaisin sinut Herran edessä, ennenkuin kuolen''.'),
(1669661,58,1,27,8,'Kuule siis, poikani, mitä sanon, ja tee, mitä minä käsken:'),
(1669662,58,1,27,9,'mene laumaan ja ota sieltä minulle kaksi hyvää vohlaa laittaakseni niistä isällesi herkkuruuan, hänen mieliruokansa.'),
(1669663,58,1,27,10,'Ja sinun on vietävä se isäsi syödä, että hän siunaisi sinut, ennenkuin kuolee."'),
(1669664,58,1,27,11,'Mutta Jaakob sanoi äidillensä Rebekalle: "Katso, veljeni Eesau on karvainen, mutta minä olen sileäihoinen.'),
(1669665,58,1,27,12,'Entä jos isäni tunnustelee minua? Silloin minä joudun hänen silmissään pilkkaajaksi ja hankin itselleni kirouksen enkä siunausta."'),
(1669666,58,1,27,13,'Hänen äitinsä sanoi hänelle: "Kohdatkoon se kirous minua, poikani; kuule vain, mitä minä sanon, mene ja nouda".'),
(1669667,58,1,27,14,'Niin hän meni noutamaan ne ja toi ne äidilleen; ja hänen äitinsä laittoi herkkuruuan, hänen isänsä mieliruuan.'),
(1669668,58,1,27,15,'Ja Rebekka otti vanhemman poikansa Eesaun parhaat vaatteet, jotka olivat hänen hallussaan talossa, ja puki ne nuoremman poikansa Jaakobin ylle.'),
(1669669,58,1,27,16,'Mutta vohlain nahat hän kääri hänen käsiinsä ja paljaaseen kaulaansa.'),
(1669670,58,1,27,17,'Sitten hän antoi herkkuruuan ynnä leipomansa leivän poikansa Jaakobin käteen.'),
(1669671,58,1,27,18,'Ja Jaakob meni isänsä luo ja sanoi: "Isäni!" Hän vastasi: "Tässä olen; kuka sinä olet, poikani?"'),
(1669672,58,1,27,19,'Jaakob sanoi isällensä: "Minä olen Eesau, esikoisesi. Olen tehnyt, niinkuin käskit minun tehdä; nouse istumaan ja syö riistaani, siunataksesi minut."'),
(1669673,58,1,27,20,'Mutta Iisak sanoi pojalleen: "Kuinka olet, poikani, niin pian löytänyt?" Hän vastasi: "Herra, sinun Jumalasi, johdatti sen minun eteeni".'),
(1669674,58,1,27,21,'Niin Iisak sanoi Jaakobille: "Tulehan lähemmä, poikani, tunnustellakseni, oletko sinä poikani Eesau vai etkö".'),
(1669675,58,1,27,22,'Ja Jaakob astui isänsä Iisakin luo, ja tämä tunnusteli häntä ja sanoi: "Ääni on Jaakobin ääni, mutta kädet ovat Eesaun kädet".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669676,58,1,27,23,'Eikä Iisak tuntenut häntä, sillä hänen kätensä olivat karvaiset, niinkuin hänen veljensä Eesaun kädet, ja hän siunasi hänet.'),
(1669677,58,1,27,24,'Vielä hän kysyi: "Oletko sinä todella minun poikani Eesau?" Hän vastasi: "Olen".'),
(1669678,58,1,27,25,'Silloin hän sanoi: "Tuo ruoka minulle, syödäkseni poikani riistaa, että siunaisin sinut". Niin hän toi hänelle sen, ja hän söi; ja hän tarjosi hänelle viiniä, ja hän joi.'),
(1669679,58,1,27,26,'Senjälkeen hänen isänsä Iisak sanoi hänelle: "Tule tänne ja suutele minua, poikani".'),
(1669680,58,1,27,27,'Hän astui hänen luokseen ja suuteli häntä. Niin Iisak tunsi hänen vaatteidensa hajun ja siunasi hänet, sanoen: "Katso, minun poikani tuoksu on kuin kedon tuoksu, jonka Herra on siunannut.'),
(1669681,58,1,27,28,'Jumala antakoon sinulle taivaan kastetta ja maan lihavuutta, jyviä ja viiniä yllin kyllin.'),
(1669682,58,1,27,29,'Kansat palvelkoot sinua, kansakunnat sinua kumartakoot. Ole veljiesi herra, ja äitisi pojat kumartakoot sinua. Kirottu olkoon, joka sinua kiroaa, siunattu, joka sinua siunaa."'),
(1669683,58,1,27,30,'Kun Iisak oli ehtinyt siunata Jaakobin ja tämä juuri oli lähtenyt isänsä Iisakin luota, niin hänen veljensä Eesau tuli kotiin metsästämästä.'),
(1669684,58,1,27,31,'Ja hänkin laittoi herkkuruuan, vei sen isälleen ja sanoi isälleen: "Nouse, isäni, ja syö poikasi riistaa, siunataksesi minut".'),
(1669685,58,1,27,32,'Hänen isänsä Iisak kysyi häneltä: "Kuka olet?" Hän vastasi: "Minä olen poikasi Eesau, sinun esikoisesi".'),
(1669686,58,1,27,33,'Silloin Iisak säikähtyi kovin ja sanoi: "Kuka sitten oli se metsästäjä, joka toi minulle riistaa, niin että minä, ennenkuin sinä tulit, söin kaikkea ja siunasin hänet? Siunattu hän myös on oleva."'),
(1669687,58,1,27,34,'Kun Eesau kuuli isänsä sanat, puhkesi hän valittamaan äänekkäästi ja haikeasti ja sanoi isälleen: "Siunaa minutkin, isäni!"'),
(1669688,58,1,27,35,'Mutta hän vastasi: "Veljesi tuli kavalasti ja riisti sinulta siunauksen".'),
(1669689,58,1,27,36,'Niin hän sanoi: "Oikeinpa häntä kutsutaankin Jaakobiksi. Sillä hän on nyt kahdesti minut pettänyt: esikoisuuteni hän on minulta vienyt, ja katso, nyt hän riisti minulta myöskin siunauksen." Ja hän kysyi: "Eikö sinulla ole mitään siunausta minun varalleni?"'),
(1669690,58,1,27,37,'Ja Iisak vastasi ja sanoi Eesaulle: "Katso, minä olen asettanut hänet sinun herraksesi ja antanut kaikki hänen veljensä hänelle palvelijoiksi sekä varustanut hänet jyvillä ja viinillä; mitä voisin enää tehdä sinun hyväksesi, poikani?"'),
(1669691,58,1,27,38,'Eesau sanoi isällensä: "Tuo yksi ainoa siunausko sinulla vain onkin, isäni? Siunaa myöskin minut, isäni!" Ja Eesau korotti äänensä ja itki.'),
(1669692,58,1,27,39,'Niin hänen isänsä Iisak vastasi ja sanoi hänelle: "Katso, sinun asuinsijasi on oleva kaukana lihavasta maasta ja vailla taivaan kastetta ylhäältä.'),
(1669693,58,1,27,40,'Miekkasi varassa sinä olet elävä ja palveleva veljeäsi. Mutta valtoimena kierrellen sinä riisut hänen ikeensä niskaltasi."'),
(1669694,58,1,27,41,'Ja Eesau alkoi vihata Jaakobia siunauksen tähden, jolla hänen isänsä oli hänet siunannut; ja Eesau ajatteli itsekseen: "Pian tulee aika, jolloin suremme isäämme; silloin minä tapan veljeni Jaakobin".'),
(1669695,58,1,27,42,'Mutta Rebekalle ilmoitettiin hänen vanhemman poikansa Eesaun aikeista; ja hän kutsutti luokseen nuoremman poikansa Jaakobin ja sanoi hänelle: "Katso, veljesi Eesau uhkaa kostaa sinulle ja tappaa sinut.'),
(1669696,58,1,27,43,'Kuule siis, mitä sanon, poikani: nouse ja pakene minun veljeni Laabanin luo Harraniin'),
(1669697,58,1,27,44,'ja jää hänen luokseen joksikin aikaa, kunnes veljesi kiukku asettuu,'),
(1669698,58,1,27,45,'kunnes veljesi lakkaa sinua vihaamasta ja unhottaa, mitä olet hänelle tehnyt. Sitten minä lähetän noutamaan sinut sieltä. Minkätähden menettäisin teidät molemmat samana päivänä!"'),
(1669699,58,1,27,46,'Ja Rebekka sanoi Iisakille: "Minä olen kyllästynyt elämääni Heetin tyttärien tähden. Jos Jaakobkin ottaa vaimon Heetin tyttäristä, tässä maassa syntyneen, sellaisen kuin nämä, niin mitä varten minä enää elän?"'),
(1669700,58,1,28,1,'Silloin Iisak kutsui Jaakobin ja siunasi hänet; hän käski häntä ja sanoi hänelle: "Älä ota vaimoksesi ketään Kanaanin tyttäristä,'),
(1669701,58,1,28,2,'vaan nouse ja mene Mesopotamiaan, isoisäsi Betuelin kotiin, ja ota sieltä itsellesi vaimo enosi Laabanin tyttäristä.'),
(1669702,58,1,28,3,'Ja Jumala, Kaikkivaltias, siunatkoon sinua ja antakoon sinun tulla hedelmälliseksi ja lisääntyä, niin että sinusta tulee suuri kansojen joukko.'),
(1669703,58,1,28,4,'Ja hän suokoon sinulle Aabrahamin siunauksen, sinulle ynnä sinun jälkeläisillesi, että saisit omaksesi maan, jossa sinä muukalaisena asut ja jonka Jumala on antanut Aabrahamille."'),
(1669704,58,1,28,5,'Niin Iisak lähetti Jaakobin matkalle, ja hän lähti Mesopotamiaan Laabanin luo, joka oli aramilaisen Betuelin poika ja Rebekan, Jaakobin ja Eesaun äidin, veli.'),
(1669705,58,1,28,6,'Kun Eesau näki, että Iisak oli siunannut Jaakobin ja lähettänyt hänet Mesopotamiaan ottamaan sieltä itselleen vaimoa - sillä hän oli siunannut hänet, käskenyt häntä ja sanonut: "Älä ota vaimoa Kanaanin tyttäristä" -'),
(1669706,58,1,28,7,'ja että Jaakob oli totellut isäänsä ja äitiänsä ja lähtenyt Mesopotamiaan,'),
(1669707,58,1,28,8,'silloin hän huomasi, että Kanaanin tyttäret olivat hänen isälleen Iisakille vastenmieliset;'),
(1669708,58,1,28,9,'ja niin Eesau meni Ismaelin luo ja otti Mahalatin, Aabrahamin pojan Ismaelin tyttären, Nebajotin sisaren, vaimokseen entisten lisäksi.'),
(1669709,58,1,28,10,'Niin Jaakob lähti Beersebasta mennäksensä Harraniin.'),
(1669710,58,1,28,11,'Ja hän osui erääseen paikkaan, johon yöpyi, sillä aurinko oli laskenut; ja hän otti sen paikan kivistä yhden, pani sen päänsä alaiseksi ja asettui nukkumaan siihen paikkaan.'),
(1669711,58,1,28,12,'Niin hän näki unta, ja katso, maan päälle oli asetettu tikapuut, joiden pää ulottui taivaaseen, ja katso, Jumalan enkelit kulkivat niitä myöten ylös ja alas.'),
(1669712,58,1,28,13,'Ja katso, Herra seisoi hänen edessään ja sanoi: "Minä olen Herra, sinun Isäsi Aabrahamin Jumala ja Iisakin Jumala. Tämän maan, jonka päällä sinä makaat, minä annan sinulle ja sinun jälkeläisillesi.'),
(1669713,58,1,28,14,'Ja sinun jälkeläistesi paljous on oleva kuin maan tomu, ja sinä leviät länteen ja itään, pohjoiseen ja etelään, ja sinussa ja sinun siemenessäsi tulevat siunatuiksi kaikki sukukunnat maan päällä.'),
(1669714,58,1,28,15,'Ja katso, minä olen sinun kanssasi ja varjelen sinua, missä ikinä kuljet, ja saatan sinut takaisin tähän maahan; sillä minä en jätä sinua, ennenkuin olen toteuttanut sen, minkä minä olen sinulle puhunut."'),
(1669715,58,1,28,16,'Silloin Jaakob heräsi unestansa ja sanoi: "Herra on totisesti tässä paikassa, enkä minä sitä tiennyt".'),
(1669716,58,1,28,17,'Ja pelko valtasi hänet, ja hän sanoi: "Kuinka peljättävä onkaan tämä paikka! Tässä on varmasti Jumalan huone ja taivaan portti."'),
(1669717,58,1,28,18,'Ja Jaakob nousi varhain aamulla, otti kiven, jonka hän oli pannut päänsä alaiseksi, ja nosti sen pystyyn patsaaksi ja vuodatti öljyä sen päälle.'),
(1669718,58,1,28,19,'Ja hän kutsui paikan Beeteliksi; mutta ennen oli kaupungin nimenä Luus.'),
(1669719,58,1,28,20,'Ja Jaakob teki lupauksen, sanoen: "Jos Jumala on minun kanssani ja varjelee minut sillä tiellä, jota nyt kuljen, ja antaa minulle leipää syödäkseni ja vaatteita pukeutuakseni,'),
(1669720,58,1,28,21,'niin että saan palata rauhassa isäni kotiin, niin on Herra oleva minun Jumalani;'),
(1669721,58,1,28,22,'ja tämä kivi, jonka olen patsaaksi pystyttänyt, on oleva Jumalan huone, ja kaikesta, mitä minulle suot, minä totisesti annan sinulle kymmenykset".'),
(1669722,58,1,29,1,'Ja Jaakob lähti matkaan ja tuli Idän miesten maalle.'),
(1669723,58,1,29,2,'Ja katso, hän huomasi kedolla kaivon, ja katso, sen ääressä makasi kolme lammaslaumaa, sillä siitä kaivosta oli tapana juottaa laumoja. Ja kaivon suulla oli suuri kivi.'),
(1669724,58,1,29,3,'Sentähden annettiin kaikkien laumojen kokoontua sinne ja sitten vieritettiin kivi kaivon suulta ja juotettiin lampaat, jonka jälkeen kivi taas pantiin paikoilleen kaivon suulle.'),
(1669725,58,1,29,4,'Ja Jaakob sanoi heille: "Veljeni, mistä te olette?" He vastasivat: "Harranista olemme".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669726,58,1,29,5,'Hän kysyi heiltä: "Tunnetteko Laabanin, Naahorin pojan?" He vastasivat: "Tunnemme".'),
(1669727,58,1,29,6,'Ja hän kysyi heiltä: "Voiko hän hyvin?" He vastasivat: "Hyvin hän voi; ja katso, Raakel, hänen tyttärensä, tulee tuolla lammasten kanssa".'),
(1669728,58,1,29,7,'Hän sanoi: "Vielä on täysi päivä ja liian aikaista koota lauma; juottakaa lampaat ja viekää ne takaisin laitumelle".'),
(1669729,58,1,29,8,'He vastasivat: "Emme voi, ennenkuin kaikki laumat ovat koolla ja kivi on vieritetty kaivon suulta; sitten juotamme lampaat".'),
(1669730,58,1,29,9,'Hänen vielä puhuessaan heidän kanssaan tuli Raakel isänsä lammasten kanssa, sillä hänen oli tapana olla paimenessa.'),
(1669731,58,1,29,10,'Kun Jaakob näki Raakelin, enonsa Laabanin tyttären, ja enonsa Laabanin lampaat, astui hän esiin ja vieritti kiven kaivon suulta ja juotti enonsa Laabanin lampaat.'),
(1669732,58,1,29,11,'Ja Jaakob suuteli Raakelia ja korotti äänensä ja itki.'),
(1669733,58,1,29,12,'Niin Jaakob ilmoitti Raakelille, että hän oli hänen isänsä sukulainen ja Rebekan poika; ja Raakel riensi pois ja ilmoitti sen isällensä.'),
(1669734,58,1,29,13,'Kun Laaban kuuli kerrottavan Jaakobista, sisarensa pojasta, riensi hän häntä vastaan, syleili ja suuteli häntä ja toi hänet kotiinsa; ja hän kertoi Laabanille kaikki, mitä oli tapahtunut.'),
(1669735,58,1,29,14,'Ja Laaban sanoi hänelle: "Niin, sinä olet minun luutani ja lihaani". Ja hän asui hänen luonaan kuukauden päivät.'),
(1669736,58,1,29,15,'Ja Laaban sanoi Jaakobille: "Olet tosin sukulaiseni, mutta palvelisitko silti minua palkatta? Sano minulle, mikä on palkkasi oleva."'),
(1669737,58,1,29,16,'Mutta Laabanilla oli kaksi tytärtä; vanhemman nimi oli Leea, nuoremman nimi oli Raakel.'),
(1669738,58,1,29,17,'Ja Leealla oli sameat silmät, mutta Raakelilla oli kaunis vartalo ja kauniit kasvot.'),
(1669739,58,1,29,18,'Ja Jaakob rakasti Raakelia; niin hän sanoi: "Minä palvelen sinua seitsemän vuotta saadakseni Raakelin, nuoremman tyttäresi".'),
(1669740,58,1,29,19,'Laaban vastasi: "Parempi on, että annan hänet sinulle, kuin että antaisin hänet jollekin toiselle; jää luokseni".'),
(1669741,58,1,29,20,'Jaakob palveli siis seitsemän vuotta saadakseen Raakelin, ja ne tuntuivat hänestä muutamilta päiviltä; niin hän rakasti häntä.'),
(1669742,58,1,29,21,'Senjälkeen Jaakob sanoi Laabanille: "Anna minulle vaimoni, sillä aikani on nyt kulunut umpeen, mennäkseni hänen tykönsä".'),
(1669743,58,1,29,22,'Silloin Laaban kutsui kokoon kaikki sen paikkakunnan asukkaat ja laittoi pidot;'),
(1669744,58,1,29,23,'mutta illalla hän otti tyttärensä Leean ja vei hänet hänen luokseen; ja hän yhtyi häneen.'),
(1669745,58,1,29,24,'Ja Laaban antoi orjattarensa Silpan tyttärellensä Leealle orjattareksi.'),
(1669746,58,1,29,25,'Aamulla hän näki, että se oli Leea. Ja hän sanoi Laabanille: "Mitä oletkaan minulle tehnyt? Olenhan palvellut sinua saadakseni Raakelin! Miksi petit minut?"'),
(1669747,58,1,29,26,'Laaban vastasi: "Ei ole meidän maassamme tapana antaa nuorempaa ennen vanhempaa.'),
(1669748,58,1,29,27,'Vietä nyt vain tämä hääviikko loppuun, niin annetaan sinulle toinenkin, kunhan olet palveluksessani vielä toiset seitsemän vuotta."'),
(1669749,58,1,29,28,'Ja Jaakob suostui siihen, ja kun hän oli viettänyt sen viikon loppuun, antoi Laaban myöskin tyttärensä Raakelin hänelle vaimoksi.'),
(1669750,58,1,29,29,'Ja Laaban antoi orjattarensa Bilhan tyttärellensä Raakelille orjattareksi.'),
(1669751,58,1,29,30,'Ja hän yhtyi myös Raakeliin, ja Raakel oli hänelle rakkaampi kuin Leea; ja hän palveli Laabanin luona vielä toiset seitsemän vuotta.'),
(1669752,58,1,29,31,'Ja kun Herra näki, että Leeaa hyljittiin, avasi hän hänen kohtunsa; mutta Raakel oli hedelmätön.'),
(1669753,58,1,29,32,'Niin Leea tuli raskaaksi ja synnytti pojan ja antoi hänelle nimen Ruuben, sanoen: "Herra on nähnyt minun kurjuuteni; nyt on mieheni rakastava minua".'),
(1669754,58,1,29,33,'Ja hän tuli jälleen raskaaksi ja synnytti pojan ja sanoi: "Herra on kuullut, että minua hyljitään, ja on antanut minulle myös tämän". Niin hän antoi hänelle nimen Simeon.'),
(1669755,58,1,29,34,'Ja hän tuli jälleen raskaaksi ja synnytti pojan ja sanoi: "Nyt kai mieheni vihdoinkin kiintyy minuun, sillä olenhan synnyttänyt hänelle kolme poikaa". Sentähden hän antoi hänelle nimen Leevi.'),
(1669756,58,1,29,35,'Ja hän tuli vieläkin raskaaksi ja synnytti pojan ja sanoi: "Nyt minä kiitän Herraa". Sentähden hän antoi hänelle nimen Juuda. Sitten hän lakkasi synnyttämästä.'),
(1669757,58,1,30,1,'Kun Raakel näki, ettei hän synnyttänyt Jaakobille, kadehti hän sisartaan ja sanoi Jaakobille: "Hanki minulle lapsia, muuten minä kuolen".'),
(1669758,58,1,30,2,'Niin Jaakob vihastui Raakeliin ja sanoi: "Minäkö olen Jumala, joka on kieltänyt sinulta kohdun hedelmän?"'),
(1669759,58,1,30,3,'Mutta Raakel sanoi: "Tässä on orjattareni Bilha; yhdy häneen, että hän synnyttäisi minun helmaani ja minäkin siten saisin lapsia hänestä".'),
(1669760,58,1,30,4,'Ja hän antoi hänelle orjattarensa Bilhan vaimoksi ja Jaakob yhtyi häneen.'),
(1669761,58,1,30,5,'Ja Bilha tuli raskaaksi ja synnytti Jaakobille pojan.'),
(1669762,58,1,30,6,'Niin Raakel sanoi: "Jumala hankki minulle oikeuden, ja hän kuuli minun ääneni ja antoi minulle pojan". Sentähden hän antoi hänelle nimen Daan.'),
(1669763,58,1,30,7,'Ja Bilha, Raakelin orjatar, tuli jälleen raskaaksi ja synnytti Jaakobille toisen pojan.'),
(1669764,58,1,30,8,'Niin Raakel sanoi: "Jumalan taisteluja minä olen taistellut sisareni kanssa ja olen voittanut". Ja hän antoi hänelle nimen Naftali.'),
(1669765,58,1,30,9,'Kun Leea näki lakanneensa synnyttämästä, otti hän orjattarensa Silpan ja antoi hänet Jaakobille vaimoksi.'),
(1669766,58,1,30,10,'Ja Silpa, Leean orjatar, synnytti Jaakobille pojan.'),
(1669767,58,1,30,11,'Niin Leea sanoi: "Onneksi!" Ja hän antoi hänelle nimen Gaad.'),
(1669768,58,1,30,12,'Ja Silpa, Leean orjatar, synnytti Jaakobille toisen pojan.'),
(1669769,58,1,30,13,'Niin Leea sanoi: "Onnellista minua! Niin, naiset ylistävät minua onnelliseksi." Ja hän antoi hänelle nimen Asser.'),
(1669770,58,1,30,14,'Mutta Ruuben meni kerran ulos nisunleikkuun aikana ja löysi lemmenmarjoja vainiolta ja toi ne äidillensä Leealle. Niin Raakel sanoi Leealle: "Anna minulle poikasi lemmenmarjoja".'),
(1669771,58,1,30,15,'Leea vastasi hänelle: "Eikö riitä, että olet vienyt minulta mieheni, koska tahdot ottaa vielä poikani lemmenmarjatkin?" Raakel sanoi: "Olkoon, maatkoon hän tämän yön sinun kanssasi, kunhan saan poikasi lemmenmarjat".'),
(1669772,58,1,30,16,'Kun Jaakob illalla palasi vainiolta, meni Leea häntä vastaan ja sanoi: "Minun luokseni sinun on tultava, sillä minä olen ostanut sinut poikani lemmenmarjoilla". Ja hän makasi sen yön hänen kanssaan.'),
(1669773,58,1,30,17,'Ja Jumala kuuli Leeaa, ja Leea tuli raskaaksi ja synnytti Jaakobille viidennen pojan.'),
(1669774,58,1,30,18,'Niin Leea sanoi: "Jumala on palkinnut minulle sen, että annoin orjattareni miehelleni". Ja hän antoi hänelle nimen Isaskar.'),
(1669775,58,1,30,19,'Ja Leea tuli jälleen raskaaksi ja synnytti Jaakobille kuudennen pojan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669776,58,1,30,20,'Silloin Leea sanoi: "Jumala on antanut minulle hyvän lahjan. Nyt mieheni on asuva minun luonani, sillä minä olen synnyttänyt hänelle kuusi poikaa." Ja hän antoi hänelle nimen Sebulon.'),
(1669777,58,1,30,21,'Sitten hän synnytti tyttären ja antoi hänelle nimen Diina.'),
(1669778,58,1,30,22,'Mutta Jumala muisti Raakeliakin, ja Jumala kuuli häntä ja avasi hänen kohtunsa.'),
(1669779,58,1,30,23,'Niin hän tuli raskaaksi ja synnytti pojan ja sanoi: "Jumala on ottanut pois minun häpeäni".'),
(1669780,58,1,30,24,'Ja hän antoi hänelle nimen Joosef, sanoen: "Herra antakoon minulle vielä toisen pojan".'),
(1669781,58,1,30,25,'Ja kun Raakel oli synnyttänyt Joosefin, sanoi Jaakob Laabanille: "Päästä minut menemään kotiini ja omaan maahani.'),
(1669782,58,1,30,26,'Anna minulle vaimoni ja lapseni, joiden vuoksi olen sinua palvellut, mennäkseni pois; sillä tiedäthän itse, kuinka olen sinua palvellut."'),
(1669783,58,1,30,27,'Laaban vastasi hänelle: "Jospa saisin armon silmiesi edessä! Merkkini ilmoittavat, että Herra sinun tähtesi on siunannut minua."'),
(1669784,58,1,30,28,'Ja hän sanoi vielä: "Määrää palkka, joka minun on sinulle maksettava, niin minä sen annan".'),
(1669785,58,1,30,29,'Hän vastasi hänelle: "Itsehän tiedät, kuinka minä olen sinua palvellut ja millaiseksi karjasi on tullut minun hoidossani.'),
(1669786,58,1,30,30,'Sillä vähän sinulla oli ennen minun tuloani, mutta sitten se on karttunut suureksi, ja Herra on siunannut sinua, missä vain minä liikuin. Mutta milloin saan ruveta tekemään työtä minäkin oman perheeni hyväksi?"'),
(1669787,58,1,30,31,'Hän vastasi: "Mitä minun on sinulle annettava?" Jaakob sanoi: "Ei sinun tarvitse antaa minulle mitään. Jos myönnät minulle tämän, niin minä yhä edelleen paimennan ja vartioitsen sinun laumojasi:'),
(1669788,58,1,30,32,'minä tarkastan tänään kaiken laumasi; erota siitä pois kaikki pilkulliset ja kirjavat lampaat sekä karitsoista kaikki mustat ja vuohista kirjavat ja pilkulliset. Ja minun palkkani on sitten oleva tämä,'),
(1669789,58,1,30,33,'ja siinä minun rehellisyyteni tulee toteennäytetyksi: kun vasta tulet omin silmin katsomaan minun palkkaani, niin kaikki vuohet, jotka eivät ole pilkullisia eivätkä kirjavia, ja kaikki karitsat, jotka eivät ole mustia, katsottakoon minun varastamikseni."'),
(1669790,58,1,30,34,'Laaban vastasi: "Hyvä, olkoon, niinkuin olet puhunut".'),
(1669791,58,1,30,35,'Ja samana päivänä hän erotti pois juovikkaat ja kirjavat vuohipukit ja kaikki pilkulliset ja kirjavat vuohet - kaikki, joissa oli jotakin valkoista - sekä kaikki mustat karitsat ja jätti ne poikiensa hoitoon.'),
(1669792,58,1,30,36,'Ja hän asetti niin, että oli kolmen päivän välimatka hänen ja Jaakobin välillä; ja Jaakob paimensi Laabanin muuta karjaa.'),
(1669793,58,1,30,37,'Mutta Jaakob otti itselleen tuoreita haavan, mantelipuun ja plataanin oksia ja kuori niihin valkeita juovia, paljastaen oksien valkoisen rungon.'),
(1669794,58,1,30,38,'Ja kuorimansa oksat hän pani eläinten eteen vesikaukaloihin eli juoma-astioihin, joista ne tulivat juomaan; ja ne olivat kiimallaan tullessansa juomaan.'),
(1669795,58,1,30,39,'Ja eläimet pariutuivat oksien edessä ja synnyttivät juovikkaita, pilkullisia ja kirjavia karitsoita.'),
(1669796,58,1,30,40,'Sitten Jaakob erotti karitsat; ja hän asetti eläinten päät niihin päin, jotka olivat pilkullisia, ja kaikkiin niihin päin, jotka olivat mustia Laabanin laumassa; siten hän hankki itselleen eri laumansa eikä päästänyt niitä Laabanin laumaan.'),
(1669797,58,1,30,41,'Ja joka kerta kun voimakkaat eläimet olivat kiimallaan, pani Jaakob oksat eläinten silmien eteen vesikaukaloihin, niin että ne pariutuivat oksien edessä.'),
(1669798,58,1,30,42,'Mutta heikkojen eläinten eteen hän ei niitä pannut. Niin joutuivat heikot Laabanille ja voimakkaat Jaakobille.'),
(1669799,58,1,30,43,'Ja siten mies tuli ylen rikkaaksi; hän sai paljon pikkukarjaa sekä palvelijattaria, palvelijoita, kameleja ja aaseja.'),
(1669800,58,1,31,1,'Mutta hän sai kuulla, että Laabanin pojat puhuivat näin: "Jaakob on anastanut kaikki, mitä isämme omisti; isämme omaisuudesta hän on hankkinut itselleen kaiken tämän rikkauden".'),
(1669801,58,1,31,2,'Ja Jaakob huomasi Laabanin kasvoista, ettei hän ollut häntä kohtaan niinkuin ennen.'),
(1669802,58,1,31,3,'Ja Herra sanoi Jaakobille: "Palaja isiesi maahan ja sukusi tykö. Minä olen sinun kanssasi."'),
(1669803,58,1,31,4,'Niin Jaakob kutsutti Raakelin ja Leean kedolle laumansa luo,'),
(1669804,58,1,31,5,'ja hän sanoi heille: "Minä huomaan isänne kasvoista, ettei hän ole minua kohtaan niinkuin ennen, vaikka isäni Jumala on ollut minun kanssani.'),
(1669805,58,1,31,6,'Te tiedätte, että minä olen palvellut isäänne kaikin voimin,'),
(1669806,58,1,31,7,'mutta isänne on kohdellut minua petollisesti ja muuttanut palkkaani kymmenen kertaa. Jumala ei kuitenkaan ole sallinut hänen tehdä minulle mitään vahinkoa.'),
(1669807,58,1,31,8,'Kun hän sanoi: ''Pilkulliset olkoot sinun palkkasi'', niin koko lauma kantoi pilkullisia; ja kun hän sanoi: ''Juovikkaat olkoot sinun palkkasi'', niin koko lauma kantoi juovikkaita.'),
(1669808,58,1,31,9,'Niin on Jumala ottanut isänne omaisuuden ja antanut minulle.'),
(1669809,58,1,31,10,'Mutta lauman pariutumisen aikana minä nostin silmäni ja näin unessa, että vuohipukit, jotka astuivat laumaa, olivat juovikkaita, pilkullisia ja kirjavia.'),
(1669810,58,1,31,11,'Ja Jumalan enkeli sanoi minulle unessa: ''Jaakob!'' Minä vastasin: ''Tässä olen''.'),
(1669811,58,1,31,12,'Niin hän sanoi: ''Nosta silmäsi ja katso, kaikki vuohipukit, jotka astuvat laumaa, ovat juovikkaita, pilkullisia ja kirjavia, sillä minä olen nähnyt kaiken, mitä Laaban sinulle tekee.'),
(1669812,58,1,31,13,'Minä olen Jumala, joka ilmestyin Beetelissä, jossa sinä voitelit patsaan ja jossa teit minulle lupauksen. Nouse nyt ja lähde tästä maasta ja palaja synnyinmaahasi.''"'),
(1669813,58,1,31,14,'Silloin Raakel ja Leea vastasivat ja sanoivat hänelle: "Ei meillä ole enää osaa eikä perintöä isämme talossa.'),
(1669814,58,1,31,15,'Eikö hän pitänyt meitä kuin vieraita, koska myi meidät ja söi suuhunsa meistä saamansa hinnan.'),
(1669815,58,1,31,16,'Niin, koko se rikkaus, jonka Jumala on ottanut isältämme, meidän se on ja meidän lastemme. Tee siis nyt kaikki, mitä Jumala on sinulle sanonut."'),
(1669816,58,1,31,17,'Silloin Jaakob nousi ja nosti lapsensa ja vaimonsa kamelien selkään'),
(1669817,58,1,31,18,'ja kuljetti pois kaiken karjansa ja kaiken omaisuutensa, jonka hän oli koonnut, kaiken omistamansa ja Mesopotamiassa hankkimansa karjan, mennäkseen isänsä Iisakin luo Kanaanin maahan.'),
(1669818,58,1,31,19,'Mutta Laaban oli mennyt keritsemään lampaitaan. Silloin Raakel varasti isänsä kotijumalat.'),
(1669819,58,1,31,20,'Ja Jaakob lähti varkain aramilaisen Laabanin luota eikä ilmaissut hänelle pakenemisaiettaan.'),
(1669820,58,1,31,21,'Niin hän pakeni kaikkinensa, lähti ja meni virran yli ja suuntasi kulkunsa Gileadin vuorille päin.'),
(1669821,58,1,31,22,'Mutta kolmantena päivänä Laabanille ilmoitettiin, että Jaakob oli paennut.'),
(1669822,58,1,31,23,'Silloin hän otti mukaansa heimonsa miehet ja ajoi häntä takaa seitsemän päivänmatkaa ja saavutti hänet Gileadin vuorilla.'),
(1669823,58,1,31,24,'Mutta Jumala tuli aramilaisen Laabanin luo unessa yöllä ja sanoi hänelle: "Varo, ettet puhu Jaakobille hyvää etkä pahaa".'),
(1669824,58,1,31,25,'Ja Laaban saavutti Jaakobin. Jaakob oli pystyttänyt telttansa vuorelle, Laaban taas pystytti telttansa Gileadin vuorelle.'),
(1669825,58,1,31,26,'Ja Laaban sanoi Jaakobille: "Mitä oletkaan tehnyt? Sinä olet pettänyt minut ja kuljettanut pois minun tyttäreni niinkuin miekalla otetut!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669826,58,1,31,27,'Minkätähden pakenit salaa, läksit luotani varkain? Et ilmoittanut minulle mitään, ja niin minä en saanut saattaa sinua matkalle iloiten ja laulaen, vaskirummuin ja kantelein,'),
(1669827,58,1,31,28,'etkä suonut minun suudella lasteni lapsia ja tyttäriäni. Tyhmästi sinä olet menetellyt.'),
(1669828,58,1,31,29,'Minulla olisi valta tehdä teille pahaa, mutta teidän isänne Jumala sanoi minulle viime yönä näin: ''Varo, ettet puhu Jaakobille hyvää etkä pahaa''.'),
(1669829,58,1,31,30,'Olkoon: sinä olet nyt lähtenyt matkallesi, koska niin suuresti ikävöit isäsi kotiin, mutta minkätähden olet varastanut minun jumalani?"'),
(1669830,58,1,31,31,'Jaakob vastasi ja sanoi Laabanille: "Minä pelkäsin, sillä ajattelin, että sinä riistäisit minulta tyttäresi.'),
(1669831,58,1,31,32,'Mutta se, jonka hallusta löydät jumalasi, menettäköön henkensä. Heimojemme miesten läsnäollessa tutki, mitä minulla on, ja ota pois, mikä on omaasi." Sillä Jaakob ei tiennyt, että Raakel oli ne varastanut.'),
(1669832,58,1,31,33,'Ja Laaban meni Jaakobin telttaan, Leean telttaan ja molempien orjatarten telttaan, mutta ei löytänyt mitään. Ja tultuaan ulos Leean teltasta hän meni Raakelin telttaan.'),
(1669833,58,1,31,34,'Mutta Raakel oli ottanut kotijumalat, pannut ne kamelin satulaan ja istunut niiden päälle. Ja Laaban penkoi koko teltan, mutta ei löytänyt mitään.'),
(1669834,58,1,31,35,'Ja hän sanoi isällensä: "Älä vihastu, herrani, siitä etten voi nousta sinun edessäsi, sillä minun on, niinkuin naisten tavallisesti on". Ja Laaban etsi, mutta ei löytänyt kotijumalia.'),
(1669835,58,1,31,36,'Silloin Jaakob vihastui ja soimasi Laabania; Jaakob puhkesi puhumaan ja sanoi Laabanille: "Mitä minä olen rikkonut, mitä pahaa minä olen tehnyt, että näin minua ahdistat?'),
(1669836,58,1,31,37,'Nyt olet penkonut kaikki minun tavarani; mitä olet löytänyt sellaista, joka olisi sinun talosi tavaraa? Tuo se tähän minun heimoni ja sinun heimosi miesten eteen, että he ratkaisisivat meidän molempien välin.'),
(1669837,58,1,31,38,'Jo kaksikymmentä vuotta minä olen ollut sinun luonasi; sinun uuhesi ja vuohesi eivät ole synnyttäneet keskoisia, enkä minä ole oinaita sinun laumastasi syönyt.'),
(1669838,58,1,31,39,'Pedon haaskaamaa en ole sinulle tuonut, se oli minun itseni korvattava; minulta sinä sen vaadit, olipa se viety päivällä tai viety yöllä.'),
(1669839,58,1,31,40,'Päivällä vaivasi minua helle, yöllä vilu, ja uni pakeni silmistäni.'),
(1669840,58,1,31,41,'Jo kaksikymmentä vuotta minä olen ollut sinun talossasi; neljätoista vuotta minä palvelin sinua saadakseni molemmat tyttäresi ja kuusi vuotta saadakseni sinulta karjaa, mutta kymmenen kertaa sinä muutit minun palkkani.'),
(1669841,58,1,31,42,'Jos minun isäni Jumala, Aabrahamin Jumala, jota myöskin Iisak pelkää, ei olisi ollut minun puolellani, niin sinä olisit nyt lähettänyt minut tyhjänä tieheni. Jumala on nähnyt minun kurjuuteni ja kätteni vaivannäön, ja hän ratkaisi viime yönä asian."'),
(1669842,58,1,31,43,'Niin Laaban vastasi ja sanoi Jaakobille: "Tyttäret ovat minun tyttäriäni, ja lapset ovat minun lapsiani, ja karja on minun karjaani, ja kaikki, mitä näet, on minun omaani. Mutta minkä minä nyt mahdan näille tyttärilleni tai lapsille, jotka he ovat synnyttäneet!'),
(1669843,58,1,31,44,'Tule siis, tehkäämme liitto keskenämme, ja olkoon se todistuksena meidän välillämme, minun ja sinun."'),
(1669844,58,1,31,45,'Silloin Jaakob otti kiven ja nosti sen pystyyn patsaaksi.'),
(1669845,58,1,31,46,'Ja Jaakob sanoi heimonsa miehille: "Kootkaa kiviä". Ja he ottivat kiviä ja rakensivat roukkion ja aterioivat siinä sen kiviroukkion päällä.'),
(1669846,58,1,31,47,'Ja Laaban antoi sille nimen Jegar-Saahaduta, mutta Jaakob antoi sille nimen Galed.'),
(1669847,58,1,31,48,'Ja Laaban sanoi: "Tämä roukkio olkoon tänään todistajana meidän välillämme, minun ja sinun"; sentähden hän antoi sille nimen Galed'),
(1669848,58,1,31,49,'ja myöskin nimen Mispa, sillä hän sanoi: "Herra olkoon vartija meidän välillämme, minun ja sinun, kun joudumme loitolle toistemme näkyvistä.'),
(1669849,58,1,31,50,'Jos sinä kohtelet pahasti minun tyttäriäni tahi otat toisia vaimoja tyttärieni lisäksi, niin tiedä, että vaikkei ketään ihmistä olekaan läsnä, Jumala kuitenkin on todistajana meidän välillämme, minun ja sinun."'),
(1669850,58,1,31,51,'Ja Laaban sanoi vielä Jaakobille: "Katso, tämä roukkio ja tämä patsas, jonka minä olen pystyttänyt meidän välillemme, minun ja sinun'),
(1669851,58,1,31,52,'- tämä roukkio olkoon todistuksena, ja myöskin tämä patsas olkoon todistuksena siitä, etten minä kulje tämän roukkion ohi sinun luoksesi ja ettet sinäkään kulje tämän roukkion ja tämän patsaan ohi minun luokseni paha mielessä.'),
(1669852,58,1,31,53,'Aabrahamin Jumala ja Naahorin Jumala, heidän isiensä Jumala, olkoon tuomarina meidän välillämme." Ja Jaakob vannoi valansa Jumalan kautta, jota hänen isänsä Iisak pelkäsi.'),
(1669853,58,1,31,54,'Ja Jaakob uhrasi vuorella teurasuhrin ja kutsui heimonsa miehet aterioimaan, ja he aterioivat ja olivat yötä vuorella.'),
(1669854,58,1,31,55,'Mutta varhain seuraavana aamuna Laaban nousi, suuteli lastensa lapsia ja tyttäriään ja hyvästeli heidät; sitten hän lähti matkaan ja palasi kotiinsa.'),
(1669855,58,1,32,1,'Mutta Jaakob kulki tietänsä; ja Jumalan enkeleitä tuli häntä vastaan.'),
(1669856,58,1,32,2,'Ja nähdessään heidät Jaakob sanoi: "Tämä on Jumalan sotajoukkoa". Ja hän antoi sille paikalle nimen Mahanaim.'),
(1669857,58,1,32,3,'Sitten Jaakob lähetti sanansaattajat edellään veljensä Eesaun luo Seirin maahan, Edomin alueelle.'),
(1669858,58,1,32,4,'Ja hän käski heitä sanoen: "Sanokaa herralleni Eesaulle näin: ''Sinun palvelijasi Jaakob sanoo: Minä olen oleskellut Laabanin luona ja viipynyt siellä tähän saakka;'),
(1669859,58,1,32,5,'ja minä olen saanut raavaita, aaseja, pikkukarjaa, palvelijoita ja palvelijattaria ja lähetän nyt sanan herralleni, että saisin armon sinun silmiesi edessä''."'),
(1669860,58,1,32,6,'Sanansaattajat palasivat Jaakobin luo ja sanoivat: "Me tulimme veljesi Eesaun luo; hän on jo matkalla sinua vastaan, neljäsataa miestä mukanaan".'),
(1669861,58,1,32,7,'Silloin valtasi Jaakobin suuri pelko ja ahdistus. Ja hän jakoi väen, joka oli hänen kanssansa, ja pikkukarjan ja raavaskarjan ja kamelit kahteen joukkoon.'),
(1669862,58,1,32,8,'Sillä hän ajatteli: "Jos Eesau hyökkää toisen joukon kimppuun ja tuhoaa sen, niin toinen joukko pääsee pakoon".'),
(1669863,58,1,32,9,'Ja Jaakob sanoi: "Isäni Aabrahamin Jumala ja isäni Iisakin Jumala, Herra, sinä, joka sanoit minulle: ''Palaja maahasi ja sukusi luo, niin minä teen sinulle hyvää!'''),
(1669864,58,1,32,10,'Minä olen liian halpa kaikkeen siihen armoon ja kaikkeen siihen uskollisuuteen, jota sinä olet palvelijallesi osoittanut; sillä ainoastaan sauva kädessäni minä kuljin tämän Jordanin yli, ja nyt on minulle karttunut kaksi joukkoa.'),
(1669865,58,1,32,11,'Pelasta minut veljeni Eesaun käsistä, sillä minä pelkään, että hän tulee ja tuhoaa minut ynnä äidit lapsineen.'),
(1669866,58,1,32,12,'Olethan itse sanonut: ''Minä teen sinulle hyvää ja annan sinun jälkeläistesi luvun tulla paljoksi kuin meren hiekka, jota ei voida lukea sen paljouden tähden''."'),
(1669867,58,1,32,13,'Ja hän jäi siihen siksi yöksi. Sitten hän erotti omaisuudestaan lahjaksi veljelleen Eesaulle'),
(1669868,58,1,32,14,'kaksisataa vuohta ja kaksikymmentä vuohipukkia, kaksisataa uuhta ja kaksikymmentä oinasta,'),
(1669869,58,1,32,15,'kolmekymmentä imettävää kamelia varsoinensa, neljäkymmentä lehmää ja kymmenen härkää, kaksikymmentä aasintammaa ja kymmenen aasia.'),
(1669870,58,1,32,16,'Ja hän jätti ne palvelijainsa haltuun, kunkin lauman erikseen, ja sanoi palvelijoilleen: "Menkää minun edelläni ja jättäkää välimatka kunkin lauman välille".'),
(1669871,58,1,32,17,'Ja hän käski ensimmäistä sanoen: "Kun veljeni Eesau kohtaa sinut ja kysyy: ''Kenen sinä olet, ja mihin menet, ja kenen ovat nuo elukat tuolla edelläsi?'''),
(1669872,58,1,32,18,'niin vastaa: ''Ne ovat palvelijasi Jaakobin, lähetetyt lahjaksi herralleni Eesaulle; ja katso, myös hän itse tulee jäljessämme''."'),
(1669873,58,1,32,19,'Samoin hän käski toista ja kolmatta ja kaikkia muita, jotka laumoja ajoivat, sanoen: "Juuri näin on teidän sanottava Eesaulle, kun tapaatte hänet.'),
(1669874,58,1,32,20,'Ja sanokaa myös: ''Katso, sinun palvelijasi Jaakob tulee meidän jäljessämme''." Sillä hän ajatteli: "Minä koetan lepyttää häntä lahjalla, joka kulkee edelläni. Sitten astun itse hänen kasvojensa eteen; ehkä hän ottaa minut ystävällisesti vastaan."'),
(1669875,58,1,32,21,'Niin lahja kulki hänen edellänsä, mutta itse hän jäi siksi yöksi leiriin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669876,58,1,32,22,'Mutta yöllä hän nousi, otti molemmat vaimonsa ja molemmat orjattarensa ja yksitoista lastansa ja meni kahlauspaikasta Jabbokin yli.'),
(1669877,58,1,32,23,'Ja hän otti heidät ja vei heidät joen yli ja vei sen yli kaiken, mitä hänellä oli.'),
(1669878,58,1,32,24,'Ja Jaakob jäi yksinänsä toiselle puolelle. Silloin painiskeli hänen kanssaan muuan mies päivän koittoon saakka.'),
(1669879,58,1,32,25,'Ja kun mies huomasi, ettei hän häntä voittanut, iski hän häntä lonkkaluuhun, niin että Jaakobin lonkka nyrjähti hänen painiskellessaan hänen kanssaan.'),
(1669880,58,1,32,26,'Ja mies sanoi: "Päästä minut, sillä päivä koittaa". Mutta hän vastasi: "En päästä sinua, ellet siunaa minua".'),
(1669881,58,1,32,27,'Ja hän sanoi hänelle: "Mikä sinun nimesi on?" Hän vastasi: "Jaakob".'),
(1669882,58,1,32,28,'Silloin hän sanoi: "Sinun nimesi älköön enää olko Jaakob, vaan Israel, sillä sinä olet taistellut Jumalan ja ihmisten kanssa ja olet voittanut".'),
(1669883,58,1,32,29,'Ja Jaakob kysyi ja sanoi: "Ilmoita nimesi". Hän vastasi: "Miksi kysyt minun nimeäni?" Ja hän siunasi hänet siinä.'),
(1669884,58,1,32,30,'Ja Jaakob antoi sille paikalle nimen Penuel, "sillä", sanoi hän, "minä olen nähnyt Jumalan kasvoista kasvoihin, ja kuitenkin on minun henkeni pelastunut".'),
(1669885,58,1,32,31,'Ja kun hän oli kulkenut Penuelin ohitse, nousi aurinko; mutta hän ontui lonkkaansa.'),
(1669886,58,1,32,32,'Sentähden israelilaiset eivät vielä tänäkään päivänä syö reisijännettä, joka kulkee lonkkaluun yli; sillä hän iski Jaakobia lonkkaluuhun, reisijänteen kohdalle.'),
(1669887,58,1,33,1,'Kun Jaakob nosti silmänsä ja katseli, niin katso, Eesau oli tulossa, neljäsataa miestä mukanaan. Silloin hän jakoi lapset Leealle, Raakelille ja molemmille orjattarille.'),
(1669888,58,1,33,2,'Ja hän asetti orjattaret lapsineen ensimmäisiksi, niiden jälkeen Leean lapsineen ja Raakelin Joosefin kanssa viimeiseksi.'),
(1669889,58,1,33,3,'Mutta itse hän astui heidän edellänsä ja kumartui maahan seitsemän kertaa, kunnes oli saapunut veljensä eteen.'),
(1669890,58,1,33,4,'Mutta Eesau riensi häntä vastaan ja sulki hänet syliinsä, halasi häntä kaulasta ja suuteli häntä; ja he itkivät.'),
(1669891,58,1,33,5,'Ja hän nosti silmänsä ja näki vaimot ja lapset ja kysyi: "Keitä ovat nämä, jotka ovat sinun seurassasi?" Hän vastasi: "Ne ovat minun lapseni, jotka Jumala on palvelijallesi lahjoittanut".'),
(1669892,58,1,33,6,'Niin orjattaret lähestyivät lapsineen ja kumartuivat maahan.'),
(1669893,58,1,33,7,'Myöskin Leea lapsineen lähestyi, ja he kumartuivat maahan. Viimein lähestyivät Joosef ja Raakel ja kumartuivat maahan.'),
(1669894,58,1,33,8,'Sitten hän kysyi: "Mitä tarkoitit kaikella sillä joukolla, jonka minä kohtasin?" Hän vastasi: "Saada armon herrani silmien edessä".'),
(1669895,58,1,33,9,'Mutta Eesau sanoi: "Minulla on itselläni kyllin; pidä, veljeni, omasi!"'),
(1669896,58,1,33,10,'Jaakob vastasi: "Ei niin; jos olen saanut armon sinun silmiesi edessä, niin ota minulta vastaan lahjani; sillä olenhan saanut nähdä sinun kasvosi, niinkuin nähdään Jumalan kasvot, ja sinä olet ottanut minut suosiollisesti vastaan.'),
(1669897,58,1,33,11,'Ota siis tervehdyslahjani, joka sinulle tuotiin, sillä Jumala on ollut minulle armollinen, ja minulla on yllin kyllin kaikkea." Ja hän pyysi häntä pyytämällä, kunnes hän otti sen.'),
(1669898,58,1,33,12,'Sitten Eesau sanoi: "Lähtekäämme liikkeelle ja vaeltakaamme eteenpäin; minä vaellan sinun edelläsi".'),
(1669899,58,1,33,13,'Mutta Jaakob sanoi hänelle: "Herrani näkee itse, että lapset ovat pieniä ja että minulla on imettäviä lampaita ja lehmiä mukanani; jos näitä ajaa kiivaasti päivänkään, kuolee koko lauma.'),
(1669900,58,1,33,14,'Kulkekoon siis herrani palvelijansa edellä; minä seuraan hiljalleen jäljessä, sen mukaan kuin karja, jota kuljetan, ja lapset jaksavat käydä, kunnes saavun herrani luo Seiriin."'),
(1669901,58,1,33,15,'Eesau vastasi: "Minä jätän luoksesi osan väestäni". Hän sanoi: "Minkätähden niin? Kunhan vain saan armon herrani silmien edessä!"'),
(1669902,58,1,33,16,'Niin Eesau sinä päivänä kääntyi takaisin ja meni sitä tietään Seiriin.'),
(1669903,58,1,33,17,'Mutta Jaakob lähti Sukkotiin ja rakensi siellä itsellensä majan. Ja karjallensa hän teki tarhoja. Siitä tuli sen paikan nimeksi Sukkot.'),
(1669904,58,1,33,18,'Ja Jaakob saapui matkallansa Mesopotamiasta onnellisesti Sikemin kaupunkiin, joka on Kanaanin maassa, ja leiriytyi kaupungin edustalle.'),
(1669905,58,1,33,19,'Ja hän osti sen maapalstan, johon hän oli pystyttänyt telttansa, Hamorin, Sikemin isän, pojilta sadalla kesitalla.'),
(1669906,58,1,33,20,'Ja hän pystytti siihen alttarin ja antoi sille nimen Eel, Israelin Jumala.'),
(1669907,58,1,34,1,'Ja Diina, Leean tytär, jonka hän oli synnyttänyt Jaakobille, meni tapaamaan sen maan tyttäriä.'),
(1669908,58,1,34,2,'Ja Sikem, joka oli hivviläisen Hamorin, sen maan ruhtinaan, poika, näki hänet, otti hänet luokseen, makasi hänen kanssaan ja teki hänelle väkivaltaa.'),
(1669909,58,1,34,3,'Ja hänen sydämensä kiintyi Diinaan, Jaakobin tyttäreen, ja hän rakasti tyttöä ja viihdytteli häntä.'),
(1669910,58,1,34,4,'Ja Sikem puhui isällensä Hamorille sanoen: "Hanki minulle tämä tyttö vaimoksi".'),
(1669911,58,1,34,5,'Ja Jaakob oli saanut kuulla, että Sikem oli raiskannut hänen tyttärensä Diinan; mutta kun hänen poikansa olivat hänen laumansa kanssa kedolla, oli Jaakob vaiti siksi, kunnes he palasivat.'),
(1669912,58,1,34,6,'Ja Hamor, Sikemin isä, meni Jaakobin luo puhuttelemaan häntä.'),
(1669913,58,1,34,7,'Ja Jaakobin pojat tulivat kedolta. Kuultuaan, mitä oli tapahtunut, miehet sydäntyivät ja vihastuivat kovin siitä, että hän oli tehnyt häpeällisen teon Israelissa, kun oli maannut Jaakobin tyttären; sillä semmoista ei saa tehdä.'),
(1669914,58,1,34,8,'Niin Hamor puhui heille sanoen: "Poikani Sikemin sydän on mielistynyt teidän sisareenne; antakaa hänet hänelle vaimoksi.'),
(1669915,58,1,34,9,'Lankoutukaa meidän kanssamme, antakaa te tyttäriänne meille, ja ottakaa te itsellenne meidän tyttäriämme,'),
(1669916,58,1,34,10,'ja jääkää asumaan meidän luoksemme. Maa on oleva teille avoinna, asukaa siinä ja kierrelkää siinä ja asettukaa sinne."'),
(1669917,58,1,34,11,'Ja Sikem sanoi tytön isälle ja veljille: "Suokaa minun saada armo silmienne edessä, ja mitä te vaaditte minulta, sen minä annan.'),
(1669918,58,1,34,12,'Vaatikaa minulta kuinka suuri morsiamen hinta ja kuinka suuret antimet tahansa: minä annan, mitä te minulta vaaditte. Antakaa minulle vain se tyttö vaimoksi."'),
(1669919,58,1,34,13,'Mutta Jaakobin pojat vastasivat Sikemille ja hänen isällensä Hamorille puhuen petollisesti, sentähden että hän oli raiskannut heidän sisarensa Diinan;'),
(1669920,58,1,34,14,'he sanoivat heille: "Emme voi tehdä sitä, että antaisimme sisaremme ympärileikkaamattomalle miehelle, sillä se olisi meistä häpeällistä.'),
(1669921,58,1,34,15,'Me suostumme ainoastaan sillä ehdolla, että te tulette meidän kaltaisiksemme, niin että kaikki miehenpuolenne ympärileikataan.'),
(1669922,58,1,34,16,'Silloin me annamme omia tyttäriämme teille ja otamme itsellemme teidän tyttäriänne, ja me asetumme teidän luoksenne ja tulemme yhdeksi kansaksi.'),
(1669923,58,1,34,17,'Mutta jos te ette kuule meitä ettekä ympärileikkauta itseänne, niin me otamme sisaremme ja menemme tiehemme."'),
(1669924,58,1,34,18,'Ja heidän puheensa kelpasi Hamorille ja Sikemille, Hamorin pojalle.'),
(1669925,58,1,34,19,'Eikä nuori mies viivytellyt niin tekemästä, sillä hän oli mieltynyt Jaakobin tyttäreen; ja hän oli suuremmassa arvossa kuin kukaan muu hänen isänsä perheessä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669926,58,1,34,20,'Niin menivät Hamor ja hänen poikansa Sikem kaupunkinsa porttiin ja puhuivat kaupunkinsa miehille sanoen:'),
(1669927,58,1,34,21,'"Näillä miehillä on rauha mielessä meitä kohtaan; antakaamme heidän siis asettua tähän maahan ja kierrellä siinä, onhan maa tilava heillekin joka suuntaan. Ottakaamme me heidän tyttäriänsä vaimoiksemme, ja antakaamme me tyttäriämme heille.'),
(1669928,58,1,34,22,'Mutta ainoastaan sillä ehdolla miehet suostuvat asettumaan meidän luoksemme, tullaksensa meidän kanssamme yhdeksi kansaksi, että kaikki miehenpuolemme ympärileikataan, niinkuin he itsekin ovat ympärileikatut.'),
(1669929,58,1,34,23,'Tulevathan silloin heidän karjansa ja tavaransa ja kaikki heidän juhtansa meidän omiksemme. Suostukaamme siis, niin he asettuvat luoksemme."'),
(1669930,58,1,34,24,'Ja he kuulivat Hamoria ja hänen poikaansa Sikemiä; kaikki, jotka kulkivat hänen kaupunkinsa portista; ja niin kaikki miehenpuolet, kaikki, jotka kulkivat hänen kaupunkinsa portista, ympärileikkauttivat itsensä.'),
(1669931,58,1,34,25,'Mutta kolmantena päivänä, kun he olivat kipeimmillään, Jaakobin kaksi poikaa, Simeon ja Leevi, Diinan veljet, ottivat kumpikin miekkansa ja hyökkäsivät, kenenkään aavistamatta, kaupunkiin ja tappoivat jokaisen miehenpuolen.'),
(1669932,58,1,34,26,'Myöskin Hamorin ja hänen poikansa Sikemin he tappoivat miekan terällä, ottivat Diinan Sikemin talosta ja menivät pois.'),
(1669933,58,1,34,27,'Ja Jaakobin pojat karkasivat haavoitettujen kimppuun ja ryöstivät kaupungin, sentähden että he olivat raiskanneet heidän sisarensa.'),
(1669934,58,1,34,28,'Ja he anastivat heidän pikkukarjansa ja raavaskarjansa ja aasinsa ja kaikki, mitä oli sekä kaupungissa että kedolla.'),
(1669935,58,1,34,29,'Ja kaikki heidän tavaransa, kaikki heidän lapsensa ja vaimonsa he veivät saaliinaan, ja he ryöstivät samoin kaiken muun, mitä taloissa oli.'),
(1669936,58,1,34,30,'Niin Jaakob sanoi Simeonille ja Leeville: "Te olette syösseet minut onnettomuuteen, saattaneet minut tämän maan asukkaiden, kanaanilaisten ja perissiläisten, vihoihin. Minun joukkoni on vähäinen; jos he kokoontuvat minua vastaan, niin he tuhoavat minut, ja niin minut ja minun sukuni hävitetään."'),
(1669937,58,1,34,31,'Mutta he vastasivat: "Pitikö hänen kohdella meidän sisartamme niinkuin porttoa!"'),
(1669938,58,1,35,1,'Ja Jumala sanoi Jaakobille: "Nouse, mene Beeteliin, asetu sinne ja rakenna sinne alttari Jumalalle, joka ilmestyi sinulle paetessasi veljeäsi Eesauta".'),
(1669939,58,1,35,2,'Niin Jaakob sanoi perheellensä ja kaikille, jotka olivat hänen kanssaan: "Poistakaa vieraat jumalat, joita teillä on keskuudessanne, puhdistautukaa ja muuttakaa vaatteenne.'),
(1669940,58,1,35,3,'Ja nouskaamme ja menkäämme Beeteliin, rakentaakseni sinne alttarin Jumalalle, joka kuuli minua ahdistukseni aikana ja oli minun kanssani tiellä, jota vaelsin."'),
(1669941,58,1,35,4,'Niin he jättivät Jaakobille kaikki vieraat jumalat, jotka olivat heidän hallussansa, sekä renkaat, jotka olivat heidän korvissaan, ja Jaakob kätki ne maahan tammen alle, joka oli Sikemissä.'),
(1669942,58,1,35,5,'Ja he lähtivät liikkeelle; ja Jumalan kauhu valtasi heidän ympärillään olevat kaupungit, niin etteivät nämä ajaneet takaa Jaakobin poikia.'),
(1669943,58,1,35,6,'Ja Jaakob saapui Luusiin, joka on Kanaanin maassa, se on Beeteliin, kaiken väen kanssa, joka oli hänen seurassaan.'),
(1669944,58,1,35,7,'Ja hän rakensi sinne alttarin ja nimitti paikan Eel-Beeteliksi, koska Jumala oli siellä ilmestynyt hänelle, silloin kun hän pakeni veljeään.'),
(1669945,58,1,35,8,'Mutta Debora, Rebekan imettäjä, kuoli, ja hänet haudattiin Beetelin alapuolelle tammen alle, ja se sai siitä nimen "Itkutammi".'),
(1669946,58,1,35,9,'Ja Jumala ilmestyi jälleen Jaakobille hänen palattuaan Mesopotamiasta ja siunasi hänet.'),
(1669947,58,1,35,10,'Ja Jumala sanoi hänelle: "Sinun nimesi on Jaakob; mutta älköön sinua enää kutsuttako Jaakobiksi, vaan nimesi olkoon Israel". - Niin hän sai nimen Israel.'),
(1669948,58,1,35,11,'Ja Jumala sanoi hänelle: "Minä olen Jumala, Kaikkivaltias; ole hedelmällinen ja lisäänny. Kansa, suuri kansojen joukko on sinusta tuleva, ja kuninkaita lähtee sinun kupeistasi.'),
(1669949,58,1,35,12,'Ja maan, jonka minä olen antanut Aabrahamille ja Iisakille, minä annan sinulle; myöskin sinun jälkeläisillesi minä annan sen maan."'),
(1669950,58,1,35,13,'Ja Jumala kohosi ylös hänen luotaan siitä paikasta, jossa hän oli häntä puhutellut.'),
(1669951,58,1,35,14,'Ja Jaakob pystytti patsaan siihen paikkaan, jossa hän oli häntä puhutellut, kivipatsaan, ja vuodatti juomauhrin sen päälle ja kaatoi öljyä sen päälle.'),
(1669952,58,1,35,15,'Ja Jaakob nimitti sen paikan, jossa Jumala oli häntä puhutellut, Beeteliksi.'),
(1669953,58,1,35,16,'Sitten he lähtivät liikkeelle Beetelistä. Ja kun vielä oli jonkun verran matkaa Efrataan, joutui Raakel synnytystuskiin, ja hänen synnytystuskansa olivat hyvin kovat.'),
(1669954,58,1,35,17,'Ja kun hänen synnytystuskansa olivat kovimmillaan, sanoi kätilövaimo hänelle: "Älä pelkää, sillä tälläkin kertaa sinä saat pojan".'),
(1669955,58,1,35,18,'Mutta kun hänen henkensä oli lähtemäisillään, sillä hänen oli kuoltava, antoi hän hänelle nimen Benoni, mutta hänen isänsä antoi hänelle nimen Benjamin.'),
(1669956,58,1,35,19,'Niin Raakel kuoli siellä, ja hänet haudattiin Efratan tien varteen, se on Beetlehemiin.'),
(1669957,58,1,35,20,'Ja Jaakob pystytti hänen haudalleen patsaan; tämä Raakelin hautapatsas on olemassa vielä tänäkin päivänä.'),
(1669958,58,1,35,21,'Ja Israel lähti liikkeelle sieltä ja pystytti telttansa tuolle puolen Karjatornia.'),
(1669959,58,1,35,22,'Ja tapahtui, kun Israel asui siinä maassa, että Ruuben meni ja makasi Bilhan, isänsä sivuvaimon, kanssa. Ja Israel sai sen kuulla.'),
(1669960,58,1,35,23,'Jaakobilla oli kaksitoista poikaa. Leean pojat olivat Ruuben, Jaakobin esikoinen, Simeon, Leevi, Juuda, Isaskar ja Sebulon.'),
(1669961,58,1,35,24,'Raakelin pojat olivat Joosef ja Benjamin.'),
(1669962,58,1,35,25,'Bilhan, Raakelin orjattaren, pojat olivat Daan ja Naftali.'),
(1669963,58,1,35,26,'Silpan, Leean orjattaren, pojat olivat Gaad ja Asser. Nämä ovat ne Jaakobin pojat, jotka syntyivät hänelle Mesopotamiassa.'),
(1669964,58,1,35,27,'Ja Jaakob saapui isänsä Iisakin luo Mamreen, Kirjat-Arbaan, se on Hebroniin, jossa Aabraham ja Iisak olivat asuneet muukalaisina.'),
(1669965,58,1,35,28,'Ja Iisakin elinaika oli sata kahdeksankymmentä vuotta.'),
(1669966,58,1,35,29,'Ja Iisak vaipui kuolemaan ja tuli otetuksi heimonsa tykö, vanhana ja elämästä kyllänsä saaneena. Ja hänen poikansa Eesau ja Jaakob hautasivat hänet.'),
(1669967,58,1,36,1,'Tämä on kertomus Eesaun, se on Edomin, suvusta.'),
(1669968,58,1,36,2,'Eesau otti vaimoikseen Kanaanin tyttäristä Aadan, heettiläisen Eelonin tyttären, ja Oholibaman, joka oli hivviläisen Sibonin pojan Anan tytär,'),
(1669969,58,1,36,3,'ja Baasematin, Ismaelin tyttären, Nebajotin sisaren.'),
(1669970,58,1,36,4,'Aada synnytti Eesaulle Elifaan, ja Baasemat synnytti Reguelin.'),
(1669971,58,1,36,5,'Ja Oholibama synnytti Jeuksen, Jalamin ja Koorahin. Nämä olivat Eesaun pojat, jotka syntyivät hänelle Kanaanin maassa.'),
(1669972,58,1,36,6,'Ja Eesau otti vaimonsa, poikansa ja tyttärensä ja kaiken talonväkensä, karjansa ja kaikki juhtansa ja kaiken tavaransa, jonka hän oli hankkinut Kanaanin maassa; ja hän lähti toiseen maahan, pois veljensä Jaakobin luota.'),
(1669973,58,1,36,7,'Sillä heidän omaisuutensa oli niin suuri, etteivät he voineet asua yhdessä, eikä se maa, jossa he asuivat muukalaisina, riittänyt heille heidän karjansa paljouden tähden.'),
(1669974,58,1,36,8,'Ja Eesau asettui Seirin vuoristoon, Eesau, se on Edom.'),
(1669975,58,1,36,9,'Ja tämä on kertomus edomilaisten isän Eesaun suvusta, hänen, joka asui Seirin vuoristossa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1669976,58,1,36,10,'Nämä ovat Eesaun poikien nimet: Elifas, Eesaun vaimon Aadan poika; Reguel, Eesaun vaimon Baasematin poika.'),
(1669977,58,1,36,11,'Ja Elifaan pojat olivat Teeman, Oomar, Sefo, Gaetam ja Kenas.'),
(1669978,58,1,36,12,'Mutta Timna oli Elifaan, Eesaun pojan, sivuvaimo, ja hän synnytti Elifaalle Amalekin. Nämä olivat Eesaun vaimon Aadan pojat.'),
(1669979,58,1,36,13,'Reguelin pojat olivat nämä: Nahat ja Serah, Samma ja Missa. Ne olivat Eesaun vaimon Baasematin pojat.'),
(1669980,58,1,36,14,'Mutta nämä olivat Eesaun vaimon Oholibaman, Sibonin pojan Anan tyttären, pojat, jotka hän synnytti Eesaulle: Jeus, Jalam ja Koorah.'),
(1669981,58,1,36,15,'Nämä olivat Eesaun poikien sukuruhtinaat: Elifaan, Eesaun esikoisen, pojat olivat ruhtinas Teeman, ruhtinas Oomar, ruhtinas Sefo, ruhtinas Kenas,'),
(1669982,58,1,36,16,'ruhtinas Koorah, ruhtinas Gaetam, ruhtinas Amalek. Nämä olivat ne ruhtinaat, jotka polveutuivat Elifaasta Edomin maassa; ne olivat Aadan pojat.'),
(1669983,58,1,36,17,'Ja nämä olivat Reguelin, Eesaun pojan, pojat: ruhtinas Nahat, ruhtinas Serah, ruhtinas Samma, ruhtinas Missa. Nämä olivat ne ruhtinaat, jotka polveutuivat Reguelista Edomin maassa; ne olivat Eesaun vaimon Baasematin pojat.'),
(1669984,58,1,36,18,'Ja nämä olivat Eesaun vaimon Oholibaman pojat: ruhtinas Jeus, ruhtinas Jalam, ruhtinas Koorah. Nämä olivat ne ruhtinaat, jotka polveutuivat Eesaun vaimosta, Anan tyttärestä Oholibamasta.'),
(1669985,58,1,36,19,'Nämä olivat Eesaun, se on Edomin, pojat, ja nämä heidän sukuruhtinaansa.'),
(1669986,58,1,36,20,'Mutta nämä olivat hoorilaisen Seirin pojat, sen maan alkuasukkaat: Lootan, Soobal, Sibon, Ana,'),
(1669987,58,1,36,21,'Diison, Eeser ja Diisan. Nämä olivat hoorilaisten sukuruhtinaat, Seirin pojat, Edomin maassa.'),
(1669988,58,1,36,22,'Mutta Lootanin pojat olivat Hoori ja Heemam; ja Lootanin sisar oli Timna.'),
(1669989,58,1,36,23,'Ja nämä olivat Soobalin pojat: Alvan, Maanahat ja Eebal, Sefo ja Oonam.'),
(1669990,58,1,36,24,'Nämä olivat Sibonin pojat: Aija ja Ana. Tämä oli se Ana, joka löysi ne lämpimät lähteet erämaassa, paimentaessaan isänsä Sibonin aaseja.'),
(1669991,58,1,36,25,'Ja nämä olivat Anan lapset: Diison ja Oholiba, Anan tytär.'),
(1669992,58,1,36,26,'Nämä olivat Diisonin pojat: Hemdan, Esban, Jitran ja Keran.'),
(1669993,58,1,36,27,'Nämä olivat Eeserin pojat: Bilhan, Saavan ja Akan.'),
(1669994,58,1,36,28,'Nämä olivat Diisanin pojat: Uus ja Aran.'),
(1669995,58,1,36,29,'Nämä olivat hoorilaisten sukuruhtinaat: ruhtinas Lootan, ruhtinas Soobal, ruhtinas Sibon, ruhtinas Ana,'),
(1669996,58,1,36,30,'ruhtinas Diison, ruhtinas Eeser, ruhtinas Diisan. Nämä olivat hoorilaisten sukuruhtinaat, ruhtinas ruhtinaalta, Seirin maassa.'),
(1669997,58,1,36,31,'Ja nämä olivat ne kuninkaat, jotka hallitsivat Edomin maassa, ennenkuin yksikään kuningas oli hallinnut israelilaisia:'),
(1669998,58,1,36,32,'Bela, Beorin poika, oli kuninkaana Edomissa, ja hänen kaupunkinsa nimi oli Dinhaba.'),
(1669999,58,1,36,33,'Kun Bela kuoli, tuli Joobab, Serahin poika, Bosrasta, kuninkaaksi hänen sijaansa.'),
(1670000,58,1,36,34,'Kun Joobab kuoli, tuli Huusam, teemanilaisten maasta, kuninkaaksi hänen sijaansa.'),
(1670001,58,1,36,35,'Kun Huusam kuoli, tuli Hadad, Bedadin poika, kuninkaaksi hänen sijaansa, hän, joka voitti midianilaiset Mooabin kedolla; ja hänen kaupunkinsa nimi oli Avit.'),
(1670002,58,1,36,36,'Kun Hadad kuoli, tuli Samla, Masrekasta, kuninkaaksi hänen sijaansa.'),
(1670003,58,1,36,37,'Kun Samla kuoli, tuli Saul, Rehobotista, virran varrelta, kuninkaaksi hänen sijaansa.'),
(1670004,58,1,36,38,'Kun Saul kuoli, tuli Baal-Haanan, Akborin poika, kuninkaaksi hänen sijaansa.'),
(1670005,58,1,36,39,'Kun Baal-Haanan, Akborin poika, kuoli, tuli Hadar kuninkaaksi hänen sijaansa, ja hänen kaupunkinsa nimi oli Paagu; ja hänen vaimonsa nimi oli Mehetabel, joka oli Matredin, Mee-Saahabin tyttären, tytär.'),
(1670006,58,1,36,40,'Ja nämä ovat Eesaun sukuruhtinasten nimet, heidän sukujensa, asuinpaikkojensa ja nimiensä mukaan: ruhtinas Timna, ruhtinas Alva, ruhtinas Jetet,'),
(1670007,58,1,36,41,'ruhtinas Oholibama, ruhtinas Eela, ruhtinas Piinon,'),
(1670008,58,1,36,42,'ruhtinas Kenas, ruhtinas Teeman, ruhtinas Mibsar,'),
(1670009,58,1,36,43,'ruhtinas Magdiel, ruhtinas Iiram. Nämä olivat Edomin sukuruhtinaat, heidän asuinsijojensa mukaan heidän perintömaassaan - Edomin, se on Eesaun, edomilaisten isän, sukuruhtinaat.'),
(1670010,58,1,37,1,'Mutta Jaakob asui siinä maassa, jossa hänen isänsä oli oleskellut muukalaisena, Kanaanin maassa.'),
(1670011,58,1,37,2,'Tämä on kertomus Jaakobin suvusta. Kun Joosef oli seitsemäntoista vuoden vanha, oli hän veljiensä kanssa lampaita paimentamassa; hän oli nuorukaisena isänsä vaimojen Bilhan ja Silpan poikien seurassa. Ja hän kertoi isälleen, mitä pahaa kuuli heistä puhuttavan.'),
(1670012,58,1,37,3,'Ja Israel rakasti Joosefia enemmän kuin kaikkia muita poikiansa, koska hän oli syntynyt hänelle hänen vanhalla iällänsä, ja hän teetti hänelle pitkäliepeisen, hihallisen ihokkaan.'),
(1670013,58,1,37,4,'Kun hänen veljensä näkivät, että heidän isänsä rakasti häntä enemmän kuin kaikkia hänen veljiänsä, vihasivat he häntä eivätkä voineet puhutella häntä ystävällisesti.'),
(1670014,58,1,37,5,'Kerran Joosef näki unen ja kertoi sen veljilleen; sen jälkeen he vihasivat häntä vielä enemmän.'),
(1670015,58,1,37,6,'Hän näet sanoi heille: "Kuulkaa, minkä unen minä olen nähnyt.'),
(1670016,58,1,37,7,'Katso, me olimme sitovinamme lyhteitä vainiolla, ja katso, minun lyhteeni nousi seisomaan, ja teidän lyhteenne asettuivat ympärille ja kumarsivat minun lyhdettäni."'),
(1670017,58,1,37,8,'Niin hänen veljensä sanoivat hänelle: "Sinäkö tulisit meidän kuninkaaksemme, sinäkö hallitsisit meitä?" Ja he vihasivat häntä vielä enemmän hänen uniensa ja puheidensa tähden.'),
(1670018,58,1,37,9,'Ja hän näki vielä toisenkin unen, jonka hän kertoi veljilleen ja sanoi: "Minä näin vielä unen: katso, aurinko ja kuu ja yksitoista tähteä kumarsivat minua".'),
(1670019,58,1,37,10,'Ja kun hän kertoi sen isälleen ja veljilleen, nuhteli hänen isänsä häntä ja sanoi hänelle: "Mikä uni se on, jonka sinä olet nähnyt? Olisiko minun ja äitisi ja veljiesi tultava kumartumaan sinun eteesi maahan?"'),
(1670020,58,1,37,11,'Ja hänen veljensä kadehtivat häntä; mutta hänen isänsä pani tämän mieleensä.'),
(1670021,58,1,37,12,'Kun hänen veljensä olivat menneet kaitsemaan isänsä lampaita Sikemiin,'),
(1670022,58,1,37,13,'sanoi Israel Joosefille: "Sinun veljesi ovat paimenessa Sikemissä; tule, minä lähetän sinut heidän luokseen". Hän vastasi: "Tässä olen".'),
(1670023,58,1,37,14,'Ja hän sanoi hänelle: "Mene katsomaan, kuinka veljesi ja karja voivat, ja kerro sitten minulle". Niin hän lähetti hänet matkalle Hebronin laaksosta, ja hän tuli Sikemiin.'),
(1670024,58,1,37,15,'Ja muuan mies kohtasi hänet, hänen harhaillessaan kedolla; ja mies kysyi häneltä: "Mitä etsit?"'),
(1670025,58,1,37,16,'Hän vastasi: "Minä etsin veljiäni; sano minulle, missä he ovat paimentamassa".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670026,58,1,37,17,'Mies vastasi: "He lähtivät pois täältä, sillä minä kuulin heidän sanovan: ''Menkäämme Dootaniin''." Niin Joosef meni veljiensä jäljissä ja löysi heidät Dootanista.'),
(1670027,58,1,37,18,'Kun he kaukaa näkivät hänet ja ennenkuin hän saapui heidän luokseen, pitivät he neuvoa tappaaksensa hänet.'),
(1670028,58,1,37,19,'He sanoivat toisillensa: "Katso, tuolla tulee se unennäkijä!'),
(1670029,58,1,37,20,'Tulkaa, tappakaamme nyt hänet ja heittäkäämme hänet johonkin kaivoon ja sanokaamme: villipeto on hänet syönyt. Saammepa sitten nähdä, mitä hänen unistaan tulee."'),
(1670030,58,1,37,21,'Kun Ruuben sen kuuli, tahtoi hän pelastaa hänet heidän käsistään ja sanoi: "Älkäämme lyökö häntä kuoliaaksi".'),
(1670031,58,1,37,22,'Vielä Ruuben sanoi heille: "Älkää vuodattako verta; heittäkää hänet tähän kaivoon, joka on täällä erämaassa, mutta älkää satuttako kättänne häneen". Hän näet tahtoi pelastaa hänet heidän käsistään, saattaaksensa hänet takaisin isänsä tykö.'),
(1670032,58,1,37,23,'Kun Joosef sitten tuli veljiensä luo, riisuivat he Joosefilta hänen ihokkaansa, pitkäliepeisen, hihallisen ihokkaan, joka oli hänen yllään,'),
(1670033,58,1,37,24,'ja ottivat hänet ja heittivät hänet kaivoon; mutta kaivo oli tyhjä, siinä ei ollut vettä.'),
(1670034,58,1,37,25,'Senjälkeen he istuivat aterioimaan. Ja kun he nostivat silmänsä, näkivät he ismaelilaismatkueen tulevan Gileadista; heidän kamelinsa kuljettivat kumihartsia, balsamia ja hajupihkaa, ja he olivat viemässä niitä Egyptiin.'),
(1670035,58,1,37,26,'Silloin Juuda sanoi veljillensä: "Mitä hyötyä meillä on siitä, että surmaamme veljemme ja salaamme hänen verensä?'),
(1670036,58,1,37,27,'Tulkaa, myykäämme hänet ismaelilaisille, mutta älköön kätemme sattuko häneen, sillä hän on meidän veljemme, meidän omaa lihaamme." Ja hänen veljensä kuulivat häntä.'),
(1670037,58,1,37,28,'Kun nyt midianilaiset kauppiaat menivät siitä ohitse, vetivät veljet Joosefin ylös kaivosta; ja he myivät Joosefin kahdestakymmenestä hopeasekelistä ismaelilaisille. Nämä veivät Joosefin Egyptiin.'),
(1670038,58,1,37,29,'Kun sitten Ruuben palasi kaivolle, niin Joosefia ei enää ollut kaivossa. Silloin hän repäisi vaatteensa,'),
(1670039,58,1,37,30,'palasi veljiensä luo ja sanoi: "Poika on kadonnut. Voi minua, minne minä joudun!"'),
(1670040,58,1,37,31,'Niin he ottivat Joosefin ihokkaan, teurastivat vuohipukin ja kastoivat ihokkaan vereen.'),
(1670041,58,1,37,32,'Sitten he lähettivät tuon pitkäliepeisen, hihallisen ihokkaan kotiin isälleen ja sanoivat: "Tämän me löysimme; tarkasta, onko se poikasi ihokas vai eikö".'),
(1670042,58,1,37,33,'Ja tarkastettuaan sen hän sanoi: "Tämä on minun poikani ihokas. Villipeto on hänet syönyt; totisesti, Joosef on raadeltu kuoliaaksi."'),
(1670043,58,1,37,34,'Ja Jaakob repäisi vaatteensa, pani säkin lanteilleen ja suri poikaansa pitkät ajat.'),
(1670044,58,1,37,35,'Ja kaikki hänen poikansa ja tyttärensä kävivät häntä lohduttamaan, mutta hän ei huolinut lohdutuksesta, vaan sanoi: "Murehtien minä menen tuonelaan poikani tykö". Ja hänen isänsä itki häntä.'),
(1670045,58,1,37,36,'Mutta midianilaiset myivät hänet Egyptiin Potifarille, joka oli faraon hoviherra ja henkivartijain päämies.'),
(1670046,58,1,38,1,'Siihen aikaan Juuda lähti pois veljiensä luota ja asettui erään Adullamissa asuvan miehen luo, jonka nimi oli Hiira.'),
(1670047,58,1,38,2,'Siellä Juuda näki Suua nimisen kanaanilaisen miehen tyttären, ja hän otti tämän luokseen ja yhtyi häneen.'),
(1670048,58,1,38,3,'Ja hän tuli raskaaksi ja synnytti pojan; ja hän antoi hänelle nimen Eer.'),
(1670049,58,1,38,4,'Ja taas hän tuli raskaaksi ja synnytti pojan ja antoi hänelle nimen Oonan.'),
(1670050,58,1,38,5,'Ja hän synnytti vieläkin pojan ja antoi hänelle nimen Seela; ja synnyttäessään hänet hän oli Kesibissä.'),
(1670051,58,1,38,6,'Ja Juuda otti Eerille, esikoisellensa, vaimon, jonka nimi oli Taamar.'),
(1670052,58,1,38,7,'Mutta Eer, Juudan esikoinen, ei ollut Herralle otollinen; sentähden Herra antoi hänen kuolla.'),
(1670053,58,1,38,8,'Niin Juuda sanoi Oonanille: "Yhdy veljesi leskeen ja ota hänet avioksesi ja herätä siemen veljellesi".'),
(1670054,58,1,38,9,'Mutta kun Oonan tiesi, ettei jälkeläinen olisi oleva hänen, niin hän antoi, aina kun yhtyi veljensä vaimoon, siemenensä mennä maahan, ettei hankkisi jälkeläistä veljelleen.'),
(1670055,58,1,38,10,'Mutta se, minkä hän teki, oli paha Herran silmissä; sentähden hän antoi hänenkin kuolla.'),
(1670056,58,1,38,11,'Silloin Juuda sanoi miniällensä Taamarille: "Asu leskenä isäsi talossa, kunnes poikani Seela joutuu täysikasvuiseksi". Hän näet ajatteli: "Kun ei vain tämäkin kuolisi niinkuin hänen veljensä". Niin Taamar meni pois ja jäi asumaan isänsä kotiin.'),
(1670057,58,1,38,12,'Pitkän aikaa sen jälkeen Suuan tytär, Juudan vaimo, kuoli. Suruajan mentyä Juuda lähti ystävänsä adullamilaisen Hiiran kanssa Timnaan lammastensa keritsiäisiin.'),
(1670058,58,1,38,13,'Niin tuotiin Taamarille tämä sanoma: "Katso, appesi menee Timnaan keritsemään lampaitaan".'),
(1670059,58,1,38,14,'Silloin hän riisui pois leskenvaatteensa ja verhoutui huntuun peittäytyen siihen ja istui Eenaimin portille, Timnaan vievän tien varteen. Sillä hän oli nähnyt, että vaikka Seela oli täysikasvuinen, ei häntä annettu hänelle vaimoksi.'),
(1670060,58,1,38,15,'Kun nyt Juuda näki hänet, luuli hän häntä portoksi; sillä hän oli peittänyt kasvonsa.'),
(1670061,58,1,38,16,'Ja hän poikkesi hänen luokseen tiepuoleen ja sanoi: "Anna minun yhtyä sinuun". Hän näet ei tiennyt, että nainen oli hänen miniänsä. Tämä vastasi: "Mitä annat minulle saadaksesi yhtyä minuun?"'),
(1670062,58,1,38,17,'Hän sanoi: "Lähetän sinulle vohlan laumastani". Nainen vastasi: "Annatko minulle pantin, kunnes sen lähetät?"'),
(1670063,58,1,38,18,'Hän sanoi: "Mitä on minun annettava sinulle pantiksi?" Hän vastasi: "Sinettisi, nauhasi ja sauvasi, joka on kädessäsi". Niin hän antoi ne hänelle ja yhtyi häneen, ja hän tuli hänestä raskaaksi.'),
(1670064,58,1,38,19,'Ja hän nousi ja meni sieltä ja pani pois huntunsa ja pukeutui leskenvaatteisiinsa.'),
(1670065,58,1,38,20,'Mutta Juuda lähetti adullamilaisen ystävänsä viemään vohlaa, saadaksensa takaisin pantin naiselta; mutta hän ei löytänyt häntä.'),
(1670066,58,1,38,21,'Ja hän kyseli sen paikkakunnan miehiltä ja sanoi: "Missä on se pyhäkköportto, joka istui Eenaimissa tien varressa?" He vastasivat: "Ei täällä ole ollut mitään pyhäkköporttoa".'),
(1670067,58,1,38,22,'Ja hän palasi Juudan luo ja sanoi: "En löytänyt häntä; ja myös sen paikkakunnan miehet sanoivat, ettei siellä ole ollutkaan mitään pyhäkköporttoa".'),
(1670068,58,1,38,23,'Silloin Juuda sanoi: "Pitäköön sen sitten, ettemme joutuisi häpeään. Katso, minä olen lähettänyt tämän vohlan, mutta sinä et ole löytänyt häntä."'),
(1670069,58,1,38,24,'Noin kolmen kuukauden kuluttua ilmoitettiin Juudalle: "Sinun miniäsi Taamar on harjoittanut haureutta, ja haureudesta hän on myös tullut raskaaksi". Juuda sanoi: "Viekää hänet poltettavaksi".'),
(1670070,58,1,38,25,'Mutta kun häntä vietiin, lähetti hän sanan apelleen sanoen: "Minä olen raskaana siitä miehestä, jonka nämä ovat". Ja hän käski sanoa: "Tarkasta, kenen tämä sinetti, nämä nauhat ja tämä sauva ovat".'),
(1670071,58,1,38,26,'Ja Juuda tunsi ne ja sanoi: "Hän on oikeassa minua vastaan, koska minä en antanut häntä pojalleni Seelalle". Ei hän kuitenkaan enää yhtynyt häneen.'),
(1670072,58,1,38,27,'Kun hänen synnyttämisensä aika tuli, katso, hänen kohdussaan oli kaksoiset.'),
(1670073,58,1,38,28,'Ja hänen synnyttäessään pisti toinen kätensä ulos; kätilövaimo otti punaista lankaa ja sitoi sen hänen käteensä ja sanoi: "Tämä tuli ensiksi ulos".'),
(1670074,58,1,38,29,'Mutta kun hän sitten taas veti kätensä takaisin, katso, silloin tuli hänen veljensä ulos; ja kätilövaimo sanoi: "Minkä repeämän oletkaan reväissyt itsellesi!" Ja hän sai nimen Peres.'),
(1670075,58,1,38,30,'Sitten tuli hänen veljensä, jonka kädessä oli punainen lanka; ja hän sai nimen Serah.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670076,58,1,39,1,'Ja Joosef vietiin Egyptiin, ja Potifar, egyptiläinen mies, joka oli faraon hoviherra ja henkivartijain päämies, osti hänet ismaelilaisilta, jotka olivat hänet sinne tuoneet.'),
(1670077,58,1,39,2,'Mutta Herra oli Joosefin kanssa, niin että hän menestyi kaikessa, ja hän oleskeli isäntänsä, egyptiläisen, talossa.'),
(1670078,58,1,39,3,'Ja hänen isäntänsä näki, että Herra oli hänen kanssaan ja että Herra antoi kaiken, mitä hän teki, menestyä hänen käsissään.'),
(1670079,58,1,39,4,'Niin Joosef saavutti hänen suosionsa ja sai palvella häntä. Ja hän asetti hänet talonsa hoitajaksi ja uskoi hänen haltuunsa kaikki, mitä hänellä oli.'),
(1670080,58,1,39,5,'Ja siitä ajasta lähtien, kun hän oli uskonut hänen hoitoonsa talonsa ja kaiken, mitä hänellä oli, Herra siunasi egyptiläisen taloa Joosefin tähden, ja Herran siunaus oli kaikessa, mitä hänellä oli kotona ja kedolla.'),
(1670081,58,1,39,6,'Niin hän jätti Joosefin haltuun kaikki, mitä hänellä oli, eikä hän itse välittänyt mistään, paitsi ruuasta, jota hän söi.'),
(1670082,58,1,39,7,'Mutta Joosefilla oli kaunis vartalo ja kauniit kasvot. Ja tapahtui jonkun ajan kuluttua, että hänen isäntänsä puoliso iski silmänsä Joosefiin ja sanoi: "Makaa minun kanssani".'),
(1670083,58,1,39,8,'Mutta hän kieltäytyi ja sanoi isäntänsä puolisolle: "Katso, isäntäni ei itse välitä mistään, mitä talossa on, vaan on uskonut minun haltuuni kaikki, mitä hänellä on.'),
(1670084,58,1,39,9,'Hänellä ei ole tässä talossa enemmän valtaa kuin minulla, eikä hän ole kieltänyt minulta mitään, paitsi sinut, koska olet hänen puolisonsa. Kuinka minä siis tekisin niin suuren pahanteon ja rikkoisin Jumalaa vastaan!"'),
(1670085,58,1,39,10,'Ja vaikka vaimo joka päivä puhui sellaista Joosefille, ei tämä suostunut makaamaan hänen vieressänsä eikä olemaan hänen kanssaan.'),
(1670086,58,1,39,11,'Mutta eräänä päivänä, kun Joosef tuli taloon toimittamaan askareitaan eikä ketään talonväestä ollut sisällä saapuvilla,'),
(1670087,58,1,39,12,'tarttui hän Joosefin vaippaan ja sanoi: "Makaa minun kanssani". Mutta tämä jätti vaippansa hänen käsiinsä, pakeni ja riensi ulos.'),
(1670088,58,1,39,13,'Kun hän nyt huomasi, että Joosef oli jättänyt vaippansa hänen käsiinsä ja paennut ulos,'),
(1670089,58,1,39,14,'huusi hän talonväkeään ja sanoi heille näin: "Katsokaa, hän on tuonut meille hebrealaisen miehen pitämään meitä pilkkanaan; tämä tuli luokseni maatakseen minun kanssani, mutta minä huusin kovalla äänellä.'),
(1670090,58,1,39,15,'Ja kun hän kuuli minun kirkaisevan ja huutavan, jätti hän vaippansa viereeni, pakeni ja riensi ulos."'),
(1670091,58,1,39,16,'Ja hän pani vaipan viereensä siksi, kunnes Joosefin isäntä tuli kotiin.'),
(1670092,58,1,39,17,'Ja hän puhui hänelle samalla tavalla, sanoen: "Tuo hebrealainen orja, jonka olet tuonut meille, tuli luokseni pitämään minua pilkkanaan;'),
(1670093,58,1,39,18,'mutta kun minä kirkaisin ja huusin, jätti hän vaippansa viereeni ja pakeni ulos".'),
(1670094,58,1,39,19,'Kun hänen isäntänsä kuuli puolisonsa kertovan ja sanovan: "Näin sinun orjasi on tehnyt minulle", syttyi hänen vihansa.'),
(1670095,58,1,39,20,'Ja Joosefin isäntä otti hänet ja pani hänet vankilaan, paikkaan, jossa kuninkaan vangit säilytettiin; ja hän jäi siihen vankilaan.'),
(1670096,58,1,39,21,'Mutta Herra oli Joosefin kanssa ja soi hänen saavuttaa suosiota ja päästä vankilan päällikön armoihin.'),
(1670097,58,1,39,22,'Ja vankilan päällikkö uskoi kaikki vangit, jotka vankilassa olivat, Joosefin haltuun. Ja kaikki, mitä siellä toimitettiin, tehtiin hänen toimestaan.'),
(1670098,58,1,39,23,'Eikä vankilan päällikkö ollenkaan valvonut sitä, mikä oli Joosefille uskottu, sillä Herra oli Joosefin kanssa. Ja Herra antoi menestyä sen, mitä hän teki.'),
(1670099,58,1,40,1,'Ja tapahtui jonkun ajan kuluttua, että Egyptin kuninkaan juomanlaskija ja leipoja rikkoivat herraansa, Egyptin kuningasta, vastaan.'),
(1670100,58,1,40,2,'Ja farao vihastui näihin kahteen hoviherraansa, ylimmäiseen juomanlaskijaan ja ylimmäiseen leipojaan,'),
(1670101,58,1,40,3,'ja panetti heidät vankeuteen henkivartijain päämiehen taloon, samaan vankilaan, jossa Joosef oli vankina.'),
(1670102,58,1,40,4,'Ja henkivartijain päämies antoi heille Joosefin heitä palvelemaan. Niin he olivat jonkun aikaa vankeudessa.'),
(1670103,58,1,40,5,'Ollessaan vankilassa vangittuina he molemmat, Egyptin kuninkaan juomanlaskija ja leipoja, näkivät samana yönä unta, kumpikin unensa, ja kummankin unella oli oma selityksensä.'),
(1670104,58,1,40,6,'Ja kun Joosef aamulla tuli heidän luokseen, huomasi hän heidät alakuloisiksi.'),
(1670105,58,1,40,7,'Silloin hän kysyi faraon hoviherroilta, jotka olivat hänen kanssansa vankeudessa hänen isäntänsä talossa: "Miksi te olette tänään niin murheellisen näköiset?"'),
(1670106,58,1,40,8,'He vastasivat hänelle: "Olemme kumpikin nähneet unen, eikä ole niiden selittäjää". Ja Joosef sanoi heille: "Unien selitykset ovat Jumalan; kertokaa kuitenkin minulle".'),
(1670107,58,1,40,9,'Niin ylimmäinen juomanlaskija kertoi unensa Joosefille ja sanoi hänelle: "Minä näin unta, ja katso, minun edessäni oli viinipuu;'),
(1670108,58,1,40,10,'viinipuussa oli kolme oksaa, ja samassa kun se alkoi versoa, sen kukat puhkesivat ja marjat sen rypäleissä kypsyivät.'),
(1670109,58,1,40,11,'Ja minulla oli faraon malja kädessäni, ja minä otin marjat ja pusersin niistä mehun faraon maljaan ja annoin maljan faraon käteen."'),
(1670110,58,1,40,12,'Ja Joosef sanoi hänelle: "Tämä on sen selitys: kolme oksaa merkitsee kolmea päivää.'),
(1670111,58,1,40,13,'Kolmen päivän kuluttua farao korottaa sinun pääsi ja asettaa sinut jälleen virkaasi. Ja sinä annat faraon maljan hänen käteensä niinkuin ennenkin, kun olit hänen juomanlaskijansa.'),
(1670112,58,1,40,14,'Mutta muista minua, kun sinun hyvin käy, ja tee minulle laupeus mainitsemalla minusta faraolle ja toimittamalla minut pois tästä talosta.'),
(1670113,58,1,40,15,'Sillä minut on varastettu hebrealaisten maasta, enkä minä ole täälläkään tehnyt mitään, mistä minut olisi tullut panna tähän vankikuoppaan."'),
(1670114,58,1,40,16,'Kun ylimmäinen leipoja näki, että Joosef antoi hyvän selityksen, sanoi hän hänelle: "Myöskin minä näin unen, ja katso, kolme nisuleipäkoria oli minun pääni päällä.'),
(1670115,58,1,40,17,'Ja ylimmässä korissa oli kaikenlaisia leivoksia faraon syötäväksi, mutta linnut söivät ne korista, joka oli minun pääni päällä."'),
(1670116,58,1,40,18,'Joosef vastasi ja sanoi: "Tämä on sen selitys: kolme koria merkitsee kolmea päivää.'),
(1670117,58,1,40,19,'Kolmen päivän kuluttua farao korottaa sinun pääsi ripustamalla sinut hirsipuuhun, ja taivaan linnut syövät sinun lihasi."'),
(1670118,58,1,40,20,'Kolmantena päivänä sen jälkeen, faraon syntymäpäivänä, tämä laittoi pidot kaikille palvelijoilleen. Silloin hän korotti palvelijainsa joukosta sekä ylimmäisen juomanlaskijan että ylimmäisen leipojan pään.'),
(1670119,58,1,40,21,'Ylimmäisen juomanlaskijan hän asetti hänen entiseen juomanlaskijan toimeensa, niin että hän sai antaa maljan faraon käteen;'),
(1670120,58,1,40,22,'mutta ylimmäisen leipojan hän hirtätti, niinkuin Joosef oli heille selityksessään sanonut.'),
(1670121,58,1,40,23,'Mutta ylimmäinen juomanlaskija ei muistanut Joosefia, vaan unhotti hänet.'),
(1670122,58,1,41,1,'Kahden vuoden kuluttua tapahtui, että farao näki unen; hän oli seisovinaan Niilivirran rannalla.'),
(1670123,58,1,41,2,'Ja katso, virrasta nousi seitsemän kaunista ja lihavaa lehmää, jotka kävivät laitumella kaislikossa.'),
(1670124,58,1,41,3,'Ja katso, niiden jälkeen nousi virrasta toiset seitsemän lehmää, rumia ja laihoja; ne asettuivat edellisten lehmien viereen virran rannalle.'),
(1670125,58,1,41,4,'Ja ne rumat ja laihat lehmät söivät ne seitsemän kaunista ja lihavaa lehmää. Siihen farao heräsi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670126,58,1,41,5,'Mutta hän nukkui uudestaan ja näki toisen kerran unta: seitsemän paksua ja kaunista tähkäpäätä kasvoi samassa oljessa.'),
(1670127,58,1,41,6,'Ja katso, niiden jälkeen kasvoi vielä seitsemän tähkäpäätä, ohutta ja itätuulen polttamaa.'),
(1670128,58,1,41,7,'Ja nämä ohuet tähkäpäät nielivät ne seitsemän paksua ja täyteläistä tähkäpäätä. Siihen farao heräsi, ja katso, se oli unta.'),
(1670129,58,1,41,8,'Mutta aamulla hänen mielensä oli levoton, ja hän kutsutti eteensä kaikki Egyptin tietäjät ja kaikki viisaat; ja farao kertoi heille unensa, mutta ei ollut sitä, joka olisi voinut selittää ne faraolle.'),
(1670130,58,1,41,9,'Silloin puhui ylimmäinen juomanlaskija faraolle sanoen: "Nyt minä muistan rikokseni.'),
(1670131,58,1,41,10,'Farao oli vihastunut palvelijoihinsa, ja hän pani minut vankeuteen henkivartijain päämiehen taloon, minut ja ylimmäisen leipojan.'),
(1670132,58,1,41,11,'Niin me molemmat, minä ja hän, näimme samana yönä unta; me näimme kumpikin unemme, jolla oli oma selityksensä.'),
(1670133,58,1,41,12,'Ja siellä oli meidän kanssamme hebrealainen nuorukainen, henkivartijain päämiehen palvelija. Hänelle me kerroimme unemme, ja hän selitti ne meille; hän selitti, mitä kummankin uni merkitsi.'),
(1670134,58,1,41,13,'Ja niinkuin hän meille oli selittänyt, niin kävikin: minut asetettiin entiseen virkaani, toinen hirtettiin."'),
(1670135,58,1,41,14,'Silloin farao kutsutti Joosefin eteensä. Ja hänet tuotiin kiiruusti vankikuopasta. Ja hän ajatti hiuksensa ja muutti vaatteensa ja tuli faraon eteen.'),
(1670136,58,1,41,15,'Ja farao sanoi Joosefille: "Minä olen nähnyt unen, eikä ole sen selittäjää, mutta olen kuullut kerrottavan sinusta, että kun kuulet unen, sinä voit sen selittää".'),
(1670137,58,1,41,16,'Joosef vastasi faraolle sanoen: "En minä; mutta Jumala antaa faraolle suotuisan vastauksen".'),
(1670138,58,1,41,17,'Ja farao puhui Joosefille: "Minä näin unen; olin seisovinani Niilivirran rannalla.'),
(1670139,58,1,41,18,'Ja katso, virrasta nousi seitsemän lihavaa ja kaunista lehmää, jotka kävivät laitumella kaislikossa.'),
(1670140,58,1,41,19,'Ja katso, niiden jälkeen nousi virrasta toiset seitsemän lehmää, kurjia, kovin rumia ja laihoja; en ole koko Egyptin maassa nähnyt niin rumia kuin ne.'),
(1670141,58,1,41,20,'Ja nämä laihat ja rumat lehmät söivät ne ensimmäiset, ne lihavat lehmät.'),
(1670142,58,1,41,21,'Mutta vaikka ne olivat nielleet nämä, ei voinut huomata, että ne olivat nielleet ne, vaan ne olivat yhtä rumannäköiset kuin ennenkin. Siihen minä heräsin.'),
(1670143,58,1,41,22,'Mutta taas minä näin unta: seitsemän täyteläistä ja kaunista tähkäpäätä kasvoi samassa oljessa.'),
(1670144,58,1,41,23,'Ja katso, niiden jälkeen kasvoi vielä seitsemän tähkäpäätä, kuivunutta, ohutta ja itätuulen polttamaa.'),
(1670145,58,1,41,24,'Ja nämä ohuet tähkäpäät nielivät ne seitsemän kaunista tähkäpäätä. Minä kerroin tämän tietäjille, mutta ei kukaan kyennyt sanomaan minulle, mitä se merkitsee."'),
(1670146,58,1,41,25,'Niin Joosef sanoi faraolle: "Faraon unet merkitsevät kumpikin samaa; Jumala on ilmaissut faraolle, mitä hän on tekevä.'),
(1670147,58,1,41,26,'Seitsemän kaunista lehmää merkitsee seitsemää vuotta, seitsemän kaunista tähkäpäätä merkitsee myös seitsemää vuotta; unilla on sama merkitys.'),
(1670148,58,1,41,27,'Ja seitsemän laihaa ja rumaa lehmää, jotka nousivat niiden jälkeen, merkitsee seitsemää vuotta, ja seitsemän tyhjää, itätuulen polttamaa tähkäpäätä merkitsee seitsemää nälkävuotta.'),
(1670149,58,1,41,28,'Tätä minä tarkoitin, kun sanoin faraolle: Jumala on antanut faraon nähdä, mitä hän on tekevä.'),
(1670150,58,1,41,29,'Katso, tulee seitsemän vuotta, jolloin on suuri viljavuus koko Egyptin maassa.'),
(1670151,58,1,41,30,'Mutta niitä seuraa seitsemän sellaista nälkävuotta, että Egyptin maan entinen viljavuus kokonaan unhottuu, ja nälänhätä tuottaa maalle häviön.'),
(1670152,58,1,41,31,'Eikä enää tiedetä mitään maassa vallinneesta viljavuudesta sitä seuraavan nälänhädän vuoksi, sillä se on oleva ylen kova.'),
(1670153,58,1,41,32,'Mutta että uni toistui faraolle, se tietää, että Jumala on asian varmasti päättänyt ja että Jumala antaa sen pian tapahtua.'),
(1670154,58,1,41,33,'Nyt valitkoon siis farao ymmärtäväisen ja taitavan miehen ja asettakoon hänet Egyptin hallitusmieheksi.'),
(1670155,58,1,41,34,'Näin tehköön farao: asettakoon päällysmiehiä maahan ja ottakoon viidennen osan Egyptin maan sadosta seitsemänä viljavuotena.'),
(1670156,58,1,41,35,'Ja koottakoon näinä hyvinä vuosina, jotka tulevat, kaikki niiden sato ja kasattakoon viljaa faraon haltuun, talletettakoon sato kaupunkeihin ja säilytettäköön,'),
(1670157,58,1,41,36,'niin että maalla on eloa säästössä seitsemän nälkävuoden varalle, jotka kohtaavat Egyptin maata. Niin ei maa joudu perikatoon nälänhädän aikana."'),
(1670158,58,1,41,37,'Tämä puhe miellytti faraota ja kaikkia hänen palvelijoitansa.'),
(1670159,58,1,41,38,'Ja farao sanoi palvelijoilleen: "Voisimmeko löytää ketään, jossa on Jumalan henki niinkuin tässä?"'),
(1670160,58,1,41,39,'Ja farao sanoi Joosefille: "Koska Jumala on sinulle ilmoittanut kaiken tämän, ei ole ketään niin ymmärtäväistä ja taitavaa, kuin sinä olet.'),
(1670161,58,1,41,40,'Hoida sinä minun taloani, ja sinun käskyäsi totelkoon kaikki minun kansani; ainoastaan valtaistuimen puolesta minä olen sinua korkeampi."'),
(1670162,58,1,41,41,'Ja farao sanoi Joosefille: "Katso, minä asetan sinut koko Egyptin maan hallitusmieheksi".'),
(1670163,58,1,41,42,'Ja farao otti sinettisormuksensa kädestään ja pani sen Joosefin käteen ja puetti hänen ylleen hienot pellavavaatteet ja ripusti kultakäädyt hänen kaulaansa.'),
(1670164,58,1,41,43,'Ja hän antoi hänen ajaa omissa, lähinnä parhaissa vaunuissaan, ja hänen edellään huudettiin: abrek! Niin asetettiin hänet koko Egyptin maan hallitusmieheksi.'),
(1670165,58,1,41,44,'Ja farao sanoi Joosefille: "Minä olen farao, mutta sinun tahtomattasi älköön kukaan nostako kättä tai jalkaa koko Egyptin maassa".'),
(1670166,58,1,41,45,'Ja farao nimitti Joosefin Saafenat-Paneahiksi ja antoi hänelle puolisoksi Aasenatin, Oonin papin Poti-Feran tyttären. Niin Joosef lähti tarkastamaan Egyptin maata.'),
(1670167,58,1,41,46,'Joosef oli kolmenkymmenen vuoden vanha, kun hän tuli faraon, Egyptin kuninkaan, palvelijaksi. Ja Joosef lähti faraon luota ja kulki läpi koko Egyptin maan.'),
(1670168,58,1,41,47,'Ja seitsemänä viljavuotena maa kasvoi ylen runsaasti.'),
(1670169,58,1,41,48,'Ja näinä seitsemänä hyvänä vuotena, jotka tulivat Egyptin maahan, hän kokosi kaikkea eloa ja talletti sen kaupunkeihin. Hän talletti kuhunkin kaupunkiin sen elon, joka tuotiin ympäristön vainioilta.'),
(1670170,58,1,41,49,'Niin Joosef kasasi viljaa niinkuin meren hiekkaa, ylen suuret määrät, siihen asti että lakattiin sitä mittaamasta, sillä se ei ollut enää mitattavissa.'),
(1670171,58,1,41,50,'Joosefille syntyi, ennenkuin nälkävuosi tuli, kaksi poikaa, jotka Aasenat, Oonin papin Poti-Feran tytär, synnytti hänelle.'),
(1670172,58,1,41,51,'Esikoiselle Joosef antoi nimen Manasse, "sillä", sanoi hän, "Jumala on saattanut minut unhottamaan kaikki vaivani ja koko isäni kodin".'),
(1670173,58,1,41,52,'Toiselle hän antoi nimen Efraim, "sillä", sanoi hän, "Jumala on tehnyt minut hedelmälliseksi kärsimysteni maassa".'),
(1670174,58,1,41,53,'Ne seitsemän viljavuotta, jotka tulivat Egyptin maahan, kuluivat loppuun.'),
(1670175,58,1,41,54,'Senjälkeen alkoi seitsemän nälkävuotta, niinkuin Joosef oli sanonut, ja tuli nälänhätä kaikkiin maihin, mutta Egyptin maassa oli leipäviljaa kaikkialla.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670176,58,1,41,55,'Mutta koko Egyptin maa näki nälkää, ja kansa huusi faraolta leipää. Silloin farao sanoi kaikille egyptiläisille: "Menkää Joosefin luo ja tehkää, mitä hän käskee teidän tehdä".'),
(1670177,58,1,41,56,'Kun nälkä ahdisti koko maata, avasi Joosef kaikki varastot ja myi viljaa egyptiläisille. Mutta nälänhätä tuli yhä kovemmaksi Egyptin maassa.'),
(1670178,58,1,41,57,'Ja kaikista maista tultiin Egyptiin Joosefin luo ostamaan viljaa, sillä kaikissa maissa oli kova nälänhätä.'),
(1670179,58,1,42,1,'Mutta kun Jaakob sai tietää, että Egyptissä oli viljaa, sanoi hän pojillensa: "Mitä epäröitte?"'),
(1670180,58,1,42,2,'Ja hän sanoi: "Katso, minä olen kuullut, että Egyptissä on viljaa. Menkää sinne ja ostakaa meille sieltä viljaa, että pysyisimme hengissä emmekä kuolisi."'),
(1670181,58,1,42,3,'Niin kymmenen Joosefin veljeä lähti ostamaan viljaa Egyptistä.'),
(1670182,58,1,42,4,'Mutta Benjaminia, Joosefin veljeä, Jaakob ei lähettänyt hänen veljiensä mukana, sillä hän pelkäsi, että häntä kohtaisi jokin onnettomuus.'),
(1670183,58,1,42,5,'Niin Israelin pojat tulivat muiden tulijain mukana ostamaan viljaa, sillä Kanaanin maassa oli nälänhätä.'),
(1670184,58,1,42,6,'Mutta Joosef oli vallanpitäjänä maassa; hän myi viljaa kaikelle maan kansalle. Niin Joosefin veljet tulivat ja kumartuivat hänen edessään kasvoilleen maahan.'),
(1670185,58,1,42,7,'Ja Joosef näki veljensä, ja hän tunsi heidät, mutta tekeytyi heille vieraaksi, puhutteli heitä ankarasti ja kysyi heiltä: "Mistä te tulette?" He vastasivat: "Kanaanin maasta tulemme, ostamaan elintarpeita".'),
(1670186,58,1,42,8,'Ja Joosef tunsi veljensä, mutta he eivät tunteneet häntä.'),
(1670187,58,1,42,9,'Silloin Joosef muisti unet, jotka hän oli nähnyt heistä, ja sanoi heille: "Te olette vakoojia; olette tulleet katsomaan, mistä maa olisi avoin".'),
(1670188,58,1,42,10,'He vastasivat hänelle: "Ei, herra; palvelijasi ovat tulleet ostamaan elintarpeita.'),
(1670189,58,1,42,11,'Me olemme kaikki saman miehen poikia, olemme rehellisiä miehiä; palvelijasi eivät ole vakoojia."'),
(1670190,58,1,42,12,'Mutta hän sanoi heille: "Ei ole niin, vaan te olette tulleet katsomaan, mistä maa olisi avoin".'),
(1670191,58,1,42,13,'He vastasivat: "Meitä, sinun palvelijoitasi, on kaksitoista veljestä, saman miehen poikia Kanaanin maasta; nuorin on nyt kotona isämme luona, ja yhtä ei enää ole".'),
(1670192,58,1,42,14,'Joosef sanoi heille: "Niin on, kuin olen teille puhunut: te olette vakoojia.'),
(1670193,58,1,42,15,'Näin te tulette koeteltaviksi: niin totta kuin farao elää, te ette pääse täältä lähtemään, ellei nuorin veljenne tule tänne.'),
(1670194,58,1,42,16,'Lähettäkää yksi joukostanne noutamaan veljenne tänne, mutta teidän muiden on jääminen tänne vangeiksi, että koeteltaisiin, oletteko puhuneet totta; muuten, niin totta kuin farao elää, te olette vakoojia."'),
(1670195,58,1,42,17,'Ja hän panetti heidät vankeuteen kolmeksi päiväksi.'),
(1670196,58,1,42,18,'Mutta kolmantena päivänä Joosef sanoi heille: "Jos tahdotte elää, niin tehkää näin, sillä minä olen Jumalaa pelkääväinen:'),
(1670197,58,1,42,19,'jos olette rehellisiä miehiä, niin jääköön yksi teistä, veljeksistä, vangiksi vankilaan, jossa teitä säilytettiin, mutta te muut menkää viemään kotiin viljaa perheittenne nälänhätään.'),
(1670198,58,1,42,20,'Ja tuokaa nuorin veljenne minun luokseni. Jos teidän puheenne siten todeksi vahvistuu, niin vältätte kuoleman." Ja heidän täytyi tehdä niin.'),
(1670199,58,1,42,21,'Mutta he sanoivat toinen toisellensa: "Totisesti, me olemme syylliset sen tähden, mitä teimme veljellemme; sillä me näimme hänen sielunsa tuskan, kun hän anoi meiltä armoa, emmekä kuulleet häntä. Sentähden on meille tullut tämä tuska."'),
(1670200,58,1,42,22,'Ruuben vastasi heille sanoen: "Enkö minä sanonut teille: ''Älkää tehkö pahoin nuorukaista vastaan!'' Mutta te ette kuulleet minua; katsokaa, nyt kostetaan hänen verensä."'),
(1670201,58,1,42,23,'Mutta he eivät tienneet, että Joosef ymmärsi heitä, sillä hän puhui heille tulkin kautta.'),
(1670202,58,1,42,24,'Ja hän kääntyi pois heistä ja itki. Sitten hän kääntyi taas heihin päin ja puhui heidän kanssaan. Ja hän otti heidän joukostaan Simeonin ja vangitutti hänet heidän nähtensä.'),
(1670203,58,1,42,25,'Ja Joosef käski täyttää heidän säkkinsä viljalla ja panna jokaisen rahat takaisin hänen säkkiinsä sekä antaa heille evästä matkalle. Ja heille tehtiin niin.'),
(1670204,58,1,42,26,'Ja he sälyttivät viljansa aasien selkään ja lähtivät sieltä.'),
(1670205,58,1,42,27,'Kun sitten eräs heistä yöpaikassa avasi säkkinsä syöttääkseen aasiansa, huomasi hän rahansa säkin suussa.'),
(1670206,58,1,42,28,'Hän sanoi veljilleen: "Minulle on annettu rahani takaisin; katso, se on minun säkissäni". Silloin heidän sydämensä vavahti, ja he katsoivat säikähtyneinä toisiinsa sanoen: "Mitä Jumala on meille tehnyt?"'),
(1670207,58,1,42,29,'Tultuansa isänsä Jaakobin luo Kanaanin maahan he ilmoittivat hänelle kaikki, mitä heille oli tapahtunut, ja sanoivat:'),
(1670208,58,1,42,30,'"Mies, joka on sen maan valtiaana, puhutteli meitä ankarasti ja kohteli meitä, niinkuin olisimme olleet maata vakoilemassa.'),
(1670209,58,1,42,31,'Mutta me sanoimme hänelle: ''Olemme rehellisiä miehiä emmekä mitään vakoojia;'),
(1670210,58,1,42,32,'meitä on kaksitoista veljestä, saman isän poikia; yhtä ei enää ole, ja nuorin on nyt kotona isämme luona Kanaanin maassa''.'),
(1670211,58,1,42,33,'Mutta mies, sen maan valtias, sanoi meille: ''Siitä minä saan tietää, oletteko rehellisiä miehiä: jättäkää yksi veljistänne minun luokseni; ottakaa sitten viljaa perheittenne nälänhätään.'),
(1670212,58,1,42,34,'Ja menkää ja tuokaa nuorin veljenne luokseni, saadakseni tietää, ettette ole vakoojia, vaan rehellisiä miehiä. Sitten minä annan teille veljenne takaisin, ja te saatte vapaasti liikkua maassa''."'),
(1670213,58,1,42,35,'Kun he sitten tyhjensivät säkkinsä, niin katso, kunkin rahakukkaro oli hänen säkissään; ja nähdessään rahakukkaronsa he sekä heidän isänsä peljästyivät.'),
(1670214,58,1,42,36,'Ja heidän isänsä Jaakob sanoi heille: "Te teette minut lapsettomaksi; Joosefia ei enää ole, Simeonia ei enää ole, ja Benjamininkin te tahdotte viedä minulta; kaikki tämä kohtaa minua".'),
(1670215,58,1,42,37,'Ruuben vastasi isälleen sanoen: "Saat surmata minun molemmat poikani, jos en tuo häntä sinulle takaisin; anna hänet minun huostaani, niin minä tuon hänet sinulle takaisin".'),
(1670216,58,1,42,38,'Mutta hän sanoi: "Ei minun poikani saa lähteä teidän kanssanne, sillä hänen veljensä on kuollut, ja hän on yksin jäljellä; jos onnettomuus kohtaa häntä matkalla, jolle aiotte lähteä, niin te saatatte minun harmaat hapseni vaipumaan murheella tuonelaan".'),
(1670217,58,1,43,1,'Mutta nälänhätä oli maassa kova.'),
(1670218,58,1,43,2,'Ja kun he olivat syöneet loppuun sen viljan, jonka olivat tuoneet Egyptistä, sanoi heidän isänsä heille: "Menkää jälleen ostamaan meille vähän elintarpeita".'),
(1670219,58,1,43,3,'Juuda vastasi hänelle sanoen: "Se mies teroitti meille teroittamalla: ''Ette saa tulla minun kasvojeni eteen, ellei veljenne ole teidän kanssanne''.'),
(1670220,58,1,43,4,'Jos annat veljemme seurata meidän mukanamme, niin me lähdemme ostamaan sinulle elintarpeita.'),
(1670221,58,1,43,5,'Mutta jos et anna, niin emme lähde; sillä se mies sanoi meille: ''Ette saa tulla minun kasvojeni eteen, ellei veljenne ole teidän kanssanne''."'),
(1670222,58,1,43,6,'Israel sanoi: "Minkätähden teitte niin pahasti minua kohtaan, että ilmaisitte tuolle miehelle teillä olevan vielä veljen?"'),
(1670223,58,1,43,7,'He vastasivat: "Mies kyseli tuiki tarkasti meitä ja meidän sukuamme, sanoen: ''Elääkö isänne vielä? Onko teillä vielä veljeä?'' Silloin me ilmoitimme hänelle, niinkuin asia on. Saatoimmeko tietää, että hän sanoisi: ''Tuokaa tänne veljenne''?"'),
(1670224,58,1,43,8,'Ja Juuda sanoi isällensä Israelille: "Anna nuorukaisen seurata minun mukanani, niin me nousemme ja lähdemme matkalle, että jäisimme eloon, sekä me että sinä ja vaimomme ja lapsemme, emmekä kuolisi.'),
(1670225,58,1,43,9,'Minä vastaan hänestä; minun kädestäni saat vaatia hänet. Jos en tuo häntä takaisin sinun luoksesi ja aseta häntä eteesi, niin minä olen syyllinen sinun edessäsi kaiken elinaikani.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670226,58,1,43,10,'Totisesti, jos emme olisi näin vitkastelleet, niin olisimme jo kaksikin kertaa voineet olla sieltä kotona."'),
(1670227,58,1,43,11,'Silloin heidän isänsä Israel sanoi heille: "Jos niin on, tehkää ainakin tämä: ottakaa säkkeihinne maan parhaimpia tuotteita ja viekää ne sille miehelle lahjaksi: vähän balsamia ja vähän hunajaa, kumihartsia ja hajupihkaa, pähkinöitä ja manteleita.'),
(1670228,58,1,43,12,'Ja ottakaa mukaanne kaksinkertainen raha, niin että viette takaisin sen rahan, joka palautettiin säkkienne suussa. Ehkä se oli erehdys.'),
(1670229,58,1,43,13,'Ottakaa sitten mukaanne myöskin veljenne ja nouskaa ja menkää jälleen sen miehen luo.'),
(1670230,58,1,43,14,'Jumala, Kaikkivaltias, suokoon, että se mies tekisi teille laupeuden ja antaisi toisen veljenne sekä Benjaminin palata kotiin teidän kanssanne. Mutta jos tulen lapsettomaksi, niin tulen lapsettomaksi."'),
(1670231,58,1,43,15,'Niin miehet ottivat mukaansa lahjan ja kaksinkertaisen rahan sekä myöskin Benjaminin ja nousivat ja menivät Egyptiin; ja he astuivat Joosefin eteen.'),
(1670232,58,1,43,16,'Kun Joosef näki Benjaminin heidän seurassaan, sanoi hän huoneenhaltijalleen: "Vie nämä miehet sisään; teurasta teuras ja valmista se, sillä miehet saavat syödä päivällistä minun kanssani".'),
(1670233,58,1,43,17,'Ja mies teki, niinkuin Joosef oli käskenyt, ja vei miehet Joosefin taloon.'),
(1670234,58,1,43,18,'Mutta miehet pelkäsivät, kun heitä vietiin Joosefin taloon, arvellen: "Sen rahan tähden, joka viime kerralla tuli takaisin meidän säkeissämme, ne nyt vievät meitä tänne hyökätäkseen ja karatakseen meidän kimppuumme, ottaakseen meidät orjiksi ja anastaakseen aasimme".'),
(1670235,58,1,43,19,'Niin he menivät Joosefin huoneenhaltijan luo ja puhuttelivat häntä talon ovella'),
(1670236,58,1,43,20,'ja sanoivat: "Oi kuule, herra, me olemme kerran ennen käyneet täällä ostamassa elintarpeita,'),
(1670237,58,1,43,21,'ja kun me tulimme yöpaikkaan ja avasimme säkkimme, niin katso, jokaisen raha oli hänen säkkinsä suussa täysipainoisena; olemme nyt tuoneet ne mukanamme takaisin.'),
(1670238,58,1,43,22,'Ja olemme tuoneet mukanamme toisenkin rahan ostaaksemme viljaa elatukseksemme. Emme tiedä, kuka on pannut meidän rahamme säkkeihimme."'),
(1670239,58,1,43,23,'Hän vastasi: "Olkaa rauhassa, älkää peljätkö. Teidän Jumalanne ja teidän isänne Jumala on antanut teidän löytää aarteen säkeistänne. Teidän rahanne minä olen saanut." Ja hän toi heidän luokseen Simeonin.'),
(1670240,58,1,43,24,'Ja hän vei miehet Joosefin taloon ja antoi heille vettä jalkain pesemiseksi ja heidän aaseilleen rehua.'),
(1670241,58,1,43,25,'He laittoivat lahjansa järjestykseen siksi, kunnes Joosef tulisi päivälliselle; sillä he olivat kuulleet, että saisivat aterioida siellä.'),
(1670242,58,1,43,26,'Kun Joosef oli tullut kotiin, veivät he hänelle huoneeseen lahjat, jotka heillä oli mukanaan, ja kumartuivat maahan hänen edessänsä.'),
(1670243,58,1,43,27,'Hän tervehti heitä ja kysyi: "Kuinka voi teidän vanha isänne, josta puhuitte? Vieläkö hän elää?"'),
(1670244,58,1,43,28,'He vastasivat: "Palvelijasi, meidän isämme, voi hyvin; hän elää vielä". Ja he kumartuivat ja heittäytyivät maahan.'),
(1670245,58,1,43,29,'Ja hän nosti silmänsä ja näki veljensä Benjaminin, äitinsä pojan, ja kysyi: "Onko tämä teidän nuorin veljenne, josta puhuitte?" Sitten hän sanoi: "Jumala olkoon sinulle, poikani, armollinen".'),
(1670246,58,1,43,30,'Mutta silloin Joosef keskeytti äkkiä puheensa, sillä nähdessään veljensä hän tuli sydämessään liikutetuksi ja etsi tilaisuutta itkeäkseen; niin hän meni sisähuoneeseen ja itki siellä.'),
(1670247,58,1,43,31,'Senjälkeen hän pestyään kasvonsa tuli ulos, hillitsi itsensä ja käski: "Tarjotkaa ruokaa".'),
(1670248,58,1,43,32,'Ja tarjottiin erikseen hänelle ja erikseen heille ja erikseen egyptiläisille, jotka aterioivat hänen kanssaan; egyptiläiset näet eivät saata syödä yhdessä hebrealaisten kanssa, sillä se on egyptiläisille kauhistus.'),
(1670249,58,1,43,33,'He istuivat vastapäätä häntä iän mukaan, esikoinen ensimmäisenä ja nuorin viimeisenä; ja ihmetellen miehet katselivat toisiaan.'),
(1670250,58,1,43,34,'Ja hän antoi kantaa omasta pöydästään ruokia heille, ja Benjaminin annos oli viisi kertaa suurempi kuin kaikkien muiden. Ja he joivat hänen kanssaan ja juopuivat.'),
(1670251,58,1,44,1,'Sen jälkeen Joosef käski huoneenhaltijaansa sanoen: "Täytä miesten säkit viljalla, niin paljon kuin he voivat kuljettaa, ja pane itsekunkin raha hänen säkkinsä suuhun.'),
(1670252,58,1,44,2,'Ja nuorimman säkin suuhun pane minun maljani, tuo hopeamalja, ynnä hänen viljarahansa." Ja hän teki, niinkuin Joosef käski.'),
(1670253,58,1,44,3,'Aamulla päivän valjetessa miehet saivat aaseinensa lähteä matkalle.'),
(1670254,58,1,44,4,'Mutta kun he olivat ehtineet vähän matkaa kaupungin ulkopuolelle, sanoi Joosef huoneenhaltijalleen: "Nouse ja aja miehiä takaa, ja kun saavutat heidät, sano heille: ''Minkätähden olette palkinneet hyvän pahalla?'),
(1670255,58,1,44,5,'Onhan se juuri se, josta isäntäni juo ja josta hän salaisia tiedustelee. Te olette pahoin tehneet menetellessänne näin.''"'),
(1670256,58,1,44,6,'Kun hän sitten saavutti heidät, puhui hän heille nämä sanat.'),
(1670257,58,1,44,7,'He vastasivat hänelle: "Minkätähden herramme puhuu näin? Pois se, että palvelijasi tekisivät niin!'),
(1670258,58,1,44,8,'Katso, rahan, jonka löysimme säkkiemme suusta, me olemme tuoneet takaisin sinulle Kanaanin maasta; kuinka siis olisimme varastaneet hopeata tai kultaa herrasi talosta?'),
(1670259,58,1,44,9,'Se palvelijoistasi, jolta se löydetään, kuolkoon; ja me muut tulemme herramme orjiksi."'),
(1670260,58,1,44,10,'Hän vastasi: "Olkoon niin, kuin olette puhuneet; se, jolta se löydetään, olkoon minun orjani. Mutta te muut pääsette vapaiksi."'),
(1670261,58,1,44,11,'Ja he laskivat nopeasti säkkinsä maahan, ja jokainen avasi säkkinsä.'),
(1670262,58,1,44,12,'Ja hän etsi, alkaen vanhimmasta ja lopettaen nuorimpaan, ja malja löytyi Benjaminin säkistä.'),
(1670263,58,1,44,13,'Silloin he repäisivät vaatteensa, kuormasivat kukin tavaransa aasinsa selkään ja palasivat kaupunkiin.'),
(1670264,58,1,44,14,'Ja Juuda meni veljinensä Joosefin taloon, jossa tämä vielä oli, ja he lankesivat maahan hänen eteensä.'),
(1670265,58,1,44,15,'Silloin Joosef sanoi heille: "Mitä olettekaan tehneet! Ettekö tienneet, että minun kaltaiseni mies saa salatut ilmi?"'),
(1670266,58,1,44,16,'Juuda vastasi: "Mitä sanoisimmekaan herralleni, mitä puhuisimme ja millä puolustautuisimme! Jumala on paljastanut palvelijaisi syyllisyyden. Katso, me olemme herrani orjat, niin hyvin me muut kuin se, jolta malja löytyi."'),
(1670267,58,1,44,17,'Hän sanoi: "Pois se, että minä tekisin niin! Se, jolta malja löytyi, olkoon minun orjani, mutta te muut menkää rauhassa kotiin isänne luo."'),
(1670268,58,1,44,18,'Silloin Juuda astui hänen eteensä ja sanoi: "Oi herrani, salli palvelijasi puhua sananen herrani kuullen, älköönkä vihasi syttykö palvelijaasi kohtaan, sillä sinä olet niinkuin itse farao!'),
(1670269,58,1,44,19,'Herrani kysyi palvelijoiltaan sanoen: ''Onko teillä isää tai veljeä?'''),
(1670270,58,1,44,20,'Me vastasimme herralleni: ''Meillä on kotona vanha isä ja veli, joka on syntynyt hänen vanhoilla päivillänsä ja on vielä nuori; mutta tämän veli on kuollut, ja niin hän on jäänyt yksin äidistänsä, ja hänen isänsä rakastaa häntä''.'),
(1670271,58,1,44,21,'Niin sinä sanoit palvelijoillesi: ''Tuokaa hänet tänne minun luokseni, että silmäni saisivat katsella häntä''.'),
(1670272,58,1,44,22,'Me vastasimme herralleni: ''Nuorukainen ei saata jättää isäänsä, sillä jos hän jättäisi isänsä, niin tämä kuolisi''.'),
(1670273,58,1,44,23,'Mutta sinä sanoit palvelijoillesi: ''Jos nuorin veljenne ei tule tänne teidän kanssanne, niin älkää enää näyttäytykö minun kasvojeni edessä''.'),
(1670274,58,1,44,24,'Ja me menimme kotiin palvelijasi, minun isäni, luo ja kerroimme hänelle herrani sanat.'),
(1670275,58,1,44,25,'Niin isämme sanoi: ''Menkää jälleen ostamaan meille vähän elintarpeita''.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670276,58,1,44,26,'Me sanoimme: ''Emme voi lähteä sinne; ainoastaan jos nuorin veljemme seuraa mukanamme, me lähdemme, sillä me emme voi näyttäytyä sen miehen kasvojen edessä, jollei nuorin veljemme ole mukanamme''.'),
(1670277,58,1,44,27,'Niin palvelijasi, minun isäni, sanoi meille: ''Tiedättehän itse, että vaimoni synnytti minulle kaksi poikaa.'),
(1670278,58,1,44,28,'Toinen lähti pois luotani, ja minä sanoin: Varmaan hänet on raadeltu kuoliaaksi, enkä minä ole häntä siitä päivin nähnyt.'),
(1670279,58,1,44,29,'Jos te nyt viette minulta tämänkin ja jos onnettomuus kohtaa häntä, niin te saatatte minun harmaat hapseni vaipumaan tuskalla tuonelaan.'''),
(1670280,58,1,44,30,'Jos minä siis tulisin kotiin palvelijasi, isäni, luo eikä meillä olisi mukanamme nuorukaista, johon hän on kaikesta sielustaan kiintynyt,'),
(1670281,58,1,44,31,'niin hän nähdessään, ettei nuorukainen ole kanssamme, kuolisi, ja me, sinun palvelijasi, saattaisimme palvelijasi, isämme, harmaat hapset vaipumaan murheella tuonelaan.'),
(1670282,58,1,44,32,'Sillä palvelijasi on luvannut isälleen vastata nuorukaisesta ja sanonut: ''Jos en tuo häntä takaisin luoksesi, niin minä olen syyllinen isäni edessä kaiken elinaikani''.'),
(1670283,58,1,44,33,'Ja jääköön siis palvelijasi herralleni orjaksi nuorukaisen sijaan, ja nuorukainen menköön kotiin veljiensä kanssa.'),
(1670284,58,1,44,34,'Sillä kuinka minä voisin mennä kotiin isäni luo, jollei nuorukainen olisi kanssani? En voisi nähdä sitä surkeutta, joka tulisi isäni osaksi."'),
(1670285,58,1,45,1,'Silloin Joosef ei voinut kauemmin hillitä itseään kaikkien niiden nähden, jotka seisoivat hänen ympärillään. Hän huusi: "Antakaa kaikkien mennä pois minun luotani!" Niin ei ollut ketään saapuvilla, kun Joosef ilmaisi itsensä veljilleen.'),
(1670286,58,1,45,2,'Ja hän purskahti ääneensä itkemään, niin että egyptiläiset ja faraon hoviväki sen kuulivat.'),
(1670287,58,1,45,3,'Ja Joosef sanoi veljilleen: "Minä olen Joosef. Vieläkö minun isäni elää?" Mutta hänen veljensä eivät voineet vastata hänelle, niin hämmästyksissään he olivat hänen edessään.'),
(1670288,58,1,45,4,'Mutta Joosef sanoi veljilleen: "Tulkaa tänne luokseni". Ja he tulivat. Niin hän sanoi: "Minä olen Joosef, teidän veljenne, jonka myitte Egyptiin.'),
(1670289,58,1,45,5,'Mutta älkää nyt olko murheissanne älkääkä pahoitelko sitä, että olette myyneet minut tänne, sillä Jumala on minut lähettänyt teidän edellänne pitääkseen teidät hengissä.'),
(1670290,58,1,45,6,'Kaksi vuotta on nyt nälänhätä ollut maassa, ja vielä on jäljellä viisi vuotta, joina ei kynnetä eikä eloa korjata.'),
(1670291,58,1,45,7,'Niin Jumala lähetti minut teidän edellänne säilyttääkseen teille jälkeläisiä maan päällä ja pitääkseen teidät hengissä, pelastukseksi monille.'),
(1670292,58,1,45,8,'Ette siis te ole lähettäneet minua tänne, vaan Jumala; hän asetti minut faraon neuvonantajaksi ja koko hänen hovinsa herraksi ja koko Egyptin maan valtiaaksi.'),
(1670293,58,1,45,9,'Menkää, rientäkää minun isäni tykö ja sanokaa hänelle: ''Näin sanoo poikasi Joosef: Jumala on asettanut minut koko Egyptin herraksi, tule luokseni, älä viivyttele!'),
(1670294,58,1,45,10,'Sinä saat asettua Goosenin maakuntaan ja olla minun läheisyydessäni, sinä ja sinun lapsesi ja lastesi lapset, pikkukarjasi ja raavaskarjasi, kaikki, mitä sinulla on.'),
(1670295,58,1,45,11,'Minä elätän sinua siellä - vielä on näet viisi nälkävuotta - niin ettet sinä eikä sinun perheesi eikä kukaan omaisistasi ole sortuva puutteeseen.'''),
(1670296,58,1,45,12,'Te näette omin silmin, ja myöskin veljeni Benjamin näkee, että minä itse teille puhun.'),
(1670297,58,1,45,13,'Kertokaa siis isällenne kaikesta siitä kunniasta, joka on tullut minun osakseni Egyptissä, ja kaikesta, mitä olette nähneet, ja rientäkää ja tuokaa isäni tänne."'),
(1670298,58,1,45,14,'Ja hän lankesi veljensä Benjaminin kaulaan ja itki, ja myöskin Benjamin itki hänen kaulassaan.'),
(1670299,58,1,45,15,'Ja hän suuteli kaikkia veljiään ja itki heidän rinnoillaan. Senjälkeen hänen veljensä puhelivat hänen kanssaan.'),
(1670300,58,1,45,16,'Kun sanoma siitä, että Joosefin veljet olivat saapuneet, kuului faraon hoviin, oli se faraon ja kaikkien hänen palvelijainsa mieleen.'),
(1670301,58,1,45,17,'Ja farao sanoi Joosefille: "Sano veljillesi: ''Tehkää näin: sälyttäkää kuormat juhtainne selkään ja lähtekää kotiin Kanaanin maahan,'),
(1670302,58,1,45,18,'ottakaa isänne ja perheenne ja tulkaa minun luokseni, niin minä annan teille parasta, mitä Egyptissä on, ja te saatte syödä maan lihavuudesta''.'),
(1670303,58,1,45,19,'Ja näin sinun on käskettävä heitä: ''Tehkää näin: ottakaa itsellenne vaunuja Egyptin maasta lapsianne ja vaimojanne varten ja tuokaa isänne ja tulkaa.'),
(1670304,58,1,45,20,'Älkää surko taloustavaroitanne, sillä mitä parasta on koko Egyptin maassa, se on oleva teidän omanne.''"'),
(1670305,58,1,45,21,'Israelin pojat tekivät niin, ja Joosef antoi heille vaunuja faraon käskyn mukaan sekä evästä matkaa varten.'),
(1670306,58,1,45,22,'Hän antoi kullekin heistä juhlapuvun, mutta Benjaminille hän antoi kolmesataa hopeasekeliä sekä viisi juhlapukua.'),
(1670307,58,1,45,23,'Samoin hän lähetti isälleen lahjaksi kymmenen aasia, jotka olivat kuormitetut Egyptin parhaimmilla tavaroilla, ja kymmenen aasintammaa, jotka kantoivat viljaa ja leipää sekä eväitä hänen isälleen matkaa varten.'),
(1670308,58,1,45,24,'Sitten hän päästi veljensä menemään ja sanoi heille: "Älkää riidelkö matkalla".'),
(1670309,58,1,45,25,'Niin he lähtivät Egyptistä ja tulivat isänsä Jaakobin luo Kanaanin maahan.'),
(1670310,58,1,45,26,'Ja he kertoivat hänelle ja sanoivat: "Joosef on vielä elossa ja on koko Egyptin maan valtias". Mutta hänen sydämensä pysyi kylmänä, sillä hän ei uskonut heitä.'),
(1670311,58,1,45,27,'Niin he kertoivat hänelle kaiken, mitä Joosef oli heille puhunut. Ja kun hän näki vaunut, jotka Joosef oli lähettänyt häntä tuomaan, niin elpyi heidän isänsä Jaakobin henki.'),
(1670312,58,1,45,28,'Ja Israel sanoi: "Nyt on minulla kyllin; poikani Joosef elää vielä, minä menen häntä katsomaan, ennenkuin kuolen".'),
(1670313,58,1,46,1,'Niin Israel lähti matkalle mukanaan kaikki, mitä hänellä oli. Ja kun hän saapui Beersebaan, uhrasi hän teurasuhreja isänsä Iisakin Jumalalle.'),
(1670314,58,1,46,2,'Ja Jumala puhui Israelille näyssä yöllä; hän sanoi: "Jaakob, Jaakob!" Tämä vastasi: "Tässä olen".'),
(1670315,58,1,46,3,'Niin hän sanoi: "Minä olen Jumala, sinun isäsi Jumala; älä pelkää mennä Egyptiin, sillä minä teen sinut siellä suureksi kansaksi.'),
(1670316,58,1,46,4,'Minä menen sinun kanssasi Egyptiin, ja minä myös johdatan sinut sieltä takaisin. Ja Joosefin käsi on sulkeva sinun silmäsi."'),
(1670317,58,1,46,5,'Ja Jaakob lähti Beersebasta, ja Israelin pojat nostivat isänsä Jaakobin, lapsensa ja vaimonsa vaunuihin, jotka farao oli lähettänyt häntä noutamaan.'),
(1670318,58,1,46,6,'Ja he ottivat karjansa ja tavaransa, jotka he olivat hankkineet Kanaanin maassa, ja tulivat niin Egyptiin, Jaakob ynnä kaikki hänen jälkeläisensä.'),
(1670319,58,1,46,7,'Poikansa ja poikiensa pojat, tyttärensä ja poikiensa tyttäret, kaikki jälkeläisensä, hän vei mukanaan Egyptiin.'),
(1670320,58,1,46,8,'Nämä ovat Israelin lasten nimet, niiden, jotka tulivat Egyptiin: Jaakob ja hänen poikansa. Jaakobin esikoinen oli Ruuben.'),
(1670321,58,1,46,9,'Ruubenin pojat olivat Hanok, Pallu, Hesron ja Karmi.'),
(1670322,58,1,46,10,'Simeonin pojat olivat Jemuel, Jaamin, Oohad, Jaakin, Soohar ja Saul, kanaanilaisen vaimon poika.'),
(1670323,58,1,46,11,'Leevin pojat olivat Geerson, Kehat ja Merari.'),
(1670324,58,1,46,12,'Juudan pojat olivat Eer, Oonan, Seela, Peres ja Serah; mutta Eer ja Oonan kuolivat Kanaanin maassa. Pereksen pojat olivat Hesron ja Haamul.'),
(1670325,58,1,46,13,'Isaskarin pojat olivat Toola, Puvva, Joob ja Simron.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670326,58,1,46,14,'Sebulonin pojat olivat Sered, Eelon ja Jahleel.'),
(1670327,58,1,46,15,'Nämä olivat Leean pojat; ne hän synnytti Jaakobille Mesopotamiassa sekä tyttären Diinan. Näitä Jaakobin poikia ja tyttäriä oli kaikkiaan kolmekymmentä kolme henkeä.'),
(1670328,58,1,46,16,'Gaadin pojat olivat Sifjon ja Haggi, Suuni ja Esbon, Eeri ja Arodi ja Areli.'),
(1670329,58,1,46,17,'Asserin pojat olivat Jimna, Jisva, Jisvi ja Beria; heidän sisarensa oli Serah. Berian pojat olivat Heber ja Malkiel.'),
(1670330,58,1,46,18,'Nämä olivat Silpan lapset, hänen, jonka Laaban antoi tyttärellensä Leealle, ja hän synnytti ne Jaakobille, kuusitoista henkeä.'),
(1670331,58,1,46,19,'Raakelin, Jaakobin vaimon, pojat olivat Joosef ja Benjamin.'),
(1670332,58,1,46,20,'Ja pojat, jotka syntyivät Joosefille Egyptin maassa, olivat Manasse ja Efraim; nämä synnytti hänelle Aasenat, Oonin papin Poti-Feran tytär.'),
(1670333,58,1,46,21,'Benjaminin pojat olivat Bela, Beker ja Asbel, Geera ja Naaman, Eehi ja Roos, Muppim ja Huppim ja Ard.'),
(1670334,58,1,46,22,'Nämä olivat Raakelin pojat, jotka syntyivät Jaakobille, kaikkiaan neljätoista henkeä.'),
(1670335,58,1,46,23,'Daanin poika oli Husim.'),
(1670336,58,1,46,24,'Naftalin pojat olivat Jahseel, Guuni, Jeeser ja Sillem.'),
(1670337,58,1,46,25,'Nämä olivat Bilhan pojat, hänen, jonka Laaban antoi tyttärellensä Raakelille, ja hän synnytti ne Jaakobille, kaikkiaan seitsemän henkeä.'),
(1670338,58,1,46,26,'Kaikkiaan oli niitä, jotka Jaakobin kanssa siirtyivät Egyptiin ja olivat lähteneet hänen kupeistansa, paitsi Jaakobin miniöitä, yhteensä kuusikymmentä kuusi henkeä.'),
(1670339,58,1,46,27,'Ja Joosefin poikia, jotka syntyivät hänelle Egyptissä, oli kaksi. Jaakobin perheen jäseniä, jotka siirtyivät Egyptiin, oli kaikkiaan seitsemänkymmentä henkeä.'),
(1670340,58,1,46,28,'Ja hän lähetti Juudan edellänsä Joosefin luo ilmoittamaan hänelle tulostaan Gooseniin. Niin he tulivat Goosenin maakuntaan.'),
(1670341,58,1,46,29,'Ja Joosef valjastutti vaununsa ja meni isäänsä Israelia vastaan Gooseniin. Ja kun hän saapui hänen eteensä, lankesi hän hänen kaulaansa ja itki kauan hänen kaulassaan.'),
(1670342,58,1,46,30,'Ja Israel sanoi Joosefille: "Nyt minä kuolen mielelläni, kun olen nähnyt sinun kasvosi ja tiedän, että sinä vielä elät".'),
(1670343,58,1,46,31,'Sen jälkeen Joosef sanoi veljilleen ja isänsä perheelle: "Minä menen ilmoittamaan faraolle ja sanon hänelle: ''Minun veljeni ja minun isäni perhe, jotka ovat olleet Kanaanin maassa, ovat saapuneet luokseni.'),
(1670344,58,1,46,32,'Ja nämä miehet ovat paimenia, sillä he hoitavat karjaa; ja he ovat tuoneet mukanaan lampaansa, karjansa ja kaiken muun omaisuutensa.'''),
(1670345,58,1,46,33,'Kun siis farao kutsuu teidät eteensä ja kysyy: ''Mikä teidän ammattinne on?'''),
(1670346,58,1,46,34,'niin vastatkaa: ''Me, sinun palvelijasi, olemme hoitaneet karjaa nuoruudestamme tähän asti, me niinkuin meidän isämmekin'' - että saisitte asettua Goosenin maakuntaan. Sillä kaikki paimenet ovat egyptiläisille kauhistus."'),
(1670347,58,1,47,1,'Ja Joosef meni ja ilmoitti faraolle, sanoen: "Minun isäni ja veljeni ovat pikkukarjoineen ja raavaskarjoineen, kaikkine omaisuuksineen, tulleet Kanaanin maasta, ja katso, he ovat Goosenin maakunnassa".'),
(1670348,58,1,47,2,'Ja hän oli ottanut mukaansa veljiensä joukosta viisi miestä; ne hän toi faraon eteen.'),
(1670349,58,1,47,3,'Niin farao kysyi hänen veljiltänsä: "Mikä on teidän ammattinne?" He vastasivat faraolle: "Me, sinun palvelijasi, olemme paimenia, me niinkuin isämmekin".'),
(1670350,58,1,47,4,'Ja he sanoivat vielä faraolle: "Me olemme tulleet asuaksemme jonkun aikaa tässä maassa; sillä palvelijoillasi ei ollut laidunta karjalleen, koska kova nälänhätä on Kanaanin maassa. Suo siis palvelijaisi asettua Goosenin maakuntaan."'),
(1670351,58,1,47,5,'Niin farao sanoi Joosefille: "Isäsi ja veljesi ovat tulleet sinun luoksesi.'),
(1670352,58,1,47,6,'Egyptin maa on avoinna sinun edessäsi; sijoita isäsi ja veljesi maan parhaaseen osaan. Asukoot Goosenin maakunnassa; ja jos tiedät heidän joukossaan olevan kelvollisia miehiä, niin aseta heidät minun karjani päällysmiehiksi."'),
(1670353,58,1,47,7,'Senjälkeen Joosef toi isänsä Jaakobin sisään ja esitti hänet faraolle. Ja Jaakob toivotti faraolle siunausta.'),
(1670354,58,1,47,8,'Niin farao kysyi Jaakobilta: "Kuinka monta ikävuotta sinulla on?"'),
(1670355,58,1,47,9,'Jaakob vastasi faraolle: "Minun vaellusaikani on kestänyt sata kolmekymmentä vuotta. Vähät ja pahat ovat olleet minun elinvuosieni päivät eivätkä ole saavuttaneet sitä elinvuosien määrää, mikä isilläni oli vaelluksensa aikana."'),
(1670356,58,1,47,10,'Ja Jaakob toivotti faraolle siunausta ja lähti hänen luotaan.'),
(1670357,58,1,47,11,'Ja Joosef sijoitti isänsä ja veljensä Egyptin maahan ja antoi heille maaomaisuutta maan parhaasta osasta, Ramseksen maakunnasta, niinkuin farao oli hänen käskenyt tehdä.'),
(1670358,58,1,47,12,'Ja Joosef elätti isäänsä ja veljiänsä ja koko isänsä perhettä antamalla jokaiselle elatusta vaimojen ja lasten luvun mukaan.'),
(1670359,58,1,47,13,'Mutta ei missään koko maassa ollut leipää; sillä nälänhätä oli hyvin kova, niin että Egyptin maa ja Kanaanin maa olivat nääntymässä nälkään.'),
(1670360,58,1,47,14,'Ja viljalla, jota ostettiin, Joosef kokosi kaiken rahan, mitä oli Egyptin maassa ja Kanaanin maassa; ja Joosef vei rahat faraon hoviin.'),
(1670361,58,1,47,15,'Kun raha oli loppunut Egyptin maasta ja Kanaanin maasta, tulivat kaikki egyptiläiset Joosefin luo, sanoen: "Anna meille leipää. Miksi me kuolisimme sinun silmiesi edessä? Sillä raha on loppunut."'),
(1670362,58,1,47,16,'Joosef vastasi: "Tuokaa tänne karjanne. Minä annan teille leipää karjastanne, jos rahanne on loppunut."'),
(1670363,58,1,47,17,'Ja he toivat Joosefille karjansa, ja Joosef antoi heille leipää hevosista, lampaista, raavaskarjasta ja aaseista. Niin hän sen vuoden elätti heitä leivällä kaiken heidän karjansa hinnasta.'),
(1670364,58,1,47,18,'Niin kului se vuosi. Seuraavana vuonna he tulivat taas hänen luoksensa ja sanoivat hänelle: "Emme tahdo salata herraltamme, että raha on lopussa, ja myöskin eläimemme ovat joutuneet herramme omiksi; meillä ei ole muuta jäljellä annettavana herrallemme kuin ruumiimme ja peltomme.'),
(1670365,58,1,47,19,'Miksi me menehtyisimme sinun silmiesi edessä, sekä me itse että meidän peltomme? Osta meidät ja peltomme leivällä, niin me tulemme peltoinemme faraon orjiksi. Anna meille siementä, että eläisimme emmekä kuolisi eivätkä peltomme joutuisi autioiksi."'),
(1670366,58,1,47,20,'Niin Joosef osti faraolle kaikki Egyptin pellot; sillä egyptiläiset myivät jokainen vainionsa, koska nälkä ahdisti heitä. Niin joutui maa faraon omaksi.'),
(1670367,58,1,47,21,'Ja hän siirsi kansan kaupunkeihin, Egyptin toisesta äärestä toiseen saakka.'),
(1670368,58,1,47,22,'Ainoastaan pappien peltoja hän ei ostanut; sillä papeilla oli määrätyt tulot faraolta ja he elivät niistä määrätyistä tuloistaan, jotka he faraolta saivat. Sentähden heidän ei tarvinnut myydä peltojansa.'),
(1670369,58,1,47,23,'Ja Joosef sanoi kansalle: "Katso, minä olen nyt ostanut teidät ja teidän peltonne faraolle; katso, tässä on teille siementä, kylväkää peltonne.'),
(1670370,58,1,47,24,'Mutta sadosta teidän on annettava viides osa faraolle; mutta neljä viidettä osaa jääköön teille pellon siemeneksi sekä ravinnoksi itsellenne ja niille, jotka talossanne ovat, sekä elatukseksi vaimoillenne ja lapsillenne."'),
(1670371,58,1,47,25,'He vastasivat: "Sinä olet pitänyt meidät hengissä; suo meidän vain saada armo herramme silmien edessä, niin olemme faraon orjia".'),
(1670372,58,1,47,26,'Niin Joosef teki sen säädökseksi, joka vielä tänäkin päivänä on voimassa Egyptin pelloista, että faraolle on annettava viides osa. Ainoastaan pappien pellot eivät joutuneet faraon omiksi.'),
(1670373,58,1,47,27,'Niin Israel jäi asumaan Egyptiin, Goosenin maakuntaan; he asettuivat sinne ja olivat hedelmällisiä ja lisääntyivät suuresti.'),
(1670374,58,1,47,28,'Ja Jaakob eli Egyptin maassa seitsemäntoista vuotta, ja koko hänen elinaikansa oli sata neljäkymmentä seitsemän vuotta.'),
(1670375,58,1,47,29,'Kun lähestyi aika, jolloin Israelin oli kuoltava, kutsui hän poikansa Joosefin ja sanoi hänelle: "Jos olen saanut armon sinun silmiesi edessä, niin pane nyt kätesi minun kupeeni alle ja osoita minulle laupeus ja uskollisuus: älä hautaa minua Egyptiin,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670376,58,1,47,30,'sillä minä tahdon levätä isieni luona; vie siis minut Egyptistä ja hautaa minut heidän hautaansa". Hän vastasi: "Minä teen, niinkuin sanot".'),
(1670377,58,1,47,31,'Hän sanoi: "Vanno se minulle". Ja hän vannoi hänelle. Silloin Israel rukoili, kumartuneena vuoteensa päänalaista vasten.'),
(1670378,58,1,48,1,'Tämän jälkeen tuotiin Joosefille sana: "Katso, isäsi on sairaana". Ja hän otti mukaansa molemmat poikansa, Manassen ja Efraimin.'),
(1670379,58,1,48,2,'Ja Jaakobille ilmoitettiin ja sanottiin: "Katso, poikasi Joosef on tullut sinun luoksesi". Niin Israel kokosi voimansa ja nousi istumaan vuoteessaan.'),
(1670380,58,1,48,3,'Ja Jaakob sanoi Joosefille: "Jumala, Kaikkivaltias, ilmestyi minulle Luusissa Kanaanin maassa ja siunasi minut'),
(1670381,58,1,48,4,'ja sanoi minulle: ''Katso, minä teen sinut hedelmälliseksi ja annan sinun lisääntyä, annan tulla sinusta suuren kansojen joukon, ja minä annan sinun jälkeläisillesi tämän maan ikuiseksi perintömaaksi''.'),
(1670382,58,1,48,5,'Kaksi poikaasi, jotka ovat sinulle syntyneet Egyptin maassa, ennenkuin minä tulin luoksesi Egyptiin, olkoot minun omani; Efraim ja Manasse olkoot minun omani niinkuin Ruuben ja Simeon.'),
(1670383,58,1,48,6,'Mutta ne lapsesi, jotka ovat syntyneet sinulle heidän jälkeensä, olkoot sinun; nimitettäköön heitä veljiensä nimellä heidän perintöosassaan.'),
(1670384,58,1,48,7,'Palatessani Mesopotamiasta kuoli minulta Raakel matkalla Kanaanissa, kun vielä oli jonkun verran matkaa Efrataan; ja minä hautasin hänet siellä Efratan" - se on Beetlehemin - "tien varteen".'),
(1670385,58,1,48,8,'Kun nyt Israel huomasi Joosefin pojat, kysyi hän: "Keitä nämä ovat?"'),
(1670386,58,1,48,9,'Joosef vastasi isälleen: "Ne ovat minun poikani, jotka Jumala on minulle täällä antanut". Hän sanoi: "Tuo heidät minun luokseni siunatakseni heidät".'),
(1670387,58,1,48,10,'Mutta Israelin silmät olivat vanhuudesta hämärät, niin ettei hän voinut nähdä. Niin Joosef toi heidät hänen luokseen, ja hän suuteli heitä ja syleili heitä.'),
(1670388,58,1,48,11,'Ja Israel sanoi Joosefille: "En olisi uskonut saavani nähdä sinun kasvojasi; ja katso, Jumala on suonut minun nähdä sinun jälkeläisiäsikin".'),
(1670389,58,1,48,12,'Ja Joosef otti heidät pois hänen polviltansa ja kumartui maahan kasvoilleen.'),
(1670390,58,1,48,13,'Sitten Joosef tarttui heihin molempiin, Efraimiin oikealla kädellänsä, vasemmalla Israelista, ja Manasseen vasemmalla kädellänsä, oikealla Israelista, ja toi heidät niin hänen eteensä.'),
(1670391,58,1,48,14,'Mutta Israel ojensi oikean kätensä ja laski sen Efraimin pään päälle, vaikka tämä oli nuorempi, ja vasemman kätensä Manassen pään päälle; hän pani siis kätensä ristikkäin, sillä Manasse oli esikoinen.'),
(1670392,58,1,48,15,'Ja hän siunasi Joosefin sanoen: "Jumala, jonka kasvojen edessä minun isäni Aabraham ja Iisak ovat vaeltaneet, Jumala, joka on minua kainnut syntymästäni hamaan tähän päivään asti,'),
(1670393,58,1,48,16,'enkeli, joka on minut pelastanut kaikesta pahasta, siunatkoon näitä nuorukaisia; heitä mainittaessa mainittakoon minun nimeni ja minun isieni Aabrahamin ja Iisakin nimi, ja he lisääntykööt suuresti keskellä maata".'),
(1670394,58,1,48,17,'Mutta kun Joosef huomasi, että hänen isänsä laski oikean kätensä Efraimin pään päälle, pani hän sen pahakseen ja tarttui isänsä käteen siirtääkseen sen Efraimin pään päältä Manassen pään päälle.'),
(1670395,58,1,48,18,'Ja Joosef sanoi isälleen: "Ei niin, isäni, sillä tämä on esikoinen; pane oikea kätesi hänen päänsä päälle".'),
(1670396,58,1,48,19,'Mutta hänen isänsä epäsi ja sanoi: "Kyllä tiedän, poikani, kyllä tiedän; hänestäkin on tuleva kansa, hänkin on tuleva suureksi, mutta hänen nuorempi veljensä on kuitenkin tuleva häntä suuremmaksi, ja hänen jälkeläisistään on tuleva kansan paljous".'),
(1670397,58,1,48,20,'Ja niin hän siunasi heidät sinä päivänä, sanoen: "Sinun nimelläsi siunataan Israelissa, sanotaan: Jumala tehköön sinut Efraimin ja Manassen kaltaiseksi". Niin hän asetti Efraimin Manassen edelle.'),
(1670398,58,1,48,21,'Ja Israel sanoi Joosefille: "Katso, minä kuolen, mutta Jumala on teidän kanssanne ja vie teidät takaisin isienne maahan.'),
(1670399,58,1,48,22,'Ja lisäksi siihen, minkä veljesi saavat, minä annan sinulle vuorenharjanteen, jonka olen miekallani ja jousellani ottanut amorilaisilta."'),
(1670400,58,1,49,1,'Sitten Jaakob kutsui poikansa ja sanoi: "Kokoontukaa, niin minä ilmoitan teille, mitä teille päivien lopulla tapahtuu.'),
(1670401,58,1,49,2,'Tulkaa kokoon ja kuulkaa, Jaakobin pojat, kuulkaa isäänne Israelia.'),
(1670402,58,1,49,3,'Ruuben, sinä olet minun esikoiseni, minun voimani ja minun miehuuteni ensimmäinen, ensi sijalla arvossa, ensi sijalla vallassa.'),
(1670403,58,1,49,4,'Mutta sinä kuohahdat kuin vesi, et pysy ensi sijalla, sillä sinä nousit isäsi leposijalle; silloin sinä sen saastutit. Niin, hän nousi vuoteeseeni.'),
(1670404,58,1,49,5,'Simeon ja Leevi, veljekset, heidän aseensa ovat väkivallan aseet.'),
(1670405,58,1,49,6,'Heidän neuvoonsa ei suostu minun sieluni, heidän seuraansa ei yhdy minun sydämeni; sillä vihassaan he murhasivat miehiä, omavaltaisuudessaan he silpoivat härkiä.'),
(1670406,58,1,49,7,'Kirottu olkoon heidän vihansa, sillä se on raju, heidän kiukkunsa, sillä se on julma. Minä jakelen heidät Jaakobin sekaan ja hajotan heidät Israelin sekaan.'),
(1670407,58,1,49,8,'Juuda, sinua sinun veljesi ylistävät; sinun kätesi on vihollistesi niskassa, sinua kumartavat isäsi pojat.'),
(1670408,58,1,49,9,'Juuda on nuori leijona; saaliilta olet, poikani, noussut. Hän on asettunut makaamaan, hän lepää kuin leijona, kuin naarasleijona - kuka uskaltaa häntä häiritä?'),
(1670409,58,1,49,10,'Ei siirry valtikka pois Juudalta eikä hallitsijansauva hänen polviensa välistä, kunnes tulee hän, jonka se on ja jota kansat tottelevat.'),
(1670410,58,1,49,11,'Hän sitoo aasinsa viinipuuhun, viiniköynnökseen aasinsa varsan; hän huuhtoo vaatteensa viinissä; viittansa rypäleen veressä.'),
(1670411,58,1,49,12,'Hänen silmänsä ovat viinistä sameat, hänen hampaansa valkeat maidosta.'),
(1670412,58,1,49,13,'Sebulon asuu meren rannalla, laivojen rannikolla, hänen sivunsa on Siidoniin päin.'),
(1670413,58,1,49,14,'Isaskar on luiseva aasi, joka loikoilee karjatarhojen välissä.'),
(1670414,58,1,49,15,'Hän huomasi lepopaikkansa suloiseksi ja maan ihanaksi; niin hän taivutti olkansa taakan alle ja joutui työveroa tekemään.'),
(1670415,58,1,49,16,'Daan hankkii oikeutta kansalleen, hänkin yhtenä Israelin sukukunnista.'),
(1670416,58,1,49,17,'Daan on käärmeenä tiellä, on polulla kyynä, joka puree hevosta vuohiseen, niin että ratsastaja syöksyy selin maahan.'),
(1670417,58,1,49,18,'Sinulta minä odotan pelastusta, Herra.'),
(1670418,58,1,49,19,'Gaadia ahdistavat rosvojoukot, mutta hän itse ahdistaa heitä heidän kintereillään.'),
(1670419,58,1,49,20,'Asserista tulee lihavuus, hänen leipänsä, hän tarjoaa kuninkaan herkkuja.'),
(1670420,58,1,49,21,'Naftali on nopea peura; hän antaa kauniita sanoja.'),
(1670421,58,1,49,22,'Joosef on nuori hedelmäpuu, nuori hedelmäpuu lähteen reunalla; sen oksat ulottuvat yli muurin.'),
(1670422,58,1,49,23,'Jousimiehet hätyyttävät häntä, ampuvat ja ahdistavat häntä.'),
(1670423,58,1,49,24,'Mutta hänen jousensa pysyy lujana, ja hänen käsivartensa ovat notkeat Jaakobin Väkevän avulla, kaitsijan, Israelin kallion,'),
(1670424,58,1,49,25,'isäsi Jumalan, avulla, joka sinua auttakoon, Kaikkivaltiaan avulla, joka sinua siunatkoon, antakoon siunauksia taivaasta ylhäältä, siunauksia syvyydestä alhaalta, siunauksia nisistä ja kohdusta.'),
(1670425,58,1,49,26,'Sinun isäsi siunaukset kohoavat yli minun vanhempaini siunausten, yli ikuisten kukkulain ihanuuden. Ne laskeutukoot Joosefin pään päälle, veljiensä ruhtinaan päälaelle.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670426,58,1,49,27,'Benjamin on raatelevainen susi; aamulla hän syö riistaa, ja illalla hän jakaa saalista."'),
(1670427,58,1,49,28,'Nämä ovat kaikki Israelin sukukunnat, luvultaan kaksitoista, ja tämän puhui heille heidän isänsä siunatessaan heidät; hän siunasi jokaisen erikseen erityisellä siunauksella.'),
(1670428,58,1,49,29,'Ja hän käski heitä ja sanoi heille: "Minut otetaan pois heimoni tykö; haudatkaa minut isieni viereen, siihen luolaan, joka on heettiläisen Efronin vainiolla,'),
(1670429,58,1,49,30,'luolaan, joka on Makpelan vainiolla, itään päin Mamresta Kanaanin maassa, jonka vainion Aabraham osti heettiläiseltä Efronilta perintöhaudakseen.'),
(1670430,58,1,49,31,'Siihen on haudattu Aabraham ja hänen vaimonsa Saara, siihen on haudattu Iisak ja hänen vaimonsa Rebekka, ja siihen minäkin hautasin Leean,'),
(1670431,58,1,49,32,'siihen vainioon, joka luolineen on ostettu heettiläisiltä."'),
(1670432,58,1,49,33,'Kun Jaakob oli antanut määräyksensä pojilleen, veti hän jalkansa vuoteeseen ja kuoli ja tuli otetuksi heimonsa tykö.'),
(1670433,58,1,50,1,'Ja Joosef vaipui isänsä kasvoja vasten, itki siinä kumartuneena hänen ylitsensä ja suuteli häntä.'),
(1670434,58,1,50,2,'Sitten Joosef käski lääkäreitä, jotka olivat hänen palveluksessaan, balsamoimaan hänen isänsä, ja lääkärit balsamoivat Israelin.'),
(1670435,58,1,50,3,'Siihen kului neljäkymmentä päivää, sillä niin pitkä aika kuluu balsamoimiseen. Ja egyptiläiset itkivät häntä seitsemänkymmentä päivää.'),
(1670436,58,1,50,4,'Sittenkuin hänen muistoksensa vietetty suruaika oli päättynyt, puhui Joosef faraon hoviväelle: "Jos olen saanut armon teidän silmienne edessä, niin puhukaa minun puolestani faraolle näin:'),
(1670437,58,1,50,5,'Isäni vannotti minua sanoen: ''Katso, minä kuolen, hautaa minut omaan hautaani, jonka olen kaivanut itselleni Kanaanin maassa''. Anna minun siis nyt mennä hautaamaan isäni; sitten palaan takaisin."'),
(1670438,58,1,50,6,'Farao vastasi: "Mene hautaamaan isäsi sen valan mukaan, jonka olet hänelle vannonut".'),
(1670439,58,1,50,7,'Niin Joosef meni hautaamaan isäänsä, ja hänen kanssaan menivät kaikki faraon palvelijat, hänen hovinsa vanhimmat ja kaikki Egyptin maan vanhimmat'),
(1670440,58,1,50,8,'sekä koko Joosefin perhe, hänen veljensä ja hänen isänsä perhe; ainoastaan vaimonsa, lapsensa, pikkukarjansa ja raavaskarjansa he jättivät Goosenin maakuntaan;'),
(1670441,58,1,50,9,'hänen mukanaan meni myös sekä vaunuja että ratsumiehiä. Ja niin heitä oli sangen suuri joukko.'),
(1670442,58,1,50,10,'Kun he saapuivat Gooren-Aatadiin, joka on Jordanin tuolla puolella, panivat he siellä toimeen ylen suuret ja juhlalliset valittajaiset, ja hän vietti isänsä surujuhlaa seitsemän päivää.'),
(1670443,58,1,50,11,'Ja kun maan asukkaat, kanaanilaiset, näkivät surujuhlan Gooren-Aatadissa, sanoivat he: "Siellä on egyptiläisillä suuri surujuhla". Siitä sai paikka nimekseen Aabel-Misraim; se on Jordanin tuolla puolella.'),
(1670444,58,1,50,12,'Ja hänen poikansa tekivät hänelle, niinkuin hän oli määrännyt heille:'),
(1670445,58,1,50,13,'hänen poikansa veivät hänet Kanaanin maahan ja hautasivat hänet Makpelan vainiolla olevaan luolaan, jonka vainion Aabraham oli ostanut perintöhaudaksi heettiläiseltä Efronilta ja joka oli itään päin Mamresta.'),
(1670446,58,1,50,14,'Senjälkeen kuin Joosef oli haudannut isänsä, palasi hän Egyptiin, hän ja hänen veljensä sekä kaikki, jotka hänen kanssaan olivat menneet hautaamaan hänen isäänsä.'),
(1670447,58,1,50,15,'Mutta kun Joosefin veljet näkivät, että heidän isänsä oli kuollut, ajattelivat he: "Ehkä Joosef nyt alkaa vainota meitä ja kostaa meille kaiken sen pahan, mitä me olemme hänelle tehneet".'),
(1670448,58,1,50,16,'Niin he lähettivät Joosefille tämän sanan: "Isäsi käski ennen kuolemaansa ja sanoi:'),
(1670449,58,1,50,17,'''Sanokaa Joosefille näin: Oi, anna anteeksi veljiesi rikos ja synti, sillä pahasti he ovat menetelleet sinua kohtaan''. Anna siis isäsi Jumalan palvelijoille anteeksi heidän rikoksensa." Ja Joosef itki kuullessaan nämä heidän sanansa.'),
(1670450,58,1,50,18,'Sitten tulivat Joosefin veljet itse, lankesivat maahan hänen eteensä ja sanoivat: "Katso, me olemme sinun orjiasi!"'),
(1670451,58,1,50,19,'Mutta Joosef vastasi heille: "Älkää peljätkö, olenko minä Jumalan sijassa?'),
(1670452,58,1,50,20,'Te tosin hankitsitte minua vastaan pahaa, mutta Jumala on kääntänyt sen hyväksi, että hän saisi aikaan sen, mikä nyt on tapahtunut, ja pitäisi hengissä paljon kansaa.'),
(1670453,58,1,50,21,'Älkää siis peljätkö; minä elätän teidät ja teidän vaimonne ja lapsenne." Ja hän lohdutti ja rauhoitti heitä.'),
(1670454,58,1,50,22,'Ja Joosef sekä hänen isänsä perhe jäivät asumaan Egyptiin. Ja Joosef eli sadan kymmenen vuoden vanhaksi.'),
(1670455,58,1,50,23,'Ja Joosef sai nähdä Efraimin lapsia kolmanteen polveen; myöskin Maakirista, Manassen pojasta, syntyi lapsia Joosefin polville.'),
(1670456,58,1,50,24,'Niin Joosef sanoi veljilleen: "Minä kuolen, mutta Jumala pitää huolen teistä ja johdattaa teidät tästä maasta siihen maahan, jonka hän valalla vannoen on luvannut Aabrahamille, Iisakille ja Jaakobille".'),
(1670457,58,1,50,25,'Ja Joosef vannotti Israelin poikia sanoen: "Kun Jumala pitää huolen teistä, viekää silloin minun luuni täältä".'),
(1670458,58,2,1,1,'Nämä ovat Egyptiin tulleiden Israelin poikien nimet; Jaakobin kanssa he olivat itsekukin perheineen tulleet sinne:'),
(1670459,58,2,1,2,'Ruuben, Simeon, Leevi ja Juuda,'),
(1670460,58,2,1,3,'Isaskar, Sebulon ja Benjamin,'),
(1670461,58,2,1,4,'Daan, Naftali, Gaad ja Asser.'),
(1670462,58,2,1,5,'Ja Jaakobin kupeista lähteneitä oli kaikkiaan seitsemänkymmentä henkeä. Mutta Joosef oli jo ennestään Egyptissä.'),
(1670463,58,2,1,6,'Ja Joosef kuoli ja kaikki hänen veljensä ynnä koko se sukupolvi.'),
(1670464,58,2,1,7,'Mutta israelilaiset olivat hedelmälliset ja sikisivät, lisääntyivät ja enenivät hyvin suurilukuisiksi, niin että maa tuli heitä täyteen.'),
(1670465,58,2,1,8,'Niin Egyptiin tuli uusi kuningas, joka ei Joosefista mitään tiennyt.'),
(1670466,58,2,1,9,'Tämä sanoi kansallensa: "Katso, israelilaisten kansa on suurempi ja väkevämpi kuin me.'),
(1670467,58,2,1,10,'Tulkaa, menetelkäämme siis viisaasti heitä kohtaan, että he eivät lisääntyisi eivätkä, jos sota syttyisi, liittyisi hekin vihollisiimme ja sotisi meitä vastaan ja lähtisi maasta pois."'),
(1670468,58,2,1,11,'Niin heille asetettiin työnjohtajia rasittamaan heitä raskaalla työllä. Ja heidän täytyi rakentaa faraolle varastokaupungit Piitom ja Ramses.'),
(1670469,58,2,1,12,'Mutta kuta enemmän kansaa rasitettiin, sitä enemmän se lisääntyi, ja sitä enemmän se levisi, niin että israelilaisia ruvettiin pelkäämään.'),
(1670470,58,2,1,13,'Niin egyptiläiset pitivät israelilaisia orjantyössä väkivalloin'),
(1670471,58,2,1,14,'ja katkeroittivat heidän elämänsä kovalla laasti- ja tiilityöllä ja kaikenlaisella työllä ulkona kedolla, kaikenlaisella työllä, jota he teettivät heillä väkivalloin.'),
(1670472,58,2,1,15,'Ja Egyptin kuningas puhui hebrealaisille kätilövaimoille, joista toisen nimi oli Sifra ja toisen Puua;'),
(1670473,58,2,1,16,'ja hän sanoi: "Kun te autatte hebrealaisia vaimoja heidän synnyttäessänsä, niin tarkastakaa lapsen sukupuoli: jos se on poika, surmatkaa se, mutta jos se on tyttö, jääköön eloon".'),
(1670474,58,2,1,17,'Mutta kätilövaimot pelkäsivät Jumalaa eivätkä tehneet, niinkuin Egyptin kuningas oli heille sanonut, vaan antoivat poikalasten elää.'),
(1670475,58,2,1,18,'Niin Egyptin kuningas kutsui kätilövaimot ja sanoi heille: "Miksi te näin teette ja annatte poikalasten elää?"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670476,58,2,1,19,'Kätilövaimot vastasivat faraolle: "Hebrealaiset vaimot eivät ole niinkuin egyptiläiset. He ovat voimakkaita; ennenkuin kätilövaimo tulee heidän luoksensa, ovat he jo synnyttäneet."'),
(1670477,58,2,1,20,'Mutta Jumala salli kätilövaimojen menestyä, ja kansa lisääntyi ja eneni suurilukuiseksi.'),
(1670478,58,2,1,21,'Ja koska kätilövaimot pelkäsivät Jumalaa, niin hän antoi heille runsaasti perhettä.'),
(1670479,58,2,1,22,'Niin farao antoi käskyn kaikelle kansallensa, sanoen: "Kaikki poikalapset, jotka syntyvät, heittäkää Niilivirtaan, mutta kaikkien tyttölasten antakaa elää".'),
(1670480,58,2,2,1,'Niin eräs mies, joka oli Leevin sukua, meni ja nai leeviläisen neidon.'),
(1670481,58,2,2,2,'Ja vaimo tuli raskaaksi ja synnytti pojan. Ja kun hän näki, että se oli ihana lapsi, salasi hän sitä kolme kuukautta.'),
(1670482,58,2,2,3,'Mutta kun hän ei voinut sitä enää salata, otti hän kaisla-arkun, siveli sen maapihkalla ja piellä, pani lapsen siihen ja laski sen kaislikkoon Niilivirran rantaan.'),
(1670483,58,2,2,4,'Ja lapsen sisar asettui taammaksi nähdäksensä, mitä hänelle tapahtuisi.'),
(1670484,58,2,2,5,'Silloin faraon tytär tuli alas peseytymään virrassa, ja hänen seuranaisensa kävelivät virran rannalla; ja kun hän näki arkun kaislikossa, lähetti hän palvelijattarensa ja otatti sen ylös.'),
(1670485,58,2,2,6,'Ja kun hän avasi sen, näki hän lapsen; ja katso, siinä oli poikanen, joka itki. Niin hänen tuli sitä sääli, ja hän sanoi: "Tämä on hebrealaisten lapsia".'),
(1670486,58,2,2,7,'Niin lapsen sisar sanoi faraon tyttärelle: "Menenkö kutsumaan sinulle hebrealaisen imettäjän, joka voi imettää sen lapsen sinulle?"'),
(1670487,58,2,2,8,'Faraon tytär vastasi hänelle: "Mene!" Niin tyttö meni ja kutsui lapsen äidin.'),
(1670488,58,2,2,9,'Ja faraon tytär sanoi hänelle: "Ota tämä lapsi ja imetä se minulle, niin minä maksan sinulle siitä palkan". Ja vaimo otti lapsen ja imetti sen.'),
(1670489,58,2,2,10,'Mutta kun lapsi oli kasvanut, toi hän sen faraon tyttärelle, ja tämä otti sen pojaksensa ja antoi hänelle nimen Mooses, sillä hän sanoi: "Minä olen vetänyt hänet ylös vedestä".'),
(1670490,58,2,2,11,'Ja tapahtui niihin aikoihin, kun Mooses oli kasvanut suureksi, että hän meni veljiensä luo ja näki heidän raskaan työnsä. Ja hän näki egyptiläisen miehen lyövän hebrealaista miestä, erästä hänen veljistään.'),
(1670491,58,2,2,12,'Silloin hän katseli ympärillensä joka taholle, ja kun hän näki, ettei ketään ollut läheisyydessä, löi hän egyptiläisen kuoliaaksi ja kätki hänet hiekkaan.'),
(1670492,58,2,2,13,'Ja hän meni toisena päivänä ulos ja näki kaksi hebrealaista miestä tappelemassa keskenään; ja hän sanoi syylliselle: "Miksi lyöt toveriasi?"'),
(1670493,58,2,2,14,'Tämä vastasi: "Kuka on asettanut sinut meidän päämieheksemme ja tuomariksemme? Aiotko tappaa minutkin, niinkuin tapoit egyptiläisen?" Silloin Mooses peljästyi ja ajatteli: "Se on siis tullut ilmi".'),
(1670494,58,2,2,15,'Ja kun farao sai kuulla tästä tapahtumasta, etsi hän Moosesta tappaaksensa hänet. Mutta Mooses lähti faraota pakoon ja pysähtyi Midianin maahan ja istahti eräälle kaivolle.'),
(1670495,58,2,2,16,'Ja Midianin papilla oli seitsemän tytärtä; nämä tulivat vettä ammentamaan ja täyttivät vesikaukalot, juottaakseen isänsä lampaita.'),
(1670496,58,2,2,17,'Mutta paimenet tulivat ja ajoivat heidät pois. Silloin Mooses nousi ja auttoi heitä ja juotti heidän lampaansa.'),
(1670497,58,2,2,18,'Ja kun he tulivat isänsä Reguelin luo, kysyi hän: "Kuinka te tänä päivänä niin pian jouduitte?"'),
(1670498,58,2,2,19,'He vastasivat: "Egyptiläinen mies auttoi meitä paimenten käsistä, ammensipa vielä vettäkin meille ja juotti lampaat".'),
(1670499,58,2,2,20,'Ja hän sanoi tyttärillensä: "Missä hän on? Miksi te niin jätitte miehen? Kutsukaa hänet aterioimaan meidän kanssamme."'),
(1670500,58,2,2,21,'Ja Mooses suostui asumaan sen miehen luona, ja hän antoi Moosekselle tyttärensä Sipporan vaimoksi.'),
(1670501,58,2,2,22,'Tämä synnytti pojan, ja Mooses antoi hänelle nimen Geersom; sillä hän sanoi: "Minä olen muukalainen vieraalla maalla".'),
(1670502,58,2,2,23,'Ja kun oli kulunut pitkä aika, kuoli Egyptin kuningas. Ja israelilaiset huokailivat orjuuttansa ja valittivat; ja heidän huutonsa heidän orjuutensa tähden nousi Jumalan tykö.'),
(1670503,58,2,2,24,'Ja Jumala kuuli heidän vaikeroimisensa, ja Jumala muisti liittonsa Aabrahamin, Iisakin ja Jaakobin kanssa.'),
(1670504,58,2,2,25,'Ja Jumala katsoi israelilaisten puoleen, ja Jumala piti heistä huolta.'),
(1670505,58,2,3,1,'Ja Mooses kaitsi appensa Jetron, Midianin papin, lampaita. Ja kun hän kerran ajoi lampaita erämaan tuolle puolen, tuli hän Jumalan vuoren, Hoorebin, juurelle.'),
(1670506,58,2,3,2,'Silloin Herran enkeli ilmestyi hänelle tulen liekissä keskellä orjantappurapensasta; ja hän näki, että pensas paloi ilmitulessa, mutta pensas ei kuitenkaan kulunut.'),
(1670507,58,2,3,3,'Niin Mooses sanoi: "Minä käyn tuonne ja katson tätä suurta näkyä, miksi ei pensas pala poroksi".'),
(1670508,58,2,3,4,'Kun Herra näki hänen tulevan katsomaan, huusi hän, Jumala, hänelle pensaasta ja sanoi: "Mooses, Mooses!" Hän vastasi: "Tässä olen".'),
(1670509,58,2,3,5,'Hän sanoi: "Älä tule tänne! Riisu kengät jalastasi, sillä paikka, jossa seisot, on pyhä maa."'),
(1670510,58,2,3,6,'Ja hän sanoi vielä: "Minä olen sinun isäsi Jumala, Aabrahamin Jumala, Iisakin Jumala ja Jaakobin Jumala". Ja Mooses peitti kasvonsa, sillä hän pelkäsi katsoa Jumalaa.'),
(1670511,58,2,3,7,'Ja Herra sanoi: "Minä olen nähnyt kansani kurjuuden Egyptissä ja kuullut heidän huutonsa sortajainsa tähden; niin, minä tiedän heidän tuskansa.'),
(1670512,58,2,3,8,'Sentähden minä olen astunut alas vapauttamaan heidät egyptiläisten kädestä ja johdattamaan heidät siitä maasta hyvään ja tilavaan maahan, maahan, joka vuotaa maitoa ja mettä, sinne, missä kanaanilaiset, heettiläiset, amorilaiset, perissiläiset, hivviläiset ja jebusilaiset asuvat.'),
(1670513,58,2,3,9,'Ja nyt on israelilaisten huuto tullut minun kuuluviini, ja minä olen myös nähnyt sen sorron, jolla egyptiläiset heitä sortavat.'),
(1670514,58,2,3,10,'Niin mene nyt, minä lähetän sinut faraon tykö, ja vie minun kansani, israelilaiset, pois Egyptistä."'),
(1670515,58,2,3,11,'Mutta Mooses sanoi Jumalalle: "Mikä minä olen menemään faraon tykö ja viemään israelilaisia pois Egyptistä?"'),
(1670516,58,2,3,12,'Hän vastasi: "Minä olen sinun kanssasi; ja tämä olkoon sinulle tunnusmerkkinä, että minä olen sinut lähettänyt: kun olet vienyt kansan pois Egyptistä, niin te palvelette Jumalaa tällä vuorella".'),
(1670517,58,2,3,13,'Mooses sanoi Jumalalle: "Katso, kun minä menen israelilaisten luo ja sanon heille: ''Teidän isienne Jumala on lähettänyt minut teidän luoksenne'', ja kun he kysyvät minulta: ''Mikä hänen nimensä on?'' niin mitä minä heille vastaan?"'),
(1670518,58,2,3,14,'Jumala vastasi Moosekselle: "Minä olen se, joka minä olen". Ja hän sanoi vielä: "Sano israelilaisille näin: ''Minä olen'' lähetti minut teidän luoksenne".'),
(1670519,58,2,3,15,'Ja Jumala sanoi vielä Moosekselle: "Sano israelilaisille näin: Herra, teidän isienne Jumala, Aabrahamin Jumala, Iisakin Jumala ja Jaakobin Jumala, lähetti minut teidän luoksenne; tämä on minun nimeni iankaikkisesti, ja näin minua kutsuttakoon sukupolvesta sukupolveen.'),
(1670520,58,2,3,16,'Mene ja kokoa Israelin vanhimmat ja sano heille: Herra, teidän isienne Jumala, Aabrahamin, Iisakin ja Jaakobin Jumala, on ilmestynyt minulle ja sanonut: ''Totisesti minä pidän teistä huolen ja pidän silmällä, mitä teille tapahtuu Egyptissä.'),
(1670521,58,2,3,17,'Ja minä olen päättänyt näin: minä johdatan teidät pois Egyptin kurjuudesta kanaanilaisten, heettiläisten, amorilaisten, perissiläisten, hivviläisten ja jebusilaisten maahan, siihen maahan, joka vuotaa maitoa ja mettä.'''),
(1670522,58,2,3,18,'Ja he kuulevat sinua. Niin mene sitten, sinä ja Israelin vanhimmat, Egyptin kuninkaan tykö, ja sanokaa hänelle: ''Herra, hebrealaisten Jumala, on kohdannut meitä. Anna siis meidän mennä kolmen päivän matka erämaahan uhraamaan Herralle, Jumalallemme.'''),
(1670523,58,2,3,19,'Mutta minä tiedän, että Egyptin kuningas ei päästä teitä menemään, ei edes väkevän käden pakolla.'),
(1670524,58,2,3,20,'Mutta minä ojennan käteni ja lyön Egyptiä kaikenkaltaisilla ihmeilläni, joita minä olen siellä tekevä, ja sitten hän päästää teidät.'),
(1670525,58,2,3,21,'Ja minä annan tämän kansan päästä egyptiläisten suosioon, niin että te lähtiessänne ette lähde tyhjin käsin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670526,58,2,3,22,'Vaan jokainen vaimo on pyytävä naapuriltaan ja luonaan majailevalta vaimolta hopea- ja kultakaluja ja vaatteita. Niihin te puette poikanne ja tyttärenne ja viette ne saaliina egyptiläisiltä."'),
(1670527,58,2,4,1,'Mooses vastasi ja sanoi: "Katso, he eivät usko minua eivätkä kuule minua, vaan sanovat: ''Ei Herra ole sinulle ilmestynyt''".'),
(1670528,58,2,4,2,'Herra sanoi hänelle: "Mikä sinulla on kädessäsi?" Hän vastasi: "Sauva".'),
(1670529,58,2,4,3,'Hän sanoi: "Heitä se maahan". Ja hän heitti sen maahan, ja se muuttui käärmeeksi; ja Mooses pakeni sitä.'),
(1670530,58,2,4,4,'Mutta Herra sanoi Moosekselle: "Ojenna kätesi ja tartu sen pyrstöön". Niin hän ojensi kätensä ja tarttui siihen, ja se muuttui sauvaksi hänen kädessänsä.'),
(1670531,58,2,4,5,'- "Siitä he uskovat, että Herra, heidän isiensä Jumala, Aabrahamin Jumala, Iisakin Jumala ja Jaakobin Jumala, on sinulle ilmestynyt".'),
(1670532,58,2,4,6,'Ja Herra sanoi vielä hänelle: "Pistä kätesi poveesi". Ja hän pisti kätensä poveensa. Ja kun hän veti sen ulos, niin katso, hänen kätensä oli pitalista valkoinen niinkuin lumi.'),
(1670533,58,2,4,7,'Ja hän sanoi: "Pistä kätesi takaisin poveesi". Ja hän pisti kätensä takaisin poveensa. Ja kun hän veti sen ulos povestansa, niin katso, se oli taas niinkuin hänen muukin ihonsa.'),
(1670534,58,2,4,8,'Herra sanoi: "Jos he eivät usko sinua eivätkä tottele ensimmäistä tunnustekoa, niin he uskovat toisen tunnusteon.'),
(1670535,58,2,4,9,'Mutta jos he eivät usko näitäkään kahta tunnustekoa eivätkä kuule sinua, niin ota vettä Niilivirrasta ja kaada kuivalle maalle, niin se vesi, jonka virrasta otat, on muuttuva vereksi kuivalla maalla."'),
(1670536,58,2,4,10,'Niin Mooses sanoi Herralle: "Oi Herra, minä en ole puhetaitoinen mies; en ole ollut ennen enkä senkään jälkeen, kuin sinä puhuit palvelijallesi; sillä minulla on hidas puhe ja kankea kieli".'),
(1670537,58,2,4,11,'Ja Herra sanoi hänelle: "Kuka on antanut ihmiselle suun, tahi kuka tekee mykän tai kuuron, näkevän tai sokean? Enkö minä, Herra?'),
(1670538,58,2,4,12,'Mene siis nyt, minä olen sinun suusi apuna ja opetan sinulle, mitä sinun on puhuttava."'),
(1670539,58,2,4,13,'Mutta hän sanoi: "Oi Herra, lähetä kuka muu tahansa!"'),
(1670540,58,2,4,14,'Niin Herra vihastui Moosekseen ja sanoi: "Eikö sinulla ole veljesi Aaron, leeviläinen? Minä tiedän, että hän osaa puhua. Ja katso, hän tuleekin sinua vastaan; ja kun hän näkee sinut, iloitsee hän sydämestänsä.'),
(1670541,58,2,4,15,'Ja puhu sinä hänelle ja pane sanat hänen suuhunsa. Ja minä olen sinun suusi apuna ja hänen suunsa apuna ja opetan teille, mitä teidän on tehtävä.'),
(1670542,58,2,4,16,'Ja hän on puhuva sinun puolestasi kansalle; niin hän on oleva sinulla suuna, ja sinä olet oleva hänellä jumalana.'),
(1670543,58,2,4,17,'Ja ota käteesi tämä sauva, jolla olet tekevä nuo tunnusteot."'),
(1670544,58,2,4,18,'Niin Mooses tuli takaisin appensa Jetron luo ja sanoi hänelle: "Anna minun mennä takaisin veljieni tykö Egyptiin, katsomaan, ovatko he vielä elossa". Jetro sanoi Moosekselle: "Mene rauhassa".'),
(1670545,58,2,4,19,'Ja Herra sanoi Moosekselle Midianissa: "Mene takaisin Egyptiin, sillä kaikki ne ovat kuolleet, jotka väijyivät sinun henkeäsi".'),
(1670546,58,2,4,20,'Niin Mooses otti vaimonsa ja poikansa ja pani heidät aasin selkään ja palasi Egyptin maahan; ja Mooses otti käteensä Jumalan sauvan.'),
(1670547,58,2,4,21,'Ja Herra sanoi Moosekselle: "Kun tulet takaisin Egyptiin, niin katso, että teet faraon edessä kaikki ne ihmeet, jotka minä olen pannut sinun käteesi. Mutta minä paadutan hänen sydämensä, niin että hän ei päästä kansaa.'),
(1670548,58,2,4,22,'Sano silloin faraolle: ''Näin sanoo Herra: Israel on minun esikoispoikani;'),
(1670549,58,2,4,23,'sentähden minä sanon sinulle: Päästä minun poikani palvelemaan minua. Mutta jos kieltäydyt päästämästä häntä, niin katso, minä tapan sinun esikoispoikasi.''"'),
(1670550,58,2,4,24,'Ja matkan varrella yöpaikassa tapahtui, että Herra kävi hänen kimppuunsa ja tahtoi surmata hänet.'),
(1670551,58,2,4,25,'Silloin Sippora otti terävän kiven ja leikkasi pois poikansa esinahan, kosketti sillä Moosesta alhaalta ja sanoi: "Sinä olet minun veriylkäni".'),
(1670552,58,2,4,26,'Niin hän jätti hänet rauhaan. Silloin Sippora sanoi: "Veriylkä ympärileikkauksen kautta".'),
(1670553,58,2,4,27,'Ja Herra sanoi Aaronille: "Mene Moosesta vastaan erämaahan". Ja hän meni ja kohtasi hänet Jumalan vuorella ja suuteli häntä.'),
(1670554,58,2,4,28,'Ja Mooses kertoi Aaronille kaikki, mitä Herra oli puhunut lähettäessään hänet, ja kaikki ne tunnusteot, jotka hän oli käskenyt hänen tehdä.'),
(1670555,58,2,4,29,'Niin Mooses ja Aaron menivät ja kokosivat kaikki israelilaisten vanhimmat.'),
(1670556,58,2,4,30,'Ja Aaron puhui kaikki, mitä Herra oli Moosekselle sanonut, ja Mooses teki tunnusteot kansan silmien edessä.'),
(1670557,58,2,4,31,'Ja kansa uskoi. Ja kun he kuulivat, että Herra oli pitänyt huolta israelilaisista ja nähnyt heidän kurjuutensa, kumartuivat he maahan ja rukoilivat.'),
(1670558,58,2,5,1,'Senjälkeen Mooses ja Aaron menivät ja sanoivat faraolle: "Näin sanoo Herra, Israelin Jumala: Päästä minun kansani viettämään minulle juhlaa erämaassa".'),
(1670559,58,2,5,2,'Mutta farao vastasi: "Kuka on Herra, jota minun pitäisi kuulla ja päästää Israel? Minä en tunne Herraa enkä päästä Israelia."'),
(1670560,58,2,5,3,'Niin he sanoivat: "Hebrealaisten Jumala on kohdannut meitä. Anna siis meidän mennä kolmen päivän matka erämaahan uhraamaan Herralle, Jumalallemme, ettei hän rankaisisi meitä rutolla tai miekalla."'),
(1670561,58,2,5,4,'Mutta Egyptin kuningas vastasi heille: "Miksi te, Mooses ja Aaron, pidätätte kansaa työnteosta? Menkää töihinne."'),
(1670562,58,2,5,5,'Ja farao sanoi vielä: "Katsokaa, liian paljon on muutenkin joutoväkeä maassa, ja te tahdotte saattaa heidät kulkemaan työttöminä".'),
(1670563,58,2,5,6,'Ja farao antoi sinä päivänä käskyn kansan työnteettäjille ja päällysmiehille, sanoen:'),
(1670564,58,2,5,7,'"Älkää enää antako kansalle olkia tiilien tekemistä varten niinkuin ennen; he menkööt itse ja kootkoot itselleen oljet.'),
(1670565,58,2,5,8,'Pankaa kuitenkin heidän tehtäväkseen sama tiilimäärä, jonka he ennenkin ovat tehneet, siitä mitään vähentämättä; sillä he ovat laiskoja, sentähden he huutavat näin: ''Menkäämme uhraamaan Jumalallemme!'''),
(1670566,58,2,5,9,'Pantakoon miehille raskasta työtä, että heillä olisi siinä tekemistä ja että he eivät kuuntelisi valhepuheita."'),
(1670567,58,2,5,10,'Niin kansan työnteettäjät ja päällysmiehet menivät ja sanoivat kansalle: "Näin sanoo farao: ''Minä en anna teille enää olkia.'),
(1670568,58,2,5,11,'Menkää itse ja hankkikaa itsellenne olkia, mistä vain löydätte, mutta työstänne ei vähennetä mitään.''"'),
(1670569,58,2,5,12,'Niin kansa hajosi pitkin Egyptin maata keräämään pehkuja olkien asemesta.'),
(1670570,58,2,5,13,'Ja työnteettäjät ahdistivat heitä sanoen: "Tehkää työnne valmiiksi, kunkin päivän määrä päivälleen, niinkuin silloinkin, kun saitte olkia".'),
(1670571,58,2,5,14,'Ja israelilaisten päällysmiehiä, joita faraon työnteettäjät olivat heille asettaneet, piestiin, ja heille sanottiin: "Miksi ette ole eilen ettekä tänään suorittaneet tähänastista määräänne tiilien teossa?"'),
(1670572,58,2,5,15,'Niin israelilaisten päällysmiehet menivät ja valittivat faraolle, sanoen: "Minkätähden teet näin palvelijoillesi?'),
(1670573,58,2,5,16,'Olkia palvelijoillesi ei anneta, mutta kuitenkin sanotaan meille: ''Tehkää tiilet''. Ja katso, palvelijoitasi piestään, vaikka vika on sinun oman väkesi."'),
(1670574,58,2,5,17,'Mutta hän sanoi: "Te olette laiskoja, laiskoja olette; sentähden te sanotte: ''Menkäämme uhraamaan Herralle''.'),
(1670575,58,2,5,18,'Menkää vain työhönne. Olkia ei teille anneta, mutta määrätty luku tiiliä on teidän hankittava."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670576,58,2,5,19,'Niin israelilaisten päällysmiehet huomasivat joutuneensa ahtaalle, kun heille sanottiin: "Ette saa mitään tiililuvun vähennystä kunkin päivän määrästä".'),
(1670577,58,2,5,20,'Ja kun he lähtivät faraon luota, kohtasivat he Mooseksen ja Aaronin, jotka odottivat heitä,'),
(1670578,58,2,5,21,'ja he sanoivat näille: "Herra kostakoon teille ja tuomitkoon teidät; sillä te olette saattaneet meidät faraon ja hänen palvelijainsa vihoihin ja antaneet heidän käteensä miekan, meille surmaksi".'),
(1670579,58,2,5,22,'Silloin Mooses palasi Herran tykö ja sanoi: "Herra, miksi olet tehnyt niin pahoin tälle kansalle? Miksi olet lähettänyt minut?'),
(1670580,58,2,5,23,'Sillä siitä asti, kun minä menin faraon tykö puhumaan sinun nimessäsi, hän on tehnyt pahaa tälle kansalle, etkä sinä suinkaan ole kansaasi vapahtanut."'),
(1670581,58,2,6,1,'Mutta Herra vastasi Moosekselle: "Nyt saat nähdä, mitä minä faraolle teen; sillä väkevän käden pakottamana hän on päästävä heidät, ja väkevän käden pakottamana hän on ajava heidät maastansa".'),
(1670582,58,2,6,2,'Ja Jumala puhui Moosekselle ja sanoi hänelle: "Minä olen Herra.'),
(1670583,58,2,6,3,'Ja minä olen ilmestynyt Aabrahamille, Iisakille ja Jaakobille ''Jumalana Kaikkivaltiaana'', mutta nimelläni ''Herra'' en minä ole tehnyt itseäni heille tunnetuksi.'),
(1670584,58,2,6,4,'Ja minä tein myös liittoni heidän kanssansa, antaakseni heille Kanaanin maan, sen maan, jossa he muukalaisina asuivat.'),
(1670585,58,2,6,5,'Ja nyt minä olen kuullut israelilaisten vaikeroimisen, kun egyptiläiset pitävät heitä orjantyössä, ja olen muistanut liittoni.'),
(1670586,58,2,6,6,'Sano sentähden israelilaisille: ''Minä olen Herra, ja minä vien teidät pois egyptiläisten sorron alta ja vapautan teidät orjuudesta ja pelastan teidät ojennetulla käsivarrella ja suurilla rangaistustuomioilla.'),
(1670587,58,2,6,7,'Niin minä otan teidät kansakseni ja olen teidän Jumalanne; ja te tulette tietämään, että minä olen Herra, teidän Jumalanne, joka vien teidät pois egyptiläisten sorron alta.'),
(1670588,58,2,6,8,'Ja minä johdatan teidät siihen maahan, jonka minä olen kättä kohottaen luvannut antaa Aabrahamille, Iisakille ja Jaakobille; ja sen minä annan teille omaksi. Minä olen Herra.''"'),
(1670589,58,2,6,9,'Ja Mooses puhui näin israelilaisille; mutta he eivät kuulleet Moosesta tuskaantumisensa ja raskaan orjuutensa tähden.'),
(1670590,58,2,6,10,'Sitten Herra puhui Moosekselle ja sanoi:'),
(1670591,58,2,6,11,'"Mene ja sano faraolle, Egyptin kuninkaalle, että hän päästää israelilaiset maastansa".'),
(1670592,58,2,6,12,'Mutta Mooses puhui Herran edessä ja sanoi: "Katso, israelilaiset eivät kuulleet minua; kuinka sitten farao kuulisi minua, joka olen huuliltani ympärileikkaamaton?"'),
(1670593,58,2,6,13,'Mutta Herra puhui Moosekselle ja Aaronille ja käski heitä menemään israelilaisten ja faraon, Egyptin kuninkaan, tykö ja viemään israelilaiset pois Egyptin maasta.'),
(1670594,58,2,6,14,'Nämä ovat heidän perhekuntainsa päämiehet: Ruubenin, Israelin esikoisen, pojat olivat Hanok ja Pallu, Hesron ja Karmi. Nämä ovat Ruubenin sukukunnat.'),
(1670595,58,2,6,15,'Simeonin pojat olivat Jemuel, Jaamin, Oohad, Jaakin, Soohar ja Saul, kanaanilaisen vaimon poika. Nämä ovat Simeonin sukukunnat.'),
(1670596,58,2,6,16,'Ja nämä ovat Leevin poikien nimet heidän polveutumisensa mukaan: Geerson, Kehat ja Merari. Ja Leevin elinaika oli sata kolmekymmentä seitsemän vuotta.'),
(1670597,58,2,6,17,'Geersonin pojat olivat Libni ja Siimei, sukujensa mukaan.'),
(1670598,58,2,6,18,'Kehatin pojat olivat Amram, Jishar, Hebron ja Ussiel. Ja Kehatin elinaika oli sata kolmekymmentä kolme vuotta.'),
(1670599,58,2,6,19,'Merarin pojat olivat Mahli ja Muusi. Nämä ovat Leevin suvut polveutumisensa mukaan.'),
(1670600,58,2,6,20,'Mutta Amram otti isänsä sisaren Jookebedin vaimokseen, ja tämä synnytti hänelle Aaronin ja Mooseksen. Ja Amramin elinaika oli sata kolmekymmentä seitsemän vuotta.'),
(1670601,58,2,6,21,'Jisharin pojat olivat Koorah, Nefeg ja Sikri.'),
(1670602,58,2,6,22,'Ussielin pojat olivat Miisael, Elsafan ja Sitri.'),
(1670603,58,2,6,23,'Ja Aaron otti vaimoksensa Eliseban, Amminadabin tyttären, Nahsonin sisaren, ja tämä synnytti hänelle Naadabin, Abihun, Eleasarin ja Iitamarin.'),
(1670604,58,2,6,24,'Koorahin pojat olivat Assir, Elkana ja Abiasaf. Nämä ovat koorahilaisten suvut.'),
(1670605,58,2,6,25,'Ja Eleasar, Aaronin poika, otti itsellensä vaimon Puutielin tyttäristä, ja tämä synnytti hänelle Piinehaan. Nämä ovat leeviläisten perhekuntien päämiehet heidän sukujensa mukaan.'),
(1670606,58,2,6,26,'Nämä olivat Aaron ja Mooses, joille Herra sanoi: "Viekää israelilaiset joukkoinensa pois Egyptin maasta".'),
(1670607,58,2,6,27,'Nämä puhuivat faraolle, Egyptin kuninkaalle, että he aikoivat viedä israelilaiset pois Egyptistä, nimittäin Mooses ja Aaron.'),
(1670608,58,2,6,28,'Ja niihin aikoihin, kun Herra puhui Moosekselle Egyptin maassa,'),
(1670609,58,2,6,29,'puhui Herra Moosekselle näin: "Minä olen Herra. Sano faraolle, Egyptin kuninkaalle, kaikki, mitä minä sinulle puhun."'),
(1670610,58,2,6,30,'Mutta Mooses vastasi Herran edessä: "Katso, minä olen huuliltani ympärileikkaamaton, kuinka siis farao kuulisi minua?"'),
(1670611,58,2,7,1,'Mutta Herra sanoi Moosekselle: "Katso, minä asetan sinut jumalaksi faraolle, ja veljesi Aaron on oleva sinun profeettasi.'),
(1670612,58,2,7,2,'Puhu kaikki, mitä minä sinun käsken puhua; ja Aaron, sinun veljesi, puhukoon faraolle, että hän päästää israelilaiset maastansa.'),
(1670613,58,2,7,3,'Mutta minä paadutan faraon sydämen ja teen monta tunnustekoa ja ihmettä Egyptin maassa.'),
(1670614,58,2,7,4,'Ja farao ei kuule teitä, mutta minä asetan käteni Egyptiä vastaan ja vien pois joukkoni, kansani, israelilaiset, Egyptin maasta, toimittaen suuret rangaistustuomiot.'),
(1670615,58,2,7,5,'Ja egyptiläiset tulevat tietämään, että minä olen Herra, kun minä ojennan käteni Egyptin yli ja vien pois israelilaiset heidän keskeltänsä."'),
(1670616,58,2,7,6,'Ja Mooses ja Aaron tekivät, niinkuin Herra oli heitä käskenyt; niin he tekivät.'),
(1670617,58,2,7,7,'Mutta Mooses oli kahdeksankymmenen vuoden vanha ja Aaron kahdeksankymmenen kolmen vuoden vanha, kun he puhuivat faraon kanssa.'),
(1670618,58,2,7,8,'Ja Herra puhui Moosekselle ja Aaronille ja sanoi:'),
(1670619,58,2,7,9,'"Kun farao puhuu teille ja sanoo: ''Tehkää jokin ihmetyö'', niin sano sinä Aaronille: ''Ota sauvasi ja heitä se faraon eteen, niin se muuttuu käärmeeksi''".'),
(1670620,58,2,7,10,'Niin Mooses ja Aaron menivät faraon tykö ja tekivät, niinkuin Herra oli käskenyt. Aaron heitti sauvansa faraon ja hänen palvelijainsa eteen, ja se muuttui käärmeeksi.'),
(1670621,58,2,7,11,'Ja faraokin kutsui maansa viisaat ja velhot; ja nämä Egyptin tietäjät tekivät samoin taioillansa:'),
(1670622,58,2,7,12,'he heittivät kukin sauvansa maahan, ja ne muuttuivat käärmeiksi. Mutta Aaronin sauva nieli heidän sauvansa.'),
(1670623,58,2,7,13,'Ja faraon sydän paatui, eikä hän kuullut heitä, niinkuin Herra oli sanonutkin.'),
(1670624,58,2,7,14,'Sitten Herra sanoi Moosekselle: "Faraon sydän on kovettunut, hän kieltäytyy päästämästä kansaa.'),
(1670625,58,2,7,15,'Mene faraon tykö huomenaamuna, kun hän menee veden luo, ja seisahdu hänen tielleen Niilivirran partaalle. Ja ota käteesi se sauva, joka oli muuttunut käärmeeksi,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670626,58,2,7,16,'ja sano hänelle: ''Herra, hebrealaisten Jumala, on lähettänyt minut sinun luoksesi ja käskenyt sanoa: Päästä minun kansani palvelemaan minua erämaassa. Mutta katso, sinä et ole totellut tähän asti.'),
(1670627,58,2,7,17,'Sentähden Herra sanoo näin: Tästä olet tunteva, että minä olen Herra: katso, minä lyön sauvalla, joka on kädessäni, virran veteen, ja se muuttuu vereksi.'),
(1670628,58,2,7,18,'Ja kalat virrassa kuolevat, ja virta rupeaa haisemaan, niin että egyptiläisiä inhottaa juoda vettä virrasta.''"'),
(1670629,58,2,7,19,'Ja Herra sanoi Moosekselle: "Sano Aaronille: ''Ota sauvasi ja ojenna kätesi Egyptin vetten yli, sen jokien, kanavien ja lammikkojen yli ja kaikkien niiden paikkojen yli, joihin on vettä kokoontunut, niin ne muuttuvat vereksi. Ja verta on oleva Egyptin maassa kaikkialla, sekä puuastioissa että kiviastioissa.''"'),
(1670630,58,2,7,20,'Ja Mooses ja Aaron tekivät, niinkuin Herra oli käskenyt. Hän kohotti sauvan ja löi Niilivirran veteen faraon ja hänen palvelijainsa nähden; ja kaikki vesi, joka virrassa oli, muuttui vereksi.'),
(1670631,58,2,7,21,'Ja kalat virrassa kuolivat, ja virta haisi, niin että egyptiläiset eivät saattaneet juoda vettä virrasta; ja verta oli kaikkialla Egyptin maassa.'),
(1670632,58,2,7,22,'Mutta Egyptin tietäjät tekivät samoin taioillansa. Ja faraon sydän paatui, eikä hän kuullut heitä, niinkuin Herra oli sanonutkin.'),
(1670633,58,2,7,23,'Ja farao kääntyi ja palasi kotiinsa eikä välittänyt tästäkään.'),
(1670634,58,2,7,24,'Mutta kaikki egyptiläiset kaivoivat Niilivirran ympäriltä vettä juodaksensa; sillä he eivät voineet juoda virran vettä.'),
(1670635,58,2,7,25,'Ja näin oli kulunut seitsemän päivää siitä, kun Herra oli lyönyt Niilivirtaa.'),
(1670636,58,2,8,1,'Sitten Herra sanoi Moosekselle: "Mene faraon luo ja sano hänelle: ''Näin sanoo Herra: Päästä minun kansani palvelemaan minua.'),
(1670637,58,2,8,2,'Mutta jos kieltäydyt päästämästä heitä, niin katso, minä rankaisen koko sinun maatasi sammakoilla.'),
(1670638,58,2,8,3,'Ja Niilivirta on vilisevä sammakoita, ja ne nousevat maalle ja tulevat sinun taloosi ja makuuhuoneeseesi ja vuoteeseesi, sekä sinun palvelijaisi taloihin ja kansasi sekaan, sinun leivinuuneihisi ja taikinakaukaloihisi.'),
(1670639,58,2,8,4,'Jopa sinun ja sinun kansasi ja kaikkien sinun palvelijaisi päälle hyppii sammakoita.''"'),
(1670640,58,2,8,5,'Ja Herra sanoi Moosekselle: "Sano Aaronille: ''Ojenna kätesi sauvoinensa jokien, kanavien ja lammikkojen yli ja nostata sammakoita Egyptin maahan''".'),
(1670641,58,2,8,6,'Niin Aaron ojensi kätensä Egyptin vetten yli, ja sammakoita nousi, ja ne peittivät Egyptin maan.'),
(1670642,58,2,8,7,'Ja tietäjät tekivät samoin taioillansa ja nostattivat sammakoita Egyptin maahan.'),
(1670643,58,2,8,8,'Niin farao kutsui Mooseksen ja Aaronin ja sanoi: "Rukoilkaa Herraa, että hän ottaisi pois sammakot vaivaamasta minua ja minun kansaani, niin minä päästän kansan uhraamaan Herralle".'),
(1670644,58,2,8,9,'Mooses sanoi faraolle: "Suvaitse määrätä minulle aika, jonka kuluessa minun on rukoiltava, sinun itsesi, sinun palvelijaisi ja kansasi puolesta, sammakot hävitettäviksi luotasi ja taloistasi, niin että niitä jää ainoastaan Niilivirtaan".'),
(1670645,58,2,8,10,'Hän vastasi: "Huomiseksi". Niin Mooses sanoi: "Tapahtukoon, niinkuin sanoit, tietääksesi, ettei kukaan ole niinkuin Herra, meidän Jumalamme.'),
(1670646,58,2,8,11,'Sammakot katoavat luotasi ja taloistasi ja sinun palvelijaisi ja kansasi luota, ja niitä jää ainoastaan Niilivirtaan."'),
(1670647,58,2,8,12,'Niin Mooses ja Aaron lähtivät faraon luota. Ja Mooses huusi Herran puoleen sammakkojen tähden, jotka hän oli pannut faraon vaivaksi.'),
(1670648,58,2,8,13,'Ja Herra teki Mooseksen sanan mukaan: sammakot kuolivat huoneista, pihoilta ja kedoilta.'),
(1670649,58,2,8,14,'Ja he kokosivat niitä läjittäin, ja maa rupesi haisemaan.'),
(1670650,58,2,8,15,'Mutta kun farao näki päässeensä hengähtämään, kovensi hän sydämensä eikä kuullut heitä, niinkuin Herra oli sanonutkin.'),
(1670651,58,2,8,16,'Sitten Herra sanoi Moosekselle: "Sano Aaronille: ''Ojenna sauvasi ja lyö maan tomua, niin siitä tulee sääskiä koko Egyptin maahan''".'),
(1670652,58,2,8,17,'Ja he tekivät niin: Aaron ojensi kätensä ja sauvansa ja löi maan tomua; niin sääsket ahdistivat ihmisiä ja karjaa. Kaikki maan tomu muuttui sääskiksi koko Egyptin maassa.'),
(1670653,58,2,8,18,'Ja tietäjät tekivät samoin taioillansa saadakseen sääskiä syntymään, mutta he eivät voineet. Ja sääsket ahdistivat ihmisiä ja karjaa.'),
(1670654,58,2,8,19,'Niin tietäjät sanoivat faraolle: "Tämä on Jumalan sormi". Mutta faraon sydän paatui, eikä hän kuullut heitä, niinkuin Herra oli sanonutkin.'),
(1670655,58,2,8,20,'Ja Herra sanoi Moosekselle: "Astu huomenaamuna varhain faraon eteen, kun hän menee veden luo, ja sano hänelle: ''Näin sanoo Herra: Päästä minun kansani palvelemaan minua.'),
(1670656,58,2,8,21,'Sillä jos et päästä minun kansaani, niin katso, minä lähetän paarmoja sinun, sinun palvelijaisi ja sinun kansasi kimppuun ja sinun taloihisi, niin että egyptiläisten talot, jopa se maa, jonka päällä ne ovat, tulevat paarmoja täyteen.'),
(1670657,58,2,8,22,'Mutta minä erotan sinä päivänä Goosenin maan, jossa minun kansani asuu, ettei sinne paarmoja tule, tietääksesi, että minä olen maan Herra.'),
(1670658,58,2,8,23,'Näin minä panen pelastuksen erottamaan oman kansani sinun kansastasi. Huomenna on tämä ihme tapahtuva.''"'),
(1670659,58,2,8,24,'Ja Herra teki niin: paarmoja tuli suuret parvet faraon ja hänen palvelijainsa taloihin; ja paarmat tulivat maan turmioksi koko Egyptin maassa.'),
(1670660,58,2,8,25,'Niin farao kutsutti Mooseksen ja Aaronin ja sanoi: "Menkää ja uhratkaa Jumalallenne tässä maassa".'),
(1670661,58,2,8,26,'Mutta Mooses sanoi: "Ei sovi niin tehdä; sillä me uhraamme Herralle, Jumalallemme, sellaista, joka on egyptiläisille kauhistus. Jos me nyt uhraamme egyptiläisten nähden sellaista, joka on heille kauhistus, niin eivätkö he kivitä meitä?'),
(1670662,58,2,8,27,'Salli meidän mennä kolmen päivän matka erämaahan uhraamaan Herralle, Jumalallemme, niinkuin hän on meille sanonut."'),
(1670663,58,2,8,28,'Farao sanoi: "Minä päästän teidät uhraamaan Herralle, Jumalallenne, erämaassa; älkää vain menkö kovin kauas. Rukoilkaa minun puolestani."'),
(1670664,58,2,8,29,'Niin Mooses sanoi: "Katso, kun olen lähtenyt sinun luotasi, rukoilen minä Herraa, ja paarmat häviävät pois huomenna faraolta, hänen palvelijoiltansa ja hänen kansaltaan. Älköön vain farao enää pettäkö, niin ettei hän päästäkään kansaa uhraamaan Herralle."'),
(1670665,58,2,8,30,'Ja Mooses lähti faraon luota ja rukoili Herraa.'),
(1670666,58,2,8,31,'Ja Herra teki, niinkuin Mooses oli sanonut: hän vapautti faraon, hänen palvelijansa ja hänen kansansa paarmoista, niin ettei niitä jäänyt ainoatakaan.'),
(1670667,58,2,8,32,'Mutta farao kovensi sydämensä tälläkin kerralla eikä päästänyt kansaa.'),
(1670668,58,2,9,1,'Sitten Herra sanoi Moosekselle: "Mene faraon tykö ja puhu hänelle: ''Näin sanoo Herra, hebrealaisten Jumala: Päästä minun kansani palvelemaan minua.'),
(1670669,58,2,9,2,'Sillä jos kieltäydyt päästämästä heitä ja vielä pidätät heitä,'),
(1670670,58,2,9,3,'niin katso, Herran käsi on lyövä sinun karjaasi, joka on kedolla, hevosia, aaseja, kameleita, nautoja ja lampaita ylen ankaralla ruttotaudilla.'),
(1670671,58,2,9,4,'Mutta Herra on tekevä erotuksen israelilaisten karjan ja egyptiläisten karjan välillä, niin ettei mitään kuole siitä, mikä on israelilaisten omaa.''"'),
(1670672,58,2,9,5,'Ja Herra asetti määrätyn ajan ja sanoi: "Huomenna on Herra tekevä niin tässä maassa".'),
(1670673,58,2,9,6,'Ja seuraavana päivänä Herra teki niin, ja kaikki Egyptin karja kuoli; mutta israelilaisten karjasta ei kuollut ainoatakaan.'),
(1670674,58,2,9,7,'Ja kun farao lähetti tiedustelemaan, niin katso, israelilaisten karjasta ei ollut kuollut ainoatakaan. Mutta faraon sydän kovettui, eikä hän päästänyt kansaa.'),
(1670675,58,2,9,8,'Sitten Herra sanoi Moosekselle ja Aaronille: "Ottakaa kahmalonne täyteen pätsin nokea, ja Mooses viskatkoon sen taivasta kohti faraon silmien edessä,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670676,58,2,9,9,'niin se muuttuu tomuksi, joka peittää koko Egyptin maan, ja siitä tulee ihmisiin ja karjaan märkäpaiseita kaikkialla Egyptin maassa".'),
(1670677,58,2,9,10,'Ja he ottivat pätsin nokea ja astuivat faraon eteen, ja Mooses viskasi sen taivasta kohti; niin märkäpaiseita tuli ihmisiin ja karjaan.'),
(1670678,58,2,9,11,'Eivätkä tietäjätkään voineet pitää puoliaan Moosesta vastaan paiseiden tähden, sillä paiseita oli tietäjissä samoin kuin kaikissa muissakin egyptiläisissä.'),
(1670679,58,2,9,12,'Mutta Herra paadutti faraon sydämen, niin ettei hän kuullut heitä, niinkuin Herra oli sanonutkin Moosekselle.'),
(1670680,58,2,9,13,'Sitten Herra sanoi Moosekselle: "Astu huomenaamuna varhain faraon eteen ja sano hänelle: ''Näin sanoo Herra, hebrealaisten Jumala: Päästä minun kansani palvelemaan minua.'),
(1670681,58,2,9,14,'Muutoin minä tällä kertaa lähetän kaikki vitsaukseni vaivaamaan sinua itseäsi, sinun palvelijoitasi ja kansaasi, tietääksesi, ettei ketään ole minun vertaistani koko maan päällä.'),
(1670682,58,2,9,15,'Sillä minä olisin jo ojentanut käteni ja lyönyt sinua ja sinun kansaasi ruttotaudilla, niin että olisit kokonaan hävinnyt maan päältä,'),
(1670683,58,2,9,16,'mutta juuri sitä varten minä olen antanut sinun säilyä, että näyttäisin sinulle voimani ja että minun nimeni julistettaisiin kaiken maan päällä.'),
(1670684,58,2,9,17,'Jos sinä vielä estät minun kansaani etkä päästä heitä,'),
(1670685,58,2,9,18,'niin katso, huomenna tähän aikaan minä annan tulla ylen ankaran raesateen, jonka kaltaista ei ole Egyptissä ollut siitä päivästä saakka, jona sen perustus pantiin, aina tähän asti.'),
(1670686,58,2,9,19,'Lähetä siis nyt saattamaan suojaan karjasi ja kaikki, mitä sinulla on kedolla. Sillä kaikki ihmiset ja karja, jotka ovat kedolla ja joita ei ole korjattu kotiin, joutuvat raesateen alle ja kuolevat.''"'),
(1670687,58,2,9,20,'Se faraon palvelijoista, joka pelkäsi Herran sanaa, toimitti silloin palvelijansa ja karjansa huoneiden suojaan;'),
(1670688,58,2,9,21,'mutta joka ei välittänyt Herran sanasta, se jätti palvelijansa ja karjansa kedolle.'),
(1670689,58,2,9,22,'Ja Herra sanoi Moosekselle: "Ojenna kätesi taivasta kohti, niin raesade kohtaa koko Egyptin maata, ihmisiä, karjaa ja kaikkia kedon kasveja Egyptin maassa".'),
(1670690,58,2,9,23,'Niin Mooses ojensi sauvansa taivasta kohti, ja Herra antoi jylistä ja lähetti rakeita, ja tulta iski maahan. Näin Herra antoi sataa rakeita yli Egyptin maan.'),
(1670691,58,2,9,24,'Ja rakeita tuli, ja tulta leimahteli rakeiden keskellä. Raesade oli ylen ankara, niin ettei sellainen ollut kohdannut koko Egyptin maata siitä ajasta saakka, jolloin se tuli asutuksi.'),
(1670692,58,2,9,25,'Ja rakeet löivät maahan kaikkialla Egyptin maassa kaiken, mitä kedolla oli, sekä ihmiset että karjan; ja rakeet tuhosivat kaikki maan kasvit ja pirstoivat kaikki kedon puut.'),
(1670693,58,2,9,26,'Ainoastaan Goosenin maata, jossa israelilaiset olivat, ei raesade kohdannut.'),
(1670694,58,2,9,27,'Niin farao kutsutti Mooseksen ja Aaronin ja sanoi heille: "Minä olen tehnyt syntiä tällä kertaa. Herra on oikeassa, mutta minä ja minun kansani olemme väärässä.'),
(1670695,58,2,9,28,'Rukoilkaa Herraa, sillä jo on meillä kyllin Jumalan jylinää ja rakeita. Minä päästän teidät, eikä teidän tarvitse enää viipyä."'),
(1670696,58,2,9,29,'Mooses vastasi hänelle: "Kun lähden kaupungista, niin minä ojennan käteni Herran puoleen, ja jylinä lakkaa eikä rakeita enää tule, tietääksesi, että maa on Herran.'),
(1670697,58,2,9,30,'Mutta et sinä eivätkä sinun palvelijasi, sen kyllä tiedän, vielä nytkään pelkää Herraa Jumalaa."'),
(1670698,58,2,9,31,'Niin pellava ja ohra tuhoutuivat, sillä ohra oli tähkällä ja pellava kukalla;'),
(1670699,58,2,9,32,'mutta nisu ja kolmitahkoinen vehnä eivät turmeltuneet, sillä ne tuleentuvat myöhemmin.'),
(1670700,58,2,9,33,'Ja Mooses lähti faraon luota, ulos kaupungista, ja ojensi kätensä Herran puoleen; ja jylinä ja rakeet lakkasivat, eikä sade enää vuotanut maahan.'),
(1670701,58,2,9,34,'Kun farao näki, että sade, rakeet ja jylinä lakkasivat, teki hän yhä edelleen syntiä ja kovensi sydämensä, sekä hän että hänen palvelijansa.'),
(1670702,58,2,9,35,'Niin faraon sydän paatui, eikä hän päästänyt israelilaisia, niinkuin Herra oli Mooseksen kautta sanonutkin.'),
(1670703,58,2,10,1,'Sitten Herra sanoi Moosekselle: "Mene faraon tykö, sillä minä olen koventanut hänen sydämensä ja hänen palvelijainsa sydämet, että tekisin nämä tunnustekoni heidän keskellänsä'),
(1670704,58,2,10,2,'ja että sinä kertoisit lapsillesi ja lastesi lapsille, mitä minä olen tehnyt egyptiläisille, ja minun tunnustekoni, jotka olen tehnyt heidän keskellänsä, tietääksenne, että minä olen Herra".'),
(1670705,58,2,10,3,'Niin Mooses ja Aaron menivät faraon tykö ja sanoivat hänelle: "Näin sanoo Herra, hebrealaisten Jumala: Kuinka kauan sinä kieltäydyt nöyrtymästä minun edessäni? Päästä minun kansani palvelemaan minua.'),
(1670706,58,2,10,4,'Sillä jos sinä kieltäydyt päästämästä minun kansaani, niin katso, minä annan huomenna tulla sinun maahasi heinäsirkkoja.'),
(1670707,58,2,10,5,'Ja ne peittävät maan pinnan, niin ettei maata näy, ja ne syövät tähteet siitä, mikä teille rakeilta pelastui ja jäi, ja ne syövät kaikki teidän puunne, jotka kedolla kasvavat.'),
(1670708,58,2,10,6,'Ja ne täyttävät sinun talosi ja kaikkien sinun palvelijaisi talot ja kaikkien egyptiläisten talot, niin ettei sinun isäsi eivätkä esi-isäsi ole sellaista nähneet siitä päivästä, jona tulivat maailmaan, hamaan tähän päivään asti." Ja hän kääntyi ja lähti pois faraon luota.'),
(1670709,58,2,10,7,'Mutta faraon palvelijat sanoivat hänelle: "Kuinka kauan tämä mies on oleva meille paulaksi? Päästä miehet palvelemaan Herraa, heidän Jumalaansa. Etkö vieläkään ymmärrä, että Egypti joutuu perikatoon?"'),
(1670710,58,2,10,8,'Niin Mooses ja Aaron tuotiin takaisin faraon eteen. Ja tämä sanoi heille: "Menkää ja palvelkaa Herraa, Jumalaanne. Vaan ketkä menevät?"'),
(1670711,58,2,10,9,'Mooses vastasi: "Me menemme, nuoret ja vanhat, me menemme poikinemme ja tyttärinemme, lampainemme ja karjoinemme; sillä meillä on Herran juhla".'),
(1670712,58,2,10,10,'Niin hän sanoi heille: "Olkoon vain Herra teidän kanssanne, kunhan minä ensin päästän teidät ja teidän vaimonne ja lapsenne. Katsokaa, teillä on paha mielessä.'),
(1670713,58,2,10,11,'Siitä ei tule mitään. Mutta menkää te, miehet, ja palvelkaa Herraa, sillä sitähän te olette pyytäneetkin." Ja heidät ajettiin pois faraon edestä.'),
(1670714,58,2,10,12,'Ja Herra sanoi Moosekselle: "Ojenna kätesi Egyptin maan yli ja tuo tänne heinäsirkat; tulkoon niitä Egyptin maahan, ja syökööt ne kaikki maan kasvit, kaikki, mitä rakeilta on jäänyt".'),
(1670715,58,2,10,13,'Niin Mooses ojensi sauvansa Egyptin maan yli, ja Herra antoi itätuulen puhaltaa yli maan koko sen päivän ja koko yön; kun aamu tuli, toi itätuuli heinäsirkat mukanaan.'),
(1670716,58,2,10,14,'Ja heinäsirkkoja tuli koko Egyptin maahan, ja ne laskeutuivat ylen suurina laumoina koko Egyptin alueelle; niin paljon ei heinäsirkkoja ollut koskaan sitä ennen tullut eikä sen jälkeen tule.'),
(1670717,58,2,10,15,'Ne peittivät koko maan pinnan, niin että maa tuli mustaksi; ja ne söivät kaikki maan kasvit ja kaikki puiden hedelmät, jotka olivat rakeilta säilyneet. Niin ei jäänyt mitään vihantaa jäljelle puihin eikä kedon kasveihin koko Egyptin maassa.'),
(1670718,58,2,10,16,'Silloin farao kutsutti kiiruusti Mooseksen ja Aaronin ja sanoi: "Minä olen rikkonut Herraa, teidän Jumalaanne, ja teitä vastaan.'),
(1670719,58,2,10,17,'Anna nyt anteeksi minun rikkomukseni vielä tämä kerta, ja rukoilkaa Herraa, Jumalaanne, että hän poistaisi minulta ainakin tämän surman."'),
(1670720,58,2,10,18,'Niin hän lähti pois faraon luota ja rukoili Herraa.'),
(1670721,58,2,10,19,'Ja Herra käänsi tuulen hyvin kovaksi länsituuleksi; se vei heinäsirkat mukanaan ja painoi ne Kaislamereen, niin ettei yhtäkään heinäsirkkaa jäänyt koko Egyptin alueelle.'),
(1670722,58,2,10,20,'Mutta Herra paadutti faraon sydämen, niin ettei hän päästänyt israelilaisia.'),
(1670723,58,2,10,21,'Sitten Herra sanoi Moosekselle: "Ojenna kätesi taivasta kohti, niin Egyptin maahan tulee sellainen pimeys, että siihen voi käsin tarttua".'),
(1670724,58,2,10,22,'Ja Mooses ojensi kätensä taivasta kohti, ja koko Egyptin maahan tuli synkeä pimeys kolmeksi päiväksi.'),
(1670725,58,2,10,23,'Ei kukaan voinut nähdä toistansa, eikä kukaan voinut liikkua paikaltansa kolmeen päivään. Mutta kaikilla israelilaisilla oli valoisata asuinpaikoissansa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670726,58,2,10,24,'Niin farao kutsui Mooseksen ja sanoi: "Menkää ja palvelkaa Herraa; ainoastaan lampaanne ja karjanne jääkööt tänne. Myöskin vaimonne ja lapsenne menkööt teidän mukananne."'),
(1670727,58,2,10,25,'Mutta Mooses sanoi: "Sinun on annettava mukaamme myös teurasuhrit ja polttouhrit, uhrataksemme niitä Herralle, Jumalallemme.'),
(1670728,58,2,10,26,'Karjammekin täytyy tulla meidän kanssamme, ei sorkkaakaan saa jäädä, sillä siitä meidän on otettava uhrit palvellaksemme Herraa, Jumalaamme, emmekä itsekään tiedä, ennenkuin tulemme sinne, mitä meidän on uhrattava palvellessamme Herraa."'),
(1670729,58,2,10,27,'Mutta Herra paadutti faraon sydämen, niin että hän ei tahtonut päästää heitä.'),
(1670730,58,2,10,28,'Ja farao sanoi hänelle: "Mene pois luotani ja varo, ettet enää tule minun kasvojeni eteen; sillä sinä päivänä, jona tulet minun kasvojeni eteen, sinä olet kuoleva".'),
(1670731,58,2,10,29,'Mooses vastasi: "Oikein sinä puhuit; minä en tule tämän jälkeen sinun kasvojesi eteen".'),
(1670732,58,2,11,1,'Sitten Herra sanoi Moosekselle: "Vielä yhden vitsauksen minä annan tulla faraolle ja Egyptiin; sen jälkeen hän päästää teidät täältä. Ja kun hän todella päästää teidät, niin hän ajamalla ajaa teidät täältä.'),
(1670733,58,2,11,2,'Puhu siis nyt kansalle, että he, jokainen mies ja jokainen vaimo, pyytävät lähimmäisiltänsä hopea- ja kultakaluja."'),
(1670734,58,2,11,3,'Ja Herra antoi kansan päästä egyptiläisten suosioon. Myöskin Mooses oli hyvin arvossapidetty mies Egyptin maassa, sekä faraon palvelijain että kansan silmissä.'),
(1670735,58,2,11,4,'Ja Mooses sanoi: "Näin sanoo Herra: Puoliyön aikana minä lähden kulkemaan kautta Egyptin maan.'),
(1670736,58,2,11,5,'Ja kaikki esikoiset Egyptin maassa kuolevat, valtaistuimellansa istuvan faraon esikoisesta käsikiveä vääntävän orjattaren esikoiseen asti, ynnä kaikki karjan esikoiset.'),
(1670737,58,2,11,6,'Ja koko Egyptin maassa on oleva kova valitus, jonka kaltaista ei ole ollut eikä koskaan tule.'),
(1670738,58,2,11,7,'Mutta kenellekään israelilaiselle ei koirakaan ole muriseva, ei ihmiselle eikä eläimelle, tietääksesi, että Herra tekee erotuksen egyptiläisten ja Israelin välillä.'),
(1670739,58,2,11,8,'Ja kaikki nämä sinun palvelijasi tulevat minun luokseni, kumartavat minua ja sanovat: ''Mene pois, sinä ja kaikki kansa, joka sinua seuraa''. Ja sen jälkeen minä menen." Ja niin hän lähti faraon luota vihasta hehkuen.'),
(1670740,58,2,11,9,'Mutta Herra sanoi Moosekselle: "Farao ei kuule teitä, että paljon minun ihmeitäni tapahtuisi Egyptin maassa".'),
(1670741,58,2,11,10,'Ja Mooses ja Aaron tekivät kaikki nämä ihmeet faraon edessä; mutta Herra paadutti faraon sydämen, niin ettei hän päästänyt israelilaisia maastansa.'),
(1670742,58,2,12,1,'Ja Herra puhui Moosekselle ja Aaronille Egyptin maassa sanoen:'),
(1670743,58,2,12,2,'"Tämä kuukausi olkoon teillä kuukausista ensimmäinen; siitä alottakaa vuoden kuukaudet.'),
(1670744,58,2,12,3,'Puhukaa koko Israelin kansalle ja sanokaa: Tämän kuun kymmenentenä päivänä ottakoon kukin perheenisäntä itsellensä karitsan, yhden karitsan joka perhekuntaa kohti.'),
(1670745,58,2,12,4,'Mutta jos perhe on liian pieni koko karitsaa syömään, niin ottakoon lähimmän naapurinsa kanssa yhteisen karitsan, henkilöluvun mukaan. Karitsaa kohti laskekaa niin monta, että voivat sen syödä.'),
(1670746,58,2,12,5,'Ja karitsanne olkoon virheetön, vuoden vanha urospuoli; lampaista tai vuohista se ottakaa.'),
(1670747,58,2,12,6,'Ja pitäkää se tallella neljänteentoista päivään tätä kuuta; silloin Israelin koko seurakunta teurastakoon sen iltahämärässä.'),
(1670748,58,2,12,7,'Ja he ottakoot sen verta ja sivelkööt sillä molemmat pihtipielet ja ovenpäällisen niissä taloissa, joissa he sitä syövät.'),
(1670749,58,2,12,8,'Ja he syökööt lihan samana yönä; tulessa paistettuna, happamattoman leivän ja katkerain yrttien kanssa he sen syökööt.'),
(1670750,58,2,12,9,'Älkää syökö siitä mitään raakana tai vedessä keitettynä, vaan tulessa paistettuna päineen, jalkoineen ja sisälmyksineen.'),
(1670751,58,2,12,10,'Älkääkä jättäkö siitä mitään huomenaamuksi; mutta jos jotakin siitä jäisi huomenaamuksi, niin polttakaa se tulessa.'),
(1670752,58,2,12,11,'Ja syökää se näin: kupeet vyötettyinä, kengät jalassanne ja sauva kädessänne; ja syökää se kiiruusti. Tämä on pääsiäinen Herran kunniaksi.'),
(1670753,58,2,12,12,'Sillä minä kuljen sinä yönä kautta Egyptin maan ja surmaan kaikki esikoiset Egyptin maassa, sekä ihmiset että eläimet, ja panen toimeen rangaistustuomion, jonka minä olen langettanut kaikista Egyptin jumalista. Minä olen Herra.'),
(1670754,58,2,12,13,'Ja veri on oleva merkki, teille suojelukseksi, taloissa, joissa olette; sillä kun minä näen veren, niin minä menen teidän ohitsenne, eikä rangaistus ole tuhoava teitä, kun minä rankaisen Egyptin maata.'),
(1670755,58,2,12,14,'Ja tämä päivä olkoon teille muistopäivä, ja viettäkää sitä Herran juhlana; sukupolvesta sukupolveen viettäkää sitä ikuisena säädöksenä.'),
(1670756,58,2,12,15,'Seitsemän päivää syökää happamatonta leipää; jo ensimmäisenä päivänä korjatkaa pois hapan taikina taloistanne. Sillä jokainen, joka hapanta syö, ensimmäisestä päivästä seitsemänteen päivään asti, hävitettäköön Israelista.'),
(1670757,58,2,12,16,'Ensimmäisenä päivänä pitäkää pyhä kokous ja samoin myös seitsemäntenä päivänä pyhä kokous. Mitään työtä älköön tehtäkö niinä päivinä; ainoastaan se, mitä kukin tarvitsee ruuaksi, ainoastaan se valmistettakoon.'),
(1670758,58,2,12,17,'Ja pitäkää tätä happamattoman leivän juhlaa, sillä juuri sinä päivänä minä vein teidän joukkonne pois Egyptin maasta; sentähden pitäkää tätä päivää, sukupolvesta sukupolveen, ikuisena säädöksenä.'),
(1670759,58,2,12,18,'Ensimmäisessä kuussa, kuukauden neljäntenätoista päivänä, ehtoolla, syökää happamatonta leipää, ja niin tehkää aina saman kuun yhdennenkolmatta päivän ehtooseen asti.'),
(1670760,58,2,12,19,'Seitsemään päivään älköön hapanta taikinaa olko teidän taloissanne; sillä jokainen, joka hapanta leipää syö, hävitettäköön Israelin kansasta, olipa hän muukalainen tai maassasyntynyt.'),
(1670761,58,2,12,20,'Älkää syökö mitään hapanta, vaan syökää happamatonta leipää, missä asuttekin."'),
(1670762,58,2,12,21,'Ja Mooses kutsui kaikki Israelin vanhimmat ja sanoi heille: "Menkää ja ottakaa lammas kutakin perhekuntaanne kohti ja teurastakaa pääsiäislammas.'),
(1670763,58,2,12,22,'Ja ottakaa isoppikimppu, kastakaa se vereen, joka on maljassa, ja sivelkää ovenpäällinen ja molemmat pihtipielet sillä verellä, joka on maljassa. Älköönkä kukaan menkö ulos talonsa ovesta ennen aamua.'),
(1670764,58,2,12,23,'Sillä Herra kulkee rankaisemassa egyptiläisiä; mutta kun Herra näkee veren ovenpäällisessä ja molemmissa pihtipielissä, menee hän sen oven ohi eikä salli tuhoojan tulla teidän taloihinne teitä vitsauksella lyömään.'),
(1670765,58,2,12,24,'Noudattakaa tätä; se olkoon ikuinen säädös sinulle ja sinun lapsillesi.'),
(1670766,58,2,12,25,'Ja kun te tulette siihen maahan, jonka Herra on teille antava, niinkuin hän on sanonut, niin noudattakaa näitä menoja.'),
(1670767,58,2,12,26,'Kun sitten lapsenne kysyvät teiltä: ''Mitä nämä menot merkitsevät?'''),
(1670768,58,2,12,27,'niin vastatkaa: ''Tämä on pääsiäisuhri Herralle, joka meni israelilaisten talojen ohi Egyptissä, kun hän rankaisi egyptiläisiä, mutta säästi meidän kotimme''." Silloin kansa kumartui maahan ja rukoili.'),
(1670769,58,2,12,28,'Ja israelilaiset menivät ja tekivät, niinkuin Herra oli Moosekselle ja Aaronille käskyn antanut; niin he tekivät.'),
(1670770,58,2,12,29,'Ja puoliyön aikana tapahtui, että Herra surmasi kaikki Egyptin maan esikoiset, valtaistuimellaan istuvan faraon esikoisesta vankikuopassa olevan vangin esikoiseen asti, ynnä kaikki karjan esikoiset.'),
(1670771,58,2,12,30,'Niin farao nousi sinä yönä ja kaikki hänen palvelijansa ynnä kaikki egyptiläiset, ja kova valitus oli Egyptissä; sillä ei ollut yhtään taloa, jossa ei ollut kuollutta.'),
(1670772,58,2,12,31,'Ja hän kutsutti yöllä Mooseksen ja Aaronin ja sanoi: "Nouskaa ja menkää pois minun kansani joukosta, sekä te että israelilaiset; menkää ja palvelkaa Herraa, niinkuin olette puhuneet.'),
(1670773,58,2,12,32,'Ottakaa myös lampaanne ja karjanne mukaanne, niinkuin olette puhuneet, ja menkää ja rukoilkaa minullekin siunausta."'),
(1670774,58,2,12,33,'Ja egyptiläiset ahdistivat kansaa jouduttaaksensa heidän lähtöänsä maasta pois, sillä he ajattelivat: "Me kuolemme kaikki".'),
(1670775,58,2,12,34,'Ja kansa otti taikinansa, ennenkuin se oli hapannut, ja kantoi taikinakaukalonsa vaippoihin käärittyinä olkapäillään.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670776,58,2,12,35,'Ja israelilaiset olivat tehneet Mooseksen sanan mukaan: he olivat pyytäneet egyptiläisiltä hopea- ja kultakaluja sekä vaatteita.'),
(1670777,58,2,12,36,'Ja Herra oli antanut kansan päästä egyptiläisten suosioon, niin että nämä suostuivat heidän pyyntöönsä; ja niin he veivät saalista egyptiläisiltä.'),
(1670778,58,2,12,37,'Ja israelilaiset lähtivät liikkeelle ja kulkivat Ramseksesta Sukkotiin; heitä oli noin kuusisataa tuhatta jalkamiestä, paitsi vaimoja ja lapsia.'),
(1670779,58,2,12,38,'Ja myös paljon sekakansaa meni heidän kanssansa, sekä lampaita ja raavaskarjaa suuret laumat.'),
(1670780,58,2,12,39,'Ja he leipoivat siitä taikinasta, jonka olivat tuoneet Egyptistä, happamattomia leipiä; sillä se ei ollut hapannut, kun heidät karkoitettiin Egyptistä. He eivät olleet saaneet viipyä, eivätkä he myöskään olleet valmistaneet itsellensä evästä.'),
(1670781,58,2,12,40,'Mutta aika, jonka israelilaiset olivat asuneet Egyptissä, oli neljäsataa kolmekymmentä vuotta.'),
(1670782,58,2,12,41,'Kun ne neljäsataa kolmekymmentä vuotta olivat kuluneet, niin juuri sinä päivänä kaikki Herran joukot lähtivät Egyptin maasta.'),
(1670783,58,2,12,42,'Valvontayö Herran kunniaksi on tämä yö, koska hän silloin vei heidät pois Egyptin maasta; tämän yön kaikki israelilaiset valvokoot Herran kunniaksi, sukupolvesta sukupolveen.'),
(1670784,58,2,12,43,'Ja Herra sanoi Moosekselle ja Aaronille: "Tämä on säädös pääsiäislampaasta: Kukaan muukalainen älköön siitä syökö;'),
(1670785,58,2,12,44,'mutta jokainen rahalla ostettu orja syököön siitä, kunhan olet ympärileikannut hänet.'),
(1670786,58,2,12,45,'Loinen ja päiväpalkkalainen älkööt siitä syökö.'),
(1670787,58,2,12,46,'Samassa talossa se syötäköön; älköön mitään siitä lihasta vietäkö talosta ulos, älkääkä siitä luuta rikkoko.'),
(1670788,58,2,12,47,'Koko Israelin seurakunta viettäköön sitä ateriaa.'),
(1670789,58,2,12,48,'Ja jos joku muukalainen asuu sinun luonasi ja tahtoo viettää pääsiäistä Herran kunniaksi, niin ympärileikkauttakoon kaikki miehenpuolensa ja sitten käyköön sitä viettämään ja olkoon silloin niinkuin maassasyntynyt. Mutta yksikään ympärileikkaamaton älköön siitä syökö.'),
(1670790,58,2,12,49,'Sama laki olkoon maassasyntyneellä ja muukalaisella, joka asuu teidän keskuudessanne."'),
(1670791,58,2,12,50,'Ja kaikki israelilaiset tekivät, niinkuin Herra oli Moosekselle ja Aaronille käskyn antanut; niin he tekivät. Ja juuri sinä päivänä Herra vei israelilaiset joukkoinensa pois Egyptin maasta.'),
(1670792,58,2,13,1,'Ja Herra puhui Moosekselle sanoen:'),
(1670793,58,2,13,2,'"Pyhitä minulle jokainen esikoinen, jokainen, joka israelilaisten seassa, sekä ihmisistä että karjasta, avaa äidinkohdun; se on minun".'),
(1670794,58,2,13,3,'Ja Mooses sanoi kansalle: "Muistakaa tämä päivä, jona te lähditte Egyptistä, orjuuden pesästä; sillä Herra vei teidät sieltä pois väkevällä kädellä. Sentähden älköön mitään hapanta syötäkö.'),
(1670795,58,2,13,4,'Tänä päivänä aabib-kuussa te lähditte.'),
(1670796,58,2,13,5,'Ja kun Herra vie sinut kanaanilaisten, heettiläisten, amorilaisten, hivviläisten ja jebusilaisten maahan, jonka hän sinun isillesi vannotulla valalla on luvannut antaa sinulle, siihen maahan, joka vuotaa maitoa ja mettä, niin vietä tämä jumalanpalvelus tässä kuussa.'),
(1670797,58,2,13,6,'Syö seitsemänä päivänä happamatonta leipää, ja seitsemäntenä päivänä olkoon Herran juhla.'),
(1670798,58,2,13,7,'Happamatonta leipää syötäköön näinä seitsemänä päivänä; älköön mitään hapanta olko, älköön olko hapanta taikinaa koko sinun maassasi.'),
(1670799,58,2,13,8,'Ja kerro pojallesi sinä päivänä ja sano: ''Näin tehdään sen johdosta, mitä Herra minulle teki, kun minä lähdin Egyptistä''.'),
(1670800,58,2,13,9,'Ja se olkoon merkkinä sinun kädessäsi ja muistutuksena sinun otsallasi, että Herran laki olisi sinun suussasi; sillä Herra vei sinut väkevällä kädellä pois Egyptistä.'),
(1670801,58,2,13,10,'Sentähden noudata tätä säädöstä määräaikanansa vuodesta vuoteen.'),
(1670802,58,2,13,11,'Ja kun Herra on vienyt sinut kanaanilaisten maahan, niinkuin hän on sinulle ja sinun isillesi vannonut, ja kun hän on sen sinulle antanut,'),
(1670803,58,2,13,12,'niin luovuta Herralle kaikki, mikä avaa äidinkohdun; ja kaikki ensiksisyntyneet karjastasi, urospuolet, olkoot Herran.'),
(1670804,58,2,13,13,'Mutta jokainen aasin ensiksisynnyttämä lunasta lampaalla; mutta jos et sitä lunasta, niin taita siltä niska. Ja lunasta jokainen ihmisen esikoinen poikiesi seassa.'),
(1670805,58,2,13,14,'Ja kun sinun poikasi vastaisuudessa kysyy sinulta ja sanoo: ''Mitä tämä merkitsee?'' niin vastaa hänelle: ''Herra vei meidät väkevällä kädellä pois Egyptistä, orjuuden pesästä.'),
(1670806,58,2,13,15,'Sillä kun farao paatui ja kieltäytyi päästämästä meitä, surmasi Herra kaikki esikoiset Egyptin maassa, ihmisten esikoisista karjan esikoisiin asti. Sentähden minä uhraan Herralle jokaisen urospuolen, joka avaa äidinkohdun, ja jokaisen esikoisen pojistani minä lunastan.'''),
(1670807,58,2,13,16,'Ja se olkoon merkkinä sinun kädessäsi ja muistolauseena sinun otsallasi; sillä Herra vei meidät väkevällä kädellä pois Egyptistä."'),
(1670808,58,2,13,17,'Mutta kun farao oli päästänyt kansan, ei Jumala johdattanut heitä sitä tietä, joka kulki filistealaisten maan kautta, vaikka se oli suorin, sillä Jumala ajatteli, että kansa ehkä katuisi nähdessänsä sodan syttyvän ja palaisi Egyptiin;'),
(1670809,58,2,13,18,'vaan Jumala antoi kansan poiketa erämaan tietä myöten Kaislamerta kohti. Ja taisteluun valmiina israelilaiset lähtivät Egyptin maasta.'),
(1670810,58,2,13,19,'Ja Mooses otti mukaansa Joosefin luut; sillä tämä oli vannottanut israelilaisia ja sanonut: "Kun Jumala pitää huolen teistä, viekää silloin minun luuni täältä mukananne".'),
(1670811,58,2,13,20,'Ja he lähtivät liikkeelle Sukkotista ja leiriytyivät Eetamiin, erämaan reunaan.'),
(1670812,58,2,13,21,'Ja Herra kulki heidän edellänsä, päivällä pilvenpatsaassa johdattaaksensa heitä tietä myöten ja yöllä tulenpatsaassa valaistaksensa heidän kulkunsa, niin että he voivat vaeltaa sekä päivällä että yöllä.'),
(1670813,58,2,13,22,'Pilvenpatsas ei poistunut päivällä eikä tulenpatsas yöllä kansan edestä.'),
(1670814,58,2,14,1,'Herra puhui Moosekselle sanoen:'),
(1670815,58,2,14,2,'"Sano israelilaisille, että he kääntyvät takaisin ja leiriytyvät Pii-Hahirotin kohdalle Migdolin ja meren välille; leiriytykää vastapäätä Baal-Sefonia meren rannalle.'),
(1670816,58,2,14,3,'Ja farao on ajatteleva, että israelilaiset ovat eksyneet maassa ja että erämaa on saartanut heidät.'),
(1670817,58,2,14,4,'Ja minä paadutan faraon sydämen, niin että hän ajaa heitä takaa; mutta minä näytän kunniani tuhoamalla faraon ja koko hänen sotajoukkonsa; ja niin egyptiläiset tulevat tietämään, että minä olen Herra." Ja he tekivät niin.'),
(1670818,58,2,14,5,'Kun Egyptin kuninkaalle ilmoitettiin, että kansa oli paennut, muuttui faraon ja hänen palvelijainsa mieli kansaa kohtaan, ja he sanoivat: "Mitä teimmekään, kun päästimme Israelin meitä palvelemasta!"'),
(1670819,58,2,14,6,'Ja hän valjastutti hevoset sotavaunujensa eteen ja otti väkensä mukaansa;'),
(1670820,58,2,14,7,'ja hän otti kuudetsadat valitut sotavaunut sekä kaikki muut Egyptin sotavaunut ynnä vaunusoturit niihin kaikkiin.'),
(1670821,58,2,14,8,'Sillä Herra paadutti faraon, Egyptin kuninkaan, sydämen, niin että hän lähti ajamaan takaa israelilaisia, vaikka israelilaiset olivat lähteneet matkaan voimallisen käden suojassa.'),
(1670822,58,2,14,9,'Ja egyptiläiset, kaikki faraon hevoset, sotavaunut ja ratsumiehet ja koko hänen sotajoukkonsa, ajoivat heitä takaa ja saavuttivat heidät leiriytyneinä meren rannalle, Pii-Hahirotin kohdalle, vastapäätä Baal-Sefonia.'),
(1670823,58,2,14,10,'Ja kun farao oli lähellä, nostivat israelilaiset silmänsä ja näkivät, että egyptiläiset olivat tulossa heidän jäljessänsä. Silloin israelilaiset peljästyivät kovin ja huusivat Herraa.'),
(1670824,58,2,14,11,'Ja he sanoivat Moosekselle: "Eikö Egyptissä ollut hautoja, kun toit meidät tänne erämaahan kuolemaan? Mitä teit meille, kun johdatit meidät pois Egyptistä!'),
(1670825,58,2,14,12,'Emmekö sanoneet tätä sinulle Egyptissä? Sanoimmehan: Anna meidän olla rauhassa, että palvelisimme egyptiläisiä. Sillä parempi olisi ollut palvella egyptiläisiä kuin kuolla erämaahan."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670826,58,2,14,13,'Mooses vastasi kansalle: "Älkää peljätkö; pysykää paikoillanne, niin te näette, minkä pelastuksen Herra tänä päivänä antaa teille; sillä sellaista, minkä näette egyptiläisille tapahtuvan tänä päivänä, ette koskaan enää tule näkemään.'),
(1670827,58,2,14,14,'Herra sotii teidän puolestanne, ja te olkaa hiljaa."'),
(1670828,58,2,14,15,'Ja Herra sanoi Moosekselle: "Miksi huudat minulle? Sano israelilaisille, että he lähtevät liikkeelle.'),
(1670829,58,2,14,16,'Mutta sinä nosta sauvasi ja ojenna kätesi meren yli ja halkaise se, niin että israelilaiset voivat käydä meren poikki kuivaa myöten.'),
(1670830,58,2,14,17,'Ja katso, minä paadutan egyptiläisten sydämet, niin että he tulevat heidän perässänsä; minä näytän kunniani tuhoamalla faraon ja koko hänen sotajoukkonsa, hänen sotavaununsa ja ratsumiehensä.'),
(1670831,58,2,14,18,'Ja egyptiläiset tulevat tietämään, että minä olen Herra, kun minä näytän kunniani tuhoamalla faraon, hänen sotavaununsa ja ratsumiehensä."'),
(1670832,58,2,14,19,'Niin Jumalan enkeli, joka oli kulkenut Israelin joukon edellä, siirtyi kulkemaan heidän takanansa; ja pilvenpatsas siirtyi heidän edeltänsä ja asettui heidän taaksensa'),
(1670833,58,2,14,20,'ja tuli egyptiläisten joukon ja Israelin joukon väliin; ja pilvi oli pimeä noille ja valaisi yön näille. Näin koko yönä toinen joukko ei voinut lähestyä toista.'),
(1670834,58,2,14,21,'Ja Mooses ojensi kätensä meren yli. Niin Herra saattoi vahvalla itätuulella, joka puhalsi koko yön, meren väistymään ja muutti meren kuivaksi maaksi; ja vesi jakautui kahtia.'),
(1670835,58,2,14,22,'Ja israelilaiset kulkivat meren poikki kuivaa myöten, ja vesi oli heillä muurina sekä oikealla että vasemmalla puolella.'),
(1670836,58,2,14,23,'Ja egyptiläiset, kaikki faraon hevoset, hänen sotavaununsa ja ratsumiehensä, ajoivat heitä takaa ja tulivat heidän perässänsä keskelle merta.'),
(1670837,58,2,14,24,'Kun aamuvartio tuli, katsahti Herra egyptiläisten joukkoa tulenpatsaasta ja pilvestä ja saattoi hämminkiin egyptiläisten joukon.'),
(1670838,58,2,14,25,'Ja hän antoi heidän vaunujensa pyöräin irtautua, niin että heille kävi vaikeaksi päästä eteenpäin. Niin egyptiläiset sanoivat: "Paetkaamme Israelia, sillä Herra sotii heidän puolestansa egyptiläisiä vastaan".'),
(1670839,58,2,14,26,'Mutta Herra sanoi Moosekselle: "Ojenna kätesi meren yli, että vedet palautuisivat ja peittäisivät egyptiläiset, heidän sotavaununsa ja ratsumiehensä".'),
(1670840,58,2,14,27,'Niin Mooses ojensi kätensä meren yli, ja aamun koittaessa meri palasi paikoillensa, egyptiläisten paetessa sitä vastaan; ja Herra syöksi egyptiläiset keskelle merta.'),
(1670841,58,2,14,28,'Ja vedet palasivat ja peittivät sotavaunut ja ratsumiehet, koko faraon sotajoukon, joka oli seurannut heitä mereen; ei yksikään heistä pelastunut.'),
(1670842,58,2,14,29,'Mutta israelilaiset kulkivat kuivaa myöten meren poikki, ja vesi oli heillä muurina sekä oikealla että vasemmalla puolella.'),
(1670843,58,2,14,30,'Niin Herra pelasti Israelin sinä päivänä egyptiläisten käsistä, ja Israel näki egyptiläiset kuolleina meren rannalla.'),
(1670844,58,2,14,31,'Ja Israel näki sen suuren teon, jonka Herra teki tuhotessaan egyptiläiset. Silloin kansa pelkäsi Herraa ja uskoi Herraan ja uskoi hänen palvelijaansa Moosesta.'),
(1670845,58,2,15,1,'Silloin Mooses ja israelilaiset veisasivat Herralle tämän virren; he sanoivat näin: "Minä veisaan Herralle, sillä hän on ylen korkea; hevoset ja miehet hän mereen syöksi.'),
(1670846,58,2,15,2,'Herra on minun väkevyyteni ja ylistysvirteni, ja hänestä tuli minulle pelastus. Hän on minun Jumalani, ja minä ylistän häntä, hän on minun isäni Jumala, ja minä kunnioitan häntä.'),
(1670847,58,2,15,3,'Herra on sotasankari, Herra on hänen nimensä.'),
(1670848,58,2,15,4,'Faraon vaunut ja hänen sotajoukkonsa hän suisti mereen, hänen valitut vaunusoturinsa hukkuivat Kaislamereen.'),
(1670849,58,2,15,5,'Syvyys peitti heidät; he vajosivat pohjaan niinkuin kivi.'),
(1670850,58,2,15,6,'Sinun oikea kätesi, Herra, sinä voimassa jalo, sinun oikea kätesi, Herra, murskaa vihollisen.'),
(1670851,58,2,15,7,'Valtasuuruudessasi sinä kukistat vastustajasi. Sinä päästät vihasi valloilleen, ja se kuluttaa heidät niinkuin korret.'),
(1670852,58,2,15,8,'Ja sinun vihasi puhalluksesta kasaantuivat vedet, laineet seisahtuivat roukkioiksi, syvyyden aallot hyytyivät keskelle merta.'),
(1670853,58,2,15,9,'Vihollinen sanoi: ''Minä ajan takaa, minä saavutan heidät, minä jaan saaliin ja tyydytän heissä kostonhimoni; minä paljastan miekkani, minun käteni hävittää heidät''.'),
(1670854,58,2,15,10,'Sinun tuulesi puhalsi, ja meri peitti heidät; he upposivat valtavesiin niinkuin lyijy.'),
(1670855,58,2,15,11,'Herra, kuka on sinun vertaisesi jumalien joukossa! Kuka on sinun vertaisesi, sinä pyhyydessä jalo; sinä ylistettävissä teoissa peljättävä, sinä ihmeitten tekijä!'),
(1670856,58,2,15,12,'Sinä ojensit oikean kätesi, maa nielaisi heidät.'),
(1670857,58,2,15,13,'Mutta armossasi sinä johdatit lunastamaasi kansaa, sinä veit sen voimallasi pyhään asuntoosi.'),
(1670858,58,2,15,14,'Kansat kuulivat sen ja vapisivat, tuska valtasi Filistean asukkaat.'),
(1670859,58,2,15,15,'Silloin peljästyivät Edomin ruhtinaat, Mooabin sankarit valtasi vavistus, kaikki Kanaanin asukkaat menehtyivät pelkoon.'),
(1670860,58,2,15,16,'Kauhu ja väristys valtasi heidät; sinun käsivartesi väkevyyden tähden he kävivät mykiksi niinkuin kivi. Niin sinun kansasi, Herra, kulkee perille, kulkee perille se kansa, jonka olet itsellesi hankkinut.'),
(1670861,58,2,15,17,'Sinä viet heidät perille ja istutat heidät vuorelle, joka on sinun perintöosasi, paikkaan, jonka sinä, Herra, olet asunnoksesi valmistanut, pyhäkköösi, Herra, jonka sinun kätesi ovat tehneet.'),
(1670862,58,2,15,18,'Herra on kuningas aina ja iankaikkisesti."'),
(1670863,58,2,15,19,'Sillä kun faraon hevoset ja hänen sotavaununsa ja ratsumiehensä menivät mereen, palautti Herra meren vedet heidän päällensä; mutta israelilaiset kulkivat kuivaa myöten meren poikki.'),
(1670864,58,2,15,20,'Ja naisprofeetta Mirjam, Aaronin sisar, otti vaskirummun käteensä, ja kaikki naiset seurasivat häntä vaskirumpuja lyöden ja karkeloiden.'),
(1670865,58,2,15,21,'Ja Mirjam viritti heille virren: "Veisatkaa Herralle, sillä hän on ylen korkea, hevoset ja miehet hän mereen syöksi".'),
(1670866,58,2,15,22,'Sitten Mooses antoi israelilaisten lähteä liikkeelle Kaislameren luota, ja he menivät Suurin erämaahan. Ja he vaelsivat kolme päivää erämaassa löytämättä vettä.'),
(1670867,58,2,15,23,'Sitten he tulivat Maaraan; mutta he eivät voineet juoda Maaran vettä; sillä se oli karvasta. Sentähden paikka sai nimen Maara.'),
(1670868,58,2,15,24,'Niin kansa napisi Moosesta vastaan ja sanoi: "Mitä me juomme?"'),
(1670869,58,2,15,25,'Mutta hän huusi Herran puoleen; ja Herra osoitti hänelle puun, jonka hän heitti veteen, ja vesi tuli makeaksi. Siellä hän antoi kansalle lain ja oikeuden, ja siellä hän koetteli sitä.'),
(1670870,58,2,15,26,'Hän sanoi: "Jos sinä kuulet Herraa, Jumalaasi, ja teet, mikä on oikein hänen silmissänsä, tarkkaat hänen käskyjänsä ja noudatat kaikkea hänen lakiansa, niin minä en pane sinun kärsittäväksesi yhtäkään niistä vaivoista, jotka olen pannut egyptiläisten kärsittäviksi, sillä minä olen Herra, sinun parantajasi".'),
(1670871,58,2,15,27,'Sitten he tulivat Eelimiin; siellä oli kaksitoista vesilähdettä ja seitsemänkymmentä palmupuuta. Ja he leiriytyivät siellä veden ääreen.'),
(1670872,58,2,16,1,'Sitten he lähtivät, koko Israelin kansa, liikkeelle Eelimistä ja tulivat Siinin erämaahan, joka on Eelimin ja Siinain välillä, toisen kuun viidentenätoista päivänä siitä, kun he olivat lähteneet Egyptin maasta.'),
(1670873,58,2,16,2,'Ja koko Israelin kansa napisi Moosesta ja Aaronia vastaan erämaassa;'),
(1670874,58,2,16,3,'ja israelilaiset sanoivat heille: "Jospa olisimme saaneet surmamme Herran kädestä Egyptin maassa, jossa istuimme lihapatain ääressä ja leipää oli kyllin syödäksemme! Mutta te olette tuoneet meidät tähän erämaahan antaaksenne koko tämän joukon kuolla nälkään."'),
(1670875,58,2,16,4,'Niin Herra sanoi Moosekselle: "Katso, minä annan sataa teille leipää taivaasta. Ja kansa menköön ja kootkoon kunakin päivänä sen päivän tarpeen. Näin minä koettelen heitä, vaeltavatko he minun lakini mukaan vai eivät.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670876,58,2,16,5,'Ja kun he kuudentena päivänä valmistavat sen, mitä ovat tuoneet kotiin, niin sitä on oleva kaksi kertaa niin paljon, kuin mitä he muutoin joka päivä kokoavat."'),
(1670877,58,2,16,6,'Ja Mooses ja Aaron sanoivat kaikille israelilaisille: "Tänä iltana te tulette tietämään, että Herra on vienyt teidät pois Egyptin maasta,'),
(1670878,58,2,16,7,'ja huomenaamuna te tulette näkemään Herran kunnian, koska Herra on kuullut teidän napinanne häntä vastaan. Sillä mitä olemme me, että te meitä vastaan napisette?"'),
(1670879,58,2,16,8,'Ja Mooses sanoi vielä: "Herra antaa teille tänä iltana lihaa syödäksenne ja huomenna leipää yltäkyllin ravinnoksenne, koska Herra on kuullut teidän napinanne, kun olette napisseet häntä vastaan. Sillä mitä olemme me? Ette ole napisseet meitä vastaan, vaan Herraa vastaan."'),
(1670880,58,2,16,9,'Ja Mooses sanoi Aaronille: "Sano koko Israelin kansalle: Astukaa Herran eteen, sillä hän on kuullut teidän napinanne".'),
(1670881,58,2,16,10,'Ja kun Aaron oli puhunut tämän koko Israelin seurakunnalle, kääntyivät he erämaahan päin, ja katso, Herran kunnia näkyi pilvessä.'),
(1670882,58,2,16,11,'Ja Herra puhui Moosekselle sanoen:'),
(1670883,58,2,16,12,'"Minä olen kuullut israelilaisten napinan. Puhu heille ja sano: Iltahämärässä teillä on oleva lihaa syödäksenne, ja huomenna on teillä leipää yltäkyllin; niin te tulette tietämään, että minä olen Herra, teidän Jumalanne."'),
(1670884,58,2,16,13,'Ja illalla tuli viiriäisiä, ja ne peittivät leirin, ja aamulla laskeutui kastesumu leirin ympärille.'),
(1670885,58,2,16,14,'Ja kun kastesumu oli haihtunut, katso, erämaassa oli maan pinnalla jotakin hienoa, suomujen tapaista, jotakin hienoa niinkuin härmä.'),
(1670886,58,2,16,15,'Kun israelilaiset näkivät sen, kyselivät he toisiltansa: "Mitä tämä on?" Sillä he eivät tienneet, mitä se oli. Ja Mooses sanoi heille: "Tämä on se leipä, jonka Herra on antanut teille syötäväksi.'),
(1670887,58,2,16,16,'Ja näin on Herra käskenyt: Kootkaa sitä, jokainen tarpeenne mukaan; ottakaa goomer-mitta mieheen perheenne pääluvun mukaan, kukin niin monelle, kuin kullakin majassansa on."'),
(1670888,58,2,16,17,'Ja israelilaiset tekivät niin, ja he kokosivat, yksi enemmän, toinen vähemmän.'),
(1670889,58,2,16,18,'Mutta kun he mittasivat sen goomer-mitalla, niin ei sille jäänyt liikaa, joka oli koonnut enemmän, eikä siltä puuttunut, joka oli koonnut vähemmän; jokainen oli koonnut niin paljon, kuin hän tarvitsi.'),
(1670890,58,2,16,19,'Ja Mooses sanoi heille: "Älköön kukaan jättäkö siitä mitään huomiseksi".'),
(1670891,58,2,16,20,'Mutta he eivät kuulleet Moosesta, vaan muutamat jättivät siitä jotakin huomiseksi. Niin siihen kasvoi matoja, ja se rupesi haisemaan; ja Mooses vihastui heihin.'),
(1670892,58,2,16,21,'Ja he kokosivat sitä joka aamu sen verran, kuin kukin tarvitsi; mutta kun aurinko alkoi paahtaa, niin se suli.'),
(1670893,58,2,16,22,'Mutta kuudentena päivänä he kokosivat sitä leipää kaksinkertaisesti, kaksi goomeria kullekin. Ja kaikki kansan päämiehet tulivat ja ilmoittivat sen Moosekselle.'),
(1670894,58,2,16,23,'Niin hän sanoi heille: "Tämä tapahtuu Herran sanan mukaan; huomenna on levon päivä, Herralle pyhitetty sapatti. Mitä leivotte, se leipokaa, ja mitä keitätte, se keittäkää; mutta kaikki, mitä tähteeksi jää, pankaa talteen huomiseksi."'),
(1670895,58,2,16,24,'Ja he panivat sen talteen huomiseksi, niinkuin Mooses oli käskenyt, eikä se ruvennut haisemaan, eikä siihen tullut matoja.'),
(1670896,58,2,16,25,'Ja Mooses sanoi: "Syökää se tänä päivänä, sillä tänä päivänä on Herran sapatti; tänään ette löydä kedolta mitään.'),
(1670897,58,2,16,26,'Kuutena päivänä on teidän sitä koottava, mutta seitsemäntenä päivänä on sapatti; silloin ei sitä ole."'),
(1670898,58,2,16,27,'Kuitenkin muutamat kansasta lähtivät seitsemäntenä päivänä kokoamaan sitä, mutta he eivät löytäneet mitään.'),
(1670899,58,2,16,28,'Niin Herra sanoi Moosekselle: "Kuinka kauan aiotte kieltäytyä noudattamasta minun käskyjäni ja lakejani?'),
(1670900,58,2,16,29,'Katsokaa, Herra on antanut teille sapatin; sentähden hän antaa teille kuudentena päivänä kahden päivän leivän. Olkoon jokainen alallaan, älköönkä kukaan lähtekö paikaltansa seitsemäntenä päivänä."'),
(1670901,58,2,16,30,'Ja kansa lepäsi seitsemäntenä päivänä.'),
(1670902,58,2,16,31,'Ja Israelin heimo antoi sille nimen manna. Ja se oli valkean korianderinsiemenen kaltaista ja maistui hunajakakulta.'),
(1670903,58,2,16,32,'Ja Mooses sanoi: "Näin on Herra käskenyt: Ota sitä goomerin täysi säilytettäväksi sukupolvesta sukupolveen, että he näkisivät sen leivän, jolla minä olen ravinnut teitä erämaassa, johdattaessani teitä Egyptin maasta".'),
(1670904,58,2,16,33,'Ja Mooses sanoi Aaronille: "Ota astia ja pane siihen goomerin täysi mannaa ja aseta se Herran eteen säilytettäväksi sukupolvesta sukupolveen".'),
(1670905,58,2,16,34,'Ja Aaron asetti sen talteen lain arkin eteen, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1670906,58,2,16,35,'Ja israelilaiset söivät mannaa neljäkymmentä vuotta, kunnes he tulivat asuttuun maahan; he söivät mannaa siihen asti, kunnes tulivat Kanaanin maan rajalle. -'),
(1670907,58,2,16,36,'Goomer on kymmenesosa eefaa.'),
(1670908,58,2,17,1,'Sitten kaikki israelilaisten seurakunta lähti liikkeelle Siinin erämaasta ja matkusti levähdyspaikasta toiseen Herran käskyn mukaan. Ja he leiriytyivät Refidimiin; siellä ei ollut vettä kansan juoda.'),
(1670909,58,2,17,2,'Niin kansa riiteli Moosesta vastaan ja sanoi: "Antakaa meille vettä juoda!" Mooses vastasi heille: "Miksi riitelette minua vastaan? Miksi kiusaatte Herraa?"'),
(1670910,58,2,17,3,'Mutta kansalla oli siellä jano, ja he napisivat yhä Moosesta vastaan ja sanoivat: "Minkätähden olet tuonut meidät Egyptistä, antaaksesi meidän ja meidän lastemme ja karjamme kuolla janoon?"'),
(1670911,58,2,17,4,'Niin Mooses huusi Herraa ja sanoi: "Mitä minä teen tälle kansalle? Ei paljon puutu, että he kivittävät minut."'),
(1670912,58,2,17,5,'Herra vastasi Moosekselle: "Mene kansan edellä ja ota mukaasi muutamia Israelin vanhimpia. Ja ota käteesi sauva, jolla löit Niilivirtaa, ja mene.'),
(1670913,58,2,17,6,'Katso, minä seison siellä sinun edessäsi kalliolla Hoorebin luona; lyö kallioon, ja siitä on vuotava vettä, niin että kansa saa juoda." Ja Mooses teki niin Israelin vanhimpain nähden.'),
(1670914,58,2,17,7,'Ja hän antoi sille paikalle nimen Massa ja Meriba sentähden, että israelilaiset siellä riitelivät ja kiusasivat Herraa, sanoen: "Onko Herra meidän keskellämme vai ei?"'),
(1670915,58,2,17,8,'Sitten tulivat amalekilaiset ja taistelivat Israelia vastaan Refidimissä.'),
(1670916,58,2,17,9,'Niin Mooses sanoi Joosualle: "Valitse meille miehiä, mene ja taistele huomenna amalekilaisia vastaan. Minä asetun vuoren huipulle, Jumalan sauva kädessäni."'),
(1670917,58,2,17,10,'Ja Joosua teki, niinkuin Mooses oli hänelle sanonut, ja taisteli amalekilaisia vastaan. Mutta Mooses, Aaron ja Huur nousivat vuoren huipulle.'),
(1670918,58,2,17,11,'Ja niin kauan kuin Mooses piti kätensä ylhäällä, oli Israel voitolla; mutta kun hän antoi kätensä vaipua, olivat amalekilaiset voitolla.'),
(1670919,58,2,17,12,'Mutta kun Mooseksen kädet väsyivät, ottivat he kiven ja asettivat sen hänen allensa, ja hän istui sille, ja Aaron ja Huur kannattivat hänen käsiänsä kumpikin puoleltansa. Näin hänen kätensä kestivät vahvoina auringon laskuun asti.'),
(1670920,58,2,17,13,'Ja Joosua voitti amalekilaiset ja heidän sotaväkensä miekan terällä.'),
(1670921,58,2,17,14,'Ja Herra sanoi Moosekselle: "Kirjoita tämä kirjaan muistoksi ja teroita se Joosuan mieleen: Minä pyyhin pois amalekilaisten muiston taivaan alta".'),
(1670922,58,2,17,15,'Ja Mooses rakensi alttarin ja pani sille nimeksi: "Herra on minun lippuni".'),
(1670923,58,2,17,16,'Ja hän sanoi: "Minä nostan käteni Herran istuinta kohden: Herra sotii amalekilaisia vastaan sukupolvesta sukupolveen".'),
(1670924,58,2,18,1,'Ja Midianin pappi Jetro, Mooseksen appi, sai kuulla kaikki, mitä Jumala oli tehnyt Moosekselle ja kansalleen Israelille, kuinka Herra oli vienyt Israelin pois Egyptistä.'),
(1670925,58,2,18,2,'Ja Jetro, Mooseksen appi, otti mukaansa Sipporan, Mooseksen vaimon, jonka tämä oli lähettänyt kotiin,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670926,58,2,18,3,'ja hänen kaksi poikaansa; näistä oli toisen nimi Geersom, koska Mooses oli sanonut: "Minä olen muukalainen vieraalla maalla",'),
(1670927,58,2,18,4,'ja toisen nimi Elieser, koska hän oli sanonut: "Isäni Jumala oli minun apuni ja pelasti minut faraon miekasta".'),
(1670928,58,2,18,5,'Ja Jetro, Mooseksen appi, tuli hänen poikiensa ja hänen vaimonsa kanssa Mooseksen luo erämaahan, jossa tämä oli leiriytynyt Jumalan vuoren juurelle.'),
(1670929,58,2,18,6,'Ja hän käski sanoa Moosekselle: "Minä, Jetro, sinun appesi, ynnä vaimosi kahden poikansa kanssa olemme tulleet luoksesi".'),
(1670930,58,2,18,7,'Niin Mooses meni appeansa vastaan, kumarsi ja suuteli häntä. Ja kun he olivat tervehtineet toisiansa, menivät he telttaan.'),
(1670931,58,2,18,8,'Ja Mooses kertoi apellensa kaikki, mitä Herra oli tehnyt faraolle ja egyptiläisille Israelin tähden, ja kaikki ne vaikeudet, jotka heitä olivat kohdanneet matkalla, ja kuinka Herra oli pelastanut heidät.'),
(1670932,58,2,18,9,'Ja Jetro iloitsi kaikesta siitä hyvästä, mitä Herra oli tehnyt Israelille, pelastaessaan heidät egyptiläisten kädestä.'),
(1670933,58,2,18,10,'Ja Jetro sanoi: "Kiitetty olkoon Herra, joka on pelastanut teidät egyptiläisten ja faraon kädestä, Herra, joka on pelastanut kansansa egyptiläisten vallasta.'),
(1670934,58,2,18,11,'Nyt minä tiedän, että Herra on suurempi kaikkia jumalia; sillä sentähden, että egyptiläiset ylpeilivät, on heidän näin käynyt."'),
(1670935,58,2,18,12,'Ja Jetro, Mooseksen appi, toimitti polttouhrin ja teurasuhreja Jumalalle; ja Aaron ja kaikki Israelin vanhimmat tulivat aterioimaan Mooseksen apen kanssa Jumalan eteen.'),
(1670936,58,2,18,13,'Seuraavana päivänä Mooses istui tuomitsemaan kansaa, ja kansa seisoi Mooseksen ympärillä aamusta iltaan asti.'),
(1670937,58,2,18,14,'Kun Mooseksen appi näki kaiken, mitä hän teki kansalle, sanoi hän: "Mitä tämä puuha on, jota sinulla on kansan kanssa? Miksi sinä istut yksin ja kaikki kansa seisoo ympärilläsi aamusta iltaan asti?"'),
(1670938,58,2,18,15,'Mooses vastasi apellensa: "Kansa tulee minun luokseni kysymään Jumalalta neuvoa.'),
(1670939,58,2,18,16,'Kun heillä on jokin riita-asia, tulevat he minun luokseni, ja minä ratkaisen heidän riitansa ja ilmoitan heille Jumalan säädökset ja lait."'),
(1670940,58,2,18,17,'Niin Mooseksen appi sanoi hänelle: "Siinä sinä et menettele viisaasti.'),
(1670941,58,2,18,18,'Sinä uuvutat sekä itsesi että tämän kansan, joka on kanssasi; sillä tämä tehtävä on sinulle liian raskas, etkä sinä voi sitä yksinäsi toimittaa.'),
(1670942,58,2,18,19,'Kuule nyt, mitä minä sanon. Minä neuvon sinua, ja Jumala on oleva sinun kanssasi. Ole sinä kansan edusmies Jumalan edessä, ja saata sinä sen asiat Jumalan eteen. Ja opeta heille säädökset ja lait,'),
(1670943,58,2,18,20,'ja neuvo heille tie, jota heidän on kuljettava, ja mitä heidän on tehtävä.'),
(1670944,58,2,18,21,'Mutta valitse koko kansasta kelvollisia ja Jumalaa pelkääväisiä, luotettavia ja väärää voittoa vihaavia miehiä, ja aseta ne heille tuhannen, sadan, viidenkymmenen ja kymmenen päämiehiksi.'),
(1670945,58,2,18,22,'Nämä tuomitkoot kansaa joka aika. Kaikki suuret asiat he saattakoot sinun tietoosi, mutta kaikki vähäiset asiat ratkaiskoot itse. Huojenna näin jotakin itseltäsi, ja kantakoot he kuormaa sinun kanssasi.'),
(1670946,58,2,18,23,'Jos näin teet ja Jumala itse sinua näin käskee, niin sinä jaksat sen kestää; ja kaikki tämä kansa saa mennä rauhassa kotiinsa."'),
(1670947,58,2,18,24,'Ja Mooses noudatti appensa puhetta ja teki kaiken, mitä tämä oli sanonut.'),
(1670948,58,2,18,25,'Mooses valitsi kelvollisia miehiä koko Israelista ja asetti heidät kansan johtoon, tuhannen, sadan, viidenkymmenen ja kymmenen päämiehiksi.'),
(1670949,58,2,18,26,'Nämä tuomitsivat kansaa joka aika. Vaikeat asiat he lykkäsivät Moosekselle, mutta vähäiset asiat he ratkaisivat itse.'),
(1670950,58,2,18,27,'Sitten Mooses saattoi appensa matkaan, ja tämä meni omaan maahansa.'),
(1670951,58,2,19,1,'Kolmantena kuukautena siitä, kun israelilaiset olivat lähteneet Egyptin maasta, juuri samana kuukauden päivänä, he tulivat Siinain erämaahan.'),
(1670952,58,2,19,2,'Sillä he olivat lähteneet Refidimistä, tulleet Siinain erämaahan ja leiriytyneet erämaahan; ja Israel oli siellä leirissä vuoren kohdalla.'),
(1670953,58,2,19,3,'Ja Mooses nousi Jumalan tykö, ja Herra huusi häntä vuorelta ja sanoi: "Sano näin Jaakobin heimolle ja ilmoita israelilaisille:'),
(1670954,58,2,19,4,'''Te olette nähneet, mitä minä olen tehnyt egyptiläisille ja kuinka minä olen kantanut teitä kotkan siivillä ja tuonut teidät luokseni.'),
(1670955,58,2,19,5,'Jos te nyt kuulette minun ääntäni ja pidätte minun liittoni, niin te olette minun omaisuuteni ennen kaikkia muita kansoja; sillä koko maa on minun.'),
(1670956,58,2,19,6,'Ja te olette minulle pappisvaltakunta ja pyhä kansa.'' Sano nämä sanat israelilaisille."'),
(1670957,58,2,19,7,'Kun Mooses tuli takaisin, kutsui hän kokoon kansan vanhimmat ja puhui heille kaikki ne sanat, jotka Herra oli hänen käskenyt puhua.'),
(1670958,58,2,19,8,'Niin koko kansa vastasi yhtenä miehenä ja sanoi: "Kaiken, mitä Herra on puhunut, me teemme". Ja Mooses vei kansan vastauksen Herralle.'),
(1670959,58,2,19,9,'Niin Herra sanoi Moosekselle: "Katso, minä tulen sinun tykösi paksussa pilvessä, että kansa kuulisi, kun minä puhun sinun kanssasi, ja uskoisi myös sinua ainiaan". Ja Mooses ilmoitti Herralle kansan vastauksen.'),
(1670960,58,2,19,10,'Niin Herra sanoi Moosekselle: "Mene kansan luo ja pyhitä heidät tänä päivänä ja huomenna, ja peskööt he vaatteensa.'),
(1670961,58,2,19,11,'Ja olkoot valmiit kolmanneksi päiväksi; sillä kolmantena päivänä Herra astuu koko kansan nähden alas Siinain vuorelle.'),
(1670962,58,2,19,12,'Ja merkitse raja kansalle yltympäri ja sano: ''Varokaa nousemasta vuorelle tahi koskettamasta sen juureen. Jokainen, joka vuoreen koskee, rangaistakoon kuolemalla.'),
(1670963,58,2,19,13,'Älköön kenenkään käsi häneen koskeko, vaan hänet kivitettäköön tahi ammuttakoon kuoliaaksi. Olipa eläin tai ihminen, ei se saa jäädä eloon.'' Vasta kun pitkä torven puhallus kuuluu, he nouskoot vuorelle."'),
(1670964,58,2,19,14,'Ja Mooses astui alas vuorelta kansan luo; ja hän pyhitti kansan, ja he pesivät vaatteensa.'),
(1670965,58,2,19,15,'Ja hän sanoi kansalle: "Olkaa kolmanneksi päiväksi valmiit; älköön kukaan ryhtykö naiseen".'),
(1670966,58,2,19,16,'Ja kolmantena päivänä, kun aamu oli tullut, alkoi jylistä ja salamoida, ja paksu pilvi laskeutui vuoren ylle, ja kuului ylen kova pasunan ääni, niin että koko kansa, joka oli leirissä, vapisi pelosta.'),
(1670967,58,2,19,17,'Silloin Mooses vei kansan leiristä Jumalaa vastaan, ja he asettuivat vuoren juurelle.'),
(1670968,58,2,19,18,'Ja koko Siinain vuori peittyi savuun, kun Herra astui sille alas tulessa, ja siitä nousi savu niinkuin pätsin savu, ja koko vuori vapisi kovasti.'),
(1670969,58,2,19,19,'Ja pasunan ääni koveni kovenemistaan. Mooses puhui, ja Jumala vastasi hänelle jylinällä.'),
(1670970,58,2,19,20,'Ja Herra astui alas Siinain vuorelle, vuoren kukkulalle, ja Herra kutsui Mooseksen vuoren kukkulalle; ja Mooses nousi sinne ylös.'),
(1670971,58,2,19,21,'Niin Herra sanoi Moosekselle: "Astu alas ja varoita kansaa tunkeutumasta lähelle Herraa, häntä nähdäkseen, sillä silloin heistä monta kaatuu.'),
(1670972,58,2,19,22,'Papitkin, jotka saavat lähestyä Herraa, pyhittäkööt itsensä, ettei Herra heitä tuhoaisi."'),
(1670973,58,2,19,23,'Mutta Mooses vastasi Herralle: "Kansa ei voi nousta Siinain vuorelle, sillä sinä olet varoittanut meitä ja sanonut: ''Merkitse raja vuoren ympäri ja pyhitä se''."'),
(1670974,58,2,19,24,'Niin Herra sanoi hänelle: "Astu alas ja tule taas ylös, sinä ja Aaron sinun kanssasi. Mutta papit ja kansa älkööt tunkeutuko ylös, Herraa lähelle, ettei hän heitä tuhoaisi."'),
(1670975,58,2,19,25,'Ja Mooses astui alas kansan luo ja sanoi heille tämän.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1670976,58,2,20,1,'Ja Jumala puhui kaikki nämä sanat ja sanoi:'),
(1670977,58,2,20,2,'"Minä olen Herra, sinun Jumalasi, joka vein sinut pois Egyptin maasta, orjuuden pesästä.'),
(1670978,58,2,20,3,'Älä pidä muita jumalia minun rinnallani.'),
(1670979,58,2,20,4,'Älä tee itsellesi jumalankuvaa äläkä mitään kuvaa, älä niistä, jotka ovat ylhäällä taivaassa, älä niistä, jotka ovat alhaalla maan päällä, äläkä niistä, jotka ovat vesissä maan alla.'),
(1670980,58,2,20,5,'Älä kumarra niitä äläkä palvele niitä. Sillä minä, Herra, sinun Jumalasi, olen kiivas Jumala, joka kostan isien pahat teot lapsille kolmanteen ja neljänteen polveen, niille, jotka minua vihaavat;'),
(1670981,58,2,20,6,'mutta teen laupeuden tuhansille, jotka minua rakastavat ja pitävät minun käskyni.'),
(1670982,58,2,20,7,'Älä turhaan lausu Herran, sinun Jumalasi, nimeä, sillä Herra ei jätä rankaisematta sitä, joka hänen nimensä turhaan lausuu.'),
(1670983,58,2,20,8,'Muista pyhittää lepopäivä.'),
(1670984,58,2,20,9,'Kuusi päivää tee työtä ja toimita kaikki askareesi;'),
(1670985,58,2,20,10,'mutta seitsemäs päivä on Herran, sinun Jumalasi, sapatti; silloin älä mitään askaretta toimita, älä sinä älköönkä sinun poikasi tai tyttäresi, sinun palvelijasi tai palvelijattaresi tai juhtasi älköönkä muukalaisesi, joka sinun porteissasi on.'),
(1670986,58,2,20,11,'Sillä kuutena päivänä Herra teki taivaan ja maan ja meren ja kaikki, mitä niissä on, mutta seitsemäntenä päivänä hän lepäsi; sentähden Herra siunasi lepopäivän ja pyhitti sen.'),
(1670987,58,2,20,12,'Kunnioita isääsi ja äitiäsi, että kauan eläisit siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa.'),
(1670988,58,2,20,13,'Älä tapa.'),
(1670989,58,2,20,14,'Älä tee huorin.'),
(1670990,58,2,20,15,'Älä varasta.'),
(1670991,58,2,20,16,'Älä sano väärää todistusta lähimmäisestäsi.'),
(1670992,58,2,20,17,'Älä himoitse lähimmäisesi huonetta. Älä himoitse lähimmäisesi vaimoa äläkä hänen palvelijaansa, palvelijatartaan, härkäänsä, aasiansa äläkä mitään, mikä on lähimmäisesi omaa."'),
(1670993,58,2,20,18,'Ja kaikki kansa havaitsi jylinän, tulen leimaukset, pasunan äänen ja vuoren suitsuamisen; ja kun he sen havaitsivat, vapisivat he ja pysyivät taampana.'),
(1670994,58,2,20,19,'Ja he sanoivat Moosekselle: "Puhu sinä meidän kanssamme, niin me kuulemme. Älköön Jumala puhuko meidän kanssamme, ettemme kuolisi."'),
(1670995,58,2,20,20,'Mutta Mooses vastasi kansalle: "Älkää peljätkö, sillä Jumala on tullut koettelemaan teitä, että Herran pelko olisi teidän silmäinne edessä ja ettette syntiä tekisi".'),
(1670996,58,2,20,21,'Ja kansa pysyi taampana, mutta Mooses lähestyi pimeyttä, jossa Jumala oli.'),
(1670997,58,2,20,22,'Ja Herra sanoi Moosekselle: "Sano israelilaisille näin: Te olette nähneet, että minä olen puhunut teille taivaasta.'),
(1670998,58,2,20,23,'Älkää tehkö jumalia minun rinnalleni; hopeaisia tai kultaisia jumalia älkää tehkö itsellenne.'),
(1670999,58,2,20,24,'Tee minulle alttari maasta, ja uhraa sen päällä polttouhrisi ja yhteysuhrisi, lampaasi ja raavaasi. Joka paikassa, mihin minä säädän nimeni muiston, minä tulen sinun tykösi ja siunaan sinua.'),
(1671000,58,2,20,25,'Mutta jos sinä teet minulle kivialttarin, niin älä rakenna sitä hakatusta kivestä; sillä jos sinä kosket taltallasi kiveen, niin sinä saastutat sen.'),
(1671001,58,2,20,26,'Äläkä nouse portaita myöten minun alttarilleni, ettei häpysi sen päällä paljastuisi."'),
(1671002,58,2,21,1,'"Nämä ovat ne oikeudet, jotka sinun tulee asettaa heidän eteensä:'),
(1671003,58,2,21,2,'Jos sinä ostat hebrealaisen orjan, niin hän palvelkoon kuusi vuotta, mutta seitsemäntenä hän pääsköön vapaaksi maksutta.'),
(1671004,58,2,21,3,'Jos hän on tullut yksinäisenä, niin yksinäisenä lähteköönkin; mutta jos hän oli nainut, niin lähteköön vaimo hänen kanssaan.'),
(1671005,58,2,21,4,'Jos hänen isäntänsä on antanut hänelle vaimon, ja tämä on synnyttänyt hänelle poikia tai tyttäriä, niin vaimo lapsinensa jääköön isännän omaksi, ja hän lähteköön yksinään.'),
(1671006,58,2,21,5,'Mutta jos orja vakuuttaa: ''Minä rakastan isäntääni, vaimoani ja lapsiani enkä tahdo päästä vapaaksi'','),
(1671007,58,2,21,6,'niin hänen isäntänsä vieköön hänet Jumalan eteen ja asettakoon hänet ovea tai pihtipieltä vasten, ja hänen isäntänsä lävistäköön hänen korvansa naskalilla, ja hän olkoon hänen orjansa ainiaan.'),
(1671008,58,2,21,7,'Jos joku myy tyttärensä orjaksi, älköön tämä pääskö vapaaksi, niinkuin miesorjat pääsevät.'),
(1671009,58,2,21,8,'Jos hän ei miellytä isäntäänsä, sitten kuin tämä jo on määrännyt hänet itsellensä, niin tämä sallikoon lunastaa hänet pois. Vieraaseen kansaan älköön hänellä olko valtaa häntä myydä, kun hän hänet hylkää.'),
(1671010,58,2,21,9,'Mutta jos hän määrää hänet pojallensa, niin antakoon hänen nauttia tyttärien oikeutta.'),
(1671011,58,2,21,10,'Jos hän ottaa itselleen toisen vaimon, niin älköön vähentäkö ensimmäiseltä tämän ravintoa, vaatetusta ja aviollista oikeutta.'),
(1671012,58,2,21,11,'Jos hän ei tee hänelle näitä kolmea, niin lähteköön vaimo pois maksutta ja rahakorvauksetta.'),
(1671013,58,2,21,12,'Joka lyö ihmistä, niin että tämä kuolee, se rangaistakoon kuolemalla.'),
(1671014,58,2,21,13,'Mutta jos hän ei ole tehnyt sitä murha-aikeessa, vaan Jumala on sallinut sen vahingon tapahtua hänen kätensä kautta, niin minä määrään sinulle paikan, johon hän voi paeta.'),
(1671015,58,2,21,14,'Mutta jos joku menettelee niin rikollisesti lähimmäistänsä kohtaan, että tappaa hänet kavalasti, on sinun otettava hänet minun alttarinikin luota surmattavaksi.'),
(1671016,58,2,21,15,'Joka lyö isäänsä tai äitiänsä, se rangaistakoon kuolemalla.'),
(1671017,58,2,21,16,'Joka varastaa ihmisen ja joko myy hänet tahi pitää häntä hallussansa, se rangaistakoon kuolemalla.'),
(1671018,58,2,21,17,'Joka kiroaa isäänsä tai äitiänsä, se rangaistakoon kuolemalla.'),
(1671019,58,2,21,18,'Jos miehet riitelevät keskenänsä ja toinen lyö toista kivellä tai nyrkillä, mutta tämä ei kuole, vaan joutuu vuoteen omaksi,'),
(1671020,58,2,21,19,'niin olkoon, jos hän tointuu ja voi mennä ulos sauvaansa nojaten, lyöjä vapaa rangaistuksesta; korvatkoon ainoastaan hänen sairastamisaikansa ja pitäköön huolta hänen paranemisestaan.'),
(1671021,58,2,21,20,'Jos joku lyö orjaansa tai orjatartaan sauvalla, niin että tämä kuolee hänen käsiinsä, niin häntä rangaistakoon.'),
(1671022,58,2,21,21,'Mutta jos se elää päivän tai kaksi, niin älköön lyöjää rangaistako, sillä se on hänen omaa rahaansa.'),
(1671023,58,2,21,22,'Jos miehet tappelevat keskenänsä ja loukkaavat raskasta vaimoa, niin että hän synnyttää kesken, mutta vahinkoa ei tapahdu, niin sakotettakoon syyllistä vaimon miehen vaatimuksen ja riidanratkaisijain harkinnan mukaan.'),
(1671024,58,2,21,23,'Mutta jos vahinko tapahtuu, niin annettakoon henki hengestä,'),
(1671025,58,2,21,24,'silmä silmästä, hammas hampaasta, käsi kädestä, jalka jalasta,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671026,58,2,21,25,'palovamma palovammasta, haava haavasta, mustelma mustelmasta.'),
(1671027,58,2,21,26,'Jos joku lyö orjaansa tai orjatartansa silmään ja turmelee sen, niin päästäköön hänet vapaaksi silmän tähden.'),
(1671028,58,2,21,27,'Ja jos hän lyö orjaltaan tai orjattareltaan hampaan suusta, niin päästäköön hänet vapaaksi hampaan tähden.'),
(1671029,58,2,21,28,'Jos härkä puskee miehen tai naisen kuoliaaksi, niin härkä kivitettäköön, älköönkä sen lihaa syötäkö; mutta härän omistaja olkoon vapaa rangaistuksesta.'),
(1671030,58,2,21,29,'Mutta jos härkä on ennenkin puskenut ja sen isäntää on varoitettu eikä hän ole sitä vartioinut, ja jos se tappaa miehen tai naisen, niin härkä kivitettäköön, ja myös sen isäntä rangaistakoon kuolemalla.'),
(1671031,58,2,21,30,'Mutta jos hänelle määrätään lunastusmaksu, niin maksakoon henkensä lunnaiksi niin paljon, kuin hänelle määrätään.'),
(1671032,58,2,21,31,'Jos se puskee pojan tai tytön, niin meneteltäköön saman lain mukaan.'),
(1671033,58,2,21,32,'Jos härkä puskee orjan tai orjattaren, niin maksakoon sen omistaja pusketun isännälle kolmekymmentä hopeasekeliä, ja härkä kivitettäköön.'),
(1671034,58,2,21,33,'Jos joku jättää kaivon auki tahi kaivaa kaivon eikä peitä sitä, ja härkä tai aasi putoaa siihen,'),
(1671035,58,2,21,34,'niin kaivon omistaja korvatkoon isännälle sen rahassa; mutta kuollut eläin olkoon hänen.'),
(1671036,58,2,21,35,'Jos jonkun härkä puskee toisen härän kuoliaaksi, niin myykööt elävän härän ja jakakoot sen hinnan, ja myös kuolleen jakakoot keskenään.'),
(1671037,58,2,21,36,'Jos taas oli tunnettua, että se härkä ennenkin oli puskenut eikä sen isäntä ollut sitä vartioinut, niin antakoon härän härästä, mutta kuollut olkoon hänen."'),
(1671038,58,2,22,1,'"Jos joku varastaa härän tai lampaan ja teurastaa tahi myy sen, antakoon viisi raavasta yhdestä härästä ja neljä lammasta yhdestä lampaasta.'),
(1671039,58,2,22,2,'Jos varas tavataan murtautumasta sisälle ja lyödään kuoliaaksi, ei tappaja ole vereen vikapää.'),
(1671040,58,2,22,3,'Mutta jos aurinko jo oli noussut, niin tappaja on vereen vikapää. Varas maksakoon korvauksen; mutta jos hänellä ei ole mitään, niin myytäköön hänet varastamansa tavaran korvaukseksi.'),
(1671041,58,2,22,4,'Jos varastettu eläin, olipa se härkä, aasi tai lammas, tavataan hänen hallustaan elävänä, niin korvatkoon sen kaksinkertaisesti.'),
(1671042,58,2,22,5,'Jos joku turmelee toiselta pellon tai viinitarhan päästämällä siihen karjansa ja syöttämällä sitä toisen pellossa, antakoon korvaukseksi peltonsa tai viinitarhansa parhaimman kasvun.'),
(1671043,58,2,22,6,'Jos tuli pääsee irti ja tarttuu orjantappuroihin ja jos kuhilaat tai vilja tai pelto palaa, niin korvatkoon vahingon se, joka on kulovalkean sytyttänyt.'),
(1671044,58,2,22,7,'Jos joku antaa toiselle rahaa tai tavaraa säilytettäväksi ja se varastetaan tämän talosta, niin varas, jos hänet tavataan, korvatkoon sen kaksinkertaisesti.'),
(1671045,58,2,22,8,'Mutta jos varasta ei tavata, astukoon talon omistaja Jumalan eteen ja vannokoon, ettei hän ole kädellänsä kajonnut toisen omaan.'),
(1671046,58,2,22,9,'Jokaisessa anastusasiassa, koskipa se härkää tai aasia tai lammasta tai vaatetta tai mitä tahansa kadonnutta, josta joku sanoo: ''Tämä se on'', tulkoon kummankin asia Jumalan eteen; ja se, jonka Jumala tuomitsee syylliseksi, korvatkoon toiselle kaksinkertaisesti.'),
(1671047,58,2,22,10,'Jos joku antaa toiselle aasin tai härän tai lampaan tai minkä eläimen tahansa säilytettäväksi ja se kuolee tai vahingoittuu tai ryöstetään pois kenenkään näkemättä,'),
(1671048,58,2,22,11,'niin vala Herran edessä ratkaiskoon heidän välillään, onko toinen kädellänsä kajonnut toisen omaan; omistaja hyväksyköön valan, ja toinen olkoon korvauksesta vapaa.'),
(1671049,58,2,22,12,'Mutta jos se on häneltä varastettu, korvatkoon sen omistajalle.'),
(1671050,58,2,22,13,'Jos se on raadeltu, tuokoon sen esiin todistukseksi, eikä hänen tarvitse raadeltua korvata.'),
(1671051,58,2,22,14,'Jos joku lainaa toiselta elukan ja se vahingoittuu tai kuolee eikä sen omistaja ole saapuvilla, korvatkoon sen.'),
(1671052,58,2,22,15,'Jos sen omistaja on saapuvilla, ei tarvitse korvausta maksaa; jos se oli vuokralla, olkoon vuokra korvauksena.'),
(1671053,58,2,22,16,'Jos joku viettelee neitsyen, joka ei ole kihlattu, ja makaa hänet, maksakoon hänestä morsiamenhinnan ja ottakoon hänet vaimokseen.'),
(1671054,58,2,22,17,'Jos isä kieltäytyy antamasta häntä hänelle, maksakoon mies rahassa morsiamenhinnan niinkuin neitsyestä.'),
(1671055,58,2,22,18,'Velhonaisen älä salli elää.'),
(1671056,58,2,22,19,'Jokainen, joka sekaantuu eläimeen, rangaistakoon kuolemalla.'),
(1671057,58,2,22,20,'Joka uhraa muille jumalille kuin Herralle, ainoalle, olkoon vihitty tuhon omaksi.'),
(1671058,58,2,22,21,'Älä sorra äläkä ahdista muukalaista, sillä te olette itse olleet muukalaisina Egyptin maassa.'),
(1671059,58,2,22,22,'Älkää sortako leskeä tai orpoa.'),
(1671060,58,2,22,23,'Sillä jos sinä sorrat heitä ja he huutavat minua avuksensa, niin minä totisesti kuulen heidän huutonsa,'),
(1671061,58,2,22,24,'ja minun vihani syttyy, ja minä surmaan teidät miekalla, niin että teidän vaimonne joutuvat leskiksi ja lapsenne orvoiksi.'),
(1671062,58,2,22,25,'Jos lainaat rahaa jollekin minun kansastani, jollekin köyhälle, joka on sinun luonasi, niin älä menettele koronkiskurin tavoin häntä kohtaan. Älkää panko korkoa hänen maksettavakseen.'),
(1671063,58,2,22,26,'Jos sinä olet lähimmäiseltäsi ottanut pantiksi vaipan, anna se hänelle takaisin, ennenkuin aurinko laskee;'),
(1671064,58,2,22,27,'sillä se on hänen ainoa peitteensä, johon hän käärii ruumiinsa. Missä hän muutoin makaisi? Ja jos hän huutaa minua avukseen, kuulen minä häntä, sillä minä olen laupias.'),
(1671065,58,2,22,28,'Jumalaa älä herjaa, ja kansasi ruhtinasta älä kiroa.'),
(1671066,58,2,22,29,'Älä viivyttele antamasta antia vilja- ja mehusatosi runsaudesta. Esikoinen pojistasi anna minulle.'),
(1671067,58,2,22,30,'Samoin tee raavaittesi ja lampaittesi ensiksisyntyneelle. Seitsemän päivää se olkoon emänsä kanssa; kahdeksantena päivänä anna se minulle.'),
(1671068,58,2,22,31,'Ja te olkaa minulle pyhä kansa. Älkää syökö kedolla raadellun eläimen lihaa, vaan heittäkää se koirille."'),
(1671069,58,2,23,1,'"Älä levitä valheellista huhua, äläkä anna apuasi syylliselle rupeamalla vääräksi todistajaksi.'),
(1671070,58,2,23,2,'Älä ole joukon mukana tekemässä pahaa, äläkä todista riita-asiassa niin, että taivut joukon mukaan ja väännät oikean vääräksi.'),
(1671071,58,2,23,3,'Älä ole puolueellinen alhaisen hyväksi hänen asiassansa.'),
(1671072,58,2,23,4,'Jos tapaat vihollisesi härän tai aasin eksyksissä, niin saata se hänelle takaisin.'),
(1671073,58,2,23,5,'Jos näet vihamiehesi aasin makaavan kuormansa alla, niin älä jätä häntä auttamatta, vaan auta häntä sitä päästämään.'),
(1671074,58,2,23,6,'Älä väännä vääräksi keskuudessanne asuvan köyhän oikeutta hänen riita-asiassansa.'),
(1671075,58,2,23,7,'Pysy erilläsi väärästä asiasta, äläkä surmaa viatonta ja syytöntä, sillä minä en julista syyllistä syyttömäksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671076,58,2,23,8,'Äläkä ota lahjusta, sillä lahjus sokaisee näkevät ja vääristää syyttömien asiat.'),
(1671077,58,2,23,9,'Muukalaista älä sorra, sillä te tiedätte muukalaisen mielialan, koska itsekin olette olleet muukalaisina Egyptin maassa.'),
(1671078,58,2,23,10,'Kuutena vuotena kylvä maasi ja korjaa sen sato.'),
(1671079,58,2,23,11,'Mutta seitsemäntenä vuotena jätä se korjaamatta ja lepäämään, että kansasi köyhät saisivat siitä syödä; ja mitä jäljelle jää, sen metsän eläimet syökööt. Samoin tee viinitarhallesi ja öljytarhallesi.'),
(1671080,58,2,23,12,'Kuusi päivää tee työtäsi, mutta lepää seitsemäs päivä, että härkäsi ja aasisi saisivat hengähtää ja orjattaresi poika ynnä muukalainen saisivat virkistyä.'),
(1671081,58,2,23,13,'Kaikkea, mitä minä olen sanonut teille, noudattakaa. Vierasten jumalien nimiä älkää mainitko, älköön niitä kuuluko teidän huuliltanne.'),
(1671082,58,2,23,14,'Kolme kertaa vuodessa vietä juhlaa minun kunniakseni.'),
(1671083,58,2,23,15,'Pidä happamattoman leivän juhla: seitsemänä päivänä syö happamatonta leipää, niinkuin minä olen sinua käskenyt, määrättynä aikana aabib-kuussa, sillä siinä kuussa sinä olet lähtenyt Egyptistä; mutta tyhjin käsin älköön tultako minun kasvojeni eteen.'),
(1671084,58,2,23,16,'Ja vietä leikkuujuhla, kun leikkaat uutiset viljastasi, jonka olet kylvänyt vainioon, ja korjuujuhla vuoden lopussa, kun korjaat satosi vainiolta.'),
(1671085,58,2,23,17,'Kolme kertaa vuodessa tulkoon kaikki sinun miesväkesi Herran, Herran, kasvojen eteen.'),
(1671086,58,2,23,18,'Älä uhraa minun teurasuhrini verta happamen leivän ohella. Ja minun juhlauhrini rasvaa älköön jääkö yön yli seuraavaan aamuun.'),
(1671087,58,2,23,19,'Parhaat maasi uutisesta tuo Herran, Jumalasi, huoneeseen. Älä keitä vohlaa emänsä maidossa.'),
(1671088,58,2,23,20,'Katso, minä lähetän enkelin sinun edellesi varjelemaan sinua tiellä ja johdattamaan sinua siihen paikkaan, jonka minä olen valmistanut.'),
(1671089,58,2,23,21,'Ole varuillasi hänen edessään ja kuule häntä äläkä pahoita hänen mieltänsä. Hän ei jätä teidän rikoksianne rankaisematta, sillä minun nimeni on hänessä.'),
(1671090,58,2,23,22,'Mutta jos sinä kuulet häntä ja teet kaikki, mitä minä käsken, niin minä olen sinun vihollistesi vihollinen ja vastustajaisi vastustaja.'),
(1671091,58,2,23,23,'Sillä minun enkelini käy sinun edelläsi ja johdattaa sinut amorilaisten, heettiläisten, perissiläisten, kanaanilaisten, hivviläisten ja jebusilaisten maahan, ja minä hävitän heidät.'),
(1671092,58,2,23,24,'Älä kumarra heidän jumaliansa, älä palvele niitä äläkä tee, niinkuin he tekevät, vaan kukista ne maahan ja murskaa niiden patsaat.'),
(1671093,58,2,23,25,'Palvelkaa Herraa, Jumalaanne, niin hän siunaa sinun ruokasi ja juomasi, ja minä pidän puutteen sinusta kaukana.'),
(1671094,58,2,23,26,'Ei keskensynnyttäjää eikä hedelmätöntä ole sinun maassasi oleva. Ja sinun päiviesi luvun minä teen täydeksi.'),
(1671095,58,2,23,27,'Minä lähetän kauhuni sinun edelläsi ja saatan hämminkiin kaikki kansat, joiden luo sinä tulet, ja ajan kaikki vihollisesi pakoon sinun edestäsi.'),
(1671096,58,2,23,28,'Ja minä lähetän herhiläisiä sinun edelläsi karkoittamaan hivviläiset, kanaanilaiset ja heettiläiset sinun tieltäsi.'),
(1671097,58,2,23,29,'Mutta minä en karkoita heitä sinun tieltäsi yhtenä vuotena, ettei maa tulisi autioksi eivätkä metsän pedot lisääntyisi sinun vahingoksesi;'),
(1671098,58,2,23,30,'vähitellen minä karkoitan heidät sinun tieltäsi, kunnes olet tullut kyllin lukuisaksi ottamaan haltuusi maan.'),
(1671099,58,2,23,31,'Ja minä asetan sinun rajasi Kaislamerestä filistealaisten mereen ja erämaasta Eufrat-virtaan asti; sillä minä annan maan asukkaat teidän valtaanne, ja sinä karkoitat heidät tieltäsi.'),
(1671100,58,2,23,32,'Älä tee liittoa heidän äläkä heidän jumaliensa kanssa.'),
(1671101,58,2,23,33,'Älkööt he jääkö asumaan sinun maahasi, etteivät saattaisi sinua tekemään syntiä minua vastaan; sillä jos sinä palvelet heidän jumaliansa, on se sinulle paulaksi."'),
(1671102,58,2,24,1,'Ja hän sanoi Moosekselle: "Nouse Herran tykö, sinä ja Aaron, Naadab ja Abihu ynnä seitsemänkymmentä Israelin vanhinta; ja kumartukaa ja rukoilkaa taampana.'),
(1671103,58,2,24,2,'Mooses yksinään lähestyköön Herraa; muut älkööt lähestykö, ja kansa älköön nousko sinne hänen kanssansa."'),
(1671104,58,2,24,3,'Ja Mooses tuli ja kertoi kansalle kaikki Herran sanat ja kaikki hänen säädöksensä. Niin koko kansa vastasi yhteen ääneen ja sanoi: "Kaiken, mitä Herra on puhunut, me teemme".'),
(1671105,58,2,24,4,'Sitten Mooses kirjoitti kaikki Herran sanat. Ja hän nousi varhain seuraavana aamuna ja rakensi alttarin vuoren juurelle sekä pystytti kaksitoista patsasta Israelin kahdentoista sukukunnan mukaan.'),
(1671106,58,2,24,5,'Ja hän lähetti israelilaisten joukosta nuoria miehiä uhraamaan polttouhreja ja teurastamaan härkiä yhteysuhriksi Herralle.'),
(1671107,58,2,24,6,'Ja Mooses otti verestä puolet ja pani uhrimaljoihin, ja toisen puolen hän vihmoi alttarille.'),
(1671108,58,2,24,7,'Ja hän otti liitonkirjan ja luki sen kansan kuullen. Ja he sanoivat: "Kaikkea, mitä Herra on puhunut, me noudatamme ja tottelemme".'),
(1671109,58,2,24,8,'Niin Mooses otti veren ja vihmoi sitä kansan päälle ja sanoi: "Katso, tämä on sen liiton veri, jonka Herra on tehnyt teidän kanssanne kaikkien näiden sanojen perusteella".'),
(1671110,58,2,24,9,'Ja Mooses ja Aaron, Naadab ja Abihu ynnä seitsemänkymmentä Israelin vanhinta nousivat vuorelle.'),
(1671111,58,2,24,10,'Ja he näkivät Israelin Jumalan; ja hänen jalkainsa alla oli alusta, niinkuin safiirikivistä, kirkas kuin itse taivas.'),
(1671112,58,2,24,11,'Eikä hän kajonnut kädellänsä israelilaisten valittuihin, ja he katselivat Jumalaa, söivät ja joivat.'),
(1671113,58,2,24,12,'Ja Herra sanoi Moosekselle: "Nouse minun tyköni vuorelle ja ole siellä, niin minä annan sinulle kivitaulut ynnä lain ja käskyt, jotka minä olen kirjoittanut heille opetukseksi".'),
(1671114,58,2,24,13,'Silloin Mooses ja hänen palvelijansa Joosua lähtivät; ja Mooses nousi Jumalan vuorelle.'),
(1671115,58,2,24,14,'Mutta vanhimmille hän sanoi: "Odottakaa meitä täällä, kunnes palaamme teidän tykönne. Ja katso, Aaron ja Huur ovat teidän kanssanne; jolla on jotakin asiaa, kääntyköön heidän puoleensa."'),
(1671116,58,2,24,15,'Kun Mooses oli noussut vuorelle, peitti pilvi vuoren.'),
(1671117,58,2,24,16,'Ja Herran kirkkaus laskeutui Siinain vuorelle, ja pilvi peitti sen kuusi päivää; ja seitsemäntenä päivänä hän huusi Moosesta pilven keskeltä.'),
(1671118,58,2,24,17,'Ja Herran kirkkaus vuoren kukkulalla näytti israelilaisten silmissä kuluttavalta tulelta.'),
(1671119,58,2,24,18,'Ja Mooses meni pilven keskelle ja nousi vuorelle. Ja Mooses oli vuorella neljäkymmentä päivää ja neljäkymmentä yötä.'),
(1671120,58,2,25,1,'Ja Herra puhui Moosekselle sanoen:'),
(1671121,58,2,25,2,'"Sano israelilaisille, että he kokoavat anteja minulle; jokaiselta, jonka sydän on siihen altis, ottakaa vastaan anti minulle.'),
(1671122,58,2,25,3,'Ja nämä ovat ne annit, joita teidän on otettava vastaan heiltä: kultaa, hopeata ja vaskea,'),
(1671123,58,2,25,4,'punasinisiä, purppuranpunaisia ja helakanpunaisia lankoja ja valkoisia pellavalankoja sekä vuohenkarvoja,'),
(1671124,58,2,25,5,'punaisia oinaannahkoja, sireeninnahkoja, akasiapuuta,'),
(1671125,58,2,25,6,'öljyä seitsenhaaraista lamppua varten, hajuaineita voiteluöljyä ja hyvänhajuista suitsutusta varten,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671126,58,2,25,7,'onyks-kiviä ja muita jalokiviä kasukkaa ja rintakilpeä varten.'),
(1671127,58,2,25,8,'Ja tehkööt he minulle pyhäkön asuakseni heidän keskellään.'),
(1671128,58,2,25,9,'Tehkää asumus ja kaikki sen kalusto tarkoin sen kaavan mukaan, jonka minä sinulle näytän.'),
(1671129,58,2,25,10,'Tehkööt he arkin akasiapuusta, puolenkolmatta kyynärän pituisen, puolentoista kyynärän levyisen ja puolentoista kyynärän korkuisen.'),
(1671130,58,2,25,11,'Ja päällystä se puhtaalla kullalla, päällystä se sisältä ja ulkoa; ja tee siihen kultareunus yltympäri.'),
(1671131,58,2,25,12,'Ja vala siihen neljä kultarengasta ja kiinnitä ne sen neljään jalkaan, niin että kaksi rengasta tulee sen toiselle puolelle ja kaksi rengasta sen toiselle puolelle.'),
(1671132,58,2,25,13,'Ja tee korennot akasiapuusta ja päällystä ne kullalla.'),
(1671133,58,2,25,14,'Ja pistä renkaisiin arkin sivuille korennot, joilla arkki on kannettava.'),
(1671134,58,2,25,15,'Korennot jääkööt arkin renkaisiin, älköönkä niitä vedettäkö pois.'),
(1671135,58,2,25,16,'Ja pane arkkiin laki, jonka minä sinulle annan.'),
(1671136,58,2,25,17,'Tee myös armoistuin puhtaasta kullasta, puolenkolmatta kyynärän pituinen ja puolentoista kyynärän levyinen.'),
(1671137,58,2,25,18,'Ja tee kaksi kultakerubia, tee ne kohotakoista tekoa, armoistuimen molempiin päihin.'),
(1671138,58,2,25,19,'Tee toinen kerubi toiseen päähän ja toinen kerubi toiseen päähän. Tehkää kerubit armoistuimesta kohoaviksi, sen kumpaankin päähän.'),
(1671139,58,2,25,20,'Ja kerubit levittäkööt siipensä ylöspäin, niin että ne peittävät siivillänsä armoistuimen, ja niiden kasvot olkoot vastakkain; armoistuinta kohti olkoot kerubien kasvot käännetyt.'),
(1671140,58,2,25,21,'Ja aseta armoistuin arkin päälle ja pane arkkiin laki, jonka minä sinulle annan.'),
(1671141,58,2,25,22,'Ja siinä minä ilmestyn sinulle ja puhun sinulle armoistuimelta, niiden kahden kerubin välistä, jotka ovat lain arkin päällä, kaiken sen, minkä minä sinun kauttasi israelilaisille säädän.'),
(1671142,58,2,25,23,'Ja tee pöytä akasiapuusta, kahden kyynärän pituinen, kyynärän levyinen ja puolentoista kyynärän korkuinen.'),
(1671143,58,2,25,24,'Ja päällystä se puhtaalla kullalla ja tee siihen kultareunus yltympäri.'),
(1671144,58,2,25,25,'Ja tee sen ympäri kämmenen korkuinen lista ja listan ympäri kultareunus.'),
(1671145,58,2,25,26,'Ja tee siihen neljä kultarengasta ja kiinnitä renkaat sen neljään kulmaan, kunkin neljän jalan kohdalle.'),
(1671146,58,2,25,27,'Renkaat olkoot juuri listan alla niiden korentojen pitiminä, joilla pöytä on kannettava.'),
(1671147,58,2,25,28,'Ja tee ne korennot akasiapuusta ja päällystä ne kullalla, ja niillä on pöytä kannettava.'),
(1671148,58,2,25,29,'Tee myös siihen vadit ja kupit, kannut ja maljat, joista juomauhrit vuodatetaan; tee ne puhtaasta kullasta.'),
(1671149,58,2,25,30,'Ja pidä aina minun edessäni pöydällä näkyleivät.'),
(1671150,58,2,25,31,'Ja tee myös seitsenhaarainen lamppu puhtaasta kullasta. Tee lamppu jalkoineen ja varsineen kohotakoista tekoa; sen kukkakuvut, nuput kukkalehtineen, olkoot samaa kappaletta kuin se.'),
(1671151,58,2,25,32,'Kuusi haaraa lähteköön lampun sivuista, kolme haaraa toisesta sivusta ja kolme haaraa toisesta sivusta.'),
(1671152,58,2,25,33,'Toisessa haarassa olkoon kolme mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen, ja toisessa haarassa samoin kolme mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen; näin olkoon jokaisessa kuudessa haarassa, jotka lampusta lähtevät.'),
(1671153,58,2,25,34,'Mutta lampussa itsessään olkoon neljä mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen.'),
(1671154,58,2,25,35,'Yksi nuppu olkoon aina jokaisen haaraparin alla niistä kuudesta haarasta, jotka lampusta lähtevät.'),
(1671155,58,2,25,36,'Nuput ja haarat olkoot samaa kappaletta kuin se; olkoon se kauttaaltaan samaa kohotakoista tekoa, puhdasta kultaa.'),
(1671156,58,2,25,37,'Ja tee siihen seitsemän lamppua, ja lamput asetettakoon niin, että seitsenhaarainen lamppu heittää valonsa etupuolelle.'),
(1671157,58,2,25,38,'Ja sen lamppusakset ja karstakupit olkoot puhdasta kultaa.'),
(1671158,58,2,25,39,'Yhdestä talentista puhdasta kultaa tehtäköön sekä se että kaikki nämä kalut.'),
(1671159,58,2,25,40,'Ja katso, että teet ne sen kaavan mukaan, joka sinulle niistä vuorella näytettiin."'),
(1671160,58,2,26,1,'"Ja tee asumus kymmenestä telttakankaan kaistasta, jotka ovat valmistetut kerratuista valkoisista pellavalangoista ja punasinisistä, purppuranpunaisista ja helakanpunaisista langoista, ja tee niihin taidokkaasti kudottuja kerubeja.'),
(1671161,58,2,26,2,'Kunkin kaistan pituus olkoon kaksikymmentäkahdeksan kyynärää ja leveys neljä kyynärää; kaikilla kaistoilla olkoon sama mitta.'),
(1671162,58,2,26,3,'Viisi kaistaa yhdistettäköön toisiinsa, ja samoin toiset viisi kaistaa yhdistettäköön toisiinsa.'),
(1671163,58,2,26,4,'Ja tee silmukat punasinisestä langasta ensimmäisen kaistan reunaan, yhdistetyn kappaleen laitaan, ja samoin toisen yhdistetyn kappaleen viimeisen kaistan reunaan.'),
(1671164,58,2,26,5,'Tee viisikymmentä silmukkaa ensimmäiseen kaistaan, ja tee viisikymmentä silmukkaa vastaavan kaistan laitaan, toiseen yhdistettyyn kappaleeseen, niin että silmukat ovat kohdakkain.'),
(1671165,58,2,26,6,'Ja tee viisikymmentä kultahakasta ja yhdistä kaistat toisiinsa näillä hakasilla, niin että siitä tulee yhtenäinen asumus.'),
(1671166,58,2,26,7,'Tee vielä kaistoista, jotka ovat kudotut vuohenkarvoista, teltta asumuksen suojaksi; tee niitä kaistoja yksitoista.'),
(1671167,58,2,26,8,'Kunkin kaistan pituus olkoon kolmekymmentä kyynärää ja leveys neljä kyynärää; niillä yhdellätoista kaistalla olkoon sama mitta.'),
(1671168,58,2,26,9,'Liitä yhteen viisi kaistaa erikseen ja kuusi kaistaa erikseen, ja aseta kuudes niistä kaksin kerroin teltan etupuolelle.'),
(1671169,58,2,26,10,'Ja tee viisikymmentä silmukkaa toisen yhdistetyn kappaleen viimeisen kaistan reunaan ja viisikymmentä silmukkaa toisen yhdistetyn kappaleen vastaavan kaistan reunaan.'),
(1671170,58,2,26,11,'Tee myös viisikymmentä vaskihakasta ja pistä hakaset silmukkoihin ja liitä teltta yhteen, niin että siitä tulee yhtenäinen.'),
(1671171,58,2,26,12,'Siitä telttakaistojen liiasta osasta, joka jää riippumaan, jääköön puolet riippumaan asumuksen takasivulle.'),
(1671172,58,2,26,13,'Ja siitä, mikä telttakaistoissa on liikaa pituutta, riippukoon kyynärän verran asumuksen kummallakin sivulla sitä peittämässä.'),
(1671173,58,2,26,14,'Ja tee teltalle peite punaisista oinaannahoista ja sen päälle vielä toinen peite sireeninnahoista.'),
(1671174,58,2,26,15,'Asumuksen laudat tee akasiapuusta, pystyyn asetettaviksi.'),
(1671175,58,2,26,16,'Jokainen lauta olkoon kymmentä kyynärää pitkä ja puoltatoista kyynärää leveä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671176,58,2,26,17,'Jokaisessa laudassa olkoon kaksi tappia, jotka ovat poikkilistalla yhdistetyt keskenään; tee näin kaikki asumuksen laudat.'),
(1671177,58,2,26,18,'Ja asumuksen lautoja tee kaksikymmentä lautaa eteläpuolta varten.'),
(1671178,58,2,26,19,'Ja tee neljäkymmentä hopeajalustaa kahdenkymmenen laudan alle, aina kaksi jalustaa kunkin laudan alle sen kahta tappia varten.'),
(1671179,58,2,26,20,'Samoin asumuksen toista sivua, pohjoispuolta, varten kaksikymmentä lautaa,'),
(1671180,58,2,26,21,'ja neljäkymmentä hopeajalustaa, aina kaksi jalustaa kunkin laudan alle.'),
(1671181,58,2,26,22,'Mutta asumuksen takasivua, länsipuolta, varten tee kuusi lautaa.'),
(1671182,58,2,26,23,'Ja tee kaksi lautaa asumuksen peränurkkia varten.'),
(1671183,58,2,26,24,'Ja ne olkoot yhteenliitettyjä kaksoislautoja ja alhaalta alkaen kiinni toisissaan ylös saakka, ensimmäiseen renkaaseen asti; näin tehtäköön ne molemmat ja asetettakoon kumpaankin nurkkaan.'),
(1671184,58,2,26,25,'Näin tulee olemaan yhteensä kahdeksan lautaa ja niihin kuusitoista hopeajalustaa, aina kaksi jalustaa kunkin laudan alla.'),
(1671185,58,2,26,26,'Tee myös viisi poikkitankoa akasiapuusta asumuksen toisen sivun lautoja varten,'),
(1671186,58,2,26,27,'ja viisi poikkitankoa asumuksen toisen sivun lautoja varten, ja viisi poikkitankoa asumuksen takasivun, länsipuolen, lautoja varten.'),
(1671187,58,2,26,28,'Ja keskimmäinen poikkitanko asetettakoon keskelle lautoja, ja kulkekoon se reunasta reunaan.'),
(1671188,58,2,26,29,'Ja päällystä laudat kullalla ja tee kullasta niiden renkaat poikkitankojen pitimiksi ja päällystä poikkitangot kullalla.'),
(1671189,58,2,26,30,'Ja aseta asumus pystyyn sen muotoiseksi, kuin sinulle vuorella näytettiin.'),
(1671190,58,2,26,31,'Tee vielä esirippu punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista; ja tehtäköön siihen taidokkaasti kudottuja kerubeja.'),
(1671191,58,2,26,32,'Ja ripusta se neljään akasiapuiseen, kullalla päällystettyyn pylvääseen, joissa on kultakoukut ja jotka seisovat neljällä hopeajalustalla.'),
(1671192,58,2,26,33,'Ja ripusta esirippu hakasten alle ja vie sinne esiripun sisäpuolelle lain arkki. Ja niin olkoon esirippu teille väliseinänä pyhän ja kaikkeinpyhimmän välillä.'),
(1671193,58,2,26,34,'Ja aseta armoistuin lain arkin päälle, joka on kaikkeinpyhimmässä.'),
(1671194,58,2,26,35,'Mutta pöytä sijoita esiripun ulkopuolelle ja seitsenhaarainen lamppu vastapäätä pöytää, asumuksen eteläsivulle; aseta siis pöytä pohjoissivulle.'),
(1671195,58,2,26,36,'Tee myös teltan oveen uudin, kirjaellen kudottu punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista.'),
(1671196,58,2,26,37,'Ja tee uudinta varten viisi pylvästä akasiapuusta ja päällystä ne kullalla, mutta niiden koukut olkoot kultaa; ja vala niille viisi vaskijalustaa."'),
(1671197,58,2,27,1,'"Ja tee alttari akasiapuusta; se olkoon neliskulmainen, viittä kyynärää pitkä ja viittä kyynärää leveä sekä kolmea kyynärää korkea.'),
(1671198,58,2,27,2,'Tee siihen sarvet, sen neljään kulmaan, niin että sarvet ovat samaa kappaletta kuin se. Ja päällystä se vaskella.'),
(1671199,58,2,27,3,'Tee siihen kuuluvat kattilat tuhan poisviemistä varten sekä lapiot, maljat, haarukat ja hiilipannut. Kaikki sen kalusto tee vaskesta.'),
(1671200,58,2,27,4,'Ja tee siihen myös verkonkaltainen ristikkokehys vaskesta ja tee verkkoon neljä vaskirengasta, ristikon neljään kulmaan.'),
(1671201,58,2,27,5,'Ja aseta se alttarin välireunuksen alle, maahan kiinni, niin että verkko ulottuu puolitiehen alttaria.'),
(1671202,58,2,27,6,'Ja tee alttariin korennot akasiapuusta ja päällystä ne vaskella.'),
(1671203,58,2,27,7,'Ja korennot pistettäköön renkaisiin, niin että korennot ovat kahden puolen alttaria, sitä kannettaessa.'),
(1671204,58,2,27,8,'Tee se laudoista, ontoksi. Niinkuin sinulle näytettiin vuorella, niin se tehtäköön.'),
(1671205,58,2,27,9,'Tee myös asumukselle esipiha. Etelän puolella olkoot esipihan ympärysverhot kerratuista valkoisista pellavalangoista, sadan kyynärän pituiset tätä yhtä sivua varten;'),
(1671206,58,2,27,10,'ja olkoon niiden pylväitä kaksikymmentä ja näiden vaskijalustoja kaksikymmentä, mutta pylväiden koukut ja niiden koristepienat olkoot hopeata.'),
(1671207,58,2,27,11,'Samoin myös pohjoisen puolella olkoot ympärysverhot sadan kyynärän pituiset; ja olkoon niiden pylväitä kaksikymmentä ja näiden vaskijalustoja kaksikymmentä, mutta pylväiden koukut ja niiden koristepienat olkoot hopeata.'),
(1671208,58,2,27,12,'Ja esipihan lännenpuoleisella sivulla olkoot ympärysverhot viidenkymmenen kyynärän pituiset, ja olkoon niiden pylväitä kymmenen ja näiden jalustoja kymmenen.'),
(1671209,58,2,27,13,'Ja esipihan leveys etupuolella, itään päin, olkoon viisikymmentä kyynärää.'),
(1671210,58,2,27,14,'Ja olkoot ympärysverhot portin toisella puolella viidentoista kyynärän pituiset, ja olkoon niiden pylväitä kolme ja näiden jalustoja kolme.'),
(1671211,58,2,27,15,'Samoin olkoot ympärysverhot toisella puolella viidentoista kyynärän pituiset, ja olkoon niiden pylväitä kolme ja näiden jalustoja kolme.'),
(1671212,58,2,27,16,'Ja esipihan portissa olkoon kahdenkymmenen kyynärän pituinen uudin, kirjaellen kudottu punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista, ja olkoon sen pylväitä neljä ja näiden jalustoja neljä.'),
(1671213,58,2,27,17,'Kaikissa pylväissä esipihan ympärillä olkoot koristepienat hopeata ja koukut hopeata, mutta jalustat vaskea.'),
(1671214,58,2,27,18,'Esipihan pituus olkoon sata kyynärää ja leveys viisikymmentä kyynärää; ympärysverho olkoon viittä kyynärää korkea ja kudottu kerratuista valkoisista pellavalangoista, ja jalustat olkoot vaskea.'),
(1671215,58,2,27,19,'Koko asumuksen kalusto kaikkia siinä tehtäviä töitä varten, samoin kuin kaikki sen vaarnat ja kaikki esipihan vaarnat, olkoot vaskea.'),
(1671216,58,2,27,20,'Ja käske israelilaisten tuoda sinulle puhdasta, survomalla saatua öljypuun öljyä seitsenhaaraista lamppua varten, että lamput aina voidaan nostaa paikoilleen.'),
(1671217,58,2,27,21,'Ilmestysmajassa, ulkopuolella esirippua, joka on lain arkin edessä, hoitakoon Aaron poikineen niitä illasta aamuun asti Herran edessä. Tämä olkoon ikuinen säädös, jota israelilaiset noudattakoot sukupolvesta sukupolveen."'),
(1671218,58,2,28,1,'"Ja kutsu eteesi israelilaisten joukosta veljesi Aaron poikineen, että he pappeina palvelisivat minua, Aaron ja hänen poikansa Naadab ja Abihu, Eleasar ja Iitamar.'),
(1671219,58,2,28,2,'Ja teetä veljellesi Aaronille pyhät vaatteet, kunniaksi ja kaunistukseksi.'),
(1671220,58,2,28,3,'Ja puhuttele kaikkia taidollisia miehiä, jotka minä olen täyttänyt taidollisuuden hengellä, että he tekevät vaatteet Aaronille, jotta hänet pyhitettäisiin pappina palvelemaan minua.'),
(1671221,58,2,28,4,'Ja nämä ovat ne vaatteet, jotka heidän on tehtävä: rintakilpi, kasukka, viitta, ruutuinen ihokas, käärelakki ja vyö. Ja he tehkööt sinun veljellesi Aaronille ja hänen pojilleen pyhät vaatteet, että he pappeina palvelisivat minua.'),
(1671222,58,2,28,5,'Ja he ottakoot tätä varten kultaa sekä punasinisiä, purppuranpunaisia ja helakanpunaisia lankoja ja valkoisia pellavalankoja.'),
(1671223,58,2,28,6,'Kasukan he tehkööt kullasta sekä punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista, taidokkaasti kutomalla.'),
(1671224,58,2,28,7,'Siinä olkoon kaksi yhdistettävää olkakappaletta, ja se kiinnitettäköön niihin molemmista päistään.'),
(1671225,58,2,28,8,'Ja vyö, jolla kasukka kiinnitetään, olkoon tehty samalla tavalla ja samasta kappaleesta kuin se: kullasta sekä punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671226,58,2,28,9,'Ota sitten kaksi onyks-kiveä ja kaiverra niihin Israelin poikien nimet,'),
(1671227,58,2,28,10,'kuusi heidän nimeään toiseen kiveen ja toiset kuusi nimeä toiseen kiveen siinä järjestyksessä, kuin he ovat syntyneet.'),
(1671228,58,2,28,11,'Niinkuin taidokkaasti hiotaan kiveä, kaiverretaan sinettisormuksia, niin kaiverra Israelin poikien nimet niihin kahteen kiveen. Ja kehystettäköön ne kultapalmikoimilla.'),
(1671229,58,2,28,12,'Ja pane molemmat kivet kasukan olkakappaleihin kiviksi, jotka johdattavat muistoon israelilaiset; näin Aaron kantakoon heidän nimiänsä molemmilla olkapäillään Herran kasvojen edessä, että heitä muistettaisiin.'),
(1671230,58,2,28,13,'Ja tee kultapalmikoimia'),
(1671231,58,2,28,14,'ja kahdet käädyt puhtaasta kullasta; tee ne punomalla, niinkuin punonnaista tehdään, ja kiinnitä punotut käädyt palmikoimiin.'),
(1671232,58,2,28,15,'Ja jumalanvastausten rintakilpi tee taidokkaasti kutomalla; tee sekin samalla tavalla, kuin kasukka on tehty: tee se kullasta sekä punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista.'),
(1671233,58,2,28,16,'Se olkoon neliskulmainen ja taskun muotoon tehty, vaaksan pituinen ja vaaksan levyinen.'),
(1671234,58,2,28,17,'Ja kiinnitä sen pintaan kiviä yliyltään, neljään riviin: ensimmäiseen riviin karneoli, topaasi ja smaragdi;'),
(1671235,58,2,28,18,'toiseen riviin rubiini, safiiri ja jaspis;'),
(1671236,58,2,28,19,'kolmanteen riviin hyasintti, akaatti ja ametisti;'),
(1671237,58,2,28,20,'ja neljänteen riviin krysoliitti, onyks ja berylli. Kultapalmikoimilla kehystettyinä kiinnitettäköön ne paikoilleen.'),
(1671238,58,2,28,21,'Kiviä olkoon Israelin poikain nimien mukaan kaksitoista, yksi kutakin nimeä kohti; kussakin kivessä olkoon yksi kahdentoista sukukunnan nimistä, kaiverrettuna samalla tavalla, kuin kaiverretaan sinettisormuksia.'),
(1671239,58,2,28,22,'Ja tee rintakilpeen puhtaasta kullasta käädyt, punotut, niinkuin punonnaista tehdään.'),
(1671240,58,2,28,23,'Ja tee rintakilpeen kaksi kultarengasta ja kiinnitä molemmat renkaat rintakilven kahteen yläkulmaan.'),
(1671241,58,2,28,24,'Ja kiinnitä ne molemmat kultapunonnaiset kahteen renkaaseen rintakilven yläkulmiin.'),
(1671242,58,2,28,25,'Ja kiinnitä molempien punonnaisten toiset kaksi päätä kahteen palmikoimaan ja kiinnitä nämä kasukan olkakappaleihin, sen etupuolelle.'),
(1671243,58,2,28,26,'Ja tee vielä kaksi kultarengasta ja pane ne rintakilven molempiin alakulmiin, sen sisäpuoliseen, kasukkaa vasten olevaan reunaan.'),
(1671244,58,2,28,27,'Ja tee vieläkin kaksi kultarengasta ja kiinnitä ne kasukan molempiin olkakappaleihin, niiden alareunaan, etupuolelle, sauman kohdalle, kasukan vyön yläpuolelle.'),
(1671245,58,2,28,28,'Ja rintakilpi solmittakoon renkaistaan punasinisellä nauhalla kasukan renkaisiin, niin että se on kasukan vyön yläpuolella; näin rintakilpi ei irtaudu kasukasta.'),
(1671246,58,2,28,29,'Ja niin Aaron kantakoon jumalanvastausten rintakilvessä sydämensä päällä, astuessaan pyhäkköön, Israelin poikain nimet, että heidät alati johdatettaisiin muistoon Herran edessä.'),
(1671247,58,2,28,30,'Ja pane jumalanvastausten rintakilpeen uurim ja tummim, niin että ne ovat Aaronin sydämen päällä, hänen astuessaan Herran eteen. Ja niin kantakoon Aaron Jumalan vastaukset israelilaisille sydämensä päällä aina Herran edessä ollessaan.'),
(1671248,58,2,28,31,'Kasukan viitta tee kokonaan punasinisistä langoista;'),
(1671249,58,2,28,32,'ja sen keskellä olkoon pääntie, ja tämä pääntie ympäröitäköön kudotulla päärmeellä niinkuin haarniskan aukko, ettei se repeäisi.'),
(1671250,58,2,28,33,'Ja tee sen helmaan granaattiomenia punasinisistä, purppuranpunaisista ja helakanpunaisista langoista, ja kiinnitä ne helmaan ympärinsä ja niiden väliin kultatiukuja yltympäri,'),
(1671251,58,2,28,34,'vuorotellen kultatiuku ja granaattiomena, viitan helmaan ympärinsä.'),
(1671252,58,2,28,35,'Ja Aaron pitäköön sen yllään toimittaessaan virkaansa, niin että kuuluu, kun hän menee pyhäkköön Herran eteen ja tulee sieltä ulos, ettei hän kuolisi.'),
(1671253,58,2,28,36,'Tee myös otsakoriste puhtaasta kullasta ja kaiverra siihen, niinkuin sinettisormusta kaiverretaan, sanat: ''Herralle pyhitetty''.'),
(1671254,58,2,28,37,'Ja sido se punasinisellä nauhalla, niin että se on kiinni käärelakissa; etupuolella käärelakkia se olkoon.'),
(1671255,58,2,28,38,'Ja se olkoon Aaronin otsalla, niin että Aaron kantaa kaiken sen, mitä israelilaiset rikkovat uhratessaan pyhiä uhrejansa ja antaessaan pyhiä lahjojansa; ja se olkoon alati hänen otsallaan, että Herran mielisuosio tulisi heidän osaksensa.'),
(1671256,58,2,28,39,'Kudo myös ruutuinen ihokas valkoisista pellavalangoista, ja tee käärelakki valkoisista pellavalangoista, ja tee vyö kirjokudoksesta.'),
(1671257,58,2,28,40,'Ja Aaronin pojille tee ihokkaat ja vyöt; ja tee heille päähineet kunniaksi ja kaunistukseksi.'),
(1671258,58,2,28,41,'Ja pue ne veljesi Aaronin ja hänen poikiensa ylle; ja voitele heidät ja vihi heidät virkaansa ja pyhitä heidät pappeina palvelemaan minua.'),
(1671259,58,2,28,42,'Ja tee heille pellavakaatiot hävyn peitteeksi; ulottukoot ne lanteilta reisiin asti.'),
(1671260,58,2,28,43,'Ja Aaron ja hänen poikansa pitäkööt ne yllään mennessänsä ilmestysmajaan, tahi kun he lähestyvät alttaria tehdäkseen palvelusta pyhäkössä, etteivät he joutuisi syynalaisiksi ja kuolisi. Tämä olkoon ikuinen säädös hänelle ja hänen jälkeläisilleen."'),
(1671261,58,2,29,1,'"Tee heille näin, pyhittääksesi heidät pappeina palvelemaan minua: Ota mullikka ja kaksi virheetöntä oinasta'),
(1671262,58,2,29,2,'ja happamatonta leipää ja öljyyn leivottuja happamattomia kakkuja ja öljyllä voideltuja happamattomia ohukaisia; leivo ne lestyistä nisujauhoista.'),
(1671263,58,2,29,3,'Ja pane ne samaan koriin ja tuo ne korissa, samalla kertaa kuin tuot mullikan ja kaksi oinasta.'),
(1671264,58,2,29,4,'Tuo sitten Aaron poikinensa ilmestysmajan ovelle ja pese heidät vedellä.'),
(1671265,58,2,29,5,'Ja ota vaatteet ja pue Aaronin ylle ihokas ja kasukan viitta ja kasukka ja rintakilpi; ja sido hänen ympärilleen kasukan vyö.'),
(1671266,58,2,29,6,'Pane myös käärelakki hänen päähänsä ja kiinnitä pyhä otsalehti käärelakkiin.'),
(1671267,58,2,29,7,'Ja ota voiteluöljyä ja vuodata hänen päähänsä ja voitele hänet.'),
(1671268,58,2,29,8,'Ja tuo hänen poikansa esille ja pue heidän ylleen ihokkaat.'),
(1671269,58,2,29,9,'Ja vyötä heidät vyöllä, sekä Aaron että hänen poikansa, ja sido päähineet heidän päähänsä, että pappeus olisi heillä ikuisena säätynä. Vihi näin virkaansa Aaron ja hänen poikansa.'),
(1671270,58,2,29,10,'Ja tuo mullikka ilmestysmajan eteen, ja Aaron poikineen laskekoon kätensä mullikan pään päälle.'),
(1671271,58,2,29,11,'Ja teurasta sitten mullikka Herran edessä, ilmestysmajan ovella.'),
(1671272,58,2,29,12,'Ja ota mullikan verta ja sivele sitä sormellasi alttarin sarviin; mutta kaikki muu veri vuodata alttarin juurelle.'),
(1671273,58,2,29,13,'Ja ota kaikki sisälmyksiä peittävä rasva ja maksanlisäke ja molemmat munuaiset ynnä niiden päällä oleva rasva, ja polta ne alttarilla.'),
(1671274,58,2,29,14,'Mutta mullikan liha, nahka ja rapa polta tulessa leirin ulkopuolella. Se on syntiuhri.'),
(1671275,58,2,29,15,'Ja ota toinen oinaista, ja Aaron poikinensa laskekoon kätensä sen oinaan pään päälle.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671276,58,2,29,16,'Teurasta sitten oinas ja ota sen veri ja vihmo se alttarille ympärinsä;'),
(1671277,58,2,29,17,'ja leikkele oinas määräkappaleiksi ja pese sen sisälmykset ja jalat ja pane ne kappaleiden ja pään päälle.'),
(1671278,58,2,29,18,'Ja polta koko oinas alttarilla. Se on polttouhri Herralle, se on suloisesti tuoksuva uhri Herralle.'),
(1671279,58,2,29,19,'Ota sitten toinen oinas, ja Aaron poikinensa laskekoon kätensä oinaan pään päälle.'),
(1671280,58,2,29,20,'Ja teurasta oinas ja ota sen verta ja sivele Aaronin ja hänen poikiensa oikean korvan lehteen ja oikean käden peukaloon ja heidän oikean jalkansa isoonvarpaaseen, mutta vihmo muu veri alttarille ympärinsä.'),
(1671281,58,2,29,21,'Ja ota alttarilla olevaa verta ja voiteluöljyä ja pirskoita Aaronin ja hänen vaatteidensa päälle, ja samoin hänen poikiensa ja heidän vaatteidensa päälle. Näin hän tulee pyhäkölle pyhitetyksi, sekä hän itse että hänen vaatteensa, ja samoin hänen poikansa ja hänen poikiensa vaatteet.'),
(1671282,58,2,29,22,'Ota sitten oinaasta rasva ja rasvahäntä ja sisälmyksiä peittävä rasva ja maksanlisäke ja molemmat munuaiset ynnä niiden päällä oleva rasva ja oikea reisi, sillä tämä on vihkiäisoinas.'),
(1671283,58,2,29,23,'Ja ota pyöreä leipä ja öljyyn leivottu kakku ja ohukainen happamattomien leipien korista, joka on Herran edessä.'),
(1671284,58,2,29,24,'Ja pane kaikki nämä Aaronin käsiin ja hänen poikiensa käsiin, että toimitettaisiin niiden heilutus Herran edessä.'),
(1671285,58,2,29,25,'Ota ne sitten heidän käsistään ja polta alttarilla, polttouhrin päällä, suloiseksi tuoksuksi Herran edessä. Se on Herran uhri.'),
(1671286,58,2,29,26,'Ja ota rintaliha Aaronin vihkiäisoinaasta ja toimituta sen heilutus Herran edessä; ja se olkoon sinun osasi.'),
(1671287,58,2,29,27,'Näin sinun on pyhitettävä heilutettu rintaliha ja anniksi annettu reisi, se, mitä on heilutettu ja anniksi annettu Aaronin ja hänen poikiensa vihkiäisoinaasta.'),
(1671288,58,2,29,28,'Ja ne olkoot Aaronin ja hänen poikiensa ikuinen osuus, israelilaisilta saatu, sillä se on anti. Se olkoon israelilaisten anti heidän yhteysuhreistaan, heidän antinsa Herralle.'),
(1671289,58,2,29,29,'Aaronin pyhät vaatteet tulkoot hänen pojillensa hänen jälkeensä, että heidät niissä voideltaisiin ja vihittäisiin virkaansa.'),
(1671290,58,2,29,30,'Seitsemänä päivänä on sen hänen pojistaan, joka tulee papiksi hänen sijaansa, puettava ne ylleen, kun hän menee ilmestysmajaan toimittamaan virkaansa pyhäkössä.'),
(1671291,58,2,29,31,'Ja ota vihkiäisoinas ja keitä sen liha pyhässä paikassa.'),
(1671292,58,2,29,32,'Ja Aaron poikinensa syököön ilmestysmajan ovella oinaan lihan ynnä leivän, joka on korissa.'),
(1671293,58,2,29,33,'He syökööt sen, mitä käytettiin heidän sovittamisekseen, kun heidät vihittiin virkaansa ja pyhitettiin, mutta syrjäinen älköön sitä syökö, sillä se on pyhää.'),
(1671294,58,2,29,34,'Jos jotakin jää tähteeksi vihkiäislihasta tai leivästä seuraavaan aamuun, polta tähteeksi jäänyt tulessa; älköön sitä syötäkö, sillä se on pyhää.'),
(1671295,58,2,29,35,'Tee näin Aaronille ja hänen pojillensa, aivan niinkuin minä olen sinua käskenyt. Seitsemän päivää kestäköön heidän vihkimisensä.'),
(1671296,58,2,29,36,'Ja uhraa joka päivä syntiuhrimullikka sovitukseksi, ja puhdista alttari toimittamalla sen sovitus ja voitele se pyhittääksesi sen.'),
(1671297,58,2,29,37,'Seitsemänä päivänä toimita alttarin sovitus ja pyhitä se. Näin tulee alttarista korkeasti-pyhä; jokainen, joka alttariin koskee, on pyhäkölle pyhitetty.'),
(1671298,58,2,29,38,'Ja uhraa alttarilla tämä: kaksi vuodenvanhaa karitsaa joka päivä, ainiaan.'),
(1671299,58,2,29,39,'Uhraa toinen karitsa aamulla ja toinen karitsa iltahämärässä,'),
(1671300,58,2,29,40,'ja kumpaakin karitsaa kohti kymmenennes lestyjä jauhoja, sekoitettuna neljännekseen hiin-mittaa survomalla saatua öljyä, ja juomauhriksi neljännes hiin-mittaa viiniä.'),
(1671301,58,2,29,41,'Ja uhraa toinen karitsa iltahämärässä; uhrattakoon se toimittamalla samankaltainen ruokauhri ja juomauhri kuin aamullakin, suloisesti tuoksuvaksi uhriksi Herralle.'),
(1671302,58,2,29,42,'Tämä olkoon teillä jokapäiväinen polttouhri sukupolvesta sukupolveen ilmestysmajan ovella Herran edessä, jossa minä ilmestyn teille puhuakseni sinun kanssasi.'),
(1671303,58,2,29,43,'Siinä minä ilmestyn israelilaisille, ja se on oleva minun kirkkauteni pyhittämä.'),
(1671304,58,2,29,44,'Ja minä pyhitän ilmestysmajan ja alttarin; ja minä pyhitän Aaronin poikinensa pappeina palvelemaan minua.'),
(1671305,58,2,29,45,'Ja minä asun israelilaisten keskellä ja olen heidän Jumalansa.'),
(1671306,58,2,29,46,'Ja he tulevat tietämään, että minä olen Herra, heidän Jumalansa, joka vein heidät pois Egyptin maasta, asuakseni heidän keskellään. Minä olen Herra, heidän Jumalansa."'),
(1671307,58,2,30,1,'"Tee myös alttari suitsutuksen polttamista varten; tee se akasiapuusta.'),
(1671308,58,2,30,2,'Olkoon se kyynärän pituinen ja kyynärän levyinen, siis neliskulmainen, ja kahta kyynärää korkea; sen sarvet olkoot samaa kappaletta kuin sekin.'),
(1671309,58,2,30,3,'Ja päällystä se puhtaalla kullalla, sekä sen levy että sivut ympärinsä ja sen sarvet; ja tee kultareunus sen ympäri.'),
(1671310,58,2,30,4,'Ja tee siihen kaksi kultarengasta; pane ne reunuksen alle, kummallekin sivulle, molempiin sivukappaleihin. Ne olkoot niiden korentojen pitiminä, joilla alttari on kannettava.'),
(1671311,58,2,30,5,'Ja tee korennotkin akasiapuusta ja päällystä ne kullalla.'),
(1671312,58,2,30,6,'Ja aseta se lain arkin edessä olevan esiripun eteen, niin että se tulee armoistuimen kohdalle, joka on lain arkin päällä ja jossa minä sinulle ilmestyn.'),
(1671313,58,2,30,7,'Ja Aaron polttakoon sen päällä hyvänhajuista suitsutusta; joka aamu, kun hän laittaa lamput kuntoon, hän polttakoon sitä.'),
(1671314,58,2,30,8,'Samoin myös, kun Aaron iltahämärässä nostaa lamput paikoilleen, hän polttakoon sitä. Tämä olkoon teillä jokapäiväinen suitsutusuhri Herran edessä sukupolvesta sukupolveen.'),
(1671315,58,2,30,9,'Älkää uhratko sen päällä vierasta suitsutusta älkääkä polttouhria tai ruokauhria; älkää myöskään vuodattako juomauhria sen päällä.'),
(1671316,58,2,30,10,'Ja Aaron toimittakoon kerran vuodessa sen sarvien sovituksen; sovitukseksi uhratun syntiuhrin verellä hän toimittakoon kerran vuodessa sen sovituksen, sukupolvesta sukupolveen. Se on korkeasti-pyhä Herralle."'),
(1671317,58,2,30,11,'Ja Herra puhui Moosekselle sanoen:'),
(1671318,58,2,30,12,'"Kun sinä lasket israelilaisten lukumäärän - niiden, joiden on oltava katselmuksessa - niin jokainen heistä suorittakoon, heistä katselmusta pidettäessä, hengestään sovitusmaksun Herralle, ettei mikään rangaistus heitä kohtaisi, heistä katselmusta pidettäessä.'),
(1671319,58,2,30,13,'Jokainen katselmuksessa oleva antakoon puoli sekeliä, pyhäkkösekelin painon mukaan, kaksikymmentä geeraa laskettuna sekeliin; puoli sekeliä olkoon anti Herralle.'),
(1671320,58,2,30,14,'Kaikki katselmuksessa olevat, kaksikymmenvuotiaat ja sitä vanhemmat, antakoot tämän annin Herralle.'),
(1671321,58,2,30,15,'Rikas älköön antako enemmän älköönkä köyhä vähemmän kuin puoli sekeliä, antina Herralle, maksaaksenne sovituksen hengestänne.'),
(1671322,58,2,30,16,'Ja ota sovitusrahat israelilaisilta ja käytä ne palvelukseen ilmestysmajassa, että israelilaiset johdatettaisiin muistoon Herran edessä teidän henkenne sovitukseksi."'),
(1671323,58,2,30,17,'Ja Herra puhui Moosekselle sanoen:'),
(1671324,58,2,30,18,'"Tee myös vaskiallas vaskijalustoineen peseytymistä varten ja aseta se ilmestysmajan ja alttarin välille ja kaada siihen vettä;'),
(1671325,58,2,30,19,'ja Aaron ja hänen poikansa peskööt siinä kätensä ja jalkansa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671326,58,2,30,20,'Kun he menevät ilmestysmajaan, peseytykööt vedessä, etteivät kuolisi; samoin myös, kun he lähestyvät alttaria ja käyvät toimittamaan virkaansa polttamalla uhrin Herralle.'),
(1671327,58,2,30,21,'He peskööt kätensä ja jalkansa, etteivät kuolisi. Ja tämä olkoon heille ikuinen säädös, hänelle itselleen ja hänen jälkeläisillensä, sukupolvesta sukupolveen."'),
(1671328,58,2,30,22,'Ja Herra puhui Moosekselle sanoen:'),
(1671329,58,2,30,23,'"Ota itsellesi hajuaineita parasta lajia: sulavaa mirhaa viisisataa sekeliä, hyvänhajuista kanelia puolet siitä eli kaksisataa viisikymmentä sekeliä ja hyvänhajuista kalmoruokoa samoin kaksisataa viisikymmentä sekeliä,'),
(1671330,58,2,30,24,'sitten vielä kassiaa viisisataa sekeliä, pyhäkkösekelin painon mukaan, ja hiin-mitta öljypuun öljyä.'),
(1671331,58,2,30,25,'Ja tee siitä pyhä voiteluöljy, höystetty voide, jollaista voiteensekoittaja valmistaa; se olkoon pyhä voiteluöljy.'),
(1671332,58,2,30,26,'Voitele sillä ilmestysmaja, lain arkki'),
(1671333,58,2,30,27,'ja pöytä kaikkine kaluineen, seitsenhaarainen lamppu kaluineen, niin myös suitsutusalttari,'),
(1671334,58,2,30,28,'polttouhrialttari kaikkine kaluineen ynnä allas jalustoineen.'),
(1671335,58,2,30,29,'Ja pyhitä ne, niin että ne tulevat korkeasti-pyhiksi. Jokainen, joka niihin koskee, tulee pyhäksi.'),
(1671336,58,2,30,30,'Voitele myös Aaron ja hänen poikansa ja pyhitä heidät pappeina palvelemaan minua.'),
(1671337,58,2,30,31,'Puhu myös israelilaisille ja sano: Tämä olkoon teillä minun pyhä voiteluöljyni sukupolvesta sukupolveen.'),
(1671338,58,2,30,32,'Kenenkään muun ihmisen ruumiille älköön sitä vuodatettako, älkääkä sen sekoitusta jäljitelkö. Pyhä se on, ja pyhänä se pitäkää.'),
(1671339,58,2,30,33,'Jokainen, joka valmistaa sellaisen voiteen, ja jokainen, joka sivelee sitä syrjäiseen, hävitettäköön kansastansa."'),
(1671340,58,2,30,34,'Ja Herra sanoi Moosekselle vielä: "Ota itsellesi hyvänhajuisia aineita, hajupihkaa, simpukankuorta, tuoksukumia, näitä hyvänhajuisia aineita, ja puhdasta suitsuketta, yhtä paljon kutakin lajia,'),
(1671341,58,2,30,35,'ja tee niistä suitsutus, höystesekoitus, jollaista voiteensekoittaja valmistaa, suolansekainen, puhdas ja pyhä.'),
(1671342,58,2,30,36,'Ja hienonna osa siitä jauhoksi ja pane sitä lain arkin eteen ilmestysmajaan, jossa minä ilmestyn sinulle. Korkeasti-pyhänä se pitäkää.'),
(1671343,58,2,30,37,'Älkää valmistako itsellenne mitään muuta suitsutusta tämän sekoituksen mukaan. Pidä tämä Herralle pyhitettynä.'),
(1671344,58,2,30,38,'Jokainen, joka sellaista tekee nauttiaksensa sen tuoksusta, hävitettäköön kansastansa."'),
(1671345,58,2,31,1,'Ja Herra puhui Moosekselle sanoen:'),
(1671346,58,2,31,2,'"Katso, minä olen nimeltään kutsunut Besalelin, Uurin pojan, Huurin pojanpojan, Juudan sukukunnasta;'),
(1671347,58,2,31,3,'ja minä olen täyttänyt hänet Jumalan hengellä, taidollisuudella, ymmärryksellä, tiedolla ja kaikkinaisella kätevyydellä'),
(1671348,58,2,31,4,'sommittelemaan taidokkaita teoksia ja valmistamaan niitä kullasta, hopeasta ja vaskesta,'),
(1671349,58,2,31,5,'hiomaan ja kiinnittämään kiviä ja veistämään puuta, tekemään kaikkinaisia töitä.'),
(1671350,58,2,31,6,'Ja katso, minä olen antanut hänelle apulaiseksi Oholiabin, Ahisamakin pojan, Daanin sukukunnasta, ja olen antanut kaikkien taidollisten sydämeen taidollisuuden tehdä kaikki, mitä minä olen sinun käskenyt teettää:'),
(1671351,58,2,31,7,'ilmestysmajan, lain arkin, armoistuimen sen päälle, kaiken majan kaluston,'),
(1671352,58,2,31,8,'pöydän kaluinensa, aitokultaisen seitsenhaaraisen lampun kaikkine kaluinensa, suitsutusalttarin,'),
(1671353,58,2,31,9,'polttouhrialttarin kaikkine kaluinensa, altaan jalustoineen,'),
(1671354,58,2,31,10,'virkapuvut ja pappi Aaronin muut pyhät vaatteet sekä hänen poikiensa pappispuvut,'),
(1671355,58,2,31,11,'voiteluöljyn ja hyvänhajuisen suitsukkeen pyhäkköä varten. He tehkööt kaiken niin, kuin minä olen sinulle käskyn antanut."'),
(1671356,58,2,31,12,'Ja Herra puhui Moosekselle sanoen:'),
(1671357,58,2,31,13,'"Puhu israelilaisille ja sano: Pitäkää minun sapattini, sillä se on merkkinä meidän välillämme, minun ja teidän, sukupolvesta sukupolveen, tietääksenne, että minä olen Herra, joka pyhitän teidät.'),
(1671358,58,2,31,14,'Siis pitäkää sapatti, sillä se on teille pyhä. Joka sen rikkoo, rangaistakoon kuolemalla; sillä kuka ikinä silloin työtä tekee, hävitettäköön kansastansa.'),
(1671359,58,2,31,15,'Kuusi päivää tehtäköön työtä, mutta seitsemäntenä päivänä on sapatti, levon päivä, Herralle pyhitetty. Kuka ikinä tekee työtä sapatinpäivänä, rangaistakoon kuolemalla.'),
(1671360,58,2,31,16,'Ja pitäkööt israelilaiset sapatin, niin että he viettävät sapattia sukupolvesta sukupolveen ikuisena liittona.'),
(1671361,58,2,31,17,'Se on oleva ikuinen merkki minun ja israelilaisten välillä; sillä kuutena päivänä Herra teki taivaan ja maan, mutta seitsemäntenä päivänä hän lepäsi ja hengähti."'),
(1671362,58,2,31,18,'Ja kun hän oli lakannut puhumasta Mooseksen kanssa Siinain vuorella, antoi hän hänelle kaksi laintaulua, kivitaulua, joitten kirjoitus oli Jumalan sormella kirjoitettu.'),
(1671363,58,2,32,1,'Mutta kun kansa näki, että Mooses viipyi eikä tullut alas vuorelta, kokoontui kansa Aaronin ympärille ja sanoi hänelle: "Nouse, tee meille jumala, joka käy meidän edellämme. Sillä me emme tiedä, mitä on tapahtunut Moosekselle, tälle miehelle, joka johdatti meidät Egyptin maasta."'),
(1671364,58,2,32,2,'Niin Aaron sanoi heille: "Irroittakaa kultarenkaat, jotka ovat vaimojenne, poikienne ja tyttärienne korvissa, ja tuokaa ne minulle".'),
(1671365,58,2,32,3,'Ja kaikki kansa irroitti kultarenkaat, jotka heillä oli korvissaan, ja he toivat ne Aaronille;'),
(1671366,58,2,32,4,'ja hän otti vastaan kullan heidän käsistään, kaavaili sitä piirtimellä ja teki siitä valetun vasikan. Ja he sanoivat: "Tämä on sinun jumalasi, Israel, se, joka on johdattanut sinut Egyptin maasta".'),
(1671367,58,2,32,5,'Kun Aaron tämän näki, rakensi hän sille alttarin; ja Aaron julisti ja sanoi: "Huomenna on Herran juhla".'),
(1671368,58,2,32,6,'Ja he nousivat varhain seuraavana päivänä ja uhrasivat polttouhreja ja toivat yhteysuhreja; ja kansa istui syömään ja juomaan, ja sitten he nousivat iloa pitämään.'),
(1671369,58,2,32,7,'Silloin Herra sanoi Moosekselle: "Mene, astu alas, sillä sinun kansasi, jonka johdatit Egyptin maasta, on turmion tehnyt.'),
(1671370,58,2,32,8,'Pian he poikkesivat siltä tieltä, jota minä käskin heidän kulkea; he tekivät itselleen valetun vasikan. Sitä he ovat kumartaneet, ja sille he ovat uhranneet ja sanoneet: ''Tämä on sinun jumalasi, Israel, se, joka on johdattanut sinut Egyptin maasta''."'),
(1671371,58,2,32,9,'Ja Herra sanoi vielä Moosekselle: "Minä näen, että tämä kansa on niskurikansa.'),
(1671372,58,2,32,10,'Anna minun olla, että vihani leimahtaisi heitä vastaan, hukuttaakseni heidät; mutta sinusta minä teen suuren kansan."'),
(1671373,58,2,32,11,'Mutta Mooses rukoili armoa Herralta, Jumalaltansa, ja sanoi: "Herra, miksi sinun vihasi syttyy omaa kansaasi vastaan, jonka olet vienyt pois Egyptin maasta suurella voimalla ja väkevällä kädellä?'),
(1671374,58,2,32,12,'Miksi egyptiläiset saisivat sanoa: ''Heidän onnettomuudekseen hän vei heidät pois, tappaaksensa heidät vuorilla ja hävittääksensä heidät maan päältä''? Käänny vihasi hehkusta ja kadu sitä turmiota, jonka aioit tuottaa kansallesi.'),
(1671375,58,2,32,13,'Muista palvelijoitasi Aabrahamia, Iisakia ja Israelia, joille olet itse kauttasi vannonut ja sanonut: ''Minä teen teidän jälkeläistenne luvun paljoksi kuin taivaan tähdet; ja koko tämän maan, josta olen puhunut, minä annan teidän jälkeläisillenne, ja he saavat sen ikuiseksi perinnöksi''."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671376,58,2,32,14,'Niin Herra katui sitä turmiota, jonka hän oli uhannut tuottaa kansallensa.'),
(1671377,58,2,32,15,'Ja Mooses kääntyi ja astui alas vuorelta, ja hänen kädessään oli kaksi laintaulua. Ja tauluihin oli kirjoitettu molemmille puolille; etupuolelle ja takapuolelle oli niihin kirjoitettu.'),
(1671378,58,2,32,16,'Ja taulut olivat Jumalan tekemät, ja kirjoitus oli Jumalan kirjoitusta, joka oli tauluihin kaiverrettu.'),
(1671379,58,2,32,17,'Kun Joosua kuuli kansan huudon, sen melutessa, sanoi hän Moosekselle: "Sotahuuto kuuluu leiristä".'),
(1671380,58,2,32,18,'Mutta tämä vastasi: "Se ei ole voittajien huutoa, eikä se ole voitettujen huutoa; minä kuulen laulua".'),
(1671381,58,2,32,19,'Ja kun Mooses lähestyi leiriä ja näki vasikan ja karkelon, niin hänen vihansa syttyi, ja hän heitti taulut käsistänsä ja murskasi ne vuoren juurella.'),
(1671382,58,2,32,20,'Senjälkeen hän otti vasikan, jonka he olivat tehneet, poltti sen tulessa ja rouhensi sen hienoksi ja hajotti veteen ja juotti sen israelilaisille.'),
(1671383,58,2,32,21,'Ja Mooses sanoi Aaronille: "Mitä tämä kansa on tehnyt sinulle, kun olet saattanut heidät näin suureen syntiin?"'),
(1671384,58,2,32,22,'Aaron vastasi: "Älköön herrani viha syttykö; sinä tiedät itse, että tämä kansa on paha.'),
(1671385,58,2,32,23,'He sanoivat minulle: ''Tee meille jumala, joka käy meidän edellämme; sillä emme tiedä, mitä on tapahtunut Moosekselle, tälle miehelle, joka johdatti meidät Egyptin maasta''.'),
(1671386,58,2,32,24,'Niin minä sanoin heille: ''Jolla on kultaa, irroittakoon sen yltänsä''; ja he antoivat sen minulle. Ja minä heitin sen tuleen, ja siitä tuli tämä vasikka."'),
(1671387,58,2,32,25,'Kun Mooses näki, että kansa oli kurittomuuden vallassa, koska Aaron oli päästänyt heidät kurittomuuden valtaan, vahingoniloksi heidän vihollisillensa,'),
(1671388,58,2,32,26,'niin Mooses seisahtui leirin portille ja huusi: "Joka on Herran oma, se tulkoon minun luokseni". Silloin kokoontuivat hänen luoksensa kaikki leeviläiset.'),
(1671389,58,2,32,27,'Ja hän sanoi heille: "Näin sanoo Herra, Israelin Jumala: ''Jokainen sitokoon miekkansa vyölleen. Käykää sitten edestakaisin leirin halki portista porttiin ja tappakaa jokainen, olkoon vaikka oma veli, ystävä tai sukulainen.''"'),
(1671390,58,2,32,28,'Niin leeviläiset tekivät Mooseksen käskyn mukaan; ja sinä päivänä kaatui kansaa noin kolmetuhatta miestä.'),
(1671391,58,2,32,29,'Ja Mooses sanoi: "Koska te nyt olette olleet omia poikianne ja veljiänne vastaan, niin vihkiytykää tänä päivänä Herran palvelukseen, että hän tänä päivänä antaisi siunauksen teille".'),
(1671392,58,2,32,30,'Seuraavana päivänä Mooses sanoi kansalle: "Te olette tehneet suuren synnin. Minä nousen nyt Herran tykö - jos ehkä voisin sovittaa teidän rikoksenne."'),
(1671393,58,2,32,31,'Ja Mooses palasi Herran tykö ja sanoi: "Voi, tämä kansa on tehnyt suuren synnin! He ovat tehneet itselleen jumalan kullasta.'),
(1671394,58,2,32,32,'Jospa nyt antaisit heidän rikoksensa anteeksi! Mutta jos et, niin pyyhi minut pois kirjastasi, johon kirjoitat."'),
(1671395,58,2,32,33,'Mutta Herra vastasi Moosekselle: "Joka on tehnyt syntiä minua vastaan, sen minä pyyhin pois kirjastani.'),
(1671396,58,2,32,34,'Mene nyt ja johdata kansa siihen paikkaan, josta minä olen sinulle puhunut; katso, minun enkelini käy sinun edelläsi. Mutta kostoni päivänä minä kostan heille heidän rikoksensa."'),
(1671397,58,2,32,35,'Niin Herra rankaisi kansaa, koska he olivat teettäneet vasikan, jonka Aaron teki.'),
(1671398,58,2,33,1,'Sitten Herra sanoi Moosekselle: "Lähde täältä ja vaella, sinä ja kansa, jonka olet johdattanut Egyptin maasta, siihen maahan, jonka minä olen vannoen luvannut Aabrahamille, Iisakille ja Jaakobille, sanoen: ''Sinun jälkeläisillesi minä annan sen''.'),
(1671399,58,2,33,2,'Ja minä lähetän enkelin sinun edelläsi ja karkoitan pois kanaanilaiset, amorilaiset, heettiläiset, perissiläiset, hivviläiset ja jebusilaiset,'),
(1671400,58,2,33,3,'että tulisit siihen maahan, joka vuotaa maitoa ja mettä. Sillä minä en itse vaella sinun kanssasi, koska olet niskurikansa, etten minä sinua tiellä hukuttaisi."'),
(1671401,58,2,33,4,'Kun kansa kuuli tämän kovan puheen, tulivat he murheellisiksi, eikä yksikään pukenut koristuksiaan yllensä.'),
(1671402,58,2,33,5,'Ja Herra sanoi Moosekselle: "Sano israelilaisille: Te olette niskurikansa. Jos minä silmänräpäyksenkään vaeltaisin sinun keskelläsi, minä hukuttaisin sinut. Riisu nyt koristuksesi yltäsi, niin minä ajattelen, mitä sinulle tekisin."'),
(1671403,58,2,33,6,'Niin israelilaiset riisuivat koristuksensa ja olivat Hoorebin vuoren luota lähtien ilman niitä.'),
(1671404,58,2,33,7,'Mutta Mooses otti majan ja pystytti sen leirin ulkopuolelle, jonkun matkan päähän leiristä, ja kutsui sen ilmestysmajaksi; ja jokaisen, jolla oli kysyttävää Herralta, oli mentävä ilmestysmajalle, leirin ulkopuolelle.'),
(1671405,58,2,33,8,'Ja kun Mooses lähti majalle, nousi koko kansa, ja kukin asettui majansa ovelle ja katseli Mooseksen jälkeen, kunnes hän oli mennyt majaan.'),
(1671406,58,2,33,9,'Ja aina kun Mooses meni majaan, laskeutui pilvenpatsas ja seisahtui majan ovelle; ja Herra puhutteli Moosesta.'),
(1671407,58,2,33,10,'Ja kaikki kansa näki pilvenpatsaan seisovan majan ovella; niin kaikki kansa nousi, ja he kumartuivat itsekukin majansa ovella.'),
(1671408,58,2,33,11,'Ja Herra puhutteli Moosesta kasvoista kasvoihin, niinkuin mies puhuttelee toista. Sitten Mooses palasi takaisin leiriin; mutta Joosua, Nuunin poika, hänen apumiehensä ja palvelijansa, ei poistunut majasta.'),
(1671409,58,2,33,12,'Ja Mooses sanoi Herralle: "Katso, sinä sanot minulle: ''Johdata tämä kansa sinne'', mutta et ole ilmoittanut minulle, kenen sinä lähetät minun kanssani. Ja kuitenkin sinä sanoit: ''Minä tunnen sinut nimeltäsi, ja sinä olet myös saanut armon minun silmieni edessä''.'),
(1671410,58,2,33,13,'Jos siis olen saanut armon sinun silmiesi edessä, niin ilmoita minulle tiesi, että tulisin tuntemaan sinut ja tietäisin saaneeni armon sinun silmiesi edessä; ja katso: tämä kansa on sinun kansasi."'),
(1671411,58,2,33,14,'Hän sanoi: "Pitäisikö minun kasvojeni käymän sinun kanssasi ja minun viemän sinut lepoon?"'),
(1671412,58,2,33,15,'Hän vastasi hänelle: "Elleivät sinun kasvosi käy meidän kanssamme, niin älä johdata meitä täältä pois.'),
(1671413,58,2,33,16,'Sillä mistä muutoin tiedetään, että minä olen saanut armon sinun silmiesi edessä, minä ja sinun kansasi, ellei siitä, että sinä käyt meidän kanssamme, niin että me, minä ja sinun kansasi, olemme erikoiset kaikkien kansojen joukossa, jotka maan päällä ovat?"'),
(1671414,58,2,33,17,'Herra vastasi Moosekselle: "Mitä sinä nyt pyydät, sen minä myös teen; sillä sinä olet saanut armon minun silmieni edessä, ja minä tunnen sinut nimeltäsi".'),
(1671415,58,2,33,18,'Silloin hän sanoi: "Anna siis minun nähdä sinun kirkkautesi".'),
(1671416,58,2,33,19,'Hän vastasi: "Minä annan kaiken ihanuuteni käydä sinun ohitsesi ja huudan nimen ''Herra'' sinun edessäsi. Ja minä olen armollinen, kenelle olen armollinen, armahdan, ketä armahdan".'),
(1671417,58,2,33,20,'Ja hän sanoi vielä: "Sinä et voi nähdä minun kasvojani; sillä ei kukaan, joka näkee minut, jää eloon".'),
(1671418,58,2,33,21,'Sitten Herra sanoi: "Katso, tässä on paikka minun läheisyydessäni; astu tuohon kalliolle.'),
(1671419,58,2,33,22,'Ja kun minun kirkkauteni kulkee ohitse, asetan minä sinut kallion rotkoon ja peitän sinut kädelläni, kunnes olen kulkenut ohi.'),
(1671420,58,2,33,23,'Kun minä sitten siirrän pois käteni, näet sinä minun selkäpuoleni; mutta minun kasvojani ei voi kenkään katsoa."'),
(1671421,58,2,34,1,'Ja Herra sanoi Moosekselle: "Veistä itsellesi kaksi kivitaulua, entisten kaltaista, niin minä kirjoitan niihin tauluihin ne sanat, jotka olivat entisissä tauluissa, jotka sinä murskasit.'),
(1671422,58,2,34,2,'Ole siis huomenaamuksi valmis; ja nouse huomenaamuna Siinain vuorelle ja seiso siellä minua vastassa vuoren huipulla.'),
(1671423,58,2,34,3,'Mutta älköön kukaan nousko sinne sinun kanssasi, älköönkä ketään näkykö koko vuorella; lampaitakaan ja karjaa älköön käykö laitumella vuoren vaiheilla."'),
(1671424,58,2,34,4,'Ja Mooses veisti kaksi kivitaulua, entisten kaltaista. Ja varhain seuraavana aamuna Mooses nousi Siinain vuorelle, niinkuin Herra oli häntä käskenyt, ja otti ne kaksi kivitaulua käteensä.'),
(1671425,58,2,34,5,'Niin Herra astui alas pilvessä, ja Mooses asettui siellä hänen läheisyyteensä ja huusi Herran nimeä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671426,58,2,34,6,'Ja Herra kulki hänen ohitsensa ja huusi: "Herra, Herra on laupias ja armahtavainen Jumala, pitkämielinen ja suuri armossa ja uskollisuudessa,'),
(1671427,58,2,34,7,'joka pysyy armollisena tuhansille, joka antaa anteeksi pahat teot, rikokset ja synnit, mutta ei kuitenkaan jätä rankaisematta, vaan kostaa isien pahat teot lapsille ja lasten lapsille kolmanteen ja neljänteen polveen".'),
(1671428,58,2,34,8,'Niin Mooses kumartui nopeasti maahan ja rukoili ja sanoi:'),
(1671429,58,2,34,9,'"Herra, jos olen saanut armon sinun silmiesi edessä, niin käyköön Herra meidän keskellämme. Sillä tämä on tosin niskurikansa, mutta anna anteeksi meidän pahat tekomme ja syntimme ja ota meidät perintöosaksesi."'),
(1671430,58,2,34,10,'Hän vastasi: "Katso, minä teen liiton, minä teen kaiken sinun kansasi nähden ihmeellisiä tekoja, joiden kaltaisia ei ole tehty yhdessäkään maassa, ei minkään kansan keskuudessa. Niin koko kansa, jonka keskellä sinä olet, on näkevä Herran teot, sillä peljättävää on se, mitä minä sinulle teen.'),
(1671431,58,2,34,11,'Noudata, mitä minä tänä päivänä käsken sinun noudattaa. Katso, minä karkoitan sinun tieltäsi amorilaiset, kanaanilaiset, heettiläiset, perissiläiset, hivviläiset ja jebusilaiset.'),
(1671432,58,2,34,12,'Kavahda, ettet tee liittoa sen maan asukasten kanssa, johon tulet, etteivät he tulisi teidän keskuudessanne ansaksi;'),
(1671433,58,2,34,13,'vaan kukistakaa heidän alttarinsa ja murskatkaa heidän patsaansa ja hakatkaa maahan heidän asera-karsikkonsa.'),
(1671434,58,2,34,14,'Älä kumarra muuta jumalaa; sillä Herra on nimeltänsä Kiivas, hän on kiivas Jumala.'),
(1671435,58,2,34,15,'Älä siis tee liittoa maan asukasten kanssa, ettet, kun he kulkevat haureudessa jumaliensa jäljessä ja uhraavat jumalillensa ja kutsuvat sinua, sinä söisi heidän uhristaan,'),
(1671436,58,2,34,16,'ja etteivät heidän tyttärensä, kun sinä otat heitä pojillesi vaimoiksi ja kun he kulkevat haureudessa jumaliensa jäljessä, viettelisi sinun poikiasikin haureudessa kulkemaan heidän jumaliensa jäljessä.'),
(1671437,58,2,34,17,'Älä tee itsellesi valettuja jumalankuvia.'),
(1671438,58,2,34,18,'Vietä happamattoman leivän juhlaa: seitsemänä päivänä syö happamatonta leipää, niinkuin minä olen sinua käskenyt, määrättynä aikana, aabib-kuussa, sillä aabib-kuussa sinä olet lähtenyt Egyptistä.'),
(1671439,58,2,34,19,'Kaikki, mikä avaa äidinkohdun, on minun; samoin myös kaikki sinun karjasi urospuolet, raavaittesi ja lampaittesi ensiksisynnyttämät.'),
(1671440,58,2,34,20,'Mutta aasin ensiksisynnyttämä lunasta lampaalla, mutta jos et sitä lunasta, niin taita siltä niska. Jokainen esikoinen pojistasi lunasta. Ja tyhjin käsin älköön tultako minun kasvojeni eteen.'),
(1671441,58,2,34,21,'Kuusi päivää tee työtä, mutta lepää seitsemäs päivä; kyntö- ja elonleikkuuaikanakin sinun on levättävä.'),
(1671442,58,2,34,22,'Ja vietä viikkojuhla, kun leikkaat nisusi uutisen, ja korjuujuhla vuoden vaihteessa.'),
(1671443,58,2,34,23,'Kolme kertaa vuodessa kaikki sinun miesväkesi tulkoon Herran, sinun Herrasi, Israelin Jumalan, kasvojen eteen.'),
(1671444,58,2,34,24,'Sillä minä karkoitan kansat sinun tieltäsi ja laajennan sinun alueesi; eikä kukaan ole himoitseva sinun maatasi, kun sinä kolme kertaa vuodessa vaellat tullaksesi Herran, sinun Jumalasi, kasvojen eteen.'),
(1671445,58,2,34,25,'Älä uhraa minun teurasuhrini verta happamen leivän ohella. Ja pääsiäisjuhlan uhrista älköön mitään jääkö yli yön seuraavaan aamuun.'),
(1671446,58,2,34,26,'Parhaat maasi uutisesta tuo Herran, sinun Jumalasi, huoneeseen. Älä keitä vohlaa emänsä maidossa."'),
(1671447,58,2,34,27,'Ja Herra sanoi Moosekselle: "Kirjoita itsellesi nämä sanat, sillä näiden sanojen mukaisesti minä olen tehnyt liiton sinun ja Israelin kanssa".'),
(1671448,58,2,34,28,'Ja hän oli siellä Herran tykönä neljäkymmentä päivää ja neljäkymmentä yötä syömättä ja juomatta. Ja hän kirjoitti tauluihin liiton sanat, ne kymmenen sanaa.'),
(1671449,58,2,34,29,'Ja kun Mooses astui alas Siinain vuorelta ja hänellä vuorelta alas astuessaan oli kädessänsä kaksi laintaulua, ei hän tiennyt, että hänen kasvojensa iho oli tullut säteileväksi hänen puhuessaan Herran kanssa.'),
(1671450,58,2,34,30,'Ja kun Aaron ja kaikki israelilaiset näkivät Mooseksen kasvojen ihon säteilevän, pelkäsivät he lähestyä häntä.'),
(1671451,58,2,34,31,'Mutta Mooses huusi heitä; niin Aaron ja kaikki kansan päämiehet kääntyivät takaisin hänen luokseen, ja Mooses puhui heille.'),
(1671452,58,2,34,32,'Sitten kaikki israelilaiset lähestyivät häntä, ja hän käski heidän noudattaa kaikkea, mitä Herra oli puhunut hänelle Siinain vuorella.'),
(1671453,58,2,34,33,'Ja kun Mooses oli lakannut puhumasta heidän kanssaan, pani hän peitteen kasvoillensa.'),
(1671454,58,2,34,34,'Mutta niin usein kuin hän meni Herran eteen puhuttelemaan häntä, poisti hän peitteen, siksi kunnes tuli ulos. Ja tultuaan ulos hän puhui israelilaisille, mitä hänen oli käsketty puhua.'),
(1671455,58,2,34,35,'Ja israelilaiset näkivät joka kerta Mooseksen kasvojen ihon säteilevän; ja Mooses veti peitteen kasvoillensa, siksi kunnes hän jälleen meni puhuttelemaan häntä.'),
(1671456,58,2,35,1,'Ja Mooses kokosi kaiken Israelin kansan ja sanoi heille: "Näin on Herra käskenyt teidän tehdä:'),
(1671457,58,2,35,2,'Kuusi päivää tehtäköön työtä, mutta seitsemäs päivä olkoon teille pyhä sapatti, levon päivä, Herralle pyhitetty. Kuka ikinä silloin työtä tekee, se surmattakoon.'),
(1671458,58,2,35,3,'Älkää sytyttäkö tulta sapatin päivänä, missä asuttekin."'),
(1671459,58,2,35,4,'Ja Mooses sanoi koko Israelin kansalle näin: "Näin on Herra käskenyt ja sanonut:'),
(1671460,58,2,35,5,'Ottakaa siitä, mitä teillä on, anti Herralle; jokainen, jonka sydän on siihen altis, tuokoon anniksi Herralle kultaa, hopeata ja vaskea,'),
(1671461,58,2,35,6,'punasinisiä, purppuranpunaisia ja helakanpunaisia lankoja ja valkoisia pellavalankoja sekä vuohenkarvoja,'),
(1671462,58,2,35,7,'punaisia oinaannahkoja, sireeninnahkoja, akasiapuuta,'),
(1671463,58,2,35,8,'öljyä seitsenhaaraista lamppua varten, hajuaineita voiteluöljyä ja hyvänhajuista suitsutusta varten,'),
(1671464,58,2,35,9,'onyks-kiviä ja muita jalokiviä kasukkaa ja rintakilpeä varten.'),
(1671465,58,2,35,10,'Ja kaikki taidolliset teidän keskuudessanne tulkoot ja tehkööt kaikki, mitä Herra on käskenyt:'),
(1671466,58,2,35,11,'asumuksen telttoineen ja peitteineen, hakasineen, lautoineen, poikkitankoineen, pylväineen ja jalustoineen,'),
(1671467,58,2,35,12,'arkin korentoineen, armoistuimen ja sitä verhoavan esiripun,'),
(1671468,58,2,35,13,'pöydän korentoineen ja kaikkine kaluineen sekä näkyleivät,'),
(1671469,58,2,35,14,'seitsenhaaraisen lampun kaluineen ja lamppuineen, öljyä seitsenhaaraista lamppua varten,'),
(1671470,58,2,35,15,'suitsutusalttarin korentoineen, voiteluöljyn ja hyvänhajuisen suitsukkeen, oviuutimen asumuksen ovelle,'),
(1671471,58,2,35,16,'polttouhrialttarin vaskiristikkoineen, korentoineen ja kaikkine kaluineen, altaan jalustoineen,'),
(1671472,58,2,35,17,'esipihan ympärysverhot pylväineen ja jalustoineen sekä esipihan porttiin uutimen,'),
(1671473,58,2,35,18,'asumuksen vaarnat ja esipihan vaarnat köysineen,'),
(1671474,58,2,35,19,'virkapuvut pyhäkköpalvelusta varten ja pappi Aaronin muut pyhät vaatteet sekä hänen poikiensa pappispuvut."'),
(1671475,58,2,35,20,'Ja kaikki israelilaisten seurakunta meni pois Mooseksen luota.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671476,58,2,35,21,'Sitten he tulivat takaisin, jokainen, jonka sydän häntä siihen vaati, ja jokainen, jonka henki oli siihen altis, ja toivat antinsa Herralle ilmestysmajan valmistamista varten ja kaikkea siinä vietettävää jumalanpalvelusta varten ja pyhiä vaatteita varten.'),
(1671477,58,2,35,22,'He tulivat, sekä miehet että naiset, jokainen, jonka sydän oli siihen altis, ja toivat solkia, korvarenkaita, sormuksia ja kaulakoristeita, kaikkinaisia kultakaluja - jokainen, joka toi Herralle kultaa heilutusuhriksi.'),
(1671478,58,2,35,23,'Ja jokainen, jolla oli punasinisiä, purppuranpunaisia ja helakanpunaisia lankoja, valkoisia pellavalankoja, vuohen karvoja, punaisia oinaannahkoja tai sireeninnahkoja, toi niitä.'),
(1671479,58,2,35,24,'Ja jokainen, joka voi antaa anniksi hopeata ja vaskea, toi annin Herralle. Ja jokainen, jolla oli akasiapuuta, toi sitä kaikkinaisten töiden valmistamista varten.'),
(1671480,58,2,35,25,'Ja kaikki taitavat naiset kehräsivät omin käsin ja toivat kehräämänsä punasiniset, purppuranpunaiset ja helakanpunaiset langat ja valkoiset pellavalangat;'),
(1671481,58,2,35,26,'ja kaikki naiset, joiden taidollinen sydän heitä siihen vaati, kehräsivät vuohenkarvoja.'),
(1671482,58,2,35,27,'Mutta päämiehet toivat onyks-kiviä ja muita jalokiviä kasukkaa ja rintakilpeä varten,'),
(1671483,58,2,35,28,'ja hajuaineita ja öljyä seitsenhaaraista lamppua varten sekä voiteluöljyksi ja hyvänhajuiseksi suitsutukseksi.'),
(1671484,58,2,35,29,'Kaikki israelilaiset, miehet ja naiset, joiden sydän oli altis ja vaati heitä tuomaan jotakin niitä töitä varten, joita Herra Mooseksen kautta oli käskenyt tehdä, toivat vapaaehtoisen lahjan Herralle.'),
(1671485,58,2,35,30,'Ja Mooses sanoi israelilaisille: "Katsokaa, Herra on nimeltään kutsunut Besalelin, Uurin pojan, Huurin pojanpojan, Juudan sukukunnasta,'),
(1671486,58,2,35,31,'ja on täyttänyt hänet Jumalan hengellä, taidollisuudella, ymmärryksellä, tiedolla ja kaikkinaisella kätevyydellä'),
(1671487,58,2,35,32,'sommittelemaan taidokkaita teoksia ja valmistamaan niitä kullasta, hopeasta ja vaskesta,'),
(1671488,58,2,35,33,'hiomaan ja kiinnittämään kiviä ja veistämään puuta, tekemään kaikkinaisia taidokkaita töitä.'),
(1671489,58,2,35,34,'Hänelle ja Oholiabille, Ahisamakin pojalle, Daanin sukukunnasta, hän on myös antanut kyvyn opettaa muita.'),
(1671490,58,2,35,35,'Nämä hän on täyttänyt taidollisuudella tekemään kaikkinaisia töitä, jommoisia tekevät seppä, kuvakudosten tekijä, kirjokankaiden kutoja, joka valmistaa punasinisiä, purppuranpunaisia ja helakanpunaisia kankaita ja valkoisia pellavakankaita, sekä muu kankuri, ne, jotka valmistavat kaikkinaisia töitä ja sommittelevat taidokkaita teoksia."'),
(1671491,58,2,36,1,'"Ja Besalel ja Oholiab ynnä kaikki taidolliset, joille Herra on antanut taidollisuuden ja ymmärryksen tietää, miten mikin pyhäkössä tehtävä työ on suoritettava, tehkööt kaikissa kohdin, niinkuin Herra on käskenyt."'),
(1671492,58,2,36,2,'Niin Mooses kutsui luoksensa Besalelin ja Oholiabin ja kaikki taidolliset, joiden sydämeen Herra oli antanut taidollisuuden, kaikki, joiden sydän vaati heitä ryhtymään työhön suorittaaksensa sen.'),
(1671493,58,2,36,3,'Ja he ottivat Moosekselta kaikki annit, jotka israelilaiset olivat tuoneet pyhäkössä tehtävien töiden suorittamista varten. Mutta he toivat hänelle vielä joka aamu vapaaehtoisia lahjoja.'),
(1671494,58,2,36,4,'Niin tulivat kaikki taidolliset, jotka tekivät kaikkinaista työtä pyhäkössä, mies toisensa jälkeen, siitä työstä, jota kukin oli tekemässä,'),
(1671495,58,2,36,5,'ja sanoivat Moosekselle näin: "Kansa tuo enemmän, kuin mitä tarvitaan sen työn valmistamiseksi, jonka Herra on käskenyt tehdä".'),
(1671496,58,2,36,6,'Niin Mooses käski kuuluttaa leirissä ja sanoa: "Älköön kukaan, mies tai nainen, enää valmistako mitään anniksi pyhäkköä varten". Ja niin kansa lakkasi tuomasta lahjoja.'),
(1671497,58,2,36,7,'Sillä kaikkea työtä varten, mikä oli tehtävä, oli jo koottu riittävästi, jopa liiaksikin.'),
(1671498,58,2,36,8,'Ja niin kaikki taidolliset, jotka siinä työssä olivat, tekivät asumuksen kymmenestä telttakankaan kaistasta, jotka olivat valmistetut kerratuista valkoisista pellavalangoista ja punasinisistä, purppuranpunaisista ja helakanpunaisista langoista; ja niihin tehtiin taidokkaasti kudottuja kerubeja.'),
(1671499,58,2,36,9,'Kunkin kaistan pituus oli kaksikymmentä kahdeksan kyynärää ja leveys neljä kyynärää; kaikilla kaistoilla oli sama mitta.'),
(1671500,58,2,36,10,'Ja viisi kaistaa yhdistettiin toisiinsa, ja samoin toiset viisi kaistaa yhdistettiin toisiinsa.'),
(1671501,58,2,36,11,'Sitten tehtiin silmukat punasinisestä langasta ensimmäisen kaistan reunaan, yhdistetyn kappaleen laitaan, ja samoin toisen yhdistetyn kappaleen viimeisen kaistan reunaan.'),
(1671502,58,2,36,12,'Viisikymmentä silmukkaa tehtiin ensimmäiseen kaistaan ja viisikymmentä silmukkaa vastaavan kaistan laitaan, toiseen yhdistettyyn kappaleeseen, niin että silmukat olivat kohdakkain.'),
(1671503,58,2,36,13,'Ja sitten tehtiin viisikymmentä kultahakasta, ja kaistat yhdistettiin toisiinsa näillä hakasilla, niin että siitä tuli yhtenäinen asumus.'),
(1671504,58,2,36,14,'Vielä tehtiin vuohen karvoista telttakankaan kaistoja asumusta suojaavaksi teltaksi; niitä kaistoja tehtiin yksitoista.'),
(1671505,58,2,36,15,'Kunkin kaistan pituus oli kolmekymmentä kyynärää ja leveys neljä kyynärää; niillä yhdellätoista kaistalla oli sama mitta.'),
(1671506,58,2,36,16,'Kaistat liitettiin yhteen, viisi kaistaa erikseen ja kuusi kaistaa erikseen.'),
(1671507,58,2,36,17,'Ja viisikymmentä silmukkaa tehtiin toisen yhdistetyn kappaleen viimeisen kaistan reunaan ja viisikymmentä silmukkaa toisen yhdistetyn kappaleen vastaavan kaistan reunaan.'),
(1671508,58,2,36,18,'Sitten tehtiin viisikymmentä vaskihakasta, joilla teltta liitettiin yhteen, niin että siitä tuli yhtenäinen.'),
(1671509,58,2,36,19,'Vielä tehtiin teltalle peite punaisista oinaannahoista ja sen päälle vielä toinen peite sireeninnahoista.'),
(1671510,58,2,36,20,'Asumuksen laudat tehtiin akasiapuusta, pystyyn asetettaviksi.'),
(1671511,58,2,36,21,'Jokainen lauta oli kymmentä kyynärää pitkä ja puoltatoista kyynärää leveä.'),
(1671512,58,2,36,22,'Jokaisessa laudassa oli kaksi tappia, jotka olivat poikkilistalla yhdistetyt keskenään; näin tehtiin kaikki asumuksen laudat.'),
(1671513,58,2,36,23,'Ja asumuksen lautoja tehtiin kaksikymmentä lautaa eteläpuolta varten.'),
(1671514,58,2,36,24,'Ja tehtiin neljäkymmentä hopeajalustaa kahdenkymmenen laudan alle, aina kaksi jalustaa kunkin laudan alle, sen kahta tappia varten.'),
(1671515,58,2,36,25,'Samoin asumuksen toista sivua, pohjoispuolta, varten tehtiin kaksikymmentä lautaa,'),
(1671516,58,2,36,26,'ja neljäkymmentä hopeajalustaa, aina kaksi jalustaa kunkin laudan alle.'),
(1671517,58,2,36,27,'Mutta asumuksen takasivua, länsipuolta, varten tehtiin kuusi lautaa.'),
(1671518,58,2,36,28,'Ja kaksi lautaa tehtiin asumuksen peränurkkia varten,'),
(1671519,58,2,36,29,'ja ne olivat yhteenliitettyjä kaksoislautoja ja alhaalta alkaen kiinni toisissaan ylös saakka, ensimmäiseen renkaaseen asti; näin ne molemmat tehtiin kumpaakin nurkkaa varten.'),
(1671520,58,2,36,30,'Näin tuli olemaan yhteensä kahdeksan lautaa ja niihin kuusitoista hopeajalustaa, aina kaksi jalustaa kunkin laudan alla.'),
(1671521,58,2,36,31,'Sitten tehtiin myös viisi poikkitankoa akasiapuusta asumuksen toisen sivun lautoja varten'),
(1671522,58,2,36,32,'ja viisi poikkitankoa asumuksen toisen sivun lautoja varten ja viisi poikkitankoa asumuksen takasivun, länsipuolen, lautoja varten.'),
(1671523,58,2,36,33,'Ja keskimmäinen poikkitanko tehtiin kulkemaan lautojen keskikohdalta, reunasta reunaan.'),
(1671524,58,2,36,34,'Ja laudat päällystettiin kullalla, ja niiden renkaat tehtiin kullasta poikkitankojen pitimiksi, ja poikkitangotkin päällystettiin kullalla.'),
(1671525,58,2,36,35,'Vielä tehtiin esirippu punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista; ja siihen tehtiin taidokkaasti kudottuja kerubeja.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671526,58,2,36,36,'Ja siihen tehtiin neljä pylvästä akasiapuusta, ja ne päällystettiin kullalla, ja niiden koukut olivat kultaa; ja niitä varten valettiin neljä hopeajalustaa.'),
(1671527,58,2,36,37,'Sitten tehtiin myös teltan oveen uudin, kirjaellen kudottu punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista,'),
(1671528,58,2,36,38,'ja siihen viisi pylvästä koukkuineen; ja niiden päät ja niiden koristepienat päällystettiin kullalla, ja niiden viisi jalustaa tehtiin vaskesta.'),
(1671529,58,2,37,1,'Ja Besalel teki arkin akasiapuusta, puolenkolmatta kyynärän pituisen, puolentoista kyynärän levyisen ja puolentoista kyynärän korkuisen.'),
(1671530,58,2,37,2,'Ja hän päällysti sen puhtaalla kullalla sisältä ja ulkoa ja teki siihen kultareunuksen yltympäri.'),
(1671531,58,2,37,3,'Ja hän valoi siihen neljä kultarengasta, sen neljään kulmaan, niin että kaksi rengasta tuli sen toiselle puolelle ja kaksi rengasta sen toiselle puolelle.'),
(1671532,58,2,37,4,'Ja hän teki korennot akasiapuusta ja päällysti ne kullalla.'),
(1671533,58,2,37,5,'Ja hän pisti arkin sivuilla oleviin renkaisiin korennot, joilla arkki oli kannettava.'),
(1671534,58,2,37,6,'Ja hän teki armoistuimen puhtaasta kullasta, puoltakolmatta kyynärää pitkän ja puoltatoista kyynärää leveän.'),
(1671535,58,2,37,7,'Ja hän teki kaksi kultakerubia, kohotakoista tekoa, armoistuimen molempiin päihin,'),
(1671536,58,2,37,8,'toisen kerubin toiseen päähän ja toisen kerubin toiseen päähän. Armoistuimesta kohoaviksi hän teki kerubit, sen kumpaankin päähän.'),
(1671537,58,2,37,9,'Ja kerubit levittivät siipensä ylöspäin, niin että ne peittivät siivillänsä armoistuimen, ja niiden kasvot olivat vastakkain; kerubien kasvot olivat käännetyt armoistuinta kohti.'),
(1671538,58,2,37,10,'Hän teki myös pöydän akasiapuusta, kahta kyynärää pitkän, kyynärää leveän ja puoltatoista kyynärää korkean.'),
(1671539,58,2,37,11,'Ja hän päällysti sen puhtaalla kullalla ja teki siihen kultareunuksen yltympäri.'),
(1671540,58,2,37,12,'Ja hän teki sen ympäri kämmenen korkuisen listan, ja listan ympäri kultareunuksen.'),
(1671541,58,2,37,13,'Ja hän valoi siihen neljä kultarengasta ja kiinnitti renkaat neljään kulmaan, sen neljän jalan kohdalle.'),
(1671542,58,2,37,14,'Renkaat olivat juuri listan alla niiden korentojen pitiminä, joilla pöytä oli kannettava.'),
(1671543,58,2,37,15,'Ja hän teki korennot akasiapuusta ja päällysti ne kullalla; ja niillä oli pöytä kannettava.'),
(1671544,58,2,37,16,'Hän teki puhtaasta kullasta pöydällä pidettävät astiat: vadit ja kupit, maljat ja kannut, joista juomauhri vuodatetaan.'),
(1671545,58,2,37,17,'Hän teki myös seitsenhaaraisen lampun puhtaasta kullasta. Kohotakoista tekoa hän teki seitsenhaaraisen lampun jalkoineen ja varsineen; sen kukkakuvut, nuput kukkalehtineen, olivat samaa kappaletta kuin se.'),
(1671546,58,2,37,18,'Kuusi haaraa lähti lampun sivuista, kolme haaraa toisesta sivusta ja kolme haaraa toisesta sivusta.'),
(1671547,58,2,37,19,'Toisessa haarassa oli kolme mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen, ja toisessa haarassa samoin kolme mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen; näin oli jokaisessa kuudessa haarassa, jotka lampusta lähtivät.'),
(1671548,58,2,37,20,'Mutta itse seitsenhaaraisessa lampussa oli neljä mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen.'),
(1671549,58,2,37,21,'Yksi nuppu oli aina jokaisen haaraparin alla niistä kuudesta haarasta, jotka lampusta lähtivät.'),
(1671550,58,2,37,22,'Nuput ja haarat olivat samaa kappaletta kuin se; se oli kokonaan samaa kohotakoista tekoa, puhdasta kultaa.'),
(1671551,58,2,37,23,'Ja hän teki siihen seitsemän lamppua ja siihen kuuluvat lamppusakset ja karstakupit puhtaasta kullasta.'),
(1671552,58,2,37,24,'Yhdestä talentista puhdasta kultaa hän teki sekä sen että kaikki sen kalut.'),
(1671553,58,2,37,25,'Hän teki myös suitsutusalttarin akasiapuusta, kyynärän pituisen ja kyynärän levyisen, siis neliskulmaisen, ja kahta kyynärää korkean; sen sarvet olivat samaa kappaletta kuin se.'),
(1671554,58,2,37,26,'Ja hän päällysti sen puhtaalla kullalla, sekä sen levyn että sivut ympärinsä ja sen sarvet; ja hän teki kultareunuksen sen ympäri.'),
(1671555,58,2,37,27,'Ja hän teki siihen kaksi kultarengasta reunuksen alle molemmin puolin, molempiin sivuihin, niiden korentojen pitimiksi, joilla alttari oli kannettava.'),
(1671556,58,2,37,28,'Ja korennotkin hän teki akasiapuusta ja päällysti ne kullalla.'),
(1671557,58,2,37,29,'Ja hän teki pyhän voiteluöljyn ja puhtaan, hyvänhajuisen suitsukkeen, jollaista voiteensekoittaja valmistaa.'),
(1671558,58,2,38,1,'Ja hän teki polttouhrialttarin akasiapuusta, neliskulmaisen, viittä kyynärää pitkän, viittä kyynärää leveän ja kolmea kyynärää korkean.'),
(1671559,58,2,38,2,'Ja hän teki siihen sarvet, sen neljään kulmaan, niin että sarvet olivat samaa kappaletta kuin se. Ja hän päällysti sen vaskella.'),
(1671560,58,2,38,3,'Ja hän teki kaikki alttarin kalut: kattilat, lapiot, maljat, haarukat ja hiilipannut. Kaikki sen kalut hän teki vaskesta.'),
(1671561,58,2,38,4,'Ja hän teki alttariin verkonkaltaisen ristikkokehyksen vaskesta, alttarin välireunuksen alle, maahan kiinni, niin että se ulottui puolitiehen alttaria.'),
(1671562,58,2,38,5,'Ja hän valoi neljä rengasta vaskiristikon neljään kulmaan, korentojen pitimiksi.'),
(1671563,58,2,38,6,'Ja korennot hän teki akasiapuusta ja päällysti ne vaskella.'),
(1671564,58,2,38,7,'Ja hän pisti alttarin sivuilla oleviin renkaisiin korennot, joilla se oli kannettava. Ja hän teki sen laudoista, ontoksi.'),
(1671565,58,2,38,8,'Ja hän teki vaskialtaan vaskijalustoineen niiden naisten kuvastimista, jotka toimittivat palvelusta ilmestysmajan ovella.'),
(1671566,58,2,38,9,'Sitten hän teki esipihan. Etelän puolella olivat esipihan ympärysverhot kerratuista valkoisista pellavalangoista, sadan kyynärän pituiset;'),
(1671567,58,2,38,10,'niiden pylväitä oli kaksikymmentä ja näiden vaskijalustoja kaksikymmentä, mutta pylväiden koukut ja niiden koristepienat olivat hopeata.'),
(1671568,58,2,38,11,'Samoin olivat ympärysverhot myös pohjoisen puolella sadan kyynärän pituiset; niiden pylväitä oli kaksikymmentä ja näiden vaskijalustoja kaksikymmentä, mutta pylväiden koukut ja niiden koristepienat olivat hopeata.'),
(1671569,58,2,38,12,'Mutta lännen puolella olivat ympärysverhot viidenkymmenen kyynärän pituiset; niiden pylväitä oli kymmenen ja näiden jalustoja kymmenen, ja pylväiden koukut ja niiden koristepienat olivat hopeata.'),
(1671570,58,2,38,13,'Ja etupuolella, itään päin, olivat ympärysverhot viidenkymmenen kyynärän pituiset.'),
(1671571,58,2,38,14,'Ympärysverhot olivat portin toisella sivulla viidentoista kyynärän pituiset, ja niiden pylväitä oli kolme ja näiden jalustoja kolme.'),
(1671572,58,2,38,15,'Samoin olivat ympärysverhot toisellakin sivulla, siis esipihan portin kummallakin puolella, viidentoista kyynärän pituiset; niiden pylväitä oli kolme ja näiden jalustoja kolme.'),
(1671573,58,2,38,16,'Kaikki esipihan ympärysverhot yltympäri olivat kerratuista valkoisista pellavalangoista,'),
(1671574,58,2,38,17,'ja pylväiden jalustat olivat vaskea, mutta pylväiden koukut ja niiden koristepienat olivat hopeata, ja niiden päiden päällystys oli hopeata; kaikki esipihan pylväät olivat ympäröidyt hopeaisilla koristepienoilla.'),
(1671575,58,2,38,18,'Ja esipihan portin uudin oli kirjaellen kudottu punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista, kahdenkymmenen kyynärän pituinen ja niinkuin esipihan ympärysverhotkin viiden kyynärän korkuinen, vaatteen leveyden mukaan;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671576,58,2,38,19,'ja sen pylväitä oli neljä ja näiden vaskijalustoja neljä, mutta niiden koukut olivat hopeata, ja niiden päiden päällystys ja niiden koristepienat olivat hopeata.'),
(1671577,58,2,38,20,'Ja kaikki asumuksen ja ympärillä olevan esipihan vaarnat olivat vaskea.'),
(1671578,58,2,38,21,'Näin paljon lasketaan menneen asumuksen, lain asumuksen, kustannuksiin, joka lasku tehtiin Mooseksen käskyn mukaan leeviläisten toimesta, Iitamarin, pappi Aaronin pojan, johdolla.'),
(1671579,58,2,38,22,'Ja Besalel, Uurin poika, Huurin pojanpoika, Juudan sukukunnasta, oli tehnyt kaikki, mistä Herra oli Moosekselle käskyn antanut,'),
(1671580,58,2,38,23,'ja hänellä oli apulaisena Oholiab, Ahisamakin poika, Daanin sukukunnasta, seppä ja kuvakudosten tekijä; tämä valmisti kirjokankaita punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja valkoisista pellavalangoista.'),
(1671581,58,2,38,24,'Kultaa, joka käytettiin siihen työhön, kaikkeen työhön pyhäkössä, oli heilutusuhrina tuotu kaikkiaan kaksikymmentä yhdeksän talenttia, seitsemänsataa kolmekymmentä sekeliä, pyhäkkösekelin painon mukaan.'),
(1671582,58,2,38,25,'Ja hopeata, joka kansalta katselmusta pidettäessä kerääntyi, oli sata talenttia ja tuhat seitsemänsataa seitsemänkymmentä viisi sekeliä, pyhäkkösekelin painon mukaan,'),
(1671583,58,2,38,26,'puolikas, puoli sekeliä, henkeä kohti, pyhäkkösekelin painon mukaan, jokaiselta katselmuksessa olleelta kaksikymmenvuotiaalta ja sitä vanhemmalta, kaikkiaan kuudeltasadalta kolmelta tuhannelta viideltäsadalta viideltäkymmeneltä.'),
(1671584,58,2,38,27,'Ja ne sata talenttia hopeata käytettiin pyhäkön jalustain ja esiripun jalustain valamiseen: sata talenttia sataan jalustaan, talentti jalustaa kohti.'),
(1671585,58,2,38,28,'Ja niistä tuhannesta seitsemästäsadasta seitsemästäkymmenestä viidestä sekelistä tehtiin koukut pylväisiin ja päällystettiin hopealla niiden päät ja tehtiin niihin koristepienat.'),
(1671586,58,2,38,29,'Ja heilutusuhri-vaskea oli seitsemänkymmentä talenttia, kaksituhatta neljäsataa sekeliä.'),
(1671587,58,2,38,30,'Siitä tehtiin jalustat ilmestysmajan oveen, vaskialttari ja siihen kuuluva vaskinen ristikkokehys ja kaikki alttarin kalut'),
(1671588,58,2,38,31,'sekä jalustat ympärillä olevaan esipihaan ja jalustat esipihan porttiin ja kaikki asumuksen vaarnat ja kaikki vaarnat ympärillä olevaan esipihaan.'),
(1671589,58,2,39,1,'Ja punasinisistä, purppuranpunaisista ja helakanpunaisista langoista tehtiin virkapuvut pyhäkköpalvelusta varten; ja samoin tehtiin muut pyhät vaatteet Aaronille, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1671590,58,2,39,2,'Kasukka tehtiin kullasta sekä punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista.'),
(1671591,58,2,39,3,'Kultalevyt taottiin ohuiksi ja leikattiin säikeiksi, taidokkaasti kudottaviksi punasinisten, purppuranpunaisten ja helakanpunaisten lankojen ja valkoisten pellavalankojen sekaan.'),
(1671592,58,2,39,4,'Siihen tehtiin yhdistettävät olkakappaleet; molemmista päistänsä se kiinnitettiin niihin.'),
(1671593,58,2,39,5,'Ja vyö, joka oli oleva kasukassa sen kiinnittämiseksi, oli tehty samasta kappaleesta kuin se, samalla tavalla kullasta sekä punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1671594,58,2,39,6,'Sitten valmistettiin kultapalmikoimilla kehystetyt onyks-kivet, joihin oli kaiverrettu Israelin poikien nimet, niinkuin kaiverretaan sinettisormuksia.'),
(1671595,58,2,39,7,'Ja ne pantiin kasukan olkakappaleihin, että ne kivet johdattaisivat muistoon israelilaiset, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1671596,58,2,39,8,'Rintakilpi tehtiin taidokkaasti kutomalla, samalla tavalla kuin kasukkakin oli tehty, kullasta sekä punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista.'),
(1671597,58,2,39,9,'Se oli neliskulmainen ja taskun muotoon tehty; rintakilpi tehtiin vaaksan pituinen ja vaaksan levyinen, taskun muotoon.'),
(1671598,58,2,39,10,'Ja sen pintaan kiinnitettiin kiviä yliyltään, neljään riviin: ensimmäiseen riviin karneoli, topaasi ja smaragdi;'),
(1671599,58,2,39,11,'toiseen riviin rubiini, safiiri ja jaspis;'),
(1671600,58,2,39,12,'kolmanteen riviin hyasintti, akaatti ja ametisti;'),
(1671601,58,2,39,13,'ja neljänteen riviin krysoliitti, onyks ja berylli. Kultapalmikoimilla kehystettyinä ne kiinnitettiin paikoilleen.'),
(1671602,58,2,39,14,'Kiviä oli Israelin poikien nimien mukaan kaksitoista, yksi kutakin nimeä kohti; kussakin kivessä oli yksi kahdentoista sukukunnan nimistä, kaiverrettuna samalla tavalla, kuin kaiverretaan sinettisormuksia.'),
(1671603,58,2,39,15,'Ja rintakilpeen tehtiin puhtaasta kullasta käädyt, punotut, niinkuin punonnaista tehdään.'),
(1671604,58,2,39,16,'Vielä tehtiin kaksi kultapalmikoimaa ja kaksi kultarengasta, ja molemmat renkaat kiinnitettiin rintakilven molempiin yläkulmiin.'),
(1671605,58,2,39,17,'Ja molemmat kultapunonnaiset kiinnitettiin kahteen renkaaseen rintakilven yläkulmiin.'),
(1671606,58,2,39,18,'Ja molempien punonnaisten toiset kaksi päätä kiinnitettiin kahteen palmikoimaan, ja nämä kiinnitettiin kasukan olkakappaleihin, sen etupuolelle.'),
(1671607,58,2,39,19,'Vielä tehtiin kaksi kultarengasta, ja ne pantiin rintakilven molempiin alakulmiin, sen sisäpuoliseen, kasukkaa vasten olevaan reunaan.'),
(1671608,58,2,39,20,'Ja vieläkin tehtiin kaksi kultarengasta, ja ne kiinnitettiin kasukan molempiin olkakappaleihin, niiden alareunaan, etupuolelle, sauman kohdalle, kasukan vyön yläpuolelle.'),
(1671609,58,2,39,21,'Sitten rintakilpi solmittiin renkaistaan punasinisellä nauhalla kasukan renkaisiin, niin että se oli kasukan vyön yläpuolella, eikä siis rintakilpi irtautunut kasukasta - kaikki, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1671610,58,2,39,22,'Kasukan viitta tehtiin kokonaan kutomalla punasinisistä langoista.'),
(1671611,58,2,39,23,'Ja pääntie viitan keskellä oli niinkuin haarniskan aukko, ja pääntie ympäröitiin päärmeellä, ettei se repeäisi.'),
(1671612,58,2,39,24,'Ja viitan helmaan tehtiin granaattiomenia punasinisistä, purppuranpunaisista ja helakanpunaisista kerratuista langoista.'),
(1671613,58,2,39,25,'Sitten tehtiin tiukuja puhtaasta kullasta, ja nämä tiuvut kiinnitettiin granaattiomenien väliin viitan helmaan ympärinsä, granaattiomenien väliin:'),
(1671614,58,2,39,26,'vuorotellen tiuku ja granaattiomena viitan helmaan ympärinsä, käytettäviksi virantoimituksessa, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1671615,58,2,39,27,'Sitten tehtiin Aaronille ja hänen pojilleen ihokkaat, kudotut valkoisista pellavalangoista,'),
(1671616,58,2,39,28,'käärelakki valkoisista pellavalangoista, koristepäähineet valkoisista pellavalangoista ja pellavakaatiot kerratuista valkoisista pellavalangoista,'),
(1671617,58,2,39,29,'ja vihdoin vyö kerratuista valkoisista pellavalangoista ja punasinisistä, purppuranpunaisista ja helakanpunaisista langoista, kirjaellen kudottu, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1671618,58,2,39,30,'Vielä tehtiin otsakoriste, pyhä otsalehti, puhtaasta kullasta ja siihen piirrettiin, niinkuin sinettisormusta kaiverretaan, kirjoitus: "Herralle pyhitetty".'),
(1671619,58,2,39,31,'Ja siihen kiinnitettiin punasininen nauha sidottavaksi käärelakin yläreunaan, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1671620,58,2,39,32,'Ja niin valmistui koko työ: asumus, ilmestysmaja. Ja israelilaiset tekivät kaiken, niinkuin Herra oli Moosekselle käskyn antanut; niin he tekivät.'),
(1671621,58,2,39,33,'Ja he toivat Mooseksen eteen asumuksen, majan kaikkine kaluineen, hakasineen, lautoineen, poikkitankoineen, pylväineen ja jalustoineen,'),
(1671622,58,2,39,34,'punaisista oinaannahoista tehdyn peitteen ja sireeninnahoista tehdyn peitteen ja verhona olevan esiripun,'),
(1671623,58,2,39,35,'lain arkin korentoineen, armoistuimen,'),
(1671624,58,2,39,36,'pöydän kaikkine kaluineen ja näkyleivät,'),
(1671625,58,2,39,37,'aitokultaisen seitsenhaaraisen lampun riviin pantavine lamppuineen ja kaikkine kaluineen sekä öljyä seitsenhaaraista lamppua varten,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671626,58,2,39,38,'kultaisen alttarin, voiteluöljyn ja hyvänhajuisen suitsukkeen, majan oven uutimen,'),
(1671627,58,2,39,39,'vaskialttarin vaskisine ristikkokehyksineen, sen korennot ja kaikki kalut, altaan jalustoineen,'),
(1671628,58,2,39,40,'esipihan ympärysverhot pylväineen ja jalustoineen, esipihan portin uutimen sekä sen köydet ja vaarnat, ja kaikki kalut, joita tarvitaan asumuksen, ilmestysmajan, tehtävissä,'),
(1671629,58,2,39,41,'virkapuvut pyhäkköpalvelusta varten ja pappi Aaronin muut pyhät vaatteet sekä hänen poikiensa pappispuvut.'),
(1671630,58,2,39,42,'Aivan niinkuin Herra oli Moosekselle käskyn antanut, niin olivat israelilaiset tehneet kaiken sen työn.'),
(1671631,58,2,39,43,'Ja Mooses katseli kaikkea työtä, ja katso, he olivat tehneet sen niin, kuin Herra oli käskenyt; niin he olivat tehneet. Silloin Mooses siunasi heidät.'),
(1671632,58,2,40,1,'Ja Herra puhui Moosekselle sanoen:'),
(1671633,58,2,40,2,'"Ensimmäisen kuukauden ensimmäisenä päivänä pystytä asumus, ilmestysmaja.'),
(1671634,58,2,40,3,'Ja aseta sinne lain arkki ja ripusta esirippu arkin eteen.'),
(1671635,58,2,40,4,'Ja tuo sinne pöytä ja lado sille näkyleivät päälletysten; ja tuo sinne seitsenhaarainen lamppu ja nosta sen lamput paikoilleen.'),
(1671636,58,2,40,5,'Ja sijoita kultainen suitsutusalttari lain arkin eteen ja ripusta uudin majan oveen.'),
(1671637,58,2,40,6,'Ja polttouhrialttari sijoita asumuksen, ilmestysmajan, oven eteen.'),
(1671638,58,2,40,7,'Ja allas sijoita ilmestysmajan ja alttarin välille ja kaada siihen vettä.'),
(1671639,58,2,40,8,'Ja tee esipiha yltympäri ja pane uudin esipihan porttiin.'),
(1671640,58,2,40,9,'Ota sitten voiteluöljyä ja voitele asumus ja kaikki, mitä siinä on, ja pyhitä se kalustoineen, että se tulisi pyhäksi.'),
(1671641,58,2,40,10,'Ja voitele polttouhrialttari kaikkine kaluineen ja pyhitä alttari, että alttari tulisi korkeasti-pyhäksi.'),
(1671642,58,2,40,11,'Voitele myös allas jalustoineen ja pyhitä se.'),
(1671643,58,2,40,12,'Tuo sitten Aaron poikineen ilmestysmajan ovelle ja pese heidät vedellä.'),
(1671644,58,2,40,13,'Ja pue Aaron pyhiin vaatteisiin ja voitele hänet ja pyhitä hänet, että hän pappina palvelisi minua.'),
(1671645,58,2,40,14,'Ja tuo myös hänen poikansa ja pue heidän ylleen ihokkaat.'),
(1671646,58,2,40,15,'Ja voitele heidät, niinkuin sinä voitelit heidän isänsäkin, että he pappeina palvelisivat minua. Niin tämä on oleva heille voitelu ikuiseen pappeuteen, sukupolvesta sukupolveen."'),
(1671647,58,2,40,16,'Ja Mooses teki kaiken, niinkuin Herra oli häntä käskenyt; niin hän teki.'),
(1671648,58,2,40,17,'Ja asumus pystytettiin toisen vuoden ensimmäisessä kuussa, kuukauden ensimmäisenä päivänä.'),
(1671649,58,2,40,18,'Silloin Mooses pystytti asumuksen. Hän asetti paikoilleen sen jalustat, kiinnitti sen laudat, sovitti paikoilleen sen poikkitangot ja pystytti sen pylväät.'),
(1671650,58,2,40,19,'Ja hän levitti asumuksen ylle teltan ja asetti ylimmäksi sen päälle telttapeitteen, niinkuin Herra oli Moosesta käskenyt.'),
(1671651,58,2,40,20,'Sitten hän otti lain, pani sen arkkiin ja kiinnitti arkkiin korennot ja asetti armoistuimen arkin päälle.'),
(1671652,58,2,40,21,'Ja hän toi arkin asumukseen ja sijoitti paikoilleen sitä verhoavan esiripun, ripustaen sen lain arkin eteen, niinkuin Herra oli Moosesta käskenyt.'),
(1671653,58,2,40,22,'Ja hän asetti pöydän ilmestysmajaan, asumuksen pohjoissivulle, esiripun ulkopuolelle'),
(1671654,58,2,40,23,'ja latoi sille näkyleivät päälletysten Herran eteen, niinkuin Herra oli Moosesta käskenyt.'),
(1671655,58,2,40,24,'Ja hän asetti seitsenhaaraisen lampun ilmestysmajaan, vastapäätä pöytää, asumuksen eteläsivulle,'),
(1671656,58,2,40,25,'ja nosti lamput paikoilleen Herran eteen, niinkuin Herra oli Moosesta käskenyt.'),
(1671657,58,2,40,26,'Ja hän asetti kultaisen alttarin ilmestysmajaan esiripun eteen'),
(1671658,58,2,40,27,'ja poltti siinä hyvänhajuista suitsuketta, niinkuin Herra oli Moosesta käskenyt.'),
(1671659,58,2,40,28,'Ja hän ripusti uutimen asumuksen oveen.'),
(1671660,58,2,40,29,'Ja polttouhrialttarin hän asetti asumuksen, ilmestysmajan, oven eteen ja uhrasi sen päällä polttouhrin ja ruokauhrin, niinkuin Herra oli Moosesta käskenyt.'),
(1671661,58,2,40,30,'Ja altaan hän asetti ilmestysmajan ja alttarin välille ja kaatoi siihen vettä peseytymistä varten.'),
(1671662,58,2,40,31,'Ja Mooses ja Aaron ja hänen poikansa pesivät siinä kätensä ja jalkansa;'),
(1671663,58,2,40,32,'kun he menivät ilmestysmajaan tahi lähestyivät alttaria, niin he aina peseytyivät, niinkuin Herra oli Moosesta käskenyt.'),
(1671664,58,2,40,33,'Ja asumuksen ja alttarin ympärille hän laittoi esipihan ja ripusti uutimen esipihan porttiin. Ja niin Mooses päätti sen työn.'),
(1671665,58,2,40,34,'Sitten pilvi peitti ilmestysmajan, ja Herran kirkkaus täytti asumuksen;'),
(1671666,58,2,40,35,'eikä Mooses voinut mennä ilmestysmajaan, sillä pilvi oli laskeutunut sen päälle, ja Herran kirkkaus täytti asumuksen.'),
(1671667,58,2,40,36,'Ja joka kerta, kun pilvi kohosi asumuksen päältä, lähtivät israelilaiset liikkeelle; näin oli koko heidän vaelluksensa ajan.'),
(1671668,58,2,40,37,'Mutta milloin pilvi ei kohonnut, he eivät lähteneet liikkeelle, ennenkuin sinä päivänä, jona se taas kohosi.'),
(1671669,58,3,1,1,'Ja Herra kutsui Mooseksen ja puhui hänelle sisältä ilmestysmajasta sanoen:'),
(1671670,58,3,1,2,'"Puhu israelilaisille ja sano heille: Jos joku teistä tahtoo tuoda uhrilahjan Herralle, niin tuokaa uhrilahjanne karjasta, joko raavaista tai lampaista.'),
(1671671,58,3,1,3,'Jos hänen uhrilahjansa on raavaspolttouhri, tuokoon virheettömän urospuolen; ilmestysmajan ovelle hän tuokoon sen, että Herran mielisuosio tulisi hänen osaksensa.'),
(1671672,58,3,1,4,'Ja hän laskekoon kätensä polttouhriteuraan pään päälle; niin se on oleva otollinen ja tuottava hänelle sovituksen.'),
(1671673,58,3,1,5,'Ja hän teurastakoon mullikan Herran kasvojen edessä, ja papit, Aaronin pojat, tuokoot veren ja vihmokoot veren ympärinsä alttarille, joka on ilmestysmajan ovella.'),
(1671674,58,3,1,6,'Ja hän nylkeköön polttouhriteuraan ja leikelköön sen määräkappaleiksi.'),
(1671675,58,3,1,7,'Ja pappi Aaronin pojat tehkööt tulen alttarille ja pankoot halkoja tuleen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671676,58,3,1,8,'Ja papit, Aaronin pojat, asettakoot kappaleet ynnä pään ja rasvan halkojen päälle, jotka ovat tulessa alttarilla.'),
(1671677,58,3,1,9,'Mutta sisälmykset ja jalat hän pesköön vedessä, ja pappi polttakoon kaiken alttarilla; se on polttouhri, suloisesti tuoksuva uhri Herralle.'),
(1671678,58,3,1,10,'Ja jos hänen uhrilahjansa, joka on tarkoitettu polttouhriksi, on otettu pikkukarjasta, lampaista tai vuohista, tuokoon virheettömän urospuolen.'),
(1671679,58,3,1,11,'Ja teurastakoon sen alttarin pohjoissivulla, Herran edessä; ja papit, Aaronin pojat, vihmokoot sen veren alttarille ympärinsä.'),
(1671680,58,3,1,12,'Ja hän leikelköön sen määräkappaleiksi, ja pappi asettakoon ne ynnä pään ja rasvan halkojen päälle, jotka ovat tulessa alttarilla.'),
(1671681,58,3,1,13,'Mutta sisälmykset ja jalat hän pesköön vedessä, ja pappi tuokoon sen kaiken ja polttakoon alttarilla; se on polttouhri, suloisesti tuoksuva uhri Herralle.'),
(1671682,58,3,1,14,'Ja jos hänen uhrilahjansa Herralle on lintupolttouhri, tuokoon uhrilahjanaan metsäkyyhkysiä tai kyyhkysenpoikia.'),
(1671683,58,3,1,15,'Ja pappi tuokoon sen alttarille, vääntäköön siltä niskat poikki ja polttakoon sen alttarilla, ja puserrettakoon sen veri alttarin seinään.'),
(1671684,58,3,1,16,'Ja hän ottakoon sen kuvun rapoineen pois ja heittäköön sen alttarin viereen itäpuolelle, tuhkaläjälle.'),
(1671685,58,3,1,17,'Sitten hän reväisköön sen auki siipien kohdalta, niitä kuitenkaan irroittamatta, ja pappi polttakoon sen alttarilla halkojen päällä, jotka ovat tulessa; se on polttouhri, suloisesti tuoksuva uhri Herralle."'),
(1671686,58,3,2,1,'"Jos joku tahtoo tuoda Herralle lahjaksi ruokauhrin, olkoon hänen uhrilahjanaan lestyjä jauhoja; ja hän vuodattakoon siihen öljyä ja pankoon sen päälle suitsuketta'),
(1671687,58,3,2,2,'ja vieköön sen papeille, Aaronin pojille, ja pappi ottakoon kourallisen niitä jauhoja ja sitä öljyä ynnä kaiken suitsukkeen ja polttakoon tämän alttariuhriosan alttarilla suloisesti tuoksuvana uhrina Herralle.'),
(1671688,58,3,2,3,'Mutta se, mikä jää tähteeksi ruokauhrista, olkoon Aaronin ja hänen poikiensa oma; se on korkeasti-pyhää, Herran uhria.'),
(1671689,58,3,2,4,'Mutta jos tahdot tuoda ruokauhrilahjan uunissa paistetusta, olkoon uhrinasi lestyistä jauhoista valmistetut, öljyyn leivotut happamattomat kakut tai öljyllä voidellut happamattomat ohukaiset.'),
(1671690,58,3,2,5,'Jos taas uhrilahjasi on ruokauhri, joka leivinlevyllä paistetaan, olkoon se valmistettu lestyistä jauhoista, öljyyn leivottu ja happamaton.'),
(1671691,58,3,2,6,'Paloittele se palasiksi ja vuodata öljyä sen päälle; se on ruokauhri.'),
(1671692,58,3,2,7,'Ja jos uhrilahjasi on ruokauhri, joka paistetaan pannussa, valmistettakoon se lestyistä jauhoista ynnä öljystä.'),
(1671693,58,3,2,8,'Ja vie ruokauhri, joka näin on valmistettu, Herralle; se vietäköön papille, ja hän tuokoon sen alttarin ääreen.'),
(1671694,58,3,2,9,'Ja pappi erottakoon ruokauhrista alttariuhriosan ja polttakoon sen alttarilla suloisesti tuoksuvana uhrina Herralle.'),
(1671695,58,3,2,10,'Mutta se, mikä jää tähteeksi ruokauhrista, olkoon Aaronin ja hänen poikiensa oma; se on korkeasti-pyhää, Herran uhria.'),
(1671696,58,3,2,11,'Mitään ruokauhria, jonka te tuotte Herralle, älköön valmistettako happamesta; älkää polttako uhria Herralle mistään happamesta taikinasta tai hunajasta.'),
(1671697,58,3,2,12,'Uutisuhrilahjana saatte tuoda niitä Herralle, mutta älkööt ne tulko alttarille suloiseksi tuoksuksi.'),
(1671698,58,3,2,13,'Ja jokainen ruokauhrilahjasi suolaa suolalla, äläkä anna Jumalasi liitonsuolan puuttua ruokauhristasi; jokaiseen uhrilahjaasi sinun on tuotava suolaa.'),
(1671699,58,3,2,14,'Mutta jos tahdot tuoda uutisesta ruokauhrin Herralle, niin tuo uutisruokauhrinasi tulessa paahdettuja tähkäpäitä tai survottuja jyviä tuleentumattomasta viljasta.'),
(1671700,58,3,2,15,'Ja vuodata siihen öljyä ja pane siihen suitsuketta; se on ruokauhri.'),
(1671701,58,3,2,16,'Ja pappi polttakoon alttariuhriosan survotuista jyvistä ja öljystä ynnä kaiken suitsukkeen uhrina Herralle."'),
(1671702,58,3,3,1,'"Jos hänen uhrilahjansa on yhteysuhri, tuokoon hän, jos hän tuo raavaskarjasta härän tai lehmän, virheettömän eläimen Herran eteen.'),
(1671703,58,3,3,2,'Ja hän laskekoon kätensä uhriteuraansa pään päälle ja teurastakoon sen ilmestysmajan ovella; ja papit, Aaronin pojat, vihmokoot veren alttarille ympärinsä.'),
(1671704,58,3,3,3,'Ja hän tuokoon yhteysuhrista uhrina Herralle sisälmyksiä peittävän rasvan ja kaiken sisälmysten rasvan'),
(1671705,58,3,3,4,'ja molemmat munuaiset ynnä niiden päällä lantiolihaksissa olevan rasvan ja maksanlisäkkeen, joka on irroitettava munuaisten luota.'),
(1671706,58,3,3,5,'Ja Aaronin pojat polttakoot sen alttarilla polttouhrin päällä, joka on halkojen päällä tulessa, suloisesti tuoksuvana uhrina Herralle.'),
(1671707,58,3,3,6,'Mutta jos hän tuo uhrilahjanaan Herralle yhteysuhriksi pikkukarjasta urospuolen tai naaraspuolen, niin tuokoon virheettömän eläimen.'),
(1671708,58,3,3,7,'Jos hän tuo uhrilahjanaan lampaan, niin tuokoon sen Herran eteen'),
(1671709,58,3,3,8,'ja laskekoon kätensä uhriteuraansa pään päälle ja teurastakoon sen ilmestysmajan ovella, ja Aaronin pojat vihmokoot sen veren alttarille ympärinsä.'),
(1671710,58,3,3,9,'Ja hän tuokoon yhteysuhrista uhrina Herralle sen rasvan, koko rasvahännän, joka on irroitettava häntänikamista, sisälmyksiä peittävän rasvan ja kaiken sisälmysten rasvan'),
(1671711,58,3,3,10,'ja molemmat munuaiset ynnä niiden päällä lantiolihaksissa olevan rasvan ja maksanlisäkkeen, joka on irroitettava munuaisten luota.'),
(1671712,58,3,3,11,'Ja pappi polttakoon sen alttarilla uhriruokana Herralle.'),
(1671713,58,3,3,12,'Ja jos hänen uhrilahjansa on vuohi, tuokoon sen Herran eteen'),
(1671714,58,3,3,13,'ja laskekoon kätensä sen pään päälle ja teurastakoon sen ilmestysmajan ovella; ja Aaronin pojat vihmokoot sen veren alttarille ympärinsä.'),
(1671715,58,3,3,14,'Ja hän tuokoon siitä uhrilahjanaan Herralle uhriksi sisälmyksiä peittävän rasvan ja kaiken sisälmysten rasvan'),
(1671716,58,3,3,15,'ja molemmat munuaiset ynnä niiden päällä lantiolihaksissa olevan rasvan ja maksanlisäkkeen, joka on irroitettava munuaisten luota.'),
(1671717,58,3,3,16,'Ja pappi polttakoon ne alttarilla uhriruokana, suloisesti tuoksuvana uhrina; kaikki rasva olkoon Herran oma.'),
(1671718,58,3,3,17,'Tämä olkoon teille ikuinen säädös sukupolvesta sukupolveen, missä asuttekin: mitään rasvaa tai verta älkää syökö."'),
(1671719,58,3,4,1,'Ja Herra puhui Moosekselle sanoen:'),
(1671720,58,3,4,2,'"Puhu israelilaisille ja sano: Jos joku erehdyksestä rikkoo jotakuta Herran käskyä vastaan ja tekee jotakin, mitä ei saa tehdä,'),
(1671721,58,3,4,3,'niin, jos voideltu pappi tekee rikkomuksen ja saattaa kansan vikapääksi, tuokoon rikkomuksensa tähden, jonka hän on tehnyt, virheettömän mullikan Herralle syntiuhriksi.'),
(1671722,58,3,4,4,'Ja vieköön mullikan ilmestysmajan ovelle Herran eteen ja laskekoon kätensä mullikan pään päälle ja teurastakoon mullikan Herran edessä.'),
(1671723,58,3,4,5,'Ja ottakoon se voideltu pappi mullikan verta ja vieköön sen ilmestysmajaan,'),
(1671724,58,3,4,6,'ja pappi kastakoon sormensa vereen ja pirskoittakoon verta seitsemän kertaa Herran edessä, pyhäkön esiripun edessä.'),
(1671725,58,3,4,7,'Ja pappi sivelköön sitä verta alttarin sarviin, jolla poltetaan hyvänhajuista suitsutusta Herran edessä ja joka on ilmestysmajassa; mullikan kaiken muun veren hän vuodattakoon ilmestysmajan oven edessä olevan polttouhrialttarin juurelle.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671726,58,3,4,8,'Ja kaiken syntiuhrimullikan rasvan hän erottakoon siitä pois, sekä sisälmyksiä peittävän rasvan että kaiken sisälmysten rasvan,'),
(1671727,58,3,4,9,'ja molemmat munuaiset ynnä niiden päällä lantiolihaksissa olevan rasvan ja maksanlisäkkeen, joka on irroitettava munuaisten luota,'),
(1671728,58,3,4,10,'samalla tavalla kuin se erotetaan pois yhteysuhrihärästä; ja pappi polttakoon ne polttouhrialttarilla.'),
(1671729,58,3,4,11,'Mutta mullikan nahan ja kaiken lihan ynnä pään ja jalat, sisälmykset ja ravan,'),
(1671730,58,3,4,12,'koko mullikan, hän vieköön leirin ulkopuolelle puhtaaseen paikkaan, johon tuhka heitetään, ja polttakoon sen halkojen päällä tulessa; siinä paikassa, johon tuhka heitetään, se poltettakoon.'),
(1671731,58,3,4,13,'Ja jos koko Israelin seurakunta erehdyksestä tekee rikkomuksen ja seurakunta ei siitä tiedä ja he rikkomalla jotakuta Herran käskyä vastaan ovat tehneet sellaista, mitä ei saa tehdä, ja niin joutuneet vikapäiksi,'),
(1671732,58,3,4,14,'ja jos sitten rikkomus, jonka he ovat tehneet sitä vastaan, tulee tunnetuksi, niin tuokoon seurakunta mullikan syntiuhriksi ja vieköön sen ilmestysmajan eteen.'),
(1671733,58,3,4,15,'Ja seurakunnan vanhimmat laskekoot kätensä mullikan pään päälle Herran edessä, ja mullikka teurastettakoon Herran edessä.'),
(1671734,58,3,4,16,'Ja voideltu pappi vieköön mullikan verta ilmestysmajaan.'),
(1671735,58,3,4,17,'Ja pappi kastakoon sormensa vereen ja pirskoittakoon sitä seitsemän kertaa Herran edessä, esiripun edessä.'),
(1671736,58,3,4,18,'Ja hän sivelköön sitä verta alttarin sarviin, joka on Herran edessä ilmestysmajassa; kaiken muun veren hän vuodattakoon ilmestysmajan oven edessä olevan polttouhrialttarin juurelle.'),
(1671737,58,3,4,19,'Ja hän erottakoon siitä pois kaiken rasvan ja polttakoon sen alttarilla'),
(1671738,58,3,4,20,'ja tehköön tälle mullikalle, niinkuin hän teki syntiuhrimullikalle; samalla tavalla hän sille tehköön. Kun pappi näin on toimittanut heille sovituksen, annetaan heille anteeksi.'),
(1671739,58,3,4,21,'Ja mullikan hän vieköön leirin ulkopuolelle ja polttakoon sen, niinkuin hän poltti edellisen mullikan; se on seurakunnan syntiuhri.'),
(1671740,58,3,4,22,'Jos päämies tekee rikkomuksen ja erehdyksestä rikkomalla jotakuta Herran, Jumalansa, käskyä vastaan tekee sellaista, mitä ei saa tehdä, ja niin joutuu vikapääksi,'),
(1671741,58,3,4,23,'ja hän sitten saa tietää rikkomuksensa, jonka hän on tehnyt, niin tuokoon uhrilahjanaan kauriin, virheettömän urospuolen,'),
(1671742,58,3,4,24,'ja laskekoon kätensä kauriin pään päälle ja teurastakoon sen siinä paikassa, jossa polttouhriteuraat Herran edessä teurastetaan; se on hänen syntiuhrinsa.'),
(1671743,58,3,4,25,'Ja pappi ottakoon syntiuhrin verta sormeensa ja sivelköön sitä polttouhrialttarin sarviin; muun veren hän vuodattakoon polttouhrialttarin juurelle.'),
(1671744,58,3,4,26,'Mutta kaiken sen rasvan hän polttakoon alttarilla, niinkuin yhteysuhrin rasvan. Kun pappi näin on toimittanut hänelle sovituksen hänen rikkomuksestansa, annetaan hänelle anteeksi.'),
(1671745,58,3,4,27,'Jos joku rahvaasta erehdyksestä rikkoo jotakuta Herran käskyä vastaan tekemällä sellaista, mitä ei saa tehdä, ja niin joutuu vikapääksi,'),
(1671746,58,3,4,28,'ja hän sitten saa tietää rikkomuksensa, jonka hän on tehnyt, niin tuokoon rikkomuksensa tähden, jonka hän on tehnyt, uhrilahjanaan vuohen, virheettömän naaraspuolen,'),
(1671747,58,3,4,29,'ja laskekoon kätensä tämän syntiuhriteuraan pään päälle ja teurastakoon sen polttouhripaikalla.'),
(1671748,58,3,4,30,'Ja pappi ottakoon sen verta sormeensa ja sivelköön sitä polttouhrialttarin sarviin; kaiken muun veren hän vuodattakoon alttarin juurelle.'),
(1671749,58,3,4,31,'Ja hän irroittakoon kaiken sen rasvan, niinkuin rasva irroitetaan yhteysuhrista, ja pappi polttakoon sen alttarilla suloisena tuoksuna Herralle. Kun pappi näin on toimittanut hänelle sovituksen, annetaan hänelle anteeksi.'),
(1671750,58,3,4,32,'Mutta jos hän tuo uhrilahjanaan karitsan syntiuhriksi, niin tuokoon virheettömän uuhen'),
(1671751,58,3,4,33,'ja laskekoon kätensä tämän syntiuhriteuraan pään päälle ja teurastakoon sen syntiuhriksi siinä paikassa, jossa polttouhrieläin teurastetaan.'),
(1671752,58,3,4,34,'Ja pappi ottakoon syntiuhrin verta sormeensa ja sivelköön polttouhrialttarin sarviin; kaiken muun veren hän vuodattakoon alttarin juurelle.'),
(1671753,58,3,4,35,'Ja kaiken sen rasvan hän irroittakoon, niinkuin yhteysuhrilampaan rasva irroitetaan, ja pappi polttakoon sen alttarilla Herran uhrin päällä. Kun pappi on toimittanut hänelle sovituksen hänen rikkomuksestansa, jonka hän on tehnyt, annetaan hänelle anteeksi."'),
(1671754,58,3,5,1,'"Jos joku rikkoo siten, että hän, vaikka kuulee vannotuksen ja voisi olla todistajana, joko hän on ollut silminnäkijänä tahi muuten saanut asiasta tietää, ei kuitenkaan ilmoita sitä ja niin joutuu syynalaiseksi;'),
(1671755,58,3,5,2,'tahi jos joku tietämättään koskee johonkin saastaiseen, mihin tahansa, joko saastaisen metsäeläimen raatoon tai saastaisen kotieläimen raatoon tai saastaisen matelijan raatoon, ja on siten tullut saastaiseksi ja vikapääksi;'),
(1671756,58,3,5,3,'tahi jos hän tietämättään koskee ihmisen saastaan, olipa se mitä saastaa tahansa, josta tulee saastaiseksi, mutta sitten huomaa sen ja joutuu vikapääksi;'),
(1671757,58,3,5,4,'tahi jos joku, ajattelemattomasti puhuen huulillansa, tietämättään vannoo tekevänsä jotakin, pahaa tai hyvää - vannoipa mitä hyvänsä, mitä ihminen saattaa ajattelemattomasti vannoa - mutta sitten huomaa sen ja joutuu johonkin sellaiseen vikapääksi,'),
(1671758,58,3,5,5,'niin, jos hän on vikapää johonkin sellaiseen, tunnustakoon sen, mitä on rikkonut,'),
(1671759,58,3,5,6,'ja tuokoon hyvityksenä Herralle rikkomuksesta, jonka hän on tehnyt, naaraspuolen pikkukarjasta, uuhen tai vuohen, syntiuhriksi; ja pappi toimittakoon hänelle sovituksen hänen rikkomuksestansa.'),
(1671760,58,3,5,7,'Mutta jollei hän saa hankituksi sellaista eläintä, niin tuokoon Herralle hyvitykseksi siitä, mitä on rikkonut, kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa, toisen syntiuhriksi ja toisen polttouhriksi,'),
(1671761,58,3,5,8,'ja vieköön ne papille. Tämä uhratkoon ensiksi sen, joka on määrätty syntiuhriksi, vääntäköön siltä niskat poikki, päätä kuitenkaan irroittamatta,'),
(1671762,58,3,5,9,'ja pirskoittakoon syntiuhrin verta alttarin seinään, ja puserrettakoon se veri, joka jää jäljelle, alttarin juurelle; se on syntiuhri.'),
(1671763,58,3,5,10,'Ja toisen hän säädetyllä tavalla valmistakoon polttouhriksi. Kun pappi näin on toimittanut hänelle sovituksen hänen rikkomuksestaan, jonka hän on tehnyt, annetaan hänelle anteeksi.'),
(1671764,58,3,5,11,'Jollei hän saa hankituksi kahta metsäkyyhkystä tai kahta kyyhkysenpoikaa, niin tuokoon uhrilahjanaan sen sovittamiseksi, mitä on rikkonut, kymmenennen osan eefa-mittaa lestyjä jauhoja syntiuhriksi, mutta älköön vuodattako siihen öljyä älköönkä panko sen päälle suitsuketta, sillä se on syntiuhri.'),
(1671765,58,3,5,12,'Ja vieköön sen papille, ja pappi ottakoon siitä kourallisen, alttariuhriosan, ja polttakoon sen alttarilla Herran uhrin päällä; se on syntiuhri.'),
(1671766,58,3,5,13,'Kun pappi näin on toimittanut hänelle sovituksen jostakin sellaisesta hänen tekemästään rikkomuksesta, annetaan hänelle anteeksi. Ja papille tulkoon se, mikä ruokauhristakin."'),
(1671767,58,3,5,14,'Ja Herra puhui Moosekselle sanoen:'),
(1671768,58,3,5,15,'"Jos joku lankeaa uskottomuuteen ja erehdyksestä rikkoo anastamalla sitä, mikä on Herralle pyhitetty, tuokoon hyvityksenä Herralle vikauhriksi virheettömän oinaan pikkukarjasta, niin monen hopeasekelin arvoisen, pyhäkkösekelin painon mukaan, kuin sinä arvioit.'),
(1671769,58,3,5,16,'Ja mitä hän on pyhitetystä anastanut itselleen, sen hän korvatkoon ja pankoon siihen lisäksi vielä viidennen osan sen arvosta ja antakoon sen papille. Kun pappi näin on toimittanut hänelle sovituksen uhraamalla vikauhrioinaan, annetaan hänelle anteeksi.'),
(1671770,58,3,5,17,'Jos joku rikkoo jotakuta Herran käskyä vastaan ja tekee tietämättään sellaista, mitä ei saa tehdä, ja tulee vikapääksi ja joutuu syynalaiseksi,'),
(1671771,58,3,5,18,'niin tuokoon papille vikauhriksi pikkukarjasta sinun arviosi mukaisen, virheettömän oinaan. Kun pappi on toimittanut hänelle sovituksen siitä erehdyksestä, jonka hän on tietämättään tehnyt, annetaan hänelle anteeksi.'),
(1671772,58,3,5,19,'Se on vikauhri; sillä hän on tullut vikapääksi Herran edessä."'),
(1671773,58,3,6,1,'Ja Herra puhui Moosekselle sanoen:'),
(1671774,58,3,6,2,'"Jos joku tekee rikkomuksen ja on uskoton Herraa kohtaan kieltämällä saaneensa lähimmäiseltään, mitä tämä on hänen haltuunsa antanut tai hänen hoitoonsa uskonut, tahi mitä hän itse on väkisin ottanut tai vääryydellä anastanut lähimmäiseltään,'),
(1671775,58,3,6,3,'tahi jos hän on löytänyt kadotetun esineen ja kieltää sen, tahi vannoo väärin missä asiassa tahansa, jossa ihminen helposti rikkoo,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671776,58,3,6,4,'niin hän, jos hän näin on rikkonut ja tullut vikapääksi, antakoon takaisin, mitä hän väkisin on ottanut tai vääryydellä anastanut, tahi mitä hänen haltuunsa oli uskottu, tahi kadotetun esineen, jonka hän oli löytänyt,'),
(1671777,58,3,6,5,'kaiken, jonka tähden hän oli väärin vannonut; ja korvatkoon sen täyteen määräänsä ja pankoon siihen vielä lisäksi viidennen osan sen arvosta. Sille, jonka oma se on, hän antakoon sen sinä päivänä, jona hän vikauhrinsa toimittaa.'),
(1671778,58,3,6,6,'Mutta hyvityksenä Herralle hän tuokoon papille vikauhriksi sinun arviosi mukaisen, virheettömän oinaan pikkukarjasta.'),
(1671779,58,3,6,7,'Kun pappi näin on toimittanut hänelle sovituksen Herran edessä, annetaan hänelle anteeksi kaikki, mitä hän on tehnyt sellaista, josta hän on tullut vikapääksi."'),
(1671780,58,3,6,8,'Ja Herra puhui Moosekselle sanoen:'),
(1671781,58,3,6,9,'"Käske Aaronia ja hänen poikiansa ja sano: Tämä on laki polttouhrista. Polttouhri olkoon alttarin liedellä koko yön aamuun asti, ja tulta pidettäköön siten vireillä alttarilla.'),
(1671782,58,3,6,10,'Ja pappi pukeutukoon pellavapukuunsa ja pukeutukoon pellavakaatioihin peittääkseen häpynsä, ja korjatkoon pois tuhan, joksi tuli on kuluttanut polttouhrin alttarilla, ja pankoon sen alttarin viereen.'),
(1671783,58,3,6,11,'Ja sitten hän riisukoon vaatteensa ja pukeutukoon toisiin vaatteisiin, ja vieköön tuhan leirin ulkopuolelle puhtaaseen paikkaan.'),
(1671784,58,3,6,12,'Ja tulta pidettäköön siten vireillä alttarilla älköönkä se koskaan sammuko; ja pappi sytyttäköön alttarilla halot joka aamu ja asettakoon sen päälle polttouhrin ja polttakoon sen päällä yhteysuhrin rasvat.'),
(1671785,58,3,6,13,'Tuli palakoon aina alttarilla älköönkä koskaan sammuko.'),
(1671786,58,3,6,14,'Ja tämä on laki ruokauhrista: Aaronin pojat tuokoot sen Herran eteen, alttarin ääreen.'),
(1671787,58,3,6,15,'Ja pappi erottakoon ruokauhrista kourallisen lestyjä jauhoja ja öljyä ja kaiken suitsukkeen, joka on ruokauhrin päällä, ja polttakoon alttarilla alttariuhriosan suloiseksi tuoksuksi Herralle.'),
(1671788,58,3,6,16,'Ja mikä siitä jää tähteeksi, sen syököön Aaron poikinensa; happamatonna se syötäköön pyhässä paikassa, ilmestysmajan esipihalla he sen syökööt.'),
(1671789,58,3,6,17,'Älköön sitä leivottako hapatettuna. Heidän osakseen minä olen sen uhreistani antanut; se on korkeasti-pyhää niinkuin syntiuhri ja vikauhrikin.'),
(1671790,58,3,6,18,'Jokainen miehenpuoli Aaronin jälkeläisistä syököön siitä. Tämä olkoon heidän ikuinen osuutensa Herran uhreista sukupolvesta sukupolveen. Jokainen, joka niihin koskee, on pyhäkölle pyhitetty."'),
(1671791,58,3,6,19,'Ja Herra puhui Moosekselle sanoen:'),
(1671792,58,3,6,20,'"Tämä olkoon Aaronin ja hänen poikiensa uhrilahja, joka heidän on tuotava Herralle voitelupäivänänsä: kymmenes osa eefa-mittaa lestyjä jauhoja jokapäiväiseksi ruokauhriksi, puolet aamulla ja puolet illalla.'),
(1671793,58,3,6,21,'Leivinlevyllä se valmistettakoon öljyyn leivottuna; tuo se hyvin sotkettuna ja uhraa se palasiksi paloiteltuna ruokauhrina suloiseksi tuoksuksi Herralle.'),
(1671794,58,3,6,22,'Ja pappi, joka hänen pojistaan on hänen sijaansa voideltu, toimittakoon sen. Se on Herran ikuinen osuus; se poltettakoon kokonaisuhrina.'),
(1671795,58,3,6,23,'Jokainen papin ruokauhri on kokonaisuhri; älköön sitä syötäkö."'),
(1671796,58,3,6,24,'Ja Herra puhui Moosekselle sanoen:'),
(1671797,58,3,6,25,'"Puhu Aaronille ja hänen pojillensa ja sano: Tämä on laki syntiuhrista. Siinä paikassa, missä polttouhri teurastetaan, teurastettakoon myös syntiuhri Herran edessä; ja se on korkeasti-pyhä.'),
(1671798,58,3,6,26,'Pappi, joka syntiuhrin uhraa, syököön sen; pyhässä paikassa se syötäköön, ilmestysmajan esipihalla.'),
(1671799,58,3,6,27,'Jokainen, joka sen lihaan koskee, on pyhäkölle pyhitetty, ja jos sen verta on pirskunut vaatteille, niin pese pyhässä paikassa se, mihin sitä on pirskunut.'),
(1671800,58,3,6,28,'Ja saviastia, jossa se keitetään, rikottakoon; jos se on keitetty vaskiastiassa, hangattakoon astia puhtaaksi ja huuhdottakoon vedellä.'),
(1671801,58,3,6,29,'Jokainen miehenpuoli papeista saakoon sitä syödä; se on korkeasti-pyhää.'),
(1671802,58,3,6,30,'Mutta mitään syntiuhria, jonka verta viedään ilmestysmajaan sovituksen toimittamista varten pyhäkössä, älköön syötäkö, vaan se poltettakoon tulessa."'),
(1671803,58,3,7,1,'"Ja tämä on laki vikauhrista. Se on korkeasti-pyhää.'),
(1671804,58,3,7,2,'Siinä paikassa, missä polttouhri teurastetaan, teurastettakoon myös vikauhri, ja sen veri vihmottakoon alttarille ympärinsä.'),
(1671805,58,3,7,3,'Ja kaikki sen rasva uhrattakoon, sekä rasvahäntä että sisälmyksiä peittävä rasva,'),
(1671806,58,3,7,4,'ja molemmat munuaiset ynnä niiden päällä lantiolihaksissa oleva rasva ja maksanlisäke, joka on irroitettava munuaisten luota.'),
(1671807,58,3,7,5,'Ja pappi polttakoon ne alttarilla uhrina Herralle; se on vikauhri.'),
(1671808,58,3,7,6,'Jokainen miehenpuoli papeista saakoon sitä syödä. Se syötäköön pyhässä paikassa; se on korkeasti-pyhää.'),
(1671809,58,3,7,7,'Mitä on säädetty syntiuhrista, koskee vikauhriakin; laki on sama molemmista. Se olkoon sen papin oma, joka sillä sovituksen toimittaa.'),
(1671810,58,3,7,8,'Ja pappi, joka toimittaa jonkun puolesta polttouhrin, saakoon uhraamansa polttouhriteuraan nahan.'),
(1671811,58,3,7,9,'Ja jokainen ruokauhri, joka paistetaan uunissa, ja jokainen pannussa tai leivinlevyllä valmistettu, olkoon sen papin oma, joka uhrin toimittaa.'),
(1671812,58,3,7,10,'Mutta jokainen muu ruokauhri, olipa siihen sekoitettu öljyä tai olipa se kuiva, olkoon kaikkien Aaronin poikien oma, yhden niinkuin toisenkin.'),
(1671813,58,3,7,11,'Ja tämä on laki yhteysuhrista, joka Herralle tuodaan:'),
(1671814,58,3,7,12,'Jos joku tuo sen kiitokseksi, niin tuokoon kiitosuhriteuraan lisäksi öljyyn leivottuja happamattomia kakkuja, öljyllä voideltuja happamattomia ohukaisia ja sekoitettuja lestyjä jauhoja öljyyn leivottuina kakkuina.'),
(1671815,58,3,7,13,'Hapatetusta taikinasta leivottujen kakkujen ohella hän tuokoon tämän uhrilahjansa kiitosuhrina uhratun yhteysuhriteuraan lisäksi.'),
(1671816,58,3,7,14,'Ja hän tuokoon siitä yhden kutakin uhrilahja-lajia anniksi Herralle; se olkoon sen papin oma, joka vihmoo yhteysuhrin veren.'),
(1671817,58,3,7,15,'Ja kiitosuhrina uhratun yhteysuhriteuraan liha syötäköön sinä päivänä, jona se on uhrattu, älköönkä mitään siitä jätettäkö seuraavaan aamuun.'),
(1671818,58,3,7,16,'Mutta jos uhrilahjana tuotu teuras on lupausuhri tai vapaaehtoinen uhri, syötäköön se sinä päivänä, jona se on tuotu; jos kuitenkin jotakin siitä jää tähteeksi, saatakoon se syödä seuraavana päivänä.'),
(1671819,58,3,7,17,'Mutta mitä uhrilihasta on tähteenä kolmantena päivänä, se poltettakoon tulessa.'),
(1671820,58,3,7,18,'Jos yhteysuhriteuraan lihaa syödään kolmantena päivänä, ei se ole otollinen eikä sitä lueta tuojan hyväksi, vaan se on saastaista; jokainen, joka sitä syö, joutuu syynalaiseksi.'),
(1671821,58,3,7,19,'Sitä lihaa, joka on sattunut saastaiseen, mihin tahansa, älköön syötäkö, vaan se poltettakoon tulessa; muuten saakoon jokainen, joka on puhdas, syödä yhteysuhriteuraan lihaa.'),
(1671822,58,3,7,20,'Mutta jokainen, joka saastaisena ollessaan syö yhteysuhriteuraan lihaa, joka on Herran oma, hävitettäköön kansastansa.'),
(1671823,58,3,7,21,'Jos joku koskee johonkin saastaiseen, mihin tahansa, joko ihmisen saastaan tahi saastaiseen karjaeläimeen tai mihin inhottavaan saastaan tahansa, ja syö yhteysuhriteuraan lihaa, joka on Herran oma, hänet hävitettäköön kansastansa."'),
(1671824,58,3,7,22,'Ja Herra puhui Moosekselle sanoen:'),
(1671825,58,3,7,23,'"Puhu israelilaisille ja sano: Älkää syökö mitään härän, lampaan tai vuohen rasvaa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671826,58,3,7,24,'Itsestään kuolleen tai kuoliaaksi raadellun eläimen rasva käytettäköön kaikkinaisiin tarpeisiin; mutta älkää sitä syökö.'),
(1671827,58,3,7,25,'Sillä jokainen, joka syö sen eläimen rasvaa, josta tuodaan Herralle uhri, hävitettäköön kansastansa.'),
(1671828,58,3,7,26,'Älkää myöskään, missä asuttekin, syökö mitään verta, ei lintujen eikä karjaeläinten.'),
(1671829,58,3,7,27,'Jokainen, joka syö verta, minkälaista hyvänsä, hävitettäköön kansastansa."'),
(1671830,58,3,7,28,'Ja Herra puhui Moosekselle sanoen:'),
(1671831,58,3,7,29,'"Puhu israelilaisille ja sano: Joka tuo Herralle yhteysuhrinsa, tuokoon Herralle uhrilahjan tästä yhteysuhristaan.'),
(1671832,58,3,7,30,'Omin käsin hän tuokoon Herran uhrit; tuokoon rasvan ynnä rintalihan, ja toimitettakoon niiden heilutus Herran edessä.'),
(1671833,58,3,7,31,'Ja pappi polttakoon rasvan alttarilla, mutta rintaliha olkoon Aaronin ja hänen poikiensa oma.'),
(1671834,58,3,7,32,'Ja oikea reisi antakaa papille anniksi yhteysuhriteuraistanne.'),
(1671835,58,3,7,33,'Se Aaronin pojista, joka uhraa yhteysuhrin veren ja rasvan, saakoon oikean reiden osaksensa.'),
(1671836,58,3,7,34,'Sillä minä olen ottanut heilutus-rintalihan ja anniksi annetun reiden israelilaisilta heidän yhteysuhriteuraistansa ja antanut ne pappi Aaronille ja hänen pojillensa ikuiseksi osuudeksi israelilaisilta."'),
(1671837,58,3,7,35,'Tämä on Aaronin ja hänen poikiensa osa Herran uhreista, joka heille määrättiin sinä päivänä, jona hän toi heidät pappeina palvelemaan Herraa;'),
(1671838,58,3,7,36,'sen osan Herra käski sinä päivänä, jona hän heidät voiteli, israelilaisten antaa heille ikuiseksi osuudeksi sukupolvesta sukupolveen.'),
(1671839,58,3,7,37,'Tämä on se laki polttouhrista, ruokauhrista, syntiuhrista, vikauhrista, vihkiäisuhrista ja yhteysuhrista,'),
(1671840,58,3,7,38,'jonka lain Herra antoi Moosekselle Siinain vuorella sinä päivänä, jona hän antoi israelilaisille käskyn tuoda uhrilahjansa Herralle Siinain erämaassa.'),
(1671841,58,3,8,1,'Ja Herra puhui Moosekselle sanoen:'),
(1671842,58,3,8,2,'"Ota Aaron ja hänen poikansa ynnä heidän vaatteensa ja voiteluöljy sekä syntiuhrimullikka ja ne kaksi oinasta ja kori, jossa happamattomat leivät ovat,'),
(1671843,58,3,8,3,'ja kokoa kaikki seurakunta ilmestysmajan oven eteen".'),
(1671844,58,3,8,4,'Ja Mooses teki, niinkuin Herra oli häntä käskenyt, ja seurakunta kokoontui ilmestysmajan oven eteen.'),
(1671845,58,3,8,5,'Ja Mooses sanoi seurakunnalle: "Näin on Herra käskenyt tehdä".'),
(1671846,58,3,8,6,'Ja Mooses toi Aaronin ja hänen poikansa esille ja pesi heidät vedellä.'),
(1671847,58,3,8,7,'Sitten hän pani hänen yllensä ihokkaan ja vyötti hänet vyöllä ja puki hänet viittaan ja pani kasukan hänen päälleen ja vyötti hänet kasukan vyöllä ja sitoi sen hänen ympärilleen'),
(1671848,58,3,8,8,'ja asetti hänen rintaansa rintakilven ja pani kilpeen uurimin ja tummimin'),
(1671849,58,3,8,9,'ja pani käärelakin hänen päähänsä ja pani käärelakkiin, sen etupuolelle, kultaisen otsakoristeen, pyhän otsalehden, niinkuin Herra oli Moosesta käskenyt.'),
(1671850,58,3,8,10,'Ja Mooses otti voiteluöljyn ja voiteli asumuksen ja kaikki, mitä siinä oli, ja pyhitti ne;'),
(1671851,58,3,8,11,'ja hän pirskoitti sitä seitsemän kertaa alttarille ja voiteli alttarin kaikkine kaluineen ynnä altaan jalustoineen pyhittääkseen ne.'),
(1671852,58,3,8,12,'Ja hän vuodatti voiteluöljyä Aaronin päähän ja voiteli hänet pyhittääkseen hänet.'),
(1671853,58,3,8,13,'Ja Mooses toi esille Aaronin pojat ja puki heidän yllensä ihokkaat ja vyötti heidät vyöllä ja sitoi päähineet heidän päähänsä, niinkuin Herra oli Moosesta käskenyt.'),
(1671854,58,3,8,14,'Ja hän toi esille syntiuhrimullikan, ja Aaron ja hänen poikansa laskivat kätensä syntiuhrimullikan pään päälle.'),
(1671855,58,3,8,15,'Sitten Mooses teurasti sen ja otti sen verta ja siveli sitä sormellansa alttarin sarviin yltympäri ja puhdisti alttarin; ja muun veren hän vuodatti alttarin juurelle ja pyhitti sen toimittamalla sen sovituksen.'),
(1671856,58,3,8,16,'Ja Mooses otti kaiken sisälmysten päällä olevan rasvan ja maksanlisäkkeen ja molemmat munuaiset rasvoineen ja poltti ne alttarilla.'),
(1671857,58,3,8,17,'Mutta mullikan nahkoinensa, lihoinensa ja rapoinensa hän poltti tulessa leirin ulkopuolella, niinkuin Herra oli Moosesta käskenyt.'),
(1671858,58,3,8,18,'Ja hän toi esille polttouhrioinaan, ja Aaron ja hänen poikansa laskivat kätensä oinaan pään päälle.'),
(1671859,58,3,8,19,'Ja Mooses teurasti sen ja vihmoi veren alttarille ympärinsä'),
(1671860,58,3,8,20,'ja leikkeli oinaan määräkappaleiksi; sitten Mooses poltti pään ynnä kappaleet ja rasvan.'),
(1671861,58,3,8,21,'Mutta sisälmykset ja jalat hän pesi vedessä; ja niin Mooses poltti koko oinaan alttarilla. Se oli polttouhri suloiseksi tuoksuksi, uhri Herralle, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1671862,58,3,8,22,'Ja hän toi esille toisen oinaan, vihkiäisoinaan, ja Aaron ja hänen poikansa laskivat kätensä oinaan pään päälle.'),
(1671863,58,3,8,23,'Ja Mooses teurasti sen ja otti sen verta ja siveli sitä Aaronin oikean korvan lehteen ja oikean käden peukaloon ja oikean jalan isoonvarpaaseen.'),
(1671864,58,3,8,24,'Ja Mooses toi Aaronin pojat esille ja siveli verta heidän oikean korvansa lehteen ja oikean kätensä peukaloon ja heidän oikean jalkansa isoonvarpaaseen, mutta vihmoi muun veren alttarille ympärinsä.'),
(1671865,58,3,8,25,'Ja hän otti rasvan ja rasvahännän ja kaiken sisälmysten päällä olevan rasvan ja maksanlisäkkeen ja molemmat munuaiset rasvoineen ja oikean reiden.'),
(1671866,58,3,8,26,'Sitten hän otti happamattomien leipien korista, joka oli Herran edessä, yhden happamattoman kakun ja yhden öljyyn leivotun kakun ja yhden ohukaisen ja pani ne rasvojen ja oikean reiden päälle'),
(1671867,58,3,8,27,'ja pani kaikki nämä Aaronin käsiin ja hänen poikiensa käsiin, ja toimitutti niiden heilutuksen Herran edessä.'),
(1671868,58,3,8,28,'Sitten Mooses otti ne heidän käsistänsä ja poltti ne alttarilla polttouhrin päällä; tämä oli vihkiäisuhri suloiseksi tuoksuksi, uhri Herralle.'),
(1671869,58,3,8,29,'Ja Mooses otti rintalihan ja toimitti sen heilutuksen Herran edessä; vihkiäisoinaasta tuli tämä Mooseksen osaksi, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1671870,58,3,8,30,'Ja Mooses otti voiteluöljyä ja verta, jota oli alttarilla, ja pirskoitti sitä Aaronin ja hänen vaatteidensa päälle ja samoin hänen poikiensa ja heidän vaatteidensa päälle ja pyhitti niin Aaronin ja hänen vaatteensa ynnä hänen poikansa ja heidän vaatteensa.'),
(1671871,58,3,8,31,'Ja Mooses sanoi Aaronille ja hänen pojillensa: "Keittäkää liha ilmestysmajan ovella ja syökää se siinä ynnä leipä, joka on vihkiäisuhriin kuuluvassa korissa, niinkuin minä olen käskenyt ja sanonut: Aaron poikinensa syököön sen.'),
(1671872,58,3,8,32,'Mutta mitä jää tähteeksi lihasta ja leivästä, se polttakaa tulessa.'),
(1671873,58,3,8,33,'Seitsemään päivään älkää lähtekö ilmestysmajan ovelta, älkää ennenkuin teidän vihkimispäivänne ovat kuluneet umpeen, sillä seitsemän päivää kestää teidän vihkimisenne.'),
(1671874,58,3,8,34,'Niinkuin on tehty tänä päivänä, niin on Herra käskenyt vastakin tehdä toimittaakseen teille sovituksen.'),
(1671875,58,3,8,35,'Ja olkaa seitsemän päivää ilmestysmajan ovella, päivät ja yöt, ja toimittakaa Herran palvelustehtävät, ettette kuolisi; sillä niin on minulle käsky annettu."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671876,58,3,8,36,'Ja Aaron ja hänen poikansa tekivät kaiken, mitä Herra oli Mooseksen kautta käskenyt.'),
(1671877,58,3,9,1,'Ja kahdeksantena päivänä Mooses kutsui Aaronin ja hänen poikansa ja Israelin vanhimmat'),
(1671878,58,3,9,2,'ja sanoi Aaronille: "Ota itsellesi härkävasikka syntiuhriksi ja oinas polttouhriksi, molemmat virheettömiä, ja tuo ne Herran eteen.'),
(1671879,58,3,9,3,'Ja puhu israelilaisille ja sano: ''Ottakaa kauris syntiuhriksi ja vasikka ja karitsa, molemmat vuoden vanhoja ja virheettömiä, polttouhriksi'),
(1671880,58,3,9,4,'ja härkä ja oinas yhteysuhriksi, uhrattaviksi Herran edessä, ynnä ruokauhri, johon on öljyä sekoitettu, sillä tänä päivänä ilmestyy teille Herra''."'),
(1671881,58,3,9,5,'Ja he toivat, mitä Mooses oli käskenyt, ilmestysmajan edustalle, ja koko seurakunta astui esiin ja asettui Herran eteen.'),
(1671882,58,3,9,6,'Ja Mooses sanoi: "Näin Herra on käskenyt teidän tehdä, että Herran kirkkaus ilmestyisi teille".'),
(1671883,58,3,9,7,'Ja Mooses sanoi Aaronille: "Astu alttarin ääreen ja uhraa syntiuhrisi ja polttouhrisi ja toimita itsellesi ja kansalle sovitus ja uhraa sitten kansan uhrilahja ja toimita heille sovitus, niinkuin Herra on käskenyt".'),
(1671884,58,3,9,8,'Niin Aaron astui alttarin ääreen ja teurasti oman syntiuhrivasikkansa.'),
(1671885,58,3,9,9,'Ja Aaronin pojat toivat hänelle veren, ja hän kastoi sormensa vereen ja siveli sitä alttarin sarviin, mutta muun veren hän vuodatti alttarin juurelle.'),
(1671886,58,3,9,10,'Mutta syntiuhriteuraan rasvan ja munuaiset ja maksanlisäkkeen hän poltti alttarilla, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1671887,58,3,9,11,'Ja lihan ja nahan hän poltti tulessa leirin ulkopuolella.'),
(1671888,58,3,9,12,'Sitten hän teurasti polttouhrin, ja Aaronin pojat ojensivat hänelle veren, ja hän vihmoi sen alttarille ympärinsä.'),
(1671889,58,3,9,13,'Ja he ojensivat hänelle polttouhrin kappaleittain ynnä pään, ja hän poltti ne alttarilla.'),
(1671890,58,3,9,14,'Ja hän pesi sisälmykset ja jalat ja poltti ne polttouhrin päällä alttarilla.'),
(1671891,58,3,9,15,'Sitten hän toi kansan uhrilahjan ja otti kansan syntiuhrikauriin, teurasti sen ja uhrasi sen syntiuhrina samalla tavalla kuin edellisen.'),
(1671892,58,3,9,16,'Ja hän toi myös polttouhrin ja uhrasi sen säädetyllä tavalla.'),
(1671893,58,3,9,17,'Ja hän toi ruokauhrin ja otti siitä kouransa täyden ja poltti sen alttarilla aamu-polttouhrin lisäksi.'),
(1671894,58,3,9,18,'Sitten hän teurasti härän ja oinaan kansan yhteysuhriksi, ja Aaronin pojat ojensivat hänelle veren, ja hän vihmoi sen alttarille ympärinsä.'),
(1671895,58,3,9,19,'Mutta härän ja oinaan rasvat, rasvahännän, rasvakalvon, munuaiset ja maksanlisäkkeen,'),
(1671896,58,3,9,20,'nämä rasvat he panivat rintalihojen päälle, ja hän poltti rasvat alttarilla.'),
(1671897,58,3,9,21,'Mutta rintalihain ja oikean reiden heilutuksen Aaron toimitti Herran edessä, niinkuin Mooses oli käskenyt.'),
(1671898,58,3,9,22,'Ja Aaron kohotti kätensä kansaa kohti ja siunasi heidät, ja kun hän oli toimittanut syntiuhrin, polttouhrin ja yhteysuhrin, astui hän alas.'),
(1671899,58,3,9,23,'Ja Mooses ja Aaron menivät ilmestysmajaan, ja kun he tulivat sieltä ulos, siunasivat he kansan. Silloin Herran kirkkaus ilmestyi kaikelle kansalle.'),
(1671900,58,3,9,24,'Ja tuli lähti Herran tyköä ja kulutti polttouhrin ja rasvat alttarilta. Ja kaikki kansa näki sen, ja he riemuitsivat ja lankesivat kasvoillensa.'),
(1671901,58,3,10,1,'Ja Aaronin pojat Naadab ja Abihu ottivat kumpikin hiilipannunsa ja virittivät niihin tulen ja panivat suitsuketta sen päälle ja toivat vierasta tulta Herran eteen, vastoin hänen käskyänsä.'),
(1671902,58,3,10,2,'Silloin lähti tuli Herran tyköä ja kulutti heidät, niin että he kuolivat Herran edessä.'),
(1671903,58,3,10,3,'Niin Mooses sanoi Aaronille: "Tämä tapahtuu Herran sanan mukaan: Niissä, jotka ovat minua lähellä, minä osoitan pyhyyteni ja kaiken kansan edessä kirkkauteni". - Mutta Aaron oli ääneti.'),
(1671904,58,3,10,4,'Ja Mooses kutsui Miisaelin ja Elsafanin, Aaronin sedän Ussielin pojat, ja sanoi heille: "Astukaa esiin ja kantakaa sukulaisenne pyhäkön läheisyydestä leirin ulkopuolelle".'),
(1671905,58,3,10,5,'Ja he astuivat esiin ja kantoivat heidät ihokkaineen leirin ulkopuolelle, niinkuin Mooses oli sanonut.'),
(1671906,58,3,10,6,'Sitten Mooses sanoi Aaronille ja hänen pojillensa Eleasarille ja Iitamarille: "Älkää päästäkö tukkaanne hajalle älkääkä repikö vaatteitanne, ettette kuolisi ja ettei hänen vihansa kohtaisi koko seurakuntaa; mutta teidän veljenne, koko Israelin heimo, itkekööt tätä paloa, jonka Herra on sytyttänyt.'),
(1671907,58,3,10,7,'Älkääkä poistuko ilmestysmajan ovelta, ettette kuolisi, sillä Herran voiteluöljy on teissä." Ja he tekivät, niinkuin Mooses oli sanonut.'),
(1671908,58,3,10,8,'Ja Herra puhui Aaronille sanoen:'),
(1671909,58,3,10,9,'"Viiniä ja väkijuomaa älkää juoko, älä sinä älköötkä sinun poikasi sinun kanssasi, kun menette ilmestysmajaan, ettette kuolisi. Tämä olkoon teille ikuinen säädös sukupolvesta sukupolveen,'),
(1671910,58,3,10,10,'tehdäksenne erotuksen pyhän ja epäpyhän, saastaisen ja puhtaan välillä,'),
(1671911,58,3,10,11,'ja opettaaksenne israelilaisille kaikki ne käskyt, jotka Herra on heille Mooseksen kautta puhunut."'),
(1671912,58,3,10,12,'Ja Mooses puhui Aaronille ja hänen eloon jääneille pojillensa Eleasarille ja Iitamarille: "Ottakaa se ruokauhri, joka on jäänyt tähteeksi Herran uhreista, ja syökää se happamattomana alttarin ääressä; sillä se on korkeasti-pyhä.'),
(1671913,58,3,10,13,'Ja syökää se pyhässä paikassa, sillä se on sinun osuutesi ja sinun poikiesi osuus Herran uhreista; niin on minulle käsky annettu.'),
(1671914,58,3,10,14,'Mutta heilutus-rintaliha ja anniksi annettu reisi syökää puhtaassa paikassa, sinä ja sinun poikasi ja tyttäresi sinun kanssasi; sillä ne ovat sinun osuudeksesi ja sinun poikiesi osuudeksi annetut israelilaisten yhteysuhriteuraista.'),
(1671915,58,3,10,15,'Anniksi annettu reisi ja heilutus-rintaliha tuotakoon uhrirasvojen kanssa ja toimitettakoon niiden heilutus Herran edessä; ne olkoot sinun ja sinun poikiesi ikuinen osuus, niinkuin Herra on käskenyt."'),
(1671916,58,3,10,16,'Ja Mooses tiedusteli syntiuhrikaurista, ja katso, se oli poltettu. Silloin hän vihastui Eleasariin ja Iitamariin, Aaronin eloon jääneihin poikiin, ja sanoi:'),
(1671917,58,3,10,17,'"Miksi ette ole syöneet syntiuhria pyhässä paikassa? Sehän on korkeasti-pyhä, ja hän on antanut sen teille, että poistaisitte kansan syntivelan ja toimittaisitte heille sovituksen Herran edessä.'),
(1671918,58,3,10,18,'Katso, ei ole sen verta tuotu pyhäkköön sisälle; teidän olisi tullut syödä se pyhäkössä, niinkuin minä olen käskenyt."'),
(1671919,58,3,10,19,'Mutta Aaron sanoi Moosekselle: "Katso, he ovat tänä päivänä tuoneet syntiuhrinsa ja polttouhrinsa Herran eteen, ja kuitenkin on tämä minua kohdannut; jos minä tänä päivänä söisin syntiuhria, olisikohan se Herralle otollista?"'),
(1671920,58,3,10,20,'Kun Mooses sen kuuli, tyytyi hän siihen.'),
(1671921,58,3,11,1,'Ja Herra puhui Moosekselle ja Aaronille sanoen heille:'),
(1671922,58,3,11,2,'"Puhukaa israelilaisille ja sanokaa: Nämä ovat ne eläimet, joita te saatte syödä kaikista nelijalkaisista eläimistä maan päällä:'),
(1671923,58,3,11,3,'Kaikkia nelijalkaisia eläimiä, joilla on kokonansa halkinaiset sorkat ja jotka märehtivät, te saatte syödä.'),
(1671924,58,3,11,4,'Näitä älkää kuitenkaan syökö niistä, jotka märehtivät, ja niistä, joilla on sorkat: kamelia, joka kyllä märehtii, mutta jolla ei ole sorkkia: se olkoon teille saastainen;'),
(1671925,58,3,11,5,'tamaania, joka kyllä märehtii, mutta jolla ei ole sorkkia: se olkoon teille saastainen;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671926,58,3,11,6,'jänistä, joka kyllä märehtii, mutta jolla ei ole sorkkia: se olkoon teille saastainen;'),
(1671927,58,3,11,7,'sikaa, jolla tosin on kokonansa halkinaiset sorkat, mutta joka ei märehdi: se olkoon teille saastainen.'),
(1671928,58,3,11,8,'Näiden lihaa älkää syökö ja näiden raatoihin älkää koskeko, ne olkoot teille saastaiset.'),
(1671929,58,3,11,9,'Näitä te saatte syödä kaikista vesieläimistä: kaikkia, joilla on evät ja suomukset ja jotka elävät vedessä, niin hyvin merissä kuin joissa, te saatte syödä.'),
(1671930,58,3,11,10,'Mutta kaikista niistä, joita vedet vilisevät, kaikista elollisista, jotka elävät vedessä, inhotkaa kaikkia niitä, joilla ei ole eviä eikä suomuksia, elivätpä merissä tai joissa.'),
(1671931,58,3,11,11,'Niitä inhotkaa; niiden lihaa älkää syökö, ja niiden raadot inhottakoot teitä.'),
(1671932,58,3,11,12,'Kaikkia niitä vesieläimiä, joilla ei ole eviä eikä suomuksia, inhotkaa.'),
(1671933,58,3,11,13,'Linnuista taas inhotkaa näitä; älköön niitä syötäkö, vaan olkoot inhottavia: kotka, partakorppikotka ja harmaa korppikotka,'),
(1671934,58,3,11,14,'haarahaukka ja suohaukkalajit,'),
(1671935,58,3,11,15,'kaikki kaarnelajit,'),
(1671936,58,3,11,16,'kamelikurki, pääskynen, kalalokki ja jalohaukkalajit,'),
(1671937,58,3,11,17,'huuhkaja, kalasääksi ja kissapöllö,'),
(1671938,58,3,11,18,'sarvipöllö, pelikaani ja likakorppikotka,'),
(1671939,58,3,11,19,'haikara ja sirriäislajit, harjalintu ja yölepakko.'),
(1671940,58,3,11,20,'Ja kaikkia siivellisiä pikkueläimiä, jotka liikkuvat neljällä jalalla, inhotkaa.'),
(1671941,58,3,11,21,'Kuitenkin saatte siivellisistä pikkueläimistä, jotka liikkuvat neljällä jalalla, syödä niitä, joilla jalkojen yläpuolella on kaksi säärtä hypelläksensä niillä maassa.'),
(1671942,58,3,11,22,'Niistä te saatte syödä seuraavia: heinäsirkkalajeja, solam-sirkkalajeja, hargol-sirkkalajeja ja haagab-sirkkalajeja.'),
(1671943,58,3,11,23,'Mutta kaikkia muita siivellisiä pikkueläimiä, joilla on neljä jalkaa, inhotkaa.'),
(1671944,58,3,11,24,'Seuraavista eläimistä te tulette saastaisiksi; jokainen, joka niiden raatoihin koskee, olkoon saastainen iltaan asti.'),
(1671945,58,3,11,25,'Ja jokainen, joka niiden raatoja kantaa, pesköön vaatteensa ja olkoon saastainen iltaan asti.'),
(1671946,58,3,11,26,'Kaikki nelijalkaiset eläimet, joilla on sorkat, mutta ei kokonaan halkinaiset, ja jotka eivät märehdi, olkoot teille saastaiset; jokainen, joka niihin koskee, olkoon saastainen.'),
(1671947,58,3,11,27,'Ja kaikki nelijalkaiset eläimet, jotka käyvät käpälillä, olkoot teille saastaiset; jokainen, joka niiden raatoihin koskee, olkoon saastainen iltaan asti.'),
(1671948,58,3,11,28,'Ja joka kantaa niiden raatoja, pesköön vaatteensa ja olkoon saastainen iltaan asti; ne olkoot teille saastaiset.'),
(1671949,58,3,11,29,'Ja nämä olkoot teille saastaiset niistä pikkueläimistä, jotka liikkuvat maassa: myyrä, hiiri ja sisiliskolajit,'),
(1671950,58,3,11,30,'anaka-eläin, kooah-eläin, letaa-eläin, hoomet-eläin ja kameleontti.'),
(1671951,58,3,11,31,'Ne olkoot teille saastaiset kaikista pikkueläimistä; jokainen, joka niihin koskee, sittenkuin ne ovat kuolleet, olkoon saastainen iltaan asti.'),
(1671952,58,3,11,32,'Ja kaikki, minkä päälle joku niistä kuolleena putoaa, on saastaista, olipa se sitten puuastia tai vaatekappale tai nahka tai säkki tai mikä tahansa kalu, jota johonkin tarpeeseen käytetään. Se pantakoon veteen ja olkoon saastainen iltaan asti; sitten se on puhdas.'),
(1671953,58,3,11,33,'Ja jos joku niistä putoaa saviastiaan, on kaikki, mitä siinä on, saastaista, ja astia rikottakoon.'),
(1671954,58,3,11,34,'Kaikki ruoka, jota syödään, on saastaista, jos sen astian vettä tulee siihen; ja kaikki juoma, jota juodaan, on jokaisessa sellaisessa astiassa saastaista.'),
(1671955,58,3,11,35,'Ja kaikki, minkä päälle niiden raato putoaa, tulee saastaiseksi; olkoon se leivinuuni tai liesi, niin se revittäköön maahan; sillä saastaisia ne ovat ja saastaisia ne teille olkoot.'),
(1671956,58,3,11,36,'Kuitenkin lähde tai kaivo, paikka, johon vettä on kokoontunut, pysyy puhtaana. Mutta joka niiden raatoon koskee, olkoon saastainen.'),
(1671957,58,3,11,37,'Ja jos niiden raato putoaa kylvösiemenen päälle, minkä hyvänsä, joka kylvetään, pysyy tämä puhtaana.'),
(1671958,58,3,11,38,'Mutta jos siemen on vedellä kasteltu ja niiden raato putoaa sen päälle, tulee siemen teille saastaiseksi.'),
(1671959,58,3,11,39,'Ja jos joku eläin, joka on teille ravinnoksi, kuolee, olkoon se, joka sen raatoon koskee, saastainen iltaan asti.'),
(1671960,58,3,11,40,'Ja joka syö sen raatoa, pesköön vaatteensa ja olkoon saastainen iltaan asti; ja joka kantaa sen raatoa, pesköön vaatteensa ja olkoon saastainen iltaan asti.'),
(1671961,58,3,11,41,'Kaikki pikkueläimet, jotka liikkuvat maassa, olkoot inhottavia; älköön niitä syötäkö.'),
(1671962,58,3,11,42,'Kaikista niistä, jotka käyvät vatsallansa, ja kaikista pikkueläimistä, jotka liikkuvat maassa, käyden neljällä tai useammalla jalalla, niistä älkää mitään syökö, sillä ne ovat inhottavia.'),
(1671963,58,3,11,43,'Älkää saattako itseänne inhottaviksi koskemalla matelevaan pikkueläimeen, mihin tahansa, älkääkä saastuttako itseänne niillä, niin että tulette niistä saastaisiksi.'),
(1671964,58,3,11,44,'Sillä minä olen Herra, teidän Jumalanne; pyhittäkää siis itsenne ja olkaa pyhät, sillä minä olen pyhä. Niin älkää saastuttako itseänne koskemalla mihinkään pikkueläimeen, joka liikkuu maassa.'),
(1671965,58,3,11,45,'Sillä minä olen Herra, joka olen johdattanut teidät Egyptin maasta, ja joka olen teidän Jumalanne; olkaa siis pyhät, sillä minä olen pyhä.'),
(1671966,58,3,11,46,'Tämä on laki nelijalkaisista eläimistä ja linnuista ja kaikista elollisista, joita vedessä vilisee, ja kaikista olennoista, joita maassa liikkuu,'),
(1671967,58,3,11,47,'että tietäisitte erottaa puhtaat saastaisista ja syötävät eläimet niistä eläimistä, joita ei saa syödä."'),
(1671968,58,3,12,1,'Ja Herra puhui Moosekselle sanoen:'),
(1671969,58,3,12,2,'"Puhu israelilaisille ja sano: Kun vaimo tulee hedelmälliseksi ja synnyttää poikalapsen, olkoon hän saastainen seitsemän päivää; yhtä monta päivää kuin hänen kuukautisensa kestävät, hän olkoon saastainen.'),
(1671970,58,3,12,3,'Ja kahdeksantena päivänä ympärileikattakoon pojan esinahan liha.'),
(1671971,58,3,12,4,'Mutta vaimo pysyköön kotona kolmekymmentä kolme päivää puhdistavan verenvuotonsa aikana; älköön hän koskeko mihinkään, mikä on pyhää, älköönkä tulko pyhäkköön, ennenkuin hänen puhdistuspäivänsä ovat kuluneet umpeen.'),
(1671972,58,3,12,5,'Mutta jos hän synnyttää tyttölapsen, olkoon hän saastainen kaksi viikkoa, samoinkuin kuukautisissaan, ja pysyköön kotona kuusikymmentä kuusi päivää puhdistavan verenvuotonsa aikana.'),
(1671973,58,3,12,6,'Mutta kun hänen puhdistuspäivänsä pojan tai tyttären jälkeen ovat kuluneet umpeen, vieköön hän vuoden vanhan karitsan polttouhriksi ja kyyhkysenpojan tai metsäkyyhkysen syntiuhriksi ilmestysmajan oven eteen papille.'),
(1671974,58,3,12,7,'Ja tämä tuokoon ne Herran eteen ja toimittakoon hänelle sovituksen, niin hän on puhdas verenvuodostansa. Tämä on laki lapsensynnyttäjästä, olipa hän synnyttänyt poika- tai tyttölapsen.'),
(1671975,58,3,12,8,'Mutta jos hän ei saa hankituksi lammasta, ottakoon kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa, toisen polttouhriksi ja toisen syntiuhriksi; ja pappi toimittakoon hänelle sovituksen, niin hän on puhdas."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1671976,58,3,13,1,'Ja Herra puhui Moosekselle ja Aaronille sanoen:'),
(1671977,58,3,13,2,'"Jos jonkun ihoon tulee nystyrä tai ihottuma tai vaalea pilkku, niinkuin pitalitauti olisi tulemassa hänen ihoonsa, vietäköön hänet pappi Aaronin tai jonkun hänen poikansa, pappien, eteen.'),
(1671978,58,3,13,3,'Ja jos pappi tarkastaessaan sairasta paikkaa ihossa huomaa, että karvat sairaassa paikassa ovat muuttuneet valkoisiksi ja että se paikka näyttää muuta ihoa matalammalta, on se pitalitautia; ja niin pian kuin pappi on sen huomannut, julistakoon hän hänet saastaiseksi.'),
(1671979,58,3,13,4,'Ja jos hänen ihossansa on valkea pilkku, mutta se ei näytä muuta ihoa matalammalta eivätkä karvat ole muuttuneet valkoisiksi, sulkekoon pappi sairaan sisälle seitsemäksi päiväksi.'),
(1671980,58,3,13,5,'Ja seitsemäntenä päivänä pappi tarkastakoon häntä, ja jos sairas paikka hänestä näyttää pysyneen entisellään sairauden leviämättä ihossa, sulkekoon pappi hänet sisälle vielä seitsemäksi päiväksi.'),
(1671981,58,3,13,6,'Ja seitsemäntenä päivänä pappi uudestaan tarkastakoon häntä, ja jos hän huomaa että sairas paikka on käynyt vaaleaksi ja että sairaus ei ole ihossa levinnyt, julistakoon pappi hänet puhtaaksi, sillä se on ihottumaa; hän pesköön vaatteensa, ja niin hän on puhdas.'),
(1671982,58,3,13,7,'Mutta jos ihottuma leviää leviämistään hänen ihossansa, sen jälkeen kuin hän oli näyttäytynyt papille tullakseen puhtaaksi julistetuksi, näyttäytyköön uudestaan papille;'),
(1671983,58,3,13,8,'ja jos pappi huomaa ihottuman levinneen ihossa, julistakoon pappi hänet saastaiseksi; se on pitalia.'),
(1671984,58,3,13,9,'Jos pitalitauti ilmestyy ihmiseen, vietäköön hänet papin luo.'),
(1671985,58,3,13,10,'Ja jos pappi tarkastaessaan huomaa ihossa valkoisen nystyrän, jonka kohdalta karvat ovat muuttuneet valkoisiksi, ja liikaa lihaa kasvavan nystyrään,'),
(1671986,58,3,13,11,'on hänen ihossaan jo vanha pitali, ja sentähden pappi julistakoon hänet saastaiseksi älköönkä enää sulkeko häntä sisälle, sillä hän on saastainen.'),
(1671987,58,3,13,12,'Ja jos pitali puhkeaa ihossa, niin että se peittää sairaan koko ihon päästä jalkoihin asti, mihin pappi katsokoonkin,'),
(1671988,58,3,13,13,'ja jos pappi tarkastaessaan huomaa pitalin peittävän koko ihon, niin julistakoon hän sairaan puhtaaksi; hän on kokonansa muuttunut valkoiseksi ja on puhdas.'),
(1671989,58,3,13,14,'Mutta niin pian kuin häneen ilmestyy liikaa lihaa, on hän saastainen.'),
(1671990,58,3,13,15,'Ja kun pappi huomaa liian lihan, julistakoon hän hänet saastaiseksi; liika liha on saastaista, se on pitalia.'),
(1671991,58,3,13,16,'Mutta jos liika liha häviää ja sairas paikka muuttuu valkoiseksi, menköön hän papin luo.'),
(1671992,58,3,13,17,'Ja jos pappi huomaa, että sairas paikka on muuttunut valkoiseksi, julistakoon pappi sairaan puhtaaksi; hän on puhdas.'),
(1671993,58,3,13,18,'Ja jos jonkun ihoon tulee paise, joka paranee jälleen,'),
(1671994,58,3,13,19,'ja paiseen sijalle tulee valkoinen nystyrä tai vaaleanpunainen pilkku, näyttäytyköön hän papille.'),
(1671995,58,3,13,20,'Ja jos pappi tarkastaessaan huomaa, että se paikka näyttää muuta ihoa matalammalta ja että karvat siinä ovat muuttuneet valkoisiksi, julistakoon pappi hänet saastaiseksi; paiseeseen on puhjennut pitalitauti.'),
(1671996,58,3,13,21,'Mutta jos pappi tarkastaessaan huomaa, ettei siinä ole valkoisia karvoja ja ettei se paikka ole muuta ihoa matalampi ja että se on käynyt vaaleaksi, sulkekoon pappi hänet sisälle seitsemäksi päiväksi.'),
(1671997,58,3,13,22,'Ja jos se leviää leviämistään hänen ihossaan, julistakoon pappi hänet saastaiseksi; se on pitalia.'),
(1671998,58,3,13,23,'Mutta jos pilkku pysyy alallansa eikä leviä, on se paiseen arpi, ja pappi julistakoon hänet puhtaaksi.'),
(1671999,58,3,13,24,'Tahi jos joku saa palohaavan ihoonsa ja palohaavaan kasvavaan lihaan ilmestyy vaaleanpunainen tai valkoinen pilkku,'),
(1672000,58,3,13,25,'ja jos pappi tarkastaessaan huomaa karvojen muuttuneen valkoisiksi siinä pilkussa ja sen paikan näyttävän muuta ihoa matalammalta, niin on palohaavaan puhjennut pitali, ja pappi julistakoon hänet saastaiseksi; se on pitalitautia.'),
(1672001,58,3,13,26,'Mutta jos pappi tarkastaessaan huomaa, ettei pilkussa ole valkoisia karvoja ja ettei se ole muuta ihoa matalampi ja että se on käynyt vaaleaksi, niin sulkekoon pappi hänet sisälle seitsemäksi päiväksi.'),
(1672002,58,3,13,27,'Ja seitsemäntenä päivänä pappi tarkastakoon häntä; jos se on yhä levinnyt ihossa, julistakoon pappi hänet saastaiseksi; se on pitalitautia.'),
(1672003,58,3,13,28,'Mutta jos pilkku on pysynyt alallansa eikä ole levinnyt ihossa ja on edelleen vaalennut, on se palohaavasta syntynyt nystyrä, ja pappi julistakoon hänet puhtaaksi; se on palohaavan arpi.'),
(1672004,58,3,13,29,'Jos mieheen tai naiseen tulee sairas paikka päähän tai partaan,'),
(1672005,58,3,13,30,'ja jos pappi tarkastaessaan sairasta paikkaa huomaa, että se näyttää muuta ihoa matalammalta ja että siinä on ohuita, kellertäviä karvoja, niin julistakoon pappi hänet saastaiseksi; se on pitalisyyhelmää, se on pää- eli partapitalia.'),
(1672006,58,3,13,31,'Ja jos pappi tarkastaessaan sairasta paikkaa huomaa, ettei se näytä muuta ihoa matalammalta, mutta ettei siinä ole mustia karvoja, sulkekoon pappi syyhelmää sairastavan sisälle seitsemäksi päiväksi.'),
(1672007,58,3,13,32,'Ja jos pappi seitsemäntenä päivänä tarkastaessaan sairasta paikkaa huomaa, ettei syyhelmä ole levinnyt ja ettei siinä ole kellertäviä karvoja ja ettei syyhelmä näytä muuta ihoa matalammalta,'),
(1672008,58,3,13,33,'niin ajakoon sairas hiuksensa tai partansa, kuitenkaan ajamatta sairasta paikkaa, ja pappi sulkekoon syyhelmää sairastavan sisälle vielä seitsemäksi päiväksi.'),
(1672009,58,3,13,34,'Ja jos pappi seitsemäntenä päivänä tarkastaessaan sairasta paikkaa huomaa, ettei syyhelmä ole levinnyt ihossa ja ettei se näytä muuta ihoa matalammalta, julistakoon pappi hänet puhtaaksi; hän pesköön vaatteensa, ja niin hän on puhdas.'),
(1672010,58,3,13,35,'Mutta jos syyhelmä leviää leviämistään ihossa, sen jälkeen kuin hänet julistettiin puhtaaksi,'),
(1672011,58,3,13,36,'ja jos pappi tarkastaessaan häntä huomaa, että syyhelmä on levinnyt ihossa, älköön pappi enää etsikö kellertäviä karvoja; hän on saastainen.'),
(1672012,58,3,13,37,'Mutta jos syyhelmä hänestä näyttää pysyneen entisellään ja jos siihen on kasvanut mustia karvoja, on syyhelmä parantunut; hän on puhdas, ja pappi julistakoon hänet puhtaaksi.'),
(1672013,58,3,13,38,'Jos miehen tai naisen ihoon tulee pilkkuja, valkoisia pilkkuja,'),
(1672014,58,3,13,39,'ja jos pappi tarkastaessaan huomaa vaalenevia, valkoisia pilkkuja heidän ihossaan, on se vaaratonta valkoista ihottumaa, joka on puhjennut ihoon; hän on puhdas.'),
(1672015,58,3,13,40,'Jos hiukset lähtevät miehen päästä, takaraivosta, on hän takakalju; hän on puhdas.'),
(1672016,58,3,13,41,'Ja jos hiukset lähtevät päästä, ohimoista, on hän otsakalju; hän on puhdas.'),
(1672017,58,3,13,42,'Mutta jos vaaleanpunainen pilkku ilmestyy takaraivon tai otsapuolen paljaaseen paikkaan, on se pitalia, joka on puhkeamassa takaraivon tai otsapuolen paljaaseen paikkaan.'),
(1672018,58,3,13,43,'Ja jos pappi tarkastaessaan häntä huomaa, että nystyrä takaraivon tai otsapuolen paljaassa paikassa on vaaleanpunainen näyttäen samanlaiselta kuin pitali muussa ihossa,'),
(1672019,58,3,13,44,'niin mies on pitalinen ja saastainen; pappi julistakoon hänet heti saastaiseksi hänen päässänsä olevan sairauden tähden.'),
(1672020,58,3,13,45,'Joka sairastaa pitalia, hän käyköön rikkirevityissä vaatteissa, tukka hajallaan ja parta peitettynä ja huutakoon: ''Saastainen, saastainen!'''),
(1672021,58,3,13,46,'Niin kauan kuin sairaus hänessä on, olkoon hän saastainen; saastaisena hän asukoon yksinänsä, hänen asuinsijansa olkoon leirin ulkopuolella.'),
(1672022,58,3,13,47,'Jos pitalitartuntaa tulee vaatekappaleeseen, olipa vaatekappale villainen tai pellavainen,'),
(1672023,58,3,13,48,'tai kudottuun tai solmustettuun kankaaseen, olipa se pellavaista tai villaista, tai nahkaan tai mihin nahasta tehtyyn esineeseen tahansa,'),
(1672024,58,3,13,49,'ja jos tartunnan paikka näyttää vihertävältä tai punertavalta vaatekappaleessa tai nahassa tai kudotussa tai solmustetussa kankaassa tai missä nahasta tehdyssä esineessä tahansa, niin se on pitalia, ja se on näytettävä papille.'),
(1672025,58,3,13,50,'Ja kun pappi on tarkastanut tartunnan paikan, sulkekoon hän tartutetun sisälle seitsemäksi päiväksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672026,58,3,13,51,'Ja jos hän seitsemäntenä päivänä tarkastaessaan tartunnan paikkaa huomaa, että tarttuma on levinnyt vaatekappaleessa tai kudotussa tai solmustetussa kankaassa tai nahassa tai missä nahasta tehdyssä esineessä tahansa, on tarttuma pahanlaatuista pitalia; ne ovat saastaiset.'),
(1672027,58,3,13,52,'Ja hän polttakoon vaatekappaleen tai kudotun tai solmustetun kankaan, olipa se villainen tai pellavainen, tai nahasta tehdyn esineen, olipa se mikä tahansa, jossa tarttuma on, sillä se on pahanlaatuista pitalia; kaikki sellainen poltettakoon tulessa.'),
(1672028,58,3,13,53,'Mutta jos pappi tarkastaessaan huomaa, ettei tarttuma ole levinnyt vaatekappaleessa tai kudotussa tai solmustetussa kankaassa tai nahasta tehdyssä esineessä, olipa se mikä tahansa,'),
(1672029,58,3,13,54,'käskeköön pappi pestä esineen, jossa tarttuma on, ja sulkekoon sen sisälle vielä seitsemäksi päiväksi.'),
(1672030,58,3,13,55,'Ja jos pappi tarkastaessaan tartunnan saanutta esinettä, sen jälkeen kuin se on pesty, huomaa, ettei tarttuma ole muuttunut näöltään, on esine, vaikka tarttuma ei olekaan levinnyt, saastainen, ja se poltettakoon tulessa; se on pitalin syömä, olkoon sitten nurjalta tai oikealta puolelta.'),
(1672031,58,3,13,56,'Mutta jos pappi tarkastaessaan huomaa, että tartunnan paikka on pesemisen jälkeen vaalennut, reväisköön hän sen pois vaatekappaleesta tai nahasta tai kudotusta tai solmustetusta kankaasta.'),
(1672032,58,3,13,57,'Ja jos sitten vielä tarttumaa ilmestyy vaatekappaleeseen tai kudottuun tai solmustettuun kankaaseen tai mihin nahasta tehtyyn esineeseen tahansa, on se puhkeavaa pitalia; se esine, jossa tarttuma on, poltettakoon tulessa.'),
(1672033,58,3,13,58,'Mutta vaatekappale tai kudottu tai solmustettu kangas tai mikä nahasta tehty esine tahansa, josta tarttuma on pesemällä kadonnut, pestäköön vielä kerran, ja niin se on puhdas."'),
(1672034,58,3,13,59,'Tämä on laki pitalitarttumasta vaatekappaleessa, villaisessa tai pellavaisessa, tai kudotussa tai solmustetussa kankaassa tai missä nahasta tehdyssä esineessä tahansa, laki niiden puhtaiksi tai saastaisiksi julistamisesta.'),
(1672035,58,3,14,1,'Ja Herra puhui Moosekselle sanoen:'),
(1672036,58,3,14,2,'"Tämä olkoon laki pitalitautisen puhdistamispäivästä. Hänet tuotakoon papin eteen,'),
(1672037,58,3,14,3,'ja pappi menköön leirin ulkopuolelle; ja jos pappi tarkastaessaan pitalista huomaa, että hän on parantunut pitalitaudista,'),
(1672038,58,3,14,4,'käskeköön pappi puhdistettavaa varten ottaa kaksi elävää, puhdasta lintua, setripuuta, helakanpunaista lankaa ja isoppikorren.'),
(1672039,58,3,14,5,'Ja pappi käskeköön teurastaa toisen linnun saviastian päällä, jossa on raikasta vettä.'),
(1672040,58,3,14,6,'Sitten hän ottakoon sen elävän linnun ynnä setripuun, helakanpunaisen langan ja isoppikorren ja kastakoon ne ynnä elävän linnun sen linnun vereen, joka teurastettiin raikkaan veden päällä,'),
(1672041,58,3,14,7,'ja pirskoittakoon sitä seitsemän kertaa siihen, joka on pitalista puhdistettava; ja puhdistettuaan hänet hän päästäköön sen elävän linnun lentämään kedolle.'),
(1672042,58,3,14,8,'Ja puhdistettava pesköön vaatteensa, ajakoon kaikki hiuksensa ja peseytyköön vedessä, niin hän on puhdas. Sen jälkeen hän saa mennä leiriin; asukoon kuitenkin ulkona teltastansa seitsemän päivää.'),
(1672043,58,3,14,9,'Seitsemäntenä päivänä hän ajakoon kaikki hiukset päästänsä, partansa ja kulmakarvansa: kaikki karvat hän ajakoon; pesköön sitten vaatteensa ja pesköön ruumiinsa vedessä, niin hän on puhdas.'),
(1672044,58,3,14,10,'Ja kahdeksantena päivänä hän ottakoon kaksi virheetöntä karitsaa ja virheettömän, vuoden vanhan uuhikaritsan sekä kolme kymmenennestä lestyjä jauhoja, joihin on sekoitettu öljyä, ruokauhriksi, ja yhden loog-mitan öljyä.'),
(1672045,58,3,14,11,'Ja puhdistusta toimittava pappi asettakoon puhdistettavan henkilön ja nämä esineet Herran eteen ilmestysmajan ovelle.'),
(1672046,58,3,14,12,'Sitten pappi ottakoon toisen karitsan ja tuokoon sen vikauhriksi ynnä loog-mitan öljyä, ja toimittakoon niiden heilutuksen Herran edessä.'),
(1672047,58,3,14,13,'Ja niin hän teurastakoon karitsan siinä paikassa, jossa syntiuhri- ja polttouhriteuraat teurastetaan, pyhässä paikassa; sillä vikauhri on, niinkuin syntiuhrikin, papin oma, se on korkeasti-pyhä.'),
(1672048,58,3,14,14,'Ja pappi ottakoon vikauhrin verta ja sivelköön sitä puhdistettavan oikeaan korvanlehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen.'),
(1672049,58,3,14,15,'Senjälkeen pappi ottakoon öljyä loog-mitasta ja kaatakoon sitä vasempaan käteensä,'),
(1672050,58,3,14,16,'ja pappi kastakoon oikean kätensä etusormen öljyyn, jota on hänen vasemmassa kädessään, ja pirskoittakoon öljyä sormellansa seitsemän kertaa Herran edessä.'),
(1672051,58,3,14,17,'Ja käteensä jäänyttä öljyä pappi sivelköön puhdistettavan oikeaan korvanlehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen vikauhrin veren päälle.'),
(1672052,58,3,14,18,'Ja käteensä vielä jääneen öljyn pappi sivelköön puhdistettavan päähän; näin pappi toimittakoon hänelle sovituksen Herran edessä.'),
(1672053,58,3,14,19,'Sitten pappi uhratkoon syntiuhrin ja toimittakoon puhdistettavalle sovituksen hänen saastaisuudestansa, ja senjälkeen hän teurastakoon polttouhriteuraan.'),
(1672054,58,3,14,20,'Ja pappi uhratkoon polttouhrin ja ruokauhrin alttarilla, ja kun pappi näin on toimittanut hänelle sovituksen, on hän puhdas.'),
(1672055,58,3,14,21,'Mutta jos hän on köyhä eikä saa hankituksi niin paljoa, ottakoon vain yhden karitsan vikauhriksi, heilutettavaksi, toimittaakseen itsellensä sovituksen, sekä vain yhden kymmenenneksen lestyjä jauhoja, joihin on sekoitettu öljyä, ruokauhriksi, ja loog-mitan öljyä,'),
(1672056,58,3,14,22,'sekä kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa, mikäli hän on saanut ne hankituksi; toinen olkoon syntiuhriksi ja toinen polttouhriksi.'),
(1672057,58,3,14,23,'Ja hän vieköön ne papille puhdistustaan varten kahdeksantena päivänä, ilmestysmajan ovelle Herran eteen.'),
(1672058,58,3,14,24,'Ja pappi ottakoon vikauhrikaritsan ja loog-mitan öljyä, ja pappi toimittakoon niiden heilutuksen Herran edessä,'),
(1672059,58,3,14,25,'ja vikauhrikaritsa teurastettakoon, ja pappi ottakoon vikauhrin verta ja sivelköön sitä puhdistettavan oikeaan korvanlehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen.'),
(1672060,58,3,14,26,'Sitten pappi kaatakoon öljyä vasempaan käteensä,'),
(1672061,58,3,14,27,'ja pappi pirskoittakoon oikealla etusormellaan öljyä, jota on hänen vasemmassa kädessään, seitsemän kertaa Herran edessä.'),
(1672062,58,3,14,28,'Ja käteensä jäänyttä öljyä pappi sivelköön puhdistettavan oikeaan korvanlehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen, siihen paikkaan, missä on vikauhrin verta.'),
(1672063,58,3,14,29,'Ja käteensä vielä jääneen öljyn pappi sivelköön puhdistettavan päähän toimittaakseen hänelle sovituksen Herran edessä.'),
(1672064,58,3,14,30,'Ja hän uhratkoon toisen niistä metsäkyyhkysistä tai kyyhkysenpojista, jotka hän on hankkinut,'),
(1672065,58,3,14,31,'mikäli on saanut ne hankituiksi, toisen syntiuhriksi ja toisen polttouhriksi ruokauhrin ohella. Näin pappi toimittakoon puhdistettavalle sovituksen Herran edessä."'),
(1672066,58,3,14,32,'Tämä on laki pitalitautia sairastavasta, joka ei saa hankituksi puhdistukseensa sitä, mikä on säädetty.'),
(1672067,58,3,14,33,'Ja Herra puhui Moosekselle ja Aaronille sanoen:'),
(1672068,58,3,14,34,'"Kun te tulette Kanaanin maahan, jonka minä annan teille perintömaaksi, ja minä sallin pitalin tarttua johonkin taloon siinä maassa, jonka te saatte perintömaaksenne,'),
(1672069,58,3,14,35,'niin talon omistaja menköön ja ilmoittakoon sen papille sanoen: ''Minun talooni näyttää ilmestyneen jotakin pitalitarttuman tapaista''.'),
(1672070,58,3,14,36,'Ja pappi käskeköön tyhjentää talon, ennenkuin menee tarkastamaan tarttumaa, ettei kaikki, mitä talossa on, tulisi saastaiseksi; sitten pappi menköön tarkastamaan taloa.'),
(1672071,58,3,14,37,'Ja jos hän tarkastaessaan tarttumaa näkee tartunnan paikassa talon seinissä vihertäviä tai punertavia syvennyksiä, jotka näyttävät muuta seinää matalammilta,'),
(1672072,58,3,14,38,'menköön pappi talosta ulos talon ovelle ja sulkekoon talon seitsemäksi päiväksi.'),
(1672073,58,3,14,39,'Ja jos pappi palattuaan seitsemäntenä päivänä tarkastaessaan huomaa tarttuman levinneen talon seinissä,'),
(1672074,58,3,14,40,'käskeköön hän murtaa pois ne kivet, joissa tarttuma on, ja heittää ne ulos kaupungista saastaiseen paikkaan.'),
(1672075,58,3,14,41,'Ja talo kaavittakoon sisältä ympärinsä puhtaaksi, ja kaavittu savi heitettäköön ulos kaupungista saastaiseen paikkaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672076,58,3,14,42,'Ja otettakoon toisia kiviä ja pantakoon entisten kivien sijaan, ja otettakoon toista savea ja savettakoon talo sillä.'),
(1672077,58,3,14,43,'Jos tarttuma taas ilmestyy taloon, sen jälkeen kuin kivet ovat murretut pois ja talo on puhtaaksi kaavittu ja uudestaan savettu,'),
(1672078,58,3,14,44,'menköön pappi sisälle, ja jos hän tarkastaessaan huomaa tarttuman levinneen talossa, niin on talossa pahanlaatuinen pitali; se on saastainen.'),
(1672079,58,3,14,45,'Sentähden se talo revittäköön, sekä sen kivet että puuaineet ja kaikki sen savi, ja vietäköön ne ulos kaupungista saastaiseen paikkaan.'),
(1672080,58,3,14,46,'Ja se, joka on käynyt talossa sinä aikana, jona sen oli oltava suljettuna, olkoon saastainen iltaan asti.'),
(1672081,58,3,14,47,'Ja se, joka siinä talossa on maannut, pesköön vaatteensa, ja se, joka siinä talossa on syönyt, pesköön vaatteensa.'),
(1672082,58,3,14,48,'Mutta jos pappi menee sisälle ja tarkastaessaan huomaa, ettei tarttuma ole levinnyt talossa, sen jälkeen kuin talo on savettu, niin julistakoon pappi talon puhtaaksi, sillä tarttuma on hävinnyt.'),
(1672083,58,3,14,49,'Ja hän ottakoon talon puhdistamiseksi kaksi lintua, setripuuta, helakanpunaista lankaa ja isoppikorren.'),
(1672084,58,3,14,50,'Ja teurastakoon toisen linnun saviastian päällä, jossa on raikasta vettä.'),
(1672085,58,3,14,51,'Ja ottakoon setripuun, isoppikorren ja helakanpunaisen langan ja elävän linnun, kastakoon ne teurastetun linnun vereen ja raikkaaseen veteen ja pirskoittakoon sitä taloon seitsemän kertaa.'),
(1672086,58,3,14,52,'Näin hän puhdistakoon talon linnun verellä ja raikkaalla vedellä, elävällä linnulla, setripuulla, isoppikorrella ja helakanpunaisella langalla.'),
(1672087,58,3,14,53,'Ja sitten hän päästäköön elävän linnun lentämään ulkopuolelle kaupunkia kedolle. Kun hän näin on toimittanut talolle sovituksen, on se puhdas."'),
(1672088,58,3,14,54,'Tämä on laki kaikkinaisesta pitalitaudista ja syyhelmästä,'),
(1672089,58,3,14,55,'pitalista vaatteissa ja taloissa,'),
(1672090,58,3,14,56,'nystyröistä, ihottumista ja vaaleista pilkuista,'),
(1672091,58,3,14,57,'neuvoksi siitä, milloin mikin on saastainen, milloin puhdas. Tämä on laki pitalista.'),
(1672092,58,3,15,1,'Ja Herra puhui Moosekselle ja Aaronille sanoen:'),
(1672093,58,3,15,2,'"Puhukaa israelilaisille ja sanokaa heille: Jos jollakin, kenellä tahansa, on elimestään liman vuoto, on hänen vuotonsa saastainen.'),
(1672094,58,3,15,3,'Hänen vuotonsa saastaisuus on sellainen, että hän, niin hyvin silloin, kun hänen elimestään vuotaa, kuin silloin, kun hänen elimensä pidättää vuodon, on saastainen.'),
(1672095,58,3,15,4,'Jokainen vuode, jossa vuotoa sairastava lepää, tulee saastaiseksi, ja jokainen istuin, jolla hän istuu, tulee saastaiseksi.'),
(1672096,58,3,15,5,'Ja se, joka koskee hänen vuoteeseensa, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.'),
(1672097,58,3,15,6,'Ja se, joka istuu istuimelle, jolla vuotoa sairastava on istunut, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.'),
(1672098,58,3,15,7,'Ja se, joka koskee vuotoa sairastavan ruumiiseen, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.'),
(1672099,58,3,15,8,'Ja jos vuotoa sairastava sylkee puhtaan ihmisen päälle, niin tämä pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.'),
(1672100,58,3,15,9,'Ja jokainen satula, jossa vuotoa sairastava ratsastaa, tulee saastaiseksi.'),
(1672101,58,3,15,10,'Ja jokainen, joka koskee mihin hyvänsä, mikä on ollut hänen allaan, olkoon saastainen iltaan asti; ja joka sellaista kantaa, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.'),
(1672102,58,3,15,11,'Ja jokainen, johon vuotoa sairastava koskee, ennenkuin on huuhtonut kätensä vedessä, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.'),
(1672103,58,3,15,12,'Ja saviastia, johon vuotoa sairastava koskee, rikottakoon; mutta jokainen puuastia huuhdottakoon vedessä.'),
(1672104,58,3,15,13,'Ja kun vuotoa sairastava tulee puhtaaksi vuodostansa, niin hän laskekoon puhtaaksi-tulemisestaan seitsemän päivää ja sitten pesköön vaatteensa ja pesköön ruumiinsa raikkaassa vedessä, niin hän on puhdas.'),
(1672105,58,3,15,14,'Ja kahdeksantena päivänä hän ottakoon kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa ja tulkoon Herran eteen ilmestysmajan ovelle ja antakoon ne papille.'),
(1672106,58,3,15,15,'Ja pappi uhratkoon ne, toisen syntiuhriksi ja toisen polttouhriksi. Näin pappi toimittakoon Herran edessä hänelle sovituksen hänen vuodostansa.'),
(1672107,58,3,15,16,'Kun miehellä on ollut siemenvuoto, pesköön hän koko ruumiinsa vedessä ja olkoon saastainen iltaan asti.'),
(1672108,58,3,15,17,'Ja jokainen vaatekappale ja jokainen nahka, johon siemenvuotoa on tullut, pestäköön vedessä ja olkoon saastainen iltaan asti.'),
(1672109,58,3,15,18,'Ja kun mies on maannut naisen kanssa ja vuodattanut siemenensä, peseytykööt he vedessä ja olkoot saastaiset iltaan asti.'),
(1672110,58,3,15,19,'Ja kun naisella on vuoto, niin että verta vuotaa hänen ruumiistansa, olkoon hän kuukautistilassaan seitsemän päivää, ja jokainen, joka häneen koskee, olkoon saastainen iltaan asti.'),
(1672111,58,3,15,20,'Ja kaikki, minkä päällä hän lepää kuukautistilansa aikana, tulee saastaiseksi, ja kaikki, minkä päällä hän istuu, tulee saastaiseksi.'),
(1672112,58,3,15,21,'Ja jokainen, joka hänen vuoteeseensa koskee, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.'),
(1672113,58,3,15,22,'Ja jokainen, joka koskee istuimeen, mihin hyvänsä, jolla hän on istunut, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.'),
(1672114,58,3,15,23,'Ja jos joku koskee esineeseen, joka on hänen vuoteellaan tai istuimella, jolla hän on istunut, olkoon saastainen iltaan asti.'),
(1672115,58,3,15,24,'Ja jos mies makaa hänen kanssaan ja hänen kuukautistansa tulee hänen päällensä, olkoon hän saastainen seitsemän päivää, ja jokainen vuode, jossa hän lepää, tulee saastaiseksi.'),
(1672116,58,3,15,25,'Jos naisen verenvuoto kestää kauan aikaa, vaikka ei ole hänen kuukautisaikansa, tahi jos se jatkuu hänen kuukautisaikansa ohitse, pidettäköön hänet koko vuotonsa ajan saastaisena, niinkuin hänen kuukautisaikanaankin; hän on saastainen.'),
(1672117,58,3,15,26,'Jokaisesta vuoteesta, jossa hän lepää vuotonsa aikana, olkoon voimassa, mitä on säädetty hänen kuukautisaikana käyttämästään vuoteesta; ja jokainen istuin, jolla hän istuu, tulee saastaiseksi niinkuin hänen kuukautisaikanaankin.'),
(1672118,58,3,15,27,'Ja jokainen, joka niihin koskee, tulee saastaiseksi; hän pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.'),
(1672119,58,3,15,28,'Mutta kun hän tulee puhtaaksi vuodostansa, laskekoon seitsemän päivää, ja sitten hän on puhdas.'),
(1672120,58,3,15,29,'Ja kahdeksantena päivänä hän ottakoon kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa ja tuokoon ne papille, ilmestysmajan ovelle.'),
(1672121,58,3,15,30,'Ja pappi uhratkoon toisen syntiuhriksi ja toisen polttouhriksi. Näin pappi toimittakoon Herran edessä hänelle sovituksen hänen saastaisesta vuodostaan.'),
(1672122,58,3,15,31,'Näin teidän on varoitettava israelilaisia saastaisuudesta, etteivät he saastaisuudessansa kuolisi, jos saastuttavat minun asumukseni, joka on heidän keskellänsä."'),
(1672123,58,3,15,32,'Tämä on laki miehestä, joka sairastaa vuotoa, ja miehestä, jolla on siemenvuoto ja joka tulee siitä saastaiseksi,'),
(1672124,58,3,15,33,'ja naisesta, jolla on kuukautisensa, ja miehestä ja naisesta, jotka sairastavat jotakin vuotoa, sekä miehestä, joka makaa saastaisen naisen kanssa.'),
(1672125,58,3,16,1,'Ja Herra puhui Moosekselle, sen jälkeen kuin kaksi Aaronin poikaa oli kuollut, joita kuolema kohtasi, kun he astuivat Herran eteen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672126,58,3,16,2,'Ja Herra sanoi Moosekselle: "Sano veljellesi Aaronille: älköön hän joka aika menkö pyhimpään, esiripun sisäpuolelle, armoistuimen eteen, joka on arkin päällä, ettei hän kuolisi; sillä minä ilmestyn pilvessä armoistuimen kohdalla.'),
(1672127,58,3,16,3,'Mutta näin Aaron menköön pyhimpään: hänellä olkoon mukanaan mullikka syntiuhriksi ja oinas polttouhriksi;'),
(1672128,58,3,16,4,'ja hän pukekoon pyhän pellava-ihokkaan yllensä, peittäköön häpynsä pellavakaatioilla, vyöttäköön itsensä pellavavyöllä ja pankoon pellavaisen käärelakin päähänsä. Nämä ovat pyhät vaatteet; ja hän pesköön ruumiinsa vedessä ja pukekoon ne yllensä.'),
(1672129,58,3,16,5,'Ja hän ottakoon israelilaisten seurakunnalta kaksi kaurista syntiuhriksi ja yhden oinaan polttouhriksi.'),
(1672130,58,3,16,6,'Ja Aaron tuokoon oman syntiuhrimullikkansa ja toimittakoon sovituksen itsellensä ja perheellensä.'),
(1672131,58,3,16,7,'Sitten hän ottakoon ne kaksi kaurista ja asettakoon ne Herran eteen ilmestysmajan ovelle.'),
(1672132,58,3,16,8,'Ja Aaron heittäköön arpaa niistä kahdesta kauriista: toisen arvan Herralle ja toisen Asaselille.'),
(1672133,58,3,16,9,'Ja Aaron tuokoon sen kauriin, jonka arpa määräsi Herralle, ja uhratkoon sen syntiuhriksi.'),
(1672134,58,3,16,10,'Mutta se kauris, jonka arpa määräsi Asaselille, asetettakoon elävänä Herran eteen, että sille toimitettaisiin sovitus ja se sitten päästettäisiin erämaahan Asaselille.'),
(1672135,58,3,16,11,'Senjälkeen Aaron tuokoon oman syntiuhrimullikkansa ja toimittakoon sovituksen itsellensä ja perheellensä ja teurastakoon oman syntiuhrimullikkansa.'),
(1672136,58,3,16,12,'Ja hän ottakoon hiilipannun täyteen tulisia hiiliä alttarilta, joka on Herran edessä, ja kahmalonsa täyteen survottua hyvänhajuista suitsuketta ja vieköön ne esiripun sisäpuolelle.'),
(1672137,58,3,16,13,'Ja hän pankoon suitsukkeen tulen päälle Herran eteen, niin että suitsutus pilvenä peittää lain arkin päällä olevan armoistuimen, ettei hän kuolisi.'),
(1672138,58,3,16,14,'Ja hän ottakoon mullikan verta ja pirskoittakoon sitä sormellansa armoistuimen etupuolelle; ja armoistuimen eteen hän pirskoittakoon sormellansa verta seitsemän kertaa.'),
(1672139,58,3,16,15,'Sitten hän teurastakoon kansan syntiuhrikauriin ja vieköön sen verta esiripun sisäpuolelle ja tehköön sen verellä, niinkuin hän teki mullikan verellä: pirskoittakoon sitä armoistuimelle ja armoistuimen eteen.'),
(1672140,58,3,16,16,'Ja näin hän toimittakoon pyhäkölle sovituksen israelilaisten saastaisuudesta ja heidän rikoksistaan, olivatpa heidän syntinsä minkälaiset tahansa; näin hän tehköön myös ilmestysmajalle, joka on heidän tykönänsä, keskellä heidän saastaisuuttansa.'),
(1672141,58,3,16,17,'Älköön yhtään ihmistä olko ilmestysmajassa, kun hän tulee toimittamaan sovitusta pyhimmässä, siihen saakka kunnes hän sieltä lähtee ja on toimittanut itsellensä ja perheellensä ja koko Israelin seurakunnalle sovituksen.'),
(1672142,58,3,16,18,'Sitten hän lähteköön sieltä alttarin ääreen, joka on Herran edessä, ja toimittakoon sille sovituksen; ja hän ottakoon mullikan verta ja kauriin verta ja sivelköön sitä alttarin sarviin yltympäri.'),
(1672143,58,3,16,19,'Ja hän pirskoittakoon sormellansa sen päälle verta seitsemän kertaa ja puhdistakoon ja pyhittäköön sen israelilaisten saastaisuudesta.'),
(1672144,58,3,16,20,'Ja kun hän on loppuun toimittanut pyhäkön ja ilmestysmajan ja alttarin sovittamisen, tuokoon hän sen elävän kauriin.'),
(1672145,58,3,16,21,'Ja Aaron laskekoon molemmat kätensä elävän kauriin pään päälle ja tunnustakoon siinä kaikki israelilaisten pahat teot ja kaikki heidän rikkomuksensa, olipa heillä mitä syntejä tahansa, ja pankoon ne kauriin pään päälle ja lähettäköön sen, sitä varten varatun miehen viemänä, erämaahan.'),
(1672146,58,3,16,22,'Näin kauris kantakoon kaikki heidän pahat tekonsa autioon seutuun; ja kauris päästettäköön erämaahan.'),
(1672147,58,3,16,23,'Ja Aaron menköön ilmestysmajaan ja riisukoon yltänsä pellavavaatteet, jotka hän oli pukenut päälleen mennessänsä pyhäkköön, ja jättäköön ne sinne.'),
(1672148,58,3,16,24,'Ja hän pesköön pyhässä paikassa ruumiinsa vedessä ja pukekoon ylleen omat vaatteensa; sitten hän lähteköön sieltä ja uhratkoon sekä oman polttouhrinsa että kansan polttouhrin ja toimittakoon niin sekä itsellensä että kansalle sovituksen.'),
(1672149,58,3,16,25,'Ja syntiuhrin rasvan hän polttakoon alttarilla.'),
(1672150,58,3,16,26,'Ja se, joka päästi kauriin Asaselille, pesköön vaatteensa ja pesköön ruumiinsa vedessä, ja sitten hän tulkoon leiriin.'),
(1672151,58,3,16,27,'Ja syntiuhrimullikka ja syntiuhrikauris, joiden veri tuotiin sovitukseksi pyhäkköön, vietäköön leirin ulkopuolelle, ja niiden nahka, liha ja rapa poltettakoon tulessa.'),
(1672152,58,3,16,28,'Ja se, joka ne polttaa, pesköön vaatteensa ja pesköön ruumiinsa vedessä, ja sitten hän tulkoon leiriin.'),
(1672153,58,3,16,29,'Tämä olkoon teille ikuinen säädös: seitsemännessä kuussa, kuukauden kymmenentenä päivänä, kurittakaa itseänne paastolla älkääkä yhtäkään askaretta toimittako, älköön maassa syntynyt älköönkä muukalainen, joka asuu teidän keskellänne.'),
(1672154,58,3,16,30,'Sillä sinä päivänä toimitetaan teille sovitus teidän puhdistamiseksenne; kaikista synneistänne te tulette puhtaiksi Herran edessä.'),
(1672155,58,3,16,31,'Se olkoon teille levon päivä, kurittakaa silloin itseänne paastolla; se olkoon ikuinen säädös.'),
(1672156,58,3,16,32,'Ja sovituksen toimittakoon se pappi, joka on voideltu ja joka on vihitty papinvirkaan isänsä sijaan; hän pukekoon yllensä pellavavaatteet, pyhät vaatteet,'),
(1672157,58,3,16,33,'ja toimittakoon sovituksen kaikkeinpyhimmälle ja sovituksen ilmestysmajalle ja alttarille sekä sovituksen myös papeille ja kaikelle seurakunnan kansalle.'),
(1672158,58,3,16,34,'Tämä olkoon teille ikuinen säädös, että toimitatte israelilaisille sovituksen kaikista heidän synneistänsä kerran vuodessa." Ja hän teki, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1672159,58,3,17,1,'Ja Herra puhui Moosekselle sanoen:'),
(1672160,58,3,17,2,'"Puhu Aaronille ja hänen pojillensa ja kaikille israelilaisille ja sano heille: Näin on Herra käskenyt sanoen:'),
(1672161,58,3,17,3,'Kuka ikinä Israelin heimosta teurastaa härän tai karitsan tai vuohen leirissä tai leirin ulkopuolella'),
(1672162,58,3,17,4,'eikä tuo sitä ilmestysmajan ovelle antaaksensa sen uhrilahjana Herralle Herran asumuksen edessä, hänet pidettäköön vereen vikapäänä; hän on vuodattanut verta, ja se mies hävitettäköön kansastansa.'),
(1672163,58,3,17,5,'Sentähden israelilaiset tuokoot uhriteuraansa, jotka he ovat teurastaneet kedolla, Herran eteen ilmestysmajan ovelle, papille, ja siellä uhratkoot ne yhteysuhriksi Herralle.'),
(1672164,58,3,17,6,'Ja pappi vihmokoon veren Herran alttarille ilmestysmajan oven edessä ja polttakoon rasvan suloiseksi tuoksuksi Herralle.'),
(1672165,58,3,17,7,'Ja älkööt he enää uhratko uhrejansa metsänpeikoille, joiden jäljessä he haureudessa kulkevat. Tämä olkoon heille ikuinen säädös sukupolvesta sukupolveen.'),
(1672166,58,3,17,8,'Ja sano heille: Kuka ikinä Israelin heimosta tai muukalaisista, jotka asuvat teidän keskellänne, uhraa polttouhrin tai teurasuhrin'),
(1672167,58,3,17,9,'eikä tuo sitä ilmestysmajan ovelle, Herralle uhrattavaksi, se mies hävitettäköön kansastansa.'),
(1672168,58,3,17,10,'Kuka ikinä Israelin heimosta tai muukalaisista, jotka asuvat teidän keskellänne, syö verta, mitä tahansa, sitä ihmistä vastaan, joka verta syö, minä käännän kasvoni ja hävitän hänet kansastansa.'),
(1672169,58,3,17,11,'Sillä lihan sielu on veressä, ja minä olen sen teille antanut alttarille, että se tuottaisi teille sovituksen; sillä veri tuottaa sovituksen, koska sielu on siinä.'),
(1672170,58,3,17,12,'Sentähden minä olen sanonut israelilaisille: Älköön kukaan teistä syökö verta; älköön myöskään muukalainen, joka asuu teidän keskellänne, syökö verta.'),
(1672171,58,3,17,13,'Ja kuka ikinä Israelin heimosta tai muukalaisista, jotka asuvat teidän keskellänne, saa pyydystetyksi syötävän metsäeläimen tai linnun, hän vuodattakoon sen veren maahan ja peittäköön multaan.'),
(1672172,58,3,17,14,'Sillä kaiken lihan sielu on sen veri, jossa sen sielu on; sentähden minä sanon israelilaisille: Älkää syökö minkään lihan verta. Sillä kaiken lihan sielu on sen veri; jokainen, joka sitä syö, hävitettäköön.'),
(1672173,58,3,17,15,'Ja jokainen, olipa hän maassa syntynyt tai muukalainen, joka syö itsestään kuollutta tai kuoliaaksi raadeltua eläintä, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti; niin hän tulee puhtaaksi.'),
(1672174,58,3,17,16,'Mutta jos hän ei pese vaatteitansa eikä pese ruumistansa, joutuu hän syynalaiseksi."'),
(1672175,58,3,18,1,'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672176,58,3,18,2,'"Puhu israelilaisille ja sano heille: Minä olen Herra, teidän Jumalanne.'),
(1672177,58,3,18,3,'Älkää tehkö, niinkuin tehdään Egyptin maassa, jossa te asuitte, älkääkä tehkö, niinkuin tehdään Kanaanin maassa, johon minä teidät vien; älkää vaeltako heidän tapojensa mukaan.'),
(1672178,58,3,18,4,'Vaan seuratkaa minun säädöksiäni ja noudattakaa minun käskyjäni vaeltaaksenne niiden mukaan. Minä olen Herra, teidän Jumalanne.'),
(1672179,58,3,18,5,'Noudattakaa minun käskyjäni ja säädöksiäni, sillä se ihminen, joka ne pitää, on niistä elävä. Minä olen Herra.'),
(1672180,58,3,18,6,'Älköön kukaan teistä ryhtykö veriheimolaiseensa paljastaakseen hänen häpyänsä. Minä olen Herra.'),
(1672181,58,3,18,7,'Isäsi häpyä ja äitisi häpyä älä paljasta. Hän on sinun äitisi, älä hänen häpyänsä paljasta.'),
(1672182,58,3,18,8,'Älä paljasta äitipuolesi häpyä, se on sinun isäsi häpy.'),
(1672183,58,3,18,9,'Älä paljasta sisaresi häpyä, olipa hän isäsi tytär tai äitisi tytär, kotona tai ulkona syntynyt; älä paljasta heidän häpyänsä.'),
(1672184,58,3,18,10,'Älä paljasta poikasi tyttären tai tyttäresi tyttären häpyä, sillä se on sinun oma häpysi.'),
(1672185,58,3,18,11,'Älä paljasta äitipuolesi tyttären häpyä, tyttären, joka on sinun isällesi syntynyt; hän on sinun sisaresi.'),
(1672186,58,3,18,12,'Älä paljasta isäsi sisaren häpyä; hän on sinun isäsi veriheimolainen.'),
(1672187,58,3,18,13,'Älä paljasta äitisi sisaren häpyä, sillä hän on sinun äitisi veriheimolainen.'),
(1672188,58,3,18,14,'Älä paljasta setäsi häpyä, älä ryhdy hänen vaimoonsa; hän on sinun tätisi.'),
(1672189,58,3,18,15,'Älä paljasta miniäsi häpyä; hän on sinun poikasi vaimo, älä paljasta hänen häpyänsä.'),
(1672190,58,3,18,16,'Älä paljasta veljesi vaimon häpyä; se on sinun veljesi häpy.'),
(1672191,58,3,18,17,'Älä paljasta vaimon ja hänen tyttärensä häpyä, äläkä ota vaimoksi hänen poikansa tytärtä tai tyttärensä tytärtä paljastaaksesi hänen häpyänsä, sillä he ovat veriheimolaisia; se on sukurutsausta.'),
(1672192,58,3,18,18,'Älä ota vaimosi eläessä hänen sisartansa vaimoksesi ja paljasta hänen häpyänsä, sillä se tuo riidan.'),
(1672193,58,3,18,19,'Älä ryhdy vaimoon paljastaaksesi hänen häpyänsä, kun hän on saastainen kuukautisaikanansa.'),
(1672194,58,3,18,20,'Älä makaa lähimmäisesi vaimon kanssa, ettet siten itseäsi saastuttaisi.'),
(1672195,58,3,18,21,'Älä anna lapsiasi poltettaviksi uhrina Molokille, ettet häpäisisi Jumalasi nimeä. Minä olen Herra.'),
(1672196,58,3,18,22,'Älä makaa miehenpuolen kanssa, niinkuin naisen kanssa maataan; se on kauhistus.'),
(1672197,58,3,18,23,'Älä sekaannu mihinkään eläimeen, ettet siten itseäsi saastuttaisi. Älköönkä nainen tarjoutuko eläimelle pariutuaksensa sen kanssa; se on iljettävyys.'),
(1672198,58,3,18,24,'Älkää saastuttako itseänne millään näistä, sillä näillä kaikilla ovat itsensä saastuttaneet ne kansat, jotka minä karkoitan teidän tieltänne.'),
(1672199,58,3,18,25,'Ja maa tuli saastaiseksi, ja minä kostin sille sen pahat teot, niin että maa oksensi ulos asujamensa.'),
(1672200,58,3,18,26,'Sentähden noudattakaa minun käskyjäni ja säädöksiäni älkääkä mitään näistä kauhistuksista tehkö, älköön maassa syntynyt älköönkä muukalainen, joka asuu teidän keskellänne -'),
(1672201,58,3,18,27,'sillä kaikkia näitä kauhistuksia ovat tehneet tämän maan asukkaat, jotka olivat ennen teitä, niin että maa tuli saastaiseksi -'),
(1672202,58,3,18,28,'ettei maa teitäkin oksentaisi, jos te sen saastutatte, niinkuin se on oksentanut ulos sen kansan, joka oli ennen teitä.'),
(1672203,58,3,18,29,'Sillä jokainen, joka tekee minkä tahansa näistä kauhistuksista, hävitettäköön kansastansa, kaikki, jotka semmoista tekevät.'),
(1672204,58,3,18,30,'Sentähden noudattakaa minun määräyksiäni, ettette seuraisi niitä kauhistavia tapoja, joita on seurattu ennen teitä, ettekä saastuttaisi itseänne niillä. Minä olen Herra, teidän Jumalanne."'),
(1672205,58,3,19,1,'Ja Herra puhui Moosekselle sanoen:'),
(1672206,58,3,19,2,'"Puhu kaikelle israelilaisten seurakunnalle ja sano heille: Olkaa pyhät, sillä minä, Herra, teidän Jumalanne, olen pyhä.'),
(1672207,58,3,19,3,'Jokainen teistä peljätköön äitiänsä ja isäänsä, ja pitäkää minun sapattini. Minä olen Herra, teidän Jumalanne.'),
(1672208,58,3,19,4,'Älkää kääntykö epäjumalien puoleen älkääkä tehkö itsellenne valettuja jumalankuvia. Minä olen Herra, teidän Jumalanne.'),
(1672209,58,3,19,5,'Ja kun te uhraatte yhteysuhria Herralle, uhratkaa se niin, että hänen mielisuosionsa tulee teidän osaksenne.'),
(1672210,58,3,19,6,'Syökää se samana päivänä, jona te uhraatte, tai seuraavana päivänä; mutta mitä tähteeksi jää kolmanteen päivään, se poltettakoon tulessa.'),
(1672211,58,3,19,7,'Jos sitä syödään kolmantena päivänä, niin se on saastaista, ei otollista.'),
(1672212,58,3,19,8,'Ja joka sitä syö, joutuu syynalaiseksi, sillä hän on häväissyt Herran pyhän, ja hänet hävitettäköön kansastansa.'),
(1672213,58,3,19,9,'Kun te korjaatte eloa maastanne, niin älä leikkaa viljaa pelloltasi reunoja myöten äläkä poimi tähkäpäitä leikkuun jälkeen.'),
(1672214,58,3,19,10,'Älä myöskään korjaa tyhjäksi viinitarhaasi äläkä poimi varisseita marjoja, vaan jätä ne köyhälle ja muukalaiselle. Minä olen Herra, teidän Jumalanne.'),
(1672215,58,3,19,11,'Älkää varastako, älkää valhetelko älkääkä lähimmäistänne pettäkö.'),
(1672216,58,3,19,12,'Älkää vannoko väärin minun nimeeni, ettet häpäisisi Jumalasi nimeä. Minä olen Herra.'),
(1672217,58,3,19,13,'Älä tee lähimmäisellesi vääryyttä äläkä ota mitään väkisin. Päivämiehesi palkka älköön olko sinun takanasi huomiseen asti.'),
(1672218,58,3,19,14,'Älä kiroa kuuroa äläkä pane kompastusta sokean eteen, vaan pelkää Jumalaasi. Minä olen Herra.'),
(1672219,58,3,19,15,'Älkää tehkö vääryyttä tuomitessanne; älä ole puolueellinen köyhän hyväksi äläkä pidä ylhäisen puolta, vaan tuomitse lähimmäisesi oikein.'),
(1672220,58,3,19,16,'Älä liiku panettelijana kansasi keskellä äläkä vaani lähimmäisesi verta. Minä olen Herra.'),
(1672221,58,3,19,17,'Älä vihaa veljeäsi sydämessäsi, vaan nuhtele lähimmäistäsi, ettet joutuisi hänen tähtensä syynalaiseksi.'),
(1672222,58,3,19,18,'Älä kosta äläkä pidä vihaa kansasi lapsia vastaan, vaan rakasta lähimmäistäsi niinkuin itseäsi. Minä olen Herra.'),
(1672223,58,3,19,19,'Noudattakaa minun käskyjäni. Älä anna karjassasi kahden erilaisen eläimen pariutua, älä kylvä peltoosi kahdenlaista siementä, älköönkä kahdenlaisista langoista kudottua vaatetta tulko yllesi.'),
(1672224,58,3,19,20,'Jos mies makaa naisen, joka on orjatar ja toisen miehen oma eikä ole lunastettu eikä vapaaksi laskettu, rangaistakoon heitä, ei kuitenkaan kuolemalla, koska nainen ei ollut vapaa.'),
(1672225,58,3,19,21,'Ja mies tuokoon hyvityksenään Herralle vikauhri-oinaan ilmestysmajan ovelle.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672226,58,3,19,22,'Ja kun pappi on toimittanut hänelle vikauhri-oinaalla Herran edessä sovituksen siitä synnistä, jonka hän on tehnyt, annetaan hänelle hänen tekemänsä synti anteeksi.'),
(1672227,58,3,19,23,'Kun te tulette siihen maahan ja istutatte kaikkinaisia hedelmäpuita, niin jättäkää niiden hedelmä, niiden esinahka, koskemattomaksi; kolmena vuotena pitäkää ne ympärileikkaamattomina, älkää niitä syökö.'),
(1672228,58,3,19,24,'Mutta neljäntenä vuotena pyhitettäköön kaikki niiden hedelmät ilojuhlassa Herralle,'),
(1672229,58,3,19,25,'ja vasta viidentenä vuotena syökää niiden hedelmää; näin te lisäätte niiden tuottoa. Minä olen Herra, teidän Jumalanne.'),
(1672230,58,3,19,26,'Älkää syökö mitään verinensä. Älkää merkeistä ennustelko älkääkä harjoittako noituutta.'),
(1672231,58,3,19,27,'Älkää keritkö tukkaanne päälaen ympäriltä, äläkä leikkaamalla turmele partasi reunaa.'),
(1672232,58,3,19,28,'Älkää viileskelkö ihoanne vainajan tähden älkääkä koristelko itseänne ihopiirroksilla. Minä olen Herra.'),
(1672233,58,3,19,29,'Älä häpäise tytärtäsi antamalla hänen tulla portoksi, ettei maa harjoittaisi haureutta ja tulisi täyteen iljettävyyttä.'),
(1672234,58,3,19,30,'Pitäkää minun sapattini ja peljätkää minun pyhäkköäni. Minä olen Herra.'),
(1672235,58,3,19,31,'Älkää kääntykö vainaja- ja tietäjähenkien puoleen; älkää etsikö heitä, ettette tulisi heistä saastutetuiksi. Minä olen Herra, teidän Jumalanne.'),
(1672236,58,3,19,32,'Nouse harmaapään edessä ja kunnioita vanhusta sekä pelkää Jumalaasi. Minä olen Herra.'),
(1672237,58,3,19,33,'Kun muukalainen asuu luonasi teidän maassanne, älkää sortako häntä.'),
(1672238,58,3,19,34,'Muukalainen, joka asuu teidän luonanne, olkoon niinkuin maassa syntynyt teikäläinen. Rakasta häntä niinkuin itseäsi, sillä tekin olitte muukalaisina Egyptin maassa. Minä olen Herra, teidän Jumalanne.'),
(1672239,58,3,19,35,'Älkää tehkö vääryyttä tuomitessanne älkääkä käyttäessänne pituus-, paino- tai astiamittaa.'),
(1672240,58,3,19,36,'Olkoon teillä oikea vaaka, oikeat punnukset, oikea eefa-mitta ja oikea hiin-mitta. Minä olen Herra, teidän Jumalanne, joka vein teidät pois Egyptin maasta.'),
(1672241,58,3,19,37,'Noudattakaa kaikkia minun käskyjäni ja kaikkia minun säädöksiäni ja pitäkää ne. Minä olen Herra."'),
(1672242,58,3,20,1,'Ja Herra puhui Moosekselle sanoen:'),
(1672243,58,3,20,2,'"Sano israelilaisille: Jos joku, kuka tahansa israelilainen tai muukalainen, joka asuu Israelissa, antaa lapsiansa Molokille, hänet rangaistakoon kuolemalla; maan kansa kivittäköön hänet.'),
(1672244,58,3,20,3,'Ja minä käännän kasvoni sitä miestä vastaan ja hävitän hänet hänen kansastansa, koska hän on antanut Molokille lapsiansa saastuttaen minun pyhäkköni ja häväisten minun pyhän nimeni.'),
(1672245,58,3,20,4,'Ja jos maan kansa säästää sitä miestä, joka antaa lapsiansa Molokille, niin etteivät he häntä surmaa,'),
(1672246,58,3,20,5,'niin minä itse käännän kasvoni sitä miestä vastaan ja hänen sukuansa vastaan; hänet ja kaikki, jotka häntä seuraten ovat lähteneet haureudessa kulkemaan Molokin jäljessä, minä hävitän heidän kansastansa.'),
(1672247,58,3,20,6,'Ja jos joku kääntyy vainaja- tai tietäjähenkien puoleen, lähtien haureudessa kulkemaan heidän jäljessänsä, sitä ihmistä vastaan minä käännän kasvoni ja hävitän hänet hänen kansastansa.'),
(1672248,58,3,20,7,'Pyhittäkää siis itsenne ja olkaa pyhät; sillä minä olen Herra, teidän Jumalanne.'),
(1672249,58,3,20,8,'Ja noudattakaa minun käskyjäni ja pitäkää ne. Minä olen Herra, joka pyhitän teidät.'),
(1672250,58,3,20,9,'Kuka ikinä kiroaa isäänsä tai äitiänsä, hänet rangaistakoon kuolemalla; isäänsä ja äitiänsä hän on kironnut, hän on verivelan alainen.'),
(1672251,58,3,20,10,'Jos joku tekee aviorikoksen toisen miehen vaimon kanssa, jos hän tekee aviorikoksen lähimmäisensä vaimon kanssa, niin heidät, sekä avionrikkoja mies että -nainen, rangaistakoon kuolemalla.'),
(1672252,58,3,20,11,'Jos joku makaa äitipuolensa kanssa, paljastaa hän isänsä hävyn; heidät molemmat rangaistakoon kuolemalla, he ovat verivelan alaiset.'),
(1672253,58,3,20,12,'Jos joku makaa miniänsä kanssa, rangaistakoon heidät molemmat kuolemalla; he ovat tehneet iljettävyyden, he ovat verivelan alaiset.'),
(1672254,58,3,20,13,'Jos joku makaa miehenpuolen kanssa, niinkuin naisen kanssa maataan, tekevät he molemmat kauhistuksen; heidät rangaistakoon kuolemalla, he ovat verivelan alaiset.'),
(1672255,58,3,20,14,'Jos joku ottaa vaimoksi naisen ja hänen äitinsä, on se iljettävyys; sekä hänet että ne molemmat poltettakoon tulessa, ettei mitään iljettävyyttä olisi teidän seassanne.'),
(1672256,58,3,20,15,'Jos joku sekaantuu eläimeen, rangaistakoon hänet kuolemalla, ja se eläin tappakaa.'),
(1672257,58,3,20,16,'Ja jos nainen ryhtyy eläimeen, mihin tahansa, pariutuaksensa sen kanssa, niin surmaa sekä nainen että eläin; heidät rangaistakoon kuolemalla, he ovat verivelan alaiset.'),
(1672258,58,3,20,17,'Jos joku ottaa vaimoksi sisarensa, isänsä tyttären tai äitinsä tyttären, ja näkee hänen häpynsä ja tämä näkee hänen häpynsä, niin se on häpeä, ja heidät hävitettäköön kansalaistensa silmien edessä; hän on paljastanut sisarensa hävyn, hän on joutunut syynalaiseksi.'),
(1672259,58,3,20,18,'Jos joku makaa kuukautistilassa olevan naisen kanssa ja paljastaa hänen häpynsä, avaa hänen lähteensä, ja nainen paljastaa verensä lähteen, niin heidät molemmat hävitettäköön kansastansa.'),
(1672260,58,3,20,19,'Älä paljasta äitisi sisaren tai isäsi sisaren häpyä; sillä se, joka niin tekee, on paljastanut veriheimolaisensa; he joutuvat syynalaisiksi.'),
(1672261,58,3,20,20,'Jos joku makaa setänsä vaimon kanssa, on hän paljastanut setänsä hävyn; he joutuvat syynalaisiksi, lapsettomina he kuolkoot.'),
(1672262,58,3,20,21,'Jos joku ottaa vaimoksi veljensä vaimon, on se saastaisuus; hän on paljastanut veljensä hävyn, lapsettomiksi he jääkööt.'),
(1672263,58,3,20,22,'Noudattakaa siis kaikkia minun käskyjäni ja kaikkia minun säädöksiäni ja pitäkää ne, ettei teitä oksentaisi ulos se maa, johon minä vien teidät asumaan.'),
(1672264,58,3,20,23,'Ja älkää vaeltako sen kansan tapojen mukaan, jonka minä karkoitan teidän tieltänne; sillä kaikkia näitä he ovat tehneet ja nostaneet minun inhoni.'),
(1672265,58,3,20,24,'Mutta minä sanon teille: Te saatte ottaa omaksenne heidän maansa, sillä minä annan sen teille omaksi, maan, joka vuotaa maitoa ja mettä. Minä olen Herra, teidän Jumalanne, joka olen teidät erottanut muista kansoista.'),
(1672266,58,3,20,25,'Erottakaa myös puhtaat eläimet saastaisista ja saastaiset linnut puhtaista, ettette saattaisi itseänne inhottaviksi koskemalla nelijalkaisiin eläimiin, lintuihin tai maan matelijoihin, mihin tahansa, jotka minä olen erottanut, että te pitäisitte ne saastaisina.'),
(1672267,58,3,20,26,'Olkaa siis minulle pyhät, sillä minä, Herra, olen pyhä, ja minä olen teidät erottanut muista kansoista olemaan minun omani.'),
(1672268,58,3,20,27,'Jos jossakin miehessä tai naisessa on vainaja- tai tietäjähenki, niin heidät rangaistakoon kuolemalla; heidät kivitettäköön, he ovat verivelan alaiset."'),
(1672269,58,3,21,1,'Ja Herra sanoi Moosekselle: "Puhu papeille, Aaronin pojille, ja sano heille: Pappi älköön saattako itseänsä saastaiseksi kenestäkään kuolleesta sukulaisestansa,'),
(1672270,58,3,21,2,'paitsi lähimmästä veriheimolaisestaan: äidistänsä, isästänsä, pojastansa, tyttärestänsä ja veljestänsä,'),
(1672271,58,3,21,3,'sekä sisarestansa, jos tämä oli neitsyt ja eli hänen luonaan eikä ollut naitu; hänestä hän saa saastua.'),
(1672272,58,3,21,4,'Älköön hän, sukunsa päämies, saattako itseänsä saastaiseksi, ettei hän itseänsä häpäisisi.'),
(1672273,58,3,21,5,'Älkööt he ajako paljaaksi päälakeansa älköötkä leikatko partansa reunaa älköötkä koristelko itseänsä ihopiirroksilla.'),
(1672274,58,3,21,6,'He olkoot Jumalallensa pyhät älköötkä häväiskö Jumalansa nimeä, sillä he uhraavat Herran uhreja, Jumalansa leipää; sentähden he olkoot pyhät.'),
(1672275,58,3,21,7,'Älkööt he ottako vaimoksi porttoa tai häväistyä naista älköötkä ottako miehensä hylkäämää vaimoa, sillä pappi on pyhä Jumalallensa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672276,58,3,21,8,'Sinun on pidettävä häntä pyhänä, koska hän uhraa sinun Jumalasi leipää; hän olkoon sinulle pyhä, sillä minä, Herra, joka pyhitän teidät, olen pyhä.'),
(1672277,58,3,21,9,'Jos papin tytär häpäisee itsensä haureudella, niin hän häpäisee isänsä; hänet poltettakoon tulessa.'),
(1672278,58,3,21,10,'Se pappi, joka on ylimmäinen veljiensä seassa, jonka pään päälle voiteluöljy on vuodatettu ja joka pyhiin vaatteisiin pukemalla on vihitty virkaansa, älköön päästäkö tukkaansa hajalle älköönkä reväiskö vaatteitansa.'),
(1672279,58,3,21,11,'Älköön hän myöskään menkö minkään kuolleen luo; isästänsäkään tai äidistänsä hän älköön saattako itseänsä saastaiseksi.'),
(1672280,58,3,21,12,'Älköön hän lähtekö pyhäköstä, ettei hän häpäisisi Jumalansa pyhäkköä, sillä hänessä on hänen Jumalansa voiteluöljyn vihkimys. Minä olen Herra.'),
(1672281,58,3,21,13,'Hän ottakoon vaimoksensa neitsyen.'),
(1672282,58,3,21,14,'Leskeä tai hyljättyä vaimoa tai häväistyä naista tai porttoa hän älköön ottako, vaan neitsyen omasta suvustaan hän ottakoon vaimoksensa,'),
(1672283,58,3,21,15,'ettei hän häpäisisi jälkeläisiään suvussansa; sillä minä olen Herra, joka hänet pyhitän."'),
(1672284,58,3,21,16,'Ja Herra puhui Moosekselle sanoen:'),
(1672285,58,3,21,17,'"Puhu Aaronille ja sano: jos jossakin sinun jälkeläisistäsi, tulevissa sukupolvissa, on joku vamma, älköön hän lähestykö uhraamaan Jumalansa leipää.'),
(1672286,58,3,21,18,'Älköön lähestykö kukaan, jossa on joku vamma, älköön kukaan sokea tai ontuva, kukaan kasvoiltaan tahi jäseniltään muodoton,'),
(1672287,58,3,21,19,'jalkansa tai kätensä taittanut,'),
(1672288,58,3,21,20,'kyttyräselkäinen tai surkastunut, silmävikainen tai ihotautinen tai rupinen tai kuohittu.'),
(1672289,58,3,21,21,'Pappi Aaronin jälkeläisistä älköön kukaan, jossa on joku vamma, lähestykö uhraamaan Herran uhreja; hänessä on vamma, sentähden hän älköön lähestykö uhraamaan Jumalansa leipää.'),
(1672290,58,3,21,22,'Kuitenkin hän syököön Jumalansa leipää, sekä korkeasti-pyhää että pyhää.'),
(1672291,58,3,21,23,'Mutta älköön hän tulko esiripun luo älköönkä lähestykö alttaria, koska hänessä on vamma, ettei hän häpäisisi minun pyhäkköäni; sillä minä olen Herra, joka pyhitän heidät."'),
(1672292,58,3,21,24,'Ja Mooses sanoi tämän Aaronille ja hänen pojillensa ja kaikille israelilaisille.'),
(1672293,58,3,22,1,'Ja Herra puhui Moosekselle sanoen:'),
(1672294,58,3,22,2,'"Käske Aaronia ja hänen poikiansa pyhästi pitelemään israelilaisten pyhiä lahjoja, heidän minulle pyhittämiänsä, etteivät he häpäisisi minun pyhää nimeäni. Minä olen Herra.'),
(1672295,58,3,22,3,'Sano heille polvesta polveen: Jos kuka tahansa teidän jälkeläisistänne saastuneena ollessaan lähestyy niitä pyhiä lahjoja, joita israelilaiset pyhittävät Herralle, hänet hävitettäköön minun kasvojeni edestä.'),
(1672296,58,3,22,4,'Minä olen Herra. Älköön kukaan Aaronin jälkeläinen, joka on pitalinen tai jolla on vuoto, syökö pyhistä lahjoista, ennenkuin hän on tullut puhtaaksi; ja joka koskee johonkin kuolleesta saastuneeseen tahi jolla on siemenvuoto,'),
(1672297,58,3,22,5,'tahi joka koskee pikkueläimeen, mihin tahansa, josta saastuu, tai ihmiseen, josta saastuu, olipa sen saastaisuus mitä laatua tahansa,'),
(1672298,58,3,22,6,'niin jokainen, joka koskee johonkin sellaiseen, olkoon saastainen iltaan asti älköönkä syökö pyhistä lahjoista, ellei hän ole pessyt ruumistaan vedessä.'),
(1672299,58,3,22,7,'Mutta kun aurinko on laskenut, on hän puhdas, ja sitten hän syököön pyhistä lahjoista, sillä se on hänen ruokansa.'),
(1672300,58,3,22,8,'Itsestään kuollutta tai kuoliaaksi raadeltua eläintä hän älköön syökö, ettei hän siten saastuisi. Minä olen Herra.'),
(1672301,58,3,22,9,'He noudattakoot minun määräyksiäni, etteivät joutuisi syynalaisiksi pyhitetyn tähden ja kuolisi, sentähden että häpäisevät pyhitetyn. Minä olen Herra, joka pyhitän heidät.'),
(1672302,58,3,22,10,'Yksikään syrjäinen älköön syökö pyhästä lahjasta; papin loinen tai päiväpalkkalainen älköön syökö pyhästä lahjasta.'),
(1672303,58,3,22,11,'Mutta kun pappi ostaa rahallansa orjan, saakoon tämä siitä syödä; samoin hänen kodissaan syntyneet orjat syökööt hänen ruokaansa.'),
(1672304,58,3,22,12,'Jos papin tytär tulee syrjäisen miehen vaimoksi, älköön hän syökö pyhistä antilahjoista.'),
(1672305,58,3,22,13,'Mutta jos papin tytär tulee leskeksi tai hyljätyksi ja on lapseton ja hän tulee takaisin isänsä taloon ja asuu siellä niinkuin nuoruudessaan, niin hän syököön isänsä ruokaa; mutta kukaan syrjäinen älköön sitä syökö.'),
(1672306,58,3,22,14,'Ja jos joku erehdyksessä syö pyhästä lahjasta, korvatkoon papille pyhän lahjan ja pankoon siihen vielä lisäksi viidennen osan sen arvosta.'),
(1672307,58,3,22,15,'Älkööt papit häväiskö israelilaisten pyhiä lahjoja, joita nämä antavat Herralle,'),
(1672308,58,3,22,16,'älköötkä saattako heitä syynalaisiksi ja vikapäiksi sallimalla heidän syödä pyhiä lahjojansa; sillä minä olen Herra, joka pyhitän heidät."'),
(1672309,58,3,22,17,'Ja Herra puhui Moosekselle sanoen:'),
(1672310,58,3,22,18,'"Puhu Aaronille ja hänen pojillensa ja kaikille israelilaisille ja sano heille: Kuka ikinä Israelin heimosta tai muukalaisista Israelissa tuo polttouhriksi uhrilahjansa, olipa se mikä hyvänsä lupausuhri tai vapaaehtoinen uhri, jonka he tuovat Herralle,'),
(1672311,58,3,22,19,'niin tuokaa sellainen uhri, että hänen mielisuosionsa tulee teidän osaksenne: virheetön urospuoli raavaista, lampaista tai vuohista.'),
(1672312,58,3,22,20,'Mutta yhtään eläintä, jossa on vamma, älkää tuoko, sillä siitä hänen mielisuosionsa ei tule teidän osaksenne.'),
(1672313,58,3,22,21,'Jos joku tuo Herralle yhteysuhrin raavaista tai lampaista, joko lupausta täyttääkseen tai vapaaehtoisena uhrina, olkoon eläin virheetön ollakseen otollinen; älköön siinä olko mitään vammaa.'),
(1672314,58,3,22,22,'Sokeata tai raajarikkoa tai silvottua tai paiseista tai ihotautista tai rupista älkää Herralle tuoko, älkääkä sellaisia asettako alttarille, uhriksi Herralle.'),
(1672315,58,3,22,23,'Härän tai lampaan, joka on jäseniltään muodoton tai vaivainen, sinä saat uhrata vapaaehtoisena uhrina, mutta lupausuhriksi se ei ole otollinen.'),
(1672316,58,3,22,24,'Älkää uhratko Herralle eläintä, joka on kuohittu puristamalla tai musertamalla tai repimällä tai leikkaamalla; älkää tehkö maassanne sellaista.'),
(1672317,58,3,22,25,'Älkää myöskään muukalaiselta ostako mitään sellaisia eläimiä tuodaksenne niitä Jumalanne ruuaksi, sillä ne ovat turmeltuja, niissä on vamma; niistä ei tule teidän osaksenne mielisuosio."'),
(1672318,58,3,22,26,'Ja Herra puhui Moosekselle sanoen:'),
(1672319,58,3,22,27,'"Kun vasikka tai karitsa tai vohla on syntynyt, olkoon se emänsä luona seitsemän päivää; mutta kahdeksannesta päivästä alkaen se on otollinen uhrilahjaksi Herralle.'),
(1672320,58,3,22,28,'Älkää raavaseläintä tai lammasta ja sen sikiötä teurastako samana päivänä.'),
(1672321,58,3,22,29,'Kun te uhraatte Herralle kiitosuhrin, uhratkaa se niin, että hänen mielisuosionsa tulee teidän osaksenne.'),
(1672322,58,3,22,30,'Se syötäköön samana päivänä; älkää jättäkö siitä mitään seuraavaan aamuun. Minä olen Herra.'),
(1672323,58,3,22,31,'Noudattakaa siis minun käskyjäni ja pitäkää ne. Minä olen Herra.'),
(1672324,58,3,22,32,'Älkää häväiskö minun pyhää nimeäni: minä tahdon olla pyhä israelilaisten keskellä. Minä olen Herra, joka pyhitän teidät'),
(1672325,58,3,22,33,'ja joka vein teidät pois Egyptin maasta, ollakseni teidän Jumalanne. Minä olen Herra."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672326,58,3,23,1,'Ja Herra puhui Moosekselle sanoen:'),
(1672327,58,3,23,2,'"Puhu israelilaisille ja sano heille: Herran juhla-ajat, joiksi teidän on kuulutettava pyhät kokoukset, minun juhla-aikani, ovat nämä.'),
(1672328,58,3,23,3,'Kuusi päivää tehtäköön työtä, mutta seitsemäntenä päivänä on sapatti, levon päivä, pyhä kokous; silloin älkää yhtäkään askaretta toimittako, se on Herran sapatti, missä asuttekin.'),
(1672329,58,3,23,4,'Nämä ovat Herran juhla-ajat, pyhät kokoukset, jotka teidän on kuulutettava määräajallansa:'),
(1672330,58,3,23,5,'Ensimmäisessä kuussa, kuukauden neljäntenätoista päivänä, iltahämärässä, on pääsiäinen Herran kunniaksi.'),
(1672331,58,3,23,6,'Ja saman kuukauden viidentenätoista päivänä on happamattoman leivän juhla Herran kunniaksi; syökää happamatonta leipää seitsemän päivää.'),
(1672332,58,3,23,7,'Ensimmäisenä päivänä olkoon teillä pyhä kokous, silloin älkää yhtäkään arkiaskaretta toimittako.'),
(1672333,58,3,23,8,'Tuokaa Herralle uhri seitsemänä päivänä. Seitsemäntenä päivänä on pyhä kokous; silloin älkää yhtäkään arkiaskaretta toimittako."'),
(1672334,58,3,23,9,'Ja Herra puhui Moosekselle sanoen:'),
(1672335,58,3,23,10,'"Puhu israelilaisille ja sano heille: Kun te tulette siihen maahan, jonka minä teille annan, ja leikkaatte sen viljaa, niin viekää papille viljastanne uutislyhde.'),
(1672336,58,3,23,11,'Ja hän toimittakoon sen lyhteen heilutuksen Herran edessä, että hänen mielisuosionsa tulisi teidän osaksenne; sapatin jälkeisenä päivänä pappi toimittakoon sen heilutuksen.'),
(1672337,58,3,23,12,'Ja sinä päivänä, jona teidän lyhteenne heilutus toimitetaan, uhratkaa virheetön, vuoden vanha karitsa polttouhriksi Herralle,'),
(1672338,58,3,23,13,'ja siihen kuuluvaksi ruokauhriksi kaksi kymmenennestä lestyjä jauhoja, öljyyn sekoitettuna, uhriksi, suloiseksi tuoksuksi Herralle, sekä siihen kuuluvaksi juomauhriksi neljännes hiin-mittaa viiniä.'),
(1672339,58,3,23,14,'Älkääkä syökö uutisleipää, paahdettuja jyviä tai tuleentumatonta viljaa ennen sitä päivää, jona tuotte Jumalallenne uhrilahjan. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen, missä asuttekin.'),
(1672340,58,3,23,15,'Sitten laskekaa sapatin jälkeisestä päivästä, siitä päivästä, jona toitte heilutuslyhteen, seitsemän täyttä viikkoa,'),
(1672341,58,3,23,16,'laskekaa viisikymmentä päivää seitsemännen sapatin jälkeiseen päivään asti; sitten tuokaa Herralle uusi ruokauhri.'),
(1672342,58,3,23,17,'Sieltä, missä asutte, tuokaa heilutusleiväksi kaksi kakkua, jotka on leivottava happamena kahdesta kymmenenneksestä lestyjä jauhoja, Herralle uutislahjaksi.'),
(1672343,58,3,23,18,'Ja tuokaa leipänne ohella seitsemän virheetöntä, vuoden vanhaa karitsaa ja mullikka sekä kaksi oinasta; ruoka- ja juomauhreineen ne olkoot polttouhri Herralle, suloisesti tuoksuva uhri Herralle.'),
(1672344,58,3,23,19,'Ja uhratkaa kauris syntiuhriksi sekä kaksi vuoden vanhaa karitsaa yhteysuhriksi.'),
(1672345,58,3,23,20,'Ja pappi toimittakoon niiden ja uutisleivän ynnä kahden karitsan heilutuksen Herran edessä. Ne olkoot Herralle pyhät ja papin omat.'),
(1672346,58,3,23,21,'Ja kuuluttakaa pyhä kokous juuri siksi päiväksi; silloin älkää yhtäkään arkiaskaretta toimittako. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen, missä asuttekin.'),
(1672347,58,3,23,22,'Kun te korjaatte eloa maastanne, niin älä leikkaa viljaa pelloltasi reunoja myöten äläkä poimi tähkäpäitä leikkuun jälkeen, vaan jätä ne köyhälle ja muukalaiselle. Minä olen Herra, teidän Jumalanne."'),
(1672348,58,3,23,23,'Ja Herra puhui Moosekselle sanoen:'),
(1672349,58,3,23,24,'"Puhu israelilaisille ja sano: Seitsemännessä kuussa, kuukauden ensimmäisenä päivänä, pitäkää sapatinlepo, muistojuhla pasunaa soittaen, pyhä kokous.'),
(1672350,58,3,23,25,'Älkää silloin yhtäkään arkiaskaretta toimittako, vaan tuokaa uhri Herralle."'),
(1672351,58,3,23,26,'Ja Herra puhui Moosekselle sanoen:'),
(1672352,58,3,23,27,'"Tämän seitsemännen kuun kymmenentenä päivänä on sovituspäivä; pitäkää silloin pyhä kokous, kurittakaa itseänne paastolla ja tuokaa Herralle uhri.'),
(1672353,58,3,23,28,'Älkää toimittako yhtäkään askaretta sinä päivänä, sillä se on sovituspäivä, jolloin teille toimitetaan sovitus Herran, teidän Jumalanne, edessä.'),
(1672354,58,3,23,29,'Sillä jokainen, joka ei sinä päivänä kurita itseänsä paastolla, hävitettäköön kansastansa.'),
(1672355,58,3,23,30,'Ja jokaisen, joka sinä päivänä toimittaa jotakin askaretta, minä hävitän hänen kansastansa.'),
(1672356,58,3,23,31,'Älkää silloin yhtäkään askaretta toimittako. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen, missä asuttekin.'),
(1672357,58,3,23,32,'Se on oleva teille levon päivä, kurittakaa itseänne paastolla. Kuukauden yhdeksäntenä päivänä illalla, illasta iltaan, pitäkää tämä sapatti."'),
(1672358,58,3,23,33,'Ja Herra puhui Moosekselle sanoen:'),
(1672359,58,3,23,34,'"Puhu israelilaisille ja sano: Tämän seitsemännen kuun viidentenätoista päivänä on lehtimajanjuhla Herran kunniaksi; se kestää seitsemän päivää.'),
(1672360,58,3,23,35,'Ensimmäisenä päivänä pidettäköön pyhä kokous; älkää silloin yhtäkään arkiaskaretta toimittako.'),
(1672361,58,3,23,36,'Seitsemänä päivänä tuokaa uhri Herralle. Kahdeksantena päivänä olkoon teillä pyhä kokous, ja tuokaa uhri Herralle; se on juhlakokous, älkää silloin yhtäkään arkiaskaretta toimittako.'),
(1672362,58,3,23,37,'Nämä ovat Herran juhla-ajat, joiksi teidän on kuulutettava pyhät kokoukset, tuodaksenne Herralle uhreja: polttouhreja ja ruokauhreja, teurasuhreja ja juomauhreja, kunakin päivänä sen päivän uhrit;'),
(1672363,58,3,23,38,'ja sitäpaitsi Herran sapatit ja teidän muut lahjanne ja kaikki lupausuhrinne ja kaikki vapaaehtoiset uhrinne, joita te Herralle annatte.'),
(1672364,58,3,23,39,'Mutta seitsemännen kuukauden viidentenätoista päivänä, kun te olette korjanneet maan sadon, viettäkää Herran juhlaa seitsemän päivää; ensimmäinen päivä on levon päivä, ja kahdeksas päivä on myös levon päivä.'),
(1672365,58,3,23,40,'Ensimmäisenä päivänä ottakaa ihania hedelmiä puista, palmunoksia ja tuuheiden puiden lehviä sekä pajuja purojen varsilta, ja pitäkää iloa seitsemän päivää Herran, Jumalanne edessä.'),
(1672366,58,3,23,41,'Ja viettäkää sitä juhlana Herran kunniaksi seitsemän päivää vuodessa. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen; viettäkää se seitsemännessä kuussa.'),
(1672367,58,3,23,42,'Seitsemän päivää asukaa lehtimajoissa; kaikki Israelissa syntyneet asukoot lehtimajoissa,'),
(1672368,58,3,23,43,'että teidän jälkeläisenne tietäisivät, kuinka minä annoin israelilaisten asua lehtimajoissa, kun vein heidät pois Egyptin maasta. Minä olen Herra, teidän Jumalanne."'),
(1672369,58,3,23,44,'Ja Mooses puhui näistä Herran juhla-ajoista israelilaisille.'),
(1672370,58,3,24,1,'Ja Herra puhui Moosekselle sanoen:'),
(1672371,58,3,24,2,'"Käske israelilaisten tuoda sinulle puhdasta, survomalla saatua öljypuun öljyä seitsenhaaraista lamppua varten, että lamput aina voidaan nostaa paikoilleen.'),
(1672372,58,3,24,3,'Ulkopuolella esirippua, joka on lain arkin edessä ilmestysmajassa, Aaron hoitakoon sitä niin, että se aina, ehtoosta aamuun asti, palaa Herran edessä. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen.'),
(1672373,58,3,24,4,'Aitokultaisen seitsenhaaraisen lampun lamppuja hän hoitakoon niin, että ne aina palavat Herran edessä.'),
(1672374,58,3,24,5,'Ja ota lestyjä jauhoja ja leivo niistä kaksitoista kakkua; joka kakussa olkoon niitä kaksi kymmenennestä.'),
(1672375,58,3,24,6,'Ja lado ne päälletysten kahteen pinoon, kuusi pinoonsa, aitokultaiselle pöydälle Herran eteen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672376,58,3,24,7,'Ja pane pinojen päälle puhdasta suitsuketta leipien alttariuhriosana uhriksi Herralle.'),
(1672377,58,3,24,8,'Sapatti sapatilta hän aina asettakoon ne Herran eteen israelilaisten antina; se on ikuinen liitto.'),
(1672378,58,3,24,9,'Ne olkoot Aaronin ja hänen poikiensa omat, ja he syökööt ne pyhässä paikassa, sillä ne ovat korkeasti-pyhät; ne ovat hänen ikuinen osuutensa Herran uhreista."'),
(1672379,58,3,24,10,'Erään israelilaisen vaimon poika, jonka isä oli egyptiläinen mies, oli lähtenyt maasta israelilaisten mukana; ja tämän israelilaisen vaimon poika ja muuan israelilainen mies riitelivät keskenänsä leirissä.'),
(1672380,58,3,24,11,'Ja israelilaisen vaimon poika pilkkasi Herran nimeä ja kirosi sitä. Silloin he toivat hänet Mooseksen eteen. Ja hänen äitinsä nimi oli Selomit, Dibrin tytär, Daanin sukukunnasta.'),
(1672381,58,3,24,12,'Ja he panivat hänet vankeuteen, kunnes heille ilmoitettaisiin Herran vastaus.'),
(1672382,58,3,24,13,'Ja Herra puhui Moosekselle sanoen:'),
(1672383,58,3,24,14,'"Vie kirooja leirin ulkopuolelle, ja kaikki, jotka kuulivat sen, laskekoot kätensä hänen päänsä päälle, ja koko kansa kivittäköön hänet.'),
(1672384,58,3,24,15,'Ja puhu israelilaisille ja sano: Kuka ikinä Jumalaansa kiroaa, se joutuu syynalaiseksi.'),
(1672385,58,3,24,16,'Ja joka Herran nimeä pilkkaa, rangaistakoon kuolemalla; koko kansa kivittäköön hänet kuoliaaksi. Olipa se muukalainen tai maassa syntynyt, joka pilkkaa Herran nimeä, hänet surmattakoon.'),
(1672386,58,3,24,17,'Jos joku lyö kuoliaaksi ihmisen, kenen hyvänsä, hänet rangaistakoon kuolemalla.'),
(1672387,58,3,24,18,'Mutta joka lyö kuoliaaksi kotieläimen, korvatkoon sen: henki hengestä.'),
(1672388,58,3,24,19,'Ja joka tuottaa lähimmäisellensä vamman, sille tehtäköön, niinkuin hänkin on tehnyt:'),
(1672389,58,3,24,20,'ruhje ruhjeesta, silmä silmästä, hammas hampaasta; saman vamman, jonka hän on toiselle tuottanut, saakoon hän itsekin.'),
(1672390,58,3,24,21,'Joka lyö kuoliaaksi kotieläimen, korvatkoon sen; mutta joka lyö kuoliaaksi ihmisen, se surmattakoon.'),
(1672391,58,3,24,22,'Sama laki olkoon teillä, niin muukalaisella kuin maassa syntyneelläkin; sillä minä olen Herra, teidän Jumalanne."'),
(1672392,58,3,24,23,'Ja Mooses puhui näin israelilaisille; ja he veivät kiroojan leirin ulkopuolelle ja kivittivät hänet kuoliaaksi. Näin israelilaiset tekivät, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1672393,58,3,25,1,'Ja Herra puhui Moosekselle Siinain vuorella sanoen:'),
(1672394,58,3,25,2,'"Puhu israelilaisille ja sano heille: Kun te tulette siihen maahan, jonka minä teille annan, niin maa pitäköön sapattia Herran kunniaksi.'),
(1672395,58,3,25,3,'Kuutena vuotena kylvä peltosi ja kuutena vuotena leikkaa viinitarhasi ja korjaa niiden sato,'),
(1672396,58,3,25,4,'mutta seitsemäntenä vuotena olkoon maalla levon aika, sapatti Herran kunniaksi; silloin älä kylvä peltoasi äläkä leikkaa viinitarhaasi.'),
(1672397,58,3,25,5,'Leikatun viljasi jälkikasvua älä leikkaa, äläkä poimi viinirypäleitä, jotka ovat kasvaneet leikkaamattomissa viinipuissasi. Silloin olkoon maalla levon vuosi.'),
(1672398,58,3,25,6,'Mutta mitä itsestänsä kasvaa maan levätessä, olkoon teille ruuaksi, sinulle itsellesi, sinun palvelijallesi ja palvelijattarellesi, päiväpalkkalaisellesi ja loisellesi, jotka luonasi asuvat.'),
(1672399,58,3,25,7,'Ja karjallesi ja metsäeläimille sinun maassasi olkoon kaikki sen sato ruuaksi.'),
(1672400,58,3,25,8,'Ja laske seitsemän vuosiviikkoa: seitsemän kertaa seitsemän vuotta, niin että seitsemän vuosiviikon aika on neljäkymmentä yhdeksän vuotta.'),
(1672401,58,3,25,9,'Ja seitsemännessä kuussa, kuukauden kymmenentenä päivänä anna pasunan raikuen soida; sovituspäivänä antakaa pasunan soida koko maassanne.'),
(1672402,58,3,25,10,'Ja pyhittäkää viideskymmenes vuosi ja julistakaa vapautus maassa kaikille sen asukkaille. Se olkoon teille riemuvuosi; jokainen teistä saa silloin palata perintömaallensa ja sukunsa luo.'),
(1672403,58,3,25,11,'Riemuvuosi olkoon teille viideskymmenes vuosi; älkää silloin kylväkö älkääkä jälkikasvua leikatko, älkääkä poimiko, mitä leikkaamattomissa viinipuissa on kasvanut.'),
(1672404,58,3,25,12,'Sillä se on riemuvuosi, se olkoon teille pyhä; pellolta syökää sen sato.'),
(1672405,58,3,25,13,'Riemuvuotena saa jokainen teistä palata perintömaallensa.'),
(1672406,58,3,25,14,'Jos myyt jotakin lähimmäisellesi tai ostat jotakin lähimmäiseltäsi, niin älkää tehkö vääryyttä toinen toisellenne.'),
(1672407,58,3,25,15,'Vaan maksa lähimmäisellesi riemuvuoden jälkeisten vuosien luvun mukaan, satovuosien luvun mukaan hän saakoon maksun sinulta.'),
(1672408,58,3,25,16,'Kuta useampia vuosia on, maksa sitä suurempi hinta, ja kuta vähemmän vuosia on, maksa sitä pienempi hinta; sillä satomäärän hän myy sinulle.'),
(1672409,58,3,25,17,'Älköön teistä kukaan tehkö vääryyttä lähimmäisellensä, vaan pelkää Jumalaasi; sillä minä olen Herra, teidän Jumalanne.'),
(1672410,58,3,25,18,'Sentähden pitäkää minun käskyni ja noudattakaa minun säädöksiäni ja pitäkää ne, niin te saatte turvallisesti asua maassa.'),
(1672411,58,3,25,19,'Ja maa on antava hedelmänsä, ja teillä on kyllin syötävää, ja te saatte turvallisesti asua siinä.'),
(1672412,58,3,25,20,'Ja jos te sanotte: ''Mitä me syömme seitsemäntenä vuotena, kun meidän ei ole lupa kylvää eikä korjata satoamme?'''),
(1672413,58,3,25,21,'niin minä käsken siunaukseni kuudentena vuotena tulemaan teille, niin että se tuottaa teille kolmen vuoden sadon.'),
(1672414,58,3,25,22,'Ja kun te kylvätte kahdeksantena vuotena, on teillä vielä vanhaa satoa syödä; siihen asti, kunnes yhdeksäntenä vuotena sen sato on saatu, on teillä vanhaa syödä.'),
(1672415,58,3,25,23,'Älköön maata ainaiseksi myytäkö, sillä maa on minun ja te olette muukalaisia ja vieraita minun luonani.'),
(1672416,58,3,25,24,'Ja kaikessa siinä maassa, jonka te saatte perintömaaksenne, antakaa oikeus maan sukulunastamiseen.'),
(1672417,58,3,25,25,'Jos veljesi köyhtyy ja myy perintömaatansa, niin hänen lähin sukulunastajansa tulkoon ja lunastakoon sen, mitä hänen veljensä on myynyt.'),
(1672418,58,3,25,26,'Mutta jos jollakin ei ole sukulunastajaa, mutta hän itse voi hankkia niin paljon, kuin lunastukseen tarvitaan,'),
(1672419,58,3,25,27,'niin laskekoon, kuinka monta vuotta on kulunut myymisestä, ja maksakoon jäljellä olevasta ajasta miehelle, jolle hän myi, ja palatkoon perintömaallensa.'),
(1672420,58,3,25,28,'Mutta jos hän ei voi hankkia niin paljoa, kuin maksamiseen tarvitaan, niin jääköön se, mitä hän on myynyt, ostajan haltuun riemuvuoteen asti. Mutta riemuvuotena se on vapaa, ja hän palatkoon perintömaallensa.'),
(1672421,58,3,25,29,'Jos joku myy asuinrakennuksen muureilla varustetussa kaupungissa, olkoon hänellä oikeus lunastaa se vuoden kuluessa siitä, kun hän sen myi; sen ajan kestää hänen sukulunastusoikeutensa.'),
(1672422,58,3,25,30,'Mutta jollei sitä lunasteta, ennenkuin vuosi on kulunut umpeen, niin jääköön talo muureilla varustetussa kaupungissa ainaiseksi ostajalle ja hänen suvullensa, riemuvuotena vapaaksi tulematta.'),
(1672423,58,3,25,31,'Mutta talot kylissä, joiden ympärillä ei ole muuria, luettakoon peltomaahan; ne olkoot lunastettavissa, ja riemuvuotena ne tulevat vapaiksi.'),
(1672424,58,3,25,32,'Kuitenkin olkoon leeviläisillä niissä kaupungeissa, jotka ovat heidän perintöomaisuuttaan, ikuinen oikeus talojen lunastamiseen.'),
(1672425,58,3,25,33,'Jos joku leeviläinen käyttää lunastusoikeutta, niin myyty talo kaupungissa, joka on leeviläistä perintöomaisuutta, palautuu riemuvuotena vapaaksi; sillä talot leeviläiskaupungeissa ovat heidän perintöomaisuuttaan israelilaisten seassa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672426,58,3,25,34,'Ja heidän kaupunkeihinsa kuuluvaa laidunmaata älköön myytäkö, sillä se on heidän ikuista perintöomaisuuttansa.'),
(1672427,58,3,25,35,'Jos veljesi sinun luonasi köyhtyy eikä jaksa pysyä pystyssä, tue häntä samoinkuin muukalaista tai loista; hän eläköön luonasi.'),
(1672428,58,3,25,36,'Älä ota korkoa tai voittoa häneltä, vaan pelkää Jumalaasi ja anna veljesi elää luonasi.'),
(1672429,58,3,25,37,'Älä anna hänelle rahaasi korolle äläkä ota elintarpeista voittoa.'),
(1672430,58,3,25,38,'Minä olen Herra, teidän Jumalanne, joka vein teidät pois Egyptin maasta antaakseni teille Kanaanin maan ja ollakseni teidän Jumalanne.'),
(1672431,58,3,25,39,'Jos veljesi sinun luonasi köyhtyy ja myy itsensä sinulle, älä pane häntä orjan työhön,'),
(1672432,58,3,25,40,'vaan hän olkoon päiväpalkkalaisena ja loisena sinun luonasi; riemuvuoteen asti hän palvelkoon sinua.'),
(1672433,58,3,25,41,'Silloin hän lähteköön luotasi vapaana, hän ja hänen lapsensa hänen kanssaan, ja palatkoon sukunsa luo ja isiensä perintömaalle.'),
(1672434,58,3,25,42,'Sillä he ovat minun palvelijoitani, jotka minä vein pois Egyptin maasta; sentähden älköön heitä orjan tavalla myytäkö.'),
(1672435,58,3,25,43,'Älä hallitse heitä kovuudella, vaan pelkää Jumalaasi.'),
(1672436,58,3,25,44,'Mutta orjasi ja orjattaresi, jotka hankit itsellesi, ostakaa kansoista, jotka asuvat teidän ympärillänne.'),
(1672437,58,3,25,45,'Tahi ostakaa ne teidän luonanne asuvien loisten lapsista ja heidän sukulaisistaan, jotka ovat teidän luonanne ja jotka ovat heille syntyneet teidän maassanne; ja ne olkoot teidän perintöomaisuuttanne.'),
(1672438,58,3,25,46,'Ja jättäkää ne jälkeenne perinnöksi lapsillenne, pysyväksi perintöomaisuudeksi; niitä saatte pitää ainaisesti orjinanne. Mutta veljistänne, israelilaisista, älä ketään kovuudella hallitse.'),
(1672439,58,3,25,47,'Jos sinun luonasi asuva muukalainen tai loinen tulee varoihin, veljesi köyhtyessä hänen luonaan, niin että hän myy itsensä sinun luonasi asuvalle muukalaiselle tai loiselle tai jollekin muukalaisen suvun jäsenelle,'),
(1672440,58,3,25,48,'niin olkoon hän, sen jälkeen kuin hän myi itsensä, lunastettavissa; joku hänen veljistään lunastakoon hänet.'),
(1672441,58,3,25,49,'Tahi lunastakoon hänet hänen setänsä tai setänsä poika tai joku veriheimolainen hänen suvustansa; tahi jos hän tulee varoihin, lunastakoon hän itse itsensä.'),
(1672442,58,3,25,50,'Ja hänen on laskettava yhdessä ostajansa kanssa, kuinka pitkä aika on riemuvuoteen siitä vuodesta, jolloin hän myi itsensä hänelle; ja hänen myyntihintansa jaettakoon vuosien luvulla; hänen palvelusaikansa laskettakoon saman arvoiseksi kuin päiväpalkkalaisen.'),
(1672443,58,3,25,51,'Jos vielä on monta vuotta jäljellä, maksakoon hän takaisin lunastushintanaan niitä vastaavan osan siitä summasta, jolla hänet ostettiin.'),
(1672444,58,3,25,52,'Mutta jos vain vähän vuosia on jäljellä riemuvuoteen, laskekoon ostaja nekin hänelle, ja hän maksakoon lunastushintansa sen mukaan, kuin hänellä on vuosia jäljellä.'),
(1672445,58,3,25,53,'Vuosikaupalla otetun päiväpalkkalaisen tavalla hän palvelkoon häntä, mutta älköön tämä kovuudella hallitko häntä sinun silmiesi edessä.'),
(1672446,58,3,25,54,'Mutta jos häntä ei näin lunasteta, tulkoon hän riemuvuotena vapaaksi, hän itse ja hänen lapsensa hänen kanssaan.'),
(1672447,58,3,25,55,'Sillä israelilaiset ovat minun palvelijoitani; he ovat minun palvelijani, jotka minä vein pois Egyptin maasta. Minä olen Herra, teidän Jumalanne."'),
(1672448,58,3,26,1,'"Älkää tehkö itsellenne epäjumalia älkääkä pystyttäkö itsellenne jumalankuvia tai patsaita, älkää myöskään asettako maahanne kiviä, joissa on kuvia, kumartaaksenne niitä, sillä minä olen Herra, teidän Jumalanne.'),
(1672449,58,3,26,2,'Pitäkää minun sapattini ja peljätkää minun pyhäkköäni. Minä olen Herra.'),
(1672450,58,3,26,3,'Jos te vaellatte minun säädöksieni mukaan ja noudatatte minun käskyjäni ja pidätte ne,'),
(1672451,58,3,26,4,'annan minä teille sateen ajallansa, niin että maa antaa satonsa ja kedon puut kantavat hedelmänsä.'),
(1672452,58,3,26,5,'Ja puiminen kestää teillä viininkorjuuseen asti, ja viininkorjuu kestää kylvöön asti, ja teillä on kyllin leipää syödäksenne, ja te saatte turvallisesti asua maassanne.'),
(1672453,58,3,26,6,'Ja minä annan rauhan teidän maallenne, ja te saatte levätä, kenenkään peljättämättä; ja minä hävitän pahat pedot teidän maastanne, eikä miekka käy teidän maanne ylitse.'),
(1672454,58,3,26,7,'Te ajatte pakoon vihollisenne, ja he kaatuvat miekkaan teidän edessänne.'),
(1672455,58,3,26,8,'Viisi teistä ajaa pakoon sata, ja sata teistä ajaa pakoon kymmenentuhatta, ja teidän vihollisenne kaatuvat miekkaan teidän edessänne.'),
(1672456,58,3,26,9,'Ja minä käännyn teidän puoleenne ja teen teidät hedelmällisiksi ja annan teidän lisääntyä ja pidän liittoni teidän kanssanne.'),
(1672457,58,3,26,10,'Ja te saatte syödä vanhaa, viime vuoden satoa, ja te joudutte viemään vanhan pois uuden tieltä.'),
(1672458,58,3,26,11,'Ja minä panen asumukseni teidän keskellenne enkä viero teitä.'),
(1672459,58,3,26,12,'Ja minä vaellan teidän keskellänne ja olen teidän Jumalanne, ja te olette minun kansani.'),
(1672460,58,3,26,13,'Minä olen Herra, teidän Jumalanne, joka vein teidät pois Egyptin maasta, olemasta heidän orjinansa; ja minä mursin rikki teidän ikeenne puut ja annoin teidän kulkea pää pystyssä.'),
(1672461,58,3,26,14,'Mutta jos te ette kuule minua ettekä pidä kaikkia näitä käskyjä,'),
(1672462,58,3,26,15,'vaan hylkäätte halpana minun ohjeeni ja teidän sielunne vieroo minun säädöksiäni, niin ettette pidä kaikkia minun käskyjäni, vaan rikotte minun liittoni,'),
(1672463,58,3,26,16,'niin minäkin teen teille samoin ja rankaisen teitä hirmuisilla onnettomuuksilla, hivutustaudilla ja kuumeella, jotka sammuttavat teidän silmänne ja näännyttävät sielunne; ja te kylvätte siemenenne turhaan, sillä teidän vihollisenne syövät sen.'),
(1672464,58,3,26,17,'Ja minä käännän kasvoni teitä vastaan, ja teidän vihollisenne voittavat teidät; teidän vihamiehenne hallitsevat teitä, ja te pakenette, vaikka ei kukaan aja teitä takaa.'),
(1672465,58,3,26,18,'Jos ette sittenkään kuule minua, niin minä vielä kuritan teitä seitsenkertaisesti teidän syntienne tähden.'),
(1672466,58,3,26,19,'Ja minä murran teidän ylpeän uhmanne; minä teen teidän taivaanne raudankovaksi ja maanne vasken kaltaiseksi.'),
(1672467,58,3,26,20,'Ja teidän voimanne kuluu hukkaan, sillä teidän maanne ei anna satoansa eivätkä maan puut anna hedelmäänsä.'),
(1672468,58,3,26,21,'Ja jos te sittenkin käytte minua vastaan ettekä tahdo kuulla minua, niin minä lyön teitä vielä seitsenkertaisesti, teidän syntienne mukaan.'),
(1672469,58,3,26,22,'Minä lähetän teidän sekaanne metsän pedot riistämään teiltä lapsenne, raatelemaan karjaanne ja vähentämään teidän lukuanne, niin että teidän tienne tulevat autioiksi.'),
(1672470,58,3,26,23,'Jos te ette vielä tästäkään minun kurituksestani ota ojentuaksenne, vaan yhä käytte minua vastaan,'),
(1672471,58,3,26,24,'niin minäkin käyn teitä vastaan ja lyön teitä seitsenkertaisesti teidän syntienne tähden.'),
(1672472,58,3,26,25,'Minä saatan teidän kimppuunne miekan, joka kostaa rikotun liiton; ja kun te kokoonnutte kaupunkeihinne, niin minä lähetän teidän sekaanne ruttotaudin, ja teidän on antautuminen vihollisen valtaan.'),
(1672473,58,3,26,26,'Kun minä murran teiltä leivän tuen, niin kymmenen vaimoa paistaa teidän leipänne yhdessä uunissa, ja he tuovat kotiin teidän leipänne vaa''alla punnittuna; ja kun te syötte, ette tule ravituiksi.'),
(1672474,58,3,26,27,'Ja jos te ette vielä sittenkään kuule minua, vaan yhä käytte minua vastaan,'),
(1672475,58,3,26,28,'niin minäkin kiivastuksessani käyn teitä vastaan ja kuritan teitä seitsenkertaisesti teidän syntienne tähden.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672476,58,3,26,29,'Ja te syötte poikienne lihaa, ja tyttärienne lihaa te syötte.'),
(1672477,58,3,26,30,'Ja minä kukistan teidän uhrikukkulanne ja hävitän teidän auringonpatsaanne ja panen teidän ruumiinne teidän kivijumalienne ruumiiden päälle, ja minun sieluni inhoaa teitä.'),
(1672478,58,3,26,31,'Ja minä muutan teidän kaupunkinne raunioiksi ja hävitän teidän pyhäkkönne enkä mielisty teidän uhrienne tuoksuun.'),
(1672479,58,3,26,32,'Ja minä hävitän maan, niin että teidän vihollisenne, jotka siinä asuvat, siitä tyrmistyvät.'),
(1672480,58,3,26,33,'Mutta teidät minä hajotan kansojen sekaan ja ajan teitä takaa paljastetulla miekalla, ja teidän maanne tulee autioksi ja kaupunkinne raunioiksi.'),
(1672481,58,3,26,34,'Silloin maa saa hyvityksen sapateistaan, niin kauan kuin se on autiona ja te olette vihollistenne maassa. Silloin maa lepää ja saa hyvityksen sapateistaan.'),
(1672482,58,3,26,35,'Niin kauan kuin se on autiona, saa se levätä nauttien sitä lepoa, jota se ei saanut teidän sapatteinanne, asuessanne siinä.'),
(1672483,58,3,26,36,'Ja niille teistä, jotka jäävät jäljelle, minä annan pelokkaan sydämen heidän vihollistensa maassa, niin että lentävän lehden kahina ajaa heidät pakoon, ja he pakenevat, niinkuin pakenisivat miekkaa, ja kaatuvat, vaikka ei kukaan heitä aja takaa.'),
(1672484,58,3,26,37,'Ja he kompastuvat toinen toiseensa niinkuin miekkaa paeten, vaikka ei kukaan aja heitä takaa; ja te ette voi pitää puolianne vihollisianne vastaan.'),
(1672485,58,3,26,38,'Ja te häviätte kansojen sekaan, ja vihollistenne maa nielee teidät.'),
(1672486,58,3,26,39,'Ja ne teistä, jotka jäävät jäljelle, riutuvat teidän vihollistenne maassa syntivelkansa tähden; ja myös isiensä syntivelan tähden he riutuvat niinkuin nekin.'),
(1672487,58,3,26,40,'Silloin he tunnustavat syntivelkansa ja isiensä syntivelan, sen että ovat olleet minulle uskottomat ja käyneet minua vastaan,'),
(1672488,58,3,26,41,'jonka tähden minäkin kävin heitä vastaan ja vein heidät heidän vihollistensa maahan. Silloin heidän ympärileikkaamaton sydämensä nöyrtyy, ja silloin he sovittavat syntivelkansa.'),
(1672489,58,3,26,42,'Ja silloin minä muistan liittoni Jaakobin kanssa ja muistan liittoni Iisakin kanssa ja liittoni Aabrahamin kanssa, ja minä muistan myös maan.'),
(1672490,58,3,26,43,'Mutta ensin tulkoon maa tyhjäksi heistä ja saakoon hyvityksen sapateistansa olemalla autiona, niin kauan kuin he ovat poissa; ja he sovittakoot syntivelkansa sentähden, juuri sentähden, että he hylkäsivät minun säädökseni ja että heidän sielunsa vieroi minun käskyjäni.'),
(1672491,58,3,26,44,'Mutta sittenkään, vaikka he ovat vihollistensa maassa, en minä heitä hylkää enkä viero heitä niin, että lopettaisin heidät ja rikkoisin liittoni heidän kanssansa; sillä minä olen Herra, heidän Jumalansa.'),
(1672492,58,3,26,45,'Ja minä muistan heidän hyväksensä liiton heidän isiensä kanssa, jotka minä vein pois Egyptin maasta kansojen silmien edessä, ollakseni heidän Jumalansa. Minä olen Herra."'),
(1672493,58,3,26,46,'Nämä ovat ne käskyt, säädökset ja lait, jotka Herra asetti itsensä ja israelilaisten välille Siinain vuorella, Mooseksen kautta.'),
(1672494,58,3,27,1,'Ja Herra puhui Moosekselle sanoen:'),
(1672495,58,3,27,2,'"Puhu israelilaisille ja sano heille: Jos jollakin on täytettävänä lupaus Herralle ja sinun on arvioitava luvatun ihmisen arvo,'),
(1672496,58,3,27,3,'niin arvioitse mies, joka on kahdenkymmenen ja kuudenkymmenen vuoden välillä, viiteenkymmeneen hopeasekeliin pyhäkkösekelin painon mukaan;'),
(1672497,58,3,27,4,'mutta jos se on nainen, arvioitse hänet kolmeenkymmeneen sekeliin.'),
(1672498,58,3,27,5,'Viisivuotisesta kaksikymmenvuotiseen asti arvioitse miehenpuoli kahteenkymmeneen sekeliin ja vaimonpuoli kymmeneen sekeliin.'),
(1672499,58,3,27,6,'Kuukauden vanhasta viisivuotiseen asti arvioitse miehenpuoli viiteen hopeasekeliin ja vaimonpuoli kolmeen hopeasekeliin.'),
(1672500,58,3,27,7,'Kuusikymmenvuotinen ja sitä vanhempi miehenpuoli arvioitse viiteentoista sekeliin ja vaimonpuoli kymmeneen sekeliin.'),
(1672501,58,3,27,8,'Jos joku on liian köyhä maksamaan arviohintaa, vietäköön hänet papin eteen, ja pappi arvioikoon hänet; lupauksen tekijän varojen mukaan arvioikoon pappi hänet.'),
(1672502,58,3,27,9,'Mutta jos lupaus koskee karjaa, josta voidaan tuoda uhrilahja Herralle, olkoon kaikki, mikä siitä annetaan Herralle, pyhää.'),
(1672503,58,3,27,10,'Sitä älköön vaihdettako älköönkä muutettako; ei hyvää huonoon eikä huonoa hyvään. Jos joku kuitenkin vaihtaa eläimen toiseen, olkoon sekä se että siihen vaihdettu pyhä.'),
(1672504,58,3,27,11,'Mutta jos se on saastainen eläin, mikä tahansa, joita ei saa tuoda uhrilahjaksi Herralle, niin vietäköön eläin papin eteen;'),
(1672505,58,3,27,12,'ja pappi arvioikoon sen tarkastaen, onko se hyvä vai huono. Olkoon sillä se arviohinta, jonka pappi määrää.'),
(1672506,58,3,27,13,'Jos omistaja tahtoo sen lunastaa, antakoon arviohinnan lisäksi viidennen osan siitä.'),
(1672507,58,3,27,14,'Ja jos joku pyhittää talonsa pyhäksi lahjaksi Herralle, niin pappi arvioikoon sen tarkastaen, onko se hyvä vai huono. Olkoon sillä se arviohinta, jonka pappi määrää.'),
(1672508,58,3,27,15,'Mutta jos se, joka on talonsa pyhittänyt, tahtoo lunastaa sen, niin antakoon arviosumman lisäksi viidennen osan siitä; ja niin se on hänen omansa.'),
(1672509,58,3,27,16,'Jos joku pyhittää Herralle kappaleen perintömaatansa, niin arvioi se kylvön suuruuden mukaan; hoomer-mitta ohria vastatkoon viittäkymmentä hopeasekeliä.'),
(1672510,58,3,27,17,'Jos hän pyhittää peltonsa riemuvuodesta alkaen, jääköön sille arvioimasi täysi hinta.'),
(1672511,58,3,27,18,'Mutta jos hän pyhittää peltonsa riemuvuoden jälkeen, laskekoon pappi hänelle rahasumman niiden vuosien luvun mukaan, jotka ovat jäljellä seuraavaan riemuvuoteen; ja se vähennettäköön sinun arvioimastasi hinnasta.'),
(1672512,58,3,27,19,'Ja jos se, joka pellon on pyhittänyt, tahtoo lunastaa sen, niin antakoon arvioimasi hinnan lisäksi viidennen osan siitä; ja niin se jää hänen omakseen.'),
(1672513,58,3,27,20,'Mutta jos hän ei lunasta peltoa, vaan myy sen toiselle, ei se enää ole lunastettavissa;'),
(1672514,58,3,27,21,'vaan kun pelto riemuvuotena tulee vapaaksi, olkoon se Herralle pyhitetty, niinkuin vihitty pelto; se joutuu papin omaisuudeksi.'),
(1672515,58,3,27,22,'Jos joku Herralle pyhittää ostamansa pellon, joka ei ole hänen perintömaatansa,'),
(1672516,58,3,27,23,'laskekoon pappi hänelle arviohinnan riemuvuoteen asti; ja hän suorittakoon samana päivänä arvioimasi hinnan pyhänä lahjana Herralle.'),
(1672517,58,3,27,24,'Riemuvuotena pelto palautukoon sille, jolta se on ostettu ja jonka perintömaata se on.'),
(1672518,58,3,27,25,'Ja kaikki sinun arvioimisesi tapahtukoon pyhäkkösekelin painon mukaan; sekelissä olkoon kaksikymmentä geeraa.'),
(1672519,58,3,27,26,'Mutta karjan esikoista, joka ensiksi syntyneenä jo on Herran oma, älköön kukaan pyhittäkö; olipa se härkä tai lammas, se on jo Herran oma.'),
(1672520,58,3,27,27,'Jos se on saastaisia eläimiä, lunastakoon omistaja sen sinun arvioimastasi hinnasta ja pankoon lisäksi viidennen osan sen arvosta; jos sitä ei lunasteta, myytäköön se arvioimaasi hintaan.'),
(1672521,58,3,27,28,'Mitään vihittyä, mitä hyvänsä, jonka joku on vihkinyt Herralle omaisuudestansa, olipa se ihminen tai eläin tai perintömaa, älköön myytäkö älköönkä lunastettako; sillä kaikki vihitty on korkeasti-pyhää, Herran omaa.'),
(1672522,58,3,27,29,'Ihmistä, ketä hyvänsä, joka on tuhon omaksi vihitty, älköön lunastettako, vaan hänet surmattakoon.'),
(1672523,58,3,27,30,'Kaikki maan kymmenykset, sekä pellon viljasta että puiden hedelmistä, ovat Herran omat, pyhä lahja Herralle.'),
(1672524,58,3,27,31,'Jos joku tahtoo lunastaa jotakin kymmenyksistänsä, antakoon hän siihen lisäksi viidennen osan.'),
(1672525,58,3,27,32,'Ja kaikki kymmenykset raavaskarjasta ja pikkukarjasta, joka kymmenes eläin kaikesta, mikä kulkee paimenen sauvan alitse, olkoot pyhä lahja Herralle.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672526,58,3,27,33,'Älköön kysyttäkö, onko se hyvä vai huono, älköönkä sitä vaihdettako. Jos joku kuitenkin vaihtaa sen, niin olkoon sekä se että siihen vaihdettu pyhä; älköön niitä lunastettako."'),
(1672527,58,4,1,1,'Ja Herra puhui Moosekselle Siinain erämaassa ilmestysmajassa toisen kuukauden ensimmäisenä päivänä, toisena vuotena siitä, kun he olivat lähteneet Egyptin maasta, sanoen:'),
(1672528,58,4,1,2,'"Laskekaa koko Israelin kansan väkiluku suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaikki miehenpuolet, pääluvun mukaan.'),
(1672529,58,4,1,3,'Pitäkää katselmus, sinä ja Aaron, kaikista Israelin sotakelpoisista miehistä, kaksikymmenvuotisista ja sitä vanhemmista, osastoittain.'),
(1672530,58,4,1,4,'Ja teidän apunanne olkoon yksi mies jokaisesta sukukunnasta, sen perhekuntien päämies.'),
(1672531,58,4,1,5,'Ja nämä ovat niiden miesten nimet, jotka teitä avustakoot: Ruubenista Elisur, Sedeurin poika;'),
(1672532,58,4,1,6,'Simeonista Selumiel, Suurisaddain poika;'),
(1672533,58,4,1,7,'Juudasta Nahson, Amminadabin poika;'),
(1672534,58,4,1,8,'Isaskarista Netanel, Suuarin poika;'),
(1672535,58,4,1,9,'Sebulonista Eliab, Heelonin poika;'),
(1672536,58,4,1,10,'Joosefin pojista: Efraimista Elisama, Ammihudin poika ja Manassesta Gamliel, Pedasurin poika;'),
(1672537,58,4,1,11,'Benjaminista Abidan, Gideonin poika;'),
(1672538,58,4,1,12,'Daanista Ahieser, Ammisaddain poika;'),
(1672539,58,4,1,13,'Asserista Pagiel, Okranin poika;'),
(1672540,58,4,1,14,'Gaadista Eljasaf, Deguelin poika;'),
(1672541,58,4,1,15,'Naftalista Ahira, Eenanin poika.'),
(1672542,58,4,1,16,'Nämä olkoot kansan edusmiehet, heidän isiensä sukukuntien ruhtinaat, Israelin heimojen päämiehet."'),
(1672543,58,4,1,17,'Ja Mooses ja Aaron ottivat luoksensa nämä nimeltä mainitut miehet'),
(1672544,58,4,1,18,'ja kokosivat kaiken kansan toisen kuukauden ensimmäisenä päivänä, ja kansa pantiin luetteloihin suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotiset ja sitä vanhemmat, pääluvun mukaan,'),
(1672545,58,4,1,19,'niinkuin Herra oli Moosekselle käskyn antanut. Niin hän piti heistä katselmuksen Siinain erämaassa.'),
(1672546,58,4,1,20,'Ruubenin, Israelin esikoisen, jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän, pääluvun mukaan, kaikkiaan miehenpuolia, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,'),
(1672547,58,4,1,21,'näitä Ruubenin sukukunnasta katselmuksessa olleita oli neljäkymmentäkuusi tuhatta viisisataa.'),
(1672548,58,4,1,22,'Simeonin jälkeläisiä, katselmuksessa olleita, oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän, pääluvun mukaan, kaikkiaan miehenpuolia, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,'),
(1672549,58,4,1,23,'näitä Simeonin sukukunnasta katselmuksessa olleita oli viisikymmentäyhdeksän tuhatta kolmesataa.'),
(1672550,58,4,1,24,'Gaadin jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,'),
(1672551,58,4,1,25,'näitä Gaadin sukukunnasta katselmuksessa olleita oli neljäkymmentäviisi tuhatta kuusisataa viisikymmentä.'),
(1672552,58,4,1,26,'Juudan jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,'),
(1672553,58,4,1,27,'näitä Juudan sukukunnasta katselmuksessa olleita oli seitsemänkymmentäneljä tuhatta kuusisataa.'),
(1672554,58,4,1,28,'Isaskarin jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,'),
(1672555,58,4,1,29,'näitä Isaskarin sukukunnasta katselmuksessa olleita oli viisikymmentäneljä tuhatta neljäsataa.'),
(1672556,58,4,1,30,'Sebulonin jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,'),
(1672557,58,4,1,31,'näitä Sebulonin sukukunnasta katselmuksessa olleita oli viisikymmentäseitsemän tuhatta neljäsataa.'),
(1672558,58,4,1,32,'Joosefin jälkeläisiä, Efraimin jälkeläisiä, oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,'),
(1672559,58,4,1,33,'näitä Efraimin sukukunnasta katselmuksessa olleita oli neljäkymmentätuhatta viisisataa.'),
(1672560,58,4,1,34,'Manassen jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,'),
(1672561,58,4,1,35,'näitä Manassen sukukunnasta katselmuksessa olleita oli kolmekymmentäkaksi tuhatta kaksisataa.'),
(1672562,58,4,1,36,'Benjaminin jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,'),
(1672563,58,4,1,37,'näitä Benjaminin sukukunnasta katselmuksessa olleita oli kolmekymmentäviisi tuhatta neljäsataa.'),
(1672564,58,4,1,38,'Daanin jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,'),
(1672565,58,4,1,39,'näitä Daanin sukukunnasta katselmuksessa olleita oli kuusikymmentäkaksi tuhatta seitsemänsataa.'),
(1672566,58,4,1,40,'Asserin jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,'),
(1672567,58,4,1,41,'näitä Asserin sukukunnasta katselmuksessa olleita oli neljäkymmentäyksi tuhatta viisisataa.'),
(1672568,58,4,1,42,'Naftalin jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,'),
(1672569,58,4,1,43,'näitä Naftalin sukukunnasta katselmuksessa olleita oli viisikymmentäkolme tuhatta neljäsataa.'),
(1672570,58,4,1,44,'Nämä ovat ne katselmuksessa olleet, joista Mooses ja Aaron ja Israelin ruhtinaat, nuo kaksitoista miestä, perhekuntiansa edustaen, pitivät katselmuksen.'),
(1672571,58,4,1,45,'Ja kaikkiaan katselmuksessa olleita israelilaisia oli perhekunnittain, kaksikymmenvuotisia ja sitä vanhempia, kaikkia Israelin sotakelpoisia miehiä,'),
(1672572,58,4,1,46,'näitä katselmuksessa olleita oli yhteensä kuusisataakolme tuhatta viisisataa viisikymmentä.'),
(1672573,58,4,1,47,'Mutta leeviläisistä, heidän isiensä sukukunnasta, ei pidetty katselmusta yhdessä muiden kanssa.'),
(1672574,58,4,1,48,'Sillä Herra puhui Moosekselle sanoen:'),
(1672575,58,4,1,49,'"Ainoastaan Leevin sukukunnasta älä pidä katselmusta äläkä laske heidän väkilukuansa yhdessä muiden israelilaisten kanssa,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672576,58,4,1,50,'vaan pane leeviläiset hoitamaan lain asumusta ja sen kaikkea kalustoa ja kaikkea, mitä siihen kuuluu. He kantakoot asumusta ja sen kaikkea kalustoa, ja he toimittakoot siinä palvelusta sekä leiriytykööt asumuksen ympärille.'),
(1672577,58,4,1,51,'Kun asumus lähtee liikkeelle, purkakoot leeviläiset sen; ja kun asumus pysähtyy leiripaikkaan, pystyttäkööt leeviläiset sen. Syrjäinen, joka siihen ryhtyy, surmattakoon.'),
(1672578,58,4,1,52,'Muut israelilaiset asettukoot kukin omaan leiriinsä ja kukin lippunsa luo, osastoittain.'),
(1672579,58,4,1,53,'Mutta leeviläiset leiriytykööt lain asumuksen ympärille, ettei Herran viha kohtaisi Israelin kansaa, ja leeviläiset hoitakoot tehtäviä lain asumuksessa."'),
(1672580,58,4,1,54,'Ja israelilaiset tekivät kaiken, niinkuin Herra oli Moosekselle käskyn antanut; niin he tekivät.'),
(1672581,58,4,2,1,'Ja Herra puhui Moosekselle ja Aaronille sanoen:'),
(1672582,58,4,2,2,'"Israelilaiset leiriytykööt kukin lippunsa luo, perhekuntiensa sotamerkkien kohdalle; he leiriytykööt taammas ilmestysmajan ympärille.'),
(1672583,58,4,2,3,'Etupuolelle, itään päin, leiriytyköön Juudan leirin lippukunta osastoittain, ja Juudan jälkeläisten päämiehenä olkoon Nahson, Amminadabin poika;'),
(1672584,58,4,2,4,'hänen osastonsa, katselmuksessa olleet, on seitsemänkymmentäneljä tuhatta kuusisataa miestä.'),
(1672585,58,4,2,5,'Hänen viereensä leiriytyköön Isaskarin sukukunta, ja Isaskarin jälkeläisten päämiehenä olkoon Netanel, Suuarin poika;'),
(1672586,58,4,2,6,'hänen osastonsa, katselmuksessa olleet, on viisikymmentäneljä tuhatta neljäsataa miestä.'),
(1672587,58,4,2,7,'Sitten Sebulonin sukukunta, ja Sebulonin jälkeläisten päämiehenä olkoon Eliab, Heelonin poika;'),
(1672588,58,4,2,8,'hänen osastonsa, katselmuksessa olleet, on viisikymmentäseitsemän tuhatta neljäsataa miestä.'),
(1672589,58,4,2,9,'Juudan leirin katselmuksessa olleita on siis kaikkiaan sata kahdeksankymmentäkuusi tuhatta neljäsataa miestä, osastoittain; he lähtekööt liikkeelle ensimmäisenä joukkona.'),
(1672590,58,4,2,10,'Ruubenin leirin lippukunta leiriytyköön etelään päin osastoittain, ja Ruubenin jälkeläisten päämiehenä olkoon Elisur, Sedeurin poika;'),
(1672591,58,4,2,11,'hänen osastonsa, katselmuksessa olleet, on neljäkymmentäkuusi tuhatta viisisataa miestä.'),
(1672592,58,4,2,12,'Hänen viereensä leiriytyköön Simeonin sukukunta, ja Simeonin jälkeläisten päämiehenä olkoon Selumiel, Suurisaddain poika;'),
(1672593,58,4,2,13,'hänen osastonsa, katselmuksessa olleet, on viisikymmentäyhdeksän tuhatta kolmesataa miestä.'),
(1672594,58,4,2,14,'Sitten Gaadin sukukunta, ja Gaadin jälkeläisten päämiehenä olkoon Eljasaf, Reguelin poika;'),
(1672595,58,4,2,15,'hänen osastonsa, katselmuksessa olleet, on neljäkymmentäviisi tuhatta kuusisataa viisikymmentä miestä.'),
(1672596,58,4,2,16,'Ruubenin leirin katselmuksessa olleita on siis kaikkiaan sata viisikymmentäyksi tuhatta neljäsataa viisikymmentä miestä, osastoittain. He lähtekööt liikkeelle toisena joukkona.'),
(1672597,58,4,2,17,'Sitten lähtee liikkeelle ilmestysmaja ja leeviläisten leiri toisten leirien keskellä. Niinkuin olivat leiriytyneet, niin lähteköötkin, kukin kohdallansa, lippukunnittain.'),
(1672598,58,4,2,18,'Efraimin leirin lippukunta leiriytyköön länteen päin osastoittain, ja Efraimin jälkeläisten päämiehenä olkoon Elisama, Ammihudin poika;'),
(1672599,58,4,2,19,'hänen osastonsa, katselmuksessa olleet, on neljäkymmentä tuhatta viisisataa miestä.'),
(1672600,58,4,2,20,'Hänen viereensä leiriytyköön Manassen sukukunta, ja Manassen jälkeläisten päämiehenä olkoon Gamliel, Pedasurin poika;'),
(1672601,58,4,2,21,'hänen osastonsa, katselmuksessa olleet, on kolmekymmentäkaksi tuhatta kaksisataa miestä.'),
(1672602,58,4,2,22,'Sitten Benjaminin sukukunta, ja Benjaminin jälkeläisten päämiehenä olkoon Abidan, Gideonin poika;'),
(1672603,58,4,2,23,'hänen osastonsa, katselmuksessa olleet, on kolmekymmentäviisi tuhatta neljäsataa miestä.'),
(1672604,58,4,2,24,'Efraimin leirin katselmuksessa olleita on siis kaikkiaan satakahdeksan tuhatta ja sata miestä, osastoittain. He lähtekööt liikkeelle kolmantena joukkona.'),
(1672605,58,4,2,25,'Daanin leirin lippukunta leiriytyköön pohjoiseen päin osastoittain, ja Daanin jälkeläisten päämiehenä olkoon Ahieser, Ammisaddain poika;'),
(1672606,58,4,2,26,'hänen osastonsa, katselmuksessa olleet, on kuusikymmentäkaksi tuhatta seitsemänsataa miestä.'),
(1672607,58,4,2,27,'Hänen viereensä leiriytyköön Asserin sukukunta, ja Asserin jälkeläisten päämiehenä olkoon Pagiel, Okranin poika;'),
(1672608,58,4,2,28,'hänen osastonsa, katselmuksessa olleet, on neljäkymmentäyksi tuhatta viisisataa miestä.'),
(1672609,58,4,2,29,'Sitten Naftalin sukukunta, ja Naftalin jälkeläisten päämiehenä olkoon Ahira, Eenanin poika;'),
(1672610,58,4,2,30,'hänen osastonsa, katselmuksessa olleet, on viisikymmentäkolme tuhatta neljäsataa miestä.'),
(1672611,58,4,2,31,'Daanin leirin katselmuksessa olleita on siis kaikkiaan sata viisikymmentäseitsemän tuhatta kuusisataa miestä. He lähtekööt liikkeelle viimeisenä joukkona, lippukuntinensa."'),
(1672612,58,4,2,32,'Nämä olivat israelilaisten katselmuksessa olleet, perhekunnittain; eri leirien katselmuksessa olleita oli osastoittain kaikkiaan kuusisataakolme tuhatta viisisataa viisikymmentä miestä.'),
(1672613,58,4,2,33,'Mutta leeviläisten katselmusta ei pidetty samalla kuin muiden israelilaisten, sillä niin oli Herra Moosekselle käskyn antanut.'),
(1672614,58,4,2,34,'Ja israelilaiset tekivät kaiken, niinkuin Herra oli Moosekselle käskyn antanut. Niin he leiriytyivät lippukunnittain, ja niin he lähtivät liikkeelle kukin suvuittain ja perhekunnittain.'),
(1672615,58,4,3,1,'Tämä on kertomus Aaronin ja Mooseksen suvusta, siihen aikaan kun Herra puhui Moosekselle Siinain vuorella.'),
(1672616,58,4,3,2,'Nämä ovat Aaronin poikien nimet: Naadab, esikoinen, Abihu, Eleasar ja Iitamar.'),
(1672617,58,4,3,3,'Nämä ovat Aaronin poikien, voideltujen pappien, nimet, niiden, jotka olivat vihityt papinvirkaa toimittamaan.'),
(1672618,58,4,3,4,'Mutta Naadab ja Abihu kuolivat Herran edessä tuodessaan vierasta tulta Herran eteen Siinain erämaassa; ja heillä ei ollut poikia. Niin Eleasar ja Iitamar toimittivat papinvirkaa isänsä Aaronin edessä.'),
(1672619,58,4,3,5,'Ja Herra puhui Moosekselle sanoen:'),
(1672620,58,4,3,6,'"Tuo Leevin sukukunta esille ja aseta se pappi Aaronin eteen palvelemaan häntä.'),
(1672621,58,4,3,7,'Ja he hoitakoot sekä hänen että koko kansan tehtäviä ilmestysmajan edustalla, toimittakoot palvelusta asumuksessa.'),
(1672622,58,4,3,8,'Ja he hoitakoot kaikkea ilmestysmajan kalustoa ja israelilaisten tehtäviä, toimittakoot palvelusta asumuksessa.'),
(1672623,58,4,3,9,'Niin on sinun annettava leeviläiset Aaronille ja hänen pojilleen; antakoot israelilaiset heidät hänen haltuunsa, hänelle palvelijoiksi.'),
(1672624,58,4,3,10,'Mutta Aaronin ja hänen poikiensa käske hoitaa papinvirkansa. Syrjäinen, joka siihen ryhtyy, surmattakoon."'),
(1672625,58,4,3,11,'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672626,58,4,3,12,'"Katso, minä itse olen ottanut leeviläiset israelilaisten keskuudesta israelilaisten kaikkien esikoisten sijaan, kaiken sijaan, joka avaa äidinkohdun; leeviläiset ovat siis tulleet minun omikseni.'),
(1672627,58,4,3,13,'Sillä minun omani on jokainen esikoinen. Sinä päivänä, jona minä surmasin kaikki Egyptin maan esikoiset, minä pyhitin itselleni kaikki Israelin esikoiset, sekä ihmisten että karjan; minun omani ne ovat. Minä olen Herra."'),
(1672628,58,4,3,14,'Ja Herra puhui Moosekselle Siinain erämaassa sanoen:'),
(1672629,58,4,3,15,'"Pidä leeviläisten katselmus perhekunnittain ja suvuittain; kaikista miehenpuolista, kuukauden ikäisistä ja sitä vanhemmista, pidä katselmus".'),
(1672630,58,4,3,16,'Ja Mooses piti heistä katselmuksen Herran käskyn mukaan, niinkuin hänelle oli määrätty.'),
(1672631,58,4,3,17,'Ja nämä olivat Leevin poikien nimet: Geerson, Kehat ja Merari.'),
(1672632,58,4,3,18,'Ja nämä olivat Geersonin poikien nimet, suvuittain: Libni ja Siimei.'),
(1672633,58,4,3,19,'Ja Kehatin pojat olivat, suvuittain, Amram, Jishar, Hebron ja Ussiel.'),
(1672634,58,4,3,20,'Ja Merarin pojat olivat, suvuittain, Mahli ja Muusi. Nämä olivat Leevin suvut perhekunnittain.'),
(1672635,58,4,3,21,'Geersonista polveutuivat libniläisten suku ja siimeiläisten suku. Nämä olivat geersonilaisten suvut.'),
(1672636,58,4,3,22,'Katselmuksessa olleita oli heitä, kaikkien miehenpuolten, kuukauden ikäisten ja sitä vanhempien, lukumäärän mukaan - näitä katselmuksessa olleita oli seitsemäntuhatta viisisataa miestä.'),
(1672637,58,4,3,23,'Geersonilaisten suvut leiriytyivät asumuksen taakse länteen päin.'),
(1672638,58,4,3,24,'Ja geersonilaisten perhekunta-päämies oli Eljasaf, Laaelin poika.'),
(1672639,58,4,3,25,'Geersonin poikien hoidettavana ilmestysmajassa oli asumus ja teltta, sen peite, ilmestysmajan oven uudin'),
(1672640,58,4,3,26,'ja asumusta ja alttaria ympäröivän esipihan ympärysverhot ja sen portin uudin sekä sen köydet - kaikki ne palvelustehtävineen.'),
(1672641,58,4,3,27,'Kehatista polveutuivat amramilaisten suku, jisharilaisten suku, hebronilaisten suku ja ussielilaisten suku. Nämä olivat kehatilaisten suvut.'),
(1672642,58,4,3,28,'Miehenpuolten, kuukauden ikäisten ja sitä vanhempien, lukumäärän mukaan oli heitä kaikkiaan kahdeksantuhatta kuusisataa, jotka hoitivat pyhäkössä suoritettavia tehtäviä.'),
(1672643,58,4,3,29,'Kehatilaisten suvut leiriytyivät asumuksen sivulle etelään päin.'),
(1672644,58,4,3,30,'Ja kehatilaisten sukujen perhekunta-päämies oli Elisafan, Ussielin poika.'),
(1672645,58,4,3,31,'Heidän hoidettavanaan oli arkki, pöytä, seitsenhaarainen lamppu, alttarit ja pyhä kalusto, jota jumalanpalveluksessa käytettiin, ynnä esirippu - kaikkine palvelustehtävineen.'),
(1672646,58,4,3,32,'Ja leeviläisten päämiesten esimies oli Eleasar, pappi Aaronin poika; hän oli niiden päällysmies, jotka hoitivat tehtäviä pyhäkössä.'),
(1672647,58,4,3,33,'Merarista polveutuivat mahlilaisten suku ja muusilaisten suku. Nämä olivat Merarin suvut.'),
(1672648,58,4,3,34,'Katselmuksessa olleita oli heitä kaikkien miehenpuolten, kuukauden ikäisten ja sitä vanhempien, lukumäärän mukaan kuusituhatta kaksisataa.'),
(1672649,58,4,3,35,'Ja Merarin sukujen perhekunta-päämies oli Suuriel, Abihailin poika. He leiriytyivät asumuksen sivulle pohjoiseen päin.'),
(1672650,58,4,3,36,'Ja Merarin poikien hoidettavaksi oli uskottu asumuksen laudat, poikkitangot, pylväät ja jalustat sekä kaikki sen kalusto - kaikki ne palvelustehtävineen;'),
(1672651,58,4,3,37,'niinikään ympärillä olevan esipihan pylväät jalustoinensa, vaarnoinensa ja köysinensä.'),
(1672652,58,4,3,38,'Mutta asumuksen eteen, itään päin, ilmestysmajan eteen, auringon nousuun päin, leiriytyivät Mooses ja Aaron ynnä hänen poikansa; heidän hoidettavanaan oli pyhäkkö, se, mikä oli israelilaisten hoidettavana. Mutta syrjäinen, joka ryhtyi siihen, oli surmattava.'),
(1672653,58,4,3,39,'Katselmuksessa olleita leeviläisiä, joista Mooses ja Aaron Herran käskyn mukaan pitivät katselmuksen suvuittain, kaikkia miehenpuolia, kuukauden ikäisiä ja sitä vanhempia, oli kaikkiaan kaksikymmentäkaksi tuhatta.'),
(1672654,58,4,3,40,'Ja Herra sanoi Moosekselle: "Katsasta kaikki israelilaisten miehenpuoliset esikoiset, kuukauden ikäisistä ja sitä vanhemmista, ja laske heidän nimiensä lukumäärä.'),
(1672655,58,4,3,41,'Ja ota minulle - minä olen Herra - leeviläiset israelilaisten kaikkien esikoisten sijaan sekä myös leeviläisten karja israelilaisten karjan kaikkien esikoisten sijaan."'),
(1672656,58,4,3,42,'Ja Mooses katsasti, niinkuin Herra oli häntä käskenyt, kaikki israelilaisten esikoiset.'),
(1672657,58,4,3,43,'Ja katselmuksessa olleita oli heitä, kaikkia miehenpuolisia esikoisia, nimien lukumäärän mukaan, kuukauden ikäisiä ja sitä vanhempia, kaikkiaan kaksikymmentäkaksi tuhatta kaksisataa seitsemänkymmentä kolme.'),
(1672658,58,4,3,44,'Ja Herra puhui Moosekselle sanoen:'),
(1672659,58,4,3,45,'"Ota leeviläiset israelilaisten kaikkien esikoisten sijaan ja leeviläisten karja heidän karjansa sijaan, ja niin leeviläiset tulevat minun omikseni. Minä olen Herra.'),
(1672660,58,4,3,46,'Mutta lunastukseksi noista kahdestasadasta seitsemästäkymmenestä kolmesta, jonka verran israelilaisten esikoisia on yli leeviläisten määrän,'),
(1672661,58,4,3,47,'ota miestä kohti viisi sekeliä, ota ne pyhäkkösekelin painon mukaan, kaksikymmentä geeraa laskettuna sekeliin.'),
(1672662,58,4,3,48,'Ja anna se raha Aaronille ja hänen pojillensa lunastukseksi niistä, joita on yli leeviläisten määrän."'),
(1672663,58,4,3,49,'Ja Mooses otti lunastushinnan niistä, joita oli yli leeviläisillä lunastettujen määrän.'),
(1672664,58,4,3,50,'Israelilaisten esikoisista hän otti tämän rahan, tuhat kolmesataa kuusikymmentä viisi sekeliä pyhäkkösekelin painon mukaan.'),
(1672665,58,4,3,51,'Ja Mooses antoi sen lunastushinnan Aaronille ja hänen pojillensa Herran käskyn mukaan, niinkuin Herra oli Moosesta käskenyt.'),
(1672666,58,4,4,1,'Ja Herra puhui Moosekselle ja Aaronille sanoen:'),
(1672667,58,4,4,2,'"Laske Leevin jälkeläisten joukosta Kehatin jälkeläisten lukumäärä suvuittain ja perhekunnittain,'),
(1672668,58,4,4,3,'kolmikymmenvuotiset ja sitä vanhemmat aina viisikymmenvuotisiin saakka, kaikki, joiden on palveltava toimittamalla askareita ilmestysmajassa.'),
(1672669,58,4,4,4,'Kehatin poikien palvelustehtävänä ilmestysmajassa olkoon tämä: huolenpito korkeasti-pyhistä.'),
(1672670,58,4,4,5,'Ja leirin liikkeelle lähtiessä menkööt Aaron ja hänen poikansa ja päästäkööt alas esiripun sekä peittäkööt sillä lain arkin;'),
(1672671,58,4,4,6,'sitten he pankoot sen päälle sireeninnahkapeitteen ja levittäkööt päällimmäiseksi vaatteen, kokonaan punasinisistä langoista tehdyn, ja asettakoot paikoilleen sen korennot.'),
(1672672,58,4,4,7,'Ja näkyleipäpöydälle he levittäkööt punasinisen vaatteen ja pankoot sen päälle vadit ja kupit, maljat ja juomauhrikannut; ja ainainen leipä olkoon myös sen päällä.'),
(1672673,58,4,4,8,'Sitten he levittäkööt näiden päälle helakanpunaisen vaatteen ja peittäkööt sen sireeninnahkapeitteellä ja asettakoot paikoilleen sen korennot.'),
(1672674,58,4,4,9,'Ja he ottakoot punasinisen vaatteen ja peittäkööt seitsenhaaraisen lampun lamppuineen, lamppusaksineen, karstakuppeineen ja kaikkine öljyastioineen, joita sen hoitamisessa käytetään.'),
(1672675,58,4,4,10,'Ja he käärikööt sen ja kaiken sen kaluston sireeninnahkapeitteeseen ja pankoot kantopaareille.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672676,58,4,4,11,'Ja kultaiselle alttarille he levittäkööt punasinisen vaatteen ja peittäkööt sen sireeninnahkapeitteellä ja asettakoot paikoilleen sen korennot.'),
(1672677,58,4,4,12,'Ja he ottakoot kaiken jumalanpalveluskaluston, jota pyhäkössä käytetään, ja käärikööt sen punasiniseen vaatteeseen ja peittäkööt sen sireeninnahkapeitteellä ja pankoot kantopaareille.'),
(1672678,58,4,4,13,'Ja he puhdistakoot tuhasta alttarin sekä levittäkööt sen päälle purppuranpunaisen vaatteen'),
(1672679,58,4,4,14,'ja pankoot sen päälle kaiken kaluston, jota alttarilla käytetään: hiilipannut, haarukat, lapiot ja maljat, kaiken alttarikaluston; ja levittäkööt sen päälle sireeninnahkapeitteen ja asettakoot paikoilleen sen korennot.'),
(1672680,58,4,4,15,'Ja kun leirin lähtiessä liikkeelle Aaron ja hänen poikansa ovat valmiiksi peittäneet pyhäkön ja pyhäkön kaiken kaluston, niin tulkoot Kehatin pojat kantamaan, mutta älkööt koskeko pyhäkköön, etteivät kuolisi. Tämä on ilmestysmajasta se, mikä on Kehatin poikien kannettava.'),
(1672681,58,4,4,16,'Ja Eleasar, pappi Aaronin poika, pitäköön huolen seitsenhaaraisen lampun öljystä, hyvänhajuisesta suitsukkeesta, jokapäiväisestä ruokauhrista ja voiteluöljystä; hän pitäköön huolen koko asumuksesta ja kaikesta, mitä siinä on, pyhäköstä ja sen kalustosta."'),
(1672682,58,4,4,17,'Ja Herra puhui Moosekselle ja Aaronille sanoen:'),
(1672683,58,4,4,18,'"Älkää päästäkö kehatilaisten sukuhaaraa häviämään leeviläisten joukosta.'),
(1672684,58,4,4,19,'Näin siis tehkää heille, että he saisivat elää eivätkä kuolisi lähestyessään kaikkeinpyhintä: Aaron ja hänen poikansa menkööt ja asettakoot heidät jokaisen tekemään palvelustehtäväänsä ja kantamaan kannettavaansa;'),
(1672685,58,4,4,20,'mutta älkööt nämä menkö katsomaan pyhiä esineitä, älkööt silmänräpäykseksikään, etteivät kuolisi."'),
(1672686,58,4,4,21,'Ja Herra puhui Moosekselle sanoen:'),
(1672687,58,4,4,22,'"Laske myöskin Geersonin jälkeläisten lukumäärä perhekunnittain ja suvuittain;'),
(1672688,58,4,4,23,'pidä kolmikymmenvuotisten katselmus ja sitä vanhempien, viisikymmenvuotisiin asti, kaikkien, joiden on palveltava toimittamalla palvelusta ilmestysmajassa.'),
(1672689,58,4,4,24,'Geersonilaissukujen tehtävänä palveltaessa ja kannettaessa olkoon tämä:'),
(1672690,58,4,4,25,'he kantakoot asumuksen telttakankaan kaistat ja ilmestysmajan, sen peitteen ja sireeninnahkapeitteen, joka on sen päällä päällimmäisenä, sekä ilmestysmajan oven uutimen'),
(1672691,58,4,4,26,'ja asumusta ja alttaria ympäröivän esipihan ympärysverhot ja sen portin uutimen sekä niiden köydet ja kaiken niiden hoitamiseen tarvittavan kaluston; he toimittakoot kaiken, mitä siinä on tehtävä.'),
(1672692,58,4,4,27,'Aaronin ja hänen poikiensa käskyn mukaisesti tapahtukoon kaikki geersonilaisten palvelus, mitä hyvänsä he kantavat ja toimittavatkin, ja antakaa heidän hoitoonsa kaikki heidän kannettavansa.'),
(1672693,58,4,4,28,'Tämä on geersonilaissukujen palvelustehtävä ilmestysmajassa; ja he hoitakoot toimensa Iitamarin, pappi Aaronin pojan, johdolla.'),
(1672694,58,4,4,29,'Pidä Merarin jälkeläisten katselmus suvuittain ja perhekunnittain;'),
(1672695,58,4,4,30,'pidä kolmikymmenvuotisten katselmus ja sitä vanhempien, viisikymmenvuotisiin asti, kaikkien, joiden on palveltava toimittamalla palvelusta ilmestysmajassa.'),
(1672696,58,4,4,31,'Ja nämä ovat uskotut heille kannettaviksi heidän toimittaessaan palvelusta ilmestysmajassa: asumuksen laudat, sen poikkitangot, pylväät ja jalustat'),
(1672697,58,4,4,32,'sekä ympärillä olevan esipihan pylväät jalustoineen, vaarnoineen ja köysineen, kaikki niiden kalusto ja kaikki, mitä tarvitaan niiden hoitamiseen. Ja antakaa heidän hoitoonsa nimeltä mainittuina ne kalut, joiden kantaminen on heidän tehtävänään.'),
(1672698,58,4,4,33,'Tämä on merarilaissukujen palvelustehtävä, mitä hyvänsä he toimittavatkin ilmestysmajassa Iitamarin, pappi Aaronin pojan, johdolla."'),
(1672699,58,4,4,34,'Ja Mooses ja Aaron sekä kansan päämiehet pitivät Kehatin jälkeläisten katselmuksen suvuittain ja perhekunnittain,'),
(1672700,58,4,4,35,'kolmikymmenvuotisten ja sitä vanhempien, aina viisikymmenvuotisiin asti, kaikkien, joiden oli palveltava toimittamalla palvelusta ilmestysmajassa.'),
(1672701,58,4,4,36,'Ja heitä, suvuittain katselmuksessa olleita, oli kaksituhatta seitsemänsataa viisikymmentä.'),
(1672702,58,4,4,37,'Näin paljon oli kehatilaissuvuista katselmuksessa olleita, kaikkia ilmestysmajassa palvelevia, joiden katselmuksen Mooses ja Aaron pitivät sen käskyn mukaisesti, jonka Herra oli Mooseksen kautta antanut.'),
(1672703,58,4,4,38,'Ja Geersonin jälkeläisiä, joiden katselmus pidettiin suvuittain ja perhekunnittain,'),
(1672704,58,4,4,39,'kolmikymmenvuotisia ja sitä vanhempia viisikymmenvuotisiin asti, kaikkia, joiden oli palveltava toimittamalla palvelusta ilmestysmajassa,'),
(1672705,58,4,4,40,'näitä katselmuksessa olleita oli suvuittain ja perhekunnittain kaksituhatta kuusisataa kolmekymmentä.'),
(1672706,58,4,4,41,'Näin paljon oli geersonilaisten suvuista katselmuksessa olleita, kaikkia ilmestysmajassa palvelevia, joiden katselmuksen Mooses ja Aaron pitivät Herran käskyn mukaisesti.'),
(1672707,58,4,4,42,'Ja merarilaisten suvuista oli niitä, joiden katselmus pidettiin suvuittain ja perhekunnittain,'),
(1672708,58,4,4,43,'kolmikymmenvuotisia ja sitä vanhempia viisikymmenvuotisiin asti, kaikkia, joiden oli palveltava toimittamalla palvelusta ilmestysmajassa,'),
(1672709,58,4,4,44,'näitä, suvuittain katselmuksessa olleita, oli kolmetuhatta kaksisataa.'),
(1672710,58,4,4,45,'Näin paljon oli merarilaisten suvuista katselmuksessa olleita, joista Mooses ja Aaron pitivät katselmuksen sen käskyn mukaisesti, jonka Herra oli Mooseksen kautta antanut.'),
(1672711,58,4,4,46,'Kaikkia katselmuksessa olleita leeviläisiä, joiden katselmuksen Mooses ja Aaron ja Israelin päämiehet pitivät suvuittain ja perhekunnittain,'),
(1672712,58,4,4,47,'kolmikymmenvuotisia ja sitä vanhempia, viisikymmenvuotisiin asti, kaikkia, joiden oli palveltava toimittamalla palvelusta ja kantamistyötä ilmestysmajassa,'),
(1672713,58,4,4,48,'näitä katselmuksessa olleita oli kahdeksantuhatta viisisataa kahdeksankymmentä.'),
(1672714,58,4,4,49,'Sen käskyn mukaisesti, jonka Herra oli Mooseksen kautta antanut, määrättiin jokaiselle heistä oma palvelustehtävänsä ja kantamistyönsä. Tämän katselmuksen Mooses piti, niinkuin Herra oli häntä käskenyt.'),
(1672715,58,4,5,1,'Ja Herra puhui Moosekselle sanoen:'),
(1672716,58,4,5,2,'"Käske israelilaisten karkoittaa leiristä jokainen pitalinen ja jokainen vuotoa sairastava ja jokainen kuolleesta saastunut.'),
(1672717,58,4,5,3,'Karkoittakaa sellaiset, sekä miehet että naiset, leirin ulkopuolelle, etteivät he saastuttaisi leiriään, jossa minä asun heidän keskellänsä."'),
(1672718,58,4,5,4,'Ja israelilaiset tekivät niin ja karkoittivat heidät leirin ulkopuolelle; niinkuin Herra oli puhunut Moosekselle, niin israelilaiset tekivät.'),
(1672719,58,4,5,5,'Ja Herra puhui Moosekselle sanoen:'),
(1672720,58,4,5,6,'"Puhu israelilaisille: Jos mies tai nainen tekee rikkomuksen minkä tahansa, jonka ihminen tekee menettelemällä uskottomasti Herraa kohtaan, ja niin joutuu vikapääksi,'),
(1672721,58,4,5,7,'tunnustakoon hän rikkomuksensa, jonka on tehnyt, ja maksakoon velkansa täyteen määrään sekä pankoon siihen lisäksi viidennen osan sen arvosta ja antakoon sen sille, jolle hän on velkaa.'),
(1672722,58,4,5,8,'Mutta jos hänellä ei ole sukulunastajaa, jolle velka olisi maksettava, maksettakoon velka Herralle, se on papille, ja sitä paitsi sovitus-oinas, jolla toimitetaan syynalaiselle sovitus.'),
(1672723,58,4,5,9,'Ja jokainen anti, mikä hyvänsä israelilaisten papille tuomista pyhistä lahjoista, olkoon papin oma.'),
(1672724,58,4,5,10,'Ja jokaisen pyhät lahjat olkoot papin omat; mitä joku antaa papille, se olkoon papin oma."'),
(1672725,58,4,5,11,'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672726,58,4,5,12,'"Puhu israelilaisille ja sano heille: jos jonkun miehen vaimo on pettänyt miehensä ja ollut hänelle uskoton'),
(1672727,58,4,5,13,'ja joku on maannut hänen kanssaan eikä hänen miehensä ole saanut sitä tietää ja vaimo on saanut sen salatuksi, vaikka hän on saastuttanut itsensä, eikä ole todistajaa häntä vastaan eikä häntä ole teosta tavattu,'),
(1672728,58,4,5,14,'mutta luulevaisuuden henki on vallannut miehen ja hän luulee vaimoansa, joka onkin saastuttanut itsensä, tahi jos luulevaisuuden henki on vallannut miehen ja hän luulee vaimoansa, vaikka tämä ei ole saastuttanut itseänsä,'),
(1672729,58,4,5,15,'niin tuokoon mies vaimonsa papin eteen ja uhrilahjana hänen puolestaan kymmenennen osan eefa-mittaa ohrajauhoja, mutta älköön hän sen päälle vuodattako öljyä älköönkä panko suitsuketta, sillä se on luulevaisuusuhri, muistutusuhri, joka johdattaa muistoon pahan teon.'),
(1672730,58,4,5,16,'Ja pappi tuokoon vaimon ja asettakoon hänet Herran eteen.'),
(1672731,58,4,5,17,'Ja pappi ottakoon pyhää vettä saviastiaan, ja sitten pappi ottakoon tomua asumuksen lattialta ja pankoon veteen.'),
(1672732,58,4,5,18,'Ja pappi asettakoon vaimon Herran eteen, päästäköön vaimon tukan hajalle ja asettakoon hänen käsiinsä muistutusuhrin, se on luulevaisuusuhrin, ja papin kädessä olkoon katkera kirovesi.'),
(1672733,58,4,5,19,'Ja pappi vannottakoon vaimoa ja sanokoon hänelle: ''Jos ei kukaan ole maannut sinun kanssasi etkä ole pettänyt miestäsi saastuttamalla itseäsi, niin älköön tämä katkera kirovesi sinua vahingoittako.'),
(1672734,58,4,5,20,'Mutta jos olet pettänyt miehesi ja saastuttanut itsesi ja joku muu kuin miehesi on maannut sinun kanssasi,'),
(1672735,58,4,5,21,'niin'' - pappi vannottakoon vaimoa kirovalalla ja pappi sanokoon vaimolle - ''tehköön Herra sinun nimesi kiroukseksi ja sadatukseksi sinun kansasi keskuudessa, kuihduttakoon Herra sinun lanteesi ja paisuttakoon vatsasi;'),
(1672736,58,4,5,22,'menköön tämä kirovesi sinun sisuksiisi, niin että vatsasi paisuu ja lanteesi kuihtuvat.'' Ja vaimo sanokoon: ''Amen, Amen''.'),
(1672737,58,4,5,23,'Ja pappi kirjoittakoon nämä kiroukset ja huuhtokoon kirjoituksen kiroveteen.'),
(1672738,58,4,5,24,'Sitten hän juottakoon vaimolla sen katkeran kiroveden, ja menköön kirovesi häneen, tuskaksi hänelle.'),
(1672739,58,4,5,25,'Ja pappi ottakoon vaimon kädestä luulevaisuusuhrin ja toimittakoon uhrin heilutuksen Herran edessä ja tuokoon sen alttarille.'),
(1672740,58,4,5,26,'Ja pappi ottakoon uhrista kourallisen alttariuhriosaksi ja polttakoon sen alttarilla ja juottakoon sitten vaimolla veden.'),
(1672741,58,4,5,27,'Ja kun hän on juottanut vaimolla veden, niin, jos hän on saastuttanut itsensä ja ollut miehelleen uskoton, menee kirovesi häneen, hänelle tuskaksi, ja hänen vatsansa paisuu ja lanteensa kuihtuvat, ja vaimon nimi tulee kiroukseksi hänen kansansa keskuudessa.'),
(1672742,58,4,5,28,'Mutta jos vaimo ei ole saastuttanut itseänsä, vaan on puhdas, ei hän vahingoitu, vaan pysyy hedelmällisenä.'),
(1672743,58,4,5,29,'Tämä on laki luulevaisuudesta. Jos vaimo pettää miehensä ja saastuttaa itsensä,'),
(1672744,58,4,5,30,'tai jos jonkun valtaa luulevaisuuden henki ja hän luulee vaimoansa, niin hän asettakoon vaimonsa Herran eteen, ja pappi tehköön vaimolle kaiken tämän lain mukaan.'),
(1672745,58,4,5,31,'Niin mies olkoon syyllisyydestä vapaa, mutta vaimo kantakoon syyllisyytensä."'),
(1672746,58,4,6,1,'Ja Herra puhui Moosekselle sanoen:'),
(1672747,58,4,6,2,'"Puhu israelilaisille ja sano heille: Kun mies tai nainen tekee nasiirilupauksen vihkiytyäksensä Herralle,'),
(1672748,58,4,6,3,'niin pidättyköön hän viinistä ja väkijuomasta; älköön juoko hapanviiniä tai hapanta juomaa älköönkä mitään viinirypäleen mehua; älköön syökö tuoreita älköönkä kuivia rypäleitä.'),
(1672749,58,4,6,4,'Niin kauan kuin hänen nasiirilupauksensa kestää, älköön hän syökö mitään, mikä viiniköynnöksestä saadaan, älköön edes raakiloita tai köynnösten versoja.'),
(1672750,58,4,6,5,'Niin kauan kuin hänen nasiirilupauksensa kestää, älköön partaveitsi koskettako hänen päätänsä. Kunnes kuluu umpeen aika, joksi hän on vihkiytynyt Herralle, hän olkoon pyhä ja kasvattakoon päänsä hiukset pitkiksi.'),
(1672751,58,4,6,6,'Niin kauan kuin hän on Herralle vihkiytynyt, älköön hän menkö kuolleen luo.'),
(1672752,58,4,6,7,'Älköön hän saastuko edes isästänsä tai äidistänsä, veljestänsä tai sisarestansa heidän kuoltuaan, sillä hänen päässään on Jumalalle-vihkiytymisen merkki.'),
(1672753,58,4,6,8,'Niin kauan kuin hänen nasiirilupauksensa kestää, hän on pyhä Herralle.'),
(1672754,58,4,6,9,'Jos joku odottamatta, äkkiarvaamatta kuolee hänen läheisyydessään ja hän niin saastuttaa vihityn päänsä, niin hän ajattakoon hiuksensa puhdistuspäivänään, seitsemäntenä päivänä hän ajattakoon ne.'),
(1672755,58,4,6,10,'Ja kahdeksantena päivänä hän tuokoon kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa papille ilmestysmajan ovelle.'),
(1672756,58,4,6,11,'Ja pappi uhratkoon toisen syntiuhriksi ja toisen polttouhriksi ja toimittakoon hänelle sovituksen kuolleen tähden tulleesta rikkomuksesta ja pyhittäköön uudelleen hänen päänsä sinä päivänä.'),
(1672757,58,4,6,12,'Ja hän vihkiytyköön uudelleen Herralle nasiirilupauksensa ajaksi ja tuokoon vuoden vanhan karitsan vikauhriksi. Mutta kulunut aika jääköön lukuunottamatta, koska hän saastutti vihkimyksensä.'),
(1672758,58,4,6,13,'Ja tämä on nasiirilaki: Sinä päivänä, jona hänen nasiirilupauksensa aika on kulunut umpeen, tuotakoon hänet ilmestysmajan ovelle,'),
(1672759,58,4,6,14,'ja hän tuokoon uhrilahjanansa Herralle vuoden vanhan virheettömän karitsan polttouhriksi ja vuoden vanhan virheettömän uuhikaritsan syntiuhriksi sekä virheettömän oinaan yhteysuhriksi'),
(1672760,58,4,6,15,'ynnä korillisen lestyistä jauhoista leivottuja happamattomia leipiä, öljyyn leivottuja kakkuja ja öljyllä voideltuja happamattomia ohukaisia sekä niihin kuuluvan ruoka- ja juomauhrin.'),
(1672761,58,4,6,16,'Ja pappi tuokoon ne Herran eteen ja toimittakoon hänen syntiuhrinsa ja polttouhrinsa.'),
(1672762,58,4,6,17,'Mutta oinaan hän uhratkoon yhteysuhriksi Herralle ynnä korillisen happamattomia leipiä; ja pappi toimittakoon myös hänen ruoka- ja juomauhrinsa.'),
(1672763,58,4,6,18,'Ja nasiiri ajattakoon hiuksensa, vihkiytymisensä merkin, ilmestysmajan ovella ja ottakoon päänsä hiukset, vihkiytymisensä merkin, ja pankoon ne tuleen, joka palaa yhteysuhrin alla.'),
(1672764,58,4,6,19,'Ja pappi ottakoon oinaan keitetyn lavan ja korista happamattoman kakun sekä happamattoman ohukaisen ja pankoon ne nasiirin käsiin, senjälkeen kuin tämä on ajattanut pois vihkiytymisensä merkin.'),
(1672765,58,4,6,20,'Ja pappi toimittakoon niiden heilutuksen Herran edessä. Se olkoon pyhä lahja papille, annettava heilutetun rintalihan ja anniksi annetun reiden lisäksi. Sen jälkeen nasiiri saakoon juoda viiniä.'),
(1672766,58,4,6,21,'Tämä on laki nasiirista, joka tekee lupauksen, ja hänen uhrilahjastaan, jonka hän uhraa Herralle vihkiytymisensä tähden, sen lisäksi, mitä hän muuten saa hankituksi. Tekemänsä lupauksen mukaan hän menetelköön näin, noudattaen vihkiytymistään koskevaa lakia."'),
(1672767,58,4,6,22,'Ja Herra puhui Moosekselle sanoen:'),
(1672768,58,4,6,23,'"Puhu Aaronille ja hänen pojillensa ja sano: Siunatessanne israelilaisia sanokaa heille:'),
(1672769,58,4,6,24,'Herra siunatkoon sinua ja varjelkoon sinua;'),
(1672770,58,4,6,25,'Herra valistakoon kasvonsa sinulle ja olkoon sinulle armollinen;'),
(1672771,58,4,6,26,'Herra kääntäköön kasvonsa sinun puoleesi ja antakoon sinulle rauhan.'),
(1672772,58,4,6,27,'Näin he laskekoot minun nimeni israelilaisten ylitse, ja minä siunaan heitä."'),
(1672773,58,4,7,1,'Kun nyt Mooses oli saanut pystytetyksi asumuksen ja oli voidellut sen ja pyhittänyt sen kaikkine kalustoineen ynnä alttarin kaikkine kalustoineen sekä voidellut ja pyhittänyt ne,'),
(1672774,58,4,7,2,'niin Israelin ruhtinaat, perhekuntien päämiehet, nimittäin heimoruhtinaat, katselmuksessa olleiden esimiehet,'),
(1672775,58,4,7,3,'toivat lahjanansa Herran eteen kuudet katetut vaunut ja kaksitoista raavasta, kaksi ruhtinasta aina yhdet vaunut ja kukin ruhtinas härän; ne he toivat asumuksen eteen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672776,58,4,7,4,'Ja Herra sanoi Moosekselle näin:'),
(1672777,58,4,7,5,'"Ota ne heiltä ilmestysmajan palveluksessa käytettäviksi ja anna ne leeviläisille, kullekin hänen palvelustehtävänsä mukaisesti".'),
(1672778,58,4,7,6,'Ja Mooses otti vastaan vaunut ja raavaat ja antoi ne leeviläisille.'),
(1672779,58,4,7,7,'Kahdet vaunut ja neljä raavasta hän antoi Geersonin pojille heidän palvelustehtävänsä mukaisesti.'),
(1672780,58,4,7,8,'Ja neljät vaunut sekä kahdeksan raavasta hän antoi Merarin pojille sen palvelustehtävän mukaisesti, joka heidän oli suoritettava Iitamarin, pappi Aaronin pojan, johdolla.'),
(1672781,58,4,7,9,'Mutta Kehatin pojille hän ei antanut mitään, koska heidän hoidettavinaan oli pyhät esineet, joita heidän oli olallaan kannettava.'),
(1672782,58,4,7,10,'Ja ruhtinaat toivat vihkiäislahjoja alttaria varten sinä päivänä, jona se voideltiin; ja ruhtinaat toivat lahjansa alttarin eteen.'),
(1672783,58,4,7,11,'Ja Herra sanoi Moosekselle: "Ruhtinaat tuokoot yksitellen, kukin päivänänsä, uhrilahjansa alttarin vihkiäisiin".'),
(1672784,58,4,7,12,'Ensimmäisenä päivänä toi uhrilahjansa Nahson, Amminadabin poika, Juudan sukukunnasta.'),
(1672785,58,4,7,13,'Ja hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, ja hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,'),
(1672786,58,4,7,14,'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,'),
(1672787,58,4,7,15,'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,'),
(1672788,58,4,7,16,'kauris syntiuhriksi'),
(1672789,58,4,7,17,'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Nahsonin, Amminadabin pojan, uhrilahja.'),
(1672790,58,4,7,18,'Toisena päivänä Netanel, Suuarin poika, Isaskarin ruhtinas, toi uhrilahjansa.'),
(1672791,58,4,7,19,'Hän toi uhrilahjanansa hopeavadin, sadan kolmenkymmenen sekelin painoisen, hopeamaljan, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,'),
(1672792,58,4,7,20,'kymmenen sekelin painoisen kultakupin, täynnä suitsuketta,'),
(1672793,58,4,7,21,'mullikan, oinaan ja vuoden vanhan karitsan polttouhriksi,'),
(1672794,58,4,7,22,'kauriin syntiuhriksi'),
(1672795,58,4,7,23,'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Netanelin, Suuarin pojan, uhrilahja.'),
(1672796,58,4,7,24,'Kolmantena päivänä Sebulonin jälkeläisten ruhtinas Eliab, Heelonin poika:'),
(1672797,58,4,7,25,'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,'),
(1672798,58,4,7,26,'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,'),
(1672799,58,4,7,27,'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,'),
(1672800,58,4,7,28,'kauris syntiuhriksi'),
(1672801,58,4,7,29,'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Eliabin, Heelonin pojan, uhrilahja.'),
(1672802,58,4,7,30,'Neljäntenä päivänä Ruubenin jälkeläisten ruhtinas Elisur, Sedeurin poika:'),
(1672803,58,4,7,31,'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,'),
(1672804,58,4,7,32,'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,'),
(1672805,58,4,7,33,'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,'),
(1672806,58,4,7,34,'kauris syntiuhriksi'),
(1672807,58,4,7,35,'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Elisurin, Sedeurin pojan, uhrilahja.'),
(1672808,58,4,7,36,'Viidentenä päivänä Simeonin jälkeläisten ruhtinas Selumiel, Suurisaddain poika:'),
(1672809,58,4,7,37,'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,'),
(1672810,58,4,7,38,'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,'),
(1672811,58,4,7,39,'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,'),
(1672812,58,4,7,40,'kauris syntiuhriksi'),
(1672813,58,4,7,41,'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Selumielin, Suurisaddain pojan, uhrilahja.'),
(1672814,58,4,7,42,'Kuudentena päivänä Gaadin jälkeläisten ruhtinas Eljasaf, Deguelin poika:'),
(1672815,58,4,7,43,'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,'),
(1672816,58,4,7,44,'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,'),
(1672817,58,4,7,45,'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,'),
(1672818,58,4,7,46,'kauris syntiuhriksi'),
(1672819,58,4,7,47,'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Eljasafin, Deguelin pojan, uhrilahja.'),
(1672820,58,4,7,48,'Seitsemäntenä päivänä Efraimin jälkeläisten ruhtinas Elisama, Ammihudin poika:'),
(1672821,58,4,7,49,'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,'),
(1672822,58,4,7,50,'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,'),
(1672823,58,4,7,51,'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,'),
(1672824,58,4,7,52,'kauris syntiuhriksi'),
(1672825,58,4,7,53,'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Elisaman, Ammihudin pojan, uhrilahja.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672826,58,4,7,54,'Kahdeksantena päivänä Manassen jälkeläisten ruhtinas Gamliel, Pedasurin poika:'),
(1672827,58,4,7,55,'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,'),
(1672828,58,4,7,56,'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,'),
(1672829,58,4,7,57,'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,'),
(1672830,58,4,7,58,'kauris syntiuhriksi'),
(1672831,58,4,7,59,'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Gamlielin, Pedasurin pojan, uhrilahja.'),
(1672832,58,4,7,60,'Yhdeksäntenä päivänä Benjaminin jälkeläisten ruhtinas Abidan, Gideonin poika:'),
(1672833,58,4,7,61,'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,'),
(1672834,58,4,7,62,'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,'),
(1672835,58,4,7,63,'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,'),
(1672836,58,4,7,64,'kauris syntiuhriksi'),
(1672837,58,4,7,65,'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Abidanin, Gideonin pojan, uhrilahja.'),
(1672838,58,4,7,66,'Kymmenentenä päivänä Daanin jälkeläisten ruhtinas Ahieser, Ammisaddain poika:'),
(1672839,58,4,7,67,'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,'),
(1672840,58,4,7,68,'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,'),
(1672841,58,4,7,69,'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,'),
(1672842,58,4,7,70,'kauris syntiuhriksi'),
(1672843,58,4,7,71,'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Ahieserin, Ammisaddain pojan, uhrilahja.'),
(1672844,58,4,7,72,'Yhdentenätoista päivänä Asserin jälkeläisten ruhtinas Pagiel, Okranin poika:'),
(1672845,58,4,7,73,'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,'),
(1672846,58,4,7,74,'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,'),
(1672847,58,4,7,75,'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,'),
(1672848,58,4,7,76,'kauris syntiuhriksi'),
(1672849,58,4,7,77,'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Pagielin, Okranin pojan, uhrilahja.'),
(1672850,58,4,7,78,'Kahdentenatoista päivänä Naftalin jälkeläisten ruhtinas Ahira, Eenanin poika:'),
(1672851,58,4,7,79,'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,'),
(1672852,58,4,7,80,'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,'),
(1672853,58,4,7,81,'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,'),
(1672854,58,4,7,82,'kauris syntiuhriksi'),
(1672855,58,4,7,83,'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Ahiran, Eenanin pojan, uhrilahja.'),
(1672856,58,4,7,84,'Nämä olivat ne vihkiäislahjat, jotka Israelin ruhtinaat antoivat alttaria varten sinä päivänä, jona se voideltiin: kaksitoista hopeavatia, kaksitoista maljaa, kaksitoista kultakuppia,'),
(1672857,58,4,7,85,'kukin hopeavati sadan kolmenkymmenen sekelin ja kukin malja seitsemänkymmenen sekelin painoinen; näissä astioissa oli siis hopeata yhteensä kaksituhatta neljäsataa sekeliä pyhäkkösekelin painon mukaan.'),
(1672858,58,4,7,86,'Kultakuppeja oli kaksitoista, täynnä suitsuketta, kukin kuppi kymmenen sekelin painoinen pyhäkkösekelin painon mukaan; kupeissa oli siis kultaa yhteensä sata kaksikymmentä sekeliä.'),
(1672859,58,4,7,87,'Polttouhrieläimiä oli yhteensä: kaksitoista härkää, kaksitoista oinasta, kaksitoista vuoden vanhaa karitsaa ynnä niihin kuuluva ruokauhri; ja syntiuhrikauriita oli kaksitoista.'),
(1672860,58,4,7,88,'Yhteysuhrieläimiä oli yhteensä: kaksikymmentä neljä härkää, kuusikymmentä oinasta, kuusikymmentä kaurista ja kuusikymmentä vuoden vanhaa karitsaa. Nämä olivat ne vihkiäislahjat, jotka annettiin alttaria varten, sen jälkeen kuin se oli voideltu.'),
(1672861,58,4,7,89,'Ja kun Mooses meni ilmestysmajaan puhumaan Herran kanssa, kuuli hän äänen, joka puhutteli häntä lain arkin päällä olevalta armoistuimelta, molempien kerubien väliltä; ja Herra puhui hänelle.'),
(1672862,58,4,8,1,'Ja Herra puhui Moosekselle sanoen:'),
(1672863,58,4,8,2,'"Puhu Aaronille ja sano hänelle: Kun nostat lamput paikoilleen, niin valaiskoot ne seitsemän lamppua seitsenhaaraisen lampun edustaa".'),
(1672864,58,4,8,3,'Ja Aaron teki niin; hän nosti lamput valaisemaan seitsenhaaraisen lampun edustaa, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1672865,58,4,8,4,'Ja näin oli seitsenhaarainen lamppu tehty: se oli kullasta, kohotakoista tekoa; sen jalka ja kukkalehdetkin olivat kohotakoista tekoa. Aivan sen kaavan mukaan, jonka Herra oli Moosekselle näyttänyt, hän teki seitsenhaaraisen lampun.'),
(1672866,58,4,8,5,'Ja Herra puhui Moosekselle sanoen:'),
(1672867,58,4,8,6,'"Ota leeviläiset israelilaisten keskuudesta ja puhdista heidät.'),
(1672868,58,4,8,7,'Ja puhdistaaksesi heidät tee näin: Pirskoita heihin synnistä puhdistavaa vettä, ja ajattakoot he koko ruumiinsa partaveitsellä ja peskööt vaatteensa ja puhdistakoot itsensä.'),
(1672869,58,4,8,8,'Ja sitten he ottakoot mullikan sekä siihen kuuluvana ruokauhrina öljyllä sekoitettuja lestyjä jauhoja; ja ota toinen mullikka syntiuhriksi.'),
(1672870,58,4,8,9,'Tuo sitten leeviläiset ilmestysmajan eteen sekä kokoa kaikki Israelin kansa.'),
(1672871,58,4,8,10,'Ja kun olet tuonut leeviläiset Herran eteen, laskekoot israelilaiset kätensä leeviläisten päälle,'),
(1672872,58,4,8,11,'ja Aaron toimittakoon leeviläisille israelilaisten puolesta heilutuksen Herran edessä, että he kelpaisivat Herran palvelukseen.'),
(1672873,58,4,8,12,'Mutta leeviläiset laskekoot kätensä mullikkain pään päälle, ja valmista toinen syntiuhriksi ja toinen polttouhriksi Herralle, toimittaaksesi sovituksen leeviläisille.'),
(1672874,58,4,8,13,'Aseta sitten leeviläiset Aaronin ja hänen poikiensa eteen ja toimita heille heilutus Herran edessä.'),
(1672875,58,4,8,14,'Erota leeviläiset israelilaisten keskuudesta, että leeviläiset olisivat minun omani.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672876,58,4,8,15,'Ja senjälkeen leeviläiset menkööt palvelemaan ilmestysmajaa, kun sinä olet puhdistanut heidät ja toimittanut heille heilutuksen.'),
(1672877,58,4,8,16,'Sillä he ovat kokonaan annetut minun omikseni israelilaisten keskuudesta; kaiken sen sijaan, joka avaa äidinkohdun, israelilaisten kaikkien esikoisten sijaan, minä olen heidät ottanut omikseni.'),
(1672878,58,4,8,17,'Sillä jokainen esikoinen israelilaisten keskuudessa, niin ihmisten kuin karjankin, on minun omani; sinä päivänä, jona minä surmasin kaikki Egyptin maan esikoiset, minä pyhitin heidät itselleni.'),
(1672879,58,4,8,18,'Ja minä otin leeviläiset israelilaisten kaikkien esikoisten sijaan.'),
(1672880,58,4,8,19,'Ja minä annoin leeviläiset Aaronille ja hänen pojillensa palvelijoiksi, israelilaisten keskuudesta, suorittamaan israelilaisten puolesta palvelusta ilmestysmajassa ja toimittamaan israelilaisille sovitusta; ja niin israelilaisia ei kohtaa rangaistus siitä, että lähestyvät pyhäkköä.'),
(1672881,58,4,8,20,'Mooses ja Aaron ja koko Israelin kansa tekivät leeviläisille kaiken, niinkuin Herra oli Moosekselle leeviläisistä käskyn antanut; niin israelilaiset heille tekivät.'),
(1672882,58,4,8,21,'Ja leeviläiset puhdistautuivat synnistä ja pesivät vaatteensa. Ja Aaron toimitti heille heilutuksen Herran edessä, ja Aaron toimitti heille sovituksen heidän puhdistamiseksensa.'),
(1672883,58,4,8,22,'Ja senjälkeen leeviläiset menivät toimittamaan palvelustansa ilmestysmajassa Aaronin ja hänen poikiensa edessä. Niinkuin Herra oli Moosekselle leeviläisistä käskyn antanut, niin heille tehtiin.'),
(1672884,58,4,8,23,'Ja Herra puhui Moosekselle sanoen:'),
(1672885,58,4,8,24,'"Tämä olkoon voimassa leeviläisistä: Kahdenkymmenen viiden vuoden ikäiset ja sitä vanhemmat menkööt palvelemaan ja toimittamaan palvelusta ilmestysmajassa.'),
(1672886,58,4,8,25,'Mutta viidennestäkymmenennestä ikävuodesta alkaen leeviläinen olkoon palveluksesta vapaa älköönkä enää palvelko,'),
(1672887,58,4,8,26,'vaan auttakoon veljiään ilmestysmajassa heidän tehtäviensä hoitamisessa, mutta palvelusta hän älköön enää toimittako. Järjestä näin leeviläisille heidän tehtävänsä."'),
(1672888,58,4,9,1,'Ja Herra puhui Moosekselle Siinain erämaassa toisena vuotena siitä, kun he olivat lähteneet Egyptin maasta, sen vuoden ensimmäisessä kuussa, sanoen:'),
(1672889,58,4,9,2,'"Israelilaiset viettäkööt pääsiäisen määräaikanansa.'),
(1672890,58,4,9,3,'Tämän kuukauden neljäntenätoista päivänä, iltahämärässä, viettäkää se määräaikanansa; kaikkien sitä koskevien käskyjen ja säädösten mukaan se viettäkää."'),
(1672891,58,4,9,4,'Ja Mooses käski israelilaisten viettää pääsiäistä.'),
(1672892,58,4,9,5,'Niin he viettivät pääsiäisen ensimmäisessä kuussa, kuukauden neljäntenätoista päivänä, iltahämärässä, Siinain erämaassa; israelilaiset tekivät kaiken, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1672893,58,4,9,6,'Mutta siellä oli miehiä, jotka olivat saastuneet kuolleesta eivätkä voineet viettää pääsiäistä sinä päivänä. Niin he astuivat sinä päivänä Mooseksen ja Aaronin eteen.'),
(1672894,58,4,9,7,'Ja miehet sanoivat hänelle: "Me olemme saastuneet kuolleesta; miksi meidät estetään tuomasta Herralle uhrilahjaa määräaikanansa israelilaisten keskuudessa?"'),
(1672895,58,4,9,8,'Ja Mooses sanoi heille: "Jääkää tähän, minä menen kuulemaan, mitä Herra teistä säätää".'),
(1672896,58,4,9,9,'Ja Herra puhui Moosekselle sanoen:'),
(1672897,58,4,9,10,'"Puhu israelilaisille näin: Jos joku teistä tai teidän jälkeläisistänne on saastunut kuolleesta tai on kaukana matkalla, viettäköön kuitenkin pääsiäistä Herran kunniaksi;'),
(1672898,58,4,9,11,'viettäkööt sitä toisen kuukauden neljäntenätoista päivänä, iltahämärässä. Happamattoman leivän ja katkerain yrttien kanssa he syökööt pääsiäislampaan.'),
(1672899,58,4,9,12,'Älkööt he jättäkö siitä mitään seuraavaan aamuun älköötkä siitä luuta rikkoko. Kaikkien pääsiäistä koskevien käskyjen mukaan he viettäkööt sitä.'),
(1672900,58,4,9,13,'Mutta se mies, joka on puhdas eikä ole matkoilla ja kuitenkin jättää pääsiäisen viettämättä, hävitettäköön kansastansa, koska hän ei tuonut uhrilahjaa Herralle määräaikanansa; se mies joutuu syynalaiseksi.'),
(1672901,58,4,9,14,'Ja jos muukalainen asuu teidän luonanne ja tahtoo viettää pääsiäistä Herran kunniaksi, viettäköön sen pääsiäistä koskevien käskyjen ja säädösten mukaan; samat käskyt olkoot teillä, niin muukalaisella kuin maassa syntyneelläkin."'),
(1672902,58,4,9,15,'Mutta sinä päivänä, jona asumus pystytettiin, peitti pilvi asumuksen, lain majan, ja illalla näkyi asumuksen päällä niinkuin tulenhohde, ja aina aamuun asti.'),
(1672903,58,4,9,16,'Niin oli aina: pilvi peitti sen päivällä ja tulenhohde yöllä.'),
(1672904,58,4,9,17,'Ja niin usein kuin pilvi kohosi majan päältä, lähtivät israelilaiset liikkeelle; ja mihin pilvi laskeutui, siihen israelilaiset leiriytyivät.'),
(1672905,58,4,9,18,'Herran käskyn mukaan israelilaiset lähtivät liikkeelle, ja Herran käskyn mukaan israelilaiset leiriytyivät. He olivat leiriytyneinä, niin kauan kuin pilvi pysyi asumuksen päällä.'),
(1672906,58,4,9,19,'Ja kun pilvi viipyi asumuksen päällä useampia päiviä, noudattivat israelilaiset, mitä Herra oli käskenyt heidän noudattaa, eivätkä lähteneet liikkeelle.'),
(1672907,58,4,9,20,'Mutta joskus pilvi viipyi asumuksen päällä vain muutamia päiviä; silloinkin he Herran käskyn mukaan olivat leiriytyneinä ja lähtivät Herran käskyn mukaan liikkeelle.'),
(1672908,58,4,9,21,'Ja joskus pilvi pysyi paikallaan vain illasta aamuun ja kohosi aamulla; silloinkin he lähtivät liikkeelle. Tahi jos pilvi pysyi päivän ja yön ja sitten kohosi, niin he lähtivät liikkeelle.'),
(1672909,58,4,9,22,'Tahi kun pilvi viipyi pysyen asumuksen päällä pari päivää tai kuukauden tai vielä pitemmän ajan, niin olivat israelilaiset leiriytyneinä eivätkä lähteneet liikkeelle; mutta kun se kohosi, lähtivät he liikkeelle.'),
(1672910,58,4,9,23,'Herran käskyn mukaan he leiriytyivät ja Herran käskyn mukaan he lähtivät liikkeelle. He noudattivat, mitä Herra Mooseksen kautta oli käskenyt heidän noudattaa.'),
(1672911,58,4,10,1,'Ja Herra puhui Moosekselle sanoen:'),
(1672912,58,4,10,2,'"Tee itsellesi kaksi hopeatorvea, tee ne kohotakoista tekoa, käyttääksesi niitä kansan kokoonkutsumiseen ja leirien liikkeelle-panemiseen.'),
(1672913,58,4,10,3,'Kun niihin molempiin puhalletaan, kokoontukoon sinun luoksesi koko kansa ilmestysmajan oven eteen.'),
(1672914,58,4,10,4,'Mutta kun ainoastaan toiseen puhalletaan, kokoontukoot sinun luoksesi ruhtinaat, Israelin heimojen päämiehet.'),
(1672915,58,4,10,5,'Mutta kun puhallatte hälytyssoiton, silloin lähtekööt itään päin leiriytyneet leirit liikkeelle.'),
(1672916,58,4,10,6,'Ja kun toistamiseen puhallatte hälytyssoiton, lähtekööt etelään päin leiriytyneet leirit liikkeelle. Hälytyssoitto puhallettakoon liikkeelle lähdettäessä.'),
(1672917,58,4,10,7,'Mutta seurakuntaa kokoonkutsuttaessa puhaltakaa torveen, hälytyssoittoa soittamatta.'),
(1672918,58,4,10,8,'Ja Aaronin pojat, papit, puhaltakoot näitä torvia. Tämä olkoon teille ikuinen säädös sukupolvesta sukupolveen.'),
(1672919,58,4,10,9,'Ja kun te maassanne lähdette taisteluun vihollista vastaan, joka teitä ahdistaa, niin soittakaa torvilla hälytys; silloin te muistutte Herran, teidän Jumalanne, mieleen ja pelastutte vihollisistanne.'),
(1672920,58,4,10,10,'Ja ilopäivinänne sekä juhlinanne ynnä uudenkuun päivinä puhaltakaa torviin uhratessanne poltto- ja yhteysuhrejanne, niin ne saattavat teidän Jumalanne muistamaan teitä. Minä olen Herra, teidän Jumalanne."'),
(1672921,58,4,10,11,'Toisen vuoden toisen kuukauden kahdentenakymmenentenä päivänä pilvi kohosi lain asumuksen päältä.'),
(1672922,58,4,10,12,'Silloin israelilaiset lähtivät liikkeelle, leiri leirin jälkeen, Siinain erämaasta; ja pilvi pysähtyi Paaranin erämaassa.'),
(1672923,58,4,10,13,'Niin he ensi kerran lähtivät liikkeelle sillä tavoin, kuin Herra oli Mooseksen kautta käskenyt.'),
(1672924,58,4,10,14,'Juudan jälkeläisten leirin lippukunta lähti ensimmäisenä joukkona liikkeelle osastoittain, ja tätä osastoa johti Nahson, Amminadabin poika.'),
(1672925,58,4,10,15,'Ja Isaskarin jälkeläisten sukukuntaosastoa johti Netanel, Suuarin poika.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672926,58,4,10,16,'Ja Sebulonin jälkeläisten sukukuntaosastoa johti Eliab, Heelonin poika.'),
(1672927,58,4,10,17,'Ja kun asumus oli purettu, niin lähtivät liikkeelle Geersonin pojat ja Merarin pojat, jotka kantoivat asumusta.'),
(1672928,58,4,10,18,'Sitten lähti Ruubenin leirin lippukunta liikkeelle osastoittain, ja tätä osastoa johti Elisur, Sedeurin poika.'),
(1672929,58,4,10,19,'Ja Simeonin jälkeläisten sukukuntaosastoa johti Selumiel, Suurisaddain poika.'),
(1672930,58,4,10,20,'Ja Gaadin jälkeläisten sukukuntaosastoa johti Eljasaf, Deguelin poika.'),
(1672931,58,4,10,21,'Sitten lähtivät kehatilaiset liikkeelle kantaen pyhiä esineitä. Ja asumus pantiin pystyyn, ennenkuin he saapuivat perille.'),
(1672932,58,4,10,22,'Sitten lähti Efraimin jälkeläisten leirin lippukunta liikkeelle osastoittain, ja tätä osastoa johti Elisama, Ammihudin poika.'),
(1672933,58,4,10,23,'Manassen jälkeläisten sukukuntaosastoa johti Gamliel, Pedasurin poika.'),
(1672934,58,4,10,24,'Benjaminin jälkeläisten sukukuntaosastoa johti Abidan, Gideonin poika.'),
(1672935,58,4,10,25,'Sitten lähti Daanin jälkeläisten leirin lippukunta liikkeelle kaikkien leirien jälkijoukkona, osastoittain, ja tätä osastoa johti Ahieser, Ammisaddain poika.'),
(1672936,58,4,10,26,'Asserin jälkeläisten sukukuntaosastoa johti Pagiel, Okranin poika.'),
(1672937,58,4,10,27,'Ja Naftalin jälkeläisten sukukuntaosastoa johti Ahira, Eenanin poika.'),
(1672938,58,4,10,28,'Tällainen oli israelilaisten liikkeellelähtö osastoittain; niin he lähtivät liikkeelle.'),
(1672939,58,4,10,29,'Ja Mooses puhui Hoobabille, midianilaisen Reguelin, Mooseksen apen, pojalle: "Me lähdemme siihen paikkaan, josta Herra on sanonut: ''Sen minä annan teille''. Lähde meidän kanssamme, niin me palkitsemme sinut hyvin, sillä Herra on luvannut hyvää Israelille."'),
(1672940,58,4,10,30,'Mutta hän vastasi hänelle: "En lähde, vaan minä menen omaan maahani ja sukuni luo".'),
(1672941,58,4,10,31,'Niin Mooses sanoi: "Älä jätä meitä, sillä sinähän tiedät, mihin meidän sopii leiriytyä erämaassa; rupea siis meille oppaaksi.'),
(1672942,58,4,10,32,'Jos lähdet meidän kanssamme, niin me annamme sinun saada osasi siitä hyvästä, minkä Herra meille suo."'),
(1672943,58,4,10,33,'Niin he lähtivät liikkeelle Herran vuoren luota ja vaelsivat kolme päivänmatkaa. Ja Herran liitonarkki kulki heidän edellänsä kolme päivänmatkaa etsimässä heille levähdyspaikkaa.'),
(1672944,58,4,10,34,'Ja Herran pilvi oli heidän päällänsä päivällä, kun he lähtivät leiristä liikkeelle.'),
(1672945,58,4,10,35,'Ja kun arkki lähti liikkeelle, niin Mooses lausui: "Nouse, Herra, hajaantukoot sinun vihollisesi, ja sinun vihamiehesi paetkoot sinua".'),
(1672946,58,4,10,36,'Ja kun arkki laskettiin maahan, lausui hän: "Palaja, Herra, Israelin heimojen kymmentuhansien tykö".'),
(1672947,58,4,11,1,'Mutta kansa tuskitteli, ja se oli paha Herran korvissa. Kun Herra sen kuuli, vihastui hän, ja Herran tuli syttyi heidän keskellään, ja se kulutti ulommaisen osan leiriä.'),
(1672948,58,4,11,2,'Silloin kansa huusi Moosesta, ja Mooses rukoili Herraa; niin tuli alkoi sammua.'),
(1672949,58,4,11,3,'Ja sen paikan nimeksi pantiin Tabeera, koska Herran tuli oli siellä syttynyt heidän keskellään.'),
(1672950,58,4,11,4,'Mutta heidän keskuuteensa kerääntyneessä hylkyväessä heräsivät himot, ja niin israelilaisetkin rupesivat jälleen itkemään, sanoen: "Voi jospa meillä olisi lihaa syödäksemme!'),
(1672951,58,4,11,5,'Me muistelemme kaloja, joita söimme Egyptissä ilmaiseksi, kurkkuja, melooneja, ruoholaukkaa, sipulia ja kynsilaukkaa.'),
(1672952,58,4,11,6,'Mutta nyt me näännymme, sillä eihän täällä ole mitään; emme saa nähdäkään muuta kuin tuota mannaa."'),
(1672953,58,4,11,7,'Ja manna oli korianderin siemenen kaltaista ja bedellion-pihkan näköistä.'),
(1672954,58,4,11,8,'Kansa samoili sitä kokoamassa ja jauhoi sitä käsikivillä tai survoi huhmaressa; sitten he keittivät sitä padassa ja valmistivat siitä kaltiaisia. Ja sen maku oli samanlainen kuin öljyleivoksen.'),
(1672955,58,4,11,9,'Ja kasteen laskeutuessa yöllä leiriin laskeutui mannakin siihen.'),
(1672956,58,4,11,10,'Ja Mooses kuuli, kuinka kansa, joka suku, itki, kukin majansa ovella; niin Herra vihastui kovin, ja myös Mooseksen silmissä se oli paha.'),
(1672957,58,4,11,11,'Ja Mooses sanoi Herralle: "Miksi olet tehnyt niin pahoin palvelijallesi, ja miksi en ole saanut armoa sinun silmiesi edessä, koska olet pannut kaiken tämän kansan minun taakakseni?'),
(1672958,58,4,11,12,'Olenko minä kaiken tämän kansan äiti tai isä, koska käsket minua kantamaan sitä sylissäni, niinkuin hoitaja kantaa imeväistä lasta, siihen maahan, jonka olet valalla vannoen luvannut heidän isillensä?'),
(1672959,58,4,11,13,'Mistä minulla on lihaa antaa kaikelle tälle kansalle, kun he ahdistavat minua itkullaan sanoen: ''Anna meille lihaa syödäksemme''?'),
(1672960,58,4,11,14,'En minä jaksa yksinäni kantaa koko tätä kansaa, sillä se on minulle liian raskas.'),
(1672961,58,4,11,15,'Ja jos näin aiot kohdella minua, niin surmaa minut mieluummin, jos olen saanut armon sinun silmiesi edessä, ja päästä minut näkemästä tätä kurjuutta."'),
(1672962,58,4,11,16,'Silloin Herra puhui Moosekselle: "Kutsu kokoon minua varten seitsemänkymmentä miestä Israelin vanhimpia, jotka tiedät kansan vanhimmiksi ja päällysmiehiksi; tuo heidät ilmestysmajalle, ja he asettukoot sinne sinun kanssasi.'),
(1672963,58,4,11,17,'Minä sitten astun alas ja puhun siellä sinun kanssasi ja otan henkeä, joka sinussa on, ja annan heille; siten he voivat auttaa sinua tuon kansataakan kantamisessa, ettei sinun tarvitse sitä yksinäsi kantaa.'),
(1672964,58,4,11,18,'Mutta kansalle sano: Pyhittäytykää huomiseksi, niin saatte syödä lihaa, koska itkitte Herran kuullen, sanoen: ''Voi, jospa meillä olisi lihaa syödäksemme! Egyptissä meidän oli hyvä olla.'' Herra antaa nyt teille lihaa syödäksenne.'),
(1672965,58,4,11,19,'Eikä siinä ole teille syömistä ainoastaan päiväksi tai kahdeksi, tai viideksi tai kymmeneksi tai kahdeksikymmeneksi päiväksi,'),
(1672966,58,4,11,20,'vaan kuukauden päiviksi, kunnes ette enää siedä sen hajua ja se iljettää teitä. Sillä te olette pitäneet halpana Herran, joka on teidän keskellänne, ja itkeneet hänen edessänsä sanoen: ''Miksi lähdimmekään Egyptistä!"'),
(1672967,58,4,11,21,'Mooses vastasi: "Kuusisataa tuhatta jalkamiestä on sitä kansaa, jonka keskuudessa minä elän, ja kuitenkin sinä sanot: ''Minä annan heille lihaa, niin että heillä on sitä syödä kuukauden päivät''.'),
(1672968,58,4,11,22,'Onko lampaita ja raavaita teurastettaviksi heille, niin että heille riittää, vai kootaanko heille kaikki meren kalat, niin että heille riittää?"'),
(1672969,58,4,11,23,'Mutta Herra sanoi Moosekselle: "Onko Herran käsi lyhyt? Nyt saat nähdä, toteutuuko sinulle minun sanani vai eikö."'),
(1672970,58,4,11,24,'Niin Mooses meni ulos ja kertoi kansalle Herran sanat. Sitten hän kutsui kokoon seitsemänkymmentä miestä kansan vanhimpia ja asetti heidät majan ympärille.'),
(1672971,58,4,11,25,'Silloin Herra astui alas pilvessä ja puhutteli häntä, otti henkeä, joka hänessä oli, ja antoi sitä niille seitsemällekymmenelle vanhimmalle. Kun henki laskeutui heihin, niin he joutuivat hurmoksiin, mutta sen jälkeen he eivät enää siihen joutuneet.'),
(1672972,58,4,11,26,'Mutta leiriin oli heitä jäänyt kaksi miestä, toisen nimi oli Eldad ja toisen nimi Meedad. Heihinkin henki laskeutui, sillä hekin olivat luetteloon merkityt, vaikka eivät olleet lähteneet majalle; nämä joutuivat leirissä hurmoksiin.'),
(1672973,58,4,11,27,'Silloin riensi muuan nuorukainen ja ilmoitti Moosekselle sanoen: "Eldad ja Meedad ovat joutuneet hurmoksiin leirissä".'),
(1672974,58,4,11,28,'Mutta Joosua, Nuunin poika, joka oli ollut Mooseksen palvelija nuoruudestaan asti, puuttui puheeseen sanoen: "Oi, herrani Mooses, kiellä heitä!"'),
(1672975,58,4,11,29,'Mutta Mooses vastasi hänelle: "Oletko kateellinen minun puolestani? Oi, jospa koko Herran kansa olisi profeettoja, niin että Herra antaisi henkensä heihin!"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1672976,58,4,11,30,'Sitten Mooses siirtyi takaisin leiriin ja hänen kanssaan Israelin vanhimmat.'),
(1672977,58,4,11,31,'Mutta Herran lähettämä tuuli nousi ja ajoi edellään viiriäisiä mereltä päin ja painoi niitä leiriin päivänmatkan laajuudelta joka suunnalle leiristä, lähes kahden kyynärän korkeuteen maasta.'),
(1672978,58,4,11,32,'Silloin kansa ryhtyi kokoamaan viiriäisiä ja kokosi niitä koko sen päivän ja koko yön ja koko seuraavan päivän. Vähin määrä, jonka joku sai kootuksi, oli kymmenen hoomer-mittaa. Ja he levittivät niitä pitkin leiriä kuivamaan.'),
(1672979,58,4,11,33,'Mutta lihan vielä ollessa heidän hampaissaan, ennenkuin se oli syöty loppuun, syttyi Herran viha kansaa kohtaan, ja Herra tuotti kansalle hyvin suuren surman.'),
(1672980,58,4,11,34,'Ja sen paikan nimeksi pantiin Kibrot-Hattaava, koska sinne haudattiin kansasta ne, jotka olivat antautuneet halunsa valtaan.'),
(1672981,58,4,11,35,'Kibrot-Hattaavasta kansa lähti liikkeelle Haserotia kohti ja pysähtyi Haserotiin.'),
(1672982,58,4,12,1,'Mutta Mirjam ja Aaron parjasivat Moosesta etiopialaisen naisen tähden, jonka hän oli ottanut vaimokseen; sillä hän oli ottanut vaimokseen etiopialaisen naisen.'),
(1672983,58,4,12,2,'Ja he sanoivat: "Ainoastaan Mooseksen kauttako Herra puhuu? Eikö hän puhu myös meidän kauttamme?" Ja Herra kuuli sen.'),
(1672984,58,4,12,3,'Mutta Mooses oli sangen nöyrä mies, nöyrempi kuin kukaan muu ihminen maan päällä.'),
(1672985,58,4,12,4,'Niin Herra sanoi äkisti Moosekselle ja Aaronille ja Mirjamille: "Menkää te kaikki kolme ilmestysmajalle". Ja he menivät kaikki kolme sinne.'),
(1672986,58,4,12,5,'Silloin Herra astui alas pilvenpatsaassa, asettui majan ovelle ja kutsui Aaronia ja Mirjamia; molemmat menivät sinne.'),
(1672987,58,4,12,6,'Ja Herra sanoi: "Kuulkaa minun sanani. Jos keskuudessanne on profeetta, niin minä ilmestyn hänelle näyssä, puhun hänen kanssaan unessa.'),
(1672988,58,4,12,7,'Niin ei ole minun palvelijani Mooses, hän on uskollinen koko minun talossani;'),
(1672989,58,4,12,8,'hänen kanssaan minä puhun suusta suuhun, avoimesti enkä peitetyin sanoin, ja hän saa katsella Herran muotoa. Miksi ette siis peljänneet puhua minun palvelijaani Moosesta vastaan?"'),
(1672990,58,4,12,9,'Ja Herran viha syttyi heitä kohtaan, ja hän meni pois.'),
(1672991,58,4,12,10,'Kun pilvi oli poistunut majan päältä, niin katso, Mirjam oli lumivalkea pitalista; ja Aaron kääntyi Mirjamiin päin, ja katso, tämä oli pitalinen.'),
(1672992,58,4,12,11,'Silloin Aaron sanoi Moosekselle: "Oi, herrani! Älä pane meidän päällemme syntiä, jonka olemme tyhmyydessä tehneet.'),
(1672993,58,4,12,12,'Älä anna hänen jäädä kuolleen sikiön kaltaiseksi, jonka ruumis on puoleksi mädännyt, kun se äitinsä kohdusta tulee."'),
(1672994,58,4,12,13,'Silloin Mooses huusi Herran puoleen sanoen: "Oi, Jumala! Paranna hänet!"'),
(1672995,58,4,12,14,'Herra vastasi Moosekselle: "Jos hänen isänsä olisi sylkenyt häntä silmille, eikö hänen olisi ollut hävettävä seitsemän päivää? Olkoon hän nyt suljettuna ulos leiristä seitsemän päivää, ja sitten hän pääsköön takaisin."'),
(1672996,58,4,12,15,'Niin Mirjam oli suljettuna ulos leiristä seitsemän päivää, eikä kansa lähtenyt liikkeelle, ennenkuin Mirjam oli tuotu takaisin.'),
(1672997,58,4,13,1,'Sen jälkeen kansa lähti liikkeelle Haserotista ja leiriytyi Paaranin erämaahan.'),
(1672998,58,4,13,2,'Ja Herra puhui Moosekselle sanoen:'),
(1672999,58,4,13,3,'"Lähetä miehiä vakoilemaan Kanaanin maata, jonka minä annan israelilaisille; lähettäkää mies kustakin isien sukukunnasta, ainoastaan niitä, jotka ovat ruhtinaita heidän keskuudessaan".'),
(1673000,58,4,13,4,'Niin Mooses lähetti heidät Paaranin erämaasta Herran käskyn mukaan; kaikki ne miehet olivat israelilaisten päämiehiä.'),
(1673001,58,4,13,5,'Ja nämä olivat heidän nimensä: Ruubenin sukukunnasta Sammua, Sakkurin poika,'),
(1673002,58,4,13,6,'Simeonin sukukunnasta Saafat, Hoorin poika,'),
(1673003,58,4,13,7,'Juudan sukukunnasta Kaaleb, Jefunnen poika,'),
(1673004,58,4,13,8,'Isaskarin sukukunnasta Jigal, Joosefin poika,'),
(1673005,58,4,13,9,'Efraimin sukukunnasta Hoosea, Nuunin poika,'),
(1673006,58,4,13,10,'Benjaminin sukukunnasta Palti, Raafun poika,'),
(1673007,58,4,13,11,'Sebulonin sukukunnasta Gaddiel, Soodin poika,'),
(1673008,58,4,13,12,'Manassen sukukunnasta Joosefin sukukuntaa Gaddi, Suusin poika,'),
(1673009,58,4,13,13,'Daanin sukukunnasta Ammiel, Gemallin poika,'),
(1673010,58,4,13,14,'Asserin sukukunnasta Setur, Miikaelin poika,'),
(1673011,58,4,13,15,'Naftalin sukukunnasta Nahbi, Vofsin poika,'),
(1673012,58,4,13,16,'Gaadin sukukunnasta Genuel, Maakin poika.'),
(1673013,58,4,13,17,'Nämä olivat niiden miesten nimet, jotka Mooses lähetti maata vakoilemaan. Mutta Mooses kutsui Hoosean, Nuunin pojan, Joosuaksi.'),
(1673014,58,4,13,18,'Ja lähettäessään heidät vakoilemaan Kanaanin maata Mooses sanoi heille: "Lähtekää nyt Etelämaahan ja nouskaa vuoristoon'),
(1673015,58,4,13,19,'ja katselkaa, minkälainen maa on ja minkälainen kansa, joka siinä asuu, onko se voimakas vai heikko, onko sitä vähän vai paljon,'),
(1673016,58,4,13,20,'ja minkälainen maa on, jossa se asuu, onko se hyvä vai huono, ja minkälaiset ne kaupungit ovat, joissa se asuu, avonaisia kyliäkö vai varustettuja kaupunkeja,'),
(1673017,58,4,13,21,'ja minkälaista on maa, lihavaa vai laihaa, onko siinä puita vai ei. Ja olkaa rohkealla mielellä ja ottakaa mukaanne sen maan hedelmiä." Oli näet se aika, jolloin ensimmäiset rypäleet kypsyivät.'),
(1673018,58,4,13,22,'Niin he lähtivät sinne ja vakoilivat maata Siinin erämaasta Rehobiin asti, josta mennään Hamatiin.'),
(1673019,58,4,13,23,'Ja he lähtivät Etelämaahan ja tulivat Hebroniin, jossa asuivat Ahiman, Seesai ja Talmai, Anakin jälkeläiset. Mutta Hebron oli rakennettu seitsemän vuotta ennen Egyptin Sooania.'),
(1673020,58,4,13,24,'Ja he tulivat Rypälelaaksoon; sieltä he leikkasivat viiniköynnöksen, jossa oli rypäleterttu, ja kahden miehen täytyi kantaa sitä korennolla; samoin he ottivat granaattiomenia ja viikunoita.'),
(1673021,58,4,13,25,'Se paikka nimitettiin Rypälelaaksoksi, rypäleen tähden, jonka israelilaiset sieltä leikkasivat.'),
(1673022,58,4,13,26,'Ja he palasivat maata vakoilemasta neljänkymmenen päivän kuluttua.'),
(1673023,58,4,13,27,'He vaelsivat ja tulivat Mooseksen, Aaronin ja kaiken Israelin kansan luo Paaranin erämaahan Kaadekseen. Ja he tekivät heille ja kaikelle kansalle selkoa matkastaan ja näyttivät heille sen maan hedelmiä.'),
(1673024,58,4,13,28,'Ja he kertoivat hänelle sanoen: "Me menimme siihen maahan, jonne meidät lähetit. Ja se tosiaankin vuotaa maitoa ja mettä, ja tällaisia ovat sen hedelmät.'),
(1673025,58,4,13,29,'Mutta kansa, joka siinä maassa asuu, on voimallista, ja kaupungit ovat lujasti varustettuja ja hyvin suuria; näimmepä siellä Anakin jälkeläisiäkin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673026,58,4,13,30,'Amalekilaiset asuvat Etelämaassa ja heettiläiset, jebusilaiset ja amorilaiset asuvat vuoristossa, ja kanaanilaiset asuvat meren rannalla ja Jordanin varsilla."'),
(1673027,58,4,13,31,'Ja Kaaleb koitti tyynnyttää kansaa napisemasta Moosesta vastaan ja sanoi: "Menkäämme sittenkin sinne ja ottakaamme se haltuumme, sillä varmasti me sen voitamme".'),
(1673028,58,4,13,32,'Mutta ne miehet, jotka olivat käyneet hänen kanssaan siellä, sanoivat: "Emme me kykene käymään sen kansan kimppuun, sillä se on meitä voimakkaampi".'),
(1673029,58,4,13,33,'Niin he saattoivat israelilaisten keskuudessa pahaan huutoon sen maan, jota olivat olleet vakoilemassa, sanoessaan: "Se maa, jota olemme kierrelleet ja vakoilleet, on maa, joka syö omat asukkaansa; ja kaikki kansa, jota me siellä näimme, oli kookasta väkeä.'),
(1673030,58,4,13,34,'Näimmepä siellä jättiläisiäkin, Anakin jättiläisheimon jälkeläisiä, ja me olimme mielestämme kuin heinäsirkkoja; sellaisia me heistäkin olimme."'),
(1673031,58,4,14,1,'Silloin koko kansa alkoi huutaa ja parkua, ja kansa itki sen yön.'),
(1673032,58,4,14,2,'Ja kaikki israelilaiset napisivat Moosesta ja Aaronia vastaan, ja koko kansa sanoi heille: "Jospa olisimme kuolleet Egyptin maahan tai tähän erämaahan! Jospa olisimme kuolleet!'),
(1673033,58,4,14,3,'Ja miksi viekään Herra meitä tuohon maahan, jossa me kaadumme miekkaan ja vaimomme ja lapsemme joutuvat vihollisen saaliiksi! Eikö meidän olisi parempi palata Egyptiin?"'),
(1673034,58,4,14,4,'Ja he puhuivat toinen toiselleen: "Valitkaamme johtaja ja palatkaamme Egyptiin".'),
(1673035,58,4,14,5,'Silloin Mooses ja Aaron lankesivat kasvoilleen Israelin kansan koko seurakunnan eteen.'),
(1673036,58,4,14,6,'Mutta Joosua, Nuunin poika, ja Kaaleb, Jefunnen poika, jotka olivat olleet mukana maata vakoilemassa, repäisivät vaatteensa'),
(1673037,58,4,14,7,'ja puhuivat kaikelle israelilaisten seurakunnalle näin: "Maa, jota kävimme vakoilemassa, on ylen ihana maa.'),
(1673038,58,4,14,8,'Jos Herra on meille suosiollinen, niin hän vie meidät siihen maahan ja antaa sen meille, maan, joka vuotaa maitoa ja mettä.'),
(1673039,58,4,14,9,'Älkää vain kapinoiko Herraa vastaan älkääkä peljätkö sen maan kansaa, sillä heitä ei ole meille kuin suupalaksi. Heidän varjelijansa on väistynyt heistä, mutta meidän kanssamme on Herra. Älkää te heitä peljätkö."'),
(1673040,58,4,14,10,'Silloin koko seurakunta vaati heitä kivitettäviksi, mutta Herran kirkkaus ilmestyi kaikille israelilaisille ilmestysmajassa.'),
(1673041,58,4,14,11,'Ja Herra sanoi Moosekselle: "Kuinka kauan tämä kansa pitää minua pilkkanaan eikä usko minuun, huolimatta kaikista tunnusteoista, jotka minä olen tehnyt sen keskuudessa?'),
(1673042,58,4,14,12,'Minä tuhoan sen rutolla ja hävitän sen perinjuurin, mutta sinusta minä teen suuremman ja väkevämmän kansan, kuin se on."'),
(1673043,58,4,14,13,'Mutta Mooses sanoi Herralle: "Ovathan egyptiläiset kuulleet, että sinä voimallasi olet vienyt tämän kansan heidän keskeltänsä.'),
(1673044,58,4,14,14,'Ja he ovat puhuneet siitä sen maan asukkaille; hekin siis ovat kuulleet, että sinä, Herra, olet tämän kansan keskellä, sinä Herra, joka olet sille ilmestynyt silmästä silmään, ja että sinun pilvesi pysyy heidän päällänsä ja että sinä kuljet heidän edellänsä pilvenpatsaassa päivin ja tulenpatsaassa öin.'),
(1673045,58,4,14,15,'Mutta jos sinä nyt surmaat tämän kansan, niinkuin yhden miehen, niin kansat, jotka saavat kuulla sitä kerrottavan sinusta, sanovat näin:'),
(1673046,58,4,14,16,'''Koska Herra ei kyennyt viemään tätä kansaa siihen maahan, jonka hän oli heille valalla vannoen luvannut, tappoi hän heidät erämaahan''.'),
(1673047,58,4,14,17,'Osoittautukoon nyt sinun suuri voimasi, Herra, niinkuin olet puhunut sanoen:'),
(1673048,58,4,14,18,'''Herra on pitkämielinen ja suuri armossa, hän antaa anteeksi pahat teot ja rikokset, mutta ei jätä niitä rankaisematta, vaan kostaa isien pahat teot lapsille kolmanteen ja neljänteen polveen''.'),
(1673049,58,4,14,19,'Anna siis anteeksi tämän kansan pahat teot suuressa armossasi, niinkuin sinä ennenkin olet anteeksi antanut tälle kansalle, Egyptistä tänne saakka."'),
(1673050,58,4,14,20,'Ja Herra vastasi: "Minä annan anteeksi, niinkuin sinä olet anonut.'),
(1673051,58,4,14,21,'Mutta niin totta kuin minä elän, ja niin totta kuin Herran kirkkaus on täyttävä kaiken maan:'),
(1673052,58,4,14,22,'ei kukaan niistä miehistä, jotka ovat nähneet minun kirkkauteni ja minun tunnustekoni, jotka minä olen tehnyt Egyptissä ja tässä erämaassa, mutta kuitenkin nyt jo kymmenen kertaa ovat minua kiusanneet eivätkä ole kuulleet minun ääntäni,'),
(1673053,58,4,14,23,'ei yksikään heistä ole näkevä sitä maata, jonka minä valalla vannoen lupasin heidän isillensä; ei yksikään minun pilkkaajistani ole sitä näkevä.'),
(1673054,58,4,14,24,'Mutta koska minun palvelijassani Kaalebissa on toinen henki, niin että hän on minua uskollisesti seurannut, niin hänet minä vien siihen maahan, jossa hän kävi, ja hänen jälkeläisensä saavat sen omakseen.'),
(1673055,58,4,14,25,'Mutta koska amalekilaiset ja kanaanilaiset asuvat laaksoissa, niin kääntykää huomenna toisaanne päin ja painukaa erämaahan, Kaislameren tietä."'),
(1673056,58,4,14,26,'Ja Herra puhui Moosekselle ja Aaronille sanoen:'),
(1673057,58,4,14,27,'"Kuinka kauan tämä häijy joukko napisee minua vastaan? Minä olen kuullut, kuinka israelilaiset napisevat minua vastaan.'),
(1673058,58,4,14,28,'Sano heille: Niin totta kuin minä elän, sanoo Herra, aivan niinkuin te olette minulle puhuneet, niin minä teille teen.'),
(1673059,58,4,14,29,'Tähän erämaahan kaatuvat teidän ruumiinne, teidän kaikkien, jotka olette katselmuksessa olleet, niin monta kuin teitä on kaksikymmenvuotisia ja sitä vanhempia, jotka olette napisseet minua vastaan.'),
(1673060,58,4,14,30,'Totisesti, te ette pääse siihen maahan, jonka minä olen kättä kohottaen luvannut antaa teille asumasijaksi, ei kukaan teistä, paitsi Kaaleb, Jefunnen poika, ja Joosua, Nuunin poika.'),
(1673061,58,4,14,31,'Mutta teidän lapsenne, joiden sanoitte joutuvan vihollisen saaliiksi, heidät minä vien sinne, ja he saavat tulla tuntemaan sen maan, jota te halveksitte.'),
(1673062,58,4,14,32,'Mutta teidän ruumiinne kaatuvat tähän erämaahan,'),
(1673063,58,4,14,33,'ja teidän lastenne täytyy harhailla paimentolaisina tässä erämaassa neljäkymmentä vuotta ja kärsiä teidän uskottomuutenne tähden, kunnes teidän ruumiinne ovat maatuneet tähän erämaahan.'),
(1673064,58,4,14,34,'Niinkuin te neljäkymmentä päivää vakoilitte maata, niin saatte nyt, päivä vuodeksi luettuna, neljäkymmentä vuotta kärsiä pahoista teoistanne ja tulla tuntemaan, mitä se on, että minä käännyn teistä pois.'),
(1673065,58,4,14,35,'Minä, Herra, olen puhunut. Totisesti, niin minä teen tälle häijylle kansalle, joka on käynyt kapinoimaan minua vastaan: he hukkuvat tähän erämaahan, tänne he kuolevat."'),
(1673066,58,4,14,36,'Mutta ne miehet, jotka Mooses oli lähettänyt maata vakoilemaan ja jotka palattuaan olivat saattaneet koko kansan napisemaan häntä vastaan, saattamalla sen maan pahaan huutoon,'),
(1673067,58,4,14,37,'ne miehet, jotka olivat saattaneet sen maan pahaan huutoon, kuolivat äkkikuolemalla Herran edessä.'),
(1673068,58,4,14,38,'Mutta Joosua, Nuunin poika, ja Kaaleb, Jefunnen poika, jäivät eloon niistä miehistä, jotka olivat käyneet maata vakoilemassa.'),
(1673069,58,4,14,39,'Ja Mooses puhui tämän kaikille israelilaisille. Niin kansa tuli kovin murheelliseksi.'),
(1673070,58,4,14,40,'Ja he nousivat varhain seuraavana aamuna lähteäkseen ylös vuoristoon ja sanoivat: "Katso, tässä me olemme; me lähdemme siihen paikkaan, josta Herra on puhunut, sillä me olemme syntiä tehneet".'),
(1673071,58,4,14,41,'Mutta Mooses sanoi: "Minkätähden te nyt käytte rikkomaan Herran käskyä? Ei se onnistu.'),
(1673072,58,4,14,42,'Älkää lähtekö sinne, sillä Herra ei ole teidän keskellänne; älkää lähtekö, etteivät vihollisenne voittaisi teitä.'),
(1673073,58,4,14,43,'Sillä amalekilaiset ja kanaanilaiset ovat siellä teitä vastassa, ja niin te kaadutte miekkaan; sillä te olette kääntyneet pois Herrasta, eikä Herra ole teidän kanssanne."'),
(1673074,58,4,14,44,'Yhtäkaikki he lähtivät uppiniskaisuudessaan kulkemaan ylös vuoristoon; mutta ei Herran liitonarkki eikä Mooseskaan siirtynyt leiristä.'),
(1673075,58,4,14,45,'Silloin amalekilaiset ja kanaanilaiset, jotka siinä vuoristossa asuivat, syöksyivät alas ja voittivat heidät ja hajottivat heidät, ajaen heitä aina Hormaan asti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673076,58,4,15,1,'Ja Herra puhui Moosekselle sanoen:'),
(1673077,58,4,15,2,'"Puhu israelilaisille ja sano heille: Kun te tulette siihen maahan, jonka minä annan teille asuinsijaksi,'),
(1673078,58,4,15,3,'ja uhraatte Herralle uhrin, poltto- tai teurasuhrin, joko lupausta täyttääksenne tai vapaaehtoisena lahjana tai juhlissanne, valmistaaksenne Herralle suloisen tuoksun raavaista tai lampaista,'),
(1673079,58,4,15,4,'niin se, joka tuo uhrin, tuokoon lahjanansa Herralle ruokauhriksi kymmenenneksen lestyjä jauhoja, sekoitettuna neljännekseen hiin-mittaa öljyä;'),
(1673080,58,4,15,5,'ja juomauhriksi, polttouhrin tai teurasuhrin lisäksi, uhraa neljännes hiin-mittaa viiniä kutakin karitsaa kohti.'),
(1673081,58,4,15,6,'Mutta oinaan lisäksi uhraa ruokauhrina kaksi kymmenennestä lestyjä jauhoja, sekoitettuna kolmannekseen hiin-mittaa öljyä,'),
(1673082,58,4,15,7,'ja juomauhriksi tuo kolmannes hiin-mittaa viiniä suloiseksi tuoksuksi Herralle.'),
(1673083,58,4,15,8,'Mutta kun uhraat mullikan poltto- tai teurasuhriksi, joko lupausta täyttääksesi tai yhteysuhriksi Herralle,'),
(1673084,58,4,15,9,'niin tuotakoon mullikan lisäksi ruokauhrina kolme kymmenennestä lestyjä jauhoja, sekoitettuna puoleen hiin-mittaa öljyä,'),
(1673085,58,4,15,10,'ja juomauhriksi tuo puoli hiin-mittaa viiniä suloisesti tuoksuvaksi uhriksi Herralle.'),
(1673086,58,4,15,11,'Näin tehtäköön kutakin härkää tai oinasta tai karitsaa tai vohlaa uhrattaessa.'),
(1673087,58,4,15,12,'Niin monta kuin uhrieläimiä on, niin tehkää näin kullekin, niin monta kuin niitä on.'),
(1673088,58,4,15,13,'Jokainen maassa syntynyt tehköön näin, tuodessaan suloisesti tuoksuvan uhrin Herralle.'),
(1673089,58,4,15,14,'Ja jos muukalainen, joka asuu teidän luonanne tai on ainiaaksi asettunut teidän keskuuteenne, tahtoo uhrata suloisesti tuoksuvan uhrin Herralle, niin hän tehköön, niinkuin tekin teette.'),
(1673090,58,4,15,15,'Seurakunnassa olkoon laki sama teillä kuin muukalaisellakin, joka asuu teidän luonanne. Tämä olkoon teille ikuinen säädös sukupolvesta sukupolveen. Se, mikä koskee teitä, koskekoon myös muukalaista Herran edessä.'),
(1673091,58,4,15,16,'Sama laki ja sama oikeus olkoon sekä teillä että muukalaisella, joka asuu teidän luonanne."'),
(1673092,58,4,15,17,'Ja Herra puhui Moosekselle sanoen:'),
(1673093,58,4,15,18,'"Puhu israelilaisille ja sano heille: Kun tulette siihen maahan, johon minä teidät vien,'),
(1673094,58,4,15,19,'niin syödessänne sen maan leipää antakaa Herralle anti.'),
(1673095,58,4,15,20,'Ensimmäisistä jyvärouheistanne antakaa kakku anniksi; antakaa se, niinkuin puimatantereelta annatte annin.'),
(1673096,58,4,15,21,'Ensimmäisistä jyvärouheistanne antakaa Herralle anti sukupolvesta sukupolveen.'),
(1673097,58,4,15,22,'Mutta jos erehdyksestä jätätte täyttämättä jonkun näistä käskyistä, jotka Herra on Moosekselle puhunut,'),
(1673098,58,4,15,23,'mitä hyvänsä, mistä Herra Mooseksen kautta on teille käskyn antanut, siitä päivästä lähtien, jolloin Herra antoi käskynsä, ja edelleen sukupolvesta sukupolveen,'),
(1673099,58,4,15,24,'niin, jos rikkomus tapahtui seurakunnan tietämättä, erehdyksestä, uhratkoon koko seurakunta mullikan polttouhriksi, suloiseksi tuoksuksi Herralle, ynnä siihen kuuluvan ruoka- ja juomauhrin, niinkuin säädetty on, sekä kauriin syntiuhriksi.'),
(1673100,58,4,15,25,'Kun pappi sitten on toimittanut sovituksen kaikelle israelilaisten seurakunnalle, niin rikkomus annetaan heille anteeksi; sillä se on ollut erehdys ja he ovat tuoneet lahjansa uhriksi Herralle sekä syntiuhrinsa Herran eteen erehdyksensä vuoksi.'),
(1673101,58,4,15,26,'Se annetaan silloin anteeksi kaikelle israelilaisten seurakunnalle samoinkuin muukalaiselle, joka asuu heidän keskellänsä; sillä koko kansa on vastuunalainen erehdyksestä.'),
(1673102,58,4,15,27,'Mutta jos joku yksityinen rikkoo erehdyksestä, tuokoon vuoden vanhan vuohen syntiuhriksi.'),
(1673103,58,4,15,28,'Kun pappi on toimittanut sovituksen sille, joka on erehdyksestä, tahtomattaan, rikkonut Herraa vastaan, kun hän on toimittanut hänelle sovituksen, niin hänelle annetaan anteeksi.'),
(1673104,58,4,15,29,'Sama laki olkoon sekä maassa syntyneillä israelilaisilla että muukalaisella, joka asuu heidän keskellänsä, kun joku rikkoo erehdyksestä.'),
(1673105,58,4,15,30,'Mutta se, joka tahallisesti tekee syntiä, olipa hän maassa syntynyt tai muukalainen, pilkkaa Herraa, ja hänet hävitettäköön kansastansa.'),
(1673106,58,4,15,31,'Sillä hän on pitänyt halpana Herran sanan ja rikkonut hänen käskynsä; hänet tuhottakoon, syntivelka painaa häntä."'),
(1673107,58,4,15,32,'Israelilaisten oleskellessa erämaassa tavattiin mies kokoamassa puita sapatinpäivänä.'),
(1673108,58,4,15,33,'Niin ne, jotka hänet tapasivat puita kokoamasta, toivat hänet Mooseksen ja Aaronin ja koko seurakunnan eteen.'),
(1673109,58,4,15,34,'Ja he panivat hänet vankeuteen, koska ei ollut vielä määrätty, mitä hänelle oli tehtävä.'),
(1673110,58,4,15,35,'Mutta Herra sanoi Moosekselle: "Se mies rangaistakoon kuolemalla, koko seurakunta kivittäköön hänet leirin ulkopuolella".'),
(1673111,58,4,15,36,'Silloin koko seurakunta vei hänet leirin ulkopuolelle, ja he kivittivät hänet kuoliaaksi, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1673112,58,4,15,37,'Ja Herra puhui Moosekselle sanoen:'),
(1673113,58,4,15,38,'"Puhu israelilaisille ja sano heille, että heidän on sukupolvesta sukupolveen tehtävä itsellensä tupsut viittojensa kulmiin ja sidottava kulmien tupsuihin punasininen lanka.'),
(1673114,58,4,15,39,'Ne tupsut olkoon teillä, että te, kun ne näette, muistaisitte kaikki Herran käskyt ja ne täyttäisitte ettekä seuraisi sydämenne ettekä silmienne himoja, jotka houkuttelevat teitä haureuteen;'),
(1673115,58,4,15,40,'niin muistakaa ja täyttäkää kaikki minun käskyni ja olkaa pyhät Jumalallenne.'),
(1673116,58,4,15,41,'Minä olen Herra, teidän Jumalanne, joka vein teidät pois Egyptin maasta ollakseni teidän Jumalanne. Minä olen Herra, teidän Jumalanne."'),
(1673117,58,4,16,1,'Mutta Koorah, Jisharin poika, joka oli Leevin pojan Kehatin poika, otti Daatanin ja Abiramin, Eliabin pojat, ja Oonin, joka oli Ruubenin pojan Peletin poika,'),
(1673118,58,4,16,2,'ja he nousivat kapinaan Moosesta vastaan, ja heihin yhtyi israelilaisista kaksisataa viisikymmentä miestä, kansan päämiehiä, kansankokouksen jäseniä, arvokkaita miehiä.'),
(1673119,58,4,16,3,'Ja he kokoontuivat Moosesta ja Aaronia vastaan ja sanoivat heille: "Jo riittää! Koko seurakunta, he kaikki, ovat pyhät, ja Herra on heidän keskellänsä. Miksi te siis korotatte itsenne Herran seurakunnan yli?"'),
(1673120,58,4,16,4,'Kun Mooses sen kuuli, lankesi hän kasvoillensa.'),
(1673121,58,4,16,5,'Sitten hän puhui Koorahille ja kaikelle hänen joukolleen sanoen: "Huomenna Herra ilmoittaa, kuka on hänen omansa ja kuka on pyhä ja kenen hän sallii käydä tykönsä. Kenen hän valitsee, sen hän sallii käydä tykönsä.'),
(1673122,58,4,16,6,'Tehkää näin: Ottakaa itsellenne hiilipannut, sinä Koorah ja kaikki sinun joukkosi,'),
(1673123,58,4,16,7,'ja virittäkää niihin tuli ja pankaa niihin huomenna suitsuketta Herran edessä, niin se mies, jonka Herra silloin valitsee, on pyhä. Riittäköön se teille, te leeviläiset!"'),
(1673124,58,4,16,8,'Ja Mooses puhui Koorahille: "Kuulkaa, te leeviläiset!'),
(1673125,58,4,16,9,'Eikö teille jo riitä se, että Israelin Jumala on erottanut teidät Israelin seurakunnasta, sallinut teidän käydä hänen tykönsä toimittamaan palvelusta Herran asumuksessa ja seisomaan seurakunnan edessä palvelemassa heitä?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673126,58,4,16,10,'Hän salli käydä tykönsä sinun ja kaikkien veljiesi, leeviläisten, sinun kanssasi; ja nyt te tavoittelette pappeuttakin.'),
(1673127,58,4,16,11,'Niin siis sinä ja koko sinun joukkosi käytte kapinoimaan Herraa vastaan; sillä mikä on Aaron, että te häntä vastaan napisette!"'),
(1673128,58,4,16,12,'Ja Mooses kutsutti Daatanin ja Abiramin, Eliabin pojat. Mutta he sanoivat: "Emme tule.'),
(1673129,58,4,16,13,'Eikö jo riitä, että olet tuonut meidät tänne maasta, joka vuotaa maitoa ja mettä, hukuttaaksesi meidät erämaahan? Pyritkö vielä meidän valtiaaksemme?'),
(1673130,58,4,16,14,'Oletpa totisesti tuonut meidät maahan, joka vuotaa maitoa ja mettä, ja antanut meille perintöosaksi vainioita ja viinitarhoja! Luuletko voivasi sokaista silmät näiltä ihmisiltä? Me emme tule."'),
(1673131,58,4,16,15,'Silloin Mooses vihastui kovin ja sanoi Herralle: "Älä katso heidän uhrilahjansa puoleen. En ole keneltäkään heistä aasiakaan anastanut enkä kenellekään heistä mitään vääryyttä tehnyt."'),
(1673132,58,4,16,16,'Silloin Mooses sanoi Koorahille: "Astukaa huomenna Herran eteen, sinä itse ja koko sinun joukkosi, sekä myöskin Aaron,'),
(1673133,58,4,16,17,'ja ottakoon kukin teistä hiilipannunsa ja pankoon siihen suitsuketta sekä tuokoon Herran eteen hiilipannunsa, kaksisataa viisikymmentä hiilipannua; niin ikään sinä ja Aaron tuokaa kumpikin hiilipannunne".'),
(1673134,58,4,16,18,'Niin he ottivat kukin hiilipannunsa, virittivät niihin tulen ja panivat niihin suitsuketta ja asettuivat ilmestysmajan ovelle; samoin myöskin Mooses ja Aaron.'),
(1673135,58,4,16,19,'Mutta Koorah kokosi heitä vastaan koko seurakunnan ilmestysmajan ovelle. Silloin Herran kirkkaus näkyi koko seurakunnalle.'),
(1673136,58,4,16,20,'Ja Herra puhui Moosekselle ja Aaronille sanoen:'),
(1673137,58,4,16,21,'"Erottautukaa te tästä joukosta, niin minä tuokiossa heidät tuhoan".'),
(1673138,58,4,16,22,'Mutta he lankesivat kasvoillensa ja sanoivat: "Oi Jumala, sinä Jumala, jonka vallassa on kaiken lihan henki: jos yksi mies rikkoo, vihastutko silloin koko seurakuntaan?"'),
(1673139,58,4,16,23,'Niin Herra puhui Moosekselle sanoen:'),
(1673140,58,4,16,24,'"Puhu seurakunnalle näin: Lähtekää pois Koorahin, Daatanin ja Abiramin asumuksen ympäriltä".'),
(1673141,58,4,16,25,'Sitten Mooses nousi ja meni Daatanin ja Abiramin luo, ja Israelin vanhimmat seurasivat häntä.'),
(1673142,58,4,16,26,'Ja hän puhui seurakunnalle sanoen: "Siirtykää pois näiden jumalattomien miesten majoilta älkääkä koskeko mihinkään, mikä on heidän, ettette tuhoutuisi kaikkien heidän syntiensä tähden".'),
(1673143,58,4,16,27,'Niin he lähtivät pois Koorahin, Daatanin ja Abiramin asumuksen ympäriltä. Mutta Daatan ja Abiram olivat tulleet ulos ja asettuneet majojensa ovelle vaimoinensa ja suurine ja pienine lapsinensa.'),
(1673144,58,4,16,28,'Ja Mooses puhui: "Tästä te tietäkää, että Herra on minut lähettänyt tekemään kaikki nämä teot ja etteivät ne ole tapahtuneet minun omasta tahdostani:'),
(1673145,58,4,16,29,'jos nämä kuolevat samalla tavalla, kuin muut ihmiset kuolevat, ja heidän käy, niinkuin kaikkien muiden ihmisten käy, niin ei Herra ole minua lähettänyt.'),
(1673146,58,4,16,30,'Mutta jos Herra antaa jotakin erikoista tapahtua ja maa avaa kitansa ja nielaisee heidät kaikkinensa, niin että he elävältä suistuvat tuonelaan, niin siitä tietäkää, että nämä miehet ovat pilkanneet Herraa."'),
(1673147,58,4,16,31,'Tuskin oli hän saanut kaiken tämän sanotuksi, niin maa halkesi heidän altansa'),
(1673148,58,4,16,32,'ja maa avasi kitansa ja nielaisi heidät, heidän asuntonsa, kaiken Koorahin väen ja kaikki heidän tavaransa.'),
(1673149,58,4,16,33,'Ja he suistuivat kaikkinensa elävältä tuonelaan, ja maa peitti heidät; ja niin heidät hävitettiin seurakunnan keskeltä.'),
(1673150,58,4,16,34,'Ja koko Israel, joka oli heidän ympärillänsä, pakeni kuullessaan heidän huutonsa, sillä he pelkäsivät maan nielaisevan heidätkin.'),
(1673151,58,4,16,35,'Mutta tuli lähti Herran tyköä ja kulutti ne kaksisataa viisikymmentä miestä, jotka olivat tuoneet suitsutusta.'),
(1673152,58,4,16,36,'Ja Herra puhui Moosekselle sanoen:'),
(1673153,58,4,16,37,'"Käske Eleasaria, pappi Aaronin poikaa, korjaamaan nuo hiilipannut palosta, mutta pudistamaan tuli niistä kauas,'),
(1673154,58,4,16,38,'sillä ne ovat tulleet pyhäkön omiksi. Noiden henkensä menettäneiden syntisten hiilipannuista takokaa ohuita levyjä alttarin päällystämiseksi; sillä he toivat ne Herran eteen, ja niin ne tulivat pyhäkön omiksi ja merkiksi israelilaisille."'),
(1673155,58,4,16,39,'Niin pappi Eleasar otti ne vaskiset hiilipannut, jotka nuo tulen polttamat miehet olivat tuoneet, ja ne taottiin alttarin päällystykseksi,'),
(1673156,58,4,16,40,'muistuttamaan israelilaisille, ettei kukaan syrjäinen, joka ei ole Aaronin sukua, lähestyisi polttamaan suitsuketta Herran edessä, niin ettei hänen kävisi samoin kuin Koorahin ja hänen joukkonsa, niinkuin Herra oli hänelle Mooseksen kautta puhunut.'),
(1673157,58,4,16,41,'Mutta seuraavana päivänä kaikki israelilaisten seurakunta napisi Moosesta ja Aaronia vastaan sanoen: "Te olette surmanneet Herran kansaa".'),
(1673158,58,4,16,42,'Mutta kun kansa kokoontui Moosesta ja Aaronia vastaan, niin he kääntyivät ilmestysmajaan päin, ja katso, pilvi peitti sen, ja Herran kirkkaus näkyi.'),
(1673159,58,4,16,43,'Silloin Mooses ja Aaron menivät ilmestysmajan edustalle.'),
(1673160,58,4,16,44,'Ja Herra puhui Moosekselle sanoen:'),
(1673161,58,4,16,45,'"Poistukaa tämän joukon luota, niin minä tuokiossa heidät tuhoan". Silloin he lankesivat kasvoillensa.'),
(1673162,58,4,16,46,'Ja Mooses sanoi Aaronille: "Ota hiilipannu ja viritä siihen tuli alttarilta, pane siihen suitsuketta ja vie se nopeasti seurakunnan luo ja toimita heille sovitus, sillä viha on lähtenyt liikkeelle Herran tyköä, vitsaus on jo alkanut".'),
(1673163,58,4,16,47,'Ja Aaron teki, niinkuin Mooses oli käskenyt, ja riensi seurakunnan keskelle, ja katso, vitsaus oli jo alkanut kansan keskuudessa. Silloin hän suitsutti ja toimitti kansalle sovituksen.'),
(1673164,58,4,16,48,'Ja hänen siinä seisoessaan kuolleitten ja elävien vaiheella vitsaus taukosi.'),
(1673165,58,4,16,49,'Mutta niitä, jotka vitsauksesta kuolivat, oli neljätoista tuhatta seitsemänsataa henkeä, paitsi niitä, jotka saivat surmansa Koorahin tähden.'),
(1673166,58,4,16,50,'Sitten Aaron palasi takaisin Mooseksen luo ilmestysmajan ovelle, ja vitsaus oli tauonnut.'),
(1673167,58,4,17,1,'Ja Herra puhui Moosekselle sanoen:'),
(1673168,58,4,17,2,'"Puhu israelilaisille ja ota heiltä, kaikilta heidän ruhtinailtansa, sauva kutakin sukukuntaa kohti, heidän sukukuntiensa mukaan, kaksitoista sauvaa. Kirjoita kunkin nimi hänen sauvaansa,'),
(1673169,58,4,17,3,'mutta Leevin sauvaan kirjoita Aaronin nimi, sillä tämänkin sukukunnan päämiehellä olkoon sauvansa.'),
(1673170,58,4,17,4,'Pane ne sitten ilmestysmajaan lain arkin eteen, missä minä teille ilmestyn.'),
(1673171,58,4,17,5,'Ja tapahtuu, että kenen minä valitsen, sen sauva versoo. Siten minä lopetan israelilaisten napinan, niin että pääsen kuulemasta heidän napinaansa teitä vastaan."'),
(1673172,58,4,17,6,'Ja Mooses puhui tämän israelilaisille, ja kaikki heidän ruhtinaansa antoivat hänelle kukin sauvansa sukukunnittain, yhteensä kaksitoista sauvaa, ja Aaronin sauva oli heidän sauvainsa joukossa.'),
(1673173,58,4,17,7,'Ja Mooses pani sauvat lain majaan, Herran eteen.'),
(1673174,58,4,17,8,'Kun Mooses seuraavana päivänä meni lain majaan, niin katso, Aaronin sauva, joka oli siinä Leevin sukukunnan puolesta, oli alkanut versoa, siihen oli ilmestynyt silmuja, puhjennut kukkia ja kasvanut kypsiä manteleita.'),
(1673175,58,4,17,9,'Ja Mooses vei ulos kaikki sauvat Herran kasvojen edestä kaikkien israelilaisten tykö; ja he katselivat niitä ja ottivat kukin sauvansa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673176,58,4,17,10,'Ja Herra sanoi Moosekselle: "Vie Aaronin sauva takaisin lain arkin eteen säilytettäväksi merkkinä uppiniskaisille, ja lopeta heidän napinansa, niin että minä pääsen sitä kuulemasta, jotta he eivät kuolisi".'),
(1673177,58,4,17,11,'Ja Mooses teki sen; niinkuin Herra häntä käski, niin hän teki.'),
(1673178,58,4,17,12,'Mutta israelilaiset sanoivat Moosekselle näin: "Katso, me menehdymme, me hukumme, kaikki me hukumme!'),
(1673179,58,4,17,13,'Kuka vain lähestyy, kuka ikinä lähestyy Herran asumusta, se kuolee! Onko meidän kaikkien hukkuminen?"'),
(1673180,58,4,18,1,'Ja Herra sanoi Aaronille: "Sinun ja sinun poikiesi, isäsi suvun sinun kanssasi, on kannettava pyhäkköä vastaan tehdyt rikkomukset; samoin sinun ja poikiesi sinun kanssasi on kannettava pappeutta vastaan tehdyt rikkomukset.'),
(1673181,58,4,18,2,'Mutta salli myös veljiesi, Leevin sukukunnan, isäsi heimon, käydä sinun kanssasi sinne. He liittykööt sinuun ja palvelkoot sinua, kun sinä ja poikasi sinun kanssasi toimitatte palvelusta lain majan edessä.'),
(1673182,58,4,18,3,'Ja he hoitakoot sekä sinun tehtäviäsi että kaikkia majan tehtäviä, mutta älkööt lähestykö pyhiä esineitä tai alttaria, etteivät kuolisi, niin he kuin tekin.'),
(1673183,58,4,18,4,'Liittykööt he sinuun ja hoitakoot ilmestysmajan tehtävät, majan kaikki palvelustehtävät; mutta syrjäinen älköön teitä lähestykö.'),
(1673184,58,4,18,5,'Ja teidän on hoidettava tehtävät pyhäkössä ja alttarilla, ettei Herran viha enää kohtaisi israelilaisia.'),
(1673185,58,4,18,6,'Ja katso, minä olen ottanut teidän veljenne, leeviläiset, israelilaisten keskuudesta teille lahjaksi, Herralle annettuina toimittamaan palvelusta ilmestysmajassa.'),
(1673186,58,4,18,7,'Mutta sinä ja poikasi sinun kanssasi hoitakaa papinvirkaanne, pitäen huolta kaikista alttarilla ja esiripun sisäpuolella suoritettavista tehtävistä, ja toimittakaa palvelusta siellä. Lahjana minä annan teille papinvirkanne; mutta syrjäinen, joka siihen ryhtyy, surmattakoon."'),
(1673187,58,4,18,8,'Ja Herra puhui Aaronille: "Katso, minä annan sinulle sen, mikä saamistani anneista on talteen otettava; kaikista israelilaisten pyhistä lahjoista minä annan sen sinulle osuudeksi ja sinun pojillesi ikuiseksi oikeudeksi.'),
(1673188,58,4,18,9,'Korkeasti-pyhistä lahjoista olkoon sinun omasi tämä, jota ei tulessa polteta: kaikki ne heidän uhrilahjansa, jotka kuuluvat kaikkiin heidän ruokauhreihinsa, syntiuhreihinsa ja vikauhreihinsa, joita he suorittavat minulle korvauksena; se on korkeasti-pyhää ja olkoon sinun ja sinun poikiesi oma.'),
(1673189,58,4,18,10,'Syökää se korkeasti-pyhässä paikassa; jokainen miehenpuoli saakoon syödä sitä. Olkoon se sinulle pyhä.'),
(1673190,58,4,18,11,'Ja antina heidän lahjoistansa olkoon sinun omasi tämä: kaiken sen, minkä israelilaiset uhraavat heilutusmenoin, minä annan sinulle, sinun pojillesi ja tyttärillesi ikuiseksi oikeudeksi; jokainen, joka on puhdas sinun perheessäsi, saakoon syödä sitä.'),
(1673191,58,4,18,12,'Kaiken parhaan öljyn ja kaiken parhaan viinin ja viljan, minkä he uutisena antavat Herralle, sen minä annan sinulle.'),
(1673192,58,4,18,13,'Uutiset kaikesta, mitä heidän maassansa kasvaa ja minkä he tuovat Herralle, olkoot sinun omasi; jokainen, joka on puhdas sinun perheessäsi, saakoon syödä niitä.'),
(1673193,58,4,18,14,'Kaikki, mitä Israelissa vihittyä on, olkoon sinun omaasi.'),
(1673194,58,4,18,15,'Kaikki, mikä avaa äidinkohdun, mikä elollinen hyvänsä, joka tuodaan Herralle, ihmisistä tai karjasta, olkoon sinun omasi; lunastuta kuitenkin ihmisen esikoinen samoinkuin saastaisen eläimen esikoinen.'),
(1673195,58,4,18,16,'Ja mitä heidän lunastamiseensa tulee, niin lunastuta heidät kuukauden ikäisistä alkaen sinun asettamastasi viiden sekelin arviohinnasta pyhäkkösekelin painon mukaan, sekeli kaksikymmentä geeraa.'),
(1673196,58,4,18,17,'Mutta raavaan tai lampaan tai vuohen esikoista älä lunastuta; ne ovat pyhiä. Vihmo niiden veri alttarille ja polta niiden rasva uhriksi, suloiseksi tuoksuksi Herralle.'),
(1673197,58,4,18,18,'Mutta niiden liha olkoon sinun omasi; niinkuin heilutettu rintalihakin ja oikea reisi olkoon se sinun omasi.'),
(1673198,58,4,18,19,'Kaikki pyhät annit, joita israelilaiset antavat Herralle, minä annan sinulle, sinun pojillesi ja tyttärillesi ikuiseksi oikeudeksi. Se olkoon ikuinen suolaliitto Herran edessä sinulle ja sinun jälkeläisillesi."'),
(1673199,58,4,18,20,'Ja Herra puhui Aaronille: "Sinulla älköön olko perintöosaa heidän maassansa älköönkä osuutta heidän keskellänsä; minä itse olen sinun osuutesi ja perintöosasi israelilaisten keskellä.'),
(1673200,58,4,18,21,'Mutta leeviläisille minä annan kaikki kymmenykset Israelissa perintöosaksi, palkkana siitä palveluksesta, jonka he toimittavat ilmestysmajassa.'),
(1673201,58,4,18,22,'Älköötkä muut israelilaiset enää lähestykö ilmestysmajaa, että he eivät joutuisi syynalaisiksi ja kuolisi.'),
(1673202,58,4,18,23,'Ainoastaan leeviläiset toimittakoot palvelusta ilmestysmajassa ja kantakoot tehdyt rikkomukset; se olkoon teille ikuinen säädös sukupolvesta sukupolveen. Mutta heillä älköön olko perintöosaa israelilaisten keskellä.'),
(1673203,58,4,18,24,'Sillä israelilaisten kymmenykset, jotka he antavat Herralle anniksi, minä annan leeviläisille perintöosaksi; sentähden minä kiellän heiltä perintöosan israelilaisten keskuudessa."'),
(1673204,58,4,18,25,'Ja Herra puhui Moosekselle sanoen:'),
(1673205,58,4,18,26,'"Puhu leeviläisille ja sano: Kun te israelilaisilta otatte ne kymmenykset, jotka minä olen määrännyt heidän teille annettavaksi perintöosaksenne, niin antakaa siitä Herralle anti, kymmenykset kymmenyksistä,'),
(1673206,58,4,18,27,'ja se katsotaan teidän anniksenne, niinkuin puimatantereelta annetut jyvät tai kuurnasta tullut mehu.'),
(1673207,58,4,18,28,'Niin antakaa tekin Herralle anti kaikista kymmenyksistä, jotka te saatte israelilaisilta, ja tämä Herralle niistä tuleva anti antakaa pappi Aaronille.'),
(1673208,58,4,18,29,'Kaikista saamistanne lahjoista antakaa Herralle täysi anti; kaikesta, mikä parasta on, antakaa pyhä lahja.'),
(1673209,58,4,18,30,'Ja sano heille: Kun te siitä annatte parhaimman osan, niin se katsotaan leeviläisten anniksi niinkuin puimatantereen tai kuurnan sato.'),
(1673210,58,4,18,31,'Ja sen saatte te ja teidän perheenne syödä missä hyvänsä, sillä se on teille palkka palveluksestanne ilmestysmajassa.'),
(1673211,58,4,18,32,'Kun te näin annatte siitä anniksi parhaimman osan, ette joudu syynalaisiksi ettekä saastuta israelilaisten pyhiä lahjoja ettekä kuole."'),
(1673212,58,4,19,1,'Ja Herra puhui Moosekselle ja Aaronille sanoen:'),
(1673213,58,4,19,2,'"Tämä on lakimääräys, jonka Herra sääsi sanoen: Käske israelilaisia tuomaan sinulle ruskeanpunainen, virheetön hieho, jossa ei ole mitään vammaa ja jonka päälle iestä ei vielä ole pantu.'),
(1673214,58,4,19,3,'Antakaa se pappi Eleasarin haltuun, ja vietäköön se leiristä ulos ja teurastettakoon hänen edessänsä.'),
(1673215,58,4,19,4,'Sitten pappi Eleasar ottakoon sen verta sormeensa ja pirskoittakoon sen verta ilmestysmajan etupuolta kohti seitsemän kertaa.'),
(1673216,58,4,19,5,'Ja hieho poltettakoon hänen nähtensä; nahkoinensa, lihoinensa ja verinensä ynnä rapoinensa se poltettakoon.'),
(1673217,58,4,19,6,'Mutta pappi ottakoon setripuuta, isoppikorren ja helakanpunaista lankaa ja viskatkoon ne tuleen, missä hieho palaa.'),
(1673218,58,4,19,7,'Sitten pappi pesköön vaatteensa ja pesköön ruumiinsa vedessä; sitten menköön leiriin. Mutta pappi olkoon saastainen iltaan asti.'),
(1673219,58,4,19,8,'Sekin, joka hiehon poltti, pesköön vaatteensa vedessä ja pesköön ruumiinsa vedessä ja olkoon saastainen iltaan asti.'),
(1673220,58,4,19,9,'Sitten joku, joka on puhdas, kootkoon hiehon tuhan ja pankoon sen talteen leirin ulkopuolelle puhtaaseen paikkaan. Ja säilytettäköön se israelilaisten seurakunnalle puhdistusvettä varten. Tämä on syntiuhri.'),
(1673221,58,4,19,10,'Ja joka hiehon tuhan kokosi, pesköön vaatteensa ja olkoon saastainen iltaan asti. Tämä olkoon israelilaisille ja muukalaiselle, joka asuu heidän keskellänsä, ikuinen säädös.'),
(1673222,58,4,19,11,'Joka koskee kuolleen ihmisen ruumiiseen, kenen hyvänsä, olkoon saastainen seitsemän päivää.'),
(1673223,58,4,19,12,'Hän puhdistakoon itsensä tällä vedellä kolmantena ja seitsemäntenä päivänä, niin hän tulee puhtaaksi. Mutta jos hän ei puhdistaudu kolmantena ja seitsemäntenä päivänä, niin hän ei tule puhtaaksi.'),
(1673224,58,4,19,13,'Jokainen, joka koskee kuolleeseen, kuolleen ihmisen ruumiiseen, eikä puhdistaudu, hän saastuttaa Herran asumuksen, ja hänet hävitettäköön Israelista, koska puhdistusvettä ei ole vihmottu häneen; hän on saastainen, hänen saastaisuutensa pysyy hänessä yhä.'),
(1673225,58,4,19,14,'Tämä on laki: Kun joku kuolee telttamajassa, niin jokainen, joka menee siihen majaan, ja jokainen, joka on siinä majassa, olkoon saastainen seitsemän päivää.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673226,58,4,19,15,'Ja jokainen avoin astia, johon ei ole peitettä sidottu, olkoon saastainen.'),
(1673227,58,4,19,16,'Ja jokainen, joka ulkona kedolla koskee miekalla surmattuun tai muulla tavoin kuolleeseen tai ihmisluuhun tai hautaan, olkoon saastainen seitsemän päivää.'),
(1673228,58,4,19,17,'Mutta näin saastunutta varten otettakoon poltetun syntiuhrin tuhkaa ja kaadettakoon sen päälle astiaan raikasta vettä.'),
(1673229,58,4,19,18,'Ottakoon sitten joku, joka on puhdas, isoppikorren ja kastakoon sen siihen veteen ja pirskoittakoon sitä tuohon majaan ja kaikkiin sen esineihin ja ihmisiin, jotka siellä olivat, samoinkuin siihen, joka on koskenut luuhun tai surmattuun tai muulla tavoin kuolleeseen tai hautaan.'),
(1673230,58,4,19,19,'Ja se puhdas pirskoittakoon sitä saastuneeseen kolmantena ja seitsemäntenä päivänä ja puhdistakoon hänet seitsemäntenä päivänä. Sitten hän pesköön vaatteensa ja peseytyköön vedessä, niin hän tulee illalla puhtaaksi.'),
(1673231,58,4,19,20,'Mutta joka on saastunut eikä puhdistaudu, se hävitettäköön seurakunnasta, koska hän on saastuttanut Herran pyhäkön eikä puhdistusvettä ole vihmottu häneen; hän on saastainen.'),
(1673232,58,4,19,21,'Ja tämä olkoon heille ikuinen säädös. Mutta puhdistusveden pirskoittaja pesköön vaatteensa, ja se, joka koskee puhdistusveteen, olkoon saastainen iltaan asti.'),
(1673233,58,4,19,22,'Ja kaikki, mihin saastunut koskee, olkoon saastaista, ja se, joka koskee häneen, olkoon saastainen iltaan asti."'),
(1673234,58,4,20,1,'Senjälkeen israelilaiset, koko seurakunta, tulivat Siinin erämaahan ensimmäisenä kuukautena, ja kansa asettui Kaadekseen. Siellä Mirjam kuoli, ja hänet haudattiin sinne.'),
(1673235,58,4,20,2,'Mutta kansalla ei ollut vettä; niin he kokoontuivat Moosesta ja Aaronia vastaan.'),
(1673236,58,4,20,3,'Ja kansa riiteli Moosesta vastaan ja sanoi näin: "Jospa mekin olisimme hukkuneet silloin, kun veljemme hukkuivat Herran edessä!'),
(1673237,58,4,20,4,'Minkätähden toitte Herran seurakunnan tähän erämaahan, kuollaksemme karjoinemme tänne?'),
(1673238,58,4,20,5,'Ja minkätähden johdatitte meidät pois Egyptistä tuodaksenne meidät tähän pahaan paikkaan, jossa ei kasva viljaa eikä viikunoita, ei viiniköynnöksiä eikä granaattiomenia, ja jossa ei ole vettä juoda?"'),
(1673239,58,4,20,6,'Mutta Mooses ja Aaron menivät seurakunnan luota ilmestysmajan ovelle ja lankesivat kasvoilleen. Silloin näkyi Herran kirkkaus heille.'),
(1673240,58,4,20,7,'Ja Herra puhui Moosekselle sanoen:'),
(1673241,58,4,20,8,'"Ota sauva ja kokoa seurakunta, sinä ja veljesi Aaron, ja puhukaa heidän silmiensä edessä kalliolle, niin se antaa vettä, ja sinä saat vettä tulemaan heille kalliosta ja juotat joukon ja sen karjan".'),
(1673242,58,4,20,9,'Niin Mooses otti sauvan Herran kasvojen edestä, niinkuin hän oli häntä käskenyt.'),
(1673243,58,4,20,10,'Ja Mooses ja Aaron kokosivat seurakunnan kallion eteen, ja hän sanoi heille: "Kuulkaa nyt, te niskurit! Onko meidän saatava teille vettä tästä kalliosta?"'),
(1673244,58,4,20,11,'Niin Mooses nosti kätensä ja iski kalliota kahdesti sauvallansa, ja siitä lähti runsaasti vettä, niin että kansa ja sen karja saivat juoda.'),
(1673245,58,4,20,12,'Mutta Herra sanoi Moosekselle ja Aaronille: "Koska ette uskoneet minuun ettekä pitäneet minua pyhänä israelilaisten silmien edessä, niin te ette saa viedä tätä seurakuntaa siihen maahan, jonka minä heille annan".'),
(1673246,58,4,20,13,'Tämä oli Meriban vesi, jonka luona israelilaiset riitelivät Herraa vastaan ja hän näytti heille pyhyytensä.'),
(1673247,58,4,20,14,'Mutta Mooses lähetti Kaadeksesta sanansaattajat Edomin kuninkaan tykö sanomaan: "Näin sanoo veljesi Israel: Sinä tunnet kaiken vaivan, joka on meitä kohdannut,'),
(1673248,58,4,20,15,'kuinka isämme lähtivät Egyptiin, kuinka olemme asuneet Egyptissä kauan aikaa ja kuinka egyptiläiset kohtelivat pahoin meitä ja meidän isiämme.'),
(1673249,58,4,20,16,'Mutta me huusimme Herran puoleen, ja hän kuuli meidän huutomme ja lähetti enkelin, joka vei meidät pois Egyptistä. Ja katso, me olemme nyt Kaadeksessa, kaupungissa, joka on sinun maasi rajalla.'),
(1673250,58,4,20,17,'Salli meidän kulkea maasi läpi. Me emme kulje peltojen emmekä viinitarhojen poikki emmekä juo vettä kaivoista. Poikkeamatta oikealle tai vasemmalle me kuljemme valtatietä, kunnes olemme päässeet alueesi läpi."'),
(1673251,58,4,20,18,'Mutta Edom vastasi hänelle: "Älä kulje minun maani läpi; muutoin minä käyn miekka kädessä sinua vastaan".'),
(1673252,58,4,20,19,'Mutta israelilaiset sanoivat hänelle: "Maantietä me kuljemme, ja jos juomme vettäsi, me tai meidän karjamme, niin me maksamme sen, kun vain saamme jalkaisin kulkea sinun maasi läpi".'),
(1673253,58,4,20,20,'Mutta hän vastasi: "Tästä et kulje!" Ja Edom lähti häntä vastaan suurella sotajoukolla ja vahvasti varustettuna.'),
(1673254,58,4,20,21,'Kun siis Edom kielsi Israelia kulkemasta maansa läpi, niin Israel väistyi sieltä pois.'),
(1673255,58,4,20,22,'Ja he lähtivät liikkeelle Kaadeksesta. Ja israelilaiset, koko kansa, tulivat Hoorin vuorelle.'),
(1673256,58,4,20,23,'Mutta Herra sanoi Moosekselle ja Aaronille Hoorin vuorella, Edomin maan rajalla, näin:'),
(1673257,58,4,20,24,'"Aaron otetaan nyt pois heimonsa tykö, sillä hän ei pääse siihen maahan, jonka minä annan israelilaisille, koska te niskoittelitte minun käskyäni vastaan Meriban veden luona.'),
(1673258,58,4,20,25,'Ota Aaron ja hänen poikansa Eleasar ja vie heidät Hoorin vuorelle.'),
(1673259,58,4,20,26,'Ja riisu Aaronilta vaatteet ja pue ne hänen poikansa Eleasarin ylle. Aaron otetaan pois ja kuolee siellä."'),
(1673260,58,4,20,27,'Ja Mooses teki, niinkuin Herra oli käskenyt; ja he nousivat Hoorin vuorelle koko kansan silmien edessä.'),
(1673261,58,4,20,28,'Ja Mooses riisui Aaronilta vaatteet ja puki ne hänen poikansa Eleasarin ylle. Niin Aaron kuoli siellä vuoren huipulla, mutta Mooses ja Eleasar astuivat alas vuorelta.'),
(1673262,58,4,20,29,'Ja kun koko kansa sai tietää, että Aaron oli kuollut, niin he itkivät Aaronia kolmekymmentä päivää, koko Israelin heimo.'),
(1673263,58,4,21,1,'Mutta kun Aradin kuningas, kanaanilainen, joka asui Etelämaassa, kuuli, että Israel oli tulossa Atarimin tietä, ryhtyi hän sotimaan Israelia vastaan ja otti muutamia heistä vangiksi.'),
(1673264,58,4,21,2,'Silloin Israel teki lupauksen Herralle ja sanoi: "Jos sinä annat tämän kansan minun käsiini, niin minä vihin sen kaupungit tuhon omiksi".'),
(1673265,58,4,21,3,'Ja Herra kuuli, mitä Israel lausui, ja jätti kanaanilaiset hänen käsiinsä. Niin Israel vihki heidät ja heidän kaupunkinsa tuhon omiksi. Ja sen paikan nimeksi pantiin Horma.'),
(1673266,58,4,21,4,'Senjälkeen he lähtivät liikkeelle Hoorin vuorelta Kaislameren tietä kiertääksensä Edomin maan. Mutta matkalla kansa kävi kärsimättömäksi.'),
(1673267,58,4,21,5,'Ja kansa puhui Jumalaa ja Moosesta vastaan: "Minkätähden te johdatitte meidät pois Egyptistä kuolemaan erämaahan? Eihän täällä ole leipää eikä vettä, ja me olemme kyllästyneet tähän huonoon ruokaan."'),
(1673268,58,4,21,6,'Silloin Herra lähetti kansan sekaan myrkkykäärmeitä, jotka purivat kansaa, niin että paljon kansaa Israelista kuoli.'),
(1673269,58,4,21,7,'Niin kansa tuli Mooseksen luo, ja he sanoivat: "Me teimme syntiä, kun puhuimme Herraa ja sinua vastaan. Rukoile Herraa, että hän poistaa käärmeet meidän kimpustamme." Ja Mooses rukoili kansan puolesta.'),
(1673270,58,4,21,8,'Silloin Herra sanoi Moosekselle: "Tee itsellesi käärme ja pane se tangon päähän, niin jokainen purtu, joka siihen katsoo, jää eloon".'),
(1673271,58,4,21,9,'Niin Mooses teki vaskikäärmeen ja pani sen tangon päähän; jos ketä käärmeet sitten purivat ja tämä katsoi vaskikäärmeeseen, niin hän jäi eloon.'),
(1673272,58,4,21,10,'Sitten israelilaiset lähtivät liikkeelle ja leiriytyivät Oobotiin.'),
(1673273,58,4,21,11,'Ja he lähtivät liikkeelle Oobotista ja leiriytyivät Iije-Abarimiin siinä erämaassa, joka on Mooabista itään, auringon nousun puolella.'),
(1673274,58,4,21,12,'Sieltä he lähtivät liikkeelle ja leiriytyivät Seredin laaksoon.'),
(1673275,58,4,21,13,'Sieltä he lähtivät liikkeelle ja leiriytyivät erämaahan tuolle puolelle Arnon-jokea, joka lähtee amorilaisten alueelta; sillä Arnon on Mooabin rajana Mooabin ja amorilaisten maan välillä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673276,58,4,21,14,'Sentähden sanotaan "Herran sotien kirjassa": "Vaaheb Suufassa ja Arnonin laaksot'),
(1673277,58,4,21,15,'ja laaksojen rinteet, jotka ulottuvat Aarin tienoille ja kallistuvat Mooabin rajaan".'),
(1673278,58,4,21,16,'Ja sieltä he kulkivat Beeriin. Se oli se kaivo, josta Herra oli sanonut Moosekselle: "Kokoa kansa, niin minä annan heille vettä".'),
(1673279,58,4,21,17,'Silloin lauloi Israel tämän laulun: "Kuohu, kaivo! - laulakaa sille laulu -'),
(1673280,58,4,21,18,'kaivo, jonka ruhtinaat kaivoivat, kansan parhaat koversivat valtikallaan, sauvoillansa!" Ja siitä erämaasta he kulkivat Mattanaan'),
(1673281,58,4,21,19,'ja Mattanasta Nahalieliin ja Nahalielista Baamotiin'),
(1673282,58,4,21,20,'ja Baamotista siihen laaksoon, joka on Mooabin maassa, Pisgan huipun juurella, joka kohoaa yli erämaan.'),
(1673283,58,4,21,21,'Ja Israel lähetti sanansaattajat Siihonin, amorilaisten kuninkaan, tykö sanomaan:'),
(1673284,58,4,21,22,'"Salli minun kulkea maasi läpi. Me emme poikkea pelloille emmekä viinitarhoihin emmekä juo vettä kaivoista. Valtatietä me kuljemme, kunnes olemme päässeet sinun alueesi läpi."'),
(1673285,58,4,21,23,'Mutta Siihon ei sallinut Israelin kulkea alueensa läpi, vaan kokosi kaiken väkensä ja lähti Israelia vastaan erämaahan. Ja kun hän oli tullut Jahaaseen, ryhtyi hän taisteluun Israelia vastaan.'),
(1673286,58,4,21,24,'Mutta Israel voitti hänet miekan terällä ja valloitti hänen maansa Arnonista Jabbokiin, aina ammonilaisten maahan asti, sillä ammonilaisten raja oli varustettu.'),
(1673287,58,4,21,25,'Ja Israel valtasi sieltä kaikki kaupungit; ja Israel asettui kaikkiin amorilaisten kaupunkeihin, Hesboniin ja kaikkiin sen tytärkaupunkeihin.'),
(1673288,58,4,21,26,'Sillä Hesbon oli amorilaisten kuninkaan Siihonin kaupunki; hän oli näet käynyt sotaa entistä Mooabin kuningasta vastaan sekä vallannut häneltä kaiken hänen maansa Arnoniin asti.'),
(1673289,58,4,21,27,'Sentähden runosepät sanovat: "Tulkaa Hesboniin! Rakennettakoon ja varustettakoon Siihonin kaupunki.'),
(1673290,58,4,21,28,'Sillä tuli lähti Hesbonista, liekki Siihonin kaupungista; se kulutti Aar-Mooabin, Arnonin kukkulain valtiaat.'),
(1673291,58,4,21,29,'Voi sinua, Mooab! Sinä hukuit, Kemoksen kansa! Poikiensa hän salli tulla pakolaisiksi, tytärtensä amorilaisten kuninkaan Siihonin vangeiksi.'),
(1673292,58,4,21,30,'Me ammuimme heidät, Hesbon kukistui Diibonia myöten; me hävitimme Noofahiin asti, aina Meedebaan saakka."'),
(1673293,58,4,21,31,'Niin Israel asettui amorilaisten maahan.'),
(1673294,58,4,21,32,'Ja Mooses lähetti vakoilemaan Jaeseria, ja he valloittivat sen tytärkaupungit; ja hän karkoitti amorilaiset, jotka siellä olivat.'),
(1673295,58,4,21,33,'Sitten he kääntyivät toisaalle ja kulkivat Baasanin tietä. Silloin lähti Oog, Baasanin kuningas, heitä vastaan, hän ja kaikki hänen väkensä, Edreihin taistelemaan.'),
(1673296,58,4,21,34,'Mutta Herra sanoi Moosekselle: "Älä pelkää häntä, sillä minä annan sinun käteesi hänet ja kaiken hänen kansansa ja maansa. Ja tee hänelle, niinkuin teit Siihonille, amorilaisten kuninkaalle, joka asui Hesbonissa."'),
(1673297,58,4,21,35,'Ja he voittivat hänet ja hänen poikansa ja kaiken hänen väkensä, päästämättä pakoon ainoatakaan. Niin he valloittivat hänen maansa.'),
(1673298,58,4,22,1,'Sitten israelilaiset lähtivät liikkeelle ja leiriytyivät Mooabin arolle, Jordanin tuolle puolelle, Jerikon kohdalle.'),
(1673299,58,4,22,2,'Mutta Baalak, Sipporin poika, näki kaiken, mitä Israel oli tehnyt amorilaisille.'),
(1673300,58,4,22,3,'Ja Mooab pelkäsi tätä kansaa suuresti, kun sitä oli niin paljon; ja Mooab kauhistui israelilaisia.'),
(1673301,58,4,22,4,'Mooab sanoi Midianin vanhimmille: "Nyt tuo lauma syö puhtaaksi kaiken meidän ympäriltämme, niinkuin härkä syö kedon vihannuuden". Ja Baalak, Sipporin poika, oli Mooabin kuninkaana siihen aikaan.'),
(1673302,58,4,22,5,'Hän lähetti sanansaattajat Bileamin, Beorin pojan, tykö Petoriin, joka on Eufrat-virran varrella, heimolaistensa maahan, kutsumaan häntä ja käski sanoa hänelle: "Katso, Egyptistä on lähtenyt liikkeelle kansa; katso, se on tulvinut yli maan ja asettunut minua lähelle.'),
(1673303,58,4,22,6,'Tule siis ja kiroa minun puolestani tämä kansa, sillä se on minua väkevämpi; ehkä minä sitten saan sen voitetuksi ja karkoitetuksi maasta. Sillä minä tiedän, että jonka sinä siunaat, se on siunattu, ja jonka sinä kiroat, se on kirottu."'),
(1673304,58,4,22,7,'Niin Mooabin vanhimmat ja Midianin vanhimmat lähtivät matkaan, tietäjänpalkka mukanansa. Ja kun he saapuivat Bileamin luo, puhuivat he hänelle Baalakin sanat.'),
(1673305,58,4,22,8,'Hän vastasi heille: "Viipykää täällä tämä yö, niin minä annan teille vastauksen sen mukaan, kuin Herra minulle puhuu". Silloin jäivät mooabilaisten päämiehet Bileamin luo.'),
(1673306,58,4,22,9,'Niin Jumala tuli Bileamin tykö ja kysyi: "Keitä ovat ne miehet, jotka ovat sinun luonasi?"'),
(1673307,58,4,22,10,'Bileam vastasi Jumalalle: "Baalak, Sipporin poika, Mooabin kuningas, on lähettänyt heidät tuomaan minulle tämän sanan:'),
(1673308,58,4,22,11,'''Katso, kansa on lähtenyt Egyptistä ja on tulvinut yli maan; tule siis, kiroa se minun puolestani, ehkä sitten voin ryhtyä taisteluun sitä vastaan ja karkoittaa sen''".'),
(1673309,58,4,22,12,'Mutta Jumala sanoi Bileamille: "Älä mene heidän kanssaan äläkä kiroa sitä kansaa, sillä se on siunattu".'),
(1673310,58,4,22,13,'Niin Bileam nousi aamulla ja sanoi Baalakin päämiehille: "Menkää takaisin maahanne, sillä Herra ei ole sallinut minun lähteä teidän kanssanne".'),
(1673311,58,4,22,14,'Silloin nousivat Mooabin päämiehet ja tulivat Baalakin luo ja sanoivat: "Bileam ei suostunut lähtemään meidän kanssamme".'),
(1673312,58,4,22,15,'Mutta Baalak lähetti uudestaan päämiehiä matkaan, vielä useampia ja arvokkaampia kuin edelliset.'),
(1673313,58,4,22,16,'Ja he saapuivat Bileamin luo ja sanoivat hänelle: "Näin sanoo Baalak, Sipporin poika: ''Älä kieltäydy tulemasta minun luokseni.'),
(1673314,58,4,22,17,'Sillä minä palkitsen sinut ylenpalttisesti ja teen kaiken, mitä minulta vaadit; tule siis ja kiroa minun puolestani tämä kansa.''"'),
(1673315,58,4,22,18,'Mutta Bileam vastasi ja sanoi Baalakin palvelijoille: "Vaikka Baalak antaisi minulle talonsa täyden hopeata ja kultaa, en sittenkään voisi, en pienessä enkä suuressa, rikkoa Herran, minun Jumalani, käskyä.'),
(1673316,58,4,22,19,'Mutta jääkää nyt tänne tekin täksi yöksi, saadakseni tietää, mitä Herra vielä minulle sanoo."'),
(1673317,58,4,22,20,'Niin Jumala tuli Bileamin tykö yöllä ja sanoi hänelle: "Jos nämä miehet ovat tulleet kutsumaan sinua, niin nouse ja lähde heidän kanssaan, mutta tee vain se, mitä minä sinulle sanon".'),
(1673318,58,4,22,21,'Ja Bileam nousi aamulla, satuloi aasintammansa ja lähti matkaan Mooabin päämiesten kanssa.'),
(1673319,58,4,22,22,'Mutta kun hän lähti, syttyi Jumalan viha, ja Herran enkeli asettui tielle estämään häntä, hänen ratsastaessaan aasintammallaan, kaksi palvelijaa mukanansa.'),
(1673320,58,4,22,23,'Kun aasintamma näki Herran enkelin seisovan tiellä, paljastettu miekka kädessänsä, niin se poikkesi tieltä ja meni peltoon. Mutta Bileam löi aasintammaa palauttaaksensa sen tielle.'),
(1673321,58,4,22,24,'Sitten Herran enkeli asettui solaan viinitarhojen välille, jossa oli kiviaita kummallakin puolella.'),
(1673322,58,4,22,25,'Kun aasintamma näki Herran enkelin, niin se painautui aitaan ja likisti Bileamin jalkaa aitaa vasten. Ja hän löi sitä vielä kerran.'),
(1673323,58,4,22,26,'Silloin Herran enkeli taas meni edemmäs ja asettui ahtaaseen paikkaan, jossa ei ollut tilaa väistyä oikealle eikä vasemmalle.'),
(1673324,58,4,22,27,'Kun aasintamma näki Herran enkelin, laskeutui se maahan Bileamin alla. Silloin Bileamin viha syttyi, ja hän löi aasintammaa sauvalla.'),
(1673325,58,4,22,28,'Niin Herra avasi aasintamman suun, ja se sanoi Bileamille: "Mitä minä olen sinulle tehnyt, koska lyöt minua jo kolmannen kerran?"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673326,58,4,22,29,'Bileam vastasi aasintammalle: "Sinä olet pitänyt minua pilkkanasi. Olisipa minulla miekka kädessäni, niin nyt minä sinut tappaisin."'),
(1673327,58,4,22,30,'Mutta aasintamma sanoi Bileamille: "Enkö minä ole sinun aasintammasi, jolla olet ratsastanut kaiken aikasi tähän päivään asti? Onko minun ollut tapana tehdä sinulle näin?" Hän vastasi: "Ei".'),
(1673328,58,4,22,31,'Niin Herra avasi Bileamin silmät, niin että hän näki Herran enkelin seisovan tiellä, paljastettu miekka kädessänsä. Silloin hän kumartui ja heittäytyi kasvoilleen.'),
(1673329,58,4,22,32,'Niin Herran enkeli sanoi hänelle: "Minkätähden olet lyönyt aasintammaasi jo kolme kertaa? Katso, minä olen tullut sinua estämään, sillä ajattelemattomasti sinä olet lähtenyt tälle matkalle vastoin minun tahtoani.'),
(1673330,58,4,22,33,'Mutta aasintamma näki minut ja on väistynyt minun edestäni jo kolme kertaa. Ja jos se ei olisi väistynyt minun edestäni, niin minä olisin surmannut sinut, mutta jättänyt sen elämään."'),
(1673331,58,4,22,34,'Niin Bileam vastasi Herran enkelille: "Minä olen tehnyt syntiä; sillä minä en tiennyt, että sinä olit asettunut minua vastaan tielle. Mutta jos tämä ei ole sinulle mieleen, niin minä nyt palaan takaisin."'),
(1673332,58,4,22,35,'Mutta Herran enkeli sanoi Bileamille: "Mene näiden miesten kanssa, mutta puhu ainoastaan se, minkä minä sinulle puhun". Niin Bileam lähti Baalakin päämiesten kanssa.'),
(1673333,58,4,22,36,'Kun Baalak kuuli, että Bileam oli tulossa, meni hän häntä vastaan Iir-Mooabiin, joka on Arnonia pitkin kulkevalla rajalla, uloimmalla rajalla.'),
(1673334,58,4,22,37,'Ja Baalak sanoi Bileamille: "Enkö minä vartavasten lähettänyt kutsumaan sinua? Minkätähden et tahtonut tulla minun luokseni? Enkö minä muka voi sinua palkita?"'),
(1673335,58,4,22,38,'Mutta Bileam vastasi Baalakille: "Olenhan minä nyt tullut sinun luoksesi. Mutta onko minun vallassani puhua mitään? Minkä Jumala panee minun suuhuni, sen minä puhun."'),
(1673336,58,4,22,39,'Niin Bileam lähti Baalakin kanssa, ja he saapuivat Kirjat-Husotiin.'),
(1673337,58,4,22,40,'Ja Baalak teurasti raavaita ja lampaita ja lähetti ne Bileamille ja päämiehille, jotka olivat hänen luonansa.'),
(1673338,58,4,22,41,'Mutta seuraavana aamuna Baalak otti Bileamin mukaansa ja vei hänet Baamot-Baalin kukkulalle, josta hän näki reunimmaisen osan tuota kansaa.'),
(1673339,58,4,23,1,'Ja Bileam sanoi Baalakille: "Rakenna minulle tähän seitsemän alttaria ja hanki minulle tänne seitsemän härkää ja seitsemän oinasta".'),
(1673340,58,4,23,2,'Niin Baalak teki, niinkuin Bileam käski. Ja Baalak ja Bileam uhrasivat härän ja oinaan kullakin alttarilla.'),
(1673341,58,4,23,3,'Niin Bileam sanoi Baalakille: "Asetu tähän polttouhrisi ääreen, minä menen tuonne; ehkä minä saan kohdata Herran. Minkä hän minulle näyttää, sen minä ilmoitan sinulle." Ja hän meni eräälle autiolle kukkulalle.'),
(1673342,58,4,23,4,'Ja Jumala tuli ja kohtasi Bileamin. Silloin tämä sanoi hänelle: "Seitsemän alttaria minä olen pannut kuntoon ja olen uhrannut härän ja oinaan kullakin alttarilla".'),
(1673343,58,4,23,5,'Ja Herra pani sanat Bileamin suuhun ja sanoi: "Palaja Baalakin luo ja puhu hänelle näin".'),
(1673344,58,4,23,6,'Niin hän palasi hänen luoksensa, ja hän seisoi siinä polttouhrinsa ääressä, hän ja kaikki Mooabin päämiehet.'),
(1673345,58,4,23,7,'Niin hän puhkesi lausumaan ja sanoi: "Aramista nouti minut Baalak, idän vuorilta Mooabin kuningas: ''Tule, kiroa minun puolestani Jaakob, tule ja sadattele Israelia''.'),
(1673346,58,4,23,8,'Kuinka minä kiroaisin sen, jota ei Jumala kiroa, kuinka sadattelisin sitä, jota ei Herra sadattele?'),
(1673347,58,4,23,9,'Minä näen sen kallioiden huipulta, minä katselen sitä kukkuloilta: katso, se on erillään asuva kansa, se ei lukeudu pakanakansojen joukkoon.'),
(1673348,58,4,23,10,'Kuka mittaa Jaakobin hiekkajyväset, kuka Israelin tomuhiukkasten luvun? Suotakoon minun kuolla oikeamielisten kuolema, olkoon minun loppuni niinkuin heidän."'),
(1673349,58,4,23,11,'Silloin Baalak sanoi Bileamille: "Mitä oletkaan minulle tehnyt! Minä toin sinut tänne vihollisiani kiroamaan, ja katso, nyt sinä heidät siunaat!"'),
(1673350,58,4,23,12,'Mutta hän vastasi ja sanoi: "Eikö minun ole tarkoin puhuttava se, minkä Herra panee minun suuhuni?"'),
(1673351,58,4,23,13,'Niin Baalak sanoi hänelle: "Tule minun kanssani toiseen paikkaan, josta voit nähdä sen kansan, kuitenkin ainoastaan sen äärimmäisen reunan, et sitä kokonaisuudessaan, ja kiroa se minun puolestani sieltä".'),
(1673352,58,4,23,14,'Ja hän vei hänet Vartijakedolle Pisga-vuoren huipulle ja rakensi siihen seitsemän alttaria ja uhrasi härän ja oinaan kullakin alttarilla.'),
(1673353,58,4,23,15,'Sitten Bileam sanoi Baalakille: "Asetu tähän polttouhrisi ääreen, ehkä hän kohtaa minua tuolla".'),
(1673354,58,4,23,16,'Niin Herra tuli kohtaamaan Bileamia, pani sanat hänen suuhunsa ja sanoi: "Palaja Baalakin luo ja puhu hänelle näin".'),
(1673355,58,4,23,17,'Niin hän tuli hänen luoksensa, ja hän seisoi siinä polttouhrinsa ääressä, Mooabin päämiehet kanssansa. Baalak kysyi häneltä: "Mitä Herra puhui?"'),
(1673356,58,4,23,18,'Niin hän puhkesi lausumaan ja sanoi: "Nouse, Baalak, ja kuule! Kuuntele minua, sinä Sipporin poika!'),
(1673357,58,4,23,19,'Ei Jumala ole ihminen, niin että hän valhettelisi, eikä ihmislapsi, että hän katuisi. Sanoisiko hän jotakin eikä sitä tekisi, puhuisiko jotakin eikä sitä täyttäisi?'),
(1673358,58,4,23,20,'Katso, minä olen saanut tehtäväkseni siunata: hän on siunannut, enkä minä voi sitä peruuttaa.'),
(1673359,58,4,23,21,'Ei havaita vaivaa Jaakobissa eikä nähdä onnettomuutta Israelissa; Herra, hänen Jumalansa, on hänen kanssansa, riemuhuuto kuninkaalle kaikuu siellä.'),
(1673360,58,4,23,22,'Jumala vei sen pois Egyptistä; sen sarvet ovat kuin villihärän.'),
(1673361,58,4,23,23,'Sillä ei ole noituutta Jaakobissa eikä tavata taikuutta Israelissa. Aikanansa ilmoitetaan Jaakobille ja Israelille, mitä Jumala on tekevä.'),
(1673362,58,4,23,24,'Katso, se on kansa, joka nousee kuin naarasleijona, joka kohoaa kuin leijona. Ei se paneudu levolle, ennenkuin on saalista syönyt ja juonut surmattujen verta."'),
(1673363,58,4,23,25,'Mutta Baalak sanoi Bileamille: "Älä kiroa sitä äläkä siunaa sitä".'),
(1673364,58,4,23,26,'Mutta Bileam vastasi ja sanoi Baalakille: "Enkö minä puhunut sinulle näin: ''Kaikki, mitä Herra sanoo, on minun tehtävä''?"'),
(1673365,58,4,23,27,'Niin Baalak sanoi Bileamille: "Tule, minä vien sinut toiseen paikkaan; ehkäpä on Jumalan silmissä otollista, että kiroat kansan minun puolestani sieltä".'),
(1673366,58,4,23,28,'Ja Baalak vei Bileamin Peor-vuoren huipulle, joka kohoaa yli erämaan.'),
(1673367,58,4,23,29,'Sitten Bileam sanoi Baalakille: "Rakenna minulle tähän seitsemän alttaria ja hanki minulle tänne seitsemän härkää ja seitsemän oinasta".'),
(1673368,58,4,23,30,'Ja Baalak teki, niinkuin Bileam käski, ja uhrasi härän ja oinaan kullakin alttarilla.'),
(1673369,58,4,24,1,'Kun Bileam näki, että Israelin siunaaminen oli Herralle otollista, ei hän enää mennyt niinkuin aina ennen ennusmerkkejä etsimään, vaan käänsi kasvonsa erämaahan.'),
(1673370,58,4,24,2,'Ja kun Bileam nosti silmänsä ja näki Israelin leiriytyneenä heimokunnittain, niin Jumalan Henki tuli häneen.'),
(1673371,58,4,24,3,'Ja hän puhkesi lausumaan ja sanoi: "Näin puhuu Bileam, Beorin poika, näin puhuu mies, jonka silmä on avattu.'),
(1673372,58,4,24,4,'Näin puhuu hän, joka kuulee Jumalan puheen, joka näkee Kaikkivaltiaan näkyjä, joka lankeaa loveen ja jonka silmät avataan.'),
(1673373,58,4,24,5,'Kuinka ihanat ovat sinun majasi, Jaakob, sinun asuinsijasi, Israel!'),
(1673374,58,4,24,6,'Niinkuin laajat purolaaksot, niinkuin puutarhat virran varrella, niinkuin aloepuut, Herran istuttamat, niinkuin setripuut vesien vierillä!'),
(1673375,58,4,24,7,'Vettä läikkyy sen vesisangoista, ja sen laihot saavat runsaasti vettä. Agagia mahtavampi on sen kuningas, ylhäinen sen kuningasvalta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673376,58,4,24,8,'Jumala vei sen pois Egyptistä; sen sarvet ovat kuin villihärän. Se syö suuhunsa viholliskansat, heidän luunsa se murskaa ja lävistää heidät nuolillansa.'),
(1673377,58,4,24,9,'Se on kyyristynyt, se on laskeutunut maahan kuin leijona, niinkuin naarasleijona - kuka uskaltaa sitä häiritä? Siunattu olkoon, joka sinua siunaa, kirottu, joka sinua kiroaa!"'),
(1673378,58,4,24,10,'Silloin Baalak vihastui Bileamiin ja löi kätensä yhteen. Ja Baalak sanoi Bileamille: "Minä kutsuin sinut vihollisiani kiroamaan, ja nyt sinä olet siunannut heidät jo kolme kertaa.'),
(1673379,58,4,24,11,'Mene tiehesi! Minä aioin sinua runsaasti palkita, mutta katso, Herra on sinulta palkan kieltänyt."'),
(1673380,58,4,24,12,'Bileam vastasi Baalakille: "Enkö minä jo sanonut sinun sanansaattajillesi, jotka lähetit luokseni:'),
(1673381,58,4,24,13,'''Vaikka Baalak antaisi minulle talonsa täyden hopeata ja kultaa, en sittenkään voisi rikkoa Herran käskyä, en tehdä mitään oman mieleni mukaan, en hyvää, en pahaa''. Minkä Herra puhuu, sen minäkin puhun.'),
(1673382,58,4,24,14,'Ja nyt minä lähden kansani tykö, mutta sitä ennen minä ilmoitan sinulle, mitä tämä kansa on tekevä sinun kansallesi aikojen lopulla."'),
(1673383,58,4,24,15,'Ja hän puhkesi lausumaan ja sanoi: "Näin puhuu Bileam, Beorin poika, näin puhuu mies, jonka silmä on avattu.'),
(1673384,58,4,24,16,'Näin puhuu hän, joka kuulee Jumalan puheen ja saa tietonsa Korkeimmalta, joka näkee Kaikkivaltiaan näkyjä, joka lankeaa loveen ja jonka silmät avataan:'),
(1673385,58,4,24,17,'Minä näen hänet, en kuitenkaan nyt, minä katselen häntä, en kuitenkaan läheltä. Tähti nousee Jaakobista, ja valtikka kohoaa Israelista. Se ruhjoo Mooabilta ohimot, päälaen kaikilta Seetin pojilta.'),
(1673386,58,4,24,18,'Ja Edomista tulee alusmaa, Seir joutuu vihollistensa omaksi; mutta Israel tekee väkeviä tekoja.'),
(1673387,58,4,24,19,'Ja Jaakobista tulee valtias, hän hävittää kaupungeista niihin pelastuneet."'),
(1673388,58,4,24,20,'Ja kun hän näki Amalekin, niin hän puhkesi lausumaan ja sanoi: "Kansakunnista ensimmäinen on Amalek, mutta sen loppu on perikato".'),
(1673389,58,4,24,21,'Ja kun hän näki keeniläiset, niin hän puhkesi lausumaan ja sanoi: "Järkkymätön on sinun asumuksesi, ja kalliolle on pesäsi pantu.'),
(1673390,58,4,24,22,'Mutta sittenkin Kain hävitetään: ei aikaakaan, niin Assur vie sinut vangiksi."'),
(1673391,58,4,24,23,'Ja hän puhkesi lausumaan ja sanoi: "Voi! Kuka jää enää elämään, kun Jumala tämän tekee!'),
(1673392,58,4,24,24,'Laivoja saapuu kittiläisten suunnalta, ja ne kurittavat Assurin ja kurittavat Eeberin. Hänkin on perikadon oma."'),
(1673393,58,4,24,25,'Senjälkeen Bileam nousi, lähti matkaan ja palasi kotiinsa; ja myöskin Baalak lähti tiehensä.'),
(1673394,58,4,25,1,'Niin Israel asettui Sittimiin. Ja kansa rupesi irstailemaan Mooabin tyttärien kanssa.'),
(1673395,58,4,25,2,'Nämä kutsuivat kansaa jumaliensa uhreille, ja kansa söi ja kumarsi heidän jumaliansa.'),
(1673396,58,4,25,3,'Kun Israel näin antautui palvelemaan Baal-Peoria, syttyi Herran viha Israelia kohtaan.'),
(1673397,58,4,25,4,'Ja Herra sanoi Moosekselle: "Ota kansan kaikki päämiehet ja lävistä heidät paaluihin Herralle, vasten aurinkoa, että Herran vihan hehku kääntyisi pois Israelista".'),
(1673398,58,4,25,5,'Niin Mooses sanoi Israelin tuomareille: "Surmatkoon jokainen miehistään ne, jotka ovat antautuneet palvelemaan Baal-Peoria".'),
(1673399,58,4,25,6,'Ja katso, muuan mies israelilaisista tuli ja toi veljiensä luo midianilaisen naisen, Mooseksen ja kaiken israelilaisten seurakunnan nähden, kun nämä olivat itkemässä ilmestysmajan ovella.'),
(1673400,58,4,25,7,'Kun Piinehas, pappi Aaronin pojan Eleasarin poika, näki sen, nousi hän kansan keskeltä ja otti keihään käteensä'),
(1673401,58,4,25,8,'ja seurasi tuota Israelin miestä makuusuojaan ja lävisti heidät molemmat, Israelin miehen ja sen naisen, vatsan kohdalta. Silloin taukosi israelilaisilta vitsaus.'),
(1673402,58,4,25,9,'Ja niitä, jotka kuolivat tässä vitsauksessa, oli kaksikymmentäneljä tuhatta.'),
(1673403,58,4,25,10,'Ja Herra puhui Moosekselle sanoen:'),
(1673404,58,4,25,11,'"Piinehas, pappi Aaronin pojan Eleasarin poika, on kääntänyt minun vihani pois israelilaisista, kun hän on kiivaillut minun puolestani heidän keskuudessaan, niin ettei minun ole tarvinnut kiivaudessani tehdä loppua israelilaisista.'),
(1673405,58,4,25,12,'Sano siis: Katso, minä teen hänen kanssansa liiton hänen menestymiseksensä.'),
(1673406,58,4,25,13,'Ja se tulee hänelle ja hänen jälkeläisillensä ikuiseksi pappeuden liitoksi, koska hän kiivaili Jumalansa puolesta ja toimitti sovituksen israelilaisille."'),
(1673407,58,4,25,14,'Ja surmatun Israelin miehen nimi, sen, joka surmattiin midianilaisen naisen kanssa, oli Simri, simeonilaisen perhekunta-päämiehen Saalun poika.'),
(1673408,58,4,25,15,'Ja surmatun midianilais-naisen nimi oli Kosbi, Suurin, midianilaisen perhekunnan heimopäällikön, tytär.'),
(1673409,58,4,25,16,'Ja Herra puhui Moosekselle sanoen:'),
(1673410,58,4,25,17,'"Ahdistakaa midianilaisia ja tuhotkaa heidät.'),
(1673411,58,4,25,18,'Sillä he ahdistivat teitä viekkailla juonillansa, joilla he houkuttelivat teidät Peorin ja sisarensa Kosbin, midianilaisen päämiehen tyttären, ansaan, hänen, joka surmattiin Peorin vuoksi tapahtuneen vitsauksen päivänä."'),
(1673412,58,4,26,1,'Tämän vitsauksen jälkeen Herra puhui Moosekselle ja Eleasarille, pappi Aaronin pojalle, sanoen:'),
(1673413,58,4,26,2,'"Laskekaa koko israelilaisten seurakunnan väkiluku, kaksikymmenvuotiset ja sitä vanhemmat, perhekunnittain, kaikki Israelin sotakelpoiset miehet".'),
(1673414,58,4,26,3,'Ja Mooses ja pappi Eleasar puhuivat heille Mooabin arolla Jordanin luona, Jerikon kohdalla, sanoen:'),
(1673415,58,4,26,4,'"Kaksikymmenvuotiset ja sitä vanhemmat laskettakoon", niinkuin Herra oli Moosekselle käskyn antanut. Ja israelilaiset, jotka olivat lähteneet Egyptin maasta, olivat:'),
(1673416,58,4,26,5,'Ruuben, Israelin esikoinen; Ruubenin jälkeläisiä olivat: Hanokista hanokilaisten suku, Pallusta pallulaisten suku,'),
(1673417,58,4,26,6,'Hesronista hesronilaisten suku, Karmista karmilaisten suku.'),
(1673418,58,4,26,7,'Nämä olivat ruubenilaisten suvut. Ja katselmuksessa olleita oli heitä neljäkymmentäkolme tuhatta seitsemänsataa kolmekymmentä.'),
(1673419,58,4,26,8,'Ja Pallun poika oli Eliab.'),
(1673420,58,4,26,9,'Ja Eliabin pojat olivat Nemuel ja Daatan ja Abiram. Nämä olivat ne kansan edusmiehet Daatan ja Abiram, jotka taistelivat Moosesta ja Aaronia vastaan Koorahin joukossa ja taistelivat Herraa vastaan,'),
(1673421,58,4,26,10,'jolloin maa avasi kitansa ja nielaisi heidät ja Koorahin, silloin kun hänen joukkonsa kuoli ja tuli kulutti kaksisataa viisikymmentä miestä; ja heistä tuli varoitusmerkki.'),
(1673422,58,4,26,11,'Mutta Koorahin pojat eivät kuolleet.'),
(1673423,58,4,26,12,'Simeonin jälkeläisiä, sukujensa mukaan, olivat: Nemuelista nemuelilaisten suku, Jaaminista jaaminilaisten suku, Jaakinista jaakinilaisten suku,'),
(1673424,58,4,26,13,'Serahista serahilaisten suku, Saulista saulilaisten suku.'),
(1673425,58,4,26,14,'Nämä olivat simeonilaisten suvut, kaksikymmentäkaksi tuhatta kaksisataa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673426,58,4,26,15,'Gaadin jälkeläisiä, sukujensa mukaan, olivat: Sefonista sefonilaisten suku, Haggista haggilaisten suku, Suunista suunilaisten suku,'),
(1673427,58,4,26,16,'Osnista osnilaisten suku, Eeristä eeriläisten suku,'),
(1673428,58,4,26,17,'Arodista arodilaisten suku, Arelista arelilaisten suku.'),
(1673429,58,4,26,18,'Nämä olivat Gaadin jälkeläisten suvut; katselmuksessa olleita oli heitä neljäkymmentä tuhatta viisisataa.'),
(1673430,58,4,26,19,'Juudan poikia olivat Eer ja Oonan, mutta Eer ja Oonan kuolivat Kanaanin maassa.'),
(1673431,58,4,26,20,'Ja Juudan jälkeläisiä, sukujensa mukaan, olivat: Seelasta seelalaisten suku, Pereksestä perekseläisten suku, Serahista serahilaisten suku.'),
(1673432,58,4,26,21,'Ja Pereksen jälkeläisiä olivat: Hesronista hesronilaisten suku, Haamulista haamulilaisten suku.'),
(1673433,58,4,26,22,'Nämä olivat Juudan suvut; katselmuksessa olleita oli heitä seitsemänkymmentäkuusi tuhatta viisisataa.'),
(1673434,58,4,26,23,'Isaskarin jälkeläisiä, sukujensa mukaan, olivat: Toolasta toolalaisten suku, Puvvasta puunilaisten suku,'),
(1673435,58,4,26,24,'Jaasubista jaasubilaisten suku, Simronista simronilaisten suku.'),
(1673436,58,4,26,25,'Nämä olivat Isaskarin suvut; katselmuksessa olleita oli heitä kuusikymmentäneljä tuhatta kolmesataa.'),
(1673437,58,4,26,26,'Sebulonin jälkeläisiä, sukujensa mukaan, olivat: Seredistä serediläisten suku, Eelonista eelonilaisten suku, Jahlelista jahlelilaisten suku.'),
(1673438,58,4,26,27,'Nämä olivat sebulonilaisten suvut; katselmuksessa olleita oli heitä kuusikymmentä tuhatta viisisataa.'),
(1673439,58,4,26,28,'Joosefin jälkeläisiä, sukujensa mukaan, olivat Manasse ja Efraim.'),
(1673440,58,4,26,29,'Manassen jälkeläisiä olivat: Maakirista maakirilaisten suku. Ja Maakirille syntyi Gilead; Gileadista on gileadilaisten suku.'),
(1673441,58,4,26,30,'Nämä olivat Gileadin jälkeläisiä: Iieseristä iieseriläisten suku, Helekistä helekiläisten suku;'),
(1673442,58,4,26,31,'Asrielista asrielilaisten suku, Sekemistä sekemiläisten suku;'),
(1673443,58,4,26,32,'Semidasta semidalaisten suku, Heeferistä heeferiläisten suku.'),
(1673444,58,4,26,33,'Mutta Selofhadilla, Heeferin pojalla, ei ollut poikia, vaan ainoastaan tyttäriä. Ja Selofhadin tyttärien nimet olivat: Mahla, Nooga, Hogla, Milka ja Tirsa.'),
(1673445,58,4,26,34,'Nämä olivat Manassen suvut; katselmuksessa olleita oli heitä viisikymmentäkaksi tuhatta seitsemänsataa.'),
(1673446,58,4,26,35,'Ja nämä olivat Efraimin jälkeläisiä, sukujensa mukaan: Suutelahista suutelahilaisten suku, Bekeristä bekeriläisten suku, Tahanista tahanilaisten suku.'),
(1673447,58,4,26,36,'Nämä olivat Suutelahin jälkeläisiä: Eeranista eeranilaisten suku.'),
(1673448,58,4,26,37,'Nämä olivat efraimilaisten suvut; katselmuksessa olleita oli heitä kolmekymmentäkaksi tuhatta viisisataa. Nämä olivat Joosefin jälkeläiset sukujensa mukaan.'),
(1673449,58,4,26,38,'Benjaminin jälkeläisiä, sukujensa mukaan, olivat: Belasta belalaisten suku, Asbelista asbelilaisten suku, Ahiramista ahiramilaisten suku,'),
(1673450,58,4,26,39,'Sefufamista suufamilaisten suku, Huufamista huufamilaisten suku.'),
(1673451,58,4,26,40,'Mutta Belan jälkeläisiä olivat Ard ja Naaman: Ardista ardilaisten suku, Naamanista naamilaisten suku.'),
(1673452,58,4,26,41,'Nämä olivat Benjaminin jälkeläiset sukujensa mukaan; ja katselmuksessa olleita oli heitä neljäkymmentäviisi tuhatta kuusisataa.'),
(1673453,58,4,26,42,'Nämä olivat Daanin jälkeläisiä, sukujensa mukaan: Suuhamista suuhamilaisten suku. Nämä ovat Daanin suvut sukujensa mukaan.'),
(1673454,58,4,26,43,'Kaikista suuhamilaisten suvuista oli katselmuksessa olleita kuusikymmentäneljä tuhatta neljäsataa.'),
(1673455,58,4,26,44,'Asserin jälkeläisiä, sukujensa mukaan, olivat: Jimnasta jimnalaisten suku, Jisvistä jisviläisten suku, Beriasta berialaisten suku.'),
(1673456,58,4,26,45,'Berian jälkeläisiä olivat: Heeberistä heeberiläisten suku, Malkielista malkielilaisten suku.'),
(1673457,58,4,26,46,'Mutta Asserin tyttären nimi oli Serah.'),
(1673458,58,4,26,47,'Nämä olivat asserilaisten suvut; katselmuksessa olleita oli heitä viisikymmentäkolme tuhatta neljäsataa.'),
(1673459,58,4,26,48,'Naftalin jälkeläisiä, sukujensa mukaan, olivat: Jahselista jahselilaisten suku, Guunista guunilaisten suku;'),
(1673460,58,4,26,49,'Jeeseristä jeeseriläisten suku, Sillemistä sillemiläisten suku.'),
(1673461,58,4,26,50,'Nämä olivat Naftalin suvut sukujensa mukaan; ja katselmuksessa olleita oli heitä neljäkymmentäviisi tuhatta neljäsataa.'),
(1673462,58,4,26,51,'Nämä olivat katselmuksessa olleet israelilaiset: kuusisataayksi tuhatta seitsemänsataa kolmekymmentä.'),
(1673463,58,4,26,52,'Ja Herra puhui Moosekselle sanoen:'),
(1673464,58,4,26,53,'"Näille jaettakoon maa perintöosiksi nimien lukumäärän mukaan.'),
(1673465,58,4,26,54,'Isommalle suvulle anna isompi perintöosa ja pienemmälle pienempi perintöosa; kullekin annettakoon perintöosa katselmuksessa olleiden määrän mukaan.'),
(1673466,58,4,26,55,'Mutta maa jaettakoon arvalla. Isiensä heimojen nimien mukaan he saakoot perintöosansa.'),
(1673467,58,4,26,56,'Arvan määräyksen mukaan jaettakoon perintöosat suurilukuisten ja vähälukuisten heimojen kesken."'),
(1673468,58,4,26,57,'Ja nämä olivat Leevin katselmuksessa olleet, sukujensa mukaan: Geersonista geersonilaisten suku, Kehatista kehatilaisten suku, Merarista merarilaisten suku.'),
(1673469,58,4,26,58,'Nämä olivat leeviläisten suvut: libniläisten suku, hebronilaisten suku, mahlilaisten suku, muusilaisten suku, koorahilaisten suku. Ja Kehatille oli syntynyt Amram.'),
(1673470,58,4,26,59,'Ja Amramin vaimon nimi oli Jookebed, Leevin tytär, joka oli Leeville syntynyt Egyptissä. Ja hän synnytti Amramille Aaronin ja Mooseksen sekä heidän sisarensa Mirjamin.'),
(1673471,58,4,26,60,'Ja Aaronille syntyi Naadab ja Abihu, Eleasar ja Iitamar.'),
(1673472,58,4,26,61,'Mutta Naadab ja Abihu kuolivat, kun toivat vierasta tulta Herran eteen.'),
(1673473,58,4,26,62,'Ja katselmuksessa olleita oli heitä kaksikymmentäkolme tuhatta, kaikki miehenpuolia, kuukauden vanhoja ja sitä vanhempia. Sillä heistä ei pidetty katselmusta yhdessä muiden israelilaisten kanssa, koska heille ei annettu perintöosaa israelilaisten keskuudessa.'),
(1673474,58,4,26,63,'Nämä olivat siinä israelilaisten katselmuksessa, jonka Mooses ja pappi Eleasar pitivät Mooabin arolla lähellä Jordania, Jerikon kohdalla.'),
(1673475,58,4,26,64,'Eikä heidän joukossaan ollut ketään siinä israelilaisten katselmuksessa ollutta, jonka Mooses ja pappi Aaron olivat pitäneet Siinain erämaassa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673476,58,4,26,65,'Sillä Herra oli heille sanonut, että heidän oli kuoltava erämaassa. Eikä heistä jäänyt ketään, paitsi Kaaleb, Jefunnen poika, ja Joosua, Nuunin poika.'),
(1673477,58,4,27,1,'Niin astuivat esiin Selofhadin tyttäret - Selofhadin, Heeferin pojan, Gileadin pojan, Maakirin pojan, Manassen pojan, tyttäret - jotka olivat Manassen, Joosefin pojan, suvuista ja joiden nimet olivat Mahla, Nooga, Hogla, Milka ja Tirsa,'),
(1673478,58,4,27,2,'ja he asettuivat Mooseksen ja pappi Eleasarin ja päämiesten ja kaiken kansan eteen ilmestysmajan ovelle ja sanoivat:'),
(1673479,58,4,27,3,'"Meidän isämme kuoli erämaassa, mutta hän ei ollut siinä joukossa, joka kävi kapinoimaan Herraa vastaan, Koorahin joukossa, vaan hän kuoli oman syntinsä tähden, eikä hänellä ollut poikia.'),
(1673480,58,4,27,4,'Miksi häviäisi nyt meidän isämme nimi hänen sukunsa keskuudesta sentähden, että hänellä ei ollut poikaa? Anna meille perintöosuus isämme veljien keskuudessa."'),
(1673481,58,4,27,5,'Ja Mooses saattoi heidän asiansa Herran eteen.'),
(1673482,58,4,27,6,'Ja Herra puhui Moosekselle sanoen:'),
(1673483,58,4,27,7,'"Selofhadin tyttäret puhuvat oikein. Anna heille perintöosuus heidän isänsä veljien keskuudessa ja siirrä heidän isänsä perintöosa heille.'),
(1673484,58,4,27,8,'Ja puhu israelilaisille sanoen: Jos joku kuolee pojatonna, niin siirtäkää hänen perintöosansa hänen tyttärellensä.'),
(1673485,58,4,27,9,'Mutta jos hänellä ei ole tytärtä, niin antakaa hänen perintöosansa hänen veljillensä.'),
(1673486,58,4,27,10,'Mutta jos hänellä ei ole veljiä, niin antakaa hänen perintöosansa hänen isänsä veljille.'),
(1673487,58,4,27,11,'Mutta jos hänen isällänsä ei ole veljiä, niin antakaa hänen perintöosansa sille hänen veriheimolaisellensa, joka hänen suvussansa on häntä lähin; tämä ottakoon sen haltuunsa. Ja tämä olkoon oikeussäädöksenä israelilaisilla, niinkuin Herra on Moosekselle käskyn antanut."'),
(1673488,58,4,27,12,'Ja Herra sanoi Moosekselle: "Nouse tälle Abarimin vuorelle ja katsele sitä maata, jonka minä annan israelilaisille.'),
(1673489,58,4,27,13,'Ja kun olet sitä katsellut, niin sinutkin otetaan pois heimosi tykö, niinkuin veljesi Aaron otettiin,'),
(1673490,58,4,27,14,'sentähden että te Siinin erämaassa, kansan riidellessä, niskoittelitte minun käskyjäni vastaan ettekä pitäneet minua pyhänä heidän silmiensä edessä, silloin kun vettä hankitte." Se oli Meriban vesi Kaadeksessa Siinin erämaassa.'),
(1673491,58,4,27,15,'Ja Mooses puhui Herralle sanoen:'),
(1673492,58,4,27,16,'"Asettakoon Herra, Jumala, jonka vallassa on kaiken lihan henki, tämän seurakunnan johtoon miehen,'),
(1673493,58,4,27,17,'joka heidän edellänsä lähtee ja joka heidän edellänsä tulee, joka saattaa heidät lähtemään ja tulemaan, ettei Herran seurakunta olisi niinkuin lammaslauma, jolla ei ole paimenta".'),
(1673494,58,4,27,18,'Ja Herra sanoi Moosekselle: "Ota Joosua, Nuunin poika, mies, jossa on Henki, ja pane kätesi hänen päällensä.'),
(1673495,58,4,27,19,'Ja aseta hänet pappi Eleasarin ja kaiken kansan eteen ja aseta hänet virkaan heidän nähtensä.'),
(1673496,58,4,27,20,'Ja siirrä hänelle osa omaa arvoasi, että kaikki israelilaisten seurakunta häntä tottelisi.'),
(1673497,58,4,27,21,'Ja hän astukoon pappi Eleasarin eteen, ja tämä kysyköön hänen puolestaan uurimin kautta Jumalan vastausta Herran edessä. Hänen käskystänsä he lähtekööt ja hänen käskystänsä he tulkoot, hän ja kaikki israelilaiset hänen kanssansa, koko seurakunta."'),
(1673498,58,4,27,22,'Ja Mooses teki, niinkuin Herra oli häntä käskenyt, ja otti Joosuan ja asetti hänet pappi Eleasarin ja kaiken seurakunnan eteen.'),
(1673499,58,4,27,23,'Ja hän pani kätensä hänen päällensä ja asetti hänet virkaan, niinkuin Herra oli puhunut Mooseksen kautta.'),
(1673500,58,4,28,1,'Ja Herra puhui Moosekselle sanoen:'),
(1673501,58,4,28,2,'"Käske israelilaisia ja sano heille: Pitäkää vaari siitä, että tuotte minulle minun uhrilahjani, ruokani, suloisesti tuoksuvat uhrini, määräaikanaan.'),
(1673502,58,4,28,3,'Ja sano heille: Tämä on se uhri, joka teidän on tuotava joka päivä Herralle: kaksi vuoden vanhaa virheetöntä karitsaa jokapäiväiseksi polttouhriksi.'),
(1673503,58,4,28,4,'Uhraa toinen karitsa aamulla, ja toinen karitsa uhraa iltahämärässä'),
(1673504,58,4,28,5,'ja ruokauhriksi kymmenesosa eefa-mittaa lestyjä jauhoja, sekoitettuna neljännekseen hiin-mittaa survomalla saatua öljyä.'),
(1673505,58,4,28,6,'Tämä on jokapäiväinen polttouhri, joka toimitettiin Siinain vuorella suloisesti tuoksuvaksi uhriksi Herralle.'),
(1673506,58,4,28,7,'Ja siihen kuulukoon juomauhrina neljännes hiin-mittaa viiniä kumpaakin karitsaa kohti. Pyhäkössä vuodata Herralle höysteviiniuhri.'),
(1673507,58,4,28,8,'Ja toinen karitsa uhraa iltahämärässä ja toimita siihen kuuluva ruoka- ja juomauhri samalla tavoin kuin aamullakin, suloisesti tuoksuvaksi uhriksi Herralle.'),
(1673508,58,4,28,9,'Mutta sapatinpäivänä uhraa kaksi vuoden vanhaa virheetöntä karitsaa ynnä kaksi kymmenennestä lestyjä jauhoja, öljyyn sekoitettuna, ruokauhriksi, sekä siihen kuuluva juomauhri.'),
(1673509,58,4,28,10,'Tämä on sapatin polttouhri, joka uhrattakoon kunakin sapattina jokapäiväisen polttouhrin ja siihen kuuluvan juomauhrin ohella.'),
(1673510,58,4,28,11,'Ja kuukausienne ensimmäisenä päivänä tuokaa polttouhriksi Herralle kaksi mullikkaa, oinas ja seitsemän virheetöntä vuoden vanhaa karitsaa'),
(1673511,58,4,28,12,'sekä kolme kymmenennestä lestyjä jauhoja, öljyyn sekoitettuna, ruokauhriksi kutakin mullikkaa kohti ynnä kaksi kymmenennestä lestyjä jauhoja, öljyyn sekoitettuna, ruokauhriksi oinasta kohti,'),
(1673512,58,4,28,13,'sekä yksi kymmenennes lestyjä jauhoja, öljyyn sekoitettuna, ruokauhriksi kutakin karitsaa kohti. Tämä on polttouhri, suloisesti tuoksuva uhri Herralle.'),
(1673513,58,4,28,14,'Ja niihin kuulukoon juomauhrina puoli hiin-mittaa viiniä kutakin mullikkaa kohti ja kolmannes hiin-mittaa oinasta kohti ja neljännes hiin-mittaa karitsaa kohti. Tämä on uudenkuun polttouhri, joka uhrattakoon kunakin uutenakuuna, vuoden kaikkina kuukausina.'),
(1673514,58,4,28,15,'Ja sitäpaitsi uhratkaa yksi kauris syntiuhriksi Herralle. Se uhrattakoon jokapäiväisen polttouhrin ynnä siihen kuuluvan juomauhrin ohella.'),
(1673515,58,4,28,16,'Ja ensimmäisessä kuussa, kuukauden neljäntenätoista päivänä, on pääsiäinen Herran kunniaksi.'),
(1673516,58,4,28,17,'Ja saman kuukauden viidentenätoista päivänä on juhla; seitsemän päivää syötäköön happamatonta leipää.'),
(1673517,58,4,28,18,'Ensimmäisenä päivänä on pyhä kokous; älkää silloin yhtäkään arkiaskaretta toimittako.'),
(1673518,58,4,28,19,'Ja tuokaa polttouhriksi Herralle kaksi mullikkaa, oinas ja seitsemän vuodenvanhaa karitsaa; ne olkoot virheettömät.'),
(1673519,58,4,28,20,'Ja niihin kuuluvana ruokauhrina uhratkaa lestyjä jauhoja, öljyyn sekoitettuna, kolme kymmenennestä mullikkaa kohti ja kaksi kymmenennestä oinasta kohti.'),
(1673520,58,4,28,21,'Kutakin kohti niistä seitsemästä karitsasta uhratkaa kymmenennes.'),
(1673521,58,4,28,22,'Ja vielä uhratkaa kauris syntiuhriksi, joka tuottaa teille sovituksen.'),
(1673522,58,4,28,23,'Paitsi aamupolttouhria, joka on jokapäiväinen polttouhri, uhratkaa nämä.'),
(1673523,58,4,28,24,'Samoin uhratkaa Herralle joka päivä seitsemän päivän aikana leipää suloisesti tuoksuvaksi uhriksi; uhratkaa tämä jokapäiväisen polttouhrin ynnä siihen kuuluvan juomauhrin ohella.'),
(1673524,58,4,28,25,'Ja seitsemäntenä päivänä olkoon teillä pyhä kokous; älkää silloin yhtäkään arkiaskaretta toimittako.'),
(1673525,58,4,28,26,'Mutta uutisen päivänä, kun tuotte uuden ruokauhrin Herralle viikkojuhlananne, olkoon teillä pyhä kokous; älkää silloin yhtäkään arkiaskaretta toimittako.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673526,58,4,28,27,'Ja tuokaa suloisesti tuoksuvaksi polttouhriksi Herralle kaksi mullikkaa, oinas ja seitsemän vuodenvanhaa karitsaa'),
(1673527,58,4,28,28,'ja niihin kuuluvana ruokauhrina lestyjä jauhoja, öljyyn sekoitettuna, kolme kymmenennestä kutakin mullikkaa kohti, kaksi kymmenennestä oinasta kohti'),
(1673528,58,4,28,29,'ja yksi kymmenennes kutakin kohti niistä seitsemästä karitsasta;'),
(1673529,58,4,28,30,'ja yksi kauris sovittamiseksenne.'),
(1673530,58,4,28,31,'Paitsi jokapäiväistä polttouhria ja siihen kuuluvaa ruokauhria uhratkaa nämä ynnä niihin kuuluvat juomauhrit; eläimet olkoot virheettömät."'),
(1673531,58,4,29,1,'"Ja seitsemännessä kuussa, kuukauden ensimmäisenä päivänä, olkoon teillä pyhä kokous; älkää silloin yhtäkään arkiaskaretta toimittako. Olkoon se teille pasunansoiton päivä.'),
(1673532,58,4,29,2,'Ja uhratkaa suloisesti tuoksuvaksi polttouhriksi Herralle mullikka, oinas ja seitsemän vuodenvanhaa virheetöntä karitsaa'),
(1673533,58,4,29,3,'ja niihin kuuluvana ruokauhrina lestyjä jauhoja, öljyyn sekoitettuna, kolme kymmenennestä mullikkaa kohti, kaksi kymmenennestä oinasta kohti'),
(1673534,58,4,29,4,'ja yksi kymmenennes kutakin kohti niistä seitsemästä karitsasta;'),
(1673535,58,4,29,5,'ja kauris syntiuhriksi, teidän sovittamiseksenne.'),
(1673536,58,4,29,6,'Paitsi uudenkuun polttouhria ynnä siihen kuuluvaa ruokauhria ja jokapäiväistä polttouhria ynnä siihen kuuluvaa ruokauhria ja niihin kuuluvia juomauhreja, niinkuin niistä on säädetty, uhratkaa kaikki tämä suloisesti tuoksuvaksi uhriksi Herralle.'),
(1673537,58,4,29,7,'Ja saman seitsemännen kuun kymmenentenä päivänä olkoon teillä pyhä kokous, ja silloin kurittakaa itseänne paastolla, älkääkä yhtäkään askaretta toimittako.'),
(1673538,58,4,29,8,'Ja tuokaa suloisesti tuoksuvaksi polttouhriksi Herralle mullikka, oinas ja seitsemän vuodenvanhaa karitsaa; ne olkoot virheettömät.'),
(1673539,58,4,29,9,'Ja niihin kuulukoon ruokauhrina lestyjä jauhoja, öljyyn sekoitettuna, kolme kymmenennestä mullikkaa kohti, kaksi kymmenennestä oinasta kohti'),
(1673540,58,4,29,10,'ja yksi kymmenennes kutakin kohti niistä seitsemästä karitsasta;'),
(1673541,58,4,29,11,'ja kauris syntiuhriksi, paitsi sovitusuhria ja jokapäiväistä polttouhria ynnä niihin kuuluvia ruoka- ja juomauhreja.'),
(1673542,58,4,29,12,'Ja seitsemännen kuukauden viidentenätoista päivänä olkoon teillä pyhä kokous; älkää silloin yhtäkään arkiaskaretta toimittako, vaan viettäkää juhlaa Herran kunniaksi seitsemän päivää.'),
(1673543,58,4,29,13,'Ja tuokaa polttouhriksi, suloisesti tuoksuvaksi uhriksi Herralle, kolmetoista mullikkaa, kaksi oinasta ja neljätoista vuodenvanhaa karitsaa; olkoot ne virheettömät.'),
(1673544,58,4,29,14,'Ja kuulukoon niihin ruokauhrina lestyjä jauhoja, öljyyn sekoitettuna, kolme kymmenennestä kutakin kohti niistä kolmestatoista mullikasta, kaksi kymmenennestä kumpaakin kohti niistä kahdesta oinaasta'),
(1673545,58,4,29,15,'ja yksi kymmenennes kutakin kohti niistä neljästätoista karitsasta;'),
(1673546,58,4,29,16,'ja kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka- ja juomauhria.'),
(1673547,58,4,29,17,'Ja toisena päivänä: kaksitoista mullikkaa, kaksi oinasta ja neljätoista vuodenvanhaa, virheetöntä karitsaa'),
(1673548,58,4,29,18,'ja niihin kuuluvat ruoka- ja juomauhrit mullikkain, oinaiden ja karitsain luvun mukaan, niinkuin säädetty on,'),
(1673549,58,4,29,19,'sekä kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka- ja juomauhria.'),
(1673550,58,4,29,20,'Ja kolmantena päivänä: yksitoista mullikkaa, kaksi oinasta ja neljätoista vuodenvanhaa, virheetöntä karitsaa'),
(1673551,58,4,29,21,'ja niihin kuuluvat ruoka- ja juomauhrit mullikkain, oinaiden ja karitsain luvun mukaan, niinkuin säädetty on,'),
(1673552,58,4,29,22,'sekä kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka- ja juomauhria.'),
(1673553,58,4,29,23,'Ja neljäntenä päivänä: kymmenen mullikkaa, kaksi oinasta ja neljätoista vuodenvanhaa, virheetöntä karitsaa'),
(1673554,58,4,29,24,'ja niihin kuuluvat ruoka- ja juomauhrit mullikkain, oinaiden ja karitsain luvun mukaan, niinkuin säädetty on,'),
(1673555,58,4,29,25,'sekä kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka- ja juomauhria.'),
(1673556,58,4,29,26,'Ja viidentenä päivänä: yhdeksän mullikkaa, kaksi oinasta ja neljätoista vuodenvanhaa, virheetöntä karitsaa'),
(1673557,58,4,29,27,'ja niihin kuuluvat ruoka- ja juomauhrit mullikkain, oinaiden ja karitsain luvun mukaan, niinkuin säädetty on,'),
(1673558,58,4,29,28,'sekä kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka- ja juomauhria.'),
(1673559,58,4,29,29,'Ja kuudentena päivänä: kahdeksan mullikkaa, kaksi oinasta ja neljätoista vuodenvanhaa, virheetöntä karitsaa'),
(1673560,58,4,29,30,'ja niihin kuuluvat ruoka- ja juomauhrit mullikkain, oinaiden ja karitsain luvun mukaan, niinkuin säädetty on,'),
(1673561,58,4,29,31,'sekä kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka- ja juomauhria.'),
(1673562,58,4,29,32,'Ja seitsemäntenä päivänä: seitsemän mullikkaa, kaksi oinasta ja neljätoista vuodenvanhaa, virheetöntä karitsaa'),
(1673563,58,4,29,33,'ja niihin kuuluvat ruoka- ja juomauhrit mullikkain, oinaiden ja karitsain luvun mukaan, niinkuin säädetty on,'),
(1673564,58,4,29,34,'sekä kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka- ja juomauhria.'),
(1673565,58,4,29,35,'Ja kahdeksantena päivänä olkoon teillä juhlakokous; älkää silloin yhtäkään arkiaskaretta toimittako,'),
(1673566,58,4,29,36,'vaan tuokaa suloisesti tuoksuvaksi polttouhriksi Herralle mullikka, oinas ja seitsemän vuodenvanhaa, virheetöntä karitsaa'),
(1673567,58,4,29,37,'ja niihin kuuluvat ruoka- ja juomauhrit mullikan, oinaan ja karitsain luvun mukaan, niinkuin säädetty on,'),
(1673568,58,4,29,38,'sekä kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka- ja juomauhria.'),
(1673569,58,4,29,39,'Nämä uhratkaa Herralle juhla-aikoinanne, paitsi mitä lupausuhreinanne ja vapaaehtoisina lahjoinanne tuotte polttouhreiksi, ruokauhreiksi, juomauhreiksi ja yhteysuhreiksi."'),
(1673570,58,4,30,1,'Ja Mooses puhui israelilaisille kaiken, mitä Herra oli Mooseksen käskenyt puhua.'),
(1673571,58,4,30,2,'Ja Mooses puhui Israelin sukukuntien päämiehille sanoen: "Näin on Herra käskenyt:'),
(1673572,58,4,30,3,'Jos joku tekee lupauksen Herralle tahi valalla vannoen sitoutuu kieltäytymään jostakin, älköön hän rikkoko sanaansa, vaan tehköön kaiken, mitä hänen suunsa on sanonut.'),
(1673573,58,4,30,4,'Ja jos nainen ollessaan nuorena tyttönä isänsä kodissa tekee lupauksen Herralle tahi sitoutuu kieltäytymään jostakin'),
(1673574,58,4,30,5,'ja hänen isänsä kuulee hänen lupauksensa tai sitoumuksensa eikä hänen isänsä hänelle siitä mitään puhu, niin kaikki hänen lupauksensa ja kaikki hänen sitoumuksensa, joilla hän kieltäytyy jostakin, olkoot pätevät.'),
(1673575,58,4,30,6,'Mutta jos hänen isänsä kieltää häntä sinä päivänä, jona hän ne kuulee, niin hänen lupauksensa ja sitoumuksensa, joilla hän kieltäytyy jostakin, älkööt olko pätevät, olivatpa ne mitkä hyvänsä, ja Herra antaa hänelle anteeksi, sentähden että hänen isänsä on häntä kieltänyt.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673576,58,4,30,7,'Ja jos hän joutuu miehelle ja hänellä on täytettävänä lupauksia tai ajattelemattomasti lausuttu sana, jolla hän on kieltäytynyt jostakin,'),
(1673577,58,4,30,8,'ja hänen miehensä saa sen kuulla, mutta ei puhu hänelle siitä mitään sinä päivänä, jona hän sen kuulee, niin hänen lupauksensa ja hänen sitoumuksensa, joilla hän on kieltäytynyt jostakin, olkoot pätevät.'),
(1673578,58,4,30,9,'Mutta jos hänen miehensä sinä päivänä, jona hän sen kuulee, kieltää häntä, niin hän purkaa hänen lupauksensa, jonka täyttämiseen hän on sitoutunut, ja sen ajattelemattomasti lausutun sanan, jolla hän on kieltäytynyt jostakin, ja Herra antaa hänelle anteeksi.'),
(1673579,58,4,30,10,'Mutta lesken tai hyljätyn lupaus, mihin hyvänsä hän onkin sitoutunut, olkoon pätevä.'),
(1673580,58,4,30,11,'Ja jos vaimo on miehensä kodissa tehnyt lupauksen tahi valalla sitoutunut kieltäytymään jostakin'),
(1673581,58,4,30,12,'ja hänen miehensä saa sen kuulla, mutta ei puhu hänelle siitä mitään eikä kiellä häntä, niin kaikki hänen lupauksensa ja kaikki sitoumukset, joilla hän on kieltäytynyt jostakin, olkoot pätevät.'),
(1673582,58,4,30,13,'Mutta jos hänen miehensä ne purkaa sinä päivänä, jona hän niistä kuulee, älköön yksikään hänen huuliltaan lähtenyt lupaus tai sitoumus olko pätevä. Hänen miehensä on ne purkanut, ja Herra antaa hänelle anteeksi.'),
(1673583,58,4,30,14,'Jokaisen lupauksen ja jokaisen valallisen sitoumuksen, jonka vaimo itsensä kurittamiseksi tekee, saakoon hänen miehensä joko vahvistaa tahi purkaa.'),
(1673584,58,4,30,15,'Mutta jos hänen miehensä ei puhu hänelle niistä mitään sen päivän kuluessa, niin hän on vahvistanut kaikki hänen lupauksensa ja kaikki hänen sitoumuksensa, jotka hänellä on täytettävinä. Hän on ne vahvistanut, koska hän ei niistä hänelle mitään puhunut sinä päivänä, jona hän niistä kuuli.'),
(1673585,58,4,30,16,'Mutta jos hän ne purkaa vasta jonkun aikaa sen jälkeen, kuin on niistä kuullut, joutuu hän kantamaan vaimonsa syyllisyyden."'),
(1673586,58,4,30,17,'Nämä ovat ne säädökset, jotka Herra antoi Moosekselle, olemaan voimassa miehen ja hänen vaimonsa välillä sekä isän ja hänen tyttärensä välillä, tämän ollessa nuorena tyttönä isänsä kodissa.'),
(1673587,58,4,31,1,'Ja Herra puhui Moosekselle sanoen:'),
(1673588,58,4,31,2,'"Kosta israelilaisten puolesta midianilaisille. Senjälkeen sinut otetaan pois heimosi tykö."'),
(1673589,58,4,31,3,'Niin Mooses puhui kansalle sanoen: "Varustakaa joukostanne miehiä sotaan, ja lähtekööt he Midiania vastaan toimittamaan Herran koston Midianille.'),
(1673590,58,4,31,4,'Tuhat miestä jokaisesta sukukunnasta, kaikista Israelin sukukunnista, lähettäkää sotaan."'),
(1673591,58,4,31,5,'Silloin annettiin Israelin heimoista tuhat miestä jokaisesta sukukunnasta, yhteensä kaksitoista tuhatta sotaan varustettua miestä.'),
(1673592,58,4,31,6,'Ja Mooses lähetti heidät, tuhat miestä jokaisesta sukukunnasta, sotaan sekä heidän kanssaan Piinehaan, pappi Eleasarin pojan; tällä oli mukanaan pyhät esineet ja hälytystorvet.'),
(1673593,58,4,31,7,'Niin he lähtivät sotimaan Midiania vastaan, niinkuin Herra oli Moosekselle käskyn antanut, ja surmasivat kaikki miehenpuolet.'),
(1673594,58,4,31,8,'Muiden mukana, jotka kaatuivat, he surmasivat Midianin kuninkaat Evin, Rekemin, Suurin, Huurin ja Reban, Midianin viisi kuningasta. Myös Bileamin, Beorin pojan, he surmasivat miekalla.'),
(1673595,58,4,31,9,'Mutta israelilaiset ottivat vangiksi midianilaisten vaimot ja lapset ja ryöstivät kaikki heidän juhtansa ja kaiken heidän karjansa ja kaiken heidän tavaransa.'),
(1673596,58,4,31,10,'Ja kaikki heidän asumansa kaupungit ja kaikki heidän leiripaikkansa he polttivat tulella.'),
(1673597,58,4,31,11,'Ja he ottivat kaiken ryöstettävän ja kaiken otettavan, sekä ihmiset että karjan.'),
(1673598,58,4,31,12,'Ja he toivat Moosekselle ja pappi Eleasarille sekä Israelin kansalle vangit ja ottamansa ja ryöstämänsä saaliin leiriin Mooabin arolle, joka on Jordanin luona, Jerikon kohdalla.'),
(1673599,58,4,31,13,'Silloin Mooses ja pappi Eleasar ja kaikki kansan päämiehet lähtivät heitä vastaan leirin ulkopuolelle.'),
(1673600,58,4,31,14,'Ja Mooses vihastui sotajoukon johtajiin, tuhannen- ja sadanpäämiehiin, kun he palasivat sotaretkeltä.'),
(1673601,58,4,31,15,'Ja Mooses sanoi heille: "Oletteko siis jättäneet henkiin kaikki naiset?'),
(1673602,58,4,31,16,'Katso, nehän ne olivat, jotka Bileamin neuvosta saivat israelilaiset antautumaan uskottomuuteen Herraa vastaan Peorin vuoksi, niin että vitsaus kohtasi Herran seurakuntaa.'),
(1673603,58,4,31,17,'Niin surmatkaa siis kaikki poikalapset ja surmatkaa myös jokainen vaimo, joka on yhtynyt mieheen.'),
(1673604,58,4,31,18,'Mutta jokainen tyttö, joka ei ole yhtynyt mieheen, jättäkää itsellenne henkiin.'),
(1673605,58,4,31,19,'Mutta itse oleskelkaa leirin ulkopuolella seitsemän päivää. Jokainen teistä, joka on jonkun surmannut, ja jokainen teistä, joka on koskenut surmattuun, puhdistautukoon kolmantena ja seitsemäntenä päivänä, sekä te että teidän vankinne.'),
(1673606,58,4,31,20,'Ja puhdistettakoon jokainen vaate ja jokainen nahkaesine ja kaikki, mikä on tehty vuohen karvoista, ja jokainen puuesine."'),
(1673607,58,4,31,21,'Ja pappi Eleasar sanoi sotamiehille, jotka olivat menneet sotaan: "Tämä on lakisäädös, jonka Herra antoi Moosekselle:'),
(1673608,58,4,31,22,'Vain kulta, hopea, vaski, rauta, tina ja lyijy,'),
(1673609,58,4,31,23,'kaikki, mikä tulta kestää, käyttäkää tulessa, niin se puhdistuu; puhdistettakoon se kuitenkin vielä puhdistusvedellä. Mutta mikä ei tulta kestä, käyttäkää se vedessä.'),
(1673610,58,4,31,24,'Ja peskää vaatteenne seitsemäntenä päivänä, niin te puhdistutte; ja sitten tulkaa leiriin."'),
(1673611,58,4,31,25,'Ja Herra puhui Moosekselle sanoen:'),
(1673612,58,4,31,26,'"Laskekaa, sinä ja pappi Eleasar ja kansan perhekuntien päämiehet, otetun saaliin määrä, ihmiset ja karja.'),
(1673613,58,4,31,27,'Ja pane saalis kahtia soturien, sotaan lähteneiden, ja kaiken muun kansan kesken.'),
(1673614,58,4,31,28,'Ja ota Herralle verona sotamiehiltä, sotaan lähteneiltä, yksi viidestäsadasta, ihmisiä, raavaita, aaseja ja lampaita.'),
(1673615,58,4,31,29,'Ota se heille tulevasta puoliskosta ja anna se pappi Eleasarille antina Herralle.'),
(1673616,58,4,31,30,'Ja israelilaisille tulevasta puoliskosta ota yksi viidestäkymmenestä, ihmisiä, raavaita, aaseja, lampaita ja kaikkia karjaeläimiä, ja anna ne leeviläisille, joiden on hoidettava tehtävät Herran asumuksessa."'),
(1673617,58,4,31,31,'Ja Mooses ja pappi Eleasar tekivät, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1673618,58,4,31,32,'Ja saalis, jäännös siitä, mitä sotajoukko oli ryöstänyt, oli: lampaita kuusisataa seitsemänkymmentäviisi tuhatta'),
(1673619,58,4,31,33,'ja raavaita seitsemänkymmentäkaksi tuhatta'),
(1673620,58,4,31,34,'ja aaseja kuusikymmentäyksi tuhatta'),
(1673621,58,4,31,35,'ja ihmisiä, tyttöjä, jotka eivät olleet yhtyneet mieheen, kaikkiaan kolmekymmentäkaksi tuhatta.'),
(1673622,58,4,31,36,'Ja puolet siitä eli se osa, joka tuli sotaan lähteneille, oli: lampaita kolmesataa kolmekymmentäseitsemän tuhatta viisisataa,'),
(1673623,58,4,31,37,'ja Herralle tuleva vero lampaista oli kuusisataa seitsemänkymmentä viisi;'),
(1673624,58,4,31,38,'ja raavaita kolmekymmentäkuusi tuhatta sekä niistä Herralle tuleva vero seitsemänkymmentä kaksi;'),
(1673625,58,4,31,39,'ja aaseja kolmekymmentä tuhatta viisisataa sekä niistä Herralle tuleva vero kuusikymmentä yksi;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673626,58,4,31,40,'ja ihmisiä kuusitoista tuhatta sekä niistä Herralle tuleva vero kolmekymmentä kaksi.'),
(1673627,58,4,31,41,'Ja Mooses antoi Herran antiveron pappi Eleasarille, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1673628,58,4,31,42,'Ja israelilaisille tuleva puolisko, jonka Mooses oli erottanut sotamiesten osasta,'),
(1673629,58,4,31,43,'tämä seurakunnalle tuleva puolisko oli: lampaita kolmesataa kolmekymmentäseitsemän tuhatta viisisataa'),
(1673630,58,4,31,44,'ja raavaita kolmekymmentäkuusi tuhatta'),
(1673631,58,4,31,45,'ja aaseja kolmekymmentä tuhatta viisisataa'),
(1673632,58,4,31,46,'sekä ihmisiä kuusitoista tuhatta.'),
(1673633,58,4,31,47,'Tästä israelilaisille tulevasta puoliskosta Mooses otti yhden viidestäkymmenestä, ihmisiä ja karjaa, sekä antoi ne leeviläisille, joiden oli hoidettava tehtävät Herran asumuksessa, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1673634,58,4,31,48,'Silloin tulivat sotajoukon osastojen johtajat, tuhannen- ja sadanpäämiehet, Mooseksen luo'),
(1673635,58,4,31,49,'ja sanoivat Moosekselle: "Palvelijasi ovat laskeneet niiden sotamiesten luvun, jotka ovat olleet hallussamme, eikä meistä puutu yhtäkään.'),
(1673636,58,4,31,50,'Sentähden me tuomme nyt Herralle lahjaksi, mitä kukin on saanut kultakaluja: käätyjä, rannerenkaita, sormuksia, korvarenkaita ja kaulakoristeita, saadaksemme itsellemme sovituksen Herran edessä."'),
(1673637,58,4,31,51,'Niin Mooses ja pappi Eleasar ottivat heiltä kullan, kaikkinaiset taidokkaasti valmistetut esineet.'),
(1673638,58,4,31,52,'Ja anniksi annettua kultaa, jonka he antoivat Herralle tuhannen- ja sadanpäämiesten puolesta, oli kaikkiaan kuusitoista tuhatta seitsemänsataa viisikymmentä sekeliä.'),
(1673639,58,4,31,53,'Sotamiehet olivat ottaneet saalista kukin itselleen.'),
(1673640,58,4,31,54,'Ja Mooses ja pappi Eleasar ottivat kullan tuhannen- ja sadanpäämiehiltä ja veivät sen ilmestysmajaan, että se johdattaisi israelilaiset Herran muistoon.'),
(1673641,58,4,32,1,'Mutta ruubenilaisilla ja gaadilaisilla oli paljon, ylen runsaasti, karjaa. Kun he nyt katselivat Jaeserin maata ja Gileadin maata, niin he huomasivat, että seutu oli karjanhoitoon sopiva.'),
(1673642,58,4,32,2,'Niin gaadilaiset ja ruubenilaiset tulivat ja puhuivat Moosekselle ja pappi Eleasarille ja seurakunnan päämiehille sanoen:'),
(1673643,58,4,32,3,'"Atarot, Diibon, Jaeser, Nimra, Hesbon, Elale, Sebam, Nebo ja Beon,'),
(1673644,58,4,32,4,'tämä maa, jonka Herra on vallannut Israelin seurakunnalle, on karjanhoitoon sopivaa maata, ja sinun palvelijoillasi on karjaa".'),
(1673645,58,4,32,5,'Ja he sanoivat vielä: "Jos olemme saaneet armon sinun silmiesi edessä, niin annettakoon tämä maa palvelijoillesi omaksi, äläkä vie meitä Jordanin yli".'),
(1673646,58,4,32,6,'Mutta Mooses vastasi gaadilaisille ja ruubenilaisille: "Onko teidän veljienne lähdettävä sotaan, ja te jäisitte tänne?'),
(1673647,58,4,32,7,'Miksi viette israelilaisilta halun mennä siihen maahan, jonka Herra on heille antanut?'),
(1673648,58,4,32,8,'Niin teidän isännekin tekivät, kun minä lähetin heidät Kaades-Barneasta katselemaan sitä maata.'),
(1673649,58,4,32,9,'Kun he olivat saapuneet Rypälelaaksoon asti ja katselleet sitä maata, veivät he israelilaisilta halun lähteä siihen maahan, jonka Herra oli heille antanut.'),
(1673650,58,4,32,10,'Ja sinä päivänä syttyi Herran viha, ja hän vannoi sanoen:'),
(1673651,58,4,32,11,'''Ne miehet, jotka lähtivät Egyptistä, kaksikymmenvuotiset ja sitä vanhemmat, eivät saa nähdä sitä maata, jonka minä vannoen lupasin Aabrahamille, Iisakille ja Jaakobille, sillä he eivät ole minua uskollisesti seuranneet,'),
(1673652,58,4,32,12,'paitsi Kaaleb, kenissiläisen Jefunnen poika, ja Joosua, Nuunin poika; sillä nämä ovat uskollisesti seuranneet Herraa''.'),
(1673653,58,4,32,13,'Ja Herran viha syttyi Israelia kohtaan, ja hän antoi heidän harhailla erämaassa neljäkymmentä vuotta, kunnes koko se sukupolvi hävisi, joka oli tehnyt sitä, mikä oli pahaa Herran silmissä.'),
(1673654,58,4,32,14,'Mutta katso, te olette nyt astuneet isienne sijaan, te syntisten sikiöt, lisätäksenne vielä Herran vihan kiivautta Israelia kohtaan.'),
(1673655,58,4,32,15,'Jos te nyt käännytte pois hänestä, niin hän jättää kansan vielä kauemmaksi aikaa tähän erämaahan, ja niin te tuotatte tuhon kaikelle tälle kansalle."'),
(1673656,58,4,32,16,'Niin he lähestyivät häntä ja sanoivat: "Karjatarhoja me vain rakentaisimme tänne laumoillemme ja kaupunkeja vaimojamme ja lapsiamme varten,'),
(1673657,58,4,32,17,'mutta itse me varustautuisimme ja rientäisimme israelilaisten etunenässä, kunnes saisimme viedyksi heidät määräpaikkoihinsa, mutta meidän vaimomme ja lapsemme asuisivat sillä aikaa varustetuissa kaupungeissa maan asukkailta rauhassa.'),
(1673658,58,4,32,18,'Emme me palaisi kotiimme, ennenkuin israelilaiset ovat saaneet haltuunsa kukin perintöosansa,'),
(1673659,58,4,32,19,'sillä me emme tahdo perintöosaa heidän kanssansa tuolta puolen Jordanin emmekä kauempaa, vaan meidän perintöosamme on joutunut meille tältä puolelta Jordanin, itään päin."'),
(1673660,58,4,32,20,'Niin Mooses vastasi heille: "Jos näin teette, jos Herran edessä varustaudutte sotaan'),
(1673661,58,4,32,21,'ja teistä jokainen, sotaan varustettuna, menee Jordanin yli Herran edessä niin pitkäksi aikaa, kunnes on karkoittanut vihollisensa edestään,'),
(1673662,58,4,32,22,'ja te palaatte vasta senjälkeen, kuin se maa on tehty alamaiseksi Herralle, niin te olette vastuusta vapaat Herran ja Israelin edessä, ja tämä maa tulee teidän omaksenne Herran edessä.'),
(1673663,58,4,32,23,'Mutta jos ette näin tee, niin katso, te rikotte Herraa vastaan ja saatte tuntea syntinne palkan, joka kohtaa teitä.'),
(1673664,58,4,32,24,'Rakentakaa siis itsellenne kaupunkeja vaimojanne ja lapsianne varten ja tarhoja karjallenne ja tehkää se, mitä suunne on sanonut."'),
(1673665,58,4,32,25,'Niin gaadilaiset ja ruubenilaiset vastasivat Moosekselle sanoen: "Sinun palvelijasi tekevät, niinkuin herramme käskee.'),
(1673666,58,4,32,26,'Lapsemme, vaimomme, laumamme ja kaikki juhtamme jääkööt tänne Gileadin kaupunkeihin,'),
(1673667,58,4,32,27,'mutta sinun palvelijasi lähtevät, jokainen sotaan varustettuna, sinne taisteluun Herran edessä, niinkuin herramme sanoi."'),
(1673668,58,4,32,28,'Niin Mooses antoi heistä käskyn pappi Eleasarille ja Joosualle, Nuunin pojalle, ja Israelin sukukuntien perhekuntain päämiehille,'),
(1673669,58,4,32,29,'ja Mooses sanoi heille: "Jos gaadilaiset ja ruubenilaiset teidän kanssanne lähtevät Jordanin yli, jokainen varustettuna taisteluun Herran edessä, ja se maa tulee teille alamaiseksi, niin antakaa heille Gileadin maa omaksi.'),
(1673670,58,4,32,30,'Mutta jolleivät he varustaudu ja lähde teidän kanssanne sinne, niin asettukoot teidän keskuuteenne Kanaanin maahan."'),
(1673671,58,4,32,31,'Silloin gaadilaiset ja ruubenilaiset vastasivat sanoen: "Mitä Herra on puhunut sinun palvelijoillesi, sen me teemme.'),
(1673672,58,4,32,32,'Me lähdemme varustettuina Herran edessä Kanaanin maahan, että saisimme omaksemme perintöosan tällä puolella Jordanin."'),
(1673673,58,4,32,33,'Ja Mooses antoi heille, gaadilaisille ja ruubenilaisille sekä toiselle puolelle Manassen, Joosefin pojan, sukukuntaa, amorilaisten kuninkaan Siihonin valtakunnan ja Baasanin kuninkaan Oogin valtakunnan, maan ja sen kaupungit alueinensa, sen maan kaupungit yltympäri.'),
(1673674,58,4,32,34,'Ja gaadilaiset rakensivat Diibonin, Atarotin, Aroerin,'),
(1673675,58,4,32,35,'Atrot-Soofanin, Jaeserin, Jogbehan,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673676,58,4,32,36,'Beet-Nimran ja Beet-Haaranin varustetuiksi kaupungeiksi sekä karjatarhoja.'),
(1673677,58,4,32,37,'Ja ruubenilaiset rakensivat Hesbonin, Elalen ja Kirjataimin,'),
(1673678,58,4,32,38,'Nebon ja Baal-Meonin, joiden nimet muutettiin, sekä Sibman. Ja he panivat nimet niille kaupungeille, jotka he rakensivat.'),
(1673679,58,4,32,39,'Mutta Maakir, Manassen poika, lähti Gileadiin ja valloitti sen ja karkoitti amorilaiset, jotka asuivat siellä.'),
(1673680,58,4,32,40,'Ja Mooses antoi Gileadin Maakirille, Manassen pojalle, ja hän asettui sinne.'),
(1673681,58,4,32,41,'Ja Jaair, Manassen poika, meni ja valloitti heidän leirikylänsä ja kutsui ne Jaairin leirikyliksi.'),
(1673682,58,4,32,42,'Ja Noobah meni ja valloitti Kenatin ynnä sen alueella olevat kylät ja kutsui sen, nimensä mukaan, Noobahiksi.'),
(1673683,58,4,33,1,'Nämä olivat israelilaisten matkat, jotka he kulkivat Egyptistä osastoittain Mooseksen ja Aaronin johdolla.'),
(1673684,58,4,33,2,'Ja Mooses kirjoitti Herran käskyn mukaan muistiin ne paikat, joista he lähtivät liikkeelle matkoillansa. Ja nämä ovat heidän matkansa heidän lähtöpaikkojensa mukaan.'),
(1673685,58,4,33,3,'He lähtivät liikkeelle Ramseksesta ensimmäisessä kuussa, ensimmäisen kuukauden viidentenätoista päivänä; pääsiäisen jälkeisenä päivänä israelilaiset lähtivät matkaan voimallisen käden suojassa, kaikkien egyptiläisten nähden,'),
(1673686,58,4,33,4,'egyptiläisten haudatessa kaikkia esikoisiansa, jotka Herra heidän keskuudestaan oli surmannut, ja Herran antaessa tuomion kohdata heidän jumaliansa.'),
(1673687,58,4,33,5,'Niin israelilaiset lähtivät Ramseksesta ja leiriytyivät Sukkotiin.'),
(1673688,58,4,33,6,'Sitten he lähtivät Sukkotista ja leiriytyivät Eetamiin, joka on erämaan reunassa.'),
(1673689,58,4,33,7,'Ja he lähtivät Eetamista ja kääntyivät takaisin Pii-Hahirotiin päin, joka on vastapäätä Baal-Sefonia, ja leiriytyivät Migdolin kohdalle.'),
(1673690,58,4,33,8,'Ja he lähtivät Pii-Hahirotista ja kulkivat meren keskitse erämaahan ja vaelsivat kolmen päivän matkan Eetamin erämaassa ja leiriytyivät Maaraan.'),
(1673691,58,4,33,9,'Sitten he lähtivät Maarasta ja tulivat Eelimiin. Eelimissä oli kaksitoista vesilähdettä ja seitsemänkymmentä palmupuuta, ja he leiriytyivät sinne.'),
(1673692,58,4,33,10,'Ja he lähtivät Eelimistä ja leiriytyivät Kaislameren rannalle.'),
(1673693,58,4,33,11,'Ja he lähtivät Kaislameren rannalta ja leiriytyivät Siinin erämaahan.'),
(1673694,58,4,33,12,'Ja he lähtivät Siinin erämaasta ja leiriytyivät Dofkaan.'),
(1673695,58,4,33,13,'Ja he lähtivät Dofkasta ja leiriytyivät Aalukseen.'),
(1673696,58,4,33,14,'Ja he lähtivät Aaluksesta ja leiriytyivät Refidimiin; siellä ei ollut vettä kansan juoda.'),
(1673697,58,4,33,15,'Ja he lähtivät Refidimistä ja leiriytyivät Siinain erämaahan.'),
(1673698,58,4,33,16,'Ja he lähtivät Siinain erämaasta ja leiriytyivät Kibrot-Hattaavaan.'),
(1673699,58,4,33,17,'Ja he lähtivät Kibrot-Hattaavasta ja leiriytyivät Haserotiin.'),
(1673700,58,4,33,18,'Ja he lähtivät Haserotista ja leiriytyivät Ritmaan.'),
(1673701,58,4,33,19,'Ja he lähtivät Ritmasta ja leiriytyivät Rimmon-Perekseen.'),
(1673702,58,4,33,20,'Ja he lähtivät Rimmon-Pereksestä ja leiriytyivät Libnaan.'),
(1673703,58,4,33,21,'Ja he lähtivät Libnasta ja leiriytyivät Rissaan.'),
(1673704,58,4,33,22,'Ja he lähtivät Rissasta ja leiriytyivät Kehelataan.'),
(1673705,58,4,33,23,'Ja he lähtivät Kehelatasta ja leiriytyivät Seferin vuoren juurelle.'),
(1673706,58,4,33,24,'Ja he lähtivät Seferin vuoren juurelta ja leiriytyivät Haradaan.'),
(1673707,58,4,33,25,'Ja he lähtivät Haradasta ja leiriytyivät Makhelotiin.'),
(1673708,58,4,33,26,'Ja he lähtivät Makhelotista ja leiriytyivät Tahatiin.'),
(1673709,58,4,33,27,'Ja he lähtivät Tahatista ja leiriytyivät Tarahiin.'),
(1673710,58,4,33,28,'Ja he lähtivät Tarahista ja leiriytyivät Mitkaan.'),
(1673711,58,4,33,29,'Ja he lähtivät Mitkasta ja leiriytyivät Hasmonaan.'),
(1673712,58,4,33,30,'Ja he lähtivät Hasmonasta ja leiriytyivät Mooserotiin.'),
(1673713,58,4,33,31,'Ja he lähtivät Mooserotista ja leiriytyivät Bene-Jaakaniin.'),
(1673714,58,4,33,32,'Ja he lähtivät Bene-Jaakanista ja leiriytyivät Hoor-Gidgadiin.'),
(1673715,58,4,33,33,'Ja he lähtivät Hoor-Gidgadista ja leiriytyivät Jotbataan.'),
(1673716,58,4,33,34,'Ja he lähtivät Jotbatasta ja leiriytyivät Abronaan.'),
(1673717,58,4,33,35,'Ja he lähtivät Abronasta ja leiriytyivät Esjon-Geberiin.'),
(1673718,58,4,33,36,'Ja he lähtivät Esjon-Geberistä ja leiriytyivät Siinin erämaahan, se on Kaadekseen.'),
(1673719,58,4,33,37,'Ja he lähtivät Kaadeksesta ja leiriytyivät Hoorin vuoren juurelle, Edomin maan rajalle.'),
(1673720,58,4,33,38,'Ja pappi Aaron nousi Hoorin vuorelle Herran käskyn mukaan ja kuoli siellä neljäntenäkymmenentenä vuotena siitä, kun israelilaiset olivat lähteneet Egyptin maasta, viidennessä kuussa, kuukauden ensimmäisenä päivänä.'),
(1673721,58,4,33,39,'Ja Aaron oli sadan kahdenkymmenen kolmen vuoden vanha kuollessaan Hoorin vuorella.'),
(1673722,58,4,33,40,'Mutta Aradin kuningas, kanaanilainen, joka asui Kanaanin maan eteläosassa, sai kuulla israelilaisten tulosta.'),
(1673723,58,4,33,41,'Ja he lähtivät Hoorin vuorelta ja leiriytyivät Salmonaan.'),
(1673724,58,4,33,42,'Ja he lähtivät Salmonasta ja leiriytyivät Puunoniin.'),
(1673725,58,4,33,43,'Ja he lähtivät Puunonista ja leiriytyivät Oobotiin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673726,58,4,33,44,'Ja he lähtivät Oobotista ja leiriytyivät Iije-Abarimiin Mooabin rajalle.'),
(1673727,58,4,33,45,'Ja he lähtivät Iijimistä ja leiriytyivät Diibon-Gaadiin.'),
(1673728,58,4,33,46,'Ja he lähtivät Diibon-Gaadista ja leiriytyivät Almon-Diblataimiin.'),
(1673729,58,4,33,47,'Ja he lähtivät Almon-Diblataimista ja leiriytyivät Abarimin vuoristoon vastapäätä Neboa.'),
(1673730,58,4,33,48,'Ja he lähtivät Abarimin vuoristosta ja leiriytyivät Mooabin arolle Jordanin rantaan, Jerikon kohdalle.'),
(1673731,58,4,33,49,'Ja Jordanin rannalla heidän leirinsä ulottui Beet-Jesimotista aina Aabel-Sittimiin asti Mooabin arolle.'),
(1673732,58,4,33,50,'Ja Herra puhui Moosekselle Mooabin arolla Jordanin rannalla, Jerikon kohdalla, sanoen:'),
(1673733,58,4,33,51,'"Puhu israelilaisille ja sano heille: Kun olette kulkeneet Jordanin yli Kanaanin maahan,'),
(1673734,58,4,33,52,'niin karkoittakaa tieltänne kaikki maan asukkaat ja hävittäkää kaikki heidän jumalankuvansa, hävittäkää kaikki heidän valetut kuvansa ja kukistakaa kaikki heidän uhrikukkulansa.'),
(1673735,58,4,33,53,'Ottakaa sitten maa haltuunne ja asukaa siinä, sillä teille minä annan omaksi sen maan.'),
(1673736,58,4,33,54,'Ja jakakaa maa keskenänne arvalla sukujenne mukaan; suuremmalle antakaa suurempi perintöosa ja pienemmälle pienempi perintöosa. Kukin saakoon perintöosansa siinä, mihin arpa sen hänelle määrää; isienne sukukuntien mukaan jakakaa maa keskenänne.'),
(1673737,58,4,33,55,'Mutta jos ette karkoita maan asukkaita tieltänne, niin ne, jotka te heistä jätätte jäljelle, tulevat teille okaiksi silmiinne ja tutkaimiksi kylkiinne, ja he ahdistavat teitä siinä maassa, jossa te asutte.'),
(1673738,58,4,33,56,'Ja silloin minä teen teille, niinkuin aioin tehdä heille."'),
(1673739,58,4,34,1,'Ja Herra puhui Moosekselle sanoen:'),
(1673740,58,4,34,2,'"Käske israelilaisia ja sano heille: Kun te tulette Kanaanin maahan - se on se maa, jonka te saatte perintöosaksenne, Kanaanin maa äärestä ääreen -'),
(1673741,58,4,34,3,'niin teidän eteläinen rajanne kulkekoon Siinin erämaasta Edomia pitkin; eteläinen raja alkakoon idässä Suolameren päästä'),
(1673742,58,4,34,4,'ja kääntyköön Skorpionisolasta etelään ja kulkekoon Siiniin, ja se päättyköön Kaades-Barneasta etelään. Sieltä raja lähteköön Hasar-Addariin, kulkekoon Asmoniin'),
(1673743,58,4,34,5,'ja kääntyköön Asmonista Egyptin purolle ja päättyköön mereen.'),
(1673744,58,4,34,6,'Ja teidän läntisenä rajananne olkoon Suuri meri; tämä olkoon läntisenä rajananne.'),
(1673745,58,4,34,7,'Ja teidän pohjoinen rajanne olkoon tämä: Suuresta merestä vetäkää raja Hoorin vuoreen;'),
(1673746,58,4,34,8,'Hoorin vuoresta vetäkää raja siihen, mistä mennään Hamatiin, ja raja päättyköön Sedadiin.'),
(1673747,58,4,34,9,'Sieltä raja lähteköön Sifroniin ja päättyköön Hasar-Eenaniin. Tämä olkoon pohjoisena rajananne.'),
(1673748,58,4,34,10,'Ja itäinen rajanne vetäkää Hasar-Eenanista Sefamiin;'),
(1673749,58,4,34,11,'Sefamista raja painukoon Riblaan, Ainista itään, ja sieltä raja edelleen painukoon, kunnes se sattuu vuoriselänteeseen Kinneretin järven itäpuolella.'),
(1673750,58,4,34,12,'Sitten raja yhtyköön Jordaniin ja päättyköön Suolamereen. Tämä on oleva teidän maanne rajoineen yltympäri."'),
(1673751,58,4,34,13,'Ja Mooses käski israelilaisia sanoen: "Tämä on se maa, joka teidän on jaettava arvalla keskenänne ja jonka Herra määräsi annettavaksi yhdeksälle ja puolelle sukukunnalle.'),
(1673752,58,4,34,14,'Sillä ruubenilaisten sukukunta perhekunnittain ja gaadilaisten sukukunta perhekunnittain ja toinen puoli Manassen sukukuntaa ovat jo saaneet perintöosansa.'),
(1673753,58,4,34,15,'Nämä kaksi ja puoli sukukuntaa ovat jo saaneet perintöosansa tällä puolella Jordania Jerikon kohdalla, itään päin, auringonnousuun päin."'),
(1673754,58,4,34,16,'Ja Herra puhui Moosekselle sanoen:'),
(1673755,58,4,34,17,'"Nämä ovat niiden miesten nimet, joiden on jaettava teille se maa: pappi Eleasar ja Joosua, Nuunin poika;'),
(1673756,58,4,34,18,'ja näiden lisäksi valitkaa päämies kustakin sukukunnasta maata jakamaan.'),
(1673757,58,4,34,19,'Nämä ovat niiden miesten nimet: Juudan sukukunnasta Kaaleb, Jefunnen poika;'),
(1673758,58,4,34,20,'simeonilaisten sukukunnasta Semuel, Ammihudin poika;'),
(1673759,58,4,34,21,'Benjaminin sukukunnasta Elidad, Kislonin poika;'),
(1673760,58,4,34,22,'daanilaisten sukukunnasta päämies Bukki, Joglin poika;'),
(1673761,58,4,34,23,'joosefilaisista, manasselaisten sukukunnasta, päämies Hanniel, Eefodin poika;'),
(1673762,58,4,34,24,'efraimilaisten sukukunnasta päämies Kemuel, Siftanin poika;'),
(1673763,58,4,34,25,'sebulonilaisten sukukunnasta päämies Elisafan, Parnakin poika;'),
(1673764,58,4,34,26,'isaskarilaisten sukukunnasta päämies Paltiel, Assanin poika;'),
(1673765,58,4,34,27,'asserilaisten sukukunnasta päämies Ahihud, Selomin poika,'),
(1673766,58,4,34,28,'ja naftalilaisten sukukunnasta Pedahel, Ammihudin poika."'),
(1673767,58,4,34,29,'Nämä olivat ne, jotka Herra määräsi jakamaan israelilaisille Kanaanin maan.'),
(1673768,58,4,35,1,'Ja Herra puhui Moosekselle Mooabin arolla Jordanin rannalla, Jerikon kohdalla, sanoen:'),
(1673769,58,4,35,2,'"Käske israelilaisia antamaan omistamistaan perintöosista leeviläisille kaupunkeja heidän asuaksensa ja antamaan leeviläisille myöskin laidunmaata näiden kaupunkien ympäriltä.'),
(1673770,58,4,35,3,'Nämä kaupungit olkoot heillä asuntoina, ja niiden laidunmaat olkoot heidän juhtiansa, karjaansa ja kaikkia muita elukoitansa varten.'),
(1673771,58,4,35,4,'Ja näiden kaupunkien laidunmaat, jotka teidän on annettava leeviläisille, ulottukoot kaupungin muurista ulospäin tuhat kyynärää joka taholle.'),
(1673772,58,4,35,5,'Ja mitatkaa kaupungin ulkopuolella itään päin kaksituhatta kyynärää ja etelään päin kaksituhatta kyynärää ja länteen päin kaksituhatta kyynärää ja pohjoiseen päin kaksituhatta kyynärää, ja kaupunki olkoon siinä keskellä. Tämä olkoon heillä kaupunkien laidunmaa.'),
(1673773,58,4,35,6,'Ja niistä kaupungeista, jotka teidän on annettava leeviläisille, olkoon kuusi turvakaupunkia, jotka teidän on annettava pakopaikaksi sille, joka on jonkun tappanut; ja niiden lisäksi antakaa neljäkymmentä kaksi kaupunkia.'),
(1673774,58,4,35,7,'Kaikkiaan olkoon kaupunkeja ja niiden laidunmaita, jotka teidän on annettava leeviläisille, neljäkymmentä kahdeksan.'),
(1673775,58,4,35,8,'Ja niitä israelilaisten omistamia kaupunkeja, jotka teidän on annettava, otettakoon useampia siltä sukukunnalta, jolla niitä on paljon, ja vähemmän siltä, jolla niitä on vähemmän. Kukin sukukunta antakoon leeviläisille kaupunkejaan saamansa perintöosan mukaan."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673776,58,4,35,9,'Ja Herra puhui Moosekselle sanoen:'),
(1673777,58,4,35,10,'"Puhu israelilaisille ja sano heille: Kun te olette menneet Jordanin yli Kanaanin maahan,'),
(1673778,58,4,35,11,'niin valitkaa itsellenne kaupunkeja turvakaupungeiksenne. Niihin paetkoon tappaja, joka tapaturmaisesti on jonkun surmannut.'),
(1673779,58,4,35,12,'Ja nämä kaupungit olkoot teillä turvapaikkoina verenkostajalta, niin ettei tappajan tarvitse kuolla, ennenkuin hän on ollut seurakunnan tuomittavana.'),
(1673780,58,4,35,13,'Ja kaupunkeja, jotka teidän on määrättävä turvakaupungeiksi, olkoon teillä kuusi.'),
(1673781,58,4,35,14,'Kolme kaupunkia teidän on määrättävä tältä puolelta Jordanin, ja kolme kaupunkia teidän on määrättävä Kanaanin maasta; ne olkoot turvakaupunkeja.'),
(1673782,58,4,35,15,'Israelilaisille ja teidän keskuudessanne asuvalle muukalaiselle ja loiselle olkoot ne kuusi kaupunkia turvapaikkoina, joihin voi paeta jokainen, joka tapaturmaisesti jonkun surmaa.'),
(1673783,58,4,35,16,'Mutta jos joku rauta-aseella lyö toista, niin että tämä kuolee, on hän tahallinen tappaja; sellainen tappaja rangaistakoon kuolemalla.'),
(1673784,58,4,35,17,'Jos joku ottaa käteensä kiven, jolla voi lyödä kuoliaaksi, ja lyö toista, niin että tämä kuolee, on hän tahallinen tappaja; sellainen tappaja rangaistakoon kuolemalla.'),
(1673785,58,4,35,18,'Tahi jos joku ottaa käteensä puuaseen, jolla voi lyödä kuoliaaksi, ja lyö toista, niin että tämä kuolee, on hän tahallinen tappaja; sellainen tappaja rangaistakoon kuolemalla.'),
(1673786,58,4,35,19,'Verenkostaja ottakoon sellaisen tappajan hengiltä; hän ottakoon hänet hengiltä, milloin vain hänet tapaa.'),
(1673787,58,4,35,20,'Ja jos joku vihassa iskee toista tahi heittää häntä jollakin murhaamisen tarkoituksessa, niin että tämä kuolee,'),
(1673788,58,4,35,21,'tahi vihaa kantaen lyö häntä kädellään, niin että hän kuolee, rangaistakoon lyöjä kuolemalla, sillä hän on tahallinen tappaja; verenkostaja ottakoon sellaisen tappajan hengiltä, milloin vain hänet tapaa.'),
(1673789,58,4,35,22,'Mutta jos joku vahingossa, vaan ei vihassa, satuttaa toista tai heittää häntä jollakin esineellä, millä hyvänsä, ilman murhaamisen tarkoitusta,'),
(1673790,58,4,35,23,'tahi jos hän kivellä, jolla voi lyödä kuoliaaksi, huomaamattansa satuttaa toista, niin että tämä kuolee, eikä hän ollut hänen vihamiehensä eikä tarkoittanut häntä vahingoittaa,'),
(1673791,58,4,35,24,'niin seurakunta ratkaiskoon tappajan ja verenkostajan välin näiden säädösten mukaan.'),
(1673792,58,4,35,25,'Ja seurakunta päästäköön tappajan verenkostajan kädestä, ja seurakunta antakoon hänen palata turvakaupunkiin, johon hän oli paennut, ja siellä hän asukoon pyhällä öljyllä voidellun ylimmäisen papin kuolemaan asti.'),
(1673793,58,4,35,26,'Mutta jos tappaja menee sen turvakaupungin alueen ulkopuolelle, johon hän on paennut,'),
(1673794,58,4,35,27,'ja verenkostaja tapaa hänet ulkopuolella hänen turvakaupunkinsa aluetta ja verenkostaja surmaa tappajan, niin ei hän joudu verenvikaan;'),
(1673795,58,4,35,28,'sillä hänen on asuttava turvakaupungissaan ylimmäisen papin kuolemaan asti. Mutta ylimmäisen papin kuoltua tappaja saa palata perintömaallensa.'),
(1673796,58,4,35,29,'Ja tämä olkoon teillä oikeussäädöksenä sukupolvesta sukupolveen, missä asuttekin.'),
(1673797,58,4,35,30,'Jos joku lyö toisen kuoliaaksi, surmattakoon tappaja todistajien antaman todistuksen nojalla; mutta yhden todistajan todistuksen nojalla älköön ketään kuolemalla rangaistako.'),
(1673798,58,4,35,31,'Älkää ottako lunastusmaksua sellaisen tappajan hengestä, joka on tehnyt hengenrikoksen, vaan rangaistakoon hänet kuolemalla.'),
(1673799,58,4,35,32,'Älkääkä ottako lunastusmaksua siltä, joka on paennut turvakaupunkiin, ettei hän ennen papin kuolemaa saisi palata asumaan omalle maallensa.'),
(1673800,58,4,35,33,'Älkääkä saastuttako sitä maata, jossa te olette, sillä veri saastuttaa maan. Ja maalle ei voi toimittaa sovitusta verestä, joka siihen on vuodatettu, muulla kuin sen verellä, joka sen on vuodattanut.'),
(1673801,58,4,35,34,'Älkää siis saastuttako sitä maata, jossa te asutte ja jossa minäkin asun teidän keskellänne, sillä minä, Herra, asun israelilaisten keskellä."'),
(1673802,58,4,36,1,'Silloin Gileadin, Maakirin pojan, Manassen pojanpojan, suvun perhekuntapäämiehet, jotka olivat Joosefin poikien sukua, astuivat esiin ja puhuivat Moosekselle ja ruhtinaille, israelilaisten perhekunta-päämiehille,'),
(1673803,58,4,36,2,'ja sanoivat: "Herra käski herrani jakaa sen maan arvalla israelilaisille perintöosaksi, ja herrani sai käskyn Herralta antaa Selofhadin, meidän veljemme, perintöosan hänen tyttärillensä.'),
(1673804,58,4,36,3,'Mutta jos he joutuvat vaimoiksi joillekin israelilaisten muiden heimojen pojista, niin heidän perintöosansa siirtyy pois meidän isiemme perintöosasta ja liitetään sen sukukunnan perintöosaan, johon he tulevat kuulumaan, mutta meidän perintöosamme vähenee.'),
(1673805,58,4,36,4,'Ja kun israelilaisten riemuvuosi tulee, niin heidän perintöosansa lisätään sen sukukunnan perintöosaan, johon he tulevat kuulumaan, mutta meidän isiemme sukukunnan perintöosasta vähentyy heidän perintöosansa."'),
(1673806,58,4,36,5,'Silloin Mooses sääti israelilaisille Herran käskyn mukaan, sanoen: "Joosefilaisten sukukunta puhuu oikein.'),
(1673807,58,4,36,6,'Näin Herra säätää Selofhadin tyttäristä: Menkööt he vaimoiksi kenelle tahtovat, kunhan vain menevät vaimoiksi johonkin isänsä sukukunnan sukuun.'),
(1673808,58,4,36,7,'Sillä älköön israelilaisilla perintöosa siirtykö sukukunnasta toiseen, vaan israelilaiset säilyttäkööt kukin isiensä sukukunnan perintöosan.'),
(1673809,58,4,36,8,'Mutta jokainen tytär, joka saa perintöosan israelilaisten sukukunnissa, menköön vaimoksi johonkin isänsä sukukunnan sukuun, että israelilaiset saisivat periä kukin isiensä perintöosan'),
(1673810,58,4,36,9,'ja ettei perintöosa siirtyisi sukukunnasta toiseen, vaan israelilaisten sukukunnat säilyttäisivät kukin perintöosansa."'),
(1673811,58,4,36,10,'Niinkuin Herra Moosekselle käskyn antoi, niin Selofhadin tyttäret tekivät.'),
(1673812,58,4,36,11,'Ja Mahla, Tirsa, Hogla, Milka ja Nooga, Selofhadin tyttäret, menivät vaimoiksi setiensä pojille.'),
(1673813,58,4,36,12,'Joosefin pojan Manassen poikien sukuihin he menivät vaimoiksi; ja niin heidän perintöosansa jäi heidän isänsä suvun sukukuntaan.'),
(1673814,58,5,1,1,'Nämä ovat ne sanat, jotka Mooses puhui kaikelle Israelille, tuolla puolella Jordanin, erämaassa, Aromaassa, vastapäätä Suufia, Paaranin, Toofelin, Laabanin, Haserotin ja Dii-Saahabin välillä.'),
(1673815,58,5,1,2,'Hoorebista on yksitoista päivänmatkaa, Seirin vuoriston tietä, Kaades-Barneaan.'),
(1673816,58,5,1,3,'Neljäntenäkymmenentenä vuotena, yhdennessätoista kuussa, kuukauden ensimmäisenä päivänä, Mooses puhui israelilaisille kaiken, mitä Herra oli käskenyt hänen heille puhua.'),
(1673817,58,5,1,4,'Tämä tapahtui sen jälkeen, kuin hän oli voittanut Siihonin, amorilaisten kuninkaan, joka asui Hesbonissa, ja Oogin, Baasanin kuninkaan, joka asui Astarotissa, Edrein luona.'),
(1673818,58,5,1,5,'Tuolla puolella Jordanin, Mooabin maassa, Mooses alkoi selittää tätä lakia, sanoen:'),
(1673819,58,5,1,6,'"Herra, meidän Jumalamme, puhui meille Hoorebilla näin: ''Te olette jo tarpeeksi kauan olleet tämän vuoren vaiheilla;'),
(1673820,58,5,1,7,'kääntykää toisaalle, lähtekää liikkeelle ja menkää amorilaisten vuoristoon ja kaikkien heidän naapuriensa tykö Aromaahan, Vuoristoon, Alankomaahan, Etelämaahan ja Merenrannikolle, kanaanilaisten maahan ja Libanoniin, aina suureen virtaan, Eufrat-virtaan, saakka.'),
(1673821,58,5,1,8,'Katso, minä annan maan teidän valtaanne; menkää ja ottakaa omaksenne se maa, jonka Herra teidän isillenne, Aabrahamille, Iisakille ja Jaakobille, vannotulla valalla on luvannut antaa heille ja heidän jälkeläisillensä.'''),
(1673822,58,5,1,9,'Ja minä puhuin teille silloin sanoen: ''Minä en jaksa yksin kantaa teitä.'),
(1673823,58,5,1,10,'Herra, teidän Jumalanne, on antanut teidän lisääntyä, ja katso, teidän lukunne on tänä päivänä niinkuin taivaan tähtien.'),
(1673824,58,5,1,11,'Lisätköön Herra, teidän isienne Jumala, teitä vielä tuhatkertaisesti ja siunatkoon teitä, niinkuin hän on teille puhunut.'),
(1673825,58,5,1,12,'Mutta kuinka minä voin yksin kantaa sitä kuormaa ja taakkaa, joka minulla on teistä ja teidän riitelemisistänne?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673826,58,5,1,13,'Tuokaa tänne viisaita, ymmärtäväisiä ja tunnettuja miehiä jokaisesta sukukunnastanne, niin minä asetan heidät teidän päämiehiksenne.'''),
(1673827,58,5,1,14,'Te vastasitte minulle ja sanoitte: ''Se on hyvä, mitä sinä ehdotat tehtäväksi''.'),
(1673828,58,5,1,15,'Silloin minä otin teidän sukukuntienne päämiehet, jotka olivat viisaita ja tunnettuja miehiä, ja asetin heidät teidän päämiehiksenne, tuhannen-, sadan-, viidenkymmenen- ja kymmenenjohtajiksi, ja päällysmiehiksi sukukuntiinne.'),
(1673829,58,5,1,16,'Ja silloin minä käskin teidän tuomareitanne sanoen: ''Kuulustelkaa veljiänne ja tuomitkaa oikein, jos jollakulla on riita-asia veljensä tai luonaan asuvan muukalaisen kanssa.'),
(1673830,58,5,1,17,'Älkää katsoko henkilöön tuomitessanne, vaan kuulkaa pientä yhtä hyvin kuin suurtakin; älkää peljätkö ketään ihmistä, sillä tuomio on Jumalan. Mutta asia, joka on teistä liian vaikea, lykätkää minulle, kuullakseni sen.'''),
(1673831,58,5,1,18,'Ja silloin minä annoin teille käskyt kaikesta, mitä teidän oli tehtävä.'),
(1673832,58,5,1,19,'Niin me lähdimme liikkeelle Hoorebilta ja kuljimme koko sen suuren ja peljättävän erämaan kautta, jonka te olette nähneet, amorilaisten vuoriston tietä, niinkuin Herra, meidän Jumalamme, oli käskenyt meitä, ja tulimme Kaades-Barneaan.'),
(1673833,58,5,1,20,'Silloin minä sanoin teille: ''Te olette tulleet amorilaisten vuoristoon, jonka Herra, meidän Jumalamme, meille antaa.'),
(1673834,58,5,1,21,'Katso, Herra, sinun Jumalasi, antaa maan sinun valtaasi. Mene ja ota se omaksesi, niinkuin Herra, sinun isiesi Jumala, on sinulle puhunut; älä pelkää äläkä arkaile.'''),
(1673835,58,5,1,22,'Silloin te astuitte kaikki minun eteeni ja sanoitte: ''Lähettäkäämme miehiä edellämme tutkimaan maata ja antamaan meille tietoja tiestä, jota meidän on sinne mentävä, ja kaupungeista, joihin me tulemme''.'),
(1673836,58,5,1,23,'Tämä puhe oli minun silmissäni hyvä, ja minä otin kaksitoista miestä teidän keskuudestanne, yhden jokaisesta sukukunnasta.'),
(1673837,58,5,1,24,'Nämä lähtivät ja nousivat vuoristoon ja tulivat Rypälelaaksoon ja vakoilivat maata.'),
(1673838,58,5,1,25,'Ja he ottivat mukaansa maan hedelmiä ja toivat meille ja antoivat meille tietoja ja sanoivat: ''Maa, jonka Herra, meidän Jumalamme, antaa meille, on hyvä''.'),
(1673839,58,5,1,26,'Mutta te ette tahtoneet mennä sinne, vaan niskoittelitte Herran, teidän Jumalanne, käskyä vastaan.'),
(1673840,58,5,1,27,'Ja te napisitte teltoissanne ja sanoitte: ''Sentähden että Herra vihaa meitä, vei hän meidät pois Egyptin maasta, antaakseen meidät amorilaisten käsiin ja tuhotakseen meidät.'),
(1673841,58,5,1,28,'Mihin me menemme? Veljemme ovat saattaneet meidän rohkeutemme raukeamaan, sillä he sanovat: Siellä on meitä suurempi ja kookkaampi kansa, siellä on suuria, taivaan tasalle varustettuja kaupunkeja; näimmepä siellä anakilaisiakin.'''),
(1673842,58,5,1,29,'Niin minä vastasin teille: ''Älkää säikähtykö älkääkä peljätkö heitä.'),
(1673843,58,5,1,30,'Herra, teidän Jumalanne, joka käy teidän edellänne, taistelee itse teidän puolestanne, aivan niinkuin hän teki teille Egyptissä teidän silmienne edessä'),
(1673844,58,5,1,31,'ja erämaassa, jossa sinä olet nähnyt, kuinka Herra, sinun Jumalasi, on kantanut sinua, niinkuin mies kantaa poikaansa, koko sen matkan, jonka te olette kulkeneet, kunnes tulitte tähän paikkaan.'''),
(1673845,58,5,1,32,'Mutta sittenkään te ette uskoneet Herraan, teidän Jumalaanne,'),
(1673846,58,5,1,33,'joka kävi teidän edellänne tiellä katsoakseen teille leiripaikat: yöllä tulessa, valaistakseen teille tien, jota teidän oli kuljettava, ja päivällä pilvessä.'),
(1673847,58,5,1,34,'Kun Herra kuuli teidän puheenne, vihastui hän ja vannoi sanoen:'),
(1673848,58,5,1,35,'''Totisesti, ei kukaan näistä miehistä, tästä pahasta sukupolvesta, saa nähdä sitä hyvää maata, jonka minä valalla vannoen olen luvannut antaa teidän isillenne,'),
(1673849,58,5,1,36,'ei kukaan, paitsi Kaaleb, Jefunnen poika; hän saa sen nähdä, ja hänelle ja hänen lapsillensa minä annan sen maan, johon hän on astunut, sentähden että hän on uskollisesti seurannut Herraa''.'),
(1673850,58,5,1,37,'Myöskin minuun Herra vihastui teidän tähtenne ja sanoi: ''Et sinäkään sinne pääse.'),
(1673851,58,5,1,38,'Joosua, Nuunin poika, joka sinua palvelee, hän pääsee sinne; vahvista häntä, sillä hän on jakava maan Israelille perinnöksi.'),
(1673852,58,5,1,39,'Ja teidän lapsenne, joiden sanoitte joutuvan vihollisen saaliiksi, ja teidän poikanne, jotka eivät vielä tiedä, mikä on hyvä, mikä paha, ne pääsevät sinne; heille minä annan maan, ja he ottavat sen omaksensa.'),
(1673853,58,5,1,40,'Mutta te kääntykää takaisin ja lähtekää liikkeelle erämaahan, Kaislameren tietä.'''),
(1673854,58,5,1,41,'Silloin te vastasitte ja sanoitte minulle: ''Me olemme tehneet syntiä Herraa vastaan. Me menemme ja taistelemme, aivan niinkuin Herra, meidän Jumalamme, on meitä käskenyt.'' Ja te vyöttäydyitte kaikki sota-aseisiinne ja lähditte kevytmielisesti nousemaan vuoristoon.'),
(1673855,58,5,1,42,'Mutta Herra sanoi minulle: ''Sano heille: Älkää nousko sinne älkääkä antautuko taisteluun, sillä minä en ole teidän keskellänne; älkää tehkö niin, etteivät vihollisenne voittaisi teitä''.'),
(1673856,58,5,1,43,'Ja minä puhuin teille, mutta te ette kuulleet, vaan niskoittelitte Herran käskyä vastaan ja lähditte ylimielisesti vuoristoon.'),
(1673857,58,5,1,44,'Ja amorilaiset, jotka asuvat siinä vuoristossa, lähtivät teitä vastaan ja ajoivat teitä takaa, niinkuin mehiläiset tekevät, ja hajottivat teidät Seirissä, ja aina Hormaan asti.'),
(1673858,58,5,1,45,'Niin te palasitte ja itkitte Herran edessä. Mutta Herra ei kuullut teidän huutoanne, ei kuunnellut teitä.'),
(1673859,58,5,1,46,'Ja teidän täytyi viipyä Kaadeksessa se pitkä aika, minkä siellä viivyitte."'),
(1673860,58,5,2,1,'"Sitten me käännyimme toisaalle ja lähdimme liikkeelle erämaahan, Kaislameren tietä, niinkuin Herra oli minulle puhunut, ja kiertelimme kauan aikaa Seirin vuoristossa.'),
(1673861,58,5,2,2,'Ja Herra sanoi minulle näin:'),
(1673862,58,5,2,3,'''Te olette jo tarpeeksi kauan kierrelleet tässä vuoristossa; kääntykää nyt pohjoista kohti.'),
(1673863,58,5,2,4,'Ja käske kansaa sanoen: Te tulette kulkemaan Seirissä asuvien veljienne, Eesaun jälkeläisten, alueen kautta. He pelkäävät teitä, mutta te pitäkää itsestänne tarkka vaari:'),
(1673864,58,5,2,5,'älkää ryhtykö taisteluun heidän kanssansa, sillä minä en anna teille jalanleveyttäkään heidän maastansa, koska minä olen antanut Seirin vuoriston Eesaun omaksi.'),
(1673865,58,5,2,6,'Rahalla te ostakaa heiltä ruokaa syödäksenne; vesikin hankkikaa heiltä rahalla juodaksenne.'),
(1673866,58,5,2,7,'Sillä Herra, sinun Jumalasi, on siunannut sinua kaikissa kättesi töissä. Hän on pitänyt huolen sinun vaelluksestasi tässä suuressa erämaassa. Jo neljäkymmentä vuotta on Herra, sinun Jumalasi, ollut sinun kanssasi, eikä sinulta ole mitään puuttunut.'''),
(1673867,58,5,2,8,'Niin me lähdimme pois veljiemme, Eesaun jälkeläisten, luota, jotka asuvat Seirissä, poiketen Aromaan tieltä, joka tulee Eelatista ja Esjon-Geberistä. Me käännyimme toisaalle ja lähdimme kulkemaan Mooabin erämaan tietä.'),
(1673868,58,5,2,9,'Ja Herra sanoi minulle: ''Älä käy Mooabin kimppuun äläkä ryhdy taisteluun heidän kanssaan, sillä minä en anna heidän maastaan mitään sinun omaksesi, koska minä olen antanut Aarin Lootin jälkeläisten omaksi''.'),
(1673869,58,5,2,10,'Eemiläiset asuivat muinoin siellä, suuri, lukuisa ja kookas kansa niinkuin anakilaiset.'),
(1673870,58,5,2,11,'Ja samoin kuin anakilaiset luettiin heidätkin refalaisiin; mutta mooabilaiset kutsuivat heitä eemiläisiksi.'),
(1673871,58,5,2,12,'Hoorilaiset sitävastoin asuivat muinoin Seirissä, mutta Eesaun jälkeläiset karkoittivat heidät tieltään ja tuhosivat heidät ja asettuivat heidän sijaansa, samoin kuin Israel teki siinä maassa, jonka Herra oli antanut heidän omaksensa.'),
(1673872,58,5,2,13,'''Nouskaa siis ja kulkekaa Seredin puron poikki.'' Ja me kuljimme Seredin puron poikki.'),
(1673873,58,5,2,14,'Ja aika, joka kului vaellukseemme Kaades-Barneasta siihen asti, että kuljimme Seredin puron yli, oli kolmekymmentä kahdeksan vuotta, kunnes hävisi koko se sukupolvi, kaikki sotakuntoiset miehet, leiristä, niinkuin Herra oli heille vannonut.'),
(1673874,58,5,2,15,'Myös oli Herran käsi heitä vastaan hävittämässä heitä leiristä, viimeiseen mieheen asti.'),
(1673875,58,5,2,16,'Kun kaikki sotakuntoiset miehet olivat kuolleet pois kansasta,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673876,58,5,2,17,'puhui Herra minulle sanoen:'),
(1673877,58,5,2,18,'''Sinä kuljet nyt Mooabin alueen kautta, Aarin kautta,'),
(1673878,58,5,2,19,'ja lähestyt ammonilaisia; mutta älä käy heidän kimppuunsa äläkä ryhdy taisteluun heidän kanssansa, sillä minä en anna ammonilaisten maasta mitään omaksesi, koska minä olen antanut sen Lootin jälkeläisten omaksi''.'),
(1673879,58,5,2,20,'Tämäkin on luettu refalaisten maaksi; refalaiset asuivat muinoin siellä, mutta ammonilaiset kutsuivat heitä samsumilaisiksi.'),
(1673880,58,5,2,21,'Ne olivat niinkuin anakilaiset suuri, lukuisa ja kookas kansa. Mutta Herra tuhosi ne heidän tieltänsä; he karkoittivat ne ja asettuivat niiden sijaan.'),
(1673881,58,5,2,22,'Samoin hän on tehnyt Eesaun jälkeläisille, jotka asuvat Seirissä, kun hän tuhosi hoorilaiset heidän tieltänsä; he karkoittivat nämä ja asettuivat heidän sijaansa, ja siellä he asuvat vielä tänäkin päivänä.'),
(1673882,58,5,2,23,'Mutta avvilaisille, jotka asuivat maakylissä aina Gassaan asti, tuottivat tuhon kaftorilaiset, jotka olivat lähteneet Kaftorista, ja asettuivat heidän sijaansa.'),
(1673883,58,5,2,24,'''Nouskaa ja lähtekää liikkeelle ja kulkekaa Arnon-joen yli. Katso, minä annan sinun käsiisi amorilaisen Siihonin, Hesbonin kuninkaan, ja hänen maansa. Käy sitä valloittamaan ja ryhdy taisteluun häntä vastaan.'),
(1673884,58,5,2,25,'Tästä päivästä alkaen minä saatan kauhuun ja pelkoon sinun edessäsi kansat kaiken taivaan alla, niin että, kun ne kuulevat sinusta kerrottavan, ne pelkäävät ja vapisevat sinun edessäsi.'''),
(1673885,58,5,2,26,'Ja minä lähetin sanansaattajat Kedemotin erämaasta Siihonille, Hesbonin kuninkaalle, viemään rauhan tervehdyksen ja sanomaan:'),
(1673886,58,5,2,27,'''Salli minun kulkea maasi kautta. Aina tiellä pysyen minä kuljen, poikkeamatta oikealle tai vasemmalle.'),
(1673887,58,5,2,28,'Anna minun rahalla ostaa ruokaa syödäkseni ja anna minulle rahalla vettä juodakseni; salli vain minun jalkaisin kulkea maasi kautta -'),
(1673888,58,5,2,29,'minkä minulle myönsivät Eesaun jälkeläiset, jotka asuvat Seirissä, ja mooabilaiset, jotka asuvat Aarissa - kunnes menen Jordanin yli siihen maahan, jonka Herra, meidän Jumalamme, meille antaa.'''),
(1673889,58,5,2,30,'Mutta Siihon, Hesbonin kuningas, ei tahtonut antaa meidän kulkea maansa kautta, sillä Herra, sinun Jumalasi, paadutti hänen mielensä ja kovensi hänen sydämensä, antaakseen hänet sinun käsiisi, niinkuin nyt onkin tapahtunut.'),
(1673890,58,5,2,31,'Ja Herra sanoi minulle: ''Katso, minä annan nyt Siihonin ja hänen maansa sinun valtaasi. Ryhdy sitä valloittamaan ja ota hänen maansa omaksesi.'''),
(1673891,58,5,2,32,'Niin Siihon ja kaikki hänen sotaväkensä lähti Jahaaseen taistelemaan meitä vastaan.'),
(1673892,58,5,2,33,'Mutta Herra, meidän Jumalamme, antoi hänet meidän valtaamme, ja me voitimme hänet ja hänen poikansa ja kaiken hänen sotaväkensä.'),
(1673893,58,5,2,34,'Ja me valloitimme silloin kaikki hänen kaupunkinsa ja vihimme tuhon omiksi jokaisessa kaupungissa miehet, naiset ja lapset, päästämättä pakoon ainoatakaan.'),
(1673894,58,5,2,35,'Ainoastaan karjan me ryöstimme itsellemme ynnä saaliin valloittamistamme kaupungeista.'),
(1673895,58,5,2,36,'Aroerista, joka on Arnon-joen rannalla, ja jokilaaksossa olevasta kaupungista Gileadiin saakka ei ollut ainoatakaan kaupunkia, joka olisi ollut meille liian korkealla; Herra, meidän Jumalamme, antoi kaikki meidän valtaamme.'),
(1673896,58,5,2,37,'Ainoastaan ammonilaisten maahan sinä et astunut, et mihinkään, mikä on Jabbok-joen varrella, et vuoriston kaupunkeihin etkä mihinkään muuhun, josta Herra, meidän Jumalamme, oli niin määrännyt."'),
(1673897,58,5,3,1,'"Sitten me käännyimme toisaalle ja kuljimme Baasanin tietä. Silloin lähti Oog, Baasanin kuningas, hän ja kaikki hänen sotaväkensä, Edreihin taistelemaan meitä vastaan.'),
(1673898,58,5,3,2,'Mutta Herra sanoi minulle: ''Älä pelkää häntä, sillä minä annan sinun käsiisi hänet ja kaiken hänen kansansa ja hänen maansa. Tee hänelle, niinkuin teit Siihonille, amorilaisten kuninkaalle, joka asui Hesbonissa.'''),
(1673899,58,5,3,3,'Ja niin Herra, meidän Jumalamme, antoi meidän käsiimme myöskin Oogin, Baasanin kuninkaan, ja kaiken hänen sotaväkensä, ja me voitimme hänet, päästämättä pakoon ainoatakaan.'),
(1673900,58,5,3,4,'Ja me valloitimme silloin kaikki hänen kaupunkinsa - ei ollut ainoatakaan kaupunkia, jota emme olisi heiltä ottaneet - kuusikymmentä kaupunkia, koko Argobin seudun, Oogin valtakunnan Baasanissa,'),
(1673901,58,5,3,5,'kaikki nämä kaupungit korkeilla muureilla, porteilla ja salvoilla varustettuja, ja sen lisäksi vielä suuren joukon linnoittamattomia pikkukaupunkeja.'),
(1673902,58,5,3,6,'Ja me vihimme ne tuhon omiksi, niinkuin olimme tehneet Siihonille, Hesbonin kuninkaalle; me vihimme tuhon omiksi jokaisessa kaupungissa miehet, naiset ja lapset.'),
(1673903,58,5,3,7,'Mutta kaiken karjan ynnä saaliin kaupungeista me ryöstimme itsellemme.'),
(1673904,58,5,3,8,'Niin me otimme silloin kahdelta amorilaisten kuninkaalta, jotka hallitsivat tuolla puolella Jordanin, heidän maansa Arnon-joesta aina Hermonin vuoreen asti -'),
(1673905,58,5,3,9,'siidonilaiset kutsuvat Hermonia Sirjoniksi, mutta amorilaiset kutsuvat sitä Seniriksi -'),
(1673906,58,5,3,10,'kaikki ylätasangon kaupungit ja koko Gileadin ja koko Baasanin aina Salkaan ja Edreihin, Baasanissa oleviin Oogin valtakunnan kaupunkeihin, saakka.'),
(1673907,58,5,3,11,'Sillä Baasanin kuningas Oog oli yksin enää jäljellä viimeisistä refalaisista. Hänen basaltista tehty ruumisarkkunsa on vieläkin ammonilaisten kaupungissa Rabbassa; se on yhdeksää kyynärää pitkä ja neljää kyynärää leveä, mitattuna tavallisella kyynärämitalla.'),
(1673908,58,5,3,12,'Kun me silloin olimme ottaneet omaksemme tämän maan, annoin minä sen osan siitä, joka alkaa Aroerista, Arnon-joen varrelta, sekä puolet Gileadin vuoristoa kaupunkeineen ruubenilaisille ja gaadilaisille.'),
(1673909,58,5,3,13,'Loput Gileadista ja koko Baasanin, Oogin valtakunnan, minä annoin toiselle puolelle Manassen sukukuntaa, koko Argobin seudun; koko tätä Baasania kutsutaan refalaisten maaksi.'),
(1673910,58,5,3,14,'Jaair, Manassen poika, valtasi koko Argobin seudun aina gesurilaisten ja maakatilaisten alueeseen saakka, ja hän kutsui nämä seudut, se on Baasanin, oman nimensä mukaan Jaairin leirikyliksi, niinkuin niitä kutsutaan vielä tänäkin päivänä.'),
(1673911,58,5,3,15,'Ja Maakirille minä annoin Gileadin.'),
(1673912,58,5,3,16,'Ja ruubenilaisille ja gaadilaisille minä annoin maan Gileadista aina Arnon-jokeen, jokilaakson keskikohtaan saakka, joka on rajana, ja Jabbok-jokeen saakka, joka on ammonilaisten rajana;'),
(1673913,58,5,3,17,'niin myös Aromaan, Jordan rajana, Kinneretistä aina Aromaan mereen, Suolamereen, saakka, Pisgan rinteiden juurelle, itään päin.'),
(1673914,58,5,3,18,'Ja silloin minä käskin teitä ja sanoin: ''Herra, teidän Jumalanne, on antanut teille tämän maan omaksenne. Mutta te, kaikki sotakuntoiset miehet, lähtekää asestettuina veljienne, israelilaisten, etunenässä.'),
(1673915,58,5,3,19,'Ainoastaan vaimonne, lapsenne ja karjanne - sillä minä tiedän teillä olevan paljon karjaa - jääkööt kaupunkeihinne, jotka minä olen teille antanut,'),
(1673916,58,5,3,20,'kunnes Herra suo veljienne, samoinkuin teidänkin, päästä rauhaan, kun hekin ovat ottaneet omaksensa sen maan, jonka Herra, teidän Jumalanne, antaa teille Jordanin tuolta puolelta; sitten saatte palata takaisin, kukin omistamallensa maalle, jonka minä olen teille antanut.'''),
(1673917,58,5,3,21,'Ja silloin minä käskin Joosuaa ja sanoin: ''Sinä olet omin silmin nähnyt kaiken, mitä Herra, teidän Jumalanne, on tehnyt näille kahdelle kuninkaalle. Samalla tavalla Herra on tekevä kaikille valtakunnille, joihin sinä menet.'),
(1673918,58,5,3,22,'Älkää niitä peljätkö, sillä Herra, teidän Jumalanne, sotii itse teidän puolestanne.'''),
(1673919,58,5,3,23,'Ja silloin minä anoin Herralta armoa sanoen:'),
(1673920,58,5,3,24,'''Herra, Herra, sinä olet alkanut näyttää palvelijallesi valtasuuruuttasi ja väkevää kättäsi; sillä kuka on se jumala taivaassa tai maassa, joka voi tehdä sellaisia töitä ja niin voimallisia tekoja kuin sinä?'),
(1673921,58,5,3,25,'Niin salli minun nyt mennä katsomaan sitä hyvää maata, joka on tuolla puolella Jordanin, tuota ihanaa vuoristoa ja Libanonia.'''),
(1673922,58,5,3,26,'Mutta Herra oli julmistunut minuun teidän tähtenne eikä kuullut minua, vaan sanoi minulle: ''Riittää! Älä puhu minulle enempää tästä asiasta.'),
(1673923,58,5,3,27,'Nouse Pisgan huipulle ja kohota katseesi länteen ja pohjoiseen, etelään ja itään ja katsele silmilläsi; sillä tämän Jordanin yli sinä et mene.'),
(1673924,58,5,3,28,'Ja anna määräyksiä Joosualle, vahvista ja rohkaise häntä. Sillä hän menee sinne tämän kansan edellä, ja hän jakaa heille perinnöksi sen maan, jonka sinä näet.'''),
(1673925,58,5,3,29,'Ja me jäimme laaksoon, vastapäätä Beet-Peoria."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673926,58,5,4,1,'"Ja nyt, Israel, kuule ne käskyt ja säädökset, jotka minä teille opetan, että seuraisitte niitä, eläisitte ja ottaisitte omaksenne sen maan, jonka Herra, teidän isienne Jumala, teille antaa.'),
(1673927,58,5,4,2,'Älkää lisätkö mitään siihen, mitä minä teille määrään, älkääkä ottako siitä mitään pois, vaan noudattakaa Herran, teidän Jumalanne, käskyjä, jotka minä teille annan.'),
(1673928,58,5,4,3,'Te olette omin silmin nähneet, mitä Herra teki Baal-Peorin asiassa, kuinka Herra, sinun Jumalasi, hävitti sinun keskuudestasi jokaisen, joka lähti kulkemaan Baal-Peorin perässä.'),
(1673929,58,5,4,4,'Mutta te, jotka riipuitte kiinni Herrassa, teidän Jumalassanne, te kaikki olette elossa vielä tänä päivänä.'),
(1673930,58,5,4,5,'Katso, minä olen opettanut teille käskyt ja säädökset, niinkuin Herra, minun Jumalani, on minua käskenyt, että seuraisitte niitä siinä maassa, jota te menette ottamaan omaksenne.'),
(1673931,58,5,4,6,'Noudattakaa ja seuratkaa niitä, sillä se on oleva teidän viisautenne ja ymmärryksenne kansojen silmissä. Kun he kuulevat kaikki nämä käskyt, sanovat he: ''Totisesti, viisas ja ymmärtäväinen kansa on tämä suuri kansa''.'),
(1673932,58,5,4,7,'Sillä onko toista suurta kansaa, jonka jumalat ovat sitä niin lähellä, kuin Herra, meidän Jumalamme, on lähellä meitä, niin usein kuin me häntä rukoilemme?'),
(1673933,58,5,4,8,'Ja onko toista suurta kansaa, jolla on niin vanhurskaat käskyt ja säädökset, kuin on koko tämä laki, jonka minä tänä päivänä teille annan?'),
(1673934,58,5,4,9,'Ole vain varuillasi ja ota itsestäsi tarkka vaari, ettet unhota, mitä omin silmin olet nähnyt, ja ettei se lähde sinun sydämestäsi koko elinaikanasi, vaan että ilmoitat sen lapsillesi ja lastesi lapsille:'),
(1673935,58,5,4,10,'mitä tapahtui sinä päivänä, jona seisoit Herran, sinun Jumalasi, edessä Hoorebilla, kun Herra sanoi minulle: ''Kokoa kansa, niin minä julistan heille sanani, että he oppisivat pelkäämään minua, niin kauan kuin elävät maan päällä, ja opettaisivat lapsensakin siihen''.'),
(1673936,58,5,4,11,'Ja te astuitte esille ja jäitte seisomaan vuoren juurelle, ja vuori paloi tulena, joka loimusi sisimpään taivaaseen asti pimeyden ja synkkien pilvien keskellä.'),
(1673937,58,5,4,12,'Ja Herra puhui teille tulen keskeltä. Sanat te kuulitte, mutta ette nähneet hänen muotoansa, kuulitte vain äänen.'),
(1673938,58,5,4,13,'Ja hän ilmoitti teille liittonsa, jonka hän käski teidän pitää, nimittäin ne kymmenen käskysanaa; ja hän kirjoitti ne kahteen kivitauluun.'),
(1673939,58,5,4,14,'Ja minun Herra silloin käski opettaa teille käskyt ja säädökset, että te seuraisitte niitä siinä maassa, jota te menette ottamaan omaksenne.'),
(1673940,58,5,4,15,'Ottakaa siis itsestänne tarkka vaari - sillä te ette sinä päivänä, jona Herra puhui teille tulen keskeltä Hoorebilla, nähneet hänestä minkäänkaltaista muotoa -'),
(1673941,58,5,4,16,'ettette menettele kelvottomasti ettekä tee itsellenne jumalankuvaa, ette minkään muotoista patsasta, ette miehen tai naisen kuvaa,'),
(1673942,58,5,4,17,'ette maan päällä liikkuvan nelijalkaisen eläimen kuvaa, ette taivaan alla lentävän siivekkään linnun kuvaa,'),
(1673943,58,5,4,18,'ette maassa matelevaisen kuvaa ettekä vesissä maan alla olevan kalan kuvaa;'),
(1673944,58,5,4,19,'ja ettet, kun nostat silmäsi taivasta kohti ja katselet aurinkoa ja kuuta ja tähtiä, kaikkea taivaan joukkoa, anna vietellä itseäsi kumartamaan ja palvelemaan niitä, sillä Herra, sinun Jumalasi, on jakanut ne kaikille muille kansoille koko taivaan alla.'),
(1673945,58,5,4,20,'Onhan Herra ottanut teidät ja vienyt pois rautapätsistä, Egyptistä, että teistä tulisi hänen perintökansansa, niinkuin nyt on tapahtunut.'),
(1673946,58,5,4,21,'Mutta Herra vihastui minuun teidän tähtenne ja vannoi, etten minä saa mennä Jordanin yli enkä tulla siihen hyvään maahan, jonka Herra, sinun Jumalasi, antaa sinulle perintöosaksi,'),
(1673947,58,5,4,22,'vaan että minä kuolen tässä maassa enkä mene Jordanin yli. Mutta te menette sen yli ja otatte tuon hyvän maan omaksenne.'),
(1673948,58,5,4,23,'Niin varokaa, ettette unhota Herran, teidän Jumalanne, liittoa, jonka hän on tehnyt teidän kanssanne, ettekä tee itsellenne jumalankuvaa, mitään sen muotoista kuvaa, jota Herra, sinun Jumalasi, on kieltänyt sinua tekemästä.'),
(1673949,58,5,4,24,'Sillä Herra, sinun Jumalasi, on kuluttava tuli, kiivas Jumala.'),
(1673950,58,5,4,25,'Kun sitten sinulle on syntynyt lapsia ja lasten lapsia ja te olette vanhentuneet maassa, ja jos te silloin menettelette kelvottomasti ja teette itsellenne jumalankuvan, minkämuotoisen kuvan hyvänsä, ja siten teette sitä, mikä on pahaa Herran, sinun Jumalasi, silmissä, ja vihoitatte hänet,'),
(1673951,58,5,4,26,'niin minä otan tänä päivänä taivaan ja maan todistajiksi teitä vastaan, että teidät äkkiä hävitetään siitä maasta, johon te menette Jordanin yli ottamaan sen omaksenne; te ette saa kauan elää siellä, vaan teidät tuhotaan kokonaan.'),
(1673952,58,5,4,27,'Ja Herra hajottaa teidät kansojen sekaan, ja ainoastaan vähäinen joukko teitä on jäävä niiden pakanakansojen keskelle, joiden tykö Herra teidät kuljettaa.'),
(1673953,58,5,4,28,'Ja siellä te palvelette jumalia, jotka ovat ihmiskätten tekoa, puuta ja kiveä, jotka eivät näe eivätkä kuule, eivät syö eivätkä hajua tunne.'),
(1673954,58,5,4,29,'Mutta sitten sinä siellä etsit Herraa, sinun Jumalaasi, ja sinä löydät hänet, kun kysyt häntä kaikesta sydämestäsi ja kaikesta sielustasi.'),
(1673955,58,5,4,30,'Kun olet ahdistuksessa ja kaikki tämä kohtaa sinua aikojen lopussa, niin sinä palajat Herran, sinun Jumalasi, tykö ja kuulet hänen ääntänsä.'),
(1673956,58,5,4,31,'Sillä Herra, sinun Jumalasi, on laupias Jumala. Hän ei jätä sinua eikä hukuta sinua; hän ei unhota sinun isiesi kanssa tekemäänsä liittoa, jonka hän on heille valalla vahvistanut.'),
(1673957,58,5,4,32,'Sillä kysy menneiltä ajoilta, jotka ovat olleet ennen sinua, alkaen siitä päivästä, jona Jumala loi ihmiset maan päälle, kysy taivaan äärestä toiseen: onko koskaan mitään näin suurta tapahtunut, tai onko mitään tällaista ikinä kuultu?'),
(1673958,58,5,4,33,'Onko mikään kansa kuullut Jumalan äänen puhuvan tulen keskeltä, niinkuin sinä olet kuullut, ja kuitenkin jäänyt elämään?'),
(1673959,58,5,4,34,'Tahi onko mikään jumala koettanut mennä ottamaan itsellensä kansaa toisen kansan keskuudesta koettelemuksilla, tunnusteoilla ja ihmeillä, sodalla, väkevällä kädellä ja ojennetulla käsivarrella ja suurilla, peljättävillä teoilla, minkä kaiken Herra, teidän Jumalanne, on tehnyt teille Egyptissä, sinun silmiesi edessä?'),
(1673960,58,5,4,35,'Sinun on annettu se nähdä, tietääksesi, että Herra on Jumala, eikä muuta jumalaa ole kuin hän.'),
(1673961,58,5,4,36,'Taivaasta hän antoi sinun kuulla äänensä opettaaksensa sinua, ja maan päällä hän antoi sinun nähdä suuren tulensa, ja sinä kuulit hänen sanansa tulen keskeltä.'),
(1673962,58,5,4,37,'Koska hän siis rakasti sinun isiäsi ja valitsi heidän jälkeläisensä itselleen ja itse suurella voimallaan vei sinut pois Egyptistä'),
(1673963,58,5,4,38,'karkoittaen sinun tieltäsi kansoja, suurempia ja väkevämpiä kuin sinä, ja tuoden sinut heidän maahansa antaakseen sen sinulle perintöosaksi, niinkuin nyt on tapahtunut,'),
(1673964,58,5,4,39,'niin tiedä siis tänä päivänä ja paina se sydämeesi, että Herra on Jumala ylhäällä taivaassa ja alhaalla maan päällä, eikä muuta jumalaa ole.'),
(1673965,58,5,4,40,'Noudata hänen säädöksiänsä ja käskyjänsä, jotka minä tänä päivänä sinulle annan, että sinä ja sinun lapsesi sinun jälkeesi menestyisitte ja että eläisit kauan siinä maassa, jonka Herra, sinun Jumalasi, antaa sinulle ainiaaksi."'),
(1673966,58,5,4,41,'Silloin Mooses erotti kolme kaupunkia tuolta puolelta Jordanin, auringon nousun puolelta,'),
(1673967,58,5,4,42,'että niihin voisi paeta tappaja, joka on tappanut toisen tahtomattaan ja häntä ennestään vihaamatta; paetkoon hän johonkin näistä kaupungeista, niin hän saa elää.'),
(1673968,58,5,4,43,'Ne olivat: ruubenilaisille Beser erämaassa, ylätasangolla; gaadilaisille Raamot Gileadissa ja manasselaisille Goolan Baasanissa.'),
(1673969,58,5,4,44,'Tämä on se laki, jonka Mooses antoi israelilaisille,'),
(1673970,58,5,4,45,'ja nämä ovat ne todistukset, käskyt ja oikeudet, jotka Mooses julisti israelilaisille, heidän lähdettyään Egyptistä,'),
(1673971,58,5,4,46,'tuolla puolella Jordanin, laaksossa, vastapäätä Beet-Peoria, Siihonin, amorilaisten kuninkaan, maassa, hänen, joka asui Hesbonissa ja jonka Mooses ja israelilaiset voittivat, lähdettyänsä Egyptistä.'),
(1673972,58,5,4,47,'Ja he ottivat omakseen hänen maansa ja Oogin, Baasanin kuninkaan, maan, kahden amorilaisten kuninkaan maat, jotka ovat tuolla puolella Jordanin, auringon nousuun päin,'),
(1673973,58,5,4,48,'alkaen Aroerista, joka on Arnonjoen rannalla, aina Sirjonin vuoreen, se on Hermoniin, saakka,'),
(1673974,58,5,4,49,'sekä koko Aromaan, tuolla puolella Jordanin, idän puolella, aina Aromaan mereen saakka, Pisgan rinteiden juurelle.'),
(1673975,58,5,5,1,'Ja Mooses kutsui kokoon kaiken Israelin ja sanoi heille: "Kuule, Israel, nämä käskyt ja oikeudet, jotka minä tänä päivänä julistan teidän korvienne kuullen. Oppikaa ne ja noudattakaa niitä tarkoin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1673976,58,5,5,2,'Herra, meidän Jumalamme, teki liiton meidän kanssamme Hoorebilla.'),
(1673977,58,5,5,3,'Herra ei tehnyt tätä liittoa meidän isiemme kanssa, vaan meidän kanssamme, jotka olemme tässä tänä päivänä, kaikkien meidän kanssamme, jotka nyt elämme.'),
(1673978,58,5,5,4,'Kasvoista kasvoihin Herra puhui teidän kanssanne vuorelta, tulen keskeltä.'),
(1673979,58,5,5,5,'Minä seisoin silloin Herran ja teidän välillänne ja ilmoitin teille Herran sanan, sillä te pelkäsitte tulta ettekä nousseet vuorelle. Hän sanoi:'),
(1673980,58,5,5,6,'''Minä olen Herra, sinun Jumalasi, joka vein sinut pois Egyptin maasta, orjuuden pesästä.'),
(1673981,58,5,5,7,'Älä pidä muita jumalia minun rinnallani.'),
(1673982,58,5,5,8,'Älä tee itsellesi jumalankuvaa, älä mitään kuvaa, älä niistä, jotka ovat ylhäällä taivaassa, älä niistä, jotka ovat alhaalla maan päällä, äläkä niistä, jotka ovat vesissä maan alla.'),
(1673983,58,5,5,9,'Älä kumarra niitä äläkä palvele niitä. Sillä minä, Herra, sinun Jumalasi, olen kiivas Jumala, joka kostan isien pahat teot lapsille kolmanteen ja neljänteen polveen, niille, jotka minua vihaavat;'),
(1673984,58,5,5,10,'mutta teen laupeuden tuhansille, jotka minua rakastavat ja pitävät minun käskyni.'),
(1673985,58,5,5,11,'Älä turhaan lausu Herran, sinun Jumalasi, nimeä, sillä Herra ei jätä rankaisematta sitä, joka hänen nimensä turhaan lausuu.'),
(1673986,58,5,5,12,'Ota vaari lepopäivästä, niin että sen pyhität, niinkuin Herra, sinun Jumalasi, on sinua käskenyt.'),
(1673987,58,5,5,13,'Kuusi päivää tee työtä ja toimita kaikki askareesi;'),
(1673988,58,5,5,14,'mutta seitsemäs päivä on Herran, sinun Jumalasi, sapatti; silloin älä mitään askaretta toimita, älä sinä älköönkä sinun poikasi tai tyttäresi, sinun palvelijasi tai palvelijattaresi, sinun härkäsi, aasisi tai muu juhtasi älköönkä muukalaisesi, joka sinun porteissasi on, että palvelijasi ja palvelijattaresi saisivat levätä niinkuin sinäkin.'),
(1673989,58,5,5,15,'Ja muista, että itse olit orjana Egyptin maassa ja että Herra, sinun Jumalasi, vei sinut sieltä pois väkevällä kädellä ja ojennetulla käsivarrella. Sentähden Herra, sinun Jumalasi, käski sinun viettää lepopäivän.'),
(1673990,58,5,5,16,'Kunnioita isääsi ja äitiäsi, niinkuin Herra, sinun Jumalasi, on sinua käskenyt, että kauan eläisit ja menestyisit siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa.'),
(1673991,58,5,5,17,'Älä tapa.'),
(1673992,58,5,5,18,'Älä tee huorin.'),
(1673993,58,5,5,19,'Älä varasta.'),
(1673994,58,5,5,20,'Älä sano väärää todistusta lähimmäisestäsi.'),
(1673995,58,5,5,21,'Älä himoitse lähimmäisesi vaimoa. Älä halaja lähimmäisesi huonetta, älä hänen peltoansa, älä hänen palvelijaansa, palvelijatartansa, härkäänsä, aasiansa, äläkä mitään, mikä on lähimmäisesi omaa.'''),
(1673996,58,5,5,22,'Nämä sanat Herra puhui koko teidän seurakunnallenne vuorelta, tulen ja synkkien pilvien keskeltä, suurella äänellä, eikä siihen enempää lisännyt. Ja hän kirjoitti ne kahteen kivitauluun ja antoi ne minulle.'),
(1673997,58,5,5,23,'Kun te kuulitte äänen pimeyden keskeltä, vuoren palaessa tulena, niin te astuitte minun luokseni, kaikki teidän sukukuntienne päämiehet, niin myös teidän vanhimpanne.'),
(1673998,58,5,5,24,'Ja te sanoitte: ''Katso, Herra, meidän Jumalamme, on antanut meidän nähdä kirkkautensa ja valtasuuruutensa, ja me olemme kuulleet hänen äänensä tulen keskeltä. Tänä päivänä me olemme nähneet, että Jumala voi puhua ihmisen kanssa, ja tämä jää kuitenkin henkiin.'),
(1673999,58,5,5,25,'Miksi on meidän siis kuoleminen? Sillä tämä suuri tuli kuluttaa meidät. Jos me vielä kuulemme Herran, meidän Jumalamme, äänen, niin me kuolemme.'),
(1674000,58,5,5,26,'Sillä kuka kaikesta lihasta on koskaan niinkuin me kuullut elävän Jumalan äänen puhuvan tulen keskeltä ja jäänyt henkiin?'),
(1674001,58,5,5,27,'Astu siis esiin ja kuule kaikki, mitä Herra, meidän Jumalamme, sanoo; ja puhu sinä meille kaikki, mitä Herra, meidän Jumalamme, sinulle puhuu, niin me kuulemme ja teemme.'''),
(1674002,58,5,5,28,'Ja Herra kuuli teidän puheenne, kun te puhuitte minulle, ja Herra sanoi minulle: ''Minä olen kuullut, mitä tämä kansa on puhunut sinulle. Kaikki, mitä he ovat puhuneet, on oikein puhuttu.'),
(1674003,58,5,5,29,'Jospa heillä olisi sellainen sydän, että he alati pelkäisivät minua ja noudattaisivat kaikkia minun käskyjäni, niin että he ja heidän lapsensa menestyisivät iankaikkisesti!'),
(1674004,58,5,5,30,'Mene siis ja sano heille: Palatkaa majoillenne.'),
(1674005,58,5,5,31,'Mutta jää sinä tähän minun eteeni, niin minä puhun sinulle kaikki ne käskyt, säädökset ja oikeudet, jotka sinun on opetettava heille, että he seuraisivat niitä siinä maassa, jonka minä annan heille omaksi.'''),
(1674006,58,5,5,32,'Niin noudattakaa siis tarkoin niitä, niinkuin Herra, teidän Jumalanne, on teitä käskenyt; älkää poiketko oikealle älkääkä vasemmalle,'),
(1674007,58,5,5,33,'vaan vaeltakaa aina sitä tietä, jota Herra, teidän Jumalanne, käski teidän vaeltaa, että eläisitte, menestyisitte ja elinpäivänne olisivat pitkät siinä maassa, jonka otatte omaksenne."'),
(1674008,58,5,6,1,'"Ja nämä ovat ne käskyt, säädökset ja oikeudet, jotka Herra, teidän Jumalanne, on käskenyt teille opettaa, että seuraisitte niitä siinä maassa, jota te menette ottamaan omaksenne'),
(1674009,58,5,6,2,'- että sinä pelkäisit Herraa, sinun Jumalaasi, ja noudattaisit kaikkia hänen säädöksiänsä ja käskyjänsä, jotka minä sinulle annan, sekä sinä että sinun poikasi ja poikasi poika, kaikkena elinaikanasi, ja että saisit kauan elää.'),
(1674010,58,5,6,3,'Niin kuule siis, Israel, ja noudata tarkoin niitä, että, niinkuin Herra, sinun isiesi Jumala, on sinulle luvannut, menestyisit ja te lisääntyisitte suuresti siinä maassa, joka vuotaa maitoa ja mettä.'),
(1674011,58,5,6,4,'Kuule, Israel! Herra, meidän Jumalamme, Herra on yksi.'),
(1674012,58,5,6,5,'Ja rakasta Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi ja kaikesta voimastasi.'),
(1674013,58,5,6,6,'Nämä sanat, jotka minä tänä päivänä sinulle annan, painukoot sydämeesi.'),
(1674014,58,5,6,7,'Ja teroita niitä lastesi mieleen ja puhu niistä kotona istuessasi ja tietä käydessäsi, maata pannessasi ja ylös noustessasi.'),
(1674015,58,5,6,8,'Ja sido ne merkiksi käteesi, ja ne olkoot muistolauseena sinun otsallasi.'),
(1674016,58,5,6,9,'Ja kirjoita ne talosi pihtipieliin ja portteihisi.'),
(1674017,58,5,6,10,'Kun Herra, sinun Jumalasi, on vienyt sinut siihen maahan, jonka hän isillesi, Aabrahamille, Iisakille ja Jaakobille, vannotulla valalla on luvannut antaa sinulle - suuret ja kauniit kaupungit, joita sinä et ole rakentanut,'),
(1674018,58,5,6,11,'ja talot, täynnä kaikkea hyvää, joita sinä et ole täyttänyt, ja kallioon hakatut vesisäiliöt, joita sinä et ole hakannut, viinitarhat ja öljypuut, joita sinä et ole istuttanut - ja kun sinä olet syönyt ja olet ravittu,'),
(1674019,58,5,6,12,'niin varo, ettet unhota Herraa, joka vei sinut pois Egyptin maasta, orjuuden pesästä.'),
(1674020,58,5,6,13,'Pelkää Herraa, sinun Jumalaasi, ja palvele häntä ja vanno hänen nimeensä.'),
(1674021,58,5,6,14,'Älkää kulkeko muiden jumalien perässä, niiden kansain jumalien, jotka asuvat teidän ympärillänne -'),
(1674022,58,5,6,15,'sillä Herra, sinun Jumalasi, on kiivas Jumala sinun keskelläsi - ettei Herran, sinun Jumalasi, viha syttyisi sinua vastaan ja hän hävittäisi sinua maasta.'),
(1674023,58,5,6,16,'Älkää kiusatko Herraa, teidän Jumalaanne, niinkuin kiusasitte häntä Massassa,'),
(1674024,58,5,6,17,'vaan noudattakaa Herran, teidän Jumalanne, käskyjä ja niitä todistuksia ja säädöksiä, jotka hän on sinulle antanut.'),
(1674025,58,5,6,18,'Ja tee, mikä on oikeata ja hyvää Herran silmissä, että menestyisit ja pääsisit siihen hyvään maahan, jonka Herra valalla vannoen on luvannut sinun isillesi, ja ottaisit sen omaksesi');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674026,58,5,6,19,'ja karkoittaisit tieltäsi kaikki vihollisesi, niinkuin Herra on puhunut.'),
(1674027,58,5,6,20,'Kun poikasi vastaisuudessa kysyy sinulta ja sanoo: ''Mitä merkitsevät ne todistukset, säädökset ja oikeudet, jotka Herra, meidän Jumalamme, on teille antanut?'''),
(1674028,58,5,6,21,'niin vastaa pojallesi: ''Me olimme faraon orjia Egyptissä, mutta väkevällä kädellä Herra vei meidät pois Egyptistä.'),
(1674029,58,5,6,22,'Ja Herra teki suuria ja tuhoisia tunnustekoja ja ihmeitä Egyptissä faraolle ja kaikelle hänen hoviväellensä meidän silmiemme edessä,'),
(1674030,58,5,6,23,'mutta meidät hän vei sieltä pois ja johdatti meidät siihen maahan, jonka hän valalla vannoen oli luvannut meidän isillemme, ja antoi sen meille.'),
(1674031,58,5,6,24,'Ja Herra käski meidän pitää kaikki nämä säädökset ja peljätä Herraa, meidän Jumalaamme, että me aina menestyisimme ja hän pitäisi meitä elossa, niinkuin tähän päivään saakka on tapahtunut.'),
(1674032,58,5,6,25,'Ja se on koituva meille vanhurskaudeksi, että tarkoin noudatamme kaikkia näitä käskyjä Herran, meidän Jumalamme, edessä, niinkuin hän on meitä käskenyt.''"'),
(1674033,58,5,7,1,'"Kun Herra, sinun Jumalasi, vie sinut siihen maahan, jota menet ottamaan omaksesi, ja kun hän sinun tieltäsi karkoittaa suuret kansat, heettiläiset, girgasilaiset, amorilaiset, kanaanilaiset, perissiläiset, hivviläiset ja jebusilaiset, nuo seitsemän kansaa, jotka ovat sinua suuremmat ja väkevämmät,'),
(1674034,58,5,7,2,'ja kun Herra, sinun Jumalasi, antaa ne sinulle alttiiksi ja sinä voitat ne, niin vihi heidät tuhon omiksi; älä tee liittoa heidän kanssansa äläkä osoita heille armoa.'),
(1674035,58,5,7,3,'Älä lankoudu heidän kanssansa; älä anna tyttäriäsi heidän pojillensa äläkä ota heidän tyttäriänsä pojillesi vaimoiksi.'),
(1674036,58,5,7,4,'Sillä he viettelevät sinun poikasi luopumaan minusta ja palvelemaan muita jumalia; ja silloin Herran viha syttyy teitä kohtaan, ja hän hävittää sinut nopeasti.'),
(1674037,58,5,7,5,'Vaan tehkää heille näin: kukistakaa heidän alttarinsa, murskatkaa heidän patsaansa, hakatkaa maahan heidän aserakarsikkonsa ja polttakaa tulessa heidän jumalankuvansa.'),
(1674038,58,5,7,6,'Sillä sinä olet Herralle, Jumalallesi, pyhitetty kansa; Herra, sinun Jumalasi, on valinnut sinut omaisuuskansakseen ennen kaikkia muita kansoja, mitä maan päällä on.'),
(1674039,58,5,7,7,'Ei Herra sentähden ole mielistynyt teihin ja valinnut teitä, että olisitte lukuisammat kaikkia muita kansoja, sillä tehän olette kaikkia muita kansoja vähälukuisemmat,'),
(1674040,58,5,7,8,'vaan sen tähden, että Herra rakasti teitä ja tahtoi pitää valan, jonka hän oli vannonut teidän isillenne; niin Herra vei teidät pois väkevällä kädellä ja vapahti sinut orjuuden pesästä, faraon, Egyptin kuninkaan, käsistä.'),
(1674041,58,5,7,9,'Ja tiedä siis, että Herra, sinun Jumalasi, on Jumala, uskollinen Jumala, joka pitää liiton ja on laupias tuhansiin polviin asti niille, jotka häntä rakastavat ja pitävät hänen käskynsä,'),
(1674042,58,5,7,10,'mutta kostaa sille, joka häntä vihaa, ja hukuttaa hänet. Hän ei vitkastele, vaan kostaa sille, joka häntä vihaa.'),
(1674043,58,5,7,11,'Noudata siis niitä käskyjä, säädöksiä ja oikeuksia, jotka minä tänä päivänä sinulle annan, ja pidä ne.'),
(1674044,58,5,7,12,'Jos te tottelette näitä säädöksiä, noudatatte ja seuraatte niitä, niin Herra, sinun Jumalasi, pitää liittonsa ja on laupias sinulle, niinkuin hän valalla vannoen on sinun isillesi luvannut.'),
(1674045,58,5,7,13,'Ja hän rakastaa sinua, siunaa sinua ja antaa sinun lisääntyä; hän siunaa sinun kohtusi hedelmän ja maasi hedelmän, siunaa sinun viljasi, viinisi ja öljysi, sinun raavaittesi vasikat ja lampaittesi karitsat siinä maassa, jonka hän isillesi vannotulla valalla on luvannut antaa sinulle.'),
(1674046,58,5,7,14,'Siunattu olet sinä oleva yli kaikkien muitten kansojen. Hedelmätöntä miestä tai naista ei ole sinun keskuudessasi oleva, ei myöskään sinun karjassasi yhtään hedelmätöntä.'),
(1674047,58,5,7,15,'Ja Herra on poistava sinusta kaikki sairaudet; ei ainoatakaan Egyptin kovista taudeista, jotka sinä tunnet, hän ole paneva sinun kärsittäväksesi, vaan hän antaa niiden tulla kaikkiin niihin, jotka sinua vihaavat.'),
(1674048,58,5,7,16,'Tuhoa kaikki kansat, jotka Herra, sinun Jumalasi, antaa sinulle; älä heitä sääli. Älä myöskään palvele heidän jumaliansa, sillä se tulee sinulle paulaksi.'),
(1674049,58,5,7,17,'Vaikka ajatteletkin sydämessäsi: ''Nämä kansat ovat minua suuremmat, kuinka minä voisin ne karkoittaa?'''),
(1674050,58,5,7,18,'niin älä kuitenkaan pelkää niitä; muista, mitä Herra, sinun Jumalasi, teki faraolle ja kaikille egyptiläisille,'),
(1674051,58,5,7,19,'niitä suuria koettelemuksia, jotka sinä näit omin silmin, ja niitä tunnustekoja ja ihmeitä ja sitä väkevätä kättä ja ojennettua käsivartta, joilla Herra, sinun Jumalasi, vei sinut pois. Samoin on Herra, sinun Jumalasi, tekevä kaikille niille kansoille, joita sinä pelkäät.'),
(1674052,58,5,7,20,'Niin, Herra, sinun Jumalasi, lähettää heidän kimppuunsa herhiläisiä, kunnes ne, jotka ovat jäljellä ja ovat sinulta piiloutuneet, ovat hävitetyt.'),
(1674053,58,5,7,21,'Älä heitä säikähdy, sillä Herra, sinun Jumalasi, on sinun keskelläsi, suuri ja peljättävä Jumala.'),
(1674054,58,5,7,22,'Ja Herra, sinun Jumalasi, karkoittaa nämä kansat sinun tieltäsi vähitellen. Älä lopeta heitä yhtäkkiä, etteivät metsän pedot lisääntyisi sinun vahingoksesi.'),
(1674055,58,5,7,23,'Herra, sinun Jumalasi, antaa heidät sinulle alttiiksi ja saattaa heidät suureen hämminkiin, kunnes he tuhoutuvat,'),
(1674056,58,5,7,24,'ja hän antaa heidän kuninkaansa sinun käsiisi, ja sinä hävität heidän nimensä taivaan alta. Ei kukaan kestä sinun edessäsi, vaan sinä tuhoat heidät.'),
(1674057,58,5,7,25,'Heidän jumaliensa kuvat polttakaa tulessa. Älä himoitse hopeata ja kultaa, joka niissä on, äläkä ota siitä itsellesi mitään, ettet joutuisi sen paulaan, sillä se on Herralle, sinun Jumalallesi, kauhistus.'),
(1674058,58,5,7,26,'Äläkä vie sitä kauhistusta taloosi, ettet sinäkin samoin kuin se joutuisi vihittäväksi tuhon omaksi. Katso se inhottavaksi ja kauhistavaksi, sillä se on vihitty tuhon omaksi."'),
(1674059,58,5,8,1,'"Pitäkää tarkoin kaikki käskyt, jotka minä tänä päivänä sinulle annan, että eläisitte ja lisääntyisitte ja pääsisitte ottamaan omaksenne sen maan, jonka Herra valalla vannoen on luvannut teidän isillenne.'),
(1674060,58,5,8,2,'Ja muista kaikki, mitä on tapahtunut sillä tiellä, jota Herra, sinun Jumalasi, näinä neljänäkymmenenä vuotena on sinua kuljettanut erämaassa nöyryyttääksensä sinua ja koetellaksensa sinua ja tietääksensä, mitä sinun sydämessäsi on: tahdotko noudattaa hänen käskyjänsä vai etkö.'),
(1674061,58,5,8,3,'Hän nöyryytti sinua ja antoi sinun nähdä nälkää, ja hän antoi sinulle mannaa syödä, jota et ennen tuntenut ja jota eivät isäsikään tunteneet, opettaaksensa sinut ymmärtämään, että ihminen ei elä ainoastaan leivästä, vaan että hän elää jokaisesta sanasta, joka Herran suusta lähtee.'),
(1674062,58,5,8,4,'Sinun vaatteesi eivät kuluneet yltäsi, eivätkä sinun jalkasi ajettuneet näinä neljänäkymmenenä vuotena.'),
(1674063,58,5,8,5,'Tiedä siis sydämessäsi, että Herra, sinun Jumalasi, kasvattaa sinua, niinkuin isä kasvattaa poikaansa.'),
(1674064,58,5,8,6,'Ja noudata Herran, sinun Jumalasi, käskyjä, vaella hänen teitänsä ja pelkää häntä.'),
(1674065,58,5,8,7,'Sillä Herra, sinun Jumalasi, vie sinut hyvään maahan, laaksoissa ja vuorilla vuotavien purojen, lähteiden ja syvien vesien maahan,'),
(1674066,58,5,8,8,'nisun ja ohran, viiniköynnöksen, viikunapuun ja granaattiomenapuun maahan, jalostetun öljypuun ja hunajan maahan,'),
(1674067,58,5,8,9,'maahan, jossa sinun ei tarvitse puutteessa leipääsi syödä eikä mitään puutetta nähdä, maahan, jonka kivet ovat rautaa ja jonka vuorista voit louhia vaskea.'),
(1674068,58,5,8,10,'Kun sinä syöt ja tulet ravituksi, niin ylistä Herraa, sinun Jumalaasi, siitä hyvästä maasta, jonka hän on antanut sinulle.'),
(1674069,58,5,8,11,'Varo, ettet unhota Herraa, sinun Jumalaasi, ja muista noudattaa hänen käskyjänsä, oikeuksiansa ja säädöksiänsä, jotka minä tänä päivänä sinulle annan.'),
(1674070,58,5,8,12,'Kun sinä syöt ja tulet ravituksi, kun rakennat kauniita taloja ja asut niissä,'),
(1674071,58,5,8,13,'kun karjasi ja lampaasi lisääntyvät ja kun hopeasi ja kultasi lisääntyy ja kaikki, mitä sinulla on, lisääntyy,'),
(1674072,58,5,8,14,'niin älköön sydämesi ylpistykö, äläkä unhota Herraa, sinun Jumalaasi, joka vei sinut pois Egyptin maasta, orjuuden pesästä,'),
(1674073,58,5,8,15,'kuljetti sinua suuressa ja hirmuisessa, myrkyllisten käärmeiden ja skorpionien ja kuivien, vedettömien maiden erämaassa, vuodatti sinulle vettä kovasta kalliosta'),
(1674074,58,5,8,16,'ja antoi erämaassa sinulle mannaa syödä, jota sinun isäsi eivät tunteneet - nöyryyttääksensä ja koetellaksensa sinua ja lopuksi sinulle hyvää tehdäksensä.'),
(1674075,58,5,8,17,'Älä ajattele sydämessäsi: ''Oma voimani ja oman käteni väkevyys on hankkinut minulle tämän rikkauden'',');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674076,58,5,8,18,'vaan muista, että Herra, sinun Jumalasi, antaa sinulle voiman hankkia rikkautta pitääkseen liittonsa, jonka hän valalla vannoen teki sinun isiesi kanssa, niinkuin tähän päivään saakka on tapahtunut.'),
(1674077,58,5,8,19,'Mutta jos sinä unhotat Herran, sinun Jumalasi, ja seuraat muita jumalia, palvelet niitä ja kumarrat niitä, niin minä vakuutan teille tänä päivänä, että te peräti hukutte.'),
(1674078,58,5,8,20,'Niinkuin ne kansat, jotka Herra hukuttaa teidän tieltänne, niin tekin hukutte, kun ette kuulleet Herraa, teidän Jumalaanne."'),
(1674079,58,5,9,1,'"Kuule, Israel! Sinä menet nyt Jordanin yli laskeaksesi valtasi alle kansoja, jotka ovat sinua suuremmat ja väkevämmät, ja suuria, taivaan tasalle varustettuja kaupunkeja,'),
(1674080,58,5,9,2,'anakilaisten suuren ja kookkaan kansan, jonka sinä tunnet ja josta olet kuullut sanottavan: ''Kuka kestää anakilaisten edessä?'''),
(1674081,58,5,9,3,'Niin tiedä nyt, että Herra, sinun Jumalasi, käy sinun edelläsi niinkuin kuluttava tuli; hän hävittää heidät ja nöyryyttää heidät sinun edessäsi, ja sinä karkoitat heidät ja hukutat heidät nopeasti, niinkuin Herra on sinulle puhunut.'),
(1674082,58,5,9,4,'Kun Herra, sinun Jumalasi, työntää heidät sinun tieltäsi, niin älä ajattele sydämessäsi näin: ''Minun vanhurskauteni tähden Herra on tuonut minut ottamaan tämän maan omakseni''. Sillä näiden kansojen jumalattomuuden tähden Herra karkoittaa heidät sinun tieltäsi.'),
(1674083,58,5,9,5,'Et sinä vanhurskautesi ja oikeamielisyytesi tähden pääse ottamaan heidän maatansa omaksesi, vaan näiden kansojen jumalattomuuden tähden Herra, sinun Jumalasi, karkoittaa heidät sinun tieltäsi ja täyttääksensä, mitä Herra valalla vannoen on luvannut sinun isillesi, Aabrahamille, Iisakille ja Jaakobille.'),
(1674084,58,5,9,6,'Tiedä siis, ettei Herra, sinun Jumalasi, sinun vanhurskautesi tähden anna sinulle tätä hyvää maata omaksesi; sillä sinä olet niskurikansa.'),
(1674085,58,5,9,7,'Muista äläkä unhota, kuinka sinä erämaassa vihoitit Herran, sinun Jumalasi. Siitä päivästä alkaen, jona sinä lähdit Egyptin maasta, aina siihen saakka, kun te tulitte tähän paikkaan, te olette niskoitelleet Herraa vastaan.'),
(1674086,58,5,9,8,'Myöskin Hoorebilla te vihoititte Herran, ja Herra vihastui teihin, niin että hän aikoi tuhota teidät.'),
(1674087,58,5,9,9,'Kun minä olin noussut vuorelle vastaanottamaan kivitaulut, sen liiton taulut, jonka Herra oli tehnyt teidän kanssanne, olin minä vuorella neljäkymmentä päivää ja neljäkymmentä yötä syömättä ja juomatta.'),
(1674088,58,5,9,10,'Ja Herra antoi minulle ne kaksi kivitaulua, joihin oli kirjoitettu Jumalan sormella, ja niissä oli kaikki ne sanat, jotka Herra oli puhunut teille vuorelta, tulen keskeltä, silloin kun seurakunta oli koolla.'),
(1674089,58,5,9,11,'Ja niiden neljänkymmenen päivän ja neljänkymmenen yön kuluttua Herra antoi minulle ne kaksi kivitaulua, liitontaulut.'),
(1674090,58,5,9,12,'Ja Herra sanoi minulle: ''Nouse ja astu nopeasti täältä alas, sillä sinun kansasi, jonka sinä veit pois Egyptistä, on turmion tehnyt. Pian he poikkesivat siltä tieltä, jota minä käskin heidän vaeltaa; he tekivät itselleen valetun kuvan.'''),
(1674091,58,5,9,13,'Ja Herra puhui minulle sanoen: ''Minä olen nähnyt, että tämä kansa on niskurikansa.'),
(1674092,58,5,9,14,'Anna minun olla, minä tuhoan heidät ja pyyhin pois heidän nimensä taivaan alta. Mutta sinusta minä teen väkevämmän ja lukuisamman kansan, kuin se on.'''),
(1674093,58,5,9,15,'Silloin minä käännyin ja astuin alas vuorelta, vuoren palaessa tulena; ja minulla oli käsissäni ne kaksi liitontaulua.'),
(1674094,58,5,9,16,'Ja niin minä näin, että te olitte rikkoneet Herraa, teidän Jumalaanne, vastaan: olitte tehneet itsellenne valetun vasikankuvan, pian poikenneet siltä tieltä, jota Herra oli käskenyt teidän vaeltaa.'),
(1674095,58,5,9,17,'Silloin minä tartuin molempiin tauluihin ja heitin ne käsistäni ja murskasin ne teidän silmienne edessä.'),
(1674096,58,5,9,18,'Ja minä heittäydyin Herran eteen ja olin, niinkuin edelliselläkin kerralla, neljäkymmentä päivää ja neljäkymmentä yötä syömättä ja juomatta, kaiken sen synnin tähden, jota te olitte tehneet, kun teitte sitä, mikä on pahaa Herran silmissä, ja vihoititte hänet.'),
(1674097,58,5,9,19,'Sillä minä pelkäsin sitä vihaa ja kiivautta teitä vastaan, joka oli vallannut Herran, niin että hän aikoi tuhota teidät. Ja Herra kuuli minua vielä silläkin kertaa.'),
(1674098,58,5,9,20,'Myöskin Aaroniin Herra vihastui niin suuresti, että hän aikoi tuhota hänet, ja minä rukoilin silloin myöskin Aaronin puolesta.'),
(1674099,58,5,9,21,'Sitten minä otin teidän tekemänne syntikuvatuksen, vasikan, ja poltin sen tulessa, löin sen palasiksi ja rouhensin sen hienoksi, aivan kuin tuhaksi, ja sen tuhan minä heitin puroon, joka juoksi vuorelta.'),
(1674100,58,5,9,22,'Tabeerassa, Massassa ja Kibrot-Hattaavassa te vielä vihoititte Herran.'),
(1674101,58,5,9,23,'Ja kun Herra tahtoi lähettää teidät Kaades-Barneasta ja sanoi: ''Menkää ja ottakaa omaksenne se maa, jonka minä teille annan'', niin te niskoittelitte Herran, teidän Jumalanne, käskyä vastaan ettekä uskoneet häneen ettekä kuulleet hänen ääntänsä.'),
(1674102,58,5,9,24,'Te olette niskoitelleet Herraa, teidän Jumalaanne, vastaan aina siitä päivästä alkaen, jona minä opin teidät tuntemaan.'),
(1674103,58,5,9,25,'Silloin minä heittäydyin Herran eteen ja olin siinä neljäkymmentä päivää ja neljäkymmentä yötä; sillä Herra oli sanonut aikovansa tuhota teidät.'),
(1674104,58,5,9,26,'Ja minä rukoilin Herraa ja sanoin: Herra, Herra, älä tuhoa kansaasi ja perintöosaasi, jonka sinä suuruudessasi vapahdit ja jonka sinä veit pois Egyptistä väkevällä kädellä.'),
(1674105,58,5,9,27,'Muista palvelijoitasi Aabrahamia, Iisakia ja Jaakobia, älä katso tämän kansan uppiniskaisuutta, jumalattomuutta ja syntiä,'),
(1674106,58,5,9,28,'ettei sanottaisi siinä maassa, josta sinä veit meidät pois: ''Koska Herra ei kyennyt viemään heitä siihen maahan, jonka hän oli heille luvannut, ja koska hän vihasi heitä, vei hän heidät täältä pois surmatakseen heidät erämaassa''.'),
(1674107,58,5,9,29,'Ovathan he sinun kansasi ja perintöosasi, jonka sinä veit sieltä pois suurella voimallasi ja ojennetulla käsivarrellasi."'),
(1674108,58,5,10,1,'"Silloin Herra sanoi minulle: ''Veistä itsellesi kaksi kivitaulua, entisten kaltaista, ja nouse vuorelle minun tyköni; tee myös itsellesi puusta arkki.'),
(1674109,58,5,10,2,'Minä kirjoitan niihin tauluihin ne sanat, jotka olivat entisissä tauluissa, niissä, jotka sinä murskasit; pane ne arkkiin.'''),
(1674110,58,5,10,3,'Niin minä tein arkin akasiapuusta ja veistin kaksi kivitaulua, entisten kaltaista. Ja minä nousin vuorelle, kädessäni ne kaksi taulua.'),
(1674111,58,5,10,4,'Ja hän kirjoitti tauluihin saman, minkä edellisellä kerralla, ne kymmenen sanaa, jotka Herra oli puhunut teille vuorelta, tulen keskeltä, seurakunnan kokouspäivänä. Ja Herra antoi ne minulle.'),
(1674112,58,5,10,5,'Sitten minä käännyin ja astuin alas vuorelta ja panin taulut tekemääni arkkiin, niinkuin Herra oli minua käskenyt, ja siinä ne ovat.'),
(1674113,58,5,10,6,'Ja israelilaiset lähtivät liikkeelle Bene-Jaakanin kaivoilta ja vaelsivat Mooseraan. Siellä kuoli Aaron, ja hänet haudattiin sinne; ja hänen poikansa Eleasar tuli papiksi hänen sijaansa.'),
(1674114,58,5,10,7,'Sieltä he lähtivät liikkeelle Gudgodaan, ja Gudgodasta Jotbataan, seutuun, jossa on vesipuroja.'),
(1674115,58,5,10,8,'Siihen aikaan Herra erotti Leevin sukukunnan kantamaan Herran liitonarkkia, seisomaan Herran edessä, palvelemaan häntä ja siunaamaan hänen nimeensä, niinkuin tähän päivään saakka on tapahtunut.'),
(1674116,58,5,10,9,'Sentähden Leevi ei saanut osuutta eikä perintöosaa veljiensä rinnalla, sillä Herra on hänen perintöosansa, niinkuin Herra, sinun Jumalasi, on hänelle puhunut.'),
(1674117,58,5,10,10,'Ja minä viivyin vuorella, niinkuin edelliselläkin kerralla, neljäkymmentä päivää ja neljäkymmentä yötä; ja Herra kuuli minua vielä silläkin kertaa, sillä Herra ei tahtonut tuhota sinua.'),
(1674118,58,5,10,11,'Ja Herra sanoi minulle: ''Nouse ja lähde, kulje kansan edellä, että he menevät ja ottavat omakseen maan, jonka minä heidän isillensä vannotulla valalla olen luvannut antaa heille''.'),
(1674119,58,5,10,12,'Ja nyt, Israel, mitä Herra, sinun Jumalasi, sinulta muuta vaatii, kuin että pelkäät Herraa, sinun Jumalaasi, että aina vaellat hänen teitänsä ja rakastat häntä, ja että palvelet Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi,'),
(1674120,58,5,10,13,'noudattaen Herran käskyjä ja säädöksiä, jotka minä sinulle tänä päivänä annan, että menestyisit.'),
(1674121,58,5,10,14,'Katso, taivaat ja taivasten taivaat, maa ja kaikki, mitä siinä on, ovat Herran, sinun Jumalasi.'),
(1674122,58,5,10,15,'Mutta ainoastaan sinun isiisi Herra mielistyi ja rakasti heitä; ja hän valitsi omikseen heidän jälkeläisensä, hän valitsi teidät kaikista kansoista, niinkuin yhä vielä on.'),
(1674123,58,5,10,16,'Ympärileikatkaa sentähden sydämenne älkääkä olko enää niskureita.'),
(1674124,58,5,10,17,'Sillä Herra, teidän Jumalanne, on jumalain Jumala ja herrain Herra, suuri, voimallinen ja peljättävä Jumala, joka ei katso henkilöön eikä ota lahjusta,'),
(1674125,58,5,10,18,'joka hankkii orvolle ja leskelle oikeuden ja joka rakastaa muukalaista ja antaa hänelle ruuan ja vaatteen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674126,58,5,10,19,'Sentähden rakastakaa muukalaista, sillä te olette itse olleet muukalaisina Egyptin maassa.'),
(1674127,58,5,10,20,'Herraa, sinun Jumalaasi, pelkää, häntä palvele, hänessä riipu kiinni ja vanno hänen nimeensä.'),
(1674128,58,5,10,21,'Hän on sinun ylistyksesi, ja hän on sinun Jumalasi, joka on tehnyt sinulle ne suuret ja peljättävät teot, jotka sinun silmäsi ovat nähneet.'),
(1674129,58,5,10,22,'Seitsemänkymmentä henkeä oli sinun isiesi joukkoa, kun he menivät Egyptiin, mutta nyt Herra, sinun Jumalasi, on tehnyt sinun lukusi paljoksi niinkuin taivaan tähdet."'),
(1674130,58,5,11,1,'"Rakasta siis Herraa, sinun Jumalaasi, ja noudata alati hänen määräyksiänsä, säädöksiänsä, oikeuksiansa ja käskyjänsä.'),
(1674131,58,5,11,2,'Ja huomatkaa tänä päivänä, etten minä nyt puhu teidän lapsillenne, jotka eivät ole kokeneet eivätkä nähneet Herran, teidän Jumalanne, kuritusta, hänen suuruuttansa, väkevää kättänsä ja ojennettua käsivarttansa,'),
(1674132,58,5,11,3,'eivät hänen tunnustekojaan ja töitään, jotka hän teki Egyptissä faraolle, Egyptin kuninkaalle, ja koko hänen maalleen,'),
(1674133,58,5,11,4,'eivätkä, mitä hän teki egyptiläisten sotajoukolle, heidän hevosillensa ja vaunuillensa, joiden päälle hän vyörytti Kaislameren vedet, kun he ajoivat teitä takaa, ja jotka Herra hukutti, niin ettei heitä enää ole,'),
(1674134,58,5,11,5,'eivätkä, mitä hän teki teille erämaassa, aina siihen saakka, kunnes te tulitte tähän paikkaan,'),
(1674135,58,5,11,6,'eivätkä, mitä hän teki Daatanille ja Abiramille, Eliabin, Ruubenin pojan, pojille, kun maa avasi kitansa ja koko Israelin keskeltä nielaisi heidät ja heidän perheensä ja majansa ja kaiken, mitä heillä oli mukanansa;'),
(1674136,58,5,11,7,'vaan minä puhun teille, jotka olette omin silmin nähneet kaikki Herran suuret teot, jotka hän on tehnyt.'),
(1674137,58,5,11,8,'Niin pitäkää kaikki käskyt, jotka minä tänä päivänä teille annan, että te tulisitte voimakkaiksi, menisitte ja ottaisitte omaksenne sen maan, jota nyt menette omaksenne ottamaan,'),
(1674138,58,5,11,9,'ja että te kauan eläisitte siinä maassa, jonka Herra teidän isillenne vannotulla valalla on luvannut antaa heille ja heidän jälkeläisillensä, maan, joka vuotaa maitoa ja mettä.'),
(1674139,58,5,11,10,'Sillä se maa, jota sinä menet omaksesi ottamaan, ei ole niinkuin Egyptin maa, josta te olette lähteneet ja jota sinä, siemenesi siihen kylvettyäsi, jalalla polkien kastelit niinkuin vihannestarhaa.'),
(1674140,58,5,11,11,'Vaan se maa, jota te menette omaksenne ottamaan, on maa, jossa on vuoria ja laaksoja ja joka juo vettä taivaan sateesta,'),
(1674141,58,5,11,12,'maa, josta Herra, sinun Jumalasi, pitää huolen ja jota Herran, sinun Jumalasi, silmät aina katsovat, vuoden alusta sen loppuun saakka.'),
(1674142,58,5,11,13,'Ja jos nyt tottelette minun käskyjäni, jotka minä tänä päivänä teille annan, niin että rakastatte Herraa, teidän Jumalaanne, ja palvelette häntä kaikesta sydämestänne ja kaikesta sielustanne,'),
(1674143,58,5,11,14,'niin minä annan teidän maallenne sateen ajallansa, syyssateen ja kevätsateen, ja sinä saat korjata viljasi ja viinisi ja öljysi.'),
(1674144,58,5,11,15,'Ja minä annan sinun karjallesi ruohoa kedoillasi; ja sinä syöt ja tulet ravituksi.'),
(1674145,58,5,11,16,'Varokaa, ettei teidän sydämenne antaudu vieteltäväksi, niin että poikkeatte pois ja palvelette muita jumalia ja niitä kumarratte;'),
(1674146,58,5,11,17,'muutoin Herran viha syttyy teitä kohtaan, ja hän sulkee taivaan, niin ettei tule sadetta eikä maa anna satoansa, ja te häviätte pian siitä hyvästä maasta, jonka Herra teille antaa.'),
(1674147,58,5,11,18,'Painakaa siis nämä minun sanani sydämeenne ja mieleenne ja sitokaa ne merkiksi käteenne, ja ne olkoot muistolauseena otsallanne;'),
(1674148,58,5,11,19,'ja opettakaa ne lapsillenne, niin että puhut niistä kotona istuessasi ja tietä käydessäsi, maata pannessasi ja ylös noustessasi.'),
(1674149,58,5,11,20,'Ja kirjoita ne talosi pihtipieliin ja portteihisi,'),
(1674150,58,5,11,21,'että te ja teidän lapsenne kauan eläisitte siinä maassa, jonka Herra teidän isillenne vannotulla valalla lupasi antaa heille, niin kauan kuin taivas maan yli kaareutuu.'),
(1674151,58,5,11,22,'Sillä jos te pidätte kaikki nämä käskyt, jotka minä teille annan, ja seuraatte niitä, niin että rakastatte Herraa, teidän Jumalaanne, ja aina vaellatte hänen teitänsä ja riiputte hänessä kiinni,'),
(1674152,58,5,11,23,'niin Herra karkoittaa kaikki nämä kansat teidän tieltänne, ja te laskette valtanne alle kansoja, jotka ovat teitä suuremmat ja väkevämmät.'),
(1674153,58,5,11,24,'Mihin paikkaan te jalkanne astutte, se on oleva teidän. Erämaasta ja Libanonista, virrasta, Eufrat-virrasta, aina Länsimereen saakka on teidän alueenne ulottuva.'),
(1674154,58,5,11,25,'Ei kukaan kestä teidän edessänne. Kauhuun ja peljästykseen teidän edessänne on Herra saattava koko sen maan, johon te astutte, niinkuin hän on teille puhunut.'),
(1674155,58,5,11,26,'Katso, minä asetan tänä päivänä teidän eteenne siunauksen ja kirouksen:'),
(1674156,58,5,11,27,'siunauksen, jos te tottelette Herran, teidän Jumalanne, käskyjä, jotka minä tänä päivänä teille annan,'),
(1674157,58,5,11,28,'mutta kirouksen, jos te ette tottele Herran, teidän Jumalanne, käskyjä, vaan poikkeatte siltä tieltä, jota minä tänä päivänä käsken teidän vaeltaa, ja seuraatte muita jumalia, joita te ette tunne.'),
(1674158,58,5,11,29,'Ja kun Herra, sinun Jumalasi, on vienyt sinut siihen maahan, jota sinä nyt menet omaksesi ottamaan, niin tee Garissimin vuoresta siunauksen paikka ja Eebalin vuoresta kirouksen paikka."'),
(1674159,58,5,11,30,'Ne ovat toisella puolella Jordanin, länteen päin auringonlaskun tiestä, kanaanilaisten maassa, niiden, jotka asuvat Aromaassa, vastapäätä Gilgalia, Mooren tammiston luona.'),
(1674160,58,5,11,31,'"Sillä te kuljette Jordanin yli ja menette ottamaan omaksenne sen maan, jonka Herra, teidän Jumalanne, teille antaa. Kun sitten olette ottaneet sen omaksenne ja asettuneet siihen,'),
(1674161,58,5,11,32,'niin noudattakaa tarkoin kaikkia niitä käskyjä ja oikeuksia, jotka minä tänä päivänä teille annan."'),
(1674162,58,5,12,1,'"Nämä ovat ne käskyt ja oikeudet, joita teidän on tarkoin noudatettava siinä maassa, jonka Herra, sinun isiesi Jumala, sinulle antaa, että ottaisit sen omaksesi - noudatettava niin kauan kuin elätte maan päällä.'),
(1674163,58,5,12,2,'Hävittäkää perin pohjin kaikki ne paikat, missä karkoittamanne kansat ovat jumaliansa palvelleet, korkeilla vuorilla, kukkuloilla tai viheriäin puiden alla.'),
(1674164,58,5,12,3,'Kukistakaa heidän alttarinsa, murskatkaa heidän patsaansa, polttakaa tulessa heidän asera-karsikkonsa ja hakatkaa maahan heidän jumaliensa kuvat, ja hävittäkää heidän nimensä niistä paikoista.'),
(1674165,58,5,12,4,'Palvellessanne Herraa, teidän Jumalaanne, älkää tehkö niinkuin he,'),
(1674166,58,5,12,5,'vaan se paikka, jonka Herra, teidän Jumalanne, valitsee teidän sukukuntienne alueelta ja johon hän asettaa nimensä asuaksensa siellä, se etsikää, ja mene sinne.'),
(1674167,58,5,12,6,'Ja sinne viekää polttouhrinne ja teurasuhrinne, kymmenyksenne, kätenne anti, lupausuhrinne ja vapaaehtoiset uhrinne sekä raavaittenne ja lampaittenne esikoiset.'),
(1674168,58,5,12,7,'Ja siellä syökää Herran, teidän Jumalanne, edessä, ja iloitkaa perheinenne kaikesta, mitä kätenne on hankkinut, millä Herra, sinun Jumalasi, on sinua siunannut.'),
(1674169,58,5,12,8,'Älkää tehkö, niinkuin me tässä tänä päivänä teemme, jokainen sitä, mikä hänen omasta mielestään on oikein,'),
(1674170,58,5,12,9,'sillä te ette vielä ole päässeet lepoon ettekä siihen perintömaahan, jonka Herra, sinun Jumalasi, on sinulle antava.'),
(1674171,58,5,12,10,'Mutta kun olette menneet Jordanin yli ja asettuneet siihen maahan, jonka Herra, teidän Jumalanne, jakaa teille perinnöksi, ja kun hän on suonut teidän päästä rauhaan kaikista vihollisistanne joka taholta, niin että asutte turvassa,'),
(1674172,58,5,12,11,'silloin viekää siihen paikkaan, jonka Herra, teidän Jumalanne, valitsee nimensä asuinsijaksi, kaikki, mitä minä käsken teidän viedä: polttouhrinne ja teurasuhrinne, kymmenyksenne, kätenne anti, niin myös kaikki parhaat lupausuhrinne, jotka te lupaatte Herralle.'),
(1674173,58,5,12,12,'Ja iloitkaa Herran, teidän Jumalanne, edessä, sekä te että teidän poikanne ja tyttärenne, palvelijanne ja palvelijattarenne, ja leeviläiset, jotka asuvat teidän porttienne sisäpuolella, sillä heillä ei ole osuutta eikä perintöosaa teidän rinnallanne.'),
(1674174,58,5,12,13,'Varo, ettet uhraa polttouhrejasi missä mieleisessäsi paikassa hyvänsä.'),
(1674175,58,5,12,14,'Vaan siinä paikassa, jonka Herra valitsee jonkun sinun sukukuntasi alueelta, siinä uhraa polttouhrisi ja tee kaikki, mitä minä käsken sinun tehdä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674176,58,5,12,15,'Kuitenkin saat kaikkialla porttiesi sisäpuolella teurastaa mielinmäärin ja syödä lihaa, sen mukaan kuin Herra, sinun Jumalasi, sinulle siunaa. Sekä saastainen että puhdas saakoon syödä sitä, niinkuin syödään gasellia tai peuraa.'),
(1674177,58,5,12,16,'Vain verta älkää syökö, vuodattakaa se maahan niinkuin vesi.'),
(1674178,58,5,12,17,'Sinä et saa omien porttiesi sisäpuolella syödä jyviesi, viinisi ja öljysi kymmenyksiä etkä myöskään raavaittesi ja lampaittesi esikoisia etkä mitään lupaamaasi lupausuhria tai vapaaehtoisia uhreja tai kätesi antia,'),
(1674179,58,5,12,18,'vaan syö niitä Herran, sinun Jumalasi, edessä siinä paikassa, jonka Herra, sinun Jumalasi, valitsee, sekä sinä että sinun poikasi ja tyttäresi, sinun palvelijasi ja palvelijattaresi ja leeviläinen, joka asuu sinun porttiesi sisäpuolella; ja iloitse näin Herran, sinun Jumalasi, edessä kaikesta, mitä kätesi on hankkinut.'),
(1674180,58,5,12,19,'Varo, ettet jätä osattomaksi leeviläistä, niin kauan kuin sinä elät maassasi.'),
(1674181,58,5,12,20,'Kun Herra, sinun Jumalasi, on laajentanut sinun alueesi, niinkuin hän on sinulle luvannut, ja sinä ajattelet: ''Minä tahdon syödä lihaa'' - koska haluat syödä lihaa - niin syö lihaa mielinmäärin.'),
(1674182,58,5,12,21,'Jos se paikka, jonka Herra, sinun Jumalasi, valitsee asettaakseen siihen nimensä, on liian kaukana sinusta, niin teurasta, niinkuin minä olen sinua käskenyt, raavaitasi ja lampaitasi, joita Herra on sinulle antanut, ja syö niitä porttiesi sisäpuolella mielinmäärin.'),
(1674183,58,5,12,22,'Mutta syö niitä, niinkuin syödään gasellia ja peuraa; niinhyvin saastainen kuin puhdas saakoon syödä niitä.'),
(1674184,58,5,12,23,'Ole vain luja siinä, ettet syö verta; sillä veri on sielu, ja sielua sinun ei pidä syömän lihan kanssa.'),
(1674185,58,5,12,24,'Älä syö sitä; vuodata se maahan niinkuin vesi.'),
(1674186,58,5,12,25,'Älä syö sitä, että menestyisit, sinä ja sinun lapsesi sinun jälkeesi, kun teet, mikä oikeata on Herran silmissä.'),
(1674187,58,5,12,26,'Mutta pyhät lahjasi, jotka sinä tuot, sekä lupausuhrisi, ota ja vie siihen paikkaan, jonka Herra on valinnut.'),
(1674188,58,5,12,27,'Ja uhraa polttouhrisi, sekä liha että veri, Herran, sinun Jumalasi, alttarilla. Teurasuhreistasi vuodatettakoon veri Herran, sinun Jumalasi, alttarille, mutta lihan sinä saat syödä.'),
(1674189,58,5,12,28,'Noudata ja tottele kaikkia näitä sanoja, jotka minä sinulle annan, että menestyisit, sinä ja sinun lapsesi sinun jälkeesi, ikuisesti, kun teet sitä, mikä on hyvää ja oikeata Herran, sinun Jumalasi, silmissä.'),
(1674190,58,5,12,29,'Kun Herra, sinun Jumalasi, on hävittänyt ne kansat, joita sinä menet karkoittamaan tieltäsi, ja kun olet karkoittanut heidät ja asettunut heidän maahansa,'),
(1674191,58,5,12,30,'niin varo, sittenkuin he ovat hävitetyt sinun tieltäsi, ettet kietoudu heidän pauloihinsa, heitä seuraamaan, ja ettet etsi heidän jumaliansa ja kysy: ''Miten oli näiden kansojen tapana palvella jumaliansa, että minäkin tekisin niin?'''),
(1674192,58,5,12,31,'Älä tee niin Herraa, sinun Jumalaasi, kohtaan, sillä kaikkea, mikä on Herralle kauhistus ja mitä hän vihaa, he ovat tehneet palvellessaan jumaliansa: omia poikiansakin ja tyttäriänsä he ovat jumalillensa polttaneet.'),
(1674193,58,5,12,32,'Kaikkea, mitä minä käsken, noudattakaa tarkoin. Älkää siihen mitään lisätkö älkääkä siitä mitään ottako pois."'),
(1674194,58,5,13,1,'"Jos teidän keskuuteenne ilmestyy profeetta tai unennäkijä ja lupaa sinulle jonkun tunnusteon tai ihmeen,'),
(1674195,58,5,13,2,'ja jos sitten todellakin tapahtuu se tunnusteko tai ihme, josta hän puhui sinulle sanoen: ''Lähtekäämme seuraamaan muita jumalia, joita te ette tunne, ja palvelkaamme niitä'','),
(1674196,58,5,13,3,'niin älä kuuntele sen profeetan puhetta tai sitä unennäkijää, sillä Herra, teidän Jumalanne, ainoastaan koettelee teitä tietääksensä, rakastatteko Herraa, teidän Jumalaanne, kaikesta sydämestänne ja kaikesta sielustanne.'),
(1674197,58,5,13,4,'Seuratkaa Herraa, teidän Jumalaanne, häntä peljätkää ja pitäkää hänen käskynsä, häntä kuulkaa, häntä palvelkaa ja hänessä kiinni riippukaa.'),
(1674198,58,5,13,5,'Mutta se profeetta tai unennäkijä surmattakoon, sillä hän on julistanut luopumusta Herrasta, teidän Jumalastanne, joka vei teidät pois Egyptin maasta ja vapahti sinut orjuuden pesästä, ja on tahtonut vietellä sinut siltä tieltä, jota Herra, sinun Jumalasi, käski sinun vaeltaa. Poista paha keskuudestasi.'),
(1674199,58,5,13,6,'Jos sinun veljesi, sinun äitisi poika, tai sinun poikasi tai tyttäresi tai vaimo, joka on sylissäsi, tai ystäväsi, joka on sinulle kuin oma sielusi, salaa houkuttelisi sinua ja sanoisi: ''Käykäämme palvelemaan muita jumalia'', joita et sinä tunne eivätkä sinun isäsi tunteneet -'),
(1674200,58,5,13,7,'niiden kansojen jumalia, jotka asuvat teidän ympärillänne, lähellä sinua tai kaukana sinusta, maan äärestä toiseen -'),
(1674201,58,5,13,8,'niin älä noudata hänen mieltään äläkä kuule häntä; älä sääli äläkä armahda häntä äläkä salaa hänen rikostansa,'),
(1674202,58,5,13,9,'vaan tapa hänet: oma kätesi kohotkoon ensimmäisenä häntä vastaan surmatakseen hänet, ja sitten koko kansan käsi.'),
(1674203,58,5,13,10,'Kivitä hänet kuoliaaksi, sillä hän koetti saada sinut luopumaan Herrasta, sinun Jumalastasi, joka vei sinut pois Egyptin maasta, orjuuden pesästä.'),
(1674204,58,5,13,11,'Ja koko Israel kuulkoon sen ja peljätköön, ettei kukaan enää tekisi senkaltaista pahaa sinun keskuudessasi.'),
(1674205,58,5,13,12,'Jos sinä kuulet sanottavan, että jossakin kaupungeistasi, jotka Herra, sinun Jumalasi, antaa sinun asuttaviksesi,'),
(1674206,58,5,13,13,'sinun keskuudestasi on lähtenyt kelvottomia miehiä, jotka viettelevät kaupunkinsa asukkaita sanoen: ''Käykäämme palvelemaan muita jumalia'', joita te ette tunne,'),
(1674207,58,5,13,14,'niin tutki, tiedustele ja kysele tarkoin; ja jos on totta ja varmaa, että sellaista kauhistusta on harjoitettu sinun keskuudessasi,'),
(1674208,58,5,13,15,'niin surmaa sen kaupungin asukkaat miekan terällä ja vihi tuhon omaksi se ja kaikki, mitä siinä on, ja tapa sen karjakin miekan terällä.'),
(1674209,58,5,13,16,'Ja kokoa kaikki siitä otettu saalis keskelle sen toria ja polta tulella sekä kaupunki että kaikki siitä otettu saalis kokonaisuhrina Herralle, sinun Jumalallesi; ja jääköön se rauniokummuksi iankaikkisesti, älköönkä sitä koskaan enää rakennettako.'),
(1674210,58,5,13,17,'Älköön siitä tuhon omaksi vihitystä mitään tarttuko sinun käsiisi, että Herra kääntyisi pois vihansa hehkusta, antaisi sinulle armon ja armahtaisi sinua ja sallisi sinun lisääntyä, niinkuin hän on vannonut sinun isillesi,'),
(1674211,58,5,13,18,'jos sinä vain kuulet Herran, sinun Jumalasi ääntä ja pidät kaikki hänen käskynsä, jotka minä tänä päivänä sinulle annan, ja teet sitä, mikä on oikein Herran, sinun Jumalasi, silmissä."'),
(1674212,58,5,14,1,'"Te olette Herran, teidän Jumalanne, lapsia. Älkää viileskelkö ihoanne älkääkä ajako paljaaksi päätänne otsapuolelta vainajan tähden,'),
(1674213,58,5,14,2,'sillä sinä olet Herralle, sinun Jumalallesi, pyhitetty kansa, ja Herra on valinnut sinut omaisuuskansakseen ennen kaikkia muita kansoja, mitä maan päällä on.'),
(1674214,58,5,14,3,'Älä syö mitään, mikä on kauhistus.'),
(1674215,58,5,14,4,'Nämä ovat ne nelijalkaiset eläimet, joita saatte syödä: raavas, lammas ja vuohi,'),
(1674216,58,5,14,5,'peura, gaselli, metsäkauris, vuorikauris, musta antilooppi, keihäsantilooppi ja betsoari-vuohi,'),
(1674217,58,5,14,6,'kaikki ne nelijalkaiset eläimet, joilla on kokonansa halkinaiset, kaksivarpaiset sorkat ja jotka märehtivät; niitä saatte syödä.'),
(1674218,58,5,14,7,'Näitä älkää kuitenkaan syökö niistä, jotka märehtivät, ja niistä, joilla on kokonansa halkinaiset sorkat: kamelia, jänistä ja tamaania, jotka kyllä märehtivät, mutta joilla ei ole sorkkia: ne olkoot teille saastaiset;'),
(1674219,58,5,14,8,'sikaa, jolla kyllä on sorkat, mutta joka ei märehdi: se olkoon teille saastainen. Näiden lihaa älkää syökö, ja niiden raatoihin älkää koskeko.'),
(1674220,58,5,14,9,'Näitä te saatte syödä kaikista vesieläimistä: kaikkia, joilla on evät ja suomukset, te saatte syödä.'),
(1674221,58,5,14,10,'Mutta kaikista niistä, joilla ei ole eviä eikä suomuksia, älkää syökö mitään: ne olkoot teille saastaiset.'),
(1674222,58,5,14,11,'Kaikkia puhtaita lintuja te saatte syödä.'),
(1674223,58,5,14,12,'Mutta nämä ovat linnuista ne, joita älkää syökö: kotka, partakorppikotka, harmaa korppikotka,'),
(1674224,58,5,14,13,'haarahaukka ja suohaukkalajit,'),
(1674225,58,5,14,14,'kaikki kaarnelajit,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674226,58,5,14,15,'kamelikurki, pääskynen, kalalokki, jalohaukkalajit,'),
(1674227,58,5,14,16,'huuhkaja, kissapöllö, sarvipöllö,'),
(1674228,58,5,14,17,'pelikaani, likakorppikotka, kalasääksi,'),
(1674229,58,5,14,18,'haikara, sirriäislajit, harjalintu ja yölepakko.'),
(1674230,58,5,14,19,'Myöskin kaikki siivelliset pikkueläimet olkoot teille saastaiset, niitä älköön syötäkö.'),
(1674231,58,5,14,20,'Kaikkia puhtaita siivellisiä te saatte syödä.'),
(1674232,58,5,14,21,'Älkää syökö mitään itsestään kuollutta. Muukalaiselle, joka sinun porteissasi on, sinä saat antaa sitä syötäväksi, tahi myy se vieraalle; sillä sinä olet Herralle, sinun Jumalallesi, pyhitetty kansa. Älä keitä vohlaa emänsä maidossa.'),
(1674233,58,5,14,22,'Kaikesta kylvösi sadosta, joka kasvaa pellollasi, anna joka vuosi kymmenykset,'),
(1674234,58,5,14,23,'ja syö ne Herran, sinun Jumalasi, edessä, siinä paikassa, jonka hän valitsee nimensä asuinsijaksi: kymmenykset jyvistäsi, viinistäsi ja öljystäsi, niin myös raavaittesi ja lampaittesi esikoiset, että oppisit pelkäämään Herraa, sinun Jumalaasi, kaikkena elinaikanasi.'),
(1674235,58,5,14,24,'Mutta jos tie on sinulle liian pitkä, niin ettet voi kantaa kannettavaasi, koska se paikka, jonka Herra, sinun Jumalasi, on valinnut asettaakseen siihen nimensä, on sinulle liian kaukana, - sillä Herra, sinun Jumalasi on sinua siunaava -'),
(1674236,58,5,14,25,'niin muuta se rahaksi, pane raha kääröön, ota käteesi ja mene siihen paikkaan, jonka Herra, sinun Jumalasi, valitsee,'),
(1674237,58,5,14,26,'ja osta sillä rahalla kaikkea, mitä haluat, joko raavaita tai lampaita, viiniä tai väkijuomaa, kaikkea, mitä mielesi tekee, ja syö siellä Herran, sinun Jumalasi, edessä ja iloitse, sinä ja perheesi.'),
(1674238,58,5,14,27,'Äläkä jätä osattomaksi leeviläistä, joka asuu sinun porttiesi sisäpuolella, sillä hänellä ei ole osuutta eikä perintöosaa sinun rinnallasi.'),
(1674239,58,5,14,28,'Joka kolmas vuosi tuo kaikki kymmenykset sinä vuonna saamastasi sadosta ja pane ne talteen porttiesi sisäpuolelle.'),
(1674240,58,5,14,29,'Ja sitten tulkoon leeviläinen, jolla ei ole osuutta eikä perintöosaa sinun rinnallasi, niin myös muukalainen, orpo ja leski, jotka asuvat sinun porttiesi sisäpuolella, ja he syökööt ja tulkoot ravituiksi, että Herra, sinun Jumalasi, siunaisi sinua kaikissa kättesi töissä, joita teet."'),
(1674241,58,5,15,1,'"Joka seitsemäs vuosi pane toimeen vapautus.'),
(1674242,58,5,15,2,'Ja näin on vapautuksesta määrätty: jokainen saamamies luopukoon siitä, minkä hän on lähimmäiselleen lainannut, älköönkä velkoko lähimmäistänsä ja veljeänsä, sillä silloin on Herran kunniaksi vapautus julistettu.'),
(1674243,58,5,15,3,'Vierasta saat velkoa, mutta luovu siitä, mitä sinulla on saamista veljeltäsi.'),
(1674244,58,5,15,4,'Tosin ei köyhää sinun keskuudessasi tulisi ollakaan, sillä Herra on runsaasti siunaava sinua siinä maassa, jonka Herra, sinun Jumalasi, antaa sinulle perintöosaksi ja jonka saat ottaa omaksesi,'),
(1674245,58,5,15,5,'jos vain kuulet Herran, sinun Jumalasi, ääntä ja tarkoin noudatat kaikkia näitä käskyjä, jotka minä tänä päivänä sinulle annan.'),
(1674246,58,5,15,6,'Sillä Herra, sinun Jumalasi, on siunaava sinua, niinkuin hän on sinulle puhunut; ja sinä lainaat monelle kansalle, mutta sinun ei tarvitse lainaa ottaa, ja sinä vallitset monia kansoja, mutta he eivät vallitse sinua.'),
(1674247,58,5,15,7,'Jos sinun keskuudessasi on joku köyhä, joku veljesi jossakin porttiesi sisäpuolella siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa, niin älä kovenna sydäntäsi äläkä sulje kättäsi köyhältä veljeltäsi,'),
(1674248,58,5,15,8,'vaan avaa auliisti kätesi hänelle ja lainaa mielelläsi, mitä hän puutteessansa tarvitsee.'),
(1674249,58,5,15,9,'Varo, ettei sydämessäsi synny tämä paha ajatus: ''Seitsemäs vuosi, vapautusvuosi, on lähellä'', ja ettet sen tähden katso karsaasti köyhää veljeäsi etkä anna hänelle mitään. Jos hän silloin huutaa sinun tähtesi Herran puoleen, niin sinä joudut syyhyn.'),
(1674250,58,5,15,10,'Anna mielelläsi hänelle, älköönkä sydämesi olko vastahakoinen antaessasi, sillä lahjasi tähden on Herra, sinun Jumalasi, siunaava sinua kaikissa töissäsi, kaikessa, mihin ryhdyt.'),
(1674251,58,5,15,11,'Koska köyhiä ei koskaan puutu maasta, sentähden käsken minä sinua näin: Avaa auliisti kätesi veljellesi, kurjalle ja köyhälle, joita sinun maassasi on.'),
(1674252,58,5,15,12,'Jos joku veljesi, hebrealainen mies tai nainen, on myynyt itsensä sinulle ja palvellut sinua kuusi vuotta, niin päästä hänet seitsemäntenä vuotena luotasi vapaaksi,'),
(1674253,58,5,15,13,'ja kun päästät hänet luotasi vapaaksi, niin älä lähetä häntä tyhjin käsin.'),
(1674254,58,5,15,14,'Vaan sälytä hänen selkäänsä runsaasti lahjoja laumastasi, puimatantereeltasi ja kuurnastasi; anna hänellekin siitä, millä Herra, sinun Jumalasi, on sinua siunannut.'),
(1674255,58,5,15,15,'Muista, että itse olit orjana Egyptin maassa ja että Herra, sinun Jumalasi, vapahti sinut. Sentähden minä tänä päivänä annan sinulle tämän käskyn.'),
(1674256,58,5,15,16,'Mutta jos hän sanoo sinulle: ''En tahdo lähteä luotasi'', koska hän rakastaa sinua ja sinun perhettäsi ja koska hänen on ollut sinun luonasi hyvä olla,'),
(1674257,58,5,15,17,'niin ota naskali ja pistä se hänen korvansa läpi oveen; olkoon hän sitten sinun orjasi ainiaan. Samoin tee myös orjattarellesi.'),
(1674258,58,5,15,18,'Älköön sinusta olko vaikeata päästää häntä luotasi vapaaksi: onhan hänestä kuutena vuotena ollut sinulle kahta vertaa suurempi hyöty kuin palkkalaisesta. Ja Herra, sinun Jumalasi, on siunaava sinua kaikessa, mitä teet.'),
(1674259,58,5,15,19,'Kaikki urospuoliset esikoiset, jotka syntyvät raavaskarjassasi ja pikkukarjassasi, pyhitä Herralle, Jumalallesi; raavaasi esikoisella älä työtä tee, älä myöskään keritse lampaasi esikoista.'),
(1674260,58,5,15,20,'Herran, sinun Jumalasi, edessä syö perheinesi se joka vuosi siinä paikassa, jonka Herra valitsee.'),
(1674261,58,5,15,21,'Jos siinä on joku vamma, jos se ontuu tai on sokea tai jos sillä on joku muu paha vamma, mikä tahansa, niin älä uhraa sitä Herralle, sinun Jumalallesi.'),
(1674262,58,5,15,22,'Syö se porttiesi sisäpuolella; niin hyvin saastainen kuin puhdas saakoon syödä sitä, niinkuin syödään gasellia tai peuraa.'),
(1674263,58,5,15,23,'Vain verta älä syö; vuodata se maahan niinkuin vesi."'),
(1674264,58,5,16,1,'"Ota vaari aabib-kuusta ja vietä pääsiäinen Herran, sinun Jumalasi, kunniaksi, sillä aabib-kuussa Herra, sinun Jumalasi, vei sinut pois Egyptistä, yöllä.'),
(1674265,58,5,16,2,'Ja teurasta Herralle, sinun Jumalallesi, pääsiäisuhri, lampaita ja raavaita, siinä paikassa, jonka Herra valitsee nimensä asuinsijaksi.'),
(1674266,58,5,16,3,'Älä syö sen ohella hapanta. Syö seitsemänä päivänä sen ohella happamatonta leipää, kurjuuden leipää - sillä kiiruusti sinä lähdit pois Egyptin maasta - että alati muistaisit sitä päivää, jona lähdit Egyptin maasta.'),
(1674267,58,5,16,4,'Seitsemään päivään älköön hapanta taikinaa olko koko sinun maassasi; ja siitä, mitä teurastat ensimmäisen päivän ehtoona, älköön mitään lihaa jääkö yön yli seuraavaan aamuun.'),
(1674268,58,5,16,5,'Sinä et saa teurastaa pääsiäisuhria niiden kaupunkiesi porttien sisäpuolella, jotka Herra, sinun Jumalasi, sinulle antaa,'),
(1674269,58,5,16,6,'vaan siinä paikassa, jonka Herra, sinun Jumalasi, valitsee nimensä asuinsijaksi, teurasta pääsiäisuhri, ehtoolla, auringon laskiessa, sinä määrähetkenä, jona Egyptistä lähdit.'),
(1674270,58,5,16,7,'Ja keitä ja syö se siinä paikassa, jonka Herra, sinun Jumalasi, valitsee; aamulla saat sitten lähteä paluumatkalle ja mennä kotiisi.'),
(1674271,58,5,16,8,'Kuutena päivänä syö happamatonta leipää, ja seitsemäntenä päivänä olkoon juhlakokous Herran, sinun Jumalasi, kunniaksi; älä silloin yhtäkään askaretta toimita.'),
(1674272,58,5,16,9,'Laske seitsemän viikkoa; siitä alkaen, kun sirppi ensi kerran olkeen pannaan, laske seitsemän viikkoa'),
(1674273,58,5,16,10,'ja vietä viikkojuhla Herran, sinun Jumalasi, kunniaksi kätesi vapaaehtoisin lahjoin, joita sinä annat sen mukaan, kuin Herra, sinun Jumalasi, on sinulle siunausta antanut.'),
(1674274,58,5,16,11,'Ja iloitse Herran, sinun Jumalasi, edessä, sinä ja sinun poikasi ja tyttäresi, palvelijasi ja palvelijattaresi, leeviläinen, joka asuu sinun porttiesi sisäpuolella, muukalainen, orpo ja leski, jotka sinun keskuudessasi ovat, siinä paikassa, jonka Herra, sinun Jumalasi, valitsee nimensä asuinsijaksi.'),
(1674275,58,5,16,12,'Ja muista, että itse olit orjana Egyptissä, ja noudata tarkoin näitä käskyjä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674276,58,5,16,13,'Lehtimajanjuhlaa vietä seitsemän päivää, korjatessasi satoa puimatantereeltasi ja kuurnastasi.'),
(1674277,58,5,16,14,'Ja iloitse tänä juhlanasi, sinä ja sinun poikasi ja tyttäresi, palvelijasi ja palvelijattaresi, leeviläinen, muukalainen, orpo ja leski, jotka asuvat sinun porttiesi sisäpuolella.'),
(1674278,58,5,16,15,'Seitsemän päivää juhli Herran, sinun Jumalasi, kunniaksi siinä paikassa, jonka Herra valitsee; sillä Herra, sinun Jumalasi, on siunaava sinua kaikessa, minkä satona saat, ja kaikissa kättesi töissä; sentähden ole iloinen.'),
(1674279,58,5,16,16,'Kolme kertaa vuodessa tulkoon kaikki sinun miesväkesi Herran, sinun Jumalasi, kasvojen eteen siihen paikkaan, jonka hän valitsee: happamattoman leivän juhlana, viikkojuhlana ja lehtimajanjuhlana. Mutta tyhjin käsin älköön tultako Herran kasvojen eteen;'),
(1674280,58,5,16,17,'kukin tuokoon lahjana sen, minkä voi, sen siunauksen mukaan, minkä Herra, sinun Jumalasi, on sinulle antanut.'),
(1674281,58,5,16,18,'Aseta tuomarit ja päällysmiehet eri sukukuntiasi varten kaikkien niiden kaupunkiesi portteihin, jotka Herra, sinun Jumalasi, sinulle antaa; he tuomitkoot kansaa oikein.'),
(1674282,58,5,16,19,'Älä vääristä oikeutta, älä katso henkilöön äläkä ota lahjusta, sillä lahjus sokaisee viisaiden silmät ja vääristää syyttömien asiat.'),
(1674283,58,5,16,20,'Vanhurskautta, ainoastaan vanhurskautta harrasta, että eläisit ja ottaisit omaksesi sen maan, jonka Herra, sinun Jumalasi, sinulle antaa.'),
(1674284,58,5,16,21,'Älä pystytä itsellesi asera-karsikoita, älä mitään puuta, Herran, sinun Jumalasi, alttarin viereen, jonka itsellesi teet;'),
(1674285,58,5,16,22,'älä myöskään pystytä itsellesi patsasta, sillä niitä Herra, sinun Jumalasi, vihaa."'),
(1674286,58,5,17,1,'"Älä uhraa Herralle, sinun Jumalallesi, raavasta tai lammasta, jossa on joku vamma, mikä paha vika tahansa, sillä se on kauhistus Herralle, sinun Jumalallesi.'),
(1674287,58,5,17,2,'Jos sinun keskuudessasi, niiden kaupunkiesi porttien sisäpuolella, jotka Herra, sinun Jumalasi, sinulle antaa, on mies tai nainen, joka tekee sitä, mikä on pahaa Herran, sinun Jumalasi, silmissä, rikkoo hänen liittonsa,'),
(1674288,58,5,17,3,'ja menee ja palvelee muita jumalia ja kumartaa niitä: aurinkoa, kuuta tai kaikkea taivaan joukkoa, minkä minä olen kieltänyt,'),
(1674289,58,5,17,4,'ja siitä ilmoitetaan sinulle, niin että saat sen kuulla, niin tutki asia tarkoin, ja jos on totta ja varmaa, että sellaista kauhistusta on harjoitettu Israelissa,'),
(1674290,58,5,17,5,'niin vie se mies tai se nainen, joka on sellaisen pahan tehnyt, porttiesi edustalle - se mies tai se nainen - ja kivitä heidät kuoliaaksi.'),
(1674291,58,5,17,6,'Kahden tai kolmen todistajan todistuksen nojalla kuolemaan tuomittu surmattakoon; yhden ainoan todistajan todistuksen nojalla älköön häntä surmattako.'),
(1674292,58,5,17,7,'Todistajien käsi kohotkoon ensimmäisenä häntä vastaan surmatakseen hänet, ja sitten koko kansan käsi. Poista paha keskuudestasi.'),
(1674293,58,5,17,8,'Jos joku murhaa tai omaisuusriitaa tai pahoinpitelyä koskeva asia tai mikä muu asia hyvänsä, josta sinun porteissasi riidellään, näyttää sinusta liian vaikealta ratkaista, niin nouse ja lähde siihen paikkaan, jonka Herra, sinun Jumalasi, valitsee,'),
(1674294,58,5,17,9,'ja mene leeviläisten pappien luo ja sen luo, joka siihen aikaan on tuomarina; kysy heiltä, ja he ilmoittavat sinulle tuomion.'),
(1674295,58,5,17,10,'Ja tee sen sanan mukaan, minkä he sinulle ilmoittavat siinä paikassa, jonka Herra valitsee; ja noudata tarkoin kaikkea, mitä he sinulle opettavat.'),
(1674296,58,5,17,11,'Tee sen lain mukaan, minkä he sinulle opettavat, ja sen tuomion mukaan, minkä he sinulle julistavat, poikkeamatta oikealle tai vasemmalle siitä, mitä he sinulle ilmoittavat.'),
(1674297,58,5,17,12,'Mutta jos joku menettelisi niin julkeasti, ettei kuulisi pappia, joka siellä seisoo palvelemassa Herraa, sinun Jumalaasi, tai tuomaria, niin se mies kuolkoon.'),
(1674298,58,5,17,13,'Poista paha Israelista. Ja kaikki kansa kuulkoon sen ja peljätköön, niin ettei kukaan enää olisi niin julkea.'),
(1674299,58,5,17,14,'Kun tulet siihen maahan, jonka Herra, sinun Jumalasi, sinulle antaa, ja otat sen omaksesi ja asetut siihen ja ajattelet: ''Minä asetan itselleni kuninkaan, niinkuin on kaikilla kansoilla, jotka minun ympärilläni asuvat'','),
(1674300,58,5,17,15,'niin aseta itsellesi kuninkaaksi se, jonka Herra, sinun Jumalasi, valitsee. Aseta joku veljistäsi kuninkaaksesi; älä korota hallitsijaksesi muukalaista miestä, joka ei ole sinun veljesi.'),
(1674301,58,5,17,16,'Mutta älköön hän hankkiko itselleen paljon hevosia älköönkä viekö kansaa takaisin Egyptiin hankkiakseen paljon hevosia, sillä Herra on teille sanonut: ''Älkää enää palatko tätä tietä''.'),
(1674302,58,5,17,17,'Älköönkä hän ottako itsellensä monta vaimoa, ettei hänen sydämensä luopuisi pois; älköönkä hän kootko itsellensä ylen paljon hopeata ja kultaa.'),
(1674303,58,5,17,18,'Ja kun hän on noussut valtaistuimellensa, kirjoituttakoon hän itsellensä kirjaan jäljennöksen tästä laista, joka on leeviläisten pappien huostassa.'),
(1674304,58,5,17,19,'Ja hän pitäköön sen luonaan ja lukekoon sitä, niin kauan kuin elää, oppiaksensa pelkäämään Herraa, Jumalaansa, ja noudattamaan tarkoin kaikkia tämän lain sanoja ja näitä käskyjä,'),
(1674305,58,5,17,20,'ettei hänen sydämensä ylpistyisi hänen veljiänsä kohtaan ja ettei hän poikkeaisi käskyistä, ei oikealle eikä vasemmalle - niin että hän ja hänen poikansa kauan hallitsisivat Israelin keskuudessa."'),
(1674306,58,5,18,1,'"Leeviläisillä papeilla, Leevin koko sukukunnalla, älköön olko osuutta tai perintöosaa muun Israelin rinnalla; Herran uhreista ja siitä, mikä hänen osakseen tulee, he saakoot elatuksensa.'),
(1674307,58,5,18,2,'Heillä ei ole oleva perintöosaa veljiensä keskuudessa; Herra itse on heidän perintöosansa, niinkuin hän on heille puhunut.'),
(1674308,58,5,18,3,'Ja tämä olkoon papeilla oikeus saada kansalta, niiltä, jotka uhraavat teurasuhrin, raavaan tai lampaan: papille annettakoon lapa, leukaluut ja maha.'),
(1674309,58,5,18,4,'Uutiset jyvistäsi, viinistäsi ja öljystäsi ja lammastesi ensimmäiset kerityt villat anna hänelle.'),
(1674310,58,5,18,5,'Sillä hänet Herra, sinun Jumalasi, on valinnut kaikista sukukunnistasi, että hän ja hänen poikansa alati seisoisivat ja palvelisivat Herran nimessä.'),
(1674311,58,5,18,6,'Ja jos leeviläinen tahtoo tulla jostakin sinun kaupungistasi, jonka porttien sisäpuolella hän muukalaisena asuu, missä hyvänsä Israelissa, niin tulkoon vapaasti, niinkuin hänen mielensä tekee, siihen paikkaan, jonka Herra valitsee,'),
(1674312,58,5,18,7,'ja saakoon palvella Herran, Jumalansa, nimessä, niinkuin kaikki muutkin hänen veljensä, leeviläiset, jotka seisovat siellä Herran edessä.'),
(1674313,58,5,18,8,'He kaikki saakoot elatukseksensa yhtäläisen osuuden, lukuunottamatta sitä, mitä joku on saanut myymällä perheomaisuuttaan.'),
(1674314,58,5,18,9,'Kun tulet siihen maahan, jonka Herra, sinun Jumalasi, sinulle antaa, niin älä opettele jäljittelemään niiden kansojen kauhistavia tekoja.'),
(1674315,58,5,18,10,'Älköön keskuudessasi olko ketään, joka panee poikansa tai tyttärensä kulkemaan tulen läpi, tahi joka tekee taikoja, ennustelee merkeistä, harjoittaa noituutta tai velhoutta,'),
(1674316,58,5,18,11,'joka lukee loitsuja, kysyy vainaja- tai tietäjähengiltä tahi kääntyy vainajien puoleen.'),
(1674317,58,5,18,12,'Sillä jokainen, joka senkaltaista tekee, on kauhistus Herralle, ja sellaisten kauhistusten tähden Herra, sinun Jumalasi, karkoittaa heidät sinun tieltäsi.'),
(1674318,58,5,18,13,'Ole siis nuhteeton Herran, sinun Jumalasi, edessä.'),
(1674319,58,5,18,14,'Sillä nämä kansat, jotka sinä nyt karkoitat, kuuntelevat kyllä merkeistäennustajia ja taikureita, mutta sinulle ei Herra, sinun Jumalasi, sitä salli.'),
(1674320,58,5,18,15,'Sinun keskuudestasi, veljiesi joukosta, Herra, sinun Jumalasi, herättää sinulle profeetan, minun kaltaiseni; häntä kuulkaa.'),
(1674321,58,5,18,16,'On tapahtuva aivan niin, kuin sinä Herralta, sinun Jumalaltasi, anoit Hoorebilla, silloin kun seurakunta oli koolla ja sanoit: ''Älköön minun enää suotako kuulla Herran, minun Jumalani, ääntä älköönkä nähdä tätä suurta tulta, etten kuolisi''.'),
(1674322,58,5,18,17,'Ja Herra sanoi minulle: ''Mitä he ovat puhuneet, on oikein puhuttu.'),
(1674323,58,5,18,18,'Profeetan minä olen herättävä heille heidän veljiensä keskuudesta, sinun kaltaisesi, ja minä panen sanani hänen suuhunsa, ja hän puhuu heille kaikki, mitä minä käsken hänen puhua.'),
(1674324,58,5,18,19,'Ja joka ei kuule minun sanojani, joita hän minun nimessäni puhuu, hänet minä itse vaadin tilille.'),
(1674325,58,5,18,20,'Mutta profeetta, joka julkeaa puhua minun nimessäni jotakin, jota minä en ole käskenyt hänen puhua, tahi puhuu muiden jumalien nimessä, sellainen profeetta kuolkoon.''');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674326,58,5,18,21,'Ja jos sinä ajattelet sydämessäsi: ''Mistä me tiedämme, mikä sana ei ole Herran puhetta?'' niin huomaa:'),
(1674327,58,5,18,22,'kun profeetta puhuu Herran nimessä, ja kun se, mitä hän on puhunut, ei tapahdu eikä käy toteen, niin sitä sanaa Herra ei ole puhunut; julkeuttaan se profeetta on niin puhunut; älä pelkää häntä."'),
(1674328,58,5,19,1,'"Kun Herra, sinun Jumalasi, on hävittänyt ne kansat, joiden maan Herra, sinun Jumalasi, antaa sinulle, ja kun sinä olet karkoittanut heidät ja asettunut heidän kaupunkeihinsa ja heidän taloihinsa,'),
(1674329,58,5,19,2,'niin erota itsellesi kolme kaupunkia siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa, että ottaisit sen omaksesi.'),
(1674330,58,5,19,3,'Mittaa matkat ja jaa kolmeen osaan sen maan alue, jonka Herra, sinun Jumalasi, antaa sinulle perinnöksi, että niihin voisi paeta jokainen tappaja.'),
(1674331,58,5,19,4,'Ja näin on määrätty tappajasta, joka pakenee niihin saadakseen elää: kun joku tappaa lähimmäisensä tahtomattaan ja häntä ennestään vihaamatta -'),
(1674332,58,5,19,5,'niinkuin jos joku menee lähimmäisensä kanssa metsään puita hakkaamaan ja hänen kätensä heiluttaa kirvestä kaataakseen puun ja rauta lentää varresta ja sattuu toiseen, niin että tämä kuolee - niin paetkoon sellainen johonkin näistä kaupungeista saadakseen elää,'),
(1674333,58,5,19,6,'ettei verenkostaja, sydämensä kiihkossa tappajaa takaa ajaessaan, saavuttaisi häntä, jos tie on pitkä, ja surmaisi häntä, vaikka hän ei ole ansainnut kuolemaa, koska ei ennestään toista vihannut.'),
(1674334,58,5,19,7,'Sentähden minä käsken sinua sanoen: ''Erota itsellesi kolme kaupunkia''.'),
(1674335,58,5,19,8,'Ja jos Herra, sinun Jumalasi, laajentaa sinun aluettasi, niinkuin hän on vannonut sinun isillesi, ja antaa sinulle kaiken sen maan, jonka hän on sinun isillesi sanonut antavansa,'),
(1674336,58,5,19,9,'jos sinä noudatat tarkoin kaikkia näitä käskyjä, jotka minä tänä päivänä sinulle annan, niin että alati rakastat Herraa, sinun Jumalaasi, ja vaellat hänen teitänsä, lisää silloin vielä kolme kaupunkia näihin kolmeen,'),
(1674337,58,5,19,10,'ettei viatonta verta vuodatettaisi sinun maassasi, jonka Herra, sinun Jumalasi, antaa sinulle perintöosaksi, ja ettet joutuisi verivelan alaiseksi.'),
(1674338,58,5,19,11,'Mutta jos joku vihaa lähimmäistään ja asettuu häntä väijymään ja karkaa hänen kimppuunsa ja lyö hänet kuoliaaksi ja sitten pakenee johonkin näistä kaupungeista,'),
(1674339,58,5,19,12,'niin lähettäkööt hänen kaupunkinsa vanhimmat noutamaan hänet sieltä ja antakoot hänet verenkostajan käsiin, ja hän kuolkoon.'),
(1674340,58,5,19,13,'Älä sääli häntä, vaan poista viattoman veren velka Israelista, että menestyisit.'),
(1674341,58,5,19,14,'Älä siirrä lähimmäisesi rajaa, jonka entiset polvet ovat määränneet sinun perintöosallesi siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa, että ottaisit sen omaksesi.'),
(1674342,58,5,19,15,'Yksi ainoa todistaja älköön olko pätevä ketään vastaan, olkoonpa mikä pahateko tai rikkomus, mikä synti tahansa, jonka joku tekee. Kahden tai kolmen todistajan sanalla on asia vahva.'),
(1674343,58,5,19,16,'Jos väärä todistaja nousee jotakuta vastaan ja syyttää häntä jostakin rikkomuksesta,'),
(1674344,58,5,19,17,'niin astukoot molemmat riitapuolet Herran eteen, pappien eteen ja niiden eteen, jotka siihen aikaan ovat tuomareina.'),
(1674345,58,5,19,18,'Ja tuomarit tutkikoot tarkoin asian, ja jos todistaja on väärä todistaja, joka on tehnyt väärän syytöksen veljeänsä vastaan,'),
(1674346,58,5,19,19,'niin tehkää hänelle samoin, kuin hän aikoi tehdä veljellensä. Poista paha keskuudestasi.'),
(1674347,58,5,19,20,'Ja muut kuulkoot sen ja peljätkööt, niin ettei kukaan enää tekisi sellaista pahaa sinun keskuudessasi.'),
(1674348,58,5,19,21,'Älä sääli häntä: henki hengestä, silmä silmästä, hammas hampaasta, käsi kädestä, jalka jalasta."'),
(1674349,58,5,20,1,'"Jos lähdet sotaan vihollistasi vastaan ja näet hevosia ja sotavaunuja ja sotajoukon, joka on sinua suurempi, niin älä pelkää heitä, sillä Herra, sinun Jumalasi, on sinun kanssasi, hän, joka johdatti sinut Egyptin maasta.'),
(1674350,58,5,20,2,'Kun olette ryhtymässä taisteluun, astukoon pappi esiin puhumaan kansalle'),
(1674351,58,5,20,3,'ja sanokoon heille: ''Kuule, Israel! Te ryhdytte nyt taisteluun vihollisianne vastaan. Älkää arkailko, älkää peljätkö älkääkä hätääntykö, älkää säikähtykö heitä;'),
(1674352,58,5,20,4,'sillä Herra, teidän Jumalanne, käy teidän kanssanne, sotii teidän puolestanne vihollisianne vastaan ja antaa teille voiton.'''),
(1674353,58,5,20,5,'Ja päällysmiehet puhukoot kansalle ja sanokoot: ''Joka on rakentanut uuden talon, mutta ei vielä ole sitä vihkinyt, menköön ja palatkoon kotiinsa, ettei hän kaatuisi taistelussa ja joku toinen vihkisi sitä.'),
(1674354,58,5,20,6,'Joka on istuttanut viinitarhan, mutta ei vielä ole korjannut sen ensi hedelmää, menköön ja palatkoon kotiinsa, ettei hän kaatuisi taistelussa ja joku toinen korjaisi sen ensi hedelmää.'),
(1674355,58,5,20,7,'Joka on kihlannut naisen, mutta ei vielä ole ottanut häntä vaimoksensa, menköön ja palatkoon kotiinsa, ettei hän kaatuisi taistelussa ja joku toinen ottaisi hänen morsiantaan vaimoksensa.'''),
(1674356,58,5,20,8,'Vielä puhukoot päällysmiehet kansalle ja sanokoot: ''Joka pelkää ja arkailee, menköön ja palatkoon kotiinsa, etteivät hänen veljensäkin menettäisi rohkeuttaan niinkuin hän''.'),
(1674357,58,5,20,9,'Ja kun päällysmiehet ovat tämän kaiken kansalle puhuneet, asettakoot he osastopäälliköt väen johtoon.'),
(1674358,58,5,20,10,'Kun lähestyt jotakin kaupunkia sotiaksesi sitä vastaan, tarjoa sille ensin rauhaa.'),
(1674359,58,5,20,11,'Ja jos se suostuu tarjoamaasi rauhaan ja avaa sinulle porttinsa, suorittakoon kaikki siellä oleva kansa sinulle työveroa ja palvelkoon sinua.'),
(1674360,58,5,20,12,'Mutta jos se ei tee rauhaa sinun kanssasi, vaan valmistautuu taistelemaan sinua vastaan, niin piiritä sitä.'),
(1674361,58,5,20,13,'Ja jos Herra, sinun Jumalasi, antaa sen sinun käsiisi, niin surmaa kaikki sen miesväki miekan terällä.'),
(1674362,58,5,20,14,'Mutta naiset, lapset ja karja ja kaikki, mitä kaupungissa on, kaikki, mitä sieltä on saatavana saalista, ryöstä itsellesi, ja nauti vihollisiltasi saatu saalis, minkä Herra, sinun Jumalasi, sinulle antaa.'),
(1674363,58,5,20,15,'Tee näin kaikille niille kaupungeille, jotka ovat sinusta hyvin kaukana, jotka eivät ole näiden kansojen kaupunkeja.'),
(1674364,58,5,20,16,'Mutta näiden kansojen kaupungeissa, jotka Herra, sinun Jumalasi, antaa sinulle perintöosaksi, älä jätä ainoatakaan henkeä eloon,'),
(1674365,58,5,20,17,'vaan vihi ne tuhon omiksi: heettiläiset ja amorilaiset, kanaanilaiset ja perissiläiset, hivviläiset ja jebusilaiset, niinkuin Herra, sinun Jumalasi, on sinua käskenyt,'),
(1674366,58,5,20,18,'etteivät he opettaisi teitä tekemään kaikkia niitä kauhistavia tekoja, joita he ovat tehneet palvellessaan jumaliansa, ja ettette te rikkoisi Herraa, teidän Jumalaanne, vastaan.'),
(1674367,58,5,20,19,'Jos joudut kauan piirittämään kaupunkia ja sotimaan sitä vastaan valloittaaksesi sen, niin älä hävitä sen puita äläkä heiluta kirvestäsi niitä vastaan. Niiden hedelmiä saat nauttia, mutta älä hakkaa niitä maahan, sillä eivät kedon puut ole ihmisiä joutuakseen sinun piiritettäviksesi.'),
(1674368,58,5,20,20,'Ainoastaan ne puut, joista tiedät, että niissä ei ole mitään syötävää, saat hävittää ja hakata maahan, rakentaaksesi niistä varustuksia sinun kanssasi sotivaa kaupunkia vastaan, kunnes se kukistuu."'),
(1674369,58,5,21,1,'"Jos siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa, että ottaisit sen omaksesi, löydetään murhattu virumassa kedolla, eikä tiedetä, kuka hänet tappoi,'),
(1674370,58,5,21,2,'niin lähtekööt sinun vanhimpasi ja tuomarisi mittaamaan välimatkan niihin kaupunkeihin, jotka ovat murhatun ympärillä.'),
(1674371,58,5,21,3,'Sen kaupungin vanhimmat, joka on murhattua lähinnä, ottakoot hiehon, jolla ei ole työtä tehty ja joka ei ole ollut vetojuhtana ikeen alla,'),
(1674372,58,5,21,4,'ja sen kaupungin vanhimmat viekööt hiehon alas ehtymättömän puron notkoon, jossa ei ole kynnetty eikä kylvetty; ja he taittakoot hieholta niskan siinä notkossa.'),
(1674373,58,5,21,5,'Ja papit, leeviläiset, astukoot esiin, sillä heidät on Herra, sinun Jumalasi, valinnut palvelemaan häntä ja Herran nimeen siunaamaan, ja heidän sanansa mukaan ratkaistakoon jokainen riita ja pahoinpitely.'),
(1674374,58,5,21,6,'Ja kaikki sen kaupungin vanhimmat, he kun asuvat murhattua lähinnä, peskööt kätensä pitäen niitä hiehon päällä, jolta niska taitettiin siinä notkossa;'),
(1674375,58,5,21,7,'ja he lausukoot sanoen: ''Meidän kätemme eivät ole tätä verta vuodattaneet, eivätkä silmämme tapausta nähneet.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674376,58,5,21,8,'Anna anteeksi, Herra, kansallesi Israelille, jonka vapahdit, äläkä lue viatonta verta kansallesi Israelille.'' Ja niin se verivelka annetaan heille anteeksi.'),
(1674377,58,5,21,9,'Poista keskuudestasi viattoman veren velka, sillä sinun on tehtävä se, mikä on oikeata Herran silmissä.'),
(1674378,58,5,21,10,'Kun lähdet sotaan vihollisiasi vastaan ja Herra, sinun Jumalasi, antaa heidät sinun käsiisi ja sinä otat heistä vankeja'),
(1674379,58,5,21,11,'ja vankien joukossa näet kaunisvartaloisen naisen ja mielistyt häneen ja tahdot ottaa hänet vaimoksesi,'),
(1674380,58,5,21,12,'niin vie hänet kotiisi, ja hän ajattakoon hiuksensa ja leikatkoon kyntensä.'),
(1674381,58,5,21,13,'Ja hän riisukoon vaatteensa, joissa hänet vangittiin, ja asukoon sinun kodissasi ja saakoon itkeä kuukauden päivät isäänsä ja äitiänsä; sitten saat yhtyä häneen ja naida hänet, niin että hän tulee vaimoksesi.'),
(1674382,58,5,21,14,'Mutta jos hän ei sitten enää sinua miellytä, niin päästä hänet menemään vapaana äläkä myy häntä rahasta. Älä kohtele häntä tylysti, koska olet häntä alentavasti kohdellut.'),
(1674383,58,5,21,15,'Jos jollakin miehellä on kaksi vaimoa, toinen, jota hän rakastaa, ja toinen, jota hän hylkii, ja he synnyttävät hänelle lapsia, sekä se, jota hän rakastaa, että se, jota hän hylkii, ja esikoinen on hyljityn poika,'),
(1674384,58,5,21,16,'älköön hän, kun jakaa pojilleen omaisuutensa perinnöksi, antako esikoisoikeutta rakastetun pojalle syrjäyttämällä hyljityn vaimon pojan, joka on esikoinen;'),
(1674385,58,5,21,17,'vaan hän tunnustakoon esikoisekseen hyljityn vaimon pojan ja antakoon hänelle kaksinkertaisen osan kaikesta, minkä omistaa. Sillä hän on hänen miehuutensa parhain; hänen on esikoisoikeus.'),
(1674386,58,5,21,18,'Jos jollakin on uppiniskainen ja kovakorvainen poika, joka ei ota kuullakseen, mitä hänen isänsä ja äitinsä sanovat, eikä tottele heitä, vaikka he kurittavat häntä,'),
(1674387,58,5,21,19,'niin hänen isänsä ja äitinsä ottakoot hänet ja viekööt kaupunkinsa vanhinten eteen, asuinpaikkansa porttiin,'),
(1674388,58,5,21,20,'ja sanokoot kaupunkinsa vanhimmille: ''Tämä meidän poikamme on uppiniskainen ja kovakorvainen, hän ei ota kuullakseen, mitä me sanomme, vaan on irstailija ja juomari''.'),
(1674389,58,5,21,21,'Silloin kaikki hänen kaupunkinsa miehet kivittäkööt hänet kuoliaaksi. Poista paha keskuudestasi, ja koko Israel kuulkoon sen ja peljätköön.'),
(1674390,58,5,21,22,'Jos joku on tehnyt itsensä syypääksi rikkomukseen, josta rangaistaan kuolemalla, ja hänet surmataan, ja sinä ripustat hänet hirteen,'),
(1674391,58,5,21,23,'niin älköön hänen ruumiinsa jääkö hirteen yöksi, vaan hautaa hänet samana päivänä, sillä Jumalan kiroama on se, joka on hirteen ripustettu; älä saastuta sitä maata, jonka Herra, sinun Jumalasi, antaa sinulle perintöosaksi."'),
(1674392,58,5,22,1,'"Jos näet veljesi härän tai lampaan eksyneen, älä jätä sitä siihen; vie se takaisin veljellesi.'),
(1674393,58,5,22,2,'Jos veljesi ei asu sinua lähellä tai jos et tiedä, kuka hän on, niin korjaa eksynyt taloosi, ja olkoon se sinun huostassasi, kunnes veljesi tiedustelee sitä; anna se silloin hänelle takaisin.'),
(1674394,58,5,22,3,'Tee samoin, jos veljeltäsi on kadonnut aasi, samoin, jos vaate, samoin, jos mitä muuta hyvänsä, jonka löydät; älä jätä sitä siihen.'),
(1674395,58,5,22,4,'Jos näet veljesi aasin tai härän kaatuneen tielle, älä jätä sitä siihen; auta häntä nostamaan se jaloilleen.'),
(1674396,58,5,22,5,'Nainen älköön käyttäkö miehen tamineita, älköönkä mies pukeutuko naisen vaatteisiin; sillä jokainen, joka niin tekee, on kauhistus Herralle, sinun Jumalallesi.'),
(1674397,58,5,22,6,'Jos kulkiessasi tapaat puusta tai maasta linnun pesän, jossa on pojat tai munat ja emo makaamassa poikien tai munien päällä, niin älä ota emoa poikineen,'),
(1674398,58,5,22,7,'vaan päästä emo lentämään ja ota vain pojat, että menestyisit ja kauan eläisit.'),
(1674399,58,5,22,8,'Kun rakennat uuden talon, tee kaide kattosi ympärille, ettet saattaisi verenvikaa taloosi, jos joku sieltä putoaisi.'),
(1674400,58,5,22,9,'Älä kylvä viinitarhaasi kahdenlaista siementä, muutoin kaikki, mitä siinä on, sekä siemen, jonka kylvit, että viinitarhan sato, on oleva pyhäkölle pyhitetty.'),
(1674401,58,5,22,10,'Älä kynnä yhtaikaa härällä ja aasilla.'),
(1674402,58,5,22,11,'Älä pue yllesi vaatetta, joka on kudottu kahdenlaisista langoista, villaisista ja pellavaisista sekaisin.'),
(1674403,58,5,22,12,'Tee itsellesi tupsut viittasi neljään kulmaan, johon verhoudut.'),
(1674404,58,5,22,13,'Jos joku on ottanut vaimon ja yhtynyt häneen, mutta sitten hylkii häntä'),
(1674405,58,5,22,14,'ja esittää häntä vastaan perättömiä syytöksiä ja saattaa hänet pahaan maineeseen ja sanoo: ''Minä otin tämän naisen vaimokseni, mutta kun ryhdyin häneen, en tavannut hänessä neitsyyden merkkiä'','),
(1674406,58,5,22,15,'niin tytön isä ja äiti ottakoot ja tuokoot tytön neitsyyden merkin kaupungin vanhimmille, porttiin.'),
(1674407,58,5,22,16,'Ja tytön isä sanokoon vanhimmille: ''Minä annoin tyttäreni vaimoksi tälle miehelle, mutta hän hylkii häntä.'),
(1674408,58,5,22,17,'Ja katso, hän esittää häntä vastaan perättömiä syytöksiä sanoen: Minä en tavannut tyttäressäsi neitsyyden merkkiä. Mutta tässä on tyttäreni neitsyyden merkki.'' Ja he levittäkööt vaatteen kaupungin vanhinten eteen.'),
(1674409,58,5,22,18,'Silloin kaupungin vanhimmat ottakoot sen miehen ja kurittakoot häntä. Ja he määrätkööt hänelle sakkoa sata hopeasekeliä annettavaksi tytön isälle, sentähden että hän saattoi Israelin neitsyen pahaan maineeseen.'),
(1674410,58,5,22,19,'Ja hän olkoon hänen vaimonsa; hän älköön hyljätkö häntä koko elinaikanansa.'),
(1674411,58,5,22,20,'Mutta jos syytös on tosi, jos tytössä ei tavattu neitsyyden merkkiä,'),
(1674412,58,5,22,21,'silloin vietäköön tyttö isänsä talon ovelle, ja kaupungin miehet kivittäkööt hänet kuoliaaksi, koska hän teki häpeällisen teon Israelissa, harjoittaen haureutta isänsä kodissa. Poista paha keskuudestasi.'),
(1674413,58,5,22,22,'Jos joku tavataan makaamasta naisen kanssa, joka on toisen miehen aviovaimo, niin kuolkoot molemmat, sekä mies, joka makasi vaimon kanssa, että vaimo. Poista paha Israelista.'),
(1674414,58,5,22,23,'Jos joku neitsyt on kihloissa miehen kanssa ja toinen tapaa hänet kaupungissa ja makaa hänen kanssaan,'),
(1674415,58,5,22,24,'niin viekää molemmat sen kaupungin portille ja kivittäkää heidät kuoliaaksi, tyttö siksi, että hän ei huutanut apua kaupungissa, ja mies siksi, että hän teki väkivaltaa lähimmäisensä morsiamelle. Poista paha keskuudestasi.'),
(1674416,58,5,22,25,'Mutta jos mies tapaa kihlatun tytön kedolla, käy häneen käsiksi ja makaa hänen kanssaan, niin mies, joka makasi hänen kanssaan, kuolkoon yksin.'),
(1674417,58,5,22,26,'Mutta tytölle älä tee mitään, sillä tyttö ei ole tehnyt kuoleman rikosta; tässä on samanlainen tapaus, kuin jos mies karkaa toisen kimppuun ja tappaa hänet.'),
(1674418,58,5,22,27,'Sillä hän tapasi hänet kedolla; kihlattu tyttö huusi, mutta hänellä ei ollut auttajaa.'),
(1674419,58,5,22,28,'Jos joku tapaa neitsyen, joka ei ole kihlattu, ja ottaa hänet kiinni ja makaa hänen kanssaan ja heidät siitä tavataan,'),
(1674420,58,5,22,29,'niin mies, joka makasi hänen kanssaan, antakoon tytön isälle viisikymmentä hopeasekeliä, ja tyttö tulkoon hänen vaimokseen, koska hän raiskasi hänet; hän älköön hyljätkö häntä koko elinaikanansa.'),
(1674421,58,5,22,30,'Älköön kukaan ottako vaimoksi äitipuoltaan älköönkä nostako isänsä peitettä."'),
(1674422,58,5,23,1,'"Älköön kukaan, joka on kuohittu musertamalla tai leikkaamalla, pääskö Herran seurakuntaan.'),
(1674423,58,5,23,2,'Älköön kukaan sekasikiö pääskö Herran seurakuntaan; älköön sellaisen jälkeläinen edes kymmenennessä polvessa pääskö Herran seurakuntaan.'),
(1674424,58,5,23,3,'Älköön ammonilainen ja mooabilainen pääskö Herran seurakuntaan; älkööt heidän jälkeläisensä edes kymmenennessä polvessa koskaan pääskö Herran seurakuntaan,'),
(1674425,58,5,23,4,'sentähden että he eivät tulleet leipää ja vettä tuoden teitä vastaan matkalla, kun olitte lähteneet Egyptistä, ja sentähden että hän palkkasi sinua vastaan Bileamin, Beorin pojan, Mesopotamian Petorista, sinua kiroamaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674426,58,5,23,5,'Mutta Herra, sinun Jumalasi, ei tahtonut kuulla Bileamia, vaan Herra, sinun Jumalasi, muutti kirouksen sinulle siunaukseksi, sillä Herra, sinun Jumalasi, rakasti sinua.'),
(1674427,58,5,23,6,'Älä koskaan, älä koko elinaikanasi, harrasta heidän menestystään ja onneaan.'),
(1674428,58,5,23,7,'Edomilaista älä inhoa, sillä hän on sinun veljesi. Älä inhoa egyptiläistä, sillä sinä olet asunut muukalaisena hänen maassaan.'),
(1674429,58,5,23,8,'Lapset, jotka heille syntyvät kolmannessa polvessa, pääskööt Herran seurakuntaan.'),
(1674430,58,5,23,9,'Kun lähdettyäsi vihollisiasi vastaan asetut leiriin, karta kaikkea siivotonta.'),
(1674431,58,5,23,10,'Jos sinun keskuudessasi on joku, joka ei ole puhdas sen johdosta, mitä hänelle yöllä on tapahtunut, menköön hän leirin ulkopuolelle; hän älköön tulko leiriin.'),
(1674432,58,5,23,11,'Illan suussa hän peseytyköön vedessä, ja auringon laskettua hän tulkoon leiriin.'),
(1674433,58,5,23,12,'Leirin ulkopuolella olkoon sinulla syrjäinen paikka, johon sinun on mentävä tarpeellesi.'),
(1674434,58,5,23,13,'Ja sinulla olkoon aseittesi lisänä pieni lapio, ja kun siellä ulkona istut tarpeellesi, kaiva sillä kuoppa ja peitä sitten ulostuksesi.'),
(1674435,58,5,23,14,'Sillä Herra, sinun Jumalasi, vaeltaa leirissä auttaaksensa sinua ja antaakseen vihollisesi sinulle alttiiksi; sentähden olkoon sinun leirisi pyhä, ettei hän näkisi sinun keskuudessasi mitään häpeällistä ja kääntyisi pois sinusta.'),
(1674436,58,5,23,15,'Älä luovuta orjaa, joka on paennut isäntänsä luota sinun luoksesi, hänen isännällensä.'),
(1674437,58,5,23,16,'Hän asukoon sinun luonasi, sinun keskuudessasi, valitsemassaan paikassa, jonkun kaupunkisi porttien sisäpuolella, missä hän viihtyy; älä sorra häntä.'),
(1674438,58,5,23,17,'Älköön pyhäkköporttoa olko Israelin tyttärien joukossa älköönkä haureellista pyhäkköpoikaa Israelin poikien joukossa.'),
(1674439,58,5,23,18,'Älä tuo portonpalkkaa äläkä koiranpalkkaa Herran, sinun Jumalasi, huoneeseen lupauksen suoritukseksi, sillä molemmat ovat kauhistus Herralle, sinun Jumalallesi.'),
(1674440,58,5,23,19,'Älä pane veljeäsi maksamaan korkoa rahasta tai elintarpeista tai muusta, mitä korkoa vastaan lainataan.'),
(1674441,58,5,23,20,'Muukalaisen saat panna korkoa maksamaan, mutta et veljeäsi, että Herra, sinun Jumalasi, siunaisi sinua kaikessa, mihin ryhdyt, siinä maassa, jota menet ottamaan omaksesi.'),
(1674442,58,5,23,21,'Kun teet lupauksen Herralle, sinun Jumalallesi, niin täytä se viivyttelemättä, sillä totisesti on Herra, sinun Jumalasi, sen vaativa sinulta, ja sinä joudut syyhyn.'),
(1674443,58,5,23,22,'Mutta jos jätät lupauksen tekemättä, et joudu syyhyn.'),
(1674444,58,5,23,23,'Pidä se, mikä on huuliltasi lähtenyt, ja tee, niinkuin vapaaehtoisesti olet luvannut Herralle, sinun Jumalallesi, niinkuin olet suullasi puhunut.'),
(1674445,58,5,23,24,'Kun tulet lähimmäisesi viinitarhaan, niin saat syödä rypäleitä, minkä mielesi tekee, kunnes olet saanut kylläsi, mutta älä pane mitään astiaasi.'),
(1674446,58,5,23,25,'Kun tulet lähimmäisesi viljapellolle, niin saat kädelläsi katkoa tähkäpäitä, mutta sirppiä älä heiluta lähimmäisesi viljapellolla."'),
(1674447,58,5,24,1,'"Jos joku ottaa vaimon ja nai hänet ja vaimo ei häntä enää miellytä, sentähden että mies on tavannut hänessä jotakin häpeällistä, ja hän kirjoittaa hänelle erokirjan ja antaa sen hänen käteensä ja lähettää hänet pois talostaan,'),
(1674448,58,5,24,2,'ja jos nainen sitten, lähdettyään hänen talostaan, menee ja joutuu toisen miehen vaimoksi,'),
(1674449,58,5,24,3,'ja myöskin tämä toinen mies hylkii häntä ja kirjoittaa hänelle erokirjan ja antaa sen hänen käteensä ja lähettää hänet pois talostaan, tai jos tämä toinen mies, joka on ottanut hänet vaimokseen, kuolee,'),
(1674450,58,5,24,4,'älköön hänen ensimmäinen miehensä, joka lähetti hänet pois, ottako häntä uudestaan vaimokseen, sittenkuin tämä on tullut saastutetuksi, sillä se olisi kauhistus Herran edessä. Älä saata syynalaiseksi maata, jonka Herra, sinun Jumalasi, antaa sinulle perintöosaksi.'),
(1674451,58,5,24,5,'Jos joku äsken on ottanut vaimon, ei hänen tarvitse lähteä sotaan, älköönkä hänen päälleen pantako muutakaan rasitusta; olkoon hän vuoden ajan vapaa perhettään varten ja iloksi vaimolleen, jonka on ottanut.'),
(1674452,58,5,24,6,'Älköön pantiksi otettako käsikiviä, ei päällimmäistäkään kiveä, sillä se olisi hengen ottamista pantiksi.'),
(1674453,58,5,24,7,'Jos joku tavataan siitä, että hän on varastanut jonkun veljistään, israelilaisista, ja kohdellut häntä tylysti tai myynyt hänet, niin varas kuolkoon. Poista paha keskuudestasi.'),
(1674454,58,5,24,8,'Ole varuillasi pitalitautia vastaan, niin että tarkoin noudatat kaikkea, mitä leeviläiset papit teille neuvovat. Noudattakaa tarkoin käskyjä, jotka minä olen heille antanut.'),
(1674455,58,5,24,9,'Muista, mitä Herra, sinun Jumalasi, teki Mirjamille matkalla, kun te olitte lähteneet Egyptistä.'),
(1674456,58,5,24,10,'Jos lainaat jotakin lähimmäisellesi, älä mene hänen taloonsa ottamaan häneltä panttia.'),
(1674457,58,5,24,11,'Jää ulos, ja se mies, jolle lainasit, tuokoon pantin sinulle ulos.'),
(1674458,58,5,24,12,'Ja jos hän on köyhä mies, niin älä mene maata, pitäen hänen panttiansa,'),
(1674459,58,5,24,13,'vaan anna hänelle takaisin hänen panttinsa auringon laskiessa, että hän voisi maata vaipassaan ja siunaisi sinua; se koituu sinulle vanhurskaudeksi Herran, sinun Jumalasi, edessä.'),
(1674460,58,5,24,14,'Älä tee vääryyttä kurjalle ja köyhälle palkkalaiselle, olipa hän veljiäsi tai muukalaisia, joita asuu maassasi, sinun porttiesi sisäpuolella.'),
(1674461,58,5,24,15,'Maksa hänelle hänen palkkansa samana päivänä, ennenkuin aurinko laskee, sillä hän on kurja ja halajaa palkkaansa - ettei hän huutaisi sinun tähtesi Herran puoleen ja ettet sinä joutuisi syyhyn.'),
(1674462,58,5,24,16,'Älköön isiä rangaistako kuolemalla lasten tähden älköönkä lapsia isien tähden; kukin rangaistakoon kuolemalla oman syntinsä tähden.'),
(1674463,58,5,24,17,'Älä vääristä muukalaisen äläkä orvon oikeutta, äläkä ota lesken vaatteita pantiksi.'),
(1674464,58,5,24,18,'Muista, että itse olit orjana Egyptissä ja että Herra, sinun Jumalasi, sinut sieltä vapahti; sentähden minä käsken sinua näin tekemään.'),
(1674465,58,5,24,19,'Jos korjatessasi eloa pelloltasi unhotat pellolle lyhteen, älä palaa sitä hakemaan; se olkoon muukalaisen, orvon ja lesken oma, että Herra, sinun Jumalasi, siunaisi sinua kaikissa kättesi töissä.'),
(1674466,58,5,24,20,'Kun olet pudistanut öljypuustasi hedelmät, älä enää jäännöstä oksilta poimi; se olkoon muukalaisen, orvon ja lesken oma.'),
(1674467,58,5,24,21,'Kun olet korjannut sadon viinitarhastasi, älä enää jälkikorjuuta pidä; se jääköön muukalaiselle, orvolle ja leskelle.'),
(1674468,58,5,24,22,'Muista, että itse olit orjana Egyptin maassa; sentähden minä käsken sinua näin tekemään."'),
(1674469,58,5,25,1,'"Jos syntyy riita miesten välillä ja he astuvat oikeuden eteen ja heidät tuomitaan, syytön syyttömäksi ja syyllinen syylliseksi,'),
(1674470,58,5,25,2,'ja jos syyllinen tuomitaan raippoihin, niin käskeköön tuomari hänen laskeutua maahan ja annattakoon läsnä ollessaan hänelle hänen rikostaan vastaavan määräluvun raippoja.'),
(1674471,58,5,25,3,'Neljäkymmentä raippaa saa hän hänelle antaa, ei enempää, ettei veljeäsi häväistäisi sinun silmiesi edessä antamalla hänelle vielä useampia lyöntejä.'),
(1674472,58,5,25,4,'Älä sido puivan härän suuta.'),
(1674473,58,5,25,5,'Kun veljeksiä asuu yhdessä ja joku heistä kuolee eikä hänellä ole poikaa, niin älköön vainajan leski menkö naimisiin muuhun sukuun, syrjäisen miehen kanssa. Hänen lankonsa yhtyköön häneen, ottakoon hänet vaimokseen ja täyttäköön häntä kohtaan langon velvollisuuden.'),
(1674474,58,5,25,6,'Ja esikoinen, jonka vaimo synnyttää, katsottakoon kuolleen veljen omaksi, ettei hänen nimeänsä pyyhittäisi pois Israelista.'),
(1674475,58,5,25,7,'Mutta jos mies ei suostu ottamaan kälyänsä vaimoksi, niin menköön käly porttiin vanhinten eteen ja sanokoon: ''Minun lankoni kieltäytyy pysyttämästä veljensä nimeä Israelissa; hän ei tahdo täyttää langon velvollisuutta''.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674476,58,5,25,8,'Silloin hänen kaupunkinsa vanhimmat kutsukoot hänet ja puhutelkoot häntä. Ja jos hän pysyy päätöksessään ja sanoo: ''En suostu ottamaan häntä vaimokseni'','),
(1674477,58,5,25,9,'niin hänen kälynsä astukoon hänen luoksensa vanhinten silmien eteen ja vetäköön kengän hänen jalastaan, sylkeköön häntä silmille ja lausukoon sanoen: ''Näin tehtäköön jokaiselle, joka ei veljensä huonetta rakenna''.'),
(1674478,58,5,25,10,'Ja hänen perhettänsä nimitettäköön sitten Israelissa ''paljasjalan perheeksi''.'),
(1674479,58,5,25,11,'Jos kaksi miestä tappelee keskenään ja toisen vaimo tulee auttamaan miestään sen käsistä, joka häntä lyö, ja ojentaa kätensä ja tarttuu tämän häpyyn,'),
(1674480,58,5,25,12,'niin hakkaa poikki hänen kätensä säälimättä.'),
(1674481,58,5,25,13,'Älä pidä kukkarossasi kahdenlaisia punnuksia, suurempia ja pienempiä.'),
(1674482,58,5,25,14,'Älä pidä talossasi kahdenlaista eefa-mittaa, suurempaa ja pienempää.'),
(1674483,58,5,25,15,'Olkoon sinulla täydet ja oikeat punnukset; olkoon sinulla täysi ja oikea eefa-mitta, että eläisit kauan siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa.'),
(1674484,58,5,25,16,'Sillä jokainen, joka näitä tekee, on kauhistus Herralle, jokainen, joka vääryyttä tekee.'),
(1674485,58,5,25,17,'Muista, mitä Amalek teki sinulle matkalla, kun olit lähtenyt Egyptistä,'),
(1674486,58,5,25,18,'kuinka hän, Jumalaa pelkäämättä, tuli sinua vastaan tiellä, kun sinä olit väsynyt ja uuvuksissa, ja eristi sinun yhteydestäsi kaikki heikommat, jotka kulkivat jälkipäässä.'),
(1674487,58,5,25,19,'Sentähden, kun Herra, sinun Jumalasi, antaa sinun päästä rauhaan kaikista ympärillä olevista vihollisistasi siinä maassa, jonka Herra, sinun Jumalasi, antaa sinulle perintöosaksi, ottaaksesi sen omaksesi, niin pyyhi pois Amalekin muisto taivaan alta. Älä tätä unhota."'),
(1674488,58,5,26,1,'"Kun tulet siihen maahan, jonka Herra, sinun Jumalasi, antaa sinulle perintöosaksi, ja sinä otat sen omaksesi ja asetut siihen,'),
(1674489,58,5,26,2,'niin ota uutiset kaikista maasi hedelmistä, mitä saat satona maastasi, jonka Herra, sinun Jumalasi, sinulle antaa, ja pane ne koriin ja lähde siihen paikkaan, jonka Herra, sinun Jumalasi, valitsee nimensä asuinsijaksi.'),
(1674490,58,5,26,3,'Ja mene sen tykö, joka siihen aikaan on pappina, ja sano hänelle: ''Minä tunnustan tänä päivänä Herralle, sinun Jumalallesi, että minä olen tullut siihen maahan, jonka Herra meidän isillemme vannotulla valalla on luvannut antaa meille''.'),
(1674491,58,5,26,4,'Ja pappi ottakoon korin sinun kädestäsi ja asettakoon sen Herran, sinun Jumalasi, alttarin eteen.'),
(1674492,58,5,26,5,'Niin lausu Herran, Jumalasi, edessä sanoen: ''Minun isäni oli harhaileva aramilainen, joka meni Egyptiin, vähäinen joukko mukanaan, ja asui siellä muukalaisena ja tuli siellä suureksi, väkeväksi ja lukuisaksi kansaksi.'),
(1674493,58,5,26,6,'Mutta egyptiläiset kohtelivat meitä pahoin ja rasittivat meitä ja teettivät meillä kovaa työtä.'),
(1674494,58,5,26,7,'Silloin me huusimme Herran, isiemme Jumalan, puoleen, ja Herra kuuli meidän huutomme ja näki meidän kurjuutemme, vaivamme ja kärsimämme sorron.'),
(1674495,58,5,26,8,'Ja Herra vei meidät pois Egyptistä väkevällä kädellä ja ojennetulla käsivarrella, suurella peljätyksellä, tehden tunnustekoja ja ihmeitä.'),
(1674496,58,5,26,9,'Ja hän toi meidät tähän paikkaan ja antoi meille tämän maan, maan, joka vuotaa maitoa ja mettä.'),
(1674497,58,5,26,10,'Ja katso, nyt minä tuon uutiset sen maan hedelmistä, jonka sinä, Herra, minulle annoit.'' Niin aseta ne Herran, sinun Jumalasi, eteen ja kumartaen rukoile Herran, sinun Jumalasi, edessä'),
(1674498,58,5,26,11,'ja iloitse kaikesta hyvästä, minkä Herra, sinun Jumalasi, on antanut sinulle ja sinun perheellesi, sinä ja leeviläinen ja muukalainen, joka asuu sinun keskuudessasi.'),
(1674499,58,5,26,12,'Kun kolmantena vuotena, kymmenysten vuotena, olet suorittanut loppuun kaikki kymmenykset saamastasi sadosta ja antanut ne leeviläiselle, muukalaiselle, orvolle ja leskelle, ja he ovat syöneet sinun porttiesi sisäpuolella ja tulleet ravituiksi,'),
(1674500,58,5,26,13,'niin sano Herran, Jumalasi, edessä: ''Minä olen vienyt pois talostani sen, mikä on pyhäkölle pyhitettyä, ja olen antanut sen leeviläiselle ja muukalaiselle, orvolle ja leskelle, aivan sinun käskysi mukaan, jonka olet minulle antanut; en ole rikkonut sinun käskyjäsi enkä niitä unhottanut.'),
(1674501,58,5,26,14,'Minä en syönyt siitä mitään silloin, kun minulla oli suru, enkä vienyt siitä mitään pois silloin, kun olin saastunut, enkä antanut siitä mitään vainajalle. Olen kuullut Herran, minun Jumalani, ääntä; olen tehnyt aivan niin, kuin olet minun käskenyt tehdä.'),
(1674502,58,5,26,15,'Katso pyhästä asunnostasi, taivaasta, ja siunaa kansaasi Israelia ja sitä maata, jonka olet meille antanut, niinkuin valalla vannoen lupasit isillemme, maata, joka vuotaa maitoa ja mettä.'''),
(1674503,58,5,26,16,'Tänä päivänä Herra, sinun Jumalasi, käskee sinun seurata näitä käskyjä ja oikeuksia; noudata ja seuraa niitä kaikesta sydämestäsi ja kaikesta sielustasi.'),
(1674504,58,5,26,17,'Sinä olet tänään kuullut Herran, sinun Jumalasi, julistavan, että hän tahtoo olla sinun Jumalasi ja että sinun on vaellettava hänen teitänsä ja noudatettava hänen käskyjänsä, säädöksiänsä ja oikeuksiansa sekä kuultava häntä.'),
(1674505,58,5,26,18,'Ja Herra on kuullut sinun tänä päivänä julistavan, että sinä tahdot olla hänen omaisuuskansansa, niinkuin hän on sinulle puhunut, ja noudattaa kaikkia hänen käskyjänsä,'),
(1674506,58,5,26,19,'että hän asettaisi sinut korkeammaksi kaikkia luomiansa kansoja, ylistykseksi, kunniaksi ja kiitokseksi, ja että olisit Herralle, sinun Jumalallesi, pyhitetty kansa, niinkuin hän on puhunut."'),
(1674507,58,5,27,1,'Niin Mooses ja Israelin vanhimmat käskivät kansaa sanoen: "Noudattakaa kaikkia niitä käskyjä, jotka minä tänä päivänä teille annan.'),
(1674508,58,5,27,2,'Ja kun menette Jordanin yli siihen maahan, jonka Herra, sinun Jumalasi, sinulle antaa, pystytä itsellesi suuria kiviä ja sivele ne kalkilla.'),
(1674509,58,5,27,3,'Ja kirjoita niihin kaikki tämän lain sanat, kun menet joen yli siihen maahan, jonka Herra, sinun Jumalasi, sinulle antaa, maahan, joka vuotaa maitoa ja mettä, niinkuin Herra, sinun isiesi Jumala, on sinulle puhunut.'),
(1674510,58,5,27,4,'Ja kun olette menneet Jordanin yli, niin pystyttäkää Eebalin vuorelle ne kivet, joista minä tänä päivänä annan teille käskyn, ja sivele ne kalkilla.'),
(1674511,58,5,27,5,'Ja rakenna siihen alttari Herralle, sinun Jumalallesi, alttari kivistä, joihin et saa rauta-aseella koskea.'),
(1674512,58,5,27,6,'Hakkaamattomista kivistä rakenna Herran, Jumalasi, alttari; uhraa sen päällä polttouhreja Herralle, Jumalallesi,'),
(1674513,58,5,27,7,'ja teurasta teuraita yhteysuhriksi ja syö siellä ja iloitse Herran, Jumalasi, edessä.'),
(1674514,58,5,27,8,'Ja kirjoita kiviin kaikki tämän lain sanat hyvin selkeästi."'),
(1674515,58,5,27,9,'Ja Mooses ja leeviläiset papit puhuivat kaikelle Israelille sanoen: "Ole hiljaa ja kuule, Israel! Tänä päivänä on sinusta tullut Herran, Jumalasi, kansa.'),
(1674516,58,5,27,10,'Kuule siis Herraa, Jumalaasi, ja noudata hänen käskyjänsä ja ohjeitansa, jotka minä tänä päivänä sinulle annan."'),
(1674517,58,5,27,11,'Ja Mooses käski kansaa sinä päivänä sanoen:'),
(1674518,58,5,27,12,'"Kun te olette menneet Jordanin yli, asettukoot nämä Garissimin vuorelle siunaamaan kansaa: Simeon, Leevi, Juuda, Isaskar, Joosef ja Benjamin.'),
(1674519,58,5,27,13,'Nämä taas asettukoot Eebalin vuorelle lausumaan kirouksen: Ruuben, Gaad, Asser, Sebulon, Daan ja Naftali.'),
(1674520,58,5,27,14,'Ja leeviläiset lausukoot ja sanokoot kovalla äänellä kaikille Israelin miehille:'),
(1674521,58,5,27,15,'''Kirottu olkoon se, joka tekee jumalankuvan, veistetyn tai valetun, taitajan käden tekemän, kauhistukseksi Herralle, ja joka salaa sen pystyttää''. Ja kaikki kansa vastatkoon ja sanokoon: ''Amen''.'),
(1674522,58,5,27,16,'Kirottu olkoon se, joka häpäisee isäänsä tai äitiänsä. Ja kaikki kansa sanokoon: ''Amen''.'),
(1674523,58,5,27,17,'Kirottu olkoon se, joka siirtää lähimmäisensä rajan. Ja kaikki kansa sanokoon: ''Amen''.'),
(1674524,58,5,27,18,'Kirottu olkoon se, joka vie sokean harhaan tieltä. Ja kaikki kansa sanokoon: ''Amen''.'),
(1674525,58,5,27,19,'Kirottu olkoon se, joka vääristää muukalaisen, orvon tai lesken oikeuden. Ja kaikki kansa sanokoon: ''Amen''.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674526,58,5,27,20,'Kirottu olkoon se, joka makaa äitipuolensa kanssa, sillä hän nostaa isänsä peitteen. Ja kaikki kansa sanokoon: ''Amen''.'),
(1674527,58,5,27,21,'Kirottu olkoon se, joka sekaantuu eläimeen. Ja kaikki kansa sanokoon: ''Amen''.'),
(1674528,58,5,27,22,'Kirottu olkoon se, joka makaa sisarensa, isänsä tyttären tai äitinsä tyttären, kanssa. Ja kaikki kansa sanokoon: ''Amen''.'),
(1674529,58,5,27,23,'Kirottu olkoon se, joka makaa anoppinsa kanssa. Ja kaikki kansa sanokoon: ''Amen''.'),
(1674530,58,5,27,24,'Kirottu olkoon se, joka salaa murhaa lähimmäisensä. Ja kaikki kansa sanokoon: ''Amen''.'),
(1674531,58,5,27,25,'Kirottu olkoon se, joka ottaa lahjuksen surmatakseen viattoman. Ja kaikki kansa sanokoon: ''Amen''.'),
(1674532,58,5,27,26,'Kirottu olkoon se, joka ei pidä tämän lain sanoja eikä täytä niitä. Ja kaikki kansa sanokoon: ''Amen''."'),
(1674533,58,5,28,1,'"Jos kuulet Herran, sinun Jumalasi, ääntä ja pidät tarkoin kaikki hänen käskynsä, jotka minä tänä päivänä sinulle annan, niin Herra, sinun Jumalasi, asettaa sinut korkeammaksi kaikkia kansoja maan päällä.'),
(1674534,58,5,28,2,'Ja kaikki nämä siunaukset tulevat sinun osaksesi ja saavuttavat sinut, jos kuulet Herran, sinun Jumalasi, ääntä.'),
(1674535,58,5,28,3,'Siunattu olet sinä kaupungissa ja siunattu olet kedolla.'),
(1674536,58,5,28,4,'Siunattu on sinun kohtusi hedelmä ja maasi hedelmä ja sinun karjasi hedelmä, raavaittesi vasikat ja lampaittesi karitsat.'),
(1674537,58,5,28,5,'Siunattu on sinun korisi ja sinun taikinakaukalosi.'),
(1674538,58,5,28,6,'Siunattu olet tullessasi ja siunattu olet lähtiessäsi.'),
(1674539,58,5,28,7,'Herra antaa sinun voittaa vihollisesi, jotka nousevat sinua vastaan; yhtä tietä he lähtevät sinua vastaan, mutta seitsemää tietä he sinua pakenevat.'),
(1674540,58,5,28,8,'Herra käskee siunauksen seurata sinua jyväaitoissasi ja kaikessa, mihin ryhdyt; hän siunaa sinua siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa.'),
(1674541,58,5,28,9,'Herra korottaa sinut hänelle pyhitetyksi kansaksi, niinkuin hän valalla vannoen on sinulle luvannut, jos sinä noudatat Herran, sinun Jumalasi, käskyjä ja vaellat hänen teitänsä.'),
(1674542,58,5,28,10,'Ja kaikki kansat maan päällä näkevät, että Herra on ottanut sinut nimiinsä; ja he pelkäävät sinua.'),
(1674543,58,5,28,11,'Ja Herra antaa sinulle ylen runsaasti hyvää, tekee sinun kohtusi hedelmän, karjasi hedelmän ja maasi hedelmän ylen runsaaksi siinä maassa, jonka Herra sinun isillesi vannotulla valalla on luvannut antaa sinulle.'),
(1674544,58,5,28,12,'Herra avaa sinulle rikkaan aarrekammionsa, taivaan, antaakseen sinun maallesi sateen aikanansa ja siunatakseen kaikki sinun kättesi työt; ja sinä lainaat monelle kansalle, mutta sinun itsesi ei tarvitse lainaa ottaa.'),
(1674545,58,5,28,13,'Ja Herra tekee sinut pääksi eikä hännäksi; sinä aina vain ylenet etkä koskaan alene, jos tottelet Herran, sinun Jumalasi, käskyjä, jotka minä tänä päivänä sinulle annan, että ne tarkoin pitäisit,'),
(1674546,58,5,28,14,'etkä poikkea oikealle etkä vasemmalle yhdestäkään niistä sanoista, jotka minä tänä päivänä teille annan, et seuraa muita jumalia etkä palvele niitä.'),
(1674547,58,5,28,15,'Mutta jos sinä et kuule Herran, sinun Jumalasi, ääntä etkä tarkoin pidä kaikkia hänen käskyjänsä ja säädöksiänsä, jotka minä tänä päivänä sinulle annan, niin kaikki nämä kiroukset tulevat sinun päällesi ja saavuttavat sinut.'),
(1674548,58,5,28,16,'Kirottu olet sinä kaupungissa ja kirottu olet kedolla.'),
(1674549,58,5,28,17,'Kirottu on sinun korisi ja sinun taikinakaukalosi.'),
(1674550,58,5,28,18,'Kirottu on sinun kohtusi hedelmä ja maasi hedelmä, kirotut sinun raavaittesi vasikat ja lampaittesi karitsat.'),
(1674551,58,5,28,19,'Kirottu olet tullessasi ja kirottu olet lähtiessäsi.'),
(1674552,58,5,28,20,'Herra lähettää sinun sekaasi kirousta, hämminkiä ja uhkaa, mihin tahansa ryhdyt, kunnes äkisti tuhoudut ja hukut töittesi pahuuden tähden, kun olet minut hyljännyt.'),
(1674553,58,5,28,21,'Herra antaa ruttotaudin tarttua sinuun, kunnes se sukupuuttoon hävittää sinut siitä maasta, jota menet ottamaan omaksesi.'),
(1674554,58,5,28,22,'Herra lyö sinua hivutustaudilla, kuumeella, poltteella ja tulehduksella, kuivuudella, nokitähkillä ja viljan ruosteella, ja ne vainoavat sinua, kunnes menehdyt.'),
(1674555,58,5,28,23,'Ja taivaasi, joka on sinun pääsi päällä, on niinkuin vaski, ja maa, joka on allasi, on niinkuin rauta.'),
(1674556,58,5,28,24,'Herra muuttaa sinun maasi sateen tomuksi ja tuhaksi; taivaasta se tulee sinun päällesi, kunnes tuhoudut.'),
(1674557,58,5,28,25,'Herra antaa sinun vihollistesi voittaa sinut; yhtä tietä sinä menet heitä vastaan, mutta seitsemää tietä sinä heitä pakenet; ja sinä tulet kauhistukseksi kaikille valtakunnille maan päällä.'),
(1674558,58,5,28,26,'Ja ruumiisi joutuvat ruuaksi kaikille taivaan linnuille ja maan eläimille, eikä kukaan karkoita niitä.'),
(1674559,58,5,28,27,'Herra lyö sinua Egyptin paiseilla ja ajoksilla, ihottumalla ja ruvella, joista et parannu.'),
(1674560,58,5,28,28,'Herra lyö sinua hulluudella, sokeudella ja mielisairaudella.'),
(1674561,58,5,28,29,'Sinä haparoit keskellä päivää, niinkuin sokea haparoi pimeässä; sinä et menesty teilläsi, vaan kaiken elinaikasi sinä olet oleva sorrettu ja ryöstetty, eikä ole auttajaa.'),
(1674562,58,5,28,30,'Sinä kihlaat naisen, mutta toinen makaa hänet; sinä rakennat talon, mutta et siinä asu; sinä istutat viinitarhan, mutta et korjaa sen hedelmää.'),
(1674563,58,5,28,31,'Härkäsi teurastetaan sinun silmiesi edessä, mutta sinä et sitä syö; aasisi ryöstetään sinulta sinun nähtesi eikä sitä anneta sinulle takaisin; lampaasi joutuvat sinun vihollistesi valtaan, eikä sinulla ole auttajaa.'),
(1674564,58,5,28,32,'Sinun poikasi ja tyttäresi joutuvat vieraan kansan valtaan, ja sinun silmäsi näkevät sen ja raukeavat heitä alinomaa ikävöidessäsi, mutta sinä et voi sille mitään.'),
(1674565,58,5,28,33,'Sinun maasi hedelmän ja kaiken sinun vaivannäkösi kuluttaa kansa, jota sinä et tunne; kaiken elinaikasi sinä olet oleva sorrettu ja runneltu.'),
(1674566,58,5,28,34,'Ja sinä tulet hulluksi siitä, mitä sinun silmäsi näkevät.'),
(1674567,58,5,28,35,'Herra lyö sinuun, sinun polviisi ja pohkeisiisi, pahoja paiseita, joista et parannu, kantapäästä kiireeseen asti.'),
(1674568,58,5,28,36,'Herra vie sinut ja kuninkaan, jonka sinä itsellesi asetat, kansan luo, jota sinä et tunne ja jota sinun isäsi eivät tunteneet; ja siellä sinä palvelet muita jumalia, puu- ja kivijumalia.'),
(1674569,58,5,28,37,'Ja sinä tulet kauhistukseksi, sananparreksi ja pistopuheeksi kaikille niille kansoille, joiden keskuuteen Herra sinut kuljettaa.'),
(1674570,58,5,28,38,'Paljon siementä sinä viet pellollesi, mutta vähän sinä korjaat, sillä heinäsirkat hävittävät sen.'),
(1674571,58,5,28,39,'Viinitarhoja sinä istutat ja hoidat, mutta viiniä et saa juodaksesi etkä tallettaaksesi, sillä madot syövät sen.'),
(1674572,58,5,28,40,'Öljypuita sinulla on kaikkialla alueellasi, mutta öljyllä et sinä itseäsi voitele, sillä sinun öljymarjasi varisevat maahan.'),
(1674573,58,5,28,41,'Poikia ja tyttäriä sinulle syntyy, mutta et saa niitä pitää, sillä he vaeltavat vankeuteen.'),
(1674574,58,5,28,42,'Tuhohyönteiset valtaavat kaikki sinun puusi ja sinun maasi hedelmän.'),
(1674575,58,5,28,43,'Muukalainen, joka asuu keskuudessasi, kohoaa sinun ylitsesi yhä ylemmäksi, mutta sinä painut aina alemmaksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674576,58,5,28,44,'Hän lainaa sinulle, mutta sinä et voi lainata hänelle. Hän tulee pääksi, mutta sinä hännäksi.'),
(1674577,58,5,28,45,'Kaikki nämä kiroukset tulevat sinun päällesi, vainoavat sinua ja saavuttavat sinut, kunnes tuhoudut, koska et kuullut Herran, sinun Jumalasi ääntä etkä noudattanut hänen käskyjänsä ja säädöksiänsä, jotka hän on sinulle antanut.'),
(1674578,58,5,28,46,'Ne jäävät merkkeinä ja ihmeinä sinuun ja sinun jälkeläisiisi iankaikkisesti.'),
(1674579,58,5,28,47,'Koska et palvellut Herraa, sinun Jumalaasi, ilolla ja sydämen halulla, kun sinulla oli yltäkyllin kaikkea,'),
(1674580,58,5,28,48,'on sinun palveltava vihollisiasi, jotka Herra sinun kimppuusi lähettää, nälässä ja janossa ja alastomuudessa ja kaiken puutteessa. Ja hän panee sinun kaulallesi rautaisen ikeen, kunnes hän sinut tuhoaa.'),
(1674581,58,5,28,49,'Herra nostaa sinua vastaan kaukaisen kansan, joka tulee maan äärestä lentäen niinkuin kotka, kansan, jonka kieltä sinä et ymmärrä;'),
(1674582,58,5,28,50,'tuimakatseisen kansan, joka ei armahda vanhaa eikä sääli nuorta.'),
(1674583,58,5,28,51,'Se syö sinun karjasi hedelmän ja maasi hedelmän, kunnes sinä tuhoudut; se ei jätä sinulle mitään, ei jyviä ei viiniä eikä öljyä, ei raavaittesi vasikoita eikä lampaittesi karitsoita, kunnes on tehnyt sinusta lopun.'),
(1674584,58,5,28,52,'Ja se ahdistaa sinua kaikissa porteissasi, kunnes korkeat ja lujat muurisi, joihin sinä luotit, kukistuvat kaikkialla maassasi. Se ahdistaa sinua kaikissa porteissasi kaikkialla sinun maassasi, jonka Herra, sinun Jumalasi, on sinulle antanut.'),
(1674585,58,5,28,53,'Siinä hädässä ja ahdistuksessa, johon sinun vihollisesi saattaa sinut, sinä syöt oman kohtusi hedelmän, syöt poikiesi ja tyttäriesi lihaa, jotka Herra, sinun Jumalasi, on sinulle antanut.'),
(1674586,58,5,28,54,'Hempeästi ja hekumallisesti elänyt mies sinun keskuudessasi katselee silloin karsaasti veljeänsä ja vaimoaan, joka hänen sylissänsä on, ja jäljellä olevia lapsiaan, jotka hän on jättänyt henkiin;'),
(1674587,58,5,28,55,'kenellekään heistä hän ei anna lastensa lihaa, jota hän itse syö, kun hänellä ei ole mitään muuta jäljellä, siinä hädässä ja ahdistuksessa, johon vihollisesi saattaa sinut kaikissa sinun porteissasi.'),
(1674588,58,5,28,56,'Hempeästi ja hekumallisesti elänyt nainen sinun keskuudessasi, joka hekumassaan ja hempeydessään ei edes yrittänyt laskea jalkaansa maahan, katselee silloin karsaasti miestä, joka hänen sylissänsä on, ja poikaansa ja tytärtänsä'),
(1674589,58,5,28,57,'eikä suo heille jälkeläisiä, jotka tulevat hänen kohdustansa, eikä lapsia, joita hän synnyttää, sillä kaiken muun puutteessa syö hän ne salaa itse siinä hädässä ja ahdistuksessa, johon vihollisesi saattaa sinut sinun porteissasi.'),
(1674590,58,5,28,58,'Jos et tarkoin noudata kaikkia tämän lain sanoja, jotka ovat kirjoitetut tähän kirjaan, niin että pelkäät tätä kunniallista ja peljättävää nimeä, Herraa, sinun Jumalaasi,'),
(1674591,58,5,28,59,'niin Herra panee sinun ja sinun jälkeläistesi kärsittäväksi erinomaisia vaivoja, suuria ja pitkällisiä vaivoja, pahoja ja pitkällisiä sairauksia.'),
(1674592,58,5,28,60,'Hän kääntää sinua vastaan kaikki Egyptin taudit, joita sinä pelkäät, ja ne tarttuvat sinuun.'),
(1674593,58,5,28,61,'Ja kaikkinaisia muita sairauksia ja vaivoja, joista ei ole kirjoitettu tässä lakikirjassa, Herra nostattaa sinua vastaan, kunnes sinä tuhoudut.'),
(1674594,58,5,28,62,'Ja teistä, jotka ennen olitte monilukuiset kuin taivaan tähdet, jää jäljelle ainoastaan vähäinen joukko, koska et kuullut Herran, sinun Jumalasi, ääntä.'),
(1674595,58,5,28,63,'Ja niinkuin Herra ennen iloitsi teistä, siitä, että teki teille hyvää ja antoi teidän lisääntyä, niin Herra silloin iloitsee teistä, siitä, että hävittää ja tuhoaa teidät. Ja teidät temmataan irti siitä maasta, jota sinä menet ottamaan omaksesi.'),
(1674596,58,5,28,64,'Ja Herra hajottaa sinut kaikkien kansojen sekaan maan äärestä toiseen, ja sinä palvelet siellä muita jumalia, joita sinä et tunne ja joita sinun isäsi eivät tunteneet, puuta ja kiveä.'),
(1674597,58,5,28,65,'Ja niiden kansojen seassa sinä et saa rauhaa, eikä jalkasi löydä lepopaikkaa. Herra antaa sinulle siellä vapisevan sydämen, rauenneet silmät ja nääntyvän sielun.'),
(1674598,58,5,28,66,'Ja sinun elämäsi näyttää sinusta olevan hiuskarvan varassa, yöt ja päivät sinä olet pelon vallassa etkä ole varma hengestäsi.'),
(1674599,58,5,28,67,'Aamulla sinä sanot: ''Jospa olisi ilta!'' ja illalla sanot: ''Jospa olisi aamu!'' - sellaista pelkoa sinä tunnet sydämessäsi, ja sellaisia näkyjä sinä näet silmissäsi.'),
(1674600,58,5,28,68,'Ja Herra vie sinut laivoilla takaisin Egyptiin samaa tietä, josta minä sanoin sinulle: ''Et ole sitä enää näkevä''. Ja siellä teitä kaupitaan vihollisillenne orjiksi ja orjattariksi, mutta ostajaa ei ole."'),
(1674601,58,5,29,1,'Nämä ovat sen liiton sanat, jonka Herra käski Mooseksen tehdä israelilaisten kanssa Mooabin maassa, sen liiton lisäksi, jonka hän oli tehnyt heidän kanssaan Hoorebilla.'),
(1674602,58,5,29,2,'(29:1) Ja Mooses kutsui kokoon kaiken Israelin ja sanoi heille: "Te olette nähneet kaiken, minkä Herra teki teidän silmienne edessä Egyptin maassa faraolle ja kaikille hänen palvelijoilleen ja koko hänen maalleen,'),
(1674603,58,5,29,3,'ne suuret koettelemukset, jotka sinun silmäsi näkivät, ne suuret tunnusteot ja ihmeet.'),
(1674604,58,5,29,4,'Mutta tähän päivään asti Herra ei vielä ole antanut teille sydäntä ymmärtääksenne ja silmiä nähdäksenne ja korvia kuullaksenne.'),
(1674605,58,5,29,5,'Ja minä kuljetin teitä erämaassa neljäkymmentä vuotta: teidän vaatteenne eivät kuluneet yltänne, eivätkä kenkäsi kuluneet jalassasi.'),
(1674606,58,5,29,6,'Leipää ette saaneet syödäksenne ettekä viiniä ja väkijuomaa juodaksenne, jotta tietäisitte, että minä olen Herra, teidän Jumalanne.'),
(1674607,58,5,29,7,'Ja kun te tulitte tähän paikkaan, niin lähtivät Siihon, Hesbonin kuningas, ja Oog, Baasanin kuningas, sotimaan meitä vastaan, mutta me voitimme heidät.'),
(1674608,58,5,29,8,'Ja me valloitimme heidän maansa ja annoimme sen perintöosaksi ruubenilaisille ja gaadilaisille ja toiselle puolelle Manassen sukukuntaa.'),
(1674609,58,5,29,9,'Noudattakaa siis tämän liiton sanoja ja täyttäkää ne menestyäksenne kaikessa, mitä teette.'),
(1674610,58,5,29,10,'Te seisotte tänä päivänä kaikki Herran, teidän Jumalanne, edessä: teidän päämiehenne, sukukuntanne, vanhimpanne ja päällysmiehenne, kaikki Israelin miehet,'),
(1674611,58,5,29,11,'teidän lapsenne ja vaimonne sekä muukalainen, joka on leirissäsi, jopa puunhakkaajasi ja vedenkantajasikin,'),
(1674612,58,5,29,12,'käydäksenne Herran, teidän Jumalanne, liittoon, siihen valaliittoon, jonka Herra, sinun Jumalasi, tänä päivänä tekee sinun kanssasi,'),
(1674613,58,5,29,13,'että hän tänä päivänä korottaisi sinut kansaksensa ja tulisi sinun Jumalaksesi, niinkuin hän on sinulle puhunut ja niinkuin hän on vannonut sinun isillesi, Aabrahamille, Iisakille ja Jaakobille.'),
(1674614,58,5,29,14,'Enkä minä tee tätä liittoa, tätä valaliittoa, ainoastaan teidän kanssanne,'),
(1674615,58,5,29,15,'vaan niinhyvin niiden kanssa, jotka tänä päivänä ovat tässä meidän kanssamme seisomassa Herran, meidän Jumalamme, edessä, kuin niidenkin kanssa, jotka eivät ole tänä päivänä tässä meidän kanssamme.'),
(1674616,58,5,29,16,'Sillä te tiedätte, kuinka me asuimme Egyptin maassa ja kuinka me kuljimme niiden kansojen keskitse, joiden kautta te olette kulkeneet.'),
(1674617,58,5,29,17,'Ja te näitte heidän iljetyksensä, ne puu-, kivi-, hopea- ja kultajumalat, jotka heillä on.'),
(1674618,58,5,29,18,'Älköön siis teidän joukossanne olko ainoatakaan miestä tai naista, sukua tai sukukuntaa, jonka sydän tänä päivänä kääntyisi pois Herrasta, meidän Jumalastamme, mennäkseen palvelemaan noiden kansojen jumalia; älköön teidän keskuudessanne olko juurta, josta kasvaa koiruohoa ja marunaa,'),
(1674619,58,5,29,19,'niin että se, joka kuulee tämän valan sanat, siunaisi itseänsä sydämessään sanoen: ''Minun käy hyvin, vaikka vaellankin sydämeni paatumuksessa''. Siten hän hukuttaisi kaikki, sekä kostean että kuivan maan.'),
(1674620,58,5,29,20,'Herra ei tahdo antaa hänelle anteeksi, vaan silloin suitsuaa Herran viha ja kiivaus sitä miestä vastaan, ja kaikki se kirous, joka on kirjoitettu tähän kirjaan, laskeutuu hänen päällensä, ja Herra pyyhkii pois hänen nimensä taivaan alta.'),
(1674621,58,5,29,21,'Ja Herra erottaa hänet kaikista Israelin sukukunnista, tuottaakseen hänelle onnettomuuden, kaikki ne kiroukset, jotka sisältyvät tähän lain kirjaan kirjoitettuun liittoon.'),
(1674622,58,5,29,22,'Ja tuleva sukupolvi, teidän lapsenne, jotka nousevat teidän jälkeenne, ja vieras, joka tulee kaukaisesta maasta, kysyvät, kun näkevät sen maan vaivat ja ne sairaudet, joilla Herra sitä rasittaa,'),
(1674623,58,5,29,23,'tulikiven ja suolan, kun koko maa on poltettu, niin ettei siihen kylvetä eikä se kasva eikä siitä ruohonkortta nouse - niinkuin oli silloin, kun Sodoma ja Gomorra, Adma ja Seboim hävitettiin, kun Herra vihassaan ja kiivastuksessaan ne hävitti -'),
(1674624,58,5,29,24,'silloin kaikki kansat kysyvät: ''Minkätähden Herra on näin tehnyt tälle maalle? Mistä tämä hänen suuri vihansa hehku?'''),
(1674625,58,5,29,25,'Silloin vastataan: ''Siitä, että he hylkäsivät Herran, isiensä Jumalan, liiton, jonka hän teki heidän kanssansa viedessään heidät pois Egyptin maasta,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674626,58,5,29,26,'ja menivät palvelemaan muita jumalia ja kumarsivat niitä, jumalia, joita he eivät tunteneet ja joita hän ei ollut heidän osalleen jakanut -'),
(1674627,58,5,29,27,'siitä syttyi Herran viha tätä maata kohtaan, niin että hän antoi kohdata sitä kaiken sen kirouksen, joka on kirjoitettu tähän kirjaan.'),
(1674628,58,5,29,28,'Ja Herra tempasi heidät irti heidän maastaan vihassa ja kiivastuksessa ja suuressa suuttumuksessa ja heitti heidät toiseen maahan, niinkuin nyt on tapahtunut.'''),
(1674629,58,5,29,29,'(29:28) Se, mikä on salassa, se on Herran, meidän Jumalamme; mutta mikä on ilmoitettu, se on meitä ja meidän lapsiamme varten ikuisesti, että me pitäisimme kaikki tämän lain sanat."'),
(1674630,58,5,30,1,'"Jos sinä silloin, kun tämä kaikki sinua kohtaa, siunaus tai kirous, jotka minä olen asettanut sinun valittavaksesi, painat sen sydämeesi kaikkien kansojen keskellä, joiden luo Herra, sinun Jumalasi, on sinut karkoittanut,'),
(1674631,58,5,30,2,'ja palajat Herran, sinun Jumalasi, tykö ja kuulet hänen ääntänsä kaikesta sydämestäsi ja kaikesta sielustasi, sinä itse ja sinun lapsesi, kaikessa, niinkuin minä tänä päivänä sinua käsken,'),
(1674632,58,5,30,3,'niin Herra, sinun Jumalasi, kääntää sinun kohtalosi ja armahtaa sinua; Herra, sinun Jumalasi, kokoaa sinut jälleen kaikista kansoista, joiden sekaan hän on sinut hajottanut.'),
(1674633,58,5,30,4,'Vaikka sinun karkoitettusi olisivat taivaan äärissä, niin Herra, sinun Jumalasi, kokoaa ja noutaa sinut sieltäkin.'),
(1674634,58,5,30,5,'Ja Herra, sinun Jumalasi, tuo sinut siihen maahan, jonka sinun isäsi ovat omistaneet, ja niin sinä otat sen omaksesi; ja hän tekee sinulle hyvää ja antaa sinun lisääntyä enemmän kuin isiesi.'),
(1674635,58,5,30,6,'Ja Herra, sinun Jumalasi, ympärileikkaa sinun sydämesi ja sinun jälkeläistesi sydämet, niin että rakastat Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi, että eläisit.'),
(1674636,58,5,30,7,'Ja Herra, sinun Jumalasi, antaa kaikkien näiden kirousten kohdata sinun vihollisiasi ja vihamiehiäsi, jotka sinua vainosivat.'),
(1674637,58,5,30,8,'Ja sinä kuulet jälleen Herran ääntä ja pidät kaikki hänen käskynsä, jotka minä tänä päivänä sinulle annan.'),
(1674638,58,5,30,9,'Herra, sinun Jumalasi, antaa sinulle ylen runsaasti hyvää kaikissa sinun kättesi töissä, hän tekee sinun kohtusi hedelmän, karjasi hedelmän ja maasi hedelmän ylen runsaaksi. Sillä niinkuin Herra iloitsi sinun isistäsi, hän jälleen iloitsee sinusta, siitä, että tekee sinulle hyvää,'),
(1674639,58,5,30,10,'kun sinä kuulet Herran, sinun Jumalasi, ääntä ja noudatat hänen käskyjänsä ja säädöksiänsä, jotka ovat kirjoitetut tähän lain kirjaan, ja kun sinä palajat Herran, sinun Jumalasi, tykö kaikesta sydämestäsi ja kaikesta sielustasi.'),
(1674640,58,5,30,11,'Sillä tämä käsky, jonka minä tänä päivänä sinulle annan, ei ole sinulle vaikea täyttää eikä liian kaukana.'),
(1674641,58,5,30,12,'Se ei ole taivaassa, eikä sinun tarvitse sanoa: ''Kuka nousisi meidän puolestamme taivaaseen noutamaan sen meille ja julistaisi sen meille, että me sen täyttäisimme?'''),
(1674642,58,5,30,13,'Se ei ole meren takana, eikä sinun tarvitse sanoa: ''Kuka menisi meidän puolestamme meren taakse noutamaan sen meille ja julistaisi sen meille, että me sen täyttäisimme?'''),
(1674643,58,5,30,14,'Vaan sana on sinua aivan lähellä, sinun suussasi ja sydämessäsi, niin että voit sen täyttää.'),
(1674644,58,5,30,15,'Katso, minä panen tänä päivänä sinun eteesi elämän ja hyvän, kuoleman ja pahan,'),
(1674645,58,5,30,16,'kun minä tänä päivänä käsken sinua rakastamaan Herraa, sinun Jumalaasi, ja vaeltamaan hänen teitänsä ja noudattamaan hänen käskyjänsä, säädöksiänsä ja oikeuksiansa, että eläisit ja lisääntyisit ja että Herra, sinun Jumalasi, siunaisi sinua siinä maassa, jota menet ottamaan omaksesi.'),
(1674646,58,5,30,17,'Mutta jos sinun sydämesi kääntyy pois etkä tottele, vaan annat vietellä itsesi kumartamaan muita jumalia ja palvelemaan niitä,'),
(1674647,58,5,30,18,'niin minä julistan teille tänä päivänä, että te totisesti hukutte; te ette kauan elä siinä maassa, johon sinä menet Jordanin yli, ottamaan sen omaksesi.'),
(1674648,58,5,30,19,'Minä otan tänä päivänä taivaan ja maan todistajiksi teitä vastaan, että minä olen pannut sinun eteesi elämän ja kuoleman, siunauksen ja kirouksen. Niin valitse siis elämä, että sinä ja sinun jälkeläisesi eläisitte.'),
(1674649,58,5,30,20,'Rakasta Herraa, sinun Jumalaasi, kuule hänen ääntänsä ja riipu hänessä kiinni, sillä siinä on sinun elämäsi ja pitkä ikäsi, ja niin sinä saat asua siinä maassa, jonka Herra sinun isillesi, Aabrahamille, Iisakille ja Jaakobille, vannotulla valalla on luvannut heille antaa."'),
(1674650,58,5,31,1,'Ja Mooses meni ja puhui kaikelle Israelille nämä sanat;'),
(1674651,58,5,31,2,'hän sanoi heille: "Minä olen nyt sadan kahdenkymmenen vuoden vanha; en voi enää mennä ja tulla, ja Herra on sanonut minulle: ''Sinä et mene tämän Jordanin yli''.'),
(1674652,58,5,31,3,'Mutta Herra, sinun Jumalasi, kulkee sinun edelläsi. Hän tuhoaa nämä kansat sinun tieltäsi, ja sinä lasket heidät valtasi alle. Joosua kulkee sinun edelläsi, niinkuin Herra on puhunut.'),
(1674653,58,5,31,4,'Ja Herra tekee heille, niinkuin hän teki Siihonille ja Oogille, tuhoamillensa amorilaisten kuninkaille, ja heidän maallensa.'),
(1674654,58,5,31,5,'Herra antaa heidät teille alttiiksi; tehkää heille aivan sen käskyn mukaan, jonka minä olen teille antanut.'),
(1674655,58,5,31,6,'Olkaa lujat ja rohkeat, älkää peljätkö älkääkä säikähtykö heitä, sillä Herra, sinun Jumalasi, käy itse sinun kanssasi; hän ei jätä eikä hylkää sinua."'),
(1674656,58,5,31,7,'Ja Mooses kutsui Joosuan ja sanoi hänelle koko Israelin läsnä ollessa: "Ole luja ja rohkea, sillä sinä viet tämän kansan siihen maahan, jonka Herra heidän isillensä vannotulla valalla on luvannut antaa heille, ja sinä jaat sen heille perinnöksi.'),
(1674657,58,5,31,8,'Ja Herra itse käy sinun edelläsi, hän on sinun kanssasi, hän ei jätä sinua eikä hylkää sinua; älä pelkää äläkä arkaile."'),
(1674658,58,5,31,9,'Ja Mooses kirjoitti tämän lain ja antoi sen papeille, leeviläisille, jotka kantoivat Herran liitonarkkia, ja kaikille Israelin vanhimmille.'),
(1674659,58,5,31,10,'Ja Mooses käski heitä sanoen: "Joka seitsemäs vuosi, määrättynä aikana vapautusvuonna, lehtimajanjuhlassa,'),
(1674660,58,5,31,11,'kun koko Israel tulee Herran, sinun Jumalasi, kasvojen eteen siinä paikassa, jonka hän valitsee, lue tämä laki koko Israelin läsnä ollessa, heidän kuultensa.'),
(1674661,58,5,31,12,'Kokoa kansa, miehet, naiset ja lapset sekä muukalaiset, jotka asuvat porttiesi sisäpuolella, että he kuulisivat sen ja oppisivat pelkäämään Herraa, teidän Jumalaanne, ja tarkoin pitämään kaikki tämän lain sanat,'),
(1674662,58,5,31,13,'ja että heidän lapsensa, jotka eivät vielä sitä tunne, kuulisivat sen ja oppisivat pelkäämään Herraa, teidän Jumalaanne, niin kauan kuin elätte siinä maassa, johon menette Jordanin yli, ottamaan sen omaksenne."'),
(1674663,58,5,31,14,'Ja Herra sanoi Moosekselle: "Katso, lähestyy aika, jolloin sinun on kuoltava. Kutsu Joosua, ja asettukaa ilmestysmajaan, niin minä asetan hänet virkaansa." Niin Mooses ja Joosua menivät ja asettuivat ilmestysmajaan.'),
(1674664,58,5,31,15,'Niin Herra ilmestyi majassa pilvenpatsaassa, ja pilvenpatsas seisahtui majan ovelle.'),
(1674665,58,5,31,16,'Ja Herra sanoi Moosekselle: "Katso, sinä käyt lepäämään isiesi tykö; silloin tämä kansa nousee ja lähtee haureudessa kulkemaan vieraiden jumalien jäljessä, joita palvellaan siinä maassa, johon se menee, ja hylkää minut ja rikkoo liiton, jonka minä olen tehnyt sen kanssa.'),
(1674666,58,5,31,17,'Sinä päivänä minun vihani syttyy sitä vastaan, ja minä hylkään heidät ja peitän kasvoni heiltä, niin että he joutuvat tuhon omiksi, ja suuret onnettomuudet ja ahdistukset kohtaavat sitä. Sinä päivänä se sanoo: ''Eivätkö nämä onnettomuudet ole kohdanneet minua sen tähden, ettei minun Jumalani ole minun keskelläni?'''),
(1674667,58,5,31,18,'Mutta sinä päivänä minä kokonaan peitän kasvoni kaiken sen pahan tähden, mitä he ovat tehneet, kun ovat kääntyneet muiden jumalien puoleen.'),
(1674668,58,5,31,19,'Ja nyt kirjoittakaa itsellenne tämä virsi. Opeta se israelilaisille ja pane se heidän suuhunsa, että tämä laulu olisi minulle todistajana israelilaisia vastaan.'),
(1674669,58,5,31,20,'Sillä minä vien heidät siihen maahan, jonka minä valalla vannoen olen luvannut heidän isillensä, maahan, joka vuotaa maitoa ja mettä, ja he syövät ja tulevat ravituiksi ja lihaviksi; mutta he kääntyvät muiden jumalien puoleen ja palvelevat niitä ja pitävät minua pilkkanaan ja rikkovat minun liittoni.'),
(1674670,58,5,31,21,'Ja kun suuret onnettomuudet ja ahdistukset kohtaavat heitä, niin tämä laulu on oleva todistajana heitä vastaan, eikä se ole unhottuva heidän jälkeläistensä suusta. Sillä minä tiedän heidän aikeensa, joita he hautovat jo ennenkuin minä olen vienyt heidät siihen maahan, josta minä olen valan vannonut."'),
(1674671,58,5,31,22,'Ja Mooses kirjoitti tämän laulun sinä päivänä ja opetti sen israelilaisille.'),
(1674672,58,5,31,23,'Ja hän asetti virkaan Joosuan, Nuunin pojan, ja sanoi: "Ole luja ja rohkea, sillä sinä viet israelilaiset siihen maahan, jonka minä valalla vannoen olen heille luvannut, ja minä olen sinun kanssasi".'),
(1674673,58,5,31,24,'Ja kun Mooses oli kirjoittanut kirjaan tämän lain sanat, alusta loppuun asti,'),
(1674674,58,5,31,25,'käski hän leeviläisiä, jotka kantoivat Herran liitonarkkia, sanoen:'),
(1674675,58,5,31,26,'"Ottakaa tämä lain kirja ja pankaa se Herran, teidän Jumalanne, liitonarkin sivulle, olemaan siellä todistajana sinua vastaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674676,58,5,31,27,'Sillä minä tunnen sinun tottelemattomuutesi ja uppiniskaisuutesi. Katso, minun vielä eläessäni teidän kanssanne te olette niskoitelleet Herraa vastaan; saati sitten minun kuoltuani!'),
(1674677,58,5,31,28,'Kootkaa minun luokseni kaikki sukukuntienne vanhimmat sekä päällysmiehenne, että minä heidän kuultensa puhuisin nämä sanat ja ottaisin taivaan ja maan todistajiksi heitä vastaan.'),
(1674678,58,5,31,29,'Sillä minä tiedän, että te minun kuoltuani vaellatte kelvottomasti ja poikkeatte siltä tieltä, jota minä käskin teidän vaeltaa. Sentähden on onnettomuus kohtaava teitä aikojen lopulla, kun te teette sitä, mikä on pahaa Herran silmissä, ja vihoitatte hänet kättenne teoilla."'),
(1674679,58,5,31,30,'Ja Mooses lausui koko Israelin seurakunnan kuullen tämän virren sanat, alusta loppuun asti:'),
(1674680,58,5,32,1,'"Kuunnelkaa, te taivaat, kun minä puhun, ja kuulkoon maa minun suuni sanat!'),
(1674681,58,5,32,2,'Sateena pisaroikoon minun opetukseni, kasteena valukoon puheeni niinkuin vihma vihannalle, niinkuin sadekuuro ruohikolle.'),
(1674682,58,5,32,3,'Sillä minä julistan Herran nimeä; antakaa kunnia meidän Jumalallemme.'),
(1674683,58,5,32,4,'Hän on kallio; täydelliset ovat hänen tekonsa, sillä kaikki hänen tiensä ovat oikeat. Uskollinen Jumala ja ilman vääryyttä, vanhurskas ja vakaa hän on.'),
(1674684,58,5,32,5,'Heidän menonsa oli paha häntä kohtaan, he eivät olleet hänen lapsiansa, vaan häpeäpilkku - tuo nurja ja kiero sukupolvi!'),
(1674685,58,5,32,6,'Niinkö sinä maksat Herralle, sinä houkka ja tyhmä kansa? Eikö hän ole sinun isäsi, joka sinut loi? Hän sinut teki ja valmisti.'),
(1674686,58,5,32,7,'Muistele muinaisia päiviä, ajattele menneiden sukupolvien vuosia. Kysy isältäsi, niin hän sen sinulle ilmoittaa, vanhimmiltasi, niin he sen sinulle sanovat.'),
(1674687,58,5,32,8,'Kun Korkein jakoi perinnöt kansoille, kun hän erotteli ihmisten lapset, silloin hän määräsi kansojen rajat israelilaisten luvun mukaan.'),
(1674688,58,5,32,9,'Sillä Herran kansa on hänen osuutensa, Jaakob on hänen perintöosansa.'),
(1674689,58,5,32,10,'Erämaasta hän löysi hänet, autiosta, ulvovasta korvesta; hän otti hänet suojaansa ja hoitoonsa, varjeli häntä kuin silmäteräänsä.'),
(1674690,58,5,32,11,'Niinkuin kotka kiihoittaa pesuettaan lentoon ja liitelee poikastensa suojana, niin hän levitti siipensä, otti hänet ja kantoi häntä sulillansa.'),
(1674691,58,5,32,12,'Herra yksin johdatti häntä, eikä hänen kanssansa ollut ketään vierasta jumalaa.'),
(1674692,58,5,32,13,'Hän kuljetti hänet maan kukkuloiden yli ja ruokki häntä pellon antimilla; hän antoi hänen imeä hunajaa kalliosta ja öljyä kovasta kivestä.'),
(1674693,58,5,32,14,'Hän antoi voita lehmistä ja maitoa lampaista sekä karitsain ja oinasten rasvaa, Baasanin härkiä ja kauriita ja parasta vehnän ydintä; ja sinä sait juoda rypäleen verta, tulista viiniä.'),
(1674694,58,5,32,15,'Ja Jesurun lihoi ja alkoi potkia, sinä tulit lihavaksi, paksuksi ja aloit äksyillä. Niin hän hylkäsi Jumalan, joka oli tehnyt hänet, ja halveksui pelastuksensa kalliota.'),
(1674695,58,5,32,16,'He herättivät hänen kiivautensa vierailla jumalillaan, he vihoittivat hänet kauhistuksillansa.'),
(1674696,58,5,32,17,'He uhrasivat riivaajille, epäjumalille, jumalille, joita he eivät tunteneet, uusille, äsken tulleille, joista teidän isänne eivät tienneet.'),
(1674697,58,5,32,18,'Kalliota, joka sinut synnytti, sinä et muistanut; sinä unhotit Jumalan, joka sinulle elämän antoi.'),
(1674698,58,5,32,19,'Herra näki sen ja hylkäsi heidät, sillä hän vihastui poikiinsa ja tyttäriinsä.'),
(1674699,58,5,32,20,'Hän sanoi: ''Minä peitän heiltä kasvoni, minä katson, mikä heidän loppunsa on; sillä he ovat nurja suku, lapsia, joissa ei ole uskollisuutta.'),
(1674700,58,5,32,21,'He ovat herättäneet minun kiivauteni jumalilla, jotka eivät jumalia ole, ovat vihoittaneet minut turhilla jumalillansa; niin minäkin herätän heidän kiivautensa kansalla, joka ei ole kansa, vihoitan heidät houkalla pakanakansalla.'),
(1674701,58,5,32,22,'Sillä minun vihani tuli on syttynyt, ja se leimuaa tuonelan syvyyksiin saakka; se kuluttaa maan kasvuinensa ja polttaa vuorten perustukset.'),
(1674702,58,5,32,23,'Minä kasaan onnettomuuksia heidän päällensä, kaikki nuoleni minä heihin ammun.'),
(1674703,58,5,32,24,'He nääntyvät nälkään ja menehtyvät ruttoon, kulkutautien poltteeseen; minä lähetän heidän kimppuunsa petojen hampaat ja tomussa matelevaisten myrkyn.'),
(1674704,58,5,32,25,'Ulkona surmaa miekka ja sisällä kauhu sekä nuorukaisen että neitosen, sekä imeväisen että harmaapään.'),
(1674705,58,5,32,26,'Minä sanoisin: ''Minä puhallan heidät pois, hävitän heidän muistonsa ihmisten seasta'','),
(1674706,58,5,32,27,'jollen varoisi, että vihollinen tuottaisi minulle mielipahaa, että heidän vastustajansa selittäisivät sen väärin, että he sanoisivat: ''Meidän kätemme oli korotettu, eikä Herra ole tästä kaikesta mitään tehnyt''.'),
(1674707,58,5,32,28,'Sillä he ovat neuvoton kansa, eikä heissä ole ymmärrystä.'),
(1674708,58,5,32,29,'Jos he viisaita olisivat, niin he käsittäisivät tämän, he ymmärtäisivät, mikä heidän loppunsa on.'),
(1674709,58,5,32,30,'Kuinka yksi ajaisi tuhatta takaa, kuinka kaksi ajaisi pakoon kymmenentuhatta, jollei heidän kallionsa olisi heitä myynyt ja Herra luovuttanut heitä!'),
(1674710,58,5,32,31,'Sillä heidän kallionsa ei ole niinkuin meidän kalliomme; niin vihollisemmekin päättelevät.'),
(1674711,58,5,32,32,'Sillä Sodoman viinipuita on heidän viinipuunsa, se on kotoisin Gomorran viinitarhoista; heidän rypäleensä ovat myrkkyrypäleitä, heidän viiniterttujensa maku on karvas.'),
(1674712,58,5,32,33,'Heidän viininsä on lohikäärmeitten kähyä, kyykäärmeitten kauheata myrkkyä.'),
(1674713,58,5,32,34,'Eikö sitä ole talletettuna minun takanani, sinetillä lukittuna minun aitoissani?'),
(1674714,58,5,32,35,'Minun on kosto ja rankaiseminen, säästetty siksi ajaksi, jolloin heidän jalkansa horjuu. Sillä heidän onnettomuutensa päivä on lähellä, ja mikä heitä odottaa, se tulee rientäen.'),
(1674715,58,5,32,36,'Sillä Herra hankkii oikeuden kansallensa ja armahtaa palvelijoitansa, koska hän näkee, että heidän voimansa on poissa ja että kaikki tyynni on lopussa.'),
(1674716,58,5,32,37,'Silloin hän kysyy: ''Missä ovat nyt niiden jumalat, missä kallio, johon he turvasivat,'),
(1674717,58,5,32,38,'missä ne, jotka söivät heidän teurasuhriensa rasvan ja joivat heidän juomauhriensa viinin?'' Nouskoot ne auttamaan teitä, olkoot ne teidän suojananne.'),
(1674718,58,5,32,39,'Katsokaa nyt, että minä, minä olen, eikä yhtäkään jumalaa ole minun rinnallani. Minä kuoletan ja minä teen eläväksi, minä lyön ja minä parannan; eikä ole sitä, joka pelastaisi minun käsistäni.'),
(1674719,58,5,32,40,'Minä nostan käteni taivasta kohti ja sanon: Niin totta kuin minä elän iankaikkisesti, kun minä teroitan miekkani salaman,'),
(1674720,58,5,32,41,'kun minun käteni ryhtyy tuomiota pitämään, niin minä kostan vastustajilleni ja maksan vihamiehilleni. Minä annan nuolteni juopua verestä -'),
(1674721,58,5,32,42,'ja minun miekkani syö lihaa - surmattujen ja vangittujen verestä, vihollispäällikköjen päistä.'),
(1674722,58,5,32,43,'Riemuiten ylistäkää, te pakanakansat, hänen kansaansa, sillä hän kostaa palvelijoittensa veren; hän antaa koston kohdata vastustajiansa ja toimittaa sovituksen maallensa, kansallensa."'),
(1674723,58,5,32,44,'Ja Mooses tuli ja lausui kaikki tämän virren sanat kansan kuullen, hän itse ja Joosua, Nuunin poika.'),
(1674724,58,5,32,45,'Ja kun Mooses oli puhunut loppuun kaikki nämä sanat koko Israelille,'),
(1674725,58,5,32,46,'sanoi hän heille: "Painakaa sydämiinne kaikki ne sanat, jotka minä tänä päivänä teen todistajiksi teitä vastaan, niin että käskette lapsianne tarkoin täyttämään kaikki tämän lain sanat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674726,58,5,32,47,'Sillä ei ole se turha sana, joka ei koskisi teitä, vaan siinä on teidän elämänne; ja sen sanan varassa te elätte kauan siinä maassa, johon te menette Jordanin yli, ottamaan sen omaksenne."'),
(1674727,58,5,32,48,'Ja Herra puhui Moosekselle sinä samana päivänä sanoen:'),
(1674728,58,5,32,49,'"Nouse tänne Abarimin vuoristoon, Nebon vuorelle, joka on Mooabin maassa vastapäätä Jerikoa, ja katsele Kanaanin maata, jonka minä annan israelilaisten omaksi.'),
(1674729,58,5,32,50,'Ja sinä kuolet sillä vuorella, jolle nouset, ja tulet otetuksi heimosi tykö, niinkuin sinun veljesi Aaron kuoli Hoorin vuorella ja tuli otetuksi heimonsa tykö,'),
(1674730,58,5,32,51,'koska te lankesitte uskottomuuteen minua kohtaan israelilaisten keskellä Meriban veden ääressä Kaadeksessa, Siinin erämaassa, kun ette pitäneet minua pyhänä israelilaisten keskellä.'),
(1674731,58,5,32,52,'Niin, sinä saat katsella sitä maata matkan päästä, mutta sinne sinä et pääse, siihen maahan, jonka minä annan israelilaisille."'),
(1674732,58,5,33,1,'Tämä on se siunaus, jolla Jumalan mies Mooses siunasi israelilaiset ennen kuolemaansa;'),
(1674733,58,5,33,2,'hän sanoi: "Herra tuli Siinailta, Seiristä hän nousi loistaen heille; hän ilmestyi kirkkaudessa Paaranin vuoristosta, hän tuli kymmentuhantisesta pyhien joukosta; hänen oikealla puolellansa liekitsi lain tuli.'),
(1674734,58,5,33,3,'Hän rakastaa kansoja; kaikki niiden pyhät ovat sinun kädessäsi. He asettuvat sinun jalkojesi juureen, ottavat oppia sinun sanoistasi.'),
(1674735,58,5,33,4,'Mooses antoi meille lain, perintönä Jaakobin seurakunnalle.'),
(1674736,58,5,33,5,'Ja Herra tuli kuninkaaksi Jesurunissa, kun kansan päämiehet kokoontuivat, kaikki Israelin sukukunnat.'),
(1674737,58,5,33,6,'Ruuben eläköön, älköön hän kuolko; mutta vähäiseksi jääköön hänen miestensä joukko."'),
(1674738,58,5,33,7,'Ja tämän hän sanoi Juudasta: "Kuule, Herra, Juudan huuto ja tuo hänet kansansa luo. Hän sen puolesta käsillänsä taisteli; ole sinä apuna hänen vihollisiansa vastaan."'),
(1674739,58,5,33,8,'Ja Leevistä hän sanoi: "Sinun tummimisi ja uurimisi olkoot sinun hurskaasi omat, sen miehen, jota sinä Massassa koettelit, jonka kanssa sinä riitelit Meriban veden luona,'),
(1674740,58,5,33,9,'joka sanoi isästänsä ja äidistänsä: ''Minä en heitä nähnyt'', ja joka ei tunnustanut veljiään omiksensa eikä tuntenut omia lapsiansa. Sillä he noudattivat sinun sanaasi ja pysyivät sinun liitossasi.'),
(1674741,58,5,33,10,'He opettavat sinun säädöksiäsi Jaakobille ja Israelille sinun lakiasi; he panevat suitsutusta sinun eteesi ja kokonaisuhreja sinun alttarillesi.'),
(1674742,58,5,33,11,'Siunaa, Herra, hänen voimansa, ja olkoon hänen kättensä työ sinulle otollinen. Ruhjo hänen vastustajiensa lanteet ja hänen vihamiehensä niin, että eivät enää nouse."'),
(1674743,58,5,33,12,'Benjaminista hän sanoi: "Herran rakkaana hän asuu hänen turvissansa; Herra suojelee häntä aina ja asuu hänen kukkulainsa välissä".'),
(1674744,58,5,33,13,'Ja Joosefista hän sanoi: "Herra siunatkoon hänen maansa kalleimmalla, kasteella, joka tulee taivaasta, kalleimmalla, mikä tulee syvyydestä alhaalta,'),
(1674745,58,5,33,14,'kalleimmalla, minkä aurinko antaa, kalleimmalla, minkä kuun vaiheet tuottavat,'),
(1674746,58,5,33,15,'kalleimmalla, mikä tulee ikuisten vuorien huipuilta, kalleimmalla, mikä tulee ikikukkuloilta,'),
(1674747,58,5,33,16,'kalleimmalla, minkä maa kasvaa, ja kaikella, mitä siinä on, ja mielisuosiollaan, hän, joka pensaassa asui. Ne laskeutukoot Joosefin pään päälle, hänen päälaellensa, hänen, joka on ruhtinas veljiensä joukossa.'),
(1674748,58,5,33,17,'Uljas on hänen härkiensä esikoinen, sen sarvet ovat kuin villihärän sarvet; niillä se puskee kumoon kansat, kaikki tyynni maan ääriin saakka. Sellaisia ovat Efraimin kymmenet tuhannet, sellaisia Manassen tuhannet."'),
(1674749,58,5,33,18,'Ja Sebulonista hän sanoi: "Iloitse, Sebulon, kun liikkeelle lähdet, ja sinä, Isaskar, majoissasi.'),
(1674750,58,5,33,19,'He kutsuvat kansoja vuorellensa, siellä he uhraavat oikeita uhreja. Sillä he imevät merten rikkauden ja hiekkaan kätketyt aarteet."'),
(1674751,58,5,33,20,'Ja Gaadista hän sanoi: "Kiitetty olkoon hän, joka on niin laajentanut Gaadin. Niinkuin naarasleijona hän asettuu leposijaansa ja raatelee sekä käsivarren että päälaen.'),
(1674752,58,5,33,21,'Hän katsoi itsellensä parhaan osan maata, sillä siellä oli hänelle johtajan osa varattu. Mutta hän tuli kansan päämiesten kanssa, pani toimeen Herran vanhurskauden ja hänen tuomionsa yhdessä muun Israelin kanssa."'),
(1674753,58,5,33,22,'Ja Daanista hän sanoi: "Daan on nuori leijona, joka syöksyy esiin Baasanista".'),
(1674754,58,5,33,23,'Ja Naftalista hän sanoi: "Naftali on kylläinen mielisuosiosta ja täynnä Herran siunausta. Lännen ja etelän hän omaksensa ottakoon."'),
(1674755,58,5,33,24,'Ja Asserista hän sanoi: "Siunattu olkoon Asser poikien joukossa. Olkoon hän veljiensä lemmikki, ja kastakoon hän jalkansa öljyyn.'),
(1674756,58,5,33,25,'Rautaa ja vaskea olkoot sinun salpasi; ja niinkuin sinun päiväsi, niin olkoon sinun voimasikin.'),
(1674757,58,5,33,26,'Ei kukaan ole niinkuin Jesurunin Jumala, joka kulkee taivasten yli sinun apunasi ja korkeudessaan pilvien päällitse.'),
(1674758,58,5,33,27,'Sinun turvasi on ikiaikojen Jumala, sinua kannattavat iankaikkiset käsivarret. Hän karkoitti viholliset sinun tieltäsi, hän sanoi: ''Hävitä!'''),
(1674759,58,5,33,28,'Näin Israel asuu turvassa, Jaakobin lähde erillänsä viljan ja viinin maassa, jonka taivaskin tiukkuu kastetta.'),
(1674760,58,5,33,29,'Autuas olet sinä, Israel; kuka on sinun vertaisesi! Sinä olet kansa, jota Herra auttaa, hän, joka on sinun kilpesi ja suojasi, sinun miekkasi ja korkeutesi. Vihollisesi mielistelevät sinua, ja sinä astut heidän kukkuloillansa."'),
(1674761,58,5,34,1,'Ja Mooses nousi Mooabin arolta Nebon vuorelle, Pisgan huipulle, vastapäätä Jerikoa. Ja Herra näytti hänelle koko maan: Gileadin Daaniin asti,'),
(1674762,58,5,34,2,'koko Naftalin, Efraimin ja Manassen maan, koko Juudan maan aina Länsimereen asti,'),
(1674763,58,5,34,3,'Etelämaan sekä Lakeuden, se on Jerikon, Palmukaupungin, laakson, aina Sooariin asti.'),
(1674764,58,5,34,4,'Ja Herra sanoi hänelle: "Tämä on se maa, jonka minä valalla vannoen olen luvannut Aabrahamille, Iisakille ja Jaakobille, sanoen: ''Sinun jälkeläisillesi minä annan sen''. Minä olen nyt antanut sinun omin silmin nähdä sen, mutta sinne sinä et mene."'),
(1674765,58,5,34,5,'Ja Herran palvelija Mooses kuoli siellä Mooabin maassa, Herran sanan mukaan.'),
(1674766,58,5,34,6,'Ja hän hautasi hänet laaksoon Mooabin maahan, vastapäätä Beet-Peoria, mutta ei kukaan ole saanut tietää hänen hautaansa tähän päivään asti.'),
(1674767,58,5,34,7,'Ja Mooses oli kuollessaan sadan kahdenkymmenen vuoden vanha, mutta hänen silmänsä eivät olleet hämärtyneet, eikä hänen elinvoimansa ollut kadonnut.'),
(1674768,58,5,34,8,'Ja israelilaiset itkivät Moosesta Mooabin arolla kolmekymmentä päivää; sitten päättyi Mooseksen muistoksi vietetty itku- ja suruaika.'),
(1674769,58,5,34,9,'Ja Joosua, Nuunin poika, oli täynnä viisauden henkeä, sillä Mooses oli pannut kätensä hänen päällensä; ja israelilaiset tottelivat häntä ja tekivät, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1674770,58,5,34,10,'Mutta Israelissa ei enää noussut yhtäkään sellaista profeettaa kuin Mooses, jonka kanssa Herra seurusteli kasvoista kasvoihin;'),
(1674771,58,5,34,11,'ei ketään, joka olisi tehnyt sellaisia tunnustekoja ja ihmeitä, kuin hän Herran lähettämänä teki Egyptin maassa faraolle ja kaikille hänen palvelijoillensa, koko hänen maallensa;'),
(1674772,58,6,1,1,'Herran palvelijan Mooseksen kuoltua sanoi Herra Joosualle, Nuunin pojalle, Mooseksen palvelijalle, näin:'),
(1674773,58,6,1,2,'"Minun palvelijani Mooses on kuollut; nouse siis ja mene tämän Jordanin yli, sinä ja kaikki tämä kansa, siihen maahan, jonka minä annan heille, israelilaisille.'),
(1674774,58,6,1,3,'Jokaisen paikan, johon te jalkanne astutte, minä annan teille, niinkuin olen Moosekselle puhunut.'),
(1674775,58,6,1,4,'Maa erämaasta ja tuolta Libanonista aina suureen virtaan, Eufrat-virtaan, saakka - koko heettiläisten maa - ja aina Suureen mereen asti, auringonlaskuun päin, on oleva teidän aluettanne.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674776,58,6,1,5,'Ei kukaan kestä sinun edessäsi kaikkena elinaikanasi. Niinkuin minä olin Mooseksen kanssa, niin minä olen sinunkin kanssasi; minä en jätä sinua enkä hylkää sinua.'),
(1674777,58,6,1,6,'Ole luja ja rohkea; sillä sinä jaat tälle kansalle perinnöksi sen maan, jonka minä heidän isillensä vannotulla valalla olen luvannut antaa heille.'),
(1674778,58,6,1,7,'Ole vain luja ja aivan rohkea ja noudata tarkoin kaikessa sitä lakia, jonka minun palvelijani Mooses on sinulle antanut; älä poikkea siitä oikealle äläkä vasemmalle, että menestyisit, missä ikinä kuljetkin.'),
(1674779,58,6,1,8,'Älköön tämä lain kirja sinun suustasi poistuko, vaan tutkiskele sitä päivät ja yöt, että tarkoin noudattaisit kaikkea, mitä siihen on kirjoitettu, sillä silloin sinä onnistut teilläsi ja silloin sinä menestyt.'),
(1674780,58,6,1,9,'Olenhan minä sinua käskenyt: Ole luja ja rohkea; älä säikähdy äläkä arkaile, sillä Herra, sinun Jumalasi, on sinun kanssasi, missä ikinä kuljetkin."'),
(1674781,58,6,1,10,'Silloin Joosua käski kansan päällysmiehiä sanoen:'),
(1674782,58,6,1,11,'"Kulkekaa halki leirin ja käskekää kansaa sanoen: ''Valmistakaa itsellenne evästä, sillä kolmen päivän kuluttua te kuljette tämän Jordanin yli mennäksenne ottamaan omaksenne sen maan, jonka Herra, teidän Jumalanne, teidän omaksenne antaa''".'),
(1674783,58,6,1,12,'Mutta ruubenilaisille, gaadilaisille ja toiselle puolelle Manassen sukukuntaa Joosua sanoi näin:'),
(1674784,58,6,1,13,'"Muistakaa sitä käskyä, jonka Herran palvelija Mooses teille antoi sanoen: ''Herra, teidän Jumalanne, suo teidän päästä rauhaan ja antaa teille tämän maan''.'),
(1674785,58,6,1,14,'Vaimonne, lapsenne ja karjanne jääkööt siihen maahan, jonka Mooses antoi teille tältä puolelta Jordanin. Mutta teidän itsenne, kaikkien sotaurhojen, on taisteluun valmiina lähdettävä veljienne etunenässä ja autettava heitä,'),
(1674786,58,6,1,15,'kunnes Herra suo teidän veljienne päästä rauhaan niinkuin teidänkin, ja hekin ottavat omakseen sen maan, jonka Herra, teidän Jumalanne, heille antaa. Sitten saatte palata takaisin siihen maahan, joka on teidän omanne, ja ottaa omaksenne sen maan, jonka Herran palvelija Mooses antoi teille tältä puolelta Jordanin, auringonnousun puolelta."'),
(1674787,58,6,1,16,'Niin he vastasivat Joosualle sanoen: "Kaiken, minkä olet meidän käskenyt tehdä, me teemme, ja mihin ikinä meidät lähetät, sinne me menemme.'),
(1674788,58,6,1,17,'Niinkuin me olemme kaikessa totelleet Moosesta, niin me tottelemme sinuakin. Olkoon vain Herra, sinun Jumalasi, sinun kanssasi, niinkuin hän oli Mooseksen kanssa.'),
(1674789,58,6,1,18,'Jokainen, joka niskoittelee sinun käskyjäsi vastaan eikä tottele sanojasi kaikessa, mitä hänelle käsket, surmattakoon. Ole vain luja ja rohkea."'),
(1674790,58,6,2,1,'Niin Joosua, Nuunin poika, lähetti salaa Sittimistä kaksi vakoojaa, sanoen: "Menkää, katselkaa maata ja Jerikoa". Ja he menivät ja tulivat Raahab nimisen porton taloon ja laskeutuivat siellä levolle.'),
(1674791,58,6,2,2,'Mutta Jerikon kuninkaalle kerrottiin näin: "Katso, tänne on yöllä tullut miehiä israelilaisten joukosta vakoilemaan maata".'),
(1674792,58,6,2,3,'Silloin Jerikon kuningas lähetti sanan Raahabille: "Tuo ulos ne miehet, jotka ovat tulleet luoksesi, jotka ovat tulleet sinun taloosi, sillä he ovat tulleet koko maata vakoilemaan".'),
(1674793,58,6,2,4,'Mutta vaimo otti molemmat miehet, piilotti heidät ja sanoi: "Miehet kyllä tulivat minun luokseni, mutta en tiennyt, mistä he olivat.'),
(1674794,58,6,2,5,'Ja kun kaupungin portti pimeän tullen oli suljettava, niin miehet lähtivät ulos. En tiedä, minne miehet menivät; ajakaa nopeasti heitä takaa, niin te saavutatte heidät."'),
(1674795,58,6,2,6,'Mutta hän oli vienyt heidät katolle ja kätkenyt heidät pellavanvarsien alle, joita oli asetellut katolle.'),
(1674796,58,6,2,7,'Niin miehet ajoivat heitä takaa Jordanin tietä kahlauspaikoille saakka, ja kaupungin portti suljettiin, niin pian kuin heidän takaa-ajajansa olivat menneet.'),
(1674797,58,6,2,8,'Mutta ennenkuin he olivat laskeutuneet levolle, nousi hän heidän luoksensa katolle ja sanoi miehille:'),
(1674798,58,6,2,9,'"Minä tiedän, että Herra antaa teille tämän maan ja että kauhu teitä kohtaan on vallannut meidät ja että kaikki maan asukkaat menehtyvät pelkoon teidän edessänne.'),
(1674799,58,6,2,10,'Sillä me olemme kuulleet, kuinka Herra kuivasi Kaislameren vedet teidän tieltänne, kun lähditte Egyptistä, ja mitä te teitte niille kahdelle amorilaisten kuninkaalle tuolla puolella Jordanin, Siihonille ja Oogille, jotka te vihitte tuhon omiksi.'),
(1674800,58,6,2,11,'Kun me sen kuulimme, raukesi meidän sydämemme, eikä kenessäkään ole enää rohkeutta asettua teitä vastaan; sillä Herra, teidän Jumalanne, on Jumala ylhäällä taivaassa ja alhaalla maan päällä.'),
(1674801,58,6,2,12,'Niin vannokaa nyt minulle Herran kautta, että niinkuin minä olen tehnyt teille laupeuden, tekin teette laupeuden minun isäni perheelle; ja antakaa minulle varma merkki siitä,'),
(1674802,58,6,2,13,'että jätätte eloon minun isäni, äitini, veljeni, sisareni ja kaikki heidän omaisensa ja pelastatte meidät kuolemasta."'),
(1674803,58,6,2,14,'Niin miehet sanoivat hänelle: "Me vastaamme hengellämme teidän hengestänne, jos vain ette ilmaise tätä meidän asiaamme. Kun Herra antaa meille tämän maan, niin me osoitamme sinulle laupeutta ja uskollisuutta."'),
(1674804,58,6,2,15,'Ja hän laski heidät köydellä alas ikkunasta, sillä hänen talonsa oli kiinni kaupungin muurissa, niin että hän asui muurissa kiinni.'),
(1674805,58,6,2,16,'Ja hän sanoi heille: "Menkää vuoristoon, etteivät takaa-ajajat kohtaisi teitä, ja olkaa siellä piilossa kolme päivää, kunnes takaa-ajajat ovat palanneet; sitten voitte lähteä matkaanne".'),
(1674806,58,6,2,17,'Niin miehet sanoivat hänelle: "Me olemme vapaat siitä valasta, jonka meille vannotit,'),
(1674807,58,6,2,18,'jollet sinä, kun me tulemme tähän maahan, sido tätä punaista nauhaa siihen ikkunaan, josta laskit meidät alas, ja kokoa isääsi, äitiäsi, veljiäsi ja isäsi koko perhettä luoksesi taloon.'),
(1674808,58,6,2,19,'Ja kuka vain menee talosi ovesta ulos, sen veri tulkoon hänen oman päänsä päälle, ja me olemme vastuusta vapaat; mutta kuka vain on sinun kanssasi talossa, sen veri tulkoon meidän päämme päälle, jos kenen käsi sattuu häneen.'),
(1674809,58,6,2,20,'Mutta jos sinä ilmaiset tämän meidän asiamme, niin me olemme vapaat valasta, jonka meillä vannotit."'),
(1674810,58,6,2,21,'Ja hän sanoi: "Olkoon, niinkuin sanotte", ja päästi heidät menemään, ja he lähtivät. Ja hän sitoi sen punaisen nauhan ikkunaan.'),
(1674811,58,6,2,22,'Niin he lähtivät ja tulivat vuoristoon ja viipyivät siellä kolme päivää, kunnes takaa-ajajat olivat palanneet. Ja takaa-ajajat etsivät heitä kaikkialta tien varrelta, mutta eivät löytäneet.'),
(1674812,58,6,2,23,'Sitten nuo kaksi miestä kääntyivät paluumatkalle. He laskeutuivat alas vuoristosta, menivät virran yli ja tulivat Joosuan, Nuunin pojan, luo ja kertoivat hänelle kaikki, mitä heille oli tapahtunut.'),
(1674813,58,6,2,24,'Ja he sanoivat Joosualle: "Herra on antanut koko maan meidän käsiimme, ja kaikki maan asukkaat menehtyvät pelkoon meidän edessämme".'),
(1674814,58,6,3,1,'Niin Joosua nousi varhain seuraavana aamuna, ja he lähtivät liikkeelle Sittimistä ja tulivat Jordanille, hän ja kaikki israelilaiset; ja he olivat siellä yötä, ennenkuin menivät virran yli.'),
(1674815,58,6,3,2,'Mutta kolmen päivän kuluttua kulkivat päällysmiehet halki leirin'),
(1674816,58,6,3,3,'ja käskivät kansaa sanoen: "Kun te näette Herran, teidän Jumalanne, liitonarkin ja leeviläiset papit sitä kantamassa, niin lähtekää tekin liikkeelle paikoiltanne ja seuratkaa sitä.'),
(1674817,58,6,3,4,'Kuitenkin olkoon noin kahdentuhannen kyynärän välimatka teidän ja sen välillä - älkää menkö sitä lähelle - että tietäisitte tien, jota teidän on käytävä, sillä te ette ole ennen kulkeneet sitä tietä."'),
(1674818,58,6,3,5,'Ja Joosua sanoi kansalle: "Pyhittäytykää, sillä huomenna Herra on tekevä ihmeellisiä tekoja teidän keskuudessanne".'),
(1674819,58,6,3,6,'Mutta papeille Joosua sanoi näin: "Ottakaa liitonarkki ja kulkekaa kansan edellä". Niin he ottivat liitonarkin ja kulkivat kansan edellä.'),
(1674820,58,6,3,7,'Silloin Herra sanoi Joosualle: "Tästä päivästä alkaen minä teen sinut suureksi koko Israelin silmissä, jotta he tietäisivät, että niinkuin minä olin Mooseksen kanssa, niin minä olen sinunkin kanssasi.'),
(1674821,58,6,3,8,'Käske pappeja, jotka kantavat liitonarkkia, ja sano: ''Kun tulette Jordanin veden ääreen, niin pysähtykää Jordanin rantaan''."'),
(1674822,58,6,3,9,'Sitten Joosua sanoi israelilaisille: "Tulkaa tänne ja kuulkaa Herran, teidän Jumalanne, sanat".'),
(1674823,58,6,3,10,'Ja Joosua sanoi: "Tästä saatte tietää, että elävä Jumala on teidän keskellänne ja karkoittaa teidän tieltänne kanaanilaiset, heettiläiset, hivviläiset, perissiläiset, girgasilaiset, amorilaiset ja jebusilaiset:'),
(1674824,58,6,3,11,'katso, kaiken maan Herran liitonarkki kulkee teidän edellänne Jordanin poikki.'),
(1674825,58,6,3,12,'Ottakaa siis kaksitoista miestä Israelin sukukunnista, kustakin sukukunnasta yksi mies.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674826,58,6,3,13,'Niin pian kuin papit, jotka kantavat Herran, kaiken maan Herran, liitonarkkia, laskevat jalkansa Jordanin veteen, katkeaa Jordanin vesi, ylhäältä päin virtaava vesi, juoksussaan ja pysähtyy roukkioksi."'),
(1674827,58,6,3,14,'Kun kansa sitten lähti liikkeelle teltoistaan mennäksensä Jordanin poikki, liitonarkkia kantavien pappien käydessä kansan edellä,'),
(1674828,58,6,3,15,'ja niin pian kuin liitonarkin kantajat tulivat Jordanille ja liitonarkkia kantavien pappien jalat painuivat rantaveteen, niin vaikka Jordan koko elonleikkuuajan on tulvillaan yli kaikkien äyräidensä,'),
(1674829,58,6,3,16,'pysähtyi ylhäältä päin virtaava vesi ja seisoi yhtenä roukkiona hyvin kaukana Aadamin luona, sen kaupungin, joka on Saaretanin vieressä; ja se vesi, joka virtasi alaspäin Aromereen, Suolamereen, hävisi kokonaan. Niin kansa kulki virran yli Jerikon kohdalta.'),
(1674830,58,6,3,17,'Ja Herran liitonarkkia kantavat papit seisoivat alallaan kuivalla pohjalla keskellä Jordania, kaiken Israelin kulkiessa kuivaa myöten, kunnes koko kansa oli ehtinyt kulkea Jordanin yli.'),
(1674831,58,6,4,1,'Ja kun koko kansa oli ehtinyt kulkea Jordanin yli, sanoi Herra Joosualle näin:'),
(1674832,58,6,4,2,'"Ottakaa kansasta kaksitoista miestä, kustakin sukukunnasta yksi mies,'),
(1674833,58,6,4,3,'ja käskekää heitä sanoen: ''Ottakaa itsellenne tästä, keskeltä Jordania, siltä kohdalta, missä papit seisovat alallaan, kaksitoista kiveä ja viekää ne mukananne ja asettakaa ne siihen paikkaan, mihin jäätte ensi yöksi''".'),
(1674834,58,6,4,4,'Niin Joosua kutsui ne kaksitoista miestä, jotka hän oli määrännyt otettaviksi israelilaisista, yhden miehen kustakin sukukunnasta,'),
(1674835,58,6,4,5,'ja Joosua sanoi heille: "Menkää Herran, Jumalanne, arkin eteen keskelle Jordania, ja nostakoon kukin kiven olalleen israelilaisten sukukuntien luvun mukaan,'),
(1674836,58,6,4,6,'että ne olisivat merkkinä teidän keskellänne. Kun lapsenne vastaisuudessa kysyvät ja sanovat: ''Mitä nämä kivet merkitsevät?'''),
(1674837,58,6,4,7,'niin vastatkaa heille: ''Sitä, että Jordanin vesi katkesi juoksussaan Herran liitonarkin edessä, kun se kulki Jordanin poikki; Jordanin vesi katkesi juoksussaan, ja siitä ovat nämä kivet muistona israelilaisille ikuisiksi ajoiksi''."'),
(1674838,58,6,4,8,'Ja israelilaiset tekivät, niinkuin Joosua oli käskenyt, ja ottivat israelilaisten sukukuntien luvun mukaan kaksitoista kiveä keskeltä Jordania, niinkuin Herra oli puhunut Joosualle, ja veivät ne mukanaan yöpaikkaan ja asettivat ne sinne.'),
(1674839,58,6,4,9,'Ja Joosua pystytti kaksitoista kiveä keskelle Jordania sille kohdalle, jossa liitonarkkia kantavat papit seisoivat; ja ne ovat siellä vielä tänäkin päivänä.'),
(1674840,58,6,4,10,'Ja papit, jotka kantoivat arkkia, seisoivat keskellä Jordania, kunnes oli suoritettu kaikki, mitä Herra oli käskenyt Joosuan puhua kansalle, kaikki tyynni, mistä Mooses oli Joosualle käskyn antanut, ja kansa kulki nopeasti virran yli.'),
(1674841,58,6,4,11,'Ja kun koko kansa oli ehtinyt kulkea virran yli, menivät Herran arkki ja papit yli, kansan eteen.'),
(1674842,58,6,4,12,'Ja ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa kulkivat taisteluun valmiina israelilaisten etunenässä, niinkuin Mooses oli heille puhunut.'),
(1674843,58,6,4,13,'Noin nelikymmentuhantinen sotaan varustettu joukko heitä kulki Herran edellä taisteluun Jerikon arolle.'),
(1674844,58,6,4,14,'Sinä päivänä Herra teki Joosuan suureksi koko Israelin silmissä, ja he pelkäsivät häntä kaikkena hänen elinaikanansa, niinkuin olivat Moosesta peljänneet.'),
(1674845,58,6,4,15,'Ja Herra puhui Joosualle sanoen:'),
(1674846,58,6,4,16,'"Käske pappeja, jotka kantavat lain arkkia, astumaan ylös Jordanista."'),
(1674847,58,6,4,17,'Niin Joosua käski pappeja sanoen: "Astukaa ylös Jordanista".'),
(1674848,58,6,4,18,'Kun nyt Herran liitonarkkia kantavat papit astuivat ylös Jordanista, niin tuskin olivat pappien jalat nousseet kuivalle maalle, kun Jordanin vesi palasi paikoilleen ja juoksi niinkuin ennenkin yli kaikkien äyräidensä.'),
(1674849,58,6,4,19,'Kansa astui ylös Jordanista ensimmäisen kuun kymmenentenä päivänä. Ja he leiriytyivät Gilgaliin, Jerikon itäiselle rajalle.'),
(1674850,58,6,4,20,'Ja ne kaksitoista kiveä, jotka he olivat ottaneet Jordanista, Joosua pystytti Gilgaliin.'),
(1674851,58,6,4,21,'Ja hän sanoi israelilaisille näin: "Kun lapsenne vastaisuudessa kysyvät isiltään ja sanovat: ''Mitä nämä kivet merkitsevät?'''),
(1674852,58,6,4,22,'niin ilmoittakaa se lapsillenne ja sanokaa: ''Israel kulki tämän Jordanin poikki kuivaa myöten,'),
(1674853,58,6,4,23,'koska Herra, teidän Jumalanne, kuivasi Jordanin veden teidän tieltänne, kunnes olitte kulkeneet virran poikki, samoinkuin Herra, teidän Jumalanne, teki Kaislamerelle, jonka hän kuivasi meidän tieltämme, kunnes olimme kulkeneet sen poikki,'),
(1674854,58,6,4,24,'jotta kaikki maan kansat tulisivat tietämään, että Herran käsi on väkevä, ja jotta te pelkäisitte Herraa, teidän Jumalaanne, ainiaan''".'),
(1674855,58,6,5,1,'Kun kaikki amorilaisten kuninkaat, jotka asuivat tällä puolella Jordanin, lännen puolella, ja kaikki kanaanilaisten kuninkaat, jotka asuivat meren rannalla, kuulivat, kuinka Herra oli kuivannut Jordanin veden israelilaisten tieltä, kunnes he olivat kulkeneet yli, niin raukesi heidän sydämensä, eikä heissä enää ollut rohkeutta asettua israelilaisia vastaan.'),
(1674856,58,6,5,2,'Siihen aikaan Herra sanoi Joosualle: "Tee itsellesi kiviveitsiä ja ympärileikkaa taas israelilaiset toistamiseen".'),
(1674857,58,6,5,3,'Niin Joosua teki itselleen kiviveitsiä ja ympärileikkasi israelilaiset Esinahkakukkulan luona.'),
(1674858,58,6,5,4,'Ja syy siihen, että Joosua toimitti ympärileikkauksen, oli tämä: koko kansa, joka oli lähtenyt Egyptistä, miehenpuolet, kaikki sotakuntoiset miehet, olivat kuolleet matkalla erämaassa, heidän lähdettyään Egyptistä.'),
(1674859,58,6,5,5,'Sillä kaikki se kansa, joka oli lähtenyt, oli ollut ympärileikattu, mutta sitä kansaa, joka oli syntynyt matkalla erämaassa, heidän lähdettyään Egyptistä, ei oltu ympärileikattu.'),
(1674860,58,6,5,6,'Sillä neljäkymmentä vuotta olivat israelilaiset vaeltaneet erämaassa, kunnes oli hävinnyt koko se kansa, ne sotakuntoiset miehet, jotka olivat Egyptistä lähteneet, ne, jotka eivät olleet totelleet Herran ääntä ja joille Herra sentähden oli vannonut, ettei hän ollut salliva heidän nähdä sitä maata, jonka Herra heidän isillensä vannotulla valalla oli luvannut antaa meille, sitä maata, joka vuotaa maitoa ja mettä.'),
(1674861,58,6,5,7,'Mutta hän herätti heidän poikansa heidän sijaansa; ne Joosua ympärileikkasi, sillä he olivat ympärileikkaamattomia, koska ei heitä oltu ympärileikattu matkalla.'),
(1674862,58,6,5,8,'Kun koko kansa oli saatu ympärileikatuksi, pysyivät he paikallaan leirissä, kunnes olivat toipuneet.'),
(1674863,58,6,5,9,'Niin Herra sanoi Joosualle: "Tänä päivänä minä olen vierittänyt teidän päältänne Egyptin häväistyksen". Sentähden kutsutaan paikkaa vielä tänäkin päivänä Gilgaliksi.'),
(1674864,58,6,5,10,'Kun israelilaiset olivat leiriytyneet Gilgaliin, viettivät he sen kuukauden neljäntenätoista päivänä, ehtoolla, pääsiäistä Jerikon arolla.'),
(1674865,58,6,5,11,'Ja pääsiäisen jälkeisenä päivänä he söivät sen maan tuotteista happamatonta leipää ja paahdettuja jyviä, juuri sinä päivänä.'),
(1674866,58,6,5,12,'Mutta seuraavana päivänä lakkasi manna, koska he söivät sen maan tuotteita; eivätkä israelilaiset enää saaneet mannaa, vaan he söivät sinä vuonna Kanaanin maan satoa.'),
(1674867,58,6,5,13,'Ja tapahtui Joosuan ollessa Jerikon luona, että hän nosti silmänsä ja näki miehen seisovan edessään, paljastettu miekka kädessä. Ja Joosua meni hänen luokseen ja sanoi hänelle: "Oletko sinä meikäläisiä vai vihollisiamme?"'),
(1674868,58,6,5,14,'Niin hän sanoi: "En, vaan minä olen Herran sotajoukon päämies ja olen juuri nyt tullut". Niin Joosua heittäytyi kasvoilleen maahan, kumarsi ja sanoi hänelle: "Mitä herrallani on sanottavana palvelijalleen?"'),
(1674869,58,6,5,15,'Ja Herran sotajoukon päämies sanoi Joosualle: "Riisu kengät jalastasi, sillä paikka, jossa seisot, on pyhä". Ja Joosua teki niin.'),
(1674870,58,6,6,1,'Mutta Jeriko sulki porttinsa ja oli suljettuna israelilaisilta: ei kukaan käynyt ulos, eikä kukaan käynyt sisälle.'),
(1674871,58,6,6,2,'Niin Herra sanoi Joosualle: "Katso, minä annan sinun käsiisi Jerikon sekä sen kuninkaan ja sotaurhot.'),
(1674872,58,6,6,3,'Kulkekaa siis, kaikki sotakuntoiset miehet, kaupungin ympäri, kiertäkää kerta kaupunki; tee niin kuutena päivänä.'),
(1674873,58,6,6,4,'Ja seitsemän pappia kantakoon seitsemää oinaansarvista pasunaa arkin edellä. Seitsemäntenä päivänä kulkekaa kaupungin ympäri seitsemän kertaa, ja papit puhaltakoot pasunoihin.'),
(1674874,58,6,6,5,'Ja kun pitkä oinaansarven puhallus kuuluu, kun kuulette pasunan äänen, niin nostakoon koko kansa kovan sotahuudon; silloin kaupungin muuri kukistuu siihen paikkaansa, ja kansa voi rynnätä sinne ylös, kukin suoraan eteensä."'),
(1674875,58,6,6,6,'Silloin Joosua, Nuunin poika, kutsui papit ja sanoi heille: "Ottakaa liitonarkki, ja seitsemän pappia kantakoon seitsemää oinaansarvista pasunaa Herran arkin edellä".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674876,58,6,6,7,'Sitten hän sanoi kansalle: "Lähtekää ja kulkekaa kaupungin ympäri, ja aseväki käyköön Herran arkin edellä".'),
(1674877,58,6,6,8,'Ja tapahtui, niinkuin Joosua oli kansalle sanonut. Ne seitsemän pappia, jotka kantoivat niitä seitsemää oinaansarvista pasunaa Herran edellä, lähtivät ja puhalsivat pasunoihin, ja Herran liitonarkki kulki heidän jäljessään.'),
(1674878,58,6,6,9,'Ja aseväki kulki pasunaa puhaltavien pappien edellä, mutta muu väki kulki arkin jäljessä, samalla kuin pasunoihin yhtenään puhallettiin.'),
(1674879,58,6,6,10,'Ja Joosua käski kansaa sanoen: "Älkää nostako sotahuutoa älkääkä antako äänenne kuulua, älköönkä sanaakaan pääskö teidän suustanne ennenkuin sinä päivänä, jona minä teille sanon: ''Nostakaa sotahuuto'', silloin se nostakaa."'),
(1674880,58,6,6,11,'Ja hän antoi Herran arkin kulkea yhden kierroksen kaupungin ympäri; sitten he menivät leiriin ja jäivät yöksi leiriin.'),
(1674881,58,6,6,12,'Joosua nousi varhain seuraavana aamuna, ja papit ottivat Herran arkin.'),
(1674882,58,6,6,13,'Ja ne seitsemän pappia, jotka kantoivat niitä seitsemää oinaansarvista pasunaa Herran arkin edellä, kulkivat puhaltaen yhtenään pasunoihin, ja aseväki kulki heidän edellään, mutta muu väki kulki Herran arkin jäljessä, samalla kuin pasunoihin yhtenään puhallettiin.'),
(1674883,58,6,6,14,'Ja tänä toisenakin päivänä he kulkivat kerran kaupungin ympäri ja palasivat sitten leiriin. Niin he tekivät kuutena päivänä.'),
(1674884,58,6,6,15,'Mutta seitsemäntenä päivänä he nousivat varhain aamun sarastaessa ja kulkivat kaupungin ympäri samalla tavalla seitsemän kertaa. Ainoastaan sinä päivänä he kulkivat kaupungin ympäri seitsemän kertaa.'),
(1674885,58,6,6,16,'Ja kun papit seitsemännellä kerralla puhalsivat pasunoihin, sanoi Joosua kansalle: "Nostakaa sotahuuto, sillä Herra antaa teille kaupungin.'),
(1674886,58,6,6,17,'Kaupunki ja kaikki, mitä siinä on, vihittäköön tuhon omaksi Herran kunniaksi; ainoastaan portto Raahab jääköön henkiin, hän ja kaikki, jotka ovat hänen kanssaan hänen talossansa, sillä hän piilotti tiedustelijat, jotka me lähetimme.'),
(1674887,58,6,6,18,'Mutta karttakaa tuhon omaksi vihittyä, ettette vihi jotakin tuhon omaksi ja kuitenkin ota tuhon omaksi vihittyä ja niin tule vihkineiksi Israelin leiriä tuhon omaksi ja syökse sitä onnettomuuteen.'),
(1674888,58,6,6,19,'Ja kaikki hopea ja kulta sekä vaski- ja rautakalut olkoot pyhitetyt Herralle; ne joutukoot Herran aartehistoon."'),
(1674889,58,6,6,20,'Silloin kansa nosti sotahuudon ja pasunoihin puhallettiin. Kun kansa kuuli pasunan äänen, niin se nosti kovan sotahuudon; silloin kukistui muuri siihen paikkaansa, ja kansa ryntäsi ylös kaupunkiin, kukin suoraan eteensä. Niin he valloittivat kaupungin.'),
(1674890,58,6,6,21,'Ja he vihkivät miekan terällä tuhon omaksi kaiken, mitä kaupungissa oli, miehet ja naiset, nuoret ja vanhat, vieläpä härät, lampaat ja aasit.'),
(1674891,58,6,6,22,'Mutta niille kahdelle miehelle, jotka olivat olleet vakoilemassa maata, Joosua sanoi: "Menkää sen porton taloon ja tuokaa nainen ja kaikki hänen omaisensa sieltä ulos, niinkuin olette hänelle vannoneet".'),
(1674892,58,6,6,23,'Silloin ne nuoret miehet, jotka olivat olleet vakoilemassa, menivät ja toivat ulos Raahabin sekä hänen isänsä, äitinsä, veljensä ja kaikki hänen omaisensa; kaikki hänen sukulaisensa he toivat ulos ja jättivät heidät Israelin leirin ulkopuolelle.'),
(1674893,58,6,6,24,'Mutta kaupungin ja kaikki, mitä siinä oli, he polttivat tulella; ainoastaan hopean, kullan sekä vaski- ja rautakalut he panivat Herran huoneen aartehistoon.'),
(1674894,58,6,6,25,'Mutta portto Raahabin sekä hänen isänsä perheen ja kaikki hänen omaisensa Joosua jätti henkiin; ja hän jäi asumaan Israelin keskuuteen, aina tähän päivään asti, koska hän oli piilottanut ne tiedustelijat, jotka Joosua oli lähettänyt vakoilemaan Jerikoa.'),
(1674895,58,6,6,26,'Siihen aikaan Joosua vannotti tämän valan: "Kirottu olkoon Herran edessä se mies, joka ryhtyy rakentamaan tätä Jerikon kaupunkia. Sen perustuksen laskemisesta hän menettäköön esikoisensa ja sen porttien pystyttämisestä nuorimpansa."'),
(1674896,58,6,6,27,'Ja Herra oli Joosuan kanssa, ja hänen maineensa levisi kautta maan.'),
(1674897,58,6,7,1,'Mutta israelilaiset menettelivät uskottomasti anastamalla itselleen tuhon omaksi vihittyä; sillä Aakan, Karmin poika, joka oli Sabdin poika, joka Serahin poika, Juudan sukukuntaa, otti itselleen tuhon omaksi vihittyä. Silloin syttyi Herran viha israelilaisia kohtaan.'),
(1674898,58,6,7,2,'Ja Joosua lähetti miehiä Jerikosta Aihin, joka on lähellä Beet-Aavenia, itään päin Beetelistä, ja sanoi heille näin: "Menkää vakoilemaan maata". Niin miehet menivät ja vakoilivat Aita.'),
(1674899,58,6,7,3,'Kun he palasivat Joosuan luo, sanoivat he hänelle: "Älköön koko kansa menkö, vaan menköön noin kaksi tai kolme tuhatta miestä Aita valloittamaan; älä vaivaa koko kansaa sinne, sillä niitä on vähän".'),
(1674900,58,6,7,4,'Niin meni sinne kansasta noin kolme tuhatta miestä, mutta he kääntyivät pakoon Ain miesten edestä.'),
(1674901,58,6,7,5,'Ja Ain miehet löivät heitä kuoliaaksi noin kolmekymmentä kuusi miestä, ajoivat heitä takaa kaupungin portilta Sebarimiin asti ja voittivat heidät rinteessä. Silloin kansan sydän raukesi ja tuli kuin vedeksi.'),
(1674902,58,6,7,6,'Niin Joosua repäisi vaatteensa ja lankesi kasvoilleen maahan Herran arkin eteen ja oli siinä iltaan saakka, hän ja Israelin vanhimmat; ja he heittivät tomua päänsä päälle.'),
(1674903,58,6,7,7,'Ja Joosua sanoi: "Voi, Herra, Herra, minkätähden toit tämän kansan Jordanin yli antaaksesi meidät amorilaisten käsiin ja tuhotaksesi meidät? Oi, jospa olisimme päättäneet jäädä tuolle puolelle Jordanin!'),
(1674904,58,6,7,8,'Oi, Herra, mitä sanoisinkaan, kun Israel on kääntynyt pakoon vihollistensa edestä!'),
(1674905,58,6,7,9,'Kun kanaanilaiset ja kaikki muut maan asukkaat sen kuulevat, niin he saartavat meidät ja hävittävät meidän nimemme maan päältä. Mitä aiot tehdä suuren nimesi puolesta?"'),
(1674906,58,6,7,10,'Mutta Herra sanoi Joosualle: "Nouse! Miksi makaat kasvoillasi?'),
(1674907,58,6,7,11,'Israel on tehnyt syntiä, he ovat rikkoneet minun liittoni, jonka minä olen heille säätänyt; he ovat ottaneet sitä, mikä oli vihitty tuhon omaksi, he ovat varastaneet ja valhetelleet, he ovat panneet sen omain tavarainsa joukkoon.'),
(1674908,58,6,7,12,'Sentähden israelilaiset eivät voi kestää vihollistensa edessä, vaan heidän täytyy kääntyä pakoon vihollistensa edestä, sillä he itse ovat vihityt tuhon omiksi. En minä enää ole teidän kanssanne, ellette hävitä keskuudestanne tuhon omaksi vihittyä.'),
(1674909,58,6,7,13,'Nouse, pyhitä kansa ja sano: Pyhittäytykää huomiseksi, sillä näin sanoo Herra, Israelin Jumala: Sinun keskuudessasi, Israel, on jotakin tuhon omaksi vihittyä; sinä et voi kestää vihollistesi edessä, ennenkuin olette poistaneet keskuudestanne tuhon omaksi vihityn.'),
(1674910,58,6,7,14,'Astukaa siis huomenaamuna sukukunnittain esiin, ja se sukukunta, johon Herran arpa osuu, astukoon esiin suvuittain, ja se suku, johon Herran arpa osuu, astukoon esiin perhekunnittain, ja se perhekunta, johon Herran arpa osuu, astukoon esiin mies mieheltä.'),
(1674911,58,6,7,15,'Mutta se, jolta tavataan tuhon omaksi vihittyä, poltettakoon tulessa, hän ja kaikki, mitä hänellä on, sillä hän on rikkonut Herran liiton ja tehnyt häpeällisen teon Israelissa."'),
(1674912,58,6,7,16,'Niin Joosua antoi varhain seuraavana aamuna Israelin sukukunnittain astua esiin; ja arpa osui Juudan sukukuntaan.'),
(1674913,58,6,7,17,'Silloin hän antoi Juudan sukukunnan astua esiin, ja arpa osui serahilaisten sukuun. Sitten hän antoi serahilaisten suvun astua esiin mies mieheltä, ja arpa osui Sabdiin.'),
(1674914,58,6,7,18,'Niin hän antoi hänen perhekuntansa mies mieheltä astua esiin, ja arpa osui Aakaniin, Karmin poikaan, joka oli Sabdin poika, joka Serahin poika, Juudan sukukuntaa.'),
(1674915,58,6,7,19,'Silloin Joosua sanoi Aakanille: "Poikani, anna Herralle, Israelin Jumalalle, kunnia ja anna hänelle ylistys: tunnusta minulle, mitä olet tehnyt, äläkä salaa sitä minulta".'),
(1674916,58,6,7,20,'Niin Aakan vastasi Joosualle ja sanoi: "Minä todella olen tehnyt syntiä Herraa, Israelin Jumalaa, vastaan, sillä näin minä tein:'),
(1674917,58,6,7,21,'kun minä näin saaliin joukossa kauniin sinearilaisen vaipan, kaksisataa sekeliä hopeata ja kultalevyn, viidenkymmenen sekelin painoisen, niin minussa syttyi niihin himo, ja minä otin ne; ne ovat kätkettyinä maahan keskelle minun telttaani, hopea alimpana".'),
(1674918,58,6,7,22,'Niin Joosua lähetti miehiä ottamaan selkoa, ja ne juoksivat telttaan. Siellä oli kätkö hänen teltassaan, hopea alimpana.'),
(1674919,58,6,7,23,'Ja he ottivat ne teltasta, veivät ne Joosuan ja kaikkien israelilaisten luo ja panivat Herran eteen.'),
(1674920,58,6,7,24,'Niin Joosua yhdessä koko Israelin kanssa otti Aakanin, Serahin pojan, ja hopean, vaipan ja kultalevyn, sekä hänen poikansa, tyttärensä, härkänsä, aasinsa, lampaansa, telttansa ynnä kaikki, mitä hänellä oli, ja he veivät ne Aakorin laaksoon.'),
(1674921,58,6,7,25,'Ja Joosua sanoi: "Miksi olet syössyt meidät onnettomuuteen? Herra syöksee sinut onnettomuuteen tänä päivänä." Silloin koko Israel kivitti hänet kuoliaaksi. He polttivat heidät tulessa ja kivittivät heidät.'),
(1674922,58,6,7,26,'Ja he kasasivat hänen päällensä suuren kiviroukkion, joka vielä tänäkin päivänä on olemassa; ja niin Herra lauhtui vihansa hehkusta. Sentähden kutsutaan sitä paikkaa vielä tänäkin päivänä Aakorin laaksoksi.'),
(1674923,58,6,8,1,'Ja Herra sanoi Joosualle: "Älä pelkää äläkä arkaile. Ota mukaasi kaikki sotaväki ja lähde ja mene Aihin. Katso, minä annan sinun käsiisi Ain kuninkaan ja hänen kansansa, hänen kaupunkinsa ja maansa.'),
(1674924,58,6,8,2,'Ja tee Aille ja sen kuninkaalle, niinkuin teit Jerikolle ja sen kuninkaalle; kuitenkin saatte ryöstää itsellenne, mitä sieltä on saatavana saalista ja karjaa. Aseta väijytys kaupungin taa."'),
(1674925,58,6,8,3,'Niin Joosua ynnä kaikki sotaväki lähti liikkeelle mennäkseen Aihin. Ja Joosua valitsi kolmekymmentä tuhatta miestä, sotaurhoa, ja lähetti heidät menemään yöllä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674926,58,6,8,4,'Ja hän käski heitä sanoen: "Asettukaa väijyksiin kaupungin taa, ei aivan kauas kaupungista; ja olkaa kaikki valmiina.'),
(1674927,58,6,8,5,'Mutta minä ynnä kaikki se väki, joka on minun kanssani, lähenemme kaupunkia. Kun he sitten tulevat ulos meitä vastaan niinkuin ensi kerrallakin, niin me käännymme pakoon heidän edestänsä.'),
(1674928,58,6,8,6,'Ja he seuraavat meitä niin kauas, että eristämme heidät kaupungista, sillä he sanovat: ''He pakenevat meitä niinkuin ensi kerrallakin''. Kun me näin pakenemme heitä,'),
(1674929,58,6,8,7,'silloin nouskaa te väijytyksestä ja ottakaa kaupunki haltuunne, sillä Herra, teidän Jumalanne, antaa sen teidän käsiinne.'),
(1674930,58,6,8,8,'Ja kun olette saaneet kaupungin valtaanne, sytyttäkää kaupunki palamaan; tehkää Herran sanan mukaan. Huomatkaa, että minä käsken teidän tehdä sen."'),
(1674931,58,6,8,9,'Sitten Joosua lähetti heidät menemään, ja he menivät ja asettuivat väijytyspaikkaan Beetelin ja Ain välille, länteen päin Aista. Mutta Joosua oli sen yön kansan kanssa.'),
(1674932,58,6,8,10,'Varhain seuraavana aamuna Joosua piti kansan katselmuksen ja lähti, hän ja Israelin vanhimmat, kansan etunenässä nousemaan Aihin.'),
(1674933,58,6,8,11,'Ja kaikki se sotaväki, joka oli hänen kanssaan, nousi, lähestyi ja tuli kaupungin edustalle; ja he leiriytyivät Ain pohjoispuolelle, niin että laakso oli heidän ja Ain välillä.'),
(1674934,58,6,8,12,'Sitten hän otti noin viisituhatta miestä ja asetti heidät väijyksiin Beetelin ja Ain välille, länteen päin kaupungista.'),
(1674935,58,6,8,13,'Niin kansa, koko leiri, joka oli kaupungin pohjoispuolella, ja kaupungin länsipuolella oleva jälkijoukko asetettiin asemiinsa. Mutta Joosua meni sinä yönä keskelle laaksoa.'),
(1674936,58,6,8,14,'Kun Ain kuningas näki sen, niin kaupungin miehet, kuningas ja kaikki hänen väkensä, lähtivät varhain aamulla nopeasti taisteluun Israelia vastaan määrättyyn paikkaan aromaan puolelle; hän ei näet tiennyt, että oli väijytys häntä vastaan kaupungin takana.'),
(1674937,58,6,8,15,'Niin Joosua ja koko Israel olivat joutuvinaan tappiolle ja pakenivat erämaahan päin.'),
(1674938,58,6,8,16,'Silloin kaupungin koko väki kutsuttiin ajamaan heitä takaa; ja he ajoivat Joosuaa takaa, ja niin heidät eristettiin kaupungista.'),
(1674939,58,6,8,17,'Eikä Aihin eikä Beeteliin jäänyt ainoatakaan miestä, joka ei lähtenyt Israelin jälkeen, vaan he jättivät kaupungin avoimeksi ja ajoivat takaa Israelia.'),
(1674940,58,6,8,18,'Niin Herra sanoi Joosualle: "Ojenna keihäs, joka on kädessäsi, Aita kohti, sillä minä annan sen sinun käsiisi". Ja Joosua ojensi keihään, joka oli hänen kädessään, kaupunkia kohti.'),
(1674941,58,6,8,19,'Silloin väijyksissä oleva joukko nousi kiiruusti paikaltaan ja riensi, niin pian kuin hän ojensi kätensä, ja tunkeutui kaupunkiin ja valloitti sen ja sytytti heti kaupungin palamaan.'),
(1674942,58,6,8,20,'Kun Ain miehet kääntyivät ja katsoivat taaksensa, niin he näkivät kaupungista savun nousevan taivasta kohti; eivätkä he kyenneet pakenemaan, ei sinne eikä tänne, sillä se väki, joka pakeni erämaahan, kääntyi takaa-ajajia vastaan.'),
(1674943,58,6,8,21,'Kun Joosua ja koko Israel näki, että väijyksissä ollut joukko oli valloittanut kaupungin ja että kaupungista nousi savu, niin he palasivat takaisin ja voittivat Ain miehet.'),
(1674944,58,6,8,22,'Ja myöskin ne toiset lähtivät kaupungista heitä vastaan, joten he joutuivat israelilaisten väliin, toisten ollessa edessä, toisten takana. Ja he voittivat heidät, päästämättä pakoon ja pelastumaan ainoatakaan heistä.'),
(1674945,58,6,8,23,'Mutta Ain kuninkaan he ottivat kiinni elävänä ja toivat hänet Joosuan eteen.'),
(1674946,58,6,8,24,'Kun Israel oli surmannut kaikki Ain asukkaat kedolla, erämaassa, jonne he olivat heitä ajaneet takaa, ja he kaikki viimeiseen mieheen olivat kaatuneet miekan terään, palasi koko Israel Aihin, ja siellä olevat tapettiin miekan terällä.'),
(1674947,58,6,8,25,'Ja niitä, jotka sinä päivänä kaatuivat, miehiä ja naisia, oli kaikkiaan kaksitoista tuhatta, kaikki Ain asukkaat.'),
(1674948,58,6,8,26,'Joosua ei vetänyt takaisin kättänsä, jossa hänellä oli keihäs ojennettuna, ennenkuin oli vihkinyt tuhon omiksi kaikki Ain asukkaat.'),
(1674949,58,6,8,27,'Ainoastaan karjan, ja mitä kaupungista oli saatavana saalista, Israel ryösti itselleen sen määräyksen mukaan, jonka Herra oli Joosualle antanut.'),
(1674950,58,6,8,28,'Ja Joosua poltti Ain ja teki siitä ikiajoiksi rauniokummun, aution aina tähän päivään asti.'),
(1674951,58,6,8,29,'Mutta Ain kuninkaan hän ripusti hirteen, jossa hän riippui iltaan asti. Mutta auringon laskiessa Joosua käski ottaa hänen ruumiinsa alas hirrestä, ja he heittivät sen kaupungin portin edustalle ja kasasivat sen päälle suuren kiviroukkion, joka on siellä vielä tänäkin päivänä.'),
(1674952,58,6,8,30,'Silloin Joosua rakensi Eebalin vuorelle alttarin Herralle, Israelin Jumalalle,'),
(1674953,58,6,8,31,'niinkuin Herran palvelija Mooses oli käskenyt israelilaisten tehdä ja niinkuin on kirjoitettuna Mooseksen lain kirjassa: alttarin hakkaamattomista kivistä, joihin ei oltu rauta-aseella koskettu. Ja he uhrasivat sen päällä polttouhreja Herralle ja teurastivat teuraita yhteysuhriksi.'),
(1674954,58,6,8,32,'Ja hän kirjoitti siellä kiviin jäljennöksen Mooseksen laista, jonka tämä oli kirjoittanut israelilaisille.'),
(1674955,58,6,8,33,'Ja koko Israel vanhimpineen, päällysmiehineen ja tuomareineen seisoi kummallakin puolella arkkia, päin leeviläisiä pappeja, jotka kantoivat Herran liitonarkkia, niin muukalaiset kuin maassasyntyneetkin, toinen puoli kääntyneenä Garissimin vuorta kohti, toinen puoli Eebalin vuorta kohti. Niin Israelin kansa ensiksi siunattiin, niinkuin Herran palvelija Mooses oli käskenyt,'),
(1674956,58,6,8,34,'ja sen jälkeen hän luki kaikki lain sanat, siunauksen ja kirouksen, aivan niinkuin lain kirjassa on kirjoitettuna.'),
(1674957,58,6,8,35,'Ei mitään siitä, mitä Mooses oli käskenyt, Joosua jättänyt lukematta kaiken Israelin seurakunnan läsnäollessa, niin myös naisten, lasten ja mukana kulkevien muukalaisten läsnäollessa.'),
(1674958,58,6,9,1,'Kun kaikki kuninkaat, jotka asuivat tällä puolella Jordanin, Vuoristossa, Alankomaassa ja pitkin Suuren meren koko rannikkoa Libanoniin päin, heettiläiset, amorilaiset, kanaanilaiset, perissiläiset, hivviläiset ja jebusilaiset, kuulivat, mitä oli tapahtunut,'),
(1674959,58,6,9,2,'niin he kokoontuivat yhteen sotiakseen yksimielisesti Joosuaa ja Israelia vastaan.'),
(1674960,58,6,9,3,'Mutta kun Gibeonin asukkaat kuulivat, mitä Joosua oli tehnyt Jerikolle ja Aille,'),
(1674961,58,6,9,4,'niin hekin menettelivät viekkaasti: he menivät ja tekeytyivät lähettiläiksi, ottivat kuluneita säkkejä aasiensa selkään sekä kuluneita, repeytyneitä ja kiinnisolmeiltuja viinileilejä'),
(1674962,58,6,9,5,'ja panivat kuluneet, paikatut kengät jalkaansa ja kuluneet vaatteet päällensä; ja kaikki heidän eväsleipänsä olivat kuivia ja murentuneita.'),
(1674963,58,6,9,6,'Niin he menivät Joosuan luo Gilgalin leiriin ja sanoivat hänelle sekä Israelin miehille: "Me olemme tulleet kaukaisesta maasta; tehkää siis liitto meidän kanssamme".'),
(1674964,58,6,9,7,'Mutta Israelin miehet vastasivat hivviläisille: "Kenties te asutte täällä meidän keskellämme; kuinka me tekisimme liiton teidän kanssanne?"'),
(1674965,58,6,9,8,'Niin he sanoivat Joosualle: "Me olemme sinun palvelijoitasi". Joosua sanoi heille: "Keitä te olette ja mistä tulette?"'),
(1674966,58,6,9,9,'Niin he vastasivat hänelle: "Palvelijasi tulevat hyvin kaukaisesta maasta Herran, sinun Jumalasi, nimen tähden. Sillä me olemme kuulleet hänestä kaiken, mitä hän teki Egyptissä,'),
(1674967,58,6,9,10,'ja kaiken, mitä hän teki niille kahdelle amorilaisten kuninkaalle, jotka asuivat tuolla puolella Jordanin, Siihonille, Hesbonin kuninkaalle, ja Oogille, Baasanin kuninkaalle, joka asui Astarotissa.'),
(1674968,58,6,9,11,'Sentähden sanoivat meille meidän vanhimpamme ja kaikki maamme asukkaat näin: ''Ottakaa evästä mukaanne matkalle ja menkää heitä vastaan ja sanokaa heille: Me olemme teidän palvelijanne, tehkää siis liitto meidän kanssamme''.'),
(1674969,58,6,9,12,'Tämä leipämme oli vielä lämmintä, kun kotoa otimme sen evääksi lähtiessämme matkalle teidän luoksenne, ja katso, nyt se on kuivaa ja murentunutta.'),
(1674970,58,6,9,13,'Ja nämä viinileilit, jotka uusina täytimme, ovat nyt repeytyneitä; ja nämä vaatteemme ja kenkämme ovat kovin pitkällä matkalla kuluneet."'),
(1674971,58,6,9,14,'Niin miehet ottivat heidän evästänsä, mutta eivät kysyneet Herran mieltä.'),
(1674972,58,6,9,15,'Niin Joosua takasi heille rauhan ja teki heidän kanssaan liiton, luvaten jättää heidät henkiin; ja kansan päämiehet vannoivat heille valan.'),
(1674973,58,6,9,16,'Mutta kolmen päivän kuluttua, sen jälkeen kuin liitto heidän kanssaan oli tehty, saatiin kuulla, että he olivat lähiseuduilta ja asuivat heidän keskellänsä.'),
(1674974,58,6,9,17,'Niin israelilaiset lähtivät liikkeelle ja tulivat kolmantena päivänä heidän kaupunkeihinsa; ja heidän kaupunkinsa olivat Gibeon, Kefira, Beerot ja Kirjat-Jearim.'),
(1674975,58,6,9,18,'Mutta israelilaiset eivät surmanneet heitä, sillä kansan päämiehet olivat vannoneet heille valan Herran, Israelin Jumalan, kautta. Ja koko seurakunta napisi päämiehiä vastaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1674976,58,6,9,19,'Silloin kaikki päämiehet sanoivat koko seurakunnalle: "Me olemme vannoneet heille valan Herran, Israelin Jumalan, kautta; sentähden me emme voi koskea heihin.'),
(1674977,58,6,9,20,'Mutta tämän me teemme heille, jättäessämme heidät henkiin, ettei viha kohtaisi meitä valan tähden, jonka olemme heille vannoneet."'),
(1674978,58,6,9,21,'Ja päämiehet sanoivat heistä: "Jääkööt henkiin, mutta tulkoon heistä halonhakkaajia ja vedenkantajia kaikelle kansalle". Näin päämiehet antoivat käskyn heistä.'),
(1674979,58,6,9,22,'Silloin Joosua kutsui heidät ja puhui heille sanoen: "Miksi olette pettäneet meidät ja sanoneet: ''Me asumme hyvin kaukana teistä'', vaikka asutte täällä meidän keskellämme?'),
(1674980,58,6,9,23,'Sentähden olkaa kirotut! Älköön ikinä ketään teistä päästettäkö olemasta minun Jumalani huoneen palvelijana, halonhakkaajana ja vedenkantajana."'),
(1674981,58,6,9,24,'He vastasivat Joosualle ja sanoivat: "Sinun palvelijoillesi oli kerrottu, että Herra, sinun Jumalasi, oli käskenyt palvelijaansa Moosesta antamaan teille koko tämän maan ja tuhoamaan kaikki maan asukkaat teidän tieltänne. Sentähden me suuresti pelkäsimme henkeämme teidän edessänne ja teimme tämän.'),
(1674982,58,6,9,25,'Mutta katso, nyt me olemme sinun käsissäsi: tee meille, mikä mielestäsi on hyvin ja oikein."'),
(1674983,58,6,9,26,'Silloin hän teki heille näin: hän pelasti heidät israelilaisten käsistä, niin etteivät he heitä surmanneet.'),
(1674984,58,6,9,27,'Niin Joosua sinä päivänä määräsi heidät seurakunnan ja Herran alttarin halonhakkaajiksi ja vedenkantajiksi, aina tähän päivään asti, sitä paikkaa varten, jonka Herra oli valitseva.'),
(1674985,58,6,10,1,'Kun Adonisedek, Jerusalemin kuningas, kuuli, että Joosua oli valloittanut Ain ja vihkinyt sen tuhon omaksi, tehden Aille ja sen kuninkaalle, niinkuin oli tehnyt Jerikolle ja sen kuninkaalle, ja että Gibeonin asukkaat olivat tehneet rauhan Israelin kanssa ja jääneet heidän keskuuteensa,'),
(1674986,58,6,10,2,'niin he peljästyivät suuresti, sillä Gibeon oli suuri kaupunki, niinkuin joku kuninkaankaupunki, ja suurempi kuin Ai, ja kaikki sen miehet olivat urhoollisia.'),
(1674987,58,6,10,3,'Ja Adonisedek, Jerusalemin kuningas, lähetti sanan Hoohamille, Hebronin kuninkaalle, Piramille, Jarmutin kuninkaalle, Jaafialle, Laakiin kuninkaalle, ja Debirille, Eglonin kuninkaalle:'),
(1674988,58,6,10,4,'"Tulkaa minun luokseni ja auttakaa minua, ja kukistakaamme Gibeon, koska se on tehnyt rauhan Joosuan ja israelilaisten kanssa".'),
(1674989,58,6,10,5,'Niin nuo viisi amorilaisten kuningasta, Jerusalemin kuningas, Hebronin kuningas, Jarmutin kuningas, Laakiin kuningas ja Eglonin kuningas, kokoontuivat ja lähtivät liikkeelle kaikkine joukkoineen; ja he asettuivat leiriin Gibeonin edustalle ja ryhtyivät taisteluun sitä vastaan.'),
(1674990,58,6,10,6,'Silloin Gibeonin miehet lähettivät sanan Joosualle Gilgalin leiriin: "Älköön sinun kätesi vetäytykö auttamasta palvelijoitasi. Tule nopeasti luoksemme, pelasta meidät ja auta meitä, sillä kaikki vuoristossa asuvien amorilaisten kuninkaat ovat kokoontuneet meitä vastaan."'),
(1674991,58,6,10,7,'Niin Joosua lähti Gilgalista, hän ja kaikki sotaväki hänen kanssaan ja kaikki sotaurhot.'),
(1674992,58,6,10,8,'Silloin Herra sanoi Joosualle: "Älä pelkää heitä, sillä minä annan heidät sinun käsiisi; ei kukaan heistä kestä sinun edessäsi".'),
(1674993,58,6,10,9,'Niin Joosua yllätti heidät, kuljettuaan kaiken yötä Gilgalista.'),
(1674994,58,6,10,10,'Ja Herra saattoi heidät hämminkiin israelilaisten edessä, niin että nämä tuottivat heille suuren tappion Gibeonissa ja ajoivat heitä takaa Beet-Hooronin solatietä, surmaten heitä aina Asekaan ja Makkedaan asti.'),
(1674995,58,6,10,11,'Ja kun he paetessaan Israelia olivat Beet-Hooronin rinteessä, heitti Herra taivaasta heidän päällensä isoja kiviä, koko matkan Asekaan asti, niin että he kuolivat; niitä, jotka kuolivat raekivistä, oli useampia kuin niitä, jotka israelilaiset surmasivat miekalla.'),
(1674996,58,6,10,12,'Silloin puhui Joosua Herralle, sinä päivänä, jona Herra antoi amorilaiset israelilaisten valtaan, ja sanoi Israelin silmien edessä: "Aurinko, seiso alallasi Gibeonissa, ja kuu Aijalonin laaksossa".'),
(1674997,58,6,10,13,'Niin aurinko seisoi alallansa, ja kuu pysyi paikallansa, kunnes kansa oli kostanut vihollisilleen. Niinhän on kirjoitettuna "Oikeamielisen kirjassa". Niin aurinko pysyi paikallansa keskitaivaalla päiväkauden, kiirehtimättä laskemaan.'),
(1674998,58,6,10,14,'Eikä ole ollut sen päivän vertaista, ei ennen eikä jälkeen, jona Herra näin kuuli ihmisen ääntä; sillä Herra soti Israelin puolesta.'),
(1674999,58,6,10,15,'Sen jälkeen Joosua ja koko Israel hänen kanssaan palasi Gilgalin leiriin.'),
(1675000,58,6,10,16,'Mutta nuo viisi kuningasta pakenivat ja piiloutuivat Makkedan luolaan.'),
(1675001,58,6,10,17,'Niin Joosualle ilmoitettiin: "Ne viisi kuningasta on löydetty piiloutuneina Makkedan luolaan".'),
(1675002,58,6,10,18,'Silloin Joosua sanoi: "Vierittäkää isoja kiviä luolan suulle ja asettakaa sen eteen miehiä vartioimaan heitä.'),
(1675003,58,6,10,19,'Mutta te muut, älkää pysähtykö, vaan ajakaa takaa vihollisianne ja hakatkaa maahan heidän jälkijoukkonsa älkääkä päästäkö heitä menemään kaupunkeihinsa, sillä Herra, teidän Jumalanne, on antanut heidät teidän käsiinne."'),
(1675004,58,6,10,20,'Kun sitten Joosua ja israelilaiset olivat tuottaneet heille hyvin suuren, perinpohjaisen tappion ja ne harvat, jotka olivat pelastuneet, olivat päässeet varustettuihin kaupunkeihin,'),
(1675005,58,6,10,21,'niin koko kansa palasi vahingoittumatonna takaisin Joosuan luo leiriin Makkedaan, eikä kukaan uskaltanut enää hiiskua sanaakaan israelilaisia vastaan.'),
(1675006,58,6,10,22,'Silloin Joosua sanoi: "Avatkaa luolan suu ja tuokaa ne viisi kuningasta minun eteeni luolasta".'),
(1675007,58,6,10,23,'Ja he tekivät niin ja toivat hänen eteensä ne viisi kuningasta luolasta: Jerusalemin kuninkaan, Hebronin kuninkaan, Jarmutin kuninkaan, Laakiin kuninkaan ja Eglonin kuninkaan.'),
(1675008,58,6,10,24,'Ja kun he olivat tuoneet nämä kuninkaat Joosuan eteen, niin Joosua kutsui kaikki Israelin miehet ja sanoi sotaväen päälliköille, jotka olivat seuranneet häntä: "Astukaa esiin ja pankaa jalkanne näiden kuninkaiden niskalle". Niin he astuivat esiin ja panivat jalkansa heidän niskallensa.'),
(1675009,58,6,10,25,'Silloin Joosua sanoi heille: "Älkää peljätkö älkääkä arkailko, vaan olkaa lujat ja rohkeat, sillä näin on Herra tekevä kaikille teidän vihollisillenne, joita vastaan te joudutte sotimaan".'),
(1675010,58,6,10,26,'Sen jälkeen Joosua löi heidät kuoliaaksi ja ripusti heidät viiteen hirsipuuhun. Ja he riippuivat hirressä iltaan asti.'),
(1675011,58,6,10,27,'Mutta auringonlaskun aikaan Joosua käski ottaa heidät alas hirrestä ja heittää luolaan, johon he olivat piiloutuneet. Ja he panivat luolan suulle isoja kiviä, jotka ovat siinä vielä tänäkin päivänä.'),
(1675012,58,6,10,28,'Samana päivänä Joosua valloitti Makkedan ja surmasi miekan terällä sen asukkaat ja sen kuninkaan; hän vihki tuhon omiksi heidät ja jokaisen, joka siellä oli, päästämättä pakoon ainoatakaan. Ja hän teki Makkedan kuninkaalle, niinkuin oli tehnyt Jerikon kuninkaalle.'),
(1675013,58,6,10,29,'Sitten Joosua ja koko Israel hänen kanssaan lähti Makkedasta Libnaan ja ryhtyi taisteluun Libnaa vastaan.'),
(1675014,58,6,10,30,'Ja Herra antoi senkin ja sen kuninkaan Israelin käsiin. Ja Joosua surmasi miekan terällä sen asukkaat, jokaisen, joka siellä oli, päästämättä sieltä pakoon ainoatakaan; ja hän teki sen kuninkaalle saman, minkä oli tehnyt Jerikon kuninkaalle.'),
(1675015,58,6,10,31,'Sitten Joosua ja koko Israel hänen kanssaan lähti Libnasta Laakiiseen ja asettui leiriin sen edustalle ja ryhtyi taisteluun sitä vastaan.'),
(1675016,58,6,10,32,'Ja Herra antoi Laakiin Israelin käsiin, niin että hän valloitti sen toisena päivänä; ja hän surmasi miekan terällä sen asukkaat, jokaisen, joka siellä oli, samoin kuin oli tehnyt Libnalle.'),
(1675017,58,6,10,33,'Silloin Hooram, Geserin kuningas, tuli auttamaan Laakista; mutta Joosua voitti hänet ja hänen väkensä, päästämättä pakoon ainoatakaan heistä.'),
(1675018,58,6,10,34,'Ja Laakiista Joosua ja koko Israel hänen kanssaan lähti Egloniin, ja he asettuivat leiriin sen edustalle ja ryhtyivät taisteluun sitä vastaan.'),
(1675019,58,6,10,35,'Ja he valloittivat sen samana päivänä ja surmasivat miekan terällä sen asukkaat, ja hän vihki sinä päivänä tuhon omaksi jokaisen, joka siellä oli, samoin kuin oli tehnyt Laakiille.'),
(1675020,58,6,10,36,'Sen jälkeen Joosua ja koko Israel hänen kanssaan lähti Eglonista Hebroniin, ja he ryhtyivät taisteluun sitä vastaan.'),
(1675021,58,6,10,37,'Ja he valloittivat sen ja surmasivat miekan terällä sen asukkaat ja sen kuninkaan, ja samoin kaikki sen alaiset kaupungit ja jokaisen, joka siellä oli, päästämättä pakoon ainoatakaan, samoin kuin hän oli tehnyt Eglonille. Hän vihki tuhon omaksi sen ja jokaisen, joka siellä oli.'),
(1675022,58,6,10,38,'Sitten Joosua ja koko Israel hänen kanssaan kääntyi Debiriin ja ryhtyi taisteluun sitä vastaan.'),
(1675023,58,6,10,39,'Ja hän sai valtaansa sen ja sen kuninkaan ja kaikki sen alaiset kaupungit, ja he surmasivat miekan terällä niiden asukkaat ja vihkivät tuhon omaksi jokaisen, joka siellä oli, päästämättä pakoon ainoatakaan. Hän teki Debirille ja sen kuninkaalle saman, minkä oli tehnyt Hebronille ja minkä oli tehnyt Libnalle ja sen kuninkaalle.'),
(1675024,58,6,10,40,'Sitten Joosua valtasi koko maan, Vuoriston, Etelämaan, Alankomaan ja Rinnemaat, ja surmasi kaikki niiden kuninkaat, päästämättä pakoon ainoatakaan, ja vihki tuhon omaksi joka hengen, niinkuin Herra, Israelin Jumala, oli käskenyt.'),
(1675025,58,6,10,41,'Ja Joosua valtasi heidän alueensa Kaades-Barneasta Gassaan saakka ja koko Goosenin maakunnan Gibeoniin saakka.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675026,58,6,10,42,'Kaikki nämä kuninkaat ja heidän maansa Joosua sai valtaansa yhdellä otteella; sillä Herra, Israelin Jumala, soti Israelin puolesta.'),
(1675027,58,6,10,43,'Sitten Joosua ja koko Israel hänen kanssaan palasi Gilgalin leiriin.'),
(1675028,58,6,11,1,'Kun Jaabin, Haasorin kuningas, sen kuuli, lähetti hän sanan Joobabille, Maadonin kuninkaalle, ja Simronin kuninkaalle ja Aksafin kuninkaalle'),
(1675029,58,6,11,2,'ja niille kuninkaille, jotka asuivat pohjoisessa, Vuoristossa, Aromaassa Kinarotista etelään päin, Alankomaassa ja Doorin kukkuloilla lännessä,'),
(1675030,58,6,11,3,'kanaanilaisille itään ja länteen, amorilaisille, heettiläisille, perissiläisille ja jebusilaisille vuoristoon ja hivviläisille Hermonin juurelle Mispan maahan.'),
(1675031,58,6,11,4,'Nämä lähtivät liikkeelle kaikkine joukkoineen; väkeä oli niin paljon kuin hiekkaa meren rannalla ja hevosia ja sotavaunuja ylen paljon.'),
(1675032,58,6,11,5,'Ja kaikki nämä kuninkaat liittyivät yhteen, tulivat ja leiriytyivät yhdessä Meeromin veden rannalle sotiaksensa Israelia vastaan.'),
(1675033,58,6,11,6,'Silloin Herra sanoi Joosualle: "Älä pelkää heitä, sillä huomenna tähän aikaan minä annan heidät kaikki voitettuina Israelin valtaan; heidän ratsujensa vuohisjänteet sinä katkot, ja heidän vaununsa sinä poltat tulessa".'),
(1675034,58,6,11,7,'Niin Joosua ja kaikki sotaväki hänen kanssaan yllätti heidät Meeromin veden rannalla ja hyökkäsi heidän kimppuunsa.'),
(1675035,58,6,11,8,'Ja Herra antoi heidät Israelin käsiin, niin että he voittivat heidät ja ajoivat heitä takaa aina suureen Siidoniin, Misrefot-Majimiin ja itään päin Mispan laaksoon asti; ja he voittivat heidät, päästämättä pakoon ainoatakaan heistä.'),
(1675036,58,6,11,9,'Ja Joosua teki heille, niinkuin Herra oli hänelle sanonut: heidän ratsujensa vuohisjänteet hän katkoi, ja heidän vaununsa hän poltti tulessa.'),
(1675037,58,6,11,10,'Sitten Joosua kääntyi takaisin ja valloitti Haasorin ja surmasi miekalla sen kuninkaan; Haasor oli näet muinoin kaikkien näiden kuningaskuntien pääkaupunki.'),
(1675038,58,6,11,11,'Ja he surmasivat miekan terällä ja vihkivät tuhon omaksi jokaisen, joka siellä oli, niin ettei jäänyt jäljelle ainoatakaan henkeä; ja Haasorin hän poltti tulella.'),
(1675039,58,6,11,12,'Kaikki nämä kuninkaankaupungit ja niiden kuninkaat Joosua sai valtaansa, ja hän surmasi miekan terällä niiden asukkaat, vihkien heidät tuhon omiksi, niinkuin Herran palvelija Mooses oli käskenyt.'),
(1675040,58,6,11,13,'Mutta kukkuloilla olevista kaupungeista Israel ei polttanut ainoatakaan, paitsi Haasorin, jonka Joosua poltti.'),
(1675041,58,6,11,14,'Ja kaiken, mitä näistä kaupungeista oli saatavana saalista, ynnä karjan israelilaiset ryöstivät itselleen; mutta kaikki ihmiset he surmasivat miekan terällä ja tuhosivat heidät, jättämättä eloon ainoatakaan henkeä.'),
(1675042,58,6,11,15,'Niinkuin Herra oli käskenyt palvelijaansa Moosesta, niin oli Mooses käskenyt Joosuaa, ja niin Joosua teki; eikä hän jättänyt tekemättä mitään kaikesta siitä, mistä Herra oli Moosekselle käskyn antanut.'),
(1675043,58,6,11,16,'Niin Joosua valloitti koko tämän maan, Vuoriston, koko Etelämaan ja koko Goosenin maakunnan, Alankomaan ja Aromaan, niin myös Israelin vuoriston ja sen alankomaan -'),
(1675044,58,6,11,17,'maan Seiriin päin kohoavasta Sileästä vuoresta aina Baal-Gaadiin saakka, Libanonin laaksoon, Hermonin vuoren juurelle; kaikki heidän kuninkaansa hän sai valtaansa ja löi heidät kuoliaaksi.'),
(1675045,58,6,11,18,'Kauan aikaa Joosua kävi sotaa kaikkia näitä kuninkaita vastaan.'),
(1675046,58,6,11,19,'Eikä ollut ainoatakaan kaupunkia, joka olisi tehnyt rauhan Israelin kanssa, paitsi ne hivviläiset, jotka asuivat Gibeonissa; vaan kaikki valloitettiin asevoimalla.'),
(1675047,58,6,11,20,'Sillä Herralta tämä tuli; hän paadutti heidän sydämensä, niin että he kävivät taisteluun Israelia vastaan, jotta heidät armotta vihittäisiin tuhon omiksi ja hävitettäisiin, niinkuin Herra oli Moosekselle käskyn antanut.'),
(1675048,58,6,11,21,'Siihen aikaan Joosua tuli ja hävitti anakilaiset vuoristosta, Hebronista, Debiristä ja Anabista, koko Juudan vuoristosta ja koko Israelin vuoristosta; Joosua vihki heidät kaupunkeineen tuhon omiksi.'),
(1675049,58,6,11,22,'Israelilaisten maahan ei jäänyt anakilaisia; ainoastaan Gassaan, Gatiin ja Asdodiin niitä jäi.'),
(1675050,58,6,11,23,'Näin Joosua valloitti koko maan, aivan niinkuin Herra oli Moosekselle puhunut; ja Joosua antoi sen perintöosaksi Israelille, heidän sukukunnilleen heidän osastojensa mukaan. Ja maa pääsi rauhaan sodasta.'),
(1675051,58,6,12,1,'Nämä olivat ne maan kuninkaat, jotka israelilaiset voittivat ja joiden maan he ottivat omakseen tuolla puolella Jordanin, auringonnousun puolella, maan Arnon-joesta aina Hermonin vuoreen saakka ja koko itäpuolisen Aromaan:'),
(1675052,58,6,12,2,'Siihon, amorilaisten kuningas, joka asui Hesbonissa ja hallitsi maata Arnon-joen rannalla olevasta Aroerista ja jokilaakson keskikohdalta, ja puolta Gileadia, Jabbok-jokeen saakka, joka on ammonilaisten rajana,'),
(1675053,58,6,12,3,'ja Aromaata aina Kinerotin järveen, sen itärantaan, saakka ja Aromaan mereen, Suolamereen, sen itärantaan, saakka, Beet-Jesimotin tienoille, ja etelään päin Pisgan rinteiden juurelle saakka.'),
(1675054,58,6,12,4,'Ja he ottivat omakseen Oogin, Baasanin kuninkaan, alueen, hänen, joka oli viimeisiä refalaisia ja asui Astarotissa ja Edreissä'),
(1675055,58,6,12,5,'ja hallitsi Hermonin vuorta, Salkaa ja koko Baasania gesurilaisten ja maakatilaisten alueeseen saakka ja toista puolta Gileadia, Hesbonin kuninkaan Siihonin alueeseen saakka.'),
(1675056,58,6,12,6,'Herran palvelija Mooses ja israelilaiset olivat voittaneet heidät; ja Herran palvelija Mooses oli antanut maan omaksi ruubenilaisille ja gaadilaisille ja toiselle puolelle Manassen sukukuntaa.'),
(1675057,58,6,12,7,'Ja nämä olivat ne maan kuninkaat, jotka Joosua ja israelilaiset voittivat tällä puolella Jordanin, länsipuolella, Libanonin laaksossa olevasta Baal-Gaadista aina Seiriin päin kohoavaan Sileään vuoreen saakka, ja joiden maan Joosua antoi Israelin sukukuntien omaksi, heidän osastojensa mukaan,'),
(1675058,58,6,12,8,'Vuoristossa, Alankomaassa, Aromaassa, Rinnemaissa, Erämaassa ja Etelämaassa, heettiläisten, amorilaisten, kanaanilaisten, perissiläisten, hivviläisten ja jebusilaisten maan:'),
(1675059,58,6,12,9,'Jerikon kuningas yksi, lähellä Beeteliä olevan Ain kuningas yksi,'),
(1675060,58,6,12,10,'Jerusalemin kuningas yksi, Hebronin kuningas yksi,'),
(1675061,58,6,12,11,'Jarmutin kuningas yksi, Laakiin kuningas yksi,'),
(1675062,58,6,12,12,'Eglonin kuningas yksi, Geserin kuningas yksi,'),
(1675063,58,6,12,13,'Debirin kuningas yksi, Gederin kuningas yksi,'),
(1675064,58,6,12,14,'Horman kuningas yksi, Aradin kuningas yksi,'),
(1675065,58,6,12,15,'Libnan kuningas yksi, Adullamin kuningas yksi,'),
(1675066,58,6,12,16,'Makkedan kuningas yksi, Beetelin kuningas yksi,'),
(1675067,58,6,12,17,'Tappuahin kuningas yksi, Heeferin kuningas yksi,'),
(1675068,58,6,12,18,'Afekin kuningas yksi, Lassaronin kuningas yksi,'),
(1675069,58,6,12,19,'Maadonin kuningas yksi, Haasorin kuningas yksi,'),
(1675070,58,6,12,20,'Simron-Meronin kuningas yksi, Aksafin kuningas yksi,'),
(1675071,58,6,12,21,'Taanakin kuningas yksi, Megiddon kuningas yksi,'),
(1675072,58,6,12,22,'Kedeksen kuningas yksi, Karmelin juurella olevan Jokneamin kuningas yksi,'),
(1675073,58,6,12,23,'Doorin kukkuloilla olevan Doorin kuningas yksi, Gilgalin seudun pakanain kuningas yksi,'),
(1675074,58,6,12,24,'Tirsan kuningas yksi. Kaikkiaan kolmekymmentä yksi kuningasta.'),
(1675075,58,6,13,1,'Kun Joosua oli käynyt vanhaksi ja iäkkääksi, sanoi Herra hänelle: "Sinä olet käynyt vanhaksi ja iäkkääksi, mutta vielä on hyvin paljon maata valtaamatta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675076,58,6,13,2,'Tämä on se maa, mikä vielä on jäljellä: kaikki filistealaisten alueet ja koko gesurilaisten maa.'),
(1675077,58,6,13,3,'Siihorista alkaen, joka on itään päin Egyptistä, aina Ekronin alueeseen saakka pohjoiseen päin - se luetaan kanaanilaisten alueeseen - ne viisi filistealaista ruhtinasta, nimittäin Gassan, Asdodin, Askelonin, Gatin ja Ekronin ruhtinaat, niin myöskin avvilaiset'),
(1675078,58,6,13,4,'etelässä päin; koko kanaanilaisten maa ja Meara, joka on siidonilaisten, Afekiin saakka, amorilaisten alueeseen saakka;'),
(1675079,58,6,13,5,'ja gebalilaisten maa ja koko Libanon, auringonnousun puolella, Hermonin vuoren juurella olevasta Baal-Gaadista siihen saakka, mistä mennään Hamatiin.'),
(1675080,58,6,13,6,'Kaikki vuoriston asukkaat Libanonista Misrefot-Majimiin saakka, kaikki siidonilaiset, minä karkoitan israelilaisten tieltä; arvo vain niiden maa Israelin kesken perintöosaksi, niinkuin minä olen sinulle käskyn antanut.'),
(1675081,58,6,13,7,'Jaa siis tämä maa perintöosana yhdeksälle sukukunnalle ja toiselle puolelle Manassen sukukuntaa."'),
(1675082,58,6,13,8,'Samalla kuin sen toinen puoli olivat näet myöskin ruubenilaiset ja gaadilaiset saaneet perintöosansa, jonka Mooses antoi heille tuolta puolelta Jordanin, idän puolelta, niinkuin Herran palvelija Mooses sen heille antoi,'),
(1675083,58,6,13,9,'maan Arnon-joen rannalla olevasta Aroerista ja jokilaakson keskikohdalla olevasta kaupungista alkaen ja koko Meedeban ylätasangon Diiboniin saakka;'),
(1675084,58,6,13,10,'ja kaikki Siihonin, amorilaisten kuninkaan, kaupungit, hänen, joka hallitsi Hesbonissa, aina ammonilaisten alueeseen saakka,'),
(1675085,58,6,13,11,'ja Gileadin sekä gesurilaisten ja maakatilaisten alueet ja koko Hermonin vuoren ja koko Baasanin Salkaan saakka,'),
(1675086,58,6,13,12,'koko Oogin valtakunnan Baasanissa, hänen, joka hallitsi Astarotissa ja Edreissä ja oli viimeisiä refalaisia; nämä Mooses voitti ja karkoitti.'),
(1675087,58,6,13,13,'Mutta israelilaiset eivät karkoittaneet gesurilaisia ja maakatilaisia, vaan gesurilaiset ja maakatilaiset jäivät asumaan Israelin keskeen aina tähän päivään asti.'),
(1675088,58,6,13,14,'Ainoastaan Leevin sukukunnalle hän ei antanut perintöosaa. Herran, Israelin Jumalan, uhrit ovat sen perintöosa, niinkuin hän on sille puhunut.'),
(1675089,58,6,13,15,'Mooses antoi ruubenilaisten sukukunnalle, heidän suvuilleen, maata:'),
(1675090,58,6,13,16,'heille tuli alue Arnon-joen rannalla olevasta Aroerista ja jokilaakson keskikohdalla olevasta kaupungista alkaen ja koko ylätasanko Meedeban luona;'),
(1675091,58,6,13,17,'Hesbon ynnä kaikki sen alaiset kaupungit, jotka ovat ylätasangolla, Diibon, Baamot-Baal, Beet-Baal-Meon,'),
(1675092,58,6,13,18,'Jahas, Kedemot, Meefaat,'),
(1675093,58,6,13,19,'Kirjataim, Sibma, Seret-Sahar Laaksovuorella,'),
(1675094,58,6,13,20,'Beet-Peor ja Pisgan rinteet ja Beet-Jesimot;'),
(1675095,58,6,13,21,'ja kaikki ylätasangon kaupungit ja Siihonin, amorilaisten kuninkaan, koko valtakunta, hänen, joka hallitsi Hesbonissa ja jonka Mooses voitti samalla kuin Midianin ruhtinaat Evin, Rekemin, Suurin, Huurin ja Reban, jotka olivat Siihonin aliruhtinaita ja asuivat siinä maassa.'),
(1675096,58,6,13,22,'Muiden mukana, jotka kaatuivat, israelilaiset surmasivat miekalla myöskin Bileamin, Beorin pojan, tietäjän.'),
(1675097,58,6,13,23,'Ruubenilaisten raja on Jordan; se on rajana. Tämä on ruubenilaisten, heidän sukujensa, perintöosa, kaupungit kylineen.'),
(1675098,58,6,13,24,'Mooses antoi Gaadin sukukunnalle, gaadilaisille, heidän suvuilleen, maata:'),
(1675099,58,6,13,25,'heidän alueekseen tuli Jaeser, ja kaikki Gileadin kaupungit ja puolet ammonilaisten maata Aroeriin asti, joka on itään päin Rabbasta,'),
(1675100,58,6,13,26,'ja maa Hesbonista Raamat-Mispeen ja Betonimiin saakka, ja Mahanaimista Lidebirin alueeseen saakka;'),
(1675101,58,6,13,27,'ja laaksossa: Beet-Raam, Beet-Nimra, Sukkot ja Saafon, loput Siihonin, Hesbonin kuninkaan, valtakunnasta, rajana Jordan Kinneretin järven päähän saakka, tuolla puolella Jordanin, idän puolella.'),
(1675102,58,6,13,28,'Tämä on gaadilaisten, heidän sukujensa, perintöosa, kaupungit kylineen.'),
(1675103,58,6,13,29,'Mooses antoi toiselle puolelle Manassen sukukuntaa maata, ja se tuli toiselle puolelle Manassen sukukuntaa, heidän suvuilleen:'),
(1675104,58,6,13,30,'heidän alueekseen tuli Mahanaimista alkaen koko Baasan, Oogin, Baasanin kuninkaan, koko valtakunta, kaikki Jaairin leirikylät Baasanissa, kuusikymmentä kaupunkia,'),
(1675105,58,6,13,31,'ja puolet Gileadia sekä Astarot ja Edrei, Oogin valtakunnan pääkaupungit Baasanissa; tämä tuli Maakirin, Manassen pojan, jälkeläisille, toiselle puolelle Maakirin jälkeläisiä, heidän suvuilleen.'),
(1675106,58,6,13,32,'Nämä ovat ne alueet, jotka Mooses jakoi perintöosiksi Mooabin arolla, tuolla puolella Jordanin, Jerikon kohdalla, idän puolella.'),
(1675107,58,6,13,33,'Mutta Leevin sukukunnalle Mooses ei antanut perintöosaa. Herra, Israelin Jumala, on heidän perintöosansa, niinkuin hän on heille puhunut.'),
(1675108,58,6,14,1,'Nämä ovat ne alueet, jotka israelilaiset saivat perintöosiksi Kanaanin maassa, ne, jotka pappi Eleasar ja Joosua, Nuunin poika, ja israelilaisten sukukuntien perhekunta-päämiehet jakoivat heille'),
(1675109,58,6,14,2,'arvalla perintöosiksi sen käskyn mukaisesti, jonka Herra oli yhdeksästä ja puolesta sukukunnasta antanut Mooseksen kautta.'),
(1675110,58,6,14,3,'Sillä Mooses oli antanut kahdelle ja puolelle sukukunnalle perintöosat tuolta puolelta Jordanin, mutta leeviläisille hän ei antanut perintöosaa heidän keskellänsä.'),
(1675111,58,6,14,4,'Sillä joosefilaisia oli kaksi sukukuntaa, Manasse ja Efraim; ja leeviläisille ei annettu osuutta maahan, vaan ainoastaan kaupunkeja heidän asuaksensa sekä niiden laidunmaat heidän karjaansa ja omaisuuttansa varten.'),
(1675112,58,6,14,5,'Niinkuin Herra oli Moosekselle käskyn antanut, niin israelilaiset tekivät ja jakoivat maan.'),
(1675113,58,6,14,6,'Silloin juudalaiset astuivat Joosuan eteen Gilgalissa, ja kenissiläinen Kaaleb, Jefunnen poika, sanoi hänelle: "Sinä tunnet sen sanan, jonka Herra puhui Jumalan miehelle Moosekselle minusta ja sinusta Kaades-Barneassa.'),
(1675114,58,6,14,7,'Minä olin neljänkymmenen vuoden vanha, kun Herran palvelija Mooses lähetti minut Kaades-Barneasta vakoilemaan maata, ja minä annoin hänelle tietoja parhaan ymmärrykseni mukaan.'),
(1675115,58,6,14,8,'Mutta veljeni, jotka olivat käyneet siellä minun kanssani, saivat kansan sydämen raukeamaan, kun taas minä uskollisesti seurasin Herraa, Jumalaani.'),
(1675116,58,6,14,9,'Sinä päivänä Mooses vannoi sanoen: ''Totisesti, se maa, johon sinä olet jalkasi astunut, on tuleva sinulle ja sinun lapsillesi perintöosaksi ikiaikoihin asti, koska sinä olet uskollisesti seurannut Herraa, minun Jumalaani''.'),
(1675117,58,6,14,10,'Ja nyt, katso, Herra on antanut minun elää, niinkuin hän oli sanonut, vielä neljäkymmentä viisi vuotta sen jälkeen, kuin Herra puhui tämän sanan Moosekselle, Israelin vaeltaessa erämaassa. Ja katso, minä olen nyt kahdeksankymmenen viiden vuoden vanha'),
(1675118,58,6,14,11,'ja olen vielä tänä päivänä yhtä voimakas, kuin olin sinä päivänä, jona Mooses minut lähetti; niinkuin voimani oli silloin, niin se on vielä nytkin: minä kykenen sotimaan, lähtemään ja tulemaan.'),
(1675119,58,6,14,12,'Anna minulle siis tämä vuoristo, josta Herra puhui sinä päivänä. Sinähän kuulit sinä päivänä, että siellä asuu anakilaisia ja että siellä on suuria, varustettuja kaupunkeja. Kenties Herra on minun kanssani, niin että minä saan heidät karkoitetuksi, niinkuin Herra on puhunut."'),
(1675120,58,6,14,13,'Silloin Joosua siunasi Kaalebin, Jefunnen pojan, ja antoi hänelle perintöosaksi Hebronin.'),
(1675121,58,6,14,14,'Niin Hebron tuli kenissiläisen Kaalebin, Jefunnen pojan, perintöosaksi, niinkuin se on tänäkin päivänä, sentähden että hän oli uskollisesti seurannut Herraa, Israelin Jumalaa.'),
(1675122,58,6,14,15,'Mutta Hebronin nimi oli muinoin Kirjat-Arba, Arban mukaan, joka oli mahtavin mies anakilaisten joukossa. Ja maa pääsi rauhaan sodasta.'),
(1675123,58,6,15,1,'Juudan jälkeläisten sukukunta, heidän sukunsa, saivat arpaosansa etelästä, Edomin rajaan ja Siinin erämaahan päin, etäisintä etelää myöten.'),
(1675124,58,6,15,2,'Heidän eteläinen rajansa alkaa Suolameren päästä, sen eteläisimmästä pohjukasta,'),
(1675125,58,6,15,3,'jatkuu Skorpionisolan eteläpuolitse, kulkee Siiniin, nousee Kaades-Barnean eteläpuolitse, kulkee Hesroniin, nousee Addariin ja kääntyy Karkaan päin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675126,58,6,15,4,'Edelleen se kulkee Asmoniin ja jatkuu Egyptin puroon; sitten raja päättyy mereen. Tämä olkoon teidän eteläinen rajanne.'),
(1675127,58,6,15,5,'Itäisenä rajana on Suolameri Jordanin suuhun saakka. Pohjoinen raja alkaa siitä meren pohjukasta, jossa on Jordanin suu.'),
(1675128,58,6,15,6,'Sieltä raja nousee Beet-Hoglaan ja kulkee Beet-Araban pohjoispuolitse; edelleen raja nousee Boohanin, Ruubenin pojan, kiveen.'),
(1675129,58,6,15,7,'Sitten raja nousee Debiriin Aakorin laaksosta ja kääntyy pohjoiseen päin Gilgalia kohti, joka on vastapäätä puron eteläpuolella olevaa Adummimin solaa; sitten raja kulkee Een-Semeksen veteen ja päättyy Roogelin lähteeseen.'),
(1675130,58,6,15,8,'Edelleen raja nousee Ben-Hinnomin laaksoon, Jebusilaiskukkulan, se on Jerusalemin, eteläpuolitse. Sitten raja nousee sen vuoren laelle, joka on vastapäätä Hinnomin laaksoa, lännessä päin, Refaimin tasangon pohjoisessa laidassa.'),
(1675131,58,6,15,9,'Tämän vuoren laelta raja kaartuu Neftoahin veden lähteelle ja jatkuu Efronin vuoren kaupunkeihin, ja sitten raja kaartuu Baalaan, se on Kirjat-Jearimiin.'),
(1675132,58,6,15,10,'Baalasta raja kääntyy länteen päin Seirin vuoreen, kulkee Jearimin vuoren kukkulan, se on Kesalonin, pohjoispuolitse, laskeutuu Beet-Semekseen ja kulkee sitten Timnaan.'),
(1675133,58,6,15,11,'Edelleen raja jatkuu Ekronin kukkulaan, pohjoiseen päin; sitten raja kaartuu Sikkeroniin, kulkee Baala-vuoreen ja jatkuu Jabneeliin; sitten raja päättyy mereen.'),
(1675134,58,6,15,12,'Ja läntisenä rajana on Suuri meri; se on rajana. Nämä ovat Juudan jälkeläisten, heidän sukukuntiensa, rajat yltympäri.'),
(1675135,58,6,15,13,'Mutta Kaalebille, Jefunnen pojalle, Joosua antoi, niinkuin Herra oli häntä käskenyt, osuuden Juudan jälkeläisten keskuudessa, Kirjat-Arban, anakilaisten isän Arban kaupungin, se on Hebronin.'),
(1675136,58,6,15,14,'Ja Kaaleb karkoitti sieltä kolme anakilaista, Anakin jälkeläiset Seesain, Ahimanin ja Talmain,'),
(1675137,58,6,15,15,'ja lähti sieltä Debirin asukkaita vastaan; mutta Debirin nimi oli muinoin Kirjat-Seefer.'),
(1675138,58,6,15,16,'Silloin Kaaleb sanoi: "Joka voittaa ja valloittaa Kirjat-Seeferin, sille minä annan tyttäreni Aksan vaimoksi".'),
(1675139,58,6,15,17,'Niin Otniel, Kenaan, Kaalebin veljen, poika, valloitti sen; ja hän antoi tälle tyttärensä Aksan vaimoksi.'),
(1675140,58,6,15,18,'Ja kun Aksa tuli, niin hän yllytti miestänsä, että tämä pyytäisi hänen isältänsä peltomaata; ja Aksa pudottautui aasin selästä maahan. Silloin Kaaleb sanoi hänelle: "Mikä sinun on?"'),
(1675141,58,6,15,19,'Niin hän vastasi: "Anna minulle jäähyväislahja, sillä sinä olet naittanut minut kuivaan maahan; anna siis minulle vesilähteitä". Silloin hän antoi hänelle Ylälähteet ja Alalähteet.'),
(1675142,58,6,15,20,'Tämä on Juudan jälkeläisten sukukunnan, heidän sukujensa, perintöosa.'),
(1675143,58,6,15,21,'Juudan jälkeläisten sukukunnan etäisimmät kaupungit Edomin rajalla Etelämaassa ovat: Kabseel, Eeder, Jaagur,'),
(1675144,58,6,15,22,'Kiina, Diimona, Adada,'),
(1675145,58,6,15,23,'Kedes, Haasor, Jitnan,'),
(1675146,58,6,15,24,'Siif, Telem, Bealot,'),
(1675147,58,6,15,25,'Haasor-Hadatta, Kerijot-Hesron, se on Haasor,'),
(1675148,58,6,15,26,'Amam, Sema, Moolada,'),
(1675149,58,6,15,27,'Hasar-Gadda, Hesmon, Beet-Pelet,'),
(1675150,58,6,15,28,'Hasar-Suual, Beerseba ja Bisjotja,'),
(1675151,58,6,15,29,'Baala, Ijjim, Esem,'),
(1675152,58,6,15,30,'Eltolad, Kesil, Horma,'),
(1675153,58,6,15,31,'Siklag, Madmanna, Sansanna,'),
(1675154,58,6,15,32,'Lebaot, Silhim, Ain ja Rimmon - kaikkiaan kaksikymmentä yhdeksän kaupunkia kylineen.'),
(1675155,58,6,15,33,'Alankomaassa: Estaol, Sora, Asna,'),
(1675156,58,6,15,34,'Saanoah, Een-Gannim, Tappuah, Eenam,'),
(1675157,58,6,15,35,'Jarmut, Adullam, Sooko, Aseka,'),
(1675158,58,6,15,36,'Saaraim, Aditaim, Gedera ja Gederotaim - neljätoista kaupunkia kylineen;'),
(1675159,58,6,15,37,'Senan, Hadasa, Migdal-Gaad,'),
(1675160,58,6,15,38,'Dilan, Mispe, Jokteel,'),
(1675161,58,6,15,39,'Laakis, Boskat, Eglon,'),
(1675162,58,6,15,40,'Kabbon, Lahmas, Kitlis,'),
(1675163,58,6,15,41,'Gederot, Beet-Daagon, Naema ja Makkeda - kuusitoista kaupunkia kylineen;'),
(1675164,58,6,15,42,'Libna, Eter, Aasan,'),
(1675165,58,6,15,43,'Jiftah, Asna, Nesib,'),
(1675166,58,6,15,44,'Kegila, Aksib ja Maaresa - yhdeksän kaupunkia kylineen;'),
(1675167,58,6,15,45,'Ekron ja sen tytärkaupungit ja kylät;'),
(1675168,58,6,15,46,'koko se alue kylineen, joka on Asdodin puolella Ekronista mereen kulkevaa rajaa;'),
(1675169,58,6,15,47,'Asdod ja sen tytärkaupungit ja kylät; Gassa ja sen tytärkaupungit ja kylät Egyptin puroon asti. Ja Suuri meri on rajana.'),
(1675170,58,6,15,48,'Ja vuoristossa: Saamir, Jattir, Sooko,'),
(1675171,58,6,15,49,'Danna, Kirjat-Sanna, se on Debir;'),
(1675172,58,6,15,50,'Anab, Estemo, Aanim;'),
(1675173,58,6,15,51,'Goosen, Hoolon ja Giilo - yksitoista kaupunkia kylineen;'),
(1675174,58,6,15,52,'Arab, Duuma, Esan,'),
(1675175,58,6,15,53,'Jaanum, Beet-Tappuah, Afeka,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675176,58,6,15,54,'Humta, Kirjat-Arba, se on Hebron, ja Siior - yhdeksän kaupunkia kylineen;'),
(1675177,58,6,15,55,'Maaon, Karmel, Siif, Jutta,'),
(1675178,58,6,15,56,'Jisreel, Jokdeam ja Saanoah,'),
(1675179,58,6,15,57,'Kain, Gibea, Timna - kymmenen kaupunkia kylineen;'),
(1675180,58,6,15,58,'Halhul, Beet-Suur, Gedor,'),
(1675181,58,6,15,59,'Maarat, Beet-Anot ja Eltekon - kuusi kaupunkia kylineen;'),
(1675182,58,6,15,60,'Kirjat-Baal, se on Kirjat-Jearim, ja Rabba - kaksi kaupunkia kylineen.'),
(1675183,58,6,15,61,'Ja erämaassa: Beet-Araba, Middin, Sekaka,'),
(1675184,58,6,15,62,'Nibsan, Iir-Melah ja Een-Gedi - kuusi kaupunkia kylineen.'),
(1675185,58,6,15,63,'Mutta jebusilaisia, jotka asuivat Jerusalemissa, eivät Juudan jälkeläiset kyenneet karkoittamaan, ja niin jebusilaiset jäivät asumaan Juudan jälkeläisten sekaan, Jerusalemiin, aina tähän päivään asti.'),
(1675186,58,6,16,1,'Joosefilaisille määräsi arpa rajan kulkemaan idästä päin, Jerikon Jordanista, Jerikon veteen ja sieltä erämaahan, joka kohoaa Jerikosta vuoristoon Beeteliä kohti.'),
(1675187,58,6,16,2,'Beetelistä raja jatkuu Luusiin ja kulkee arkilaisten alueeseen, Atarotiin.'),
(1675188,58,6,16,3,'Sitten se laskeutuu länteen päin jafletilaisten alueeseen, aina alisen Beet-Hooronin alueeseen ja Geseriin asti ja päättyy mereen.'),
(1675189,58,6,16,4,'Joosefilaiset, Manasse ja Efraim, saivat perintöosakseen tämän:'),
(1675190,58,6,16,5,'Efraimilaisille, heidän suvuilleen, tuli seuraava alue: heidän perintöosansa itäinen raja kulkee Aterot-Addarista yliseen Beet-Hooroniin.'),
(1675191,58,6,16,6,'Sitten raja päättyy mereen. Pohjoisessa on Mikmetat rajana. Sieltä raja kääntyy itään päin Taanat-Siiloon ja menee sen itäpuolitse Janohaan.'),
(1675192,58,6,16,7,'Janohasta se laskeutuu Atarotiin ja Naaraan, koskettaa Jerikoa ja päättyy Jordaniin.'),
(1675193,58,6,16,8,'Tappuahista raja kulkee länteen päin Kaana-puroon ja päättyy mereen. Tämä on efraimilaisten sukukunnan, heidän sukujensa, perintöosa,'),
(1675194,58,6,16,9,'ja lisäksi ne kaupungit, jotka erotettiin efraimilaisille keskeltä manasselaisten perintöosaa, kaikki ne kaupungit kylineen.'),
(1675195,58,6,16,10,'Mutta he eivät karkoittaneet kanaanilaisia, jotka asuivat Geserissä; niin kanaanilaiset jäivät asumaan Efraimin keskeen aina tähän päivään asti, mutta joutuivat työveron alaisiksi.'),
(1675196,58,6,17,1,'Manassen sukukunta sai sekin arpaosansa, sillä hän oli Joosefin esikoinen. Maakir, Manassen esikoinen, Gileadin isä, sai Gileadin ja Baasanin, sillä hän oli sotilas.'),
(1675197,58,6,17,2,'Muutkin manasselaiset saivat osuutensa, suvuittain: abieserilaiset, heelekiläiset, asrielilaiset, sekemiläiset, heeferiläiset ja semidalaiset. Nämä ovat Manassen, Joosefin pojan, miespuoliset jälkeläiset, suvuittain.'),
(1675198,58,6,17,3,'Mutta Selofhadilla, Heeferin pojalla, joka oli Gileadin poika, joka Maakirin poika, joka Manassen poika, ei ollut poikia, vaan ainoastaan tyttäriä; ja nämä olivat hänen tyttäriensä nimet: Mahla, Nooga, Hogla, Milka ja Tirsa.'),
(1675199,58,6,17,4,'Nämä astuivat pappi Eleasarin ja Joosuan, Nuunin pojan, ja päämiesten eteen ja sanoivat: "Herra käski Mooseksen antaa meille perintöosan veljiemme keskuudessa". Silloin Joosua antoi heille Herran käskyn mukaisesti perintöosan heidän isänsä veljien keskuudessa.'),
(1675200,58,6,17,5,'Niin tuli Manasselle, paitsi Gileadin maata ja Baasania tuolla puolella Jordanin, kymmenen osaa,'),
(1675201,58,6,17,6,'koska Manassen tyttäret saivat perintöosan hänen poikiensa keskuudessa; mutta Gileadin maa joutui Manassen muille jälkeläisille.'),
(1675202,58,6,17,7,'Manassen raja kulkee Asserista Mikmetatiin, joka on Sikemin itäpuolella; sitten raja menee oikealle Een-Tappuahin asukkaiden tienoille.'),
(1675203,58,6,17,8,'Tappuahin maa joutui Manasselle, mutta Tappuah, Manassen rajalla, efraimilaisille.'),
(1675204,58,6,17,9,'Sitten raja laskeutuu Kaana-puroon, puron eteläpuolelle; mutta siellä, Manassen kaupunkien keskellä, olevat kaupungit joutuivat Efraimille. Sitten Manassen raja kulkee puron pohjoispuolelle ja päättyy mereen.'),
(1675205,58,6,17,10,'Eteläpuolella oleva maa joutui Efraimille, mutta pohjoispuolella oleva maa joutui Manasselle, ja meri on sen rajana. Ja pohjoisessa sen raja koskettaa Asseria ja idässä Isaskaria.'),
(1675206,58,6,17,11,'Isaskarista ja Asserista joutui Manasselle Beet-Sean ja sen tytärkaupungit, Jibleam ja sen tytärkaupungit, Doorin asukkaat ja sen tytärkaupungit, Een-Doorin asukkaat ja sen tytärkaupungit, Taanakin asukkaat ja sen tytärkaupungit, Megiddon asukkaat ja sen tytärkaupungit, kolme kukkulaa.'),
(1675207,58,6,17,12,'Mutta manasselaiset eivät kyenneet ottamaan haltuunsa näitä kaupunkeja, vaan kanaanilaisten onnistui jäädä asumaan siihen maahan.'),
(1675208,58,6,17,13,'Kun israelilaiset sitten voimistuivat, saattoivat he kanaanilaiset työveron alaisiksi, mutta eivät karkoittaneet heitä.'),
(1675209,58,6,17,14,'Joosefilaiset puhuivat Joosualle sanoen: "Miksi sinä olet antanut minulle perintöosaksi vain yhden arvan ja yhden osan, vaikka minä olen lukuisa kansa, kun Herra aina tähän asti on minua siunannut?"'),
(1675210,58,6,17,15,'Silloin Joosua sanoi heille: "Jos sinä olet niin lukuisa kansa, niin mene metsäseutuun ja raivaa itsellesi maata sieltä, perissiläisten ja refalaisten maasta, kun kerran Efraimin vuoristo on sinulle liian ahdas".'),
(1675211,58,6,17,16,'Mutta joosefilaiset vastasivat: "Ei vuoristo riitä meille; ja kaikilla kanaanilaisilla, jotka asuvat tasangoilla, on raudoitettuja sotavaunuja, sekä niillä, jotka asuvat Beet-Seanissa ja sen tytärkaupungeissa, että niillä, jotka asuvat Jisreelin tasangolla".'),
(1675212,58,6,17,17,'Silloin Joosua sanoi Joosefin heimolle, Efraimille ja Manasselle, näin: "Sinä olet lukuisa kansa ja sinun voimasi on suuri; sinua ei ole jätettävä yhdelle ainoalle arpaosalle,'),
(1675213,58,6,17,18,'vaan vuoristo on tuleva sinun omaksesi. Koska se on metsäseutua, on sinun raivattava se, ja sen laitapuoletkin tulevat sinun omiksesi. Sillä sinun on karkoitettava kanaanilaiset, vaikka heillä on raudoitettuja sotavaunuja ja vaikka he ovat voimakkaat."'),
(1675214,58,6,18,1,'Ja kaikki israelilaisten seurakunta kokoontui Siiloon, ja he pystyttivät sinne ilmestysmajan, sittenkuin maa oli tullut heille alamaiseksi.'),
(1675215,58,6,18,2,'Mutta vielä oli israelilaisista jäljellä seitsemän sukukuntaa, joiden perintöosa oli jakamatta.'),
(1675216,58,6,18,3,'Niin Joosua sanoi israelilaisille: "Kuinka kauan hidastelette ettekä mene ottamaan omaksenne maata, jonka Herra, teidän isienne Jumala, on teille antanut?'),
(1675217,58,6,18,4,'Tuokaa tänne jokaisesta sukukunnasta kolme miestä, niin minä lähetän heidät menemään ja kiertelemään maata ja panemaan sen kirjaan heidän perintöosiaan silmällä pitäen; ja tulkoot he sitten takaisin minun luokseni.'),
(1675218,58,6,18,5,'He jakakoot maan seitsemään osaan. Juuda pysyköön alueellaan etelässä, ja Joosefin heimo pysyköön alueellaan pohjoisessa.'),
(1675219,58,6,18,6,'Pankaa maa, ne seitsemän osaa, kirjaan ja tuokaa kirja tänne minulle, niin minä heitän teidän puolestanne arpaa täällä Herran, meidän Jumalamme, edessä.'),
(1675220,58,6,18,7,'Sillä leeviläisillä ei ole osuutta teidän keskuudessanne, vaan Herran pappeus on heidän perintöosansa; ja Gaad ja Ruuben ja toinen puoli Manassen sukukuntaa saivat tuolta puolelta Jordanin, idän puolelta, perintöosansa, jonka Herran palvelija Mooses heille antoi."'),
(1675221,58,6,18,8,'Niin miehet nousivat ja lähtivät; ja Joosua käski lähtevien panna kirjaan maan, sanoen: "Menkää ja kierrelkää maa ja pankaa se kirjaan ja palatkaa sitten minun luokseni, niin minä heitän teidän puolestanne arpaa täällä Herran edessä Siilossa".'),
(1675222,58,6,18,9,'Ja miehet lähtivät, kulkivat kautta maan ja panivat sen kirjaan kaupunki kaupungilta, seitsemänä osana, ja tulivat takaisin Joosuan luo Siilon leiriin.'),
(1675223,58,6,18,10,'Ja Joosua heitti heidän puolestaan arpaa Siilossa Herran edessä, ja Joosua jakoi siellä maan israelilaisille, heidän osastojensa mukaan.'),
(1675224,58,6,18,11,'Ja arpa nousi benjaminilaisten sukukunnalle, heidän suvuilleen; ja heidän arvalla saamansa alue oli Juudan jälkeläisten ja joosefilaisten välillä.'),
(1675225,58,6,18,12,'Heidän pohjoinen rajansa lähtee Jordanista, ja raja nousee Jerikon pohjoispuolella olevalle kukkulalle ja nousee vuoristoon, länteen päin, ja päättyy Beet-Aavenin erämaahan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675226,58,6,18,13,'Sieltä raja kulkee Luusiin, Luusin eteläpuolella olevaan kukkulaan, se on Beeteliin; sitten raja laskeutuu Aterot-Addariin vuoren yli, joka on alisen Beet-Hooronin eteläpuolella.'),
(1675227,58,6,18,14,'Sitten raja kaartuu ja kääntyy läntisenä rajana etelään päin siitä vuoresta, joka on vastapäätä Beet-Hooronia, sen eteläpuolella, ja päättyy Kirjat-Baaliin, se on Kirjat-Jearimiin, Juudan jälkeläisten kaupunkiin. Tämä on läntinen raja.'),
(1675228,58,6,18,15,'Mutta eteläinen raja lähtee Kirjat-Jearimin laidasta, lännen puolelta, ja jatkuu Neftoahin veden lähteelle.'),
(1675229,58,6,18,16,'Sitten raja laskeutuu sen vuoren päähän, joka on vastapäätä Ben-Hinnomin laaksoa, Refaimin tasangon pohjoisessa laidassa; sieltä se laskeutuu Hinnomin laaksoon Jebusilaiskukkulan eteläpuolitse ja edelleen Roogelin lähteelle.'),
(1675230,58,6,18,17,'Sitten se kaartuu pohjoiseen päin ja jatkuu Een-Semekseen ja edelleen kivitarhoille, jotka ovat vastapäätä Adummimin solaa, ja laskeutuu Boohanin, Ruubenin pojan, kiveen.'),
(1675231,58,6,18,18,'Edelleen se kulkee Aromaahan päin olevan kukkulan pohjoispuolitse ja laskeutuu Aromaalle.'),
(1675232,58,6,18,19,'Sitten raja kulkee Beet-Hoglan kukkulan pohjoispuolitse, ja raja päättyy Suolameren pohjoiseen pohjukkaan, Jordanin eteläpäähän. Tämä on eteläinen raja.'),
(1675233,58,6,18,20,'Mutta idän puolella on Jordan rajana. Tämä on benjaminilaisten, heidän sukujensa, perintöosa rajoineen yltympäri.'),
(1675234,58,6,18,21,'Ja benjaminilaisten sukukunnan, heidän sukujensa, kaupungit ovat: Jeriko, Beet-Hogla, Eemek-Kesis,'),
(1675235,58,6,18,22,'Beet-Araba, Semaraim, Beetel,'),
(1675236,58,6,18,23,'Avvim, Paara, Ofra,'),
(1675237,58,6,18,24,'Kefar-Ammoni, Ofni ja Geba - kaksitoista kaupunkia kylineen;'),
(1675238,58,6,18,25,'Gibeon, Raama, Beerot,'),
(1675239,58,6,18,26,'Mispe, Kefira, Moosa,'),
(1675240,58,6,18,27,'Rekem, Jirpeel, Tarala,'),
(1675241,58,6,18,28,'Seela, Elef, Jebus, se on Jerusalem, Gibeat ja Kirjat - neljätoista kaupunkia kylineen. Tämä on benjaminilaisten, heidän sukujensa, perintöosa.'),
(1675242,58,6,19,1,'Toinen arpa tuli Simeonille, simeonilaisten sukukunnalle, heidän suvuillensa; ja heidän perintöosansa tuli olemaan keskellä Juudan jälkeläisten perintöosaa.'),
(1675243,58,6,19,2,'Heidän perintöosakseen tuli: Beerseba, Seba, Moolada,'),
(1675244,58,6,19,3,'Hasar-Suual, Baala, Esem,'),
(1675245,58,6,19,4,'Eltolad, Betul, Horma,'),
(1675246,58,6,19,5,'Siklag, Beet-Markabot, Hasar-Suusa,'),
(1675247,58,6,19,6,'Beet-Lebaot ja Saaruhen - kolmetoista kaupunkia kylineen;'),
(1675248,58,6,19,7,'Ain, Rimmon, Eeter ja Aasan - neljä kaupunkia kylineen;'),
(1675249,58,6,19,8,'sitten kaikki ne kylät, jotka ovat näiden kaupunkien ympärillä, aina Baalat-Beeriin, Etelämaan Raamaan, saakka. Tämä on simeonilaisten sukukunnan, heidän sukujensa, perintöosa.'),
(1675250,58,6,19,9,'Juudan jälkeläisten osasta saivat simeonilaiset perintöosansa, sillä Juudan jälkeläisille oli heidän osuutensa liian suuri; niin simeonilaiset saivat perintöosansa heidän perintöosansa keskeltä.'),
(1675251,58,6,19,10,'Kolmas arpa nousi sebulonilaisille, heidän suvuillensa, ja heidän perintöosansa alue tuli ulottumaan Saaridiin saakka.'),
(1675252,58,6,19,11,'Länteen päin nousee heidän rajansa Maralaan, koskettaa Dabbesetia ja sitä puroa, joka on Jokneamin itäpuolella.'),
(1675253,58,6,19,12,'Itään päin, auringonnousuun päin, kääntyy raja Saaridista Kislot-Taaborin alueelle ja jatkuu Daberatiin ja nousee Jaafiaan.'),
(1675254,58,6,19,13,'Sieltä se kulkee itään päin, auringonnousuun päin, Gat-Heeferiin ja Eet-Kasiniin ja jatkuu Rimmoniin, joka ulottuu Neegaan.'),
(1675255,58,6,19,14,'Sitten raja kääntyy sen pohjoispuolitse Hannatoniin ja päättyy Jiftah-Eelin laaksoon.'),
(1675256,58,6,19,15,'Kattat, Nahalal, Simron, Jidala ja Beetlehem - kaksitoista kaupunkia kylineen.'),
(1675257,58,6,19,16,'Tämä on sebulonilaisten, heidän sukujensa, perintöosa, nämä kaupungit kylineen.'),
(1675258,58,6,19,17,'Neljäs arpa tuli Isaskarille, isaskarilaisille, heidän suvuilleen.'),
(1675259,58,6,19,18,'Ja heidän alueellaan tuli olemaan Jisreel, Kesullot, Suunem,'),
(1675260,58,6,19,19,'Hafaraim, Siion, Anaharat,'),
(1675261,58,6,19,20,'Rabbit, Kisjon, Ebes,'),
(1675262,58,6,19,21,'Remet, Een-Gannim, Een-Hadda ja Beet-Passes;'),
(1675263,58,6,19,22,'ja raja koskettaa Taaboria, Sahasimia, Beet-Semestä, ja heidän rajansa päättyy Jordaniin - kuusitoista kaupunkia kylineen.'),
(1675264,58,6,19,23,'Tämä on isaskarilaisten sukukunnan, heidän sukujensa, perintöosa, kaupungit kylineen.'),
(1675265,58,6,19,24,'Viides arpa tuli asserilaisten sukukunnalle, heidän suvuillensa.'),
(1675266,58,6,19,25,'Ja heidän alueellaan tuli olemaan Helkat, Hali, Beten ja Aksaf,'),
(1675267,58,6,19,26,'Alammelek, Amad ja Misal; ja lännessä raja koskettaa Karmelia ja Siihor-Libnatia,'),
(1675268,58,6,19,27,'kääntyy sitten auringonnousuun päin Beet-Daagoniin ja koskettaa Sebulonia ja Jiftah-Eelin laaksoa pohjoisessa, Beet-Eemekiä ja Negieliä ja jatkuu Kaabulin pohjoispuolitse'),
(1675269,58,6,19,28,'Ebroniin, Rehobiin, Hammoniin ja Kaanaan, aina suureen Siidoniin saakka.'),
(1675270,58,6,19,29,'Sitten raja kääntyy Raamaan ja menee Tyyron varustettuun kaupunkiin saakka; sitten raja kääntyy Hoosaan ja päättyy mereen, Heebelistä Aksibiin.'),
(1675271,58,6,19,30,'Umma, Afek ja Rehob - kaksikymmentä kaksi kaupunkia kylineen.'),
(1675272,58,6,19,31,'Tämä on asserilaisten sukukunnan, heidän sukujensa, perintöosa, nämä kaupungit kylineen.'),
(1675273,58,6,19,32,'Kuudes arpa tuli naftalilaisille, naftalilaisten suvuille.'),
(1675274,58,6,19,33,'Ja heidän rajansa tuli kulkemaan Heelefistä, Saanannimin tammesta, Adami-Nekebin ja Jabneelin kautta Lakkumiin asti ja päättyy Jordaniin.'),
(1675275,58,6,19,34,'Ja raja kääntyy länteen päin Asnot-Taaboriin ja jatkuu sieltä Hukkokiin ja koskettaa etelässä Sebulonia, lännessä Asseria ja idässä Juudaa Jordanin luona.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675276,58,6,19,35,'Varustettuja kaupunkeja ovat: Siddim, Seer, Hammat, Rakkat, Kinneret,'),
(1675277,58,6,19,36,'Adama, Raama, Haasor,'),
(1675278,58,6,19,37,'Kedes, Edrei, Een-Haasor,'),
(1675279,58,6,19,38,'Jireon, Migdal-Eel, Horem, Beet-Anat ja Beet-Semes - yhdeksäntoista kaupunkia kylineen.'),
(1675280,58,6,19,39,'Tämä on naftalilaisten sukukunnan, heidän sukujensa, perintöosa, kaupungit kylineen.'),
(1675281,58,6,19,40,'Seitsemäs arpa tuli daanilaisten sukukunnalle, heidän suvuilleen.'),
(1675282,58,6,19,41,'Heidän perintöosansa alueella tuli olemaan Sora, Estaol, Iir-Semes,'),
(1675283,58,6,19,42,'Saalabbin, Aijalon, Jitla,'),
(1675284,58,6,19,43,'Eelon, Timna, Ekron,'),
(1675285,58,6,19,44,'Elteke, Gibbeton, Baalat,'),
(1675286,58,6,19,45,'Jehud, Bene-Berak, Gat-Rimmon,'),
(1675287,58,6,19,46,'Mee-Jarkon ja Rakkon, ynnä Jaafoon päin oleva alue.'),
(1675288,58,6,19,47,'Mutta daanilaisten alue joutui heiltä pois. Niin daanilaiset lähtivät ja taistelivat Lesemiä vastaan ja valloittivat sen ja surmasivat miekan terällä sen asukkaat ja ottivat sen omaksensa ja asettuivat sinne. Ja he antoivat Lesemille nimen Daan, isänsä Daanin mukaan.'),
(1675289,58,6,19,48,'Tämä on daanilaisten sukukunnan, heidän sukujensa, perintöosa, nämä kaupungit kylineen.'),
(1675290,58,6,19,49,'Kun israelilaiset olivat saaneet jaetuksi maan sen rajoja myöten, antoivat he Joosualle, Nuunin pojalle, perintöosan keskuudessaan.'),
(1675291,58,6,19,50,'Herran käskyn mukaisesti he antoivat hänelle sen kaupungin, jota hän pyysi, Timnat-Serahin Efraimin vuoristossa. Ja hän rakensi uudestaan kaupungin ja asettui sinne.'),
(1675292,58,6,19,51,'Nämä ovat ne perintöosat, jotka pappi Eleasar ja Joosua, Nuunin poika, ja israelilaisten sukukuntien perhekunta-päämiehet jakoivat arvalla Siilossa Herran edessä, ilmestysmajan ovella. Niin he lopettivat maan jakamisen.'),
(1675293,58,6,20,1,'Silloin Herra puhui Joosualle sanoen:'),
(1675294,58,6,20,2,'"Puhu israelilaisille ja sano: Määrätkää itsellenne ne turvakaupungit, joista minä olen puhunut teille Mooseksen kautta,'),
(1675295,58,6,20,3,'että niihin voisi paeta tappaja, joka tapaturmaisesti, tahtomattaan, on jonkun surmannut; ja olkoot ne teillä turvapaikkoina verenkostajalta.'),
(1675296,58,6,20,4,'Ja kun joku pakenee johonkin näistä kaupungeista, pysähtyköön hän kaupungin portin ovelle ja kertokoon asiansa sen kaupungin vanhimmille; he korjatkoot hänet luoksensa kaupunkiin ja antakoot hänelle paikan, jossa hän saa asua heidän luonansa.'),
(1675297,58,6,20,5,'Ja jos verenkostaja ajaa häntä takaa, älkööt he luovuttako tappajaa hänen käsiinsä, koska hän tahtomattaan tappoi lähimmäisensä, häntä ennestään vihaamatta.'),
(1675298,58,6,20,6,'Ja asukoon hän siinä kaupungissa, kunnes on ollut kansan tuomittavana, ja silloisen ylimmäisen papin kuolemaan saakka; sitten tappaja tulkoon taas takaisin omaan kaupunkiinsa ja kotiinsa, kaupunkiin, josta oli paennut."'),
(1675299,58,6,20,7,'Niin he pyhittivät sitä varten Kedeksen Galileasta, Naftalin vuoristosta, Sikemin Efraimin vuoristosta ja Kirjat-Arban, se on Hebronin, Juudan vuoristosta.'),
(1675300,58,6,20,8,'Ja tuolta puolelta Jerikon Jordanin, idän puolelta, he määräsivät Ruubenin sukukunnasta Beserin erämaasta, ylätasangolta, ja Gaadin sukukunnasta Raamotin, Gileadista, ja Manassen sukukunnasta Goolanin, Baasanista.'),
(1675301,58,6,20,9,'Nämä ovat ne kaupungit, jotka asetettiin kaikille israelilaisille ja heidän keskuudessaan asuville muukalaisille sitä varten, että niihin voisi paeta jokainen, joka tapaturmaisesti oli jonkun surmannut, eikä hänen tarvitsisi kuolla verenkostajan käden kautta, ennenkuin oli ollut kansan tuomittavana.'),
(1675302,58,6,21,1,'Leeviläisten perhekunta-päämiehet astuivat pappi Eleasarin ja Joosuan, Nuunin pojan, eteen ja israelilaisten sukukuntien perhekunta-päämiesten eteen'),
(1675303,58,6,21,2,'ja puhuivat heille Siilossa Kanaanin maassa, sanoen: "Herra käski Mooseksen kautta antaa meille kaupunkeja asuaksemme ja niiden laidunmaat karjaamme varten".'),
(1675304,58,6,21,3,'Niin israelilaiset antoivat leeviläisille perintöosastaan Herran käskyn mukaan nämä kaupungit laidunmaineen:'),
(1675305,58,6,21,4,'Arpa tuli kehatilaisten suvuille niin, että leeviläisistä pappi Aaronin jälkeläiset saivat arvalla Juudan sukukunnalta, Simeonin sukukunnalta ja Benjaminin sukukunnalta kolmetoista kaupunkia.'),
(1675306,58,6,21,5,'Mutta muut kehatilaiset saivat arvalla Efraimin sukukunnan suvuilta, Daanin sukukunnalta ja toiselta puolelta Manassen sukukuntaa kymmenen kaupunkia.'),
(1675307,58,6,21,6,'Geersonilaiset saivat arvalla Isaskarin sukukunnan suvuilta, Asserin sukukunnalta ja Naftalin sukukunnalta, sekä toiselta puolelta Manassen sukukuntaa Baasanista, kolmetoista kaupunkia.'),
(1675308,58,6,21,7,'Merarilaiset, heidän sukunsa, saivat Ruubenin sukukunnalta, Gaadin sukukunnalta ja Sebulonin sukukunnalta kaksitoista kaupunkia.'),
(1675309,58,6,21,8,'Israelilaiset antoivat arvalla leeviläisille nämä kaupungit laidunmaineen, niinkuin Herra oli Mooseksen kautta käskenyt.'),
(1675310,58,6,21,9,'Juudan jälkeläisten sukukunnasta ja simeonilaisten sukukunnasta annettiin nämä nimeltä mainitut kaupungit:'),
(1675311,58,6,21,10,'Leevin jälkeläisiin, kehatilaisten sukuihin, kuuluville Aaronin jälkeläisille, sillä heille tuli arpa ensin,'),
(1675312,58,6,21,11,'annettiin Kirjat-Arba, anakilaisten kantaisän Arban kaupunki, se on Hebron, Juudan vuoristosta, ympärillä olevine laidunmaineen.'),
(1675313,58,6,21,12,'Mutta kaupungin peltomaat kylineen annettiin Kaalebille, Jefunnen pojalle, perintömaaksi.'),
(1675314,58,6,21,13,'Pappi Aaronin jälkeläisille annettiin tappajan turvakaupunki Hebron laidunmaineen, Libna laidunmaineen,'),
(1675315,58,6,21,14,'Jattir laidunmaineen, Estemoa laidunmaineen,'),
(1675316,58,6,21,15,'Hoolon laidunmaineen, Debir laidunmaineen,'),
(1675317,58,6,21,16,'Ain laidunmaineen, Jutta laidunmaineen ja Beet-Semes laidunmaineen - yhdeksän kaupunkia näistä kahdesta sukukunnasta;'),
(1675318,58,6,21,17,'ja Benjaminin sukukunnasta Gibeon laidunmaineen, Geba laidunmaineen,'),
(1675319,58,6,21,18,'Anatot laidunmaineen ja Almon laidunmaineen - neljä kaupunkia.'),
(1675320,58,6,21,19,'Aaronin jälkeläisten, pappien, kaupunkeja oli kaikkiaan kolmetoista kaupunkia laidunmaineen.'),
(1675321,58,6,21,20,'Muut leeviläisiin kuuluvat kehatilaisten suvut, muut kehatilaiset, saivat arvalla Efraimin sukukunnalta seuraavat kaupungit:'),
(1675322,58,6,21,21,'heille annettiin tappajan turvakaupunki Sikem laidunmaineen Efraimin vuoristosta, Geser laidunmaineen,'),
(1675323,58,6,21,22,'Kibsaim laidunmaineen, Beet-Hooron laidunmaineen - neljä kaupunkia;'),
(1675324,58,6,21,23,'ja Daanin sukukunnasta Elteke laidunmaineen, Gibbeton laidunmaineen,'),
(1675325,58,6,21,24,'Aijalon laidunmaineen ja Gat-Rimmon laidunmaineen - neljä kaupunkia,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675326,58,6,21,25,'ja toisesta puolesta Manassen sukukuntaa Taanak laidunmaineen ja Gat-Rimmon laidunmaineen - kaksi kaupunkia.'),
(1675327,58,6,21,26,'Näiden muiden kehatilaisten sukujen kaupunkeja laidunmaineen oli kaikkiaan kymmenen.'),
(1675328,58,6,21,27,'Leeviläisten sukuihin kuuluvat geersonilaiset saivat toiselta puolelta Manassen sukukuntaa tappajan turvakaupungin Goolanin laidunmaineen Baasanista ja Beesteran laidunmaineen - kaksi kaupunkia;'),
(1675329,58,6,21,28,'ja Isaskarin sukukunnalta Kisjonin laidunmaineen, Daberatin laidunmaineen,'),
(1675330,58,6,21,29,'Jarmutin laidunmaineen ja Een-Gannimin laidunmaineen - neljä kaupunkia;'),
(1675331,58,6,21,30,'ja Asserin sukukunnalta Misalin laidunmaineen, Abdonin laidunmaineen,'),
(1675332,58,6,21,31,'Helkatin laidunmaineen ja Rehobin laidunmaineen - neljä kaupunkia;'),
(1675333,58,6,21,32,'ja Naftalin sukukunnalta tappajan turvakaupungin Kedeksen laidunmaineen Galileasta, Hammot-Doorin laidunmaineen ja Kartanin laidunmaineen - kolme kaupunkia.'),
(1675334,58,6,21,33,'Geersonilaisten, heidän sukujensa, kaupunkeja oli kaikkiaan kolmetoista kaupunkia laidunmaineen.'),
(1675335,58,6,21,34,'Muut leeviläisiin kuuluvat merarilaisten suvut saivat Sebulonin sukukunnalta Jokneamin laidunmaineen, Kartan laidunmaineen,'),
(1675336,58,6,21,35,'Dimnan laidunmaineen, Nahalalin laidunmaineen - neljä kaupunkia;'),
(1675337,58,6,21,36,'ja Ruubenin sukukunnalta Beserin laidunmaineen, Jahaan laidunmaineen,'),
(1675338,58,6,21,37,'Kedemotin laidunmaineen ja Meefaatin laidunmaineen - neljä kaupunkia;'),
(1675339,58,6,21,38,'ja Gaadin sukukunnalta tappajan turvakaupungin Raamotin laidunmaineen Gileadista ja Mahanaimin laidunmaineen,'),
(1675340,58,6,21,39,'Hesbonin laidunmaineen ja Jaeserin laidunmaineen - yhteensä neljä kaupunkia.'),
(1675341,58,6,21,40,'Niitä kaupunkeja, jotka nämä muut leeviläisten sukuihin kuuluvat merarilaiset, heidän sukunsa, saivat arvalla, oli kaikkiaan kaksitoista kaupunkia.'),
(1675342,58,6,21,41,'Kaikkiaan oli leeviläisten kaupunkeja israelilaisten perintömaassa neljäkymmentä kahdeksan kaupunkia laidunmaineen.'),
(1675343,58,6,21,42,'Näihin kaupunkeihin kuului kuhunkin itse kaupunki ja sen ympärillä olevat laidunmaat; sellaisia olivat kaikki nämä kaupungit.'),
(1675344,58,6,21,43,'Niin Herra antoi Israelille koko sen maan, jonka hän oli vannonut antavansa heidän isilleen; ja he ottivat sen omaksensa ja asettuivat siihen.'),
(1675345,58,6,21,44,'Ja Herra soi heidän päästä rauhaan kaikkialla, aivan niinkuin hän valalla vannoen oli luvannut heidän isillensä; eikä yksikään heidän vihollisistaan kestänyt heidän edessään, vaan kaikki heidän vihollisensa Herra antoi heidän käsiinsä.'),
(1675346,58,6,21,45,'Ei jäänyt täyttämättä ainoakaan kaikista niistä lupauksista, jotka Herra oli antanut Israelin heimolle, vaan kaikki toteutui.'),
(1675347,58,6,22,1,'Sitten Joosua kutsui ruubenilaiset, gaadilaiset ja toisen puolen Manassen sukukuntaa'),
(1675348,58,6,22,2,'ja sanoi heille: "Te olette noudattaneet kaikkea, mitä Herran palvelija Mooses on käskenyt teidän noudattaa, ja olette kuulleet minua kaikessa, mitä minä olen käskenyt teidän tehdä.'),
(1675349,58,6,22,3,'Te ette ole hyljänneet veljiänne koko tämän pitkän ajan kuluessa aina tähän päivään asti, ja te olette noudattaneet, mitä Herra, teidän Jumalanne, on käskenyt noudattaa.'),
(1675350,58,6,22,4,'Ja nyt on Herra, teidän Jumalanne, suonut teidän veljienne päästä rauhaan, niinkuin hän heille puhui; kääntykää siis takaisin ja menkää majoillenne, siihen perintömaahanne, jonka Herran palvelija Mooses antoi teille tuolta puolelta Jordanin.'),
(1675351,58,6,22,5,'Noudattakaa vain tarkoin niitä käskyjä ja sitä lakia, jotka Herran palvelija Mooses on teille antanut, rakastakaa Herraa, teidän Jumalaanne, vaeltakaa aina hänen teitänsä, noudattakaa hänen käskyjänsä, riippukaa hänessä kiinni ja palvelkaa häntä kaikesta sydämestänne ja kaikesta sielustanne."'),
(1675352,58,6,22,6,'Niin Joosua siunasi heidät ja päästi heidät menemään, ja he menivät majoillensa.'),
(1675353,58,6,22,7,'Toiselle puolelle Manassen sukukuntaa Mooses oli antanut maata Baasanista, ja toiselle puolelle Joosua oli antanut maata länsipuolelta Jordanin, heille samoin kuin heidän veljilleen. Ja kun Joosua päästi heidät menemään majoillensa ja siunasi heidät,'),
(1675354,58,6,22,8,'sanoi hän heille näin: "Kun te palaatte majoillenne, mukananne suuret rikkaudet ja suuri karjan paljous, suuri hopean, kullan, vasken, raudan ja vaatteiden paljous, jakakaa veljienne kanssa vihollisiltanne saatu saalis."'),
(1675355,58,6,22,9,'Niin ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa palasivat takaisin ja lähtivät pois israelilaisten luota Siilosta, joka on Kanaanin maassa, mennäkseen Gileadin maahan, perintömaahansa, johon he olivat asettuneet sen käskyn mukaan, jonka Herra oli Mooseksen kautta antanut.'),
(1675356,58,6,22,10,'Kun ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa tulivat Jordanin kivitarhoille, jotka ovat Kanaanin maan puolella, rakensivat he sinne Jordanin partaalle alttarin, valtavan alttarin.'),
(1675357,58,6,22,11,'Niin israelilaiset kuulivat sanottavan: "Katso, ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa ovat rakentaneet alttarin, päin Kanaanin maata, Jordanin kivitarhojen luo, israelilaisten puolelle".'),
(1675358,58,6,22,12,'Kun israelilaiset sen kuulivat, kokoontui kaikki israelilaisten seurakunta Siiloon, lähteäkseen sotaan heitä vastaan.'),
(1675359,58,6,22,13,'Ja israelilaiset lähettivät ruubenilaisten ja gaadilaisten luo ja Manassen sukukunnan toisen puolen luo Gileadin maahan pappi Piinehaan, Eleasarin pojan,'),
(1675360,58,6,22,14,'ja hänen kanssaan kymmenen ruhtinasta, yhden ruhtinaan kustakin perhekunnasta, kaikista Israelin sukukunnista; kukin heistä oli perhekunta-päämies Israelin heimojen joukossa.'),
(1675361,58,6,22,15,'Ja he tulivat ruubenilaisten ja gaadilaisten luo ja Manassen sukukunnan toisen puolen luo Gileadin maahan, puhuivat heille ja sanoivat:'),
(1675362,58,6,22,16,'"Näin sanoo koko Herran seurakunta: Kuinka te menettelette näin uskottomasti Israelin Jumalaa kohtaan, että nyt käännytte pois Herrasta rakentamalla itsellenne alttarin ja niin nyt kapinoitte Herraa vastaan?'),
(1675363,58,6,22,17,'Eikö meille jo riitä Peorin vuoksi tehty rikos, josta emme ole päässeet puhdistumaan vielä tänäkään päivänä ja josta rangaistus kohtasi Herran seurakuntaa?'),
(1675364,58,6,22,18,'Ja kuitenkin te nytkin käännytte pois Herrasta! Kun te tänä päivänä kapinoitte Herraa vastaan, niin hän huomenna vihastuu koko Israelin seurakuntaan.'),
(1675365,58,6,22,19,'Mutta jos teidän perintömaanne on saastainen, niin tulkaa Herran perintömaahan, jossa on Herran asumus, ja asettukaa meidän keskellemme. Älkää kapinoiko Herraa vastaan älkääkä kapinoiko meitä vastaan rakentamalla itsellenne alttaria, toista kuin Herran, meidän Jumalamme, alttari.'),
(1675366,58,6,22,20,'Eikö silloin, kun Aakan, Serahin poika, oli ollut uskoton ja anastanut itselleen sitä, mikä oli vihitty tuhon omaksi, viha kohdannut koko Israelin seurakuntaa, vaikka hän olikin vain yksi mies? Eikö hänen täytynyt hukkua rikoksensa tähden?"'),
(1675367,58,6,22,21,'Silloin ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa vastasivat ja puhuivat Israelin heimojen päämiehille:'),
(1675368,58,6,22,22,'"Jumala, Herra Jumala, Jumala, Herra Jumala, hän tietää sen, ja Israel myöskin tietäköön sen: jos me olemme kapinamielessä tai uskottomuudesta Herraa kohtaan - älä meitä silloin tänä päivänä auta -'),
(1675369,58,6,22,23,'rakentaneet alttarin kääntyäksemme pois Herrasta, uhrataksemme sen päällä polttouhria ja ruokauhria tai toimittaaksemme sen päällä yhteysuhreja, niin kostakoon Herra itse sen.'),
(1675370,58,6,22,24,'Totisesti, me olemme tehneet sen vain yhdestä huolestuneina, siitä, että teidän lapsenne vastaisuudessa voivat sanoa meidän lapsillemme näin: ''Mitä teillä on tekemistä Herran, Israelin Jumalan, kanssa?'),
(1675371,58,6,22,25,'Onhan Herra pannut Jordanin välirajaksi meille ja teille, te ruubenilaiset ja gaadilaiset; teillä ei ole mitään osuutta Herraan.'' Ja niin teidän lapsenne voivat saada aikaan, että meidän lapsemme lakkaavat pelkäämästä Herraa.'),
(1675372,58,6,22,26,'Sentähden me sanoimme: Tehkäämme itsellemme alttari, rakentakaamme se, ei polttouhria eikä teurasuhria varten,'),
(1675373,58,6,22,27,'vaan olemaan meidän ja teidän sekä myös meidän jälkeläistemme välillä meidän jälkeemme todistajana siitä, että me tahdomme toimittaa Herran palvelusta hänen edessänsä, polttouhreja, teurasuhreja ja yhteysuhreja, etteivät teidän lapsenne vastaisuudessa sanoisi meidän lapsillemme: ''Teillä ei ole mitään osuutta Herraan''.'),
(1675374,58,6,22,28,'Ja me ajattelimme: Jos he vastaisuudessa sanovat näin meille ja meidän jälkeläisillemme, niin me voimme vastata: ''Katsokaa Herran alttarin kuvaa, jonka meidän esi-isämme ovat tehneet, ei polttouhria eikä teurasuhria varten, vaan olemaan todistajana meidän välillämme ja teidän''.'),
(1675375,58,6,22,29,'Pois se, että me kapinoisimme Herraa vastaan ja kääntyisimme tänä päivänä pois Herrasta rakentamalla alttarin polttouhria, ruokauhria ja teurasuhria varten, toisen kuin Herran, meidän Jumalamme, alttari, joka on hänen asumuksensa edessä!"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675376,58,6,22,30,'Kun pappi Piinehas ja kansan ruhtinaat, Israelin heimojen päämiehet, jotka olivat hänen kanssaan, kuulivat, mitä ruubenilaiset, gaadilaiset ja manasselaiset puhuivat, oli se heille mieleen.'),
(1675377,58,6,22,31,'Ja pappi Piinehas, Eleasarin poika, sanoi ruubenilaisille, gaadilaisille ja manasselaisille: "Nyt me tiedämme, että Herra on meidän keskellämme, koska ette olekaan menetelleet uskottomasti Herraa kohtaan; näin te pelastitte israelilaiset joutumasta Herran käsiin".'),
(1675378,58,6,22,32,'Sen jälkeen pappi Piinehas, Eleasarin poika, ja ruhtinaat palasivat Gileadin maasta, ruubenilaisten ja gaadilaisten luota, takaisin Kanaanin maahan israelilaisten luo ja antoivat heille nämä tiedot.'),
(1675379,58,6,22,33,'Ja ne olivat israelilaisille mieleen, ja israelilaiset ylistivät Jumalaa; eivätkä he enää ajatelleet lähteä sotaan heitä vastaan, hävittämään sitä maata, jossa ruubenilaiset ja gaadilaiset asuivat.'),
(1675380,58,6,22,34,'Ja ruubenilaiset ja gaadilaiset antoivat alttarille nimen, sanoen: "Se on todistaja meidän välillämme siitä, että Herra on Jumala".'),
(1675381,58,6,23,1,'Pitkän ajan kuluttua, sitten kuin Herra oli suonut Israelin päästä rauhaan kaikilta sen ympärillä asuvilta vihollisilta, ja kun Joosua oli käynyt vanhaksi ja iäkkääksi,'),
(1675382,58,6,23,2,'kutsui Joosua kaiken Israelin, sen vanhimmat, päämiehet, tuomarit ja päällysmiehet ja sanoi heille: "Minä olen käynyt vanhaksi ja iäkkääksi.'),
(1675383,58,6,23,3,'Ja te olette itse nähneet kaiken, mitä Herra, teidän Jumalanne, on tehnyt kaikille näille kansoille, jotka hän on karkoittanut teidän tieltänne; sillä Herra, teidän Jumalanne, on itse sotinut teidän puolestanne.'),
(1675384,58,6,23,4,'Katsokaa, minä olen arponut teille, teidän sukukunnillenne, perintöosaksi nämä kansat, jotka vielä ovat jäljellä, ja kaikki kansat, jotka minä hävitin Jordanista Suureen mereen asti, auringonlaskuun päin.'),
(1675385,58,6,23,5,'Ja Herra, teidän Jumalanne, työntää itse ne pois teidän edestänne ja karkoittaa ne teidän tieltänne, niin että te otatte omaksenne heidän maansa, niinkuin Herra, teidän Jumalanne, on teille puhunut.'),
(1675386,58,6,23,6,'Olkaa siis aivan lujat ja noudattakaa tarkoin kaikkea, mitä Mooseksen lain kirjaan on kirjoitettu, poikkeamatta siitä oikealle tai vasemmalle,'),
(1675387,58,6,23,7,'niin ettette yhdy näihin teidän keskuuteenne jääneisiin kansoihin, ette mainitse heidän jumaliensa nimiä ettekä vanno niiden nimeen, ette palvele niitä ettekä kumarra niitä,'),
(1675388,58,6,23,8,'vaan että riiputte kiinni Herrassa, Jumalassanne, niinkuin olette tehneet aina tähän päivään asti.'),
(1675389,58,6,23,9,'Sentähden Herra on karkoittanut teidän tieltänne suuret ja mahtavat kansat, eikä ainoakaan ole kestänyt teidän edessänne aina tähän päivään asti.'),
(1675390,58,6,23,10,'Yksi ainoa mies teistä ajoi pakoon tuhat, sillä Herra, teidän Jumalanne, soti itse teidän puolestanne, niinkuin hän on teille puhunut.'),
(1675391,58,6,23,11,'Ottakaa siis henkenne tähden tarkka vaari siitä, että rakastatte Herraa, teidän Jumalaanne.'),
(1675392,58,6,23,12,'Sillä jos te käännytte hänestä pois ja liitytte näiden teidän keskuuteenne jääneiden kansojen tähteisiin ja lankoudutte heidän kanssansa ja yhdytte heihin ja he teihin,'),
(1675393,58,6,23,13,'niin tietäkää, ettei Herra, teidän Jumalanne, enää karkoita näitä kansoja teidän tieltänne, vaan ne tulevat teille paulaksi ja ansaksi, kylkienne ruoskaksi ja okaiksi silmiinne, kunnes te häviätte tästä hyvästä maasta, jonka Herra, teidän Jumalanne, on teille antanut.'),
(1675394,58,6,23,14,'Katso, minä menen nyt kaiken maailman tietä. Koko sydämenne ja koko sielunne tietäköön, ettei ainoakaan kaikista niistä teitä koskevista lupauksista, jotka Herra, teidän Jumalanne, on antanut, ole jäänyt täyttämättä; kaikki ovat toteutuneet teille, ei ainoakaan niistä ole jäänyt täyttämättä.'),
(1675395,58,6,23,15,'Ja niinkuin kaikki teitä koskevat lupaukset, jotka Herra, teidän Jumalanne, on antanut, ovat toteutuneet teille, niin Herra myöskin antaa kaikkien uhkauksiensa toteutua teille, kunnes hän on hävittänyt teidät tästä hyvästä maasta, jonka Herra, teidän Jumalanne, on teille antanut:'),
(1675396,58,6,23,16,'jos te rikotte Herran, teidän Jumalanne, liiton, jonka hän on teille säätänyt, ja menette ja palvelette muita jumalia ja niitä kumarratte, niin Herran viha syttyy teitä kohtaan, ja te häviätte pian siitä hyvästä maasta, jonka hän on teille antanut."'),
(1675397,58,6,24,1,'Sitten Joosua kokosi kaikki Israelin sukukunnat Sikemiin ja kutsui Israelin vanhimmat, sen päämiehet, tuomarit ja päällysmiehet, ja he asettuivat Jumalan eteen.'),
(1675398,58,6,24,2,'Ja Joosua sanoi koko kansalle: "Näin sanoo Herra, Israelin Jumala: Tuolla puolella Eufrat-virran asuivat muinoin teidän isänne, myös Terah, Aabrahamin ja Naahorin isä, ja he palvelivat muita jumalia.'),
(1675399,58,6,24,3,'Mutta minä otin teidän isänne Aabrahamin tuolta puolelta virran ja kuljetin häntä kautta koko Kanaanin maan ja tein hänen jälkeläisensä lukuisiksi ja annoin hänelle Iisakin.'),
(1675400,58,6,24,4,'Ja Iisakille minä annoin Jaakobin ja Eesaun. Ja Eesaulle minä annoin Seirin vuoriston omaksi, mutta Jaakob ja hänen poikansa menivät Egyptiin.'),
(1675401,58,6,24,5,'Sitten minä lähetin Mooseksen ja Aaronin ja rankaisin Egyptiä sillä, mitä minä siellä tein, ja sen jälkeen minä vein teidät sieltä pois.'),
(1675402,58,6,24,6,'Ja kun minä vein teidän isänne pois Egyptistä ja te olitte saapuneet meren rannalle, ajoivat egyptiläiset teidän isiänne takaa sotavaunuilla ja ratsumiehillä Kaislamereen saakka.'),
(1675403,58,6,24,7,'Niin he huusivat Herraa, ja hän pani pimeyden teidän ja egyptiläisten välille ja antoi meren tulla heidän ylitsensä, ja se peitti heidät; omin silmin te näitte, mitä minä tein egyptiläisille. Kun te sitten olitte asuneet kauan aikaa erämaassa,'),
(1675404,58,6,24,8,'toin minä teidät amorilaisten maahan, jotka asuivat tuolla puolella Jordanin, ja he taistelivat teitä vastaan; mutta minä annoin heidät teidän käsiinne, ja te otitte omaksenne heidän maansa, ja minä tuhosin heidät teidän tieltänne.'),
(1675405,58,6,24,9,'Silloin nousi Baalak, Sipporin poika, Mooabin kuningas ja taisteli Israelia vastaan; ja hän lähetti kutsumaan Bileamin, Beorin pojan, että hän kiroaisi teidät.'),
(1675406,58,6,24,10,'Mutta minä en tahtonut kuulla Bileamia, vaan hänen täytyi siunata teidät, ja minä pelastin teidät hänen käsistään.'),
(1675407,58,6,24,11,'Ja kun te olitte menneet Jordanin yli ja tulleet Jerikoon, niin Jerikon miehet ja amorilaiset, perissiläiset, kanaanilaiset, heettiläiset, girgasilaiset, hivviläiset ja jebusilaiset taistelivat teitä vastaan, mutta minä annoin heidät teidän käsiinne.'),
(1675408,58,6,24,12,'Ja minä lähetin herhiläisiä teidän edellänne, ja ne karkoittivat heidät teidän tieltänne, ne kaksi amorilaisten kuningasta; sinä miekallasi ja jousellasi et sitä tehnyt.'),
(1675409,58,6,24,13,'Ja minä annoin teille maan, josta sinä et ollut vaivaa nähnyt, ja kaupunkeja, joita te ette olleet rakentaneet, mutta joihin saitte asettua; viinitarhoista ja öljypuista, joita te ette olleet istuttaneet, te saitte syödä.'),
(1675410,58,6,24,14,'Niin peljätkää nyt Herraa, palvelkaa häntä nuhteettomasti ja uskollisesti ja poistakaa ne jumalat, joita teidän isänne palvelivat tuolla puolella virran ja Egyptissä, ja palvelkaa Herraa.'),
(1675411,58,6,24,15,'Mutta jos pidätte pahana palvella Herraa, niin valitkaa tänä päivänä, ketä tahdotte palvella, niitäkö jumalia, joita teidän isänne palvelivat tuolla puolella virran, vai amorilaisten jumalia, niiden, joiden maassa te asutte. Mutta minä ja minun perheeni palvelemme Herraa."'),
(1675412,58,6,24,16,'Silloin kansa vastasi ja sanoi: "Pois se, että me hylkäisimme Herran ja palvelisimme muita jumalia!'),
(1675413,58,6,24,17,'Sillä Herra on meidän Jumalamme, hän, joka johdatti meidät ja meidän isämme pois Egyptin maasta, orjuuden pesästä, ja joka teki meidän silmiemme edessä suuret tunnusteot ja aina varjeli meitä sillä tiellä, jota me vaelsimme, ja kaikkien niiden kansojen keskellä, joiden kautta me kuljimme.'),
(1675414,58,6,24,18,'Ja Herra karkoitti meidän tieltämme kaikki ne kansat, myös amorilaiset, jotka asuivat tässä maassa. Sentähden me palvelemme Herraa, sillä hän on meidän Jumalamme."'),
(1675415,58,6,24,19,'Niin Joosua sanoi kansalle: "Te ette voi palvella Herraa, sillä hän on pyhä Jumala; hän on kiivas Jumala, hän ei anna anteeksi teidän rikoksianne ja syntejänne.'),
(1675416,58,6,24,20,'Jos te hylkäätte Herran ja palvelette vieraita jumalia, niin hän kääntyy pois ja antaa teille käydä pahoin ja tekee lopun teistä, sen sijaan että hän on ennen antanut teille käydä hyvin."'),
(1675417,58,6,24,21,'Mutta kansa sanoi Joosualle: "Ei niin, vaan me palvelemme Herraa".'),
(1675418,58,6,24,22,'Silloin Joosua sanoi kansalle: "Te olette itse todistajina itseänne vastaan, että olette valinneet itsellenne Herran palvellaksenne häntä". He vastasivat: "Olemme".'),
(1675419,58,6,24,23,'Hän sanoi: "Niin poistakaa nyt vieraat jumalat, joita on teidän keskuudessanne, ja taivuttakaa sydämenne Herran, Israelin Jumalan, puoleen".'),
(1675420,58,6,24,24,'Kansa vastasi Joosualle: "Herraa, meidän Jumalaamme, me palvelemme, ja hänen ääntänsä me kuulemme".'),
(1675421,58,6,24,25,'Niin Joosua teki sinä päivänä liiton kansan kanssa ja antoi heille Sikemissä käskyt ja oikeudet.'),
(1675422,58,6,24,26,'Ja Joosua kirjoitti nämä puheet Jumalan lain kirjaan, ja hän otti suuren kiven ja pystytti sen sinne, tammen alle, joka oli Herran pyhäkössä.'),
(1675423,58,6,24,27,'Ja Joosua sanoi kaikelle kansalle: "Katso, tämä kivi on oleva todistajana meitä vastaan, sillä se on kuullut kaikki Herran sanat, jotka hän on meille puhunut, ja se on oleva todistajana teitä vastaan, ettette kieltäisi Jumalaanne".'),
(1675424,58,6,24,28,'Sitten Joosua päästi kansan menemään, kunkin perintöosalleen.'),
(1675425,58,6,24,29,'Näiden tapausten jälkeen Herran palvelija Joosua, Nuunin poika, kuoli sadan kymmenen vuoden vanhana.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675426,58,6,24,30,'Ja he hautasivat hänet hänen perintöosansa alueelle, Timnat-Serahiin, joka on Efraimin vuoristossa, pohjoispuolelle Gaas-vuorta.'),
(1675427,58,6,24,31,'Ja Israel palveli Herraa Joosuan koko elinajan ja niiden vanhinten koko elinajan, jotka elivät vielä kauan Joosuan jälkeen ja tunsivat kaikki ne teot, jotka Herra oli Israelille tehnyt.'),
(1675428,58,6,24,32,'Ja Joosefin luut, jotka israelilaiset olivat tuoneet Egyptistä, he hautasivat Sikemiin, siihen maapalstaan, jonka Jaakob oli ostanut Hamorin, Sikemin isän, pojilta sadalla kesitalla ja jonka joosefilaiset olivat saaneet perintöosaksensa.'),
(1675429,58,7,1,1,'Joosuan kuoleman jälkeen israelilaiset kysyivät Herralta ja sanoivat: "Kenen meistä on ensiksi lähdettävä kanaanilaisia vastaan, sotimaan heitä vastaan?" Herra vastasi:'),
(1675430,58,7,1,2,'"Juuda lähteköön; katso, minä annan maan hänen käsiinsä".'),
(1675431,58,7,1,3,'Niin Juuda sanoi veljellensä Simeonille: "Lähde minun kanssani minun arpaosaani, ja sotikaamme kanaanilaisia vastaan, niin minäkin tulen sinun kanssasi sinun arpaosaasi". Niin Simeon lähti hänen kanssaan.'),
(1675432,58,7,1,4,'Ja Juuda lähti, ja Herra antoi kanaanilaiset ja perissiläiset heidän käsiinsä; ja he voittivat heidät Besekissä - kymmenentuhatta miestä.'),
(1675433,58,7,1,5,'Ja he kohtasivat Adoni-Besekin Besekissä ja taistelivat häntä vastaan ja voittivat kanaanilaiset ja perissiläiset.'),
(1675434,58,7,1,6,'Ja Adoni-Besek pakeni, mutta he ajoivat häntä takaa ja ottivat hänet kiinni ja hakkasivat häneltä peukalot ja isotvarpaat.'),
(1675435,58,7,1,7,'Silloin Adoni-Besek sanoi: "Seitsemänkymmentä kuningasta, joilta oli hakattu peukalot ja isotvarpaat, kokosi muruja minun pöytäni alta; niinkuin minä olen tehnyt, niin on Jumala minulle maksanut". Ja he veivät hänet Jerusalemiin, ja siellä hän kuoli.'),
(1675436,58,7,1,8,'Ja Juudan miehet ryhtyivät taisteluun Jerusalemia vastaan ja valloittivat sen ja surmasivat miekan terällä sen asukkaat ja pistivät kaupungin tuleen.'),
(1675437,58,7,1,9,'Sen jälkeen Juudan miehet laskeutuivat sotimaan niitä kanaanilaisia vastaan, jotka asuivat Vuoristossa, Etelämaassa ja Alankomaassa.'),
(1675438,58,7,1,10,'Niin Juuda meni niitä kanaanilaisia vastaan, jotka asuivat Hebronissa - Hebronin nimi oli muinoin Kirjat-Arba - ja he voittivat Seesain, Ahimanin ja Talmain.'),
(1675439,58,7,1,11,'Sieltä hän meni Debirin asukkaita vastaan - Debirin nimi oli muinoin Kirjat-Seefer -'),
(1675440,58,7,1,12,'ja Kaaleb sanoi: "Joka voittaa ja valloittaa Kirjat-Seeferin, sille minä annan tyttäreni Aksan vaimoksi".'),
(1675441,58,7,1,13,'Niin Otniel, Kenaan, Kaalebin nuoremman veljen, poika, valloitti sen; ja hän antoi tälle tyttärensä Aksan vaimoksi.'),
(1675442,58,7,1,14,'Ja kun Aksa tuli, niin hän yllytti miestänsä, että tämä pyytäisi hänen isältänsä peltomaata; ja Aksa pudottautui aasin selästä maahan. Silloin Kaaleb sanoi hänelle: "Mikä sinun on?"'),
(1675443,58,7,1,15,'Niin hän vastasi hänelle: "Anna minulle jäähyväislahja, sillä sinä olet naittanut minut kuivaan maahan, anna siis minulle vesilähteitä". Silloin Kaaleb antoi hänelle Ylälähteet ja Alalähteet.'),
(1675444,58,7,1,16,'Ja keeniläisen, Mooseksen apen, jälkeläiset olivat lähteneet Palmukaupungista Juudan jälkeläisten kanssa Juudan erämaahan, eteläpuolelle Aradia; he menivät ja asettuivat sikäläisen kansan sekaan.'),
(1675445,58,7,1,17,'Mutta Juuda meni veljensä Simeonin kanssa, ja he voittivat kanaanilaiset, jotka asuivat Sefatissa, ja he vihkivät kaupungin tuhon omaksi ja kutsuivat sen Hormaksi.'),
(1675446,58,7,1,18,'Ja Juuda valloitti Gassan alueineen, Askelonin alueineen ja Ekronin alueineen.'),
(1675447,58,7,1,19,'Ja Herra oli Juudan kanssa, niin että hän sai haltuunsa vuoriston; sillä hän ei kyennyt karkoittamaan niitä, jotka asuivat tasangolla, koska heillä oli raudoitettuja sotavaunuja.'),
(1675448,58,7,1,20,'Ja he antoivat Kaalebille Hebronin, niinkuin Mooses oli puhunut; ja hän karkoitti sieltä ne kolme anakilaista.'),
(1675449,58,7,1,21,'Mutta benjaminilaiset eivät karkoittaneet jebusilaisia, jotka asuivat Jerusalemissa, ja niin jebusilaiset jäivät asumaan benjaminilaisten sekaan, Jerusalemiin, aina tähän päivään asti.'),
(1675450,58,7,1,22,'Myöskin Joosefin heimo lähti liikkeelle; se lähti Beeteliin, ja Herra oli heidän kanssansa.'),
(1675451,58,7,1,23,'Ja Joosefin heimo vakoilutti Beeteliä - kaupungin nimi oli muinoin Luus -'),
(1675452,58,7,1,24,'ja vakoilijat näkivät miehen tulevan kaupungista ja sanoivat hänelle: "Näytä meille, mistä päästään kaupunkiin, niin me teemme sinulle laupeuden".'),
(1675453,58,7,1,25,'Niin hän näytti heille, mistä päästiin kaupunkiin, ja he surmasivat miekan terällä kaupungin asukkaat, mutta sen miehen ja koko hänen sukunsa he päästivät menemään.'),
(1675454,58,7,1,26,'Ja se mies meni heettiläisten maahan ja rakensi kaupungin ja antoi sille nimen Luus, ja se nimi sillä on vielä tänäkin päivänä.'),
(1675455,58,7,1,27,'Mutta Manasse ei saanut haltuunsa Beet-Seania ja sen tytärkaupunkeja, ei Taanakia ja sen tytärkaupunkeja, ei Doorin asukkaita ja sen tytärkaupunkeja, ei Jibleamin asukkaita ja sen tytärkaupunkeja eikä Megiddon asukkaita ja sen tytärkaupunkeja, vaan kanaanilaisten onnistui jäädä asumaan siihen maahan.'),
(1675456,58,7,1,28,'Kun Israel sitten voimistui, saattoi se kanaanilaiset työveron alaisiksi, mutta ei karkoittanut heitä.'),
(1675457,58,7,1,29,'Efraim ei karkoittanut kanaanilaisia, jotka asuivat Geserissä, ja niin kanaanilaiset jäivät asumaan sen keskeen, Geseriin.'),
(1675458,58,7,1,30,'Sebulon ei karkoittanut Kidronin asukkaita eikä Nahalolin asukkaita, ja niin kanaanilaiset jäivät asumaan sen keskeen, mutta joutuivat työveron alaisiksi.'),
(1675459,58,7,1,31,'Asser ei karkoittanut Akkon asukkaita eikä Siidonin asukkaita eikä myöskään Ahlabin, Aksibin, Helban, Afekin ja Rehobin asukkaita.'),
(1675460,58,7,1,32,'Ja niin asserilaiset joutuivat asumaan maan asukkaiden, kanaanilaisten, keskeen, koska eivät karkoittaneet heitä.'),
(1675461,58,7,1,33,'Naftali ei karkoittanut Beet-Semeksen asukkaita eikä Beet-Anatin asukkaita ja joutui niin asumaan maan asukkaiden, kanaanilaisten, keskeen; mutta Beet-Semeksen ja Beet-Anatin asukkaat joutuivat heille työveron alaisiksi.'),
(1675462,58,7,1,34,'Amorilaiset tunkivat daanilaiset vuoristoon, sillä he eivät sallineet heidän laskeutua tasangolle.'),
(1675463,58,7,1,35,'Ja amorilaisten onnistui jäädä asumaan Har-Herekseen, Aijaloniin ja Saalbimiin; mutta Joosefin heimon käsi kävi heille raskaaksi, ja he joutuivat työveron alaisiksi.'),
(1675464,58,7,1,36,'Ja amorilaisten alue ulottui Skorpionisolasta, Seelasta, ylöspäin.'),
(1675465,58,7,2,1,'Ja Herran enkeli tuli Gilgalista ylös Bookimiin. Ja hän sanoi: "Minä johdatin teidät Egyptistä ja toin teidät maahan, jonka minä valalla vannoen olin luvannut teidän isillenne, ja sanoin: ''Minä en riko liittoani teidän kanssanne ikinä.'),
(1675466,58,7,2,2,'Te taas älkää tehkö liittoa tämän maan asukasten kanssa, vaan kukistakaa heidän alttarinsa.'' Mutta te ette ole kuulleet minun ääntäni. Mitä olettekaan tehneet!'),
(1675467,58,7,2,3,'Niinpä minä nyt sanon teille: Minä en karkoita heitä teidän tieltänne, vaan heistä tulee teille ahdistajat, ja heidän jumalansa tulevat teille ansaksi."'),
(1675468,58,7,2,4,'Ja kun Herran enkeli oli puhunut nämä sanat kaikille israelilaisille, korotti kansa äänensä ja itki.'),
(1675469,58,7,2,5,'Ja he antoivat sille paikalle nimen Bookim; ja he uhrasivat siinä Herralle.'),
(1675470,58,7,2,6,'Kun Joosua oli päästänyt kansan menemään, menivät israelilaiset kukin perintöosallensa, ottaakseen maan omaksensa.'),
(1675471,58,7,2,7,'Ja kansa palveli Herraa Joosuan koko elinajan ja niiden vanhinten koko elinajan, jotka elivät vielä kauan Joosuan jälkeen ja jotka olivat nähneet kaikki ne suuret teot, jotka Herra oli Israelille tehnyt.'),
(1675472,58,7,2,8,'Mutta Herran palvelija Joosua, Nuunin poika, kuoli sadan kymmenen vuoden vanhana.'),
(1675473,58,7,2,9,'Ja he hautasivat hänet hänen perintöosansa alueelle Timnat-Herekseen, Efraimin vuoristoon, pohjoispuolelle Gaas-vuorta.'),
(1675474,58,7,2,10,'Ja kun koko sekin sukupolvi oli tullut kootuksi isiensä tykö, nousi heidän jälkeensä toinen sukupolvi, joka ei tuntenut Herraa eikä niitä tekoja, jotka hän oli Israelille tehnyt.'),
(1675475,58,7,2,11,'Niin israelilaiset tekivät sitä, mikä oli pahaa Herran silmissä, ja palvelivat baaleja');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675476,58,7,2,12,'ja hylkäsivät Herran, isiensä Jumalan, joka oli vienyt heidät pois Egyptin maasta, ja lähtivät kulkemaan muiden jumalien jäljessä, niiden kansojen jumalien, jotka asuivat heidän ympärillänsä, kumarsivat niitä ja vihoittivat Herran.'),
(1675477,58,7,2,13,'Mutta kun he hylkäsivät Herran ja palvelivat baalia ja astarteja,'),
(1675478,58,7,2,14,'niin Herran viha syttyi Israelia kohtaan, ja hän antoi heidät ryöstäjien käsiin, jotka ryöstivät heitä, ja myi heidät heidän ympärillään asuvien vihollisten käsiin, niin etteivät he enää voineet kestää vihollistensa edessä.'),
(1675479,58,7,2,15,'Mihin ikinä he lähtivätkin, oli Herran käsi heitä vastaan, tuottaen onnettomuutta, niinkuin Herra oli puhunut ja niinkuin Herra oli heille vannonut; ja niin he joutuivat suureen ahdinkoon.'),
(1675480,58,7,2,16,'Silloin Herra herätti tuomareita, jotka pelastivat heidät heidän ryöstäjäinsä käsistä.'),
(1675481,58,7,2,17,'Mutta he eivät totelleet tuomareitansakaan, vaan kulkivat haureudessa muiden jumalien jäljessä ja kumarsivat niitä. Pian he poikkesivat siltä tieltä, jota heidän isänsä, Herran käskyjä totellen, olivat kulkeneet; he eivät tehneet niin.'),
(1675482,58,7,2,18,'Kun siis Herra herätti heille tuomareita, niin Herra oli tuomarin kanssa ja pelasti heidät heidän vihollistensa käsistä niin kauaksi aikaa, kuin tuomari eli; sillä Herran tuli sääli, kun he voihkivat sortajainsa ja vaivaajainsa käsissä.'),
(1675483,58,7,2,19,'Mutta kun tuomari kuoli, vaelsivat he jälleen kelvottomasti, vielä pahemmin kuin heidän isänsä, kulkien muiden jumalien jäljessä, palvellen ja kumartaen niitä. He eivät lakanneet teoistansa eivätkä paatuneesta vaelluksestansa.'),
(1675484,58,7,2,20,'Niin Herran viha syttyi Israelia kohtaan, ja hän sanoi: "Koska tämä kansa on rikkonut minun liittoni, jonka minä sääsin heidän isillensä, eivätkä he ole kuulleet minun ääntäni,'),
(1675485,58,7,2,21,'niin en minäkään enää karkoita heidän tieltänsä ainoatakaan niistä kansoista, jotka Joosua kuollessaan jätti jäljelle.'),
(1675486,58,7,2,22,'Minä tahdon näin heidän kauttansa koetella Israelia, noudattavatko he Herran tietä ja vaeltavatko sitä, niinkuin heidän isänsä tekivät, vai eivätkö."'),
(1675487,58,7,2,23,'Niin Herra jätti nämä kansat paikoilleen, karkoittamatta niitä heti kohta; hän ei antanut niitä Joosuan käsiin.'),
(1675488,58,7,3,1,'Nämä ovat ne kansat, jotka Herra jätti paikoilleen koetellakseen niiden kautta Israelia, kaikkia niitä, jotka eivät olleet kokeneet mitään kaikista Kanaanin sodista -'),
(1675489,58,7,3,2,'hän jätti ne ainoastaan sitä varten, että israelilaisten sukupolvet saisivat kokea sotaa, hänen opettaessaan heitä sotimaan, kuitenkin ainoastaan niitä, jotka eivät ennen olleet sotaa kokeneet -:'),
(1675490,58,7,3,3,'filistealaisten viisi ruhtinasta ja kaikki kanaanilaiset ja siidonilaiset ja hivviläiset, jotka asuivat Libanonin vuoristossa, Baal-Hermonin vuoresta siihen saakka, mistä mennään Hamatiin.'),
(1675491,58,7,3,4,'Nämä jäivät, että hän niiden kautta koettelisi Israelia saadakseen tietää, tottelisivatko he Herran käskyjä, jotka hän Mooseksen kautta oli antanut heidän isillensä.'),
(1675492,58,7,3,5,'Israelilaiset asuivat siis kanaanilaisten, heettiläisten, amorilaisten, perissiläisten, hivviläisten ja jebusilaisten keskellä,'),
(1675493,58,7,3,6,'ja he ottivat heidän tyttäriänsä vaimoikseen ja antoivat omia tyttäriänsä heidän pojillensa ja palvelivat heidän jumaliansa.'),
(1675494,58,7,3,7,'Näin israelilaiset tekivät sitä, mikä oli pahaa Herran silmissä, ja unhottivat Herran, Jumalansa, ja palvelivat baaleja ja aseroita.'),
(1675495,58,7,3,8,'Silloin Herran viha syttyi Israelia kohtaan, ja hän myi heidät Kuusan-Risataimin, Mesopotamian kuninkaan, käsiin; ja israelilaiset palvelivat Kuusan-Risataimia kahdeksan vuotta.'),
(1675496,58,7,3,9,'Mutta israelilaiset huusivat Herraa, ja Herra herätti israelilaisille vapauttajan, joka heidät vapautti, Otnielin, Kenaan, Kaalebin nuoremman veljen, pojan.'),
(1675497,58,7,3,10,'Ja Herran henki tuli häneen, ja hän oli tuomarina Israelissa; hän lähti sotaan, ja Herra antoi Kuusan-Risataimin, Aramin kuninkaan, hänen käsiinsä, ja Kuusan-Risataim sai tuntea hänen kätensä voimaa.'),
(1675498,58,7,3,11,'Ja maassa oli rauha neljäkymmentä vuotta; sitten Otniel, Kenaan poika, kuoli.'),
(1675499,58,7,3,12,'Mutta israelilaiset tekivät jälleen sitä, mikä oli pahaa Herran silmissä. Silloin Herra vahvisti Eglonin, Mooabin kuninkaan, Israelia väkevämmäksi, koska he tekivät sitä, mikä oli pahaa Herran silmissä.'),
(1675500,58,7,3,13,'Ja tämä kokosi luoksensa ammonilaiset ja amalekilaiset, lähti liikkeelle ja voitti Israelin, ja he valtasivat Palmukaupungin.'),
(1675501,58,7,3,14,'Ja israelilaiset palvelivat Eglonia, mooabilaisten kuningasta, kahdeksantoista vuotta.'),
(1675502,58,7,3,15,'Ja israelilaiset huusivat Herraa, ja Herra herätti heille vapauttajan, benjaminilaisen Eehudin, Geeran pojan, vasenkätisen miehen. Kun israelilaiset lähettivät hänet viemään veroa Eglonille, Mooabin kuninkaalle,'),
(1675503,58,7,3,16,'niin Eehud teki itsellensä kaksiteräisen miekan, jalan pituisen, ja sitoi sen takkinsa alle oikealle kupeelleen.'),
(1675504,58,7,3,17,'Ja hän toi veron Eglonille, Mooabin kuninkaalle. Mutta Eglon oli hyvin lihava mies.'),
(1675505,58,7,3,18,'Kun hän oli saanut tuoduksi veron, saattoi hän väen, joka oli verolahjoja kantanut, matkalle.'),
(1675506,58,7,3,19,'Mutta itse hän kääntyi takaisin Gilgalin luona olevilta jumalankuvilta ja käski sanoa: "Minulla on salaista asiaa sinulle, kuningas". Niin tämä sanoi: "Hiljaa!" Ja kaikki, jotka seisoivat hänen luonaan, menivät hänen luotaan ulos.'),
(1675507,58,7,3,20,'Kun Eehud oli tullut hänen luoksensa, hänen istuessaan yksin viileässä yläsalissaan, sanoi Eehud: "Minulla on sinulle sana Jumalalta". Silloin hän nousi istuimeltaan,'),
(1675508,58,7,3,21,'mutta Eehud ojensi vasemman kätensä ja tempasi miekan oikealta kupeeltaan ja pisti sen hänen vatsaansa,'),
(1675509,58,7,3,22,'niin että kahvakin meni sisään terän mukana ja terä upposi kokonaan ihraan, sillä hän ei vetänyt ulos miekkaa hänen vatsastaan. Sitten hän meni ulos laakealle katolle.'),
(1675510,58,7,3,23,'Kun Eehud oli tullut pylväskäytävään, sulki hän yläsalin ovet jälkeensä ja lukitsi ne.'),
(1675511,58,7,3,24,'Hänen mentyään tulivat kuninkaan palvelijat, ja kun he näkivät, että yläsalin ovet olivat lukitut, niin he ajattelivat: "Varmaankin hän on tarpeellaan viileässä kammiossa".'),
(1675512,58,7,3,25,'Sitten he odottivat kyllästyksiin asti, mutta kun hän ei sittenkään avannut yläsalin ovia, ottivat he avaimen ja avasivat itse. Ja katso, heidän herransa makasi kuolleena lattialla.'),
(1675513,58,7,3,26,'Mutta Eehud oli paennut heidän vitkastellessaan; hän oli jo päässyt jumalankuvien ohi ja pakeni Seiraan.'),
(1675514,58,7,3,27,'Ja sinne tultuaan hän puhalsi pasunaan Efraimin vuoristossa. Silloin israelilaiset laskeutuivat hänen kanssaan vuoristosta, ja hän heidän etunenässään.'),
(1675515,58,7,3,28,'Ja hän sanoi heille: "Seuratkaa minua, sillä Herra antaa teidän vihollisenne, mooabilaiset, teidän käsiinne". Silloin he laskeutuivat hänen jäljessään alas, valtasivat mooabilaisten tieltä Jordanin kahlauspaikat eivätkä päästäneet ketään yli.'),
(1675516,58,7,3,29,'Ja he voittivat silloin Mooabin, lähes kymmenen tuhatta miestä, kaikki voimakkaita ja sotakuntoisia miehiä; eikä ainoakaan päässyt pakoon.'),
(1675517,58,7,3,30,'Niin täytyi Mooabin silloin nöyrtyä Israelin käden alle. Ja maassa oli rauha kahdeksankymmentä vuotta.'),
(1675518,58,7,3,31,'Hänen jälkeensä tuli Samgar, Anatin poika. Hän surmasi filistealaisia kuusisataa miestä häränpistimellä; hänkin vapautti Israelin.'),
(1675519,58,7,4,1,'Mutta Eehudin kuoltua israelilaiset tekivät jälleen sitä, mikä oli pahaa Herran silmissä.'),
(1675520,58,7,4,2,'Silloin Herra myi heidät Jaabinin, Kanaanin kuninkaan, käsiin, joka hallitsi Haasorissa. Hänen sotapäällikkönsä oli Siisera, joka asui Haroset-Goojimissa.'),
(1675521,58,7,4,3,'Ja israelilaiset huusivat Herraa, sillä Siiseralla oli yhdeksätsadat raudoitetut sotavaunut, ja hän sorti ankarasti israelilaisia kaksikymmentä vuotta.'),
(1675522,58,7,4,4,'Mutta Debora, naisprofeetta, Lappidotin vaimo, oli siihen aikaan tuomarina Israelissa.'),
(1675523,58,7,4,5,'Hänen oli tapana istua Deboran-palmun alla, Raaman ja Beetelin välillä, Efraimin vuoristossa, ja israelilaiset menivät hänen luoksensa oikeutta saamaan.'),
(1675524,58,7,4,6,'Hän lähetti kutsumaan Baarakin, Abinoamin pojan, Naftalin Kedeksestä, ja hän sanoi hänelle: "Näin käskee Herra, Israelin Jumala: Lähde ja mene Taaborin vuorelle ja ota mukaasi kymmenentuhatta miestä naftalilaisia ja sebulonilaisia.'),
(1675525,58,7,4,7,'Ja minä tuon sinun luoksesi Kiisonin purolle Siiseran, Jaabinin sotapäällikön, sotavaunuineen ja laumoineen ja annan hänet sinun käsiisi."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675526,58,7,4,8,'Niin Baarak sanoi hänelle: "Jos sinä lähdet minun kanssani, niin minäkin lähden; mutta jos sinä et lähde minun kanssani, niin en minäkään lähde".'),
(1675527,58,7,4,9,'Hän vastasi: "Minä lähden sinun kanssasi; mutta kunnia siitä retkestä, jolle lähdet, ei tule sinulle, vaan Herra on myyvä Siiseran naisen käsiin". Niin Debora nousi ja lähti Baarakin kanssa Kedekseen.'),
(1675528,58,7,4,10,'Silloin Baarak kutsui Sebulonin ja Naftalin koolle Kedekseen; kymmenentuhatta miestä seurasi häntä, ja Debora lähti hänen kanssaan.'),
(1675529,58,7,4,11,'Mutta keeniläinen Heber oli eronnut keeniläisistä, Hoobabin, Mooseksen apen, jälkeläisistä; ja hän oli telttaansa pystytellen tullut aina Saanaimin tammelle asti, joka on Kedeksen luona.'),
(1675530,58,7,4,12,'Kun Siiseralle ilmoitettiin, että Baarak, Abinoamin poika, oli noussut Taaborin vuorelle,'),
(1675531,58,7,4,13,'niin Siisera kutsui koolle kaikki sotavaununsa, yhdeksätsadat raudoitetut sotavaunut, ja kaiken väen, mikä hänellä oli, Haroset-Goojimista Kiisonin purolle.'),
(1675532,58,7,4,14,'Silloin Debora sanoi Baarakille: "Nouse, sillä tämä on se päivä, jona Herra antaa Siiseran sinun käsiisi; onhan Herra lähtenyt sinun edelläsi". Niin Baarak laskeutui Taaborin vuorelta, ja kymmenentuhatta miestä hänen jäljessään.'),
(1675533,58,7,4,15,'Ja Herra saattoi Baarakin miekan terän edessä hämminkiin Siiseran ja kaikki hänen sotavaununsa ja koko hänen joukkonsa; ja Siisera astui alas vaunuistaan ja pakeni jalkaisin.'),
(1675534,58,7,4,16,'Mutta Baarak ajoi takaa sotavaunuja ja sotajoukkoa Haroset-Goojimiin saakka. Ja koko Siiseran joukko kaatui miekan terään; ei ainoakaan pelastunut.'),
(1675535,58,7,4,17,'Mutta Siisera oli paennut jalkaisin Jaaelin, keeniläisen Heberin vaimon, teltalle; sillä Jaabinin, Haasorin kuninkaan, ja keeniläisen Heberin perheen välillä oli rauha.'),
(1675536,58,7,4,18,'Ja Jaael meni Siiseraa vastaan ja sanoi hänelle: "Poikkea, herrani, poikkea minun luokseni, älä pelkää". Ja hän poikkesi hänen luoksensa telttaan, ja hän peitti hänet peitteellä.'),
(1675537,58,7,4,19,'Ja hän sanoi hänelle: "Anna minulle vähän vettä juodakseni, sillä minun on jano". Niin hän avasi maitoleilin ja antoi hänen juoda ja peitti hänet.'),
(1675538,58,7,4,20,'Ja hän sanoi hänelle: "Asetu teltan ovelle; ja jos joku tulee ja kysyy sinulta ja sanoo: ''Onko täällä ketään?'' niin vastaa: ''Ei ole''.'),
(1675539,58,7,4,21,'Mutta Jaael, Heberin vaimo, tempasi telttavaarnan, otti vasaran käteensä, hiipi hänen luoksensa ja löi vaarnan hänen ohimoonsa, niin että se tunkeutui aina maahan asti; hän oli näet väsymyksestä vaipunut sikeään uneen, ja hän kuoli.'),
(1675540,58,7,4,22,'Ja katso, silloin Baarak tuli ajaen Siiseraa takaa; ja Jaael meni häntä vastaan ja sanoi hänelle: "Tule, minä näytän sinulle miehen, jota etsit". Ja hän tuli hänen luoksensa, ja katso, Siisera makasi kuolleena, vaarna ohimossaan.'),
(1675541,58,7,4,23,'Näin Jumala sinä päivänä nöyryytti Jaabinin, Kanaanin kuninkaan, israelilaisten edessä.'),
(1675542,58,7,4,24,'Ja israelilaisten käsi painoi yhä raskaammin Jaabinia, Kanaanin kuningasta, kunnes he tuhosivat Jaabinin, Kanaanin kuninkaan.'),
(1675543,58,7,5,1,'Sinä päivänä Debora ja Baarak, Abinoamin poika, lauloivat näin:'),
(1675544,58,7,5,2,'"Johtajat johtivat Israelia, kansa oli altis - siitä te kiittäkää Herraa.'),
(1675545,58,7,5,3,'Kuulkaa, te kuninkaat, kuunnelkaa, te ruhtinaat. Herran kiitosta minä laulan, minä veisaan Herran, Israelin Jumalan, ylistystä.'),
(1675546,58,7,5,4,'Kun sinä, Herra, lähdit liikkeelle Seiristä, kun sinä tulit astuen Edomin maasta, niin maa järisi, ja taivaat vuotivat, pilvet vuotivat vettä.'),
(1675547,58,7,5,5,'Vuoret järkkyivät Herran edessä, itse Siinai Herran, Israelin Jumalan, edessä.'),
(1675548,58,7,5,6,'Samgarin, Anatin pojan, päivinä, Jaaelin päivinä tiet olivat tyhjinä, matkamiehet kiertelivät syrjäisiä polkuja.'),
(1675549,58,7,5,7,'Israel oli johtoa vailla, peräti vailla, kunnes sinä, Debora, nousit, sinä, Israelin äiti.'),
(1675550,58,7,5,8,'He valitsivat uusia jumalia; silloin oli sota porteilla asti, mutta ei näkynyt kilpeä, ei keihästä Israelin neljänkymmenen tuhannen joukossa.'),
(1675551,58,7,5,9,'Minun sydämeni on kiintynyt Israelin johtomiehiin. Te kansan joukossa alttiit, kiittäkää Herraa.'),
(1675552,58,7,5,10,'Te, jotka ratsastatte valkoisilla aasintammoilla, te, jotka istutte matoilla, ja te, jotka kuljette teillä, puhukaa.'),
(1675553,58,7,5,11,'Laulu kuuluu juotto-ojilta, siellä ylistetään Herran vanhurskaita tekoja, hänen johdatuksensa vanhurskautta Israelissa. Silloin Herran kansa laskeutui porteille.'),
(1675554,58,7,5,12,'Heräjä, heräjä, Debora! Heräjä, heräjä, laula laulu! Nouse, Baarak! Ota vankeja saaliiksesi, sinä Abinoamin poika!'),
(1675555,58,7,5,13,'Silloin pakolaiset laskeutuivat näiden jalojen luo, Herran kansa laskeutui minun luokseni, sankarien joukko.'),
(1675556,58,7,5,14,'Efraimista tulivat ne, jotka olivat juurtuneet Amalekiin, he seurasivat sinun joukkojesi mukana, Benjamin. Maakirista laskeutuivat johtomiehet, Sebulonista ne, jotka kantoivat päällikönsauvaa.'),
(1675557,58,7,5,15,'Ja Isaskarin ruhtinaat tulivat Deboran kanssa, ja niinkuin Baarak, niin Isaskar: hän kiiti tasangolle hänen jäljessänsä. Ruubenin suvuissa oli suuria neuvotteluja.'),
(1675558,58,7,5,16,'Miksi sinä jäit istumaan karjatarhojen välille, kuuntelemaan paimenpillin soittoa? Ruubenin suvuissa oli suuria neuvonpitoja.'),
(1675559,58,7,5,17,'Gilead pysyi alallaan tuolla puolella Jordanin, ja Daan - miksi hän viipyi vierailla laivoilla? Asser jäi istumaan meren rannalle ja pysyi alallaan lahtiensa luona.'),
(1675560,58,7,5,18,'Sebulon on kansa, joka antaa henkensä alttiiksi kuolemaan, samoin Naftali kedon kummuilla.'),
(1675561,58,7,5,19,'Kuninkaat tulivat ja taistelivat, silloin taistelivat Kanaanin kuninkaat Taanakissa, Megiddon vesien varsilla; mutta hopeata he eivät saaneet saaliiksensa.'),
(1675562,58,7,5,20,'Tähdet taivaalta kävivät sotaa, radoiltaan ne sotivat Siiseraa vastaan.'),
(1675563,58,7,5,21,'Kiisonin puro tempasi heidät mukaansa, taistelujen puro, Kiisonin puro. Astu esiin, minun sieluni, voimallisesti!'),
(1675564,58,7,5,22,'Silloin hevosten kaviot tömistivät maata, kun urhot laskivat, laskivat laukkaa.'),
(1675565,58,7,5,23,'Kirotkaa Meeros, sanoo Herran enkeli, kiroamalla kirotkaa sen asukkaat, koska eivät tulleet Herran avuksi, Herran avuksi sankarien joukkoon.'),
(1675566,58,7,5,24,'Siunattu olkoon vaimojen joukossa Jaael, keeniläisen Heberin vaimo, siunattu vaimojen joukossa, jotka teltoissa asuvat.'),
(1675567,58,7,5,25,'Vettä toinen pyysi, maitoa hän antoi, toi juhlamaljassa kermaa.'),
(1675568,58,7,5,26,'Hän ojensi kätensä ottamaan vaarnaa, oikean kätensä työvasaraa; ja hän iski Siiseraa, löi murskaksi hänen päänsä, musersi ja lävisti hänen ohimonsa.'),
(1675569,58,7,5,27,'Hänen jalkainsa juureen hän vaipui, kaatui, jäi siihen, hänen jalkainsa juureen hän vaipui, kaatui; jäi kuolleena makaamaan siihen, mihin vaipui.'),
(1675570,58,7,5,28,'Siiseran äiti katselee ikkunasta ja huutaa ristikon läpi: ''Miksi viipyvät hänen sotavaununsa tulemasta? Miksi ovat hänen valjakkonsa askeleet niin hitaat?'''),
(1675571,58,7,5,29,'Viisain hänen ruhtinattaristaan vastaa hänelle, ja hän kertaa itselleen hänen sanansa:'),
(1675572,58,7,5,30,'''Varmaankin he ovat saaneet saalista ja jakavat sitä: tytön, kaksikin mieheen, kirjavaa kangasta saaliiksi Siiseralle, kirjavaa kangasta, kirjaeltua vaatetta saaliiksi, kaksi kirjaeltua, kirjavaa huivia saatujen saalisten kaulaan''.'),
(1675573,58,7,5,31,'Niin häviävät kaikki sinun vihollisesi, Herra. Mutta ne, jotka häntä rakastavat, ovat niinkuin aurinko, kun se nousee voimassansa." Ja maassa oli rauha neljäkymmentä vuotta.'),
(1675574,58,7,6,1,'Mutta israelilaiset tekivät sitä, mikä oli pahaa Herran silmissä, ja Herra antoi heidät Midianin käsiin seitsemäksi vuodeksi.'),
(1675575,58,7,6,2,'Ja Israel sai tuntea Midianin käden voimaa, ja israelilaiset tekivät suojakseen midianilaisia vastaan ne onkalot, joita on vuorissa, ja luolat ja vuorilinnat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675576,58,7,6,3,'Ja joka kerta kun israelilaiset olivat kylväneet, tulivat midianilaiset, amalekilaiset ja Idän miehet ja hyökkäsivät heidän kimppuunsa.'),
(1675577,58,7,6,4,'He leiriytyivät heitä vastaan ja hävittivät maan sadon aina Gassaa myöten eivätkä jättäneet mitään elintarpeita Israeliin, eivät myöskään lampaita, nautakarjaa eivätkä aaseja.'),
(1675578,58,7,6,5,'Sillä he lähtivät liikkeelle laumoineen ja telttoineen, he tulivat monilukuisina kuin heinäsirkat, heillä ja heidän kameleillaan ei ollut määrää, ja he tulivat maahan sitä hävittämään.'),
(1675579,58,7,6,6,'Niin Israel joutui suureen kurjuuteen midianilaisten tähden; ja israelilaiset huusivat Herraa.'),
(1675580,58,7,6,7,'Ja kun israelilaiset huusivat Herraa Midianin tähden,'),
(1675581,58,7,6,8,'lähetti Herra israelilaisten luo profeetan, joka sanoi heille: "Näin sanoo Herra, Israelin Jumala: Minä johdatin teidät Egyptistä ja vein teidät pois orjuuden pesästä;'),
(1675582,58,7,6,9,'minä pelastin teidät egyptiläisten käsistä ja kaikkien teidän sortajainne käsistä; minä karkoitin heidät teidän tieltänne ja annoin teille heidän maansa.'),
(1675583,58,7,6,10,'Ja minä sanoin teille: Minä olen Herra, teidän Jumalanne, älkää peljätkö amorilaisten jumalia, joiden maassa te asutte. Mutta te ette kuulleet minun ääntäni."'),
(1675584,58,7,6,11,'Ja Herran enkeli tuli ja istui Ofran tammen alle, joka oli abieserilaisen Jooaan oma, juuri kun tämän poika Gideon oli puimassa nisuja viinikuurnassa, korjatakseen ne talteen midianilaisilta.'),
(1675585,58,7,6,12,'Ja Herran enkeli ilmestyi hänelle ja sanoi hänelle: "Herra olkoon sinun kanssasi, sinä sotaurho!"'),
(1675586,58,7,6,13,'Niin Gideon vastasi hänelle: "Oi, Herrani, jos Herra on meidän kanssamme, miksi sitten kaikki tämä on meitä kohdannut? Ja missä ovat kaikki hänen ihmeelliset tekonsa, joista isämme ovat meille kertoneet sanoen: ''Herra on johdattanut meidät tänne Egyptistä''? Mutta nyt Herra on hyljännyt meidät ja antanut meidät Midianin kouriin."'),
(1675587,58,7,6,14,'Silloin Herra kääntyi häneen ja sanoi: "Mene tässä voimassasi ja vapauta Israel Midianin kourista; minä lähetän sinut".'),
(1675588,58,7,6,15,'Hän vastasi hänelle: "Oi, Herra, millä minä vapautan Israelin? Minun sukunihan on heikoin Manassessa, ja minä itse olen kaikkein vähäisin isäni perheessä."'),
(1675589,58,7,6,16,'Herra sanoi hänelle: "Minä olen sinun kanssasi, ja sinä voitat midianilaiset niinkuin yhden ainoan miehen".'),
(1675590,58,7,6,17,'Mutta hän sanoi hänelle: "Jos olen saanut armon sinun silmiesi edessä, niin osoita minulle tunnusteolla, että sinä itse puhut minun kanssani.'),
(1675591,58,7,6,18,'Älä poistu täältä, ennenkuin minä tulen takaisin sinun luoksesi ja tuon uhrilahjani ja panen sen eteesi." Hän sanoi: "Minä jään, kunnes sinä tulet takaisin".'),
(1675592,58,7,6,19,'Gideon meni ja valmisti vohlan, ja eefa-mitan jauhoja happamattomiksi leiviksi, pani lihan koriin ja liemen pataan ja vei ne hänen luoksensa tammen alle ja pani ne tarjolle.'),
(1675593,58,7,6,20,'Mutta Jumalan enkeli sanoi hänelle: "Ota liha ja happamattomat leivät ja pane ne tälle kalliolle ja vuodata liemi". Ja hän teki niin.'),
(1675594,58,7,6,21,'Ja Herran enkeli ojensi sauvan, joka hänellä oli kädessään, ja kosketti sen kärjellä lihaa ja happamattomia leipiä; niin kalliosta nousi tuli, ja se kulutti lihan ja happamattomat leivät. Ja Herran enkeli katosi hänen silmistänsä.'),
(1675595,58,7,6,22,'Kun Gideon näki, että se oli Herran enkeli, sanoi Gideon: "Voi minua, Herra, Herra, kun olen nähnyt Herran enkelin kasvoista kasvoihin!"'),
(1675596,58,7,6,23,'Mutta Herra sanoi hänelle: "Rauha sinulle! Älä pelkää, sinä et kuole."'),
(1675597,58,7,6,24,'Silloin Gideon rakensi siihen Herralle alttarin ja pani sen nimeksi: "Herra on rauha". Se on vielä tänäkin päivänä abieserilaisten Ofrassa.'),
(1675598,58,7,6,25,'Ja sinä yönä Herra sanoi hänelle: "Ota härkä, joka isälläsi on, ja toinen seitsenvuotias härkä ja hajota Baalin alttari, joka isälläsi on, ja hakkaa maahan asera-karsikko, joka on sen vieressä.'),
(1675599,58,7,6,26,'Ja rakenna ladotuista kivistä alttari Herralle, Jumalallesi, tämän vuorenkukkulan laelle; ota sitten se toinen härkä ja uhraa se polttouhriksi halkojen päällä, jotka saat hakkaamastasi asera-karsikosta."'),
(1675600,58,7,6,27,'Niin Gideon otti palvelijoitaan kymmenen miestä ja teki, niinkuin Herra oli hänelle puhunut. Mutta kun hän isänsä perhettä ja kaupungin miehiä peljäten ei uskaltanut tehdä sitä päivällä, teki hän sen yöllä.'),
(1675601,58,7,6,28,'Kun kaupungin miehet varhain seuraavana aamuna nousivat, niin katso, Baalin alttari oli kukistettu ja asera-karsikko sen vierestä hakattu maahan, ja se toinen härkä oli uhrattu polttouhriksi vastarakennetulla alttarilla.'),
(1675602,58,7,6,29,'Niin he sanoivat toinen toiselleen: "Kuka on tämän tehnyt?" Ja kun he tutkivat ja tiedustelivat, niin sanottiin: "Gideon, Jooaan poika, on sen tehnyt".'),
(1675603,58,7,6,30,'Silloin kaupungin miehet sanoivat Jooaalle: "Tuo tänne poikasi, hänen täytyy kuolla, sillä hän on kukistanut Baalin alttarin ja hakannut maahan asera-karsikon sen vierestä".'),
(1675604,58,7,6,31,'Mutta Jooas vastasi kaikille, jotka seisoivat hänen ympärillään: "Tekö ajatte Baalin asiaa, tekö autatte häntä? Se, joka ajaa hänen asiaansa, rangaistakoon kuolemalla ennen huomisaamua. Jos hän on jumala, ajakoon itse asiansa, koska kukistettu alttari oli hänen."'),
(1675605,58,7,6,32,'Sinä päivänä Gideon sai nimekseen Jerubbaal, sillä sanottiin: "Baal ajakoon itse asiansa häntä vastaan, koska hän on kukistanut hänen alttarinsa".'),
(1675606,58,7,6,33,'Kaikki midianilaiset, amalekilaiset ja Idän miehet olivat kokoontuneet yhteen, tulleet virran yli ja leiriytyneet Jisreelin tasangolle.'),
(1675607,58,7,6,34,'Silloin Herran henki täytti Gideonin; hän puhalsi pasunaan, ja niin abieserilaiset kutsuttiin koolle seuraamaan häntä.'),
(1675608,58,7,6,35,'Ja hän lähetti sanansaattajia koko Manasseen, niin että heidätkin kutsuttiin koolle seuraamaan häntä; samoin hän lähetti sanansaattajat Asseriin, Sebuloniin ja Naftaliin, ja nämä lähtivät vihollisia vastaan.'),
(1675609,58,7,6,36,'Silloin Gideon sanoi Jumalalle: "Jos sinä aiot vapauttaa Israelin minun kädelläni, niinkuin olet puhunut,'),
(1675610,58,7,6,37,'niin katso, minä panen nämä kerityt villat puimatantereelle: jos kastetta tulee ainoastaan villoihin ja kaikki maa muuten jää kuivaksi, niin minä siitä tiedän, että sinä minun kädelläni vapautat Israelin, niinkuin olet puhunut".'),
(1675611,58,7,6,38,'Ja tapahtui niin. Sillä kun hän varhain seuraavana päivänä nousi ja puristi villoja, pusersi hän kastetta villoista koko vesimaljan täyden.'),
(1675612,58,7,6,39,'Ja Gideon sanoi Jumalalle: "Älköön vihasi syttykö minua kohtaan, jos minä vielä kerran puhun. Anna minun vielä kerta tehdä koetus villoilla. Anna ainoastaan villojen jäädä kuiviksi ja kastetta tulla kaikkialle muualle maahan."'),
(1675613,58,7,6,40,'Ja Jumala teki niin sinä yönä; ainoastaan villat jäivät kuiviksi, ja kastetta tuli kaikkialle muualle maahan.'),
(1675614,58,7,7,1,'Varhain seuraavana aamuna Jerubbaal, se on Gideon, ynnä kaikki väki, joka oli hänen kanssaan, leiriytyi Harodin lähteelle. Midianilaisten leiri taas oli siitä, Mooren kukkulasta, pohjoiseen päin, tasangolla.'),
(1675615,58,7,7,2,'Mutta Herra sanoi Gideonille: "Sinulla on kanssasi liian paljon väkeä, antaakseni Midianin heidän käsiinsä; muuten Israel voisi kerskua minua vastaan ja sanoa: ''Oma käteni vapautti minut''.'),
(1675616,58,7,7,3,'Julista siis kansan kuullen näin: ''Se, joka pelkää ja on arka, palatkoon takaisin ja väistyköön Gileadin vuorilta''." Niin kansasta palasi takaisin kaksikymmentäkaksi tuhatta, ja kymmenentuhatta jäi.'),
(1675617,58,7,7,4,'Ja Herra sanoi Gideonille: "Vielä on väkeä liian paljon; vie heidät alas veden ääreen, niin minä siellä heidät sinulle tutkin. Se, josta minä sinulle sanon: ''Tämä lähteköön sinun kanssasi'', se lähteköön kanssasi; mutta jokainen, josta minä sinulle sanon: ''Tämä älköön lähtekö sinun kanssasi'', se älköön lähtekö."'),
(1675618,58,7,7,5,'Niin hän vei väen alas veden ääreen. Ja Herra sanoi Gideonille: "Aseta erikseen jokainen, joka latkii vettä kielellään, niinkuin koira latkii, ja samoin jokainen, joka laskeutuu polvilleen juodaksensa".'),
(1675619,58,7,7,6,'Niiden luku, jotka latkivat kädestä suuhunsa, oli kolmesataa miestä; kaikki muu väki oli laskeutunut polvilleen juomaan vettä.'),
(1675620,58,7,7,7,'Silloin Herra sanoi Gideonille: "Niillä kolmellasadalla miehellä, jotka latkivat, minä vapautan teidät ja annan Midianin sinun käsiisi; kaikki muu väki menköön kukin kotiinsa".'),
(1675621,58,7,7,8,'Sitten väki otti mukaansa eväät ja pasunansa, ja hän päästi kaikki Israelin miehet menemään kunkin majalleen, pidättäen ainoastaan ne kolmesataa miestä. Ja midianilaisten leiri oli hänen alapuolellaan tasangolla.'),
(1675622,58,7,7,9,'Sinä yönä Herra sanoi hänelle: "Nouse ja käy leirin kimppuun, sillä minä annan sen sinun käsiisi.'),
(1675623,58,7,7,10,'Mutta jos sinä pelkäät käydä sen kimppuun, niin mene palvelijasi Puuran kanssa alas leiriin'),
(1675624,58,7,7,11,'ja kuuntele, mitä siellä puhutaan. Sitten saat rohkeutta käydä leirin kimppuun." Niin hän meni palvelijansa Puuran kanssa alas aina leirin etuvartijoiden luo.'),
(1675625,58,7,7,12,'Midianilaisia, amalekilaisia ja kaikkia Idän miehiä oli asettunut tasangolle niin paljon kuin heinäsirkkoja; ja heidän kameleillaan ei ollut määrää, niitä oli niin paljon kuin hiekkaa meren rannalla.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675626,58,7,7,13,'Kun Gideon tuli, niin muuan mies kertoi untansa toiselle. Hän sanoi: "Minä näin unta ja katso, ohraleipäkakku tuli pyörien midianilaisten leiriin. Se tuli teltalle saakka, iski siihen niin, että se kaatui, ja käänsi sen ylösalaisin, ja teltta jäi kumoon."'),
(1675627,58,7,7,14,'Niin toinen vastasi ja sanoi: "Se ei ole mikään muu kuin israelilaisen Gideonin, Jooaan pojan, miekka; Jumala antaa hänen käsiinsä Midianin ja koko leirin".'),
(1675628,58,7,7,15,'Kun Gideon oli kuullut kertomuksen unesta ja sen selityksen, niin hän kumartaen rukoili, palasi sitten takaisin Israelin leiriin ja sanoi: "Nouskaa, sillä Herra antaa midianilaisten leirin teidän käsiinne".'),
(1675629,58,7,7,16,'Ja hän jakoi ne kolmesataa miestä kolmeen joukkoon ja antoi heille kullekin käteen pasunan ja tyhjän saviruukun, tulisoihtu ruukussa.'),
(1675630,58,7,7,17,'Ja hän sanoi heille: "Tarkatkaa minua ja tehkää niinkuin minä; kun minä olen tullut leirin laitaan, niin tehkää, niinkuin minä teen.'),
(1675631,58,7,7,18,'Kun minä ja kaikki, jotka ovat minun kanssani, puhallamme pasunoihin, niin puhaltakaa tekin pasunoihin kaikkialla leirin ympärillä ja huutakaa: ''Herran ja Gideonin puolesta!''"'),
(1675632,58,7,7,19,'Niin Gideon ja ne sata miestä, jotka olivat hänen kanssansa, tulivat leirin laitaan keskimmäisen yövartion alussa; vartijat olivat juuri asetetut paikoilleen. Silloin he puhalsivat pasunoihin ja särkivät saviruukut, jotka heillä oli käsissään.'),
(1675633,58,7,7,20,'Niin ne kolme joukkoa puhalsivat pasunoihin, murskasivat saviruukut, tempasivat vasempaan käteensä tulisoihdut ja oikeaan pasunat, puhalsivat niihin ja huusivat: "Herran ja Gideonin miekka!"'),
(1675634,58,7,7,21,'Ja he seisoivat kukin paikallaan leirin ympärillä. Mutta leirissä kaikki juoksivat sekaisin, kirkuivat ja pakenivat.'),
(1675635,58,7,7,22,'Ja kun he puhalsivat noihin kolmeensataan pasunaan, niin Herra käänsi toisen miekan toista vastaan koko leirissä, ja leiri pakeni Beet-Sittaan asti Sereraan päin, Tabbatin luona olevan Aabel-Meholan rantaan saakka.'),
(1675636,58,7,7,23,'Ja Israelin miehet kutsuttiin koolle Naftalista, Asserista ja koko Manassesta, ja he ajoivat midianilaisia takaa.'),
(1675637,58,7,7,24,'Ja Gideon oli lähettänyt sanansaattajia koko Efraimin vuoristoon, sanomaan: "Tulkaa alas midianilaisia vastaan ja vallatkaa heidän tieltään vedet aina Beet-Baaraan asti sekä Jordan". Niin kaikki Efraimin miehet kutsuttiin koolle, ja he valtasivat vedet aina Beet-Baaraan asti sekä Jordanin.'),
(1675638,58,7,7,25,'Ja he ottivat vangiksi kaksi midianilaisten ruhtinasta, Oorebin ja Seebin; Oorebin he surmasivat Oorebin kalliolla, ja Seebin he surmasivat Seebin viinikuurnan luona, ja he ajoivat midianilaisia takaa. Mutta Oorebin ja Seebin päät he toivat Gideonille tuolta puolelta Jordanin.'),
(1675639,58,7,8,1,'Mutta Efraimin miehet sanoivat hänelle: "Miksi teit meille sen, ettet kutsunut meitä, kun menit taistelemaan midianilaisia vastaan?" Ja he riitelivät kovasti häntä vastaan.'),
(1675640,58,7,8,2,'Niin hän sanoi heille: "Mitä minä sitten olen tehnyt teihin verraten? Eikö Efraimin jälkikorjuu ole parempi kuin Abieserin viininkorjuu?'),
(1675641,58,7,8,3,'Teidän käsiinnehän Jumala antoi midianilaisten ruhtinaat Oorebin ja Seebin. Mitä minä olen voinut tehdä teihin verraten?" Kun hän puhui näin, asettui heidän suuttumuksensa häneen.'),
(1675642,58,7,8,4,'Kun Gideon tuli Jordanille, meni hän sen yli, hän ja ne kolmesataa miestä, jotka olivat hänen kanssaan. He olivat uuvuksissa takaa-ajamisesta.'),
(1675643,58,7,8,5,'Ja hän sanoi Sukkotin miehille: "Antakaa joitakin leipäkakkuja väelle, joka seuraa minua, sillä he ovat uuvuksissa; minä olen ajamassa takaa midianilaisten kuninkaita Sebahia ja Salmunnaa".'),
(1675644,58,7,8,6,'Mutta Sukkotin päämiehet sanoivat: "Onko sinulla sitten jo Sebahin ja Salmunnan nyrkki kädessäsi, että me antaisimme leipää sinun sotajoukollesi?"'),
(1675645,58,7,8,7,'Gideon vastasi: "Hyvä! Kun Herra antaa Sebahin ja Salmunnan minun käsiini, puin minä teidän lihanne rikki erämaan orjantappuroilla ja orjanruoskilla."'),
(1675646,58,7,8,8,'Ja hän nousi sieltä Penueliin ja puhui heille samalla tavalla. Ja Penuelin miehet vastasivat hänelle samoin, kuin Sukkotin miehet olivat vastanneet.'),
(1675647,58,7,8,9,'Niin hän sanoi myös Penuelin miehille: "Jahka palaan voittajana, kukistan minä tämän tornin".'),
(1675648,58,7,8,10,'Mutta Sebah ja Salmunna olivat Karkorissa ja heidän joukkonsa heidän kanssansa, noin viisitoista tuhatta miestä, kaikki, mitä oli jäljellä Idän miesten koko joukosta; kaatunut oli sata kaksikymmentä tuhatta miekkamiestä.'),
(1675649,58,7,8,11,'Ja Gideon kulki teltoissa-eläjien tietä Noobahin ja Jogbehan itäpuolitse ja voitti joukon, kun se oli huoletonna leirissään.'),
(1675650,58,7,8,12,'Ja Sebah ja Salmunna pakenivat, mutta hän ajoi heitä takaa; ja hän otti molemmat midianilaisten kuninkaat, Sebahin ja Salmunnan, vangiksi, saatettuaan koko leirin pakokauhun valtaan.'),
(1675651,58,7,8,13,'Ja Gideon, Jooaan poika, palasi taistelusta, Hereksen solalta.'),
(1675652,58,7,8,14,'Ja hän otti kiinni erään nuorukaisen, joka oli Sukkotin miehiä, ja kyseli häneltä, ja tämä kirjoitti hänelle Sukkotin päämiehet ja vanhimmat, seitsemänkymmentä seitsemän miestä.'),
(1675653,58,7,8,15,'Kun hän sitten tuli Sukkotin miesten luo, sanoi hän: "Tässä ovat nyt Sebah ja Salmunna, joilla te pilkkasitte minua sanoen: ''Onko sinulla sitten jo Sebahin ja Salmunnan nyrkki kädessäsi, että me antaisimme leipää sinun uupuneille miehillesi?''"'),
(1675654,58,7,8,16,'Ja hän otti kiinni kaupungin vanhimmat; ja hän otti erämaan orjantappuroita ja orjanruoskia ja antoi Sukkotin miesten maistaa niitä.'),
(1675655,58,7,8,17,'Ja hän kukisti Penuelin tornin ja surmasi kaupungin miehet.'),
(1675656,58,7,8,18,'Sitten hän sanoi Sebahille ja Salmunnalle: "Minkä näköisiä ne miehet olivat, jotka te tapoitte Taaborilla?" He vastasivat: "Ne olivat niinkuin sinä; jokainen oli varreltaan kuin kuninkaan poika".'),
(1675657,58,7,8,19,'Hän sanoi: "He olivat minun veljiäni, minun äitini poikia. Niin totta kuin Herra elää: jos te olisitte jättäneet heidät henkiin, en minä surmaisi teitä."'),
(1675658,58,7,8,20,'Ja hän sanoi Jeterille, esikoiselleen: "Nouse ja surmaa heidät". Mutta nuorukainen ei paljastanut miekkaansa, sillä hän pelkäsi, koska oli vielä nuori.'),
(1675659,58,7,8,21,'Silloin sanoivat Sebah ja Salmunna: "Nouse sinä ja pistä meidät kuoliaaksi, sillä miehellä on miehen voima". Niin Gideon nousi ja surmasi Sebahin ja Salmunnan. Ja hän otti heidän kameliensa kaulasta puolikuukorut.'),
(1675660,58,7,8,22,'Niin Israelin miehet sanoivat Gideonille: "Hallitse sinä meitä, sekä sinä itse että sinun poikasi ja poikasi poika; sillä sinä olet vapauttanut meidät Midianin käsistä".'),
(1675661,58,7,8,23,'Mutta Gideon vastasi heille: "En minä hallitse teitä, eikä minun poikani ole hallitseva teitä; Herra on teitä hallitseva".'),
(1675662,58,7,8,24,'Ja Gideon sanoi heille: "Yhtä minä pyydän teiltä: antakoon kukin minulle heiltä saaliiksi saamansa nenärenkaan". Heikäläisillä näet on kultaiset nenärenkaat, koska ovat ismaelilaisia.'),
(1675663,58,7,8,25,'Niin he vastasivat: "Annamme mielellämme". Ja he levittivät vaipan ja heittivät siihen kukin saaliiksi saamansa nenärenkaan.'),
(1675664,58,7,8,26,'Ja hänen pyytämänsä kultaiset nenärenkaat painoivat tuhat seitsemänsataa kultasekeliä, lukuunottamatta niitä puolikuukoruja, korvarenkaita ja purppuravaatteita, joita midianilaisten kuninkaat olivat kantaneet, ja heidän kameliensa kaulavitjoja.'),
(1675665,58,7,8,27,'Ja Gideon valmisti niistä kasukan, jonka hän sijoitti kaupunkiinsa Ofraan, ja koko Israel kulki haureudessa siellä sen jäljessä. Ja se tuli ansaksi Gideonille ja hänen perheellensä.'),
(1675666,58,7,8,28,'Niin täytyi Midianin nöyrtyä israelilaisten edessä, eikä se enää nostanut päätänsä. Ja maassa oli rauha neljäkymmentä vuotta, niin kauan kuin Gideon eli.'),
(1675667,58,7,8,29,'Ja Jerubbaal, Jooaan poika, meni ja jäi asumaan taloonsa.'),
(1675668,58,7,8,30,'Ja Gideonilla oli seitsemänkymmentä poikaa, jotka olivat lähteneet hänen kupeistansa; sillä hänellä oli monta vaimoa.'),
(1675669,58,7,8,31,'Ja myös hänen sivuvaimonsa, joka hänellä oli Sikemissä, synnytti hänelle pojan, ja hän antoi tälle nimen Abimelek.'),
(1675670,58,7,8,32,'Ja Gideon, Jooaan poika, kuoli päästyään korkeaan ikään, ja hänet haudattiin isänsä Jooaan hautaan abieserilaisten Ofraan.'),
(1675671,58,7,8,33,'Mutta kun Gideon oli kuollut, niin israelilaiset lähtivät jälleen haureudessa kulkemaan baalien jäljessä ja ottivat Baal-Beritin jumalaksensa.'),
(1675672,58,7,8,34,'Eivätkä israelilaiset enää muistaneet Herraa, Jumalaansa, joka oli pelastanut heidät kaikkien heidän vihollistensa käsistä, jotka asuivat heidän ympärillään.'),
(1675673,58,7,8,35,'Eivät he myöskään tehneet Jerubbaalin, Gideonin, perheelle laupeutta kaiken sen hyvän tähden, mitä hän oli tehnyt Israelille.'),
(1675674,58,7,9,1,'Mutta Abimelek, Jerubbaalin poika, meni Sikemiin äitinsä veljien luo ja puhui heille sekä kaikille, jotka olivat sukua hänen äitinsä isän perheelle, ja sanoi:'),
(1675675,58,7,9,2,'"Puhukaa kaikkien Sikemin miesten kuullen: Kumpi teille on parempi, sekö, että teitä hallitsee seitsemänkymmentä miestä, kaikki Jerubbaalin pojat, vai että teitä hallitsee yksi mies? Ja muistakaa, että minä olen teidän luutanne ja lihaanne."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675676,58,7,9,3,'Niin hänen äitinsä veljet puhuivat hänen puolestaan kaikkien Sikemin miesten kuullen kaiken tämän. Ja heidän sydämensä taipui Abimelekin puolelle, sillä he sanoivat: "Hän on meidän veljemme".'),
(1675677,58,7,9,4,'Ja he antoivat hänelle seitsemänkymmentä hopeasekeliä Baal-Beritin temppelistä. Niillä Abimelek palkkasi tyhjäntoimittajia ja huikentelijoita, ja ne seurasivat häntä.'),
(1675678,58,7,9,5,'Sitten hän lähti isänsä taloon Ofraan ja surmasi veljensä, Jerubbaalin pojat, seitsemänkymmentä miestä, saman kiven päällä; mutta Jootam, Jerubbaalin nuorin poika, jäi henkiin, sillä hän oli piiloutunut.'),
(1675679,58,7,9,6,'Sen jälkeen kokoontuivat kaikki Sikemin miehet ja koko Millon väki, ja he menivät ja tekivät Abimelekin kuninkaaksi Muistomerkkitammen luona, joka on Sikemissä.'),
(1675680,58,7,9,7,'Kun se kerrottiin Jootamille, niin hän meni, asettui seisomaan Garissimin vuoren laelle ja korotti äänensä, huusi ja sanoi heille: "Kuulkaa minua, te Sikemin miehet, että Jumalakin kuulisi teitä.'),
(1675681,58,7,9,8,'Puut lähtivät voitelemaan itsellensä kuningasta. Ja he sanoivat öljypuulle: ''Ole sinä meidän kuninkaamme''.'),
(1675682,58,7,9,9,'Mutta öljypuu vastasi heille: ''Jättäisinkö lihavuuteni, josta jumalat ja ihmiset minua ylistävät, mennäkseni huojumaan ylempänä muita puita!'''),
(1675683,58,7,9,10,'Niin puut sanoivat viikunapuulle: ''Tule sinä ja ole meidän kuninkaamme''.'),
(1675684,58,7,9,11,'Mutta viikunapuu vastasi heille: ''Jättäisinkö makeuteni ja hyvät antimeni, mennäkseni huojumaan ylempänä muita puita!'''),
(1675685,58,7,9,12,'Niin puut sanoivat viinipuulle: ''Tule sinä ja ole meidän kuninkaamme''.'),
(1675686,58,7,9,13,'Mutta viinipuu vastasi heille: ''Jättäisinkö mehuni, joka saa jumalat ja ihmiset iloisiksi, mennäkseni huojumaan ylempänä muita puita!'''),
(1675687,58,7,9,14,'Niin kaikki puut sanoivat orjantappuralle: ''Tule sinä ja ole meidän kuninkaamme''.'),
(1675688,58,7,9,15,'Ja orjantappura vastasi puille: ''Jos todella aiotte voidella minut kuninkaaksenne, niin tulkaa ja etsikää suojaa minun varjossani; mutta ellette, niin tuli lähtee orjantappurasta ja kuluttaa Libanonin setrit''.'),
(1675689,58,7,9,16,'Jos te nyt olette menetelleet uskollisesti ja rehellisesti tehdessänne Abimelekin kuninkaaksi ja jos olette kohdelleet hyvin Jerubbaalia ja hänen perhettänsä ja jos olette palkinneet häntä siitä, mitä hänen kätensä ovat hyvää tehneet -'),
(1675690,58,7,9,17,'sillä sotihan minun isäni teidän puolestanne ja pani alttiiksi henkensä ja pelasti teidät Midianin käsistä,'),
(1675691,58,7,9,18,'mutta te olette tänä päivänä nousseet minun isäni perhettä vastaan ja surmanneet hänen poikansa, seitsemänkymmentä miestä, saman kiven päällä ja tehneet Abimelekin, hänen orjattarensa pojan, Sikemin miesten kuninkaaksi, koska hän on teidän veljenne -'),
(1675692,58,7,9,19,'jos te siis olette tänä päivänä menetelleet uskollisesti ja rehellisesti Jerubbaalia ja hänen perhettänsä kohtaan, niin olkoon teillä iloa Abimelekista ja myöskin hänellä olkoon iloa teistä;'),
(1675693,58,7,9,20,'mutta ellette ole, niin lähteköön tuli Abimelekista ja kuluttakoon Sikemin miehet sekä Millon väen; ja samoin lähteköön tuli Sikemin miehistä ja Millon väestä ja kuluttakoon Abimelekin."'),
(1675694,58,7,9,21,'Sitten Jootam lähti pakoon ja pääsi pakenemaan Beeriin; hän asettui sinne suojaan veljeltään Abimelekilta.'),
(1675695,58,7,9,22,'Kun Abimelek oli hallinnut Israelia kolme vuotta,'),
(1675696,58,7,9,23,'lähetti Jumala pahan hengen Abimelekin ja Sikemin miesten väliin, niin että Sikemin miehet luopuivat Abimelekista,'),
(1675697,58,7,9,24,'jotta Jerubbaalin seitsemällekymmenelle pojalle tehty väkivalta tulisi kostetuksi ja heidän verensä tulisi Abimelekin, heidän veljensä, päälle, joka oli heidät surmannut, ja Sikemin miesten päälle, jotka olivat auttaneet häntä surmaamaan veljensä.'),
(1675698,58,7,9,25,'Ja Sikemin miehet asettivat vuorten kukkuloille väijyjiä, ja nämä ryöstivät jokaisen, joka kulki sitä tietä heidän ohitsensa. Se kerrottiin Abimelekille.'),
(1675699,58,7,9,26,'Mutta Gaal, Ebedin poika, tuli veljineen, ja he poikkesivat Sikemiin; ja Sikemin miehet luottivat häneen.'),
(1675700,58,7,9,27,'Ja he menivät kedolle ja korjasivat sadon viinitarhoistaan, polkivat rypäleet ja pitivät ilojuhlan; he menivät jumalansa huoneeseen ja söivät ja joivat ja kirosivat Abimelekia.'),
(1675701,58,7,9,28,'Ja Gaal, Ebedin poika, sanoi: "Mikä on Abimelek, ja mikä on Sikem, että me häntä palvelisimme? Eikö hän ole Jerubbaalin poika, eikö Sebul ole hänen käskynhaltijansa? Palvelkaa Hamorin, Sikemin isän, miehiä. Miksi me palvelisimme häntä?'),
(1675702,58,7,9,29,'Olisipa minulla tuo kansa vallassani, niin minä toimittaisin pois Abimelekin; ja Abimelekista hän sanoi: ''Lisää sotajoukkoasi ja tule!''"'),
(1675703,58,7,9,30,'Mutta kun Sebul, kaupungin päällikkö, kuuli Gaalin, Ebedin pojan, sanat, syttyi hänen vihansa.'),
(1675704,58,7,9,31,'Ja hän lähetti salaa sanansaattajia Abimelekin luo sanomaan: "Katso, Gaal, Ebedin poika, ja hänen veljensä ovat tulleet Sikemiin, ja nyt he yllyttävät kaupunkia sinua vastaan.'),
(1675705,58,7,9,32,'Nouse siis yöllä, sinä ja väki, joka on sinun kanssasi, ja asetu kedolle väijyksiin.'),
(1675706,58,7,9,33,'Ja karkaa aamulla varhain, auringon noustessa, kaupungin kimppuun. Kun hän ja väki, joka on hänen kanssaan, silloin lähtee sinua vastaan, niin tee hänelle, minkä voit."'),
(1675707,58,7,9,34,'Silloin Abimelek ja kaikki väki, joka oli hänen kanssaan, lähti liikkeelle yöllä, ja he asettuivat väijyksiin Sikemiä vastaan neljässä joukossa.'),
(1675708,58,7,9,35,'Ja Gaal, Ebedin poika, tuli ulos ja asettui kaupungin portin ovelle; niin Abimelek ja väki, joka oli hänen kanssaan, nousi väijytyspaikasta.'),
(1675709,58,7,9,36,'Kun Gaal näki väen, sanoi hän Sebulille: "Katso, väkeä tulee alas vuorten kukkuloilta". Mutta Sebul vastasi hänelle: "Vuorten varjot näyttävät sinusta miehiltä".'),
(1675710,58,7,9,37,'Gaal puhui taas ja sanoi: "Katso, väkeä tulee alas Maannavalta; ja toinen joukko tulee Tietäjätammelta päin".'),
(1675711,58,7,9,38,'Silloin Sebul sanoi hänelle: "Missä on nyt sinun suuri suusi, kun sanoit: ''Mikä on Abimelek, että me häntä palvelisimme?'' Siinä on nyt se väki, jota halveksit. Mene nyt ja taistele heitä vastaan."'),
(1675712,58,7,9,39,'Niin Gaal lähti Sikemin miesten etunenässä ja taisteli Abimelekia vastaan.'),
(1675713,58,7,9,40,'Mutta Abimelek ajoi hänet pakoon, ja hän pääsi pakenemaan häntä; ja heitä kaatui paljon, aina portin ovelle asti.'),
(1675714,58,7,9,41,'Ja Abimelek jäi Arumaan; mutta Sebul karkoitti Gaalin ja hänen veljensä pois Sikemistä.'),
(1675715,58,7,9,42,'Seuraavana päivänä kansa lähti ulos kedolle, ja siitä ilmoitettiin Abimelekille.'),
(1675716,58,7,9,43,'Silloin hän otti väkensä ja jakoi sen kolmeen joukkoon ja asettui väijyksiin kedolle. Ja kun hän näki kansan lähtevän kaupungista, hyökkäsi hän heidän kimppuunsa ja surmasi heidät.'),
(1675717,58,7,9,44,'Abimelek ja ne joukot, jotka olivat hänen kanssaan, karkasivat näet esiin ja asettuivat kaupungin portin ovelle, samalla kuin muut kaksi joukkoa karkasivat kaikkien niiden kimppuun, jotka olivat kedolla, ja surmasivat heidät.'),
(1675718,58,7,9,45,'Sitten Abimelek taisteli kaupunkia vastaan koko sen päivän, valloitti kaupungin ja surmasi kansan, joka siellä oli. Ja hän hävitti kaupungin ja kylvi suolaa sen paikalle.'),
(1675719,58,7,9,46,'Kun kaikki Sikemin tornin miehet sen kuulivat, menivät he Eel-Beritin temppelin holviin.'),
(1675720,58,7,9,47,'Mutta kun Abimelekille kerrottiin, että kaikki Sikemin tornin miehet olivat kokoontuneet sinne,'),
(1675721,58,7,9,48,'niin Abimelek nousi Salmonin vuorelle, hän ja kaikki väki, joka oli hänen kanssaan. Ja Abimelek otti kirveen käteensä ja löi poikki puunoksan, nosti ja pani sen olalleen ja sanoi väelle, joka oli hänen kanssaan: "Mitä näitte minun tekevän, se tehkää tekin joutuin".'),
(1675722,58,7,9,49,'Niin väestäkin löi poikki oksansa kukin; sitten he seurasivat Abimelekia, panivat oksat holvin päälle ja sytyttivät holvin heidän päällään palamaan. Niin saivat surmansa myöskin kaikki Sikemin tornin asukkaat, noin tuhat miestä ja naista.'),
(1675723,58,7,9,50,'Sitten Abimelek meni Teebekseen, asettui leiriin Teebestä vastaan ja valloitti sen.'),
(1675724,58,7,9,51,'Mutta kaupungin keskellä oli luja torni, ja kaikki miehet ja naiset, kaikki kaupungin asukkaat, pakenivat siihen. He sulkivat jälkeensä oven ja nousivat tornin katolle.'),
(1675725,58,7,9,52,'Niin Abimelek tuli tornin ääreen ja ryhtyi taisteluun sitä vastaan; ja hän astui tornin ovelle polttaakseen sen tulella.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675726,58,7,9,53,'Mutta eräs nainen heitti jauhinkiven Abimelekin päähän ja murskasi hänen pääkallonsa.'),
(1675727,58,7,9,54,'Silloin hän heti huusi palvelijalle, joka kantoi hänen aseitansa, ja sanoi hänelle: "Paljasta miekkasi ja surmaa minut, ettei minusta sanottaisi: ''Nainen tappoi hänet''". Ja hänen palvelijansa lävisti hänet, ja hän kuoli.'),
(1675728,58,7,9,55,'Kun Israelin miehet näkivät, että Abimelek oli kuollut, menivät he kukin kotiinsa.'),
(1675729,58,7,9,56,'Näin Jumala kosti Abimelekille sen pahan, minkä hän oli tehnyt isäänsä kohtaan surmatessaan seitsemänkymmentä veljeään;'),
(1675730,58,7,9,57,'ja kaiken Sikemin miesten tekemän pahan Jumala käänsi heidän omaan päähänsä. Niin heidät saavutti Jootamin, Jerubbaalin pojan, kirous.'),
(1675731,58,7,10,1,'Abimelekin jälkeen nousi Israelia vapauttamaan isaskarilainen Toola, Doodon pojan Puuan poika, joka asui Saamirissa, Efraimin vuoristossa.'),
(1675732,58,7,10,2,'Hän oli tuomarina Israelissa kaksikymmentä kolme vuotta; sitten hän kuoli, ja hänet haudattiin Saamiriin.'),
(1675733,58,7,10,3,'Hänen jälkeensä nousi gileadilainen Jaair ja oli tuomarina Israelissa kaksikymmentä kaksi vuotta.'),
(1675734,58,7,10,4,'Ja hänellä oli kolmekymmentä poikaa, jotka ratsastivat kolmellakymmenellä aasilla; ja heillä oli kolmekymmentä kaupunkia, joita vielä tänäkin päivänä kutsutaan Jaairin leirikyliksi ja jotka ovat Gileadin maassa.'),
(1675735,58,7,10,5,'Ja Jaair kuoli, ja hänet haudattiin Kaamoniin.'),
(1675736,58,7,10,6,'Mutta israelilaiset tekivät jälleen sitä, mikä oli pahaa Herran silmissä, ja palvelivat baaleja ja astarteja ja Aramin jumalia, Siidonin jumalia, Mooabin jumalia, ammonilaisten jumalia ja filistealaisten jumalia, ja he hylkäsivät Herran eivätkä palvelleet häntä.'),
(1675737,58,7,10,7,'Niin Herran viha syttyi Israelia kohtaan, ja hän myi heidät filistealaisten ja ammonilaisten käsiin.'),
(1675738,58,7,10,8,'Nämä riistivät ja raastivat israelilaisia sen vuoden ja vielä kahdeksantoista vuotta, kaikkia israelilaisia, jotka asuivat tuolla puolella Jordanin amorilaisten maassa, Gileadissa.'),
(1675739,58,7,10,9,'Ja ammonilaiset menivät Jordanin yli taistelemaan myöskin Juudaa, Benjaminia ja Efraimin heimoa vastaan, ja niin Israel joutui suureen ahdinkoon.'),
(1675740,58,7,10,10,'Silloin israelilaiset huusivat Herraa sanoen: "Me olemme tehneet syntiä sinua vastaan, sillä me olemme hyljänneet oman Jumalamme ja palvelleet baaleja".'),
(1675741,58,7,10,11,'Ja Herra vastasi israelilaisille: "Eivätkö egyptiläiset, amorilaiset, ammonilaiset, filistealaiset,'),
(1675742,58,7,10,12,'siidonilaiset, amalekilaiset ja maaonilaiset sortaneet teitä, ja kun te huusitte minua, enkö minä pelastanut teitä heidän käsistänsä.'),
(1675743,58,7,10,13,'Mutta te hylkäsitte minut ja palvelitte muita jumalia; sentähden en minä enää teitä pelasta.'),
(1675744,58,7,10,14,'Menkää ja huutakaa avuksenne niitä jumalia, jotka olette valinneet; pelastakoot ne teidät ahdinkonne aikana."'),
(1675745,58,7,10,15,'Niin israelilaiset sanoivat Herralle: "Me olemme syntiä tehneet; tee sinä meille aivan niinkuin hyväksi näet, kunhan vain tänä päivänä autat meitä".'),
(1675746,58,7,10,16,'Ja he poistivat vieraat jumalat keskuudestaan ja palvelivat Herraa. Silloin hän ei enää kärsinyt, että Israelia vaivattiin.'),
(1675747,58,7,10,17,'Ja ammonilaiset kutsuttiin koolle, ja he leiriytyivät Gileadiin; mutta israelilaiset kokoontuivat ja leiriytyivät Mispaan.'),
(1675748,58,7,10,18,'Silloin kansa, Gileadin ruhtinaat, sanoivat toisillensa: "Kuka on se mies, joka alkaa taistelun ammonilaisia vastaan? Hän on oleva kaikkien Gileadin asukasten päämies."'),
(1675749,58,7,11,1,'Gileadilainen Jefta oli sotaurho, mutta hän oli porton poika; Jeftan isä oli Gilead.'),
(1675750,58,7,11,2,'Mutta Gileadin vaimo synnytti hänelle poikia, ja kun tämän vaimon pojat kasvoivat suuriksi, niin he karkoittivat Jeftan ja sanoivat hänelle: "Et sinä saa perintöosaa meidän isämme talossa, sillä sinä olet toisen naisen poika".'),
(1675751,58,7,11,3,'Niin Jefta lähti pakoon veljiänsä ja asettui Toobin maahan. Ja Jeftan luo kerääntyi tyhjäntoimittajia, ja ne retkeilivät yhdessä hänen kanssaan.'),
(1675752,58,7,11,4,'Jonkun ajan kuluttua ammonilaiset aloittivat sodan Israelia vastaan.'),
(1675753,58,7,11,5,'Kun nyt ammonilaiset alottivat sodan Israelia vastaan, niin Gileadin vanhimmat lähtivät noutamaan Jeftaa Toobin maasta.'),
(1675754,58,7,11,6,'Ja he sanoivat Jeftalle: "Tule ja rupea meidän päälliköksemme, sotiaksemme ammonilaisia vastaan".'),
(1675755,58,7,11,7,'Mutta Jefta vastasi Gileadin vanhimmille: "Ettekö te vihanneet minua ja karkoittaneet minua isäni talosta? Minkätähden tulette minun luokseni nyt, kun teillä on hätä?"'),
(1675756,58,7,11,8,'Gileadin vanhimmat sanoivat Jeftalle: "Juuri sentähden olemme nyt tulleet jälleen sinun luoksesi; ja jos sinä tulet meidän kanssamme ja ryhdyt taistelemaan ammonilaisia vastaan, niin sinä olet oleva meidän, kaikkien Gileadin asukasten, päämies".'),
(1675757,58,7,11,9,'Jefta vastasi Gileadin vanhimmille: "Jos te viette minut takaisin, taistelemaan ammonilaisia vastaan, ja Herra antaa heidät minun valtaani, niin minä rupean teidän päämieheksenne".'),
(1675758,58,7,11,10,'Silloin Gileadin vanhimmat sanoivat Jeftalle: "Herra kuulee meidän välipuheemme; totisesti, me teemme kaiken, mitä sinä sanoit".'),
(1675759,58,7,11,11,'Niin Jefta lähti Gileadin vanhinten kanssa, ja kansa asetti hänet päämiehekseen ja päällikökseen. Ja Jefta lausui Herran edessä Mispassa kaiken, mitä oli puhunut.'),
(1675760,58,7,11,12,'Sitten Jefta lähetti ammonilaisten kuninkaan luo sanansaattajia sanomaan: "Mitä sinulla on minun kanssani tekemistä, kun tulet minua vastaan, sotimaan minun maatani vastaan?"'),
(1675761,58,7,11,13,'Niin ammonilaisten kuningas vastasi Jeftan sanansaattajille: "Ottihan Israel tullessaan Egyptistä minun maani Arnonista Jabbokiin ja Jordaniin asti; anna se nyt hyvällä takaisin".'),
(1675762,58,7,11,14,'Jefta lähetti taas sanansaattajia ammonilaisten kuninkaan luo'),
(1675763,58,7,11,15,'ja käski sanoa hänelle: "Näin sanoo Jefta: Ei Israel ole ottanut Mooabin maata eikä ammonilaisten maata.'),
(1675764,58,7,11,16,'Sillä tullessaan Egyptistä Israel kulki erämaan kautta Kaislamerelle saakka ja tuli Kaadekseen.'),
(1675765,58,7,11,17,'Ja Israel lähetti sanansaattajia Edomin kuninkaan luo sanomaan: ''Salli minun kulkea maasi läpi''. Mutta Edomin kuningas ei kuullut heitä. Ja he lähettivät sanan myöskin Mooabin kuninkaalle, mutta ei hänkään suostunut. Niin Israel asettui Kaadekseen.'),
(1675766,58,7,11,18,'Sitten he kulkivat erämaan kautta ja kiersivät Edomin maan ja Mooabin maan ja tulivat itäpuolelle Mooabin maata ja leiriytyivät Arnonin toiselle puolelle; he eivät tulleet Mooabin alueelle, sillä Arnon on Mooabin raja.'),
(1675767,58,7,11,19,'Silloin Israel lähetti sanansaattajia Siihoniin, amorilaisten kuninkaan, Hesbonin kuninkaan, luo, ja Israel käski sanoa hänelle: ''Salli meidän kulkea maasi läpi määräpaikkaamme''.'),
(1675768,58,7,11,20,'Mutta Siihon ei uskonut Israelia, niin että olisi sallinut sen kulkea alueensa läpi, vaan Siihon kokosi kaiken väkensä, ja he leiriytyivät Jahaaseen, ja hän ryhtyi taisteluun Israelia vastaan.'),
(1675769,58,7,11,21,'Mutta Herra, Israelin Jumala, antoi Siihonin ja kaiken hänen väkensä Israelin käsiin, niin että nämä voittivat heidät. Ja Israel valloitti koko amorilaisten maan, niiden, jotka asuivat siinä maassa.'),
(1675770,58,7,11,22,'Ja he ottivat omakseen koko amorilaisten alueen Arnonista Jabbokiin asti ja erämaasta Jordaniin saakka.'),
(1675771,58,7,11,23,'Näin siis Herra, Israelin Jumala, karkoitti amorilaiset kansansa Israelin tieltä. Ja nyt sinä ottaisit omaksesi heidän maansa!'),
(1675772,58,7,11,24,'Eikö ole niin: minkä sinun jumalasi Kemos antaa sinun omaksesi, sen sinä otat omaksesi; ja kenen hyvänsä Herra, meidän Jumalamme, karkoittaa meidän tieltämme, sen maan me otamme omaksemme?'),
(1675773,58,7,11,25,'Vai oletko sinä parempi kuin Baalak, Sipporin poika, Mooabin kuningas? Rakensiko hän riitaa Israelin kanssa, tahi ryhtyikö hän sotaan heitä vastaan?'),
(1675774,58,7,11,26,'Israel on nyt asunut Hesbonissa ja sen tytärkaupungeissa, Aroerissa ja sen tytärkaupungeissa ja kaikissa Arnonin varrella olevissa kaupungeissa kolmesataa vuotta. Miksi te ette sen ajan kuluessa ole ottaneet niitä pois?'),
(1675775,58,7,11,27,'Minä en ole rikkonut sinua vastaan, mutta sinä teet pahasti minua kohtaan, kun ryhdyt sotimaan minua vastaan. Herra, joka on tuomari, tuomitkoon tänä päivänä israelilaisten ja ammonilaisten välillä."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675776,58,7,11,28,'Mutta ammonilaisten kuningas ei ottanut kuuloonsa, mitä Jefta lähetti hänelle sanomaan.'),
(1675777,58,7,11,29,'Silloin Herran henki tuli Jeftaan, ja hän kulki Gileadin ja Manassen läpi ja kulki edelleen Gileadin Mispeen, ja Gileadin Mispestä hän lähti ammonilaisia vastaan.'),
(1675778,58,7,11,30,'Ja Jefta teki lupauksen Herralle ja sanoi: "Jos sinä annat ammonilaiset minun käsiini,'),
(1675779,58,7,11,31,'niin tulkoon kuka tulkoonkin minua vastaan taloni ovesta, kun minä voittajana palaan ammonilaisten luota, hän on oleva Herran, ja minä uhraan hänet polttouhriksi".'),
(1675780,58,7,11,32,'Sitten Jefta lähti ammonilaisia vastaan, sotimaan heitä vastaan, ja Herra antoi heidät hänen käsiinsä.'),
(1675781,58,7,11,33,'Ja hän tuotti heille hyvin suuren tappion, valloittaen maan Aroerista Minnitiin ja Aabel-Keramimiin asti, kaksikymmentä kaupunkia. Niin täytyi ammonilaisten nöyrtyä israelilaisten edessä.'),
(1675782,58,7,11,34,'Kun Jefta sitten tuli kotiinsa Mispaan, niin katso, hänen tyttärensä tuli ulos häntä vastaan vaskirumpua lyöden ja karkeloiden. Ja hän oli hänen ainoa lapsensa; paitsi tätä ei hänellä ollut poikaa eikä tytärtä.'),
(1675783,58,7,11,35,'Nähdessään hänet hän repäisi vaatteensa ja sanoi: "Voi, tyttäreni, nyt sinä masennat minut maahan, nyt sinä syökset minut onnettomuuteen! Sillä minä avasin suuni Herralle enkä voi sanaani peruuttaa."'),
(1675784,58,7,11,36,'Niin hän vastasi hänelle: "Isäni, jos sinä avasit suusi Herralle, niin tee minulle, niinkuin suusi on puhunut, koska Herra on antanut sinun kostaa vihollisillesi, ammonilaisille".'),
(1675785,58,7,11,37,'Sitten hän sanoi isällensä: "Myönnettäköön minulle kuitenkin tämä: jätä minut vapauteeni kahdeksi kuukaudeksi, että minä yhdessä ystävättärieni kanssa menen vuorille itkemään neitsyyttäni".'),
(1675786,58,7,11,38,'Niin hän sanoi: "Mene!" ja päästi hänet menemään kahdeksi kuukaudeksi. Ja hän meni ystävättärineen ja itki neitsyyttänsä vuorilla.'),
(1675787,58,7,11,39,'Mutta kahden kuukauden kuluttua hän palasi isänsä luo, ja tämä pani hänessä täytäntöön lupauksensa, jonka oli tehnyt. Eikä hän miehestä tietänyt. Ja tuli tavaksi Israelissa,'),
(1675788,58,7,11,40,'että Israelin tyttäret joka vuosi menivät lauluin ylistämään gileadilaisen Jeftan tytärtä - neljän päivän ajaksi joka vuosi.'),
(1675789,58,7,12,1,'Ja Efraimin miehet kutsuttiin koolle, ja he lähtivät pohjoiseen päin ja sanoivat Jeftalle: "Miksi lähdit sotimaan ammonilaisia vastaan kutsumatta meitä tulemaan kanssasi? Me poltamme tulella sinun talosi pääsi päältä."'),
(1675790,58,7,12,2,'Jefta vastasi heille: "Minulla ja minun kansallani oli kova taistelu ammonilaisten kanssa; silloin minä kutsuin teitä, mutta te ette tulleet auttamaan minua heidän käsistään.'),
(1675791,58,7,12,3,'Ja kun minä näin, ettette tulleet auttamaan minua, panin minä henkeni kämmenelleni ja lähdin ammonilaisia vastaan, ja Herra antoi heidät minun käsiini. Miksi te olette nyt lähteneet minua vastaan, sotimaan minua vastaan?"'),
(1675792,58,7,12,4,'Ja Jefta kokosi kaikki Gileadin miehet ja ryhtyi taisteluun Efraimia vastaan; ja Gileadin miehet voittivat efraimilaiset, jotka olivat sanoneet: "Te olette karkureita Efraimista; Gilead on Efraimin ja Manassen keskessä".'),
(1675793,58,7,12,5,'Ja gileadilaiset valtasivat efraimilaisten tieltä Jordanin kahlauspaikat. Kun sitten Efraimin pakolaiset sanoivat: "Antakaa minun mennä yli", kysyivät Gileadin miehet kultakin: "Oletko efraimilainen?" Jos hän vastasi: "En",'),
(1675794,58,7,12,6,'niin he sanoivat hänelle: "Sano ''shibbolet''". Jos hän sanoi "sibbolet", kun ei osannut ääntää oikein, ottivat he hänet kiinni ja tappoivat Jordanin kahlauspaikoilla. Niin kaatui silloin Efraimista neljäkymmentäkaksi tuhatta.'),
(1675795,58,7,12,7,'Ja Jefta oli tuomarina Israelissa kuusi vuotta; sitten gileadilainen Jefta kuoli, ja hänet haudattiin erääseen Gileadin kaupunkiin.'),
(1675796,58,7,12,8,'Hänen jälkeensä oli Ibsan, Beetlehemistä, tuomarina Israelissa.'),
(1675797,58,7,12,9,'Hänellä oli kolmekymmentä poikaa, ja hän naitti kolmekymmentä tytärtänsä muualle ja toi muualta kolmekymmentä tyttöä pojilleen vaimoiksi. Ja hän oli tuomarina Israelissa seitsemän vuotta.'),
(1675798,58,7,12,10,'Sitten Ibsan kuoli, ja hänet haudattiin Beetlehemiin.'),
(1675799,58,7,12,11,'Hänen jälkeensä oli sebulonilainen Eelon tuomarina Israelissa; hän oli tuomarina Israelissa kymmenen vuotta.'),
(1675800,58,7,12,12,'Sitten sebulonilainen Eelon kuoli, ja hänet haudattiin Aijaloniin, Sebulonin maahan.'),
(1675801,58,7,12,13,'Hänen jälkeensä oli piratonilainen Abdon, Hillelin poika, tuomarina Israelissa.'),
(1675802,58,7,12,14,'Hänellä oli neljäkymmentä poikaa ja kolmekymmentä pojanpoikaa, jotka ratsastivat seitsemälläkymmenellä aasilla; hän oli tuomarina Israelissa kahdeksan vuotta.'),
(1675803,58,7,12,15,'Sitten piratonilainen Abdon, Hillelin poika, kuoli, ja hänet haudattiin Piratoniin, Efraimin maahan, amalekilaisten vuoristoon.'),
(1675804,58,7,13,1,'Kun israelilaiset taas tekivät sitä, mikä oli pahaa Herran silmissä, niin Herra antoi heidät filistealaisten käsiin neljäksikymmeneksi vuodeksi.'),
(1675805,58,7,13,2,'Sorassa oli mies, Daanin sukukuntaa, nimeltä Maanoah; hänen vaimonsa oli hedelmätön eikä ollut synnyttänyt.'),
(1675806,58,7,13,3,'Silloin ilmestyi Herran enkeli vaimolle ja sanoi hänelle: "Katso, sinä olet hedelmätön etkä ole synnyttänyt, mutta sinä tulet raskaaksi ja synnytät pojan.'),
(1675807,58,7,13,4,'Varo siis, ettet juo viiniä ja väkijuomaa etkä syö mitään saastaista.'),
(1675808,58,7,13,5,'Sillä katso, sinä tulet raskaaksi ja synnytät pojan; partaveitsi älköön koskettako hänen päätänsä, sillä poika on oleva Jumalan nasiiri äitinsä kohdusta asti, ja hän on alottava Israelin vapauttamisen filistealaisten käsistä."'),
(1675809,58,7,13,6,'Niin vaimo meni ja sanoi miehelleen näin: "Jumalan mies tuli minun luokseni; hän oli näöltään niinkuin Jumalan enkeli, hyvin peljättävä. En kysynyt häneltä, mistä hän oli, eikä hän ilmaissut minulle nimeänsä.'),
(1675810,58,7,13,7,'Ja hän sanoi minulle: ''Katso, sinä tulet raskaaksi ja synnytät pojan; älä siis juo viiniä ja väkijuomaa äläkä syö mitään saastaista, sillä poika on oleva Jumalan nasiiri äitinsä kohdusta aina kuolinpäiväänsä asti''."'),
(1675811,58,7,13,8,'Silloin Maanoah rukoili Herraa ja sanoi: "Oi Herra, salli Jumalan miehen, jonka lähetit, vielä tulla luoksemme opettamaan meille, mitä meidän on tehtävä pojalle, joka on syntyvä".'),
(1675812,58,7,13,9,'Ja Jumala kuuli Maanoahin rukouksen, ja Jumalan enkeli tuli jälleen vaimon tykö, kun tämä istui kedolla; ja Maanoah, hänen miehensä, ei ollut hänen kanssaan.'),
(1675813,58,7,13,10,'Niin vaimo juoksi nopeasti ilmoittamaan miehellensä ja sanoi hänelle: "Katso, sama mies, joka äsken kävi luonani, ilmestyi minulle".'),
(1675814,58,7,13,11,'Niin Maanoah nousi ja seurasi vaimoaan. Ja kun hän tuli miehen luo, sanoi hän tälle: "Sinäkö olet se mies, joka puhuttelit tätä vaimoa?" Hän vastasi: "Minä".'),
(1675815,58,7,13,12,'Silloin Maanoah sanoi: "Kun sanasi käy toteen, miten sitten on meneteltävä pojan kanssa ja mitä hänelle on tehtävä?"'),
(1675816,58,7,13,13,'Herran enkeli sanoi Maanoahille: "Varokoon vaimo kaikkea, mistä minä olen hänelle puhunut:'),
(1675817,58,7,13,14,'älköön syökö mitään, mikä viiniköynnöksestä tulee, viiniä ja väkijuomaa hän älköön juoko älköönkä syökö mitään saastaista. Noudattakoon hän kaikkea, mitä minä olen käskenyt hänen noudattaa."'),
(1675818,58,7,13,15,'Ja Maanoah sanoi Herran enkelille: "Salli meidän pidättää sinua valmistaaksemme sinulle vohlan".'),
(1675819,58,7,13,16,'Mutta Herran enkeli vastasi Maanoahille: "Vaikka sinä pidättäisitkin minut, en minä kuitenkaan söisi sinun ruokaasi; mutta jos tahdot valmistaa polttouhrin, niin uhraa se Herralle". Sillä Maanoah ei tiennyt häntä Herran enkeliksi.'),
(1675820,58,7,13,17,'Niin Maanoah sanoi Herran enkelille: "Mikä on sinun nimesi, kunnioittaaksemme sinua, kun sinun sanasi käy toteen?"'),
(1675821,58,7,13,18,'Herran enkeli vastasi hänelle: "Minkätähden kysyt minun nimeäni? Se on ihmeellinen."'),
(1675822,58,7,13,19,'Niin Maanoah otti vohlan ja ruokauhrin ja uhrasi sen kalliolla Herralle. Ja Herra teki ihmeen Maanoahin ja hänen vaimonsa nähden:'),
(1675823,58,7,13,20,'liekin kohotessa alttarilta taivasta kohti kohosi Herran enkeli alttarin liekissä ylös Maanoahin ja hänen vaimonsa nähden, ja he heittäytyivät kasvoilleen maahan;'),
(1675824,58,7,13,21,'eikä Herran enkeli enää ilmestynyt Maanoahille ja hänen vaimollensa. Nyt Maanoah tiesi hänet Herran enkeliksi.'),
(1675825,58,7,13,22,'Niin Maanoah sanoi vaimolleen: "Me olemme kuoleman omat, sillä olemme nähneet Jumalan".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675826,58,7,13,23,'Mutta hänen vaimonsa vastasi hänelle: "Jos Herra tahtoisi surmata meidät, ei hän olisi ottanut meiltä vastaan polttouhria ja ruokauhria eikä antanut meidän nähdä tätä kaikkea eikä antanut meidän juuri nyt tätä kuulla".'),
(1675827,58,7,13,24,'Ja vaimo synnytti pojan ja antoi hänelle nimen Simson; ja poika kasvoi, ja Herra siunasi häntä.'),
(1675828,58,7,13,25,'Ja Herran henki alkoi hänessä vaikuttaa Daanin leirissä, Soran ja Estaolin välillä.'),
(1675829,58,7,14,1,'Ja Simson meni alas Timnaan ja näki Timnassa naisen, filistealaisten tyttäriä.'),
(1675830,58,7,14,2,'Niin hän tuli sieltä ja kertoi sen isälleen ja äidilleen ja sanoi: "Minä näin Timnassa naisen, filistealaisten tyttäriä; ottakaa hänet nyt minulle vaimoksi".'),
(1675831,58,7,14,3,'Hänen isänsä ja äitinsä sanoivat hänelle: "Eikö ole yhtään naista veljiesi tyttärien joukossa ja minun koko kansassani, kun aiot mennä ottamaan vaimon ympärileikkaamattomien filistealaisten joukosta?" Mutta Simson sanoi isälleen: "Ota hänet minulle, sillä hän on mieluinen minun silmissäni".'),
(1675832,58,7,14,4,'Mutta hänen isänsä ja äitinsä eivät tienneet, että se tuli Herralta, sillä hän etsi tilaisuutta filistealaisia vastaan. Filistealaiset näet hallitsivat siihen aikaan Israelia.'),
(1675833,58,7,14,5,'Niin Simson meni isänsä ja äitinsä kanssa alas Timnaan. Mutta kun he saapuivat Timnan viinitarhoille, niin katso, nuori leijona tuli kiljuen häntä vastaan.'),
(1675834,58,7,14,6,'Silloin Herran henki tuli häneen, niin että hän repäisi sen, niinkuin olisi reväissyt vohlan, sulin käsin. Eikä hän ilmoittanut isälleen eikä äidilleen, mitä oli tehnyt.'),
(1675835,58,7,14,7,'Sitten hän meni sinne ja puhutteli naista, ja tämä oli mieluinen Simsonin silmissä.'),
(1675836,58,7,14,8,'Ja kun hän jonkun ajan kuluttua palasi sinne ottaakseen hänet, poikkesi hän katsomaan leijonan raatoa, ja katso, leijonan ruumiissa oli mehiläisparvi ja hunajaa.'),
(1675837,58,7,14,9,'Ja hän kaapi hunajan kouriinsa ja kulki edelleen ja söi sitä. Niin hän tuli isänsä ja äitinsä luo ja antoi heille, ja he söivät. Mutta hän ei sanonut heille, että oli kaapinut hunajan leijonan ruumiista.'),
(1675838,58,7,14,10,'Sitten hänen isänsä meni naisen luo, ja Simson laittoi siellä pidot, sillä niin oli nuorten miesten tapa.'),
(1675839,58,7,14,11,'Mutta kun he näkivät hänet, valitsivat he kolmekymmentä sulhaspoikaa olemaan hänen kanssaan.'),
(1675840,58,7,14,12,'Niin Simson sanoi heille: "Minä panen teille arvoituksen; jos selitätte sen minulle seitsemän pitopäivän kuluessa ja arvaatte oikein, niin minä annan teille kolmekymmentä aivinapaitaa ja kolmekymmentä juhlapukua.'),
(1675841,58,7,14,13,'Mutta ellette voi sitä minulle selittää, niin te annatte minulle kolmekymmentä aivinapaitaa ja kolmekymmentä juhlapukua." Ja he sanoivat hänelle: "Lausu arvoituksesi, että saamme sen kuulla".'),
(1675842,58,7,14,14,'Silloin hän sanoi heille: "Lähti syötävä syömäristä, lähti väkevästä makea". Mutta he eivät voineet kolmeen päivään selittää arvoitusta.'),
(1675843,58,7,14,15,'Seitsemäntenä päivänä he sanoivat Simsonin vaimolle: "Viekoittele miehesi selittämään meille arvoitus, muuten me poltamme sinut ja sinun isäsi talon tulella. Oletteko kutsuneet meidät tänne köyhdyttääksenne meitä, vai kuinka?"'),
(1675844,58,7,14,16,'Niin Simsonin vaimo ahdisti häntä itkullaan ja sanoi: "Sinähän vihaat minua etkä rakasta; sinä olet pannut arvoituksen minun kansalaisilleni etkä selitä sitä minulle". Mutta hän vastasi hänelle: "En ole selittänyt sitä edes isälleni enkä äidilleni, sinulleko sen selittäisin!"'),
(1675845,58,7,14,17,'Niin hän ahdisti häntä itkullaan ne seitsemän päivää, jotka heidän pitonsa kestivät. Mutta seitsemäntenä päivänä Simson selitti hänelle, koska vaimo häntä ahdisti. Ja vaimo selitti arvoituksen kansalaisilleen.'),
(1675846,58,7,14,18,'Niin kaupungin miehet sanoivat hänelle seitsemäntenä päivänä, ennenkuin aurinko laski: "Mikä on makeampaa kuin hunaja, ja mikä leijonaa väkevämpi?" Hän vastasi heille: "Ellette olisi kyntäneet minun vasikallani, ette olisi arvoitustani arvanneet".'),
(1675847,58,7,14,19,'Silloin Herran Henki tuli häneen, ja hän meni Askeloniin, löi siellä kuoliaaksi kolmekymmentä miestä, otti heiltä vaatteet ja antoi juhlapuvut arvoituksen selittäjille. Ja hänen vihansa syttyi, ja hän meni isänsä kotiin.'),
(1675848,58,7,14,20,'Mutta Simsonin vaimo joutui sille sulhaspojista, joka oli ollut yljän ystävänä.'),
(1675849,58,7,15,1,'Jonkun ajan kuluttua, nisunleikkuuaikana, tuli Simson katsomaan vaimoansa, tuomisinaan vohla, ja sanoi: "Minä menen vaimoni luo sisähuoneeseen". Mutta tämän isä ei sallinut hänen mennä,'),
(1675850,58,7,15,2,'vaan sanoi: "Minä tosiaankin luulin, että olit ruvennut vihaamaan häntä, ja annoin hänet sinun sulhaspojallesi. Mutta onhan hänen nuorempi sisarensa häntä kauniimpi, sinä saat hänet toisen sijaan".'),
(1675851,58,7,15,3,'Mutta Simson vastasi heille: "Nyt minä en tule syynalaiseksi filistealaisista, vaikka teenkin heille pahaa".'),
(1675852,58,7,15,4,'Niin Simson meni ja pyydysti kolmesataa kettua. Ja hän otti tulisoihtuja, sitoi aina kaksi häntää yhteen ja asetti tulisoihdun kunkin häntäparin väliin.'),
(1675853,58,7,15,5,'Sitten hän sytytti tulisoihdut ja päästi ketut menemään filistealaisten viljapeltoihin; näin hän sytytti palamaan sekä kuhilaat että kasvavan viljan, viinitarhat ja öljypuut.'),
(1675854,58,7,15,6,'Niin filistealaiset kysyivät: "Kuka tämän on tehnyt?" Vastattiin: "Simson, timnalaisen vävy, koska tämä otti hänen vaimonsa ja antoi sen hänen sulhaspojalleen". Niin filistealaiset menivät ja polttivat sekä vaimon että hänen isänsä tulessa.'),
(1675855,58,7,15,7,'Mutta Simson sanoi heille: "Koska te näin teette, niin totisesti minä en lakkaa, ennenkuin olen kostanut teille".'),
(1675856,58,7,15,8,'Ja hän pieksi heitä pahasti kupeisiin jos kinttuihinkin. Sitten hän meni ja asettui asumaan Eetamin kallioluolaan.'),
(1675857,58,7,15,9,'Silloin filistealaiset lähtivät liikkeelle, leiriytyivät Juudaan ja levittäytyivät Lehin tienoille.'),
(1675858,58,7,15,10,'Ja Juudan miehet kysyivät: "Miksi te olette tulleet meitä vastaan?" He vastasivat: "Me olemme tulleet sitomaan Simsonin tehdäksemme hänelle, niinkuin hän teki meille".'),
(1675859,58,7,15,11,'Niin kolmetuhatta miestä Juudasta meni Eetamin kallioluolalle, ja he sanoivat Simsonille: "Etkö tiedä, että filistealaiset hallitsevat meitä; mitä oletkaan meille tehnyt!" Hän vastasi heille: "Niinkuin he tekivät minulle, niin minäkin tein heille".'),
(1675860,58,7,15,12,'He sanoivat hänelle: "Me tulimme sitomaan sinut antaaksemme sinut filistealaisten käsiin". Mutta Simson sanoi heille: "Vannokaa minulle, ettette itse lyö minua kuoliaaksi".'),
(1675861,58,7,15,13,'Niin he vastasivat hänelle sanoen: "Emme lyö; me ainoastaan sidomme sinut ja annamme sinut heidän käsiinsä, mutta emme sinua surmaa". Ja he sitoivat hänet kahdella uudella köydellä ja veivät hänet pois kalliolta.'),
(1675862,58,7,15,14,'Kun hän saapui Lehiin, niin filistealaiset riensivät riemuhuudoin häntä vastaan. Silloin Herran henki tuli häneen, ja samalla köydet hänen käsivarsissaan olivat kuin tulen polttamat aivinalangat, ja hänen siteensä sulivat pois hänen käsistänsä.'),
(1675863,58,7,15,15,'Ja hän huomasi tuoreen aasinleukaluun, ojensi kätensä, otti sen ja löi sillä kuoliaaksi tuhat miestä.'),
(1675864,58,7,15,16,'Ja Simson sanoi: "Aasinleukaluulla minä löin heitä läjään, löin kahteen, aasinleukaluulla löin heitä tuhannen miestä".'),
(1675865,58,7,15,17,'Sen sanottuaan hän heitti leukaluun kädestänsä. Niin sen paikan nimeksi tuli Raamat-Lehi.'),
(1675866,58,7,15,18,'Mutta kun hän oli kovin janoissaan, niin hän huusi Herraa ja sanoi: "Sinä annoit palvelijasi käden kautta tämän suuren voiton; ja nyt minä kuolen janoon ja joudun ympärileikkaamattomien käsiin".'),
(1675867,58,7,15,19,'Silloin Jumala avasi hampaankolon leukaluussa, ja siitä vuoti vettä; hän joi, ja hänen henkensä elpyi, ja hän virkistyi. Siitä lähde sai nimekseen Een-Hakkore; se on vielä tänäkin päivänä Lehissä.'),
(1675868,58,7,15,20,'Ja hän oli filistealaisten aikana tuomarina Israelissa kaksikymmentä vuotta.'),
(1675869,58,7,16,1,'Niin Simson meni Gassaan, ja hän näki siellä porton ja meni sen luo.'),
(1675870,58,7,16,2,'Kun gassalaisille kerrottiin, että Simson oli tullut sinne, niin he piirittivät hänet ja väijyivät häntä koko yön kaupungin portilla. Mutta he olivat hiljaa koko yön, ajatellen: "Kun aamu valkenee, surmaamme hänet".'),
(1675871,58,7,16,3,'Ja Simson makasi siellä puoliyöhön asti. Mutta puoliyön aikana hän nousi, tarttui kaupungin portin oviin ja molempiin pihtipieliin, nosti ne salpoineen paikaltansa, asetti hartioilleen ja vei ne sen vuoren laelle, joka on vastapäätä Hebronia.'),
(1675872,58,7,16,4,'Sen jälkeen hän rakastui erääseen Soorekin laaksossa asuvaan naiseen, jonka nimi oli Delila.'),
(1675873,58,7,16,5,'Niin filistealaisten ruhtinaat tulivat naisen luo ja sanoivat hänelle: "Viekoittele hänet ja ota selko, missä hänen suuri voimansa on ja miten voisimme voittaa hänet, että saisimme hänet sidotuksi ja masennetuksi; niin me annamme sinulle kukin tuhat ja sata hopeasekeliä".'),
(1675874,58,7,16,6,'Silloin Delila sanoi Simsonille: "Ilmaise minulle, missä sinun suuri voimasi on ja miten sinut voidaan sitoa ja masentaa".'),
(1675875,58,7,16,7,'Simson vastasi hänelle: "Jos minut sidotaan seitsemällä tuoreella jänteellä, jotka eivät ole kuivuneet, niin minä tulen heikoksi ja olen niinkuin muutkin ihmiset".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675876,58,7,16,8,'Niin filistealaisten ruhtinaat toivat naiselle seitsemän tuoretta jännettä, jotka eivät olleet kuivuneet, ja hän sitoi hänet niillä.'),
(1675877,58,7,16,9,'Mutta sisähuoneessa hänellä istui väijyjiä. Ja hän sanoi hänelle: "Filistealaiset ovat kimpussasi, Simson!" Silloin tämä katkaisi jänteet, niinkuin katkeaa tulen kärventämä rohdinlanka. Ei siis päästy hänen voimansa perille.'),
(1675878,58,7,16,10,'Ja Delila sanoi Simsonille: "Katso, sinä olet pettänyt minut ja valhetellut minulle. Ilmaise nyt minulle, miten sinut voidaan sitoa."'),
(1675879,58,7,16,11,'Niin hän sanoi hänelle: "Jos minut sidotaan uusilla köysillä, joilla ei ole tehty työtä, niin minä tulen heikoksi ja olen niinkuin muutkin ihmiset".'),
(1675880,58,7,16,12,'Niin Delila otti uudet köydet, sitoi hänet niillä ja sanoi hänelle: "Filistealaiset ovat kimpussasi, Simson!" Ja sisähuoneessa istui väijyjiä. Mutta hän katkaisi ne käsivarsistaan niinkuin langan.'),
(1675881,58,7,16,13,'Niin Delila sanoi Simsonille: "Sinä olet tähän asti minua pettänyt ja valhetellut minulle; ilmaise minulle, miten sinut voidaan sitoa". Niin hän vastasi hänelle: "Jos kudot minun pääni seitsemän palmikkoa kankaan loimiin".'),
(1675882,58,7,16,14,'Ja hän löi ne lujaan iskulastalla. Sitten hän sanoi hänelle: "Filistealaiset ovat kimpussasi, Simson!" Kun hän heräsi unestansa, repäisi hän irti iskulastan ja loimet.'),
(1675883,58,7,16,15,'Niin nainen sanoi hänelle: "Kuinka sinä saatat sanoa: ''Minä rakastan sinua'', vaikka sydämesi ei ole minun kanssani? Jo kolme kertaa olet pettänyt minut etkä ole minulle ilmaissut, missä sinun suuri voimasi on."'),
(1675884,58,7,16,16,'Ja kun hän joka päivä ahdisti häntä sanoillansa ja vaivasi häntä, niin hän kiusautui kuollakseen'),
(1675885,58,7,16,17,'ja paljasti hänelle koko sydämensä ja sanoi hänelle: "Ei ole partaveitsi minun päätäni koskettanut, sillä minä olen Jumalan nasiiri äitini kohdusta asti; jos minun hiukseni ajetaan, niin voimani poistuu minusta, ja minä tulen heikoksi ja olen niinkuin kaikki muutkin ihmiset".'),
(1675886,58,7,16,18,'Kun Delila huomasi, että hän oli paljastanut hänelle koko sydämensä, niin hän lähetti kutsumaan filistealaisten ruhtinaat sanoen: "Nyt tulkaa, sillä hän on paljastanut minulle koko sydämensä". Niin filistealaisten ruhtinaat tulivat hänen luoksensa tuoden mukanaan rahat.'),
(1675887,58,7,16,19,'Ja hän nukutti hänet polvilleen ja kutsui miehen, joka leikkasi hänen päänsä seitsemän palmikkoa. Niin hän alkoi saada hänet masennetuksi, ja hänen voimansa poistui hänestä.'),
(1675888,58,7,16,20,'Ja Delila sanoi: "Filistealaiset ovat kimpussasi, Simson!" Kun hän heräsi unestaan, niin hän ajatteli: "Kyllä minä selviydyn niinkuin aina ennenkin ja pudistan itseni vapaaksi". Eikä hän tiennyt, että Herra oli poistunut hänestä.'),
(1675889,58,7,16,21,'Silloin filistealaiset ottivat hänet kiinni ja puhkaisivat hänen silmänsä. Ja he veivät hänet Gassaan ja kytkivät hänet vaskikahleisiin, ja hänen täytyi jauhaa vankilassa.'),
(1675890,58,7,16,22,'Mutta hiukset rupesivat jälleen kasvamaan hänen päähänsä sen jälkeen, kuin ne olivat ajetut.'),
(1675891,58,7,16,23,'Niin filistealaisten ruhtinaat kokoontuivat uhraamaan suurta uhria jumalalleen Daagonille ja iloa pitämään, sillä he sanoivat: "Meidän jumalamme on antanut vihollisemme Simsonin meidän käsiimme".'),
(1675892,58,7,16,24,'Kun kansa näki hänet, niin he ylistivät jumalaansa, sillä he sanoivat: "Meidän jumalamme on antanut käsiimme vihollisemme, maamme hävittäjän, sen, joka surmasi meistä niin monta".'),
(1675893,58,7,16,25,'Ja kun heidän sydämensä olivat tulleet iloisiksi, niin he sanoivat: "Noutakaa Simson huvittamaan meitä". Niin Simson noudettiin vankilasta huvittamaan heitä. Ja he asettivat hänet seisomaan pylvästen väliin.'),
(1675894,58,7,16,26,'Silloin Simson sanoi palvelijalle, joka piti kiinni hänen kädestään: "Päästä minut tunnustelemaan pylväitä, joiden varassa rakennus on, nojatakseni niihin".'),
(1675895,58,7,16,27,'Mutta huone oli täynnä miehiä ja naisia; myöskin kaikki filistealaisten ruhtinaat olivat siellä, ja katolla oli noin kolmetuhatta miestä ja naista katselemassa, kuinka Simson heitä huvitti.'),
(1675896,58,7,16,28,'Silloin Simson huusi Herraa ja sanoi: "Herra, Herra, muista minua ja vahvista minua ainoastaan tämä kerta, oi Jumala, niin että saisin filistealaisille yhdellä kertaa kostetuksi molemmat silmäni!"'),
(1675897,58,7,16,29,'Sitten Simson kiersi käsivartensa molempien keskipylväiden ympäri, joiden varassa rakennus oli, toisen ympäri oikean ja toisen ympäri vasemman käsivartensa, ja painautui niitä vastaan.'),
(1675898,58,7,16,30,'Ja Simson sanoi: "Menköön oma henkeni yhdessä filistealaisten kanssa!" Ja hän taivuttautui eteenpäin niin rajusti, että rakennus luhistui ruhtinasten ja kaiken siinä olevan kansan päälle. Ja kuolleita, jotka hän surmasi kuollessaan, oli enemmän kuin niitä, jotka hän oli surmannut eläessään.'),
(1675899,58,7,16,31,'Niin hänen veljensä ja koko hänen isänsä perhe menivät ja ottivat hänet ja veivät ja hautasivat hänet Soran ja Estaolin välille, hänen isänsä Maanoahin hautaan. Hän oli ollut tuomarina Israelissa kaksikymmentä vuotta.'),
(1675900,58,7,17,1,'Efraimin vuoristossa oli mies, nimeltä Miika.'),
(1675901,58,7,17,2,'Hän sanoi äidillensä: "Ne tuhat ja sata hopeasekeliä, jotka sinulta otettiin ja joiden tähden sinä lausuit vannotuksen minunkin kuulteni, katso, ne rahat ovat minulla; minä ne otin". Silloin sanoi hänen äitinsä: "Herra siunatkoon sinua, poikani!"'),
(1675902,58,7,17,3,'Niin hän antoi takaisin äidilleen ne tuhat ja sata hopeasekeliä. Mutta hänen äitinsä sanoi: "Minä pyhitän nämä rahat Herralle ja luovutan ne pojalleni veistetyn ja valetun jumalankuvan teettämistä varten. Nyt minä annan ne sinulle takaisin."'),
(1675903,58,7,17,4,'Mutta hän antoi rahat takaisin äidilleen. Ja hänen äitinsä otti kaksisataa hopeasekeliä ja antoi ne kultasepälle, joka niistä teki veistetyn ja valetun jumalankuvan. Se oli sitten Miikan talossa.'),
(1675904,58,7,17,5,'Sillä miehellä, Miikalla, oli siis jumalanhuone, ja hän teetti kasukan ja kotijumalien kuvia ja asetti yhden pojistaan itsellensä papiksi.'),
(1675905,58,7,17,6,'Siihen aikaan ei ollut kuningasta Israelissa, ja jokainen teki sitä, mikä hänen omasta mielestään oli oikein.'),
(1675906,58,7,17,7,'Juudan Beetlehemissä oli nuori mies, Juudan sukukuntaa; hän oli leeviläinen ja asui siellä muukalaisena.'),
(1675907,58,7,17,8,'Tämä mies lähti siitä kaupungista, Juudan Beetlehemistä, asuaksensa muukalaisena, missä vain sopisi; ja vaeltaessaan tietänsä hän tuli Efraimin vuoristoon, Miikan talolle asti.'),
(1675908,58,7,17,9,'Miika kysyi häneltä: "Mistä sinä tulet?" Hän vastasi: "Minä olen leeviläinen Juudan Beetlehemistä ja vaellan asuakseni muukalaisena, missä vain sopii".'),
(1675909,58,7,17,10,'Miika sanoi hänelle: "Asetu minun luokseni ja tule minun isäkseni ja papikseni, niin minä annan sinulle vuosittain kymmenen hopeasekeliä ja vaatetuksen ja elatuksesi". Niin leeviläinen tuli.'),
(1675910,58,7,17,11,'Ja leeviläinen suostui asettumaan sen miehen luo, ja tämä piti sitä nuorta miestä kuin omaa poikaansa.'),
(1675911,58,7,17,12,'Miika asetti leeviläisen virkaan, ja nuoresta miehestä tuli hänen pappinsa, ja hän jäi Miikan taloon.'),
(1675912,58,7,17,13,'Ja Miika sanoi: "Nyt minä tiedän, että Herra tekee minulle hyvää, sillä minulla on pappina leeviläinen".'),
(1675913,58,7,18,1,'Siihen aikaan ei ollut kuningasta Israelissa; ja siihen aikaan daanilaisten sukukunta etsi itsellensä perintöosaa asuttavaksensa, sillä siihen päivään asti se ei ollut saanut perintöosaa Israelin sukukuntien kesken.'),
(1675914,58,7,18,2,'Ja daanilaiset lähettivät sukukuntansa keskuudesta viisi miestä, sotakuntoisia miehiä Sorasta ja Estaolista, vakoilemaan maata ja tutkimaan sitä; he sanoivat heille: "Menkää tutkimaan maata". Ja nämä tulivat Efraimin vuoristoon, Miikan talolle asti, ja yöpyivät sinne.'),
(1675915,58,7,18,3,'Ollessaan Miikan talon luona he tunsivat nuoren miehen hänen äänestään leeviläiseksi; niin he poikkesivat sinne ja kysyivät häneltä: "Kuka on tuonut sinut tänne? Mitä sinä täällä toimitat, ja mitä sinulla on täällä tekemistä?"'),
(1675916,58,7,18,4,'Hän vastasi heille: "Niin ja niin teki Miika minulle ja palkkasi minut papiksensa".'),
(1675917,58,7,18,5,'Ja he sanoivat hänelle: "Kysy Jumalalta, että saisimme tietää, onnistuuko matka, jolla me olemme".'),
(1675918,58,7,18,6,'Pappi vastasi heille: "Menkää rauhassa. Matka, jolla olette, tapahtuu Herran edessä."'),
(1675919,58,7,18,7,'Niin ne viisi miestä jatkoivat matkaansa ja tulivat Laikseen; ja he näkivät, että sikäläinen kansa asui huoleti siidonilaisten tavoin, rauhassa ja huoletonna; eikä kukaan tehnyt vahinkoa siinä maassa rikkauksia anastamalla. Myöskin olivat he kaukana siidonilaisista eivätkä olleet tekemisissä muitten ihmisten kanssa.'),
(1675920,58,7,18,8,'Ja he tulivat veljiensä luo Soraan ja Estaoliin, ja heidän veljensä kysyivät heiltä: "Mitä kuuluu?"'),
(1675921,58,7,18,9,'He sanoivat: "Nouskaa, lähtekäämme heitä vastaan. Sillä me olemme katselleet maata, ja katso, se on hyvin hyvä. Ja tekö jäisitte toimettomiksi! Älkää viivytelkö, lähtekää liikkeelle, menkää sinne ja ottakaa omaksenne se maa.'),
(1675922,58,7,18,10,'Kun tulette sinne, tulette huoletonna elävän kansan luo, ja maa on tilava joka suuntaan. Niin, Jumala antaa sen teidän käsiinne, paikan, jossa ei ole puutetta mistään, mitä maan päällä on."'),
(1675923,58,7,18,11,'Niin lähti sieltä liikkeelle, daanilaisten sukukunnasta, Sorasta ja Estaolista, kuusisataa sota-aseilla varustettua miestä.'),
(1675924,58,7,18,12,'He nousivat Juudan Kirjat-Jearimiin ja leiriytyivät sinne. Sentähden kutsutaan sitä paikkaa vielä tänäkin päivänä "Daanin leiriksi"; se on Kirjat-Jearimin takana.'),
(1675925,58,7,18,13,'Sieltä he kulkivat Efraimin vuoristoon ja tulivat Miikan talolle asti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675926,58,7,18,14,'Niin ne viisi miestä, jotka olivat käyneet vakoilemassa Laiksen maata, rupesivat puhumaan ja sanoivat veljillensä: "Tiedättekö, että noissa huoneissa on kasukka ja kotijumalia sekä veistetty ja valettu jumalankuva? Miettikää siis, mitä teidän on tehtävä."'),
(1675927,58,7,18,15,'Niin he poikkesivat sinne ja tulivat sen nuoren leeviläisen miehen asunnolle, Miikan taloon, ja tervehtivät häntä.'),
(1675928,58,7,18,16,'Ja ne kuusisataa sota-aseilla varustettua daanilaista asettuivat portin oven eteen.'),
(1675929,58,7,18,17,'Ja ne viisi miestä, jotka olivat käyneet vakoilemassa maata, nousivat taloon, menivät sisään ja ottivat veistetyn jumalankuvan ja kasukan ja kotijumalat ja valetun jumalankuvan, mutta pappi ja ne kuusisataa sota-aseilla varustettua miestä seisoivat portin oven edessä.'),
(1675930,58,7,18,18,'Kun he menivät Miikan taloon ja ottivat veistetyn jumalankuvan ja kasukan ja kotijumalat ja valetun jumalankuvan, niin pappi kysyi heiltä: "Mitä te teette?"'),
(1675931,58,7,18,19,'He vastasivat hänelle: "Vaikene, pidä suusi kiinni ja lähde meidän kanssamme ja tule meidän isäksemme ja papiksemme. Onko parempi ollaksesi pappina yhden miehen talossa kuin Israelin heimon ja sukukunnan pappina?"'),
(1675932,58,7,18,20,'Silloin pappi tuli hyville mielin, ja hän otti kasukan ja kotijumalat ja veistetyn jumalankuvan ja meni väen keskeen.'),
(1675933,58,7,18,21,'Sitten he kääntyivät jatkamaan matkaansa ja panivat vaimot ja lapset sekä karjan ja kuormaston kulkemaan edellänsä.'),
(1675934,58,7,18,22,'He olivat ehtineet vähän matkaa Miikan talosta, kun Miikan talon lähitalojen miehet kutsuttiin koolle, ja he pääsivät daanilaisten kintereille.'),
(1675935,58,7,18,23,'Ja he huusivat daanilaisille; nämä kääntyivät ja kysyivät Miikalta: "Mikä sinun on, kun väkesi on noin kutsuttu koolle?"'),
(1675936,58,7,18,24,'Hän vastasi: "Te olette ottaneet minun jumalani, jotka minä olen teettänyt, ja papin, ja menette matkoihinne. Mitä on minulla enää jäljellä? Ja kuinka te vielä kysytte minulta: ''Mikä sinun on''?"'),
(1675937,58,7,18,25,'Mutta daanilaiset sanoivat hänelle: "Herkeä huutamasta meille, muuten miehet ärtyvät ja käyvät kimppuunne, ja te menetätte henkenne, sekä sinä että sinun perheesi".'),
(1675938,58,7,18,26,'Niin daanilaiset jatkoivat matkaansa, ja kun Miika näki, että he olivat häntä voimakkaammat, kääntyi hän ja palasi kotiinsa.'),
(1675939,58,7,18,27,'Otettuaan siis sen, minkä Miika oli teettänyt, sekä hänen pappinsa, hyökkäsivät he Laiksen rauhassa ja huoletonna elävän kansan kimppuun ja surmasivat heidät miekan terällä ja polttivat kaupungin tulella.'),
(1675940,58,7,18,28,'Eikä kukaan tullut avuksi, sillä se oli kaukana Siidonista eivätkä he olleet tekemisissä muitten ihmisten kanssa; se oli Beet-Rehobin tasangolla. Daanilaiset rakensivat kaupungin uudestaan ja asettuivat siihen.'),
(1675941,58,7,18,29,'Ja he antoivat kaupungille nimen Daan, isänsä Daanin nimen mukaan, hänen, joka oli Israelille syntynyt; mutta ennen oli kaupungin nimi ollut Lais.'),
(1675942,58,7,18,30,'Sitten daanilaiset pystyttivät itsellensä sen veistetyn jumalankuvan; ja Joonatan, Manassen pojan Geersomin poika, ja hänen poikansa olivat daanilaisten sukukunnan pappeina, kunnes maan väestö vietiin pakkosiirtolaisuuteen.'),
(1675943,58,7,18,31,'He pystyttivät itsellensä sen veistetyn jumalankuvan, jonka Miika oli teettänyt, ja se oli siinä koko ajan, minkä Jumalan huone oli Siilossa.'),
(1675944,58,7,19,1,'Siihen aikaan, kun ei ollut kuningasta Israelissa, asui eräs leeviläinen mies muukalaisena Efraimin vuoriston perukoilla, ja hän otti itselleen sivuvaimon Juudan Beetlehemistä.'),
(1675945,58,7,19,2,'Mutta hänen sivuvaimonsa oli hänelle uskoton ja meni hänen luotansa isänsä kotiin Juudan Beetlehemiin, ja hän oli siellä jonkun aikaa, neljä kuukautta.'),
(1675946,58,7,19,3,'Sitten hänen miehensä nousi ja lähti hänen jälkeensä viihdytelläkseen häntä ja palauttaakseen hänet luokseen; ja hänellä oli mukanaan palvelija ja aasipari. Ja nainen vei hänet isänsä kotiin; ja kun naisen isä näki hänet, riensi hän iloisena häntä vastaan.'),
(1675947,58,7,19,4,'Ja hänen appensa, naisen isä, pidätteli häntä, niin että hän viipyi hänen luonaan kolme päivää; he söivät ja joivat ja olivat siellä yötä.'),
(1675948,58,7,19,5,'Neljäntenä päivänä hän varhain aamulla nousi lähteäkseen; mutta naisen isä sanoi vävyllensä: "Vahvista itseäsi leipäpalalla; sitten saatte lähteä".'),
(1675949,58,7,19,6,'Niin he istuivat, söivät ja joivat molemmat yhdessä. Sitten naisen isä sanoi miehelle: "Suostu jäämään yöksi, ja olkoon sydämesi iloinen".'),
(1675950,58,7,19,7,'Mutta mies nousi lähteäksensä; silloin hänen appensa pyysi häntä pyytämällä, ja hän jäi sinne vielä yöksi.'),
(1675951,58,7,19,8,'Viidentenä päivänä hän varhain aamulla nousi lähteäksensä, mutta naisen isä sanoi hänelle: "Vahvista itseäsi, ja viipykää iltapäivään asti". Niin he söivät toistensa kanssa.'),
(1675952,58,7,19,9,'Ja mies nousi lähteäkseen sivuvaimonsa ja palvelijansa kanssa, mutta hänen appensa, naisen isä, sanoi hänelle: "Katso, päivä kallistuu iltaan, jääkää yöksi; päivä on menemässä mailleen, jää tänne yöksi, ja olkoon sydämesi iloinen. Nouskaa huomenna varhain matkallenne, ja lähde sitten majallesi."'),
(1675953,58,7,19,10,'Mutta mies ei tahtonut jäädä yöksi, vaan nousi ja lähti ja tuli Jebuksen, se on Jerusalemin, kohdalle, mukanaan satuloitu aasipari ja sivuvaimonsa.'),
(1675954,58,7,19,11,'Kun he olivat Jebuksen luona ja päivä oli kohta laskemassa, sanoi palvelija isännälleen: "Tule, poiketkaamme tuohon jebusilaisten kaupunkiin ja yöpykäämme sinne".'),
(1675955,58,7,19,12,'Mutta hänen isäntänsä vastasi hänelle: "Emme poikkea vieraitten kaupunkiin, jotka eivät ole israelilaisia, vaan menemme edelleen Gibeaan asti".'),
(1675956,58,7,19,13,'Ja hän sanoi palvelijallensa: "Tule, pyrkikäämme toiseen paikkaan, yöpykäämme Gibeaan tai Raamaan".'),
(1675957,58,7,19,14,'Niin he jatkoivat matkaansa, ja aurinko laski heiltä lähellä Gibeaa, joka on Benjaminissa.'),
(1675958,58,7,19,15,'Ja he poikkesivat Gibeaan yöpyäkseen sinne. Hän tuli sinne ja istuutui kaupungin torille, mutta ei kukaan ottanut heitä yöksi huoneeseen.'),
(1675959,58,7,19,16,'Ja katso, illalla tuli vanha mies työstään kedolta; hän oli Efraimin vuoristosta ja asui muukalaisena Gibeassa. Mutta sen paikkakunnan miehet olivat benjaminilaisia.'),
(1675960,58,7,19,17,'Ja kun hän nosti silmänsä, näki hän matkamiehen kaupungin torilla. Silloin vanha mies sanoi: "Minne olet matkalla ja mistä tulet?"'),
(1675961,58,7,19,18,'Hän vastasi hänelle sanoen: "Me olemme matkalla Juudan Beetlehemistä Efraimin vuoriston perukoille; sieltä minä olen kotoisin ja olen käynyt Juudan Beetlehemissä asti. Olen matkalla Herran huoneeseen, mutta ei kukaan ota minua huoneeseen.'),
(1675962,58,7,19,19,'Meillä on sekä olkia että muuta rehua aaseillemme, niin myös leipää ja viiniä minulle itselleni ja palvelijattarellesi ja nuorelle miehelle, joka on palvelijasi kanssa, niin ettei meiltä mitään puutu."'),
(1675963,58,7,19,20,'Vanha mies sanoi: "Rauha sinulle! Minun asiani on, jos sinulta jotakin puuttuisi. Älä vain jää yöksi tähän torille."'),
(1675964,58,7,19,21,'Ja hän vei hänet taloonsa ja teki aaseille appeen. Ja he pesivät jalkansa ja söivät ja joivat.'),
(1675965,58,7,19,22,'Ja kun he olivat ilahduttamassa sydäntänsä, niin katso, kaupungin miehet, kelvottomat miehet, piirittivät talon, kolkuttivat ovelle ja sanoivat vanhalle miehelle, talon isännälle, näin: "Tuo tänne se mies, joka tuli sinun taloosi, ryhtyäksemme häneen".'),
(1675966,58,7,19,23,'Mutta mies, talon isäntä, meni ulos heidän luokseen ja sanoi heille: "Älkää, veljeni, älkää tehkö niin pahoin! Kun kerran tämä mies on tullut minun talooni, älkää tehkö sellaista häpeällistä tekoa.'),
(1675967,58,7,19,24,'Katso, täällä on minun tyttäreni, joka on neitsyt, ja tämän miehen sivuvaimo. Minä tuon heidät tänne; tehkää heille väkivaltaa, tehkää heille, mitä tahdotte, mutta tälle miehelle älkää tehkö sellaista häpeällistä tekoa."'),
(1675968,58,7,19,25,'Mutta miehet eivät tahtoneet häntä kuulla. Silloin mies tarttui sivuvaimoonsa ja vei hänet heidän luoksensa kadulle, ja he yhtyivät häneen ja pitelivät häntä pahoin koko yön aina aamuun asti, ja vasta aamun sarastaessa he hänet päästivät.'),
(1675969,58,7,19,26,'Ja päivän koittaessa vaimo tuli ja kaatui sen miehen talon oven eteen, jonka talossa hänen isäntänsä oli, ja makasi siinä, kunnes päivä valkeni.'),
(1675970,58,7,19,27,'Kun hänen isäntänsä aamulla nousi ja avasi talon oven ja tuli ulos lähteäksensä matkalle, niin katso, hänen sivuvaimonsa makasi talon oven edessä, kädet kynnyksellä.'),
(1675971,58,7,19,28,'Hän sanoi hänelle: "Nouse ja lähtekäämme!" Mutta vastausta ei tullut. Silloin mies nosti hänet aasin selkään, nousi ja lähti kotiinsa.'),
(1675972,58,7,19,29,'Mutta kotiin tultuaan hän otti veitsen, tarttui sivuvaimoonsa ja paloitteli hänet luineen kaikkineen kahdeksitoista kappaleeksi ja lähetti ne kaikkialle Israelin alueelle.'),
(1675973,58,7,19,30,'Ja jokainen, joka sen näki, sanoi: "Mitään sellaista ei ole tapahtunut eikä nähty siitä päivästä lähtien, jona israelilaiset tulivat Egyptin maasta, aina tähän päivään saakka. Harkitkaa tätä, neuvotelkaa ja puhukaa."'),
(1675974,58,7,20,1,'Ja kaikki israelilaiset lähtivät liikkeelle, ja kansa kokoontui yhtenä miehenä Daanista aina Beersebaan saakka, niin myös Gileadin maasta, Herran eteen Mispaan.'),
(1675975,58,7,20,2,'Ja koko kansan päämiehet ja kaikki Israelin sukukunnat astuivat esiin Jumalan kansan seurakunnassa: neljäsataa tuhatta miekalla varustettua jalkamiestä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1675976,58,7,20,3,'Ja benjaminilaiset saivat kuulla, että israelilaiset olivat menneet Mispaan. Ja israelilaiset sanoivat: "Kertokaa, kuinka tämä pahateko tapahtui".'),
(1675977,58,7,20,4,'Niin se leeviläinen mies, murhatun vaimon mies, vastasi ja sanoi: "Minä ja minun sivuvaimoni olimme tulleet Benjaminin Gibeaan yöpyäksemme sinne.'),
(1675978,58,7,20,5,'Silloin Gibean miehet nousivat minua vastaan ja piirittivät yöllä talon, jossa minä olin. Minut he aikoivat tappaa, minun sivuvaimolleni he tekivät väkivaltaa, niin että hän kuoli.'),
(1675979,58,7,20,6,'Sitten minä tartuin sivuvaimooni ja paloittelin hänet ja lähetin kappaleet kaikkialle Israelin perintömaahan, koska he olivat tehneet ilkityön ja häpeällisen teon Israelissa.'),
(1675980,58,7,20,7,'Katso, nyt olette kaikki tässä, te israelilaiset. Keskustelkaa ja neuvotelkaa tässä paikassa."'),
(1675981,58,7,20,8,'Silloin nousi kaikki kansa yhtenä miehenä ja sanoi: "Älköön meistä kukaan menkö majallensa, älköön kukaan poistuko kotiinsa.'),
(1675982,58,7,20,9,'Tämän me nyt teemme Gibealle: me menemme sitä vastaan arvan mukaan.'),
(1675983,58,7,20,10,'Ja me otamme kymmenen miestä sadasta, Israelin kaikista sukukunnista, ja sata tuhannesta ja tuhat kymmenestätuhannesta, hankkimaan muonaa kansalle, kun se menee kostamaan Benjaminin Gibealle sen häpeällisen teon, minkä se on tehnyt Israelissa."'),
(1675984,58,7,20,11,'Niin kokoontuivat kaikki Israelin miehet kaupunkia vastaan, kuin yhdeksi mieheksi yhtyneinä.'),
(1675985,58,7,20,12,'Ja Israelin sukukunnat lähettivät miehiä kaikkiin Benjaminin sukuihin sanomaan: "Mikä pahateko onkaan teidän keskuudessanne tehty!'),
(1675986,58,7,20,13,'Luovuttakaa nyt ne Gibean kelvottomat miehet, surmataksemme heidät ja poistaaksemme pahan Israelista." Mutta benjaminilaiset eivät tahtoneet kuulla veljiänsä, israelilaisia.'),
(1675987,58,7,20,14,'Niin benjaminilaiset kokoontuivat kaupungeistaan Gibeaan lähteäksensä sotaan israelilaisia vastaan.'),
(1675988,58,7,20,15,'Sinä päivänä pidettiin benjaminilaisten katselmus, ja heitä oli muista kaupungeista kaksikymmentäkuusi tuhatta miekkamiestä, paitsi Gibean asukkaita, joita katselmuksessa oli seitsemänsataa valiomiestä.'),
(1675989,58,7,20,16,'Kaikesta tästä väestä oli seitsemänsataa valiomiestä vasenkätistä; jokainen näistä osasi lingota kiven hiuskarvalleen, hairahtumatta.'),
(1675990,58,7,20,17,'Myös pidettiin Israelin miesten katselmus, ja heitä oli, paitsi benjaminilaisia, neljäsataa tuhatta miekkamiestä, kaikki sotilaita.'),
(1675991,58,7,20,18,'Ja he nousivat ja lähtivät Beeteliin ja kysyivät Jumalalta. Israelilaiset sanoivat: "Kenen meistä on ensiksi lähdettävä taistelemaan benjaminilaisia vastaan?" Herra vastasi: "Juuda ensiksi".'),
(1675992,58,7,20,19,'Ja israelilaiset lähtivät liikkeelle seuraavana aamuna ja asettuivat leiriin Gibean edustalle.'),
(1675993,58,7,20,20,'Ja Israelin miehet lähtivät taistelemaan Benjaminia vastaan, ja Israelin miehet asettuivat sotarintaan heitä vastaan Gibean edustalle.'),
(1675994,58,7,20,21,'Mutta benjaminilaiset ryntäsivät ulos Gibeasta ja kaatoivat sinä päivänä Israelista kaksikymmentäkaksi tuhatta miestä.'),
(1675995,58,7,20,22,'Mutta kansa, Israelin miehet, rohkaisivat mielensä ja asettuivat jälleen sotarintaan samalle paikalle, mihin olivat asettuneet ensimmäisenä päivänä.'),
(1675996,58,7,20,23,'Sillä kun israelilaiset menivät ja itkivät Herran edessä iltaan asti ja kysyivät Herralta sanoen: "Onko minun vielä ryhdyttävä taisteluun veljiäni, benjaminilaisia, vastaan?" niin Herra vastasi: "Menkää heitä vastaan".'),
(1675997,58,7,20,24,'Ja toisena päivänä israelilaiset lähenivät benjaminilaisia;'),
(1675998,58,7,20,25,'niin benjaminilaiset toisena päivänä ryntäsivät Gibeasta heitä vastaan ja kaatoivat israelilaisia vielä kahdeksantoista tuhatta miestä, kaikki miekkamiehiä.'),
(1675999,58,7,20,26,'Silloin kaikki israelilaiset, koko kansa, lähtivät ja tulivat Beeteliin ja itkivät ja istuivat siellä Herran edessä ja paastosivat sen päivän aina iltaan asti; ja he uhrasivat polttouhreja ja yhteysuhreja Herran edessä.'),
(1676000,58,7,20,27,'Ja israelilaiset kysyivät Herralta - sillä Jumalan liitonarkki oli siihen aikaan siellä,'),
(1676001,58,7,20,28,'ja Piinehas, Aaronin pojan Eleasarin poika, seisoi siihen aikaan sen edessä - ja sanoivat: "Onko minun vielä lähdettävä taisteluun veljiäni, benjaminilaisia, vastaan, vai onko minun siitä luovuttava?" Herra vastasi: "Lähtekää; sillä huomenna minä annan heidät sinun käsiisi".'),
(1676002,58,7,20,29,'Silloin Israel asetti väijytyksiä Gibean ympärille.'),
(1676003,58,7,20,30,'Ja israelilaiset menivät kolmantena päivänä benjaminilaisia vastaan ja asettuivat sotarintaan Gibeaa vastaan niinkuin edellisilläkin kerroilla.'),
(1676004,58,7,20,31,'Ja benjaminilaiset ryntäsivät ulos kansaa vastaan, mutta tulivat eristetyiksi kaupungista; ja niinkuin edellisilläkin kerroilla he aluksi saivat lyödyksi kansaa kuoliaaksi niillä valtateillä, joista toinen vie Beeteliin, toinen kedon yli Gibeaan, noin kolmekymmentä Israelin miestä.'),
(1676005,58,7,20,32,'Ja benjaminilaiset sanoivat: "Me voitimme heidät nyt niinkuin ennenkin"; mutta israelilaiset sanoivat: "Paetkaamme ja eristäkäämme heidät kaupungista valtateille".'),
(1676006,58,7,20,33,'Niin kaikki Israelin miehet nousivat, kukin paikaltaan, ja asettuivat sotarintaan Baal-Taamariin; ja väijyksissä oleva Israelin joukko syöksyi esiin paikaltaan Geban aukealta.'),
(1676007,58,7,20,34,'Niin tuli kymmenentuhatta valiomiestä koko Israelista Gibean edustalle, ja syntyi ankara taistelu; eivätkä he huomanneet, että onnettomuus oli kohtaamassa heitä.'),
(1676008,58,7,20,35,'Ja Herra antoi Israelin voittaa Benjaminin, ja israelilaiset kaatoivat sinä päivänä Benjaminista kaksikymmentäviisi tuhatta ja sata miestä, kaikki miekkamiehiä.'),
(1676009,58,7,20,36,'Nyt benjaminilaiset näkivät olevansa voitetut. Mutta Israelin miehet väistyivät benjaminilaisten tieltä, sillä he luottivat väijytykseen, jonka olivat asettaneet Gibeaa vastaan.'),
(1676010,58,7,20,37,'Silloin väijyksissä ollut joukko riensi ja karkasi Gibeaan; väijyksissä ollut joukko meni ja surmasi kaikki kaupungin asukkaat miekan terällä.'),
(1676011,58,7,20,38,'Ja Israelin miehet olivat sopineet väijyksissä olevan joukon kanssa, että se panisi sakean savupilven nousemaan kaupungista.'),
(1676012,58,7,20,39,'Kun siis Israelin miehet olivat kääntyneet pakosalle taistelussa, ja kun Benjaminin miehet aluksi olivat lyöneet kuoliaaksi Israelin miehiä noin kolmekymmentä miestä ja sanoneet: "Varmasti me voitamme heidät niinkuin ensimmäisessäkin taistelussa",'),
(1676013,58,7,20,40,'niin alkoi pilvi, savupatsas, nousta kaupungista. Ja kun benjaminilaiset kääntyivät taaksepäin, niin katso, koko kaupunki nousi savuna taivasta kohti.'),
(1676014,58,7,20,41,'Israelin miehet kääntyivät takaisin, mutta Benjaminin miehet kauhistuivat, sillä he näkivät, että onnettomuus oli kohdannut heitä.'),
(1676015,58,7,20,42,'Ja he kääntyivät pakoon Israelin miesten edestä erämaan tielle, mutta sota seurasi heitä kintereillä; ja sikäläisten kaupunkien asukkaat kaatoivat heitä heidän keskeltänsä.'),
(1676016,58,7,20,43,'He saartoivat Benjaminin, ajoivat heitä takaa ja tallasivat heitä maahan levähdyspaikassa ja aina Gibean kohdalle asti, auringonnousuun päin.'),
(1676017,58,7,20,44,'Niin kaatui Benjaminista kahdeksantoistatuhatta miestä, kaikki sotakuntoisia miehiä.'),
(1676018,58,7,20,45,'He kääntyivät ja pakenivat erämaahan päin, Rimmonin kalliolle; mutta israelilaiset tekivät heistä valtateillä vielä jälkikorjuun, surmaten viisituhatta miestä, ja seurasivat heitä kintereillä aina Gideomiin asti ja surmasivat heitä kaksituhatta miestä.'),
(1676019,58,7,20,46,'Kaikkiaan oli niitä, jotka sinä päivänä kaatuivat Benjaminista, kaksikymmentäviisi tuhatta miekkamiestä, kaikki sotakuntoisia miehiä.'),
(1676020,58,7,20,47,'Ja heitä kääntyi pakoon erämaahan päin, Rimmonin kalliolle, kuusisataa miestä. Ja he jäivät Rimmonin kalliolle neljäksi kuukaudeksi.'),
(1676021,58,7,20,48,'Mutta Israelin miehet palasivat takaisin benjaminilaisten luo ja surmasivat heidät miekan terällä, kaupungin sekä vahingoittumatta jääneet ihmiset että eläimet, kaiken, minkä tapasivat; myöskin pistivät he tuleen kaikki kaupungit, joihin tulivat.'),
(1676022,58,7,21,1,'Israelin miehet olivat vannoneet Mispassa ja sanoneet: "Ei kukaan meistä anna tytärtään benjaminilaiselle vaimoksi".'),
(1676023,58,7,21,2,'Ja kansa tuli Beeteliin, ja he istuivat siellä aina iltaan asti Jumalan edessä, korottivat äänensä ja itkivät katkerasti'),
(1676024,58,7,21,3,'ja sanoivat: "Miksi, oi Herra, Israelin Jumala, on Israelissa käynyt niin, että Israelista nyt puuttuu yksi sukukunta?"'),
(1676025,58,7,21,4,'Varhain seuraavana päivänä kansa nousi ja rakensi sinne alttarin ja uhrasi polttouhreja ja yhteysuhreja.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676026,58,7,21,5,'Ja israelilaiset sanoivat: "Onko yhdessäkään Israelin sukukunnassa ketään, joka ei ole tullut seurakunnan kanssa tänne Herran eteen?" Sillä siitä, joka ei tulisi Herran luo Mispaan, oli vannottu ankara vala: "Hän on kuolemalla rangaistava".'),
(1676027,58,7,21,6,'Ja israelilaisten tuli sääli veljeänsä Benjaminia, ja he sanoivat: "Tänä päivänä on yksi sukukunta hakattu pois Israelista.'),
(1676028,58,7,21,7,'Mitä meidän on tehtävä, että jäljelle jääneet saavat vaimoja? Sillä itse me olemme vannoneet Herran kautta, ettemme anna heille tyttäriämme vaimoiksi."'),
(1676029,58,7,21,8,'Ja he kysyivät: "Onko Israelin sukukunnissa ainoatakaan, joka ei ole tullut Herran eteen Mispaan?" Ja katso, Gileadin Jaabeksesta ei ollut ketään tullut leiriin, seurakuntakokoukseen.'),
(1676030,58,7,21,9,'Sillä kun kansasta pidettiin katselmus, niin katso, siellä ei ollut ketään Gileadin Jaabeksen asukkaista.'),
(1676031,58,7,21,10,'Niin kansa lähetti sinne kaksitoistatuhatta sotakuntoista miestä ja käski heitä sanoen: "Menkää ja surmatkaa miekan terällä Gileadin Jaabeksen asukkaat vaimoineen ja lapsineen.'),
(1676032,58,7,21,11,'Tehkää näin: kaikki miehenpuolet ja kaikki naiset, jotka ovat yhtyneet mieheen, vihkikää tuhon omiksi."'),
(1676033,58,7,21,12,'Ja Gileadin Jaabeksen asukkaista he löysivät neljäsataa nuorta naista, jotka olivat neitsyitä eivätkä olleet yhtyneet mieheen; ja he veivät nämä leiriin Siiloon, joka on Kanaanin maassa.'),
(1676034,58,7,21,13,'Sitten koko kansa lähetti sanansaattajia puhumaan benjaminilaisten kanssa, jotka olivat Rimmonin kalliolla, ja tarjosi heille rauhaa.'),
(1676035,58,7,21,14,'Silloin benjaminilaiset palasivat takaisin, ja heille annettiin ne naiset, jotka oli jätetty henkiin Gileadin Jaabeksen naisista. Mutta ne eivät riittäneet heille.'),
(1676036,58,7,21,15,'Niin kansan tuli sääli Benjaminia, koska Herra oli tehnyt aukon Israelin sukukuntiin.'),
(1676037,58,7,21,16,'Ja kansan vanhimmat sanoivat: "Mitä meidän on tehtävä, että jäljelle jääneet saisivat vaimoja? Sillä ovathan naiset hävitetyt Benjaminista."'),
(1676038,58,7,21,17,'Ja he sanoivat: "Pelastuneiden perintöomaisuus on jäävä Benjaminille, ettei yksikään sukukunta häviäisi Israelista.'),
(1676039,58,7,21,18,'Mutta itse me emme voi antaa heille tyttäriämme vaimoiksi, sillä israelilaiset ovat vannoneet ja sanoneet: kirottu olkoon se, joka antaa vaimon benjaminilaiselle."'),
(1676040,58,7,21,19,'Niin he sanoivat: "Katso, joka vuosi vietetään Herran juhla Siilossa, joka on pohjoiseen päin Beetelistä, auringonnousuun päin siitä valtatiestä, joka vie Beetelistä Sikemiin, ja etelään päin Lebonasta".'),
(1676041,58,7,21,20,'Ja he käskivät benjaminilaisia sanoen: "Menkää ja asettukaa väijyksiin viinitarhoihin.'),
(1676042,58,7,21,21,'Kun näette Siilon tyttärien tulevan ulos karkeloimaan, niin rynnätkää viinitarhoista ja ryöstäkää jokainen itsellenne vaimo Siilon tyttäristä ja lähtekää Benjaminin maahan.'),
(1676043,58,7,21,22,'Ja kun heidän isänsä tai veljensä tulevat valittamaan meille, niin me sanomme heille: ''Lahjoittakaa heidät meille, sillä ei kukaan meistä ole ottanut sodassa vaimoa. Ettehän te ole itse antaneet niitä heille; muuten olisitte joutuneet vikapäiksi.''"'),
(1676044,58,7,21,23,'Benjaminilaiset tekivät niin ja ottivat lukumääränsä mukaan itselleen vaimoja karkeloivien joukosta, ryöstäen heidät. Sitten he palasivat perintöosaansa ja rakensivat uudestaan kaupungit ja asettuivat niihin.'),
(1676045,58,7,21,24,'Silloin israelilaisetkin vaelsivat sieltä, kukin sukukuntaansa ja sukuunsa, ja menivät sieltä kukin perintöosallensa.'),
(1676046,58,8,1,1,'Siihen aikaan kun tuomarit hallitsivat, tuli nälänhätä maahan. Silloin muuan Juudan Beetlehemin mies lähti sieltä ja asettui vaimonsa ja kahden poikansa kanssa muukalaisena asumaan Mooabin maahan.'),
(1676047,58,8,1,2,'Miehen nimi oli Elimelek, hänen vaimonsa nimi oli Noomi ja hänen kahden poikansa nimet Mahlon ja Kiljon; he olivat efratilaisia Juudan Beetlehemistä. Niin he tulivat Mooabin maahan ja oleskelivat siellä.'),
(1676048,58,8,1,3,'Ja Elimelek, Noomin mies, kuoli, ja Noomi jäi jälkeen kahden poikansa kanssa.'),
(1676049,58,8,1,4,'Nämä ottivat itselleen mooabilaiset vaimot; toisen nimi oli Orpa ja toisen nimi Ruut. Ja he asuivat siellä noin kymmenen vuotta.'),
(1676050,58,8,1,5,'Ja myös nuo molemmat, Mahlon ja Kiljon, kuolivat, niin että vaimo jäi yksin jälkeen kahdesta pojastaan ja miehestään.'),
(1676051,58,8,1,6,'Silloin hän nousi miniöineen palataksensa takaisin Mooabin maasta, sillä hän oli kuullut Mooabin maassa, että Herra oli pitänyt kansastansa huolen ja antanut sille leipää.'),
(1676052,58,8,1,7,'Niin hän lähti yhdessä molempien miniäinsä kanssa siitä paikasta, jossa oli oleskellut. Ja heidän tietä käydessään matkalla Juudan maahan'),
(1676053,58,8,1,8,'sanoi Noomi molemmille miniöillensä: "Menkää, palatkaa kumpikin äitinne kotiin. Herra tehköön teille laupeuden, niinkuin te olette vainajille ja minulle tehneet.'),
(1676054,58,8,1,9,'Herra suokoon, että saisitte turvan kumpikin miehenne kodissa." Ja hän suuteli heitä. Mutta he korottivat äänensä ja itkivät'),
(1676055,58,8,1,10,'ja sanoivat hänelle: "Me seuraamme sinua sinun kansasi luo".'),
(1676056,58,8,1,11,'Mutta Noomi vastasi: "Kääntykää takaisin, tyttäreni; miksi te lähtisitte minun kanssani? Voinko minä enää saada poikia miehiksi teille?'),
(1676057,58,8,1,12,'Kääntykää takaisin, tyttäreni, menkää, sillä minä olen liian vanha joutuakseni miehelään. Vaikka ajattelisinkin: ''Minulla on vielä toivoa'', ja vaikka vielä tänä yönä joutuisin miehelään ja synnyttäisin poikia,'),
(1676058,58,8,1,13,'ette kai te kuitenkaan odottaisi, kunnes he kasvaisivat suuriksi, ette kai te kuitenkaan sulkeutuisi huoneeseen ja olisi miehelään menemättä. Ei, tyttäreni; minä olen hyvin murheissani teidän tähtenne, sillä Herran käsi on sattunut minuun."'),
(1676059,58,8,1,14,'Niin he korottivat vielä äänensä ja itkivät. Silloin Orpa suuteli anoppiaan jäähyväisiksi, mutta Ruut riippui kiinni hänessä.'),
(1676060,58,8,1,15,'Ja Noomi sanoi: "Katso, kälysi on kääntynyt takaisin oman kansansa ja jumalansa luo, käänny sinäkin kälysi kanssa".'),
(1676061,58,8,1,16,'Mutta Ruut vastasi: "Älä vaadi minua jättämään sinua ja kääntymään takaisin, pois sinun tyköäsi. Sillä mihin sinä menet, sinne minäkin menen, ja mihin sinä jäät, sinne minäkin jään; sinun kansasi on minun kansani, sinun Jumalasi on minun Jumalani.'),
(1676062,58,8,1,17,'Missä sinä kuolet, siellä minäkin tahdon kuolla ja sinne tulla haudatuksi. Herra rangaiskoon minua nyt ja vasta, jos muu kuin kuolema erottaa meidät."'),
(1676063,58,8,1,18,'Kun Noomi näki, että hän oli lujasti päättänyt seurata häntä, ei hän enää puhunut siitä hänen kanssansa.'),
(1676064,58,8,1,19,'Niin he kulkivat molemmat yhdessä, kunnes tulivat Beetlehemiin. Ja kun he tulivat Beetlehemiin, joutui koko kaupunki liikkeelle heidän tähtensä, ja vaimot sanoivat: "Onko tämä Noomi?"'),
(1676065,58,8,1,20,'Mutta hän vastasi heille: "Älkää kutsuko minua Noomiksi, kutsukaa minua Maaraksi, sillä Kaikkivaltias on antanut minulle paljon katkerata murhetta.'),
(1676066,58,8,1,21,'Rikkaana minä lähdin, mutta tyhjänä Herra antaa minun palata. Miksi siis kutsutte minua Noomiksi, kun Herra on minua vastaan todistanut ja Kaikkivaltias on tuottanut minulle onnettomuutta?"'),
(1676067,58,8,1,22,'Niin Noomi palasi miniänsä, mooabilaisen Ruutin, kanssa, joka tuli Mooabin maasta; ja he saapuivat Beetlehemiin ohranleikkuun alussa.'),
(1676068,58,8,2,1,'Noomilla oli miehensä puolelta sukulainen, hyvin varakas mies, Elimelekin sukua, nimeltä Booas.'),
(1676069,58,8,2,2,'Ja mooabilainen Ruut sanoi Noomille: "Anna minun mennä pellolle poimimaan tähkiä jonkun jäljessä, jonka silmien edessä saan armon". Noomi vastasi hänelle: "Mene, tyttäreni!"'),
(1676070,58,8,2,3,'Niin hän lähti ja meni poimimaan eräälle pellolle leikkuuväen jäljessä; ja hänelle sattui niin, että se peltopalsta oli Booaan, joka oli Elimelekin sukua.'),
(1676071,58,8,2,4,'Ja katso, Booas tuli Beetlehemistä, ja hän sanoi leikkuuväelle: "Herra olkoon teidän kanssanne!" He vastasivat hänelle: "Herra siunatkoon sinua!"'),
(1676072,58,8,2,5,'Sitten Booas sanoi palvelijallensa, joka oli leikkuuväen päällysmiehenä: "Kenen tuo nuori nainen on?"'),
(1676073,58,8,2,6,'Palvelija, joka oli leikkuuväen päällysmiehenä, vastasi ja sanoi: "Se on se nuori mooabitar, joka tuli Noomin mukana Mooabin maasta.'),
(1676074,58,8,2,7,'Hän sanoi: ''Salli minun poimia ja koota tähkiä lyhteiden väliltä leikkuuväen jäljessä''. Niin hän tuli ja on ahertanut aamusta varhain tähän saakka; vasta äsken hän hiukan levähti tuolla majassa."'),
(1676075,58,8,2,8,'Niin Booas sanoi Ruutille: "Kuules, tyttäreni! Älä mene muiden pelloille poimimaan äläkä lähde pois täältä, vaan pysyttele täällä minun palvelijattarieni mukana.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676076,58,8,2,9,'Pidä silmällä, millä pellolla leikataan, ja kulje heidän jäljessään. Minä olen kieltänyt palvelijoitani koskemasta sinuun. Jos sinun tulee jano, niin mene astioille ja juo vettä, jota palvelijat ammentavat."'),
(1676077,58,8,2,10,'Silloin Ruut heittäytyi kasvoilleen, kumartui maahan ja sanoi hänelle: "Miten olen saanut armon sinun silmiesi edessä, niin että huolehdit minusta, vaikka olen vieras?"'),
(1676078,58,8,2,11,'Booas vastasi ja sanoi hänelle: "Minulle on kerrottu kaikki, mitä sinä olet tehnyt anopillesi miehesi kuoltua, kuinka jätit isäsi ja äitisi ja synnyinmaasi ja lähdit kansan luo, jota et ennen tuntenut.'),
(1676079,58,8,2,12,'Herra palkitkoon sinulle tekosi; tulkoon sinulle täysi palkka Herralta, Israelin Jumalalta, jonka siipien alta olet tullut turvaa etsimään."'),
(1676080,58,8,2,13,'Ruut sanoi: "Minä olen saanut armon sinun silmiesi edessä, herrani, sillä sinä olet lohduttanut minua ja puhutellut palvelijatartasi ystävällisesti, vaikka en ole yhdenkään sinun palvelijattaresi vertainen".'),
(1676081,58,8,2,14,'Ruoka-ajan tultua Booas sanoi hänelle: "Käy tänne ruualle ja kasta palasesi hapanviiniin". Niin Ruut istui leikkuuväen viereen; ja Booas pani hänen eteensä paahdettuja jyviä, niin että hän söi tarpeeksensa ja jäi tähteeksikin.'),
(1676082,58,8,2,15,'Kun hän sitten nousi poimimaan, käski Booas palvelijoitaan sanoen: "Hän saa poimia myöskin lyhteiden väliltä; ja te ette saa loukata häntä.'),
(1676083,58,8,2,16,'Voittepa vetää sitomistakin joitakin tähkiä ja jättää ne hänen poimittavikseen; ja te ette saa nuhdella häntä."'),
(1676084,58,8,2,17,'Niin Ruut poimi pellolla iltaan asti; sitten hän pui, mitä oli saanut poimituksi, ja siitä tuli noin eefa-mitan verta ohria.'),
(1676085,58,8,2,18,'Ja hän otti ne ja tuli kaupunkiin ja näytti anopillensa, mitä oli poiminut. Sen jälkeen Ruut otti esille tähteet ruuasta, josta oli syönyt tarpeekseen, ja antoi ne hänelle.'),
(1676086,58,8,2,19,'Silloin hänen anoppinsa sanoi hänelle: "Missä olet tänään poiminut ja missä olet tehnyt työtä? Siunattu olkoon se, joka on sinusta huolehtinut." Sitten hän ilmoitti anopillensa, kenen luona hän oli ollut työssä, sanoen: "Se mies, jonka luona olin tänä päivänä työssä, on nimeltään Booas".'),
(1676087,58,8,2,20,'Noomi sanoi miniällensä: "Siunatkoon häntä Herra, joka on osoittanut laupeutta eläviä ja kuolleita kohtaan". Ja Noomi sanoi vielä: "Hän on sukulaisemme ja meidän sukulunastajiamme".'),
(1676088,58,8,2,21,'Silloin mooabilainen Ruut sanoi: "Vielä hän sanoi minulle: ''Pysyttele vain minun palvelijaini mukana siihen asti, että he saavat kaiken minun leikkuuni lopetetuksi''".'),
(1676089,58,8,2,22,'Niin Noomi sanoi miniällensä Ruutille: "Hyvä on, tyttäreni, lähde hänen palvelijattariensa mukana, niin et joudu sysittäväksi muiden pelloilla".'),
(1676090,58,8,2,23,'Ja hän pysytteli Booaan palvelijattarien seurassa poimien tähkiä, kunnes ohran- ja nisunleikkuu oli lopussa. Sitten hän jäi olemaan anoppinsa luo.'),
(1676091,58,8,3,1,'Niin Noomi, hänen anoppinsa, sanoi hänelle: "Tyttäreni, minäpä hankin sinulle turvapaikan, että sinun kävisi hyvin.'),
(1676092,58,8,3,2,'Onhan Booas, jonka palvelijattarien kanssa olit, sukulaisemme; katso, hän viskaa tänä yönä ohria puimatantereella.'),
(1676093,58,8,3,3,'Niin peseydy nyt ja voitele itsesi ja pukeudu ja mene puimatantereelle; mutta älä näyttäydy hänelle, ennenkuin hän on syönyt ja juonut.'),
(1676094,58,8,3,4,'Kun hän panee maata, niin katso, mihin paikkaan hän panee maata, ja mene ja nosta peitettä hänen jalkojensa kohdalta ja pane siihen maata; hän sanoo sitten sinulle, mitä sinun on tehtävä."'),
(1676095,58,8,3,5,'Ruut vastasi hänelle: "Minä teen kaiken, mitä sanot".'),
(1676096,58,8,3,6,'Niin hän meni alas puimatantereelle ja teki aivan niin, kuin hänen anoppinsa oli häntä käskenyt.'),
(1676097,58,8,3,7,'Ja kun Booas oli syönyt ja juonut, tuli hänen sydämensä iloiseksi, ja hän meni maata viljakasan ääreen. Ja Ruut tuli hiljaa ja nosti peitettä hänen jalkojensa kohdalta ja pani siihen maata.'),
(1676098,58,8,3,8,'Puoliyön aikana mies säikähti ja kumartui eteenpäin; ja katso, nainen makasi hänen jalkapohjissaan.'),
(1676099,58,8,3,9,'Ja hän kysyi: "Kuka sinä olet?" Hän vastasi: "Minä olen Ruut, palvelijattaresi. Levitä liepeesi palvelijattaresi yli, sillä sinä olet minun sukulunastajani."'),
(1676100,58,8,3,10,'Hän sanoi: "Herra siunatkoon sinua, tyttäreni! Sinä olet osoittanut sukurakkauttasi nyt viimeksi vielä kauniimmin kuin aikaisemmin, kun et ole kulkenut nuorten miesten jäljessä, et köyhien etkä rikkaitten.'),
(1676101,58,8,3,11,'Ja nyt, tyttäreni, älä pelkää; kaiken, mitä sanot, teen minä sinulle. Sillä minun kansani portissa jokainen tietää sinut kunnialliseksi naiseksi.'),
(1676102,58,8,3,12,'Totta on, että minä olen sinun sukulunastajasi, mutta on vielä toinen sukulunastaja, joka on läheisempi kuin minä.'),
(1676103,58,8,3,13,'Jää tähän yöksi; jos hän huomenna lunastaa sinut, niin hyvä; lunastakoon. Mutta jollei hän halua lunastaa sinua, niin minä lunastan sinut, niin totta kuin Herra elää. Lepää siinä aamuun asti."'),
(1676104,58,8,3,14,'Niin hän lepäsi hänen jalkapohjissaan aamuun asti, mutta nousi, ennenkuin kukaan vielä voi tuntea toisensa. Ja Booas ajatteli: "Älköön tulko tunnetuksi, että tuo nainen on tullut tänne puimatantereelle".'),
(1676105,58,8,3,15,'Ja hän sanoi: "Anna tänne vaippa, joka on ylläsi, ja pidä sitä". Ja Ruut piti sitä. Silloin hän mittasi siihen kuusi mittaa ohria ja pani ne hänen selkäänsä. Ja hän meni kaupunkiin.'),
(1676106,58,8,3,16,'Ja Ruut tuli anoppinsa luo, joka sanoi: "Kuinka kävi, tyttäreni?" Niin hän kertoi hänelle kaikki, mitä mies oli hänelle tehnyt;'),
(1676107,58,8,3,17,'ja hän sanoi: "Nämä kuusi mittaa ohria hän antoi minulle, sanoen: ''Et saa mennä tyhjin käsin anoppisi luo''".'),
(1676108,58,8,3,18,'Silloin Noomi sanoi: "Pysy alallasi, tyttäreni, kunnes saat tietää, kuinka asia päättyy; sillä mies ei suo itselleen lepoa, ennenkuin hän tänä päivänä saattaa asian päätökseen".'),
(1676109,58,8,4,1,'Mutta Booas meni kaupungin porttiin ja istuutui sinne. Ja katso, sukulunastaja, josta Booas oli puhunut, kulki siitä ohitse; ja Booas sanoi: "Sinä siellä, poikkea tänne istumaan". Hän poikkesi ja istui siihen.'),
(1676110,58,8,4,2,'Senjälkeen Booas otti kaupungin vanhimpia kymmenen miestä ja sanoi: "Istukaa tähän". Ja he istuivat.'),
(1676111,58,8,4,3,'Sitten Booas sanoi sukulunastajalle: "Sen peltopalstan, joka oli veljellämme Elimelekillä, on Noomi, joka on palannut Mooabin maasta, myynyt.'),
(1676112,58,8,4,4,'Sentähden ajattelin: minä ilmoitan siitä sinulle ja sanon: osta se tässä saapuvilla olevien ja minun kansani vanhimpien läsnäollessa. Jos tahdot sen lunastaa sukuun, niin lunasta. Mutta ellet tahdo sitä lunastaa, niin ilmoita minulle, että saan sen tietää; sillä ei ole ketään muuta sukulunastajaa kuin sinä, ja sinun jälkeesi minä." Hän sanoi: "Minä lunastan sen".'),
(1676113,58,8,4,5,'Niin Booas sanoi: "Ostaessasi pellon Noomilta ostat sen myöskin mooabilaiselta Ruutilta, vainajan leskeltä, ja sinun on pysytettävä vainajan nimi hänen perintöosassaan".'),
(1676114,58,8,4,6,'Silloin sanoi sukulunastaja: "En voi lunastaa sitä itselleni, sillä siten minä turmelisin oman perintöosani. Lunasta sinä itsellesi, mitä minun olisi lunastettava; minä en voi sitä tehdä."'),
(1676115,58,8,4,7,'Muinoin oli Israelissa lunastus- ja vaihtokauppoja vahvistettaessa tapa tällainen: riisuttiin kenkä ja annettiin toiselle; tätä käytettiin Israelissa todistuksena.'),
(1676116,58,8,4,8,'Niin sukulunastaja sanoi Booaalle: "Osta sinä se itsellesi". Ja hän veti kengän jalastaan.'),
(1676117,58,8,4,9,'Silloin sanoi Booas vanhimmille ja kaikelle kansalle: "Te olette tänään todistajina, että minä ostan Noomilta kaiken Elimelekin ja kaiken Kiljonin ja Mahlonin omaisuuden.'),
(1676118,58,8,4,10,'Samalla minä olen ostanut myös mooabilaisen Ruutin, Mahlonin lesken, vaimokseni, pysyttääkseni vainajan nimen hänen perintöosassaan, ettei vainajan nimi häviäisi hänen veljiensä keskuudesta eikä hänen kotipaikkansa portista; sen todistajat te olette tänä päivänä."'),
(1676119,58,8,4,11,'Niin kaikki kansa, joka oli portissa saapuvilla, ja vanhimmat sanoivat: "Me olemme sen todistajat. Suokoon Herra, että vaimo, joka tulee taloosi, tulisi Raakelin ja Leean kaltaiseksi, jotka molemmat rakensivat Israelin huoneen. Tee väkeviä tekoja Efratassa ja saata nimesi kuuluisaksi Beetlehemissä.'),
(1676120,58,8,4,12,'Ja tulkoon niistä jälkeläisistä, jotka Herra antaa sinulle tästä nuoresta naisesta, sinulle suku, Pereksen suvun kaltainen, hänen, jonka Taamar synnytti Juudalle."'),
(1676121,58,8,4,13,'Niin Booas otti Ruutin, ja tämä tuli hänen vaimokseen. Ja hän yhtyi häneen; ja Herra antoi hänen tulla raskaaksi, ja hän synnytti pojan.'),
(1676122,58,8,4,14,'Silloin vaimot sanoivat Noomille: "Kiitetty olkoon Herra, joka tänä päivänä salli sinun saada sukulunastajan. Hänen nimensä tulee kuuluisaksi Israelissa.'),
(1676123,58,8,4,15,'Hän on virvoittava sinua, ja hänestä on tuleva sinun vanhuutesi tuki, sillä miniäsi, joka rakastaa sinua, on hänet synnyttänyt, hän, joka on sinulle parempi kuin seitsemän poikaa."'),
(1676124,58,8,4,16,'Niin Noomi otti lapsen, pani sen helmaansa ja rupesi sen hoitajaksi.'),
(1676125,58,8,4,17,'Ja naapurivaimot antoivat lapselle nimen, sanoen: "Noomille on syntynyt poika". Ja he panivat hänen nimekseen Oobed. Hänestä tuli Iisain, Daavidin isän, isä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676126,58,8,4,18,'Tämä on Pereksen sukuluettelo: Perekselle syntyi Hesron.'),
(1676127,58,8,4,19,'Hesronille syntyi Raam, ja Raamille syntyi Amminadab.'),
(1676128,58,8,4,20,'Amminadabille syntyi Nahson, ja Nahsonille syntyi Salma.'),
(1676129,58,8,4,21,'Salmalle syntyi Booas, ja Booaalle syntyi Oobed.'),
(1676130,58,9,1,1,'Raamataim-Soofimissa, Efraimin vuoristossa, oli mies, nimeltä Elkana, Jerohamin poika, joka oli Elihun poika, joka Toohun poika, joka Suufin poika, efratilainen.'),
(1676131,58,9,1,2,'Hänellä oli kaksi vaimoa; toisen nimi oli Hanna, ja toisen nimi oli Peninna. Ja Peninnalla oli lapsia, mutta Hanna oli lapseton.'),
(1676132,58,9,1,3,'Tämä mies meni joka vuosi kaupungistansa Siiloon rukoilemaan Herraa Sebaotia ja uhraamaan hänelle. Ja siellä oli kaksi Eelin poikaa, Hofni ja Piinehas, Herran pappeina.'),
(1676133,58,9,1,4,'Niin Elkana eräänä päivänä uhrasi. Ja hänellä oli tapana antaa vaimollensa Peninnalle ja kaikille tämän pojille ja tyttärille määräosat.'),
(1676134,58,9,1,5,'Mutta Hannalle hän antoi kahdenkertaisen osan, sillä hän rakasti Hannaa, vaikka Herra oli sulkenut hänen kohtunsa.'),
(1676135,58,9,1,6,'Ja hänen kilpailijattarensa kiusasi häntä kiusaamistaan suututtaaksensa häntä, koska Herra oli sulkenut hänen kohtunsa.'),
(1676136,58,9,1,7,'Ja näin tapahtui joka vuosi, niin usein kuin hän meni Herran huoneeseen. Niinpä Peninna nytkin kiusasi häntä, ja hän itki eikä syönyt mitään.'),
(1676137,58,9,1,8,'Silloin hänen miehensä Elkana sanoi hänelle: "Hanna, mitä itket, miksi et syö ja miksi olet noin apealla mielellä? Enkö minä ole sinulle enempi kuin kymmenen poikaa?"'),
(1676138,58,9,1,9,'Kun he sitten olivat syöneet ja juoneet Siilossa ja pappi Eeli istui istuimellaan Herran temppelin ovenpielessä, nousi Hanna'),
(1676139,58,9,1,10,'ja rukoili Herraa mieli murheellisena, itki katkerasti'),
(1676140,58,9,1,11,'ja teki lupauksen sanoen: "Herra Sebaot, jos sinä katsot palvelijattaresi kurjuutta, muistat minua etkä unhota palvelijatartasi, vaan annat palvelijattarellesi miehisen perillisen, niin minä annan hänet Herralle koko hänen elinajaksensa, eikä partaveitsi ole koskettava hänen päätänsä".'),
(1676141,58,9,1,12,'Ja kun hän kauan rukoili Herran edessä, tarkkasi Eeli hänen suutansa,'),
(1676142,58,9,1,13,'sillä Hanna puhui sydämessänsä ja ainoastaan hänen huulensa liikkuivat, mutta ääntä häneltä ei kuulunut; niin Eeli luuli, että hän oli juovuksissa.'),
(1676143,58,9,1,14,'Ja Eeli sanoi hänelle: "Kuinka kauan sinä siinä olet juovuksissa? Haihduta humalasi."'),
(1676144,58,9,1,15,'Mutta Hanna vastasi ja sanoi: "Ei, herrani, minä olen murheen raskauttama vaimo; viiniä ja väkijuomaa en ole juonut, vaan minä vuodatin sydämeni Herran eteen.'),
(1676145,58,9,1,16,'Älä pidä palvelijatartasi kelvottomana naisena, sillä tuskani ja suruni suuruuden tähden minä olen näin kauan puhunut."'),
(1676146,58,9,1,17,'Eeli vastasi ja sanoi: "Mene rauhaan, Israelin Jumala antakoon sinulle, mitä olet häneltä pyytänyt".'),
(1676147,58,9,1,18,'Hän sanoi: "Salli palvelijattaresi saada armo sinun silmiesi edessä". Niin vaimo meni pois ja söi eikä enää näyttänyt murheelliselta.'),
(1676148,58,9,1,19,'Varhain seuraavana aamuna he nousivat ja kumartaen rukoilivat Herran edessä; sitten he palasivat ja tulivat kotiinsa Raamaan. Ja Elkana yhtyi vaimoonsa Hannaan, ja Herra muisti tätä.'),
(1676149,58,9,1,20,'Ja Hanna tuli raskaaksi ja synnytti vuoden vaihteessa pojan ja antoi hänelle nimen Samuel, sanoen: "Herralta olen minä hänet pyytänyt".'),
(1676150,58,9,1,21,'Sitten se mies, Elkana, ja koko hänen perheensä lähti uhraamaan Herralle jokavuotista teurasuhria ja lupausuhriaan,'),
(1676151,58,9,1,22,'mutta Hanna ei lähtenyt, vaan sanoi miehellensä: "Kun poika on vieroitettu, vien minä hänet sinne, niin että hän tulee Herran kasvojen eteen ja saa jäädä sinne ainiaaksi".'),
(1676152,58,9,1,23,'Hänen miehensä Elkana sanoi hänelle: "Tee, niinkuin hyväksi näet, jää kotiin, kunnes olet hänet vieroittanut; kunhan Herra vain täyttää sanansa". Niin vaimo jäi kotiin ja imetti poikaansa, kunnes hän vieroitti tämän.'),
(1676153,58,9,1,24,'Mutta kun hän oli hänet vieroittanut, vei hän hänet kanssansa ottaen mukaansa kolme härkää, yhden eefa-mitan jauhoja ja leilin viiniä; niin hän toi hänet Herran huoneeseen Siiloon. Mutta poika oli vielä pieni.'),
(1676154,58,9,1,25,'Ja teurastettuaan härän he toivat pojan Eelin tykö.'),
(1676155,58,9,1,26,'Ja Hanna sanoi: "Oi, herrani, niin totta kuin sinä elät, herrani, minä olen se vaimo, joka seisoin tässä sinun luonasi rukoillen Herraa.'),
(1676156,58,9,1,27,'Tätä poikaa minä rukoilin; Herra antoi minulle, mitä häneltä pyysin.'),
(1676157,58,9,1,28,'Sentähden myös minä suostun antamaan hänet Herralle: kaikiksi elinpäiviksensä hän olkoon Herralle annettu." Ja Samuel rukoili siellä Herraa.'),
(1676158,58,9,2,1,'Ja Hanna rukoili ja sanoi: "Minun sydämeni riemuitsee Herrassa; minun sarveni kohoaa korkealle Herrassa. Minun suuni on avartunut vihollisiani vastaan, sillä minä iloitsen sinun avustasi.'),
(1676159,58,9,2,2,'Ei kukaan ole pyhä niinkuin Herra; paitsi sinua ei ole yhtäkään, eikä ole kalliota meidän Jumalamme vertaista.'),
(1676160,58,9,2,3,'Älkää yhä ylpeitä puhuko, älköön suustanne lähtekö julkeita sanoja; sillä Herra on kaikkitietävä Jumala, hänen edessänsä punnitaan teot.'),
(1676161,58,9,2,4,'Urhojen jouset ovat särjetyt, voipuneet vyöttäytyvät voimalla.'),
(1676162,58,9,2,5,'Kylläisinä olleet käyvät palvelukseen leipäpalkoilla, nälkää nähneet eivät enää nälkää näe. Hedelmätön synnyttää seitsemän lasta, lapsirikas kuihtuu.'),
(1676163,58,9,2,6,'Herra antaa kuoleman ja antaa elämän, hän vie alas tuonelaan ja tuo ylös jälleen.'),
(1676164,58,9,2,7,'Herra köyhdyttää ja rikastuttaa, hän alentaa ja ylentää.'),
(1676165,58,9,2,8,'Hän tomusta nostaa halvan, hän loasta korottaa köyhän, pannaksensa heidät ruhtinasten rinnalle ja antaaksensa heidän periä kunniasijat. Sillä maan tukipylväät ovat Herran, hän on asettanut niiden päälle maanpiirin.'),
(1676166,58,9,2,9,'Hän varjelee hurskastensa jalat, mutta jumalattomat hukkuvat pimeyteen; sillä mies ei omalla voimallaan mitään voi.'),
(1676167,58,9,2,10,'Jotka taistelevat Herraa vastaan, ne joutuvat kauhun valtaan; hän jylisee taivaasta heidän ylitsensä. Herra tuomitsee maan ääret; hän antaa vallan kuninkaallensa ja korottaa korkealle voideltunsa sarven."'),
(1676168,58,9,2,11,'Sitten Elkana meni kotiinsa Raamaan; mutta poikanen palveli Herraa pappi Eelin johdolla.'),
(1676169,58,9,2,12,'Mutta Eelin pojat olivat kelvottomia miehiä; he eivät välittäneet Herrasta'),
(1676170,58,9,2,13,'eivätkä siitä, mitä papeilla oli oikeus kansalta saada. Niin usein kuin joku uhrasi teurasuhria, tuli papin palvelija lihan kiehuessa, kolmihaarainen haarukka kädessänsä,'),
(1676171,58,9,2,14,'ja pisti sen kattilaan tai ruukkuun tai pannuun tai pataan, ja kaikki, minkä haarukka toi mukanaan, sen pappi otti itselleen. Niin he tekivät kaikille israelilaisille, jotka tulivat sinne Siiloon.'),
(1676172,58,9,2,15,'Jo ennenkuin rasva oli poltettu, tuli papin palvelija ja sanoi miehelle, joka uhrasi: "Anna liha paistettavaksi papille, sillä hän ei ota sinulta keitettyä lihaa, vaan raakaa".'),
(1676173,58,9,2,16,'Kun mies sanoi hänelle: "Ensin poltettakoon rasva; ota sitten itsellesi, mitä haluat", niin hän sanoi: "Ei niin, vaan anna se nyt heti, muutoin minä otan väkisin".'),
(1676174,58,9,2,17,'Ja nuorten miesten synti oli kovin suuri Herran edessä, koska he pitivät Herran uhrilahjan halpana.'),
(1676175,58,9,2,18,'Mutta Samuel palveli Herran edessä, puettuna, vaikka oli poikanen, pellavakasukkaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676176,58,9,2,19,'Ja hänen äitinsä teki hänelle joka vuosi pienen viitan ja toi sen hänelle, kun miehensä kanssa tuli uhraamaan vuotuista teurasuhria.'),
(1676177,58,9,2,20,'Silloin Eeli aina siunasi Elkanan ja hänen vaimonsa ja sanoi: "Herra antakoon sinulle lapsen tästä vaimosta sen sijaan, jonka hän on suostunut antamaan Herralle"; sitten he menivät kotiinsa.'),
(1676178,58,9,2,21,'Ja Herra piti Hannasta huolen, niin että hän tuli raskaaksi ja synnytti vielä kolme poikaa ja kaksi tytärtä. Mutta poikanen Samuel kasvoi Herran edessä.'),
(1676179,58,9,2,22,'Mutta Eeli oli käynyt hyvin vanhaksi; ja kun hän sai kuulla, mitä hänen poikansa tekivät kaikelle Israelille, ja että he makasivat niiden naisten kanssa, jotka toimittivat palvelusta ilmestysmajan ovella,'),
(1676180,58,9,2,23,'sanoi hän heille: "Miksi te sellaista pahaa teette, mitä minä teistä kuulen kaikelta tältä kansalta?'),
(1676181,58,9,2,24,'Ei niin, poikani! Ei ole hyvä se huhu, jonka minä kuulen kulkevan Herran kansan seassa.'),
(1676182,58,9,2,25,'Jos ihminen rikkoo ihmistä vastaan, niin Jumala voi olla hänellä välittäjänä; mutta jos ihminen rikkoo Herraa vastaan, niin kuka voi ruveta hänelle välittäjäksi?" Mutta he eivät kuulleet isäänsä, sillä Herra tahtoi surmata heidät.'),
(1676183,58,9,2,26,'Mutta poikanen Samuel kasvoi kasvamistaan ja oli sekä Herralle että ihmisille otollinen.'),
(1676184,58,9,2,27,'Ja Eelin luo tuli Jumalan mies ja sanoi hänelle: "Näin sanoo Herra: Enkö minä ilmestynyt sinun isäsi suvulle, kun he olivat Egyptissä faraon huoneen vallassa?'),
(1676185,58,9,2,28,'Ja minä valitsin heidät kaikista Israelin sukukunnista olemaan pappeinani, nousemaan minun alttarilleni, polttamaan suitsuketta ja kantamaan kasukkaa minun edessäni; ja minä annoin sinun isäsi suvulle kaikki israelilaisten uhrit.'),
(1676186,58,9,2,29,'Miksi te häpäisette minun teurasuhrini ja ruokauhrini, jotka minä olen säätänyt asuntooni? Ja miksi sinä kunnioitat poikiasi enemmän kuin minua, niin että te lihotatte itseänne parhaalla osalla jokaisesta minun kansani Israelin uhrilahjasta?'),
(1676187,58,9,2,30,'Sentähden Herra, Israelin Jumala, sanoo: Minä olen tosin sanonut: sinun sukusi ja sinun isäsi suku saavat vaeltaa minun edessäni iäti. Mutta nyt Herra sanoo: Pois se! Sillä minä kunnioitan niitä, jotka minua kunnioittavat; mutta jotka minut ylenkatsovat, ne tulevat halveksituiksi.'),
(1676188,58,9,2,31,'Katso, päivät tulevat, jolloin minä katkaisen sinun käsivartesi ja sinun isäsi suvun käsivarren, niin ettei kukaan sinun suvussasi elä vanhaksi.'),
(1676189,58,9,2,32,'Ja sinä saat nähdä minun asuntoni olevan puutteessa huolimatta kaikesta siitä hyvästä, mikä tulee Israelille. Eikä kukaan sinun suvussasi ole koskaan elävä vanhaksi.'),
(1676190,58,9,2,33,'Kuitenkaan minä en hävitä kaikkia sinun omaisiasi alttariltani, niin että sammuttaisin sinun silmäsi ja näännyttäisin sielusi; mutta kaikki sinun suvussasi kasvaneet kuolevat miehiksi tultuaan.'),
(1676191,58,9,2,34,'Ja merkkinä tästä on sinulla oleva se, mitä kahdelle pojallesi, Hofnille ja Piinehaalle, tapahtuu: he kuolevat molemmat samana päivänä.'),
(1676192,58,9,2,35,'Mutta minä herätän itselleni uskollisen papin, joka tekee minun sydämeni ja mieleni mukaan. Hänelle minä rakennan pysyväisen huoneen, ja hän on vaeltava minun voideltuni edessä kaiken elinaikansa.'),
(1676193,58,9,2,36,'Ja jokainen, joka jää jäljelle sinun suvustasi, on tuleva kumartamaan häntä saadaksensa hopearahan ja leipäkakun ja sanovat: ''Päästä minutkin johonkin papintehtävään, että saisin palan leipää syödäkseni''."'),
(1676194,58,9,3,1,'Ja poikanen Samuel palveli Herraa Eelin johdolla; mutta Herran sana oli harvinainen siihen aikaan, eivätkä näyt olleet tavallisia.'),
(1676195,58,9,3,2,'Siihen aikaan tapahtui kerran, kun Eeli, jonka silmiä alkoi hämärtää, niin ettei hän voinut nähdä, makasi sijallansa'),
(1676196,58,9,3,3,'eikä Jumalan lamppu ollut vielä sammunut ja Samuel makasi Herran temppelissä, jossa Jumalan arkki oli,'),
(1676197,58,9,3,4,'että Herra kutsui Samuelia. Hän vastasi: "Tässä olen".'),
(1676198,58,9,3,5,'Ja hän riensi Eelin tykö ja sanoi: "Tässä olen, sinä kutsuit minua". Mutta hän vastasi: "En minä kutsunut; pane jälleen maata". Ja hän meni ja pani maata.'),
(1676199,58,9,3,6,'Mutta Herra kutsui taas Samuelia; ja Samuel nousi ja meni Eelin tykö ja sanoi: "Tässä olen, sinä kutsuit minua". Mutta tämä vastasi: "En minä kutsunut, poikani; pane jälleen maata".'),
(1676200,58,9,3,7,'Mutta Samuel ei silloin vielä tuntenut Herraa, eikä Herran sana ollut vielä ilmestynyt hänelle.'),
(1676201,58,9,3,8,'Ja Herra kutsui Samuelia vielä kolmannen kerran; niin hän nousi ja meni Eelin tykö ja sanoi: "Tässä olen, sinä kutsuit minua". Silloin Eeli ymmärsi, että Herra oli kutsunut poikasta.'),
(1676202,58,9,3,9,'Ja Eeli sanoi Samuelille: "Mene ja pane maata; ja jos sinua vielä kutsutaan, niin sano: ''Puhu, Herra; palvelijasi kuulee''". Samuel meni ja pani maata sijallensa.'),
(1676203,58,9,3,10,'Niin Herra tuli ja seisoi ja huusi niinkuin edellisilläkin kerroilla: "Samuel, Samuel!" Samuel vastasi: "Puhu, palvelijasi kuulee".'),
(1676204,58,9,3,11,'Ja Herra sanoi Samuelille: "Katso, minä teen Israelissa sellaisen teon, että joka sen kuulee, sen molemmat korvat soivat.'),
(1676205,58,9,3,12,'Sinä päivänä minä annan toteutua Eelille kaiken, mitä olen hänen sukuansa vastaan puhunut, alusta loppuun asti.'),
(1676206,58,9,3,13,'Minä ilmoitan hänelle, että minä tuomitsen hänen sukunsa ikuisiksi ajoiksi sen rikoksen tähden, kun hän tiesi poikiensa pilkkaavan Jumalaa eikä pitänyt heitä kurissa.'),
(1676207,58,9,3,14,'Sentähden minä olen vannonut Eelin suvusta: ''Totisesti, Eelin suvun rikosta ei koskaan soviteta, ei teurasuhrilla eikä ruokauhrilla''."'),
(1676208,58,9,3,15,'Ja Samuel makasi aamuun asti ja avasi sitten Herran huoneen ovet. Eikä Samuel uskaltanut kertoa Eelille sitä ilmestystä.'),
(1676209,58,9,3,16,'Mutta Eeli kutsui Samuelin ja sanoi: "Samuel, poikani!" Hän vastasi: "Tässä olen".'),
(1676210,58,9,3,17,'Hän sanoi: "Mikä oli asia, josta hän sinulle puhui? Älä salaa sitä minulta. Jumala rangaiskoon sinua nyt ja vasta, jos salaat minulta mitään siitä, mitä hän sinulle puhui."'),
(1676211,58,9,3,18,'Niin Samuel kertoi hänelle kaiken eikä salannut häneltä mitään. Mutta hän sanoi: "Hän on Herra; hän tehköön, minkä hyväksi näkee".'),
(1676212,58,9,3,19,'Ja Samuel kasvoi, ja Herra oli hänen kanssansa eikä antanut yhdenkään sanoistansa varista maahan.'),
(1676213,58,9,3,20,'Ja koko Israel Daanista Beersebaan asti tiesi, että Samuelille oli uskottu Herran profeetan tehtävä.'),
(1676214,58,9,3,21,'Ja Herra ilmestyi edelleenkin Siilossa; sillä Herra ilmestyi Samuelille Siilossa Herran sanan kautta. Ja Samuelin sana tuli koko Israelille.'),
(1676215,58,9,4,1,'Israel lähti sotaan filistealaisia vastaan ja leiriytyi Eben-Eserin luo, mutta filistealaiset olivat leiriytyneet Afekiin.'),
(1676216,58,9,4,2,'Ja filistealaiset asettuivat sotarintaan Israelia vastaan, ja taistelu levisi laajalle, ja filistealaiset voittivat Israelin ja surmasivat taistelukentällä noin neljätuhatta miestä.'),
(1676217,58,9,4,3,'Kun kansa tuli leiriin, sanoivat Israelin vanhimmat: "Minkätähden Herra antoi tänä päivänä filistealaisten voittaa meidät? Ottakaamme Herran liitonarkki Siilosta luoksemme, tulkoon se keskellemme pelastamaan meidät vihollistemme käsistä."'),
(1676218,58,9,4,4,'Ja kansa lähetti sanan Siiloon, ja sieltä tuotiin Herran Sebaotin liitonarkki, hänen, jonka valtaistuinta kerubit kannattavat; ja Eelin kaksi poikaa, Hofni ja Piinehas, seurasivat sieltä Jumalan liitonarkkia.'),
(1676219,58,9,4,5,'Ja kun Herran liitonarkki tuli leiriin, nosti koko Israel suuren riemuhuudon, niin että maa jymisi.'),
(1676220,58,9,4,6,'Kun filistealaiset kuulivat sen riemuhuudon, sanoivat he: "Mitä tuo suuri riemuhuuto on hebrealaisten leirissä?" Ja he saivat tietää, että leiriin oli tullut Herran arkki.'),
(1676221,58,9,4,7,'Silloin filistealaiset peljästyivät, sillä he ajattelivat: "Jumala on tullut leiriin". Ja he sanoivat: "Voi meitä! Tällaista ei ole milloinkaan ennen tapahtunut.'),
(1676222,58,9,4,8,'Voi meitä! Kuka pelastaa meidät tämän voimallisen jumalan kädestä? Tämähän on se jumala, joka löi egyptiläisiä kaikkinaisilla vaivoilla erämaassa.'),
(1676223,58,9,4,9,'Rohkaiskaa mielenne ja olkaa miehiä, filistealaiset, ettette te joutuisi palvelemaan hebrealaisia, niinkuin he ovat palvelleet teitä. Olkaa miehiä ja taistelkaa."'),
(1676224,58,9,4,10,'Ja filistealaiset ryhtyivät taisteluun; ja Israel voitettiin, niin että he pakenivat kukin majallensa, ja tappio oli sangen suuri: Israelista kaatui kolmekymmentä tuhatta jalkamiestä.'),
(1676225,58,9,4,11,'Ja Jumalan arkki ryöstettiin, ja Eelin kaksi poikaa, Hofni ja Piinehas, saivat surmansa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676226,58,9,4,12,'Eräs benjaminilainen mies juoksi sotarinnasta ja tuli samana päivänä Siiloon, takki reväistynä ja multaa pään päällä.'),
(1676227,58,9,4,13,'Ja kun hän tuli sinne, istui Eeli istuimellaan tien vieressä tähystellen, sillä hänen sydämensä oli levoton Jumalan arkin tähden. Ja kun mies tuli ja kertoi kaupungissa tapahtumasta, puhkesi koko kaupunki valittamaan.'),
(1676228,58,9,4,14,'Kun Eeli kuuli valitushuudon, kysyi hän: "Mikä meteli tämä on?" Niin mies tuli rientäen sinne ja kertoi sen Eelille.'),
(1676229,58,9,4,15,'Mutta Eeli oli yhdeksänkymmenen kahdeksan vuoden vanha, ja hänen silmissään oli kaihi, niin ettei hän voinut nähdä.'),
(1676230,58,9,4,16,'Ja mies sanoi Eelille: "Minä tulen sotarinnasta; olen tänä päivänä paennut sotarinnasta". Niin hän kysyi: "Miten on asiat, poikani?"'),
(1676231,58,9,4,17,'Sanansaattaja vastasi ja sanoi: "Israel on paennut filistealaisia, ja kansan mieshukka on suuri; myöskin sinun molemmat poikasi, Hofni ja Piinehas, ovat saaneet surmansa, ja Jumalan arkki on ryöstetty".'),
(1676232,58,9,4,18,'Kun hän mainitsi Jumalan arkin, kaatui Eeli istuimeltaan taapäin portin viereen, taittoi niskansa ja kuoli; sillä hän oli vanha ja raskas mies. Ja hän oli ollut tuomarina Israelissa neljäkymmentä vuotta.'),
(1676233,58,9,4,19,'Ja hänen miniänsä, Piinehaan vaimo, oli viimeisillänsä raskaana. Kun hän kuuli sanoman Jumalan arkin ryöstöstä ja appensa ja miehensä kuolemasta, vaipui hän maahan ja synnytti, sillä poltot yllättivät hänet.'),
(1676234,58,9,4,20,'Ja kun hän silloin oli kuolemaisillansa, sanoivat vaimot, jotka seisoivat hänen luonaan: "Älä pelkää, sillä sinä olet synnyttänyt pojan". Mutta hän ei vastannut mitään eikä välittänyt siitä,'),
(1676235,58,9,4,21,'vaan nimitti pojan Iikabodiksi ja sanoi: "Kunnia on mennyt Israelilta" - hän tarkoitti Jumalan arkin ryöstöä ja appeansa ja miestänsä.'),
(1676236,58,9,4,22,'Hän sanoi: "Kunnia on mennyt Israelilta", koska Jumalan arkki oli ryöstetty.'),
(1676237,58,9,5,1,'Kun filistealaiset olivat ryöstäneet Jumalan arkin, veivät he sen Eben-Eseristä Asdodiin.'),
(1676238,58,9,5,2,'Ja filistealaiset ottivat Jumalan arkin ja veivät sen Daagonin temppeliin ja asettivat sen Daagonin rinnalle.'),
(1676239,58,9,5,3,'Kun asdodilaiset nousivat varhain seuraavana päivänä, niin katso: Daagon makasi kasvoillaan maassa Herran arkin edessä. Mutta he ottivat Daagonin ja asettivat sen takaisin paikoillensa.'),
(1676240,58,9,5,4,'Kun he taas nousivat varhain seuraavana aamuna, niin katso: Daagon makasi kasvoillaan maassa Herran arkin edessä, mutta Daagonin pää ja molemmat kädet olivat katkaistuina kynnyksellä, ja ainoastaan muu ruumis oli jäljellä.'),
(1676241,58,9,5,5,'Sentähden eivät Daagonin papit eikä kukaan, joka menee Daagonin temppeliin, astu Daagonin kynnykselle Asdodissa vielä tänäkään päivänä.'),
(1676242,58,9,5,6,'Mutta Herran käsi painoi asdodilaisia, ja hän tuhosi heitä: hän löi heitä ajoksilla, sekä Asdodia että sen aluetta.'),
(1676243,58,9,5,7,'Kun Asdodin miehet näkivät, miten oli, sanoivat he: "Älköön Israelin Jumalan arkki jääkö meidän luoksemme, sillä hänen kätensä on käynyt raskaaksi meille ja meidän jumalallemme Daagonille".'),
(1676244,58,9,5,8,'Ja he lähettivät sanan ja kokosivat kaikki filistealaisten ruhtinaat luoksensa ja sanoivat: "Mitä me teemme Israelin Jumalan arkille?" He vastasivat: "Israelin Jumalan arkki siirtyköön Gatiin". Ja he siirsivät Israelin Jumalan arkin sinne.'),
(1676245,58,9,5,9,'Mutta kun he olivat siirtäneet sen sinne, kohtasi Herran käsi kaupunkia ja sai aikaan suuren hämmingin: hän löi kaupungin asukkaita, sekä pieniä että suuria, niin että heihin puhkesi ajoksia.'),
(1676246,58,9,5,10,'Silloin he lähettivät Jumalan arkin Ekroniin. Mutta kun Jumalan arkki tuli Ekroniin, huusivat ekronilaiset sanoen: "He ovat siirtäneet Israelin Jumalan arkin tänne minun luokseni, surmaamaan minut ja minun kansani".'),
(1676247,58,9,5,11,'Ja he lähettivät sanan ja kokosivat kaikki filistealaisten ruhtinaat ja sanoivat: "Lähettäkää Israelin Jumalan arkki pois, ja palatkoon se kotiinsa älköönkä enää surmatko minua ja minun kansaani". Sillä surma oli saattanut koko kaupungin hämminkiin; Jumalan käsi painoi sitä kovasti.'),
(1676248,58,9,5,12,'Ne asukkaat, jotka eivät kuolleet, olivat ajoksilla lyödyt, ja huuto nousi kaupungista ylös taivaaseen.'),
(1676249,58,9,6,1,'Herran arkki oli filistealaisten maassa seitsemän kuukautta.'),
(1676250,58,9,6,2,'Ja filistealaiset kutsuivat papit ja tietäjät ja sanoivat: "Mitä me teemme Herran arkille? Antakaa meidän tietää, millä tavalla me lähettäisimme sen kotiinsa."'),
(1676251,58,9,6,3,'He vastasivat: "Jos te lähetätte Israelin Jumalan arkin pois, niin älkää lähettäkö häntä tyhjin käsin, vaan antakaa hänelle hyvitys. Silloin te tulette terveiksi ja saatte tietää, minkätähden hänen kätensä ei heltiä teistä."'),
(1676252,58,9,6,4,'Mutta he kysyivät: "Minkälainen hyvitys meidän on annettava hänelle?" He vastasivat: "Viisi kulta-ajosta ja viisi kultahiirtä, yhtä monta, kuin on filistealaisten ruhtinasta; sillä sama vitsaus on kohdannut kaikkia, myöskin teidän ruhtinaitanne.'),
(1676253,58,9,6,5,'Tehkää siis ajoksistanne kuvat, samoin hiiristänne, jotka hävittävät maata, ja antakaa kunnia Israelin Jumalalle. Kenties hän silloin hellittää kätensä teistä, teidän jumalistanne ja maastanne.'),
(1676254,58,9,6,6,'Miksi te paadutatte sydämenne, niinkuin egyptiläiset ja farao paaduttivat sydämensä? Eivätkö he, sittenkuin hän oli näyttänyt heille voimansa, päästäneet israelilaisia menemään?'),
(1676255,58,9,6,7,'Niin tehkää nyt uudet vaunut ja ottakaa kaksi imettävää lehmää, joiden niskassa ei ole iestä ollut, ja valjastakaa lehmät vaunujen eteen, mutta ajakaa vasikat kotiin, pois niiden jäljestä.'),
(1676256,58,9,6,8,'Ja ottakaa Herran arkki ja asettakaa se vaunuihin ja pankaa ne kultakalut, jotka annatte hänelle hyvitykseksi, lippaaseen sen viereen, ja lähettäkää se menemään.'),
(1676257,58,9,6,9,'Ja sitten katsokaa: jos hän menee omaa aluettaan kohti, ylös Beet-Semekseen, niin on hän tuottanut meille tämän suuren onnettomuuden; mutta jos ei, niin tiedämme, ettei hänen kätensä ole meihin koskenut. Se on silloin tapahtunut meille sattumalta."'),
(1676258,58,9,6,10,'Miehet tekivät niin; he ottivat kaksi imettävää lehmää ja valjastivat ne vaunujen eteen, mutta niiden vasikat he jättivät kotiin.'),
(1676259,58,9,6,11,'Ja he panivat Herran arkin vaunuihin ynnä lippaan, kultahiiret ja paiseittensa kuvat.'),
(1676260,58,9,6,12,'Ja lehmät menivät suoraan Beet-Semestä kohti; ne kulkivat koko ajan samaa tietä, poikkeamatta oikealle tai vasemmalle, ja ammuivat lakkaamatta. Ja filistealaisten ruhtinaat seurasivat niitä Beet-Semeksen alueelle asti.'),
(1676261,58,9,6,13,'Mutta Beet-Semeksessä oltiin leikkaamassa nisua laaksossa. Kun he nostivat silmänsä, näkivät he arkin; ja he ilostuivat nähdessään sen.'),
(1676262,58,9,6,14,'Vaunut tulivat beet-semekseläisen Joosuan pellolle ja pysähtyivät sinne; ja siellä oli suuri kivi. Ja he hakkasivat vaunut haloiksi ja uhrasivat lehmät polttouhriksi Herralle.'),
(1676263,58,9,6,15,'Ja leeviläiset nostivat maahan Herran arkin ja sen vieressä olevan lippaan, jossa kultakalut olivat, ja panivat ne sille suurelle kivelle. Ja Beet-Semeksen miehet uhrasivat sinä päivänä Herralle polttouhreja ja teurasuhreja.'),
(1676264,58,9,6,16,'Katseltuaan tätä ne filistealaisten viisi ruhtinasta palasivat samana päivänä Ekroniin.'),
(1676265,58,9,6,17,'Nämä ovat ne kultapaiseet, jotka filistealaiset antoivat Herralle hyvitykseksi: yksi Asdodin puolesta, yksi Gassan puolesta, yksi Askelonin puolesta, yksi Gatin puolesta ja yksi Ekronin puolesta.'),
(1676266,58,9,6,18,'Mutta kultahiiriä oli yhtä monta, kuin oli kaikkiaan filistealaisten kaupunkeja viidellä ruhtinaalla, niin hyvin varustettuja kaupunkeja kuin linnoittamattomia kyliä, suureen Aabel-kiveen asti, jolle he laskivat Herran arkin ja joka on vielä tänäkin päivänä beet-semekseläisen Joosuan pellolla.'),
(1676267,58,9,6,19,'Mutta Herra surmasi Beet-Semeksen miehiä sentähden, että he olivat katsoneet Herran arkkia; hän surmasi kansasta seitsemänkymmentä miestä, viisikymmentä tuhatta miestä; ja kansa suri sitä, että Herra oli surmannut niin paljon kansaa.'),
(1676268,58,9,6,20,'Ja Beet-Semeksen miehet sanoivat: "Kuka voi kestää Herran, tämän pyhän Jumalan, edessä? Ja kenen luo hän menee meidän luotamme?"'),
(1676269,58,9,6,21,'Ja he lähettivät sanansaattajat Kirjat-Jearimin asukasten luo sanomaan: "Filistealaiset ovat tuoneet Herran arkin takaisin; tulkaa tänne ja viekää se luoksenne".'),
(1676270,58,9,7,1,'Niin Kirjat-Jearimin miehet tulivat ja veivät Herran arkin sinne ja toivat sen Abinadabin taloon mäelle. Ja hänen poikansa Eleasarin he pyhittivät pitämään huolta Herran arkista.'),
(1676271,58,9,7,2,'Ja siitä päivästä, jona arkki oli asettunut Kirjat-Jearimiin, kului pitkä aika, kului kaksikymmentä vuotta; ja koko Israelin heimo huokaili Herran puoleen.'),
(1676272,58,9,7,3,'Mutta Samuel sanoi koko Israelin heimolle näin: "Jos te kaikesta sydämestänne käännytte Herran puoleen, niin poistakaa keskuudestanne vieraat jumalat ja astartet ja kiinnittäkää sydämenne Herraan ja palvelkaa ainoastaan häntä, niin hän pelastaa teidät filistealaisten käsistä".'),
(1676273,58,9,7,4,'Niin israelilaiset poistivat baalit ja astartet ja palvelivat ainoastaan Herraa.'),
(1676274,58,9,7,5,'Ja Samuel sanoi: "Kootkaa koko Israel Mispaan, ja minä rukoilen teidän puolestanne Herraa".'),
(1676275,58,9,7,6,'Niin he kokoontuivat Mispaan, ammensivat vettä ja vuodattivat sitä Herran eteen sekä paastosivat sen päivän; ja he sanoivat siellä: "Me olemme tehneet syntiä Herraa vastaan". Ja Samuel jakoi israelilaisille oikeutta Mispassa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676276,58,9,7,7,'Kun filistealaiset kuulivat israelilaisten kokoontuneen Mispaan, lähtivät filistealaisten ruhtinaat Israelia vastaan. Kun israelilaiset kuulivat sen, pelkäsivät he filistealaisia.'),
(1676277,58,9,7,8,'Ja israelilaiset sanoivat Samuelille: "Älä kieltäydy huutamasta meidän puolestamme Herraa, meidän Jumalaamme, että hän pelastaisi meidät filistealaisten käsistä".'),
(1676278,58,9,7,9,'Niin Samuel otti imevän karitsan ja uhrasi sen polttouhriksi, kokonaisuhriksi, Herralle; ja Samuel huusi Herraa Israelin puolesta, ja Herra kuuli häntä.'),
(1676279,58,9,7,10,'Sillä kun Samuelin uhratessa polttouhria filistealaiset lähestyivät käydäkseen taisteluun Israelia vastaan, niin sinä päivänä Herra jylisi kovalla ukkosen jylinällä filistealaisia vastaan ja saattoi heidät hämminkiin, niin että Israel voitti heidät.'),
(1676280,58,9,7,11,'Ja Israelin miehet lähtivät Mispasta ja ajoivat filistealaisia takaa, surmaten heitä aina Beet-Kaarin alapuolelle asti.'),
(1676281,58,9,7,12,'Ja Samuel otti kiven ja pani sen Mispan ja Seenin välille ja antoi sille nimen Eben-Eser ja sanoi: "Tähän asti on Herra meitä auttanut".'),
(1676282,58,9,7,13,'Niin filistealaiset lannistettiin, eivätkä he enää tulleet Israelin alueelle. Ja Herran käsi oli filistealaisia vastaan Samuelin koko elinajan.'),
(1676283,58,9,7,14,'Ja ne kaupungit, jotka filistealaiset olivat ottaneet Israelilta, joutuivat takaisin Israelille, Ekronista Gatiin saakka; ja myös niiden alueet Israel vapautti filistealaisten käsistä. Myöskin Israelin ja amorilaisten välillä oli rauha.'),
(1676284,58,9,7,15,'Samuel oli tuomarina Israelissa koko elinaikansa.'),
(1676285,58,9,7,16,'Ja hän teki joka vuosi kiertomatkoja Beeteliin, Gilgaliin ja Mispaan, ja hän jakoi Israelille oikeutta kaikissa näissä paikoissa.'),
(1676286,58,9,7,17,'Sitten hän palasi jälleen Raamaan, sillä siellä oli hänen kotinsa ja siellä hän jakoi oikeutta Israelille. Ja hän rakensi sinne alttarin Herralle.'),
(1676287,58,9,8,1,'Kun Samuel oli käynyt vanhaksi, pani hän poikansa Israelin tuomareiksi.'),
(1676288,58,9,8,2,'Hänen esikoisensa nimi oli Jooel, ja hänen toisen poikansa nimi oli Abia; nämä olivat tuomareina Beersebassa.'),
(1676289,58,9,8,3,'Mutta hänen poikansa eivät vaeltaneet hänen teitänsä, vaan olivat väärän voiton pyytäjiä, ottivat lahjuksia ja vääristivät oikeutta.'),
(1676290,58,9,8,4,'Niin kaikki Israelin vanhimmat kokoontuivat ja tulivat Samuelin tykö Raamaan'),
(1676291,58,9,8,5,'ja sanoivat hänelle: "Katso, sinä olet käynyt vanhaksi, eivätkä poikasi vaella sinun teitäsi. Niin aseta nyt meille oikeutta jakamaan kuningas, jollainen kaikilla muillakin kansoilla on."'),
(1676292,58,9,8,6,'Mutta Samuel pahastui siitä, että he sanoivat: "Anna meille kuningas jakamaan meille oikeutta". Ja Samuel rukoili Herraa.'),
(1676293,58,9,8,7,'Niin Herra sanoi Samuelille: "Kuule kansan ääntä kaikessa, mitä he sinulle sanovat; sillä sinua he eivät ole pitäneet halpana, vaan minut he ovat pitäneet halpana olemaan heidän kuninkaanansa.'),
(1676294,58,9,8,8,'Niinkuin he aina siitä päivästä, jona minä johdatin heidät tänne Egyptistä, tähän päivään asti ovat tehneet, kun ovat hyljänneet minut ja palvelleet muita jumalia, aivan niin he tekevät nyt sinullekin.'),
(1676295,58,9,8,9,'Kuule siis heidän ääntänsä. Kuitenkin varoita heitä vakavasti ja ilmoita heille, mitkä oikeudet on kuninkaalla, joka on heitä hallitseva."'),
(1676296,58,9,8,10,'Niin Samuel puhui kaikki Herran sanat kansalle, joka häneltä pyysi kuningasta.'),
(1676297,58,9,8,11,'Hän sanoi: "Nämä oikeudet on kuninkaalla, joka on teitä hallitseva: Teidän poikanne hän ottaa ja panee heidät vaunumiehikseen ja ratsumiehikseen ja vaunujensa edelläjuoksijoiksi.'),
(1676298,58,9,8,12,'Myöskin hän panee heitä tuhannen- ja viidenkymmenenpäämiehiksi ja kyntämään hänen kyntöjänsä ja leikkaamaan hänen viljaansa sekä tekemään hänelle sotatarpeita ja vaunutarpeita.'),
(1676299,58,9,8,13,'Ja teidän tyttärenne hän ottaa voiteiden tekijöiksi, keittäjiksi ja leipojiksi.'),
(1676300,58,9,8,14,'Hän ottaa teidän parhaat peltonne, viinitarhanne ja öljypuunne ja antaa ne palvelijoillensa;'),
(1676301,58,9,8,15,'ja hän ottaa kymmenykset teidän kylvöstänne ja viinitarhojenne sadosta ja antaa ne hoviherroillensa ja palvelijoillensa.'),
(1676302,58,9,8,16,'Hän ottaa myös teidän palvelijanne ja palvelijattarenne ja parhaat nuoret miehenne sekä aasinne ja teettää niillä työnsä;'),
(1676303,58,9,8,17,'ja hän ottaa kymmenykset teidän lampaistanne, ja te tulette hänen palvelijoiksensa.'),
(1676304,58,9,8,18,'Silloin te huudatte Herraa kuninkaanne tähden, jonka olette itsellenne valinneet, mutta hän ei silloin teitä kuule."'),
(1676305,58,9,8,19,'Mutta kansa ei tahtonut kuulla Samuelin puhetta, vaan sanoi: "Ei, kuningas meillä pitää olla.'),
(1676306,58,9,8,20,'Mekin tahdomme olla niinkuin kaikki muut kansat: kuningas jakakoon meille oikeutta ja johtakoon meitä ja käyköön sotiamme."'),
(1676307,58,9,8,21,'Kun Samuel kuuli kaikki kansan puheet, puhui hän ne Herralle.'),
(1676308,58,9,8,22,'Ja Herra sanoi Samuelille: "Kuule heidän ääntänsä ja aseta heille kuningas". Niin Samuel sanoi Israelin miehille: "Menkää kukin kaupunkiinne".'),
(1676309,58,9,9,1,'Benjaminissa oli mies, hyvin varakas, nimeltä Kiis, Abielin poika, joka oli Serorin poika, joka Bekoratin poika, joka Afiahin poika, joka erään benjaminilaisen miehen poika.'),
(1676310,58,9,9,2,'Hänellä oli poika, nimeltä Saul, nuori, kaunis mies. Israelilaisten joukossa ei ollut kauniimpaa miestä kuin hän: hän oli päätänsä pitempi kaikkea kansaa.'),
(1676311,58,9,9,3,'Ja Kiisiltä, Saulin isältä, olivat aasintammat joutuneet kateisiin, ja Kiis sanoi pojallensa Saulille: "Ota palvelijoista joku mukaasi, nouse ja mene etsimään aasintammoja".'),
(1676312,58,9,9,4,'Niin hän kulki Efraimin vuoriston halki, ja hän kulki Salisan maan halki; mutta he eivät löytäneet niitä. Ja he kulkivat Saalimin maan halki, eikä niitä ollut sielläkään; sitten he kulkivat Benjaminin maan halki eivätkä löytäneet niitä.'),
(1676313,58,9,9,5,'Kun he olivat tulleet Suufin maahan, sanoi Saul palvelijallensa, joka hänellä oli mukanaan: "Tule, palatkaamme kotiin; muutoin isäni käy levottomaksi meidän tähtemme ja jättää mielestään aasintammat".'),
(1676314,58,9,9,6,'Mutta palvelija sanoi hänelle: "Katso, tässä kaupungissa on Jumalan mies, arvossa pidetty mies; kaikki, mitä hän sanoo, se varmasti toteutuu. Menkäämme nyt sinne; kenties hän ilmaisee meille jotakin matkasta, jolla olemme."'),
(1676315,58,9,9,7,'Niin Saul sanoi palvelijallensa: "Jos menemme sinne, niin mitä me viemme sille miehelle? Sillä leipä on loppunut repuistamme, eikä meillä ole muutakaan lahjaa vietäväksi Jumalan miehelle. Vai onko meillä mitään?"'),
(1676316,58,9,9,8,'Palvelija vastasi vielä Saulille ja sanoi: "Katso, tässä on minulla neljännes sekeliä hopeata; minä annan sen Jumalan miehelle, että hän ilmaisisi meille jotakin matkastamme".'),
(1676317,58,9,9,9,'- Muinoin sanottiin Israelissa, kun mentiin kysymään Jumalalta, näin: "Tulkaa, menkäämme näkijän luo". Sillä sitä, jota nyt sanotaan profeetaksi, kutsuttiin muinoin näkijäksi. -'),
(1676318,58,9,9,10,'Saul vastasi palvelijallensa: "Puheesi on hyvä; tule, menkäämme". Ja he menivät kaupunkiin, jossa Jumalan mies oli.'),
(1676319,58,9,9,11,'Kun he nousivat rinnettä ylös kaupunkiin, kohtasivat he tyttöjä, jotka olivat menossa vettä ammentamaan. Näiltä he kysyivät: "Onko näkijä täällä?"'),
(1676320,58,9,9,12,'Nämä vastasivat heille ja sanoivat: "On, katso, hän on tuolla edessäpäin. Riennä, sillä hän on juuri nyt tullut kaupunkiin, koska kansalla tänä päivänä on teurasuhrit uhrikukkulalla.'),
(1676321,58,9,9,13,'Kun tulette kaupunkiin, tapaatte hänet, ennenkuin hän menee uhrikukkulalle aterioimaan; sillä kansa ei aterioi, ennenkuin hän tulee. Kun hän on siunannut uhrin, sitten vasta kutsuvieraat aterioivat. Menkää siis sinne, sillä juuri nyt te hänet tapaatte."'),
(1676322,58,9,9,14,'Ja he menivät kaupunkiin. Kun he tulivat kaupunkiin, niin katso, Samuel tuli heitä vastaan menossa uhrikukkulalle.'),
(1676323,58,9,9,15,'Mutta päivää ennen Saulin tuloa oli Herra ilmoittanut ja sanonut Samuelille:'),
(1676324,58,9,9,16,'"Huomenna tähän aikaan minä lähetän sinun tykösi miehen Benjaminin maasta. Voitele hänet minun kansani Israelin ruhtinaaksi. Hän on vapauttava minun kansani filistealaisten käsistä. Sillä minä olen katsonut kansani puoleen, sen huuto on tullut minun eteeni."'),
(1676325,58,9,9,17,'Kun Samuel näki Saulin, ilmoitti Herra hänelle: "Katso, tässä on mies, josta minä olen sinulle sanonut: ''Tämä on vallitseva minun kansaani''".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676326,58,9,9,18,'Saul meni Samuelin tykö keskelle porttia ja sanoi: "Sano minulle, missä on näkijän asunto?"'),
(1676327,58,9,9,19,'Samuel vastasi Saulille ja sanoi: "Minä olen näkijä. Mene minun edelläni uhrikukkulalle. Aterioikaa tänä päivänä minun kanssani; huomenaamuna minä päästän sinut menemään, ja kaikki, mitä sinulla on sydämelläsi, minä selvitän sinulle.'),
(1676328,58,9,9,20,'Äläkä enää ole huolissasi aasintammoista, jotka ovat olleet sinulta kateissa kolme päivää, sillä ne ovat löytyneet. Ja kenen on kaikki, mitä kallisarvoisinta Israelissa on, jollei sinun ja kaiken sinun isäsi perheen?"'),
(1676329,58,9,9,21,'Saul vastasi ja sanoi: "Minähän olen benjaminilainen, olen sukukunnasta, joka on Israelin pienimpiä, ja minun sukuni on vähäisin kaikista Benjaminin sukukunnan suvuista. Miksi puhut minulle näin?"'),
(1676330,58,9,9,22,'Mutta Samuel otti Saulin palvelijoinensa ja vei heidät ruokailuhuoneeseen ja antoi heille ylimmän sijan kutsuvierasten joukossa, joita oli noin kolmekymmentä miestä.'),
(1676331,58,9,9,23,'Ja Samuel sanoi keittäjälle: "Tuo tänne se kappale, jonka minä sinulle annoin ja josta minä sinulle sanoin: ''Pane se syrjään''".'),
(1676332,58,9,9,24,'Niin keittäjä otti reiden, ja mitä siihen kuului, ja pani sen Saulin eteen. Ja Samuel sanoi: "Katso, tässä pannaan sinun eteesi se, mikä on varattu; syö siitä. Sillä juuri täksi hetkeksi se säästettiin sinua varten, kun minä sanoin: ''Minä olen kutsunut kansan''." Niin Saul aterioi Samuelin kanssa sinä päivänä.'),
(1676333,58,9,9,25,'Kun he sitten olivat tulleet uhrikukkulalta alas kaupunkiin, puhui hän Saulin kanssa katolla. Ja he nousivat varhain.'),
(1676334,58,9,9,26,'Niin Samuel aamun sarastaessa kutsui Saulia katolta ja sanoi: "Nouse, minä lähden saattamaan sinua". Saul nousi, ja hän ja Samuel menivät yhdessä ulos.'),
(1676335,58,9,9,27,'Kun he tulivat alas kaupungin laitaan, sanoi Samuel Saulille: "Sano palvelijalle, että hän menee meidän edellämme" - ja tämä meni edelle - "mutta pysähdy sinä hetkeksi tähän, niin minä julistan sinulle Jumalan sanan".'),
(1676336,58,9,10,1,'Silloin Samuel otti öljyastian, vuodatti öljyä hänen päähänsä, suuteli häntä ja sanoi: "Katso, Herra on voidellut sinut perintöosansa ruhtinaaksi.'),
(1676337,58,9,10,2,'Kun sinä tänä päivänä lähdet minun luotani, kohtaat sinä Raakelin haudan luona Selsahissa Benjaminin rajalla kaksi miestä; ne sanovat sinulle: ''Aasintammat, joita olet lähtenyt etsimään, ovat löytyneet; katso, isäsi on heittänyt mielestään aasintammat, kun on levoton teidän tähtenne ja sanoo: Mitä minä voisin tehdä poikani avuksi?'''),
(1676338,58,9,10,3,'Ja kun menet siitä edemmäksi ja tulet Taaborin tammelle, tulee siellä sinua vastaan kolme miestä menossa Jumalan eteen Beeteliin. Yksi kantaa kolmea vohlaa, toinen kantaa kolmea leipäkakkua, ja kolmas kantaa viinileiliä.'),
(1676339,58,9,10,4,'Ne tervehtivät sinua ja antavat sinulle kaksi leipää; ota ne heiltä.'),
(1676340,58,9,10,5,'Senjälkeen sinä tulet Jumalan Gibeaan, jossa filistealaisten maaherrat ovat. Ja tullessasi sinne kaupunkiin sinä kohtaat joukon profeettoja, jotka tulevat alas uhrikukkulalta hurmoksissaan, harppu, vaskirumpu, huilu ja kannel edellänsä.'),
(1676341,58,9,10,6,'Ja Herran henki tulee sinuun, ja sinäkin joudut hurmoksiin niinkuin hekin; ja sinä muutut toiseksi mieheksi.'),
(1676342,58,9,10,7,'Ja kun nämä ennusmerkit käyvät toteen, niin tee, mikä tehtäväksesi tulee, sillä Jumala on sinun kanssasi.'),
(1676343,58,9,10,8,'Mene sitten minun edelläni Gilgaliin, niin minä tulen sinne sinun luoksesi uhraamaan polttouhreja ja yhteysuhreja; odota seitsemän päivää, kunnes minä tulen sinun luoksesi ja ilmoitan sinulle, mitä sinun on tehtävä."'),
(1676344,58,9,10,9,'Ja kun hän käänsi selkänsä lähteäksensä Samuelin luota, muutti Jumala hänen sydämensä; ja kaikki nämä ennusmerkit kävivät sinä päivänä toteen.'),
(1676345,58,9,10,10,'Ja kun he tulivat sinne, Gibeaan, niin katso, joukko profeettoja tuli häntä vastaan. Silloin Jumalan henki tuli häneen, ja hänkin joutui hurmoksiin heidän keskellänsä.'),
(1676346,58,9,10,11,'Kun kaikki, jotka ennestään tunsivat hänet, näkivät hänet hurmoksissa niinkuin profeetatkin, sanoivat he toisillensa: "Mikä Kiisin pojalle on tullut? Onko Saulkin profeettain joukossa?"'),
(1676347,58,9,10,12,'Mutta eräs sikäläisistä miehistä vastasi ja sanoi: "Kuka sitten heidän isänsä on?" - Niin tuli sananlaskuksi: "Onko Saulkin profeettain joukossa?"'),
(1676348,58,9,10,13,'Päästyään hurmoksista hän meni uhrikukkulalle.'),
(1676349,58,9,10,14,'Ja Saulin setä kysyi häneltä ja hänen palvelijaltansa: "Missä te olette käyneet?" Hän vastasi: "Aasintammoja etsimässä. Mutta kun emme niitä missään nähneet, menimme Samuelin tykö."'),
(1676350,58,9,10,15,'Silloin Saulin setä sanoi: "Kerro minulle, mitä Samuel teille sanoi".'),
(1676351,58,9,10,16,'Saul vastasi sedällensä: "Hän ilmoitti meille aasintammain löytyneen". Mutta mitä Samuel oli sanonut kuninkuudesta, sitä hän ei hänelle kertonut.'),
(1676352,58,9,10,17,'Sitten Samuel kutsui kansan koolle Herran eteen Mispaan.'),
(1676353,58,9,10,18,'Hän sanoi israelilaisille: "Näin sanoo Herra, Israelin Jumala: Minä johdatin Israelin Egyptistä, ja minä vapautin teidät egyptiläisten käsistä sekä kaikkien niiden valtakuntien käsistä, jotka teitä sortivat.'),
(1676354,58,9,10,19,'Mutta nyt te olette pitäneet halpana Jumalanne, joka on auttanut teidät kaikista onnettomuuksistanne ja ahdingoistanne, ja olette sanoneet hänelle: ''Aseta meille kuningas''. Asettukaa siis Herran eteen sukukunnittain ja suvuittain."'),
(1676355,58,9,10,20,'Niin Samuel antoi kaikkien Israelin sukukuntien astua esiin; ja arpa osui Benjaminin sukukuntaan.'),
(1676356,58,9,10,21,'Kun hän sitten antoi Benjaminin sukukunnan astua esiin suvuittain, osui arpa Matrin sukuun; sen jälkeen osui arpa Sauliin, Kiisin poikaan. Mutta kun häntä etsittiin, ei häntä löydetty.'),
(1676357,58,9,10,22,'Silloin he kysyivät vielä kerran Herralta: "Onko ketään muuta vielä tullut tänne?" Herra vastasi: "Katso, hän on piiloutunut kuormastoon".'),
(1676358,58,9,10,23,'Niin he juoksivat ja toivat hänet sieltä, ja kun hän asettui kansan keskelle, niin hän oli päätänsä pitempi kaikkea kansaa.'),
(1676359,58,9,10,24,'Ja Samuel sanoi kaikelle kansalle: "Näettekö, kenen Herra on valinnut; sillä ei ole hänen vertaistansa koko kansan joukossa". Niin koko kansa riemuitsi huutaen: "Eläköön kuningas!"'),
(1676360,58,9,10,25,'Ja Samuel julisti kansalle kuninkuuden oikeudet, kirjoitti ne kirjaan ja asetti sen Herran eteen. Sitten Samuel päästi kaiken kansan menemään, kunkin kotiinsa.'),
(1676361,58,9,10,26,'Ja myöskin Saul meni kotiinsa Gibeaan, ja hänen kanssaan meni sotaväki, ne, joiden sydämiä Jumala oli koskettanut.'),
(1676362,58,9,10,27,'Mutta kelvottomat miehet sanoivat: "Mitä apua meille tästä on?" Ja nämä halveksivat häntä eivätkä tuoneet hänelle mitään lahjoja; mutta hän ei virkkanut mitään.'),
(1676363,58,9,11,1,'Ammonilainen Naahas lähti piirittämään Gileadin Jaabesta. Niin kaikki Jaabeksen miehet sanoivat Naahaalle: "Tee liitto meidän kanssamme, niin me palvelemme sinua".'),
(1676364,58,9,11,2,'Mutta ammonilainen Naahas vastasi heille: "Sillä ehdolla minä teen liiton teidän kanssanne, että saan puhkaista jokaiselta teiltä oikean silmän; niin minä häpäisen koko Israelin".'),
(1676365,58,9,11,3,'Jaabeksen vanhimmat sanoivat hänelle: "Jätä meidät rauhaan seitsemäksi päiväksi, niin me lähetämme sanansaattajia kaikkialle Israelin alueelle; jollei kukaan meitä auta, niin me antaudumme sinulle".'),
(1676366,58,9,11,4,'Niin sanansaattajat tulivat Saulin Gibeaan ja puhuivat asian kansalle. Silloin kaikki kansa korotti äänensä ja itki.'),
(1676367,58,9,11,5,'Ja katso, Saul tuli käyden härkäin jäljessä pellolta. Ja Saul kysyi: "Mikä kansalla on, kun he itkevät?" Niin he kertoivat hänelle Jaabeksen miesten asian.'),
(1676368,58,9,11,6,'Kun Saul kuuli tämän asian, tuli Jumalan henki häneen, ja hän vihastui kovin.'),
(1676369,58,9,11,7,'Ja hän otti härkäparin, paloitteli härät ja lähetti kappaleet kaikkialle Israelin alueelle sanansaattajain mukana ja käski sanoa: "Näin tehdään jokaisen härjille, joka ei seuraa Saulia ja Samuelia". Ja Herran kauhu valtasi kansan, niin että he lähtivät niinkuin yksi mies.'),
(1676370,58,9,11,8,'Ja hän piti katselmuksen heistä Besekissä; ja israelilaisia oli kolmesataa tuhatta ja Juudan miehiä kolmekymmentä tuhatta.'),
(1676371,58,9,11,9,'Ja he sanoivat sanansaattajille, jotka olivat tulleet: "Sanokaa näin Gileadin Jaabeksen miehille: ''Huomenna, auringon ollessa polttavimmillaan, te saatte apua''". Niin sanansaattajat tulivat ja ilmoittivat sen Jaabeksen miehille; ja nämä ilostuivat.'),
(1676372,58,9,11,10,'Niin Jaabeksen miehet sanoivat: "Huomenna me antaudumme teille, ja te saatte tehdä meille, mitä tahdotte".'),
(1676373,58,9,11,11,'Seuraavana päivänä Saul jakoi kansan kolmeen joukkoon; ja he tunkeutuivat leiriin aamuvartion aikana ja voittivat ammonilaiset, surmaten heitä, kunnes päivä tuli palavimmilleen. Ja jäljelle jääneet hajaantuivat, niin ettei heistä kahta yhteen jäänyt.'),
(1676374,58,9,11,12,'Silloin kansa sanoi Samuelille: "Ketkä ne olivat, jotka sanoivat: ''Saulko tulisi meidän kuninkaaksemme?'' Antakaa tänne ne miehet, surmataksemme heidät."'),
(1676375,58,9,11,13,'Mutta Saul sanoi: "Tänä päivänä ei ketään surmata, sillä tänä päivänä on Herra antanut voiton Israelille".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676376,58,9,11,14,'Ja Samuel sanoi kansalle: "Tulkaa, menkäämme Gilgaliin ja uudistakaamme siellä kuninkuus".'),
(1676377,58,9,11,15,'Niin kaikki kansa meni Gilgaliin ja teki Saulin kuninkaaksi siellä, Herran edessä Gilgalissa; ja he uhrasivat siellä yhteysuhreja Herran edessä. Ja Saul ja kaikki Israelin miehet iloitsivat siellä suuresti.'),
(1676378,58,9,12,1,'Samuel sanoi kaikelle Israelille: "Katso, minä olen kuullut teidän ääntänne kaikessa, mitä te olette minulta pyytäneet; minä olen asettanut kuninkaan teitä hallitsemaan.'),
(1676379,58,9,12,2,'Ja nyt on teidän kuninkaanne käyvä teidän edellänne, kun minä olen tullut vanhaksi ja harmaaksi - ovathan jo minun poikani teidän keskellänne. Mutta minä olen käynyt teidän edellänne nuoruudestani tähän päivään asti.'),
(1676380,58,9,12,3,'Tässä minä olen; todistakaa minua vastaan Herran ja hänen voideltunsa edessä. Keneltä minä olen vienyt härän tai keneltä aasin? Kenelle minä olen tehnyt vääryyttä, kenelle väkivaltaa? Keneltä minä olen lahjuksia ottanut ummistaakseni silmäni hänen hyväksensä? Todistakaa, niin minä korvaan sen teille."'),
(1676381,58,9,12,4,'He vastasivat: "Et ole tehnyt meille vääryyttä etkä väkivaltaa, et myös ole keneltäkään mitään ottanut".'),
(1676382,58,9,12,5,'Silloin hän sanoi heille: "Herra on todistaja teitä vastaan, ja hänen voideltunsa on todistaja tänä päivänä, että te ette ole löytäneet mitään minun kädestäni". He vastasivat: "Hän on todistaja".'),
(1676383,58,9,12,6,'Samuel sanoi kansalle: "Todistaja on Herra, joka kutsui Mooseksen ja Aaronin ja johdatti teidän isänne Egyptin maasta.'),
(1676384,58,9,12,7,'Astukaa nyt esiin, minä haastan teidät tuomiolle Herran edessä kaikista Herran vanhurskaista teoista, jotka hän on teille ja teidän isillenne tehnyt.'),
(1676385,58,9,12,8,'Kun Jaakob oli tullut Egyptiin, huusivat teidän isänne Herraa, ja Herra lähetti Mooseksen ja Aaronin viemään teidän isänne pois Egyptistä ja sijoittamaan heidät tähän paikkaan.'),
(1676386,58,9,12,9,'Mutta he unhottivat Herran, Jumalansa. Silloin hän myi heidät Siiseran, Haasorin sotapäällikön, käsiin ja filistealaisten käsiin ja Mooabin kuninkaan käsiin, ja nämä sotivat heitä vastaan.'),
(1676387,58,9,12,10,'Niin he huusivat Herraa ja sanoivat: ''Me olemme syntiä tehneet, kun hylkäsimme Herran ja palvelimme baaleja ja astarteja; mutta vapauta nyt meidät vihollistemme käsistä, niin me palvelemme sinua''.'),
(1676388,58,9,12,11,'Ja Herra lähetti Jerubbaalin, Bedanin, Jeftan ja Samuelin ja vapautti teidät ympärillä asuvain vihollistenne käsistä, niin että saitte asua turvassa.'),
(1676389,58,9,12,12,'Mutta kun te näitte Naahaan, ammonilaisten kuninkaan, hyökkäävän teitä vastaan, sanoitte te minulle: ''Ei, vaan kuningas hallitkoon meitä'', vaikka Herra, teidän Jumalanne, on kuninkaanne.'),
(1676390,58,9,12,13,'Tässä on nyt kuningas, jonka te valitsitte ja jota anoitte: katso, Herra on antanut teille kuninkaan.'),
(1676391,58,9,12,14,'Jos te pelkäätte Herraa ja palvelette häntä, kuulette hänen ääntänsä ettekä niskoittele hänen käskyjänsä vastaan, niin te seuraatte Herraa, Jumalaanne, sekä te että kuningas, joka teitä hallitsee.'),
(1676392,58,9,12,15,'Mutta jollette kuule Herran ääntä, vaan niskoittelette hänen käskyjänsä vastaan, niin Herran käsi on oleva teitä vastaan, niinkuin oli myös teidän isiänne vastaan.'),
(1676393,58,9,12,16,'Astukaa nyt esiin ja katsokaa tätä suurta tekoa, jonka Herra tekee teidän silmienne edessä.'),
(1676394,58,9,12,17,'Nythän on nisunleikkuun aika; mutta minä huudan Herraa, että hän antaa ukkosenjylinän ja sateen, että ymmärtäisitte ja näkisitte, kuinka paha Herran silmissä on se, minkä olette tehneet anoessanne itsellenne kuningasta."'),
(1676395,58,9,12,18,'Ja Samuel huusi Herraa, ja Herra antoi ukkosenjylinän ja sateen sinä päivänä. Ja kaikki kansa pelkäsi suuresti Herraa ja Samuelia.'),
(1676396,58,9,12,19,'Ja kaikki kansa sanoi Samuelille: "Rukoile palvelijaisi puolesta Herraa, Jumalaasi, ettemme kuolisi; sillä me olemme tehneet kaikkien muiden syntiemme lisäksi senkin pahan, että anoimme itsellemme kuningasta".'),
(1676397,58,9,12,20,'Samuel sanoi kansalle: "Älkää peljätkö. Te olette tosin tehneet kaiken tämän pahan, mutta älkää kuitenkaan poiketko pois seuraamasta Herraa, vaan palvelkaa Herraa kaikesta sydämestänne.'),
(1676398,58,9,12,21,'Älkää poiketko seuraamaan turhia jumalia, joista ei ole hyötyä eikä apua, sillä turhia ne ovat.'),
(1676399,58,9,12,22,'Suuren nimensä tähden Herra ei hylkää kansaansa, koska Herra on tahtonut tehdä teidät omaksi kansaksensa.'),
(1676400,58,9,12,23,'Ja pois se minusta, että tekisin sen synnin Herraa vastaan, että lakkaisin rukoilemasta teidän puolestanne ja opettamasta teille hyvää ja oikeata tietä.'),
(1676401,58,9,12,24,'Peljätkää vain Herraa ja palvelkaa häntä uskollisesti kaikesta sydämestänne. Sillä katsokaa, kuinka suuria hän on teille tehnyt.'),
(1676402,58,9,12,25,'Mutta jos teette pahaa, niin hukutte, sekä te itse että teidän kuninkaanne."'),
(1676403,58,9,13,1,'Saul oli ollut vuoden kuninkaana ja hallitsi Israelia toista vuotta,'),
(1676404,58,9,13,2,'kun Saul valitsi itsellensä kolmetuhatta miestä Israelista, ja näistä oli kaksituhatta Saulin kanssa Mikmaassa ja Beetelin vuoristossa, ja tuhat Joonatanin kanssa Benjaminin Gibeassa. Mutta muun väen hän oli päästänyt menemään, kunkin majallensa.'),
(1676405,58,9,13,3,'Mutta Joonatan, Saulin poika, löi kuoliaaksi filistealaisten maaherran, joka asui Gebassa, ja filistealaiset saivat sen kuulla. Silloin Saul puhallutti pasunaan kaikkialla maassa ja käski sanoa: "Hebrealaiset kuulkoot tämän".'),
(1676406,58,9,13,4,'Ja koko Israel kuuli sen sanoman, että Saul oli lyönyt kuoliaaksi filistealaisten maaherran ja että Israel oli joutunut filistealaisten vihoihin. Niin kansa kutsuttiin koolle Gilgaliin, seuraamaan Saulia.'),
(1676407,58,9,13,5,'Sillä filistealaiset olivat kokoontuneet sotimaan Israelia vastaan: kolmetkymmenet tuhannet sotavaunut, kuusituhatta ratsumiestä ja muuta väkeä niin paljon kuin hiekkaa meren rannalla; ja he tulivat ylös ja leiriytyivät Mikmaaseen, vastapäätä Beet-Aavenia.'),
(1676408,58,9,13,6,'Kun Israelin miehet näkivät joutuneensa hätään ja kansaa ahdistettavan, piiloutuivat he luoliin, onkaloihin, kallionrotkoihin, hautoihin ja kaivoihin.'),
(1676409,58,9,13,7,'Hebrealaisia meni myös Jordanin yli Gaadiin ja Gileadin maahan. Mutta Saul oli vielä Gilgalissa, ja kaikki sotaväki seurasi häntä peloissaan.'),
(1676410,58,9,13,8,'Kun hän oli odottanut seitsemän päivää, sen ajan, jonka Samuel oli määrännyt, eikä Samuel tullutkaan Gilgaliin, alkoi kansa hajaantua pois hänen luotaan.'),
(1676411,58,9,13,9,'Silloin Saul sanoi: "Tuokaa minulle polttouhri ja yhteysuhri". Ja hän uhrasi polttouhrin.'),
(1676412,58,9,13,10,'Mutta juuri kun hän oli saanut polttouhrin uhratuksi, niin katso, Samuel tuli. Ja Saul meni häntä vastaan tervehtimään häntä.'),
(1676413,58,9,13,11,'Mutta Samuel sanoi: "Mitä olet tehnyt?" Saul vastasi: "Kun näin, että kansa hajaantui pois minun luotani etkä sinä tullut määrättynä aikana, vaikka filistealaiset olivat kokoontuneet Mikmaaseen,'),
(1676414,58,9,13,12,'niin minä ajattelin: nyt filistealaiset hyökkäävät minua vastaan alas Gilgaliin, enkä minä ole etsinyt Herran mielisuosiota; ja minä rohkaisin itseni ja uhrasin polttouhrin".'),
(1676415,58,9,13,13,'Samuel sanoi Saulille: "Sinä olet tehnyt tyhmästi. Et ole noudattanut Herran, Jumalasi, käskyä, jonka hän antoi sinulle; muutoin olisi Herra vahvistanut sinun kuninkuutesi Israelissa ikuisiksi ajoiksi.'),
(1676416,58,9,13,14,'Mutta nyt sinun kuninkuutesi ei ole pysyvä. Herra on etsinyt itselleen mielensä mukaisen miehen, ja hänet on Herra määrännyt kansansa ruhtinaaksi, koska sinä et noudattanut käskyä, minkä Herra sinulle antoi."'),
(1676417,58,9,13,15,'Sitten Samuel nousi ja meni Gilgalista Benjaminin Gibeaan. Ja Saul piti mukanansa olevan väen katselmuksen: noin kuusisataa miestä.'),
(1676418,58,9,13,16,'Ja Saul ja hänen poikansa Joonatan ynnä väki, joka oli heidän kanssansa, jäivät Benjaminin Gebaan, mutta filistealaiset olivat leiriytyneet Mikmaaseen.'),
(1676419,58,9,13,17,'Ja filistealaisten leiristä lähti ryöstöosasto kolmena joukkona: yksi joukko kääntyi Ofran tielle Suualin maahan päin,'),
(1676420,58,9,13,18,'toinen joukko kääntyi Beet-Hooronin tielle, ja kolmas joukko kääntyi sille tielle, joka vie Seboimin laakson yli kohoavalle alueelle, erämaahan päin.'),
(1676421,58,9,13,19,'Mutta ei yhtään seppää ollut löydettävissä koko Israelin maasta, sillä filistealaiset ajattelivat, että hebrealaiset muutoin teettäisivät miekkoja tai keihäitä.'),
(1676422,58,9,13,20,'Ja koko Israelin, joka miehen, oli mentävä filistealaisten luo teroituttamaan vannastansa, kuokkaansa, kirvestänsä tai muuta teräkaluansa,'),
(1676423,58,9,13,21,'kun vannasten, kuokkien, tadikkojen tai kirvesten terät olivat tylsyneet, tahi kun häränpistimen tutkain oli oikaistava.'),
(1676424,58,9,13,22,'Niinpä ei taistelupäivänä ollut yhtään miekkaa eikä keihästä kenelläkään siitä väestä, joka oli Saulin ja Joonatanin kanssa; ainoastaan Saulilla ja hänen pojallansa Joonatanilla oli.'),
(1676425,58,9,13,23,'Mutta filistealaisten vartiosto lähti Mikmaan solatielle.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676426,58,9,14,1,'Ja tapahtui eräänä päivänä, että Joonatan, Saulin poika, sanoi palvelijalle, joka kantoi hänen aseitansa: "Tule, menkäämme lähelle filistealaisten vartiostoa, joka on tuolla toisella puolella". Mutta hän ei ilmoittanut sitä isällensä.'),
(1676427,58,9,14,2,'Saul istui silloin granaattiomenapuun juurella Migronissa Gibean rajalla, ja väkeä oli hänellä kanssansa noin kuusisataa miestä.'),
(1676428,58,9,14,3,'Ja kasukankantajana oli Ahia, Ahitubin, Iikabodin veljen, poika, joka oli Piinehaan poika, joka Eelin poika, sen, joka oli ollut Herran pappina Siilossa. Mutta kansa ei tiennyt, että Joonatan oli lähtenyt.'),
(1676429,58,9,14,4,'Mutta kummallakin puolen solatietä, jota Joonatan koetti mennä lähelle filistealaisten vartiostoa, oli jyrkkä kallionkieleke; toisen nimi on Booses, toisen Sene.'),
(1676430,58,9,14,5,'Toinen kallionkieleke on kuin pylväs, pohjoisen puolella, Mikmaaseen päin, toinen on etelän puolella, Gebaan päin.'),
(1676431,58,9,14,6,'Ja Joonatan sanoi palvelijalle, joka kantoi hänen aseitansa: "Tule, menkäämme lähelle noiden ympärileikkaamattomain vartiostoa; ehkä Herra on tekevä jotakin meidän puolestamme, sillä ei mikään estä Herraa antamasta voittoa harvojen kautta yhtä hyvin kuin monien".'),
(1676432,58,9,14,7,'Hänen aseenkantajansa vastasi hänelle: "Tee, mitä mielessäsi on. Lähde, minä seuraan sinua mielesi mukaan."'),
(1676433,58,9,14,8,'Niin Joonatan sanoi: "Katso, me menemme tuonne, lähelle noita miehiä, ja näyttäydymme heille.'),
(1676434,58,9,14,9,'Jos he sanovat meille näin: ''Olkaa hiljaa, kunnes me tulemme teidän luoksenne'', niin me seisomme alallamme emmekä lähde nousemaan heidän luoksensa.'),
(1676435,58,9,14,10,'Mutta jos he sanovat näin: ''Nouskaa tänne meidän luoksemme'', niin me nousemme, sillä silloin Herra on antanut heidät meidän käsiimme; tämä olkoon meillä merkkinä."'),
(1676436,58,9,14,11,'Kun he sitten molemmat tulivat filistealaisten vartioston näkyviin, sanoivat filistealaiset: "Katso, hebrealaiset tulevat esiin koloistansa, joihin ovat piiloutuneet".'),
(1676437,58,9,14,12,'Ja vartioston miehet huusivat Joonatanille ja hänen aseenkantajalleen ja sanoivat: "Nouskaa tänne meidän luoksemme, niin me ilmoitamme teille jotakin". Silloin sanoi Joonatan aseenkantajallensa: "Nouse minun perässäni, sillä Herra on antanut heidät Israelin käsiin".'),
(1676438,58,9,14,13,'Ja Joonatan kiipesi käsin ja jaloin ylöspäin, ja aseenkantaja hänen perässään. Ja he kaatuivat Joonatanin edessä, ja aseenkantaja löi heidät kuoliaaksi hänen jäljessänsä.'),
(1676439,58,9,14,14,'Tässä ensimmäisessä kahakassa surmasivat Joonatan ja hänen aseenkantajansa noin kaksikymmentä miestä, noin puolen auranalan suuruisella maa-alalla.'),
(1676440,58,9,14,15,'Silloin syntyi kauhu leirissä ja sen ulkopuolella, koko sotaväessä; myös vartiosto ja ryöstöosasto joutuivat kauhun valtaan. Maakin järisi, ja niin syntyi Jumalan kauhu.'),
(1676441,58,9,14,16,'Ja Saulin tähystäjät Benjaminin Gibeassa huomasivat lauman hajoavan ja menevän sinne tänne.'),
(1676442,58,9,14,17,'Niin Saul sanoi väelle, joka oli hänen kanssansa: "Pitäkää katselmus ja katsokaa, kuka on mennyt pois meidän luotamme". Ja kun katselmus pidettiin, huomattiin, etteivät Joonatan ja hänen aseenkantajansa olleet läsnä.'),
(1676443,58,9,14,18,'Ja Saul sanoi Ahialle: "Tuo tänne Jumalan arkki". Sillä Jumalan arkki oli siihen aikaan israelilaisten hallussa.'),
(1676444,58,9,14,19,'Mutta Saulin vielä puhutellessa pappia kävi meteli filistealaisten leirissä yhä suuremmaksi. Niin Saul sanoi papille: "Jätä sikseen".'),
(1676445,58,9,14,20,'Silloin Saul kutsutti koolle kaiken väen, joka oli hänen kanssaan, ja he tulivat taistelupaikalle, ja katso, toisen miekka oli toista vastaan, ja oli mitä suurin hämminki.'),
(1676446,58,9,14,21,'Myös ne hebrealaiset, jotka ennestään olivat filistealaisten vallassa ja jotka olivat tulleet heidän kanssaan ja olivat leirissä, menivät niiden israelilaisten puolelle, jotka olivat Saulin ja Joonatanin kanssa.'),
(1676447,58,9,14,22,'Ja kun ne Israelin miehet, jotka olivat piiloutuneet Efraimin vuoristoon, kuulivat filistealaisten pakenevan, yhtyivät hekin kaikki ajamaan heitä takaa taistelussa.'),
(1676448,58,9,14,23,'Niin Herra antoi Israelille voiton sinä päivänä, ja taistelu levisi Beet-Aavenin toiselle puolelle.'),
(1676449,58,9,14,24,'Israelin miehet olivat sinä päivänä ylen rasitetut, mutta Saul vannotti kansan ja sanoi: "Kirottu olkoon se mies, joka syö mitään ennen iltaa ja ennen kuin minä olen kostanut vihollisilleni". Ja koko kansa oli ruokaa maistamatta.'),
(1676450,58,9,14,25,'Ja kun he kaikki tulivat metsään, oli maassa hunajata.'),
(1676451,58,9,14,26,'Kun kansa tuli kennokakkujen ääreen, niin katso, niistä vuoti hunajata, mutta ei kukaan vienyt kättään suuhun, sillä kansa pelkäsi valaa.'),
(1676452,58,9,14,27,'Mutta Joonatan ei ollut kuulemassa, kun hänen isänsä vannotti kansan; niin hän ojensi sauvan, joka oli hänen kädessään, pisti sen kärjen kennokakkuun ja vei sitten kätensä suuhunsa, ja silloin hänen silmänsä kirkastuivat.'),
(1676453,58,9,14,28,'Mutta eräs mies väestä puhkesi puhumaan ja sanoi: "Sinun isäsi vannotti väen ja sanoi: ''Kirottu olkoon se mies, joka tänä päivänä syö mitään''". Ja väki oli näännyksissä.'),
(1676454,58,9,14,29,'Joonatan vastasi: "Isäni on syössyt maan onnettomuuteen. Katsokaa, kuinka minun silmäni kirkastuivat, kun vähän maistoin tätä hunajata.'),
(1676455,58,9,14,30,'Jos myös väki olisi tänä päivänä saanut syödä vihollisiltaan ottamaansa saalista, niin eiköhän filistealaisten tappio olisi ollut vieläkin suurempi?"'),
(1676456,58,9,14,31,'Ja he voittivat sinä päivänä filistealaiset ja ajoivat heitä takaa Mikmaasta Aijaloniin asti; ja väki oli kovin näännyksissä.'),
(1676457,58,9,14,32,'Sentähden väki syöksyi saaliin kimppuun ja otti lampaita, raavaita ja vasikoita ja teurasti niitä paljaan maan päällä; ja väki söi lihan verinensä.'),
(1676458,58,9,14,33,'Niin Saulille ilmoitettiin tämä: "Katso, väki tekee syntiä Herraa vastaan, kun syö lihaa verinensä". Hän sanoi: "Te olette menetelleet uskottomasti; vierittäkää nyt tänne minun eteeni suuri kivi".'),
(1676459,58,9,14,34,'Ja Saul sanoi: "Menkää väen sekaan ja sanokaa heille: ''Tuokaa jokainen härkänne ja lampaanne minun luokseni ja teurastakaa ne täällä. Sitten syökää; älkääkä tehkö syntiä Herraa vastaan syömällä lihaa verinensä.''" Niin väestä jokainen silloin yöllä toi omin käsin härkänsä ja teurasti sen siellä.'),
(1676460,58,9,14,35,'Ja Saul rakensi alttarin Herralle; tämä oli ensimmäinen alttari, jonka hän Herralle rakensi.'),
(1676461,58,9,14,36,'Ja Saul sanoi: "Lähtekäämme tänä yönä filistealaisten jälkeen ja ryöstäkäämme heitä, kunnes aamu valkenee, ja älkäämme jättäkö heistä jäljelle ainoatakaan". He vastasivat: "Tee kaikki, mitä hyväksi näet". Mutta pappi sanoi: "Astukaamme tänne Jumalan eteen".'),
(1676462,58,9,14,37,'Silloin Saul kysyi Jumalalta: "Lähdenkö minä filistealaisten jälkeen? Annatko sinä heidät Israelin käsiin?" Mutta hän ei vastannut hänelle sinä päivänä.'),
(1676463,58,9,14,38,'Niin Saul sanoi: "Tulkaa tänne, kaikki kansan päämiehet, saadaksenne tietää ja nähdä, mikä synti nyt on tähän syynä.'),
(1676464,58,9,14,39,'Sillä niin totta kuin Herra elää, hän, joka on antanut Israelille voiton: vaikka syy olisi minun poikani Joonatanin, niin hänen on kuoltava." Mutta ei kukaan koko kansasta vastannut hänelle.'),
(1676465,58,9,14,40,'Silloin hän sanoi koko Israelille: "Olkaa te toisella puolella, niin minä ja minun poikani Joonatan olemme toisella puolella". Kansa vastasi Saulille: "Tee, niinkuin hyväksi näet".'),
(1676466,58,9,14,41,'Ja Saul sanoi Herralle, Israelin Jumalalle: "Anna oikea arpa". Niin arpa osui Joonataniin ja Sauliin, ja kansa pääsi vapaaksi.'),
(1676467,58,9,14,42,'Saul sanoi: "Heittäkää arpaa minun ja minun poikani Joonatanin välillä". Niin arpa osui Joonataniin.'),
(1676468,58,9,14,43,'Ja Saul sanoi Joonatanille: "Ilmaise minulle, mitä olet tehnyt". Joonatan ilmaisi sen hänelle ja sanoi: "Minä maistoin vähän hunajata sauvan kärjellä, joka oli kädessäni; katso, minä olen valmis kuolemaan".'),
(1676469,58,9,14,44,'Ja Saul sanoi: "Jumala rangaiskoon minua nyt ja vasta: sinun on kuolemalla kuoltava, Joonatan".'),
(1676470,58,9,14,45,'Mutta kansa sanoi Saulille: "Onko Joonatanin kuoltava, hänen, joka on hankkinut tämän suuren voiton Israelille? Pois se! Niin totta kuin Herra elää: ei saa hiuskarvakaan pudota maahan hänen päästänsä; sillä Jumalan avulla hän on sen tänä päivänä tehnyt." Näin kansa vapahti Joonatanin kuolemasta.'),
(1676471,58,9,14,46,'Sitten Saul meni eikä ajanut filistealaisia takaa; ja filistealaiset menivät kotiinsa.'),
(1676472,58,9,14,47,'Kun nyt Saul oli saanut kuninkuuden Israelissa, soti hän kaikkia vihollisiansa vastaan joka taholla: mooabilaisia, ammonilaisia, edomilaisia, Sooban kuninkaita ja filistealaisia vastaan; ja minne tahansa hän kääntyi, siellä hän rankaisi.'),
(1676473,58,9,14,48,'Ja hän teki väkeviä tekoja ja voitti amalekilaiset ja vapautti Israelin sen ryöstäjäin käsistä.'),
(1676474,58,9,14,49,'Saulin pojat olivat Joonatan, Jisvi ja Malkisua; ja hänen kahden tyttärensä nimet olivat: vanhemman nimi Meerab ja nuoremman nimi Miikal.'),
(1676475,58,9,14,50,'Ja Saulin vaimon nimi oli Ahinoam, Ahimaan tytär. Ja hänen sotapäällikkönsä nimi oli Abner, Neerin, Saulin sedän, poika.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676476,58,9,14,51,'Sillä Kiis, Saulin isä, ja Neer, Abnerin isä, olivat Abielin poikia.'),
(1676477,58,9,14,52,'Mutta filistealaisia vastaan käytiin kiivaasti sotaa, niin kauan kuin Saul eli. Ja kenen vain Saul tapasi urhoollisen ja sotakuntoisen miehen, sen hän otti luoksensa.'),
(1676478,58,9,15,1,'Mutta Samuel sanoi Saulille: "Minut Herra lähetti voitelemaan sinut kansansa Israelin kuninkaaksi. Kuule siis Herran ääntä.'),
(1676479,58,9,15,2,'Näin sanoo Herra Sebaot: Minä kostan Amalekille sen, mitä hän teki Israelille asettumalla hänen tielleen, kun hän tuli Egyptistä.'),
(1676480,58,9,15,3,'Mene siis ja voita amalekilaiset, ja vihkikää tuhon omaksi kaikki, mitä heillä on; äläkä säästä heitä, vaan surmaa miehet ja naiset, lapset ja imeväiset, raavaat ja lampaat, kamelit ja aasit."'),
(1676481,58,9,15,4,'Saul kuulutti kansan kokoon ja piti heistä katselmuksen Telaimissa: kaksisataa tuhatta jalkamiestä ynnä kymmenentuhatta Juudan miestä.'),
(1676482,58,9,15,5,'Kun Saul tuli lähelle amalekilaisten kaupunkia, asettui hän laaksoon väijyksiin.'),
(1676483,58,9,15,6,'Ja Saul sanoi keeniläisille: "Tulkaa, erotkaa ja siirtykää pois amalekilaisten joukosta, etten minä hukuttaisi teitä heidän kanssansa; sillä te teitte laupeuden kaikille israelilaisille, kun he tulivat Egyptistä". Niin keeniläiset erosivat amalekilaisista.'),
(1676484,58,9,15,7,'Ja Saul voitti amalekilaiset ja ajoi heitä takaa Havilasta Suuriin päin, joka on Egyptistä itään päin.'),
(1676485,58,9,15,8,'Ja hän otti Agagin, Amalekin kuninkaan, elävänä vangiksi, mutta kaiken kansan hän vihki tuhon omaksi miekan terällä.'),
(1676486,58,9,15,9,'Mutta Saul ja väki säästivät Agagin sekä parhaimmat lampaat, lihavimmat raavaat ja karitsat, kaiken, mikä oli arvokasta; sitä he eivät tahtoneet vihkiä tuhon omaksi. Mutta kaiken karjan, mikä oli halpaa ja arvotonta, he vihkivät tuhon omaksi.'),
(1676487,58,9,15,10,'Silloin Samuelille tuli tämä Herran sana:'),
(1676488,58,9,15,11,'"Minä kadun, että tein Saulin kuninkaaksi, sillä hän on kääntynyt pois minusta eikä ole täyttänyt minun käskyjäni". Samuel pahastui, ja hän huusi Herraa kaiken sen yön.'),
(1676489,58,9,15,12,'Varhain seuraavana aamuna Samuel lähti tapaamaan Saulia. Mutta Samuelille ilmoitettiin: "Saul on mennyt Karmeliin ja pystyttänyt sinne itsellensä muistomerkin; sitten hän on palannut sieltä ja mennyt alas Gilgaliin".'),
(1676490,58,9,15,13,'Kun Samuel tuli Saulin luo, sanoi Saul hänelle: "Herra siunatkoon sinua! Minä olen täyttänyt Herran käskyn."'),
(1676491,58,9,15,14,'Mutta Samuel sanoi: "Mitä tämä lammasten määkiminen sitten on, joka kuuluu minun korviini, ja tämä raavaiden ammuminen, jonka kuulen?"'),
(1676492,58,9,15,15,'Saul vastasi: "Amalekilaisilta ne on tuotu; sillä kansa säästi parhaat lampaat ja raavaat uhrataksensa ne Herralle, sinun Jumalallesi; mutta muut me olemme vihkineet tuhon omiksi".'),
(1676493,58,9,15,16,'Silloin Samuel sanoi Saulille: "Lopeta; minä ilmoitan sinulle, mitä Herra on minulle tänä yönä puhunut". Hän sanoi hänelle: "Puhu".'),
(1676494,58,9,15,17,'Samuel sanoi: "Sinä olet Israelin sukukuntien päämies, vaikka oletkin vähäinen omissa silmissäsi: Herra on voidellut sinut Israelin kuninkaaksi.'),
(1676495,58,9,15,18,'Ja Herra lähetti sinut matkaan ja sanoi: ''Mene ja vihi tuhon omiksi nämä syntiset, amalekilaiset, ja sodi heitä vastaan, kunnes olet tehnyt heistä lopun''.'),
(1676496,58,9,15,19,'Miksi et kuullut Herran ääntä, vaan syöksyit saaliin kimppuun ja teit sitä, mikä on pahaa Herran silmissä?"'),
(1676497,58,9,15,20,'Saul vastasi Samuelille: "Minähän olen kuullut Herran ääntä ja tehnyt sen matkan, jolle Herra minut lähetti. Minä olen tuonut tänne Agagin, Amalekin kuninkaan, ja vihkinyt tuhon omiksi amalekilaiset.'),
(1676498,58,9,15,21,'Mutta väki on ottanut saaliista lampaita ja raavaita, parhaan osan siitä, mikä oli vihitty tuhon omaksi, uhrataksensa ne Herralle, sinun Jumalallesi, Gilgalissa."'),
(1676499,58,9,15,22,'Silloin Samuel sanoi: "Haluaako Herra polttouhreja ja teurasuhreja yhtä hyvin kuin kuuliaisuutta Herran äänelle? Katso, kuuliaisuus on parempi kuin uhri ja tottelevaisuus parempi kuin oinasten rasva.'),
(1676500,58,9,15,23,'Sillä tottelemattomuus on taikuuden syntiä, ja niskoittelu on valhetta ja kuin kotijumalain palvelusta. Koska sinä olet hyljännyt Herran sanan, on myös hän hyljännyt sinut, etkä sinä enää saa olla kuninkaana."'),
(1676501,58,9,15,24,'Saul sanoi Samuelille: "Minä olen tehnyt syntiä, kun olen rikkonut Herran käskyn ja sinun sanasi; sillä minä pelkäsin kansaa ja kuulin heidän ääntänsä.'),
(1676502,58,9,15,25,'Anna nyt minulle syntini anteeksi ja palaja minun kanssani, niin minä kumartaen rukoilen Herraa."'),
(1676503,58,9,15,26,'Samuel sanoi Saulille: "Minä en palaja sinun kanssasi; sillä sinä olet hyljännyt Herran sanan, ja Herra on myös hyljännyt sinut, niin että et enää saa olla Israelin kuninkaana".'),
(1676504,58,9,15,27,'Kun sitten Samuel kääntyi menemään pois, tarttui Saul hänen viittansa liepeeseen, niin että se repesi.'),
(1676505,58,9,15,28,'Ja Samuel sanoi hänelle: "Herra on tänä päivänä reväissyt Israelin kuninkuuden sinulta ja antanut sen toiselle, joka on sinua parempi.'),
(1676506,58,9,15,29,'Ja hän, joka on Israelin kunnia, ei valhettele eikä kadu; sillä hän ei ole ihminen, että hän katuisi."'),
(1676507,58,9,15,30,'Hän vastasi: "Minä olen syntiä tehnyt; mutta osoita minulle kuitenkin se kunnia kansani vanhimpien edessä ja Israelin edessä, että palajat minun kanssani, niin minä kumartaen rukoilisin Herraa, sinun Jumalaasi".'),
(1676508,58,9,15,31,'Niin Samuel palasi Saulin jäljessä; ja Saul kumartaen rukoili Herraa.'),
(1676509,58,9,15,32,'Ja Samuel sanoi: "Tuokaa minun eteeni Agag, Amalekin kuningas". Ja Agag tuli iloisesti hänen eteensä; ja Agag sanoi: "Totisesti on katkera kuolema väistynyt pois".'),
(1676510,58,9,15,33,'Mutta Samuel sanoi: "Niinkuin sinun miekkasi on tehnyt vaimoja lapsettomiksi, niin on myös sinun äitisi tuleva lapsettomaksi ennen muita vaimoja". Ja Samuel hakkasi Agagin kappaleiksi Herran edessä Gilgalissa.'),
(1676511,58,9,15,34,'Sitten Samuel lähti Raamaan, mutta Saul meni kotiinsa Saulin Gibeaan.'),
(1676512,58,9,15,35,'Eikä Samuel enää nähnyt Saulia kuolinpäiväänsä asti, ja Samuel suri Saulia. Mutta Herra katui, että oli tehnyt Saulin Israelin kuninkaaksi.'),
(1676513,58,9,16,1,'Ja Herra sanoi Samuelille: "Kuinka kauan sinä suret Saulia? Minähän olen hyljännyt hänet, niin ettei hän enää saa olla Israelin kuninkaana. Täytä sarvesi öljyllä ja mene; minä lähetän sinut beetlehemiläisen Iisain luo, sillä hänen pojistansa minä olen katsonut itselleni kuninkaan."'),
(1676514,58,9,16,2,'Mutta Samuel sanoi: "Kuinka minä voisin mennä sinne? Jos Saul saa sen kuulla, tappaa hän minut." Herra vastasi: "Ota mukaasi vasikka ja sano: ''Minä tulin uhraamaan Herralle''.'),
(1676515,58,9,16,3,'Kutsu sitten Iisai uhrille, niin minä ilmoitan sinulle, mitä sinun on tehtävä; ja voitele minulle se, jonka minä sinulle osoitan."'),
(1676516,58,9,16,4,'Samuel teki, niinkuin Herra oli puhunut. Mutta kun hän tuli Beetlehemiin, tulivat kaupungin vanhimmat vavisten häntä vastaan ja kysyivät: "Tietääkö tulosi rauhaa?"'),
(1676517,58,9,16,5,'Hän vastasi: "Rauhaa. Minä olen tullut uhraamaan Herralle. Pyhittäytykää ja tulkaa minun kanssani uhrille." Ja hän pyhitti Iisain ja hänen poikansa ja kutsui heidät uhrille.'),
(1676518,58,9,16,6,'Kun he sitten tulivat ja hän näki Eliabin, ajatteli hän: "Varmaan on nyt tässä Herran edessä hänen voideltunsa".'),
(1676519,58,9,16,7,'Mutta Herra sanoi Samuelille: "Älä katso hänen näköänsä äläkä kookasta vartaloansa, sillä minä olen hänet hyljännyt. Sillä ei ole, niinkuin ihminen näkee: ihminen näkee ulkomuodon, mutta Herra näkee sydämen."'),
(1676520,58,9,16,8,'Niin Iisai kutsui Abinadabin ja toi hänet Samuelin eteen. Mutta hän sanoi: "Ei ole Herra tätäkään valinnut".'),
(1676521,58,9,16,9,'Silloin Iisai toi Samman esille. Mutta hän sanoi: "Ei ole Herra tätäkään valinnut".'),
(1676522,58,9,16,10,'Niin toi Iisai seitsemän poikaansa Samuelin eteen. Mutta Samuel sanoi Iisaille: "Herra ei ole valinnut ketään näistä".'),
(1676523,58,9,16,11,'Ja Samuel kysyi Iisailta: "Siinäkö olivat kaikki nuorukaiset?" Hän vastasi: "Vielä on nuorin jäljellä, mutta hän on kaitsemassa lampaita". Niin Samuel sanoi Iisaille: "Lähetä noutamaan hänet, sillä me emme istu ruualle, ennenkuin hän tulee tänne".'),
(1676524,58,9,16,12,'Silloin tämä noudatti hänet; ja hän oli verevä, kaunissilmäinen ja sorea nähdä. Ja Herra sanoi: "Nouse ja voitele tämä, sillä hän se on".'),
(1676525,58,9,16,13,'Niin Samuel otti öljysarven ja voiteli hänet hänen veljiensä keskellä. Ja Herran henki tuli Daavidiin, siitä päivästä ja yhä edelleen. Sitten Samuel nousi ja meni Raamaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676526,58,9,16,14,'Mutta Herran henki poistui Saulista, ja Herran lähettämä paha henki vaivasi häntä.'),
(1676527,58,9,16,15,'Niin Saulin palvelijat sanoivat hänelle: "Katso, Jumalan lähettämä paha henki vaivaa sinua.'),
(1676528,58,9,16,16,'Käskeköön vain herramme, niin palvelijasi, jotka ovat edessäsi, etsivät miehen, joka taitaa soittaa kannelta, että hän, kun Jumalan lähettämä paha henki tulee sinuun, soittaisi sitä, ja sinun olisi parempi olla."'),
(1676529,58,9,16,17,'Silloin Saul sanoi palvelijoillensa: "Katsokaa minulle mies, joka on taitava soittaja, ja tuokaa hänet minun luokseni".'),
(1676530,58,9,16,18,'Niin eräs nuorista miehistä vastasi ja sanoi: "Katso, minä olen nähnyt beetlehemiläisellä Iisailla pojan, joka taitaa soittaa ja joka on kelpo mies ja sotilas sekä ymmärtäväinen puheiltaan ja komea mies, ja Herra on hänen kanssaan".'),
(1676531,58,9,16,19,'Niin Saul lähetti sanansaattajat Iisain luo ja käski sanoa: "Lähetä minun luokseni poikasi Daavid, joka kaitsee lampaita".'),
(1676532,58,9,16,20,'Ja Iisai otti aasin sekä leipää, viinileilin ja vohlan ja lähetti ne poikansa Daavidin mukana Saulille.'),
(1676533,58,9,16,21,'Ja Daavid tuli Saulin luo ja rupesi palvelemaan häntä; ja hän tuli hänelle hyvin rakkaaksi ja pääsi hänen aseenkantajakseen.'),
(1676534,58,9,16,22,'Ja Saul lähetti sanan Iisaille ja käski sanoa: "Anna Daavidin jäädä minua palvelemaan, sillä hän on saanut armon minun silmieni edessä".'),
(1676535,58,9,16,23,'Niin usein kuin Jumalan lähettämä henki tuli Sauliin, otti Daavid kanteleen ja soitti sitä; silloin Saulin oli helpompi ja parempi olla, ja paha henki väistyi hänestä.'),
(1676536,58,9,17,1,'Mutta filistealaiset kokosivat joukkonsa sotaan, ja he kokoontuivat lähelle Sookoa, joka on Juudassa. Ja he leiriytyivät Sookon ja Asekan välille, Efes-Dammimiin.'),
(1676537,58,9,17,2,'Saul ja Israelin miehet olivat myös kokoontuneet ja leiriytyneet Tammilaaksoon; ja he asettuivat sotarintaan filistealaisia vastaan.'),
(1676538,58,9,17,3,'Filistealaiset olivat vuorella, joka oli toisella puolella, ja israelilaiset olivat vuorella, joka oli toisella puolella, ja laakso oli heidän välillänsä.'),
(1676539,58,9,17,4,'Niin filistealaisten joukoista tuli kaksintaistelija nimeltä Goljat, kotoisin Gatista. Hän oli kuuden kyynärän ja vaaksan pituinen.'),
(1676540,58,9,17,5,'Hänellä oli vaskikypäri päässänsä ja suomuspanssari yllänsä, ja rintahaarniska, joka painoi viisituhatta sekeliä, oli vaskea.'),
(1676541,58,9,17,6,'Ja hänellä oli säärissään vaskivarukset ja selässään vaskikeihäs.'),
(1676542,58,9,17,7,'Hänen peitsensä varsi oli niinkuin kangastukki, ja hänen peitsensä kärki, joka painoi kuusisataa sekeliä, oli rautaa. Ja kilvenkantaja kävi hänen edellänsä.'),
(1676543,58,9,17,8,'Hän astui esiin ja huusi Israelin taisteluriveille sanoen: "Miksi te lähditte sotaan ja asetuitte sotarintaan? Minä olen filistealainen, ja te olette Saulin palvelijoita; valitkaa joukostanne mies, joka tulee tänne minun luokseni.'),
(1676544,58,9,17,9,'Jos hän kykenee taistelemaan minua vastaan ja surmaa minut, niin me olemme teidän palvelijanne; mutta jos minä voitan ja surmaan hänet, niin te olette meidän palvelijamme ja palvelette meitä."'),
(1676545,58,9,17,10,'Ja filistealainen sanoi vielä: "Minä olen tänä päivänä häväissyt Israelin taistelurivit. Antakaa tänne mies, niin me taistelemme keskenämme."'),
(1676546,58,9,17,11,'Kun Saul ja koko Israel kuuli nämä filistealaisen puheet, valtasi heidät kauhu, ja he pelkäsivät suuresti.'),
(1676547,58,9,17,12,'Mutta Daavid oli sen efratilaisen miehen poika Juudan Beetlehemistä, jonka nimi oli Iisai, ja tällä oli kahdeksan poikaa; hän oli Saulin aikana jo vanha, iäkäs mies.'),
(1676548,58,9,17,13,'Ja Iisain kolme vanhinta poikaa oli seurannut Saulia sotaan; ja näiden hänen kolmen sotaan lähteneen poikansa nimet olivat: esikoisen Eliab, toisen Abinadab ja kolmannen Samma.'),
(1676549,58,9,17,14,'Daavid oli nuorin. Ja nuo kolme vanhinta olivat seuranneet Saulia.'),
(1676550,58,9,17,15,'Mutta Daavid lähti tuontuostakin Saulin luota Beetlehemiin kaitsemaan isänsä lampaita.'),
(1676551,58,9,17,16,'Ja filistealainen astui esiin haastaen taisteluun joka aamu ja ilta, neljänäkymmenenä päivänä.'),
(1676552,58,9,17,17,'Ja Iisai sanoi pojallensa Daavidille: "Ota veljillesi eefa-mitta näitä paahdettuja jyviä ja nämä kymmenen leipää, ja vie ne kiiruusti leiriin veljillesi.'),
(1676553,58,9,17,18,'Ja vie nämä kymmenen juustoa tuhannenpäämiehelle. Tiedustele veljiesi vointia ja hanki varmuus, että lähetys on heille saapunut.'),
(1676554,58,9,17,19,'Saul ja he ynnä kaikki Israelin miehet ovat Tammilaaksossa sotimassa filistealaisia vastaan."'),
(1676555,58,9,17,20,'Varhain seuraavana aamuna Daavid jätti lampaat vartijan haltuun, otti kantamuksensa ja lähti matkalle, niinkuin Iisai oli häntä käskenyt. Kun hän tuli leiriin, lähti sotaväki taistelurintaan ja nosti sotahuudon.'),
(1676556,58,9,17,21,'Ja Israel ja filistealaiset asettuivat sotarintaan toisiansa vastaan.'),
(1676557,58,9,17,22,'Niin Daavid heitti tavarat selästänsä kuormaston vartijalle ja riensi sotarintaan; ja sinne tultuaan hän tervehti veljiänsä.'),
(1676558,58,9,17,23,'Kun hän puhutteli heitä, niin katso, kaksintaistelija, Goljat niminen filistealainen, kotoisin Gatista, tuli filistealaisten taisteluriveistä ja puhui niinkuin ennenkin; ja Daavid kuuli sen.'),
(1676559,58,9,17,24,'Ja kun israelilaiset näkivät tuon miehen, pakenivat he häntä kaikki ja pelkäsivät suuresti.'),
(1676560,58,9,17,25,'Ja Israelin miehet sanoivat: "Katsokaa miestä, joka tuolla tulee! Hän tulee häpäisemään Israelia. Mutta sen miehen, joka surmaa hänet, kuningas tekee hyvin rikkaaksi ja antaa hänelle tyttärensä ja tekee hänen isänsä perheen veroista vapaaksi Israelissa."'),
(1676561,58,9,17,26,'Niin Daavid sanoi miehille, jotka seisoivat siinä hänen kanssaan: "Mitä saa se mies, joka surmaa tuon filistealaisen ja poistaa häväistyksen Israelista? Sillä mikä tuo ympärileikkaamaton filistealainen on häpäisemään elävän Jumalan taistelurivejä?"'),
(1676562,58,9,17,27,'Väki sanoi hänelle saman, minkä ennenkin: sen ja sen saa se mies, joka surmaa hänet.'),
(1676563,58,9,17,28,'Mutta kun hänen vanhin veljensä Eliab kuuli hänen puhuvan miesten kanssa, vihastui Eliab Daavidiin ja sanoi: "Miksi sinä olet tullut tänne, ja kenelle olet jättänyt sen pienen lammaslauman siellä erämaassa? Minä tunnen sinun julkeutesi ja pahan sisusi; sinä olet tullut tänne katsomaan sotaa."'),
(1676564,58,9,17,29,'Daavid vastasi: "Mitä minä sitten olen tehnyt? Saaneehan tuon verran kysyä."'),
(1676565,58,9,17,30,'Ja hän kääntyi hänen luotansa toisen puoleen ja kysyi niinkuin ennenkin; ja väki vastasi hänelle samoin kuin äsken.'),
(1676566,58,9,17,31,'Mutta tuli tunnetuksi, mitä Daavid oli puhunut; ja se kerrottiin Saulille, ja tämä noudatti hänet luoksensa.'),
(1676567,58,9,17,32,'Ja Daavid sanoi Saulille: "Älköön kenenkään mieli masentuko hänen tähtensä. Palvelijasi käy taistelemaan tuota filistealaista vastaan."'),
(1676568,58,9,17,33,'Saul sanoi Daavidille: "Et sinä voi mennä tuota filistealaista vastaan etkä taistella hänen kanssaan, sillä sinä olet nuorukainen, mutta hän on sotilas nuoruudestansa saakka".'),
(1676569,58,9,17,34,'Mutta Daavid sanoi Saulille: "Palvelijasi on ollut kaitsemassa isänsä lampaita. Jos leijona tai karhu tuli ja vei lampaan laumasta,'),
(1676570,58,9,17,35,'niin minä hyökkäsin sen jälkeen, löin sen maahan ja tempasin saaliin sen suusta; ja jos se karkasi minua vastaan, niin minä tartuin sen partaan, löin sen maahan ja tapoin sen.'),
(1676571,58,9,17,36,'Kun palvelijasi on lyönyt maahan sekä leijonan että karhun, niin tuolle ympärileikkaamattomalle filistealaiselle käy niinkuin niille; sillä hän on häväissyt elävän Jumalan taistelurivejä."'),
(1676572,58,9,17,37,'Ja Daavid sanoi: "Herra, joka on pelastanut minut leijonan ja karhun kynsistä, pelastaa minut myös tämän filistealaisen käsistä". Silloin Saul sanoi Daavidille: "Mene; Herra olkoon sinun kanssasi".'),
(1676573,58,9,17,38,'Ja Saul puki takkinsa Daavidin ylle ja pani vaskikypärin hänen päähänsä sekä panssarin hänen yllensä.'),
(1676574,58,9,17,39,'Ja Daavid sitoi hänen miekkansa vyölleen takin päälle ja yritti käydä, sillä hän ei ollut koskaan sellaisia koettanut. Niin Daavid sanoi Saulille: "En minä voi näissä käydä, sillä en ole koskaan tällaisia koettanut". Ja Daavid riisui ne päältänsä.'),
(1676575,58,9,17,40,'Ja hän otti sauvansa käteensä, valitsi purosta viisi sileätä kiveä, pani ne paimenlaukkuun, joka hänellä oli linkokivisäiliönä, otti lingon käteensä ja meni filistealaista vastaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676576,58,9,17,41,'Ja filistealainen tuli yhä lähemmäksi Daavidia, ja kilvenkantaja kulki hänen edellänsä.'),
(1676577,58,9,17,42,'Kun filistealainen katsahti ja näki Daavidin, halveksi hän häntä; sillä hän oli vielä nuorukainen, verevä ja kaunis näöltään.'),
(1676578,58,9,17,43,'Niin filistealainen sanoi Daavidille: "Olenko minä koira, kun tulet sauva kädessä minua vastaan?" Ja filistealainen kiroili Daavidia vannoen jumaliensa kautta.'),
(1676579,58,9,17,44,'Sitten filistealainen sanoi Daavidille: "Tule tänne minun luokseni, niin minä annan sinun lihasi taivaan linnuille ja metsän eläimille".'),
(1676580,58,9,17,45,'Mutta Daavid sanoi filistealaiselle: "Sinä tulet minua vastaan miekan, peitsen ja keihään voimalla, mutta minä tulen sinua vastaan Herran Sebaotin nimeen, Israelin sotajoukon Jumalan, jota sinä olet häväissyt.'),
(1676581,58,9,17,46,'Tänä päivänä Herra antaa sinut minun käsiini, ja minä surmaan sinut, katkaisen sinulta pään ja annan filistealaisten sotajoukon ruumiit tänä päivänä taivaan linnuille ja metsän pedoille; ja kaikki maat tulevat tietämään, että Israelilla on Jumala.'),
(1676582,58,9,17,47,'Ja koko tämä suuri joukko tulee tietämään, ettei Herra anna voittoa miekan eikä keihään voimalla; sillä sota on Herran, ja hän antaa teidät meidän käsiimme."'),
(1676583,58,9,17,48,'Kun filistealainen lähti tulemaan ja lähestyi Daavidia, niin Daavid juoksi nopeasti sotarintaan filistealaista vastaan.'),
(1676584,58,9,17,49,'Ja Daavid pisti kätensä reppuunsa ja otti sieltä kiven, linkosi ja satutti filistealaista otsaan, niin että kivi upposi hänen otsaansa, ja hän kaatui maahan kasvoillensa.'),
(1676585,58,9,17,50,'Niin sai Daavid voiton filistealaisesta lingolla ja kivellä ja löi filistealaisen kuoliaaksi, eikä Daavidilla ollut miekkaa kädessään.'),
(1676586,58,9,17,51,'Sitten Daavid juoksi ja asettui filistealaisen ääreen, tarttui hänen miekkaansa, veti sen tupesta ja tappoi hänet ja löi sillä häneltä pään poikki. Kun filistealaiset näkivät, että heidän sankarinsa oli kuollut, pakenivat he.'),
(1676587,58,9,17,52,'Mutta Israelin ja Juudan miehet nousivat, nostivat sotahuudon ja ajoivat filistealaisia takaa laakson suulle ja Ekronin porteille saakka; ja filistealaisia kaatui surmattuina Saaraimin tiellä, aina Gatiin ja Ekroniin saakka.'),
(1676588,58,9,17,53,'Sitten israelilaiset palasivat ajamasta filistealaisia takaa ja ryöstivät heidän leirinsä.'),
(1676589,58,9,17,54,'Ja Daavid otti filistealaisen pään ja vei sen Jerusalemiin, mutta hänen aseensa hän asetti majaansa.'),
(1676590,58,9,17,55,'Kun Saul näki Daavidin menevän filistealaista vastaan, kysyi hän sotapäälliköltään Abnerilta: "Kenen poika tuo nuorukainen on, Abner?" Abner vastasi: "Niin totta kuin sinä, kuningas, elät, minä en sitä tiedä".'),
(1676591,58,9,17,56,'Niin kuningas sanoi: "Kysele sitten, kenen poika tuo nuori mies on".'),
(1676592,58,9,17,57,'Ja kun Daavid palasi takaisin surmattuaan filistealaisen, otti Abner hänet ja vei hänet Saulin eteen, ja hänellä oli kädessään filistealaisen pää.'),
(1676593,58,9,17,58,'Niin Saul kysyi häneltä: "Kenen poika sinä olet, nuorukainen?" Daavid vastasi: "Palvelijasi beetlehemiläisen Iisain poika".'),
(1676594,58,9,18,1,'Kun hän oli lakannut puhumasta Saulin kanssa, kiintyi Joonatan kaikesta sielustaan Daavidiin, ja Joonatan rakasti häntä niinkuin omaa sieluansa.'),
(1676595,58,9,18,2,'Ja Saul otti hänet sinä päivänä luoksensa eikä sallinut hänen enää palata isänsä kotiin.'),
(1676596,58,9,18,3,'Ja Joonatan teki liiton Daavidin kanssa, sillä hän rakasti häntä niinkuin omaa sieluansa.'),
(1676597,58,9,18,4,'Ja Joonatan riisui viitan, joka hänellä oli yllänsä, ja antoi sen Daavidille, ja samoin takkinsa, vieläpä miekkansa, jousensa ja vyönsä.'),
(1676598,58,9,18,5,'Daavid lähti, minne vain Saul hänet lähetti, ja hän menestyi. Niin Saul asetti hänet sotamiesten päälliköksi, ja se oli mieleen kaikelle kansalle ja myös Saulin palvelijoille.'),
(1676599,58,9,18,6,'Ja kun he olivat tulossa, silloin kun Daavid palasi takaisin surmattuansa filistealaisen, menivät naiset kaikista Israelin kaupungeista laulaen ja karkeloiden kuningas Saulia vastaan, riemuiten, vaskirumpuja ja kymbaaleja lyöden.'),
(1676600,58,9,18,7,'Ja karkeloivat naiset virittivät laulun ja sanoivat: "Saul voitti tuhat, mutta Daavid kymmenen tuhatta".'),
(1676601,58,9,18,8,'Silloin Saul vihastui kovin, sillä hän pani sen puheen pahakseen, ja hän sanoi: "Daavidille he antavat kymmenen tuhatta, ja minulle he antavat tuhat; nyt puuttuu häneltä enää vain kuninkuus".'),
(1676602,58,9,18,9,'Ja Saul katsoi karsain silmin Daavidia siitä päivästä alkaen.'),
(1676603,58,9,18,10,'Seuraavana päivänä Jumalan lähettämä paha henki valtasi Saulin, niin että hän raivosi kotonansa; mutta Daavid soitteli, niinkuin muulloinkin joka päivä, ja Saulilla oli kädessänsä keihäs.'),
(1676604,58,9,18,11,'Niin Saul heitti keihään ja ajatteli: "Minä keihästän Daavidin seinään". Mutta Daavid väisti häntä kaksi kertaa.'),
(1676605,58,9,18,12,'Ja Saul pelkäsi Daavidia, koska Herra oli hänen kanssansa, mutta oli poistunut Saulista.'),
(1676606,58,9,18,13,'Sentähden Saul toimitti hänet pois luotansa ja teki hänet tuhannenpäämieheksi; ja hän lähti ja tuli väen edellä.'),
(1676607,58,9,18,14,'Ja Daavid menestyi kaikilla teillään, ja Herra oli hänen kanssansa.'),
(1676608,58,9,18,15,'Kun Saul näki, että hänellä oli niin suuri menestys, rupesi hän häntä kammomaan.'),
(1676609,58,9,18,16,'Mutta koko Israel ja Juuda rakasti Daavidia, koska hän lähti ja tuli heidän edellänsä.'),
(1676610,58,9,18,17,'Ja Saul sanoi Daavidille: "Katso, vanhimman tyttäreni, Meerabin, minä annan sinulle vaimoksi; ole vain urhoollinen ja käy Herran sotia". Sillä Saul ajatteli: "Minun käteni älköön sattuko häneen, vaan sattukoon häneen filistealaisten käsi".'),
(1676611,58,9,18,18,'Mutta Daavid vastasi Saulille: "Mikä minä olen, mikä on minun elämäni ja mikä on isäni suku Israelissa, että minä tulisin kuninkaan vävyksi?"'),
(1676612,58,9,18,19,'Kun aika tuli, että Saulin tytär Meerab oli annettava Daavidille, annettiinkin hänet vaimoksi meholalaiselle Adrielille.'),
(1676613,58,9,18,20,'Mutta Saulin tytär Miikal rakasti Daavidia. Ja kun se ilmoitettiin Saulille, oli se hänelle mieleen.'),
(1676614,58,9,18,21,'Sillä Saul ajatteli: "Minä annan hänet Daavidille, että hän tulisi hänelle ansaksi ja filistealaisten käsi sattuisi häneen". Niin Saul sanoi Daavidille: "Nyt voit toisen kerran tulla minun vävykseni".'),
(1676615,58,9,18,22,'Ja Saul käski palvelijoitansa: "Puhukaa salaa Daavidille näin: ''Katso, kuningas on mieltynyt sinuun, ja kaikki hänen palvelijansa rakastavat sinua; sinun on nyt tultava kuninkaan vävyksi''".'),
(1676616,58,9,18,23,'Niin Saulin palvelijat puhuivat nämä sanat Daavidille. Mutta Daavid sanoi: "Onko teidän mielestänne niin pieni asia tulla kuninkaan vävyksi? Minähän olen köyhä ja halpa mies."'),
(1676617,58,9,18,24,'Saulin palvelijat ilmoittivat hänelle tämän, sanoen: "Näin on Daavid puhunut".'),
(1676618,58,9,18,25,'Niin Saul sanoi: "Sanokaa Daavidille näin: ''Kuningas ei halua muuta morsiamenhintaa kuin sata filistealaisten esinahkaa, että kuninkaan vihollisille kostettaisiin''". Sillä Saul ajatteli kaataa Daavidin filistealaisten käden kautta.'),
(1676619,58,9,18,26,'Kun hänen palvelijansa ilmoittivat tämän Daavidille, miellytti Daavidia tulla näin kuninkaan vävyksi; ja ennenkuin määräaika oli kulunut umpeen,'),
(1676620,58,9,18,27,'nousi Daavid ja lähti miehineen ja kaatoi filistealaisia kaksisataa miestä. Ja Daavid toi heidän esinahkansa, täyden määrän, kuninkaalle, tullaksensa kuninkaan vävyksi. Silloin Saul antoi tyttärensä Miikalin hänelle vaimoksi.'),
(1676621,58,9,18,28,'Ja Saul näki ja ymmärsi, että Herra oli Daavidin kanssa, ja Saulin tytär Miikal rakasti häntä.'),
(1676622,58,9,18,29,'Niin Saul pelkäsi vielä enemmän Daavidia, ja Saulista tuli koko elinajakseen Daavidin vihamies.'),
(1676623,58,9,18,30,'Mutta filistealaisten ruhtinaat lähtivät sotaan; ja niin usein kuin he lähtivät sotaan, oli Daavidilla suurempi menestys kuin kaikilla muilla Saulin palvelijoilla, niin että hänen nimensä tuli sangen kuuluisaksi.'),
(1676624,58,9,19,1,'Ja Saul puhui pojallensa Joonatanille ja kaikille palvelijoillensa, että Daavid olisi surmattava. Mutta Saulin poika Joonatan oli suuresti mieltynyt Daavidiin.'),
(1676625,58,9,19,2,'Sentähden Joonatan ilmaisi sen Daavidille ja sanoi: "Minun isäni Saul koettaa saada sinut surmatuksi. Ole siis varuillasi huomenaamuna, kätkeydy ja pysy piilossa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676626,58,9,19,3,'Mutta minä menen ja asetun isäni viereen kedolle, sinne, missä sinä olet, ja puhun sinusta isälleni; ja jos jotakin huomaan, niin minä ilmaisen sen sinulle."'),
(1676627,58,9,19,4,'Niin Joonatan puhui hyvää Daavidista isällensä Saulille ja sanoi hänelle: "Älköön kuningas rikkoko palvelijaansa Daavidia vastaan, sillä hän ei ole rikkonut sinua vastaan, vaan hänen työnsä ovat olleet sinulle suureksi hyödyksi.'),
(1676628,58,9,19,5,'Hänhän pani henkensä kämmenelleen ja surmasi sen filistealaisen, ja niin Herra antoi suuren voiton koko Israelille; sinä olet itse nähnyt sen ja iloinnut. Miksi siis rikkoisit viatonta verta vastaan surmaamalla Daavidin syyttömästi?"'),
(1676629,58,9,19,6,'Saul kuuli Joonatanin ääntä; ja Saul vannoi: "Niin totta kuin Herra elää, häntä ei surmata".'),
(1676630,58,9,19,7,'Niin Joonatan kutsui Daavidin, ja Joonatan ilmoitti hänelle kaiken tämän. Ja sitten Joonatan vei Daavidin Saulin tykö, ja hän palveli häntä niinkuin ennenkin.'),
(1676631,58,9,19,8,'Kun sitten sota alkoi uudestaan, lähti Daavid taistelemaan filistealaisia vastaan ja tuotti heille suuren tappion, niin että he pakenivat hänen edestään.'),
(1676632,58,9,19,9,'Mutta Herran lähettämä paha henki tuli Sauliin, kun hän istui kotonaan keihäs kädessä ja Daavid soitteli.'),
(1676633,58,9,19,10,'Niin Saul koetti keihästää Daavidin seinään; mutta hän väisti Saulia, ja tämä iski keihään seinään. Daavid pakeni ja pelastui sinä yönä.'),
(1676634,58,9,19,11,'Niin Saul lähetti miehiä Daavidin kotiin vartioimaan häntä ja surmaamaan hänet aamulla. Mutta Daavidin vaimo Miikal ilmaisi sen hänelle ja sanoi: "Jollet tänä yönä pelasta henkeäsi, niin sinä huomenna olet surman oma".'),
(1676635,58,9,19,12,'Ja Miikal laski Daavidin alas ikkunasta; ja hän lähti pakoon ja pelastui.'),
(1676636,58,9,19,13,'Sitten Miikal otti kotijumalan ja asetti sen vuoteeseen, ja levitettyään vuohenkarvoista tehdyn kärpäsverkon sen pään yli hän peitti sen vaatteella.'),
(1676637,58,9,19,14,'Ja kun Saul lähetti miehiä ottamaan Daavidia, sanoi hän: "Hän on sairas".'),
(1676638,58,9,19,15,'Niin Saul lähetti miehiä katsomaan Daavidia, sanoen: "Tuokaa hänet vuoteessa tänne minun luokseni surmattavaksi".'),
(1676639,58,9,19,16,'Mutta kun miehet tulivat sisälle, niin katso, vuoteessa olikin kotijumala, vuohenkarvoista tehty kärpäsverkko pään päällä.'),
(1676640,58,9,19,17,'Niin Saul sanoi Miikalille: "Miksi sinä olet minut näin pettänyt ja olet päästänyt minun vihamieheni pelastumaan?" Miikal vastasi Saulille: "Hän sanoi minulle: ''Päästä minut, muutoin minä surmaan sinut''".'),
(1676641,58,9,19,18,'Kun Daavid oli paennut ja pelastunut, meni hän Samuelin luo Raamaan ja kertoi hänelle kaikki, mitä Saul oli hänelle tehnyt. Ja hän ja Samuel menivät Naajotiin ja jäivät sinne.'),
(1676642,58,9,19,19,'Ja Saulille ilmoitettiin: "Katso, Daavid on Raaman Naajotissa".'),
(1676643,58,9,19,20,'Niin Saul lähetti miehiä ottamaan Daavidia. Mutta kun he näkivät profeettain joukon hurmoksissa ja Samuelin seisovan johtamassa heitä, tuli Jumalan henki Saulin miehiin, niin että hekin joutuivat hurmoksiin.'),
(1676644,58,9,19,21,'Kun se ilmoitettiin Saulille, lähetti hän toiset miehet; mutta hekin joutuivat hurmoksiin. Ja Saul lähetti vielä kolmannet miehet, mutta hekin joutuivat hurmoksiin.'),
(1676645,58,9,19,22,'Silloin hän itse lähti Raamaan. Ja kun hän tuli sen suuren vesisäiliön luo, joka on Seekussa, kysyi hän: "Missä ovat Samuel ja Daavid?" Hänelle vastattiin: "He ovat Raaman Naajotissa".'),
(1676646,58,9,19,23,'Mutta kun hän oli menossa sinne, Raaman Naajotiin, tuli Jumalan henki häneenkin, niin että hän kulki hurmoksissa, kunnes tuli Raaman Naajotiin.'),
(1676647,58,9,19,24,'Silloin hänkin riisui vaatteensa ja joutui hurmoksiin Samuelin edessä; ja hän kaatui maahan ja makasi alastonna koko sen päivän ja koko sen yön. Sentähden on tapana sanoa: "Onko Saulkin profeettain joukossa?"'),
(1676648,58,9,20,1,'Mutta Daavid pakeni Raaman Naajotista, tuli ja puhui Joonatanille: "Mitä minä olen tehnyt? Mitä vääryyttä, mitä syntiä minä olen tehnyt sinun isääsi vastaan, kun hän väijyy henkeäni?"'),
(1676649,58,9,20,2,'Tämä vastasi hänelle: "Pois se! Et sinä kuole. Katso, isäni ei tee mitään, suurta eikä pientä, ilmoittamatta minulle. Miksi sitten isäni salaisi minulta tämän? Ei ole niin."'),
(1676650,58,9,20,3,'Mutta Daavid vielä vakuutti vannoen ja sanoi: "Isäsi tietää, että minä olen saanut armon sinun silmiesi edessä; sentähden hän ajattelee: ''Älköön Joonatan saako tietää tätä, ettei hän tulisi murheelliseksi''. Mutta niin totta kuin Herra elää ja niin totta kuin sinä itse elät: on vain askel minun ja kuoleman välillä."'),
(1676651,58,9,20,4,'Niin Joonatan sanoi Daavidille: "Mitä sinä vain lausut toivovasi, sen minä sinulle teen".'),
(1676652,58,9,20,5,'Daavid sanoi Joonatanille: "Katso, huomenna on uusikuu, ja minun pitäisi istua aterioimassa kuninkaan kanssa; mutta salli minun mennä ja kätkeytyä ulos kedolle ylihuomeniltaan asti.'),
(1676653,58,9,20,6,'Jos isäsi kaipaa minua, niin sano: ''Daavid pyysi minulta, että saisi käväistä kaupungissaan Beetlehemissä, sillä koko suvulla on siellä jokavuotiset teurasuhrit''.'),
(1676654,58,9,20,7,'Ja jos hän sanoo: ''Hyvä on'', niin voi palvelijasi olla rauhassa. Mutta jos hän vihastuu, niin tiedä, että hänellä on paha mielessä.'),
(1676655,58,9,20,8,'Tee siis laupeus palvelijallesi, koska olet ottanut palvelijasi Herran liittoon kanssasi. Mutta jos minussa on vääryys, niin surmaa sinä minut; sillä miksi sinä veisit minut isäsi eteen?"'),
(1676656,58,9,20,9,'Joonatan sanoi: "Pois se! Jos huomaan, että minun isälläni on paha mielessä sinua vastaan, niin minä sen varmasti sinulle ilmoitan."'),
(1676657,58,9,20,10,'Mutta Daavid sanoi Joonatanille: "Kunpa sitten joku ilmoittaisi minulle, antaako isäsi sinulle kovan vastauksen".'),
(1676658,58,9,20,11,'Joonatan sanoi Daavidille: "Tule, menkäämme ulos kedolle". Niin he menivät molemmat ulos kedolle.'),
(1676659,58,9,20,12,'Ja Joonatan sanoi Daavidille: "Minä vakuutan Herran, Israelin Jumalan, kautta, että koetan huomenna tai ylihuomenna tähän aikaan päästä selville isästäni; ja jos Daavidin asiat ovat hyvin, niin minä varmasti lähetän siitä tiedon ja ilmoitan sen sinulle.'),
(1676660,58,9,20,13,'Herra rangaiskoon Joonatania nyt ja vasta, jollen minä, jos isäni mielii tehdä sinulle pahaa, ilmoita sitä sinulle ja päästä sinua menemään rauhassa. Herra olkoon sinun kanssasi, niinkuin hän on ollut minun isäni kanssa.'),
(1676661,58,9,20,14,'Etkö sinäkin, jos minä silloin vielä elän, etkö sinäkin tee Herran laupeutta minulle, niin ettei minun tarvitse kuolla?'),
(1676662,58,9,20,15,'Ethän koskaan kiellä laupeuttasi minun suvultani, et silloinkaan, kun Herra hävittää Daavidin vihamiehet kaikki tyynni maan päältä?"'),
(1676663,58,9,20,16,'Niin Joonatan teki liiton Daavidin suvun kanssa. Ja Herra vaati koston Daavidin vihamiehiltä.'),
(1676664,58,9,20,17,'Ja Joonatan vannotti vielä Daavidin heidän keskinäisen rakkautensa kautta, sillä hän rakasti häntä niinkuin omaa sieluansa.'),
(1676665,58,9,20,18,'Ja Joonatan sanoi hänelle: "Huomenna on uusikuu, ja sinua kaivataan, kun paikkasi on tyhjä.'),
(1676666,58,9,20,19,'Mutta ylihuomenna mene nopeasti siihen paikkaan, johon kätkeydyit sinä päivänä, jona se teko tapahtui, ja istuudu Eselin kiven ääreen.'),
(1676667,58,9,20,20,'Niin minä ammun kolme nuolta sen laitaa kohti, niinkuin ampuisin maaliin.'),
(1676668,58,9,20,21,'Sitten minä lähetän palvelijan sanoen: ''Mene ja hae nuolet''. Jos minä silloin sanon palvelijalle: ''Katso, nuolet ovat takanasi, tännempänä, ota ne'', niin tule kotiin, sillä silloin voit olla rauhassa eikä mitään ole tekeillä; niin totta kuin Herra elää.'),
(1676669,58,9,20,22,'Mutta jos minä sanon sille nuorelle miehelle näin: ''Katso, nuolet ovat edessäsi, sinnempänä'', niin lähde, sillä Herra lähettää sinut pois.'),
(1676670,58,9,20,23,'Ja mitä minä ja sinä olemme keskenämme puhuneet, sen todistaja meidän välillämme, minun ja sinun, on Herra iankaikkisesti."'),
(1676671,58,9,20,24,'Niin Daavid kätkeytyi kedolle. Ja kun uusikuu tuli, istuutui kuningas aterialle.'),
(1676672,58,9,20,25,'Kuningas istui tavallisella istuimellansa, istuimella seinän vieressä. Ja Joonatan nousi seisomaan, ja Abner istuutui Saulin viereen. Mutta Daavidin paikka oli tyhjä.'),
(1676673,58,9,20,26,'Saul ei kuitenkaan sanonut mitään sinä päivänä, sillä hän ajatteli: "Jotakin on hänelle tapahtunut: hän ei liene puhdas; varmaankaan hän ei ole puhdas".'),
(1676674,58,9,20,27,'Mutta kun Daavidin paikka oli tyhjä seuraavanakin päivänä, toisena uudenkuun päivänä, sanoi Saul pojallensa Joonatanille: "Miksi ei Iisain poika ole eilen eikä tänään tullut aterialle?"'),
(1676675,58,9,20,28,'Joonatan vastasi Saulille: "Daavid pyysi minulta, että saisi mennä Beetlehemiin;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676676,58,9,20,29,'hän sanoi: ''Salli minun mennä, sillä meillä on suvun teurasuhrit kaupungissa, ja veljeni itse on käskenyt minut sinne; jos minä siis olen saanut armon sinun silmiesi edessä, niin päästä minut katsomaan veljiäni''. Sentähden hän ei ole tullut kuninkaan pöytään."'),
(1676677,58,9,20,30,'Silloin Saul vihastui Joonataniin ja sanoi hänelle: "Sinä säädyttömän naisen poika! Tiesinhän minä, että sinä olet mieltynyt Iisain poikaan, häpeäksi itsellesi ja häpeäksi äitisi hävylle.'),
(1676678,58,9,20,31,'Sillä niin kauan kuin Iisain poika elää maan päällä, et sinä eikä sinun kuninkuutesi ole turvassa. Lähetä nyt noutamaan hänet minun luokseni, sillä hän on kuoleman oma."'),
(1676679,58,9,20,32,'Joonatan vastasi isälleen Saulille ja sanoi hänelle: "Miksi hänet on surmattava? Mitä hän on tehnyt?"'),
(1676680,58,9,20,33,'Silloin Saul heitti keihään häntä kohti surmataksensa hänet. Niin Joonatan ymmärsi, että hänen isänsä oli päättänyt tappaa Daavidin.'),
(1676681,58,9,20,34,'Ja Joonatan nousi pöydästä, vihasta hehkuen, eikä syönyt mitään toisena uudenkuun päivänä, sillä hän oli murheissaan Daavidin tähden, koska hänen isänsä oli häväissyt tätä.'),
(1676682,58,9,20,35,'Seuraavana aamuna Joonatan lähti ulos kedolle, niinkuin hän oli sopinut Daavidin kanssa, ja hänellä oli mukanaan pieni poikanen.'),
(1676683,58,9,20,36,'Ja hän sanoi pojalle: "Juokse noutamaan nuolet, jotka minä ammun". Ja pojan juostessa hän ampui nuolen hänen ylitsensä.'),
(1676684,58,9,20,37,'Ja kun poika oli tulemassa siihen paikkaan, missä Joonatanin ampuma nuoli oli, huusi Joonatan pojalle ja sanoi: "Nuoli on edessäsi, sinnempänä".'),
(1676685,58,9,20,38,'Ja Joonatan huusi vielä pojalle: "Riennä nopeasti, älä seisahtele!" Niin Joonatanin poikanen otti nuolen ja tuli herransa luo.'),
(1676686,58,9,20,39,'Eikä poika tiennyt asiasta mitään; ainoastaan Joonatan ja Daavid tiesivät sen.'),
(1676687,58,9,20,40,'Ja Joonatan antoi aseensa pojalle, joka hänellä oli mukanaan, ja sanoi hänelle: "Mene ja vie nämä kaupunkiin".'),
(1676688,58,9,20,41,'Ja kun poika oli mennyt, nousi Daavid ylös etelän puolelta; ja hän lankesi kasvoilleen maahan ja kumartui kolme kertaa; ja he suutelivat toisiansa ja itkivät yhdessä; Daavid itki hillittömästi.'),
(1676689,58,9,20,42,'Ja Joonatan sanoi Daavidille: "Mene rauhassa. Niin on, kuin me molemmat olemme vannoneet Herran nimeen ja sanoneet: ''Herra on todistaja meidän välillämme, minun ja sinun, ja minun jälkeläisteni ja sinun jälkeläistesi välillä iankaikkisesti''."'),
(1676690,58,9,20,43,'Sitten Daavid nousi ja lähti, mutta Joonatan palasi kaupunkiin.'),
(1676691,58,9,21,1,'Ja Daavid tuli pappi Ahimelekin luo Noobiin. Mutta Ahimelek tuli vavisten Daavidia vastaan ja kysyi häneltä: "Miksi sinä tulet yksin, eikä ole ketään sinun kanssasi?"'),
(1676692,58,9,21,2,'Daavid vastasi pappi Ahimelekille: "Kuningas on käskenyt minut asialle ja sanoi minulle: ''Älköön kukaan saako tietää mitään siitä asiasta, jolle minä sinut lähetän, ja siitä käskystä, jonka minä olen sinulle antanut''. Ja palvelijat minä olen määrännyt siihen ja siihen paikkaan.'),
(1676693,58,9,21,3,'Anna nyt minulle, mitä sinulla on, viisi leipää, tahi mitä muuta löytyy."'),
(1676694,58,9,21,4,'Pappi vastasi Daavidille ja sanoi: "Tavallista leipää minulla ei ole; ainoastaan pyhää leipää on, jos vain palvelijat ovat karttaneet naisia".'),
(1676695,58,9,21,5,'Daavid vastasi papille ja sanoi hänelle: "Totisesti olivat naiset eristettyinä meistä niinkuin ennenkin, milloin minä olen retkelle lähtenyt; ovatpa palvelijain reputkin aina olleet pyhät, vaikka retki on ollutkin tavallinen retki. Sitä enemmän leipä repuissa nyt pysyy pyhänä."'),
(1676696,58,9,21,6,'Niin pappi antoi hänelle pyhää leipää; sillä siellä ei ollut muuta leipää kuin näkyleipiä, jotka oli siirretty pois Herran edestä, että sinne samana päivänä, jona ne oli otettu pois, pantaisiin tuoreet leivät.'),
(1676697,58,9,21,7,'Mutta siellä oli sinä päivänä eristettynä Herran edessä eräs Saulin palvelija, nimeltä Dooeg, edomilainen, Saulin paimenten päämies.'),
(1676698,58,9,21,8,'Ja Daavid kysyi vielä Ahimelekiltä: "Eikö sinulla ole täällä yhtään keihästä tai miekkaa? Sillä minä en ottanut mukaani, en miekkaani enkä muita aseitani, koska kuninkaan asia oli niin kiireellinen."'),
(1676699,58,9,21,9,'Pappi vastasi: "On, sen filistealaisen Goljatin miekka, jonka sinä surmasit Tammilaaksossa; katso, se on vaippaan käärittynä tuolla kasukan takana. Jos tahdot ottaa itsellesi sen, niin ota; sillä muuta kuin se ei täällä ole." Daavid sanoi: "Ei ole toista sen vertaista; anna se minulle".'),
(1676700,58,9,21,10,'Sitten Daavid nousi ja pakeni sinä päivänä Saulia ja tuli Aakiin, Gatin kuninkaan, luo.'),
(1676701,58,9,21,11,'Mutta Aakiin palvelijat sanoivat hänelle: "Eikö tämä ole Daavid, sen maan kuningas? Eivätkö he karkeloiden virittäneet hänelle tätä laulua: ''Saul voitti tuhat, mutta Daavid kymmenentuhatta''?"'),
(1676702,58,9,21,12,'Daavid pani mieleensä nämä sanat ja pelkäsi suuresti Aakista, Gatin kuningasta.'),
(1676703,58,9,21,13,'Niin hän tekeytyi mielipuoleksi heidän silmiensä edessä ja raivosi heidän käsissään ja piirusteli portin oviin ja valutti sylkeä partaansa.'),
(1676704,58,9,21,14,'Silloin Aakis sanoi palvelijoilleen: "Näettehän, että mies on hullu. Miksi toitte hänet minun luokseni?'),
(1676705,58,9,21,15,'Puuttuuko minulta hulluja, kun toitte tämän hulluttelemaan minun eteeni? Tällainenko saisi tulla minun hoviini?"'),
(1676706,58,9,22,1,'Niin Daavid lähti sieltä ja pääsi pakoon Adullamin luolaan. Ja kun hänen veljensä ja koko hänen isänsä perhe kuulivat sen, tulivat he sinne hänen luoksensa.'),
(1676707,58,9,22,2,'Ja hänen luoksensa kokoontui kaikenlaista ahdingossa olevaa, velkaantunutta ja katkeroitunutta väkeä, ja hän rupesi heidän päämiehekseen. Näin liittyi häneen noin neljäsataa miestä.'),
(1676708,58,9,22,3,'Sieltä Daavid meni Mooabin Mispeen. Ja hän sanoi Mooabin kuninkaalle: "Salli minun isäni ja äitini tulla asumaan teidän luoksenne, kunnes saan tietää, mitä Jumala minulle tekee".'),
(1676709,58,9,22,4,'Ja hän vei heidät Mooabin kuninkaan eteen; ja he jäivät tämän luo kaikeksi aikaa, minkä Daavid oli vuorilinnassa.'),
(1676710,58,9,22,5,'Mutta profeetta Gaad sanoi Daavidille: "Älä jää vuorilinnaan; lähde täältä ja mene Juudan maahan". Niin Daavid lähti ja tuli Jaar-Heretiin.'),
(1676711,58,9,22,6,'Ja Saul kuuli, että oli saatu vihiä Daavidista ja niistä miehistä, jotka olivat hänen kanssaan; ja Saul istui Gibeassa tamariskipuun alla kummulla, keihäs kädessä, ja kaikki hänen palvelijansa seisoivat hänen luonaan.'),
(1676712,58,9,22,7,'Niin Saul sanoi palvelijoilleen, jotka seisoivat hänen luonaan: "Kuulkaa, benjaminilaiset! Antaako Iisain poika teillekin kaikille pellot ja viinitarhat, ja tekeekö hän teidät kaikki tuhannen- ja sadanpäämiehiksi?'),
(1676713,58,9,22,8,'Tehän olette kaikki salaliitossa minua vastaan, eikä kukaan ole ilmaissut minulle, että oma poikani on tehnyt liiton Iisain pojan kanssa. Ei kukaan teistä välitä niin paljoa minusta, että olisi ilmaissut sen minulle. Sillä minun poikani on yllyttänyt palvelijani väijymään minua, niinkuin nyt tapahtuu."'),
(1676714,58,9,22,9,'Niin edomilainen Dooeg, joka seisoi siinä Saulin palvelijain kanssa, vastasi ja sanoi: "Minä näin Iisain pojan tulevan Noobiin, Ahimelekin, Ahitubin pojan, luo.'),
(1676715,58,9,22,10,'Tämä kysyi hänelle neuvoa Herralta ja evästi hänet ja antoi hänelle filistealaisen Goljatin miekan."'),
(1676716,58,9,22,11,'Silloin kuningas lähetti kutsumaan pappi Ahimelekin, Ahitubin pojan, ja koko hänen isänsä suvun, Noobin papit. Ja he tulivat kaikki kuninkaan luo.'),
(1676717,58,9,22,12,'Niin Saul sanoi: "Kuule, Ahitubin poika!" Hän vastasi: "Tässä olen, Herrani".'),
(1676718,58,9,22,13,'Saul sanoi hänelle: "Miksi te olette salaliitossa minua vastaan, sinä ja Iisain poika, koska sinä olet antanut hänelle leipää ja miekan ja kysynyt hänelle Herralta neuvoa, että hän ryhtyisi väijymään minua, niinkuin nyt tapahtuu?"'),
(1676719,58,9,22,14,'Ahimelek vastasi kuninkaalle ja sanoi: "Kuka on kaikkien sinun palvelijaisi joukossa niin uskottu kuin Daavid, joka on kuninkaan vävy ja sinun henkivartiostosi päällikkö ja on korkeassa arvossa sinun hovissasi?'),
(1676720,58,9,22,15,'Enhän minä nyt ensi kertaa kysynyt hänelle Jumalalta neuvoa. Pois se! Älköön kuningas lukeko mitään viaksi minulle, palvelijalleen, älköönkä kaikelle minun isäni suvulle, sillä palvelijasi ei tietänyt kaikesta tästä vähän vähääkään."'),
(1676721,58,9,22,16,'Mutta kuningas sanoi: "Sinun on kuolemalla kuoltava, Ahimelek, sinun ja koko sinun isäsi suvun".'),
(1676722,58,9,22,17,'Ja kuningas sanoi henkivartijoille, jotka seisoivat hänen luonaan: "Käykää tänne ja surmatkaa Herran papit, sillä hekin pitävät Daavidin puolta; ja vaikka tiesivät hänen paenneen, eivät he ilmoittaneet sitä minulle". Mutta kuninkaan palvelijat eivät tahtoneet ojentaa kättään lyömään kuoliaaksi Herran pappeja.'),
(1676723,58,9,22,18,'Niin kuningas sanoi Dooegille: "Käy sinä tänne ja lyö papit kuoliaaksi". Ja edomilainen Dooeg astui esiin ja löi papit kuoliaaksi; ja hän tappoi sinä päivänä kahdeksankymmentä viisi pellavakasukkaa kantavaa miestä.'),
(1676724,58,9,22,19,'Myös pappiskaupungin Noobin asukkaat hän surmasi miekan terällä, sekä miehet että naiset, sekä lapset että imeväiset; jopa raavaat, aasit ja lampaatkin hän tappoi miekan terällä.'),
(1676725,58,9,22,20,'Ainoastaan yksi Ahimelekin, Ahitubin pojan, poika, nimeltä Ebjatar, pelastui ja pakeni Daavidin luo.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676726,58,9,22,21,'Ja Ebjatar kertoi Daavidille, että Saul oli tappanut Herran papit.'),
(1676727,58,9,22,22,'Niin Daavid sanoi Ebjatarille: "Minä ymmärsin jo silloin, että edomilainen Dooeg, kun hän oli siellä, oli ilmaiseva sen Saulille. Minä olen syypää koko sinun isäsi suvun, joka hengen, kuolemaan.'),
(1676728,58,9,22,23,'Jää minun luokseni, älä pelkää; sillä joka väijyy sinun henkeäsi, se väijyy minun henkeäni. Minun luonani sinä olet turvassa."'),
(1676729,58,9,23,1,'Daavidille ilmoitettiin: "Katso, filistealaiset ovat taistelemassa Kegilaa vastaan ja ryöstävät puimatantereita".'),
(1676730,58,9,23,2,'Niin Daavid kysyi Herralta: "Menenkö minä ja lyönkö nämä filistealaiset maahan?" Herra vastasi Daavidille: "Mene, lyö filistealaiset maahan ja pelasta Kegila".'),
(1676731,58,9,23,3,'Mutta Daavidin miehet sanoivat hänelle: "Mehän elämme pelossa jo täällä Juudassa. Menisimmekö vielä Kegilaan filistealaisten taistelurivejä vastaan?"'),
(1676732,58,9,23,4,'Niin Daavid kysyi taas Herralta, ja Herra vastasi hänelle ja sanoi: "Nouse ja mene alas Kegilaan; sillä minä annan filistealaiset sinun käsiisi".'),
(1676733,58,9,23,5,'Ja Daavid meni miehinensä Kegilaan ja ryhtyi taisteluun filistealaisia vastaan ja kuljetti heidän karjansa pois ja tuotti heille suuren tappion. Näin Daavid pelasti Kegilan asukkaat.'),
(1676734,58,9,23,6,'Ja kun Ebjatar, Ahimelekin poika, pakeni Daavidin luo Kegilaan, seurasi kasukka hänen mukanaan.'),
(1676735,58,9,23,7,'Saulille ilmoitettiin, että Daavid oli mennyt Kegilaan. Niin Saul sanoi: "Jumala on jättänyt hänet minun käsiini, sillä hän on itse sulkenut itsensä sisälle, kun on mennyt kaupunkiin, jossa on ovet ja salvat".'),
(1676736,58,9,23,8,'Sitten Saul kuulutti kaiken kansan sotaan, menemään alas Kegilaan, piirittämään Daavidia ja hänen miehiänsä.'),
(1676737,58,9,23,9,'Kun Daavid sai tietää, että Saul hankki hänelle tuhoa, sanoi hän pappi Ebjatarille: "Tuo tänne kasukka".'),
(1676738,58,9,23,10,'Ja Daavid sanoi: "Herra, Israelin Jumala! Sinun palvelijasi on kuullut, että Saul aikoo tulla Kegilaan hävittämään kaupungin minun tähteni.'),
(1676739,58,9,23,11,'Luovuttavatko Kegilan miehet minut hänen käsiinsä? Tuleeko Saul, niinkuin palvelijasi on kuullut? Herra, Israelin Jumala, ilmoita se palvelijallesi." Herra vastasi: "Tulee".'),
(1676740,58,9,23,12,'Ja Daavid kysyi vielä: "Luovuttavatko Kegilan miehet minut ja minun mieheni Saulin käsiin?" Herra vastasi: "Luovuttavat".'),
(1676741,58,9,23,13,'Niin Daavid nousi miehinensä, joita oli noin kuusisataa miestä, ja he lähtivät Kegilasta ja kuljeskelivat paikasta toiseen. Mutta kun Saulille kerrottiin, että Daavid oli päässyt pakoon Kegilasta, luopui hän retkestänsä.'),
(1676742,58,9,23,14,'Ja Daavid oleskeli erämaassa vuorten huipuilla; hän oleskeli Siifin erämaan vuoristossa. Ja Saul etsi häntä kaiken aikaa, mutta Jumala ei antanut häntä tämän käsiin.'),
(1676743,58,9,23,15,'Daavid huomasi, että Saul oli lähtenyt väijymään hänen henkeänsä, ja Daavid oli Hooreksessa, Siifin erämaassa.'),
(1676744,58,9,23,16,'Silloin Saulin poika Joonatan nousi ja meni Daavidin luo Hoorekseen ja rohkaisi häntä Jumalassa.'),
(1676745,58,9,23,17,'Hän sanoi hänelle: "Älä pelkää; sillä minun isäni Saulin käsi ei ole tapaava sinua, vaan sinusta tulee Israelin kuningas, ja minä tulen olemaan lähinnä sinua. Myös minun isäni Saul tietää kyllä sen."'),
(1676746,58,9,23,18,'Sitten he molemmat tekivät liiton Herran edessä. Ja Daavid jäi Hoorekseen, mutta Joonatan palasi kotiinsa.'),
(1676747,58,9,23,19,'Mutta siifiläisiä meni Saulin luo Gibeaan, ja he sanoivat: "Daavid piileksii meillä päin, vuorten huipuilla Hooreksessa, Gibeat-Hakilassa, joka on kallioerämaasta etelään.'),
(1676748,58,9,23,20,'Niin tule nyt sinne, kuningas, milloin vain haluat tulla; me kyllä luovutamme hänet kuninkaan käsiin."'),
(1676749,58,9,23,21,'Saul sanoi: "Herra siunatkoon teitä, kun te säälitte minua.'),
(1676750,58,9,23,22,'Menkää, pitäkää häntä vielä silmällä, tiedustelkaa ja katsokaa, missä paikassa hänen jalkansa liikkuu ja kuka hänet on siellä nähnyt; sillä minulle on sanottu, että hän on hyvin kavala.'),
(1676751,58,9,23,23,'Katsokaa ja tiedustelkaa kaikki piilopaikat, joihin hän voi piiloutua. Palatkaa sitten minun luokseni ja tuokaa varmat tiedot, niin minä lähden teidän kanssanne. Ja jos hän on tässä maassa, niin minä etsin hänet kaikkien Juudan sukujen seasta."'),
(1676752,58,9,23,24,'Ja he nousivat ja menivät Siifiin Saulin edellä. Mutta Daavid miehineen oli Maaonin erämaassa, aromaassa, kallioerämaasta etelään.'),
(1676753,58,9,23,25,'Kun Saul miehineen meni etsimään Daavidia, ilmoitettiin se tälle, ja hän laskeutui eräälle kalliolle ja jäi Maaonin erämaahan. Kun Saul kuuli sen, lähti hän ajamaan Daavidia takaa Maaonin erämaahan.'),
(1676754,58,9,23,26,'Ja Saul kulki vuoren toista puolta ja Daavid miehineen vuoren toista puolta. Ja kun Daavid riensi pakoon Saulin tieltä ja Saul miehinensä oli kiertämässä Daavidia ja hänen miehiänsä, ottaaksensa heidät kiinni,'),
(1676755,58,9,23,27,'tuli sanansaattaja Saulin luo ja sanoi: "Tule kiiruusti, sillä filistealaiset ovat hyökänneet maahan".'),
(1676756,58,9,23,28,'Silloin Saul lakkasi ajamasta takaa Daavidia ja lähti filistealaisia vastaan. Siitä se paikka sai nimekseen Mahlekotkallio.'),
(1676757,58,9,24,1,'Mutta Daavid lähti sieltä ja oleskeli Een-Gedin vuorten huipuilla.'),
(1676758,58,9,24,2,'Ja kun Saul palasi ajamasta filistealaisia takaa, ilmoitettiin hänelle: "Katso, Daavid on Een-Gedin erämaassa".'),
(1676759,58,9,24,3,'Niin Saul otti kolmetuhatta valiomiestä koko Israelista ja meni etsimään Daavidia ja hänen miehiään Kauriskallioiden itäpuolelta.'),
(1676760,58,9,24,4,'Ja kun hän tuli tien varrella oleville karjatarhoille, oli siellä luola; ja Saul meni luolaan tarpeelleen. Mutta Daavid ja hänen miehensä istuivat luolan perällä.'),
(1676761,58,9,24,5,'Niin Daavidin miehet sanoivat hänelle: "Katso, tämä on se päivä, josta Herra on sanonut sinulle: ''Minä annan vihamiehesi sinun käsiisi, tehdäksesi hänelle, mitä hyväksi näet''". Ja Daavid nousi ja leikkasi salaa kappaleen Saulin viitan liepeestä.'),
(1676762,58,9,24,6,'Mutta sen jälkeen Daavidin omatunto soimasi häntä siitä, että hän oli leikannut Saulin viitan lievettä.'),
(1676763,58,9,24,7,'Ja hän sanoi miehillensä: "Pois se! Herra varjelkoon minua tekemästä sitä herralleni, Herran voidellulle, että satuttaisin käteni häneen; sillä hän on Herran voideltu".'),
(1676764,58,9,24,8,'Ja Daavid kovisti miehiänsä eikä sallinut heidän hyökätä Saulin kimppuun. Niin Saul nousi luolasta ja meni matkaansa.'),
(1676765,58,9,24,9,'Senjälkeen Daavid myös nousi, lähti luolasta ja huusi Saulin jälkeen: "Minun herrani, kuningas!" Kun Saul katsahti taaksensa, kumartui Daavid kasvoilleen maahan ja osoitti kunnioitusta.'),
(1676766,58,9,24,10,'Ja Daavid sanoi Saulille: "Miksi sinä kuuntelet ihmisten puhetta, jotka sanovat: ''Daavid hankkii sinulle onnettomuutta''?'),
(1676767,58,9,24,11,'Katso, näethän nyt omin silmin, kuinka Herra tänä päivänä antoi sinut minun käsiini luolassa, mutta minä säästin sinut, vaikka minua neuvottiin tappamaan sinut; sillä minä ajattelin: ''Minä en satuta kättäni herraani; sillä hän on Herran voideltu''.'),
(1676768,58,9,24,12,'Katso itse, isäni, katso tätä viittasi liepeen kappaletta, joka on minun kädessäni. Kun minä leikkasin sen sinun viittasi liepeestä enkä sinua tappanut, niin ymmärrä siitä ja näe, ettei minulla ole tekeillä mitään pahaa tai rikollista ja etten minä ole sinua vastaan rikkonut, vaikka sinä vainoat minua ottaaksesi minulta hengen.'),
(1676769,58,9,24,13,'Herra tuomitkoon meidän välillämme, minun ja sinun, ja Herra kostakoon sinulle minun puolestani, mutta minun käteni ei sinuun satu.'),
(1676770,58,9,24,14,'On, niinkuin vanha sananlasku sanoo: ''Jumalattomuus tulee jumalattomista''; mutta minun käteni ei sinuun satu.'),
(1676771,58,9,24,15,'Kenen jälkeen Israelin kuningas on lähtenyt? Ketä sinä ajat takaa? Koiranraatoa, yhtä kirppua!'),
(1676772,58,9,24,16,'Herra olkoon tuomari ja tuomitkoon meidän välillämme, minun ja sinun; hän nähköön ja ajakoon minun asiani ja auttakoon minut sinun käsistäsi oikeuteeni."'),
(1676773,58,9,24,17,'Kun Daavid oli päättänyt tämän puheensa Saulille, sanoi Saul: "Eikö se ole sinun äänesi, poikani Daavid?" Ja Saul korotti äänensä ja itki.'),
(1676774,58,9,24,18,'Ja hän sanoi Daavidille: "Sinä olet minua vanhurskaampi, sillä sinä olet tehnyt minulle hyvää, vaikka minä olen tehnyt sinulle pahaa.'),
(1676775,58,9,24,19,'Sinä olet tänä päivänä osoittanut hyvyyttäsi minua kohtaan, kun et tappanut minua, vaikka Herra oli antanut minut sinun käsiisi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676776,58,9,24,20,'Sillä kun joku kohtaa vihollisensa, päästääkö hän hänet menemään rauhassa? Herra palkitkoon sinulle runsaasti sen, mitä olet tänä päivänä tehnyt minulle.'),
(1676777,58,9,24,21,'Ja katso, nyt minä tiedän, että sinä tulet kuninkaaksi ja että Israelin kuninkuus on pysyvä sinun kädessäsi.'),
(1676778,58,9,24,22,'Niin vanno nyt minulle Herran kautta, ettet hukuta minun jälkeläisiäni etkä hävitä minun nimeäni isäni suvusta."'),
(1676779,58,9,24,23,'Ja Daavid vannoi Saulille. Sitten Saul meni kotiinsa; mutta Daavid ja hänen miehensä nousivat vuorilinnaan.'),
(1676780,58,9,25,1,'Ja Samuel kuoli, ja koko Israel kokoontui pitämään hänen valittajaisiaan, ja he hautasivat hänet hänen kotipaikkaansa Raamaan. Ja Daavid nousi ja meni Paaranin erämaahan.'),
(1676781,58,9,25,2,'Ja Maaonissa oli mies, jolla oli karjataloutensa Karmelissa, ja se mies oli hyvin rikas: hänellä oli kolmetuhatta lammasta ja tuhat vuohta. Ja hän oli keritsemässä lampaitansa Karmelissa.'),
(1676782,58,9,25,3,'Miehen nimi oli Naabal, ja hänen vaimonsa nimi oli Abigail. Vaimo oli hyvin ymmärtäväinen ja vartaloltaan kaunis, mutta mies oli tyly ja menoissaan raaka; hän oli kaalebilainen.'),
(1676783,58,9,25,4,'Ja kun Daavid kuuli erämaassa, että Naabal keritsi lampaitansa,'),
(1676784,58,9,25,5,'lähetti hän sinne kymmenen nuorta miestä, ja Daavid sanoi nuorille miehille: "Menkää Karmeliin, ja kun tulette Naabalin luo, niin tervehtikää häntä minun nimessäni'),
(1676785,58,9,25,6,'ja sanokaa sille eläjälle: ''Sinä elät rauhassa; rauhassa elää myös sinun perheesi ja kaikki, mitä sinulla on.'),
(1676786,58,9,25,7,'Minä olen nyt kuullut, että sinulla on lammasten keritsiäiset. Sinun paimenesi ovat olleet meidän läheisyydessämme; me emme ole heitä loukanneet, eikä heiltä ole mitään hävinnyt koko sinä aikana, minkä ovat olleet Karmelissa.'),
(1676787,58,9,25,8,'Kysy nuorilta miehiltäsi, niin he sanovat sen sinulle. Saakoot siis nämä miehet armon sinun silmiesi edessä, sillä mehän olemme tulleet juhlapäivänä. Anna sentähden palvelijoillesi ja pojallesi Daavidille sitä, mitä sinulla on käsillä.''"'),
(1676788,58,9,25,9,'Kun Daavidin miehet tulivat sinne, puhuivat he Daavidin nimessä Naabalille tämän kaiken ja jäivät hiljaa odottamaan.'),
(1676789,58,9,25,10,'Mutta Naabal vastasi Daavidin palvelijoille ja sanoi: "Kuka Daavid on, kuka on Iisain poika? Tätä nykyä on paljon orjia, jotka karkaavat isäntäinsä luota.'),
(1676790,58,9,25,11,'Ottaisinko minä ruokani ja juomani ja teuraani, jotka olen teurastanut keritsiäisiini, ja antaisin ne miehille, jotka ovat kotoisin ties mistä?"'),
(1676791,58,9,25,12,'Niin Daavidin miehet kääntyivät ja menivät pois, ja tultuaan takaisin he kertoivat hänelle tämän kaiken.'),
(1676792,58,9,25,13,'Niin Daavid sanoi miehillensä: "Jokainen sitokoon miekkansa vyölleen". Ja jokainen sitoi miekkansa vyölleen; ja Daavid itsekin sitoi miekkansa vyölleen. Ja noin neljäsataa miestä lähti seuraamaan Daavidia, mutta kaksisataa jäi kuormaston luo.'),
(1676793,58,9,25,14,'Mutta eräs nuori mies toi sanan Abigailille, Naabalin vaimolle, ja sanoi: "Katso, Daavid on lähettänyt sanansaattajia erämaasta tervehtimään meidän isäntäämme, mutta hän vain haukkui heitä.'),
(1676794,58,9,25,15,'Ne miehet ovat kuitenkin olleet meille varsin hyviä: he eivät loukanneet meitä, eikä meiltä mitään hävinnyt koko sinä aikana, minkä kuljeskelimme heidän läheisyydessään ollessamme kedolla.'),
(1676795,58,9,25,16,'He olivat muurina meidän ympärillämme yöllä ja päivällä koko sen ajan, minkä oleskelimme heidän läheisyydessään paimentaessamme lampaita.'),
(1676796,58,9,25,17,'Niin ajattele nyt sinä ja katso, mitä voit tehdä, sillä onnettomuus uhkaa meidän isäntäämme ja koko hänen taloansa. Hän itse on kelvoton mies, niin ettei hänelle auta puhua."'),
(1676797,58,9,25,18,'Niin Abigail otti joutuin kaksisataa leipää, kaksi leiliä viiniä, viisi lampaanpaistia, viisi sea-mittaa paahdettuja jyviä, sata rusinakakkua ja kaksisataa viikunakakkua ja pani ne aasien selkään.'),
(1676798,58,9,25,19,'Ja hän sanoi palvelijoillensa: "Menkää minun edelläni, minä tulen jäljessänne". Mutta miehellensä Naabalille hän ei sitä ilmoittanut.'),
(1676799,58,9,25,20,'Kun hän sitten ratsasti aasilla alas mäkeä vuoren suojassa, niin katso, Daavid miehinensä tuli toista mäkeä alas häntä vastaan, niin että hän joutui kohtaamaan heidät.'),
(1676800,58,9,25,21,'Mutta Daavid oli sanonut: "Mitään saamatta minä olen suojellut kaikkea, mitä tällä miehellä oli erämaassa, niin ettei mitään ole hävinnyt kaikesta, mitä hänellä oli. Hän on palkinnut minulle hyvän pahalla.'),
(1676801,58,9,25,22,'Jumala rangaiskoon Daavidin vihamiehiä nyt ja vasta: totisesti, minä en jätä kaikesta hänen väestänsä huomenaamuksi henkiin yhtään miehenpuolta."'),
(1676802,58,9,25,23,'Mutta kun Abigail näki Daavidin, laskeutui hän kiiruusti aasin selästä maahan, lankesi kasvoilleen Daavidin eteen ja kumartui maahan.'),
(1676803,58,9,25,24,'Ja kun hän oli langennut hänen jalkainsa juureen, sanoi hän: "Minun on syy, herrani. Mutta salli palvelijattaresi puhua sinulle ja kuule palvelijattaresi sanoja.'),
(1676804,58,9,25,25,'Älköön herrani välittäkö mitään tuosta kelvottomasta miehestä, Naabalista, sillä nimi on miestä myöten. Naabal on hänen nimensä, ja houkkamainen hän on. Mutta minä, sinun palvelijattaresi, en ole nähnyt niitä miehiä, jotka sinä, herrani, lähetit.'),
(1676805,58,9,25,26,'Ja nyt, herrani, niin totta kuin Herra elää ja niin totta kuin sinä itse elät, jonka Herra on estänyt joutumasta verivelan alaiseksi ja auttamasta itseäsi omalla kädelläsi: käyköön nyt sinun vihamiehillesi ja kaikille, jotka hankkivat onnettomuutta minun herralleni, niinkuin Naabalille.'),
(1676806,58,9,25,27,'Ja nyt annettakoon tämä tervehdyslahja, jonka palvelijattaresi on herralleni tuonut, niille miehille, jotka seuraavat herraani.'),
(1676807,58,9,25,28,'Anna palvelijattaresi rikkomus anteeksi. Sillä Herra on rakentava minun herralleni pysyväisen huoneen, koska minun herrani käy Herran sotia; eikä mitään pahaa löydetä sinussa koko elinaikanasi.'),
(1676808,58,9,25,29,'Ja jos joku nousee vainoamaan sinua ja väijymään sinun henkeäsi, niin herrani henki on tallella elävien kukkarossa Herran, sinun Jumalasi, tykönä; mutta sinun vihollistesi hengen hän lingolla linkoaa pois.'),
(1676809,58,9,25,30,'Ja kun Herra tekee minun herralleni kaiken hyvän, josta hän on sinulle puhunut, ja määrää sinut Israelin ruhtinaaksi,'),
(1676810,58,9,25,31,'niin ei sinua kaada eikä herrani tuntoa vaivaa se, että olisit aiheettomasti vuodattanut verta ja että herrani olisi itse auttanut itseänsä. Mutta kun Herra on tekevä hyvää minun herralleni, niin muista palvelijatartasi."'),
(1676811,58,9,25,32,'Niin Daavid sanoi Abigailille: "Kiitetty olkoon Herra, Israelin Jumala, joka tänä päivänä lähetti sinut minua vastaan.'),
(1676812,58,9,25,33,'Ja siunattu olkoon sinun ymmärtäväisyytesi, ja siunattu ole sinä itse, joka tänä päivänä estit minut joutumasta verivelan alaiseksi ja auttamasta itseäni omalla kädelläni.'),
(1676813,58,9,25,34,'Mutta niin totta kuin Herra, Israelin Jumala, elää, hän, joka on pidättänyt minut tekemästä sinulle pahaa: jollet sinä joutuin olisi tullut minua vastaan, niin totisesti ei Naabalin väestä olisi huomenna aamun valjetessa ollut jäljellä yhtään miehenpuolta."'),
(1676814,58,9,25,35,'Sitten Daavid otti häneltä, mitä hän oli hänelle tuonut, ja sanoi hänelle: "Mene rauhassa kotiisi. Katso, minä olen kuullut sinua ja tehnyt sinulle mieliksi."'),
(1676815,58,9,25,36,'Kun Abigail sitten tuli Naabalin luo, oli tällä talossansa pidot, niinkuin kuninkaan pidot; ja Naabalin sydän oli iloinen, ja hän oli kovin juovuksissa. Niin hän ei kertonut Naabalille mitään, ennenkuin aamu valkeni.'),
(1676816,58,9,25,37,'Mutta seuraavana aamuna, kun Naabalista humala oli haihtunut, kertoi hänen vaimonsa hänelle, mitä oli tapahtunut. Silloin hänen sydämensä kuoleutui hänen povessaan, ja hän ikäänkuin kivettyi.'),
(1676817,58,9,25,38,'Ja noin kymmenen päivän kuluttua Herra löi Naabalia, niin että hän kuoli.'),
(1676818,58,9,25,39,'Kun Daavid kuuli, että Naabal oli kuollut, sanoi hän: "Kiitetty olkoon Herra, joka on kostanut Naabalille minun häväistykseni ja pidättänyt palvelijansa pahasta ja kääntänyt Naabalin pahuuden hänen oman päänsä päälle". Senjälkeen Daavid lähetti sanomaan Abigailille, että hän halusi ottaa hänet vaimokseen.'),
(1676819,58,9,25,40,'Ja kun Daavidin palvelijat tulivat Abigailin luo Karmeliin, puhuivat he hänelle ja sanoivat: "Daavid lähetti meidät sinun luoksesi ottamaan sinut hänelle vaimoksi".'),
(1676820,58,9,25,41,'Niin hän nousi ylös, kumartui kasvoilleen maahan ja sanoi: "Katso, palvelijattaresi on valmis rupeamaan orjattareksi ja pesemään herrani palvelijain jalat".'),
(1676821,58,9,25,42,'Sitten Abigail nousi kiiruusti ylös ja istuutui aasin selkään, samoin hänen viisi palvelijatartansa, jotka olivat hänellä seuralaisina. Ja niin hän seurasi Daavidin sanansaattajia ja tuli hänen vaimoksensa.'),
(1676822,58,9,25,43,'Daavid oli nainut myös Ahinoamin Jisreelistä, niin että he molemmat tulivat hänen vaimoikseen.'),
(1676823,58,9,25,44,'Mutta Saul oli antanut tyttärensä Miikalin, Daavidin vaimon, Paltille, Laiksen pojalle, joka oli kotoisin Gallimista.'),
(1676824,58,9,26,1,'Siifiläiset tulivat Saulin luo Gibeaan ja sanoivat: "Daavid piileksii Gibeat-Hakilassa, kallioerämaan puolella".'),
(1676825,58,9,26,2,'Niin Saul nousi ja meni Siifin erämaahan, ja hänen kanssansa kolmetuhatta Israelin valiomiestä, etsimään Daavidia Siifin erämaasta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676826,58,9,26,3,'Ja Saul leiriytyi Gibeat-Hakilaan, joka on kallioerämaan puolella tien varrella. Mutta Daavid oleskeli erämaassa. Ja kun Daavid huomasi, että Saul oli tullut hänen jäljessään erämaahan,'),
(1676827,58,9,26,4,'lähetti hän vakoojia ja sai varman tiedon Saulin tulosta.'),
(1676828,58,9,26,5,'Niin Daavid nousi ja meni siihen paikkaan, johon Saul oli leiriytynyt; ja Daavid näki, missä paikassa Saul ja hänen sotapäällikkönsä Abner, Neerin poika, makasivat. Saul näet makasi leirissä, ja väki oli asettunut hänen ympärilleen.'),
(1676829,58,9,26,6,'Ja Daavid puhui heettiläiselle Ahimelekille ja Abisaille, Serujan pojalle, Jooabin veljelle, ja sanoi: "Kuka lähtee minun kanssani Saulin tykö leiriin?" Abisai vastasi: "Minä lähden sinun kanssasi".'),
(1676830,58,9,26,7,'Niin Daavid ja Abisai menivät yöllä väen luo ja näkivät, että Saul makasi ja nukkui leirissä, ja hänen keihäänsä oli pistettynä maahan hänen päänpohjiinsa; mutta Abner ja väki makasivat hänen ympärillänsä.'),
(1676831,58,9,26,8,'Ja Abisai sanoi Daavidille: "Jumala on tänä päivänä antanut vihamiehesi sinun käsiisi. Salli nyt minun keihästää hänet maahan; yksi isku vain, toista ei tarvita."'),
(1676832,58,9,26,9,'Mutta Daavid vastasi Abisaille: "Älä surmaa häntä; sillä kuka on rankaisematta satuttanut kätensä Herran voideltuun?"'),
(1676833,58,9,26,10,'Ja Daavid sanoi vielä: "Niin totta kuin Herra elää: Herra itse lyö hänet, tahi hänen kuolinpäivänsä tulee, tahi hän menee sotaan ja tuhoutuu siellä.'),
(1676834,58,9,26,11,'Mutta minä en satuta kättäni Herran voideltuun. Pois se, Herra varjelkoon! Vaan ota nyt keihäs hänen päänpohjistaan ja vesiastia, ja sitten menkäämme."'),
(1676835,58,9,26,12,'Ja Daavid otti keihään ja vesiastian Saulin päänpohjista, ja sitten he menivät tiehensä. Eikä kukaan nähnyt tai huomannut sitä, eikä kukaan herännyt, vaan he nukkuivat kaikki; sillä Herran lähettämä raskas uni oli vallannut heidät.'),
(1676836,58,9,26,13,'Kun sitten Daavid oli tullut toiselle puolelle, asettui hän kauas vuoren laelle, pitkän välimatkan päähän.'),
(1676837,58,9,26,14,'Ja Daavid huusi väelle ja Abnerille, Neerin pojalle, ja sanoi: "Etkö vastaa, Abner?" Abner vastasi ja sanoi: "Kuka sinä olet, joka niin huudat kuninkaalle?"'),
(1676838,58,9,26,15,'Daavid sanoi Abnerille: "Sinähän olet mies, eikä sinun vertaistasi ole Israelissa. Miksi et sitten vartioinut herraasi, kuningasta? Sillä joku kansasta tuli surmaamaan kuningasta, sinun herraasi.'),
(1676839,58,9,26,16,'Ei ole hyvin tehty, mitä sinä olet tehnyt. Niin totta kuin Herra elää: te olette kuoleman omat, koska ette vartioineet herraanne, Herran voideltua. Katsohan nyt: missä ovat kuninkaan keihäs ja vesiastia, jotka olivat hänen päänpohjissaan?"'),
(1676840,58,9,26,17,'Niin Saul tunsi Daavidin äänen ja sanoi: "Sehän on sinun äänesi, poikani Daavid". Daavid vastasi: "Niin on, herrani, kuningas".'),
(1676841,58,9,26,18,'Ja hän sanoi vielä: "Miksi herrani vainoaa palvelijaansa? Mitä minä olen tehnyt, tahi mitä pahaa minulla on tekeillä?'),
(1676842,58,9,26,19,'Kuulkoon nyt herrani, kuningas, mitä hänen palvelijansa sanoo: Jos Herra on yllyttänyt sinut minua vastaan, niin saakoon hän tuntea ruokauhrin hajua; mutta jos sen ovat tehneet ihmiset, niin olkoot he kirotut Herran edessä, koska tänä päivänä karkoittavat minut pois Herran perintöosasta, sanoen: ''Mene ja palvele muita jumalia''.'),
(1676843,58,9,26,20,'Älköön kuitenkaan minun vereni vuotako maahan siellä kaukana Herran kasvoista. Niin, Israelin kuningas on lähtenyt liikkeelle etsimään yhtä kirppua, niinkuin ajetaan peltokanaa vuorilla."'),
(1676844,58,9,26,21,'Niin Saul sanoi: "Minä olen tehnyt syntiä. Tule takaisin, poikani Daavid; sillä minä en enää tee sinulle pahaa, koska minun henkeni tänä päivänä on ollut kallis sinun silmissäsi. Katso, minä olen tehnyt tyhmästi ja erehtynyt kovin pahoin."'),
(1676845,58,9,26,22,'Daavid vastasi ja sanoi: "Tässä on kuninkaan keihäs; tulkoon joku miehistä tänne ottamaan sen.'),
(1676846,58,9,26,23,'Herra palkitsee jokaiselle hänen vanhurskautensa ja uskollisuutensa. Sillä Herra antoi sinut tänä päivänä minun käsiini, mutta minä en tahtonut satuttaa kättäni Herran voideltuun.'),
(1676847,58,9,26,24,'Katso, niinkuin sinun henkesi tänä päivänä on ollut suuriarvoinen minun silmissäni, niin on myös minun henkeni oleva suuriarvoinen Herran silmissä, ja hän on pelastava minut kaikesta hädästä."'),
(1676848,58,9,26,25,'Saul sanoi Daavidille: "Siunattu ole sinä, poikani Daavid! Mihin sinä ryhdyt, siihen sinä pystyt." Sitten Daavid meni pois, ja Saul palasi kotiinsa.'),
(1676849,58,9,27,1,'Mutta Daavid ajatteli mielessään: "Kerran Saulin käsi kuitenkin tuhoaa minut. Minulla ei ole muuta neuvoa kuin pelastautua filistealaisten maahan. Silloin Saul huomaa turhaksi enää etsiä minua kaikkialta Israelin alueelta, ja niin minä pelastun hänen käsistänsä."'),
(1676850,58,9,27,2,'Niin Daavid nousi ja meni, hän ja ne kuusisataa miestä, jotka olivat hänen kanssaan, Aakiin, Maaokin pojan, Gatin kuninkaan, luo.'),
(1676851,58,9,27,3,'Ja Daavid asettui miehinensä Aakiin luo Gatiin. Jokaisella oli perheensä mukanaan, Daavidilla molemmat vaimonsa, jisreeliläinen Ahinoam ja karmelilainen Abigail, Naabalin vaimo.'),
(1676852,58,9,27,4,'Kun sitten Saulille ilmoitettiin, että Daavid oli paennut Gatiin, ei hän enää etsinyt häntä.'),
(1676853,58,9,27,5,'Ja Daavid sanoi Aakiille: "Jos minä olen saanut armon sinun silmiesi edessä, niin annettakoon minulle paikka jossakin maaseutukaupungissa, asuakseni siellä. Sillä miksi sinun palvelijasi asuisi kuninkaan kaupungissa sinun luonasi?"'),
(1676854,58,9,27,6,'Niin Aakis antoi hänelle sinä päivänä Siklagin. Sentähden on Siklag Juudan kuningasten oma vielä tänä päivänä.'),
(1676855,58,9,27,7,'Aika, jonka Daavid asui filistealaisten maassa, oli vuosi ja neljä kuukautta.'),
(1676856,58,9,27,8,'Daavid lähti miehinensä, ja he tekivät ryöstöretkiä gesurilaisten, geresiläisten ja amalekilaisten maahan. Sillä nämä asuivat siinä maassa, joka muinoin ulottui Suuriin päin ja Egyptin maahan asti.'),
(1676857,58,9,27,9,'Ja hävittäessään maata Daavid ei jättänyt yhtään miestä eikä naista henkiin, otti lampaat, raavaat, aasit, kamelit ja vaatteet ja palasi sitten takaisin ja tuli Aakiin luo.'),
(1676858,58,9,27,10,'Ja kun Aakis kysyi: "Ette kai ole tänään tehneet ryöstöretkeä?" vastasi Daavid: "Kyllä, Juudan Etelämaahan", tahi: "Jerahmeelilaisten Etelämaahan", tahi: "Keeniläisten Etelämaahan".'),
(1676859,58,9,27,11,'Daavid ei jättänyt yhtään miestä eikä naista henkiin, vietäväksi Gatiin, sillä hän ajatteli: "Ne voisivat kertoa meistä ja sanoa: ''Näin on Daavid tehnyt, tämä on ollut hänen tapansa kaiken aikaa, minkä hän asui filistealaisten maassa''".'),
(1676860,58,9,27,12,'Ja Aakis luotti Daavidiin ja ajatteli: "Hän on saattanut itsensä kansansa Israelin vihoihin ja tulee olemaan minun palvelijani ainiaan".'),
(1676861,58,9,28,1,'Siihen aikaan filistealaiset kokosivat joukkonsa sotaretkelle Israelia vastaan. Ja Aakis sanoi Daavidille: "Tiedä, että sinun on miehinesi lähdettävä minun kanssani sotajoukon mukana".'),
(1676862,58,9,28,2,'Daavid vastasi Aakiille: "Hyvä! Sinä tulet tietämään, mitä palvelijasi saa aikaan." Aakis sanoi Daavidille: "Siispä minä asetan sinut oman pääni vartijaksi koko täksi aikaa".'),
(1676863,58,9,28,3,'Samuel oli kuollut, ja koko Israel oli pitänyt hänelle valittajaiset; ja he olivat haudanneet hänet hänen kaupunkiinsa Raamaan. Ja Saul oli toimittanut pois maasta vainaja- ja tietäjähenkien manaajat.'),
(1676864,58,9,28,4,'Ja filistealaiset kokoontuivat, ja he tulivat ja leiriytyivät Suunemiin. Niin Saulkin kokosi koko Israelin, ja he leiriytyivät Gilboaan.'),
(1676865,58,9,28,5,'Mutta kun Saul näki filistealaisten leirin, peljästyi hän, ja hänen sydämensä vapisi kovin.'),
(1676866,58,9,28,6,'Ja Saul kysyi Herralta, mutta Herra ei vastannut hänelle, ei unissa, ei uurimin eikä profeettain kautta.'),
(1676867,58,9,28,7,'Niin Saul sanoi palvelijoillensa: "Etsikää minulle joku vaimo, jolla on vallassaan vainajahenki, niin minä menen hänen luoksensa ja kysyn häneltä". Hänen palvelijansa vastasivat hänelle: "Katso, Een-Doorissa on vaimo, jolla on vallassaan vainajahenki".'),
(1676868,58,9,28,8,'Silloin Saul teki itsensä tuntemattomaksi, pukeutui toisiin vaatteisiin ja lähti matkalle, mukanansa kaksi miestä. He tulivat yöllä vaimon luo, ja hän sanoi: "Ennusta minulle vainajahengen avulla ja nostata minulle se, jonka minä sinulle sanon".'),
(1676869,58,9,28,9,'Mutta vaimo vastasi hänelle: "Sinä tiedät kyllä, mitä Saul on tehnyt, kuinka hän on hävittänyt vainaja- ja tietäjähenkien manaajat maasta. Miksi virität minulle ansan tuottaaksesi minulle kuoleman?"'),
(1676870,58,9,28,10,'Niin Saul vannoi hänelle Herran kautta ja sanoi: "Niin totta kuin Herra elää: tästä asiasta ei sinulle tule mitään syytä".'),
(1676871,58,9,28,11,'Vaimo kysyi: "Kenen minä nostatan sinulle?" Hän vastasi: "Nostata minulle Samuel".'),
(1676872,58,9,28,12,'Mutta kun vaimo näki Samuelin, huudahti hän kovalla äänellä. Ja vaimo sanoi Saulille: "Miksi olet pettänyt minut? Sinähän olet Saul."'),
(1676873,58,9,28,13,'Kuningas sanoi hänelle: "Älä pelkää. Mitä sinä näet?" Vaimo vastasi Saulille: "Minä näen jumal''olennon nousevan maasta".'),
(1676874,58,9,28,14,'Hän kysyi häneltä: "Minkä näköinen hän on?" Vaimo vastasi: "Vanha mies nousee ylös, viittaan verhoutuneena". Niin Saul ymmärsi, että se oli Samuel, ja kumartui kasvoilleen maahan ja osoitti kunnioitusta.'),
(1676875,58,9,28,15,'Ja Samuel sanoi Saulille: "Miksi sinä olet häirinnyt minua ja nostattanut minut?" Saul vastasi: "Minä olen suuressa hädässä: filistealaiset sotivat minua vastaan, ja Jumala on poistunut minusta eikä vastaa minulle enää, ei profeettain kautta eikä unissa. Niin minä kutsutin sinut, että ilmoittaisit minulle, mitä minun on tehtävä."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676876,58,9,28,16,'Mutta Samuel vastasi: "Miksi sinä minulta kysyt, kun Herra on poistunut sinusta ja tullut vihamieheksesi?'),
(1676877,58,9,28,17,'Herra on tehnyt sen, minkä hän on minun kauttani puhunut: Herra on reväissyt kuninkuuden sinun kädestäsi ja on antanut sen toiselle, Daavidille.'),
(1676878,58,9,28,18,'Kun sinä et kuullut Herran ääntä etkä tehnyt Amalekille, mitä hänen hehkuva vihansa vaati, sentähden Herra on tänä päivänä tehnyt sinulle tämän.'),
(1676879,58,9,28,19,'Herra antaa myöskin Israelin yhdessä sinun kanssasi filistealaisten käsiin, ja huomenna olet sinä poikinesi minun tykönäni; myös Israelin leirin Herra antaa filistealaisten käsiin."'),
(1676880,58,9,28,20,'Niin Saul siinä tuokiossa kaatui pitkin koko pituuttaan maahan, sillä hän peljästyi kovin Samuelin puheesta; myös olivat häneltä voimat lopussa, sillä vuorokauteen hän ei ollut syönyt mitään.'),
(1676881,58,9,28,21,'Mutta vaimo meni Saulin luo, ja kun hän näki, että tämä oli kauhun vallassa, sanoi hän hänelle: "Katso, palvelijattaresi kuuli sinua, minä panin henkeni kämmenelleni ja tottelin käskyä, jonka sinä minulle lausuit.'),
(1676882,58,9,28,22,'Niin kuule nyt sinäkin palvelijatartasi ja salli minun asettaa sinun eteesi palanen leipää, ja syö, että olisit voimissasi, kun lähdet matkalle."'),
(1676883,58,9,28,23,'Hän epäsi ja sanoi: "Minä en syö". Mutta kun hänen palvelijansa yhdessä vaimon kanssa pyytämällä pyysivät häntä, kuuli hän heitä; ja hän nousi maasta ja istui vuoteelle.'),
(1676884,58,9,28,24,'Ja vaimolla oli juottovasikka kotonaan; sen hän teurasti joutuin. Sitten hän otti jauhoja, sotki ne ja leipoi niistä happamattomia leipiä.'),
(1676885,58,9,28,25,'Ja hän toi ruuan Saulin ja hänen palvelijainsa eteen, ja he söivät. Sitten he nousivat ja lähtivät samana yönä.'),
(1676886,58,9,29,1,'Filistealaiset kokosivat kaikki joukkonsa Afekiin, ja israelilaiset olivat leiriytyneet lähteelle, joka on Jisreelissä.'),
(1676887,58,9,29,2,'Ja kun filistealaisten ruhtinaat tulivat satoineen ja tuhansineen, ja Daavid miehineen tuli viimeiseksi Aakiin kanssa,'),
(1676888,58,9,29,3,'sanoivat filistealaisten päälliköt: "Mitä nuo hebrealaiset täällä tekevät?" Aakis vastasi filistealaisten päälliköille: "Tämähän on Daavid, Saulin, Israelin kuninkaan, palvelija, joka on ollut minun luonani toista vuotta, enkä minä ole havainnut hänessä mitään siitä päivästä alkaen, jona hän siirtyi minun luokseni, tähän päivään asti".'),
(1676889,58,9,29,4,'Niin filistealaisten päälliköt vihastuivat häneen; ja filistealaisten päälliköt sanoivat hänelle: "Toimita tämä mies takaisin; palatkoon hän siihen paikkaan, jonka sinä olet hänelle määrännyt. Älköön hän tulko meidän kanssamme taisteluun, ettei hän taistelussa tulisi meidän vastustajaksemme. Sillä miten hän voisi hankkia itselleen Herransa suosion paremmin kuin näiden miesten päillä?'),
(1676890,58,9,29,5,'Eikö tämä ole se Daavid, jolle he karkeloiden virittivät tämän laulun: ''Saul voitti tuhat, mutta Daavid kymmenentuhatta''?"'),
(1676891,58,9,29,6,'Niin Aakis kutsui Daavidin ja sanoi hänelle: "Niin totta kuin Herra elää: sinä olet rehellinen, ja minulle olisi mieleen, että olisit täällä leirissä, lähtisit ja tulisit minun kanssani; sillä minä en ole havainnut mitään pahaa sinussa siitä päivästä alkaen, jona tulit minun luokseni, tähän päivään asti. Mutta ruhtinaille sinä et ole mieluinen.'),
(1676892,58,9,29,7,'Lähde siis takaisin ja mene rauhassa, ettet tekisi mitään, joka ei olisi filistealaisten ruhtinaille mieleen."'),
(1676893,58,9,29,8,'Daavid sanoi Aakiille: "Mitä minä olen tehnyt, ja mitä olet havainnut palvelijassasi siitä päivästä alkaen, jona minä tulin sinun palvelukseesi, tähän päivään asti, koska en saa tulla taistelemaan herrani, kuninkaan, vihollisia vastaan?"'),
(1676894,58,9,29,9,'Aakis vastasi ja sanoi Daavidille: "Minä tiedän, että sinä olet minulle mieluinen niinkuin Jumalan enkeli; mutta filistealaisten päälliköt sanovat: ''Hän ei saa lähteä meidän kanssamme taisteluun''.'),
(1676895,58,9,29,10,'Nouse siis huomenaamuna varhain, sinä ja sinun herrasi palvelijat, jotka ovat tulleet kanssasi, ja lähtekää matkaan huomenaamuna varhain, kun päivä valkenee."'),
(1676896,58,9,29,11,'Niin Daavid miehinensä lähti varhain seuraavana aamuna matkalle palatakseen filistealaisten maahan. Mutta filistealaiset menivät Jisreeliin.'),
(1676897,58,9,30,1,'Kun Daavid miehinensä kolmantena päivänä tuli Siklagiin, olivat amalekilaiset tehneet ryöstöretken Etelämaahan ja Siklagiin, ja he olivat vallanneet Siklagin ja polttaneet sen tulella.'),
(1676898,58,9,30,2,'Naiset, mitä siellä oli, sekä pienet että suuret, he olivat ottaneet vangiksi, surmaamatta ketään; he olivat vieneet ne pois ja menneet matkoihinsa.'),
(1676899,58,9,30,3,'Kun Daavid miehinensä tuli kaupunkiin, niin katso, se oli tulella poltettu, ja heidän vaimonsa, poikansa ja tyttärensä oli otettu vangiksi.'),
(1676900,58,9,30,4,'Silloin Daavid ja väki, joka oli hänen kanssaan, korottivat äänensä ja itkivät, kunnes eivät enää jaksaneet itkeä.'),
(1676901,58,9,30,5,'Vangiksi oli otettu myös Daavidin molemmat vaimot, jisreeliläinen Ahinoam ja Abigail, karmelilaisen Naabalin vaimo.'),
(1676902,58,9,30,6,'Ja Daavid joutui suureen hätään, sillä kansa aikoi kivittää hänet: niin katkeroitunut oli koko kansa, kukin poikiensa ja tyttäriensä tähden. Mutta Daavid rohkaisi mielensä Herrassa, Jumalassansa.'),
(1676903,58,9,30,7,'Ja Daavid sanoi pappi Ebjatarille, Ahimelekin pojalle: "Tuo minulle kasukka". Niin Ebjatar toi kasukan Daavidille.'),
(1676904,58,9,30,8,'Ja Daavid kysyi Herralta: "Ajanko takaa tuota rosvojoukkoa? Saavutanko minä sen?" Hän vastasi hänelle: "Aja, sillä sinä saavutat sen ja pelastat pelastettavat".'),
(1676905,58,9,30,9,'Niin Daavid lähti, hän ja ne kuusisataa miestä, jotka olivat hänen kanssaan, ja he tulivat Besorin purolle; siihen pysähtyivät ne, jotka olivat jääneet muista jälkeen.'),
(1676906,58,9,30,10,'Mutta Daavid jatkoi takaa-ajoa neljänsadan miehen kanssa; sillä niitä, jotka väsyneinä pysähtyivät eivätkä menneet Besorin puron poikki, oli kaksisataa miestä.'),
(1676907,58,9,30,11,'Ja he tapasivat kedolla egyptiläisen miehen ja toivat hänet Daavidin luo. He antoivat hänelle leipää syödä ja vettä juoda,'),
(1676908,58,9,30,12,'ja he antoivat vielä hänelle viikunakakun ja kaksi rusinakakkua syödä. Silloin hän virkosi henkiin; sillä hän ei ollut syönyt eikä juonut kolmeen vuorokauteen.'),
(1676909,58,9,30,13,'Ja Daavid kysyi häneltä: "Kenen olet miehiä ja mistä tulet?" Hän vastasi: "Minä olen egyptiläinen nuorukainen, erään amalekilaisen miehen palvelija; mutta minun herrani jätti minut, sillä minä sairastuin kolme päivää sitten.'),
(1676910,58,9,30,14,'Me teimme ryöstöretken kreettien, Juudan ja Kaalebin Etelämaahan ja poltimme Siklagin tulella."'),
(1676911,58,9,30,15,'Daavid sanoi hänelle: "Vietkö minut tuon rosvojoukon luo?" Hän vastasi: "Vanno minulle Jumalan kautta, ettet surmaa minua etkä luovuta minua herrani käsiin, niin minä vien sinut sen rosvojoukon luo".'),
(1676912,58,9,30,16,'Ja hän vei hänet sinne; ja katso, heitä oli hajallaan maassa kaikkialla syömässä, juomassa ja juhlimassa kaikella sillä suurella saaliilla, jonka olivat ottaneet filistealaisten maasta ja Juudan maasta.'),
(1676913,58,9,30,17,'Niin Daavid kaatoi heitä aamuhämärästä iltaan asti; eikä heistä pelastunut kuin neljäsataa nuorta miestä, jotka nousivat kamelien selkään ja pakenivat.'),
(1676914,58,9,30,18,'Ja Daavid pelasti kaikki, mitä amalekilaiset olivat ottaneet; myös molemmat vaimonsa Daavid pelasti.'),
(1676915,58,9,30,19,'Ei ketään puuttunut, ei pientä eikä suurta, ei kenenkään poikaa eikä kenenkään tytärtä eikä saalista tai muuta, mitä he olivat ottaneet itsellensä; kaiken Daavid toi takaisin.'),
(1676916,58,9,30,20,'Daavid otti myös kaikki lampaat ja raavaat, ja niitä ajettiin muun karjan edellä ja huudettiin: "Tämä on Daavidin saalis!"'),
(1676917,58,9,30,21,'Ja kun Daavid tuli niiden kahdensadan miehen luo, jotka olivat väsyneet, jaksamatta seurata Daavidia, ja jotka oli jätetty Besorin purolle, tulivat he Daavidia vastaan ja sitä väkeä, joka oli hänen kanssansa; ja kun Daavid väkineen lähestyi, tervehti hän heitä.'),
(1676918,58,9,30,22,'Mutta kaikenlaiset huonot ja kelvottomat miehet niiden joukosta, jotka olivat kulkeneet Daavidin mukana, rupesivat sanomaan: "Koska nämä eivät ole kulkeneet meidän mukanamme, emme me anna heille mitään saaliista, jonka pelastimme, paitsi kunkin vaimon ja lapset; viekööt ne ja menkööt matkoihinsa".'),
(1676919,58,9,30,23,'Mutta Daavid sanoi: "Älkää tehkö niin, veljeni, sen jälkeen, mitä Herra on meille suonut, kun hän varjeli meidät ja antoi meidän käsiimme rosvojoukon, joka hyökkäsi meidän kimppuumme.'),
(1676920,58,9,30,24,'Ja kukapa teitä kuulisi tässä asiassa? Sillä taisteluun menevällä ja kuormaston luo jäävällä on oleva yhtäläinen osuus; heidän on jaettava tasan."'),
(1676921,58,9,30,25,'Ja sillensä asia jäi silloin ja sen jälkeenkin: hän teki sen säännöksi ja tavaksi Israelissa, aina tähän päivään asti.'),
(1676922,58,9,30,26,'Kun Daavid tuli Siklagiin, lähetti hän osan saaliista Juudan vanhimmille, ystävillensä, sanoen: "Tässä on teille tervehdyslahja siitä saaliista, joka otettiin Herran vihollisilta" -'),
(1676923,58,9,30,27,'lahja niille, jotka olivat Beetelissä, Etelämaan Raamotissa, Jattirissa,'),
(1676924,58,9,30,28,'Aroerissa, Sifmotissa, Estemoassa,'),
(1676925,58,9,30,29,'Raakalissa, jerahmeelilaisten kaupungeissa, keeniläisten kaupungeissa,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676926,58,9,30,30,'Hormassa, Boor-Aasanissa, Atakissa'),
(1676927,58,9,30,31,'ja Hebronissa, ja samoin lahja kaikille muille paikkakunnille, joissa Daavid miehinensä oli kulkenut.'),
(1676928,58,9,31,1,'Mutta filistealaiset taistelivat Israelia vastaan. Ja Israelin miehet pakenivat filistealaisia, ja heitä kaatui surmattuina Gilboan vuorella.'),
(1676929,58,9,31,2,'Ja filistealaiset pääsivät Saulin ja hänen poikiensa kintereille, ja filistealaiset surmasivat Joonatanin, Abinadabin ja Malkisuan, Saulin pojat.'),
(1676930,58,9,31,3,'Ja kun taistelu kiihtyi ankaraksi Saulia vastaan ja jousimiehet keksivät hänet, joutui hän suureen hätään jousimiesten ahdistaessa.'),
(1676931,58,9,31,4,'Ja Saul sanoi aseenkantajallensa: "Paljasta miekkasi ja lävistä sillä minut, etteivät nuo ympärileikkaamattomat tulisi lävistämään minua ja pitämään minua pilkkanaan". Mutta hänen aseenkantajansa ei tahtonut, sillä hän pelkäsi kovin. Niin Saul itse otti miekan ja heittäytyi siihen.'),
(1676932,58,9,31,5,'Mutta kun hänen aseenkantajansa näki, että Saul oli kuollut, heittäytyi hänkin miekkaansa ja kuoli hänen kanssansa.'),
(1676933,58,9,31,6,'Niin kuolivat sinä päivänä yhdessä Saul, hänen kolme poikaansa ja hänen aseenkantajansa ynnä kaikki hänen miehensä.'),
(1676934,58,9,31,7,'Ja kun Israelin miehet, jotka asuivat tuolla puolella laakson ja tuolla puolella Jordanin, huomasivat, että Israelin miehet olivat paenneet ja että Saul poikinensa oli kuollut, jättivät he kaupungit ja pakenivat, ja filistealaiset tulivat ja asettuivat niihin.'),
(1676935,58,9,31,8,'Seuraavana päivänä filistealaiset tulivat ryöstämään surmattuja ja löysivät Saulin ja hänen kolme poikaansa kaatuneina Gilboan vuorella.'),
(1676936,58,9,31,9,'Niin he löivät häneltä pään poikki, ryöstivät häneltä aseet ja lähettivät ne ympäri filistealaisten maata, julistaaksensa voitonsanomaa epäjumaliensa temppeleissä ja kansan seassa.'),
(1676937,58,9,31,10,'Ja he asettivat hänen aseensa Astarten temppeliin, mutta hänen ruumiinsa he kiinnittivät Beet-Seanin muurille.'),
(1676938,58,9,31,11,'Kun Gileadin Jaabeksen asukkaat kuulivat, mitä filistealaiset olivat tehneet Saulille,'),
(1676939,58,9,31,12,'nousivat he, kaikki sotakuntoiset miehet, kulkivat kaiken yötä ja ottivat Saulin ja hänen poikiensa ruumiit alas Beet-Seanin muurilta, menivät Jaabekseen ja polttivat ne siellä.'),
(1676940,58,10,1,1,'Saulin kuoleman jälkeen, kun Daavid, voitettuaan amalekilaiset, oli palannut takaisin ja ollut Siklagissa pari päivää,'),
(1676941,58,10,1,2,'tuli kolmantena päivänä eräs mies leiristä Saulin luota, vaatteet reväistyinä ja multaa pään päällä. Ja tullessaan Daavidin luo hän heittäytyi maahan ja osoitti kunnioitusta.'),
(1676942,58,10,1,3,'Daavid kysyi häneltä: "Mistä tulet?" Hän vastasi hänelle: "Minä olen päässyt pakoon Israelin leiristä".'),
(1676943,58,10,1,4,'Niin Daavid sanoi hänelle: "Miten on asiat? Kerro minulle." Hän vastasi: "Väki on paennut taistelusta, paljon väkeä on kaatunut ja kuollut; myöskin Saul ja hänen poikansa Joonatan ovat kuolleet".'),
(1676944,58,10,1,5,'Daavid kysyi nuorelta mieheltä, joka kertoi tämän hänelle: "Mistä tiedät, että Saul ja hänen poikansa Joonatan ovat kuolleet?"'),
(1676945,58,10,1,6,'Nuori mies, joka oli kertonut hänelle tämän, vastasi: "Minä tulin sattumalta Gilboan vuorelle, ja katso, Saul nojasi keihääseensä, ja sotavaunut ja ratsumiehet ahdistivat häntä.'),
(1676946,58,10,1,7,'Hän kääntyi taakseen ja nähdessään minut hän huusi minua; minä vastasin: ''Tässä olen''.'),
(1676947,58,10,1,8,'Niin hän kysyi minulta: ''Kuka olet?'' Minä vastasin hänelle: ''Olen amalekilainen''.'),
(1676948,58,10,1,9,'Sitten hän sanoi minulle: ''Astu luokseni ja surmaa minut, sillä minä olen kangistumassa, vaikka olenkin vielä täysin hengissä''.'),
(1676949,58,10,1,10,'Niin minä astuin hänen luoksensa ja surmasin hänet, sillä minä käsitin, ettei hän sortumisensa jälkeen jäisi henkiin. Ja minä otin kruunun, joka oli hänen päässänsä, ja rannerenkaan, joka oli hänen käsivarressaan, ja toin ne tänne herralleni."'),
(1676950,58,10,1,11,'Niin Daavid tarttui vaatteisiinsa ja repäisi ne; samoin tekivät kaikki miehet, jotka olivat hänen kanssansa.'),
(1676951,58,10,1,12,'Ja he pitivät valittajaisia ja itkivät ja paastosivat iltaan asti Saulin ja hänen poikansa Joonatanin tähden ja Herran kansan tähden ja Israelin heimon tähden, koska he olivat kaatuneet miekkaan.'),
(1676952,58,10,1,13,'Ja Daavid kysyi nuorelta mieheltä, joka oli hänelle kertonut tämän: "Mistä sinä olet?" Hän vastasi: "Minä olen täällä muukalaisena elävän amalekilaisen miehen poika".'),
(1676953,58,10,1,14,'Daavid sanoi hänelle: "Kuinka et peljännyt ojentaa kättäsi tuhotaksesi Herran voidellun?"'),
(1676954,58,10,1,15,'Ja Daavid kutsui yhden palvelijoistaan ja sanoi: "Käy tänne, lyö hänet kuoliaaksi". Ja hän iski hänet kuoliaaksi.'),
(1676955,58,10,1,16,'Mutta Daavid sanoi hänelle: "Sinun veresi tulkoon oman pääsi päälle, sillä oma suusi on todistanut sinua vastaan, kun sanoit: ''Minä olen surmannut Herran voidellun''".'),
(1676956,58,10,1,17,'Ja Daavid viritti tämän itkuvirren Saulista ja hänen pojastaan Joonatanista'),
(1676957,58,10,1,18,'ja käski opettaa sen, "Jousilaulun", Juudan pojille: katso, se on kirjoitettuna "Oikeamielisen kirjassa":'),
(1676958,58,10,1,19,'"Sinun kaunistuksesi, Israel, on surmattuna kukkuloillasi. Kuinka ovatkaan sankarit kaatuneet!'),
(1676959,58,10,1,20,'Älkää ilmoittako sitä Gatissa, älkää julistako voitonsanomaa Askelonin kaduilla, etteivät filistealaisten tyttäret iloitsisi, etteivät ympärileikkaamattomain tyttäret riemuitsisi.'),
(1676960,58,10,1,21,'Te Gilboan vuoret, älköön teille kastetta tulko, älköön sadetta, älköön peltoja, joista anteja uhrataan. Sillä siellä on poisviskattuna sankarien kilpi, Saulin kilpi, öljyllä voitelematonna.'),
(1676961,58,10,1,22,'Kaatuneitten verta, sankarien ytimiä ei Joonatanin jousi väistänyt, eikä tyhjänä palannut Saulin miekka.'),
(1676962,58,10,1,23,'Saul ja Joonatan, rakkaat ja armaat, olivat elämässä ja kuolemassa erottamattomat, olivat nopeammat kuin kotkat, leijonia väkevämmät.'),
(1676963,58,10,1,24,'Te Israelin tyttäret, itkekää Saulia, häntä, joka puetti teidät purppuraan ja koristeihin, joka kiinnitti pukuunne kultahelyjä.'),
(1676964,58,10,1,25,'Kuinka ovat sankarit taistelussa kaatuneet! Joonatan on surmattuna kukkuloillasi.'),
(1676965,58,10,1,26,'Minä suren sinua, veljeni Joonatan; sinä olit minulle ylen rakas. Rakkautesi oli minulle ihmeellisempi kuin naisen rakkaus.'),
(1676966,58,10,1,27,'Kuinka ovatkaan sankarit kaatuneet, kuinka ovat hukkuneet taisteluaseet!"'),
(1676967,58,10,2,1,'Sen jälkeen Daavid kysyi Herralta: "Menenkö minä johonkin Juudan kaupunkiin?" Herra vastasi hänelle: "Mene". Ja Daavid kysyi: "Mihinkä minä menen?" Hän vastasi: "Hebroniin".'),
(1676968,58,10,2,2,'Niin Daavid meni sinne, mukanaan molemmat vaimonsa, jisreeliläinen Ahinoam ja Abigail, karmelilaisen Naabalin vaimo.'),
(1676969,58,10,2,3,'Ja Daavid vei sinne myös miehet, jotka olivat hänen kanssaan, kunkin perheinensä; ja he asettuivat Hebronin ympärillä oleviin kaupunkeihin.'),
(1676970,58,10,2,4,'Ja Juudan miehet tulivat ja voitelivat siellä Daavidin Juudan heimon kuninkaaksi. Kun Daavidille ilmoitettiin, että Gileadin Jaabeksen miehet olivat haudanneet Saulin,'),
(1676971,58,10,2,5,'lähetti Daavid lähettiläät Gileadin Jaabeksen miesten luo sanomaan heille: "Herra siunatkoon teitä, koska olette osoittaneet herrallenne Saulille laupeutta hautaamalla hänet.'),
(1676972,58,10,2,6,'Osoittakoon nyt Herra laupeutta ja uskollisuutta teitä kohtaan. Minäkin teen teille hyvää, koska tämän teitte.'),
(1676973,58,10,2,7,'Rohkaiskaa siis itsenne ja olkaa urhoolliset; teidän herranne Saul tosin on kuollut, mutta Juudan heimo on voidellut kuninkaaksensa minut."'),
(1676974,58,10,2,8,'Mutta Abner, Neerin poika, Saulin sotapäällikkö, otti Saulin pojan Iisbosetin ja vei hänet Mahanaimiin'),
(1676975,58,10,2,9,'ja asetti hänet Gileadin, Asurin, Jisreelin, Efraimin, Benjaminin ja koko Israelin kuninkaaksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1676976,58,10,2,10,'Saulin poika Iisboset oli neljänkymmenen vuoden vanha tullessaan Israelin kuninkaaksi ja hallitsi kaksi vuotta. Ainoastaan Juudan heimo seurasi Daavidia.'),
(1676977,58,10,2,11,'Ja aika, minkä Daavid oli Juudan heimon kuninkaana Hebronissa, oli seitsemän vuotta ja kuusi kuukautta.'),
(1676978,58,10,2,12,'Abner, Neerin poika, ja Saulin pojan Iisbosetin palvelijat lähtivät Mahanaimista Gibeoniin.'),
(1676979,58,10,2,13,'Ja Jooab, Serujan poika, ja Daavidin palvelijat lähtivät hekin liikkeelle, ja he kohtasivat toisensa Gibeonin lammikolla; he asettuivat toiset tälle, toiset tuolle puolelle lammikon.'),
(1676980,58,10,2,14,'Ja Abner sanoi Jooabille: "Nouskoon nuoria miehiä pitämään taistelukisaa meidän edessämme". Jooab sanoi: "Nouskoon vain".'),
(1676981,58,10,2,15,'Niin heitä nousi ja astui esiin sama määrä: kaksitoista Benjaminin ja Saulin pojan Iisbosetin puolelta sekä kaksitoista Daavidin palvelijaa.'),
(1676982,58,10,2,16,'Ja he tarttuivat kukin vastustajaansa päähän ja pistivät miekkansa toinen toisensa kylkeen ja kaatuivat yhdessä. Niin sen paikan nimeksi tuli Helkat-Suurim, ja se on Gibeonin luona.'),
(1676983,58,10,2,17,'Ja sinä päivänä syntyi hyvin kova taistelu; mutta Daavidin palvelijat voittivat Abnerin ja Israelin miehet.'),
(1676984,58,10,2,18,'Ja siellä oli kolme Serujan poikaa: Jooab, Abisai ja Asael. Ja Asael oli nopeajalkainen kuin gaselli kedolla.'),
(1676985,58,10,2,19,'Ja Asael ajoi takaa Abneria eikä poikennut oikealle eikä vasemmalle Abnerin jäljestä.'),
(1676986,58,10,2,20,'Niin Abner käännähti taaksensa ja sanoi: "Sinäkö se olet, Asael?" Hän vastasi: "Minä".'),
(1676987,58,10,2,21,'Ja Abner sanoi hänelle: "Käänny oikealle tai vasemmalle ja ota joku noista nuorista miehistä kiinni ja riistä siltä sota-asu". Mutta Asael ei tahtonut luopua hänestä.'),
(1676988,58,10,2,22,'Niin Abner vielä kerran sanoi Asaelille: "Luovu minusta, muutoin lyön sinut maahan. Mutta kuinka minä sitten voisin katsoa sinun veljeäsi Jooabia silmiin?"'),
(1676989,58,10,2,23,'Mutta kun hän ei tahtonut luopua hänestä, pisti Abner häntä keihään varsipuolella vatsaan, niin että keihäs tuli takaapäin ulos; ja hän kaatui ja kuoli siihen paikkaan. Ja jokainen, joka tuli siihen paikkaan, mihin Asael oli kaatunut ja kuollut, pysähtyi siihen.'),
(1676990,58,10,2,24,'Mutta Jooab ja Abisai ajoivat Abneria takaa ja tulivat, kun aurinko oli laskenut, Amman kukkulalle, joka on vastapäätä Giiahia, Gibeonin erämaahan päin.'),
(1676991,58,10,2,25,'Silloin benjaminilaiset kokoontuivat Abnerin taakse yhteen joukkoon ja asettuivat kukkulan laelle.'),
(1676992,58,10,2,26,'Ja Abner huusi Jooabille ja sanoi: "Pitääkö miekan syödä ainiaan? Etkö sinä ymmärrä, että siitä tulee vain katkeruutta jäljestäpäin? Etkö jo käske väen lakata ajamasta takaa veljiänsä?"'),
(1676993,58,10,2,27,'Jooab vastasi: "Niin totta kuin Jumala elää: jos sinä et olisi puhunut, niin varmasti väki vasta huomenaamuna olisi lähtenyt pois ajamasta takaa veljiänsä".'),
(1676994,58,10,2,28,'Ja Jooab puhalsi pasunaan; niin kaikki väki pysähtyi eikä enää ajanut takaa Israelia. Ja he eivät enää taistelleet.'),
(1676995,58,10,2,29,'Mutta Abner ja hänen miehensä kulkivat koko sen yön Aromaata ja menivät Jordanin yli, kulkivat koko Bitronin läpi ja tulivat Mahanaimiin.'),
(1676996,58,10,2,30,'Ja Jooab kokosi kaiken kansan, palattuaan ajamasta takaa Abneria. Ja Daavidin palvelijoista puuttui yhdeksäntoista miestä ja Asael.'),
(1676997,58,10,2,31,'Mutta Daavidin palvelijat olivat lyöneet benjaminilaisia ja Abnerin miehiä kuoliaaksi kolmesataa kuusikymmentä miestä.'),
(1676998,58,10,2,32,'Ja he ottivat Asaelin ja hautasivat hänet hänen isänsä hautaan Beetlehemiin. Ja Jooab ja hänen miehensä kulkivat koko sen yön ja tulivat päivän valjetessa Hebroniin.'),
(1676999,58,10,3,1,'Sota Saulin suvun ja Daavidin suvun välillä tuli pitkälliseksi. Mutta Daavid vahvistui vahvistumistaan, Saulin suku heikontui heikontumistaan.'),
(1677000,58,10,3,2,'Ja Daavidille syntyi poikia Hebronissa. Hänen esikoisensa oli Amnon, jonka äiti oli jisreeliläinen Ahinoam.'),
(1677001,58,10,3,3,'Hänen toinen poikansa oli Kilab, jonka äiti oli Abigail, karmelilaisen Naabalin vaimo; kolmas oli Absalom, Gesurin kuninkaan Talmain tyttären, Maakan, poika.'),
(1677002,58,10,3,4,'Neljäs oli Adonia, Haggitin poika, ja viides Sefatja, Abitalin poika.'),
(1677003,58,10,3,5,'Kuudes oli Jitream, Daavidin vaimon Eglan poika. Nämä syntyivät Daavidille Hebronissa.'),
(1677004,58,10,3,6,'Niin kauan kuin oli sota Saulin suvun ja Daavidin suvun välillä, piti Abner voimakkaasti Saulin suvun puolta.'),
(1677005,58,10,3,7,'Saulilla oli ollut sivuvaimo, nimeltä Rispa, Aijan tytär. Ja Iisboset sanoi Abnerille: "Miksi olet mennyt minun isäni sivuvaimon tykö?"'),
(1677006,58,10,3,8,'Abner vihastui kovin Iisbosetin sanoista ja sanoi: "Olenko minä koiranpää, Juudasta kotoisin? Kun minä nytkin osoitan laupeutta isäsi Saulin suvulle, hänen veljilleen ja ystävilleen enkä ole antanut sinun joutua Daavidin käsiin, niin sinä kuitenkin nyt syytät minua rikoksen teosta naiselle.'),
(1677007,58,10,3,9,'Jumala rangaiskoon Abneria nyt ja vasta, jos minä en tee Daavidille, niinkuin Herra on hänelle vannonut:'),
(1677008,58,10,3,10,'minä otan pois kuninkuuden Saulin suvulta ja pystytän Daavidille valtaistuimen Israeliin ja Juudaan, Daanista aina Beersebaan asti."'),
(1677009,58,10,3,11,'Eikä hän enää voinut vastata Abnerille sanaakaan, sillä hän pelkäsi häntä.'),
(1677010,58,10,3,12,'Mutta Abner lähetti paikalla sanansaattajat Daavidin luo sanomaan: "Kenenkä on maa?" ja vielä näin: "Tee liitto minun kanssani; ja katso, minun käteni on oleva sinun kanssasi ja on kääntävä koko Israelin sinun puolellesi".'),
(1677011,58,10,3,13,'Hän vastasi: "Hyvä, minä teen liiton sinun kanssasi. Yhtä minä kuitenkin vaadin sinulta: älä astu minun kasvojeni eteen tuomatta Miikalia, Saulin tytärtä, kun tulet astuaksesi minun kasvojeni eteen."'),
(1677012,58,10,3,14,'Sitten Daavid lähetti sanansaattajat Iisbosetin, Saulin pojan, luo sanomaan: "Anna minulle vaimoni Miikal, jonka minä olen kihlannut itselleni sadalla filistealaisten esinahalla".'),
(1677013,58,10,3,15,'Iisboset lähetti ottamaan hänet hänen mieheltään Paltielilta, Laiksen pojalta.'),
(1677014,58,10,3,16,'Ja hänen miehensä lähti hänen mukanaan ja seurasi häntä aina Bahurimiin asti, itkien lakkaamatta. Niin Abner sanoi hänelle: "Mene tiehesi, palaja takaisin". Ja hän palasi takaisin.'),
(1677015,58,10,3,17,'Abner oli neuvotellut Israelin vanhinten kanssa sanoen: "Jo kauan olette halunneet saada Daavidin kuninkaaksenne.'),
(1677016,58,10,3,18,'Niin pankaa se nyt toimeen, sillä Herra on sanonut Daavidille näin: ''Palvelijani Daavidin kädellä minä vapautan kansani Israelin filistealaisten käsistä ja kaikkien heidän vihollistensa käsistä''."'),
(1677017,58,10,3,19,'Abner puhui tämän myös benjaminilaisille, ja Abner meni ja puhui Daavidillekin Hebronissa, mitä mieltä Israel ja koko Benjaminin heimo olivat.'),
(1677018,58,10,3,20,'Kun Abner tuli Daavidin luo Hebroniin, mukanaan kaksikymmentä miestä, laittoi Daavid pidot Abnerille ja miehille, jotka olivat hänen kanssaan.'),
(1677019,58,10,3,21,'Ja Abner sanoi Daavidille: "Minä nousen ja menen kokoamaan kaiken Israelin herrani, kuninkaan, luo, että he tekisivät liiton sinun kanssasi ja sinä saisit hallittaviksesi kaikki, joita haluat". Niin Daavid päästi Abnerin menemään, ja hän lähti rauhassa.'),
(1677020,58,10,3,22,'Katso, silloin Daavidin palvelijat ja Jooab tulivat ryöstöretkeltä ja toivat mukanaan paljon saalista; mutta Abner ei ollut enää Daavidin luona Hebronissa, sillä tämä oli päästänyt hänet menemään, ja hän oli lähtenyt rauhassa.'),
(1677021,58,10,3,23,'Kun Jooab ja kaikki sotaväki, joka oli hänen kanssaan, tulivat, kerrottiin Jooabille: "Abner, Neerin poika, tuli kuninkaan luo, ja hän päästi hänet menemään, ja hän lähti rauhassa".'),
(1677022,58,10,3,24,'Silloin Jooab meni kuninkaan luo ja sanoi: "Mitä olet tehnyt? Katso, Abner tuli sinun luoksesi; miksi päästit hänet menemään menojansa?'),
(1677023,58,10,3,25,'Etkö ymmärrä, että Abner, Neerin poika, tuli pettämään sinua ja urkkimaan lähtöäsi ja tuloasi ja kaikkea, mitä teet?"'),
(1677024,58,10,3,26,'Sitten Jooab lähti Daavidin luota ja lähetti sanansaattajat Abnerin jälkeen, ja he palauttivat hänet takaisin Boor-Siirasta; eikä Daavid tiennyt siitä mitään.'),
(1677025,58,10,3,27,'Kun Abner tuli takaisin Hebroniin, vei Jooab hänet syrjään porttiholvin keskelle, muka puhutellakseen häntä kahden kesken, ja pisti häntä siellä vatsaan, niin että hän kuoli - hänen veljensä Asaelin veren kostoksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677026,58,10,3,28,'Kun Daavid sitten sai sen kuulla, sanoi hän: "Abnerin, Neerin pojan, vereen olen viaton minä ja minun kuninkuuteni Herran edessä iankaikkisesti.'),
(1677027,58,10,3,29,'Tulkoon se Jooabin pään päälle ja kaiken hänen isänsä perheen päälle, älköötkä Jooabin suvusta loppuko vuotoa tai pitalia sairastavat, kainalosauvoilla kulkijat, miekkaan kaatuvat ja leivän puutteessa olijat."'),
(1677028,58,10,3,30,'Näin Jooab ja hänen veljensä Abisai tappoivat Abnerin, sentähden että tämä oli surmannut heidän veljensä Asaelin taistelussa Gibeonin luona.'),
(1677029,58,10,3,31,'Mutta Daavid sanoi Jooabille ja kaikelle väelle, joka oli hänen kanssaan: "Reväiskää vaatteenne ja kääriytykää säkkeihin ja pitäkää valittajaiset Abnerille". Ja kuningas Daavid kulki paarien perässä.'),
(1677030,58,10,3,32,'Ja he hautasivat Abnerin Hebroniin; ja kuningas korotti äänensä ja itki Abnerin haudalla, ja kaikki kansa itki.'),
(1677031,58,10,3,33,'Ja kuningas viritti itkuvirren Abnerista ja sanoi: "Pitikö Abnerin kuolla, niinkuin kuolee houkka?'),
(1677032,58,10,3,34,'Eivät olleet sinun kätesi sidotut eivätkä jalkasi vaskikahleisiin pannut. Sinä kaaduit, niinkuin kaadutaan vilpillisten käden kautta." Niin kaikki kansa itki häntä vielä enemmän.'),
(1677033,58,10,3,35,'Ja kaikki kansa tuli, kun vielä oli päivä, vaatimaan, että Daavid söisi jotakin; mutta Daavid vannoi ja sanoi: "Jumala rangaiskoon minua nyt ja vasta, jos minä maistan leipää tai muuta, ennenkuin aurinko laskee".'),
(1677034,58,10,3,36,'Kun kaikki kansa sai kuulla sen, miellytti se heitä, samoinkuin kaikki muu, mitä kuningas teki, oli kaikelle kansalle mieleen.'),
(1677035,58,10,3,37,'Ja kaikki kansa ja koko Israel ymmärsivät sinä päivänä, että Abnerin, Neerin pojan, surma ei ollut lähtenyt kuninkaasta.'),
(1677036,58,10,3,38,'Ja kuningas sanoi palvelijoilleen: "Ettekö tiedä, että ruhtinas ja suuri mies on tänä päivänä kaatunut Israelissa?'),
(1677037,58,10,3,39,'Mutta minä olen vielä heikko, vaikka olen voideltu kuninkaaksi, ja nuo miehet, Serujan pojat, ovat liian väkivaltaiset minun hillitä. Herra maksakoon sille, joka tekee pahaa, hänen pahuutensa mukaan."'),
(1677038,58,10,4,1,'Kun Saulin poika kuuli Abnerin kuolleen Hebronissa, herposivat hänen kätensä, ja koko Israel peljästyi.'),
(1677039,58,10,4,2,'Ja Saulin pojalla oli partiojoukkojen päämiehinä kaksi miestä, toisen nimi oli Baana ja toisen Reekab, beerotilaisen Rimmonin poikia, benjaminilaisia; sillä Beerotkin luetaan kuuluvaksi Benjaminiin.'),
(1677040,58,10,4,3,'Mutta beerotilaiset olivat paenneet Gittaimiin ja asuivat siellä muukalaisina, niinkuin asuvat vielä tänäkin päivänä.'),
(1677041,58,10,4,4,'Joonatanilla, Saulin pojalla, oli poika, joka oli rampa jaloistaan. Hän oli viiden vuoden vanha, kun sanoma Saulista ja Joonatanista tuli Jisreelistä; ja hänen hoitajansa otti hänet ja pakeni. Mutta kun tämä hätääntyneenä pakeni, putosi poika ja tuli ontuvaksi; ja hänen nimensä oli Mefiboset.'),
(1677042,58,10,4,5,'Beerotilaisen Rimmonin pojat Reekab ja Baana lähtivät matkaan ja tulivat päivän ollessa palavimmillaan Iisbosetin taloon, kun hän oli puolipäivälevollansa.'),
(1677043,58,10,4,6,'Ja katso, he tulivat sisälle taloon muka ottamaan nisuja, mutta pistivät häntä vatsaan. Ja Reekab ja hänen veljensä Baana pääsivät pakoon.'),
(1677044,58,10,4,7,'He tulivat niinmuodoin taloon, kun hän lepäsi vuoteellansa makuuhuoneessaan, pistivät hänet kuoliaaksi, löivät häneltä pään poikki ja ottivat sen mukaansa. He kulkivat sitten Aromaan tietä koko yön,'),
(1677045,58,10,4,8,'toivat Iisbosetin pään Daavidille Hebroniin ja sanoivat kuninkaalle: "Katso, tässä on Iisbosetin, Saulin pojan, sinun vihamiehesi, pää, hänen, joka väijyi sinun henkeäsi. Herra on tänä päivänä kostanut Saulille ja hänen jälkeläisillensä herrani, kuninkaan, puolesta."'),
(1677046,58,10,4,9,'Niin Daavid vastasi Reekabille ja hänen veljellensä Baanalle, beerotilaisen Rimmonin pojille, ja sanoi heille: "Niin totta kuin Herra elää, joka on vapahtanut minut kaikesta hädästä:'),
(1677047,58,10,4,10,'sen, joka ilmoitti minulle ja sanoi: ''Katso, Saul on kuollut'', luullen tuovansa ilosanoman, minä otatin kiinni ja surmautin Siklagissa antaakseni hänelle sanansaattajan palkan;'),
(1677048,58,10,4,11,'eikö minun paljoa enemmän nyt, kun jumalattomat miehet ovat murhanneet syyttömän miehen hänen omassa kodissaan, hänen vuoteeseensa, ole vaadittava hänen verensä teidän kädestänne ja hävitettävä teidät maan päältä?"'),
(1677049,58,10,4,12,'Ja Daavid käski nuorten miesten surmata heidät. Niin he hakkasivat poikki heidän kätensä ja jalkansa ja hirttivät heidät Hebronin lammikon rannalle. Mutta Iisbosetin pään he ottivat ja hautasivat sen Abnerin hautaan Hebroniin.'),
(1677050,58,10,5,1,'Sitten kaikki Israelin sukukunnat tulivat Daavidin luo Hebroniin ja sanoivat näin: "Katso, me olemme sinun luutasi ja lihaasi.'),
(1677051,58,10,5,2,'Jo kauan sitten, Saulin vielä ollessa kuninkaanamme, sinä saatoit Israelin lähtemään ja tulemaan. Ja sinulle on Herra sanonut: ''Sinä olet kaitseva minun kansaani Israelia, ja sinä olet oleva Israelin ruhtinas''."'),
(1677052,58,10,5,3,'Ja kaikki Israelin vanhimmat tulivat kuninkaan tykö Hebroniin, ja kuningas Daavid teki heidän kanssaan liiton Hebronissa, Herran edessä; ja sitten he voitelivat Daavidin Israelin kuninkaaksi.'),
(1677053,58,10,5,4,'Daavid oli kolmenkymmenen vuoden vanha tullessaan kuninkaaksi ja hallitsi neljäkymmentä vuotta.'),
(1677054,58,10,5,5,'Hebronissa hän hallitsi Juudaa seitsemän vuotta ja kuusi kuukautta, ja Jerusalemissa hän hallitsi koko Israelia ja Juudaa kolmekymmentä kolme vuotta.'),
(1677055,58,10,5,6,'Ja kuningas meni miehinensä Jerusalemiin jebusilaisia vastaan, jotka asuivat siinä maassa. He sanoivat Daavidille näin: "Tänne sinä et tule, vaan sokeat ja ontuvat karkoittavat sinut sanomalla: ''Ei tule Daavid tänne''".'),
(1677056,58,10,5,7,'Mutta Daavid valloitti Siionin vuorilinnan, se on Daavidin kaupungin.'),
(1677057,58,10,5,8,'Ja Daavid sanoi sinä päivänä: "Jokainen, joka surmaa jebusilaisen ja tunkeutuu vesijohdolle asti, hän voittaa ne sokeat ja ontuvat, joita Daavid vihaa". Sentähden on tapana sanoa: "Sokea ja ontuva älköön tulko taloon".'),
(1677058,58,10,5,9,'Sitten Daavid asettui vuorilinnaan ja kutsui sen Daavidin kaupungiksi. Ja Daavid rakenteli sitä yltympäri, Millosta sisälle päin.'),
(1677059,58,10,5,10,'Ja Daavid tuli yhä mahtavammaksi, ja Herra, Jumala Sebaot, oli hänen kanssansa.'),
(1677060,58,10,5,11,'Hiiram, Tyyron kuningas, lähetti sanansaattajat Daavidin luo sekä setripuita, puuseppiä ja kivenhakkaajia; ja nämä rakensivat Daavidille palatsin.'),
(1677061,58,10,5,12,'Ja Daavid ymmärsi, että Herra oli vahvistanut hänet Israelin kuninkaaksi ja korottanut hänen kuninkuutensa kansansa Israelin tähden.'),
(1677062,58,10,5,13,'Ja Hebronista tultuaan Daavid otti Jerusalemista vielä useampia sivuvaimoja ja vaimoja. Ja Daavidille syntyi vielä poikia ja tyttäriä.'),
(1677063,58,10,5,14,'Ja nämä ovat niiden poikien nimet, jotka syntyivät hänelle Jerusalemissa: Sammua, Soobab, Naatan, Salomo,'),
(1677064,58,10,5,15,'Jibhar, Elisua, Nefeg, Jaafia,'),
(1677065,58,10,5,16,'Elisama, Eljada ja Elifelet.'),
(1677066,58,10,5,17,'Mutta kun filistealaiset kuulivat, että Daavid oli voideltu Israelin kuninkaaksi, lähtivät kaikki filistealaiset etsimään Daavidia. Kun Daavid sen kuuli, meni hän alas vuorilinnaan.'),
(1677067,58,10,5,18,'Kun filistealaiset olivat tulleet ja levittäytyneet Refaimin tasangolle,'),
(1677068,58,10,5,19,'kysyi Daavid Herralta: "Menenkö minä filistealaisia vastaan? Annatko sinä heidät minun käsiini?" Ja Herra sanoi Daavidille: "Mene, sillä minä annan filistealaiset sinun käsiisi".'),
(1677069,58,10,5,20,'Niin Daavid tuli Baal-Perasimiin. Ja siellä Daavid voitti heidät ja sanoi: "Herra on murtanut viholliseni minun edessäni, niinkuin vedet murtavat". Siitä sen paikan nimeksi tuli Baal-Perasim.'),
(1677070,58,10,5,21,'He jättivät siihen epäjumalankuvansa, ja Daavid ja hänen miehensä veivät ne pois.'),
(1677071,58,10,5,22,'Mutta filistealaiset tulivat vielä kerran ja levittäytyivät Refaimin tasangolle.'),
(1677072,58,10,5,23,'Niin Daavid kysyi Herralta, ja hän vastasi: "Älä mene heitä vastaan, vaan kierrä heidät takaapäin ja hyökkää heidän kimppuunsa balsamipuiden puolelta.'),
(1677073,58,10,5,24,'Ja kun kuulet astunnan kahinan balsamipuiden latvoista, niin ryntää nopeasti, sillä silloin Herra on käynyt sinun edelläsi tuhotakseen filistealaisten leirin." Daavid teki, niinkuin Herra oli häntä käskenyt; ja hän voitti filistealaiset ja ajoi heitä takaa Gebasta aina Geseriin saakka.'),
(1677074,58,10,6,1,'Daavid kokosi jälleen kaikki valiomiehet Israelista, kolmekymmentä tuhatta miestä.'),
(1677075,58,10,6,2,'Ja Daavid ja kaikki väki, joka oli hänen kanssaan, nousi ja lähti Juudan Baalasta, tuomaan sieltä Jumalan arkkia, jonka Herra Sebaot oli ottanut nimiinsä, hän, jonka istuinta kerubit kannattavat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677076,58,10,6,3,'Ja he panivat Jumalan arkin uusiin vaunuihin ja veivät sen pois Abinadabin talosta, joka oli mäellä; ja Ussa ja Ahjo, Abinadabin pojat, ohjasivat niitä uusia vaunuja.'),
(1677077,58,10,6,4,'Niin he veivät Jumalan arkin pois Abinadabin talosta, joka oli mäellä, kulkien Jumalan arkin mukana, ja Ahjo kulki arkin edellä.'),
(1677078,58,10,6,5,'Ja Daavid ynnä koko Israelin heimo karkeloi kaikin voimin Herran edessä soittaen kaikenkaltaisilla kypressipuisilla soittimilla, kanteleilla, harpuilla, vaskirummuilla, helistimillä ja kymbaaleilla.'),
(1677079,58,10,6,6,'Mutta kun he tulivat Naakonin puimatantereen luo, ojensi Ussa kätensä Jumalan arkkiin ja tarttui siihen, sillä härät kompastuivat.'),
(1677080,58,10,6,7,'Silloin Herran viha syttyi Ussaa kohtaan, ja Jumala löi hänet siinä hänen hairahduksensa tähden, niin että hän kuoli siihen, Jumalan arkin ääreen.'),
(1677081,58,10,6,8,'Mutta Daavid pahastui siitä, että Herra niin oli murtanut Ussan. Siitä se paikka sai nimekseen Peres-Ussa, aina tähän päivään saakka.'),
(1677082,58,10,6,9,'Ja Daavid pelkäsi sinä päivänä Herraa, niin että hän sanoi: "Kuinka Herran arkki voi tulla minun tyköni?"'),
(1677083,58,10,6,10,'Eikä Daavid tahtonut siirtää Herran arkkia tykönsä Daavidin kaupunkiin, vaan Daavid toimitti sen syrjään, gatilaisen Oobed-Edomin taloon.'),
(1677084,58,10,6,11,'Ja Herran arkki jäi kolmeksi kuukaudeksi gatilaisen Oobed-Edomin taloon. Ja Herra siunasi Oobed-Edomia ja koko hänen taloansa.'),
(1677085,58,10,6,12,'Kun kuningas Daavidille kerrottiin, että Herra oli Jumalan arkin tähden siunannut Oobed-Edomin taloa ja kaikkea, mitä hänellä oli, niin Daavid meni ja toi riemuiten Jumalan arkin Oobed-Edomin talosta Daavidin kaupunkiin.'),
(1677086,58,10,6,13,'Kun Herran arkin kantajat olivat astuneet kuusi askelta, uhrasi hän härän ja juottovasikan.'),
(1677087,58,10,6,14,'Ja Daavid hyppi kaikin voimin Herran edessä, ja Daavid oli puettu pellavakasukkaan.'),
(1677088,58,10,6,15,'Niin Daavid ja koko Israelin heimo toivat Herran arkin riemun raikuessa ja pasunain pauhatessa.'),
(1677089,58,10,6,16,'Kun Herran arkki tuli Daavidin kaupunkiin, katseli Miikal, Saulin tytär, ikkunasta; ja nähdessään kuningas Daavidin karkeloivan ja hyppivän Herran edessä halveksi hän häntä sydämessänsä.'),
(1677090,58,10,6,17,'Ja kun he olivat tuoneet Herran arkin ja asettaneet sen paikalleen majaan, jonka Daavid oli sille pystyttänyt, uhrasi Daavid polttouhreja ja yhteysuhreja Herran edessä.'),
(1677091,58,10,6,18,'Ja kun Daavid oli uhrannut polttouhrin ja yhteysuhrit, siunasi hän kansan Herran Sebaotin nimeen.'),
(1677092,58,10,6,19,'Ja hän jakoi koko kansalle, kaikelle Israelin joukolle, sekä miehille että naisille, kullekin kakun, kappaleen lihaa ja rypälekakun. Sitten kaikki kansa lähti, kukin kotiinsa.'),
(1677093,58,10,6,20,'Mutta kun Daavid palasi takaisin tervehtimään perhettänsä, meni Miikal, Saulin tytär, ulos Daavidia vastaan ja sanoi: "Kuinka arvokkaana onkaan Israelin kuningas nyt esiintynyt, kun on tänä päivänä paljastanut itsensä palvelijainsa palvelijattarien silmien edessä, niinkuin kevytmielinen ihminen paljastautuu!"'),
(1677094,58,10,6,21,'Niin Daavid sanoi Miikalille: "Herran edessä, joka on valinnut minut, sivu sinun isäsi ja koko hänen sukunsa, ja asettanut minut Herran kansan, Israelin, ruhtinaaksi - Herran edessä minä karkeloin;'),
(1677095,58,10,6,22,'ja tähänkin minä pidän itseni liian vähäisenä ja olen omissa silmissäni halpa; mutta ne palvelijattaret, joista sinä puhuit, tulevat minua kunnioittamaan".'),
(1677096,58,10,6,23,'Ja Miikal, Saulin tytär, ei saanut lasta kuolinpäiväänsä asti.'),
(1677097,58,10,7,1,'Kerran, kun kuningas istui linnassaan, sittenkuin Herra oli suonut hänen päästä rauhaan kaikilta hänen ympärillään olevilta vihollisilta,'),
(1677098,58,10,7,2,'sanoi kuningas profeetta Naatanille: "Katso, minä asun setripuisessa linnassa, mutta Jumalan arkki asuu telttakankaan suojassa".'),
(1677099,58,10,7,3,'Naatan sanoi kuninkaalle: "Tee vain kaikki, mitä mielessäsi on, sillä Herra on sinun kanssasi".'),
(1677100,58,10,7,4,'Mutta sinä yönä tapahtui, että Naatanille tuli tämä Herran sana:'),
(1677101,58,10,7,5,'"Mene ja sano minun palvelijalleni Daavidille: Näin sanoo Herra: Sinäkö rakentaisit minulle huoneen asuakseni?'),
(1677102,58,10,7,6,'Enhän minä ole asunut huoneessa siitä päivästä asti, jona johdatin israelilaiset Egyptistä, tähän päivään saakka, vaan minä olen vaeltanut asuen teltta-asumuksessa.'),
(1677103,58,10,7,7,'Olenko minä koskaan, missä olenkin vaeltanut kaikkien israelilaisten keskuudessa, millekään Israelin sukukunnalle, jonka olen asettanut kaitsemaan kansaani Israelia, sanonut näin: Miksi te ette ole rakentaneet minulle setripuista huonetta?'),
(1677104,58,10,7,8,'Sano siis minun palvelijalleni Daavidille: Näin sanoo Herra Sebaot: Minä olen ottanut sinut laitumelta, lammasten jäljestä, kansani Israelin ruhtinaaksi.'),
(1677105,58,10,7,9,'Ja minä olen ollut sinun kanssasi kaikkialla, missä sinä vaelsit, ja olen hävittänyt kaikki vihollisesi sinun tieltäsi. Ja minä teen sinulle suuren nimen, suurimpien nimien vertaisen maan päällä.'),
(1677106,58,10,7,10,'Ja minä valmistan sijan kansalleni Israelille ja istutan sen niin, että se asuu paikallansa eikä enää ole levoton, eivätkä vääryyden tekijät sitä enää sorra niinkuin ennen,'),
(1677107,58,10,7,11,'siitä ajasta saakka, jolloin minä asetin tuomareita kansalleni Israelille; minä annan sinun päästä rauhaan kaikista vihollisistasi. Ja Herra ilmoittaa sinulle, että Herra on tekevä sinulle huoneen.'),
(1677108,58,10,7,12,'Kun sinun päiväsi ovat päättyneet ja sinä lepäät isiesi tykönä, korotan minä sinun seuraajaksesi jälkeläisesi, joka lähtee sinun ruumiistasi; ja minä vahvistan hänen kuninkuutensa.'),
(1677109,58,10,7,13,'Hän on rakentava huoneen minun nimelleni, ja minä vahvistan hänen valtaistuimensa ikuisiksi ajoiksi.'),
(1677110,58,10,7,14,'Minä olen oleva hänen isänsä ja hän minun poikani, niin että, jos hän tekee väärin, minä rankaisen häntä ihmisvitsalla ja niinkuin ihmislapsia lyödään;'),
(1677111,58,10,7,15,'mutta minun armoni ei poistu hänestä, niinkuin minä poistin sen Saulista, jonka minä poistin sinun tieltäsi.'),
(1677112,58,10,7,16,'Ja sinun sukusi ja kuninkuutesi pysyvät sinun edessäsi iäti, ja sinun valtaistuimesi on oleva iäti vahva."'),
(1677113,58,10,7,17,'Aivan näillä sanoilla ja tämän näyn mukaan Naatan puhui Daavidille.'),
(1677114,58,10,7,18,'Niin kuningas Daavid meni ja asettui Herran eteen ja sanoi: "Mikä olen minä, Herra, Herra, ja mikä on minun sukuni, että olet saattanut minut tähän asti?'),
(1677115,58,10,7,19,'Mutta tämäkin on ollut vähän sinun silmissäsi, Herra, Herra, ja niin olet sinä puhunut palvelijasi suvulle myöskin kaukaisista asioista, näin opettaen ihmisten tavalla, Herra, Herra.'),
(1677116,58,10,7,20,'Mitä Daavid enää sinulle puhuisi? Sinähän tunnet palvelijasi, Herra, Herra.'),
(1677117,58,10,7,21,'Oman sanasi tähden ja mielesi mukaan sinä olet tehnyt sen, että ilmoitit palvelijallesi kaikki nämä suuret asiat.'),
(1677118,58,10,7,22,'Sentähden olet sinä, Herra Jumala, suuri; sillä kaiken sen mukaan, mitä me olemme korvillamme kuulleet, ei ole sinun vertaistasi, eikä muuta jumalaa ole kuin sinä.'),
(1677119,58,10,7,23,'Ja missä on maan päällä toista kansaa sinun kansasi Israelin vertaista, jota Jumala itse on käynyt lunastamaan kansaksensa, tehdäkseen sen nimen kuuluisaksi ja tehdäkseen teille, sinun maallesi, suuria ja peljättäviä tekoja kansasi edessä, jonka sinä lunastit itsellesi Egyptistä, pakanain ja heidän jumaliensa vallasta?'),
(1677120,58,10,7,24,'Ja sinä olet valmistanut itsellesi kansasi Israelin, omaksi kansaksesi ikuisiksi ajoiksi; ja sinä, Herra, olet tullut heidän Jumalaksensa.'),
(1677121,58,10,7,25,'Niin täytä nyt, Herra Jumala, ikuisiksi ajoiksi se, mitä olet puhunut palvelijastasi ja hänen suvustansa; tee, niinkuin olet puhunut.'),
(1677122,58,10,7,26,'Niin sinun nimesi tulee suureksi iankaikkisesti, ja se on oleva: Herra Sebaot, Israelin Jumala. Ja palvelijasi Daavidin suku on pysyvä sinun edessäsi.'),
(1677123,58,10,7,27,'Sillä sinä, Herra Sebaot, Israelin Jumala, olet ilmoittanut palvelijallesi ja sanonut: ''Minä rakennan sinulle huoneen''. Siitä sinun palvelijasi on saanut rohkeuden rukoilla tämän rukouksen sinun kuullaksesi.'),
(1677124,58,10,7,28,'Ja nyt, Herra, Herra, sinä olet Jumala, ja sinun sanasi ovat todet; ja kun olet luvannut palvelijallesi tämän hyvän,'),
(1677125,58,10,7,29,'niin suvaitse nyt siunata palvelijasi sukua, että se pysyisi iäti sinun edessäsi. Sillä sinä, Herra, Herra, olet sen luvannut, ja sinun palvelijasi suku on oleva siunattu sinun siunauksellasi iankaikkisesti."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677126,58,10,8,1,'Sen jälkeen Daavid voitti filistealaiset ja nöyryytti heidät; ja Daavid otti vallan ohjat filistealaisten käsistä.'),
(1677127,58,10,8,2,'Hän voitti myös mooabilaiset ja mittasi heitä nuoralla, pantuaan heidät makaamaan maahan: aina kaksi nuoranpituutta hän mittasi surmattavaksi ja yhden nuoranpituuden henkiin jätettäväksi. Niin tulivat mooabilaiset Daavidin veronalaisiksi palvelijoiksi.'),
(1677128,58,10,8,3,'Samoin Daavid voitti Hadadeserin, Rehobin pojan, Sooban kuninkaan, kun tämä oli menossa ulottamaan valtaansa Eufrat-virtaan.'),
(1677129,58,10,8,4,'Ja Daavid otti häneltä vangiksi tuhat seitsemänsataa ratsumiestä ja kaksikymmentä tuhatta jalkamiestä ja katkoi kaikilta vaunuhevosilta vuohisjänteet; ainoastaan sata vaunuhevosta hän niistä säästi.'),
(1677130,58,10,8,5,'Ja kun Damaskon aramilaiset tulivat auttamaan Hadadeseria, Sooban kuningasta, voitti Daavid kaksikymmentä kaksi tuhatta aramilaista.'),
(1677131,58,10,8,6,'Ja Daavid asetti maaherroja Damaskon Aramiin; ja aramilaiset tulivat Daavidin veronalaisiksi palvelijoiksi. Näin Herra antoi Daavidille voiton, mihin tahansa hän meni.'),
(1677132,58,10,8,7,'Ja Daavid otti ne kultavarustukset, jotka Hadadeserin palvelijoilla oli, ja vei ne Jerusalemiin.'),
(1677133,58,10,8,8,'Mutta Hadadeserin kaupungeista, Betahista ja Beerotaista, kuningas Daavid otti sangen paljon vaskea.'),
(1677134,58,10,8,9,'Kun Tooi, Hamatin kuningas, kuuli, että Daavid oli voittanut Hadadeserin koko sotajoukon,'),
(1677135,58,10,8,10,'lähetti Tooi poikansa Jooramin kuningas Daavidin luo tervehtimään häntä ja onnittelemaan häntä siitä, että hän oli taistellut Hadadeserin kanssa ja voittanut hänet; sillä Hadadeser oli ollut Tooin vastustaja. Ja hänellä oli mukanaan hopea-, kulta- ja vaskikaluja.'),
(1677136,58,10,8,11,'Nekin kuningas Daavid pyhitti Herralle, samoin kuin oli pyhittänyt sen hopean ja kullan, minkä oli ottanut kaikilta kukistamiltaan kansoilta:'),
(1677137,58,10,8,12,'Aramilta, Mooabilta, ammonilaisilta, filistealaisilta ja Amalekilta, sekä sen saaliin, minkä hän oli ottanut Hadadeserilta, Rehobin pojalta, Sooban kuninkaalta.'),
(1677138,58,10,8,13,'Ja Daavid teki nimensä kuuluisaksi, kun hän palasi takaisin, voitettuaan Suolalaaksossa edomilaiset, kahdeksantoista tuhatta miestä.'),
(1677139,58,10,8,14,'Sen jälkeen hän asetti maaherroja Edomiin, koko Edomiin hän asetti maaherrat, ja kaikki edomilaiset tulivat Daavidin palvelijoiksi. Näin Herra antoi Daavidille voiton, mihin tahansa tämä meni.'),
(1677140,58,10,8,15,'Ja Daavid hallitsi koko Israelia, ja Daavid teki kaikelle kansallensa sitä, mikä oikeus ja vanhurskaus on.'),
(1677141,58,10,8,16,'Jooab, Serujan poika, oli sotajoukon ylipäällikkönä, ja Joosafat, Ahiludin poika, oli kanslerina.'),
(1677142,58,10,8,17,'Saadok, Ahitubin poika, ja Ahimelek, Ebjatarin poika, olivat pappeina, ja Seraja oli kirjurina.'),
(1677143,58,10,8,18,'Benaja, Joojadan poika, oli kreettien ja pleettien päällikkönä; Daavidin pojat olivat myös pappeina.'),
(1677144,58,10,9,1,'Daavid kysyi: "Onko Saulin suvusta enää jäljellä ketään, jolle minä voisin tehdä laupeuden Joonatanin tähden?"'),
(1677145,58,10,9,2,'Saulin perheessä oli ollut palvelija nimeltä Siiba, ja hänet he kutsuivat Daavidin eteen. Ja kuningas sanoi hänelle: "Oletko sinä Siiba?" Hän vastasi: "Palvelijasi on".'),
(1677146,58,10,9,3,'Kuningas kysyi: "Eikö Saulin suvusta ole enää jäljellä ketään, jolle minä voisin tehdä Jumalan laupeuden?" Siiba vastasi kuninkaalle: "Vielä on Joonatanin poika, joka on rampa jaloistaan".'),
(1677147,58,10,9,4,'Kuningas kysyi häneltä: "Missä hän on?" Siiba vastasi kuninkaalle: "Hän on Maakirin, Ammielin pojan, talossa Loodebarissa".'),
(1677148,58,10,9,5,'Niin kuningas Daavid lähetti noutamaan hänet Maakirin, Ammielin pojan, talosta Loodebarista.'),
(1677149,58,10,9,6,'Kun Mefiboset, Saulin pojan Joonatanin poika, tuli Daavidin tykö, lankesi hän kasvoillensa ja osoitti kunnioitusta. Niin Daavid sanoi: "Mefiboset!" Hän vastasi: "Tässä on palvelijasi".'),
(1677150,58,10,9,7,'Daavid sanoi hänelle: "Älä pelkää, sillä minä teen sinulle laupeuden isäsi Joonatanin tähden, ja minä palautan sinulle isoisäsi Saulin kaiken maaomaisuuden, ja sinä saat aina aterioida minun pöydässäni".'),
(1677151,58,10,9,8,'Niin tämä kumarsi ja sanoi: "Mikä on palvelijasi, että sinä käännyt minunlaiseni koiranraadon puoleen?"'),
(1677152,58,10,9,9,'Sitten kuningas kutsui Siiban, Saulin palvelijan, ja sanoi hänelle: "Kaiken, mikä on ollut Saulin ja koko hänen sukunsa omaa, minä annan sinun herrasi pojalle.'),
(1677153,58,10,9,10,'Ja sinä poikinesi ja palvelijoinesi viljele hänelle sitä maata ja korjaa sato, että sinun herrasi pojalla olisi leipää syödä; kuitenkin saa Mefiboset, sinun herrasi poika, aina aterioida minun pöydässäni." Ja Siiballa oli viisitoista poikaa ja kaksikymmentä palvelijaa.'),
(1677154,58,10,9,11,'Siiba sanoi kuninkaalle: "Aivan niinkuin herrani, kuningas, käskee palvelijaansa, on palvelijasi tekevä". - "Niin, Mefiboset on syövä minun pöydässäni, niinkuin hän olisi kuninkaan poikia."'),
(1677155,58,10,9,12,'Ja Mefibosetilla oli pieni poika nimeltä Miika. Ja koko Siiban talonväki oli Mefibosetin palvelijoita.'),
(1677156,58,10,9,13,'Ja Mefiboset asui Jerusalemissa, koska hän aina söi kuninkaan pöydässä. Ja hän ontui kumpaakin jalkaansa.'),
(1677157,58,10,10,1,'Senjälkeen ammonilaisten kuningas kuoli, ja hänen poikansa Haanun tuli kuninkaaksi hänen sijaansa.'),
(1677158,58,10,10,2,'Niin Daavid sanoi: "Minä osoitan laupeutta Haanunille, Naahaan pojalle, niinkuin hänen isänsä osoitti laupeutta minulle". Ja Daavid lähetti palvelijoitaan lohduttamaan häntä hänen isänsä kuoleman johdosta. Kun Daavidin palvelijat tulivat ammonilaisten maahan,'),
(1677159,58,10,10,3,'sanoivat ammonilaisten päämiehet herrallensa Haanunille: "Luuletko sinä, että Daavid tahtoo kunnioittaa sinun isääsi, kun hän lähettää lohduttajia sinun luoksesi? Varmasti on Daavid lähettänyt palvelijansa sinun luoksesi tutkimaan kaupunkia ja vakoilemaan ja hävittämään sitä."'),
(1677160,58,10,10,4,'Niin Haanun otatti kiinni Daavidin palvelijat, ajatti toisen puolen heidän partaansa ja leikkautti toisen puolen heidän vaatteistaan, peräpuolia myöten, ja päästi heidät sitten menemään.'),
(1677161,58,10,10,5,'Ja kun se ilmoitettiin Daavidille, lähetti hän sanan heitä vastaan, sillä miehiä oli pahasti häväisty. Ja kuningas käski sanoa: "Jääkää Jerikoon, kunnes partanne on kasvanut, ja tulkaa sitten takaisin".'),
(1677162,58,10,10,6,'Kun ammonilaiset näkivät joutuneensa Daavidin vihoihin, lähettivät ammonilaiset lähettiläitä ja palkkasivat Beet-Rehobin ja Sooban aramilaisia, kaksikymmentä tuhatta jalkamiestä, ja Maakan kuninkaalta tuhat miestä ja Toobin miehiä kaksitoista tuhatta.'),
(1677163,58,10,10,7,'Kun Daavid sen kuuli, lähetti hän Jooabin ja koko sotajoukon, kaikki urhot.'),
(1677164,58,10,10,8,'Niin ammonilaiset lähtivät ja asettuivat sotarintaan portin oven edustalle, mutta Sooban ja Rehobin aramilaiset ja Toobin ja Maakan miehet olivat eri joukkona kedolla.'),
(1677165,58,10,10,9,'Kun Jooab näki, että häntä uhkasi hyökkäys edestä ja takaa, valitsi hän miehiä kaikista Israelin valiomiehistä ja asettui sotarintaan aramilaisia vastaan.'),
(1677166,58,10,10,10,'Mutta muun väen hän antoi veljensä Abisain johtoon, ja tämä asettui sotarintaan ammonilaisia vastaan.'),
(1677167,58,10,10,11,'Ja hän sanoi: "Jos aramilaiset tulevat minulle ylivoimaisiksi, niin tule sinä minun avukseni; jos taas ammonilaiset tulevat sinulle ylivoimaisiksi, niin minä tulen sinua auttamaan.'),
(1677168,58,10,10,12,'Ole luja, ja pysykäämme lujina kansamme puolesta ja meidän Jumalamme kaupunkien puolesta. Tehköön sitten Herra, minkä hyväksi näkee."'),
(1677169,58,10,10,13,'Sitten Jooab ja väki, joka oli hänen kanssaan, ryhtyi taisteluun aramilaisia vastaan, ja nämä pakenivat häntä.'),
(1677170,58,10,10,14,'Ja kun ammonilaiset näkivät aramilaisten pakenevan, pakenivat hekin Abisaita ja menivät kaupunkiin. Sitten Jooab palasi ahdistamasta ammonilaisia ja tuli Jerusalemiin.'),
(1677171,58,10,10,15,'Kun aramilaiset näkivät, että Israel oli voittanut heidät, kokoontuivat he kaikki,'),
(1677172,58,10,10,16,'ja Hadareser lähetti nostattamaan niitä aramilaisia, jotka asuivat tuolla puolella Eufrat-virran; ja he tulivat Heelamiin, ja Soobak, Hadareserin sotapäällikkö, johti heitä.'),
(1677173,58,10,10,17,'Kun se ilmoitettiin Daavidille, kokosi hän kaiken Israelin ja meni Jordanin yli ja tuli Heelamiin; ja aramilaiset asettuivat sotarintaan Daavidia vastaan ja taistelivat hänen kanssaan.'),
(1677174,58,10,10,18,'Mutta aramilaiset pakenivat Israelia, ja Daavid tappoi aramilaisilta seitsemän sataa vaunuhevosta ja neljäkymmentä tuhatta ratsumiestä, ja heidän sotapäällikkönsä Soobakin hän siellä löi kuoliaaksi.'),
(1677175,58,10,10,19,'Kun kaikki Hadareserin alaiset kuninkaat näkivät, että Israel oli voittanut heidät, tekivät he Israelin kanssa rauhan ja palvelivat heitä. Sitten aramilaiset eivät enää uskaltaneet auttaa ammonilaisia.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677176,58,10,11,1,'Vuoden vaihteessa, kuningasten sotaanlähtöaikana, lähetti Daavid Jooabin ja hänen kanssaan palvelijansa ja koko Israelin sotaretkelle; ja he hävittivät ammonilaisten maata ja piirittivät Rabbaa. Mutta Daavid itse jäi Jerusalemiin.'),
(1677177,58,10,11,2,'Niin tapahtui eräänä iltana, kun Daavid oli noussut vuoteeltansa ja käveli kuninkaan linnan katolla, että hän katolta näki naisen peseytymässä; ja nainen oli näöltään hyvin ihana.'),
(1677178,58,10,11,3,'Daavid lähetti hankkimaan tietoja naisesta; ja sanottiin: "Se on Batseba, Eliamin tytär, heettiläisen Uurian vaimo".'),
(1677179,58,10,11,4,'Niin Daavid lähetti sanansaattajat häntä noutamaan, ja hän tuli hänen luoksensa. Ja Daavid makasi naisen kanssa, joka juuri oli puhdistautunut saastaisuudestaan. Sitten tämä palasi kotiinsa.'),
(1677180,58,10,11,5,'Ja vaimo tuli raskaaksi; ja hän lähetti ilmoittamaan Daavidille: "Minä olen raskaana".'),
(1677181,58,10,11,6,'Silloin Daavid lähetti Jooabille sanan: "Lähetä minun luokseni heettiläinen Uuria". Ja Jooab lähetti Uurian Daavidin luo.'),
(1677182,58,10,11,7,'Ja kun Uuria tuli Daavidin luo, kysyi tämä, kuinka Jooab ja väki voivat ja kuinka sota menestyi.'),
(1677183,58,10,11,8,'Ja Daavid sanoi Uurialle: "Mene kotiisi ja pese jalkasi". Uuria lähti kuninkaan linnasta, ja kuninkaan lahja seurasi häntä.'),
(1677184,58,10,11,9,'Mutta Uuria panikin maata kuninkaan linnan oven eteen kaikkien muiden herransa palvelijain joukkoon eikä mennyt kotiinsa.'),
(1677185,58,10,11,10,'Kun Daavidille ilmoitettiin: "Uuria ei ole mennytkään kotiinsa", sanoi Daavid Uurialle: "Tulethan sinä matkalta, mikset mennyt kotiisi?"'),
(1677186,58,10,11,11,'Mutta Uuria sanoi Daavidille: "Arkki ja Israel ja Juuda asuvat lehtimajoissa, minun herrani Jooab ja herrani palvelijat ovat leiriytyneinä kedolla; menisinkö minä kotiin syömään, juomaan ja makaamaan vaimoni kanssa? Niin totta kuin sinä elät ja sinun sielusi elää: sitä minä en tee."'),
(1677187,58,10,11,12,'Niin Daavid sanoi Uurialle: "Jää tänne vielä täksi päiväksi, niin minä huomenna päästän sinut menemään". Niin Uuria jäi Jerusalemiin vielä siksi päiväksi. Seuraavana päivänä'),
(1677188,58,10,11,13,'Daavid kutsui hänet luoksensa syömään ja juomaan ja juotti hänet juovuksiin. Mutta illalla hän meni maata vuoteelleen herransa palvelijain joukkoon eikä mennyt kotiinsa.'),
(1677189,58,10,11,14,'Seuraavana aamuna Daavid kirjoitti kirjeen Jooabille ja lähetti sen Uurian mukana.'),
(1677190,58,10,11,15,'Ja kirjeessä hän kirjoitti näin: "Pankaa Uuria eturintaan, kiivaimpaan taisteluun, ja vetäytykää takaisin hänen luotaan, että hänet lyötäisiin kuoliaaksi".'),
(1677191,58,10,11,16,'Piirittäessään kaupunkia Jooab asetti Uurian siihen paikkaan, missä tiesi urhoollisimpien miesten olevan.'),
(1677192,58,10,11,17,'Kun sitten kaupungin miehet ryntäsivät ulos ja ryhtyivät taisteluun Jooabin kanssa, niin väkeä, Daavidin palvelijoita, kaatui, ja myöskin heettiläinen Uuria kuoli.'),
(1677193,58,10,11,18,'Sitten Jooab lähetti ilmoittamaan Daavidille kaikki, mitä taistelussa oli tapahtunut.'),
(1677194,58,10,11,19,'Ja hän käski sanansaattajaa sanoen: "Kun olet kertonut kuninkaalle kaikki, mitä sodassa on tapahtunut,'),
(1677195,58,10,11,20,'niin kuningas ehkä kiivastuu ja sanoo sinulle: ''Miksi menitte niin lähelle kaupunkia taistelemaan? Ettekö tienneet, että ne ampuvat muurilta?'),
(1677196,58,10,11,21,'Kuka surmasi Abimelekin, Jerubbesetin pojan? Eikö nainen heittänyt muurilta jauhinkiviä hänen päällensä, niin että hän kuoli Teebeksessä? Miksi menitte niin lähelle muuria?'' Sano silloin: ''Myöskin sinun palvelijasi heettiläinen Uuria on kuollut''."'),
(1677197,58,10,11,22,'Sanansaattaja lähti, ja tultuaan hän ilmoitti Daavidille kaiken, mitä Jooab oli lähettänyt hänet ilmoittamaan.'),
(1677198,58,10,11,23,'Ja sanansaattaja sanoi Daavidille: "Ne miehet olivat meille ylivoimaiset ja ryntäsivät meitä vastaan ulos kedolle, mutta me työnsimme heidät takaisin portin ovelle saakka.'),
(1677199,58,10,11,24,'Silloin ampujat ampuivat muurilta sinun palvelijoitasi, ja kuninkaan palvelijoita kuoli; myöskin palvelijasi heettiläinen Uuria kuoli."'),
(1677200,58,10,11,25,'Silloin Daavid sanoi sanansaattajalle: "Sano näin Jooabille: ''Älä pane sitä pahaksesi, sillä miekka syö milloin yhden, milloin toisen; taistele urheasti kaupunkia vastaan ja hävitä se''. Rohkaise häntä näin."'),
(1677201,58,10,11,26,'Kun Uurian vaimo kuuli, että hänen miehensä Uuria oli kuollut, piti hän puolisolleen valittajaiset.'),
(1677202,58,10,11,27,'Mutta kun suruaika oli ohitse, lähetti Daavid ottamaan hänet linnaansa, ja hän tuli hänen vaimoksensa. Sitten hän synnytti hänelle pojan. Mutta se, minkä Daavid oli tehnyt, oli paha Herran silmissä.'),
(1677203,58,10,12,1,'Ja Herra lähetti Naatanin Daavidin tykö. Kun hän tuli hänen tykönsä, sanoi hän hänelle: "Kaksi miestä oli samassa kaupungissa, toinen rikas ja toinen köyhä.'),
(1677204,58,10,12,2,'Rikkaalla oli lampaita ja raavaita hyvin paljon.'),
(1677205,58,10,12,3,'Mutta köyhällä ei ollut muuta kuin yksi ainoa pieni karitsa, jonka hän oli ostanut. Hän elätti sitä, ja se kasvoi hänen luonansa yhdessä hänen lastensa kanssa: se söi hänen leipäpalastansa, joi hänen maljastansa, makasi hänen sylissään ja oli hänelle niinkuin tytär.'),
(1677206,58,10,12,4,'Niin rikkaalle miehelle tuli vieras. Mutta hän ei raskinut ottaa omia lampaitansa eikä raavaitansa valmistaakseen ruokaa matkamiehelle, joka oli tullut hänen luoksensa; vaan hän otti köyhän miehen karitsan ja valmisti sen miehelle, joka oli tullut hänen luoksensa."'),
(1677207,58,10,12,5,'Niin Daavid vihastui kovin siihen mieheen ja sanoi Naatanille: "Niin totta kuin Herra elää: mies, joka tämän on tehnyt, on kuoleman oma.'),
(1677208,58,10,12,6,'Ja karitsa hänen on korvattava nelinkertaisesti, koska hän teki näin ja koska hän ei sääliä tuntenut."'),
(1677209,58,10,12,7,'Mutta Naatan sanoi Daavidille: "Sinä olet se mies. Näin sanoo Herra, Israelin Jumala: ''Minä olen voidellut sinut Israelin kuninkaaksi ja pelastanut sinut Saulin käsistä.'),
(1677210,58,10,12,8,'Minä olen antanut sinulle herrasi linnan ja antanut herrasi vaimot sinun syliisi; ja minä olen antanut sinulle Israelin ja Juudan heimot. Ja jos tämä olisi vähän, niin minä antaisin sinulle vielä sekä sitä että tätä.'),
(1677211,58,10,12,9,'Miksi sinä olet pitänyt halpana Herran sanan ja tehnyt sitä, mikä on pahaa hänen silmissään? Heettiläisen Uurian sinä olet surmannut miekalla, olet tappanut hänet ammonilaisten miekalla, ja hänen vaimonsa sinä olet ottanut vaimoksesi.'),
(1677212,58,10,12,10,'Sentähden ei miekka ole milloinkaan väistyvä sinun suvustasi, koska olet pitänyt halpana minut ja ottanut vaimoksesi heettiläisen Uurian vaimon.'),
(1677213,58,10,12,11,'Näin sanoo Herra: Katso, minä nostatan sinulle onnettomuuden sinun omasta perheestäsi, ja silmiesi edessä minä otan sinun vaimosi ja annan heidät toiselle, ja hän on makaava sinun vaimojesi kanssa tämän auringon nähden.'),
(1677214,58,10,12,12,'Sillä sinä olet tehnyt tekosi salassa, mutta minä teen tämän koko Israelin ja auringon nähden.''"'),
(1677215,58,10,12,13,'Niin Daavid sanoi Naatanille: "Minä olen tehnyt syntiä Herraa vastaan". Naatan sanoi Daavidille: "Niin on myös Herra antanut sinun syntisi anteeksi; sinä et kuole.'),
(1677216,58,10,12,14,'Mutta koska sinä tällä teolla olet saattanut Herran viholliset pilkkaamaan häntä, niin se poika, joka sinulle on syntynyt, on kuoleva."'),
(1677217,58,10,12,15,'Sitten Naatan meni kotiinsa. Ja Herra löi lasta, jonka Uurian vaimo oli Daavidille synnyttänyt, niin että se sairastui vaikeasti.'),
(1677218,58,10,12,16,'Silloin Daavid etsi Jumalaa pojan tähden, ja Daavid paastosi; ja aina kun hän tuli kotiinsa, makasi hän yötä paljaalla maalla.'),
(1677219,58,10,12,17,'Niin hänen hovinsa vanhimmat menivät hänen luokseen saadaksensa hänet nousemaan ylös maasta, mutta hän ei tahtonut; eikä hän syönyt mitään heidän kanssansa.'),
(1677220,58,10,12,18,'Seitsemäntenä päivänä lapsi kuoli. Mutta Daavidin palvelijat eivät uskaltaneet ilmoittaa hänelle, että lapsi oli kuollut, sillä he ajattelivat: "Katso, kun me puhuimme hänelle lapsen vielä eläessä, ei hän kuullut meitä. Kuinka voisimme sitten sanoa hänelle, että lapsi on kuollut? Hän voisi tehdä itselleen pahaa."'),
(1677221,58,10,12,19,'Mutta kun Daavid näki, että hänen palvelijansa kuiskailivat keskenänsä, ymmärsi hän, että lapsi oli kuollut. Ja Daavid kysyi palvelijoiltansa: "Onko lapsi kuollut?" He vastasivat: "On".'),
(1677222,58,10,12,20,'Niin Daavid nousi maasta, peseytyi ja voiteli itsensä, muutti vaatteensa, meni Herran huoneeseen ja rukoili. Ja kun hän tuli kotiinsa, pyysi hän ruokaa; ja he tarjosivat, ja hän söi.'),
(1677223,58,10,12,21,'Mutta hänen palvelijansa sanoivat hänelle: "Miksi teet näin? Lapsen eläessä sinä paastosit ja itkit, mutta lapsen kuoltua sinä nouset ja syöt."'),
(1677224,58,10,12,22,'Hän vastasi: "Kun lapsi vielä eli, paastosin minä ja itkin, sillä minä ajattelin: Kenties Herra on minulle armollinen, niin että lapsi jää eloon.'),
(1677225,58,10,12,23,'Mutta kun hän nyt on kuollut, niin mitä minä enää paastoaisin? Enhän minä enää voi palauttaa häntä. Minä menen hänen tykönsä, mutta hän ei enää palaja minun tyköni."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677226,58,10,12,24,'Daavid lohdutti vaimoansa Batsebaa ja meni hänen luoksensa ja makasi hänen kanssansa. Ja tämä synnytti pojan, ja hän antoi tälle nimen Salomo, ja Herra rakasti häntä.'),
(1677227,58,10,12,25,'Ja Daavid laittoi hänet profeetta Naatanin hoitoon, ja tämä kutsui häntä Jedidjaksi Herran tähden.'),
(1677228,58,10,12,26,'Mutta Jooab ryhtyi taistelemaan ammonilaisten Rabbaa vastaan ja valloitti kuninkaan kaupungin.'),
(1677229,58,10,12,27,'Ja Jooab lähetti sanansaattajat Daavidin luo ja käski sanoa: "Minä olen ryhtynyt taisteluun Rabbaa vastaan ja olen jo valloittanut vesikaupungin.'),
(1677230,58,10,12,28,'Niin kokoa nyt jäljellä oleva väki ja asetu leiriin kaupungin edustalle ja valloita se, etten minä sitä valloittaisi ja ottaisi sitä nimiini."'),
(1677231,58,10,12,29,'Silloin Daavid kokosi kaiken väen ja lähti Rabbaan, ryhtyi taisteluun sitä vastaan ja valloitti sen.'),
(1677232,58,10,12,30,'Ja hän otti heidän kuninkaansa kruunun hänen päästänsä - se painoi talentin kultaa, ja siinä oli kallis kivi - ja se pantiin Daavidin päähän. Ja hän vei sangen paljon saalista kaupungista.'),
(1677233,58,10,12,31,'Ja kansan, mitä siellä oli, hän vei pois ja asetti heitä kivisahojen ja rautahakkujen ja rautakirveiden ääreen ja pani heitä tiilentekoon. Näin hän teki kaikille ammonilaisten kaupungeille. Sitten Daavid ja kaikki väki palasi Jerusalemiin.'),
(1677234,58,10,13,1,'Sen jälkeen tapahtui tämä. Daavidin pojalla Absalomilla oli kaunis sisar nimeltä Taamar, ja Daavidin poika Amnon rakastui häneen.'),
(1677235,58,10,13,2,'Ja Amnon tuli aivan sairaaksi tuskasta sisarensa Taamarin tähden; sillä kun tämä oli neitsyt, näytti Amnonista mahdottomalta tehdä hänelle mitään.'),
(1677236,58,10,13,3,'Mutta Amnonilla oli ystävä, nimeltä Joonadab, Daavidin veljen Simean poika; ja Joonadab oli hyvin ovela mies.'),
(1677237,58,10,13,4,'Tämä sanoi hänelle: "Miksi sinä kuihdut noin päivä päivältä, kuninkaan poika? Etkö ilmaise minulle sitä?" Amnon vastasi hänelle: "Minä olen rakastunut veljeni Absalomin sisareen Taamariin".'),
(1677238,58,10,13,5,'Joonadab sanoi hänelle: "Paneudu vuoteeseesi ja tekeydy sairaaksi. Ja kun isäsi tulee katsomaan sinua, niin sano hänelle: ''Salli minun sisareni Taamarin tulla antamaan minulle jotakin syötävää; jos hän valmistaisi ruuan minun silmieni edessä, että minä näkisin sen, niin minä söisin hänen kädestään''."'),
(1677239,58,10,13,6,'Niin Amnon paneutui maata ja tekeytyi sairaaksi. Kun kuningas tuli katsomaan häntä, sanoi Amnon kuninkaalle: "Salli minun sisareni Taamarin tulla tekemään kaksi kakkua minun silmieni edessä, niin minä syön hänen kädestään".'),
(1677240,58,10,13,7,'Silloin Daavid lähetti sanan Taamarille linnaan ja käski sanoa hänelle: "Mene veljesi Amnonin taloon ja valmista hänelle ruokaa".'),
(1677241,58,10,13,8,'Niin Taamar meni veljensä Amnonin taloon, jossa tämä makasi. Ja hän otti taikinaa, sotki ja teki kakkuja hänen silmiensä edessä ja paistoi kakut,'),
(1677242,58,10,13,9,'otti pannun ja kaatoi hänen eteensä; mutta tämä ei tahtonut syödä. Ja Amnon sanoi: "Toimittakaa kaikki minun luotani ulos". Niin menivät kaikki hänen luotaan ulos.'),
(1677243,58,10,13,10,'Sitten Amnon sanoi Taamarille: "Tuo ruoka tänne sisähuoneeseen, syödäkseni sinun kädestäsi". Niin Taamar otti tekemänsä kakut ja toi ne sisähuoneeseen veljellensä Amnonille.'),
(1677244,58,10,13,11,'Mutta kun hän tarjosi niitä tälle syödä, tarttui tämä häneen ja sanoi hänelle: "Tule, makaa minun kanssani, sisareni!"'),
(1677245,58,10,13,12,'Mutta hän sanoi: "Pois se, veljeni, älä tee minulle väkivaltaa; sillä semmoista ei saa tehdä Israelissa. Älä tee sellaista häpeällistä tekoa.'),
(1677246,58,10,13,13,'Mihin minä joutuisin häpeäni kanssa? Ja sinua pidettäisiin Israelissa houkkana. Puhu nyt kuninkaan kanssa; hän ei minua sinulta kiellä."'),
(1677247,58,10,13,14,'Mutta tämä ei tahtonut kuulla häntä, vaan voitti hänet, teki hänelle väkivaltaa ja makasi hänet.'),
(1677248,58,10,13,15,'Mutta sitten valtasi Amnonin ylen suuri vastenmielisyys häntä kohtaan: vastenmielisyys häntä kohtaan oli suurempi kuin rakkaus, jolla hän oli häntä rakastanut. Ja Amnon sanoi hänelle: "Nouse, mene tiehesi".'),
(1677249,58,10,13,16,'Silloin hän sanoi hänelle: "Eikö tämä rikos, että ajat minut pois, ole vielä suurempi kuin se toinen, jonka olet minulle tehnyt?" Mutta hän ei tahtonut kuulla häntä,'),
(1677250,58,10,13,17,'vaan huusi nuoren miehen, joka häntä palveli, ja sanoi: "Ajakaa ulos minun luotani tämä, ja lukitse ovi hänen jälkeensä".'),
(1677251,58,10,13,18,'Ja tytöllä oli yllään pitkäliepeinen, hihallinen ihokas; sillä sellaisiin viittoihin olivat kuninkaan tyttäret puetut neitsyenä ollessaan. Ja kun palvelija oli vienyt hänet ulos ja lukinnut oven hänen jälkeensä,'),
(1677252,58,10,13,19,'sirotteli Taamar tuhkaa päähänsä ja repäisi pitkäliepeisen, hihallisen ihokkaan, joka hänellä oli yllänsä, pani kätensä päänsä päälle ja meni huutaen lakkaamatta.'),
(1677253,58,10,13,20,'Hänen veljensä Absalom sanoi hänelle: "Onko veljesi Amnon ollut sinun kanssasi? Vaikene nyt, sisareni, onhan hän veljesi. Älä pane tätä asiaa niin sydämellesi." Niin Taamar jäi hyljättynä veljensä Absalomin taloon.'),
(1677254,58,10,13,21,'Kun kuningas Daavid kuuli kaiken tämän, vihastui hän kovin.'),
(1677255,58,10,13,22,'Mutta Absalom ei puhunut Amnonille sanaakaan, ei pahaa eikä hyvää, sillä Absalom vihasi Amnonia, sentähden että tämä oli tehnyt väkivaltaa hänen sisarellensa Taamarille.'),
(1677256,58,10,13,23,'Kahden vuoden kuluttua tapahtui, että Absalomilla oli lammasten keritsiäiset Baal-Haasorissa, joka on Efraimin luona. Ja Absalom kutsui sinne kaikki kuninkaan pojat.'),
(1677257,58,10,13,24,'Ja Absalom tuli kuninkaan tykö ja sanoi: "Katso, palvelijallasi on lammasten keritsiäiset; jospa kuningaskin palvelijoineen tulisi palvelijansa luo".'),
(1677258,58,10,13,25,'Mutta kuningas vastasi Absalomille: "Ei niin, poikani, älkäämme tulko kaikki, ettemme olisi sinulle vaivaksi". Ja vaikka hän pyytämällä pyysi häntä, ei hän kuitenkaan tahtonut mennä, vaan hyvästeli hänet.'),
(1677259,58,10,13,26,'Silloin Absalom sanoi: "Jollet itse tulekaan, salli kuitenkin veljeni Amnonin tulla meidän kanssamme". Kuningas sanoi hänelle: "Miksi juuri hänen olisi mentävä sinun kanssasi?"'),
(1677260,58,10,13,27,'Mutta kun Absalom pyytämällä pyysi häntä, päästi hän Amnonin ja kaikki muut kuninkaan pojat menemään hänen kanssansa.'),
(1677261,58,10,13,28,'Ja Absalom käski palvelijoitaan ja sanoi: "Pitäkää silmällä, milloin Amnonin sydän tulee iloiseksi viinistä, ja kun minä sanon teille: ''Surmatkaa Amnon'', niin tappakaa hänet älkääkä peljätkö; sillä minähän olen teitä käskenyt. Olkaa lujat ja urhoolliset."'),
(1677262,58,10,13,29,'Absalomin palvelijat tekivät Amnonille, niinkuin Absalom oli käskenyt. Silloin kaikki kuninkaan pojat nousivat, istuivat kukin muulinsa selkään ja pakenivat.'),
(1677263,58,10,13,30,'Heidän vielä ollessaan matkalla tuli Daavidille sanoma: "Absalom on surmannut kaikki kuninkaan pojat, niin ettei heistä ole jäänyt jäljelle ainoatakaan".'),
(1677264,58,10,13,31,'Silloin kuningas nousi, repäisi vaatteensa ja paneutui maahan maata; ja kaikki hänen palvelijansa seisoivat siinä reväistyin vaattein.'),
(1677265,58,10,13,32,'Niin Joonadab, Daavidin veljen Simean poika, puhkesi puhumaan ja sanoi: "Älköön herrani luulko, että kaikki nuoret miehet, kuninkaan pojat, ovat tapetut; ainoastaan Amnon on kuollut. Sillä ilme Absalomin kasvoilla on tiennyt pahaa siitä päivästä lähtien, jona Amnon teki väkivaltaa hänen sisarellensa Taamarille.'),
(1677266,58,10,13,33,'Älköön siis herrani, kuningas, panko sydämelleen sitä puhetta, että muka kaikki kuninkaan pojat olisivat kuolleet; sillä ainoastaan Amnon on kuollut."'),
(1677267,58,10,13,34,'Mutta Absalom pakeni. Kun palvelija, joka oli tähystäjänä, nosti silmänsä ja katseli, niin katso, paljon väkeä tuli tietä, joka oli hänen takanansa, vuoren kuvetta.'),
(1677268,58,10,13,35,'Silloin Joonadab sanoi kuninkaalle: "Katso, kuninkaan pojat tulevat. On tapahtunut, niinkuin palvelijasi sanoi."'),
(1677269,58,10,13,36,'Juuri kun hän oli saanut sen sanotuksi, niin katso, kuninkaan pojat tulivat; ja he korottivat äänensä ja itkivät. Myöskin kuningas ja kaikki hänen palvelijansa itkivät hyvin katkerasti.'),
(1677270,58,10,13,37,'Mutta Absalom oli paennut ja mennyt Gesurin kuninkaan Talmain, Ammihudin pojan, luo. Ja Daavid suri poikaansa kaiken aikaa.'),
(1677271,58,10,13,38,'Kun Absalom oli paennut ja tullut Gesuriin, jäi hän sinne kolmeksi vuodeksi.'),
(1677272,58,10,13,39,'Ja kuningas Daavid ikävöi päästä Absalomin luo, sillä hän oli lohduttautunut Amnonin kuolemasta.'),
(1677273,58,10,14,1,'Kun Jooab, Serujan poika, huomasi, että kuninkaan sydän oli kääntynyt Absalomin puoleen,'),
(1677274,58,10,14,2,'lähetti Jooab noutamaan Tekoasta taitavan vaimon ja sanoi hänelle: "Ole surevinasi ja pukeudu suruvaatteisiin äläkä voitele itseäsi öljyllä, vaan ole niinkuin vaimo, joka jo kauan on surrut vainajaa.'),
(1677275,58,10,14,3,'Mene sitten kuninkaan eteen ja puhu hänelle näin." Ja Jooab pani sanat hänen suuhunsa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677276,58,10,14,4,'Niin tekoalainen vaimo meni kuninkaan eteen, lankesi kasvoillensa maahan ja osoitti kunnioitusta ja sanoi: "Auta, kuningas!"'),
(1677277,58,10,14,5,'Kuningas sanoi hänelle: "Mikä sinun on?" Hän vastasi: "Totisesti, minä olen leskivaimo; mieheni on kuollut.'),
(1677278,58,10,14,6,'Ja sinun palvelijattarellasi oli kaksi poikaa; he tulivat riitaan keskenänsä kedolla, eikä siellä ollut ketään, joka olisi sovittanut heidän välinsä, ja niin toinen löi toisen kuoliaaksi.'),
(1677279,58,10,14,7,'Ja katso, koko suku on noussut palvelijatartasi vastaan, ja he sanovat: ''Anna tänne veljensä surmaaja, että me otamme häneltä hengen hänen tapetun veljensä hengestä ja niin hävitämme perillisenkin''. Niin he sammuttaisivat kipinänkin, joka minulla vielä on jäljellä, ettei miehestäni jäisi nimeä eikä jälkeläistä maan päälle."'),
(1677280,58,10,14,8,'Kuningas sanoi vaimolle: "Mene kotiisi, minä annan käskyn sinusta".'),
(1677281,58,10,14,9,'Mutta tekoalainen vaimo sanoi kuninkaalle: "Herrani, kuningas, tulkoon tämä rikos minun ja minun isäni perheen kannettavaksi, mutta kuningas ja hänen valtaistuimensa olkoon siitä vapaa".'),
(1677282,58,10,14,10,'Kuningas sanoi: "Tuo minun eteeni se, joka puhuu sinulle niin, ja hän ei enää sinuun koske".'),
(1677283,58,10,14,11,'Vaimo sanoi: "Muistakoon kuningas Herraa Jumalaansa, ettei verenkostaja saisi tuottaa vielä suurempaa turmiota, ja ettei minun poikaani tuhottaisi". Silloin hän sanoi: "Niin totta kuin Herra elää: ei hiuskarvaakaan sinun poikasi päästä ole putoava maahan".'),
(1677284,58,10,14,12,'Mutta vaimo sanoi: "Salli palvelijattaresi puhua vielä sananen herralleni, kuninkaalle". Hän vastasi: "Puhu".'),
(1677285,58,10,14,13,'Vaimo sanoi: "Miksi sinä ajattelet tehdä juuri samoin Jumalan kansaa vastaan, koskapa kuningas ei salli oman hylkäämänsä tulla takaisin? Noin puhuessaanhan kuningas itse joutuu ikäänkuin syylliseksi.'),
(1677286,58,10,14,14,'Mehän kuolemme ja olemme niinkuin maahan kaadettu vesi, jota ei voi koota takaisin. Mutta Jumala ei ota pois elämää, vaan sitä hän ajattelee, ettei vain hyljätty joutuisi hänestä erotetuksi.'),
(1677287,58,10,14,15,'Sentähden minä tulin nyt puhumaan tätä herralleni, kuninkaalle, kun kansa sai minut pelkäämään; silloin ajatteli palvelijattaresi: minä puhun kuninkaalle, ehkä kuningas tekee palvelijattarensa sanan mukaan.'),
(1677288,58,10,14,16,'Niin, kuningas on kuuleva ja pelastava palvelijattarensa sen miehen kourista, joka tahtoo hävittää sekä minut että minun poikani Jumalan perintöosasta.'),
(1677289,58,10,14,17,'Ja palvelijattaresi ajatteli: minun herrani, kuninkaan, sana on rauhoittava minut. Sillä herrani, kuningas, on Jumalan enkelin kaltainen, niin että hän kuulee, mikä hyvää on ja mikä pahaa. Ja Herra, sinun Jumalasi, olkoon sinun kanssasi."'),
(1677290,58,10,14,18,'Kuningas vastasi ja sanoi vaimolle: "Älä salaa minulta mitään, mitä minä sinulta kysyn". Vaimo sanoi: "Herrani, kuningas, puhukoon".'),
(1677291,58,10,14,19,'Kuningas kysyi: "Eikö Jooabin käsi ole mukanasi kaikessa tässä?" Vaimo vastasi ja sanoi: "Niin totta kuin sinun sielusi, minun herrani, kuningas, elää: ei pääse oikeaan eikä vasempaan siitä, mitä herrani, kuningas, puhuu. Niin, sinun palvelijasi Jooab on käskenyt minua tähän ja pannut kaikki nämä sanat palvelijattaresi suuhun.'),
(1677292,58,10,14,20,'Antaakseen asialle toisen muodon on palvelijasi Jooab näin tehnyt; mutta herrani on viisas niinkuin Jumalan enkeli ja tietää kaiken, mitä maan päällä tapahtuu."'),
(1677293,58,10,14,21,'Silloin kuningas sanoi Jooabille: "Katso, tämän minä teen: mene ja tuo takaisin nuorukainen Absalom".'),
(1677294,58,10,14,22,'Niin Jooab lankesi kasvoilleen maahan, osoitti kunnioitusta ja siunasi kuningasta. Ja Jooab sanoi: "Nyt palvelijasi tietää, että minä olen saanut armon sinun silmiesi edessä, herrani, kuningas, koska kuningas tekee palvelijansa sanan mukaan".'),
(1677295,58,10,14,23,'Sitten Jooab nousi ja meni Gesuriin ja toi Absalomin Jerusalemiin.'),
(1677296,58,10,14,24,'Mutta kuningas sanoi: "Hän siirtyköön omaan taloonsa, mutta älköön tulko minun kasvojeni eteen". Niin Absalom siirtyi omaan taloonsa, mutta ei tullut kuninkaan kasvojen eteen.'),
(1677297,58,10,14,25,'Mutta koko Israelissa ei ollut yhtään niin kaunista miestä kuin Absalom, eikä ketään niin ylisteltyä: kantapäästä kiireeseen asti ei ollut hänessä yhtään virheä.'),
(1677298,58,10,14,26,'Ja kun hän ajatti hiuksensa - aina vuoden kuluttua hän ajatti ne, sillä ne tulivat hänelle niin raskaiksi, että hänen täytyi ne ajattaa - niin painoivat hänen hiuksensa kaksisataa sekeliä kuninkaan painoa.'),
(1677299,58,10,14,27,'Ja Absalomille syntyi kolme poikaa ja tytär, jonka nimi oli Taamar; hän oli kaunis nainen.'),
(1677300,58,10,14,28,'Absalom asui kaksi vuotta Jerusalemissa, tulematta kuninkaan kasvojen eteen.'),
(1677301,58,10,14,29,'Ja Absalom lähetti sanan Jooabille lähettääkseen hänet kuninkaan luo; mutta tämä ei tahtonut tulla hänen luokseen. Ja hän lähetti vielä toisen kerran, mutta hän ei tahtonut tulla.'),
(1677302,58,10,14,30,'Silloin hän sanoi palvelijoillensa: "Katsokaa, Jooabin maapalsta on minun maapalstani vieressä, ja hänellä on siinä ohraa; menkää ja sytyttäkää se palamaan". Ja Absalomin palvelijat sytyttivät maapalstan palamaan.'),
(1677303,58,10,14,31,'Niin Jooab nousi ja meni Absalomin luo taloon ja sanoi hänelle: "Miksi sinun palvelijasi ovat sytyttäneet palamaan maapalstan, joka on minun omani?"'),
(1677304,58,10,14,32,'Absalom vastasi Jooabille: "Katso, minä lähetin sinulle sanan: Tule tänne, niin minä lähetän sinut kuninkaan luo sanomaan: Mitä varten minä olen tullut kotiin Gesurista? Olisi parempi, jos vielä olisin siellä. Nyt minä tahdon tulla kuninkaan kasvojen eteen; ja jos minussa on vääryys, niin surmatkoon hän minut."'),
(1677305,58,10,14,33,'Silloin Jooab meni kuninkaan tykö ja kertoi hänelle tämän. Ja hän kutsui Absalomin, ja tämä tuli kuninkaan tykö ja kumartui kasvoilleen maahan kuninkaan eteen. Ja kuningas suuteli Absalomia.'),
(1677306,58,10,15,1,'Mutta sitten tapahtui, että Absalom hankki itsellensä vaunut ja hevoset sekä viisikymmentä miestä, jotka juoksivat hänen edellänsä.'),
(1677307,58,10,15,2,'Ja Absalomilla oli tapana asettua varhain aamulla sen tien viereen, joka vei portille; ja kun joku oli tulossa kuninkaan eteen saamaan oikeutta riita-asiassaan, kutsui Absalom hänet ja kysyi: "Mistä kaupungista sinä olet?" Kun tämä vastasi: "Palvelijasi on siitä tai siitä Israelin sukukunnasta",'),
(1677308,58,10,15,3,'sanoi Absalom hänelle: "Asiasi on kyllä hyvä ja oikea, mutta kuninkaan luona ei ole ketään, joka sinua kuulisi".'),
(1677309,58,10,15,4,'Ja Absalom sanoi vielä: "Jospa minut asetettaisiin tuomariksi maahan! Silloin tulisi minun eteeni jokainen, jolla on riita- tai oikeusasia, ja minä antaisin hänelle oikeuden."'),
(1677310,58,10,15,5,'Ja kun joku lähestyi kumartaaksensa häntä, ojensi hän kätensä, tarttui häneen ja suuteli häntä.'),
(1677311,58,10,15,6,'Näin Absalom teki kaikille israelilaisille, jotka tulivat kuninkaan eteen saamaan oikeutta. Ja niin Absalom varasti Israelin miesten sydämet.'),
(1677312,58,10,15,7,'Neljän vuoden kuluttua sanoi Absalom kerran kuninkaalle: "Salli minun mennä Hebroniin täyttämään lupaus, jonka olen Herralle tehnyt.'),
(1677313,58,10,15,8,'Sillä asuessani Gesurissa, Aramissa, sinun palvelijasi teki lupauksen ja sanoi: ''Jos Herra antaa minun tulla takaisin Jerusalemiin, niin minä palvelen Herraa''."'),
(1677314,58,10,15,9,'Kuningas sanoi hänelle: "Mene rauhassa". Niin hän nousi ja meni Hebroniin.'),
(1677315,58,10,15,10,'Mutta Absalom lähetti vakoojia kaikkiin Israelin sukukuntiin ja sanoi: "Kun kuulette pasunan äänen, niin sanokaa: ''Absalom on tullut kuninkaaksi Hebronissa''".'),
(1677316,58,10,15,11,'Ja Absalomin kanssa oli Jerusalemista kutsuvieraina mennyt kaksisataa miestä, jotka menivät sinne aivan viattomina, tietämättä mitään koko asiasta.'),
(1677317,58,10,15,12,'Ja Absalom lähetti myös, sillä aikaa kun uhrasi teurasuhrejaan, noutamaan giilolaisen Ahitofelin, Daavidin neuvonantajan, hänen kaupungistaan Giilosta. Ja salaliitto vahvistui, ja yhä enemmän kansaa meni Absalomin puolelle.'),
(1677318,58,10,15,13,'Niin tultiin Daavidin luo ja ilmoitettiin: "Israelin miesten sydämet ovat kääntyneet Absalomin puolelle".'),
(1677319,58,10,15,14,'Silloin Daavid sanoi kaikille palvelijoillensa, jotka olivat hänen luonaan Jerusalemissa: "Nouskaa, paetkaamme, sillä meillä ei ole muuta pelastusta Absalomin käsistä. Lähtekää kiiruusti, ettei hän äkkiä saavuttaisi meitä ja saattaisi onnettomuutta meille ja surmaisi kaupungin asukkaita miekan terällä."'),
(1677320,58,10,15,15,'Kuninkaan palvelijat vastasivat kuninkaalle: "Tehtäköön aivan niinkuin herrani, kuningas, harkitsee parhaaksi. Me olemme sinun palvelijoitasi."'),
(1677321,58,10,15,16,'Ja kuningas lähti, ja koko hänen hovinsa seurasi häntä; kuitenkin jätti kuningas kymmenen sivuvaimoaan jäljelle vartioimaan linnaa.'),
(1677322,58,10,15,17,'Niin kuningas lähti, ja kaikki väki seurasi häntä. He pysähtyivät kaukaisimman talon kohdalle'),
(1677323,58,10,15,18,'kaikkien hänen palvelijainsa kulkiessa hänen ohitsensa. Myös kaikki kreetit ja pleetit sekä kaikki gatilaiset, kuusisataa miestä, jotka olivat tulleet hänen jäljessään Gatista, kulkivat kuninkaan ohitse.'),
(1677324,58,10,15,19,'Niin kuningas sanoi gatilaiselle Ittaille: "Miksi sinäkin tulet meidän kanssamme? Käänny takaisin ja jää kuninkaan luo, sillä sinä olet vieras, vieläpä maanpaossa kotoasi.'),
(1677325,58,10,15,20,'Eilen sinä tulit; ottaisinko minä jo tänä päivänä sinut harhailemaan meidän kanssamme matkallamme, kun minä itsekin menen, minne menenkin? Käänny takaisin ja vie veljesi mukanasi. Armo ja uskollisuus sinulle!"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677326,58,10,15,21,'Mutta Ittai vastasi kuninkaalle ja sanoi: "Niin totta kuin Herra elää, ja niin totta kuin herrani, kuningas, elää: missä paikassa herrani, kuningas, on, siellä tahtoo myös palvelijasi olla, olkoonpa se elämäksi tai kuolemaksi".'),
(1677327,58,10,15,22,'Daavid sanoi Ittaille: "Tule sitten ja kulje minun ohitseni". Niin gatilainen Ittai kulki ohitse ja kaikki hänen miehensä ja kaikki vaimot ja lapset, jotka olivat hänen kanssaan.'),
(1677328,58,10,15,23,'Ja koko maa itki ääneen, kun kaikki väki kulki ohitse. Ja kun kuningas oli kulkemassa Kidronin laakson poikki, kaiken väen kulkiessa erämaan tielle päin,'),
(1677329,58,10,15,24,'niin katso, siinä oli myös Saadok ynnä hänen kanssaan kaikki leeviläiset, jotka kantoivat Jumalan liitonarkkia. Mutta he laskivat Jumalan arkin maahan, ja Ebjatar uhrasi, kunnes kaikki väki kaupungista oli ehtinyt kulkea ohitse.'),
(1677330,58,10,15,25,'Niin kuningas sanoi Saadokille: "Vie Jumalan arkki takaisin kaupunkiin. Jos minä saan armon Herran silmien edessä, tuo hän minut takaisin ja antaa minun vielä nähdä hänet ja hänen asumuksensa.'),
(1677331,58,10,15,26,'Mutta jos hän sanoo näin: ''Minä en ole mielistynyt sinuun'', niin katso, hän tehköön minulle, minkä hyväksi näkee."'),
(1677332,58,10,15,27,'Ja kuningas sanoi pappi Saadokille: "Sinähän olet näkijä; palaa rauhassa kaupunkiin, sinä ja sinun poikasi Ahimaas ja Ebjatarin poika Joonatan, molemmat poikanne, teidän kanssanne.'),
(1677333,58,10,15,28,'Katsokaa, minä viivyn kahlauspaikoissa erämaassa, kunnes teiltä tulee sana minun tiedokseni."'),
(1677334,58,10,15,29,'Niin Saadok ja Ebjatar veivät Jumalan arkin takaisin Jerusalemiin ja jäivät sinne.'),
(1677335,58,10,15,30,'Mutta Daavid kulki itkien Öljymäkeä ylös, pää peitettynä ja paljain jaloin. Ja kaikki väki, mikä oli hänen kanssansa, oli myös peittänyt päänsä, ja he kulkivat itkien lakkaamatta.'),
(1677336,58,10,15,31,'Ja kun Daavidille kerrottiin, että myös Ahitofel oli salaliittolaisten joukossa Absalomin puolella, sanoi Daavid: "Herra, käännä Ahitofelin neuvo hulluudeksi".'),
(1677337,58,10,15,32,'Kun sitten Daavid oli tullut vuoren laelle, jossa Jumalaa rukoiltiin, tuli arkilainen Huusai häntä vastaan, ihokas reväistynä ja multaa pään päällä.'),
(1677338,58,10,15,33,'Daavid sanoi hänelle: "Jos sinä tulet minun kanssani, niin olet minulle vain kuormaksi.'),
(1677339,58,10,15,34,'Mutta jos palaat kaupunkiin ja sanot Absalomille: ''Minä tahdon olla sinun palvelijasi, kuningas. Minä olen ennen ollut sinun isäsi palvelija, mutta nyt tahdon olla sinun palvelijasi'', niin voit olla minulle avuksi tekemällä Ahitofelin neuvon tyhjäksi.'),
(1677340,58,10,15,35,'Siellähän ovat sinun kanssasi myöskin papit, Saadok ja Ebjatar; kaikki, mitä kuulet kuninkaan linnasta, ilmoita papeille, Saadokille ja Ebjatarille.'),
(1677341,58,10,15,36,'Katso, heillä on siellä mukanaan myös molemmat poikansa, Saadokilla Ahimaas ja Ebjatarilla Joonatan; näiden kautta voitte lähettää minulle tiedon kaikesta, mitä kuulette."'),
(1677342,58,10,15,37,'Niin Huusai, Daavidin ystävä, meni kaupunkiin, juuri kun Absalom tuli Jerusalemiin.'),
(1677343,58,10,16,1,'Kun Daavid oli kulkenut vähän matkaa vuoren laelta, tuli häntä vastaan Siiba, Mefibosetin palvelija, mukanaan satuloitu aasipari, jonka selässä oli kaksisataa leipää, sata rusinakakkua, sata hedelmää ja leili viiniä.'),
(1677344,58,10,16,2,'Niin kuningas sanoi Siiballe: "Mitä sinä näillä teet?" Siiba vastasi: "Aasit ovat kuninkaan perheelle ratsastettaviksi, leipä ja hedelmät palvelijoille syötäviksi ja viini uupuneiden juotavaksi erämaassa".'),
(1677345,58,10,16,3,'Kuningas sanoi: "Mutta missä sinun herrasi poika on?" Siiba vastasi kuninkaalle: "Hän jäi Jerusalemiin; sillä hän ajatteli: ''Nyt Israelin heimo antaa minulle takaisin isäni kuninkuuden''".'),
(1677346,58,10,16,4,'Niin kuningas sanoi Siiballe: "Katso, kaikki, mitä Mefibosetilla on, tulee sinun omaksesi". Siiba vastasi: "Minä kumarran; suo minun saada armo sinun silmiesi edessä, herrani, kuningas".'),
(1677347,58,10,16,5,'Kun kuningas Daavid tuli Bahurimiin, niin katso, sieltä tuli mies, joka oli sukua Saulin perheelle, nimeltä Siimei, Geeran poika; hän tuli ja kiroili tullessaan.'),
(1677348,58,10,16,6,'Ja hän viskeli kivillä Daavidia ja kaikkia kuningas Daavidin palvelijoita, vaikka kaikki väki ja kaikki urhot olivat hänen oikealla ja vasemmalla puolellaan.'),
(1677349,58,10,16,7,'Ja kiroillessaan häntä Siimei sanoi näin: "Pois, pois, sinä murhamies, sinä kelvoton!'),
(1677350,58,10,16,8,'Herra kostaa sinulle kaiken Saulin perheen veren, hänen, jonka sijaan sinä olet tullut kuninkaaksi. Ja Herra antaa nyt kuninkuuden sinun poikasi Absalomin käteen. Ja katso, sinä olet itse joutunut onnettomuuteen, sillä murhamies sinä olet."'),
(1677351,58,10,16,9,'Niin Abisai, Serujan poika, sanoi kuninkaalle: "Miksi tuo koiranraato saa kiroilla herraani, kuningasta? Anna minun mennä ja lyödä häneltä pää poikki."'),
(1677352,58,10,16,10,'Mutta kuningas vastasi: "Mitä teillä on minun kanssani tekemistä, te Serujan pojat? Jos hän kiroilee ja jos Herra on käskenyt häntä: ''Kiroile Daavidia'', niin kuka voi sanoa: ''Miksi teet niin?''"'),
(1677353,58,10,16,11,'Ja Daavid sanoi vielä Abisaille ja kaikille palvelijoillensa: "Katso, oma poikani, joka on lähtenyt minun ruumiistani, väijyy henkeäni; miksi ei sitten tämä benjaminilainen? Antakaa hänen olla, kiroilkoon vain; sillä Herra on häntä käskenyt.'),
(1677354,58,10,16,12,'Ehkä Herra vielä näkee minun kurjuuteni, ja ehkä Herra maksaa minulle hyvällä sen kirouksen, joka tänä päivänä kohtaa minua."'),
(1677355,58,10,16,13,'Ja Daavid kulki miehinensä tietä myöten, ja Siimei kulki pitkin vuoren kuvetta rinnan hänen kanssansa, kiroili kulkiessaan ja viskeli kiviä ja heitteli soraa.'),
(1677356,58,10,16,14,'Kun kuningas ja kaikki väki, joka oli hänen kanssansa, oli tullut Ajefimiin, hengähti hän siellä.'),
(1677357,58,10,16,15,'Mutta Absalom ja kaikki kansa, Israelin miehet, olivat tulleet Jerusalemiin; ja Ahitofel oli hänen kanssansa.'),
(1677358,58,10,16,16,'Kun arkilainen Huusai, Daavidin ystävä, tuli Absalomin luo, sanoi Huusai Absalomille: "Eläköön kuningas! Eläköön kuningas!"'),
(1677359,58,10,16,17,'Absalom sanoi Huusaille: "Tällainenko on rakkautesi ystävääsi kohtaan? Miksi et mennyt ystäväsi kanssa?"'),
(1677360,58,10,16,18,'Huusai vastasi Absalomille: "Ei, vaan kenen Herra ja tämä kansa ja kaikki Israelin miehet ovat valinneet, sen puolella minä olen, ja sen luokse minä jään.'),
(1677361,58,10,16,19,'Ja toisekseen: ketä minä palvelisin? Enkö hänen poikaansa? Niinkuin olen palvellut sinun isääsi, niin tahdon palvella sinuakin."'),
(1677362,58,10,16,20,'Sitten Absalom sanoi Ahitofelille: "Antakaa nyt neuvo, mitä meidän on tehtävä".'),
(1677363,58,10,16,21,'Ahitofel vastasi Absalomille: "Mene isäsi sivuvaimojen tykö, jotka hän on jättänyt linnaa vartioimaan. Silloin koko Israel saa kuulla, että sinä olet saattanut itsesi isäsi vihoihin, ja kaikki, jotka ovat sinun kanssasi, saavat rohkeutta."'),
(1677364,58,10,16,22,'Niin Absalomille pystytettiin teltta katolle; ja Absalom meni isänsä sivuvaimojen tykö koko Israelin nähden.'),
(1677365,58,10,16,23,'Ahitofelin antama neuvo oli siihen aikaan niinkuin Jumalalta saatu vastaus: sen arvoinen oli jokainen Ahitofelin neuvo sekä Daavidille että Absalomille.'),
(1677366,58,10,17,1,'Ja Ahitofel sanoi Absalomille: "Salli minun valita kaksitoista tuhatta miestä ja nousta tänä yönä ajamaan takaa Daavidia,'),
(1677367,58,10,17,2,'niin minä karkaan hänen kimppuunsa, kun hän on väsynyt ja hänen kätensä ovat herpoutuneet, ja saatan hänet kauhun valtaan, niin että kaikki väki, mitä hänen kanssansa on, pakenee. Sitten minä surmaan kuninkaan yksinänsä.'),
(1677368,58,10,17,3,'Ja minä palautan kaiken kansan sinun luoksesi. Kaikkien palaaminen riippuu siitä miehestä, jota sinä etsit; kaikki kansa saa rauhan."'),
(1677369,58,10,17,4,'Tämä miellytti Absalomia ja kaikkia Israelin vanhimpia.'),
(1677370,58,10,17,5,'Kuitenkin sanoi Absalom: "Kutsukaa myös arkilainen Huusai, kuullaksemme, mitä hänellä on sanottavana".'),
(1677371,58,10,17,6,'Ja kun Huusai tuli Absalomin tykö, sanoi Absalom hänelle: "Niin ja niin puhui Ahitofel. Onko meidän tehtävä hänen sanansa mukaan? Jollei, niin puhu sinä."'),
(1677372,58,10,17,7,'Huusai vastasi Absalomille: "Ei ole hyvä se neuvo, jonka Ahitofel tällä kertaa on antanut".'),
(1677373,58,10,17,8,'Ja Huusai sanoi vielä: "Sinä tiedät, että isäsi ja hänen miehensä ovat urhoja ja julmistuneita niinkuin karhu kedolla, jolta poikaset on riistetty; myöskin on isäsi sotilas, joka väkineen ei lepää yöllä.'),
(1677374,58,10,17,9,'Katso, hän on nyt piiloutunut johonkin onkaloon tai muuhun paikkaan. Jos jo alussa meikäläisiä kaatuisi ja se saataisiin kuulla, niin sanottaisiin: ''Väelle, joka seurasi Absalomia, on tullut tappio''.'),
(1677375,58,10,17,10,'Silloin urhoollisinkin, jolla on sydän kuin leijonalla, menettäisi rohkeutensa; sillä koko Israel tietää, että sinun isäsi on sankari ja että ne, jotka ovat hänen kanssansa, ovat urhoollisia miehiä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677376,58,10,17,11,'Sentähden on minun neuvoni tämä: Koottakoon sinun luoksesi koko Israel Daanista aina Beersebaan asti, että niitä tulee niin paljon kuin hiekkaa meren rannalla; ja lähde sinä itsekin taisteluun.'),
(1677377,58,10,17,12,'Kun me sitten karkaamme hänen kimppuunsa, missä ikinä hänet tavataan, niin me painumme hänen päällensä, niinkuin kaste laskeutuu maahan. Eikä hänestä ja kaikista niistä miehistä, jotka ovat hänen kanssaan, jää jäljelle ainoatakaan.'),
(1677378,58,10,17,13,'Ja jos hän vetäytyisi johonkin kaupunkiin, niin koko Israel asettaisi köydet sen kaupungin ympärille, ja me kiskoisimme sen alas laaksoon, kunnes siitä ei löytyisi kiveäkään."'),
(1677379,58,10,17,14,'Silloin sanoivat Absalom ja kaikki Israelin miehet: "Arkilaisen Huusain neuvo on parempi kuin Ahitofelin neuvo". Sillä Herra oli säätänyt sen näin, tehdäkseen tyhjäksi Ahitofelin hyvän neuvon, että Herra saattaisi Absalomin onnettomuuteen.'),
(1677380,58,10,17,15,'Ja Huusai sanoi papeille, Saadokille ja Ebjatarille: "Sen ja sen neuvon on Ahitofel antanut Absalomille ja Israelin vanhimmille, ja sen ja sen neuvon olen minä antanut.'),
(1677381,58,10,17,16,'Niin lähettäkää nyt pian ja ilmoittakaa Daavidille tämä sana: ''Älä jää yöksi kahlauspaikkoihin erämaahan, vaan mene joen yli, ettei kuningas ja kaikki väki, joka on hänen kanssaan, joutuisi perikatoon''."'),
(1677382,58,10,17,17,'Ja Joonatan ja Ahimaas olivat asettuneet Roogelin lähteelle, ja eräs palvelijatar kuljetti heille sinne sanaa; sitten he aina menivät ja veivät sanan kuningas Daavidille. Sillä he eivät uskaltaneet näyttäytyä menemällä kaupunkiin.'),
(1677383,58,10,17,18,'Mutta eräs poikanen näki heidät ja ilmoitti Absalomille. Silloin he molemmat menivät kiiruusti pois ja tulivat erään miehen taloon Bahurimiin. Hänellä oli kaivo pihallaan, ja he laskeutuivat siihen.'),
(1677384,58,10,17,19,'Ja hänen vaimonsa otti peitteen ja levitti sen kaivon suulle ja sirotti jyviä sen päälle, niin ettei voitu huomata mitään.'),
(1677385,58,10,17,20,'Kun Absalomin palvelijat tulivat vaimon luo taloon, kysyivät he: "Missä ovat Ahimaas ja Joonatan?" Vaimo vastasi heille: "Tuosta he menivät vesilätäkön yli". He etsivät, ja kun eivät heitä löytäneet, palasivat he takaisin Jerusalemiin.'),
(1677386,58,10,17,21,'Ja niin pian kuin he olivat menneet, nousivat toiset kaivosta, menivät ja veivät sanan kuningas Daavidille; he sanoivat Daavidille: "Nouskaa ja menkää joutuin veden yli, sillä sen ja sen neuvon on Ahitofel antanut teidän turmioksenne".'),
(1677387,58,10,17,22,'Silloin Daavid ja kaikki väki, mikä oli hänen kanssaan, nousi, ja he menivät Jordanin yli. Ja kun aamu valkeni, ei ollut ainoatakaan, joka ei olisi tullut Jordanin yli.'),
(1677388,58,10,17,23,'Mutta kun Ahitofel näki, ettei hänen neuvoansa noudatettu, satuloi hän aasinsa, nousi ja lähti kotiinsa omaan kaupunkiinsa, ja kun hän oli toimittanut talonsa, hirttäytyi hän; niin hän kuoli, ja hänet haudattiin isänsä hautaan.'),
(1677389,58,10,17,24,'Daavid oli tullut Mahanaimiin, kun Absalom ja kaikki Israelin miehet hänen kanssaan menivät Jordanin yli.'),
(1677390,58,10,17,25,'Mutta Absalom oli asettanut Amasan Jooabin sijaan sotajoukon ylipäälliköksi. Ja Amasa oli Jitra nimisen jisreeliläisen miehen poika; tämä mies oli yhtynyt Abigailiin, Naahaan tyttäreen, Jooabin äidin Serujan sisareen.'),
(1677391,58,10,17,26,'Ja Israel ja Absalom leiriytyivät Gileadin maahan.'),
(1677392,58,10,17,27,'Kun Daavid tuli Mahanaimiin, niin Soobi, Naahaan poika, ammonilaisten Rabbasta, ja Maakir, Ammielin poika, Loodebarista, ja gileadilainen Barsillai, Roogelimista,'),
(1677393,58,10,17,28,'toivat sinne vuoteita, vateja ja saviastioita, nisuja, ohria, jauhoja ja paahdettuja jyviä, papuja, herneitä'),
(1677394,58,10,17,29,'sekä hunajaa, voita, lampaita ja juustoja ruuaksi Daavidille ja väelle, mikä oli hänen kanssansa; sillä he ajattelivat: "Väki on nälissään, uuvuksissa ja janoissaan erämaassa".'),
(1677395,58,10,18,1,'Ja Daavid piti mukanaan olevan väen katselmuksen, ja asetti sille tuhannen- ja sadanpäämiehet.'),
(1677396,58,10,18,2,'Sitten Daavid lähetti väen liikkeelle: yhden kolmanneksen Jooabin johdolla, toisen kolmanneksen Abisain, Serujan pojan, Jooabin veljen, johdolla ja kolmannen kolmanneksen gatilaisen Ittain johdolla. Ja kuningas sanoi kansalle: "Minä lähden myös itse teidän kanssanne".'),
(1677397,58,10,18,3,'Mutta kansa vastasi: "Älä lähde; sillä jos me pakenemme, ei meistä välitetä, ja jos puolet meistä saa surmansa, ei meistä silloinkaan välitetä, mutta sinä olet niinkuin kymmenen tuhatta meistä. Sentähden on nyt parempi, että sinä olet valmiina tulemaan meille avuksi kaupungista."'),
(1677398,58,10,18,4,'Niin kuningas sanoi heille: "Minä teen, minkä te hyväksi näette". Ja kuningas asettui portin pieleen, ja kaikki väki lähti liikkeelle sadan ja tuhannen joukkoina.'),
(1677399,58,10,18,5,'Mutta kuningas käski Jooabia, Abisaita ja Ittaita ja sanoi: "Pidelkää minulle mieliksi hellävaroen nuorukaista Absalomia". Ja kaikki kansa kuuli, kuinka kuningas antoi kaikille päälliköille käskyn Absalomista.'),
(1677400,58,10,18,6,'Niin väki lähti kentälle Israelia vastaan, ja taistelu tapahtui Efraimin metsässä.'),
(1677401,58,10,18,7,'Siellä Daavidin palvelijat voittivat Israelin väen, ja siellä oli sinä päivänä suuri mieshukka: kaksikymmentä tuhatta miestä.'),
(1677402,58,10,18,8,'Ja taistelu levisi koko siihen seutuun; ja metsä söi sinä päivänä enemmän väkeä kuin miekka.'),
(1677403,58,10,18,9,'Ja Absalom sattui yhteen Daavidin palvelijain kanssa. Absalom ratsasti muulilla; ja kun muuli tuli suuren, tiheäoksaisen tammen alle, tarttui hän päästään tammeen, niin että hän jäi riippumaan taivaan ja maan välille, kun muuli juoksi pois hänen altansa.'),
(1677404,58,10,18,10,'Sen näki eräs mies ja ilmoitti sen Jooabille ja sanoi: "Katso, minä näin Absalomin riippuvan tammessa".'),
(1677405,58,10,18,11,'Niin Jooab sanoi miehelle, joka ilmoitti hänelle tämän: "Jos näit sen, miksi et lyönyt häntä siinä maahan? Minun olisi ollut annettava sinulle kymmenen hopeasekeliä ja vyö."'),
(1677406,58,10,18,12,'Mutta mies vastasi Jooabille: "Vaikka käsiini punnittaisiin tuhat hopeasekeliä, en sittenkään kävisi käsiksi kuninkaan poikaan, sillä kuningas käski meidän kuultemme sinua, Abisaita ja Ittaita sanoen: ''Pitäkää vaari nuorukaisesta Absalomista''.'),
(1677407,58,10,18,13,'Vai kavaltaisinko minä oman henkeni? Sillä eihän mikään pysy salassa kuninkaalta, ja sinä pysyisit kyllä syrjässä."'),
(1677408,58,10,18,14,'Niin Jooab sanoi: "Minä en enää kuluta aikaa sinun kanssasi". Sitten hän otti kolme keihästä käteensä ja pisti ne Absalomin rintaan, kun hän vielä eli tammessa.'),
(1677409,58,10,18,15,'Ja kymmenen nuorta miestä, Jooabin aseenkantajaa, astui Absalomin luo, ja he löivät hänet kuoliaaksi.'),
(1677410,58,10,18,16,'Sitten Jooab puhalsi pasunaan; ja väki palasi ajamasta takaa Israelia, kun Jooab pysähdytti väen.'),
(1677411,58,10,18,17,'Ja he ottivat Absalomin ja heittivät hänet metsässä suureen kuoppaan ja pystyttivät sangen suuren kiviroukkion hänen päällensä. Mutta koko Israel pakeni, kukin majallensa.'),
(1677412,58,10,18,18,'Mutta Absalom oli eläessään hankkinut ja pystyttänyt itsellensä patsaan, joka on Kuninkaanlaaksossa; sillä hän sanoi: "Minulla ei ole poikaa, joka säilyttäisi minun nimeni muiston". Patsaan hän oli kutsunut nimensä mukaan, ja sen nimi on vielä tänäkin päivänä Absalomin muistomerkki.'),
(1677413,58,10,18,19,'Ja Ahimaas, Saadokin poika, sanoi: "Minä juoksen saattamaan kuninkaalle sen ilosanoman, että Herra on auttanut hänet hänen vihollistensa käsistä oikeuteensa".'),
(1677414,58,10,18,20,'Mutta Jooab sanoi hänelle: "Tänä päivänä et ole ilosanoman saattaja; jonakin muuna päivänä saattanet ilosanoman, mutta tänä päivänä et saata ilosanomaa, sillä onhan kuninkaan poika kuollut".'),
(1677415,58,10,18,21,'Sitten Jooab sanoi eräälle etiopialaiselle: "Mene ja ilmoita kuninkaalle, mitä olet nähnyt". Niin etiopialainen kumarsi Jooabille ja lähti juoksemaan.'),
(1677416,58,10,18,22,'Mutta Ahimaas, Saadokin poika, sanoi taas Jooabille: "Tulkoon mitä tahansa, mutta minä juoksen etiopialaisen jälkeen". Jooab sanoi: "Miksi sinä juoksisit, poikani, eihän sinulle siitä ilosanomansaattajan palkkaa tule?"'),
(1677417,58,10,18,23,'"Tulkoon mitä tahansa, mutta minä juoksen." Silloin hän sanoi hänelle: "Juokse sitten". Niin Ahimaas lähti juoksemaan Lakeuden tietä ja sivuutti etiopialaisen.'),
(1677418,58,10,18,24,'Daavid istui molempien porttien välissä. Ja tähystäjä meni portin katolle muurin päälle; kun hän nosti silmänsä ja katseli, niin katso: mies tuli juosten yksinänsä.'),
(1677419,58,10,18,25,'Tähystäjä huusi ja ilmoitti sen kuninkaalle. Niin kuningas sanoi: "Jos hän on yksin, niin hänellä on ilosanoma". Ja hän tuli yhä lähemmäksi.'),
(1677420,58,10,18,26,'Sitten tähystäjä näki toisen miehen tulevan juosten; ja hän huusi porttiin sanoen: "Minä näen vielä toisen miehen tulevan juosten yksinänsä". Kuningas sanoi: "Sekin saattaa ilosanomaa".'),
(1677421,58,10,18,27,'Ja tähystäjä sanoi: "Sen ensimmäisen juoksu näyttää minusta Ahimaasin, Saadokin pojan, juoksulta". Niin kuningas sanoi: "Se on hyvä mies; hän tulee hyviä sanomia tuoden".'),
(1677422,58,10,18,28,'Ja Ahimaas huusi ja sanoi kuninkaalle: "Rauha!" Sitten hän kumartui kasvoillensa maahan kuninkaan eteen ja sanoi: "Kiitetty olkoon Herra, sinun Jumalasi, joka on antanut sinun käsiisi ne miehet, jotka nostivat kätensä herraani, kuningasta, vastaan".'),
(1677423,58,10,18,29,'Niin kuningas kysyi: "Voiko nuorukainen Absalom hyvin?" Ahimaas vastasi: "Minä näin suuren väkijoukon, kun kuninkaan palvelija Jooab lähetti minut, palvelijasi; mutta en tiedä, mitä se oli".'),
(1677424,58,10,18,30,'Kuningas sanoi: "Astu syrjään ja asetu sinne". Niin hän astui syrjään ja jäi seisomaan sinne.'),
(1677425,58,10,18,31,'Ja katso, etiopialainen tuli perille, ja etiopialainen sanoi: "Ilosanoma herralleni, kuninkaalle: Herra on tänä päivänä auttanut sinut oikeuteesi kaikkien niiden käsistä, jotka ovat nousseet sinua vastaan".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677426,58,10,18,32,'Kuningas kysyi etiopialaiselta: "Voiko nuorukainen Absalom hyvin?" Etiopialainen vastasi: "Käyköön herrani kuninkaan vihollisille ja kaikille, jotka nousevat sinua vastaan tehdäksensä sinulle pahaa, niinkuin on käynyt sille nuorukaiselle".'),
(1677427,58,10,18,33,'(19:1) Kuningas tuli kovin järkytetyksi, nousi portin päällä olevaan yläsaliin ja itki. Ja mennessänsä hän huusi näin: "Poikani Absalom, minun poikani, oma poikani Absalom! Jospa minä olisin kuollut sinun sijastasi! Absalom, poikani, oma poikani!"'),
(1677428,58,10,19,1,'Jooabille ilmoitettiin: "Katso, kuningas itkee ja suree Absalomia".'),
(1677429,58,10,19,2,'(19:3) Ja voitto muuttui sinä päivänä suruksi kaikelle kansalle, koska kansa sinä päivänä kuuli sanottavan, että kuningas oli murheissaan poikansa tähden.'),
(1677430,58,10,19,3,'Ja kansa tuli sinä päivänä kaupunkiin ikäänkuin varkain, niinkuin tulee varkain väki, joka on häväissyt itsensä pakenemalla taistelusta.'),
(1677431,58,10,19,4,'Mutta kuningas oli peittänyt kasvonsa, ja hän huusi kovalla äänellä: "Poikani Absalom! Absalom, poikani, oma poikani!"'),
(1677432,58,10,19,5,'Niin Jooab meni sisälle kuninkaan luo ja sanoi: "Sinä olet tänä päivänä nostanut häpeän kaikkien palvelijaisi kasvoille, vaikka he tänä päivänä ovat pelastaneet sekä sinun oman henkesi että sinun poikiesi, tyttäriesi, vaimojesi ja sivuvaimojesi hengen.'),
(1677433,58,10,19,6,'Sinähän rakastat niitä, jotka sinua vihaavat, ja vihaat niitä, jotka sinua rakastavat. Sillä nyt sinä olet antanut tietää, ettei sinulla olekaan päälliköitä eikä palvelijoita; - niin, nyt minä tiedän, että jos Absalom olisi elossa ja me kaikki olisimme tänään kuolleet, se olisi sinulle mieleen.'),
(1677434,58,10,19,7,'Mutta nouse nyt ylös ja mene ulos ja puhuttele ystävällisesti palvelijoitasi. Sillä minä vannon Herran kautta: jollet mene ulos, niin ei totisesti yhtä ainoatakaan miestä jää luoksesi tänä yönä; ja tämä on oleva sinulle suurempi onnettomuus kuin mikään muu, joka on kohdannut sinua nuoruudestasi tähän päivään saakka."'),
(1677435,58,10,19,8,'Silloin kuningas nousi ja asettui istumaan porttiin. Ja kaikelle kansalle ilmoitettiin ja sanottiin: "Kuningas istuu nyt portissa". Silloin kaikki kansa tuli kuninkaan eteen. Mutta kun Israel oli paennut, kukin majallensa,'),
(1677436,58,10,19,9,'alkoi kaikki kansa kaikkien Israelin heimojen keskuudessa riidellä ja sanoa: "Kuningas on pelastanut meidät vihollistemme kourista, hän on vapauttanut meidät filistealaisten kourista, ja nyt hän on Absalomia paossa, maasta poissa.'),
(1677437,58,10,19,10,'Mutta Absalom, jonka me olemme voidelleet kuninkaaksemme, on kuollut taistelussa. Miksi ette nyt ryhdy tuomaan kuningasta takaisin?"'),
(1677438,58,10,19,11,'Mutta kuningas Daavid lähetti sanan papeille Saadokille ja Ebjatarille ja käski sanoa: "Puhukaa Juudan vanhimmille ja sanokaa: ''Miksi te olette viimeiset tuomaan kuningasta takaisin hänen linnaansa? Sillä se, mitä koko Israel puhuu, on tullut kuninkaan tietoon hänen olinpaikkaansa.'),
(1677439,58,10,19,12,'Te olette minun veljiäni, minun luutani ja lihaani. Miksi te olisitte viimeiset tuomaan kuningasta takaisin?'''),
(1677440,58,10,19,13,'Ja Amasalle sanokaa: ''Olethan sinä minun luutani ja lihaani. Jumala rangaiskoon minua nyt ja vasta, jollet sinä kaikkea elinaikaasi ole minun sotapäällikköni Jooabin sijassa.''"'),
(1677441,58,10,19,14,'Näin hän taivutti kaikkien Juudan miesten sydämet, niin että he yhtenä miehenä lähettivät sanomaan kuninkaalle: "Palaa takaisin, sinä ja kaikki sinun palvelijasi".'),
(1677442,58,10,19,15,'Niin kuningas palasi takaisin ja tuli Jordanille; mutta Juuda oli tullut Gilgaliin mennäkseen kuningasta vastaan ja tuodakseen kuninkaan Jordanin yli.'),
(1677443,58,10,19,16,'Myöskin Siimei, Geeran poika, benjaminilainen Bahurimista, lähti kiiruusti Juudan miesten kanssa kuningas Daavidia vastaan.'),
(1677444,58,10,19,17,'Ja hänen kanssansa oli tuhat miestä Benjaminista sekä Siiba, Saulin perheen palvelija, viidentoista poikansa ja kahdenkymmenen palvelijansa kanssa. Nämä olivat rientäneet Jordanille ennen kuningasta'),
(1677445,58,10,19,18,'ja menneet yli kahlauspaikasta tuomaan kuninkaan perhettä ja toimittamaan, mitä hän näkisi hyväksi määrätä. Mutta Siimei, Geeran poika, heittäytyi kuninkaan eteen, kun hän oli lähtemässä Jordanin yli,'),
(1677446,58,10,19,19,'ja sanoi kuninkaalle: "Älköön herrani lukeko minulle pahaa tekoani älköönkä muistelko, kuinka väärin palvelijasi teki sinä päivänä, jona herrani, kuningas, lähti Jerusalemista; älköön kuningas panko sitä sydämellensä.'),
(1677447,58,10,19,20,'Sillä palvelijasi tuntee, että olen tehnyt synnin; sentähden minä olen tänä päivänä ensimmäisenä koko Joosefin heimosta tullut tänne herraani, kuningasta, vastaan."'),
(1677448,58,10,19,21,'Niin Abisai, Serujan poika, puuttui puheeseen ja sanoi: "Eikö Siimei ole rangaistava kuolemalla siitä, että hän on kiroillut Herran voideltua?"'),
(1677449,58,10,19,22,'Mutta Daavid vastasi: "Mitä teillä on minun kanssani tekemistä, te Serujan pojat, kun tulette minulle tänä päivänä kiusaajaksi? Olisiko ketään Israelissa tänä päivänä kuolemalla rangaistava? Minä tiedän tulleeni tänä päivänä Israelin kuninkaaksi."'),
(1677450,58,10,19,23,'Ja kuningas sanoi Siimeille: "Sinä et kuole". Ja kuningas vannoi sen hänelle.'),
(1677451,58,10,19,24,'Mefiboset, Saulin pojanpoika, oli myös tullut kuningasta vastaan. Hän ei ollut siistinyt jalkojansa, ei siistinyt partaansa eikä pesettänyt vaatteitansa siitä päivästä, jona kuningas lähti, siihen päivään asti, jona hän rauhassa tuli takaisin.'),
(1677452,58,10,19,25,'Kun hän nyt tuli Jerusalemista kuningasta vastaan, sanoi kuningas hänelle: "Miksi sinä et tullut minun kanssani, Mefiboset?"'),
(1677453,58,10,19,26,'Hän vastasi: "Herrani, kuningas, palvelijani petti minut. Sillä sinun palvelijasi sanoi hänelle: ''Satuloi minun aasini, ratsastaakseni sillä ja mennäkseni kuninkaan kanssa'' - sillä palvelijasihan on ontuva -'),
(1677454,58,10,19,27,'mutta hän on panetellut palvelijaasi herralle kuninkaalle. Herrani, kuningas, on kuitenkin niinkuin Jumalan enkeli; tee siis, mitä hyväksi näet.'),
(1677455,58,10,19,28,'Sillä koko minun isäni suku oli herrani, kuninkaan, edessä kuoleman oma, ja kuitenkin sinä asetit palvelijasi niiden joukkoon, jotka syövät sinun pöydässäsi. Mitäpä minulla on enää muuta oikeutta ja mitä valittamista kuninkaalle?"'),
(1677456,58,10,19,29,'Kuningas sanoi hänelle: "Mitäs tuosta enää puhut? Minä sanon, että sinä ja Siiba saatte jakaa keskenänne maaomaisuuden."'),
(1677457,58,10,19,30,'Niin Mefiboset sanoi kuninkaalle: "Ottakoon hän sen vaikka kokonaan, kun kerran herrani, kuningas, on palannut rauhassa kotiinsa".'),
(1677458,58,10,19,31,'Gileadilainen Barsillai oli myös tullut Roogelimista ja meni kuninkaan kanssa Jordanille saattamaan häntä Jordanin yli.'),
(1677459,58,10,19,32,'Barsillai oli hyvin vanha, kahdeksankymmenen vuoden vanha. Hän oli elättänyt kuningasta tämän ollessa Mahanaimissa, sillä hän oli hyvin rikas mies.'),
(1677460,58,10,19,33,'Kuningas sanoi nyt Barsillaille: "Tule sinä minun mukanani, niin minä elätän sinut luonani Jerusalemissa".'),
(1677461,58,10,19,34,'Mutta Barsillai vastasi kuninkaalle: "Montakopa ikävuotta minulla enää lienee, että menisin kuninkaan kanssa Jerusalemiin:'),
(1677462,58,10,19,35,'minä olen nyt kahdeksankymmenen vuoden vanha; osaisinko minä enää erottaa hyvää pahasta, tahi maistuisiko palvelijastasi miltään se, mitä hän syö ja mitä juo? Tahi kuuluisiko minusta enää miltään laulajain ja laulajattarien laulu? Miksi palvelijasi vielä tulisi herralleni, kuninkaalle, kuormaksi?'),
(1677463,58,10,19,36,'Ainoastaan vähän matkaa seuraa palvelijasi kuningasta tuolle puolelle Jordanin. Miksi kuningas antaisi minulle sellaisen korvauksen?'),
(1677464,58,10,19,37,'Salli palvelijasi palata takaisin, saadakseni kuolla omassa kaupungissani isäni ja äitini haudan ääressä. Mutta katso, tässä on palvelijasi Kimham, menköön hän herrani, kuninkaan, kanssa; ja tee hänelle, mitä hyväksi näet."'),
(1677465,58,10,19,38,'Niin kuningas sanoi: "Kimham tulkoon minun kanssani, ja minä teen hänelle, mitä sinä hyväksi näet. Ja kaiken, mitä sinä minulta toivot, minä sinulle teen."'),
(1677466,58,10,19,39,'Sitten kaikki kansa meni Jordanin yli, ja myös kuningas itse meni. Ja kuningas suuteli Barsillaita ja hyvästeli hänet. Sitten tämä palasi takaisin kotiinsa.'),
(1677467,58,10,19,40,'Kuningas meni Gilgaliin, ja Kimham meni hänen mukanansa, samoin myös kaikki Juudan kansa. Ja he ja puolet Israelin kansasta veivät kuninkaan yli sinne.'),
(1677468,58,10,19,41,'Ja katso, silloin kaikki muut Israelin miehet tulivat kuninkaan tykö ja sanoivat kuninkaalle: "Miksi ovat meidän veljemme, Juudan miehet, varkain tuoneet Jordanin yli kuninkaan ja hänen perheensä ynnä kaikki Daavidin miehet hänen kanssaan?"'),
(1677469,58,10,19,42,'Mutta kaikki Juudan miehet vastasivat Israelin miehille: "Onhan kuningas meille läheisempi; miksi vihastut siitä? Olemmeko me syöneet kuningasta, tahi olemmeko vieneet hänet itsellemme?"'),
(1677470,58,10,19,43,'(19:44) Israelin miehet vastasivat Juudan miehille ja sanoivat: "Minulla on kymmenen kertaa suurempi osa kuninkaaseen, myös Daavidiin, kuin sinulla. Miksi olet siis ylenkatsonut minua? Ja enkö minä ensin puhunut kuninkaani takaisintuomisesta?" Mutta Juudan miesten sanat olivat vielä ankarammat kuin Israelin miesten sanat.'),
(1677471,58,10,20,1,'Ja siellä oli sattumalta kelvoton mies, nimeltä Seba, Bikrin poika, benjaminilainen. Hän puhalsi pasunaan ja sanoi: "Meillä ei ole mitään osaa Daavidiin eikä perintöosaa Iisain poikaan. Kukin majallensa, Israel!"'),
(1677472,58,10,20,2,'Silloin kaikki Israelin miehet luopuivat Daavidista ja seurasivat Sebaa, Bikrin poikaa; mutta Juudan miehet riippuivat kiinni kuninkaassansa ja seurasivat häntä Jordanilta aina Jerusalemiin.'),
(1677473,58,10,20,3,'Niin Daavid tuli linnaansa Jerusalemiin. Ja kuningas otti ne kymmenen sivuvaimoa, jotka hän oli jättänyt palatsia vartioimaan, ja panetti heidät vartioituun taloon; ja hän elätti heitä, mutta ei mennyt heidän luoksensa. Siellä he olivat eristettyinä kuolinpäiväänsä asti, elävän miehen leskinä.'),
(1677474,58,10,20,4,'Ja kuningas sanoi Amasalle: "Kutsu koolle Juudan miehet kolmen päivän kuluessa ja ole silloin itse paikallasi täällä".'),
(1677475,58,10,20,5,'Niin Amasa meni kutsumaan koolle Juudaa; mutta hän viipyi ohi sen ajan, jonka hän oli määrännyt.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677476,58,10,20,6,'Silloin sanoi Daavid Abisaille: "Nyt Seba, Bikrin poika, tekee meille enemmän pahaa kuin Absalom. Ota sinä herrasi palvelijat ja aja häntä takaa, ettei hän saisi haltuunsa varustettuja kaupunkeja ja repisi meiltä silmiä."'),
(1677477,58,10,20,7,'Niin Jooabin miehet sekä kreetit ja pleetit ja kaikki urhot lähtivät liikkeelle hänen jäljessään; he lähtivät Jerusalemista ajamaan takaa Sebaa, Bikrin poikaa.'),
(1677478,58,10,20,8,'Mutta kun he olivat suuren kiven luona, joka on Gibeonissa, tuli Amasa heitä vastaan. Ja Jooab oli puettu takkiinsa, ja sen päällä oli miekanvyö, kiinnitettynä vyötäisille; miekka oli tupessaan, mutta kun hän lähti liikkeelle, niin se putosi.'),
(1677479,58,10,20,9,'Ja Jooab sanoi Amasalle: "Voitko hyvin, veljeni?" Ja Jooab tarttui oikealla kädellään Amasaa partaan, muka suudellakseen häntä.'),
(1677480,58,10,20,10,'Ja kun Amasa ei varonut miekkaa, joka Jooabilla oli kädessään, pisti tämä häntä sillä vatsaan, niin että hänen sisälmyksensä valuivat maahan; toista pistoa ei tarvittu: hän kuoli. Sitten Jooab ja hänen veljensä Abisai ajoivat takaa Sebaa, Bikrin poikaa.'),
(1677481,58,10,20,11,'Mutta eräs Jooabin palvelijoista jäi seisomaan Amasan ääreen ja huusi: "Jokainen, joka on Jooabille myötämielinen ja joka on Daavidin puolella, seuratkoon Jooabia!"'),
(1677482,58,10,20,12,'Ja Amasa virui verissään keskellä tietä; mutta kun se mies näki, että kaikki väki pysähtyi siihen, vei hän Amasan tieltä syrjään pellolle ja heitti vaatteen hänen päällensä, nähdessään, että kaikki ohikulkijat pysähtyivät.'),
(1677483,58,10,20,13,'Ja kun hänet oli toimitettu pois tieltä, kulkivat kaikki ohi ja seurasivat Jooabia ajaakseen takaa Sebaa, Bikrin poikaa.'),
(1677484,58,10,20,14,'Tämä kulki kaikkien Israelin sukukuntien kautta Aabeliin ja Beet-Maakaan, ja kaikki beeriläiset kokoontuivat ja seurasivat häntä sinne saakka.'),
(1677485,58,10,20,15,'Mutta he tulivat ja piirittivät häntä Aabel-Beet-Maakassa ja loivat kaupunkia vastaan vallin, joka ulottui ulkomuuriin. Ja kaikki Jooabin väki teki hävitystyötä kukistaakseen muurin.'),
(1677486,58,10,20,16,'Silloin huusi viisas vaimo kaupungista: "Kuulkaa! Kuulkaa! Sanokaa Jooabille, että hän tulee tänne lähelle puhutellakseni häntä".'),
(1677487,58,10,20,17,'Ja kun tämä tuli häntä lähelle, sanoi vaimo: "Oletko Jooab?" Hän vastasi: "Olen". Vaimo sanoi hänelle: "Kuule palvelijattaresi sanoja". Hän vastasi: "Minä kuulen".'),
(1677488,58,10,20,18,'Silloin vaimo sanoi: "Muinoin oli tapana sanoa: ''On kysyttävä neuvoa Aabelista'', ja niin tuli valmista.'),
(1677489,58,10,20,19,'Minä olen rauhallisimpia ja uskollisimpia Israelissa, ja sinä koetat ottaa hengen kaupungilta, joka on äiti Israelissa. Miksi sinä tahdot hävittää Herran perintöosan?"'),
(1677490,58,10,20,20,'Jooab vastasi ja sanoi: "Pois se, pois se! En minä tahdo hävittää enkä tuhota.'),
(1677491,58,10,20,21,'Niin ei ole asia, vaan eräs mies Efraimin vuoristosta, nimeltä Seba, Bikrin poika, on nostanut kätensä kuningas Daavidia vastaan; luovuttakaa hänet yksin, niin minä lähden pois kaupungin edustalta." Vaimo vastasi Jooabille: "Katso, hänen päänsä heitetään sinulle muurin yli".'),
(1677492,58,10,20,22,'Sitten vaimo viisaudessaan meni kaiken kansan luo; niin he löivät Sebalta, Bikrin pojalta, pään poikki ja heittivät sen Jooabille. Silloin tämä puhalsi pasunaan, ja he hajaantuivat kaupungin edustalta, kukin majallensa. Mutta Jooab palasi kuninkaan luo Jerusalemiin.'),
(1677493,58,10,20,23,'Jooab oli Israelin koko sotajoukon ylipäällikkönä, ja Benaja, Joojadan poika, oli kreettien ja pleettien päällikkönä.'),
(1677494,58,10,20,24,'Adoram oli verotöiden valvojana, ja Joosafat, Ahiludin poika, oli kanslerina.'),
(1677495,58,10,20,25,'Seja oli kirjurina, ja Saadok ja Ebjatar olivat pappeina.'),
(1677496,58,10,20,26,'Myöskin jaairilainen Iira oli Daavidilla pappina.'),
(1677497,58,10,21,1,'Daavidin aikana oli nälänhätä, jota kesti kolme vuotta peräkkäin; silloin Daavid etsi Herran kasvoja. Herra vastasi: "Saulin tähden, verivelan alaisen suvun tähden, koska hän surmasi gibeonilaiset".'),
(1677498,58,10,21,2,'Niin kuningas kutsui gibeonilaiset ja puhutteli heitä. Mutta gibeonilaiset eivät olleet israelilaisia, vaan amorilaisten jätteitä, ja israelilaiset olivat vannoneet heille valan, mutta Saul oli kiivaillessaan israelilaisten ja Juudan puolesta koettanut hävittää heidät.'),
(1677499,58,10,21,3,'Daavid sanoi gibeonilaisille: "Mitä minun on tehtävä teidän hyväksenne, ja millä minun on teidät sovitettava, että siunaisitte Herran perintöosaa?"'),
(1677500,58,10,21,4,'Gibeonilaiset vastasivat hänelle: "Ei ole meidän ja Saulin sekä hänen sukunsa välillä kysymys hopeasta eikä kullasta, eikä meillä ole valtaa surmata ketään Israelissa". Hän sanoi: "Mitä sitten vaaditte minua tekemään teidän hyväksenne?"'),
(1677501,58,10,21,5,'He vastasivat kuninkaalle: "Sen miehen, joka tahtoi meidät lopettaa ja joka aikoi hävittää meidät, niin ettei meillä olisi missä olla koko Israelin alueella,'),
(1677502,58,10,21,6,'sen miehen jälkeläisistä luovutettakoon meille seitsemän miestä lävistääksemme heidät paaluihin Herralle Saulin, Herran valitun, Gibeassa". Kuningas sanoi: "Minä luovutan".'),
(1677503,58,10,21,7,'Mefibosetin, Saulin pojan Joonatanin pojan, kuningas kuitenkin säästi Herran valan tähden, joka oli heidän välillänsä, Daavidin ja Joonatanin, Saulin pojan, välillä.'),
(1677504,58,10,21,8,'Mutta kuningas otti Rispan, Aijan tyttären, kaksi poikaa, Armonin ja Mefibosetin, jotka tämä oli synnyttänyt Saulille, sekä Meerabin, Saulin tyttären, viisi poikaa, jotka tämä oli synnyttänyt Adrielille, meholalaisen Barsillain pojalle,'),
(1677505,58,10,21,9,'ja luovutti heidät gibeonilaisten käsiin; ja nämä lävistivät heidät paaluihin vuorella Herran edessä, niin että ne seitsemän sortuivat kaikki yhdessä. Näin heidät surmattiin elonleikkuun ensimmäisinä päivinä, ohranleikkuun alussa.'),
(1677506,58,10,21,10,'Silloin Rispa, Aijan tytär, otti säkin ja levitti sen kalliolle, ja se oli hänen vuoteenaan elonleikkuun alusta siihen asti, kunnes sade taivaasta vuoti heidän päällensä, eikä hän sallinut taivaan lintujen päivällä eikä metsän eläinten yöllä tulla heidän päällensä.'),
(1677507,58,10,21,11,'Kun Daavidille kerrottiin, mitä Rispa, Aijan tytär, Saulin sivuvaimo, oli tehnyt,'),
(1677508,58,10,21,12,'meni Daavid ja otti Saulin ja hänen poikansa Joonatanin luut Gileadin Jaabeksen miehiltä, jotka olivat varkain ottaneet ne siltä torilta Beet-Seanista, jolle filistealaiset olivat heidät ripustaneet silloin, kun filistealaiset surmasivat Saulin Gilboassa.'),
(1677509,58,10,21,13,'Ja hän toi sieltä Saulin ja hänen poikansa Joonatanin luut. Myös paaluihin lävistettyjen luut koottiin'),
(1677510,58,10,21,14,'ja haudattiin yhdessä Saulin ja hänen poikansa Joonatanin luiden kanssa Benjaminin maahan Seelaan, Saulin isän, Kiisin, hautaan. Tehtiin kaikki, mitä kuningas oli käskenyt. Niin Jumala leppyi maalle.'),
(1677511,58,10,21,15,'Taas syttyi sota filistealaisten ja Israelin välillä. Ja Daavid lähti palvelijoineen sotimaan filistealaisia vastaan. Ja Daavid väsyi.'),
(1677512,58,10,21,16,'Niin Jisbi-Benob, Raafan jälkeläisiä, jonka keihäs painoi kolmesataa sekeliä vaskea ja joka oli puettu uusiin tamineihin, aikoi surmata Daavidin.'),
(1677513,58,10,21,17,'Mutta Abisai, Serujan poika, tuli hänen avukseen ja löi filistealaisen kuoliaaksi. Silloin Daavidin miehet vannottivat hänellä valan sanoen: "Sinä et saa enää lähteä meidän kanssamme taisteluun, ettet sammuttaisi Israelin lamppua".'),
(1677514,58,10,21,18,'Sen jälkeen oli taas taistelu filistealaisten kanssa Goobissa: silloin huusalainen Sibbekai surmasi Safin, joka myös oli Raafan jälkeläisiä.'),
(1677515,58,10,21,19,'Taas oli taistelu filistealaisia vastaan Goobissa. Elhanan, Jare-Ooregimin poika, beetlehemiläinen, surmasi gatilaisen Goljatin, jonka peitsen varsi oli niinkuin kangastukki.'),
(1677516,58,10,21,20,'Taas oli taistelu Gatissa. Siellä oli kookas mies, jolla oli kuusi sormea kummassakin kädessä ja kuusi varvasta kummassakin jalassa, yhteensä kaksikymmentä neljä; hänkin polveutui Raafasta.'),
(1677517,58,10,21,21,'Ja kun hän häpäisi Israelia, surmasi hänet Joonatan, Daavidin veljen Simean poika.'),
(1677518,58,10,21,22,'Nämä neljä polveutuivat gatilaisesta Raafasta; he kaatuivat Daavidin ja hänen palvelijainsa käden kautta.'),
(1677519,58,10,22,1,'Ja Daavid puhui Herralle tämän laulun sanat sinä päivänä, jona Herra oli pelastanut hänet kaikkien hänen vihollistensa ja Saulin vallasta. Hän sanoi:'),
(1677520,58,10,22,2,'"Herra, minun kallioni, linnani ja pelastajani!'),
(1677521,58,10,22,3,'Jumala, minun vuoreni, jonka turviin minä pakenen, minun kilpeni, autuuteni sarvi, varustukseni ja pakopaikkani, sinä pelastajani, joka pelastat minut väkivallasta!'),
(1677522,58,10,22,4,'''Ylistetty olkoon Herra'' - niin minä huudan, ja vihollisistani minä pelastun.'),
(1677523,58,10,22,5,'Sillä kuoleman aallot piirittivät minut, turmion virrat peljästyttivät minut.'),
(1677524,58,10,22,6,'Tuonelan paulat kietoivat minut, kuoleman ansat yllättivät minut.'),
(1677525,58,10,22,7,'Ahdistuksessani minä rukoilin Herraa, Jumalaani minä rukoilin; ja hän kuuli minun ääneni temppelistänsä, minun huutoni kohosi hänen korviinsa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677526,58,10,22,8,'Silloin maa huojui ja järisi, taivaan perustukset järkkyivät; ne horjuivat, sillä hänen vihansa syttyi.'),
(1677527,58,10,22,9,'Savu suitsusi hänen sieraimistaan, kuluttava tuli hänen suustansa, palavat hiilet hehkuivat hänestä.'),
(1677528,58,10,22,10,'Hän notkisti taivaan ja astui alas, synkkä pilvi jalkojensa alla.'),
(1677529,58,10,22,11,'Hän ajoi kerubin kannattamana ja lensi, hän näkyi tuulen siipien päältä.'),
(1677530,58,10,22,12,'Ja hän pani pimeyden majaksi ympärillensä, synkät vedet, paksut pilvet.'),
(1677531,58,10,22,13,'Hohteesta, joka kävi hänen edellänsä, hehkuivat palavat hiilet.'),
(1677532,58,10,22,14,'Herra jylisi taivaasta, Korkein antoi äänensä kaikua.'),
(1677533,58,10,22,15,'Hän lennätti nuolia ja hajotti heidät, salamoita, ja kauhistutti heidät.'),
(1677534,58,10,22,16,'Silloin meren syvyydet tulivat näkyviin, maanpiirin perustukset paljastuivat Herran nuhtelusta, hänen vihansa hengen puuskauksesta.'),
(1677535,58,10,22,17,'Hän ojensi kätensä korkeudesta ja tarttui minuun, veti minut ylös suurista vesistä.'),
(1677536,58,10,22,18,'Hän pelasti minut voimallisesta vihollisestani, minun vihamiehistäni, sillä he olivat minua väkevämmät.'),
(1677537,58,10,22,19,'He hyökkäsivät minun kimppuuni hätäni päivänä, mutta Herra tuli minun tuekseni.'),
(1677538,58,10,22,20,'Hän toi minut avaraan paikkaan, hän vapautti minut, sillä hän oli mielistynyt minuun.'),
(1677539,58,10,22,21,'Herra tekee minulle minun vanhurskauteni mukaan; minun kätteni puhtauden mukaan hän minulle maksaa.'),
(1677540,58,10,22,22,'Sillä minä olen noudattanut Herran teitä enkä ole luopunut pois Jumalastani, jumalattomuuteen.'),
(1677541,58,10,22,23,'Kaikki hänen oikeutensa ovat minun silmieni edessä, enkä minä poikkea hänen käskyistänsä.'),
(1677542,58,10,22,24,'Minä olen vilpitön häntä kohtaan ja varon itseni pahoista teoista.'),
(1677543,58,10,22,25,'Sentähden Herra palkitsee minulle vanhurskauteni mukaan, sen mukaan kuin olen puhdas hänen silmiensä edessä.'),
(1677544,58,10,22,26,'Hurskasta kohtaan sinä olet hurskas, nuhteetonta sankaria kohtaan nuhteeton;'),
(1677545,58,10,22,27,'puhdasta kohtaan sinä olet puhdas, mutta kieroa kohtaan nurja.'),
(1677546,58,10,22,28,'Ja sinä pelastat nöyrän kansan, mutta sinun silmäsi ovat ylpeitä vastaan, sinä alennat heidät.'),
(1677547,58,10,22,29,'Sillä sinä, Herra, olet minun lamppuni; Herra valaisee minun pimeyteni.'),
(1677548,58,10,22,30,'Sinun avullasi minä hyökkään rosvojoukkoa vastaan, Jumalani avulla minä ryntään ylitse muurin.'),
(1677549,58,10,22,31,'Jumalan tie on nuhteeton, Herran sana tulessa koeteltu. Hän on kaikkien kilpi, jotka häneen turvaavat.'),
(1677550,58,10,22,32,'Sillä kuka muu on Jumala paitsi Herra, ja kuka muu on pelastuksen kallio paitsi meidän Jumalamme?'),
(1677551,58,10,22,33,'se Jumala, joka on minun vahva turvani ja johdattaa nuhteetonta hänen tiellänsä,'),
(1677552,58,10,22,34,'tekee hänen jalkansa nopeiksi niinkuin peurat ja asettaa minut kukkuloilleni,'),
(1677553,58,10,22,35,'joka opettaa minun käteni sotimaan ja käsivarteni vaskijousta jännittämään.'),
(1677554,58,10,22,36,'Sinä annat minulle pelastuksen kilven; ja kun sinä kuulet minun rukoukseni, teet sinä minut suureksi.'),
(1677555,58,10,22,37,'Sinä annat minun askeleilleni avaran tilan, ja minun jalkani eivät horju.'),
(1677556,58,10,22,38,'Minä ajan vihollisiani takaa ja tuhoan heidät enkä palaja, ennenkuin teen heistä lopun.'),
(1677557,58,10,22,39,'Minä lopetan heidät ja murskaan heidät, niin etteivät enää nouse; he sortuvat minun jalkojeni alle.'),
(1677558,58,10,22,40,'Sinä vyötät minut voimalla sotaan, sinä painat vastustajani minun alleni.'),
(1677559,58,10,22,41,'Sinä ajat minun viholliseni pakoon, vihamieheni minä hukutan.'),
(1677560,58,10,22,42,'He katselevat, mutta pelastajaa ei ole, katsovat Herran puoleen, mutta hän ei heille vastaa.'),
(1677561,58,10,22,43,'Minä survon heidät maan tomuksi, kadun loaksi minä heidät poljen ja tallaan.'),
(1677562,58,10,22,44,'Sinä pelastat minut kansani riidoista, sinä varjelet minua, niin että tulen pakanain pääksi; kansat, joita minä en tunne, palvelevat minua.'),
(1677563,58,10,22,45,'Muukalaiset minua mielistelevät; jo korvan kuulemalta he tottelevat minua.'),
(1677564,58,10,22,46,'Muukalaiset masentuvat; he tulevat vyöttäytyneinä varustuksistansa.'),
(1677565,58,10,22,47,'Herra elää! Kiitetty olkoon minun kallioni, ja ylistetty Jumala, minun pelastukseni kallio,'),
(1677566,58,10,22,48,'Jumala, joka hankkii minulle koston ja laskee kansat minun valtani alle;'),
(1677567,58,10,22,49,'sinä, joka vapahdat minut vihollisistani ja korotat minut vastustajaini ylitse ja päästät minut väkivaltaisesta miehestä.'),
(1677568,58,10,22,50,'Sentähden minä ylistän sinua, Herra, kansojen keskuudessa ja veisaan sinun nimesi kiitosta;'),
(1677569,58,10,22,51,'sinun, joka annat kuninkaallesi suuren avun ja osoitat armoa voidellullesi, Daavidille, ja hänen jälkeläisilleen, iankaikkisesti."'),
(1677570,58,10,23,1,'Nämä olivat Daavidin viimeiset sanat: Näin puhuu Daavid, Iisain poika, näin puhuu korkealle korotettu mies, Jaakobin Jumalan voideltu, ihana Israelin ylistysvirsissä:'),
(1677571,58,10,23,2,'"Herran Henki on puhunut minulle, ja hänen sanansa on minun kielelläni;'),
(1677572,58,10,23,3,'Israelin Jumala on sanonut, Israelin kallio on puhunut minulle: ''Joka hallitsee ihmisiä vanhurskaasti, joka hallitsee Jumalan pelossa,'),
(1677573,58,10,23,4,'hän on niinkuin huomenhohde auringon noustessa pilvettömänä aamuna, kun maa kirkkaassa valossa vihannoi sateen jälkeen''.'),
(1677574,58,10,23,5,'Eikö minun sukuni ole näin Jumalan edessä? Sillä hän on tehnyt minun kanssani iankaikkisen liiton, kaikin puolin taatun ja vakaan. Hän antaa versoa minulle kaiken autuuden ja kaiken ilon.'),
(1677575,58,10,23,6,'Mutta kaikki kelvottomat ovat niinkuin poisviskatut orjantappurat, joihin ei käsin tartuta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677576,58,10,23,7,'Ja jos jonkun on koskettava niihin, varustautuu hän raudalla ja keihäänvarrella; sitten ne tulella poltetaan, siinä missä ovat."'),
(1677577,58,10,23,8,'Nämä ovat Daavidin sankarien nimet: Jooseb-Bassebet, tahkemonilainen, vaunusoturien päällikkö, hän, joka heilutti keihästään kahdeksansadan kaatuneen yli yhdellä kertaa.'),
(1677578,58,10,23,9,'Hänen jälkeensä Eleasar, Doodin poika, joka oli erään ahohilaisen poika. Hän oli yksi niistä kolmesta urhosta, jotka olivat Daavidin kanssa silloin, kun he häpäisivät filistealaisia, jotka olivat kokoontuneet sinne sotimaan. Israelin miehet vetäytyivät silloin takaisin,'),
(1677579,58,10,23,10,'mutta hän jäi paikalleen ja surmasi filistealaisia, kunnes hänen kätensä uupui niin, että se kouristui kiinni miekkaan. Ja Herra antoi suuren voiton sinä päivänä; väki kääntyi vain hänen jälkeensä ryöstämään.'),
(1677580,58,10,23,11,'Hänen jälkeensä Samma, Aagen poika, hararilainen. Kerran olivat filistealaiset kokoontuneet yhteen joukkoon, ja siellä oli peltopalsta, kokonaan hernettä kasvamassa. Ja väki pakeni filistealaisia,'),
(1677581,58,10,23,12,'mutta hän asettui keskelle palstaa, sai sen pelastetuksi ja voitti filistealaiset; ja niin Herra antoi suuren voiton.'),
(1677582,58,10,23,13,'Kerran lähti kolme niistä kolmestakymmenestä päälliköstä liikkeelle, ja he tulivat elonleikkuun aikana Daavidin luo Adullamin luolalle. Ja filistealaisten joukko oli leiriytynyt Refaimin tasangolle.'),
(1677583,58,10,23,14,'Mutta Daavid oli silloin vuorilinnassa, ja filistealaisten vartiosto oli Beetlehemissä.'),
(1677584,58,10,23,15,'Ja Daavidin rupesi tekemään mieli vettä, ja hän sanoi: "Jospa joku toisi minulle vettä juodakseni Beetlehemin kaivosta, joka on portin edustalla!"'),
(1677585,58,10,23,16,'Silloin murtautuivat ne kolme urhoa filistealaisten leirin läpi ja ammensivat vettä Beetlehemin kaivosta portin edustalta, kantoivat ja toivat sen Daavidille. Mutta hän ei tahtonut sitä juoda, vaan vuodatti sen juomauhriksi Herralle'),
(1677586,58,10,23,17,'ja sanoi: "Pois se! Herra varjelkoon minut sitä tekemästä. Onhan se niiden miesten veri, jotka menivät sinne oman henkensä uhalla." Eikä hän tahtonut juoda sitä. Tämän tekivät ne kolme urhoa.'),
(1677587,58,10,23,18,'Abisai, Jooabin veli, Serujan poika, oli niiden kolmen päällikkö; hän heilutti keihästään kolmensadan kaatuneen yli. Ja hän oli kuulu niiden kolmen joukossa.'),
(1677588,58,10,23,19,'Hän oli arvossa pidetty niiden kolmen joukossa ja oli heidän päämiehensä, mutta ei hän vetänyt vertoja niille kolmelle.'),
(1677589,58,10,23,20,'Benaja, Joojadan poika, joka oli urhoollisen ja suurista teoistaan kuuluisan miehen poika, oli kotoisin Kabseelista. Hän surmasi ne kaksi mooabilaista sankaria, ja hän laskeutui alas ja tappoi lumituiskun aikana leijonan kaivoon.'),
(1677590,58,10,23,21,'Myöskin surmasi hän egyptiläisen miehen, sen uhkean miehen. Egyptiläisellä oli keihäs kädessä, mutta hän meni häntä vastaan ainoastaan sauva kädessä. Ja hän tempasi keihään egyptiläisen kädestä ja tappoi hänet hänen omalla keihäällään.'),
(1677591,58,10,23,22,'Tällaisia teki Benaja, Joojadan poika. Ja hän oli kuulu niiden kolmen urhon joukossa.'),
(1677592,58,10,23,23,'Hän oli arvossa pidetty niiden kolmenkymmenen joukossa, mutta ei hän vetänyt vertoja niille kolmelle. Ja Daavid asetti hänet henkivartiostonsa päälliköksi.'),
(1677593,58,10,23,24,'Niiden kolmenkymmenen joukossa oli Asael, Jooabin veli; Elhanan, Doodon poika, Beetlehemistä;'),
(1677594,58,10,23,25,'harodilainen Samma; harodilainen Elika;'),
(1677595,58,10,23,26,'pleettiläinen Heles; tekoalainen Iira, Ikkeksen poika;'),
(1677596,58,10,23,27,'anatotilainen Abieser; huusalainen Mebunnai;'),
(1677597,58,10,23,28,'ahohilainen Salmon; netofalainen Maharai;'),
(1677598,58,10,23,29,'netofalainen Heeleb, Baanan poika; Ittai, Riibain poika, benjaminilaisten Gibeasta;'),
(1677599,58,10,23,30,'piratonilainen Benaja; Hiddai Nahale-Gaasista;'),
(1677600,58,10,23,31,'arabalainen Abi-Albon; barhumilainen Asmavet;'),
(1677601,58,10,23,32,'saalbonilainen Eljahba; Bene-Jaasen; Joonatan;'),
(1677602,58,10,23,33,'hararilainen Samma; ararilainen Ahiam, Sararin poika;'),
(1677603,58,10,23,34,'Elifelet, Ahasbain poika, joka oli erään maakatilaisen poika; giilolainen Eliam, Ahitofelin poika;'),
(1677604,58,10,23,35,'karmelilainen Hesrai; arabilainen Paarai;'),
(1677605,58,10,23,36,'Jigal, Naatanin poika, Soobasta; gaadilainen Vaani;'),
(1677606,58,10,23,37,'ammonilainen Selek; beerotilainen Naharai, Jooabin, Serujan pojan, aseenkantaja;'),
(1677607,58,10,23,38,'jeteriläinen Iira; jeteriläinen Gaareb;'),
(1677608,58,10,23,39,'heettiläinen Uuria. Kaikkiaan kolmekymmentä seitsemän.'),
(1677609,58,10,24,1,'Mutta Herran viha syttyi taas Israelia kohtaan, niin että hän yllytti Daavidin heitä vastaan, sanoen: "Mene ja laske Israel ja Juuda".'),
(1677610,58,10,24,2,'Niin kuningas sanoi Jooabille, sotajoukon päällikölle, joka oli hänen luonaan: "Kiertele kaikki Israelin sukukunnat Daanista Beersebaan asti, ja pitäkää kansan katselmus, että minä saisin tietää kansan lukumäärän".'),
(1677611,58,10,24,3,'Jooab vastasi kuninkaalle: "Herra, sinun Jumalasi, lisätköön kansan, olkoon se kuinka suuri tahansa, satakertaiseksi, ja saakoon herrani, kuningas, nähdä sen omin silmin. Mutta miksi herrani, kuningas, haluaa sellaista?"'),
(1677612,58,10,24,4,'Kuitenkin kuninkaan sana velvoitti Jooabia ja sotapäällikköjä; niin Jooab ja sotapäälliköt lähtivät kuninkaan luota pitämään Israelin kansan katselmusta.'),
(1677613,58,10,24,5,'Ja he menivät Jordanin yli ja leiriytyivät Aroeriin, oikealle puolelle jokilaakson keskikohdalla olevaa kaupunkia, Gaadiin ja Jaeseriin päin.'),
(1677614,58,10,24,6,'Sitten he tulivat Gileadiin ja Tahtim-Hodsin maahan; sitten he tulivat Daan-Jaaniin ja sieltä ympäri Siidoniin.'),
(1677615,58,10,24,7,'Sitten he tulivat Tyyron linnoitukseen ja kaikkiin hivviläisten ja kanaanilaisten kaupunkeihin ja menivät sieltä Juudan Etelämaahan Beersebaan asti.'),
(1677616,58,10,24,8,'Ja kun he olivat kierrelleet koko maan, tulivat he yhdeksän kuukauden ja kahdenkymmenen päivän kuluttua takaisin Jerusalemiin.'),
(1677617,58,10,24,9,'Ja Jooab ilmoitti kuninkaalle kansan lasketun lukumäärän: Israelissa oli kahdeksansataa tuhatta sotakuntoista miekkamiestä, ja Juudassa oli viisisataa tuhatta miestä.'),
(1677618,58,10,24,10,'Mutta Daavidin omatunto soimasi häntä, sittenkuin hän oli laskenut kansan, ja Daavid sanoi Herralle: "Minä olen tehnyt suuren synnin tehdessäni tämän; mutta anna nyt, Herra, anteeksi palvelijasi rikos, sillä minä olen menetellyt ylen tyhmästi".'),
(1677619,58,10,24,11,'Ja kun Daavid aamulla nousi, oli profeetta Gaadille, Daavidin näkijälle, tullut tämä Herran sana:'),
(1677620,58,10,24,12,'"Mene ja puhu Daavidille: Näin sanoo Herra: Kolme ehtoa minä asetan sinun eteesi; valitse yksi niistä, niin minä teen sen sinulle".'),
(1677621,58,10,24,13,'Niin Gaad meni Daavidin tykö, ilmoitti ja sanoi hänelle: "Tuleeko nälkä seitsemäksi vuodeksi sinun maahasi, vai pakenetko sinä kolme kuukautta vihollisiasi, jotka ajavat sinua takaa, vai tuleeko rutto sinun maahasi kolmeksi päiväksi? Mieti nyt ja katso, mitä minä vastaan hänelle, joka minut lähetti."'),
(1677622,58,10,24,14,'Daavid vastasi Gaadille: "Minä olen suuressa hädässä. Me tahdomme langeta Herran käsiin, sillä hänen laupeutensa on suuri; ihmisten käsiin minä en tahdo langeta."'),
(1677623,58,10,24,15,'Niin Herra antoi ruton tulla Israeliin, aamusta alkaen määrättyyn aikaan asti; ja kansaa kuoli Daanista Beersebaan asti seitsemänkymmentä tuhatta miestä.'),
(1677624,58,10,24,16,'Mutta kun enkeli ojensi kätensä Jerusalemia kohti tuhotaksensa sen, katui Herra sitä pahaa ja sanoi enkelille, joka kansaa tuhosi: "Jo riittää; laske kätesi alas". Ja Herran enkeli oli silloin jebusilaisen Araunan puimatantereen luona.'),
(1677625,58,10,24,17,'Mutta nähdessään enkelin surmaavan kansaa sanoi Daavid Herralle: "Katso, minä olen tehnyt syntiä, minä olen tehnyt väärin; mutta nämä minun lampaani, mitä he ovat tehneet? Sattukoon sinun kätesi minuun ja minun isäni perheeseen."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677626,58,10,24,18,'Ja Gaad tuli Daavidin tykö samana päivänä ja sanoi hänelle: "Mene ja pystytä Herralle alttari jebusilaisen Araunan puimatantereelle".'),
(1677627,58,10,24,19,'Niin Daavid meni, Gaadin sanan ja Herran käskyn mukaan.'),
(1677628,58,10,24,20,'Mutta kun Arauna katsahti ulos ja näki kuninkaan palvelijoineen tulevan luoksensa, meni hän ulos ja kumartui kasvoillensa maahan kuninkaan eteen.'),
(1677629,58,10,24,21,'Ja Arauna sanoi: "Miksi herrani, kuningas, tulee palvelijansa luo?" Daavid vastasi: "Ostamaan sinulta puimatantereen, rakentaakseni Herralle alttarin, että vitsaus taukoaisi kansasta".'),
(1677630,58,10,24,22,'Arauna sanoi Daavidille: "Herrani, kuningas, ottakoon ja uhratkoon, mitä hyväksi näkee. Katso, tässä on härät polttouhriksi ja puimaäkeet sekä härkien valjaat haloiksi.'),
(1677631,58,10,24,23,'Tämän kaiken, kuningas, Arauna antaa kuninkaalle." Ja Arauna sanoi kuninkaalle: "Olkoon Herra, sinun Jumalasi, sinulle suosiollinen".'),
(1677632,58,10,24,24,'Mutta kuningas sanoi Araunalle: "Ei niin, vaan minä ostan ne sinulta täydestä hinnasta, sillä minä en uhraa Herralleni, Jumalalleni, ilmaiseksi saatuja polttouhreja". Niin Daavid osti puimatantereen ja härät viidelläkymmenellä hopeasekelillä.'),
(1677633,58,11,1,1,'Kun kuningas Daavid oli käynyt vanhaksi ja iäkkääksi, ei hän enää voinut pysyä lämpimänä, vaikka häntä peitettiin peitteillä.'),
(1677634,58,11,1,2,'Silloin hänen palvelijansa sanoivat hänelle: "Etsittäköön herralleni, kuninkaalle, tyttö, neitsyt, palvelemaan kuningasta ja olemaan hänen hoitajattarenaan. Jos hän makaa sinun sylissäsi, niin herrani, kuningas, pysyy lämpimänä."'),
(1677635,58,11,1,3,'Ja he etsivät koko Israelin alueelta kaunista tyttöä ja löysivät suunemilaisen Abisagin ja veivät hänet kuninkaan tykö.'),
(1677636,58,11,1,4,'Hän oli hyvin kaunis tyttö ja tuli kuninkaan hoitajattareksi ja palveli häntä. Mutta kuningas ei yhtynyt häneen.'),
(1677637,58,11,1,5,'Mutta Adonia, Haggitin poika, korotti itsensä ja sanoi: "Minä tahdon tulla kuninkaaksi". Ja hän hankki itselleen sotavaunuja ja ratsumiehiä ja viisikymmentä miestä, jotka juoksivat hänen edellään.'),
(1677638,58,11,1,6,'Hänen isänsä ei koskaan elämässään ollut pahoittanut hänen mieltään sanomalla: "Kuinka sinä noin teet?" Hän oli myöskin hyvin kaunis mies; ja äiti oli synnyttänyt hänet Absalomin jälkeen.'),
(1677639,58,11,1,7,'Hän neuvotteli Jooabin, Serujan pojan, ja pappi Ebjatarin kanssa; ja he kannattivat Adonian puoluetta.'),
(1677640,58,11,1,8,'Mutta pappi Saadok ja Benaja, Joojadan poika, sekä profeetta Naatan, Siimei, Rei ja Daavidin urhot eivät olleet Adonian puolella.'),
(1677641,58,11,1,9,'Ja Adonia teurasti lampaita, raavaita ja juottovasikoita Soohelet-kiven luona, joka on Roogelin lähteen ääressä. Ja hän kutsui kaikki veljensä, kuninkaan pojat, ja kaikki Juudan miehet, kuninkaan palvelijat;'),
(1677642,58,11,1,10,'mutta profeetta Naatanin, Benajan, urhot ja veljensä Salomon hän jätti kutsumatta.'),
(1677643,58,11,1,11,'Silloin Naatan sanoi Batseballe, Salomon äidille, näin: "Etkö ole kuullut, että Adonia, Haggitin poika, on tullut kuninkaaksi, herramme Daavidin siitä mitään tietämättä?'),
(1677644,58,11,1,12,'Niin tule nyt, minä annan sinulle neuvon, että pelastat oman henkesi ja poikasi Salomon hengen.'),
(1677645,58,11,1,13,'Mene kuningas Daavidin tykö ja sano hänelle: Herrani, kuningas, etkö sinä itse ole vannonut palvelijattarellesi ja sanonut: Sinun poikasi Salomo on tuleva kuninkaaksi minun jälkeeni; hän on istuva minun valtaistuimellani? Miksi siis Adonia on tullut kuninkaaksi?'),
(1677646,58,11,1,14,'Ja katso, sinun vielä puhutellessasi kuningasta siellä, tulen minä sinun jälkeesi sisään ja vahvistan sinun sanasi."'),
(1677647,58,11,1,15,'Niin Batseba meni kuninkaan tykö makuuhuoneeseen. Kuningas oli hyvin vanha; ja suunemilainen Abisag palveli kuningasta.'),
(1677648,58,11,1,16,'Ja Batseba kumarsi ja osoitti kuninkaalle kunnioitusta. Kuningas sanoi: "Mikä sinun on?"'),
(1677649,58,11,1,17,'Hän vastasi hänelle: "Herrani, sinä olet itse vannonut palvelijattarellesi Herran, Jumalasi, kautta: ''Sinun poikasi Salomo on tuleva kuninkaaksi minun jälkeeni; hän on istuva minun valtaistuimellani''.'),
(1677650,58,11,1,18,'Mutta katso, nyt on Adonia tullut kuninkaaksi, ja sinä, herrani, kuningas, et tiedä siitä mitään.'),
(1677651,58,11,1,19,'Hän on teurastanut paljon härkiä, juottovasikoita ja lampaita ja kutsunut kaikki kuninkaan pojat, pappi Ebjatarin ja sotapäällikkö Jooabin; mutta palvelijasi Salomon hän on jättänyt kutsumatta.'),
(1677652,58,11,1,20,'Sinua kohti, herrani, kuningas, ovat nyt koko Israelin silmät tähdätyt, että ilmoittaisit heille, kuka on istuva herrani, kuninkaan, valtaistuimella hänen jälkeensä.'),
(1677653,58,11,1,21,'Muuten käy niin, että kun herrani, kuningas, on mennyt lepoon isiensä tykö, minua ja minun poikaani Salomoa pidetään rikollisina."'),
(1677654,58,11,1,22,'Ja katso, hänen vielä puhutellessaan kuningasta tuli profeetta Naatan.'),
(1677655,58,11,1,23,'Ja kuninkaalle ilmoitettiin: "Katso, profeetta Naatan on täällä". Ja tämä tuli kuninkaan eteen ja kumartui kasvoillensa maahan kuninkaan eteen.'),
(1677656,58,11,1,24,'Ja Naatan sanoi: "Herrani, kuningas, sinäkö olet sanonut: ''Adonia on tuleva kuninkaaksi minun jälkeeni; hän on istuva minun valtaistuimellani''?'),
(1677657,58,11,1,25,'Sillä hän on tänä päivänä mennyt ja teurastanut paljon härkiä, juottovasikoita ja lampaita ja kutsunut kaikki kuninkaan pojat, sotapäälliköt ja pappi Ebjatarin; ja katso, he syövät ja juovat hänen edessään, ja he huutavat: ''Eläköön kuningas Adonia!'''),
(1677658,58,11,1,26,'Mutta minut, sinun palvelijasi, pappi Saadokin, Benajan, Joojadan pojan, ja sinun palvelijasi Salomon hän on jättänyt kutsumatta.'),
(1677659,58,11,1,27,'Onko tämä lähtenyt herrastani, kuninkaasta, sinun antamatta palvelijasi tietää, kuka on istuva herrani, kuninkaan, valtaistuimella hänen jälkeensä?"'),
(1677660,58,11,1,28,'Kuningas Daavid vastasi ja sanoi: "Kutsukaa minun luokseni Batseba". Kun hän tuli kuninkaan eteen ja seisoi kuninkaan edessä,'),
(1677661,58,11,1,29,'vannoi kuningas ja sanoi: "Niin totta kuin Herra elää, joka on pelastanut minut kaikesta hädästä:'),
(1677662,58,11,1,30,'niinkuin minä vannoin sinulle Herran, Israelin Jumalan, kautta ja sanoin: ''Sinun poikasi Salomo on tuleva kuninkaaksi minun jälkeeni, hän on istuva minun valtaistuimellani minun sijassani'', niin minä tänä päivänä teen".'),
(1677663,58,11,1,31,'Silloin Batseba kumartui kasvoillensa maahan ja osoitti kuninkaalle kunnioitusta ja sanoi: "Herrani, kuningas Daavid, eläköön iankaikkisesti!"'),
(1677664,58,11,1,32,'Ja kuningas Daavid sanoi: "Kutsukaa minun luokseni pappi Saadok, profeetta Naatan ja Benaja, Joojadan poika". Niin he tulivat kuninkaan eteen.'),
(1677665,58,11,1,33,'Ja kuningas sanoi heille: "Ottakaa mukaanne herranne palvelijat ja pankaa poikani Salomo minun oman muulini selkään ja viekää hänet alas Giihonille.'),
(1677666,58,11,1,34,'Siellä pappi Saadok ja profeetta Naatan voidelkoot hänet Israelin kuninkaaksi. Ja puhaltakaa pasunaan ja huutakaa: ''Eläköön kuningas Salomo!'''),
(1677667,58,11,1,35,'Seuratkaa sitten häntä tänne, että hän tulisi ja istuisi minun valtaistuimelleni ja olisi kuninkaana minun sijassani. Sillä hänet minä olen määrännyt Israelin ja Juudan ruhtinaaksi."'),
(1677668,58,11,1,36,'Silloin Benaja, Joojadan poika, vastasi kuninkaalle ja sanoi: "Amen! Niin sanokoon Herra, minun herrani, kuninkaan, Jumala.'),
(1677669,58,11,1,37,'Niinkuin Herra on ollut minun herrani, kuninkaan, kanssa, niin olkoon hän Salomon kanssa ja tehköön hänen valtaistuimensa vielä suuremmaksi kuin on herrani, kuningas Daavidin, valtaistuin."'),
(1677670,58,11,1,38,'Niin pappi Saadok, profeetta Naatan ja Benaja, Joojadan poika, sekä kreetit ja pleetit menivät sinne. He panivat Salomon kuningas Daavidin muulin selkään ja saattoivat hänet Giihonille.'),
(1677671,58,11,1,39,'Ja pappi Saadok otti öljysarven majasta ja voiteli Salomon. Ja he puhalsivat pasunaan, ja kaikki kansa huusi: "Eläköön kuningas Salomo!"'),
(1677672,58,11,1,40,'Ja kaikki kansa seurasi häntä, ja kansa soitti huiluilla ja ratkesi niin suureen riemuun, että maa oli haljeta heidän huudostansa.'),
(1677673,58,11,1,41,'Mutta Adonia ja kaikki kutsuvieraat, jotka olivat hänen kanssaan, kuulivat sen, juuri kun olivat lopettaneet syöntinsä. Ja kun Jooab kuuli pasunan äänen, sanoi hän: "Mitä tuo huuto ja pauhu kaupungissa tietää?"'),
(1677674,58,11,1,42,'Hänen vielä puhuessaan tuli Joonatan, pappi Ebjatarin poika; ja Adonia sanoi: "Tule tänne, sillä sinä olet kunnon mies ja tuot hyviä sanomia".'),
(1677675,58,11,1,43,'Joonatan vastasi ja sanoi Adonialle: "Päinvastoin! Herramme, kuningas Daavid, on tehnyt Salomon kuninkaaksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677676,58,11,1,44,'Kuningas lähetti hänen kanssaan pappi Saadokin, profeetta Naatanin ja Benajan, Joojadan pojan, sekä kreetit ja pleetit, ja he panivat hänet kuninkaan muulin selkään.'),
(1677677,58,11,1,45,'Ja pappi Saadok ja profeetta Naatan voitelivat hänet Giihonilla kuninkaaksi, ja he tulivat sieltä riemuiten, ja koko kaupunki joutui liikkeelle. Sitä oli se huuto, jonka te kuulitte.'),
(1677678,58,11,1,46,'Onpa Salomo jo istunut kuninkaan valtaistuimellekin,'),
(1677679,58,11,1,47,'ja kuninkaan palvelijat ovat tulleet onnittelemaan meidän herraamme, kuningas Daavidia, ja sanoneet: ''Antakoon sinun Jumalasi Salomon nimen tulla vielä mainehikkaammaksi kuin sinun nimesi ja tehköön hänen valtaistuimensa vielä suuremmaksi kuin on sinun valtaistuimesi''. Ja kuningas on rukoillut vuoteessansa.'),
(1677680,58,11,1,48,'Ja vielä on kuningas puhunut näin: ''Kiitetty olkoon Herra, Israelin Jumala, joka tänä päivänä on asettanut jälkeläisen istumaan minun valtaistuimellani, niin että minä olen sen omin silmin nähnyt''."'),
(1677681,58,11,1,49,'Silloin kaikki Adonian kutsuvieraat joutuivat kauhun valtaan ja nousivat ja menivät kukin tiehensä.'),
(1677682,58,11,1,50,'Mutta Adonia pelkäsi Salomoa, nousi, meni ja tarttui alttarin sarviin.'),
(1677683,58,11,1,51,'Ja Salomolle ilmoitettiin: "Katso, Adonia on peläten kuningas Salomoa tarttunut alttarin sarviin ja sanonut: ''Kuningas Salomo vannokoon minulle tänä päivänä, ettei hän miekalla surmaa palvelijaansa''".'),
(1677684,58,11,1,52,'Silloin Salomo sanoi: "Jos hän osoittautuu kunnon mieheksi, ei hiuskarvakaan hänen päästään ole putoava maahan; mutta jos hänessä huomataan jotakin pahaa, on hänen kuoltava".'),
(1677685,58,11,1,53,'Ja kuningas Salomo lähetti tuomaan hänet pois alttarilta; niin hän tuli ja kumarsi kuningas Salomoa. Ja Salomo sanoi hänelle: "Mene kotiisi".'),
(1677686,58,11,2,1,'Kun lähestyi aika, jolloin Daavidin oli kuoltava, käski hän poikaansa Salomoa sanoen:'),
(1677687,58,11,2,2,'"Minä menen kaiken maailman tietä; ole luja ja ole mies.'),
(1677688,58,11,2,3,'Ja noudata Herran, Jumalasi, määräyksiä, niin että vaellat hänen teitänsä ja noudatat hänen säädöksiänsä, käskyjänsä, oikeuksiansa ja todistuksiansa, niinkuin on kirjoitettuna Mooseksen laissa, että menestyisit kaikessa, mitä teet, ja kaikkialla, minne käännyt;'),
(1677689,58,11,2,4,'että Herra täyttäisi tämän sanansa, jonka hän minusta puhui: ''Jos sinun poikasi pitävät vaarin teistänsä, niin että vaeltavat minun edessäni uskollisesti, kaikesta sydämestänsä ja kaikesta sielustansa, niin on mies sinun suvustasi aina oleva Israelin valtaistuimella''.'),
(1677690,58,11,2,5,'Sinä tiedät myöskin, mitä Jooab, Serujan poika, on tehnyt minulle - tiedät, mitä hän teki kahdelle Israelin sotapäällikölle, Abnerille, Neerin pojalle, ja Amasalle, Jeterin pojalle: kuinka hän tappoi heidät, vuodattaen sotaverta rauhan aikana ja tahraten sotaverellä vyönsä, joka hänellä oli vyötäisillään, ja kenkänsä, jotka hänellä oli jalassaan.'),
(1677691,58,11,2,6,'Niin tee nyt viisautesi mukaan äläkä anna hänen harmaiden hapsiensa rauhassa mennä alas tuonelaan.'),
(1677692,58,11,2,7,'Mutta gileadilaisen Barsillain pojille osoita laupeutta, niin että he pääsevät niiden joukkoon, jotka syövät sinun pöydästäsi, sillä hekin tulivat minun avukseni, kun minä pakenin sinun veljeäsi Absalomia.'),
(1677693,58,11,2,8,'Ja katso, vielä on sinun luonasi Siimei, Geeran poika, benjaminilainen Bahurimista, joka hirveillä kirouksilla kiroili minua, kun minä menin Mahanaimiin. Kun hän tuli minua vastaan alas Jordanille, vannoin minä hänelle Herran kautta ja sanoin: ''Minä en surmaa sinua miekalla''.'),
(1677694,58,11,2,9,'Mutta älä sinä jätä häntä rankaisematta, sillä sinä olet viisas mies ja tiedät, mitä sinun on hänelle tehtävä, saattaaksesi hänen harmaat hapsensa verisinä alas tuonelaan."'),
(1677695,58,11,2,10,'Sitten Daavid meni lepoon isiensä tykö, ja hänet haudattiin Daavidin kaupunkiin.'),
(1677696,58,11,2,11,'Ja aika, jonka Daavid hallitsi Israelia, oli neljäkymmentä vuotta: Hebronissa hän hallitsi seitsemän vuotta, ja Jerusalemissa hän hallitsi kolmekymmentä kolme vuotta.'),
(1677697,58,11,2,12,'Ja Salomo istui isänsä Daavidin valtaistuimelle, ja hänen kuninkuutensa tuli hyvin vahvaksi.'),
(1677698,58,11,2,13,'Mutta Adonia, Haggitin poika, tuli Batseban, Salomon äidin, luo. Tämä sanoi: "Rauhaako sinun tulosi tietää?" Hän vastasi: "Rauhaa".'),
(1677699,58,11,2,14,'Sitten hän sanoi: "Minulla on asiaa sinulle". Batseba sanoi: "Puhu".'),
(1677700,58,11,2,15,'Silloin hän sanoi: "Sinä tiedät, että kuninkuus oli minun, ja että koko Israel oli kääntänyt katseensa minuun, että minusta tulisi kuningas. Mutta sitten kuninkuus meni minulta pois ja joutui minun veljelleni, sillä Herralta se hänelle tuli.'),
(1677701,58,11,2,16,'Yhtä minä nyt sinulta pyydän; älä sitä minulta kiellä." Hän sanoi hänelle: "Puhu".'),
(1677702,58,11,2,17,'Hän sanoi: "Puhu kuningas Salomolle - sillä sinulta hän ei sitä kiellä - että hän antaisi minulle suunemilaisen Abisagin vaimoksi".'),
(1677703,58,11,2,18,'Batseba vastasi: "Hyvä. Minä puhun kuninkaalle sinun puolestasi."'),
(1677704,58,11,2,19,'Silloin Batseba meni kuningas Salomon tykö puhumaan hänelle Adonian puolesta. Niin kuningas nousi ja meni häntä vastaan ja kumarsi häntä ja istui valtaistuimelleen. Ja myös kuninkaan äidille asetettiin istuin, ja hän istui hänen oikealle puolellensa.'),
(1677705,58,11,2,20,'Sitten hän sanoi: "Minulla on sinulle pieni pyyntö, älä sitä minulta kiellä". Kuningas sanoi hänelle: "Pyydä, äiti, minä en sinulta kiellä".'),
(1677706,58,11,2,21,'Silloin hän sanoi: "Annettakoon suunemilainen Abisag sinun veljellesi Adonialle vaimoksi".'),
(1677707,58,11,2,22,'Mutta kuningas Salomo vastasi ja sanoi äidillensä: "Miksi pyydät vain suunemilaista Abisagia Adonialle? Pyydä myös kuninkuutta hänelle - hänhän on minun vanhin veljeni - hänelle ja pappi Ebjatarille ja Jooabille, Serujan pojalle."'),
(1677708,58,11,2,23,'Ja kuningas Salomo vannoi Herran kautta, sanoen: "Jumala rangaiskoon minua nyt ja vasta, jollei Adonia saa hengellään maksaa sitä, että on puhunut näin.'),
(1677709,58,11,2,24,'Ja nyt, niin totta kuin Herra elää, joka on minut vahvistanut ja on asettanut minut isäni Daavidin valtaistuimelle ja joka lupauksensa mukaan on perustanut minun sukuni: Adonia on tänä päivänä kuolemalla rangaistava."'),
(1677710,58,11,2,25,'Ja kuningas Salomo lähetti Benajan, Joojadan pojan, lyömään hänet kuoliaaksi; ja hän kuoli.'),
(1677711,58,11,2,26,'Ja pappi Ebjatarille kuningas sanoi: "Mene maatilallesi Anatotiin, sillä sinä olet kuoleman oma. En minä sinua nyt surmaa, koska sinä olet kantanut Herran Jumalan arkkia minun isäni Daavidin edessä ja koska olet kärsinyt kaikkea, mitä isäni on kärsinyt."'),
(1677712,58,11,2,27,'Niin Salomo karkoitti Ebjatarin olemasta Herran pappina ja täytti sen sanan, minkä Herra oli Siilossa puhunut Eelin suvusta.'),
(1677713,58,11,2,28,'Ja kun sanoma tästä tuli Jooabille - sillä Jooab oli liittynyt Adoniaan, vaikka hän ei ollut liittynyt Absalomiin - pakeni Jooab Herran majaan ja tarttui alttarin sarviin.'),
(1677714,58,11,2,29,'Mutta kun kuningas Salomolle ilmoitettiin: "Jooab on paennut Herran majaan ja on alttarin ääressä", lähetti Salomo Benajan, Joojadan pojan, sanoen: "Mene ja lyö hänet kuoliaaksi".'),
(1677715,58,11,2,30,'Benaja meni Herran majaan ja sanoi hänelle: "Näin käskee kuningas: ''Tule ulos''". Mutta hän vastasi: "En, tässä minä kuolen". Silloin Benaja palasi kertomaan sitä kuninkaalle ja sanoi: "Näin Jooab puhui, ja näin hän vastasi minulle".'),
(1677716,58,11,2,31,'Kuningas sanoi hänelle: "Tee, niinkuin hän on puhunut, lyö hänet kuoliaaksi ja hautaa hänet, että poistaisit minusta ja minun isäni perheestä sen viattoman veren, jonka Jooab on vuodattanut.'),
(1677717,58,11,2,32,'Ja Herra antakoon hänen verensä tulla hänen oman päänsä päälle, koska hän löi kuoliaaksi kaksi miestä, jotka olivat häntä hurskaammat ja paremmat, ja tappoi heidät miekalla, minun isäni Daavidin siitä mitään tietämättä: Abnerin, Neerin pojan, Israelin sotapäällikön, ja Amasan, Jeterin pojan, Juudan sotapäällikön.'),
(1677718,58,11,2,33,'Heidän verensä tulkoon Jooabin pään päälle ja hänen jälkeläistensä pään päälle, iankaikkisesti. Mutta Daavidilla ja hänen jälkeläisillään, hänen suvullansa ja hänen valtaistuimellansa olkoon rauha Herralta iankaikkisesti."'),
(1677719,58,11,2,34,'Niin Benaja, Joojadan poika, meni ja löi hänet kuoliaaksi; ja hänet haudattiin omaan taloonsa erämaahan.'),
(1677720,58,11,2,35,'Ja kuningas asetti Benajan, Joojadan pojan, hänen sijaansa sotaväen päälliköksi; ja pappi Saadokin kuningas asetti Ebjatarin sijalle.'),
(1677721,58,11,2,36,'Sen jälkeen kuningas lähetti kutsumaan Siimein ja sanoi hänelle: "Rakenna itsellesi talo Jerusalemiin ja asu siellä, menemättä sieltä sinne tai tänne.'),
(1677722,58,11,2,37,'Sillä jona päivänä sinä lähdet sieltä ja menet Kidronin laakson poikki, sinä päivänä on sinun, tiedä se, kuolemalla kuoltava; sinun veresi on tuleva oman pääsi päälle."'),
(1677723,58,11,2,38,'Siimei sanoi kuninkaalle: "Hyvä on; niinkuin herrani, kuningas, on puhunut, niin on sinun palvelijasi tekevä". Ja Siimei asui Jerusalemissa kauan aikaa.'),
(1677724,58,11,2,39,'Mutta kolmen vuoden kuluttua tapahtui, että Siimeiltä karkasi kaksi palvelijaa Aakiin, Maakan pojan, Gatin kuninkaan, luo. Ja Siimeille ilmoitettiin: "Katso, sinun palvelijasi ovat Gatissa".'),
(1677725,58,11,2,40,'Niin Siimei nousi ja satuloi aasinsa ja lähti Aakiin luo Gatiin etsimään palvelijoitaan; ja Siimei meni ja toi palvelijansa Gatista.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677726,58,11,2,41,'Ja kun Salomolle ilmoitettiin, että Siimei oli mennyt Jerusalemista Gatiin ja palannut takaisin,'),
(1677727,58,11,2,42,'lähetti kuningas kutsumaan Siimein ja sanoi hänelle: "Enkö minä ole vannottanut sinua Herran kautta ja varoittanut sinua sanoen: ''Jona päivänä sinä lähdet ja menet sinne tai tänne, sinä päivänä on sinun, tiedä se, kuolemalla kuoltava''? Ja sinä sanoit minulle: ''Hyvä on; minä olen kuullut''.'),
(1677728,58,11,2,43,'Miksi et ole pitänyt Herran valaa etkä sitä käskyä, jonka minä sinulle annoin?"'),
(1677729,58,11,2,44,'Ja kuningas sanoi vielä Siimeille: "Sinä tiedät, tunnossasi tiedät, kaiken pahan, minkä olet tehnyt minun isälleni Daavidille; Herra kääntää tekemäsi pahan omaan päähäsi.'),
(1677730,58,11,2,45,'Mutta kuningas Salomo on oleva siunattu, ja Daavidin valtaistuin on oleva iäti vahva Herran edessä."'),
(1677731,58,11,2,46,'Ja kuningas käski Benajaa, Joojadan poikaa; niin tämä meni ja löi hänet kuoliaaksi, ja hän kuoli. Niin kuninkuus vahvistui Salomon käsissä.'),
(1677732,58,11,3,1,'Ja Salomo tuli faraon, Egyptin kuninkaan, vävyksi: hän otti faraon tyttären vaimokseen. Ja hän vei hänet Daavidin kaupunkiin, kunnes oli saanut rakennetuksi oman linnansa, Herran temppelin ja Jerusalemin ympärysmuurin.'),
(1677733,58,11,3,2,'Mutta kansa uhrasi uhrikukkuloilla, koska niihin aikoihin ei vielä oltu rakennettu temppeliä Herran nimelle.'),
(1677734,58,11,3,3,'Ja Salomo rakasti Herraa ja vaelsi isänsä Daavidin käskyjen mukaan; kuitenkin hän uhrasi ja suitsutti uhrikukkuloilla.'),
(1677735,58,11,3,4,'Niin kuningas meni Gibeoniin, uhraamaan siellä, sillä se oli suurin uhrikukkula. Tuhat polttouhria Salomo uhrasi sillä alttarilla.'),
(1677736,58,11,3,5,'Gibeonissa Herra ilmestyi Salomolle yöllä unessa, ja Jumala sanoi: "Ano, mitä tahdot, että minä sinulle antaisin".'),
(1677737,58,11,3,6,'Salomo vastasi: "Sinä olet tehnyt suuren laupeuden palvelijallesi, minun isälleni Daavidille, koska hän vaelsi sinun edessäsi totuudessa ja vanhurskaudessa sekä vilpittömällä sydämellä sinua kohtaan. Ja sinä olet säilyttänyt hänelle tämän suuren laupeuden ja antanut hänelle pojan, joka istuu hänen valtaistuimellansa, niinkuin on laita tänä päivänä.'),
(1677738,58,11,3,7,'Ja nyt, Herra, minun Jumalani, sinä olet tehnyt palvelijasi kuninkaaksi minun isäni Daavidin sijaan; mutta minä olen kuin pieni poikanen: en osaa lähteä enkä tulla.'),
(1677739,58,11,3,8,'Ja palvelijasi on keskellä sinun kansaasi, jonka olet valinnut, niin monilukuista kansaa, että sitä ei voi laskea eikä lukea sen paljouden tähden.'),
(1677740,58,11,3,9,'Anna sentähden palvelijallesi kuuliainen sydän tuomitakseni sinun kansaasi ja erottaakseni hyvän pahasta; sillä kuka voi muuten tätä sinun suurta kansaasi tuomita?"'),
(1677741,58,11,3,10,'Herralle oli otollista, että Salomo tätä anoi.'),
(1677742,58,11,3,11,'Ja Jumala sanoi hänelle: "Koska sinä anoit tätä etkä anonut itsellesi pitkää ikää, et rikkautta etkä vihamiestesi henkeä, vaan anoit itsellesi ymmärrystä kuullaksesi, mikä oikein on,'),
(1677743,58,11,3,12,'niin katso, minä teen, niinkuin sanot: katso, minä annan sinulle viisaan ja ymmärtäväisen sydämen, niin ettei sinun vertaistasi ole ollut ennen sinua eikä tule sinun jälkeesi.'),
(1677744,58,11,3,13,'Ja lisäksi minä annan sinulle, mitä et anonutkaan: sekä rikkautta että kunniaa, niin ettei koko elinaikanasi ole kuningasten joukossa oleva sinun vertaistasi.'),
(1677745,58,11,3,14,'Ja jos sinä vaellat minun teitäni, noudattaen minun säädöksiäni ja käskyjäni, niinkuin sinun isäsi Daavid vaelsi, niin minä suon sinulle pitkän iän."'),
(1677746,58,11,3,15,'Siihen Salomo heräsi; ja katso, se oli unta. Ja kun hän tuli Jerusalemiin, astui hän Herran liitonarkin eteen, uhrasi polttouhreja ja toimitti yhteysuhrin ja laittoi pidot kaikille palvelijoillensa.'),
(1677747,58,11,3,16,'Siihen aikaan tuli kaksi porttoa kuninkaan luo, ja he astuivat hänen eteensä.'),
(1677748,58,11,3,17,'Ja toinen nainen sanoi: "Oi herrani, minä ja tämä nainen asumme samassa huoneessa. Ja minä synnytin hänen luonansa siinä huoneessa.'),
(1677749,58,11,3,18,'Ja kolmantena päivänä sen jälkeen, kun minä olin synnyttänyt, synnytti myös tämä nainen. Me olimme yhdessä, eikä ketään vierasta ollut meidän kanssamme huoneessa; ainoastaan me kahden olimme huoneessa.'),
(1677750,58,11,3,19,'Mutta tämän naisen poika kuoli yöllä, sillä hän oli maannut sen.'),
(1677751,58,11,3,20,'Niin hän nousi keskellä yötä ja otti minun poikani vierestäni palvelijattaresi nukkuessa ja pani sen povellensa, mutta oman kuolleen poikansa hän pani minun povelleni.'),
(1677752,58,11,3,21,'Kun minä aamulla nousin imettämään poikaani, niin katso, se oli kuollut. Mutta kun minä tarkastin sitä aamulla, niin katso, se ei ollutkaan minun poikani, jonka minä olin synnyttänyt."'),
(1677753,58,11,3,22,'Niin toinen nainen sanoi: "Ei ole niin; vaan tuo elossa oleva on minun poikani, ja tämä kuollut on sinun poikasi". Mutta edellinen vastasi: "Ei ole niin; tuo kuollut on sinun poikasi, ja tämä elossa oleva on minun poikani". Näin he riitelivät kuninkaan edessä.'),
(1677754,58,11,3,23,'Niin kuningas sanoi: "Toinen sanoo: ''Elossa oleva on minun poikani, ja kuollut on sinun poikasi''. Ja toinen sanoo: ''Ei ole niin; vaan kuollut on sinun poikasi, ja elossa oleva on minun poikani''."'),
(1677755,58,11,3,24,'Sitten kuningas sanoi: "Antakaa minulle miekka". Ja kuninkaan eteen tuotiin miekka.'),
(1677756,58,11,3,25,'Ja kuningas sanoi: "Viiltäkää elossa oleva lapsi kahtia, ja antakaa toinen puoli toiselle ja toinen puoli toiselle".'),
(1677757,58,11,3,26,'Mutta silloin sanoi kuninkaalle se nainen, jonka oma elossa oleva poika oli, sillä hänen sydämensä tuli liikutetuksi hänen poikansa tähden - hän sanoi: "Oi herrani, antakaa tuolle elossa oleva lapsi; älkää surmatko sitä". Mutta toinen sanoi: "Ei minulle eikä sinulle; viiltäkää!"'),
(1677758,58,11,3,27,'Niin kuningas vastasi ja sanoi: "Antakaa tälle elossa oleva lapsi; älkää surmatko sitä. Hän on sen äiti."'),
(1677759,58,11,3,28,'Ja koko Israel kuuli tästä tuomiosta, jonka kuningas oli antanut, ja he pelkäsivät kuningasta; sillä he näkivät, että hänessä oli Jumalan viisaus oikeuden jakamiseen.'),
(1677760,58,11,4,1,'Kuningas Salomo oli koko Israelin kuningas.'),
(1677761,58,11,4,2,'Ja nämä olivat hänen ylimmät virkamiehensä: Asarja, Saadokin poika, oli ylipappina;'),
(1677762,58,11,4,3,'Elihoref ja Ahia, Siisan pojat, olivat kirjureina; Joosafat, Ahiludin poika, oli kanslerina;'),
(1677763,58,11,4,4,'Benaja, Joojadan poika, oli sotaväen ylipäällikkönä; Saadok ja Ebjatar olivat pappeina.'),
(1677764,58,11,4,5,'Asarja, Naatanin poika, oli ylimaaherrana; Saabud, Naatanin poika, pappi, oli kuninkaan ystävänä.'),
(1677765,58,11,4,6,'Ahisar oli linnanpäällikkönä; Adoniram, Abdan poika, oli verotöiden valvojana.'),
(1677766,58,11,4,7,'Ja Salomolla oli kaksitoista maaherraa, yli koko Israelin, joiden oli hankittava kuninkaan ja hänen hovinsa elintarpeet; yhtenä kuukautena vuodessa oli kunkin hankittava elintarpeet.'),
(1677767,58,11,4,8,'Nämä olivat heidän nimensä: Huurin poika Efraimin vuoristossa;'),
(1677768,58,11,4,9,'Dekerin poika Maakaassa, Saalbimissa, Beet-Semeksessä, Eelonissa ja Beet-Haananissa;'),
(1677769,58,11,4,10,'Hesedin poika Arubbotissa; hänellä oli Sooko ja koko Heeferin maa;'),
(1677770,58,11,4,11,'Abinadabin poika koko Doorin kukkula-alueella; hänellä oli vaimona Taafat, Salomon tytär;'),
(1677771,58,11,4,12,'Baana, Ahiludin poika, Taanakissa ja Megiddossa ja koko Beet-Seanissa, joka on Saaretanin sivulla Jisreelin alapuolella, Beet-Seanista aina Aabel-Meholaan, tuolle puolelle Jokmeamin;'),
(1677772,58,11,4,13,'Geberin poika Gileadin Raamotissa; hänellä oli Jaairin, Manassen pojan, leirikylät, jotka ovat Gileadissa; hänellä oli siis Argobin seutu, joka on Baasanissa, kuusikymmentä suurta, muureilla ja vaskisalvoilla varustettua kaupunkia;'),
(1677773,58,11,4,14,'Ahinadab, Iddon poika, Mahanaimissa;'),
(1677774,58,11,4,15,'Ahimaas Naftalissa; hänkin oli ottanut vaimokseen Salomon tyttären, Baasematin;'),
(1677775,58,11,4,16,'Baana, Huusain poika, Asserissa ja Bealotissa;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677776,58,11,4,17,'Joosafat, Paaruahin poika, Isaskarissa;'),
(1677777,58,11,4,18,'Siimei, Eelan poika, Benjaminissa;'),
(1677778,58,11,4,19,'Geber, Uurin poika, Gileadin maassa, Siihonin, amorilaisten kuninkaan, ja Oogin, Baasanin kuninkaan, maassa; sillä siinä maassa oli yksi maaherra.'),
(1677779,58,11,4,20,'Juudaa ja Israelia oli paljon, niin paljon kuin hiekkaa meren rannalla; he söivät ja joivat ja olivat iloisia.'),
(1677780,58,11,4,21,'Ja Salomo hallitsi kaikkia valtakuntia Eufrat-virrasta aina filistealaisten maahan ja Egyptin rajaan asti. He toivat lahjoja ja palvelivat Salomoa, niin kauan kuin hän eli.'),
(1677781,58,11,4,22,'Ja Salomon jokapäiväinen muona oli: kolmekymmentä koor-mittaa lestyjä jauhoja ja kuusikymmentä koor-mittaa muita jauhoja,'),
(1677782,58,11,4,23,'kymmenen syöttöraavasta, kaksikymmentä laitumella käyvää raavasta ja sata lammasta; näitten lisäksi peuroja, gaselleja, metsäkauriita ja syötettyjä hanhia.'),
(1677783,58,11,4,24,'Sillä hän vallitsi kaikkea Eufrat-virran senpuoleista maata, Tifsahista aina Gassaan saakka, kaikkia Eufrat-virran senpuoleisia kuninkaita; ja hänellä oli rauha joka puolelta yltympäri,'),
(1677784,58,11,4,25,'niin että Juuda ja Israel asuivat turvallisesti, itsekukin viinipuunsa ja viikunapuunsa alla, Daanista Beersebaan asti, niin kauan kuin Salomo eli.'),
(1677785,58,11,4,26,'Ja Salomolla oli neljäkymmentä tuhatta hevosvaljakkoa vaunujaan varten ja kaksitoista tuhatta ratsuhevosta.'),
(1677786,58,11,4,27,'Ja maaherrat hankkivat, kukin kuukautenaan, elintarpeet kuningas Salomolle ja kaikille, joilla oli pääsy kuningas Salomon pöytään, antamatta minkään puuttua.'),
(1677787,58,11,4,28,'Myöskin ohrat ja oljet hevosille ja juoksijoille he toivat, kukin vuorollaan, siihen paikkaan, missä hän oleskeli.'),
(1677788,58,11,4,29,'Ja Jumala antoi Salomolle viisautta ja ymmärrystä ylen runsaasti ja älyä niin laajalti, kuin on hiekkaa meren rannalla,'),
(1677789,58,11,4,30,'niin että Salomon viisaus oli suurempi kuin kaikkien Idän miesten ja kaikkien egyptiläisten viisaus.'),
(1677790,58,11,4,31,'Hän oli viisaampi kaikkia ihmisiä, viisaampi kuin esrahilainen Eetan ja Heeman, Kalkol ja Darda, Maaholin pojat; ja hänen nimensä tuli kuuluksi kaikkien ympärillä olevien kansojen keskuudessa.'),
(1677791,58,11,4,32,'Ja Salomo sepitti kolmetuhatta sananlaskua, ja hänen laulujansa oli tuhatviisi.'),
(1677792,58,11,4,33,'Hän puhui puista, Libanonin setripuusta alkaen isoppiin asti, joka kasvaa seinän vieressä. Hän puhui myös karjaeläimistä, linnuista, matelijoista ja kaloista.'),
(1677793,58,11,4,34,'Ja Salomon viisautta tultiin kuulemaan kaikista kansoista, kaikkien maan kuninkaiden luota, jotka olivat kuulleet hänen viisaudestansa.'),
(1677794,58,11,5,1,'Hiiram, Tyyron kuningas, lähetti palvelijoitansa Salomon luo, kuultuaan, että hänet oli voideltu kuninkaaksi isänsä sijaan; sillä Hiiram oli aina ollut Daavidin likeinen ystävä.'),
(1677795,58,11,5,2,'Ja Salomo lähetti Hiiramille tämän sanan:'),
(1677796,58,11,5,3,'"Sinä tiedät, ettei minun isäni Daavid voinut rakentaa temppeliä Herran, Jumalansa, nimelle niiden sotien tähden, joilla häntä joka puolelta ahdistettiin, kunnes Herra oli laskenut viholliset hänen jalkojensa alle.'),
(1677797,58,11,5,4,'Mutta nyt Herra, minun Jumalani, on suonut minun päästä rauhaan joka taholla; ei ole vastustajaa eikä vaaran uhkaa.'),
(1677798,58,11,5,5,'Sentähden minä aion rakentaa temppelin Herran, Jumalani, nimelle, niinkuin Herra puhui minun isälleni Daavidille, sanoen: ''Sinun poikasi, jonka minä asetan valtaistuimellesi sinun sijaasi, on rakentava minun nimelleni temppelin''.'),
(1677799,58,11,5,6,'Niin käske nyt hakata minulle setripuita Libanonilta. Ja minun palvelijani olkoot sinun palvelijaisi kanssa. Ja minä annan sinulle palvelijaisi palkan, aivan niinkuin sinä määräät. Sillä sinä tiedät, ettei meillä ole ketään, joka osaisi niin hakata puita kuin siidonilaiset."'),
(1677800,58,11,5,7,'Kun Hiiram kuuli Salomon sanat, tuli hän hyvin iloiseksi ja sanoi: "Kiitetty olkoon tänä päivänä Herra, joka on antanut Daavidille viisaan pojan hallitsemaan tuota monilukuista kansaa".'),
(1677801,58,11,5,8,'Ja Hiiram lähetti Salomolle tämän sanan: "Minä olen kuullut sanan, jonka sinä minulle lähetit. Minä olen täyttävä kaikessa sinun toivomuksesi, mitä tulee setripuihin ja kypressipuihin.'),
(1677802,58,11,5,9,'Minun palvelijani vetäkööt ne Libanonilta alas mereen, ja minä panetan ne meressä lauttoihin kuljetettaviksi paikkaan, minkä sinä minulle määräät, ja hajotan ne siellä; sinä saat noutaa ne sieltä. Mutta täytä sinä minun toivomukseni ja anna minun hovilleni muonaa."'),
(1677803,58,11,5,10,'Niin Hiiram antoi Salomolle setripuita ja kypressipuita niin paljon, kuin tämä toivoi.'),
(1677804,58,11,5,11,'Mutta Salomo antoi Hiiramille kaksikymmentä tuhatta koor-mittaa nisuja, ravinnoksi hänen hovillensa, ja kaksikymmentä koor-mittaa survomalla saatua öljyä. Tämän Salomo antoi Hiiramille joka vuosi.'),
(1677805,58,11,5,12,'Ja Herra oli antanut Salomolle viisautta, niinkuin hän oli hänelle luvannut. Ja rauha vallitsi Hiiramin ja Salomon välillä, ja he tekivät liiton keskenänsä.'),
(1677806,58,11,5,13,'Ja kuningas Salomo otti verotyöläisiä koko Israelista, ja verotyöläisiä oli kolmekymmentä tuhatta miestä.'),
(1677807,58,11,5,14,'Nämä hän lähetti Libanonille vuorotellen, kymmenentuhatta kunakin kuukautena, niin että he olivat yhden kuukauden Libanonilla ja kaksi kuukautta kotonansa; ja Adoniram oli verotöiden valvojana.'),
(1677808,58,11,5,15,'Ja Salomolla oli seitsemänkymmentä tuhatta taakankantajaa ja kahdeksankymmentä tuhatta kivenhakkaajaa vuoristossa;'),
(1677809,58,11,5,16,'sen lisäksi Salomon maaherrojen virkamiehiä, jotka valvoivat töitä, kolmetuhatta kolmesataa miestä, vallitsemassa väkeä, joka teki työtä.'),
(1677810,58,11,5,17,'Ja kuningas käski louhia suuria kiviä, kallisarvoisia kiviä, laskeakseen temppelin perustuksen hakatuista kivistä.'),
(1677811,58,11,5,18,'Niin Salomon ja Hiiramin rakentajat ja gebalilaiset hakkasivat niitä ja valmistivat puut ja kivet temppelin rakentamiseksi.'),
(1677812,58,11,6,1,'Neljäntenäsadantena kahdeksantenakymmenentenä vuotena siitä, kun israelilaiset olivat lähteneet Egyptin maasta, neljäntenä vuotena siitä, kun Salomo oli tullut Israelin kuninkaaksi, alkoi hän siiv-kuussa, joka on toinen kuukausi, rakentaa temppeliä Herralle.'),
(1677813,58,11,6,2,'Temppeli, jonka kuningas Salomo Herralle rakensi, oli kuuttakymmentä kyynärää pitkä, kahtakymmentä kyynärää leveä ja kolmeakymmentä kyynärää korkea.'),
(1677814,58,11,6,3,'Temppelisalin eteinen, joka oli temppelin itäpäässä, oli kahtakymmentä kyynärää pitkä, ja sen leveys, temppelin itäiseen suuntaan, oli kymmenen kyynärää.'),
(1677815,58,11,6,4,'Ja hän teki temppeliin sisäänpäin avartuvat ikkuna-aukot.'),
(1677816,58,11,6,5,'Ja hän rakensi temppelin seinään kiinni kylkirakennuksen, ympäri temppelin seinien, sekä temppelisalin että kaikkeinpyhimmän ympäri, ja teki siihen sivukammioita yltympäri.'),
(1677817,58,11,6,6,'Kylkirakennuksen alin kerros oli viittä kyynärää leveä, keskimmäinen kuutta kyynärää leveä ja kolmas seitsemää kyynärää leveä; sillä hän teki temppelin ulkomuurin ympärinsä penkerellisen, ettei vuoliaisia tarvinnut upottaa temppelin seiniin.'),
(1677818,58,11,6,7,'Ja kun temppeli rakennettiin, tehtiin se kivistä, jotka tulivat valmiina louhimosta, niin ettei kuulunut vasaran, ei minkään rauta-aseen kalketta temppeliä rakennettaessa.'),
(1677819,58,11,6,8,'Alimman kerroksen ovi oli temppelin eteläsivussa; portaita myöten noustiin keskimmäiseen kerrokseen ja keskimmäisestä kolmanteen.'),
(1677820,58,11,6,9,'Rakennettuaan temppelin valmiiksi hän laudoitti sen sisältä setripuisilla parruilla ja laudoilla.'),
(1677821,58,11,6,10,'Ja hän rakensi kauttaaltaan kiinni temppeliin kylkirakennuksen, jonka kerrokset olivat viiden kyynärän korkuiset ja joka oli kiinnitetty temppeliin setripalkeilla.'),
(1677822,58,11,6,11,'Ja Salomolle tuli tämä Herran sana:'),
(1677823,58,11,6,12,'"Tälle temppelille, jota sinä rakennat, on käyvä näin: jos sinä vaellat minun säädöksieni mukaan ja noudatat minun oikeuksiani, otat vaarin kaikista minun käskyistäni ja vaellat niiden mukaan, niin minä täytän sinulle sanani, jonka olen puhunut sinun isällesi Daavidille:'),
(1677824,58,11,6,13,'minä asun israelilaisten keskellä enkä hylkää kansaani Israelia".'),
(1677825,58,11,6,14,'Niin Salomo rakensi temppelin valmiiksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677826,58,11,6,15,'Hän laudoitti temppelin seinät sisäpuolelta setrilaudoilla; temppelin lattiasta kattopalkkeihin asti hän päällysti sen puulla sisäpuolelta. Temppelin lattian hän päällysti kypressilaudoilla.'),
(1677827,58,11,6,16,'Ja temppelin peräosan, kaksikymmentä kyynärää, hän laudoitti erilleen setrilaudoilla lattiasta kattopalkkeihin asti; niin hän rakensi siihen sisälle kuorin, kaikkeinpyhimmän.'),
(1677828,58,11,6,17,'Ja temppeli, se on temppelisali kaikkeinpyhimmän edessä, oli neljääkymmentä kyynärää pitkä.'),
(1677829,58,11,6,18,'Ja temppeli oli sisäpuolelta setripuuta, koristettu metsäkurpitsi- ja kukkakiehkura-leikkauksilla; kaikki oli setripuuta, kiveä ei näkynyt.'),
(1677830,58,11,6,19,'Temppelin sisään hän laittoi kaikkeinpyhimmän, pannakseen sinne Herran liitonarkin.'),
(1677831,58,11,6,20,'Kaikkeinpyhin oli kahtakymmentä kyynärää pitkä, kahtakymmentä kyynärää leveä ja kahtakymmentä kyynärää korkea; ja hän päällysti sen sisältä puhtaalla kullalla, ja hän teki alttarin setripuusta.'),
(1677832,58,11,6,21,'Ja Salomo päällysti temppelin sisäpuolelta puhtaalla kullalla. Ja hän sulki kultavitjoilla kaikkeinpyhimmän, jonka oli päällystänyt kullalla.'),
(1677833,58,11,6,22,'Koko temppelin hän päällysti sisältä kullalla, koko temppelin yltyleensä. Myöskin koko sen alttarin, joka oli kaikkeinpyhimmän edessä, hän päällysti kullalla.'),
(1677834,58,11,6,23,'Ja hän teki kaikkeinpyhimpään kaksi kerubia öljypuusta, kymmenen kyynärän korkuista;'),
(1677835,58,11,6,24,'ja kerubin toinen siipi oli viisikyynäräinen, ja kerubin toinen siipi oli myöskin viisikyynäräinen, niin että oli kymmenen kyynärää toisen siiven kärjestä toisen kärkeen.'),
(1677836,58,11,6,25,'Toinen kerubi oli myöskin kymmenkyynäräinen. Molemmat kerubit olivat yhtä suuret ja yhdenmuotoiset:'),
(1677837,58,11,6,26,'toinen kerubi oli kymmentä kyynärää korkea ja samoin myöskin toinen kerubi.'),
(1677838,58,11,6,27,'Ja hän pani kerubit temppelin sisimpään osaan, ja kerubit levittivät siipensä niin, että toisen siipi kosketti toista seinää ja toisen kerubin siipi kosketti toista seinää; ja temppelin keskikohdalla koskettivat niiden toiset siivet toisiaan.'),
(1677839,58,11,6,28,'Ja hän päällysti kerubit kullalla.'),
(1677840,58,11,6,29,'Ja kaikkiin temppelin seiniin yltympäri hän leikkautti veistoksia, kerubeja, palmuja ja kukkakiehkuroita sekä perä- että etuosaan.'),
(1677841,58,11,6,30,'Ja temppelin lattian hän päällysti kullalla, sekä perä- että etuosan lattian.'),
(1677842,58,11,6,31,'Ja kaikkeinpyhimmän oviaukkoon hän teki ovet öljypuusta; kamana ja pielet muodostivat viisikulmion.'),
(1677843,58,11,6,32,'Ja molempiin öljypuusta tehtyihin oviin hän leikkautti kerubeja, palmuja ja kukkakiehkuroita, ja päällysti ne kullalla; hän levitti kultaa kerubien ja palmujen päälle.'),
(1677844,58,11,6,33,'Niin hän teki myös temppelisalin oviaukkoon öljypuusta pielet, nelikulmion muotoiset,'),
(1677845,58,11,6,34,'ja kypressipuusta kaksi ovea; toisen oven molemmat laudat olivat kääntyviä, ja toisen oven molemmat laudat olivat kääntyviä.'),
(1677846,58,11,6,35,'Ja hän leikkautti niihin kerubeja, palmuja ja kukkakiehkuroita ja päällysti ne kullalla, joka levitettiin veistosten päälle.'),
(1677847,58,11,6,36,'Sitten hän rakensi sisemmän esipihan muurin, jossa oli aina rinnakkain kolme kivikertaa hakattuja kiviä ja yksi hirsikerta veistettyjä setrihirsiä.'),
(1677848,58,11,6,37,'Neljäntenä vuotena, siiv-kuussa, laskettiin Herran temppelin perustus.'),
(1677849,58,11,6,38,'Ja yhdentenätoista vuotena, buul-kuussa, joka on kahdeksas kuukausi, temppeli oli kokonaan ja kaikkineen valmis. Hän rakensi sitä seitsemän vuotta.'),
(1677850,58,11,7,1,'Mutta omaa linnaansa Salomo rakensi kolmetoista vuotta ja sai niin koko linnansa valmiiksi.'),
(1677851,58,11,7,2,'Hän rakensi Libanoninmetsä-talon, sataa kyynärää pitkän, viittäkymmentä kyynärää leveän ja kolmeakymmentä kyynärää korkean, kolmen setripylväsrivin varaan, ja pylväiden päällä oli veistetyt setriansaat.'),
(1677852,58,11,7,3,'Ja siinä oli setripuukatto sivukammioiden päällä, jotka olivat pylväiden varassa; pylväitä oli yhteensä neljäkymmentä viisi, viisitoista kussakin rivissä.'),
(1677853,58,11,7,4,'Ja siinä oli ikkunoita kolmessa rivissä, ja valoaukot olivat vastakkain, aina kolme ja kolme.'),
(1677854,58,11,7,5,'Kaikki oviaukot ja valoaukot olivat nelikulmaiset; ja oviaukot olivat vastakkain, aina kolme ja kolme.'),
(1677855,58,11,7,6,'Vielä hän teki pylvässalin, viittäkymmentä kyynärää pitkän ja kolmeakymmentä kyynärää leveän, ja sen eteen eteisen pylväineen sekä pylväiden eteen porraskatoksen.'),
(1677856,58,11,7,7,'Sitten hän teki valtaistuinsalin, jossa hän jakoi oikeutta, oikeussalin; se oli laudoitettu sisältä setripuulla lattiasta kattoon asti.'),
(1677857,58,11,7,8,'Ja hänen linnansa, jossa hän itse asui, oli toisella esipihalla, salin takana, ja oli rakennettu samalla tavalla. Salomo teki myöskin faraon tyttärelle, jonka hän oli nainut, palatsin, samanlaisen kuin sali.'),
(1677858,58,11,7,9,'Kaikki nämä olivat rakennetut kallisarvoisista, mitan mukaan hakatuista ja sisältä ja ulkoa sahalla sahatuista kivistä, perustuksesta räystäisiin asti; samoin ulkopuolella suureen esipihaan saakka.'),
(1677859,58,11,7,10,'Ja perustus oli laskettu kallisarvoisista kivistä, suurista kivistä, kymmenkyynäräisistä ja kahdeksankyynäräisistä kivistä.'),
(1677860,58,11,7,11,'Ja sen päällä oli kallisarvoisia, mitan mukaan hakattuja kiviä sekä setripuuta.'),
(1677861,58,11,7,12,'Ja suuren esipihan muurissa oli yltympäri, aina rinnakkain, kolme kivikertaa hakattuja kiviä ja yksi hirsikerta veistettyjä setrihirsiä. Samoin oli Herran temppelin sisemmän esipihan muuri ja myöskin palatsin eteisen esipihan muuri rakennettu.'),
(1677862,58,11,7,13,'Ja kuningas Salomo lähetti noutamaan Hiiramin Tyyrosta.'),
(1677863,58,11,7,14,'Hän oli leskivaimon poika Naftalin sukukunnasta, ja hänen isänsä oli ollut tyyrolainen, vaskiseppä. Hän oli täynnä taidollisuutta, ymmärrystä ja tietoa, niin että hän kykeni valmistamaan kaikkinaisia vaskitöitä. Ja hän tuli kuningas Salomon luo ja valmisti kaikki hänen työnsä.'),
(1677864,58,11,7,15,'Hän teki vaskesta kaksi pylvästä. Toinen pylväs oli kahdeksantoista kyynärän korkuinen, ja kahdentoista kyynärän pituinen nauha ulottui toisen pylvään ympäri.'),
(1677865,58,11,7,16,'Hän teki myös kaksi pylväänpäätä, vaskesta valettua, pylväiden päähän pantavaksi. Kummankin pylväänpään korkeus oli viisi kyynärää.'),
(1677866,58,11,7,17,'Verkon kaltaisia ristikkokoristeita, vitjan kaltaisia riippukoristeita, oli pylväänpäissä, jotka olivat pylväiden päässä, seitsemän kummassakin pylväänpäässä.'),
(1677867,58,11,7,18,'Ja hän teki granaattiomenia kahteen riviin toisen ristikkokoristeen päälle yltympäri, peittämään pylväänpäät, jotka olivat pylväiden päässä; ja samoin hän teki niitä toiseen pylväänpäähän.'),
(1677868,58,11,7,19,'Ja pylväänpäät, jotka olivat pylväiden päässä eteisessä, olivat liljan muotoiset, nelikyynäräiset.'),
(1677869,58,11,7,20,'Pylväänpäissä, ylhäällä kahden pylvään päässä, oli kupevat alaosat, joihin ristikkokoriste ei ulottunut. Ja granaattiomenia oli kaksisataa, rivittäin yltympäri toisen pylväänpään päällä.'),
(1677870,58,11,7,21,'Ja hän pystytti pylväät temppelin eteisen eteen. Pylväälle, jonka hän pystytti oikealle puolelle, hän antoi nimen Jaakin, ja pylväälle, jonka hän pystytti vasemmalle puolelle, hän antoi nimen Booas.'),
(1677871,58,11,7,22,'Ylinnä pylväiden päällä oli liljan muotoinen laite. Ja niin päättyi pylväiden valmistus.'),
(1677872,58,11,7,23,'Hän teki myös meren, valetun, kymmentä kyynärää leveän reunasta reunaan, ympärinsä pyöreän ja viittä kyynärää korkean; ja kolmenkymmenen kyynärän pituinen mittanuora ulottui sen ympäri.'),
(1677873,58,11,7,24,'Sen reunan alla oli metsäkurpitsikoristeita, jotka kulkivat sen ympäri. Ne ympäröivät merta yltympäri, kymmenen jokaisella kyynärällä. Metsäkurpitsikoristeet olivat kahdessa rivissä, valettuina meren kanssa yhteen.'),
(1677874,58,11,7,25,'Ja se seisoi kahdentoista raavaan varassa, joista kolme oli käännettynä pohjoiseen, kolme länteen, kolme etelään ja kolme itään päin; meri oli niiden yläpuolella, niiden varassa, ja kaikkien niiden takapuolet olivat sisäänpäin.'),
(1677875,58,11,7,26,'Se oli kämmenen paksuinen, ja sen reuna oli maljan reunan kaltainen, puhjenneen liljan muotoinen; se veti kaksituhatta bat-mittaa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677876,58,11,7,27,'Hän teki myös kymmenen telinettä vaskesta. Kukin teline oli neljää kyynärää pitkä, neljää kyynärää leveä ja kolmea kyynärää korkea.'),
(1677877,58,11,7,28,'Ja telineet olivat rakenteeltaan tällaiset: niissä oli kehäpienat, ja myös poikkitankojen välissä oli kehäpienat.'),
(1677878,58,11,7,29,'Kehäpienain päällä, jotka olivat poikkitankojen välissä, oli leijonia, raavaita ja kerubeja, ja samoin poikkitankojen päällä, sekä ylhäällä että alhaalla. Leijonissa ja raavaissa oli takomalla tehtyjä punonnaiskoristeita.'),
(1677879,58,11,7,30,'Kussakin telineessä oli neljä vaskipyörää ja vaskiakselit; ja niiden neljässä jalkapylväässä oli olkapää. Olkapäät olivat valetut altaan alle; kunkin ulkopuolella oli punonnaiskoristeita.'),
(1677880,58,11,7,31,'Telineen aukko oli olkapäiden sisäpuolella, ja sen reuna oli kyynärän korkuinen; aukko oli pyöreä, jalustan tapaan tehty, puolitoistakyynäräinen. Myöskin aukon reunassa oli leikkauksia. Kehäpienat olivat nelikulmaiset eivätkä pyöreät.'),
(1677881,58,11,7,32,'Ja ne neljä pyörää olivat kehäpienain alla, ja pyöräin pitimet olivat telineessä kiinni. Kukin pyörä oli puoltatoista kyynärää korkea.'),
(1677882,58,11,7,33,'Pyörät olivat tehdyt niinkuin vaununpyörät; ja niiden pitimet, kehät, puolat ja navat olivat kaikki valetut.'),
(1677883,58,11,7,34,'Neljä olkapäätä oli kussakin telineessä, sen neljässä kulmassa; olkapäät olivat yhtä telineen kanssa.'),
(1677884,58,11,7,35,'Ylinnä telineen päällä oli puolen kyynärän korkuinen laite, ympärinsä pyöreä; ja telineen pitimet ja kehäpienat olivat yhtä sen kanssa.'),
(1677885,58,11,7,36,'Ja sen kehäpienojen pintoihin hän kaiversi kerubeja, leijonia ja palmuja, niin paljon kuin kussakin oli tilaa, sekä punonnaiskoristeita yltympäri.'),
(1677886,58,11,7,37,'Näin hän teki ne kymmenen telinettä; ne olivat kaikki valetut samalla tavalla, yhtä suuret ja yhdenmuotoiset.'),
(1677887,58,11,7,38,'Hän teki myös kymmenen vaskiallasta; kukin allas veti neljäkymmentä bat-mittaa, ja kukin allas oli neljää kyynärää läpimitaten. Kullakin kymmenellä telineellä oli altaansa.'),
(1677888,58,11,7,39,'Ja hän asetti viisi telinettä temppelin oikealle sivulle ja viisi temppelin vasemmalle sivulle; meren hän asetti temppelin oikealle sivulle, kaakkoa kohti.'),
(1677889,58,11,7,40,'Hiiram teki myös kattilat, lapiot ja maljat. Ja niin Hiiram sai suoritetuksi kaiken työn, mikä hänen oli tehtävä kuningas Salomolle Herran temppeliin:'),
(1677890,58,11,7,41,'kaksi pylvästä ja ne kaksi pallonmuotoista pylväänpäätä, jotka olivat pylväiden päässä, ja ne kaksi ristikkokoristetta peittämään niitä kahta pallonmuotoista pylväänpäätä, jotka olivat pylväiden päässä;'),
(1677891,58,11,7,42,'ja ne neljäsataa granaattiomenaa kahteen ristikkokoristeeseen, kaksi riviä granaattiomenia kumpaankin ristikkokoristeeseen, peittämään niitä kahta pallonmuotoista pylväänpäätä, jotka olivat pylväiden päässä;'),
(1677892,58,11,7,43,'ja ne kymmenen telinettä ja ne kymmenen allasta telineiden päälle;'),
(1677893,58,11,7,44,'ja sen yhden meren, ja ne kaksitoista raavasta meren alle; ja kattilat, lapiot ja maljat.'),
(1677894,58,11,7,45,'Kaikki nämä kalut, jotka Hiiram teki kuningas Salomolle Herran temppeliin, olivat kiilloitetusta vaskesta.'),
(1677895,58,11,7,46,'Jordanin lakeudella kuningas ne valatti savimuotteihin, Sukkotin ja Saaretanin välillä.'),
(1677896,58,11,7,47,'Ja Salomo jätti kaikki kalut punnitsematta, koska niitä oli ylen paljon; vasken painoa ei määrätty.'),
(1677897,58,11,7,48,'Salomo teetti myös kaikki muut kalut, mitä Herran temppelissä on: kulta-alttarin, pöydän, jolla näkyleivät ovat, kullasta,'),
(1677898,58,11,7,49,'lampunjalat, viisi oikealle puolelle ja viisi vasemmalle puolelle kaikkeinpyhimmän eteen, puhtaasta kullasta, kultaisine kukkalehtineen, lamppuineen ja lamppusaksineen,'),
(1677899,58,11,7,50,'vadit, veitset, maljat, kupit ja hiilipannut, puhtaasta kullasta, sekä kultasaranat niihin temppelin sisäosan oviin, jotka vievät kaikkeinpyhimpään, ja niihin temppelin oviin, jotka vievät temppelisaliin.'),
(1677900,58,11,7,51,'Kun kaikki työ, minkä kuningas Salomo teetti Herran temppeliin, oli valmis, vei Salomo sinne isänsä Daavidin pyhät lahjat; hopean, kullan ja kalut hän pani Herran temppelin aarrekammioihin.'),
(1677901,58,11,8,1,'Sitten Salomo kokosi Israelin vanhimmat ja kaikki sukukuntien johtomiehet, israelilaisten perhekunta-päämiehet, kuningas Salomon luo Jerusalemiin, tuomaan Herran liitonarkkia Daavidin kaupungista, se on Siionista.'),
(1677902,58,11,8,2,'Niin kokoontuivat kuningas Salomon luo kaikki Israelin miehet juhlapäivänä eetanim-kuussa, joka on seitsemäs kuukausi.'),
(1677903,58,11,8,3,'Ja kun kaikki Israelin vanhimmat olivat tulleet saapuville, nostivat papit arkin,'),
(1677904,58,11,8,4,'ja he veivät Herran arkin ja ilmestysmajan sinne, sekä kaiken pyhän kaluston, joka oli majassa; papit ja leeviläiset veivät ne sinne.'),
(1677905,58,11,8,5,'Ja kuningas Salomo seisoi arkin edessä ja hänen kanssaan koko Israelin kansa, joka oli kokoontunut hänen luoksensa; ja he uhrasivat lampaita ja raavaita niin paljon, että niitä ei voitu lukea, ei laskea.'),
(1677906,58,11,8,6,'Ja papit toivat Herran liitonarkin paikoilleen temppelin kuoriin, kaikkeinpyhimpään, kerubien siipien alle.'),
(1677907,58,11,8,7,'Sillä kerubit levittivät siipensä sen paikan yli, missä arkki oli, ja kerubit suojasivat ylhäältä päin arkkia ja sen korentoja.'),
(1677908,58,11,8,8,'Ja korennot olivat niin pitkät, että niiden päät voi nähdä kaikkeinpyhimmästä, kuorin edestä; mutta ulkoa niitä ei voinut nähdä. Ja ne jäivät sinne, tähän päivään asti.'),
(1677909,58,11,8,9,'Arkissa ei ollut muuta kuin ne kaksi kivitaulua, jotka Mooses oli pannut sinne Hoorebilla, kun Herra teki liiton israelilaisten kanssa, heidän lähdettyänsä Egyptin maasta.'),
(1677910,58,11,8,10,'Ja kun papit lähtivät pyhäköstä, täytti pilvi Herran temppelin,'),
(1677911,58,11,8,11,'niin että papit eivät voineet astua toimittamaan virkaansa pilven tähden; sillä Herran kirkkaus täytti Herran temppelin.'),
(1677912,58,11,8,12,'Silloin Salomo sanoi: "Herra on sanonut tahtovansa asua pimeässä.'),
(1677913,58,11,8,13,'Minä olen rakentanut huoneen sinulle asunnoksi, asuinsijan, asuaksesi siinä iäti."'),
(1677914,58,11,8,14,'Sitten kuningas käänsi kasvonsa ja siunasi koko Israelin seurakunnan; ja koko Israelin seurakunta seisoi.'),
(1677915,58,11,8,15,'Hän sanoi: "Kiitetty olkoon Herra, Israelin Jumala, joka kädellänsä on täyttänyt sen, mitä hän suullansa puhui minun isälleni Daavidille, sanoen:'),
(1677916,58,11,8,16,'''Siitä päivästä saakka, jona minä vein kansani Israelin pois Egyptistä, en ole mistään Israelin sukukunnasta valinnut yhtään kaupunkia, että siihen rakennettaisiin temppeli, missä minun nimeni asuisi; mutta minä olen valinnut Daavidin vallitsemaan kansaani Israelia''.'),
(1677917,58,11,8,17,'Ja minun isäni Daavid aikoi rakentaa temppelin Herran, Israelin Jumalan, nimelle.'),
(1677918,58,11,8,18,'Mutta Herra sanoi minun isälleni Daavidille: ''Kun sinä aiot rakentaa temppelin minun nimelleni, niin tosin teet siinä hyvin, että sitä aiot;'),
(1677919,58,11,8,19,'kuitenkaan et sinä ole sitä temppeliä rakentava, vaan sinun poikasi, joka lähtee sinun kupeistasi, hän on rakentava temppelin minun nimelleni''.'),
(1677920,58,11,8,20,'Ja Herra on täyttänyt sanansa, jonka hän puhui: minä olen noussut isäni Daavidin sijalle ja istun Israelin valtaistuimella, niinkuin Herra puhui, ja minä olen rakentanut temppelin Herran, Israelin Jumalan, nimelle.'),
(1677921,58,11,8,21,'Ja minä olen valmistanut siihen sijan arkille, jossa on se Herran liitto, minkä hän teki meidän isiemme kanssa viedessään heidät pois Egyptin maasta."'),
(1677922,58,11,8,22,'Sitten Salomo astui Herran alttarin eteen koko Israelin seurakunnan nähden, ojensi kätensä taivasta kohti'),
(1677923,58,11,8,23,'ja sanoi: "Herra, Israelin Jumala, ei ole sinun vertaistasi jumalaa, ei ylhäällä taivaassa eikä alhaalla maan päällä, sinun, joka pidät liiton ja säilytät laupeuden palvelijoitasi kohtaan, jotka vaeltavat sinun edessäsi kaikesta sydämestänsä,'),
(1677924,58,11,8,24,'sinun, joka olet pitänyt, mitä puhuit palvelijallesi Daavidille, minun isälleni. Mitä suullasi puhuit, sen sinä kädelläsi täytit, niinkuin nyt on tapahtunut.'),
(1677925,58,11,8,25,'Niin pidä nytkin, Herra, Israelin Jumala, mitä puhuit palvelijallesi Daavidille, minun isälleni, sanoen: ''Aina on mies sinun suvustasi istuva minun edessäni Israelin valtaistuimella, jos vain sinun poikasi pitävät vaarin tiestänsä, niin että he vaeltavat minun edessäni, niinkuin sinä olet minun edessäni vaeltanut''.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677926,58,11,8,26,'Niin toteutukoot nyt, Israelin Jumala, sinun sanasi, jotka puhuit palvelijallesi Daavidille, minun isälleni.'),
(1677927,58,11,8,27,'Mutta asuuko todella Jumala maan päällä? Katso, taivaisiin ja taivasten taivaisiin sinä et mahdu; kuinka sitten tähän temppeliin, jonka minä olen rakentanut!'),
(1677928,58,11,8,28,'Käänny kuitenkin palvelijasi rukouksen ja anomisen puoleen, Herra, minun Jumalani, niin että kuulet huudon ja rukouksen, jonka palvelijasi tänä päivänä rukoilee sinun edessäsi,'),
(1677929,58,11,8,29,'ja että silmäsi ovat yöt ja päivät avoinna tätä temppeliä kohti, tätä paikkaa kohti, josta sinä olet sanonut: ''Minun nimeni on asuva siellä'', niin että kuulet rukouksen, jonka palvelijasi tähän paikkaan päin kääntyneenä rukoilee.'),
(1677930,58,11,8,30,'Kuule palvelijasi ja kansasi Israelin rukous, jonka he rukoilevat tähän paikkaan päin kääntyneinä; kuule asuinpaikastasi, taivaasta, ja kun kuulet, niin anna anteeksi.'),
(1677931,58,11,8,31,'Jos joku rikkoo lähimmäistänsä vastaan ja hänet pannaan valalle ja vannotetaan, ja jos hän tulee ja vannoo sinun alttarisi edessä tässä temppelissä,'),
(1677932,58,11,8,32,'niin kuule taivaasta ja auta palvelijasi oikeuteensa; tee niin, että tuomitset syyllisen syylliseksi ja annat hänen tekojensa tulla hänen päänsä päälle, mutta julistat syyttömän syyttömäksi ja annat hänelle hänen vanhurskautensa mukaan.'),
(1677933,58,11,8,33,'Jos vihollinen voittaa sinun kansasi, Israelin, sentähden että he ovat tehneet syntiä sinua vastaan, mutta he palajavat sinun tykösi, kiittävät sinun nimeäsi, rukoilevat sinua ja anovat sinulta armoa tässä temppelissä,'),
(1677934,58,11,8,34,'niin kuule taivaasta ja anna anteeksi kansasi Israelin synti ja tuo heidät takaisin tähän maahan, jonka olet antanut heidän isillensä.'),
(1677935,58,11,8,35,'Jos taivas suljetaan, niin ettei tule sadetta, koska he ovat tehneet syntiä sinua vastaan, mutta he rukoilevat kääntyneinä tähän paikkaan päin, ja kiittävät sinun nimeäsi ja kääntyvät synnistään, koska sinä kuulet heitä,'),
(1677936,58,11,8,36,'niin kuule taivaasta ja anna anteeksi palvelijaisi ja kansasi Israelin synti - sillä sinä osoitat heille hyvän tien, jota heidän on vaeltaminen - ja suo sade maallesi, jonka olet antanut kansallesi perintöosaksi.'),
(1677937,58,11,8,37,'Jos maahan tulee nälänhätä, rutto, jos tulee nokitähkä ja viljanruoste, jos tulevat heinäsirkat ja tuhosirkat, jos vihollinen ahdistaa sitä maassa, jossa sen portit ovat, jos tulee mikä tahansa vitsaus tai vaiva,'),
(1677938,58,11,8,38,'ja jos silloin joku ihminen, kuka hyvänsä, tai koko sinun kansasi Israel rukoilee ja anoo armoa, kun he kukin tuntevat omantunnon vaivoja ja ojentavat kätensä tähän temppeliin päin,'),
(1677939,58,11,8,39,'niin kuule silloin taivaasta, asuinpaikastasi, ja anna anteeksi ja tee niin, että annat jokaiselle aivan hänen tekojensa mukaan, koska sinä tunnet hänen sydämensä - sillä sinä yksin tunnet kaikkien ihmislasten sydämet -'),
(1677940,58,11,8,40,'jotta he sinua pelkäisivät niin kauan kuin he elävät tässä maassa, jonka sinä olet meidän isillemme antanut.'),
(1677941,58,11,8,41,'Myös jos joku muukalainen, joka ei ole sinun kansaasi Israelia, tulee kaukaisesta maasta sinun nimesi tähden -'),
(1677942,58,11,8,42,'sillä sielläkin kuullaan sinun suuresta nimestäsi, väkevästä kädestäsi ja ojennetusta käsivarrestasi - jos hän tulee ja rukoilee kääntyneenä tähän temppeliin päin,'),
(1677943,58,11,8,43,'niin kuule taivaasta, asuinpaikastasi, häntä ja tee kaikki, mitä muukalainen sinulta rukoilee, että kaikki maan kansat tuntisivat sinun nimesi ja pelkäisivät sinua, samoin kuin sinun kansasi Israel, ja tulisivat tietämään, että sinä olet ottanut nimiisi tämän temppelin, jonka minä olen rakentanut.'),
(1677944,58,11,8,44,'Jos sinun kansasi lähtee sotaan vihollistansa vastaan sitä tietä, jota sinä heidät lähetät, ja he rukoilevat Herraa kääntyneinä tähän kaupunkiin päin, jonka sinä olet valinnut, ja tähän temppeliin päin, jonka minä olen sinun nimellesi rakentanut,'),
(1677945,58,11,8,45,'niin kuule taivaasta heidän rukouksensa ja anomisensa ja hanki heille oikeus.'),
(1677946,58,11,8,46,'Jos he tekevät syntiä sinua vastaan - sillä ei ole ihmistä, joka ei syntiä tee - ja sinä vihastut heihin ja annat heidät vihollisen valtaan, niin että heidän vangitsijansa vievät heidät vangeiksi vihollismaahan, kaukaiseen tai läheiseen,'),
(1677947,58,11,8,47,'mutta jos he sitten menevät itseensä siinä maassa, johon heidät on vangeiksi viety, kääntyvät ja anovat sinulta armoa vangitsijainsa maassa, sanoen: ''Me olemme tehneet syntiä, tehneet väärin ja olleet jumalattomat'','),
(1677948,58,11,8,48,'ja palajavat sinun tykösi kaikesta sydämestään ja kaikesta sielustaan vihollistensa maassa, jotka veivät heidät vangeiksi, ja rukoilevat sinua kääntyneinä tähän maahan päin, jonka sinä olet antanut heidän isillensä, tähän kaupunkiin päin, jonka olet valinnut, ja tähän temppeliin päin, jonka minä olen sinun nimellesi rakentanut,'),
(1677949,58,11,8,49,'niin kuule taivaasta, asuinsijastasi, heidän rukouksensa ja anomisensa, hanki heille oikeus'),
(1677950,58,11,8,50,'ja anna anteeksi kansallesi, mitä he ovat rikkoneet sinua vastaan, ja kaikki heidän syntinsä, jotka he ovat tehneet sinua vastaan; ja suo, että heidän vangitsijansa olisivat laupiaat heitä kohtaan ja armahtaisivat heitä.'),
(1677951,58,11,8,51,'Sillä ovathan he sinun kansasi ja sinun perintöosasi, jonka olet vienyt pois Egyptistä, rautapätsistä.'),
(1677952,58,11,8,52,'Olkoot siis sinun silmäsi avoinna palvelijasi ja sinun kansasi Israelin anomisen puoleen, niin että kuulet heitä kaikessa, mitä he sinulta rukoilevat.'),
(1677953,58,11,8,53,'Sillä sinä olet erottanut heidät perintöosaksesi kaikista maan kansoista, niinkuin sinä puhuit palvelijasi Mooseksen kautta, viedessäsi isämme pois Egyptistä, Herra, Herra."'),
(1677954,58,11,8,54,'Ja kun Salomo oli lakannut rukoilemasta ja anomasta Herralta kaikkea tätä, nousi hän Herran alttarin edestä, jossa hän oli ollut polvillaan kädet ojennettuina taivasta kohti,'),
(1677955,58,11,8,55,'astui esille ja siunasi koko Israelin seurakunnan suurella äänellä, sanoen:'),
(1677956,58,11,8,56,'"Kiitetty olkoon Herra, joka on antanut levon kansallensa Israelille, aivan niinkuin hän on puhunut. Ei ole jäänyt täyttämättä ainoakaan kaikista lupauksista, jotka Herra on antanut palvelijansa Mooseksen kautta.'),
(1677957,58,11,8,57,'Olkoon Herra, meidän Jumalamme, meidän kanssamme, niinkuin hän on ollut meidän isiemme kanssa. Älköön hän meitä jättäkö älköönkä hyljätkö,'),
(1677958,58,11,8,58,'vaan kääntäköön meidän sydämemme puoleensa, niin että aina vaellamme hänen teitänsä ja noudatamme hänen käskyjänsä, säädöksiänsä ja oikeuksiansa, jotka hän on antanut meidän isillemme.'),
(1677959,58,11,8,59,'Ja olkoot nämä minun sanani, joilla minä olen armoa anonut Herran edessä, päivät ja yöt likellä Herraa, meidän Jumalaamme, että hän hankkisi oikeuden palvelijallensa ja kansallensa Israelille, kunkin päivän tarpeen mukaan,'),
(1677960,58,11,8,60,'niin että kaikki maan kansat tulisivat tietämään, että Herra on Jumala eikä muuta jumalaa ole.'),
(1677961,58,11,8,61,'Ja antautukaa te ehyin sydämin Herralle, Jumalallenne, niin että vaellatte hänen säädöksiensä mukaan ja noudatatte hänen käskyjänsä samoin kuin nytkin."'),
(1677962,58,11,8,62,'Sitten kuningas ja koko Israel hänen kanssansa uhrasivat teurasuhrin Herran edessä.'),
(1677963,58,11,8,63,'Ja Salomo uhrasi yhteysuhrina, jonka hän Herralle uhrasi, kaksikymmentäkaksi tuhatta raavasta ja satakaksikymmentä tuhatta lammasta. Niin he, kuningas ja kaikki israelilaiset, vihkivät Herran temppelin.'),
(1677964,58,11,8,64,'Sinä päivänä kuningas pyhitti Herran temppelin edessä olevan esipihan keskiosan, sillä hänen oli siellä uhrattava polttouhri, ruokauhri ja yhteysuhrin rasvat. Vaskialttari, joka oli Herran edessä, oli näet liian pieni, että polttouhri, ruokauhri ja yhteysuhrin rasvat olisivat siihen mahtuneet.'),
(1677965,58,11,8,65,'Näin Salomo siihen aikaan vietti juhlaa, ja koko Israel hänen kanssansa, Herran, meidän Jumalamme, edessä seitsemän päivää ja vielä toiset seitsemän päivää, yhteensä neljätoista päivää. Se oli suuri kokous, johon kokoonnuttiin aina sieltä, mistä mennään Hamatiin, ja aina Egyptin purolta asti.'),
(1677966,58,11,8,66,'Kahdeksantena päivänä hän päästi kansan menemään, ja he hyvästelivät kuninkaan. Sitten he menivät majoillensa iloiten ja hyvillä mielin kaikesta hyvästä, mitä Herra oli tehnyt palvelijallensa Daavidille ja kansallensa Israelille.'),
(1677967,58,11,9,1,'Kun Salomo oli saanut rakennetuksi Herran temppelin ja kuninkaan linnan ja kaiken, mitä Salomo oli halunnut tehdä,'),
(1677968,58,11,9,2,'ilmestyi Herra Salomolle toisen kerran,'),
(1677969,58,11,9,3,'niinkuin hän oli ilmestynyt hänelle Gibeonissa. Ja Herra sanoi hänelle: "Minä olen kuullut sinun rukouksesi ja anomisesi, kun sinä anoit armoa minun edessäni. Minä olen pyhittänyt tämän temppelin, jonka sinä olet rakentanut sitä varten, että minä sijoittaisin nimeni siihen ainiaaksi; ja minun silmäni ja sydämeni tulevat alati olemaan siellä.'),
(1677970,58,11,9,4,'Ja jos sinä vaellat minun edessäni, niinkuin sinun isäsi Daavid vaelsi, vilpittömällä sydämellä ja oikeamielisesti, niin että teet kaiken, mitä minä olen käskenyt sinun tehdä, ja noudatat minun käskyjäni ja oikeuksiani,'),
(1677971,58,11,9,5,'niin minä pidän pystyssä sinun kuninkaallisen valtaistuimesi Israelissa ikuisesti, niinkuin minä puhuin isällesi Daavidille sanoen: ''Aina on mies sinun suvustasi oleva Israelin valtaistuimella''.'),
(1677972,58,11,9,6,'Mutta jos te käännytte pois minusta, te ja teidän lapsenne, ettekä noudata minun käskyjäni ja säädöksiäni, jotka minä olen teille antanut, vaan menette ja palvelette muita jumalia ja kumarratte niitä,'),
(1677973,58,11,9,7,'niin minä hävitän Israelin siitä maasta, jonka olen antanut heille, ja temppelin, jonka minä olen pyhittänyt nimelleni, minä heitän pois kasvojeni edestä; ja Israel tulee sananparreksi ja pistopuheeksi kaikille kansoille.'),
(1677974,58,11,9,8,'Ja tämä temppeli on tosin korkein, mutta jokainen, joka kulkee siitä ohi, on tyrmistyvä ja viheltävä; ja kun kysytään: ''Miksi on Herra tehnyt näin tälle maalle ja tälle temppelille?'''),
(1677975,58,11,9,9,'niin vastataan: ''Siksi, että he hylkäsivät Herran, Jumalansa, joka oli vienyt heidän isänsä pois Egyptin maasta, ja liittyivät muihin jumaliin ja kumarsivat niitä ja palvelivat niitä; sentähden Herra on antanut kaiken tämän pahan kohdata heitä''."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1677976,58,11,9,10,'Kun olivat loppuun kuluneet ne kaksikymmentä vuotta, joiden kuluessa Salomo oli rakentanut ne kaksi rakennusta, Herran temppelin ja kuninkaan linnan,'),
(1677977,58,11,9,11,'Hiiramin, Tyyron kuninkaan, avustaessa Salomoa setripuilla, kypressipuilla ja kullalla, niin paljolla kuin tämä halusi, silloin kuningas Salomo antoi Hiiramille kaksikymmentä kaupunkia Galilean maakunnasta.'),
(1677978,58,11,9,12,'Niin Hiiram lähti Tyyrosta katsomaan niitä kaupunkeja, jotka Salomo oli antanut hänelle, mutta ne eivät miellyttäneet häntä.'),
(1677979,58,11,9,13,'Hän sanoi: "Mitä kaupunkeja nämä ovat, jotka sinä olet antanut minulle, veljeni!" Ja niin kutsutaan niitä Kaabulin maaksi vielä tänäkin päivänä.'),
(1677980,58,11,9,14,'Mutta Hiiram lähetti kuninkaalle sata kaksikymmentä talenttia kultaa.'),
(1677981,58,11,9,15,'Ja näin on sen työveron laita, jonka kuningas Salomo otatti rakentaaksensa Herran temppeliä, omaa linnaansa, Milloa ja Jerusalemin muuria sekä Haasoria, Megiddoa ja Geseriä.'),
(1677982,58,11,9,16,'Farao, Egyptin kuningas, oli näet tullut ja valloittanut Geserin, polttanut sen tulella ja surmannut kanaanilaiset, jotka asuivat kaupungissa, ja antanut sen myötäjäisiksi tyttärellensä, Salomon puolisolle.'),
(1677983,58,11,9,17,'Ja Salomo linnoitti Geserin, alisen Beet-Hooronin,'),
(1677984,58,11,9,18,'Baalatin ja Taamarin sen maan erämaassa'),
(1677985,58,11,9,19,'ja kaikki varastokaupungit, jotka hänellä oli, ja kaikki vaunukaupungit ja ratsumiesten kaupungit ja mitä muuta Salomo oli tahtonut linnoittaa Jerusalemissa ja Libanonilla ja koko hallitsemassaan maassa.'),
(1677986,58,11,9,20,'Kaiken kansan, mitä oli jäänyt jäljelle amorilaisista, heettiläisistä, perissiläisistä, hivviläisistä ja jebusilaisista, kaikki, jotka eivät olleet israelilaisia,'),
(1677987,58,11,9,21,'ne niiden jälkeläiset, jotka vielä olivat jäljellä maassa ja joita israelilaiset eivät olleet kyenneet vihkimään tuhon omiksi, ne Salomo saattoi työveron alaisiksi, aina tähän päivään asti.'),
(1677988,58,11,9,22,'Mutta israelilaisista Salomo ei tehnyt ketään orjaksi, vaan heitä oli sotilaina, hänen palvelijoinaan, päällikköinään, vaunusotureinaan ja hänen sotavaunujensa ja ratsumiestensä päällikköinä.'),
(1677989,58,11,9,23,'Maaherrojen virkamiehiä, jotka valvoivat Salomon töitä, oli viisisataa viisikymmentä miestä, vallitsemassa väkeä, joka teki työtä.'),
(1677990,58,11,9,24,'Heti kun faraon tytär oli muuttanut Daavidin kaupungista omaan linnaansa, jonka hän oli hänelle rakentanut, rakensi hän Millon.'),
(1677991,58,11,9,25,'Ja Salomo uhrasi kolme kertaa vuodessa polttouhreja ja yhteysuhreja alttarilla, jonka hän oli rakentanut Herralle, ja suitsutti alttarin ääressä, joka oli Herran edessä. Ja niin hän oli saanut temppelin valmiiksi.'),
(1677992,58,11,9,26,'Kuningas Salomo rakensi myös laivaston Esjon-Geberissä, joka on lähellä Eelatia Kaislameren rannalla Edomin maassa.'),
(1677993,58,11,9,27,'Tähän laivastoon Hiiram lähetti palvelijoitaan, meritaitoisia laivamiehiä, Salomon palvelijain mukaan.'),
(1677994,58,11,9,28,'He menivät Oofiriin ja noutivat sieltä kultaa neljäsataa kaksikymmentä talenttia ja toivat sen kuningas Salomolle.'),
(1677995,58,11,10,1,'Kun Saban kuningatar kuuli, mitä Salomosta kerrottiin Herran nimen kunniaksi, tuli hän koettelemaan häntä arvoituksilla.'),
(1677996,58,11,10,2,'Hän tuli Jerusalemiin sangen suuren seurueen kanssa, mukanaan kameleja, jotka kantoivat hajuaineita, kultaa ylen paljon ja kalliita kiviä. Ja kun hän tuli Salomon luo, puhui hän tälle kaikki, mitä hänellä oli mielessänsä.'),
(1677997,58,11,10,3,'Mutta Salomo selitti hänelle kaikki hänen kysymyksensä; kuninkaalle ei mikään jäänyt ongelmaksi, jota hän ei olisi hänelle selittänyt.'),
(1677998,58,11,10,4,'Kun Saban kuningatar näki kaiken Salomon viisauden, linnan, jonka hän oli rakentanut,'),
(1677999,58,11,10,5,'ruuat hänen pöydällänsä, kuinka hänen palvelijansa asuivat ja hänen palvelusväkensä palveli ja kuinka he olivat puetut, ja näki hänen juomanlaskijansa ja hänen polttouhrinsa, jotka hän uhrasi Herran temppelissä, meni hän miltei hengettömäksi.'),
(1678000,58,11,10,6,'Sitten hän sanoi kuninkaalle: "Totta oli se puhe, jonka minä kotimaahani sinusta ja sinun viisaudestasi kuulin.'),
(1678001,58,11,10,7,'Minä en uskonut, mitä sanottiin, ennenkuin itse tulin ja sain omin silmin nähdä; ja katso, ei puoltakaan oltu minulle kerrottu. Sinulla on paljon enemmän viisautta ja rikkautta, kuin minä olin kuullut huhuttavan.'),
(1678002,58,11,10,8,'Onnellisia ovat sinun miehesi, onnellisia nämä palvelijasi, jotka aina saavat olla sinun edessäsi ja kuulla sinun viisauttasi.'),
(1678003,58,11,10,9,'Kiitetty olkoon Herra, sinun Jumalasi, joka sinuun on niin mielistynyt, että on asettanut sinut Israelin valtaistuimelle. Sentähden, että Herra rakastaa Israelia ainiaan, hän on pannut sinut kuninkaaksi, tekemään sitä, mikä oikeus ja vanhurskaus on."'),
(1678004,58,11,10,10,'Ja hän antoi kuninkaalle sata kaksikymmentä talenttia kultaa, hyvin paljon hajuaineita ja kalliita kiviä. Niin paljon hajuaineita, kuin mitä Saban kuningatar antoi kuningas Salomolle, ei sinne ole sen jälkeen tullut.'),
(1678005,58,11,10,11,'Myöskin Hiiramin laivat, jotka kuljettivat kultaa Oofirista, toivat Oofirista hyvin paljon santelipuuta ja kalliita kiviä.'),
(1678006,58,11,10,12,'Ja kuningas teetti santelipuusta kalustoa Herran temppeliin ja kuninkaan linnaan ja kanteleita ja harppuja laulajille. Sellaista santelipuumäärää ei ole tuotu eikä nähty tähän päivään asti.'),
(1678007,58,11,10,13,'Kuningas Salomo taas antoi Saban kuningattarelle kaiken, mitä tämä halusi ja pyysi, ja sen lisäksi hän antoi muutakin kuninkaallisella anteliaisuudella. Sitten tämä lähti ja meni palvelijoineen omaan maahansa.'),
(1678008,58,11,10,14,'Sen kullan paino, mikä yhtenä vuotena tuli Salomolle, oli kuusisataa kuusikymmentä kuusi talenttia kultaa,'),
(1678009,58,11,10,15,'paitsi mitä tuli kauppamiehiltä ja kaupustelijain kaupanteosta ja kaikilta Erebin kuninkailta ja maan käskynhaltijoilta.'),
(1678010,58,11,10,16,'Ja kuningas Salomo teetti pakotetusta kullasta kaksisataa suurta kilpeä ja käytti jokaiseen kilpeen kuusisataa sekeliä kultaa;'),
(1678011,58,11,10,17,'ja pakotetusta kullasta kolmesataa pienempää kilpeä, ja käytti jokaiseen kilpeen kolme miinaa kultaa. Ja kuningas asetti ne Libanoninmetsä-taloon.'),
(1678012,58,11,10,18,'Vielä kuningas teetti suuren norsunluisen valtaistuimen ja päällysti sen puhdistetulla kullalla.'),
(1678013,58,11,10,19,'Valtaistuimessa oli kuusi porrasta, ja valtaistuimen selusta oli ylhäältä pyöreä. Istuimen kummallakin puolella oli käsinoja, ja kaksi leijonaa seisoi käsinojain vieressä.'),
(1678014,58,11,10,20,'Ja kaksitoista leijonaa seisoi siinä kuudella portaalla, kummallakin puolella. Senkaltaista ei ole tehty missään muussa valtakunnassa.'),
(1678015,58,11,10,21,'Ja kaikki kuningas Salomon juoma-astiat olivat kultaa, ja kaikki Libanoninmetsä-talon astiat olivat puhdasta kultaa. Hopeata ei siellä ollut, eikä sitä Salomon päivinä pidetty minkään arvoisena.'),
(1678016,58,11,10,22,'Kuninkaalla oli Tarsiin-laivasto merellä Hiiramin laivaston kanssa. Kerran kolmessa vuodessa Tarsiin-laivasto tuli ja toi kultaa ja hopeata, norsunluuta, apinoita ja riikinkukkoja.'),
(1678017,58,11,10,23,'Ja kuningas Salomo oli kaikkia maan kuninkaita suurempi rikkaudessa ja viisaudessa.'),
(1678018,58,11,10,24,'Ja kaikki maa pyrki näkemään Salomoa kuullakseen hänen viisauttaan, jonka Jumala oli antanut hänen sydämeensä.'),
(1678019,58,11,10,25,'Ja he toivat kukin lahjansa: hopea- ja kultakaluja, vaatteita, aseita, hajuaineita, hevosia ja muuleja, joka vuosi vuoden tarpeen.'),
(1678020,58,11,10,26,'Salomo kokosi sotavaunuja ja ratsumiehiä, niin että hänellä oli tuhannet neljätsadat sotavaunut ja kaksitoista tuhatta ratsumiestä; ne hän sijoitti vaunukaupunkeihin ja Jerusalemiin kuninkaan luo.'),
(1678021,58,11,10,27,'Ja kuningas toimitti niin, että Jerusalemissa oli hopeata kuin kiviä, ja setripuuta niin paljon kuin metsäviikunapuita Alankomaassa.'),
(1678022,58,11,10,28,'Ja hevoset, mitä Salomolla oli, tuotiin Egyptistä ja Kuvesta. Kuninkaan kauppiaat noutivat niitä Kuvesta maksua vastaan.'),
(1678023,58,11,10,29,'Egyptistä tuodut vaunut maksoivat kuusisataa hopeasekeliä ja hevonen sata viisikymmentä. Samoin tuotiin niitä heidän välityksellään kaikille heettiläisten ja aramilaisten kuninkaille.'),
(1678024,58,11,11,1,'Mutta kuningas Salomolla oli paitsi faraon tytärtä monta muuta muukalaista vaimoa, joita hän rakasti: mooabilaisia, ammonilaisia, edomilaisia, siidonilaisia ja heettiläisiä,'),
(1678025,58,11,11,2,'niiden kansain naisia, joista Herra oli sanonut israelilaisille: "Älkää yhtykö heihin, älköötkä hekään yhtykö teihin; he varmasti taivuttavat teidän sydämenne seuraamaan heidän jumaliansa". Näihin Salomo kiintyi rakkaudella.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678026,58,11,11,3,'Hänellä oli seitsemänsataa ruhtinaallista puolisoa ja kolmesataa sivuvaimoa; ja hänen vaimonsa taivuttivat hänen sydämensä.'),
(1678027,58,11,11,4,'Ja kun Salomo vanheni, taivuttivat hänen vaimonsa hänen sydämensä seuraamaan muita jumalia, niin ettei hän antautunut ehyin sydämin Herralle, Jumalallensa, niinkuin hänen isänsä Daavidin sydän oli ollut.'),
(1678028,58,11,11,5,'Niin Salomo lähti seuraamaan Astartea, siidonilaisten jumalatarta, ja Milkomia, ammonilais-iljetystä.'),
(1678029,58,11,11,6,'Ja Salomo teki sitä, mikä on pahaa Herran silmissä, eikä uskollisesti seurannut Herraa niinkuin hänen isänsä Daavid.'),
(1678030,58,11,11,7,'Silloin Salomo rakensi Kemokselle, mooabilais-iljetykselle, uhrikukkulan sille vuorelle, joka on itään päin Jerusalemista, ja samoin Moolokille, ammonilais-iljetykselle.'),
(1678031,58,11,11,8,'Näin hän teki kaikkien muukalaisten vaimojen mieliksi, jotka suitsuttivat ja uhrasivat jumalilleen.'),
(1678032,58,11,11,9,'Niin Herra vihastui Salomoon, koska hänen sydämensä oli kääntynyt pois Herrasta, Israelin Jumalasta, joka kahdesti oli ilmestynyt hänelle'),
(1678033,58,11,11,10,'ja nimenomaan kieltänyt häntä seuraamasta muita jumalia, ja koska hän ei ollut noudattanut Herran kieltoa.'),
(1678034,58,11,11,11,'Sentähden Herra sanoi Salomolle: "Koska sinun on käynyt näin, ja koska et ole pitänyt minun liittoani etkä noudattanut minun käskyjäni, jotka minä sinulle annoin, niin minä repäisen valtakunnan sinulta ja annan sen sinun palvelijallesi.'),
(1678035,58,11,11,12,'Mutta isäsi Daavidin tähden minä en tee tätä sinun päivinäsi; sinun poikasi kädestä minä sen repäisen.'),
(1678036,58,11,11,13,'Kuitenkaan en minä repäise koko valtakuntaa: yhden sukukunnan minä annan sinun pojallesi palvelijani Daavidin tähden ja Jerusalemin tähden, jonka minä olen valinnut."'),
(1678037,58,11,11,14,'Niin Herra nostatti Salomolle vastustajaksi edomilaisen Hadadin; tämä oli edomilaista kuningassukua.'),
(1678038,58,11,11,15,'Kun Daavid oli sodassa Edomin kanssa ja sotapäällikkö Jooab meni hautaamaan kaatuneita ja surmasi kaikki miehenpuolet Edomissa -'),
(1678039,58,11,11,16,'sillä Jooab ja koko Israel viipyi siellä kuusi kuukautta, kunnes olivat hävittäneet kaikki miehenpuolet Edomista -'),
(1678040,58,11,11,17,'pakeni Hadad ja hänen kanssaan muutamat edomilaiset miehet, hänen isänsä palvelijat, Egyptiin päin; Hadad oli vielä pieni poikanen.'),
(1678041,58,11,11,18,'He lähtivät liikkeelle Midianista ja tulivat Paaraniin. Ja he ottivat mukaansa miehiä Paaranista ja tulivat Egyptiin faraon, Egyptin kuninkaan, luo. Tämä antoi hänelle talon ja määräsi hänelle elatuksen ja antoi hänelle myös maata.'),
(1678042,58,11,11,19,'Ja Hadad pääsi faraon suureen suosioon, niin että hän antoi hänelle vaimoksi kälynsä, kuningatar Tahpeneen sisaren.'),
(1678043,58,11,11,20,'Tahpeneen sisar synnytti hänelle hänen poikansa Genubatin, ja Tahpenes vieroitti hänet faraon palatsissa; ja niin jäi Genubat faraon palatsiin, faraon lasten joukkoon.'),
(1678044,58,11,11,21,'Kun Hadad Egyptissä kuuli, että Daavid oli mennyt lepoon isiensä tykö ja että sotapäällikkö Jooab oli kuollut, sanoi Hadad faraolle: "Päästä minut menemään omaan maahani".'),
(1678045,58,11,11,22,'Mutta farao sanoi hänelle: "Mitä sinulta puuttuu minun luonani, koska haluat mennä omaan maahasi?" Hän vastasi: "Ei mitään, mutta päästä minut".'),
(1678046,58,11,11,23,'Ja Jumala nostatti Salomolle vastustajaksi Resonin, Eljadan pojan, joka oli paennut herransa Hadadeserin, Sooban kuninkaan, luota.'),
(1678047,58,11,11,24,'Tämä kokosi miehiä ympärilleen ja oli partiojoukon päällikkönä silloin, kun Daavid surmasi heitä. He menivät sitten Damaskoon, asettuivat sinne ja hallitsivat Damaskossa.'),
(1678048,58,11,11,25,'Ja hän oli Israelin vastustaja, niin kauan kuin Salomo eli, ja teki sille pahaa samoin kuin Hadadkin. Hän inhosi Israelia; ja hänestä tuli Aramin kuningas.'),
(1678049,58,11,11,26,'Myöskin Salomon palvelija Jerobeam, Nebatin poika, efraimilainen Seredasta, jonka äiti oli nimeltään Serua ja oli leskivaimo, kohotti kätensä kuningasta vastaan.'),
(1678050,58,11,11,27,'Hän joutui kohottamaan kätensä kuningasta vastaan seuraavalla tavalla. Salomo rakensi Milloa ja sulki siten aukon isänsä Daavidin kaupungissa.'),
(1678051,58,11,11,28,'Ja Jerobeam oli kelpo mies; ja kun Salomo näki, kuinka tämä nuori mies teki työtä, asetti hän hänet kaiken sen pakkotyön valvojaksi, mikä oli Joosefin heimon osalla.'),
(1678052,58,11,11,29,'Siihen aikaan tapahtui, kun Jerobeam kerran oli lähtenyt Jerusalemista, että siilolainen Ahia, profeetta, kohtasi hänet tiellä. Tämä oli puettuna uuteen vaippaan, ja he olivat kahdenkesken kedolla.'),
(1678053,58,11,11,30,'Silloin Ahia tarttui siihen uuteen vaippaan, joka hänellä oli yllään, ja repäisi sen kahdeksitoista kappaleeksi'),
(1678054,58,11,11,31,'ja sanoi Jerobeamille: "Ota itsellesi kymmenen kappaletta, sillä näin sanoo Herra, Israelin Jumala: Katso, minä repäisen valtakunnan Salomon kädestä ja annan kymmenen sukukuntaa sinulle.'),
(1678055,58,11,11,32,'Yksi sukukunta jääköön hänelle minun palvelijani Daavidin tähden ja Jerusalemin kaupungin tähden, jonka minä olen valinnut kaikista Israelin sukukunnista.'),
(1678056,58,11,11,33,'Näin on tapahtuva, koska he ovat hyljänneet minut ja kumartaneet Astartea, siidonilaisten jumalatarta, ja Kemosta, Mooabin jumalaa, ja Milkomia, ammonilaisten jumalaa, eivätkä ole vaeltaneet minun teitäni eivätkä tehneet sitä, mikä on oikein minun silmissäni, eivätkä noudattaneet minun käskyjäni ja oikeuksiani niinkuin Salomon isä Daavid.'),
(1678057,58,11,11,34,'Kuitenkaan en minä ota hänen kädestään koko valtakuntaa, vaan annan hänen olla ruhtinaana koko elinaikansa palvelijani Daavidin tähden, jonka minä valitsin, koska hän noudatti minun käskyjäni ja säädöksiäni.'),
(1678058,58,11,11,35,'Mutta hänen poikansa kädestä minä otan kuninkuuden ja annan sen sinulle, nimittäin ne kymmenen sukukuntaa,'),
(1678059,58,11,11,36,'ja hänen pojallensa minä annan yhden sukukunnan, että minun palvelijallani Daavidilla aina olisi lamppu palamassa minun edessäni Jerusalemissa, siinä kaupungissa, jonka minä olen itselleni valinnut, asettaakseni nimeni siihen.'),
(1678060,58,11,11,37,'Mutta sinut minä otan, ja sinä saat hallittavaksesi kaikki, joita haluat; sinusta tulee Israelin kuningas.'),
(1678061,58,11,11,38,'Jos sinä olet kuuliainen kaikessa, mitä minä käsken sinun tehdä, ja vaellat minun tietäni ja teet sitä, mikä on oikein minun silmissäni, ja noudatat minun säädöksiäni ja käskyjäni, niinkuin minun palvelijani Daavid teki, niin minä olen sinun kanssasi ja rakennan sinulle pysyväisen huoneen, niinkuin minä Daavidille rakensin, ja annan Israelin sinulle.'),
(1678062,58,11,11,39,'Siitä syystä minä nöyryytän Daavidin jälkeläiset, en kuitenkaan ainiaaksi."'),
(1678063,58,11,11,40,'Salomo koetti saada surmatuksi Jerobeamin; mutta Jerobeam lähti ja pakeni Egyptiin, Suusakin, Egyptin kuninkaan, luo. Ja hän oli Egyptissä Salomon kuolemaan asti.'),
(1678064,58,11,11,41,'Mitä muuta Salomosta on kerrottavaa, kaikesta, mitä hän teki, ja hänen viisaudestansa, se on kirjoitettuna Salomon historiassa.'),
(1678065,58,11,11,42,'Ja aika, minkä Salomo hallitsi Jerusalemissa koko Israelia, oli neljäkymmentä vuotta.'),
(1678066,58,11,11,43,'Sitten Salomo meni lepoon isiensä tykö ja hänet haudattiin isänsä Daavidin kaupunkiin. Ja hänen poikansa Rehabeam tuli kuninkaaksi hänen sijaansa.'),
(1678067,58,11,12,1,'Rehabeam meni Sikemiin, sillä koko Israel oli tullut Sikemiin tekemään häntä kuninkaaksi.'),
(1678068,58,11,12,2,'Kun Jerobeam, Nebatin poika, kuuli sen - hän oli vielä Egyptissä, jonne hän oli paennut kuningas Salomoa, ja Jerobeam asui Egyptissä,'),
(1678069,58,11,12,3,'mutta he lähettivät kutsumaan hänet - niin Jerobeam ja koko Israelin seurakunta tuli saapuville, ja he puhuivat Rehabeamille sanoen:'),
(1678070,58,11,12,4,'"Sinun isäsi teki meidän ikeemme raskaaksi; mutta huojenna sinä nyt se kova työ, jota isäsi teetti, ja se raskas ies, jonka hän pani meidän niskaamme, niin me palvelemme sinua".'),
(1678071,58,11,12,5,'Hän vastasi heille: "Menkää ja odottakaa kolme päivää ja tulkaa sitten takaisin minun tyköni". Ja kansa meni.'),
(1678072,58,11,12,6,'Kuningas Rehabeam neuvotteli vanhain kanssa, jotka olivat palvelleet hänen isäänsä Salomoa, kun tämä vielä eli, ja kysyi: "Kuinka te neuvotte vastaamaan tälle kansalle?"'),
(1678073,58,11,12,7,'He vastasivat hänelle ja sanoivat: "Jos sinä tänä päivänä rupeat tämän kansan palvelijaksi ja palvelet heitä, jos kuulet heitä ja puhut heille hyviä sanoja, niin he ovat sinun palvelijoitasi kaiken elinaikasi".'),
(1678074,58,11,12,8,'Mutta hän hylkäsi tämän neuvon, jonka vanhat hänelle antoivat, ja neuvotteli nuorten miesten kanssa, jotka olivat kasvaneet hänen kanssaan ja jotka palvelivat häntä.'),
(1678075,58,11,12,9,'Hän kysyi heiltä: "Kuinka te neuvotte meitä vastaamaan tälle kansalle, joka on puhunut minulle sanoen: ''Huojenna se ies, jonka sinun isäsi on pannut meidän niskaamme''?"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678076,58,11,12,10,'Niin nuoret miehet, jotka olivat kasvaneet hänen kanssaan, vastasivat hänelle sanoen: "Sano näin tälle kansalle, joka on puhunut sinulle sanoen: ''Sinun isäsi teki meidän ikeemme raskaaksi, mutta huojenna sinä sitä meiltä'' - puhu heille näin: ''Minun pikkusormeni on paksumpi kuin minun isäni lantio.'),
(1678077,58,11,12,11,'Jos siis isäni on sälyttänyt teidän selkäänne raskaan ikeen, niin minä teen teidän ikeenne vielä raskaammaksi; jos isäni on kurittanut teitä raipoilla, niin minä kuritan teitä piikkiruoskilla.''"'),
(1678078,58,11,12,12,'Niin Jerobeam ja kaikki kansa tuli Rehabeamin tykö kolmantena päivänä, niinkuin kuningas oli käskenyt sanoen: "Tulkaa takaisin minun tyköni kolmantena päivänä".'),
(1678079,58,11,12,13,'Ja kuningas antoi kansalle kovan vastauksen, hyljäten sen neuvon, jonka vanhat olivat hänelle antaneet.'),
(1678080,58,11,12,14,'Ja hän puhui heille nuorten miesten neuvon mukaan, sanoen: "Jos minun isäni on tehnyt teidän ikeenne raskaaksi, niin minä teen ikeenne vielä raskaammaksi; jos minun isäni on kurittanut teitä raipoilla, niin minä kuritan teitä piikkiruoskilla".'),
(1678081,58,11,12,15,'Kuningas ei siis kuullut kansaa; sillä Herra sen niin salli täyttääkseen sanansa, jonka Herra oli puhunut Jerobeamille, Nebatin pojalle, siilolaisen Ahian kautta.'),
(1678082,58,11,12,16,'Kun koko Israel huomasi, ettei kuningas heitä kuullut, vastasi kansa kuninkaalle näin: "Mitä osaa meillä on Daavidiin? Ei meillä ole perintöosaa Iisain poikaan. Majoillesi, Israel! Valvo nyt huonettasi, Daavid!" Ja Israel meni majoillensa.'),
(1678083,58,11,12,17,'Niin Rehabeam tuli ainoastaan niiden israelilaisten kuninkaaksi, jotka asuivat Juudan kaupungeissa.'),
(1678084,58,11,12,18,'Ja kun kuningas Rehabeam lähetti matkaan verotöiden valvojan Adoramin, kivitti koko Israel hänet kuoliaaksi. Silloin kuningas Rehabeam nousi nopeasti vaunuihinsa ja pakeni Jerusalemiin.'),
(1678085,58,11,12,19,'Näin Israel luopui Daavidin suvusta, aina tähän päivään asti.'),
(1678086,58,11,12,20,'Mutta kun koko Israel kuuli, että Jerobeam oli tullut takaisin, lähettivät he kutsumaan hänet kansankokoukseen ja tekivät hänet koko Israelin kuninkaaksi. Daavidin sukua ei seurannut kukaan muu kuin Juudan sukukunta yksin.'),
(1678087,58,11,12,21,'Ja kun Rehabeam tuli Jerusalemiin, kokosi hän koko Juudan heimon ja Benjaminin sukukunnan, satakahdeksankymmentä tuhatta sotakuntoista valiomiestä, sotimaan Israelin heimoa vastaan ja palauttamaan kuninkuutta Rehabeamille Salomon pojalle.'),
(1678088,58,11,12,22,'Mutta Jumalan miehelle Semajalle tuli tämä Jumalan sana:'),
(1678089,58,11,12,23,'"Sano Rehabeamille, Salomon pojalle, Juudan kuninkaalle, ja koko Juudan ja Benjaminin heimoille sekä muulle kansalle näin:'),
(1678090,58,11,12,24,'''Näin sanoo Herra: Älkää menkö sotimaan veljiänne, israelilaisia, vastaan. Palatkaa kukin kotiinne, sillä minä olen sallinut tämän tapahtua.''" Niin he kuulivat Herran sanaa, kääntyivät takaisin ja menivät pois Herran sanan mukaan.'),
(1678091,58,11,12,25,'Mutta Jerobeam linnoitti Sikemin Efraimin vuoristossa ja asettui sinne. Sitten hän lähti sieltä ja linnoitti Penuelin.'),
(1678092,58,11,12,26,'Ja Jerobeam ajatteli sydämessänsä: "Nyt valtakunta joutuu takaisin Daavidin suvulle.'),
(1678093,58,11,12,27,'Jos tämä kansa menee ja uhraa teurasuhreja Herran temppelissä Jerusalemissa, niin tämän kansan sydän kääntyy jälleen heidän herransa Rehabeamin, Juudan kuninkaan, puolelle; ja he tappavat minut ja palaavat takaisin Rehabeamin, Juudan kuninkaan, luo."'),
(1678094,58,11,12,28,'Mietittyään asiaa kuningas teetti kaksi kultaista vasikkaa ja sanoi heille: "Te olette jo tarpeeksi kauan kulkeneet Jerusalemissa. Katso, Israel, tässä on sinun Jumalasi, joka on johdattanut sinut Egyptin maasta."'),
(1678095,58,11,12,29,'Ja hän pystytti toisen Beeteliin, ja toisen hän asetti Daaniin.'),
(1678096,58,11,12,30,'Ja tämä koitui synniksi. Ja kansa kulki sen toisen kuvan luo Daaniin saakka.'),
(1678097,58,11,12,31,'Hän rakensi myös uhrikukkulatemppeleitä ja teki kansan keskuudesta papeiksi kaikenkaltaisia miehiä, jotka eivät olleet leeviläisiä.'),
(1678098,58,11,12,32,'Ja Jerobeam laittoi juhlan kahdeksannessa kuussa, kuukauden viidentenätoista päivänä, sen juhlan kaltaisen, jota vietetään Juudassa, ja nousi silloin itse alttarille; niin hän teki Beetelissä ja uhrasi niille vasikoille, jotka hän oli teettänyt. Ja tekemiänsä uhrikukkulapappeja hän asetti virkaan Beeteliin.'),
(1678099,58,11,12,33,'Hän nousi sille alttarille, jonka oli teettänyt Beeteliin, viidentenätoista päivänä kahdeksatta kuuta, jonka kuukauden hän oli omasta päästään keksinyt. Hän laittoi silloin juhlan israelilaisille ja nousi alttarille polttamaan uhreja.'),
(1678100,58,11,13,1,'Ja katso, Juudasta Beeteliin tuli Herran käskystä Jumalan mies, juuri kun Jerobeam seisoi alttarin ääressä polttamassa uhreja.'),
(1678101,58,11,13,2,'Ja hän huusi alttaria kohti Herran käskystä ja sanoi: "Alttari, alttari, näin sanoo Herra: Katso, Daavidin suvusta on syntyvä poika, nimeltä Joosia. Hän on teurastava sinun päälläsi uhrikukkulapapit, jotka polttavat uhreja sinun päälläsi, ja sinun päälläsi tullaan polttamaan ihmisten luita."'),
(1678102,58,11,13,3,'Ja hän antoi sinä päivänä ennusmerkin, sanoen: "Ennusmerkki siitä, että Herra on puhunut, on tämä: alttari halkeaa, ja tuhka, joka on sen päällä, hajoaa".'),
(1678103,58,11,13,4,'Kun kuningas Jerobeam kuuli Jumalan miehen sanan, jonka hän huusi alttaria kohti Beetelissä, ojensi hän kätensä alttarilta ja sanoi: "Ottakaa hänet kiinni". Silloin hänen kätensä, jonka hän oli ojentanut häntä vastaan, kuivettui, eikä hän enää voinut vetää sitä takaisin.'),
(1678104,58,11,13,5,'Ja alttari halkesi ja tuhka hajosi alttarilta, niinkuin Jumalan mies Herran käskystä oli ennusmerkin antanut.'),
(1678105,58,11,13,6,'Silloin kuningas puhkesi puhumaan ja sanoi Jumalan miehelle: "Lepytä Herraa, Jumalaasi, ja rukoile minun puolestani, että minä voisin vetää käteni takaisin". Ja Jumalan mies lepytti Herraa; niin kuningas voi vetää kätensä takaisin, ja se tuli entiselleen.'),
(1678106,58,11,13,7,'Ja kuningas puhui Jumalan miehelle: "Tule minun kanssani kotiini virkistämään itseäsi; minä annan sinulle lahjan".'),
(1678107,58,11,13,8,'Mutta Jumalan mies sanoi kuninkaalle: "Vaikka antaisit minulle puolet linnastasi, en minä tulisi sinun kanssasi. Tässä paikassa en minä syö leipää enkä juo vettä.'),
(1678108,58,11,13,9,'Sillä niin käski minua Herra sanallansa, sanoen: Älä syö leipää, älä juo vettä äläkä palaa samaa tietä, jota olet tullut."'),
(1678109,58,11,13,10,'Ja hän meni toista tietä eikä palannut samaa tietä, jota oli tullut Beeteliin.'),
(1678110,58,11,13,11,'Mutta Beetelissä asui vanha profeetta; ja hänen poikansa tuli ja kertoi hänelle kaiken, mitä Jumalan mies sinä päivänä oli tehnyt Beetelissä ja mitä hän oli puhunut kuninkaalle. Kun he olivat kertoneet sen isällensä,'),
(1678111,58,11,13,12,'kysyi heidän isänsä heiltä, mitä tietä hän oli mennyt. Ja hänen poikansa olivat nähneet, mitä tietä Juudasta tullut Jumalan mies oli lähtenyt.'),
(1678112,58,11,13,13,'Silloin hän sanoi pojilleen: "Satuloikaa minulle aasi". Ja kun he olivat satuloineet hänelle aasin, istui hän sen selkään'),
(1678113,58,11,13,14,'ja lähti Jumalan miehen jälkeen ja tapasi hänet istumassa tammen alla. Ja hän kysyi häneltä: "Sinäkö olet se Juudasta tullut Jumalan mies?" Hän vastasi: "Minä".'),
(1678114,58,11,13,15,'Hän sanoi hänelle: "Tule kanssani minun kotiini syömään".'),
(1678115,58,11,13,16,'Hän vastasi: "En voi palata enkä tulla sinun kanssasi, en voi syödä leipää enkä juoda vettä sinun kanssasi tässä paikassa,'),
(1678116,58,11,13,17,'sillä minulle on tullut sana, Herran sana: ''Älä syö leipää äläkä juo vettä siellä, älä myöskään tule takaisin samaa tietä, jota olet mennyt''".'),
(1678117,58,11,13,18,'Hän sanoi hänelle: "Minäkin olen profeetta niinkuin sinä, ja enkeli on puhunut minulle Herran käskystä, sanoen: ''Vie hänet kanssasi takaisin kotiisi syömään leipää ja juomaan vettä''". Mutta sen hän valhetteli hänelle.'),
(1678118,58,11,13,19,'Niin tämä palasi hänen kanssansa ja söi leipää ja joi vettä hänen kodissaan.'),
(1678119,58,11,13,20,'Mutta heidän istuessaan pöydässä tuli Herran sana profeetalle, joka oli tuonut hänet takaisin.'),
(1678120,58,11,13,21,'Ja hän huusi Juudasta tulleelle Jumalan miehelle, sanoen: "Näin sanoo Herra: Koska sinä olet niskoitellut Herran käskyä vastaan etkä ole noudattanut sitä määräystä, jonka Herra, sinun Jumalasi, sinulle antoi,'),
(1678121,58,11,13,22,'vaan olet palannut syömään leipää ja juomaan vettä siinä paikassa, josta sinulle oli sanottu: ''Älä siellä syö leipää äläkä juo vettä'', niin älköön sinun ruumiisi tulko isiesi hautaan".'),
(1678122,58,11,13,23,'Ja kun hän oli syönyt leipää ja juonut, satuloi hän aasin profeetalle, jonka hän oli tuonut takaisin.'),
(1678123,58,11,13,24,'Kun tämä oli lähtenyt, kohtasi hänet leijona tiellä ja tappoi hänet. Ja hänen ruumiinsa oli pitkänään tiellä, ja aasi seisoi hänen vieressään, ja leijona seisoi ruumiin ääressä.'),
(1678124,58,11,13,25,'Ja katso, siitä kulki ohitse miehiä, ja he näkivät ruumiin pitkänään tiellä ja leijonan seisomassa ruumiin ääressä. He menivät ja puhuivat siitä kaupungissa, jossa vanha profeetta asui.'),
(1678125,58,11,13,26,'Kun profeetta, joka oli palauttanut hänet tieltä, kuuli sen, sanoi hän: "Se on se Jumalan mies, joka niskoitteli Herran käskyä vastaan. Sentähden Herra on antanut hänet leijonalle, ja se on ruhjonut ja tappanut hänet sen Herran sanan mukaan, jonka hän oli hänelle puhunut."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678126,58,11,13,27,'Ja hän puhui pojilleen, sanoen: "Satuloikaa minulle aasi". Ja he satuloivat.'),
(1678127,58,11,13,28,'Ja hän lähti ja löysi hänen ruumiinsa, joka oli pitkänään tiellä, ja aasin ja leijonan seisomasta ruumiin ääressä; leijona ei ollut syönyt ruumista eikä myöskään ruhjonut aasia.'),
(1678128,58,11,13,29,'Niin profeetta otti Jumalan miehen ruumiin, pani sen aasin selkään ja vei sen takaisin; ja vanha profeetta tuli kaupunkiin pitämään valittajaisia ja hautaamaan häntä.'),
(1678129,58,11,13,30,'Ja hän pani ruumiin omaan hautaansa; ja he pitivät valittajaiset hänelle ja huusivat: "Voi, minun veljeni!"'),
(1678130,58,11,13,31,'Ja kun hän oli haudannut hänet, sanoi hän pojilleen näin: "Kun minä kuolen, niin haudatkaa minut siihen hautaan, johon Jumalan mies on haudattu, ja pankaa minun luuni hänen luittensa viereen.'),
(1678131,58,11,13,32,'Sillä toteutuva on sana, jonka hän Herran käskystä huusi Beetelissä olevaa alttaria vastaan ja kaikkia Samarian kaupungeissa olevia uhrikukkulatemppeleitä vastaan."'),
(1678132,58,11,13,33,'Ei tämänkään jälkeen Jerobeam kääntynyt pahalta tieltään, vaan teki taas uhrikukkulapapeiksi kaikenkaltaisia miehiä kansan keskuudesta. Kuka vain halusi, sen hän vihki papin virkaan, ja niin siitä tuli uhrikukkulapappi.'),
(1678133,58,11,13,34,'Ja tällä tavalla tämä tuli synniksi Jerobeamin suvulle ja syyksi siihen, että se hävitettiin ja hukutettiin maan päältä.'),
(1678134,58,11,14,1,'Siihen aikaan sairastui Abia, Jerobeamin poika.'),
(1678135,58,11,14,2,'Niin Jerobeam sanoi vaimollensa: "Nouse ja pukeudu niin, ettei sinua tunneta Jerobeamin vaimoksi, ja mene Siiloon. Katso, siellä on profeetta Ahia, joka ilmoitti, että minusta on tuleva tämän kansan kuningas.'),
(1678136,58,11,14,3,'Ja ota mukaasi kymmenen leipää sekä pieniä leivoksia ja ruukullinen hunajaa ja mene hänen luoksensa. Hän ilmaisee sinulle, kuinka pojan käy."'),
(1678137,58,11,14,4,'Jerobeamin vaimo teki niin: hän nousi ja meni Siiloon ja tuli Ahian taloon. Ja Ahia ei voinut nähdä, sillä hänellä oli vanhuuttaan kaihi silmissä.'),
(1678138,58,11,14,5,'Mutta Herra oli sanonut Ahialle: "Katso, Jerobeamin vaimo tulee sinulta kysymään pojastaan, sillä hän on sairaana. Niin ja niin on sinun puhuttava hänelle." Ja kun hän tuli tekeytyen tuntemattomaksi,'),
(1678139,58,11,14,6,'ja kun Ahia kuuli hänen askeleensa hänen tullessaan ovessa, sanoi hän: "Tule sisään, Jerobeamin vaimo; miksi sinä tekeydyt tuntemattomaksi? Minä olen saanut ilmoittaakseni sinulle kovan sanoman.'),
(1678140,58,11,14,7,'Mene ja sano Jerobeamille: ''Näin sanoo Herra, Israelin Jumala: Minä olen korottanut sinut kansan seasta ja asettanut sinut kansani Israelin ruhtinaaksi'),
(1678141,58,11,14,8,'ja reväissyt valtakunnan Daavidin suvulta ja antanut sen sinulle. Mutta sinä et ole ollut niinkuin minun palvelijani Daavid, joka noudatti minun käskyjäni ja seurasi minua kaikesta sydämestänsä, niin että hän teki ainoastaan sitä, mikä oli oikeata minun silmissäni.'),
(1678142,58,11,14,9,'Vaan sinä olet tehnyt enemmän pahaa kuin kaikki sinun edeltäjäsi: sinä olet mennyt ja tehnyt itsellesi muita jumalia, valettuja kuvia, ja olet vihoittanut minut ja heittänyt minut selkäsi taakse.'),
(1678143,58,11,14,10,'Katso, sentähden minä annan onnettomuuden kohdata Jerobeamin sukua ja hävitän Israelista Jerobeamin miespuoliset jälkeläiset, kaikki tyynni, ja minä lakaisen pois Jerobeamin suvun, niinkuin saasta lakaistaan, kunnes siitä on tullut loppu.'),
(1678144,58,11,14,11,'Joka Jerobeamin jälkeläisistä kuolee kaupungissa, sen koirat syövät, ja joka kuolee kedolle, sen syövät taivaan linnut. Sillä Herra on puhunut.'''),
(1678145,58,11,14,12,'Niin nouse nyt ja mene kotiisi. Kun sinun jalkasi astuu kaupunkiin, kuolee lapsi.'),
(1678146,58,11,14,13,'Ja koko Israel on pitävä valittajaiset hänelle, ja hänet haudataan. Sillä Jerobeamin jälkeläisistä on hän yksin tuleva hautaan, koska Jerobeamin suvussa on vain hänessä havaittu jotakin Herralle, Israelin Jumalalle, otollista.'),
(1678147,58,11,14,14,'Mutta Herra on herättävä itsellensä Israeliin kuninkaan, joka hävittää Jerobeamin suvun. Se on se päivä; ja mitä sitten?'),
(1678148,58,11,14,15,'Herra on lyövä Israelia, niin että se tulee ruovon kaltaiseksi, joka häilyy vedessä. Ja hän kiskaisee Israelin irti tästä hyvästä maasta, jonka hän on antanut heidän isillensä, ja hajottaa heidät tuolle puolelle Eufrat-virran, koska he ovat tehneet itsellensä asera-karsikkoja ja siten vihoittaneet Herran.'),
(1678149,58,11,14,16,'Ja hän antaa alttiiksi Israelin niiden syntien tähden, jotka Jerobeam on tehnyt ja joilla hän on saattanut Israelin tekemään syntiä."'),
(1678150,58,11,14,17,'Niin Jerobeamin vaimo nousi, meni matkaansa ja tuli Tirsaan. Juuri kun hän tuli huoneen kynnykselle, kuoli poika.'),
(1678151,58,11,14,18,'Ja hänet haudattiin, ja koko Israel piti valittajaiset hänelle, sen sanan mukaan, jonka Herra oli puhunut palvelijansa, profeetta Ahian, kautta.'),
(1678152,58,11,14,19,'Mitä muuta on kerrottavaa Jerobeamista, kuinka hän soti ja kuinka hän hallitsi, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678153,58,11,14,20,'Ja aika, minkä Jerobeam hallitsi, oli kaksikymmentä kaksi vuotta. Sitten hän meni lepoon isiensä tykö. Ja hänen poikansa Naadab tuli kuninkaaksi hänen sijaansa.'),
(1678154,58,11,14,21,'Mutta Rehabeam, Salomon poika, tuli Juudan kuninkaaksi. Neljänkymmenen yhden vuoden vanha oli Rehabeam tullessaan kuninkaaksi, ja hän hallitsi seitsemäntoista vuotta Jerusalemissa, siinä kaupungissa, jonka Herra oli valinnut kaikista Israelin sukukunnista, asettaakseen nimensä siihen. Hänen äitinsä oli nimeltään Naema, ammonilainen.'),
(1678155,58,11,14,22,'Ja Juuda teki sitä, mikä oli pahaa Herran silmissä. Synneillänsä, joita he tekivät, he vihoittivat Herraa paljon enemmän, kuin heidän isänsä olivat tehneet.'),
(1678156,58,11,14,23,'Hekin tekivät itsellensä uhrikukkuloita, patsaita ja asera-karsikkoja kaikille korkeille kukkuloille ja jokaisen viheriän puun alle.'),
(1678157,58,11,14,24,'Ja maassa oli myöskin haureellisia pyhäkköpoikia. He jäljittelivät niiden kansojen kaikkia kauhistavia tekoja, jotka Herra oli karkoittanut israelilaisten tieltä.'),
(1678158,58,11,14,25,'Mutta kuningas Rehabeamin viidentenä hallitusvuotena hyökkäsi Suusak, Egyptin kuningas, Jerusalemin kimppuun.'),
(1678159,58,11,14,26,'Ja hän otti Herran temppelin aarteet ja kuninkaan palatsin aarteet; otti kaikki tyynni. Hän otti myös kaikki ne kultakilvet, jotka Salomo oli teettänyt.'),
(1678160,58,11,14,27,'Kuningas Rehabeam teetti niiden sijaan vaskikilvet ja jätti ne henkivartijain päälliköiden haltuun, jotka vartioivat kuninkaan linnan ovella.'),
(1678161,58,11,14,28,'Ja niin usein kuin kuningas meni Herran temppeliin, kantoivat henkivartijat niitä ja veivät ne sitten takaisin henkivartijain huoneeseen.'),
(1678162,58,11,14,29,'Mitä muuta on kerrottavaa Rehabeamista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.'),
(1678163,58,11,14,30,'Mutta Rehabeam ja Jerobeam olivat kaiken aikaa sodassa keskenään.'),
(1678164,58,11,14,31,'Sitten Rehabeam meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Hänen äitinsä oli nimeltään Naema, ammonilainen. Ja hänen poikansa Abiam tuli kuninkaaksi hänen sijaansa.'),
(1678165,58,11,15,1,'Ja kuningas Jerobeamin, Nebatin pojan, kahdeksantenatoista hallitusvuotena tuli Abiam Juudan kuninkaaksi.'),
(1678166,58,11,15,2,'Hän hallitsi kolme vuotta Jerusalemissa. Hänen äitinsä oli nimeltään Maaka, Abisalomin tytär.'),
(1678167,58,11,15,3,'Ja hän vaelsi kaikissa isänsä synneissä, joita tämä oli tehnyt ennen häntä, eikä hänen sydämensä ollut ehyesti antautunut Herralle, hänen Jumalallensa, niinkuin hänen isänsä Daavidin sydän oli ollut.'),
(1678168,58,11,15,4,'Mutta Daavidin tähden Herra, hänen Jumalansa, antoi hänen lamppunsa palaa Jerusalemissa, korottamalla hänen jälkeläisekseen hänen poikansa ja pitämällä Jerusalemia pystyssä -'),
(1678169,58,11,15,5,'koska Daavid oli tehnyt sitä, mikä on oikein Herran silmissä, eikä koko elinaikanaan ollut poikennut mistään, mitä hän on käskenyt, paitsi heettiläisen Uurian asiassa.'),
(1678170,58,11,15,6,'Ja Abiam oli koko elinaikansa sodassa Jerobeamin kanssa.'),
(1678171,58,11,15,7,'Mitä muuta on kerrottavaa Abiamista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa. Mutta Abiam ja Jerobeam olivat sodassa keskenään.'),
(1678172,58,11,15,8,'Ja Abiam meni lepoon isiensä tykö, ja hänet haudattiin Daavidin kaupunkiin. Ja Aasa, hänen poikansa, tuli kuninkaaksi hänen sijaansa.'),
(1678173,58,11,15,9,'Israelin kuninkaan Jerobeamin kahdentenakymmenentenä hallitusvuotena tuli Aasa Juudan kuninkaaksi.'),
(1678174,58,11,15,10,'Hän hallitsi neljäkymmentä yksi vuotta Jerusalemissa. Hänen äitinsä oli nimeltään Maaka, Abisalomin tytär.'),
(1678175,58,11,15,11,'Ja Aasa teki sitä, mikä oli oikein Herran silmissä, niinkuin hänen isänsä Daavid,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678176,58,11,15,12,'ja toimitti haureelliset pyhäkköpojat pois maasta ja hävitti kaikki ne kivijumalat, jotka hänen isänsä olivat tehneet.'),
(1678177,58,11,15,13,'Jopa hän erotti äitinsä Maakan kuningattaren arvosta, koska tämä oli pystyttänyt inhotuksen Aseralle; ja Aasa kukisti inhotuksen ja poltti sen Kidronin laaksossa.'),
(1678178,58,11,15,14,'Mutta uhrikukkulat eivät hävinneet. Kuitenkin oli Aasan sydän ehyesti antautunut Herralle, niin kauan kuin hän eli.'),
(1678179,58,11,15,15,'Ja hän vei Herran temppeliin isänsä pyhät lahjat ja omat pyhät lahjansa: hopeata, kultaa ja kaluja.'),
(1678180,58,11,15,16,'Mutta Aasa ja Israelin kuningas Baesa olivat kaiken aikansa sodassa keskenään.'),
(1678181,58,11,15,17,'Baesa, Israelin kuningas, lähti Juudaa vastaan ja linnoitti Raaman, estääkseen ketään pääsemästä Aasan, Juudan kuninkaan, luota tai hänen luokseen.'),
(1678182,58,11,15,18,'Ja Aasa otti kaiken hopean ja kullan, mikä vielä oli jäljellä Herran temppelin ja kuninkaan linnan aarrekammioissa, ja antoi sen palvelijainsa haltuun; ja kuningas Aasa lähetti heidät Benhadadin, Tabrimmonin pojan, Hesjonin pojanpojan, Aramin kuninkaan, luo, joka asui Damaskossa, ja käski sanoa hänelle:'),
(1678183,58,11,15,19,'"Onhan liitto meidän välillämme, minun ja sinun, niinkuin oli minun isäni ja sinun isäsi välillä. Katso, minä lähetän sinulle hopeata ja kultaa lahjaksi; mene ja riko Baesan, Israelin kuninkaan, kanssa tekemäsi liitto, että hän lähtisi pois minun kimpustani."'),
(1678184,58,11,15,20,'Niin Benhadad kuuli kuningas Aasaa ja lähetti sotajoukkojensa päälliköt Israelin kaupunkeja vastaan ja valtasi Iijonin, Daanin, Aabel-Beet-Maakan ja koko Kinnerotin ynnä koko Naftalin maan.'),
(1678185,58,11,15,21,'Kun Baesa kuuli sen, lakkasi hän linnoittamasta Raamaa ja jäi Tirsaan.'),
(1678186,58,11,15,22,'Mutta kuningas Aasa kutsui kokoon kaiken Juudan, vapauttamatta ketään. Ja he veivät pois kivet ja puut, joilla Baesa oli linnoittanut Raamaa. Niillä kuningas Aasa linnoitti Geban, joka on Benjaminissa, ja Mispan.'),
(1678187,58,11,15,23,'Mitä muuta kaikkea on kerrottavaa Aasasta, kaikista hänen urotöistään, kaikesta, mitä hän teki, ja kaupungeista, jotka hän rakensi, se on kirjoitettuna Juudan kuningasten aikakirjassa. Mutta vanhuutensa päivinä hän oli sairas jaloistaan.'),
(1678188,58,11,15,24,'Sitten Aasa meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen hänen isänsä Daavidin kaupunkiin. Ja hänen poikansa Joosafat tuli kuninkaaksi hänen sijaansa.'),
(1678189,58,11,15,25,'Ja Naadab, Jerobeamin poika, tuli Israelin kuninkaaksi Aasan, Juudan kuninkaan, toisena hallitusvuotena, ja hän hallitsi Israelia kaksi vuotta.'),
(1678190,58,11,15,26,'Hän teki sitä, mikä on pahaa Herran silmissä, ja vaelsi isänsä teitä ja hänen synnissänsä, jolla hän oli saattanut Israelin tekemään syntiä.'),
(1678191,58,11,15,27,'Mutta Baesa, Ahian poika, Isaskarin sukua, teki salaliiton häntä vastaan, ja Baesa surmasi hänet Gibbetonin luona, joka oli filistealaisilla; sillä Naadab ja koko Israel piirittivät Gibbetonia.'),
(1678192,58,11,15,28,'Baesa tappoi hänet Juudan kuninkaan Aasan kolmantena hallitusvuotena ja tuli kuninkaaksi hänen sijaansa.'),
(1678193,58,11,15,29,'Kuninkaaksi tultuaan hän surmasi koko Jerobeamin suvun jättämättä Jerobeamin jälkeläisistä eloon ainoatakaan henkeä: hän hävitti heidät Herran sanan mukaan, jonka hän oli puhunut palvelijansa, siilolaisen Ahian, kautta -'),
(1678194,58,11,15,30,'niiden syntien tähden, jotka Jerobeam oli tehnyt ja joilla hän oli saattanut Israelin tekemään syntiä, siten vihoittaen Herran, Israelin Jumalan.'),
(1678195,58,11,15,31,'Mitä muuta on kerrottavaa Naadabista ja kaikesta, mitä hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678196,58,11,15,32,'Mutta Aasa ja Israelin kuningas Baesa olivat kaiken aikansa sodassa keskenään.'),
(1678197,58,11,15,33,'Aasan, Juudan kuninkaan, kolmantena hallitusvuotena tuli Baesa, Ahian poika, koko Israelin kuninkaaksi Tirsassa, ja hän hallitsi kaksikymmentä neljä vuotta.'),
(1678198,58,11,15,34,'Hän teki sitä, mikä on pahaa Herran silmissä, ja vaelsi Jerobeamin teitä ja hänen synneissänsä, joilla hän oli saattanut Israelin tekemään syntiä.'),
(1678199,58,11,16,1,'Ja Jeehulle, Hananin pojalle, tuli tämä Herran sana Baesaa vastaan:'),
(1678200,58,11,16,2,'"Sentähden, että sinä, vaikka minä olen korottanut sinut tomusta ja pannut sinut kansani Israelin ruhtinaaksi, olet vaeltanut Jerobeamin teitä ja saattanut minun kansani Israelin tekemään syntiä, niin että he ovat vihoittaneet minut synneillänsä,'),
(1678201,58,11,16,3,'katso, minä lakaisen pois Baesan ja hänen sukunsa. Minä teen sinun suvullesi, niinkuin minä tein Jerobeamin, Nebatin pojan, suvulle.'),
(1678202,58,11,16,4,'Joka Baesan jälkeläisistä kuolee kaupungissa, sen koirat syövät, ja joka kuolee kedolle, sen syövät taivaan linnut."'),
(1678203,58,11,16,5,'Mitä muuta on kerrottavaa Baesasta, siitä, mitä hän teki, ja hänen urotöistänsä, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678204,58,11,16,6,'Ja Baesa meni lepoon isiensä tykö, ja hänet haudattiin Tirsaan. Ja hänen poikansa Eela tuli kuninkaaksi hänen sijaansa.'),
(1678205,58,11,16,7,'Mutta profeetta Jeehun, Hananin pojan, kautta oli tullut Herran sana Baesaa ja hänen sukuansa vastaan kaiken sen tähden, mitä hän oli tehnyt ja mikä oli pahaa Herran silmissä, hänen kättensä tekojen tähden, joilla hän oli vihoittanut Herran, niin että hänen kävi niinkuin Jerobeamin suvun, kuin myöskin sen tähden, että hän oli surmannut tämän suvun.'),
(1678206,58,11,16,8,'Aasan, Juudan kuninkaan, kahdentenakymmenentenä kuudentena hallitusvuotena tuli Eela, Baesan poika, Israelin kuninkaaksi Tirsassa, ja hän hallitsi kaksi vuotta.'),
(1678207,58,11,16,9,'Mutta hänen palvelijansa Simri, jolla oli johdossaan puolet sotavaunuista, teki salaliiton häntä vastaan. Ja kun hän Tirsassa kerran oli juonut itsensä juovuksiin Tirsassa olevan linnan päällikön Arsan talossa,'),
(1678208,58,11,16,10,'tuli Simri sinne ja löi hänet kuoliaaksi Juudan kuninkaan Aasan kahdentenakymmenentenä seitsemäntenä hallitusvuotena; ja hän tuli kuninkaaksi hänen sijaansa.'),
(1678209,58,11,16,11,'Ja kun hän oli tullut kuninkaaksi ja istunut valtaistuimelleen, surmasi hän koko Baesan suvun eikä jättänyt hänen jälkeläisistään eloon ainoatakaan miehenpuolta, ei sukulunastajaa eikä ystävää.'),
(1678210,58,11,16,12,'Ja niin tuhosi Simri koko Baesan suvun, Herran sanan mukaan, jonka hän oli puhunut Baesaa vastaan profeetta Jeehun kautta,'),
(1678211,58,11,16,13,'kaikkien Baesan ja hänen poikansa Eelan syntien tähden, jotka nämä olivat tehneet ja joilla he olivat saattaneet Israelin tekemään syntiä; he olivat vihoittaneet Herran, Israelin Jumalan, turhilla jumalilla, joita he palvelivat.'),
(1678212,58,11,16,14,'Mitä muuta on kerrottavaa Eelasta ja kaikesta, mitä hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678213,58,11,16,15,'Juudan kuninkaan Aasan kahdentenakymmenentenä seitsemäntenä hallitusvuotena tuli Simri kuninkaaksi, ja hän hallitsi Tirsassa seitsemän päivää. Väki oli silloin asettuneena leiriin Gibbetonin edustalle, joka oli filistealaisilla.'),
(1678214,58,11,16,16,'Kun leiriin asettunut väki kuuli sanottavan: "Simri on tehnyt salaliiton ja on myös surmannut kuninkaan", niin koko Israel teki sinä päivänä leirissä Omrin, Israelin sotapäällikön, kuninkaaksi.'),
(1678215,58,11,16,17,'Ja Omri ja koko Israel hänen kanssaan lähti Gibbetonista, ja he saarsivat Tirsan.'),
(1678216,58,11,16,18,'Ja kun Simri näki, että kaupunki oli valloitettu, meni hän kuninkaan linnan palatsiin ja poltti kuninkaan linnan päänsä päältä tulella, ja niin hän kuoli,'),
(1678217,58,11,16,19,'syntiensä tähden, jotka hän oli tehnyt, kun oli tehnyt sitä, mikä on pahaa Herran silmissä, vaeltamalla Jerobeamin teitä ja hänen synnissään, jota tämä oli tehnyt ja jolla hän oli saattanut Israelin tekemään syntiä.'),
(1678218,58,11,16,20,'Mitä muuta on kerrottavaa Simristä ja salaliitosta, jonka hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678219,58,11,16,21,'Silloin Israelin kansa jakaantui kahtia. Toinen puoli kansaa seurasi Tibniä, Giinatin poikaa, tehdäkseen hänet kuninkaaksi, toinen puoli seurasi Omria.'),
(1678220,58,11,16,22,'Mutta se osa kansaa, joka seurasi Omria, sai voiton siitä osasta kansaa, joka seurasi Tibniä, Giinatin poikaa. Ja Tibni kuoli, ja Omri tuli kuninkaaksi.'),
(1678221,58,11,16,23,'Juudan kuninkaan Aasan kolmantenakymmenentenä ensimmäisenä hallitusvuotena tuli Omri Israelin kuninkaaksi, ja hän hallitsi kaksitoista vuotta; Tirsassa hän hallitsi kuusi vuotta.'),
(1678222,58,11,16,24,'Hän osti Samarian vuoren Semeriltä kahdella talentilla hopeata ja rakensi vuorelle kaupungin ja kutsui rakentamansa kaupungin Samariaksi Semerin, vuoren omistajan, nimen mukaan.'),
(1678223,58,11,16,25,'Ja Omri teki sitä, mikä on pahaa Herran silmissä, teki enemmän pahaa kuin kaikki hänen edeltäjänsä.'),
(1678224,58,11,16,26,'Ja hän vaelsi kaikessa Jerobeamin, Nebatin pojan, tietä ja hänen synneissänsä, joilla hän oli saattanut Israelin tekemään syntiä, niin että he vihoittivat Herran, Israelin Jumalan, turhilla jumalillaan.'),
(1678225,58,11,16,27,'Mitä muuta on kerrottavaa Omrista, siitä, mitä hän teki, ja hänen tekemistään urotöistä, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678226,58,11,16,28,'Omri meni lepoon isiensä tykö, ja hänet haudattiin Samariaan. Ja hänen poikansa Ahab tuli kuninkaaksi hänen sijaansa.'),
(1678227,58,11,16,29,'Ahab, Omrin poika, tuli Israelin kuninkaaksi Aasan, Juudan kuninkaan, kolmantenakymmenentenä kahdeksantena hallitusvuotena; sitten Ahab, Omrin poika, hallitsi Israelia Samariassa kaksikymmentä kaksi vuotta.'),
(1678228,58,11,16,30,'Mutta Ahab, Omrin poika, teki sitä, mikä on pahaa Herran silmissä, enemmän kuin kaikki hänen edeltäjänsä.'),
(1678229,58,11,16,31,'Ei ollut siinä kylliksi, että hän vaelsi Jerobeamin, Nebatin pojan, synneissä, vaan hän otti myös vaimokseen Iisebelin, siidonilaisten kuninkaan Etbaalin tyttären, ja rupesi palvelemaan Baalia ja kumartamaan sitä.'),
(1678230,58,11,16,32,'Ja hän pystytti alttarin Baalille Baalin temppeliin, jonka hän oli rakentanut Samariaan.'),
(1678231,58,11,16,33,'Ahab teki myös aseran. Ja Ahab teki vielä paljon muuta ja vihoitti Herraa, Israelin Jumalaa, enemmän kuin kukaan niistä Israelin kuninkaista, jotka olivat olleet ennen häntä.'),
(1678232,58,11,16,34,'Hänen aikanansa beeteliläinen Hiiel rakensi uudelleen Jerikon. Sen perustuksen laskemisesta hän menetti esikoisensa Abiramin, ja sen ovien pystyttämisestä hän menetti nuorimpansa Segubin, Herran sanan mukaan, jonka hän oli puhunut Joosuan, Nuunin pojan, kautta.'),
(1678233,58,11,17,1,'Tisbeläinen Elia, eräs Gileadiin asettuneita siirtolaisia, sanoi Ahabille: "Niin totta kuin Herra, Israelin Jumala, elää, jonka edessä minä seison: näinä vuosina ei tule kastetta eikä sadetta muutoin kuin minun sanani kautta".'),
(1678234,58,11,17,2,'Ja hänelle tuli tämä Herran sana:'),
(1678235,58,11,17,3,'"Mene pois täältä ja käänny itään päin ja kätkeydy Keritin purolle, joka on Jordanin itäpuolella.'),
(1678236,58,11,17,4,'Sinä saat juoda purosta, ja minä olen käskenyt kaarneiden elättää sinua siellä."'),
(1678237,58,11,17,5,'Niin hän meni ja teki Herran sanan mukaan: hän meni ja asettui Keritin purolle, joka on Jordanin itäpuolella.'),
(1678238,58,11,17,6,'Ja kaarneet toivat hänelle leipää ja lihaa aamuin sekä leipää ja lihaa illoin, ja hän joi purosta.'),
(1678239,58,11,17,7,'Mutta jonkun ajan kuluttua puro kuivui, koska siinä maassa ei ollut satanut.'),
(1678240,58,11,17,8,'Ja hänelle tuli tämä Herran sana:'),
(1678241,58,11,17,9,'"Nouse ja mene Sarpatiin, joka on Siidonin aluetta, ja asetu sinne. Katso, minä olen käskenyt leskivaimon elättää sinua siellä."'),
(1678242,58,11,17,10,'Niin hän nousi ja meni Sarpatiin. Ja kun hän tuli kaupungin portille, niin katso, siellä oli leskivaimo keräilemässä puita. Hän huusi tälle ja sanoi: "Tuo minulle vähän vettä astiassa juodakseni".'),
(1678243,58,11,17,11,'Kun hän meni hakemaan, huusi hän hänelle ja sanoi: "Tuo minulle myös palanen leipää kädessäsi".'),
(1678244,58,11,17,12,'Mutta hän vastasi: "Niin totta kuin Herra, sinun Jumalasi, elää, minulla ei ole leipäkakkuakaan, vaan ainoastaan kourallinen jauhoja ruukussa ja vähän öljyä astiassa. Ja katso, kerättyäni pari puuta minä menen leipomaan itselleni ja pojalleni, syödäksemme ja sitten kuollaksemme."'),
(1678245,58,11,17,13,'Niin Elia sanoi hänelle: "Älä pelkää; mene ja tee, niinkuin olet sanonut. Mutta leivo minulle ensin pieni kaltiainen ja tuo se minulle. Leivo sitten itsellesi ja pojallesi.'),
(1678246,58,11,17,14,'Sillä näin sanoo Herra, Israelin Jumala: Jauhot eivät lopu ruukusta, eikä öljyä ole puuttuva astiasta siihen päivään asti, jona Herra antaa sateen maan päälle."'),
(1678247,58,11,17,15,'Niin hän meni ja teki, niinkuin Elia oli sanonut. Ja hänellä sekä myös Elialla ja vaimon perheellä oli syötävää pitkäksi aikaa.'),
(1678248,58,11,17,16,'Jauhot eivät loppuneet ruukusta, eikä öljyä puuttunut astiasta, sen Herran sanan mukaan, jonka hän oli Elian kautta puhunut.'),
(1678249,58,11,17,17,'Sen jälkeen vaimon, talon emännän, poika sairastui; ja hänen tautinsa kävi hyvin kovaksi, niin ettei hänessä enää ollut henkeä.'),
(1678250,58,11,17,18,'Silloin vaimo sanoi Elialle: "Mitä minulla on tekemistä sinun kanssasi, Jumalan mies? Sinä olet tullut minun luokseni saattamaan minun pahat tekoni muistoon ja tuottamaan kuoleman minun pojalleni."'),
(1678251,58,11,17,19,'Mutta hän sanoi hänelle: "Anna poikasi minulle". Ja hän otti tämän hänen sylistään ja vei hänet yliskammioon, jossa asui, ja pani hänet vuoteellensa.'),
(1678252,58,11,17,20,'Ja hän huusi Herraa ja sanoi: "Herra, minun Jumalani, oletko tehnyt niin pahoin tätä leskeä kohtaan, jonka vieraana minä olen, että olet surmannut hänen poikansa?"'),
(1678253,58,11,17,21,'Sitten hän ojentautui pojan yli kolme kertaa, huusi Herraa ja sanoi: "Herra, minun Jumalani, anna tämän pojan sielun tulla häneen takaisin".'),
(1678254,58,11,17,22,'Ja Herra kuuli Eliaa, ja pojan sielu tuli häneen takaisin, ja hän virkosi henkiin.'),
(1678255,58,11,17,23,'Ja Elia otti pojan ja toi hänet yliskammiosta alas huoneeseen ja antoi hänet hänen äidillensä. Ja Elia sanoi: "Katso, poikasi elää".'),
(1678256,58,11,17,24,'Niin vaimo sanoi Elialle: "Nyt minä tiedän, että sinä olet Jumalan mies ja että Herran sana sinun suussasi on tosi".'),
(1678257,58,11,18,1,'Pitkän ajan kuluttua, kolmantena vuotena, tuli Elialle tämä Herran sana: "Mene ja näyttäydy Ahabille, niin minä annan sateen maan päälle".'),
(1678258,58,11,18,2,'Niin Elia meni näyttäytymään Ahabille. Mutta Samariassa oli kova nälänhätä.'),
(1678259,58,11,18,3,'Ja Ahab kutsui Obadjan, joka oli palatsin päällikkönä. Mutta Obadja oli hyvin Herraa pelkääväinen mies;'),
(1678260,58,11,18,4,'niinpä Obadja oli silloin, kun Iisebel hävitti Herran profeetat, ottanut sata profeettaa ja piilottanut heidät luolaan, viisikymmentä kerrallaan, ja elättänyt heitä leivällä ja vedellä.'),
(1678261,58,11,18,5,'Ahab sanoi Obadjalle: "Kulje maa, kaikki vesilähteet ja kaikki purot. Kenties me löydämme ruohoa pitääksemme hevoset ja muulit hengissä, niin ettei meidän tarvitse hävittää elukoita."'),
(1678262,58,11,18,6,'Ja he jakoivat keskenään kuljettavansa maan. Ahab kulki toista tietä yksinänsä, ja Obadja kulki toista tietä yksinänsä.'),
(1678263,58,11,18,7,'Kun nyt Obadja oli matkalla, niin katso, Elia tuli häntä vastaan. Tuntiessaan tämän hän heittäytyi kasvoillensa ja sanoi: "Sinäkö se olet, herrani Elia?"'),
(1678264,58,11,18,8,'Tämä vastasi hänelle: "Minä. Mene ja sano herrallesi: ''Katso, Elia on täällä''."'),
(1678265,58,11,18,9,'Niin hän sanoi: "Mitä minä olen rikkonut, koska annat palvelijasi Ahabin käsiin, hänen surmattavakseen?'),
(1678266,58,11,18,10,'Niin totta kuin Herra, sinun Jumalasi, elää, ei ole sitä kansaa eikä sitä valtakuntaa, josta minun herrani ei olisi lähettänyt etsimään sinua, mutta kun on vastattu: ''Ei hän ole täällä'', on hän vannottanut sillä valtakunnalla ja sillä kansalla valan, ettei sinua ole löydetty.'),
(1678267,58,11,18,11,'Ja nyt sinä sanot: ''Mene ja sano herrallesi: Katso, Elia on täällä''.'),
(1678268,58,11,18,12,'Kun minä lähden pois luotasi, niin Herran Henki kuljettaa sinut, en tiedä minne, ja kun minä menen ilmoittamaan Ahabille eikä hän löydä sinua, niin hän tappaa minut. Ja kuitenkin palvelijasi on peljännyt Herraa nuoruudestaan asti.'),
(1678269,58,11,18,13,'Eikö herralleni ole kerrottu, mitä minä tein, kun Iisebel tappoi Herran profeetat: kuinka minä piilotin luolaan sata Herran profeettaa, viisikymmentä kerrallaan, ja elätin heitä leivällä ja vedellä?'),
(1678270,58,11,18,14,'Ja nyt sinä sanot: ''Mene ja sano herrallesi: Katso, Elia on täällä'', ja niin hän tappaa minut."'),
(1678271,58,11,18,15,'Mutta Elia sanoi: "Niin totta kuin Herra Sebaot elää, jonka edessä minä seison, minä näyttäydyn tänä päivänä hänelle".'),
(1678272,58,11,18,16,'Niin Obadja meni Ahabia vastaan ja ilmoitti hänelle tämän. Ahab meni silloin Eliaa vastaan.'),
(1678273,58,11,18,17,'Ja nähdessään Elian Ahab sanoi hänelle: "Siinäkö sinä olet, sinä, joka syökset Israelin onnettomuuteen?"'),
(1678274,58,11,18,18,'Tämä vastasi: "En minä syökse Israelia onnettomuuteen, vaan sinä ja sinun isäsi suku, koska te hylkäätte Herran käskyt ja koska sinä seuraat baaleja.'),
(1678275,58,11,18,19,'Mutta lähetä nyt kokoamaan kaikki Israel minun luokseni Karmel-vuorelle, sekä neljäsataa viisikymmentä Baalin profeettaa ja neljäsataa Aseran profeettaa, jotka syövät Iisebelin pöydästä."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678276,58,11,18,20,'Niin Ahab lähetti sanan kaikille israelilaisille ja kokosi profeetat Karmel-vuorelle.'),
(1678277,58,11,18,21,'Ja Elia astui kaiken kansan eteen ja sanoi: "Kuinka kauan te onnutte molemmille puolille? Jos Herra on Jumala, seuratkaa häntä; mutta jos Baal on Jumala, seuratkaa häntä." Eikä kansa vastannut hänelle mitään.'),
(1678278,58,11,18,22,'Niin Elia sanoi kansalle: "Minä olen ainoa jäljelle jäänyt Herran profeetta, mutta Baalin profeettoja on neljäsataa viisikymmentä.'),
(1678279,58,11,18,23,'Antakaa meille kaksi mullikkaa, ja valitkoot he itselleen toisen mullikan, paloitelkoot sen ja pankoot kappaleet puiden päälle, mutta älkööt panko tulta; ja minä valmistan toisen mullikan ja asetan sen puiden päälle, mutta en pane tulta.'),
(1678280,58,11,18,24,'Sitten huutakaa te jumalanne nimeä, ja minä huudan Herran nimeä. Se jumala, joka vastaa tulella, on Jumala." Kaikki kansa vastasi ja sanoi: "Niin on hyvä".'),
(1678281,58,11,18,25,'Ja Elia sanoi Baalin profeetoille: "Valitkaa itsellenne toinen mullikka ja valmistakaa se ensin, sillä teitä on enemmän. Huutakaa sitten jumalanne nimeä, mutta älkää panko tulta".'),
(1678282,58,11,18,26,'Niin he ottivat sen mullikan, jonka hän antoi heille, ja valmistivat sen. Sitten he huusivat Baalin nimeä aamusta puolipäivään asti, sanoen: "Baal, vastaa meille!" Mutta ei ääntä, ei vastausta! Ja he hyppelivät alttarin ääressä, joka oli tehty.'),
(1678283,58,11,18,27,'Puolipäivän aikana Elia pilkkasi heitä ja sanoi: "Huutakaa kovemmin; hän on tosin jumala, mutta hänellä voi olla jotakin toimittamista, tahi hän on poistunut johonkin, tahi on matkalla; kenties hän nukkuu, mutta kyllä hän herää".'),
(1678284,58,11,18,28,'Niin he huusivat vielä kovemmin ja viileksivät itseään tapansa mukaan miekoilla ja keihäillä, niin että heistä vuoti verta.'),
(1678285,58,11,18,29,'Kun puolipäivä oli kulunut, joutuivat he hurmoksiin, aina siihen hetkeen asti, jolloin ruokauhri uhrataan. Mutta ei ääntä, ei vastausta, ei vaarinottoa!'),
(1678286,58,11,18,30,'Niin Elia sanoi kaikelle kansalle: "Astukaa minun luokseni". Ja kaikki kansa astui hänen luoksensa. Niin hän korjasi Herran alttarin, joka oli hajotettu.'),
(1678287,58,11,18,31,'Ja Elia otti kaksitoista kiveä, yhtä monta kuin oli Jaakobin poikien sukukuntia, hänen, jolle oli tullut tämä Herran sana: "Israel on oleva sinun nimesi".'),
(1678288,58,11,18,32,'Ja hän rakensi kivistä alttarin Herran nimeen ja teki alttarin ympärille ojan, johon olisi mahtunut kaksi sea-mittaa jyviä.'),
(1678289,58,11,18,33,'Sitten hän latoi puut, paloitteli mullikan ja pani kappaleet puiden päälle.'),
(1678290,58,11,18,34,'Ja hän sanoi: "Täyttäkää neljä ruukkua vedellä ja vuodattakaa se polttouhrin ja puiden päälle". Ja hän sanoi: "Tehkää se toinen kerta". Ja he tekivät niin toisen kerran. Vielä hän sanoi: "Tehkää se kolmas kerta". Ja he tekivät niin kolmannen kerran.'),
(1678291,58,11,18,35,'Niin vesi juoksi ympäri alttarin; ojankin hän täytti vedellä.'),
(1678292,58,11,18,36,'Ja kun oli tullut hetki, jolloin ruokauhri uhrataan, astui profeetta Elia esille ja sanoi: "Herra, Aabrahamin, Iisakin ja Israelin Jumala, tulkoon tänä päivänä tiettäväksi, että sinä olet Jumala Israelissa ja että minä olen sinun palvelijasi ja että minä olen sinun käskystäsi tehnyt kaiken tämän.'),
(1678293,58,11,18,37,'Vastaa minulle, Herra, vastaa minulle, että tämä kansa tulisi näkemään, että sinä, Herra, olet Jumala ja että sinä käännät heidän sydämensä takaisin."'),
(1678294,58,11,18,38,'Silloin Herran tuli iski alas ja kulutti polttouhrin, puut, kivet ja mullan sekä nuoli veden, joka oli ojassa.'),
(1678295,58,11,18,39,'Kun kaikki kansa näki tämän, lankesivat he kasvoillensa ja sanoivat: "Herra on Jumala! Herra on Jumala!"'),
(1678296,58,11,18,40,'Mutta Elia sanoi heille: "Ottakaa Baalin profeetat kiinni; älköön yksikään heistä pääskö pakoon". Ja he ottivat heidät kiinni. Ja Elia vei heidät Kiisonin purolle ja tappoi heidät siellä.'),
(1678297,58,11,18,41,'Ja Elia sanoi Ahabille: "Nouse, syö ja juo, sillä sateen kohina kuuluu".'),
(1678298,58,11,18,42,'Niin Ahab nousi syömään ja juomaan. Mutta Elia nousi Karmelin huipulle, kumartui maahan ja painoi kasvonsa polviensa väliin.'),
(1678299,58,11,18,43,'Ja hän sanoi palvelijallensa: "Nouse ja katso merelle päin". Tämä nousi ja katsoi, mutta sanoi: "Ei näy mitään". Hän sanoi: "Mene takaisin". Näin seitsemän kertaa.'),
(1678300,58,11,18,44,'Seitsemännellä kerralla palvelija sanoi: "Katso, pieni pilvi, miehen kämmenen kokoinen, nousee merestä". Niin Elia sanoi: "Nouse ja sano Ahabille: ''Valjasta ja lähde alas, ettei sade sinua pidättäisi''".'),
(1678301,58,11,18,45,'Ja tuossa tuokiossa taivas kävi mustaksi pilvistä ja myrskytuulesta, ja tuli ankara sade. Mutta Ahab nousi vaunuihinsa ja lähti Jisreeliin.'),
(1678302,58,11,18,46,'Ja Herran käsi tuli Elian päälle, ja niin hän vyötti kupeensa ja juoksi Ahabin edellä Jisreeliin saakka.'),
(1678303,58,11,19,1,'Mutta kun Ahab kertoi Iisebelille kaiken, mitä Elia oli tehnyt ja kuinka hän oli tappanut miekalla kaikki profeetat,'),
(1678304,58,11,19,2,'lähetti Iisebel sanansaattajan Elian luo ja käski sanoa: "Jumalat rangaiskoot minua nyt ja vasta, jollen minä huomenna tähän aikaan tee sinulle samaa, mikä jokaiselle näistä on tehty".'),
(1678305,58,11,19,3,'Kun tämä näki sen, nousi hän ja lähti matkaan pelastaakseen henkensä ja tuli Beersebaan, joka on Juudan aluetta.'),
(1678306,58,11,19,4,'Sinne hän jätti palvelijansa, mutta meni itse erämaahan päivänmatkan päähän. Hän tuli ja istuutui kinsteripensaan juureen. Ja hän toivotti itsellensä kuolemaa ja sanoi: "Jo riittää, Herra; ota minun henkeni, sillä minä en ole isiäni parempi".'),
(1678307,58,11,19,5,'Ja hän paneutui maata ja nukkui kinsteripensaan juurelle. Mutta katso, enkeli kosketti häntä ja sanoi hänelle: "Nouse ja syö".'),
(1678308,58,11,19,6,'Ja kun hän katsahti, niin katso, hänen päänsä pohjissa oli kuumennetuilla kivillä paistettu kaltiainen ja vesiastia. Niin hän söi ja joi ja paneutui jälleen maata.'),
(1678309,58,11,19,7,'Mutta Herran enkeli kosketti häntä vielä toisen kerran ja sanoi: "Nouse ja syö, sillä muutoin käy matka sinulle liian pitkäksi".'),
(1678310,58,11,19,8,'Niin hän nousi ja söi ja joi. Ja hän kulki sen ruuan voimalla neljäkymmentä päivää ja neljäkymmentä yötä Jumalan vuorelle, Hoorebille, asti.'),
(1678311,58,11,19,9,'Siellä hän meni luolaan ja oli siinä yötä. Ja katso, Herran sana tuli hänelle; hän kysyi häneltä: "Mitä sinä täällä teet, Elia?"'),
(1678312,58,11,19,10,'Hän vastasi: "Minä olen kiivailemalla kiivaillut Herran, Jumalan Sebaotin, puolesta. Sillä israelilaiset ovat hyljänneet sinun liittosi, hajottaneet sinun alttarisi ja tappaneet miekalla sinun profeettasi. Minä yksin olen jäänyt jäljelle, mutta minunkin henkeäni he väijyvät, ottaaksensa sen."'),
(1678313,58,11,19,11,'Hän sanoi: "Mene ulos ja asetu vuorelle Herran eteen". Ja katso, Herra kulki ohitse, ja suuri ja raju myrsky, joka halkoi vuoret ja särki kalliot, kävi Herran edellä; mutta ei Herra ollut myrskyssä. Myrskyn jälkeen tuli maanjäristys; mutta ei Herra ollut maanjäristyksessä.'),
(1678314,58,11,19,12,'Maanjäristyksen jälkeen tuli tulta; mutta ei Herra ollut tulessa. Tulen jälkeen tuli hiljainen tuulen hyminä.'),
(1678315,58,11,19,13,'Kun Elia sen kuuli, peitti hän kasvonsa vaipallansa, meni ulos ja asettui luolan suulle. Ja katso, hänelle puhui ääni ja sanoi: "Mitä sinä täällä teet, Elia?"'),
(1678316,58,11,19,14,'Hän vastasi: "Minä olen kiivailemalla kiivaillut Herran, Jumalan Sebaotin, puolesta. Sillä israelilaiset ovat hyljänneet sinun liittosi, hajottaneet sinun alttarisi ja tappaneet miekalla sinun profeettasi. Minä yksin olen jäänyt jäljelle, mutta minunkin henkeäni he väijyvät, ottaaksensa sen."'),
(1678317,58,11,19,15,'Herra sanoi hänelle: "Lähde takaisin samaa tietä, jota tulit, erämaan kautta Damaskoon. Mene ja voitele Hasael Aramin kuninkaaksi.'),
(1678318,58,11,19,16,'Ja voitele Jeehu, Nimsin poika, Israelin kuninkaaksi. Ja voitele sijaasi profeetaksi Elisa, Saafatin poika, Aabel-Meholasta.'),
(1678319,58,11,19,17,'Ja on tapahtuva näin: joka välttää Hasaelin miekan, sen surmaa Jeehu, ja joka välttää Jeehun miekan, sen surmaa Elisa.'),
(1678320,58,11,19,18,'Mutta minä jätän jäljelle Israeliin seitsemäntuhatta: kaikki polvet, jotka eivät ole notkistuneet Baalille, ja kaikki suut, jotka eivät ole hänelle suuta antaneet."'),
(1678321,58,11,19,19,'Niin hän lähti sieltä ja kohtasi Elisan, Saafatin pojan, kun tämä oli kyntämässä; kaksitoista härkäparia kulki hänen edellänsä, ja itse hän ajoi kahdettatoista. Kulkiessaan hänen ohitsensa Elia heitti vaippansa hänen päällensä.'),
(1678322,58,11,19,20,'Niin hän jätti härät, riensi Elian jälkeen ja sanoi: "Salli minun ensin antaa suuta isälleni ja äidilleni; sitten minä seuraan sinua". Elia sanoi hänelle: "Mene, mutta tule takaisin; tiedäthän, mitä minä olen sinulle tehnyt".'),
(1678323,58,11,19,21,'Niin hän meni hänen luotaan takaisin, otti härkäparinsa ja teurasti sen, ja härkäin ikeellä hän keitti lihat; ne hän antoi väelle, ja he söivät. Sitten hän nousi ja seurasi Eliaa ja palveli häntä.'),
(1678324,58,11,20,1,'Ja Benhadad, Aramin kuningas, kokosi kaiken sotajoukkonsa. Hänellä oli mukanaan kolmekymmentä kaksi kuningasta sekä hevosia ja sotavaunuja. Ja hän meni ja piiritti Samariaa ja ryhtyi taisteluun sitä vastaan.'),
(1678325,58,11,20,2,'Ja hän lähetti sanansaattajat kaupunkiin Ahabin, Israelin kuninkaan, luo');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678326,58,11,20,3,'ja käski sanoa hänelle: "Näin sanoo Benhadad: ''Sinun hopeasi ja kultasi ovat minun, ja sinun kauneimmat vaimosi ja lapsesi ovat myöskin minun''".'),
(1678327,58,11,20,4,'Israelin kuningas vastasi ja sanoi: "Niinkuin sinä olet sanonut, herrani, kuningas, minä olen sinun, minä ja kaikki, mitä minulla on".'),
(1678328,58,11,20,5,'Mutta sanansaattajat tulivat takaisin ja sanoivat: "Näin sanoo Benhadad: ''Minä olen lähettänyt sinulle tämän sanan: Anna minulle hopeasi ja kultasi, vaimosi ja lapsesi.'),
(1678329,58,11,20,6,'Totisesti minä lähetän huomenna tähän aikaan palvelijani sinun luoksesi tutkimaan sinun taloasi ja sinun palvelijaisi taloja; ja kaiken, mikä on sinun silmiesi ihastus, he ottavat haltuunsa ja vievät.''"'),
(1678330,58,11,20,7,'Silloin Israelin kuningas kutsui kaikki maan vanhimmat ja sanoi: "Ymmärtäkää ja nähkää, että hän hankkii meille onnettomuutta; sillä kun hän lähetti vaatimaan minulta vaimojani ja lapsiani, hopeatani ja kultaani, en minä niitä häneltä kieltänyt".'),
(1678331,58,11,20,8,'Kaikki vanhimmat ja kaikki kansa sanoivat hänelle: "Älä kuule häntä äläkä suostu".'),
(1678332,58,11,20,9,'Niin hän sanoi Benhadadin sanansaattajille: "Sanokaa herralleni, kuninkaalle: ''Kaiken, mitä sinä ensi kerralla käskit palvelijasi tehdä, minä teen; mutta tätä minä en voi tehdä''". Ja sanansaattajat menivät ja veivät tämän vastauksen hänelle.'),
(1678333,58,11,20,10,'Niin Benhadad lähetti hänelle sanan: "Jumalat rangaiskoot minua nyt ja vasta, jos Samarian tomu riittää täyttämään kaiken sen väen kourat, joka minua seuraa".'),
(1678334,58,11,20,11,'Mutta Israelin kuningas vastasi ja sanoi: "Sanokaa hänelle: ''Älköön se, joka vyöttäytyy miekkaan, kerskatko niinkuin se, joka sen riisuu''".'),
(1678335,58,11,20,12,'Kun hän, juodessaan kuninkaitten kanssa lehtimajoissa, kuuli tämän vastauksen, sanoi hän palvelijoilleen: "Piiritys käyntiin!" Ja he panivat piirityksen käyntiin kaupunkia vastaan.'),
(1678336,58,11,20,13,'Ja katso, eräs profeetta astui Ahabin, Israelin kuninkaan, eteen ja sanoi: "Näin sanoo Herra: Näetkö kaiken tuon suuren lauman? Katso, minä annan sen tänä päivänä sinun käsiisi, että sinä tulisit tietämään, että minä olen Herra."'),
(1678337,58,11,20,14,'Ahab kysyi: "Kenen avulla?" Hän vastasi: "Näin sanoo Herra: Maaherrain palvelijoitten avulla". Ahab kysyi vielä: "Kuka alottaa taistelun?" Hän vastasi: "Sinä".'),
(1678338,58,11,20,15,'Niin hän katsasti herrain palvelijat, ja niitä oli kaksisataa kolmekymmentä kaksi. Niitten jälkeen hän katsasti kaiken väen, kaikki israelilaiset, joita oli seitsemäntuhatta.'),
(1678339,58,11,20,16,'Ja he tekivät hyökkäyksen puolenpäivän aikana, kun Benhadad oli juovuksissa ja joi lehtimajoissa, hän ja ne kolmekymmentä kaksi kuningasta, jotka olivat tulleet hänen avuksensa.'),
(1678340,58,11,20,17,'Maaherrain palvelijat hyökkäsivät ensimmäisinä. Silloin Benhadad lähetti tiedustelemaan, ja hänelle ilmoitettiin: "Miehiä on lähtenyt liikkeelle Samariasta".'),
(1678341,58,11,20,18,'Hän sanoi: "Jos he ovat lähteneet liikkeelle rauha mielessä, niin ottakaa heidät kiinni elävinä; ja jos he ovat lähteneet taistellakseen, ottakaa heidät silloinkin kiinni elävinä".'),
(1678342,58,11,20,19,'Mutta kun maaherrain palvelijat ja sotajoukko, joka seurasi heitä, olivat hyökänneet kaupungista,'),
(1678343,58,11,20,20,'surmasivat he miehen kukin. Niin aramilaiset pakenivat, ja Israel ajoi heitä takaa. Mutta Benhadad, Aramin kuningas, pääsi muutamien ratsumiesten kanssa pakoon hevosen selässä.'),
(1678344,58,11,20,21,'Mutta Israelin kuningas lähti liikkeelle ja valtasi hevoset ja sotavaunut; ja niin hän tuotti aramilaisille suuren tappion.'),
(1678345,58,11,20,22,'Ja profeetta astui Israelin kuninkaan eteen ja sanoi hänelle: "Vahvista itsesi, ymmärrä ja katso, mitä sinun on tehtävä, sillä vuoden vaihteessa hyökkää Aramin kuningas sinun kimppuusi".'),
(1678346,58,11,20,23,'Aramin kuninkaan palvelijat sanoivat tälle: "Heidän jumalansa on vuorijumala; sentähden he saivat meistä voiton. Mutta taistelkaamme heitä vastaan tasangolla, silloin me varmasti saamme heistä voiton.'),
(1678347,58,11,20,24,'Ja tee näin: Pane pois kuninkaat, kukin paikaltaan, ja aseta käskynhaltijat heidän sijaansa.'),
(1678348,58,11,20,25,'Hanki sitten itsellesi sotajoukko, yhtä suuri kuin menettämäsi oli, yhtä monta hevosta ja yhtä monet sotavaunut; ja taistelkaamme heitä vastaan tasangolla, niin me varmasti saamme heistä voiton." Niin hän kuuli heitä ja teki niin.'),
(1678349,58,11,20,26,'Vuoden vaihteessa Benhadad katsasti aramilaiset ja lähti Afekiin taistelemaan Israelia vastaan.'),
(1678350,58,11,20,27,'Ja israelilaiset katsastettiin ja muonitettiin, ja he lähtivät heitä vastaan. Israelilaiset leiriytyivät heidän eteensä niinkuin kaksi pientä vuohilaumaa, mutta aramilaiset täyttivät maan.'),
(1678351,58,11,20,28,'Silloin Jumalan mies astui Israelin kuninkaan eteen ja sanoi: "Näin sanoo Herra: Sentähden, että aramilaiset ovat sanoneet: ''Herra on vuorijumala eikä laaksojumala'', annan minä koko tämän suuren lauman sinun käsiisi, tullaksenne tietämään, että minä olen Herra."'),
(1678352,58,11,20,29,'Ja he olivat leiriytyneinä vastakkain seitsemän päivää. Seitsemäntenä päivänä sukeutui taistelu, ja israelilaiset surmasivat aramilaisia satatuhatta jalkamiestä yhtenä päivänä.'),
(1678353,58,11,20,30,'Jäljellejääneet pakenivat Afekiin, kaupunkiin. Ja muuri kaatui kahdenkymmenen seitsemän tuhannen jäljellejääneen miehen päälle. Mutta Benhadad pakeni, tuli kaupunkiin ja juoksi huoneesta huoneeseen.'),
(1678354,58,11,20,31,'Silloin hänen palvelijansa sanoivat hänelle: "Katso, me olemme kuulleet, että Israelin heimon kuninkaat ovat laupiaita kuninkaita. Pankaamme säkit lanteillemme ja nuorat päämme ympärille ja antautukaamme Israelin kuninkaalle; ehkä hän jättää sinut henkiin."'),
(1678355,58,11,20,32,'Ja he käärivät säkit lanteilleen ja panivat nuorat päänsä ympärille ja tulivat Israelin kuninkaan luo ja sanoivat: "Palvelijasi Benhadad sanoo: ''Salli minun elää''." Hän sanoi: "Vieläkö hän elää? Hän on minun veljeni."'),
(1678356,58,11,20,33,'Niin miehet katsoivat sen hyväksi enteeksi, tarttuivat kiiruusti hänen sanaansa ja sanoivat: "Benhadad on sinun veljesi". Hän sanoi: "Menkää ja noutakaa hänet". Silloin Benhadad antautui hänelle, ja hän antoi hänen nousta vaunuihinsa.'),
(1678357,58,11,20,34,'Ja Benhadad sanoi hänelle: "Kaupungit, jotka minun isäni otti sinun isältäsi, minä annan takaisin. Laita itsellesi katumyymälöitä Damaskoon, niinkuin minun isäni laittoi Samariaan." Ahab vastasi: "Minä päästän sinut menemään sillä välipuheella". Ja hän teki liiton hänen kanssaan ja päästi hänet menemään.'),
(1678358,58,11,20,35,'Silloin eräs profeetanoppilaista sanoi Herran käskystä toverilleen: "Lyö minua". Mutta mies ei tahtonut lyödä häntä.'),
(1678359,58,11,20,36,'Niin hän sanoi tälle: "Koska et kuullut Herran ääntä, niin katso, leijona surmaa sinut, kun lähdet minun luotani". Ja kun hän lähti hänen luotansa, kohtasi leijona hänet ja surmasi hänet.'),
(1678360,58,11,20,37,'Sitten hän tapasi toisen miehen ja sanoi: "Lyö minua". Ja mies löi hänet haavoille.'),
(1678361,58,11,20,38,'Niin profeetta meni ja asettui tielle, jota kuninkaan oli kuljettava, ja teki itsensä tuntemattomaksi panemalla siteen silmilleen.'),
(1678362,58,11,20,39,'Kun kuningas kulki ohitse, huusi hän kuninkaalle ja sanoi: "Palvelijasi oli lähtenyt keskelle taistelua; ja katso, sieltä tuli mies ja toi toisen miehen minun luokseni ja sanoi: ''Vartioitse tätä miestä. Jos hän katoaa, menee sinun henkesi hänen hengestään, tahi sinä maksat talentin hopeata.'''),
(1678363,58,11,20,40,'Palvelijallasi oli tehtävää siellä ja täällä, ja sitten ei miestä enää ollut." Israelin kuningas sanoi hänelle: "Tuomiosi on siis se; sinä olet itse julistanut sen".'),
(1678364,58,11,20,41,'Silloin hän nopeasti poisti siteen silmiltään, ja Israelin kuningas tunsi hänet, että hän oli profeettoja.'),
(1678365,58,11,20,42,'Ja tämä sanoi hänelle: "Näin sanoo Herra: Koska sinä päästit käsistäsi menemään minulle tuhon omaksi vihityn miehen, menee sinun henkesi hänen hengestänsä ja sinun kansasi hänen kansastaan."'),
(1678366,58,11,20,43,'Niin Israelin kuningas meni kotiinsa pahastuneena ja alakuloisena ja tuli Samariaan.'),
(1678367,58,11,21,1,'Näiden tapausten jälkeen tapahtui tämä. Jisreeliläisellä Naabotilla oli viinitarha, joka oli Jisreelissä Samarian kuninkaan Ahabin palatsin vieressä.'),
(1678368,58,11,21,2,'Ja Ahab puhui Naabotille sanoen: "Anna minulle viinitarhasi vihannestarhaksi, koska se on niin likellä minun linnaani; minä annan sinulle sen sijaan paremman viinitarhan, tahi, jos niin tahdot, minä annan sinulle sen hinnan rahana".'),
(1678369,58,11,21,3,'Mutta Naabot vastasi Ahabille: "Pois se, Herra varjelkoon minua antamasta sinulle isieni perintöosaa".'),
(1678370,58,11,21,4,'Niin Ahab tuli kotiinsa pahastuneena ja alakuloisena vastauksesta, jonka jisreeliläinen Naabot oli hänelle antanut, kun tämä oli sanonut: "En minä anna sinulle isieni perintöosaa". Ja hän pani maata vuoteellensa, käänsi kasvonsa pois eikä syönyt mitään.'),
(1678371,58,11,21,5,'Niin hänen vaimonsa Iisebel tuli hänen luokseen ja puhui hänelle: "Miksi olet niin pahoilla mielin ja miksi et syö mitään?"'),
(1678372,58,11,21,6,'Ahab vastasi hänelle: "Siksi, että puhuttelin jisreeliläistä Naabotia ja sanoin hänelle: ''Anna minulle viinitarhasi rahasta, tahi jos haluat, annan minä sinulle toisen viinitarhan sen sijaan'', mutta hän vastasi: ''En minä anna sinulle viinitarhaani''".'),
(1678373,58,11,21,7,'Niin hänen vaimonsa Iisebel sanoi hänelle: "Sinäkö olet käyttävinäsi kuninkaanvaltaa Israelissa? Nouse ja syö, ja olkoon sydämesi iloinen; minä kyllä toimitan sinulle jisreeliläisen Naabotin viinitarhan."'),
(1678374,58,11,21,8,'Ja hän kirjoitti kirjeen Ahabin nimessä, sinetöi sen hänen sinetillään ja lähetti kirjeen vanhimmille ja ylimyksille, jotka olivat Naabotin kaupungissa ja asuivat siellä hänen kanssaan.'),
(1678375,58,11,21,9,'Ja kirjeessä hän kirjoitti näin: "Kuuluttakaa paasto ja asettakaa Naabot istumaan etumaiseksi kansan joukkoon.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678376,58,11,21,10,'Ja asettakaa kaksi kelvotonta miestä istumaan häntä vastapäätä, että he todistaisivat hänestä näin: ''Sinä olet kironnut Jumalaa ja kuningasta''. Viekää hänet sitten ulos ja kivittäkää hänet kuoliaaksi."'),
(1678377,58,11,21,11,'Ja kaupungin miehet, vanhimmat ja ylimykset, jotka asuivat hänen kaupungissansa, tekivät, niinkuin Iisebel oli käskenyt heitä ja niinkuin oli kirjoitettu kirjeessä, jonka hän oli heille lähettänyt.'),
(1678378,58,11,21,12,'He kuuluttivat paaston ja asettivat Naabotin istumaan etumaiseksi kansan joukkoon.'),
(1678379,58,11,21,13,'Ja kaksi kelvotonta miestä tuli ja istui häntä vastapäätä. Ja ne kelvottomat miehet todistivat Naabotista kansan edessä sanoen: "Naabot on kironnut Jumalaa ja kuningasta". Silloin he veivät hänet kaupungin ulkopuolelle ja kivittivät hänet kuoliaaksi.'),
(1678380,58,11,21,14,'Sitten he lähettivät Iisebelille tämän sanan: "Naabot on kivitetty kuoliaaksi".'),
(1678381,58,11,21,15,'Kun Iisebel kuuli, että Naabot oli kivitetty kuoliaaksi, sanoi Iisebel Ahabille: "Nouse ja ota haltuusi jisreeliläisen Naabotin viinitarha, jota hän ei tahtonut antaa sinulle rahasta; sillä Naabot ei ole enää elossa, vaan on kuollut".'),
(1678382,58,11,21,16,'Kun Ahab kuuli, että Naabot oli kuollut, nousi hän ja lähti jisreeliläisen Naabotin viinitarhalle ottaakseen sen haltuunsa.'),
(1678383,58,11,21,17,'Mutta tisbeläiselle Elialle tuli tämä Herran sana:'),
(1678384,58,11,21,18,'"Nouse ja mene tapaamaan Ahabia, Israelin kuningasta, joka asuu Samariassa. Katso, hän on Naabotin viinitarhassa, jota hän on mennyt ottamaan haltuunsa.'),
(1678385,58,11,21,19,'Ja puhu hänelle ja sano: ''Näin sanoo Herra: Oletko sinä sekä tappanut että anastanut perinnön?'' Ja puhu sitten hänelle ja sano: ''Näin sanoo Herra: Siinä paikassa, missä koirat nuoleskelivat Naabotin veren, tulevat koirat nuoleskelemaan sinunkin veresi''."'),
(1678386,58,11,21,20,'Ahab sanoi Elialle: "Joko löysit minut, sinä vihamieheni?" Hän vastasi: "Jo löysin. Koska sinä olet myynyt itsesi tekemään sitä, mikä on pahaa Herran silmissä,'),
(1678387,58,11,21,21,'niin katso, minä annan onnettomuuden kohdata sinua ja lakaisen sinut pois ja hävitän Israelista Ahabin miespuoliset jälkeläiset, kaikki tyynni.'),
(1678388,58,11,21,22,'Ja minä teen sinun suvullesi niinkuin Jerobeamin, Nebatin pojan, suvulle ja niinkuin Baesan, Ahian pojan, suvulle, koska sinä olet vihoittanut minut ja saattanut Israelin tekemään syntiä.'),
(1678389,58,11,21,23,'Myöskin Iisebelistä on Herra puhunut sanoen: Koirat syövät Iisebelin Jisreelin muurin luona.'),
(1678390,58,11,21,24,'Joka Ahabin jälkeläisistä kuolee kaupungissa, sen koirat syövät, ja joka kuolee kedolle, sen syövät taivaan linnut."'),
(1678391,58,11,21,25,'Totisesti ei ole ollut ketään, joka olisi niin myynyt itsensä tekemään sitä, mikä on pahaa Herran silmissä, kuin Ahab, kun hänen vaimonsa Iisebel vietteli häntä.'),
(1678392,58,11,21,26,'Hän teki ylen kauhistavasti, kun lähti seuraamaan kivijumalia, aivan niinkuin amorilaiset tekivät, jotka Herra karkoitti israelilaisten tieltä.'),
(1678393,58,11,21,27,'Mutta kun Ahab kuuli nämä sanat, repäisi hän vaatteensa, pani paljaalle iholleen säkin ja paastosi. Ja hän makasi säkki yllänsä ja liikkui hiljaa.'),
(1678394,58,11,21,28,'Niin tisbeläiselle Elialle tuli tämä Herran sana:'),
(1678395,58,11,21,29,'"Oletko nähnyt, kuinka Ahab on nöyrtynyt minun edessäni? Koska hän on nöyrtynyt minun edessäni, en minä anna onnettomuuden tulla hänen aikanansa: hänen poikansa aikana minä annan onnettomuuden kohdata hänen sukuansa."'),
(1678396,58,11,22,1,'He olivat alallaan kolme vuotta: ei ollut sotaa Aramin ja Israelin välillä.'),
(1678397,58,11,22,2,'Mutta kolmantena vuotena tuli Joosafat, Juudan kuningas, Israelin kuninkaan luo.'),
(1678398,58,11,22,3,'Ja Israelin kuningas sanoi palvelijoillensa: "Tiedättehän, että Gileadin Raamot on meidän. Ja kuitenkin me olemme toimettomat emmekä ota sitä pois Aramin kuninkaan käsistä."'),
(1678399,58,11,22,4,'Ja hän sanoi Joosafatille: "Lähdetkö sinä minun kanssani sotaan Gileadin Raamotiin?" Joosafat vastasi Israelin kuninkaalle: "Minä niinkuin sinä, minun kansani niinkuin sinun kansasi, minun hevoseni niinkuin sinun hevosesi!"'),
(1678400,58,11,22,5,'Mutta Joosafat sanoi Israelin kuninkaalle: "Kysy kuitenkin ensin, mitä Herra sanoo".'),
(1678401,58,11,22,6,'Niin Israelin kuningas kokosi profeetat, noin neljäsataa miestä, ja sanoi heille: "Onko minun lähdettävä sotaan Gileadin Raamotia vastaan vai oltava lähtemättä?" He vastasivat: "Lähde; Herra antaa sen kuninkaan käsiin".'),
(1678402,58,11,22,7,'Mutta Joosafat sanoi: "Eikö täällä ole enää ketään muuta Herran profeettaa, jolta voisimme kysyä?"'),
(1678403,58,11,22,8,'Israelin kuningas vastasi Joosafatille: "On täällä vielä mies, jolta voisimme kysyä Herran mieltä, mutta minä vihaan häntä, sillä hän ei koskaan ennusta minulle hyvää, vaan aina pahaa; se on Miika, Jimlan poika". Joosafat sanoi: "Älköön kuningas niin puhuko".'),
(1678404,58,11,22,9,'Niin Israelin kuningas kutsui erään hoviherran ja sanoi: "Nouda kiiruusti Miika, Jimlan poika".'),
(1678405,58,11,22,10,'Mutta Israelin kuningas ja Joosafat, Juudan kuningas, istuivat kumpikin valtaistuimellansa, puettuina kuninkaallisiin pukuihinsa, puimatantereella Samarian portin ovella; ja kaikki profeetat olivat hurmoksissa heidän edessänsä.'),
(1678406,58,11,22,11,'Ja Sidkia, Kenaanan poika, teki itsellensä rautasarvet ja sanoi: "Näin sanoo Herra: Näillä sinä pusket aramilaisia, kunnes teet heistä lopun".'),
(1678407,58,11,22,12,'Ja kaikki profeetat ennustivat samalla tavalla, sanoen: "Mene Gileadin Raamotiin, niin sinä saat voiton; Herra antaa sen kuninkaan käsiin".'),
(1678408,58,11,22,13,'Ja sanansaattaja, joka oli mennyt kutsumaan Miikaa, puhui hänelle sanoen: "Katso, kaikki profeetat ovat yhdestä suusta luvanneet kuninkaalle hyvää; olkoon sinun sanasi heidän sanansa kaltainen, ja lupaa sinäkin hyvää".'),
(1678409,58,11,22,14,'Mutta Miika vastasi: "Niin totta kuin Herra elää, sen minä puhun, minkä Herra minulle sanoo".'),
(1678410,58,11,22,15,'Kun hän tuli kuninkaan eteen, sanoi kuningas hänelle: "Miika, onko meidän lähdettävä sotaan Gileadin Raamotiin vai oltava lähtemättä?" Hän vastasi hänelle: "Lähde, niin saat voiton; Herra antaa sen kuninkaan käsiin".'),
(1678411,58,11,22,16,'Mutta kuningas sanoi hänelle: "Kuinka monta kertaa minun on vannotettava sinua, ettet puhu minulle muuta kuin totuutta Herran nimessä?"'),
(1678412,58,11,22,17,'Silloin hän sanoi: "Minä näin koko Israelin hajallaan vuorilla niinkuin lampaat, joilla ei ole paimenta. Ja Herra sanoi: ''Näillä ei ole isäntää; palatkoot he kukin rauhassa kotiinsa''."'),
(1678413,58,11,22,18,'Niin Israelin kuningas sanoi Joosafatille: "Enkö minä sanonut sinulle, ettei tämä koskaan ennusta minulle hyvää, vaan aina pahaa?"'),
(1678414,58,11,22,19,'Mutta hän sanoi: "Kuule siis Herran sana: Minä näin Herran istuvan istuimellansa ja kaiken taivaan joukon seisovan hänen edessään, hänen oikealla ja vasemmalla puolellansa.'),
(1678415,58,11,22,20,'Ja Herra sanoi: ''Kuka viekoittelisi Ahabin lähtemään sotaan, että hän kaatuisi Gileadin Raamotissa?'' Mikä vastasi niin, mikä näin.'),
(1678416,58,11,22,21,'Silloin tuli henki ja asettui Herran eteen ja sanoi: ''Minä viekoittelen hänet''. Herra kysyi häneltä: ''Miten?'''),
(1678417,58,11,22,22,'Hän vastasi: ''Minä menen valheen hengeksi kaikkien hänen profeettainsa suuhun''. Silloin Herra sanoi: ''Saat viekoitella, siihen sinä pystyt; mene ja tee niin''.'),
(1678418,58,11,22,23,'Katso, nyt Herra on pannut valheen hengen kaikkien näiden sinun profeettaisi suuhun, sillä Herra on päättänyt sinun osaksesi onnettomuuden."'),
(1678419,58,11,22,24,'Silloin astui esille Sidkia, Kenaanan poika, löi Miikaa poskelle ja sanoi: "Mitä tietä Herran henki on poistunut minusta puhuakseen sinun kanssasi?"'),
(1678420,58,11,22,25,'Miika vastasi: "Sen saat nähdä sinä päivänä, jona kuljet huoneesta huoneeseen piiloutuaksesi".'),
(1678421,58,11,22,26,'Mutta Israelin kuningas sanoi: "Ota Miika ja vie hänet takaisin Aamonin, kaupungin päällikön, ja Jooaan, kuninkaan pojan, luo.'),
(1678422,58,11,22,27,'Ja sano: ''Näin sanoo kuningas: Pankaa tämä vankilaan ja elättäkää häntä vaivaisella vedellä ja leivällä, kunnes minä palaan voittajana takaisin''."'),
(1678423,58,11,22,28,'Miika vastasi: "Jos sinä palaat voittajana takaisin, niin ei Herra ole puhunut minun kauttani". Ja hän sanoi vielä: "Kuulkaa tämä, kaikki kansat".'),
(1678424,58,11,22,29,'Niin Israelin kuningas ja Joosafat, Juudan kuningas, menivät Gileadin Raamotiin.'),
(1678425,58,11,22,30,'Ja Israelin kuningas sanoi Joosafatille: "Täytyypä pukeutua tuntemattomaksi, kun käy taisteluun, mutta ole sinä omissa vaatteissasi". Ja Israelin kuningas pukeutui tuntemattomaksi ja kävi taisteluun.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678426,58,11,22,31,'Mutta Aramin kuningas oli käskenyt sotavaunujen päälliköitä, joita hänellä oli kolmekymmentä kaksi, sanoen: "Älkää ryhtykö taisteluun kenenkään muun kanssa, olkoon alempi tai ylempi, kuin ainoastaan Israelin kuninkaan kanssa".'),
(1678427,58,11,22,32,'Kun sotavaunujen päälliköt näkivät Joosafatin, ajattelivat he: "Tuo on varmaankin Israelin kuningas", ja kääntyivät hyökkäämään häntä vastaan. Silloin Joosafat huusi.'),
(1678428,58,11,22,33,'Kun sotavaunujen päälliköt näkivät, ettei se ollutkaan Israelin kuningas, vetäytyivät he hänestä pois.'),
(1678429,58,11,22,34,'Mutta eräs mies, joka oli jännittänyt jousensa ja ampui umpimähkään, satutti Israelin kuningasta vyöpanssarin ja rintahaarniskan väliin. Niin tämä sanoi vaunujensa ohjaajalle: "Käännä vaunut ja vie minut pois sotarinnasta, sillä minä olen haavoittunut".'),
(1678430,58,11,22,35,'Mutta kun taistelu sinä päivänä yltyi yltymistään, jäi kuningas seisomaan vaunuihinsa, päin aramilaisia. Illalla hän kuoli; ja verta oli vuotanut haavasta vaununpohjaan.'),
(1678431,58,11,22,36,'Ja auringon laskiessa kaikui kautta sotajoukon huuto: "Joka mies kaupunkiinsa! Joka mies maahansa!"'),
(1678432,58,11,22,37,'Näin kuoli kuningas, ja hänet vietiin Samariaan; ja kuningas haudattiin Samariaan.'),
(1678433,58,11,22,38,'Ja kun vaunut huuhdottiin Samarian lammikolla, nuoleskelivat koirat hänen vertansa, ja portot peseytyivät siinä, sen sanan mukaan, jonka Herra oli puhunut.'),
(1678434,58,11,22,39,'Mitä muuta on kerrottavaa Ahabista ja kaikesta, mitä hän teki, siitä norsunluisesta palatsista, jonka hän rakensi, ja kaikista kaupungeista, jotka hän linnoitti, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678435,58,11,22,40,'Ja niin Ahab meni lepoon isiensä tykö. Ja hänen poikansa Ahasja tuli kuninkaaksi hänen sijaansa.'),
(1678436,58,11,22,41,'Joosafat, Aasan poika, tuli Juudan kuninkaaksi Ahabin, Israelin kuninkaan, neljäntenä hallitusvuotena.'),
(1678437,58,11,22,42,'Joosafat oli kolmenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi kaksikymmentä viisi vuotta Jerusalemissa. Hänen äitinsä oli nimeltään Asuba, Silhin tytär.'),
(1678438,58,11,22,43,'Ja hän vaelsi kaikessa isänsä Aasan tietä, siltä poikkeamatta, ja teki sitä, mikä oli oikein Herran silmissä.'),
(1678439,58,11,22,44,'Mutta uhrikukkulat eivät hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla.'),
(1678440,58,11,22,45,'Ja Joosafat teki rauhan Israelin kuninkaan kanssa.'),
(1678441,58,11,22,46,'Mitä muuta on kerrottavaa Joosafatista, hänen urotöistään ja hänen sodistaan, se on kirjoitettuna Juudan kuningasten aikakirjassa.'),
(1678442,58,11,22,47,'Hän hävitti maasta viimeiset niistä haureellisista pyhäkköpojista, jotka olivat jääneet jäljelle hänen isänsä Aasan ajoilta.'),
(1678443,58,11,22,48,'Edomissa ei siihen aikaan ollut kuningasta; maaherra oli kuninkaana.'),
(1678444,58,11,22,49,'Ja Joosafat oli teettänyt Tarsiin-laivoja, joiden oli määrä kulkea Oofiriin kultaa noutamaan; mutta laivat eivät päässeet lähtemään, sillä ne särkyivät Esjon-Geberissä.'),
(1678445,58,11,22,50,'Silloin Ahasja, Ahabin poika, sanoi Joosafatille: "Anna minun palvelijaini kulkea sinun palvelijaisi kanssa laivoissa". Mutta Joosafat ei tahtonut.'),
(1678446,58,11,22,51,'Ja Joosafat meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen hänen isänsä Daavidin kaupunkiin. Ja hänen poikansa Jooram tuli kuninkaaksi hänen sijaansa.'),
(1678447,58,11,22,52,'Ahasja, Ahabin poika, tuli Israelin kuninkaaksi Samariassa Joosafatin, Juudan kuninkaan, seitsemäntenätoista hallitusvuotena, ja hän hallitsi Israelia kaksi vuotta.'),
(1678448,58,11,22,53,'Hän teki sitä, mikä on pahaa Herran silmissä, ja vaelsi isänsä ja äitinsä tietä ja Jerobeamin, Nebatin pojan, tietä, hänen, joka oli saattanut Israelin tekemään syntiä.'),
(1678449,58,12,1,1,'Ahabin kuoleman jälkeen Mooab luopui Israelista.'),
(1678450,58,12,1,2,'Ahasja putosi Samariassa yläsalinsa ristikon läpi ja makasi sairaana. Ja hän lähetti sanansaattajia ja sanoi heille: "Menkää ja kysykää Baal-Sebubilta, Ekronin jumalalta, toivunko minä tästä taudista".'),
(1678451,58,12,1,3,'Mutta Herran enkeli oli sanonut tisbeläiselle Elialle: "Nouse ja mene Samarian kuninkaan sanansaattajia vastaan ja sano heille: ''Eikö ole Jumalaa Israelissa, koska menette kysymään neuvoa Baal-Sebubilta, Ekronin jumalalta?'''),
(1678452,58,12,1,4,'Sentähden sanoo Herra näin: ''Vuoteesta, johon olet noussut, et sinä enää astu alas, sillä sinun on kuoltava''." Ja Elia lähti tiehensä.'),
(1678453,58,12,1,5,'Kun sanansaattajat sitten palasivat kuninkaan luo, kysyi hän heiltä: "Minkätähden te tulette takaisin?"'),
(1678454,58,12,1,6,'He vastasivat hänelle: "Meitä vastaan tuli mies, joka sanoi meille: ''Menkää takaisin kuninkaan luo, joka on teidät lähettänyt, ja sanokaa hänelle: Näin sanoo Herra: Eikö ole Jumalaa Israelissa, koska sinä lähetät kysymään neuvoa Baal-Sebubilta, Ekronin jumalalta? Sentähden sinä et enää astu alas vuoteesta, johon olet noussut, sillä sinun on kuoltava.''"'),
(1678455,58,12,1,7,'Hän kysyi heiltä: "Minkä näköinen oli mies, joka tuli teitä vastaan ja puhui teille näitä?"'),
(1678456,58,12,1,8,'He vastasivat hänelle: "Hänellä oli yllään karvanahka ja nahkavyö vyötäisillä". Silloin hän sanoi: "Se oli tisbeläinen Elia".'),
(1678457,58,12,1,9,'Ja hän lähetti hänen luokseen viidenkymmenenpäämiehen ja hänen viisikymmentä miestänsä. Ja kun tämä tuli hänen luoksensa, hänen istuessaan vuoren kukkulalla, sanoi hän hänelle: "Sinä Jumalan mies, kuningas käskee: Tule alas".'),
(1678458,58,12,1,10,'Mutta Elia vastasi ja sanoi viidenkymmenenpäämiehelle: "Jos minä olen Jumalan mies, niin tulkoon tuli taivaasta ja kuluttakoon sinut ja sinun viisikymmentä miestäsi". Silloin tuli taivaasta tuli ja kulutti hänet ja hänen viisikymmentä miestänsä.'),
(1678459,58,12,1,11,'Hän lähetti taas hänen luoksensa toisen viidenkymmenenpäämiehen ja hänen viisikymmentä miestänsä. Tämä lausui ja sanoi hänelle: "Sinä Jumalan mies, näin käskee kuningas: Tule kiiruusti alas".'),
(1678460,58,12,1,12,'Mutta Elia vastasi ja sanoi heille: "Jos minä olen Jumalan mies, niin tulkoon tuli taivaasta ja kuluttakoon sinut ja sinun viisikymmentä miestäsi". Silloin tuli taivaasta Jumalan tuli ja kulutti hänet ja hänen viisikymmentä miestänsä.'),
(1678461,58,12,1,13,'Hän lähetti vielä kolmannen viidenkymmenenpäämiehen ja hänen viisikymmentä miestänsä. Ja tämä kolmas viidenkymmenenpäämies meni sinne, ja kun hän tuli perille, polvistui hän Elian eteen ja anoi häneltä armoa ja sanoi hänelle: "Sinä Jumalan mies, olkoon minun henkeni ja näiden viidenkymmenen palvelijasi henki kallis sinun silmissäsi.'),
(1678462,58,12,1,14,'Katso, tuli on tullut taivaasta ja kuluttanut ne kaksi ensimmäistä viidenkymmenenpäämiestä ja heidän viisikymmentä miestänsä, mutta olkoon minun henkeni kallis sinun silmissäsi."'),
(1678463,58,12,1,15,'Ja Herran enkeli sanoi Elialle: "Mene alas hänen kanssaan, älä pelkää häntä". Niin hän nousi ja meni hänen kanssaan kuninkaan tykö.'),
(1678464,58,12,1,16,'Ja hän sanoi hänelle: "Näin sanoo Herra: Koska lähetit sanansaattajia kysymään neuvoa Baal-Sebubilta, Ekronin jumalalta, ikäänkuin Israelissa ei olisi Jumalaa, jolta voisi kysyä neuvoa, sentähden sinä et astu alas vuoteesta, johon olet noussut, sillä sinun on kuoltava".'),
(1678465,58,12,1,17,'Niin hän kuoli, Herran sanan mukaan, jonka Elia oli puhunut. Ja Jooram tuli kuninkaaksi hänen sijaansa Jooramin, Joosafatin pojan, Juudan kuninkaan, toisena hallitusvuotena, sillä Ahasjalla ei ollut poikaa.'),
(1678466,58,12,1,18,'Mitä muuta on kerrottavaa Ahasjasta, siitä, mitä hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678467,58,12,2,1,'Silloin, kun Herra oli vievä Elian tuulispäässä taivaaseen, kulkivat Elia ja Elisa Gilgalista.'),
(1678468,58,12,2,2,'Ja Elia sanoi Elisalle: "Jää tähän, sillä Herra on lähettänyt minut Beeteliin asti". Mutta Elisa vastasi: "Niin totta kuin Herra elää, ja niin totta kuin sinun sielusi elää: minä en jätä sinua". Ja he menivät Beeteliin.'),
(1678469,58,12,2,3,'Niin Beetelissä olevat profeetanoppilaat tulivat Elisan tykö ja sanoivat hänelle: "Tiedätkö, että Herra tänä päivänä ottaa sinun herrasi pois sinun pääsi ylitse?" Hän vastasi: "Tiedän kyllä; olkaa vaiti".'),
(1678470,58,12,2,4,'Ja Elia sanoi hänelle: "Elisa, jää tähän, sillä Herra on lähettänyt minut Jerikoon". Mutta hän vastasi: "Niin totta kuin Herra elää, ja niin totta kuin sinun sielusi elää: minä en jätä sinua". Ja he tulivat Jerikoon.'),
(1678471,58,12,2,5,'Niin Jerikossa olevat profeetanoppilaat astuivat Elisan tykö ja sanoivat hänelle: "Tiedätkö, että Herra tänä päivänä ottaa herrasi pois sinun pääsi ylitse?" Hän vastasi: "Tiedän kyllä; olkaa vaiti".'),
(1678472,58,12,2,6,'Ja Elia sanoi hänelle: "Jää tähän, sillä Herra on lähettänyt minut Jordanille". Mutta hän vastasi: "Niin totta kuin Herra elää, ja niin totta kuin sinun sielusi elää: minä en jätä sinua". Niin he kulkivat molemmat yhdessä.'),
(1678473,58,12,2,7,'Mutta myös profeetanoppilaita lähti matkaan viisikymmentä miestä, ja he asettuivat syrjään jonkun matkan päähän näiden kahden pysähtyessä Jordanille.'),
(1678474,58,12,2,8,'Niin Elia otti vaippansa, kääri sen kokoon ja löi veteen; ja vesi jakaantui kummallekin puolelle, ja he kävivät molemmat virran yli kuivaa myöten.'),
(1678475,58,12,2,9,'Kun he olivat tulleet yli, sanoi Elia Elisalle: "Pyydä minua tekemään hyväksesi jotakin, ennenkuin minut otetaan pois sinun tyköäsi". Elisa sanoi: "Tulkoon minuun sinun hengestäsi kaksinkertainen osa".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678476,58,12,2,10,'Hän vastasi: "Pyyntösi on vaikea täyttää. Mutta jos näet, kuinka minut otetaan pois sinun tyköäsi, niin se täytetään; jollet, niin se jää täyttämättä."'),
(1678477,58,12,2,11,'Kun he niin kulkivat ja puhelivat, niin katso, äkkiä ilmestyivät tuliset vaunut ja tuliset hevoset, ja ne erottivat heidät toisistansa, ja Elia nousi tuulispäässä taivaaseen.'),
(1678478,58,12,2,12,'Kun Elisa sen näki, huusi hän: "Isäni, isäni! Israelin sotavaunut ja ratsumiehet!" Sitten hän ei enää nähnyt häntä. Ja hän tarttui vaatteisiinsa ja repäisi ne kahdeksi kappaleeksi.'),
(1678479,58,12,2,13,'Sitten hän otti maasta Elian vaipan, joka oli pudonnut hänen päältään, palasi takaisin ja pysähtyi Jordanin rannalle.'),
(1678480,58,12,2,14,'Ja hän otti Elian vaipan, joka oli pudonnut tämän päältä, löi veteen ja sanoi: "Missä on Herra, Elian Jumala?" Kun hän siis löi veteen, jakaantui se kummallekin puolelle, ja Elisa kävi virran yli.'),
(1678481,58,12,2,15,'Kun Jerikosta tulleet profeetanoppilaat syrjästä näkivät sen, sanoivat he: "Elian henki on laskeutunut Elisaan". Niin he tulivat häntä vastaan ja kumartuivat hänen edessään maahan.'),
(1678482,58,12,2,16,'Ja he sanoivat hänelle: "Katso, palvelijaisi joukossa on viisikymmentä urhoollista miestä; menkööt he etsimään sinun isäntääsi. Ehkä Herran Henki on vienyt hänet ja heittänyt jollekin vuorelle tai johonkin laaksoon." Hän vastasi: "Älkää lähettäkö".'),
(1678483,58,12,2,17,'Mutta he pyysivät häntä pyytämällä, kyllästyksiin asti, kunnes hän sanoi: "Lähettäkää sitten". Niin he lähettivät viisikymmentä miestä; ja nämä etsivät kolme päivää, mutta eivät löytäneet häntä.'),
(1678484,58,12,2,18,'Kun he tulivat takaisin hänen luoksensa, hänen ollessaan Jerikossa, sanoi hän heille: "Enkö minä kieltänyt teitä menemästä?"'),
(1678485,58,12,2,19,'Ja kaupungin miehet sanoivat Elisalle: "Katso, kaupungin asema on hyvä, niinkuin herrani näkee, mutta vesi on huonoa, ja maassa syntyy keskoisia".'),
(1678486,58,12,2,20,'Hän sanoi: "Tuokaa minulle uusi malja ja pankaa siihen suoloja". Ja he toivat sen hänelle.'),
(1678487,58,12,2,21,'Niin hän meni vesien lähteelle ja heitti siihen suolat, sanoen: "Näin sanoo Herra: Minä olen parantanut tämän veden; siitä ei enää tule kuolemaa eikä keskenmenoa".'),
(1678488,58,12,2,22,'Niin vesi tuli terveelliseksi, aina tähän päivään asti, Elisan sanan mukaan, jonka hän puhui.'),
(1678489,58,12,2,23,'Sieltä hän meni Beeteliin, ja hänen käydessään tietä tuli pieniä poikasia kaupungista, ja ne pilkkasivat häntä ja sanoivat hänelle: "Tule ylös, kaljupää, tule ylös, kaljupää!"'),
(1678490,58,12,2,24,'Ja kun hän kääntyi ja näki heidät, kirosi hän heidät Herran nimeen. Silloin tuli metsästä kaksi karhua ja raateli neljäkymmentä kaksi poikaa kuoliaaksi.'),
(1678491,58,12,2,25,'Sieltä hän meni Karmel-vuorelle ja palasi sieltä Samariaan.'),
(1678492,58,12,3,1,'Jooram, Ahabin poika, tuli Israelin kuninkaaksi Samariassa Joosafatin, Juudan kuninkaan, kahdeksantenatoista hallitusvuotena, ja hän hallitsi kaksitoista vuotta.'),
(1678493,58,12,3,2,'Hän teki sitä, mikä on pahaa Herran silmissä, ei kuitenkaan niinkuin hänen isänsä ja äitinsä, sillä hän poisti Baalin patsaan, jonka hänen isänsä oli teettänyt.'),
(1678494,58,12,3,3,'Kuitenkin hän riippui kiinni Jerobeamin, Nebatin pojan, synnissä, jolla tämä oli saattanut Israelin tekemään syntiä; siitä hän ei luopunut.'),
(1678495,58,12,3,4,'Meesa, Mooabin kuningas, omisti lammaslaumoja ja maksoi verona Israelin kuninkaalle satatuhatta karitsaa ja sadantuhannen oinaan villat.'),
(1678496,58,12,3,5,'Mutta Ahabin kuoltua Mooabin kuningas luopui Israelin kuninkaasta.'),
(1678497,58,12,3,6,'Siihen aikaan lähti kuningas Jooram Samariasta ja katsasti kaiken Israelin.'),
(1678498,58,12,3,7,'Ja hän meni ja lähetti Joosafatille Juudan kuninkaalle sanan: "Mooabin kuningas on luopunut minusta. Lähdetkö minun kanssani sotaan Mooabia vastaan?" Hän vastasi: "Lähden; minä niinkuin sinä, minun kansani niinkuin sinun kansasi, minun hevoseni niinkuin sinun hevosesi!"'),
(1678499,58,12,3,8,'Ja Joosafat kysyi: "Mitä tietä meidän on sinne mentävä?" Hän vastasi: "Edomin erämaan tietä".'),
(1678500,58,12,3,9,'Niin Israelin kuningas, Juudan kuningas ja Edomin kuningas lähtivät liikkeelle. Mutta kun he olivat kierrellen kulkeneet seitsemän päivän matkan eikä ollut vettä sotajoukolle eikä juhdille, jotka seurasivat heitä,'),
(1678501,58,12,3,10,'sanoi Israelin kuningas: "Voi, Herra on kutsunut nämä kolme kuningasta kokoon antaakseen heidät Mooabin käsiin!"'),
(1678502,58,12,3,11,'Mutta Joosafat sanoi: "Eikö täällä ole ketään Herran profeettaa, kysyäksemme hänen kauttaan neuvoa Herralta?" Silloin eräs Israelin kuninkaan palvelijoista vastasi ja sanoi: "Täällä on Elisa, Saafatin poika, joka vuodatti vettä Elian käsille".'),
(1678503,58,12,3,12,'Joosafat sanoi: "Hänellä on Herran sana". Niin Israelin kuningas, Joosafat ja Edomin kuningas menivät hänen tykönsä.'),
(1678504,58,12,3,13,'Ja Elisa sanoi Israelin kuninkaalle: "Mitä minulla on tekemistä sinun kanssasi? Mene isäsi ja äitisi profeettain tykö." Israelin kuningas sanoi hänelle: "Ei niin! Sillä Herra on kutsunut nämä kolme kuningasta kokoon antaakseen heidät Mooabin käsiin."'),
(1678505,58,12,3,14,'Elisa sanoi: "Niin totta kuin Herra Sebaot elää, jonka edessä minä seison: jollen tahtoisi tehdä Joosafatille, Juudan kuninkaalle, mieliksi, niin minä tosiaankaan en katsoisi sinuun enkä huomaisi sinua.'),
(1678506,58,12,3,15,'Mutta tuokaa minulle nyt kanteleensoittaja." Ja kun kanteleensoittaja soitti, niin Herran käsi laskeutui hänen päällensä,'),
(1678507,58,12,3,16,'ja hän sanoi: "Näin sanoo Herra: Tehkää tämä laakso kuoppia täyteen.'),
(1678508,58,12,3,17,'Sillä näin sanoo Herra: Te ette tule näkemään tuulta ettekä sadetta, ja kuitenkin tämä laakso tulee vettä täyteen; ja te saatte juoda, sekä te että teidän karjanne ja juhtanne.'),
(1678509,58,12,3,18,'Mutta tämä on Herran silmissä pieni asia: hän antaa Mooabin teidän käsiinne,'),
(1678510,58,12,3,19,'ja niin te valloitatte kaikki varustetut kaupungit ja kaikki valitut kaupungit, kaadatte kaikki hedelmäpuut, tukitte kaikki vesilähteet ja turmelette kivillä kaikki hyvät peltopalstat."'),
(1678511,58,12,3,20,'Ja katso, seuraavana aamuna, sinä hetkenä, jona ruokauhri uhrataan, tuli vettä Edomista päin, niin että maa tuli vettä täyteen.'),
(1678512,58,12,3,21,'Kun kaikki mooabilaiset kuulivat, että kuninkaat olivat lähteneet sotaan heitä vastaan, kutsuttiin koolle kaikki miekkaan vyöttäytyvät ja myös vanhemmat miehet, ja he asettuivat rajalle.'),
(1678513,58,12,3,22,'Mutta varhain aamulla, kun aurinko nousi ja paistoi veteen, näkivät mooabilaiset, että vesi heidän edessään oli punaista kuin veri.'),
(1678514,58,12,3,23,'Ja he sanoivat: "Se on verta; varmaan kuninkaat ovat joutuneet taisteluun keskenään ja surmanneet toisensa. Ja nyt saaliin ryöstöön, Mooab!"'),
(1678515,58,12,3,24,'Mutta kun he tulivat Israelin leiriin, nousivat israelilaiset ja voittivat mooabilaiset, niin että nämä pakenivat heitä. Ja he hyökkäsivät maahan ja voittivat uudelleen mooabilaiset.'),
(1678516,58,12,3,25,'Ja he hävittivät kaupungit, kaikille hyville peltopalstoille heitti kukin heistä kiven, täyttäen ne; he tukkivat kaikki vesilähteet ja kaatoivat kaikki hedelmäpuut, niin että ainoastaan Kiir-Haresetissa jäivät kivet paikoilleen. Ja linkomiehet piirittivät kaupungin ja ampuivat sitä.'),
(1678517,58,12,3,26,'Kun Mooabin kuningas näki joutuvansa tappiolle taistelussa, otti hän mukaansa seitsemänsataa miekkamiestä murtautuakseen Edomin kuninkaan luo; mutta he eivät voineet.'),
(1678518,58,12,3,27,'Niin hän otti poikansa, esikoisensa, joka oli tuleva kuninkaaksi hänen sijaansa, ja uhrasi hänet polttouhriksi muurilla. Silloin suuri viha kohtasi Israelia, niin että he lähtivät sieltä ja palasivat omaan maahansa.'),
(1678519,58,12,4,1,'Eräs nainen, profeetanoppilaan vaimo, huusi Elisalle sanoen: "Minun mieheni, sinun palvelijasi, kuoli, ja sinä tiedät, että palvelijasi oli herraapelkääväinen mies. Nyt velkoja tulee ottamaan minun molemmat poikani orjikseen."'),
(1678520,58,12,4,2,'Elisa sanoi hänelle: "Mitä minä voin tehdä sinun hyväksesi? Sano minulle, mitä sinulla on talossasi." Hän vastasi: "Palvelijattarellasi ei ole talossa muuta kuin öljyä sen verran, kuin minä tarvitsen voidellakseni itseäni".'),
(1678521,58,12,4,3,'Silloin hän sanoi: "Mene ja lainaa itsellesi astioita kylästä, kaikilta naapureiltasi, tyhjiä astioita, tarpeeksi paljon.'),
(1678522,58,12,4,4,'Mene sitten sisään, sulje ovi jälkeesi ja poikiesi jälkeen ja kaada kaikkiin niihin astioihin. Ja aina kun astia on täysi, nosta se syrjään."'),
(1678523,58,12,4,5,'Niin hän meni pois hänen tyköänsä ja sulki oven jälkeensä ja poikiensa jälkeen. Nämä toivat sitten hänelle astiat, ja hän kaatoi niihin.'),
(1678524,58,12,4,6,'Ja kun astiat olivat täynnä, sanoi hän pojallensa: "Tuo minulle vielä yksi astia". Mutta hän vastasi hänelle: "Ei ole enää astiata". Silloin öljy tyrehtyi.'),
(1678525,58,12,4,7,'Ja hän meni ja kertoi sen Jumalan miehelle. Tämä sanoi: "Mene ja myy öljy ja maksa velkasi. Sinä ja poikasi elätte siitä, mikä jää jäljelle."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678526,58,12,4,8,'Eräänä päivänä Elisa meni Suunemiin, ja siellä oli arvossa pidetty vaimo, joka vaati häntä aterioimaan. Ja niin usein kuin hän kulki sen kautta, poikkesi hän sinne aterioimaan.'),
(1678527,58,12,4,9,'Niin vaimo sanoi miehellensä: "Katso, minä olen huomannut, että hän, joka aina kulkee meidän kauttamme, on pyhä Jumalan mies.'),
(1678528,58,12,4,10,'Muurauttakaamme pieni yliskammio ja pankaamme hänelle sinne vuode, pöytä, tuoli ja lamppu, niin että hän tullessaan meidän luoksemme voi vetäytyä sinne."'),
(1678529,58,12,4,11,'Eräänä päivänä hän sitten tuli sinne, poikkesi yliskammioon ja pani sinne maata.'),
(1678530,58,12,4,12,'Ja hän sanoi palvelijallensa Geehasille: "Kutsu se suunemilainen vaimo". Ja hän kutsui tämän, ja hän astui hänen eteensä.'),
(1678531,58,12,4,13,'Niin hän sanoi palvelijalle: "Sano hänelle: ''Katso, sinä olet nähnyt kaiken tämän vaivan meidän tähtemme. Voisinko minä tehdä jotakin sinun hyväksesi? Onko sinulla jotakin esitettävää kuninkaalle tai sotapäällikölle?''" Mutta hän vastasi: "Minähän asun heimoni keskellä".'),
(1678532,58,12,4,14,'Niin hän kysyi: "Eikö siis voi tehdä mitään hänen hyväksensä?" Geehasi vastasi: "Voi kyllä: hänellä ei ole poikaa, ja hänen miehensä on vanha".'),
(1678533,58,12,4,15,'Hän sanoi: "Kutsu hänet". Niin tämä kutsui hänet, ja hän astui ovelle.'),
(1678534,58,12,4,16,'Ja Elisa sanoi: "Tähän aikaan tulevana vuonna on sinulla poika sylissäsi". Hän vastasi: "Ei, herrani; sinä Jumalan mies, älä petä palvelijatartasi".'),
(1678535,58,12,4,17,'Mutta vaimo tuli raskaaksi ja synnytti pojan seuraavana vuonna juuri sinä aikana, jonka Elisa oli hänelle sanonut.'),
(1678536,58,12,4,18,'Kun poika oli kasvanut isoksi, meni hän eräänä päivänä isänsä tykö, joka oli leikkuuväen luona.'),
(1678537,58,12,4,19,'Ja hän valitti isällensä: "Voi minun päätäni, voi minun päätäni!" Tämä sanoi palvelijalle: "Kanna hänet äitinsä luo".'),
(1678538,58,12,4,20,'Niin palvelija otti hänet ja vei hänen äitinsä luo. Ja poika istui hänen polvillansa puolipäivään asti; sitten hän kuoli.'),
(1678539,58,12,4,21,'Ja äiti meni ylös ja laski hänet Jumalan miehen vuoteeseen, sulki oven, niin että poika jäi yksin, ja lähti pois.'),
(1678540,58,12,4,22,'Sitten hän kutsui miehensä ja sanoi: "Lähetä minulle palvelija ja aasintamma, niin minä riennän Jumalan miehen tykö ja tulen heti takaisin".'),
(1678541,58,12,4,23,'Hän sanoi: "Miksi menet hänen tykönsä tänä päivänä? Eihän nyt ole uusikuu eikä sapatti." Hän vastasi: "Ole huoleti".'),
(1678542,58,12,4,24,'Ja hän satuloi aasintamman ja sanoi palvelijallensa: "Aja yhä eteenpäin äläkä keskeytä minun matkaani, ennenkuin sanon sinulle".'),
(1678543,58,12,4,25,'Niin hän lähti ja tuli Jumalan miehen tykö Karmel-vuorelle. Kun Jumalan mies näki hänet kaukaa, sanoi hän palvelijalleen Geehasille: "Katso, se on suunemilainen vaimo.'),
(1678544,58,12,4,26,'Riennä nyt häntä vastaan ja kysy häneltä: ''Voitko sinä hyvin, voivatko miehesi ja poikasi hyvin?''" Hän vastasi: "Hyvin".'),
(1678545,58,12,4,27,'Tultuaan vuorelle Jumalan miehen tykö hän tarttui hänen jalkoihinsa. Niin Geehasi astui esiin työntääkseen hänet pois. Mutta Jumalan mies sanoi: "Jätä hänet rauhaan, sillä hänen sielunsa on murheellinen, ja Herra on salannut sen minulta eikä ole ilmoittanut sitä minulle".'),
(1678546,58,12,4,28,'Hän sanoi: "Pyysinkö minä poikaa herraltani? Enkö sanonut: ''Älä uskottele minulle''?"'),
(1678547,58,12,4,29,'Silloin Elisa sanoi Geehasille: "Vyötä kupeesi ja ota minun sauvani käteesi ja mene. Jos kohtaat jonkun, älä tervehdi häntä, ja jos joku tervehtii sinua, älä vastaa. Ja pane minun sauvani pojan kasvoille."'),
(1678548,58,12,4,30,'Mutta pojan äiti sanoi: "Niin totta kuin Herra elää, ja niin totta kuin sinun sielusi elää: minä en jätä sinua". Ja Elisa nousi ja seurasi häntä.'),
(1678549,58,12,4,31,'Mutta Geehasi oli mennyt heidän edellänsä ja pannut sauvan pojan kasvoille, mutta tämä ei ääntänyt eikä kuullut. Niin hän tuli takaisin häntä vastaan ja kertoi hänelle sanoen: "Poika ei herännyt".'),
(1678550,58,12,4,32,'Ja kun Elisa tuli huoneeseen, niin katso, poika makasi hänen vuoteessaan kuolleena.'),
(1678551,58,12,4,33,'Tultuaan sisään hän sulki oven, niin että he jäivät kahden, ja rukoili Herraa.'),
(1678552,58,12,4,34,'Senjälkeen hän nousi vuoteelle ja laskeutui pojan yli, pannen suunsa hänen suunsa päälle, silmänsä hänen silmiensä päälle ja kätensä hänen kättensä päälle. Ja kun hän näin kumartui hänen ylitsensä, lämpeni pojan ruumis.'),
(1678553,58,12,4,35,'Sitten hän kulki huoneessa kerran edestakaisin ja nousi ja kumartui hänen ylitsensä. Silloin poika aivasti seitsemän kertaa, ja senjälkeen poika avasi silmänsä.'),
(1678554,58,12,4,36,'Hän kutsui Geehasin ja sanoi: "Kutsu se suunemilainen vaimo". Niin hän kutsui vaimon, ja tämä tuli hänen luokseen. Hän sanoi: "Ota poikasi".'),
(1678555,58,12,4,37,'Ja vaimo tuli ja lankesi hänen jalkainsa juureen, kumartui maahan ja otti poikansa ja meni ulos.'),
(1678556,58,12,4,38,'Elisa palasi Gilgaliin, ja maassa oli nälänhätä. Ja kun profeetanoppilaat istuivat hänen edessänsä, sanoi hän palvelijallensa: "Pane suuri pata liedelle ja keitä keitto profeetanoppilaille".'),
(1678557,58,12,4,39,'Niin muuan heistä meni kedolle poimimaan yrttejä ja löysi villin köynnöskasvin ja poimi siitä villikurkkuja viittansa täyden. Tultuaan hän leikkeli ne keittopataan, sillä he eivät tunteneet niitä.'),
(1678558,58,12,4,40,'Ja he kaatoivat miesten syödä, mutta kun nämä maistoivat keittoa, huusivat he ja sanoivat: "Jumalan mies, padassa on kuolema!" Eivätkä he voineet syödä.'),
(1678559,58,12,4,41,'Silloin hän sanoi: "Tuokaa jauhoja". Ja hän heitti ne pataan. Sitten hän sanoi: "Kaatakaa väen syödä". Eikä padassa ollut mitään vahingollista.'),
(1678560,58,12,4,42,'Ja eräs mies tuli Baal-Saalisasta ja toi Jumalan miehelle uutisleipää, kaksikymmentä ohraleipää ja tuleentumatonta viljaa repussansa. Silloin Elisa sanoi: "Anna väelle syödä".'),
(1678561,58,12,4,43,'Mutta hänen palvelijansa sanoi: "Kuinka minä voin tarjota siitä sadalle miehelle?" Hän sanoi: "Anna väelle syödä; sillä näin sanoo Herra: He syövät, ja jää tähteeksikin".'),
(1678562,58,12,4,44,'Ja hän tarjosi heille; ja he söivät, ja jäi tähteeksikin, Herran sanan mukaan.'),
(1678563,58,12,5,1,'Naeman, Aramin kuninkaan sotapäällikkö, oli herransa hyvin arvossa pitämä ja suurta kunnioitusta nauttiva mies, sillä hänen kauttansa Herra oli antanut Aramille voiton; ja hän oli sotaurho, mutta pitalitautinen.'),
(1678564,58,12,5,2,'Kerran olivat aramilaiset menneet ryöstöretkelle ja tuoneet Israelin maasta vankina pienen tytön, joka joutui palvelukseen Naemanin puolisolle.'),
(1678565,58,12,5,3,'Tyttö sanoi emännällensä: "Oi, jospa herrani kävisi profeetan luona Samariassa! Hän kyllä päästäisi hänet hänen pitalistansa."'),
(1678566,58,12,5,4,'Niin Naeman meni ja kertoi tämän herrallensa, sanoen: "Niin ja niin on tyttö, joka on Israelin maasta, puhunut".'),
(1678567,58,12,5,5,'Aramin kuningas vastasi: "Mene vain sinne; minä lähetän kirjeen Israelin kuninkaalle". Niin Naeman lähti sinne ja otti mukaansa kymmenen talenttia hopeata, kuusituhatta sekeliä kultaa ja kymmenen juhlapukua.'),
(1678568,58,12,5,6,'Ja hän vei Israelin kuninkaalle kirjeen, joka kuului näin: "Kun tämä kirje tulee sinulle, niin katso, minä olen lähettänyt luoksesi palvelijani Naemanin, että sinä päästäisit hänet hänen pitalistansa".'),
(1678569,58,12,5,7,'Kun Israelin kuningas oli lukenut kirjeen, repäisi hän vaatteensa ja sanoi: "Olenko minä Jumala, joka ottaa elämän ja antaa elämän, koska hän käskee minua päästämään miehen hänen pitalistansa? Ymmärtäkää ja nähkää, että hän etsii aihetta minua vastaan."'),
(1678570,58,12,5,8,'Mutta kun Jumalan mies Elisa kuuli, että Israelin kuningas oli reväissyt vaatteensa, lähetti hän kuninkaalle sanan: "Miksi olet reväissyt vaatteesi? Anna hänen tulla minun luokseni, niin hän tulee tietämään, että Israelissa on profeetta."'),
(1678571,58,12,5,9,'Niin Naeman tuli hevosineen ja vaunuineen ja pysähtyi Elisan talon oven eteen.'),
(1678572,58,12,5,10,'Ja Elisa lähetti hänen luokseen sanansaattajan ja käski sanoa: "Mene ja peseydy seitsemän kertaa Jordanissa, niin lihasi tulee entisellensä, ja sinä tulet puhtaaksi".'),
(1678573,58,12,5,11,'Mutta Naeman vihastui ja meni matkaansa sanoen: "Katso, minä luulin hänen edes tulevan ja astuvan esiin ja rukoilevan Herran, Jumalansa, nimeä, heiluttavan kättänsä sen paikan yli ja niin poistavan pitalin.'),
(1678574,58,12,5,12,'Eivätkö Damaskon virrat, Abana ja Parpar, ole kaikkia Israelin vesiä paremmat? Voisinhan minä yhtä hyvin peseytyä niissä tullakseni puhtaaksi." Ja hän kääntyi ja meni tiehensä kiukustuneena.'),
(1678575,58,12,5,13,'Mutta hänen palvelijansa astuivat esiin ja puhuttelivat häntä ja sanoivat: "Isäni, jos profeetta olisi määrännyt sinulle jotakin erinomaista, etkö tekisi sitä? Saati sitten, kun hän sanoi sinulle ainoastaan: ''Peseydy, niin tulet puhtaaksi''."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678576,58,12,5,14,'Niin hän meni ja sukelsi Jordaniin seitsemän kertaa, niinkuin Jumalan mies oli sanonut; ja hänen lihansa tuli entisellensä, pienen pojan lihan kaltaiseksi, ja hän tuli puhtaaksi.'),
(1678577,58,12,5,15,'Sitten hän palasi Jumalan miehen luo, hän ja koko hänen joukkonsa, meni sisälle, astui hänen eteensä ja sanoi: "Katso, nyt minä tiedän, ettei Jumalaa ole missään muualla maan päällä kuin Israelissa. Ota siis vastaan jäähyväislahja palvelijaltasi."'),
(1678578,58,12,5,16,'Mutta hän vastasi: "Niin totta kuin Herra elää, jonka edessä minä seison, en minä sitä ota". Ja Naeman pyytämällä pyysi häntä ottamaan, mutta hän epäsi.'),
(1678579,58,12,5,17,'Niin Naeman sanoi: "Jos et tätä otakaan, salli kuitenkin palvelijasi saada sen verran maata, kuin muulipari voi kantaa. Sillä palvelijasi ei enää uhraa polttouhria eikä teurasuhria muille jumalille kuin Herralle.'),
(1678580,58,12,5,18,'Tämän antakoon kuitenkin Herra anteeksi palvelijallesi: kun minun herrani menee Rimmonin temppeliin rukoilemaan, nojaten minun käteeni, ja minäkin kumartaen rukoilen Rimmonin temppelissä, niin antakoon Herra palvelijallesi anteeksi sen, että minä kumartaen rukoilen Rimmonin temppelissä."'),
(1678581,58,12,5,19,'Elisa sanoi hänelle: "Mene rauhassa". Kun hän oli kulkenut hänen luotansa jonkun matkaa,'),
(1678582,58,12,5,20,'ajatteli Geehasi, Jumalan miehen Elisan palvelija: "Katso, minun herrani säästi tuota aramilaista Naemania, niin ettei ottanut häneltä, mitä hän oli tuonut. Niin totta kuin Herra elää, minä riennän hänen jälkeensä ja otan häneltä jotakin."'),
(1678583,58,12,5,21,'Niin Geehasi juoksi Naemanin jälkeen. Kun Naeman näki hänen rientävän jäljessänsä, hyppäsi hän alas vaunuistaan, meni häntä vastaan ja kysyi: "Onko kaikki hyvin?"'),
(1678584,58,12,5,22,'Hän vastasi: "Hyvin on; mutta herrani on lähettänyt minut ja käskee sanoa: ''Nyt juuri tuli luokseni Efraimin vuoristosta kaksi nuorta miestä, profeetanoppilaita. Anna heille talentti hopeata ja kaksi juhlapukua.''"'),
(1678585,58,12,5,23,'Naeman vastasi: "Suvaitse ottaa kaksi talenttia". Ja hän pyytämällä pyysi häntä. Niin hän sitoi kaksi talenttia hopeata kahteen kukkaroon ja antoi ne ynnä kaksi juhlapukua kahdelle palvelijallensa, ja he kantoivat niitä hänen edellänsä.'),
(1678586,58,12,5,24,'Mutta kun hän tuli kummulle, otti hän ne heidän käsistänsä ja kätki ne taloon; sitten hän päästi miehet menemään.'),
(1678587,58,12,5,25,'Ja hän meni sisälle ja astui herransa luo. Niin Elisa kysyi häneltä: "Mistä tulet, Geehasi?" Hän vastasi: "Palvelijasi ei ole käynyt missään".'),
(1678588,58,12,5,26,'Elisa sanoi hänelle: "Eikö minun henkeni kulkenut sinun kanssasi, kun eräs mies kääntyi vaunuissansa sinua vastaan? Oliko nyt aika ottaa hopeata ja hankkia vaatteita, öljytarhoja, viinitarhoja, lampaita, raavaita, palvelijoita ja palvelijattaria?'),
(1678589,58,12,5,27,'Naemanin pitalitauti tarttuu sinuun ja sinun jälkeläisiisi ikiajoiksi." Ja Geehasi lähti hänen luotansa lumivalkeana pitalista.'),
(1678590,58,12,6,1,'Ja profeetanoppilaat sanoivat Elisalle: "Katso, huone, jossa me istumme sinun edessäsi, on meille liian ahdas.'),
(1678591,58,12,6,2,'Menkäämme siis Jordanille, ja tuokaamme sieltä kukin yksi hirsi ja rakentakaamme sinne huone istuaksemme." Hän sanoi: "Menkää".'),
(1678592,58,12,6,3,'Eräs heistä sanoi: "Suvaitse tulla palvelijasi kanssa". Hän sanoi: "Minä tulen".'),
(1678593,58,12,6,4,'Niin hän meni heidän kanssaan. Ja Jordanille tultuaan he hakkasivat puita.'),
(1678594,58,12,6,5,'Mutta erään heistä kaataessa hirttä kirposi kirves veteen. Niin hän huusi ja sanoi: "Voi, herrani, se oli vielä lainattu!"'),
(1678595,58,12,6,6,'Jumalan mies kysyi: "Mihin se kirposi?" Ja hän näytti hänelle paikan. Silloin hän veisti puukappaleen ja heitti sen siihen ja sai kirveen nousemaan pinnalle.'),
(1678596,58,12,6,7,'Sitten hän sanoi: "Nosta se ylös". Ja mies ojensi kätensä ja otti sen.'),
(1678597,58,12,6,8,'Kun Aramin kuningas oli sodassa Israelia vastaan, neuvotteli hän palvelijainsa kanssa ja sanoi: "Siihen ja siihen paikkaan minä asetun leiriin".'),
(1678598,58,12,6,9,'Mutta Jumalan mies lähetti Israelin kuninkaalle sanan: "Varo, ettet mene siihen paikkaan, sillä aramilaiset ovat asettuneet sinne".'),
(1678599,58,12,6,10,'Niin Israelin kuningas lähetti sanan siihen paikkaan, jonka Jumalan mies oli hänelle sanonut. Näin tämä varoitti häntä, ja hän oli siellä varuillaan. Eikä se tapahtunut ainoastaan kerran tai kahdesti.'),
(1678600,58,12,6,11,'Aramin kuninkaan sydän tuli tästä levottomaksi, ja hän kutsui palvelijansa ja sanoi heille: "Ettekö voi ilmaista minulle, kuka meikäläisistä pitää Israelin kuninkaan puolta?"'),
(1678601,58,12,6,12,'Silloin eräs hänen palvelijoistaan sanoi: "Ei niin, herrani, kuningas, vaan profeetta Elisa, joka on Israelissa, ilmaisee Israelin kuninkaalle nekin sanat, jotka sinä puhut makuuhuoneessasi".'),
(1678602,58,12,6,13,'Hän sanoi: "Menkää ja katsokaa, missä hän on, niin minä lähetän ottamaan hänet kiinni". Ja hänelle ilmoitettiin: "Katso, hän on Dootanissa".'),
(1678603,58,12,6,14,'Niin hän lähetti sinne hevosia ja sotavaunuja ja suuren sotajoukon. He tulivat sinne yöllä ja ympäröivät kaupungin.'),
(1678604,58,12,6,15,'Kun Jumalan miehen palvelija nousi aamulla varhain ja meni ulos, niin katso, sotajoukko, hevoset ja sotavaunut piirittivät kaupunkia. Ja hänen palvelijansa sanoi hänelle: "Voi, herrani, mitä me nyt teemme?"'),
(1678605,58,12,6,16,'Hän sanoi: "Älä pelkää, sillä niitä, jotka ovat meidän kanssamme, on enemmän kuin niitä, jotka ovat heidän kanssansa".'),
(1678606,58,12,6,17,'Ja Elisa rukoili ja sanoi: "Herra, avaa hänen silmänsä, että hän näkisi". Ja Herra avasi palvelijan silmät, ja hän näki, ja katso: vuori oli täynnä tulisia hevosia ja tulisia vaunuja Elisan ympärillä.'),
(1678607,58,12,6,18,'Kun viholliset sitten tulivat häntä vastaan, rukoili Elisa Herraa ja sanoi: "Sokaise tämä väki". Silloin hän sokaisi heidät Elisan pyynnön mukaan.'),
(1678608,58,12,6,19,'Ja Elisa sanoi heille: "Ei tämä ole oikea tie, eikä tämä ole oikea kaupunki. Seuratkaa minua, niin minä vien teidät sen miehen luo, jota te etsitte." Ja hän vei heidät Samariaan.'),
(1678609,58,12,6,20,'Mutta kun he tulivat Samariaan, sanoi Elisa: "Herra, avaa näiden silmät, että he näkisivät". Silloin Herra avasi heidän silmänsä, ja he näkivät; ja katso: he olivat keskellä Samariaa.'),
(1678610,58,12,6,21,'Ja kun Israelin kuningas näki heidät, sanoi hän Elisalle: "Surmaanko minä heidät, isäni, surmaanko heidät?"'),
(1678611,58,12,6,22,'Hän sanoi: "Älä surmaa. Surmaatko sinä ne, jotka otat vangiksi miekallasi ja jousellasi? Pane heidän eteensä ruokaa ja juomaa heidän syödä ja juoda; menkööt sitten takaisin herransa luo."'),
(1678612,58,12,6,23,'Niin tämä valmisti heille suuren aterian, ja kun he olivat syöneet ja juoneet, päästi hän heidät menemään; ja he menivät herransa luo. Eikä aramilaisia partiojoukkoja sitten enää tullut Israelin maahan.'),
(1678613,58,12,6,24,'Sen jälkeen Benhadad, Aramin kuningas, kokosi kaiken sotajoukkonsa ja tuli ja piiritti Samarian.'),
(1678614,58,12,6,25,'Silloin syntyi Samariassa, heidän piirittäessään sitä, suuri nälänhätä, niin että aasinpää maksoi kahdeksankymmentä hopeasekeliä ja neljännes kab-mittaa kyyhkysensontaa viisi hopeasekeliä.'),
(1678615,58,12,6,26,'Ja kun Israelin kuningas käveli muurin päällä, huusi muuan vaimo hänelle ja sanoi: "Auta, herrani, kuningas".'),
(1678616,58,12,6,27,'Hän vastasi: "Jollei Herra auta sinua, niin mistä minä hankin sinulle apua? Puimatantereeltako vai viinikuurnasta?"'),
(1678617,58,12,6,28,'Ja kuningas sanoi hänelle: "Mikä sinun on?" Hän vastasi: "Tämä vaimo sanoi minulle: ''Anna tänne poikasi, syödäksemme hänet tänä päivänä, niin syömme huomenna minun poikani''.'),
(1678618,58,12,6,29,'Ja me keitimme minun poikani ja söimme hänet. Ja minä sanoin toisena päivänä hänelle: ''Anna tänne poikasi, syödäksemme hänet''. Mutta hän piilotti poikansa."'),
(1678619,58,12,6,30,'Kun kuningas kuuli vaimon sanat, repäisi hän vaatteensa, kävellessään muurin päällä. Niin kansa näki, että hänellä oli vaatteiden alla säkki, paljaalla iholla.'),
(1678620,58,12,6,31,'Ja hän sanoi: "Jumala rangaiskoon minua nyt ja vasta, jos Elisan, Saafatin pojan, pää tänä päivänä jää hänen hartioilleen".'),
(1678621,58,12,6,32,'Elisa istui talossaan, ja vanhimmat istuivat hänen tykönänsä. Ja kuningas oli lähettänyt miehen edellänsä. Mutta ennenkuin sanansaattaja tuli hänen luokseen, sanoi hän vanhimmille: "Näettekö, kuinka se murhamiehen poika lähettää hakkaamaan minulta päätä poikki? Mutta kun sanansaattaja tulee, katsokaa, että suljette oven ja pidätte oven kiinni häneltä. Eivätkö jo kuulu hänen herransa askeleet hänen jäljessään?"'),
(1678622,58,12,6,33,'Hänen vielä puhuessaan heidän kanssansa, tuli sanansaattaja hänen luokseen ja sanoi: "Katso, tämä onnettomuus tulee Herralta; mitä minä enää odottaisin Herraa?"'),
(1678623,58,12,7,1,'Mutta Elisa vastasi: "Kuulkaa Herran sana; näin sanoo Herra: Huomenna tähän aikaan maksaa Samarian portissa sea-mitta lestyjä jauhoja sekelin ja kaksi sea-mittaa ohria sekelin".'),
(1678624,58,12,7,2,'Niin vaunusoturi, jonka käsivarteen kuningas nojasi, vastasi Jumalan miehelle ja sanoi: "Katso, vaikka Herra tekisi akkunat taivaaseen, kuinka voisi tämä tapahtua?" Hän sanoi: "Sinä olet näkevä sen omin silmin, mutta syödä siitä et saa".'),
(1678625,58,12,7,3,'Ja kaupungin portin oven edustalla oleskeli neljä pitalitautista miestä. He sanoivat toisillensa: "Mitä me istumme tässä, kunnes kuolemme?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678626,58,12,7,4,'Jos päätämme mennä kaupunkiin, jossa on nälänhätä, niin me kuolemme. Jos jäämme tähän, niin me kuolemme. Tulkaa, siirtykäämme nyt aramilaisten leiriin. Jos he jättävät meidät eloon, niin me jäämme eloon; jos he surmaavat meidät, niin me kuolemme."'),
(1678627,58,12,7,5,'Niin he nousivat hämärissä mennäkseen aramilaisten leiriin. Kun he tulivat aramilaisten leirin laitaan, niin katso: siellä ei ollut ketään.'),
(1678628,58,12,7,6,'Sillä Herra oli antanut aramilaisten sotajoukon kuulla sotavaunujen, hevosten ja suuren sotajoukon töminää; ja niin he olivat sanoneet toisilleen: "Katso, Israelin kuningas on palkannut meitä vastaan heettiläisten kuninkaat ja egyptiläisten kuninkaat, että nämä hyökkäisivät meidän kimppuumme".'),
(1678629,58,12,7,7,'Niin he olivat lähteneet liikkeelle ja paenneet hämärissä ja jättäneet telttansa, hevosensa, aasinsa ja leirinsä, niinkuin se oli; he olivat paenneet pelastaakseen henkensä.'),
(1678630,58,12,7,8,'Tultuaan leirin laitaan pitalitautiset menivät erääseen telttaan, söivät ja joivat, ottivat sieltä hopeata ja kultaa ja vaatteita, menivät pois ja kätkivät ne. Sitten he tulivat takaisin ja menivät toiseen telttaan ja ottivat sieltä saalista ja menivät pois ja kätkivät sen.'),
(1678631,58,12,7,9,'Mutta sitten he sanoivat toisilleen: "Emme tee oikein. Tämä päivä on hyvän sanoman päivä. Jos olemme vaiti ja odotamme aamun valkenemiseen asti, niin me joudumme syyllisiksi. Tulkaa, menkäämme nyt ilmoittamaan tämä kuninkaan linnaan."'),
(1678632,58,12,7,10,'Niin he tulivat ja kutsuivat kaupungin portinvartijat ja ilmoittivat heille sanoen: "Me tulimme aramilaisten leiriin, ja katso, siellä ei ollut ketään eikä kuulunut ihmisääntä; siellä oli vain hevosia ja aaseja kytkettyinä kiinni, ja teltat olivat, niinkuin olivat olleet".'),
(1678633,58,12,7,11,'Portinvartijat huusivat ja ilmoittivat tämän kuninkaan linnaan.'),
(1678634,58,12,7,12,'Silloin kuningas nousi yöllä ja sanoi palvelijoilleen: "Minä sanon teille, minkä aramilaiset meille tekevät. He tietävät meidän kärsivän nälkää, ja sentähden he ovat poistuneet leiristä ja piiloutuneet kedolle, ajatellen: kun ne lähtevät kaupungista, niin me otamme heidät elävinä kiinni ja menemme kaupunkiin."'),
(1678635,58,12,7,13,'Mutta eräs hänen palvelijoistaan vastasi ja sanoi: "Otettakoon viisi tähteeksi jääneistä hevosista, jotka ovat vielä täällä jäljellä - niidenhän käy kuitenkin samoin kuin kaiken Israelin joukon, joka on täällä jäljellä, ja samoin kuin kaiken Israelin joukon, joka on hukkunut - ja lähettäkäämme katsomaan".'),
(1678636,58,12,7,14,'Niin he ottivat kahdet sotavaunut hevosineen, ja kuningas lähetti ne aramilaisten sotajoukon jälkeen, sanoen: "Menkää ja katsokaa".'),
(1678637,58,12,7,15,'He menivät heidän jälkeensä aina Jordanille asti; ja katso: koko tie oli täynnä vaatteita ja aseita, jotka aramilaiset olivat heittäneet pois rientäessään pakoon. Niin sanansaattajat tulivat takaisin ja ilmoittivat sen kuninkaalle.'),
(1678638,58,12,7,16,'Silloin kansa lähti ja ryösti aramilaisten leirin. Ja niin sea-mitta lestyjä jauhoja maksoi sekelin ja kaksi sea-mittaa ohria sekelin, Herran sanan mukaan.'),
(1678639,58,12,7,17,'Kuningas oli asettanut sen vaunusoturin, jonka käsivarteen hän nojasi, porttiin valvomaan järjestystä. Mutta kansa tallasi hänet kuoliaaksi portissa, niinkuin Jumalan mies oli puhunut, silloin kun kuningas tuli hänen luoksensa.'),
(1678640,58,12,7,18,'Sillä kun Jumalan mies oli puhunut kuninkaalle näin: "Huomenna tähän aikaan maksaa kaksi sea-mittaa ohria Samarian portissa sekelin ja sea-mitta lestyjä jauhoja sekelin",'),
(1678641,58,12,7,19,'oli vaunusoturi vastannut Jumalan miehelle ja sanonut: "Katso, vaikka Herra tekisi akkunat taivaaseen, kuinka tämä voisi tapahtua?" Silloin hän oli sanonut: "Sinä olet näkevä sen omin silmin, mutta syödä siitä et saa".'),
(1678642,58,12,7,20,'Ja niin hänen myös kävi: kansa tallasi hänet kuoliaaksi portissa.'),
(1678643,58,12,8,1,'Ja Elisa puhui vaimolle, jonka pojan hän oli palauttanut henkiin, ja sanoi: "Nouse ja lähde, sinä ja sinun perheesi, asumaan muukalaisena, missä vain voit asua, sillä Herra on käskenyt nälänhädän tulla, ja se myös tulee maahan seitsemäksi vuodeksi".'),
(1678644,58,12,8,2,'Niin vaimo nousi ja teki Jumalan miehen sanan mukaan: hän lähti ja asui perheinensä muukalaisena filistealaisten maassa seitsemän vuotta.'),
(1678645,58,12,8,3,'Mutta niiden seitsemän vuoden kuluttua vaimo palasi filistealaisten maasta; ja hän tuli anomaan kuninkaalta taloansa ja peltoansa.'),
(1678646,58,12,8,4,'Ja kuningas puhutteli juuri Geehasia, Jumalan miehen palvelijaa, ja sanoi: "Kerro minulle kaikki ne suuret teot, jotka Elisa on tehnyt".'),
(1678647,58,12,8,5,'Juuri kun hän kertoi kuninkaalle, kuinka Elisa oli palauttanut kuolleen henkiin, tuli vaimo, jonka pojan hän oli palauttanut henkiin, anomaan kuninkaalta taloansa ja peltoansa. Silloin Geehasi sanoi: "Herrani, kuningas, tämä on se vaimo; ja tämä on se poika, jonka Elisa palautti henkiin".'),
(1678648,58,12,8,6,'Ja kuningas kyseli vaimolta, ja tämä kertoi sen hänelle. Niin kuningas antoi hänen mukaansa hoviherran ja sanoi: "Toimita tälle takaisin kaikki, mikä on hänen omaansa, ja lisäksi kaikki pellon sadot siitä päivästä alkaen, jona hän jätti maan, aina tähän asti".'),
(1678649,58,12,8,7,'Ja Elisa tuli Damaskoon. Ja Aramin kuningas Benhadad oli sairaana. Kun hänelle ilmoitettiin: "Jumalan mies on tullut tänne",'),
(1678650,58,12,8,8,'sanoi kuningas Hasaelille: "Ota mukaasi lahja ja mene Jumalan miestä vastaan ja kysy hänen kauttansa Herralta: ''Toivunko minä tästä taudista?''"'),
(1678651,58,12,8,9,'Ja Hasael meni häntä vastaan ja otti mukaansa lahjaksi kaikkea, mitä Damaskossa oli parasta, neljäkymmentä kamelinkuormaa. Ja hän tuli ja astui hänen eteensä ja sanoi: "Poikasi Benhadad, Aramin kuningas, lähetti minut sinun luoksesi ja käski kysyä: ''Toivunko minä tästä taudista?''"'),
(1678652,58,12,8,10,'Elisa sanoi: "Mene ja sano hänelle: ''Toivut''. Mutta Herra on ilmoittanut minulle, että hänen on kuoltava."'),
(1678653,58,12,8,11,'Ja hän tuijotti eteensä kauan ja liikahtamatta; sitten Jumalan mies alkoi itkeä.'),
(1678654,58,12,8,12,'Niin Hasael sanoi: "Minkätähden herrani itkee?" Hän vastasi: "Sentähden, että minä tiedän, kuinka paljon pahaa sinä olet tekevä israelilaisille: sinä pistät heidän varustetut kaupunkinsa tuleen, sinä surmaat miekalla heidän valiomiehensä, sinä murskaat heidän pienet lapsensa ja halkaiset heidän raskaat vaimonsa".'),
(1678655,58,12,8,13,'Hasael sanoi: "Mikä on palvelijasi, tällainen koira, tekemään näitä suuria asioita?" Elisa vastasi: "Herra on ilmoittanut minulle, että sinusta on tuleva Aramin kuningas".'),
(1678656,58,12,8,14,'Niin hän meni Elisan tyköä, ja kun hän tuli herransa tykö, kysyi tämä häneltä: "Mitä Elisa sanoi sinulle?" Hän vastasi: "Hän sanoi minulle, että sinä toivut".'),
(1678657,58,12,8,15,'Mutta seuraavana päivänä hän otti peitteen ja kastoi sen veteen ja levitti sen hänen kasvoillensa; niin hän kuoli. Ja Hasael tuli kuninkaaksi hänen sijaansa.'),
(1678658,58,12,8,16,'Israelin kuninkaan Jooramin, Ahabin pojan, viidentenä hallitusvuotena tuli Jooram, Juudan kuninkaan Joosafatin poika, kuninkaaksi.'),
(1678659,58,12,8,17,'Hän oli kolmenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kahdeksan vuotta.'),
(1678660,58,12,8,18,'Mutta hän vaelsi Israelin kuningasten tietä, niinkuin Ahabin suku oli tehnyt, sillä hänellä oli puolisona Ahabin tytär. Ja niin hän teki sitä, mikä on pahaa Herran silmissä.'),
(1678661,58,12,8,19,'Mutta palvelijansa Daavidin tähden Herra ei tahtonut tuhota Juudaa, koska hän oli luvannut antaa hänelle ja hänen pojilleen lampun ainiaaksi.'),
(1678662,58,12,8,20,'Hänen aikanaan edomilaiset luopuivat Juudan vallanalaisuudesta ja asettivat itsellensä kuninkaan.'),
(1678663,58,12,8,21,'Ja Jooram lähti Saairiin kaikkine sotavaunuinensa. Ja hän nousi yöllä ja voitti edomilaiset, jotka olivat saartaneet hänet, sekä sotavaunujen päälliköt. Mutta väki pakeni majoillensa;'),
(1678664,58,12,8,22,'ja edomilaiset luopuivat Juudan vallanalaisuudesta; niin aina tähän päivään asti. Siihen aikaan luopui myös Libna.'),
(1678665,58,12,8,23,'Mitä muuta on kerrottavaa Jooramista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.'),
(1678666,58,12,8,24,'Sitten Jooram meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Ja hänen poikansa Ahasja tuli kuninkaaksi hänen sijaansa.'),
(1678667,58,12,8,25,'Israelin kuninkaan Jooramin, Ahabin pojan, kahdentenatoista hallitusvuotena tuli Ahasja, Juudan kuninkaan Jooramin poika, kuninkaaksi.'),
(1678668,58,12,8,26,'Ja Ahasja oli kahdenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa vuoden. Hänen äitinsä oli nimeltään Atalja, Israelin kuninkaan Omrin tytär.'),
(1678669,58,12,8,27,'Ahasja vaelsi Ahabin suvun tietä ja teki sitä, mikä on pahaa Herran silmissä, samoin kuin Ahabin suku; sillä hän oli lankoutunut Ahabin suvun kanssa.'),
(1678670,58,12,8,28,'Ja hän lähti Jooramin, Ahabin pojan, kanssa sotimaan Hasaelia, Aramin kuningasta, vastaan Gileadin Raamotiin; mutta aramilaiset haavoittivat Jooramin.'),
(1678671,58,12,8,29,'Niin kuningas Jooram tuli takaisin parantuakseen Jisreelissä haavoista, joita aramilaiset olivat iskeneet häneen Raamassa hänen taistellessaan Hasaelia, Aramin kuningasta, vastaan. Ja Ahasja, Jooramin poika, Juudan kuningas, tuli Jisreeliin katsomaan Jooramia, Ahabin poikaa, koska tämä oli sairas.'),
(1678672,58,12,9,1,'Profeetta Elisa kutsui erään profeetanoppilaan ja sanoi hänelle: "Vyötä kupeesi ja ota tämä öljyastia mukaasi ja mene Gileadin Raamotiin.'),
(1678673,58,12,9,2,'Ja tultuasi sinne hae sieltä käsiisi Jeehu, Joosafatin poika, Nimsin pojanpoika; mene sisään, käske hänen nousta toveriensa keskeltä ja vie hänet sisimpään huoneeseen.'),
(1678674,58,12,9,3,'Ota sitten öljyastia, vuodata öljyä hänen päähänsä ja sano: ''Näin sanoo Herra: Minä olen voidellut sinut Israelin kuninkaaksi''. Avaa sitten ovi ja pakene viivyttelemättä."'),
(1678675,58,12,9,4,'Niin nuorukainen, profeetan palvelija, meni Gileadin Raamotiin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678676,58,12,9,5,'Ja kun hän tuli sinne, niin katso: sotaväen päälliköt istuivat siellä. Niin hän sanoi: "Minulla on asiaa sinulle, päällikkö". Jeehu kysyi: "Kenelle meistä kaikista?" Hän vastasi: "Sinulle itsellesi, päällikkö".'),
(1678677,58,12,9,6,'Silloin tämä nousi ja meni sisälle huoneeseen; ja hän vuodatti öljyä tämän päähän ja sanoi hänelle: "Näin sanoo Herra, Israelin Jumala: Minä olen voidellut sinut Herran kansan, Israelin, kuninkaaksi.'),
(1678678,58,12,9,7,'Ja sinä olet surmaava herrasi Ahabin suvun; sillä minä kostan Iisebelille palvelijaini, profeettain, veren ja kaikkien Herran palvelijain veren.'),
(1678679,58,12,9,8,'Ja koko Ahabin suku on hukkuva: minä hävitän Israelista Ahabin miespuoliset jälkeläiset, kaikki tyynni.'),
(1678680,58,12,9,9,'Ja minä teen Ahabin suvulle saman, minkä Jerobeamin, Nebatin pojan, suvulle ja saman, minkä Baesan, Ahian pojan, suvulle.'),
(1678681,58,12,9,10,'Ja koirat syövät Iisebelin Jisreelin vainiolla, eikä kukaan ole hautaava häntä." Sitten hän avasi oven ja pakeni.'),
(1678682,58,12,9,11,'Kun Jeehu tuli ulos herransa palvelijain luo, kysyttiin häneltä: "Onko kaikki hyvin? Miksi tuo hullu kävi sinun luonasi?" Hän vastasi heille: "Tehän tunnette sen miehen ja hänen puheensa".'),
(1678683,58,12,9,12,'Mutta he sanoivat: "Valhetta! Sano meille totuus." Hän sanoi: "Niin ja niin hän puhui minulle ja sanoi: ''Näin sanoo Herra: Minä olen voidellut sinut Israelin kuninkaaksi''".'),
(1678684,58,12,9,13,'Silloin he ottivat kiiruusti kukin vaatteensa ja panivat ne hänen allensa paljaille portaille; ja he puhalsivat pasunaan ja huusivat: "Jeehu on tullut kuninkaaksi".'),
(1678685,58,12,9,14,'Niin Jeehu, Joosafatin poika, Nimsin pojanpoika, teki salaliiton Jooramia vastaan. Jooram oli ollut kaiken Israelin kanssa puolustamassa Gileadin Raamotia Hasaelia, Aramin kuningasta, vastaan.'),
(1678686,58,12,9,15,'Mutta kuningas Jooram oli tullut takaisin parantuakseen Jisreelissä haavoista, joita aramilaiset olivat iskeneet häneen hänen taistellessaan Hasaelia, Aramin kuningasta, vastaan. Ja Jeehu sanoi: "Jos se teille kelpaa, niin älkää päästäkö pakoon kaupungista ketään, joka menisi ilmoittamaan tätä Jisreeliin".'),
(1678687,58,12,9,16,'Sitten Jeehu nousi vaunuihinsa ja lähti Jisreeliin, sillä Jooram makasi siellä; ja Ahasja, Juudan kuningas, oli tullut sinne katsomaan Jooramia.'),
(1678688,58,12,9,17,'Mutta tähystäjä seisoi Jisreelin tornissa, ja kun hän näki Jeehun joukon tulevan, sanoi hän: "Minä näen väkijoukon". Niin Jooram sanoi: "Otettakoon ratsumies ja lähetettäköön heitä vastaan kysymään, onko kaikki hyvin".'),
(1678689,58,12,9,18,'Ja ratsumies lähti häntä vastaan ja sanoi: "Näin kysyy kuningas: ''Onko kaikki hyvin?''" Jeehu vastasi: "Mitä se sinua liikuttaa, onko hyvin? Käänny ja seuraa minua." Niin tähystäjä ilmoitti sanoen: "Sanansaattaja on tullut heidän luoksensa, mutta ei palaa".'),
(1678690,58,12,9,19,'Silloin hän lähetti toisen ratsumiehen. Kun tämä oli tullut heidän luoksensa, sanoi hän: "Näin kysyy kuningas: ''Onko kaikki hyvin?'' Jeehu vastasi: "Mitä se sinua liikuttaa, onko hyvin? Käänny ja seuraa minua."'),
(1678691,58,12,9,20,'Niin tähystäjä ilmoitti sanoen: "Hän on tullut heidän luoksensa, mutta ei palaa. Ja ajo on aivan kuin Jeehun, Nimsin pojan, ajoa; sillä hän ajaa niinkuin hurja."'),
(1678692,58,12,9,21,'Silloin Jooram sanoi: "Valjastettakoon!" Ja he valjastivat hänen sotavaununsa. Niin Jooram, Israelin kuningas, ja Ahasja, Juudan kuningas, lähtivät kumpikin sotavaunuissansa ja menivät Jeehua vastaan. He kohtasivat hänet jisreeliläisen Naabotin maapalstalla.'),
(1678693,58,12,9,22,'Kun Jooram näki Jeehun, kysyi hän: "Onko kaikki hyvin, Jeehu?" Tämä vastasi: "Kuinka kaikki voisi olla hyvin, kun sinun äitisi Iisebelin haureus ja hänen monet velhoutensa yhä vielä jatkuvat?"'),
(1678694,58,12,9,23,'Silloin Jooram käänsi vaununsa ja pakeni, huutaen Ahasjalle: "Kavallus, Ahasja!"'),
(1678695,58,12,9,24,'Mutta Jeehu sieppasi jousen käteensä ja ampui Jooramia hartioiden väliin, niin että nuoli meni sydämen lävitse, ja hän vaipui vaunuihinsa.'),
(1678696,58,12,9,25,'Sitten hän sanoi Bidkarille, vaunusoturille: "Ota hänet ja heitä jisreeliläisen Naabotin maapalstalle; sillä muistathan, että Herra meidän ratsastaessamme rinnakkain hänen isänsä Ahabin jäljessä lausui hänestä tämän ennustuksen:'),
(1678697,58,12,9,26,'''Totisesti, minä näin eilen Naabotin ja hänen poikiensa veren, sanoo Herra; ja minä olen juuri tällä maapalstalla kostava sinulle, sanoo Herra''. Ota siis hänet ja heitä tälle maapalstalle, Herran sanan mukaan."'),
(1678698,58,12,9,27,'Kun Ahasja, Juudan kuningas, sen näki, pakeni hän Beet-Gaaniin päin. Mutta Jeehu ajoi häntä takaa ja sanoi: "Ampukaa hänetkin vaunuihinsa". Ja he ampuivat häntä Guurin solassa, joka on Jibleamin luona; mutta hän pakeni Megiddoon ja kuoli siellä.'),
(1678699,58,12,9,28,'Ja hänen palvelijansa veivät hänet vaunuissa Jerusalemiin ja hautasivat hänet hänen omaan hautaansa, hänen isiensä viereen, Daavidin kaupunkiin.'),
(1678700,58,12,9,29,'Ahasja oli tullut Juudan kuninkaaksi Jooramin, Ahabin pojan, yhdentenätoista hallitusvuotena.'),
(1678701,58,12,9,30,'Sitten Jeehu tuli Jisreeliin. Kun Iisebel kuuli sen, maalasi hän ihomaalilla silmäluomensa, koristeli päänsä ja katseli ulos akkunasta.'),
(1678702,58,12,9,31,'Ja kun Jeehu tuli portista sisään, kysyi Iisebel: "Kävikö hyvin Simrille, herransa murhaajalle?"'),
(1678703,58,12,9,32,'Hän käänsi kasvonsa akkunaa kohti ja sanoi: "Kuka on minun puolellani? Kuka?" Niin pari kolme hoviherraa katsoi alas häneen.'),
(1678704,58,12,9,33,'Jeehu sanoi: "Syöskää hänet alas". Ja he syöksivät hänet alas, niin että hänen vertansa pirskui seinään ja hevosiin; ja nämä tallasivat hänet jalkoihinsa.'),
(1678705,58,12,9,34,'Sitten Jeehu meni sisään, söi ja joi. Ja hän sanoi: "Korjatkaa se kirottu ja haudatkaa hänet, sillä onhan hän kuninkaan tytär".'),
(1678706,58,12,9,35,'Mutta kun he menivät hautaamaan häntä, eivät he löytäneet hänestä muuta kuin pääkallon, jalat ja kädet.'),
(1678707,58,12,9,36,'Ja he tulivat takaisin ja ilmoittivat sen Jeehulle. Niin hän sanoi: "Tässä on toteutunut Herran sana, jonka hän puhui palvelijansa tisbeläisen Elian kautta: ''Jisreelin vainiolla koirat syövät Iisebelin lihan;'),
(1678708,58,12,9,37,'ja Iisebelin ruumis on oleva niinkuin pellon lanta Jisreelin vainiolla, niin ettei voida sanoa: Tämä on Iisebel''".'),
(1678709,58,12,10,1,'Mutta Ahabilla oli seitsemänkymmentä poikaa Samariassa. Ja Jeehu kirjoitti kirjeet ja lähetti ne Samariaan, Jisreelin päämiehille, vanhimmille ja Ahabin poikien holhoojille; hän kirjoitti näin:'),
(1678710,58,12,10,2,'"Kun tämä kirje tulee teille, joiden hallussa herranne pojat ovat ja joiden hallussa ovat sotavaunut, hevoset, varustettu kaupunki ja aseet,'),
(1678711,58,12,10,3,'niin valitkaa herranne pojista paras ja oikeamielisin ja asettakaa hänet isänsä valtaistuimelle ja sotikaa herranne suvun puolesta".'),
(1678712,58,12,10,4,'Mutta he peljästyivät kovin ja sanoivat: "Katso, ne kaksi kuningasta eivät kestäneet hänen edessään, kuinka me kestäisimme?"'),
(1678713,58,12,10,5,'Niin linnan päällikkö ja kaupungin päällikkö sekä vanhimmat ja holhoojat lähettivät Jeehulle sanan: "Me olemme sinun palvelijoitasi; me teemme kaiken, mitä sinä meille määräät. Emme me tee ketään kuninkaaksi; tee, mitä tahdot."'),
(1678714,58,12,10,6,'Silloin hän kirjoitti heille toisen kirjeen, näin kuuluvan: "Jos te olette minun puolellani ja kuulette minua, niin ottakaa herranne poikien päät ja tulkaa huomenna tähän aikaan minun luokseni Jisreeliin". Ne seitsemänkymmentä kuninkaan poikaa asuivat näet kaupungin ylimysten luona, jotka heitä kasvattivat.'),
(1678715,58,12,10,7,'Kun kirje tuli heille, ottivat he kuninkaan pojat ja tappoivat heidät, seitsemänkymmentä miestä, panivat heidän päänsä koreihin ja lähettivät ne Jeehulle Jisreeliin.'),
(1678716,58,12,10,8,'Ja sanansaattaja tuli ja ilmoitti hänelle sanoen: "He ovat tuoneet kuninkaan poikien päät". Hän sanoi: "Pankaa ne kahteen roukkioon portin oven edustalle huomiseen saakka".'),
(1678717,58,12,10,9,'Ja aamulla hän meni ulos, asettui siihen ja sanoi kaikelle kansalle: "Te olette syyttömät. Katso, minä olen tehnyt salaliiton herraani vastaan ja tappanut hänet; mutta kuka on surmannut kaikki nämä?'),
(1678718,58,12,10,10,'Tietäkää siis, ettei ainoakaan Herran sana, jonka Herra on puhunut Ahabin sukua vastaan, varise maahan. Herra on tehnyt, minkä hän on puhunut palvelijansa Elian kautta."'),
(1678719,58,12,10,11,'Sitten Jeehu surmasi kaikki, jotka olivat Ahabin suvusta jäljellä Jisreelissä, sekä kaikki hänen ylimyksensä, uskottunsa ja pappinsa, päästämättä pakoon ainoatakaan.'),
(1678720,58,12,10,12,'Sitten hän nousi ja lähti Samariaan; mutta tullessaan paimenten Beet-Eekediin, joka on tien varrella,'),
(1678721,58,12,10,13,'Jeehu kohtasi Ahasjan, Juudan kuninkaan, veljet ja kysyi: "Keitä te olette?" He vastasivat: "Me olemme Ahasjan veljiä ja menemme tervehtimään kuninkaan poikia ja kuninkaan äidin poikia".'),
(1678722,58,12,10,14,'Hän sanoi: "Ottakaa nämä elävinä kiinni". Ja he ottivat heidät elävinä kiinni ja tappoivat heidät ja heittivät Beet-Eekedin vesisäiliöön, neljäkymmentä kaksi miestä. Hän ei jättänyt heistä eloon ainoatakaan.'),
(1678723,58,12,10,15,'Kun hän sitten lähti sieltä, kohtasi hän Joonadabin, Reekabin pojan, joka tuli häntä vastaan. Ja hän tervehti häntä ja sanoi hänelle: "Onko sinun sydämesi yhtä vilpitön minua kohtaan, kuin minun sydämeni on sinua kohtaan?" Joonadab vastasi: "On". - "Jos niin on, niin lyö kättä minun kanssani." Ja hän löi kättä, ja hän otti hänet vaunuihinsa.'),
(1678724,58,12,10,16,'Ja hän sanoi: "Tule minun kanssani katsomaan minun kiivailuani Herran puolesta". Niin hän sai ajaa hänen vaunuissansa.'),
(1678725,58,12,10,17,'Tultuaan Samariaan hän surmasi kaikki, jotka olivat Ahabin jälkeläisistä jäljellä Samariassa, kunnes hän oli hävittänyt hänen sukunsa, Herran sanan mukaan, jonka Herra oli puhunut Elialle.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678726,58,12,10,18,'Sitten Jeehu kokosi kaiken kansan ja sanoi heille: "Ahab on palvellut Baalia vähän; Jeehu on palveleva häntä paljon.'),
(1678727,58,12,10,19,'Kutsukaa nyt minun luokseni kaikki Baalin profeetat, kaikki hänen palvelijansa ja kaikki hänen pappinsa, älköönkä kukaan jääkö pois; sillä minä aion uhrata suuret uhrit Baalille. Eloon ei jää kukaan, joka jää pois." Mutta Jeehu menetteli kavalasti, tuhotakseen Baalin palvelijat.'),
(1678728,58,12,10,20,'Niin Jeehu sanoi: "Kuuluttakaa pyhä juhlakokous Baalin kunniaksi". Ja se kutsuttiin koolle.'),
(1678729,58,12,10,21,'Ja Jeehu lähetti sanan kaikkeen Israeliin, ja kaikki Baalin palvelijat tulivat; ei yksikään jäänyt tulematta. Niin he menivät Baalin temppeliin, ja Baalin temppeli täyttyi ääriään myöten.'),
(1678730,58,12,10,22,'Ja hän sanoi vaatekammion hoitajalle: "Tuo puvut kaikille Baalin palvelijoille". Ja tämä toi heille puvut.'),
(1678731,58,12,10,23,'Kun Jeehu Joonadabin, Reekabin pojan, kanssa tuli Baalin temppeliin, sanoi hän Baalin palvelijoille: "Tutkikaa ja katsokaa, ettei täällä teidän joukossanne ole ketään Herran palvelijaa, vaan ainoastaan Baalin palvelijoita".'),
(1678732,58,12,10,24,'Sitten he menivät uhraamaan teurasuhreja ja polttouhreja. Mutta Jeehu oli asettanut ulkopuolelle kahdeksankymmentä miestä ja sanonut: "Jos kuka päästää pakoon yhdenkään niistä miehistä, jotka minä tuon teidän käsiinne, menee henki hengestä".'),
(1678733,58,12,10,25,'Ja päätettyänsä polttouhrin uhraamisen sanoi Jeehu henkivartijoille ja vaunusotureille: "Menkää sisään ja surmatkaa heidät; älköön yksikään pääskö ulos". Niin he surmasivat heidät miekan terällä, ja henkivartijat ja vaunusoturit heittivät ulos heidän ruumiinsa. Sitten he menivät Baalin temppelilinnaan'),
(1678734,58,12,10,26,'ja toivat ulos Baalin temppelin patsaat ja polttivat ne,'),
(1678735,58,12,10,27,'ja he kukistivat Baalin patsaan. He hävittivät Baalin temppelin ja tekivät siitä käymälöitä; niin aina tähän päivään asti.'),
(1678736,58,12,10,28,'Näin Jeehu hävitti Baalin Israelista.'),
(1678737,58,12,10,29,'Mutta Jerobeamin, Nebatin pojan, synneistä, joilla hän oli saattanut Israelin tekemään syntiä, Beetelissä ja Daanissa olevista kultavasikoista, Jeehu ei luopunut.'),
(1678738,58,12,10,30,'Niin Herra sanoi Jeehulle: "Koska olet hyvin toimittanut sen, mikä oli oikein minun silmissäni, ja koska teit Ahabin suvulle aivan minun mieleni mukaan, niin istukoot sinun poikasi Israelin valtaistuimella neljänteen polveen".'),
(1678739,58,12,10,31,'Mutta Jeehu ei vaeltanut tarkoin, kaikesta sydämestänsä, Herran, Israelin Jumalan, lain mukaan; hän ei luopunut Jerobeamin synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.'),
(1678740,58,12,10,32,'Niihin aikoihin Herra rupesi lohkomaan Israelia, sillä Hasael voitti heidät kaikkialla Israelin raja-alueella'),
(1678741,58,12,10,33,'ja valloitti Jordanista auringonnousuun päin koko Gileadin maan, gaadilaiset, ruubenilaiset ja manasselaiset, alkaen Aroerista, joka on Arnon-joen rannalla - sekä Gileadin että Baasanin.'),
(1678742,58,12,10,34,'Mitä muuta on kerrottavaa Jeehusta ja kaikesta, mitä hän teki, ja kaikista hänen urotöistänsä, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678743,58,12,10,35,'Sitten Jeehu meni lepoon isiensä tykö, ja hänet haudattiin Samariaan. Ja hänen poikansa Jooahas tuli kuninkaaksi hänen sijaansa.'),
(1678744,58,12,10,36,'Ja aika, jonka Jeehu hallitsi Israelia Samariassa, oli kaksikymmentä kahdeksan vuotta.'),
(1678745,58,12,11,1,'Kun Atalja, Ahasjan äiti, näki, että hänen poikansa oli kuollut, nousi hän ja tuhosi koko kuningassuvun.'),
(1678746,58,12,11,2,'Mutta kuningas Jooramin tytär Jooseba, Ahasjan sisar, otti surmattavien kuninkaan poikien joukosta Ahasjan pojan Jooaan ja vei hänet ja hänen imettäjänsä salaa makuuhuoneeseen. Täällä pidettiin Jooasta kätkettynä Ataljalta, niin ettei hän tullut surmatuksi.'),
(1678747,58,12,11,3,'Sitten poika oli Jooseban luona Herran temppeliin piilotettuna kuusi vuotta, Ataljan hallitessa maata.'),
(1678748,58,12,11,4,'Mutta seitsemäntenä vuotena Joojada lähetti hakemaan kaarilaisten ja henkivartijain sadanpäämiehiä ja tuotti heidät luoksensa Herran temppeliin. Ja sittenkuin hän oli tehnyt liiton heidän kanssansa ja vannottanut heidät siellä Herran temppelissä, näytti hän heille kuninkaan pojan.'),
(1678749,58,12,11,5,'Sitten hän käski heitä sanoen: "Tehkää näin: kolmas osa teistä, joiden on mentävä vartionpitoon sapattina, vartioikoon kuninkaan palatsia,'),
(1678750,58,12,11,6,'kolmas osa olkoon sivuportilla ja kolmas osa henkivartijain takana olevalla portilla; vartioikaa palatsia, kukin vuorollanne.'),
(1678751,58,12,11,7,'Mutta kaksi muuta teidän osastoanne, kaikki, jotka pääsevät vartionpidosta sapattina, vartioikoot Herran temppeliä, kuninkaan luona.'),
(1678752,58,12,11,8,'Asettukaa kuninkaan ympärille, kullakin ase kädessä; ja joka tunkeutuu rivien läpi, se surmattakoon. Näin olkaa kuninkaan luona, menköön hän ulos tai sisään."'),
(1678753,58,12,11,9,'Sadanpäämiehet tekivät, aivan niinkuin pappi Joojada oli heitä käskenyt: kukin heistä otti miehensä, sekä ne, joiden oli mentävä vartionpitoon sapattina, että ne, jotka pääsivät vartionpidosta sapattina, ja he tulivat pappi Joojadan luo.'),
(1678754,58,12,11,10,'Ja pappi antoi sadanpäämiehille keihäät ja varustukset, jotka olivat olleet kuningas Daavidin omat ja olivat Herran temppelissä.'),
(1678755,58,12,11,11,'Ja henkivartijat asettuivat, kullakin ase kädessä, temppelin eteläsivulta aina sen pohjoissivulle saakka, päin alttaria ja temppeliä, kuninkaan ympärille.'),
(1678756,58,12,11,12,'Sitten hän toi kuninkaan pojan esille, pani hänen päähänsä kruunun ja antoi hänelle lain kirjan, ja he tekivät hänet kuninkaaksi ja voitelivat hänet; ja he paukuttivat käsiänsä ja huusivat: "Eläköön kuningas!"'),
(1678757,58,12,11,13,'Kun Atalja kuuli henkivartijain ja kansan huudon, meni hän kansan luo Herran temppeliin.'),
(1678758,58,12,11,14,'Hän näki kuninkaan seisovan pylvään vieressä, niinkuin tapa oli, ja päälliköt ja torvensoittajat kuninkaan luona, ja kaiken maan kansan, joka riemuitsi ja puhalsi torviin. Silloin Atalja repäisi vaatteensa ja huusi: "Kapina! Kapina!"'),
(1678759,58,12,11,15,'Mutta pappi Joojada käski sadanpäämiehiä, sotajoukon johtajia, ja sanoi heille: "Viekää hänet pois rivien välitse, ja joka yrittää seurata häntä, se surmatkaa miekalla". Sillä pappi oli sanonut: "Älköön häntä surmattako Herran temppelissä".'),
(1678760,58,12,11,16,'Niin he kävivät häneen käsiksi, ja kun hän oli tullut tielle, jota myöten hevosia kuljetettiin kuninkaan palatsiin, surmattiin hänet siellä.'),
(1678761,58,12,11,17,'Ja Joojada teki liiton Herran, kuninkaan ja kansan kesken, että he olisivat Herran kansa; niin myös kuninkaan ja kansan kesken.'),
(1678762,58,12,11,18,'Sitten kaikki maan kansa meni Baalin temppeliin, ja he hävittivät sen. Sen alttarit ja kuvat he löivät aivan murskaksi ja tappoivat alttarien edessä Mattanin, Baalin papin. Sitten pappi asetti vartijat vartioimaan Herran temppeliä.'),
(1678763,58,12,11,19,'Ja hän otti mukaansa sadanpäämiehet sekä kaarilaiset ja henkivartijat ja kaiken maan kansan, ja he veivät kuninkaan Herran temppelistä ja tulivat henkivartijain portin kautta kuninkaan linnaan, ja hän istui kuninkaalliselle valtaistuimelle.'),
(1678764,58,12,11,20,'Ja kaikki maan kansa iloitsi, ja kaupunki pysyi rauhallisena. Mutta Ataljan he surmasivat miekalla kuninkaan linnassa.'),
(1678765,58,12,11,21,'Jooas oli seitsemän vuoden vanha tullessaan kuninkaaksi.'),
(1678766,58,12,12,1,'Jeehun seitsemäntenä hallitusvuotena tuli Jooas kuninkaaksi, ja hän hallitsi Jerusalemissa neljäkymmentä vuotta. Hänen äitinsä oli nimeltään Sibja Beersebasta.'),
(1678767,58,12,12,2,'Ja Jooas teki sitä, mikä on oikein Herran silmissä, niin kauan kuin hän eli, sillä pappi Joojada oli opettanut häntä.'),
(1678768,58,12,12,3,'Kuitenkaan eivät uhrikukkulat hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla.'),
(1678769,58,12,12,4,'Ja Jooas sanoi papeille: "Kaiken rahan, joka pyhinä lahjoina tuodaan Herran temppeliin, käyvän rahan, kaiken arvion mukaan suoritettavan henkilörahan ja kaiken rahan, jonka joku sydämensä vaatimuksesta tuo Herran temppeliin,'),
(1678770,58,12,12,5,'sen ottakoot papit itselleen, kukin tuttavaltaan; mutta heidän on niillä korjattava, mitä on rappeutunutta Herran temppelissä, missä vain jotakin rappeutunutta on".'),
(1678771,58,12,12,6,'Mutta vielä kuningas Jooaan kahdentenakymmenentenä kolmantena hallitusvuotena eivät papit olleet korjanneet mitään, mikä temppelissä oli rappeutunutta.'),
(1678772,58,12,12,7,'Silloin kuningas Jooas kutsui pappi Joojadan ja muut papit ja sanoi heille: "Miksi te ette ole korjanneet mitään, mikä temppelissä on rappeutunutta? Nyt te ette enää saa ottaa rahaa tuttaviltanne, vaan teidän on annettava se siihen, mikä temppelissä on rappeutunutta."'),
(1678773,58,12,12,8,'Ja papit suostuivat siihen, etteivät ottaisi rahaa kansalta, mutta eivät myöskään korjaisi sitä, mikä temppelissä oli rappeutunutta.'),
(1678774,58,12,12,9,'Mutta pappi Joojada otti arkun ja kaivoi reiän sen kanteen ja asetti sen alttarin ääreen, oikealle puolelle, kun mennään Herran temppeliin. Ja papit, jotka vartioivat ovea, panivat siihen kaiken rahan, mikä Herran temppeliin tuotiin.'),
(1678775,58,12,12,10,'Kun he näkivät, että arkussa oli paljon rahaa, meni kuninkaan kirjuri sinne ylimmäisen papin kanssa, ja he sitoivat yhteen ja laskivat rahat, jotka olivat Herran temppelissä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678776,58,12,12,11,'Sitten annettiin punnitut rahat työnteettäjille, jotka oli pantu valvomaan töitä Herran temppelissä; ja he maksoivat niillä puusepät ja rakentajat, jotka tekivät työtä Herran temppelissä,'),
(1678777,58,12,12,12,'ynnä muurarit ja kivenhakkaajat, niin myös puutavarat ja hakatut kivet, jotka oli ostettava sen korjaamiseksi, mikä Herran temppelissä oli rappeutunutta, kaikki temppelin korjausmenot.'),
(1678778,58,12,12,13,'Ei kuitenkaan teetetty Herran temppeliin hopeavateja, veitsiä, maljoja, torvia, ei mitään kulta- tai hopeakaluja, rahalla, joka tuotiin Herran temppeliin,'),
(1678779,58,12,12,14,'vaan se annettiin työmiehille, että he sillä korjaisivat Herran temppeliä.'),
(1678780,58,12,12,15,'Eikä miehiltä, joille rahat luovutettiin työmiehille annettaviksi, vaadittu tilintekoa, vaan he toimivat luottamusmiehinä.'),
(1678781,58,12,12,16,'Vikauhri- ja syntiuhrirahoja ei tuotu Herran temppeliin; ne tulivat papeille.'),
(1678782,58,12,12,17,'Siihen aikaan Hasael, Aramin kuningas, tuli ja ryhtyi sotimaan Gatia vastaan, ja hän valloitti sen. Sitten Hasael kävi hyökkäämään Jerusalemia vastaan.'),
(1678783,58,12,12,18,'Silloin Jooas, Juudan kuningas, otti kaikki pyhät lahjat, jotka hänen isänsä, Juudan kuninkaat Joosafat, Jooram ja Ahasja, olivat pyhittäneet, ja omat pyhät lahjansa sekä kaiken kullan, mitä oli Herran temppelin aarrekammioissa ja kuninkaan linnassa, ja lähetti ne Hasaelille, Aramin kuninkaalle. Niin tämä lähti pois Jerusalemin kimpusta.'),
(1678784,58,12,12,19,'Mitä muuta on kerrottavaa Jooaasta ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.'),
(1678785,58,12,12,20,'Mutta hänen palvelijansa nousivat ja tekivät salaliiton ja surmasivat Jooaan Millo-rakennuksessa, siinä, mistä mennään alas Sillaan.'),
(1678786,58,12,12,21,'Hänen palvelijansa Joosakar, Simeatin poika, ja Joosabad, Soomerin poika, löivät hänet kuoliaaksi, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Ja hänen poikansa Amasja tuli kuninkaaksi hänen sijaansa.'),
(1678787,58,12,13,1,'Juudan kuninkaan Jooaan, Ahasjan pojan, kahdentenakymmenentenä kolmantena hallitusvuotena tuli Jooahas, Jeehun poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa seitsemäntoista vuotta.'),
(1678788,58,12,13,2,'Ja hän teki sitä, mikä on pahaa Herran silmissä, ja vaelsi Jerobeamin, Nebatin pojan, synneissä, joilla tämä oli saattanut Israelin tekemään syntiä; hän ei luopunut niistä.'),
(1678789,58,12,13,3,'Niin Herran viha syttyi Israelia kohtaan, ja hän antoi heidät Hasaelin, Aramin kuninkaan, ja Benhadadin, Hasaelin pojan, käsiin koko siksi ajaksi.'),
(1678790,58,12,13,4,'Mutta Jooahas lepytti Herraa, ja Herra kuuli häntä, sillä hän näki Israelin sorron, kun Aramin kuningas sorti heitä.'),
(1678791,58,12,13,5,'Ja Herra antoi Israelille vapauttajan, ja he pääsivät aramilaisten käsistä. Ja israelilaiset asuivat majoissansa niinkuin ennenkin.'),
(1678792,58,12,13,6,'Eivät he kuitenkaan luopuneet Jerobeamin suvun synneistä, joilla hän oli saattanut Israelin tekemään syntiä, vaan he vaelsivat niissä; aserakin jäi paikoilleen Samariaan.'),
(1678793,58,12,13,7,'Niin ei Herra jättänyt Jooahaalle väkeä enempää kuin viisikymmentä ratsumiestä, kymmenet sotavaunut ja kymmenentuhatta jalkamiestä; sillä Aramin kuningas oli hävittänyt ne ja pannut ne tomuksi, niinkuin puitaessa tulee tomua.'),
(1678794,58,12,13,8,'Mitä muuta on kerrottavaa Jooahaasta, kaikesta, mitä hän teki, ja hänen urotöistänsä, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678795,58,12,13,9,'Ja Jooahas meni lepoon isiensä tykö, ja hänet haudattiin Samariaan. Ja hänen poikansa Jooas tuli kuninkaaksi hänen sijaansa.'),
(1678796,58,12,13,10,'Juudan kuninkaan Jooaan kolmantenakymmenentenä seitsemäntenä hallitusvuotena tuli Jooas, Jooahaan poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa kuusitoista vuotta.'),
(1678797,58,12,13,11,'Hän teki sitä, mikä on pahaa Herran silmissä: hän ei luopunut mistään Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä, vaan vaelsi niissä.'),
(1678798,58,12,13,12,'Mitä muuta on kerrottavaa Jooaasta, kaikesta, mitä hän teki, ja hänen urotöistään, kuinka hän soti Juudan kuningasta Amasjaa vastaan, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678799,58,12,13,13,'Ja Jooas meni lepoon isiensä tykö, ja Jerobeam istui hänen valtaistuimellensa. Ja Jooas haudattiin Samariaan Israelin kuningasten viereen.'),
(1678800,58,12,13,14,'Mutta kun Elisa sairasti kuolintautiansa, tuli Jooas, Israelin kuningas, hänen tykönsä. Ja kumartuneena hänen kasvojensa yli hän itki ja sanoi: "Isäni, isäni! Israelin sotavaunut ja ratsumiehet!"'),
(1678801,58,12,13,15,'Niin Elisa sanoi hänelle: "Nouda jousi ja nuolia". Ja hän nouti hänelle jousen ja nuolia.'),
(1678802,58,12,13,16,'Sitten hän sanoi Israelin kuninkaalle: "Laske kätesi jouselle". Ja kun hän oli laskenut kätensä, pani Elisa kätensä kuninkaan kätten päälle.'),
(1678803,58,12,13,17,'Ja hän sanoi: "Avaa ikkuna itään päin". Ja kun tämä oli avannut sen, sanoi Elisa: "Ammu". Ja hän ampui. Niin hän sanoi: "Herran voitonnuoli, voitonnuoli Aramia vastaan! Sinä olet voittava aramilaiset Afekissa perinpohjin."'),
(1678804,58,12,13,18,'Sitten hän sanoi: "Ota nuolet". Ja kun hän oli ne ottanut, sanoi hän Israelin kuninkaalle: "Lyö maahan". Niin hän löi kolme kertaa ja lakkasi sitten.'),
(1678805,58,12,13,19,'Mutta Jumalan mies vihastui häneen ja sanoi: "Sinun olisi pitänyt lyödä viisi tai kuusi kertaa: silloin olisit voittanut aramilaiset perinpohjin. Mutta nyt olet voittava aramilaiset ainoastaan kolme kertaa."'),
(1678806,58,12,13,20,'Sitten Elisa kuoli, ja hänet haudattiin. Ja mooabilaisten partiojoukkoja tuli maahan vuosi vuodelta.'),
(1678807,58,12,13,21,'Ja kerran, kun he haudatessaan erästä miestä näkivät partiojoukon, heittivät he miehen Elisan hautaan ja menivät matkoihinsa. Kun mies kosketti Elisan luita, virkosi hän ja nousi jaloilleen.'),
(1678808,58,12,13,22,'Hasael, Aramin kuningas, sorti Israelia, niin kauan kuin Jooahas eli.'),
(1678809,58,12,13,23,'Mutta Herra oli heille laupias, armahti heitä ja kääntyi heidän puoleensa liiton tähden, jonka hän oli tehnyt Aabrahamin, Iisakin ja Jaakobin kanssa. Sillä hän ei tahtonut tuhota heitä, eikä hän ollut vielä heittänyt heitä pois kasvojensa edestä.'),
(1678810,58,12,13,24,'Ja Hasael, Aramin kuningas, kuoli, ja hänen poikansa Benhadad tuli kuninkaaksi hänen sijaansa.'),
(1678811,58,12,13,25,'Ja Jooas, Jooahaan poika, otti Benhadadilta, Hasaelin pojalta, takaisin ne kaupungit, jotka tämä oli asevoimalla ottanut hänen isältänsä Jooahaalta. Kolme kertaa Jooas voitti hänet ja otti takaisin Israelin kaupungit.'),
(1678812,58,12,14,1,'Israelin kuninkaan Jooaan, Jooahaan pojan, toisena hallitusvuotena tuli Amasja, Jooaan poika, Juudan kuninkaaksi.'),
(1678813,58,12,14,2,'Hän oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kaksikymmentä yhdeksän vuotta. Hänen äitinsä oli nimeltään Jooaddin, Jerusalemista.'),
(1678814,58,12,14,3,'Hän teki sitä, mikä on oikein Herran silmissä, ei kuitenkaan niinkuin hänen isänsä Daavid. Kaikessa hän teki, niinkuin hänen isänsä Jooas oli tehnyt.'),
(1678815,58,12,14,4,'Kuitenkaan eivät uhrikukkulat hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla.'),
(1678816,58,12,14,5,'Ja kun kuninkuus oli vahvistunut hänen käsissään, surmautti hän ne palvelijansa, jotka olivat murhanneet kuninkaan, hänen isänsä.'),
(1678817,58,12,14,6,'Mutta murhaajain lapset hän jätti surmaamatta, niinkuin on kirjoitettu Mooseksen lain kirjaan, jossa Herra on käskenyt: "Älköön isiä rangaistako kuolemalla lasten tähden älköönkä lapsia isien tähden; kukin rangaistakoon kuolemalla oman syntinsä tähden".'),
(1678818,58,12,14,7,'Hän voitti edomilaiset Suolalaaksossa, kymmenentuhatta miestä, ja valloitti Seelan asevoimalla ja antoi sille nimen Jokteel, joka sillä tänäkin päivänä on.'),
(1678819,58,12,14,8,'Silloin Amasja lähetti sanansaattajat Israelin kuninkaan Jooaan, Jooahaan pojan, Jeehun pojanpojan luo ja käski sanoa hänelle: "Tule, otelkaamme keskenämme".'),
(1678820,58,12,14,9,'Mutta Jooas, Israelin kuningas, lähetti Amasjalle, Juudan kuninkaalle tämän sanan: "Libanonilla kasvava ohdake lähetti setripuulle, joka kasvoi Libanonilla, sanan: ''Anna tyttäresi vaimoksi minun pojalleni''. Mutta metsän eläimet Libanonilla kulkivat ohdakkeen ylitse ja tallasivat sen maahan.'),
(1678821,58,12,14,10,'Sinä olet voittanut Edomin, ja siitä olet käynyt ylpeäksi. Tyydy siihen kunniaan ja pysy kotonasi. Minkätähden tuotat onnettomuuden? Sinä kukistut itse ynnä Juuda sinun kanssasi."'),
(1678822,58,12,14,11,'Mutta Amasja ei totellut. Niin Jooas, Israelin kuningas, lähti liikkeelle, ja he, hän ja Amasja, Juudan kuningas, ottelivat keskenään Beet-Semeksessä, joka on Juudan aluetta.'),
(1678823,58,12,14,12,'Ja israelilaiset voittivat Juudan miehet, ja nämä pakenivat kukin majallensa.'),
(1678824,58,12,14,13,'Ja Jooas, Israelin kuningas, otti Juudan kuninkaan Amasjan, Jooaan pojan, Ahasjan pojanpojan, Beet-Semeksessä vangiksi. Kun hän tuli Jerusalemiin, revitti hän Jerusalemin muuria Efraimin portista Kulmaporttiin saakka, neljäsataa kyynärää.'),
(1678825,58,12,14,14,'Ja hän otti kaiken kullan ja hopean sekä kaikki kalut, mitä Herran temppelissä ja kuninkaan linnan aarrekammioissa oli, ynnä panttivankeja, ja palasi Samariaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678826,58,12,14,15,'Mitä muuta on kerrottavaa Jooaasta, siitä, mitä hän teki, ja hänen urotöistään, kuinka hän soti Amasjaa, Juudan kuningasta, vastaan, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678827,58,12,14,16,'Ja Jooas meni lepoon isiensä tykö, ja hänet haudattiin Samariaan Israelin kuningasten viereen. Ja hänen poikansa Jerobeam tuli kuninkaaksi hänen sijaansa.'),
(1678828,58,12,14,17,'Mutta Juudan kuningas Amasja, Jooaan poika, eli Israelin kuninkaan Jooaan, Jooahaan pojan, kuoleman jälkeen viisitoista vuotta.'),
(1678829,58,12,14,18,'Mitä muuta on kerrottavaa Amasjasta, se on kirjoitettuna Juudan kuningasten aikakirjassa.'),
(1678830,58,12,14,19,'Ja häntä vastaan tehtiin Jerusalemissa salaliitto. Hän pakeni Laakiiseen, mutta Laakiiseen lähetettiin miehiä hänen jälkeensä, ja ne surmasivat hänet siellä.'),
(1678831,58,12,14,20,'Hänet nostettiin hevosten selkään ja haudattiin Jerusalemiin isiensä viereen Daavidin kaupunkiin.'),
(1678832,58,12,14,21,'Mutta koko Juudan kansa otti Asarjan, joka oli kuudentoista vuoden vanha, ja teki hänet kuninkaaksi hänen isänsä Amasjan sijaan.'),
(1678833,58,12,14,22,'Hän linnoitti Eelatin ja palautti sen Juudalle, sittenkuin kuningas oli mennyt lepoon isiensä tykö.'),
(1678834,58,12,14,23,'Juudan kuninkaan Amasjan, Jooaan pojan, viidentenätoista hallitusvuotena tuli Jerobeam, Jooaan poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa neljäkymmentä yksi vuotta.'),
(1678835,58,12,14,24,'Hän teki sitä, mikä on pahaa Herran silmissä; hän ei luopunut mistään Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.'),
(1678836,58,12,14,25,'Hän palautti entiselleen Israelin alueen, siitä, mistä mennään Hamatiin, aina Aromaan mereen saakka, sen sanan mukaan, jonka Herra, Israelin Jumala, oli puhunut palvelijansa, profeetta Joonan, Amittain pojan, kautta, joka oli kotoisin Gat-Heeferistä.'),
(1678837,58,12,14,26,'Sillä Herra oli nähnyt Israelin ylen katkeran kurjuuden, kuinka kaikki tyynni menehtyivät eikä Israelilla ollut auttajaa.'),
(1678838,58,12,14,27,'Herra ei ollut vielä sanonut, että hän oli pyyhkivä Israelin nimen pois taivaan alta, ja niin hän vapautti heidät Jerobeamin, Jooaan pojan, kautta.'),
(1678839,58,12,14,28,'Mitä muuta on kerrottavaa Jerobeamista, kaikesta, mitä hän teki, ja hänen urotöistänsä, kuinka hän kävi sotaa ja kuinka hän palautti Israelille Damaskosta ja Hamatista sen, mikä oli ollut Juudan, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678840,58,12,14,29,'Ja Jerobeam meni lepoon isiensä, Israelin kuningasten, tykö. Ja hänen poikansa Sakarja tuli kuninkaaksi hänen sijaansa.'),
(1678841,58,12,15,1,'Jerobeamin, Israelin kuninkaan, kahdentenakymmenentenä seitsemäntenä hallitusvuotena tuli Asarja, Amasjan poika, Juudan kuninkaaksi.'),
(1678842,58,12,15,2,'Hän oli kuudentoista vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa viisikymmentä kaksi vuotta. Hänen äitinsä oli nimeltään Jekolja, Jerusalemista.'),
(1678843,58,12,15,3,'Ja hän teki sitä, mikä on oikein Herran silmissä, aivan niinkuin hänen isänsä Amasja oli tehnyt.'),
(1678844,58,12,15,4,'Kuitenkaan eivät uhrikukkulat hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla.'),
(1678845,58,12,15,5,'Ja Herra löi kuningasta, niin että hän oli pitalitautinen kuolinpäiväänsä saakka. Hän asui eri talossa, mutta Jootam, kuninkaan poika, oli linnan päällikkönä ja tuomitsi maan kansaa.'),
(1678846,58,12,15,6,'Mitä muuta on kerrottavaa Asarjasta ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.'),
(1678847,58,12,15,7,'Ja Asarja meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Ja hänen poikansa Jootam tuli kuninkaaksi hänen sijaansa.'),
(1678848,58,12,15,8,'Asarjan, Juudan kuninkaan, kolmantenakymmenentenä kahdeksantena hallitusvuotena tuli Sakarja, Jerobeamin poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa kuusi kuukautta.'),
(1678849,58,12,15,9,'Ja hän teki sitä, mikä on pahaa Herran silmissä, niinkuin hänen isänsäkin olivat tehneet; hän ei luopunut Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.'),
(1678850,58,12,15,10,'Ja Sallum, Jaabeksen poika, teki salaliiton häntä vastaan ja löi hänet kuoliaaksi kansan nähden ja tuli kuninkaaksi hänen sijaansa.'),
(1678851,58,12,15,11,'Mitä muuta on kerrottavaa Sakarjasta, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678852,58,12,15,12,'Näin toteutui Herran sana, jonka hän oli puhunut Jeehulle sanoen: "Sinun poikasi istukoot Israelin valtaistuimella neljänteen polveen": niin tapahtui.'),
(1678853,58,12,15,13,'Sallum, Jaabeksen poika, tuli kuninkaaksi Ussian, Juudan kuninkaan, kolmantenakymmenentenä yhdeksäntenä hallitusvuotena, ja hän hallitsi Samariassa kuukauden päivät.'),
(1678854,58,12,15,14,'Mutta silloin Menahem, Gaadin poika, lähti liikkeelle Tirsasta, tuli Samariaan ja löi Sallumin, Jaabeksen pojan, kuoliaaksi Samariassa. Ja hän tuli kuninkaaksi tämän sijaan.'),
(1678855,58,12,15,15,'Mitä muuta on kerrottavaa Sallumista ja salaliitosta, jonka hän teki, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678856,58,12,15,16,'Siihen aikaan Menahem hävitti Tifsahin ja kaiken, mitä siellä oli, niin myös sen alueen Tirsasta lähtien, koska he eivät avanneet hänelle portteja; hän hävitti sen ja halkaisi kaikki raskaat vaimot.'),
(1678857,58,12,15,17,'Juudan kuninkaan Asarjan kolmantenakymmenentenä yhdeksäntenä hallitusvuotena tuli Menahem, Gaadin poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa kymmenen vuotta.'),
(1678858,58,12,15,18,'Hän teki sitä, mikä on pahaa Herran edessä; hän ei luopunut koko elinaikanaan mistään Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.'),
(1678859,58,12,15,19,'Puul, Assurin kuningas, hyökkäsi maahan; ja Menahem antoi Puulille tuhat talenttia hopeata, että tämä auttaisi häntä ja vahvistaisi kuninkuuden hänen käsiinsä.'),
(1678860,58,12,15,20,'Ja Menahem otti rahat verona Israelilta, kaikilta varakkailta miehiltä, niin että jokainen joutui maksamaan Assurin kuninkaalle viisikymmentä sekeliä hopeata.'),
(1678861,58,12,15,21,'Niin Assurin kuningas palasi takaisin eikä jäänyt siihen maahan. Mitä muuta on kerrottavaa Menahemista ja kaikesta, mitä hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678862,58,12,15,22,'Ja Menahem meni lepoon isiensä tykö. Ja hänen poikansa Pekahja tuli kuninkaaksi hänen sijaansa.'),
(1678863,58,12,15,23,'Juudan kuninkaan Asarjan viidentenäkymmenentenä hallitusvuotena tuli Pekahja, Menahemin poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa kaksi vuotta.'),
(1678864,58,12,15,24,'Hän teki sitä, mikä on pahaa Herran silmissä; hän ei luopunut Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.'),
(1678865,58,12,15,25,'Ja Pekah, Remaljan poika, hänen vaunusoturinsa, teki salaliiton häntä vastaan ja tappoi hänet Samariassa kuninkaan linnan palatsissa, sekä hänet että Argobin ja Arjen, jolloin Pekahilla oli mukanaan viisikymmentä Gileadin miestä. Näin tämä surmasi hänet ja tuli kuninkaaksi hänen sijaansa.'),
(1678866,58,12,15,26,'Mitä muuta on kerrottavaa Pekahjasta ja kaikesta, mitä hän teki, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678867,58,12,15,27,'Juudan kuninkaan Asarjan viidentenäkymmenentenä toisena hallitusvuotena tuli Pekah, Remaljan poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa kaksikymmentä vuotta.'),
(1678868,58,12,15,28,'Hän teki sitä, mikä on pahaa Herran silmissä; hän ei luopunut Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.'),
(1678869,58,12,15,29,'Israelin kuninkaan Pekahin aikana tuli Tiglat-Pileser, Assurin kuningas, ja valloitti Iijonin, Aabel-Beet-Maakan, Jaanoahin, Kedeksen, Haasorin, Gileadin ja Galilean, koko Naftalin maan, ja vei asukkaat pakkosiirtolaisuuteen Assuriin.'),
(1678870,58,12,15,30,'Mutta Hoosea, Eelan poika, teki salaliiton Pekahia, Remaljan poikaa, vastaan ja löi hänet kuoliaaksi ja tuli kuninkaaksi hänen sijaansa Jootamin, Ussian pojan, kahdentenakymmenentenä hallitusvuotena.'),
(1678871,58,12,15,31,'Mitä muuta on kerrottavaa Pekahista ja kaikesta, mitä hän teki, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.'),
(1678872,58,12,15,32,'Israelin kuninkaan Pekahin, Remaljan pojan, toisena hallitusvuotena tuli Jootam, Juudan kuninkaan Ussian poika, kuninkaaksi.'),
(1678873,58,12,15,33,'Hän oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa kuusitoista vuotta. Hänen äitinsä oli nimeltään Jerusa, Saadokin tytär.'),
(1678874,58,12,15,34,'Hän teki sitä, mikä on oikein Herran silmissä, aivan niinkuin hänen isänsä Ussia oli tehnyt.'),
(1678875,58,12,15,35,'Kuitenkaan uhrikukkulat eivät hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla. Hän rakennutti Yläportin Herran temppeliin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678876,58,12,15,36,'Mitä muuta on kerrottavaa Jootamista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.'),
(1678877,58,12,15,37,'Niihin aikoihin alkoivat Resin, Aramin kuningas, ja Pekah, Remaljan poika, Herran lähettäminä käydä Juudan kimppuun.'),
(1678878,58,12,15,38,'Ja Jootam meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen, isänsä Daavidin kaupunkiin. Ja hänen poikansa Aahas tuli kuninkaaksi hänen sijaansa.'),
(1678879,58,12,16,1,'Pekahin, Remaljan pojan, seitsemäntenätoista hallitusvuotena tuli Aahas, Juudan kuninkaan Jootamin poika, kuninkaaksi.'),
(1678880,58,12,16,2,'Aahas oli kahdenkymmenen vuoden vanha tullessansa kuninkaaksi ja hallitsi Jerusalemissa kuusitoista vuotta. Hän ei tehnyt sitä, mikä oli oikein Herran, hänen Jumalansa, silmissä, niinkuin hänen isänsä Daavid,'),
(1678881,58,12,16,3,'vaan vaelsi Israelin kuningasten tietä; jopa hän pani poikansakin kulkemaan tulen läpi, niiden kansain kauhistavien tekojen mukaan, jotka Herra oli karkoittanut israelilaisten tieltä.'),
(1678882,58,12,16,4,'Ja hän uhrasi ja suitsutti uhrikukkuloilla ja kummuilla ja jokaisen viheriän puun alla.'),
(1678883,58,12,16,5,'Siihen aikaan Resin, Aramin kuningas, ja Pekah, Remaljan poika, Israelin kuningas, lähtivät Jerusalemiin sotimaan. Ja he saartoivat Aahaan, mutta eivät voineet valloittaa kaupunkia.'),
(1678884,58,12,16,6,'Samaan aikaan Resin, Aramin kuningas, palautti Eelatin Aramille ja karkoitti Juudan miehet Eelatista. Niin tulivat aramilaiset Eelatiin ja asettuivat sinne, ja siellä heitä on tänäkin päivänä.'),
(1678885,58,12,16,7,'Mutta Aahas lähetti sanansaattajat Assurin kuninkaan Tiglat-Pileserin luo ja käski sanoa hänelle: "Minä olen sinun palvelijasi ja sinun poikasi. Tule ja pelasta minut Aramin kuninkaan ja Israelin kuninkaan käsistä; he ovat hyökänneet minun kimppuuni."'),
(1678886,58,12,16,8,'Ja Aahas otti hopean ja kullan, mitä Herran temppelissä ja kuninkaan palatsin aarrekammioissa oli, ja lähetti sen lahjaksi Assurin kuninkaalle.'),
(1678887,58,12,16,9,'Ja Assurin kuningas kuuli häntä. Niin Assurin kuningas lähti Damaskoa vastaan ja valloitti sen, vei asukkaat pakkosiirtolaisuuteen Kiiriin ja surmasi Resinin.'),
(1678888,58,12,16,10,'Silloin kuningas Aahas lähti Damaskoon kohtaamaan Assurin kuningasta Tiglat-Pileseriä. Ja kun kuningas Aahas näki Damaskossa olevan alttarin, lähetti hän pappi Uurialle kuvan alttarista ja sen mukaan tehdyn tarkan mallin.'),
(1678889,58,12,16,11,'Ja pappi Uuria rakensi alttarin; aivan sen määräyksen mukaan, jonka kuningas Aahas oli hänelle lähettänyt Damaskosta; aivan sen mukaan pappi Uuria teki, jo ennenkuin kuningas Aahas oli palannut Damaskosta.'),
(1678890,58,12,16,12,'Ja kun kuningas palasi Damaskosta ja näki alttarin, astui hän alttarin ääreen ja nousi sen päälle,'),
(1678891,58,12,16,13,'poltti polttouhrinsa ja ruokauhrinsa, vuodatti juomauhrinsa ja vihmoi uhraamansa uhrin veren alttarille.'),
(1678892,58,12,16,14,'Mutta vaskialttarin, joka oli Herran edessä, hän siirsi pois temppelin edustalta, alttarin ja Herran temppelin väliltä, ja pani sen alttarin pohjoissivulle.'),
(1678893,58,12,16,15,'Ja kuningas Aahas käski pappi Uuriaa ja sanoi: "Polta suuremmalla alttarilla aamu-polttouhri ja ehtoo-ruokauhri ja kuninkaan polttouhri sekä hänen ruokauhrinsa, niin myös koko maan kansan polttouhri sekä heidän ruoka- ja juomauhrinsa; ja vihmo kaikki sekä polttouhrin että teurasuhrin veri sen päälle. Mutta vaskialttarin käyttämistä minä vielä mietin."'),
(1678894,58,12,16,16,'Ja pappi Uuria teki kaiken, mitä kuningas Aahas oli käskenyt.'),
(1678895,58,12,16,17,'Kuningas Aahas leikkautti irti telineiden kehäpienat ja otti pois altaat niiden päältä; ja meren hän nostatti pois vaskiraavasten päältä, jotka olivat sen alla, ja panetti sen kivialustalle.'),
(1678896,58,12,16,18,'Ja katetun sapattikäytävän, joka oli rakennettu temppeliin, ja kuninkaan ulkopuolisen sisäänkäytävän hän muutti Herran temppelin sisään Assurin kuninkaan vuoksi.'),
(1678897,58,12,16,19,'Mitä muuta on vielä kerrottavaa Aahaasta, siitä, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.'),
(1678898,58,12,16,20,'Ja Aahas meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Ja hänen poikansa Hiskia tuli kuninkaaksi hänen sijaansa.'),
(1678899,58,12,17,1,'Juudan kuninkaan Aahaan kahdentenatoista hallitusvuotena tuli Hoosea, Eelan poika, Israelin kuninkaaksi Samariaan, ja hän hallitsi yhdeksän vuotta.'),
(1678900,58,12,17,2,'Hän teki sitä, mikä on pahaa Herran silmissä, ei kuitenkaan niinkuin ne Israelin kuninkaat, jotka olivat olleet ennen häntä.'),
(1678901,58,12,17,3,'Hänen kimppuunsa hyökkäsi Salmaneser, Assurin kuningas; ja Hoosea tuli hänen palvelijakseen ja maksoi hänelle veroa.'),
(1678902,58,12,17,4,'Mutta Assurin kuningas huomasi Hoosean olevan salahankkeissa, koska tämä lähetti sanansaattajat Soon, Egyptin kuninkaan, luo eikä suorittanut enää niinkuin ennen vuotuista veroa Assurin kuninkaalle. Niin Assurin kuningas vangitutti hänet ja piti häntä sidottuna vankilassa.'),
(1678903,58,12,17,5,'Ja Assurin kuningas hyökkäsi koko maan kimppuun ja meni Samariaan ja piiritti sitä kolme vuotta.'),
(1678904,58,12,17,6,'Hoosean yhdeksäntenä hallitusvuotena Assurin kuningas valloitti Samarian ja vei Israelin pakkosiirtolaisuuteen Assuriin ja asetti heidät asumaan Halahiin ja Haaborin, Goosanin joen, rannoille sekä Meedian kaupunkeihin.'),
(1678905,58,12,17,7,'Näin tapahtui, koska israelilaiset olivat tehneet syntiä Herraa, Jumalaansa, vastaan, joka oli johdattanut heidät Egyptin maasta, pois faraon, Egyptin kuninkaan, käsistä, ja koska he olivat peljänneet muita jumalia.'),
(1678906,58,12,17,8,'He olivat myös vaeltaneet niiden kansain säädösten mukaan, jotka Herra oli karkoittanut israelilaisten tieltä, ja tehneet sitä, mitä Israelin kuninkaatkin.'),
(1678907,58,12,17,9,'Israelilaiset olivat tehneet Herraa, Jumalaansa, vastaan sellaista, mikä ei ole oikein: he olivat rakentaneet itsellensä uhrikukkuloita kaikkiin kaupunkeihinsa, sekä vartiotornien luo että varustettuihin kaupunkeihin.'),
(1678908,58,12,17,10,'He olivat pystyttäneet itsellensä patsaita ja asera-karsikkoja jokaiselle korkealle kummulle ja jokaisen viheriän puun alle.'),
(1678909,58,12,17,11,'He olivat polttaneet uhreja kaikilla uhrikukkuloilla, niinkuin ne kansat, jotka Herra oli karkoittanut heidän tieltänsä, olivat harjoittaneet pahuutta ja vihoittaneet Herran.'),
(1678910,58,12,17,12,'He olivat palvelleet kivijumalia, vaikka Herra oli heille sanonut: "Älkää tehkö sitä".'),
(1678911,58,12,17,13,'Ja Herra oli varoittanut sekä Israelia että Juudaa kaikkien profeettainsa, kaikkien näkijäin, kautta ja sanonut: "Palatkaa pahoilta teiltänne ja noudattakaa minun käskyjäni ja säädöksiäni, kaiken sen lain mukaan, jonka minä annoin teidän isillenne ja jonka minä olen teille ilmoittanut palvelijaini, profeettain, kautta".'),
(1678912,58,12,17,14,'Mutta he eivät kuulleet, vaan olivat niskureita niinkuin heidän isänsäkin, jotka eivät uskoneet Herraan, Jumalaansa.'),
(1678913,58,12,17,15,'He hylkäsivät hänen käskynsä ja hänen liittonsa, jonka hän oli tehnyt heidän isiensä kanssa, ja todistukset, jotka hän oli heille antanut. He seurasivat turhia jumalia, ja turhanpäiväisiksi he tulivat, kun seurasivat pakanakansoja, jotka asuivat heidän ympärillänsä, vaikka Herra oli kieltänyt heitä tekemästä niinkuin ne.'),
(1678914,58,12,17,16,'He hylkäsivät Herran, Jumalansa, kaikki käskyt ja tekivät itsellensä valettuja kuvia, kaksi vasikkaa. Ja he tekivät itsellensä myös asera-karsikkoja ja kumarsivat kaikkea taivaan joukkoa ja palvelivat Baalia.'),
(1678915,58,12,17,17,'Ja he panivat poikansa ja tyttärensä kulkemaan tulen läpi ja tekivät taikoja ja harjoittivat noituutta. He myivät itsensä tekemään sitä, mikä on pahaa Herran silmissä, ja vihoittivat hänet.'),
(1678916,58,12,17,18,'Niin Herra vihastui suuresti Israeliin ja poisti heidät kasvojensa edestä, niin ettei muuta jäänyt jäljelle kuin Juudan sukukunta yksin.'),
(1678917,58,12,17,19,'Ei myöskään Juuda pitänyt Herran, Jumalansa, käskyjä, vaan he vaelsivat niiden säädösten mukaan, jotka Israel itse oli tehnyt.'),
(1678918,58,12,17,20,'Niin Herra hylkäsi koko Israelin heimon, nöyryytti heitä ja antoi heidät ryöstäjien käsiin ja heitti viimein heidät pois kasvojensa edestä.'),
(1678919,58,12,17,21,'Sillä kun hän oli reväissyt Israelin Daavidin suvulta ja he olivat tehneet kuninkaaksi Jerobeamin, Nebatin pojan, käänsi Jerobeam Israelin pois Herrasta ja saattoi heidät tekemään suuren synnin.'),
(1678920,58,12,17,22,'Ja israelilaiset vaelsivat kaikissa synneissä, joita Jerobeam oli tehnyt; he eivät luopuneet niistä.'),
(1678921,58,12,17,23,'Ja niin Herra viimein poisti Israelin kasvojensa edestä, niinkuin hän oli puhunut kaikkien palvelijainsa, profeettain, kautta. Ja Israel vietiin pois maastansa pakkosiirtolaisuuteen Assuriin, jossa he ovat tänäkin päivänä.'),
(1678922,58,12,17,24,'Sen jälkeen Assurin kuningas antoi tuoda kansaa Baabelista, Kuutasta, Avvasta, Hamatista ja Sefarvaimista ja asetti heidät asumaan Samarian kaupunkeihin israelilaisten sijaan. Ja he ottivat Samarian omaksensa ja asettuivat sen kaupunkeihin.'),
(1678923,58,12,17,25,'Ja kun he siellä olonsa ensi aikoina eivät peljänneet Herraa, lähetti Herra heidän sekaansa leijonia, jotka tappoivat heitä.'),
(1678924,58,12,17,26,'Se ilmoitettiin Assurin kuninkaalle näin: "Kansat, jotka sinä veit pakkosiirtolaisuuteen ja asetit asumaan Samarian kaupunkeihin, eivät tiedä, millä tavalla sen maan Jumalaa on palveltava. Sentähden hän on lähettänyt leijonia heidän sekaansa, ja katso, ne surmaavat heitä, koska he eivät tiedä, millä tavalla sen maan Jumalaa on palveltava."'),
(1678925,58,12,17,27,'Silloin Assurin kuningas käski sanoen: "Viekää sinne joku niistä papeista, jotka toitte sieltä pakkosiirtolaisuuteen; joku heistä menköön sinne ja asukoon siellä ja opettakoon heille, millä tavalla sen maan Jumalaa on palveltava."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678926,58,12,17,28,'Ja niin eräs niistä papeista, jotka he olivat vieneet Samariasta pakkosiirtolaisuuteen, tuli ja asettui Beeteliin; ja hän opetti heille, kuinka heidän oli peljättävä Herraa.'),
(1678927,58,12,17,29,'Mutta kukin kansa teki itselleen omat jumalansa, ja he panivat ne samarialaisten rakentamiin uhrikukkula-temppeleihin, kukin kansa niissä kaupungeissa, joissa se asui.'),
(1678928,58,12,17,30,'Baabelin miehet tekivät itselleen Sukkot-Benotin, Kuutin miehet tekivät Neergalin, Hamatin miehet Asiman,'),
(1678929,58,12,17,31,'avvalaiset tekivät Nibhaan ja Tartakin, sefarvaimilaiset polttivat poikiansa tulessa Adrammelekille ja Annammelekille, Sefarvaimin jumalille.'),
(1678930,58,12,17,32,'Mutta he pelkäsivät myöskin Herraa. Ja he asettivat itsellensä uhrikukkula-pappeja omasta keskuudestaan, ja nämä uhrasivat heidän puolestaan uhrikukkula-temppeleissä.'),
(1678931,58,12,17,33,'He pelkäsivät tosin Herraa, mutta palvelivat myös omia jumaliansa samalla tavalla kuin ne kansat, joiden keskuudesta heidät oli tuotu.'),
(1678932,58,12,17,34,'Ja vielä tänäkin päivänä he tekevät vanhan tapansa mukaan: he eivät pelkää Herraa eivätkä tee saamiensa säädösten ja oikeuksien mukaan, eivät sen lain ja niiden käskyjen mukaan, jotka Herra on antanut Jaakobin pojille, hänen, jolle hän antoi nimen Israel.'),
(1678933,58,12,17,35,'Herra teki liiton näiden kanssa ja käski heitä sanoen: "Älkää peljätkö muita jumalia, älkää kumartako ja palvelko niitä älkääkä uhratko niille,'),
(1678934,58,12,17,36,'vaan Herraa, joka johdatti teidät Egyptin maasta suurella voimalla ja ojennetulla käsivarrella, häntä te peljätkää, häntä kumartakaa ja hänelle uhratkaa.'),
(1678935,58,12,17,37,'Ja niitä säädöksiä ja oikeuksia, sitä lakia ja niitä käskyjä, jotka hän on teille kirjoittanut, te alati tarkoin noudattakaa, mutta älkää peljätkö muita jumalia.'),
(1678936,58,12,17,38,'Liittoa, jonka minä tein teidän kanssanne, älkää unhottako. Älkääkä peljätkö muita jumalia,'),
(1678937,58,12,17,39,'vaan peljätkää ainoastaan Herraa, teidän Jumalaanne, niin hän pelastaa teidät kaikkien vihollistenne käsistä."'),
(1678938,58,12,17,40,'Mutta he eivät totelleet, vaan tekivät vanhan tapansa mukaan.'),
(1678939,58,12,17,41,'Niin nämä kansat pelkäsivät Herraa, mutta palvelivat samalla omia jumalankuviansa. Myöskin heidän lapsensa ja heidän lastensa lapset tekevät vielä tänä päivänä samoin, kuin heidän isänsä ovat tehneet.'),
(1678940,58,12,18,1,'Israelin kuninkaan Hoosean, Eelan pojan, kolmantena hallitusvuotena tuli Hiskia, Juudan kuninkaan Aahaan poika, kuninkaaksi.'),
(1678941,58,12,18,2,'Hän oli kahdenkymmenen viiden vuoden vanha tullessansa kuninkaaksi, ja hän hallitsi Jerusalemissa kaksikymmentä yhdeksän vuotta. Hänen äitinsä oli nimeltään Abi, Sakarjan tytär.'),
(1678942,58,12,18,3,'Hän teki sitä, mikä on oikein Herran silmissä, aivan niinkuin hänen isänsä Daavid oli tehnyt.'),
(1678943,58,12,18,4,'Hän poisti uhrikukkulat, murskasi patsaat, hakkasi maahan asera-karsikon ja löi palasiksi vaskikäärmeen, jonka Mooses oli tehnyt; sillä niihin aikoihin asti israelilaiset olivat polttaneet uhreja sille; sitä kutsuttiin nimellä Nehustan.'),
(1678944,58,12,18,5,'Hän turvasi Herraan, Israelin Jumalaan, niin ettei kukaan ollut hänen kaltaisensa kaikista hänen jälkeläisistään Juudan kuninkaista eikä niistä, jotka olivat olleet ennen häntä.'),
(1678945,58,12,18,6,'Hän riippui Herrassa kiinni eikä luopunut hänestä, vaan noudatti hänen käskyjänsä, jotka Herra oli antanut Moosekselle.'),
(1678946,58,12,18,7,'Niin Herra oli hänen kanssansa; hän menestyi kaikessa, mihin ryhtyi. Hän kapinoi Assurin kuningasta vastaan eikä enää palvellut häntä.'),
(1678947,58,12,18,8,'Hän voitti filistealaiset ja valtasi heidän alueensa aina Gassaan asti, sekä vartiotornit että varustetut kaupungit.'),
(1678948,58,12,18,9,'Mutta kuningas Hiskian neljäntenä hallitusvuotena, joka oli Israelin kuninkaan Hoosean, Eelan pojan, seitsemäs hallitusvuosi, hyökkäsi Salmaneser, Assurin kuningas, Samarian kimppuun ja piiritti sitä.'),
(1678949,58,12,18,10,'Ja hän valloitti sen kolmen vuoden kuluttua. Hiskian kuudentena hallitusvuotena, joka oli Israelin kuninkaan Hoosean yhdeksäs hallitusvuosi, valloitettiin Samaria.'),
(1678950,58,12,18,11,'Ja Assurin kuningas vei Israelin pakkosiirtolaisuuteen Assuriin ja sijoitti heidät Halahiin ja Haaborin, Goosanin joen, rannoille ja Meedian kaupunkeihin,'),
(1678951,58,12,18,12,'sentähden että he eivät olleet kuulleet Herran, Jumalansa, ääntä, vaan olivat rikkoneet hänen liittonsa, kaiken, mitä Mooses, Herran palvelija, oli käskenyt; he eivät olleet kuulleet sitä eivätkä tehneet sen mukaan.'),
(1678952,58,12,18,13,'Kuningas Hiskian neljäntenätoista hallitusvuotena hyökkäsi Sanherib, Assurin kuningas, kaikkien Juudan varustettujen kaupunkien kimppuun ja valloitti ne.'),
(1678953,58,12,18,14,'Niin Hiskia, Juudan kuningas, lähetti Assurin kuninkaalle Laakiiseen sanan: "Minä olen rikkonut, käänny pois minun kimpustani. Minä kannan, mitä panet kannettavakseni." Niin Assurin kuningas määräsi Hiskian, Juudan kuninkaan, maksettavaksi kolmesataa talenttia hopeata ja kolmekymmentä talenttia kultaa.'),
(1678954,58,12,18,15,'Ja Hiskia antoi kaikki rahat, mitä Herran temppelissä ja kuninkaan linnan aarrekammioissa oli.'),
(1678955,58,12,18,16,'Siihen aikaan Hiskia leikkautti irti Herran temppelin ovista ja pihtipielistä sen päällystyksen, jolla Hiskia, Juudan kuningas, oli päällystänyt ne, ja antoi sen Assurin kuninkaalle.'),
(1678956,58,12,18,17,'Mutta Assurin kuningas lähetti Laakiista Tartanin ja ylimmäisen hoviherran ja Rabsaken suuren sotajoukon kanssa kuningas Hiskiaa vastaan Jerusalemiin. Ja nämä lähtivät liikkeelle ja tulivat Jerusalemiin; ja lähdettyänsä liikkeelle ja tultuansa he pysähtyivät Ylälammikon vesijohdolle, joka on Vanuttajankedon tien varrella.'),
(1678957,58,12,18,18,'Kun he sitten kutsuivat kuningasta, menivät Eljakim, Hilkian poika, joka oli linnan päällikkönä, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, heidän luoksensa.'),
(1678958,58,12,18,19,'Ja Rabsake sanoi heille: "Sanokaa Hiskialle: Näin sanoo suurkuningas, Assurin kuningas: ''Mitä on tuo luottamus, mikä sinulla on?'),
(1678959,58,12,18,20,'Arvelet kai, että pelkästä huulten puheesta tulee neuvo ja voima sodankäyntiin. Keneen sinä oikein luotat, kun kapinoit minua vastaan?'),
(1678960,58,12,18,21,'Katso, sinä luotat nyt Egyptiin, tuohon särkyneeseen ruokosauvaan, joka tunkeutuu sen käteen, joka siihen nojaa, ja lävistää sen. Sellainen on farao, Egyptin kuningas, kaikille, jotka häneen luottavat.'),
(1678961,58,12,18,22,'Vai sanotteko te ehkä minulle: Me luotamme Herraan, meidän Jumalaamme? Mutta eikö hän ole se, jonka uhrikukkulat ja alttarit Hiskia poisti, kun hän sanoi Juudalle ja Jerusalemille: Tämän alttarin edessä on teidän kumartaen rukoiltava, täällä Jerusalemissa?'''),
(1678962,58,12,18,23,'Mutta lyö nyt vetoa minun herrani, Assurin kuninkaan, kanssa: minä annan sinulle kaksi tuhatta hevosta, jos sinä voit hankkia niille ratsastajat.'),
(1678963,58,12,18,24,'Kuinka sinä sitten voisit torjua ainoankaan käskynhaltijan, ainoankaan minun herrani vähimmän palvelijan, hyökkäyksen? Ja sinä vain luotat Egyptiin, sen vaunuihin ja ratsumiehiin.'),
(1678964,58,12,18,25,'Olenko minä siis Herran sallimatta hyökännyt tämän paikan kimppuun hävittämään sitä? Herra itse on sanonut minulle: ''Hyökkää tähän maahan ja hävitä se''."'),
(1678965,58,12,18,26,'Niin Eljakim, Hilkian poika, ja Sebna ja Jooah sanoivat Rabsakelle: "Puhu palvelijoillesi araminkieltä, sillä me ymmärrämme sitä; älä puhu meidän kanssamme juudankieltä kansan kuullen, jota on muurilla".'),
(1678966,58,12,18,27,'Mutta Rabsake vastasi heille: "Onko minun herrani lähettänyt minut puhumaan näitä sanoja sinun herrallesi ja sinulle? Eikö juuri niille miehille, jotka istuvat muurilla ja joutuvat teidän kanssanne syömään omaa likaansa ja juomaan omaa vettänsä?"'),
(1678967,58,12,18,28,'Sitten Rabsake astui esiin, huusi kovalla äänellä juudankielellä, puhui ja sanoi: "Kuulkaa suurkuninkaan, Assurin kuninkaan, sana.'),
(1678968,58,12,18,29,'Näin sanoo kuningas: ''Älkää antako Hiskian pettää itseänne, sillä hän ei voi pelastaa teitä minun käsistäni.'),
(1678969,58,12,18,30,'Älköön Hiskia saako teitä luottamaan Herraan, kun hän sanoo: Herra on varmasti pelastava meidät, eikä tätä kaupunkia anneta Assurin kuninkaan käsiin.'),
(1678970,58,12,18,31,'Älkää kuulko Hiskiaa.'' Sillä Assurin kuningas sanoo näin: ''Tehkää sovinto minun kanssani ja antautukaa minulle, niin te saatte syödä kukin omasta viinipuustanne ja viikunapuustanne ja juoda kukin omasta kaivostanne,'),
(1678971,58,12,18,32,'kunnes minä tulen ja vien teidät maahan, joka on teidän maanne kaltainen, vilja-, viini- ja leipämaahan, viinitarhojen, jalon öljypuun ja hunajan maahan; ja niin te saatte elää ettekä kuole. Mutta älkää kuulko Hiskiaa; sillä hän viettelee teidät, kun sanoo: Herra pelastaa meidät.'),
(1678972,58,12,18,33,'Onko muidenkaan kansojen jumalista yksikään pelastanut maatansa Assurin kuninkaan käsistä?'),
(1678973,58,12,18,34,'Missä ovat Hamatin ja Arpadin jumalat? Missä ovat Sefarvaimin, Heenan ja Ivvan jumalat? Ovatko ne pelastaneet Samariaa minun käsistäni?'),
(1678974,58,12,18,35,'Onko muiden maiden kaikista jumalista ainoakaan pelastanut maatansa minun käsistäni? Kuinka sitten Herra pelastaisi Jerusalemin minun käsistäni?''"'),
(1678975,58,12,18,36,'Mutta kansa oli vaiti, eivätkä he vastanneet hänelle mitään; sillä kuningas oli käskenyt niin ja sanonut: "Älkää vastatko hänelle".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1678976,58,12,18,37,'Sitten palatsin päällikkö Eljakim, Hilkian poika, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, tulivat Hiskian luo vaatteet reväistyinä ja kertoivat hänelle, mitä Rabsake oli sanonut.'),
(1678977,58,12,19,1,'Kun kuningas Hiskia sen kuuli, repäisi hän vaatteensa, pukeutui säkkiin ja meni Herran temppeliin.'),
(1678978,58,12,19,2,'Ja hän lähetti palatsin päällikön Eljakimin ja kirjuri Sebnan sekä pappien vanhimmat, säkkeihin puettuina, profeetta Jesajan, Aamoksen pojan, tykö.'),
(1678979,58,12,19,3,'Ja he sanoivat hänelle: "Näin sanoo Hiskia: ''Hädän, kurituksen ja häväistyksen päivä on tämä päivä, sillä lapset ovat tulleet kohdun suulle saakka, mutta ei ole voimaa synnyttää.'),
(1678980,58,12,19,4,'Ehkä Herra, sinun Jumalasi, kuulee kaikki Rabsaken sanat, joilla hänen herransa, Assurin kuningas, on lähettänyt hänet herjaamaan elävää Jumalaa, ja rankaisee häntä näistä sanoista, jotka Herra, sinun Jumalasi, on kuullut. Niin kohota nyt rukous jäännöksen puolesta, joka vielä on olemassa.''"'),
(1678981,58,12,19,5,'Kun kuningas Hiskian palvelijat tulivat Jesajan tykö,'),
(1678982,58,12,19,6,'sanoi Jesaja heille: "Sanokaa näin herrallenne: ''Näin sanoo Herra: Älä pelkää niitä sanoja, jotka olet kuullut ja joilla Assurin kuninkaan poikaset ovat häväisseet minua.'),
(1678983,58,12,19,7,'Katso, minä annan häneen mennä sellaisen hengen, että hän kuultuaan sanoman palaa omaan maahansa. Ja minä annan hänen kaatua miekkaan omassa maassansa.''"'),
(1678984,58,12,19,8,'Ja Rabsake kääntyi takaisin ja tapasi Assurin kuninkaan sotimassa Libnaa vastaan; sillä hän oli kuullut, että tämä oli lähtenyt Laakiista pois.'),
(1678985,58,12,19,9,'Mutta kun Sanherib kuuli Tirhakasta, Etiopian kuninkaasta, sanottavan: "Katso, hän on lähtenyt liikkeelle sotiakseen sinua vastaan", lähetti hän taas sanansaattajat Hiskian tykö ja käski sanoa:'),
(1678986,58,12,19,10,'"Sanokaa näin Hiskialle, Juudan kuninkaalle: ''Älä anna Jumalasi, johon sinä luotat, pettää itseäsi äläkä ajattele: Jerusalem ei joudu Assurin kuninkaan käsiin.'),
(1678987,58,12,19,11,'Olethan kuullut, mitä Assurin kuninkaat ovat tehneet kaikille maille, kuinka he ovat vihkineet ne tuhon omiksi. Ja sinäkö pelastuisit!'),
(1678988,58,12,19,12,'Ovatko kansain jumalat pelastaneet niitä, jotka minun isäni ovat tuhonneet: Goosania, Harrania, Resefiä ja Telassarin edeniläisiä?'),
(1678989,58,12,19,13,'Missä on Hamatin kuningas ja Arpadin kuningas, Sefarvaimin kaupungin, Heenan ja Ivvan kuningas?''"'),
(1678990,58,12,19,14,'Kun Hiskia oli ottanut kirjeen sanansaattajilta ja lukenut sen, meni hän Herran temppeliin; ja Hiskia levitti sen Herran eteen.'),
(1678991,58,12,19,15,'Ja Hiskia rukoili Herran edessä ja sanoi: "Herra, Israelin Jumala, jonka valtaistuinta kerubit kannattavat, sinä yksin olet maan kaikkien valtakuntain Jumala; sinä olet tehnyt taivaan ja maan.'),
(1678992,58,12,19,16,'Herra, kallista korvasi ja kuule; Herra, avaa silmäsi ja katso. Kuule Sanheribin sanat, kuinka hän lähetti tuon miehen herjaamaan elävää Jumalaa.'),
(1678993,58,12,19,17,'Se on totta, Herra, että Assurin kuninkaat ovat hävittäneet kansat ja heidän maansa.'),
(1678994,58,12,19,18,'Ja he ovat heittäneet heidän jumalansa tuleen; sillä ne eivät olleet jumalia, vaan ihmiskätten tekoa, puuta ja kiveä, ja sentähden he voivat hävittää ne.'),
(1678995,58,12,19,19,'Mutta pelasta nyt meidät, Herra, meidän Jumalamme, hänen käsistänsä, että kaikki maan valtakunnat tulisivat tietämään, että sinä, Herra, yksin olet Jumala."'),
(1678996,58,12,19,20,'Niin Jesaja, Aamoksen poika, lähetti Hiskialle tämän sanan: "Näin sanoo Herra, Israelin Jumala: Mitä sinä olet minulta Sanheribin, Assurin kuninkaan, tähden rukoillut, sen minä olen kuullut.'),
(1678997,58,12,19,21,'Ja tämä on sana, jonka Herra on puhunut hänestä: Neitsyt, tytär Siion, halveksii ja pilkkaa sinua; tytär Jerusalem nyökyttää ilkkuen päätänsä sinun jälkeesi.'),
(1678998,58,12,19,22,'Ketä olet herjannut ja häväissyt, ja ketä vastaan olet korottanut äänesi? Korkealle olet kohottanut silmäsi Israelin Pyhää vastaan.'),
(1678999,58,12,19,23,'Sanansaattajaisi kautta sinä herjasit Herraa ja sanoit: ''Monilla vaunuillani minä nousin vuorten harjalle, Libanonin ääriin saakka; minä hakkasin maahan sen korkeat setrit, sen parhaat kypressit, ja tunkeuduin sen etäisimpään yöpaikkaan, sen rehevimpään metsään;'),
(1679000,58,12,19,24,'minä kaivoin kaivoja ja join kuiviin muukalaisten vedet, ja jalkapohjallani minä kuivasin kaikki Egyptin virrat''.'),
(1679001,58,12,19,25,'Etkö ole kuullut: kauan sitten minä olen tätä valmistanut, muinaisuudesta saakka tätä aivoitellut! Nyt minä olen sen toteuttanut, ja niin sinä sait hävittää varustetut kaupungit autioiksi kiviroukkioiksi,'),
(1679002,58,12,19,26,'ja niiden asukkaat olivat voimattomat, he kauhistuivat ja joutuivat häpeään; heidän kävi niinkuin kedon ruohon ja niinkuin vihannan heinän, niinkuin katolla kasvavain kortten ja niinkuin laihon, joka kuivettuu ennen oljelle tulemistaan.'),
(1679003,58,12,19,27,'Istuitpa sinä tai lähdit tai tulit, minä sen tiedän, niinkuin senkin, että sinä raivoat minua vastaan.'),
(1679004,58,12,19,28,'Koska sinä minua vastaan raivoat ja koska sinun ylpeytesi on tullut minun korviini, niin minä panen koukkuni sinun nenääsi ja suitseni sinun suuhusi ja vien sinut takaisin samaa tietä, jota tulitkin.'),
(1679005,58,12,19,29,'Ja tämä on oleva sinulle merkkinä: tänä vuonna syödään jälkikasvua ja toisena vuonna kesanto-aaluvaa, mutta kolmantena vuonna te kylväkää ja leikatkaa, istuttakaa viinitarhoja ja syökää niiden hedelmää.'),
(1679006,58,12,19,30,'Ja Juudan heimon pelastuneet, jotka ovat jäljelle jääneet, tekevät taas juurta alaspäin ja hedelmää ylöspäin.'),
(1679007,58,12,19,31,'Sillä Jerusalemista lähtee kasvamaan jäännös, pelastunut joukko Siionin vuorelta. Herran kiivaus on sen tekevä.'),
(1679008,58,12,19,32,'Sentähden, näin sanoo Herra Assurin kuninkaasta: Hän ei tule tähän kaupunkiin eikä siihen nuolta ammu, ei tuo sitä vastaan kilpeä eikä luo sitä vastaan vallia.'),
(1679009,58,12,19,33,'Samaa tietä, jota hän tuli, hän palajaa, ja tähän kaupunkiin hän ei tule, sanoo Herra.'),
(1679010,58,12,19,34,'Sillä minä varjelen tämän kaupungin ja pelastan sen itseni tähden ja palvelijani Daavidin tähden."'),
(1679011,58,12,19,35,'Ja sinä yönä Herran enkeli lähti ja löi Assurin leirissä sata kahdeksankymmentä viisi tuhatta miestä, ja kun noustiin aamulla varhain, niin katso, ne olivat kaikki kuolleina ruumiina.'),
(1679012,58,12,19,36,'Silloin Sanherib, Assurin kuningas, lähti liikkeelle ja meni pois; hän palasi takaisin ja jäi Niiniveen.'),
(1679013,58,12,19,37,'Mutta kun hän oli kerran rukoilemassa jumalansa Nisrokin temppelissä, surmasivat Adrammelek ja Sareser hänet miekalla; sitten he pakenivat Araratin maahan. Ja hänen poikansa Eesarhaddon tuli kuninkaaksi hänen sijaansa.'),
(1679014,58,12,20,1,'Niihin aikoihin Hiskia sairastui ja oli kuolemaisillansa; ja profeetta Jesaja, Aamoksen poika, tuli hänen tykönsä ja sanoi hänelle: "Näin sanoo Herra: Toimita talosi; sillä sinä kuolet etkä enää parane".'),
(1679015,58,12,20,2,'Niin hän käänsi kasvonsa seinään päin ja rukoili Herraa sanoen:'),
(1679016,58,12,20,3,'"Oi Herra, muista, kuinka minä olen vaeltanut sinun edessäsi uskollisesti ja ehyellä sydämellä ja tehnyt sitä, mikä on hyvää sinun silmissäsi!" Ja Hiskia itki katkerasti.'),
(1679017,58,12,20,4,'Mutta Jesaja ei ollut vielä lähtenyt keskimmäiseltä esipihalta, kun hänelle tuli tämä Herran sana:'),
(1679018,58,12,20,5,'"Palaja takaisin ja sano Hiskialle, minun kansani ruhtinaalle: ''Näin sanoo Herra, sinun isäsi Daavidin Jumala: Minä olen kuullut sinun rukouksesi, olen nähnyt sinun kyyneleesi. Katso, minä parannan sinut: jo kolmantena päivänä sinä menet Herran temppeliin.'),
(1679019,58,12,20,6,'Ja minä lisään sinulle ikää viisitoista vuotta. Ja minä pelastan sinut ja tämän kaupungin Assurin kuninkaan käsistä. Minä varjelen tätä kaupunkia itseni tähden ja palvelijani Daavidin tähden.''"'),
(1679020,58,12,20,7,'Ja Jesaja sanoi: "Toimittakaa tänne viikunakakkua". Niin he toivat sitä ja panivat paiseen päälle; ja hän parani.'),
(1679021,58,12,20,8,'Ja Hiskia sanoi Jesajalle: "Mikä on merkkinä siitä, että Herra on parantava minut, niin että minä kolmantena päivänä voin mennä Herran temppeliin?"'),
(1679022,58,12,20,9,'Jesaja sanoi: "Tämä on oleva sinulle merkkinä Herralta siitä, että Herra tekee, mitä hän on sanonut: varjo kulkee kymmenen astetta eteenpäin tahi siirtyy kymmenen astetta takaisin".'),
(1679023,58,12,20,10,'Hiskia sanoi: "Varjon on helppo pidetä kymmenen astetta. Ei, vaan siirtyköön varjo takaisin kymmenen astetta."'),
(1679024,58,12,20,11,'Silloin profeetta Jesaja huusi Herraa, ja hän antoi varjon Aahaan aurinkokellossa siirtyä takaisin kymmenen astetta, jotka se oli jo laskeutunut.'),
(1679025,58,12,20,12,'Siihen aikaan Merodak-Baladan, Baladanin poika, Baabelin kuningas, lähetti kirjeen ja lahjoja Hiskialle, sillä hän oli kuullut, että Hiskia oli ollut sairaana.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679026,58,12,20,13,'Ja kuultuansa heitä Hiskia näytti heille koko varastohuoneensa, hopean ja kullan, hajuaineet ja kalliin öljyn ja koko asehuoneensa ja kaikki, mitä hänen aarrekammioissansa oli. Ei ollut mitään Hiskian talossa eikä koko hänen valtakunnassaan, mitä hän ei olisi heille näyttänyt.'),
(1679027,58,12,20,14,'Mutta profeetta Jesaja tuli kuningas Hiskian tykö ja sanoi hänelle: "Mitä nämä miehet ovat sanoneet, ja mistä he ovat tulleet sinun tykösi?" Hiskia vastasi: "He ovat tulleet kaukaisesta maasta, Baabelista".'),
(1679028,58,12,20,15,'Hän sanoi: "Mitä he ovat nähneet sinun talossasi?" Hiskia vastasi: "Kaiken, mitä talossani on, he ovat nähneet; minun aarrekammioissani ei ole mitään, mitä en olisi heille näyttänyt".'),
(1679029,58,12,20,16,'Niin Jesaja sanoi Hiskialle: "Kuule Herran sana:'),
(1679030,58,12,20,17,'Katso, päivät tulevat, jolloin kaikki, mitä sinun talossasi on ja mitä sinun isäsi ovat koonneet tähän päivään asti, viedään pois Baabeliin; ei mitään jää jäljelle, sanoo Herra.'),
(1679031,58,12,20,18,'Ja sinun omia poikiasi, jotka sinusta polveutuvat, jotka sinulle syntyvät, viedään hovipalvelijoiksi Baabelin kuninkaan palatsiin."'),
(1679032,58,12,20,19,'Hiskia sanoi Jesajalle: "Herran sana, jonka olet puhunut, on hyvä". Sillä hän ajatteli: "Onpahan rauha ja turvallisuus minun päivinäni".'),
(1679033,58,12,20,20,'Mitä muuta on kerrottavaa Hiskiasta ja kaikista hänen urotöistään, ja kuinka hän rakensi lammikon ja vesijohdon ja johti veden kaupunkiin, se on kirjoitettuna Juudan kuningasten aikakirjassa.'),
(1679034,58,12,20,21,'Ja Hiskia meni lepoon isiensä tykö. Ja hänen poikansa Manasse tuli kuninkaaksi hänen sijaansa.'),
(1679035,58,12,21,1,'Manasse oli kahdentoista vuoden vanha tullessansa kuninkaaksi, ja hän hallitsi Jerusalemissa viisikymmentä viisi vuotta. Hänen äitinsä oli nimeltään Hefsibah.'),
(1679036,58,12,21,2,'Hän teki sitä, mikä on pahaa Herran silmissä, niiden kansain kauhistavien tekojen mukaan, jotka Herra oli karkoittanut israelilaisten tieltä.'),
(1679037,58,12,21,3,'Hän rakensi jälleen uhrikukkulat, jotka hänen isänsä Hiskia oli hävittänyt, ja pystytti alttareja Baalille ja teki aseran, niinkuin Israelin kuningas Ahab oli tehnyt, kumarsi ja palveli kaikkea taivaan joukkoa.'),
(1679038,58,12,21,4,'Hän rakensi alttareja myös Herran temppeliin, josta paikasta Herra oli sanonut: "Jerusalemiin minä asetan nimeni".'),
(1679039,58,12,21,5,'Hän rakensi alttareja kaikelle taivaan joukolle Herran temppelin molempiin esipihoihin.'),
(1679040,58,12,21,6,'Myös pani hän poikansa kulkemaan tulen läpi, ennusteli merkeistä, harjoitti noituutta ja hankki itsellensä vainaja- ja tietäjähenkien manaajia; hän teki paljon sitä, mikä on pahaa Herran silmissä, ja vihoitti hänet.'),
(1679041,58,12,21,7,'Ja teettämänsä Aseran kuvan hän asetti temppeliin, josta Herra oli sanonut Daavidille ja hänen pojallensa Salomolle: "Tähän temppeliin ja Jerusalemiin, jonka minä olen valinnut kaikista Israelin sukukunnista, minä asetan nimeni ikiajoiksi.'),
(1679042,58,12,21,8,'Enkä minä anna enää Israelin jalkojen harhailla pois siitä maasta, jonka minä olen antanut heidän isillensä, jos he vain kaikessa noudattavat sitä, mitä minä olen käskenyt heidän noudattaa - koko sitä lakia, jonka minun palvelijani Mooses on heille antanut."'),
(1679043,58,12,21,9,'Mutta he eivät totelleet, ja Manasse eksytti heidät tekemään pahaa enemmän kuin ne kansat, jotka Herra oli hävittänyt israelilaisten tieltä.'),
(1679044,58,12,21,10,'Niin Herra puhui palvelijainsa, profeettain, kautta ja sanoi:'),
(1679045,58,12,21,11,'"Koska Manasse, Juudan kuningas, on tehnyt nämä kauhistavat teot ja siten tehnyt pahaa enemmän kuin amorilaiset, jotka olivat ennen häntä, ja on saattanut kivijumalillansa myös Juudan tekemään syntiä,'),
(1679046,58,12,21,12,'sentähden sanoo Herra, Israelin Jumala, näin: Katso, minä annan sellaisen onnettomuuden kohdata Jerusalemia ja Juudaa, että joka sen kuulee, sen molemmat korvat soivat.'),
(1679047,58,12,21,13,'Ja minä mittaan Jerusalemin samalla mittanuoralla kuin Samarian ja punnitsen sen samalla vaa''alla kuin Ahabin suvun. Ja minä huuhdon Jerusalemin, niinkuin vati huuhdotaan: se huuhdotaan ja käännetään kumollensa.'),
(1679048,58,12,21,14,'Minä hylkään perintöosani jäännöksen ja annan heidät vihollistensa käsiin, niin että he joutuvat kaikkien vihollistensa saaliiksi ja ryöstettäviksi,'),
(1679049,58,12,21,15,'koska ovat tehneet sitä, mikä on pahaa minun silmissäni, ja vihoittaneet minua siitä päivästä asti, jona heidän isänsä lähtivät Egyptin maasta, tähän päivään saakka."'),
(1679050,58,12,21,16,'Manasse vuodatti myös sangen paljon viatonta verta, niin että hän sillä täytti Jerusalemin ääriään myöten, sen syntinsä lisäksi, jolla hän saattoi Juudan tekemään syntiä, tekemään sitä, mikä on pahaa Herran silmissä.'),
(1679051,58,12,21,17,'Mitä muuta on kerrottavaa Manassesta ja kaikesta, mitä hän teki, ja synnistä, minkä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.'),
(1679052,58,12,21,18,'Ja Manasse meni lepoon isiensä tykö, ja hänet haudattiin linnansa puutarhaan, Ussan puutarhaan. Ja hänen poikansa Aamon tuli kuninkaaksi hänen sijaansa.'),
(1679053,58,12,21,19,'Aamon oli kahdenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kaksi vuotta. Hänen äitinsä oli nimeltään Mesullemet, Haaruksen tytär, Jotbasta.'),
(1679054,58,12,21,20,'Hän teki sitä, mikä on pahaa Herran silmissä, niinkuin hänen isänsä Manasse oli tehnyt.'),
(1679055,58,12,21,21,'Hän vaelsi kaikessa samaa tietä, mitä hänen isänsä oli vaeltanut: hän palveli niitä kivijumalia, joita hänen isänsä oli palvellut, ja kumarsi niitä;'),
(1679056,58,12,21,22,'hän hylkäsi Herran, isiensä Jumalan, eikä vaeltanut Herran tietä.'),
(1679057,58,12,21,23,'Ja Aamonin palvelijat tekivät salaliiton häntä vastaan ja tappoivat kuninkaan hänen linnassansa.'),
(1679058,58,12,21,24,'Mutta maan kansa surmasi kaikki, jotka olivat tehneet salaliiton kuningas Aamonia vastaan. Ja maan kansa teki hänen poikansa Joosian kuninkaaksi hänen sijaansa.'),
(1679059,58,12,21,25,'Mitä muuta on kerrottavaa Aamonista, siitä, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.'),
(1679060,58,12,21,26,'Ja hänet haudattiin omaan hautaansa Ussan puutarhaan. Ja hänen poikansa Joosia tuli kuninkaaksi hänen sijaansa.'),
(1679061,58,12,22,1,'Joosia oli kahdeksan vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kolmekymmentä yksi vuotta. Hänen äitinsä oli nimeltään Jedida, Adajan tytär, Boskatista.'),
(1679062,58,12,22,2,'Hän teki sitä, mikä on oikein Herran silmissä, ja vaelsi kaikessa isänsä Daavidin tietä, poikkeamatta oikealle tai vasemmalle.'),
(1679063,58,12,22,3,'Kahdeksantenatoista hallitusvuotenaan kuningas Joosia lähetti kirjuri Saafanin, Asaljan pojan, Mesullamin pojanpojan, Herran temppeliin ja sanoi:'),
(1679064,58,12,22,4,'"Mene ylimmäisen papin Hilkian luo, että hän lukisi valmiiksi Herran temppeliin tuodut rahat, joita ovenvartijat ovat koonneet kansalta.'),
(1679065,58,12,22,5,'Ja hän antakoon ne työnteettäjille, jotka on pantu valvomaan töitä Herran temppelissä, ja nämä maksakoot niillä työmiehet, jotka ovat Herran temppelissä korjaamassa sitä, mikä temppelissä on rappeutunutta,'),
(1679066,58,12,22,6,'puusepät, rakentajat ja muurarit, sekä temppelin korjaamista varten ostettavat puutavarat ja hakatut kivet.'),
(1679067,58,12,22,7,'Älköön heiltä kuitenkaan vaadittako tilintekoa rahoista, jotka heille luovutetaan, vaan toimikoot he luottamusmiehinä."'),
(1679068,58,12,22,8,'Ja ylimmäinen pappi Hilkia sanoi kirjuri Saafanille: "Minä löysin Herran temppelistä lain kirjan". Ja Hilkia antoi kirjan Saafanille, ja tämä luki sen.'),
(1679069,58,12,22,9,'Sitten kirjuri Saafan meni kuninkaan tykö ja teki kuninkaalle selon asiasta, sanoen: "Palvelijasi ovat ottaneet esille rahat, mitä temppelissä oli, ja ovat antaneet ne työnteettäjille, jotka on pantu valvomaan töitä Herran temppelissä".'),
(1679070,58,12,22,10,'Ja kirjuri Saafan kertoi kuninkaalle sanoen: "Pappi Hilkia antoi minulle erään kirjan". Ja Saafan luki sen kuninkaalle.'),
(1679071,58,12,22,11,'Kun kuningas kuuli lain kirjan sanat, repäisi hän vaatteensa.'),
(1679072,58,12,22,12,'Ja kuningas käski pappi Hilkiaa, Ahikamia, Saafanin poikaa, Akboria, Miikajan poikaa, kirjuri Saafania ja Asajaa, kuninkaan palvelijaa, sanoen:'),
(1679073,58,12,22,13,'"Menkää ja kysykää minun ja kansan ja koko Juudan puolesta neuvoa Herralta tästä löydetystä kirjasta. Sillä suuri on Herran viha, joka on syttynyt meitä vastaan, koska meidän isämme eivät ole totelleet tämän kirjan sanoja eivätkä tehneet mitään kaikesta siitä, mitä siinä on meille kirjoitettuna."'),
(1679074,58,12,22,14,'Niin pappi Hilkia, Ahikam, Akbor, Saafan ja Asaja menivät naisprofeetta Huldan tykö, joka oli vaatevaraston hoitajan Sallumin, Tikvan pojan, Harhaan pojanpojan, vaimo ja asui Jerusalemissa, toisessa kaupunginosassa. He puhuivat hänen kanssaan.'),
(1679075,58,12,22,15,'Niin hän sanoi heille: "Näin sanoo Herra, Israelin Jumala: Sanokaa sille miehelle, joka lähetti teidät minun tyköni:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679076,58,12,22,16,'''Näin sanoo Herra: Katso, minä annan tätä paikkaa ja sen asukkaita kohdata onnettomuuden, kaiken, mitä sanotaan siinä kirjassa, jonka Juudan kuningas on lukenut,'),
(1679077,58,12,22,17,'sillä he ovat hyljänneet minut ja polttaneet uhreja muille jumalille ja vihoittaneet minut kaikilla kättensä teoilla; ja minussa on syttynyt viha tätä paikkaa kohtaan, eikä se sammu.'),
(1679078,58,12,22,18,'Mutta Juudan kuninkaalle, joka on lähettänyt teidät kysymään neuvoa Herralta, sanokaa näin: Näin sanoo Herra, Israelin Jumala, niistä sanoista, jotka sinä olet kuullut:'),
(1679079,58,12,22,19,'Koska sinun sydämesi on pehminnyt ja sinä olet nöyrtynyt Herran edessä, kuullessasi, mitä minä olen puhunut tätä paikkaa ja sen asukkaita vastaan, että he tulevat kauhistukseksi ja kiroussanaksi, ja koska sinä olet reväissyt vaatteesi ja itkenyt minun edessäni, niin minäkin olen kuullut sinua, sanoo Herra.'),
(1679080,58,12,22,20,'Sentähden minä korjaan sinut isiesi tykö, ja sinä saat rauhassa siirtyä hautaasi, ja sinun silmäsi pääsevät näkemästä kaikkea sitä onnettomuutta, minkä minä annan kohdata tätä paikkaa.''" Ja he toivat kuninkaalle tämän vastauksen.'),
(1679081,58,12,23,1,'Niin kuningas lähetti kokoamaan luoksensa kaikki Juudan ja Jerusalemin vanhimmat.'),
(1679082,58,12,23,2,'Ja kuningas meni Herran temppeliin, ja hänen kanssaan kaikki Juudan miehet ja kaikki Jerusalemin asukkaat, myöskin papit ja profeetat, koko kansa pienimmästä suurimpaan. Ja hän luki heidän kuultensa kaikki Herran temppelistä löydetyn liitonkirjan sanat.'),
(1679083,58,12,23,3,'Ja kuningas asettui pylvään viereen ja teki Herran edessä liiton, että heidän tuli seurata Herraa, noudattaa hänen käskyjänsä, todistuksiansa ja säädöksiänsä kaikesta sydämestään ja kaikesta sielustaan ja pitää liiton sanat, jotka olivat kirjoitettuina siinä kirjassa. Ja kaikki kansa yhtyi siihen liittoon.'),
(1679084,58,12,23,4,'Sitten kuningas käski ylimmäistä pappia Hilkiaa ja häntä lähimpiä pappeja sekä ovenvartijoita viemään Herran temppelistä pois kaikki kalut, mitä oli tehty Baalille, Aseralle ja kaikelle taivaan joukolle. Ja hän poltatti ne Jerusalemin ulkopuolella Kidronin kedoilla, mutta vei niiden tuhan Beeteliin.'),
(1679085,58,12,23,5,'Hän pani myös viralta epäjumalain papit, jotka Juudan kuninkaat olivat asettaneet polttamaan uhreja uhrikukkuloilla Juudan kaupungeissa ja Jerusalemin ympäristössä ja jotka polttivat uhreja Baalille, auringolle, kuulle, eläinradan tähdille ja kaikelle taivaan joukolle.'),
(1679086,58,12,23,6,'Hän vei aseran pois Herran temppelistä Jerusalemin ulkopuolelle Kidronin laaksoon ja poltti sen Kidronin laaksossa, rouhensi sen tomuksi ja heitti tomun yhteiselle hautausmaalle.'),
(1679087,58,12,23,7,'Ja hän kukisti haureellisten pyhäkköpoikien huoneet, jotka olivat Herran temppelissä ja joissa naiset kutoivat verhoja Aseralle.'),
(1679088,58,12,23,8,'Hän toi pois kaikki papit Juudan kaupungeista ja saastutti uhrikukkulat, joilla papit olivat polttaneet uhreja, Gebasta Beersebaan asti. Ja hän kukisti porteilla olevat uhrikukkulat, joita oli kaupungin päällikön Joosuan portin oven edustalla, vasemmalla puolella mentäessä sisään kaupungin portista.'),
(1679089,58,12,23,9,'Uhrikukkulapapit eivät kuitenkaan saaneet nousta Herran alttarille Jerusalemissa; he saivat vain syödä happamatonta leipää veljiensä kanssa.'),
(1679090,58,12,23,10,'Hän saastutti myöskin polttopaikan Ben-Hinnomin laaksossa, ettei kukaan voisi panna poikaansa tai tytärtänsä kulkemaan tulen läpi Molokin kunniaksi.'),
(1679091,58,12,23,11,'Ja hän poisti ne hevoset, jotka Juudan kuninkaat olivat auringon kunniaksi asettaneet, siitä, mistä mennään Herran temppeliin, hoviherra Netan-Melekin kammion vierestä, joka oli Parvarimissa, ja poltti auringonvaunut tulessa.'),
(1679092,58,12,23,12,'Ja Aahaan yläsalin katolla olevat alttarit, jotka Juudan kuninkaat olivat teettäneet, ja ne alttarit, jotka Manasse oli teettänyt Herran temppelin molempiin esipihoihin, kuningas kukisti; sitten hän riensi sieltä ja heitti niiden tomun Kidronin laaksoon.'),
(1679093,58,12,23,13,'Ja ne uhrikukkulat, jotka olivat itään päin Jerusalemista, etelään päin Turmiovuoresta, ja jotka Salomo, Israelin kuningas, oli rakentanut Astartelle, siidonilais-iljetykselle, ja Kemokselle, Mooabin iljetykselle, ja Milkomille, ammonilais-kauhistukselle, ne kuningas saastutti.'),
(1679094,58,12,23,14,'Hän murskasi patsaat ja hakkasi maahan asera-karsikot ja täytti niiden sijan ihmisten luilla.'),
(1679095,58,12,23,15,'Myöskin Beetelissä olevan alttarin, sen uhrikukkulan, jonka oli teettänyt Jerobeam, Nebatin poika, joka saattoi Israelin tekemään syntiä, senkin alttarin uhrikukkuloineen hän kukisti; sitten hän poltti uhrikukkulan ja rouhensi sen tomuksi sekä poltti asera-karsikon.'),
(1679096,58,12,23,16,'Kun Joosia sitten kääntyi ja näki haudat, jotka olivat vuorella, lähetti hän ottamaan luut haudoista, poltti ne alttarilla ja saastutti näin alttarin, Herran sanan mukaan, jonka oli julistanut se Jumalan mies, joka nämä julisti.'),
(1679097,58,12,23,17,'Ja hän kysyi: "Mikä tuo hautamerkki on, jonka minä näen?" Kaupungin miehet vastasivat hänelle: "Se on sen Jumalan miehen hauta, joka tuli Juudasta ja julisti sen, minkä sinä nyt olet tehnyt Beetelin alttarille".'),
(1679098,58,12,23,18,'Hän sanoi: "Antakaa hänen olla; älköön kukaan koskeko hänen luihinsa". Niin he jättivät hänen luunsa rauhaan ja samoin sen profeetan luut, joka oli tullut Samariasta.'),
(1679099,58,12,23,19,'Myöskin Samarian kaupungeista Joosia poisti kaikki uhrikukkulatemppelit, jotka Israelin kuninkaat olivat rakentaneet ja niin vihoittaneet Herran; ja hän teki niille saman, minkä oli tehnyt Beetelissä.'),
(1679100,58,12,23,20,'Ja kaikki siellä olevat uhrikukkulapapit hän teurasti alttareilla ja poltti ihmisten luita niiden päällä. Sitten hän palasi takaisin Jerusalemiin.'),
(1679101,58,12,23,21,'Ja kuningas käski kaikkea kansaa sanoen: "Viettäkää pääsiäistä Herran, teidän Jumalanne, kunniaksi, niinkuin on kirjoitettuna tässä liitonkirjassa".'),
(1679102,58,12,23,22,'Sillä sellaista pääsiäistä ei oltu vietetty sen ajan jälkeen, jona tuomarit tuomitsivat Israelia, ei Israelin kuningasten eikä Juudan kuningasten koko aikana.'),
(1679103,58,12,23,23,'Vasta kuningas Joosian kahdeksantenatoista hallitusvuotena vietettiin sellainen pääsiäinen Jerusalemissa Herran kunniaksi.'),
(1679104,58,12,23,24,'Myöskin vainaja- ja tietäjähenkien manaajat, kotijumalat ja kivijumalat ja kaikki iljetykset, joita oli nähty Juudan maassa ja Jerusalemissa, Joosia hävitti, täyttääkseen lain sanat, jotka olivat kirjoitettuina siinä kirjassa, minkä pappi Hilkia oli löytänyt Herran temppelistä.'),
(1679105,58,12,23,25,'Ei ollut ennen häntä ollut hänen vertaistansa kuningasta, joka niin kaikesta sydämestänsä, kaikesta sielustansa ja kaikesta voimastansa olisi kääntynyt Herran puoleen, kaiken Mooseksen lain mukaan; eikä hänen jälkeensä tullut hänen vertaistansa.'),
(1679106,58,12,23,26,'Kuitenkaan ei Herra kääntynyt suuren vihansa hehkusta, kun kerran hänen vihansa oli syttynyt Juudaa vastaan kaikesta siitä, millä Manasse oli vihoittanut hänet.'),
(1679107,58,12,23,27,'Ja Herra sanoi: "Minä toimitan myöskin Juudan pois kasvojeni edestä, niinkuin minä olen toimittanut pois Israelin; ja minä hylkään Jerusalemin, tämän kaupungin, jonka minä olin valinnut, ja temppelin, josta minä olin sanonut: ''Minun nimeni on oleva siinä''".'),
(1679108,58,12,23,28,'Mitä muuta on kerrottavaa Joosiasta ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.'),
(1679109,58,12,23,29,'Hänen aikanansa farao Neko, Egyptin kuningas, lähti Assurin kuningasta vastaan Eufrat-virralle. Niin kuningas Joosia meni häntä vastaan, mutta farao surmasi hänet Megiddossa heti, kun näki hänet.'),
(1679110,58,12,23,30,'Ja hänen palvelijansa veivät hänet kuolleena vaunuissa Megiddosta, toivat hänet Jerusalemiin ja hautasivat hänet hänen omaan hautaansa. Mutta maan kansa otti Joosian pojan Jooahaan, voiteli hänet ja teki hänet kuninkaaksi hänen isänsä sijaan.'),
(1679111,58,12,23,31,'Jooahas oli kahdenkymmenen kolmen vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi kolme kuukautta Jerusalemissa. Hänen äitinsä oli nimeltään Hamutal, Jeremian tytär, Libnasta.'),
(1679112,58,12,23,32,'Ja hän teki sitä, mikä on pahaa Herran silmissä, aivan niinkuin hänen isänsä olivat tehneet.'),
(1679113,58,12,23,33,'Mutta farao Neko vangitutti hänet Riblassa, Hamatin maassa, ettei hän hallitsisi Jerusalemissa, ja määräsi maan maksettavaksi pakkoveron: sata talenttia hopeata ja kymmenen talenttia kultaa.'),
(1679114,58,12,23,34,'Ja farao Neko teki Eljakimin, Joosian pojan, kuninkaaksi hänen isänsä Joosian sijaan ja muutti hänen nimensä Joojakimiksi. Mutta Jooahaan hän otti vangiksi, ja tämä joutui Egyptiin; siellä hän kuoli.'),
(1679115,58,12,23,35,'Hopean ja kullan Joojakim maksoi faraolle; mutta voidakseen maksaa rahat faraon käskyn mukaan hän veroitti maata, ottaen maan kansalta, sen mukaan kuin kukin oli verotettu, hopeata ja kultaa, antaakseen farao Nekolle.'),
(1679116,58,12,23,36,'Joojakim oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa yksitoista vuotta. Hänen äitinsä oli nimeltään Sebida, Pedajan tytär, Ruumasta.'),
(1679117,58,12,23,37,'Hän teki sitä, mikä on pahaa Herran silmissä, aivan niinkuin hänen isänsä olivat tehneet.'),
(1679118,58,12,24,1,'Hänen aikanaan Nebukadnessar, Baabelin kuningas, lähti liikkeelle, ja Joojakim tuli hänen palvelijakseen. Kolmen vuoden kuluttua tämä jälleen kapinoi häntä vastaan.'),
(1679119,58,12,24,2,'Ja Herra lähetti hänen kimppuunsa kaldealaisten, aramilaisten, mooabilaisten ja ammonilaisten partiojoukkoja; hän lähetti ne Juudan kimppuun sitä tuhoamaan, Herran sanan mukaan, jonka hän oli puhunut palvelijainsa, profeettain, kautta.'),
(1679120,58,12,24,3,'Mutta tämä tapahtui Juudalle Herran käskystä; ja näin hän toimitti heidät pois kasvojensa edestä Manassen syntien tähden, kaiken tähden, mitä hän oli tehnyt,'),
(1679121,58,12,24,4,'ja myöskin viattoman veren tähden, minkä hän oli vuodattanut täyttäessään Jerusalemin viattomalla verellä; sitä ei Herra tahtonut antaa anteeksi.'),
(1679122,58,12,24,5,'Mitä muuta on kerrottavaa Joojakimista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.'),
(1679123,58,12,24,6,'Ja Joojakim meni lepoon isiensä tykö. Ja hänen poikansa Joojakin tuli kuninkaaksi hänen sijaansa.'),
(1679124,58,12,24,7,'Egyptin kuningas ei enää lähtenyt maastansa, sillä Baabelin kuningas oli vallannut kaiken, mikä oli Egyptin kuninkaan omaa, Egyptin purosta aina Eufrat-virtaan saakka.'),
(1679125,58,12,24,8,'Joojakin oli kahdeksantoista vuoden vanha tullessansa kuninkaaksi, ja hän hallitsi Jerusalemissa kolme kuukautta. Hänen äitinsä oli nimeltään Nehusta, Elnatanin tytär, Jerusalemista.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679126,58,12,24,9,'Hän teki sitä, mikä on pahaa Herran silmissä, aivan niinkuin hänen isänsä oli tehnyt.'),
(1679127,58,12,24,10,'Siihen aikaan Baabelin kuninkaan Nebukadnessarin palvelijat tulivat Jerusalemiin, ja kaupunki saarrettiin.'),
(1679128,58,12,24,11,'Ja Nebukadnessar, Baabelin kuningas, ryntäsi kaupunkiin, hänen palvelijainsa saartaessa sitä.'),
(1679129,58,12,24,12,'Niin Joojakin, Juudan kuningas, antautui Baabelin kuninkaalle äitineen ja palvelijoineen, päällikköineen ja hoviherroineen. Ja Baabelin kuningas otti hänet vangiksi kahdeksantena hallitusvuotenaan.'),
(1679130,58,12,24,13,'Ja hän vei pois sieltä kaikki Herran temppelin ja kuninkaan linnan aarteet, ja hän rikkoi kaikki kultakalut, jotka Israelin kuningas Salomo oli teettänyt Herran temppeliin. Tapahtui, niinkuin Herra oli puhunut.'),
(1679131,58,12,24,14,'Ja hän vei pakkosiirtolaisuuteen koko Jerusalemin, kaikki päälliköt ja kaikki sotaurhot, kymmenentuhatta pakkosiirtolaista, ja kaikki sepät ja lukkosepät; ei jäänyt jäljelle muita kuin maakansan köyhät.'),
(1679132,58,12,24,15,'Hän siirsi Joojakinin vankina Baabeliin; samoin hän vei kuninkaan äidin, kuninkaan puolisot ja hänen hoviherransa sekä muut maan mahtavat pakkosiirtolaisina Jerusalemista Baabeliin,'),
(1679133,58,12,24,16,'niin myös kaikki sotilaat, luvultaan seitsemäntuhatta, sepät ja lukkosepät, luvultaan tuhat, kaikki sotaan harjaantuneita urhoja. Ne Baabelin kuningas vei pakkosiirtolaisina Baabeliin.'),
(1679134,58,12,24,17,'Mutta Baabelin kuningas asetti hänen setänsä Mattanjan kuninkaaksi hänen sijaansa ja muutti hänen nimensä Sidkiaksi.'),
(1679135,58,12,24,18,'Sidkia oli kahdenkymmenen yhden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa yksitoista vuotta. Hänen äitinsä oli nimeltään Hamutal, Jeremian tytär, Libnasta.'),
(1679136,58,12,24,19,'Hän teki sitä, mikä on pahaa Herran silmissä, aivan samoin kuin Joojakim oli tehnyt.'),
(1679137,58,12,24,20,'Sillä Herran vihan tähden kävi näin Jerusalemille ja Juudalle, kunnes hän vihdoin heitti heidät pois kasvojensa edestä.'),
(1679138,58,12,25,1,'Sidkia kapinoi Baabelin kuningasta vastaan. Hänen yhdeksäntenä hallitusvuotenaan, sen kymmenennessä kuussa, kuukauden kymmenentenä päivänä, kävi Nebukadnessar, Baabelin kuningas, hän ja koko hänen sotajoukkonsa, Jerusalemin kimppuun ja asettui leiriin sitä vastaan. Ja he rakensivat saartovarusteet sitä vastaan yltympäri.'),
(1679139,58,12,25,2,'Näin kaupunkia piiritettiin kuningas Sidkian yhdenteentoista hallitusvuoteen asti.'),
(1679140,58,12,25,3,'Mutta neljännen kuukauden yhdeksäntenä päivänä, kun nälänhätä ahdisti kaupunkia eikä ollut leipää maan kansalle,'),
(1679141,58,12,25,4,'valloitettiin kaupunki, ja kaikki sotilaat pakenivat yöllä molempien muurien välistä porttitietä, joka oli kuninkaan puutarhan puolella, kaldealaisten ollessa kaupungin ympärillä, ja he kulkivat Aromaahan päin.'),
(1679142,58,12,25,5,'Mutta kaldealaisten sotajoukko ajoi kuningasta takaa, ja he saavuttivat hänet Jerikon aroilla; ja kaikki hänen sotaväkensä oli jättänyt hänet ja hajaantunut.'),
(1679143,58,12,25,6,'Ja he ottivat kuninkaan kiinni ja veivät hänet Baabelin kuninkaan eteen Riblaan; ja hänelle julistettiin tuomio:'),
(1679144,58,12,25,7,'Sidkian pojat teurastettiin hänen silmiensä edessä, ja Sidkialta itseltään hän sokaisutti silmät ja kytketti hänet vaskikahleisiin, ja hänet vietiin Baabeliin.'),
(1679145,58,12,25,8,'Viidennessä kuussa, kuukauden seitsemäntenä päivänä, Baabelin kuninkaan Nebukadnessarin yhdeksäntenätoista hallitusvuotena, tuli Baabelin kuninkaan palvelija Nebusaradan, henkivartijain päällikkö, Jerusalemiin.'),
(1679146,58,12,25,9,'Hän poltti Herran temppelin ja kuninkaan linnan ja kaikki Jerusalemin talot; kaikki ylhäisten talot hän poltti tulella.'),
(1679147,58,12,25,10,'Ja koko kaldealaisten sotajoukko, joka henkivartijain päälliköllä oli mukanaan, repi maahan Jerusalemin muurit, yltympäri.'),
(1679148,58,12,25,11,'Ja Nebusaradan, henkivartijain päällikkö, vei pakkosiirtolaisuuteen kansan tähteet, mitä oli jäljellä kaupungissa, sekä ne, jotka olivat menneet Baabelin kuninkaan puolelle, ja muun rahvaan.'),
(1679149,58,12,25,12,'Mutta osan maan köyhiä henkivartijain päällikkö jätti jäljelle viinitarhureiksi ja peltomiehiksi.'),
(1679150,58,12,25,13,'Vaskipylväät, jotka olivat Herran temppelissä, altaiden telineet ja vaskimeren, jotka olivat Herran temppelissä, kaldealaiset särkivät ja veivät vasken Baabeliin.'),
(1679151,58,12,25,14,'Ja kattilat, lapiot, veitset, kupit ja kaikki vaskikalut, joita oli käytetty jumalanpalveluksessa, he ottivat pois.'),
(1679152,58,12,25,15,'Samoin otti henkivartijain päällikkö hiilipannut ja maljat, jotka olivat läpeensä kultaa tai hopeata.'),
(1679153,58,12,25,16,'Molempien pylväiden, meren ja telineiden, jotka Salomo oli teettänyt Herran temppeliin - näiden kaikkien esineiden vaski ei ollut punnittavissa.'),
(1679154,58,12,25,17,'Toisen pylvään korkeus oli kahdeksantoista kyynärää, ja sen päässä oli pylväänpää vaskesta; pylväänpään korkeus oli kolme kyynärää, ja pylväänpään päällä oli ristikkokoriste ja granaattiomenia yltympäri, kaikki vaskea; ja samanlaiset oli toisessa pylväässä ristikkokoristeen päällä.'),
(1679155,58,12,25,18,'Henkivartijain päällikkö otti ylimmäisen papin Serajan ja häntä lähimmän papin Sefanjan sekä kolme ovenvartijaa,'),
(1679156,58,12,25,19,'ja kaupungista hän otti yhden hoviherran, joka oli sotaväen tarkastaja, ja viisi kuninkaan lähintä miestä, jotka tavattiin kaupungista, sekä sotapäällikön kirjurin, jonka tehtävänä oli ottaa maan kansaa sotapalvelukseen, ja kuusikymmentä miestä maan kansasta, jotka tavattiin kaupungista.'),
(1679157,58,12,25,20,'Nämä otti Nebusaradan, henkivartijain päällikkö, ja vei heidät Baabelin kuninkaan eteen Riblaan.'),
(1679158,58,12,25,21,'Ja Baabelin kuningas antoi lyödä heidät kuoliaaksi Riblassa Hamatin maassa. Ja niin Juuda vietiin pois maastansa pakkosiirtolaisuuteen.'),
(1679159,58,12,25,22,'Mutta sen väen käskynhaltijaksi, joka jäi Juudan maahan, sen, jonka Nebukadnessar, Baabelin kuningas, jätti sinne, hän asetti Gedaljan, Ahikamin pojan, Saafanin pojanpojan.'),
(1679160,58,12,25,23,'Kun kaikki sotaväen päälliköt, he ja heidän miehensä, kuulivat, että Baabelin kuningas oli asettanut Gedaljan käskynhaltijaksi, tulivat he miehinensä Gedaljan luo Mispaan, nimittäin Ismael, Netanjan poika, Joohanan, Kaareahin poika, netofalainen Seraja, Tanhumetin poika, ja Jaasanja, maakatilaisen poika.'),
(1679161,58,12,25,24,'Ja Gedalja vannoi heille ja heidän miehillensä ja sanoi heille: "Älkää peljätkö kaldealaisten palvelijoita. Jääkää maahan ja palvelkaa Baabelin kuningasta, niin te menestytte."'),
(1679162,58,12,25,25,'Mutta seitsemännessä kuussa tuli Ismael, Netanjan poika, Elisaman pojanpoika, joka oli kuninkaallista sukua, mukanaan kymmenen miestä, ja he löivät kuoliaaksi Gedaljan ja ne Juudan miehet ja kaldealaiset, jotka olivat hänen kanssansa Mispassa.'),
(1679163,58,12,25,26,'Silloin nousi kaikki kansa, pienimmästä suurimpaan, ja samoin sotaväen päälliköt, ja he menivät Egyptiin, sillä he pelkäsivät kaldealaisia.'),
(1679164,58,12,25,27,'Mutta kolmantenakymmenentenä seitsemäntenä vuotena siitä, kun Joojakin, Juudan kuningas, oli viety pakkosiirtolaisuuteen, kahdennessatoista kuussa, kuukauden kahdentenakymmenentenä seitsemäntenä päivänä, korotti Evil-Merodak, Baabelin kuningas, samana vuonna, jona hän tuli kuninkaaksi, Juudan kuninkaan Joojakinin pään, vapauttaen hänet vankilasta.'),
(1679165,58,12,25,28,'Ja hän puhutteli häntä ystävällisesti ja asetti hänen istuimensa ylemmäksi muitten kuningasten istuimia, jotka olivat hänen tykönänsä Baabelissa.'),
(1679166,58,12,25,29,'Hän sai panna pois vangin puvun ja aina aterioida hänen luonaan, niin kauan kuin eli.'),
(1679167,58,13,1,1,'Aadam, Seet, Enos,'),
(1679168,58,13,1,2,'Keenan, Mahalalel, Jered,'),
(1679169,58,13,1,3,'Hanok, Metusalah, Lemek,'),
(1679170,58,13,1,4,'Nooa, Seem, Haam ja Jaafet.'),
(1679171,58,13,1,5,'Jaafetin pojat olivat Goomer, Maagog, Maadai, Jaavan, Tuubal, Mesek ja Tiiras.'),
(1679172,58,13,1,6,'Ja Goomerin pojat olivat Askenas, Diifat ja Toogarma.'),
(1679173,58,13,1,7,'Ja Jaavanin pojat olivat Elisa ja Tarsisa, kittiläiset ja roodanilaiset.'),
(1679174,58,13,1,8,'Haamin pojat olivat Kuus, Misraim, Puut ja Kanaan.'),
(1679175,58,13,1,9,'Ja Kuusin pojat olivat Seba, Havila, Sabta, Raema ja Sabteka. Ja Raeman pojat olivat Saba ja Dedan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679176,58,13,1,10,'Ja Kuusille syntyi Nimrod; hän oli ensimmäinen valtias maan päällä.'),
(1679177,58,13,1,11,'Ja Misraimille syntyivät luudilaiset, anamilaiset, lehabilaiset, naftuhilaiset,'),
(1679178,58,13,1,12,'patrokselaiset ja kasluhilaiset, joista filistealaiset ovat lähteneet, sekä kaftorilaiset.'),
(1679179,58,13,1,13,'Ja Kanaanille syntyivät Siidon, hänen esikoisensa, ja Heet,'),
(1679180,58,13,1,14,'sekä jebusilaiset, amorilaiset, girgasilaiset,'),
(1679181,58,13,1,15,'hivviläiset, arkilaiset, siiniläiset,'),
(1679182,58,13,1,16,'arvadilaiset, semarilaiset ja hamatilaiset.'),
(1679183,58,13,1,17,'Seemin pojat olivat Eelam, Assur, Arpaksad, Luud, Aram, Uus, Huul, Geter ja Mesek.'),
(1679184,58,13,1,18,'Ja Arpaksadille syntyi Selah, ja Selahille syntyi Eeber.'),
(1679185,58,13,1,19,'Ja Eeberille syntyi kaksi poikaa; toisen nimi oli Peleg, sillä hänen aikanansa jakaantuivat maan asukkaat, ja hänen veljensä nimi oli Joktan.'),
(1679186,58,13,1,20,'Ja Joktanille syntyivät Almodad, Selef, Hasarmavet, Jerah,'),
(1679187,58,13,1,21,'Hadoram, Uusal, Dikla,'),
(1679188,58,13,1,22,'Eebal, Abimael, Saba,'),
(1679189,58,13,1,23,'Oofir, Havila ja Joobab. Kaikki nämä olivat Joktanin poikia.'),
(1679190,58,13,1,24,'Seem, Arpaksad, Selah,'),
(1679191,58,13,1,25,'Eeber, Peleg, Regu,'),
(1679192,58,13,1,26,'Serug, Naahor, Terah,'),
(1679193,58,13,1,27,'Abram, se on Aabraham.'),
(1679194,58,13,1,28,'Aabrahamin pojat olivat Iisak ja Ismael.'),
(1679195,58,13,1,29,'Tämä on heidän sukuluettelonsa: Nebajot, Ismaelin esikoinen, Keedar, Adbeel, Mibsan,'),
(1679196,58,13,1,30,'Misma, Duuma, Massa, Hadad, Teema,'),
(1679197,58,13,1,31,'Jetur, Naafis ja Keedma. Nämä olivat Ismaelin pojat.'),
(1679198,58,13,1,32,'Ja Keturan, Aabrahamin sivuvaimon, pojat, jotka tämä synnytti, olivat Simran, Joksan, Medan, Midian, Jisbak ja Suuah. Joksanin pojat olivat Saba ja Dedan.'),
(1679199,58,13,1,33,'Ja Midianin pojat olivat Eefa, Eefer, Hanok, Abida ja Eldaa. Kaikki nämä olivat Keturan jälkeläisiä.'),
(1679200,58,13,1,34,'Ja Aabrahamille syntyi Iisak. Iisakin pojat olivat Eesau ja Israel.'),
(1679201,58,13,1,35,'Eesaun pojat olivat Elifas, Reguel, Jeus, Jaelam ja Koorah.'),
(1679202,58,13,1,36,'Elifaan pojat olivat Teeman, Oomar, Sefi, Gaetam, Kenas, Timna ja Amalek.'),
(1679203,58,13,1,37,'Reguelin pojat olivat Nahat, Serah, Samma ja Missa.'),
(1679204,58,13,1,38,'Seirin pojat olivat Lootan, Soobal, Sibon, Ana, Diison, Eeser ja Diisan.'),
(1679205,58,13,1,39,'Lootanin pojat olivat Hoori ja Hoomam; ja Lootanin sisar oli Timna.'),
(1679206,58,13,1,40,'Soobalin pojat olivat Aljan, Maanahat, Eebal, Sefi ja Oonan. Ja Sibonin pojat olivat Aija ja Ana.'),
(1679207,58,13,1,41,'Anan pojat olivat Diison. Ja Diisonin pojat olivat Hamran, Esban, Jitran ja Keran.'),
(1679208,58,13,1,42,'Eeserin pojat olivat Bilhan, Saavan ja Jaakan. Diisanin pojat olivat Uus ja Aran.'),
(1679209,58,13,1,43,'Ja nämä olivat ne kuninkaat, jotka hallitsivat Edomin maassa, ennenkuin mikään kuningas oli hallinnut israelilaisia: Bela, Beorin poika; ja hänen kaupunkinsa nimi oli Dinhaba.'),
(1679210,58,13,1,44,'Ja kun Bela kuoli, tuli Joobab, Serahin poika, Bosrasta, kuninkaaksi hänen sijaansa.'),
(1679211,58,13,1,45,'Kun Joobab kuoli, tuli Huusam, teemanilaisten maasta, kuninkaaksi hänen sijaansa.'),
(1679212,58,13,1,46,'Kun Huusam kuoli, tuli Hadad, Bedadin poika, kuninkaaksi hänen sijaansa, hän, joka voitti midianilaiset Mooabin maassa; ja hänen kaupunkinsa nimi oli Avit.'),
(1679213,58,13,1,47,'Kun Hadad kuoli, tuli Samla, Masrekasta, kuninkaaksi hänen sijaansa.'),
(1679214,58,13,1,48,'Kun Samla kuoli, tuli Saul, virran rannalla olevasta Rehobotista, kuninkaaksi hänen sijaansa.'),
(1679215,58,13,1,49,'Kun Saul kuoli, tuli Baal-Haanan, Akborin poika, kuninkaaksi hänen sijaansa.'),
(1679216,58,13,1,50,'Kun Baal-Haanan kuoli, tuli Hadad kuninkaaksi hänen sijaansa, ja hänen kaupunkinsa nimi oli Paagi; ja hänen vaimonsa nimi oli Mehetabel, Matredin tytär, joka oli Mee-Saahabin tytär.'),
(1679217,58,13,1,51,'Ja Hadad kuoli; ja Edomin sukuruhtinaat olivat: ruhtinas Timna, ruhtinas Alva, ruhtinas Jetet,'),
(1679218,58,13,1,52,'ruhtinas Oholibama, ruhtinas Eela, ruhtinas Piinon,'),
(1679219,58,13,1,53,'ruhtinas Kenas, ruhtinas Teeman, ruhtinas Mibsar,'),
(1679220,58,13,1,54,'ruhtinas Magdiel, ruhtinas Iiram. Nämä olivat Edomin sukuruhtinaat.'),
(1679221,58,13,2,1,'Nämä olivat Israelin pojat: Ruuben, Simeon, Leevi ja Juuda, Isaskar ja Sebulon,'),
(1679222,58,13,2,2,'Daan, Joosef ja Benjamin, Naftali, Gaad ja Asser.'),
(1679223,58,13,2,3,'Juudan pojat olivat Eer, Oonan ja Seela; nämä kolme synnytti hänelle Suuahin tytär, kanaanilainen. Mutta Eer, Juudan esikoinen, ei ollut otollinen Herran silmissä; sentähden hän antoi hänen kuolla.'),
(1679224,58,13,2,4,'Ja Taamar, Juudan miniä, synnytti hänelle Pereksen ja Serahin. Juudan poikia oli kaikkiaan viisi.'),
(1679225,58,13,2,5,'Pereksen pojat olivat Hesron ja Haamul.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679226,58,13,2,6,'Ja Serahin pojat olivat Simri, Eetan, Heeman, Kalkol ja Daara; heitä oli kaikkiaan viisi.'),
(1679227,58,13,2,7,'Ja Karmin pojat olivat Aakar, joka syöksi Israelin onnettomuuteen, kun oli uskoton ja anasti tuhon omaksi vihittyä.'),
(1679228,58,13,2,8,'Ja Eetanin poika oli Asarja.'),
(1679229,58,13,2,9,'Ja Hesronin pojat, jotka hänelle syntyivät, olivat Jerahmeel, Raam ja Kelubai.'),
(1679230,58,13,2,10,'Ja Raamille syntyi Amminadab, ja Amminadabille syntyi Nahson, Juudan jälkeläisten ruhtinas.'),
(1679231,58,13,2,11,'Ja Nahsonille syntyi Salma, ja Salmalle syntyi Booas.'),
(1679232,58,13,2,12,'Ja Booaalle syntyi Oobed, ja Oobedille syntyi Iisai.'),
(1679233,58,13,2,13,'Ja Iisaille syntyi esikoisena Eliab, toisena Abinadab, kolmantena Simea,'),
(1679234,58,13,2,14,'neljäntenä Netanel, viidentenä Raddai,'),
(1679235,58,13,2,15,'kuudentena Oosem ja seitsemäntenä Daavid.'),
(1679236,58,13,2,16,'Ja heidän sisarensa olivat Seruja ja Abigail. Ja Serujan pojat olivat Abisai, Jooab ja Asael, kaikkiaan kolme.'),
(1679237,58,13,2,17,'Ja Abigail synnytti Amasan; ja Amasan isä oli ismaelilainen Jeter.'),
(1679238,58,13,2,18,'Ja Kaalebille, Hesronin pojalle, syntyi lapsia Asubasta, hänen vaimostaan, ja Jeriotista; ja nämä olivat Asuban pojat: Jeeser, Soobab ja Ardon.'),
(1679239,58,13,2,19,'Ja kun Asuba kuoli, nai Kaaleb Efratin, ja tämä synnytti hänelle Huurin.'),
(1679240,58,13,2,20,'Ja Huurille syntyi Uuri, ja Uurille syntyi Besalel.'),
(1679241,58,13,2,21,'Senjälkeen meni Hesron Maakirin, Gileadin isän, tyttären tykö; ja hän nai tämän ollessaan kuudenkymmenen vuoden vanha. Ja tämä synnytti hänelle Segubin.'),
(1679242,58,13,2,22,'Ja Segubille syntyi Jaair; tällä oli kaksikymmentä kolme kaupunkia Gileadin maassa.'),
(1679243,58,13,2,23,'Mutta gesurilaiset ja aramilaiset ottivat heiltä Jaairin leirikylät ja Kenatin ynnä sen tytärkaupungit, kuusikymmentä kaupunkia. Kaikki nämä olivat Maakirin, Gileadin isän, poikia.'),
(1679244,58,13,2,24,'Kun Hesron oli kuollut Kaaleb-Efratassa, synnytti Abia - hän oli Hesronin vaimo - hänelle Ashurin, Tekoan isän.'),
(1679245,58,13,2,25,'Ja Jerahmeelin, Hesronin esikoisen, pojat olivat Raam, esikoinen, ja Buuna, Ooren, Oosem ja Ahia.'),
(1679246,58,13,2,26,'Ja Jerahmeelilla oli vielä toinen vaimo, jonka nimi oli Atara; hän oli Oonamin äiti.'),
(1679247,58,13,2,27,'Ja Raamin, Jerahmeelin esikoisen, pojat olivat Maas, Jaamin ja Eeker.'),
(1679248,58,13,2,28,'Ja Oonamin pojat olivat Sammai ja Jaada; ja Sammain pojat olivat Naadab ja Abisur.'),
(1679249,58,13,2,29,'Ja Abisurin vaimon nimi oli Abihail, ja tämä synnytti hänelle Ahbanin ja Moolidin.'),
(1679250,58,13,2,30,'Ja Naadabin pojat olivat Seled ja Appaim. Ja Seled kuoli lapsetonna.'),
(1679251,58,13,2,31,'Ja Appaimin poika oli Jisi; ja Jisin poika oli Seesan; ja Seesanin poika oli Ahlai.'),
(1679252,58,13,2,32,'Ja Jaadan, Sammain veljen, pojat olivat Jeter ja Joonatan. Jeter kuoli lapsetonna.'),
(1679253,58,13,2,33,'Ja Joonatanin pojat olivat Pelet ja Saasa. Nämä olivat Jerahmeelin jälkeläisiä.'),
(1679254,58,13,2,34,'Mutta Seesanilla ei ollut poikia, vaan ainoastaan tyttäriä. Ja Seesanilla oli egyptiläinen palvelija, jonka nimi oli Jarha.'),
(1679255,58,13,2,35,'Ja Seesan antoi tyttärensä vaimoksi palvelijallensa Jarhalle, ja hän synnytti tälle Attain.'),
(1679256,58,13,2,36,'Ja Attaille syntyi Naatan, ja Naatanille syntyi Saabad.'),
(1679257,58,13,2,37,'Ja Saabadille syntyi Eflal, ja Eflalille syntyi Oobed.'),
(1679258,58,13,2,38,'Ja Oobedille syntyi Jeehu, ja Jeehulle syntyi Asarja.'),
(1679259,58,13,2,39,'Ja Asarjalle syntyi Heles, ja Helekselle syntyi Eleasa.'),
(1679260,58,13,2,40,'Ja Eleasalle syntyi Sismai, ja Sismaille syntyi Sallum.'),
(1679261,58,13,2,41,'Ja Sallumille syntyi Jekamja, ja Jekamjalle syntyi Elisama.'),
(1679262,58,13,2,42,'Ja Kaalebin, Jerahmeelin veljen, pojat olivat Meesa, hänen esikoisensa, joka oli Siifin isä, ja Maaresan, Hebronin isän, pojat.'),
(1679263,58,13,2,43,'Ja Hebronin pojat olivat Koorah, Tappuah, Rekem ja Sema.'),
(1679264,58,13,2,44,'Ja Semalle syntyi Raham, Jorkeamin isä, ja Rekemille syntyi Sammai.'),
(1679265,58,13,2,45,'Ja Sammain poika oli Maaon, ja Maaon oli Beet-Suurin isä.'),
(1679266,58,13,2,46,'Ja Eefa, Kaalebin sivuvaimo, synnytti Haaranin, Moosan ja Gaaseksen; ja Haaranille syntyi Gaases.'),
(1679267,58,13,2,47,'Ja Jahdain pojat olivat Regem, Jootam, Geesan, Pelet, Eefa ja Saaf.'),
(1679268,58,13,2,48,'Maaka, Kaalebin sivuvaimo, synnytti Seberin ja Tirhanan.'),
(1679269,58,13,2,49,'Hän synnytti myös Saafin, Madmannan isän, Sevan, Makbenan isän ja Gibean isän. Ja Kaalebin tytär oli Aksa.'),
(1679270,58,13,2,50,'Nämä olivat Kaalebin jälkeläisiä. Huurin, Efratan esikoisen, pojat olivat Soobal, Kirjat-Jearimin isä,'),
(1679271,58,13,2,51,'Salma, Beetlehemin isä, ja Haaref, Beet-Gaaderin isä.'),
(1679272,58,13,2,52,'Soobalin, Kirjat-Jearimin isän, jälkeläiset olivat Rooe ja toinen puoli Menuhotia.'),
(1679273,58,13,2,53,'Kirjat-Jearimin suvut olivat jeteriläiset, puutilaiset, suumatilaiset ja misrailaiset. Heistä ovat soratilaiset ja estaolilaiset lähteneet.'),
(1679274,58,13,2,54,'Ja Salman jälkeläiset olivat Beetlehem ja netofalaiset, Atrot, Beet-Jooab ja toinen puoli manahtilaisia, sorilaiset.'),
(1679275,58,13,2,55,'Ja kirjanoppineiden suvut, jotka asuivat Jaebeksessa, olivat tiratilaiset, simatilaiset ja sukatilaiset. Nämä olivat ne keeniläiset, jotka polveutuvat Hammatista, Reekabin suvun isästä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679276,58,13,3,1,'Nämä ovat ne Daavidin pojat, jotka syntyivät hänelle Hebronissa: esikoinen Amnon, jisreeliläisestä Ahinoamista; toinen Daniel, karmelilaisesta Abigailista;'),
(1679277,58,13,3,2,'kolmas Absalom, Maakan, Gesurin kuninkaan Talmain tyttären, poika; neljäs Adonia, Haggitin poika;'),
(1679278,58,13,3,3,'viides Sefatja, Abitalista; kuudes Jitream, hänen vaimostaan Eglasta.'),
(1679279,58,13,3,4,'Nämä kuusi syntyivät hänelle Hebronissa, jossa hän hallitsi seitsemän vuotta ja kuusi kuukautta. Mutta Jerusalemissa hän hallitsi kolmekymmentä kolme vuotta.'),
(1679280,58,13,3,5,'Ja nämä syntyivät hänelle Jerusalemissa: Simea, Soobab, Naatan ja Salomo, kaikkiaan neljä, Bat-Suuasta, Ammielin tyttärestä;'),
(1679281,58,13,3,6,'sitten Jibhar, Elisama, Elifelet,'),
(1679282,58,13,3,7,'Noogah, Nefeg, Jaafia,'),
(1679283,58,13,3,8,'Elisama, Eljada ja Elifelet; kaikkiaan yhdeksän.'),
(1679284,58,13,3,9,'Tässä ovat kaikki Daavidin pojat, lukuunottamatta sivuvaimojen poikia. Ja Taamar oli heidän sisarensa.'),
(1679285,58,13,3,10,'Ja Salomon poika oli Rehabeam; tämän poika Abia; tämän poika Aasa; tämän poika Joosafat;'),
(1679286,58,13,3,11,'tämän poika Jooram; tämän poika Ahasja; tämän poika Jooas;'),
(1679287,58,13,3,12,'tämän poika Amasja; tämän poika Asarja; tämän poika Jootam;'),
(1679288,58,13,3,13,'tämän poika Aahas; tämän poika Hiskia; tämän poika Manasse;'),
(1679289,58,13,3,14,'tämän poika Aamon; tämän poika Joosia.'),
(1679290,58,13,3,15,'Ja Joosian pojat olivat esikoinen Joohanan, toinen Joojakim, kolmas Sidkia, neljäs Sallum.'),
(1679291,58,13,3,16,'Ja Joojakimin pojat olivat hänen poikansa Jekonja ja tämän poika Sidkia.'),
(1679292,58,13,3,17,'Ja vangitun Jekonjan pojat olivat: hänen poikansa Sealtiel,'),
(1679293,58,13,3,18,'Malkiram, Pedaja, Senassar, Jekamja, Hoosama ja Nedabja.'),
(1679294,58,13,3,19,'Ja Pedajan pojat olivat Serubbaabel ja Siimei. Ja Serubbaabelin pojat olivat Mesullam ja Hananja, ja heidän sisarensa oli Selomit;'),
(1679295,58,13,3,20,'vielä Hasuba, Oohel, Berekja, Hasadja ja Juusab-Hesed, kaikkiaan viisi.'),
(1679296,58,13,3,21,'Ja Hananjan pojat olivat Pelatja ja Jesaja, Refajan pojat, Arnanin pojat, Obadjan pojat ja Sekanjan pojat.'),
(1679297,58,13,3,22,'Ja Sekanjan poika oli Semaja; ja Semajan pojat olivat Hattus, Jigal, Baariah, Nearja ja Saafat, kaikkiaan kuusi.'),
(1679298,58,13,3,23,'Ja Nearjan pojat olivat Eljoenai, Hiskia, Asrikam, kaikkiaan kolme.'),
(1679299,58,13,3,24,'Ja Eljoenain pojat olivat Hoodavja, Eljasib, Pelaja, Akkub, Joohanan, Delaja ja Anani, kaikkiaan seitsemän.'),
(1679300,58,13,4,1,'Juudan pojat olivat Peres, Hesron, Karmi, Huur ja Soobal.'),
(1679301,58,13,4,2,'Ja Reajalle, Soobalin pojalle, syntyi Jahat, ja Jahatille syntyivät Ahumai ja Lahad. Nämä ovat soratilaisten suvut.'),
(1679302,58,13,4,3,'Ja nämä olivat Eetamin isän pojat: Jisreel, Jisma ja Jidbas; ja heidän sisarensa nimi oli Haslelponi;'),
(1679303,58,13,4,4,'vielä Penuel, Gedorin isä, ja Eeser, Huusan isä. Nämä olivat Huurin, Efratan esikoisen, Beetlehemin isän, pojat.'),
(1679304,58,13,4,5,'Ja Ashurilla, Tekoan isällä, oli kaksi vaimoa, Hela ja Naara.'),
(1679305,58,13,4,6,'Ja Naara synnytti hänelle Ahussamin, Heeferin, Teemenin ja ahastarilaiset. Nämä olivat Naaran pojat.'),
(1679306,58,13,4,7,'Ja Helan pojat olivat Seret, Soohar ja Etnan.'),
(1679307,58,13,4,8,'Ja Koosille syntyivät Aanub ja Soobeba sekä Aharhelin, Haarumin pojan, suvut.'),
(1679308,58,13,4,9,'Mutta Jabes oli suuremmassa arvossa pidetty kuin hänen veljensä; ja hänen äitinsä oli antanut hänelle nimen Jabes sanoen: "Olen synnyttänyt hänet kipuja kärsien".'),
(1679309,58,13,4,10,'Ja Jabes huusi Israelin Jumalaa, sanoen: "Jospa sinä siunaisit minua ja laajentaisit minun alueeni; jospa sinun kätesi olisi minun kanssani ja sinä varjelisit pahasta, niin että minä pääsisin kipuja kärsimästä!" Ja Jumala antoi hänen pyyntönsä toteutua.'),
(1679310,58,13,4,11,'Ja Kelubille, Suuhan veljelle, syntyi Mehir; hän oli Estonin isä.'),
(1679311,58,13,4,12,'Ja Estonille syntyivät Beet-Raafa, Paaseah ja Tehinna, Naahaan kaupungin isä. Nämä olivat Reekan miehet.'),
(1679312,58,13,4,13,'Ja Kenaan pojat olivat Otniel ja Seraja. Ja Otnielin pojat olivat: Hatat.'),
(1679313,58,13,4,14,'Ja Meonotaille syntyi Ofra. Ja Serajalle syntyi Jooab, Seppäinlaakson isä; sillä he olivat seppiä.'),
(1679314,58,13,4,15,'Ja Kaalebin, Jefunnen pojan, pojat olivat Iiru, Eela ja Naam sekä Eelan pojat ja Kenas.'),
(1679315,58,13,4,16,'Ja Jehallelelin pojat olivat Siif, Siifa, Tiireja ja Asarel.'),
(1679316,58,13,4,17,'Ja Esran pojat olivat Jeter, Mered, Eefer ja Jaalon. Ja vaimo tuli raskaaksi ja synnytti Mirjamin, Sammain ja Jisbahin, Estemoan isän.'),
(1679317,58,13,4,18,'Ja hänen juudansukuinen vaimonsa synnytti Jeredin, Gedorin isän, Heberin, Sookon isän, ja Jekutielin, Saanoahin isän. Ja nämä olivat Bitjan, faraon tyttären, poikia, jonka Mered oli ottanut vaimokseen.'),
(1679318,58,13,4,19,'Ja Hoodian vaimon, Nahamin sisaren, pojat olivat Kegilan isä, garmilainen, ja maakatilainen Estemoa.'),
(1679319,58,13,4,20,'Ja Siimonin pojat olivat Amnon ja Rinna, Ben-Haanan ja Tiilon. Ja Jisin pojat olivat Soohet ja Soohetin poika.'),
(1679320,58,13,4,21,'Seelan, Juudan pojan, pojat olivat Eer, Leekan isä, Lada, Maaresan isä, ja pellavakankaiden kutojain suvut Beet-Asbeasta;'),
(1679321,58,13,4,22,'vielä Jookim ja Kooseban miehet sekä Jooas ja Saaraf, jotka hallitsivat Mooabia, ja Jaasubi-Lehem. Mutta nämä ovat vanhoja asioita.'),
(1679322,58,13,4,23,'He olivat niitä savenvalajia, jotka asuvat Netaimissa ja Gederassa; he asuivat siellä kuninkaan luona ja olivat hänen työssään.'),
(1679323,58,13,4,24,'Simeonin pojat olivat Nemuel ja Jaamin, Jaarib, Serah ja Saul;'),
(1679324,58,13,4,25,'tämän poika oli Sallum, tämän poika Mibsam, tämän poika Misma.'),
(1679325,58,13,4,26,'Ja Misman pojat olivat: hänen poikansa Hammuel, tämän poika Sakkur ja tämän poika Siimei.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679326,58,13,4,27,'Ja Siimeillä oli kuusitoista poikaa ja kuusi tytärtä; mutta hänen veljillään ei ollut monta lasta, eikä koko heidän sukunsa lisääntynyt Juudan lasten määrään.'),
(1679327,58,13,4,28,'Ja he asuivat Beersebassa, Mooladassa ja Hasar-Suualissa,'),
(1679328,58,13,4,29,'Bilhassa, Esemissä ja Tooladissa,'),
(1679329,58,13,4,30,'Betuelissa, Hormassa ja Siklagissa,'),
(1679330,58,13,4,31,'Beet-Markabotissa, Hasar-Suusimissa, Beet-Birissä ja Saaraimissa. Nämä olivat heidän kaupunkinsa Daavidin hallitukseen asti.'),
(1679331,58,13,4,32,'Ja heidän kylänsä olivat Eetam, Ain, Rimmon, Tooken ja Aasan - viisi kaupunkia;'),
(1679332,58,13,4,33,'siihen lisäksi kaikki heidän kylänsä, jotka olivat näiden kaupunkien ympärillä, aina Baaliin asti. Nämä olivat heidän asuinsijansa; ja heillä oli omat sukuluettelonsa.'),
(1679333,58,13,4,34,'Vielä: Mesobab, Jamlek, Joosa, Amasjan poika,'),
(1679334,58,13,4,35,'Jooel, Jeehu, Joosibjan poika, joka oli Serajan poika, joka Asielin poika;'),
(1679335,58,13,4,36,'Eljoenai, Jaakoba, Jesohaja, Asaja, Adiel, Jesimiel, Benaja'),
(1679336,58,13,4,37,'ja Siisa, Sifin poika, joka oli Allonin poika, joka Jedajan poika, joka Simrin poika, joka Semajan poika.'),
(1679337,58,13,4,38,'Nämä nimeltä mainitut olivat sukujensa ruhtinaita, ja heidän perhekuntansa olivat levinneet ja lisääntyneet.'),
(1679338,58,13,4,39,'Ja he kulkivat Gedoriin päin, aina laakson itäiseen osaan saakka, hakeakseen laidunta lampailleen.'),
(1679339,58,13,4,40,'Ja he löysivät lihavan ja hyvän laitumen, ja maa oli tilava joka suuntaan sekä rauhallinen ja levollinen, sillä ne, jotka olivat asuneet siellä ennen, olivat haamilaisia.'),
(1679340,58,13,4,41,'Mutta nämä nimeltä luetellut tulivat Hiskian, Juudan kuninkaan, päivinä ja valtasivat heidän telttansa ja voittivat meunilaiset, jotka olivat siellä, ja vihkivät heidät tuhon omiksi, aina tähän päivään asti, ja asettuivat heidän sijaansa, sillä siellä oli laidunta heidän lampaillensa.'),
(1679341,58,13,4,42,'Ja heistä, simeonilaisista, meni viisisataa miestä Seirin vuoristoon, ja heidän etunenässään olivat Pelatja, Nearja, Refaja ja Ussiel, Jisin pojat.'),
(1679342,58,13,4,43,'Ja he surmasivat ne, jotka olivat jäljellä pelastuneista amalekilaisista, ja jäivät sinne asumaan aina tähän päivään asti.'),
(1679343,58,13,5,1,'Ruubenin, Israelin esikoisen, pojat olivat - hän oli näet esikoinen, mutta koska hän saastutti isänsä vuoteen, annettiin hänen esikoisuutensa Joosefin, Israelin pojan, pojille, kuitenkin niin, ettei heitä merkitty sukuluetteloon esikoisina,'),
(1679344,58,13,5,2,'sillä Juuda tuli voimallisimmaksi veljiensä joukossa, ja yhdestä hänen jälkeläisistään tuli ruhtinas, mutta esikoisuus joutui Joosefille -'),
(1679345,58,13,5,3,'Ruubenin, Israelin esikoisen, pojat olivat Hanok ja Pallu, Hesron ja Karmi.'),
(1679346,58,13,5,4,'Jooelin pojat olivat: hänen poikansa Semaja, tämän poika Goog, tämän poika Siimei,'),
(1679347,58,13,5,5,'tämän poika Miika, tämän poika Reaja, tämän poika Baal'),
(1679348,58,13,5,6,'ja tämän poika Beera, jonka Assurin kuningas Tillegat-Pilneser vei pakkosiirtolaisuuteen; hän oli ruubenilaisten ruhtinas.'),
(1679349,58,13,5,7,'Ja hänen veljensä olivat sukujensa mukaan, kun heidät merkittiin sukuluetteloon heidän polveutumisensa mukaan: Jegiel, päämies, Sakarja,'),
(1679350,58,13,5,8,'Bela, Aasaan poika, joka oli Seman poika, joka Jooelin poika; hän asui Aroerissa ja aina Neboon ja Baal-Meoniin asti.'),
(1679351,58,13,5,9,'Ja idässä hän asui erämaahan saakka, joka alkaa Eufrat-virrasta; sillä heillä oli suuria karjalaumoja Gileadin maassa.'),
(1679352,58,13,5,10,'Mutta Saulin päivinä he kävivät sotaa hagrilaisia vastaan, ja kun nämä olivat joutuneet heidän käsiinsä, asettuivat he heidän telttoihinsa Gileadin koko itäistä rajaseutua myöten.'),
(1679353,58,13,5,11,'Gaadilaiset asuivat heidän kanssaan rajakkain Baasanin maassa Salkaan saakka:'),
(1679354,58,13,5,12,'Jooel päämiehenä ja Saafam toisena, sitten Janai ja Saafat Baasanissa.'),
(1679355,58,13,5,13,'Ja heidän veljensä olivat, perhekuntiensa mukaan: Miikael, Mesullam, Seba, Joorai, Jakan, Siia ja Eeber, kaikkiaan seitsemän.'),
(1679356,58,13,5,14,'Nämä olivat Abihailin pojat, joka oli Huurin poika, joka Jaaroahin poika, joka Gileadin poika, joka Miikaelin poika, joka Jesisain poika, joka Jahdon poika, joka Buusin poika.'),
(1679357,58,13,5,15,'Ahi, Abdielin poika, joka oli Guunin poika, oli heidän perhekuntiensa päämies.'),
(1679358,58,13,5,16,'Ja he asuivat Gileadissa, Baasanissa ja sen tytärkaupungeissa sekä kaikilla Saaronin laidunmailla, niin kauas kuin ne ulottuivat.'),
(1679359,58,13,5,17,'Kaikki nämä merkittiin sukuluetteloon Juudan kuninkaan Jootamin ja Israelin kuninkaan Jerobeamin päivinä.'),
(1679360,58,13,5,18,'Ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa - sotakuntoisia miehiä, jotka kantoivat kilpeä ja miekkaa ja jännittivät jousta ja olivat taisteluun harjaantuneita, neljäkymmentäneljä tuhatta seitsemänsataa kuusikymmentä sotakelpoista miestä -'),
(1679361,58,13,5,19,'kävivät sotaa hagrilaisia, Jeturia, Naafista ja Noodabia vastaan.'),
(1679362,58,13,5,20,'Ja he saivat apua näitä vastaan, niin että hagrilaiset ja kaikki, jotka olivat heidän kanssaan, joutuivat heidän käsiinsä; sillä he huusivat taistelussa Jumalan puoleen, ja hän kuuli heidän rukouksensa, koska he turvasivat häneen.'),
(1679363,58,13,5,21,'Ja he veivät saaliinaan heidän karjansa, viisikymmentä tuhatta kamelia, kaksisataa viisikymmentä tuhatta lammasta ja kaksituhatta aasia, sekä satatuhatta ihmistä.'),
(1679364,58,13,5,22,'Paljon oli surmattuina kaatuneita, sillä sota oli Jumalan sota. Ja he asettuivat asumaan heidän sijaansa aina pakkosiirtolaisuuteen saakka.'),
(1679365,58,13,5,23,'Toinen puoli Manassen sukukuntaa asui siinä maassa, Baasanista aina Baal-Hermoniin ja Seniriin ja Hermon-vuoreen saakka; heitä oli paljon.'),
(1679366,58,13,5,24,'Ja nämä olivat heidän perhekuntiensa päämiehet: Eefer, Jisi, Eliel, Asriel, Jeremia, Hoodavja ja Jahdiel, sotaurhoja, kuuluisia miehiä, perhekuntiensa päämiehiä.'),
(1679367,58,13,5,25,'Mutta he tulivat uskottomiksi isiensä Jumalaa kohtaan ja juoksivat haureudessa maan kansojen jumalain jäljessä, niiden kansojen, jotka Jumala oli hävittänyt heidän edestänsä.'),
(1679368,58,13,5,26,'Niin Israelin Jumala herätti Puulin, Assurin kuninkaan, hengen ja Tillegat-Pilneserin, Assurin kuninkaan, hengen ja kuljetutti heidät, ruubenilaiset, gaadilaiset ja toisen puolen Manassen sukukuntaa, pakkosiirtolaisuuteen ja antoi viedä heidät Halahiin, Haaboriin, Haaraan ja Goosanin joen rannoille, missä he tänäkin päivänä ovat.'),
(1679369,58,13,6,1,'Leevin pojat olivat Geerson, Kehat ja Merari.'),
(1679370,58,13,6,2,'Ja Kehatin pojat olivat Amram, Jishar, Hebron ja Ussiel.'),
(1679371,58,13,6,3,'Ja Amramin lapset olivat Aaron, Mooses ja Mirjam. Ja Aaronin pojat olivat Naadab, Abihu, Eleasar ja Iitamar.'),
(1679372,58,13,6,4,'Eleasarille syntyi Piinehas; Piinehaalle syntyi Abisua.'),
(1679373,58,13,6,5,'Ja Abisualle syntyi Bukki, ja Bukille syntyi Ussi.'),
(1679374,58,13,6,6,'Ja Ussille syntyi Serahja, ja Serahjalle syntyi Merajot.'),
(1679375,58,13,6,7,'Merajotille syntyi Amarja, ja Amarjalle syntyi Ahitub.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679376,58,13,6,8,'Ja Ahitubille syntyi Saadok, ja Saadokille syntyi Ahimaas.'),
(1679377,58,13,6,9,'Ja Ahimaasille syntyi Asarja, ja Asarjalle syntyi Joohanan.'),
(1679378,58,13,6,10,'Ja Joohananille syntyi Asarja, hän joka toimitti papinvirkaa temppelissä, jonka Salomo rakennutti Jerusalemiin.'),
(1679379,58,13,6,11,'Ja Asarjalle syntyi Amarja, ja Amarjalle syntyi Ahitub.'),
(1679380,58,13,6,12,'Ja Ahitubille syntyi Saadok, ja Saadokille syntyi Sallum.'),
(1679381,58,13,6,13,'Ja Sallumille syntyi Hilkia, ja Hilkialle syntyi Asarja.'),
(1679382,58,13,6,14,'Ja Asarjalle syntyi Seraja, ja Serajalle syntyi Jehosadak.'),
(1679383,58,13,6,15,'Mutta Jehosadakin oli lähdettävä mukaan silloin, kun Herra antoi Nebukadnessarin viedä Juudan ja Jerusalemin pakkosiirtolaisuuteen.'),
(1679384,58,13,6,16,'Leevin pojat olivat Geersom, Kehat ja Merari.'),
(1679385,58,13,6,17,'Ja nämä ovat Geersomin poikien nimet: Libni ja Siimei.'),
(1679386,58,13,6,18,'Ja Kehatin pojat olivat Amram, Jishar, Hebron ja Ussiel.'),
(1679387,58,13,6,19,'Merarin pojat olivat Mahli ja Muusi. Nämä olivat leeviläisten suvut heidän isiensä mukaan.'),
(1679388,58,13,6,20,'Geersomista polveutuivat hänen poikansa Libni, tämän poika Jahat, tämän poika Simma,'),
(1679389,58,13,6,21,'tämän poika Jooah, tämän poika Iddo, tämän Serah ja tämän poika Jeatrai.'),
(1679390,58,13,6,22,'Kehatin pojat olivat: hänen poikansa Amminadab, tämän poika Koorah, tämän poika Assir,'),
(1679391,58,13,6,23,'tämän poika Elkana, tämän poika Ebjasaf, tämän poika Assir,'),
(1679392,58,13,6,24,'tämän poika Tahat, tämän poika Uuriel, tämän poika Ussia ja tämän poika Saul.'),
(1679393,58,13,6,25,'Ja Elkanan pojat olivat Amasai ja Ahimot.'),
(1679394,58,13,6,26,'Elkana: Elkanan pojat, Suufai, tämän poika Nahat,'),
(1679395,58,13,6,27,'tämän poika Eliab, tämän poika Jeroham, tämän poika Elkana.'),
(1679396,58,13,6,28,'Ja Samuelin pojat olivat esikoinen Vasni ja Abia.'),
(1679397,58,13,6,29,'Merarin pojat olivat: Mahli, tämän poika Libni, tämän poika Siimei, tämän poika Ussa,'),
(1679398,58,13,6,30,'tämän poika Simea, tämän poika Haggia ja tämän poika Asaja.'),
(1679399,58,13,6,31,'Ja nämä ovat ne, jotka Daavid asetti pitämään huolta laulusta Herran temppelissä, senjälkeen kuin arkki oli saanut leposijan.'),
(1679400,58,13,6,32,'He palvelivat veisaajina ilmestysmajan asumuksen edessä, kunnes Salomo rakensi Herran temppelin Jerusalemiin; he toimittivat virkaansa, niinkuin heille oli säädetty.'),
(1679401,58,13,6,33,'Ja nämä ovat ne, jotka palvelivat, ja nämä heidän poikansa: Kehatilaisia: Heeman, veisaaja, Jooelin poika, joka oli Samuelin poika,'),
(1679402,58,13,6,34,'joka Elkanan poika, joka Jerohamin poika, joka Elielin poika, joka Tooahin poika,'),
(1679403,58,13,6,35,'joka Suufin poika, joka Elkanan poika, joka Mahatin poika, joka Amasain poika,'),
(1679404,58,13,6,36,'joka Elkanan poika, joka Jooelin poika, joka Asarjan poika, joka Sefanjan poika,'),
(1679405,58,13,6,37,'joka Tahatin poika, joka Assirin poika, joka Ebjasafin poika, joka Koorahin poika,'),
(1679406,58,13,6,38,'joka Jisharin poika, joka Kehatin poika, joka Leevin poika, joka Israelin poika.'),
(1679407,58,13,6,39,'Vielä hänen veljensä Aasaf, joka seisoi hänen oikealla puolellansa, Aasaf, Berekjan poika, joka oli Simean poika,'),
(1679408,58,13,6,40,'joka Miikaelin poika, joka Baasejan poika, joka Malkian poika,'),
(1679409,58,13,6,41,'joka Etnin poika, joka Serahin poika, joka Adajan poika,'),
(1679410,58,13,6,42,'joka Eetanin poika, joka Simman poika, joka Siimein poika,'),
(1679411,58,13,6,43,'joka Jahatin poika, joka Geersomin poika, joka Leevin poika.'),
(1679412,58,13,6,44,'Ja heidän veljensä, Merarin pojat, vasemmalla puolella: Eetan, Kiisin poika, joka oli Abdin poika, joka Mallukin poika,'),
(1679413,58,13,6,45,'joka Hasabjan poika, joka Amasjan poika, joka Hilkian poika,'),
(1679414,58,13,6,46,'joka Amsin poika, joka Baanin poika, joka Semerin poika,'),
(1679415,58,13,6,47,'joka Mahlin poika, joka Muusin poika, joka Merarin poika, joka Leevin poika.'),
(1679416,58,13,6,48,'Ja heidän veljensä, leeviläiset, olivat annetut toimittamaan kaikkinaista palvelusta Jumalan temppeli-asumuksessa.'),
(1679417,58,13,6,49,'Mutta Aaron ja hänen poikansa polttivat uhreja polttouhrialttarilla ja suitsutusalttarilla, toimittivat kaikki askareet kaikkeinpyhimmässä ja Israelin sovituksen, aivan niinkuin Jumalan palvelija Mooses oli käskenyt.'),
(1679418,58,13,6,50,'Ja nämä olivat Aaronin pojat: hänen poikansa Eleasar, tämän poika Piinehas, tämän poika Abisua,'),
(1679419,58,13,6,51,'tämän poika Bukki, tämän poika Ussi, tämän poika Serahja,'),
(1679420,58,13,6,52,'tämän poika Merajot, tämän poika Amarja, tämän poika Ahitub,'),
(1679421,58,13,6,53,'tämän poika Saadok, tämän poika Ahimaas.'),
(1679422,58,13,6,54,'Ja nämä olivat heidän asuinsijansa, heidän leiripaikkojensa mukaan, heidän alueellaan: Niille Aaronin jälkeläisille, jotka olivat kehatilaisten sukua, sillä he saivat arpaosan,'),
(1679423,58,13,6,55,'annettiin Hebron Juudan maasta, ympärillä olevine laidunmaineen.'),
(1679424,58,13,6,56,'Mutta kaupungin peltomaat kylineen annettiin Kaalebille, Jefunnen pojalle.'),
(1679425,58,13,6,57,'Aaronin jälkeläisille annettiin turvakaupungit Hebron, Libna laidunmaineen, Jattir, Estemoa laidunmaineen,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679426,58,13,6,58,'Hiilen laidunmaineen, Debir laidunmaineen,'),
(1679427,58,13,6,59,'Aasan laidunmaineen ja Beet-Semes laidunmaineen.'),
(1679428,58,13,6,60,'Ja Benjaminin sukukunnasta Geba laidunmaineen, Aalemet laidunmaineen ja Anatot laidunmaineen. Heidän kaupunkejaan oli kaikkiaan kolmetoista kaupunkia, heidän sukujensa mukaan.'),
(1679429,58,13,6,61,'Ja muut kehatilaiset saivat arvalla sukujensa mukaan Efraimin sukukunnalta, Daanin sukukunnalta ja toiselta puolelta Manassen sukukuntaa kymmenen kaupunkia.'),
(1679430,58,13,6,62,'Ja geersomilaiset saivat sukujensa mukaan Isaskarin sukukunnalta, Asserin sukukunnalta, Naftalin sukukunnalta ja Manassen sukukunnalta Baasanista kolmetoista kaupunkia.'),
(1679431,58,13,6,63,'Merarilaiset saivat arvalla sukujensa mukaan Ruubenin sukukunnalta, Gaadin sukukunnalta ja Sebulonin sukukunnalta kaksitoista kaupunkia.'),
(1679432,58,13,6,64,'Näin israelilaiset antoivat leeviläisille nämä kaupungit laidunmaineen.'),
(1679433,58,13,6,65,'He antoivat arvalla Juudan lasten sukukunnasta, simeonilaisten sukukunnasta ja benjaminilaisten sukukunnasta nämä nimeltä mainitut kaupungit.'),
(1679434,58,13,6,66,'Kehatilaisten suvuista muutamat saivat arvalla Efraimin sukukunnalta alueekseen seuraavat kaupungit:'),
(1679435,58,13,6,67,'heille annettiin turvakaupungit Sikem laidunmaineen Efraimin vuoristosta, Geser laidunmaineen,'),
(1679436,58,13,6,68,'Jokmeam laidunmaineen, Beet-Hooron laidunmaineen,'),
(1679437,58,13,6,69,'Aijalon laidunmaineen ja Gat-Rimmon laidunmaineen;'),
(1679438,58,13,6,70,'ja toisesta puolesta Manassen sukukuntaa Aaner laidunmaineen ja Bileam laidunmaineen. Nämä tulivat muitten kehatilaisten suvuille.'),
(1679439,58,13,6,71,'Geersomilaiset saivat sukujensa mukaan toiselta puolelta Manassen sukukuntaa Goolanin laidunmaineen Baasanista ja Astarotin laidunmaineen;'),
(1679440,58,13,6,72,'ja Isaskarin sukukunnalta Kedeksen laidunmaineen, Dobratin laidunmaineen,'),
(1679441,58,13,6,73,'Raamotin laidunmaineen ja Aanemin laidunmaineen;'),
(1679442,58,13,6,74,'ja Asserin sukukunnalta Maasalin laidunmaineen, Abdonin laidunmaineen,'),
(1679443,58,13,6,75,'Huukokin laidunmaineen ja Rehobin laidunmaineen;'),
(1679444,58,13,6,76,'ja Naftalin sukukunnalta Kedeksen laidunmaineen Galileasta, Hammonin laidunmaineen ja Kirjataimin laidunmaineen.'),
(1679445,58,13,6,77,'Muut merarilaiset saivat Sebulonin sukukunnalta Rimmonin laidunmaineen ja Taaborin laidunmaineen;'),
(1679446,58,13,6,78,'ja tuolta puolelta Jerikon Jordanin, Jordanista auringonnousuun päin, Ruubenin sukukunnalta Beserin laidunmaineen erämaasta, Jahaan laidunmaineen,'),
(1679447,58,13,6,79,'Kedemotin laidunmaineen, Meefaatin laidunmaineen;'),
(1679448,58,13,6,80,'ja Gaadin sukukunnalta Raamotin laidunmaineen Gileadista, Mahanaimin laidunmaineen,'),
(1679449,58,13,6,81,'Hesbonin laidunmaineen ja Jaeserin laidunmaineen.'),
(1679450,58,13,7,1,'Isaskarin pojat olivat Toola, Puua, Jaasub ja Simron, kaikkiaan neljä.'),
(1679451,58,13,7,2,'Ja Toolan pojat olivat Ussi, Refaja, Jeriel, Jahmai, Jibsam ja Samuel, jotka olivat perhekuntiensa päämiehiä, Toolan jälkeläisiä, sotaurhoja, polveutumisensa mukaan. Daavidin aikana oli heidän lukumääränsä kaksikymmentäkaksi tuhatta kuusisataa.'),
(1679452,58,13,7,3,'Ja Ussin poika oli Jisrahja, ja Jisrahjan pojat olivat Miikael, Obadja, Jooel ja Jissia, kaikkiaan viisi, kaikki päämiehiä.'),
(1679453,58,13,7,4,'Heitä seurasi polveutumisensa ja perhekuntiensa mukaan taisteluun valmiina sotajoukkoina kolmekymmentäkuusi tuhatta miestä, sillä heillä oli paljon vaimoja ja lapsia.'),
(1679454,58,13,7,5,'Ja heidän veljensä, kaikissa Isaskarin suvuissa, olivat sotaurhoja. Sukuluetteloihin merkittyjä oli kaikkiaan kahdeksankymmentäseitsemän tuhatta.'),
(1679455,58,13,7,6,'Benjaminia oli: Bela, Beker ja Jediael, kaikkiaan kolme.'),
(1679456,58,13,7,7,'Ja Belan pojat olivat Esbon, Ussi, Ussiel, Jerimot ja Iiri, kaikkiaan viisi, perhekunta-päämiehiä, sotaurhoja. Ja sukuluetteloihin merkittyjä oli heitä kaksikymmentäkaksi tuhatta kolmekymmentä neljä.'),
(1679457,58,13,7,8,'Ja Bekerin pojat olivat Semira, Jooas, Elieser, Eljoenai, Omri, Jeremot, Abia, Anatot ja Aalemet; kaikki nämä olivat Bekerin poikia.'),
(1679458,58,13,7,9,'Ja sukuluetteloihin merkittyjä oli heitä polveutumisensa mukaan, perhekunta-päämiestensä, sotaurhojen, mukaan, kaksikymmentä tuhatta kaksisataa.'),
(1679459,58,13,7,10,'Ja Jediaelin poika oli Bilhan, ja Bilhanin pojat olivat Jeus, Benjamin, Eehud, Kenaana, Seetan, Tarsis ja Ahisahar.'),
(1679460,58,13,7,11,'Kaikki nämä olivat Jediaelin poikia perhekunta-päämiesten, sotaurhojen, mukaan; seitsemäntoista tuhatta kaksisataa sotakelpoista miestä.'),
(1679461,58,13,7,12,'Ja Suppim ja Huppim olivat Iirin poikia; Huusim oli Aherin poika.'),
(1679462,58,13,7,13,'Naftalin pojat olivat Jahasiel, Guuni, Jeeser ja Sallum, Bilhan jälkeläisiä.'),
(1679463,58,13,7,14,'Manassen poika oli Asriel, jonka hänen aramilainen sivuvaimonsa synnytti; tämä synnytti Maakirin, Gileadin isän.'),
(1679464,58,13,7,15,'Ja Maakir otti vaimon Huppimille ja Suppimille, ja hänen sisarensa nimi oli Maaka. Ja toisen nimi oli Selofhad; ja Selofhadilla oli tyttäriä.'),
(1679465,58,13,7,16,'Ja Maaka, Maakirin vaimo, synnytti pojan, jolle hän antoi nimen Peres; hänen veljensä nimi oli Seres, ja hänen poikansa olivat Uulam ja Rekem.'),
(1679466,58,13,7,17,'Uulamin poika oli Bedan. Nämä olivat Gileadin pojat, joka oli Maakirin poika, joka Manassen poika.'),
(1679467,58,13,7,18,'Ja hänen sisarensa Mooleket synnytti Iishodin, Abieserin ja Mahlan.'),
(1679468,58,13,7,19,'Ja Semidan pojat olivat Ahjan, Sekem, Likhi ja Aniam.'),
(1679469,58,13,7,20,'Efraimin pojat olivat: Suutelah, tämän poika Bered, tämän poika Tahat, tämän poika Elada, tämän poika Tahat,'),
(1679470,58,13,7,21,'tämän poika Saabad, tämän poika Suutelah, sekä Eser ja Elead. Ja Gatin miehet, siinä maassa syntyneet, tappoivat heidät, koska he olivat lähteneet ottamaan heidän karjaansa.'),
(1679471,58,13,7,22,'Ja heidän isänsä Efraim suri pitkät ajat, ja hänen veljensä tulivat lohduttamaan häntä.'),
(1679472,58,13,7,23,'Sitten hän yhtyi vaimoonsa, ja tämä tuli raskaaksi ja synnytti pojan; ja hän antoi tälle nimen Beria, koska se oli tapahtunut hänen perheensä onnettomuuden aikana.'),
(1679473,58,13,7,24,'Ja hänen tyttärensä oli Seera; tämä rakensi Ala- ja Ylä-Beet-Hooronin sekä Ussen-Seeran.'),
(1679474,58,13,7,25,'Ja Berian poika oli Refah, samoin Resef, tämän poika Telah, tämän poika Tahan,'),
(1679475,58,13,7,26,'tämän poika Ladan, tämän poika Ammihud, tämän poika Elisama,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679476,58,13,7,27,'tämän poika Nuun ja tämän poika Joosua.'),
(1679477,58,13,7,28,'Ja heidän perintömaansa ja asuinsijansa olivat Beetel ja sen tytärkaupungit, itään päin Naaran ja länteen päin Geser ja sen tytärkaupungit, sekä Sikem ja sen tytärkaupungit, aina Aijaan ja sen tytärkaupunkeihin asti.'),
(1679478,58,13,7,29,'Ja manasselaisten hallussa olivat Beet-Sean ja sen tytärkaupungit, Taanak ja sen tytärkaupungit, Megiddo ja sen tytärkaupungit, Door ja sen tytärkaupungit. Näissä asuivat Joosefin, Israelin pojan, jälkeläiset.'),
(1679479,58,13,7,30,'Asserin pojat olivat Jimna, Jisva, Jisvi ja Beria; heidän sisarensa oli Serah.'),
(1679480,58,13,7,31,'Berian pojat olivat Heber ja Malkiel; tämä oli Birsaitin isä.'),
(1679481,58,13,7,32,'Ja Heberille syntyi Jaflet, Soomer, Hootam ja heidän sisarensa Suua.'),
(1679482,58,13,7,33,'Ja Jafletin pojat olivat Paasak, Bimhal ja Asva; nämä ovat Jafletin pojat.'),
(1679483,58,13,7,34,'Ja Semerin pojat olivat Ahi, Rohga, Hubba ja Aram.'),
(1679484,58,13,7,35,'Ja hänen veljensä Heelemin pojat olivat Soofah, Jimna, Seeles ja Aamal.'),
(1679485,58,13,7,36,'Soofahin pojat olivat Suuah, Harnefer, Suual, Beeri, Jimra,'),
(1679486,58,13,7,37,'Beser, Hood, Samma, Silsa, Jitran ja Beera.'),
(1679487,58,13,7,38,'Ja Jeterin pojat olivat Jefunne, Fispa ja Ara.'),
(1679488,58,13,7,39,'Ja Ullan pojat olivat Aarah, Hanniel ja Risja.'),
(1679489,58,13,7,40,'Kaikki nämä olivat Asserin jälkeläisiä, perhekunta-päämiehiä, valittuja sotaurhoja, ruhtinasten päämiehiä. Ja heidän sukuluetteloihin merkittyjen sotakelpoisten miestensä lukumäärä oli kaksikymmentäkuusi tuhatta.'),
(1679490,58,13,8,1,'Benjaminille syntyi esikoisena Bela, toisena Asbel, kolmantena Ahrah,'),
(1679491,58,13,8,2,'neljäntenä Nooha ja viidentenä Raafa.'),
(1679492,58,13,8,3,'Ja Belalla oli pojat: Addar, Geera, Abihud,'),
(1679493,58,13,8,4,'Abisua, Naaman, Ahoah,'),
(1679494,58,13,8,5,'Geera, Sefufan ja Huuram.'),
(1679495,58,13,8,6,'Ja nämä olivat Eehudin pojat - nämä olivat Geban asukkaiden perhekunta-päämiehet. Heidät siirrettiin pois Manahatiin,'),
(1679496,58,13,8,7,'niin myös Naaman, Ahia ja Geera; hän siirsi heidät pois. Hänelle syntyi Ussa ja Ahihud.'),
(1679497,58,13,8,8,'Ja Saharaimille syntyi Mooabin maassa, sittenkuin hän oli hyljännyt vaimonsa Huusimin ja Baaran,'),
(1679498,58,13,8,9,'hänelle syntyi hänen vaimostaan Hoodeksesta Joobab, Sibja, Meesa, Malkam,'),
(1679499,58,13,8,10,'Jeus, Sokja ja Mirma; nämä olivat hänen poikiansa, perhekunta-päämiehiä.'),
(1679500,58,13,8,11,'Ja Huusimista oli hänelle syntynyt Abitub ja Elpaal.'),
(1679501,58,13,8,12,'Ja Elpaalin pojat olivat Eeber, Misam ja Semed. Tämä rakensi Oonon ja Loodin ynnä sen tytärkaupungit.'),
(1679502,58,13,8,13,'Beria ja Sema olivat Aijalonin asukasten perhekunta-päämiehiä; ja he karkoittivat Gatin asukkaat,'),
(1679503,58,13,8,14,'he ja Ahjo, Saasak ja Jeremot.'),
(1679504,58,13,8,15,'Ja Sebadja, Arad, Eder,'),
(1679505,58,13,8,16,'Miikael, Jispa ja Jooha olivat Berian poikia.'),
(1679506,58,13,8,17,'Ja Sebadja, Mesullam, Hiski, Heber,'),
(1679507,58,13,8,18,'Jismerai, Jislia ja Joobab olivat Elpaalin poikia.'),
(1679508,58,13,8,19,'Ja Jaakim, Sikri, Sabdi,'),
(1679509,58,13,8,20,'Elienai, Silletai, Eliel,'),
(1679510,58,13,8,21,'Adaja, Beraja ja Simrat olivat Siimein poikia.'),
(1679511,58,13,8,22,'Ja Jispan, Eder, Eliel,'),
(1679512,58,13,8,23,'Abdon, Sikri, Haanan,'),
(1679513,58,13,8,24,'Hananja, Eelam, Antotia,'),
(1679514,58,13,8,25,'Jifdeja ja Penuel olivat Saasakin poikia.'),
(1679515,58,13,8,26,'Ja Samserai, Seharja, Atalja,'),
(1679516,58,13,8,27,'Jaaresja, Elia ja Sikri olivat Jerohamin poikia.'),
(1679517,58,13,8,28,'Nämä olivat perhekunta-päämiehiä, päämiehiä polveutumisensa mukaan; he asuivat Jerusalemissa.'),
(1679518,58,13,8,29,'Gibeonissa asui Gibeonin isä, jonka vaimon nimi oli Maaka.'),
(1679519,58,13,8,30,'Ja hänen esikoispoikansa oli Abdon, sitten Suur, Kiis, Baal, Naadab,'),
(1679520,58,13,8,31,'Gedor, Ahjo ja Seker.'),
(1679521,58,13,8,32,'Ja Miklotille syntyi Simea. Hekin asuivat veljinensä Jerusalemissa, rajakkain veljiensä kanssa.'),
(1679522,58,13,8,33,'Ja Neerille syntyi Kiis, Kiisille syntyi Saul, ja Saulille syntyi Joonatan, Malkisua, Abinadab ja Esbaal.'),
(1679523,58,13,8,34,'Ja Joonatanin poika oli Meribbaal, ja Meribbaalille syntyi Miika.'),
(1679524,58,13,8,35,'Ja Miikan pojat olivat Piiton, Melek, Tarea ja Aahas.'),
(1679525,58,13,8,36,'Ja Aahaalle syntyi Jooadda, Jooaddalle syntyi Aalemet, Asmavet ja Simri. Ja Simrille syntyi Moosa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679526,58,13,8,37,'Ja Moosalle syntyi Binea; hänen poikansa oli Raafa, tämän poika Elasa ja tämän poika Aasel.'),
(1679527,58,13,8,38,'Ja Aaselilla oli kuusi poikaa, ja nämä ovat heidän nimensä: Asrikam, Bookeru, Jismael, Searja, Obadja ja Haanan. Nämä kaikki olivat Aaselin poikia.'),
(1679528,58,13,8,39,'Ja Eesekin, hänen veljensä, pojat olivat: hänen esikoisensa Uulam, toinen Jeus ja kolmas Elifelet.'),
(1679529,58,13,8,40,'Ja Uulamin pojat olivat sotaurhoja, jousen jännittäjiä, ja heillä oli paljon poikia ja poikien poikia, sataviisikymmentä. Nämä kaikki ovat benjaminilaisia.'),
(1679530,58,13,9,1,'Koko Israel merkittiin sukuluetteloon, ja katso, he ovat kirjoitetut Israelin kuningasten kirjaan. Ja Juuda vietiin Baabeliin pakkosiirtolaisuuteen uskottomuutensa tähden.'),
(1679531,58,13,9,2,'Entiset asukkaat, jotka elivät perintömaillaan, kaupungeissaan, olivat israelilaisia, pappeja, leeviläisiä ja temppelipalvelijoita.'),
(1679532,58,13,9,3,'Jerusalemissa asui Juudan lapsia, benjaminilaisia, efraimilaisia ja manasselaisia, nimittäin:'),
(1679533,58,13,9,4,'Uutai, Ammihudin poika, joka oli Omrin poika, joka Imrin poika, joka Baanin poika, Pereksen, Juudan pojan, jälkeläisiä;'),
(1679534,58,13,9,5,'ja seelalaisia: Asaja, esikoinen, ja hänen poikansa;'),
(1679535,58,13,9,6,'serahilaisia: Jeguel ja hänen veljensä, kuusisataa yhdeksänkymmentä;'),
(1679536,58,13,9,7,'benjaminilaisia: Sallu, Mesullamin poika, joka oli Hoodavjan poika, joka Senuan poika,'),
(1679537,58,13,9,8,'Jibneja, Jerohamin poika, Eela, Ussin poika, joka oli Mikrin poika, ja Mesullam, Sefatjan poika, joka oli Reguelin poika, joka Jibnean poika,'),
(1679538,58,13,9,9,'sekä heidän veljensä, heidän polveutumisensa mukaan, yhdeksänsataa viisikymmentä kuusi. Kaikki nämä olivat perhekunta-päämiehiä perhekunnissaan.'),
(1679539,58,13,9,10,'Ja pappeja: Jedaja, Joojarib, Jaakin,'),
(1679540,58,13,9,11,'Asarja, Hilkian poika, joka oli Mesullamin poika, joka Saadokin poika, joka Merajotin poika, joka Ahitubin poika, Jumalan temppelin esimies;'),
(1679541,58,13,9,12,'Adaja, Jerohamin poika, joka oli Pashurin poika, joka Malkian poika, ja Maesai, Adielin poika, joka oli Jahseran poika, joka Mesullamin poika, joka Mesillemitin poika, joka Immerin poika;'),
(1679542,58,13,9,13,'sekä heidän veljensä, heidän perhekuntiensa päämiehet, tuhat seitsemänsataa kuusikymmentä miestä, kelvollisia toimittamaan palvelusta Jumalan temppelissä.'),
(1679543,58,13,9,14,'Ja leeviläisiä: Semaja, Hassubin poika, joka oli Asrikamin poika, joka Hasabjan poika, merarilaisia;'),
(1679544,58,13,9,15,'Bakbakkar, Heres, Gaalal, Mattanja, Miikan poika, joka oli Sikrin poika, joka Aasafin poika;'),
(1679545,58,13,9,16,'Obadja, Semajan poika, joka oli Gaalalin poika, joka Jedutunin poika; ja Berekja, Aasan poika, joka oli Elkanan poika, hänen, joka asui netofalaisten kylissä.'),
(1679546,58,13,9,17,'Ja ovenvartijat: Sallum, Akkub, Talmon ja Ahiman veljineen: Sallum oli päämies,'),
(1679547,58,13,9,18,'ja tähän saakka hän on ollut vartijana Kuninkaan portilla, idän puolella. Nämä olivat ovenvartijoina leeviläisten leirissä.'),
(1679548,58,13,9,19,'Mutta Sallumilla, Kooren pojalla, joka oli Ebjasafin poika, joka Koorahin poika, ja hänen veljillään, jotka olivat hänen perhekuntaansa - koorahilaisilla, oli palvelustehtävänä majan kynnyksien vartioiminen; heidän isänsä olivat näet vartioineet sisäänkäytävää Herran leirissä.'),
(1679549,58,13,9,20,'Ja Piinehas, Eleasarin poika, oli muinoin heidän esimiehenään - Herra olkoon hänen kanssaan! -'),
(1679550,58,13,9,21,'Sakarja, Meselemjan poika, oli ovenvartijana ilmestysmajan ovella.'),
(1679551,58,13,9,22,'Kaikkiaan oli kynnyksien ovenvartijoiksi valittuja kaksisataa kaksitoista; he olivat kylissään merkityt sukuluetteloon. Daavid ja Samuel, näkijä, olivat asettaneet heidät heidän luottamustoimeensa.'),
(1679552,58,13,9,23,'Niin he ja heidän poikansa olivat vartijoina Herran temppelin, telttapyhäkön, ovilla.'),
(1679553,58,13,9,24,'Ovenvartijat olivat asetetut neljälle ilmansuunnalle: idän, lännen, pohjoisen ja etelän puolelle.'),
(1679554,58,13,9,25,'Ja heidän veljiensä, jotka asuivat kylissään, oli aina määräaikoina seitsemäksi päiväksi tultava toimittamaan palvelusta yhdessä heidän kanssaan;'),
(1679555,58,13,9,26,'sillä ne neljä ylintä ovenvartijaa olivat pysyväisesti luottamustoimessaan. Nämä olivat leeviläiset. Heidän oli myöskin valvottava kammioita ja Jumalan temppelin aarteita,'),
(1679556,58,13,9,27,'ja he viettivät yönsä Jumalan temppelin ympärillä, sillä heidän tehtävänään oli vartioiminen ja heidän oli pidettävä huoli ovien avaamisesta joka aamu.'),
(1679557,58,13,9,28,'Muutamien heistä oli pidettävä huoli jumalanpalveluksessa tarvittavasta kalustosta, sillä heidän oli tuotava se sisään täysilukuisena ja vietävä se ulos täysilukuisena.'),
(1679558,58,13,9,29,'Ja muutamat heistä olivat määrätyt pitämään huolta kaluista, kaikista pyhistä kaluista, sekä lestyistä jauhoista, viinistä, öljystä, suitsukkeista ja hajuaineista.'),
(1679559,58,13,9,30,'Ja muutamat pappien pojista valmistivat voiteita hajuaineista.'),
(1679560,58,13,9,31,'Ja Mattitjalla, joka oli leeviläisiä ja oli koorahilaisen Sallumin esikoinen, oli luottamustoimena leivosten valmistaminen.'),
(1679561,58,13,9,32,'Ja muutamien kehatilaisista, heidän veljistään, oli pidettävä huoli näkyleivistä, valmistettava ne joka sapatiksi.'),
(1679562,58,13,9,33,'Mutta veisaajat, leeviläisten perhekuntain päämiehet, oleskelivat kammioissa, muusta palveluksesta vapaina, sillä he olivat toimessa sekä päivällä että yöllä.'),
(1679563,58,13,9,34,'He olivat leeviläisten perhekuntain päämiehiä, päämiehiä polveutumisensa mukaan; he asuivat Jerusalemissa.'),
(1679564,58,13,9,35,'Gibeonissa asuivat Gibeonin isä, jonka vaimon nimi oli Maaka,'),
(1679565,58,13,9,36,'hänen esikoispoikansa Abdon, sitten Suur, Kiis, Baal, Neer, Naadab,'),
(1679566,58,13,9,37,'Gedor, Ahjo, Sakarja ja Mikleot.'),
(1679567,58,13,9,38,'Ja Mikleotille syntyi Simeam. Hekin asuivat veljinensä Jerusalemissa, rajakkain veljiensä kanssa.'),
(1679568,58,13,9,39,'Ja Neerille syntyi Kiis, Kiisille syntyi Saul, ja Saulille syntyi Joonatan, Malkisua, Abinadab ja Esbaal.'),
(1679569,58,13,9,40,'Ja Joonatanin poika oli Meribbaal, ja Meribbaalille syntyi Miika.'),
(1679570,58,13,9,41,'Ja Miikan pojat olivat Piiton, Melek ja Tahrea.'),
(1679571,58,13,9,42,'Ja Aahaalle syntyi Jaera, Jaeralle syntyi Aalemet, Asmavet ja Simri. Ja Simrille syntyi Moosa,'),
(1679572,58,13,9,43,'ja Moosalle syntyi Binea; hänen poikansa oli Refaja, tämän poika Elasa ja tämän poika Aasel.'),
(1679573,58,13,9,44,'Ja Aaselilla oli kuusi poikaa, ja nämä ovat heidän nimensä: Asrikam, Bookeru, Jismael, Searja, Obadja ja Haanan. Nämä olivat Aaselin pojat.'),
(1679574,58,13,10,1,'Mutta filistealaiset taistelivat Israelia vastaan; ja Israelin miehet pakenivat filistealaisia, ja heitä kaatui surmattuina Gilboan vuorella.'),
(1679575,58,13,10,2,'Ja filistealaiset pääsivät Saulin ja hänen poikiensa kintereille, ja filistealaiset surmasivat Joonatanin, Abinadabin ja Malkisuan, Saulin pojat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679576,58,13,10,3,'Ja kun taistelu kiihtyi ankaraksi Saulia vastaan ja jousimiehet keksivät hänet, joutui hän hätään jousimiesten ahdistaessa.'),
(1679577,58,13,10,4,'Ja Saul sanoi aseenkantajallensa: "Paljasta miekkasi ja lävistä sillä minut, etteivät nuo ympärileikkaamattomat tulisi pitämään minua pilkkanaan". Mutta hänen aseenkantajansa ei tahtonut, sillä hän pelkäsi kovin. Niin Saul itse otti miekan ja heittäytyi siihen.'),
(1679578,58,13,10,5,'Mutta kun hänen aseenkantajansa näki, että Saul oli kuollut, heittäytyi hänkin miekkaansa ja kuoli.'),
(1679579,58,13,10,6,'Niin kuolivat Saul ja hänen kolme poikaansa ynnä koko hänen perheensä; he kuolivat yhdessä.'),
(1679580,58,13,10,7,'Ja kun kaikki Israelin miehet, jotka asuivat tasangolla, huomasivat, että he olivat paenneet ja että Saul poikinensa oli kuollut, jättivät he kaupunkinsa ja pakenivat, ja filistealaiset tulivat ja asettuivat niihin.'),
(1679581,58,13,10,8,'Seuraavana päivänä filistealaiset tulivat ryöstämään surmattuja ja löysivät Saulin ja hänen poikansa kaatuneina Gilboan vuorelta.'),
(1679582,58,13,10,9,'Niin he ryöstivät hänet ja ottivat hänen päänsä ja hänen aseensa ja lähettivät ne ympäri filistealaisten maata, julistaaksensa voitonsanomaa epäjumalillensa ja kansalle.'),
(1679583,58,13,10,10,'Ja he asettivat hänen aseensa jumalansa temppeliin, ja hänen pääkallonsa he kiinnittivät Daagonin temppeliin.'),
(1679584,58,13,10,11,'Kun koko Gileadin Jaabes kuuli, mitä kaikkea filistealaiset olivat tehneet Saulille,'),
(1679585,58,13,10,12,'nousivat he, kaikki asekuntoiset miehet, ja ottivat Saulin ja hänen poikainsa ruumiit ja toivat ne Jaabekseen. Sitten he hautasivat heidän luunsa tammen alle Jaabekseen ja paastosivat seitsemän päivää.'),
(1679586,58,13,10,13,'Niin kuoli Saul, koska hän oli ollut uskoton Herraa kohtaan eikä ollut ottanut vaaria Herran sanasta, ja myös sentähden, että hän oli kysynyt vainajahengeltä neuvoa,'),
(1679587,58,13,10,14,'mutta ei ollut kysynyt neuvoa Herralta. Sentähden Herra surmasi hänet ja siirsi kuninkuuden Daavidille, Iisain pojalle.'),
(1679588,58,13,11,1,'Sitten koko Israel kokoontui Daavidin tykö Hebroniin, ja he sanoivat: "Katso, me olemme sinun luutasi ja lihaasi.'),
(1679589,58,13,11,2,'Jo kauan sitten, Saulin vielä ollessa kuninkaana, sinä saatoit Israelin lähtemään ja tulemaan. Ja sinulle on Herra, sinun Jumalasi, sanonut: ''Sinä olet kaitseva minun kansaani Israelia, ja sinä olet oleva minun kansani Israelin ruhtinas''."'),
(1679590,58,13,11,3,'Ja kaikki Israelin vanhimmat tulivat kuninkaan tykö Hebroniin, ja Daavid teki heidän kanssaan liiton Hebronissa Herran edessä. Ja sitten he voitelivat Daavidin Israelin kuninkaaksi sen sanan mukaan, jonka Herra oli puhunut Samuelin kautta.'),
(1679591,58,13,11,4,'Ja Daavid ja koko Israel menivät Jerusalemiin, se on Jebukseen, ja siellä olivat jebusilaiset, jotka asuivat siinä maassa.'),
(1679592,58,13,11,5,'Jebuksen asukkaat sanoivat Daavidille: "Tänne sinä et tule". Mutta Daavid valloitti Siionin vuorilinnan, se on Daavidin kaupungin.'),
(1679593,58,13,11,6,'Ja Daavid sanoi: "Joka ensimmäisenä surmaa jebusilaisen, hän on oleva päämies ja päällikkö". Jooab, Serujan poika, tuli ensimmäisenä sinne ylös, ja niin hänestä tuli päämies.'),
(1679594,58,13,11,7,'Sitten Daavid asettui vuorilinnaan; sentähden kutsuttiin sitä Daavidin kaupungiksi.'),
(1679595,58,13,11,8,'Ja hän rakensi kaupunkia yltympäri, Millosta reunoihin asti; ja Jooab rakensi entiselleen muun osan kaupunkia.'),
(1679596,58,13,11,9,'Ja Daavid tuli yhä suuremmaksi, ja Herra Sebaot oli hänen kanssansa.'),
(1679597,58,13,11,10,'Nämä ovat ensimmäiset Daavidin urhoista, jotka voimakkaasti auttoivat häntä kuninkuuteen yhdessä koko Israelin kanssa, tehdäkseen hänet Israelin kuninkaaksi Herran sanan mukaan.'),
(1679598,58,13,11,11,'Tämä on Daavidin urhojen luettelo: Jaasobeam, hakmonilaisen poika, niiden kolmen päällikkö, hän, joka heilutti keihästään kolmensadan kaatuneen yli yhdellä kertaa.'),
(1679599,58,13,11,12,'Hänen jälkeensä Eleasar, Doodon poika, ahohilainen, yksi niistä kolmesta urhosta.'),
(1679600,58,13,11,13,'Hän oli Daavidin kanssa Pas-Dammimissa, kun filistealaiset olivat kokoontuneet sinne sotimaan. Ja siellä oli peltopalsta täynnä ohraa. Ja väki pakeni filistealaisia;'),
(1679601,58,13,11,14,'mutta he asettuivat keskelle palstaa, saivat sen pelastetuksi ja voittivat filistealaiset; ja niin Herra antoi suuren voiton.'),
(1679602,58,13,11,15,'Kerran lähti kolme niistä kolmestakymmenestä päälliköstä Daavidin luo kalliolinnaan, Adullamin luolalle. Ja filistealaisten joukko oli leiriytynyt Refaimin tasangolle.'),
(1679603,58,13,11,16,'Mutta Daavid oli silloin vuorilinnassa, ja filistealaisten vartiosto oli Beetlehemissä.'),
(1679604,58,13,11,17,'Ja Daavidin rupesi tekemään mieli vettä, ja hän sanoi: "Jospa joku toisi minulle vettä juodakseni Beetlehemin kaivosta, joka on portin edustalla!"'),
(1679605,58,13,11,18,'Silloin murtautuivat nämä kolme filistealaisten leirin läpi ja ammensivat vettä Beetlehemin kaivosta portin edustalta, kantoivat ja toivat sen Daavidille. Mutta Daavid ei tahtonut sitä juoda, vaan vuodatti sen juomauhriksi Herralle'),
(1679606,58,13,11,19,'ja sanoi: "Pois se! Jumala varjelkoon minut sitä tekemästä. Joisinko minä näiden miesten verta, heidän henkeänsä, sillä henkensä uhalla he toivat sen." Eikä hän tahtonut juoda sitä. Tämän tekivät ne kolme urhoa.'),
(1679607,58,13,11,20,'Absai, Jooabin veli, oli niiden kolmen päällikkö; hän heilutti keihästään kolmensadan kaatuneen yli. Ja hän oli kuulu niiden kolmen joukossa.'),
(1679608,58,13,11,21,'Hän oli kahdenkertaisessa arvossa pidetty niiden kolmen joukossa ja oli heidän päämiehensä, mutta hän ei vetänyt vertoja niille kolmelle.'),
(1679609,58,13,11,22,'Benaja, Joojadan poika, joka oli urhoollisen ja suurista teoistaan kuuluisan miehen poika, oli kotoisin Kabseelista. Hän surmasi ne kaksi mooabilaista sankaria, ja hän laskeutui alas ja tappoi lumituiskun aikana leijonan kaivoon.'),
(1679610,58,13,11,23,'Myöskin surmasi hän egyptiläisen miehen, sen suurikasvuisen, viittä kyynärää pitkän miehen. Egyptiläisellä oli kädessä keihäs, joka oli niinkuin kangastukki, mutta hän meni häntä vastaan ainoastaan sauva kädessä. Ja hän tempasi keihään egyptiläisen kädestä ja tappoi hänet hänen omalla keihäällään.'),
(1679611,58,13,11,24,'Tällaisia teki Benaja, Joojadan poika. Ja hän oli kuulu niiden kolmen urhon joukossa.'),
(1679612,58,13,11,25,'Hän oli arvossa pidetty niiden kolmenkymmenen joukossa, mutta hän ei vetänyt vertoja niille kolmelle. Ja Daavid asetti hänet henkivartiostonsa päälliköksi.'),
(1679613,58,13,11,26,'Sotaurhot olivat: Asael, Jooabin veli; Elhanan, Doodon poika, Beetlehemistä;'),
(1679614,58,13,11,27,'harorilainen Sammot; pelonilainen Heeles;'),
(1679615,58,13,11,28,'tekoalainen Iira, Ikkeksen poika; anatotilainen Abieser;'),
(1679616,58,13,11,29,'huusalainen Sibbekai; ahohilainen Iilai;'),
(1679617,58,13,11,30,'netofalainen Maharai; netofalainen Heeled, Baanan poika;'),
(1679618,58,13,11,31,'Iitai, Riibain poika, benjaminilaisten Gibeasta, piratonilainen Benaja;'),
(1679619,58,13,11,32,'Huurai Nahale-Gaasista; arabalainen Abiel;'),
(1679620,58,13,11,33,'baharumilainen Asmavet; saalbonilainen Eljahba;'),
(1679621,58,13,11,34,'gisonilainen Bene-Haasem; hararilainen Joonatan, Saagen poika;'),
(1679622,58,13,11,35,'hararilainen Abiam, Saakarin poika; Elifal, Uurin poika;'),
(1679623,58,13,11,36,'mekeralainen Heefer; pelonilainen Ahia;'),
(1679624,58,13,11,37,'karmelilainen Hesro; Naarai, Esbain poika;'),
(1679625,58,13,11,38,'Jooel, Naatanin veli; Mibhar, Hagrin poika;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679626,58,13,11,39,'ammonilainen Selek; beerotilainen Nahrai, Jooabin, Serujan pojan aseenkantaja;'),
(1679627,58,13,11,40,'jeteriläinen Iira; jeteriläinen Gaareb;'),
(1679628,58,13,11,41,'heettiläinen Uuria; Saabad, Ahlain poika;'),
(1679629,58,13,11,42,'ruubenilainen Adina, Siisan poika, ruubenilaisten päämies, ja hänen kanssaan kolmekymmentä muuta;'),
(1679630,58,13,11,43,'Haanan, Maakan poika, ja mitniläinen Joosafat;'),
(1679631,58,13,11,44,'astarotilainen Ussia; Saama ja Jegiel, aroerilaisen Hootamin pojat;'),
(1679632,58,13,11,45,'Jediael, Simrin poika, ja hänen veljensä Jooha, tiisiläinen;'),
(1679633,58,13,11,46,'Eliel-Mahavim sekä Jeribai ja Joosavja, Elnaamin pojat, ja mooabilainen Jitma;'),
(1679634,58,13,11,47,'Eliel, Oobed ja Jaasiel-Mesobaja.'),
(1679635,58,13,12,1,'Ja nämä olivat ne, jotka tulivat Daavidin luo Siklagiin, kun hän vielä piileskeli Saulia, Kiisin poikaa; ja he olivat niitä urhoja, jotka auttoivat häntä sodassa.'),
(1679636,58,13,12,2,'He olivat asestetut jousella ja taitavia sekä oikealla että vasemmalla kädellä linkoamaan kiviä ja ampumaan jousella nuolia. Saulin heimolaisia, benjaminilaisia:'),
(1679637,58,13,12,3,'Ahieser, päämies, ja Jooas, gibealaisen Hassemaan pojat; Jesiel ja Pelet, Asmavetin pojat; Beraka; anatotilainen Jeehu;'),
(1679638,58,13,12,4,'gibeonilainen Jismaja, urho niiden kolmenkymmenen joukossa ja niiden kolmenkymmenen päällikkö; Jeremia; Jahasiel; Joohanan; gederalainen Joosabad;'),
(1679639,58,13,12,5,'Elusai; Jerimot; Bealja; Semarja; harufilainen Sefatja;'),
(1679640,58,13,12,6,'koorahilaiset Elkana, Jissia, Asarel, Jooeser ja Jaasobeam;'),
(1679641,58,13,12,7,'Jooela ja Sebadja, Jerohamin pojat, Gedorista.'),
(1679642,58,13,12,8,'Gaadilaisista meni Daavidin puolelle vuorilinnaan, erämaahan, sotaurhoja, sotakelpoisia miehiä, kilpeä ja keihästä käyttäviä, jotka olivat näöltään kuin leijonat ja nopeat kuin gasellit vuorilla:'),
(1679643,58,13,12,9,'Eeser, päämies Obadja toinen, Eliab kolmas,'),
(1679644,58,13,12,10,'Masmanna neljäs, Jeremia viides,'),
(1679645,58,13,12,11,'Attai kuudes, Eliel seitsemäs,'),
(1679646,58,13,12,12,'Joohanan kahdeksas, Elsabad yhdeksäs,'),
(1679647,58,13,12,13,'Jeremia kymmenes, Makbannai yhdestoista.'),
(1679648,58,13,12,14,'Nämä olivat gaadilaisia, sotajoukon päälliköitä, pienin sadan, suurin tuhannen miehen veroinen.'),
(1679649,58,13,12,15,'Nämä olivat ne, jotka ensimmäisessä kuussa menivät Jordanin poikki, kun se tulvi yli kaikkien äyräittensä, ja jotka karkoittivat kaikki tasangoilla-asujat itään ja länteen.'),
(1679650,58,13,12,16,'Myöskin benjaminilaisia ja Juudan miehiä tuli Daavidin vuorilinnaan.'),
(1679651,58,13,12,17,'Silloin Daavid meni heitä vastaan, lausui ja sanoi heille: "Jos te tulette minun luokseni rauha mielessä, auttaaksenne minua, niin minun sydämeni yhtyy teihin; mutta jos te tulette kavaltamaan minua vihollisilleni, vaikkei väkivalta minun käsiäni tahraa, niin nähköön meidän isiemme Jumala sen ja rangaiskoon".'),
(1679652,58,13,12,18,'Mutta henki täytti Amasain, niiden kolmenkymmenen päällikön, ja hän sanoi: "Sinun me olemme, Daavid, ja sinun puolellasi olemme, sinä Iisain poika. Rauha, rauha sinulle, ja rauha sinun auttajillesi, sillä sinun Jumalasi auttoi sinua!" Niin Daavid otti heidät vastaan ja asetti heidät partiojoukon päälliköiksi.'),
(1679653,58,13,12,19,'Manassesta siirtyi muutamia Daavidin puolelle, kun hän filistealaisten kanssa meni taistelemaan Saulia vastaan, vaikkeivät he joutuneetkaan auttamaan näitä, sillä filistealaisten ruhtinaat neuvoteltuaan lähettivät hänet pois sanoen: "Hän voisi meidän päämme menoksi siirtyä herransa Saulin puolelle".'),
(1679654,58,13,12,20,'Kun hän siis lähti Siklagiin, siirtyivät hänen puolelleen Manassesta: Adna, Joosabad, Jediael, Miikael, Joosabad, Elihu ja Silletai, tuhannenpäämiehet Manassesta.'),
(1679655,58,13,12,21,'Ja nämä auttoivat Daavidia rosvojoukkoa vastaan, sillä he olivat kaikki sotaurhoja, ja heistä tuli sotajoukon päälliköitä.'),
(1679656,58,13,12,22,'Sillä joka päivä tuli väkeä Daavidin luo auttamaan häntä, kunnes joukko oli suuri kuin Jumalan joukko.'),
(1679657,58,13,12,23,'Ja tämä on sotaan varustetun aseväen lukumäärä, niitten, jotka tulivat Daavidin luo Hebroniin siirtääkseen Saulin kuninkuuden hänelle Herran käskyn mukaan:'),
(1679658,58,13,12,24,'Juudan miehiä, jotka kantoivat kilpeä ja keihästä, kuusituhatta kahdeksansataa, sotaan varustettua;'),
(1679659,58,13,12,25,'simeonilaisia, sotataitoisia urhoja, seitsemäntuhatta sata;'),
(1679660,58,13,12,26,'leeviläisiä neljätuhatta kuusisataa,'),
(1679661,58,13,12,27,'sekä Joojada, Aaronin suvun ruhtinas, ynnä kolmetuhatta seitsemänsataa hänen kanssaan;'),
(1679662,58,13,12,28,'ja Saadok, nuorukainen, sotaurho, perhekuntinensa, kaksikymmentä kaksi päällikköä;'),
(1679663,58,13,12,29,'benjaminilaisia, Saulin veljiä, kolmetuhatta, sillä vielä siihen aikaan suurin osa heistä palveli uskollisesti Saulin sukua;'),
(1679664,58,13,12,30,'efraimilaisia kaksikymmentä tuhatta kahdeksansataa, sotaurhoja, kuuluisia miehiä perhekunnissaan;'),
(1679665,58,13,12,31,'toisesta puolesta Manassen sukukuntaa kahdeksantoista tuhatta, jotka olivat nimeltä mainitut menemään ja tekemään Daavidin kuninkaaksi;'),
(1679666,58,13,12,32,'isaskarilaisia, jotka ymmärsivät ajan ja käsittivät, mitä Israelin oli tehtävä, kaksisataa päämiestä, ja kaikki heidän veljensä heidän johdollansa;'),
(1679667,58,13,12,33,'Sebulonista sotakelpoisia miehiä, kaikkinaisilla sota-aseilla sotaan varustettuja, viisikymmentä tuhatta, yksimielisiä sotarintaan järjestymään;'),
(1679668,58,13,12,34,'Naftalista tuhat päällikköä, ja heidän kanssansa kolmekymmentäseitsemäntuhatta kilvellä ja keihäällä varustettua miestä;'),
(1679669,58,13,12,35,'daanilaisia kaksikymmentäkahdeksan tuhatta kuusisataa sotaan varustettua miestä;'),
(1679670,58,13,12,36,'Asserista sotakelpoisia miehiä, taisteluun valmiita, neljäkymmentä tuhatta;'),
(1679671,58,13,12,37,'tuolta puolelta Jordanin, ruubenilaisia, gaadilaisia ja manasselaisia sukukunnan toisesta puolesta, satakaksikymmentä tuhatta, kaikkinaisilla sota-aseilla varustettuja.'),
(1679672,58,13,12,38,'Kaikki nämä sotilaat, sotarintaan järjestyneinä, tulivat ehyellä sydämen halulla Hebroniin tehdäkseen Daavidin koko Israelin kuninkaaksi. Myöskin koko muu Israel oli yksimielinen tehdäkseen Daavidin kuninkaaksi.'),
(1679673,58,13,12,39,'Ja he olivat siellä Daavidin luona kolme päivää ja söivät ja joivat, sillä heidän heimolaisensa olivat evästäneet heidät.'),
(1679674,58,13,12,40,'Nekin, jotka asuivat lähellä heitä, aina Isaskariin, Sebuloniin ja Naftaliin saakka, toivat aasien, kamelien, muulien ja härkien selässä ruokatavaraa: jauhoja, viikunakakkuja ja rusinakakkuja, viiniä ja öljyä, raavaita ja pikkukarjaa viljalti; sillä Israelissa oli ilo.'),
(1679675,58,13,13,1,'Ja Daavid neuvotteli tuhannen- ja sadanpäämiesten, kaikkien ruhtinasten, kanssa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679676,58,13,13,2,'Ja Daavid sanoi kaikelle Israelin seurakunnalle: "Jos se on teistä hyvä ja jos se tulee Herralta, meidän Jumalaltamme, niin lähettäkäämme joka taholle sana veljillemme, jotka ovat jääneet kaikkiin Israelin maakuntiin, ja papeille ja leeviläisille, jotka asuvat heidän luonaan laidunmaittensa kaupungeissa, että he kokoontuvat meidän luoksemme,'),
(1679677,58,13,13,3,'ja siirtäkäämme Jumalamme arkki luoksemme, sillä Saulin päivinä emme siitä välittäneet".'),
(1679678,58,13,13,4,'Silloin koko seurakunta vastasi, että niin oli tehtävä, sillä se oli oikein koko kansan silmissä.'),
(1679679,58,13,13,5,'Niin Daavid kokosi kaiken Israelin, aina Egyptin Siihorista asti ja aina sieltä, mistä mennään Hamatiin, tuomaan Jumalan arkkia Kirjat-Jearimista.'),
(1679680,58,13,13,6,'Ja Daavid ja koko Israel meni Baalatiin, Kirjat-Jearimiin, joka on Juudassa, tuomaan sieltä Jumalan arkkia, jonka Herra oli ottanut nimiinsä, hän, jonka istuinta kerubit kannattavat.'),
(1679681,58,13,13,7,'Ja he panivat Jumalan arkin uusiin vaunuihin ja veivät sen pois Abinadabin talosta, ja Ussa ja Ahjo ohjasivat vaunuja.'),
(1679682,58,13,13,8,'Ja Daavid ynnä koko Israel karkeloi kaikin voimin Jumalan edessä laulaen sekä soittaen kanteleita, harppuja, vaskirumpuja, kymbaaleja ja torvia.'),
(1679683,58,13,13,9,'Mutta kun he tulivat Kiidonin puimatantereen luo, ojensi Ussa kätensä tarttuaksensa arkkiin, sillä härät kompastuivat.'),
(1679684,58,13,13,10,'Silloin Herran viha syttyi Ussaa kohtaan, ja hän löi hänet sentähden, että hän oli ojentanut kätensä arkkiin, ja niin hän kuoli siihen, Jumalan eteen.'),
(1679685,58,13,13,11,'Mutta Daavid pahastui siitä, että Herra niin oli murtanut Ussan. Siitä sen paikan nimenä on Peres-Ussa vielä tänäkin päivänä.'),
(1679686,58,13,13,12,'Ja Daavid pelkäsi sinä päivänä Jumalaa, niin että hän sanoi: "Kuinka minä voin tuoda Jumalan arkin tyköni?"'),
(1679687,58,13,13,13,'Eikä Daavid siirtänyt arkkia luoksensa Daavidin kaupunkiin, vaan hän toimitti sen syrjään gatilaisen Oobed-Edomin taloon.'),
(1679688,58,13,13,14,'Ja Jumalan arkki jäi kolmeksi kuukaudeksi Oobed-Edomin talon luo omaan majaansa. Ja Herra siunasi Oobed-Edomin taloa ja kaikkea, mitä hänellä oli.'),
(1679689,58,13,14,1,'Hiiram, Tyyron kuningas, lähetti sanansaattajat Daavidin luo, sekä setripuita ja puuseppiä ja kivenhakkaajia rakentamaan hänelle linnaa.'),
(1679690,58,13,14,2,'Ja Daavid ymmärsi, että Herra oli vahvistanut hänet Israelin kuninkaaksi, koska hänen kuninkuutensa oli korotettu korkealle Herran kansan Israelin tähden.'),
(1679691,58,13,14,3,'Jerusalemissa Daavid vielä otti vaimoja, ja Daavidille syntyi vielä poikia ja tyttäriä.'),
(1679692,58,13,14,4,'Ja nämä ovat niiden poikien nimet, jotka syntyivät hänelle Jerusalemissa: Sammua, Soobab, Naatan, Salomo,'),
(1679693,58,13,14,5,'Jibhar, Elisua, Elpelet,'),
(1679694,58,13,14,6,'Noogah, Nefeg, Jaafia,'),
(1679695,58,13,14,7,'Elisama, Beeljada ja Elifelet.'),
(1679696,58,13,14,8,'Mutta kun filistealaiset kuulivat, että Daavid oli voideltu koko Israelin kuninkaaksi, lähtivät kaikki filistealaiset etsimään Daavidia. Kun Daavid sen kuuli, lähti hän heitä vastaan.'),
(1679697,58,13,14,9,'Kun filistealaiset olivat tulleet ja tehneet ryöstöretken Refaimin tasangolle,'),
(1679698,58,13,14,10,'kysyi Daavid Jumalalta: "Menenkö minä filistealaisia vastaan, ja annatko sinä heidät minun käsiini?" Ja Herra sanoi hänelle: "Mene; minä annan heidät sinun käsiisi".'),
(1679699,58,13,14,11,'Niin he menivät Baal-Perasimiin, ja siellä Daavid voitti heidät. Ja Daavid sanoi: "Jumala on murtanut viholliseni minun kädelläni, niinkuin vedet murtavat". Siitä sen paikan nimeksi tuli Baal-Perasim.'),
(1679700,58,13,14,12,'He jättivät siihen jumalansa, ja Daavid käski polttaa ne tulessa.'),
(1679701,58,13,14,13,'Mutta filistealaiset tekivät vielä kerran ryöstöretken tasangolle.'),
(1679702,58,13,14,14,'Niin Daavid kysyi taas Jumalalta, ja Jumala vastasi hänelle: "Älä mene heidän jälkeensä, vaan kierrä heidät ja hyökkää heidän kimppuunsa balsamipuiden puolelta.'),
(1679703,58,13,14,15,'Ja kun kuulet astunnan kahinan balsamipuiden latvoista, niin käy taisteluun, sillä Jumala on käynyt sinun edelläsi tuhotakseen filistealaisten leirin."'),
(1679704,58,13,14,16,'Daavid teki, niinkuin Jumala oli häntä käskenyt, ja niin he voittivat filistealaisten sotajoukon ja ajoivat heitä takaa Gibeonista aina Geseriin saakka.'),
(1679705,58,13,14,17,'Niin Daavidin maine levisi kaikkiin maihin, ja Herra nosti kaikissa kansoissa pelon häntä kohtaan.'),
(1679706,58,13,15,1,'Ja hän rakensi itsellensä taloja Daavidin kaupunkiin ja valmisti paikan Jumalan arkille ja pystytti sille majan.'),
(1679707,58,13,15,2,'Silloin Daavid käski: "Älkööt muut kuin leeviläiset kantako Jumalan arkkia; sillä heidät on Herra valinnut kantamaan Jumalan arkkia ja palvelemaan häntä ikuisesti".'),
(1679708,58,13,15,3,'Ja Daavid kokosi kaiken Israelin Jerusalemiin, tuomaan Herran arkkia siihen paikkaan, jonka hän oli sille valmistanut.'),
(1679709,58,13,15,4,'Daavid kokosi Aaronin jälkeläiset ja leeviläiset;'),
(1679710,58,13,15,5,'Kehatin jälkeläisistä: Uurielin, päämiehen, ja hänen veljensä, sata kaksikymmentä;'),
(1679711,58,13,15,6,'Merarin jälkeläisistä: Asajan, päämiehen, ja hänen veljensä, kaksisataa kaksikymmentä;'),
(1679712,58,13,15,7,'Geersomin jälkeläisistä: Jooelin, päämiehen, ja hänen veljensä, sata kolmekymmentä;'),
(1679713,58,13,15,8,'Elisafanin jälkeläisistä: Semajan, päämiehen, ja hänen veljensä, kaksisataa;'),
(1679714,58,13,15,9,'Hebronin jälkeläisistä: Elielin, päämiehen, ja hänen veljensä, kahdeksankymmentä;'),
(1679715,58,13,15,10,'Ussielin jälkeläisistä: Amminadabin, päämiehen, ja hänen veljensä, sata kaksitoista.'),
(1679716,58,13,15,11,'Ja Daavid kutsui papit Saadokin ja Ebjatarin sekä leeviläiset Uurielin, Asajan, Jooelin, Semajan, Elielin ja Amminadabin'),
(1679717,58,13,15,12,'ja sanoi heille: "Te olette leeviläisten perhekuntien päämiehet. Pyhittäkää itsenne ja veljenne ja tuokaa Herran, Israelin Jumalan, arkki siihen paikkaan, jonka minä olen sille valmistanut.'),
(1679718,58,13,15,13,'Sillä sentähden, ettette ensimmäisellä kerralla olleet läsnä, mursi Herra, meidän Jumalamme, meidät; sillä me emme etsineet häntä, niinkuin olisi pitänyt."'),
(1679719,58,13,15,14,'Silloin papit ja leeviläiset pyhittäytyivät tuomaan Herran, Israelin Jumalan, arkkia.'),
(1679720,58,13,15,15,'Ja leeviläiset kantoivat Jumalan arkkia korennoilla olallansa, niinkuin Mooses oli Herran sanan mukaan käskenyt.'),
(1679721,58,13,15,16,'Ja Daavid käski leeviläisten päämiesten asettaa veljensä, veisaajat, soittimilla, harpuilla, kanteleilla ja kymbaaleilla kaiuttamaan riemuvirsiä.'),
(1679722,58,13,15,17,'Niin leeviläiset asettivat soittamaan Heemanin, Jooelin pojan, ja hänen heimolaisistaan Aasafin, Berekjan pojan, ja heidän heimolaisistaan, Merarin jälkeläisistä, Eetanin, Kuusajan pojan,'),
(1679723,58,13,15,18,'ja heidän kanssaan heidän arvossa lähinnä olevista heimolaisistaan: Sakarjan, Benin ja Jaasielin, Semiramotin, Jehielin, Unnin, Eliabin, Benajan, Maasejan, Mattitjan, Elifelehun, Miknejan, Oobed-Edomin ja Jegielin, ovenvartijat.'),
(1679724,58,13,15,19,'Ja veisaajista oli Heemanin, Aasafin ja Eetanin soitettava vaskikymbaaleilla,'),
(1679725,58,13,15,20,'Sakarjan, Ussielin, Semiramotin, Jehielin, Unnin, Eliabin, Maasejan ja Benajan harpuilla korkeassa äänialassa,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679726,58,13,15,21,'Mattitjan, Elifelehun, Miknejan, Oobed-Edomin, Jegielin ja Asasjan kanteleilla matalassa äänialassa, veisuuta johtaaksensa.'),
(1679727,58,13,15,22,'Kenanja, leeviläisten johtaja kantajatehtävässä, valvoi kantamista, sillä hän oli taitava siihen.'),
(1679728,58,13,15,23,'Berekja ja Elkana olivat arkin ovenvartijat.'),
(1679729,58,13,15,24,'Ja papit Sebanja, Joosafat, Netanel, Amasai, Sakarja, Benaja ja Elieser puhalsivat torviin Jumalan arkin edellä, ja Oobed-Edom ja Jehia olivat arkin ovenvartijat.'),
(1679730,58,13,15,25,'Sitten Daavid, Israelin vanhimmat ja tuhannenpäämiehet menivät ja toivat riemuiten Herran liitonarkin Oobed-Edomin talosta.'),
(1679731,58,13,15,26,'Ja kun Jumala auttoi leeviläisiä, jotka kantoivat Herran liitonarkkia, uhrattiin seitsemän härkää ja seitsemän oinasta.'),
(1679732,58,13,15,27,'Daavid oli puettu hienosta pellavakankaasta tehtyyn viittaan ja samoin kaikki leeviläiset, jotka kantoivat arkkia, sekä veisaajat ja kantamisen johtaja Kenanja veisaajain kanssa; ja Daavidilla oli yllään pellavakasukka.'),
(1679733,58,13,15,28,'Niin koko Israel toi Herran liitonarkin riemun raikuessa ja pasunain pauhatessa, torvien, kymbaalien, harppujen ja kannelten soidessa.'),
(1679734,58,13,15,29,'Kun Herran liitonarkki tuli Daavidin kaupunkiin, katseli Miikal, Saulin tytär, ikkunasta, ja nähdessään kuningas Daavidin hyppivän ja karkeloivan halveksi hän häntä sydämessään.'),
(1679735,58,13,16,1,'Kun he olivat tuoneet Jumalan arkin ja asettaneet sen majaan, jonka Daavid oli sille pystyttänyt, uhrasivat he polttouhreja ja yhteysuhreja Jumalan edessä.'),
(1679736,58,13,16,2,'Ja kun Daavid oli uhrannut polttouhrin ja yhteysuhrit, siunasi hän kansan Herran nimeen.'),
(1679737,58,13,16,3,'Ja hän jakoi kaikille israelilaisille, sekä miehille että naisille, kullekin leipäkakun, kappaleen lihaa ja rypälekakun.'),
(1679738,58,13,16,4,'Ja hän asetti Herran arkin eteen leeviläisiä palvelemaan ja kunnioittamaan, kiittämään ja ylistämään Herraa, Israelin Jumalaa:'),
(1679739,58,13,16,5,'Aasafin johtajaksi, toiseksi Sakarjan, sitten Jegielin, Semiramotin, Jehielin, Mattitjan, Eliabin, Benajan, Oobed-Edomin ja Jegielin soittamaan harpuilla ja kanteleilla, Aasafin helistäessä kymbaaleja'),
(1679740,58,13,16,6,'ja pappien, Benajan ja Jahasielin, soittaessa yhtämittaa torvia Jumalan liitonarkin edessä.'),
(1679741,58,13,16,7,'Silloin, sinä päivänä, ensi kerran Daavid asetti Aasafin ja hänen veljensä kiittämään Herraa näin:'),
(1679742,58,13,16,8,'"Kiittäkää Herraa, julistakaa hänen nimeänsä, tehkää hänen suuret tekonsa tiettäviksi kansojen keskuudessa.'),
(1679743,58,13,16,9,'Laulakaa hänelle, veisatkaa hänelle, puhukaa kaikista hänen ihmeistänsä.'),
(1679744,58,13,16,10,'Hänen pyhä nimensä olkoon teidän kerskauksenne; iloitkoon niiden sydän, jotka etsivät Herraa.'),
(1679745,58,13,16,11,'Kysykää Herraa ja hänen voimaansa, etsikää alati hänen kasvojansa.'),
(1679746,58,13,16,12,'Muistakaa hänen ihmetöitänsä, jotka hän on tehnyt, hänen ihmeitänsä ja hänen suunsa tuomioita,'),
(1679747,58,13,16,13,'te Israelin, hänen palvelijansa, siemen, Jaakobin lapset, te hänen valittunsa.'),
(1679748,58,13,16,14,'Hän, Herra, on meidän Jumalamme; hänen tuomionsa käyvät yli kaiken maan.'),
(1679749,58,13,16,15,'Muistakaa hänen liittonsa iankaikkisesti, hamaan tuhansiin polviin, sana, jonka hän on säätänyt,'),
(1679750,58,13,16,16,'liitto, jonka hän teki Aabrahamin kanssa, ja hänen lisakille vannomansa vala.'),
(1679751,58,13,16,17,'Hän vahvisti sen käskyksi Jaakobille, Israelille iankaikkiseksi liitoksi.'),
(1679752,58,13,16,18,'Hän sanoi: ''Sinulle minä annan Kanaanin maan, se olkoon teidän perintöosanne''.'),
(1679753,58,13,16,19,'Teitä oli vähäinen joukko, vain harvoja, ja te olitte muukalaisia siellä.'),
(1679754,58,13,16,20,'Ja he vaelsivat kansasta kansaan ja yhdestä valtakunnasta toiseen kansaan.'),
(1679755,58,13,16,21,'Hän ei sallinut kenenkään heitä vahingoittaa, ja hän rankaisi kuninkaita heidän tähtensä:'),
(1679756,58,13,16,22,'''Älkää koskeko minun voideltuihini, älkää tehkö pahaa minun profeetoilleni''.'),
(1679757,58,13,16,23,'Veisatkaa Herralle, kaikki maa, julistakaa päivästä päivään hänen pelastustekojansa.'),
(1679758,58,13,16,24,'Ilmoittakaa pakanain seassa hänen kunniaansa, hänen ihmeitänsä kaikkien kansojen seassa.'),
(1679759,58,13,16,25,'Sillä Herra on suuri ja sangen ylistettävä, hän on peljättävä yli kaikkien jumalain.'),
(1679760,58,13,16,26,'Sillä kaikki kansojen jumalat ovat epäjumalia, mutta Herra on tehnyt taivaat.'),
(1679761,58,13,16,27,'Kirkkaus ja kunnia on hänen kasvojensa edessä, väkevyys ja riemu hänen asuinsijassaan.'),
(1679762,58,13,16,28,'Antakaa Herralle, te kansojen sukukunnat, antakaa Herralle kunnia ja väkevyys.'),
(1679763,58,13,16,29,'Antakaa Herralle hänen nimensä kunnia, tuokaa lahjoja ja tulkaa hänen kasvojensa eteen, kumartakaa Herraa pyhässä kaunistuksessa.'),
(1679764,58,13,16,30,'Vaviskaa hänen kasvojensa edessä, kaikki maa. Maan piiri pysyy lujana, se ei horju.'),
(1679765,58,13,16,31,'Iloitkoot taivaat, ja riemuitkoon maa; ja sanottakoon pakanain seassa: ''Herra on kuningas!'''),
(1679766,58,13,16,32,'Pauhatkoon meri ja kaikki, mitä siinä on; ihastukoot kedot ja kaikki, mitä niissä on,'),
(1679767,58,13,16,33,'riemuitkoot silloin metsän puut Herran edessä, sillä hän tulee tuomitsemaan maata.'),
(1679768,58,13,16,34,'Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.'),
(1679769,58,13,16,35,'Ja sanokaa: ''Pelasta meidät, sinä pelastuksemme Jumala, kokoa ja vapahda meidät pakanain seasta, että me kiittäisimme sinun pyhää nimeäsi ja kerskaisimme sinun ylistyksestäsi''.'),
(1679770,58,13,16,36,'Ylistetty olkoon Herra, Israelin Jumala, iankaikkisesta iankaikkiseen." Ja kaikki kansa sanoi: "Amen", ja ylisti Herraa.'),
(1679771,58,13,16,37,'Ja hän asetti Aasafin ja hänen veljensä sinne Herran liitonarkin eteen tekemään vakituista palvelusta arkin edessä, kunakin päivänä sen päivän palveluksen,'),
(1679772,58,13,16,38,'mutta Oobed-Edomin ja heidän veljensä, yhteensä kuusikymmentä kahdeksan, nimittäin Oobed-Edomin, Jeditunin pojan, ja Hoosan, ovenvartijoiksi.'),
(1679773,58,13,16,39,'Ja pappi Saadokin ja hänen veljensä, papit, hän asetti Herran asumuksen eteen, uhrikukkulalle, joka on Gibeonissa,'),
(1679774,58,13,16,40,'uhraamaan polttouhreja Herralle polttouhrialttarilla, aina aamuin ja illoin, kaikki niinkuin on kirjoitettuna Herran laissa, jonka hän on antanut Israelille.'),
(1679775,58,13,16,41,'Ja heidän kanssaan olivat Heeman ja Jedutun ynnä muut valitut, nimeltä mainitut, kiittämässä Herraa siitä, että hänen armonsa pysyy iankaikkisesti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679776,58,13,16,42,'Näiden, Heemanin ja Jedutunin, hallussa oli torvet ja kymbaalit soittajia varten ynnä muut soittimet Jumalan virttä varten. Ja Jedutunin pojat vartioivat ovia.'),
(1679777,58,13,16,43,'Sitten kaikki kansa lähti kukin kotiinsa, ja Daavid kääntyi takaisin tervehtimään perhettänsä.'),
(1679778,58,13,17,1,'Kerran, kun Daavid istui linnassansa, sanoi Daavid profeetta Naatanille: "Katso, minä asun setripuisessa palatsissa, mutta Herran liitonarkki on telttakankaan alla". Naatan sanoi Daavidille:'),
(1679779,58,13,17,2,'"Tee vain kaikki, mitä mielessäsi on, sillä Jumala on sinun kanssasi".'),
(1679780,58,13,17,3,'Mutta sinä yönä tapahtui, että Naatanille tuli tämä Jumalan sana:'),
(1679781,58,13,17,4,'"Mene ja sano minun palvelijalleni Daavidille: Näin sanoo Herra: Et sinä ole rakentava minulle huonetta asuakseni.'),
(1679782,58,13,17,5,'Minä en ole asunut huoneessa siitä päivästä asti, jona johdatin Israelin tänne, tähän päivään saakka, vaan minä olen muuttanut teltasta telttaan ja asumuksesta asumukseen.'),
(1679783,58,13,17,6,'Olenko minä koskaan, missä olenkin vaeltanut kaikessa Israelissa, kenellekään Israelin tuomareista, joita olen asettanut kaitsemaan kansaani, sanonut näin: Miksi ette ole rakentaneet minulle setripuista huonetta?'),
(1679784,58,13,17,7,'Sano siis minun palvelijalleni Daavidille: Näin sanoo Herra Sebaot: Minä olen ottanut sinut laitumelta, lammasten jäljestä, kansani Israelin ruhtinaaksi.'),
(1679785,58,13,17,8,'Ja minä olen ollut sinun kanssasi kaikkialla, missä sinä vaelsit, ja olen hävittänyt kaikki vihollisesi sinun tieltäsi. Ja minä teen sinulle nimen, suurimpien nimien vertaisen maan päällä.'),
(1679786,58,13,17,9,'Ja minä valmistan sijan kansalleni Israelille ja istutan sen niin, että se asuu paikallansa eikä enää ole levoton eivätkä vääryyden tekijät sitä enää vaivaa niinkuin ennen,'),
(1679787,58,13,17,10,'siitä ajasta saakka, jolloin minä asetin tuomareita kansalleni Israelille. Ja minä nöyryytän kaikki sinun vihollisesi. Ja minä ilmoitan sinulle, että Herra on rakentava sinulle huoneen.'),
(1679788,58,13,17,11,'Kun sinun päiväsi ovat päättyneet ja sinä lähdet isiesi tykö, korotan minä sinun seuraajaksesi jälkeläisesi, joka on yksi sinun pojistasi; ja minä vahvistan hänen kuninkuutensa.'),
(1679789,58,13,17,12,'Hän on rakentava minulle huoneen, ja minä vahvistan hänen valtaistuimensa ikuisiksi ajoiksi.'),
(1679790,58,13,17,13,'Minä olen oleva hänen isänsä, ja hän on oleva minun poikani; ja armoani minä en ota häneltä pois, niinkuin otin siltä, joka oli sinun edelläsi.'),
(1679791,58,13,17,14,'Ja minä pidän hänet pystyssä huoneessani ja valtakunnassani iäti, ja hänen valtaistuimensa on oleva iäti vahva."'),
(1679792,58,13,17,15,'Aivan näillä sanoilla ja tämän näyn mukaan Naatan puhui Daavidille.'),
(1679793,58,13,17,16,'Niin kuningas Daavid meni ja asettui Herran eteen ja sanoi: "Mikä olen minä, Herra Jumala, ja mikä on minun sukuni, että olet saattanut minut tähän asti?'),
(1679794,58,13,17,17,'Mutta tämäkin on ollut vähän sinun silmissäsi, Jumala, ja niin sinä olet puhunut palvelijasi suvulle myöskin kaukaisista asioista ja olet nähnyt minut nousevina ihmispolvina, Herra Jumala.'),
(1679795,58,13,17,18,'Mitä Daavid enää sinulle puhuisi kunniasta, jota olet osoittanut palvelijallesi? Sinähän tunnet palvelijasi.'),
(1679796,58,13,17,19,'Herra, palvelijasi tähden ja oman mielesi mukaan sinä olet tehnyt kaiken tämän suuren ja ilmoittanut kaikki nämä suuret asiat.'),
(1679797,58,13,17,20,'Herra, kaiken sen mukaan, mitä me olemme korvillamme kuulleet, ei ole sinun vertaistasi, eikä ole muuta jumalaa kuin sinä.'),
(1679798,58,13,17,21,'Ja missä on maan päällä toista kansaa sinun kansasi Israelin vertaista, jota Jumala itse on käynyt lunastamaan kansaksensa, ja niin sinä olet tehnyt itsellesi suuren ja peljättävän nimen karkoittamalla pakanat kansasi tieltä, jonka sinä Egyptistä lunastit.'),
(1679799,58,13,17,22,'Ja sinä olet asettanut kansasi Israelin omaksi kansaksesi ikuisiksi ajoiksi, ja sinä, Herra, olet tullut heidän Jumalaksensa.'),
(1679800,58,13,17,23,'Niin olkoon nyt, Herra, se sana, jonka sinä olet puhunut palvelijastasi ja hänen suvustansa, vahva ikuisiksi ajoiksi. Tee, niinkuin olet puhunut.'),
(1679801,58,13,17,24,'Silloin sinun nimesi on oleva vahva ja tuleva suureksi ikuisiksi ajoiksi, ja se on oleva: Herra Sebaot, Israelin Jumala, Jumala Israelissa. Ja palvelijasi Daavidin suku on pysyvä sinun edessäsi.'),
(1679802,58,13,17,25,'Sillä sinä, minun Jumalani, olet ilmoittanut palvelijallesi rakentavasi hänelle huoneen. Siitä palvelijasi on saanut rohkeuden rukoilla sinun edessäsi.'),
(1679803,58,13,17,26,'Ja nyt, Herra, sinä olet Jumala; ja kun olet luvannut palvelijallesi tämän hyvän,'),
(1679804,58,13,17,27,'niin suvaitse nyt siunata palvelijasi sukua, että se pysyisi iäti sinun edessäsi. Sillä mitä sinä, Herra, siunaat, se on oleva siunattu iäti."'),
(1679805,58,13,18,1,'Sen jälkeen Daavid voitti filistealaiset ja nöyryytti heidät; ja hän otti Gatin ja sen tytärkaupungit filistealaisten käsistä.'),
(1679806,58,13,18,2,'Hän voitti myös mooabilaiset, ja niin mooabilaiset tulivat Daavidin veronalaisiksi palvelijoiksi.'),
(1679807,58,13,18,3,'Samoin Daavid voitti Hadareserin, Sooban kuninkaan, Hamatin suunnalla, kun tämä oli menossa lujittamaan valtaansa Eufrat-virran rannoille.'),
(1679808,58,13,18,4,'Ja Daavid otti häneltä tuhat vaunuhevosta, seitsemäntuhatta ratsumiestä ja kaksikymmentä tuhatta jalkamiestä, ja Daavid katkoi kaikilta vaunuhevosilta vuohisjänteet; ainoastaan sata vaunuhevosta hän niistä säästi.'),
(1679809,58,13,18,5,'Ja kun Damaskon aramilaiset tulivat auttamaan Hadareseria, Sooban kuningasta, voitti Daavid kaksikymmentäkaksi tuhatta aramilaista.'),
(1679810,58,13,18,6,'Ja Daavid asetti maaherroja Damaskon Aramiin; ja aramilaiset tulivat Daavidin veronalaisiksi palvelijoiksi. Näin Herra antoi Daavidille voiton, mihin tahansa tämä meni.'),
(1679811,58,13,18,7,'Ja Daavid otti ne kultavarustukset, jotka Hadareserin palvelijoilla oli yllään, ja vei ne Jerusalemiin.'),
(1679812,58,13,18,8,'Mutta Hadareserin kaupungeista, Tibhatista ja Kuunista, Daavid otti sangen paljon vaskea. Siitä Salomo teetti vaskimeren, pylväät ja vaskikalut.'),
(1679813,58,13,18,9,'Kun Toou, Hamatin kuningas, kuuli, että Daavid oli voittanut Hadareserin, Sooban kuninkaan, koko sotajoukon,'),
(1679814,58,13,18,10,'lähetti hän poikansa Hadoramin kuningas Daavidin luo tervehtimään häntä ja onnittelemaan häntä siitä, että hän oli taistellut Hadareserin kanssa ja voittanut hänet; Hadareser oli näet ollut Tooun vastustaja. Ja hänellä oli mukanaan kaikkinaisia kulta-, hopea- ja vaskikaluja.'),
(1679815,58,13,18,11,'Nekin kuningas Daavid pyhitti Herralle samoin kuin hopean ja kullan, minkä hän oli ottanut kaikilta kansoilta: Edomilta, Mooabilta, ammonilaisilta, filistealaisilta ja Amalekilta.'),
(1679816,58,13,18,12,'Ja kun Abisai, Serujan poika, oli Suolalaaksossa voittanut edomilaiset, kahdeksantoista tuhatta miestä,'),
(1679817,58,13,18,13,'asetti hän maaherroja Edomiin, ja kaikki edomilaiset tulivat Daavidin palvelijoiksi. Näin Herra antoi Daavidille voiton, mihin tahansa tämä meni.'),
(1679818,58,13,18,14,'Ja Daavid hallitsi koko Israelia ja teki kaikelle kansallensa sitä, mikä oikeus ja vanhurskaus on.'),
(1679819,58,13,18,15,'Jooab, Serujan poika, oli sotajoukon ylipäällikkönä, ja Joosafat, Ahiludin poika, oli kanslerina.'),
(1679820,58,13,18,16,'Saadok, Ahitubin poika, ja Abimelek, Ebjatarin poika, olivat pappeina, ja Savsa oli kirjurina.'),
(1679821,58,13,18,17,'Benaja, Joojadan poika, oli kreettien ja pleettien päällikkönä; mutta Daavidin pojat olivat ensimmäiset kuninkaan rinnalla.'),
(1679822,58,13,19,1,'Sen jälkeen ammonilaisten kuningas Naahas kuoli, ja hänen poikansa tuli kuninkaaksi hänen sijaansa.'),
(1679823,58,13,19,2,'Niin Daavid sanoi: "Minä osoitan laupeutta Haanunille, Naahaan pojalle, sillä hänen isänsä osoitti laupeutta minulle". Ja Daavid lähetti sanansaattajat lohduttamaan häntä hänen isänsä kuoleman johdosta. Kun Daavidin palvelijat tulivat ammonilaisten maahan Haanunin luo lohduttamaan häntä,'),
(1679824,58,13,19,3,'sanoivat ammonilaisten päämiehet Haanunille: "Luuletko sinä, että Daavid tahtoo kunnioittaa sinun isääsi, kun hän lähettää lohduttajia sinun luoksesi? Varmaankin hänen palvelijansa ovat tulleet luoksesi tutkimaan ja hävittämään ja vakoilemaan maata."'),
(1679825,58,13,19,4,'Niin Haanun otatti kiinni Daavidin palvelijat, ajatti heidän partansa ja leikkautti toisen puolen heidän vaatteistaan, peräpuolia myöten, ja päästi heidät sitten menemään.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679826,58,13,19,5,'Kun tultiin kertomaan Daavidille miehistä, lähetti hän sanan heitä vastaan, sillä miehiä oli pahasti häväisty. Ja kuningas käski sanoa: "Jääkää Jerikoon, kunnes partanne on kasvanut, ja tulkaa sitten takaisin".'),
(1679827,58,13,19,6,'Kun ammonilaiset huomasivat joutuneensa Daavidin vihoihin, lähettivät Haanun ja ammonilaiset tuhat talenttia hopeata palkatakseen itsellensä Mesopotamiasta, Maakan Aramista ja Soobasta sotavaunuja ja ratsumiehiä.'),
(1679828,58,13,19,7,'Niin he palkkasivat itselleen kolmekymmentäkaksi tuhatta sotavaunua sekä Maakan kuninkaan ja hänen väkensä; nämä tulivat ja leiriytyivät Meedeban edustalle. Ja ammonilaiset kokoontuivat kaupungeistaan ja lähtivät sotaan.'),
(1679829,58,13,19,8,'Kun Daavid sen kuuli, lähetti hän Jooabin ja koko sotajoukon, urhot.'),
(1679830,58,13,19,9,'Niin ammonilaiset lähtivät ja asettuivat sotarintaan kaupungin portin edustalle, mutta kuninkaat, jotka olivat tulleet sinne, olivat eri joukkona kedolla.'),
(1679831,58,13,19,10,'Kun Jooab näki, että häntä uhkasi hyökkäys edestä ja takaa, valitsi hän miehiä kaikista Israelin valiomiehistä ja asettui sotarintaan aramilaisia vastaan.'),
(1679832,58,13,19,11,'Mutta muun väen hän antoi veljensä Abisain johtoon, ja nämä asettuivat sotarintaan ammonilaisia vastaan.'),
(1679833,58,13,19,12,'Ja hän sanoi: "Jos aramilaiset tulevat minulle ylivoimaisiksi, niin tule sinä minun avukseni: jos taas ammonilaiset tulevat sinulle ylivoimaisiksi, niin minä autan sinua.'),
(1679834,58,13,19,13,'Ole luja, ja pysykäämme lujina kansamme puolesta ja meidän Jumalamme kaupunkien puolesta. Tehköön sitten Herra, minkä hyväksi näkee."'),
(1679835,58,13,19,14,'Sitten Jooab ja väki, joka oli hänen kanssaan, ryhtyi taisteluun aramilaisia vastaan, ja nämä pakenivat häntä.'),
(1679836,58,13,19,15,'Ja kun ammonilaiset näkivät aramilaisten pakenevan, pakenivat hekin hänen veljeänsä Abisaita ja menivät kaupunkiin. Mutta Jooab lähti Jerusalemiin.'),
(1679837,58,13,19,16,'Kun aramilaiset näkivät, että Israel oli voittanut heidät, lähettivät he sanansaattajat nostattamaan niitä aramilaisia, jotka asuivat tuolla puolella Eufrat-virran ja joita johti Soofak, Hadareserin sotapäällikkö.'),
(1679838,58,13,19,17,'Kun se ilmoitettiin Daavidille, kokosi hän kaiken Israelin ja meni Jordanin yli, ja tultuaan heitä lähelle hän asettui sotarintaan heitä vastaan. Ja kun Daavid oli asettunut sotarintaan aramilaisia vastaan, ryhtyivät nämä taisteluun hänen kanssaan.'),
(1679839,58,13,19,18,'Mutta aramilaiset pakenivat Israelia, ja Daavid tappoi aramilaisilta seitsemäntuhatta vaunuhevosta ja neljäkymmentä tuhatta jalkamiestä ja surmasi heidän sotapäällikkönsä Soofakin.'),
(1679840,58,13,19,19,'Kun Hadareserin palvelijat näkivät, että Israel oli voittanut heidät, tekivät he Daavidin kanssa rauhan ja palvelivat häntä. Sitten aramilaiset eivät enää tahtoneet auttaa ammonilaisia.'),
(1679841,58,13,20,1,'Vuoden vaihteessa, kuningasten sotaanlähtöaikana, vei Jooab sotajoukon sotaretkelle; ja hän hävitti ammonilaisten maata ja piiritti Rabbaa. Mutta Daavid itse jäi Jerusalemiin. Sitten Jooab valtasi Rabban ja hävitti sen.'),
(1679842,58,13,20,2,'Ja Daavid otti heidän kuninkaansa kruunun hänen päästänsä ja havaitsi sen painavan talentin kultaa, ja siinä oli kallis kivi; se pantiin Daavidin päähän. Ja hän vei kaupungista hyvin paljon saalista.'),
(1679843,58,13,20,3,'Ja kansan, joka siellä oli, hän vei pois ja pani sahaamaan kiviä, pani rautahakkujen ja kivisahojen ääreen. Näin Daavid teki kaikille ammonilaisten kaupungeille. Sitten Daavid ja kaikki väki palasi Jerusalemiin.'),
(1679844,58,13,20,4,'Sen jälkeen syttyi taistelu filistealaisia vastaan Geserissä. Silloin huusalainen Sibbekai surmasi Sippain, joka oli Raafan jälkeläisiä, ja niin heidät nöyryytettiin.'),
(1679845,58,13,20,5,'Taas oli taistelu filistealaisia vastaan, ja Elhanan, Jaaorin poika, surmasi Lahmin, gatilaisen Goljatin veljen, jonka peitsen varsi oli niinkuin kangastukki.'),
(1679846,58,13,20,6,'Taas oli taistelu Gatissa. Siellä oli suurikasvuinen mies, jolla oli kuusi sormea ja kuusi varvasta, yhteensä kaksikymmentä neljä; hänkin polveutui Raafasta.'),
(1679847,58,13,20,7,'Ja kun hän häpäisi Israelia, surmasi hänet Joonatan, Daavidin veljen Simean poika.'),
(1679848,58,13,20,8,'Nämä polveutuivat gatilaisesta Raafasta; he kaatuivat Daavidin ja hänen palvelijainsa käden kautta.'),
(1679849,58,13,21,1,'Mutta saatana nousi Israelia vastaan ja yllytti Daavidin laskemaan Israelin.'),
(1679850,58,13,21,2,'Niin Daavid sanoi Jooabille ja kansan päämiehille: "Menkää ja laskekaa Israel Beersebasta Daaniin asti ja ilmoittakaa minulle, että saan tietää heidän lukumääränsä".'),
(1679851,58,13,21,3,'Jooab vastasi: "Herra lisätköön kansansa, olkoon se kuinka suuri tahansa, satakertaiseksi. Ovathan he, herrani, kuningas, kaikki herrani palvelijoita. Miksi herrani pyytää tätä? Miksi Israel näin joutuisi vikapääksi?"'),
(1679852,58,13,21,4,'Kuitenkin kuninkaan sana velvoitti Jooabia, ja niin Jooab lähti ja kierteli koko Israelin. Sitten hän tuli Jerusalemiin.'),
(1679853,58,13,21,5,'Ja Jooab ilmoitti Daavidille kansan lasketun lukumäärän: koko Israelissa oli yksitoistasataa tuhatta sotakuntoista miekkamiestä, ja Juudassa oli neljäsataa seitsemänkymmentä tuhatta miekkamiestä.'),
(1679854,58,13,21,6,'Mutta Leevistä ja Benjaminista hän ei pitänyt katselmusta yhdessä muiden kanssa, sillä kuninkaan käsky oli Jooabille kauhistus.'),
(1679855,58,13,21,7,'Mutta tämä asia oli Jumalan silmissä paha, ja hän löi Israelia.'),
(1679856,58,13,21,8,'Niin Daavid sanoi Jumalalle: "Minä olen tehnyt suuren synnin tehdessäni tämän; mutta anna nyt anteeksi palvelijasi rikos, sillä minä olen menetellyt ylen tyhmästi".'),
(1679857,58,13,21,9,'Ja Herra puhui Gaadille, Daavidin näkijälle, näin: "Mene ja puhu Daavidille:'),
(1679858,58,13,21,10,'Näin sanoo Herra: Kolme minä asetan sinun eteesi: valitse itsellesi yksi niistä, niin minä teen sen sinulle".'),
(1679859,58,13,21,11,'Niin Gaad meni Daavidin tykö ja sanoi hänelle: "Näin sanoo Herra: Valitse itsellesi'),
(1679860,58,13,21,12,'joko kolme nälkävuotta tahi kolme kuukautta hävitystä ahdistajaisi vainotessa, vihollistesi miekka kintereilläsi, tahi kolmeksi päiväksi Herran miekka ja ruttotauti maahan, Herran enkeli tuottamaan tuhoa koko Israelin alueelle. Katso nyt, mitä minä vastaan hänelle joka minut lähetti."'),
(1679861,58,13,21,13,'Daavid vastasi Gaadille: "Minä olen suuressa hädässä. Tahdon langeta Herran käsiin, sillä hänen laupeutensa on sangen suuri; ihmisten käsiin minä en tahdo langeta."'),
(1679862,58,13,21,14,'Niin Herra antoi ruton tulla Israeliin, ja Israelista kaatui seitsemänkymmentä tuhatta miestä.'),
(1679863,58,13,21,15,'Ja Jumala lähetti enkelin Jerusalemia vastaan tuhoamaan sitä; ja kun se sitä tuhosi, katsoi Herra siihen ja katui sitä pahaa ja sanoi tuhoojaenkelille: "Jo riittää; laske kätesi alas". Ja Herran enkeli seisoi silloin jebusilaisen Ornanin puimatantereen luona.'),
(1679864,58,13,21,16,'Kun Daavid nosti silmänsä ja näki Herran enkelin seisovan maan ja taivaan välillä, kädessänsä paljastettu miekka ojennettuna Jerusalemin yli, lankesivat Daavid ja vanhimmat, säkkeihin verhottuina, kasvoillensa.'),
(1679865,58,13,21,17,'Ja Daavid sanoi Jumalalle: "Minähän käskin laskea kansan, ja minä siis olen se, joka olen tehnyt syntiä ja menetellyt pahoin. Mutta nämä minun lampaani, mitä he ovat tehneet? Herra, minun Jumalani, sattukoon sinun kätesi minuun ja minun isäni perheeseen, mutta ei sinun kansaasi, sille vitsaukseksi."'),
(1679866,58,13,21,18,'Silloin Herran enkeli käski Gaadin sanoa Daavidille, että Daavid menisi pystyttämään Herralle alttarin jebusilaisen Ornanin puimatantereelle.'),
(1679867,58,13,21,19,'Ja Daavid meni sen sanan mukaan, jonka Gaad oli Herran nimeen puhunut.'),
(1679868,58,13,21,20,'Ja kun Ornan kääntyi, näki hän enkelin, ja hänen neljä poikaansa piiloutui; sillä Ornan oli puimassa nisuja.'),
(1679869,58,13,21,21,'Mutta Daavid meni Ornanin luo, ja kun Ornan katsahti ylös ja näki Daavidin, lähti hän puimatantereelta ja kumartui Daavidin eteen kasvoilleen maahan.'),
(1679870,58,13,21,22,'Ja Daavid sanoi Ornanille: "Anna minulle puimatantereen paikka, rakentaakseni siihen Herralle alttarin; täydestä hinnasta anna se minulle, että vitsaus taukoaisi kansasta".'),
(1679871,58,13,21,23,'Ornan vastasi Daavidille: "Ota se itsellesi, ja herrani, kuningas, tehköön, mitä hyväksi näkee. Katso, minä annan härät polttouhriksi ja puimaäkeet haloiksi sekä nisut ruokauhriksi; kaikki minä annan."'),
(1679872,58,13,21,24,'Mutta kuningas Daavid sanoi Ornanille: "Ei niin, vaan minä ostan ne sinulta täydestä hinnasta; sillä minä en ota Herralle sitä, mikä on sinun, enkä uhraa ilmaiseksi saatua polttouhria".'),
(1679873,58,13,21,25,'Niin Daavid antoi Ornanille siitä paikasta kuudensadan sekelin painon kultaa.'),
(1679874,58,13,21,26,'Ja Daavid rakensi sinne alttarin Herralle ja uhrasi polttouhreja ja yhteysuhreja, ja kun hän huusi Herraa, vastasi Herra tulella, jonka hän lähetti taivaasta polttouhrialttarille.'),
(1679875,58,13,21,27,'Ja Herra käski enkelin pistää miekkansa tuppeen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679876,58,13,21,28,'Siihen aikaan kun Daavid näki, että Herra oli kuullut häntä jebusilaisen Ornanin puimatantereella, uhrasi hän siellä.'),
(1679877,58,13,21,29,'Mutta Herran asumus, jonka Mooses oli teettänyt erämaassa, ja polttouhrialttari olivat siihen aikaan Gibeonin uhrikukkulalla.'),
(1679878,58,13,21,30,'Eikä Daavid rohjennut mennä Jumalan eteen etsimään häntä, sillä hän oli peljästynyt Herran enkelin miekkaa.'),
(1679879,58,13,22,1,'Ja Daavid sanoi: "Tässä olkoon Herran Jumalan temppeli ja tässä alttari Israelin polttouhria varten".'),
(1679880,58,13,22,2,'Niin Daavid käski koota muukalaiset, jotka olivat Israelin maassa. Ja hän asetti kivenhakkaajia hakkaamaan kiviä Jumalan temppelin rakentamiseksi.'),
(1679881,58,13,22,3,'Ja Daavid hankki paljon rautaa portinovien nauloiksi ja sinkilöiksi ja niin paljon vaskea, ettei se ollut punnittavissa,'),
(1679882,58,13,22,4,'ja suunnattomat määrät setripuita, sillä siidonilaiset ja tyyrolaiset toivat paljon setripuita Daavidille.'),
(1679883,58,13,22,5,'Sillä Daavid ajatteli: "Minun poikani Salomo on nuori ja hento, ja Herralle rakennettava temppeli on tehtävä ylen suuri, niin että sitä mainitaan ja kiitetään kaikissa maissa. Minä siis hankin hänelle varastot." Niin Daavid hankki ennen kuolemaansa suuret varastot.'),
(1679884,58,13,22,6,'Ja hän kutsui poikansa Salomon ja käski hänen rakentaa temppelin Herralle, Israelin Jumalalle.'),
(1679885,58,13,22,7,'Ja Daavid sanoi Salomolle: "Poikani, minä aioin itse rakentaa temppelin Herran, Jumalani, nimelle.'),
(1679886,58,13,22,8,'Mutta minulle tuli tämä Herran sana: ''Sinä olet vuodattanut paljon verta ja käynyt suuria sotia. Sinä et ole rakentava temppeliä minun nimelleni, koska olet vuodattanut niin paljon verta maahan minun edessäni.'),
(1679887,58,13,22,9,'Katso, sinulle on syntyvä poika; hänestä on tuleva rauhan mies, ja minä annan hänen päästä rauhaan kaikilta hänen ympärillään asuvilta vihollisilta, sillä Salomo on oleva hänen nimensä ja minä annan rauhan ja levon Israelille hänen päivinänsä.'),
(1679888,58,13,22,10,'Hän on rakentava temppelin minun nimelleni. Hän on oleva minun poikani, ja minä olen oleva hänen isänsä. Ja minä vahvistan hänen kuninkuutensa valtaistuimen ikuisiksi ajoiksi.'''),
(1679889,58,13,22,11,'Olkoon siis Herra sinun kanssasi, poikani, että menestyisit ja saisit rakennetuksi temppelin Herralle, Jumalallesi, niinkuin hän on sinusta puhunut.'),
(1679890,58,13,22,12,'Antakoon vain Herra sinulle älyä ja ymmärrystä ja asettakoon sinut Israelia hallitsemaan ja noudattamaan Herran, Jumalasi, lakia.'),
(1679891,58,13,22,13,'Silloin sinä menestyt, jos tarkoin noudatat niitä käskyjä ja oikeuksia, jotka Herra antoi Moosekselle Israelia varten. Ole luja ja rohkea, älä pelkää äläkä arkaile.'),
(1679892,58,13,22,14,'Katso, vaivanalaisenakin minä olen hankkinut Herran temppeliä varten satatuhatta talenttia kultaa ja tuhat kertaa tuhat talenttia hopeata sekä vaskea ja rautaa niin paljon, ettei se ole punnittavissa, sillä sitä on ylen paljon. Minä olen myös hankkinut hirsiä ja kiviä, ja sinä saat hankkia vielä lisää.'),
(1679893,58,13,22,15,'Paljon on sinulla myöskin työmiehiä, kivenhakkaajia, muurareita, puuseppiä ja kaikkinaisen työn taitajia.'),
(1679894,58,13,22,16,'Kullalla, hopealla, vaskella ja raudalla ei ole määrää. Nouse, ryhdy työhön, ja Herra olkoon sinun kanssasi!"'),
(1679895,58,13,22,17,'Ja Daavid käski kaikkia Israelin päämiehiä auttamaan poikaansa Salomoa, sanoen:'),
(1679896,58,13,22,18,'"Onhan Herra, teidän Jumalanne, ollut teidän kanssanne ja suonut teidän päästä joka taholla rauhaan; sillä hän on antanut maan asukkaat minun käsiini ja maa on tehty alamaiseksi Herralle ja hänen kansallensa.'),
(1679897,58,13,22,19,'Kääntäkää siis sydämenne ja sielunne etsimään Herraa, Jumalaanne; nouskaa ja rakentakaa Herran, Jumalan, pyhäkkö, että Herran liitonarkki ja Jumalan pyhät kalut voitaisiin viedä temppeliin, joka on rakennettava Herran nimelle."'),
(1679898,58,13,23,1,'Kun Daavid oli tullut vanhaksi ja saanut elämästä kyllänsä, teki hän poikansa Salomon Israelin kuninkaaksi.'),
(1679899,58,13,23,2,'Ja hän kutsui kokoon kaikki Israelin päämiehet, papit ja leeviläiset.'),
(1679900,58,13,23,3,'Ja leeviläiset luettiin, kolmikymmenvuotiset ja sitä vanhemmat, ja heidän lukumääränsä, pääluvun mukaan, oli kolmekymmentäkahdeksan tuhatta miestä.'),
(1679901,58,13,23,4,'"Näistä olkoon kaksikymmentäneljä tuhatta johtamassa töitä Herran temppelissä ja kuusi tuhatta päällysmiehinä ja tuomareina;'),
(1679902,58,13,23,5,'ja neljä tuhatta olkoon ovenvartijoina, ja neljä tuhatta ylistäköön Herraa soittimilla, jotka minä olen teettänyt ylistämistä varten."'),
(1679903,58,13,23,6,'Ja Daavid jakoi heidät osastoihin Leevin poikien Geersonin, Kehatin ja Merarin mukaan.'),
(1679904,58,13,23,7,'Geersonilaisia olivat Ladan ja Siimei.'),
(1679905,58,13,23,8,'Ladanin pojat olivat Jehiel, päämies, Seetam ja Jooel, kaikkiaan kolme.'),
(1679906,58,13,23,9,'Siimein pojat olivat Selomit, Hasiel ja Haaran, kaikkiaan kolme. Nämä olivat Ladanin perhekuntien päämiehet.'),
(1679907,58,13,23,10,'Ja Siimein pojat olivat Jahat, Siina, Jeus ja Beria. Nämä olivat Siimein pojat, kaikkiaan neljä.'),
(1679908,58,13,23,11,'Jahat oli päämies, Siisa toinen; mutta Jeuksella ja Berialla ei ollut monta poikaa, niin että heistä tuli yksi perhekunta, yksi palvelusvuoro.'),
(1679909,58,13,23,12,'Kehatin pojat olivat Amram, Jishar, Hebron ja Ussiel, kaikkiaan neljä.'),
(1679910,58,13,23,13,'Amramin pojat olivat Aaron ja Mooses. Mutta Aaron poikinensa erotettiin olemaan ikuisesti pyhitetty, korkeasti-pyhä, ikuisesti suitsuttamaan Herran edessä, palvelemaan häntä ja siunaamaan hänen nimessään.'),
(1679911,58,13,23,14,'Jumalan miehen Mooseksen pojat luettiin Leevin sukukuntaan kuuluviksi.'),
(1679912,58,13,23,15,'Mooseksen pojat olivat Geersom ja Elieser.'),
(1679913,58,13,23,16,'Geersomin poika oli Sebuel, päämies.'),
(1679914,58,13,23,17,'Elieserin poika oli Rehabja, päämies; Elieserillä ei ollut muita poikia. Mutta Rehabjan poikia oli ylen paljon.'),
(1679915,58,13,23,18,'Jisharin poika oli Selomit, päämies.'),
(1679916,58,13,23,19,'Hebronin pojat olivat Jeria, päämies, Amarja toinen, Jahasiel kolmas ja Jekamam neljäs.'),
(1679917,58,13,23,20,'Ussielin pojat olivat Miika, päämies, ja Jissia toinen.'),
(1679918,58,13,23,21,'Merarin pojat olivat Mahli ja Muusi. Mahlin pojat olivat Eleasar ja Kiis.'),
(1679919,58,13,23,22,'Kun Eleasar kuoli, ei häneltä jäänyt poikia, vaan ainoastaan tyttäriä, jotka heidän serkkunsa, Kiisin pojat, ottivat vaimoiksensa.'),
(1679920,58,13,23,23,'Muusin pojat olivat Mahli, Eeder ja Jeremot, kaikkiaan kolme.'),
(1679921,58,13,23,24,'Nämä olivat Leevin pojat, heidän perhekuntiensa mukaan, perhekunta-päämiehet, niin monta kuin heitä oli ollut katselmuksessa, nimien lukumäärän mukaan, pääluvun mukaan, ne, jotka toimittivat palvelustehtäviä Herran temppelissä, kaksikymmenvuotiaat ja sitä vanhemmat.'),
(1679922,58,13,23,25,'Sillä Daavid sanoi: "Herra, Israelin Jumala, on suonut kansansa päästä lepoon ja on asuva Jerusalemissa ikuisesti.'),
(1679923,58,13,23,26,'Niinpä ei leeviläistenkään tarvitse kantaa asumusta eikä mitään kaluja, joita tarvitaan siinä tehtävissä töissä."'),
(1679924,58,13,23,27,'- Sillä Daavidin viimeisten määräysten mukaan laskettiin Leevin poikien lukuun kaksikymmenvuotiaat ja sitä vanhemmat. -'),
(1679925,58,13,23,28,'Heidän tehtäväkseen tuli: olla Aaronin poikien apuna Herran temppelin töissä; pitää huoli esikartanoista ja kammioista, kaiken pyhän puhtaana pitämisestä ja Jumalan temppelin töistä,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679926,58,13,23,29,'näkyleivistä, ruokauhriin tarvittavista lestyistä jauhoista, happamattomista ohukaisista, leivinlevystä ja jauhosekoituksesta sekä astia- ja pituusmitoista;'),
(1679927,58,13,23,30,'seisoa joka aamu kiittämässä ja ylistämässä Herraa, ja samoin joka ilta;'),
(1679928,58,13,23,31,'ja uhrata kaikki polttouhrit Herralle sapatteina, uudenkuun päivinä ja juhlina, niin paljon kuin niitä oli säädetty aina uhrattavaksi Herran edessä.'),
(1679929,58,13,23,32,'Niin heidän oli hoidettava ilmestysmajan ja pyhäkön tehtävät sekä ne tehtävät, jotka heidän veljillään Aaronin pojilla oli palvellessaan Herran temppelissä.'),
(1679930,58,13,24,1,'Nämä olivat Aaronin poikien osastot: Aaronin pojat olivat Naadab, Abihu, Eleasar ja Iitamar.'),
(1679931,58,13,24,2,'Mutta Naadab ja Abihu kuolivat ennen isäänsä, eikä heillä ollut poikia. Niin palvelivat ainoastaan Eleasar ja Iitamar pappeina.'),
(1679932,58,13,24,3,'Ja Daavid yhdessä Saadokin kanssa, joka oli Eleasarin poikia, ja Ahimelekin kanssa, joka oli Iitamarin poikia, jakoi heidät osastoihin heidän palvelusvuorojensa mukaan.'),
(1679933,58,13,24,4,'Kun Eleasarin pojilla havaittiin olevan enemmän päämiehiä kuin Iitamarin pojilla, jaettiin heidät niin, että Eleasarin pojat saivat kuusitoista päämiestä perhekunnilleen ja Iitamarin pojat kahdeksan päämiestä perhekunnilleen.'),
(1679934,58,13,24,5,'Heidät jaettiin arvalla, toiset niinkuin toisetkin, sillä pyhäkköruhtinaat ja Jumalan ruhtinaat otettiin sekä Eleasarin pojista että Iitamarin pojista.'),
(1679935,58,13,24,6,'Ja Semaja, Netanelin poika, kirjuri, joka oli Leevin sukua, kirjoitti heidät muistiin kuninkaan, päämiesten, pappi Saadokin ja Ahimelekin, Ebjatarin pojan, sekä pappien ja leeviläisten perhekuntien päämiesten läsnäollessa. Yksi perhekunta otettiin vuorotellen Eleasarin ja Iitamarin suvusta.'),
(1679936,58,13,24,7,'Ensimmäinen arpa tuli Joojaribille, toinen Jedajalle,'),
(1679937,58,13,24,8,'kolmas Haarimille, neljäs Seoromille,'),
(1679938,58,13,24,9,'viides Malkialle, kuudes Miijaminille,'),
(1679939,58,13,24,10,'seitsemäs Koosille, kahdeksas Abialle,'),
(1679940,58,13,24,11,'yhdeksäs Jeesualle, kymmenes Sekanjalle,'),
(1679941,58,13,24,12,'yhdestoista Eljasibille, kahdestoista Jaakimille,'),
(1679942,58,13,24,13,'kolmastoista Huppalle, neljästoista Jesebabille,'),
(1679943,58,13,24,14,'viidestoista Bilgalle, kuudestoista Immerille,'),
(1679944,58,13,24,15,'seitsemästoista Heesirille, kahdeksastoista Pissekselle,'),
(1679945,58,13,24,16,'yhdeksästoista Petahjalle, kahdeskymmenes Hesekielille,'),
(1679946,58,13,24,17,'kahdeskymmenes yhdes Jaakinille, kahdeskymmenes kahdes Gaamulille,'),
(1679947,58,13,24,18,'kahdeskymmenes kolmas Delajalle, kahdeskymmenes neljäs Maasjalle.'),
(1679948,58,13,24,19,'Nämä ovat heidän palvelusvuoronsa, kun he menevät Herran temppeliin, niinkuin heidän isänsä Aaron oli heille säätänyt, sen mukaan, kuin Herra, Israelin Jumala, oli häntä käskenyt.'),
(1679949,58,13,24,20,'Mitä tulee muihin Leevin jälkeläisiin, niin oli Amramin jälkeläisiä Suubael, Suubaelin jälkeläisiä Jehdeja,'),
(1679950,58,13,24,21,'Rehabjan jälkeläisiä päämies Jissia,'),
(1679951,58,13,24,22,'jisharilaisia Selomot, Selomotin jälkeläisiä Jahat.'),
(1679952,58,13,24,23,'Ja Jerian jälkeläisiä olivat: Amarja toinen, Jahasiel kolmas, Jekamam neljäs.'),
(1679953,58,13,24,24,'Ussielin jälkeläisiä oli Miika, Miikan jälkeläisiä Saamir.'),
(1679954,58,13,24,25,'Miikan veli oli Jissia; Jissian jälkeläisiä oli Sakarja.'),
(1679955,58,13,24,26,'Merarin jälkeläisiä olivat Mahli ja Muusi sekä hänen poikansa Jaasian jälkeläiset.'),
(1679956,58,13,24,27,'Merarilla oli jälkeläisiä pojastaan Jaasiasta ynnä Sooham, Sakkur ja Ibri.'),
(1679957,58,13,24,28,'Mahlista polveutui Eleasar, jolla ei ollut poikia.'),
(1679958,58,13,24,29,'Kiisistä polveutui Jerahmeel, joka oli Kiisin jälkeläisiä.'),
(1679959,58,13,24,30,'Ja Muusin jälkeläisiä olivat Mahli, Eeder ja Jerimot. Nämä olivat leeviläisten jälkeläiset heidän perhekuntiensa mukaan.'),
(1679960,58,13,24,31,'Myöskin nämä, niinhyvin perhekuntapäämiehet kuin heidän nuoremmat veljensä, heittivät arpaa samoin kuin heidän veljensä, Aaronin pojat, kuningas Daavidin, Saadokin ja Ahimelekin sekä pappien ja leeviläisten perhekuntien päämiesten läsnäollessa.'),
(1679961,58,13,25,1,'Ja Daavid ja sotapäälliköt erottivat palvelukseen Aasafin, Heemanin ja Jedutunin pojat, jotka hurmoksissa soittivat kanteleilla, harpuilla ja kymbaaleilla. Ja tämä on luettelo miehistä, jotka tätä palvelustaan toimittivat:'),
(1679962,58,13,25,2,'Aasafin poikia oli Sakkur, Joosef, Netanja ja Asarela, Aasafin pojat, Aasafin johdolla, joka hurmoksissa soitti kuninkaan johdolla.'),
(1679963,58,13,25,3,'Jedutunista: Jedutunin pojat Gedalja, Seri, Jesaja, Hasabja ja Mattitja, kaikkiaan kuusi, isänsä Jedutunin johdolla, joka hurmoksissa soitti kanteleilla kiitosta ja ylistystä Herralle.'),
(1679964,58,13,25,4,'Heemanista: Heemanin pojat Bukkia, Mattanja, Ussiel, Sebuel ja Jerimot, Hananja, Hanani, Eliata, Giddalti ja Roomamti-Eser, Josbekasa, Malloti, Hootir ja Mahasiot;'),
(1679965,58,13,25,5,'nämä ovat kaikki Heemanin, kuninkaan näkijän, poikia, sen Jumalan sanan mukaan, että hän on korottava korkealle hänen sarvensa: Jumala oli antanut Heemanille neljätoista poikaa ja kolme tytärtä.'),
(1679966,58,13,25,6,'Nämä kaikki isänsä johdon alaisina veisasivat Herran temppelissä kymbaalien, harppujen ja kanteleitten säestäessä, Jumalan temppelipalveluksessa, kuninkaan, Aasafin, Jedutunin ja Heemanin johdolla.'),
(1679967,58,13,25,7,'Ja heidän ja heidän veljiensä lukumäärä, jotka oli opetettu veisaamaan Herran kunniaksi, kaikkien taitajien, oli kaksisataa kahdeksankymmentä kahdeksan.'),
(1679968,58,13,25,8,'Ja he heittivät arpaa palvelusjärjestyksestä, nuoremmat niinkuin vanhemmatkin, taitajat yhdessä oppilasten kanssa.'),
(1679969,58,13,25,9,'Ensimmäinen arpa, Aasafin arpa, tuli Joosefille. Toinen Gedaljalle, hänelle itselleen sekä hänen veljilleen ja pojilleen, joita oli kaikkiaan kaksitoista.'),
(1679970,58,13,25,10,'Kolmas Sakkurille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679971,58,13,25,11,'Neljäs Jisrille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679972,58,13,25,12,'Viides Netanjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679973,58,13,25,13,'Kuudes Bukkialle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679974,58,13,25,14,'Seitsemäs Jesarelalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679975,58,13,25,15,'Kahdeksas Jesajalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1679976,58,13,25,16,'Yhdeksäs Mattanjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679977,58,13,25,17,'Kymmenes Siimeille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679978,58,13,25,18,'Yhdestoista Asarelille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679979,58,13,25,19,'Kahdestoista Hasabjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679980,58,13,25,20,'Kolmastoista Suubaelille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679981,58,13,25,21,'Neljästoista Mattitjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679982,58,13,25,22,'Viidestoista Jeremotille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679983,58,13,25,23,'Kuudestoista Hananjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679984,58,13,25,24,'Seitsemästoista Josbekasalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679985,58,13,25,25,'Kahdeksastoista Hananille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679986,58,13,25,26,'Yhdeksästoista Mallotille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679987,58,13,25,27,'Kahdeskymmenes Elijjatalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679988,58,13,25,28,'Kahdeskymmenes yhdes Hootirille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679989,58,13,25,29,'Kahdeskymmenes kahdes Giddaltille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679990,58,13,25,30,'Kahdeskymmenes kolmas Mahasiotille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679991,58,13,25,31,'Kahdeskymmenes neljäs Roomamti-Eserille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.'),
(1679992,58,13,26,1,'Mitä tulee ovenvartijain osastoihin, niin oli koorahilaisia Meselemja, Kooren poika, Aasafin jälkeläisiä.'),
(1679993,58,13,26,2,'Meselemjalla oli pojat: esikoinen Sakarja, toinen Jediael, kolmas Sebadja, neljäs Jatniel,'),
(1679994,58,13,26,3,'viides Eelam, kuudes Joohanan, seitsemäs Eljoenai.'),
(1679995,58,13,26,4,'Oobed-Edomilla oli pojat: esikoinen Semaja, toinen Joosabad, kolmas Jooah, neljäs Saakar, viides Netanel,'),
(1679996,58,13,26,5,'kuudes Ammiel, seitsemäs Isaskar, kahdeksas Peulletai; sillä Jumala oli siunannut häntä.'),
(1679997,58,13,26,6,'Ja hänen pojallensa Semajalle syntyi poikia, jotka hallitsivat isänsä sukua, sillä he olivat kykeneviä miehiä.'),
(1679998,58,13,26,7,'Semajan pojat olivat Otni, Refael, Oobed ja Elsabad ja hänen veljensä, kykeneviä miehiä, Elihu ja Semakja.'),
(1679999,58,13,26,8,'Kaikki nämä olivat Oobed-Edomin jälkeläisiä, he sekä heidän poikansa ja veljensä, kykeneviä miehiä, tarmokkaita palveluksessaan, kaikkiaan kuusikymmentä kaksi Oobed-Edomin jälkeläistä.'),
(1680000,58,13,26,9,'Meselemjalla oli poikia ja veljiä, kykeneviä miehiä, kaikkiaan kahdeksantoista.'),
(1680001,58,13,26,10,'Ja Hoosalla, joka oli Merarin jälkeläisiä, oli poikia: päämies Simri, jonka hänen isänsä, kun ei ollut esikoista, asetti päämieheksi;'),
(1680002,58,13,26,11,'toinen Hilkia, kolmas Tebalja, neljäs Sakarja; Hoosan poikia ja veljiä oli kaikkiaan kolmetoista.'),
(1680003,58,13,26,12,'Näiden ovenvartijain osastojen, päämiesten, samoinkuin heidän veljiensä, tehtävänä oli vartiopalvelus; sillä heidän oli palveltava Herran temppelissä.'),
(1680004,58,13,26,13,'Ja he heittivät arpaa joka ovesta, nuoremmat niinkuin vanhemmatkin, perhekuntiensa mukaan.'),
(1680005,58,13,26,14,'Itäpuolen arpa lankesi Selemjalle; myöskin hänen pojallensa Sakarjalle, joka oli ymmärtäväinen neuvonantaja, heitettiin arpa, ja hänelle tuli pohjoispuolen arpa.'),
(1680006,58,13,26,15,'Oobed-Edomille määräsi arpa etelän ja hänen pojilleen varastohuoneen.'),
(1680007,58,13,26,16,'Suppimille ja Hoosalle lännen, jossa on Salleket-portti ylöspäin kohoavan tien kohdalla: vartiopaikan toisen vartiopaikan viereen.'),
(1680008,58,13,26,17,'Idän puolella oli kuusi leeviläistä, pohjoisen puolella neljä joka päivä, etelän puolella neljä joka päivä ja varastohuoneen luona kaksi ja kaksi.'),
(1680009,58,13,26,18,'Parparin luona, lännen puolella, oli neljä tiellä ja kaksi Parparin luona.'),
(1680010,58,13,26,19,'Nämä ovat ovenvartijain osastot, koorahilaisten jälkeläisten ja Merarin jälkeläisten.'),
(1680011,58,13,26,20,'Leeviläisistä hoiti Ahia Jumalan temppelin aarrekammioita ja pyhien lahjojen aarteita.'),
(1680012,58,13,26,21,'Ladanin pojat, geersonilaisten jälkeläiset, Ladanista polveutuvat geersonilaisen Ladanin perhekuntien päämiehet, jehieliläiset,'),
(1680013,58,13,26,22,'jehieliläisten jälkeläiset, olivat Seetam ja hänen veljensä Jooel; he hoitivat Herran temppelin aarrekammioita.'),
(1680014,58,13,26,23,'Mitä tulee amramilaisiin, jisharilaisiin, hebronilaisiin ja ossielilaisiin,'),
(1680015,58,13,26,24,'niin Sebuel, Geersomin poika, joka oli Mooseksen poika, oli aarrekammioiden esimies.'),
(1680016,58,13,26,25,'Ja hänen Elieseristä polveutuvat veljensä olivat: tämän poika Rehabja, tämän poika Jesaja, tämän poika Jooram, tämän poika Sikri ja tämän poika Selomot.'),
(1680017,58,13,26,26,'Tämä Selomot ja hänen veljensä hoitivat kaikkia niiden pyhien lahjojen aarteita, jotka kuningas Daavid, perhekunta-päämiehet, tuhannen- ja sadanpäämiehet ja sotapäälliköt olivat pyhittäneet.'),
(1680018,58,13,26,27,'Sodista ja saaliista he olivat ne pyhittäneet Herran temppelin voimassapitämiseksi.'),
(1680019,58,13,26,28,'Samoin kaikki, mitä Samuel, näkijä, Saul, Kiisin poika, Abner, Neerin poika, ja Jooab, Serujan poika, olivat pyhittäneet, kaikki, mikä pyhitettiin, jätettiin Selomitin ja hänen veljiensä hoitoon.'),
(1680020,58,13,26,29,'Jisharilaisista määrättiin Kenanja ja hänen poikansa maallisiin toimiin Israelissa, päällysmiehiksi ja tuomareiksi.'),
(1680021,58,13,26,30,'Hebronilaisista määrättiin Hasabja ja hänen veljensä, tuhat seitsemänsataa kykenevää miestä, Israelin hallinnon hoitoon Jordanin länsipuolella, kaikkinaisiin Herran toimiin ja kuninkaan palvelukseen.'),
(1680022,58,13,26,31,'Hebronilaisia oli Jeria, hebronilaisten päämies, heidän polveutumisensa ja isiensä mukaan - Daavidin neljäntenäkymmenentenä hallitusvuotena heidät tutkittiin ja heidän joukostaan tavattiin kykeneviä miehiä Gileadin Jaeserissa -'),
(1680023,58,13,26,32,'sekä hänen veljensä, kaksituhatta seitsemänsataa kykenevää miestä, perhekunta-päämiehiä. Heidät kuningas Daavid asetti johtamaan ruubenilaisia, gaadilaisia ja toista puolta manasselaisten sukukuntaa kaikissa Jumalan ja kuninkaan asioissa.'),
(1680024,58,13,27,1,'Israelilaisia, lukumääränsä mukaan, ynnä perhekunta-päämiehiä, tuhannen- ja sadanpäämiehiä ja heidän päällysmiehiänsä, jotka palvelivat kuningasta kaikessa, mikä koski osastoja, jotka tulivat ja lähtivät kuukausi kuukaudelta, vuoden kaikkina kuukausina, oli kussakin osastossa kaksikymmentäneljä tuhatta miestä:'),
(1680025,58,13,27,2,'Ensimmäisen osaston, ensimmäisen kuukauden osaston, johtajana oli Jaasobeam, Sabdielin poika, ja hänen osastossaan oli kaksikymmentäneljä tuhatta;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680026,58,13,27,3,'hän oli Pereksen jälkeläisiä ja oli kaikkien sotapäälliköitten ylipäällikkö, ensimmäisenä kuukautena.'),
(1680027,58,13,27,4,'Toisen kuukauden osaston johtajana oli ahohilainen Doodai; hänen osastonsa johdossa oli myös ruhtinas Miklot, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.'),
(1680028,58,13,27,5,'Kolmas sotapäällikkö, kolmantena kuukautena, oli Benaja, pappi Joojadan poika, ylipäällikkö; ja hänen osastossaan oli kaksikymmentaneljätuhatta.'),
(1680029,58,13,27,6,'Tämä Benaja oli sankari niiden kolmenkymmenen joukossa ja niiden kolmenkymmenen johtaja; ja hänen osastossaan oli hänen poikansa Ammisabad.'),
(1680030,58,13,27,7,'Neljäs, neljäntenä kuukautena, oli Asahel, Jooabin veli, ja hänen jälkeensä hänen poikansa Sebadja; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.'),
(1680031,58,13,27,8,'Viides, viidentenä kuukautena, oli päällikkö Samhut, jisrahilainen; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.'),
(1680032,58,13,27,9,'Kuudes, kuudentena kuukautena, oli tekoalainen Iira, Ikkeksen poika; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.'),
(1680033,58,13,27,10,'Seitsemäs, seitsemäntenä kuukautena, oli pelonilainen Heeles, efraimilaisia; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.'),
(1680034,58,13,27,11,'Kahdeksas, kahdeksantena kuukautena, oli huusalainen Sibbekai, serahilaisia; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.'),
(1680035,58,13,27,12,'Yhdeksäs, yhdeksäntenä kuukautena, oli anatotilainen Abieser, benjaminilaisia; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.'),
(1680036,58,13,27,13,'Kymmenes, kymmenentenä kuukautena, oli netofalainen Mahrai, serahilaisia; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.'),
(1680037,58,13,27,14,'Yhdestoista, yhdentenätoista kuukautena, oli piratonilainen Benaja, efraimilaisia; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.'),
(1680038,58,13,27,15,'Kahdestoista, kahdentenatoista kuukautena, oli netofalainen Heldai, Otnielista polveutuva; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.'),
(1680039,58,13,27,16,'Israelin sukukuntien johtajat olivat: ruubenilaisten ruhtinas oli Elieser, Sikrin poika; simeonilaisten Sefatja, Maakan poika;'),
(1680040,58,13,27,17,'Leevin oli Hasabja, Kemuelin poika; Aaronin Saadok;'),
(1680041,58,13,27,18,'Juudan oli Elihu, Daavidin veljiä; Isaskarin Omri, Miikaelin poika;'),
(1680042,58,13,27,19,'Sebulonin oli Jismaja, Obadjan poika; Naftalin Jerimot, Asrielin poika;'),
(1680043,58,13,27,20,'efraimilaisten oli Hoosea, Asasjan poika; toisen puolen Manassen sukukuntaa Jooel, Pedajan poika;'),
(1680044,58,13,27,21,'toisen puolen Manassea, Gileadissa, oli Jiddo, Sakarjan poika; Benjaminin Jaasiel, Abnerin poika;'),
(1680045,58,13,27,22,'Daanin Asarel, Jerohamin poika. Nämä olivat Israelin sukukuntien ruhtinaat.'),
(1680046,58,13,27,23,'Mutta Daavid ei ottanut luetteloon kaksikymmenvuotiaita ja sitä nuorempia, sillä Herra oli luvannut tehdä Israelin monilukuiseksi niinkuin taivaan tähdet.'),
(1680047,58,13,27,24,'Jooab, Serujan poika, oli alottanut laskemisen, mutta ei sitä lopettanut, sillä siitä kohtasi viha Israelia; eikä se luku tullut kuningas Daavidin aikakirjaan.'),
(1680048,58,13,27,25,'Kuninkaan varastojen hoitaja oli Asmavet, Adielin poika. Kedolla, kaupungeissa, kylissä ja torneissa olevien varastojen hoitaja oli Joonatan, Ussian poika.'),
(1680049,58,13,27,26,'Maatöitä tekevien peltotyömiesten kaitsija oli Esri, Kelubin poika.'),
(1680050,58,13,27,27,'Viinitarhain hoitaja oli raamatilainen Siimei. Viinitarhoista koottujen viinivarastojen hoitaja oli sifmiläinen Sabdi.'),
(1680051,58,13,27,28,'Öljypuiden ja Alankomaassa kasvavien metsäviikunapuiden hoitaja oli gaderilainen Baal-Haanan. Öljyvarastojen hoitaja oli Jooas.'),
(1680052,58,13,27,29,'Saaronissa laitumella käyvien raavasten kaitsija oli saaronilainen Sitrai, ja tasangoilla laitumella käyvien raavasten kaitsija Saafat, Adlain poika.'),
(1680053,58,13,27,30,'Kamelien kaitsija oli ismaelilainen Oobil; aasintammojen meeronotilainen Jehdeja.'),
(1680054,58,13,27,31,'Pikkukarjan kaitsija oli hagrilainen Jaasis. Nämä kaikki olivat kuningas Daavidin omaisuuden ylihoitajia.'),
(1680055,58,13,27,32,'Ja Joonatan, Daavidin setä, joka oli ymmärtäväinen mies ja kirjanoppinut, oli neuvonantaja. Jehiel, Hakmonin poika, oli kuninkaan lasten luona.'),
(1680056,58,13,27,33,'Ahitofel oli kuninkaan neuvonantaja, ja arkilainen Huusai oli kuninkaan ystävä.'),
(1680057,58,13,27,34,'Ahitofelin jälkeen tulivat Joojada, Benajan poika, ja Ebjatar. Kuninkaan sotapäällikkö oli Jooab.'),
(1680058,58,13,28,1,'Ja Daavid kokosi Jerusalemiin kaikki Israelin päämiehet, sukukuntien päämiehet, osastojen päälliköt, jotka palvelivat kuningasta, tuhannen- ja sadanpäämiehet, kuninkaan ja hänen poikiensa kaiken omaisuuden ja karjan ylihoitajat, hovimiehet, sankarit ja kaikki sotaurhot.'),
(1680059,58,13,28,2,'Ja kuningas Daavid nousi seisomaan ja sanoi: "Kuulkaa minua, veljeni ja kansani. Minä olin aikonut rakentaa huoneen Herran liitonarkin leposijaksi ja meidän Jumalamme jalkojen astinlaudaksi ja olin valmistautunut rakentamaan.'),
(1680060,58,13,28,3,'Mutta Jumala sanoi minulle: ''Älä sinä rakenna temppeliä minun nimelleni, sillä sinä olet sotilas ja olet vuodattanut verta''.'),
(1680061,58,13,28,4,'Kuitenkin valitsi Herra, Israelin Jumala, minut kaikesta isäni suvusta olemaan Israelin kuninkaana ikuisesti. Sillä Juudan hän valitsi ruhtinaaksi ja Juudan heimosta minun isäni suvun, ja isäni poikien joukossa olin minä hänelle otollinen, niin että hän teki minut koko Israelin kuninkaaksi.'),
(1680062,58,13,28,5,'Ja kaikkien minun poikieni joukosta, sillä Herra on antanut minulle monta poikaa, hän valitsi poikani Salomon istumaan Herran valtakunnan valtaistuimella ja hallitsemaan Israelia.'),
(1680063,58,13,28,6,'Ja hän sanoi minulle: ''Sinun poikasi Salomo on rakentava minun temppelini ja esikartanoni; sillä minä olen valinnut hänet pojakseni ja minä olen oleva hänen isänsä.'),
(1680064,58,13,28,7,'Ja minä vahvistan hänen kuninkuutensa iankaikkisesti, jos hän on luja ja pitää minun käskyni ja oikeuteni, niinkuin hän nyt tekee.'''),
(1680065,58,13,28,8,'Ja nyt minä sanon koko Israelin, Herran seurakunnan, läsnäollessa ja meidän Jumalamme kuullen: Noudattakaa ja tutkikaa kaikkia Herran, Jumalanne, käskyjä, että saisitte pitää omananne tämän hyvän maan ja jättäisitte sen perinnöksi lapsillenne teidän jälkeenne ikuisiksi ajoiksi.'),
(1680066,58,13,28,9,'Ja sinä, minun poikani Salomo, opi tuntemaan isäsi Jumala ja palvele häntä ehyellä sydämellä ja alttiilla mielellä, sillä Herra tutkii kaikki sydämet ja ymmärtää kaikki ajatukset ja aivoitukset. Jos häntä etsit, niin sinä löydät hänet, mutta jos luovut hänestä, niin hän hylkää sinut iankaikkisesti.'),
(1680067,58,13,28,10,'Katso siis eteesi, sillä Herra on valinnut sinut rakentamaan temppelipyhäkön. Ole luja ja ryhdy työhön."'),
(1680068,58,13,28,11,'Senjälkeen Daavid antoi pojallensa Salomolle temppelin eteisen, sen rakennusten, varastohuoneiden, yläsalien, sisähuoneiden ja armoistuimen huoneen mallin'),
(1680069,58,13,28,12,'sekä määräykset kaikesta, mitä hänellä oli mielessään: Herran temppelin esikartanoista ja kaikista kammioista yltympäri, Jumalan temppelin ja pyhien lahjojen aarrekammioista,'),
(1680070,58,13,28,13,'kuin myös pappien ja leeviläisten osastoista, kaikesta Herran temppelissä toimitettavasta palveluksesta ja kaikista Herran temppelin palveluksessa tarvittavista kaluista: kullasta,'),
(1680071,58,13,28,14,'jokaisen palveluksessa tarvittavan kultakalun painosta, kaikista hopeakaluista, jokaisen palveluksessa tarvittavan hopeakalun painosta;'),
(1680072,58,13,28,15,'kullasta tehtävien lampunjalkojen ja niiden kunkin lampun kullan painosta, jokaisen lampunjalan ja sen lamppujen painosta; samoin hopeasta tehtävien lampunjalkojen painosta, jokaisen lampunjalan ja sen lamppujen painosta, jokaisen lampunjalan käytön mukaan;'),
(1680073,58,13,28,16,'edelleen näkyleipäpöytien kullan painosta, kunkin pöydän erikseen, samoin hopeasta tehtävien pöytien hopeasta;'),
(1680074,58,13,28,17,'haarukkain, maljojen ja kannujen puhtaasta kullasta, samoin kultapikareista, kunkin pikarin painosta, ja hopeapikareista, kunkin pikarin painosta;'),
(1680075,58,13,28,18,'myöskin suitsutusalttarin puhdistetun kullan painosta ja vaunujen mallista, kultakerubeista, joitten tuli levittää siipensä ja peittää Herran liitonarkki.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680076,58,13,28,19,'"Tämä kaikki on kirjoituksessa, joka on lähtenyt Herran kädestä; hän on opettanut minulle kaikki tämän mallin mukaan tehtävät työt."'),
(1680077,58,13,28,20,'Ja Daavid sanoi pojallensa Salomolle: "Ole luja ja rohkea ja ryhdy työhön, älä pelkää äläkä arkaile, sillä Herra Jumala, minun Jumalani, on oleva sinun kanssasi. Hän ei jätä sinua eikä hylkää sinua, kunnes olet saanut valmiiksi kaikki Herran temppelissä tehtävät työt.'),
(1680078,58,13,28,21,'Ja katso, pappien ja leeviläisten osastot ovat valmiit kaikkinaiseen palvelukseen Jumalan temppelissä, ja sinulla on kaikkiin töihin käytettävinäsi niitä, jotka alttiisti ja taidolla tekevät kaikkinaista palvelusta, niin myös päämiehet ja koko kansa kaikkiin tehtäviisi."'),
(1680079,58,13,29,1,'Sitten kuningas Daavid sanoi koko seurakunnalle: "Minun poikani Salomo, ainoa Jumalan valittu, on nuori ja hento, ja työ on suuri, sillä tämä linna ei ole aiottu ihmiselle, vaan Herralle Jumalalle.'),
(1680080,58,13,29,2,'Sentähden minä olen kaikin voimin hankkinut Jumalani temppeliä varten kultaa kultaesineihin, hopeata hopeaesineihin, vaskea vaskiesineihin, rautaa rautaesineihin ja puuta puuesineihin, onykskiviä ja muita jalokiviä, mustankiiltävää ja kirjavaa kiveä, kaikkinaisia kalliita kiviä ja marmorikiveä suuret määrät.'),
(1680081,58,13,29,3,'Koska minun Jumalani temppeli on minulle rakas, minä vielä luovutan omistamani kullan ja hopean Jumalani temppeliä varten, kaiken lisäksi, minkä olen pyhäkköä varten hankkinut:'),
(1680082,58,13,29,4,'kolmetuhatta talenttia kultaa, Oofirin kultaa, ja seitsemäntuhatta talenttia puhdistettua hopeata huoneitten seinien silaamiseksi,'),
(1680083,58,13,29,5,'kultaa kultaesineihin ja hopeata hopeaesineihin ja kaikkinaisiin taitomiesten kätten töihin. Tahtooko kukaan muu tänä päivänä tuoda vapaaehtoisesti, täysin käsin, lahjoja Herralle?"'),
(1680084,58,13,29,6,'Silloin tulivat vapaaehtoisesti perhekunta-päämiehet, Israelin sukukuntien ruhtinaat, tuhannen- ja sadanpäämiehet ja kuninkaan töiden ylivalvojat.'),
(1680085,58,13,29,7,'Ja he antoivat Jumalan temppelissä tehtäviin töihin viisituhatta talenttia ja kymmenentuhatta dareikkia kultaa, kymmenentuhatta talenttia hopeata, kahdeksantoista tuhatta talenttia vaskea ja satatuhatta talenttia rautaa.'),
(1680086,58,13,29,8,'Ja jolla oli hallussaan jalokiviä, antoi ne Herran temppelin aarteisiin, geersonilaisen Jehielin huostaan.'),
(1680087,58,13,29,9,'Ja kansa iloitsi heidän alttiudestaan, sillä he antoivat ehyellä sydämellä vapaaehtoiset lahjansa Herralle; ja kuningas Daavid oli myös suuresti iloissansa.'),
(1680088,58,13,29,10,'Ja Daavid kiitti Herraa koko seurakunnan läsnäollessa; Daavid sanoi: "Ole kiitetty, Herra, meidän isämme Israelin Jumala, iankaikkisesta iankaikkiseen.'),
(1680089,58,13,29,11,'Sinun, Herra, on suuruus ja väkevyys ja loisto ja kunnia ja kirkkaus, sillä sinun on kaikki taivaassa ja maan päällä. Sinun, Herra, on valtakunta, ja sinä olet korotettu kaiken pääksi.'),
(1680090,58,13,29,12,'Rikkaus ja kunnia tulevat sinulta, sinä hallitset kaikki, ja sinun kädessäsi on voima ja väkevyys. Sinun vallassasi on tehdä mikä tahansa suureksi ja väkeväksi.'),
(1680091,58,13,29,13,'Me siis kiitämme sinua, meidän Jumalaamme; me ylistämme sinun ihanaa nimeäsi.'),
(1680092,58,13,29,14,'Sillä mitä olen minä, ja mitä on minun kansani, kyetäksemme antamaan tällaisia vapaaehtoisia lahjoja? Vaan kaikki tulee sinulta, ja omasta kädestäsi olemme sen sinulle antaneet.'),
(1680093,58,13,29,15,'Sillä me olemme muukalaisia ja vieraita sinun edessäsi, niinkuin kaikki meidän isämmekin; niinkuin varjo ovat meidän päivämme maan päällä eikä ole, mihin toivonsa panna.'),
(1680094,58,13,29,16,'Herra, meidän Jumalamme, kaikki tämä runsaus, jonka me olemme hankkineet rakentaaksemme temppelin sinulle, sinun pyhälle nimellesi, on sinun kädestäsi, ja sinun on kaikki tyynni.'),
(1680095,58,13,29,17,'Ja minä tiedän, Jumalani, että sinä tutkit sydämen ja mielistyt vilpittömyyteen. Vilpittömällä sydämellä minä olen antanut kaikki nämä vapaaehtoiset lahjat, ja nyt minä olen ilolla nähnyt, kuinka sinun täällä oleva kansasi on antanut sinulle vapaaehtoiset lahjansa.'),
(1680096,58,13,29,18,'Herra, meidän isäimme Aabrahamin, Iisakin ja Israelin Jumala, säilytä tällaisina ainiaan kansasi sydämen ajatukset ja aivoitukset ja ohjaa heidän sydämensä puoleesi.'),
(1680097,58,13,29,19,'Ja anna minun pojalleni Salomolle ehyt sydän noudattamaan sinun käskyjäsi, todistuksiasi ja säädöksiäsi, toimittamaan kaikki tämä ja rakentamaan tämä linna, jota varten minä olen valmistuksia tehnyt."'),
(1680098,58,13,29,20,'Sitten Daavid sanoi kaikelle seurakunnalle: "Kiittäkää Herraa, Jumalaanne". Ja kaikki seurakunta kiitti Herraa, isiensä Jumalaa, ja he kumartuivat maahan ja osoittivat kunniaa Herralle ja kuninkaalle.'),
(1680099,58,13,29,21,'Ja seuraavana päivänä he teurastivat teuraita Herralle ja uhrasivat polttouhreja Herralle: tuhat härkää, tuhat oinasta ja tuhat karitsaa ja niihin kuuluvat juomauhrit sekä teurasuhreja suuren joukon koko Israelin puolesta.'),
(1680100,58,13,29,22,'Niin he söivät ja joivat Herran edessä sinä päivänä suuresti iloiten ja tekivät toistamiseen Salomon, Daavidin pojan, kuninkaaksi ja voitelivat hänet Herralle ruhtinaaksi, ja Saadokin papiksi.'),
(1680101,58,13,29,23,'Ja Salomo istui Herran valtaistuimelle kuninkaaksi isänsä Daavidin sijaan, ja hän menestyi; ja koko Israel totteli häntä.'),
(1680102,58,13,29,24,'Samoin kaikki päämiehet, urhot ja myös kaikki kuningas Daavidin pojat kättä lyöden lupautuivat kuningas Salomon alamaisiksi.'),
(1680103,58,13,29,25,'Herra teki Salomon ylen suureksi koko Israelin silmissä ja antoi hänelle kuninkuuden loiston, jonka kaltaista ei ollut yhdelläkään kuninkaalla Israelissa ollut ennen häntä.'),
(1680104,58,13,29,26,'Daavid, Iisain poika, oli hallinnut koko Israelia.'),
(1680105,58,13,29,27,'Ja aika, jonka hän hallitsi Israelia, oli neljäkymmentä vuotta; Hebronissa hän hallitsi seitsemän vuotta, ja Jerusalemissa hän hallitsi kolmekymmentä kolme vuotta.'),
(1680106,58,13,29,28,'Ja hän kuoli päästyänsä korkeaan ikään, elämästä, rikkaudesta ja kunniasta kyllänsä saaneena, ja hänen poikansa Salomo tuli kuninkaaksi hänen sijaansa.'),
(1680107,58,13,29,29,'Daavidin vaiheet, sekä aikaisemmat että myöhemmät, ovat kirjoitettuina näkijä Samuelin historiassa, profeetta Naatanin historiassa ja tietäjä Gaadin historiassa;'),
(1680108,58,14,1,1,'Salomo, Daavidin poika, vahvistui kuninkuudessansa, ja Herra, hänen Jumalansa, oli hänen kanssansa ja teki hänet ylen suureksi.'),
(1680109,58,14,1,2,'Ja Salomo antoi kutsun koko Israelille, tuhannen- ja sadanpäämiehille, tuomareille ja kaikille ruhtinaille koko Israelissa, perhekunta-päämiehille;'),
(1680110,58,14,1,3,'ja niin Salomo ja koko seurakunta hänen kanssaan menivät uhrikukkulalle, joka oli Gibeonissa, sillä siellä oli Jumalan ilmestysmaja, jonka Herran palvelija Mooses oli tehnyt erämaassa.'),
(1680111,58,14,1,4,'Mutta Jumalan arkin oli Daavid tuonut Kirjat-Jearimista siihen paikkaan, jonka Daavid oli sille valmistanut; sillä hän oli pystyttänyt sille majan Jerusalemiin.'),
(1680112,58,14,1,5,'Ja vaskialttari, jonka Besalel, Uurin poika, Huurin pojanpoika, oli rakentanut, oli siellä Herran asumuksen edessä; Salomo ja seurakunta etsivät häntä siellä.'),
(1680113,58,14,1,6,'Ja Salomo uhrasi siellä Herran edessä ilmestysmajan vaskialttarilla; hän uhrasi sen päällä tuhat polttouhria.'),
(1680114,58,14,1,7,'Sinä yönä Jumala ilmestyi Salomolle ja sanoi hänelle: "Ano, mitä tahdot minun sinulle antavan".'),
(1680115,58,14,1,8,'Salomo vastasi Jumalalle: "Sinä olet tehnyt suuren laupeuden minun isälleni Daavidille ja tehnyt minut kuninkaaksi hänen sijaansa.'),
(1680116,58,14,1,9,'Niin toteutukoon nyt, Herra Jumala, sinun isälleni Daavidille antamasi sana; sillä sinä olet pannut minut hallitsemaan kansaa, jota on paljon niinkuin tomua maassa.'),
(1680117,58,14,1,10,'Anna siis minulle viisaus ja taito lähteä ja tulla tämän kansan edellä, sillä kuka voi muuten tätä sinun suurta kansaasi tuomita?"'),
(1680118,58,14,1,11,'Ja Jumala sanoi Salomolle: "Koska sinulla on tämä mieli etkä anonut rikkautta, tavaraa ja kunniaa, et vihamiestesi henkeä, etkä myöskään anonut pitkää ikää, vaan anoit itsellesi viisautta ja taitoa tuomitaksesi minun kansaani, jonka kuninkaaksi minä olen sinut tehnyt,'),
(1680119,58,14,1,12,'niin annetaan sinulle viisaus ja taito; ja lisäksi minä annan sinulle rikkautta, tavaraa ja kunniaa, niin ettei sitä ole ollut niin paljoa kenelläkään kuninkaalla ennen sinua eikä tule olemaan sinun jälkeesi".'),
(1680120,58,14,1,13,'Käytyään uhrikukkulalla, joka oli Gibeonissa, Salomo palasi ilmestysmajalta Jerusalemiin ja hallitsi Israelia.'),
(1680121,58,14,1,14,'Ja Salomo kokosi sotavaunuja ja ratsumiehiä, niin että hänellä oli tuhannet neljätsadat sotavaunut ja kaksitoista tuhatta ratsumiestä. Ne hän sijoitti vaunukaupunkeihin ja kuninkaan luo Jerusalemiin.'),
(1680122,58,14,1,15,'Ja kuningas toimitti niin, että Jerusalemissa oli hopeata ja kultaa kuin kiviä, ja setripuuta niin paljon kuin metsäviikunapuita Alankomaassa.'),
(1680123,58,14,1,16,'Ja hevoset, mitä Salomolla oli, tuotiin Egyptistä ja Kuvesta; kuninkaan kauppiaat noutivat niitä Kuvesta maksua vastaan.'),
(1680124,58,14,1,17,'Egyptistä tuodut vaunut maksoivat kuusisataa hopeasekeliä ja hevonen sata viisikymmentä. Samoin tuotiin niitä heidän välityksellään kaikille heettiläisten ja aramilaisten kuninkaille.'),
(1680125,58,14,2,1,'Ja Salomo käski ryhtyä rakentamaan temppeliä Herran nimelle ja kuninkaallista linnaa itsellensä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680126,58,14,2,2,'Ja Salomo määräsi seitsemänkymmentä tuhatta miestä taakankantajiksi ja kahdeksankymmentä tuhatta miestä kivenhakkaajiksi vuoristoon ja niille kolmetuhatta kuusisataa työnjohtajaa.'),
(1680127,58,14,2,3,'Sitten Salomo lähetti Huuramille, Tyyron kuninkaalle, sanan: "Tee minulle sama, minkä teit isälleni Daavidille, jolle lähetit setripuita, että hän rakentaisi itsellensä linnan asuaksensa siinä.'),
(1680128,58,14,2,4,'Katso, minä rakennan temppelin Herran, Jumalani, nimelle, pyhittääkseni sen hänelle, että siinä poltettaisiin hyvänhajuista suitsutusta hänen edessänsä, pidettäisiin aina esillä näkyleipiä ja uhrattaisiin polttouhreja aamuin ja illoin, sapatteina, uudenkuun päivinä ja Herran, meidän Jumalamme, juhlina; tämä on Israelin ikuinen velvollisuus.'),
(1680129,58,14,2,5,'Ja temppeli, jonka minä rakennan, on oleva suuri; sillä meidän Jumalamme on suurin kaikista jumalista.'),
(1680130,58,14,2,6,'Kuka kykenisi rakentamaan hänelle huoneen? Taivaisiin ja taivasten taivaisiin hän ei mahdu. Mikä siis olen minä rakentamaan hänelle temppeliä muuta varten kuin uhratakseni hänen edessänsä?'),
(1680131,58,14,2,7,'Niin lähetä nyt minulle mies, joka on taitava tekemään kulta-, hopea-, vaski- ja rautatöitä, niin myös töitä purppuranpunaisista, helakanpunaisista ja punasinisistä langoista, ja joka osaa veistää veistoksia, työskentelemään yhdessä niiden taitajien kanssa, joita minulla on Juudassa ja Jerusalemissa ja jotka minun isäni Daavid on hankkinut.'),
(1680132,58,14,2,8,'Ja lähetä minulle setripuita, kypressipuita ja santelipuita Libanonilta, sillä minä tiedän, että sinun palvelijasi osaavat hakata Libanonin puita; ja katso, minun palvelijani olkoot sinun palvelijaisi kanssa.'),
(1680133,58,14,2,9,'Minulle on hankittava paljon puuta, sillä temppeli, jonka minä rakennan, on oleva suuri ja ihmeellinen.'),
(1680134,58,14,2,10,'Ja katso, minä annan kirvesmiehille, puitten hakkaajille, kaksikymmentä tuhatta koor-mittaa nisuja, sinun palvelijaisi ravinnoksi, ja kaksikymmentä tuhatta koor-mittaa ohria, kaksikymmentä tuhatta bat-mittaa viiniä ja kaksikymmentä tuhatta bat-mittaa öljyä."'),
(1680135,58,14,2,11,'Huuram, Tyyron kuningas, vastasi kirjeellä, jonka hän lähetti Salomolle: "Sentähden, että Herra rakastaa kansaansa, on hän asettanut sinut heidän kuninkaakseen".'),
(1680136,58,14,2,12,'Ja Huuram sanoi vielä: "Kiitetty olkoon Herra, Israelin Jumala, joka on tehnyt taivaan ja maan, siitä että hän on antanut kuningas Daavidille viisaan pojan, jolla on älyä ja ymmärrystä rakentaa temppeli Herralle ja kuninkaallinen linna itsellensä.'),
(1680137,58,14,2,13,'Ja nyt minä lähetän taitavan, ymmärtäväisen miehen, Huuram-Aabin,'),
(1680138,58,14,2,14,'joka on daanilaisen vaimon poika ja jonka isä on tyyrolainen. Hän osaa tehdä kulta- ja hopea-, vaski- ja rauta-, kivi- ja puutöitä, niin myös töitä purppuranpunaisista ja punasinisistä langoista, valkoisista pellavalangoista ja helakanpunaisista langoista. Hän osaa veistää veistoksia ja sommitella kaikkinaisia taideteoksia, joita hänen tehtäväkseen annetaan, yhdessä sinun taitomiestesi ja herrani, sinun isäsi Daavidin, taitomiesten kanssa.'),
(1680139,58,14,2,15,'Lähettäköön siis herrani palvelijoillensa nisut, ohrat, öljyn ja viinin, niinkuin on sanonut.'),
(1680140,58,14,2,16,'Silloin me hakkaamme puita Libanonilta niin paljon, kuin sinä tarvitset, ja me kuljetamme ne lautoissa meritse sinulle Jaafoon. Toimita sinä ne sitten ylös Jerusalemiin."'),
(1680141,58,14,2,17,'Ja Salomo luetti kaikki muukalaiset miehet Israelin maassa, senjälkeen kuin hänen isänsä Daavid oli heidät luettanut. Ja heitä huomattiin olevan sata viisikymmentäkolme tuhatta kuusisataa.'),
(1680142,58,14,2,18,'Näistä hän teki seitsemänkymmentä tuhatta taakankantajiksi, kahdeksankymmentä tuhatta kivenhakkaajiksi vuoristoon ja kolmetuhatta kuusisataa työnjohtajiksi, joiden oli pidettävä väki työssä.'),
(1680143,58,14,3,1,'Sitten Salomo alkoi rakentaa Herran temppeliä Jerusalemiin, Moorian vuorelle, jossa Herra oli ilmestynyt hänen isällensä Daavidille, siihen paikkaan, jonka Daavid oli valmistanut, jebusilaisen Ornanin puimatantereelle.'),
(1680144,58,14,3,2,'Hän alkoi rakentaa toisen kuun toisena päivänä, neljäntenä hallitusvuotenansa.'),
(1680145,58,14,3,3,'Tällaisen perustuksen Salomo laski rakennettavalle Jumalan temppelille: pituus oli, vanhan mitan mukaan, kuusikymmentä kyynärää, leveys kaksikymmentä kyynärää.'),
(1680146,58,14,3,4,'Eteinen, temppelin itäpäässä, oli yhtä pitkä kuin temppeli leveä, kahtakymmentä kyynärää, ja sen korkeus oli kaksikymmentä kyynärää; ja hän päällysti sen sisältä puhtaalla kullalla.'),
(1680147,58,14,3,5,'Suuren huoneen hän laudoitti sisältä kypressipuulla, jonka hän silasi parhaalla kullalla ja johon hän laittoi palmuja ja vitjoja.'),
(1680148,58,14,3,6,'Ja hän koristi huoneen kalliilla kivillä. Ja kulta oli Parvaimin kultaa.'),
(1680149,58,14,3,7,'Ja hän silasi huoneen, palkit, kynnykset, seinät ja ovet, kullalla ja kaiverrutti kerubeja seiniin.'),
(1680150,58,14,3,8,'Ja hän teki kaikkeinpyhimmän huoneen. Se oli yhtä pitkä kuin temppeli leveä, kahtakymmentä kyynärää, ja myös kahtakymmentä kyynärää leveä. Ja hän silasi sen parhaalla kullalla, joka painoi kuusisataa talenttia.'),
(1680151,58,14,3,9,'Ja kultanaulojen paino oli viisikymmentä sekeliä. Myöskin yläsalit hän silasi kullalla.'),
(1680152,58,14,3,10,'Kaikkein pyhimpään huoneeseen hän teki kaksi kerubia, taidollisesti tehtyä, ja päällysti ne kullalla.'),
(1680153,58,14,3,11,'Kerubien siipien pituus oli yhteensä kaksikymmentä kyynärää. Toisen kerubin toinen siipi oli viittä kyynärää pitkä ja kosketti huoneen toista seinää, ja sen toinen siipi oli viittä kyynärää pitkä ja ulottui toisen kerubin siipeen.'),
(1680154,58,14,3,12,'Ja toisen kerubin toinen siipi oli viittä kyynärää pitkä ja ulottui huoneen toiseen seinään, ja sen toinen siipi oli viittä kyynärää pitkä ja oli kiinni toisen kerubin siivessä.'),
(1680155,58,14,3,13,'Näin nämä kerubit levittivät siipensä kahtakymmentä kyynärää laajalti; ja ne seisoivat jaloillaan, kasvot käännettyinä huoneeseen päin.'),
(1680156,58,14,3,14,'Ja hän teki esiripun punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja valkoisista pellavalangoista ja laittoi siihen kerubeja.'),
(1680157,58,14,3,15,'Ja hän teki temppelin eteen kaksi pylvästä, kolmenkymmenen viiden kyynärän korkuista; ja pylväänpää, joka oli niiden päässä, oli viittä kyynärää korkea.'),
(1680158,58,14,3,16,'Ja hän teki vitjoja kaikkeinpyhimpään, ja hän pani niitä pylväitten päähän; ja hän teki sata granaattiomenaa ja asetti ne vitjoihin.'),
(1680159,58,14,3,17,'Ja hän pystytti pylväät temppelin eteen, toisen oikealle puolelle ja toisen vasemmalle puolelle: oikeanpuoliselle hän antoi nimen Jaakin ja vasemmanpuoliselle nimen Booas.'),
(1680160,58,14,4,1,'Hän teki alttarin vaskesta, kahtakymmentä kyynärää pitkän, kahtakymmentä kyynärää leveän ja kymmentä kyynärää korkean.'),
(1680161,58,14,4,2,'Hän teki myös meren, valetun, kymmentä kyynärää leveän reunasta reunaan, ympärinsä pyöreän, ja viittä kyynärää korkean; ja kolmenkymmenen kyynärän pituinen mittanuora ulottui sen ympäri.'),
(1680162,58,14,4,3,'Ja sen alaosassa oli yltympäri raavaankuvia, jotka kulkivat sen ympäri; ne ympäröivät merta yltympäri, kymmenen kullakin kyynärällä. Raavaita oli kahdessa rivissä, valettuina meren kanssa yhteen.'),
(1680163,58,14,4,4,'Ja se seisoi kahdentoista raavaan varassa, joista kolme oli käännettynä pohjoiseen, kolme länteen, kolme etelään ja kolme itään päin; meri oli niiden yläpuolella, niiden varassa, ja kaikkien niiden takapuolet olivat sisään päin.'),
(1680164,58,14,4,5,'Se oli kämmenen paksuinen, ja sen reuna oli maljan reunan kaltainen, puhjenneen liljan muotoinen. Siihen mahtui, se veti kolmetuhatta bat-mittaa.'),
(1680165,58,14,4,6,'Hän teki myös kymmenen allasta ja asetti viisi oikealle puolelle ja viisi vasemmalle puolelle pesemistä varten; sillä niissä huuhdottiin se, mikä kuului polttouhriin. Mutta meri oli pappien peseytymistä varten.'),
(1680166,58,14,4,7,'Hän teki myös kymmenen kultaista lampunjalkaa, niinkuin niistä oli säädetty, ja pani ne temppelisaliin, viisi oikealle puolelle ja viisi vasemmalle puolelle.'),
(1680167,58,14,4,8,'Hän teki myös kymmenen pöytää ja asetti ne temppelisaliin, viisi oikealle puolelle ja viisi vasemmalle puolelle. Hän teki myös sata kultamaljaa.'),
(1680168,58,14,4,9,'Ja hän teki pappien esipihan ja suuren esikartanon sekä esikartanon ovet; ja ovet hän päällysti vaskella.'),
(1680169,58,14,4,10,'Ja meren hän asetti oikealle sivulle, kaakkoa kohti.'),
(1680170,58,14,4,11,'Huuram teki myös kattilat, lapiot ja maljat. Ja niin Huuram sai suoritetuksi työn, mikä hänen oli tehtävä kuningas Salomolle Jumalan temppeliin:'),
(1680171,58,14,4,12,'kaksi pylvästä ja kaksi palloa, pylväänpäätä, pylväiden päähän, ja kaksi ristikkokoristetta peittämään kahta pallonmuotoista pylväänpäätä, jotka olivat pylväitten päässä,'),
(1680172,58,14,4,13,'ja neljäsataa granaattiomenaa kahteen ristikkokoristeeseen, kaksi riviä granaattiomenia kumpaankin ristikkokoristeeseen, peittämään kahta pallonmuotoista pylväänpäätä, jotka olivat pylväitten päällä.'),
(1680173,58,14,4,14,'Ja hän teki telineet ja teki altaat telineitten päälle,'),
(1680174,58,14,4,15,'Ja yhden meren ja kaksitoista raavasta sen alle.'),
(1680175,58,14,4,16,'Ja kattilat, lapiot ja haarukat ynnä kaikki niihin kuuluvat kalut Huuram-Aabiv teki kuningas Salomolle Herran temppeliin kiilloitetusta vaskesta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680176,58,14,4,17,'Jordanin lakeudella kuningas ne valatti savimuotteihin, Sukkotin ja Seredan välillä.'),
(1680177,58,14,4,18,'Ja Salomo teetti kaikkia näitä kaluja ylen paljon, sillä vasken painoa ei määrätty.'),
(1680178,58,14,4,19,'Salomo teetti myös kaikki kalut, joita tuli olla Herran temppelissä: kulta-alttarin, pöydät, joilla näkyleivät olivat,'),
(1680179,58,14,4,20,'lampunjalat lamppuineen, jotka oli sytytettävä säädetyllä tavalla kaikkeinpyhimmän eteen, puhtaasta kullasta,'),
(1680180,58,14,4,21,'kultaisine kukkalehtineen, lamppuineen ja lamppusaksineen - puhtainta kultaa;'),
(1680181,58,14,4,22,'veitset, maljat, kupit ja hiilipannut puhtaasta kullasta; ja temppelin oviaukkojen sisemmät ovet, jotka veivät kaikkeinpyhimpään, sekä ne temppelin ovet, jotka veivät temppelisaliin, kullasta.'),
(1680182,58,14,5,1,'Kun kaikki työ, minkä Salomo teetti Herran temppeliin, oli valmis, vei Salomo sinne isänsä Daavidin pyhät lahjat. Hopean, kullan ja kaikki kalut hän pani Jumalan temppelin aarrekammioihin.'),
(1680183,58,14,5,2,'Sitten Salomo kokosi Israelin vanhimmat ja kaikki sukukuntien johtomiehet, israelilaisten perhekunta-päämiehet, Jerusalemiin, tuomaan Herran liitonarkkia Daavidin kaupungista, se on Siionista.'),
(1680184,58,14,5,3,'Niin kokoontuivat kuninkaan luo kaikki Israelin miehet juhlapäivänä, joka on seitsemännessä kuussa.'),
(1680185,58,14,5,4,'Ja kun kaikki Israelin vanhimmat olivat tulleet saapuville, nostivat leeviläiset arkin,'),
(1680186,58,14,5,5,'ja he veivät arkin ja ilmestysmajan sinne, sekä kaiken pyhän kaluston, joka oli majassa; leeviläiset papit veivät ne sinne.'),
(1680187,58,14,5,6,'Ja kuningas Salomo seisoi arkin edessä ynnä koko Israelin kansa, joka oli kokoontunut hänen luoksensa; ja he uhrasivat lampaita ja raavaita niin paljon, että niitä ei voitu luetella eikä laskea.'),
(1680188,58,14,5,7,'Ja papit toivat Herran liitonarkin paikoilleen temppelin kuoriin, kaikkeinpyhimpään, kerubien siipien alle.'),
(1680189,58,14,5,8,'Sillä kerubit levittivät siipensä sen paikan ylitse, missä arkki oli, ja niin kerubit peittivät ylhäältä päin arkin ja sen korennot.'),
(1680190,58,14,5,9,'Ja korennot olivat niin pitkät, että niiden arkista ulkonevat päät voi nähdä kaikkeinpyhimmän edustalta, mutta ulkoa niitä ei voinut nähdä. Ja ne jäivät sinne tähän päivään asti.'),
(1680191,58,14,5,10,'Arkissa ei ollut muuta kuin ne kaksi taulua, jotka Mooses oli pannut sinne Hoorebilla, kun Herra oli tehnyt liiton israelilaisten kanssa, heidän lähdettyänsä Egyptistä.'),
(1680192,58,14,5,11,'Kun papit lähtivät pyhäköstä - sillä kaikki siellä olevat papit olivat pyhittäneet itsensä, osastoihin katsomatta;'),
(1680193,58,14,5,12,'ja kaikki leeviläiset veisaajat, Aasaf, Heeman ja Jedutun poikinensa ja veljinensä, seisoivat hienoihin pellavavaatteisiin puettuina kymbaaleineen, harppuineen ja kanteleineen itään päin alttarista, ja heidän kanssaan sata kaksikymmentä pappia, jotka puhalsivat torviin;'),
(1680194,58,14,5,13,'ja puhaltajien ja veisaajien oli yhdyttävä yhtaikaa ja yhteen ääneen ylistämään ja kiittämään Herraa - ja kun torvet, kymbaalit ja muut soittokoneet soivat ja viritettiin Herran ylistys: "Sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti", silloin pilvi täytti huoneen, Herran temppelin,'),
(1680195,58,14,5,14,'niin että papit eivät voineet astua toimittamaan virkaansa pilven tähden; sillä Herran kirkkaus täytti Jumalan temppelin.'),
(1680196,58,14,6,1,'Silloin Salomo sanoi: "Herra on sanonut tahtovansa asua pimeässä.'),
(1680197,58,14,6,2,'Mutta minä olen rakentanut huoneen sinulle asunnoksi, asuinsijan, asuaksesi siinä iäti."'),
(1680198,58,14,6,3,'Sitten kuningas käänsi kasvonsa ja siunasi koko Israelin seurakunnan; ja koko Israelin seurakunta seisoi.'),
(1680199,58,14,6,4,'Hän sanoi: "Kiitetty olkoon Herra, Israelin Jumala, joka kädellänsä on täyttänyt sen, mitä hän suullansa puhui minun isälleni Daavidille, sanoen:'),
(1680200,58,14,6,5,'''Siitä päivästä saakka, jona minä vein kansani Egyptistä, en minä ole mistään Israelin sukukunnasta valinnut yhtään kaupunkia, että siihen rakennettaisiin temppeli, missä minun nimeni asuisi, enkä myöskään ole valinnut ketään olemaan kansani Israelin ruhtinaana.'),
(1680201,58,14,6,6,'Mutta Jerusalemin minä olen valinnut nimeni asuinsijaksi, ja Daavidin minä olen valinnut vallitsemaan kansaani Israelia.'''),
(1680202,58,14,6,7,'Ja minun isäni Daavid aikoi rakentaa temppelin Herran, Israelin Jumalan, nimelle.'),
(1680203,58,14,6,8,'Mutta Herra sanoi minun isälleni Daavidille: ''Kun sinä aiot rakentaa temppelin minun nimelleni, niin tosin teet siinä hyvin, että sitä aiot;'),
(1680204,58,14,6,9,'kuitenkaan et sinä ole sitä temppeliä rakentava, vaan sinun poikasi, joka lähtee sinun kupeistasi, hän on rakentava temppelin minun nimelleni''.'),
(1680205,58,14,6,10,'Ja Herra on täyttänyt sanansa, minkä hän puhui: minä olen noussut isäni Daavidin sijalle ja istun Israelin valtaistuimella, niinkuin Herra puhui, ja minä olen rakentanut temppelin Herran, Israelin Jumalan, nimelle.'),
(1680206,58,14,6,11,'Ja minä olen sijoittanut siihen arkin, jossa on se Herran liitto, minkä hän teki israelilaisten kanssa."'),
(1680207,58,14,6,12,'Sitten hän astui Herran alttarin eteen koko Israelin seurakunnan nähden ja ojensi kätensä.'),
(1680208,58,14,6,13,'Salomo oli näet teettänyt lavan vaskesta, viittä kyynärää pitkän, viittä kyynärää leveän ja kolmea kyynärää korkean, ja asettanut sen esikartanon keskelle. Sille hän nousi, polvistui koko Israelin seurakunnan nähden, ojensi kätensä taivasta kohti'),
(1680209,58,14,6,14,'ja sanoi: "Herra, Israelin Jumala, ei ole sinun vertaistasi Jumalaa, ei taivaassa eikä maan päällä, sinun, joka pidät liiton ja säilytät laupeuden palvelijoitasi kohtaan, jotka vaeltavat sinun edessäsi kaikesta sydämestänsä.'),
(1680210,58,14,6,15,'Sinä olet pitänyt, mitä puhuit palvelijallesi Daavidille, minun isälleni. Minkä sinä suullasi puhuit, sen sinä kädelläsi täytit, niinkuin nyt on tapahtunut.'),
(1680211,58,14,6,16,'Niin pidä nytkin, Herra, Israelin Jumala, mitä puhuit palvelijallesi Daavidille, minun isälleni, sanoen: ''Aina on mies sinun suvustasi oleva minun edessäni, istumassa Israelin valtaistuimella, jos vain sinun poikasi pitävät vaarin teistänsä, niin että he vaeltavat minun lakini mukaan, niinkuin sinä olet minun edessäni vaeltanut''.'),
(1680212,58,14,6,17,'Niin toteutukoon nyt, Herra, Israelin Jumala, sinun sanasi, jonka puhuit palvelijallesi Daavidille.'),
(1680213,58,14,6,18,'Mutta asuuko todella Jumala maan päällä ihmisten seassa? Katso, taivaisiin ja taivasten taivaisiin sinä et mahdu; kuinka sitten tähän temppeliin, jonka minä olen rakentanut!'),
(1680214,58,14,6,19,'Käänny kuitenkin palvelijasi rukouksen ja anomisen puoleen, Herra, minun Jumalani, niin että kuulet huudon ja rukouksen, jonka palvelijasi sinun edessäsi rukoilee,'),
(1680215,58,14,6,20,'ja että silmäsi ovat päivät ja yöt avoinna tätä temppeliä kohti, tätä paikkaa kohti, johon sinä olet sanonut asettavasi nimesi, niin että kuulet rukouksen, jonka palvelijasi tähän paikkaan päin kääntyneenä rukoilee.'),
(1680216,58,14,6,21,'Kuule palvelijasi ja kansasi Israelin rukoukset, jotka he rukoilevat tähän paikkaan päin kääntyneinä; kuule asuinpaikastasi, taivaasta, ja kun kuulet, niin anna anteeksi.'),
(1680217,58,14,6,22,'Jos joku rikkoo lähimmäistänsä vastaan ja hänet pannaan valalle ja vannotetaan, ja jos hän tulee ja vannoo sinun alttarisi edessä tässä temppelissä,'),
(1680218,58,14,6,23,'niin kuule taivaasta ja auta palvelijasi oikeuteensa; tee niin, että kostat syylliselle ja annat hänen tekojensa tulla hänen päänsä päälle, mutta julistat syyttömän syyttömäksi ja annat hänelle hänen vanhurskautensa mukaan.'),
(1680219,58,14,6,24,'Jos vihollinen voittaa sinun kansasi Israelin, sentähden että he ovat tehneet syntiä sinua vastaan, mutta he kääntyvät ja kiittävät sinun nimeäsi, rukoilevat ja anovat armoa sinun kasvojesi edessä tässä temppelissä,'),
(1680220,58,14,6,25,'niin kuule taivaasta ja anna anteeksi kansasi Israelin synti ja tuo heidät takaisin tähän maahan, jonka olet antanut heille ja heidän isillensä.'),
(1680221,58,14,6,26,'Jos taivas suljetaan, niin ettei tule sadetta, koska he ovat tehneet syntiä sinua vastaan, mutta he rukoilevat kääntyneinä tähän paikkaan päin ja ylistävät sinun nimeäsi ja kääntyvät synnistänsä, koska sinä nöyryytät heitä,'),
(1680222,58,14,6,27,'niin kuule taivaasta ja anna anteeksi palvelijaisi ja kansasi Israelin synti - sillä sinä osoitat heille hyvän tien, jota heidän on vaeltaminen - ja suo sade maallesi, jonka olet antanut kansallesi perintöosaksi.'),
(1680223,58,14,6,28,'Jos maahan tulee nälänhätä, rutto, jos tulee nokitähkä ja viljanruoste, jos tulevat heinäsirkat ja tuhosirkat, jos sen viholliset ahdistavat sitä maassa, jossa sen portit ovat, jos tulee mikä tahansa vitsaus tai vaiva,'),
(1680224,58,14,6,29,'ja jos silloin joku ihminen, kuka hyvänsä, tai koko sinun kansasi Israel, rukoilee ja anoo armoa, kun he kukin tuntevat vitsauksen ja tuskan, joka on kohdannut heitä, ja ojentavat kätensä tähän temppeliin päin,'),
(1680225,58,14,6,30,'niin kuule silloin taivaasta, asuinpaikastasi, ja anna anteeksi ja anna jokaiselle aivan hänen tekojensa mukaan, koska sinä tunnet hänen sydämensä - sillä sinä yksin tunnet ihmislasten sydämet -');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680226,58,14,6,31,'että he pelkäisivät sinua ja vaeltaisivat sinun teitäsi, niin kauan kuin he elävät tässä maassa, jonka sinä olet meidän isillemme antanut.'),
(1680227,58,14,6,32,'Myös jos joku muukalainen, joka ei ole sinun kansaasi Israelia, tulee kaukaisesta maasta sinun suuren nimesi, väkevän kätesi ja ojennetun käsivartesi tähden - jos hän tulee ja rukoilee kääntyneenä tähän temppeliin päin,'),
(1680228,58,14,6,33,'niin kuule taivaasta, asuinpaikastasi, häntä ja tee kaikki, mitä muukalainen sinulta rukoilee, että kaikki maan kansat tuntisivat sinun nimesi ja pelkäisivät sinua, samoin kuin sinun kansasi Israel, ja tulisivat tietämään, että sinä olet ottanut nimiisi tämän temppelin, jonka minä olen rakentanut.'),
(1680229,58,14,6,34,'Jos sinun kansasi lähtee sotaan vihollisiansa vastaan sitä tietä, jota sinä heidät lähetät, ja he rukoilevat sinua kääntyneinä tähän kaupunkiin päin, jonka sinä olet valinnut, ja tähän temppeliin päin, jonka minä olen sinun nimellesi rakentanut,'),
(1680230,58,14,6,35,'niin kuule taivaasta heidän rukouksensa ja anomisensa ja hanki heille oikeus.'),
(1680231,58,14,6,36,'Jos he tekevät syntiä sinua vastaan - sillä ei ole ihmistä, joka ei syntiä tee - ja sinä vihastut heihin ja annat heidät vihollisen valtaan, niin että heidän vangitsijansa vievät heidät vangeiksi kaukaiseen tai läheiseen maahan,'),
(1680232,58,14,6,37,'mutta jos he sitten menevät itseensä siinä maassa, johon heidät on viety vangeiksi, kääntyvät ja anovat sinulta armoa vankeutensa maassa, sanoen: ''Me olemme tehneet syntiä, tehneet väärin ja olleet jumalattomat'','),
(1680233,58,14,6,38,'ja palajavat sinun tykösi kaikesta sydämestään ja kaikesta sielustaan vankeutensa maassa, johon heidät on vangeiksi viety, ja rukoilevat kääntyneinä tähän maahan päin, jonka sinä olet heidän isillensä antanut, tähän kaupunkiin päin, jonka sinä olet valinnut, ja tähän temppeliin päin, jonka minä olen sinun nimellesi rakentanut,'),
(1680234,58,14,6,39,'niin kuule taivaasta, asuinpaikastasi, heidän rukouksensa ja anomisensa, hanki heille oikeus ja anna anteeksi kansallesi, mitä he ovat rikkoneet sinua vastaan.'),
(1680235,58,14,6,40,'Olkoot siis, minun Jumalani, sinun silmäsi avoinna, ja tarkatkoot sinun korvasi rukouksia tässä paikassa.'),
(1680236,58,14,6,41,'Ja nyt: Nouse, Herra Jumala, tule leposijaasi, sinä ja sinun voimasi arkki. Sinun pappisi, Herra Jumala, olkoot puetut autuuteen, ja sinun hurskaasi riemuitkoot siitä, mikä hyvä on.'),
(1680237,58,14,6,42,'Herra Jumala, älä hylkää voideltuasi; muista armolupauksiasi, jotka annoit Daavidille, palvelijallesi."'),
(1680238,58,14,7,1,'Kun Salomo oli lakannut rukoilemasta, tuli taivaasta tuli ja kulutti polttouhrin ja teurasuhrit, ja Herran kirkkaus täytti temppelin,'),
(1680239,58,14,7,2,'niin että papit eivät voineet mennä Herran temppeliin; sillä Herran kirkkaus täytti Herran temppelin.'),
(1680240,58,14,7,3,'Ja kun kaikki israelilaiset näkivät tulen tulevan alas ja näkivät temppelin päällä Herran kirkkauden, polvistuivat he kivillä lasketulla pihalla kasvoillensa maahan ja rukoilivat ja kiittivät Herraa siitä, että hän on hyvä, että hänen armonsa pysyy iankaikkisesti.'),
(1680241,58,14,7,4,'Sitten kuningas ja kaikki kansa uhrasivat teurasuhrin Herran edessä.'),
(1680242,58,14,7,5,'Ja kuningas Salomo uhrasi teurasuhrina kaksikymmentäkaksi tuhatta raavasta ja satakaksikymmentä tuhatta lammasta. Näin he, kuningas ja koko kansa, vihkivät Herran temppelin.'),
(1680243,58,14,7,6,'Papit seisoivat kukin virkatoimessaan. Ja leeviläiset, käsissään Herran soittimet, jotka kuningas Daavid oli teettänyt, seisoivat kiittämässä Herraa Daavidin ylistysvirsillä siitä, että hänen armonsa pysyy iankaikkisesti. Ja heitä vastapäätä papit soittivat torvia, kaiken Israelin seisoessa.'),
(1680244,58,14,7,7,'Ja Salomo pyhitti Herran temppelin edessä olevan esipihan keskiosan, sillä hänen oli siellä uhrattava polttouhri ja yhteysuhrin rasvat, koska polttouhri, ruokauhri ja rasvat eivät mahtuneet vaskialttarille, jonka Salomo oli teettänyt.'),
(1680245,58,14,7,8,'Näin Salomo siihen aikaan vietti juhlaa seitsemän päivää, ja koko Israel hänen kanssansa. Se oli sangen suuri kokous, johon kokoonnuttiin aina sieltä, mistä mennään Hamatiin, ja aina Egyptin purolta asti.'),
(1680246,58,14,7,9,'Kahdeksantena päivänä heillä oli juhlakokous. Sillä alttarin vihkimistä he viettivät seitsemän päivää ja juhlaa seitsemän päivää.'),
(1680247,58,14,7,10,'Mutta seitsemännen kuun kahdentenakymmenentenä kolmantena päivänä hän päästi kansan menemään majoillensa. He iloitsivat ja olivat hyvillä mielin siitä hyvästä, minkä Herra oli tehnyt Daavidille ja Salomolle ja kansallensa Israelille.'),
(1680248,58,14,7,11,'Kun Salomo oli saanut valmiiksi Herran temppelin ja kuninkaan linnan ja menestynyt kaikessa, mitä oli ajatellut tehdä Herran temppelissä ja omassa linnassaan,'),
(1680249,58,14,7,12,'ilmestyi Herra Salomolle yöllä ja sanoi hänelle: "Minä olen kuullut sinun rukouksesi ja valinnut tämän paikan uhripaikakseni.'),
(1680250,58,14,7,13,'Jos minä suljen taivaan, niin ettei tule sadetta, jos minä käsken heinäsirkkain syödä maan tahi jos minä lähetän ruton kansaani,'),
(1680251,58,14,7,14,'mutta minun kansani, joka on otettu minun nimiini, nöyrtyy, ja he rukoilevat ja etsivät minun kasvojani ja palajavat pahoilta teiltänsä, niin minä kuulen taivaasta ja annan anteeksi heidän syntinsä ja teen heidän maansa jälleen terveeksi.'),
(1680252,58,14,7,15,'Nyt minun silmäni ovat avoinna, ja minun korvani tarkkaavat rukouksia tässä paikassa.'),
(1680253,58,14,7,16,'Ja nyt minä olen valinnut ja pyhittänyt tämän temppelin, että minun nimeni olisi siinä iäti; ja minun silmäni ja sydämeni tulevat aina olemaan siinä.'),
(1680254,58,14,7,17,'Ja jos sinä vaellat minun edessäni, niinkuin sinun isäsi Daavid vaelsi, ja teet kaiken, mitä minä olen käskenyt sinun tehdä, ja noudatat minun käskyjäni ja oikeuksiani,'),
(1680255,58,14,7,18,'niin minä pidän pystyssä sinun kuninkaallisen valtaistuimesi, niinkuin minä lupasin sinun isällesi Daavidille sanoen: ''Aina on mies sinun suvustasi hallitseva Israelia''.'),
(1680256,58,14,7,19,'Mutta jos te käännytte pois ja hylkäätte minun käskyni ja säädökseni, jotka minä olen teille antanut, ja menette ja palvelette muita jumalia ja kumarratte niitä,'),
(1680257,58,14,7,20,'niin minä kiskaisen sellaiset irti maastani, jonka minä olen heille antanut; ja tämän temppelin, jonka minä olen nimelleni pyhittänyt, minä heitän pois kasvojeni edestä, ja minä teen sen sananparreksi ja pistopuheeksi kaikille kansoille.'),
(1680258,58,14,7,21,'Ja tämän temppelin tähden, joka ennen oli korkein, on jokainen ohikulkija tyrmistyvä. Ja kun hän kysyy: ''Miksi on Herra näin tehnyt tälle maalle ja tälle temppelille?'','),
(1680259,58,14,7,22,'niin vastataan: ''Siksi, että he hylkäsivät Herran, isiensä Jumalan, joka oli vienyt heidät pois Egyptin maasta, ja liittyivät muihin jumaliin, kumarsivat niitä ja palvelivat niitä; sentähden hän on antanut kaiken tämän pahan heitä kohdata''."'),
(1680260,58,14,8,1,'Niiden kahdenkymmenen vuoden kuluttua, joina Salomo oli rakentanut Herran temppelin ja oman linnansa,'),
(1680261,58,14,8,2,'linnoitti Salomo ne kaupungit, jotka Huuram oli antanut hänelle, ja hän asetti israelilaisia niihin asumaan.'),
(1680262,58,14,8,3,'Ja Salomo meni Hamat-Soobaan ja valloitti sen.'),
(1680263,58,14,8,4,'Hän linnoitti myös Tadmorin erämaassa ja kaikki varastokaupungit, jotka hän oli rakentanut Hamatiin.'),
(1680264,58,14,8,5,'Vielä hän linnoitti Ylä-Beet-Hooronin ja Ala-Beet-Hooronin muureilla, porteilla ja salvoilla varustetuiksi kaupungeiksi;'),
(1680265,58,14,8,6,'samoin Baalatin ja kaikki varastokaupungit, jotka hänellä oli, ja kaikki vaunukaupungit ja ratsumiesten kaupungit ja kaikki muut paikat, mitkä hän tahtoi linnoittaa Jerusalemissa ja Libanonilla ja kaikessa hallitsemassaan maassa.'),
(1680266,58,14,8,7,'Kaiken kansan, mitä oli jäänyt jäljelle heettiläisistä, amorilaisista, perissiläisistä, hivviläisistä ja jebusilaisista, kaikki, jotka eivät olleet israelilaisia,'),
(1680267,58,14,8,8,'ne niiden jälkeläiset, jotka vielä olivat jäljellä maassa ja joita israelilaiset eivät olleet tuhonneet, ne Salomo saattoi työveron alaisiksi, aina tähän päivään asti.'),
(1680268,58,14,8,9,'Mutta israelilaisista Salomo ei tehnyt ketään työorjakseen, vaan heitä oli sotilaina, hänen vaunusoturiensa päällikköinä ja hänen sotavaunujensa ja ratsumiestensä päällikköinä.'),
(1680269,58,14,8,10,'Maaherrojen virkamiehiä oli Salomolla kaksisataa viisikymmentä, jotka vallitsivat väkeä.'),
(1680270,58,14,8,11,'Ja Salomo toi faraon tyttären Daavidin kaupungista linnaan, jonka hän oli tälle rakentanut; sillä hän sanoi: "Älköön nainen asuko Daavidin, Israelin kuninkaan, linnassa; sillä se on pyhäkkö, koska Herran arkki on tullut sinne".'),
(1680271,58,14,8,12,'Siihen aikaan Salomo uhrasi polttouhreja Herralle Herran alttarilla, jonka hän oli rakentanut eteisen eteen.'),
(1680272,58,14,8,13,'Hän uhrasi kunakin päivänä sen päivän uhrit Mooseksen käskyn mukaan, sapatteina ja uudenkuun päivinä sekä juhlina kolme kertaa vuodessa: happamattoman leivän juhlana, viikkojuhlana ja lehtimajanjuhlana.'),
(1680273,58,14,8,14,'Ja hän asetti, niinkuin hänen isänsä Daavid oli säätänyt, pappien osastot toimittamaan virkaansa ja leeviläiset suorittamaan tehtäviänsä, veisaamaan ylistysvirsiä ja palvelemaan pappeja, kunakin päivänä sen päivän tehtävissä, sekä ovenvartijat osastoittain joka ovelle, sillä niin oli Jumalan mies Daavid käskenyt.'),
(1680274,58,14,8,15,'Eikä missään poikettu kuninkaan käskyistä, mitä tuli pappeihin, leeviläisiin ja aarrekammioihin.'),
(1680275,58,14,8,16,'Ja niin suoritettiin Salomon kaikki työt, Herran temppelin perustamispäivään asti, sekä siihen saakka, kunnes se valmistui. Niin oli Herran temppeli valmis.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680276,58,14,8,17,'Siihen aikaan Salomo meni Esjon-Geberiin ja Elatiin, joka on meren rannalla Edomin maassa.'),
(1680277,58,14,8,18,'Ja Huuram lähetti palvelijansa tuomaan hänelle laivoja. Palvelijat olivat meritaitoisia ja menivät yhdessä Salomon palvelijain kanssa Oofiriin ja noutivat sieltä kultaa neljäsataa viisikymmentä talenttia ja toivat sen kuningas Salomolle.'),
(1680278,58,14,9,1,'Kun Saban kuningatar kuuli Salomon maineen, tuli hän Jerusalemiin koettelemaan Salomoa arvoituksilla. Hän tuli sangen suuren seurueen kanssa, mukanaan kameleja, jotka kantoivat hajuaineita, kultaa ylen paljon ja kalliita kiviä. Ja kun hän tuli Salomon luo, puhui hän tälle kaikki, mitä hänellä oli mielessänsä.'),
(1680279,58,14,9,2,'Mutta Salomo selitti hänelle kaikki hänen kysymyksensä; Salomolle ei mikään jäänyt ongelmaksi, jota hän ei olisi hänelle selittänyt.'),
(1680280,58,14,9,3,'Kun Saban kuningatar näki kaiken Salomon viisauden, linnan, jonka hän oli rakentanut,'),
(1680281,58,14,9,4,'ruuat hänen pöydällänsä, kuinka hänen palvelijansa asuivat ja hänen palvelusväkensä palveli ja kuinka he olivat puetut, ja näki hänen juomanlaskijansa ja kuinka he olivat puetut, ja hänen yläsalinsa, josta hän nousi Herran temppeliin, meni hän miltei hengettömäksi.'),
(1680282,58,14,9,5,'Sitten hän sanoi kuninkaalle: "Totta oli se puhe, jonka minä kotimaahani sinusta ja sinun viisaudestasi kuulin.'),
(1680283,58,14,9,6,'Minä en uskonut, mitä sanottiin, ennenkuin itse tulin ja sain omin silmin nähdä; ja katso, ei puoltakaan sinun suuresta viisaudestasi oltu minulle kerrottu. Sinä olet paljon suurempi, kuin minä olin kuullut huhuttavan.'),
(1680284,58,14,9,7,'Onnellisia ovat sinun miehesi, onnellisia nämä palvelijasi, jotka aina saavat olla sinun edessäsi ja kuulla sinun viisauttasi.'),
(1680285,58,14,9,8,'Kiitetty olkoon Herra, sinun Jumalasi, joka sinuun on niin mielistynyt, että on asettanut sinut valtaistuimellensa olemaan kuninkaana Herran, sinun Jumalasi, kunniaksi. Sentähden, että sinun Jumalasi rakastaa Israelia ja tahtoo pitää sen pystyssä ainiaan, on hän antanut sinut heille kuninkaaksi, tekemään sitä, mikä oikeus ja vanhurskaus on."'),
(1680286,58,14,9,9,'Ja hän antoi kuninkaalle sata kaksikymmentä talenttia kultaa, sangen paljon hajuaineita ja kalliita kiviä. Ei milloinkaan ole ollut moisia hajuaineita kuin ne, jotka Saban kuningatar antoi kuningas Salomolle.'),
(1680287,58,14,9,10,'Huuramin palvelijat ja Salomon palvelijat, jotka toivat kultaa Oofirista, toivat myöskin santelipuuta ja kalliita kiviä.'),
(1680288,58,14,9,11,'Ja kuningas teetti santelipuusta portaat Herran temppeliin ja kuninkaan palatsiin ja kanteleita ja harppuja laulajille. Moisia ei oltu ennen nähty Juudan maassa.'),
(1680289,58,14,9,12,'Kuningas Salomo taas antoi Saban kuningattarelle kaikki, mitä tämä halusi ja pyysi, antoi vielä enemmän, kuin mitä tämä oli tuonut kuninkaalle. Sitten hän lähti paluumatkalle ja meni palvelijoineen omaan maahansa.'),
(1680290,58,14,9,13,'Kullan paino, mikä yhtenä vuotena tuli Salomolle, oli kuusisataa kuusikymmentä kuusi talenttia kultaa,'),
(1680291,58,14,9,14,'paitsi mitä kauppamiehet ja kaupustelijat toivat. Sen lisäksi kaikki Arabian kuninkaat ja maan käskynhaltijat toivat Salomolle kultaa ja hopeata.'),
(1680292,58,14,9,15,'Ja kuningas Salomo teetti kaksisataa suurta kilpeä pakotetusta kullasta ja käytti jokaiseen kilpeen kuusisataa sekeliä pakotettua kultaa;'),
(1680293,58,14,9,16,'samoin kolmesataa pienempää kilpeä pakotetusta kullasta, ja käytti jokaiseen kilpeen kolmesataa sekeliä kultaa. Ja kuningas asetti ne Libanoninmetsä-taloon.'),
(1680294,58,14,9,17,'Vielä kuningas teetti suuren norsunluisen valtaistuimen ja päällysti sen puhtaalla kullalla.'),
(1680295,58,14,9,18,'Valtaistuimessa oli kuusi porrasta ja astinlauta, kullalla kiinnitettyinä valtaistuimeen. Istuimen kummallakin puolella oli käsinoja, ja kaksi leijonaa seisoi käsinojan vieressä.'),
(1680296,58,14,9,19,'Ja kaksitoista leijonaa seisoi siinä kuudella portaalla, kummallakin puolella. Senkaltaista ei ole tehty missään muussa valtakunnassa.'),
(1680297,58,14,9,20,'Ja kaikki kuningas Salomon juoma-astiat olivat kultaa, ja kaikki Libanoninmetsä-talon astiat olivat puhdasta kultaa. Hopeata ei Salomon päivinä pidetty minkään arvoisena.'),
(1680298,58,14,9,21,'Kuninkaalla oli näet laivoja, jotka kulkivat Tarsiiseen Huuramin palvelijain kanssa; kerran kolmessa vuodessa Tarsiin-laivat tulivat ja toivat kultaa ja hopeata, norsunluuta, apinoita ja riikinkukkoja.'),
(1680299,58,14,9,22,'Ja kuningas Salomo oli kaikkia maan kuninkaita suurempi rikkaudessa ja viisaudessa.'),
(1680300,58,14,9,23,'Ja kaikki maan kuninkaat pyrkivät näkemään Salomoa kuullaksensa hänen viisauttaan, jonka Jumala oli antanut hänen sydämeensä.'),
(1680301,58,14,9,24,'Ja he toivat kukin lahjansa: hopea- ja kultakaluja, vaatteita, aseita, hajuaineita, hevosia ja muuleja, joka vuosi vuoden tarpeen.'),
(1680302,58,14,9,25,'Salomolla oli neljätuhatta hevosvaljakkoa vaunuineen ja kaksitoista tuhatta ratsumiestä; ne hän sijoitti vaunukaupunkeihin ja kuninkaan luo Jerusalemiin.'),
(1680303,58,14,9,26,'Ja hän vallitsi kaikkia kuninkaita Eufrat-virrasta aina filistealaisten maahan ja Egyptin rajaan asti.'),
(1680304,58,14,9,27,'Ja kuningas toimitti niin, että Jerusalemissa oli hopeata kuin kiviä, ja setripuuta niin paljon kuin metsäviikunapuita Alankomaassa.'),
(1680305,58,14,9,28,'Ja hevosia tuotiin Salomolle Egyptistä ja kaikista muista maista.'),
(1680306,58,14,9,29,'Mitä muuta Salomosta on kerrottavaa, hänen sekä aikaisemmista että myöhemmistä vaiheistaan, se on kirjoitettuna profeetta Naatanin historiassa, siilolaisen Ahian ennustuksessa ja näkijä Jeddon näyssä Jerobeamista, Nebatin pojasta.'),
(1680307,58,14,9,30,'Salomo hallitsi Jerusalemissa koko Israelia neljäkymmentä vuotta.'),
(1680308,58,14,9,31,'Sitten Salomo meni lepoon isiensä tykö, ja hänet haudattiin isänsä Daavidin kaupunkiin. Ja hänen poikansa Rehabeam tuli kuninkaaksi hänen sijaansa.'),
(1680309,58,14,10,1,'Rehabeam meni Sikemiin, sillä koko Israel oli tullut Sikemiin tekemään häntä kuninkaaksi.'),
(1680310,58,14,10,2,'Kun Jerobeam, Nebatin poika, kuuli sen - hän oli Egyptissä, jonne oli paennut kuningas Salomoa - palasi Jerobeam Egyptistä.'),
(1680311,58,14,10,3,'Ja he lähettivät kutsumaan hänet. Niin Jerobeam ja koko Israel tuli saapuville, ja he puhuivat Rehabeamille sanoen:'),
(1680312,58,14,10,4,'"Sinun isäsi teki meidän ikeemme raskaaksi; mutta huojenna sinä nyt se kova työ, jota isäsi teetti, ja se raskas ies, jonka hän pani meidän niskaamme, niin me palvelemme sinua".'),
(1680313,58,14,10,5,'Hän vastasi heille: "Odottakaa kolme päivää ja tulkaa sitten takaisin minun tyköni". Ja kansa meni.'),
(1680314,58,14,10,6,'Kuningas Rehabeam neuvotteli vanhain kanssa, jotka olivat palvelleet hänen isäänsä Salomoa, kun tämä vielä eli, ja kysyi: "Kuinka te neuvotte vastaamaan tälle kansalle?"'),
(1680315,58,14,10,7,'He vastasivat hänelle ja sanoivat: "Jos sinä olet hyvä tätä kansaa kohtaan, olet armollinen heille ja puhut heille hyviä sanoja, niin he ovat sinun palvelijoitasi kaiken elinaikasi".'),
(1680316,58,14,10,8,'Mutta hän hylkäsi tämän neuvon, jonka vanhat hänelle antoivat, ja neuvotteli nuorten miesten kanssa, jotka olivat kasvaneet hänen kanssaan ja jotka palvelivat häntä.'),
(1680317,58,14,10,9,'Hän kysyi heiltä: "Kuinka te neuvotte meitä vastaamaan tälle kansalle, joka on puhunut minulle sanoen: ''Huojenna se ies, jonka sinun isäsi on pannut meidän niskaamme''?"'),
(1680318,58,14,10,10,'Niin nuoret miehet, jotka olivat kasvaneet hänen kanssaan, vastasivat hänelle sanoen: "Sano näin tälle kansalle, joka on puhunut sinulle sanoen: ''Sinun isäsi teki meidän ikeemme raskaaksi, mutta huojenna sinä se meiltä'' - sano heille näin: ''Minun pikkusormeni on paksumpi kuin minun isäni lantio.'),
(1680319,58,14,10,11,'Jos siis isäni on sälyttänyt teidän selkäänne raskaan ikeen, niin minä teen teidän ikeenne vielä raskaammaksi; jos isäni on kurittanut teitä raipoilla, niin minä kuritan teitä piikkiruoskilla.''"'),
(1680320,58,14,10,12,'Niin Jerobeam ja koko kansa tuli Rehabeamin tykö kolmantena päivänä, niinkuin kuningas oli käskenyt, sanoen: "Tulkaa takaisin minun tyköni kolmantena päivänä".'),
(1680321,58,14,10,13,'Ja kuningas antoi heille kovan vastauksen. Sillä kuningas Rehabeam hylkäsi vanhain neuvon'),
(1680322,58,14,10,14,'ja puhui heille nuorten miesten neuvon mukaan, sanoen: "Jos minun isäni on tehnyt teidän ikeenne raskaaksi, niin minä teen sen vielä raskaammaksi; jos minun isäni on kurittanut teitä raipoilla, niin minä kuritan teitä piikkiruoskilla".'),
(1680323,58,14,10,15,'Kuningas ei siis kuullut kansaa; sillä Jumala sen niin salli täyttääkseen sanansa, jonka hän oli puhunut Jerobeamille, Nebatin pojalle, siilolaisen Ahian kautta.'),
(1680324,58,14,10,16,'Kun koko Israel huomasi, ettei kuningas heitä kuullut, vastasi kansa kuninkaalle näin: "Mitä osaa meillä on Daavidiin? Ei meillä ole perintöosaa Iisain poikaan. Majoillesi, Israel, joka mies! Valvo nyt huonettasi, Daavid!" Ja koko Israel meni majoillensa.'),
(1680325,58,14,10,17,'Niin Rehabeam tuli ainoastaan niiden israelilaisten kuninkaaksi, jotka asuivat Juudan kaupungeissa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680326,58,14,10,18,'Ja kun kuningas Rehabeam lähetti matkaan verotöiden valvojan Hadoramin, kivittivät israelilaiset hänet kuoliaaksi. Silloin kuningas Rehabeam nousi nopeasti vaunuihinsa ja pakeni Jerusalemiin.'),
(1680327,58,14,10,19,'Näin Israel luopui Daavidin suvusta, aina tähän päivään asti.'),
(1680328,58,14,11,1,'Kun Rehabeam tuli Jerusalemiin, kokosi hän Juudan heimon ja Benjaminin, sata kahdeksankymmentä tuhatta sotakuntoista valiomiestä, sotimaan Israelia vastaan ja palauttamaan kuninkuutta Rehabeamille.'),
(1680329,58,14,11,2,'Mutta Jumalan miehelle Semajalle tuli tämä Herran sana:'),
(1680330,58,14,11,3,'"Sano Rehabeamille, Salomon pojalle, Juudan kuninkaalle, ja koko Israelille Juudassa ja Benjaminissa näin:'),
(1680331,58,14,11,4,'''Näin sanoo Herra: Älkää menkö sotimaan veljiänne vastaan. Palatkaa kukin kotiinne, sillä minä olen sallinut tämän tapahtua.''" Niin he kuulivat Herran sanoja, kääntyivät takaisin eivätkä menneet Jerobeamia vastaan.'),
(1680332,58,14,11,5,'Mutta Rehabeam asui Jerusalemissa ja linnoitti lujasti Juudan kaupunkeja.'),
(1680333,58,14,11,6,'Hän linnoitti Beetlehemin, Eetanin, Tekoan,'),
(1680334,58,14,11,7,'Beet-Suurin, Sookon, Adullamin,'),
(1680335,58,14,11,8,'Gatin, Maaresan, Siifin,'),
(1680336,58,14,11,9,'Adoraimin, Laakiin, Asekan,'),
(1680337,58,14,11,10,'Soran, Aijalonin ja Hebronin, jotka ovat Juudassa ja Benjaminissa; ne hän linnoitti lujiksi kaupungeiksi.'),
(1680338,58,14,11,11,'Hän varusti linnoitukset ja sijoitti niihin päämiehiä sekä muonavarastoja, öljyä ja viiniä'),
(1680339,58,14,11,12,'ja jokaiseen kaupunkiin kilpiä ja keihäitä; hän varusti ne hyvin lujasti. Ja Juuda ja Benjamin olivat hänen.'),
(1680340,58,14,11,13,'Ja papit ja leeviläiset, mitä koko Israelissa oli, tulivat kaikilta alueiltaan ja asettuivat palvelemaan häntä.'),
(1680341,58,14,11,14,'Sillä leeviläiset jättivät laidunmaansa ja perintömaansa ja lähtivät Juudaan ja Jerusalemiin, koska Jerobeam ja hänen poikansa olivat hyljänneet heidät, niin etteivät he saaneet pappeina palvella Herraa,'),
(1680342,58,14,11,15,'Jerobeam kun oli asettanut itselleen pappeja uhrikukkuloita varten ja metsänpeikkoja varten ja vasikoita varten, jotka hän oli teettänyt.'),
(1680343,58,14,11,16,'Ja heitä seurasivat kaikista Israelin sukukunnista Jerusalemiin ne, jotka sydämestään antautuivat etsimään Herraa, Israelin Jumalaa, uhratakseen Herralle, isiensä Jumalalle.'),
(1680344,58,14,11,17,'Näin he vahvistivat Juudan valtakuntaa ja tukivat Rehabeamia, Salomon poikaa, kolme vuotta; sillä he vaelsivat Daavidin ja Salomon teitä kolme vuotta.'),
(1680345,58,14,11,18,'Ja Rehabeam otti vaimokseen Mahlatin, joka oli Daavidin pojan Jerimotin ja Iisain pojan Eliabin tyttären Abihailin tytär.'),
(1680346,58,14,11,19,'Tämä synnytti hänelle pojat Jeuksen, Semarjan ja Saahamin.'),
(1680347,58,14,11,20,'Hänen jälkeensä hän nai Maakan, Absalomin tyttären, joka synnytti hänelle Abian, Attain, Siisan ja Selomitin.'),
(1680348,58,14,11,21,'Ja Rehabeam rakasti Maakaa, Absalomin tytärtä, enemmän kuin kaikkia muita vaimojaan ja sivuvaimojaan. Sillä hän oli ottanut kahdeksantoista vaimoa ja kuusikymmentä sivuvaimoa; ja hänelle syntyi kaksikymmentä kahdeksan poikaa ja kuusikymmentä tytärtä.'),
(1680349,58,14,11,22,'Ja Rehabeam asetti Abian, Maakan pojan, päämieheksi, ruhtinaaksi hänen veljiensä joukossa, sillä hän aikoi tehdä hänet kuninkaaksi.'),
(1680350,58,14,11,23,'Ja viisaasti hän jakoi kaikki Juudan ja Benjaminin maakunnat ja kaikki varustetut kaupungit kaikkien poikiensa kesken ja antoi heille runsaasti elintarpeita ja hankki heille paljon vaimoja.'),
(1680351,58,14,12,1,'Kun Rehabeamin kuninkuus oli vahvistunut ja hän oli voimistunut, hylkäsi hän Herran lain, hän ja koko Israel hänen kanssaan.'),
(1680352,58,14,12,2,'Mutta kuningas Rehabeamin viidentenä hallitusvuotena hyökkäsi Siisak, Egyptin kuningas, Jerusalemin kimppuun, sillä he olivat tulleet uskottomiksi Herraa kohtaan.'),
(1680353,58,14,12,3,'Hänellä oli mukanaan sotavaunuja tuhat kaksisataa ja ratsumiehiä kuusikymmentä tuhatta, ja lukematon oli väki, joka tuli hänen kanssaan Egyptistä: liibyalaisia, sukkilaisia ja etiopialaisia.'),
(1680354,58,14,12,4,'Ja hän valloitti Juudan varustetut kaupungit ja tuli aina Jerusalemiin saakka.'),
(1680355,58,14,12,5,'Niin profeetta Semaja tuli Rehabeamin ja Juudan päämiesten tykö, jotka olivat kokoontuneet Jerusalemiin Siisakia pakoon, ja hän sanoi heille: "Näin sanoo Herra: Te olette hyljänneet minut, sentähden olen minäkin hyljännyt teidät Siisakin käsiin".'),
(1680356,58,14,12,6,'Silloin Israelin päämiehet ja kuningas nöyrtyivät ja sanoivat: "Herra on vanhurskas".'),
(1680357,58,14,12,7,'Kun Herra näki heidän nöyrtyvän, tuli Semajalle tämä Herran sana: "He ovat nöyrtyneet; minä en tuhoa heitä, vaan minä annan heidän hädin tuskin pelastua, eikä minun vihaani vuodateta Jerusalemin päälle Siisakin käden kautta.'),
(1680358,58,14,12,8,'Kuitenkin heidän on tultava hänen palvelijoikseen, että he tulisivat tietämään, mitä on palvella minua ja mitä on palvella vieraitten maitten valtakuntia."'),
(1680359,58,14,12,9,'Niin Siisak, Egyptin kuningas, hyökkäsi Jerusalemin kimppuun ja otti Herran temppelin aarteet ja kuninkaan linnan aarteet, otti kaikki tyynni. Hän otti myös kaikki kultakilvet, jotka Salomo oli teettänyt.'),
(1680360,58,14,12,10,'Kuningas Rehabeam teetti niiden sijaan vaskikilvet ja jätti ne henkivartijain päälliköitten haltuun, jotka vartioivat kuninkaan linnan ovella.'),
(1680361,58,14,12,11,'Ja niin usein kuin kuningas meni Herran temppeliin, menivät myöskin henkivartijat ja kantoivat niitä ja veivät ne sitten takaisin henkivartijain huoneeseen.'),
(1680362,58,14,12,12,'Sentähden, että Rehabeam nöyrtyi, kääntyi Herran viha hänestä pois, niin ettei tullut täydellistä tuhoa; ja olivathan asiat Juudassa vielä hyvin.'),
(1680363,58,14,12,13,'Niin kuningas Rehabeam vahvistui Jerusalemissa ja hallitsi edelleen. Sillä Rehabeam oli neljänkymmenen yhden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi seitsemäntoista vuotta Jerusalemissa, siinä kaupungissa, jonka Herra oli valinnut kaikista Israelin sukukunnista, sijoittaaksensa nimensä siihen. Hänen äitinsä oli nimeltään Naema, ammonilainen.'),
(1680364,58,14,12,14,'Ja hän teki sitä, mikä on pahaa, sillä hän ei kiinnittänyt sydäntänsä etsimään Herraa.'),
(1680365,58,14,12,15,'Rehabeamin vaiheet, sekä aikaisemmat että myöhemmät, ovat kirjoitetut profeetta Semajan ja näkijä Iddon historiaan, sukuluettelojen tapaan. Mutta Rehabeamin ja Jerobeamin väliset taistelut jatkuivat kaiken aikaa.'),
(1680366,58,14,12,16,'Sitten Rehabeam meni lepoon isiensä tykö, ja hänet haudattiin Daavidin kaupunkiin. Ja hänen poikansa Abia tuli kuninkaaksi hänen sijaansa.'),
(1680367,58,14,13,1,'Kuningas Jerobeamin kahdeksantenatoista hallitusvuotena tuli Abia Juudan kuninkaaksi.'),
(1680368,58,14,13,2,'Hän hallitsi kolme vuotta Jerusalemissa. Hänen äitinsä nimi oli Mikaja, Uurielin tytär, Gibeasta. Mutta Abia ja Jerobeam olivat sodassa keskenään.'),
(1680369,58,14,13,3,'Abia alotti sodan urhoollisella sotajoukolla, neljälläsadalla tuhannella valiomiehellä, mutta Jerobeam asettui sotarintaan häntä vastaan kahdeksallasadalla tuhannella valiomiehellä, sotaurholla.'),
(1680370,58,14,13,4,'Ja Abia nousi Semaraimin vuoren laelle Efraimin vuoristossa ja sanoi: "Kuulkaa minua, Jerobeam ja koko Israel!'),
(1680371,58,14,13,5,'Täytyyhän teidän tietää, että Herra, Israelin Jumala, on antanut Daavidille ja hänen pojillensa ikuisiksi ajoiksi Israelin kuninkuuden, lujan kuin suolaliitto.'),
(1680372,58,14,13,6,'Mutta Jerobeam, Nebatin poika, Daavidin pojan Salomon palvelija, nousi ja kapinoitsi herraansa vastaan.'),
(1680373,58,14,13,7,'Ja hänen luoksensa kokoontui tyhjäntoimittajia, kelvottomia miehiä, ja he pääsivät voitolle Rehabeamista, Salomon pojasta, sillä Rehabeam oli nuori ja arka eikä voinut heitä vastustaa.'),
(1680374,58,14,13,8,'Ja nyt te luulette voivanne vastustaa Herran kuninkuutta, joka on Daavidin poikien käsissä, koska teitä on suuri joukko ja teillä on kultavasikat, jotka Jerobeam on teettänyt teille jumaliksi.'),
(1680375,58,14,13,9,'Ettekö te ole karkoittaneet Herran pappeja, Aaronin poikia, ja leeviläisiä, ja itse tehneet itsellenne pappeja, niinkuin muiden maiden kansat tekevät? Ken tahansa tuli papinvirkaan vihittäväksi, mukanaan mullikka ja seitsemän oinasta, hänestä tuli epäjumalan pappi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680376,58,14,13,10,'Mutta meidän Jumalamme on Herra, ja häntä me emme ole hyljänneet. Ja pappeina palvelevat Herraa Aaronin pojat, ja leeviläiset toimittavat palvelustehtäviä.'),
(1680377,58,14,13,11,'He polttavat Herralle polttouhreja joka aamu ja joka ilta ja hyvänhajuista suitsutusta, ja he latovat leivät päälletysten aitokultaiselle pöydälle ja sytyttävät joka ilta kultaisen seitsenhaaraisen lampun lamppuineen; sillä me hoidamme Herran, meidän Jumalamme, meille antamat tehtävät, mutta te olette hänet hyljänneet.'),
(1680378,58,14,13,12,'Ja katso, meidän kanssamme, meidän edellämme on Jumala ja ovat hänen pappinsa, ja hälytystorvet toitottamassa teitä vastaan. Te israelilaiset, älkää sotiko Herraa, isienne Jumalaa, vastaan, sillä se ei teille onnistu."'),
(1680379,58,14,13,13,'Mutta Jerobeam oli pannut väkeä kiertämään heidän taaksensa väijyksiin, niin että toiset olivat Juudan miesten edessä ja toiset väijyksissä heidän takanansa.'),
(1680380,58,14,13,14,'Kun Juudan miehet kääntyivät, niin katso, heillä oli sota edessä ja takana. Silloin he huusivat Herraa, ja papit puhalsivat torviin.'),
(1680381,58,14,13,15,'Ja Juudan miehet nostivat sotahuudon; ja kun Juudan miehet nostivat sotahuudon, antoi Jumala Abian ja Juudan voittaa Jerobeamin ja koko Israelin.'),
(1680382,58,14,13,16,'Ja israelilaiset kääntyivät Juudan miehiä pakoon, ja Jumala antoi heidät näiden käsiin.'),
(1680383,58,14,13,17,'Ja Abia väkinensä tuotti heille suuren tappion, niin että israelilaisia kaatui viisisataa tuhatta valiomiestä.'),
(1680384,58,14,13,18,'Näin israelilaiset siihen aikaan nöyryytettiin; mutta Juudan miehet voimistuivat, sillä he turvautuivat Herraan, isiensä Jumalaan.'),
(1680385,58,14,13,19,'Ja Abia ajoi Jerobeamia takaa ja valloitti häneltä muutamia kaupunkeja: Beetelin ja sen tytärkaupungit, Jesanan ja sen tytärkaupungit ja Efronin ja sen tytärkaupungit.'),
(1680386,58,14,13,20,'Eikä Jerobeam enää tullut voimiinsa Abian elinpäivinä, vaan Herra löi häntä, niin että hän kuoli.'),
(1680387,58,14,13,21,'Mutta Abia vahvistui. Ja hän otti itselleen neljätoista vaimoa, ja hänelle syntyi kaksikymmentä kaksi poikaa ja kuusitoista tytärtä.'),
(1680388,58,14,13,22,'Mitä muuta on kerrottavaa Abiasta, hänen vaelluksestaan ja hänen puheistaan, se on kirjoitettuna profeetta Iddon selityskirjassa.'),
(1680389,58,14,14,1,'Sitten Abia meni lepoon isiensä tykö, ja hänet haudattiin Daavidin kaupunkiin. Ja hänen poikansa Aasa tuli kuninkaaksi hänen sijaansa. Hänen aikanansa oli maassa rauha kymmenen vuotta.'),
(1680390,58,14,14,2,'Ja Aasa teki sitä, mikä oli hyvää ja oikeata Herran, hänen Jumalansa, silmissä.'),
(1680391,58,14,14,3,'Hän poisti vieraat alttarit ja uhrikukkulat, murskasi patsaat ja hakkasi maahan asera-karsikot.'),
(1680392,58,14,14,4,'Ja hän kehoitti Juudaa etsimään Herraa, heidän isiensä Jumalaa, ja noudattamaan lakia ja käskyjä.'),
(1680393,58,14,14,5,'Ja kaikista Juudan kaupungeista hän poisti uhrikukkulat ja auringonpatsaat, ja valtakunnassa oli rauha hänen aikanansa.'),
(1680394,58,14,14,6,'Ja hän rakensi varustettuja kaupunkeja Juudaan, koska maassa oli rauha eikä hänellä näinä vuosina ollut mitään sotaa; sillä Herra oli suonut hänen päästä rauhaan.'),
(1680395,58,14,14,7,'Hän sanoi Juudalle: "Linnoittakaamme nämä kaupungit, ympäröikäämme ne muureilla ja torneilla, ovilla ja salvoilla. Vielä on maa meidän vallassamme, sentähden että me olemme etsineet Herraa, meidän Jumalaamme. Me olemme etsineet häntä, ja hän on suonut meidän päästä rauhaan joka taholla." Niin he rakensivat, ja se heille onnistui.'),
(1680396,58,14,14,8,'Ja Aasalla oli sotajoukko, joka oli varustettu kilvillä ja keihäillä: Juudasta oli kolmesataa tuhatta miestä ja Benjaminista kaksisataa kahdeksankymmentä tuhatta, jotka kantoivat kilpeä ja jännittivät jousta. Kaikki nämä olivat sotaurhoja.'),
(1680397,58,14,14,9,'Mutta etiopialainen Serah lähti heitä vastaan sotajoukolla, jossa oli miehiä tuhannen tuhatta ja sotavaunuja kolmesataa; ja hän tuli Maaresaan saakka.'),
(1680398,58,14,14,10,'Ja Aasa lähti häntä vastaan, ja he asettuivat sotarintaan Sefatan laaksoon, Maaresaan.'),
(1680399,58,14,14,11,'Ja Aasa huusi Herraa, Jumalaansa, ja sanoi: "Herra, sinä yksin voit auttaa taistelussa voimallisen ja voimattoman välillä. Auta meitä, Herra, meidän Jumalamme, sillä sinuun me turvaudumme ja sinun nimessäsi me olemme tulleet tätä suurta joukkoa vastaan. Herra, sinä olet meidän Jumalamme; älä salli ihmisen päästä voitolle sinusta."'),
(1680400,58,14,14,12,'Niin Herra antoi Aasan ja Juudan voittaa etiopialaiset, ja etiopialaiset pakenivat.'),
(1680401,58,14,14,13,'Ja Aasa ja väki, joka oli hänen kanssaan, ajoivat heitä takaa Gerariin saakka. Ja etiopialaisia kaatui niin paljon, ettei heistä jäänyt ketään henkiin, sillä Herra ja hänen sotajoukkonsa tuhosivat heidät. Ja he ottivat paljon saalista,'),
(1680402,58,14,14,14,'valloittivat kaikki kaupungit Gerarin ympäriltä, sillä Herran kauhu oli vallannut nämä, ja ryöstivät kaikki kaupungit, sillä niissä oli paljon ryöstettävää.'),
(1680403,58,14,14,15,'Jopa karjamajatkin he valtasivat, veivät pois saaliinaan paljon lampaita ja kameleja ja palasivat Jerusalemiin.'),
(1680404,58,14,15,1,'Niin Jumalan henki tuli Asarjaan, Oodedin poikaan.'),
(1680405,58,14,15,2,'Hän meni Aasaa vastaan ja sanoi hänelle: "Kuulkaa minua, Aasa ja koko Juuda ja Benjamin. Herra on teidän kanssanne, kun te olette hänen kanssansa; ja jos häntä etsitte, niin te löydätte hänet, mutta jos hylkäätte hänet, niin hän hylkää teidät.'),
(1680406,58,14,15,3,'Kauan aikaa Israel oli ilman oikeata Jumalaa, ilman opetusta antavaa pappia ja ilman lakia.'),
(1680407,58,14,15,4,'Mutta kun he ahdistuksessansa palasivat Herran, Israelin Jumalan, tykö ja etsivät häntä, niin he löysivät hänet.'),
(1680408,58,14,15,5,'Niinä aikoina ei ollut turvallisuutta niillä, jotka lähtivät ja tulivat, vaan suuri hämminki vallitsi kaikkien maakuntain asukasten keskuudessa.'),
(1680409,58,14,15,6,'Ja kansa törmäsi kansaa vastaan ja kaupunki kaupunkia vastaan, sillä Jumala oli saattanut heidät hämminkiin lähettäen kaikkinaisia ahdistuksia.'),
(1680410,58,14,15,7,'Mutta te olkaa lujat älkääkä antako kättenne vaipua, sillä teidän työllänne on palkkansa."'),
(1680411,58,14,15,8,'Kun Aasa kuuli nämä profeetta Oodedin sanat ja ennustuksen, rohkaisi hän mielensä ja toimitti pois iljetykset koko Juudan ja Benjaminin maasta ja niistä kaupungeista, jotka hän oli valloittanut Efraimin vuoristosta, ja uudisti Herran alttarin, joka oli Herran eteisen edessä.'),
(1680412,58,14,15,9,'Ja hän kokosi koko Juudan ja Benjaminin ja myöskin heidän luonaan asuvat muukalaiset, jotka olivat tulleet Efraimista, Manassesta ja Simeonista, sillä monet olivat siirtyneet Israelista hänen luokseen nähtyänsä, että Herra, hänen Jumalansa, oli hänen kanssaan.'),
(1680413,58,14,15,10,'Ja he kokoontuivat Jerusalemiin Aasan viidennentoista hallitusvuoden kolmannessa kuussa'),
(1680414,58,14,15,11,'ja uhrasivat sinä päivänä Herralle saaliista, minkä he olivat tuoneet, seitsemänsataa raavasta ja seitsemäntuhatta lammasta.'),
(1680415,58,14,15,12,'Ja he tekivät liiton, että etsisivät Herraa, isiensä Jumalaa, kaikesta sydämestään ja kaikesta sielustaan,'),
(1680416,58,14,15,13,'ja että jokainen, joka ei etsinyt Herraa, Israelin Jumalaa, oli surmattava, olipa hän pieni tai suuri, mies tai nainen.'),
(1680417,58,14,15,14,'Ja he vannoivat valan Herralle suurella äänellä riemun raikuessa ja torvien ja pasunain pauhatessa.'),
(1680418,58,14,15,15,'Ja koko Juuda iloitsi siitä valasta, sillä he olivat vannoneet sen kaikesta sydämestään, ja he etsivät Herraa kaikella halullansa ja löysivät hänet; niin Herra soi heidän päästä rauhaan joka taholla.'),
(1680419,58,14,15,16,'Kuningas Aasa erotti äitinsäkin Maakan kuningattaren arvosta, koska tämä oli pystyttänyt inhotuksen Aseralle; Aasa kukisti inhotuksen, rouhensi ja poltti sen Kidronin laaksossa.'),
(1680420,58,14,15,17,'Mutta uhrikukkulat eivät hävinneet Israelista. Kuitenkin Aasan sydän oli ehyesti Herralle antautunut, niin kauan kuin hän eli.'),
(1680421,58,14,15,18,'Ja hän vei Jumalan temppeliin isänsä pyhät lahjat ja omat pyhät lahjansa: hopeata, kultaa ja kalua.'),
(1680422,58,14,15,19,'Eikä ollut sotaa Aasan kolmanteenkymmenenteen viidenteen hallitusvuoteen asti.'),
(1680423,58,14,16,1,'Aasan kolmantenakymmenentenä kuudentena hallitusvuotena lähti Baesa, Israelin kuningas, Juudaa vastaan ja linnoitti Raaman, estääkseen ketään pääsemästä Aasan, Juudan kuninkaan, luota tai hänen luokseen.'),
(1680424,58,14,16,2,'Ja Aasa toi hopeata ja kultaa Herran temppelin ja kuninkaan linnan aarrekammioista ja lähetti sen Benhadadille, Aramin kuninkaalle, joka asui Damaskossa, ja käski sanoa:'),
(1680425,58,14,16,3,'"Onhan liitto meidän välillämme, minun ja sinun, niinkuin oli minun isäni ja sinun isäsi välillä. Katso, minä lähetän sinulle hopeata ja kultaa; mene ja riko liittosi Baesan, Israelin kuninkaan, kanssa, että hän lähtisi pois minun kimpustani."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680426,58,14,16,4,'Niin Benhadad kuuli kuningas Aasaa ja lähetti sotajoukkojensa päälliköt Israelin kaupunkeja vastaan, ja he valtasivat Iijonin, Daanin ja Aabel-Maimin sekä kaikki Naftalin kaupunkien varastohuoneet.'),
(1680427,58,14,16,5,'Kun Baesa kuuli sen, lakkasi hän linnoittamasta Raamaa ja keskeytti työnsä.'),
(1680428,58,14,16,6,'Mutta kuningas Aasa toi koko Juudan, ja he veivät pois Raamasta kivet ja puut, joilla Baesa oli sitä linnoittanut. Niillä hän linnoitti Geban ja Mispan.'),
(1680429,58,14,16,7,'Siihen aikaan tuli näkijä Hanani Aasan, Juudan kuninkaan, tykö ja sanoi hänelle: "Koska sinä turvauduit Aramin kuninkaaseen etkä turvautunut Herraan, Jumalaasi, sentähden on Aramin kuninkaan sotajoukko päässyt sinun käsistäsi.'),
(1680430,58,14,16,8,'Eikö etiopialaisia ja liibyalaisia ollut suuri sotajoukko, eikö heillä ollut hyvin paljon sotavaunuja ja ratsumiehiä? Mutta koska sinä turvauduit Herraan, antoi hän heidät sinun käsiisi.'),
(1680431,58,14,16,9,'Sillä Herran silmät tarkkaavat kaikkea maata, että hän voimakkaasti auttaisi niitä, jotka ovat ehyellä sydämellä antautuneet hänelle. Tässä sinä teit tyhmästi, sillä tästä lähtien on sinulla yhä oleva sotia."'),
(1680432,58,14,16,10,'Mutta Aasa vihastui näkijään ja panetti hänet vankilaan, sillä niin vihoissaan hän oli hänelle tästä. Myöskin muutamille muille kansasta Aasa siihen aikaan teki väkivaltaa.'),
(1680433,58,14,16,11,'Aasan vaiheet, sekä aikaisemmat että myöhemmät, katso, ne ovat kirjoitettuina Juudan ja Israelin kuningasten kirjassa.'),
(1680434,58,14,16,12,'Ja kolmantenakymmenentenä yhdeksäntenä hallitusvuotenaan Aasa sairastui jaloistaan, ja hänen tautinsa yltyi hyvin kovaksi. Mutta taudissaankaan hän ei etsinyt Herraa, vaan lääkäreitä.'),
(1680435,58,14,16,13,'Sitten Aasa meni lepoon isiensä tykö ja kuoli neljäntenäkymmenentenä yhdentenä hallitusvuotenaan.'),
(1680436,58,14,16,14,'Ja hänet haudattiin omaan hautaansa, jonka hän oli hakkauttanut itsellensä Daavidin kaupunkiin; ja hänet laskettiin vuoteelle, joka oli täytetty hajuaineilla ja erilaisilla, voiteeksi sekoitetuilla höysteillä, ja hänen kunniakseen poltettiin ylen runsas kuolinsuitsutus.'),
(1680437,58,14,17,1,'Hänen poikansa Joosafat tuli kuninkaaksi hänen sijaansa. Hän vahvistautui Israelia vastaan.'),
(1680438,58,14,17,2,'Hän sijoitti sotaväkeä kaikkiin Juudan varustettuihin kaupunkeihin ja asetti maaherroja Juudan maahan ja Efraimin kaupunkeihin, jotka hänen isänsä Aasa oli valloittanut.'),
(1680439,58,14,17,3,'Ja Herra oli Joosafatin kanssa, sillä hän vaelsi isänsä Daavidin aikaisempia teitä eikä etsinyt baaleja;'),
(1680440,58,14,17,4,'vaan hän etsi isänsä Jumalaa ja vaelsi hänen käskyjensä mukaan eikä tehnyt, niinkuin Israel teki.'),
(1680441,58,14,17,5,'Niin Herra vahvisti kuninkuuden hänen käsissään, ja koko Juuda antoi lahjoja Joosafatille, niin että hänelle tuli paljon rikkautta ja kunniaa.'),
(1680442,58,14,17,6,'Ja kun hänen rohkeutensa kasvoi Herran teillä, poisti hän vielä uhrikukkulatkin ja asera-karsikot Juudasta.'),
(1680443,58,14,17,7,'Ja kolmantena hallitusvuotenaan hän lähetti ylimmät virkamiehensä Benhailin, Obadjan, Sakarjan, Netanelin ja Miikajan Juudan kaupunkeihin antamaan opetusta,'),
(1680444,58,14,17,8,'ja heidän kanssansa leeviläiset Semajan, Netanjan, Sebadjan, Asahelin, Semiramotin, Joonatanin, Adonian, Tobian ja Toob-Adonian, leeviläiset; ja näillä oli kanssansa papit Elisama ja Jooram.'),
(1680445,58,14,17,9,'Nämä opettivat Juudassa, ja heillä oli mukanaan Herran lain kirja; he kiertelivät kaikissa Juudan kaupungeissa ja opettivat kansaa.'),
(1680446,58,14,17,10,'Ja Herran kauhu valtasi kaikki Juudaa ympäröivien maitten valtakunnat, niin etteivät ne sotineet Joosafatia vastaan.'),
(1680447,58,14,17,11,'Ja osa filistealaisia toi Joosafatille lahjoja ja hopeata veroksi; myöskin arabialaiset toivat hänelle pikkukarjaa: seitsemäntuhatta seitsemänsataa oinasta ja seitsemäntuhatta seitsemänsataa pukkia.'),
(1680448,58,14,17,12,'Niin Joosafat tuli yhä mahtavammaksi, jopa ylen mahtavaksi, ja hän rakensi Juudaan linnoja ja varastokaupunkeja.'),
(1680449,58,14,17,13,'Hänellä oli suuria varastoja Juudan kaupungeissa ja sotilaita, sotaurhoja, Jerusalemissa.'),
(1680450,58,14,17,14,'Ja tämä oli heidän palvelusvuoronsa heidän perhekuntiensa mukaan: Juudan tuhanten päämiehet olivat: päämies Adna ja hänen kanssaan kolmesataa tuhatta sotaurhoa;'),
(1680451,58,14,17,15,'hänen rinnallaan päämies Joohanan ja hänen kanssaan kaksisataa kahdeksankymmentä tuhatta;'),
(1680452,58,14,17,16,'hänen rinnallaan Amasja, Sikrin poika, joka oli vapaaehtoisesti antautunut Herralle, ja hänen kanssaan kaksisataa tuhatta sotaurhoa.'),
(1680453,58,14,17,17,'Benjaminista: Eljada, sotaurho, ja hänen kanssaan kaksisataa tuhatta jousella ja kilvellä asestettua;'),
(1680454,58,14,17,18,'hänen rinnallaan Joosabad ja hänen kanssaan sata kahdeksankymmentä tuhatta sotaan varustettua.'),
(1680455,58,14,17,19,'Nämä palvelivat kuningasta, ja lisäksi ne, jotka kuningas oli sijoittanut varustettuihin kaupunkeihin koko Juudaan.'),
(1680456,58,14,18,1,'Niin Joosafatille tuli paljon rikkautta ja kunniaa, ja hän lankoutui Ahabin kanssa.'),
(1680457,58,14,18,2,'Ja muutamien vuosien kuluttua hän meni Ahabin luo Samariaan. Ahab teurastutti hänelle ja väelle, joka oli hänen kanssansa, paljon lampaita ja raavaita; ja Ahab yllytti häntä lähtemään sotaan Gileadin Raamotia vastaan.'),
(1680458,58,14,18,3,'Israelin kuningas Ahab sanoi Juudan kuninkaalle Joosafatille: "Lähdetkö minun kanssani Gileadin Raamotiin?" Hän vastasi hänelle: "Minä niinkuin sinä, minun kansani niinkuin sinun kansasi; minä tulen sinun kanssasi sotaan".'),
(1680459,58,14,18,4,'Mutta Joosafat sanoi Israelin kuninkaalle: "Kysy kuitenkin ensin, mitä Herra sanoo".'),
(1680460,58,14,18,5,'Niin Israelin kuningas kokosi profeetat, neljäsataa miestä, ja sanoi heille: "Onko meidän lähdettävä sotaan Gileadin Raamotia vastaan, vai onko minun oltava lähtemättä?" He vastasivat: "Lähde; Jumala antaa sen kuninkaan käsiin".'),
(1680461,58,14,18,6,'Mutta Joosafat sanoi: "Eikö täällä ole enää ketään muuta Herran profeettaa, jolta voisimme kysyä?"'),
(1680462,58,14,18,7,'Israelin kuningas vastasi Joosafatille: "On vielä mies, jolta voisimme kysyä Herran mieltä, mutta minä vihaan häntä, sillä hän ei koskaan ennusta minulle hyvää, vaan aina pahaa; se on Miika, Jimlan poika". Joosafat sanoi: "Älköön kuningas niin puhuko".'),
(1680463,58,14,18,8,'Niin Israelin kuningas kutsui erään hoviherran ja sanoi: "Nouda kiiruusti Miika, Jimlan poika".'),
(1680464,58,14,18,9,'Mutta Israelin kuningas ja Joosafat, Juudan kuningas, istuivat kumpikin valtaistuimellansa puettuina kuninkaallisiin pukuihinsa; he istuivat puimatantereella Samarian portin ovella, ja kaikki profeetat olivat hurmoksissa heidän edessänsä.'),
(1680465,58,14,18,10,'Ja Sidkia, Kenaanan poika, teki itsellensä rautasarvet ja sanoi: "Näin sanoo Herra: Näillä sinä pusket aramilaisia, kunnes teet heistä lopun".'),
(1680466,58,14,18,11,'Ja kaikki profeetat ennustivat samalla tavalla, sanoen: "Mene Gileadin Raamotiin, niin sinä saat voiton; Herra antaa sen kuninkaan käsiin".'),
(1680467,58,14,18,12,'Ja sanansaattaja, joka oli mennyt kutsumaan Miikaa, puhui hänelle sanoen: "Katso, kaikki profeetat ovat yhdestä suusta luvanneet kuninkaalle hyvää. Olkoon sinun sanasi heidän sanansa kaltainen, ja lupaa sinäkin hyvää."'),
(1680468,58,14,18,13,'Mutta Miika vastasi: "Niin totta kuin Herra elää, sen minä puhun, minkä minun Jumalani sanoo".'),
(1680469,58,14,18,14,'Kun hän tuli kuninkaan eteen, sanoi kuningas hänelle: "Miika, onko meidän lähdettävä sotaan Gileadin Raamotiin, vai onko minun oltava lähtemättä?" Hän vastasi hänelle: "Menkää, niin te saatte voiton; heidät annetaan teidän käsiinne".'),
(1680470,58,14,18,15,'Mutta kuningas sanoi hänelle: "Kuinka monta kertaa minun on vannotettava sinua, ettet puhu minulle muuta kuin totuutta Herran nimessä?"'),
(1680471,58,14,18,16,'Silloin hän sanoi: "Minä näin koko Israelin hajallaan vuorilla, niinkuin lampaat, joilla ei ole paimenta. Ja Herra sanoi: ''Näillä ei ole isäntää; palatkoot he kukin rauhassa kotiinsa''."'),
(1680472,58,14,18,17,'Niin Israelin kuningas sanoi Joosafatille: "Enkö minä sanonut sinulle, ettei tämä koskaan ennusta minulle hyvää, vaan aina pahaa?"'),
(1680473,58,14,18,18,'Mutta hän sanoi: "Kuulkaa siis Herran sana: Minä näin Herran istuvan istuimellansa ja kaiken taivaan joukon seisovan hänen edessään, hänen oikealla ja vasemmalla puolellansa.'),
(1680474,58,14,18,19,'Ja Herra sanoi: ''Kuka viekoittelisi Ahabin, Israelin kuninkaan, lähtemään sotaan, että hän kaatuisi Gileadin Raamotissa?'' Mikä vastasi niin, mikä näin.'),
(1680475,58,14,18,20,'Silloin tuli henki ja asettui Herran eteen ja sanoi: ''Minä viekoittelen hänet''. Herra kysyi häneltä: ''Miten?''');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680476,58,14,18,21,'Hän vastasi: ''Minä menen valheen hengeksi kaikkien hänen profeettainsa suuhun''. Silloin Herra sanoi: ''Saat viekoitella, siihen sinä pystyt; mene ja tee niin''.'),
(1680477,58,14,18,22,'Katso, nyt Herra on pannut valheen hengen näiden sinun profeettaisi suuhun, sillä Herra on päättänyt sinun osaksesi onnettomuuden."'),
(1680478,58,14,18,23,'Silloin astui esille Sidkia, Kenaanan poika, löi Miikaa poskelle ja sanoi: "Mitä tietä Herran Henki on poistunut minusta puhuakseen sinun kanssasi?"'),
(1680479,58,14,18,24,'Miika vastasi: "Sen saat nähdä sinä päivänä, jona kuljet huoneesta huoneeseen piiloutuaksesi".'),
(1680480,58,14,18,25,'Mutta Israelin kuningas sanoi: "Ottakaa Miika ja viekää hänet takaisin Aamonin, kaupungin päällikön, ja Jooaan, kuninkaan pojan, luo.'),
(1680481,58,14,18,26,'Ja sanokaa: ''Näin sanoo kuningas: Pankaa tämä vankilaan ja elättäkää häntä vaivaisella vedellä ja leivällä, kunnes minä palaan voittajana takaisin''."'),
(1680482,58,14,18,27,'Miika vastasi: "Jos sinä palaat voittajana takaisin, niin ei Herra ole puhunut minun kauttani". Ja hän sanoi vielä: "Kuulkaa tämä, kaikki kansat".'),
(1680483,58,14,18,28,'Niin Israelin kuningas ja Joosafat, Juudan kuningas, menivät Gileadin Raamotiin.'),
(1680484,58,14,18,29,'Ja Israelin kuningas sanoi Joosafatille: "Täytyypä pukeutua tuntemattomaksi, kun käy taisteluun; mutta ole sinä omissa vaatteissasi". Ja Israelin kuningas pukeutui tuntemattomaksi ja kävi taisteluun.'),
(1680485,58,14,18,30,'Mutta Aramin kuningas oli käskenyt sotavaunujensa päälliköitä sanoen: "Älkää ryhtykö taisteluun kenenkään muun kanssa, olkoon alempi tai ylempi, kuin ainoastaan Israelin kuninkaan kanssa".'),
(1680486,58,14,18,31,'Kun sotavaunujen päälliköt näkivät Joosafatin, ajattelivat he: "Tuo on Israelin kuningas", ja ympäröivät hänet hyökätäkseen hänen kimppuunsa. Silloin Joosafat huusi, ja Herra auttoi häntä, ja Jumala houkutteli heidät pois hänestä.'),
(1680487,58,14,18,32,'Kun sotavaunujen päälliköt näkivät, ettei se ollutkaan Israelin kuningas, vetäytyivät he hänestä pois.'),
(1680488,58,14,18,33,'Mutta eräs mies, joka oli jännittänyt jousensa ja ampui umpimähkään, satutti Israelin kuningasta vyöpanssarin ja rintahaarniskan väliin. Niin tämä sanoi vaunujensa ohjaajalle: "Käännä vaunut ja vie minut pois sotarinnasta, sillä minä olen haavoittunut".'),
(1680489,58,14,18,34,'Mutta kun taistelu sinä päivänä yltyi yltymistään, jäi Israelin kuningas seisomaan vaunuihinsa, päin aramilaisia, iltaan asti; auringonlaskun aikaan hän kuoli.'),
(1680490,58,14,19,1,'Mutta Joosafat, Juudan kuningas, palasi onnellisesti takaisin kotiinsa Jerusalemiin.'),
(1680491,58,14,19,2,'Silloin Jeehu, Hananin poika, näkijä, meni kuningas Joosafatia vastaan ja sanoi hänelle: "Oliko sinun autettava jumalatonta, ja rakastatko sinä niitä, jotka vihaavat Herraa? Sentähden on sinun päälläsi Herran viha.'),
(1680492,58,14,19,3,'Kuitenkin on sinussa löydetty myös hyvää, sillä sinä olet hävittänyt aserat maasta ja kiinnittänyt sydämesi Jumalan etsimiseen."'),
(1680493,58,14,19,4,'Niin Joosafat jäi Jerusalemiin. Sitten hän meni jälleen kansan keskeen, Beersebasta lähtien aina Efraimin vuoristoon saakka, ja palautti heidät takaisin Herran, heidän isiensä Jumalan, tykö.'),
(1680494,58,14,19,5,'Ja hän asetti tuomareita maahan, kaikkiin Juudan varustettuihin kaupunkeihin, kaupunki kaupungilta.'),
(1680495,58,14,19,6,'Ja hän sanoi tuomareille: "Katsokaa, mitä teette, sillä te ette ole tekemässä ihmisten tuomioita, vaan Herran tuomioita, ja hän on teidän kanssanne, kun te tuomitsette.'),
(1680496,58,14,19,7,'Hallitkoon siis teitä Herran pelko. Ottakaa vaari siitä, mitä teette, sillä Herrassa, meidän Jumalassamme, ei ole vääryyttä eikä puolueellisuutta, eikä hän ota lahjuksia."'),
(1680497,58,14,19,8,'Myöskin Jerusalemiin Joosafat asetti leeviläisiä, pappeja ja Israelin perhekunta-päämiehiä jakamaan Herran oikeutta ja ratkaisemaan riita-asioita. Ja he palasivat Jerusalemiin.'),
(1680498,58,14,19,9,'Ja hän käski heitä sanoen: "Tehkää Herraa peljäten, uskollisesti ja ehyellä sydämellä näin:'),
(1680499,58,14,19,10,'Jokaisessa riita-asiassa, minkä veljenne, jotka asuvat kaupungeissansa, tuovat teidän eteenne, koskipa se murhaa tai lakia, käskyä, säädöksiä tai oikeuksia, varoittakaa heitä, etteivät saattaisi itseänsä vikapäiksi Herran edessä ja ettei viha kohtaisi teitä ja teidän veljiänne. Näin tehkää, ettette tulisi vikapäiksi.'),
(1680500,58,14,19,11,'Ja katso, ylimmäinen pappi Amarja olkoon teillä esimiehenä kaikissa Herran asioissa ja Sebadja, Ismaelin poika, Juudan heimoruhtinas, kaikissa kuninkaan asioissa, ja olkoot leeviläiset teillä virkamiehinä. Olkaa lujat ja ryhtykää työhön; ja Herra olkoon sen kanssa, joka hyvä on."'),
(1680501,58,14,20,1,'Senjälkeen tulivat mooabilaiset ja ammonilaiset, ja heidän kanssaan myös muita paitsi ammonilaisia, sotimaan Joosafatia vastaan.'),
(1680502,58,14,20,2,'Niin tultiin ilmoittamaan tästä Joosafatille: "Suuri joukko tulee sinua vastaan meren toiselta puolelta, Aramista, ja katso, he ovat jo Hasason-Taamarissa"; se on Een-Gedissä.'),
(1680503,58,14,20,3,'Silloin Joosafat peljästyi ja kääntyi kysymään Herralta ja kuulutti paaston koko Juudaan.'),
(1680504,58,14,20,4,'Niin Juuda kokoontui etsimään apua Herralta; myös kaikista Juudan kaupungeista tultiin etsimään Herraa.'),
(1680505,58,14,20,5,'Ja Joosafat astui esiin Juudan ja Jerusalemin seurakunnassa, Herran temppelissä, uuden esipihan edessä'),
(1680506,58,14,20,6,'ja sanoi: "Herra, meidän isiemme Jumala, sinä olet Jumala taivaassa, ja sinä hallitset kaikkia pakanakansain valtakuntia. Sinun kädessäsi on voima ja väkevyys, eikä kukaan kestä sinun edessäsi.'),
(1680507,58,14,20,7,'Sinä, meidän Jumalamme, karkoitit tämän maan asukkaat kansasi Israelin tieltä ja annoit sen ystäväsi Aabrahamin jälkeläisille ikuisiksi ajoiksi.'),
(1680508,58,14,20,8,'He asettuivat tänne ja rakensivat täällä sinulle, sinun nimellesi, pyhäkön sanoen:'),
(1680509,58,14,20,9,'''Jos meitä kohtaa joku onnettomuus, miekka, rangaistustuomio, rutto tai nälänhätä, niin me astumme tämän temppelin eteen ja sinun eteesi, sillä sinun nimesi on tässä temppelissä; ja me huudamme sinua hädässämme, ja sinä kuulet ja autat''.'),
(1680510,58,14,20,10,'Ja katso, siinä ovat nyt ammonilaiset ja mooabilaiset ja Seirin vuoristolaiset, joiden alueen kautta sinä et antanut israelilaisten kulkea, kun he tulivat Egyptin maasta, vaan nämä kääntyivät heistä pois eivätkä tuhonneet heitä.'),
(1680511,58,14,20,11,'Katso, nyt he kostavat sen meille: he tulevat karkoittamaan meitä maasta, joka on sinun omasi ja jonka sinä olet antanut meidän omaksemme.'),
(1680512,58,14,20,12,'Meidän Jumalamme, etkö tuomitse heitä? Sillä me emme mahda mitään tätä suurta joukkoa vastaan, joka hyökkää meidän kimppuumme, emmekä itse tiedä mitä tehdä, vaan sinuun meidän silmämme katsovat."'),
(1680513,58,14,20,13,'Kaikki Juudan miehet seisoivat siinä Herran edessä pikkulapsineen, vaimoineen ja poikineen.'),
(1680514,58,14,20,14,'Ja Herran Henki tuli seurakunnan keskellä Jahasieliin, Sakarjan poikaan, joka oli Benajan poika, joka Jegielin poika, joka Mattanjan poika, leeviläisen, joka oli Aasafin jälkeläisiä,'),
(1680515,58,14,20,15,'ja hän sanoi: "Kuunnelkaa, kaikki te Juudan miehet ja Jerusalemin asukkaat ja sinä kuningas Joosafat. Näin sanoo teille Herra: Älkää peljätkö älkääkä arkailko tätä suurta joukkoa, sillä sota ei ole teidän, vaan Jumalan.'),
(1680516,58,14,20,16,'Menkää huomenna heitä vastaan. Katso, he nousevat silloin Siisin solaa pitkin, ja te kohtaatte heidät laakson päässä, itäänpäin Jeruelin erämaasta.'),
(1680517,58,14,20,17,'Mutta silloin ei ole teidän asianne taistella. Astukaa esiin, seisokaa ja katsokaa, kuinka Herra pelastaa teidät, Juuda ja Jerusalem. Älkää peljätkö älkääkä arkailko; menkää huomenna heitä vastaan, ja Herra on oleva teidän kanssanne."'),
(1680518,58,14,20,18,'Silloin Joosafat kumartui kasvoillensa maahan, ja kaikki Juudan miehet ja Jerusalemin asukkaat lankesivat Herran eteen, rukoilemaan Herraa.'),
(1680519,58,14,20,19,'Ja ne leeviläiset, jotka olivat Kehatin ja Koorahin jälkeläisiä, nousivat ylistämään Herraa, Israelin Jumalaa, ylen korkealla äänellä.'),
(1680520,58,14,20,20,'Mutta varhain seuraavana aamuna he menivät Tekoan erämaahan. Ja heidän lähtiessänsä Joosafat astui esiin ja sanoi: "Kuulkaa minua, te Juudan ja Jerusalemin asukkaat. Uskokaa Herraan, Jumalaanne, niin te olette hyvässä turvassa, ja uskokaa hänen profeettojansa, niin te menestytte."'),
(1680521,58,14,20,21,'Ja neuvoteltuaan kansan kanssa hän asetti veisaajat veisaamaan Herralle ylistysvirsiä pyhässä kaunistuksessa ja kulkemaan aseväen edellä sanoen: "Kiittäkää Herraa, sillä hänen armonsa pysyy iankaikkisesti".'),
(1680522,58,14,20,22,'Ja juuri kun he alottivat riemuhuudon ja ylistysvirren, antoi Herra väijyjiä tulla ammonilaisten, mooabilaisten ja Seirin vuoristolaisten selkään, jotka olivat hyökänneet Juudan kimppuun; ja heidät voitettiin.'),
(1680523,58,14,20,23,'Sillä ammonilaiset ja mooabilaiset asettuivat Seirin vuoristolaisia vastaan tuhoamaan ja hävittämään heitä; ja kun he olivat lopettaneet Seirin asukkaat, auttoivat he toisiaan toistensa tuhoamisessa.'),
(1680524,58,14,20,24,'Kun Juudan miehet tulivat paikalle, josta voi tähystää erämaahan, ja kääntyivät joukkoon päin, niin katso, ruumiita makasi maassa, ei kukaan ollut pelastunut.'),
(1680525,58,14,20,25,'Niin Joosafat väkineen tuli ryöstämään heiltä saalista, ja he löysivät heidän seastaan paljon sekä tavaraa että ruumiita ja kalliita kaluja. Ja he ottivat itsellensä enemmän kuin saivat kannetuksi; he ryöstivät saalista kolme päivää, sillä sitä oli paljon.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680526,58,14,20,26,'Neljäntenä päivänä he kokoontuivat Beraka-laaksoon; sillä siellä he kiittivät Herraa. Siitä on sen paikan nimenä Beraka-laakso vielä tänäkin päivänä.'),
(1680527,58,14,20,27,'Senjälkeen kaikki Juudan ja Jerusalemin miehet, ja Joosafat heidän etunenässään, kääntyivät iloiten paluumatkalle Jerusalemiin, sillä Herra oli antanut heille ilon heidän vihollisistaan.'),
(1680528,58,14,20,28,'Ja he tulivat soittaen harpuilla, kanteleilla ja torvilla Jerusalemiin, Herran temppeliin.'),
(1680529,58,14,20,29,'Ja Jumalan kauhu valtasi kaikkien maitten valtakunnat, kun he kuulivat Herran sotineen Israelin vihollisia vastaan.'),
(1680530,58,14,20,30,'Sitten Joosafatin valtakunnalla oli rauha; hänen Jumalansa soi hänen päästä rauhaan joka taholla.'),
(1680531,58,14,20,31,'Niin hallitsi Joosafat Juudaa. Hän oli kolmenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kaksikymmentä viisi vuotta. Hänen äitinsä oli nimeltään Asuba, Silhin tytär.'),
(1680532,58,14,20,32,'Ja hän vaelsi isänsä Aasan tietä, siltä poikkeamatta, ja teki sitä, mikä on oikein Herran silmissä.'),
(1680533,58,14,20,33,'Mutta uhrikukkulat eivät hävinneet, eikä kansa vielä ollut kiinnittänyt sydäntänsä isiensä Jumalaan.'),
(1680534,58,14,20,34,'Mitä muuta on kerrottavaa Joosafatista, sekä hänen aikaisemmista että myöhemmistä vaiheistaan, katso, se on kirjoitettuna Jeehun, Hananin pojan, historiassa, joka on otettu Israelin kuningasten kirjaan.'),
(1680535,58,14,20,35,'Senjälkeen Joosafat, Juudan kuningas, liittoutui Ahasjan, Israelin kuninkaan, kanssa, joka oli jumalaton menoissaan.'),
(1680536,58,14,20,36,'Hän liittoutui tämän kanssa rakentaakseen laivoja, joiden oli määrä kulkea Tarsiiseen; ja niin he rakensivat laivoja Esjon-Geberissä.'),
(1680537,58,14,20,37,'Mutta Elieser, Doodavahun poika, Maaresasta, ennusti Joosafatia vastaan sanoen: "Koska olet liittoutunut Ahasjan kanssa, on Herra särkevä sinun työsi". Niin laivat rikkoutuivat eivätkä kyenneet menemään Tarsiiseen.'),
(1680538,58,14,21,1,'Sitten Joosafat meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Ja hänen poikansa Jooram tuli kuninkaaksi hänen sijaansa.'),
(1680539,58,14,21,2,'Ja hänellä oli veljiä: Joosafatin pojat Asarja, Jehiel, Sakarja, Asarjahu, Miikael ja Sefatja. Nämä kaikki olivat Joosafatin, Israelin kuninkaan, poikia.'),
(1680540,58,14,21,3,'Ja heidän isänsä oli antanut heille suuria lahjoja, hopeata, kultaa ja kalleuksia, sekä varustettuja kaupunkeja Juudassa; mutta kuninkuuden hän oli antanut Jooramille, sillä tämä oli esikoinen.'),
(1680541,58,14,21,4,'Kun Jooram oli noussut isänsä valtaistuimelle ja vahvistunut, tappoi hän miekalla kaikki veljensä, niin myös muutamia Israelin päämiehiä.'),
(1680542,58,14,21,5,'Jooram oli kolmenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kahdeksan vuotta.'),
(1680543,58,14,21,6,'Mutta hän vaelsi Israelin kuningasten tietä, niinkuin Ahabin suku oli tehnyt, sillä hänellä oli puolisona Ahabin tytär; ja niin hän teki sitä, mikä on pahaa Herran silmissä.'),
(1680544,58,14,21,7,'Mutta Herra ei tahtonut tuhota Daavidin sukua, koska hän oli tehnyt liiton Daavidin kanssa ja koska hän oli luvannut antaa hänelle ja hänen pojillensa lampun ainiaaksi.'),
(1680545,58,14,21,8,'Hänen aikanaan edomilaiset luopuivat Juudan vallanalaisuudesta ja asettivat itsellensä kuninkaan.'),
(1680546,58,14,21,9,'Niin Jooram lähti sinne päällikköineen ja kaikkine sotavaunuineen. Ja hän nousi yöllä ja voitti edomilaiset, jotka olivat saartaneet hänet, ja sotavaunujen päälliköt.'),
(1680547,58,14,21,10,'Niin edomilaiset luopuivat Juudan vallanalaisuudesta vapaiksi, aina tähän päivään asti. Siihen aikaan luopui hänen vallanalaisuudestaan myös Libna, koska hän oli hyljännyt Herran, isiensä Jumalan.'),
(1680548,58,14,21,11,'Hänkin teetti uhrikukkuloita Juudan vuoristoon ja saattoi Jerusalemin asukkaat haureuteen ja vietteli Juudan.'),
(1680549,58,14,21,12,'Mutta profeetta Elialta tuli hänelle tällainen kirjoitus: "Näin sanoo Herra, sinun isäsi Daavidin Jumala: Koska et ole vaeltanut isäsi Joosafatin teitä etkä Aasan, Juudan kuninkaan, teitä,'),
(1680550,58,14,21,13,'vaan olet vaeltanut Israelin kuningasten tietä ja saattanut Juudan ja Jerusalemin asukkaat haureuteen, niinkuin Ahabin suku saattoi heidät haureuteen; ja koska myös olet tappanut veljesi, jotka olivat sinun isäsi perhekuntaa ja paremmat kuin sinä,'),
(1680551,58,14,21,14,'katso, sentähden Herra rankaisee sinun kansaasi, poikiasi, vaimojasi ja kaikkea, mitä sinulla on, kovalla vitsauksella;'),
(1680552,58,14,21,15,'ja sinä itse olet sairastava vaikeata tautia, sisusvaivaa, kunnes vuoden, parin kuluttua sisuksesi taudin voimasta tunkeutuvat ulos."'),
(1680553,58,14,21,16,'Niin Herra herätti Jooramia vastaan filistealaisten hengen ja niiden arabialaisten hengen, jotka asuivat etiopialaisten naapureina,'),
(1680554,58,14,21,17,'ja he menivät Juudaa vastaan, valloittivat sen ja veivät saaliinaan kaiken tavaran, mitä oli kuninkaan linnassa, niin myöskin hänen poikansa ja vaimonsa, niin ettei hänelle jäänyt muuta poikaa kuin Jooahas, hänen nuorin poikansa.'),
(1680555,58,14,21,18,'Ja kaiken tämän jälkeen Herra rankaisi häntä parantumattomalla sisusvaivalla.'),
(1680556,58,14,21,19,'Parin vuoden kuluttua, toisen vuoden lopulla, hänen sisuksensa taudin voimasta tunkeutuivat ulos, ja hän kuoli koviin tuskiin. Mutta hänen kansansa ei polttanut hänen kunniakseen kuolinsuitsutusta, niinkuin oli poltettu hänen isiensä kunniaksi.'),
(1680557,58,14,21,20,'Hän oli kolmenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kahdeksan vuotta. Ja hän meni pois kenenkään kaipaamatta, ja hänet haudattiin Daavidin kaupunkiin, mutta ei kuningasten hautoihin.'),
(1680558,58,14,22,1,'Jerusalemin asukkaat tekivät Ahasjan, hänen nuorimman poikansa, kuninkaaksi hänen sijaansa; sillä kaikki vanhemmat oli tappanut se rosvojoukko, joka arabialaisten kanssa oli tullut leiriin. Niin tuli Ahasja, Jooramin poika, Juudan kuninkaaksi.'),
(1680559,58,14,22,2,'Ahasja oli kahdenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa vuoden. Hänen äitinsä oli nimeltään Atalja, Omrin tytär.'),
(1680560,58,14,22,3,'Hänkin vaelsi Ahabin suvun teitä, sillä hänen äitinsä oli häntä neuvomassa jumalattomuuteen.'),
(1680561,58,14,22,4,'Niin hän teki sitä, mikä on pahaa Herran silmissä, samoinkuin Ahabin suku; sillä he olivat hänen isänsä kuoleman jälkeen hänen neuvonantajiaan, hänen turmioksensa.'),
(1680562,58,14,22,5,'Heidän neuvostansa hän myös lähti Israelin kuninkaan Jooramin, Ahabin pojan, kanssa taistelemaan Hasaelia, Aramin kuningasta, vastaan Gileadin Raamotiin; mutta aramilaiset haavoittivat Jooramin.'),
(1680563,58,14,22,6,'Niin hän tuli takaisin Jisreeliin parantuakseen, sillä hänessä oli haavat, jotka häneen oli isketty Raamassa hänen taistellessaan Hasaelia, Aramin kuningasta, vastaan. Ja Juudan kuningas Ahasja, Jooramin poika, tuli Jisreeliin katsomaan Jooramia, Ahabin poikaa, koska tämä oli sairaana.'),
(1680564,58,14,22,7,'Mutta Jumalalta tuli Ahasjan tuhoksi se, että hän meni Jooramin luo. Sillä sinne tultuaan hän meni Jooramin kanssa Jeehua, Nimsin poikaa, vastaan, jonka Herra oli voidellut hävittämään Ahabin sukua.'),
(1680565,58,14,22,8,'Ja kun Jeehu oli toimeenpanemassa Ahabin suvun tuomiota, tapasi hän Juudan ruhtinaat ja Ahasjan veljenpojat, jotka palvelivat Ahasjaa, ja tappoi heidät.'),
(1680566,58,14,22,9,'Sitten hän etsi Ahasjaa; ja tämä saatiin kiinni Samariassa, jossa hän piileskeli. Niin hänet vietiin Jeehun eteen ja surmattiin. Ja he hautasivat hänet, sillä he sanoivat: "Hän on Joosafatin poika, hänen, joka kaikesta sydämestänsä etsi Herraa". Eikä Ahasjan perheessä ollut ketään, joka olisi kyennyt hallitsemaan.'),
(1680567,58,14,22,10,'Kun Atalja, Ahasjan äiti, näki, että hänen poikansa oli kuollut, nousi hän ja tuhosi koko Juudan heimon kuningassuvun.'),
(1680568,58,14,22,11,'Mutta kuninkaan tytär Joosabat otti surmattavain kuninkaan poikien joukosta salaa Ahasjan pojan Jooaan ja pani hänet imettäjineen makuuhuoneeseen. Näin pappi Joojadan vaimo Joosabat, joka oli kuningas Jooramin tytär ja Ahasjan sisar, sai hänet kätketyksi Ataljalta, niin ettei tämä voinut häntä surmauttaa.'),
(1680569,58,14,22,12,'Sitten poika oli heidän luonaan Jumalan temppeliin piilotettuna kuusi vuotta, Ataljan hallitessa maata.'),
(1680570,58,14,23,1,'Mutta seitsemäntenä vuotena Joojada rohkaisi mielensä ja liittoutui sadanpäämiesten Asarjan, Jerohamin pojan, Ismaelin, Joohananin pojan, Asarjan, Oobedin pojan, Maasejan, Adajan pojan, ja Elisafatin, Sikrin pojan, kanssa.'),
(1680571,58,14,23,2,'Nämä kiertelivät Juudassa ja kokosivat leeviläiset kaikista Juudan kaupungeista sekä Israelin perhekunta-päämiehet; ja he tulivat Jerusalemiin.'),
(1680572,58,14,23,3,'Tehkää näin: Kolmas osa teistä, papeista ja leeviläisistä, joiden on mentävä vartionpitoon sapattina, olkoon ovenvartijoina kynnyksillä,'),
(1680573,58,14,23,5,'kolmas osa miehittäköön kuninkaan linnan ja kolmas osa Jesod-portin, ja koko kansa Herran temppelin esikartanot.'),
(1680574,58,14,23,6,'Älköön kukaan muu kuin papit ja palvelusta tekevät leeviläiset menkö Herran temppeliin. He saavat mennä sisään, sillä he ovat pyhät, mutta kaikki muu kansa noudattakoon Herran määräystä.'),
(1680575,58,14,23,7,'Leeviläiset asettukoot kuninkaan ympärille, kullakin ase kädessä; ja joka tunkeutuu temppeliin, se surmattakoon. Näin olkaa kuninkaan luona, menköön hän ulos tai sisään."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680576,58,14,23,8,'Leeviläiset ja koko Juuda tekivät kaiken, mitä pappi Joojada oli käskenyt heidän tehdä. Kukin heistä otti miehensä, sekä ne, joiden oli mentävä vartionpitoon sapattina, että ne, jotka pääsivät vartionpidosta sapattina, sillä pappi Joojada ei ollut vapauttanut osastoja palveluksesta.'),
(1680577,58,14,23,9,'Ja pappi Joojada antoi sadanpäämiehille keihäät, kilvet ja varustukset, jotka olivat olleet kuningas Daavidin omat ja olivat Jumalan temppelissä.'),
(1680578,58,14,23,10,'Ja hän asetti koko kansan, kullakin peitsi kädessä, temppelin eteläsivulta aina sen pohjoissivulle saakka, päin alttaria ja temppeliä, kuninkaan ympärille.'),
(1680579,58,14,23,11,'Sitten he toivat kuninkaan pojan esille, panivat hänen päähänsä kruunun ja antoivat hänelle lain kirjan ja tekivät hänet kuninkaaksi. Ja Joojada ja hänen poikansa voitelivat hänet ja huusivat: "Eläköön kuningas!"'),
(1680580,58,14,23,12,'Kun Atalja kuuli kansan huudon, sen juostessa ja huutaessa riemuhuutoja kuninkaalle, meni hän kansan luo Herran temppeliin.'),
(1680581,58,14,23,13,'Hän näki kuninkaan seisovan korkealla paikallansa sisäänkäytävän luona, ja päälliköt ja torvensoittajat kuninkaan luona, ja kaiken maan kansan, joka riemuitsi ja puhalsi torviin, ja veisaajat, jotka soittimillaan johtivat ylistyslaulua. Silloin Atalja repäisi vaatteensa ja huusi: "Kapina, kapina!"'),
(1680582,58,14,23,14,'Mutta pappi Joojada antoi sadanpäämiesten, sotajoukon johtajien, astua esiin ja sanoi heille: "Viekää hänet pois rivien välitse, ja joka yrittää seurata häntä, se surmattakoon miekalla". Sillä pappi oli sanonut: "Älkää surmatko häntä Herran temppelissä".'),
(1680583,58,14,23,15,'Niin he kävivät häneen käsiksi, ja kun hän oli tullut kuninkaan linnan Hevosportin sisäänkäytävän luo, surmasivat he hänet siinä.'),
(1680584,58,14,23,16,'Ja Joojada teki liiton hänen itsensä, koko kansan ja kuninkaan kesken, että he olisivat Herran kansa.'),
(1680585,58,14,23,17,'Sitten kaikki kansa meni Baalin temppeliin, ja he hävittivät sen. Sen alttarit ja kuvat he murskasivat, ja he tappoivat alttarien edessä Mattanin, Baalin papin.'),
(1680586,58,14,23,18,'Sitten Joojada asetti päällysmiehiä Herran temppeliin, leeviläisiä pappeja, jotka Daavid oli määrännyt Herran temppeliin, uhraamaan Herran polttouhreja, niinkuin on kirjoitettuna Mooseksen laissa, riemuhuudoin ja lauluin, Daavidin järjestelyn mukaan.'),
(1680587,58,14,23,19,'Ja hän asetti ovenvartijat Herran temppelin porteille, ettei pääsisi sisään kukaan, joka oli jollakin tavalla saastainen.'),
(1680588,58,14,23,20,'Ja hän otti mukaansa sadanpäämiehet, ylimykset ja kansan hallitusmiehet sekä kaiken maan kansan ja vei kuninkaan Herran temppelistä, ja he tulivat Yläportin kautta kuninkaan linnaan ja asettivat kuninkaan kuninkaalliselle valtaistuimelle.'),
(1680589,58,14,23,21,'Ja kaikki maan kansa iloitsi, ja kaupunki pysyi rauhallisena. Mutta Ataljan he surmasivat miekalla.'),
(1680590,58,14,24,1,'Jooas oli seitsemän vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa neljäkymmentä vuotta. Hänen äitinsä nimi oli Sibja, Beersebasta.'),
(1680591,58,14,24,2,'Ja Jooas teki sitä, mikä on oikein Herran silmissä, niin kauan kuin pappi Joojada eli.'),
(1680592,58,14,24,3,'Ja Joojada otti hänelle kaksi vaimoa, ja hänelle syntyi poikia ja tyttäriä.'),
(1680593,58,14,24,4,'Senjälkeen Jooas aikoi uudistaa Herran temppelin.'),
(1680594,58,14,24,5,'Ja hän kutsui kokoon papit ja leeviläiset ja sanoi heille: "Menkää Juudan kaupunkeihin ja kootkaa kaikesta Israelista rahaa Jumalanne temppelin korjaamiseksi, vuodesta vuoteen, ja jouduttakaa tätä asiaa". Mutta leeviläiset eivät jouduttaneet sitä.'),
(1680595,58,14,24,6,'Silloin kuningas kutsui luokseen ylimmäisen papin Joojadan ja sanoi hänelle: "Miksi et ole pitänyt huolta siitä, että leeviläiset toisivat Juudasta ja Jerusalemista Herran palvelijan Mooseksen määräämän Israelin seurakunnan veron lainmajaa varten?'),
(1680596,58,14,24,7,'Sillä jumalaton Atalja ja hänen poikansa ovat murtautuneet Jumalan temppeliin; he ovat myös käyttäneet baaleja varten kaikki Herran temppelin pyhät lahjat."'),
(1680597,58,14,24,8,'Sitten tehtiin kuninkaan käskystä arkku, ja se asetettiin Herran temppelin portin ulkopuolelle.'),
(1680598,58,14,24,9,'Ja Juudassa ja Jerusalemissa kuulutettiin, että vero, jonka Jumalan palvelija Mooses oli erämaassa määrännyt Israelille, oli tuotava Herralle.'),
(1680599,58,14,24,10,'Kaikki päämiehet ja kaikki kansa toivat iloiten rahaa ja heittivät arkkuun, kunnes se täyttyi.'),
(1680600,58,14,24,11,'Aina kun leeviläiset toivat arkun kuninkaan asettamien tarkastusmiesten luo, huomattuaan, että siinä oli paljon rahaa, tulivat kuninkaan kirjuri ja ylimmäisen papin käskyläinen tyhjentämään arkun, ja sitten he kantoivat sen takaisin paikoilleen. Niin he tekivät päivä päivältä ja kokosivat paljon rahaa.'),
(1680601,58,14,24,12,'Sitten kuningas ja Joojada antoivat sen niille, jotka teettivät työt Herran temppelissä, ja nämä palkkasivat kivenhakkaajia ja puuseppiä uudistamaan Herran temppeliä, niin myös rauta- ja vaskiseppiä korjaamaan Herran temppeliä.'),
(1680602,58,14,24,13,'Ja työnteettäjät toimivat niin, että työ edistyi heidän käsissään, ja he asettivat Jumalan temppelin entiselleen sen määrämittojen mukaan ja panivat sen kuntoon.'),
(1680603,58,14,24,14,'Ja kun he olivat päättäneet työnsä, veivät he rahan tähteet kuninkaalle ja Joojadalle; ja niillä teetettiin kaluja Herran temppeliin, jumalanpalvelus- ja uhraamiskaluja, kuppeja sekä kulta- ja hopeakaluja. Ja Herran temppelissä uhrattiin vakituisesti polttouhreja, niin kauan kuin Joojada eli.'),
(1680604,58,14,24,15,'Mutta Joojada kävi vanhaksi ja sai elämästä kyllänsä, ja hän kuoli. Sadan kolmenkymmenen vuoden vanha hän oli kuollessaan.'),
(1680605,58,14,24,16,'Ja hänet haudattiin Daavidin kaupunkiin kuningasten joukkoon, sillä hän oli tehnyt sitä, mikä hyvää on, Israelille ja Jumalalle ja hänen temppelilleen.'),
(1680606,58,14,24,17,'Mutta Joojadan kuoleman jälkeen tulivat Juudan päämiehet ja kumarsivat kuningasta; ja kuningas kuuli heitä.'),
(1680607,58,14,24,18,'Ja he hylkäsivät Herran, isiensä Jumalan, temppelin ja palvelivat aseroita ja jumalankuvia. Niin viha kohtasi Juudaa ja Jerusalemia tämän heidän rikoksensa tähden.'),
(1680608,58,14,24,19,'Hän lähetti heidän keskuuteensa profeettoja palauttamaan heitä Herran tykö, ja nämä varoittivat heitä, mutta he eivät kuulleet.'),
(1680609,58,14,24,20,'Niin Jumalan Henki täytti Sakarjan, pappi Joojadan pojan, ja hän astui kansan eteen ja sanoi heille: "Näin sanoo Jumala: Miksi te rikotte Herran käskyt omaksi onnettomuudeksenne? Koska te olette hyljänneet Herran, hylkää hänkin teidät."'),
(1680610,58,14,24,21,'Mutta he tekivät salaliiton häntä vastaan ja kivittivät hänet kuoliaaksi kuninkaan käskystä Herran temppelin esipihalla.'),
(1680611,58,14,24,22,'Sillä kuningas Jooas ei muistanut rakkautta, jota hänen isänsä Joojada oli hänelle osoittanut, vaan tappoi Joojadan pojan. Ja tämä sanoi kuollessaan: "Herra nähköön ja kostakoon".'),
(1680612,58,14,24,23,'Vuoden vaihteessa kävi aramilaisten sotajoukko Jooaan kimppuun, ja he tunkeutuivat Juudaan ja Jerusalemiin asti ja tuhosivat kansasta kaikki kansan päämiehet. Ja kaiken saaliinsa he lähettivät Damaskon kuninkaalle.'),
(1680613,58,14,24,24,'Sillä vaikka aramilaisten sotajoukko tuli vähälukuisena, antoi Herra näiden käsiin hyvin suuren sotajoukon, koska he olivat hyljänneet Herran, isiensä Jumalan. Ja niin nämä panivat toimeen rangaistustuomion Jooaalle.'),
(1680614,58,14,24,25,'Kun he sitten lähtivät häntä ahdistamasta - ja hän jäi heidän lähtiessään hyvin sairaaksi - tekivät hänen palvelijansa salaliiton häntä vastaan pappi Joojadan pojan murhan tähden ja tappoivat hänet hänen vuoteeseensa; ja niin hän kuoli. Ja hänet haudattiin Daavidin kaupunkiin; kuitenkaan ei häntä haudattu kuningasten hautoihin.'),
(1680615,58,14,24,26,'Ne, jotka tekivät salaliiton häntä vastaan, olivat Saabad, ammonilaisen vaimon Simeatin poika, ja Joosabad, mooabilaisen vaimon Simritin poika.'),
(1680616,58,14,24,27,'Hänen pojistaan, monista häntä vastaan lausutuista ennustuksista ja Jumalan temppelin uudestaanrakentamisesta, katso, niistä on kirjoitettu Kuningasten kirjan selityskirjaan. Ja hänen poikansa Amasja tuli kuninkaaksi hänen sijaansa.'),
(1680617,58,14,25,1,'Amasja oli kahdenkymmenen viiden vuoden vanha tullessansa kuninkaaksi, ja hän hallitsi Jerusalemissa kaksikymmentä yhdeksän vuotta. Hänen äitinsä oli nimeltään Jooaddan, Jerusalemista.'),
(1680618,58,14,25,2,'Hän teki sitä, mikä on oikein Herran silmissä, ei kuitenkaan ehyellä sydämellä.'),
(1680619,58,14,25,3,'Ja kun hänen kuninkuutensa oli vahvistunut, tappoi hän ne palvelijansa, jotka olivat murhanneet kuninkaan, hänen isänsä.'),
(1680620,58,14,25,4,'Mutta heidän lapsensa hän jätti surmaamatta: hän teki, niinkuin on kirjoitettu laissa, Mooseksen kirjassa, jossa Herra on käskenyt sanoen: "Älkööt isät kuolko lasten tähden älköötkä lapset isien tähden; kukin kuolkoon oman syntinsä tähden".'),
(1680621,58,14,25,5,'Sitten Amasja kokosi Juudan miehet ja asetti heidät perhekunnittain, tuhannen- ja sadanpäämiesten mukaan, koko Juudan ja Benjaminin. Ja hän piti katselmuksen heistä, kaksikymmenvuotiaista ja sitä vanhemmista, ja huomasi heitä olevan kolmesataa tuhatta sotakelpoista, keihästä ja kilpeä käyttävää valiomiestä.'),
(1680622,58,14,25,6,'Lisäksi hän palkkasi Israelista sadalla hopeatalentilla satatuhatta sotaurhoa.'),
(1680623,58,14,25,7,'Mutta Jumalan mies tuli hänen luoksensa ja sanoi: "Kuningas! Älköön Israelin sotajoukko lähtekö sinun kanssasi, sillä Herra ei ole Israelin, kaikkien näiden efraimilaisten, kanssa.'),
(1680624,58,14,25,8,'Vaan lähde sinä yksin, käy rohkeasti taisteluun; muutoin Jumala kaataa sinut vihollistesi eteen, sillä Jumalalla on valta auttaa ja kaataa." Amasja sanoi Jumalan miehelle:'),
(1680625,58,14,25,9,'"Mutta miten käy niiden sadan talentin, jotka minä olen antanut Israelin joukolle?" Jumalan mies vastasi: "Herra voi antaa sinulle paljon enemmän, kuin se on".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680626,58,14,25,10,'Silloin Amasja erotti sen joukon, joka oli tullut hänen luoksensa Efraimista, palaamaan kotiinsa. Siitä he vihastuivat kovin Juudaan ja menivät kotiinsa vihasta hehkuen.'),
(1680627,58,14,25,11,'Mutta Amasja rohkaisi mielensä, lähti ja vei väkensä Suolalaaksoon ja surmasi seiriläisiä kymmenen tuhatta.'),
(1680628,58,14,25,12,'Ja toiset kymmenen tuhatta Juudan miehet ottivat elävinä vangeiksi. Nämä he veivät kallion laelle ja syöksivät heidät kallion laelta alas, niin että he kaikki ruhjoutuivat.'),
(1680629,58,14,25,13,'Mutta ne, jotka kuuluivat Amasjan palauttamaan joukkoon ja jotka eivät olleet päässeet hänen kanssaan sotaan, hyökkäsivät Juudan kaupunkeihin, Samariaan ja aina Beet-Hooroniin saakka; ja he surmasivat asukkaista kolmetuhatta ja ottivat paljon saalista.'),
(1680630,58,14,25,14,'Kun Amasja, voitettuaan edomilaiset, tuli takaisin, toi hän mukanaan seiriläisten jumalat ja asetti ne itselleen jumaliksi, ja hän kumarsi niitä ja poltti niille uhreja.'),
(1680631,58,14,25,15,'Niin Herran viha syttyi Amasjaa kohtaan, ja hän lähetti hänen luokseen profeetan; tämä sanoi hänelle: "Miksi sinä etsit tuon kansan jumalia, jotka eivät voineet pelastaa omaa kansaansa sinun käsistäsi?"'),
(1680632,58,14,25,16,'Hänen näin hänelle puhuessaan Amasja sanoi hänelle: "Olemmeko me asettaneet sinut kuninkaan neuvonantajaksi? Herkeä jo, muutoin sinut surmataan." Profeetta herkesi ja sanoi: "Minä tiedän, että Jumala on päättänyt sinut tuhota, koska sinä teet näin etkä kuule minun neuvoani".'),
(1680633,58,14,25,17,'Amasja, Juudan kuningas, lähetti neuvoteltuaan asiasta Jooaalle, Jooahaan pojalle, Jeehun pojanpojalle, Israelin kuninkaalle, tämän sanan: "Tule, otelkaamme keskenämme".'),
(1680634,58,14,25,18,'Mutta Jooas, Israelin kuningas, lähetti Amasjalle, Juudan kuninkaalle tämän sanan: "Libanonilla kasvava ohdake lähetti setripuulle, joka kasvoi Libanonilla, tämän sanan: ''Anna tyttäresi vaimoksi minun pojalleni''. Mutta metsän eläimet Libanonilla kulkivat ohdakkeen ylitse ja tallasivat sen maahan.'),
(1680635,58,14,25,19,'Sinä sanot: ''Katso, minä olen voittanut edomilaiset'', ja olet käynyt ylpeäksi saatuasi kunniaa. Mutta pysy kotonasi; minkätähden tahdot tuottaa onnettomuuden: sinä itse kukistut ja Juuda sinun kanssasi?"'),
(1680636,58,14,25,20,'Mutta Amasja ei totellut; sillä tämä tuli Jumalalta: hän tahtoi antaa heidät alttiiksi, koska he olivat etsineet Edomin jumalia.'),
(1680637,58,14,25,21,'Niin Jooas, Israelin kuningas, lähti liikkeelle, ja he ottelivat keskenään, hän ja Amasja, Juudan kuningas, Beet-Semeksessä, joka on Juudan aluetta.'),
(1680638,58,14,25,22,'Ja israelilaiset voittivat Juudan miehet, ja nämä pakenivat kukin majallensa.'),
(1680639,58,14,25,23,'Ja Jooas, Israelin kuningas, otti Juudan kuninkaan Amasjan, Jooaan pojan, Jooahaan pojanpojan, Beet-Semeksessä vangiksi ja toi hänet Jerusalemiin. Sitten hän revitti Jerusalemin muuria Efraimin portista Kulmaporttiin saakka, neljäsataa kyynärää.'),
(1680640,58,14,25,24,'Ja hän otti kaiken kullan ja hopean sekä kalut, mitä Herran temppelissä, Oobed-Edomin huostassa oli, ja kuninkaan linnan aarteet ynnä panttivankeja ja palasi Samariaan.'),
(1680641,58,14,25,25,'Mutta Amasja, Jooaan poika, Juudan kuningas, eli Jooaan, Jooahaan pojan, Israelin kuninkaan, kuoleman jälkeen viisitoista vuotta.'),
(1680642,58,14,25,26,'Mitä muuta on kerrottavaa Amasjan aikaisemmista ja myöhemmistä vaiheista, se on kirjoitettuna Juudan ja Israelin kuningasten kirjassa.'),
(1680643,58,14,25,27,'Siitä ajasta alkaen, jolloin Amasja luopui Herrasta, punottiin Jerusalemissa salaliittoa häntä vastaan. Hän pakeni Laakiiseen, mutta Laakiiseen lähetettiin miehiä hänen jälkeensä, ja he surmasivat hänet siellä.'),
(1680644,58,14,25,28,'Hänet nostettiin hevosten selkään ja haudattiin isiensä viereen Juudan kaupunkiin.'),
(1680645,58,14,26,1,'Mutta koko Juudan kansa otti Ussian, joka oli kuudentoista vuoden vanha, ja teki hänet kuninkaaksi hänen isänsä Amasjan sijaan.'),
(1680646,58,14,26,2,'Hän linnoitti Eelatin ja palautti sen Juudalle, sittenkuin kuningas oli mennyt lepoon isiensä tykö.'),
(1680647,58,14,26,3,'Ussia oli kuudentoista vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa viisikymmentä kaksi vuotta. Hänen äitinsä oli nimeltään Jekolja, Jerusalemista.'),
(1680648,58,14,26,4,'Ja hän teki sitä, mikä on oikein Herran silmissä, aivan niinkuin hänen isänsä Amasja oli tehnyt.'),
(1680649,58,14,26,5,'Ja hän etsi Jumalaa, niin kauan kuin Sakarja eli, joka ymmärsi Jumalan näkyjä. Ja niin kauan kuin hän etsi Herraa, antoi Jumala hänen menestyä.'),
(1680650,58,14,26,6,'Hän lähti sotimaan filistealaisia vastaan ja revitti Gatin, Jabnen ja Asdodin muurit; ja hän rakennutti kaupunkeja Asdodin alueelle ja muualle filistealaisten maahan.'),
(1680651,58,14,26,7,'Ja Jumala auttoi häntä filistealaisia vastaan ja niitä arabialaisia vastaan, jotka asuivat Guur-Baalissa, sekä meunilaisia vastaan.'),
(1680652,58,14,26,8,'Ja ammonilaiset maksoivat veroa Ussialle, ja hänen maineensa levisi aina Egyptiin saakka, sillä hän tuli ylen mahtavaksi.'),
(1680653,58,14,26,9,'Ussia rakennutti Jerusalemiin tornit Kulmaportin ja Laaksoportin päälle ja Kulmauksen päälle ja varusti ne.'),
(1680654,58,14,26,10,'Hän rakennutti torneja myös erämaahan ja hakkautti paljon vesisäiliöitä, sillä hänellä oli paljon karjaa sekä Alankomaassa että ylätasangolla. Peltomiehiä ja viinitarhureita hänellä oli vuoristossa ja puutarhamailla, sillä hän harrasti maanviljelystä.'),
(1680655,58,14,26,11,'Ja Ussialla oli sotajoukko, joka teki sotapalvelusta ja lähti sotaan osastoittain, sen lukumäärän mukaan, mikä heitä oli katselmuksessa, jonka kirjuri Jegiel ja päällysmies Maaseja olivat toimittaneet Hananjan, kuninkaallisen päällikön, johdolla.'),
(1680656,58,14,26,12,'Perhekunta-päämiesten, sotaurhojen, koko lukumäärä oli kaksituhatta kuusisataa.'),
(1680657,58,14,26,13,'Heidän johdossaan oli kolmensadan seitsemän tuhannen viidensadan miehen suuruinen sotajoukko, joka teki väellä ja voimalla sotapalvelusta auttaakseen kuningasta vihollista vastaan.'),
(1680658,58,14,26,14,'Ja Ussia varusti heidät, koko sotajoukon, kilvillä, keihäillä, kypäreillä, rintahaarniskoilla, jousilla ja linkokivillä.'),
(1680659,58,14,26,15,'Ja hän teetti Jerusalemiin taidokkaasti sommiteltuja sotakoneita, jotka asetettiin torneihin ja muurien kulmiin ja joilla ammuttiin nuolia ja suuria kiviä. Niin hänen maineensa levisi kauas, sillä hän sai ihmeteltävästi apua, kunnes hän tuli mahtavaksi.'),
(1680660,58,14,26,16,'Mutta kun hän oli tullut mahtavaksi, ylpistyi hänen sydämensä, niin että hän teki kelvottoman teon, hän tuli uskottomaksi Herraa, Jumalaansa, kohtaan ja meni Herran temppeliin, suitsutusalttarille, suitsuttamaan.'),
(1680661,58,14,26,17,'Niin pappi Asarja meni hänen jälkeensä sinne, mukanaan kahdeksankymmentä Herran pappia, rohkeita miehiä.'),
(1680662,58,14,26,18,'Nämä astuivat kuningas Ussiaa vastaan ja sanoivat hänelle: "Ei ole sinun asiasi, Ussia, suitsuttaa Herralle, vaan pappien, Aaronin poikien, jotka ovat pyhitetyt suitsuttamaan. Mene ulos pyhäköstä, sillä sinä olet ollut uskoton, eikä siitä tule sinulle kunniaa Herralta Jumalalta."'),
(1680663,58,14,26,19,'Niin Ussia vihastui, ja hän piti juuri suitsutusastiaa kädessään suitsuttaaksensa. Mutta kun hän vihastui pappeihin, puhkesi hänen otsaansa pitali pappien läsnäollessa Herran temppelissä, suitsutusalttarin ääressä.'),
(1680664,58,14,26,20,'Ja kun ylimmäinen pappi Asarja ja kaikki muut papit kääntyivät hänen puoleensa, niin katso, hänellä oli pitali otsassa. Silloin he äkisti karkoittivat hänet sieltä, ja itsekin hän kiiruusti lähti pois, kun Herra oli häntä lyönyt.'),
(1680665,58,14,26,21,'Niin kuningas Ussia tuli pitalitautiseksi kuolinpäiväänsä saakka ja asui pitalitautisena eri talossa, sillä hän oli eristetty Herran temppelistä. Hänen poikansa Jootam hallitsi kuninkaan linnaa ja tuomitsi maan kansaa.'),
(1680666,58,14,26,22,'Mitä muuta on kerrottavaa Ussiasta, hänen aikaisemmista ja myöhemmistä vaiheistaan, sen on profeetta Jesaja, Aamoksen poika, pannut kirjaan.'),
(1680667,58,14,26,23,'Ja Ussia meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen vainioon, kuningasten hautojen ääreen; sanottiin näet: "Hän on pitalitautinen". Ja hänen poikansa Jootam tuli kuninkaaksi hänen sijaansa.'),
(1680668,58,14,27,1,'Jootam oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kuusitoista vuotta. Hänen äitinsä nimi oli Jerusa, Saadokin tytär.'),
(1680669,58,14,27,2,'Hän teki sitä, mikä on oikein Herran silmissä, aivan niinkuin hänen isänsä Ussia oli tehnyt, paitsi ettei hän tunkeutunut Herran temppeliin. Mutta kansa yhä vaelsi kelvottomasti.'),
(1680670,58,14,27,3,'Hän rakennutti Yläportin Herran temppeliin ja rakennutti paljon Oofelin muuria.'),
(1680671,58,14,27,4,'Hän rakennutti myös kaupunkeja Juudan vuoristoon, ja metsiin hän rakennutti linnoja ja torneja.'),
(1680672,58,14,27,5,'Hän kävi sotaa ammonilaisten kuningasta vastaan ja voitti heidät; ja ammonilaiset antoivat hänelle sinä vuonna sata talenttia hopeata, kymmenentuhatta koor-mittaa nisuja ja kymmenentuhatta koor-mittaa ohria. Tämän ammonilaiset suorittivat hänelle myöskin toisena ja kolmantena vuotena.'),
(1680673,58,14,27,6,'Niin Jootam tuli yhä mahtavammaksi, koska hän vaelsi vakaasti Herran, Jumalansa, edessä.'),
(1680674,58,14,27,7,'Mitä muuta on kerrottavaa Jootamista ja kaikista hänen sodistaan ja hänen vaelluksestansa, katso, se on kirjoitettuna Israelin ja Juudan kuningasten kirjassa.'),
(1680675,58,14,27,8,'Hän oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kuusitoista vuotta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680676,58,14,27,9,'Ja Jootam meni lepoon isiensä tykö, ja hänet haudattiin Daavidin kaupunkiin. Ja hänen poikansa Aahas tuli kuninkaaksi hänen sijaansa.'),
(1680677,58,14,28,1,'Aahas oli kahdenkymmenen vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kuusitoista vuotta. Hän ei tehnyt sitä, mikä on oikein Herran silmissä, niinkuin hänen isänsä Daavid,'),
(1680678,58,14,28,2,'vaan vaelsi Israelin kuningasten teitä; jopa hän teki valettuja kuvia baaleille.'),
(1680679,58,14,28,3,'Ja hän poltti uhreja Ben-Hinnomin laaksossa ja poltti poikansa tulessa, niiden kansain kauhistavien tekojen mukaan, jotka Herra oli karkoittanut israelilaisten tieltä.'),
(1680680,58,14,28,4,'Ja hän teurasti ja poltti uhreja uhrikukkuloilla ja kummuilla ja jokaisen viheriän puun alla.'),
(1680681,58,14,28,5,'Sentähden Herra, hänen Jumalansa, antoi hänet Aramin kuninkaan käsiin. He voittivat hänet ja ottivat hänen väestään suuren joukon vangiksi ja veivät Damaskoon. Hänet annettiin myöskin Israelin kuninkaan käsiin, ja tämä tuotti hänelle suuren tappion.'),
(1680682,58,14,28,6,'Pekah, Remaljan poika, surmasi Juudasta satakaksikymmentä tuhatta yhtenä päivänä, kaikki sotakuntoisia miehiä, koska he olivat hyljänneet Herran, isiensä Jumalan.'),
(1680683,58,14,28,7,'Ja Sikri, efraimilainen urho, tappoi kuninkaan pojan Maasejan, linnan esimiehen Asrikamin ja kuninkaan lähimmän miehen Elkanan.'),
(1680684,58,14,28,8,'Ja israelilaiset veivät veljiltään vangeiksi vaimoja, poikia ja tyttäriä kaksisataa tuhatta, ryöstivät heiltä myös paljon saalista ja veivät saaliin Samariaan.'),
(1680685,58,14,28,9,'Siellä oli Herran profeetta nimeltä Ooded; tämä meni sotajoukkoa vastaan, kun se oli tulossa Samariaan, ja sanoi heille: "Katso, Herra, teidän isienne Jumala, on vihastunut Juudaan ja antanut heidät teidän käsiinne, ja te olette tappaneet heitä raivossa, joka ulottuu taivaaseen asti.'),
(1680686,58,14,28,10,'Ja nyt te ajattelette pakottaa tämän Juudan väen ja Jerusalemin orjiksenne ja orjattariksenne. Eikö teillä jo ole tunnollanne kyllin rikkomuksia Herraa, Jumalaanne, vastaan?'),
(1680687,58,14,28,11,'Niin kuulkaa nyt minua ja palauttakaa vangit, jotka olette ottaneet veljienne joukosta; sillä Herran vihan hehku on teidän päällänne."'),
(1680688,58,14,28,12,'Silloin muutamat efraimilaisten päämiehistä, Asarja, Joohananin poika, Berekia, Mesillemotin poika, Hiskia, Sallumin poika, ja Amasa, Hadlain poika, nousivat sotaretkeltä tulevia vastaan'),
(1680689,58,14,28,13,'ja sanoivat heille: "Älkää tuoko tänne noita vankeja, sillä te saatatte meidät syyllisiksi Herran edessä, kun ajattelette lisätä meidän syntejämme ja syyllisyyttämme. Onhan meidän syyllisyytemme jo suuri, ja vihan hehku on Israelin päällä."'),
(1680690,58,14,28,14,'Silloin aseväki luopui vangeista ja saaliista päämiesten ja koko seurakunnan edessä.'),
(1680691,58,14,28,15,'Ja nimeltä mainitut miehet nousivat ja ottivat huostaansa vangit ja antoivat saaliista vaatteita kaikille heidän joukossaan, jotka olivat alasti. He antoivat näille vaatteita ja kenkiä, ruokaa ja juomaa, voitelivat heitä ja toimittivat heille, kaikille uupuneille, aasit ja veivät heidät Jerikoon, Palmukaupunkiin, lähelle heidän veljiänsä. Sitten he palasivat Samariaan.'),
(1680692,58,14,28,16,'Siihen aikaan kuningas Aahas lähetti sanansaattajat Assurin kuningasten tykö saadaksensa apua.'),
(1680693,58,14,28,17,'Sillä vielä edomilaisetkin olivat tulleet ja voittaneet Juudan ja ottaneet vankeja.'),
(1680694,58,14,28,18,'Ja filistealaiset olivat tehneet ryöstöretken Alankomaan ja Juudan Etelämaan kaupunkeihin ja valloittaneet Beet-Semeksen, Aijalonin ja Gederotin, niin myös Sookon ja sen tytärkaupungit, Timran ja sen tytärkaupungit ja Gimson ja sen tytärkaupungit, ja he olivat asettuneet niihin.'),
(1680695,58,14,28,19,'Sillä Herra nöyryytti Juudaa Aahaan, Israelin kuninkaan, tähden, koska tämä oli harjoittanut kurittomuutta Juudassa ja ollut uskoton Herraa kohtaan.'),
(1680696,58,14,28,20,'Niin Tillegat-Pilneser, Assurin kuningas, lähti häntä vastaan ja ahdisti häntä eikä tukenut häntä.'),
(1680697,58,14,28,21,'Sillä vaikka Aahas ryösti Herran temppeliä ja kuninkaan ja päämiesten linnoja ja antoi kaiken Assurin kuninkaalle, ei hänellä ollut siitä apua.'),
(1680698,58,14,28,22,'Silloinkin kun häntä ahdistettiin, oli hän, kuningas Aahas, edelleen uskoton Herraa kohtaan.'),
(1680699,58,14,28,23,'Sillä hän uhrasi Damaskon jumalille, jotka olivat voittaneet hänet; hän ajatteli: "Koska Aramin kuningasten jumalat ovat auttaneet heitä, uhraan minäkin niille, että ne minuakin auttaisivat". Mutta ne tulivatkin hänelle ja koko Israelille lankeemukseksi.'),
(1680700,58,14,28,24,'Ja Aahas kokosi Jumalan temppelin kalut ja hakkasi Jumalan temppelin kalut kappaleiksi. Hän sulki Herran temppelin ovet ja teetti itselleen alttareita Jerusalemin joka kolkkaan.'),
(1680701,58,14,28,25,'Ja jokaiseen Juudan kaupunkiin hän teetti uhrikukkuloita polttaakseen uhreja muille jumalille; ja niin hän vihoitti Herran, isiensä Jumalan.'),
(1680702,58,14,28,26,'Mitä muuta on kerrottavaa hänestä ja kaikesta hänen vaelluksestaan, sekä aikaisemmasta että myöhemmästä, katso, se on kirjoitettuna Juudan ja Israelin kuningasten aikakirjassa.'),
(1680703,58,14,28,27,'Ja Aahas meni lepoon isiensä tykö, ja hänet haudattiin kaupunkiin, Jerusalemiin; sillä häntä ei viety Israelin kuningasten hautoihin. Ja hänen poikansa Hiskia tuli kuninkaaksi hänen sijaansa.'),
(1680704,58,14,29,1,'Hiskia tuli kuninkaaksi kahdenkymmenen viiden vuoden vanhana, ja hän hallitsi Jerusalemissa kaksikymmentä yhdeksän vuotta. Hänen äitinsä oli nimeltään Abia, Sakarjan tytär.'),
(1680705,58,14,29,2,'Hän teki sitä, mikä on oikein Herran silmissä, aivan niinkuin hänen isänsä Daavid oli tehnyt.'),
(1680706,58,14,29,3,'Ensimmäisenä hallitusvuotenansa, sen ensimmäisessä kuussa, hän avasi Herran temppelin ovet ja korjasi ne.'),
(1680707,58,14,29,4,'Sitten hän tuotti papit ja leeviläiset ja kokosi ne idässäpäin olevalle aukealle.'),
(1680708,58,14,29,5,'Ja hän sanoi heille: "Kuulkaa minua, te leeviläiset! Pyhittäytykää nyt ja pyhittäkää Herran, isienne Jumalan, temppeli ja toimittakaa saastaisuus pois pyhäköstä.'),
(1680709,58,14,29,6,'Sillä meidän isämme ovat olleet uskottomia ja tehneet sitä, mikä on pahaa Herran, meidän Jumalamme, silmissä, ja hyljänneet hänet. He käänsivät kasvonsa pois Herran asumuksesta ja käänsivät sille selkänsä.'),
(1680710,58,14,29,7,'He myöskin sulkivat eteisen ovet, sammuttivat lamput, eivät polttaneet suitsuketta eivätkä uhranneet polttouhreja pyhäkössä Israelin Jumalalle.'),
(1680711,58,14,29,8,'Sentähden Herran viha on kohdannut Juudaa ja Jerusalemia, ja hän on tehnyt heidät kauhuksi, hämmästykseksi ja pilkaksi, niinkuin te omin silmin näette.'),
(1680712,58,14,29,9,'Katso, meidän isämme ovat kaatuneet miekkaan, ja meidän poikamme, tyttäremme ja vaimomme ovat joutuneet vankeuteen tästä syystä.'),
(1680713,58,14,29,10,'Nyt minä aion tehdä liiton Herran, Israelin Jumalan, kanssa, että hänen vihansa hehku kääntyisi meistä pois.'),
(1680714,58,14,29,11,'Älkää siis, lapseni, olko leväperäisiä, sillä teidät Herra on valinnut seisomaan hänen edessänsä ja palvelemaan häntä, olemaan hänen palvelijansa ja suitsuttamaan hänelle."'),
(1680715,58,14,29,12,'Silloin nousivat leeviläiset: Mahat, Amasain poika, ja Jooel, Asarjan poika, Kehatin jälkeläisistä; Merarin jälkeläisistä Kiis, Abdin poika, ja Asarja, Jehallelelin poika; geersonilaisista Jooah, Simman poika, ja Eeden, Jooahin poika;'),
(1680716,58,14,29,13,'Elisafanin jälkeläisistä Simri ja Jegiel; Aasafin jälkeläisistä Sakarja ja Mattanja;'),
(1680717,58,14,29,14,'Heemanin jälkeläisistä Jehiel ja Siimei; ja Jedutunin jälkeläisistä Semaja ja Ussiel.'),
(1680718,58,14,29,15,'Nämä kokosivat veljensä, pyhittäytyivät ja menivät, niinkuin kuningas oli Herran sanan mukaan käskenyt, puhdistamaan Herran temppeliä.'),
(1680719,58,14,29,16,'Mutta papit menivät sisälle Herran temppeliin puhdistamaan sitä, ja kaiken saastaisuuden, minkä löysivät Herran temppelistä, he veivät Herran temppelin esipihalle; sieltä leeviläiset ottivat sen ja veivät sen ulos Kidronin laaksoon.'),
(1680720,58,14,29,17,'He alkoivat pyhittämisen ensimmäisen kuun ensimmäisenä päivänä, ja kuukauden kahdeksantena päivänä he olivat ehtineet Herran eteiseen, ja he pyhittivät Herran temppeliä kahdeksan päivää; ensimmäisen kuun kuudentenatoista päivänä he lopettivat työnsä.'),
(1680721,58,14,29,18,'Silloin he menivät sisälle kuningas Hiskian tykö ja sanoivat: "Me olemme puhdistaneet koko Herran temppelin, polttouhrialttarin ja kaikki sen kalut ja näkyleipäpöydän ja kaikki sen kalut.'),
(1680722,58,14,29,19,'Kaikki kalut, jotka kuningas Aahas hallitusaikanansa uskottomuudessaan saastutti, me olemme panneet kuntoon ja pyhittäneet, ja katso, ne ovat Herran alttarin edessä."'),
(1680723,58,14,29,20,'Kuningas Hiskia kokosi varhain aamulla kaupungin päämiehet ja meni Herran temppeliin.'),
(1680724,58,14,29,21,'Ja he toivat seitsemän härkää, seitsemän oinasta ja seitsemän karitsaa sekä seitsemän kaurista syntiuhriksi valtakunnan puolesta, pyhäkön puolesta ja Juudan puolesta. Ja hän käski pappi Aaronin poikien, pappien, uhrata ne Herran alttarilla.'),
(1680725,58,14,29,22,'Sitten he teurastivat raavaat, ja papit ottivat veren ja vihmoivat sen alttarille; ja he teurastivat oinaat ja vihmoivat veren alttarille; sitten he teurastivat karitsat ja vihmoivat veren alttarille.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680726,58,14,29,23,'Senjälkeen he toivat syntiuhrikauriit kuninkaan ja seurakunnan eteen, ja nämä laskivat kätensä niiden päälle.'),
(1680727,58,14,29,24,'Ja papit teurastivat ne ja uhrasivat niiden veren syntiuhrina alttarilla, toimittaen koko Israelille sovituksen; sillä kuningas oli käskenyt uhrata polttouhrin ja syntiuhrin koko Israelin puolesta.'),
(1680728,58,14,29,25,'Ja hän asetti leeviläiset Herran temppeliin, kymbaalit, harput ja kanteleet käsissä, niinkuin Daavid ja kuninkaan näkijä Gaad ja profeetta Naatan olivat käskeneet; sillä käsky oli Herran antama hänen profeettainsa kautta.'),
(1680729,58,14,29,26,'Niin leeviläiset seisoivat siinä, Daavidin soittimet käsissä, ja papit, torvet käsissä.'),
(1680730,58,14,29,27,'Ja Hiskia käski uhrata alttarilla polttouhrin; ja kun uhraaminen alkoi, alkoi myöskin Herran veisu ja torvien soitto Daavidin, Israelin kuninkaan, soittimien johtaessa.'),
(1680731,58,14,29,28,'Koko seurakunta kumartaen rukoili, veisu kaikui, ja torvet soivat - kaikkea tätä kesti, kunnes polttouhri oli uhrattu.'),
(1680732,58,14,29,29,'Kun uhraaminen oli päättynyt, polvistuivat kuningas ja kaikki, jotka olivat hänen kanssaan saapuvilla, kumartaen rukoilemaan.'),
(1680733,58,14,29,30,'Ja kuningas Hiskia ja päämiehet käskivät leeviläisten ylistää Herraa Daavidin ja näkijä Aasafin sanoilla; ja nämä ylistivät häntä iloiten, polvistuivat ja kumartaen rukoilivat.'),
(1680734,58,14,29,31,'Sitten Hiskia lausui ja sanoi: "Nyt te olette tuoneet täysin käsin lahjoja Herralle; astukaa esille ja tuokaa teurasuhreja ja kiitosuhreja Herran temppeliin". Silloin seurakunta toi teurasuhreja ja kiitosuhreja, ja jokainen, jonka sydän häntä siihen vaati, myöskin polttouhreja.'),
(1680735,58,14,29,32,'Ja seurakunnan tuomien polttouhrien lukumäärä oli seitsemänkymmentä raavasta, sata oinasta ja kaksisataa karitsaa, nämä kaikki polttouhriksi Herralle.'),
(1680736,58,14,29,33,'Ja pyhiä lahjoja oli kuusisataa raavasta ja kolmetuhatta lammasta.'),
(1680737,58,14,29,34,'Mutta pappeja oli niin vähän, etteivät he voineet nylkeä kaikkia polttouhriteuraita; sentähden heidän veljensä leeviläiset auttoivat heitä, kunnes tämä työ oli suoritettu ja kunnes papit olivat pyhittäytyneet, sillä leeviläiset pyrkivät vilpittömämmin kuin papit pyhittäytymään.'),
(1680738,58,14,29,35,'Myöskin polttouhreja oli paljon ynnä yhteysuhrirasvoja ja polttouhriin kuuluvia juomauhreja.'),
(1680739,58,14,29,36,'Näin järjestettiin palvelus Herran temppelissä. Ja Hiskia ja kaikki kansa iloitsivat siitä, mitä Jumala oli kansalle valmistanut, sillä se oli tapahtunut äkisti.'),
(1680740,58,14,30,1,'Hiskia lähetti sanansaattajat kaikkeen Israeliin ja Juudaan ja kirjoitti myös kirjeet Efraimiin ja Manasseen, että he tulisivat Herran temppeliin Jerusalemiin viettämään pääsiäistä Herran, Israelin Jumalan, kunniaksi.'),
(1680741,58,14,30,2,'Ja kuningas, hänen päämiehensä ja kaikki Jerusalemin seurakunta päättivät viettää pääsiäistä toisessa kuussa,'),
(1680742,58,14,30,3,'sillä he eivät voineet viettää sitä silloin heti, koska pappeja ei ollut pyhittäytynyt riittävää määrää eikä kansa ollut kokoontunut Jerusalemiin.'),
(1680743,58,14,30,4,'Tämä kelpasi kuninkaalle ja kaikelle seurakunnalle,'),
(1680744,58,14,30,5,'ja niin he päättivät kuuluttaa koko Israelissa Beersebasta Daaniin saakka, että oli tultava Jerusalemiin viettämään pääsiäistä Herran, Israelin Jumalan, kunniaksi. Sillä sitä ei oltu vietetty joukolla, niinkuin kirjoitettu oli.'),
(1680745,58,14,30,6,'Juoksijat kulkivat, mukanaan kuninkaan ja hänen päämiestensä kirjeet, halki koko Israelin ja Juudan ja julistivat kuninkaan käskystä: "Te israelilaiset, palatkaa Herran, Aabrahamin, Iisakin ja Israelin Jumalan, tykö, että hän palajaisi niiden tykö, jotka teistä ovat säilyneet ja pelastuneet Assurin kuningasten käsistä.'),
(1680746,58,14,30,7,'Älkää olko niinkuin teidän isänne ja veljenne, jotka olivat uskottomat Herralle, isiensä Jumalalle, niin että hän antoi teidät häviön omiksi, niinkuin te itse näette.'),
(1680747,58,14,30,8,'Älkää siis olko niskureita niinkuin teidän isänne; ojentakaa kätenne Herralle ja tulkaa hänen pyhäkköönsä, jonka hän on pyhittänyt ikuisiksi ajoiksi, ja palvelkaa Herraa, teidän Jumalaanne, että hänen vihansa hehku kääntyisi teistä pois.'),
(1680748,58,14,30,9,'Sillä jos te palajatte Herran tykö, saavat teidän veljenne ja poikanne osakseen laupeuden voittajiltaan ja voivat palata takaisin tähän maahan. Sillä Herra, teidän Jumalanne, on armollinen ja laupias, eikä hän käännä kasvojansa pois teistä, jos te palajatte hänen tykönsä."'),
(1680749,58,14,30,10,'Ja juoksijat kulkivat kaupungista kaupunkiin Efraimin ja Manassen maassa ja aina Sebuloniin saakka. Mutta heille naurettiin ja heitä pilkattiin.'),
(1680750,58,14,30,11,'Kuitenkin Asserista, Manassesta ja Sebulonista muutamat nöyrtyivät ja tulivat Jerusalemiin.'),
(1680751,58,14,30,12,'Myöskin Juudassa vaikutti Jumalan käsi, ja hän antoi heille yksimielisen sydämen tekemään, mitä kuningas ja päämiehet olivat Herran sanan mukaan käskeneet.'),
(1680752,58,14,30,13,'Niin kokoontui paljon kansaa Jerusalemiin viettämään happamattoman leivän juhlaa toisessa kuussa. Se oli hyvin suuri kokous.'),
(1680753,58,14,30,14,'Ja he nousivat ja poistivat alttarit Jerusalemista. Myös kaikki suitsutusalttarit he poistivat ja heittivät Kidronin laaksoon.'),
(1680754,58,14,30,15,'Sitten he teurastivat pääsiäislampaan toisen kuun neljäntenätoista päivänä. Ja papit ja leeviläiset häpesivät ja pyhittäytyivät ja toivat polttouhreja Herran temppeliin.'),
(1680755,58,14,30,16,'Ja he asettuivat paikoilleen, niinkuin heidän velvollisuutensa oli Jumalan miehen Mooseksen lain mukaan. Papit vihmoivat veren, otettuaan sen leeviläisten käsistä.'),
(1680756,58,14,30,17,'Sillä seurakunnassa oli monta, jotka eivät olleet pyhittäytyneet; niin leeviläiset huolehtivat pääsiäislammasten teurastamisesta kaikille, jotka eivät olleet puhtaita, ja niiden pyhittämisestä Herralle.'),
(1680757,58,14,30,18,'Sillä suurin osa kansasta, monet Efraimista ja Manassesta, Isaskarista ja Sebulonista, eivät olleet puhdistautuneet, vaan söivät pääsiäislampaan toisin, kuin kirjoitettu oli. Hiskia oli näet rukoillut heidän puolestaan sanoen: "Herra, joka on hyvä, antakoon anteeksi'),
(1680758,58,14,30,19,'jokaiselle, joka on kiinnittänyt sydämensä Jumalan, Herran, isiensä Jumalan, etsimiseen, vaikka onkin pyhäkköpuhtautta vailla".'),
(1680759,58,14,30,20,'Ja Herra kuuli Hiskiaa ja säästi kansaa.'),
(1680760,58,14,30,21,'Niin israelilaiset, jotka olivat Jerusalemissa, viettivät seitsemän päivää happamattoman leivän juhlaa iloiten suuresti. Ja leeviläiset ja papit ylistivät joka päivä Herraa voimakkailla soittimilla, Herran kunniaksi.'),
(1680761,58,14,30,22,'Ja Hiskia puhutteli ystävällisesti kaikkia leeviläisiä, jotka taitavasti suorittivat tehtävänsä Herran kunniaksi. Ja he söivät seitsemän päivää juhlauhreja ja uhrasivat yhteysuhreja ja ylistivät Herraa, isiensä Jumalaa.'),
(1680762,58,14,30,23,'Ja koko seurakunta päätti viettää juhlaa vielä toiset seitsemän päivää; ja niin vietettiin ilojuhlaa vielä seitsemän päivää.'),
(1680763,58,14,30,24,'Sillä Hiskia, Juudan kuningas, oli antanut seurakunnalle anniksi tuhat härkää ja seitsemän tuhatta lammasta, ja päämiehet olivat antaneet seurakunnalle anniksi tuhat härkää ja kymmenen tuhatta lammasta. Ja paljon pappeja pyhittäytyi.'),
(1680764,58,14,30,25,'Niin koko Juudan seurakunta iloitsi ja samoin papit ja leeviläiset ja koko Israelista tullut seurakunta, niin myös muukalaiset, jotka olivat tulleet Israelin maasta tai asuivat Juudassa.'),
(1680765,58,14,30,26,'Ja Jerusalemissa oli ilo suuri, sillä Israelin kuninkaan Salomon, Daavidin pojan, ajoista asti ei sellaista ollut tapahtunut Jerusalemissa.'),
(1680766,58,14,30,27,'Ja leeviläiset papit nousivat ja siunasivat kansan; ja heidän äänensä tuli kuulluksi, ja heidän rukouksensa tuli Herran pyhään asumukseen, taivaaseen.'),
(1680767,58,14,31,1,'Kun kaikki tämä oli päättynyt, lähtivät kaikki saapuvilla olevat israelilaiset Juudan kaupunkeihin ja murskasivat patsaat, hakkasivat maahan asera-karsikot ja kukistivat uhrikukkulat ja alttarit perinpohjin koko Juudassa, Benjaminissa, Efraimissa ja Manassessa. Sitten kaikki israelilaiset palasivat kukin perintömaallensa, kaupunkeihinsa.'),
(1680768,58,14,31,2,'Ja Hiskia asetti pappien ja leeviläisten osastot, heidän osastojensa mukaan, kunkin hänen papillisen tai leeviläisen palvelustehtävänsä mukaan, polttouhreja ja yhteysuhreja toimitettaessa palvelemaan, kiittämään ja ylistämään Herran leirin porteissa.'),
(1680769,58,14,31,3,'Minkä kuningas antoi omaisuudestaan, se käytettiin polttouhreiksi, aamu- ja ehtoopolttouhreiksi sekä sapatteina, uudenkuun päivinä ja juhlina uhrattaviksi polttouhreiksi, niinkuin on kirjoitettuna Herran laissa.'),
(1680770,58,14,31,4,'Ja hän käski kansan, Jerusalemin asukasten, antaa papeille ja leeviläisille heidän osuutensa, että nämä pitäisivät kiinni Herran laista.'),
(1680771,58,14,31,5,'Kun tämä sana levisi, antoivat israelilaiset runsaat uutiset jyvistä, viinistä, öljystä ja hunajasta ja kaikesta pellon sadosta; he toivat runsaat kymmenykset kaikesta.'),
(1680772,58,14,31,6,'Ja ne israelilaiset ja Juudan miehet, jotka asuivat Juudan kaupungeissa, toivat hekin kymmenykset raavaista ja pikkukarjasta sekä kymmenykset Herralle, Jumalallensa, pyhitetyistä pyhistä lahjoista, ja panivat ne eri kasoihin.'),
(1680773,58,14,31,7,'Kolmannessa kuussa he alkoivat panna kasoihin, ja seitsemännessä kuussa he sen lopettivat.'),
(1680774,58,14,31,8,'Kun Hiskia ja päämiehet tulivat ja näkivät kasat, kiittivät he Herraa ja hänen kansaansa Israelia.'),
(1680775,58,14,31,9,'Ja kun Hiskia kysyi papeilta ja leeviläisiltä näistä kasoista,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680776,58,14,31,10,'vastasi hänelle ylimmäinen pappi Asarja, joka oli Saadokin sukua, ja sanoi: "Siitä alkaen, kun ruvettiin tuomaan antia Herran temppeliin, me olemme syöneet ja tulleet ravituiksi, ja kuitenkin on jäänyt paljon tähteeksi; sillä Herra on siunannut kansaansa, ja niin on tämä paljous jäänyt tähteeksi."'),
(1680777,58,14,31,11,'Niin Hiskia käski laittaa kammioita Herran temppeliin. Ja kun ne oli laitettu,'),
(1680778,58,14,31,12,'tuotiin niihin tunnollisesti anti, kymmenys ja pyhät lahjat. Ja niiden esimiehenä oli leeviläinen Koonanja, ja hänen veljensä Siimei oli häntä lähinnä.'),
(1680779,58,14,31,13,'Ja Jehiel, Asasja, Nahat, Asael, Jerimot, Joosabat, Eliel, Jismakja, Mahat ja Benaja olivat Koonanjan ja hänen veljensä Siimein käskyläisinä kuningas Hiskian ja Asarjan, Jumalan temppelin esimiehen, määräyksestä.'),
(1680780,58,14,31,14,'Ja leeviläinen Koore, Jimnan poika, joka oli ovenvartijana idän puolella, hoiti Jumalalle annetut vapaaehtoiset lahjat ja Herralle tulevan annin ja korkeasti-pyhäin lahjain suorituksen.'),
(1680781,58,14,31,15,'Ja hänen johdossaan olivat Eedem, Minjamin, Jeesua, Semaja, Amarja ja Sekanja, joiden oli pappiskaupungeissa tunnollisesti suoritettava osuudet veljillensä, niin pienille kuin suurille, osastoittain,'),
(1680782,58,14,31,16,'paitsi sukuluetteloihin merkityille miehenpuolille, kolmivuotiaille ja sitä vanhemmille, kaikille, jotka menivät Herran temppeliin tekemään palvelusta, kunakin päivänä sen päivän palveluksen, hoitamaan tehtäviään, osastoittain.'),
(1680783,58,14,31,17,'Papit merkittiin sukuluetteloihin perhekunnittain ja leeviläisistä kaksikymmenvuotiaat ja sitä vanhemmat, palvelustehtäviensä mukaan, osastoittain,'),
(1680784,58,14,31,18,'nimittäin niin, että sukuluetteloihin merkittiin kaikki heidän pienet lapsensa, vaimonsa, poikansa ja tyttärensä, koko heidän joukkonsa, sillä he hoitivat sitä, mikä pyhää oli, tunnollisesti.'),
(1680785,58,14,31,19,'Aaronin pojilla, papeilla, jotka asuivat kaupunkiensa laidunmailla, oli joka kaupungissa nimeltä mainitut miehet, joiden oli suoritettava osuudet kaikille miehenpuolille pappien joukossa ja kaikille sukuluetteloihin merkityille leeviläisille.'),
(1680786,58,14,31,20,'Näin Hiskia teki koko Juudassa; hän teki sitä, mikä oli hyvää, oikeata ja totta Herran, hänen Jumalansa, edessä.'),
(1680787,58,14,31,21,'Ja kaiken, mihin hän ryhtyi etsiessään Jumalaansa, koskipa se palvelusta Jumalan temppelissä tai lakia ja käskyjä, sen hän teki kaikesta sydämestänsä, ja hän menestyi.'),
(1680788,58,14,32,1,'Näiden tapausten ja Hiskian vakaan vaelluksen jälkeen tuli Sanherib, Assurin kuningas, ja hyökkäsi Juudaan, piiritti sen varustettuja kaupunkeja ja aikoi valloittaa ne itsellensä.'),
(1680789,58,14,32,2,'Kun Hiskia näki Sanheribin tulevan ja olevan aikeessa sotia Jerusalemia vastaan,'),
(1680790,58,14,32,3,'neuvotteli hän päämiestensä ja urhojensa kanssa tukkiaksensa vesilähteet, jotka olivat kaupungin ulkopuolella; ja he kannattivat häntä siinä.'),
(1680791,58,14,32,4,'Niin kokoontui paljon kansaa, ja he tukkivat kaikki lähteet ja puron, joka juoksee sen seudun läpi; sillä he sanoivat: "Miksi Assurin kuninkaat tultuansa löytäisivät vettä viljalti?"'),
(1680792,58,14,32,5,'Ja hän rohkaisi mielensä, rakensi koko revityn osan muuria ja korotti torneja ja teki sen ulkopuolelle toisen muurin, varusti Millon Daavidin kaupungissa ja teetti paljon heittoaseita ja kilpiä.'),
(1680793,58,14,32,6,'Ja hän asetti sotapäälliköitä kansalle ja kokosi heidät luoksensa aukealle kaupungin portin eteen ja puhui ystävällisesti heille ja sanoi:'),
(1680794,58,14,32,7,'"Olkaa lujat ja rohkeat, älkää peljätkö älkääkä arkailko Assurin kuningasta ja kaikkea joukkoa, joka on hänen kanssansa; sillä se, joka on meidän kanssamme, on suurempi kuin se, joka on hänen kanssansa.'),
(1680795,58,14,32,8,'Hänen kanssansa on lihan käsivarsi, mutta meidän kanssamme on Herra, meidän Jumalamme, meitä auttamassa ja meidän sotiamme sotimassa." Ja kansa luotti Hiskian, Juudan kuninkaan, sanoihin.'),
(1680796,58,14,32,9,'Tämän jälkeen Sanherib, Assurin kuningas, ollessaan itse koko sotavoimansa kanssa Laakiin edustalla, lähetti palvelijoitansa Jerusalemiin Hiskian, Juudan kuninkaan, luo ja kaikkien Jerusalemissa olevien Juudan miesten luo ja käski sanoa:'),
(1680797,58,14,32,10,'"Näin sanoo Sanherib, Assurin kuningas: Mihin te luotatte, kun jäätte Jerusalemiin saarroksiin?'),
(1680798,58,14,32,11,'Eikö Hiskia viettele teitä ja saata teitä kuolemaan nälkään ja janoon, kun hän sanoo: Herra, meidän Jumalamme, pelastaa meidät Assurin kuninkaan käsistä?'),
(1680799,58,14,32,12,'Eikö tämä sama Hiskia ole poistanut hänen uhrikukkuloitansa ja alttareitansa ja sanonut Juudalle ja Jerusalemille näin: ''Yhden ainoan alttarin edessä on teidän kumartaen rukoiltava ja sillä uhreja poltettava''?'),
(1680800,58,14,32,13,'Ettekö tiedä, mitä minä ja minun isäni olemme tehneet muiden maiden kaikille kansoille? Ovatko näiden maiden kansain jumalat voineet pelastaa maatansa minun käsistäni?'),
(1680801,58,14,32,14,'Onko kukaan minun isieni tuhoamien kansojen kaikista jumalista voinut pelastaa kansaansa minun käsistäni? Kuinka sitten teidän Jumalanne voisi pelastaa teidät minun käsistäni?'),
(1680802,58,14,32,15,'Älkää siis antako Hiskian näin pettää ja vietellä itseänne älkääkä uskoko häntä, sillä ei minkään kansan eikä minkään valtakunnan jumala ole voinut pelastaa kansaansa minun käsistäni tai minun isieni käsistä, saati sitten teidän Jumalanne: ei hän pelasta teitä minun käsistäni."'),
(1680803,58,14,32,16,'Ja hänen palvelijansa puhuivat vielä enemmän Herraa Jumalaa ja hänen palvelijaansa Hiskiaa vastaan.'),
(1680804,58,14,32,17,'Hän kirjoitti myös kirjeen herjatakseen Herraa, Israelin Jumalaa, ja puhuakseen häntä vastaan; siinä sanottiin näin: "Niinkuin muiden maiden kansain jumalat eivät ole pelastaneet kansojansa minun käsistäni, niin ei Hiskiankaan Jumala ole pelastava kansaansa minun käsistäni".'),
(1680805,58,14,32,18,'Ja Jerusalemin kansalle, jota oli muurilla, he huusivat kovalla äänellä juudankielellä nostaakseen heissä pelon ja kauhun, että saisivat kaupungin valloitetuksi.'),
(1680806,58,14,32,19,'Ja he puhuivat Jerusalemin Jumalasta niinkuin muiden maiden kansain jumalista, jotka ovat ihmiskätten tekoa.'),
(1680807,58,14,32,20,'Mutta kuningas Hiskia ja profeetta Jesaja, Aamoksen poika, rukoilivat tämän tähden ja huusivat taivaan puoleen.'),
(1680808,58,14,32,21,'Silloin Herra lähetti enkelin, joka tuhosi kaikki sotaurhot, ruhtinaat ja päälliköt Assurin kuninkaan leirissä, niin että hän häpeä kasvoillaan palasi takaisin maahansa. Ja kun hän kerran meni jumalansa temppeliin, kaatoivat hänet siellä miekalla ne, jotka olivat lähteneet hänen omasta ruumiistansa.'),
(1680809,58,14,32,22,'Näin Herra vapahti Hiskian ja Jerusalemin asukkaat Sanheribin, Assurin kuninkaan, käsistä ja kaikkien käsistä, ja hän johdatti heitä joka taholla.'),
(1680810,58,14,32,23,'Ja monet toivat Herralle lahjoja Jerusalemiin ja Hiskialle, Juudan kuninkaalle, kalleuksia; ja hän kohosi sen jälkeen kaikkien kansojen silmissä.'),
(1680811,58,14,32,24,'Niihin aikoihin Hiskia sairastui ja oli kuolemaisillaan. Niin hän rukoili Herraa, ja hän vastasi hänelle ja antoi hänelle tapahtua ihmeen.'),
(1680812,58,14,32,25,'Mutta Hiskia ei palkinnut hyvää hyvällä, vaan hänen sydämensä ylpistyi; sentähden hänen ja Juudan ja Jerusalemin osaksi tuli viha.'),
(1680813,58,14,32,26,'Mutta kun Hiskia nöyrtyi sydämensä ylpeydestä, hän ja Jerusalemin asukkaat, ei Herran viha kohdannut heitä Hiskian päivinä.'),
(1680814,58,14,32,27,'Hiskialle tuli ylen paljon rikkautta ja kunniaa; hän hankki itselleen aarrekammioita hopeata, kultaa, kalliita kiviä, hajuaineita, kilpiä ja kaikkinaisia kallisarvoisia kaluja varten,'),
(1680815,58,14,32,28,'varastohuoneita jyvä-, viini- ja öljysatoa varten ja talleja kaikenlaisille juhdille ja karjalaumoja tarhoihin.'),
(1680816,58,14,32,29,'Myös rakennutti hän itsellensä kaupunkeja ja hankki suuret laumat pikkukarjaa ja raavaskarjaa, sillä Jumala oli antanut hänelle ylen suuren omaisuuden.'),
(1680817,58,14,32,30,'Hiskia myös tukki Giihonin veden yläjuoksun ja johti veden alas, länteenpäin, Daavidin kaupunkiin. Ja Hiskia menestyi kaikessa, mitä hän teki.'),
(1680818,58,14,32,31,'Niinpä Jumala ainoastaan koetellakseen häntä ja tullakseen tuntemaan kaiken, mitä hänen sydämessään oli, jätti hänet Baabelin ruhtinasten lähettiläiden valtaan, jotka olivat lähetetyt hänen luokseen tiedustelemaan ihmettä, joka oli tapahtunut maassa.'),
(1680819,58,14,32,32,'Mitä muuta on kerrottavaa Hiskiasta ja hänen hurskaista teoistansa, katso, se on kirjoitettuna profeetta Jesajan, Aamoksen pojan, näyssä, Juudan ja Israelin kuningasten kirjassa.'),
(1680820,58,14,32,33,'Ja Hiskia meni lepoon isiensä tykö, ja hänet haudattiin siihen, mistä noustaan Daavidin jälkeläisten haudoille. Ja koko Juuda ja Jerusalemin asukkaat osoittivat hänelle kunniaa, kun hän kuoli. Ja hänen poikansa Manasse tuli kuninkaaksi hänen sijaansa.'),
(1680821,58,14,33,1,'Manasse oli kahdentoista vuoden vanha tullessansa kuninkaaksi, ja hän hallitsi Jerusalemissa viisikymmentä viisi vuotta.'),
(1680822,58,14,33,2,'Hän teki sitä, mikä on pahaa Herran silmissä, niiden kansain kauhistavien tekojen mukaan, jotka Herra oli karkoittanut israelilaisten tieltä.'),
(1680823,58,14,33,3,'Hän rakensi jälleen uhrikukkulat, jotka hänen isänsä Hiskia oli kukistanut, pystytti alttareja baaleille, teki aseroja ja kumarsi ja palveli kaikkea taivaan joukkoa.'),
(1680824,58,14,33,4,'Hän rakensi alttareja myös Herran temppeliin, josta Herra oli sanonut: "Jerusalemissa on minun nimeni oleva iankaikkisesti".'),
(1680825,58,14,33,5,'Hän rakensi alttareja kaikelle taivaan joukolle Herran temppelin molempiin esipihoihin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680826,58,14,33,6,'Myös pani hän poikansa kulkemaan tulen läpi Ben-Hinnomin laaksossa, ennusteli merkeistä, harjoitti noituutta ja velhoutta ja hankki itsellensä vainaja- ja tietäjähenkien manaajia; hän teki paljon sitä, mikä on pahaa Herran silmissä, ja vihoitti hänet.'),
(1680827,58,14,33,7,'Ja teettämänsä veistetyn kuvapatsaan hän asetti Jumalan temppeliin, josta Jumala oli sanonut Daavidille ja hänen pojallensa Salomolle: "Tähän temppeliin ja Jerusalemiin, jonka minä olen valinnut kaikista Israelin sukukunnista, minä asetan nimeni ikiajoiksi.'),
(1680828,58,14,33,8,'Enkä minä enää kuljeta Israelin jalkoja pois siitä maasta, jonka olen määrännyt teidän isillenne, jos Israel vain tarkoin noudattaa kaikkea, mitä minä olen käskenyt heidän noudattaa, koko lakia ja käskyjä ja oikeuksia, jotka ovat Mooseksen kautta annetut."'),
(1680829,58,14,33,9,'Mutta Manasse eksytti Juudan ja Jerusalemin asukkaat tekemään enemmän pahaa, kuin olivat tehneet ne kansat, jotka Herra oli hävittänyt israelilaisten tieltä.'),
(1680830,58,14,33,10,'Ja Herra puhui Manasselle ja hänen kansallensa, mutta he eivät kuunnelleet.'),
(1680831,58,14,33,11,'Niin Herra toi Assurin kuninkaan sotapäälliköt heidän kimppuunsa. He ottivat Manassen kiinni koukuilla, kytkivät hänet vaskikahleisiin ja veivät hänet Baabeliin.'),
(1680832,58,14,33,12,'Mutta ahdingossa ollessaan hän etsi Herran, Jumalansa, mielisuosiota ja nöyrtyi syvästi isiensä Jumalan edessä.'),
(1680833,58,14,33,13,'Ja kun hän näin rukoili häntä, niin Jumala taipui ja kuuli hänen rukouksensa ja toi hänet takaisin Jerusalemiin, hänen valtakuntaansa. Silloin Manasse tuli tietämään, että Herra on Jumala.'),
(1680834,58,14,33,14,'Sen jälkeen hän rakennutti Daavidin kaupungin ulomman muurin, länteen päin Giihonista, laaksoon, aina Kalaporttiin saakka, niin että se ympäröi Oofelin, ja hän teki siitä hyvin korkean. Ja hän asetti sotapäälliköitä kaikkiin Juudan varustettuihin kaupunkeihin.'),
(1680835,58,14,33,15,'Ja hän poisti vieraat jumalat ja kuvapatsaan Herran temppelistä sekä kaikki alttarit, jotka hän oli rakennuttanut Herran temppelin vuorelle ja Jerusalemiin, ja heitätti ne kaupungin ulkopuolelle.'),
(1680836,58,14,33,16,'Ja hän pani kuntoon Herran alttarin ja uhrasi sillä yhteys- ja kiitosuhreja ja kehoitti Juudaa palvelemaan Herraa, Israelin Jumalaa.'),
(1680837,58,14,33,17,'Mutta kansa uhrasi edelleen uhrikukkuloilla, kuitenkin ainoastaan Herralle, Jumalallensa.'),
(1680838,58,14,33,18,'Mitä muuta on kerrottavaa Manassesta, ja kuinka hän rukoili Jumalaansa, ja näkijäin puheista, jotka puhuivat hänelle Herran, Israelin Jumalan, nimessä, katso, se on Israelin kuningasten aikakirjassa.'),
(1680839,58,14,33,19,'Ja hänen rukouksestaan ja kuinka hän tuli kuulluksi, ja kaikista hänen synneistään ja uskottomuudestaan ja niistä paikoista, joihin hän rakennutti uhrikukkuloita ja pystytti asera-karsikoita ja jumalankuvia, ennenkuin hän nöyrtyi, katso, niistä on kirjoitettu Hoosain aikakirjaan.'),
(1680840,58,14,33,20,'Ja Manasse meni lepoon isiensä tykö, ja hänet haudattiin linnaansa. Ja hänen poikansa Aamon tuli kuninkaaksi hänen sijaansa.'),
(1680841,58,14,33,21,'Aamon oli kahdenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kaksi vuotta.'),
(1680842,58,14,33,22,'Hän teki sitä, mikä on pahaa Herran silmissä, niinkuin hänen isänsä Manasse oli tehnyt. Ja Aamon uhrasi kaikille niille jumalankuville, jotka hänen isänsä Manasse oli teettänyt, ja palveli niitä.'),
(1680843,58,14,33,23,'Mutta hän ei nöyrtynyt Herran edessä, niinkuin hänen isänsä Manasse oli nöyrtynyt, vaan hän, Aamon, sälytti päällensä suuren syntivelan.'),
(1680844,58,14,33,24,'Niin hänen palvelijansa tekivät salaliiton häntä vastaan ja tappoivat hänet hänen linnassansa.'),
(1680845,58,14,33,25,'Mutta maan kansa surmasi kaikki ne, jotka olivat tehneet salaliiton kuningas Aamonia vastaan; ja maan kansa teki hänen poikansa Joosian kuninkaaksi hänen sijaansa.'),
(1680846,58,14,34,1,'Joosia oli kahdeksan vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kolmekymmentä yksi vuotta.'),
(1680847,58,14,34,2,'Hän teki sitä, mikä on oikein Herran silmissä, ja vaelsi isänsä Daavidin teitä, poikkeamatta oikealle tai vasemmalle.'),
(1680848,58,14,34,3,'Kahdeksantena hallitusvuotenaan, ollessansa vielä nuorukainen, hän alkoi etsiä isänsä Daavidin Jumalaa; ja kahdentenatoista vuotena hän alkoi puhdistaa Juudaa ja Jerusalemia uhrikukkuloista ja asera-karsikoista sekä veistetyistä ja valetuista jumalankuvista.'),
(1680849,58,14,34,4,'Baalin alttarit kukistettiin hänen läsnäollessaan, ja niiden yli kohoavat auringonpatsaat hän hakkasi maahan, ja asera-karsikot sekä veistetyt ja valetut jumalankuvat hän murskasi ja rouhensi ja sirotteli niiden haudoille, jotka olivat niille uhranneet.'),
(1680850,58,14,34,5,'Ja pappien luut hän poltti heidän alttareillaan. Niin hän puhdisti Juudan ja Jerusalemin.'),
(1680851,58,14,34,6,'Manassen, Efraimin ja Simeonin kaupungeissa aina Naftaliin asti, yltympäri, hän heidän miekoillaan'),
(1680852,58,14,34,7,'kukisti alttarit, löi palasiksi ja rouhensi asera-karsikot ja jumalankuvat, ja hän hakkasi maahan kaikki auringonpatsaat koko Israelin maasta. Sitten hän palasi Jerusalemiin.'),
(1680853,58,14,34,8,'Kahdeksantenatoista hallitusvuotenaan, puhdistaessaan maata ja temppeliä, hän lähetti Saafanin, Asaljan pojan, kaupungin päällikön Maasejan ja kansleri Jooahin, Jooahaan pojan, korjaamaan Herran, hänen Jumalansa, temppeliä.'),
(1680854,58,14,34,9,'Ja he tulivat ylimmäisen papin Hilkian luo ja jättivät Jumalan temppeliin tuodut rahat, joita leeviläiset, ovenvartijat, olivat koonneet Manassesta, Efraimista ja koko muusta Israelista ja koko Juudasta, Benjaminista ja Jerusalemin asukkailta.'),
(1680855,58,14,34,10,'He antoivat ne työnteettäjille, jotka oli pantu valvomaan töitä Herran temppelissä, ja nämä maksoivat niillä työmiehet, jotka työskentelivät Herran temppelissä, laittoivat ja korjasivat temppeliä;'),
(1680856,58,14,34,11,'niistä annettiin myös puusepille ja rakentajille, että nämä ostaisivat hakattuja kiviä ja puutavaraa kiinnitysparruiksi ja kattohirsiksi niihin rakennuksiin, jotka Juudan kuninkaat olivat turmelleet.'),
(1680857,58,14,34,12,'Nämä miehet toimivat siinä työssä luottamusmiehinä. Ja leeviläiset Jahat ja Obadja, Merarin jälkeläiset, ja Sakarja ja Mesullam, Kehatin jälkeläiset, oli pantu valvomaan ja johtamaan heitä, ja myös kaikki leeviläiset, jotka ymmärsivät soittimia.'),
(1680858,58,14,34,13,'He myöskin valvoivat taakankantajia ja johtivat kaikkia työmiehiä eri töissä. Leeviläisiä oli kirjureina, virkamiehinä ja ovenvartijoina.'),
(1680859,58,14,34,14,'Kun he olivat viemässä ulos Herran temppeliin tuotuja rahoja, löysi pappi Hilkia Herran lain kirjan, joka oli annettu Mooseksen kautta.'),
(1680860,58,14,34,15,'Ja Hilkia lausui ja sanoi kirjuri Saafanille: "Minä löysin Herran temppelistä lain kirjan". Ja Hilkia antoi kirjan Saafanille.'),
(1680861,58,14,34,16,'Saafan vei kirjan kuninkaalle ja teki lisäksi kuninkaalle selon asiasta, sanoen: "Kaikki, mitä annettiin palvelijaisi tehtäväksi, he ovat tehneet:'),
(1680862,58,14,34,17,'he ovat ottaneet esille rahat, jotka olivat Herran temppelissä, ja antaneet ne työnvalvojille ja työnteettäjille".'),
(1680863,58,14,34,18,'Ja kirjuri Saafan kertoi kuninkaalle sanoen: "Pappi Hilkia antoi minulle erään kirjan". Ja Saafan luki siitä kuninkaalle.'),
(1680864,58,14,34,19,'Kun kuningas kuuli lain sanat, repäisi hän vaatteensa.'),
(1680865,58,14,34,20,'Ja kuningas käski Hilkiaa, Ahikamia, Saafanin poikaa, Abdonia, Miikan poikaa, kirjuri Saafania ja Asajaa, kuninkaan palvelijaa, sanoen:'),
(1680866,58,14,34,21,'"Menkää ja kysykää minun puolestani ja niiden puolesta, joita on jäljellä Israelista ja Juudasta, neuvoa Herralta tästä löydetystä kirjasta. Sillä suuri on Herran viha, joka on vuodatettu meidän ylitsemme, sentähden että meidän isämme eivät ole noudattaneet Herran sanaa eivätkä tehneet mitään kaikesta siitä, mikä on kirjoitettuna tässä kirjassa."'),
(1680867,58,14,34,22,'Niin Hilkia ynnä ne muut, jotka kuningas määräsi, menivät naisprofeetta Huldan tykö, joka oli vaatevaraston hoitajan Sallumin, Tokhatin pojan, Hasran pojanpojan, vaimo ja asui Jerusalemissa, toisessa kaupunginosassa. Ja he puhuivat hänelle, niinkuin edellä mainittiin.'),
(1680868,58,14,34,23,'Niin hän sanoi heille: "Näin sanoo Herra, Israelin Jumala: Sanokaa sille miehelle, joka lähetti teidät minun tyköni:'),
(1680869,58,14,34,24,'''Näin sanoo Herra: Katso, minä annan onnettomuuden kohdata tätä paikkaa ja sen asukkaita, kaikkien kirousten, jotka on kirjoitettu siihen kirjaan, jota on luettu Juudan kuninkaalle,'),
(1680870,58,14,34,25,'koska he ovat hyljänneet minut ja polttaneet uhreja muille jumalille ja vihoittaneet minut kaikilla kättensä teoilla; sillä minun vihani on vuodatettu tämän paikan yli, eikä se ole sammuva.'),
(1680871,58,14,34,26,'Mutta Juudan kuninkaalle, joka on lähettänyt teidät kysymään neuvoa Herralta, sanokaa näin: Näin sanoo Herra, Israelin Jumala, niistä sanoista, jotka sinä olet kuullut:'),
(1680872,58,14,34,27,'Koska sydämesi on pehminnyt ja sinä olet nöyrtynyt Jumalan edessä, kuullessasi, mitä hän on puhunut tätä paikkaa ja sen asukkaita vastaan, koska sinä olet nöyrtynyt minun edessäni ja reväissyt vaatteesi ja itkenyt minun edessäni, niin minä myös olen kuullut sinua, sanoo Herra.'),
(1680873,58,14,34,28,'Katso, minä korjaan sinut isiesi tykö, ja sinä saat rauhassa siirtyä hautaasi, ja sinun silmäsi pääsevät näkemästä kaikkea onnettomuutta, minkä minä annan kohdata tätä paikkaa ja sen asukkaita.''" Ja he toivat kuninkaalle tämän vastauksen.'),
(1680874,58,14,34,29,'Niin kuningas lähetti kokoamaan luoksensa kaikki Juudan ja Jerusalemin vanhimmat.'),
(1680875,58,14,34,30,'Ja kuningas meni Herran temppeliin, hän ja kaikki Juudan miehet ja Jerusalemin asukkaat, myöskin papit ja leeviläiset, kaikki kansa suurimmasta pienimpään asti, ja hän luki heidän kuultensa kaikki Herran temppelistä löydetyn liitonkirjan sanat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680876,58,14,34,31,'Ja kuningas asettui paikallensa ja teki Herran edessä liiton, että heidän tuli seurata Herraa, noudattaa hänen käskyjänsä, todistuksiansa ja säädöksiänsä kaikesta sydämestään ja kaikesta sielustansa ja täyttää liiton sanat, jotka ovat kirjoitetut siihen kirjaan.'),
(1680877,58,14,34,32,'Ja hän otti siihen liittoon kaikki, jotka olivat Jerusalemissa ja Benjaminissa. Ja Jerusalemin asukkaat tekivät, niinkuin Jumalan, heidän isiensä Jumalan, liitto vaati.'),
(1680878,58,14,34,33,'Ja Joosia poisti kaikki kauhistukset israelilaisten kaikista maakunnista ja vaati jokaista, joka Israelissa oli, palvelemaan Herraa, heidän Jumalaansa. Niin kauan kuin hän eli, he eivät luopuneet pois Herrasta, isiensä Jumalasta.'),
(1680879,58,14,35,1,'Sitten Joosia vietti Jerusalemissa pääsiäistä Herran kunniaksi. Pääsiäislammas teurastettiin ensimmäisen kuun neljäntenätoista päivänä.'),
(1680880,58,14,35,2,'Hän asetti papit heidän palvelustehtäviinsä ja rohkaisi heitä palvelemaan Herran temppelissä.'),
(1680881,58,14,35,3,'Ja hän sanoi leeviläisille, jotka opettivat kaikkea Israelia ja jotka olivat pyhitetyt Herralle: "Pankaa pyhä arkki temppeliin, jonka Salomo, Daavidin poika, Israelin kuningas, on rakentanut; ei teidän enää tarvitse kantaa sitä olallanne. Palvelkaa nyt Herraa, Jumalaanne, ja hänen kansaansa Israelia.'),
(1680882,58,14,35,4,'Valmistautukaa perhekunnittain, osastojenne mukaan, Daavidin, Israelin kuninkaan, määräyksen ja hänen poikansa Salomon käskykirjan mukaan,'),
(1680883,58,14,35,5,'ja asettukaa pyhäkköön veljienne, rahvaan, perhekuntaryhmien mukaan, niin että jokaista ryhmää kohden on yksi leeviläisten perhekuntaosasto.'),
(1680884,58,14,35,6,'Niin teurastakaa pääsiäislammas ja pyhittäytykää ja valmistakaa se veljillenne, tehdäksenne Herran sanan mukaan, joka on puhuttu Mooseksen kautta."'),
(1680885,58,14,35,7,'Ja Joosia antoi rahvaalle anniksi pikkukarjaa, karitsoita ja vohlia, kolmekymmentä tuhatta luvultaan, kaikki pääsiäisuhreiksi kaikille saapuvilla oleville, ja kolmetuhatta raavasta, kaikki nämä kuninkaan omaisuutta.'),
(1680886,58,14,35,8,'Ja hänen päämiehensä antoivat vapaaehtoisesti annin kansalle, papeille ja leeviläisille. Hilkia, Sakarja ja Jehiel, Jumalan temppelin esimiehet, antoivat papeille pääsiäisuhreiksi kaksituhatta kuusisataa karitsaa, niin myös kolmesataa raavasta.'),
(1680887,58,14,35,9,'Ja Koonanja, Semaja ja hänen veljensä Netanel, sekä Hasabja, Jegiel ja Joosabad, leeviläisten päämiehet, antoivat antina leeviläisille pääsiäisuhreiksi viisituhatta karitsaa ja viisisataa raavasta.'),
(1680888,58,14,35,10,'Näin järjestettiin jumalanpalvelus. Ja papit asettuivat paikoilleen ja samoin leeviläiset osastoittain, niinkuin kuningas oli käskenyt.'),
(1680889,58,14,35,11,'Sitten teurastettiin pääsiäislammas, ja papit vihmoivat veren, jonka olivat ottaneet leeviläisten käsistä; ja leeviläiset nylkivät nahan.'),
(1680890,58,14,35,12,'Mutta he panivat syrjään polttouhrikappaleet, antaakseen ne rahvaalle perhekuntaryhmittäin, uhrattaviksi Herralle, niinkuin on kirjoitettuna Mooseksen kirjassa; samoin he tekivät myös raavaille.'),
(1680891,58,14,35,13,'Ja he paistoivat tulella pääsiäislampaan säädetyllä tavalla; mutta pyhät lahjat he keittivät padoissa, ruukuissa ja vadeissa ja veivät ne kiiruusti rahvaalle.'),
(1680892,58,14,35,14,'Sitten he valmistivat itsellensä ja papeille, sillä papit, Aaronin pojat, olivat yöhön saakka uhraamassa polttouhria ja rasvoja; sentähden leeviläiset valmistivat itsellensä ja papeille, Aaronin pojille.'),
(1680893,58,14,35,15,'Ja veisaajat, Aasafin pojat, olivat paikoillansa, niinkuin Daavid, Aasaf, Heeman ja Jedutun, kuninkaan näkijä, olivat määränneet, niin myös ovenvartijat jokaisella portilla; heidän ei ollut lupa lähteä palveluksestaan, vaan heidän leeviläiset veljensä valmistivat heille.'),
(1680894,58,14,35,16,'Näin järjestettiin kaikki Herran palvelus sinä päivänä, pääsiäisen vietto ja polttouhrien uhraaminen Herran alttarilla, niinkuin kuningas Joosia oli käskenyt.'),
(1680895,58,14,35,17,'Näin viettivät saapuvilla olevat israelilaiset sinä aikana pääsiäistä ja happamattoman leivän juhlaa seitsemän päivää.'),
(1680896,58,14,35,18,'Sellaista pääsiäistä ei oltu vietetty Israelissa profeetta Samuelin ajoista asti; sillä ei kukaan Israelin kuninkaista ollut viettänyt semmoista pääsiäistä, kuin nyt viettivät Joosia, papit ja leeviläiset, koko Juuda ja saapuvilla olevat israelilaiset sekä Jerusalemin asukkaat.'),
(1680897,58,14,35,19,'Joosian kahdeksantenatoista hallitusvuotena vietettiin tämä pääsiäinen.'),
(1680898,58,14,35,20,'Kaiken tämän jälkeen, sittenkuin Joosia oli pannut kuntoon temppelin, lähti Neko, Egyptin kuningas, sotimaan Karkemista vastaan, joka on Eufratin varrella; ja Joosia meni häntä vastaan.'),
(1680899,58,14,35,21,'Niin Neko lähetti sanansaattajat hänen luokseen ja käski sanoa: "Mitä sinulla on tekemistä minun kanssani, Juudan kuningas? Enhän minä nyt tule sinua vastaan, vaan sitä sukua vastaan, joka on sodassa minun kanssani, ja Jumala on käskenyt minua kiiruhtamaan. Jätä rauhaan Jumala, joka on minun kanssani, ettei hän tuhoaisi sinua."'),
(1680900,58,14,35,22,'Mutta Joosia ei väistänyt häntä, vaan pukeutui tuntemattomaksi taistellakseen häntä vastaan, eikä kuullut Nekon sanoja, jotka kuitenkin tulivat Jumalan suusta. Niin hän meni taistelemaan Megiddon tasangolle.'),
(1680901,58,14,35,23,'Mutta ampujat ampuivat kuningas Joosiaa; ja kuningas sanoi palvelijoillensa: "Viekää minut pois, sillä minä olen pahasti haavoittunut".'),
(1680902,58,14,35,24,'Niin hänen palvelijansa siirsivät hänet sotavaunuista ja panivat hänet hänen toisiin vaunuihinsa ja kuljettivat hänet Jerusalemiin. Ja hän kuoli, ja hänet haudattiin isiensä hautoihin. Ja koko Juuda ja Jerusalem surivat Joosiaa.'),
(1680903,58,14,35,25,'Ja Jeremia sepitti itkuvirren Joosiasta. Ja kaikki laulajat ja laulajattaret ovat itkuvirsissään puhuneet Joosiasta aina tähän päivään asti; ja nämä ovat tulleet yleisiksi Israelissa. Katso, ne ovat kirjoitettuina "Itkuvirsissä".'),
(1680904,58,14,35,26,'Mitä muuta on kerrottavaa Joosiasta ja hänen hurskaista teoistansa, joita hän teki sen mukaan, kuin on kirjoitettuna Herran laissa,'),
(1680905,58,14,35,27,'hänen sekä aikaisemmista että myöhemmistä vaiheistaan, katso, se on kirjoitettuna Israelin ja Juudan kuningasten kirjassa.'),
(1680906,58,14,36,1,'Maan kansa otti Joosian pojan Jooahaan ja teki hänet kuninkaaksi Jerusalemiin hänen isänsä jälkeen.'),
(1680907,58,14,36,2,'Jooahas oli kahdenkymmenen kolmen vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kolme kuukautta.'),
(1680908,58,14,36,3,'Mutta Egyptin kuningas pani hänet viralta Jerusalemissa ja otti maasta pakkoverona sata talenttia hopeata ja yhden talentin kultaa.'),
(1680909,58,14,36,4,'Ja Egyptin kuningas teki hänen veljensä Eljakimin Juudan ja Jerusalemin kuninkaaksi ja muutti hänen nimensä Joojakimiksi. Mutta hänen veljensä Jooahaan Neko otti ja vei Egyptiin.'),
(1680910,58,14,36,5,'Joojakim oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa yksitoista vuotta. Hän teki sitä, mikä oli pahaa Herran, hänen Jumalansa, silmissä.'),
(1680911,58,14,36,6,'Ja Nebukadnessar, Baabelin kuningas, lähti häntä vastaan ja kytki hänet vaskikahleisiin viedäkseen hänet Baabeliin.'),
(1680912,58,14,36,7,'Nebukadnessar vei Herran temppelin kaluja Baabeliin ja pani ne temppeliinsä Baabelissa.'),
(1680913,58,14,36,8,'Mitä muuta on kerrottavaa Joojakimista ja niistä kauhistuksista, joita hän teki, ja mitä hänessä havaittiin, katso, se on kirjoitettuna Israelin ja Juudan kuningasten kirjassa. Ja hänen poikansa Joojakin tuli kuninkaaksi hänen sijaansa.'),
(1680914,58,14,36,9,'Joojakin oli kahdeksantoista vuoden vanha tullessansa kuninkaaksi, ja hän hallitsi Jerusalemissa kolme kuukautta ja kymmenen päivää. Hän teki sitä, mikä on pahaa Herran silmissä.'),
(1680915,58,14,36,10,'Vuoden vaihteessa kuningas Nebukadnessar lähetti noutamaan hänet Baabeliin, hänet ynnä Herran temppelin kallisarvoiset kalut. Ja hän teki hänen veljensä Sidkian Juudan ja Jerusalemin kuninkaaksi.'),
(1680916,58,14,36,11,'Sidkia oli kahdenkymmenen yhden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa yksitoista vuotta.'),
(1680917,58,14,36,12,'Hän teki sitä, mikä oli pahaa Herran, hänen Jumalansa, silmissä: hän ei nöyrtynyt profeetta Jeremian edessä, jonka sana tuli Herran suusta.'),
(1680918,58,14,36,13,'Myöskin hän kapinoi kuningas Nebukadnessaria vastaan, joka kuitenkin oli vannottanut hänet Jumalan kautta. Hän oli niskuri ja paadutti sydämensä, niin ettei hän kääntynyt Herran, Israelin Jumalan, puoleen.'),
(1680919,58,14,36,14,'Myös kaikki pappien päämiehet ja kansa harjoittivat paljon uskottomuutta jäljittelemällä pakanain kaikkia kauhistuksia, ja he saastuttivat Herran temppelin, jonka hän oli pyhittänyt Jerusalemissa.'),
(1680920,58,14,36,15,'Ja Herra, heidän isiensä Jumala, lähetti, varhaisesta alkaen, vähän väliä heille varoituksia sanansaattajainsa kautta, sillä hän sääli kansaansa ja asumustansa.'),
(1680921,58,14,36,16,'Mutta he pilkkasivat Jumalan sanansaattajia ja halveksivat hänen sanaansa ja häpäisivät hänen profeettojansa, kunnes Herran viha hänen kansaansa kohtaan oli kasvanut niin, ettei apua enää ollut.'),
(1680922,58,14,36,17,'Niin hän toi heidän kimppuunsa kaldealaisten kuninkaan ja surmautti miekalla heidän nuoret miehensä heidän pyhäkössänsä eikä säästänyt nuorukaista eikä neitosta, ei vanhusta eikä harmaapäätä; kaikki hän antoi tämän käsiin.'),
(1680923,58,14,36,18,'Ja kaikki Jumalan temppelin kalut, sekä suuret että pienet, ja Herran temppelin aarteet sekä kuninkaan ja hänen päämiestensä aarteet, kaikki hän vei Baabeliin.'),
(1680924,58,14,36,19,'Jumalan temppeli poltettiin, Jerusalemin muurit revittiin, kaikki sen palatsit poltettiin tulella, ja kaikki sen kallisarvoiset esineet hävitettiin.'),
(1680925,58,14,36,20,'Ja jotka olivat säilyneet miekalta, ne vietiin pakkosiirtolaisuuteen Baabeliin. Ja he olivat hänen ja hänen poikiensa palvelijoina, kunnes Persian valtakunta sai vallan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680926,58,14,36,21,'Ja niin toteutui Herran sana, jonka hän oli puhunut Jeremian suun kautta, kunnes maa oli saanut hyvityksen sapateistaan - niin kauan kuin se oli autiona, se lepäsi - kunnes seitsemänkymmentä vuotta oli kulunut.'),
(1680927,58,14,36,22,'Mutta Kooreksen, Persian kuninkaan, ensimmäisenä hallitusvuotena herätti Herra, että täyttyisi Herran sana, jonka hän oli puhunut Jeremian suun kautta, Kooreksen, Persian kuninkaan, hengen, niin että tämä koko valtakunnassansa kuulutti ja myös käskykirjassa julistutti näin:'),
(1680928,58,15,1,1,'Kooreksen, Persian kuninkaan, ensimmäisenä hallitusvuotena herätti Herra, että täyttyisi Herran sana, jonka hän oli puhunut Jeremian suun kautta, Kooreksen, Persian kuninkaan, hengen, niin että tämä koko valtakunnassansa kuulutti ja myös käskykirjassa julistutti näin:'),
(1680929,58,15,1,2,'"Näin sanoo Koores, Persian kuningas: Kaikki maan valtakunnat on Herra, taivaan Jumala, antanut minulle, ja hän on käskenyt minun rakentaa itsellensä temppelin Jerusalemiin, joka on Juudassa.'),
(1680930,58,15,1,3,'Kuka vain teidän joukossanne on hänen kansaansa, sen kanssa olkoon hänen Jumalansa, ja hän menköön Jerusalemiin, joka on Juudassa, rakentamaan Herran, Israelin Jumalan, temppeliä. Hän on se Jumala, joka asuu Jerusalemissa.'),
(1680931,58,15,1,4,'Kuka vain on jäljellä, se saakoon, missä asuukin muukalaisena, paikkakuntansa miehiltä kannatukseksi hopeata ja kultaa, tavaraa ja karjaa ynnä vapaaehtoisia lahjoja Jumalan temppelin rakentamiseksi Jerusalemiin."'),
(1680932,58,15,1,5,'Silloin nousivat Juudan ja Benjaminin perhekunta-päämiehet sekä papit ja leeviläiset, kaikki, joiden hengen Jumala herätti menemään ja rakentamaan Herran temppeliä Jerusalemiin.'),
(1680933,58,15,1,6,'Ja kaikki, jotka asuivat heidän ympärillään, avustivat heitä hopeakaluilla, kullalla, tavaralla, karjalla ja kalleuksilla kaiken sen lisäksi, mitä annettiin vapaaehtoisina lahjoina.'),
(1680934,58,15,1,7,'Ja kuningas Koores tuotatti esiin Herran temppelin kalut, jotka Nebukadnessar oli vienyt pois Jerusalemista ja pannut oman jumalansa temppeliin.'),
(1680935,58,15,1,8,'Ne Koores, Persian kuningas, tuotatti aarteistonvartijalle, Mitredatille, ja tämä laski niiden luvun Sesbassarille, Juudan ruhtinaalle.'),
(1680936,58,15,1,9,'Ja tämä oli niiden luku: kolmekymmentä kultamaljaa, tuhat hopeamaljaa, kaksikymmentä yhdeksän uhriastiaa,'),
(1680937,58,15,1,10,'kolmekymmentä kultapikaria, niitä arvolta lähinnä neljäsataa kymmenen hopeapikaria, tuhat muuta kalua.'),
(1680938,58,15,1,11,'Kulta- ja hopeakaluja oli kaikkiaan viisituhatta neljäsataa. Kaikki nämä Sesbassar toi, silloin kun pakkosiirtolaiset tuotiin Baabelista Jerusalemiin.'),
(1680939,58,15,2,1,'Ja nämä olivat ne tämän maakunnan asukkaat, jotka lähtivät pakkosiirtolaisten vankeudesta Baabelista, jonne Nebukadnessar, Baabelin kuningas, oli vienyt heidät pakkosiirtolaisuuteen, ja jotka palasivat Jerusalemiin ja Juudaan, kukin kaupunkiinsa,'),
(1680940,58,15,2,2,'ne, jotka tulivat Serubbaabelin, Jeesuan, Nehemian, Serajan, Reelajan, Mordekain, Bilsanin, Misparin, Bigvain, Rehumin ja Baanan kanssa. Israelin kansan miesten lukumäärä oli:'),
(1680941,58,15,2,3,'Paroksen jälkeläisiä kaksituhatta sata seitsemänkymmentä kaksi;'),
(1680942,58,15,2,4,'Sefatjan jälkeläisiä kolmesataa seitsemänkymmentä kaksi;'),
(1680943,58,15,2,5,'Aarahin jälkeläisiä seitsemänsataa seitsemänkymmentä viisi;'),
(1680944,58,15,2,6,'Pahat-Mooabin jälkeläisiä, nimittäin Jeesuan ja Jooabin jälkeläisiä, kaksituhatta kahdeksansataa kaksitoista;'),
(1680945,58,15,2,7,'Eelamin jälkeläisiä tuhat kaksisataa viisikymmentä neljä;'),
(1680946,58,15,2,8,'Sattun jälkeläisiä yhdeksänsataa neljäkymmentä viisi;'),
(1680947,58,15,2,9,'Sakkain jälkeläisiä seitsemänsataa kuusikymmentä;'),
(1680948,58,15,2,10,'Baanin jälkeläisiä kuusisataa neljäkymmentä kaksi;'),
(1680949,58,15,2,11,'Beebain jälkeläisiä kuusisataa kaksikymmentä kolme;'),
(1680950,58,15,2,12,'Asgadin jälkeläisiä tuhat kaksisataa kaksikymmentä kaksi;'),
(1680951,58,15,2,13,'Adonikamin jälkeläisiä kuusisataa kuusikymmentä kuusi;'),
(1680952,58,15,2,14,'Bigvain jälkeläisiä kaksituhatta viisikymmentä kuusi;'),
(1680953,58,15,2,15,'Aadinin jälkeläisiä neljäsataa viisikymmentä neljä;'),
(1680954,58,15,2,16,'Aaterin, nimittäin Hiskian, jälkeläisiä yhdeksänkymmentä kahdeksan;'),
(1680955,58,15,2,17,'Beesain jälkeläisiä kolmesataa kaksikymmentä kolme;'),
(1680956,58,15,2,18,'Jooran jälkeläisiä sata kaksitoista;'),
(1680957,58,15,2,19,'Haasumin jälkeläisiä kaksisataa kaksikymmentä kolme;'),
(1680958,58,15,2,20,'Gibbarin jälkeläisiä yhdeksänkymmentä viisi;'),
(1680959,58,15,2,21,'beetlehemiläisiä sata kaksikymmentä kolme;'),
(1680960,58,15,2,22,'Netofan miehiä viisikymmentä kuusi;'),
(1680961,58,15,2,23,'Anatotin miehiä sata kaksikymmentä kahdeksan;'),
(1680962,58,15,2,24,'asmavetilaisia neljäkymmentä kaksi;'),
(1680963,58,15,2,25,'kirjat-aarimilaisia, kefiralaisia ja beerotilaisia seitsemänsataa neljäkymmentä kolme;'),
(1680964,58,15,2,26,'raamalaisia ja gebalaisia kuusisataa kaksikymmentä yksi;'),
(1680965,58,15,2,27,'Mikmaan miehiä sata kaksikymmentä kaksi;'),
(1680966,58,15,2,28,'Beetelin ja Ain miehiä kaksisataa kaksikymmentä kolme;'),
(1680967,58,15,2,29,'nebolaisia viisikymmentä kaksi;'),
(1680968,58,15,2,30,'Magbiin jälkeläisiä sata viisikymmentä kuusi;'),
(1680969,58,15,2,31,'toisen Eelamin jälkeläisiä tuhat kaksisataa viisikymmentä neljä;'),
(1680970,58,15,2,32,'Haarimin jälkeläisiä kolmesataa kaksikymmentä;'),
(1680971,58,15,2,33,'loodilaisia, haadidilaisia ja oonolaisia seitsemänsataa kaksikymmentä viisi;'),
(1680972,58,15,2,34,'jerikolaisia kolmesataa neljäkymmentä viisi;'),
(1680973,58,15,2,35,'senaalaisia kolmetuhatta kuusisataa kolmekymmentä.'),
(1680974,58,15,2,36,'Pappeja oli: Jedajan jälkeläisiä, nimittäin Jeesuan sukua, yhdeksänsataa seitsemänkymmentä kolme;'),
(1680975,58,15,2,37,'Immerin jälkeläisiä tuhat viisikymmentä kaksi;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1680976,58,15,2,38,'Pashurin jälkeläisiä tuhat kaksisataa neljäkymmentä seitsemän;'),
(1680977,58,15,2,39,'Haarimin jälkeläisiä tuhat seitsemäntoista.'),
(1680978,58,15,2,40,'Leeviläisiä oli: Jeesuan ja Kadmielin jälkeläisiä, nimittäin Hoodavjan jälkeläisiä, seitsemänkymmentä neljä.'),
(1680979,58,15,2,41,'Veisaajia oli: Aasafin jälkeläisiä sata kaksikymmentä kahdeksan.'),
(1680980,58,15,2,42,'Ovenvartijain jälkeläisiä oli: Sallumin jälkeläisiä, Aaterin jälkeläisiä, Talmonin jälkeläisiä, Akkubin jälkeläisiä, Hatitan jälkeläisiä, Soobain jälkeläisiä, kaikkiaan sata kolmekymmentä yhdeksän.'),
(1680981,58,15,2,43,'Temppelipalvelijoita oli: Siihan jälkeläiset, Hasufan jälkeläiset, Tabbaotin jälkeläiset,'),
(1680982,58,15,2,44,'Keeroksen jälkeläiset, Siiahan jälkeläiset, Paadonin jälkeläiset,'),
(1680983,58,15,2,45,'Lebanan jälkeläiset, Hagaban jälkeläiset, Akkubin jälkeläiset,'),
(1680984,58,15,2,46,'Haagabin jälkeläiset, Samlain jälkeläiset, Haananin jälkeläiset,'),
(1680985,58,15,2,47,'Giddelin jälkeläiset, Gaharin jälkeläiset, Reajan jälkeläiset,'),
(1680986,58,15,2,48,'Resinin jälkeläiset, Nekodan jälkeläiset, Gassamin jälkeläiset,'),
(1680987,58,15,2,49,'Ussan jälkeläiset, Paaseahin jälkeläiset, Beesain jälkeläiset,'),
(1680988,58,15,2,50,'Asnan jälkeläiset, Meunimin jälkeläiset, Nefusimin jälkeläiset,'),
(1680989,58,15,2,51,'Bakbukin jälkeläiset, Hakufan jälkeläiset, Harhurin jälkeläiset,'),
(1680990,58,15,2,52,'Baslutin jälkeläiset, Mehidan jälkeläiset, Harsan jälkeläiset,'),
(1680991,58,15,2,53,'Barkoksen jälkeläiset, Siiseran jälkeläiset, Taamahin jälkeläiset,'),
(1680992,58,15,2,54,'Nesiahin jälkeläiset, Hatifan jälkeläiset.'),
(1680993,58,15,2,55,'Salomon palvelijain jälkeläisiä oli: Sootain jälkeläiset, Sooferetin jälkeläiset, Perudan jälkeläiset,'),
(1680994,58,15,2,56,'Jaalan jälkeläiset, Darkonin jälkeläiset, Giddelin jälkeläiset,'),
(1680995,58,15,2,57,'Sefatjan jälkeläiset, Hattilin jälkeläiset, Pookeret-Sebaimin jälkeläiset, Aamin jälkeläiset.'),
(1680996,58,15,2,58,'Temppelipalvelijoita ja Salomon palvelijain jälkeläisiä oli kaikkiaan kolmesataa yhdeksänkymmentä kaksi.'),
(1680997,58,15,2,59,'Nämä olivat ne, jotka lähtivät Teel-Melahista, Teel-Harsasta, Kerub-Addanista ja Immeristä, voimatta ilmoittaa perhekuntaansa ja syntyperäänsä, olivatko israelilaisia:'),
(1680998,58,15,2,60,'Delajan jälkeläisiä, Tobian jälkeläisiä, Nedokan jälkeläisiä, kuusisataa viisikymmentä kaksi.'),
(1680999,58,15,2,61,'Ja pappien poikain joukossa olivat Habaijan jälkeläiset, Koosin jälkeläiset ja Barsillain jälkeläiset, sen, joka oli ottanut vaimon gileadilaisen Barsillain tyttäristä ja jota kutsuttiin heidän nimellään.'),
(1681000,58,15,2,62,'Nämä etsivät sukuluetteloitaan, niitä löytämättä, ja niin heidät julistettiin pappeuteen kelpaamattomiksi.'),
(1681001,58,15,2,63,'Maaherra kielsi heitä syömästä korkeasti-pyhää, ennenkuin nousisi pappi, joka voi hoitaa uurimia ja tummimia.'),
(1681002,58,15,2,64,'Koko seurakunta oli yhteensä neljäkymmentä kaksi tuhatta kolmesataa kuusikymmentä,'),
(1681003,58,15,2,65,'paitsi heidän palvelijoitansa ja palvelijattariansa, joita oli seitsemäntuhatta kolmesataa kolmekymmentä seitsemän. Lisäksi oli heillä kaksisataa mies- ja naisveisaajaa.'),
(1681004,58,15,2,66,'Hevosia heillä oli seitsemänsataa kolmekymmentä kuusi, muuleja kaksisataa neljäkymmentä viisi,'),
(1681005,58,15,2,67,'kameleja neljäsataa kolmekymmentä viisi, aaseja kuusituhatta seitsemänsataa kaksikymmentä.'),
(1681006,58,15,2,68,'Perhekunta-päämiehistä muutamat, tullessansa Herran temppelin sijalle, joka on Jerusalemissa, antoivat vapaaehtoisia lahjoja Jumalan temppelille, sen pystyttämiseksi paikallensa.'),
(1681007,58,15,2,69,'He antoivat sen mukaan, kuin voivat, rakennusrahastoon: kuusikymmentä yksi tuhatta dareikkia kultaa, viisituhatta miinaa hopeata ja sata papinihokasta.'),
(1681008,58,15,2,70,'Sitten papit, leeviläiset ja osa kansaa sekä veisaajat, ovenvartijat ja temppelipalvelijat asettuivat kaupunkeihinsa, ja kaikki muut israelilaiset kaupunkeihinsa.'),
(1681009,58,15,3,1,'Kun seitsemäs kuukausi tuli ja israelilaiset jo olivat kaupungeissa, kokoontui kansa yhtenä miehenä Jerusalemiin.'),
(1681010,58,15,3,2,'Ja Jeesua, Joosadakin poika, ja hänen veljensä, papit, ja Serubbaabel, Sealtielin poika, ja hänen veljensä nousivat rakentamaan Israelin Jumalan alttaria uhrataksensa sen päällä polttouhreja, niinkuin on kirjoitettuna Jumalan miehen Mooseksen laissa.'),
(1681011,58,15,3,3,'He pystyttivät paikallensa alttarin, sillä he olivat kauhuissaan maan kansojen tähden; ja he uhrasivat alttarilla polttouhreja Herralle, polttouhreja aamuin ja illoin.'),
(1681012,58,15,3,4,'Ja he viettivät lehtimajanjuhlaa, niinkuin oli säädetty, ja uhrasivat polttouhreja joka päivä niin paljon, kuin oli säädetty, kunakin päivänä sen päivän uhrit,'),
(1681013,58,15,3,5,'ja sen jälkeen jokapäiväisen polttouhrin ja uudenkuun päivien ja kaikkien muiden Herran pyhien juhlien uhrit sekä kaikkien niiden uhrit, jotka toivat vapaaehtoisia lahjoja Herralle.'),
(1681014,58,15,3,6,'Seitsemännen kuun ensimmäisestä päivästä alkaen he uhrasivat polttouhreja Herralle, vaikka temppelin perustusta ei oltu vielä laskettu.'),
(1681015,58,15,3,7,'Ja he antoivat rahaa kivenhakkaajille ja puusepille sekä ruoka- ja juomatavaroita ja öljyä siidonilaisille ja tyyrolaisille, että nämä kuljettaisivat setripuita Libanonilta meritse Jaafoon, sen valtuuden nojalla, jonka Koores, Persian kuningas, oli heille antanut.'),
(1681016,58,15,3,8,'Ja toisena vuotena siitä, kun he olivat tulleet Jumalan temppelin sijalle Jerusalemiin, sen toisessa kuussa, ryhtyivät Serubbaabel, Sealtielin poika, ja Jeesua, Joosadakin poika, ja heidän muut veljensä, papit ja leeviläiset, ja kaikki, jotka vankeudesta olivat tulleet Jerusalemiin, työhön ja panivat kaksikymmenvuotiset ja sitä vanhemmat leeviläiset johtamaan Herran temppelin rakennustyötä.'),
(1681017,58,15,3,9,'Ja Jeesua poikineen ja veljineen ja Kadmiel poikineen, Juudan jälkeläiset, astuivat yhdessä johtamaan niitä, jotka tekivät Herran temppelin rakennustyötä; samoin myöskin Heenadadin pojat poikineen ja veljineen, leeviläiset.'),
(1681018,58,15,3,10,'Ja kun rakentajat laskivat Herran temppelin perustusta, asetettiin papit virkapuvuissaan torvilla ja leeviläiset, Aasafin jälkeläiset, kymbaaleilla ylistämään Herraa, Israelin kuninkaan Daavidin järjestelyn mukaan.'),
(1681019,58,15,3,11,'Ja he virittivät ylistys- ja kiitosvirren Herralle: "Sillä hän on hyvä sillä hänen armonsa pysyy iankaikkisesti Israelia kohtaan". Ja kaikki kansa nosti suuren riemuhuudon ylistäen Herraa siitä, että Herran temppelin perustus oli laskettu.'),
(1681020,58,15,3,12,'Mutta monet papit, leeviläiset ja perhekunta-päämiehet, vanhukset, jotka olivat nähneet edellisen temppelin, itkivät suurella äänellä, kun tämän temppelin perustus laskettiin heidän nähtensä. Monet taas korottivat äänensä riemuiten ja iloiten.'),
(1681021,58,15,3,13,'Eikä voitu erottaa raikuvaa riemuhuutoa kansan äänekkäästä itkusta; sillä kansa nosti suuren huudon, niin että huuto kuului kauas.'),
(1681022,58,15,4,1,'Mutta kun Juudan ja Benjaminin vastustajat kuulivat, että pakkosiirtolaiset rakensivat temppeliä Herralle, Israelin Jumalalle,'),
(1681023,58,15,4,2,'astuivat he Serubbaabelin ja perhekunta-päämiesten luo ja sanoivat heille: "Me tahdomme rakentaa yhdessä teidän kanssanne, sillä me etsimme teidän Jumalaanne, niinkuin tekin, ja hänelle me olemme uhranneet Eesarhaddonin, Assurin kuninkaan, päivistä asti, hänen, joka toi meidät tänne".'),
(1681024,58,15,4,3,'Mutta Serubbaabel ja Jeesua ja muut Israelin perhekunta-päämiehet sanoivat heille: "Ei sovi teidän ja meidän yhdessä rakentaa temppeliä meidän Jumalallemme, vaan me yksin rakennamme Herralle, Israelin Jumalalle, niinkuin kuningas Koores, Persian kuningas, on meitä käskenyt".'),
(1681025,58,15,4,4,'Mutta maan kansa sai Juudan kansan kädet herpoamaan ja pelotti heidät rakentamasta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681026,58,15,4,5,'Ja ne palkkasivat heitä vastaan neuvonantajia, jotka tekivät heidän hankkeensa tyhjäksi, niin kauan kuin Koores, Persian kuningas, eli, ja aina Daarejaveksen, Persian kuninkaan, hallitusaikaan asti.'),
(1681027,58,15,4,6,'Ahasveroksen hallituksen aikana, hänen hallituksensa alussa, he kirjoittivat syytöskirjan Juudan ja Jerusalemin asukkaita vastaan.'),
(1681028,58,15,4,7,'Ja Artahsastan aikana kirjoittivat Bislam, Mitredat ja Taabeel ynnä näiden muut virkatoverit Artahsastalle, Persian kuninkaalle. Kirje oli kirjoitettu aramin kirjoituksella ja käännetty araminkielelle.'),
(1681029,58,15,4,8,'Käskynhaltija Rehum ja kirjuri Simsai kirjoittivat kuningas Artahsastalle Jerusalemia vastaan kirjeen, joka kuului näin:'),
(1681030,58,15,4,9,'Silloin ja silloin. "Käskynhaltija Rehum ja kirjuri Simsai ynnä muut heidän virkatoverinsa, tuomarit, järjestysmiehet, tarpelilaiset, afarsilaiset, erekiläiset, babylonialaiset, suusanilaiset, dehavilaiset, eelamilaiset,'),
(1681031,58,15,4,10,'ja muut kansat, jotka suuri ja mainehikas Aasenappar vei pakkosiirtolaisuuteen ja sijoitti Samarian kaupunkiin ja muualle, tälle puolelle Eufrat-virran," ja niin edespäin.'),
(1681032,58,15,4,11,'Tämä on jäljennös kirjeestä, jonka he lähettivät hänelle: "Kuningas Artahsastalle sinun palvelijasi, miehet tältä puolelta Eufrat-virran," ja niin edespäin.'),
(1681033,58,15,4,12,'"Tietäköön kuningas, että ne juutalaiset, jotka lähtivät sinun luotasi meidän luoksemme, ovat tulleet Jerusalemiin. He ovat nyt rakentamassa tuota kapinallista ja pahaa kaupunkia ja panemassa kuntoon muureja ja korjaamassa perustuksia.'),
(1681034,58,15,4,13,'Niin tietäköön kuningas, että jos se kaupunki rakennetaan ja muurit pannaan kuntoon, he eivät suorita rahaveroa, eivät luonnontuotteita eivätkä tierahaa, ja siitä kärsivät kuningasten tulot.'),
(1681035,58,15,4,14,'Koska kerran me syömme palatsin suolaa eikä meidän sovi nähdä kuninkaan häpäisemistä, sentähden me lähetämme ja ilmoitamme tämän kuninkaalle,'),
(1681036,58,15,4,15,'että hän tutkituttaisi sinun isiesi aikakirjaa; sillä aikakirjasta sinä huomaat ja saat tietää, että se kaupunki on ollut kapinallinen kaupunki, joka on tuottanut kuninkaille ja maakunnille vahinkoa ja jossa ammoisista ajoista on pantu toimeen levottomuuksia. Sentähden se kaupunki on hävitetty.'),
(1681037,58,15,4,16,'Me ilmoitamme siis kuninkaalle, että jos se kaupunki rakennetaan ja muurit pannaan kuntoon, ei sinulla ole oleva mitään osaa tällä puolella Eufrat-virran olevaan maahan."'),
(1681038,58,15,4,17,'Kuningas lähetti vastauksen käskynhaltija Rehumille ja kirjuri Simsaille ja muille heidän virkatovereilleen, jotka asuivat Samariassa ja muualla tällä puolella Eufrat-virran: "Rauhaa" ja niin edespäin.'),
(1681039,58,15,4,18,'"Kirjelmä, jonka meille lähetitte, on minulle tarkkaan luettu.'),
(1681040,58,15,4,19,'Minä annoin käskyn tutkia asiaa, ja huomattiin, että se kaupunki ammoisista ajoista asti on noussut kuninkaita vastaan ja että siellä on pantu toimeen kapinoita ja levottomuuksia.'),
(1681041,58,15,4,20,'Jerusalemissa on ollut mahtavia kuninkaita, jotka ovat hallinneet kaikkea Eufrat-virran senpuoleista maata ja joille on suoritettu rahaveroa, luonnontuotteita ja tierahaa.'),
(1681042,58,15,4,21,'Antakaa siis käsky, että ne miehet on estettävä työstään ja että se kaupunki on jätettävä rakentamatta, kunnes minulta tulee käsky.'),
(1681043,58,15,4,22,'Ja varokaa, ettette lyö laimin mitään tässä asiassa, etteivät kuninkaat kärsisi siitä suurta vahinkoa."'),
(1681044,58,15,4,23,'Niin pian kuin kuningas Artahsastan kirjelmän jäljennös oli luettu Rehumille, kirjuri Simsaille ja heidän virkatovereilleen, menivät he kiiruusti Jerusalemiin juutalaisten luo ja estivät väkivoimalla heidät työtä tekemästä.'),
(1681045,58,15,4,24,'Silloin pysähtyi Jumalan temppelin rakennustyö Jerusalemissa ja oli pysähdyksissä Daarejaveksen, Persian kuninkaan, toiseen hallitusvuoteen asti.'),
(1681046,58,15,5,1,'Mutta profeetta Haggai ja Sakarja, Iddon poika, profeetat, ennustivat Juudassa ja Jerusalemissa oleville juutalaisille Israelin Jumalan nimeen, hänen, jonka nimiin he olivat otetut.'),
(1681047,58,15,5,2,'Niin Serubbaabel, Sealtielin poika, ja Jeesua, Joosadakin poika, nousivat ja alkoivat rakentaa Jumalan temppeliä Jerusalemissa, ja heidän kanssansa Jumalan profeetat, jotka tukivat heitä.'),
(1681048,58,15,5,3,'Siihen aikaan tulivat heidän luoksensa Tattenai, Eufrat-virran tämänpuoleisen maan käskynhaltija, ja Setar-Boosenai sekä heidän virkatoverinsa ja sanoivat heille näin: "Kuka on käskenyt teitä rakentamaan tätä temppeliä ja panemaan kuntoon tätä muuria?"'),
(1681049,58,15,5,4,'Niin me sanoimme heille niiden miesten nimet, jotka tätä rakennusta rakensivat.'),
(1681050,58,15,5,5,'Ja juutalaisten vanhinten yllä oli heidän Jumalansa silmä, niin ettei heitä estetty työstä, vaan meni kertomus asiasta Daarejavekselle ja odotettiin sitä koskevan kirjoituksen tuloa sieltä takaisin.'),
(1681051,58,15,5,6,'Jäljennös kirjeestä, jonka Tattenai, Eufrat-virran tämänpuoleisen maan käskynhaltija, ja Setar-Boosenai sekä tämän virkatoverit, ne afarsakilaiset, jotka olivat tällä puolella Eufrat-virran, lähettivät kuningas Daarejavekselle;'),
(1681052,58,15,5,7,'he näet lähettivät hänelle kertomuksen, ja siihen oli kirjoitettu näin: "Kuningas Daarejavekselle kaikkea rauhaa!'),
(1681053,58,15,5,8,'Tietäköön kuningas, että me menimme Juudan maakuntaan, suuren Jumalan temppelille. Sitä rakennetaan suurista kivistä, ja hirsiä pannaan seiniin. Työ tehdään tarkasti ja sujuu heidän käsissään.'),
(1681054,58,15,5,9,'Sitten me kysyimme vanhimmilta ja sanoimme heille näin: ''Kuka on käskenyt teitä rakentamaan tätä temppeliä ja panemaan kuntoon tätä muuria?'''),
(1681055,58,15,5,10,'Me kysyimme heiltä myöskin heidän nimiänsä ilmoittaaksemme ne sinulle ja kirjoitimme muistiin niiden miesten nimet, jotka ovat heitä johtamassa.'),
(1681056,58,15,5,11,'Ja he antoivat meille tämän vastauksen: ''Me olemme taivaan ja maan Jumalan palvelijoita, ja me rakennamme uudestaan temppeliä, joka oli rakennettu monta vuotta sitten. Suuri Israelin kuningas sen rakensi ja sai sen valmiiksi.'),
(1681057,58,15,5,12,'Mutta koska meidän isämme vihoittivat taivaan Jumalan, antoi hän heidät kaldealaisen Nebukadnessarin, Baabelin kuninkaan, käsiin; ja hän hävitti tämän temppelin ja vei kansan pakkosiirtolaisuuteen Baabeliin.'),
(1681058,58,15,5,13,'Mutta Kooreksen, Baabelin kuninkaan, ensimmäisenä hallitusvuotena antoi kuningas Koores käskyn rakentaa uudestaan tämän Jumalan temppelin.'),
(1681059,58,15,5,14,'Kuningas Koores antoi myös tuoda Baabelin temppelistä esiin Jumalan temppelin kulta- ja hopeakalut, jotka Nebukadnessar oli vienyt pois Jerusalemin temppelistä ja tuonut Baabelin temppeliin; ja ne annettiin Sesbassar-nimiselle miehelle, jonka hän oli asettanut käskynhaltijaksi.'),
(1681060,58,15,5,15,'Ja hän sanoi tälle: Ota nämä kalut, mene ja pane ne Jerusalemin temppeliin. Ja Jumalan temppeli rakennettakoon entiselle paikallensa.'),
(1681061,58,15,5,16,'Niin tämä Sesbassar tuli ja laski Jumalan temppelin perustuksen Jerusalemissa. Ja siitä ajasta alkaen tähän saakka sitä on rakennettu, eikä se vieläkään ole valmis.'''),
(1681062,58,15,5,17,'Jos kuningas siis hyväksi näkee, niin tutkittakoon kuninkaan aarrekammiossa siellä Baabelissa, onko niin, että kuningas Koores on antanut käskyn rakentaa tämän Jumalan temppelin Jerusalemissa; ja lähettänee kuningas meille tiedon tahdostansa tässä asiassa."'),
(1681063,58,15,6,1,'Niin kuningas Daarejaves antoi käskyn, että asiaa tutkittaisiin Baabelin arkistossa, jonne myös aarteet koottiin.'),
(1681064,58,15,6,2,'Ja Ahmetan linnasta, Meedian maakunnasta, löydettiin kirjakäärö, johon oli kirjoitettu seuraavasti: "Muistettava tapahtuma:'),
(1681065,58,15,6,3,'Kuningas Kooreksen ensimmäisenä hallitusvuotena kuningas Koores antoi käskyn: Jumalan temppeli Jerusalemissa, se temppeli rakennettakoon paikaksi, jossa uhreja uhrataan. Sen perustukset laskettakoon lujiksi, sen korkeus olkoon kuusikymmentä kyynärää ja leveys kuusikymmentä kyynärää.'),
(1681066,58,15,6,4,'Siinä olkoon aina rinnakkain kolme kivikertaa suuria kiviä ja yksi hirsikerta uusia hirsiä; ja kustannukset suoritettakoon kuninkaan hovista.'),
(1681067,58,15,6,5,'Ja myös Jumalan temppelin kulta- ja hopeakalut, jotka Nebukadnessar vei pois Jerusalemin temppelistä ja toi Baabeliin, annettakoon takaisin. Ne tulkoot paikoilleen Jerusalemin temppeliin, pantakoon ne Jumalan temppeliin."'),
(1681068,58,15,6,6,'- "Niinmuodoin on sinun, Tattenai, joka olet Eufrat-virran tuonpuoleisen maan käskynhaltija, sinun, Setar-Boosenai, ja teidän virkatoverienne, niiden afarsakilaisten, jotka ovat tuolla puolella Eufrat-virran, pysyttävä siitä erillänne.'),
(1681069,58,15,6,7,'Antakaa Jumalan temppelin rakennustyön olla rauhassa. Juutalaisten käskynhaltija ja juutalaisten vanhimmat rakentakoot Jumalan temppelin paikallensa.'),
(1681070,58,15,6,8,'Ja minä annan käskyn, mitä teidän on tehtävä juutalaisten vanhimmille heidän rakentaessaan Jumalan temppeliä: tuolta puolelta Eufrat-virran tulevista kuninkaan verotuloista suoritettakoon niille miehille tarkasti ja viivyttelemättä kustannukset.'),
(1681071,58,15,6,9,'Ja mitä tarvitaan, mullikoita, oinaita ja karitsoita polttouhreiksi taivaan Jumalalle, nisuja, suolaa, viiniä ja öljyä, se annettakoon heille Jerusalemin pappien esityksestä joka päivä, laiminlyömättä,'),
(1681072,58,15,6,10,'että he uhraisivat suloisesti tuoksuvia uhreja taivaan Jumalalle ja rukoilisivat kuninkaan ja hänen poikiensa hengen puolesta.'),
(1681073,58,15,6,11,'Ja minä annan käskyn, että kuka ikinä rikkoo tämän määräyksen, hänen talostaan revittäköön hirsi, ja hänet ripustettakoon ja naulittakoon siihen, ja hänen talostaan tehtäköön siitä syystä soraläjä.'),
(1681074,58,15,6,12,'Ja Jumala, joka on asettanut nimensä siihen, kukistakoon jokaisen kuninkaan ja kansan, joka ojentaa kätensä rikkomaan tätä määräystä hävittämällä Jumalan temppelin Jerusalemissa. Minä Daarejaves olen antanut tämän käskyn; se tarkoin täytettäköön."'),
(1681075,58,15,6,13,'Silloin Tattenai, Eufrat-virran tämänpuoleisen maan käskynhaltija, Setar-Boosenai ja heidän virkatoverinsa täyttivät tarkoin käskyn, jonka kuningas Daarejaves oli heille lähettänyt.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681076,58,15,6,14,'Niin juutalaisten vanhimmat rakensivat, ja työ onnistui heille profeetta Haggain ja Sakarjan, Iddon pojan, ennustuksen tukemana. Ja he saivat sen valmiiksi Israelin Jumalan käskyn ja Kooreksen, Daarejaveksen ja Artahsastan, Persian kuninkaan, käskyn mukaan.'),
(1681077,58,15,6,15,'Tämä temppeli valmistui adar-kuun kolmanneksi päiväksi, nimittäin kuningas Daarejaveksen kuudentena hallitusvuotena.'),
(1681078,58,15,6,16,'Silloin israelilaiset, papit ja leeviläiset ja muut pakkosiirtolaiset, viettivät Jumalan temppelin vihkiäisiä iloiten'),
(1681079,58,15,6,17,'ja uhrasivat Jumalan temppelin vihkiäisissä sata härkää, kaksisataa oinasta ja neljäsataa karitsaa sekä syntiuhriksi koko Israelin puolesta kaksitoista kaurista, Israelin sukukuntien luvun mukaan.'),
(1681080,58,15,6,18,'Ja he asettivat papit ryhmittäin ja leeviläiset osastoittain Jumalan palvelukseen Jerusalemissa, niinkuin on kirjoitettuna Mooseksen kirjassa.'),
(1681081,58,15,6,19,'Sitten pakkosiirtolaiset viettivät pääsiäistä ensimmäisen kuun neljäntenätoista päivänä.'),
(1681082,58,15,6,20,'Sillä papit ja leeviläiset olivat yhtenä miehenä puhdistautuneet, niin että he kaikki olivat puhtaat. Ja he teurastivat pääsiäislampaan kaikille pakkosiirtolaisille, veljillensä papeille ja itsellensä.'),
(1681083,58,15,6,21,'Ja sitä söivät kaikki pakkosiirtolaisuudesta palanneet israelilaiset sekä kaikki, jotka olivat eristäytyneet maassa asuvien pakanain saastaisuudesta ja liittyneet heihin etsiäkseen Herraa, Israelin Jumalaa.'),
(1681084,58,15,6,22,'Ja he viettivät happamattoman leivän juhlaa seitsemän päivää iloiten, sillä Herra oli ilahuttanut heitä, kun oli kääntänyt Assurin kuninkaan sydämen heidän puolellensa, niin että hän avusti heitä Jumalan, Israelin Jumalan, temppelin rakentamistyössä.'),
(1681085,58,15,7,1,'Näiden tapausten jälkeen, Persian kuninkaan Artahsastan hallituksen aikana, lähti Esra, Serajan poika, joka oli Asarjan poika, joka Hilkian poika,'),
(1681086,58,15,7,2,'joka Sallumin poika, joka Saadokin poika, joka Ahitubin poika,'),
(1681087,58,15,7,3,'joka Amarjan poika, joka Asarjan poika, joka Merajotin poika,'),
(1681088,58,15,7,4,'joka Serahjan poika, joka Ussin poika, joka Bukkin poika,'),
(1681089,58,15,7,5,'joka Abisuan poika, joka Piinehaan poika, joka Eleasarin poika, joka Aaronin, ylimmäisen papin, poika -'),
(1681090,58,15,7,6,'tämä Esra lähti Baabelista. Hän oli kirjanoppinut, perehtynyt Mooseksen lakiin, jonka Herra, Israelin Jumala, oli antanut. Ja kuningas antoi hänelle kaikki, mitä hän halusi, koska Esran päällä oli Herran, hänen Jumalansa, käsi.'),
(1681091,58,15,7,7,'Myös israelilaisia ja pappeja, leeviläisiä, veisaajia, ovenvartijoita ja temppelipalvelijoita lähti Jerusalemiin kuningas Artahsastan seitsemäntenä hallitusvuotena.'),
(1681092,58,15,7,8,'Ja hän tuli Jerusalemiin viidennessä kuussa kuninkaan seitsemäntenä hallitusvuotena.'),
(1681093,58,15,7,9,'Sillä ensimmäisen kuun ensimmäisenä päivänä alkoi lähtö Baabelista; ja viidennen kuun ensimmäisenä päivänä hän tuli Jerusalemiin, koska Jumalan hyvä käsi oli hänen päällänsä.'),
(1681094,58,15,7,10,'Sillä Esra oli kiinnittänyt sydämensä Herran lain tutkimiseen, seuratakseen sitä ja opettaakseen Israelissa lakia ja oikeutta.'),
(1681095,58,15,7,11,'Tämä on jäljennös kirjeestä, jonka kuningas Artahsasta antoi pappi Esralle, kirjanoppineelle, joka oli Herran Israelille antamien käskyjen ja ohjeitten tuntija:'),
(1681096,58,15,7,12,'"Artahsasta, kuningasten kuningas, pappi Esralle, taivaan Jumalan lain tuntijalle", ja niin edespäin.'),
(1681097,58,15,7,13,'"Minä annan käskyn, että minun valtakunnassani jokainen Israelin kansan jäsen ja sen papit ja leeviläiset, jotka ovat halukkaat lähtemään Jerusalemiin, lähtekööt sinun kanssasi,'),
(1681098,58,15,7,14,'koska kuningas ja hänen seitsemän neuvonantajaansa ovat lähettäneet sinut tarkastamaan, ovatko olot Juudassa ja Jerusalemissa sinun Jumalasi lain mukaiset, joka on sinun kädessäsi,'),
(1681099,58,15,7,15,'ja viemään sinne hopean ja kullan, minkä kuningas ja hänen neuvonantajansa ovat antaneet vapaaehtoisena lahjana Israelin Jumalalle, jonka asumus on Jerusalemissa,'),
(1681100,58,15,7,16,'ja myös kaiken hopean ja kullan, minkä saat koko Baabelin maakunnasta, sekä ne vapaaehtoiset lahjat, jotka kansa ja papit antavat Jumalansa temppeliin Jerusalemiin.'),
(1681101,58,15,7,17,'Osta siis näillä rahoilla mitä tunnollisimmin härkiä, oinaita ja karitsoita ynnä niihin kuuluvia ruoka- ja juomauhreja; ja uhraa ne teidän Jumalanne temppelin alttarilla Jerusalemissa.'),
(1681102,58,15,7,18,'Ja mitä sinä ja sinun veljesi näette hyväksi tehdä hopean ja kullan tähteillä, se tehkää Jumalanne tahdon mukaan.'),
(1681103,58,15,7,19,'Ne kalut, jotka sinulle annetaan jumalanpalvelusta varten sinun Jumalasi temppelissä, jätä Jerusalemin Jumalan eteen.'),
(1681104,58,15,7,20,'Ja muut Jumalasi temppelin tarpeet, joita joudut suorittamaan, sinä saat suorittaa kuninkaan aarrekammiosta.'),
(1681105,58,15,7,21,'Ja minä, kuningas Artahsasta, annan käskyn kaikille aarteistojen vartijoille tuolla puolella Eufrat-virran: ''Kaikki, mitä pappi Esra, taivaan Jumalan lain tuntija, teiltä pyytää, se tunnollisesti toimitettakoon:'),
(1681106,58,15,7,22,'hopeata aina sataan talenttiin, nisuja sataan koor-mittaan, viiniä sataan bat-mittaan, öljyä sataan bat-mittaan saakka, niin myös suoloja ilman määrää.'),
(1681107,58,15,7,23,'Kaikki, mitä taivaan Jumala käskee, tehtäköön taivaan Jumalan temppelille täsmällisesti, ettei viha kohtaisi kuninkaan ja hänen poikiensa valtakuntaa.'),
(1681108,58,15,7,24,'Vielä tehdään teille tiettäväksi, ettei kukaan ole oikeutettu vaatimaan rahaveroa, luonnontuotteita tai tierahoja yhdeltäkään papilta tai leeviläiseltä, veisaajalta, ovenvartijalta, temppelipalvelijalta tai muulta tämän Jumalan temppelin tehtäviä toimittavalta.'''),
(1681109,58,15,7,25,'Ja sinä, Esra, aseta Jumalasi viisauden mukaan, joka on sinun kädessäsi, tuomareita ja lakimiehiä tuomitsemaan kaikkea kansaa tuolla puolella Eufrat-virran, kaikkia, jotka tuntevat sinun Jumalasi lain; ja niille, jotka eivät sitä tunne, opettakaa sitä.'),
(1681110,58,15,7,26,'Ja jokainen, joka ei seuraa sinun Jumalasi lakia ja kuninkaan lakia, tuomittakoon tarkoin harkiten joko kuolemaan tai karkoitukseen, rahasakkoon tai vankeuteen."'),
(1681111,58,15,7,27,'Kiitetty olkoon Herra, meidän isiemme Jumala, joka on pannut kuninkaan sydämeen, että hänen on kaunistettava Herran temppeliä Jerusalemissa'),
(1681112,58,15,7,28,'ja joka on suonut minun saavuttaa kuninkaan, hänen neuvonantajainsa ja kaikkien kuninkaan mahtavain ruhtinasten suosion. Ja minä rohkaisin mieleni, koska Herran, minun Jumalani, käsi oli minun päälläni, ja minä kokosin Israelista päämiehiä lähtemään kanssani.'),
(1681113,58,15,8,1,'Nämä olivat ne heidän perhekunta-päämiehensä ja heidän sukuluetteloihinsa merkityt, jotka kuningas Artahsastan hallituksen aikana lähtivät minun kanssani Baabelista:'),
(1681114,58,15,8,2,'Piinehaan jälkeläisiä Geersom; Iitamarin jälkeläisiä Daniel; Daavidin jälkeläisiä Hattus;'),
(1681115,58,15,8,3,'Sekanjan jälkeläisiä, Paroksen jälkeläisiä, Sakarja ja hänen kanssaan sata viisikymmentä sukuluetteloihin merkittyä miestä;'),
(1681116,58,15,8,4,'Pahat-Mooabin jälkeläisiä Eljoenai, Serahjan poika, ja hänen kanssaan kaksisataa miestä;'),
(1681117,58,15,8,5,'Sekanjan jälkeläisiä Jahasielin poika ja hänen kanssaan kolmesataa miestä;'),
(1681118,58,15,8,6,'Aadinin jälkeläisiä Ebed, Joonatanin poika, ja hänen kanssaan viisikymmentä miestä;'),
(1681119,58,15,8,7,'Eelamin jälkeläisiä Jesaja, Ataljan poika, ja hänen kanssaan seitsemänkymmentä miestä;'),
(1681120,58,15,8,8,'Sefatjan jälkeläisiä Sebadja, Miikaelin poika, ja hänen kanssaan kahdeksankymmentä miestä;'),
(1681121,58,15,8,9,'Jooabin jälkeläisiä Obadja, Jehielin poika, ja hänen kanssaan kaksisataa kahdeksantoista miestä;'),
(1681122,58,15,8,10,'Selomitin jälkeläisiä Joosifjan poika ja hänen kanssaan sata kuusikymmentä miestä;'),
(1681123,58,15,8,11,'Beebain jälkeläisiä Sakarja, Beebain poika, ja hänen kanssaan kaksikymmentä kahdeksan miestä;'),
(1681124,58,15,8,12,'Asgadin jälkeläisiä Joohanan, Hakkatanin poika, ja hänen kanssaan sata kymmenen miestä;'),
(1681125,58,15,8,13,'Adonikamin jälkeläisiä myöhemmin tulleet, joiden nimet olivat Elifelet, Jeguel ja Semaja, ja heidän kanssaan kuusikymmentä miestä;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681126,58,15,8,14,'Bigvain jälkeläisiä Uutai ja Sabbud ja heidän kanssaan seitsemänkymmentä miestä.'),
(1681127,58,15,8,15,'Ja minä kokosin heidät joelle, joka juoksee Ahavaan päin, ja me olimme siellä leiriytyneinä kolme päivää. Mutta kun minä tarkkasin kansaa ja pappeja, en löytänyt sieltä yhtään leeviläistä.'),
(1681128,58,15,8,16,'Silloin minä lähetin päämiehet Elieserin, Arielin, Semajan, Elnatanin, Jaaribin, Elnatanin, Naatanin, Sakarjan ja Mesullamin sekä opettajat Joojaribin ja Elnatanin'),
(1681129,58,15,8,17,'ja käskin heidän mennä päämies Iddon luo Kaasifjan paikkakunnalle; ja minä panin heidän suuhunsa sanat, jotka heidän oli puhuttava veljilleen Iddolle ja temppelipalvelijoille, Kaasifjan paikkakunnalla, että he toisivat meille palvelijoita meidän Jumalamme temppeliä varten.'),
(1681130,58,15,8,18,'Ja koska meidän Jumalamme hyvä käsi oli meidän päällämme, toivat he meille ymmärtäväisen miehen, joka oli Mahlin, Leevin pojan ja Israelin pojan pojan, jälkeläisiä, ja Seerebjan poikineen ja veljineen, kahdeksantoista miestä,'),
(1681131,58,15,8,19,'ja Hasabjan ja hänen kanssaan Jesajan, joka oli Merarin jälkeläisiä, veljineen ja poikineen, kaksikymmentä,'),
(1681132,58,15,8,20,'niin myös temppelipalvelijoista, jotka Daavid ja päämiehet olivat antaneet leeviläisille palvelemaan heitä, kaksisataa kaksikymmentä temppelipalvelijaa, kaikki nimeltä mainittuja.'),
(1681133,58,15,8,21,'Minä kuulutin siellä Ahava-joella paaston, että me nöyrtyisimme Jumalamme edessä ja anoisimme häneltä suotuisaa matkaa itsellemme, vaimoillemme ja lapsillemme ja kaikelle omaisuudellemme.'),
(1681134,58,15,8,22,'Sillä minua hävetti pyytää kuninkaalta sotaväkeä ja ratsumiehiä auttamaan meitä vihollisia vastaan matkalla, koska me olimme sanoneet kuninkaalle näin: "Meidän Jumalamme käsi on kaikkien päällä, jotka etsivät häntä, heidän parhaakseen; mutta hänen voimansa ja vihansa on kaikkia vastaan, jotka hylkäävät hänet".'),
(1681135,58,15,8,23,'Niin me paastosimme ja anoimme tätä Jumalaltamme, ja hän kuuli meidän rukouksemme.'),
(1681136,58,15,8,24,'Ja minä valitsin pappien päämiehistä kaksitoista, nimittäin Seerebjan ja Hasabjan ja heidän kanssaan kymmenen heidän veljistään,'),
(1681137,58,15,8,25,'ja punnitsin heille hopean ja kullan ja kalut, sen antimen, jonka kuningas ja hänen neuvonantajansa ja ruhtinaansa ja kaikki siellä olevat israelilaiset olivat antaneet meidän Jumalamme temppeliä varten.'),
(1681138,58,15,8,26,'Minä punnitsin heille käteen hopeata kuusisataa viisikymmentä talenttia sekä hopeakaluja sata talenttia ja kultaa sata talenttia,'),
(1681139,58,15,8,27,'kaksikymmentä kultapikaria, arvoltaan tuhat dareikkia, sekä kaksi hienoa, kullankiiltävää vaskiastiaa, kallisarvoista kuin kulta.'),
(1681140,58,15,8,28,'Ja minä sanoin heille: "Te olette pyhitetyt Herralle, ja kalut ovat pyhitetyt; ja hopea ja kulta on vapaaehtoinen lahja Herralle, teidän isienne Jumalalle.'),
(1681141,58,15,8,29,'Vartioikaa siis niitä ja säilyttäkää ne, kunnes punnitsette ne pappien päämiesten ja leeviläisten ja Israelin perhekunta-päämiesten edessä Jerusalemissa, Herran temppelin kammioissa.'),
(1681142,58,15,8,30,'Niin papit ja leeviläiset ottivat vastaan punnitun hopean ja kullan ja kalut viedäkseen ne Jerusalemiin, meidän Jumalamme temppeliin.'),
(1681143,58,15,8,31,'Sitten me lähdimme liikkeelle Ahava-joelta ensimmäisen kuun kahdentenatoista päivänä mennäksemme Jerusalemiin. Ja meidän Jumalamme käsi oli meidän päällämme, ja hän pelasti meidät vihollisten käsistä ja väijytyksistä tiellä.'),
(1681144,58,15,8,32,'Ja me tulimme Jerusalemiin ja olimme siellä alallamme kolme päivää.'),
(1681145,58,15,8,33,'Mutta neljäntenä päivänä punnittiin hopea ja kulta ja kalut meidän Jumalamme temppelissä pappi Meremotille, Uurian pojalle, käteen; ja hänen kanssaan oli Eleasar, Piinehaan poika, ja heidän kanssansa leeviläiset Joosabad, Jeesuan poika, ja Nooadja, Binnuin poika.'),
(1681146,58,15,8,34,'Kaikki punnittiin lukumäärän ja painon mukaan, ja koko paino kirjoitettiin silloin muistiin.'),
(1681147,58,15,8,35,'Ja vankeudesta tulleet pakkosiirtolaiset uhrasivat polttouhreiksi Israelin Jumalalle kaksitoista härkää koko Israelin puolesta, yhdeksänkymmentä kuusi oinasta, seitsemänkymmentä seitsemän karitsaa ja kaksitoista syntiuhrikaurista, kaikki polttouhriksi Herralle.'),
(1681148,58,15,8,36,'Ja he jättivät kuninkaan määräykset kuninkaan satraapeille ja käskynhaltijoille, jotka olivat tällä puolella Eufrat-virran, ja nämä avustivat kansaa ja Jumalan temppeliä.'),
(1681149,58,15,9,1,'Kun tämä oli suoritettu loppuun, astuivat päämiehet minun tyköni ja sanoivat: "Ei kansa, ei Israel eivätkä papit ja leeviläiset ole eristäytyneet maan kansoista ja niiden kauhistavista teoista - ei kanaanilaisista, heettiläisistä, perissiläisistä, jebusilaisista, ammonilaisista, mooabilaisista, egyptiläisistä eikä amorilaisista.'),
(1681150,58,15,9,2,'Sillä näiden tyttäriä he ovat ottaneet itsellensä ja pojillensa vaimoiksi, ja niin on pyhä siemen sekaantunut maan kansoihin. Ja päämiesten ja esimiesten käsi on ollut ensimmäisenä tässä uskottomassa menossa."'),
(1681151,58,15,9,3,'Kun minä tämän kuulin, repäisin minä vaatteeni ja viittani, revin pääni hiuksia ja partaani ja istuin tyrmistyneenä.'),
(1681152,58,15,9,4,'Ja minun luokseni kokoontuivat kaikki, jotka pelkäsivät sitä, mitä Israelin Jumala oli puhunut pakkosiirtolaisten uskottomuudesta, ja minä jäin istumaan tyrmistyneenä ehtoouhriin asti.'),
(1681153,58,15,9,5,'Mutta ehtoouhrin aikana minä nousin nöyryyttämästä itseäni ja polvistuin, repäisin vaatteeni ja viittani ja ojensin käteni Herran, Jumalani, puoleen,'),
(1681154,58,15,9,6,'ja minä sanoin: "Jumalani, minä olen häpeissäni enkä kehtaa kohottaa kasvojani sinun puoleesi, minun Jumalani; sillä meidän rikkomuksemme ovat nousseet päämme ylitse ja meidän syyllisyytemme on kohonnut taivaaseen asti.'),
(1681155,58,15,9,7,'Isiemme päivistä aina tähän päivään asti on meidän syyllisyytemme ollut suuri; ja rikkomustemme tähden on meidät, meidän kuninkaamme ja pappimme annettu maan kuningasten käsiin miekan, vankeuden, ryöstön ja häpeän alaisiksi, niinkuin tähän päivään saakka on tapahtunut.'),
(1681156,58,15,9,8,'Mutta nyt on meille hetkiseksi tullut armo Herralta, meidän Jumalaltamme, koska hän on sallinut pelastuneen joukon meistä jäädä jäljelle ja antanut meille jalansijan pyhässä paikassansa, että hän, meidän Jumalamme, valaisisi meidän silmämme ja soisi meidän hiukan hengähtää orjuudessamme.'),
(1681157,58,15,9,9,'Sillä orjia me olemme; mutta orjuudessamme ei meidän Jumalamme ole meitä hyljännyt, vaan on suonut meidän saavuttaa Persian kuningasten suosion ja hengähtää, pystyttääksemme Jumalamme temppelin ja kohottaaksemme sen raunioistaan, ja on antanut meille suojatun paikan Juudassa ja Jerusalemissa.'),
(1681158,58,15,9,10,'Ja nyt, Jumalamme, mitä me sanomme kaiken tämän jälkeen? Mehän olemme hyljänneet sinun käskysi,'),
(1681159,58,15,9,11,'jotka sinä olet antanut palvelijaisi, profeettain, kautta, sanoen: ''Maa, jota te menette ottamaan omaksenne, se maa on saastainen maan kansojen saastaisuuden tähden ja niitten kauhistavien tekojen tähden, joilla he saastaisuudessansa ovat täyttäneet sen äärestä ääreen.'),
(1681160,58,15,9,12,'Älkää siis antako tyttäriänne heidän pojillensa älkääkä ottako heidän tyttäriänsä pojillenne vaimoiksi. Älkää myös koskaan harrastako heidän menestystään ja onneansa, että te vahvistuisitte ja saisitte syödä parasta, mitä maassa on, ja jättäisitte sen perinnöksi lapsillenne ikuisiksi ajoiksi.'''),
(1681161,58,15,9,13,'Kaiken sen jälkeen, mikä on meitä kohdannut pahojen tekojemme ja suuren syyllisyytemme tähden - ja kuitenkin sinä, Jumalamme, olet jättänyt huomioon ottamatta meidän rikkomuksiamme ja olet sallinut meistä tämmöisen joukon pelastua -'),
(1681162,58,15,9,14,'kävisimmekö me nyt jälleen rikkomaan sinun käskyjäsi ja lankoutumaan kansojen kanssa, joiden teot ovat kauhistavaiset? Etkö sinä silloin vihastuisi meihin siihen asti, että tekisit meistä lopun, niin ettei ketään jäisi jäljelle eikä kukaan pelastuisi?'),
(1681163,58,15,9,15,'Herra, Israelin Jumala, sinä olet vanhurskas, sillä meistä on jäljellä pelastuneita vain sen verran, kuin tänä päivänä on. Katso, me olemme sinun edessäsi syyllisyydessämme; emmekä me tämän tähden voi sinun edessäsi kestää."'),
(1681164,58,15,10,1,'Kun Esra näin rukoili ja tunnusti, itkien ja maahan langeten, Jumalan temppelin edustalla, kokoontui hänen luoksensa sangen suuri joukko Israelin miehiä, naisia ja lapsia; sillä kansakin itki katkerasti.'),
(1681165,58,15,10,2,'Ja Sekanja, Jehielin poika, Eelamin jälkeläisiä, puhkesi puhumaan ja sanoi Esralle: "Me olemme olleet uskottomat Jumalaamme kohtaan, kun olemme ottaneet muukalaisia vaimoja maan kansoista. Mutta kuitenkin on Israelilla vielä toivoa.'),
(1681166,58,15,10,3,'Niin tehkäämme nyt Jumalamme kanssa liitto, että me Herran neuvon mukaan ja niiden neuvon mukaan, jotka pelkäävät meidän Jumalamme käskyä, toimitamme pois kaikki ne vaimot ja heistä syntyneet lapset; tehtäköön lain mukaan.'),
(1681167,58,15,10,4,'Nouse, sillä tämä on sinun asiasi, ja me olemme sinun kanssasi. Ole luja ja ryhdy toimeen."'),
(1681168,58,15,10,5,'Niin Esra nousi ja vannotti pappien päämiehet, leeviläiset ja kaiken Israelin tekemään näin. Ja he vannoivat.'),
(1681169,58,15,10,6,'Niin Esra nousi Jumalan temppelin edustalta ja meni Joohananin, Eljasibin pojan, kammioon. Sinne tultuaan hän ei syönyt leipää eikä juonut vettä, sillä niin hän suri pakkosiirtolaisten uskottomuutta.'),
(1681170,58,15,10,7,'Ja kaikille pakkosiirtolaisille kuulutettiin Juudassa ja Jerusalemissa, että heidän tuli kokoontua Jerusalemiin;'),
(1681171,58,15,10,8,'ja joka ei tullut kolmen päivän kuluessa, päämiesten ja vanhinten päätöksen mukaan, sen koko omaisuus oli vihittävä tuhon omaksi ja hän itse tuleva erotetuksi pakkosiirtolaisten seurakunnasta.'),
(1681172,58,15,10,9,'Niin kaikki Juudan ja Benjaminin miehet kokoontuivat Jerusalemiin kolmanneksi päiväksi, joka oli yhdeksännen kuun kahdeskymmenes päivä. Ja kaikki kansa asettui Jumalan temppelin aukealle, vavisten sekä asian tähden että rankkasateen vuoksi.'),
(1681173,58,15,10,10,'Ja pappi Esra nousi ja sanoi heille: "Te olette olleet uskottomat, kun olette ottaneet muukalaisia vaimoja, ja niin te olette lisänneet Israelin syyllisyyttä.'),
(1681174,58,15,10,11,'Mutta antakaa nyt Herralle, isienne Jumalalle, kunnia ja tehkää hänen tahtonsa: eristäytykää maan kansoista ja muukalaisista vaimoista."'),
(1681175,58,15,10,12,'Niin koko seurakunta vastasi ja sanoi suurella äänellä: "Niinkuin sinä olet puhunut, niin on meidän tehtävä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681176,58,15,10,13,'Mutta kansaa on paljon, ja on sadeaika, niin ettei voida seisoa ulkona. Eikä tämä ole yhden tai kahden päivän toimitus, sillä me olemme paljon siinä asiassa rikkoneet.'),
(1681177,58,15,10,14,'Käykööt meidän päämiehemme esiin koko seurakunnan puolesta, ja kaikki, jotka kaupungeissamme ovat ottaneet muukalaisia vaimoja, tulkoot tänne määrättyinä aikoina ja heidän kanssansa kunkin kaupungin vanhimmat ja tuomarit, kunnes meistä on käännetty pois Jumalan viha, joka on syttynyt tämän asian tähden."'),
(1681178,58,15,10,15,'Ainoastaan Joonatan, Asaelin poika, ja Jahseja, Tikvan poika, nousivat tätä vastustamaan, ja Mesullam ja leeviläinen Sabbetai kannattivat heitä.'),
(1681179,58,15,10,16,'Mutta pakkosiirtolaiset tekivät näin, ja valittiin pappi Esra sekä miehiä, perhekunta-päämiehiä, perhekuntien mukaan, kaikki nimeltään mainittuja. Kymmenennen kuun ensimmäisenä päivänä he istuivat tutkimaan asiaa,'),
(1681180,58,15,10,17,'ja ensimmäisen kuun ensimmäiseen päivään he olivat selvillä kaikista miehistä, jotka olivat ottaneet muukalaisia vaimoja.'),
(1681181,58,15,10,18,'Pappien poikia, jotka olivat ottaneet muukalaisia vaimoja, havaittiin olevan: Jeesuan, Joosadakin pojan, jälkeläisiä ja hänen veljiään: Maaseja, Elieser, Jaarib ja Gedalja,'),
(1681182,58,15,10,19,'jotka kättä lyöden lupasivat toimittaa pois vaimonsa ja syyllisinä uhrata oinaan syyllisyytensä sovittamiseksi;'),
(1681183,58,15,10,20,'Immerin jälkeläisiä Hanani ja Sebadja;'),
(1681184,58,15,10,21,'Haarimin jälkeläisiä Maaseja, Elia, Semaja, Jehiel ja Ussia;'),
(1681185,58,15,10,22,'Pashurin jälkeläisiä Eljoenai, Maaseja, Ismael, Netanel, Joosabad ja Elasa.'),
(1681186,58,15,10,23,'Leeviläisiä: Joosabad, Siimei, Kelaja, se on Kelita, Petahja, Juuda ja Elieser.'),
(1681187,58,15,10,24,'Veisaajia: Eljasib. Ovenvartijoita: Sallum, Telem ja Uuri.'),
(1681188,58,15,10,25,'Israelilaisia: Paroksen jälkeläisiä Ramja, Jissia, Malkia, Miijamin, Elasar, Malkia ja Benaja;'),
(1681189,58,15,10,26,'Eelamin jälkeläisiä Mattanja, Sakarja, Jehiel, Abdi, Jeremot ja Elia;'),
(1681190,58,15,10,27,'Sattun jälkeläisiä Eljoenai, Eljasib, Mattanja, Jeremot, Saabad ja Asisa;'),
(1681191,58,15,10,28,'Beebain jälkeläisiä Joohanan, Hananja, Sabbai ja Atlai;'),
(1681192,58,15,10,29,'Baanin jälkeläisiä Mesullam, Malluk, Adaja, Jaasub, Seal ja Jeramot;'),
(1681193,58,15,10,30,'Pahat-Mooabin jälkeläisiä Adna, Kelal, Benaja, Maaseja, Mattanja, Besalel, Binnui ja Manasse;'),
(1681194,58,15,10,31,'Haarimin jälkeläisiä Elieser, Jissia, Malkia, Semaja, Simeon,'),
(1681195,58,15,10,32,'Benjamin, Malluk ja Semarja;'),
(1681196,58,15,10,33,'Haasumin jälkeläisiä Mattenai, Mattatta, Saabad, Elifelet, Jeremai, Manasse ja Siimei;'),
(1681197,58,15,10,34,'Baanin jälkeläisiä Maadai, Amram, Uuel,'),
(1681198,58,15,10,35,'Benaja, Beedja, Keluhu,'),
(1681199,58,15,10,36,'Vanja, Meremot, Eljasib,'),
(1681200,58,15,10,37,'Mattanja, Mattenai, Jaasai,'),
(1681201,58,15,10,38,'Baani, Binnui, Siimei,'),
(1681202,58,15,10,39,'Selemja, Naatan, Adaja,'),
(1681203,58,15,10,40,'Maknadbai, Saasai, Saarai,'),
(1681204,58,15,10,41,'Asarel, Selemja, Semarja,'),
(1681205,58,15,10,42,'Sallum, Amarja ja Joosef;'),
(1681206,58,15,10,43,'Nebon jälkeläisiä Jegiel, Mattitja, Saabad, Sebina, Jaddai, Jooel ja Benaja.'),
(1681207,58,16,1,1,'Nehemian, Hakaljan pojan, kertomus. Kislev-kuussa, kahdentenakymmenentenä vuotena, minun ollessani Suusanin linnassa,'),
(1681208,58,16,1,2,'tuli Hanani, eräs minun veljistäni, ja muita miehiä Juudasta. Ja minä kyselin heiltä juutalaisista, siitä pelastuneesta joukosta, joka vankeudesta palanneena oli jäljellä, ja Jerusalemista.'),
(1681209,58,16,1,3,'Ja he sanoivat minulle: "Jotka vankeudesta palanneina ovat jäljellä siinä maakunnassa, ne ovat suuressa kurjuudessa ja häväistyksen alaisina; ja Jerusalemin muuri on revitty maahan, ja sen portit ovat tulella poltetut".'),
(1681210,58,16,1,4,'Tämän kuultuani minä istuin monta päivää itkien ja murehtien, ja minä paastosin ja rukoilin taivaan Jumalan edessä.'),
(1681211,58,16,1,5,'Minä sanoin: "Oi Herra, taivaan Jumala, sinä suuri ja peljättävä Jumala, joka pidät liiton ja säilytät laupeuden niille, jotka sinua rakastavat ja noudattavat sinun käskyjäsi,'),
(1681212,58,16,1,6,'olkoon sinun korvasi tarkkaavainen ja silmäsi avoin kuullaksesi palvelijasi rukoukset, joita minä nyt päivät ja yöt rukoilen sinun edessäsi palvelijaisi, israelilaisten, puolesta, tunnustaen israelilaisten synnit, jotka me olemme tehneet sinua vastaan; sillä minäkin ja minun perhekuntani olemme syntiä tehneet!'),
(1681213,58,16,1,7,'Me olemme pahoin tehneet sinua vastaan; emme ole noudattaneet käskyjä, säädöksiä ja oikeuksia, jotka sinä annoit palvelijallesi Moosekselle.'),
(1681214,58,16,1,8,'Muista sana, jonka sinä annoit palvelijallesi Moosekselle, sanoen: ''Jos te tulette uskottomiksi, niin minä hajotan teidät kansojen sekaan;'),
(1681215,58,16,1,9,'mutta jos te palajatte minun tyköni, noudatatte minun käskyjäni ja seuraatte niitä, niin vaikka teidän karkoitettunne olisivat taivaan ääressä, minä heidät sieltäkin kokoan ja tuon heidät siihen paikkaan, jonka minä olen valinnut nimeni asuinsijaksi''.'),
(1681216,58,16,1,10,'Ovathan he sinun palvelijasi ja sinun kansasi, jotka sinä vapahdit suurella voimallasi ja väkevällä kädelläsi.'),
(1681217,58,16,1,11,'Oi Herra, tarkatkoon sinun korvasi palvelijasi rukousta ja niiden palvelijaisi rukousta, jotka tahtovat peljätä sinun nimeäsi! Anna tänä päivänä palvelijasi hankkeen menestyä ja suo hänen saada armo sen miehen edessä." Minä olin näet kuninkaan juomanlaskija.'),
(1681218,58,16,2,1,'Niisan-kuussa, kuningas Artahsastan kahdentenakymmenentenä hallitusvuotena, kun viini oli hänen edessään, otin minä viinin ja annoin sen kuninkaalle. Kun minä en ollut ennen ollut hänen edessään murheellisena,'),
(1681219,58,16,2,2,'sanoi kuningas minulle: "Minkätähden sinä olet niin murheellisen näköinen? Ethän ole sairas; sinulla on varmaan jokin sydämensuru." Silloin minä peljästyin kovin,'),
(1681220,58,16,2,3,'mutta minä sanoin kuninkaalle: "Eläköön kuningas iankaikkisesti. Kuinka minä en olisi murheellisen näköinen, kun se kaupunki, jossa minun isieni haudat ovat, on autio ja sen portit tulella poltetut?"'),
(1681221,58,16,2,4,'Kuningas sanoi minulle: "Mitä sinä siis pyydät?" Niin minä rukoilin taivaan Jumalaa'),
(1681222,58,16,2,5,'ja sanoin kuninkaalle: "Jos kuningas hyväksi näkee ja jos olet mielistynyt palvelijaasi, niin lähetä minut Juudaan, siihen kaupunkiin, jossa minun isieni haudat ovat, rakentamaan sitä uudestaan".'),
(1681223,58,16,2,6,'Niin kuningas kysyi minulta, kuningattaren istuessa hänen vieressään: "Kuinka kauan sinun matkasi kestäisi ja milloin voisit palata?" Kun siis kuningas näki hyväksi lähettää minut, ilmoitin minä hänelle määrätyn ajan.'),
(1681224,58,16,2,7,'Ja minä sanoin kuninkaalle: "Jos kuningas hyväksi näkee, niin annettakoon minun mukaani kirjeet Eufrat-virran tuonpuoleisen maan käskynhaltijoille, että he sallivat minun kulkea sen kautta perille Juudaan asti,'),
(1681225,58,16,2,8,'samoin kirje Aasafille, kuninkaan puiston vartijalle, että hän antaa minulle hirsiä temppelilinnan porttien kattamista varten sekä kaupungin muuria ja sitä taloa varten, johon menen asumaan". Ja kuningas myönsi minulle sen, koska minun Jumalani hyvä käsi oli minun päälläni.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681226,58,16,2,9,'Kun minä sitten tulin Eufrat-virran tämänpuoleisen maan käskynhaltijain luo, annoin minä heille kuninkaan kirjeet. Ja kuningas oli lähettänyt minun kanssani sotapäälliköitä ja ratsumiehiä.'),
(1681227,58,16,2,10,'Mutta kun hooronilainen Sanballat ja ammonilainen virkamies Tobia sen kuulivat, pahastuivat he kovin siitä, että oli tullut joku, joka harrasti israelilaisten parasta.'),
(1681228,58,16,2,11,'Ja tultuani Jerusalemiin ja oltuani siellä kolme päivää'),
(1681229,58,16,2,12,'minä nousin yöllä, ja muutamat miehet minun kanssani, ilmoittamatta kenellekään, mitä Jumalani oli pannut minun sydämeeni ja määrännyt tehtäväksi Jerusalemille. Eikä minulla ollut mukanani muuta juhtaakaan kuin se juhta, jolla minä ratsastin.'),
(1681230,58,16,2,13,'Ja minä lähdin yöllä Laaksoportista Lohikäärmelähteelle päin ja Lantaportille ja tarkastelin Jerusalemin maahanrevittyjä muureja ja sen tulella poltettuja portteja.'),
(1681231,58,16,2,14,'Ja minä kuljin eteenpäin Lähdeportille ja Kuninkaanlammikolle; mutta siellä ei ollut juhdalla, jonka selässä minä istuin, tilaa päästä eteenpäin.'),
(1681232,58,16,2,15,'Silloin minä menin yöllä laaksoa myöten ylöspäin ja tarkastin muuria. Sitten minä palasin taas Laaksoportin kautta ja tulin takaisin.'),
(1681233,58,16,2,16,'Mutta esimiehet eivät tietäneet, mihin minä olin mennyt ja mitä tein, sillä minä en ollut vielä ilmaissut mitään kenellekään, en juutalaisille, en papeille, ylimyksille, esimiehille enkä muille, joiden oli oltava mukana siinä työssä.'),
(1681234,58,16,2,17,'Mutta nyt minä sanoin heille: "Te näette, missä kurjuudessa me olemme, kun Jerusalem on autio ja sen portit tulella poltetut. Tulkaa, rakentakaamme uudestaan Jerusalemin muuri, ettemme enää olisi häväistyksen alaiset."'),
(1681235,58,16,2,18,'Ja minä kerroin heille, kuinka minun Jumalani hyvä käsi oli ollut minun päälläni ja myös mitä kuningas oli minulle sanonut. Niin he sanoivat: "Nouskaamme ja rakentakaamme". Ja he saivat rohkeuden käydä käsiksi tähän hyvään työhön.'),
(1681236,58,16,2,19,'Mutta kun hooronilainen Sanballat ja ammonilainen virkamies Tobia ja arabialainen Gesem sen kuulivat, pilkkasivat he meitä, osoittivat meille halveksumistaan ja sanoivat: "Mitä te siinä teette? Kapinoitteko te kuningasta vastaan?"'),
(1681237,58,16,2,20,'Silloin minä vastasin ja sanoin heille: "Taivaan Jumala on antava meille menestystä, ja me, hänen palvelijansa, nousemme ja rakennamme. Mutta teillä ei ole mitään osuutta eikä oikeutta Jerusalemiin, eikä teidän muistonne ole siellä pysyvä."'),
(1681238,58,16,3,1,'Ylimmäinen pappi Eljasib ja hänen veljensä, papit, nousivat ja rakensivat Lammasportin, jonka he pyhittivät ja jonka ovet he asettivat paikoilleen, edelleen Hammea-torniin asti, jonka he pyhittivät, ja edelleen Hananelin-torniin asti.'),
(1681239,58,16,3,2,'Heistä eteenpäin rakensivat Jerikon miehet; ja näistä eteenpäin rakensi Sakkur, Imrin poika.'),
(1681240,58,16,3,3,'Ja Kalaportin rakensivat senaalaiset; he kattoivat sen ja asettivat paikoilleen sen ovet, teljet ja salvat.'),
(1681241,58,16,3,4,'Heistä eteenpäin korjasi muuria Meremot, Uurian poika, joka oli Koosin poika; hänestä eteenpäin korjasi Mesullam, Berekjan poika, joka oli Mesesabelin poika; ja hänestä eteenpäin korjasi Saadok, Baanan poika.'),
(1681242,58,16,3,5,'Hänestä eteenpäin korjasivat muuria tekoalaiset; mutta heidän ylhäisensä eivät notkistaneet niskaansa Herransa palvelukseen.'),
(1681243,58,16,3,6,'Vanhan portin korjasivat Joojada, Paaseahin poika, ja Mesullam, Besodjan poika; he kattoivat sen ja asettivat paikoilleen sen ovet, teljet ja salvat.'),
(1681244,58,16,3,7,'Heistä eteenpäin korjasivat muuria gibeonilainen Melatja ja meeronotilainen Jaadon sekä Gibeonin ja Mispan miehet, jotka olivat Eufrat-virran tämänpuoleisen käskynhaltijan vallan alaisia.'),
(1681245,58,16,3,8,'Heistä eteenpäin korjasi muuria Ussiel, Harhajan poika, yksi kultasepistä, ja hänestä eteenpäin korjasi Hananja, yksi voiteensekoittajista; he panivat kuntoon Jerusalemia Leveään muuriin saakka.'),
(1681246,58,16,3,9,'Heistä eteenpäin korjasi muuria Refaja, Huurin poika, Jerusalemin piirin toisen puolen päällikkö.'),
(1681247,58,16,3,10,'Hänestä eteenpäin korjasi Jedaja, Harumafin poika, oman talonsa kohdalta; hänestä eteenpäin korjasi Hattus, Hasabnejan poika.'),
(1681248,58,16,3,11,'Toisen osan korjasivat Malkia, Haarimin poika, ja Hassub, Pahat-Mooabin poika, sekä sen lisäksi Uunitornin.'),
(1681249,58,16,3,12,'Heistä eteenpäin korjasi Sallum, Looheksen poika, Jerusalemin piirin toisen puolen päällikkö, hän ja hänen tyttärensä.'),
(1681250,58,16,3,13,'Laaksoportin korjasivat Haanun ja Saanoahin asukkaat; he rakensivat sen ja asettivat paikoilleen sen ovet, teljet ja salvat. Sen lisäksi he korjasivat tuhat kyynärää muuria, Lantaporttiin saakka.'),
(1681251,58,16,3,14,'Lantaportin korjasi Malkia, Reekabin poika, Beet-Keremin piirin päällikkö; hän rakensi sen ja asetti paikoilleen sen ovet, teljet ja salvat.'),
(1681252,58,16,3,15,'Lähdeportin korjasi Sallum, Kolhoosen poika, Mispan piirin päällikkö; hän rakensi sen, teki siihen katon ja asetti paikoilleen sen ovet, teljet ja salvat. Sen lisäksi hän korjasi Vesijohtolammikon muurin, kuninkaan puutarhan luota, aina niihin portaisiin saakka, jotka laskeutuvat Daavidin kaupungista.'),
(1681253,58,16,3,16,'Hänen jälkeensä korjasi Nehemia, Asbukin poika, Beet-Suurin piirin toisen puolen päällikkö, aina Daavidin hautojen kohdalle ja Tekolammikolle ja Urhojentalolle saakka.'),
(1681254,58,16,3,17,'Hänen jälkeensä korjasivat muuria leeviläiset: Rehum, Baanin poika; hänestä eteenpäin korjasi Hasabja, Kegilan piirin toisen puolen päällikkö, piirinsä puolesta.'),
(1681255,58,16,3,18,'Hänen jälkeensä korjasivat heidän veljensä: Bavvai, Heenadadin poika, joka oli Kegilan piirin toisen puolen päällikkö.'),
(1681256,58,16,3,19,'Hänestä eteenpäin korjasi Eeser, Jeesuan poika, Mispan päällikkö, toisen osan, siltä kohdalta, mistä noustaan asehuoneeseen, joka on Kulmauksessa.'),
(1681257,58,16,3,20,'Hänen jälkeensä korjasi Baaruk, Sabbain poika, suurella innolla toisen osan, Kulmauksesta aina ylimmäisen papin Eljasibin talon oveen saakka.'),
(1681258,58,16,3,21,'Hänen jälkeensä korjasi Meremot, Uurian poika, joka oli Koosin poika, toisen osan, Eljasibin talon ovesta Eljasibin talon päähän.'),
(1681259,58,16,3,22,'Hänen jälkeensä korjasivat papit, Lakeuden miehet.'),
(1681260,58,16,3,23,'Heidän jälkeensä korjasivat Benjamin ja Hassub oman talonsa kohdalta; heidän jälkeensä korjasi Asarja, Maasejan poika, joka oli Ananjan poika, talonsa viereltä.'),
(1681261,58,16,3,24,'Hänen jälkeensä korjasi Binnui, Heenadadin poika, toisen osan, Asarjan talosta aina Kulmaukseen ja kulmaan saakka.'),
(1681262,58,16,3,25,'Paalal, Uusain poika, korjasi Kulmauksen ja Ylätornin kohdalta, joka ulkonee kuninkaan linnasta vankilan pihaan päin; hänen jälkeensä Pedaja, Paroksen poika'),
(1681263,58,16,3,26,'- temppelipalvelijat asuivat Oofelilla - itäisen Vesiportin ja ulkonevan tornin kohdalta.'),
(1681264,58,16,3,27,'Hänen jälkeensä korjasivat tekoalaiset toisen osan, suuren, ulkonevan tornin kohdalta aina Oofelin muuriin saakka.'),
(1681265,58,16,3,28,'Hevosportin yläpuolelta korjasivat papit, kukin oman talonsa kohdalta.'),
(1681266,58,16,3,29,'Heidän jälkeensä korjasi Saadok, Immerin poika, oman talonsa kohdalta. Ja hänen jälkeensä korjasi Semaja, Sekanjan poika, Itäportin vartija.'),
(1681267,58,16,3,30,'Hänen jälkeensä korjasivat Hananja, Selemjan poika, ja Haanun, Saalafin kuudes poika, toisen osan; hänen jälkeensä korjasi Mesullam, Berekjan poika, yliskammionsa kohdalta.'),
(1681268,58,16,3,31,'Hänen jälkeensä korjasi Malkia, yksi kultasepistä, temppelipalvelijain ja kauppiasten taloon asti, Vartiotornin kohdalta, ja aina Kulmasaliin saakka.'),
(1681269,58,16,3,32,'Kultasepät ja kauppiaat korjasivat muurin Kulmasalin ja Lammasportin väliltä.'),
(1681270,58,16,4,1,'Kun Sanballat kuuli meidän rakentavan muuria, vihastui hän ja närkästyi kovin. Ja hän pilkkasi juutalaisia'),
(1681271,58,16,4,2,'ja puhui veljilleen ja Samarian sotaväelle ja sanoi: "Mitä nuo viheliäiset juutalaiset tekevät? Jätetäänkö heidät omiin valtoihinsa? Tulevatko he uhraamaan? Saavatko he työnsä kohta valmiiksi? Voivatko he tehdä eläviksi poltetut kivet tuhkaläjissä?"'),
(1681272,58,16,4,3,'Ja ammonilainen Tobia seisoi hänen vieressään ja sanoi: "Rakentakoot vain! Kettukin saa heidän kivimuurinsa hajoamaan, jos hyppää sen päälle."'),
(1681273,58,16,4,4,'Kuule, Jumalamme, kuinka halveksitut me olemme. Käännä heidän häpäisynsä heidän omaan päähänsä. Saata heidät ryöstetyiksi vankeuden maassa.'),
(1681274,58,16,4,5,'Älä peitä heidän rikkomustansa, älköönkä heidän syntiänsä pyyhittäkö pois sinun kasvojesi edestä, koska he ovat vihoittaneet sinut kohtelemalla noin rakentajia.'),
(1681275,58,16,4,6,'Mutta me rakensimme muuria; ja koko muuri tuli valmiiksi puoleen korkeuteensa asti, ja siitä kansa sai rohkeutta työhön.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681276,58,16,4,7,'Mutta kun Sanballat, Tobia, arabialaiset, ammonilaiset ja asdodilaiset kuulivat, että Jerusalemin muurien korjaus edistyi, niin että niiden aukot alkoivat täyttyä, vihastuivat he kovin.'),
(1681277,58,16,4,8,'Ja he kaikki tekivät liiton keskenään käydäksensä taisteluun Jerusalemia vastaan ja tehdäkseen siellä häiriötä.'),
(1681278,58,16,4,9,'Niin me rukoilimme Jumalaamme ja asetimme vartijat heitä vastaan, suojelemaan itseämme heiltä päivin ja öin.'),
(1681279,58,16,4,10,'Mutta Juuda sanoi: "Taakankantajain voima raukeaa, ja soraa on ylen paljon; me emme jaksa rakentaa muuria".'),
(1681280,58,16,4,11,'Ja meidän vastustajamme sanoivat: "Ennenkuin he tietävät tai huomaavat, me tulemme heidän keskellensä ja tapamme heidät ja lopetamme työn".'),
(1681281,58,16,4,12,'Mutta kun heidän läheisyydessään asuvat juutalaiset tulivat ja sanoivat meille joka taholta kymmenenkin kertaa: "Vetäytykää meidän luoksemme",'),
(1681282,58,16,4,13,'silloin minä asetin kansan muurin taakse, alempiin ja suojattomiin paikkoihin, asetin heidät sukukunnittain asemiinsa miekkoineen, keihäineen ja jousineen.'),
(1681283,58,16,4,14,'Ja katsastettuani kaiken minä nousin ja sanoin ylimyksille ja esimiehille ja muulle kansalle: "Älkää peljätkö heitä; muistakaa suurta ja peljättävää Herraa, ja taistelkaa veljienne, poikienne ja tyttärienne, vaimojenne ja kotienne puolesta".'),
(1681284,58,16,4,15,'Sitten kuin vihollisemme olivat kuulleet, että me olimme saaneet tietää asian ja että Jumala oli tehnyt heidän hankkeensa tyhjäksi, palasimme me kaikki takaisin muurille, itsekukin työhönsä.'),
(1681285,58,16,4,16,'Siitä päivästä alkaen teki toinen puoli minun palvelijoitani työtä, ja toinen puoli oli asestettuna keihäillä, kilvillä, jousilla ja rintahaarniskoilla; ja päämiehet seisoivat kaikkien niiden juutalaisten takana,'),
(1681286,58,16,4,17,'jotka rakensivat muurilla. Nekin, jotka kantoivat taakkoja ja kuljettivat kuormia, tekivät toisella kädellänsä työtä ja toisessa pitivät keihästä.'),
(1681287,58,16,4,18,'Ja rakentajilla oli kullakin miekka sidottuna vyöllensä heidän rakentaessaan; ja torvensoittaja seisoi minun vieressäni.'),
(1681288,58,16,4,19,'Minä sanoin ylimyksille, esimiehille ja muulle kansalle: "Työ on suuri ja laaja, ja me olemme muurilla hajallamme, kaukana toisistamme.'),
(1681289,58,16,4,20,'Missä kuulette torven soivan, sinne kokoontukaa meidän luoksemme. Meidän Jumalamme sotii meidän puolestamme."'),
(1681290,58,16,4,21,'Näin me siis teimme työtä, ja toinen puoli väkeä oli asestettuna keihäillä päivänkoitosta siihen asti, kunnes tähdet tulivat näkyviin.'),
(1681291,58,16,4,22,'Siihen aikaan minä myös sanoin kansalle: "Kukin jääköön palvelijoineen yöksi Jerusalemiin, että he olisivat meidän apunamme yöllä vartioimassa ja päivällä työssä".'),
(1681292,58,16,4,23,'Emmekä me, en minä, eivät minun veljeni ja palvelijani eivätkä ne vartijat, jotka minua seurasivat, riisuneet vaatteitamme. Kullakin keihäs ja vettä.'),
(1681293,58,16,5,1,'Mutta rahvas ja heidän vaimonsa nostivat suuren huudon juutalaisia veljiänsä vastaan.'),
(1681294,58,16,5,2,'Muutamat sanoivat: "Meitä, meidän poikiamme ja tyttäriämme on paljon. Meidän täytyy saada viljaa, että meillä olisi mitä syödä pysyäksemme hengissä."'),
(1681295,58,16,5,3,'Toiset sanoivat: "Peltomme, viinitarhamme ja talomme meidän täytyy pantata saadaksemme viljaa nälkäämme".'),
(1681296,58,16,5,4,'Toiset sanoivat: "Meidän on täytynyt kuninkaan veroihin lainata rahaa peltojamme ja viinitarhojamme vastaan.'),
(1681297,58,16,5,5,'Ovathan meidän ruumiimme veljiemme ruumiitten veroiset ja lapsemme heidän lastensa veroiset; ja katso, kuitenkin meidän täytyy antaa poikamme ja tyttäremme orjiksi, ja tyttäriämme on jo annettukin orjuuteen, emmekä me voi sille mitään, koska peltomme ja viinitarhamme ovat toisten käsissä."'),
(1681298,58,16,5,6,'Kun minä kuulin heidän valituksensa ja nämä puheet, vihastuin minä kovin.'),
(1681299,58,16,5,7,'Ja harkittuani mielessäni tätä asiaa minä nuhtelin ylimyksiä ja esimiehiä ja sanoin heille: "Tehän kiskotte korkoa, kukin veljeltänne". Sitten minä panin toimeen suuren kokouksen heitä vastaan.'),
(1681300,58,16,5,8,'Ja minä sanoin heille: "Me olemme, sen mukaan kuin olemme voineet, ostaneet vapaiksi juutalaisia veljiämme, jotka oli myyty pakanoille. Tekö nyt myytte veljiänne, ja täytyykö heidän myydä itsensä meille?" He olivat vaiti eivätkä voineet vastata mitään.'),
(1681301,58,16,5,9,'Ja minä sanoin: "Ette te siinä tee hyvin. Teidänhän tulisi vaeltaa meidän Jumalamme pelossa jo pakanain, meidän vihollistemme, häväistyksen tähden.'),
(1681302,58,16,5,10,'Myöskin minä, minun veljeni ja palvelijani olemme lainanneet heille rahaa ja viljaa; luopukaamme tästä saatavasta.'),
(1681303,58,16,5,11,'Luovuttakaa heille jo tänä päivänä heidän peltonsa, viinitarhansa, öljypuunsa ja talonsa, ja luopukaa rahan korosta sekä viljasta, viinistä ja öljystä, jonka olette heille lainanneet."'),
(1681304,58,16,5,12,'He vastasivat: "Me luovutamme ne emmekä vaadi heiltä mitään; me teemme, niinkuin olet sanonut". Ja minä kutsuin papit ja vannotin heidät tekemään näin.'),
(1681305,58,16,5,13,'Minä myös pudistin helmukseni ja sanoin: "Jokaisen, joka ei tätä sanaa täytä, pudistakoon Jumala näin pois hänen talostansa ja vaivannäkönsä hedelmistä; näin hän tulkoon pudistetuksi ja tyhjennetyksi". Ja koko seurakunta sanoi: "Amen", ja ylisti Herraa. Ja kansa teki, niinkuin oli sanottu.'),
(1681306,58,16,5,14,'Myöskään en minä eivätkä veljeni siitä päivästä asti, jona minut määrättiin olemaan heidän käskynhaltijanaan Juudan maassa, siis kuningas Artahsastan kahdennestakymmenennestä hallitusvuodesta aina hänen kolmanteenkymmenenteen toiseen hallitusvuoteensa saakka, eli kahtenatoista vuotena, syöneet käskynhaltijalle tulevaa ruokaa.'),
(1681307,58,16,5,15,'Sillä aikaisemmat käskynhaltijat, jotka olivat olleet ennen minua, olivat rasittaneet kansaa ja ottaneet siltä leipää ja viiniä sekä vielä neljäkymmentä hopeasekeliä. Myöskin heidän palvelijansa olivat sortaneet kansaa. Mutta minä en tehnyt niin, sillä minä pelkäsin Jumalaa.'),
(1681308,58,16,5,16,'Myöskin kävin minä itse käsiksi tämän muurin tekoon. Ja me emme ostaneet mitään peltoa. Ja kaikki minun palvelijani olivat kokoontuneet sinne työhön.'),
(1681309,58,16,5,17,'Myös sata viisikymmentä miestä, juutalaisia ja esimiehiä, söi minun pöydässäni sekä ne, jotka ympärillämme olevista pakanakansoista tulivat meidän luoksemme.'),
(1681310,58,16,5,18,'Ja mitä päivittäin valmistettiin ruuaksi, nimittäin härkä ja kuusi valiolammasta sekä lintuja, se valmistettiin minun kustannuksellani; ja joka kymmenes päivä hankittiin kaikenlaisia viinejä viljalti. Mutta siitä huolimatta minä en vaatinut itselleni käskynhaltijalle tulevaa ruokaa, koska työ painoi raskaasti tätä kansaa.'),
(1681311,58,16,5,19,'Muista, Jumalani, minun hyväkseni kaikki, mitä minä olen tehnyt tämän kansan puolesta.'),
(1681312,58,16,6,1,'Kun Sanballat, Tobia, arabialainen Gesem ja meidän muut vihollisemme kuulivat, että minä olin rakentanut muurin ja ettei siinä enää ollut aukkoa - vaikken minä ollutkaan vielä siihen aikaan asettanut ovia paikoilleen portteihin -'),
(1681313,58,16,6,2,'niin Sanballat ja Gesem lähettivät minulle sanan: "Tule, kohdatkaamme toisemme Kefirimissä, Oonon laaksossa". He näet ajattelivat tehdä minulle pahaa.'),
(1681314,58,16,6,3,'Niin minä lähetin heidän luokseen sanansaattajat ja käskin sanoa: "Minulla on suuri työ tekeillä, niin etten voi tulla. Keskeytyisihän työ, jos minä jättäisin sen ja tulisin teidän luoksenne."'),
(1681315,58,16,6,4,'Ja he lähettivät minulle saman sanan neljä kertaa, mutta minä vastasin heille aina samalla tavalla.'),
(1681316,58,16,6,5,'Silloin Sanballat lähetti viidennen kerran palvelijansa minun luokseni samassa asiassa, ja tällä oli kädessään avoin kirje.'),
(1681317,58,16,6,6,'Siihen oli kirjoitettu: "Kansojen kesken huhuillaan, ja myös Gasmu sanoo, että sinä ja juutalaiset suunnittelette kapinaa. Sentähden sinä rakennat muuria, ja itse sinä pyrit heidän kuninkaaksensa - niin kerrotaan.'),
(1681318,58,16,6,7,'Myöskin olet hankkinut profeettoja julistamaan itsestäsi Jerusalemissa näin: ''Juudassa on kuningas''. Tämän nyt kuningas saa kuulla; tule siis ja neuvotelkaamme keskenämme."'),
(1681319,58,16,6,8,'Silloin minä lähetin hänelle sanan: "Ei ole tapahtunut mitään semmoista, mistä puhut, vaan sinä olet keksinyt sen omasta päästäsi".'),
(1681320,58,16,6,9,'He näet kaikki peloittelivat meitä arvellen: "Heidän kätensä herpoavat työssä, ja se jää tekemättä". Mutta vahvista sinä minun käteni.'),
(1681321,58,16,6,10,'Minä menin Semajan, Delajan pojan, Mehetabelin pojanpojan, taloon, hänen ollessaan eristettynä. Hän sanoi: "Menkäämme yhdessä Jumalan temppeliin, temppelisaliin, ja sulkekaamme temppelisalin ovet. Sillä he tulevat tappamaan sinua; yöllä he tulevat ja tappavat sinut."'),
(1681322,58,16,6,11,'Mutta minä vastasin: "Pakenisiko minunlaiseni mies? Tahi kuinka voisi minunlaiseni mies mennä temppeliin ja kuitenkin jäädä eloon? Minä en mene."'),
(1681323,58,16,6,12,'Minä näet ymmärsin, ettei Jumala ollut häntä lähettänyt, vaan että hän oli lausunut minulle sen ennustuksen siitä syystä, että Tobia ja Sanballat olivat palkanneet hänet:'),
(1681324,58,16,6,13,'hänet oli palkattu siinä tarkoituksessa, että minä peljästyisin ja menettelisin sillä tavalla ja niin tekisin syntiä; siitä he saisivat panettelun aiheen, häväistäkseen minua.'),
(1681325,58,16,6,14,'Muista, Jumalani, Tobiaa ja Sanballatia näiden heidän tekojensa mukaan, niin myös naisprofeetta Nooadjaa ja muita profeettoja, jotka minua peloittelivat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681326,58,16,6,15,'Muuri valmistui elul-kuun kahdentenakymmenentenä viidentenä päivänä, viidenkymmenen kahden päivän kuluttua.'),
(1681327,58,16,6,16,'Kun kaikki meidän vihollisemme sen kuulivat, ja kaikki ympärillämme asuvat kansat näkivät sen, havaitsivat he joutuneensa aivan alakynteen; sillä he tunsivat, että tämä työ oli suoritettu meidän Jumalamme avulla.'),
(1681328,58,16,6,17,'Niinä päivinä meni myös Juudan ylimyksiltä lukuisia kirjeitä Tobialle, ja Tobialta tuli kirjeitä heille.'),
(1681329,58,16,6,18,'Sillä Juudassa oli monta, jotka olivat valalla liittoutuneet hänen kanssansa; sillä hän oli Sekanjan, Aarahin pojan, vävy, ja hänen poikansa Joohanan oli ottanut vaimokseen Mesullamin, Berekjan pojan, tyttären.'),
(1681330,58,16,6,19,'He myös puhuivat minulle hyvää hänestä ja veivät minun puheeni hänelle. Kirjeitäkin Tobia lähetti peloitellakseen minua.'),
(1681331,58,16,7,1,'Kun muuri oli rakennettu, asetin minä ovet paikoillensa; ja niiden vartioimisen saivat ovenvartijat, veisaajat ja leeviläiset tehtäväkseen.'),
(1681332,58,16,7,2,'Ja Jerusalemin päämiehiksi minä asetin veljeni Hananin ja linnanpäällikön Hananjan, sillä hän oli luotettava mies ja pelkäsi Jumalaa enemmän kuin moni muu.'),
(1681333,58,16,7,3,'Ja minä sanoin heille: "Jerusalemin portteja älköön avattako, ennenkuin aurinko on polttavimmillaan; ja vartijain vielä seisoessa paikoillaan on ovet suljettava ja salvoilla teljettävä. Ja Jerusalemin asukkaita pantakoon vartioimaan, kukin vartiopaikallensa, kukin oman talonsa kohdalle.'),
(1681334,58,16,7,4,'Kaupunki oli joka suuntaan tilava ja suuri, mutta väkeä siinä oli vähän, ja taloja oli vielä rakentamatta.'),
(1681335,58,16,7,5,'Niin Jumala antoi minun sydämeeni, että minun oli koottava ylimykset, esimiehet ja kansa sukuluetteloon merkittäviksi. Silloin minä löysin niiden sukuluettelon, jotka ensin olivat tulleet sinne, ja huomasin siihen kirjoitetun:'),
(1681336,58,16,7,6,'"Nämä ovat tämän maakunnan asukkaat, jotka lähtivät pakkosiirtolaisten vankeudesta, johon Nebukadnessar, Baabelin kuningas, oli heidät vienyt, ja palasivat Jerusalemiin ja Juudaan, kukin kaupunkiinsa,'),
(1681337,58,16,7,7,'ne, jotka tulivat Serubbaabelin, Jeesuan, Nehemian, Asarjan, Raamian, Nahamanin, Mordokain, Bilsanin, Misperetin, Bigvain, Nehumin ja Baanan kanssa. Israelin kansan miesten lukumäärä oli:'),
(1681338,58,16,7,8,'Paroksen jälkeläisiä kaksituhatta sata seitsemänkymmentä kaksi;'),
(1681339,58,16,7,9,'Sefatjan jälkeläisiä kolmesataa seitsemänkymmentä kaksi;'),
(1681340,58,16,7,10,'Aarahin jälkeläisiä kuusisataa viisikymmentä kaksi;'),
(1681341,58,16,7,11,'Pahat-Mooabin jälkeläisiä, nimittäin Jeesuan ja Jooabin jälkeläisiä, kaksituhatta kahdeksansataa kahdeksantoista;'),
(1681342,58,16,7,12,'Eelamin jälkeläisiä tuhat kaksisataa viisikymmentä neljä;'),
(1681343,58,16,7,13,'Sattun jälkeläisiä kahdeksansataa neljäkymmentä viisi;'),
(1681344,58,16,7,14,'Sakkain jälkeläisiä seitsemänsataa kuusikymmentä;'),
(1681345,58,16,7,15,'Binnuin jälkeläisiä kuusisataa neljäkymmentä kahdeksan;'),
(1681346,58,16,7,16,'Beebain jälkeläisiä kuusisataa kaksikymmentä kahdeksan;'),
(1681347,58,16,7,17,'Asgadin jälkeläisiä kaksituhatta kolmesataa kaksikymmentä kaksi;'),
(1681348,58,16,7,18,'Adonikamin jälkeläisiä kuusisataa kuusikymmentä seitsemän;'),
(1681349,58,16,7,19,'Bigvain jälkeläisiä kaksituhatta kuusikymmentä seitsemän;'),
(1681350,58,16,7,20,'Aadinin jälkeläisiä kuusisataa viisikymmentä viisi;'),
(1681351,58,16,7,21,'Aaterin, nimittäin Hiskian, jälkeläisiä yhdeksänkymmentä kahdeksan;'),
(1681352,58,16,7,22,'Haasumin jälkeläisiä kolmesataa kaksikymmentä kahdeksan;'),
(1681353,58,16,7,23,'Beesain jälkeläisiä kolmesataa kaksikymmentäneljä;'),
(1681354,58,16,7,24,'Haarifin jälkeläisiä sata kaksitoista;'),
(1681355,58,16,7,25,'gibeonilaisia yhdeksänkymmentä viisi;'),
(1681356,58,16,7,26,'Beetlehemin ja Netofan miehiä sata kahdeksankymmentä kahdeksan;'),
(1681357,58,16,7,27,'Anatotin miehiä sata kaksikymmentä kahdeksan;'),
(1681358,58,16,7,28,'Beet-Asmavetin miehiä neljäkymmentä kaksi;'),
(1681359,58,16,7,29,'Kirjat-Jearimin, Kefiran ja Beerotin miehiä seitsemänsataa neljäkymmentä kolme;'),
(1681360,58,16,7,30,'Raaman ja Geban miehiä kuusisataa kaksikymmentä yksi;'),
(1681361,58,16,7,31,'Mikmaan miehiä sata kaksikymmentä kaksi;'),
(1681362,58,16,7,32,'Beetelin ja Ain miehiä sata kaksikymmentä kolme;'),
(1681363,58,16,7,33,'toisen Nebon miehiä viisikymmentä kaksi;'),
(1681364,58,16,7,34,'toisen Eelamin jälkeläisiä tuhat kaksisataa viisikymmentä neljä;'),
(1681365,58,16,7,35,'Haarimin jälkeläisiä kolmesataa kaksikymmentä;'),
(1681366,58,16,7,36,'jerikolaisia kolmesataa neljäkymmentä viisi;'),
(1681367,58,16,7,37,'loodilaisia, haadidilaisia ja oonolaisia seitsemänsataa kaksikymmentä yksi;'),
(1681368,58,16,7,38,'senaalaisia kolmetuhatta yhdeksänsataa kolmekymmentä.'),
(1681369,58,16,7,39,'Pappeja oli: Jedajan jälkeläisiä, nimittäin Jesuan sukua, yhdeksänsataa seitsemänkymmentä kolme;'),
(1681370,58,16,7,40,'Immerin jälkeläisiä tuhat viisikymmentä kaksi;'),
(1681371,58,16,7,41,'Pashurin jälkeläisiä tuhat kaksisataa neljäkymmentä seitsemän;'),
(1681372,58,16,7,42,'Haarimin jälkeläisiä tuhat seitsemäntoista.'),
(1681373,58,16,7,43,'Leeviläisiä oli: Jeesuan ja Kadmielin jälkeläisiä, nimittäin Hoodevan jälkeläisiä, seitsemänkymmentä neljä.'),
(1681374,58,16,7,44,'Veisaajia oli: Aasafin jälkeläisiä sata neljäkymmentä kahdeksan.'),
(1681375,58,16,7,45,'Ovenvartijoita oli: Sallumin jälkeläisiä, Aaterin jälkeläisiä, Talmonin jälkeläisiä, Akkubin jälkeläisiä, Hatitan jälkeläisiä, Soobain jälkeläisiä sata kolmekymmentä kahdeksan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681376,58,16,7,46,'Temppelipalvelijoita oli: Siihan jälkeläiset, Hasufan jälkeläiset, Tabbaotin jälkeläiset,'),
(1681377,58,16,7,47,'Keeroksen jälkeläiset, Siian jälkeläiset, Paadonin jälkeläiset,'),
(1681378,58,16,7,48,'Lebanan jälkeläiset, Hagaban jälkeläiset, Salmain jälkeläiset,'),
(1681379,58,16,7,49,'Haananin jälkeläiset, Giddelin jälkeläiset, Gaharin jälkeläiset,'),
(1681380,58,16,7,50,'Reajan jälkeläiset, Resinin jälkeläiset, Nekodan jälkeläiset,'),
(1681381,58,16,7,51,'Gassamin jälkeläiset, Ussan jälkeläiset, Paaseahin jälkeläiset,'),
(1681382,58,16,7,52,'Beesain jälkeläiset, Meunimin jälkeläiset, Nefusesimin jälkeläiset,'),
(1681383,58,16,7,53,'Bakbukin jälkeläiset, Hakufan jälkeläiset, Harhurin jälkeläiset,'),
(1681384,58,16,7,54,'Baslutin jälkeläiset, Mehidan jälkeläiset, Harsan jälkeläiset,'),
(1681385,58,16,7,55,'Barkoksen jälkeläiset, Siiseran jälkeläiset, Taamahin jälkeläiset,'),
(1681386,58,16,7,56,'Nesiahin jälkeläiset, Hatifan jälkeläiset.'),
(1681387,58,16,7,57,'Salomon palvelijain jälkeläisiä oli: Sootain jälkeläiset, Sooferetin jälkeläiset, Peridan jälkeläiset,'),
(1681388,58,16,7,58,'Jaalan jälkeläiset, Darkonin jälkeläiset, Giddelin jälkeläiset,'),
(1681389,58,16,7,59,'Sefatjan jälkeläiset, Hattilin jälkeläiset, Kooferet-Sebaimin jälkeläiset, Aamonin jälkeläiset.'),
(1681390,58,16,7,60,'Temppelipalvelijoita ja Salomon palvelijain jälkeläisiä oli kaikkiaan kolmesataa yhdeksänkymmentä kaksi.'),
(1681391,58,16,7,61,'Nämä ovat ne, jotka lähtivät Teel-Melahista, Teel-Harsasta, Kerub-Addonista ja Immeristä, voimatta ilmoittaa perhekuntaansa ja syntyperäänsä, olivatko israelilaisia:'),
(1681392,58,16,7,62,'Delajan jälkeläiset, Tobian jälkeläiset, Nekodan jälkeläiset, kuusisataa neljäkymmentä kaksi.'),
(1681393,58,16,7,63,'Ja pappeja: Habaijan jälkeläiset, Koosin jälkeläiset, Barsillain jälkeläiset, sen, joka oli ottanut itsellensä vaimon gileadilaisen Barsillain tyttäristä ja jota kutsuttiin heidän nimellään.'),
(1681394,58,16,7,64,'Nämä etsivät sukuluetteloitaan, niitä löytämättä, ja niin heidät julistettiin pappeuteen kelpaamattomiksi.'),
(1681395,58,16,7,65,'Maaherra kielsi heitä syömästä korkeasti-pyhää, ennenkuin nousisi pappi, joka voi käyttää uurimia ja tummimia.'),
(1681396,58,16,7,66,'Koko seurakunta yhteenlaskettuna oli neljäkymmentäkaksi tuhatta kolmesataa kuusikymmentä,'),
(1681397,58,16,7,67,'paitsi heidän palvelijoitansa ja palvelijattariansa, joita oli seitsemäntuhatta kolmesataa kolmekymmentä seitsemän. Lisäksi oli heillä kaksisataa neljäkymmentä viisi mies- ja naisveisaajaa.'),
(1681398,58,16,7,68,'Kameleja heillä oli neljäsataa kolmekymmentä viisi, aaseja kuusituhatta seitsemänsataa kaksikymmentä.'),
(1681399,58,16,7,69,'Osa perhekunta-päämiehistä antoi lahjoja rakennustyötä varten. Maaherra antoi rahastoon tuhat dareikkia kultaa, viisikymmentä maljaa ja viisisataa kolmekymmentä papin-ihokasta.'),
(1681400,58,16,7,70,'Ja muutamat perhekunta-päämiehistä antoivat rakennusrahastoon kaksikymmentä tuhatta dareikkia kultaa ja kaksituhatta kaksisataa miinaa hopeata.'),
(1681401,58,16,7,71,'Ja muu kansa antoi yhteensä kaksikymmentä tuhatta dareikkia kultaa ja kaksituhatta miinaa hopeata sekä kuusikymmentä seitsemän papin-ihokasta.'),
(1681402,58,16,7,72,'Ja papit, leeviläiset, ovenvartijat, veisaajat ja osa kansasta sekä temppelipalvelijat, koko Israel, asettuivat kaupunkeihinsa. Ja niin tuli seitsemäs kuukausi, ja israelilaiset olivat jo kaupungeissansa.'),
(1681403,58,16,8,1,'Silloin kokoontui kaikki kansa yhtenä miehenä Vesiportin edustalla olevalle aukealle; ja he pyysivät Esraa, kirjanoppinutta, tuomaan Mooseksen lain kirjan, jonka lain Herra oli antanut Israelille.'),
(1681404,58,16,8,2,'Niin pappi Esra toi lain seurakunnan eteen, sekä miesten että naisten, kaikkien, jotka voivat ymmärtää, mitä kuulivat. Tämä tapahtui seitsemännen kuun ensimmäisenä päivänä.'),
(1681405,58,16,8,3,'Ja hän luki sitä Vesiportin edustalla olevalla aukealla päivän koitosta puolipäivään saakka miehille ja naisille, niille, jotka voivat sitä ymmärtää, kaiken kansan kuunnellessa lain kirjan lukemista.'),
(1681406,58,16,8,4,'Ja Esra, kirjanoppinut, seisoi korkealla puulavalla, joka oli tätä varten tehty. Ja hänen vieressään seisoivat: hänen oikealla puolellaan Mattitja, Sema, Anaja, Uuria, Hilkia ja Maaseja; ja hänen vasemmalla puolellaan Pedaja, Miisael, Malkia, Haasum, Hasbaddana, Sakarja ja Mesullam.'),
(1681407,58,16,8,5,'Ja Esra avasi kirjan kaiken kansan nähden, sillä hän seisoi ylempänä kaikkea kansaa; ja kun hän avasi sen, nousi kaikki kansa seisomaan.'),
(1681408,58,16,8,6,'Ja Esra kiitti Herraa, suurta Jumalaa, ja kaikki kansa vastasi, kohottaen kätensä ylös: "Amen, amen"; ja he kumarsivat ja rukoilivat Herraa, heittäytyneinä kasvoilleen maahan.'),
(1681409,58,16,8,7,'Sitten Jeesua, Baani, Seerebja, Jaamin, Akkub, Sabbetai, Hoodia, Maaseja, Kelita, Asarja, Joosabad, Haanan, Pelaja ja muut leeviläiset opettivat kansalle lakia, kansan seisoessa alallansa.'),
(1681410,58,16,8,8,'Ja he lukivat Jumalan lain kirjaa kappale kappaleelta ja selittivät sen sisällyksen, niin että luettu ymmärrettiin.'),
(1681411,58,16,8,9,'Ja Nehemia, maaherra, ja pappi Esra, kirjanoppinut, ja leeviläiset, jotka opettivat kansaa, sanoivat kaikelle kansalle: "Tämä päivä on pyhitetty Herralle, teidän Jumalallenne, älkää murehtiko älkääkä itkekö". Sillä kaikki kansa itki, kun he kuulivat lain sanat.'),
(1681412,58,16,8,10,'Ja hän sanoi vielä heille: "Menkää ja syökää rasvaisia ruokia ja juokaa makeita juomia ja lähettäkää maistiaisia niille, joilla ei ole mitään valmistettuna, sillä tämä päivä on pyhitetty meidän Herrallemme. Ja älkää olko murheelliset, sillä ilo Herrassa on teidän väkevyytenne."'),
(1681413,58,16,8,11,'Myöskin leeviläiset rauhoittivat kaikkea kansaa ja sanoivat: "Olkaa hiljaa, sillä tämä päivä on pyhä; älkää olko murheelliset".'),
(1681414,58,16,8,12,'Ja kaikki kansa meni, söi ja joi, lähetti maistiaisia ja vietti suurta ilojuhlaa; sillä he olivat ymmärtäneet, mitä heille oli julistettu.'),
(1681415,58,16,8,13,'Seuraavana päivänä kokoontuivat kaiken kansan perhekunta-päämiehet, papit ja leeviläiset Esran, kirjanoppineen, tykö painamaan lain sanoja mieleensä.'),
(1681416,58,16,8,14,'Niin he huomasivat lakiin kirjoitetun, että Herra oli Mooseksen kautta käskenyt israelilaisia asumaan lehtimajoissa juhlan aikana seitsemännessä kuussa,'),
(1681417,58,16,8,15,'ja että kaikissa heidän kaupungeissaan ja Jerusalemissa oli julistettava ja kuulutettava näin: "Menkää vuorille ja tuokaa öljypuun lehviä tai metsäöljypuun lehviä sekä myrtin, palmupuun ja muiden tuuheiden puiden lehviä, ja tehkää lehtimajoja, niinkuin on säädetty".'),
(1681418,58,16,8,16,'Ja kansa meni ja toi niitä ja teki itselleen lehtimajoja kukin katollensa ja pihoihinsa ja Jumalan temppelin esipihoihin sekä Vesiportin aukealle ja Efraimin portin aukealle.'),
(1681419,58,16,8,17,'Ja koko seurakunta, kaikki vankeudesta palanneet, tekivät lehtimajoja ja asuivat lehtimajoissa. Sillä aina Joosuan, Nuunin pojan, ajoista siihen päivään saakka eivät israelilaiset olleet niin tehneet. Ja vallitsi hyvin suuri ilo.'),
(1681420,58,16,8,18,'Ja Jumalan lain kirjaa luettiin joka päivä, ensimmäisestä päivästä viimeiseen saakka. Ja he viettivät juhlaa seitsemän päivää, ja kahdeksantena päivänä pidettiin juhlakokous säädetyllä tavalla.'),
(1681421,58,16,9,1,'Mutta saman kuun kahdentenakymmenentenä neljäntenä päivänä israelilaiset kokoontuivat paastoten, säkit yllä ja multaa pään päällä.'),
(1681422,58,16,9,2,'Ja Israelin heimo eristäytyi kaikista muukalaisista, astui esiin ja tunnusti syntinsä ja isiensä rikkomukset.'),
(1681423,58,16,9,3,'Sitten he nousivat seisomaan, kukin paikallansa, ja heille luettiin Herran, heidän Jumalansa, lain kirjaa neljännes päivää; ja toisen neljänneksen aikana he tunnustivat syntinsä ja kumartaen rukoilivat Herraa, Jumalaansa.'),
(1681424,58,16,9,4,'Ja Jeesua, Baani, Kadmiel, Sebanja, Bunni, Seerebja, Baani ja Kenani nousivat leeviläisten korokkeelle ja huusivat suurella äänellä Herraa, Jumalaansa;'),
(1681425,58,16,9,5,'ja leeviläiset Jeesua, Kadmiel, Baani, Hasabneja, Seerebja, Hoodia, Sebanja ja Petahja sanoivat: "Nouskaa ja kiittäkää Herraa, Jumalaanne, iankaikkisesta iankaikkiseen. Ja kiitettäköön sinun kunniallista nimeäsi, joka on korotettu yli kaiken kiitoksen ja ylistyksen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681426,58,16,9,6,'Sinä yksin olet Herra. Sinä olet tehnyt taivaat ja taivasten taivaat kaikkine joukkoinensa, maan ja kaikki, mitä siinä on, meret ja kaikki, mitä niissä on. Sinä annat elämän niille kaikille, ja taivaan joukot kumartavat sinua.'),
(1681427,58,16,9,7,'Sinä olet Herra Jumala, joka valitsit Abramin ja veit hänet pois Kaldean Uurista ja annoit hänelle nimen Aabraham.'),
(1681428,58,16,9,8,'Ja sinä havaitsit hänen sydämensä uskolliseksi sinua kohtaan, ja niin sinä teit hänen kanssaan liiton antaaksesi hänen jälkeläisillensä kanaanilaisten, heettiläisten, amorilaisten, perissiläisten, jebusilaisten ja girgasilaisten maan. Ja lupauksesi sinä olet täyttänyt, sillä sinä olet vanhurskas.'),
(1681429,58,16,9,9,'Ja sinä näit meidän isiemme kurjuuden Egyptissä ja kuulit heidän huutonsa Kaislameren rannalla.'),
(1681430,58,16,9,10,'Sinä teit tunnustekoja ja ihmeitä rangaisten faraota ja kaikkia hänen palvelijoitansa ja kaikkea hänen maansa kansaa; sillä sinä tiesit näiden kohdelleen heitä ylimielisesti, ja sinä teit itsellesi nimen, niinkuin se tänäkin päivänä on.'),
(1681431,58,16,9,11,'Meren sinä halkaisit heidän edessänsä kahtia, niin että he kulkivat meren poikki kuivaa myöten; mutta heidän takaa-ajajansa sinä syöksit syvyyteen, niinkuin kiven valtaviin vesiin.'),
(1681432,58,16,9,12,'Sinä johdatit heitä päivällä pilvenpatsaasta ja yöllä tulenpatsaasta, valaisten heille tien, jota heidän oli kuljettava.'),
(1681433,58,16,9,13,'Ja sinä astuit alas Siinain vuorelle ja puhuit heille taivaasta ja annoit heille oikeat tuomiot ja totiset lait, hyvät säädökset ja käskyt.'),
(1681434,58,16,9,14,'Sinä ilmoitit heille pyhän sapattisi ja annoit heille käskyt, säädökset ja lain palvelijasi Mooseksen kautta.'),
(1681435,58,16,9,15,'Sinä annoit heille leipää taivaasta heidän nälkäänsä, ja sinä hankit heille vettä kalliosta heidän janoonsa. Ja sinä käskit heidän mennä ottamaan omaksensa maan, jonka sinä olit kättä kohottaen luvannut heille antaa.'),
(1681436,58,16,9,16,'Mutta he, meidän isämme, olivat ylimielisiä; he olivat niskureita eivätkä totelleet sinun käskyjäsi.'),
(1681437,58,16,9,17,'He eivät tahtoneet totella eivätkä muistaneet ihmeellisiä tekoja, jotka sinä olit heille tehnyt, vaan olivat niskureita ja valitsivat uppiniskaisuudessaan johtajan palatakseen takaisin orjuuteensa. Mutta sinä olet anteeksiantava Jumala, armahtavainen ja laupias, pitkämielinen ja suuri armossa: sinä et heitä hyljännyt.'),
(1681438,58,16,9,18,'Vaikka he tekivät itsellensä valetun vasikankuvan ja sanoivat: ''Tämä on sinun jumalasi, joka on johdattanut sinut Egyptistä'', ja vaikka he paljon pilkkasivat Jumalaa,'),
(1681439,58,16,9,19,'niin sinä suuressa laupeudessasi et kuitenkaan hyljännyt heitä erämaassa. Pilvenpatsas ei väistynyt heidän luotansa päivällä, johtamasta heitä tiellä, eikä tulenpatsas yöllä, valaisemasta heille tietä, jota heidän oli kuljettava.'),
(1681440,58,16,9,20,'Hyvän Henkesi sinä annoit heitä opettamaan, mannaasi et kieltänyt heidän suustansa, ja vettä sinä annoit heille heidän janoonsa.'),
(1681441,58,16,9,21,'Neljäkymmentä vuotta sinä elätit heitä erämaassa, niin ettei heiltä mitään puuttunut, eivät heidän vaatteensa kuluneet, eivätkä heidän jalkansa ajettuneet.'),
(1681442,58,16,9,22,'Sinä annoit heidän haltuunsa valtakuntia ja kansoja ja jaoit ne alue alueelta; ja he valloittivat Siihonin maan - Hesbonin kuninkaan maan - ja Oogin, Baasanin kuninkaan, maan.'),
(1681443,58,16,9,23,'Ja heidän lastensa luvun sinä teit paljoksi kuin taivaan tähdet, ja sinä veit heidät siihen maahan, josta olit antanut heidän isillensä lupauksen, että he saavat mennä ottamaan sen omaksensa.'),
(1681444,58,16,9,24,'Ja lapset tulivat ja ottivat sen maan omaksensa, ja sinä nöyryytit heidän edessään maan asukkaat, kanaanilaiset, ja annoit nämä heidän käsiinsä, sekä heidän kuninkaansa että sen maan kansat, niin että he tekivät näille, mitä tahtoivat.'),
(1681445,58,16,9,25,'Ja he valloittivat varustetut kaupungit ja lihavan maan ja ottivat omikseen talot, jotka olivat täynnä kaikkea hyvää, kallioon hakatut vesisäiliöt, viinitarhat, öljypuut ja hedelmäpuita suuret määrät. He söivät ja tulivat ravituiksi ja lihaviksi ja pitivät hyviä päiviä sinun antimiesi runsaudessa.'),
(1681446,58,16,9,26,'Mutta he niskoittelivat ja kapinoivat sinua vastaan, heittivät sinun lakisi selkänsä taa ja tappoivat sinun profeettasi, jotka heitä varoittivat palauttaakseen heidät sinun luoksesi; ja he pilkkasivat paljon Jumalaa.'),
(1681447,58,16,9,27,'Sentähden sinä annoit heidät heidän ahdistajainsa käsiin, ja nämä ahdistivat heitä. Mutta kun he ahdinkonsa aikana huusivat sinua, niin sinä taivaasta kuulit ja suuressa laupeudessasi annoit heille vapauttajia, jotka vapauttivat heidät heidän ahdistajainsa käsistä.'),
(1681448,58,16,9,28,'Mutta rauhaan päästyään he jälleen tekivät sitä, mikä on pahaa sinun edessäsi. Silloin sinä jätit heidät heidän vihollistensa käsiin, niin että nämä vallitsivat heitä. Mutta kun he jälleen huusivat sinua, kuulit sinä taivaasta ja pelastit heidät laupeudessasi monta kertaa.'),
(1681449,58,16,9,29,'Ja sinä varoitit heitä palauttaaksesi heidät seuraamaan sinun lakiasi, mutta he olivat ylimielisiä eivätkä totelleet sinun käskyjäsi, vaan he rikkoivat sinun oikeutesi - se ihminen, joka ne pitää, on niistä elävä - mutta he käänsivät uppiniskaisina selkänsä ja olivat niskureita eivätkä totelleet.'),
(1681450,58,16,9,30,'Sinä kärsit heitä monta vuotta ja varoitit heitä Hengelläsi profeettaisi kautta, mutta he eivät ottaneet sitä korviinsa. Niin sinä annoit heidät pakanallisten kansojen käsiin.'),
(1681451,58,16,9,31,'Mutta sinä suuressa laupeudessasi et tehnyt loppua heistä etkä hyljännyt heitä; sillä sinä olet armahtavainen ja laupias Jumala.'),
(1681452,58,16,9,32,'Ja nyt, Jumalamme, sinä suuri, väkevä ja peljättävä Jumala, joka pidät liiton ja säilytät laupeuden: älä katso vähäksi kaikkea sitä vaivaa, joka on kohdannut meitä, meidän kuninkaitamme, päämiehiämme, pappejamme, profeettojamme, isiämme ja koko sinun kansaasi, Assurin kuningasten ajoista aina tähän päivään saakka.'),
(1681453,58,16,9,33,'Sinä olet vanhurskas kaikessa, mikä on meitä kohdannut; sillä sinä olet ollut uskollinen teoissasi, mutta me olemme olleet jumalattomat.'),
(1681454,58,16,9,34,'Meidän kuninkaamme, päämiehemme, pappimme ja isämme eivät ole seuranneet sinun lakiasi eivätkä tarkanneet sinun käskyjäsi ja säädöksiäsi, jotka sinä olit heille antanut.'),
(1681455,58,16,9,35,'Ja vaikka he elivät omassa valtakunnassansa ja siinä antimien runsaudessa, jonka sinä olit heille antanut, ja avarassa ja lihavassa maassa, jonka sinä olit heille antanut, eivät he kuitenkaan palvelleet sinua eivätkä kääntyneet pois pahoista teoistansa.'),
(1681456,58,16,9,36,'Katso, me olemme nyt orjia; siinä maassa, jonka sinä meidän isillemme annoit, että he söisivät sen hedelmiä ja antimia, siinä meidän täytyy orjina olla.'),
(1681457,58,16,9,37,'Sen runsas sato tulee niille kuninkaille, jotka sinä meidän syntiemme tähden olet pannut meitä hallitsemaan; he vallitsevat meitä ja meidän karjaamme, niinkuin tahtovat, ja me olemme suuressa ahdistuksessa."'),
(1681458,58,16,10,1,'"Kaiken tämän johdosta me teemme sitoumuksen ja kirjoitamme siihen nimemme; sinetöidyssä asiakirjassa ovat meidän päämiestemme, leeviläistemme ja pappiemme nimet.'),
(1681459,58,16,10,2,'(10:3) Seraja, Asarja, Jeremia,'),
(1681460,58,16,10,3,'Pashur, Amarja, Malkia,'),
(1681461,58,16,10,4,'Hattus, Sebanja, Malluk,'),
(1681462,58,16,10,5,'Haarim, Meremot, Obadja,'),
(1681463,58,16,10,6,'Daniel, Ginneton, Baaruk,'),
(1681464,58,16,10,7,'Mesullam, Abia, Miijamin,'),
(1681465,58,16,10,8,'Maasja, Bilgai ja Semaja - nämä ovat pappeja.'),
(1681466,58,16,10,9,'Leeviläisiä ovat: Jeesua, Asanjan poika, Binnui, Heenadadin jälkeläinen, Kadmiel'),
(1681467,58,16,10,10,'ja heidän veljensä Sebanja, Hoodia, Kelita, Pelaja, Haanan,'),
(1681468,58,16,10,11,'Miika, Rehob, Hasabja,'),
(1681469,58,16,10,12,'Sakkur, Seerebja, Sebanja,'),
(1681470,58,16,10,13,'Hoodia, Baani ja Beninu.'),
(1681471,58,16,10,14,'Kansan päämiehiä ovat: Paros, Pahat-Mooab, Eelam, Sattu, Baani,'),
(1681472,58,16,10,15,'Bunni, Asgad, Beebai,'),
(1681473,58,16,10,16,'Adonia, Bigvai, Aadin,'),
(1681474,58,16,10,17,'Aater, Hiskia, Assur,'),
(1681475,58,16,10,18,'Hoodia, Haasum, Beesai,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681476,58,16,10,19,'Haarif, Anatot, Nuubai,'),
(1681477,58,16,10,20,'Magpias, Mesullam, Heesir,'),
(1681478,58,16,10,21,'Mesesabel, Saadok, Jaddua,'),
(1681479,58,16,10,22,'Pelatja, Haanan, Anaja,'),
(1681480,58,16,10,23,'Hoosea, Hananja, Hassub,'),
(1681481,58,16,10,24,'Loohes, Pilha, Soobek,'),
(1681482,58,16,10,25,'Rehum, Hasabna, Maaseja,'),
(1681483,58,16,10,26,'Ahia, Haanan, Aanan,'),
(1681484,58,16,10,27,'Malluk, Haarim ja Baana.'),
(1681485,58,16,10,28,'Ja muu kansa, papit, leeviläiset, ovenvartijat, veisaajat, temppelipalvelijat ja kaikki, jotka ovat eristäytyneet pakanallisista kansoista Jumalan lain puolelle, sekä heidän vaimonsa, poikansa ja tyttärensä, kaikki, jotka pystyvät sen ymmärtämään,'),
(1681486,58,16,10,29,'liittyvät ylhäisiin veljiinsä, tulevat valalle ja vannovat vaeltavansa Jumalan lain mukaan, joka on annettu Jumalan palvelijan Mooseksen kautta, ja noudattavansa ja seuraavansa kaikkia Herran, meidän Herramme, käskyjä, oikeuksia ja säädöksiä.'),
(1681487,58,16,10,30,'Me emme anna tyttäriämme maan kansoille emmekä ota heidän tyttäriänsä pojillemme vaimoiksi.'),
(1681488,58,16,10,31,'Me emme osta sapattina tai pyhäpäivänä maan kansoilta, jos ne tuovat kauppatavaraa tai viljaa mitä tahansa kaupaksi sapattina. Me jätämme joka seitsemäntenä vuotena maan lepäämään ja kaikki saatavat velkomatta.'),
(1681489,58,16,10,32,'Me sitoudumme suorittamaan vuodessa kolmannes-sekelin palvelusta varten Jumalamme temppelissä:'),
(1681490,58,16,10,33,'näkyleipiin, jokapäiväiseen ruokauhriin ja jokapäiväiseen polttouhriin, uhreihin sapatteina ja uudenkuun päivinä, juhlauhreihin ja pyhiin lahjoihin, syntiuhreihin sovituksen toimittamiseksi Israelille ja kaikkeen, mikä meidän Jumalamme temppelissä toimitettava on.'),
(1681491,58,16,10,34,'Me, papit, leeviläiset ja kansa, olemme heittäneet arpaa uhrilahjahalkojen tuomisesta perhekunnittain Jumalamme temppeliin määräaikoina joka vuosi, poltettaviksi Herran, meidän Jumalamme, alttarilla, niinkuin laissa on kirjoitettuna.'),
(1681492,58,16,10,35,'Me sitoudumme tuomaan maamme uutiset ja kaikkinaisten hedelmäpuiden uutiset joka vuosi Herran temppeliin'),
(1681493,58,16,10,36,'sekä esikoiset pojistamme ja karjastamme, niinkuin laissa on kirjoitettuna, ja tuomaan raavaittemme ja lampaittemme esikoiset Jumalamme temppeliin, papeille, jotka toimittavat virkaansa meidän Jumalamme temppelissä.'),
(1681494,58,16,10,37,'Me tuomme parhaat jyvärouheemme ja antimemme, parhaat kaikkinaisten puiden hedelmät, parhaan viinin ja öljyn papeille, Jumalamme temppelin kammioihin, ja maamme kymmenykset leeviläisille. Leeviläiset itse kantavat kymmenykset kaikista kaupungeista, missä meillä on maanviljelystä.'),
(1681495,58,16,10,38,'Ja papin, Aaronin pojan, tulee olla leeviläisten kanssa, heidän kantaessaan kymmenyksiä, ja leeviläisten tulee viedä kymmenykset kymmenyksistä meidän Jumalamme temppeliin, varastohuoneen kammioihin.'),
(1681496,58,16,10,39,'(10:40) Sillä israelilaisten ja leeviläisten on vietävä anti jyvistä, viinistä ja öljystä näihin kammioihin, joissa pyhäkön kalut ja virkaansa toimittavat papit, ovenvartijat ja veisaajat ovat. Me emme laiminlyö Jumalamme temppeliä."'),
(1681497,58,16,11,1,'Ja kansan päämiehet asettuivat Jerusalemiin, mutta muu kansa heitti arpaa saadakseen joka kymmenennen asettumaan Jerusalemiin, pyhään kaupunkiin, yhdeksän kymmenesosan jäädessä asumaan muihin kaupunkeihin.'),
(1681498,58,16,11,2,'Ja kansa siunasi kaikkia niitä miehiä, jotka vapaaehtoisesti asettuivat Jerusalemiin.'),
(1681499,58,16,11,3,'Nämä olivat ne maakunnan päämiehet, jotka asettuivat Jerusalemiin ja Juudan kaupunkeihin; he asuivat kukin perintöosallaan, kaupungeissaan, Israel, papit, leeviläiset ja temppelipalvelijat sekä Salomon palvelijain jälkeläiset.'),
(1681500,58,16,11,4,'Jerusalemissa asuivat seuraavat Juudan ja Benjamin miehet: Juudan miehiä: Ataja, Ussian poika, joka oli Sakarjan poika, joka Amarjan poika, joka Sefatjan poika, joka Mahalalelin poika, Pereksen jälkeläisiä,'),
(1681501,58,16,11,5,'ja Maaseja, Baarukin poika, joka oli Kolhoosen poika, joka Hasajan poika, joka Adajan poika, joka Joojaribin poika, joka Sakarjan poika, joka siilonilaisen poika;'),
(1681502,58,16,11,6,'Jerusalemissa asuvia Pereksen jälkeläisiä oli kaikkiaan neljäsataa kuusikymmentä kahdeksan sotakuntoista miestä.'),
(1681503,58,16,11,7,'Benjaminilaiset olivat nämä: Sallu, Mesullamin poika, joka oli Jooedin poika, joka Pedajan poika, joka Koolajan poika, joka Maasejan poika, joka Iitielin poika, joka Jesajan poika,'),
(1681504,58,16,11,8,'ja hänen jälkeensä Gabbai ja Sallai, yhdeksänsataa kaksikymmentä kahdeksan.'),
(1681505,58,16,11,9,'Jooel, Sikrin poika, oli heidän päällysmiehenään ja Juuda, Senuan poika, toisena kaupunginpäällikkönä.'),
(1681506,58,16,11,10,'Pappeja: Jedaja, Joojaribin poika, Jaakin,'),
(1681507,58,16,11,11,'Seraja, Hilkian poika, joka oli Mesullamin poika, joka Saadokin poika, joka Merajotin poika, joka Ahitubin poika, Jumalan temppelin esimies,'),
(1681508,58,16,11,12,'sekä heidän veljensä, jotka toimittivat palvelusta temppelissä, kahdeksansataa kaksikymmentä kaksi miestä; ja Adaja, Jerohamin poika, joka oli Pelaljan poika, joka Amsin poika, joka Sakarjan poika, joka Pashurin poika, joka Malkian poika,'),
(1681509,58,16,11,13,'sekä hänen veljensä, jotka olivat perhekunta-päämiehiä, kaksisataa neljäkymmentä kaksi miestä; ja Amassai, Asarelin poika, joka oli Ahsain poika, joka Mesillemotin poika, joka Immerin poika,'),
(1681510,58,16,11,14,'sekä heidän veljensä, jotka olivat sotaurhoja, sata kaksikymmentä kahdeksan miestä. Heidän päällysmiehenään oli Sabdiel, Gedolimin poika.'),
(1681511,58,16,11,15,'Ja leeviläisiä: Semaja, Hassubin poika, joka oli Asrikamin poika, joka Hasabjan poika, joka Bunnin poika;'),
(1681512,58,16,11,16,'ja Sabbetai ja Joosabad, jotka valvoivat maallisia toimia Jumalan temppelissä ja olivat leeviläisten päämiehiä,'),
(1681513,58,16,11,17,'ja Mattanja, Miikan poika, joka oli Sabdin poika, joka Aasafin, ensimmäisen johtajan, poika, joka rukoiltaessa alotti kiitosvirren, ja Bakbukja, hänen veljistään toinen, ja Abda, Sammuan poika, joka oli Gaalalin poika, joka Jedutunin poika.'),
(1681514,58,16,11,18,'Leeviläisiä oli pyhässä kaupungissa kaikkiaan kaksisataa kahdeksankymmentä neljä.'),
(1681515,58,16,11,19,'Ovenvartijat olivat Akkub, Talmon sekä heidän veljensä, jotka vartioivat portteja, sata seitsemänkymmentä kaksi.'),
(1681516,58,16,11,20,'Muut israelilaiset, papit ja leeviläiset asuivat kaikissa muissa Juudan kaupungeissa, kukin perintöosallaan.'),
(1681517,58,16,11,21,'Temppelipalvelijat asuivat Oofelilla; Siiha ja Gispa valvoivat temppelipalvelijoita.'),
(1681518,58,16,11,22,'Ja leeviläisten päällysmiehenä Jerusalemissa Jumalan temppelin toimissa oli Ussi, Baanin poika, joka oli Hasabjan poika, joka Mattanjan poika, joka Miikan poika, Aasafin jälkeläisiä, veisaajia.'),
(1681519,58,16,11,23,'Oli näet heitä koskeva kuninkaan käsky, joka vakuutti veisaajille heidän jokapäiväiset tarpeensa.'),
(1681520,58,16,11,24,'Ja Petahja, Mesesabelin poika, Serahin, Juudan pojan, jälkeläisiä, oli kuninkaan edusmiehenä kaikissa kansaa koskevissa asioissa.'),
(1681521,58,16,11,25,'Heidän peltomaillaan olevissa kylissä asui Juudan miehiä: Kirjat-Arbassa ja sen tytärkaupungeissa, Diibonissa ja sen tytärkaupungeissa, Jekabseelissa ja siihen kuuluvissa kylissä,'),
(1681522,58,16,11,26,'Jeesuassa, Mooladassa, Beet-Peletissä,'),
(1681523,58,16,11,27,'Hasar-Suualissa, Beersebassa ja sen tytärkaupungeissa,'),
(1681524,58,16,11,28,'Siklagissa, Mekonassa ja sen tytärkaupungeissa,'),
(1681525,58,16,11,29,'Een-Rimmonissa, Sorassa, Jarmutissa,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681526,58,16,11,30,'Saanoahissa, Adullamissa ja niihin kuuluvissa kylissä, Laakiissa ja sen peltomailla, Asekassa ja sen tytärkaupungeissa; he sijoittuivat siis asumaan Beersebasta aina Hinnomin laaksoon saakka.'),
(1681527,58,16,11,31,'Benjaminilaiset asuivat, Gebasta alkaen, Mikmaassa, Aijassa, Beetelissä ja sen tytärkaupungeissa,'),
(1681528,58,16,11,32,'Anatotissa, Noobissa, Ananjassa,'),
(1681529,58,16,11,33,'Haasorissa, Raamassa, Gittaimissa,'),
(1681530,58,16,11,34,'Haadidissa, Seboimissa, Neballatissa,'),
(1681531,58,16,11,35,'Loodissa, Oonossa, Seppäinlaaksossa.'),
(1681532,58,16,11,36,'Leeviläisistä asui eräitä Juudan osastoja Benjaminissa.'),
(1681533,58,16,12,1,'Nämä olivat ne papit ja leeviläiset, jotka lähtivät Serubbaabelin, Sealtielin pojan, ja Jeesuan kanssa: Seraja, Jeremia, Esra,'),
(1681534,58,16,12,2,'Amarja, Malluk, Hattus,'),
(1681535,58,16,12,3,'Sekanja, Rehum, Meremot,'),
(1681536,58,16,12,4,'Iddo, Ginnetoi, Abia,'),
(1681537,58,16,12,5,'Miijamin, Maadja, Bilga,'),
(1681538,58,16,12,6,'Semaja, Joojarib, Jedaja,'),
(1681539,58,16,12,7,'Sallu, Aamok, Hilkia ja Jedaja. Nämä olivat pappien ja veljiensä päämiehet Jeesuan aikana.'),
(1681540,58,16,12,8,'Ja leeviläiset olivat: Jeesua, Binnui, Kadmiel, Seerebja, Juuda ja Mattanja, joka yhdessä veljiensä kanssa johti kiitosveisua;'),
(1681541,58,16,12,9,'ja heidän veljensä Bakbukja ja Unni seisoivat vastapäätä heitä tehtäviään suorittamassa.'),
(1681542,58,16,12,10,'Jeesualle syntyi Joojakim, Joojakimille syntyi Eljasib, Eljasibille syntyi Joojada,'),
(1681543,58,16,12,11,'Joojadalle syntyi Joonatan ja Joonatanille syntyi Jaddua.'),
(1681544,58,16,12,12,'Joojakimin aikana olivat seuraavat papit perhekunta-päämiehinä: Serajalla Meraja, Jeremialla Hananja,'),
(1681545,58,16,12,13,'Esralla Mesullam, Amarjalla Joohanan,'),
(1681546,58,16,12,14,'Mallukilla Joonatan, Sebanjalla Joosef,'),
(1681547,58,16,12,15,'Haarimilla Adna, Merajotilla Helkai,'),
(1681548,58,16,12,16,'Iddolla Sakarja, Ginnetonilla Mesullam,'),
(1681549,58,16,12,17,'Abialla Sikri, Minjaminilla, Mooadjalla Piltai,'),
(1681550,58,16,12,18,'Bilgalla Sammua, Semajalla Joonatan,'),
(1681551,58,16,12,19,'Joojaribilla Mattenai, Jedajalla Ussi,'),
(1681552,58,16,12,20,'Sallailla Kallai, Aamokilla Eeber,'),
(1681553,58,16,12,21,'Hilkialla Hasabja ja Jedajalla Netanel.'),
(1681554,58,16,12,22,'Leeviläisistä merkittiin Eljasibin, Joojadan, Joohananin ja Jadduan aikana perhekunta-päämiehet muistiin; ja samoin papit persialaisen Daarejaveksen hallitusaikana.'),
(1681555,58,16,12,23,'Leevin jälkeläisistä ovat perhekunta-päämiehet merkittyinä aikakirjaan Joohananin, Eljasibin pojan, aikaan asti.'),
(1681556,58,16,12,24,'Ja leeviläisten päämiehet olivat Hasabja, Seerebja ja Jeesua, Kadmielin poika, sekä heidän veljensä, jotka seisoivat heitä vastapäätä ylistämässä ja kiittämässä, niinkuin Jumalan mies Daavid oli käskenyt, osasto osaston vieressä;'),
(1681557,58,16,12,25,'ja Mattanja, Bakbukja, Obadja, Mesullam, Talmon ja Akkub, ovenvartijat, jotka vartioivat porttien varastohuoneita.'),
(1681558,58,16,12,26,'Nämä olivat Joojakimin, Jeesuan pojan, Joosadakin pojanpojan, aikalaisia ja käskynhaltija Nehemian ja pappi Esran, kirjanoppineen, aikalaisia.'),
(1681559,58,16,12,27,'Kun Jerusalemin muuri oli vihittävä, haettiin leeviläiset kaikista heidän asuinpaikoistansa ja tuotiin Jerusalemiin viettämään vihkimäjuhlaa iloiten, kiitosvirsiä ja lauluja laulaen, kymbaaleja, harppuja ja kanteleita soittaen.'),
(1681560,58,16,12,28,'Niin kokoontuivat veisaajain pojat Lakeudelta, Jerusalemin ympäristöstä, netofalaisten kylistä,'),
(1681561,58,16,12,29,'Beet-Gilgalista ja Geban ja Asmavetin peltomailta, sillä veisaajat olivat rakentaneet itselleen kyliä Jerusalemin ympäristöön.'),
(1681562,58,16,12,30,'Papit ja leeviläiset puhdistautuivat ja puhdistivat kansan sekä portit ja muurin.'),
(1681563,58,16,12,31,'Sitten minä vein Juudan päämiehet rinteelle, muurin yläpuolelle, ja järjestin kaksi suurta laulukuntaa ja juhlakulkuetta muurin yläpuolelle, oikealle kädelle, Lantaportille päin.'),
(1681564,58,16,12,32,'Ja heidän jäljessään kulkivat Hoosaja ja toinen puoli Juudan päämiehiä'),
(1681565,58,16,12,33,'sekä Asarja, Esra, Mesullam,'),
(1681566,58,16,12,34,'Juuda, Benjamin, Semaja ja Jeremia'),
(1681567,58,16,12,35,'sekä pappien poikia torvineen, ja Sakarja, Joonatanin poika, joka oli Semajan poika, joka Mattanjan poika, joka Miikajan poika, joka Sakkurin poika, joka Aasafin poika,'),
(1681568,58,16,12,36,'sekä hänen veljensä Semaja, Asarel, Milalai, Gilalai, Maai, Netanel, Juuda ja Hanani Daavidin, Jumalan miehen, soittimia kantaen; ja Esra, kirjanoppinut, kulki heidän edellään.'),
(1681569,58,16,12,37,'He menivät Lähdeportin ohi ja nousivat suoraan Daavidin kaupungin portaita sinne, mistä noustaan muurille, Daavidin palatsin yläpuolelle, aina Vesiportille asti idässä.'),
(1681570,58,16,12,38,'Toinen laulukunta kulki vastakkaiseen suuntaan, ja sen jäljessä minä ja toinen puoli kansaa, muurin yläpuolitse, Uunitornin yläpuolitse, aina Leveälle muurille asti,'),
(1681571,58,16,12,39,'ja Efraimin-portin yläpuolitse ja Vanhanportin, Kalaportin, Hananelin-tornin ja Hammea-tornin ohitse aina Lammasportille saakka; ja he asettuivat Vankilaportin luokse.'),
(1681572,58,16,12,40,'Sitten molemmat laulukunnat asettuivat Jumalan temppeliin, ja samoin minä ja toinen puoli esimiehiä minun kanssani,'),
(1681573,58,16,12,41,'sekä papit Eljakim, Maaseja, Minjamin, Miikaja, Eljoenai, Sakarja ja Hananja torvineen,'),
(1681574,58,16,12,42,'ja Maaseja, Semaja, Eleasar, Ussi, Joohanan, Malkia, Eelam ja Eser. Veisaajat kaiuttivat virsiään, ja Jisrahja oli johtajana.'),
(1681575,58,16,12,43,'Ja he uhrasivat sinä päivänä suuria uhreja ja iloitsivat, sillä Jumala oli suuresti ilahuttanut heitä; myöskin vaimot ja lapset iloitsivat. Ja ilo kuului Jerusalemista kauas.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681576,58,16,12,44,'Sinä päivänä asetettiin miehiä valvomaan varastokammioita, joissa antimet, uutiset ja kymmenykset säilytettiin. Niihin oli koottava kaupunkien peltomailta papeille ja leeviläisille lain mukaan tulevat osuudet. Sillä Juuda iloitsi palvelusta toimittavista papeista ja leeviläisistä.'),
(1681577,58,16,12,45,'Ja nämä toimittivat tehtävänsä Jumalaansa palvellen ja puhdistuksia suorittaen, samoin veisaajat ja ovenvartijat, niinkuin Daavid ja hänen poikansa Salomo olivat käskeneet.'),
(1681578,58,16,12,46,'Sillä jo muinoin, Daavidin ja Aasafin aikana, oli veisaajain päämiehiä, ja veisattiin ylistys- ja kiitosvirsiä Jumalalle.'),
(1681579,58,16,12,47,'Ja koko Israel antoi Serubbaabelin ja Nehemian aikana veisaajille ja ovenvartijoille heidän osuutensa, heidän jokapäiväiset tarpeensa; he pyhittivät lahjoja myöskin leeviläisille, ja leeviläiset pyhittivät lahjoja Aaronin pojille.'),
(1681580,58,16,13,1,'Sinä päivänä luettiin Mooseksen kirjaa kansan kuullen, ja siihen havaittiin kirjoitetun, ettei ammonilainen eikä mooabilainen koskaan pääse Jumalan seurakuntaan,'),
(1681581,58,16,13,2,'sen tähden että he eivät tulleet leipää ja vettä tuoden israelilaisia vastaan ja koska hän palkkasi heitä vastaan Bileamin kiroamaan heidät, vaikka meidän Jumalamme muuttikin kirouksen siunaukseksi.'),
(1681582,58,16,13,3,'Kuultuaan lain he erottivat kaiken sekakansan Israelista.'),
(1681583,58,16,13,4,'Mutta sitä ennen oli pappi Eljasib, Tobian sukulainen, joka oli asetettu meidän Jumalamme temppelin kammionhoitajaksi,'),
(1681584,58,16,13,5,'sisustanut hänelle suuren kammion, johon ennen oli pantu ruokauhri, suitsuke, kalut ja jyvä-, viini- ja öljykymmenykset, jotka olivat määrätyt leeviläisille, veisaajille ja ovenvartijoille, sekä papeille tuleva anti.'),
(1681585,58,16,13,6,'Tämän kaiken tapahtuessa en minä ollut Jerusalemissa; sillä Artahsastan, Baabelin kuninkaan, kolmantenakymmenentenä toisena hallitusvuotena minä olin mennyt kuninkaan luo. Mutta jonkun ajan kuluttua minä pyysin kuninkaalta lomaa'),
(1681586,58,16,13,7,'ja palasin Jerusalemiin. Ja kun minä tulin huomaamaan, minkä pahan Eljasib oli tehnyt Tobian eduksi, sisustaessaan hänelle kammion Jumalan temppelin esipihoissa,'),
(1681587,58,16,13,8,'pahastuin minä suuresti, ja minä heitin kaikki Tobian huonekalut ulos kammiosta.'),
(1681588,58,16,13,9,'Ja minä käskin puhdistaa kammiot ja panetin niihin takaisin Jumalan temppelin kalut, ruokauhrin ja suitsukkeen.'),
(1681589,58,16,13,10,'Vielä minä sain tietää, ettei leeviläisille oltu annettu heidän osuuksiaan, ja niin olivat leeviläiset ja veisaajat, joiden olisi ollut tehtävä palvelusta, vetäytyneet kukin maatilalleen.'),
(1681590,58,16,13,11,'Minä nuhtelin esimiehiä siitä ja sanoin: "Minkätähden on Jumalan temppeli laiminlyöty?" Ja minä kokosin leeviläiset ja veisaajat ja asetin heidät paikoilleen.'),
(1681591,58,16,13,12,'Ja koko Juuda toi kymmenykset jyvistä, viinistä ja öljystä varastohuoneisiin.'),
(1681592,58,16,13,13,'Ja minä asetin Selemjan, papin, ja Saadokin, kirjanoppineen, ja Pedajan, leeviläisen, valvomaan varastohuoneita ja annoin heidän apulaisekseen Haananin, Sakkurin pojan, Mattanjan pojanpojan; sillä heitä pidettiin luotettavina, ja heidän tehtävänään oli toimittaa jako veljiensä kesken.'),
(1681593,58,16,13,14,'Muista tämän tähden minua, Jumalani, äläkä pyyhi pois minun hurskaita tekojani, jotka minä olen tehnyt Jumalani temppelin ja siinä toimitettavan palveluksen hyväksi.'),
(1681594,58,16,13,15,'Siihen aikaan minä näin Juudassa niitä, jotka sapattina polkivat viinikuurnaa ja jotka kuljettivat viljaa ja kuormittivat aaseja sillä sekä viinillä, rypäleillä, viikunoilla ja kaikenlaisella muulla kuormatavaralla. Ja he toivat niitä Jerusalemiin sapatinpäivänä; ja minä varoitin heitä, kun he myivät elintarpeita.'),
(1681595,58,16,13,16,'Sinne oli myös asettunut tyyrolaisia, jotka toivat kalaa ja kaikenlaista kauppatavaraa ja myivät Juudan kansalle sapattina ja Jerusalemissa.'),
(1681596,58,16,13,17,'Ja minä nuhtelin Juudan ylimyksiä ja sanoin heille: "Kuinka te teette näin pahasti ja rikotte sapatinpäivän?'),
(1681597,58,16,13,18,'Eikö Jumalamme juuri sen tähden, että teidän isänne näin tekivät, antanut kaiken tämän onnettomuuden kohdata meitä ja tätä kaupunkia? Ja te tuotatte nyt vielä suuremman vihan Israelin ylitse, kun rikotte sapatinpäivän."'),
(1681598,58,16,13,19,'Ja niin pian kuin oli tullut pimeä ennen sapattia Jerusalemin porteissa, käskin minä sulkea ovet ja kielsin avaamasta niitä ennen kuin sapatin jälkeen. Ja minä asetin palvelijoitani porteille, ettei yhtään kuormaa pääsisi kaupunkiin sapatinpäivänä.'),
(1681599,58,16,13,20,'Kauppiaat ja kaikenlaisen tavaran myyjät jäivät yöksi Jerusalemin ulkopuolelle, kerran ja toisen.'),
(1681600,58,16,13,21,'Mutta minä varoitin heitä ja sanoin heille: "Minkätähden te jäätte yöksi muurin edustalle? Jos vielä kerran teette sen, niin minä käyn teihin käsiksi." Sen jälkeen he eivät enää tulleet sapattina.'),
(1681601,58,16,13,22,'Ja minä käskin leeviläisten puhdistautua ja tulla vartioimaan portteja, että sapatinpäivä pyhitettäisiin. Muista minua, Jumalani, myös tämän tähden ja armahda minua suuressa laupeudessasi.'),
(1681602,58,16,13,23,'Siihen aikaan minä näin myös juutalaisia, jotka olivat naineet asdodilaisia, ammonilaisia ja mooabilaisia vaimoja.'),
(1681603,58,16,13,24,'Ja heidän lapsistaan puolet puhuivat asdodinkieltä tai jonkun muun kansan kieltä, eivätkä osanneet puhua juudankieltä.'),
(1681604,58,16,13,25,'Silloin minä nuhtelin heitä ja kirosin heidät, jopa löin muutamia heistä ja revin heitä parrasta; ja minä vannotin heitä Jumalan kautta: "Älkää antako tyttäriänne heidän pojillensa älkääkä ottako heidän tyttäriään vaimoiksi pojillenne tai itsellenne.'),
(1681605,58,16,13,26,'Eikö Salomo, Israelin kuningas, tehnyt juuri tuollaista syntiä? Ei yhdelläkään monien kansojen joukossa ollut hänen vertaistaan kuningasta; hän oli Jumalallensa rakas, ja Jumala asetti hänet koko Israelin kuninkaaksi. Kuitenkin muukalaiset vaimot saattoivat hänetkin tekemään syntiä.'),
(1681606,58,16,13,27,'Ja nytkö meidän täytyy kuulla teistä, että te olette tehneet kaiken tämän suuren pahan ja olleet uskottomat meidän Jumalaamme kohtaan, kun olette naineet muukalaisia vaimoja?"'),
(1681607,58,16,13,28,'Ja yksi ylimmäisen papin Eljasibin pojan Joojadan pojista oli hooronilaisen Sanballatin vävy; hänet minä karkoitin luotani.'),
(1681608,58,16,13,29,'Muista heidät, Jumalani, sillä he ovat saastuttaneet pappeuden sekä sekä pappeuden sekä pappeus- ja leeviläisliiton.'),
(1681609,58,16,13,30,'Niin minä puhdistin heidät kaikesta muukalaisuudesta. Ja minä järjestin virkatehtävät papeille ja leeviläisille, kullekin hänen toimensa mukaan,'),
(1681610,58,17,1,1,'Ahasveroksen aikana - sen Ahasveroksen, joka hallitsi Intiasta Etiopiaan saakka, sataa kahtakymmentä seitsemää maakuntaa - siihen aikaan,'),
(1681611,58,17,1,2,'kun kuningas Ahasveros istui kuninkaallisella valtaistuimellansa, joka oli Suusanin linnassa, tapahtui tämä.'),
(1681612,58,17,1,3,'Kolmantena hallitusvuotenaan hän laittoi pidot kaikille ruhtinaillensa ja palvelijoillensa. Persian ja Meedian voima, ylimykset ja maaherrat olivat hänen luonansa,'),
(1681613,58,17,1,4,'ja hän näytti heille kuninkaallisen kunniansa rikkautta ja suuruutensa loistavaa komeutta monta päivää, sata kahdeksankymmentä päivää.'),
(1681614,58,17,1,5,'Ja kun ne päivät olivat kuluneet, laittoi kuningas kaikelle Suusanin linnan väelle, niin pienille kuin suurillekin, kuninkaan palatsin puutarhan esipihaan seitsenpäiväiset pidot.'),
(1681615,58,17,1,6,'Pellava-, puuvilla- ja punasiniverhoja oli kiinnitetty valkoisilla pellavanauhoilla ja purppuranpunaisilla nauhoilla hopeatankoihin ja valkomarmoripylväisiin. Kultaisia ja hopeaisia lepovuoteita oli pihalla, joka oli laskettu vihreällä ja valkoisella marmorilla, helmiäisellä ja kirjavalla marmorilla.'),
(1681616,58,17,1,7,'Juotavaa tarjottiin kulta-astioissa, ja astiat olivat erimuotoiset, ja kuninkaan viiniä oli viljalti, kuninkaalliseen tapaan.'),
(1681617,58,17,1,8,'Ja juomisessa oli lakina, ettei saanut olla mitään pakkoa, sillä niin oli kuningas käskenyt kaikkia hovimestareitansa, että oli tehtävä kunkin oman halun mukaan.'),
(1681618,58,17,1,9,'Myöskin kuningatar Vasti laittoi naisille pidot kuningas Ahasveroksen kuninkaalliseen palatsiin.'),
(1681619,58,17,1,10,'Seitsemäntenä päivänä, kun kuninkaan sydän oli viinistä iloinen, käski hän Mehumanin, Bistan, Harbonan, Bigtan, Abagtan, Seetarin ja Karkaan, niiden seitsemän hoviherran, jotka toimittivat palvelusta kuningas Ahasveroksen luona,'),
(1681620,58,17,1,11,'tuoda kuningatar Vastin, kuninkaallinen kruunu päässä, kuninkaan eteen, että hän saisi näyttää kansoille ja ruhtinaille hänen kauneutensa, sillä hän oli näöltään ihana.'),
(1681621,58,17,1,12,'Mutta kuningatar Vasti kieltäytyi tulemasta, vaikka kuningas hoviherrojen kautta oli käskenyt. Silloin kuningas suuttui kovin, ja hänessä syttyi viha.'),
(1681622,58,17,1,13,'Ja kuningas puhui viisaille, ajantietäjille - sillä näin oli tapana esittää kuninkaan sana kaikille lain ja oikeuden tuntijoille,'),
(1681623,58,17,1,14,'ja hänen lähimpänsä olivat Karsena, Seetar, Admata, Tarsis, Meres, Marsena ja Memukan, seitsemän Persian ja Meedian ruhtinasta, jotka näkivät kuninkaan kasvot ja istuivat valtakunnan ensimmäisinä -:'),
(1681624,58,17,1,15,'"Mitä on lain mukaan tehtävä kuningatar Vastille, koska hän ei ole noudattanut käskyä, jonka kuningas Ahasveros on antanut hoviherrojen kautta?"'),
(1681625,58,17,1,16,'Niin Memukan sanoi kuninkaan ja ruhtinasten edessä: "Kuningatar Vasti ei ole rikkonut ainoastaan kuningasta vastaan, vaan myös kaikkia ruhtinaita vastaan ja kaikkia kansoja vastaan kuningas Ahasveroksen kaikissa maakunnissa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681626,58,17,1,17,'Kun kuningattaren teko tulee kaikkien vaimojen tietoon, saattaa se heidät halveksimaan aviomiehiänsä, he kun voivat sanoa: ''Kuningas Ahasveros käski tuoda kuningatar Vastin eteensä, mutta tämä ei tullut''.'),
(1681627,58,17,1,18,'Jo tänä päivänä voivat Persian ja Meedian ruhtinattaret, jotka kuulevat kuningattaren teon, puhua siitä kaikille kuninkaan ruhtinaille, ja siitä tulee halveksimista ja suuttumusta riittämään asti.'),
(1681628,58,17,1,19,'Jos kuningas hyväksi näkee, julkaistakoon kuninkaallinen käsky ja kirjoitettakoon muuttumatonna Persian ja Meedian lakeihin, ettei Vasti enää saa tulla kuningas Ahasveroksen eteen ja että kuningas antaa hänen kuninkaallisen arvonsa toiselle, häntä paremmalle.'),
(1681629,58,17,1,20,'Kuninkaan antama säädös tulee tunnetuksi koko hänen valtakunnassansa, vaikka se onkin suuri, ja kaikki vaimot, niin suuret kuin pienetkin, antavat kunnian aviomiehillensä."'),
(1681630,58,17,1,21,'Tämä puhe miellytti kuningasta ja ruhtinaita, ja kuningas teki Memukanin sanan mukaan.'),
(1681631,58,17,1,22,'Hän lähetti kaikkiin kuninkaan maakuntiin - kuhunkin maakuntaan sen omalla kirjoituksella ja kullekin kansalle sen omalla kielellä - kirjeet, että joka mies olkoon herra talossaan ja saakoon puhua oman kansansa kieltä.'),
(1681632,58,17,2,1,'Näiden tapausten jälkeen, kun kuningas Ahasveroksen viha oli asettunut, muisti hän Vastia ja mitä tämä oli tehnyt ja mitä hänestä oli päätetty.'),
(1681633,58,17,2,2,'Niin kuninkaan palvelijat, jotka toimittivat hänelle palvelusta, sanoivat: "Etsittäköön kuninkaalle nuoria neitsyitä, näöltään ihania.'),
(1681634,58,17,2,3,'Ja asettakoon kuningas kaikkiin valtakuntansa maakuntiin käskyläiset keräämään kaikki nuoret neitsyet, näöltään ihanat, Suusanin linnaan, vaimolaan, Heegain, kuninkaan hoviherran ja vaimojen vartijan, huostaan, ja annettakoon heille heidän kauneudenhoitonsa.'),
(1681635,58,17,2,4,'Ja neitsyt, johon kuningas mieltyy, tulkoon kuningattareksi Vastin sijaan." Ja tämä puhe miellytti kuningasta, ja hän teki niin.'),
(1681636,58,17,2,5,'Suusanin linnassa oli juutalainen mies, nimeltä Mordokai, Jaairin poika, joka oli Siimein poika, joka Kiisin poika, benjaminilainen.'),
(1681637,58,17,2,6,'Hänet oli viety Jerusalemista pakkosiirtolaisuuteen niiden pakkosiirtolaisten joukossa, jotka vietiin samalla kuin Jekonja, Juudan kuningas, jonka Nebukadnessar, Baabelin kuningas, vei pakkosiirtolaisuuteen.'),
(1681638,58,17,2,7,'Hän oli setänsä tyttären Hadassan, se on Esterin, kasvatusisä, sillä tämä oli isätön ja äiditön. Tyttö oli vartaloltaan kaunis ja näöltään ihana, ja hänen isänsä ja äitinsä kuoltua oli Mordokai ottanut hänet tyttäreksensä.'),
(1681639,58,17,2,8,'Ja kun kuninkaan käsky ja laki tuli tunnetuksi ja kun kerättiin paljon tyttöjä Suusanin linnaan Heegain huostaan, otettiin Esterkin kuninkaan palatsiin Heegain, vaimojen vartijan, huostaan.'),
(1681640,58,17,2,9,'Tyttö miellytti häntä ja sai armon hänen edessään, ja hän antoi hänelle joutuin hänen kauneudenhoitonsa ja määrätyn ravinto-osansa sekä seitsemän valiopalvelijatarta kuninkaan palatsista ja siirsi hänet palvelijattarineen vaimolan parhaaseen paikkaan.'),
(1681641,58,17,2,10,'Ester ei ilmaissut kansaansa eikä syntyperäänsä, sillä Mordokai oli häntä kieltänyt sitä ilmaisemasta.'),
(1681642,58,17,2,11,'Mutta Mordokai käyskenteli joka päivä vaimolan esipihan edustalla saadakseen tietää, voiko Ester hyvin ja mitä hänelle tapahtui.'),
(1681643,58,17,2,12,'Kun jonkun tytön vuoro tuli mennä kuningas Ahasveroksen tykö, sittenkuin hänelle oli kaksitoista kuukautta tehty, niinkuin vaimoista oli määrätty - sillä niin pitkä aika kului heidän kauneudenhoitoonsa: kuusi kuukautta mirhaöljyllä, toiset kuusi kuukautta hajuaineilla sekä muilla naisten kauneudenhoitokeinoilla - meni tyttö kuninkaan tykö.'),
(1681644,58,17,2,13,'Kaikki, mitä hän pyysi, annettiin hänelle mukaan vaimolasta kuninkaan palatsiin.'),
(1681645,58,17,2,14,'Illalla hän meni, ja aamulla hän palasi toiseen vaimolaan kuninkaan hoviherran Saasgaan, sivuvaimojen vartijan, huostaan; ei hän enää mennyt kuninkaan tykö, paitsi jos kuningas oli häneen mieltynyt ja hänet nimeltään kutsuttiin.'),
(1681646,58,17,2,15,'Kun Esterille, Mordokain sedän Abihailin tyttärelle, jonka Mordokai oli ottanut tyttärekseen, tuli vuoro mennä kuninkaan tykö, ei hän halunnut mukaansa muuta, kuin mitä Heegai, kuninkaan hoviherra, vaimojen vartija, neuvoi. Ja Ester sai armon kaikkien niiden edessä, jotka näkivät hänet.'),
(1681647,58,17,2,16,'Ester vietiin kuningas Ahasveroksen tykö hänen kuninkaalliseen palatsiinsa kymmenennessä kuussa, se on teebet-kuussa, hänen seitsemäntenä hallitusvuotenansa.'),
(1681648,58,17,2,17,'Ja Ester tuli kuninkaalle kaikkia muita naisia rakkaammaksi ja sai hänen edessään armon ja suosion ennen kaikkia muita neitsyitä, niin että tämä pani kuninkaallisen kruunun hänen päähänsä ja teki hänet kuningattareksi Vastin sijaan.'),
(1681649,58,17,2,18,'Ja kuningas laittoi suuret pidot kaikille ruhtinailleen ja palvelijoilleen, pidot Esterin kunniaksi, ja myönsi maakunnille veronhuojennusta ja jakelutti lahjoja, kuninkaalliseen tapaan.'),
(1681650,58,17,2,19,'Kun neitsyitä koottiin toinen kerta ja Mordokai istuskeli kuninkaan portissa'),
(1681651,58,17,2,20,'- eikä Ester ollut ilmaissut syntyperäänsä eikä kansaansa, sillä Mordokai oli häntä siitä kieltänyt; Ester näet teki, mitä Mordokai käski, samoin kuin ollessaan hänen kasvattinansa -'),
(1681652,58,17,2,21,'niin siihen aikaan, Mordokain istuskellessa kuninkaan portissa, Bigtan ja Teres, kaksi kuninkaan hoviherraa, ovenvartijoita, suuttuivat ja etsivät tilaisuutta käydäkseen käsiksi kuningas Ahasverokseen.'),
(1681653,58,17,2,22,'Mutta se tuli Mordokain tietoon, ja hän ilmaisi sen kuningatar Esterille, ja Ester sanoi sen Mordokain nimessä kuninkaalle.'),
(1681654,58,17,2,23,'Ja asia tutkittiin, ja kun se havaittiin todeksi, ripustettiin ne molemmat hirsipuuhun. Ja se kirjoitettiin aikakirjaan kuningasta varten.'),
(1681655,58,17,3,1,'Näiden tapausten jälkeen kuningas Ahasveros korotti agagilaisen Haamanin, Hammedatan pojan, ylensi hänet ja antoi hänelle ylimmän sijan kaikkien ruhtinasten joukossa, jotka olivat hänen luonansa.'),
(1681656,58,17,3,2,'Ja kaikki kuninkaan palvelijat, jotka olivat kuninkaan portissa, polvistuivat ja heittäytyivät maahan Haamanin edessä, sillä niin oli kuningas käskenyt häntä kohdella. Mutta Mordokai ei polvistunut eikä heittäytynyt maahan.'),
(1681657,58,17,3,3,'Niin kuninkaan palvelijat, jotka olivat kuninkaan portissa, sanoivat Mordokaille: "Miksi sinä rikot kuninkaan käskyn?"'),
(1681658,58,17,3,4,'Ja kun he joka päivä sanoivat hänelle näin, mutta hän ei heitä totellut, ilmoittivat he tämän Haamanille, nähdäksensä, oliko Mordokain sanoma syy pätevä; sillä hän oli ilmoittanut heille olevansa juutalainen.'),
(1681659,58,17,3,5,'Kun Haaman näki, ettei Mordokai polvistunut eikä heittäytynyt maahan hänen edessään, tuli Haaman kiukkua täyteen.'),
(1681660,58,17,3,6,'Kun hänelle oli ilmoitettu, mitä kansaa Mordokai oli, vähäksyi hän käydä käsiksi yksin Mordokaihin: Haaman etsi tilaisuutta hävittääkseen kaikki juutalaiset, Mordokain kansan, Ahasveroksen koko valtakunnasta.'),
(1681661,58,17,3,7,'Ensimmäisessä kuussa, se on niisan-kuussa, kuningas Ahasveroksen kahdentenatoista vuotena, heitettiin Haamanin edessä puur''ia, se on arpaa, jokaisesta päivästä ja jokaisesta kuukaudesta, kahdenteentoista kuukauteen, se on adar-kuuhun, asti.'),
(1681662,58,17,3,8,'Ja Haaman sanoi kuningas Ahasverokselle: "On yksi kansa hajallaan ja erillään muiden kansojen seassa sinun valtakuntasi kaikissa maakunnissa. Heidän lakinsa ovat toisenlaiset kuin kaikkien muiden kansojen, he eivät noudata kuninkaan lakeja, eikä kuninkaan sovi jättää heitä rauhaan.'),
(1681663,58,17,3,9,'Jos kuningas hyväksi näkee, kirjoitettakoon määräys, että heidät on tuhottava; ja minä punnitsen kymmenentuhatta talenttia hopeata virkamiehille, vietäväksi kuninkaan aarrekammioihin."'),
(1681664,58,17,3,10,'Niin kuningas otti kädestään sinettisormuksensa ja antoi sen agagilaiselle Haamanille, Hammedatan pojalle, juutalaisten vastustajalle.'),
(1681665,58,17,3,11,'Ja kuningas sanoi Haamanille: "Hopea olkoon annettu sinulle, ja samoin se kansa, tehdäksesi sille, mitä hyväksi näet".'),
(1681666,58,17,3,12,'Niin kutsuttiin kuninkaan kirjurit ensimmäisessä kuussa, sen kolmantenatoista päivänä, ja kirjoitettiin, aivan niinkuin Haaman käski, määräys kuninkaan satraapeille ja jokaisen maakunnan käskynhaltijoille ja jokaisen kansan ruhtinaille, kuhunkin maakuntaan sen omalla kirjoituksella ja kullekin kansalle sen omalla kielellä. Kuningas Ahasveroksen nimessä se kirjoitettiin ja sinetöitiin kuninkaan sinettisormuksella.'),
(1681667,58,17,3,13,'Ja juoksijain mukana lähetettiin kaikkiin kuninkaan maakuntiin kirjeet, että oli hävitettävä, tapettava ja tuhottava kaikki juutalaiset, nuoret ja vanhat, lapset ja vaimot, samana päivänä, kahdennentoista kuun, se on adar-kuun, kolmantenatoista päivänä, ja että oli ryöstettävä, mitä heiltä oli saatavana saalista.'),
(1681668,58,17,3,14,'Kirjeen jäljennös oli julkaistava lakina jokaisessa maakunnassa, tiedoksi kaikille kansoille, että olisivat valmiit tuona päivänä.'),
(1681669,58,17,3,15,'Juoksijat lähtivät kuninkaan käskystä kiiruusti matkaan kohta, kun laki oli annettu Suusanin linnassa. Kuningas ja Haaman istuivat juomaan, mutta Suusanin kaupunki oli hämmästyksissään.'),
(1681670,58,17,4,1,'Kun Mordokai sai tietää kaiken, mitä oli tapahtunut, repäisi Mordokai vaatteensa, pukeutui säkkiin ja tuhkaan ja meni keskelle kaupunkia ja huuteli kovia ja katkeria valitushuutoja.'),
(1681671,58,17,4,2,'Ja hän meni kuninkaan portin edustalle asti, sillä sisälle kuninkaan porttiin ei saanut mennä säkkiin puettuna.'),
(1681672,58,17,4,3,'Jokaisessa maakunnassa, joka paikassa, mihin kuninkaan käsky ja hänen lakinsa tuli, syntyi juutalaisten keskuudessa suuri suru: paastottiin, itkettiin ja valitettiin; monet levittivät allensa säkin ja tuhkaa.'),
(1681673,58,17,4,4,'Kun Esterin palvelijattaret ja hänen hoviherransa tulivat ja kertoivat hänelle tämän, joutui kuningatar suureen tuskaan, ja hän lähetti vaatteita, että Mordokai puettaisiin niihin ja että hän riisuisi säkin yltään, mutta hän ei ottanut niitä vastaan.'),
(1681674,58,17,4,5,'Niin Ester kutsui Hatakin, joka oli kuninkaan hoviherroja ja jonka tämä oli asettanut häntä palvelemaan, ja käski hänet Mordokain luo, saadakseen tietää, mitä ja mistä syystä tämä kaikki oli.'),
(1681675,58,17,4,6,'Niin Hatak meni Mordokain luo kaupungin torille, joka on kuninkaan portin edustalla,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681676,58,17,4,7,'ja Mordokai ilmoitti hänelle kaikki, mitä hänelle oli tapahtunut, ja myös tarkalleen, kuinka paljon hopeata Haaman oli luvannut punnita kuninkaan aarrekammioihin juutalaisten tuhoamisesta.'),
(1681677,58,17,4,8,'Myös jäljennöksen sen lain sanamuodosta, joka Suusanissa oli annettu heidän hävittämisekseen, hän antoi hänelle, että hän näyttäisi sen Esterille ja ilmoittaisi tälle asian sekä velvoittaisi häntä menemään kuninkaan luo anomaan armoa ja rukoilemaan häntä kansansa puolesta.'),
(1681678,58,17,4,9,'Niin Hatak meni ja kertoi Esterille Mordokain sanat.'),
(1681679,58,17,4,10,'Mutta Ester puhui Hatakille ja käski hänen sanoa Mordokaille:'),
(1681680,58,17,4,11,'"Kaikki kuninkaan palvelijat ja kuninkaan maakuntien kansa tietävät, että kuka ikinä, mies tai nainen, kutsumatta menee kuninkaan luo sisempään esipihaan, on laki sama jokaiselle: hänet surmataan; ainoastaan se, jota kohti kuningas ojentaa kultavaltikkansa, jää eloon. Mutta minua ei ole kolmeenkymmeneen päivään kutsuttu tulemaan kuninkaan tykö."'),
(1681681,58,17,4,12,'Kun Mordokaille kerrottiin Esterin sanat,'),
(1681682,58,17,4,13,'käski Mordokai vastata Esterille: "Älä luulekaan, että sinä, kun olet kuninkaan linnassa, yksin kaikista juutalaisista pelastut.'),
(1681683,58,17,4,14,'Jos sinä tänä aikana olet vaiti, tulee apu ja pelastus juutalaisille muualta, mutta sinä ja sinun isäsi perhe tuhoudutte. Kuka tietää, etkö sinä juuri tällaista aikaa varten ole päässyt kuninkaalliseen arvoon?"'),
(1681684,58,17,4,15,'Niin Ester käski vastata Mordokaille:'),
(1681685,58,17,4,16,'"Mene ja kokoa kaikki Suusanin juutalaiset, ja paastotkaa minun puolestani; olkaa syömättä ja juomatta kolme vuorokautta, yöt ja päivät. Myös minä palvelijattarineni samoin paastoan. Sitten minä menen kuninkaan tykö, vaikka se on vastoin lakia; ja jos tuhoudun, niin tuhoudun."'),
(1681686,58,17,4,17,'Niin Mordokai meni ja teki, aivan niinkuin Ester oli häntä käskenyt.'),
(1681687,58,17,5,1,'Kolmantena päivänä Ester pukeutui kuninkaallisesti ja astui kuninkaan linnan sisempään esipihaan, vastapäätä kuninkaan linnaa; ja kuningas istui kuninkaallisella valtaistuimellaan kuninkaallisessa linnassa vastapäätä linnan ovea.'),
(1681688,58,17,5,2,'Kun kuningas näki kuningatar Esterin seisovan esipihassa, sai tämä armon hänen silmiensä edessä, ja kuningas ojensi Esteriä kohti kultavaltikan, joka hänellä oli kädessä. Ja Ester astui esiin ja kosketti valtikan päätä.'),
(1681689,58,17,5,3,'Kuningas sanoi hänelle: "Mikä sinun on, kuningatar Ester, ja mitä pyydät? Se sinulle annetaan, olkoon vaikka puoli valtakuntaa."'),
(1681690,58,17,5,4,'Niin Ester vastasi: "Jos kuningas hyväksi näkee, tulkoon kuningas ja myös Haaman tänä päivänä pitoihin, jotka minä olen hänelle laittanut".'),
(1681691,58,17,5,5,'Kuningas sanoi: "Noutakaa kiiruusti Haaman tehdäksemme Esterin toivomuksen mukaan". Ja kun kuningas ja Haaman olivat tulleet pitoihin, jotka Ester oli laittanut,'),
(1681692,58,17,5,6,'kysyi kuningas juominkien aikana Esteriltä: "Mitä pyydät? Se sinulle annetaan. Ja mitä haluat? Se täytetään, olkoon vaikka puoli valtakuntaa."'),
(1681693,58,17,5,7,'Niin Ester vastasi sanoen: "Tätä minä pyydän ja haluan:'),
(1681694,58,17,5,8,'jos olen saanut armon kuninkaan silmien edessä ja jos kuningas näkee hyväksi antaa minulle, mitä pyydän, ja täyttää, mitä haluan, niin tulkoot kuningas ja Haaman vielä pitoihin, jotka minä heille laitan; huomenna minä teen kuninkaan toivomuksen mukaan".'),
(1681695,58,17,5,9,'Haaman lähti sieltä sinä päivänä iloisena ja hyvillä mielin; ja kun Haaman näki Mordokain kuninkaan portissa eikä tämä noussut ylös eikä näyttänyt pelkäävän häntä, täytti viha Mordokaita kohtaan Haamanin.'),
(1681696,58,17,5,10,'Mutta Haaman hillitsi itsensä ja meni kotiinsa. Sitten hän lähetti noutamaan ystävänsä ja vaimonsa Sereksen.'),
(1681697,58,17,5,11,'Ja Haaman kehuskeli heille rikkautensa loistoa ja poikiensa paljoutta, ja kuinka kuningas kaikessa oli korottanut hänet ja ylentänyt hänet ylemmäksi ruhtinaita ja kuninkaan palvelijoita.'),
(1681698,58,17,5,12,'Ja Haaman sanoi: "Eipä kuningatar Esterkään antanut laittamiinsa pitoihin kuninkaan kanssa tulla kenenkään muun kuin minun. Ja huomiseksikin minä olen kuninkaan kanssa kutsuttu hänen luoksensa.'),
(1681699,58,17,5,13,'Mutta tämä kaikki ei minua tyydytä, niin kauan kuin minä näen juutalaisen Mordokain istuvan kuninkaan portissa."'),
(1681700,58,17,5,14,'Niin hänen vaimonsa Seres ja kaikki hänen ystävänsä sanoivat hänelle: "Tehtäköön hirsipuu, viittäkymmentä kyynärää korkea, ja pyydä huomenaamuna kuninkaalta, että Mordokai ripustetaan siihen, niin voit mennä kuninkaan kanssa pitoihin iloisena". Tämä puhe miellytti Haamania, ja hän teetti hirsipuun.'),
(1681701,58,17,6,1,'Sinä yönä uni pakeni kuningasta. Niin hän käski tuoda muistettavain tapahtumain kirjan, aikakirjan.'),
(1681702,58,17,6,2,'Ja kun sitä luettiin kuninkaalle, huomattiin kirjoitetun, kuinka Mordokai oli ilmaissut, että Bigtan ja Teres, kaksi kuninkaan hoviherraa, ovenvartijoita, oli etsinyt tilaisuutta käydäkseen käsiksi kuningas Ahasverokseen.'),
(1681703,58,17,6,3,'Niin kuningas kysyi: "Mitä kunniaa ja korotusta on Mordokai tästä saanut?" Kuninkaan palvelijat, jotka toimittivat hänelle palvelusta, vastasivat: "Ei hän ole saanut mitään".'),
(1681704,58,17,6,4,'Kuningas kysyi: "Kuka on esipihassa?" Mutta Haaman oli tullut kuninkaan palatsin ulompaan esipihaan pyytämään kuninkaalta, että Mordokai ripustettaisiin hirsipuuhun, jonka hän oli pystyttänyt Mordokain varalle.'),
(1681705,58,17,6,5,'Niin kuninkaan palvelijat vastasivat hänelle: "Katso, esipihassa seisoo Haaman".'),
(1681706,58,17,6,6,'Kuningas sanoi: "Tulkoon sisään". Kun Haaman oli tullut, kysyi kuningas häneltä: "Mitä on tehtävä miehelle, jota kuningas tahtoo kunnioittaa?" Niin Haaman ajatteli sydämessään: "Kenellepä muulle kuningas tahtoisi osoittaa kunniaa kuin minulle?"'),
(1681707,58,17,6,7,'Ja Haaman vastasi kuninkaalle: "Miehelle, jota kuningas tahtoo kunnioittaa,'),
(1681708,58,17,6,8,'tuotakoon kuninkaallinen puku, johon kuningas on ollut puettuna, ja hevonen, jolla kuningas on ratsastanut ja jonka päähän on pantu kuninkaallinen kruunu.'),
(1681709,58,17,6,9,'Puku ja hevonen annettakoon jollekin kuninkaan ruhtinaista, ylimyksistä. Puettakoon siihen mies, jota kuningas tahtoo kunnioittaa, ja kuljetettakoon häntä sen hevosen selässä kaupungin torilla ja huudettakoon hänen edellänsä: ''Näin tehdään miehelle, jota kuningas tahtoo kunnioittaa''."'),
(1681710,58,17,6,10,'Kuningas sanoi Haamanille: "Hae joutuin puku ja hevonen, niinkuin sanoit, ja tee näin juutalaiselle Mordokaille, joka istuu kuninkaan portissa. Älä jätä tekemättä mitään kaikesta, mitä olet puhunut."'),
(1681711,58,17,6,11,'Niin Haaman otti puvun ja hevosen, puki Mordokain ja kuljetti häntä hevosen selässä kaupungin torilla ja huusi hänen edellänsä: "Näin tehdään miehelle, jota kuningas tahtoo kunnioittaa".'),
(1681712,58,17,6,12,'Sitten Mordokai palasi takaisin kuninkaan porttiin, mutta Haaman kiiruhti kotiinsa murehtien ja pää peitettynä.'),
(1681713,58,17,6,13,'Kun Haaman kertoi vaimollensa Serekselle ja kaikille ystävilleen kaiken, mitä hänelle oli tapahtunut, sanoivat hänelle hänen viisaansa ja hänen vaimonsa Seres: "Jos Mordokai, jonka edessä olet alkanut kaatua, on syntyjään juutalainen, et sinä voi hänelle mitään, vaan kaadut hänen eteensä maahan asti".'),
(1681714,58,17,6,14,'Heidän vielä puhuessaan hänen kanssansa, tulivat kuninkaan hoviherrat ja veivät kiiruusti Haamanin pitoihin, jotka Ester oli laittanut.'),
(1681715,58,17,7,1,'Kun kuningas ja Haaman olivat tulleet kuningatar Esterin luo juomaan,'),
(1681716,58,17,7,2,'sanoi kuningas juominkien aikana Esterille nytkin, toisena päivänä: "Mitä pyydät, kuningatar Ester? Se sinulle annetaan. Ja mitä haluat? Se täytetään, olkoon vaikka puoli valtakuntaa."'),
(1681717,58,17,7,3,'Niin kuningatar Ester vastasi ja sanoi: "Jos olen saanut armon sinun silmiesi edessä, kuningas, ja jos kuningas hyväksi näkee, niin annettakoon minulle oma henkeni, kun sitä pyydän, ja kansani, kun sitä haluan.'),
(1681718,58,17,7,4,'Sillä meidät on myyty, minut ja kansani, hävitettäviksi, tapettaviksi ja tuhottaviksi. Jos meidät olisi myyty vain orjiksi ja orjattariksi, olisin siitä vaiti, sillä sen vaivan takia ei kannattaisi kuningasta vaivata."'),
(1681719,58,17,7,5,'Niin sanoi kuningas Ahasveros ja kysyi kuningatar Esteriltä: "Kuka se on, ja missä se on, joka on rohjennut tehdä sellaista?"'),
(1681720,58,17,7,6,'Ester vastasi: "Se vastustaja ja vihamies on tuo paha Haaman". Niin Haaman peljästyi kuningasta ja kuningatarta.'),
(1681721,58,17,7,7,'Kuningas nousi vihoissaan juomingeista ja meni linnan puutarhaan, mutta Haaman jäi siihen pyytääkseen henkeänsä kuningatar Esteriltä, sillä hän näki, että kuninkaalla oli paha mielessä häntä vastaan.'),
(1681722,58,17,7,8,'Kun kuningas tuli linnan puutarhasta takaisin linnaan, jossa juomingit olivat, oli Haaman juuri heittäytymässä lepovuoteelle, jolla kuningatar Ester lepäsi. Niin kuningas sanoi: "Vai tekee hän vielä väkivaltaa kuningattarelle linnassa, minun läsnäollessani!" Tuskin oli tämä sana päässyt kuninkaan suusta, kun jo Haamanin kasvot peitettiin.'),
(1681723,58,17,7,9,'Ja Harbona, yksi kuningasta palvelevista hoviherroista, sanoi: "Katso, seisoohan Haamanin talon edessä hirsipuu, viittäkymmentä kyynärää korkea, se, minkä Haaman on teettänyt Mordokain varalle, jonka puhe kerran koitui kuninkaan hyväksi". Kuningas sanoi: "Ripustakaa hänet siihen".'),
(1681724,58,17,7,10,'Niin ripustettiin Haaman hirsipuuhun, jonka hän oli pystyttänyt Mordokain varalle. Sitten kuninkaan viha asettui.'),
(1681725,58,17,8,1,'Sinä päivänä kuningas Ahasveros lahjoitti kuningatar Esterille Haamanin, juutalaisten vastustajan, talon. Ja Mordokai pääsi kuninkaan eteen, sillä Ester oli ilmoittanut, mikä Mordokai oli hänelle.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681726,58,17,8,2,'Ja kuningas otti kädestään sinettisormuksensa, jonka hän oli otattanut pois Haamanilta, ja antoi sen Mordokaille; ja Ester pani Mordokain Haamanin talon hoitajaksi.'),
(1681727,58,17,8,3,'Mutta Ester puhui vielä kuninkaan edessä ja lankesi hänen jalkainsa juureen, itki ja rukoili häntä torjumaan agagilaisen Haamanin pahuuden ja sen juonen, jonka tämä oli punonut juutalaisia vastaan.'),
(1681728,58,17,8,4,'Niin kuningas ojensi Esteriä kohti kultavaltikan, ja Ester nousi ja seisoi kuninkaan edessä.'),
(1681729,58,17,8,5,'Ja hän sanoi: "Jos kuningas hyväksi näkee ja jos minä olen saanut armon hänen edessänsä ja kuningas sen soveliaaksi katsoo ja minä olen hänen silmissänsä otollinen, niin kirjoitettakoon määräys ja peruutettakoon agagilaisen Haamanin, Hammedatan pojan, juoni, ne kirjeet, jotka hän kirjoitutti tuhotaksensa juutalaiset kaikissa kuninkaan maakunnissa.'),
(1681730,58,17,8,6,'Sillä kuinka minä jaksaisin nähdä kansaani kohtaavan onnettomuuden, kuinka jaksaisin nähdä sukuni surman!"'),
(1681731,58,17,8,7,'Niin kuningas Ahasveros sanoi kuningatar Esterille ja juutalaiselle Mordokaille: "Katso, Haamanin talon minä olen lahjoittanut Esterille, ja hän itse on ripustettu hirsipuuhun, koska hän oli käynyt käsiksi juutalaisiin.'),
(1681732,58,17,8,8,'Ja nyt kirjoittakaa kuninkaan nimessä sellainen juutalaisia koskeva määräys, kuin hyväksi näette, ja sinetöikää se kuninkaan sinettisormuksella; sillä kirjelmä, joka on kirjoitettu kuninkaan nimessä ja sinetöity kuninkaan sinettisormuksella, on peruuttamaton."'),
(1681733,58,17,8,9,'Niin kutsuttiin kuninkaan kirjurit silloin, kolmannessa kuussa, se on siivan-kuussa, sen kahdentenakymmenentenä kolmantena päivänä, ja kirjoitettiin, aivan niinkuin Mordokai käski, määräys juutalaisille sekä satraapeille, käskynhaltijoille ja maaherroille sataan kahteenkymmeneen seitsemään maakuntaan, Intiasta Etiopiaan saakka, kuhunkin maakuntaan sen omalla kirjoituksella ja kullekin kansalle sen omalla kielellä; myös juutalaisille heidän kirjoituksellaan ja kielellään.'),
(1681734,58,17,8,10,'Hän kirjoitutti kuningas Ahasveroksen nimessä ja sinetöi kuninkaan sinettisormuksella. Ja hän lähetti ratsulähettien mukana, jotka ratsastivat tammatarhoissa kasvatetuilla hovin hevosilla, kirjeet:'),
(1681735,58,17,8,11,'että kuningas sallii juutalaisten jokaisessa kaupungissa, missä heitä onkin, kokoontua puolustamaan henkeänsä hävittämällä, tappamalla ja tuhoamalla kansan ja maakunnan kaiken aseväen, joka heitä ahdistaa, sekä myös lapset ja vaimot, ja ryöstämään, mitä heiltä on saatavana saalista,'),
(1681736,58,17,8,12,'samana päivänä kaikissa kuningas Ahasveroksen maakunnissa, kahdennentoista kuun, se on adar-kuun, kolmantenatoista päivänä.'),
(1681737,58,17,8,13,'Kirjeen jäljennös oli julkaistava lakina jokaisessa maakunnassa, tiedoksi kaikille kansoille, ja että juutalaiset olisivat valmiit sinä päivänä kostamaan vihollisillensa.'),
(1681738,58,17,8,14,'Hovin hevosilla ratsastavat lähetit lähtivät kuninkaan käskystä kiiruusti ja nopeasti matkaan kohta, kun laki oli annettu Suusanin linnassa.'),
(1681739,58,17,8,15,'Mutta Mordokai lähti kuninkaan luota puettuna kuninkaalliseen punasiniseen purppuraan ja pellavapukuun, ja hänellä oli suuri kultakruunu ja viitta, tehty valkoisesta pellavakankaasta ja purppuranpunaisesta kankaasta. Ja Suusanin kaupunki riemuitsi ja oli iloissaan.'),
(1681740,58,17,8,16,'Juutalaisille oli tullut onni, ilo, riemu ja kunnia,'),
(1681741,58,17,8,17,'ja jokaisessa maakunnassa ja kaupungissa, joka paikassa, mihin kuninkaan käsky ja hänen lakinsa tuli, oli juutalaisilla ilo ja riemu, pidot ja juhlat. Ja paljon oli maan kansoista niitä, jotka kääntyivät juutalaisiksi, sillä kauhu juutalaisia kohtaan oli vallannut heidät.'),
(1681742,58,17,9,1,'Kahdennessatoista kuussa, se on adar-kuussa, sen kolmantenatoista päivänä, jona kuninkaan käsky ja hänen lakinsa oli toimeenpantava, sinä päivänä, jona juutalaisten viholliset olivat toivoneet saavansa heidät valtaansa, mutta jona päinvastoin juutalaiset saivat valtaansa vihamiehensä,'),
(1681743,58,17,9,2,'kokoontuivat juutalaiset kaupungeissansa kaikissa kuningas Ahasveroksen maakunnissa käydäkseen käsiksi niihin, jotka hankkivat heille onnettomuutta, eikä kukaan kestänyt heidän edessänsä, sillä kauhu heitä kohtaan oli vallannut kaikki kansat.'),
(1681744,58,17,9,3,'Ja kaikki maaherrat, satraapit ja käskynhaltijat ja kuninkaan virkamiehet kannattivat juutalaisia, sillä kauhu Mordokaita kohtaan oli vallannut heidät.'),
(1681745,58,17,9,4,'Sillä Mordokai oli mahtava kuninkaan palatsissa, ja hänen maineensa levisi kaikkiin maakuntiin, sillä se mies, Mordokai, tuli yhä mahtavammaksi.'),
(1681746,58,17,9,5,'Ja juutalaiset voittivat kaikki vihollisensa lyöden miekoilla, surmaten ja tuhoten, ja tekivät vihamiehillensä, mitä tahtoivat.'),
(1681747,58,17,9,6,'Suusanin linnassa juutalaiset tappoivat ja tuhosivat viisisataa miestä.'),
(1681748,58,17,9,7,'Ja Parsandatan, Dalfonin, Aspatan,'),
(1681749,58,17,9,8,'Pooratan, Adaljan, Aridatan,'),
(1681750,58,17,9,9,'Parmastan, Arisain, Aridain ja Vaisatan,'),
(1681751,58,17,9,10,'kymmenen Haamanin, Hammedatan pojan, juutalaisten vastustajan, poikaa, he tappoivat; mutta saaliiseen he eivät käyneet käsiksi.'),
(1681752,58,17,9,11,'Sinä päivänä tuli Suusanin linnassa tapettujen luku kuninkaan tietoon.'),
(1681753,58,17,9,12,'Ja kuningas sanoi kuningatar Esterille: "Suusanin linnassa juutalaiset ovat tappaneet ja tuhonneet viisisataa miestä ja Haamanin kymmenen poikaa; muissa kuninkaan maakunnissa mitä lienevätkään tehneet! Mitä nyt pyydät? Se sinulle annetaan. Ja mitä vielä haluat? Se täytetään."'),
(1681754,58,17,9,13,'Niin Ester sanoi: "Jos kuningas hyväksi näkee, sallittakoon Suusanin juutalaisten huomennakin tehdä saman lain mukaan kuin tänä päivänä. Ja ripustettakoon Haamanin kymmenen poikaa hirsipuuhun."'),
(1681755,58,17,9,14,'Kuningas käski tehdä niin. Ja siitä annettiin laki Suusanissa. Ja Haamanin kymmenen poikaa ripustettiin.'),
(1681756,58,17,9,15,'Ja Suusanin juutalaiset kokoontuivat myös adar-kuun neljäntenätoista päivänä ja tappoivat Suusanissa kolmesataa miestä; mutta saaliiseen he eivät käyneet käsiksi.'),
(1681757,58,17,9,16,'Myös muut juutalaiset, jotka olivat kuninkaan maakunnissa, olivat kokoontuneet puolustamaan henkeänsä ja päässeet rauhaan vihollisistansa, tapettuaan vihamiehiään seitsemänkymmentäviisi tuhatta - käymättä käsiksi saaliiseen -'),
(1681758,58,17,9,17,'adar-kuun kolmantenatoista päivänä; ja he lepäsivät sen kuun neljännentoista päivän viettäen sen pito- ja ilopäivänä.'),
(1681759,58,17,9,18,'Mutta Suusanin juutalaiset olivat kokoontuneet sen kuun kolmantenatoista ja neljäntenätoista päivänä, ja he lepäsivät sen kuun viidennentoista päivän viettäen sen pito- ja ilopäivänä.'),
(1681760,58,17,9,19,'Sentähden maaseudun juutalaiset, jotka asuvat maaseutukaupungeissa, viettävät adar-kuun neljännentoista päivän ilo-, pito- ja juhlapäivänä ja lähettävät toisilleen maistiaisia.'),
(1681761,58,17,9,20,'Ja Mordokai pani kirjaan nämä tapaukset. Ja hän lähetti kirjeet kaikille juutalaisille kuningas Ahasveroksen kaikkiin maakuntiin, lähellä ja kaukana oleville,'),
(1681762,58,17,9,21,'säätäen heille, että heidän oli vietettävä adar-kuun neljättätoista päivää ja saman kuun viidettätoista päivää joka vuosi,'),
(1681763,58,17,9,22,'koska juutalaiset niinä päivinä olivat päässeet rauhaan vihollisistansa ja heille siinä kuussa murhe oli kääntynyt iloksi ja suru juhlaksi - että heidän oli vietettävä ne päivät pito- ja ilopäivinä ja lähetettävä toisilleen maistiaisia ja köyhille lahjoja.'),
(1681764,58,17,9,23,'Ja juutalaiset ottivat pysyväksi tavaksi, mitä jo olivat alkaneet tehdä ja mitä Mordokai oli heille kirjoittanut.'),
(1681765,58,17,9,24,'Koska agagilainen Haaman, Hammedatan poika, kaikkien juutalaisten vastustaja, oli punonut juonen juutalaisia vastaan tuhotakseen heidät ja oli heittänyt puur''in, se on arvan, hävittääkseen ja tuhotakseen heidät,'),
(1681766,58,17,9,25,'ja koska sen tultua kuninkaan tietoon tämä oli kirjeellisesti määrännyt, että Haamanin pahan juonen, jonka hän oli punonut juutalaisia vastaan, tuli kääntyä hänen omaan päähänsä ja että hänet ja hänen poikansa oli ripustettava hirsipuuhun,'),
(1681767,58,17,9,26,'sentähden antoivat he näille päiville nimeksi puurim, puur-sanan mukaan. Sentähden, tuon käskykirjeen koko sisällyksen johdosta ja sen johdosta, mitä he itse olivat näin nähneet ja mitä heille oli tapahtunut,'),
(1681768,58,17,9,27,'juutalaiset säätivät ja ottivat itsellensä ja jälkeläisillensä ja kaikille heihin liittyville muuttumattomaksi ja pysyväksi tavaksi, että näitä kahta päivää oli vietettävä määräyksen mukaisesti ja määräaikana joka vuosi'),
(1681769,58,17,9,28,'ja että jokaisen sukupolven ja suvun oli näitä päiviä muistettava ja vietettävä joka maakunnassa ja kaupungissa sekä että näiden puurim-päivien tuli säilyä muuttumattomina juutalaisten keskuudessa eikä niiden muisto saanut hävitä heidän jälkeläisistänsä.'),
(1681770,58,17,9,29,'Ja kuningatar Ester, Abihailin tytär, ja juutalainen Mordokai kirjoittivat kaiken valtansa nojalla kirjoituksia saattaakseen säädöksenä voimaan tämän toisen puurim-käskykirjeen.'),
(1681771,58,17,9,30,'Mordokai lähetti kirjeet, ystävällisin ja vilpittömin sanoin, kaikille juutalaisille Ahasveroksen valtakunnan sataan kahteenkymmeneen seitsemään maakuntaan,'),
(1681772,58,17,9,31,'saattaakseen säädöksenä voimaan nämä puurim-päivät niiden määräaikoina, niinkuin juutalainen Mordokai ja kuningatar Ester olivat niistä säätäneet ja niinkuin juutalaiset itse olivat säätäneet itselleen ja jälkeläisilleen määräykset niihin kuuluvista paastoista ja valitushuudoista.'),
(1681773,58,17,9,32,'Näin säädettiin Esterin käskystä nämä puurim-määräykset ja kirjoitettiin kirjaan.'),
(1681774,58,17,10,1,'Kuningas Ahasveros saattoi työveron alaisiksi sekä mannermaan että merensaaret.'),
(1681775,58,17,10,2,'Ja kaikki hänen valta- ja urotyönsä ja kertomus Mordokain suuruudesta, johon kuningas hänet korotti, ne ovat kirjoitettuina Meedian ja Persian kuningasten aikakirjassa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681776,58,18,1,1,'Uusin maassa oli mies, jonka nimi oli Job. Tämä mies oli nuhteeton ja rehellinen, pelkäsi Jumalaa ja karttoi pahaa.'),
(1681777,58,18,1,2,'Hänelle syntyi seitsemän poikaa ja kolme tytärtä.'),
(1681778,58,18,1,3,'Ja karjaa hänellä oli seitsemäntuhatta lammasta, kolmetuhatta kamelia, viisisataa härkäparia ja viisisataa aasintammaa sekä ylen paljon palvelijoita. Tämä mies oli kaikista Idän miehistä mahtavin.'),
(1681779,58,18,1,4,'Hänen pojillansa oli tapana laittaa pitoja, kullakin oli pidot talossaan vuoropäivänänsä; he lähettivät silloin sanan ja kutsuivat kolme sisartansa syömään ja juomaan kanssansa.'),
(1681780,58,18,1,5,'Mutta kun pitopäivät olivat kiertonsa kiertäneet, lähetti Job sanan ja pyhitti heidät; hän nousi varhain aamulla ja uhrasi polttouhreja, yhtä monta kuin heitä oli. Sillä Job ajatteli: "Ehkä poikani ovat tehneet syntiä ja sydämessään luopuneet Jumalasta". Näin Job teki aina.'),
(1681781,58,18,1,6,'Mutta kun eräänä päivänä Jumalan pojat tulivat ja asettuivat Herran eteen, tuli myöskin saatana heidän joukossansa.'),
(1681782,58,18,1,7,'Niin Herra kysyi saatanalta: "Mistä sinä tulet?" Saatana vastasi Herralle ja sanoi: "Maata kiertämästä ja siellä kuljeksimasta".'),
(1681783,58,18,1,8,'Niin Herra sanoi saatanalle: "Oletko pannut merkille palvelijaani Jobia? Sillä ei ole maan päällä hänen vertaistansa; hän on nuhteeton ja rehellinen mies, pelkää Jumalaa ja karttaa pahaa."'),
(1681784,58,18,1,9,'Saatana vastasi Herralle ja sanoi: "Suottako Job pelkää Jumalaa?'),
(1681785,58,18,1,10,'Olethan itse kaikilta puolin suojannut hänet, hänen talonsa ja kaiken, mitä hänellä on; olet siunannut hänen kättensä työn, ja hänen karjalaumansa ovat levinneet ympäri maata.'),
(1681786,58,18,1,11,'Mutta ojennapa kätesi ja koske kaikkeen, mitä hänellä on: varmaan hän kiroaa sinua vasten kasvojasi."'),
(1681787,58,18,1,12,'Niin Herra sanoi saatanalle: "Katso, kaikki, mitä hänellä on, olkoon sinun käsissäsi; älä vain koske kädelläsi häneen itseensä". Ja saatana meni pois Herran edestä.'),
(1681788,58,18,1,13,'Kun sitten eräänä päivänä hänen poikansa ja tyttärensä söivät ja joivat viiniä vanhimman veljensä talossa,'),
(1681789,58,18,1,14,'tuli sanansaattaja Jobin luo ja sanoi: "Raavailla kynnettiin, ja aasintammat kävivät niiden vieressä laitumella;'),
(1681790,58,18,1,15,'niin sabalaiset hyökkäsivät ja ryöstivät ne ja surmasivat palvelijat miekan terällä. Vain minä yksin pelastuin kertomaan tämän sinulle."'),
(1681791,58,18,1,16,'Hänen vielä puhuessaan tuli toinen ja sanoi: "Jumalan tuli iski alas taivaasta, sytytti palamaan lampaat ja palvelijat ja kulutti heidät. Vain minä yksin pelastuin kertomaan tämän sinulle."'),
(1681792,58,18,1,17,'Hänen vielä puhuessaan tuli taas toinen ja sanoi: "Kaldealaiset asettuivat kolmeen joukkoon ja karkasivat kamelien kimppuun, ryöstivät ne ja surmasivat palvelijat miekan terällä. Vain minä yksin pelastuin kertomaan tämän sinulle."'),
(1681793,58,18,1,18,'Hänen vielä puhuessaan tuli taas toinen ja sanoi: "Poikasi ja tyttäresi söivät ja joivat viiniä vanhimman veljensä talossa;'),
(1681794,58,18,1,19,'katso, silloin suuri tuulispää tuli tuolta puolen erämaan ja iski talon neljään nurkkaan, ja se luhistui nuorukaisten päälle, niin että he kuolivat. Vain minä yksin pelastuin kertomaan tämän sinulle."'),
(1681795,58,18,1,20,'Silloin Job nousi, repäisi viittansa ja leikkasi hiuksensa, heittäytyi maahan ja rukoili.'),
(1681796,58,18,1,21,'Ja hän sanoi: "Alastonna minä tulin äitini kohdusta, ja alastonna minä sinne palajan. Herra antoi, ja Herra otti; kiitetty olkoon Herran nimi."'),
(1681797,58,18,1,22,'Kaikessa tässä Job ei tehnyt syntiä eikä puhunut nurjasti Jumalaa vastaan.'),
(1681798,58,18,2,1,'Ja kun eräänä päivänä Jumalan pojat tulivat ja asettuivat Herran eteen, tuli myöskin saatana heidän joukossansa ja asettui Herran eteen.'),
(1681799,58,18,2,2,'Niin Herra kysyi saatanalta: "Mistä sinä tulet?" Saatana vastasi Herralle ja sanoi: "Maata kiertämästä ja siellä kuljeksimasta".'),
(1681800,58,18,2,3,'Niin Herra sanoi saatanalle: "Oletko pannut merkille palvelijaani Jobia? Sillä ei ole maan päällä hänen vertaistansa; hän on nuhteeton ja rehellinen mies, pelkää Jumalaa ja karttaa pahaa. Vielä hän pysyy hurskaudessansa, ja sinä olet yllyttänyt minut häntä vastaan, tuhoamaan hänet syyttömästi."'),
(1681801,58,18,2,4,'Saatana vastasi Herralle ja sanoi: "Nahka nahasta; ja kaikki, mitä ihmisellä on, hän antaa hengestänsä.'),
(1681802,58,18,2,5,'Mutta ojennapa kätesi ja koske hänen luihinsa ja lihaansa: varmaan hän kiroaa sinua vasten kasvojasi."'),
(1681803,58,18,2,6,'Herra sanoi saatanalle: "Katso, hän olkoon sinun käsissäsi; säästä kuitenkin hänen henkensä".'),
(1681804,58,18,2,7,'Niin saatana meni pois Herran edestä ja löi Jobiin pahoja paiseita, kantapäästä kiireeseen asti.'),
(1681805,58,18,2,8,'Ja tämä otti saviastian sirun, sillä kaapiakseen itseänsä, ja istui tuhkaläjään.'),
(1681806,58,18,2,9,'Niin hänen vaimonsa sanoi hänelle: "Vieläkö pysyt hurskaudessasi? Kiroa Jumala ja kuole."'),
(1681807,58,18,2,10,'Mutta hän vastasi hänelle: "Sinä puhut niinkuin mikäkin houkka nainen. Otammehan vastaan Jumalalta hyvää, emmekö ottaisi vastaan pahaakin?" Kaikessa tässä Job ei tehnyt syntiä huulillansa.'),
(1681808,58,18,2,11,'Kun Jobin kolme ystävää kuuli kaiken onnettomuuden, joka häntä oli kohdannut, tulivat he kukin kotipaikastansa: teemanilainen Elifas, suuhilainen Bildad ja naemalainen Soofar; ja he sopivat keskenänsä ja menivät surkuttelemaan ja lohduttamaan häntä.'),
(1681809,58,18,2,12,'Mutta kun he jonkun matkan päässä nostivat silmänsä, eivät he enää voineet tuntea häntä; niin he korottivat äänensä ja itkivät, repäisivät kukin viittansa ja viskasivat tomua taivasta kohti päittensä päälle.'),
(1681810,58,18,2,13,'Sitten he istuivat hänen kanssaan maassa seitsemän päivää ja seitsemän yötä, eikä kukaan heistä puhunut sanaakaan hänelle, sillä he näkivät, että hänen tuskansa oli ylen suuri.'),
(1681811,58,18,3,1,'Senjälkeen Job avasi suunsa ja kirosi syntymäpäivänsä;'),
(1681812,58,18,3,2,'Job lausui ja sanoi:'),
(1681813,58,18,3,3,'"Kadotkoon se päivä, jona minä synnyin, ja se yö, joka sanoi: ''Poika on siinnyt''.'),
(1681814,58,18,3,4,'Se päivä muuttukoon pimeydeksi; älköön Jumala korkeudessa sitä kysykö, älköönkä valonsäde sille paistako.'),
(1681815,58,18,3,5,'Omistakoon sen pimeys ja pilkkopimeä, pilvi laskeutukoon sen päälle, peljästyttäkööt sitä päivänpimennykset.'),
(1681816,58,18,3,6,'Sen yön ryöstäköön pimeys; älköön se iloitko vuoden päivien parissa, älköön tulko kuukausien lukuun.'),
(1681817,58,18,3,7,'Katso, hedelmätön olkoon se yö, älköön siinä riemuhuuto raikuko.'),
(1681818,58,18,3,8,'Kirotkoot sen päivänmanaajat, ne, jotka saavat hereille Leviatanin.'),
(1681819,58,18,3,9,'Pimentykööt sen kointähdet, odottakoon se valoa, joka ei tule, älköön se aamuruskon silmäripsiä nähkö,'),
(1681820,58,18,3,10,'koska se ei sulkenut minulta kohdun ovia eikä kätkenyt vaivaa minun silmiltäni.'),
(1681821,58,18,3,11,'Miksi en kuollut heti äidin helmaan, miksi en menehtynyt kohdusta tullessani?'),
(1681822,58,18,3,12,'Miksi olivat minua vastaanottamassa polvet, minkätähden rinnat imeäkseni?'),
(1681823,58,18,3,13,'Sillä makaisinhan rauhassa silloin, nukkuisin ja saisin levätä'),
(1681824,58,18,3,14,'kuningasten ja maan neuvosmiesten kanssa, jotka ovat rakentaneet itselleen pyramiideja,'),
(1681825,58,18,3,15,'päämiesten kanssa, joilla on ollut kultaa, jotka ovat täyttäneet talonsa hopealla;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681826,58,18,3,16,'tahi olisin olematon niinkuin maahan kätketty keskoinen, niinkuin sikiöt, jotka eivät ole päivänvaloa nähneet.'),
(1681827,58,18,3,17,'Siellä lakkaavat jumalattomat raivoamasta, siellä saavat uupuneet levätä;'),
(1681828,58,18,3,18,'kaikki vangit ovat rauhassa, eivät kuule käskijän ääntä.'),
(1681829,58,18,3,19,'Yhtäläiset ovat siellä pieni ja suuri, orja on vapaa herrastansa.'),
(1681830,58,18,3,20,'Miksi hän antaa vaivatulle valoa ja elämää murhemielisille,'),
(1681831,58,18,3,21,'jotka odottavat kuolemaa, eikä se tule, jotka etsivät sitä enemmän kuin aarretta,'),
(1681832,58,18,3,22,'jotka iloitsisivat riemastuksiin asti, riemuitsisivat, jos löytäisivät haudan -'),
(1681833,58,18,3,23,'miehelle, jonka tie on ummessa, jonka Jumala on aitaukseen sulkenut?'),
(1681834,58,18,3,24,'Sillä huokaukseni on tullut minun leiväkseni, valitukseni valuu kuin vesi.'),
(1681835,58,18,3,25,'Sillä mitä minä kauhistuin, se minua kohtasi, ja mitä minä pelkäsin, se minulle tapahtui.'),
(1681836,58,18,3,26,'Ennenkuin tyynnyin, rauhan ja levon sain, tuli tuska jälleen."'),
(1681837,58,18,4,1,'Silloin teemanilainen Elifas lausui ja sanoi:'),
(1681838,58,18,4,2,'"Ethän pane pahaksesi, jos sinulle puhutaan? Kuka voi vaitikaan olla?'),
(1681839,58,18,4,3,'Katso, monta sinä olet ojentanut, ja hervonneita käsiä olet vahvistanut;'),
(1681840,58,18,4,4,'sanasi ovat nostaneet kompastunutta, ja rauenneita polvia olet voimistanut.'),
(1681841,58,18,4,5,'Mutta nyt, kun itseäsi kova kohtaa, sinä tuskastut, kun se sinuun sattuu, sinä kauhistut.'),
(1681842,58,18,4,6,'Eikö jumalanpelkosi ole sinun uskalluksesi ja nuhteeton vaelluksesi sinun toivosi?'),
(1681843,58,18,4,7,'Ajattele, kuka viaton on koskaan hukkunut, ja missä ovat rehelliset joutuneet perikatoon?'),
(1681844,58,18,4,8,'Minkä minä olen nähnyt, niin ne, jotka vääryyttä kyntävät ja turmiota kylvävät, ne sitä niittävätkin.'),
(1681845,58,18,4,9,'Jumalan henkäyksestä he hukkuvat, hänen vihansa hengestä he häviävät.'),
(1681846,58,18,4,10,'Leijonan ärjyntä, jalopeuran ääni vaiennetaan, ja nuorten leijonain hampaat murskataan;'),
(1681847,58,18,4,11,'jalopeura menehtyy saaliin puutteesta, ja naarasleijonan pennut hajaantuvat.'),
(1681848,58,18,4,12,'Ja minulle tuli salaa sana, korvani kuuli kuiskauksen,'),
(1681849,58,18,4,13,'kun ajatukset liikkuivat öisissä näyissä, kun raskas uni oli vallannut ihmiset.'),
(1681850,58,18,4,14,'Pelko ja vavistus yllättivät minut, peljästyttivät kaikki minun luuni.'),
(1681851,58,18,4,15,'Tuulen henkäys hiveli kasvojani, ihoni karvat nousivat pystyyn.'),
(1681852,58,18,4,16,'Siinä seisoi - sen näköä en erottanut - haamu minun silmäini edessä; minä kuulin kuiskaavan äänen:'),
(1681853,58,18,4,17,'''Onko ihminen vanhurskas Jumalan edessä, onko mies Luojansa edessä puhdas?'),
(1681854,58,18,4,18,'Katso, palvelijoihinsakaan hän ei luota, enkeleissäänkin hän havaitsee vikoja;'),
(1681855,58,18,4,19,'saati niissä, jotka savimajoissa asuvat, joiden perustus on maan tomussa! He rusentuvat kuin koiperhonen;'),
(1681856,58,18,4,20,'ennenkuin aamu ehtooksi muuttuu, heidät muserretaan. Kenenkään huomaamatta he hukkuvat ainiaaksi.'),
(1681857,58,18,4,21,'Eikö niin: heidän telttanuoransa irroitetaan, ja he kuolevat, viisaudesta osattomina.''"'),
(1681858,58,18,5,1,'"Huuda vain! Onko ketään, joka sinulle vastaisi, ja kenenkä pyhän puoleen kääntyisit?'),
(1681859,58,18,5,2,'Mielettömän tappaa suuttumus, tyhmän surmaa kiivaus.'),
(1681860,58,18,5,3,'Minä näin mielettömän juurtuvan, mutta äkkiä sain huutaa hänen asuinsijansa kirousta.'),
(1681861,58,18,5,4,'Hänen lapsensa ovat onnesta kaukana, heitä poljetaan portissa, eikä auttajaa ole.'),
(1681862,58,18,5,5,'Ja minkä he ovat leikanneet, syö nälkäinen - ottaa sen vaikka orjantappuroista - ja janoiset tavoittelevat heidän tavaraansa.'),
(1681863,58,18,5,6,'Sillä onnettomuus ei kasva tomusta, eikä vaiva verso maasta,'),
(1681864,58,18,5,7,'vaan ihminen syntyy vaivaan, ja kipinät, liekin lapset, lentävät korkealle.'),
(1681865,58,18,5,8,'Mutta minä ainakin etsisin Jumalaa ja asettaisin asiani Jumalan eteen,'),
(1681866,58,18,5,9,'hänen, joka tekee suuria, tutkimattomia tekoja, ihmeitä ilman määrää,'),
(1681867,58,18,5,10,'joka antaa sateen maan päälle ja lähettää vettä vainioille,'),
(1681868,58,18,5,11,'että hän korottaisi alhaiset ja surevaiset kohoaisivat onneen.'),
(1681869,58,18,5,12,'Hän tekee kavalain hankkeet tyhjiksi, niin ettei mikään menesty heidän kättensä alla,'),
(1681870,58,18,5,13,'hän vangitsee viisaat heidän viekkauteensa; ovelain juonet raukeavat:'),
(1681871,58,18,5,14,'päivällä he joutuvat pimeään ja hapuilevat keskipäivällä niinkuin yöllä.'),
(1681872,58,18,5,15,'Mutta köyhän hän pelastaa heidän suunsa miekasta, auttaa väkevän kädestä.'),
(1681873,58,18,5,16,'Ja niin on vaivaisella toivo, mutta vääryyden täytyy sulkea suunsa.'),
(1681874,58,18,5,17,'Katso, autuas se ihminen, jota Jumala rankaisee! Älä siis pidä halpana Kaikkivaltiaan kuritusta.'),
(1681875,58,18,5,18,'Sillä hän haavoittaa, ja hän sitoo; lyö murskaksi, mutta hänen kätensä myös parantavat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681876,58,18,5,19,'Kuudesta hädästä hän sinut pelastaa, ja seitsemässä ei onnettomuus sinua kohtaa.'),
(1681877,58,18,5,20,'Nälänhädässä hän vapahtaa sinut kuolemasta ja sodassa miekan terästä.'),
(1681878,58,18,5,21,'Kielen ruoskalta sinä olet turvassa, etkä pelkää, kun hävitys tulee.'),
(1681879,58,18,5,22,'Hävitykselle ja kalliille ajalle sinä naurat, etkä metsän petoja pelkää.'),
(1681880,58,18,5,23,'Sillä kedon kivien kanssa sinä olet liitossa, ja metsän pedot elävät rauhassa sinun kanssasi.'),
(1681881,58,18,5,24,'Saat huomata, että majasi on rauhoitettu, ja kun tarkastat asuinsijaasi, et sieltä mitään kaipaa.'),
(1681882,58,18,5,25,'Ja saat huomata, että sinun sukusi on suuri ja vesasi runsaat kuin ruoho maassa.'),
(1681883,58,18,5,26,'Ikäsi kypsyydessä sinä menet hautaan, niinkuin lyhde korjataan ajallansa.'),
(1681884,58,18,5,27,'Katso, tämän olemme tutkineet, ja niin se on; kuule se, ja ota sinäkin siitä vaari."'),
(1681885,58,18,6,1,'Job vastasi ja sanoi:'),
(1681886,58,18,6,2,'"Oi, jospa minun suruni punnittaisiin ja kova onneni pantaisiin sen kanssa vaakaan!'),
(1681887,58,18,6,3,'Sillä se on nyt raskaampi kuin meren hiekka; sentähden menevät sanani harhaan.'),
(1681888,58,18,6,4,'Sillä Kaikkivaltiaan nuolet ovat sattuneet minuun; minun henkeni juo niiden myrkkyä. Jumalan kauhut ahdistavat minua.'),
(1681889,58,18,6,5,'Huutaako villiaasi vihannassa ruohikossa, ammuuko härkä rehuviljansa ääressä?'),
(1681890,58,18,6,6,'Käykö äitelää syöminen ilman suolaa, tahi onko makua munanvalkuaisessa?'),
(1681891,58,18,6,7,'Sieluni ei tahdo koskea sellaiseen, se on minulle kuin saastainen ruoka.'),
(1681892,58,18,6,8,'Oi, jospa minun pyyntöni täyttyisi ja Jumala toteuttaisi minun toivoni!'),
(1681893,58,18,6,9,'Jospa Jumala suvaitsisi musertaa minut, ojentaa kätensä ja katkaista elämäni langan!'),
(1681894,58,18,6,10,'Niin olisi vielä lohdutuksenani - ja ilosta minä hypähtäisin säälimättömän tuskan alla - etten ole kieltänyt Pyhän sanoja.'),
(1681895,58,18,6,11,'Mikä on minun voimani, että enää toivoisin, ja mikä on loppuni, että tätä kärsisin?'),
(1681896,58,18,6,12,'Onko minun voimani vahva kuin kivi, onko minun ruumiini vaskea?'),
(1681897,58,18,6,13,'Eikö minulla ole enää mitään apua, onko pelastus minusta karkonnut?'),
(1681898,58,18,6,14,'Tuleehan ystävän olla laupias nääntyvälle, vaikka tämä olisikin hyljännyt Kaikkivaltiaan pelon.'),
(1681899,58,18,6,15,'Minun veljeni ovat petolliset niinkuin vesipuro, niinkuin sadepurot, jotka juoksevat kuiviin.'),
(1681900,58,18,6,16,'Ne ovat jääsohjusta sameat, niihin kätkeytyy lumi;'),
(1681901,58,18,6,17,'auringon paahtaessa ne ehtyvät, ne häviävät paikastansa helteen tullen.'),
(1681902,58,18,6,18,'Niiden juoksun urat mutkistuvat, ne haihtuvat tyhjiin ja katoavat.'),
(1681903,58,18,6,19,'Teeman karavaanit tähystelivät, Seban matkueet odottivat niitä;'),
(1681904,58,18,6,20,'he joutuivat häpeään, kun niihin luottivat, pettyivät perille tullessansa.'),
(1681905,58,18,6,21,'Niin te olette nyt tyhjän veroiset: te näette kauhun ja peljästytte.'),
(1681906,58,18,6,22,'Olenko sanonut: ''Antakaa minulle ja suorittakaa tavaroistanne lahjus minun puolestani,'),
(1681907,58,18,6,23,'pelastakaa minut vihollisen vallasta ja lunastakaa minut väkivaltaisten käsistä''?'),
(1681908,58,18,6,24,'Opettakaa minua, niin minä vaikenen; neuvokaa minulle, missä olen erehtynyt.'),
(1681909,58,18,6,25,'Kuinka tehoaakaan oikea puhe! Mutta mitä merkitsee teidän nuhtelunne?'),
(1681910,58,18,6,26,'Aiotteko nuhdella sanoja? Tuultahan ovat epätoivoisen sanat.'),
(1681911,58,18,6,27,'Orvostakin te heittäisitte arpaa ja hieroisitte kauppaa ystävästänne.'),
(1681912,58,18,6,28,'Mutta suvaitkaa nyt kääntyä minuun; minä totisesti en valhettele vasten kasvojanne.'),
(1681913,58,18,6,29,'Palatkaa, älköön vääryyttä tapahtuko; palatkaa, vielä minä olen oikeassa siinä.'),
(1681914,58,18,6,30,'Olisiko minun kielelläni vääryys? Eikö suulakeni tuntisi, mikä turmioksi on?"'),
(1681915,58,18,7,1,'"Eikö ihmisen olo maan päällä ole sotapalvelusta, eivätkö hänen päivänsä ole niinkuin palkkalaisen päivät?'),
(1681916,58,18,7,2,'Hän on orjan kaltainen, joka halajaa varjoon, ja niinkuin palkkalainen, joka odottaa palkkaansa.'),
(1681917,58,18,7,3,'Niin olen minä perinyt kurjuuden kuukaudet, ja vaivan yöt ovat minun osakseni tulleet.'),
(1681918,58,18,7,4,'Maata mennessäni minä ajattelen: Milloinka saan nousta? Ilta venyy, ja minä kyllästyn kääntelehtiessäni aamuhämärään asti.'),
(1681919,58,18,7,5,'Minun ruumiini verhoutuu matoihin ja tomukamaraan, minun ihoni kovettuu ja märkii.'),
(1681920,58,18,7,6,'Päiväni kiitävät nopeammin kuin sukkula, ne katoavat toivottomuudessa.'),
(1681921,58,18,7,7,'Muista, että minun elämäni on tuulen henkäys; minun silmäni ei enää saa onnea nähdä.'),
(1681922,58,18,7,8,'Ken minut näki, sen silmä ei minua enää näe; sinun silmäsi etsivät minua, mutta minua ei enää ole.'),
(1681923,58,18,7,9,'Pilvi häipyy ja menee menojaan; niin myös tuonelaan vaipunut ei sieltä nouse.'),
(1681924,58,18,7,10,'Ei hän enää palaja taloonsa, eikä hänen asuinpaikkansa häntä enää tunne.'),
(1681925,58,18,7,11,'Niin en minäkään hillitse suutani, minä puhun henkeni ahdistuksessa, minä valitan sieluni murheessa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681926,58,18,7,12,'Olenko minä meri tai lohikäärme, että asetat vartioston minua vastaan?'),
(1681927,58,18,7,13,'Kun ajattelen: leposijani lohduttaa minua, vuoteeni huojentaa minun tuskaani,'),
(1681928,58,18,7,14,'niin sinä kauhistutat minua unilla ja peljästytät minua näyillä.'),
(1681929,58,18,7,15,'Mieluummin tukehdun, mieluummin kuolen, kuin näin luurankona kidun.'),
(1681930,58,18,7,16,'Olen kyllästynyt, en tahdo elää iankaiken; anna minun olla rauhassa, sillä tuulen henkäystä ovat minun päiväni.'),
(1681931,58,18,7,17,'Mikä on ihminen, että hänestä niin suurta lukua pidät ja että kiinnität häneen huomiosi,'),
(1681932,58,18,7,18,'tarkastat häntä joka aamu, tutkit häntä joka hetki?'),
(1681933,58,18,7,19,'Etkö koskaan käännä pois katsettasi minusta, etkö hellitä minusta sen vertaa, että saan sylkeni nielaistuksi?'),
(1681934,58,18,7,20,'Jos olenkin syntiä tehnyt, niin mitä olen sillä sinulle tehnyt, sinä ihmisten vartioitsija? Minkätähden asetit minut maalitauluksesi, ja minkätähden tulin itselleni taakaksi?'),
(1681935,58,18,7,21,'Minkätähden et anna rikostani anteeksi etkä poista pahaa tekoani? Sillä nyt minä menen levolle maan tomuun, ja jos etsit minua, niin ei minua enää ole."'),
(1681936,58,18,8,1,'Sitten suuhilainen Bildad lausui ja sanoi:'),
(1681937,58,18,8,2,'"Kuinka kauan sinä senkaltaisia haastat ja suusi puheet ovat kuin raju myrsky?'),
(1681938,58,18,8,3,'Jumalako vääristäisi oikeuden, Kaikkivaltiasko vääristäisi vanhurskauden?'),
(1681939,58,18,8,4,'Jos lapsesi tekivät syntiä häntä vastaan, niin hän hylkäsi heidät heidän rikoksensa valtaan.'),
(1681940,58,18,8,5,'Jos sinä etsit Jumalaa ja anot Kaikkivaltiaalta armoa,'),
(1681941,58,18,8,6,'jos olet puhdas ja rehellinen, silloin hän varmasti heräjää sinun avuksesi ja asettaa entiselleen sinun vanhurskautesi asunnon.'),
(1681942,58,18,8,7,'Silloin sinun alkusi näyttää vähäiseltä, mutta loppuaikasi varttuu ylen suureksi.'),
(1681943,58,18,8,8,'Sillä kysypä aikaisemmalta sukupolvelta, tarkkaa, mitä heidän isänsä ovat tutkineet.'),
(1681944,58,18,8,9,'Mehän olemme eilispäivän lapsia emmekä mitään tiedä, päivämme ovat vain varjo maan päällä.'),
(1681945,58,18,8,10,'He sinua opettavat ja sanovat sinulle, tuovat ilmi sanat sydämestään:'),
(1681946,58,18,8,11,'''Kasvaako kaisla siinä, missä ei ole rämettä? rehottaako ruoko siinä, missä ei ole vettä?'),
(1681947,58,18,8,12,'Vielä vihreänä ollessaan, ennenaikaisena leikattavaksi, se kuivettuu ennen kuin mikään muu heinä.'),
(1681948,58,18,8,13,'Niin käy kaikkien niiden, jotka unhottavat Jumalan, ja jumalattoman toivo katoaa,'),
(1681949,58,18,8,14,'hänen, jonka uskallus on langan varassa, jonka turvana on hämähäkinverkko.'),
(1681950,58,18,8,15,'Hän nojaa taloonsa, mutta se ei seiso, hän tarttuu siihen, mutta se ei kestä.'),
(1681951,58,18,8,16,'Hän on rehevänä auringon paisteessa, ja hänen vesansa leviävät yli puutarhan.'),
(1681952,58,18,8,17,'Hänen juurensa kietoutuvat kiviroukkioon, hän kiinnittää katseensa kivitaloon.'),
(1681953,58,18,8,18,'Mutta kun Jumala hävittää hänet hänen paikastansa, niin se kieltää hänet: En ole sinua koskaan nähnyt.'),
(1681954,58,18,8,19,'Katso, siinä oli hänen vaelluksensa ilo, ja tomusta kasvaa toisia.'''),
(1681955,58,18,8,20,'Katso, Jumala ei hylkää nuhteetonta eikä tartu pahantekijäin käteen.'),
(1681956,58,18,8,21,'Vielä hän täyttää sinun suusi naurulla ja huulesi riemulla.'),
(1681957,58,18,8,22,'Sinun vihamiehesi verhotaan häpeällä, ja jumalattomien majaa ei enää ole."'),
(1681958,58,18,9,1,'Job vastasi ja sanoi:'),
(1681959,58,18,9,2,'"Totisesti minä tiedän, että niin on; kuinka voisi ihminen olla oikeassa Jumalaa vastaan!'),
(1681960,58,18,9,3,'Jos ihminen tahtoisi riidellä hänen kanssaan, ei hän voisi vastata hänelle yhteen tuhannesta.'),
(1681961,58,18,9,4,'Hän on viisas mieleltään ja väkevä voimaltaan kuka on niskoitellut häntä vastaan ja jäänyt rankaisematta?'),
(1681962,58,18,9,5,'Hän siirtää vuoret äkkiarvaamatta, hän kukistaa ne vihassansa;'),
(1681963,58,18,9,6,'hän järkyttää maan paikaltaan, ja sen patsaat vapisevat;'),
(1681964,58,18,9,7,'hän kieltää aurinkoa, ja se ei nouse, ja hän lukitsee tähdet sinetillään;'),
(1681965,58,18,9,8,'hän yksinänsä levittää taivaat ja tallaa meren kuohun kukkuloita;'),
(1681966,58,18,9,9,'hän loi Seulaset ja Kalevanmiekan, Otavan ja eteläiset tähtitarhat;'),
(1681967,58,18,9,10,'hän tekee suuria, tutkimattomia tekoja, ihmeitä ilman määrää.'),
(1681968,58,18,9,11,'Katso, hän käy ohitseni, enkä minä häntä näe; hän liitää ohi, enkä minä häntä huomaa.'),
(1681969,58,18,9,12,'Katso, hän tempaa saaliinsa, kuka voi häntä estää, kuka sanoa hänelle: ''Mitä sinä teet?'''),
(1681970,58,18,9,13,'Jumala ei taltu vihastansa; hänen allensa vaipuvat Rahabin auttajat.'),
(1681971,58,18,9,14,'Minäkö sitten voisin vastata hänelle, valita sanojani häntä vastaan?'),
(1681972,58,18,9,15,'Vaikka oikeassakin olisin, en saisi vastatuksi; minun täytyisi tuomariltani armoa anoa.'),
(1681973,58,18,9,16,'Jos minä huutaisin ja hän minulle vastaisikin, en usko, että hän ottaisi korviinsa huutoani,'),
(1681974,58,18,9,17,'hän, joka ajaa minua takaa myrskytuulessa ja lisää haavojeni lukua syyttömästi,'),
(1681975,58,18,9,18,'joka ei anna minun vetää henkeäni, vaan täyttää minut katkeralla tuskalla.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1681976,58,18,9,19,'Jos väkevän voimaa kysytään, niin hän sanoo: ''Tässä olen!'' mutta jos oikeutta, niin: ''Kuka vetää minut tilille?'''),
(1681977,58,18,9,20,'Vaikka olisin oikeassa, niin oma suuni tuomitsisi minut syylliseksi; vaikka olisin syytön, niin hän kuitenkin minut vääräksi tekisi.'),
(1681978,58,18,9,21,'Syytön minä olen. En välitä hengestäni, elämäni on minulle halpa.'),
(1681979,58,18,9,22,'Yhdentekevää kaikki; sentähden minä sanon: hän lopettaa niin syyttömän kuin syyllisenkin.'),
(1681980,58,18,9,23,'Jos ruoska äkkiä surmaa, niin hän pilkkaa viattomain epätoivoa.'),
(1681981,58,18,9,24,'Maa on jätetty jumalattoman valtaan, hän peittää sen tuomarien kasvot - ellei hän, kuka sitten?'),
(1681982,58,18,9,25,'Minun päiväni rientävät juoksijata nopeammin, pakenevat onnea näkemättä,'),
(1681983,58,18,9,26,'ne kiitävät pois niinkuin ruokovenheet, niinkuin kotka, joka iskee saaliiseen.'),
(1681984,58,18,9,27,'Jos ajattelen: tahdon unhottaa tuskani, muuttaa muotoni ja ilostua,'),
(1681985,58,18,9,28,'niin minä kauhistun kaikkia kipujani, tiedän, ettet julista minua viattomaksi.'),
(1681986,58,18,9,29,'Syyllisenä täytyy minun olla; miksi turhaan itseäni vaivaan?'),
(1681987,58,18,9,30,'Jos vaikka lumessa peseytyisin ja puhdistaisin käteni lipeällä,'),
(1681988,58,18,9,31,'silloinkin sinä upottaisit minut likakuoppaan, niin että omat vaatteeni minua inhoisivat.'),
(1681989,58,18,9,32,'Sillä ei ole hän ihminen niinkuin minä, voidakseni vastata hänelle ja käydäksemme oikeutta keskenämme.'),
(1681990,58,18,9,33,'Ei ole meillä riidanratkaisijaa, joka laskisi kätensä meidän molempien päälle'),
(1681991,58,18,9,34,'ja ottaisi hänen vitsansa pois minun päältäni, niin ettei hänen kauhunsa peljättäisi minua;'),
(1681992,58,18,9,35,'silloin minä puhuisin enkä häntä pelkäisi, sillä ei ole mitään sellaista tunnollani."'),
(1681993,58,18,10,1,'"Minun sieluni on kyllästynyt elämään; minä päästän valitukseni valloilleen ja puhun sieluni murheessa,'),
(1681994,58,18,10,2,'minä sanon Jumalalle: ''Älä tuomitse minua syylliseksi; ilmaise minulle, miksi vaadit minua tilille.'),
(1681995,58,18,10,3,'Onko sinulla hyötyä siitä, että teet väkivaltaa, että oman käsialasi hylkäät, mutta valaiset jumalattomain neuvoa?'),
(1681996,58,18,10,4,'Onko sinulla lihan silmät, katsotko, niinkuin ihminen katsoo?'),
(1681997,58,18,10,5,'Ovatko sinun päiväsi niinkuin ihmisen päivät, ovatko vuotesi niinkuin miehen vuodet,'),
(1681998,58,18,10,6,'koska etsit vääryyttä minusta ja tutkit minun syntiäni,'),
(1681999,58,18,10,7,'vaikka tiedät, etten ole syyllinen ja ettei ole ketään, joka sinun käsistäsi auttaa?'''),
(1682000,58,18,10,8,'Sinun kätesi ovat minut luoneet ja tehneet; yhtäkaikki minut perin juurin tuhoat.'),
(1682001,58,18,10,9,'Muista, että sinä olet muovaillut minut niinkuin saven, ja nyt muutat minut tomuksi jälleen.'),
(1682002,58,18,10,10,'Etkö sinä valanut minua niinkuin maitoa ja juoksuttanut niinkuin juustoa?'),
(1682003,58,18,10,11,'Sinä puetit minut nahalla ja lihalla ja kudoit minut luista ja jänteistä kokoon.'),
(1682004,58,18,10,12,'Elämän ja armon olet sinä minulle suonut, ja sinun huolenpitosi on varjellut minun henkeni.'),
(1682005,58,18,10,13,'Mutta sinä kätkit sydämeesi tämän; minä tiedän, että tämä oli sinun mielessäsi:'),
(1682006,58,18,10,14,'jos minä syntiä tein, niin sinä vartioitsit minua, ja minun rikostani et antanut anteeksi.'),
(1682007,58,18,10,15,'Jos olisin syyllinen, niin voi minua! Ja vaikka olisin oikeassa, en kuitenkaan voisi päätäni nostaa, häpeästä kylläisenä ja kurjuuttani katsellen.'),
(1682008,58,18,10,16,'Jos minun pääni nousee, niin sinä ajat minua niinkuin leijona ja teet yhä ihmeitäsi minua vastaan.'),
(1682009,58,18,10,17,'Sinä hankit yhä uusia todistajia minua vastaan, ja vihasi minuun kasvaa, ja sinä tuot vereksiä joukkoja minun kimppuuni.'),
(1682010,58,18,10,18,'Miksi toit minut ilmoille äitini kohdusta? Jospa olisin kuollut, ihmissilmän näkemätönnä!'),
(1682011,58,18,10,19,'Niin minä olisin, niinkuin minua ei olisi ollutkaan; minut olisi kannettu äidin kohdusta hautaan.'),
(1682012,58,18,10,20,'Ovathan päiväni vähissä; hän antakoon minun olla rauhassa, hän kääntyköön minusta pois, että hiukkasen ilostuisin,'),
(1682013,58,18,10,21,'ennenkuin lähden, ikinä palajamatta, pimeyden ja synkeyden maahan,'),
(1682014,58,18,10,22,'maahan, jonka pimeys on synkkä pilkkopimeä ja sekasorto ja jossa valkeneminenkin on pimeyttä."'),
(1682015,58,18,11,1,'Sitten naemalainen Soofar lausui ja sanoi:'),
(1682016,58,18,11,2,'"Jäisikö suulas puhe vastausta vaille, ja saisiko suupaltti olla oikeassa?'),
(1682017,58,18,11,3,'Saattaisivatko jaarituksesi miehet vaikenemaan, niin että saisit pilkata, kenenkään sinua häpeään häätämättä?'),
(1682018,58,18,11,4,'Sanoithan: ''Minun opetukseni on selkeä, ja minä olen puhdas sinun silmissäsi''.'),
(1682019,58,18,11,5,'Mutta jospa Jumala puhuisi ja avaisi huulensa sinua vastaan'),
(1682020,58,18,11,6,'ja ilmaisisi sinulle viisauden salaisuudet, että hänellä on ymmärrystä monin verroin! Silloin huomaisit, että Jumala on painanut unhoon montakin pahaa tekoasi.'),
(1682021,58,18,11,7,'Sinäkö käsittäisit Jumalan tutkimattomuuden tahi pääsisit Kaikkivaltiaan täydellisyydestä perille?'),
(1682022,58,18,11,8,'Se on korkea kuin taivas - mitä voit tehdä, syvempi kuin tuonela - mitä voit ymmärtää?'),
(1682023,58,18,11,9,'Se on pitempi kuin maa ja laveampi kuin meri.'),
(1682024,58,18,11,10,'Jos hän liitää paikalle ja vangitsee ja kutsuu oikeuden kokoon, niin kuka voi häntä estää?'),
(1682025,58,18,11,11,'Sillä hän tuntee valheen miehet, vääryyden hän näkee tarkkaamattakin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682026,58,18,11,12,'Onttopäinen mies voi viisastua ja villiaasin varsa ihmistyä.'),
(1682027,58,18,11,13,'Jos sinäkin valmistat sydämesi ja ojennat kätesi hänen puoleensa -'),
(1682028,58,18,11,14,'mutta jos kädessäsi on vääryys, heitä se kauas äläkä anna petoksen asua majoissasi -'),
(1682029,58,18,11,15,'silloin saat kohottaa kasvosi ilman häpeän tahraa, olet kuin vaskesta valettu etkä mitään pelkää.'),
(1682030,58,18,11,16,'Silloin unhotat onnettomuutesi, muistelet sitä kuin vettä, joka on virrannut pois.'),
(1682031,58,18,11,17,'Elämäsi selkenee kirkkaammaksi keskipäivää, pimeänkin aika on niinkuin aamunkoitto.'),
(1682032,58,18,11,18,'Silloin olet turvassa, sillä sinulla on toivo; tähystelet - käyt turvallisesti levolle,'),
(1682033,58,18,11,19,'asetut makaamaan, kenenkään peljättämättä, ja monet etsivät sinun suosiotasi.'),
(1682034,58,18,11,20,'Mutta jumalattomain silmät raukeavat; turvapaikka on heiltä mennyt, ja heidän toivonsa on huokaus."'),
(1682035,58,18,12,1,'Job vastasi ja sanoi:'),
(1682036,58,18,12,2,'"Totisesti, te yksin olette kansa, ja teidän mukananne kuolee viisaus!'),
(1682037,58,18,12,3,'Onhan minullakin ymmärrystä yhtä hyvin kuin teillä; en ole minä teitä huonompi, ja kuka ei moisia tietäisi?'),
(1682038,58,18,12,4,'Ystävänsä pilkkana on hän, jota Jumala kuuli, kun hän häntä huusi, hurskas, nuhteeton on pilkkana.'),
(1682039,58,18,12,5,'Turvassa olevan mielestä sopii onnettomuudelle ylenkatse; se on valmiina niille, joiden jalka horjuu.'),
(1682040,58,18,12,6,'Ja rauhassa ovat väkivaltaisten majat, turvassa ne, jotka ärsyttävät Jumalaa, ne, jotka kantavat jumalansa kourassaan." -'),
(1682041,58,18,12,7,'"Mutta kysypä eläimiltä, niin ne opettavat sinua, ja taivaan linnuilta, niin ne ilmoittavat sinulle;'),
(1682042,58,18,12,8,'tahi tutkistele maata, niin se opettaa sinua, ja meren kalat kertovat sinulle.'),
(1682043,58,18,12,9,'Kuka kaikista näistä ei tietäisi, että Herran käsi on tämän tehnyt,'),
(1682044,58,18,12,10,'hänen, jonka kädessä on kaiken elävän sielu ja kaikkien ihmisolentojen henki?" -'),
(1682045,58,18,12,11,'"Eikö korva koettele sanoja ja suulaki maista ruuan makua?"'),
(1682046,58,18,12,12,'"Vanhuksilla on viisautta, ja pitkä-ikäisillä ymmärrystä." -'),
(1682047,58,18,12,13,'"Jumalalla on viisaus ja voima, hänellä neuvo ja ymmärrys.'),
(1682048,58,18,12,14,'Jos hän repii maahan, niin ei rakenneta jälleen; kenen hän telkeää sisälle, sille ei avata.'),
(1682049,58,18,12,15,'Katso, hän salpaa vedet, ja syntyy kuivuus; hän laskee ne irti, ja ne mullistavat maan.'),
(1682050,58,18,12,16,'Hänen on väkevyys ja ymmärrys; hänen on niin eksynyt kuin eksyttäjäkin.'),
(1682051,58,18,12,17,'Hän vie neuvosmiehet pois paljaiksi riistettyinä ja tekee tuomarit tyhmiksi.'),
(1682052,58,18,12,18,'Kuningasten kurituksesta hän kirvoittaa ja köyttää köyden heidän omiin vyötäisiinsä.'),
(1682053,58,18,12,19,'Hän vie papit pois paljaiksi riistettyinä, ja ikimahtavat hän kukistaa.'),
(1682054,58,18,12,20,'Hän hämmentää luotettavain puheen ja ottaa pois vanhoilta taidon.'),
(1682055,58,18,12,21,'Hän vuodattaa ylenkatsetta ruhtinasten päälle ja aukaisee virtojen padot.'),
(1682056,58,18,12,22,'Hän paljastaa syvyydet pimeyden peitosta ja tuo valoon pilkkopimeän.'),
(1682057,58,18,12,23,'Hän korottaa kansat, ja hän hävittää ne, hän laajentaa kansakunnat, ja hän kuljettaa ne pois.'),
(1682058,58,18,12,24,'Maan kansan päämiehiltä hän ottaa ymmärryksen ja panee heidät harhailemaan tiettömissä autioissa.'),
(1682059,58,18,12,25,'He haparoivat pimeässä valoa vailla, ja hän panee heidät hoipertelemaan kuin juopuneet."'),
(1682060,58,18,13,1,'"Katso, kaikkea tätä on silmäni nähnyt, korvani kuullut ja sitä tarkannut.'),
(1682061,58,18,13,2,'Mitä te tiedätte, sen tiedän minäkin; en ole minä teitä huonompi.'),
(1682062,58,18,13,3,'Mutta minä mielin puhua Kaikkivaltiaalle, minä tahdon tuoda todistukseni Jumalaa vastaan.'),
(1682063,58,18,13,4,'Sillä te laastaroitte valheella, olette puoskareita kaikki tyynni.'),
(1682064,58,18,13,5,'Jospa edes osaisitte visusti vaieta, niin se olisi teille viisaudeksi luettava!'),
(1682065,58,18,13,6,'Kuulkaa siis, mitä minä todistan, ja tarkatkaa, mitä huuleni väittävät vastaan.'),
(1682066,58,18,13,7,'Tahdotteko puolustaa Jumalaa väärällä puheella ja puhua vilppiä hänen puolestaan;'),
(1682067,58,18,13,8,'tahdotteko olla puolueellisia hänen hyväksensä tahi ajaa Jumalan asiaa?'),
(1682068,58,18,13,9,'Koituuko siitä silloin hyvää, kun hän käy teitä tutkimaan; tahi voitteko pettää hänet, niinkuin ihminen petetään?'),
(1682069,58,18,13,10,'Hän teitä ankarasti rankaisee, jos salassa olette puolueellisia.'),
(1682070,58,18,13,11,'Eikö hänen korkeutensa peljästytä teitä ja hänen kauhunsa teitä valtaa?'),
(1682071,58,18,13,12,'Tuhkalauselmia ovat teidän mietelauseenne, savivarustuksia silloin teidän varustuksenne.'),
(1682072,58,18,13,13,'Vaietkaa, antakaa minun olla, niin minä puhun, käyköön minun miten tahansa.'),
(1682073,58,18,13,14,'Miksi minä otan lihani hampaisiini ja panen henkeni kämmenelleni?'),
(1682074,58,18,13,15,'Katso, hän surmaa minut, en minä enää mitään toivo; tahdon vain vaellustani puolustaa häntä vastaan.'),
(1682075,58,18,13,16,'Jo sekin on minulle voitoksi; sillä jumalaton ei voi käydä hänen kasvojensa eteen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682076,58,18,13,17,'Kuulkaa tarkasti minun puhettani, ja mitä minä lausun korvienne kuullen.'),
(1682077,58,18,13,18,'Katso, olen ryhtynyt käymään oikeutta; minä tiedän, että olen oikeassa.'),
(1682078,58,18,13,19,'Kuka saattaa käräjöidä minua vastaan? Silloin minä vaikenen ja kuolen.'),
(1682079,58,18,13,20,'Kahta vain älä minulle tee, niin en lymyä sinun kasvojesi edestä:'),
(1682080,58,18,13,21,'ota pois kätesi minun päältäni, ja älköön kauhusi minua peljättäkö;'),
(1682081,58,18,13,22,'sitten haasta, niin minä vastaan, tahi minä puhun, ja vastaa sinä minulle.'),
(1682082,58,18,13,23,'Mikä on minun pahain tekojeni ja syntieni luku? Ilmaise minulle rikkomukseni ja syntini.'),
(1682083,58,18,13,24,'Miksi peität kasvosi ja pidät minua vihollisenasi?'),
(1682084,58,18,13,25,'Lentävää lehteäkö peljätät, kuivunutta korttako vainoat,'),
(1682085,58,18,13,26,'koskapa määräät katkeruuden minun osakseni ja perinnökseni nuoruuteni pahat teot,'),
(1682086,58,18,13,27,'koska panet jalkani jalkapuuhun, vartioitset kaikkia minun polkujani ja piirrät rajan jalkapohjieni ääreen?" -'),
(1682087,58,18,13,28,'"Hän hajoaa kuin lahopuu, kuin koinsyömä vaate."'),
(1682088,58,18,14,1,'"Ihminen, vaimosta syntynyt, elää vähän aikaa ja on täynnä levottomuutta,'),
(1682089,58,18,14,2,'kasvaa kuin kukkanen ja lakastuu, pakenee kuin varjo eikä pysy.'),
(1682090,58,18,14,3,'Ja sellaista sinä pidät silmällä ja viet minut käymään oikeutta kanssasi!'),
(1682091,58,18,14,4,'Syntyisikö saastaisesta puhdasta? Ei yhden yhtäkään.'),
(1682092,58,18,14,5,'Hänen päivänsä ovat määrätyt, ja hänen kuukausiensa luku on sinun tiedossasi; sinä olet asettanut hänelle määrän, jonka ylitse hän ei pääse.'),
(1682093,58,18,14,6,'Niin käännä katseesi pois hänestä, että hän pääsisi rauhaan ja että hän saisi iloita niinkuin palkkalainen päivän päätettyään.'),
(1682094,58,18,14,7,'Onhan puullakin toivo: vaikka se maahan kaadetaan, kasvaa se uudelleen, eikä siltä vesaa puutu.'),
(1682095,58,18,14,8,'Vaikka sen juuri vanhenee maassa ja sen kanto kuolee multaan,'),
(1682096,58,18,14,9,'niin se veden tuoksusta versoo jälleen ja tekee oksia niinkuin istukas.'),
(1682097,58,18,14,10,'Mutta mies kun kuolee, makaa hän martaana; kun ihminen on henkensä heittänyt, missä hän on sitten?'),
(1682098,58,18,14,11,'Vesi juoksee pois järvestä, ja joki tyhjenee ja kuivuu;'),
(1682099,58,18,14,12,'niin ihminen lepoon mentyänsä ei enää nouse. Ennenkuin taivaat katoavat, eivät he heräjä eivätkä havahdu unestansa.'),
(1682100,58,18,14,13,'Oi, jospa kätkisit minut tuonelaan, piilottaisit minut, kunnes vihasi on asettunut, panisit minulle aikamäärän ja sitten muistaisit minua!'),
(1682101,58,18,14,14,'Kun mies kuolee, virkoaako hän jälleen henkiin? Minä vartoaisin kaikki sotapalvelukseni päivät, kunnes pääsyvuoroni joutuisi.'),
(1682102,58,18,14,15,'Sinä kutsuisit, ja minä vastaisin sinulle, sinä ikävöitsisit kättesi tekoa.'),
(1682103,58,18,14,16,'Silloin sinä laskisit minun askeleeni, et pitäisi vaaria minun synnistäni;'),
(1682104,58,18,14,17,'rikokseni olisi sinetillä lukittuna kukkaroon, ja pahat tekoni sinä peittäisit piiloon.'),
(1682105,58,18,14,18,'Mutta vuorikin vyöryy ja hajoaa, ja kallio siirtyy sijaltansa,'),
(1682106,58,18,14,19,'vesi kuluttaa kivet, ja rankkasade huuhtoo pois maan mullan; niin sinä hävität ihmisen toivon.'),
(1682107,58,18,14,20,'Sinä masennat hänet iäksi, ja hän lähtee; sinä muutat hänen muotonsa ja lähetät hänet menemään.'),
(1682108,58,18,14,21,'Kohoavatko hänen lapsensa kunniaan - ei hän sitä tiedä, vaipuvatko vähäisiksi - ei hän heitä huomaa.'),
(1682109,58,18,14,22,'Hän tuntee vain oman ruumiinsa kivun, vain oman sielunsa murheen."'),
(1682110,58,18,15,1,'Sitten teemanilainen Elifas lausui ja sanoi:'),
(1682111,58,18,15,2,'"Vastaako viisas tuulta pieksämällä, täyttääkö hän rintansa itätuulella?'),
(1682112,58,18,15,3,'Puolustautuuko hän puheella, joka ei auta, ja sanoilla, joista ei ole hyötyä?'),
(1682113,58,18,15,4,'Itse jumalanpelonkin sinä teet tyhjäksi ja rikot hartauden Jumalaa rukoilevilta.'),
(1682114,58,18,15,5,'Sillä sinun pahuutesi panee sanat suuhusi, ja sinä valitset viekasten kielen.'),
(1682115,58,18,15,6,'Oma suusi julistaa sinut syylliseksi, enkä minä; omat huulesi todistavat sinua vastaan.'),
(1682116,58,18,15,7,'Sinäkö synnyit ihmisistä ensimmäisenä, luotiinko sinut ennenkuin kukkulat?'),
(1682117,58,18,15,8,'Oletko sinä kuulijana Jumalan neuvottelussa ja anastatko viisauden itsellesi?'),
(1682118,58,18,15,9,'Mitä sinä tiedät, jota me emme tietäisi? Mitä sinä ymmärrät, jota me emme tuntisi?'),
(1682119,58,18,15,10,'Onpa meidänkin joukossamme harmaapää ja vanhus, isääsi iällisempi.'),
(1682120,58,18,15,11,'Vähäksytkö Jumalan lohdutuksia ja sanaa, joka sinua piteli hellävaroin?'),
(1682121,58,18,15,12,'Miksi sydämesi tempaa sinut mukaansa, miksi pyörivät silmäsi,'),
(1682122,58,18,15,13,'niin että käännät kiukkusi Jumalaa vastaan ja syydät suustasi sanoja?'),
(1682123,58,18,15,14,'Kuinka voisi ihminen olla puhdas, kuinka vaimosta syntynyt olla vanhurskas!'),
(1682124,58,18,15,15,'Katso, pyhiinsäkään hän ei luota, eivät taivaatkaan ole puhtaat hänen silmissänsä,'),
(1682125,58,18,15,16,'saati sitten ihminen, inhottava ja kelvoton, joka juo vääryyttä niinkuin vettä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682126,58,18,15,17,'Minä julistan sinulle, kuule minua, minä kerron, mitä olen nähnyt,'),
(1682127,58,18,15,18,'mitä viisaat ilmoittavat, salaamatta, mitä olivat isiltänsä saaneet,'),
(1682128,58,18,15,19,'niiltä, joille yksin maa oli annettuna ja joiden seassa ei muukalainen liikkunut:'),
(1682129,58,18,15,20,'''Jumalattomalla on tuska koko elämänsä ajan, ne vähät vuodet, jotka väkivaltaiselle on määrätty.'),
(1682130,58,18,15,21,'Kauhun äänet kuuluvat hänen korvissansa, keskellä rauhaakin hänet yllättää hävittäjä.'),
(1682131,58,18,15,22,'Ei usko hän pääsevänsä pimeydestä, ja hän on miekalle määrätty.'),
(1682132,58,18,15,23,'Hän harhailee leivän haussa: missä sitä on? Hän tuntee, että hänen vierellään on valmiina pimeyden päivä.'),
(1682133,58,18,15,24,'Tuska ja ahdistus kauhistuttavat häntä, masentavat hänet niinkuin kuningas valmiina hyökkäykseen.'),
(1682134,58,18,15,25,'Koska hän ojensi kätensä Jumalaa vastaan ja pöyhkeili Kaikkivaltiasta vastaan,'),
(1682135,58,18,15,26,'ryntäsi häntä vastaan niska jäykkänä, taajain kilvenkupurainsa suojassa;'),
(1682136,58,18,15,27,'koska hän kasvatti ihraa kasvoihinsa ja teki lanteensa lihaviksi,'),
(1682137,58,18,15,28,'asui hävitetyissä kaupungeissa, taloissa, joissa ei ollut lupa asua,'),
(1682138,58,18,15,29,'jotka olivat määrätyt jäämään raunioiksi, sentähden hän ei rikastu, eikä hänen omaisuutensa ole pysyväistä, eikä hänen viljansa notkistu maata kohden.'),
(1682139,58,18,15,30,'Ei hän pääse pimeydestä; tulen liekki kuivuttaa hänen vesansa, ja hän hukkuu hänen suunsa henkäyksestä.'),
(1682140,58,18,15,31,'Älköön hän turvatko turhuuteen - hän pettyy; sillä hänen voittonsa on oleva turhuus.'),
(1682141,58,18,15,32,'Mitta täyttyy ennen aikojaan, eikä hänen lehvänsä vihannoi.'),
(1682142,58,18,15,33,'Hän on niinkuin viinipuu, joka pudottaa raakaleensa, niinkuin öljypuu, joka varistaa kukkansa.'),
(1682143,58,18,15,34,'Sillä jumalattoman joukkio on hedelmätön, ja tuli kuluttaa lahjustenottajan majat.'),
(1682144,58,18,15,35,'He kantavat tuhoa ja synnyttävät turmiota, ja heidän kohtunsa valmistaa petosta.''"'),
(1682145,58,18,16,1,'Job vastasi ja sanoi:'),
(1682146,58,18,16,2,'"Tuonkaltaista olen kuullut paljon; kurjia lohduttajia olette kaikki.'),
(1682147,58,18,16,3,'Eikö tule jo loppu tuulen pieksämisestä, vai mikä yllyttää sinua vastaamaan?'),
(1682148,58,18,16,4,'Voisinhan minä myös puhua niinkuin tekin, jos te olisitte minun sijassani; voisin sommitella sanoja teitä vastaan ja ilkkuen nyökytellä teille päätäni,'),
(1682149,58,18,16,5,'rohkaista teitä suullani ja tuottaa huojennusta huulteni lohduttelulla.'),
(1682150,58,18,16,6,'Jos puhun, ei tuskani helpota, ja jos lakkaan, lähteekö se sillä?'),
(1682151,58,18,16,7,'Mutta nyt hän on minut uuvuttanut. Sinä olet hävittänyt koko minun joukkoni'),
(1682152,58,18,16,8,'ja olet minut kukistanut - siitä muka tuli todistaja - ja raihnauteni nousi minua vastaan, syyttäen minua vasten silmiä.'),
(1682153,58,18,16,9,'Hänen vihansa raateli ja vainosi minua, hän kiristeli minulle hampaitansa. Viholliseni hiovat katseitaan minua vastaan,'),
(1682154,58,18,16,10,'he avaavat minulle kitansa ja lyövät häväisten minua poskille; kaikki he yhtyvät minua vastaan.'),
(1682155,58,18,16,11,'Jumala jättää minut poikaheittiöiden valtaan ja syöksee minut jumalattomain käsiin.'),
(1682156,58,18,16,12,'Minä elin rauhassa, mutta hän peljätti minut, hän tarttui minua niskaan ja murskasi minut. Hän asetti minut maalitaulukseen;'),
(1682157,58,18,16,13,'hänen nuolensa viuhuvat minun ympärilläni. Hän halkaisee munuaiseni säälimättä, vuodattaa maahan minun sappeni.'),
(1682158,58,18,16,14,'Hän murtaa minuun aukon toisensa jälkeen ja ryntää kimppuuni kuin soturi.'),
(1682159,58,18,16,15,'Minä ompelin säkin iholleni ja painoin sarveni tomuun.'),
(1682160,58,18,16,16,'Minun kasvoni punoittavat itkusta, ja silmäluomillani on pimeys,'),
(1682161,58,18,16,17,'vaikkei ole vääryyttä minun käsissäni ja vaikka minun rukoukseni on puhdas.'),
(1682162,58,18,16,18,'Maa, älä peitä minun vertani, ja minun huudollani älköön olko lepopaikkaa!'),
(1682163,58,18,16,19,'Katso, nytkin on minun todistajani taivaassa ja puolustajani korkeudessa.'),
(1682164,58,18,16,20,'Ystäväni pitävät minua pilkkanansa - Jumalaan minun silmäni kyynelöiden katsoo,'),
(1682165,58,18,16,21,'että hän hankkisi miehelle oikeuden Jumalaa vastaan ja ihmislapselle hänen lähimmäistään vastaan.'),
(1682166,58,18,16,22,'Sillä vähän on vuosia edessäni enää, ja sitten menen tietä, jota en palaja."'),
(1682167,58,18,17,1,'"Minun henkeni on rikki raastettu, minun päiväni sammuvat, kalmisto on minun osani.'),
(1682168,58,18,17,2,'Totisesti, pilkka piirittää minua ja silmäni täytyy yhä katsella heidän ynseilyänsä.'),
(1682169,58,18,17,3,'Aseta puolestani pantti talteesi; kuka muu rupeaisi kättä lyöden minun takaajakseni?'),
(1682170,58,18,17,4,'Sillä sinä olet sulkenut ymmärrykseltä heidän sydämensä; sentähden sinä et päästä heitä voitolle.'),
(1682171,58,18,17,5,'Ystäviä kutsutaan osajaolle, mutta omilta lapsilta raukeavat silmät.'),
(1682172,58,18,17,6,'Minut on pantu kansoille sananlaskuksi; silmille syljettäväksi minä olen tullut.'),
(1682173,58,18,17,7,'Minun silmäni on hämärtynyt surusta, ja kaikki minun jäseneni ovat kuin varjo.'),
(1682174,58,18,17,8,'Tästä oikeamieliset hämmästyvät, ja viatonta kuohuttaa jumalattoman meno.'),
(1682175,58,18,17,9,'Mutta hurskas pysyy tiellänsä, ja se, jolla on puhtaat kädet, kasvaa voimassa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682176,58,18,17,10,'Mutta te kaikki, tulkaa jälleen tänne; en löydä minä viisasta joukostanne.'),
(1682177,58,18,17,11,'Päiväni ovat menneet, rauenneet ovat aivoitukseni, mitä sydämeni ikävöitsi.'),
(1682178,58,18,17,12,'Yön he tekevät päiväksi; valo muka lähenee pimeydestä.'),
(1682179,58,18,17,13,'Jos kuinka toivon, on tuonela asuntoni; minä levitän vuoteeni pimeyteen,'),
(1682180,58,18,17,14,'minä sanon haudalle: ''Sinä olet isäni'', ja madoille: ''Äitini ja sisareni''.'),
(1682181,58,18,17,15,'Missä on silloin minun toivoni, ja kuka saa minun toivoani katsella?'),
(1682182,58,18,17,16,'Ne astuvat alas tuonelan salpojen taa, kun yhdessä lepäämme tomussa."'),
(1682183,58,18,18,1,'Sitten suuhilainen Bildad lausui ja sanoi:'),
(1682184,58,18,18,2,'"Kuinka kauan te asetatte sanoille ansoja? Tulkaa järkiinne, sitten puhelemme.'),
(1682185,58,18,18,3,'Miksi meitä pidetään elukkain veroisina, olemmeko teidän silmissänne tylsät?'),
(1682186,58,18,18,4,'Sinä, joka raivossasi raatelet itseäsi - sinunko tähtesi jätettäisiin maa autioksi ja kallio siirtyisi sijaltansa?'),
(1682187,58,18,18,5,'Ei, jumalattomain valo sammuu, eikä hänen tulensa liekki loista.'),
(1682188,58,18,18,6,'Valo pimenee hänen majassansa, ja hänen lamppunsa sammuu hänen päänsä päältä.'),
(1682189,58,18,18,7,'Hänen väkevät askeleensa supistuvat ahtaalle, ja hänen oma neuvonsa kaataa hänet maahan.'),
(1682190,58,18,18,8,'Sillä hänen omat jalkansa vievät hänet verkkoon, hän käyskentelee katetun pyyntihaudan päällä.'),
(1682191,58,18,18,9,'Paula tarttuu hänen kantapäähänsä, ansa käy häneen kiinni;'),
(1682192,58,18,18,10,'hänelle on maahan kätketty pyydys, polulle häntä varten silmukka.'),
(1682193,58,18,18,11,'Kauhut peljättävät häntä kaikkialta ja ajavat häntä kintereillä kiitäen.'),
(1682194,58,18,18,12,'Nälkäiseksi käy hänen vaivansa, ja turmio vartoo hänen kaatumistaan.'),
(1682195,58,18,18,13,'Hänen ruumiinsa jäseniä kalvaa, hänen jäseniänsä kalvaa kuoleman esikoinen.'),
(1682196,58,18,18,14,'Hänet temmataan pois majastansa, turvastansa; hänet pannaan astumaan kauhujen kuninkaan tykö.'),
(1682197,58,18,18,15,'Hänen majassansa asuu outoja, hänen asuinpaikallensa sirotetaan tulikiveä.'),
(1682198,58,18,18,16,'Alhaalta kuivuvat hänen juurensa, ylhäältä kuihtuvat hänen oksansa.'),
(1682199,58,18,18,17,'Hänen muistonsa katoaa maasta, eikä hänen nimeänsä kadulla mainita.'),
(1682200,58,18,18,18,'Hänet sysätään valosta pimeyteen ja karkoitetaan maan piiristä.'),
(1682201,58,18,18,19,'Ei sukua, ei jälkeläistä ole hänellä kansansa seassa, eikä ketään jää jäljelle hänen asuntoihinsa.'),
(1682202,58,18,18,20,'Lännen asujat hämmästyvät hänen tuhopäiväänsä, idän asujat valtaa vavistus.'),
(1682203,58,18,18,21,'Näin käy väärintekijän huoneelle, näin sen asuinpaikalle, joka ei Jumalasta välitä."'),
(1682204,58,18,19,1,'Job vastasi ja sanoi:'),
(1682205,58,18,19,2,'"Kuinka kauan te vaivaatte minun sieluani ja runtelette minua sanoillanne?'),
(1682206,58,18,19,3,'Jo kymmenenkin kertaa olette minua häväisseet, häpeämättä te minua rääkkäätte.'),
(1682207,58,18,19,4,'Olenko todella hairahtunut, yöpyykö hairahdukseni minun luonani?'),
(1682208,58,18,19,5,'Tahi voitteko todella ylvästellä minua vastaan ja todistaa minun ansainneen häpeäni?'),
(1682209,58,18,19,6,'Tietäkää siis, että Jumala on tehnyt minulle vääryyttä ja on kietonut minut verkkoonsa.'),
(1682210,58,18,19,7,'Katso, minä huudan: ''Väkivaltaa!'' enkä saa vastausta; huudan apua, mutta ei ole mitään oikeutta.'),
(1682211,58,18,19,8,'Hän on aidannut tieni, niin etten pääse ylitse, ja on levittänyt pimeyden poluilleni.'),
(1682212,58,18,19,9,'Hän on riisunut minulta kunniani ja ottanut kruunun minun päästäni.'),
(1682213,58,18,19,10,'Hän repi minut maahan joka puolelta, niin että olen mennyttä, ja hän tempasi irti toivoni niinkuin puun.'),
(1682214,58,18,19,11,'Hän päästi vihansa syttymään minua vastaan ja piti minua vihollisenansa.'),
(1682215,58,18,19,12,'Hänen sotajoukkonsa tulivat yhdessä ja tekivät tiensä minua vastaan ja leiriytyivät minun majani ympärille.'),
(1682216,58,18,19,13,'Veljeni hän on minusta loitontanut; tuttavani ovat minusta aivan vieraantuneet.'),
(1682217,58,18,19,14,'Läheiseni ovat minusta luopuneet, ja uskottuni ovat unhottaneet minut.'),
(1682218,58,18,19,15,'Ne, jotka talossani majailevat, ja palvelijattareni pitävät minua muukalaisena, minä olen tullut vieraaksi heidän silmissään.'),
(1682219,58,18,19,16,'Minä kutsun palvelijaani, eikä hän vastaa; minun suuni täytyy nöyrästi rukoilla häntä.'),
(1682220,58,18,19,17,'Hengitykseni on vastenmielinen vaimolleni, hajuni on äitini pojista ilkeä.'),
(1682221,58,18,19,18,'Poikasetkin halveksivat minua; kun nousen, niin he puhuvat minusta pilkkojaan.'),
(1682222,58,18,19,19,'Kaikki seuratoverini inhoavat minua, ja ne, joita minä rakastin, ovat kääntyneet minua vastaan.'),
(1682223,58,18,19,20,'Luuni ovat tarttuneet nahkaani, ihooni, eikä minusta ole enää kuin ikenet jäljellä.'),
(1682224,58,18,19,21,'Armahtakaa minua, armahtakaa, te, minun ystäväni, sillä Jumalan käsi on minuun koskenut.'),
(1682225,58,18,19,22,'Miksi vainoatte minua niinkuin Jumala, ettekä saa kylläänne minun lihastani?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682226,58,18,19,23,'Oi, jospa minun sanani kirjoitettaisiin muistiin, jospa ne piirrettäisiin kirjaan,'),
(1682227,58,18,19,24,'rautataltalla ja lyijyllä hakattaisiin kallioon ikuisiksi ajoiksi!'),
(1682228,58,18,19,25,'Mutta minä tiedän lunastajani elävän, ja viimeisenä hän on seisova multien päällä.'),
(1682229,58,18,19,26,'Ja sittenkuin tämä nahka on yltäni raastettu ja olen ruumiistani irti, saan minä nähdä Jumalan.'),
(1682230,58,18,19,27,'Hänet olen minä näkevä apunani; minun silmäni saavat nähdä hänet - eikä vieraana. Munaskuuni hiukeavat sisimmässäni.'),
(1682231,58,18,19,28,'Kun sanotte: ''Kuinka vainoammekaan häntä!'' - minusta muka löydetään asian juuri -'),
(1682232,58,18,19,29,'niin peljätkää miekkaa, sillä viha on kohtaava miekanalaisia pahoja töitä, tietääksenne, että tuomari on."'),
(1682233,58,18,20,1,'Naemalainen Soofar lausui ja sanoi:'),
(1682234,58,18,20,2,'"Tuohon minun ajatukseni tuovat vastauksen, moisesta minun mieleni kuohuu.'),
(1682235,58,18,20,3,'Häpäisevää nuhdetta täytyy minun kuulla, mutta minun ymmärrykseni henki antaa minulle vastauksen.'),
(1682236,58,18,20,4,'Tuoko on sinulla tietoa ikiajoista asti, siitä saakka, kun ihminen maan päälle pantiin?'),
(1682237,58,18,20,5,'Ei, vaan jumalattomain riemu loppuu lyhyeen, ja riettaan ilo on vain silmänräpäys.'),
(1682238,58,18,20,6,'Vaikka hänen kopeutensa kohoaa taivaaseen ja hänen päänsä ulottuu pilviin asti,'),
(1682239,58,18,20,7,'katoaa hän kuitenkin ainiaaksi oman likansa lailla; jotka näkivät hänet, kysyivät: ''Missä hän on ?'''),
(1682240,58,18,20,8,'Niinkuin uni hän lentää pois, eikä häntä enää löydetä, ja hän häipyy kuin öinen näky.'),
(1682241,58,18,20,9,'Silmä, joka häntä katseli, ei katsele häntä enää, eikä hänen paikkansa häntä enää näe.'),
(1682242,58,18,20,10,'Hänen poikiensa täytyy hyvittää köyhät, hänen kättensä on annettava pois hänen omaisuutensa.'),
(1682243,58,18,20,11,'Nuoruuden voimaa olivat täynnä hänen luunsa, mutta sen täytyi mennä maata multaan hänen kanssansa.'),
(1682244,58,18,20,12,'Vaikka paha onkin makeaa hänen suussaan, niin että hän kätkee sen kielensä alle,'),
(1682245,58,18,20,13,'säästää sitä eikä siitä luovu, vaan pidättää sitä keskellä suulakeansa,'),
(1682246,58,18,20,14,'niin muuttuu tämä ruoka hänen sisässään, tulee kyykäärmeiden kähyiksi hänen sisälmyksissänsä.'),
(1682247,58,18,20,15,'Hän nieli rikkautta, ja hänen täytyy se oksentaa pois, Jumala ajaa sen ulos hänen vatsastansa.'),
(1682248,58,18,20,16,'Kyykäärmeiden myrkkyä hän imi, kyyn kieli hänet tappaa.'),
(1682249,58,18,20,17,'Ei hän saa ilokseen katsella puroja, ei hunaja- ja kermajokia ja -virtoja.'),
(1682250,58,18,20,18,'Hänen on annettava pois hankkimansa, eikä hän saa sitä itse niellä; ei ole hänen ilonsa hänen voittamansa rikkauden veroinen.'),
(1682251,58,18,20,19,'Sillä hän teki vaivaisille väkivaltaa ja heitti heidät siihen, hän ryösti itselleen talon, eikä saa siinä rakennella.'),
(1682252,58,18,20,20,'Sillä hän ei tuntenut vatsansa ikinä tyytyvän, mutta ei pelastu hän himotulla tavarallaan.'),
(1682253,58,18,20,21,'Ei mikään säilynyt hänen ahmailultaan, sentähden hänen onnensa ei kestä.'),
(1682254,58,18,20,22,'Yltäkylläisyytensä runsaudessa on hänellä hätä, häneen iskevät kaikki kurjien kourat.'),
(1682255,58,18,20,23,'Kun hän on täyttämässä vatsaansa, lähettää Jumala hänen kimppuunsa vihansa hehkun ja antaa sen sataa hänen päällensä hänen syödessään.'),
(1682256,58,18,20,24,'Jos hän pakenee rautavaruksia, niin lävistää hänet vaskijousi;'),
(1682257,58,18,20,25,'kun hän vetää ulos selästään nuolen, käy hänen sappensa lävitse miekan salama. Kauhut valtaavat hänet,'),
(1682258,58,18,20,26,'kaikki pimeys on varattu hänen aarteilleen. Hänet kuluttaa tuli, joka palaa lietsomatta, se syö, mitä on säilynyt hänen majassansa.'),
(1682259,58,18,20,27,'Taivas paljastaa hänen pahat tekonsa, maa nousee häntä vastaan.'),
(1682260,58,18,20,28,'Minkä hänen talonsa tuotti, menee menojaan vihan päivänä niinkuin tulvavedet.'),
(1682261,58,18,20,29,'Tämä on jumalattoman ihmisen osa Jumalalta, perintöosa, jonka Jumala hänelle määrää."'),
(1682262,58,18,21,1,'Job vastasi ja sanoi:'),
(1682263,58,18,21,2,'"Kuulkaa, kuulkaa minun sanojani ja suokaa minulle se lohdutus!'),
(1682264,58,18,21,3,'Kärsikää minua, että saan puhua. Kun olen puhunut, pilkatkaa sitten.'),
(1682265,58,18,21,4,'Ihmisiäkö vastaan minä valitan? Tahi kuinka en kävisi kärsimättömäksi?'),
(1682266,58,18,21,5,'Kääntykää minuun, niin tyrmistytte ja panette kätenne suullenne.'),
(1682267,58,18,21,6,'Kun käyn ajattelemaan, niin kauhistun, ja vavistus valtaa ruumiini:'),
(1682268,58,18,21,7,'Miksi jumalattomat saavat elää, vanheta, jopa voimassa vahvistua?'),
(1682269,58,18,21,8,'Heidän sukunsa on vankkana heidän edessään, heidän jälkeläisensä heidän silmäinsä alla.'),
(1682270,58,18,21,9,'Heidän kotinsa ovat rauhassa, kauhuista kaukana; ei satu heihin Jumalan vitsa.'),
(1682271,58,18,21,10,'Hänen sonninsa polkee eikä turhaan, hänen lehmänsä poikii eikä kesken.'),
(1682272,58,18,21,11,'Poikansa he laskevat ulos niinkuin lammaslauman, heidän lapsensa hyppelevät leikiten.'),
(1682273,58,18,21,12,'He virittävät laulujaan vaskirummun ja kanteleen kaikuessa ja iloitsevat huilun soidessa.'),
(1682274,58,18,21,13,'He viettävät päivänsä onnessa, mutta äkkiä heidät säikähytetään alas tuonelaan.'),
(1682275,58,18,21,14,'Ja kuitenkin he sanoivat Jumalalle: ''Mene pois meidän luotamme, sinun teistäsi emme tahdo tietää.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682276,58,18,21,15,'Mikä on Kaikkivaltias, että häntä palvelisimme? Ja mitä hyötyä meillä on siitä, että häntä rukoilemme?'''),
(1682277,58,18,21,16,'Katso, heidän onnensa ei ole heidän omassa kädessänsä. Jumalattomain neuvo olkoon minusta kaukana.'),
(1682278,58,18,21,17,'Kuinkapa usein jumalattomain lamppu sammuu ja heidät yllättää heidän turmionsa? Kuinkapa usein hän jakelee arpaosat vihassansa?'),
(1682279,58,18,21,18,'Ovatko he niinkuin tuulen vietävät oljet, niinkuin akanat, jotka tuulispää tempaa mukaansa?'),
(1682280,58,18,21,19,'Jumala muka säästää hänen lapsilleen hänen onnettomuutensa. Kostakoon hän hänelle itselleen, niin että hän sen tuntee.'),
(1682281,58,18,21,20,'Nähköön hän perikatonsa omin silmin, juokoon itse Kaikkivaltiaan vihan.'),
(1682282,58,18,21,21,'Sillä mitä hän välittää perheestänsä, jälkeensä jäävistä, kun hänen kuukausiensa luku on täysi!'),
(1682283,58,18,21,22,'Onko opetettava ymmärrystä Jumalalle, hänelle, joka taivaallisetkin tuomitsee?'),
(1682284,58,18,21,23,'Toinen kuolee täydessä onnessansa, kaikessa rauhassa ja levossa;'),
(1682285,58,18,21,24,'hänen astiansa ovat maitoa täynnä, ja hänen luunsa juotetaan ytimellä.'),
(1682286,58,18,21,25,'Toinen kuolee katkeralla mielellä, saamatta onnea maistaa.'),
(1682287,58,18,21,26,'Yhdessä he panevat maata multaan, ja madot peittävät heidät.'),
(1682288,58,18,21,27,'Katso, minä tunnen teidän ajatuksenne ja juonet, joilla mielitte sortaa minut.'),
(1682289,58,18,21,28,'Kun sanotte: ''Missä on nyt mahtimiehen talo, missä maja, jossa jumalattomat asuivat?'''),
(1682290,58,18,21,29,'niin ettekö ole kysyneet maita kulkeneilta? Ette voi kieltää, mitä he ovat todeksi nähneet,'),
(1682291,58,18,21,30,'että paha säästetään onnettomuuden päivältä, vihan päivältä hänet saatetaan suojaan.'),
(1682292,58,18,21,31,'Kuka puhuu hänelle vasten kasvoja hänen vaelluksestaan, kuka kostaa hänelle, mitä hän on tehnyt?'),
(1682293,58,18,21,32,'Hänet saatetaan kalmistoon, ja hänen hautakumpuansa vaalitaan.'),
(1682294,58,18,21,33,'Kepeät ovat hänelle laakson turpeet. Kaikki ihmiset seuraavat hänen jäljessänsä, niinkuin epälukuiset ovat kulkeneet hänen edellänsä.'),
(1682295,58,18,21,34,'Kuinka tuotte minulle niin turhaa lohdutusta? Entä vastauksenne - niistä jää pelkkä petollisuus jäljelle."'),
(1682296,58,18,22,1,'Teemanilainen Elifas lausui ja sanoi:'),
(1682297,58,18,22,2,'"Taitaako ihminen hyödyttää Jumalaa? Ei, vaan ainoastaan itseään hyödyttää ymmärtäväinen.'),
(1682298,58,18,22,3,'Onko Kaikkivaltiaalla etua siitä, jos olet vanhurskas, tahi voittoa siitä, jos vaellat nuhteetonna?'),
(1682299,58,18,22,4,'Jumalanpelostasiko hän sinua rankaisee ja käy kanssasi oikeutta?'),
(1682300,58,18,22,5,'Eikö pahuutesi ole suuri ja sinun pahat tekosi loppumattomat?'),
(1682301,58,18,22,6,'Sillä otithan veljiltäsi pantin syyttä ja riistit vaatteet alastomilta.'),
(1682302,58,18,22,7,'Et antanut nääntyvälle vettä juoda, ja nälkäiseltä kielsit leivän.'),
(1682303,58,18,22,8,'Kovakouraisen omaksi tuli maa, ja vain korkea-arvoinen sai siinä asua.'),
(1682304,58,18,22,9,'Lesket sinä lähetit luotasi tyhjin käsin, ja orpojen käsivarret murskattiin.'),
(1682305,58,18,22,10,'Sentähden paulat nyt sinua ympäröivät, ja äkillinen peljästys kauhistuttaa sinut -'),
(1682306,58,18,22,11,'vai etkö näe pimeyttä? - ja vesitulva peittää sinut.'),
(1682307,58,18,22,12,'Eikö Jumala ole korkea kuin taivas? Katso, kuinka korkealla on tähtien päälaki.'),
(1682308,58,18,22,13,'Ja niin sinä sanot: ''Mitäpä Jumala tietää? Voiko hän tuomita synkkäin pilvien takaa?'),
(1682309,58,18,22,14,'Pilvet ovat hänellä verhona, niin ettei hän näe; ja taivaanrannalla hän käyskentelee.'''),
(1682310,58,18,22,15,'Tahdotko seurata iänikuista polkua, jota pahantekijät vaelsivat,'),
(1682311,58,18,22,16,'ne, jotka kukistettiin ennen aikojaan ja joiden perustuksen virta huuhtoi pois,'),
(1682312,58,18,22,17,'jotka sanoivat Jumalalle: ''Poistu meistä. Mitä voisi Kaikkivaltias meille tehdä?'''),
(1682313,58,18,22,18,'Ja kuitenkin hän oli täyttänyt heidän talonsa hyvyydellä. Mutta minusta on kaukana jumalattomain neuvo.'),
(1682314,58,18,22,19,'Hurskaat näkevät sen ja iloitsevat, ja viaton pilkkaa heitä:'),
(1682315,58,18,22,20,'''Totisesti, vastustajamme ovat hävinneet, ja mitä heistä jäi, kulutti tuli''.'),
(1682316,58,18,22,21,'Tee siis sovinto ja elä rauhassa hänen kanssaan, niin saavutat onnen.'),
(1682317,58,18,22,22,'Ota opetusta hänen suustaan ja kätke hänen sanansa sydämeesi.'),
(1682318,58,18,22,23,'Kun palajat Kaikkivaltiaan tykö, niin tulet raketuksi, jos karkoitat vääryyden majastasi kauas,'),
(1682319,58,18,22,24,'viskaat kulta-aarteesi tomuun ja Oofirin kullan joen kivien joukkoon.'),
(1682320,58,18,22,25,'Jos Kaikkivaltias tulee sinun kulta-aarteeksesi, sinun hopeaharkoiksesi,'),
(1682321,58,18,22,26,'silloin on ilosi oleva Kaikkivaltiaassa, ja sinä nostat kasvosi Jumalan puoleen.'),
(1682322,58,18,22,27,'Kun rukoilet häntä, niin hän kuulee sinua, ja sinä saat täyttää lupauksesi.'),
(1682323,58,18,22,28,'Jos mitä päätät, niin se sinulle onnistuu, ja sinun teillesi loistaa valo.'),
(1682324,58,18,22,29,'Jos tie painuu alaspäin, niin sinä sanot: ''Ylös!'' ja hän auttaa nöyrtyväistä.'),
(1682325,58,18,22,30,'Hän pelastaa senkin, joka ei ole viaton; sinun kättesi puhtauden tähden hän pelastuu."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682326,58,18,23,1,'Job vastasi ja sanoi:'),
(1682327,58,18,23,2,'"Tänäänkin on valitukseni niskoittelua! Minun käteni on raskas huokaukseni tähden.'),
(1682328,58,18,23,3,'Oi, jospa tietäisin, kuinka löytää hänet, jospa pääsisin hänen asunnolleen!'),
(1682329,58,18,23,4,'Minä esittäisin hänelle riita-asian ja täyttäisin suuni todisteilla.'),
(1682330,58,18,23,5,'Tahtoisinpa tietää, mitä hän minulle vastaisi, ja kuulla, mitä hän minulle sanoisi.'),
(1682331,58,18,23,6,'Riitelisikö hän kanssani suurella voimallansa? Ei, hän vain tarkkaisi minua.'),
(1682332,58,18,23,7,'Silloin käräjöisi hänen kanssaan rehellinen mies, ja minä pelastuisin tuomaristani ainiaaksi.'),
(1682333,58,18,23,8,'Katso, minä menen itään, mutta ei ole hän siellä; menen länteen, enkä häntä huomaa;'),
(1682334,58,18,23,9,'jos hän pohjoisessa toimii, en häntä erota, jos hän kääntyy etelään, en häntä näe.'),
(1682335,58,18,23,10,'Sillä hän tietää, kussa minä kuljen. Jos hän tutkisi minut, kullan kaltaisena minä selviäisin.'),
(1682336,58,18,23,11,'Hänen askeleissaan on minun jalkani pysynyt, hänen tietänsä olen noudattanut siltä poikkeamatta.'),
(1682337,58,18,23,12,'Hänen huultensa käskystä en ole luopunut, hänen suunsa sanat minä olen kätkenyt tarkemmin kuin omat päätökseni.'),
(1682338,58,18,23,13,'Mutta hän pysyy samana, kuka voi häntä estää? Mitä hän tahtoo, sen hän tekee.'),
(1682339,58,18,23,14,'Niin, hän antaa täydellisesti minulle määrätyn osan, ja sellaista on hänellä vielä tallella paljon.'),
(1682340,58,18,23,15,'Sentähden valtaa minut kauhu hänen kasvojensa edessä; kun sitä ajattelen, peljästyn häntä.'),
(1682341,58,18,23,16,'Jumala on lannistanut minun rohkeuteni, Kaikkivaltias on minut kauhistuttanut.'),
(1682342,58,18,23,17,'Sillä en menehdy pimeän tähden, en oman itseni tähden, jonka pimeys peittää."'),
(1682343,58,18,24,1,'"Miksi ei Kaikkivaltias ole varannut tuomion aikoja, ja miksi eivät saa ne, jotka hänet tuntevat, nähdä hänen päiviänsä?'),
(1682344,58,18,24,2,'Jumalattomat siirtävät rajoja, ryöstävät laumoja ja laskevat ne laitumelle.'),
(1682345,58,18,24,3,'Orpojen aasin he vievät, ottavat pantiksi lesken lehmän.'),
(1682346,58,18,24,4,'He työntävät tieltä köyhät, kaikkien maan kurjain täytyy piileskellä.'),
(1682347,58,18,24,5,'Katso, nämä ovat kuin villiaasit erämaassa: lähtevät työhönsä saalista etsien, aro on heidän lastensa leipä.'),
(1682348,58,18,24,6,'Kedolta he korjaavat rehuviljaa ruuakseen, ja jumalattoman viinitarhasta he kärkkyvät tähteitä.'),
(1682349,58,18,24,7,'Alastomina, ilman vaatteita, he viettävät yönsä, eikä heillä ole peittoa kylmässä.'),
(1682350,58,18,24,8,'He ovat likomärkiä vuorilla vuotavasta sateesta, ja vailla suojaa he syleilevät kalliota.'),
(1682351,58,18,24,9,'Äidin rinnoilta riistetään orpo, ja kurjalta otetaan pantti.'),
(1682352,58,18,24,10,'He kuljeskelevat alastomina, ilman vaatteita, ja nälkäisinä he kantavat lyhteitä.'),
(1682353,58,18,24,11,'Jumalattomain muuritarhoissa he pusertavat öljyä, he polkevat viinikuurnaa ja ovat itse janoissansa.'),
(1682354,58,18,24,12,'Kaupungista kuuluu miesten voihkina, ja haavoitettujen sielu huutaa; mutta Jumala ei piittaa nurjuudesta.'),
(1682355,58,18,24,13,'Nuo ovat valon vihaajia, eivät tunne sen teitä eivätkä pysy sen poluilla.'),
(1682356,58,18,24,14,'Ennen päivän valkenemista nousee murhaaja, tappaa kurjan ja köyhän; ja yöllä hän hiipii kuin varas.'),
(1682357,58,18,24,15,'Avionrikkojan silmä tähyilee hämärää, hän arvelee: ''Ei yksikään silmä minua näe'', ja hän panee peiton kasvoillensa.'),
(1682358,58,18,24,16,'He murtautuvat pimeässä taloihin, päivällä he sulkeutuvat sisään, tahtomatta tietää valosta.'),
(1682359,58,18,24,17,'Sillä pimeys on heille kaikille aamun vertainen, koska pimeyden kauhut ovat heille tutut." -'),
(1682360,58,18,24,18,'"Hän kiitää pois vetten viemänä, kirottu on hänen peltopalstansa maassa, hän ei enää poikkea viinimäkien tielle.'),
(1682361,58,18,24,19,'Kuivuus ja kuumuus ahmaisevat lumiveden, samoin tuonela ne, jotka syntiä tekevät.'),
(1682362,58,18,24,20,'Äidin kohtu unhottaa hänet, madot syövät hänet herkkunaan, ei häntä enää muisteta; niin murskataan vääryys kuin puu.'),
(1682363,58,18,24,21,'Hän ryösti hedelmättömältä, joka ei synnytä, ja leskelle hän ei hyvää tehnyt." -'),
(1682364,58,18,24,22,'"Väkivaltaiset Jumala ylläpitää voimallansa; he pysyvät pystyssä, vaikka jo olivat epätoivossa hengestään.'),
(1682365,58,18,24,23,'Hän antaa heidän olla turvassa, ja heillä on vahva tuki; ja hänen silmänsä valvovat heidän teitänsä.'),
(1682366,58,18,24,24,'He ovat kohonneet korkealle - ei aikaakaan, niin ei heitä enää ole; he vaipuvat kokoon, kuolevat kuin kaikki muutkin, he taittuvat kuin vihneet tähkäpäästä.'),
(1682367,58,18,24,25,'Eikö ole niin? Kuka tekee minut valhettelijaksi ja saattaa sanani tyhjiksi?"'),
(1682368,58,18,25,1,'Sitten suuhilainen Bildad lausui ja sanoi:'),
(1682369,58,18,25,2,'"Valta ja peljättävyys on hänen, joka luo rauhaa korkeuksissaan.'),
(1682370,58,18,25,3,'Onko määrää hänen joukoillansa, ja kenelle ei hänen valonsa koita?'),
(1682371,58,18,25,4,'Kuinka siis ihminen olisi vanhurskas Jumalan edessä, ja kuinka vaimosta syntynyt olisi puhdas?'),
(1682372,58,18,25,5,'Katso, eipä kuukaan ole kirkas, eivät tähdetkään ole puhtaat hänen silmissänsä;'),
(1682373,58,18,25,6,'saati sitten ihminen, tuo mato, ja ihmislapsi, tuo toukka!"'),
(1682374,58,18,26,1,'Job vastasi ja sanoi:'),
(1682375,58,18,26,2,'"Kuinka oletkaan auttanut voimatonta, tukenut heikkoa käsivartta!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682376,58,18,26,3,'Kuinka oletkaan neuvonut taitamatonta ja ilmituonut paljon ymmärrystä!'),
(1682377,58,18,26,4,'Kenelle oikein olet puheesi pitänyt, ja kenen henki on sinusta käynyt?'),
(1682378,58,18,26,5,'Haamut alhaalla värisevät, vetten ja niiden asukasten alla.'),
(1682379,58,18,26,6,'Paljaana on tuonela hänen edessänsä, eikä ole manalalla peitettä.'),
(1682380,58,18,26,7,'Pohjoisen hän kaarruttaa autiuden ylle, ripustaa maan tyhjyyden päälle.'),
(1682381,58,18,26,8,'Hän sitoo vedet pilviinsä, eivätkä pilvet halkea niiden alla.'),
(1682382,58,18,26,9,'Hän peittää valtaistuimensa näkyvistä, levittää pilvensä sen ylitse.'),
(1682383,58,18,26,10,'Hän on vetänyt piirin vetten pinnalle, siihen missä valo päättyy pimeään.'),
(1682384,58,18,26,11,'Taivaan patsaat huojuvat ja hämmästyvät hänen nuhtelustaan.'),
(1682385,58,18,26,12,'Voimallansa hän kuohutti meren, ja taidollansa hän ruhjoi Rahabin.'),
(1682386,58,18,26,13,'Hänen henkäyksestään kirkastui taivas; hänen kätensä lävisti kiitävän lohikäärmeen.'),
(1682387,58,18,26,14,'Katso, nämä ovat ainoastaan hänen tekojensa äärten häämötystä, ja kuinka hiljainen onkaan kuiskaus, jonka hänestä kuulemme! Mutta kuka käsittää hänen väkevyytensä jylinän?"'),
(1682388,58,18,27,1,'Job jatkoi lausuen julki mietelmiään ja sanoi:'),
(1682389,58,18,27,2,'"Niin totta kuin Jumala elää, joka on ottanut minulta oikeuteni, ja Kaikkivaltias, joka on sieluni murehuttanut:'),
(1682390,58,18,27,3,'niin kauan kuin minussa vielä henkeä on ja Jumalan henkäystä sieramissani,'),
(1682391,58,18,27,4,'eivät minun huuleni puhu petosta, eikä kieleni vilppiä lausu.'),
(1682392,58,18,27,5,'Pois se! En myönnä teidän oikeassa olevan. Siihen asti kunnes henkeni heitän, en luovu hurskaudestani.'),
(1682393,58,18,27,6,'Minä pidän kiinni vanhurskaudestani, en hellitä; yhdestäkään elämäni päivästä omatuntoni ei minua soimaa.'),
(1682394,58,18,27,7,'Käyköön viholliseni niinkuin jumalattoman ja vastustajani niinkuin väärän.'),
(1682395,58,18,27,8,'Mitä toivoa on riettaalla, kun Jumala katkaisee hänen elämänsä, kun hän tempaa pois hänen sielunsa?'),
(1682396,58,18,27,9,'Kuuleeko Jumala hänen huutonsa, kun ahdistus häntä kohtaa?'),
(1682397,58,18,27,10,'Tahi saattaako hän iloita Kaikkivaltiaasta, huutaa Jumalaa joka aika?'),
(1682398,58,18,27,11,'Minä opetan teille, mitä tekee Jumalan käsi; en salaa, mitä Kaikkivaltiaalla on mielessä.'),
(1682399,58,18,27,12,'Katso, itse olette kaikki sen nähneet; miksi te turhia kuvittelette?'),
(1682400,58,18,27,13,'Tämä on jumalattoman ihmisen osa, Jumalan varaama, tämä on perintöosa, jonka väkivaltaiset Kaikkivaltiaalta saavat.'),
(1682401,58,18,27,14,'Jos hänellä on paljonkin lapsia, ovat ne miekan omia; eikä hänen jälkeläisillään ole leipää ravinnoksi.'),
(1682402,58,18,27,15,'Jotka häneltä jäävät, ne saattaa rutto hautaan, eivätkä hänen leskensä pidä itkiäisiä.'),
(1682403,58,18,27,16,'Jos hän kokoaa hopeata kuin multaa ja kasaa vaatteita kuin savea,'),
(1682404,58,18,27,17,'kasatkoon: vanhurskas pukee ne päällensä, ja viaton perii hopean.'),
(1682405,58,18,27,18,'Hän rakentaa talonsa niinkuin kointoukka, se on kuin suojus, jonka vartija kyhää.'),
(1682406,58,18,27,19,'Rikkaana hän menee levolle: ''Ei häviä mitään''; hän avaa silmänsä, ja kaikki on mennyttä.'),
(1682407,58,18,27,20,'Kauhut yllättävät hänet kuin tulvavedet, yöllä tempaa hänet mukaansa rajuilma.'),
(1682408,58,18,27,21,'Itätuuli vie hänet, niin että hän menee menojaan, ja puhaltaa hänet pois paikaltansa.'),
(1682409,58,18,27,22,'Jumala ampuu häneen nuolensa säälimättä; hänen täytyy paeta hänen kättänsä, minkä voi.'),
(1682410,58,18,27,23,'Silloin paukutetaan hänelle kämmeniä ja vihelletään hänelle hänen asuinpaikaltansa."'),
(1682411,58,18,28,1,'"Hopeallakin on suonensa ja löytöpaikkansa kullalla, joka puhdistetaan;'),
(1682412,58,18,28,2,'rauta otetaan maasta, ja kivestä sulatetaan vaski.'),
(1682413,58,18,28,3,'Tehdään loppu pimeydestä, ja tutkitaan tyystin kivi, jonka synkkä pilkkopimeä peittää.'),
(1682414,58,18,28,4,'Kaivos louhitaan syvälle maan asujain alle; unhotettuina he riippuvat siellä ilman jalan tukea, heiluvat kaukana ihmisten ilmoilta.'),
(1682415,58,18,28,5,'Maasta kasvaa leipä, mutta maan uumenet mullistetaan kuin tulen voimalla.'),
(1682416,58,18,28,6,'Sen kivissä on safiirilla sijansa, siellä on kultahiekkaa.'),
(1682417,58,18,28,7,'Polkua sinne ei tiedä kotka, eikä haukan silmä sitä havaitse.'),
(1682418,58,18,28,8,'Sitä eivät astu ylväät eläimet, ei leijona sitä kulje.'),
(1682419,58,18,28,9,'Siellä käydään käsiksi kovaan kiveen, ja vuoret mullistetaan juuriaan myöten.'),
(1682420,58,18,28,10,'Kallioihin murretaan käytäviä, ja silmä näkee kaikkinaiset kalleudet.'),
(1682421,58,18,28,11,'Vesisuonet estetään tihkumasta, ja salatut saatetaan päivänvaloon.'),
(1682422,58,18,28,12,'Mutta viisaus - mistä se löytyy, ja missä on ymmärryksen asuinpaikka?'),
(1682423,58,18,28,13,'Ei tunne ihminen sille vertaa, eikä sitä löydy elävien maasta.'),
(1682424,58,18,28,14,'Syvyys sanoo: ''Ei ole se minussa'', ja meri sanoo: ''Ei se ole minunkaan tykönäni''.'),
(1682425,58,18,28,15,'Sitä ei voida ostaa puhtaalla kullalla, eikä sen hintaa punnita hopeassa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682426,58,18,28,16,'Ei korvaa sitä Oofirin kulta, ei kallis onyks-kivi eikä safiiri.'),
(1682427,58,18,28,17,'Ei vedä sille vertoja kulta eikä lasi, eivät riitä sen vaihtohinnaksi aitokultaiset kalut.'),
(1682428,58,18,28,18,'Koralleja ja kristalleja ei sen rinnalla mainita, ja viisauden omistaminen on helmiä kalliimpi.'),
(1682429,58,18,28,19,'Ei vedä sille vertoja Etiopian topaasi, ei korvaa sitä puhdas kulta.'),
(1682430,58,18,28,20,'Mistä siis tulee viisaus ja missä on ymmärryksen asuinpaikka?'),
(1682431,58,18,28,21,'Se on peitetty kaiken elävän silmiltä, salattu taivaan linnuiltakin.'),
(1682432,58,18,28,22,'Manala ja kuolema sanovat: ''Korvamme ovat kuulleet siitä vain kerrottavan''.'),
(1682433,58,18,28,23,'Jumala tietää tien sen luokse, hän tuntee sen asuinpaikan.'),
(1682434,58,18,28,24,'Sillä hän katsoo maan ääriin saakka, hän näkee kaiken, mitä taivaan alla on.'),
(1682435,58,18,28,25,'Kun hän antoi tuulelle voiman ja määräsi mitalla vedet,'),
(1682436,58,18,28,26,'kun hän sääti lain sateelle ja ukkospilvelle tien,'),
(1682437,58,18,28,27,'silloin hän sen näki ja ilmoitti, toi sen esille ja sen myös tutki.'),
(1682438,58,18,28,28,'Ja ihmiselle hän sanoi: ''Katso, Herran pelko - se on viisautta, ja pahan karttaminen on ymmärrystä''."'),
(1682439,58,18,29,1,'Job jatkoi lausuen mietelmiään ja sanoi:'),
(1682440,58,18,29,2,'"Oi, jospa olisin, niinkuin olin ammoin kuluneina kuukausina, niinkuin niinä päivinä, joina Jumala minua varjeli,'),
(1682441,58,18,29,3,'jolloin hänen lamppunsa loisti pääni päällä ja minä hänen valossansa vaelsin pimeyden halki!'),
(1682442,58,18,29,4,'Jospa olisin niinkuin kukoistukseni päivinä, jolloin Jumalan ystävyys oli majani yllä,'),
(1682443,58,18,29,5,'jolloin Kaikkivaltias oli vielä minun kanssani ja poikani minua ympäröivät,'),
(1682444,58,18,29,6,'jolloin askeleeni kylpivät kermassa ja kallio minun vierelläni vuoti öljyvirtoja!'),
(1682445,58,18,29,7,'Kun menin kaupunkiin porttiaukealle, kun asetin istuimeni torille,'),
(1682446,58,18,29,8,'niin nuorukaiset väistyivät nähdessään minut, vanhukset nousivat ja jäivät seisomaan,'),
(1682447,58,18,29,9,'päämiehet lakkasivat puhumasta ja panivat kätensä suulleen.'),
(1682448,58,18,29,10,'Ruhtinasten ääni vaikeni, ja heidän kielensä tarttui suulakeen.'),
(1682449,58,18,29,11,'Sillä kenen korva minusta kuuli, hän ylisti minua onnelliseksi, kenen silmä minut näki, hän minusta todisti;'),
(1682450,58,18,29,12,'minä näet pelastin kurjan, joka apua huusi, ja orvon, jolla ei auttajaa ollut.'),
(1682451,58,18,29,13,'Menehtyväisen siunaus tuli minun osakseni, ja lesken sydämen minä saatoin riemuitsemaan.'),
(1682452,58,18,29,14,'Vanhurskaudella minä vaatetin itseni, ja se verhosi minut; oikeus oli minulla viittana ja päähineenä.'),
(1682453,58,18,29,15,'Minä olin sokean silmä ja ontuvan jalka.'),
(1682454,58,18,29,16,'Minä olin köyhien isä, ja tuntemattoman asiaa minä tarkoin tutkin.'),
(1682455,58,18,29,17,'Minä särjin väärintekijän leukaluut ja tempasin saaliin hänen hampaistansa.'),
(1682456,58,18,29,18,'Silloin ajattelin: ''Pesääni minä saan kuolla, ja minä lisään päiväni paljoiksi kuin hiekka.'),
(1682457,58,18,29,19,'Onhan juureni vedelle avoinna, ja kaste yöpyy minun oksillani.'),
(1682458,58,18,29,20,'Kunniani uudistuu alati, ja jouseni nuortuu minun kädessäni.'''),
(1682459,58,18,29,21,'He kuuntelivat minua ja odottivat, olivat vaiti ja vartoivat neuvoani.'),
(1682460,58,18,29,22,'Puhuttuani eivät he enää sanaa sanoneet, vihmana vuoti puheeni heihin.'),
(1682461,58,18,29,23,'He odottivat minua niinkuin sadetta ja avasivat suunsa niinkuin kevätkuurolle.'),
(1682462,58,18,29,24,'Minä hymyilin heille, kun he olivat toivottomat, ja minun kasvojeni loistaessa eivät he synkiksi jääneet.'),
(1682463,58,18,29,25,'Jos suvaitsin tulla heidän luokseen, niin minä istuin ylinnä, istuin kuin kuningas sotajoukkonsa keskellä, niinkuin se, joka murheelliset lohduttaa."'),
(1682464,58,18,30,1,'"Mutta nyt nauravat minua elinpäiviltään nuoremmat, joiden isiä minä pidin liian halpoina pantaviksi paimenkoiraini pariin.'),
(1682465,58,18,30,2,'Ja mitäpä hyödyttäisi minua heidän kättensä voima, koska heidän nuoruutensa tarmon on vienyt'),
(1682466,58,18,30,3,'puute ja kova nälänhätä! He kaluavat kuivaa maata, jo ennestään autiota erämaata;'),
(1682467,58,18,30,4,'he poimivat suolaheiniä pensaiden ympäriltä, ja heidän ruokanaan ovat kinsteripensaan juuret.'),
(1682468,58,18,30,5,'Heidät karkoitetaan ihmisten parista; heitä vastaan nostetaan hälytys niinkuin varasta vastaan.'),
(1682469,58,18,30,6,'Heidän on asuttava kaameissa rotkoissa, maakoloissa ja kallioluolissa.'),
(1682470,58,18,30,7,'Pensaiden keskellä he ulisevat, nokkospehkojen suojaan he sulloutuvat -'),
(1682471,58,18,30,8,'nuo houkkioiden ja kunniattomain sikiöt, jotka on hosuttu maasta pois.'),
(1682472,58,18,30,9,'Heille minä olen nyt tullut pilkkalauluksi, olen heidän jutuksensa joutunut;'),
(1682473,58,18,30,10,'he inhoavat minua, väistyvät minusta kauas eivätkä häikäile sylkeä silmilleni.'),
(1682474,58,18,30,11,'Sillä Jumala on höllentänyt jouseni jänteen ja nöyryyttänyt minut, eivätkä he enää suista julkeuttaan minun edessäni.'),
(1682475,58,18,30,12,'Oikealta puoleltani nousee tuo sikiöparvi; he lyövät jalat altani ja luovat turmateitänsä minua vastaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682476,58,18,30,13,'He hävittävät minun polkuni, ovat apuna minua tuhottaessa, vaikka itse ovat ilman auttajaa;'),
(1682477,58,18,30,14,'niinkuin leveästä muurinaukosta he tulevat, raunioiden alta he vyöryvät esiin.'),
(1682478,58,18,30,15,'Kauhut ovat kääntyneet minua vastaan; niinkuin tuuli sinä pyyhkäiset pois minun arvoni, ja minun onneni katoaa niinkuin pilvi.'),
(1682479,58,18,30,16,'Ja nyt minun sieluni vuotaa tyhjiin, kurjuuden päivät ovat saavuttaneet minut.'),
(1682480,58,18,30,17,'Yö kaivaa luut minun ruumiistani, ja kalvavat tuskani eivät lepää.'),
(1682481,58,18,30,18,'Kaikkivallan voimasta on minun verhoni muodottomaksi muuttunut: se kiristyy ympärilleni niinkuin ihokkaani pääntie.'),
(1682482,58,18,30,19,'Hän on heittänyt minut lokaan, ja minä olen tullut tomun ja tuhan kaltaiseksi.'),
(1682483,58,18,30,20,'Minä huudan sinua, mutta sinä et vastaa minulle; minä seison tässä, mutta sinä vain tuijotat minuun.'),
(1682484,58,18,30,21,'Sinä muutut tylyksi minulle, vainoat minua väkevällä kädelläsi.'),
(1682485,58,18,30,22,'Sinä kohotat minut myrskytuuleen, kiidätät minut menemään ja annat minun menehtyä rajuilman pauhinassa.'),
(1682486,58,18,30,23,'Niin, minä tiedän: sinä viet minua kohti kuolemaa, majaan, kunne kaikki elävä kokoontuu.'),
(1682487,58,18,30,24,'Mutta eikö saisi hukkuessaan kättänsä ojentaa tahi onnettomuudessa apua huutaa?'),
(1682488,58,18,30,25,'Vai enkö minä itkenyt kovaosaisen kohtaloa, eikö sieluni säälinyt köyhää?'),
(1682489,58,18,30,26,'Niin, minä odotin onnea, mutta tuli onnettomuus; minä vartosin valoa, mutta tuli pimeys.'),
(1682490,58,18,30,27,'Sisukseni kuohuvat lakkaamatta, kurjuuden päivät ovat kohdanneet minut.'),
(1682491,58,18,30,28,'Minä käyn murheasussa, ilman päivänpaistetta; minä nousen ja huudan väkijoukossa.'),
(1682492,58,18,30,29,'Minusta on tullut aavikkosutten veli ja kamelikurkien kumppani.'),
(1682493,58,18,30,30,'Minun nahkani on mustunut ja lähtee päältäni, ja luuni ovat kuumuuden polttamat.'),
(1682494,58,18,30,31,'Niin muuttui kanteleeni soitto valitukseksi ja huiluni sävel itkun ääneksi."'),
(1682495,58,18,31,1,'"Minä olen tehnyt liiton silmäini kanssa: kuinka voisinkaan katsoa neitosen puoleen!'),
(1682496,58,18,31,2,'Minkä osan antaisi silloin Jumala ylhäältä, minkä perintöosan Kaikkivaltias korkeudesta?'),
(1682497,58,18,31,3,'Tuleehan väärälle turmio ja onnettomuus väärintekijöille.'),
(1682498,58,18,31,4,'Eikö hän näkisi minun teitäni ja laskisi kaikkia minun askeleitani?'),
(1682499,58,18,31,5,'Jos minä ikinä valheessa vaelsin, jos jalkani kiiruhti petokseen,'),
(1682500,58,18,31,6,'punnitkoon minut Jumala oikealla vaa''alla, ja hän on huomaava minun nuhteettomuuteni.'),
(1682501,58,18,31,7,'Jos minun askeleeni poikkesivat tieltä ja minun sydämeni seurasi silmiäni tahi tahra tarttui minun käsiini,'),
(1682502,58,18,31,8,'niin syököön toinen, mitä minä kylvän, ja minun vesani revittäköön juurinensa.'),
(1682503,58,18,31,9,'Jos minun sydämeni hullaantui toisen vaimoon ja minä väijyin lähimmäiseni ovella,'),
(1682504,58,18,31,10,'niin jauhakoon oma vaimoni vieraalle, ja halailkoot häntä muut;'),
(1682505,58,18,31,11,'sillä se olisi ollut ilkityö ja raskaasti rangaistava rikos,'),
(1682506,58,18,31,12,'tuli, joka kuluttaisi manalaan saakka ja hävittäisi kaiken saatuni.'),
(1682507,58,18,31,13,'Jos minä pidin halpana palvelijani ja palvelijattareni oikeuden, kun heillä oli riita minun kanssani,'),
(1682508,58,18,31,14,'niin mitä minä tekisin, jos Jumala nousisi, ja mitä vastaisin hänelle, jos hän kävisi tutkimaan?'),
(1682509,58,18,31,15,'Eikö sama, joka äidin kohdussa loi minut, luonut häntäkin, eikö sama meitä äidin sydämen alla valmistanut?'),
(1682510,58,18,31,16,'Olenko minä kieltänyt vaivaisilta heidän toivomuksensa ja saattanut lesken silmät sammumaan?'),
(1682511,58,18,31,17,'Olenko syönyt leipäpalani yksinäni, orvonkin saamatta syödä siitä?'),
(1682512,58,18,31,18,'En, vaan nuoruudestani saakka minä kasvatin häntä niinkuin oma isä ja äitini kohdusta asti minä holhosin häntä.'),
(1682513,58,18,31,19,'Jos minä näin menehtyväisen vaatteetonna ja köyhän verhoa vailla,'),
(1682514,58,18,31,20,'jos hänen lanteensa eivät minua siunanneet eikä hän saanut lämmitellä minun karitsaini villoilla,'),
(1682515,58,18,31,21,'jos minä puin nyrkkiä orvolle, kun näin puoltani pidettävän portissa,'),
(1682516,58,18,31,22,'niin irtautukoon olkapääni hartiastani, ja murtukoon käsivarteni sijoiltansa.'),
(1682517,58,18,31,23,'Sillä silloin olisi minun peljättävä turmiota Jumalalta, enkä kestäisi hänen valtasuuruutensa edessä.'),
(1682518,58,18,31,24,'Jos minä panin uskallukseni kultaan ja sanoin hienolle kullalle: ''Sinä olet minun turvani'','),
(1682519,58,18,31,25,'jos iloitsin siitä, että rikkauteni oli suuri ja että käteni oli saanut paljon hankituksi,'),
(1682520,58,18,31,26,'jos katsellessani aurinkoa, kuinka se loisti, ja kuuta, joka ylhänä vaelsi,'),
(1682521,58,18,31,27,'sydämeni antautui salaa vieteltäväksi ja käteni niille suudelmia heitti,'),
(1682522,58,18,31,28,'niin olisi sekin raskaasti rangaistava rikos, sillä minä olisin kieltänyt korkeuden Jumalan.'),
(1682523,58,18,31,29,'Olenko iloinnut vihamieheni vahingosta, riemusta hykähtänyt, kun häntä onnettomuus kohtasi?'),
(1682524,58,18,31,30,'En ole sallinut suuni syntiä tehdä, kiroten vaatia hänen henkeänsä.'),
(1682525,58,18,31,31,'Eikö täydy minun talonväkeni myöntää, että kukin on saanut lihaa yllin kyllin?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682526,58,18,31,32,'Muukalaisen ei tarvinnut yötä ulkona viettää; minä pidin oveni auki tielle päin.'),
(1682527,58,18,31,33,'Olenko ihmisten tavoin peitellyt rikkomuksiani, kätkenyt poveeni pahat tekoni,'),
(1682528,58,18,31,34,'säikkyen suurta joukkoa ja kaiken heimon ylenkatsetta peljäten, niin että pysyin hiljaa, ovestani ulkonematta?'),
(1682529,58,18,31,35,'Oi, jospa joku kuuntelisi minua! Katso, tuossa on puumerkkini! Kaikkivaltias vastatkoon minulle! Jospa saisin riitapuoleni kirjoittamaan syytekirjan!'),
(1682530,58,18,31,36,'Totisesti, olkapäälläni sitä kantaisin, sitoisin sen päähäni seppeleeksi.'),
(1682531,58,18,31,37,'Tekisin hänelle tilin kaikista askeleistani ja astuisin hänen eteensä niinkuin ruhtinas.'),
(1682532,58,18,31,38,'Jos peltoni huusi minua vastaan ja sen vaot kaikki itkivät,'),
(1682533,58,18,31,39,'jos kulutin sen voiman maksamatta ja saatoin sen haltijat huokaamaan,'),
(1682534,58,18,31,40,'niin kasvakoon nisun sijasta orjantappuroita ja ohran sijasta rikkaruohoa." Tähän päättyvät Jobin puheet.'),
(1682535,58,18,32,1,'Kun nuo kolme miestä eivät enää vastanneet Jobille, koska hän oli omissa silmissään vanhurskas,'),
(1682536,58,18,32,2,'vihastui buusilainen Elihu, Baarakelin poika, joka oli Raamin sukua; Jobiin hän vihastui, koska tämä piti itseään Jumalaa vanhurskaampana,'),
(1682537,58,18,32,3,'ja tämän kolmeen ystävään hän vihastui, koska he eivät keksineet vastausta, jolla olisivat osoittaneet Jobin olevan väärässä.'),
(1682538,58,18,32,4,'Elihu oli odottanut vuoroa puhuakseen Jobille, koska toiset olivat iältään häntä vanhemmat.'),
(1682539,58,18,32,5,'Mutta kun Elihu näki, ettei noilla kolmella miehellä enää ollut sanaa suussa vastaukseksi, vihastui hän.'),
(1682540,58,18,32,6,'Niin buusilainen Elihu, Baarakelin poika, lausui ja sanoi: "Nuori minä olen iältäni, ja te olette vanhat; sentähden minä arkailin ja pelkäsin ilmoittaa tietoani teille.'),
(1682541,58,18,32,7,'Minä ajattelin: ''Puhukoon ikä, ja vuosien paljous julistakoon viisautta''.'),
(1682542,58,18,32,8,'Mutta onhan ihmisissä henki, ja Kaikkivaltiaan henkäys antaa heille ymmärrystä.'),
(1682543,58,18,32,9,'Eivät iäkkäät ole viisaimmat, eivätkä vanhukset yksin ymmärrä, mikä on oikein.'),
(1682544,58,18,32,10,'Sentähden minä sanon: Kuule minua; minäkin ilmoitan, mitä tiedän.'),
(1682545,58,18,32,11,'Katso, minä olen odottanut, mitä teillä olisi sanomista, olen kuunnellut teidän taitavia puheitanne, kunnes olisitte löytäneet osuvat sanat.'),
(1682546,58,18,32,12,'Niin, minä tarkkasin teitä; mutta katso, ei kukaan ole Jobin sanoja kumonnut, ei kukaan teistä voinut vastata hänen puheisiinsa.'),
(1682547,58,18,32,13,'Älkää sanoko: ''Meitä vastassa on ilmetty viisaus, vain Jumala voi hänet torjua, ei ihminen''.'),
(1682548,58,18,32,14,'Minua vastaan hän ei ole todisteita tuonut, enkä käy hänelle vastaamaan teidän puheillanne.'),
(1682549,58,18,32,15,'He ovat kauhistuneet, eivät enää vastaa; sanat puuttuvat heiltä.'),
(1682550,58,18,32,16,'Odottaisinko minä, kun he eivät puhu, kun he siinä seisovat enää vastaamatta?'),
(1682551,58,18,32,17,'Vastaanpa minäkin osaltani, minäkin ilmoitan, mitä tiedän.'),
(1682552,58,18,32,18,'Sillä minä olen sanoja täynnä, henki rinnassani ahdistaa minua.'),
(1682553,58,18,32,19,'Katso, minun rintani on kuin viini, jolle ei reikää avata, se on pakahtumaisillaan niinkuin nuorella viinillä täytetyt leilit.'),
(1682554,58,18,32,20,'Tahdon puhua, saadakseni helpotusta, avata huuleni ja vastata.'),
(1682555,58,18,32,21,'En pidä kenenkään puolta enkä ketään ihmistä imartele.'),
(1682556,58,18,32,22,'Sillä en osaa imarrella; silloin Luojani ottaisi minut kohta pois."'),
(1682557,58,18,33,1,'"Mutta kuule nyt, Job, minun puhettani, ja ota korviisi kaikki minun sanani.'),
(1682558,58,18,33,2,'Katso, minä olen avannut suuni, kieleni puhuu suulakeni alla.'),
(1682559,58,18,33,3,'Vilpittömästä sydämestä lähtevät sanani; mitä tietävät, sen huuleni suoraan sanovat.'),
(1682560,58,18,33,4,'Jumalan henki on minut luonut, ja Kaikkivaltiaan henkäys elävöittää minut.'),
(1682561,58,18,33,5,'Vastaa minulle, jos taidat; varustaudu minua vastaan, nouse taisteluun.'),
(1682562,58,18,33,6,'Katso, Jumalan edessä minä olen samanlainen kuin sinä: hyppysellinen savea olen minäkin.'),
(1682563,58,18,33,7,'Katso, ei käy minusta kauhu, joka sinut peljästyttää, eikä minun painoni ole raskaana ylläsi.'),
(1682564,58,18,33,8,'Mutta sinä olet sanonut korvieni kuullen, minä olen kuullut sinun sanojesi äänen:'),
(1682565,58,18,33,9,'''Puhdas minä olen, rikoksesta vapaa; olen viaton, eikä minussa ole vääryyttä.'),
(1682566,58,18,33,10,'Katso, hän keksii vihan syitä minua vastaan, hän pitää minua vihollisenansa;'),
(1682567,58,18,33,11,'hän panee minun jalkani jalkapuuhun, vartioitsee kaikkia minun polkujani.'''),
(1682568,58,18,33,12,'Katso, sinä et ole oikeassa - niin minä vastaan sinulle - sillä Jumala on suurempi kuin ihminen.'),
(1682569,58,18,33,13,'Miksi olet riidellyt häntä vastaan, jos hän ei vastaa kaikkiin ihmisen sanoihin?'),
(1682570,58,18,33,14,'Sillä Jumala puhuu tavalla ja puhuu toisella; sitä vain ei huomata.'),
(1682571,58,18,33,15,'Unessa, öisessä näyssä, kun raskas uni valtaa ihmiset ja he nukkuvat vuoteillansa,'),
(1682572,58,18,33,16,'silloin hän avaa ihmisten korvat ja sinetillä vahvistaa heidän saamansa kurituksen,'),
(1682573,58,18,33,17,'kääntääkseen ihmisen pois pahasta teosta ja varjellakseen miestä ylpeydestä,'),
(1682574,58,18,33,18,'säästääkseen hänen sielunsa haudasta ja hänen henkensä syöksymästä peitsiin.'),
(1682575,58,18,33,19,'Myös kuritetaan häntä tuskalla vuoteessansa, kun hänen luissaan on lakkaamaton kapina,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682576,58,18,33,20,'ja hänen henkensä inhoaa leipää ja hänen sielunsa herkkuruokaa.'),
(1682577,58,18,33,21,'Hänen lihansa kuihtuu näkymättömiin, ja hänen luunsa, ennen näkymättömät, paljastuvat.'),
(1682578,58,18,33,22,'Näin lähenee hänen sielunsa hautaa ja hänen henkensä kuolonvaltoja.'),
(1682579,58,18,33,23,'Jos silloin on hänen puolellansa enkeli, välittäjä, yksi tuhansista, todistamassa ihmisen puolesta hänen vilpittömyyttään,'),
(1682580,58,18,33,24,'niin Jumala armahtaa häntä ja sanoo: ''Vapauta hänet, ettei hän mene hautaan; minä olen saanut lunastusmaksun''.'),
(1682581,58,18,33,25,'Silloin hänen ruumiinsa taas uhkuu nuoruuden voimaa, hän palajaa takaisin nuoruutensa päiviin.'),
(1682582,58,18,33,26,'Hän rukoilee Jumalaa, ja Jumala mielistyy häneen ja antaa hänen riemuiten katsella hänen kasvojaan; niin hän palauttaa ihmiselle hänen vanhurskautensa.'),
(1682583,58,18,33,27,'Hänpä nyt laulaa muille ihmisille ja sanoo: ''Minä olin tehnyt syntiä ja vääristänyt oikean, mutta ei sitä kostettu minulle;'),
(1682584,58,18,33,28,'hän pelasti minun sieluni joutumasta hautaan, ja minun henkeni saa iloiten katsella valkeutta''.'),
(1682585,58,18,33,29,'Katso, kaiken tämän tekee Jumala kahdesti ja kolmastikin ihmiselle,'),
(1682586,58,18,33,30,'palauttaakseen hänen sielunsa haudasta ja antaakseen elämän valkeuden hänelle loistaa.'),
(1682587,58,18,33,31,'Tarkkaa, Job, kuule minua; vaikene ja anna minun puhua.'),
(1682588,58,18,33,32,'Mutta jos sinulla on, mitä sanoa, niin vastaa minulle; puhu, sillä mielelläni soisin sinun olevan oikeassa.'),
(1682589,58,18,33,33,'Ellei, niin kuule minua; vaikene, niin minä opetan sinulle viisautta."'),
(1682590,58,18,34,1,'Ja Elihu lausui ja sanoi:'),
(1682591,58,18,34,2,'"Kuulkaa, te viisaat, minun sanojani, ja kuunnelkaa minua, te tietomiehet.'),
(1682592,58,18,34,3,'Sillä korva koettelee sanat, ja suulaki maistaa ruuan maun.'),
(1682593,58,18,34,4,'Tutkikaamme, mikä oikein on, koettakaamme yhdessä ymmärtää, mikä hyvä on.'),
(1682594,58,18,34,5,'Sillä Job on sanonut: ''Olen oikeassa, mutta Jumala on ottanut minulta oikeuteni.'),
(1682595,58,18,34,6,'Vaikka minun puolellani on oikeus, pitäisi minun valhetella; kuolettava nuoli on minuun sattunut, vaikka olen rikoksesta vapaa.'''),
(1682596,58,18,34,7,'Kuka mies on sellainen kuin Job, joka juo jumalanpilkkaa niinkuin vettä,'),
(1682597,58,18,34,8,'joka yhtyy väärintekijäin seuraan ja vaeltaa jumalattomain miesten parissa?'),
(1682598,58,18,34,9,'Sillä hän sanoo: ''Ei hyödy mies siitä, että elää Jumalalle mieliksi''.'),
(1682599,58,18,34,10,'Sentähden kuulkaa minua, te ymmärtäväiset miehet: Pois se! Ei Jumalassa ole jumalattomuutta eikä Kaikkivaltiaassa vääryyttä.'),
(1682600,58,18,34,11,'Vaan hän kostaa ihmiselle hänen tekonsa ja maksaa miehelle hänen vaelluksensa mukaan.'),
(1682601,58,18,34,12,'Totisesti, Jumala ei tee väärin, Kaikkivaltias ei vääristä oikeutta.'),
(1682602,58,18,34,13,'Kuka on pannut hänet vallitsemaan maata, ja kuka on perustanut koko maanpiirin?'),
(1682603,58,18,34,14,'Jos hän ajattelisi vain itseänsä ja palauttaisi luokseen henkensä ja henkäyksensä,'),
(1682604,58,18,34,15,'niin kaikki liha yhdessä menehtyisi, ja ihminen tulisi tomuksi jälleen.'),
(1682605,58,18,34,16,'Jos sinulla on ymmärrystä, niin kuule tätä, ota korviisi sanojeni ääni.'),
(1682606,58,18,34,17,'Taitaisiko todella se hallita, joka vihaa oikeutta? Vai tuomitsetko sinä syylliseksi tuon Vanhurskaan, Voimallisen,'),
(1682607,58,18,34,18,'joka sanoo kuninkaalle: ''Sinä kelvoton'', ruhtinaille: ''Sinä jumalaton'','),
(1682608,58,18,34,19,'joka ei pidä päämiesten puolta eikä aseta rikasta vaivaisen edelle, koska he kaikki ovat hänen kättensä tekoa?'),
(1682609,58,18,34,20,'Tuossa tuokiossa he kuolevat, keskellä yötä; kansat järkkyvät ja häviävät, väkevä siirretään pois käden koskematta.'),
(1682610,58,18,34,21,'Sillä hänen silmänsä valvovat ihmisen teitä, ja hän näkee kaikki hänen askeleensa.'),
(1682611,58,18,34,22,'Ei ole pimeyttä, ei pilkkopimeää, johon voisivat piiloutua väärintekijät.'),
(1682612,58,18,34,23,'Sillä ei tarvitse Jumalan kauan ihmistä tarkata, ennenkuin tämän on astuttava tuomiolle hänen eteensä;'),
(1682613,58,18,34,24,'hän musertaa voimalliset tutkimatta ja asettaa toiset heidän sijallensa.'),
(1682614,58,18,34,25,'Niinpä hän tuntee heidän tekonsa ja kukistaa heidät yöllä, ja he musertuvat.'),
(1682615,58,18,34,26,'Niinkuin jumalattomia hän kurittaa heitä julkisella paikalla,'),
(1682616,58,18,34,27,'koska he luopuivat hänestä eivätkä ensinkään huolineet hänen teistään,'),
(1682617,58,18,34,28,'vaan saattoivat vaivaisten huudon kohoamaan hänen eteensä, ja hän kuuli kurjain huudon.'),
(1682618,58,18,34,29,'Ja jos hän on hiljaa, kuka häntä siitä tuomitsee? Jos hän peittää kasvonsa, kuka voi häntä katsella? Niin kansaa kuin kutakin ihmistä hän valvoo,'),
(1682619,58,18,34,30,'ettei pääse hallitsemaan jumalaton ihminen, ei kukaan niistä, jotka ovat kansalle paulana.'),
(1682620,58,18,34,31,'Sillä onko tässä sanottu Jumalalle: ''Kyllä minä kärsin, en enää pahoin tee.'),
(1682621,58,18,34,32,'Mitä en näe, neuvo minulle; jos olen tehnyt vääryyttä, en sitä enää tee.'''),
(1682622,58,18,34,33,'Sinunko mielesi mukaan tulisi hänen kostaa, koska olet niin tyytymätön? Niin, sinun on tehtävä valinta eikä minun; puhu, mitä tiedät.'),
(1682623,58,18,34,34,'Ymmärtäväiset miehet sanovat minulle, viisas mies, joka minua kuulee, virkkaa:'),
(1682624,58,18,34,35,'''Job puhuu taitamattomasti, ja hänen sanansa ovat ymmärrystä vailla.'),
(1682625,58,18,34,36,'Jospa Jobia koeteltaisiin ainiaan, koska hän vastaa väärintekijäin tavalla!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682626,58,18,34,37,'Sillä hän lisää syntiä syntiin, lyö kämmentä keskellämme ja syytää sanoja Jumalaa vastaan.''"'),
(1682627,58,18,35,1,'Elihu lausui ja sanoi:'),
(1682628,58,18,35,2,'"Pidätkö sitä oikeutena, sanotko sitä vanhurskaudeksi Jumalan edessä,'),
(1682629,58,18,35,3,'että kysyt, mitä se sinua hyödyttää: ''Hyödynkö siitä sen enempää, kuin jos syntiä teen?'''),
(1682630,58,18,35,4,'Siihen minä vastaan sinulle sekä ystävillesi, jotka luonasi ovat.'),
(1682631,58,18,35,5,'Luo silmäsi taivaalle ja näe, katsele pilviä, jotka ovat korkealla pääsi päällä.'),
(1682632,58,18,35,6,'Jos sinä syntiä teet, mitä sillä hänelle teet; ja vaikka sinulla paljonkin rikoksia olisi, mitä sillä hänelle mahdat?'),
(1682633,58,18,35,7,'Jos olet vanhurskas, mitä sillä hänelle annat, tahi ottaako hän mitään sinun kädestäsi?'),
(1682634,58,18,35,8,'Ihmistä, kaltaistasi, koskee jumalattomuutesi ja ihmislasta sinun vanhurskautesi.'),
(1682635,58,18,35,9,'Sorron suuruutta valitetaan, huudetaan apua suurten käsivartta vastaan,'),
(1682636,58,18,35,10,'ei kysytä: ''Missä on Jumala, minun Luojani, joka yöllä saa viriämään ylistysvirret,'),
(1682637,58,18,35,11,'joka opettaa meille enemmän kuin metsän eläimille ja antaa meille viisautta enemmän kuin taivaan linnuille?'''),
(1682638,58,18,35,12,'Valittakoot sitten pahojen ylpeyttä; ei hän vastaa.'),
(1682639,58,18,35,13,'Ei, turhia ei Jumala kuule, eikä Kaikkivaltias niihin katso,'),
(1682640,58,18,35,14,'saati jos sanot, ettet voi häntä nähdä; asia on hänen edessänsä: odota häntä.'),
(1682641,58,18,35,15,'Mutta nyt, kun hänen vihansa ei kosta eikä hän ylvästelystä suuresti välitä,'),
(1682642,58,18,35,16,'niin Job avaa suunsa joutaviin ja syytää suuria sanoja taitamattomasti."'),
(1682643,58,18,36,1,'Elihu jatkoi puhettaan ja sanoi:'),
(1682644,58,18,36,2,'"Maltahan vähän, niin julistan sinulle, sillä vielä on minulla Jumalan puolesta puhuttavaa.'),
(1682645,58,18,36,3,'Minä noudan tietoni kaukaa ja osoitan Luojani oikeuden;'),
(1682646,58,18,36,4,'sillä totisesti, sanani eivät ole valhetta - mies, jolla on täydellinen tieto, on edessäsi.'),
(1682647,58,18,36,5,'Katso, Jumala on voimallinen, mutta ei halveksu ketään; väkevä on hänen ymmärryksensä voima.'),
(1682648,58,18,36,6,'Hän ei pidä jumalatonta elossa, vaan hankkii kurjille oikeuden.'),
(1682649,58,18,36,7,'Hän ei käännä silmiänsä pois hurskaista, vaan antaa heidän istua kuningasten kanssa valtaistuimella ikuisesti; he kohoavat korkealle.'),
(1682650,58,18,36,8,'Ja jos niinkin käy, että heidät kytketään kahleisiin, sidotaan kurjuuden köysillä,'),
(1682651,58,18,36,9,'niin hän sillä ilmaisee heille, mitä he ovat tehneet ja mitä rikkoneet pöyhkeilemisellään,'),
(1682652,58,18,36,10,'avaa heidän korvansa nuhtelulle ja käskee heitä kääntymään pois vääryydestä.'),
(1682653,58,18,36,11,'Jos he kuulevat ja alistuvat, niin saavat viettää päivänsä onnessa ja ikävuotensa ihanasti.'),
(1682654,58,18,36,12,'Mutta jos eivät kuule, niin he syöksyvät surman peitsiin ja menehtyvät ymmärtämättömyyteensä.'),
(1682655,58,18,36,13,'Mutta jumalattomat pitävät vihaa, he eivät apua huuda, kun hän on heidät vanginnut.'),
(1682656,58,18,36,14,'Heidän sielunsa kuolee nuoruudessa, heidän elämänsä loppuu niinkuin haureellisten pyhäkköpoikain.'),
(1682657,58,18,36,15,'Kurjan hän vapahtaa hänen kurjuutensa kautta ja avaa hänen korvansa ahdistuksella.'),
(1682658,58,18,36,16,'Sinutkin houkutteli ahdingosta pois avara tila, jossa ei ahtautta ollut, ja lihavuudesta notkuvan ruokapöydän rauha.'),
(1682659,58,18,36,17,'Ja niin kohtasi sinua kukkuramäärin jumalattoman tuomio; tuomio ja oikeus on käynyt sinuun kiinni.'),
(1682660,58,18,36,18,'Älköön kärsimyksen polte houkutelko sinua pilkkaamaan, älköönkä lunastusmaksun suuruus viekö sinua harhaan.'),
(1682661,58,18,36,19,'Voiko huutosi auttaa ahdingosta tahi kaikki voimasi ponnistukset?'),
(1682662,58,18,36,20,'Älä halaja yötä, joka siirtää kansat sijoiltansa.'),
(1682663,58,18,36,21,'Varo, ettet käänny vääryyteen, sillä se on sinulle mieluisampi kuin kärsimys.'),
(1682664,58,18,36,22,'Katso, Jumala on korkea, valliten voimassansa; kuka on hänen kaltaisensa opettaja?'),
(1682665,58,18,36,23,'Kuka määrää hänen tiensä, ja kuka sanoo: ''Sinä teit väärin''?'),
(1682666,58,18,36,24,'Muista sinäkin ylistää hänen töitänsä, joiden kiitosta ihmiset veisaavat;'),
(1682667,58,18,36,25,'kaikki ihmiset ihailevat niitä, kuolevaiset katselevat niitä kaukaa.'),
(1682668,58,18,36,26,'Katso, Jumala on suuri, emme häntä käsitä, hänen vuottensa luku on ilman määrää.'),
(1682669,58,18,36,27,'Hän kokoaa vedenpisarat; ne vihmovat virtanaan sadetta,'),
(1682670,58,18,36,28,'jota pilvet vuodattavat, valuttavat ihmisjoukkojen päälle.'),
(1682671,58,18,36,29,'Kuka ymmärtää pilvien leviämiset, kuka hänen majansa jyrinän?'),
(1682672,58,18,36,30,'Katso, hän levittää niiden päälle leimauksensa ja peittää meren pohjat.'),
(1682673,58,18,36,31,'Sillä niin hän tuomitsee kansat, niin hän antaa runsaan ravinnon.'),
(1682674,58,18,36,32,'Hän peittää molemmat kätensä leimauksilla ja lähettää ne ahdistajan kimppuun.'),
(1682675,58,18,36,33,'Hänet ilmoittaa hänen jylinänsä, jopa karjakin hänen tulonsa."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682676,58,18,37,1,'"Niin, siitä vapisee sydämeni ja hypähtää paikoiltansa.'),
(1682677,58,18,37,2,'Kuulkaa, kuulkaa hänen äänensä pauhinaa ja kohinaa, joka käy hänen suustansa.'),
(1682678,58,18,37,3,'Hän laskee sen kaikumaan kaiken taivaan alla, lähettää leimauksensa maan ääriin asti.'),
(1682679,58,18,37,4,'Sen kintereillä ärjyy ääni, hän korottaa väkevän äänensä jylinän, eikä hän säästä salamoitaan, äänensä raikuessa.'),
(1682680,58,18,37,5,'Ihmeellisesti Jumala korottaa äänensä jylinän, hän tekee suuria tekoja, joita emme käsittää taida.'),
(1682681,58,18,37,6,'Sillä hän sanoo lumelle: ''Putoa maahan'', samoin sadekuurolle, rankkasateittensa ryöpylle.'),
(1682682,58,18,37,7,'Niin hän kytkee jokaiselta kädet, että kaikki ihmiset hänen tekonsa tietäisivät.'),
(1682683,58,18,37,8,'Pedot vetäytyvät piiloon ja pysyvät luolissansa.'),
(1682684,58,18,37,9,'Tähtitarhasta tulee tuulispää, pohjan ilmalta pakkanen.'),
(1682685,58,18,37,10,'Jumalan henkäyksestä syntyy jää, ja aavat vedet ahdistuvat.'),
(1682686,58,18,37,11,'Hän myös kuormittaa pilvet kosteudella ja hajottaa välähtelevät ukkosvaarunsa.'),
(1682687,58,18,37,12,'Ne vyöryvät sinne tänne hänen ohjauksestaan, tehdäkseen maanpiirin päällä kaiken, mitä hän niille määrää.'),
(1682688,58,18,37,13,'Hän antaa niiden osua milloin maalle vitsaukseksi, milloin siunaukseksi.'),
(1682689,58,18,37,14,'Ota tämä korviisi, Job; pysähdy ja tarkkaa Jumalan ihmetöitä.'),
(1682690,58,18,37,15,'Tiedätkö, kuinka Jumala niillä tekonsa teettää ja kuinka hän antaa pilviensä leimausten loistaa?'),
(1682691,58,18,37,16,'Käsitätkö pilvien punnituksen, hänen ihmeensä, joka on kaikkitietävä?'),
(1682692,58,18,37,17,'Sinä, jonka vaatteet kuumenevat, kun maa on raukeana etelän helletuulesta,'),
(1682693,58,18,37,18,'kaarrutatko sinä hänen kanssansa taivaan, joka on vahva kuin valettu kuvastin?'),
(1682694,58,18,37,19,'Neuvo, mitä meidän on hänelle sanottava; pimeydessämme emme voi tuoda esiin mitään.'),
(1682695,58,18,37,20,'Olisiko hänelle ilmoitettava, että tahtoisin puhua? Kukapa vaatisi omaa tuhoansa!'),
(1682696,58,18,37,21,'Ja nyt: ei voida katsella valoa, joka kirkkaana loistaa, kun tuuli on puhaltanut puhdistaen taivaan.'),
(1682697,58,18,37,22,'Pohjoisesta tulee kultainen hohde; Jumalan yllä on peljättävä valtasuuruus.'),
(1682698,58,18,37,23,'Kaikkivaltiasta emme saata käsittää, häntä, joka on suuri voimassa, joka ei oikeutta ja täydellistä vanhurskautta polje.'),
(1682699,58,18,37,24,'Sentähden peljätkööt häntä ihmiset; hän ei katso keneenkään, joka on omasta mielestään viisas."'),
(1682700,58,18,38,1,'Silloin Herra vastasi Jobille tuulispäästä ja sanoi:'),
(1682701,58,18,38,2,'"Kuka olet sinä, joka taitamattomilla puheilla pimennät minun aivoitukseni?'),
(1682702,58,18,38,3,'Vyötä nyt kupeesi kuin mies; minä kysyn sinulta, opeta sinä minua.'),
(1682703,58,18,38,4,'Missä olit silloin, kun minä maan perustin? Ilmoita se, jos ymmärryksesi riittää.'),
(1682704,58,18,38,5,'Kuka on määrännyt sen mitat - tottapa sen tiedät - tahi kuka on vetänyt mittanuoran sen ylitse?'),
(1682705,58,18,38,6,'Mihin upotettiin sen perustukset, tahi kuka laski sen kulmakiven,'),
(1682706,58,18,38,7,'kun aamutähdet kaikki iloitsivat ja kaikki Jumalan pojat riemuitsivat?'),
(1682707,58,18,38,8,'Ja kuka sulki ovilla meren, kun se puhkesi ja kohdusta lähti,'),
(1682708,58,18,38,9,'kun minä panin sille pilven vaatteeksi ja synkeyden kapaloksi,'),
(1682709,58,18,38,10,'kun minä rakensin sille rajani, asetin sille teljet ja ovet'),
(1682710,58,18,38,11,'ja sanoin: ''Tähän asti saat tulla, mutta edemmäksi et; tässä täytyy sinun ylväiden aaltojesi asettua''?'),
(1682711,58,18,38,12,'Oletko eläissäsi käskenyt päivän koittaa tahi osoittanut aamuruskolle paikkansa,'),
(1682712,58,18,38,13,'että se tarttuisi maan liepeisiin ja pudistaisi jumalattomat siitä pois?'),
(1682713,58,18,38,14,'Silloin se muuttuu niinkuin savi sinetin alla, ja kaikki tulee kuin vaatetettuna esille;'),
(1682714,58,18,38,15,'jumalattomilta riistetään heidän valonsa, ja kohonnut käsivarsi murskataan.'),
(1682715,58,18,38,16,'Oletko astunut alas meren lähdesuonille asti ja kulkenut syvyyden kuilut?'),
(1682716,58,18,38,17,'Ovatko kuoleman portit sinulle paljastuneet, oletko nähnyt pimeyden portit?'),
(1682717,58,18,38,18,'Käsitätkö, kuinka avara maa on? Ilmoita se, jos kaiken tämän tiedät.'),
(1682718,58,18,38,19,'Mikä on tie sinne, kussa asuu valo, ja missä on pimeyden asuinsija,'),
(1682719,58,18,38,20,'että saattaisit sen alueellensa ja tuntisit polut sen majalle?'),
(1682720,58,18,38,21,'Kaiketi sen tiedät, sillä synnyithän jo silloin, ja onhan päiviesi luku ylen suuri!'),
(1682721,58,18,38,22,'Oletko käynyt lumen varastohuoneissa, ja oletko nähnyt rakeiden varastot,'),
(1682722,58,18,38,23,'jotka minä olen säästänyt ahdingon ajaksi, sodan ja taistelun päiväksi?'),
(1682723,58,18,38,24,'Mitä tietä jakaantuu valo ja itätuuli leviää yli maan?'),
(1682724,58,18,38,25,'Kuka on avannut kuurnan sadekuurolle ja ukkospilvelle tien,'),
(1682725,58,18,38,26,'niin että sataa maahan, joka on asumaton, erämaahan, jossa ei ihmistä ole,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682726,58,18,38,27,'niin että autio erämaa saa kylläksensä ja maa kasvaa vihannan ruohon?'),
(1682727,58,18,38,28,'Onko sateella isää, tahi kuka on synnyttänyt kastepisarat?'),
(1682728,58,18,38,29,'Kenen kohdusta on jää tullut, ja kuka on synnyttänyt taivaan härmän?'),
(1682729,58,18,38,30,'Vesi tiivistyy kuin kiveksi, ja syvyyden pinta sulkeutuu kiinni.'),
(1682730,58,18,38,31,'Taidatko solmita Otavan siteet tahi irroittaa kahleista Kalevanmiekan?'),
(1682731,58,18,38,32,'Voitko tuoda esiin eläinradan tähdet aikanansa ja johdattaa Seulaset lapsinensa?'),
(1682732,58,18,38,33,'Tunnetko taivaan lait, tahi sinäkö säädät, miten se maata vallitsee?'),
(1682733,58,18,38,34,'Taidatko korottaa äänesi pilviin ja saada vesitulvan peittämään itsesi?'),
(1682734,58,18,38,35,'Taidatko lähettää salamat menemään, niin että sanovat sinulle: ''Katso, tässä olemme''?'),
(1682735,58,18,38,36,'Kuka on pannut viisautta pilvenlonkiin, tahi kuka antoi pilvenhattaroille ymmärrystä?'),
(1682736,58,18,38,37,'Kuka on niin viisas, että laskee pilvien luvun, kuka kaataa tyhjiksi taivaan leilit,'),
(1682737,58,18,38,38,'kun multa on kuivunut kovaksi kuin valettu ja maakokkareet toisiinsa takeltuneet?"'),
(1682738,58,18,39,1,'(38:39) "Sinäkö ajat saaliin naarasleijonalle ja tyydytät nuorten leijonain nälän,'),
(1682739,58,18,39,2,'kun ne kyyristyvät luolissansa ja ovat väijyksissä tiheikössä?'),
(1682740,58,18,39,3,'Kuka hankkii ravinnon kaarneelle, kun sen poikaset huutavat Jumalan puoleen ja lentelevät sinne tänne ruokaa vailla?'),
(1682741,58,18,39,4,'(39:1) Tiedätkö sinä vuorikauristen poikimisajat, valvotko peurojen synnytyskipuja?'),
(1682742,58,18,39,5,'Lasketko, milloin niiden kuukaudet täyttyvät, ja tiedätkö ajan, milloin ne poikivat?'),
(1682743,58,18,39,6,'Ne painautuvat maahan, saavat ilmoille sikiönsä ja vapautuvat synnytystuskistaan.'),
(1682744,58,18,39,7,'Niiden vasikat vahvistuvat, kasvavat kedolla; ne lähtevät tiehensä eivätkä enää palaja.'),
(1682745,58,18,39,8,'Kuka on laskenut villiaasin vapaaksi, kuka irroittanut metsäaasin siteet,'),
(1682746,58,18,39,9,'sen, jolle minä annoin aavikon asunnoksi ja suola-aron asuinsijaksi?'),
(1682747,58,18,39,10,'Se nauraa kaupungin kohinalle, ajajan huutoa se ei kuule;'),
(1682748,58,18,39,11,'se tähystelee vuorilta laiduntansa ja etsii kaikkea vihantaa.'),
(1682749,58,18,39,12,'Taipuuko villihärkä sinua palvelemaan, ja yöpyykö se sinun seimesi ääreen?'),
(1682750,58,18,39,13,'Voitko ohjaksilla pakottaa villihärän vaolle, tahi äestääkö se laaksonpohjia sinua seuraten?'),
(1682751,58,18,39,14,'Voitko siihen luottaa, siksi että sen voima on suuri, voitko jättää sen haltuun työsi hedelmät?'),
(1682752,58,18,39,15,'Voitko uskoa, että se palajaa ja kokoaa viljasi sinun puimatantereellesi?'),
(1682753,58,18,39,16,'Kamelikurjen siipi lepattaa iloisesti, mutta asuuko sen sulissa ja höyhenissä haikaran hellyys?'),
(1682754,58,18,39,17,'Se jättää munansa maahan, hiekalle helteen haudottaviksi.'),
(1682755,58,18,39,18,'Ei se ajattele, että jalka voi ne särkeä ja metsän eläimet polkea ne rikki.'),
(1682756,58,18,39,19,'Se on tyly poikasilleen, niinkuin ne eivät olisikaan sen omia; hukkaan menee sen vaiva, mutta ei se sitä pelkää.'),
(1682757,58,18,39,20,'Sillä Jumala on jättänyt sen viisautta vaille ja tehnyt sen ymmärryksestä osattomaksi.'),
(1682758,58,18,39,21,'Kun se kiitää ilmaa piesten, nauraa se hevoselle ja ratsumiehelle.'),
(1682759,58,18,39,22,'Sinäkö annat hevoselle voiman, puetat sen kaulan liehuvalla harjalla?'),
(1682760,58,18,39,23,'Sinäkö panet sen hyppimään kuin heinäsirkan? Sen uljas korskunta on peljättävä.'),
(1682761,58,18,39,24,'Se kuopii lakeutta ja iloitsee, lähtee voimalla asevarustuksia vastaan.'),
(1682762,58,18,39,25,'Se nauraa pelolle, ei säiky eikä väisty miekan edestä.'),
(1682763,58,18,39,26,'Sen yllä kalisee viini, välkähtää keihäs ja peitsi.'),
(1682764,58,18,39,27,'Käy jyrinä ja jytinä, kun se laukaten taivalta ahmii; ei mikään sitä pidätä sotatorven pauhatessa.'),
(1682765,58,18,39,28,'Milloin ikinä sotatorvi soi, hirnuu se: iihaha! Jo kaukaa se vainuaa taistelun, päälliköiden jylisevän äänen ja sotahuudon.'),
(1682766,58,18,39,29,'Sinunko ymmärryksesi voimasta jalohaukka kohoaa korkealle, levittää siipensä kohti etelää?'),
(1682767,58,18,39,30,'Tahi sinunko käskystäsi kotka lentää ylhäälle ja tekee pesänsä korkeuteen?'),
(1682768,58,18,39,31,'Kalliolla se asuu ja yöpyy, kallion kärjellä, vuorilinnassaan.'),
(1682769,58,18,39,32,'Sieltä se tähystelee saalista; kauas katsovat sen silmät.'),
(1682770,58,18,39,33,'(39:30) Sen poikaset särpivät verta, ja missä on kaatuneita, siellä on sekin."'),
(1682771,58,18,39,34,'(40:1) Niin Herra vastasi Jobille ja sanoi:'),
(1682772,58,18,39,35,'"Tahtooko vikoilija riidellä Kaikkivaltiasta vastaan? Jumalan syyttäjä vastatkoon tähän!"'),
(1682773,58,18,39,36,'Silloin Job vastasi Herralle ja sanoi:'),
(1682774,58,18,39,37,'"Katso, minä olen siihen liian halpa; mitäpä sinulle vastaisin? Panen käteni suulleni;'),
(1682775,58,18,39,38,'(40:5) kerran minä olen puhunut, enkä enää mitään virka, kahdesti, enkä enää sitä tee."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682776,58,18,40,1,'(40:6) Silloin Herra vastasi Jobille tuulispäästä ja sanoi:'),
(1682777,58,18,40,2,'"Vyötä nyt kupeesi kuin mies; minä kysyn sinulta, opeta sinä minua.'),
(1682778,58,18,40,3,'Sinäkö teet tyhjäksi minun oikeuteni, tuomitset minut syylliseksi, ollaksesi itse oikeassa?'),
(1682779,58,18,40,4,'Tahi onko sinun käsivartesi niinkuin Jumalan, ja voitko korottaa äänesi jylinän niinkuin hän?'),
(1682780,58,18,40,5,'Kaunistaudu kunnialla ja korkeudella, pukeudu loistoon ja kirkkauteen.'),
(1682781,58,18,40,6,'Anna vihasi kiivastuksen purkautua, ja masenna katseellasi kaikki ylpeät.'),
(1682782,58,18,40,7,'Nöyryytä katseellasi kaikki ylpeät, ja muserra jumalattomat siihen paikkaan.'),
(1682783,58,18,40,8,'Kätke heidät tomuun kaikki tyynni, sulje heidän kasvonsa salaiseen kätköön.'),
(1682784,58,18,40,9,'Silloin minäkin ylistän sinua, kun oikea kätesi on hankkinut sinulle voiton.'),
(1682785,58,18,40,10,'Katso Behemotia, jonka minä loin niinkuin sinutkin; se syö ruohoa niinkuin raavas.'),
(1682786,58,18,40,11,'Katso, sen voima on lanteissa, sen väkevyys vatsalihaksissa.'),
(1682787,58,18,40,12,'Se ojentaa jäykäksi häntänsä kuin setripuun, sen reisijänteet ovat lujiksi punotut.'),
(1682788,58,18,40,13,'Sen luut ovat niinkuin vaskiputket, sen nikamat niinkuin raudasta taotut.'),
(1682789,58,18,40,14,'Se on Jumalan töiden esikoinen; sen luoja ojentaa sille miekan.'),
(1682790,58,18,40,15,'Sille kantavat satonsa vuoret, joilla kaikki metsän eläimet leikitsevät.'),
(1682791,58,18,40,16,'Lootuspensaiden alla se makaa, ruovikon ja rämeen kätkössä.'),
(1682792,58,18,40,17,'Lootuspensaat peittävät sen varjoonsa, puron pajut ympäröivät sitä.'),
(1682793,58,18,40,18,'Jos virta hätyyttää, ei se säikähdy, se on huoleton, kuohukoon vaikka itse Jordan sen kitaan.'),
(1682794,58,18,40,19,'Kukapa kävisi kiinni sen silmiin, lävistäisi heittoaseella sen turvan?'),
(1682795,58,18,40,20,'Voitko onkia koukulla Leviatanin ja siimaan kietoa sen kielen?'),
(1682796,58,18,40,21,'Voitko kiinnittää kaislaköyden sen kuonoon ja väkäraudalla lävistää siltä posken?'),
(1682797,58,18,40,22,'Rukoileeko se sinua paljon, tahi puhutteleeko se sinua lempeästi?'),
(1682798,58,18,40,23,'Tekeekö se liiton sinun kanssasi, että saisit sen olemaan orjanasi ainaisesti?'),
(1682799,58,18,40,24,'Voitko leikkiä sillä niinkuin lintusella tahi sitoa sen tyttöjesi pidellä?'),
(1682800,58,18,40,25,'Hierovatko pyyntikunnat siitä kauppaa, jakavatko sen kauppamiesten kesken?'),
(1682801,58,18,40,26,'Voitko iskeä sen nahan täyteen ahinkaita ja sen pään kala-ahraimia?'),
(1682802,58,18,40,27,'(40:32) Laskehan vain kätesi sen päälle, niin muistat sen ottelun; et sitä toiste yritä!'),
(1682803,58,18,40,28,'(41:1) Katso, siinä toivo pettää; jo sen näkemisestä sortuu maahan."'),
(1682804,58,18,41,1,'(41:2) "Ei ole niin rohkeata, joka sitä ärsyttäisi. Kuka sitten kestäisi minun edessäni?'),
(1682805,58,18,41,2,'Kuka on minulle ensin antanut jotakin, joka minun olisi korvattava? Mitä kaiken taivaan alla on, se on minun.'),
(1682806,58,18,41,3,'En saata olla puhumatta sen jäsenistä, en sen voimasta ja sorjasta rakenteesta.'),
(1682807,58,18,41,4,'Kuka voi riisua siltä päällysvaatteen, kuka tunkeutua sen kaksinkertaisten purimien väliin?'),
(1682808,58,18,41,5,'Kuka on avannut sen kasvojen kaksoisoven? Sen hammasten ympärillä on kauhu.'),
(1682809,58,18,41,6,'Sen ylpeytenä ovat uurteiset selkäkilvet, kiinnitetyt lujalla sinetillä.'),
(1682810,58,18,41,7,'Ne käyvät tarkoin toinen toiseensa, niin ettei ilma välitse pääse.'),
(1682811,58,18,41,8,'Ne ovat toisiinsa liitetyt, pysyvät kiinni erkanematta.'),
(1682812,58,18,41,9,'Sen aivastus on kuin valon välähdys, sen silmät ovat kuin aamuruskon silmäripset.'),
(1682813,58,18,41,10,'Sen kidasta lähtee tulisoihtuja, sinkoilee säkeniä.'),
(1682814,58,18,41,11,'Sen sieramista käy savu niinkuin kihisevästä kattilasta ja kaislatulesta.'),
(1682815,58,18,41,12,'Sen puhallus polttaa kuin tuliset hiilet, ja sen suusta lähtee liekki.'),
(1682816,58,18,41,13,'Sen kaulassa asuu voima, ja sen edellä hyppii kauhistus.'),
(1682817,58,18,41,14,'Sen pahkuraiset lihat ovat kiinteät, ovat kuin valetut, järkkymättömät.'),
(1682818,58,18,41,15,'Sen sydän on valettu kovaksi kuin kivi, kovaksi valettu kuin alempi jauhinkivi.'),
(1682819,58,18,41,16,'Kun se nousee, peljästyvät sankarit, kauhusta he tyrmistyvät.'),
(1682820,58,18,41,17,'Jos sen kimppuun käydään miekoin, ei miekka kestä, ei keihäs, ei heittoase eikä panssari.'),
(1682821,58,18,41,18,'Sille on rauta kuin oljenkorsi, vaski kuin lahopuu.'),
(1682822,58,18,41,19,'Ei aja sitä pakoon nuoli, jousen poika, akanoiksi muuttuvat sille linkokivet.'),
(1682823,58,18,41,20,'Kuin oljenkorsi on sille nuija, keihästen ryskeelle se nauraa.'),
(1682824,58,18,41,21,'Sen vatsapuolessa on terävät piikit, se kyntää mutaa leveälti kuin puimaäes.'),
(1682825,58,18,41,22,'Se panee syvyyden kiehumaan kuin padan, tekee meren voidekattilan kaltaiseksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682826,58,18,41,23,'Sen jäljessä polku loistaa, syvyydellä on kuin hopeahapset.'),
(1682827,58,18,41,24,'Ei ole maan päällä sen vertaista; se on luotu pelottomaksi.'),
(1682828,58,18,41,25,'(41:26) Se katsoo ylen kaikkea, mikä korkeata on; se on kaikkien ylväitten eläinten kuningas."'),
(1682829,58,18,42,1,'Silloin Job vastasi Herralle ja sanoi:'),
(1682830,58,18,42,2,'"Minä tiedän, että sinä voit kaikki ja ettei mikään päätöksesi ole sinulle mahdoton toteuttaa.'),
(1682831,58,18,42,3,'''Kuka peittää minun aivoitukseni taitamattomasti?'' Siis on niin: minä puhuin ymmärtämättömästi, asioista, jotka ovat ylen ihmeelliset minun käsittää.'),
(1682832,58,18,42,4,'Kuule siis, niin minä puhun; minä kysyn, opeta sinä minua.'),
(1682833,58,18,42,5,'Korvakuulolta vain olin sinusta kuullut, mutta nyt on silmäni sinut nähnyt.'),
(1682834,58,18,42,6,'Sentähden minä peruutan puheeni ja kadun tomussa ja tuhassa."'),
(1682835,58,18,42,7,'Mutta senjälkeen kuin Herra oli puhunut Jobille nämä sanat, sanoi Herra teemanilaiselle Elifaalle: "Minun vihani on syttynyt sinua ja sinun kahta ystävääsi kohtaan, koska ette ole puhuneet minusta oikein niinkuin minun palvelijani Job.'),
(1682836,58,18,42,8,'Ottakaa siis seitsemän mullikkaa ja seitsemän oinasta, käykää minun palvelijani Jobin luo ja uhratkaa puolestanne polttouhri, ja minun palvelijani Job rukoilkoon teidän puolestanne. Tehdäkseni hänelle mieliksi en saata teitä häpeälliseen rangaistukseen siitä, ettette puhuneet minusta oikein niinkuin minun palvelijani Job."'),
(1682837,58,18,42,9,'Niin teemanilainen Elifas, suuhilainen Bildad ja naemalainen Soofar menivät ja tekivät, niinkuin Herra oli heille puhunut; ja Herra teki Jobille mieliksi.'),
(1682838,58,18,42,10,'Ja kun Job rukoili ystäväinsä puolesta, käänsi Herra Jobin kohtalon, ja Herra antoi Jobille kaikkea kaksin verroin enemmän, kuin hänellä ennen oli ollut.'),
(1682839,58,18,42,11,'Ja kaikki hänen veljensä ja sisarensa ja kaikki hänen entiset tuttavansa tulivat hänen tykönsä ja aterioitsivat hänen kanssaan hänen talossansa, ja he surkuttelivat ja lohduttivat häntä kaikesta siitä onnettomuudesta, jonka Herra oli antanut kohdata häntä. Ja he antoivat kukin hänelle yhden kesitan ja yhden kultarenkaan.'),
(1682840,58,18,42,12,'Ja Herra siunasi Jobin elämän loppupuolta vielä enemmän kuin sen alkua, niin että hän sai neljätoista tuhatta lammasta, kuusi tuhatta kamelia, tuhat härkäparia ja tuhat aasintammaa.'),
(1682841,58,18,42,13,'Ja hän sai seitsemän poikaa ja kolme tytärtä.'),
(1682842,58,18,42,14,'Ensimmäiselle hän antoi nimen Jemima, toiselle nimen Kesia ja kolmannelle nimen Keren-Happuk.'),
(1682843,58,18,42,15,'Eikä ollut koko maassa niin kauniita naisia kuin Jobin tyttäret; ja heidän isänsä antoi heille perintöosan heidän veljiensä rinnalla.'),
(1682844,58,18,42,16,'Tämän jälkeen Job eli vielä sataneljäkymmentä vuotta ja sai nähdä lapsensa ja lastensa lapset neljänteen polveen asti.'),
(1682845,58,19,1,1,'Autuas se mies, joka ei vaella jumalattomain neuvossa eikä astu syntisten teitä eikä istu, kussa pilkkaajat istuvat,'),
(1682846,58,19,1,2,'vaan rakastaa Herran lakia ja tutkistelee hänen lakiansa päivät ja yöt!'),
(1682847,58,19,1,3,'Hän on niinkuin istutettu puu vesiojain tykönä, joka antaa hedelmänsä ajallaan ja jonka lehti ei lakastu; ja kaikki, mitä hän tekee, menestyy.'),
(1682848,58,19,1,4,'Niin eivät jumalattomat! Vaan he ovat kuin akanat, joita tuuli ajaa.'),
(1682849,58,19,1,5,'Sentähden eivät jumalattomat kestä tuomiolla eivätkä syntiset vanhurskasten seurakunnassa.'),
(1682850,58,19,1,6,'Sillä Herra tuntee vanhurskasten tien, mutta jumalattomain tie hukkuu.'),
(1682851,58,19,2,1,'Miksi pakanat pauhaavat ja kansat turhia ajattelevat?'),
(1682852,58,19,2,2,'Maan kuninkaat nousevat, ruhtinaat yhdessä neuvottelevat Herraa ja hänen voideltuansa vastaan:'),
(1682853,58,19,2,3,'"Katkaiskaamme heidän kahleensa, heittäkäämme päältämme heidän köytensä".'),
(1682854,58,19,2,4,'Hän, joka taivaassa asuu, nauraa; Herra pilkkaa heitä.'),
(1682855,58,19,2,5,'Kerran hän on puhuva heille vihassansa, peljättävä heitä hirmuisuudessaan:'),
(1682856,58,19,2,6,'"Minä olen asettanut kuninkaani Siioniin, pyhälle vuorelleni".'),
(1682857,58,19,2,7,'Minä ilmoitan, mitä Herra on säätänyt. Hän lausui minulle: "Sinä olet minun poikani, tänä päivänä minä sinut synnytin.'),
(1682858,58,19,2,8,'Ano minulta, niin minä annan pakanakansat sinun perinnöksesi ja maan ääret sinun omiksesi.'),
(1682859,58,19,2,9,'Rautaisella valtikalla sinä heidät muserrat, niinkuin saviastian sinä särjet heidät."'),
(1682860,58,19,2,10,'Tulkaa siis järkiinne, kuninkaat, maan tuomarit, ottakaa nuhteesta vaari.'),
(1682861,58,19,2,11,'Palvelkaa Herraa pelvolla ja iloitkaa vavistuksella.'),
(1682862,58,19,2,12,'Antakaa suuta pojalle, ettei hän vihastuisi ettekä te hukkuisi tiellänne. Sillä hänen vihansa syttyy äkisti. Autuaat ovat kaikki, jotka häneen turvaavat.'),
(1682863,58,19,3,1,'Daavidin virsi, hänen paetessaan poikaansa Absalomia.'),
(1682864,58,19,3,2,'Herra, kuinka paljon minulla on vihollisia, paljon niitä, jotka nousevat minua vastaan!'),
(1682865,58,19,3,3,'Monet sanovat minusta: "Ei ole hänellä pelastusta Jumalassa". Sela.'),
(1682866,58,19,3,4,'Mutta sinä, Herra, olet minun kilpeni, sinä olet minun kunniani, sinä kohotat minun pääni.'),
(1682867,58,19,3,5,'Ääneeni minä huudan Herraa, ja hän vastaa minulle pyhältä vuoreltansa. Sela.'),
(1682868,58,19,3,6,'Minä käyn levolle ja nukun; minä herään, sillä Herra minua tukee.'),
(1682869,58,19,3,7,'En pelkää kymmentuhantista joukkoa, joka asettuu yltympäri minua vastaan.'),
(1682870,58,19,3,8,'Nouse, Herra, pelasta minut, minun Jumalani! Sillä sinä lyöt poskelle kaikkia minun vihollisiani, sinä murskaat jumalattomain hampaat.'),
(1682871,58,19,3,9,'Herrassa on pelastus; sinun siunauksesi tulkoon sinun kansallesi. Sela.'),
(1682872,58,19,4,1,'Veisuunjohtajalle; kielisoittimilla; Daavidin virsi.'),
(1682873,58,19,4,2,'Vastaa minulle, kun minä huudan, sinä minun vanhurskauteni Jumala, joka ahdingossa avarrat minun tilani. Armahda minua, kuule minun rukoukseni.'),
(1682874,58,19,4,3,'Te miehet, kuinka kauan minun kunniaani pidetään pilkkana, kuinka kauan te rakastatte turhuutta, etsitte valhetta? Sela.'),
(1682875,58,19,4,4,'Tietäkää: ihmeellinen on Herra hurskastansa kohtaan, Herra kuulee, kun minä häntä huudan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682876,58,19,4,5,'Vaviskaa, älkääkä syntiä tehkö. Puhukaa sydämissänne vuoteillanne ja olkaa hiljaa. Sela.'),
(1682877,58,19,4,6,'Uhratkaa vanhurskauden uhreja ja luottakaa Herraan.'),
(1682878,58,19,4,7,'Moni sanoo: "Kuka antaa meille sitä, mikä hyvä on?" Herra, käännä sinä meihin kasvojesi valkeus.'),
(1682879,58,19,4,8,'Sinä annat minun sydämeeni suuremman ilon, kuin heillä on runsaasta viljasta ja viinistä.'),
(1682880,58,19,4,9,'Rauhassa minä käyn levolle ja nukun, sillä sinä, Herra, yksin annat minun turvassa asua.'),
(1682881,58,19,5,1,'Veisuunjohtajalle; huilusoittimilla; Daavidin virsi.'),
(1682882,58,19,5,2,'Ota korviisi minun sanani, Herra, huomaa huokaukseni.'),
(1682883,58,19,5,3,'Kuuntele huutoni ääntä, minun kuninkaani ja Jumalani, sillä sinua minä rukoilen.'),
(1682884,58,19,5,4,'Herra, varhain sinä kuulet minun ääneni, varhain minä valmistan sinulle uhrin ja odotan.'),
(1682885,58,19,5,5,'Sillä sinä et ole se Jumala, jolle jumalattomuus kelpaa. Paha ei saa asua sinun tykönäsi.'),
(1682886,58,19,5,6,'Ylvästelijät eivät kestä sinun silmiesi edessä; sinä vihaat kaikkia väärintekijöitä.'),
(1682887,58,19,5,7,'Sinä hukutat valheen puhujat; murhamiehet ja viekkaat ovat Herralle kauhistus.'),
(1682888,58,19,5,8,'Mutta minä saan sinun suuresta armostasi tulla sinun huoneeseesi, saan kumartaa sinun pyhään temppeliisi päin sinun pelvossasi.'),
(1682889,58,19,5,9,'Herra, johdata minua vanhurskaudessasi minun vihamiesteni tähden, tasoita tiesi minun eteeni.'),
(1682890,58,19,5,10,'Sillä heidän suussaan ei ole luotettavaa sanaa, heidän sisimpänsä on turmiota täynnä, heidän kurkkunsa on avoin hauta, kielellänsä he liukkaasti liehakoivat.'),
(1682891,58,19,5,11,'Tuomitse, Jumala, heidät syyllisiksi, rauetkoon heidän hankkeensa. Kukista heidät heidän rikostensa paljouden tähden, sillä he niskoittelevat sinua vastaan.'),
(1682892,58,19,5,12,'Ja iloitkoot kaikki, jotka sinuun turvaavat, ja riemuitkoot iankaikkisesti. Suojele heitä, että sinussa iloitsisivat ne, jotka rakastavat sinun nimeäsi.'),
(1682893,58,19,5,13,'Sillä sinä, Herra, siunaat vanhurskasta, sinä suojaat häntä armollasi niinkuin kilvellä.'),
(1682894,58,19,6,1,'Veisuunjohtajalle; kielisoittimilla; matalassa äänialassa; Daavidin virsi.'),
(1682895,58,19,6,2,'Herra, älä rankaise minua vihassasi, älä kiivastuksessasi minua kurita.'),
(1682896,58,19,6,3,'Herra, armahda minua, sillä minä olen näännyksissä; paranna minut, Herra, sillä minun luuni ovat peljästyneet,'),
(1682897,58,19,6,4,'ja minun sieluni on kovin peljästynyt. Voi, Herra, kuinka kauan?'),
(1682898,58,19,6,5,'Käänny, Herra, vapahda minun sieluni, pelasta minut armosi tähden.'),
(1682899,58,19,6,6,'Sillä kuolemassa ei sinua muisteta; kuka ylistää sinua tuonelassa?'),
(1682900,58,19,6,7,'Minä olen uupunut huokaamisesta; joka yö minä itken vuoteeni vesille ja kastelen leposijani kyyneleilläni.'),
(1682901,58,19,6,8,'Minun silmäni ovat huienneet surusta, vanhenneet kaikkien vastustajaini tähden.'),
(1682902,58,19,6,9,'Väistykää minusta, kaikki väärintekijät, sillä Herra kuulee minun itkuni äänen.'),
(1682903,58,19,6,10,'Herra kuulee minun anomiseni, Herra ottaa minun rukoukseni vastaan.'),
(1682904,58,19,6,11,'Kaikki minun viholliseni joutuvat häpeään ja suuren pelon valtaan; äkisti he joutuvat häpeään, kääntyvät pois.'),
(1682905,58,19,7,1,'Daavidin virsi, jonka hän veisasi Herralle benjaminilaisen Kuusin sanojen johdosta.'),
(1682906,58,19,7,2,'Herra, minun Jumalani, sinuun minä turvaan; pelasta minut kaikista vainoojistani ja vapahda minut,'),
(1682907,58,19,7,3,'etteivät he raatelisi minua niinkuin leijona ja tempaisi pois - eikä pelastajaa olisi.'),
(1682908,58,19,7,4,'Herra, minun Jumalani, jos minä näin olen tehnyt, jos vääryys minun käsiäni tahraa,'),
(1682909,58,19,7,5,'jos olen tehnyt pahaa niille, jotka elivät rauhassa minun kanssani, tai jos olen ryöstänyt niiltä, jotka syyttä minua ahdistivat,'),
(1682910,58,19,7,6,'niin vainotkoon vihollinen minun henkeäni, saakoon minut kiinni ja polkekoon maahan minun elämäni ja painakoon minun kunniani tomuun. Sela.'),
(1682911,58,19,7,7,'Nouse, Herra, vihassasi. Kohoa minun vastustajaini raivoa vastaan ja heräjä avukseni sinä, joka sääsit tuomion.'),
(1682912,58,19,7,8,'Ympäröikööt sinua kansojen joukot, ja palaja heidän ylitsensä korkeuteen.'),
(1682913,58,19,7,9,'Herra tuomitsee kansat; auta minut oikeuteeni, Herra, minun vanhurskauteni ja viattomuuteni mukaan.'),
(1682914,58,19,7,10,'Loppukoon jumalattomain pahuus, ja vahvista vanhurskaita. Sillä sinä, joka tutkit sydämet ja munaskuut, olet vanhurskas Jumala.'),
(1682915,58,19,7,11,'Minun kilpenäni on Jumala; hän on oikeamielisten pelastaja.'),
(1682916,58,19,7,12,'Jumala on vanhurskas tuomari ja Jumala, joka vihastuu joka päivä.'),
(1682917,58,19,7,13,'Jos kääntymystä ei tule, niin hän teroittaa miekkansa, jännittää jousensa ja tähtää sillä;'),
(1682918,58,19,7,14,'hän valmistaa surma-aseet ja tekee nuolensa palaviksi.'),
(1682919,58,19,7,15,'Katso, tuo hautoo turmiota, kantaa tuhoa kohdussaan, mutta hän synnyttää pettymyksen.'),
(1682920,58,19,7,16,'Hän kaivoi haudan ja koversi sen, mutta itse hän kaatuu tekemäänsä kuoppaan.'),
(1682921,58,19,7,17,'Hänen turmionhankkeensa kääntyy hänen omaan päähänsä, ja hänen vääryytensä lankeaa hänen päälaelleen.'),
(1682922,58,19,7,18,'Minä kiitän Herraa hänen vanhurskaudestansa ja veisaan Herran, Korkeimman, nimen kiitosta.'),
(1682923,58,19,8,1,'Veisuunjohtajalle; veisataan kuin viininkorjuulaulu; Daavidin virsi.'),
(1682924,58,19,8,2,'Herra, meidän Herramme, kuinka korkea onkaan sinun nimesi kaikessa maassa, sinun, joka olet asettanut valtasuuruutesi taivaitten ylitse!'),
(1682925,58,19,8,3,'Lasten ja imeväisten suusta sinä perustit voiman vastustajaisi tähden, että kukistaisit vihollisen ja kostonhimoisen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682926,58,19,8,4,'Kun minä katselen sinun taivastasi, sinun sormiesi tekoa, kuuta ja tähtiä, jotka sinä olet luonut,'),
(1682927,58,19,8,5,'niin mikä on ihminen, että sinä häntä muistat, tai ihmislapsi, että pidät hänestä huolen?'),
(1682928,58,19,8,6,'Ja kuitenkin sinä teit hänestä lähes jumal''olennon, sinä seppelöitsit hänet kunnialla ja kirkkaudella;'),
(1682929,58,19,8,7,'panit hänet hallitsemaan kättesi tekoja, asetit kaikki hänen jalkainsa alle:'),
(1682930,58,19,8,8,'lampaat ja karjan, ne kaikki, niin myös metsän eläimet,'),
(1682931,58,19,8,9,'taivaan linnut ja meren kalat ja kaiken, mikä meren polkuja kulkee.'),
(1682932,58,19,8,10,'Herra, meidän Herramme, kuinka korkea onkaan sinun nimesi kaikessa maassa!'),
(1682933,58,19,9,1,'Veisuunjohtajalle; veisataan kuin: "Kuole pojan puolesta"; Daavidin virsi.'),
(1682934,58,19,9,2,'Minä ylistän Herraa kaikesta sydämestäni, ilmoitan kaikki sinun ihmetyösi.'),
(1682935,58,19,9,3,'Minä iloitsen ja riemuitsen sinussa, veisaan sinun nimesi kiitosta, sinä Korkein.'),
(1682936,58,19,9,4,'Sillä minun viholliseni peräytyivät, kaatuivat maahan ja hukkuivat sinun kasvojesi edessä.'),
(1682937,58,19,9,5,'Sinä hankit minulle oikeuden ja ajoit minun asiani, sinä istuit valtaistuimelle, sinä vanhurskas tuomari.'),
(1682938,58,19,9,6,'Sinä nuhtelit pakanoita, tuhosit jumalattomat; sinä pyyhit pois heidän nimensä iäksi ja ainiaaksi.'),
(1682939,58,19,9,7,'Viholliset ovat tuhotut, ikuisiksi raunioiksi tulleet; kaupungit sinä kukistit, heidän muistonsa on kadonnut.'),
(1682940,58,19,9,8,'Mutta Herra hallitsee iankaikkisesti; hän on pystyttänyt istuimensa tuomitaksensa.'),
(1682941,58,19,9,9,'Hän tuomitsee maanpiirin vanhurskaasti, vallitsee kansoja oikeuden mukaan.'),
(1682942,58,19,9,10,'Niin Herra on sorretun linna, linna ahdingon aikoina.'),
(1682943,58,19,9,11,'Ja sinuun turvaavat ne, jotka sinun nimesi tuntevat; sillä sinä et hylkää niitä, jotka sinua etsivät, Herra.'),
(1682944,58,19,9,12,'Veisatkaa kiitosta Herralle, joka Siionissa asuu, julistakaa kansojen keskuudessa hänen suuria tekojaan.'),
(1682945,58,19,9,13,'Sillä hän, verenkostaja, muistaa heitä eikä unhota kurjain huutoa.'),
(1682946,58,19,9,14,'Armahda minua, Herra, katso, kuinka minun vihamieheni minua vaivaavat, sinä, joka nostat minut kuoleman porteista,'),
(1682947,58,19,9,15,'että minä julistaisin kaikki sinun ylistettävät tekosi, tytär Siionin porteissa, riemuitsisin sinun avustasi.'),
(1682948,58,19,9,16,'Pakanat ovat vajonneet kaivamaansa hautaan; heidän jalkansa takertui verkkoon, jonka he virittivät.'),
(1682949,58,19,9,17,'Herra on tehnyt itsensä tunnetuksi, on pitänyt tuomiot, kietonut jumalattoman hänen kättensä tekoihin. - Kanteleen välisoitto. Sela.'),
(1682950,58,19,9,18,'Jumalattomat peräytyvät tuonelaan, kaikki pakanat, jotka unhottavat Jumalan.'),
(1682951,58,19,9,19,'Sillä ei köyhää unhoteta iäksi, eikä kurjien toivo huku ainiaaksi.'),
(1682952,58,19,9,20,'Nouse, Herra, älä salli ihmisten uhitella. Tuomittakoon pakanat sinun kasvojesi edessä.'),
(1682953,58,19,9,21,'Saata, Herra, heidät pelkoon. Tietäkööt pakanat olevansa vain ihmisiä. Sela.'),
(1682954,58,19,10,1,'Miksi, Herra, seisot niin kaukana, miksi kätkeydyt ahdingon aikoina?'),
(1682955,58,19,10,2,'Jumalattomien ylpeyden tähden kurja kärsii, takertuu heidän punomiinsa juoniin.'),
(1682956,58,19,10,3,'Sillä jumalaton kerskaa omista himoistansa, ja kiskuri kiroaa, pilkkaa Herraa.'),
(1682957,58,19,10,4,'Jumalaton sanoo ylvästellen: "Ei hän kosta". "Ei Jumalaa ole" - siinä kaikki hänen ajatuksensa.'),
(1682958,58,19,10,5,'Hänen hankkeensa menestyvät joka aika. Sinun tuomiosi ovat korkealla, kaukana hänestä; kaikille vastustajilleen hän hymähtää.'),
(1682959,58,19,10,6,'Hän sanoo sydämessään: "En horju minä, en ikinä joudu onnettomuuteen".'),
(1682960,58,19,10,7,'Hänen suunsa on täynnä kirousta, petosta, sortoa; tuho ja turmio on hänen kielensä alla.'),
(1682961,58,19,10,8,'Kylien vaiheilla hän istuu väijyksissä, hän murhaa salaa syyttömän. Hänen silmänsä vaanivat onnetonta.'),
(1682962,58,19,10,9,'Kätkössään hän väijyy, niinkuin leijona pensaikossa, hän väijyy hyökätäksensä kurjan kimppuun; hän saa kurjan kiinni, vetää hänet verkkoonsa.'),
(1682963,58,19,10,10,'Hän kyyristyy, painautuu maahan, ja onnettomat joutuvat hänen kynsiinsä.'),
(1682964,58,19,10,11,'Hän sanoo sydämessään: "Jumala sen unhottaa, hän on peittänyt kasvonsa, hän ei sitä ikinä näe".'),
(1682965,58,19,10,12,'Nouse, Herra, kohota kätesi, Jumala! Älä unhota kurjia.'),
(1682966,58,19,10,13,'Miksi jumalaton pilkkaa Jumalaa? Miksi hän sanoo sydämessään: "Et sinä kosta?"'),
(1682967,58,19,10,14,'Sinä olet sen nähnyt, sillä sinä havaitset vaivan ja tuskan, ja sinä otat sen oman kätesi huomaan; sinulle onneton uskoo asiansa, sinä olet orpojen auttaja.'),
(1682968,58,19,10,15,'Murskaa jumalattoman käsivarsi ja kosta pahan jumalattomuus, niin ettei häntä enää löydetä.'),
(1682969,58,19,10,16,'Herra on kuningas ainiaan ja iankaikkisesti; hävinneet ovat pakanat hänen maastansa.'),
(1682970,58,19,10,17,'Sinä kuulet nöyrien halajamisen, Herra, sinä vahvistat heidän sydämensä, sinä teroitat korvasi,'),
(1682971,58,19,10,18,'auttaaksesi orvon ja sorretun oikeuteensa, ettei ihminen, joka maasta on, enää saisi kauhua aikaan.'),
(1682972,58,19,11,1,'Veisuunjohtajalle; Daavidin virsi. Herraan minä turvaan; kuinka te sanotte minulle: "Paetkaa vuorellenne niinkuin linnut!'),
(1682973,58,19,11,2,'Sillä katso, jumalattomat jännittävät jousensa, ovat panneet nuolensa jänteelle oikeamielisiä pimeässä ampuaksensa.'),
(1682974,58,19,11,3,'Kun peruspylväät murretaan maahan, mitä voi vanhurskas tehdä?"'),
(1682975,58,19,11,4,'Herra pyhässä temppelissänsä, Herra, jonka istuin on taivaassa - hänen silmänsä näkevät, hänen katseensa tutkii ihmislapset;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1682976,58,19,11,5,'Herra tutkii vanhurskaat, mutta jumalattomia ja niitä, jotka vääryyttä rakastavat, hänen sielunsa vihaa.'),
(1682977,58,19,11,6,'Hän antaa sataa jumalattomien päälle pauloja, tulta ja tulikiveä; polttava tuuli on heidän maljansa osa.'),
(1682978,58,19,11,7,'Sillä Herra on vanhurskas ja rakastaa vanhurskautta; oikeamieliset saavat katsella hänen kasvojansa.'),
(1682979,58,19,12,1,'Veisuunjohtajalle; matalassa äänialassa; Daavidin virsi.'),
(1682980,58,19,12,2,'Auta, Herra, sillä hurskaat ovat hävinneet, uskolliset ovat kadonneet ihmislasten joukosta.'),
(1682981,58,19,12,3,'He puhuvat valhetta toinen toisellensa, puhuvat liukkain huulin, kaksimielisin sydämin.'),
(1682982,58,19,12,4,'Hävittäköön Herra kaikki liukkaat huulet, kielen, joka kerskuen puhuu,'),
(1682983,58,19,12,5,'ne, jotka sanovat: "Kielemme voimalla me olemme väkevät; huulemme ovat meidän tukemme; kuka on meille herra?"'),
(1682984,58,19,12,6,'"Kurjien sorron tähden, köyhien huokausten tähden minä nyt nousen", sanoo Herra, "tuon pelastuksen sille, joka sitä huoaten ikävöitsee".'),
(1682985,58,19,12,7,'Herran sanat ovat selkeitä sanoja, hopeata, joka kirkkaana valuu sulattimesta maahan, seitsenkertaisesti puhdistettua.'),
(1682986,58,19,12,8,'Sinä, Herra, varjelet heitä, suojelet hänet iäti tältä sukukunnalta.'),
(1682987,58,19,12,9,'Yltympäri jumalattomat rehentelevät, kun kataluus pääsee valtaan ihmislasten seassa.'),
(1682988,58,19,13,1,'Veisuunjohtajalle; Daavidin virsi.'),
(1682989,58,19,13,2,'Kuinka kauan, Herra, minut yhä unhotat, kuinka kauan kätket minulta kasvosi?'),
(1682990,58,19,13,3,'Kuinka kauan minun täytyy kantaa huolia sielussani, päivät päästään murhetta sydämessäni? Kuinka kauan saa vihollinen ylvästellä minua vastaan?'),
(1682991,58,19,13,4,'Katsahda tänne, vastaa minulle, Herra, minun Jumalani. Valaise silmäni, etten nukkuisi kuolemaan,'),
(1682992,58,19,13,5,'ettei minun viholliseni sanoisi: "Minä voitin hänet", etteivät ahdistajani riemuitsisi, kun minä horjun.'),
(1682993,58,19,13,6,'Mutta minä turvaan sinun armoosi; riemuitkoon minun sydämeni sinun avustasi. Minä veisaan Herralle, sillä hän on tehnyt minulle hyvin.'),
(1682994,58,19,14,1,'Veisuunjohtajalle; Daavidin virsi. Hullu sanoo sydämessänsä: "Ei ole Jumalaa". Turmiollinen ja iljettävä on heidän menonsa; ei ole ketään, joka tekee, mikä hyvää on.'),
(1682995,58,19,14,2,'Herra katsoo taivaasta ihmislapsiin nähdäksensä, onko ketään ymmärtäväistä, ketään, joka etsii Jumalaa.'),
(1682996,58,19,14,3,'Mutta kaikki ovat poikenneet pois, kaikki tyynni kelvottomiksi käyneet; ei ole ketään, joka tekee sitä, mikä hyvää on, ei yhden yhtäkään.'),
(1682997,58,19,14,4,'Eivätkö he mitään käsitä, kaikki nuo väärintekijät, jotka saavat leipänsä syömällä minun kansaani eivätkä avuksensa huuda Herraa?'),
(1682998,58,19,14,5,'Siinä heidät valtaa kauhu, sillä Jumala on läsnä vanhurskasten sukukunnassa.'),
(1682999,58,19,14,6,'Te saatatte häpeään sorretun aikeet, mutta Herra on heidän turvansa.'),
(1683000,58,19,14,7,'Oi, että Israelin pelastus tulisi Siionista! Kun Herra kääntää kansansa kohtalon, silloin Jaakob riemuitsee, Israel iloitsee.'),
(1683001,58,19,15,1,'Daavidin virsi. Herra, kuka saa vierailla sinun majassasi, kuka asua sinun pyhällä vuorellasi?'),
(1683002,58,19,15,2,'Se, joka vaeltaa nuhteettomasti, joka tekee vanhurskauden ja puhuu sydämessänsä totuutta;'),
(1683003,58,19,15,3,'joka ei panettele kielellänsä, joka ei tee toiselle pahaa eikä saata lähimmäistään häväistyksen alaiseksi;'),
(1683004,58,19,15,4,'joka halveksuu hylkiötä, mutta kunnioittaa niitä, jotka pelkäävät Herraa; joka ei valaansa riko, vaikka on vannonut vahingokseen;'),
(1683005,58,19,15,5,'joka ei anna rahaansa korolle eikä ota lahjuksia viatonta vastaan. Joka näin tekee, hän ei ikinä horju.'),
(1683006,58,19,16,1,'Daavidin laulu. Varjele minua, Jumala, sillä sinuun minä turvaan.'),
(1683007,58,19,16,2,'Minä sanon Herralle: "Sinä olet minun Herrani, paitsi sinua ei ole minulla mitään hyvää";'),
(1683008,58,19,16,3,'ja pyhille, jotka maassa ovat: "Nämä ovat ne jalot, joihin on koko minun mielisuosioni".'),
(1683009,58,19,16,4,'Monta tuskaa on niillä, jotka ottavat vieraan jumalan; minä en uhraa niille verta juomauhriksi enkä päästä huulilleni niiden nimiä.'),
(1683010,58,19,16,5,'Herra on minun pelto- ja malja-osani; sinä hoidat minun arpani.'),
(1683011,58,19,16,6,'Arpa lankesi minulle ihanasta maasta, ja kaunis on minun perintöosani.'),
(1683012,58,19,16,7,'Minä kiitän Herraa, joka on minua neuvonut; yölläkin minua siihen sisimpäni kehoittaa.'),
(1683013,58,19,16,8,'Minä pidän Herran aina edessäni; kun hän on minun oikealla puolellani, en minä horju.'),
(1683014,58,19,16,9,'Sentähden minun sydämeni iloitsee ja sieluni riemuitsee, ja myös minun ruumiini asuu turvassa.'),
(1683015,58,19,16,10,'Sillä sinä et hylkää minun sieluani tuonelaan etkä anna hurskaasi nähdä kuolemaa.'),
(1683016,58,19,16,11,'Sinä neuvot minulle elämän tien; ylenpalttisesti on iloa sinun kasvojesi edessä, ihanuutta sinun oikeassa kädessäsi iankaikkisesti.'),
(1683017,58,19,17,1,'Daavidin rukous. Kuule, Herra, minun oikeata asiaani, tarkkaa minun huutoani, ota korviisi minun rukoukseni, joka ei lähde petollisilta huulilta.'),
(1683018,58,19,17,2,'Sinulta tulee minulle oikeus, sinun silmäsi katsovat sitä, mikä oikein on.'),
(1683019,58,19,17,3,'Sinä koettelet minun sydäntäni, tarkkaat sitä yöllä, sinä tutkit minua, mutta et mitään löydä. Jos minä pahaa ajattelen, ei se käy suustani ulos.'),
(1683020,58,19,17,4,'Mitä ihmiset tehköötkin, sinun huultesi sanassa minä pysyn ja kavahdan väkivaltaisen teitä.'),
(1683021,58,19,17,5,'Minun askeleeni pysyvät sinun poluillasi, minun jalkani eivät horju.'),
(1683022,58,19,17,6,'Minä huudan sinua avukseni, sillä sinä vastaat minulle, Jumala; kallista korvasi minun puoleeni, kuule minun puheeni.'),
(1683023,58,19,17,7,'Osoita ihmeellinen armosi, sinä, joka pelastat vihamiesten vallasta ne, jotka turvaavat sinun oikeaan käteesi.'),
(1683024,58,19,17,8,'Varjele minua niinkuin silmäterää, kätke minut siipiesi suojaan'),
(1683025,58,19,17,9,'jumalattomilta, jotka tahtovat minut tuhota, verivihollisiltani, jotka minua saartavat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683026,58,19,17,10,'He ovat sulkeneet tunnottomat sydämensä, heidän suunsa puhuu ylvästellen.'),
(1683027,58,19,17,11,'He ovat kintereillämme, he jo kiertävät meidät, he vaanivat silmillään, lyödäksensä maahan.'),
(1683028,58,19,17,12,'Hän on niinkuin saalista himoitseva leijona, niinkuin nuori leijona, joka piilossa väijyy.'),
(1683029,58,19,17,13,'Nouse, Herra, astu hänen eteensä. Paiskaa hänet maahan. Vapahda miekallasi minun sieluni jumalattomista,'),
(1683030,58,19,17,14,'kädelläsi ihmisistä, Herra, tämän maailman ihmisistä, joiden osa on tässä elämässä, joiden vatsan sinä täytät antimillasi, joiden pojat tulevat ravituiksi ja jotka jättävät yltäkylläisyytensä lapsilleen.'),
(1683031,58,19,17,15,'Mutta minä saan nähdä sinun kasvosi vanhurskaudessa, herätessäni ravita itseni sinun muotosi katselemisella.'),
(1683032,58,19,18,1,'Veisuunjohtajalle; Herran palvelijan Daavidin virsi, jonka sanat hän puhui Herralle sinä päivänä, jona Herra oli pelastanut hänet kaikkien hänen vihollistensa vallasta ja Saulin kädestä.'),
(1683033,58,19,18,2,'Hän sanoi: Sydämestäni minä rakastan sinua, Herra, minun voimani,'),
(1683034,58,19,18,3,'Herra, minun kallioni, linnani ja pelastajani, minun Jumalani, vuoreni, jonka turviin minä pakenen, minun kilpeni, autuuteni sarvi ja varustukseni.'),
(1683035,58,19,18,4,'Ylistetty olkoon Herra! - niin minä huudan, ja vihollisistani minä pelastun.'),
(1683036,58,19,18,5,'Kuoleman paulat piirittivät minut, turmion virrat peljästyttivät minut.'),
(1683037,58,19,18,6,'Tuonelan paulat kietoivat minut, kuoleman ansat yllättivät minut.'),
(1683038,58,19,18,7,'Ahdistuksessani minä rukoilin Herraa ja huusin avuksi Jumalaani; hän kuuli minun ääneni temppelistänsä, ja minun huutoni hänen edessään kohosi hänen korviinsa.'),
(1683039,58,19,18,8,'Silloin maa huojui ja järisi, vuorten perustukset järkkyivät; ne horjuivat, sillä hänen vihansa syttyi.'),
(1683040,58,19,18,9,'Savu suitsusi hänen sieraimistaan, kuluttava tuli hänen suustansa, palavat hiilet hehkuivat hänestä.'),
(1683041,58,19,18,10,'Hän notkisti taivaat ja astui alas, synkkä pilvi jalkojensa alla.'),
(1683042,58,19,18,11,'Ja hän ajoi kerubin kannattamana ja lensi, ja hän liiti tuulen siivillä;'),
(1683043,58,19,18,12,'hän pani pimeyden verhoksensa, majaksensa yltympäri: mustat vedet, paksut pilvet.'),
(1683044,58,19,18,13,'Hohteesta, joka kävi hänen edellänsä, purkautuivat pilvet rakeiksi ja palaviksi hiiliksi.'),
(1683045,58,19,18,14,'Ja Herra jylisi taivaassa, Korkein antoi äänensä kaikua, tulla rakeita ja palavia hiiliä.'),
(1683046,58,19,18,15,'Hän lennätti nuolensa ja hajotti heidät, paljon salamoita ja kauhistutti heidät.'),
(1683047,58,19,18,16,'Silloin vetten syvyydet tulivat näkyviin, ja maanpiirin perustukset paljastuivat sinun nuhtelustasi, Herra, sinun vihasi hengen puuskauksesta.'),
(1683048,58,19,18,17,'Hän ojensi kätensä korkeudesta ja tarttui minuun, veti minut ylös suurista vesistä;'),
(1683049,58,19,18,18,'hän pelasti minut voimallisesta vihollisestani, minun vihamiehistäni, sillä he olivat minua väkevämmät.'),
(1683050,58,19,18,19,'He hyökkäsivät minun kimppuuni hätäni päivänä, mutta Herra tuli minun tuekseni.'),
(1683051,58,19,18,20,'Hän toi minut avaraan paikkaan, hän vapautti minut, sillä hän oli mielistynyt minuun.'),
(1683052,58,19,18,21,'Herra tekee minulle minun vanhurskauteni mukaan, minun kätteni puhtauden mukaan hän minulle maksaa.'),
(1683053,58,19,18,22,'Sillä minä olen noudattanut Herran teitä enkä ole luopunut pois Jumalastani, jumalattomuuteen.'),
(1683054,58,19,18,23,'Kaikki hänen oikeutensa ovat minun silmieni edessä, enkä minä hänen käskyjänsä syrjään sysää.'),
(1683055,58,19,18,24,'Minä olen vilpitön häntä kohtaan ja varon itseni pahoista teoista.'),
(1683056,58,19,18,25,'Sentähden Herra palkitsee minulle minun vanhurskauteni mukaan, sen mukaan kuin käteni ovat puhtaat hänen silmiensä edessä.'),
(1683057,58,19,18,26,'Hurskasta kohtaan sinä olet hurskas, nuhteetonta kohtaan nuhteeton;'),
(1683058,58,19,18,27,'puhdasta kohtaan sinä olet puhdas, mutta kieroa kohtaan nurja.'),
(1683059,58,19,18,28,'Sillä sinä pelastat nöyrän kansan, mutta ylpeät silmät sinä painat alas.'),
(1683060,58,19,18,29,'Sillä sinä annat minun lamppuni loistaa; Herra, minun Jumalani, valaisee minun pimeyteni.'),
(1683061,58,19,18,30,'Sinun avullasi minä hyökkään rosvojoukkoa vastaan; Jumalani avulla minä ryntään ylitse muurin.'),
(1683062,58,19,18,31,'Jumalan tie on nuhteeton, Herran sana tulessa koeteltu. Hän on kaikkien kilpi, jotka häneen turvaavat.'),
(1683063,58,19,18,32,'Sillä kuka muu on Jumala kuin Herra, ja kuka pelastuksen kallio, paitsi meidän Jumalamme -'),
(1683064,58,19,18,33,'se Jumala, joka minut voimalla vyöttää ja tekee minun tieni nuhteettomaksi,'),
(1683065,58,19,18,34,'tekee minun jalkani nopeiksi niinkuin peurat ja asettaa minut kukkuloilleni,'),
(1683066,58,19,18,35,'joka opettaa minun käteni sotimaan ja käsivarteni vaskijousta jännittämään!'),
(1683067,58,19,18,36,'Sinä annat minulle pelastuksen kilven, ja sinun oikea kätesi minua tukee; sinun laupeutesi tekee minut suureksi.'),
(1683068,58,19,18,37,'Sinä annat minun askeleilleni avaran tilan, ja minun jalkani eivät horju.'),
(1683069,58,19,18,38,'Minä ajan vihollisiani takaa ja saavutan heidät enkä palaja, ennenkuin teen heistä lopun;'),
(1683070,58,19,18,39,'minä murskaan heidät, niin etteivät voi nousta, he sortuvat minun jalkojeni alle.'),
(1683071,58,19,18,40,'Sinä vyötät minut voimalla sotaan, sinä painat vastustajani minun alleni.'),
(1683072,58,19,18,41,'Sinä ajat minun viholliseni pakoon, ja vihamieheni minä hukutan.'),
(1683073,58,19,18,42,'He huutavat, mutta pelastajaa ei ole, huutavat Herraa, mutta hän ei heille vastaa.'),
(1683074,58,19,18,43,'Minä survon heidät tomuksi tuuleen, viskaan heidät niinkuin loan kadulle.'),
(1683075,58,19,18,44,'Sinä pelastat minut kansan riidoista, sinä asetat minut pakanain pääksi, kansat, joita minä en tunne, palvelevat minua.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683076,58,19,18,45,'Jo korvan kuulemalta he minua tottelevat; muukalaiset matelevat minun edessäni.'),
(1683077,58,19,18,46,'Muukalaiset masentuvat ja tulevat vavisten varustuksistansa.'),
(1683078,58,19,18,47,'Herra elää! Kiitetty olkoon minun kallioni ja ylistetty minun pelastukseni Jumala,'),
(1683079,58,19,18,48,'Jumala, joka hankkii minulle koston ja saattaa kansat minun valtani alle;'),
(1683080,58,19,18,49,'sinä, joka pelastat minut vihollisistani ja korotat minut vastustajaini ylitse ja päästät minut väkivaltaisesta miehestä.'),
(1683081,58,19,18,50,'Sentähden minä ylistän sinua, Herra, kansojen keskuudessa ja veisaan sinun nimesi kiitosta,'),
(1683082,58,19,18,51,'sinun, joka annat kuninkaallesi suuren avun ja teet laupeuden voidellullesi, Daavidille ja hänen jälkeläisilleen, iankaikkisesti.'),
(1683083,58,19,19,1,'Veisuunjohtajalle; Daavidin virsi.'),
(1683084,58,19,19,2,'Taivaat julistavat Jumalan kunniaa, taivaanvahvuus ilmoittaa hänen kättensä tekoja.'),
(1683085,58,19,19,3,'Päivä sanoo päivälle, ja yö ilmoittaa yölle.'),
(1683086,58,19,19,4,'Se ei ole puhetta, se ei ole kieltä, jonka ääni ei kuuluisi.'),
(1683087,58,19,19,5,'Niiden mittanuora ulottuu yli kaiken maan ja niiden sanat maanpiirin ääriin. Auringolle hän on tehnyt niihin majan.'),
(1683088,58,19,19,6,'Se on niinkuin ylkä, joka tulee kammiostaan, se riemuitsee kuin sankari rataansa juostessaan.'),
(1683089,58,19,19,7,'Se nousee taivasten ääristä ja kiertää niiden toisiin ääriin, eikä mikään voi lymytä sen helteeltä.'),
(1683090,58,19,19,8,'Herran laki on täydellinen; se virvoittaa sielun. Herran todistus on vahva, se tekee tyhmästä viisaan.'),
(1683091,58,19,19,9,'Herran asetukset ovat oikeat, ne ilahuttavat sydämen. Herran käskyt ovat selkeät, ne valaisevat silmät.'),
(1683092,58,19,19,10,'Herran pelko on puhdas, se pysyy iäti. Herran oikeudet ovat todet, kaikki tyynni vanhurskaat.'),
(1683093,58,19,19,11,'Ne ovat kalliimmat kultaa, puhtaan kullan paljoutta, makeammat hunajaa ja mehiläisen mettä.'),
(1683094,58,19,19,12,'Myös sinun palvelijasi ottaa niistä vaarin, niiden noudattamisesta on suuri palkka.'),
(1683095,58,19,19,13,'Erhetykset kuka ymmärtää? Anna anteeksi minun salaiset syntini.'),
(1683096,58,19,19,14,'Myös varjele palvelijasi julkeilta, älä anna heidän minua hallita. Niin minä pysyn nuhteetonna ja olen paljosta synnistä puhdas.'),
(1683097,58,19,19,15,'Kelvatkoot sinulle minun suuni sanat ja minun sydämeni ajatukset sinun edessäsi, Herra, minun kallioni ja lunastajani.'),
(1683098,58,19,20,1,'Veisuunjohtajalle; Daavidin virsi.'),
(1683099,58,19,20,2,'Kuulkoon Herra sinua hädän päivänä, varjelkoon sinua Jaakobin Jumalan nimi.'),
(1683100,58,19,20,3,'Hän lähettäköön sinulle avun pyhäköstä ja tukekoon sinua Siionista.'),
(1683101,58,19,20,4,'Muistakoon hän kaikki sinun uhrilahjasi, ja olkoon sinun polttouhrisi lihava hänen silmissään. Sela.'),
(1683102,58,19,20,5,'Hän antakoon sinulle, mitä sydämesi halajaa, ja täyttäköön kaikki sinun aivoituksesi.'),
(1683103,58,19,20,6,'Suotakoon meidän riemuita sinun voitostasi ja nostaa lippumme Jumalamme nimeen. Täyttäköön Herra kaikki sinun pyyntösi.'),
(1683104,58,19,20,7,'Nyt minä tiedän, että Herra auttaa voideltuansa, vastaa hänelle pyhästä taivaastansa, auttaa häntä oikean kätensä voimallisilla teoilla.'),
(1683105,58,19,20,8,'Toiset turvaavat vaunuihin, toiset hevosiin, mutta me tunnustamme Herran, Jumalamme, nimeä.'),
(1683106,58,19,20,9,'He vaipuvat maahan ja kaatuvat, mutta me nousemme ja pysymme pystyssä.'),
(1683107,58,19,20,10,'Herra, auta! Vastatkoon kuningas meille, kun huudamme.'),
(1683108,58,19,21,1,'Veisuunjohtajalle; Daavidin virsi.'),
(1683109,58,19,21,2,'Herra, sinun voimastasi kuningas iloitsee; kuinka suuresti hän riemuitseekaan sinun avustasi!'),
(1683110,58,19,21,3,'Mitä hänen sydämensä halasi, sen sinä hänelle annoit, et kieltänyt, mitä hänen huulensa anoivat. Sela.'),
(1683111,58,19,21,4,'Sinä suot hänelle onnen ja siunauksen, panet hänen päähänsä kultaisen kruunun.'),
(1683112,58,19,21,5,'Hän anoi sinulta elämää, sen sinä hänelle annoit: iän pitkän, ainaisen, iankaikkisen.'),
(1683113,58,19,21,6,'Suuri on hänen kunniansa, kun sinä häntä autoit; sinä peität hänet loistolla ja kirkkaudella.'),
(1683114,58,19,21,7,'Sillä sinä asetat hänet suureksi siunaukseksi ikuisiin aikoihin asti; sinä ilahutat häntä riemulla kasvojesi edessä.'),
(1683115,58,19,21,8,'Sillä kuningas luottaa Herraan, ja Korkeimman armo tekee hänet horjumattomaksi.'),
(1683116,58,19,21,9,'Sinun kätesi saavuttaa kaikki sinun vihollisesi, sinun oikea kätesi saavuttaa sinun vihamiehesi.'),
(1683117,58,19,21,10,'Sinä panet heidät hehkumaan kuin pätsin, kun sinä kasvosi näytät; Herra nielee heidät vihassansa, tuli kuluttaa heidät.'),
(1683118,58,19,21,11,'Sinä hävität maan päältä heidän hedelmänsä ja heidän jälkeläisensä ihmislasten keskuudesta.'),
(1683119,58,19,21,12,'Vaikka he hankkivat pahaa sinua vastaan, miettivät juonia, eivät he mitään voi;'),
(1683120,58,19,21,13,'sillä sinä ajat heidät pakoon, tähtäät heitä kasvoihin jousesi jänteellä.'),
(1683121,58,19,21,14,'Nouse voimassasi, Herra! Laulaen ja veisaten me ylistämme sinun väkevyyttäsi.'),
(1683122,58,19,22,1,'Veisuunjohtajalle; veisataan kuin: "Aamuruskon peura"; Daavidin virsi.'),
(1683123,58,19,22,2,'Jumalani, Jumalani, miksi minut hylkäsit? Miksi olet kaukana, et auta minua, et kuule valitukseni sanoja?'),
(1683124,58,19,22,3,'Jumalani, minä huudan päivällä, mutta sinä et vastaa, ja yöllä, enkä voi vaieta.'),
(1683125,58,19,22,4,'Ja kuitenkin sinä olet Pyhä, jonka istuin on Israelin kiitosvirtten keskellä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683126,58,19,22,5,'Meidän isämme luottivat sinuun, he luottivat, ja sinä pelastit heidät.'),
(1683127,58,19,22,6,'He huusivat sinua ja pelastuivat; he luottivat sinuun eivätkä tulleet häpeään.'),
(1683128,58,19,22,7,'Mutta minä olen mato enkä ihminen, ihmisten pilkka ja kansan hylky.'),
(1683129,58,19,22,8,'Kaikki, jotka minut näkevät, pilkkaavat minua, levittelevät suutansa, nyökyttävät ilkkuen päätään:'),
(1683130,58,19,22,9,'"Jätä asiasi Herran haltuun. Hän vapahtakoon hänet, hän pelastakoon hänet, koska on häneen mielistynyt."'),
(1683131,58,19,22,10,'Sinähän vedit minut äitini kohdusta, sinä annoit minun olla turvassa äitini rinnoilla;'),
(1683132,58,19,22,11,'sinun huomaasi minä olen jätetty syntymästäni saakka, sinä olet minun Jumalani hamasta äitini kohdusta.'),
(1683133,58,19,22,12,'Älä ole minusta kaukana, sillä ahdistus on läsnä, eikä auttajaa ole.'),
(1683134,58,19,22,13,'Minua saartavat väkevät sonnit, Baasanin härät piirittävät minut,'),
(1683135,58,19,22,14,'avaavat kitansa minua vastaan, niinkuin raatelevat, kiljuvat leijonat.'),
(1683136,58,19,22,15,'Niinkuin vesi minä olen maahan vuodatettu; kaikki minun luuni ovat irti toisistansa; minun sydämeni on niinkuin vaha, se on sulanut minun rinnassani.'),
(1683137,58,19,22,16,'Minun voimani on kuivettunut kuin saviastian siru, ja kieleni tarttuu suuni lakeen, ja sinä lasket minut alas kuoleman tomuun.'),
(1683138,58,19,22,17,'Sillä koirat minua piirittävät, pahain parvi saartaa minut, minun käteni ja jalkani, niinkuin jalopeurat.'),
(1683139,58,19,22,18,'Minä voin lukea kaikki luuni; he katselevat minua ilkkuen;'),
(1683140,58,19,22,19,'he jakavat keskenänsä minun vaatteeni ja heittävät minun puvustani arpaa.'),
(1683141,58,19,22,20,'Mutta sinä, Herra, älä ole kaukana, sinä, minun väkevyyteni, riennä avukseni.'),
(1683142,58,19,22,21,'Vapahda minun sieluni miekasta, minun ainokaiseni koirain kynsistä.'),
(1683143,58,19,22,22,'Pelasta minut jalopeuran kidasta, villihärkäin sarvista - vastaa minulle.'),
(1683144,58,19,22,23,'Minä julistan sinun nimeäsi veljilleni, ylistän sinua seurakunnan keskellä.'),
(1683145,58,19,22,24,'Te, jotka pelkäätte Herraa, ylistäkää häntä. Kunnioittakaa häntä, kaikki Jaakobin siemen, kaikki Israelin siemen, peljätkää häntä.'),
(1683146,58,19,22,25,'Sillä hän ei halveksi kurjan kärsimystä, ei katso sitä ylen, eikä kätke häneltä kasvojansa, vaan kuulee hänen avuksihuutonsa.'),
(1683147,58,19,22,26,'Sinusta on minun ylistyslauluni suuressa seurakunnassa; minä täytän lupaukseni häntä pelkääväisten edessä.'),
(1683148,58,19,22,27,'Nöyrät saavat syödä ja tulevat ravituiksi; ne, jotka etsivät Herraa, ylistävät häntä. Teidän sydämenne on elävä iankaikkisesti.'),
(1683149,58,19,22,28,'Kaikki maan ääret muistavat tämän ja palajavat Herran tykö; kaikki pakanain sukukunnat kumartavat häntä;'),
(1683150,58,19,22,29,'sillä Herran on kuninkuus, ja hän on hallitseva pakanoita.'),
(1683151,58,19,22,30,'Kaikki maan mahtavat syövät ja kumartavat; hänen edessään polvistuvat kaikki, jotka mullan alle astuvat eivätkä voi elossa pysyä.'),
(1683152,58,19,22,31,'Jälkeentulevaiset palvelevat häntä, tuleville polville kerrotaan Herrasta.'),
(1683153,58,19,22,32,'He tulevat ja julistavat vastedes syntyvälle kansalle hänen vanhurskauttaan, että hän on tämän tehnyt.'),
(1683154,58,19,23,1,'Daavidin virsi. Herra on minun paimeneni, ei minulta mitään puutu.'),
(1683155,58,19,23,2,'Viheriäisille niityille hän vie minut lepäämään; virvoittavien vetten tykö hän minut johdattaa.'),
(1683156,58,19,23,3,'Hän virvoittaa minun sieluni. Hän ohjaa minut oikealle tielle nimensä tähden.'),
(1683157,58,19,23,4,'Vaikka minä vaeltaisin pimeässä laaksossa, en minä pelkäisi mitään pahaa, sillä sinä olet minun kanssani; sinun vitsasi ja sauvasi minua lohduttavat.'),
(1683158,58,19,23,5,'Sinä valmistat minulle pöydän minun vihollisteni silmien eteen. Sinä voitelet minun pääni öljyllä; minun maljani on ylitsevuotavainen.'),
(1683159,58,19,23,6,'Sula hyvyys ja laupeus seuraavat minua kaiken elinaikani; ja minä saan asua Herran huoneessa päivieni loppuun asti.'),
(1683160,58,19,24,1,'Daavidin virsi. Herran on maa ja kaikki, mitä siinä on, maanpiiri ja ne, jotka siinä asuvat.'),
(1683161,58,19,24,2,'Sillä hän on sen perustanut merten päälle, vahvistanut sen virtojen päälle.'),
(1683162,58,19,24,3,'Kuka saa astua Herran vuorelle, kuka seisoa hänen pyhässä paikassansa?'),
(1683163,58,19,24,4,'Se, jolla on viattomat kädet ja puhdas sydän, joka ei halaja turhuutta eikä vanno väärin.'),
(1683164,58,19,24,5,'Hän saa siunauksen Herralta ja vanhurskauden pelastuksensa Jumalalta.'),
(1683165,58,19,24,6,'Tämä on se suku, joka häntä kysyy, joka etsii sinun kasvojasi, - tämä on Jaakob. Sela.'),
(1683166,58,19,24,7,'Nostakaa päänne, te portit, nostakaa päänne, te ikuiset ovet, kunnian kuninkaan käydä sisälle!'),
(1683167,58,19,24,8,'Kuka on se kunnian kuningas? Hän on Herra, väkevä ja voimallinen, Herra, voimallinen sodassa.'),
(1683168,58,19,24,9,'Nostakaa päänne, te portit, nostakaa päänne, te ikuiset ovet, kunnian kuninkaan käydä sisälle!'),
(1683169,58,19,24,10,'Kuka on se kunnian kuningas? Hän on Herra Sebaot, hän on kunnian kuningas. Sela.'),
(1683170,58,19,25,1,'Daavidin virsi. Sinun tykösi, Herra, minä ylennän sieluni,'),
(1683171,58,19,25,2,'Jumalani, sinuun minä turvaan; älä salli minun joutua häpeään, älkööt viholliseni saako riemuita minusta.'),
(1683172,58,19,25,3,'Ei yksikään, joka sinua odottaa, joudu häpeään; häpeään joutuvat ne, jotka ovat syyttä uskottomat.'),
(1683173,58,19,25,4,'Herra, neuvo minulle tiesi, opeta minulle polkusi.'),
(1683174,58,19,25,5,'Johdata minua totuutesi tiellä ja opeta minua, sillä sinä olet minun pelastukseni Jumala. Sinua minä odotan kaiken päivää.'),
(1683175,58,19,25,6,'Muista laupeuttasi, Herra, ja armoasi, sillä ne ovat olleet hamasta iankaikkisuudesta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683176,58,19,25,7,'Älä muista minun nuoruuteni syntejä, älä minun rikoksiani; muista minua armosi mukaan, hyvyytesi tähden, Herra.'),
(1683177,58,19,25,8,'Hyvä ja vakaa on Herra; sentähden hän neuvoo syntiset tielle.'),
(1683178,58,19,25,9,'Hän johdattaa nöyriä oikein, hän opettaa nöyrille tiensä.'),
(1683179,58,19,25,10,'Kaikki Herran polut ovat armo ja totuus niille, jotka pitävät hänen liittonsa ja todistuksensa.'),
(1683180,58,19,25,11,'Nimesi tähden, Herra, anna anteeksi minun syntivelkani, sillä se on suuri.'),
(1683181,58,19,25,12,'Kuka on se mies, joka Herraa pelkää - sen hän neuvoo tielle, joka hänen on valittava.'),
(1683182,58,19,25,13,'Hänen sielunsa saa nauttia hyvää, ja hänen jälkeläisensä perivät maan.'),
(1683183,58,19,25,14,'Herran neuvo on tunnettu niille, jotka häntä pelkäävät, ja hän ilmoittaa heille liittonsa.'),
(1683184,58,19,25,15,'Minun silmäni katsovat alati Herraan, sillä hän päästää minun jalkani verkosta.'),
(1683185,58,19,25,16,'Käänny minun puoleeni, armahda minua, sillä minä olen yksinäinen ja kurja.'),
(1683186,58,19,25,17,'Minun sydämeni pakahtuu tuskasta; päästä minut ahdistuksistani.'),
(1683187,58,19,25,18,'Katso minun kurjuuttani ja vaivaani, anna kaikki minun syntini anteeksi.'),
(1683188,58,19,25,19,'Katso minun vihollisiani, kuinka heitä on paljon, ja he vihaavat minua väkivaltaisella vihalla.'),
(1683189,58,19,25,20,'Varjele minun sieluni ja pelasta minut. Älä salli minun tulla häpeään, sillä sinuun minä turvaan.'),
(1683190,58,19,25,21,'Nuhteettomuus ja oikeamielisyys varjelkoon minua, sillä sinua minä odotan.'),
(1683191,58,19,25,22,'Jumala, vapahda Israel kaikista ahdistuksistansa.'),
(1683192,58,19,26,1,'Daavidin virsi. Auta minut oikeuteeni, Herra, sillä minä olen vaeltanut nuhteettomasti ja turvaan horjumatta Herraan.'),
(1683193,58,19,26,2,'Tutki minua, Herra, ja pane minut koetukselle, koettele minun munaskuuni ja sydämeni.'),
(1683194,58,19,26,3,'Sillä sinun armosi on minun silmäini edessä, ja minä olen vaeltanut sinun totuudessasi.'),
(1683195,58,19,26,4,'En minä istu valheen miesten seurassa enkä kulje salakavalain kanssa.'),
(1683196,58,19,26,5,'Minä vihaan pahojen seuraa enkä istu jumalattomien parissa.'),
(1683197,58,19,26,6,'Minä pesen käteni viattomuudessa, ja astun kulkueessa sinun alttarisi ympäri, Herra,'),
(1683198,58,19,26,7,'antaakseni kuulua kiitokseni äänen ja julistaakseni kaikkia sinun ihmeitäsi.'),
(1683199,58,19,26,8,'Herra, minä rakastan sinun huonettasi, sinun asuinsijaasi, sitä paikkaa, jossa sinun kirkkautesi asuu.'),
(1683200,58,19,26,9,'Älä tempaa pois minun sieluani syntisten kanssa äläkä minun henkeäni verenvuodattajain kanssa,'),
(1683201,58,19,26,10,'joiden käsiä ilkityö tahraa, joiden oikea käsi on lahjuksia täynnä.'),
(1683202,58,19,26,11,'Mutta minä vaellan nuhteettomasti; vapahda minut ja ole minulle armollinen.'),
(1683203,58,19,26,12,'Minun jalkani seisoo tasaisella maalla; seurakunnan kokouksissa minä kiitän Herraa.'),
(1683204,58,19,27,1,'Daavidin virsi. Herra on minun valkeuteni ja autuuteni: ketä minä pelkään! Herra on minun elämäni turva: ketä minä vapisen!'),
(1683205,58,19,27,2,'Kun pahat käyvät minun kimppuuni, syömään minun lihaani, niin he, minun ahdistajani ja vihamieheni, kompastuvat ja kaatuvat.'),
(1683206,58,19,27,3,'Vaikka sotajoukko asettuisi minua vastaan, ei minun sydämeni pelkäisi; vaikka sota nousisi minua vastaan, siinäkin minä olisin turvassa.'),
(1683207,58,19,27,4,'Yhtä minä rukoilen Herralta, sitä minä pyydän: että saisin asua Herran huoneessa kaiken elinaikani, katsella Herran suloisuutta ja tutkistella hänen temppelissänsä.'),
(1683208,58,19,27,5,'Sillä hän kätkee minut majaansa pahana päivänä, hän suojaa minua telttansa suojassa, korottaa minut kalliolle.'),
(1683209,58,19,27,6,'Niin kohoaa nyt minun pääni vihollisteni yli, jotka minua ympäröivät, ja minä uhraan riemu-uhreja hänen majassansa, Herralle minä veisaan ja soitan.'),
(1683210,58,19,27,7,'Herra, kuule minun ääneni, kun minä huudan, armahda minua ja vastaa minulle.'),
(1683211,58,19,27,8,'Minun sydämeni vetoaa sinun omaan sanaasi: "Etsikää minun kasvojani". Herra, minä etsin sinun kasvojasi.'),
(1683212,58,19,27,9,'Älä kätke minulta kasvojasi, älä työnnä vihassa pois palvelijaasi. Sinä olet minun apuni, älä minua jätä, älä minua hylkää, pelastukseni Jumala.'),
(1683213,58,19,27,10,'Vaikka minun isäni ja äitini minut hyljätkööt, niin Herra minut korjaa.'),
(1683214,58,19,27,11,'Neuvo, Herra, minulle tiesi ja johdata minua tasaista polkua minun vihamiesteni tähden.'),
(1683215,58,19,27,12,'Älä anna minua alttiiksi ahdistajaini vimmalle, sillä väärät todistajat nousevat minua vastaan ja puuskuvat väkivaltaa.'),
(1683216,58,19,27,13,'Mutta minä totisesti uskon näkeväni Herran hyvyyden elävien maassa.'),
(1683217,58,19,27,14,'Odota Herraa. Ole luja, ja vahva olkoon sinun sydämesi. Odota Herraa.'),
(1683218,58,19,28,1,'Daavidin virsi. Sinua, Herra, minä huudan; minun kallioni, älä ole minua kohtaan äänetön, etten minä, kun sinä vaiti olet, joutuisi niiden kaltaiseksi, jotka ovat hautaan vaipuneet.'),
(1683219,58,19,28,2,'Kuule minun rukousteni ääni, kun minä sinua avuksi huudan, kun minä käteni nostan sinun kaikkeinpyhintäsi kohti.'),
(1683220,58,19,28,3,'Älä tempaa minua pois jumalattomien kanssa, älä väärintekijäin kanssa, jotka puhuvat lähimmäisilleen rauhan puheita, vaikka heidän sydämessään on pahuus.'),
(1683221,58,19,28,4,'Anna heille heidän työnsä mukaan ja heidän tekojensa pahuuden mukaan; anna heille heidän kättensä tekojen mukaan, kosta heille, mitä he ovat tehneet.'),
(1683222,58,19,28,5,'Sillä eivät he ota vaaria Herran töistä eivätkä hänen kättensä teoista. Hän kukistakoon heidät, älköönkä heitä rakentako.'),
(1683223,58,19,28,6,'Kiitetty olkoon Herra, sillä hän on kuullut minun rukousteni äänen.'),
(1683224,58,19,28,7,'Herra on minun voimani ja kilpeni; häneen minun sydämeni turvasi, ja minä sain avun. Siitä minun sydämeni riemuitsee, ja veisuullani minä häntä ylistän.'),
(1683225,58,19,28,8,'Herra on kansansa väkevyys, hän on voideltunsa pelastus ja turva.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683226,58,19,28,9,'Pelasta kansasi ja siunaa perikuntasi; kaitse heitä ja kanna heitä iankaikkisesti.'),
(1683227,58,19,29,1,'Daavidin virsi. Antakaa Herralle, te Jumalan pojat, antakaa Herralle kunnia ja väkevyys.'),
(1683228,58,19,29,2,'Antakaa Herralle hänen nimensä kunnia, kumartakaa Herraa pyhässä kaunistuksessa.'),
(1683229,58,19,29,3,'Herran ääni käy vetten päällä; kunnian Jumala jylisee, Herra suurten vetten päällä.'),
(1683230,58,19,29,4,'Herran ääni käy voimallisesti, Herran ääni käy valtavasti.'),
(1683231,58,19,29,5,'Herran ääni särkee setrit, Herra särkee Libanonin setrit.'),
(1683232,58,19,29,6,'Hän hypittää niitä niinkuin vasikkaa, Libanonia ja Sirjonia niinkuin nuorta villihärkää.'),
(1683233,58,19,29,7,'Herran ääni halkoo tulen liekit.'),
(1683234,58,19,29,8,'Herran ääni vapisuttaa erämaan, Herra vapisuttaa Kaadeksen erämaan.'),
(1683235,58,19,29,9,'Herran ääni saattaa peurat poikimaan, se raastaa paljaiksi metsät. Ja kaikki hänen temppelissänsä sanoo: "Kunnia!"'),
(1683236,58,19,29,10,'Herra istui valtaistuimellaan, ja vedenpaisumus tuli. Herra istuu kuninkaana iankaikkisesti.'),
(1683237,58,19,29,11,'Herra antaa kansallensa väkevyyden, Herra siunaa kansaansa rauhalla.'),
(1683238,58,19,30,1,'Daavidin virsi; temppelin vihkimislaulu.'),
(1683239,58,19,30,2,'Minä ylistän sinua, Herra, sillä sinä pelastit minut etkä sallinut viholliseni iloita minusta.'),
(1683240,58,19,30,3,'Herra, minun Jumalani, sinua minä huusin, ja sinä paransit minut.'),
(1683241,58,19,30,4,'Herra, sinä nostit minun sieluni tuonelasta, sinä herätit minut henkiin hautaan vaipuvien joukosta.'),
(1683242,58,19,30,5,'Veisatkaa kiitosta Herralle, te hänen hurskaansa, ylistäkää hänen pyhää nimeänsä.'),
(1683243,58,19,30,6,'Sillä silmänräpäyksen kestää hänen vihansa, eliniän hänen armonsa; ehtoolla on itku vieraana, mutta aamulla ilo.'),
(1683244,58,19,30,7,'Minä sanoin menestykseni päivinä: "En minä ikinä horju".'),
(1683245,58,19,30,8,'Herra, sinä armossasi vahvistit minun vuoreni. Mutta kun sinä kätkit kasvosi, niin minä peljästyin.'),
(1683246,58,19,30,9,'Sinua, Herra, minä huusin ja Herraa minä rukoilin:'),
(1683247,58,19,30,10,'"Mitä etua on minun verestäni, jos minä hautaan vaivun? Ylistääkö tomu sinua, julistaako se sinun uskollisuuttasi?'),
(1683248,58,19,30,11,'Kuule, Herra, ja armahda minua, Herra, ole minun auttajani."'),
(1683249,58,19,30,12,'Sinä muutit minun murheeni ilokarkeloksi, sinä riisuit minun surupukuni ja vyötit minut riemulla,'),
(1683250,58,19,30,13,'että minun sieluni veisaisi sinulle kiitosta, eikä vaikenisi. Herra, minun Jumalani, sinua minä ylistän iankaikkisesti.'),
(1683251,58,19,31,1,'Veisuunjohtajalle; Daavidin virsi.'),
(1683252,58,19,31,2,'Herra, sinuun minä turvaan. Älä salli minun ikinä häpeään tulla, vapahda minut vanhurskaudessasi.'),
(1683253,58,19,31,3,'Kallista korvasi minun puoleeni, riennä, pelasta minut. Ole minulle turvakallio, vuorilinna, johon minut pelastat.'),
(1683254,58,19,31,4,'Sillä sinä olet minun kallioni ja linnani, ja nimesi tähden sinä minua johdat ja talutat.'),
(1683255,58,19,31,5,'Sinä päästät minut verkosta, jonka he ovat eteeni virittäneet, sillä sinä olet minun turvani.'),
(1683256,58,19,31,6,'Sinun käteesi minä annan henkeni, sinä, Herra, lunastat minut, sinä uskollinen Jumala.'),
(1683257,58,19,31,7,'Minä vihaan niitä, jotka seuraavat turhia epäjumalia, mutta minä turvaan Herraan.'),
(1683258,58,19,31,8,'Minä iloitsen ja riemuitsen sinun armostasi, kun sinä katsoit minun kurjuuttani, tunsit minun sieluni ahdistukset,'),
(1683259,58,19,31,9,'etkä jättänyt minua vihollisen valtaan, vaan asetit minun jalkani aukealle.'),
(1683260,58,19,31,10,'Armahda minua, Herra, sillä minulla on ahdistus; minun silmäni on surusta riutunut, niin myös minun sieluni ja ruumiini.'),
(1683261,58,19,31,11,'Sillä minun elämäni kuluu murheessa ja minun vuoteni huokauksissa. Minun voimani on rauennut pahain tekojeni tähden, ja minun luuni ovat riutuneet.'),
(1683262,58,19,31,12,'Kaikkien ahdistajaini tähden minä olen pilkaksi tullut, ylenpalttiseksi pilkaksi naapureilleni, peljätykseksi tuttavilleni; jotka minut kadulla näkevät, pakenevat minua.'),
(1683263,58,19,31,13,'Minä olen unhottunut ihmisten mielistä niinkuin kuollut, minä olen kuin rikottu astia.'),
(1683264,58,19,31,14,'Sillä minä kuulen monen parjaukset, kauhua kaikkialta, kun he keskenänsä pitävät neuvoa minua vastaan, aikovat ottaa minulta hengen.'),
(1683265,58,19,31,15,'Mutta sinuun, Herra, minä turvaan; minä sanon: "Sinä olet minun Jumalani".'),
(1683266,58,19,31,16,'Minun aikani ovat sinun kädessäsi, pelasta minut vihollisteni kädestä ja vainoojistani.'),
(1683267,58,19,31,17,'Valista kasvosi palvelijallesi, pelasta minut armossasi.'),
(1683268,58,19,31,18,'Herra, älä salli minun tulla häpeään, sillä sinua minä huudan avukseni. Jumalattomat tulkoot häpeään, vaietkoot ja vaipukoot tuonelaan.'),
(1683269,58,19,31,19,'Mykistykööt valheen huulet, jotka puhuvat vanhurskasta vastaan röyhkeästi, ylpeästi ja ylenkatseellisesti.'),
(1683270,58,19,31,20,'Kuinka suuri on sinun hyvyytesi, jonka talletat pelkääväisillesi ja jota osoitat sinuun turvaaville ihmislasten edessä!'),
(1683271,58,19,31,21,'Sinä peität heidät kasvojesi suojaan ihmisten salavehkeiltä; sinä kätket heidät turvaan kielten riidalta.'),
(1683272,58,19,31,22,'Kiitetty olkoon Herra, sillä hän osoitti minulle ihmeellisen armonsa piiritetyssä kaupungissa.'),
(1683273,58,19,31,23,'Minä sanoin hädässäni: "Minä olen sysätty pois sinun silmiesi edestä". Kuitenkin sinä kuulit minun rukousteni äänen, kun minä sinua huusin.'),
(1683274,58,19,31,24,'Rakastakaa Herraa, kaikki hänen hurskaansa. Herra varjelee uskolliset, mutta ylpeileväisille hän kostaa monin kerroin.'),
(1683275,58,19,31,25,'Olkaa lujat, ja olkoon teidän sydämenne rohkea, te kaikki, jotka Herraa odotatte.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683276,58,19,32,1,'Daavidin mietevirsi. Autuas se, jonka rikokset ovat anteeksi annetut, jonka synti on peitetty!'),
(1683277,58,19,32,2,'Autuas se ihminen, jolle Herra ei lue hänen pahoja tekojansa ja jonka hengessä ei ole vilppiä!'),
(1683278,58,19,32,3,'Kun minä siitä vaikenin, riutuivat minun luuni jokapäiväisestä valituksestani.'),
(1683279,58,19,32,4,'Sillä yötä päivää oli sinun kätesi raskaana minun päälläni; minun nesteeni kuivui niinkuin kesän helteessä. Sela.'),
(1683280,58,19,32,5,'Minä tunnustin sinulle syntini enkä peittänyt pahoja tekojani; minä sanoin: "Minä tunnustan Herralle rikokseni", ja sinä annoit anteeksi minun syntivelkani. Sela.'),
(1683281,58,19,32,6,'Sentähden rukoilkoot sinua kaikki hurskaat aikana, jona sinut löytää voidaan. Vaikka suuret vedet tulvisivat, eivät ne heihin ulotu.'),
(1683282,58,19,32,7,'Sinä olet minun suojani, sinä varjelet minut hädästä, sinä ympäröitset minut pelastuksen riemulla. Sela.'),
(1683283,58,19,32,8,'"Minä opetan sinua ja osoitan sinulle tien, jota sinun tulee vaeltaa; minä neuvon sinua, minun silmäni sinua vartioitsee".'),
(1683284,58,19,32,9,'Älkää olko niinkuin järjettömät orhit ja muulit, joita suitsilla ja ohjaksilla, niiden valjailla, suistetaan; muutoin ne eivät sinua lähesty.'),
(1683285,58,19,32,10,'Jumalattomalla on monta vaivaa, mutta joka Herraan turvaa, häntä ympäröitsee armo.'),
(1683286,58,19,32,11,'Iloitkaa Herrassa ja riemuitkaa, te vanhurskaat, ja veisatkaa ilovirsiä, kaikki te oikeamieliset.'),
(1683287,58,19,33,1,'Riemuitkaa Herrassa, te vanhurskaat. Oikeamielisten on soveliasta häntä kiittää.'),
(1683288,58,19,33,2,'Ylistäkää Herraa kanteleilla, soittakaa hänelle kymmenkielisillä harpuilla.'),
(1683289,58,19,33,3,'Veisatkaa hänelle uusi virsi, helkyttäkää kieliä ihanasti ja riemullisesti.'),
(1683290,58,19,33,4,'Sillä Herran sana on oikea, ja kaikki hänen tekonsa ovat tehdyt uskollisuudessa.'),
(1683291,58,19,33,5,'Hän rakastaa vanhurskautta ja oikeutta; maa on täynnänsä Herran armoa.'),
(1683292,58,19,33,6,'Herran sanalla ovat taivaat tehdyt, ja kaikki niiden joukot hänen suunsa hengellä.'),
(1683293,58,19,33,7,'Hän kokoaa meren vedet niinkuin roukkioksi, panee syvyydet säiliöihin.'),
(1683294,58,19,33,8,'Peljätköön Herraa kaikki maa, hänen edessänsä vaviskoot kaikki maanpiirin asukkaat.'),
(1683295,58,19,33,9,'Sillä hän sanoi, ja tapahtui niin, hän käski, ja se oli tehty.'),
(1683296,58,19,33,10,'Herra särkee pakanain neuvon, tekee turhiksi kansojen aikeet.'),
(1683297,58,19,33,11,'Mutta Herran neuvo pysyy iankaikkisesti, hänen sydämensä aivoitukset suvusta sukuun.'),
(1683298,58,19,33,12,'Autuas se kansa, jonka Jumala Herra on, se kansa, jonka hän on perinnöksensä valinnut!'),
(1683299,58,19,33,13,'Herra katsoo alas taivaasta, näkee kaikki ihmislapset;'),
(1683300,58,19,33,14,'asumuksestaan, valtaistuimeltaan hän katselee kaikkia maan asukkaita,'),
(1683301,58,19,33,15,'hän, joka on luonut kaikkien heidän sydämensä, joka tarkkaa kaikkia heidän tekojansa.'),
(1683302,58,19,33,16,'Ei kuningas voita paljolla väellänsä, ei sankari pelastu suurella voimallansa.'),
(1683303,58,19,33,17,'Turha on sotaratsu auttajaksi, ei pelasta sen suuri väkevyys.'),
(1683304,58,19,33,18,'Katso, Herran silmä valvoo niitä, jotka häntä pelkäävät ja panevat toivonsa hänen laupeuteensa,'),
(1683305,58,19,33,19,'pelastaaksensa heidän sielunsa kuolemasta, elättääksensä heitä nälän aikana.'),
(1683306,58,19,33,20,'Meidän sielumme odottaa Herraa, hän on meidän apumme ja kilpemme.'),
(1683307,58,19,33,21,'Sillä hänessä iloitsee meidän sydämemme, me turvaamme hänen pyhään nimeensä.'),
(1683308,58,19,33,22,'Sinun armosi, Herra, olkoon meidän päällämme, niinkuin me panemme toivomme sinuun.'),
(1683309,58,19,34,1,'Daavidin virsi, kun hän tekeytyi mielipuoleksi Abimelekin edessä ja tämä karkoitti hänet luotansa ja hän meni pois.'),
(1683310,58,19,34,2,'Minä kiitän Herraa joka aika, hänen ylistyksensä on alati minun suussani.'),
(1683311,58,19,34,3,'Herra on minun sieluni kerskaus, nöyrät sen kuulevat ja iloitsevat.'),
(1683312,58,19,34,4,'Ylistäkää minun kanssani Herraa, kiittäkäämme yhdessä hänen nimeänsä.'),
(1683313,58,19,34,5,'Minä etsin Herraa, ja hän vastasi minulle, hän vapahti minut kaikista peljätyksistäni.'),
(1683314,58,19,34,6,'Jotka häneen katsovat, ne säteilevät iloa, heidän kasvonsa eivät häpeästä punastu.'),
(1683315,58,19,34,7,'Tässä on kurja, joka huusi, ja Herra kuuli ja pelasti hänet kaikista hänen ahdistuksistansa.'),
(1683316,58,19,34,8,'Herran enkeli asettuu niiden ympärille, jotka häntä pelkäävät, ja pelastaa heidät.'),
(1683317,58,19,34,9,'Maistakaa ja katsokaa, kuinka Herra on hyvä. Autuas se mies, joka häneen turvaa!'),
(1683318,58,19,34,10,'Peljätkää Herraa, te hänen pyhänsä, sillä häntä pelkääväisiltä ei mitään puutu.'),
(1683319,58,19,34,11,'Nuoret leijonat kärsivät puutetta ja näkevät nälkää, mutta Herraa etsiväisiltä ei mitään hyvää puutu.'),
(1683320,58,19,34,12,'Tulkaa, lapset, kuulkaa minua: Herran pelkoon minä teidät opetan.'),
(1683321,58,19,34,13,'Kuka oletkin, joka elää tahdot ja rakastat elämän päiviä, nauttiaksesi onnea:'),
(1683322,58,19,34,14,'varjele kielesi pahasta ja huulesi vilppiä puhumasta;'),
(1683323,58,19,34,15,'vältä pahaa ja tee hyvää, etsi rauhaa ja pyri siihen.'),
(1683324,58,19,34,16,'Herran silmät tarkkaavat vanhurskaita ja hänen korvansa heidän huutoansa.'),
(1683325,58,19,34,17,'Herran kasvot ovat pahantekijöitä vastaan, hävittääksensä maasta heidän muistonsa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683326,58,19,34,18,'Vanhurskaat huutavat, ja Herra kuulee ja vapahtaa heidät kaikista heidän ahdistuksistansa.'),
(1683327,58,19,34,19,'Lähellä on Herra niitä, joilla on särjetty sydän, ja hän pelastaa ne, joilla on murtunut mieli.'),
(1683328,58,19,34,20,'Monta on vanhurskaalla kärsimystä, mutta Herra vapahtaa hänet niistä kaikista.'),
(1683329,58,19,34,21,'Hän varjelee kaikki hänen luunsa: ei yksikään niistä murru.'),
(1683330,58,19,34,22,'Pahuus tappaa jumalattoman, ja jotka vanhurskasta vihaavat, ne tulevat syynalaisiksi.'),
(1683331,58,19,34,23,'Herra lunastaa palvelijainsa sielut, eikä yksikään, joka häneen turvaa, tule syynalaiseksi.'),
(1683332,58,19,35,1,'Daavidin virsi. Riitele, Herra, minun riitaveljiäni vastaan; sodi niitä vastaan, jotka minua vastaan sotivat.'),
(1683333,58,19,35,2,'Tempaa pieni kilpi, suuri kilpi ja nouse minun avukseni.'),
(1683334,58,19,35,3,'Sivalla keihäs ja salpaa tie minun vainoojiltani. Sano minun sielulleni: "Minä olen sinun pelastuksesi".'),
(1683335,58,19,35,4,'Joutukoot häpeään ja pilkkaan, jotka minun henkeäni väijyvät; peräytykööt, punastukoot, jotka minulle pahaa aikovat.'),
(1683336,58,19,35,5,'Olkoot he niinkuin akanat tuulessa, ja Herran enkeli syösköön heidät maahan;'),
(1683337,58,19,35,6,'heidän tiensä olkoon pimeä ja liukas, ja Herran enkeli ajakoon heitä takaa.'),
(1683338,58,19,35,7,'Sillä syyttä he ovat virittäneet verkkonsa minun eteeni, syyttä he ovat kaivaneet minun sielulleni haudan.'),
(1683339,58,19,35,8,'Tulkoon hänelle turmio aavistamatta, tarttukoon hän virittämäänsä verkkoon, langetkoon siihen surmaksensa.'),
(1683340,58,19,35,9,'Mutta minun sieluni iloitkoon Herrassa, riemuitkoon hänen avustansa.'),
(1683341,58,19,35,10,'Kaikki minun luuni sanokoot: "Herra, kuka on sinun vertaisesi, sinun, joka vapahdat kurjan väkevämmästään, kurjan ja köyhän raatelijastaan?"'),
(1683342,58,19,35,11,'Väärät todistajat astuvat esiin, he minulta tutkivat, mitä minä en tiedä.'),
(1683343,58,19,35,12,'He palkitsevat minulle hyvän pahalla; minun sieluni on orpo.'),
(1683344,58,19,35,13,'Mutta minä puin päälleni surupuvun, kun he sairastivat; minä vaivasin itseäni paastolla ja rukoilin pää painuksissa.'),
(1683345,58,19,35,14,'Niinkuin he olisivat olleet minun ystäviäni, minun omia veljiäni, niin minä kuljin; niinkuin äitiänsä sureva, niin minä kävin surupuvussa, kumarruksissa.'),
(1683346,58,19,35,15,'Mutta he iloitsevat minun kompastuksestani ja kokoontuvat - kokoontuvat minua vastaan, nuo lyöjät, joita minä en tunne; he herjaavat herkeämättä,'),
(1683347,58,19,35,16,'nuo konnat, jotka leipäkyrsää kärkkyen minua pilkkaavat, kiristelevät minulle hampaitansa.'),
(1683348,58,19,35,17,'Herra, kuinka kauan sinä tätä katselet? Päästä minun sieluni turmiosta, jota he hankitsevat, minun ainokaiseni nuorista leijonista.'),
(1683349,58,19,35,18,'Niin minä kiitän sinua suuressa seurakunnassa, ylistän sinua paljon kansan keskellä.'),
(1683350,58,19,35,19,'Älkööt ne minusta iloitko, jotka syyttä ovat minun vihamiehiäni; älkööt silmää iskekö, jotka asiatta minua vihaavat.'),
(1683351,58,19,35,20,'Sillä he eivät puhu rauhan puheita, vaan miettivät petoksen sanoja maan hiljaisia vastaan.'),
(1683352,58,19,35,21,'He avaavat suunsa ammolleen minua vastaan ja sanovat: "Kas niin, kas niin! Nyt me sen omin silmin näemme!"'),
(1683353,58,19,35,22,'Sinä, Herra, näet sen, älä ole vaiti! Herra, älä ole minusta kaukana!'),
(1683354,58,19,35,23,'Heräjä ja nouse, minun Jumalani ja Herrani, hankkimaan minulle oikeutta ja ajamaan minun asiaani.'),
(1683355,58,19,35,24,'Tuomitse minut vanhurskautesi mukaan, Herra, minun Jumalani, älä salli heidän minusta riemuita.'),
(1683356,58,19,35,25,'Älä salli heidän sanoa sydämessänsä: "Kas niin! Sitä me halusimmekin." Älä salli heidän sanoa: "Me olemme hänet nielleet".'),
(1683357,58,19,35,26,'Hävetkööt ja punastukoot kaikki, jotka minun onnettomuudestani iloitsevat, saakoot puvuksensa häpeän ja pilkan ne, jotka ylvästelevät minua vastaan.'),
(1683358,58,19,35,27,'Iloitkoot ja riemuitkoot ne, jotka suovat minulle minun oikeuteni, ja sanokoot aina: "Ylistetty olkoon Herra, joka tahtoo palvelijansa parasta".'),
(1683359,58,19,35,28,'Ja minun kieleni julistakoon sinun vanhurskauttasi, sinun kiitostasi kaiken päivää.'),
(1683360,58,19,36,1,'Veisuunjohtajalle; Herran palvelijan Daavidin virsi.'),
(1683361,58,19,36,2,'Synti sanoo jumalattomalle: minun sydämessäni ei ole Jumalan pelkoa hänen silmäinsä edessä.'),
(1683362,58,19,36,3,'Sillä se tekee kaiken sileäksi hänen silmissään, että hänen pahuutensa havaittaisiin ja häntä vihattaisiin.'),
(1683363,58,19,36,4,'Hänen suunsa sanat ovat vääryyttä ja petosta; hän on lakannut tekemästä sitä, mikä taidollista ja hyvää on.'),
(1683364,58,19,36,5,'Hän miettii turmiota vuoteessansa, hän pysyy tiellä, joka ei ole hyvä, hän ei kammo pahaa.'),
(1683365,58,19,36,6,'Herra, sinun armosi ulottuu taivaisiin, sinun totuutesi pilviin asti.'),
(1683366,58,19,36,7,'Sinun vanhurskautesi on kuin Jumalan vuoret, sinun tuomiosi niinkuin suuri syvyys, ihmistä ja eläintä sinä autat, Herra.'),
(1683367,58,19,36,8,'Kuinka kallis on sinun armosi, Jumala! Ihmislapset etsivät sinun siipiesi suojaa.'),
(1683368,58,19,36,9,'Heidät ravitaan sinun huoneesi lihavuudella, sinä annat heidän juoda suloisuutesi virrasta.'),
(1683369,58,19,36,10,'Sillä sinun tykönäsi on elämän lähde; sinun valkeudessasi me näemme valkeuden.'),
(1683370,58,19,36,11,'Säilytä armosi niille, jotka sinut tuntevat, ja vanhurskautesi oikeamielisille.'),
(1683371,58,19,36,12,'Älköön ylpeyden jalka minua tallatko, älköönkä jumalattomain käsi minua karkoittako.'),
(1683372,58,19,36,13,'Katso, pahantekijät kaatuvat, he suistuvat maahan, eivätkä voi nousta.'),
(1683373,58,19,37,1,'Daavidin virsi. Älä vihastu pahain tähden, älä kadehdi väärintekijöitä.'),
(1683374,58,19,37,2,'Sillä niinkuin heinä heidät pian niitetään pois, ja he lakastuvat niinkuin vihanta ruoho.'),
(1683375,58,19,37,3,'Turvaa Herraan ja tee sitä, mikä hyvä on, asu maassa ja noudata totuutta;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683376,58,19,37,4,'silloin sinulla on ilo Herrassa, ja hän antaa sinulle, mitä sinun sydämesi halajaa.'),
(1683377,58,19,37,5,'Anna tiesi Herran haltuun ja turvaa häneen, kyllä hän sen tekee.'),
(1683378,58,19,37,6,'Ja hän antaa sinun vanhurskautesi nousta niinkuin valkeuden ja sinun oikeutesi niinkuin keskipäivän.'),
(1683379,58,19,37,7,'Hiljenny Herran edessä ja odota häntä. Älä vihastu siihen, jonka tie menestyy, mieheen, joka juonia punoo.'),
(1683380,58,19,37,8,'Herkeä vihasta ja heitä kiukku, älä kiivastu, se on vain pahaksi.'),
(1683381,58,19,37,9,'Sillä pahat hävitetään, mutta jotka Herraa odottavat, ne perivät maan.'),
(1683382,58,19,37,10,'Hetkinen vielä, niin jumalatonta ei enää ole; kun hänen sijaansa katsot, on hän jo poissa.'),
(1683383,58,19,37,11,'Mutta nöyrät perivät maan ja iloitsevat suuresta rauhasta.'),
(1683384,58,19,37,12,'Jumalaton miettii vanhurskaalle pahaa ja kiristelee hänelle hampaitansa;'),
(1683385,58,19,37,13,'mutta Herra nauraa hänelle, sillä hän näkee hänen päivänsä joutuvan.'),
(1683386,58,19,37,14,'Jumalattomat paljastavat miekkansa ja jännittävät jousensa, kaataaksensa kurjan ja köyhän, teurastaaksensa ne, jotka ovat oikealla tiellä.'),
(1683387,58,19,37,15,'Mutta heidän miekkansa käy heidän omaan sydämeensä, ja heidän jousensa särkyvät.'),
(1683388,58,19,37,16,'Vanhurskaan vähä vara on parempi kuin monen jumalattoman tavarain paljous.'),
(1683389,58,19,37,17,'Sillä jumalattomain käsivarret särjetään, mutta Herra tukee vanhurskaita.'),
(1683390,58,19,37,18,'Herra tuntee nuhteettomain päivät, ja heidän perintönsä pysyy iankaikkisesti.'),
(1683391,58,19,37,19,'Pahana aikana he eivät joudu häpeään, ja nälän päivinä heillä on kyllin syötävää.'),
(1683392,58,19,37,20,'Sillä jumalattomat hukkuvat, ja Herran viholliset ovat kuin niittyjen koreus: he katoavat, katoavat niinkuin savu.'),
(1683393,58,19,37,21,'Jumalaton ottaa lainan eikä maksa, mutta vanhurskas on armahtavainen ja antelias.'),
(1683394,58,19,37,22,'Sillä hänen siunaamansa perivät maan, mutta hänen kiroamansa hävitetään.'),
(1683395,58,19,37,23,'Herra vahvistaa sen miehen askeleet, jonka tie hänelle kelpaa.'),
(1683396,58,19,37,24,'Jos hän lankeaa, ei hän maahan sorru, sillä Herra tukee hänen kättänsä.'),
(1683397,58,19,37,25,'Olen ollut nuori ja olen vanhaksi tullut, mutta en ole nähnyt vanhurskasta hyljättynä enkä hänen lastensa kerjäävän leipää.'),
(1683398,58,19,37,26,'Aina hän on armahtavainen ja antaa lainaksi, ja hänen lapsensa ovat siunaukseksi.'),
(1683399,58,19,37,27,'Karta pahaa ja tee hyvää, niin sinä pysyt iankaikkisesti.'),
(1683400,58,19,37,28,'Sillä Herra rakastaa oikeutta eikä hylkää hurskaitansa; heidät varjellaan iankaikkisesti, mutta jumalattomain siemen hävitetään.'),
(1683401,58,19,37,29,'Vanhurskaat perivät maan ja asuvat siinä iankaikkisesti.'),
(1683402,58,19,37,30,'Vanhurskaan suu lausuu viisautta, ja hänen kielensä puhuu oikeuden sanoja.'),
(1683403,58,19,37,31,'Hänen Jumalansa laki on hänen sydämessään, hänen askeleensa eivät horju.'),
(1683404,58,19,37,32,'Jumalaton väijyy vanhurskasta ja etsii häntä tappaaksensa.'),
(1683405,58,19,37,33,'Mutta Herra ei jätä häntä hänen käsiinsä eikä tuomitse häntä syylliseksi, kun hänen asiansa on oikeudessa.'),
(1683406,58,19,37,34,'Odota Herraa ja ota vaari hänen tiestänsä, niin hän korottaa sinut, ja sinä perit maan ja näet, kuinka jumalattomat hävitetään.'),
(1683407,58,19,37,35,'Minä näin jumalattoman, väkivaltaisen, rehevänä kuin viheriöivä puu, juurtunut paikoilleen.'),
(1683408,58,19,37,36,'Mutta kun ohi kuljettiin, katso, ei häntä enää ollut; minä etsin häntä, vaan häntä ei löytynyt.'),
(1683409,58,19,37,37,'Ota nuhteettomasta vaari, katso rehellistä: rauhan miehellä on tulevaisuus,'),
(1683410,58,19,37,38,'mutta luopuneet hukkuvat kaikki, ja jumalattomain tulevaisuus leikataan pois.'),
(1683411,58,19,37,39,'Mutta vanhurskasten pelastus tulee Herralta, hän on heidän linnansa ahdingon aikana.'),
(1683412,58,19,37,40,'Herra auttaa heitä ja vapahtaa heidät, vapahtaa jumalattomista ja pelastaa heidät; sillä he turvaavat häneen.'),
(1683413,58,19,38,1,'Daavidin virsi; syntiä tunnustettaessa.'),
(1683414,58,19,38,2,'Herra, älä rankaise minua vihassasi, älä kiivastuksessasi kurita minua.'),
(1683415,58,19,38,3,'Sillä sinun nuolesi ovat uponneet minuun, sinun kätesi painaa minua.'),
(1683416,58,19,38,4,'Ei ole lihassani tervettä paikkaa sinun vihastuksesi tähden eikä luissani rauhaa minun syntieni tähden.'),
(1683417,58,19,38,5,'Sillä minun pahat tekoni käyvät pääni ylitse, niinkuin raskas kuorma ne ovat minulle liian raskaat.'),
(1683418,58,19,38,6,'Minun haavani haisevat ja märkivät minun hulluuteni tähden.'),
(1683419,58,19,38,7,'Minä käyn kumarassa, aivan kyyryssä, kuljen murheellisena kaiken päivää.'),
(1683420,58,19,38,8,'Sillä minun lanteeni ovat polttoa täynnä, eikä ole lihassani tervettä paikkaa.'),
(1683421,58,19,38,9,'Minä olen voimaton ja peräti runneltu, minä parun sydämeni tuskassa.'),
(1683422,58,19,38,10,'Herra, sinun edessäsi on kaikki minun halajamiseni, eikä minun huokaukseni ole sinulta salassa.'),
(1683423,58,19,38,11,'Minun sydämeni värisee, minun voimani on minusta luopunut, minun silmieni valo - sekin on minulta mennyt.'),
(1683424,58,19,38,12,'Minun ystäväni ja läheiseni pysyvät syrjässä minun vitsauksestani, ja minun omaiseni seisovat kaukana.'),
(1683425,58,19,38,13,'Jotka minun henkeäni etsivät, ne virittävät pauloja; ja jotka minulle pahaa suovat, ne puhuvat turmion puheita ja miettivät petosta kaiket päivät.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683426,58,19,38,14,'Mutta minä olen kuin kuuro, en mitään kuule, kuin mykkä, joka ei suutansa avaa.'),
(1683427,58,19,38,15,'Minä olen kuin mies, joka ei mitään kuule ja jonka suussa ei vastausta ole.'),
(1683428,58,19,38,16,'Sillä sinua, Herra, minä odotan, sinä vastaat, Herra, minun Jumalani.'),
(1683429,58,19,38,17,'Minä sanon: älkööt iloitko minusta, älkööt ylvästelkö minua vastaan, kun jalkani horjuu.'),
(1683430,58,19,38,18,'Sillä minä olen kaatumaisillani, ja minun tuskani on aina edessäni;'),
(1683431,58,19,38,19,'sillä minä tunnustan pahat tekoni, murehdin syntieni tähden.'),
(1683432,58,19,38,20,'Mutta minun viholliseni elävät ja ovat väkevät, ja paljon on niitä, jotka minua syyttä vihaavat,'),
(1683433,58,19,38,21,'jotka hyvän pahalla palkitsevat ja vihaavat minua, koska minä hyvään pyrin.'),
(1683434,58,19,38,22,'Älä hylkää minua, Herra, minun Jumalani, älä ole kaukana minusta.'),
(1683435,58,19,38,23,'Riennä avukseni, Herra, minun pelastukseni.'),
(1683436,58,19,39,1,'Veisuunjohtajalle; Jedutunin tapaan; Daavidin virsi.'),
(1683437,58,19,39,2,'Minä sanoin: "Minä pidän vaelluksestani vaarin, etten kielelläni syntiä tekisi. Minä pidän suustani vaarin ja suistan sen, niin kauan kuin jumalaton on minun edessäni."'),
(1683438,58,19,39,3,'Minä olin vaiti, olin ääneti, en puhunut siitä, mikä hyvä on; mutta minun tuskani yltyi.'),
(1683439,58,19,39,4,'Minun sydämeni hehkui minun rinnassani; kun minä huokailin, syttyi minussa tuli, ja niin minä kielelläni puhuin.'),
(1683440,58,19,39,5,'Herra, opeta minua ajattelemaan loppuani, ja mikä minun päivieni mitta on, että ymmärtäisin, kuinka katoavainen minä olen.'),
(1683441,58,19,39,6,'Katso, kämmenen leveydeksi sinä teit minun päiväni, ja minun elämäni on sinun edessäsi niinkuin ei mitään. Vain tuulen henkäys ovat kaikki ihmiset, kuinka lujina seisokootkin. Sela.'),
(1683442,58,19,39,7,'Varjona vain ihminen vaeltaa, turhaan vain he touhuavat, kokoavat, eivätkä tiedä, kuka ne saa.'),
(1683443,58,19,39,8,'Ja nyt, mitä minä odotan, Herra? Sinuun minä panen toivoni.'),
(1683444,58,19,39,9,'Päästä minut kaikista synneistäni, älä pane minua houkkain pilkaksi.'),
(1683445,58,19,39,10,'Minä vaikenen enkä suutani avaa; sillä sinä sen teit.'),
(1683446,58,19,39,11,'Käännä vitsauksesi minusta pois, sillä minä menehdyn sinun kätesi kuritukseen.'),
(1683447,58,19,39,12,'Kun sinä ihmistä synnin tähden rangaistuksilla kuritat, kulutat sinä hänen kauneutensa niinkuin koinsyömän. Vain tuulen henkäys ovat kaikki ihmiset. Sela.'),
(1683448,58,19,39,13,'Kuule minun rukoukseni, Herra, ota korviisi minun huutoni. Älä ole kuuro minun kyyneleilleni; sillä minä olen muukalainen sinun tykönäsi, vieras, niinkuin kaikki minun isänikin.'),
(1683449,58,19,39,14,'Käännä pois katseesi minusta, että minä ilostuisin, ennenkuin menen pois eikä minua enää ole.'),
(1683450,58,19,40,1,'Veisuunjohtajalle; Daavidin virsi.'),
(1683451,58,19,40,2,'Hartaasti minä odotin Herraa, ja hän kumartui minun puoleeni ja kuuli minun huutoni.'),
(1683452,58,19,40,3,'Ja hän nosti minut ylös turmion kuopasta, lokaisesta liejusta, ja asetti minun jalkani kalliolle, hän vahvisti minun askeleeni.'),
(1683453,58,19,40,4,'Hän antoi minun suuhuni uuden virren, kiitoslaulun Jumalallemme. Sen näkevät monet ja pelkäävät ja turvaavat Herraan.'),
(1683454,58,19,40,5,'Autuas se mies, joka panee turvansa Herraan eikä käänny ylpeiden puoleen eikä niitten, jotka valheeseen eksyvät!'),
(1683455,58,19,40,6,'Herra, minun Jumalani, suuret ovat sinun ihmetekosi ja sinun aivoituksesi meitä kohtaan. Ei ole ketään sinun vertaistasi. Niitä minä tahdon julistaa, niistä puhua, niitten paljous on suurempi, kuin luetella taidan.'),
(1683456,58,19,40,7,'Teurasuhriin ja ruokauhriin et sinä mielisty; minun korvani sinä avasit, polttouhria ja syntiuhria sinä et vaadi.'),
(1683457,58,19,40,8,'Silloin minä sanoin: "Katso, minä tulen; kirjakääröön on kirjoitettu, mitä minun on tehtävä.'),
(1683458,58,19,40,9,'Sinun tahtosi, minun Jumalani, minä teen mielelläni, ja sinun lakisi on minun sydämessäni."'),
(1683459,58,19,40,10,'Minä julistan vanhurskautta suuressa seurakunnassa; katso, en minä sulje huuliani. Sinä, Herra, sen tiedät.'),
(1683460,58,19,40,11,'Minä en peitä sinun vanhurskauttasi omaan sydämeeni, vaan puhun sinun uskollisuudestasi ja avustasi; minä en salaa sinun armoasi ja totuuttasi suurelta seurakunnalta.'),
(1683461,58,19,40,12,'Sinä, Herra, älä sulje minulta laupeuttasi, sinun armosi ja totuutesi varjelkoon minua aina.'),
(1683462,58,19,40,13,'Sillä lukemattomat vaivat minua saartavat, minun rikkomukseni ovat ottaneet minut kiinni, niin etten nähdä taida; ne ovat useammat kuin pääni hiukset, ja rohkeus on minulta mennyt.'),
(1683463,58,19,40,14,'Kelvatkoon sinulle, Herra, pelastaa minut, Herra, riennä minun avukseni.'),
(1683464,58,19,40,15,'Hävetkööt ja punastukoot kaikki, jotka minun henkeäni etsivät, hukuttaaksensa sen; peräytykööt ja tulkoot häpeään ne, jotka tahtovat minulle onnettomuutta.'),
(1683465,58,19,40,16,'Tyrmistykööt häpeästänsä ne, jotka minulle sanovat: "Kas niin, kas niin!"'),
(1683466,58,19,40,17,'Iloitkoot ja riemuitkoot sinussa kaikki, jotka sinua etsivät; ne, jotka sinun autuuttasi rakastavat, sanokoot aina: "Ylistetty olkoon Herra!"'),
(1683467,58,19,40,18,'Minä olen kurja ja köyhä, mutta Herra pitää minusta huolen. Sinä olet minun apuni ja pelastajani; minun Jumalani, älä viivy.'),
(1683468,58,19,41,1,'Veisuunjohtajalle; Daavidin virsi.'),
(1683469,58,19,41,2,'Autuas se, joka vaivaista holhoo! Hänet Herra pelastaa pahana päivänä.'),
(1683470,58,19,41,3,'Herra varjelee häntä ja pitää hänet hengissä, ja maassa ylistetään hänen onneansa, etkä sinä anna häntä alttiiksi hänen vihollistensa raivolle.'),
(1683471,58,19,41,4,'Herra tukee häntä tautivuoteessa; hänen sairasvuoteensa sinä peräti muutat.'),
(1683472,58,19,41,5,'Minä sanoin: "Herra, ole minulle armollinen, paranna minun sieluni, sillä minä olen tehnyt syntiä sinua vastaan".'),
(1683473,58,19,41,6,'Minun viholliseni puhuvat minusta pahaa: "Milloinka hän kuolee ja hänen nimensä katoaa?"'),
(1683474,58,19,41,7,'Ja jos joku tulee minua katsomaan, puhuu hän petosta; hänen sydämensä kerää häijyyttä itseensä, hän menee ulos kadulle ja purkaa sitä.'),
(1683475,58,19,41,8,'Kaikki minun vihamieheni minusta keskenään kuiskuttelevat ja hankitsevat minulle pahaa:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683476,58,19,41,9,'"Jokin parantumaton paha on häneen tarttunut, ja siitä, missä hän makaa, hän ei enää nouse".'),
(1683477,58,19,41,10,'Ystävänikin, johon minä luotin, joka minun leipääni söi, nostaa kantapäänsä minua vastaan.'),
(1683478,58,19,41,11,'Mutta sinä, Herra, armahda minua ja auta minut ylös, pystyyn, niin minä sen heille maksan.'),
(1683479,58,19,41,12,'Siitä minä tiedän sinun mielistyneen minuun, ettei minun viholliseni saa minusta riemuita.'),
(1683480,58,19,41,13,'Minun nuhteettomuuteni tähden sinä minua tuet ja annat minun seisoa kasvojesi edessä ainiaan.'),
(1683481,58,19,41,14,'Kiitetty olkoon Herra, Israelin Jumala, iankaikkisesta iankaikkiseen. Amen. Amen.'),
(1683482,58,19,42,1,'Veisuunjohtajalle; koorahilaisten mietevirsi.'),
(1683483,58,19,42,2,'Niinkuin peura halajaa vesipuroille, niin minun sieluni halajaa sinua, Jumala.'),
(1683484,58,19,42,3,'Minun sieluni janoo Jumalaa, elävää Jumalaa. Milloin saan minä tulla Jumalan kasvojen eteen?'),
(1683485,58,19,42,4,'Kyyneleeni ovat minun ruokani päivin ja öin, kun minulle joka päivä sanotaan: "Missä on sinun Jumalasi?"'),
(1683486,58,19,42,5,'Näitä minä muistelen ja vuodatan sydämeni: minä kuljin väentungoksessa, astuin sen kanssa Jumalan huoneeseen riemun ja kiitoksen raikuessa juhlivasta joukosta.'),
(1683487,58,19,42,6,'Miksi murehdit, minun sieluni, ja olet minussa niin levoton? Odota Jumalaa. Sillä vielä minä saan häntä kiittää hänen kasvojensa avusta.'),
(1683488,58,19,42,7,'Minun Jumalani, minun sieluni on murheellinen minussa, sentähden minä muistan sinua Jordanin maalla, Hermonin kukkuloilla ja Misarin vuorella.'),
(1683489,58,19,42,8,'Sinun koskiesi pauhussa syvyys syvyydelle huutaa, kaikki sinun kuohusi ja aaltosi käyvät minun ylitseni.'),
(1683490,58,19,42,9,'Päivällä Herra säätää armonsa, ja yöllä minä hänelle veisaan ja rukoilen elämäni Jumalaa.'),
(1683491,58,19,42,10,'Minä sanon Jumalalle, kalliolleni: "Miksi olet minut unhottanut? Miksi minun täytyy käydä murhepuvussa, vihollisen ahdistamana?"'),
(1683492,58,19,42,11,'Minun luitani jäytää, kun viholliseni minua häpäisevät, sanoen minulle kaiken päivää: "Missä on sinun Jumalasi?"'),
(1683493,58,19,42,12,'Miksi murehdit, minun sieluni, ja miksi olet minussa niin levoton? Odota Jumalaa. Sillä vielä minä saan kiittää häntä, minun kasvojeni apua, minun Jumalaani.'),
(1683494,58,19,43,1,'Auta minut oikeuteeni, Jumala, ja aja minun asiani armotonta kansaa vastaan. Päästä minut kavaloista ja vääristä ihmisistä.'),
(1683495,58,19,43,2,'Sillä sinä olet minun Jumalani, minun linnani. Miksi olet minut hyljännyt? Miksi minun täytyy käydä murhepuvussa, vihollisen ahdistamana?'),
(1683496,58,19,43,3,'Lähetä valkeutesi ja totuutesi. Ne minua johdattakoot, viekööt minut sinun pyhälle vuorellesi, sinun asuntoihisi,'),
(1683497,58,19,43,4,'että minä saisin tulla Jumalan alttarin eteen, Jumalan eteen, joka on minun iloni ja riemuni, ja kiittäisin kanteleilla sinua, Jumala, minun Jumalani.'),
(1683498,58,19,43,5,'Miksi murehdit, minun sieluni, ja miksi olet minussa niin levoton? Odota Jumalaa. Sillä vielä minä saan kiittää häntä, minun kasvojeni apua, minun Jumalaani.'),
(1683499,58,19,44,1,'Veisuunjohtajalle; koorahilaisten mietevirsi.'),
(1683500,58,19,44,2,'Jumala, me olemme omin korvin kuulleet, meidän isämme ovat meille kertoneet, minkä teon sinä teit heidän päivinänsä, muinaisina päivinä.'),
(1683501,58,19,44,3,'Sinä karkoitit kädelläsi pakanat, mutta heidät sinä istutit, sinä hävitit kansat, mutta heidät sinä levitit.'),
(1683502,58,19,44,4,'Sillä eivät he miekallansa valloittaneet maata, eikä heidän käsivartensa heitä auttanut, vaan sinun oikea kätesi, sinun käsivartesi ja sinun kasvojesi valkeus, koska sinä olit heihin mielistynyt.'),
(1683503,58,19,44,5,'Sinä, Jumala, sinä olet minun kuninkaani, toimita Jaakobille apu.'),
(1683504,58,19,44,6,'Sinun avullasi me syöksemme ahdistajamme maahan, sinun nimessäsi me tallaamme vastustajamme.'),
(1683505,58,19,44,7,'Sillä en minä jouseeni luota, eikä miekkani minua auta;'),
(1683506,58,19,44,8,'vaan sinä pelastat meidät vihollisistamme, ja saatat vihamiehemme häpeään.'),
(1683507,58,19,44,9,'Jumala on meidän kerskauksemme kaikkina päivinä, ja sinun nimeäsi me ylistämme iankaikkisesti. Sela.'),
(1683508,58,19,44,10,'Kuitenkin sinä meidät hylkäsit ja saatoit meidät häpeään, et lähtenyt sotaan meidän joukkojemme kanssa.'),
(1683509,58,19,44,11,'Sinä käänsit meidät vihollista pakoon, ja meidän vihamiehemme ryöstivät saalista.'),
(1683510,58,19,44,12,'Sinä annoit meidät syötäviksi kuin lampaat, ja hajotit meidät pakanain sekaan.'),
(1683511,58,19,44,13,'Sinä myit kansasi halvasta etkä heidän hinnastaan paljoa hyötynyt.'),
(1683512,58,19,44,14,'Sinä annat meidät naapuriemme häväistäviksi, ympärillämme asuvaisten pilkaksi ja ivaksi.'),
(1683513,58,19,44,15,'Sinä saatat meidät sananparreksi pakanoille, pään pudistukseksi kansoille.'),
(1683514,58,19,44,16,'Joka päivä on häväistykseni minun edessäni, ja kasvojeni häpeä peittää minut,'),
(1683515,58,19,44,17,'herjaajan ja pilkkaajan puheen tähden, vihollisen ja kostonhimoisen katseitten tähden.'),
(1683516,58,19,44,18,'Tämä kaikki on meitä kohdannut, vaikka emme ole sinua unhottaneet emmekä sinun liittoasi rikkoneet.'),
(1683517,58,19,44,19,'Ei ole meidän sydämemme sinusta luopunut, eivät meidän askeleemme sinun polultasi poikenneet.'),
(1683518,58,19,44,20,'Kuitenkin sinä runtelit meidät aavikkosutten asuinsijoilla ja peitit meidät synkeydellä.'),
(1683519,58,19,44,21,'Jos me olisimme unhottaneet Jumalamme nimen ja ojentaneet kätemme vieraan jumalan puoleen,'),
(1683520,58,19,44,22,'eikö Jumala olisi sitä tutkituksi saanut, sillä hän tuntee sydämen salaisuudet?'),
(1683521,58,19,44,23,'Ei, vaan sinun tähtesi meitä surmataan kaiken päivää, meitä pidetään teuraslampaina.'),
(1683522,58,19,44,24,'Heräjä, miksi nukut, Herra? Nouse, älä iäksi hylkää.'),
(1683523,58,19,44,25,'Miksi peität kasvosi, unhotat meidän kurjuutemme ja ahdistuksemme?'),
(1683524,58,19,44,26,'Sillä meidän sielumme on vaipunut tomuun, meidän ruumiimme painunut maahan.'),
(1683525,58,19,44,27,'Nouse, auta meitä ja lunasta meidät armosi tähden.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683526,58,19,45,1,'Veisuunjohtajalle; veisataan kuin: "Liljat"; koorahilaisten mietevirsi; laulu rakkaudesta.'),
(1683527,58,19,45,2,'Minun sydämeni tulvii ihania sanoja; minä lausun: kuninkaasta on minun lauluni, minun kieleni on kerkeän kirjurin kynä.'),
(1683528,58,19,45,3,'Sinä olet ihmislapsista ihanin, suloisuus on vuodatettu sinun huulillesi, sentähden Jumala siunaa sinua iankaikkisesti.'),
(1683529,58,19,45,4,'Vyötä miekka vyöllesi, sinä sankari, vyöttäydy kunniaasi ja korkeuteesi.'),
(1683530,58,19,45,5,'Ole onnekas korkeudessasi. Nouse sotavaunuihisi totuuden, nöyryyden ja vanhurskauden puolesta, ja oikea kätesi opettakoon sinulle peljättäviä tekoja.'),
(1683531,58,19,45,6,'Sinun nuolesi ovat terävät, kansat kaatuvat sinun allesi; kuninkaan vihollisten sydämet lävistetään.'),
(1683532,58,19,45,7,'Jumala, sinun valtaistuimesi pysyy aina ja iankaikkisesti; sinun valtakuntasi valtikka on oikeuden valtikka.'),
(1683533,58,19,45,8,'Sinä rakastat vanhurskautta ja vihaat vääryyttä; sentähden on Jumala, sinun Jumalasi, voidellut sinua iloöljyllä enemmän kuin sinun osaveljiäsi.'),
(1683534,58,19,45,9,'Mirhaa, aloeta ja kassiaa tuoksuvat kaikki sinun vaatteesi, kanteleet helisevät sinun iloksesi norsunluisista palatseista.'),
(1683535,58,19,45,10,'Kuningasten tyttäriä on sinun kaunistuksenasi, kuningatar seisoo sinun oikealla puolellasi, Oofirin kullassa.'),
(1683536,58,19,45,11,'Kuule, tytär, katso ja kallista korvasi, unhota kansasi ja isäsi huone,'),
(1683537,58,19,45,12,'ja saakoon kuningas halun sinun kauneuteesi, sillä hän on sinun herrasi. Kumarra häntä.'),
(1683538,58,19,45,13,'Tytär Tyyro ja kansan rikkaimmat etsivät lahjoillaan sinun suosiotasi.'),
(1683539,58,19,45,14,'Ylen ihana on kuninkaan tytär sisäkammiossa, kultakudosta on hänen pukunsa.'),
(1683540,58,19,45,15,'Kirjailluissa vaatteissa hänet saatetaan kuninkaan tykö. Neitsyet seuraavat häntä, hänen ystävättärensä tuodaan sinun tykösi.'),
(1683541,58,19,45,16,'Ilolla ja riemulla heitä saatetaan, he astuvat kuninkaan palatsiin.'),
(1683542,58,19,45,17,'Sinun poikasi tulkoot sinun isiesi sijaan; aseta heidät ruhtinaiksi kaikkeen maahan.'),
(1683543,58,19,45,18,'Minä teen sinun nimesi kuuluksi suvusta sukuun; sentähden kansat sinua ylistävät aina ja iankaikkisesti.'),
(1683544,58,19,46,1,'Veisuunjohtajalle; koorahilaisten laulu, korkeassa äänialassa.'),
(1683545,58,19,46,2,'Jumala on meidän turvamme ja väkevyytemme, apumme hädässä aivan vahva.'),
(1683546,58,19,46,3,'Sentähden emme pelkää, vaikka maa järkkyisi ja vuoret meren pohjaan vajoaisivat,'),
(1683547,58,19,46,4,'vaikka sen vedet pauhaisivat ja kuohuisivat ja vuoret vapisisivat sen raivosta. Sela.'),
(1683548,58,19,46,5,'Virta lähteinensä ilahuttaa Jumalan kaupungin, Korkeimman pyhät asunnot.'),
(1683549,58,19,46,6,'Jumala on sen keskellä, ei se horju, Jumala auttaa sitä jo aamun koittaessa.'),
(1683550,58,19,46,7,'Pakanat pauhaavat, valtakunnat horjuvat; kun hän jylisee, huojuu maa.'),
(1683551,58,19,46,8,'Herra Sebaot on meidän kanssamme, Jaakobin Jumala on meidän linnamme. Sela.'),
(1683552,58,19,46,9,'Tulkaa, katsokaa Herran töitä, hänen, joka tekee hämmästyttäviä tekoja maan päällä:'),
(1683553,58,19,46,10,'hän lopettaa sodat maan ääriin saakka, hän särkee jousen, taittaa keihään, polttaa sotavaunut tulessa.'),
(1683554,58,19,46,11,'"Heretkää ja tietäkää, että minä olen Jumala, korkea kansojen keskellä, korkea maan päällä."'),
(1683555,58,19,46,12,'Herra Sebaot on meidän kanssamme, Jaakobin Jumala on meidän linnamme. Sela.'),
(1683556,58,19,47,1,'Veisuunjohtajalle; koorahilaisten virsi.'),
(1683557,58,19,47,2,'Paukuttakaa käsiänne, kaikki kansat, kohottakaa Jumalalle riemuhuuto.'),
(1683558,58,19,47,3,'Sillä Herra on korkein, peljättävä, kaiken maan suuri kuningas.'),
(1683559,58,19,47,4,'Hän kukistaa kansat meidän allemme ja kansakunnat jalkaimme alle.'),
(1683560,58,19,47,5,'Hän on valinnut meille perintömaamme, joka on Jaakobin, hänen rakkaansa, kunnia. Sela.'),
(1683561,58,19,47,6,'Jumala astuu ylös riemun raikuessa, Herra pasunain pauhatessa.'),
(1683562,58,19,47,7,'Veisatkaa Jumalalle, veisatkaa, veisatkaa meidän kuninkaallemme, veisatkaa.'),
(1683563,58,19,47,8,'Sillä Jumala on kaiken maan kuningas. Veisatkaa hänelle virsi.'),
(1683564,58,19,47,9,'Jumala on kansojen kuningas, Jumala istuu pyhällä istuimellansa.'),
(1683565,58,19,47,10,'Kansojen päämiehet kokoontuvat Aabrahamin Jumalan kansaksi. Sillä maan kilvet ovat Jumalan; hän on ylen korkea.'),
(1683566,58,19,48,1,'Laulu, koorahilaisten virsi.'),
(1683567,58,19,48,2,'Suuri on Herra ja korkeasti ylistettävä meidän Jumalamme kaupungissa, pyhällä vuorellansa.'),
(1683568,58,19,48,3,'Kauniina kohoaa, kaiken maan ilona, pohjan puolella Siionin vuori, suuren kuninkaan kaupunki.'),
(1683569,58,19,48,4,'Jumala on sen linnoissa turvaksi tunnettu.'),
(1683570,58,19,48,5,'Sillä katso, kuninkaat kokoontuivat, hyökkäsivät yhdessä.'),
(1683571,58,19,48,6,'Mutta he näkivät sen, hämmästyivät, peljästyivät ja pakenivat pois.'),
(1683572,58,19,48,7,'Vavistus valtasi heidät siellä, tuska niinkuin synnyttäväisen.'),
(1683573,58,19,48,8,'Itätuulella sinä särjet Tarsiin-laivat.'),
(1683574,58,19,48,9,'Niinkuin me olimme kuulleet, niin me sen nyt näimme Herran Sebaotin kaupungissa, meidän Jumalamme kaupungissa: Jumala pitää sen lujana iankaikkisesti. Sela.'),
(1683575,58,19,48,10,'Jumala, me tutkistelemme sinun armoasi sinun temppelissäsi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683576,58,19,48,11,'Jumala, niinkuin sinun nimesi, niin ulottuu sinun ylistyksesi maan ääriin saakka; sinun oikea kätesi on vanhurskautta täynnä.'),
(1683577,58,19,48,12,'Siionin vuori iloitsee, Juudan tyttäret riemuitsevat sinun tuomioistasi.'),
(1683578,58,19,48,13,'Kiertäkää Siion, käykää sen ympäri, lukekaa sen tornit.'),
(1683579,58,19,48,14,'Tarkatkaa sen muurit, kulkekaa sen linnat, kertoaksenne niistä tulevalle polvelle.'),
(1683580,58,19,48,15,'Sillä tämä on Jumala, meidän Jumalamme, aina ja iankaikkisesti; hän johdattaa meitä kuolemaan asti.'),
(1683581,58,19,49,1,'Veisuunjohtajalle; koorahilaisten virsi.'),
(1683582,58,19,49,2,'Kuulkaa tämä, kaikki kansat, ottakaa korviinne, maailman asukkaat kaikki,'),
(1683583,58,19,49,3,'sekä alhaiset että ylhäiset, niin rikkaat kuin köyhät.'),
(1683584,58,19,49,4,'Minun suuni puhuu viisautta, minun sydämeni ajatus on ymmärrystä.'),
(1683585,58,19,49,5,'Minä kallistan korvani kuulemaan mietelauseita, minä selitän ongelmani kannelta soittaen.'),
(1683586,58,19,49,6,'Miksi minä pelkäisin pahoina päivinä, kun minun vainoojani vääryys piirittää minut?'),
(1683587,58,19,49,7,'He luottavat tavaroihinsa ja kerskaavat suuresta rikkaudestaan.'),
(1683588,58,19,49,8,'Kukaan ei voi veljeänsä lunastaa eikä hänestä Jumalalle sovitusta maksaa.'),
(1683589,58,19,49,9,'Sillä hänen sielunsa lunastus on ylen kallis ja jää iäti suorittamatta,'),
(1683590,58,19,49,10,'että hän saisi elää iankaikkisesti eikä kuolemaa näkisi.'),
(1683591,58,19,49,11,'Vaan hänen täytyy nähdä, että viisaat kuolevat, että tyhmät ja järjettömät myös hukkuvat ja jättävät toisille tavaransa.'),
(1683592,58,19,49,12,'He luulevat, että heidän huoneensa pysyvät iäti ja heidän asuntonsa polvesta polveen; he nimittävät maatiloja nimensä mukaan.'),
(1683593,58,19,49,13,'Mutta ihminen, mahtavinkaan, ei ole pysyväinen: hän on verrattava eläimiin, jotka hukkuvat.'),
(1683594,58,19,49,14,'Näin käy niiden, jotka itseensä luottavat, ja heidän perässään niiden, jotka mielistyvät heidän puheisiinsa. Sela.'),
(1683595,58,19,49,15,'Kuin lammaslauma heidät viedään tuonelaan, kuolema heitä kaitsee, jo huomenna oikeamieliset astuvat heidän ylitsensä; tuonela kalvaa heidän hahmoansa, eikä heillä ole asuntoa.'),
(1683596,58,19,49,16,'Mutta minun sieluni Jumala lunastaa tuonelan vallasta, sillä hän ottaa minut huomaansa. Sela.'),
(1683597,58,19,49,17,'Älä pelkää, jos joku rikastuu, jos hänen talonsa komeus karttuu.'),
(1683598,58,19,49,18,'Sillä kuollessaan ei hän ota mitään mukaansa, eikä hänen komeutensa astu alas hänen jäljessänsä.'),
(1683599,58,19,49,19,'Vaikka hän eläissänsä kiittää itseään siunatuksi, vaikka sinua ylistetään, kun vietät hyviä päiviä,'),
(1683600,58,19,49,20,'täytyy sinun mennä isiesi suvun tykö, jotka eivät ikinä enää valoa näe.'),
(1683601,58,19,49,21,'Ihminen, mahtavinkin, on ymmärrystä vailla, hän on verrattava eläimiin, jotka hukkuvat.'),
(1683602,58,19,50,1,'Aasafin virsi. Jumala, Herra Jumala, puhuu ja kutsuu maan auringon noususta hamaan sen laskuun.'),
(1683603,58,19,50,2,'Siionista, jonka kauneus on täydellinen, Jumala ilmestyy kirkkaudessa.'),
(1683604,58,19,50,3,'Meidän Jumalamme tulee eikä vaikene, hänen edellänsä käy kuluttava tuli ja hänen ympärillänsä väkevä myrsky.'),
(1683605,58,19,50,4,'Hän kutsuu taivaat ylhäältä ja maan, tuomitakseen kansansa:'),
(1683606,58,19,50,5,'"Kootkaa minun eteeni minun hurskaani, jotka uhreja uhraten ovat tehneet minun kanssani liiton".'),
(1683607,58,19,50,6,'Ja taivaat julistavat hänen vanhurskauttansa, sillä Jumala on tuomari. Sela.'),
(1683608,58,19,50,7,'"Kuule, minun kansani, minä puhun; kuule, Israel, minä todistan sinua vastaan. Minä olen Jumala, sinun Jumalasi.'),
(1683609,58,19,50,8,'En minä sinun teurasuhreistasi sinua nuhtele, ja sinun polttouhrisi ovat aina minun edessäni.'),
(1683610,58,19,50,9,'En minä ota härkiä sinun talostasi enkä kauriita sinun tarhoistasi.'),
(1683611,58,19,50,10,'Sillä minun ovat kaikki metsän eläimet ja tuhansien vuorten karjat.'),
(1683612,58,19,50,11,'Minä tunnen kaikki vuorten linnut, ja kaikki, mikä kedolla liikkuu, on minun edessäni.'),
(1683613,58,19,50,12,'Jos minä isoaisin, en minä sitä sinulle sanoisi; sillä minun on maanpiiri ja kaikki, mitä siinä on.'),
(1683614,58,19,50,13,'Minäkö söisin härkien lihaa tai joisin kauristen verta?'),
(1683615,58,19,50,14,'Uhraa Jumalalle kiitos ja täytä lupauksesi Korkeimmalle.'),
(1683616,58,19,50,15,'Ja avuksesi huuda minua hädän päivänä, niin minä tahdon auttaa sinua, ja sinun pitää kunnioittaman minua."'),
(1683617,58,19,50,16,'Mutta jumalattomalle Jumala sanoo: "Mikä sinä olet puhumaan minun käskyistäni ja ottamaan minun liittoni suuhusi?'),
(1683618,58,19,50,17,'Sinä, joka vihaat kuritusta ja heität minun sanani selkäsi taakse!'),
(1683619,58,19,50,18,'Jos sinä näet varkaan, niin sinä mielistyt häneen, ja sinä pidät yhtä avionrikkojain kanssa.'),
(1683620,58,19,50,19,'Sinä päästät suusi puhumaan pahaa, ja sinun kielesi punoo petosta.'),
(1683621,58,19,50,20,'Sinä istut ja puhut veljeäsi vastaan, sinä panettelet äitisi poikaa.'),
(1683622,58,19,50,21,'Näitä sinä teet, ja minäkö olisin vaiti? Luuletko, että minä olen sinun kaltaisesi? Minä nuhtelen sinua ja asetan nämä sinun silmäisi eteen.'),
(1683623,58,19,50,22,'Ymmärtäkää tämä te, jotka Jumalan unhotatte, etten minä raatelisi, eikä olisi pelastajaa.'),
(1683624,58,19,50,23,'Joka kiitosta uhraa, se kunnioittaa minua; joka ottaa tiestänsä vaarin, sen minä annan nähdä Jumalan autuuden."'),
(1683625,58,19,51,1,'Veisuunjohtajalle; Daavidin virsi,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683626,58,19,51,2,'kun profeetta Naatan tuli hänen luokseen, sen jälkeen kuin hän oli yhtynyt Batsebaan.'),
(1683627,58,19,51,3,'Jumala, ole minulle armollinen hyvyytesi tähden; pyyhi pois minun syntini suuren laupeutesi tähden.'),
(1683628,58,19,51,4,'Pese minut puhtaaksi rikoksestani, puhdista minut synnistäni.'),
(1683629,58,19,51,5,'Sillä minä tunnen rikokseni, ja minun syntini on aina minun edessäni.'),
(1683630,58,19,51,6,'Sinua ainoata vastaan minä olen syntiä tehnyt, tehnyt sitä, mikä on pahaa sinun silmissäsi; mutta sinä olet oikea puheessasi ja puhdas tuomitessasi.'),
(1683631,58,19,51,7,'Katso, minä olen synnissä syntynyt, ja äitini on minut synnissä siittänyt.'),
(1683632,58,19,51,8,'Katso, totuutta sinä tahdot salatuimpaan saakka, ja sisimmässäni sinä ilmoitat minulle viisauden.'),
(1683633,58,19,51,9,'Puhdista minut isopilla, että minä puhdistuisin, pese minut, että minä lunta valkeammaksi tulisin.'),
(1683634,58,19,51,10,'Anna minun kuulla iloa ja riemua, että ihastuisivat ne luut, jotka särkenyt olet.'),
(1683635,58,19,51,11,'Peitä kasvosi näkemästä minun syntejäni, pyyhi pois kaikki minun pahat tekoni.'),
(1683636,58,19,51,12,'Jumala, luo minuun puhdas sydän ja anna minulle uusi, vahva henki.'),
(1683637,58,19,51,13,'Älä heitä minua pois kasvojesi edestä, äläkä ota minulta pois Pyhää Henkeäsi.'),
(1683638,58,19,51,14,'Anna minulle jälleen autuutesi ilo, ja tue minua alttiuden hengellä.'),
(1683639,58,19,51,15,'Minä tahdon opettaa väärille sinun tiesi, että syntiset sinun tykösi palajaisivat.'),
(1683640,58,19,51,16,'Päästä minut verenvioista, Jumala, minun autuuteni Jumala, että minun kieleni riemuitsisi sinun vanhurskaudestasi.'),
(1683641,58,19,51,17,'Herra, avaa minun huuleni, että minun suuni julistaisi sinun kiitostasi.'),
(1683642,58,19,51,18,'Sillä ei sinulle kelpaa teurasuhri, sen minä kyllä antaisin; polttouhri ei ole sinulle mieleen.'),
(1683643,58,19,51,19,'Jumalalle kelpaava uhri on särjetty henki; särjettyä ja murtunutta sydäntä et sinä, Jumala, hylkää.'),
(1683644,58,19,51,20,'Osoita armossasi hyvyyttä Siionille, rakenna Jerusalemin muurit.'),
(1683645,58,19,51,21,'Silloin sinulle kelpaavat oikeat teurasuhrit, polttouhrit ja kokonaisuhrit; silloin uhrataan härkiä sinun alttarillasi.'),
(1683646,58,19,52,1,'Veisuunjohtajalle; Daavidin mietevirsi,'),
(1683647,58,19,52,2,'kun edomilainen Dooeg tuli ja ilmoitti Saulille, sanoen hänelle: "Daavid on mennyt Ahimelekin taloon".'),
(1683648,58,19,52,3,'Miksi kerskaat pahuudestasi, sinä väkivaltainen? Jumalan armo pysyy alati.'),
(1683649,58,19,52,4,'Sinun kielesi punoo turmiota, se on kuin terävä partaveitsi, sinä petoksen tekijä.'),
(1683650,58,19,52,5,'Sinä rakastat pahaa etkä hyvää, sinä puhut valhetta etkä totta. Sela.'),
(1683651,58,19,52,6,'Sinä rakastat kaikkia surman sanoja, sinä kavala kieli.'),
(1683652,58,19,52,7,'Sentähden myös Jumala kukistaa sinut ainiaaksi, hän tarttuu sinuun ja raastaa sinut majastasi, repäisee sinut juurinesi elävien maasta. Sela.'),
(1683653,58,19,52,8,'Ja vanhurskaat näkevät sen ja pelkäävät, ja he nauravat häntä:'),
(1683654,58,19,52,9,'"Katso, siinä on mies, joka ei pitänyt Jumalaa turvanansa, vaan luotti suureen rikkauteensa ja röyhkeili häijyydessänsä".'),
(1683655,58,19,52,10,'Mutta minä olen kuin viheriöitsevä öljypuu Jumalan huoneessa, minä turvaan Jumalan armoon aina ja iankaikkisesti.'),
(1683656,58,19,52,11,'Minä kiitän sinua iäti, että sen teit, ja minä odotan sinun hurskaittesi edessä sinun nimeäsi, sillä se on hyvä.'),
(1683657,58,19,53,1,'Veisuunjohtajalle; veisataan kuin: "Sairaus"; Daavidin mietevirsi.'),
(1683658,58,19,53,2,'Hullu sanoo sydämessänsä: "Ei ole Jumalaa". Turmiollinen ja iljettävä on heidän väärä menonsa; ei ole ketään, joka tekee sitä, mikä hyvä on.'),
(1683659,58,19,53,3,'Jumala katsoo taivaasta ihmislapsiin nähdäksensä, onko ketään ymmärtäväistä, ketään, joka etsii Jumalaa.'),
(1683660,58,19,53,4,'Mutta kaikki he ovat poikenneet pois, kaikki tyynni kelvottomiksi käyneet; ei ole ketään, joka tekee sitä, mikä hyvä on, ei yhden yhtäkään.'),
(1683661,58,19,53,5,'Eivätkö he mitään käsitä, nuo väärintekijät, jotka saavat leipänsä syömällä minun kansaani, eivätkä avuksensa huuda Jumalaa?'),
(1683662,58,19,53,6,'Siinä heidät valtaa kauhu, missä ei kauhistavaa ole; sillä Jumala hajottaa niiden luut, jotka sinua saartavat. Sinä saatat heidät häpeään, sillä Jumala hylkää heidät.'),
(1683663,58,19,53,7,'Oi, että Israelille tulisi pelastus Siionista! Kun Jumala kääntää kansansa kohtalon, silloin Jaakob riemuitsee, Israel iloitsee.'),
(1683664,58,19,54,1,'Veisuunjohtajalle; kielisoittimilla; Daavidin mietevirsi,'),
(1683665,58,19,54,2,'kun siifiläiset tulivat ja sanoivat Saulille: "Daavid piileskelee meidän luonamme".'),
(1683666,58,19,54,3,'Jumala, pelasta minut nimesi voimalla, aja minun asiani väkevyydelläsi.'),
(1683667,58,19,54,4,'Jumala, kuule minun rukoukseni, ota korviisi minun suuni sanat.'),
(1683668,58,19,54,5,'Sillä muukalaiset nousevat minua vastaan, ja väkivaltaiset väijyvät minun henkeäni, eivät he pidä Jumalaa silmäinsä edessä. Sela.'),
(1683669,58,19,54,6,'Katso, Jumala on minun auttajani, Herra on minun sieluni tuki.'),
(1683670,58,19,54,7,'Kohdatkoon paha minun vihamiehiäni, hävitä heidät uskollisuudessasi.'),
(1683671,58,19,54,8,'Niin minä alttiisti sinulle uhraan, minä ylistän sinun nimeäsi, Herra, sillä se on hyvä.'),
(1683672,58,19,54,9,'Sillä hän pelastaa minut kaikesta hädästä, ja minun silmäni saa mielikseen katsella vihollisiani.'),
(1683673,58,19,55,1,'Veisuunjohtajalle; kielisoittimilla; Daavidin mietevirsi.'),
(1683674,58,19,55,2,'Jumala, ota korviisi minun rukoukseni, älä kätkeydy, kun minä armoa anon.'),
(1683675,58,19,55,3,'Kuuntele minua ja vastaa minulle. Minä kuljen rauhatonna murheessani ja huokaan,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683676,58,19,55,4,'koska vihamies huutaa ja jumalaton ahdistaa; sillä he vyöryttävät minun päälleni turmiota ja vihassa minua vainoavat.'),
(1683677,58,19,55,5,'Sydämeni minun rinnassani vapisee, kuoleman kauhut lankeavat minun päälleni.'),
(1683678,58,19,55,6,'Pelko ja vavistus valtaa minut, pöyristys peittää minut.'),
(1683679,58,19,55,7,'Ja minä sanon: Olisipa minulla siivet kuin kyyhkysellä, niin minä lentäisin pois ja pääsisin lepoon!'),
(1683680,58,19,55,8,'Katso, minä pakenisin kauas ja yöpyisin erämaassa. Sela.'),
(1683681,58,19,55,9,'Minä rientäisin pakopaikkaani rajuilman ja myrskyn alta.'),
(1683682,58,19,55,10,'Sekoita, Herra, tee eripuraiseksi heidän kielensä, sillä minä näen väkivaltaa ja riitaa kaupungissa.'),
(1683683,58,19,55,11,'Yötä päivää he sitä kiertävät, sen muureja pitkin, vääryys ja vaiva on sen keskellä.'),
(1683684,58,19,55,12,'Sen keskellä on turmio, sorto ja petos ei väisty sen torilta.'),
(1683685,58,19,55,13,'Sillä ei minua herjaa vihollinen - sen minä kestäisin - eikä minua vastaan ylvästele minun vihamieheni - hänen edestään minä voisin lymytä;'),
(1683686,58,19,55,14,'vaan sinä, minun vertaiseni, sinä, minun ystäväni ja uskottuni,'),
(1683687,58,19,55,15,'jonka kanssa me elimme suloisessa sovussa, yhdessä vaelsimme Jumalan huoneeseen juhlakansan kohinassa!'),
(1683688,58,19,55,16,'Karatkoon kuolema heidän kimppuunsa, menkööt he elävältä alas tuonelaan, sillä heidän asunnoissansa ja sydämissänsä vallitsee sula pahuus.'),
(1683689,58,19,55,17,'Mutta minä huudan Jumalaa, ja Herra pelastaa minut.'),
(1683690,58,19,55,18,'Illoin, aamuin ja keskipäivällä minä valitan ja huokaan, ja hän kuulee minun ääneni.'),
(1683691,58,19,55,19,'Hän päästää minun sieluni heistä rauhaan, etteivät he minua saavuta; sillä paljon on niitä, jotka ovat minua vastaan.'),
(1683692,58,19,55,20,'Jumala kuulee sen ja vastaa heille, hän, joka hallitsee hamasta muinaisuudesta. Sela. Sillä he eivät muuta mieltänsä eivätkä pelkää Jumalaa.'),
(1683693,58,19,55,21,'Tuo mies käy käsiksi niihin, jotka hänen kanssaan rauhassa elävät, hän rikkoo liittonsa.'),
(1683694,58,19,55,22,'Hänen suunsa on voita sulavampi, mutta hänellä on sota mielessä; hänen sanansa ovat öljyä lauhkeammat, mutta ovat kuin paljastetut miekat.'),
(1683695,58,19,55,23,'Heitä murheesi Herran huomaan, hän pitää sinusta huolen, ei hän salli vanhurskaan ikinä horjua.'),
(1683696,58,19,55,24,'Mutta heidät sinä, Jumala, syökset tuonelan syvyyteen; murhamiehet ja petturit eivät pääse puoleen ikäänsä. Mutta minä turvaan sinuun.'),
(1683697,58,19,56,1,'Veisuunjohtajalle; veisataan kuin: "Mykkä kyyhkynen kaukaisessa maassa". Daavidin laulu, kun filistealaiset ottivat hänet kiinni Gatissa.'),
(1683698,58,19,56,2,'Jumala, ole minulle armollinen, sillä ihmiset minua polkevat, joka päivä he sotivat minua vastaan, ahdistavat minua.'),
(1683699,58,19,56,3,'Joka päivä minun vihamieheni minua polkevat; sillä paljon on niitä, jotka ylpeästi sotivat minua vastaan.'),
(1683700,58,19,56,4,'Mutta sinä päivänä, jota minä pelkään, minä turvaan sinuun.'),
(1683701,58,19,56,5,'Jumalaan minä luotan ja ylistän hänen sanaansa, Jumalaan minä turvaan enkä pelkää. Mitä liha minulle tekisi?'),
(1683702,58,19,56,6,'Joka päivä he vääntelevät minun sanojani, kaikki heidän ajatuksensa tarkoittavat minulle pahaa.'),
(1683703,58,19,56,7,'He ahdistavat, he väijyvät minua, he vakoilevat minun askeleitani, sillä he tavoittavat minun henkeäni.'),
(1683704,58,19,56,8,'Hekö pahuudessaan pelastuisivat? Syökse, Jumala, vihassasi kansat maahan.'),
(1683705,58,19,56,9,'Sinä olet lukenut minun pakolaispäiväni; pane leiliisi minun kyyneleeni, ovathan ne sinun kirjassasi.'),
(1683706,58,19,56,10,'Kerran väistyvät minun viholliseni, sinä päivänä, jona minä huudan; minä tiedän, että Jumala on minun puolellani.'),
(1683707,58,19,56,11,'Jumalaan minä luotan ja ylistän hänen sanaansa, Herraan minä luotan ja ylistän hänen sanaansa.'),
(1683708,58,19,56,12,'Jumalaan minä turvaan enkä pelkää. Mitä ihminen minulle tekisi?'),
(1683709,58,19,56,13,'Minulla on lupaus täytettävänä sinulle, Jumala; minä maksan sinulle kiitosuhrit.'),
(1683710,58,19,56,14,'Sillä sinä pelastit minun sieluni kuolemasta, minun jalkani kompastumasta, että minä vaeltaisin Jumalan edessä, eläväin valkeudessa.'),
(1683711,58,19,57,1,'Veisuunjohtajalle; veisataan kuin: "Älä turmele"; Daavidin laulu, kun hän pakeni Saulia luolaan.'),
(1683712,58,19,57,2,'Jumala, ole minulle armollinen, ole minulle armollinen; sillä sinuun minun sieluni turvaa. Minä turvaan sinun siipiesi suojaan, kunnes onnettomuudet ovat ohitse.'),
(1683713,58,19,57,3,'Minä huudan Jumalaa, Korkeinta, avukseni, Jumalaa, joka vie minun asiani päätökseen.'),
(1683714,58,19,57,4,'Hän lähettää taivaasta minulle pelastuksen, kun minua herjaavat minun polkijani. Sela. Jumala lähettää armonsa ja totuutensa.'),
(1683715,58,19,57,5,'Minun sieluni on jalopeurain keskellä, minun täytyy maata tultasuitsevaisten seassa, ihmisten, joiden hampaat ovat keihäitä ja nuolia ja joiden kieli on terävä miekka.'),
(1683716,58,19,57,6,'Korota itsesi yli taivasten, Jumala, ja kunniasi yli kaiken maan.'),
(1683717,58,19,57,7,'Verkon he virittivät minun askelteni tielle, painoivat minun sieluni maahan, kaivoivat eteeni kuopan, mutta itse he siihen suistuivat. Sela.'),
(1683718,58,19,57,8,'Jumala, minun sydämeni on valmis, minun sydämeni on valmis: minä tahdon veisata ja soittaa.'),
(1683719,58,19,57,9,'Heräjä, minun sieluni; heräjä, harppu ja kannel. Minä tahdon herättää aamuruskon.'),
(1683720,58,19,57,10,'Herra, sinua minä kiitän kansojen joukossa, veisaan sinun kiitostasi kansakuntien keskellä.'),
(1683721,58,19,57,11,'Sillä suuri on sinun armosi ja ulottuu hamaan taivaisiin, ja sinun totuutesi pilviin asti.'),
(1683722,58,19,57,12,'Korota itsesi yli taivasten, Jumala, ja kunniasi yli kaiken maan.'),
(1683723,58,19,58,1,'Veisuunjohtajalle; veisataan kuin: "Älä turmele"; Daavidin laulu.'),
(1683724,58,19,58,2,'Totisesti, onko vanhurskaus mykkä, ja te puhutte? Tekö tuomitsette oikein, te ihmislapset?'),
(1683725,58,19,58,3,'Ei, vaan te hankitsette sydämessänne vääryyttä, teidän kätenne käyttävät maassa väkivallan vaakaa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683726,58,19,58,4,'Luopuneita ovat jumalattomat äidin kohdusta asti, eksyneitä valhettelijat hamasta äidin helmasta.'),
(1683727,58,19,58,5,'Heidän myrkkynsä on niinkuin käärmeen myrkky, he ovat kuin kuuro kyy, joka korvansa tukitsee,'),
(1683728,58,19,58,6,'ettei se kuulisi lumoojan ääntä, taitavan taikojan loitsuja.'),
(1683729,58,19,58,7,'Jumala, särje hampaat heidän suustansa, Herra, murra nuorten jalopeurain raateluhampaat.'),
(1683730,58,19,58,8,'Haihtukoot he tyhjiin niinkuin vesi, joka valuu kuiviin. Kun he ampuvat nuolensa, olkoot ne kuin kärjettömät.'),
(1683731,58,19,58,9,'Olkoot he niinkuin etana, joka sulaa mataessaan, niinkuin vaimon keskoiset, jotka eivät aurinkoa näe.'),
(1683732,58,19,58,10,'Ennenkuin teidän patanne tuntevat tulen altansa orjantappuroista, hän myrskyllään puhaltaa pois kaiken, niin raa''an kuin kypsänkin.'),
(1683733,58,19,58,11,'Vanhurskas iloitsee, kun hän näkee koston, hän pesee jalkansa jumalattoman veressä.'),
(1683734,58,19,58,12,'Silloin ihmiset sanovat: "Totisesti, vanhurskaalla on hedelmä; totisesti, on Jumala, joka tuomitsee maan päällä".'),
(1683735,58,19,59,1,'Veisuunjohtajalle; veisataan kuin: "Älä turmele"; Daavidin laulu, kun Saul lähetti vartioimaan hänen taloansa, tappaakseen hänet.'),
(1683736,58,19,59,2,'Jumalani, pelasta minut vihollisistani, suojele minua niiltä, jotka nousevat minua vastaan.'),
(1683737,58,19,59,3,'Pelasta minut pahantekijöistä, vapahda minut murhamiehistä.'),
(1683738,58,19,59,4,'Sillä katso, he väijyvät minun henkeäni; julmurit kokoontuvat minua vastaan, vaikka en ole rikkonut enkä syntiä tehnyt, Herra.'),
(1683739,58,19,59,5,'Ilman minun syytäni he juoksevat ja hankkiutuvat; heräjä, käy minua kohtaamaan ja katso.'),
(1683740,58,19,59,6,'Ja sinä, Herra, Jumala Sebaot, Israelin Jumala, heräjä kostamaan kaikille pakanoille. Älä säästä ketään uskotonta väärintekijää. Sela.'),
(1683741,58,19,59,7,'He tulevat ehtoolla, ulvovat kuin koirat ja kiertävät kaupunkia.'),
(1683742,58,19,59,8,'Katso, he purkavat suustaan sisuansa, miekat ovat heidän huulillansa, sillä: "Kuka sen kuulee?"'),
(1683743,58,19,59,9,'Mutta sinä, Herra, naurat heille, sinä pidät kaikkia pakanoita pilkkanasi.'),
(1683744,58,19,59,10,'Sinä, minun väkevyyteni, sinusta minä otan vaarin, sillä Jumala on minun linnani.'),
(1683745,58,19,59,11,'Minun armollinen Jumalani käy minua kohden, Jumala antaa minun nähdä iloni vihollisistani.'),
(1683746,58,19,59,12,'Älä heitä tapa, ettei minun kansani sitä unhottaisi. Saata voimallasi heidät harhailemaan ja syökse heidät maahan, Herra, meidän kilpemme.'),
(1683747,58,19,59,13,'Minkä he huulillaan puhuvat, sen he suullaan syntiä tekevät. Joutukoot he ylpeydessään kiinni kirousten ja valheiden tähden, joita he puhuvat.'),
(1683748,58,19,59,14,'Hävitä heidät vihassasi, hävitä olemattomiin, ja tietäkööt he, että Jumala hallitsee Jaakobissa, maan ääriin saakka. Sela.'),
(1683749,58,19,59,15,'He tulevat ehtoolla, ulvovat kuin koirat ja kiertävät kaupunkia.'),
(1683750,58,19,59,16,'He harhailevat ruuan haussa; elleivät tule ravituiksi, he murisevat.'),
(1683751,58,19,59,17,'Mutta minä veisaan sinun väkevyydestäsi ja riemuitsen aamulla sinun armostasi, sillä sinä olet minun linnani ja pakopaikkani minun hätäni päivänä.'),
(1683752,58,19,59,18,'Sinä, minun väkevyyteni, sinulle minä veisaan kiitosta, sillä Jumala on minun linnani ja minun armollinen Jumalani.'),
(1683753,58,19,60,1,'Veisuunjohtajalle; veisataan kuin: "Todistuksen lilja"; Daavidin laulu, opetettavaksi,'),
(1683754,58,19,60,2,'kun hän taisteli Mesopotamian aramilaisia ja Sooban aramilaisia vastaan ja Jooab palasi ja voitti Suolalaaksossa edomilaiset, kaksitoista tuhatta miestä.'),
(1683755,58,19,60,3,'Jumala, sinä hylkäsit meidät, sinä hajotit meidät ja olit vihastunut. Auta meidät ennallemme.'),
(1683756,58,19,60,4,'Sinä saatoit maan järkkymään ja halkeilemaan, korjaa sen repeämät, sillä se horjuu.'),
(1683757,58,19,60,5,'Sinä olet antanut kansasi nähdä kovia päiviä; olet juottanut meitä päihdyttävällä viinillä.'),
(1683758,58,19,60,6,'Mutta sinä olet antanut lipun niille, jotka sinua pelkäävät, että he kokoontuisivat sen turviin, jousta pakoon. Sela.'),
(1683759,58,19,60,7,'Että sinun rakkaasi pelastetuiksi tulisivat, auta oikealla kädelläsi ja vastaa meille.'),
(1683760,58,19,60,8,'Jumala on puhunut pyhäkössänsä! Minä riemuitsen, minä jaan Sikemin ja mittaan Sukkotin laakson.'),
(1683761,58,19,60,9,'Minun on Gilead, minun on Manasse, Efraim on minun pääni suojus, Juuda minun valtikkani.'),
(1683762,58,19,60,10,'Mooab on minun pesuastiani, Edomiin minä viskaan kenkäni; Filistea, nosta minulle riemuhuuto.'),
(1683763,58,19,60,11,'Kuka vie minut varustettuun kaupunkiin? Kuka saattaa minut Edomiin?'),
(1683764,58,19,60,12,'Etkö sinä, Jumala, hyljännyt meitä? Et lähtenyt, Jumala, meidän sotajoukkojemme kanssa!'),
(1683765,58,19,60,13,'Anna meille apu ahdistajaa vastaan, sillä turha on ihmisten apu.'),
(1683766,58,19,60,14,'Jumalan voimalla me teemme väkeviä tekoja; hän tallaa meidän vihollisemme maahan.'),
(1683767,58,19,61,1,'Veisuunjohtajalle; kielisoittimilla; Daavidin virsi.'),
(1683768,58,19,61,2,'Kuule, Jumala, minun huutoni, huomaa minun rukoukseni.'),
(1683769,58,19,61,3,'Maan ääristä minä sinua huudan, kun sydämeni nääntyy. Saata minut kalliolle, joka on minulle liian korkea.'),
(1683770,58,19,61,4,'Sillä sinä olet minun turvapaikkani, vahva torni vihollista vastaan.'),
(1683771,58,19,61,5,'Suo minun asua sinun majassasi iankaikkisesti, turvautua sinun siipiesi suojaan. Sela.'),
(1683772,58,19,61,6,'Sillä sinä, Jumala, kuulet minun lupaukseni, sinä annat perinnön niille, jotka sinun nimeäsi pelkäävät.'),
(1683773,58,19,61,7,'Sinä lisäät kuninkaalle päiviä päiviin; hänen vuotensa jatkukoot polvesta polveen.'),
(1683774,58,19,61,8,'Hallitkoon hän iankaikkisesti Jumalan kasvojen edessä; säädä armo ja totuus häntä varjelemaan.'),
(1683775,58,19,61,9,'Niin minä veisaan iankaikkisesti sinun nimesi kiitosta, täytän lupaukseni päivästä päivään.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683776,58,19,62,1,'Veisuunjohtajalle; Jedutunin tapaan; Daavidin virsi.'),
(1683777,58,19,62,2,'Jumalaa yksin minun sieluni hiljaisuudessa odottaa, häneltä tulee minulle apu.'),
(1683778,58,19,62,3,'Hän yksin on minun kallioni, minun apuni ja turvani: en minä suuresti horju.'),
(1683779,58,19,62,4,'Kuinka kauan te yhtä miestä ahdistatte, hänet yhdessä surmataksenne, niinkuin hän olisi kaatuva seinä, niinkuin murrettu muuri?'),
(1683780,58,19,62,5,'He vain pitävät neuvoa, miten syöstä hänet korkeudestaan. He rakastavat valhetta, he siunaavat suullansa ja kiroavat sydämessänsä. Sela.'),
(1683781,58,19,62,6,'Odota yksin Jumalaa hiljaisuudessa, minun sieluni, sillä häneltä tulee minun toivoni.'),
(1683782,58,19,62,7,'Hän yksin on minun kallioni, minun apuni ja turvani: en minä horju.'),
(1683783,58,19,62,8,'Jumalassa on minun apuni ja kunniani. Minun väkevyyteni kallio, minun turvani on Jumala.'),
(1683784,58,19,62,9,'Turvatkaa häneen joka aika, te kansa; vuodattakaa hänen eteensä sydämenne. Jumala on meidän turvamme. Sela.'),
(1683785,58,19,62,10,'Vain tuulen henkäystä ovat ihmiset, vain valhetta ihmisten lapset: kaikki he nousevat vaa''assa ylös köykäisempinä kuin tuulenhenkäys.'),
(1683786,58,19,62,11,'Älkää luottako väkivaltaan, älkää turhaan panko toivoanne ryöstettyyn tavaraan. Jos rikkautta karttuu, älkää siihen sydäntänne kiinnittäkö.'),
(1683787,58,19,62,12,'Kerran on Jumala sanonut, kahdesti olen sen kuullut: väkevyys on Jumalan.'),
(1683788,58,19,62,13,'Ja sinun, Herra, on armo; sillä sinä maksat kullekin hänen tekojensa mukaan.'),
(1683789,58,19,63,1,'Daavidin virsi, kun hän oli Juudan erämaassa.'),
(1683790,58,19,63,2,'Jumala, sinä olet minun Jumalani, sinua minä etsin varhain; sinua minun sieluni janoaa, sinua halajaa minun ruumiini kuivassa ja nääntyvässä, vedettömässä maassa.'),
(1683791,58,19,63,3,'Niin minä katselin sinua pyhäkössä, nähdäkseni sinun voimasi ja kunniasi.'),
(1683792,58,19,63,4,'Sillä sinun armosi on parempi kuin elämä, minun huuleni ylistäkööt sinua.'),
(1683793,58,19,63,5,'Niin minä kiitän sinua elinaikani, nostan käteni sinun nimeesi.'),
(1683794,58,19,63,6,'Minun sieluni ravitaan niinkuin lihavuudella ja rasvalla, ja minun suuni ylistää sinua riemuitsevilla huulilla,'),
(1683795,58,19,63,7,'kun minä vuoteessani sinua muistan ja ajattelen sinua yön vartiohetkinä.'),
(1683796,58,19,63,8,'Sillä sinä olet minun apuni, ja sinun siipiesi suojassa minä riemuitsen.'),
(1683797,58,19,63,9,'Minun sieluni riippuu sinussa kiinni, sinun oikea kätesi tukee minua.'),
(1683798,58,19,63,10,'Mutta he etsivät minun henkeäni omaksi turmiokseen, he menevät maan syvyyksiin.'),
(1683799,58,19,63,11,'Heidät annetaan miekalle alttiiksi, he joutuvat aavikkosutten osaksi.'),
(1683800,58,19,63,12,'Mutta kuningas on iloitseva Jumalassa; hän on jokaisen kerskaus, joka hänen kauttansa vannoo. Sillä valhettelijain suu tukitaan.'),
(1683801,58,19,64,1,'Veisuunjohtajalle; Daavidin virsi.'),
(1683802,58,19,64,2,'Kuule, Jumala, minun ääneni, kun minä valitan, varjele minun elämäni vihollisen pelosta.'),
(1683803,58,19,64,3,'Kätke minut pahain seuralta, väärintekijäin riehuvalta joukolta,'),
(1683804,58,19,64,4,'jotka hiovat kielensä kuin miekan, jännittävät jousensa, nuolinaan karvaat sanat,'),
(1683805,58,19,64,5,'salaa ampuaksensa nuhteettoman. He ampuvat häntä äkisti eivätkä kavahda.'),
(1683806,58,19,64,6,'He pysyvät lujina pahoissa aikeissaan, he kehuvat, kuinka he virittävät pauloja, he sanovat: "Kuka ne näkee?"'),
(1683807,58,19,64,7,'He miettivät vääryyksiä: "Meillä on juoni valmiiksi mietittynä". Syvä on miehen sisu ja sydän.'),
(1683808,58,19,64,8,'Mutta Jumala ampuu heidät nuolella, äkisti kohtaavat heitä iskut.'),
(1683809,58,19,64,9,'He joutuvat kompastukseen, heidän oma kielensä langettaa heidät; kaikki, jotka heidät näkevät, nyökyttävät ilkkuen päätään.'),
(1683810,58,19,64,10,'Ja kaikki ihmiset peljästyvät; he julistavat Jumalan töitä ja ottavat vaarin hänen teoistansa.'),
(1683811,58,19,64,11,'Vanhurskas iloitsee Herrassa ja turvaa häneen, ja kaikki oikeamieliset kerskaavat.'),
(1683812,58,19,65,1,'Veisuunjohtajalle; Daavidin virsi, laulu.'),
(1683813,58,19,65,2,'Jumala, hiljaisuudessa kiitetään sinua Siionissa, ja sinulle täytetään lupaus.'),
(1683814,58,19,65,3,'Sinä kuulet rukouksen: sinun tykösi tulee kaikki liha.'),
(1683815,58,19,65,4,'Minun syntivelkani ovat ylen raskaat, mutta sinä annat anteeksi meidän rikoksemme.'),
(1683816,58,19,65,5,'Autuas se, jonka sinä valitset ja otat tykösi, esikartanoissasi asumaan! Salli meidän tulla ravituiksi sinun huoneesi hyvyydellä, sinun temppelisi pyhyydellä.'),
(1683817,58,19,65,6,'Ihmeellisillä teoilla sinä vastaat meille vanhurskaudessa, sinä, meidän autuutemme Jumala, sinä, kaikkien maan äärten ja kaukaisen meren turva,'),
(1683818,58,19,65,7,'joka voimallasi vahvistat vuoret ja olet vyötetty väkevyydellä;'),
(1683819,58,19,65,8,'sinä, joka asetat merten pauhinan ja niiden aaltojen pauhinan ja kansojen metelin,'),
(1683820,58,19,65,9,'niin että ne, jotka niiden äärillä asuvat, hämmästyvät sinun ihmeitäsi; aamun ja ehtoon ääret sinä täytät riemulla.'),
(1683821,58,19,65,10,'Sinä pidät maasta huolen, kastelet sen runsaasti, sinä teet sen ylen rikkaaksi. Jumalan virta on vettä täynnä. Sinä valmistat heidän viljansa, sillä niin sinä valmistat maan.'),
(1683822,58,19,65,11,'Sinä kastelet sen vaot, sinä muhennat sen multapaakut, sadekuuroilla sinä sen pehmität ja siunaat sen laihon.'),
(1683823,58,19,65,12,'Sinä kaunistat vuoden hyvyydelläsi, ja sinun askeleesi tiukkuvat lihavuutta.'),
(1683824,58,19,65,13,'Erämaan laitumet tiukkuvat, ja kukkulat vyöttäytyvät riemuun.'),
(1683825,58,19,65,14,'Kedot verhoutuvat lammaslaumoihin, ja vilja peittää laaksot. Riemuitaan ja lauletaan!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683826,58,19,66,1,'Veisuunjohtajalle; laulu, virsi. Kohottakaa Jumalalle riemuhuuto, kaikki maa,'),
(1683827,58,19,66,2,'veisatkaa hänen nimensä kunniaa, antakaa hänelle kunnia ja ylistys.'),
(1683828,58,19,66,3,'Sanokaa Jumalalle: "Kuinka peljättävät ovat sinun tekosi!" Sinun suuren voimasi tähden sinun vihollisesi matelevat sinun edessäsi.'),
(1683829,58,19,66,4,'Kaikki maa kumartakoon sinua ja veisatkoon sinun kiitostasi, veisatkoon sinun nimesi kiitosta. Sela.'),
(1683830,58,19,66,5,'Tulkaa ja katsokaa Jumalan töitä: hän on peljättävä teoissansa ihmisten lapsia kohtaan.'),
(1683831,58,19,66,6,'Meren hän muutti kuivaksi maaksi, jalkaisin käytiin virran poikki; silloin me iloitsimme hänestä.'),
(1683832,58,19,66,7,'Hän hallitsee voimallansa iankaikkisesti, hänen silmänsä vartioitsevat kansoja; niskoittelijat älkööt nostako päätänsä. Sela.'),
(1683833,58,19,66,8,'Kiittäkää, te kansat, meidän Jumalaamme, korkealle kaiuttakaa hänen ylistystänsä.'),
(1683834,58,19,66,9,'Hän antaa meidän sielullemme elämän eikä salli meidän jalkamme horjua.'),
(1683835,58,19,66,10,'Sillä sinä, Jumala, olet koetellut meitä, olet sulattanut meitä, niinkuin hopea sulatetaan.'),
(1683836,58,19,66,11,'Sinä veit meidät verkkoon, panit kuorman meidän lanteillemme.'),
(1683837,58,19,66,12,'Sinä annoit ihmisten ajaa päämme päällitse, me jouduimme tuleen ja veteen. Mutta sinä veit meidät yltäkylläisyyteen.'),
(1683838,58,19,66,13,'Minä tuon sinun huoneeseesi polttouhreja, täytän sinulle lupaukseni,'),
(1683839,58,19,66,14,'joihin minun huuleni avautuivat ja jotka minun suuni hädässäni lausui.'),
(1683840,58,19,66,15,'Lihavat polttouhrit minä sinulle uhraan ynnä oinasten uhrituoksun; minä uhraan sinulle härkiä ja kauriita. Sela.'),
(1683841,58,19,66,16,'Tulkaa, kuulkaa, niin minä kerron teille, kaikki te Jumalaa pelkääväiset, mitä hän on minun sielulleni tehnyt.'),
(1683842,58,19,66,17,'Häntä minä suullani huusin, ja ylistys tuli minun kielelleni.'),
(1683843,58,19,66,18,'Jos minulla olisi vääryys sydämessäni, ei Herra minua kuulisi.'),
(1683844,58,19,66,19,'Mutta Jumala kuuli minua ja otti vaarin minun rukoukseni äänestä.'),
(1683845,58,19,66,20,'Kiitetty olkoon Jumala, joka ei hyljännyt minun rukoustani eikä ottanut minulta pois armoansa.'),
(1683846,58,19,67,1,'Veisuunjohtajalle; kielisoittimilla; virsi, laulu.'),
(1683847,58,19,67,2,'Jumala olkoon meille armollinen ja siunatkoon meitä, hän valistakoon kasvonsa meille, - Sela -'),
(1683848,58,19,67,3,'että maan päällä tunnettaisiin sinun tiesi, kaikissa pakanakansoissa sinun apusi.'),
(1683849,58,19,67,4,'Sinua, Jumala, kansat kiittäkööt, sinua kaikki kansat kiittäkööt.'),
(1683850,58,19,67,5,'Iloitkoot ja riemuitkoot kansakunnat, sillä sinä tuomitset kansat oikein ja johdatat kansakunnat maan päällä. Sela.'),
(1683851,58,19,67,6,'Sinua, Jumala, kansat kiittäkööt, sinua kaikki kansat kiittäkööt.'),
(1683852,58,19,67,7,'Maa on satonsa antanut. Siunatkoon meitä Jumala, meidän Jumalamme.'),
(1683853,58,19,67,8,'Siunatkoon meitä Jumala, ja peljätkööt häntä kaikki maan ääret.'),
(1683854,58,19,68,1,'Veisuunjohtajalle; Daavidin virsi, laulu.'),
(1683855,58,19,68,2,'Jumala nousee, hänen vihollisensa hajaantuvat, hänen vihamiehensä pakenevat hänen kasvojensa edestä.'),
(1683856,58,19,68,3,'Sinä hajotat heidät, niinkuin savu hajoaa; niinkuin vaha sulaa tulen hohteessa, niin jumalattomat häviävät Jumalan kasvojen edessä.'),
(1683857,58,19,68,4,'Mutta vanhurskaat iloitsevat ja riemuitsevat Jumalan kasvojen edessä, he ihastuvat ilosta.'),
(1683858,58,19,68,5,'Laulakaa Jumalalle, veisatkaa hänen nimensä kiitosta. Tehkää tie hänelle, joka kiitää halki arojen. Hänen nimensä on Herra, riemuitkaa hänen kasvojensa edessä.'),
(1683859,58,19,68,6,'Hän on orpojen isä ja leskien puolustaja, Jumala pyhässä asunnossansa,'),
(1683860,58,19,68,7,'Jumala, joka antaa hyljätyille kodin ja johtaa vangitut onneen. Vain niskoittelijat asuvat kuivassa maassa.'),
(1683861,58,19,68,8,'Jumala, kun sinä kävit kansasi edellä, kun sinä kuljit erämaassa, - Sela -'),
(1683862,58,19,68,9,'niin maa vapisi ja taivaat tiukkuivat Jumalan kasvojen edessä, Siinai vapisi Jumalan, Israelin Jumalan, kasvojen edessä.'),
(1683863,58,19,68,10,'Runsaalla sateella sinä, Jumala, kostutit perintömaasi; ja kun se oli näännyksissä, niin sinä virvoitit sen.'),
(1683864,58,19,68,11,'Sinun laumasi asettui siihen; hyvyydessäsi, Jumala, sinä sen kurjille valmistit.'),
(1683865,58,19,68,12,'Herra antaa sanoman, suuri on voitonsanoman saattajatarten joukko:'),
(1683866,58,19,68,13,'"Sotajoukkojen kuninkaat pakenevat, he pakenevat, ja perheen emäntä jakaa saaliin.'),
(1683867,58,19,68,14,'Jäättekö makailemaan karjatarhojen vaiheille? Kyyhkysen siivet ovat hopealla silatut, sen sulat keltaisella kullalla!'),
(1683868,58,19,68,15,'Kun Kaikkivaltias siellä hajotti kuninkaat, satoi lunta Salmonilla."'),
(1683869,58,19,68,16,'Baasanin vuori on Jumalan vuori, Baasanin vuori on monihuippuinen vuori.'),
(1683870,58,19,68,17,'Miksi te, monihuippuiset vuoret, karsaasti katsotte vuorta, jolla Jumala on mielistynyt asumaan? Totisesti, Herra asuu siellä iankaikkisesti.'),
(1683871,58,19,68,18,'Jumalan sotavaunuja on kymmenet tuhannet, on tuhannen kertaa tuhannet; Herra on niiden keskellä, pyhyydessään niinkuin Siinai.'),
(1683872,58,19,68,19,'Sinä astuit ylös korkeuteen, otit vankeja saaliiksesi, sait ihmisiä lahjaksesi: niskoittelijatkin joutuvat asumaan Herran Jumalan tykönä.'),
(1683873,58,19,68,20,'Kiitetty olkoon Herra joka päivä. Meitä kantaa Jumala, meidän apumme. Sela.'),
(1683874,58,19,68,21,'Meillä on Jumala, Jumala, joka auttaa, ja Herra, Herra, joka kuolemasta vapahtaa.'),
(1683875,58,19,68,22,'Mutta Jumala murskaa vihollistensa pään, niiden karvaisen päälaen, jotka synneissänsä vaeltavat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683876,58,19,68,23,'Herra sanoo: "Baasanista minä heidät palautan, palautan meren syvyyksistä,'),
(1683877,58,19,68,24,'että sinä polkisit jalkasi vereen, että sinun koiriesi kieli saisi osansa vihollisista".'),
(1683878,58,19,68,25,'Julkinähtävät ovat sinun juhlasaattosi, Jumala, minun Jumalani, kuninkaani juhlasaatot pyhäkössä.'),
(1683879,58,19,68,26,'Laulajat käyvät edellä, kanteleensoittajat jäljessä, keskellä nuoret naiset vaskirumpuja lyöden.'),
(1683880,58,19,68,27,'Kiittäkää Jumalaa seurakunnan kokouksissa, kiittäkää Herraa te, jotka olette Israelin lähteestä.'),
(1683881,58,19,68,28,'Tuolla on Benjamin, nuorin, heitä johtaen, Juudan ruhtinaat joukkoinensa, Sebulonin ruhtinaat, Naftalin ruhtinaat.'),
(1683882,58,19,68,29,'Sinun Jumalasi on säätänyt sinulle vallan. Vahvista, Jumala, minkä olet hyväksemme tehnyt.'),
(1683883,58,19,68,30,'Sinun temppelisi tähden, joka kohoaa Jerusalemissa, kuninkaat tuovat sinulle lahjoja.'),
(1683884,58,19,68,31,'Käske ankarasti ruovikon petoa, härkien laumaa ynnä vasikoita, kansoja, lankeamaan maahan hopeaharkkoinensa. Hän hajottaa kansat, jotka sotia rakastavat.'),
(1683885,58,19,68,32,'Mahtavat saapuvat Egyptistä, Etiopia kiiruhtaa ojentamaan käsiänsä Jumalan puoleen.'),
(1683886,58,19,68,33,'Te maan valtakunnat, laulakaa Jumalalle, veisatkaa Herran kiitosta, - Sela -'),
(1683887,58,19,68,34,'hänen, joka kiitää ikuisten taivasten taivaissa! Katso, hän antaa äänellänsä väkevän jylinän.'),
(1683888,58,19,68,35,'Antakaa väkevyys Jumalalle! Hänen herrautensa on Israelin yllä ja hänen voimansa pilvien tasalla.'),
(1683889,58,19,68,36,'Peljättävä on Jumala, joka ilmestyy sinun pyhäköstäsi, Israelin Jumala. Hän antaa kansallensa voiman ja väkevyyden. Kiitetty olkoon Jumala.'),
(1683890,58,19,69,1,'Veisuunjohtajalle; veisataan kuin: "Liljat"; Daavidin virsi.'),
(1683891,58,19,69,2,'Pelasta minut, Jumala, sillä vedet käyvät minun sieluuni asti.'),
(1683892,58,19,69,3,'Minä olen vajonnut syvään, pohjattomaan liejuun, olen joutunut vetten syvyyksiin, ja virta tulvii minun ylitseni.'),
(1683893,58,19,69,4,'Minä olen väsynyt huutamisesta, minun kurkkuni kuivettuu, minun silmäni ovat rauenneet odottaessani Jumalaani.'),
(1683894,58,19,69,5,'Enemmän kuin hiuksia päässäni on niitä, jotka minua syyttömästi vihaavat; paljon on niitä, jotka tahtovat tuhota minut, jotka syyttä ovat vihollisiani; mitä en ole ryöstänyt, se täytyy minun maksaa.'),
(1683895,58,19,69,6,'Jumala, sinä tunnet minun hulluuteni, eivätkä minun vikani ole sinulta salassa.'),
(1683896,58,19,69,7,'Älä anna minussa häpeään joutua niiden, jotka odottavat sinua, Herra, Herra Sebaot. Älä salli minussa pettyä niiden, jotka etsivät sinua, Israelin Jumala.'),
(1683897,58,19,69,8,'Sillä sinun tähtesi minä kärsin herjausta, pilkka peittää minun kasvoni.'),
(1683898,58,19,69,9,'Veljilleni minä olen tullut vieraaksi, olen tullut oudoksi äitini lapsille.'),
(1683899,58,19,69,10,'Sillä kiivaus sinun huoneesi puolesta on minut kuluttanut, ja niiden herjaukset, jotka sinua herjaavat, ovat sattuneet minuun.'),
(1683900,58,19,69,11,'Minä, minun sieluni itki ja paastosi, mutta siitä koitui minulle vain herjausta.'),
(1683901,58,19,69,12,'Minä pukeuduin säkkipukuun, mutta tulin sananparreksi heidän suussaan.'),
(1683902,58,19,69,13,'Porteissa-istujat minusta jaarittelevat, ja väkijuomain juojat minusta laulavat.'),
(1683903,58,19,69,14,'Mutta minä rukoilen sinua, Herra, otollisella ajalla, sinua, Jumala, sinun suuren laupeutesi turvin. Vastaa minulle pelastavan uskollisuutesi tähden.'),
(1683904,58,19,69,15,'Päästä minut loasta, etten siihen vajoa, auta, että pääsen vihollisistani ja syvistä vesistä.'),
(1683905,58,19,69,16,'Älä anna vetten vuon minua upottaa, syvyyden minua niellä ja kuilun sulkea suutaan minun ylitseni.'),
(1683906,58,19,69,17,'Vastaa minulle, Herra, sillä sinun armosi on hyvä, käänny minun puoleeni suuressa laupeudessasi.'),
(1683907,58,19,69,18,'Älä peitä kasvojasi palvelijaltasi, sillä minä olen ahdistuksessa; joudu, vastaa minulle.'),
(1683908,58,19,69,19,'Lähesty minun sieluani ja lunasta se, vapahda minut vihollisteni tähden.'),
(1683909,58,19,69,20,'Sinä tiedät minun häväistykseni, minun häpeäni ja pilkkani, sinun edessäsi ovat julki kaikki minun ahdistajani.'),
(1683910,58,19,69,21,'Häväistys on särkenyt minun sydämeni, minä olen käynyt heikoksi; minä odotin sääliä, mutta en saanut, ja lohduttajia, mutta en löytänyt.'),
(1683911,58,19,69,22,'Koiruohoa he antoivat minun syödäkseni ja juottivat minulle janooni hapanviiniä.'),
(1683912,58,19,69,23,'Tulkoon heidän pöytänsä heille paulaksi, ansaksi noille suruttomille.'),
(1683913,58,19,69,24,'Soetkoot heidän silmänsä, niin etteivät näe, ja saata heidän lanteensa alati horjumaan.'),
(1683914,58,19,69,25,'Vuodata vihastuksesi heidän päällensä, ja yllättäköön heidät sinun vihasi hehku.'),
(1683915,58,19,69,26,'Joutukoon heidän leiripaikkansa autioksi, älköön heidän majoissansa asukasta olko.'),
(1683916,58,19,69,27,'Sillä he vainoavat sitä, jota sinä olet lyönyt, he juttelevat niiden tuskista, joita sinä olet haavoittanut.'),
(1683917,58,19,69,28,'Lisää heille rikosta rikoksen päälle, ja sinun vanhurskauteesi he älkööt pääskö.'),
(1683918,58,19,69,29,'Pyyhittäköön heidät pois elämän kirjasta, älköönkä heitä kirjoitettako vanhurskasten lukuun.'),
(1683919,58,19,69,30,'Mutta minä olen kurja ja vaivattu, suojatkoon minua sinun apusi, Jumala,'),
(1683920,58,19,69,31,'niin minä veisuulla kiitän Jumalan nimeä ja ylistän häntä kiitosvirsillä.'),
(1683921,58,19,69,32,'Se on Herralle otollisempi kuin härkä, kuin mulli, sarvipää ja sorkkajalka.'),
(1683922,58,19,69,33,'Nöyrät näkevät sen ja riemuitsevat; elpyköön teidän sydämenne, teidän, jotka etsitte Jumalaa.'),
(1683923,58,19,69,34,'Sillä Herra kuulee köyhiä eikä halveksi vankejansa.'),
(1683924,58,19,69,35,'Kiittäkööt häntä taivaat ja maa, meret ja kaikki, mitä niissä liikkuu.'),
(1683925,58,19,69,36,'Sillä Jumala on pelastava Siionin ja rakentava Juudan kaupungit, niin että he asettuvat niihin ja omistavat ne.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683926,58,19,69,37,'Hänen palvelijainsa jälkeläiset saavat sen perinnökseen, ja ne, jotka hänen nimeänsä rakastavat, saavat asua siinä.'),
(1683927,58,19,70,1,'Veisuunjohtajalle; Daavidin virsi; syntiä tunnustettaessa.'),
(1683928,58,19,70,2,'Jumala, riennä minua pelastamaan, riennä minun avukseni, Herra.'),
(1683929,58,19,70,3,'Joutukoot häpeään ja punastukoot ne, jotka minun henkeäni väijyvät; peräytykööt ja saakoot häpeän ne, jotka tahtovat minulle onnettomuutta.'),
(1683930,58,19,70,4,'Kääntykööt takaisin häpeissänsä ne, jotka sanovat: "Kas niin, kas niin!"'),
(1683931,58,19,70,5,'Iloitkoot ja riemuitkoot sinussa kaikki, jotka sinua etsivät; joille sinun apusi on rakas, ne sanokoot aina: "Ylistetty olkoon Jumala!"'),
(1683932,58,19,70,6,'Mutta minä olen kurja ja köyhä; Jumala, riennä minun tyköni. Sinä olet minun apuni ja vapauttajani; Herra, älä viivy.'),
(1683933,58,19,71,1,'Sinuun, Herra, minä turvaan, älä salli minun joutua häpeään iankaikkisesti.'),
(1683934,58,19,71,2,'Pelasta minut, vapahda minut vanhurskaudessasi, kallista korvasi minun puoleeni ja auta minua.'),
(1683935,58,19,71,3,'Ole minulle kallio, jolla saan asua ja jonne aina saan mennä, sinä, joka olet säätänyt minulle pelastuksen. Sillä sinä olet minun kallioni ja linnani.'),
(1683936,58,19,71,4,'Jumalani, vapauta minut jumalattoman kädestä, väärän ja väkivaltaisen kourista.'),
(1683937,58,19,71,5,'Sillä sinä olet minun toivoni, Herra, Herra, minun turvani hamasta nuoruudestani.'),
(1683938,58,19,71,6,'Sinä olet minun tukeni syntymästäni saakka, sinä päästit minut äitini kohdusta; sinua minä alati ylistän.'),
(1683939,58,19,71,7,'Monelle minä olen kuin kummitus, mutta sinä olet minun vahva suojani.'),
(1683940,58,19,71,8,'Minun suuni on täynnä sinun kiitostasi, täynnä sinun ylistystäsi kaiken päivää.'),
(1683941,58,19,71,9,'Älä heitä minua pois minun vanhalla iälläni, älä hylkää minua, kun voimani loppuu.'),
(1683942,58,19,71,10,'Sillä minun viholliseni puhuvat minusta; ne, jotka väijyvät minun henkeäni, neuvottelevat keskenänsä:'),
(1683943,58,19,71,11,'"Jumala on hänet hyljännyt; ajakaa häntä takaa ja ottakaa kiinni, sillä auttajaa ei ole".'),
(1683944,58,19,71,12,'Jumala, älä ole minusta kaukana, Jumalani, riennä minun avukseni.'),
(1683945,58,19,71,13,'Joutukoot häpeään ja hukkukoot ne, jotka vainoavat minun sieluani; peittäköön häpeä ja pilkka ne, jotka hankkivat minulle onnettomuutta.'),
(1683946,58,19,71,14,'Mutta minä odotan alati, ja yhäti minä sinua kiitän.'),
(1683947,58,19,71,15,'Minun suuni on julistava sinun vanhurskauttasi, sinun pelastustekojasi kaiken päivää, sillä niiden määrää en minä tunne.'),
(1683948,58,19,71,16,'Herran, Herran väkeviä tekoja minä tuon julki, minä ylistän sinun vanhurskauttasi, sinun ainoan.'),
(1683949,58,19,71,17,'Jumala, sinä olet opettanut minua hamasta nuoruudestani, ja yhä vielä minä sinun ihmeitäsi julistan.'),
(1683950,58,19,71,18,'Älä, Jumala, minua hylkää vanhaksi ja harmaaksi tultuani, niin minä julistan sinun käsivartesi voimaa nousevalle polvelle, sinun väkevyyttäsi kaikille vielä tuleville.'),
(1683951,58,19,71,19,'Jumala, sinun vanhurskautesi ulottuu hamaan korkeuksiin, sinun, joka teet niin suuria. Jumala, kuka on sinun vertaisesi?'),
(1683952,58,19,71,20,'Sinä, joka olet antanut meidän kokea paljon ahdistusta ja onnettomuutta, sinä virvoitat meidät jälleen henkiin, ja maan syvyyksistä sinä tuot meidät takaisin.'),
(1683953,58,19,71,21,'Anna minun arvoni kasvaa ja lohduta minua jälleen.'),
(1683954,58,19,71,22,'Niin minä myös ylistän harpulla sinua, sinun uskollisuuttasi, minun Jumalani, soitan kanteleella kiitosta sinulle, sinä Israelin Pyhä.'),
(1683955,58,19,71,23,'Minun huuleni riemuitsevat, kun minä sinulle soitan, ja myös minun sieluni, jonka sinä olet lunastanut.'),
(1683956,58,19,71,24,'Minun kieleni julistaa sinun vanhurskauttasi kaiken päivää, sillä häpeään ja pilkkaan ovat joutuneet ne, jotka hankkivat minulle onnettomuutta.'),
(1683957,58,19,72,1,'Salomon virsi. Jumala, anna kuninkaan tuomita, niinkuin sinä tuomitset, anna vanhurskautesi kuninkaan pojalle.'),
(1683958,58,19,72,2,'Tuomitkoon hän sinun kansaasi vanhurskaasti ja sinun kurjiasi oikeuden mukaan.'),
(1683959,58,19,72,3,'Vuoret kantakoot rauhaa kansalle, niin myös kukkulat, vanhurskauden voimasta.'),
(1683960,58,19,72,4,'Auttakoon hän kansan kurjat oikeuteen, pelastakoon köyhäin lapset ja musertakoon sortajan.'),
(1683961,58,19,72,5,'Niin he pelkäävät sinua, niin kauan kuin aurinko paistaa ja kuu kumottaa, polvesta polveen.'),
(1683962,58,19,72,6,'Hän olkoon niinkuin sade, joka nurmikolle vuotaa, niinkuin sadekuuro, joka kostuttaa maan.'),
(1683963,58,19,72,7,'Hänen päivinänsä vanhurskas kukoistaa, ja rauha on oleva runsas siihen saakka, kunnes kuuta ei enää ole.'),
(1683964,58,19,72,8,'Hallitkoon hän merestä mereen ja Eufrat-virrasta maan ääriin saakka.'),
(1683965,58,19,72,9,'Hänen edessänsä erämaan asujat polvistuvat, ja hänen vihollisensa nuolevat tomua.'),
(1683966,58,19,72,10,'Tarsiin ja saarten kuninkaat tuovat lahjoja, Saban ja Seban kuninkaat veroa maksavat.'),
(1683967,58,19,72,11,'Häntä kumartavat kaikki kuninkaat, kaikki kansakunnat palvelevat häntä.'),
(1683968,58,19,72,12,'Sillä hän pelastaa köyhän, joka apua huutaa, kurjan ja sen, jolla ei auttajaa ole.'),
(1683969,58,19,72,13,'Hän armahtaa vaivaista ja köyhää ja pelastaa köyhäin sielun.'),
(1683970,58,19,72,14,'Hän lunastaa heidän sielunsa sorrosta ja väkivallasta, ja heidän verensä on hänen silmissään kallis.'),
(1683971,58,19,72,15,'Hän eläköön, ja hänelle tuotakoon Saban kultaa; hänen puolestansa rukoiltakoon alati, ja siunattakoon häntä lakkaamatta.'),
(1683972,58,19,72,16,'Maa kasvakoon runsaasti viljaa, vuorten huippuja myöten, sen hedelmä huojukoon niinkuin Libanon; ja kansaa nouskoon kaupungeista niinkuin kasveja maasta.'),
(1683973,58,19,72,17,'Pysyköön hänen nimensä iankaikkisesti, ja versokoon hänen nimensä, niin kauan kuin aurinko paistaa. Hänessä he itseänsä siunatkoot, ja kaikki kansakunnat ylistäkööt häntä onnelliseksi.'),
(1683974,58,19,72,18,'Kiitetty olkoon Herra Jumala, Israelin Jumala, ainoa, joka ihmeitä tekee.'),
(1683975,58,19,72,19,'Kiitetty olkoon hänen kunniansa nimi iankaikkisesti, ja kaikki maa olkoon täynnä hänen kunniaansa. Amen, amen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1683976,58,19,72,20,'Daavidin, Iisain pojan, rukoukset päättyvät.'),
(1683977,58,19,73,1,'Aasafin virsi. Totisesti, Jumala on hyvä Israelille, niille, joilla on puhdas sydän.'),
(1683978,58,19,73,2,'Mutta minun jalkani olivat vähällä kompastua, askeleeni olivat aivan liukahtaa.'),
(1683979,58,19,73,3,'Sillä minussa nousi kateus ylvästelijöitä kohtaan, kun minä näin jumalattomien menestyvän.'),
(1683980,58,19,73,4,'Sillä he ovat vaivoista vapaat kuolemaansa asti, he ovat voimakkaat ja lihavat.'),
(1683981,58,19,73,5,'Eivät he koe muitten kuolevaisten tuskia, eikä heitä vaivata niinkuin muita ihmisiä.'),
(1683982,58,19,73,6,'Sentähden on ylpeys heillä kaulakoristeena, väkivalta on puku, joka heidät verhoaa.'),
(1683983,58,19,73,7,'Heidän silmänsä pullistuvat ulos heidän lihavuudestaan, heidän sydämensä kuvittelut kulkevat valtoimina.'),
(1683984,58,19,73,8,'He pilkkaavat ja puhuvat väkivallan puheita pahuudessansa, he puhuvat kuin korkeuksista.'),
(1683985,58,19,73,9,'Heidän suunsa tavoittelee taivasta, ja heidän kielensä kulkee pitkin maata.'),
(1683986,58,19,73,10,'Sentähden heidän kansansa liittyy heihin ja särpii vettä kyllälti.'),
(1683987,58,19,73,11,'Ja he sanovat: "Kuinka Jumala sen tietäisi, onko tietoa Korkeimmalla?"'),
(1683988,58,19,73,12,'Katso, nämä ovat jumalattomat; kuitenkin he elävät ainaisessa rauhassa ja rikastuvat yhäti.'),
(1683989,58,19,73,13,'Turhaan minä olen pitänyt sydämeni puhtaana ja pessyt käteni viattomuudessa:'),
(1683990,58,19,73,14,'minua vaivataan joka aika, ja minä saan joka aamu kuritusta.'),
(1683991,58,19,73,15,'Jos olisin sanonut: "Noin minäkin puhun", katso, niin minä olisin ollut petollinen koko sinun lastesi sukua kohtaan.'),
(1683992,58,19,73,16,'Minä mietin päästäkseni tästä selvyyteen; mutta se oli minulle ylen vaikeata,'),
(1683993,58,19,73,17,'kunnes minä pääsin sisälle Jumalan pyhiin salaisuuksiin ja käsitin, mikä heidän loppunsa on oleva.'),
(1683994,58,19,73,18,'Totisesti, sinä panet heidät liukkaalle, perikatoon sinä heidät syökset.'),
(1683995,58,19,73,19,'Kuinka he joutuvatkaan äkisti turmioon! He hukkuvat, heidän loppunsa on kauhistava.'),
(1683996,58,19,73,20,'Niinkuin unen käy herätessä, niin sinä, Herra, kun heräjät, heidän valhekuvansa hylkäät.'),
(1683997,58,19,73,21,'Kun minun sydämeni katkeroitui ja minun munaskuihini pisti,'),
(1683998,58,19,73,22,'silloin minä olin järjetön enkä mitään älynnyt, olin sinun edessäsi kuin nauta.'),
(1683999,58,19,73,23,'Kuitenkin minä pysyn alati sinun tykönäsi, sinä pidät minua kiinni oikeasta kädestäni.'),
(1684000,58,19,73,24,'Sinä talutat minua neuvosi mukaan ja korjaat minut viimein kunniaan.'),
(1684001,58,19,73,25,'Ketä muuta minulla olisi taivaassa! Ja kun sinä olet minun kanssani, en minä mistään maan päällä huoli.'),
(1684002,58,19,73,26,'Vaikka minun ruumiini ja sieluni nääntyisi, Jumala on minun sydämeni kallio ja minun osani iankaikkisesti.'),
(1684003,58,19,73,27,'Sillä katso, jotka sinusta eriävät, ne hukkuvat, sinä tuhoat kaikki, jotka haureudessa sinusta luopuvat.'),
(1684004,58,19,73,28,'Mutta minun onneni on olla Jumalaa lähellä, minä panen turvani Herraan, Herraan, kertoakseni kaikkia sinun tekojasi.'),
(1684005,58,19,74,1,'Aasafin mietevirsi. Miksi sinä, Jumala, hylkäsit meidät ainiaaksi, miksi suitsuaa sinun vihasi laitumesi lampaita vastaan?'),
(1684006,58,19,74,2,'Muista seurakuntaasi, jonka muinoin omaksesi otit, jonka lunastit perintösuvuksesi. Muista Siionin vuorta, jolla sinä asut.'),
(1684007,58,19,74,3,'Ohjaa askeleesi ikuisille raunioille. Vihollinen on raiskannut kaiken pyhäkössä.'),
(1684008,58,19,74,4,'Sinun vihollisesi huusivat kokoushuoneessasi, he pystyttivät omat merkkinsä merkeiksi sinne.'),
(1684009,58,19,74,5,'Näytti, kuin olisi tiheässä metsässä kirveitä heilutettu korkealle.'),
(1684010,58,19,74,6,'Niin he löivät kaikki sen veistokset kirveillä ja nuijilla rikki.'),
(1684011,58,19,74,7,'He pistivät sinun pyhäkkösi tuleen, he häväisivät, panivat maan tasalle sinun nimesi asumuksen.'),
(1684012,58,19,74,8,'He sanoivat sydämessään: "Me hävitämme heidät kaikki tyynni". He polttivat kaikki jumalanpalvelushuoneet maasta.'),
(1684013,58,19,74,9,'Merkkejämme me emme näe, ei ole enää profeettaa, eikä ole joukossamme ketään, joka tietäisi, kuinka kauan -.'),
(1684014,58,19,74,10,'Kuinka kauan, Jumala, vihollinen saa herjata, vihamies pilkata sinun nimeäsi lakkaamatta?'),
(1684015,58,19,74,11,'Miksi pidätät kättäsi, oikeata kättäsi? Vedä se povestasi ja hävitä heidät.'),
(1684016,58,19,74,12,'Jumala on minun kuninkaani ammoisista ajoista, hän toimittaa pelastuksen maan päällä.'),
(1684017,58,19,74,13,'Sinä voimallasi halkaisit meren, sinä musersit lohikäärmeitten päät vetten päällä.'),
(1684018,58,19,74,14,'Sinä ruhjoit rikki Leviatanin päät, sinä annoit hänet ruuaksi erämaan eläinten laumalle.'),
(1684019,58,19,74,15,'Sinä puhkaisit kuohumaan lähteen ja puron, sinä kuivasit väkevät virrat.'),
(1684020,58,19,74,16,'Sinun on päivä, sinun on yö, sinä valmistit valon ja auringon.'),
(1684021,58,19,74,17,'Sinä määräsit kaikki maan rajat, sinä asetit kesän ja talven.'),
(1684022,58,19,74,18,'Niin muista tämä: vihollinen herjaa Herraa, houkkiokansa pilkkaa sinun nimeäsi.'),
(1684023,58,19,74,19,'Älä anna pedolle alttiiksi metsäkyyhkysesi sielua, älä iäksi unhota kurjiesi elämää.'),
(1684024,58,19,74,20,'Katso liittoasi. Sillä maan pimennot ovat väkivallan pesiä täynnä.'),
(1684025,58,19,74,21,'Älä salli sorretun kääntyä häväistynä takaisin. Kurja ja köyhä saakoot ylistää sinun nimeäsi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684026,58,19,74,22,'Nouse, Jumala, aja asiasi. Muista, miten houkat herjaavat sinua kaiken aikaa.'),
(1684027,58,19,74,23,'Älä unhota vihollistesi huutoa, älä vastustajaisi melua, joka kohoaa lakkaamatta.'),
(1684028,58,19,75,1,'Veisuunjohtajalle; veisataan kuin: "Älä turmele"; virsi; Aasafin laulu.'),
(1684029,58,19,75,2,'Me kiitämme sinua, Jumala, me kiitämme sinua; lähellä on sinun nimesi, sinun ihmeitäsi kerrotaan.'),
(1684030,58,19,75,3,'"Vaikka minä valitsenkin ajan, minä tuomitsen oikein.'),
(1684031,58,19,75,4,'Vaikka maa kaikkine asukkaineen menehtyy pelkoon, pidän minä pystyssä sen patsaat." Sela.'),
(1684032,58,19,75,5,'"Ylvästelijöille minä sanon: älkää ylvästelkö, ja jumalattomille: älkää sarvea nostako.'),
(1684033,58,19,75,6,'Älkää nostako sarveanne korkealle, älkää puhuko niskoitellen, julkeasti."'),
(1684034,58,19,75,7,'Ei tule apua idästä, ei lännestä, ei vuorisesta erämaasta,'),
(1684035,58,19,75,8,'vaan Jumala on se, joka tuomitsee: yhden hän alentaa, toisen ylentää.'),
(1684036,58,19,75,9,'Sillä Herran kädessä on malja, joka vaahtoaa täynnänsä höystettyä viiniä, ja siitä hän kaataa; kaikkien maan jumalattomien täytyy se juoda, särpiä pohjasakkaa myöten.'),
(1684037,58,19,75,10,'Mutta minä julistan iäti, veisaan kiitosta Jaakobin Jumalalle.'),
(1684038,58,19,75,11,'Ja kaikki jumalattomien sarvet minä katkaisen; korkealle kohoavat vanhurskaan sarvet.'),
(1684039,58,19,76,1,'Veisuunjohtajalle; kielisoittimilla; virsi; Aasafin laulu.'),
(1684040,58,19,76,2,'Jumala on tunnettu Juudassa, hänen nimensä on suuri Israelissa;'),
(1684041,58,19,76,3,'Saalemissa on hänen majansa ja hänen asumuksensa Siionissa.'),
(1684042,58,19,76,4,'Siellä hän mursi jousen salamat, kilven ja miekan ja sodan. Sela.'),
(1684043,58,19,76,5,'Kirkkaudessa, valtasuuruudessa sinä tulit voittosaaliin vuorilta.'),
(1684044,58,19,76,6,'Urhoollisilta ryöstettiin aseet, he uupuivat uneen; kaikkien sankarien kädet herposivat.'),
(1684045,58,19,76,7,'Sinun nuhtelustasi, Jaakobin Jumala, vaipuivat raskaaseen uneen vaunut ja hevoset.'),
(1684046,58,19,76,8,'Sinä olet peljättävä, kuka kestää sinun edessäsi, kun sinä vihastut?'),
(1684047,58,19,76,9,'Taivaasta sinä annoit tuomiosi kuulua; maa peljästyi ja vaikeni,'),
(1684048,58,19,76,10,'kun Jumala nousi tuomiolle vapahtaakseen kaikki maan nöyrät. Sela.'),
(1684049,58,19,76,11,'Sillä ihmisten viha tulee sinulle ylistykseksi: sinä vyöttäydyt vihan ylenpalttisuuteen.'),
(1684050,58,19,76,12,'Tehkää lupauksia ja täyttäkää ne Herralle, Jumalallenne. Kaikki hänen ympärillään asuvaiset tuokoot lahjoja Peljättävälle,'),
(1684051,58,19,76,13,'joka nöyryyttää ruhtinaitten rohkeuden ja joka on peljättävä maan kuninkaille.'),
(1684052,58,19,77,1,'Veisuunjohtajalle; Jedutunin tapaan; Aasafin virsi.'),
(1684053,58,19,77,2,'Minä korotan ääneni Jumalan puoleen ja huudan; minä korotan ääneni Jumalan puoleen, että hän minua kuulisi.'),
(1684054,58,19,77,3,'Ahdistukseni aikana minä etsin Herraa; minun käteni on yöllä ojennettuna eikä väsy; minun sieluni ei lohdutuksesta huoli.'),
(1684055,58,19,77,4,'Minä muistan Jumalaa ja huokaan; minä tutkistelen, ja minun henkeni nääntyy. Sela.'),
(1684056,58,19,77,5,'Sinä pidät minun silmäni valveilla; minä olen niin levoton, etten voi puhua.'),
(1684057,58,19,77,6,'Minä ajattelen muinaisia päiviä, ammoin menneitä vuosia.'),
(1684058,58,19,77,7,'Minä muistan yöllä kanteleeni, minä mietiskelen sydämessäni, ja minun henkeni tutkii:'),
(1684059,58,19,77,8,'Hylkääkö Herra ikiajoiksi eikä enää osoita mielisuosiota?'),
(1684060,58,19,77,9,'Onko hänen armonsa mennyt ainiaaksi, onko hänen lupauksensa lopussa polvesta polveen?'),
(1684061,58,19,77,10,'Onko Jumala unhottanut olla armollinen, onko hän vihassaan lukinnut laupeutensa? Sela.'),
(1684062,58,19,77,11,'Minä sanoin: tämä on minun kärsimykseni, että Korkeimman oikea käsi on muuttunut.'),
(1684063,58,19,77,12,'Minä muistelen Herran tekoja, minä muistelen sinun entisiä ihmetöitäsi.'),
(1684064,58,19,77,13,'Minä tutkistelen kaikkia sinun töitäsi, minä mietin sinun suuria tekojasi.'),
(1684065,58,19,77,14,'Jumala, sinun tiesi on pyhä; kuka on jumala, suuri niinkuin sinä, Jumala?'),
(1684066,58,19,77,15,'Sinä olet Jumala, joka teet ihmeitä, sinä olet ilmoittanut voimasi kansojen seassa.'),
(1684067,58,19,77,16,'Käsivarrellasi sinä lunastit kansasi, Jaakobin ja Joosefin lapset. Sela.'),
(1684068,58,19,77,17,'Vedet näkivät sinut, Jumala, vedet näkivät sinut ja vapisivat, ja syvyydet värisivät.'),
(1684069,58,19,77,18,'Pilvet purkivat vettä, pilvet antoivat jylinänsä, sinun nuolesi lensivät.'),
(1684070,58,19,77,19,'Sinun pauhinasi ääni vyöryi, salamat valaisivat maan piirin, maa vapisi ja järkkyi.'),
(1684071,58,19,77,20,'Meren halki kävi sinun tiesi, sinun polkusi läpi suurten vetten, eivätkä sinun jälkesi tuntuneet.'),
(1684072,58,19,77,21,'Sinä kuljetit kansasi niinkuin lammaslauman Mooseksen ja Aaronin kädellä.'),
(1684073,58,19,78,1,'Aasafin mietevirsi. Kuuntele, kansani, minun opetustani, kallistakaa korvanne minun suuni sanoille.'),
(1684074,58,19,78,2,'Minä avaan suuni mietelmiin, tuon ilmi muinaisaikojen arvoituksia.'),
(1684075,58,19,78,3,'Mitä olemme kuulleet, minkä olemme saaneet tietää ja mitä isämme ovat meille kertoneet,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684076,58,19,78,4,'sitä me emme heidän lapsiltansa salaa, vaan me kerromme tulevalle polvelle Herran ylistettävistä teoista, hänen voimastansa ja ihmeistänsä, jotka hän on tehnyt.'),
(1684077,58,19,78,5,'Hän asetti todistuksen Jaakobiin, hän sääti Israeliin lain ja käski meidän isiemme julistaa ne lapsillensa,'),
(1684078,58,19,78,6,'että jälkipolvi saisi ne tietää, saisivat tietää vastedes syntyvät lapset, ja nekin nousisivat ja kertoisivat niistä lapsillensa.'),
(1684079,58,19,78,7,'Niin nämä panisivat uskalluksensa Jumalaan eivätkä unhottaisi Jumalan tekoja, vaan ottaisivat hänen käskyistänsä vaarin.'),
(1684080,58,19,78,8,'Ja niin ei heistä tulisi, niinkuin heidän isistänsä, kapinoitseva ja niskoitteleva polvi, sukupolvi, jonka sydän ei pysynyt lujana ja jonka henki ei pysynyt uskollisena Jumalalle.'),
(1684081,58,19,78,9,'Efraimin lapset, asestetut jousimiehet, kääntyivät pakoon taistelun päivänä.'),
(1684082,58,19,78,10,'Eivät he pitäneet Jumalan liittoa, eivät tahtoneet vaeltaa hänen lakinsa mukaan,'),
(1684083,58,19,78,11,'vaan he unhottivat hänen suuret tekonsa ja hänen ihmeensä, jotka hän heille näytti.'),
(1684084,58,19,78,12,'Heidän isiensä nähden hän ihmeitä teki Egyptin maassa, Sooanin kedolla.'),
(1684085,58,19,78,13,'Hän halkaisi meren ja vei heidät sen läpi, hän seisotti vedet roukkioksi.'),
(1684086,58,19,78,14,'Hän johdatti heitä päivän aikaan pilvellä ja tulen valolla kaiket yöt.'),
(1684087,58,19,78,15,'Hän halkoi kalliot erämaassa ja juotti heitä runsaasti, kuin syvistä vesistä.'),
(1684088,58,19,78,16,'Hän juoksutti puroja kalliosta ja vuodatti virtanaan vettä.'),
(1684089,58,19,78,17,'Yhä he kuitenkin tekivät syntiä häntä vastaan ja olivat uppiniskaisia Korkeimmalle erämaassa.'),
(1684090,58,19,78,18,'He kiusasivat Jumalaa sydämessänsä, vaatien ruokaa himonsa tyydyttämiseksi.'),
(1684091,58,19,78,19,'Ja he puhuivat Jumalaa vastaan sanoen: "Voikohan Jumala kattaa pöydän erämaassa?'),
(1684092,58,19,78,20,'Katso, hän kyllä kallioon iski, ja vedet vuotivat ja purot tulvivat; mutta voiko hän antaa myös leipää tai hankkia kansallensa lihaa?"'),
(1684093,58,19,78,21,'Sentähden Herra, kun hän sen kuuli, julmistui; ja tuli syttyi Jaakobissa, ja Israelia vastaan nousi viha,'),
(1684094,58,19,78,22,'koska he eivät uskoneet Jumalaan eivätkä luottaneet hänen apuunsa.'),
(1684095,58,19,78,23,'Hän käski pilviä korkeudessa ja avasi taivaan ovet;'),
(1684096,58,19,78,24,'hän satoi heille ruuaksi mannaa, hän antoi heille taivaan viljaa.'),
(1684097,58,19,78,25,'Ihmiset söivät enkelien leipää; hän lähetti heille evästä yllin kyllin.'),
(1684098,58,19,78,26,'Hän nosti taivaalle itätuulen ja ajoi voimallaan esiin etelätuulen;'),
(1684099,58,19,78,27,'hän antoi sataa heille lihaa kuin tomua, siivekkäitä lintuja kuin meren hiekkaa;'),
(1684100,58,19,78,28,'hän pudotti ne leirinsä keskeen, yltympäri asuntonsa.'),
(1684101,58,19,78,29,'Niin he söivät ja tulivat kylläisiksi; mitä he olivat himoinneet, sitä hän salli heidän saada.'),
(1684102,58,19,78,30,'Eivät olleet he vielä himoansa tyydyttäneet, ja ruoka oli vielä heidän suussaan,'),
(1684103,58,19,78,31,'kun heitä vastaan jo nousi Jumalan viha: hän tappoi heidän voimakkaimpansa ja kaatoi maahan Israelin nuoret miehet.'),
(1684104,58,19,78,32,'Mutta sittenkin he yhä vielä tekivät syntiä eivätkä uskoneet hänen ihmeitänsä.'),
(1684105,58,19,78,33,'Sentähden hän lopetti heidän päivänsä niinkuin tuulahduksen, antoi heidän vuottensa päättyä äkilliseen perikatoon.'),
(1684106,58,19,78,34,'Kun hän surmasi heitä, kysyivät he häntä, kääntyivät ja etsivät Jumalaa.'),
(1684107,58,19,78,35,'He muistivat, että Jumala oli heidän kallionsa, ja että Jumala, Korkein, oli heidän lunastajansa.'),
(1684108,58,19,78,36,'Mutta he pettivät häntä suullaan ja valhettelivat hänelle kielellänsä;'),
(1684109,58,19,78,37,'sillä heidän sydämensä ei ollut vakaa häntä kohtaan, eivätkä he olleet uskolliset hänen liitossansa.'),
(1684110,58,19,78,38,'Mutta hän on laupias, antaa anteeksi rikkomukset eikä tahdo hukuttaa. Sentähden hän usein kääntyi vihastansa eikä antanut kaiken kiivautensa nousta.'),
(1684111,58,19,78,39,'Sillä hän muisti, että he ovat liha, tuulahdus, joka menee eikä enää palaja.'),
(1684112,58,19,78,40,'Kuinka usein he niskoittelivat häntä vastaan korvessa ja murehduttivat hänen mielensä erämaassa!'),
(1684113,58,19,78,41,'Ja yhä edelleen he kiusasivat Jumalaa ja vihoittivat Israelin Pyhän.'),
(1684114,58,19,78,42,'He eivät muistaneet hänen kättänsä, eivät sitä päivää, jona hän päästi heidät ahdistajasta,'),
(1684115,58,19,78,43,'jona hän teki tunnustekonsa Egyptissä ja ihmeensä Sooanin kedolla,'),
(1684116,58,19,78,44,'muutti heidän virtansa vereksi, niin etteivät he voineet vesiojistaan juoda;'),
(1684117,58,19,78,45,'lähetti heidän sekaansa paarmoja, jotka heitä söivät, ja sammakoita, jotka tuottivat heille häviötä;'),
(1684118,58,19,78,46,'antoi heidän satonsa tuhosirkoille ja heinäsirkoille heidän vaivannäkönsä;'),
(1684119,58,19,78,47,'hävitti rakeilla heidän viiniköynnöksensä ja raekivillä heidän metsäviikunapuunsa;'),
(1684120,58,19,78,48,'antoi heidän karjansa alttiiksi rakeille ja heidän laumansa salamoille.'),
(1684121,58,19,78,49,'Hän lähetti heitä vastaan vihansa hehkun, kiivastuksen, vihastuksen ja ahdistuksen, parven pahoja enkeleitä.'),
(1684122,58,19,78,50,'Hän raivasi tien vihallensa, ei säästänyt heidän sielujansa kuolemasta, vaan antoi heidän henkensä ruton valtaan.'),
(1684123,58,19,78,51,'Hän surmasi kaikki esikoiset Egyptistä, miehuuden ensimmäiset Haamin majoista.'),
(1684124,58,19,78,52,'Mutta kansansa hän pani liikkeelle kuin lampaat ja johdatti heitä erämaassa kuin laumaa.'),
(1684125,58,19,78,53,'Hän johti heitä turvallisesti, heidän ei tarvinnut peljätä; mutta heidän vihollisensa peitti meri.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684126,58,19,78,54,'Ja hän vei heidät pyhälle alueellensa, vuorelle, jonka hänen oikea kätensä oli hankkinut.'),
(1684127,58,19,78,55,'Hän karkoitti pakanat pois heidän tieltänsä, jakoi ne heille arvalla perintöosaksi ja antoi Israelin sukukuntain asua niiden majoissa.'),
(1684128,58,19,78,56,'Mutta niskoittelullaan he kiusasivat Jumalaa, Korkeinta, eivätkä ottaneet hänen todistuksistansa vaaria,'),
(1684129,58,19,78,57,'vaan luopuivat pois ja olivat uskottomia isiensä lailla, kävivät kelvottomiksi kuin veltto jousi.'),
(1684130,58,19,78,58,'He vihoittivat hänet uhrikukkuloillansa ja herättivät hänen kiivautensa epäjumaliensa kuvilla.'),
(1684131,58,19,78,59,'Jumala kuuli sen ja julmistui, ja hän hylkäsi Israelin peräti.'),
(1684132,58,19,78,60,'Hän hylkäsi asumuksensa Siilossa, majan, jonka hän oli pystyttänyt ihmisten keskelle.'),
(1684133,58,19,78,61,'Hän salli väkevyytensä joutua vankeuteen ja kunniansa vihollisten käsiin.'),
(1684134,58,19,78,62,'Hän antoi kansansa alttiiksi miekalle ja julmistui perintöosaansa.'),
(1684135,58,19,78,63,'Heidän nuorukaisensa kulutti tuli, ja heidän neitsyensä jäivät häälauluja vaille.'),
(1684136,58,19,78,64,'Heidän pappinsa kaatuivat miekkaan, eivätkä heidän leskensä voineet itkuja itkeä.'),
(1684137,58,19,78,65,'Silloin Herra heräsi niinkuin nukkuja, niinkuin viinin voittama sankari.'),
(1684138,58,19,78,66,'Hän löi vihollisensa pakoon, tuotti heille ikuisen häpeän.'),
(1684139,58,19,78,67,'Hän hylkäsi myös Joosefin majan eikä valinnut Efraimin sukukuntaa,'),
(1684140,58,19,78,68,'vaan valitsi Juudan sukukunnan, Siionin vuoren, jota hän rakastaa.'),
(1684141,58,19,78,69,'Ja hän rakensi pyhäkkönsä korkeuksien tasalle, rakensi sen kuin maan, jonka hän on perustanut ikiajoiksi.'),
(1684142,58,19,78,70,'Hän valitsi Daavidin, palvelijansa, ja otti hänet lammastarhoista.'),
(1684143,58,19,78,71,'Hän toi hänet imettäväisten lammasten jäljestä kaitsemaan kansaansa, Jaakobia, ja Israelia, perintöosaansa.'),
(1684144,58,19,78,72,'Ja Daavid kaitsi heitä vilpittömin sydämin ja johti heitä taitavalla kädellä.'),
(1684145,58,19,79,1,'Aasafin virsi. Jumala, pakanat ovat tunkeutuneet sinun perintöosaasi, he ovat saastuttaneet sinun pyhän temppelisi, ovat tehneet Jerusalemista kiviraunion.'),
(1684146,58,19,79,2,'He antoivat sinun palvelijaisi ruumiit taivaan linnuille ruuaksi, maan pedoille sinun hurskaittesi lihan.'),
(1684147,58,19,79,3,'He vuodattivat heidän vertansa kuin vettä ympäri Jerusalemia, eikä heitä kukaan haudannut.'),
(1684148,58,19,79,4,'Me olemme joutuneet naapuriemme häväistäviksi, niiden pilkattaviksi ja ivattaviksi, jotka ympärillämme asuvat.'),
(1684149,58,19,79,5,'Kuinka kauan sinä, Herra, olet yhäti vihoissasi, kuinka kauan sinun kiivautesi tulena palaa?'),
(1684150,58,19,79,6,'Vuodata vihasi pakanain ylitse, jotka eivät sinua tunne, ja valtakuntien ylitse, jotka eivät sinun nimeäsi avukseen huuda.'),
(1684151,58,19,79,7,'Sillä he ovat syöneet Jaakobin ja tehneet hänen asuinsijansa autioksi.'),
(1684152,58,19,79,8,'Älä lue meidän syyksemme isiemme rikoksia, anna armosi pian kohdata meitä, sillä me olemme sangen viheliäisiksi tulleet.'),
(1684153,58,19,79,9,'Auta meitä sinä, pelastuksemme Jumala, nimesi kunnian tähden, pelasta meidät ja anna meidän syntimme anteeksi nimesi tähden.'),
(1684154,58,19,79,10,'Miksi pakanat saisivat sanoa: "Missä on heidän Jumalansa?" Tulkoon tunnetuksi pakanain seassa, meidän silmäimme nähden, sinun palvelijaisi vuodatetun veren kosto.'),
(1684155,58,19,79,11,'Tulkoon vankien huokaus sinun kasvojesi eteen; suuren käsivartesi voimalla pidä elossa kuoleman lapset.'),
(1684156,58,19,79,12,'Ja maksa naapureillemme, heidän helmaansa, seitsenkertaisesti se herjaus, jolla he ovat herjanneet sinua, Herra.'),
(1684157,58,19,79,13,'Mutta me, sinun kansasi, sinun laitumesi lampaat, kiitämme sinua iankaikkisesti, julistamme sinun kiitostasi polvesta polveen.'),
(1684158,58,19,80,1,'Veisuunjohtajalle; veisataan kuin: "Liljat"; Aasafin todistus; virsi.'),
(1684159,58,19,80,2,'Kuuntele, Israelin paimen. Sinä, joka johdat Joosefia niinkuin lammaslaumaa, sinä, jonka valtaistuinta kerubit kannattavat, ilmesty kirkkaudessasi.'),
(1684160,58,19,80,3,'Efraimin, Benjaminin ja Manassen edessä herätä voimasi, tule meidän avuksemme.'),
(1684161,58,19,80,4,'Jumala, saata meidät entisellemme, valista kasvosi, niin me autetuiksi tulemme.'),
(1684162,58,19,80,5,'Herra, Jumala Sebaot, kuinka kauan sinä annat vihasi suitsuta, kun sinun kansasi rukoilee?'),
(1684163,58,19,80,6,'Sinä olet syöttänyt heille kyynelten leipää, olet juottanut heille maljoittain kyyneleitä;'),
(1684164,58,19,80,7,'olet pannut meidät riidaksi naapureillemme, meidän vihollisemme pilkkaavat meitä.'),
(1684165,58,19,80,8,'Jumala Sebaot, saata meidät entisellemme, valista kasvosi, niin me autetuiksi tulemme.'),
(1684166,58,19,80,9,'Sinä siirsit viinipuun Egyptistä, sinä karkoitit pakanat ja istutit sen.'),
(1684167,58,19,80,10,'Sinä raivasit sille sijan, ja se juurtui ja täytti maan.'),
(1684168,58,19,80,11,'Se peitti vuoret varjollansa ja oksillansa Jumalan setrit.'),
(1684169,58,19,80,12,'Se levitti köynnöksensä mereen asti ja vesansa Eufrat-virtaan saakka.'),
(1684170,58,19,80,13,'Miksi sinä särjit aidan sen ympäriltä, niin että kaikki tienkulkijat sitä repivät?'),
(1684171,58,19,80,14,'Metsäkarju sitä jyrsii, ja kedon eläimet sitä syövät.'),
(1684172,58,19,80,15,'Jumala Sebaot, käänny takaisin, katso alas taivaasta ja näe; ota hoitaaksesi tämä viinipuu'),
(1684173,58,19,80,16,'ja suojaa se, minkä sinun oikea kätesi istutti, tämä taimi, jonka kasvatit suureksi itseäsi varten.'),
(1684174,58,19,80,17,'Se on tulen polttama, se on karsittu. He hukkuvat sinun kasvojesi uhkauksesta.'),
(1684175,58,19,80,18,'Kätesi suojelkoon sinun oikean kätesi miestä, ihmislasta, jonka kasvatit suureksi itseäsi varten.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684176,58,19,80,19,'Silloin me emme sinusta luovu. Suo meidän elää, niin me huudamme sinun nimeäsi avuksemme.'),
(1684177,58,19,80,20,'Herra, Jumala Sebaot, saata meidät entisellemme, valista kasvosi, niin me autetuiksi tulemme.'),
(1684178,58,19,81,1,'Veisuunjohtajalle; veisataan kuin viininkorjuulaulu; Aasafin virsi.'),
(1684179,58,19,81,2,'Nostakaa ilohuuto Jumalalle, joka on meidän väkevyytemme; nostakaa riemuhuuto Jaakobin Jumalalle.'),
(1684180,58,19,81,3,'Virittäkää kiitosvirsi, lyökää vaskirumpuja, soittakaa suloisesti kanteleita ynnä harppuja.'),
(1684181,58,19,81,4,'Puhaltakaa pasunaa uudenkuun aikana, täyden kuun aikana, meidän juhlapäivämme kunniaksi.'),
(1684182,58,19,81,5,'Sillä tämä on käsky Israelille, Jaakobin Jumalan säädös.'),
(1684183,58,19,81,6,'Hän asetti sen todistukseksi Joosefille käydessään Egyptin maata vastaan. Minä kuulen puheen, joka on minulle outo:'),
(1684184,58,19,81,7,'"Minä nostin taakan hänen hartioiltansa, hänen kätensä pääsivät kantokorin kuormasta.'),
(1684185,58,19,81,8,'Hädässäsi sinä huusit, ja minä vapautin sinut; ukkospilven peitosta minä vastasin sinulle, minä koettelin sinua Meriban veden luona." Sela.'),
(1684186,58,19,81,9,'"Kuule, kansani, minä varoitan sinua; Israel, jospa sinä minua kuulisit!'),
(1684187,58,19,81,10,'Älköön sinulla olko muukalaista jumalaa, äläkä kumarra vierasta jumalaa.'),
(1684188,58,19,81,11,'Minä olen Herra, sinun Jumalasi, joka toin sinut Egyptin maasta; avaa suusi, niin minä sen täytän.'),
(1684189,58,19,81,12,'Mutta minun kansani ei kuullut minun ääntäni, eikä Israel noudattanut minun mieltäni.'),
(1684190,58,19,81,13,'Niin minä annoin heidän mennä pois sydämensä paatumuksessa, he saivat vaeltaa omien neuvojensa mukaan.'),
(1684191,58,19,81,14,'Oi, jospa minun kansani minua kuulisi ja Israel vaeltaisi minun teilläni,'),
(1684192,58,19,81,15,'niin minä pian masentaisin heidän vihollisensa ja kääntäisin käteni heidän vihamiehiänsä vastaan.'),
(1684193,58,19,81,16,'Ne, jotka Herraa vihaavat, matelisivat hänen edessään, ja heidän kohtalonsa kestäisi iankaikkisesti.'),
(1684194,58,19,81,17,'Mutta kansaansa hän ruokkisi parhaalla nisulla; minä ravitsisin sinua hunajalla kalliosta."'),
(1684195,58,19,82,1,'Aasafin virsi. Jumala seisoo jumalien kokouksessa, hän on tuomari jumalien keskellä:'),
(1684196,58,19,82,2,'"Kuinka kauan te tuomitsette väärin ja pidätte jumalattomain puolta?" Sela.'),
(1684197,58,19,82,3,'"Auttakaa oikeuteensa vaivainen ja orpo, antakaa kurjalle ja puutteenalaiselle oikeus.'),
(1684198,58,19,82,4,'Vapauttakaa vaivainen ja köyhä, pelastakaa hänet jumalattomain käsistä.'),
(1684199,58,19,82,5,'Ei ole heillä älyä, ei ymmärrystä, he vaeltavat pimeydessä: kaikki maan perustukset horjuvat.'),
(1684200,58,19,82,6,'Minä sanon: Te olette jumalia ja kaikki tyynni Korkeimman poikia;'),
(1684201,58,19,82,7,'kuitenkin te kuolette, niinkuin ihmiset kuolevat, ja kaadutte niinkuin kuka ruhtinas tahansa."'),
(1684202,58,19,82,8,'Nouse, Jumala, tuomitse maa, sillä sinä perit kaikki pakanakansat.'),
(1684203,58,19,83,1,'Laulu, Aasafin virsi.'),
(1684204,58,19,83,2,'Jumala, älä ole niin ääneti, älä ole vaiti, älä ole, Jumala, niin hiljaa.'),
(1684205,58,19,83,3,'Sillä, katso, sinun vihollisesi pauhaavat, ja sinun vihaajasi nostavat päätänsä.'),
(1684206,58,19,83,4,'Heillä on kavalat hankkeet sinun kansaasi vastaan, ja he pitävät neuvoa sinun suojattejasi vastaan.'),
(1684207,58,19,83,5,'He sanovat: "Tulkaa, hävittäkäämme heidät olemasta kansa, niin ettei Israelin nimeä enää muisteta".'),
(1684208,58,19,83,6,'Sillä he neuvottelevat keskenään yksimielisesti, he tekevät liiton sinua vastaan:'),
(1684209,58,19,83,7,'Edomin teltat ja ismaelilaiset, Mooab ja hagrilaiset,'),
(1684210,58,19,83,8,'Gebal, Ammon ja Amalek, Filistea ynnä Tyyron asukkaat.'),
(1684211,58,19,83,9,'Myös Assur on liittynyt heihin, nämä ovat käsivartena Lootin lapsilla. Sela.'),
(1684212,58,19,83,10,'Tee heille, niinkuin teit Midianille, niinkuin Siiseralle, niinkuin Jaabinille Kiison-joen rannalla.'),
(1684213,58,19,83,11,'Heidät tuhottiin Eendorissa, he joutuivat lannaksi maahan.'),
(1684214,58,19,83,12,'Anna heidän ylhäisillensä käydä, niinkuin kävi Oorebille ja Seebille, ja kaikille heidän ruhtinaillensa niinkuin Seballe ja Salmunnalle,'),
(1684215,58,19,83,13,'koska he sanovat: "Anastakaamme itsellemme Jumalan asunnot".'),
(1684216,58,19,83,14,'Jumalani, tee heidät lentäviksi lehdiksi, kuiviksi korsiksi tuulen viedä.'),
(1684217,58,19,83,15,'Niinkuin kulovalkea metsää polttaa, niinkuin liekit kärventävät vuoria,'),
(1684218,58,19,83,16,'niin aja sinä heitä rajuilmallasi ja kauhistuta heitä tuulispäälläsi.'),
(1684219,58,19,83,17,'Täytä heidän kasvonsa häpeällä, että he etsisivät sinun nimeäsi, Herra.'),
(1684220,58,19,83,18,'Joutukoot häpeään ja kauhistukoot ikuisesti, tulkoot häpeään ja hukkukoot.'),
(1684221,58,19,83,19,'Ja tulkoot tuntemaan, että sinun ainoan nimi on Herra, että sinä olet Korkein kaikessa maassa.'),
(1684222,58,19,84,1,'Veisuunjohtajalle; veisataan kuin viininkorjuulaulu; koorahilaisten virsi.'),
(1684223,58,19,84,2,'Kuinka ihanat ovat sinun asuinsijasi, Herra Sebaot!'),
(1684224,58,19,84,3,'Minun sieluni ikävöitsee ja halajaa Herran esikartanoihin, minun sydämeni ja ruumiini pyrkii riemuiten elävää Jumalaa kohti.'),
(1684225,58,19,84,4,'Löysihän lintunen majan ja pääskynen pesän, johon se poikasensa laskee: sinun alttarisi, Herra Sebaot, minun kuninkaani ja minun Jumalani.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684226,58,19,84,5,'Autuaat ne, jotka sinun huoneessasi asuvat! He kiittävät sinua alati. Sela.'),
(1684227,58,19,84,6,'Autuaat ne ihmiset, joilla on voimansa sinussa, joilla on mielessänsä pyhät matkat!'),
(1684228,58,19,84,7,'Kun he käyvät Kyynellaakson kautta, he muuttavat sen lähteitten maaksi, ja syyssade peittää sen siunauksilla.'),
(1684229,58,19,84,8,'He käyvät voimasta voimaan, he astuvat Jumalan eteen Siionissa.'),
(1684230,58,19,84,9,'Herra, Jumala Sebaot, kuule minun rukoukseni, ota se korviisi, Jaakobin Jumala. Sela.'),
(1684231,58,19,84,10,'Jumala, meidän kilpemme, käännä katseesi, katso voideltusi kasvoja.'),
(1684232,58,19,84,11,'Sillä yksi päivä sinun esikartanoissasi on parempi kuin tuhat muualla; mieluummin minä olen vartijana Jumalani huoneen kynnyksellä, kuin asun jumalattomien majoissa.'),
(1684233,58,19,84,12,'Sillä Herra Jumala on aurinko ja kilpi; Herra antaa armon ja kunnian, ei hän kiellä hyvää niiltä, jotka nuhteettomasti vaeltavat.'),
(1684234,58,19,84,13,'Herra Sebaot, autuas se ihminen, joka sinuun turvaa!'),
(1684235,58,19,85,1,'Veisuunjohtajalle; koorahilaisten virsi.'),
(1684236,58,19,85,2,'Herra, ennen sinä olit suosiollinen maallesi, sinä käänsit Jaakobin kohtalon.'),
(1684237,58,19,85,3,'Sinä annoit anteeksi kansasi pahat teot ja peitit kaikki heidän syntinsä. Sela.'),
(1684238,58,19,85,4,'Sinä panit kaiken kiivastuksesi pois ja lauhduit vihasi hehkusta.'),
(1684239,58,19,85,5,'Käänny taas meidän puoleemme, sinä pelastuksemme Jumala, älä ole enää tuimistunut meihin.'),
(1684240,58,19,85,6,'Oletko ainiaaksi vihastunut meihin, pidätkö vihaa suvusta sukuun?'),
(1684241,58,19,85,7,'Etkö virvoita meitä eloon jälleen, että sinun kansasi iloitsisi sinussa?'),
(1684242,58,19,85,8,'Herra, suo meidän nähdä sinun armosi, anna apusi meille.'),
(1684243,58,19,85,9,'Minä tahdon kuulla, mitä Jumala, Herra, puhuu: hän puhuu rauhaa kansallensa, hurskaillensa; älkööt he kääntykö jälleen tyhmyyteen.'),
(1684244,58,19,85,10,'Totisesti, hänen apunsa on lähellä niitä, jotka häntä pelkäävät, ja niin meidän maassamme kunnia asuu.'),
(1684245,58,19,85,11,'Armo ja totuus tapaavat toisensa täällä, vanhurskaus ja rauha antavat suuta toisillensa,'),
(1684246,58,19,85,12,'uskollisuus versoo maasta, ja vanhurskaus katsoo taivaasta.'),
(1684247,58,19,85,13,'Herra antaa meille kaikkea hyvää, ja meidän maamme antaa satonsa.'),
(1684248,58,19,85,14,'Vanhurskaus käy hänen edellänsä ja seuraa hänen askeltensa jälkiä.'),
(1684249,58,19,86,1,'Daavidin rukous. Kallista, Herra, korvasi minun puoleeni ja vastaa minulle, sillä minä olen kurja ja köyhä.'),
(1684250,58,19,86,2,'Varjele minun sieluni, sillä minä olen hurskas; sinä, minun Jumalani, pelasta palvelijasi, joka sinuun turvaa.'),
(1684251,58,19,86,3,'Ole minulle armollinen, Herra, sillä sinua minä huudan kaiken päivää.'),
(1684252,58,19,86,4,'Ilahuta palvelijasi sielu, sillä sinun puoleesi, Herra, minä ylennän sieluni.'),
(1684253,58,19,86,5,'Sillä sinä, Herra, olet hyvä ja anteeksiantavainen, suuri armossa kaikille, jotka sinua avuksensa huutavat.'),
(1684254,58,19,86,6,'Ota, Herra, korviisi minun rukoukseni, tarkkaa minun anomiseni ääntä.'),
(1684255,58,19,86,7,'Hätäni päivänä minä sinua avukseni huudan, sillä sinä vastaat minulle.'),
(1684256,58,19,86,8,'Ei ole sinun vertaistasi, Herra, jumalien joukossa, eikä ole vertaa sinun töillesi.'),
(1684257,58,19,86,9,'Kaikki kansat, jotka sinä tehnyt olet, tulevat ja kumartuvat sinun edessäsi, Herra, ja kunnioittavat sinun nimeäsi.'),
(1684258,58,19,86,10,'Sillä sinä olet suuri ja teet ihmeitä, sinä ainoa olet Jumala.'),
(1684259,58,19,86,11,'Neuvo minulle tiesi, Herra, että minä vaeltaisin sinun totuudessasi. Kiinnitä minun sydämeni siihen yhteen, että minä sinun nimeäsi pelkäisin.'),
(1684260,58,19,86,12,'Kaikesta sydämestäni minä kiitän sinua, Herra, minun Jumalani, ja kunnioitan sinun nimeäsi iankaikkisesti;'),
(1684261,58,19,86,13,'sillä sinun armosi on suuri minua kohtaan, sinä olet pelastanut minun sieluni tuonelan syvyydestä.'),
(1684262,58,19,86,14,'Jumala, julkeat ovat nousseet minua vastaan, väkivaltaisten joukko etsii minun henkeäni; eivät he pidä sinua silmäinsä edessä.'),
(1684263,58,19,86,15,'Mutta sinä, Herra, olet laupias ja armahtavainen Jumala, pitkämielinen, suuri armossa ja totuudessa.'),
(1684264,58,19,86,16,'Käänny minun puoleeni, ole minulle armollinen, anna voimasi palvelijallesi, auta palvelijattaresi poikaa.'),
(1684265,58,19,86,17,'Tee merkki minulle, minun hyväkseni. Häpeäksensä minun vihaajani nähkööt, että sinä, Herra, minua autat ja lohdutat.'),
(1684266,58,19,87,1,'Koorahilaisten virsi, laulu. Pyhille vuorille perustamaansa kaupunkia,'),
(1684267,58,19,87,2,'Siionin portteja, Herra rakastaa enemmän kuin Jaakobin kaikkia muita asuinsijoja.'),
(1684268,58,19,87,3,'On kunniakasta, mitä sinusta sanotaan, sinä Jumalan kaupunki: - Sela. -'),
(1684269,58,19,87,4,'"Minä mainitsen tunnustajikseni Rahabin ja Baabelin; katso, Filisteasta, Tyyrosta ja Etiopiasta minä mainitsen: Sekin on syntynyt siellä."'),
(1684270,58,19,87,5,'Mutta Siionista sanotaan: "Joka-ainoa on syntynyt siellä". Sitä Korkein itse vahvana pitää.'),
(1684271,58,19,87,6,'Herra luettelee, kirjoittaessaan kirjaan kansat: "Tämäkin on syntynyt siellä". Sela.'),
(1684272,58,19,87,7,'Veisaten, karkeloiden sanotaan: "Kaikki minun lähteeni ovat sinussa".'),
(1684273,58,19,88,1,'Koorahilaisten laulu, virsi; veisuunjohtajalle; veisataan kuin: "Sairaus"; esrahilaisen Heemanin mietevirsi.'),
(1684274,58,19,88,2,'Herra, minun pelastukseni Jumala, päivin ja öin minä huudan sinun edessäsi.'),
(1684275,58,19,88,3,'Salli minun rukoukseni tulla kasvojesi eteen, kallista korvasi minun huutoni puoleen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684276,58,19,88,4,'Sillä minun sieluni on kärsimyksistä kylläinen, ja minun elämäni on lähellä tuonelaa.'),
(1684277,58,19,88,5,'Minut luetaan hautaan menevien joukkoon, minä olen kuin mies, jolta voima on poissa.'),
(1684278,58,19,88,6,'Minä olen jätetty kuolleitten joukkoon, olen kuin kaatuneet, jotka haudassa makaavat ja joita sinä et enää muista ja jotka ovat sinun kädestäsi erotetut.'),
(1684279,58,19,88,7,'Sinä olet laskenut minut syvimpään hautaan, pimeyteen, syviin kuiluihin.'),
(1684280,58,19,88,8,'Sinun vihasi painaa minua, ja kaikki kuohusi sinä vyörytät minun ylitseni. Sela.'),
(1684281,58,19,88,9,'Sinä olet karkoittanut tuttavani minusta kauas, olet tehnyt minut heille inhoksi; minä olen suljettu sisään enkä pääse ulos.'),
(1684282,58,19,88,10,'Minun kasvoni ovat kuihtuneet kurjuudesta. Joka päivä minä huudan sinua, Herra, ja ojennan käteni sinun puoleesi.'),
(1684283,58,19,88,11,'Teetkö sinä ihmeitä kuolleille, tai nousevatko haamut sinua kiittämään? Sela.'),
(1684284,58,19,88,12,'Kerrotaanko haudassa sinun armostasi, manalassa sinun uskollisuudestasi?'),
(1684285,58,19,88,13,'Tunnetaanko sinun ihmeitäsi pimeydessä ja sinun vanhurskauttasi unhotuksen maassa?'),
(1684286,58,19,88,14,'Mutta minä huudan avukseni sinua, Herra, ja minun rukoukseni tulee varhain sinun eteesi.'),
(1684287,58,19,88,15,'Miksi, Herra, hylkäät minun sieluni, miksi peität kasvosi minulta?'),
(1684288,58,19,88,16,'Minä olen kurja ja lähellä kuolemaa hamasta nuoruudestani, minä kärsin sinun kauhujasi, olen neuvoton.'),
(1684289,58,19,88,17,'Sinun vihasi vyöryy minun ylitseni, sinun hirmusi hukuttavat minut.'),
(1684290,58,19,88,18,'Ne saartavat minua kaiken päivää kuin vedet, ne kaikki yhdessä piirittävät minua.'),
(1684291,58,19,88,19,'Ystävät ja toverit sinä olet karkoittanut minusta kauas, pimeys on minun ainoa tuttavani.'),
(1684292,58,19,89,1,'Esrahilaisen Eetanin mietevirsi.'),
(1684293,58,19,89,2,'Minä laulan Herran armoteoista lakkaamatta, julistan suullani sinun uskollisuuttasi polvesta polveen.'),
(1684294,58,19,89,3,'Minä sanon: ikiajoiksi on armo rakennettu, sinä olet perustanut uskollisuutesi taivaisiin. -'),
(1684295,58,19,89,4,'"Minä olen tehnyt liiton valittuni kanssa, olen palvelijalleni Daavidille vannonut:'),
(1684296,58,19,89,5,'''Minä vahvistan sinun jälkeläisesi ikiajoiksi ja rakennan sinulle valtaistuimen polvesta polveen''". Sela.'),
(1684297,58,19,89,6,'Ja taivaat ylistävät sinun ihmeitäsi, Herra, ja pyhäin seurakunta sinun uskollisuuttasi.'),
(1684298,58,19,89,7,'Sillä kuka pilvissä on Herran vertainen, kuka Jumalan poikain joukossa on niinkuin Herra?'),
(1684299,58,19,89,8,'Hän on Jumala, ylen hirmuinen pyhien kokouksessa, peljättävämpi kaikkia, jotka hänen ympärillänsä ovat.'),
(1684300,58,19,89,9,'Herra, Jumala Sebaot, kuka on voimassa sinun vertaisesi, Herra? Ja sinun uskollisuutesi ympäröitsee sinua.'),
(1684301,58,19,89,10,'Sinä hallitset meren raivon; kun sen aallot kohoavat, sinä ne asetat.'),
(1684302,58,19,89,11,'Sinä ruhjoit Rahabin kuin sodassa kaatuneen; väkevällä käsivarrellasi sinä ajoit vihollisesi hajalle.'),
(1684303,58,19,89,12,'Sinun ovat taivaat, sinun on myös maa; maanpiirin täysinensä sinä olet perustanut.'),
(1684304,58,19,89,13,'Sinä loit pohjoisen ja etelän; sinun nimestäsi riemuitsevat Taabor ja Hermon.'),
(1684305,58,19,89,14,'Sinulla on käsivarsi voimaa täynnä, väkevä on sinun kätesi, korotettu sinun oikea kätesi.'),
(1684306,58,19,89,15,'Vanhurskaus ja oikeus on sinun valtaistuimesi perustus, armo ja totuus käy sinun kasvojesi edellä.'),
(1684307,58,19,89,16,'Autuas se kansa, joka tuntee juhlariemun, ne, jotka vaeltavat sinun kasvojesi valkeudessa, Herra!'),
(1684308,58,19,89,17,'He riemuitsevat sinun nimestäsi kaikkina päivinänsä, ja sinun vanhurskautesi voimasta heidät korotetaan.'),
(1684309,58,19,89,18,'Sillä sinä olet heidän väkevyytensä, heidän kaunistuksensa, ja sinä armossasi kohotat meidän sarvemme.'),
(1684310,58,19,89,19,'Sillä meidän kilpemme on Herran huomassa, meidän kuninkaamme on Israelin Pyhän huomassa.'),
(1684311,58,19,89,20,'Silloin sinä näyssä puhuit hurskaillesi ja sanoit: "Minä olen pannut avun sankarin käteen, olen kansan keskeltä korottanut valittuni:'),
(1684312,58,19,89,21,'minä olen löytänyt Daavidin, palvelijani, olen voidellut hänet pyhällä öljylläni.'),
(1684313,58,19,89,22,'Minun käteni on lujasti tukeva häntä, minun käsivarteni on häntä vahvistava.'),
(1684314,58,19,89,23,'Ei vihollinen yllätä häntä, eikä vääryyden mies häntä sorra;'),
(1684315,58,19,89,24,'vaan minä hävitän hänen ahdistajansa hänen edestänsä ja lyön hänen vihamiehensä maahan.'),
(1684316,58,19,89,25,'Minun uskollisuuteni ja armoni on hänen kanssansa, ja minun nimessäni kohoaa hänen sarvensa.'),
(1684317,58,19,89,26,'Minä asetan hänen kätensä vallitsemaan merta ja virtoja hänen oikean kätensä.'),
(1684318,58,19,89,27,'Hän kutsuu minua: ''Sinä olet minun isäni, sinä minun Jumalani ja pelastukseni kallio''.'),
(1684319,58,19,89,28,'Ja minä asetan hänet esikoiseksi, maan kuninkaista korkeimmaksi.'),
(1684320,58,19,89,29,'Minä säilytän armoni hänelle iankaikkisesti, ja minun liittoni hänen kanssaan on luja.'),
(1684321,58,19,89,30,'Minä annan hänen jälkeläistensä säilyä iäti ja hänen valtaistuimensa niin kauan, kuin taivaat pysyvät.'),
(1684322,58,19,89,31,'Jos hänen poikansa hylkäävät minun lakini eivätkä vaella minun oikeuksieni mukaan,'),
(1684323,58,19,89,32,'jos he minun säädökseni rikkovat eivätkä noudata minun käskyjäni,'),
(1684324,58,19,89,33,'niin minä rankaisen vitsalla heidän rikoksensa ja heidän pahat tekonsa vitsauksilla;'),
(1684325,58,19,89,34,'mutta armoani en minä ota häneltä pois enkä vilpistele uskollisuudestani.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684326,58,19,89,35,'En minä liittoani riko, enkä muuta sitä, mikä on minun huuliltani lähtenyt.'),
(1684327,58,19,89,36,'Minä olen kerran vannonut pyhyyteni kautta, ja totisesti, minä en Daavidille valhettele:'),
(1684328,58,19,89,37,'''Hänen jälkeläisensä pysyvät iankaikkisesti, ja hänen valtaistuimensa on minun edessäni niinkuin aurinko,'),
(1684329,58,19,89,38,'se pysyy lujana iankaikkisesti niinkuin kuu. Ja todistaja pilvissä on uskollinen''." Sela.'),
(1684330,58,19,89,39,'Ja kuitenkin sinä hylkäsit voideltusi ja pidit häntä halpana ja olet vihastunut häneen.'),
(1684331,58,19,89,40,'Sinä olet purkanut palvelijasi liiton, olet häväissyt hänen kruununsa, olet heittänyt sen maahan.'),
(1684332,58,19,89,41,'Sinä olet särkenyt kaikki hänen muurinsa, olet pannut raunioiksi hänen linnoituksensa.'),
(1684333,58,19,89,42,'Kaikki tien kulkijat ovat häntä ryöstäneet, hän on joutunut naapuriensa häväistäväksi.'),
(1684334,58,19,89,43,'Sinä olet korottanut hänen vihollistensa oikean käden, olet tuottanut ilon kaikille hänen vihamiehillensä.'),
(1684335,58,19,89,44,'Sinä olet kääntänyt takaisin hänen miekkansa terän etkä ole sodassa pitänyt häntä pystyssä.'),
(1684336,58,19,89,45,'Sinä olet tehnyt hänen loistostansa lopun ja olet syössyt maahan hänen valtaistuimensa.'),
(1684337,58,19,89,46,'Sinä olet lyhentänyt hänen nuoruutensa päivät, olet hänet häpeällä peittänyt. Sela.'),
(1684338,58,19,89,47,'Kuinka kauan sinä, Herra, itsesi yhäti kätket? Kuinka kauan sinun vihasi tulena palaa?'),
(1684339,58,19,89,48,'Muista, kuinka lyhyt minun elämäni on, kuinka katoavaisiksi sinä olet luonut kaikki ihmislapset.'),
(1684340,58,19,89,49,'Kuka on se mies, joka jää eloon eikä kuoloa näe, joka pelastaa sielunsa tuonelan kädestä? Sela.'),
(1684341,58,19,89,50,'Herra, missä ovat sinun entiset armotekosi, jotka sinä uskollisuudessasi vannoit Daavidille?'),
(1684342,58,19,89,51,'Ajattele, Herra, palvelijaisi häpäisyä ja mitä minun kaikilta noilta monilta kansoilta täytyy povessani kestää,'),
(1684343,58,19,89,52,'kun, Herra, sinun vihollisesi herjaavat, herjaavat sinun voideltusi askeleita.'),
(1684344,58,19,89,53,'Kiitetty olkoon Herra iankaikkisesti. Amen, amen.'),
(1684345,58,19,90,1,'Mooseksen, Jumalan miehen, rukous. Herra, sinä olet meidän turvamme polvesta polveen.'),
(1684346,58,19,90,2,'Ennenkuin vuoret syntyivät ja sinä loit maan ja maanpiirin, iankaikkisesta iankaikkiseen olet sinä, Jumala.'),
(1684347,58,19,90,3,'Sinä palautat ihmiset takaisin tomuun ja sanot: "Palatkaa jälleen, te ihmisten lapset".'),
(1684348,58,19,90,4,'Sillä tuhat vuotta on sinun silmissäsi niinkuin eilinen päivä, joka meni ohitse, ja niinkuin öinen vartiohetki.'),
(1684349,58,19,90,5,'Sinä huuhdot heidät pois; he ovat kuin uni, ovat kuin ruoho, joka aamulla kukoistaa:'),
(1684350,58,19,90,6,'aamulla se kasvaa ja kukoistaa, mutta illalla se leikataan ja kuivettuu.'),
(1684351,58,19,90,7,'Sillä me hukumme sinun vihasi voimasta, ja sinun kiivastuksesi voimasta me häviämme pois.'),
(1684352,58,19,90,8,'Meidän pahat tekomme sinä asetat eteesi, salaiset syntimme kasvojesi valkeuteen.'),
(1684353,58,19,90,9,'Niin kaikki meidän päivämme kuluvat sinun vihasi alla, vuotemme päättyvät meiltä kuin huokaus.'),
(1684354,58,19,90,10,'Meidän elinpäivämme ovat seitsemänkymmentä vuotta taikka enintään kahdeksankymmentä vuotta; ja parhaimmillaankin ne ovat vaiva ja turhuus, sillä ne kiitävät ohitse, niinkuin me lentäisimme pois.'),
(1684355,58,19,90,11,'Kuka ajattelee sinun vihasi ankaruutta, sinun kiivauttasi, niin että hän sinua pelkäisi?'),
(1684356,58,19,90,12,'Opeta meitä laskemaan päivämme oikein, että me saisimme viisaan sydämen.'),
(1684357,58,19,90,13,'Herra, palaja jälleen. Voi, kuinka kauan? Armahda palvelijoitasi.'),
(1684358,58,19,90,14,'Ravitse aamulla meitä armollasi, suo meille iloa ja riemua kaikkina päivinämme.'),
(1684359,58,19,90,15,'Suo meidän iloita yhtä monta päivää, kuin olet nöyryyttänyt meitä, yhtä monta vuotta, kuin olemme kovaa kokeneet.'),
(1684360,58,19,90,16,'Saakoot palvelijasi nähdä sinun tekosi ja heidän lapsensa sinun kunniasi.'),
(1684361,58,19,90,17,'Ja tulkoon osaksemme Herran, meidän Jumalamme, laupeus. Suo menestyä meille kättemme työn; niin, suo menestyä meidän kättemme työn.'),
(1684362,58,19,91,1,'Joka Korkeimman suojassa istuu ja Kaikkivaltiaan varjossa yöpyy,'),
(1684363,58,19,91,2,'se sanoo: "Herra on minun turvani ja linnani, hän on minun Jumalani, johon minä turvaan".'),
(1684364,58,19,91,3,'Sillä hän päästää sinut linnustajan paulasta, turmiollisesta rutosta.'),
(1684365,58,19,91,4,'Sulillansa hän sinua suojaa, ja sinä saat turvan hänen siipiensä alla; hänen uskollisuutensa on kilpi ja suojus.'),
(1684366,58,19,91,5,'Et sinä pelkää yön kauhuja, et päivällä lentävää nuolta,'),
(1684367,58,19,91,6,'et ruttoa, joka pimeässä kulkee, et kulkutautia, joka päiväsydännä häviötä tekee.'),
(1684368,58,19,91,7,'Vaikka tuhat kaatuisi sinun sivultasi, kymmenen tuhatta oikealta puoleltasi, ei se sinuun satu.'),
(1684369,58,19,91,8,'Sinun silmäsi saavat vain katsella ja nähdä, kuinka jumalattomille kostetaan. -'),
(1684370,58,19,91,9,'Sillä: "Sinä, Herra, olet minun turvani". - Korkeimman olet sinä ottanut suojaksesi.'),
(1684371,58,19,91,10,'Ei kohtaa sinua onnettomuus, eikä vitsaus lähesty sinun majaasi.'),
(1684372,58,19,91,11,'Sillä hän antaa enkeleilleen sinusta käskyn varjella sinua kaikilla teilläsi.'),
(1684373,58,19,91,12,'He kantavat sinua käsillänsä, ettet jalkaasi kiveen loukkaisi.'),
(1684374,58,19,91,13,'Sinä kuljet leijonan ja kyykäärmeen ylitse, sinä tallaat nuorta jalopeuraa ja lohikäärmettä. -'),
(1684375,58,19,91,14,'"Koska hän riippuu minussa kiinni, niin minä hänet pelastan; minä suojelen hänet, koska hän tuntee minun nimeni.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684376,58,19,91,15,'Hän huutaa minua avuksensa, ja minä vastaan hänelle, minä olen hänen tykönänsä, kun hänellä on ahdistus, minä vapahdan hänet ja saatan hänet kunniaan.'),
(1684377,58,19,91,16,'Minä ravitsen hänet pitkällä iällä ja suon hänen nähdä antamani pelastuksen."'),
(1684378,58,19,92,1,'Virsi, sapatinpäivä-laulu.'),
(1684379,58,19,92,2,'Hyvä on Herraa kiittää ja veisata kiitosta sinun nimellesi, sinä Korkein,'),
(1684380,58,19,92,3,'aamulla julistaa sinun armoasi ja yön tullen sinun totuuttasi'),
(1684381,58,19,92,4,'kymmenkielisillä soittimilla ja harpuilla, kannelta soittaen.'),
(1684382,58,19,92,5,'Sillä sinä ilahutat minua, Herra, töilläsi; minä riemuitsen sinun kättesi teoista.'),
(1684383,58,19,92,6,'Kuinka suuret ovat sinun tekosi, Herra! Sinun ajatuksesi ovat ylen syvät.'),
(1684384,58,19,92,7,'Järjetön mies ei tätä ymmärrä, eikä sitä älyä tomppeli.'),
(1684385,58,19,92,8,'Kun jumalattomat rehottavat niinkuin ruoho ja väärintekijät kaikki kukoistavat, on se heidän ikuiseksi häviöksensä.'),
(1684386,58,19,92,9,'Mutta sinä, Herra, olet korkea iankaikkisesti.'),
(1684387,58,19,92,10,'Sillä katso, sinun vihollisesi, Herra, katso, sinun vihollisesi hukkuvat, kaikki väärintekijät joutuvat hajallensa.'),
(1684388,58,19,92,11,'Mutta minun sarveni sinä kohotat kuin villihärän sarvet; minut voidellaan tuoreella öljyllä.'),
(1684389,58,19,92,12,'Ja iloiten minun silmäni katsovat vainoojiani, minun korvani kuulevat noista pahoista, jotka ovat nousseet minua vastaan.'),
(1684390,58,19,92,13,'Vanhurskas viheriöitsee kuin palmupuu, hän kasvaa kuin Libanonin setri.'),
(1684391,58,19,92,14,'He ovat istutetut Herran huoneeseen, he viheriöitsevät meidän Jumalamme kartanoissa.'),
(1684392,58,19,92,15,'Vielä vanhuudessaan he tekevät hedelmää, ovat mehevät ja vihannat'),
(1684393,58,19,92,16,'ja julistavat, että Herra on vanhurskas, hän, minun kallioni, ja ettei hänessä vääryyttä ole.'),
(1684394,58,19,93,1,'Herra on kuningas. Hän on pukenut itsensä korkeudella. Herra on pukeutunut, vyöttäytynyt voimaan. Niin pysyy maanpiiri lujana, se ei horju.'),
(1684395,58,19,93,2,'Sinun valtaistuimesi on vahva aikojen alusta, hamasta iankaikkisuudesta olet sinä.'),
(1684396,58,19,93,3,'Vesivirrat nostavat, Herra, vesivirrat nostavat pauhinansa, niin, vesivirrat nostavat kuohunsa.'),
(1684397,58,19,93,4,'Mutta yli suurten, voimallisten vetten pauhinan, yli meren kuohujen on Herra korkeudessa voimallinen.'),
(1684398,58,19,93,5,'Sinun todistuksesi ovat aivan vahvat, pyhyys on sinun huoneellesi arvollinen, Herra, hamaan aikojen loppuun.'),
(1684399,58,19,94,1,'Sinä koston Jumala, Herra, sinä koston Jumala, ilmesty kirkkaudessa.'),
(1684400,58,19,94,2,'Nouse, maan tuomari, kosta ylpeille heidän tekonsa.'),
(1684401,58,19,94,3,'Kuinka kauan jumalattomat, Herra, kuinka kauan jumalattomat saavat riemuita?'),
(1684402,58,19,94,4,'Ne syytävät suustaan julkeita sanoja, ne röyhkeilevät, kaikki nuo väärintekijät.'),
(1684403,58,19,94,5,'Sinun kansaasi, Herra, he runtelevat, ja sinun perintöosaasi he rasittavat.'),
(1684404,58,19,94,6,'He tappavat leskiä ja muukalaisia ja murhaavat orpoja.'),
(1684405,58,19,94,7,'Ja he sanovat: "Ei Herra sitä näe, ei Jaakobin Jumala sitä huomaa".'),
(1684406,58,19,94,8,'Ymmärtäkää, te kansan järjettömät, ja te tomppelit - milloin te tulette järkiinne?'),
(1684407,58,19,94,9,'Joka on korvan istuttanut, hänkö ei kuulisi? Joka on silmän luonut, hänkö ei näkisi?'),
(1684408,58,19,94,10,'Joka kansat kasvattaa, hänkö ei rankaisisi, hän, joka ihmisille opettaa tiedon?'),
(1684409,58,19,94,11,'Herra tuntee ihmisten ajatukset; sillä he ovat kuin tuulen henkäys.'),
(1684410,58,19,94,12,'Autuas se mies, jota sinä, Herra, kuritat ja jolle sinä opetat lakisi,'),
(1684411,58,19,94,13,'antaaksesi hänelle rauhan pahoilta päiviltä, kunnes jumalattomalle on kaivettu hauta!'),
(1684412,58,19,94,14,'Sillä Herra ei hylkää kansaansa eikä perintöosaansa heitä,'),
(1684413,58,19,94,15,'vaan oikeus on vielä noudattava vanhurskautta, ja kaikki oikeamieliset seuraavat sitä.'),
(1684414,58,19,94,16,'Kuka nousee minun puolelleni pahoja vastaan, kuka asettuu minun rinnalleni väärintekijöitä vastaan?'),
(1684415,58,19,94,17,'Ellei Herra olisi minun apuni, pian minun sieluni asuisi hiljaisuuden maassa.'),
(1684416,58,19,94,18,'Kun minä ajattelen: "Minun jalkani horjuu", niin sinun armosi, Herra, minua tukee.'),
(1684417,58,19,94,19,'Kun minulla on sydämessäni paljon murheita, niin sinun lohdutuksesi ilahuttaa minun sieluni.'),
(1684418,58,19,94,20,'Onko yhteyttä sinun kanssasi turmion tuomioistuimella, jossa väkivaltaa tehdään lain varjolla,'),
(1684419,58,19,94,21,'ahdistetaan vanhurskaan sielua ja tuomitaan syylliseksi viaton veri?'),
(1684420,58,19,94,22,'Mutta Herra on minun linnani, Jumalani on minun suojakallioni.'),
(1684421,58,19,94,23,'Hän kostaa heille heidän ilkityönsä ja hukuttaa heidät heidän pahuutensa tähden. Herra, meidän Jumalamme, hukuttaa heidät.'),
(1684422,58,19,95,1,'Tulkaa, kohottakaamme ilohuuto Herralle, riemuhuuto pelastuksemme kalliolle.'),
(1684423,58,19,95,2,'Käykäämme kiittäen hänen kasvojensa eteen, veisatkaamme hänelle riemuvirsiä.'),
(1684424,58,19,95,3,'Sillä Herra on suuri Jumala, suuri kuningas yli kaikkien jumalien.'),
(1684425,58,19,95,4,'Maan syvyydet ovat hänen kädessänsä, ja hänen ovat vuorten kukkulat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684426,58,19,95,5,'Hänen on meri, sillä hän on sen tehnyt, ja kuiva maa, jonka hänen kätensä ovat valmistaneet.'),
(1684427,58,19,95,6,'Tulkaa, kumartukaamme ja polvistukaamme, polvillemme langetkaamme Herran, meidän Luojamme, eteen.'),
(1684428,58,19,95,7,'Sillä hän on meidän Jumalamme, ja me olemme kansa, jota hän paimentaa, lauma, jota hänen kätensä kaitsee. Jospa te tänä päivänä kuulisitte hänen äänensä:'),
(1684429,58,19,95,8,'"Älkää paaduttako sydäntänne, niinkuin Meribassa, niinkuin Massan päivänä erämaassa,'),
(1684430,58,19,95,9,'jossa teidän isänne minua kiusasivat, jossa he koettelivat minua, vaikka olivat nähneet minun tekoni.'),
(1684431,58,19,95,10,'Neljäkymmentä vuotta minä olin kyllästynyt siihen sukuun ja sanoin: ''He ovat kansa, jonka sydän on eksynyt, eivätkä he tahdo tietää minun teistäni''.'),
(1684432,58,19,95,11,'Ja niin minä vihassani vannoin: ''He eivät pääse minun lepooni''."'),
(1684433,58,19,96,1,'Veisatkaa Herralle uusi virsi, veisatkaa Herralle, kaikki maa.'),
(1684434,58,19,96,2,'Veisatkaa Herralle, ylistäkää hänen nimeänsä. Julistakaa päivästä päivään hänen pelastustekojansa,'),
(1684435,58,19,96,3,'ilmoittakaa pakanain seassa hänen kunniaansa, hänen ihmeitänsä kaikkien kansojen seassa.'),
(1684436,58,19,96,4,'Sillä Herra on suuri ja sangen ylistettävä, hän on peljättävä yli kaikkien jumalain.'),
(1684437,58,19,96,5,'Sillä kaikki kansojen jumalat ovat epäjumalia, mutta Herra on tehnyt taivaat.'),
(1684438,58,19,96,6,'Herraus ja kunnia on hänen kasvojensa edessä, kiitos ja ylistys hänen pyhäkössänsä.'),
(1684439,58,19,96,7,'Antakaa Herralle, te kansojen sukukunnat, antakaa Herralle kunnia ja väkevyys.'),
(1684440,58,19,96,8,'Antakaa Herralle hänen nimensä kunnia, tuokaa lahjoja, tulkaa hänen esikartanoihinsa.'),
(1684441,58,19,96,9,'Kumartakaa Herraa pyhässä kaunistuksessa, vaviskaa hänen kasvojensa edessä, kaikki maa.'),
(1684442,58,19,96,10,'Sanokaa pakanain seassa: "Herra on kuningas". Niin pysyy maanpiiri lujana, se ei horju. Hän tuomitsee kansat oikeuden mukaan.'),
(1684443,58,19,96,11,'Iloitkoot taivaat, ja riemuitkoon maa; pauhatkoon meri ja kaikki, mitä siinä on.'),
(1684444,58,19,96,12,'Ihastukoot kedot ja kaikki, mitä kedolla on, riemuitkoot silloin kaikki metsän puut'),
(1684445,58,19,96,13,'Herran edessä, sillä hän tulee, sillä hän tulee tuomitsemaan maata: hän tuomitsee maanpiirin vanhurskaudessa ja kansat uskollisuudessansa.'),
(1684446,58,19,97,1,'Herra on kuningas! Riemuitkoon maa; iloitkoot saaret, niin monta kuin niitä on.'),
(1684447,58,19,97,2,'Pilvi ja pimeys on hänen ympärillänsä, vanhurskaus ja oikeus on hänen valtaistuimensa perustus.'),
(1684448,58,19,97,3,'Tuli käy hänen edellänsä ja polttaa hänen vihollisensa, yltympäri.'),
(1684449,58,19,97,4,'Hänen salamansa valaisevat maanpiirin; maa näkee sen ja vapisee.'),
(1684450,58,19,97,5,'Vuoret sulavat niinkuin vaha Herran edessä, kaiken maan Herran edessä.'),
(1684451,58,19,97,6,'Taivaat julistavat hänen vanhurskauttansa, ja kaikki kansat näkevät hänen kunniansa.'),
(1684452,58,19,97,7,'Kaikki kuvain kumartajat joutuvat häpeään, kaikki, jotka epäjumalista kerskaavat. Kumartakaa häntä, kaikki jumalat.'),
(1684453,58,19,97,8,'Siion kuulee sen ja iloitsee, ja Juudan tyttäret riemuitsevat sinun tuomioistasi, Herra.'),
(1684454,58,19,97,9,'Sillä sinä, Herra, olet Korkein yli kaiken maan, sinä olet ylen korkea, ylitse kaikkien jumalain.'),
(1684455,58,19,97,10,'Te, jotka Herraa rakastatte, vihatkaa pahaa. Hän varjelee hurskasten sielut, jumalattomien kädestä hän heidät pelastaa.'),
(1684456,58,19,97,11,'Vanhurskaalle koittaa valkeus ja oikeamielisille ilo.'),
(1684457,58,19,97,12,'Iloitkaa Herrassa, te vanhurskaat; kiittäkää hänen pyhää nimeänsä.'),
(1684458,58,19,98,1,'Virsi. Veisatkaa Herralle uusi virsi, sillä hän on ihmeitä tehnyt. Hän on saanut voiton oikealla kädellänsä ja pyhällä käsivarrellansa.'),
(1684459,58,19,98,2,'Herra on tehnyt tiettäväksi pelastustekonsa, hän on ilmaissut vanhurskautensa pakanain silmien edessä.'),
(1684460,58,19,98,3,'Hän on muistanut armonsa ja uskollisuutensa Israelin heimoa kohtaan; kaikki maan ääret ovat nähneet meidän Jumalamme pelastusteot.'),
(1684461,58,19,98,4,'Kohottakaa riemuhuuto Herralle, kaikki maa, iloitkaa ja riemuitkaa ja veisatkaa kiitosta.'),
(1684462,58,19,98,5,'Veisatkaa Herran kiitosta kanteleilla - kanteleilla ja ylistysvirren sävelillä,'),
(1684463,58,19,98,6,'vaskitorvilla ja pasunan äänellä. Kohottakaa riemuhuuto Herran, kuninkaan, edessä.'),
(1684464,58,19,98,7,'Pauhatkoon meri ja kaikki, mitä siinä on, maanpiiri ja ne, jotka siinä asuvat.'),
(1684465,58,19,98,8,'Paukuttakoot käsiänsä virrat, ja vuoret yhdessä riemuitkoot'),
(1684466,58,19,98,9,'Herran edessä; sillä hän tulee tuomitsemaan maata. Hän tuomitsee maanpiirin vanhurskaasti ja kansat oikeuden mukaan.'),
(1684467,58,19,99,1,'Herra on kuningas, vaviskoot kansat - hän, jonka valtaistuinta kerubit kannattavat - huojukoon maa.'),
(1684468,58,19,99,2,'Suuri on Herra Siionissa, hän on korkea yli kaikkien kansojen.'),
(1684469,58,19,99,3,'He ylistävät sinun suurta ja peljättävää nimeäsi. Hän on pyhä.'),
(1684470,58,19,99,4,'Se on kuninkaan voima, että hän rakastaa oikeutta. Sinä olet saattanut oikeuden voimaan, sinä toimitat oikeuden ja vanhurskauden Jaakobissa.'),
(1684471,58,19,99,5,'Ylistäkää Herraa, meidän Jumalaamme, kumartukaa hänen jalkainsa astinlaudan eteen. Hän on pyhä.'),
(1684472,58,19,99,6,'Mooses ja Aaron hänen pappiensa joukossa ja Samuel niiden joukossa, jotka avuksi huusivat hänen nimeänsä, he huusivat Herraa, ja hän vastasi heille.'),
(1684473,58,19,99,7,'Hän puhui heille pilvenpatsaasta; he noudattivat hänen todistuksiansa ja käskyjä, jotka hän oli heille antanut.'),
(1684474,58,19,99,8,'Herra, meidän Jumalamme, sinä vastasit heille, olit heille anteeksiantava Jumala, vaikka sinä heidän pahat tekonsa kostit.'),
(1684475,58,19,99,9,'Ylistäkää Herraa, meidän Jumalaamme, rukoilkaa kumartuneina hänen pyhää vuortansa kohti; sillä Herra, meidän Jumalamme, on pyhä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684476,58,19,100,1,'Kiitosuhri-virsi. Kohottakaa riemuhuuto Herralle, kaikki maa.'),
(1684477,58,19,100,2,'Palvelkaa Herraa ilolla, tulkaa hänen kasvojensa eteen riemulla.'),
(1684478,58,19,100,3,'Tietäkää, että Herra on Jumala. Hän on meidät tehnyt, ja hänen me olemme, hänen kansansa ja hänen laitumensa lampaat.'),
(1684479,58,19,100,4,'Käykää hänen portteihinsa kiittäen, hänen esikartanoihinsa ylistystä veisaten. Ylistäkää häntä, kiittäkää hänen nimeänsä.'),
(1684480,58,19,100,5,'Sillä Herra on hyvä; hänen armonsa pysyy iankaikkisesti ja hänen uskollisuutensa polvesta polveen.'),
(1684481,58,19,101,1,'Daavidin virsi. Minä veisaan armosta ja oikeudesta; sinun ylistystäsi, Herra, minä laulan.'),
(1684482,58,19,101,2,'Minä tahdon noudattaa nuhteetonta vaellusta; milloin tulet sinä minun tyköni? Minä tahdon vaeltaa huoneessani vilpittömällä sydämellä.'),
(1684483,58,19,101,3,'En kiinnitä silmääni siihen, mikä turmiollista on, eksyttäväistä menoa minä vihaan: ei saa se minuun tarttua.'),
(1684484,58,19,101,4,'Nurja sydän väistyköön minusta; pahasta minä en tahdo tietää.'),
(1684485,58,19,101,5,'Joka salaa panettelee lähimmäistänsä, sen minä hukutan; jolla on ylpeät silmät ja kopea sydän, sitä minä en siedä.'),
(1684486,58,19,101,6,'Maan uskollisia minun silmäni etsivät, että he asuisivat minua lähellä; joka vaeltaa nuhteettomuuden tietä, se on oleva minun palvelijani.'),
(1684487,58,19,101,7,'Vilpin tekijä älköön asuko minun huoneessani, valheen puhuja ei kestä minun silmäini edessä.'),
(1684488,58,19,101,8,'Joka aamu minä hukutan kaikki jumalattomat maasta, lopettaakseni kaikki väärintekijät Herran kaupungista.'),
(1684489,58,19,102,1,'Kurjan rukous, kun hän on näännyksissä ja vuodattaa valituksensa Herran eteen.'),
(1684490,58,19,102,2,'Herra, kuule minun rukoukseni, ja minun huutoni tulkoon sinun eteesi.'),
(1684491,58,19,102,3,'Älä peitä minulta kasvojasi, kun minulla on ahdistus, kallista korvasi minun puoleeni. Kun minä huudan, riennä ja vastaa minulle.'),
(1684492,58,19,102,4,'Sillä minun päiväni ovat haihtuneet kuin savu, ja minun luitani polttaa niinkuin ahjossa.'),
(1684493,58,19,102,5,'Sydämeni on paahtunut ja kuivunut kuin ruoho, sillä minä unhotan syödä leipääni.'),
(1684494,58,19,102,6,'Äänekkäästä vaikerruksestani minun luuni tarttuvat minun nahkaani.'),
(1684495,58,19,102,7,'Minä olen kuin pelikaani erämaassa, olen kuin huuhkaja raunioissa.'),
(1684496,58,19,102,8,'Minä olen uneton, olen kuin yksinäinen lintu katolla.'),
(1684497,58,19,102,9,'Kaiken päivää viholliseni minua häpäisevät; ne, jotka riehuvat minua vastaan, kiroavat minun nimeni kautta.'),
(1684498,58,19,102,10,'Sillä minä syön tuhkaa kuin leipää ja sekoitan juomani kyyneleillä'),
(1684499,58,19,102,11,'sinun vihasi ja kiivastuksesi tähden, sillä sinä olet nostanut minut ylös ja viskannut pois.'),
(1684500,58,19,102,12,'Minun päiväni ovat kuin pitenevä varjo, ja minä kuivun kuin ruoho.'),
(1684501,58,19,102,13,'Mutta sinä, Herra, hallitset iankaikkisesti, sinun muistosi pysyy polvesta polveen.'),
(1684502,58,19,102,14,'Nouse ja armahda Siionia, sillä aika on tehdä sille laupeus ja määrähetki on tullut.'),
(1684503,58,19,102,15,'Sillä sen kivet ovat sinun palvelijoillesi rakkaat, ja sen soraläjiä heidän on sääli.'),
(1684504,58,19,102,16,'Silloin pakanat pelkäävät Herran nimeä ja kaikki maan kuninkaat sinun kunniaasi,'),
(1684505,58,19,102,17,'kun Herra rakentaa Siionin ja ilmestyy kunniassansa,'),
(1684506,58,19,102,18,'kun hän kääntyy niiden rukouksen puoleen, jotka ovat kaikkensa menettäneet, eikä enää heidän rukoustansa hylkää.'),
(1684507,58,19,102,19,'Tämä kirjoitettakoon tulevalle polvelle, ja kansa, joka vastedes luodaan, on kiittävä Herraa,'),
(1684508,58,19,102,20,'että hän katseli pyhästä korkeudestaan, että Herra katsoi taivaasta maahan,'),
(1684509,58,19,102,21,'kuullaksensa vankien huokaukset, vapauttaaksensa kuoleman lapset,'),
(1684510,58,19,102,22,'jotta Siionissa julistettaisiin Herran nimeä ja hänen ylistystänsä Jerusalemissa,'),
(1684511,58,19,102,23,'kun kaikki kansat kokoontuvat yhteen, ja valtakunnat, palvelemaan Herraa.'),
(1684512,58,19,102,24,'Hän on lannistanut matkalla minun voimani, on lyhentänyt minun päiväni.'),
(1684513,58,19,102,25,'Minä sanon: Jumalani, älä tempaa minua pois kesken ikääni; sinun vuotesi kestävät suvusta sukuun.'),
(1684514,58,19,102,26,'Muinoin sinä perustit maan, ja taivaat ovat sinun käsialasi.'),
(1684515,58,19,102,27,'Ne katoavat, mutta sinä pysyt, ne vanhenevat kaikki kuin vaate; sinä muutat ne, niinkuin vaatteet muutetaan, ja ne muuttuvat.'),
(1684516,58,19,102,28,'Mutta sinä pysyt samana, eivätkä sinun vuotesi lopu.'),
(1684517,58,19,102,29,'Sinun palvelijaisi lapset saavat asua turvassa, ja heidän jälkeläisensä pysyvät sinun edessäsi.'),
(1684518,58,19,103,1,'Daavidin virsi. Kiitä Herraa, minun sieluni, ja kaikki, mitä minussa on, hänen pyhää nimeänsä.'),
(1684519,58,19,103,2,'Kiitä Herraa, minun sieluni, äläkä unhota, mitä hyvää hän on sinulle tehnyt,'),
(1684520,58,19,103,3,'hän, joka antaa kaikki sinun syntisi anteeksi ja parantaa kaikki sinun sairautesi,'),
(1684521,58,19,103,4,'joka lunastaa sinun henkesi tuonelasta ja kruunaa sinut armolla ja laupeudella,'),
(1684522,58,19,103,5,'joka sinun halajamisesi tyydyttää hyvyydellään, niin että sinun nuoruutesi uudistuu kuin kotkan.'),
(1684523,58,19,103,6,'Herra tekee vanhurskauden ja hankkii oikeuden kaikille sorretuille.'),
(1684524,58,19,103,7,'Hän on tehnyt Moosekselle tunnetuksi tiensä, Israelin lapsille suuret tekonsa.'),
(1684525,58,19,103,8,'Laupias ja armahtavainen on Herra, pitkämielinen ja suuri armossa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684526,58,19,103,9,'Ei hän aina riitele eikä pidä vihaa iankaikkisesti.'),
(1684527,58,19,103,10,'Ei hän tee meille syntiemme mukaan eikä kosta meille pahain tekojemme mukaan.'),
(1684528,58,19,103,11,'Sillä niin korkealla kuin taivas on maasta, niin voimallinen on hänen armonsa niitä kohtaan, jotka häntä pelkäävät.'),
(1684529,58,19,103,12,'Niin kaukana kuin itä on lännestä, niin kauas hän siirtää meistä rikkomuksemme.'),
(1684530,58,19,103,13,'Niinkuin isä armahtaa lapsiansa, niin Herrakin armahtaa pelkääväisiänsä.'),
(1684531,58,19,103,14,'Sillä hän tietää, minkäkaltaista tekoa me olemme: hän muistaa meidät tomuksi.'),
(1684532,58,19,103,15,'Ihmisen elinpäivät ovat niinkuin ruoho, hän kukoistaa niinkuin kukkanen kedolla.'),
(1684533,58,19,103,16,'Kun tuuli käy hänen ylitsensä, ei häntä enää ole, eikä hänen asuinsijansa häntä enää tunne.'),
(1684534,58,19,103,17,'Mutta Herran armo pysyy iankaikkisesta iankaikkiseen niille, jotka häntä pelkäävät, ja hänen vanhurskautensa lasten lapsille,'),
(1684535,58,19,103,18,'niille, jotka pitävät hänen liittonsa ja muistavat hänen käskynsä ja noudattavat niitä.'),
(1684536,58,19,103,19,'Herra on pystyttänyt istuimensa taivaisiin, ja hänen kuninkuutensa hallitsee kaikkia.'),
(1684537,58,19,103,20,'Kiittäkää Herraa, te hänen enkelinsä, te väkevät sankarit, jotka hänen käskynsä täytätte, kun kuulette hänen sanansa äänen.'),
(1684538,58,19,103,21,'Kiittäkää Herraa, kaikki hänen sotaväkensä, te hänen palvelijansa, jotka hänen tahtonsa teette.'),
(1684539,58,19,103,22,'Kiittäkää Herraa, kaikki hänen tekonsa, hänen valtakuntansa kaikissa paikoissa. Kiitä, minun sieluni, Herraa.'),
(1684540,58,19,104,1,'Kiitä Herraa, minun sieluni, Herra, minun Jumalani, sinä olet ylen suuri; valkeus ja kirkkaus on sinun pukusi.'),
(1684541,58,19,104,2,'Sinä verhoudut valoon niinkuin viittaan, sinä levität taivaat niinkuin teltan;'),
(1684542,58,19,104,3,'sinä rakennat salisi vetten päälle, teet pilvet vaunuiksesi ja kuljet tuulen siivillä.'),
(1684543,58,19,104,4,'Sinä teet tuulet sanasi saattajiksi, palvelijoiksesi tulen liekit.'),
(1684544,58,19,104,5,'Sinä asetit maan perustuksillensa, niin että se pysyy horjumatta iankaikkisesti.'),
(1684545,58,19,104,6,'Sinä peitit sen syvyyden vesillä kuin vaatteella: vuoria ylempänä seisoivat vedet.'),
(1684546,58,19,104,7,'Mutta ne pakenivat sinun nuhteluasi, sinun jylinääsi ne juoksivat pakoon;'),
(1684547,58,19,104,8,'vuoret kohosivat ja laaksot laskeutuivat paikkoihin, jotka sinä olit niille valmistanut.'),
(1684548,58,19,104,9,'Sinä panit rajan, jonka yli vedet eivät käy eivätkä palaja peittämään maata.'),
(1684549,58,19,104,10,'Sinä kuohutit laaksoista lähteet, jotka vuorten välillä vuotavat.'),
(1684550,58,19,104,11,'Ne antavat juoman kaikille metsän eläimille, villiaasit niistä janonsa sammuttavat.'),
(1684551,58,19,104,12,'Niiden partailla asuvat taivaan linnut ja visertävät lehvien välissä.'),
(1684552,58,19,104,13,'Saleistasi sinä kastelet vuoret, sinun töittesi hedelmistä maa saa ravintonsa.'),
(1684553,58,19,104,14,'Sinä kasvatat ruohon karjalle ja kasvit ihmisen tarpeeksi. Niin sinä tuotat maasta leivän'),
(1684554,58,19,104,15,'ja viinin, joka ilahuttaa ihmisen sydämen; niin sinä saatat kasvot öljystä kiiltäviksi, ja leipä vahvistaa ihmisen sydäntä.'),
(1684555,58,19,104,16,'Ravintonsa saavat myös Herran puut, Libanonin setrit, jotka hän on istuttanut.'),
(1684556,58,19,104,17,'Niissä lintuset pesivät, ja haikaroilla on majansa kypresseissä.'),
(1684557,58,19,104,18,'Korkeat vuoret ovat kauristen hallussa, kallionkolot ovat tamaanien suoja.'),
(1684558,58,19,104,19,'Kuun sinä olet tehnyt näyttämään aikoja; aurinko tietää laskunsa.'),
(1684559,58,19,104,20,'Sinä teet pimeän, niin tulee yö; silloin lähtevät liikkeelle kaikki metsän eläimet.'),
(1684560,58,19,104,21,'Nuoret jalopeurat kiljuvat saalista ja pyytävät Jumalalta elatustansa.'),
(1684561,58,19,104,22,'Aurinko nousee, ne vetäytyvät pois ja laskeutuvat luoliinsa maata.'),
(1684562,58,19,104,23,'Silloin ihminen menee töihinsä ja askaroitsee iltaan asti.'),
(1684563,58,19,104,24,'Kuinka moninaiset ovat sinun tekosi, Herra! Sinä olet ne kaikki viisaasti tehnyt, maa on täynnä sinun luotujasi.'),
(1684564,58,19,104,25,'Merikin, suuri ja aava - siinä vilisee lukemattomat laumat pieniä ja suuria eläviä.'),
(1684565,58,19,104,26,'Siellä kulkevat laivat, siellä Leviatan, jonka sinä olet luonut siinä leikitsemään.'),
(1684566,58,19,104,27,'Ne kaikki odottavat sinua, että antaisit heille ruuan ajallansa.'),
(1684567,58,19,104,28,'Sinä annat niille, ja ne kokoavat, sinä avaat kätesi, ja ne ravitaan hyvyydellä.'),
(1684568,58,19,104,29,'Sinä peität kasvosi, ja ne peljästyvät, sinä otat pois niiden hengen, ne kuolevat ja palajavat tomuun jälleen.'),
(1684569,58,19,104,30,'Sinä lähetät henkesi, ja ne luodaan; ja sinä uudistat maan muodon.'),
(1684570,58,19,104,31,'Pysyköön Herran kunnia iankaikkisesti. Saakoon Herra teoistansa iloita,'),
(1684571,58,19,104,32,'hän, joka katsahtaa maahan, ja se vapisee, joka koskettaa vuoria, ja ne suitsuavat.'),
(1684572,58,19,104,33,'Kaiken ikäni minä ylistän Herraa, minä veisaan Jumalani kiitosta, niin kauan kuin elän.'),
(1684573,58,19,104,34,'Olkoot minun tutkisteluni hänelle otolliset; minä iloitsen Herrassa.'),
(1684574,58,19,104,35,'Hävitkööt syntiset maasta, älköön jumalattomia enää olko. Kiitä Herraa, minun sieluni. Halleluja!'),
(1684575,58,19,105,1,'Kiittäkää Herraa, julistakaa hänen nimeänsä, tehkää hänen suuret tekonsa tiettäviksi kansojen keskuudessa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684576,58,19,105,2,'Laulakaa hänelle, veisatkaa hänelle, puhukaa kaikista hänen ihmeistänsä.'),
(1684577,58,19,105,3,'Hänen pyhä nimensä olkoon teidän kerskauksenne; iloitkoon niiden sydän, jotka etsivät Herraa.'),
(1684578,58,19,105,4,'Kysykää Herraa ja hänen voimaansa, etsikää alati hänen kasvojansa.'),
(1684579,58,19,105,5,'Muistakaa hänen ihmetöitänsä, jotka hän on tehnyt, hänen ihmeitänsä ja hänen suunsa tuomioita,'),
(1684580,58,19,105,6,'te Aabrahamin, hänen palvelijansa, siemen, Jaakobin lapset, te hänen valittunsa.'),
(1684581,58,19,105,7,'Hän, Herra, on meidän Jumalamme; hänen tuomionsa käyvät yli kaiken maan.'),
(1684582,58,19,105,8,'Hän muistaa liittonsa iankaikkisesti, säätämänsä sanan hamaan tuhansiin polviin,'),
(1684583,58,19,105,9,'liittonsa, jonka hän teki Aabrahamin kanssa, ja Iisakille vannomansa valan.'),
(1684584,58,19,105,10,'Hän vahvisti sen käskyksi Jaakobille, Israelille iankaikkiseksi liitoksi.'),
(1684585,58,19,105,11,'Hän sanoi: "Sinulle minä annan Kanaanin maan, se olkoon teidän perintöosanne".'),
(1684586,58,19,105,12,'Heitä oli vähäinen joukko, vain harvoja, ja he olivat muukalaisia siellä.'),
(1684587,58,19,105,13,'Ja he vaelsivat kansasta kansaan ja yhdestä valtakunnasta toiseen kansaan.'),
(1684588,58,19,105,14,'Hän ei sallinut kenenkään heitä vahingoittaa, ja hän rankaisi kuninkaita heidän tähtensä:'),
(1684589,58,19,105,15,'"Älkää koskeko minun voideltuihini, älkää tehkö pahaa minun profeetoilleni".'),
(1684590,58,19,105,16,'Ja kun hän kutsui nälänhädän maahan ja kokonaan mursi leivän tuen,'),
(1684591,58,19,105,17,'oli hän lähettänyt heidän edellänsä miehen: Joosef oli myyty orjaksi.'),
(1684592,58,19,105,18,'Hänen jalkojansa vaivattiin kahleilla, hän joutui rautoihin,'),
(1684593,58,19,105,19,'siksi kunnes hänen sanansa kävi toteen ja Herran puhe osoitti hänet puhtaaksi.'),
(1684594,58,19,105,20,'Niin kuningas lähetti ja päästätti hänet, kansojen hallitsija laski hänet irti.'),
(1684595,58,19,105,21,'Hän pani hänet talonsa herraksi ja kaiken omaisuutensa haltijaksi,'),
(1684596,58,19,105,22,'sitomaan mielensä mukaan hänen ruhtinaitansa ja opettamaan viisautta vanhimmille.'),
(1684597,58,19,105,23,'Niin joutui Israel Egyptiin, Jaakob muukalaiseksi Haamin maahan.'),
(1684598,58,19,105,24,'Ja Herra teki kansansa hyvin hedelmälliseksi ja väkevämmäksi heidän vihamiehiänsä.'),
(1684599,58,19,105,25,'Hän käänsi näitten sydämen vihaamaan hänen kansaansa, kavalasti kohtelemaan hänen palvelijoitaan.'),
(1684600,58,19,105,26,'Hän lähetti Mooseksen, palvelijansa, ja Aaronin, jonka hän oli valinnut.'),
(1684601,58,19,105,27,'Nämä tekivät hänen tunnustekonsa heidän keskellään, tekivät ihmeitä Haamin maassa.'),
(1684602,58,19,105,28,'Hän lähetti pimeyden ja pimensi kaiken, eivätkä he vastustaneet hänen sanojansa.'),
(1684603,58,19,105,29,'Hän muutti heidän vetensä vereksi ja kuoletti heiltä kalat.'),
(1684604,58,19,105,30,'Heidän maansa vilisi sammakoita aina kuningasten kammioita myöten.'),
(1684605,58,19,105,31,'Hän käski, ja paarmoja tuli ja sääskiä koko heidän alueellensa.'),
(1684606,58,19,105,32,'Hän antoi heille rakeita sateen sijaan, tulen leimauksia heidän maahansa.'),
(1684607,58,19,105,33,'Ja hän hävitti heidän viini- ja viikunapuunsa ja murskasi puut heidän alueeltansa.'),
(1684608,58,19,105,34,'Hän käski, ja heinäsirkkoja tuli ja tuhosirkkoja lukematon joukko;'),
(1684609,58,19,105,35,'ne söivät kaiken ruohon heidän maastansa, söivät hedelmän heidän vainioiltansa.'),
(1684610,58,19,105,36,'Ja hän surmasi kaikki heidän maansa esikoiset, kaikki heidän miehuutensa ensimmäiset.'),
(1684611,58,19,105,37,'Sitten hän vei Israelin sieltä varustettuna hopealla ja kullalla, eikä ollut hänen sukukunnissaan kompastuvaista.'),
(1684612,58,19,105,38,'Egypti iloitsi heidän lähdöstänsä, koska sen oli vallannut pelko heidän tähtensä.'),
(1684613,58,19,105,39,'Hän levitti suojaksi pilven ja tulen valaisemaan yötä.'),
(1684614,58,19,105,40,'He pyysivät, ja hän pani tulemaan viiriäiset, ja hän ravitsi heitä taivaan leivällä.'),
(1684615,58,19,105,41,'Hän avasi kallion, ja vettä vuoti; se juoksi virtana kautta erämaan.'),
(1684616,58,19,105,42,'Sillä hän muisti pyhän sanansa, muisti Aabrahamia, palvelijaansa.'),
(1684617,58,19,105,43,'Niin hän vei kansansa pois sen iloitessa, valittunsa heidän riemuitessaan.'),
(1684618,58,19,105,44,'Ja hän antoi heille pakanain maat, ja he ottivat omaksensa kansojen vaivannäöt,'),
(1684619,58,19,105,45,'että he noudattaisivat hänen käskyjänsä ja ottaisivat hänen laeistansa vaarin. Halleluja!'),
(1684620,58,19,106,1,'Halleluja! Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.'),
(1684621,58,19,106,2,'Kuka voi kertoa Herran voimalliset teot, julistaa kaiken hänen ylistyksensä?'),
(1684622,58,19,106,3,'Autuaat ne, jotka noudattavat oikeutta, jotka aina tekevät vanhurskauden!'),
(1684623,58,19,106,4,'Muista minua, Herra, armolla, jota kansallesi osoitat, etsi minua avullasi,'),
(1684624,58,19,106,5,'että minä näkisin sinun valittujesi onnen, iloitsisin sinun kansasi ilolla, kerskaisin sinun perintöosasi kanssa.'),
(1684625,58,19,106,6,'Me olemme tehneet syntiä isäimme kanssa, me olemme pahoin tehneet ja olleet jumalattomat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684626,58,19,106,7,'Eivät meidän isämme Egyptissä painaneet mieleensä sinun ihmeitäsi, eivät muistaneet sinun monia armotekojasi, vaan niskoittelivat meren rannalla, Kaislameren rannalla.'),
(1684627,58,19,106,8,'Kuitenkin hän pelasti heidät nimensä tähden, tehdäkseen voimansa tiettäväksi.'),
(1684628,58,19,106,9,'Hän nuhteli Kaislamerta, ja se kuivui. Hän kuljetti heitä syvyyksissä niinkuin erämaassa.'),
(1684629,58,19,106,10,'Hän pelasti heidät vihamiehen kädestä ja lunasti heidät vihollisen vallasta.'),
(1684630,58,19,106,11,'Vedet peittivät heidän ahdistajansa, ei yhtäkään niistä jäänyt jäljelle.'),
(1684631,58,19,106,12,'Silloin he uskoivat hänen sanansa, veisasivat hänen ylistystään.'),
(1684632,58,19,106,13,'Mutta pian he unhottivat hänen tekonsa eivätkä odottaneet hänen neuvoansa.'),
(1684633,58,19,106,14,'Heissä syttyi himo erämaassa, ja he kiusasivat Jumalaa autiossa maassa.'),
(1684634,58,19,106,15,'Ja hän antoi heille, mitä he pyysivät, mutta lähetti heihin hivuttavan taudin.'),
(1684635,58,19,106,16,'Ja heissä syttyi leirissä kateus Moosesta vastaan ja Aaronia, Herran pyhää, vastaan.'),
(1684636,58,19,106,17,'Mutta maa aukeni ja nieli Daatanin ja peitti Abiramin joukkion.'),
(1684637,58,19,106,18,'Ja heidän joukkiossaan syttyi tuli, liekki poltti jumalattomat.'),
(1684638,58,19,106,19,'He tekivät vasikan Hoorebin juurella ja kumarsivat valettua kuvaa;'),
(1684639,58,19,106,20,'he vaihtoivat Kunniansa ruohoa syövän härän kuvaan.'),
(1684640,58,19,106,21,'He unhottivat Jumalan, pelastajansa, joka oli tehnyt Egyptissä suuria tekoja,'),
(1684641,58,19,106,22,'ihmeitä Haamin maassa, peljättäviä tekoja Kaislameren rannalla.'),
(1684642,58,19,106,23,'Silloin hän aikoi hävittää heidät, mutta Mooses, hänen valittunsa, seisoi suojana hänen edessään ja käänsi pois hänen vihansa tuhoa tuottamasta.'),
(1684643,58,19,106,24,'He pitivät halpana ihanan maan eivätkä uskoneet hänen sanaansa.'),
(1684644,58,19,106,25,'He napisivat teltoissansa eivätkä kuulleet Herran ääntä.'),
(1684645,58,19,106,26,'Silloin hän nosti kätensä heitä vastaan kaataakseen heidät erämaassa,'),
(1684646,58,19,106,27,'kaataakseen heidän jälkeläisensä pakanain seassa ja hajottaakseen heidät pakanamaihin.'),
(1684647,58,19,106,28,'He antautuivat palvelemaan Baal-Peoria ja söivät kuolleitten jumalien uhreja.'),
(1684648,58,19,106,29,'He vihoittivat hänet teoillansa, ja niin vitsaus alkoi riehua heidän keskuudessaan.'),
(1684649,58,19,106,30,'Mutta Piinehas astui esiin ja pani tuomion toimeen, ja vitsaus taukosi.'),
(1684650,58,19,106,31,'Ja se luettiin hänelle vanhurskaudeksi, polvesta polveen, iankaikkisesti.'),
(1684651,58,19,106,32,'He vihoittivat hänet Meriban vetten luona, ja Mooseksen kävi pahoin heidän tähtensä.'),
(1684652,58,19,106,33,'Sillä he niskoittelivat Jumalan Henkeä vastaan, ja hän puhui huulillaan ajattelemattomasti.'),
(1684653,58,19,106,34,'He eivät hävittäneet niitä kansoja, jotka Herra oli käskenyt heidän hävittää,'),
(1684654,58,19,106,35,'vaan pitivät yhteyttä pakanain kanssa ja oppivat heidän tekonsa.'),
(1684655,58,19,106,36,'He palvelivat heidän jumalankuviansa, ja niistä tuli heille paula.'),
(1684656,58,19,106,37,'Ja he uhrasivat poikiansa ja tyttäriänsä riivaajille.'),
(1684657,58,19,106,38,'He vuodattivat viatonta verta, poikiensa ja tyttäriensä verta, uhraten heidät Kanaanin epäjumalille, ja maa saastui veriveloista.'),
(1684658,58,19,106,39,'Näin he saastuttivat itsensä töillään ja olivat haureelliset teoissansa.'),
(1684659,58,19,106,40,'Ja Herran viha syttyi hänen kansaansa vastaan, ja hän kyllästyi perintöosaansa.'),
(1684660,58,19,106,41,'Ja hän jätti heidät pakanain käsiin, ja heidän vihamiehensä vallitsivat heitä.'),
(1684661,58,19,106,42,'Heidän vihollisensa ahdistivat heitä, ja heidän täytyi painua niiden käden alle.'),
(1684662,58,19,106,43,'Monet kerrat hän pelasti heidät, mutta he olivat uppiniskaiset omassa neuvossaan ja sortuivat pahain tekojensa tähden.'),
(1684663,58,19,106,44,'Mutta hän katsoi heihin heidän ahdistuksessaan, kun hän kuuli heidän valitushuutonsa.'),
(1684664,58,19,106,45,'Ja hän muisti heidän hyväkseen liittonsa ja armahti heitä suuressa laupeudessansa.'),
(1684665,58,19,106,46,'Ja hän salli heidän saada armon kaikilta, jotka olivat vieneet heidät vankeuteen.'),
(1684666,58,19,106,47,'Pelasta meidät, Herra, meidän Jumalamme, ja kokoa meidät pakanain seasta, että me kiittäisimme sinun pyhää nimeäsi ja kerskauksemme olisi, että me sinua ylistämme.'),
(1684667,58,19,106,48,'Kiitetty olkoon Herra, Israelin Jumala, iankaikkisesta iankaikkiseen. Ja kaikki kansa sanokoon: "Amen. Halleluja!"'),
(1684668,58,19,107,1,'Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.'),
(1684669,58,19,107,2,'Niin sanokoot Herran lunastetut, jotka hän on lunastanut ahdistuksen alta'),
(1684670,58,19,107,3,'ja koonnut pakanamaista, idästä ja lännestä, pohjoisesta ja meren puolelta.'),
(1684671,58,19,107,4,'He harhailivat erämaassa, autiossa, tiettömässä maassa, löytämättä asuttua kaupunkia.'),
(1684672,58,19,107,5,'Heidän oli nälkä ja jano, heidän sielunsa nääntyi heissä.'),
(1684673,58,19,107,6,'Mutta hädässänsä he huusivat Herraa, ja hän pelasti heidät heidän ahdistuksistaan.'),
(1684674,58,19,107,7,'Ja hän ohjasi heidät oikealle tielle, niin että he pääsivät asuttuun kaupunkiin.'),
(1684675,58,19,107,8,'Kiittäkööt he Herraa hänen armostansa, hänen ihmeellisistä teoistaan ihmislapsia kohtaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684676,58,19,107,9,'Sillä hän ravitsee nääntyvän sielun ja täyttää nälkäisen sielun hyvyydellä.'),
(1684677,58,19,107,10,'He istuivat pimeydessä ja synkeydessä, vangittuina kurjuuteen ja rautoihin,'),
(1684678,58,19,107,11,'koska olivat niskoitelleet Jumalan käskyjä vastaan ja katsoneet halvaksi Korkeimman neuvon.'),
(1684679,58,19,107,12,'Hän masensi heidän sydämensä kärsimyksellä; he sortuivat, eikä ollut auttajaa.'),
(1684680,58,19,107,13,'Mutta hädässänsä he huusivat Herraa, ja hän pelasti heidät heidän ahdistuksistaan.'),
(1684681,58,19,107,14,'Hän vei heidät ulos pimeydestä ja synkeydestä, hän katkaisi heidän kahleensa.'),
(1684682,58,19,107,15,'Kiittäkööt he Herraa hänen armostansa ja hänen ihmeellisistä teoistaan ihmislapsia kohtaan.'),
(1684683,58,19,107,16,'Sillä hän särkee vaskiset ovet ja rikkoo rautaiset salvat.'),
(1684684,58,19,107,17,'He olivat hulluja, sillä heidän vaelluksensa oli syntinen, ja he kärsivät vaivaa pahojen tekojensa tähden.'),
(1684685,58,19,107,18,'Heidän sielunsa inhosi kaikkea ruokaa, ja he olivat lähellä kuoleman portteja.'),
(1684686,58,19,107,19,'Mutta hädässänsä he huusivat Herraa, ja hän pelasti heidät heidän ahdistuksistaan.'),
(1684687,58,19,107,20,'Hän lähetti sanansa ja paransi heidät ja pelasti heidät haudasta.'),
(1684688,58,19,107,21,'Kiittäkööt he Herraa hänen armostansa ja hänen ihmeellisistä teoistaan ihmislapsia kohtaan.'),
(1684689,58,19,107,22,'Uhratkoot kiitosuhreja ja kertokoot riemuiten hänen töitään.'),
(1684690,58,19,107,23,'He lähtivät laivoilla merelle ja kävivät kauppaa suurilla vesillä.'),
(1684691,58,19,107,24,'He näkivät Herran työt ja hänen ihmeelliset tekonsa meren syvyyksissä.'),
(1684692,58,19,107,25,'Hän sanoi sanansa ja nosti myrskytuulen, joka kohotti korkealle sen aallot.'),
(1684693,58,19,107,26,'He kohosivat taivasta kohti, he vajosivat syvyyksiin; heidän sielunsa menehtyi tuskasta.'),
(1684694,58,19,107,27,'He horjuivat ja hoippuivat kuin juopunut, ja kaikki heidän taitonsa hämmentyi.'),
(1684695,58,19,107,28,'Mutta hädässänsä he huusivat Herraa, ja hän päästi heidät heidän ahdistuksistaan.'),
(1684696,58,19,107,29,'Hän tyynnytti myrskyn, ja meren aallot hiljenivät.'),
(1684697,58,19,107,30,'He iloitsivat, kun tuli tyyni, ja hän vei heidät toivottuun satamaan.'),
(1684698,58,19,107,31,'Kiittäkööt he Herraa hänen armostansa ja hänen ihmeellisistä teoistaan ihmislapsia kohtaan.'),
(1684699,58,19,107,32,'Kunnioittakoot häntä kansan seurakunnassa ja vanhinten kokouksessa häntä ylistäkööt.'),
(1684700,58,19,107,33,'Hän muutti virrat erämaaksi ja vesilähteet kuivaksi maaksi,'),
(1684701,58,19,107,34,'hedelmällisen maan suola-aroksi, sen asukasten pahuuden tähden.'),
(1684702,58,19,107,35,'Hän muutti erämaan vesilammikoiksi ja kuivan maan vesilähteiksi.'),
(1684703,58,19,107,36,'Ja hän asetti nälkäiset sinne asumaan ja he rakensivat kaupungin asuaksensa.'),
(1684704,58,19,107,37,'Ja he kylvivät peltoja ja istuttivat viinitarhoja, jotka tuottivat satoisan hedelmän.'),
(1684705,58,19,107,38,'Hän siunasi heitä, ja he lisääntyivät suuresti, ja hän antoi heille paljon karjaa.'),
(1684706,58,19,107,39,'Ja kun he vähentyivät ja vaipuivat onnettomuuden ja huolten painon alla,'),
(1684707,58,19,107,40,'niin hän, joka vuodattaa ylenkatsetta ruhtinasten päälle ja panee heidät harhailemaan tiettömissä autiomaissa,'),
(1684708,58,19,107,41,'hän kohotti köyhän kurjuudesta ja teki suvut suuriksi kuin lammaslaumat.'),
(1684709,58,19,107,42,'Oikeamieliset näkevät sen ja riemuitsevat, ja kaiken vääryyden täytyy tukkia suunsa.'),
(1684710,58,19,107,43,'Joka viisas on, se ottakoon näistä vaarin ja ajatelkoon Herran armotekoja.'),
(1684711,58,19,108,1,'Laulu; Daavidin virsi.'),
(1684712,58,19,108,2,'Minun sydämeni on valmis, Jumala, minä tahdon veisata ja soittaa; valmis on minun sieluni.'),
(1684713,58,19,108,3,'Heräjä, harppu ja kannel. Minä tahdon herättää aamuruskon.'),
(1684714,58,19,108,4,'Herra, sinua minä kiitän kansojen joukossa ja veisaan sinun kiitostasi kansakuntien keskellä.'),
(1684715,58,19,108,5,'Sillä suuri on sinun armosi ja ulottuu ylitse taivasten ja sinun totuutesi hamaan pilviin asti.'),
(1684716,58,19,108,6,'Korota itsesi yli taivasten, Jumala, ja levitköön sinun kunniasi yli kaiken maan.'),
(1684717,58,19,108,7,'Että sinun rakkaasi pelastetuiksi tulisivat, auta oikealla kädelläsi ja vastaa minulle.'),
(1684718,58,19,108,8,'Jumala on puhunut pyhäkössänsä. Minä riemuitsen, minä jaan Sikemin ja mittaan Sukkotin laakson.'),
(1684719,58,19,108,9,'Minun on Gilead, ja minun on Manasse; Efraim on minun pääni suojus, Juuda minun valtikkani.'),
(1684720,58,19,108,10,'Mooab on minun pesuastiani, Edomiin minä viskaan kenkäni, minä riemuitsen Filistean maasta.'),
(1684721,58,19,108,11,'Kuka vie minut varustettuun kaupunkiin? Kuka saattaa minut Edomiin?'),
(1684722,58,19,108,12,'Etkö sinä, Jumala, hyljännyt meitä? Et lähtenyt, Jumala, meidän sotajoukkojemme kanssa!'),
(1684723,58,19,108,13,'Anna meille apu ahdistajaa vastaan, sillä turha on ihmisten apu.'),
(1684724,58,19,108,14,'Jumalan voimalla me teemme väkeviä tekoja; hän tallaa meidän vihollisemme maahan.'),
(1684725,58,19,109,1,'Veisuunjohtajalle; Daavidin virsi. Jumala, minun ylistykseni, älä ole vaiti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684726,58,19,109,2,'Sillä he ovat avanneet minua vastaan jumalattoman ja petollisen suun, he puhuttelevat minua valheen kielellä.'),
(1684727,58,19,109,3,'Vihan sanoilla he ovat minut piirittäneet, ja syyttä he sotivat minua vastaan.'),
(1684728,58,19,109,4,'Rakkauteni palkaksi he minua vainoavat, mutta minä ainoastaan rukoilen.'),
(1684729,58,19,109,5,'He kostavat minulle hyvän pahalla ja rakkauteni vihalla.'),
(1684730,58,19,109,6,'Aseta jumalaton mies häntä vastaan, ja seisokoon syyttäjä hänen oikealla puolellansa.'),
(1684731,58,19,109,7,'Oikeuden edessä hän joutukoon syyhyn, ja hänen rukouksensa tulkoon synniksi.'),
(1684732,58,19,109,8,'Hänen päivänsä olkoot harvat, ottakoon toinen hänen kaitsijatoimensa.'),
(1684733,58,19,109,9,'Tulkoot hänen lapsensa orvoiksi ja hänen vaimonsa leskeksi.'),
(1684734,58,19,109,10,'Kierrelkööt hänen lapsensa alati kerjäten, anelkoot kaukana kotinsa raunioilta.'),
(1684735,58,19,109,11,'Anastakoon koronkiskuri kaiken hänen omansa, ja riistäkööt vieraat hänen vaivannäkönsä.'),
(1684736,58,19,109,12,'Älköön kukaan osoittako hänelle laupeutta, älköönkä kukaan armahtako hänen orpojansa.'),
(1684737,58,19,109,13,'Hänen jälkeläisensä hävitkööt sukupuuttoon, pyyhittäköön heidän nimensä pois toisessa polvessa.'),
(1684738,58,19,109,14,'Hänen isiensä rikkomukset pysykööt Herran muistossa, älköönkä hänen äitinsä syntiä pyyhittäkö pois.'),
(1684739,58,19,109,15,'Olkoot ne Herran edessä alati, ja hävittäköön hän heidän muistonsa maan päältä.'),
(1684740,58,19,109,16,'Sillä se mies ei ajatellutkaan tehdä laupeutta, vaan vainosi kurjaa ja köyhää ja sydämen tuskassa olevaa, tappaaksensa hänet.'),
(1684741,58,19,109,17,'Hän rakasti kirousta, ja se kohtasi häntä; hän ei huolinut siunauksesta, ja se väistyi hänestä kauas.'),
(1684742,58,19,109,18,'Hän puki kirouksen yllensä niinkuin vaatteensa, ja se meni hänen sisuksiinsa niinkuin vesi ja hänen luihinsa niinkuin öljy.'),
(1684743,58,19,109,19,'Se olkoon hänellä viittana, johon hän verhoutuu, ja vyönä, johon hän aina vyöttäytyy.'),
(1684744,58,19,109,20,'Tämä olkoon Herralta minun vainoojaini palkka ja niiden, jotka puhuvat pahaa minua vastaan.'),
(1684745,58,19,109,21,'Mutta sinä, Herra, Herra, auta minua nimesi tähden, sillä sinun armosi on hyvä, pelasta minut.'),
(1684746,58,19,109,22,'Sillä minä olen kurja ja köyhä, ja sydämeni on haavoitettu minun rinnassani.'),
(1684747,58,19,109,23,'Minä katoan pois kuin pitenevä varjo, minut pudistetaan pois kuin heinäsirkka.'),
(1684748,58,19,109,24,'Polveni horjuvat paastoamisesta, ja minun ruumiini on laihtunut lihattomaksi.'),
(1684749,58,19,109,25,'Ja minä olen joutunut heidän herjattavakseen, minut nähdessään he nyökyttävät päätänsä.'),
(1684750,58,19,109,26,'Auta minua, Herra, minun Jumalani, pelasta minut armosi jälkeen;'),
(1684751,58,19,109,27,'ja he saakoot tuta, että tämä on sinun kätesi, että sinä, Herra, sen teit.'),
(1684752,58,19,109,28,'Jos he kiroavat, siunaa sinä, jos he nousevat, joutukoot häpeään, mutta palvelijasi saakoon iloita.'),
(1684753,58,19,109,29,'Olkoon häväistys minun vainoojaini pukuna, ja verhotkoon heitä heidän häpeänsä niinkuin viitta.'),
(1684754,58,19,109,30,'Minä suullani kiitän suuresti Herraa, ja monien keskellä minä ylistän häntä.'),
(1684755,58,19,109,31,'Sillä hän seisoo köyhän oikealla puolella pelastaakseen hänet niistä, jotka hänet tuomitsevat.'),
(1684756,58,19,110,1,'Daavidin virsi. Herra sanoi minun herralleni: "Istu minun oikealle puolelleni, kunnes minä panen sinun vihollisesi sinun jalkojesi astinlaudaksi".'),
(1684757,58,19,110,2,'Herra ojentaa sinun valtasi valtikan Siionista; hallitse vihollistesi keskellä.'),
(1684758,58,19,110,3,'Altis on sinun kansasi sinun sotaanlähtösi päivänä: pyhässä asussa sinun nuori väkesi nousee eteesi, niinkuin kaste aamuruskon helmasta.'),
(1684759,58,19,110,4,'Herra on vannonut eikä sitä kadu: "Sinä olet pappi iankaikkisesti, Melkisedekin järjestyksen mukaan".'),
(1684760,58,19,110,5,'Herra on sinun oikealla puolellasi, hän musertaa kuninkaat vihansa päivänä.'),
(1684761,58,19,110,6,'Hän tuomitsee pakanat: ruumiita viruu kaikkialla; hän murskaa päitä laajalti maan päällä.'),
(1684762,58,19,110,7,'Hän juo purosta tien varrelta; sentähden hän kohottaa päänsä.'),
(1684763,58,19,111,1,'Halleluja! Minä kiitän Herraa kaikesta sydämestäni hurskasten kokouksessa ja seurakunnassa.'),
(1684764,58,19,111,2,'Suuret ovat Herran teot, kaikkien niiden tutkisteltavat, jotka niitä rakastavat.'),
(1684765,58,19,111,3,'Kunnialliset ja korkeat ovat hänen työnsä, ja hänen vanhurskautensa pysyy iankaikkisesti.'),
(1684766,58,19,111,4,'Hän on säätänyt ihmeellisten tekojensa muiston; armollinen ja laupias on Herra.'),
(1684767,58,19,111,5,'Hän antaa ruuan pelkääväisillensä, hän muistaa liittonsa iankaikkisesti.'),
(1684768,58,19,111,6,'Hän ilmoitti kansallensa tekojensa voiman, hän antoi heille pakanain perintöosan.'),
(1684769,58,19,111,7,'Hänen kättensä teot ovat totiset ja oikeat; luotettavat ovat kaikki hänen asetuksensa.'),
(1684770,58,19,111,8,'Ne pysyvät järkkymättä aina ja iankaikkisesti; ne ovat tehdyt totuudessa ja oikeudessa.'),
(1684771,58,19,111,9,'Hän lähetti kansallensa lunastuksen, sääti liittonsa ikuisiksi ajoiksi; pyhä ja peljättävä on hänen nimensä.'),
(1684772,58,19,111,10,'Herran pelko on viisauden alku, hyvä ymmärrys kaikille, jotka sitä noudattavat. Hänen ylistyksensä pysyy iankaikkisesti.'),
(1684773,58,19,112,1,'Halleluja! Autuas se mies, joka Herraa pelkää ja suuresti halajaa hänen käskyjänsä!'),
(1684774,58,19,112,2,'Hänen jälkeläisensä tulevat voimallisiksi maassa, oikeamielisten suku tulee siunatuksi.'),
(1684775,58,19,112,3,'Varallisuus ja rikkaus on hänen huoneessansa, ja hänen vanhurskautensa pysyy iankaikkisesti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684776,58,19,112,4,'Oikeamielisille koittaa pimeydessä valkeus, armollinen, laupias ja vanhurskas.'),
(1684777,58,19,112,5,'Hyvin käy sen miehen, joka on laupias ja antaa lainaksi, joka hoitaa asiansa oikeuden mukaan.'),
(1684778,58,19,112,6,'Sillä ei hän ikinä horju; vanhurskas säilyy ikuisessa muistossa.'),
(1684779,58,19,112,7,'Ei hän pelkää pahaa sanomaa, hänen sydämensä on vahva, sillä hän turvaa Herraan.'),
(1684780,58,19,112,8,'Hänen sydämensä on luja ja peloton, kunnes hän vihdoin ilolla katselee ahdistajiaan.'),
(1684781,58,19,112,9,'Hän on runsaskätinen, hän antaa köyhille, hänen vanhurskautensa pysyy iankaikkisesti, hänen sarvensa kohoaa kunniassa.'),
(1684782,58,19,112,10,'Jumalaton näkee sen ja närkästyy, hän kiristelee hampaitaan ja pakahtuu. Jumalattomien halut raukeavat tyhjiin.'),
(1684783,58,19,113,1,'Halleluja! Ylistäkää, te Herran palvelijat, ylistäkää Herran nimeä.'),
(1684784,58,19,113,2,'Siunattu olkoon Herran nimi nyt ja iankaikkisesti.'),
(1684785,58,19,113,3,'Auringon noususta sen laskuun saakka olkoon Herran nimi ylistetty.'),
(1684786,58,19,113,4,'Herra on korkea yli kaikkien pakanakansain, yli taivasten kohoaa hänen kunniansa.'),
(1684787,58,19,113,5,'Kuka on niinkuin Herra, meidän Jumalamme, joka korkealla asuu'),
(1684788,58,19,113,6,'ja katsoo syvälle - taivaassa ja maassa?'),
(1684789,58,19,113,7,'Hän, joka tomusta nostaa alhaisen, korottaa loasta köyhän'),
(1684790,58,19,113,8,'asettaaksensa hänet ruhtinasten rinnalle, hänen kansansa ruhtinasten rinnalle,'),
(1684791,58,19,113,9,'joka antaa hedelmättömän asua kodissa, iloisena lasten äitinä! Halleluja!'),
(1684792,58,19,114,1,'Kun Israel lähti Egyptistä, Jaakobin suku vieraskielisestä kansasta,'),
(1684793,58,19,114,2,'silloin Juuda tuli hänen pyhäkökseen, Israel hänen valtakunnaksensa.'),
(1684794,58,19,114,3,'Sen näki meri ja pakeni, Jordan kääntyi takaisin.'),
(1684795,58,19,114,4,'Vuoret hyppivät niinkuin oinaat, kukkulat niinkuin lammasten karitsat.'),
(1684796,58,19,114,5,'Mikä sinun on, meri, kun pakenet, mikä sinun, Jordan, kun käännyt takaisin?'),
(1684797,58,19,114,6,'Te vuoret, miksi hypitte kuin oinaat, te kukkulat, kuin lammasten karitsat?'),
(1684798,58,19,114,7,'Vapise, maa, Herran kasvojen edessä, Jaakobin Jumalan kasvojen edessä,'),
(1684799,58,19,114,8,'joka muuttaa kallion vesilammikoksi, kovan kiven vesilähteeksi.'),
(1684800,58,19,115,1,'Älä meille, Herra, älä meille, vaan omalle nimellesi anna kunnia armosi ja totuutesi tähden.'),
(1684801,58,19,115,2,'Miksi pakanat saisivat sanoa: "Missä on heidän Jumalansa?"'),
(1684802,58,19,115,3,'Meidän Jumalamme on taivaissa; mitä ikinä hän tahtoo, sen hän tekee.'),
(1684803,58,19,115,4,'Mutta heidän epäjumalansa ovat hopeata ja kultaa, ihmiskätten tekoa.'),
(1684804,58,19,115,5,'Niillä on suu, mutta eivät ne puhu, niillä on silmät, mutta eivät näe.'),
(1684805,58,19,115,6,'Niillä on korvat, mutta eivät kuule, niillä on nenä, mutta eivät hajua tunne.'),
(1684806,58,19,115,7,'Niiden kädet eivät koske, niiden jalat eivät astu, ei tule ääntä niiden kurkusta.'),
(1684807,58,19,115,8,'Niiden kaltaisia ovat niiden tekijät ja kaikki, jotka turvaavat niihin.'),
(1684808,58,19,115,9,'Israel, turvaa Herraan - hän on heidän apunsa ja kilpensä.'),
(1684809,58,19,115,10,'Te, Aaronin suku, turvatkaa Herraan - hän on heidän apunsa ja kilpensä.'),
(1684810,58,19,115,11,'Te, Herraa pelkääväiset, turvatkaa Herraan - hän on heidän apunsa ja kilpensä.'),
(1684811,58,19,115,12,'Herra muistaa meitä ja siunaa, hän siunaa Israelin sukua, hän siunaa Aaronin sukua,'),
(1684812,58,19,115,13,'hän siunaa niitä, jotka Herraa pelkäävät, niin pieniä kuin suuriakin.'),
(1684813,58,19,115,14,'Herra lisätköön teitä, sekä teitä että teidän lapsianne.'),
(1684814,58,19,115,15,'Te olette Herran siunatut, hänen, joka on tehnyt taivaan ja maan.'),
(1684815,58,19,115,16,'Taivas on Herran taivas, mutta maan hän on antanut ihmisten lapsille.'),
(1684816,58,19,115,17,'Eivät kuolleet ylistä Herraa, ei kukaan hiljaisuuteen astuneista.'),
(1684817,58,19,115,18,'Mutta me, me kiitämme Herraa, nyt ja iankaikkisesti. Halleluja!'),
(1684818,58,19,116,1,'Minä rakastan Herraa, sillä hän kuulee minun ääneni ja rukoukseni;'),
(1684819,58,19,116,2,'sillä hän on kallistanut korvansa minun puoleeni, ja minä huudan häntä avuksi kaiken elinaikani.'),
(1684820,58,19,116,3,'Kuoleman paulat piirittivät minut, tuonelan ahdistukset kohtasivat minua; minä jouduin hätään ja murheeseen.'),
(1684821,58,19,116,4,'Mutta minä huusin avukseni Herran nimeä: "Oi Herra, pelasta minun sieluni!"'),
(1684822,58,19,116,5,'Herra on armollinen ja vanhurskas, meidän Jumalamme on laupias.'),
(1684823,58,19,116,6,'Herra varjelee yksinkertaiset; minä olin viheliäinen, mutta hän auttoi minua.'),
(1684824,58,19,116,7,'Palaja, sieluni, takaisin lepoosi, sillä Herra on tehnyt sinulle hyvin.'),
(1684825,58,19,116,8,'Sillä sinä olet pelastanut minun sieluni kuolemasta, minun silmäni kyynelistä, jalkani kompastumasta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684826,58,19,116,9,'Minä saan vaeltaa Herran kasvojen edessä elävien maassa.'),
(1684827,58,19,116,10,'Minä uskon, sentähden minä puhun, minä, joka olin kovin vaivattu.'),
(1684828,58,19,116,11,'Minä sanoin hädässäni: "Kaikki ihmiset ovat valhettelijoita".'),
(1684829,58,19,116,12,'Kuinka minä maksan Herralle kaikki hänen hyvät tekonsa minua kohtaan?'),
(1684830,58,19,116,13,'Minä kohotan pelastuksen maljan ja huudan avukseni Herran nimeä.'),
(1684831,58,19,116,14,'Minä täytän lupaukseni Herralle kaiken hänen kansansa edessä.'),
(1684832,58,19,116,15,'Kallis on Herran silmissä hänen hurskaittensa kuolema.'),
(1684833,58,19,116,16,'Oi Herra, minä olen sinun palvelijasi, sinun palvelijasi minä olen, sinun palvelijattaresi poika! Sinä päästit minun siteeni.'),
(1684834,58,19,116,17,'Sinulle minä uhraan kiitosuhrin ja huudan avukseni Herran nimeä.'),
(1684835,58,19,116,18,'Minä täytän lupaukseni Herralle kaiken hänen kansansa edessä'),
(1684836,58,19,116,19,'Herran huoneen esikartanoissa, sinun keskelläsi, Jerusalem. Halleluja!'),
(1684837,58,19,117,1,'Kiittäkää Herraa, kaikki pakanat, ylistäkää häntä, kaikki kansat.'),
(1684838,58,19,117,2,'Sillä hänen armonsa meitä kohtaan on voimallinen, ja Herran uskollisuus pysyy iankaikkisesti. Halleluja!'),
(1684839,58,19,118,1,'Kiittäkää Herraa, sillä hän on hyvä; sillä hänen armonsa pysyy iankaikkisesti.'),
(1684840,58,19,118,2,'Näin sanokoon Israel; sillä hänen armonsa pysyy iankaikkisesti.'),
(1684841,58,19,118,3,'Näin sanokoon Aaronin suku; sillä hänen armonsa pysyy iankaikkisesti.'),
(1684842,58,19,118,4,'Näin sanokoot ne, jotka Herraa pelkäävät; sillä hänen armonsa pysyy iankaikkisesti.'),
(1684843,58,19,118,5,'Ahdistuksessani minä huusin Herraa, Herra vastasi minulle ja asetti minut avaraan paikkaan.'),
(1684844,58,19,118,6,'Herra on minun puolellani, en minä pelkää; mitä voivat ihmiset minulle tehdä?'),
(1684845,58,19,118,7,'Herra on minun puolellani ja auttaa minua, ja minä saan ilolla katsella vihamiehiäni.'),
(1684846,58,19,118,8,'Parempi on luottaa Herraan, kuin turvata ihmisiin.'),
(1684847,58,19,118,9,'Parempi on luottaa Herraan, kuin turvata ruhtinaihin.'),
(1684848,58,19,118,10,'Kaikki pakanat piirittivät minua - Herran nimessä minä lyön heidät maahan.'),
(1684849,58,19,118,11,'He piirittivät minua joka taholta - Herran nimessä minä lyön heidät maahan.'),
(1684850,58,19,118,12,'Niinkuin mehiläiset he minua piirittivät - he sammuvat kuin tuli orjantappuroissa. Herran nimessä minä lyön heidät maahan.'),
(1684851,58,19,118,13,'Sinä sysäsit minua kovasti, että kaatuisin, mutta Herra auttoi minua.'),
(1684852,58,19,118,14,'Herra on minun väkevyyteni ja ylistysvirteni, ja hän tuli minulle pelastajaksi.'),
(1684853,58,19,118,15,'Riemun ja pelastuksen huuto kuuluu vanhurskaitten majoissa: Herran oikea käsi tekee väkeviä tekoja.'),
(1684854,58,19,118,16,'Herran oikea käsi korottaa, Herran oikea käsi tekee väkeviä tekoja.'),
(1684855,58,19,118,17,'En minä kuole, vaan elän ja julistan Herran töitä.'),
(1684856,58,19,118,18,'Herra minua kyllä kuritti, mutta kuolemalle hän ei minua antanut.'),
(1684857,58,19,118,19,'Avatkaa minulle vanhurskauden portit, käydäkseni niistä sisälle kiittämään Herraa.'),
(1684858,58,19,118,20,'Tämä on Herran portti: vanhurskaat käyvät siitä sisälle.'),
(1684859,58,19,118,21,'Minä kiitän sinua siitä, että vastasit minulle ja tulit minulle pelastajaksi.'),
(1684860,58,19,118,22,'Se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi.'),
(1684861,58,19,118,23,'Herralta tämä on tullut; se on ihmeellistä meidän silmissämme.'),
(1684862,58,19,118,24,'Tämä on se päivä, jonka Herra on tehnyt; riemuitkaamme ja iloitkaamme siitä.'),
(1684863,58,19,118,25,'Oi Herra, auta, oi Herra, anna menestys!'),
(1684864,58,19,118,26,'Siunattu olkoon hän, joka tulee Herran nimeen; me siunaamme teitä Herran huoneesta.'),
(1684865,58,19,118,27,'Herra on Jumala, ja hän antoi valon meille loistaa. Sitokaa juhlauhrit köysillä alttarin sarviin asti.'),
(1684866,58,19,118,28,'Sinä olet minun Jumalani, ja sinua minä kiitän. Minun Jumalani, sinua minä kunnioitan.'),
(1684867,58,19,118,29,'Kiittäkää Herraa, sillä hän on hyvä; sillä hänen armonsa pysyy iankaikkisesti.'),
(1684868,58,19,119,1,'Autuaat ne, joiden tie on nuhteeton, jotka Herran laissa vaeltavat!'),
(1684869,58,19,119,2,'Autuaat ne, jotka ottavat vaarin hänen todistuksistaan, jotka etsivät häntä kaikesta sydämestänsä,'),
(1684870,58,19,119,3,'jotka eivät vääryyttä tee, vaan vaeltavat hänen teillään!'),
(1684871,58,19,119,4,'Sinä olet asetuksesi säätänyt, että niitä tarkasti noudatettaisiin.'),
(1684872,58,19,119,5,'Oi, jospa minun vaellukseni olisi vakaa, niin että noudattaisin sinun käskyjäsi!'),
(1684873,58,19,119,6,'Silloin minä en joudu häpeään, kun katselen kaikkia sinun käskyjäsi.'),
(1684874,58,19,119,7,'Minä kiitän sinua vilpittömällä sydämellä, kun opin sinun vanhurskautesi oikeudet.'),
(1684875,58,19,119,8,'Minä noudatan sinun käskyjäsi, älä minua peräti hylkää.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684876,58,19,119,9,'Kuinka voi nuorukainen pitää tiensä puhtaana? Siten, että hän noudattaa sinun sanaasi.'),
(1684877,58,19,119,10,'Minä etsin sinua kaikesta sydämestäni, älä salli minun eksyä pois sinun käskyistäsi.'),
(1684878,58,19,119,11,'Minä kätken sinun sanasi sydämeeni, etten tekisi syntiä sinua vastaan.'),
(1684879,58,19,119,12,'Kiitetty ole sinä, Herra, opeta minulle käskysi.'),
(1684880,58,19,119,13,'Huulillani minä julistan kaikki sinun suusi oikeudet.'),
(1684881,58,19,119,14,'Minä iloitsen sinun todistustesi tiestä, niinkuin kaikkinaisesta rikkaudesta.'),
(1684882,58,19,119,15,'Minä tutkistelen sinun asetuksiasi ja katselen sinun polkujasi.'),
(1684883,58,19,119,16,'Minä iloitsen sinun käskyistäsi enkä sinun sanaasi unhota.'),
(1684884,58,19,119,17,'Tee palvelijallesi hyvin, että minä eläisin ja noudattaisin sinun sanaasi.'),
(1684885,58,19,119,18,'Avaa minun silmäni näkemään sinun lakisi ihmeitä.'),
(1684886,58,19,119,19,'Minä olen muukalainen maan päällä; älä salaa minulta käskyjäsi.'),
(1684887,58,19,119,20,'Minun sieluni hiukeaa ikävöidessäni alati sinun oikeuksiasi.'),
(1684888,58,19,119,21,'Sinä nuhtelet julkeita, kirotuita, jotka poikkeavat pois sinun käskyistäsi.'),
(1684889,58,19,119,22,'Poista minun päältäni häväistys ja ylenkatse, sillä minä otan sinun todistuksistasi vaarin.'),
(1684890,58,19,119,23,'Ruhtinaatkin istuvat ja pitävät neuvoa minua vastaan, mutta palvelijasi tutkistelee sinun käskyjäsi.'),
(1684891,58,19,119,24,'Sinun todistuksesi ovat minun iloni, ne ovat minun neuvonantajani.'),
(1684892,58,19,119,25,'Minun sieluni on vaipunut tomuun; virvoita minua sanasi jälkeen.'),
(1684893,58,19,119,26,'Minä kerron vaellukseni, ja sinä vastaat minulle; opeta minulle käskysi.'),
(1684894,58,19,119,27,'Saata minut ymmärtämään asetustesi tie, niin minä tutkistelen sinun ihmeitäsi.'),
(1684895,58,19,119,28,'Minun sieluni itkee murheesta; vahvista minua sanasi jälkeen.'),
(1684896,58,19,119,29,'Käännä minusta pois valheen tie, ja anna armostasi minulle lakisi.'),
(1684897,58,19,119,30,'Minä olen valinnut totuuden tien, olen asettanut eteeni sinun oikeutesi.'),
(1684898,58,19,119,31,'Minä riipun kiinni sinun todistuksissasi, Herra, älä anna minun joutua häpeään.'),
(1684899,58,19,119,32,'Minä juoksen sinun käskyjesi tietä, sillä sinä avarrat minun sydämeni.'),
(1684900,58,19,119,33,'Opeta minulle, Herra, käskyjesi tie, niin minä seuraan sitä loppuun asti.'),
(1684901,58,19,119,34,'Anna minulle ymmärrys ottaakseni sinun laistasi vaarin ja noudattaakseni sitä kaikesta sydämestäni.'),
(1684902,58,19,119,35,'Anna minun vaeltaa sinun käskyjesi polkua, sillä sitä minä halajan.'),
(1684903,58,19,119,36,'Anna minun sydämeni taipua sinun todistuksiisi, ei väärän voiton puoleen.'),
(1684904,58,19,119,37,'Käännä silmäni pois turhuutta katselemasta, anna minun saada virvoitus sinun teilläsi.'),
(1684905,58,19,119,38,'Anna palvelijallesi toteutua lupauksesi, joka on annettu sinua pelkääville.'),
(1684906,58,19,119,39,'Poista minusta häväistys, jota pelkään, sillä sinun oikeutesi ovat hyvät.'),
(1684907,58,19,119,40,'Katso, minä ikävöitsen sinun asetuksiasi; virvoita minua vanhurskaudellasi.'),
(1684908,58,19,119,41,'Tulkoon minulle sinun armosi, Herra, sinun apusi, sinun lupauksesi jälkeen,'),
(1684909,58,19,119,42,'että minä voisin vastata herjaajalleni; sillä sinun sanaasi minä turvaan.'),
(1684910,58,19,119,43,'Älä ota peräti pois minun suustani totuuden sanaa, sillä sinun oikeuteesi minä panen toivoni.'),
(1684911,58,19,119,44,'Minä tahdon alati noudattaa sinun lakiasi, aina ja iankaikkisesti.'),
(1684912,58,19,119,45,'Silloin minä vaellan avaralla paikalla; sillä sinun asetuksiasi minä kysyn.'),
(1684913,58,19,119,46,'Minä puhun sinun todistuksistasi kuningasten edessä, enkä häpeään joudu.'),
(1684914,58,19,119,47,'Minä iloitsen sinun käskyistäsi, jotka ovat minulle rakkaat.'),
(1684915,58,19,119,48,'Minä kohotan käteni sinun käskyjesi puoleen, jotka ovat minulle rakkaat, ja tutkistelen sinun säädöksiäsi.'),
(1684916,58,19,119,49,'Muista sana, jonka olet palvelijallesi puhunut, sillä sinä olet antanut minulle toivon.'),
(1684917,58,19,119,50,'Se on minun lohdutukseni kurjuudessani, että sinun lupauksesi minua virvoittaa.'),
(1684918,58,19,119,51,'Julkeat pilkkaavat minua kovin, mutta sinun laistasi minä en poikkea.'),
(1684919,58,19,119,52,'Herra, minä ajattelen sinun tuomioitasi, tuomioitasi hamasta ikiajoista asti, ja minä saan lohdutuksen.'),
(1684920,58,19,119,53,'Minut valtaa palava vihastus jumalattomien tähden, jotka hylkäävät sinun lakisi.'),
(1684921,58,19,119,54,'Sinun käskysi ovat minun ylistysvirteni minun muukalaisuuteni majassa.'),
(1684922,58,19,119,55,'Yöllä minä ajattelen sinun nimeäsi, Herra, ja minä noudatan sinun lakiasi.'),
(1684923,58,19,119,56,'Tämä on minun osakseni suotu: että otan vaarin sinun asetuksistasi.'),
(1684924,58,19,119,57,'Herra on minun osani; minä olen päättänyt noudattaa sinun sanojasi.'),
(1684925,58,19,119,58,'Minä etsin sinun mielisuosiotasi kaikesta sydämestäni; ole minulle armollinen lupauksesi mukaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684926,58,19,119,59,'Minä tutkin teitäni, ja käännän askeleeni sinun todistustesi puoleen.'),
(1684927,58,19,119,60,'Minä riennän viivyttelemättä noudattamaan sinun käskyjäsi.'),
(1684928,58,19,119,61,'Jumalattomain paulat piirittävät minua, mutta minä en unhota sinun lakiasi.'),
(1684929,58,19,119,62,'Puoliyöstä minä nousen kiittämään sinua sinun vanhurskautesi oikeuksista.'),
(1684930,58,19,119,63,'Minä olen kaikkien niiden ystävä, jotka sinua pelkäävät ja noudattavat sinun asetuksiasi.'),
(1684931,58,19,119,64,'Maa on täynnä sinun laupeuttasi, Herra; opeta minulle käskysi.'),
(1684932,58,19,119,65,'Sinä osoitat palvelijallesi hyvyyttä sanasi jälkeen, Herra.'),
(1684933,58,19,119,66,'Opeta minulle hyvä ymmärrys ja tieto, sillä sinun käskyihisi minä panen uskallukseni.'),
(1684934,58,19,119,67,'Ennenkuin minut nöyryytettiin, minä eksyin, mutta nyt minä noudatan sinun sanaasi.'),
(1684935,58,19,119,68,'Sinä olet hyvä, ja hyvin sinä teet; opeta minulle käskysi.'),
(1684936,58,19,119,69,'Julkeat tahraavat minua valheillansa, mutta minä otan sinun asetuksistasi vaarin kaikesta sydämestäni.'),
(1684937,58,19,119,70,'Heidän sydämensä on turta kuin ihra, mutta minä iloitsen sinun laistasi.'),
(1684938,58,19,119,71,'Hyvä oli minulle, että minut nöyryytettiin: niin minä opin sinun käskysi.'),
(1684939,58,19,119,72,'Sinun suusi laki on minulle kalliimpi kuin tuhannet kappaleet kultaa ja hopeata.'),
(1684940,58,19,119,73,'Sinun kätesi ovat minut tehneet ja valmistaneet; anna minulle ymmärrys oppiakseni sinun käskysi.'),
(1684941,58,19,119,74,'Sinua pelkääväiset näkevät minut ja iloitsevat, sillä minä panen toivoni sinun sanaasi.'),
(1684942,58,19,119,75,'Herra, minä tiedän, että sinun tuomiosi ovat vanhurskaat, ja uskollisuudessasi sinä olet minut nöyryyttänyt.'),
(1684943,58,19,119,76,'Sinun armosi olkoon minun lohdutukseni, niinkuin sinä olet palvelijallesi luvannut.'),
(1684944,58,19,119,77,'Tulkoon minulle sinun laupeutesi, että minä eläisin; sillä sinun lakisi on minun iloni.'),
(1684945,58,19,119,78,'Joutukoot julkeat häpeään, sillä he sortavat minua syyttä; minä tutkistelen sinun asetuksiasi.'),
(1684946,58,19,119,79,'Kääntykööt minun puolelleni ne, jotka sinua pelkäävät ja jotka sinun todistuksesi tuntevat.'),
(1684947,58,19,119,80,'Pysyköön sydämeni vakaana sinun käskyissäsi, etten minä häpeään joutuisi.'),
(1684948,58,19,119,81,'Sinun apuasi minun sieluni ikävöitsee, sinun sanaasi minä panen toivoni.'),
(1684949,58,19,119,82,'Minun silmäni ikävöitsevät sinun sanaasi; minä kysyn: "Milloin lohdutat minua?"'),
(1684950,58,19,119,83,'Sillä minä olen kuin nahkaleili savussa, mutta sinun käskyjäsi minä en unhota.'),
(1684951,58,19,119,84,'Kuinka harvat ovat palvelijasi päivät! Milloin sinä tuomitset minun vainoojani?'),
(1684952,58,19,119,85,'Julkeat kaivavat minulle kuoppia, ne, jotka eivät elä sinun lakisi mukaan.'),
(1684953,58,19,119,86,'Kaikki sinun käskysi ovat todet; syyttä he minua vainoavat; auta minua.'),
(1684954,58,19,119,87,'He ovat minut miltei tuhonneet tässä maassa, mutta minä en ole hyljännyt sinun asetuksiasi.'),
(1684955,58,19,119,88,'Virvoita minua armosi jälkeen, niin minä noudatan sinun suusi todistuksia.'),
(1684956,58,19,119,89,'Iankaikkisesti pysyy sinun sanasi, Herra, vahvana taivaissa.'),
(1684957,58,19,119,90,'Sinun uskollisuutesi kestää polvesta polveen, sinä perustit maan, ja se pysyy.'),
(1684958,58,19,119,91,'Sinun järjestyksesi mukaan ne pysyvät vielä tänä päivänä, sillä ne kaikki ovat sinun palvelijoitasi.'),
(1684959,58,19,119,92,'Ellei sinun lakisi olisi ollut minun iloni, olisin menehtynyt kurjuuteeni.'),
(1684960,58,19,119,93,'En minä ikinä unhota sinun asetuksiasi, sillä niillä sinä minua virvoitat.'),
(1684961,58,19,119,94,'Sinun omasi minä olen, pelasta minut, sillä sinun asetuksiasi minä kysyn.'),
(1684962,58,19,119,95,'Jumalattomat väijyvät minua, tuhotakseen minut, mutta minä tarkkaan sinun todistuksiasi.'),
(1684963,58,19,119,96,'Kaikella täydellisellä on rajansa - sen olen nähnyt - mutta sinun käskysi ovat ylen avarat.'),
(1684964,58,19,119,97,'Kuinka sinun lakisi onkaan minulle rakas! Kaiken päivää minä sitä tutkistelen.'),
(1684965,58,19,119,98,'Sinun käskysi tekevät minut vihollisiani viisaammaksi, sillä ne ovat minun omani iankaikkisesti.'),
(1684966,58,19,119,99,'Minä olen kaikkia opettajiani taitavampi, sillä minä tutkistelen sinun todistuksiasi.'),
(1684967,58,19,119,100,'Minä olen ymmärtäväisempi kuin vanhat, sillä minä otan vaarin sinun asetuksistasi.'),
(1684968,58,19,119,101,'Minä pidätän jalkani kaikilta pahoilta teiltä, noudattaakseni sinun sanaasi.'),
(1684969,58,19,119,102,'Minä en poikkea sinun oikeuksistasi, sillä sinä neuvot minua.'),
(1684970,58,19,119,103,'Kuinka makeat ovat minulle sinun lupauksesi! Ne ovat hunajaa makeammat minun suussani.'),
(1684971,58,19,119,104,'Sinun asetuksistasi minä saan ymmärrystä; sentähden minä vihaan kaikkia valheen teitä.'),
(1684972,58,19,119,105,'Sinun sanasi on minun jalkaini lamppu ja valkeus minun tielläni.'),
(1684973,58,19,119,106,'Minä olen vannonut ja tahdon sen täyttää: noudattaa sinun vanhurskautesi oikeuksia.'),
(1684974,58,19,119,107,'Minä olen kovin vaivattu; Herra, virvoita minua sanasi jälkeen.'),
(1684975,58,19,119,108,'Kelvatkoot sinulle, Herra, minun suuni vapaaehtoiset uhrit, ja opeta minulle oikeutesi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1684976,58,19,119,109,'Minun henkeni häälyy alati kämmenelläni, mutta sinun lakiasi minä en unhota.'),
(1684977,58,19,119,110,'Jumalattomat virittävät pauloja minun eteeni, mutta sinun asetuksistasi minä en eksy.'),
(1684978,58,19,119,111,'Sinun todistuksesi ovat minun ikuinen perintöosani, sillä ne ovat minun sydämeni ilo.'),
(1684979,58,19,119,112,'Minä olen taivuttanut sydämeni pitämään sinun käskysi, aina ja loppuun asti.'),
(1684980,58,19,119,113,'Kaksimielisiä minä vihaan, mutta sinun lakiasi minä rakastan.'),
(1684981,58,19,119,114,'Sinä olet minun suojani ja kilpeni, sinun sanaasi minä panen toivoni.'),
(1684982,58,19,119,115,'Luopukaa minusta, te pahantekijät, minä tahdon ottaa Jumalani käskyistä vaarin.'),
(1684983,58,19,119,116,'Tue minua lupauksesi jälkeen, että minä eläisin, äläkä anna minun joutua toivossani häpeään.'),
(1684984,58,19,119,117,'Vahvista minua, että minä pelastuisin, niin minä katselen alati sinun käskyjäsi.'),
(1684985,58,19,119,118,'Sinä hylkäät kaikki, jotka sinun käskyistäsi eksyvät, sillä heidän kavaluutensa on turha.'),
(1684986,58,19,119,119,'Kaikki maan jumalattomat sinä heität pois niinkuin kuonan; sentähden minä rakastan sinun todistuksiasi.'),
(1684987,58,19,119,120,'Sinun peljättävyytesi edessä minun ruumiini vapisee, ja minä pelkään sinun tuomioitasi.'),
(1684988,58,19,119,121,'Minä teen oikeuden ja vanhurskauden, älä jätä minua sortajaini käsiin.'),
(1684989,58,19,119,122,'Ole palvelijasi puolusmies hänen parhaaksensa, älä salli julkeain minua sortaa.'),
(1684990,58,19,119,123,'Minun silmäni hiueten halajavat sinun apuasi ja sinun vanhurskaita lupauksiasi.'),
(1684991,58,19,119,124,'Tee palvelijallesi armosi jälkeen ja opeta minulle käskysi.'),
(1684992,58,19,119,125,'Minä olen sinun palvelijasi, anna minulle ymmärrys, että minä sinun todistuksesi tuntisin.'),
(1684993,58,19,119,126,'On aika Herran tehdä tekonsa: he ovat rikkoneet sinun lakisi.'),
(1684994,58,19,119,127,'Sentähden minä rakastan sinun käskyjäsi enemmän kuin kultaa, enemmän kuin puhtainta kultaa.'),
(1684995,58,19,119,128,'Sentähden minä vaellan kaikessa suoraan, kaikkien sinun asetuksiesi mukaan; kaikkia valheen teitä minä vihaan.'),
(1684996,58,19,119,129,'Ihmeelliset ovat sinun todistuksesi, sentähden minun sieluni ottaa niistä vaarin.'),
(1684997,58,19,119,130,'Kun sinun sanasi avautuvat, niin ne valaisevat ja antavat yksinkertaiselle ymmärrystä.'),
(1684998,58,19,119,131,'Minä avaan suuni ja huohotan, sillä minä halajan sinun käskyjäsi.'),
(1684999,58,19,119,132,'Käänny minun puoleeni, ole minulle armollinen, niinkuin on oikein niitä kohtaan, jotka sinun nimeäsi rakastavat.'),
(1685000,58,19,119,133,'Tee minun askeleeni vakaviksi sanallasi äläkä salli minkään vääryyden minua hallita.'),
(1685001,58,19,119,134,'Päästä minut ihmisten sorrosta, niin minä noudatan sinun asetuksiasi.'),
(1685002,58,19,119,135,'Kirkasta kasvosi palvelijallesi ja opeta minulle käskysi.'),
(1685003,58,19,119,136,'Minun silmistäni vuotavat kyynelvirrat, kun sinun lakiasi ei noudateta.'),
(1685004,58,19,119,137,'Sinä olet vanhurskas, Herra, ja sinun tuomiosi ovat oikeat.'),
(1685005,58,19,119,138,'Sinä olet säätänyt todistuksesi vanhurskaudessa ja suuressa uskollisuudessa.'),
(1685006,58,19,119,139,'Minun kiivauteni kuluttaa minut, sillä minun vihamieheni unhottavat sinun sanasi.'),
(1685007,58,19,119,140,'Sinun sanasi on hyvin koeteltu, ja sinun palvelijasi rakastaa sitä.'),
(1685008,58,19,119,141,'Minä olen vähäinen ja halveksittu, mutta minä en unhota sinun asetuksiasi.'),
(1685009,58,19,119,142,'Sinun vanhurskautesi on iankaikkinen vanhurskaus, ja sinun lakisi on totuus.'),
(1685010,58,19,119,143,'Hätä ja ahdistus ovat minut saavuttaneet, mutta sinun käskysi ovat minun iloni.'),
(1685011,58,19,119,144,'Sinun todistuksesi ovat iankaikkisesti vanhurskaat; anna minulle ymmärrys, että minä eläisin.'),
(1685012,58,19,119,145,'Kaikesta sydämestäni minä huudan; vastaa minulle, Herra. Minä tahdon ottaa sinun käskyistäsi vaarin.'),
(1685013,58,19,119,146,'Minä huudan sinua, pelasta minut, niin minä noudatan sinun todistuksiasi.'),
(1685014,58,19,119,147,'Jo ennen aamun valkenemista minä huudan, sinun sanoihisi minä panen toivoni.'),
(1685015,58,19,119,148,'Jo ennen yön vartiohetkiä minun silmäni tutkistelevat sinun puhettasi.'),
(1685016,58,19,119,149,'Kuule minun ääneni armosi jälkeen; Herra, virvoita minua oikeutesi mukaan.'),
(1685017,58,19,119,150,'Lähellä ovat ilkeät vainoojat, jotka ovat kaukana sinun laistasi.'),
(1685018,58,19,119,151,'Lähellä olet sinä, Herra, ja kaikki sinun käskysi ovat todet.'),
(1685019,58,19,119,152,'Jo aikoja minä olen tiennyt sinun todistuksistasi, että sinä olet ne perustanut iäti pysyviksi.'),
(1685020,58,19,119,153,'Katso minun kurjuuttani ja pelasta minut, sillä minä en unhota sinun lakiasi.'),
(1685021,58,19,119,154,'Aja minun asiani ja lunasta minut, virvoita minua lupauksesi jälkeen.'),
(1685022,58,19,119,155,'Kaukana on pelastus jumalattomista, sillä he eivät kysy sinun käskyjäsi.'),
(1685023,58,19,119,156,'Herra, sinun armahtavaisuutesi on suuri, virvoita minua oikeutesi mukaan.'),
(1685024,58,19,119,157,'Monta on minulla vainoojaa ja vihamiestä, mutta sinun todistuksistasi minä en poikkea.'),
(1685025,58,19,119,158,'Minä näen uskottomat, ja minua iljettää, sillä he eivät noudata sinun sanaasi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685026,58,19,119,159,'Huomaa, että minä rakastan sinun asetuksiasi. Herra, virvoita minua armosi jälkeen.'),
(1685027,58,19,119,160,'Sinun sanasi on kokonansa totuus, ja kaikki sinun vanhurskautesi oikeudet pysyvät iankaikkisesti.'),
(1685028,58,19,119,161,'Ruhtinaat vainoavat minua syyttä, mutta minun sydämeni pelkää sinun sanojasi.'),
(1685029,58,19,119,162,'Minä riemuitsen sinun puheestasi, niinkuin suuren saaliin saanut.'),
(1685030,58,19,119,163,'Valhetta minä vihaan ja inhoan, mutta sinun lakiasi minä rakastan.'),
(1685031,58,19,119,164,'Seitsemästi päivässä minä ylistän sinua sinun vanhurskautesi oikeuksien tähden.'),
(1685032,58,19,119,165,'Suuri rauha on niillä, jotka rakastavat sinun lakiasi, eikä heille kompastusta tule.'),
(1685033,58,19,119,166,'Minä odotan sinulta pelastusta, Herra, ja täytän sinun käskysi.'),
(1685034,58,19,119,167,'Minun sieluni noudattaa sinun todistuksiasi, ja suuresti minä niitä rakastan.'),
(1685035,58,19,119,168,'Minä noudatan sinun asetuksiasi ja sinun todistuksiasi, sillä kaikki minun tieni ovat sinun edessäsi.'),
(1685036,58,19,119,169,'Herra, suo minun valitukseni tulla sinun kasvojesi eteen, anna minulle ymmärrys sanasi jälkeen.'),
(1685037,58,19,119,170,'Tulkoon minun anomiseni sinun kasvojesi eteen, pelasta minut lupauksesi mukaan.'),
(1685038,58,19,119,171,'Vuodattakoot minun huuleni ylistystä, sillä sinä opetat minulle käskysi.'),
(1685039,58,19,119,172,'Minun kieleni veisatkoon sinun lupauksistasi, sillä kaikki sinun käskysi ovat vanhurskaat.'),
(1685040,58,19,119,173,'Sinun kätesi olkoon minun apuni, sillä minä olen valinnut sinun asetuksesi.'),
(1685041,58,19,119,174,'Minä ikävöitsen pelastusta sinulta, Herra, ja sinun lakisi on minun iloni.'),
(1685042,58,19,119,175,'Saakoon minun sieluni elää ja ylistää sinua, ja sinun oikeutesi minua auttakoot.'),
(1685043,58,19,119,176,'Minä olen eksyksissä kuin kadonnut lammas; etsi palvelijaasi, sillä minä en unhota sinun käskyjäsi.'),
(1685044,58,19,120,1,'Matkalaulu. Ahdistuksessani minä huudan Herraa, ja hän vastaa minulle.'),
(1685045,58,19,120,2,'Herra, pelasta minun sieluni valheellisista huulista, petollisesta kielestä.'),
(1685046,58,19,120,3,'Mitä hän sinulle antaa ja mitä siihen vielä lisää, sinä petollinen kieli?'),
(1685047,58,19,120,4,'Väkivaltaisen teräviä nuolia ynnä kinsteripensaan tulisia hiiliä!'),
(1685048,58,19,120,5,'Voi minua, että minun täytyy oleskella muukalaisena Mesekissä, asua Keedarin majojen keskellä!'),
(1685049,58,19,120,6,'Kauan on minun sieluni täytynyt asua niiden seurassa, jotka rauhaa vihaavat.'),
(1685050,58,19,120,7,'Minä pidän rauhan, mutta jos sanan sanon, niin he ovat sotaan valmiit.'),
(1685051,58,19,121,1,'Matkalaulu. Minä nostan silmäni vuoria kohti: mistä tulee minulle apu?'),
(1685052,58,19,121,2,'Apu minulle tulee Herralta, joka on tehnyt taivaan ja maan.'),
(1685053,58,19,121,3,'Hän ei salli sinun jalkasi horjua, sinun varjelijasi ei torku.'),
(1685054,58,19,121,4,'Katso, hän, joka Israelia varjelee, ei torku eikä nuku.'),
(1685055,58,19,121,5,'Herra on sinun varjelijasi, Herra on suojaava varjosi sinun oikealla puolellasi.'),
(1685056,58,19,121,6,'Ei polta sinua aurinko päivällä, eikä kuu yöllä.'),
(1685057,58,19,121,7,'Herra varjelee sinut kaikesta pahasta, hän varjelee sinun sielusi.'),
(1685058,58,19,121,8,'Herra varjelee sinun lähtemisesi ja tulemisesi, nyt ja iankaikkisesti.'),
(1685059,58,19,122,1,'Matkalaulu; Daavidin virsi. Minä iloitsin, kun minulle sanottiin: "Menkäämme Herran huoneeseen".'),
(1685060,58,19,122,2,'Meidän jalkamme saavat seisoa sinun porteissasi, Jerusalem;'),
(1685061,58,19,122,3,'sinä Jerusalem, rakennettu kaupungiksi, johon kokoonnutaan yhteen,'),
(1685062,58,19,122,4,'jonne sukukunnat vaeltavat, Herran sukukunnat, niinkuin Israelille on säädetty, kiittämään Herran nimeä.'),
(1685063,58,19,122,5,'Sillä siellä ovat tuomioistuimet, Daavidin huoneen istuimet.'),
(1685064,58,19,122,6,'Toivottakaa rauhaa Jerusalemille, menestykööt ne, jotka sinua rakastavat.'),
(1685065,58,19,122,7,'Rauha olkoon sinun muuriesi sisällä, olkoon onni sinun linnoissasi.'),
(1685066,58,19,122,8,'Veljieni ja ystävieni tähden minä sanon: olkoon sinulla rauha.'),
(1685067,58,19,122,9,'Herran, meidän Jumalamme, huoneen tähden minä tahdon etsiä sinun parastasi.'),
(1685068,58,19,123,1,'Matkalaulu. Minä nostan silmäni sinun puoleesi, joka taivaissa asut.'),
(1685069,58,19,123,2,'Katso, niinkuin palvelijain silmät katsovat heidän isäntäinsä käsiin, ja niinkuin palvelijattaren silmät katsovat hänen emäntänsä käsiin, niin meidän silmämme katsovat Herran, meidän Jumalamme, puoleen, kunnes hän armahtaa meitä.'),
(1685070,58,19,123,3,'Ole meille armollinen, Herra, ole meille armollinen. Sillä kylliksi olemme jo saaneet ylenkatsetta.'),
(1685071,58,19,123,4,'Sielumme on jo kyllänsä saanut suruttomien pilkasta, ylpeitten ylenkatseesta.'),
(1685072,58,19,124,1,'Matkalaulu; Daavidin virsi. Ellei Herra olisi meidän kanssamme - näin sanokoon Israel -'),
(1685073,58,19,124,2,'ellei Herra olisi meidän kanssamme, kun ihmiset nousevat meitä vastaan,'),
(1685074,58,19,124,3,'niin he meidät elävältä nielisivät, kun heidän vihansa syttyy meitä vastaan;'),
(1685075,58,19,124,4,'niin vedet upottaisivat meidät, virta tulvisi meidän sielumme ylitse;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685076,58,19,124,5,'niin tulvisivat kuohuvat vedet meidän sielumme ylitse.'),
(1685077,58,19,124,6,'Kiitetty olkoon Herra, joka ei antanut meitä heidän hammastensa raadeltaviksi.'),
(1685078,58,19,124,7,'Meidän sielumme pääsi kuin lintu pyydystäjäin paulasta: paula katkesi, ja me pääsimme pois.'),
(1685079,58,19,124,8,'Meidän apumme on Herran nimi, hänen, joka on tehnyt taivaan ja maan.'),
(1685080,58,19,125,1,'Matkalaulu. Jotka Herraan turvaavat, ovat kuin Siionin vuori: se ei horju, vaan pysyy iankaikkisesti.'),
(1685081,58,19,125,2,'Vuoret ympäröivät Jerusalemia, ja Herra ympäröitsee kansaansa, nyt ja iankaikkisesti.'),
(1685082,58,19,125,3,'Sillä jumalattomuuden valtikka ei saa vallita vanhurskasten arpaosaa, että vanhurskaat eivät ojentaisi käsiänsä vääryyteen.'),
(1685083,58,19,125,4,'Anna hyvää hyville, Herra, ja oikeamielisille.'),
(1685084,58,19,125,5,'Mutta jotka poikkeavat mutkaisille teilleen, ne Herra hukuttakoon yhdessä väärintekijäin kanssa. Rauha Israelille!'),
(1685085,58,19,126,1,'Matkalaulu. Kun Herra käänsi Siionin kohtalon, niin me olimme kuin unta näkeväiset.'),
(1685086,58,19,126,2,'Silloin oli meidän suumme naurua täynnä, ja kielemme riemua täynnä; silloin sanottiin pakanain keskuudessa: "Herra on tehnyt suuria heitä kohtaan".'),
(1685087,58,19,126,3,'Niin, Herra on tehnyt suuria meitä kohtaan; siitä me iloitsemme.'),
(1685088,58,19,126,4,'Herra, käännä meidän kohtalomme, niinkuin sadepurot Etelämaassa.'),
(1685089,58,19,126,5,'Jotka kyynelin kylvävät, ne riemuiten leikkaavat.'),
(1685090,58,19,126,6,'He menevät itkien, kun kylvösiemenen vievät; he palajavat riemuiten, kun lyhteensä tuovat.'),
(1685091,58,19,127,1,'Matkalaulu; Salomon virsi. Jos Herra ei huonetta rakenna, niin sen rakentajat turhaan vaivaa näkevät. Jos Herra ei kaupunkia varjele, niin turhaan vartija valvoo.'),
(1685092,58,19,127,2,'Turhaan te nousette varhain ja myöhään menette levolle ja syötte leipänne murheella: yhtä hyvin hän antaa ystävilleen heidän nukkuessansa.'),
(1685093,58,19,127,3,'Katso, lapset ovat Herran lahja, ja kohdun hedelmä on anti.'),
(1685094,58,19,127,4,'Niinkuin nuolet sankarin kädessä, niin ovat nuoruudessa synnytetyt pojat.'),
(1685095,58,19,127,5,'Onnellinen se mies, jonka viini on niitä täynnä! Eivät he joudu häpeään, kun portissa puhuttelevat vihamiehiänsä.'),
(1685096,58,19,128,1,'Matkalaulu. Autuas on jokainen, joka pelkää Herraa, joka vaeltaa hänen teillänsä.'),
(1685097,58,19,128,2,'Sinä saat nauttia kättesi ansion; onnellinen sinä, sinun käy hyvin!'),
(1685098,58,19,128,3,'Niinkuin hedelmällinen viiniköynnös on sinun emäntäsi sinun huoneesi perällä, niinkuin öljypuun vesat ovat sinun lapsesi sinun pöytäsi ympärillä.'),
(1685099,58,19,128,4,'Sillä katso, näin siunataan mies, joka Herraa pelkää.'),
(1685100,58,19,128,5,'Siunatkoon Herra sinua Siionista, niin sinä saat kaikkina elinpäivinäsi nähdä Jerusalemin onnellisena,'),
(1685101,58,19,128,6,'saat nähdä lastesi lapset. Rauha Israelille!'),
(1685102,58,19,129,1,'Matkalaulu. He ovat minua kovin ahdistaneet nuoruudestani asti - näin sanokoon Israel -'),
(1685103,58,19,129,2,'he ovat minua kovin ahdistaneet nuoruudestani asti, mutta eivät he ole päässeet minusta voitolle.'),
(1685104,58,19,129,3,'Kyntäjät ovat minun selkääni kyntäneet ja vetäneet pitkät vaot.'),
(1685105,58,19,129,4,'Mutta Herra on vanhurskas, hän on katkonut jumalattomain köydet.'),
(1685106,58,19,129,5,'Joutukoot häpeään ja kääntykööt takaisin kaikki Siionin vihamiehet.'),
(1685107,58,19,129,6,'Olkoot he niinkuin ruoho katoilla, joka kuivuu ennen korrelle puhkeamistaan,'),
(1685108,58,19,129,7,'josta ei leikkaaja täytä kättänsä eikä lyhteen sitoja syliänsä.'),
(1685109,58,19,129,8,'Älköötkä sanoko ohitsekulkijat: "Herran siunaus tulkoon teille. Me siunaamme teitä Herran nimeen."'),
(1685110,58,19,130,1,'Matkalaulu. Syvyydestä minä huudan sinua, Herra.'),
(1685111,58,19,130,2,'Herra, kuule minun ääneni. Tarkatkoot sinun korvasi minun rukousteni ääntä.'),
(1685112,58,19,130,3,'Jos sinä, Herra, pidät mielessäsi synnit, Herra, kuka silloin kestää?'),
(1685113,58,19,130,4,'Mutta sinun tykönäsi on anteeksiantamus, että sinua peljättäisiin.'),
(1685114,58,19,130,5,'Minä odotan Herraa, minun sieluni odottaa, ja minä panen toivoni hänen sanaansa.'),
(1685115,58,19,130,6,'Minun sieluni odottaa Herraa hartaammin kuin vartijat aamua, kuin vartijat aamua.'),
(1685116,58,19,130,7,'Pane toivosi Herraan, Israel. Sillä Herran tykönä on armo, runsas lunastus hänen tykönänsä.'),
(1685117,58,19,130,8,'Ja hän lunastaa Israelin kaikista sen synneistä.'),
(1685118,58,19,131,1,'Matkalaulu; Daavidin virsi. Herra, minun sydämeni ei ole ylpeä, eivät minun silmäni ole korskeat, enkä minä tavoittele asioita, jotka ovat minulle ylen suuret ja käsittämättömät.'),
(1685119,58,19,131,2,'Totisesti, minä olen sieluni viihdyttänyt ja tyynnyttänyt: niinkuin vieroitettu lapsi äidin helmassa, niinkuin vieroitettu lapsi, niin on sieluni minussa.'),
(1685120,58,19,131,3,'Pane toivosi Herraan, Israel, nyt ja iankaikkisesti.'),
(1685121,58,19,132,1,'Matkalaulu. Muista, Herra, Daavidin hyväksi kaikkia hänen vaivojansa,'),
(1685122,58,19,132,2,'hänen, joka vannoi valan Herralle ja teki lupauksen Jaakobin Väkevälle:'),
(1685123,58,19,132,3,'"Minä en mene majaan, joka on minun kotini, enkä nouse vuoteeseeni, joka on minun leposijani,'),
(1685124,58,19,132,4,'minä en suo silmilleni unta enkä silmäluomilleni lepoa,'),
(1685125,58,19,132,5,'ennenkuin löydän sijan Herralle, asumuksen Jaakobin Väkevälle".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685126,58,19,132,6,'Katso, me kuulimme sen olevan Efratassa, me löysimme sen Jaarin kedoilta.'),
(1685127,58,19,132,7,'Menkäämme hänen asumukseensa, kumartukaamme hänen jalkainsa astinlaudan eteen.'),
(1685128,58,19,132,8,'Nouse, Herra, leposijaasi, sinä ja sinun väkevyytesi arkki.'),
(1685129,58,19,132,9,'Sinun pappisi olkoot puetut vanhurskaudella, ja sinun hurskaasi riemuitkoot.'),
(1685130,58,19,132,10,'Palvelijasi Daavidin tähden älä torju pois voideltusi kasvoja.'),
(1685131,58,19,132,11,'Herra on vannonut Daavidille totisen valan, jota hän ei peruuta: "Sinun ruumiisi hedelmän minä asetan sinun valtaistuimellesi.'),
(1685132,58,19,132,12,'Jos sinun poikasi pitävät minun liittoni ja minun todistukseni, jotka minä heille opetan, niin saavat heidänkin poikansa istua sinun valtaistuimellasi iankaikkisesti."'),
(1685133,58,19,132,13,'Sillä Herra on valinnut Siionin, halunnut sen asunnoksensa:'),
(1685134,58,19,132,14,'"Tämä on minun leposijani iankaikkisesti; tässä minä asun, sillä tänne on minun haluni ollut.'),
(1685135,58,19,132,15,'Siionin ravinnon minä runsaasti siunaan, sen köyhät minä leivällä ruokin.'),
(1685136,58,19,132,16,'Sen papit minä puetan autuudella, ja sen hurskaat riemuiten riemuitkoot.'),
(1685137,58,19,132,17,'Siellä minä annan yletä Daavidille sarven, sytytän voidellulleni lampun.'),
(1685138,58,19,132,18,'Hänen vihollisensa minä puetan häpeällä, mutta hänen päässänsä loistaa hänen kruununsa."'),
(1685139,58,19,133,1,'Matkalaulu; Daavidin virsi. Katso, kuinka hyvää ja suloista on, että veljekset sovussa asuvat!'),
(1685140,58,19,133,2,'Se on niinkuin kallis öljy pään päällä, jota tiukkuu partaan - Aaronin partaan, jota tiukkuu hänen viittansa liepeille.'),
(1685141,58,19,133,3,'Se on niinkuin Hermonin kaste, joka tiukkuu Siionin vuorille. Sillä sinne on Herra säätänyt siunauksen, elämän, ikuisiksi ajoiksi.'),
(1685142,58,19,134,1,'Matkalaulu. Katso, kiittäkää Herraa, kaikki te Herran palvelijat, jotka öisin seisotte Herran huoneessa.'),
(1685143,58,19,134,2,'Kohottakaa kätenne pyhäkköön päin ja kiittäkää Herraa.'),
(1685144,58,19,134,3,'Herra siunatkoon sinua Siionista, hän, joka on tehnyt taivaan ja maan.'),
(1685145,58,19,135,1,'Halleluja! Ylistäkää Herran nimeä. Ylistäkää, te Herran palvelijat,'),
(1685146,58,19,135,2,'jotka seisotte Herran huoneessa, meidän Jumalamme huoneen esikartanoissa.'),
(1685147,58,19,135,3,'Ylistäkää Herraa, sillä Herra on hyvä, veisatkaa kiitosta hänen nimellensä, sillä se on suloinen.'),
(1685148,58,19,135,4,'Sillä Herra on valinnut Jaakobin omaksensa, Israelin omaisuudeksensa.'),
(1685149,58,19,135,5,'Sillä minä tiedän, että Herra on suuri, ja meidän Herramme korkeampi kaikkia jumalia.'),
(1685150,58,19,135,6,'Kaiken, mitä Herra tahtoo, hän tekee, sekä taivaassa että maassa, merissä ja kaikissa syvyyksissä;'),
(1685151,58,19,135,7,'hän, joka nostaa pilvet maan ääristä, tekee salamat ja sateen ja tuopi tuulen sen säilytyspaikoista;'),
(1685152,58,19,135,8,'hän, joka surmasi Egyptin esikoiset, niin ihmisten kuin eläinten;'),
(1685153,58,19,135,9,'hän, joka lähetti tunnusteot ja ihmeet sinun keskellesi, Egypti, faraota ja kaikkia hänen palvelijoitansa vastaan;'),
(1685154,58,19,135,10,'hän, joka kukisti suuret kansat ja tuotti surman väkeville kuninkaille,'),
(1685155,58,19,135,11,'Siihonille, amorilaisten kuninkaalle, ja Oogille, Baasanin kuninkaalle, ja kaikille Kanaanin valtakunnille'),
(1685156,58,19,135,12,'ja antoi heidän maansa perintöosaksi, perintöosaksi kansallensa Israelille.'),
(1685157,58,19,135,13,'Herra, sinun nimesi pysyy iankaikkisesti, Herra, sinun muistosi polvesta polveen.'),
(1685158,58,19,135,14,'Sillä Herra hankkii oikeuden kansalleen ja armahtaa palvelijoitansa.'),
(1685159,58,19,135,15,'Pakanain epäjumalat ovat hopeata ja kultaa, ihmiskätten tekoa.'),
(1685160,58,19,135,16,'Niillä on suu, mutta eivät ne puhu, niillä on silmät, mutta eivät näe,'),
(1685161,58,19,135,17,'niillä on korvat, mutta eivät kuule, eikä niillä ole henkeä suussansa.'),
(1685162,58,19,135,18,'Niiden kaltaisia ovat niiden tekijät ja kaikki, jotka niihin turvaavat.'),
(1685163,58,19,135,19,'Te, Israelin suku, kiittäkää Herraa, te, Aaronin suku, kiittäkää Herraa.'),
(1685164,58,19,135,20,'Te, Leevin suku, kiittäkää Herraa, te, Herraa pelkääväiset, kiittäkää Herraa.'),
(1685165,58,19,135,21,'Kohotkoon Herralle kiitos Siionista, hänelle, joka Jerusalemissa asuu. Halleluja!'),
(1685166,58,19,136,1,'Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.'),
(1685167,58,19,136,2,'Kiittäkää jumalien Jumalaa, sillä hänen armonsa pysyy iankaikkisesti.'),
(1685168,58,19,136,3,'Kiittäkää herrain Herraa, sillä hänen armonsa pysyy iankaikkisesti;'),
(1685169,58,19,136,4,'häntä, joka yksin tekee suuria ihmeitä, sillä hänen armonsa pysyy iankaikkisesti;'),
(1685170,58,19,136,5,'häntä, joka on taidolla tehnyt taivaat, sillä hänen armonsa pysyy iankaikkisesti;'),
(1685171,58,19,136,6,'häntä, joka on vetten ylitse levittänyt maan, sillä hänen armonsa pysyy iankaikkisesti;'),
(1685172,58,19,136,7,'häntä, joka on tehnyt suuret valot, sillä hänen armonsa pysyy iankaikkisesti:'),
(1685173,58,19,136,8,'auringon hallitsemaan päivää, sillä hänen armonsa pysyy iankaikkisesti,'),
(1685174,58,19,136,9,'kuun ja tähdet hallitsemaan yötä, sillä hänen armonsa pysyy iankaikkisesti;'),
(1685175,58,19,136,10,'häntä, joka löi Egyptiä surmaten sen esikoiset, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685176,58,19,136,11,'ja vei Israelin pois heidän keskeltänsä, sillä hänen armonsa pysyy iankaikkisesti,'),
(1685177,58,19,136,12,'väkevällä kädellä ja ojennetulla käsivarrella, sillä hänen armonsa pysyy iankaikkisesti;'),
(1685178,58,19,136,13,'häntä, joka jakoi Kaislameren kahtia, sillä hänen armonsa pysyy iankaikkisesti,'),
(1685179,58,19,136,14,'ja kuljetti Israelin sen keskitse, sillä hänen armonsa pysyy iankaikkisesti,'),
(1685180,58,19,136,15,'ja syöksi faraon sotajoukkoineen Kaislamereen, sillä hänen armonsa pysyy iankaikkisesti;'),
(1685181,58,19,136,16,'häntä, joka johdatti kansaansa erämaassa, sillä hänen armonsa pysyy iankaikkisesti;'),
(1685182,58,19,136,17,'häntä, joka voitti suuret kuninkaat, sillä hänen armonsa pysyy iankaikkisesti,'),
(1685183,58,19,136,18,'ja surmasi mahtavat kuninkaat, sillä hänen armonsa pysyy iankaikkisesti,'),
(1685184,58,19,136,19,'Siihonin, amorilaisten kuninkaan, sillä hänen armonsa pysyy iankaikkisesti,'),
(1685185,58,19,136,20,'ja Oogin, Baasanin kuninkaan, sillä hänen armonsa pysyy iankaikkisesti,'),
(1685186,58,19,136,21,'ja antoi heidän maansa perintöosaksi, sillä hänen armonsa pysyy iankaikkisesti,'),
(1685187,58,19,136,22,'perintöosaksi palvelijallensa Israelille, sillä hänen armonsa pysyy iankaikkisesti;'),
(1685188,58,19,136,23,'häntä, joka muisti meitä alennuksessamme, sillä hänen armonsa pysyy iankaikkisesti,'),
(1685189,58,19,136,24,'ja kirvoitti meidät vihollisistamme, sillä hänen armonsa pysyy iankaikkisesti;'),
(1685190,58,19,136,25,'häntä, joka antaa ravinnon kaikelle lihalle, sillä hänen armonsa pysyy iankaikkisesti.'),
(1685191,58,19,136,26,'Kiittäkää taivaan Jumalaa, sillä hänen armonsa pysyy iankaikkisesti.'),
(1685192,58,19,137,1,'Baabelin virtain vierillä - siellä me istuimme ja itkimme, kun Siionia muistelimme.'),
(1685193,58,19,137,2,'Pajuihin, joita siellä oli, me ripustimme kanteleemme.'),
(1685194,58,19,137,3,'Sillä vangitsijamme vaativat meiltä siellä lauluja ja orjuuttajamme iloa: "Veisatkaa meille Siionin virsiä".'),
(1685195,58,19,137,4,'Kuinka me voisimme veisata Herran virsiä vieraalla maalla?'),
(1685196,58,19,137,5,'Jos minä unhotan sinut, Jerusalem, niin unhota sinä minun oikea käteni.'),
(1685197,58,19,137,6,'Tarttukoon kieleni suuni lakeen, ellen minä sinua muista, ellen pidä Jerusalemia ylimpänä ilonani.'),
(1685198,58,19,137,7,'Muista, Herra, Jerusalemin tuhopäivä, kosta se Edomin lapsille, jotka sanoivat: "Hajottakaa se, hajottakaa perustuksia myöten!"'),
(1685199,58,19,137,8,'Tytär Baabel, sinä häviön oma, autuas se, joka sinulle kostaa kaiken, minkä olet meille tehnyt!'),
(1685200,58,19,137,9,'Autuas se, joka ottaa sinun pienet lapsesi ja murskaa ne kallioon!'),
(1685201,58,19,138,1,'Daavidin virsi. Minä kiitän sinua kaikesta sydämestäni, veisaan sinun kiitostasi jumalien edessä.'),
(1685202,58,19,138,2,'Minä rukoilen sinua kumartuneena sinun pyhään temppeliisi päin ja kiitän sinun nimeäsi sinun armosi ja totuutesi tähden; sillä sinä olet osoittanut, että sinun lupauksesi on suuri yli kaiken, mitä sinun nimesi ilmoittaa.'),
(1685203,58,19,138,3,'Sinä päivänä, jona minä huusin, sinä vastasit minulle; sinä rohkaisit minua: minun sieluni sai voiman.'),
(1685204,58,19,138,4,'Herra, kaikki maan kuninkaat ylistävät sinua, kun kuulevat sinun suusi sanat.'),
(1685205,58,19,138,5,'Ja he veisaavat Herran teistä, sillä suuri on Herran kunnia.'),
(1685206,58,19,138,6,'Sillä Herra on korkea, mutta katsoo alhaiseen, ja hän tuntee ylpeän kaukaa.'),
(1685207,58,19,138,7,'Vaikka minä vaellan ahdistuksen keskellä, niin sinä virvoitat minut. Sinä ojennat kätesi minun vihamiesteni vihaa vastaan, ja sinun oikea kätesi auttaa minua.'),
(1685208,58,19,138,8,'Herra vie minun asiani päätökseen. Herra, sinun armosi pysyy iankaikkisesti; älä jätä kesken kättesi työtä.'),
(1685209,58,19,139,1,'Veisuunjohtajalle; Daavidin virsi. Herra, sinä tutkit minua ja tunnet minut.'),
(1685210,58,19,139,2,'Istunpa minä tahi nousen, sinä sen tiedät; sinä ymmärrät minun ajatukseni kaukaa.'),
(1685211,58,19,139,3,'Käynpä tahi makaan, sinä sen havaitset, ja kaikki minun tieni ovat sinulle tutut.'),
(1685212,58,19,139,4,'Sillä, katso, ei ole sanaa minun kielelläni, jota sinä, Herra, et täysin tunne.'),
(1685213,58,19,139,5,'Sinä olet saartanut minut edestä ja takaa ja laskenut kätesi minun päälleni.'),
(1685214,58,19,139,6,'Senkaltainen tieto on minulle ylen ihmeellinen, ylen korkea käsittääkseni sen.'),
(1685215,58,19,139,7,'Minne minä voisin mennä, kussa ei sinun Henkesi olisi, minne paeta sinun kasvojesi edestä?'),
(1685216,58,19,139,8,'Jos minä taivaaseen nousisin, niin sinä olet siellä; jos minä tuonelaan vuoteeni tekisin, niin katso, sinä olet siellä.'),
(1685217,58,19,139,9,'Jos minä kohoaisin aamuruskon siivillä ja asettuisin asumaan meren ääriin,'),
(1685218,58,19,139,10,'sielläkin sinun kätesi minua taluttaisi, sinun oikea kätesi tarttuisi minuun.'),
(1685219,58,19,139,11,'Ja jos minä sanoisin: "Peittäköön minut pimeys, ja valkeus minun ympärilläni tulkoon yöksi",'),
(1685220,58,19,139,12,'niin ei pimeyskään olisi sinulle pimeä: yö valaisisi niinkuin päivä, pimeys olisi niinkuin valkeus.'),
(1685221,58,19,139,13,'Sillä sinä olet luonut minun munaskuuni, sinä kudoit minut kokoon äitini kohdussa.'),
(1685222,58,19,139,14,'Minä kiitän sinua siitä, että olen tehty ylen ihmeellisesti; ihmeelliset ovat sinun tekosi, sen minun sieluni kyllä tietää.'),
(1685223,58,19,139,15,'Minun luuni eivät olleet sinulta salatut, kun minut salassa valmistettiin, kun minut taiten tehtiin maan syvyyksissä.'),
(1685224,58,19,139,16,'Sinun silmäsi näkivät minut jo idussani. Minun päiväni olivat määrätyt ja kirjoitetut kaikki sinun kirjaasi, ennenkuin ainoakaan niistä oli tullut.'),
(1685225,58,19,139,17,'Mutta kuinka kalliit ovat minulle sinun ajatuksesi, Jumala, kuinka suuri on niitten luku!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685226,58,19,139,18,'Jos minä tahtoisin ne lukea, olisi niitä enemmän kuin hiekan jyväsiä. - Minä herään ja olen vielä sinun tykönäsi.'),
(1685227,58,19,139,19,'Jumala, jospa sinä surmaisit jumalattomat! Ja te murhamiehet, väistykää minusta pois!'),
(1685228,58,19,139,20,'Sillä he puhuvat sinusta petollisesti ja lausuvat turhaan sinun nimesi - nuo sinun vihollisesi.'),
(1685229,58,19,139,21,'Herra, enkö minä vihaisi niitä, jotka sinua vihaavat, enkö inhoaisi niitä, jotka sinua vastustavat?'),
(1685230,58,19,139,22,'Kaikella vihalla minä heitä vihaan, he ovat minun omia vihollisiani.'),
(1685231,58,19,139,23,'Tutki minua, Jumala, ja tunne minun sydämeni, koettele minua ja tunne minun ajatukseni.'),
(1685232,58,19,139,24,'Ja katso: jos minun tieni on vaivaan vievä, niin johdata minut iankaikkiselle tielle.'),
(1685233,58,19,140,1,'Veisuunjohtajalle; Daavidin virsi.'),
(1685234,58,19,140,2,'Päästä minut, Herra, pahoista ihmisistä, varjele minut väkivaltaisilta miehiltä,'),
(1685235,58,19,140,3,'jotka ajattelevat sydämessään pahaa ja joka päivä yllyttävät sotaan.'),
(1685236,58,19,140,4,'He hiovat kielensä niinkuin käärmeet, kyykäärmeen myrkkyä on heidän huultensa alla. Sela.'),
(1685237,58,19,140,5,'Suojaa minut, Herra, jumalattomien käsiltä, varjele minut väkivaltaisilta miehiltä, jotka tahtovat saada minun jalkani lankeamaan.'),
(1685238,58,19,140,6,'Nuo ylpeät virittävät minulle ansoja ja pauloja, levittävät verkkoja minun tielleni, asettavat minulle pyydyksiä. Sela.'),
(1685239,58,19,140,7,'Minä sanon Herralle: "Sinä olet minun Jumalani". Herra, ota korviisi minun rukousteni ääni.'),
(1685240,58,19,140,8,'Herra, Herra, sinä minun väkevä apuni, sinä suojaat minun pääni taistelun päivänä.'),
(1685241,58,19,140,9,'Herra, älä salli, mitä jumalattomat haluavat, älä anna heidän aikeittensa onnistua; muutoin he ylvästelevät. Sela.'),
(1685242,58,19,140,10,'Sattukoon minun saartajaini omaan päähän onnettomuus, jota heidän huulensa hankkivat.'),
(1685243,58,19,140,11,'Tulkoon tulisia hiiliä heidän päällensä; hän syösköön heidät tuleen, vesivirtoihin, joista he älkööt nousko.'),
(1685244,58,19,140,12,'Kielevä mies ei ole pysyvä maassa; väkivaltaista ajaa onnettomuus ja iskee iskemistään.'),
(1685245,58,19,140,13,'Minä tiedän, että Herra ajaa kurjan asiaa, hankkii köyhille oikeuden.'),
(1685246,58,19,140,14,'Totisesti, vanhurskaat saavat kiittää sinun nimeäsi, ja oikeamieliset saavat asua sinun kasvojesi edessä.'),
(1685247,58,19,141,1,'Daavidin virsi. Herra, minä huudan sinua, riennä minun tyköni. Ota korviisi minun ääneni, kun minä sinua huudan.'),
(1685248,58,19,141,2,'Minun rukoukseni olkoon suitsutusuhri sinun kasvojesi edessä, minun kätteni kohottaminen olkoon ehtoouhri.'),
(1685249,58,19,141,3,'Herra, pane minun suulleni vartija, vartioitse minun huulteni ovea.'),
(1685250,58,19,141,4,'Älä salli minun sydämeni taipua pahaan, pitämään jumalatonta menoa väärintekijäin kanssa. Minä en tahdo maistaa heidän herkkupalojansa.'),
(1685251,58,19,141,5,'Lyököön minua vanhurskas: se on rakkautta; kurittakoon hän minua: se on öljyä minun päähäni, siitä minun pääni älköön kieltäytykö. Sillä vielä vähän aikaa, niin minun rukoukseni täyttyy, mutta heidän käy pahoin:'),
(1685252,58,19,141,6,'heidän päämiehensä syöstään kalliolta alas, ja silloin kuullaan minun sanani suloisiksi.'),
(1685253,58,19,141,7,'Niinkuin maa kynnetään ja kuokitaan, niin ovat meidän luumme hajotetut tuonelan kuilun suulle.'),
(1685254,58,19,141,8,'Mutta sinuun, Herra, Herra, minun silmäni katsovat, sinuun minä turvaan. Älä hylkää minun sieluani.'),
(1685255,58,19,141,9,'Varjele minua niiden pauloista, jotka minua pyydystävät, väärintekijäin ansoista.'),
(1685256,58,19,141,10,'Kaatukoot kaikki jumalattomat omiin kuoppiinsa; mutta suo minun ne välttää.'),
(1685257,58,19,142,1,'Daavidin mietevirsi, hänen ollessaan luolassa; rukous.'),
(1685258,58,19,142,2,'Minä korotan ääneni ja huudan Herraa, minä korotan ääneni ja rukoilen Herralta armoa.'),
(1685259,58,19,142,3,'Minä vuodatan hänen eteensä valitukseni, kerron hänelle ahdistukseni.'),
(1685260,58,19,142,4,'Kun minun henkeni minussa nääntyy, niin sinä tunnet minun tieni. Polulle, jota minä käyn, he ovat virittäneet paulan minun eteeni.'),
(1685261,58,19,142,5,'Katso minun oikealle puolelleni ja näe: ei kukaan minua tunne. Ei ole minulla pakopaikkaa, ei kukaan minun sielustani välitä.'),
(1685262,58,19,142,6,'Minä huudan sinun puoleesi, Herra; minä sanon: Sinä olet minun turvani, minun osani elävien maassa.'),
(1685263,58,19,142,7,'Tarkkaa minun huutoani, sillä minä olen sangen viheliäinen, pelasta minut vainoojistani, sillä he ovat minua väkevämmät.'),
(1685264,58,19,142,8,'Vie minun sieluni ulos vankeudesta kiittämään sinun nimeäsi. Vanhurskaat kokoontuvat minun ympärilleni, kun sinä minulle hyvin teet.'),
(1685265,58,19,143,1,'Daavidin virsi. Herra, kuule minun rukoukseni, ota korviisi minun anomiseni. Vastaa minulle uskollisuudessasi ja vanhurskaudessasi.'),
(1685266,58,19,143,2,'Älä käy tuomiolle palvelijasi kanssa, sillä ei yksikään elävä ole vanhurskas sinun edessäsi.'),
(1685267,58,19,143,3,'Sillä vihollinen vainoaa minun sieluani, hän on ruhjonut minun elämäni maahan ja pannut minut pimeään niinkuin ammoin kuolleet.'),
(1685268,58,19,143,4,'Minun henkeni nääntyy minussa, sydäntäni kouristaa minun rinnassani.'),
(1685269,58,19,143,5,'Minä muistelen muinaisia päiviä, tutkistelen kaikkia sinun töitäsi ja ajattelen sinun kättesi tekoja.'),
(1685270,58,19,143,6,'Minä levitän käteni sinun puoleesi. Niinkuin janoinen maa, niin minun sieluni halajaa sinua. Sela.'),
(1685271,58,19,143,7,'Vastaa minulle pian, Herra, minun henkeni nääntyy. Älä peitä minulta kasvojasi, etten tulisi niiden kaltaiseksi, jotka hautaan vaipuvat.'),
(1685272,58,19,143,8,'Suo minun varhain kuulla sinun armoasi, sillä sinuun minä turvaan. Osoita minulle tie, jota minun tulee käydä, sillä sinun tykösi minä ylennän sieluni.'),
(1685273,58,19,143,9,'Pelasta minut vihollisistani, Herra. Sinun tykösi minä pyrin suojaan.'),
(1685274,58,19,143,10,'Opeta minut tekemään sitä, mikä sinulle kelpaa, sillä sinä olet minun Jumalani. Sinun hyvä Henkesi johdattakoon minua tasaista maata.'),
(1685275,58,19,143,11,'Herra, virvoita nimesi tähden, vanhurskaudessasi auta minun sieluni ahdistuksesta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685276,58,19,143,12,'Tuhoa minun viholliseni armosi tähden ja hukuta kaikki, jotka minun sieluani ahdistavat, sillä minä olen sinun palvelijasi.'),
(1685277,58,19,144,1,'Daavidin virsi. Kiitetty olkoon Herra, minun kallioni, joka opettaa minun käteni taistelemaan, minun sormeni sotimaan,'),
(1685278,58,19,144,2,'hän, joka antaa minulle armon; minun linnani, varustukseni ja pelastajani, minun kilpeni, jonka turviin minä pakenen, hän, joka laskee kansani minun valtani alle.'),
(1685279,58,19,144,3,'Herra, mikä on ihminen, että hänestä lukua pidät, mikä ihmislapsi, että häntä ajattelet!'),
(1685280,58,19,144,4,'Ihminen on kuin tuulen henkäys, hänen päivänsä niinkuin pakeneva varjo.'),
(1685281,58,19,144,5,'Herra, notkista taivaasi ja astu alas, kosketa vuoria, niin että ne suitsuavat.'),
(1685282,58,19,144,6,'Iske salamoita ja hajota heidät, lennätä nuolesi ja kauhistuta heidät.'),
(1685283,58,19,144,7,'Ojenna kätesi korkeudesta, tempaa ja pelasta minut suurista vesistä, muukalaisten kädestä,'),
(1685284,58,19,144,8,'joiden suu puhuu vilppiä ja joiden oikea käsi on valheen käsi!'),
(1685285,58,19,144,9,'Jumala, minä veisaan sinulle uuden virren, soitan sinulle kymmenkielisellä harpulla,'),
(1685286,58,19,144,10,'sinulle, joka annat kuninkaille voiton ja tempaat palvelijasi Daavidin turvaan pahalta miekalta.'),
(1685287,58,19,144,11,'Tempaa ja pelasta minut muukalaisten käsistä, joiden suu puhuu vilppiä ja joiden oikea käsi on valheen käsi.'),
(1685288,58,19,144,12,'Niin meidän poikamme ovat nuoruudessaan kuin korkealle kohoavat kasvit, tyttäremme kuin temppelin veistetyt kulmapatsaat;'),
(1685289,58,19,144,13,'meidän aittamme ovat täynnä, ja antavat kaikkinaista viljaa, meidän lampaamme lisääntyvät laitumillamme tuhansin ja kymmenin tuhansin;'),
(1685290,58,19,144,14,'meidän härkiemme kuormat ovat runsaat, ei ole aukkoa muurissa, ei ole pakolaista, ei kuulu valitushuutoa kaduillamme.'),
(1685291,58,19,144,15,'Autuas se kansa, jolle näin käy, autuas se kansa, jonka Jumala Herra on!'),
(1685292,58,19,145,1,'Daavidin ylistysvirsi. Minä kunnioitan sinua, Jumalani, sinä kuningas, ja kiitän sinun nimeäsi aina ja iankaikkisesti.'),
(1685293,58,19,145,2,'Joka päivä minä kiitän sinua ja ylistän sinun nimeäsi aina ja iankaikkisesti.'),
(1685294,58,19,145,3,'Suuri on Herra ja sangen ylistettävä, ja hänen suuruutensa on tutkimaton.'),
(1685295,58,19,145,4,'Sukupolvi ylistää sukupolvelle sinun tekojasi, ja he julistavat sinun voimallisia töitäsi.'),
(1685296,58,19,145,5,'Sinun valtasuuruutesi kirkkautta ja kunniaa ja sinun ihmeellisiä tekojasi minä tahdon tutkistella.'),
(1685297,58,19,145,6,'Sinun peljättävien töittesi voimasta puhutaan, sinun suurista teoistasi minä kerron.'),
(1685298,58,19,145,7,'Julistettakoon sinun suuren hyvyytesi muistoa ja sinun vanhurskaudestasi riemuittakoon.'),
(1685299,58,19,145,8,'Herra on armahtavainen ja laupias, pitkämielinen ja suuri armossa.'),
(1685300,58,19,145,9,'Herra on hyvä kaikille ja armahtaa kaikkia tekojansa.'),
(1685301,58,19,145,10,'Kaikki sinun tekosi ylistävät sinua, Herra, ja sinun hurskaasi kiittävät sinua.'),
(1685302,58,19,145,11,'He puhuvat sinun valtakuntasi kunniasta ja kertovat sinun voimastasi.'),
(1685303,58,19,145,12,'Niin he ilmoittavat ihmislapsille hänen voimalliset työnsä ja hänen valtakuntansa kirkkauden ja kunnian.'),
(1685304,58,19,145,13,'Sinun valtakuntasi on iankaikkinen valtakunta, ja sinun herrautesi pysyy polvesta polveen.'),
(1685305,58,19,145,14,'Herra tukee kaikkia kaatuvia, ja kaikki alaspainetut hän nostaa.'),
(1685306,58,19,145,15,'Kaikkien silmät vartioitsevat sinua, ja sinä annat heille heidän ruokansa ajallaan.'),
(1685307,58,19,145,16,'Sinä avaat kätesi ja ravitset suosiollasi kaikki, jotka elävät.'),
(1685308,58,19,145,17,'Herra on vanhurskas kaikissa teissään ja armollinen kaikissa teoissaan.'),
(1685309,58,19,145,18,'Herra on lähellä kaikkia, jotka häntä avuksensa huutavat, kaikkia, jotka totuudessa häntä avuksensa huutavat.'),
(1685310,58,19,145,19,'Hän tekee, mitä häntä pelkääväiset halajavat, hän kuulee heidän huutonsa ja auttaa heitä.'),
(1685311,58,19,145,20,'Herra varjelee kaikkia, jotka häntä rakastavat, mutta kaikki jumalattomat hän hukuttaa.'),
(1685312,58,19,145,21,'Minun suuni lausukoon Herran ylistystä, ja kaikki liha kiittäköön hänen pyhää nimeänsä, aina ja iankaikkisesti.'),
(1685313,58,19,146,1,'Halleluja! Ylistä, minun sieluni, Herraa.'),
(1685314,58,19,146,2,'Minä ylistän Herraa kaiken ikäni, veisaan kiitosta Jumalalleni, niin kauan kuin elän.'),
(1685315,58,19,146,3,'Älkää luottako ruhtinaihin älkääkä ihmislapseen, sillä ei hän voi auttaa.'),
(1685316,58,19,146,4,'Kun hänen henkensä lähtee hänestä, niin hän tulee maaksi jälleen; sinä päivänä hänen hankkeensa raukeavat tyhjiin.'),
(1685317,58,19,146,5,'Autuas se, jonka apuna on Jaakobin Jumala, se, joka panee toivonsa Herraan, Jumalaansa,'),
(1685318,58,19,146,6,'häneen, joka on tehnyt taivaan ja maan, meren ja kaiken, mitä niissä on, joka pysyy uskollisena iankaikkisesti,'),
(1685319,58,19,146,7,'joka hankkii oikeuden sorretuille, joka antaa leivän nälkäisille. Herra vapauttaa vangitut,'),
(1685320,58,19,146,8,'Herra avaa sokeain silmät, Herra nostaa alaspainetut, Herra rakastaa vanhurskaita.'),
(1685321,58,19,146,9,'Herra varjelee muukalaiset, holhoo orvot ja lesket, mutta jumalattomain tien hän tekee mutkaiseksi.'),
(1685322,58,19,146,10,'Herra on kuningas iankaikkisesti, sinun Jumalasi, Siion, polvesta polveen. Halleluja!'),
(1685323,58,19,147,1,'Halleluja! Hyvä on veisata kiitosta meidän Jumalallemme. Se on suloista; ylistäminen on soveliasta.'),
(1685324,58,19,147,2,'Herra rakentaa Jerusalemin, hän kokoaa Israelin karkoitetut.'),
(1685325,58,19,147,3,'Hän parantaa ne, joilla on särjetty sydän, ja sitoo heidän haavansa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685326,58,19,147,4,'Hän on määrännyt tähtien luvun, hän kutsuu niitä kaikkia nimeltä.'),
(1685327,58,19,147,5,'Meidän Herramme on suuri, suuri voimassansa, hänen ymmärryksensä on mittaamaton.'),
(1685328,58,19,147,6,'Herra pitää pystyssä nöyrät, mutta jumalattomat hän painaa maahan.'),
(1685329,58,19,147,7,'Veisatkaa Herralle kiitosvirsi, soittakaa kanteleilla kiitosta meidän Jumalallemme.'),
(1685330,58,19,147,8,'Hän peittää pilvillä taivaan ja valmistaa sateen maalle; hän kasvattaa ruohon vuorille'),
(1685331,58,19,147,9,'ja antaa ruuan eläimille, kaarneen pojillekin, kun ne huutavat.'),
(1685332,58,19,147,10,'Ei kelpaa hänelle hevosen voima, ei hän mielisty miehen jalkojen nopeuteen:'),
(1685333,58,19,147,11,'Herra mielistyy niihin, jotka häntä pelkäävät, jotka panevat toivonsa hänen armoonsa.'),
(1685334,58,19,147,12,'Kiitä Herraa, Jerusalem. Ylistä Jumalaasi, Siion.'),
(1685335,58,19,147,13,'Sillä hän tekee lujiksi sinun porttiesi salvat; hän siunaa sinun lapsesi sinun keskelläsi.'),
(1685336,58,19,147,14,'Hän hankkii rauhan sinun rajojesi sisälle, ravitsee sinut parhaalla nisulla.'),
(1685337,58,19,147,15,'Hän lähettää sanansa maahan, nopeasti kiitää hänen käskynsä.'),
(1685338,58,19,147,16,'Hän antaa sataa lunta niinkuin villaa ja sirottaa härmää niinkuin tuhkaa.'),
(1685339,58,19,147,17,'Hän viskaa rakeitansa niinkuin leivänmuruja; kuka voi kestää hänen pakkastansa?'),
(1685340,58,19,147,18,'Hän lähettää sanansa ja sulattaa rakeet; hän panee tuulensa puhaltamaan, ja vedet virtaavat.'),
(1685341,58,19,147,19,'Hän ilmoittaa sanansa Jaakobille, käskynsä ja oikeutensa Israelille.'),
(1685342,58,19,147,20,'Niin hän ei ole tehnyt yhdellekään pakanakansalle, ja hänen oikeuksiansa ne eivät tunne. Halleluja!'),
(1685343,58,19,148,1,'Halleluja! Ylistäkää Herraa taivaista, ylistäkää häntä korkeuksissa.'),
(1685344,58,19,148,2,'Ylistäkää häntä, kaikki hänen enkelinsä, ylistäkää häntä, kaikki hänen sotajoukkonsa.'),
(1685345,58,19,148,3,'Ylistäkää häntä, aurinko ja kuu, ylistäkää häntä, kaikki kirkkaat tähdet.'),
(1685346,58,19,148,4,'Ylistäkää häntä, te taivasten taivaat, te vedet taivasten päällä.'),
(1685347,58,19,148,5,'Ylistäkööt ne Herran nimeä, sillä hän käski, ja ne tulivat luoduiksi.'),
(1685348,58,19,148,6,'Ja hän asetti ne olemaan aina ja iankaikkisesti, hän antoi niille lain, josta ne eivät poikkea.'),
(1685349,58,19,148,7,'Ylistäkää Herraa maasta, te merieläimet ja kaikki syvyydet,'),
(1685350,58,19,148,8,'tuli ja rakeet, lumi ja sumu, sinä myrskytuuli, joka panet hänen käskynsä toimeen,'),
(1685351,58,19,148,9,'te vuoret ja kaikki kukkulat, te hedelmäpuut ja kaikki setrit,'),
(1685352,58,19,148,10,'te pedot ja kaikki karja, te matelijat ja siivekkäät linnut,'),
(1685353,58,19,148,11,'te maan kuninkaat ja kaikki kansakunnat, te ruhtinaat ja kaikki maan tuomarit,'),
(1685354,58,19,148,12,'te nuorukaiset ynnä neitsyet, te vanhat yhdessä nuorten kanssa.'),
(1685355,58,19,148,13,'Ylistäkööt he Herran nimeä, sillä hänen nimensä yksin on korkea, hänen valtasuuruutensa ulottuu yli maan ja taivaan.'),
(1685356,58,19,148,14,'Hän on korottanut sarven kansallensa, että häntä ylistäisivät kaikki hänen hurskaansa, Israelin lapset, kansa, joka on häntä lähellä. Halleluja!'),
(1685357,58,19,149,1,'Halleluja! Veisatkaa Herralle uusi virsi: ylistysvirsi hänelle hurskasten seurakunnassa.'),
(1685358,58,19,149,2,'Iloitkoon Israel tekijästänsä, Siionin lapset riemuitkoot kuninkaastaan.'),
(1685359,58,19,149,3,'Ylistäkööt he karkeloiden hänen nimeänsä, soittakoot hänelle kiitosta vaskirummuilla ja kanteleilla.'),
(1685360,58,19,149,4,'Sillä Herra on mielistynyt kansaansa, hän kaunistaa nöyrät pelastuksella.'),
(1685361,58,19,149,5,'Iloitkoot hurskaat, veisaten hänen kunniaansa, riemuitkoot he vuoteissansa.'),
(1685362,58,19,149,6,'Jumalan ylistys on heidän suussansa, ja heidän kädessään kaksiteräinen miekka,'),
(1685363,58,19,149,7,'että he kostaisivat pakanoille, kurittaisivat kansakuntia,'),
(1685364,58,19,149,8,'panisivat kahleisiin heidän kuninkaansa ja jalkarautoihin heidän ylhäisensä'),
(1685365,58,19,149,9,'ja täyttäisivät heissä tuomion, joka on kirjoitettu. Tämä on kaikkien hänen hurskaittensa kunnia. Halleluja!'),
(1685366,58,19,150,1,'Halleluja! Ylistäkää Jumalaa hänen pyhäkössään, ylistäkää häntä hänen väkevyytensä taivaanvahvuuksissa.'),
(1685367,58,19,150,2,'Ylistäkää häntä hänen voimallisista teoistansa, ylistäkää häntä, sillä hänen herrautensa on suuri.'),
(1685368,58,19,150,3,'Ylistäkää häntä pasunan pauhulla, ylistäkää häntä harpuilla ja kanteleilla.'),
(1685369,58,19,150,4,'Ylistäkää häntä vaskirummuilla ja karkelolla, ylistäkää häntä kielisoittimilla ja huiluilla.'),
(1685370,58,19,150,5,'Ylistäkää häntä helisevillä kymbaaleilla, ylistäkää häntä kumisevilla kymbaaleilla.'),
(1685371,58,20,1,1,'Salomon, Daavidin pojan, Israelin kuninkaan, sananlaskut,'),
(1685372,58,20,1,2,'viisauden ja kurin oppimiseksi, ymmärryksen sanojen ymmärtämiseksi,'),
(1685373,58,20,1,3,'taitoa tuovan kurin, vanhurskauden, oikeuden ja vilpittömyyden saamiseksi,'),
(1685374,58,20,1,4,'mielevyyden antamiseksi yksinkertaisille, tiedon ja taidollisuuden nuorille.'),
(1685375,58,20,1,5,'Viisas kuulkoon ja saakoon oppia lisää, ja ymmärtäväinen hankkikoon elämänohjetta');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685376,58,20,1,6,'ymmärtääkseen sananlaskuja ja vertauksia, viisasten sanoja ja heidän ongelmiansa.'),
(1685377,58,20,1,7,'Herran pelko on tiedon alku; hullut pitävät halpana viisauden ja kurin.'),
(1685378,58,20,1,8,'Kuule, poikani, isäsi kuritusta äläkä hylkää äitisi opetusta,'),
(1685379,58,20,1,9,'sillä ne ovat ihana seppele sinun päähäsi ja käädyt sinun kaulaasi.'),
(1685380,58,20,1,10,'Poikani, jos synnintekijät sinua viekoittelevat, älä suostu.'),
(1685381,58,20,1,11,'Jos he sanovat: "Lähde mukaamme! Väijykäämme verta, vaanikaamme viatonta syyttömästi;'),
(1685382,58,20,1,12,'nielaiskaamme niinkuin tuonela heidät elävältä, ehyeltään, niinkuin hautaan vaipuvaiset;'),
(1685383,58,20,1,13,'me saamme kaikenlaista kallista tavaraa, täytämme talomme saaliilla;'),
(1685384,58,20,1,14,'heitä arpasi meidän kanssamme, yhteinen kukkaro olkoon meillä kaikilla" -'),
(1685385,58,20,1,15,'älä lähde, poikani, samalle tielle kuin he, pidätä jalkasi heidän poluiltansa.'),
(1685386,58,20,1,16,'Sillä heidän jalkansa juoksevat pahuuteen, kiiruhtavat vuodattamaan verta.'),
(1685387,58,20,1,17,'Sillä verkko on viritetty kaikille siivekkäille, niin että ne sen näkevät. - Mutta turhaan:'),
(1685388,58,20,1,18,'omaa vertansa he väijyvät, vaanivat omaa henkeänsä.'),
(1685389,58,20,1,19,'Näin käy jokaiselle väärän voiton pyytäjälle: se ottaa haltijaltaan hengen.'),
(1685390,58,20,1,20,'Viisaus huutaa kadulla, antaa äänensä kuulua toreilla;'),
(1685391,58,20,1,21,'meluisten katujen kulmissa se kutsuu, porttien ovilta kaupungissa sanansa sanoo:'),
(1685392,58,20,1,22,'Kuinka kauan te, yksinkertaiset, rakastatte yksinkertaisuutta, kuinka kauan pilkkaajilla on halu pilkkaan ja tyhmät vihaavat tietoa?'),
(1685393,58,20,1,23,'Kääntykää minun nuhdeltavikseni. Katso, minä vuodatan teille henkeäni, saatan sanani tiedoksenne.'),
(1685394,58,20,1,24,'Kun minä kutsuin ja te estelitte, kun ojensin kättäni eikä kenkään kuunnellut,'),
(1685395,58,20,1,25,'vaan te vieroksuitte kaikkia minun neuvojani, ette suostuneet minun nuhteisiini,'),
(1685396,58,20,1,26,'niin minäkin nauran teidän hädällenne, pilkkaan, kun tulee se, mitä te kauhistutte;'),
(1685397,58,20,1,27,'kun myrskynä tulee se, mitä te kauhistutte, kun hätänne saapuu tuulispäänä, kun päällenne tulee vaiva ja ahdistus.'),
(1685398,58,20,1,28,'Silloin he minua kutsuvat, mutta minä en vastaa, etsivät minua, mutta eivät löydä.'),
(1685399,58,20,1,29,'Koska he vihasivat tietoa, eivät valinneet osaksensa Herran pelkoa'),
(1685400,58,20,1,30,'eivätkä suostuneet minun neuvooni, vaan katsoivat kaiken minun nuhteluni halvaksi,'),
(1685401,58,20,1,31,'saavat he syödä oman vaelluksensa hedelmiä ja saavat kyllänsä omista hankkeistaan.'),
(1685402,58,20,1,32,'Sillä yksinkertaiset tappaa heidän oma luopumuksensa, ja tyhmät tuhoaa heidän oma suruttomuutensa.'),
(1685403,58,20,1,33,'Mutta joka minua kuulee, saa asua turvassa ja olla rauhassa onnettomuuden kauhuilta.'),
(1685404,58,20,2,1,'Poikani, jos sinä otat minun sanani varteen ja kätket mieleesi minun käskyni,'),
(1685405,58,20,2,2,'niin että herkistät korvasi viisaudelle ja taivutat sydämesi taitoon -'),
(1685406,58,20,2,3,'niin, jos kutsut ymmärrystä ja ääneesi huudat taitoa,'),
(1685407,58,20,2,4,'jos haet sitä kuin hopeata ja etsit sitä kuin aarretta,'),
(1685408,58,20,2,5,'silloin pääset ymmärtämään Herran pelon ja löydät Jumalan tuntemisen.'),
(1685409,58,20,2,6,'Sillä Herra antaa viisautta, hänen suustansa lähtee tieto ja taito.'),
(1685410,58,20,2,7,'Oikeamielisille hänellä on tallella pelastus, kilpi nuhteettomasti vaeltaville,'),
(1685411,58,20,2,8,'niin että hän suojaa oikeuden polut ja varjelee hurskaittensa tien.'),
(1685412,58,20,2,9,'Silloin ymmärrät vanhurskauden ja oikeuden ja vilpittömyyden - hyvyyden tien kaiken;'),
(1685413,58,20,2,10,'sillä viisaus tulee sydämeesi, ja tieto tulee sielullesi suloiseksi,'),
(1685414,58,20,2,11,'taidollisuus on sinua varjeleva ja ymmärrys suojeleva sinut.'),
(1685415,58,20,2,12,'Se pelastaa sinut pahojen tiestä, miehestä, joka kavalasti puhuu;'),
(1685416,58,20,2,13,'niistä, jotka ovat hyljänneet oikeat polut vaeltaaksensa pimeyden teitä;'),
(1685417,58,20,2,14,'niistä, jotka iloitsevat pahanteosta, riemuitsevat häijystä kavaluudesta,'),
(1685418,58,20,2,15,'joiden polut ovat mutkaiset ja jotka joutuvat väärään teillänsä. -'),
(1685419,58,20,2,16,'Se pelastaa sinut irstaasta naisesta, vieraasta vaimosta, joka sanoillansa liehakoitsee,'),
(1685420,58,20,2,17,'joka on hyljännyt nuoruutensa ystävän ja unhottanut Jumalansa liiton.'),
(1685421,58,20,2,18,'Sillä hänen huoneensa kallistuu kohti kuolemaa, hänen tiensä haamuja kohden.'),
(1685422,58,20,2,19,'Ei palaja kenkään, joka hänen luoksensa menee, eikä saavu elämän poluille.'),
(1685423,58,20,2,20,'Niin sinä vaellat hyvien tietä ja noudatat vanhurskasten polkuja.'),
(1685424,58,20,2,21,'Sillä oikeamieliset saavat asua maassa, ja nuhteettomat jäävät siihen jäljelle;'),
(1685425,58,20,2,22,'mutta jumalattomat hävitetään maasta, ja uskottomat siitä reväistään pois.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685426,58,20,3,1,'Poikani, älä unhota minun opetustani, vaan sinun sydämesi säilyttäköön minun käskyni;'),
(1685427,58,20,3,2,'sillä pitkää ikää, elinvuosia ja rauhaa ne sinulle kartuttavat.'),
(1685428,58,20,3,3,'Laupeus ja uskollisuus älkööt hyljätkö sinua. Sido ne kaulaasi, kirjoita ne sydämesi tauluun,'),
(1685429,58,20,3,4,'niin saat armon ja hyvän ymmärryksen Jumalan ja ihmisten silmien edessä.'),
(1685430,58,20,3,5,'Turvaa Herraan kaikesta sydämestäsi äläkä nojaudu omaan ymmärrykseesi.'),
(1685431,58,20,3,6,'Tunne hänet kaikilla teilläsi, niin hän sinun polkusi tasoittaa.'),
(1685432,58,20,3,7,'Älä ole viisas omissa silmissäsi. Pelkää Herraa ja karta pahaa.'),
(1685433,58,20,3,8,'Se on terveellistä sinun ruumiillesi ja virkistävää sinun luillesi.'),
(1685434,58,20,3,9,'Kunnioita Herraa antamalla varoistasi ja kaiken satosi parhaimmasta,'),
(1685435,58,20,3,10,'niin sinun jyväaittasi täyttyvät runsaudella, ja viini pursuu sinun kuurnistasi.'),
(1685436,58,20,3,11,'Poikani, älä pidä Herran kuritusta halpana äläkä kyllästy hänen rangaistukseensa;'),
(1685437,58,20,3,12,'sillä jota Herra rakastaa, sitä hän rankaisee, niinkuin isä poikaa, joka hänelle rakas on.'),
(1685438,58,20,3,13,'Autuas se ihminen, joka on löytänyt viisauden, ihminen, joka on saanut taidon.'),
(1685439,58,20,3,14,'Sillä parempi on hankkia sitä kuin hopeata, ja siitä saatu voitto on kultaa jalompi.'),
(1685440,58,20,3,15,'Se on kalliimpi kuin helmet, eivät mitkään kalleutesi vedä sille vertaa.'),
(1685441,58,20,3,16,'Pitkä ikä on sen oikeassa kädessä, vasemmassa rikkaus ja kunnia.'),
(1685442,58,20,3,17,'Sen tiet ovat suloiset tiet, sen polut rauhaisat kaikki tyynni.'),
(1685443,58,20,3,18,'Elämän puu on se niille, jotka siihen tarttuvat; onnelliset ne, jotka siitä pitävät kiinni.'),
(1685444,58,20,3,19,'Herra on viisaudella perustanut maan, taivaat taidolla vahvistanut.'),
(1685445,58,20,3,20,'Hänen toimestansa syvyydet kuohuivat esiin, ja pilvet pisaroivat kastetta.'),
(1685446,58,20,3,21,'Poikani, nämä älkööt häipykö näkyvistäsi, säilytä neuvokkuus ja taidollisuus,'),
(1685447,58,20,3,22,'niin ne ovat elämä sinun sielullesi ja kaunistus sinun kaulaasi.'),
(1685448,58,20,3,23,'Silloin sinä kuljet tiesi turvallisesti etkä loukkaa jalkaasi.'),
(1685449,58,20,3,24,'Kun menet maata, et pelkää mitään, ja maata mentyäsi on unesi makea.'),
(1685450,58,20,3,25,'Pääset peljästymästä äkkikauhistuksia ja turmiota, joka jumalattomat yllättää.'),
(1685451,58,20,3,26,'Sillä sinä saat luottaa Herraan, hän varjelee sinun jalkasi joutumasta kiinni.'),
(1685452,58,20,3,27,'Älä kiellä tarvitsevalta hyvää, milloin sitä tehdä voit.'),
(1685453,58,20,3,28,'Älä sano lähimmäisellesi: "Mene nyt ja tule toiste, huomenna minä annan", kun sinulla kuitenkin on.'),
(1685454,58,20,3,29,'Älä mieti pahaa lähimmäistäsi vastaan, kun hän luottavaisesti luonasi asuu.'),
(1685455,58,20,3,30,'Älä riitele kenenkään kanssa syyttä, kun ei toinen ole sinulle pahaa tehnyt.'),
(1685456,58,20,3,31,'Älä kadehdi väkivallan miestä äläkä hänen teitänsä omiksesi valitse;'),
(1685457,58,20,3,32,'sillä väärämielinen on Herralle kauhistus, mutta oikeamielisille hän on tuttava.'),
(1685458,58,20,3,33,'Herran kirous on jumalattoman huoneessa, mutta vanhurskasten asuinsijaa hän siunaa.'),
(1685459,58,20,3,34,'Pilkkaajille hänkin on pilkallinen, mutta nöyrille hän antaa armon.'),
(1685460,58,20,3,35,'Viisaat perivät kunnian, mutta tyhmäin osa on häpeä.'),
(1685461,58,20,4,1,'Kuulkaa, lapset, isän kuritusta ja kuunnelkaa oppiaksenne ymmärrystä.'),
(1685462,58,20,4,2,'Sillä minä annan teille hyvän neuvon, älkää hyljätkö minun opetustani.'),
(1685463,58,20,4,3,'Olinhan minäkin isäni poika, hento ja äitini ainokainen.'),
(1685464,58,20,4,4,'Ja isä minua opetti ja sanoi minulle: "Pitäköön sydämesi minun sanoistani kiinni, noudata minun käskyjäni, niin sinä saat elää.'),
(1685465,58,20,4,5,'Hanki viisautta, hanki ymmärrystä, älä sitä unhota, älä väisty pois minun suuni sanoista.'),
(1685466,58,20,4,6,'Älä sitä hylkää, niin se varjelee sinua; rakasta sitä, niin se sinua suojaa.'),
(1685467,58,20,4,7,'Viisauden alku on: hanki viisautta, ja kaikella muulla hankkimallasi hanki ymmärrystä.'),
(1685468,58,20,4,8,'Anna sille korkea arvo, niin se sinut korottaa, se kunnioittaa sinua, jos sen syliisi suljet;'),
(1685469,58,20,4,9,'se panee päähäsi ihanan seppeleen ja lahjoittaa sinulle kauniin kruunun."'),
(1685470,58,20,4,10,'Kuule, poikani, ja ota sanani varteen, niin elämäsi vuodet enentyvät.'),
(1685471,58,20,4,11,'Minä neuvon sinut viisauden tielle, ohjaan sinut oikeille teille.'),
(1685472,58,20,4,12,'Käydessäsi eivät askeleesi ahtaalle joudu; juostessasi et kompastu.'),
(1685473,58,20,4,13,'Tartu kiinni kuritukseen äläkä hellitä; säilytä se, sillä se on sinun elämäsi.'),
(1685474,58,20,4,14,'Älä lähde jumalattomien polulle, älä astu pahojen tielle.'),
(1685475,58,20,4,15,'Anna sen olla, älä mene sille, poikkea pois ja mene ohitse.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685476,58,20,4,16,'Sillä eivät he saa nukkua, elleivät pahaa tee; se riistää heiltä unen, elleivät ole ketään kaataneet.'),
(1685477,58,20,4,17,'Niin he syövät leipänään jumalattomuutta, juovat viininään väkivallan tekoja.'),
(1685478,58,20,4,18,'Mutta vanhurskasten polku on kuin aamurusko, joka kirkastuu kirkastumistaan sydänpäivään saakka.'),
(1685479,58,20,4,19,'Jumalattomain tie on kuin pimeys: eivät he tiedä, mihin kompastuvat.'),
(1685480,58,20,4,20,'Poikani, kuuntele minun puhettani, kallista korvasi minun sanoilleni.'),
(1685481,58,20,4,21,'Älkööt ne väistykö silmistäsi, kätke ne sydämesi sisimpään;'),
(1685482,58,20,4,22,'sillä ne ovat elämä sille, joka ne löytää, ja lääke koko hänen ruumiillensa.'),
(1685483,58,20,4,23,'Yli kaiken varottavan varjele sydämesi, sillä sieltä elämä lähtee.'),
(1685484,58,20,4,24,'Poista itsestäsi suun kavaluus, ja karkoita luotasi huulten vääryys.'),
(1685485,58,20,4,25,'Katsokoot sinun silmäsi suoraan, eteenpäin olkoon katseesi luotu.'),
(1685486,58,20,4,26,'Tasoita polku jaloillesi, ja kaikki sinun tiesi olkoot vakaat.'),
(1685487,58,20,4,27,'Älä poikkea oikeaan, älä vasempaan, väistä jalkasi pahasta.'),
(1685488,58,20,5,1,'Poikani, kuuntele minun viisauttani, kallista korvasi minun taidolleni'),
(1685489,58,20,5,2,'ottaaksesi vaarin taidollisuudesta, ja huulesi säilyttäkööt tiedon.'),
(1685490,58,20,5,3,'Sillä hunajaa tiukkuvat vieraan vaimon huulet, hänen suunsa on öljyä liukkaampi.'),
(1685491,58,20,5,4,'Mutta lopulta hän on karvas kuin koiruoho, terävä kuin kaksiteräinen miekka.'),
(1685492,58,20,5,5,'Hänen jalkansa kulkevat alas kuolemaan, tuonelaan vetävät hänen askeleensa.'),
(1685493,58,20,5,6,'Ei käy hän elämän tasaista polkua, hänen tiensä horjuvat hänen huomaamattaan.'),
(1685494,58,20,5,7,'Niinpä, lapset, kuulkaa minua, älkää väistykö minun suuni sanoista.'),
(1685495,58,20,5,8,'Pidä tiesi kaukana tuollaisesta äläkä lähesty hänen majansa ovea,'),
(1685496,58,20,5,9,'ettet antaisi muille kunniaasi etkä vuosiasi armottomalle,'),
(1685497,58,20,5,10,'ettei sinun tavarasi ravitsisi vieraita, sinun vaivannäkösi joutuisi toisen taloon'),
(1685498,58,20,5,11,'ja ettet lopulta päätyisi huokailemaan ruumiisi ja lihasi riutuessa'),
(1685499,58,20,5,12,'ja sanomaan: "Miksi minä kuritusta vihasin ja sydämeni halveksui nuhdetta?'),
(1685500,58,20,5,13,'Miksi en kuullut neuvojaini ääntä, kallistanut korvaani opettajilleni?'),
(1685501,58,20,5,14,'Olin joutua kokonaan turmion omaksi keskellä seurakunnan ja kansankokouksen."'),
(1685502,58,20,5,15,'Juo vettä omasta säiliöstäsi, sitä, mikä omasta kaivostasi juoksee.'),
(1685503,58,20,5,16,'Vuotaisivatko sinun lähteesi kadulle, toreille sinun vesiojasi!'),
(1685504,58,20,5,17,'Olkoot ne sinun omasi yksin, älkööt vierasten sinun ohessasi.'),
(1685505,58,20,5,18,'Olkoon sinun lähteesi siunattu, ja iloitse nuoruutesi vaimosta.'),
(1685506,58,20,5,19,'Armas peura, suloinen vuorikauris - hänen rintansa sinua aina riemulla ravitkoot, hurmautuos alati hänen rakkaudestaan.'),
(1685507,58,20,5,20,'Miksi, poikani, hurmautuisit irstaaseen naiseen ja syleilisit vieraan vaimon povea?'),
(1685508,58,20,5,21,'Sillä Herran silmien edessä ovat miehen tiet, ja hän tutkii kaikki hänen polkunsa.'),
(1685509,58,20,5,22,'Jumalattoman vangitsevat hänen rikoksensa, ja hän tarttuu oman syntinsä pauloihin.'),
(1685510,58,20,5,23,'Kurittomuuteensa hän kuolee ja suistuu harhaan suuressa hulluudessaan.'),
(1685511,58,20,6,1,'Poikani, jos olet ketä lähimmäisellesi taannut, lyönyt kättä vieraalle;'),
(1685512,58,20,6,2,'jos olet kietoutunut oman suusi sanoihin, joutunut suusi sanoista kiinni,'),
(1685513,58,20,6,3,'niin tee toki, poikani, pelastuaksesi tämä, koska olet joutunut lähimmäisesi kouriin: Mene, heittäydy maahan ja ahdista lähimmäistäsi;'),
(1685514,58,20,6,4,'älä suo silmillesi unta äläkä silmäluomillesi lepoa.'),
(1685515,58,20,6,5,'Pelastaudu käsistä niinkuin gaselli, niinkuin lintu pyydystäjän käsistä.'),
(1685516,58,20,6,6,'Mene, laiska, muurahaisen tykö, katso sen menoja ja viisastu.'),
(1685517,58,20,6,7,'Vaikka sillä ei ole ruhtinasta, ei päällysmiestä eikä hallitsijaa,'),
(1685518,58,20,6,8,'se kuitenkin hankkii leipänsä kesällä ja kokoaa varastoon ruokansa elonaikana.'),
(1685519,58,20,6,9,'Kuinka kauan sinä, laiska, makaat, milloinka nouset unestasi?'),
(1685520,58,20,6,10,'Nuku vielä vähän, torku vähän, makaa vähän ristissä käsin,'),
(1685521,58,20,6,11,'niin köyhyys käy päällesi niinkuin rosvo ja puute niinkuin asestettu mies.'),
(1685522,58,20,6,12,'Kelvoton ihminen, väärä mies on se, joka kulkee suu täynnä vilppiä,'),
(1685523,58,20,6,13,'silmää iskee, jaloillaan merkkiä antaa, sormillansa viittoo,'),
(1685524,58,20,6,14,'kavaluus mielessä, pahaa aina hankitsee, riitoja rakentaa.'),
(1685525,58,20,6,15,'Sentähden hänen turmionsa tulee yhtäkkiä, tuokiossa hänet rusennetaan, eikä apua ole.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685526,58,20,6,16,'Näitä kuutta Herra vihaa, ja seitsemää hänen sielunsa kauhistuu:'),
(1685527,58,20,6,17,'ylpeitä silmiä, valheellista kieltä, käsiä, jotka vuodattavat viatonta verta,'),
(1685528,58,20,6,18,'sydäntä, joka häijyjä juonia miettii, jalkoja, jotka kiiruusti juoksevat pahaan,'),
(1685529,58,20,6,19,'väärää todistajaa, joka valheita puhuu, ja riidan rakentajaa veljesten kesken.'),
(1685530,58,20,6,20,'Säilytä, poikani, isäsi käsky äläkä hylkää äitisi opetusta.'),
(1685531,58,20,6,21,'Pidä ne aina sydämellesi sidottuina, kääri ne kaulasi ympärille.'),
(1685532,58,20,6,22,'Kulkiessasi ne sinua taluttakoot, maatessasi sinua vartioikoot, herätessäsi sinua puhutelkoot.'),
(1685533,58,20,6,23,'Sillä käsky on lamppu, opetus on valo, ja kurittava nuhde on elämän tie,'),
(1685534,58,20,6,24,'että varjeltuisit pahasta naisesta, vieraan vaimon liukkaasta kielestä.'),
(1685535,58,20,6,25,'Älköön sydämesi himoitko hänen kauneuttaan, älköönkä hän sinua katseillaan vangitko.'),
(1685536,58,20,6,26,'Sillä porttonaisen tähden menee leipäkakkukin, ja naitu nainen pyydystää kallista sielua.'),
(1685537,58,20,6,27,'Voiko kukaan kuljettaa tulta helmassaan, puvun häneltä palamatta?'),
(1685538,58,20,6,28,'Voiko kukaan kävellä hiilloksella, jalkain häneltä kärventymättä?'),
(1685539,58,20,6,29,'Samoin käy sen, joka menee lähimmäisensä vaimon luo: ei jää rankaisematta kukaan, joka häneen kajoaa.'),
(1685540,58,20,6,30,'Eikö halveksita varasta, vaikka hän olisi nälissään varastanut hengenpiteikseen?'),
(1685541,58,20,6,31,'Onhan hänen, jos tavataan, seitsenkertaisesti korvattava, annettava kaikki talonsa varat.'),
(1685542,58,20,6,32,'Joka vaimon kanssa avion rikkoo, on mieletön; itsensä menettää, joka niin tekee.'),
(1685543,58,20,6,33,'Hän saa vaivan ja häpeän, eikä hänen häväistystään pyyhitä pois.'),
(1685544,58,20,6,34,'Sillä luulevaisuus nostaa miehen vihan, ja säälimätön on hän koston päivänä.'),
(1685545,58,20,6,35,'Ei hän huoli mistään lunastusmaksusta, ei suostu, vaikka kuinka lahjaasi lisäät.'),
(1685546,58,20,7,1,'Poikani, noudata minun sanojani ja kätke mieleesi minun käskyni.'),
(1685547,58,20,7,2,'Noudata minun käskyjäni, niin saat elää, säilytä opetukseni kuin silmäteräsi.'),
(1685548,58,20,7,3,'Sido ne kiinni sormiisi, kirjoita ne sydämesi tauluun.'),
(1685549,58,20,7,4,'Sano viisaudelle: "Sinä olet sisareni", kutsu ymmärrystä sukulaiseksi,'),
(1685550,58,20,7,5,'että varjeltuisit irstaalta naiselta, vieraalta vaimolta, joka sanoillansa liehakoitsee.'),
(1685551,58,20,7,6,'Sillä minä katselin taloni ikkunasta ristikon läpi,'),
(1685552,58,20,7,7,'ja minä näin yksinkertaisten joukossa, havaitsin poikain seassa nuorukaisen, joka oli mieltä vailla.'),
(1685553,58,20,7,8,'Hän kulki katua erään naisen kulmaukseen ja asteli hänen majaansa päin'),
(1685554,58,20,7,9,'päivän illaksi hämärtyessä, yön aikana, pimeässä.'),
(1685555,58,20,7,10,'Ja katso, nainen tulee häntä vastaan, porton puvussa, kavala sydämeltä.'),
(1685556,58,20,7,11,'Hän on levoton ja hillitön, eivät pysy hänen jalkansa kotona;'),
(1685557,58,20,7,12,'milloin hän on kadulla, milloin toreilla, ja väijyy joka kulmassa.'),
(1685558,58,20,7,13,'Hän tarttui nuorukaiseen, suuteli häntä ja julkeasti katsoen sanoi hänelle:'),
(1685559,58,20,7,14,'"Minun oli uhrattava yhteysuhri, tänä päivänä olen täyttänyt lupaukseni.'),
(1685560,58,20,7,15,'Sentähden läksin ulos sinua vastaan, etsiäkseni sinua, ja olen sinut löytänyt.'),
(1685561,58,20,7,16,'Olen leposijalleni peitteitä levittänyt, kirjavaa Egyptin liinavaatetta.'),
(1685562,58,20,7,17,'Vuoteeseeni olen pirskoitellut mirhaa, aloeta ja kanelia.'),
(1685563,58,20,7,18,'Tule, nauttikaamme lemmestä aamuun asti, riemuitkaamme rakkaudesta.'),
(1685564,58,20,7,19,'Sillä mieheni ei ole kotona, hän meni matkalle kauas.'),
(1685565,58,20,7,20,'Rahakukkaron hän otti mukaansa ja tulee kotiin vasta täydenkuun päiväksi."'),
(1685566,58,20,7,21,'Hän taivutti hänet paljolla houkuttelullaan, vietteli liukkailla huulillansa:'),
(1685567,58,20,7,22,'äkkiä hän lähti hänen jälkeensä, niinkuin härkä menee teuraaksi, niinkuin hullu jalkaraudoissa kuritettavaksi,'),
(1685568,58,20,7,23,'niinkuin lintu kiiruhtaa paulaan; eikä tiennyt, että oli henkeänsä kaupalla, kunnes nuoli lävisti hänen maksansa.'),
(1685569,58,20,7,24,'Sentähden, poikani, kuulkaa minua, kuunnelkaa minun suuni sanoja.'),
(1685570,58,20,7,25,'Älköön poiketko sydämesi tuon naisen teille, älä eksy hänen poluillensa.'),
(1685571,58,20,7,26,'Sillä paljon on surmattuja, hänen kaatamiaan, lukuisasti niitä, jotka hän on kaikki tappanut.'),
(1685572,58,20,7,27,'Hänen majastaan käyvät tuonelan tiet, jotka vievät alas tuonelan kammioihin.'),
(1685573,58,20,8,1,'Eikö viisaus kutsu, eikö taito anna äänensä kuulua?'),
(1685574,58,20,8,2,'Ylös kummuille, tien viereen, polkujen risteyksiin hän on asettunut.'),
(1685575,58,20,8,3,'Porttien pielissä, kaupungin portilla, oviaukoissa hän huutaa:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685576,58,20,8,4,'"Teitä minä kutsun, miehet, ja ihmislapsille kaikuu minun ääneni.'),
(1685577,58,20,8,5,'Tulkaa, yksinkertaiset, mieleviksi; tulkaa järkeviksi, te tyhmät.'),
(1685578,58,20,8,6,'Kuulkaa, sillä jalosti minä puhun, ja avaan huuleni puhumaan, mikä oikein on;'),
(1685579,58,20,8,7,'sillä totuutta minun suuni haastaa, ja jumalattomuus on minun huulilleni kauhistus.'),
(1685580,58,20,8,8,'Vanhurskaat ovat minun suuni sanat kaikki, ei ole niissä mitään petollista, ei väärää.'),
(1685581,58,20,8,9,'Ne ovat kaikki oikeat ymmärtäväiselle, suorat niille, jotka löysivät tiedon.'),
(1685582,58,20,8,10,'Ottakaa minun kuritukseni, älkääkä hopeata, ja tieto ennen valituinta kultaa.'),
(1685583,58,20,8,11,'Sillä parempi on viisaus kuin helmet, eivät mitkään kalleudet vedä sille vertaa.'),
(1685584,58,20,8,12,'Minä, viisaus, olen perehtynyt mielevyyteen, olen löytänyt tiedon ja taidollisuuden.'),
(1685585,58,20,8,13,'Herran pelko on pahan vihaamista. Kopeutta ja ylpeyttä, pahaa tietä ja kavalaa suuta minä vihaan.'),
(1685586,58,20,8,14,'Minulla on neuvo ja neuvokkuus; minä olen ymmärrys, minulla on voima.'),
(1685587,58,20,8,15,'Minun avullani kuninkaat hallitsevat, ruhtinaat säädöksensä vanhurskaasti säätävät.'),
(1685588,58,20,8,16,'Minun avullani päämiehet vallitsevat ja ylhäiset, maan tuomarit kaikki.'),
(1685589,58,20,8,17,'Minä rakastan niitä, jotka minua rakastavat, ja jotka minua varhain etsivät, ne löytävät minut.'),
(1685590,58,20,8,18,'Minun tykönäni on rikkaus ja kunnia, ikivanha varallisuus ja vanhurskaus.'),
(1685591,58,20,8,19,'Minun hedelmäni on parempi kuin kulta, kuin puhtain kulta, minun antamani voitto valituinta hopeata parempi.'),
(1685592,58,20,8,20,'Minä vaellan vanhurskauden polkua, oikeuden teitten keskikohtaa,'),
(1685593,58,20,8,21,'antaakseni niille, jotka minua rakastavat, pysyvän perinnön ja täyttääkseni heidän aarrekammionsa.'),
(1685594,58,20,8,22,'Herra loi minut töittensä esikoiseksi, ensimmäiseksi teoistaan, ennen aikojen alkua.'),
(1685595,58,20,8,23,'Iankaikkisuudesta minä olen asetettu olemaan, alusta asti, hamasta maan ikiajoista.'),
(1685596,58,20,8,24,'Ennenkuin syvyyksiä oli, synnyin minä, ennenkuin oli lähteitä, vedestä rikkaita.'),
(1685597,58,20,8,25,'Ennenkuin vuoret upotettiin paikoilleen, ennen kukkuloita, synnyin minä,'),
(1685598,58,20,8,26,'kun hän ei vielä ollut tehnyt maata, ei mantua, ei maanpiirin tomujen alkuakaan.'),
(1685599,58,20,8,27,'Kun hän taivaat valmisti, olin minä siinä, kun hän veti piirin syvyyden pinnalle,'),
(1685600,58,20,8,28,'kun hän teki vahvoiksi pilvet korkeudessa, kun syvyyden lähteet saivat voiman,'),
(1685601,58,20,8,29,'kun hän merelle asetti sen rajat, että vedet eivät kävisi hänen käskynsä yli, kun hän vahvisti maan perustukset,'),
(1685602,58,20,8,30,'silloin minä hänen sivullansa hoidokkina olin, ihastuksissani olin päivästä päivään ja leikitsin hänen edessänsä kaikin ajoin;'),
(1685603,58,20,8,31,'leikitsin hänen maanpiirinsä päällä, ja ihastukseni olivat ihmislapset.'),
(1685604,58,20,8,32,'Siis te, lapset, kuulkaa minua; autuaat ne, jotka noudattavat minun teitäni!'),
(1685605,58,20,8,33,'Kuritusta kuulkaa, niin viisastutte; älkää sen antako mennä menojaan.'),
(1685606,58,20,8,34,'Autuas se ihminen, joka minua kuulee, valvoo minun ovillani päivästä päivään, vartioitsee minun ovieni pieliä!'),
(1685607,58,20,8,35,'Sillä joka minut löytää, löytää elämän ja saa Herran mielisuosion.'),
(1685608,58,20,8,36,'Mutta joka menee minusta harhaan, saa vahingon sielullensa; kaikki, jotka minua vihaavat, rakastavat kuolemaa."'),
(1685609,58,20,9,1,'Viisaus on talonsa rakentanut, veistänyt seitsemän pylvästänsä.'),
(1685610,58,20,9,2,'Hän on teuraansa teurastanut, viininsä sekoittanut ja myöskin pöytänsä kattanut.'),
(1685611,58,20,9,3,'Hän on palvelijattarensa lähettänyt kutsua kuuluttamaan kaupungin kumpujen rinteiltä:'),
(1685612,58,20,9,4,'"Joka yksinkertainen on, poiketkoon tänne". Sille, joka on mieltä vailla, hän sanoo:'),
(1685613,58,20,9,5,'"Tulkaa, syökää minun leipääni ja juokaa viiniä, minun sekoittamaani.'),
(1685614,58,20,9,6,'Hyljätkää yksinkertaisuus, niin saatte elää, ja astukaa ymmärryksen tielle." -'),
(1685615,58,20,9,7,'Joka pilkkaajaa ojentaa, saa itsellensä häpeän, ja häpeäpilkun se, joka jumalatonta nuhtelee.'),
(1685616,58,20,9,8,'Älä nuhtele pilkkaajaa, ettei hän sinua vihaisi; nuhtele viisasta, niin hän sinua rakastaa.'),
(1685617,58,20,9,9,'Anna viisaalle, niin hän yhä viisastuu; opeta vanhurskasta, niin hän saa oppia lisää.'),
(1685618,58,20,9,10,'Herran pelko on viisauden alku, ja Pyhimmän tunteminen on ymmärrystä. -'),
(1685619,58,20,9,11,'"Sillä minun avullani päiväsi enenevät ja jatkuvat elämäsi vuodet.'),
(1685620,58,20,9,12,'Jos olet viisas, olet omaksi hyväksesi viisas; ja jos olet pilkkaaja, saat sinä sen yksin kestää."'),
(1685621,58,20,9,13,'Tyhmyys on nainen, levoton ja yksinkertainen, eikä hän mistään mitään tiedä.'),
(1685622,58,20,9,14,'Hän istuu talonsa ovella, istuimella kaupungin kummuilla,'),
(1685623,58,20,9,15,'kutsumassa ohikulkijoita, jotka käyvät polkujansa suoraan eteenpäin:'),
(1685624,58,20,9,16,'"Joka yksinkertainen on, poiketkoon tänne". Ja sille, joka on mieltä vailla, hän sanoo:'),
(1685625,58,20,9,17,'"Varastettu vesi on makeata, ja salattu leipä on suloista".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685626,58,20,9,18,'Eikä toinen tiedä, että haamuja on siellä, että hänen kutsuvieraansa ovat tuonelan laaksoissa.'),
(1685627,58,20,10,1,'Salomon sananlaskut. Viisas poika on isällensä iloksi, mutta tyhmä poika on äidillensä murheeksi.'),
(1685628,58,20,10,2,'Vääryyden aarteet eivät auta, mutta vanhurskaus vapahtaa kuolemasta.'),
(1685629,58,20,10,3,'Herra ei salli vanhurskaan nälkää nähdä, mutta jumalattomien himon hän luotansa työntää.'),
(1685630,58,20,10,4,'Köyhtyy, joka laiskasti kättä käyttää, mutta ahkerain käsi rikastuttaa.'),
(1685631,58,20,10,5,'Taitava poika kokoaa kesällä, kunnoton poika elonaikana nukkuu.'),
(1685632,58,20,10,6,'Siunaus on vanhurskaan pään päällä, mutta väkivaltaa kätkee jumalattomien suu.'),
(1685633,58,20,10,7,'Vanhurskaan muistoa siunataan, mutta jumalattomien nimi lahoaa.'),
(1685634,58,20,10,8,'Viisassydäminen ottaa käskyt varteen, mutta hulluhuulinen kukistuu.'),
(1685635,58,20,10,9,'Joka nuhteettomasti vaeltaa, vaeltaa turvassa, jonka tiet ovat väärät, se joutuu ilmi.'),
(1685636,58,20,10,10,'Joka silmää iskee, saa aikaan tuskaa, ja hulluhuulinen kukistuu.'),
(1685637,58,20,10,11,'Vanhurskaan suu on elämän lähde, mutta jumalattomien suu kätkee väkivaltaa.'),
(1685638,58,20,10,12,'Viha virittää riitoja, mutta rakkaus peittää rikkomukset kaikki.'),
(1685639,58,20,10,13,'Ymmärtäväisen huulilta löytyy viisaus, mutta joka on mieltä vailla, sille vitsa selkään!'),
(1685640,58,20,10,14,'Viisaat kätkevät, minkä tietävät, mutta hullun suu on läheinen turmio.'),
(1685641,58,20,10,15,'Rikkaan tavara on hänen vahva kaupunkinsa, mutta vaivaisten köyhyys on heidän turmionsa.'),
(1685642,58,20,10,16,'Vanhurskaan hankkima on elämäksi, jumalattoman saalis koituu synniksi.'),
(1685643,58,20,10,17,'Kuritusta noudattava on elämän tiellä, mutta nuhteet hylkäävä eksyy.'),
(1685644,58,20,10,18,'Joka salavihaa pitää, sen huulilla on valhe, ja joka parjausta levittää, on tyhmä.'),
(1685645,58,20,10,19,'Missä on paljon sanoja, siinä ei syntiä puutu; mutta joka huulensa hillitsee, se on taitava.'),
(1685646,58,20,10,20,'Vanhurskaan kieli on valituin hopea, jumalattomien äly on tyhjän veroinen.'),
(1685647,58,20,10,21,'Vanhurskaan huulet kaitsevat monia, mutta hullut kuolevat mielettömyyteensä.'),
(1685648,58,20,10,22,'Herran siunaus rikkaaksi tekee, ei oma vaiva siihen mitään lisää.'),
(1685649,58,20,10,23,'Tyhmälle on iloksi ilkityön teko, mutta ymmärtäväiselle miehelle viisaus.'),
(1685650,58,20,10,24,'Mitä jumalaton pelkää, se häntä kohtaa; mutta mitä vanhurskaat halajavat, se annetaan.'),
(1685651,58,20,10,25,'Tuulispään käytyä ei jumalatonta enää ole, mutta vanhurskaan perustus pysyy iäti.'),
(1685652,58,20,10,26,'Mitä hapan hampaille ja savu silmille, sitä laiska lähettäjillensä.'),
(1685653,58,20,10,27,'Herran pelko elinpäiviä jatkaa, mutta jumalattomien vuodet lyhenevät.'),
(1685654,58,20,10,28,'Vanhurskasten odotus koituu iloksi, mutta jumalattomien toivo hukkuu.'),
(1685655,58,20,10,29,'Herran johdatus on nuhteettoman turva, mutta väärintekijäin turmio.'),
(1685656,58,20,10,30,'Vanhurskas ei ikinä horju, mutta jumalattomat eivät saa asua maassa.'),
(1685657,58,20,10,31,'Vanhurskaan suu kasvaa viisauden hedelmän, mutta kavala kieli hävitetään.'),
(1685658,58,20,10,32,'Vanhurskaan huulet tietävät, mikä otollista on, mutta jumalattomien suu on sulaa kavaluutta.'),
(1685659,58,20,11,1,'Väärä vaaka on Herralle kauhistus, mutta täysi paino on hänelle otollinen.'),
(1685660,58,20,11,2,'Mihin ylpeys tulee, sinne tulee häpeäkin, mutta nöyräin tykönä on viisaus.'),
(1685661,58,20,11,3,'Oikeamielisiä ohjaa heidän nuhteettomuutensa, mutta uskottomat hävittää heidän vilppinsä.'),
(1685662,58,20,11,4,'Ei auta tavara vihan päivänä, mutta vanhurskaus vapahtaa kuolemasta.'),
(1685663,58,20,11,5,'Nuhteettoman vanhurskaus tasoittaa hänen tiensä, mutta jumalaton sortuu jumalattomuuteensa.'),
(1685664,58,20,11,6,'Oikeamieliset vapahtaa heidän vanhurskautensa, mutta uskottomat vangitsee heidän oma himonsa.'),
(1685665,58,20,11,7,'Jumalattoman ihmisen kuollessa hukkuu hänen toivonsa, ja vääräin odotus hukkuu.'),
(1685666,58,20,11,8,'Vanhurskas pelastetaan hädästä, ja jumalaton joutuu hänen sijaansa.'),
(1685667,58,20,11,9,'Rietas suullansa turmelee lähimmäisensä, mutta taito on vanhurskaitten pelastus.'),
(1685668,58,20,11,10,'Vanhurskaitten onnesta kaupunki iloitsee, ja jumalattomain hukkumisesta syntyy riemu.'),
(1685669,58,20,11,11,'Oikeamielisten siunauksesta kaupunki kohoaa, mutta jumalattomain suu sitä hajottaa.'),
(1685670,58,20,11,12,'Mieltä vailla on, joka lähimmäistänsä halveksii, mutta ymmärtäväinen mies on vaiti.'),
(1685671,58,20,11,13,'Joka panettelijana käy, ilmaisee salaisuuden, mutta jolla luotettava henki on, se säilyttää asian.'),
(1685672,58,20,11,14,'Missä ohjausta ei ole, sortuu kansa, mutta neuvonantajain runsaus tuo menestyksen.'),
(1685673,58,20,11,15,'Joka vierasta takaa, sen käy pahoin, mutta joka kädenlyöntiä vihaa, se on turvattu.'),
(1685674,58,20,11,16,'Suloinen nainen saa kunniaa, ja voimalliset saavat rikkautta.'),
(1685675,58,20,11,17,'Armelias mies tekee hyvää itsellensä, mutta armoton syöksee onnettomuuteen oman lihansa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685676,58,20,11,18,'Jumalaton hankkii pettäväistä voittoa, mutta joka vanhurskautta kylvää, saa pysyvän palkan.'),
(1685677,58,20,11,19,'Joka on vakaa vanhurskaudessa, saa elämän; mutta joka pahaa tavoittaa, saa kuoleman.'),
(1685678,58,20,11,20,'Väärämieliset ovat Herralle kauhistus, mutta nuhteettomasti vaeltaviin hän mielistyy.'),
(1685679,58,20,11,21,'Totisesti: paha ei jää rankaisematta, mutta vanhurskasten jälkeläiset pelastuvat.'),
(1685680,58,20,11,22,'Kultarengas sian kärsässä on kaunis nainen, älyä vailla.'),
(1685681,58,20,11,23,'Vanhurskaitten halajaminen vie onneen, jumalattomien toivo vihaan.'),
(1685682,58,20,11,24,'Toinen on antelias ja saa yhä lisää, toinen säästää yli kohtuuden ja vain köyhtyy.'),
(1685683,58,20,11,25,'Hyväätekeväinen sielu tulee ravituksi, ja joka muita virvoittaa, se itse kostuu.'),
(1685684,58,20,11,26,'Joka viljan pitää takanaan, sitä kansa kiroaa, mutta joka viljan kaupaksi antaa, sen pään päälle tulee siunaus.'),
(1685685,58,20,11,27,'Joka hyvään pyrkii, etsii sitä, mikä otollista on, mutta joka pahaa etsii, sille se tulee.'),
(1685686,58,20,11,28,'Joka rikkauteensa luottaa, se kukistuu, mutta vanhurskaat viheriöitsevät niinkuin lehvä.'),
(1685687,58,20,11,29,'Joka talonsa rappiolle saattaa, perii tuulta, ja hullu joutuu viisaan orjaksi.'),
(1685688,58,20,11,30,'Vanhurskaan hedelmä on elämän puu, ja viisas voittaa sieluja.'),
(1685689,58,20,11,31,'Katso, vanhurskas saa palkkansa maan päällä, saati sitten jumalaton ja syntinen.'),
(1685690,58,20,12,1,'Tietoa rakastaa, joka kuritusta rakastaa, mutta järjetön se, joka nuhdetta vihaa.'),
(1685691,58,20,12,2,'Hyvä saa Herran mielisuosion, mutta juonittelijan hän tuomitsee syylliseksi.'),
(1685692,58,20,12,3,'Ei ihminen kestä jumalattomuuden varassa, mutta vanhurskasten juuri on horjumaton.'),
(1685693,58,20,12,4,'Kelpo vaimo on puolisonsa kruunu, mutta kunnoton on kuin mätä hänen luissansa.'),
(1685694,58,20,12,5,'Vanhurskasten aivoitukset ovat oikeat, jumalattomien hankkeet petolliset.'),
(1685695,58,20,12,6,'Jumalattomien puheet väijyvät verta, mutta oikeamieliset pelastaa heidän suunsa.'),
(1685696,58,20,12,7,'Jumalattomat kukistuvat olemattomiin, mutta vanhurskasten huone pysyy.'),
(1685697,58,20,12,8,'Ymmärryksensä mukaan miestä kiitetään, mutta nurjasydämistä halveksitaan.'),
(1685698,58,20,12,9,'Parempi halpa-arvoinen, jolla on palvelija, kuin rehentelijä, joka on vailla leipää.'),
(1685699,58,20,12,10,'Vanhurskas tuntee, mitä hänen karjansa kaipaa, mutta jumalattomain sydän on armoton.'),
(1685700,58,20,12,11,'Joka peltonsa viljelee, saa leipää kyllin, mutta tyhjän tavoittelija on mieltä vailla.'),
(1685701,58,20,12,12,'Jumalaton himoitsee pahojen saalista, mutta vanhurskasten juuri on antoisa.'),
(1685702,58,20,12,13,'Huulten rikkomus on paha ansa, mutta vanhurskas pääsee hädästä.'),
(1685703,58,20,12,14,'Suunsa hedelmästä saa kyllälti hyvää, ja ihmisen eteen kiertyvät hänen kättensä työt.'),
(1685704,58,20,12,15,'Hullun tie on hänen omissa silmissään oikea, mutta joka neuvoa kuulee, on viisas.'),
(1685705,58,20,12,16,'Hullun suuttumus tulee kohta ilmi, mutta mielevä peittää kärsimänsä häpeän.'),
(1685706,58,20,12,17,'Toden puhuja lausuu oikeuden, mutta väärä todistaja petoksen.'),
(1685707,58,20,12,18,'Moni viskoo sanoja kuin miekanpistoja, mutta viisasten kieli on lääke.'),
(1685708,58,20,12,19,'Totuuden huulet pysyvät iäti, mutta valheen kieli vain tuokion.'),
(1685709,58,20,12,20,'Jotka pahaa miettivät, niillä on mielessä petos, mutta jotka rauhaan neuvovat, niille tulee ilo.'),
(1685710,58,20,12,21,'Ei tule turmiota vanhurskaalle, mutta jumalattomat ovat onnettomuutta täynnä.'),
(1685711,58,20,12,22,'Herralle kauhistus ovat valheelliset huulet, mutta teoissaan uskolliset ovat hänelle otolliset.'),
(1685712,58,20,12,23,'Mielevä ihminen peittää tietonsa, mutta tyhmäin sydän huutaa julki hulluutensa.'),
(1685713,58,20,12,24,'Ahkerain käsi saa hallita, mutta laiska joutuu työveron alaiseksi.'),
(1685714,58,20,12,25,'Huoli painaa alas miehen mielen, mutta hyvä sana sen ilahuttaa.'),
(1685715,58,20,12,26,'Vanhurskas opastaa lähimmäistänsä, mutta jumalattomat eksyttää heidän oma tiensä.'),
(1685716,58,20,12,27,'Laiska ei saa ajetuksi itselleen riistaa, mutta ahkeruus on ihmiselle kallis tavara.'),
(1685717,58,20,12,28,'Vanhurskauden polulla on elämä, ja sen tien kulku ei ole kuolemaksi.'),
(1685718,58,20,13,1,'Viisas poika kuulee isän kuritusta, mutta pilkkaaja ei ota nuhdetta kuullaksensa.'),
(1685719,58,20,13,2,'Suunsa hedelmästä saa nauttia hyvää, mutta uskottomilla on halu väkivaltaan.'),
(1685720,58,20,13,3,'Joka suistaa suunsa, se säilyttää henkensä, mutta avosuinen joutuu turmioon.'),
(1685721,58,20,13,4,'Laiskan sielu haluaa, saamatta mitään, mutta ahkerain sielu tulee ravituksi.'),
(1685722,58,20,13,5,'Vanhurskas vihaa valhepuhetta, mutta jumalattoman meno on iljettävä ja häpeällinen.'),
(1685723,58,20,13,6,'Vanhurskaus varjelee nuhteettomasti vaeltavan, mutta jumalattomuus syöksee syntisen kumoon.'),
(1685724,58,20,13,7,'Toinen on olevinaan rikas, omistamatta mitään, toinen olevinaan köyhä, vaikka on tavaraa paljon.'),
(1685725,58,20,13,8,'Rikkautensa saa mies antaa henkensä lunnaiksi, mutta köyhän ei tarvitse uhkauksia kuunnella.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685726,58,20,13,9,'Vanhurskasten valo loistaa iloisesti, mutta jumalattomien lamppu sammuu.'),
(1685727,58,20,13,10,'Ylpeys tuottaa pelkkää toraa, mutta jotka ottavat neuvon varteen, niillä on viisaus.'),
(1685728,58,20,13,11,'Tyhjällä saatu tavara vähenee, mutta joka vähin erin kokoaa, se saa karttumaan.'),
(1685729,58,20,13,12,'Pitkä odotus tekee sydämen sairaaksi, mutta täyttynyt halu on elämän puu.'),
(1685730,58,20,13,13,'Joka sanaa halveksii, joutuu sanan pantiksi; mutta joka käskyä pelkää, saa palkan.'),
(1685731,58,20,13,14,'Viisaan opetus on elämän lähde kuoleman paulain välttämiseksi.'),
(1685732,58,20,13,15,'Hyvä ymmärrys tuottaa suosiota, mutta uskottomien tie on koleikkoa.'),
(1685733,58,20,13,16,'Jokainen mielevä toimii taitavasti, mutta tyhmä levittää hulluutta.'),
(1685734,58,20,13,17,'Jumalaton sanansaattaja suistuu turmioon, mutta uskollinen lähetti on kuin lääke.'),
(1685735,58,20,13,18,'Köyhyys ja häpeä kuritusta vierovalle, kunnia nuhdetta noudattavalle!'),
(1685736,58,20,13,19,'Tyydytetty halu on sielulle suloinen, pahan karttaminen tyhmille kauhistus.'),
(1685737,58,20,13,20,'Vaella viisasten kanssa, niin viisastut; tyhmäin seuratoverin käy pahoin.'),
(1685738,58,20,13,21,'Syntisiä vainoaa onnettomuus, mutta vanhurskaat saavat onnen palkakseen.'),
(1685739,58,20,13,22,'Hyvä jättää perinnön lastensa lapsillekin, mutta syntisen tavara talletetaan vanhurskaalle.'),
(1685740,58,20,13,23,'Köyhien uudiskyntö antaa runsaan ruuan; mutta moni tuhoutuu, joka ei oikeudessa pysy.'),
(1685741,58,20,13,24,'Joka vitsaa säästää, se vihaa lastaan; mutta joka häntä rakastaa, se häntä ajoissa kurittaa.'),
(1685742,58,20,13,25,'Vanhurskas saa syödä kylläksensä, mutta jumalattomain vatsa jää vajaaksi.'),
(1685743,58,20,14,1,'Vaimojen viisaus talon rakentaa, mutta hulluus sen omin käsin purkaa.'),
(1685744,58,20,14,2,'Joka vaeltaa oikein, se pelkää Herraa, mutta jonka tiet ovat väärät, se hänet katsoo ylen.'),
(1685745,58,20,14,3,'Hullun suussa on ylpeydelle vitsa, mutta viisaita vartioivat heidän huulensa.'),
(1685746,58,20,14,4,'Missä raavaita puuttuu, on seimi tyhjä, mutta runsas sato saadaan härkien voimasta.'),
(1685747,58,20,14,5,'Uskollinen todistaja ei valhettele, mutta väärä todistaja puhuu valheita.'),
(1685748,58,20,14,6,'Pilkkaaja etsii viisautta turhaan, mutta ymmärtäväisen on tietoa helppo saada.'),
(1685749,58,20,14,7,'Menet pois tyhmän miehen luota: et tullut tuntemaan tiedon huulia.'),
(1685750,58,20,14,8,'Mielevän viisaus on, että hän vaelluksestaan vaarin pitää; tyhmien hulluus on petos.'),
(1685751,58,20,14,9,'Hulluja pilkkaa vikauhri, mutta oikeamielisten kesken on mielisuosio.'),
(1685752,58,20,14,10,'Sydän tuntee oman surunsa, eikä sen iloon saa vieras sekaantua.'),
(1685753,58,20,14,11,'Jumalattomain huone hävitetään, mutta oikeamielisten maja kukoistaa.'),
(1685754,58,20,14,12,'Miehen mielestä on oikea monikin tie, joka lopulta on kuoleman tie.'),
(1685755,58,20,14,13,'Nauraessakin voi sydän kärsiä, ja ilon lopuksi tulee murhe.'),
(1685756,58,20,14,14,'Omista teistään saa kyllänsä se, jolla on luopunut sydän, mutta itsestään löytää tyydytyksen hyvä mies.'),
(1685757,58,20,14,15,'Yksinkertainen uskoo joka sanan, mutta mielevä ottaa askeleistansa vaarin.'),
(1685758,58,20,14,16,'Viisas pelkää ja karttaa pahaa, mutta tyhmä on huoleton ja suruton.'),
(1685759,58,20,14,17,'Pikavihainen tekee hullun töitä, ja juonittelija joutuu vihatuksi.'),
(1685760,58,20,14,18,'Yksinkertaiset saavat perinnökseen hulluuden, mutta mielevät tiedon kruunuksensa.'),
(1685761,58,20,14,19,'Pahojen täytyy kumartua hyvien edessä ja jumalattomien seisoa vanhurskaan porteilla.'),
(1685762,58,20,14,20,'Köyhää vihaa hänen ystävänsäkin, mutta rikasta rakastavat monet.'),
(1685763,58,20,14,21,'Syntiä tekee, joka lähimmäistään halveksii, mutta autuas se, joka kurjia armahtaa!'),
(1685764,58,20,14,22,'Eivätkö eksy ne, jotka hankitsevat pahaa? Mutta armo ja totuus niille, jotka hankitsevat hyvää!'),
(1685765,58,20,14,23,'Kaikesta vaivannäöstä tulee hyötyä, mutta tyhjästä puheesta vain vahinkoa.'),
(1685766,58,20,14,24,'Viisasten kruunu on heidän rikkautensa, mutta tyhmäin hulluus hulluudeksi jää.'),
(1685767,58,20,14,25,'Uskollinen todistaja on hengen pelastaja, mutta joka valheita puhuu, on petosta täynnä.'),
(1685768,58,20,14,26,'Herran pelossa on vahva varmuus ja turva vielä lapsillekin.'),
(1685769,58,20,14,27,'Herran pelko on elämän lähde kuoleman paulain välttämiseksi.'),
(1685770,58,20,14,28,'Kansan paljous on kuninkaan kunnia, väen vähyys ruhtinaan turmio.'),
(1685771,58,20,14,29,'Pitkämielisellä on paljon taitoa, mutta pikavihaisen osa on hulluus.'),
(1685772,58,20,14,30,'Sävyisä sydän on ruumiin elämä, mutta luulevaisuus on mätä luissa.'),
(1685773,58,20,14,31,'Joka vaivaista sortaa, se herjaa hänen Luojaansa, mutta se häntä kunnioittaa, joka köyhää armahtaa.'),
(1685774,58,20,14,32,'Jumalaton sortuu omaan pahuuteensa, mutta vanhurskas on turvattu kuollessaan.'),
(1685775,58,20,14,33,'Ymmärtäväisen sydämeen ottaa majansa viisaus, ja tyhmien keskellä se itsensä tiettäväksi tekee.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685776,58,20,14,34,'Vanhurskaus kansan korottaa, mutta synti on kansakuntien häpeä.'),
(1685777,58,20,14,35,'Taitava palvelija saa kuninkaan suosion, mutta kunnoton hänen vihansa.'),
(1685778,58,20,15,1,'Leppeä vastaus taltuttaa kiukun, mutta loukkaava sana nostaa vihan.'),
(1685779,58,20,15,2,'Viisasten kieli puhuu tietoa taitavasti, mutta tyhmäin suu purkaa hulluutta.'),
(1685780,58,20,15,3,'Herran silmät ovat joka paikassa; ne vartioitsevat hyviä ja pahoja.'),
(1685781,58,20,15,4,'Sävyisä kieli on elämän puu, mutta vilpillinen kieli haavoittaa mielen.'),
(1685782,58,20,15,5,'Hullu pitää halpana isänsä kurituksen, mutta joka nuhdetta noudattaa, tulee mieleväksi.'),
(1685783,58,20,15,6,'Vanhurskaan huoneessa on suuret aarteet, mutta jumalattoman saalis on turmion oma.'),
(1685784,58,20,15,7,'Viisasten huulet kylvävät tietoa, mutta tyhmäin sydän ei ole vakaa.'),
(1685785,58,20,15,8,'Jumalattomien uhri on Herralle kauhistus, mutta oikeamielisten rukous on hänelle otollinen.'),
(1685786,58,20,15,9,'Jumalattoman tie on Herralle kauhistus, mutta joka vanhurskauteen pyrkii, sitä hän rakastaa.'),
(1685787,58,20,15,10,'Kova tulee kuritus sille, joka tien hylkää; joka nuhdetta vihaa, saa kuoleman.'),
(1685788,58,20,15,11,'Tuonelan ja manalan Herra näkee, saati sitten ihmislasten sydämet.'),
(1685789,58,20,15,12,'Pilkkaaja ei pidä siitä, että häntä nuhdellaan; viisasten luo hän ei mene.'),
(1685790,58,20,15,13,'Iloinen sydän kaunistaa kasvot, mutta sydämen tuskassa on mieli murtunut.'),
(1685791,58,20,15,14,'Ymmärtäväisen sydän etsii tietoa, mutta tyhmien suu hulluutta suosii.'),
(1685792,58,20,15,15,'Kurjalle ovat pahoja kaikki päivät, mutta hyvä mieli on kuin alituiset pidot.'),
(1685793,58,20,15,16,'Parempi vähä Herran pelossa kuin paljot varat levottomuudessa.'),
(1685794,58,20,15,17,'Parempi vihannesruoka rakkaudessa kuin syöttöhärkä vihassa.'),
(1685795,58,20,15,18,'Kiukkuinen mies nostaa riidan, mutta pitkämielinen asettaa toran.'),
(1685796,58,20,15,19,'Laiskan tie on kuin orjantappurapehko, mutta oikeamielisten polku on raivattu.'),
(1685797,58,20,15,20,'Viisas poika on isällensä iloksi, mutta tyhmä ihminen halveksii äitiänsä.'),
(1685798,58,20,15,21,'Hulluus on ilo sille, joka on mieltä vailla, mutta ymmärtäväinen mies kulkee suoraan.'),
(1685799,58,20,15,22,'Hankkeet sortuvat, missä neuvonpito puuttuu; mutta ne toteutuvat, missä on runsaasti neuvonantajia.'),
(1685800,58,20,15,23,'Miehellä on ilo suunsa vastauksesta; ja kuinka hyvä onkaan sana aikanansa!'),
(1685801,58,20,15,24,'Taitava käy elämän tietä ylöspäin, välttääkseen tuonelan, joka alhaalla on.'),
(1685802,58,20,15,25,'Ylpeitten huoneen Herra hajottaa, mutta lesken rajan hän vahvistaa.'),
(1685803,58,20,15,26,'Häijyt juonet ovat Herralle kauhistus, mutta lempeät sanat ovat puhtaat.'),
(1685804,58,20,15,27,'Väärän voiton pyytäjä hävittää huoneensa, mutta joka lahjuksia vihaa, saa elää.'),
(1685805,58,20,15,28,'Vanhurskaan sydän miettii, mitä vastata, mutta jumalattomien suu purkaa pahuutta.'),
(1685806,58,20,15,29,'Jumalattomista on Herra kaukana, mutta vanhurskasten rukouksen hän kuulee.'),
(1685807,58,20,15,30,'Valoisa silmänluonti ilahuttaa sydämen; hyvä sanoma tuo ydintä luihin.'),
(1685808,58,20,15,31,'Korva, joka kuuntelee elämän nuhdetta, saa majailla viisaitten keskellä.'),
(1685809,58,20,15,32,'Joka kuritusta vieroo, pitää sielunsa halpana; mutta joka nuhdetta kuuntelee, se saa mieltä.'),
(1685810,58,20,15,33,'Herran pelko on kuri viisauteen, ja kunnian edellä käy nöyryys.'),
(1685811,58,20,16,1,'Ihmisen ovat mielen aivoittelut, mutta Herralta tulee kielen vastaus.'),
(1685812,58,20,16,2,'Kaikki miehen tiet ovat hänen omissa silmissään puhtaat, mutta Herra tutkii henget.'),
(1685813,58,20,16,3,'Heitä työsi Herran haltuun, niin sinun hankkeesi menestyvät.'),
(1685814,58,20,16,4,'Kaiken on Herra tehnyt määrätarkoitukseen, niinpä jumalattomankin onnettomuuden päivän varalle.'),
(1685815,58,20,16,5,'Jokainen ylpeämielinen on Herralle kauhistus: totisesti, ei sellainen jää rankaisematta.'),
(1685816,58,20,16,6,'Laupeudella ja uskollisuudella rikos sovitetaan, ja Herran pelolla paha vältetään.'),
(1685817,58,20,16,7,'Jos miehen tiet ovat Herralle otolliset, saattaa hän vihamiehetkin sovintoon hänen kanssansa.'),
(1685818,58,20,16,8,'Parempi vähä vanhurskaudessa kuin suuret voitot vääryydessä.'),
(1685819,58,20,16,9,'Ihmisen sydän aivoittelee hänen tiensä, mutta Herra ohjaa hänen askeleensa.'),
(1685820,58,20,16,10,'Kuninkaan huulilla on jumalallinen ratkaisu; hänen suunsa ei petä tuomitessaan.'),
(1685821,58,20,16,11,'Puntari ja oikea vaaka ovat Herran, hänen tekoaan ovat kaikki painot kukkarossa.'),
(1685822,58,20,16,12,'Jumalattomuuden teko on kuninkaille kauhistus, sillä vanhurskaudesta valtaistuin vahvistuu.'),
(1685823,58,20,16,13,'Vanhurskaat huulet ovat kuninkaille mieleen, ja oikein puhuvaa he rakastavat.'),
(1685824,58,20,16,14,'Kuninkaan viha on kuoleman sanansaattaja, mutta sen lepyttää viisas mies.'),
(1685825,58,20,16,15,'Kuninkaan kasvojen valo on elämäksi, ja hänen suosionsa on kuin keväinen sadepilvi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685826,58,20,16,16,'Parempi kultaa on hankkia viisautta, kalliimpi hopeata hankkia ymmärrystä.'),
(1685827,58,20,16,17,'Oikeamielisten tie välttää onnettomuuden; henkensä saa pitää, joka pitää vaelluksestansa vaarin.'),
(1685828,58,20,16,18,'Kopeus käy kukistumisen edellä, ylpeys lankeemuksen edellä.'),
(1685829,58,20,16,19,'Parempi alavana nöyrien parissa kuin jakamassa saalista ylpeitten kanssa.'),
(1685830,58,20,16,20,'Joka painaa mieleensä sanan, se löytää onnen; ja autuas se, joka Herraan turvaa!'),
(1685831,58,20,16,21,'Jolla on viisas sydän, sitä ymmärtäväiseksi sanotaan, ja huulten suloisuus antaa opetukselle tehoa.'),
(1685832,58,20,16,22,'Ymmärrys on omistajalleen elämän lähde, mutta hulluus on hulluille kuritus.'),
(1685833,58,20,16,23,'Viisaan sydän tekee taitavaksi hänen suunsa ja antaa tehoa hänen huultensa opetukselle.'),
(1685834,58,20,16,24,'Lempeät sanat ovat mesileipää; ne ovat makeat sielulle ja lääkitys luille.'),
(1685835,58,20,16,25,'Miehen mielestä on oikea monikin tie, joka lopulta on kuoleman tie.'),
(1685836,58,20,16,26,'Työmiehen nälkä tekee työtä hänen hyväkseen, sillä oma suu panee hänelle pakon.'),
(1685837,58,20,16,27,'Kelvoton mies kaivaa toiselle onnettomuutta; hänen huulillaan on kuin polttava tuli.'),
(1685838,58,20,16,28,'Kavala mies rakentaa riitaa, ja panettelija erottaa ystävykset.'),
(1685839,58,20,16,29,'Väkivallan mies viekoittelee lähimmäisensä ja vie hänet tielle, joka ei ole hyvä.'),
(1685840,58,20,16,30,'Joka silmiänsä luimistelee, sillä on kavaluus mielessä; joka huulensa yhteen puristaa, sillä on paha valmiina.'),
(1685841,58,20,16,31,'Harmaat hapset ovat kunnian kruunu; se saadaan vanhurskauden tiellä.'),
(1685842,58,20,16,32,'Pitkämielinen on parempi kuin sankari, ja mielensä hillitseväinen parempi kuin kaupungin valloittaja.'),
(1685843,58,20,16,33,'Helmassa pudistellen arpa heitetään, mutta Herralta tulee aina sen ratkaisu.'),
(1685844,58,20,17,1,'Parempi kuiva kannikka rauhassa kuin talon täysi uhripaistia riidassa.'),
(1685845,58,20,17,2,'Taitava palvelija hallitsee kunnotonta poikaa ja pääsee perinnönjaolle veljesten rinnalla.'),
(1685846,58,20,17,3,'Hopealle sulatin, kullalle uuni, mutta sydämet koettelee Herra.'),
(1685847,58,20,17,4,'Paha kuuntelee häijyjä huulia, petollisuus kuulee pahoja kieliä.'),
(1685848,58,20,17,5,'Joka köyhää pilkkaa, se herjaa hänen luojaansa; joka toisen onnettomuudesta iloitsee, ei jää rankaisematta.'),
(1685849,58,20,17,6,'Vanhusten kruunu ovat lastenlapset, ja isät ovat lasten kunnia.'),
(1685850,58,20,17,7,'Ei sovi houkalle ylevä puhe, saati sitten ruhtinaalle valhe.'),
(1685851,58,20,17,8,'Lahjus on käyttäjänsä silmissä kallis kivi: mihin vain hän kääntyy, hän menestyy.'),
(1685852,58,20,17,9,'Joka rikkeen peittää, se rakkautta harrastaa; mutta joka asioita kaivelee, se erottaa ystävykset.'),
(1685853,58,20,17,10,'Nuhde pystyy paremmin ymmärtäväiseen kuin sata lyöntiä tyhmään.'),
(1685854,58,20,17,11,'Pelkkää onnettomuutta hankkii kapinoitsija, mutta häntä vastaan lähetetään armoton sanansaattaja.'),
(1685855,58,20,17,12,'Kohdatkoon miestä karhu, jolta on riistetty poikaset, mutta älköön tyhmä hulluudessansa.'),
(1685856,58,20,17,13,'Joka hyvän pahalla palkitsee, sen kodista ei onnettomuus väisty.'),
(1685857,58,20,17,14,'Alottaa tora on päästää vedet valloilleen; herkeä, ennenkuin riita syttyy.'),
(1685858,58,20,17,15,'Syyllisen syyttömäksi ja syyttömän syylliseksi tekijä ovat kumpikin Herralle kauhistus.'),
(1685859,58,20,17,16,'Mitä hyötyä on rahasta tyhmän käsissä? Viisauden hankkimiseen ei ole ymmärrystä.'),
(1685860,58,20,17,17,'Ystävä rakastaa ainiaan ja veli syntyy varaksi hädässä.'),
(1685861,58,20,17,18,'Mieltä vailla on mies, joka kättä lyöpi, joka menee toista takaamaan.'),
(1685862,58,20,17,19,'Joka toraa rakastaa, se rikkomusta rakastaa; joka ovensa korottaa, se hankkii kukistumistaan.'),
(1685863,58,20,17,20,'Väärämielinen ei onnea löydä, ja kavalakielinen suistuu onnettomuuteen.'),
(1685864,58,20,17,21,'Tyhmä on murheeksi siittäjällensä, ja houkan isä on iloa vailla.'),
(1685865,58,20,17,22,'Terveydeksi on iloinen sydän, mutta murtunut mieli kuivuttaa luut.'),
(1685866,58,20,17,23,'Jumalaton ottaa lahjuksen vastaan toisen povelta vääristääksensä oikeuden tiet.'),
(1685867,58,20,17,24,'Ymmärtäväisellä on viisaus kasvojensa edessä, mutta tyhmän silmät kiertävät maailman rantaa.'),
(1685868,58,20,17,25,'Tyhmä poika on isällensä suruksi ja synnyttäjällensä mielihaikeaksi.'),
(1685869,58,20,17,26,'Paha jo sekin, jos syytöntä sakotetaan; kovin kohtuutonta, jos jaloja lyödään.'),
(1685870,58,20,17,27,'Joka hillitsee sanansa, on taitava, ja mielensä malttava on ymmärtäväinen mies.'),
(1685871,58,20,17,28,'Hullukin käy viisaasta, jos vaiti on; joka huulensa sulkee, on ymmärtäväinen.'),
(1685872,58,20,18,1,'Eriseurainen noudattaa omia pyyteitään; kaikin neuvoin hän riitaa haastaa.'),
(1685873,58,20,18,2,'Tyhmän halu ei ole ymmärrykseen, vaan tuomaan julki oma mielensä.'),
(1685874,58,20,18,3,'Kunne jumalaton tulee, tulee ylenkatsekin, ja häpeällisen menon mukana häväistys.'),
(1685875,58,20,18,4,'Syviä vesiä ovat sanat miehen suusta, ovat virtaava puro ja viisauden lähde.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685876,58,20,18,5,'Ei ole hyvä pitää syyllisen puolta ja vääräksi vääntää syyttömän asiaa oikeudessa.'),
(1685877,58,20,18,6,'Tyhmän huulet tuovat mukanaan riidan, ja hänen suunsa kutsuu lyöntejä.'),
(1685878,58,20,18,7,'Oma suu on tyhmälle turmioksi ja omat huulet ansaksi hänelle itselleen.'),
(1685879,58,20,18,8,'Panettelijan puheet ovat kuin herkkupalat ja painuvat sisusten kammioihin asti.'),
(1685880,58,20,18,9,'Joka on veltto toimessansa, se on jo tuhontekijän veli.'),
(1685881,58,20,18,10,'Herran nimi on vahva torni; hurskas juoksee sinne ja saa turvan.'),
(1685882,58,20,18,11,'Rikkaan tavara on hänen vahva kaupunkinsa, ja korkean muurin kaltainen hänen kuvitteluissaan.'),
(1685883,58,20,18,12,'Kukistumisen edellä miehen sydän ylpistyy, mutta kunnian edellä käy nöyryys.'),
(1685884,58,20,18,13,'Jos kuka vastaa, ennenkuin on kuullut, on se hulluutta ja koituu hänelle häpeäksi.'),
(1685885,58,20,18,14,'Miehekäs mieli pitää sairaankin pystyssä, mutta kuka voi kantaa murtunutta mieltä?'),
(1685886,58,20,18,15,'Tietoa hankkii ymmärtäväisen sydän, tietoa etsii viisasten korva.'),
(1685887,58,20,18,16,'Lahja avartaa alat ihmiselle ja vie hänet isoisten pariin.'),
(1685888,58,20,18,17,'Käräjissä on kukin ensiksi oikeassa, mutta sitten tulee hänen riitapuolensa ja ottaa hänestä selvän.'),
(1685889,58,20,18,18,'Arpa riidat asettaa ja ratkaisee väkevien välit.'),
(1685890,58,20,18,19,'Petetty veli on vaikeampi voittaa kuin vahva kaupunki, ja riidat ovat kuin linnan salvat.'),
(1685891,58,20,18,20,'Suunsa hedelmästä saa mies vatsansa kylläiseksi, saa kyllikseen huultensa satoa.'),
(1685892,58,20,18,21,'Kielellä on vallassansa kuolema ja elämä; jotka sitä rakastavat, saavat syödä sen hedelmää.'),
(1685893,58,20,18,22,'Joka vaimon löysi, se onnen löysi, sai Herralta mielisuosion.'),
(1685894,58,20,18,23,'Köyhä puhuu pyydellen, mutta rikas vastaa tylysti.'),
(1685895,58,20,18,24,'Häviökseen mies on monien ystävä, mutta on myös ystäviä, veljiäkin uskollisempia.'),
(1685896,58,20,19,1,'Parempi on köyhä, joka nuhteettomasti vaeltaa, kuin huuliltansa nurja, joka on vielä tyhmäkin.'),
(1685897,58,20,19,2,'Ilman taitoa ei ole intokaan hyväksi, ja kiirehtivän jalka astuu harhaan.'),
(1685898,58,20,19,3,'Ihmisen oma hulluus turmelee hänen tiensä, mutta Herralle hän sydämessään vihoittelee.'),
(1685899,58,20,19,4,'Tavara tuo ystäviä paljon, mutta vaivainen joutuu ystävästänsä eroon.'),
(1685900,58,20,19,5,'Väärä todistaja ei jää rankaisematta, ja joka valheita puhuu, se ei pelastu.'),
(1685901,58,20,19,6,'Monet etsivät ylhäisen suosiota, ja kaikki ovat anteliaan ystäviä.'),
(1685902,58,20,19,7,'Köyhä on kaikkien veljiensä vihattu, vielä vierotumpi ystävilleen. Tyhjiä sanoja hän saa tavoitella.'),
(1685903,58,20,19,8,'Joka mieltä hankkii, se sieluansa rakastaa; joka ymmärryksen säilyttää, se onnen löytää.'),
(1685904,58,20,19,9,'Väärä todistaja ei jää rankaisematta, ja joka valheita puhuu, se hukkuu.'),
(1685905,58,20,19,10,'Ei sovi tyhmälle hyvät päivät, saati sitten palvelijalle hallita ruhtinaita.'),
(1685906,58,20,19,11,'Ymmärrys tekee ihmisen pitkämieliseksi, ja hänen kunniansa on antaa rikos anteeksi.'),
(1685907,58,20,19,12,'Kuninkaan viha on kuin nuoren leijonan kiljunta, mutta hänen suosionsa on kuin kaste ruoholle.'),
(1685908,58,20,19,13,'Tyhmä poika on isänsä turmio, ja vaimon tora on kuin räystäästä tippuva vesi.'),
(1685909,58,20,19,14,'Talo ja tavara peritään isiltä, mutta toimellinen vaimo tulee Herralta.'),
(1685910,58,20,19,15,'Laiskuus vaivuttaa sikeään uneen, ja veltto joutuu näkemään nälkää.'),
(1685911,58,20,19,16,'Joka käskyt pitää, saa henkensä pitää; joka ei teistänsä välitä, on kuoleman oma.'),
(1685912,58,20,19,17,'Joka vaivaista armahtaa, se lainaa Herralle, ja hän maksaa jälleen hänen hyvän tekonsa.'),
(1685913,58,20,19,18,'Kurita poikaasi, kun vielä toivoa on; ethän halunne hänen kuolemaansa.'),
(1685914,58,20,19,19,'Rajuluontoinen joutuu sakkoihin: vain yllytät, jos yrität apuun.'),
(1685915,58,20,19,20,'Kuule neuvoa, ota kuritus varteen, että olisit vasta viisaampi.'),
(1685916,58,20,19,21,'Monet ovat miehen mielessä aivoitukset, mutta Herran neuvo on pysyväinen.'),
(1685917,58,20,19,22,'Ihaninta ihmisessä on hänen laupeutensa, ja köyhä on parempi kuin valhettelija.'),
(1685918,58,20,19,23,'Herran pelko on elämäksi: saa levätä yönsä ravittuna, eikä mikään paha kohtaa.'),
(1685919,58,20,19,24,'Laiska pistää kätensä vatiin, mutta ei saa sitä viedyksi suuhunsa jälleen.'),
(1685920,58,20,19,25,'Lyö pilkkaajaa, niin yksinkertainen saa mieltä, ja jos ymmärtäväistä nuhdellaan, niin hän käsittää tiedon.'),
(1685921,58,20,19,26,'Joka isäänsä pahoin pitelee ja ajaa äitinsä pois, se on kunnoton ja rietas poika.'),
(1685922,58,20,19,27,'Jos herkeät, poikani, kuulemasta kuritusta, niin eksyt pois tiedon sanoista.'),
(1685923,58,20,19,28,'Kelvoton todistaja pitää oikeuden pilkkanaan, ja jumalattomien suu nielee vääryyttä.'),
(1685924,58,20,19,29,'Tuomiot ovat valmiina pilkkaajille ja lyönnit tyhmien selkään.'),
(1685925,58,20,20,1,'Viini on pilkkaaja, väkijuoma remunpitäjä; eikä ole viisas kenkään, joka siitä hoipertelee.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685926,58,20,20,2,'Kuninkaan peljättäväisyys on kuin nuoren leijonan kiljunta; joka hänet vihoittaa, se henkensä rikkoo.'),
(1685927,58,20,20,3,'On kunniaksi miehelle riitaa karttaa, mutta kaikki hullut riitaa haastavat.'),
(1685928,58,20,20,4,'Syksyllä ei laiska kynnä; elonaikana hän tyhjää tapailee.'),
(1685929,58,20,20,5,'Kuin syvät vedet ovat miehen sydämen aivoitukset, mutta ymmärtäväinen mies ne ammentaa esiin.'),
(1685930,58,20,20,6,'Monet huutavat hyvyyttänsä kukin, mutta kuka löytää luotettavan miehen?'),
(1685931,58,20,20,7,'Vanhurskas vaeltaa nuhteettomasti, onnelliset ovat lapset hänen jälkeensä.'),
(1685932,58,20,20,8,'Kuningas istuu tuomioistuimella, hän silmillänsä perkaa kaiken pahan pois.'),
(1685933,58,20,20,9,'Kuka voi sanoa: "Olen puhdistanut sydämeni, olen puhdas synnistäni"?'),
(1685934,58,20,20,10,'Kahtalainen paino ja kahtalainen mitta - molemmat ovat Herralle kauhistus.'),
(1685935,58,20,20,11,'Teoistansa tuntee jo poikasenkin, onko hänen menonsa puhdas ja oikea.'),
(1685936,58,20,20,12,'Kuulevan korvan ja näkevän silmän - molemmat on Herra luonut.'),
(1685937,58,20,20,13,'Älä unta rakasta, ettet köyhtyisi; pidä silmäsi auki, niin saat leipää kyllin.'),
(1685938,58,20,20,14,'"Huonoa, huonoa", sanoo ostaja, mutta mentyänsä pois hän kehuskelee.'),
(1685939,58,20,20,15,'Olkoon kultaa, olkoon helmiä paljon, kallein kalu ovat taidolliset huulet.'),
(1685940,58,20,20,16,'Ota siltä vaatteet, joka toista takasi, ja ota häneltä pantti vieraitten puolesta.'),
(1685941,58,20,20,17,'Makea on miehelle petoksella saatu leipä, mutta perästäpäin hän saa suunsa täyteen soraa.'),
(1685942,58,20,20,18,'Neuvotellen suunnitelmat vahvistuvat, ja sotaa on sinun käytävä neuvokkuudella.'),
(1685943,58,20,20,19,'Salaisuuden ilmaisee, joka panettelijana käy; älä siis antaudu avosuisen pariin.'),
(1685944,58,20,20,20,'Joka isäänsä ja äitiänsä kiroaa, sen lamppu sammuu pilkkopimeään.'),
(1685945,58,20,20,21,'Tavara, jota aluksi kiivaasti tavoitellaan, ei lopulta tuo siunausta.'),
(1685946,58,20,20,22,'Älä sano: "Minä kostan pahan"; odota Herraa, hän auttaa sinua.'),
(1685947,58,20,20,23,'Kahtalainen paino on Herralle kauhistus, ja väärä vaaka ei ole hyvä.'),
(1685948,58,20,20,24,'Herralta tulevat miehen askeleet; mitäpä ymmärtäisi tiestänsä ihminen itse?'),
(1685949,58,20,20,25,'Ihmiselle on ansaksi luvata hätiköiden pyhä lahja ja vasta perästäpäin harkita lupauksiansa.'),
(1685950,58,20,20,26,'Viisas kuningas perkaa jumalattomat pois viskimellään ja antaa puimajyrän käydä heidän ylitsensä.'),
(1685951,58,20,20,27,'Ihmisen henki on Herran lamppu: se tutkistelee sydämen kammiot kaikki.'),
(1685952,58,20,20,28,'Laupeus ja uskollisuus on kuninkaan turva, ja laupeudella hän valtaistuimensa tukee.'),
(1685953,58,20,20,29,'Voima on nuorukaisen kunnia, ja harmaat hapset ovat vanhusten kaunistus.'),
(1685954,58,20,20,30,'Mustelmat ja haavat puhdistavat pahantekijän, lyönnit puhdistavat sydämen kammiot.'),
(1685955,58,20,21,1,'Kuninkaan sydän on Herran kädessä kuin vesiojat: hän taivuttaa sen, kunne tahtoo.'),
(1685956,58,20,21,2,'Kaikki miehen tiet ovat hänen omissa silmissään oikeat, mutta Herra tutkii sydämet.'),
(1685957,58,20,21,3,'Vanhurskauden ja oikeuden harjoittaminen on Herralle otollisempi kuin uhri.'),
(1685958,58,20,21,4,'Ylpeät silmät ja pöyhkeä sydän - jumalattomien lamppu - ovat syntiä.'),
(1685959,58,20,21,5,'Vain hyödyksi ovat ahkeran ajatukset, mutta kaikki touhuilijat saavat vain vahinkoa.'),
(1685960,58,20,21,6,'Jotka hankkivat aarteita petollisin kielin, ovat haihtuva tuulahdus, hakevat kuolemaa.'),
(1685961,58,20,21,7,'Jumalattomat tempaa pois heidän väkivaltansa, sillä eivät he tahdo oikeutta tehdä.'),
(1685962,58,20,21,8,'Rikollisen tie on mutkainen, mutta puhtaan teot ovat oikeat.'),
(1685963,58,20,21,9,'Parempi asua katon kulmalla kuin toraisan vaimon huonetoverina.'),
(1685964,58,20,21,10,'Jumalattoman sielu himoitsee pahaa, lähimmäinen ei saa armoa hänen silmiensä edessä.'),
(1685965,58,20,21,11,'Kun pilkkaajaa rangaistaan, viisastuu yksinkertainen; ja kun viisasta neuvotaan, ottaa hän sen opiksensa.'),
(1685966,58,20,21,12,'Vanhurskas Jumala tarkkaa jumalattoman taloa, hän syöksee jumalattomat onnettomuuteen.'),
(1685967,58,20,21,13,'Joka tukkii korvansa vaivaisen huudolta, se joutuu itse huutamaan, vastausta saamatta.'),
(1685968,58,20,21,14,'Salainen lahja lepyttää vihan ja poveen kätketty lahjus kiivaan kiukun.'),
(1685969,58,20,21,15,'Vanhurskaalle on ilo, kun oikeutta tehdään, mutta väärintekijöille kauhu.'),
(1685970,58,20,21,16,'Ihminen, joka eksyy taidon tieltä, joutuu lepäämään haamujen seuraan.'),
(1685971,58,20,21,17,'Puutteen mieheksi päätyy riemujen rakastaja, eikä rikastu se, joka viiniä ja öljyä rakastaa.'),
(1685972,58,20,21,18,'Jumalaton joutuu lunastusmaksuksi vanhurskaan puolesta ja uskoton oikeamielisten sijaan.'),
(1685973,58,20,21,19,'Parempi asua autiossa maassa kuin toraisan vaimon vaivattavana.'),
(1685974,58,20,21,20,'Kalliita aarteita ja öljyä on viisaan majassa, mutta tyhmä ihminen syö suuhunsa sellaiset.'),
(1685975,58,20,21,21,'Joka vanhurskauteen ja laupeuteen pyrkii, se löytää elämän, vanhurskauden ja kunnian.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1685976,58,20,21,22,'Viisas ryntää sankarien kaupunkiin ja kukistaa varustuksen, joka oli sen turva.'),
(1685977,58,20,21,23,'Joka suunsa ja kielensä varoo, se henkensä ahdistuksilta varoo.'),
(1685978,58,20,21,24,'Pilkkaajan nimen saa julkea röyhkeilijä, jonka meno on määrätöntä julkeutta.'),
(1685979,58,20,21,25,'Oma halu laiskan tappaa, sillä hänen kätensä eivät tahdo työtä tehdä.'),
(1685980,58,20,21,26,'Aina on hartaasti haluavia, mutta vanhurskas antaa säästelemättä.'),
(1685981,58,20,21,27,'Jumalattomien uhri on kauhistus; saati sitten, jos se tuodaan ilkityön edestä!'),
(1685982,58,20,21,28,'Valheellinen todistaja hukkuu, mutta kuunteleva mies saa aina puhua.'),
(1685983,58,20,21,29,'Julkeiksi tekee jumalaton kasvonsa, vakaiksi tekee oikeamielinen tiensä.'),
(1685984,58,20,21,30,'Ei auta viisaus, ei ymmärrys, ei mikään neuvo Herraa vastaan.'),
(1685985,58,20,21,31,'Hevonen on varustettu taistelun päiväksi, mutta voitto on Herran hallussa.'),
(1685986,58,20,22,1,'Nimi on kalliimpi suurta rikkautta, suosio hopeata ja kultaa parempi.'),
(1685987,58,20,22,2,'Rikas ja köyhä kohtaavat toisensa; Herra on luonut kumpaisenkin.'),
(1685988,58,20,22,3,'Mielevä näkee vaaran ja kätkeytyy, mutta yksinkertaiset käyvät kohti ja saavat vahingon.'),
(1685989,58,20,22,4,'Nöyryyden ja Herran pelon palkka on rikkaus, kunnia ja elämä.'),
(1685990,58,20,22,5,'Orjantappuroita ja pauloja on väärän tiellä; henkensä varjelee, joka niistä kaukana pysyy.'),
(1685991,58,20,22,6,'Totuta poikanen tiensä suuntaan, niin hän ei vanhanakaan siitä poikkea.'),
(1685992,58,20,22,7,'Rikas hallitsee köyhiä, ja velallinen joutuu velkojan orjaksi.'),
(1685993,58,20,22,8,'Joka vääryyttä kylvää, se turmiota niittää, ja hänen vihansa vitsa häviää.'),
(1685994,58,20,22,9,'Hyvänsuopa saa siunauksen, sillä hän antaa leivästään vaivaiselle.'),
(1685995,58,20,22,10,'Aja pois pilkkaaja, niin poistuu tora ja loppuu riita ja häväistys.'),
(1685996,58,20,22,11,'Joka sydämen puhtautta rakastaa, jolla on suloiset huulet, sen ystävä on kuningas.'),
(1685997,58,20,22,12,'Herran silmät suojelevat taitoa, mutta uskottoman sanat hän kääntää väärään.'),
(1685998,58,20,22,13,'Laiska sanoo: "Ulkona on leijona; tappavat vielä minut keskellä toria".'),
(1685999,58,20,22,14,'Irstaitten vaimojen suu on syvä kuoppa; Herran vihan alainen kaatuu siihen.'),
(1686000,58,20,22,15,'Hulluus on kiertynyt kiinni poikasen sydämeen, mutta kurituksen vitsa sen hänestä kauas karkoittaa.'),
(1686001,58,20,22,16,'Vaivaiselle on voitoksi, jos häntä sorretaan, rikkaalle tappioksi, jos hänelle annetaan.'),
(1686002,58,20,22,17,'Kallista korvasi ja kuuntele viisaitten sanoja ja tarkkaa minun taitoani.'),
(1686003,58,20,22,18,'Sillä suloista on, jos kätket ne sisimpääsi; olkoot ne kaikki huulillasi valmiina.'),
(1686004,58,20,22,19,'Että Herra olisi sinun turvanasi, siksi olen minä nyt neuvonut juuri sinua.'),
(1686005,58,20,22,20,'Olenhan ennenkin sinulle kirjoittanut, antanut neuvoja ja tietoa,'),
(1686006,58,20,22,21,'opettaakseni sinulle totuutta, vakaita sanoja, että voisit vakain sanoin vastata lähettäjällesi.'),
(1686007,58,20,22,22,'Älä raasta vaivaista, siksi että hän on vaivainen, äläkä polje kurjaa portissa,'),
(1686008,58,20,22,23,'sillä Herra ajaa hänen asiansa ja riistää hänen riistäjiltään hengen.'),
(1686009,58,20,22,24,'Älä rupea pikavihaisen ystäväksi äläkä seurustele kiukkuisen kanssa,'),
(1686010,58,20,22,25,'että et tottuisi hänen teihinsä ja saattaisi sieluasi ansaan.'),
(1686011,58,20,22,26,'Älä ole niitä, jotka kättä lyövät, jotka menevät takuuseen veloista.'),
(1686012,58,20,22,27,'Jollei sinulla ole, millä maksaa, mitäs muuta, kuin viedään vuode altasi!'),
(1686013,58,20,22,28,'Älä siirrä ikivanhaa rajaa, jonka esi-isäsi ovat asettaneet.'),
(1686014,58,20,22,29,'Jos näet miehen, kerkeän toimissaan, hänen paikkansa on kuningasten, ei alhaisten, palveluksessa.'),
(1686015,58,20,23,1,'Kun istut aterialle hallitsijan seurassa, niin pidä tarkoin mielessä, kuka edessäsi on,'),
(1686016,58,20,23,2,'ja pane veitsi kurkullesi, jos olet kovin nälkäinen.'),
(1686017,58,20,23,3,'Älä himoitse hänen herkkujansa, sillä ne ovat petollisia ruokia.'),
(1686018,58,20,23,4,'Älä näe vaivaa rikastuaksesi, lakkaa käyttämästä ymmärrystäsi siihen.'),
(1686019,58,20,23,5,'Kun silmäsi siihen lentävät, on rikkaus mennyttä; sillä se saa siivet kuin kotka, joka lentää taivaalle.'),
(1686020,58,20,23,6,'Älä syö pahansuovan leipää äläkä himoitse hänen herkkujansa.'),
(1686021,58,20,23,7,'Sillä niinkuin hän mielessään laskee, niin hän menettelee: hän sanoo sinulle: "Syö ja juo", mutta hänen sydämensä ei ole sinun puolellasi.'),
(1686022,58,20,23,8,'Syömäsi palan sinä olet oksentava, ja suloiset sanasi sinä tuhlasit turhaan.'),
(1686023,58,20,23,9,'Älä puhu tyhmän kuullen, sillä hän katsoo ymmärtäväiset sanasi ylen.'),
(1686024,58,20,23,10,'Älä siirrä ikivanhaa rajaa äläkä mene orpojen pelloille.'),
(1686025,58,20,23,11,'Sillä heidän sukulunastajansa on väkevä, ja hän ajaa heidän asiansa sinua vastaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686026,58,20,23,12,'Tuo sydämesi kuritettavaksi ja korvasi taidon sanojen ääreen.'),
(1686027,58,20,23,13,'Älä kiellä poikaselta kuritusta, sillä jos lyöt häntä vitsalla, säästyy hän kuolemasta.'),
(1686028,58,20,23,14,'Vitsalla sinä häntä lyöt, tuonelasta hänen sielunsa pelastat.'),
(1686029,58,20,23,15,'Poikani, jos sinun sydämesi viisastuu, niin minunkin sydämeni iloitsee;'),
(1686030,58,20,23,16,'ja sisimpäni riemuitsee, jos sinun huulesi puhuvat sitä, mikä oikein on.'),
(1686031,58,20,23,17,'Älköön sydämesi kadehtiko jumalattomia, mutta kiivaile aina Jumalan pelon puolesta,'),
(1686032,58,20,23,18,'niin sinulla totisesti on tulevaisuus, ja toivosi ei mene turhaan.'),
(1686033,58,20,23,19,'Kuule, poikani, ja viisastu, ja ohjaa sydämesi oikealle tielle.'),
(1686034,58,20,23,20,'Älä oleskele viininjuomarien parissa äläkä lihansyömärien.'),
(1686035,58,20,23,21,'Sillä juomari ja syömäri köyhtyy, ja unteluus puettaa ryysyihin.'),
(1686036,58,20,23,22,'Kuule isääsi, joka on sinut siittänyt, äläkä äitiäsi halveksi, kun hän on vanhennut.'),
(1686037,58,20,23,23,'Osta totuutta, älä myy, osta viisautta, kuria ja ymmärrystä.'),
(1686038,58,20,23,24,'Ääneen saa riemuita vanhurskaan isä; joka viisaan on siittänyt, sillä on ilo hänestä.'),
(1686039,58,20,23,25,'Olkoon sinun isälläsi ja äidilläsi ilo, sinun synnyttäjäsi riemuitkoon.'),
(1686040,58,20,23,26,'Anna sydämesi, poikani, minulle, ja olkoot minun tieni sinun silmissäsi mieluiset.'),
(1686041,58,20,23,27,'Sillä portto on syvä kuoppa, ja vieras vaimo on ahdas kaivo.'),
(1686042,58,20,23,28,'Vieläpä hän väijyy kuin rosvo, ja hän kartuttaa uskottomia ihmisten seassa.'),
(1686043,58,20,23,29,'Kenellä on voivotus, kenellä vaikerrus? Kenellä torat, kenellä valitus? Kenellä haavat ilman syytä? Kenellä sameat silmät?'),
(1686044,58,20,23,30,'Niillä, jotka viinin ääressä viipyvät, jotka tulevat makujuomaa maistelemaan.'),
(1686045,58,20,23,31,'Älä katsele viiniä, kuinka se punoittaa, kuinka se maljassa hohtaa ja helposti valahtaa alas.'),
(1686046,58,20,23,32,'Lopulta se puree kuin käärme ja pistää kuin myrkkylisko.'),
(1686047,58,20,23,33,'Silmäsi outoja näkevät, ja sydämesi haastelee sekavia.'),
(1686048,58,20,23,34,'Sinusta on kuin makaisit keskellä merta, on kuin maston huipussa makaisit.'),
(1686049,58,20,23,35,'"Löivät minua, mutta ei koskenut minuun; pieksivät minua, mutta en tiennyt mitään. Milloinkahan herännen? Tahdonpa taas hakea tätä samaa."'),
(1686050,58,20,24,1,'Älä kadehdi pahoja ihmisiä äläkä halua heidän seuraansa.'),
(1686051,58,20,24,2,'Sillä heidän mielensä miettii väkivaltaa, ja turmiota haastavat heidän huulensa.'),
(1686052,58,20,24,3,'Viisaudella talo rakennetaan ja ymmärryksellä vahvaksi varustetaan.'),
(1686053,58,20,24,4,'Taidolla täytetään kammiot, kaikkea kallista ja ihanaa tavaraa täyteen.'),
(1686054,58,20,24,5,'Viisas mies on väkevä, ja taidon mies on voipa voimaltansa.'),
(1686055,58,20,24,6,'Neuvokkuudella näet on sinun käytävä sotaa, ja neuvonantajain runsaus tuo menestyksen.'),
(1686056,58,20,24,7,'Kovin on korkea hullulle viisaus, ei hän suutansa avaa portissa.'),
(1686057,58,20,24,8,'Jolla on pahanteko mielessä, sitä juonittelijaksi sanotaan.'),
(1686058,58,20,24,9,'Synti on hulluuden työ, ja pilkkaaja on ihmisille kauhistus.'),
(1686059,58,20,24,10,'Jos olet ollut veltto, joutuu ahtaana aikana voimasi ahtaalle.'),
(1686060,58,20,24,11,'Pelasta ne, joita kuolemaan viedään, pysäytä ne, jotka surmapaikalle hoippuvat.'),
(1686061,58,20,24,12,'Jos sanot: "Katso, emme tienneet siitä", niin ymmärtäähän asian sydänten tutkija; sinun sielusi vartioitsija sen tietää, ja hän kostaa ihmiselle hänen tekojensa mukaan.'),
(1686062,58,20,24,13,'Syö hunajaa, poikani, sillä se on hyvää, ja mesi on makeaa suussasi.'),
(1686063,58,20,24,14,'Samankaltaiseksi tunne viisaus sielullesi; jos sen löydät, on sinulla tulevaisuus, ja toivosi ei mene turhaan.'),
(1686064,58,20,24,15,'Älä väijy, jumalaton, vanhurskaan majaa, älä hävitä hänen leposijaansa.'),
(1686065,58,20,24,16,'Sillä seitsemästi vanhurskas lankeaa ja nousee jälleen, mutta jumalattomat suistuvat onnettomuuteen.'),
(1686066,58,20,24,17,'Älä iloitse vihamiehesi langetessa, älköön sydämesi riemuitko hänen suistuessaan kumoon,'),
(1686067,58,20,24,18,'ettei Herra, kun sen näkee, sitä pahana pitäisi, ja kääntäisi vihaansa pois hänestä.'),
(1686068,58,20,24,19,'Älä vihastu pahantekijäin tähden, älä kadehdi jumalattomia.'),
(1686069,58,20,24,20,'Sillä ei ole pahalla tulevaisuutta; jumalattomien lamppu sammuu.'),
(1686070,58,20,24,21,'Pelkää, poikani, Herraa ja kuningasta, älä sekaannu kapinallisten seuraan.'),
(1686071,58,20,24,22,'Sillä yhtäkkiä tulee heille onnettomuus, tuomio - kuka tietää milloin - toisille niinkuin toisillekin.'),
(1686072,58,20,24,23,'Nämäkin ovat viisaitten sanoja. Ei ole hyvä tuomitessa henkilöön katsoa.'),
(1686073,58,20,24,24,'Joka sanoo syylliselle: "Sinä olet syytön", sitä kansat kiroavat, kansakunnat sadattelevat.'),
(1686074,58,20,24,25,'Mutta jotka oikein tuomitsevat, niiden käy hyvin, ja heille tulee onnen siunaus.'),
(1686075,58,20,24,26,'Se huulille suutelee, joka oikean vastauksen antaa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686076,58,20,24,27,'Toimita tehtäväsi ulkona ja tee valmista pellollasi; sitten perusta itsellesi perhe.'),
(1686077,58,20,24,28,'Älä ole syyttä todistajana lähimmäistäsi vastaan, vai petätkö sinä huulillasi?'),
(1686078,58,20,24,29,'Älä sano: "Niinkuin hän teki minulle, niin teen minä hänelle, minä kostan miehelle hänen tekojensa mukaan".'),
(1686079,58,20,24,30,'Minä kuljin laiskurin pellon ohitse, mielettömän miehen viinitarhan vieritse.'),
(1686080,58,20,24,31,'Ja katso: se kasvoi yltänsä polttiaisia; sen pinta oli nokkosten peitossa ja sen kiviaita luhistunut.'),
(1686081,58,20,24,32,'Minä katselin ja painoin mieleeni, havaitsin ja otin opikseni:'),
(1686082,58,20,24,33,'Nuku vielä vähän, torku vähän, makaa vähän ristissä käsin,'),
(1686083,58,20,24,34,'niin köyhyys käy päällesi niinkuin rosvo ja puute niinkuin asestettu mies.'),
(1686084,58,20,25,1,'Nämäkin ovat Salomon sananlaskuja, Hiskian, Juudan kuninkaan, miesten kokoamia.'),
(1686085,58,20,25,2,'Jumalan kunnia on salata asia, ja kuningasten kunnia on tutkia asia.'),
(1686086,58,20,25,3,'Taivaan korkeus ja maan syvyys ja kuningasten sydän on tutkimaton.'),
(1686087,58,20,25,4,'Kun hopeasta poistetaan kuona, kuontuu kultasepältä astia.'),
(1686088,58,20,25,5,'Kun jumalaton poistetaan kuninkaan luota, vahvistuu hänen valtaistuimensa vanhurskaudessa.'),
(1686089,58,20,25,6,'Älä tavoittele kunniaa kuninkaan edessä äläkä asetu isoisten sijalle.'),
(1686090,58,20,25,7,'Sillä parempi on, jos sinulle sanotaan: "Käy tänne ylös", kuin että sinut alennetaan ylhäisen edessä, jonka silmäsi olivat nähneet.'),
(1686091,58,20,25,8,'Älä ole kärkäs käräjöimään; muutoin sinulla ei lopulta ole, mitä tehdä, kun vastapuolesi on saattanut sinut häpeään.'),
(1686092,58,20,25,9,'Riitele oma riitasi vastapuolesi kanssa, mutta toisen salaisuutta älä ilmaise.'),
(1686093,58,20,25,10,'Muutoin sinua häpäisee, kuka sen kuuleekin, eikä huono huuto sinusta lakkaa.'),
(1686094,58,20,25,11,'Kultaomenia hopeamaljoissa ovat sanat, sanotut aikanansa.'),
(1686095,58,20,25,12,'Kultainen korvarengas ja hienokultainen kaulakoru ovat viisas neuvoja ynnä kuuleva korva.'),
(1686096,58,20,25,13,'Kuin lumen viileys elonaikana on luotettava lähetti lähettäjälleen: herransa sielun hän virvoittaa.'),
(1686097,58,20,25,14,'Kuin pilvet ja tuuli, jotka eivät sadetta tuo, on mies, joka kerskuu lahjoilla, joita ei anna.'),
(1686098,58,20,25,15,'Kärsivällisyydellä taivutetaan ruhtinas, ja leppeä kieli murskaa luut.'),
(1686099,58,20,25,16,'Jos hunajata löydät, syö kohtuudella, ettet kyllästyisi siihen ja sitä oksentaisi.'),
(1686100,58,20,25,17,'Astu jalallasi harvoin lähimmäisesi kotiin, ettei hän sinuun kyllästyisi ja alkaisi sinua vihata.'),
(1686101,58,20,25,18,'Nuija ja miekka ja terävä nuoli on mies, joka väärin todistaa lähimmäistänsä vastaan.'),
(1686102,58,20,25,19,'Kuin mureneva hammas ja horjuva jalka on uskottoman turva ahdingon päivänä.'),
(1686103,58,20,25,20,'Kuin se, joka riisuu vaatteet pakkaspäivänä, kuin etikka lipeän sekaan, on se, joka laulaa lauluja murheelliselle sydämelle.'),
(1686104,58,20,25,21,'Jos vihamiehelläsi on nälkä, anna hänelle leipää syödä, ja jos hänellä on jano, anna hänelle vettä juoda.'),
(1686105,58,20,25,22,'Sillä niin sinä kokoat tulisia hiiliä hänen päänsä päälle, ja Herra sen sinulle palkitsee.'),
(1686106,58,20,25,23,'Pohjatuuli saa aikaan sateen ja salainen kielittely vihaiset kasvot.'),
(1686107,58,20,25,24,'Parempi on asua katon kulmalla kuin toraisan vaimon huonetoverina.'),
(1686108,58,20,25,25,'Kuin nääntyväiselle raikas vesi on hyvä sanoma kaukaisesta maasta.'),
(1686109,58,20,25,26,'Kuin sekoitettu lähde ja turmeltu kaivo on vanhurskas, joka horjuu jumalattoman edessä.'),
(1686110,58,20,25,27,'Liika hunajan syönti ei ole hyväksi, ja raskaitten asiain tutkiminen on raskasta.'),
(1686111,58,20,25,28,'Kuin kaupunki, varustukset hajalla, muuria vailla, on mies, joka ei mieltänsä hillitse.'),
(1686112,58,20,26,1,'Yhtä vähän kuin lumi kesällä ja sade elonaikana soveltuu tyhmälle kunnia.'),
(1686113,58,20,26,2,'Kuin liitävä lintu, kuin lentävä pääskynen on aiheeton kirous: ei se toteen käy.'),
(1686114,58,20,26,3,'Hevoselle ruoska, aasille suitset, tyhmille vitsa selkään!'),
(1686115,58,20,26,4,'Älä vastaa tyhmälle hänen hulluutensa mukaan, ettet olisi hänen kaltaisensa sinäkin.'),
(1686116,58,20,26,5,'Vastaa tyhmälle hänen hulluutensa mukaan, ettei hän itseänsä viisaana pitäisi.'),
(1686117,58,20,26,6,'Jalat altaan katkaisee ja vääryyttä saa juoda, joka sanan lähettää tyhmän mukana.'),
(1686118,58,20,26,7,'Velttoina riippuvat halvatun sääret; samoin sananlasku tyhmäin suussa.'),
(1686119,58,20,26,8,'Yhtä kuin sitoisi kiven linkoon kiinni, on antaa kunniaa tyhmälle.'),
(1686120,58,20,26,9,'Kuin ohdake, joka on osunut juopuneen käteen, on sananlasku tyhmäin suussa.'),
(1686121,58,20,26,10,'Kuin jousimies, joka kaikkia haavoittaa, on se, joka tyhmän pestaa, kulkureita pestaa.'),
(1686122,58,20,26,11,'Kuin koira, joka palajaa oksennuksilleen, on tyhmä, joka yhä uusii hulluuksiansa.'),
(1686123,58,20,26,12,'Näet miehen, viisaan omissa silmissään - enemmän on toivoa tyhmästä kuin hänestä.'),
(1686124,58,20,26,13,'Laiska sanoo: "Tuolla tiellä on leijona, jalopeura torien vaiheilla".'),
(1686125,58,20,26,14,'Ovi saranoillaan kääntyilee, laiska vuoteellansa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686126,58,20,26,15,'Laiska pistää kätensä vatiin; ei viitsi sitä viedä suuhunsa jälleen.'),
(1686127,58,20,26,16,'Laiska on omissa silmissään viisaampi kuin seitsemän, jotka vastaavat taitavasti.'),
(1686128,58,20,26,17,'Kulkukoiraa korviin tarttuu se, joka syrjäisten riidasta suuttuu.'),
(1686129,58,20,26,18,'Kuin mieletön, joka ammuskelee tulisia surmannuolia,'),
(1686130,58,20,26,19,'on mies, joka pettää lähimmäisensä ja sanoo: "Leikillähän minä sen tein".'),
(1686131,58,20,26,20,'Halkojen loppuessa sammuu tuli, ja panettelijan poistuessa taukoaa tora.'),
(1686132,58,20,26,21,'Hehkuksi hiilet, tuleksi halot, riidan lietsomiseksi toraisa mies.'),
(1686133,58,20,26,22,'Panettelijan puheet ovat kuin herkkupalat ja painuvat sisusten kammioihin asti.'),
(1686134,58,20,26,23,'Kuin hopeasilaus saviastian pinnalla ovat hehkuvat huulet ja paha sydän.'),
(1686135,58,20,26,24,'Vihamies teeskentelee huulillaan, mutta hautoo petosta sydämessänsä.'),
(1686136,58,20,26,25,'Jos hän muuttaa suloiseksi äänensä, älä häntä usko, sillä seitsemän kauhistusta hänellä on sydämessä.'),
(1686137,58,20,26,26,'Vihamielisyys kätkeytyy kavalasti, mutta seurakunnan kokouksessa sen pahuus paljastuu.'),
(1686138,58,20,26,27,'Joka kuopan kaivaa, se itse siihen lankeaa; ja joka kiveä vierittää, sen päälle se takaisin vyörähtää.'),
(1686139,58,20,26,28,'Valheellinen kieli vihaa omia ruhjomiansa, ja liukas suu saa turmiota aikaan.'),
(1686140,58,20,27,1,'Älä huomispäivästä kersku, sillä et tiedä, mitä mikin päivä synnyttää.'),
(1686141,58,20,27,2,'Kehukoon sinua toinen, ei oma suusi; vieras, eikä omat huulesi.'),
(1686142,58,20,27,3,'Raskas on kivi ja painava hiekka, mutta molempia raskaampi hullun suuttumus.'),
(1686143,58,20,27,4,'Kiukku on julma, viha on niinkuin tulva; mutta kuka voi kestää luulevaisuutta?'),
(1686144,58,20,27,5,'Parempi julkinen nuhde kuin salattu rakkaus.'),
(1686145,58,20,27,6,'Ystävän lyönnit ovat luotettavat, mutta vihamiehen suutelot ylenpalttiset.'),
(1686146,58,20,27,7,'Kylläinen polkee hunajaakin, nälkäiselle on kaikki karvaskin makeata.'),
(1686147,58,20,27,8,'Kuin pesästään paennut lintu, on mies paossa kotipaikoiltaan.'),
(1686148,58,20,27,9,'Öljy ja suitsuke ilahuttavat sydämen; samoin ystävän hellyys, alttiisti neuvoja antavainen.'),
(1686149,58,20,27,10,'Ystävääsi ja isäsi ystävää älä hylkää, äläkä hätäpäivänäsi mene veljesi taloon: parempi läheinen naapuri kuin kaukainen veli.'),
(1686150,58,20,27,11,'Viisastu, poikani, ja ilahuta minun sydämeni, niin minä voin antaa herjaajalleni vastauksen.'),
(1686151,58,20,27,12,'Mielevä näkee vaaran ja kätkeytyy, mutta yksinkertaiset käyvät kohti ja saavat vahingon.'),
(1686152,58,20,27,13,'Ota siltä vaatteet, joka toista takasi, ja ota häneltä pantti vieraan naisen tähden.'),
(1686153,58,20,27,14,'Joka siunaa ystäväänsä isoäänisesti aamulla varhain, sille se luetaan kiroukseksi.'),
(1686154,58,20,27,15,'Räystäästä tippuva vesi sadepäivänä ja toraisa vaimo ovat yhdenveroiset.'),
(1686155,58,20,27,16,'Joka tahtoo hänet salassa pitää, se tuulta salassa pitää, se tavoittaa öljyä oikeaan käteensä.'),
(1686156,58,20,27,17,'Rauta rautaa hioo, ja ihminen toistansa hioo.'),
(1686157,58,20,27,18,'Joka viikunapuuta hoitaa, saa syödä sen hedelmää; ja joka isännästänsä vaarin pitää, se tulee kunniaan.'),
(1686158,58,20,27,19,'Niinkuin kasvot kuvastuvat vedessä, niin ihmisen sydän toisessa ihmisessä.'),
(1686159,58,20,27,20,'Tuonela ja horna eivät kylläänsä saa; eivät myös saa kylläänsä ihmisen silmät.'),
(1686160,58,20,27,21,'Hopealle sulatin, kullalle uuni; mies maineensa mukainen.'),
(1686161,58,20,27,22,'Survo hullua huhmaressa, petkelellä surveitten seassa: ei erkane hänestä hänen hulluutensa.'),
(1686162,58,20,27,23,'Tiedä tarkoin, miltä pikkukarjasi näyttää; pidä huoli laumoista.'),
(1686163,58,20,27,24,'Sillä eivät aarteet säily iäti; ja pysyykö kruunukaan polvesta polveen?'),
(1686164,58,20,27,25,'Kun heinä on mennyt ja tuore äpäre tulee näkyviin ja ruoho on koottu vuorilta,'),
(1686165,58,20,27,26,'on sinulla karitsoita puvuksesi ja vuohipukkeja pellon ostohinnaksi'),
(1686166,58,20,27,27,'ja vuohenmaitoa kyllin ravinnoksesi, perheesi ravinnoksi ja palvelijatartesi elatukseksi.'),
(1686167,58,20,28,1,'Jumalattomat pakenevat, vaikka ei kenkään aja takaa, mutta vanhurskaat ovat turvassa kuin nuori jalopeura.'),
(1686168,58,20,28,2,'Rikkomisensa tähden maa saa ruhtinaita paljon, mutta yhden ymmärtäväisen miehen taidolla järjestys kauan pysyy.'),
(1686169,58,20,28,3,'Köyhä mies, joka vaivaisia sortaa, on kuin sade, joka lyö lakoon eikä anna leipää.'),
(1686170,58,20,28,4,'Lain hylkijät kehuvat jumalattomia, mutta lain noudattajat kauhistuvat heitä.'),
(1686171,58,20,28,5,'Pahat ihmiset eivät ymmärrä, mikä oikein on, mutta Herraa etsiväiset ymmärtävät kaiken.'),
(1686172,58,20,28,6,'Parempi on köyhä, joka nuhteettomasti vaeltaa, kuin kahdella tiellä mutkitteleva rikas.'),
(1686173,58,20,28,7,'Joka laista ottaa vaarin, on ymmärtäväinen poika; mutta irstailijain seuratoveri saattaa isänsä häpeään.'),
(1686174,58,20,28,8,'Joka kartuttaa varojaan korolla ja voitolla, kokoaa niitä sille, joka vaivaisia armahtaa.'),
(1686175,58,20,28,9,'Joka korvansa kääntää kuulemasta lakia, sen rukouskin on kauhistus.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686176,58,20,28,10,'Joka eksyttää oikeamielisiä pahalle tielle, se lankeaa omaan kuoppaansa; mutta nuhteettomat perivät onnen.'),
(1686177,58,20,28,11,'Rikas mies on omissa silmissään viisas, mutta ymmärtäväinen köyhä ottaa hänestä selvän.'),
(1686178,58,20,28,12,'Kun vanhurskaat riemuitsevat, on ihanuus suuri; mutta kun jumalattomat nousevat, saa ihmisiä hakea.'),
(1686179,58,20,28,13,'Joka rikkomuksensa salaa, se ei menesty; mutta joka ne tunnustaa ja hylkää, se saa armon.'),
(1686180,58,20,28,14,'Onnellinen se ihminen, joka aina on aralla tunnolla; mutta joka sydämensä paaduttaa, se onnettomuuteen lankeaa.'),
(1686181,58,20,28,15,'Kuin muriseva leijona ja ahnas karhu on kurjan kansan jumalaton hallitsija.'),
(1686182,58,20,28,16,'Vähätaitoinen ruhtinas runsaasti kiskoo, mutta väärän voiton vihaaja saa elää kauan.'),
(1686183,58,20,28,17,'Ihmisen, jota verivelka painaa, on pakoiltava hamaan hautaan asti; älköön häntä suojeltako.'),
(1686184,58,20,28,18,'Nuhteettomasti vaeltavainen saa avun, mutta kahdella tiellä mutkittelija kerralla kaatuu.'),
(1686185,58,20,28,19,'Joka peltonsa viljelee, saa leipää kyllin, mutta tyhjän tavoittelija saa köyhyyttä kyllin.'),
(1686186,58,20,28,20,'Luotettava mies saa runsaan siunauksen, mutta jolla on kiihko rikastua, se ei rankaisematta jää.'),
(1686187,58,20,28,21,'Ei ole hyvä henkilöön katsoa, mutta leipäpalankin tähden rikkomus tehdään.'),
(1686188,58,20,28,22,'Pahansuova haluaa kiihkeästi varallisuutta eikä tiedä, että hänet tapaa puute.'),
(1686189,58,20,28,23,'Joka toista nuhtelee, niinkuin minä neuvon, saa suosiota enemmän kuin se, joka kielellänsä liehakoitsee.'),
(1686190,58,20,28,24,'Joka isältään ja äidiltään riistää ja sanoo: "Ei tämä ole rikos", se on tuhontekijän toveri.'),
(1686191,58,20,28,25,'Tavaranahne nostaa riidan, mutta Herraan luottavainen tulee ravituksi.'),
(1686192,58,20,28,26,'Omaan sydämeensä luottavainen on tyhmä, mutta viisaudessa vaeltava pelastuu.'),
(1686193,58,20,28,27,'Joka köyhälle antaa, se ei puutteeseen joudu; mutta joka silmänsä häneltä sulkee, saa kirouksia paljon.'),
(1686194,58,20,28,28,'Kun jumalattomat nousevat, piileksivät ihmiset; mutta kun he hukkuvat, niin hurskaat enentyvät.'),
(1686195,58,20,29,1,'Kuritusta saanut mies, joka niskurina pysyy, rusennetaan äkisti, eikä apua ole.'),
(1686196,58,20,29,2,'Hurskaitten enentyessä kansa iloitsee, mutta jumalattoman hallitessa kansa huokaa.'),
(1686197,58,20,29,3,'Viisautta rakastavainen on isällensä iloksi, mutta porttojen seuratoveri hävittää varansa.'),
(1686198,58,20,29,4,'Oikeudella kuningas pitää maan pystyssä, mutta verojen kiskoja sen hävittää.'),
(1686199,58,20,29,5,'Mies, joka lähimmäistään liehakoitsee, virittää verkon hänen askeleilleen.'),
(1686200,58,20,29,6,'Pahalle miehelle on oma rikos paulaksi, mutta vanhurskas saa riemuita ja iloita.'),
(1686201,58,20,29,7,'Vanhurskas tuntee vaivaisten asian, mutta jumalaton ei siitä mitään ymmärrä.'),
(1686202,58,20,29,8,'Pilkkaajat kaupungin villitsevät, mutta viisaat hillitsevät vihan.'),
(1686203,58,20,29,9,'Viisas mies kun käräjöi hullun miehen kanssa, niin tämä reutoo ja nauraa eikä asetu.'),
(1686204,58,20,29,10,'Murhamiehet vihaavat nuhteetonta, oikeamielisten henkeä he väijyvät.'),
(1686205,58,20,29,11,'Tyhmä purkaa kaiken sisunsa, mutta viisas sen viimein tyynnyttää.'),
(1686206,58,20,29,12,'Hallitsija, joka kuuntelee valhepuheita, saa palvelijoikseen pelkkiä jumalattomia.'),
(1686207,58,20,29,13,'Köyhä ja sortaja kohtaavat toisensa; kumpaisenkin silmille Herra antaa valon.'),
(1686208,58,20,29,14,'Kuninkaalla, joka tuomitsee vaivaisia oikein, on valtaistuin iäti vahva.'),
(1686209,58,20,29,15,'Vitsa ja nuhde antavat viisautta, mutta kuriton poika on äitinsä häpeä.'),
(1686210,58,20,29,16,'Kun jumalattomat lisääntyvät, lisääntyy rikos, mutta vanhurskaat saavat nähdä, kuinka he kukistuvat.'),
(1686211,58,20,29,17,'Kurita poikaasi, niin hän sinua virvoittaa ja sielullesi herkkuja tarjoaa.'),
(1686212,58,20,29,18,'Missä ilmoitus puuttuu, siinä kansa käy kurittomaksi; autuas se, joka noudattaa lakia.'),
(1686213,58,20,29,19,'Ei ota palvelija sanoista ojentuakseen: hän kyllä ymmärtää, mutta ei tottele.'),
(1686214,58,20,29,20,'Näet miehen, kärkkään puhumaan - enemmän on toivoa tyhmästä kuin hänestä.'),
(1686215,58,20,29,21,'Jos palvelijaansa nuoresta pitäen hemmottelee, tulee hänestä lopulta kiittämätön.'),
(1686216,58,20,29,22,'Pikavihainen mies nostaa riidan, ja kiukkuinen tulee rikkoneeksi paljon.'),
(1686217,58,20,29,23,'Ihmisen alentaa hänen oma ylpeytensä, mutta alavamielinen saa kunnian.'),
(1686218,58,20,29,24,'Joka käy osille varkaan kanssa, se sieluansa vihaa; hän kuulee vannotuksen, mutta ei ilmaise mitään.'),
(1686219,58,20,29,25,'Ihmispelko panee paulan, mutta Herraan luottavainen on turvattu.'),
(1686220,58,20,29,26,'Hallitsijan suosiota etsivät monet, mutta Herralta tulee miehelle oikeus.'),
(1686221,58,20,29,27,'Vääryyden mies on vanhurskaille kauhistus, ja oikean tien kulkija on kauhistus jumalattomalle.'),
(1686222,58,20,30,1,'Aagurin, Jaaken pojan, sanat; lauselma. Näin puhuu se mies: Minä olen väsyttänyt itseni, Jumala; olen väsyttänyt itseni, Jumala, ja menehdyn.'),
(1686223,58,20,30,2,'Sillä järjetön olen minä mieheksi, ei ole minulla ihmisymmärrystä;'),
(1686224,58,20,30,3,'enkä ole oppinut viisautta, tullakseni tuntemaan Pyhintä.'),
(1686225,58,20,30,4,'Kuka on noussut taivaaseen ja astunut sieltä alas? Kuka on koonnut kouriinsa tuulen? Kuka on sitonut vedet vaipan sisään? Kuka on kohdalleen asettanut maan ääret kaikki? Mikä on hänen nimensä ja mikä hänen poikansa nimi, jos sen tiedät?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686226,58,20,30,5,'Jokainen Jumalan sana on taattu; hän on niiden kilpi, jotka häneen turvaavat.'),
(1686227,58,20,30,6,'Älä lisää hänen sanoihinsa mitään, ettei hän vaatisi sinua tilille ja ettet valhettelijaksi joutuisi.'),
(1686228,58,20,30,7,'Kahta minä sinulta pyydän, älä niitä minulta koskaan kiellä, kuolemaani saakka:'),
(1686229,58,20,30,8,'Vilppi ja valhepuhe pidä minusta kaukana. Älä köyhyyttä, älä rikkautta minulle anna; anna minulle ravinnoksi määräosani leipää,'),
(1686230,58,20,30,9,'etten kylläisenä tulisi kieltäjäksi ja sanoisi: "Kuka on Herra?" ja etten köyhtyneenä varastaisi ja rikkoisi Jumalani nimeä vastaan.'),
(1686231,58,20,30,10,'Älä kieli palvelijasta hänen herrallensa; muutoin hän sinut kiroaa, ja sinä saat siitä kärsiä.'),
(1686232,58,20,30,11,'Voi sukua, joka isäänsä kiroaa eikä siunaa äitiänsä;'),
(1686233,58,20,30,12,'sukua, joka on omissa silmissään puhdas, vaikka ei ole pesty liastansa!'),
(1686234,58,20,30,13,'Voi sukua - kuinka ylpeät ovatkaan sen silmät ja kuinka korskea silmänluonti -'),
(1686235,58,20,30,14,'sukua, jonka hampaat ovat miekkoja ja leukaluut veitsiä syödäksensä kurjat maasta pois ja köyhät ihmisten joukosta!'),
(1686236,58,20,30,15,'Verenimijällä on kaksi tytärtä: Anna vielä! Anna vielä! Kolme on, jotka eivät kylläänsä saa, neljä, jotka eivät sano: "Jo riittää":'),
(1686237,58,20,30,16,'tuonela, hedelmätön kohtu, maa, joka ei saa kylläänsä vedestä, ja tuli, joka ei sano: "Jo riittää".'),
(1686238,58,20,30,17,'Joka isäänsä pilkkaa ja pitää halpana totella äitiänsä, häneltä korpit puron luona hakkaavat silmän, ja kotkan poikaset syövät sen.'),
(1686239,58,20,30,18,'Kolme on minusta ylen ihmeellistä, ja neljä on, joita en käsitä:'),
(1686240,58,20,30,19,'kotkan jäljet taivaalla, käärmeen jäljet kalliolla, laivan jäljet keskellä merta ja miehen jäljet nuoren naisen tykönä.'),
(1686241,58,20,30,20,'Samoin ovat avionrikkoja-vaimon jäljet: hän syö, pyyhkii suunsa ja sanoo: "En ole pahaa tehnyt".'),
(1686242,58,20,30,21,'Kolmen alla järkkyy maa, ja neljän alla ei se jaksa kestää:'),
(1686243,58,20,30,22,'orjan alla, kun hän kuninkaaksi pääsee, houkan, kun hän saa kyllälti leipää,'),
(1686244,58,20,30,23,'hyljityn alla, kun hän miehen saa, ja palvelijattaren, kun hän emäntänsä syrjäyttää.'),
(1686245,58,20,30,24,'Neljä on maassa vähäisintä, mutta viisaan viisasta silti:'),
(1686246,58,20,30,25,'Muurahaiset ovat voimaton kansa, mutta he hankkivat leipänsä kesällä;'),
(1686247,58,20,30,26,'tamaanit ovat heikko kansa, mutta he laittavat majansa kallioihin;'),
(1686248,58,20,30,27,'heinäsirkoilla ei ole kuningasta, mutta koko lauma lähtee järjestyksessä liikkeelle;'),
(1686249,58,20,30,28,'sisiliskoon voi tarttua käsin, mutta kuitenkin se oleskelee kuninkaan linnoissa.'),
(1686250,58,20,30,29,'Kolmella on komea astunta, ja neljä komeasti kulkee:'),
(1686251,58,20,30,30,'leijona, sankari eläinten joukossa, joka ei vääjää ketään,'),
(1686252,58,20,30,31,'hevonen, solakkakylki, tai kauris, ja kuningas joukkonsa johdossa.'),
(1686253,58,20,30,32,'Jos ylpeilit - olipa se houkkamaisuutta tai harkittua - niin laske käsi suullesi.'),
(1686254,58,20,30,33,'Sillä maitoa pusertamalla saa voin, nenää pusertamalla saa veren, ja vihoja pusertamalla saa riidan.'),
(1686255,58,20,31,1,'Lemuelin, Massan kuninkaan, sanat, joilla hänen äitinsä kasvatti häntä.'),
(1686256,58,20,31,2,'Mitä, poikani; mitä, kohtuni poika; mitä, lupausteni poika?'),
(1686257,58,20,31,3,'Älä anna voimaasi naisille, vaellustasi kuningasten turmelijatarten valtaan.'),
(1686258,58,20,31,4,'Ei sovi kuningasten, Lemuel, ei sovi kuningasten viiniä juoda eikä ruhtinasten kysellä: "Missä väkijuomaa?"'),
(1686259,58,20,31,5,'Muutoin hän juodessaan unhottaa, mitä saädetty on, ja vääntelee kaikkien kurjuuden lasten oikeuden.'),
(1686260,58,20,31,6,'Antakaa väkevää juomaa menehtyvälle ja viiniä murhemielisille.'),
(1686261,58,20,31,7,'Sellainen juokoon ja unhottakoon köyhyytensä älköönkä enää vaivaansa muistelko.'),
(1686262,58,20,31,8,'Avaa suusi mykän hyväksi, oikeuden hankkimiseksi kaikille sortuville.'),
(1686263,58,20,31,9,'Avaa suusi, tuomitse oikein, hanki kurjalle ja köyhälle oikeus.'),
(1686264,58,20,31,10,'Kelpo vaimon kuka löytää? Sellaisen arvo on helmiä paljon kalliimpi.'),
(1686265,58,20,31,11,'Hänen miehensä sydän häneen luottaa, eikä siltä mieheltä riistaa puutu.'),
(1686266,58,20,31,12,'Hän tekee miehellensä hyvää, ei pahaa, kaikkina elinpäivinänsä.'),
(1686267,58,20,31,13,'Hän puuhaa villat ja pellavat ja halullisin käsin askartelee.'),
(1686268,58,20,31,14,'Hän on kauppiaan laivojen kaltainen: leipänsä hän noutaa kaukaa.'),
(1686269,58,20,31,15,'Kun yö vielä on, hän nousee ja antaa ravinnon perheellensä, piioilleen heidän osansa.'),
(1686270,58,20,31,16,'Hän haluaa peltoa ja hankkii sen, istuttaa viinitarhan kättensä hedelmällä.'),
(1686271,58,20,31,17,'Hän voimalla vyöttää kupeensa ja käsivartensa vahvistaa.'),
(1686272,58,20,31,18,'Hankkeensa hän huomaa käyvän hyvin, ei sammu hänen lamppunsa yöllä.'),
(1686273,58,20,31,19,'Hän ojentaa kätensä kehrävarteen ja käyttelee värttinää kämmenissään.'),
(1686274,58,20,31,20,'Hän avaa kätensä kurjalle, ojentaa köyhälle molemmat kätensä.'),
(1686275,58,20,31,21,'Ei pelkää hän perheensä puolesta lunta, sillä koko hänen perheensä on puettu purppuravillaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686276,58,20,31,22,'Hän valmistaa itsellensä peitteitä; hienoa pellavaa ja punapurppuraa on hänen pukunsa.'),
(1686277,58,20,31,23,'Hänen miehensä on tunnettu porteissa, maanvanhinten seassa istuessansa.'),
(1686278,58,20,31,24,'Hän aivinapaitoja tekee ja myy, vöitä hän kauppiaalle toimittaa.'),
(1686279,58,20,31,25,'Vallalla ja kunnialla hän on vaatetettu, ja hän nauraa tulevalle päivälle.'),
(1686280,58,20,31,26,'Suunsa hän avaa viisauden sanoihin, hänen kielellään on lempeä opetus.'),
(1686281,58,20,31,27,'Hän tarkkaa talonsa menoa, eikä hän laiskan leipää syö.'),
(1686282,58,20,31,28,'Hänen poikansa nousevat ja kiittävät hänen onneansa; hänen miehensä nousee ja ylistää häntä:'),
(1686283,58,20,31,29,'"Paljon on naisia, toimellisia menoissaan, mutta yli niitten kaikkien kohoat sinä".'),
(1686284,58,20,31,30,'Pettävä on sulous, kauneus katoavainen; ylistetty se vaimo, joka Herraa pelkää!'),
(1686285,58,21,1,1,'Saarnaajan sanat, Daavidin pojan, joka oli kuninkaana Jerusalemissa.'),
(1686286,58,21,1,2,'Turhuuksien turhuus, sanoi saarnaaja, turhuuksien turhuus; kaikki on turhuutta!'),
(1686287,58,21,1,3,'Mitä hyötyä on ihmiselle kaikesta vaivannäöstänsä, jolla hän vaivaa itseänsä auringon alla?'),
(1686288,58,21,1,4,'Sukupolvi menee, ja sukupolvi tulee, mutta maa pysyy iäti.'),
(1686289,58,21,1,5,'Ja aurinko nousee, ja aurinko laskee ja kiiruhtaa sille sijallensa, josta se jälleen nousee.'),
(1686290,58,21,1,6,'Tuuli menee etelään ja kiertää pohjoiseen, kiertää yhä kiertämistään, ja samalle kierrollensa tuuli palajaa.'),
(1686291,58,21,1,7,'Kaikki joet laskevat mereen, mutta meri ei siitänsä täyty; samaan paikkaan, johon joet ovat laskeneet, ne aina edelleen laskevat.'),
(1686292,58,21,1,8,'Kaikki tyynni itseänsä väsyttää, niin ettei kukaan sitä sanoa saata. Ei saa silmä kylläänsä näkemisestä eikä korva täyttänsä kuulemisesta.'),
(1686293,58,21,1,9,'Mitä on ollut, sitä vastakin on; ja mitä on tapahtunut, sitä vastakin tapahtuu. Ei ole mitään uutta auringon alla.'),
(1686294,58,21,1,10,'Jos jotakin on, josta sanotaan: "Katso, tämä on uutta", niin on sitä kuitenkin ollut jo ennen, ammoisina aikoina, jotka ovat olleet ennen meitä.'),
(1686295,58,21,1,11,'Ei jää muistoa esi-isistä; eikä jälkeläisistäkään, jotka tulevat, jää muistoa niille, jotka heidän jälkeensä tulevat.'),
(1686296,58,21,1,12,'Minä, saarnaaja, olin Israelin kuningas Jerusalemissa.'),
(1686297,58,21,1,13,'Ja minä käänsin sydämeni viisaudella tutkimaan ja miettimään kaikkea, mitä auringon alla tapahtuu. Tämä on vaikea työ, jonka Jumala on antanut ihmislapsille, heidän sillä itseään rasittaaksensa.'),
(1686298,58,21,1,14,'Minä katselin kaikkia tekoja, mitä tehdään auringon alla, ja katso, se on kaikki turhuutta ja tuulen tavoittelua.'),
(1686299,58,21,1,15,'Väärä ei voi suoristua, eikä vajaata voi täydeksi laskea.'),
(1686300,58,21,1,16,'Minä puhuin sydämessäni näin: Minä olen hankkinut suuren viisauden ja sitä yhä lisännyt, jopa yli kaikkien, jotka ovat ennen minua Jerusalemissa hallinneet, ja paljon on sydämeni nähnyt viisautta ja tietoa.'),
(1686301,58,21,1,17,'Ja minä käänsin sydämeni tutkimaan viisautta ja tietoa, mielettömyyttä ja tyhmyyttä, ja minä tulin tietämään, että sekin oli tuulen tavoittelemista.'),
(1686302,58,21,1,18,'Sillä missä on paljon viisautta, siinä on paljon surua; ja joka tietoa lisää, se tuskaa lisää.'),
(1686303,58,21,2,1,'Minä sanoin sydämessäni: Tule, minä tahdon koetella sinua ilolla, nauti hyvää. Mutta katso, sekin oli turhuutta.'),
(1686304,58,21,2,2,'Naurusta minä sanoin: "Mieletöntä!" ja ilosta: "Mitä se toimittaa?"'),
(1686305,58,21,2,3,'Minä mietin mielessäni virkistää ruumistani viinillä - kuitenkin niin, että sydämeni harrastaisi viisautta - ja noudattaa tyhmyyttä, kunnes saisin nähdä, mikä olisi ihmislapsille hyvä, heidän tehdäksensä sitä taivaan alla lyhyinä elämänsä päivinä.'),
(1686306,58,21,2,4,'Minä tein suuria töitä: rakensin itselleni taloja, istutin itselleni viinitarhoja.'),
(1686307,58,21,2,5,'Minä laitoin itselleni puutarhoja ja puistoja ja istutin niihin kaikkinaisia hedelmäpuita.'),
(1686308,58,21,2,6,'Minä tein itselleni vesilammikoita kastellakseni niistä metsiköitä, joissa puita kasvoi.'),
(1686309,58,21,2,7,'Minä ostin orjia ja orjattaria, ja kotona syntyneitäkin minulla oli; myös oli minulla karjaa, raavaita ja lampaita, paljon enemmän kuin kenelläkään niistä, jotka olivat olleet ennen minua Jerusalemissa.'),
(1686310,58,21,2,8,'Minä kokosin itselleni myöskin hopeata ja kultaa ja kuninkaitten ja maakuntien aarteita ja hankin itselleni laulajia ja laulajattaria ja ihmislasten iloja, vaimon, jopa vaimoja.'),
(1686311,58,21,2,9,'Minä tulin suureksi ja yhä suuremmaksi, yli kaikkien, jotka olivat olleet ennen minua Jerusalemissa. Sen ohessa pysyi minussa viisauteni.'),
(1686312,58,21,2,10,'Enkä minä pidättänyt silmiäni mistään, mitä ne pyysivät, enkä kieltänyt sydämeltäni mitään iloa, sillä minun sydämeni iloitsi kaikesta vaivannäöstäni, ja se oli minun osani kaikesta vaivannäöstäni.'),
(1686313,58,21,2,11,'Mutta kun minä käänsin huomioni kaikkiin töihin, joita minun käteni olivat tehneet, ja vaivannäköön, jolla olin vaivannut itseäni niitä tehdessäni, niin katso: se oli kaikki turhuutta ja tuulen tavoittelua; eikä ole hyötyä mistään auringon alla.'),
(1686314,58,21,2,12,'Kun minä käännyin katsomaan viisautta ja mielettömyyttä ja tyhmyyttä - sillä mitä taitaa ihminen, joka tulee kuninkaan jälkeen, muuta kuin tehdä, mitä jo ennen on tehty? -'),
(1686315,58,21,2,13,'niin minä näin, että viisaus on hyödyllisempi tyhmyyttä, niinkuin valo on pimeyttä hyödyllisempi.'),
(1686316,58,21,2,14,'Viisaalla on silmät päässänsä, tyhmä taas vaeltaa pimeässä; mutta minä tulin tietämään myös sen, että toisen käy niinkuin toisenkin.'),
(1686317,58,21,2,15,'Ja minä sanoin sydämessäni: Se, mikä kohtaa tyhmää, kohtaa minuakin; miksi olen sitten niin tuiki viisaaksi tullut? Ja minä sanoin sydämessäni: Tämäkin on turhuutta.'),
(1686318,58,21,2,16,'Sillä ei jää viisaasta, niinkuin ei tyhmästäkään, ikuista muistoa, kun kerran tulevina päivinä kaikki unhotetaan; ja eikö kuole viisas niinkuin tyhmäkin?'),
(1686319,58,21,2,17,'Niin minä kyllästyin elämään, sillä minusta oli pahaa se, mikä tapahtuu auringon alla, koskapa kaikki on turhuutta ja tuulen tavoittelua.'),
(1686320,58,21,2,18,'Ja minä kyllästyin kaikkeen vaivannäkööni, jolla olin vaivannut itseäni auringon alla, koska minun täytyy se jättää ihmiselle, joka tulee minun jälkeeni.'),
(1686321,58,21,2,19,'Ja kuka tietää, onko hän viisas vai tyhmä? Mutta hallitsemaan hän tulee kaikkia minun vaivannäköni hedelmiä, joiden tähden minä olen vaivannut itseäni ja ollut viisas auringon alla. Tämäkin on turhuutta.'),
(1686322,58,21,2,20,'Niin minä annoin sydämeni vaipua epätoivoon kaikesta vaivannäöstäni, jolla olin vaivannut itseäni auringon alla.'),
(1686323,58,21,2,21,'Sillä niin on: ihmisen, joka on vaivaa nähnyt toimien viisaudella, tiedolla ja kunnolla, täytyy antaa kaikki ihmiselle, joka ei ole siitä vaivaa nähnyt, hänen osaksensa. Sekin on turhuutta ja on suuri onnettomuus.'),
(1686324,58,21,2,22,'Sillä mitä saa ihminen kaikesta vaivannäöstänsä ja sydämensä pyrkimyksestä, jolla hän vaivaa itseänsä auringon alla?'),
(1686325,58,21,2,23,'Ovathan kaikki hänen päivänsä pelkkää tuskaa ja hänen työnsä surua, eikä yölläkään hänen sydämensä saa lepoa. Tämäkin on turhuutta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686326,58,21,2,24,'Ei ole ihmisellä muuta onnea kuin syödä ja juoda ja antaa sielunsa nauttia hyvää vaivannäkönsä ohessa; mutta minä tulin näkemään, että sekin tulee Jumalan kädestä.'),
(1686327,58,21,2,25,'- "Sillä kuka voi syödä ja kuka nauttia ilman minua?" -'),
(1686328,58,21,2,26,'Sillä hän antaa ihmiselle, joka on hänelle otollinen, viisautta, tietoa ja iloa; mutta syntiselle hän antaa työksi koota ja kartuttaa annettavaksi sille, joka on otollinen Jumalalle. Sekin on turhuutta ja tuulen tavoittelua.'),
(1686329,58,21,3,1,'Kaikella on määräaika, ja aikansa on joka asialla taivaan alla.'),
(1686330,58,21,3,2,'Aika on syntyä ja aika kuolla. Aika on istuttaa ja aika repiä istutus.'),
(1686331,58,21,3,3,'Aika on surmata ja aika parantaa. Aika on purkaa ja aika rakentaa.'),
(1686332,58,21,3,4,'Aika on itkeä ja aika nauraa. Aika on valittaa ja aika hypellä.'),
(1686333,58,21,3,5,'Aika on heitellä kiviä ja aika kerätä kivet. Aika on syleillä ja aika olla syleilemättä.'),
(1686334,58,21,3,6,'Aika on etsiä ja aika kadottaa. Aika on säilyttää ja aika viskata pois.'),
(1686335,58,21,3,7,'Aika on reväistä rikki ja aika ommella yhteen. Aika on olla vaiti ja aika puhua.'),
(1686336,58,21,3,8,'Aika on rakastaa ja aika vihata. Aika on sodalla ja aika rauhalla.'),
(1686337,58,21,3,9,'Mitä hyötyä on työntekijällä siitä, mistä hän näkee vaivaa?'),
(1686338,58,21,3,10,'Minä olen katsonut sitä työtä, minkä Jumala on antanut ihmislapsille, heidän sillä itseään rasittaaksensa.'),
(1686339,58,21,3,11,'Kaiken hän on tehnyt kauniisti aikanansa, myös iankaikkisuuden hän on pannut heidän sydämeensä; mutta niin on, ettei ihminen käsitä tekoja, jotka Jumala on tehnyt, ei alkua eikä loppua.'),
(1686340,58,21,3,12,'Minä tulin tietämään, ettei heillä ole muuta onnea kuin iloita ja tehdä hyvää eläessänsä.'),
(1686341,58,21,3,13,'Mutta jokaiselle ihmiselle on sekin, että hän syö ja juo ja nauttii hyvää kaiken vaivannäkönsä ohessa, Jumalan lahja.'),
(1686342,58,21,3,14,'Minä tulin tietämään, että kaikki, mitä Jumala tekee, pysyy iäti. Ei ole siihen lisäämistä eikä siitä vähentämistä. Ja Jumala on sen niin tehnyt, että häntä peljättäisiin.'),
(1686343,58,21,3,15,'Mitä nyt on, sitä on ollut jo ennenkin; ja mitä vasta on oleva, sitä on ollut jo ennenkin. Jumala etsii jälleen sen, mikä on mennyttä.'),
(1686344,58,21,3,16,'Vielä minä näin auringon alla oikeuspaikan, ja siinä oli vääryys, ja vanhurskauden paikan, ja siinä oli vääryys.'),
(1686345,58,21,3,17,'Minä sanoin sydämessäni: Vanhurskaan ja väärän tuomitsee Jumala, sillä siellä on jokaisella asialla ja jokaisella teolla aikansa.'),
(1686346,58,21,3,18,'Minä sanoin sydämessäni: Ihmislasten tähden se niin on, jotta Jumala heitä koettelisi ja he tulisivat näkemään, että he omassa olossaan ovat eläimiä.'),
(1686347,58,21,3,19,'Sillä ihmislasten käy niinkuin eläintenkin; sama on kumpienkin kohtalo. Niinkuin toiset kuolevat, niin toisetkin kuolevat; yhtäläinen henki on kaikilla. Ihmisillä ei ole mitään etua eläinten edellä, sillä kaikki on turhuutta.'),
(1686348,58,21,3,20,'Kaikki menee samaan paikkaan. Kaikki on tomusta tullut, ja kaikki palajaa tomuun.'),
(1686349,58,21,3,21,'Kuka tietää ihmisen hengestä, kohoaako se ylös, ja eläimen hengestä, vajoaako se alas maahan?'),
(1686350,58,21,3,22,'Niin minä tulin näkemään, että ei ole mitään parempaa, kuin että ihminen iloitsee teoistansa, sillä se on hänen osansa. Sillä kuka tuo hänet takaisin näkemään iloksensa sitä, mikä tulee hänen jälkeensä?'),
(1686351,58,21,4,1,'Taas minä katselin kaikkea sortoa, jota harjoitetaan auringon alla, ja katso, siinä on sorrettujen kyyneleet, eikä ole heillä lohduttajaa; väkivaltaa tekee heidän sortajainsa käsi, eikä ole heillä lohduttajaa.'),
(1686352,58,21,4,2,'Ja minä ylistin vainajia, jotka ovat jo kuolleet, onnellisemmiksi kuin eläviä, jotka vielä ovat elossa,'),
(1686353,58,21,4,3,'ja onnellisemmaksi kuin nämä kumpikaan sitä, joka ei vielä ole olemassa eikä ole nähnyt sitä pahaa, mikä tapahtuu auringon alla.'),
(1686354,58,21,4,4,'Ja minä näin kaikesta vaivannäöstä ja työn kunnollisuudesta, että se on toisen kateutta toista kohtaan.'),
(1686355,58,21,4,5,'Sekin on turhuutta ja tuulen tavoittelua. Tyhmä panee kädet ristiin ja kalvaa omaa lihaansa.'),
(1686356,58,21,4,6,'Parempi on pivollinen lepoa kuin kahmalollinen vaivannäköä ja tuulen tavoittelua.'),
(1686357,58,21,4,7,'Taas minä näin turhuuden auringon alla:'),
(1686358,58,21,4,8,'Tuossa on yksinäinen, ei ole hänellä toista, ei poikaa, ei veljeäkään ole hänellä; mutta ei ole loppua kaikella hänen vaivannäöllänsä, eikä hänen silmänsä saa kylläänsä rikkaudesta. Ja kenen hyväksi minä sitten vaivaa näen ja pidätän itseni nautinnoista? Tämäkin on turhuutta ja on paha asia.'),
(1686359,58,21,4,9,'Kahden on parempi kuin yksin, sillä heillä on vaivannäöstänsä hyvä palkka.'),
(1686360,58,21,4,10,'Jos he lankeavat, niin toinen nostaa ylös toverinsa; mutta voi yksinäistä, jos hän lankeaa! Ei ole toista nostamassa häntä ylös.'),
(1686361,58,21,4,11,'Myös, jos kaksi makaa yhdessä, on heillä lämmin; mutta kuinka voisi yksinäisellä olla lämmin?'),
(1686362,58,21,4,12,'Ja yksinäisen kimppuun voi joku käydä, mutta kaksi pitää sille puolensa. Eikä kolmisäinen lanka pian katkea.'),
(1686363,58,21,4,13,'Parempi on köyhä, mutta viisas nuorukainen kuin vanha ja tyhmä kuningas, joka ei enää ymmärrä ottaa varoituksesta vaaria.'),
(1686364,58,21,4,14,'Sillä vankilasta tuo toinen lähti tullaksensa kuninkaaksi, vaikka oli hänen kuninkaana ollessaan syntynyt köyhänä.'),
(1686365,58,21,4,15,'Minä näin kaikkien, jotka elivät ja vaelsivat auringon alla, olevan nuorukaisen puolella, tuon toisen, joka oli astuva hänen sijaansa.'),
(1686366,58,21,4,16,'Ei ollut loppua kaikella sillä väellä, niillä kaikilla, joita hän johti; mutta jälkipolvet eivät hänestä iloitse. Sillä sekin on turhuutta ja tuulen tavoittelemista.'),
(1686367,58,21,5,1,'Varo jalkasi, kun menet Jumalan huoneeseen. Tulo kuulemaan on parempi kuin tyhmäin teurasuhrin-anto, sillä he ovat tietämättömiä, ja niin he tekevät pahaa. (5:1) Älä ole kerkeä suultasi, älköönkä sydämesi kiirehtikö lausumaan sanaa Jumalan edessä, sillä Jumala on taivaassa ja sinä olet maan päällä; sentähden olkoot sanasi harvat.'),
(1686368,58,21,5,2,'Sillä paljosta työstä tulee unia, ja missä on paljon sanoja, siinä on tyhmä äänessä.'),
(1686369,58,21,5,3,'Kun teet lupauksen Jumalalle, niin täytä se viivyttelemättä; sillä ei ole hänellä mielisuosiota tyhmiin: täytä, mitä lupaat.'),
(1686370,58,21,5,4,'On parempi, ettet lupaa, kuin että lupaat etkä täytä.'),
(1686371,58,21,5,5,'Älä anna suusi saattaa ruumistasi syynalaiseksi, äläkä sano Jumalan sanansaattajan edessä: "Se oli erehdys"; miksi pitäisi Jumalan vihastua sinun puheestasi ja turmella sinun kättesi työt?'),
(1686372,58,21,5,6,'Sillä paljot unet ovat pelkkää turhuutta; samoin paljot puheet. Mutta pelkää sinä Jumalaa.'),
(1686373,58,21,5,7,'Jos näet köyhää sorrettavan sekä oikeutta ja vanhurskautta poljettavan maakunnassa, niin älä sitä asiaa ihmettele; sillä ylhäistä vartioitsee vielä ylhäisempi, ja sitäkin ylhäisemmät heitä molempia.'),
(1686374,58,21,5,8,'Ja maalle on kaikessa hyödyksi, että viljellyllä maalla on kuningas.'),
(1686375,58,21,5,9,'Joka rakastaa rahaa, ei saa rahaa kylläksensä, eikä voittoa se, joka rakastaa tavaran paljoutta. Sekin on turhuutta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686376,58,21,5,10,'Omaisuuden karttuessa karttuvat sen syöjätkin; ja mitä muuta etua siitä on haltijallensa, kuin että silmillään sen näkee?'),
(1686377,58,21,5,11,'Työntekijän uni on makea, söipä hän vähän tai paljon; mutta rikkaan ei hänen yltäkylläisyytensä salli nukkua.'),
(1686378,58,21,5,12,'On raskas onnettomuus, jonka minä näin auringon alla: rikkaus, joka on säilytetty onnettomuudeksi haltijallensa.'),
(1686379,58,21,5,13,'Se rikkaus katoaa onnettoman tapauksen kautta; ja jos hänelle on syntynyt poika, ei sen käsiin jää mitään.'),
(1686380,58,21,5,14,'Niinkuin hän tuli äitinsä kohdusta, niin on hänen alastonna jälleen mentävä pois, samoin kuin tulikin; eikä hän vaivannäöstänsä saa mitään, minkä veisi täältä kädessänsä.'),
(1686381,58,21,5,15,'Raskas onnettomuus tämäkin on: aivan niinkuin hän tuli, on hänen mentävä; ja mitä hyötyä hänellä sitten on siitä, että on vaivaa nähnyt tuulen hyväksi?'),
(1686382,58,21,5,16,'Myös kuluttaa hän kaikki päivänsä pimeydessä; ja surua on hänellä paljon, kärsimystä ja mielikarvautta.'),
(1686383,58,21,5,17,'Katso, minkä minä olen tullut näkemään, on hyvää ja kaunista syödä ja juoda ja nauttia hyvää kaiken vaivannäkönsä ohessa, jolla ihminen itseänsä vaivaa auringon alla lyhyinä elämänsä päivinä, jotka Jumala on hänelle antanut; sillä se on hänen osansa.'),
(1686384,58,21,5,18,'Sekin on Jumalan lahja, jos Jumala kenelle ihmiselle antaa rikkautta ja tavaraa ja sallii hänen syödä siitä ja saada osansa ja iloita vaivannäkönsä ohessa.'),
(1686385,58,21,5,19,'Sillä hän ei tule niin paljon ajatelleeksi elämänsä päiviä, kun Jumala suostuu hänen sydämensä iloon.'),
(1686386,58,21,6,1,'On onnettomuus tämäkin, jonka olen nähnyt auringon alla ja joka raskaasti painaa ihmistä:'),
(1686387,58,21,6,2,'että Jumala antaa miehelle rikkautta ja tavaraa ja kunniaa, niin ettei hänen sielultaan puutu mitään kaikesta siitä, mitä hän halajaa, mutta Jumala ei salli hänen nauttia sitä, vaan sen nauttii vieras. Se on turhuutta ja raskas kärsimys.'),
(1686388,58,21,6,3,'Vaikka syntyisi miehelle sata lasta ja hän eläisi vuosia paljon ja paljot olisivat hänen vuottensa päivät, mutta hän ei saisi tyydyttää omaa haluaan omaisuudellansa eikä saisi edes hautaustakaan, niin minä sanon, että keskoinen olisi onnellisempi kuin hän.'),
(1686389,58,21,6,4,'Sillä se turhaan tulee ja pimeyteen menee, ja pimeyteen peittyy sen nimi.'),
(1686390,58,21,6,5,'Ei se ole aurinkoa nähnyt eikä tuntenut. Sen lepo on parempi kuin hänen.'),
(1686391,58,21,6,6,'Ja vaikka hän eläisi kaksi kertaa tuhannen vuotta, mutta ei saisi onnea nähdä - eikö kuitenkin kaikki mene samaan paikkaan?'),
(1686392,58,21,6,7,'Kaikki ihmisen vaivannäkö tapahtuu hänen oman suunsa hyväksi, ja kuitenkaan ei halu täyty.'),
(1686393,58,21,6,8,'Sillä mitä etua on viisaalla tyhmän edellä, ja mitä kurjalla siitä, että hän osaa oikein vaeltaa elävitten edessä?'),
(1686394,58,21,6,9,'Parempi silmän näkö kuin halun haihattelu. Tämäkin on turhuutta ja tuulen tavoittelua.'),
(1686395,58,21,6,10,'Mitä olemassa on, sille on pantu nimi jo ammoin; ja edeltä tunnettua on ollut, mitä ihmisestä on tuleva. Ei voi hän riidellä väkevämpänsä kanssa.'),
(1686396,58,21,6,11,'Sillä niin on: puheen paljous enentää turhuutta. Mitä etua on ihmisellä siitä?'),
(1686397,58,21,7,1,'Sillä kuka tietää, mikä on ihmiselle hyvä elämässä, hänen elämänsä lyhyinä, turhina päivinä, jotka hän viettää kuin varjo; ja kuka ilmaisee ihmiselle, mitä on tuleva hänen jälkeensä auringon alla?'),
(1686398,58,21,7,2,'Hyvä nimi on parempi kuin kallis öljy, ja kuolinpäivä parempi kuin syntymäpäivä.'),
(1686399,58,21,7,3,'Parempi kuin pitotaloon on mennä surutaloon, sillä siinä on kaikkien ihmisten loppu, ja elossa oleva painaa sen mieleensä.'),
(1686400,58,21,7,4,'Suru on parempi kuin nauru, sillä sydämelle on hyväksi, että kasvot ovat murheelliset.'),
(1686401,58,21,7,5,'Viisaitten sydän on surutalossa, tyhmien sydän ilotalossa.'),
(1686402,58,21,7,6,'Parempi on kuulla viisaan nuhdetta, kuin olla kuulemassa tyhmien laulua;'),
(1686403,58,21,7,7,'sillä niinkuin orjantappurain rätinä padan alla, on tyhmän nauru. Ja sekin on turhuutta.'),
(1686404,58,21,7,8,'Sillä väärä voitto tekee viisaan hulluksi, ja lahja turmelee sydämen.'),
(1686405,58,21,7,9,'Asian loppu on parempi kuin sen alku, ja pitkämielinen on parempi kuin korkeamielinen.'),
(1686406,58,21,7,10,'Älköön mielesi olko pikainen vihaan, sillä viha majautuu tyhmäin poveen.'),
(1686407,58,21,7,11,'Älä sano: "Mikä siinä on, että entiset ajat olivat paremmat kuin nykyiset?" Sillä sitä et viisaudesta kysy.'),
(1686408,58,21,7,12,'Viisaus on yhtä hyvä kuin perintöosa ja on etu niille, jotka ovat näkemässä aurinkoa.'),
(1686409,58,21,7,13,'Sillä viisauden varjossa on kuin rahan varjossa, mutta tieto on hyödyllisempi: viisaus pitää haltijansa elossa.'),
(1686410,58,21,7,14,'Katso Jumalan tekoja; sillä kuka voi sen suoristaa, minkä hän on vääräksi tehnyt?'),
(1686411,58,21,7,15,'Hyvänä päivänä ole hyvillä mielin, ja pahana päivänä ymmärrä, että toisen niinkuin toisenkin on Jumala tehnyt, koskapa ihminen ei saa mitään siitä, mikä hänen jälkeensä tulee.'),
(1686412,58,21,7,16,'Kaikkea olen tullut näkemään turhina päivinäni: on vanhurskaita, jotka hukkuvat vanhurskaudessaan, ja on jumalattomia, jotka elävät kauan pahuudessaan.'),
(1686413,58,21,7,17,'Älä ole kovin vanhurskas äläkä esiinny ylen viisaana: miksi tuhoaisit itsesi?'),
(1686414,58,21,7,18,'Älä ole kovin jumalaton, äläkä ole tyhmä: miksi kuolisit ennen aikaasi?'),
(1686415,58,21,7,19,'Hyvä on, että pidät kiinni toisesta etkä hellitä kättäsi toisestakaan, sillä Jumalaa pelkääväinen selviää näistä kaikista.'),
(1686416,58,21,7,20,'Viisaus auttaa viisasta voimakkaammin kuin kymmenen vallanpitäjää, jotka ovat kaupungissa.'),
(1686417,58,21,7,21,'Sillä ei ole maan päällä ihmistä niin vanhurskasta, että hän tekisi vain hyvää eikä tekisi syntiä.'),
(1686418,58,21,7,22,'Älä myöskään pane mieleesi kaikkia puheita, mitä puhutaan, ettet kuulisi palvelijasi sinua kiroilevan.'),
(1686419,58,21,7,23,'Sillä oma sydämesikin tietää, että myös sinä olet monta kertaa kiroillut muita.'),
(1686420,58,21,7,24,'Kaiken tämän olen viisaudella koetellut. Minä sanoin: "Tahdon tulla viisaaksi", mutta se pysyi minusta kaukana.'),
(1686421,58,21,7,25,'Kaukana on kaiken olemus ja syvällä, syvällä; kuka voi sen löytää?'),
(1686422,58,21,7,26,'Minä ryhdyin sydämessäni oppimaan, miettimään ja etsimään viisautta ja tutkistelun tuloksia, tullakseni tuntemaan jumalattomuuden typeryydeksi ja tyhmyyden mielettömyydeksi.'),
(1686423,58,21,7,27,'Ja minä löysin sen, mikä on kuolemaa katkerampi: naisen, joka on verkko, jonka sydän on paula ja jonka kädet ovat kahleet. Se, joka on otollinen Jumalan edessä, pelastuu hänestä, mutta synnintekijä häneen takertuu.'),
(1686424,58,21,7,28,'Katso, tämän minä olen löytänyt, sanoi saarnaaja, pyrkiessäni asia asialta löytämään tutkistelun tulosta;'),
(1686425,58,21,7,29,'mitä sieluni on yhäti etsinyt, mutta mitä en ole löytänyt, on tämä: olen löytänyt tuhannesta yhden miehen, mutta koko siitä luvusta en ole löytänyt yhtäkään naista.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686426,58,21,7,30,'Katso, tämän ainoastaan olen löytänyt: että Jumala on tehnyt ihmiset suoriksi, mutta itse he etsivät monia mutkia.'),
(1686427,58,21,8,1,'Kuka on viisaan vertainen, ja kuka taitaa selittää asian? Ihmisen viisaus kirkastaa hänen kasvonsa, ja hänen kasvojensa kovuus muuttuu.'),
(1686428,58,21,8,2,'Minä sanon: Ota vaari kuninkaan käskystä, varsinkin Jumalan kautta vannotun valan tähden.'),
(1686429,58,21,8,3,'Älä ole kerkeä luopumaan hänestä, äläkä asetu pahan asian puolelle, sillä hän tekee, mitä vain tahtoo.'),
(1686430,58,21,8,4,'Sillä kuninkaan sana on voimallinen, ja kuka voi sanoa hänelle: Mitäs teet?'),
(1686431,58,21,8,5,'Joka käskyn pitää, ei tiedä pahasta asiasta; ja viisaan sydän tietää ajan ja tuomion.'),
(1686432,58,21,8,6,'Sillä itsekullakin asialla on aikansa ja tuomionsa; ihmistä näet painaa raskaasti hänen pahuutensa.'),
(1686433,58,21,8,7,'Hän ei tiedä, mitä tuleva on; sillä kuka ilmaisee hänelle, miten se on tuleva?'),
(1686434,58,21,8,8,'Ei ole ihminen tuulen valtias, niin että hän voisi sulkea tuulen, ei hallitse kukaan kuoleman päivää, ei ole pääsyä sodasta, eikä jumalattomuus pelasta harjoittajaansa.'),
(1686435,58,21,8,9,'Kaiken tämän minä tulin näkemään, kun käänsin sydämeni tarkkaamaan kaikkea, mitä auringon alla tapahtuu aikana, jolloin ihminen vallitsee toista ihmistä hänen onnettomuudekseen.'),
(1686436,58,21,8,10,'Sitten minä näin, kuinka jumalattomat haudattiin ja menivät lepoon, mutta ne, jotka olivat oikein tehneet, saivat lähteä pois pyhästä paikasta ja joutuivat unhotuksiin kaupungissa. Sekin on turhuus.'),
(1686437,58,21,8,11,'Milloin pahan teon tuomio ei tule pian, saavat ihmislapset rohkeutta tehdä pahaa,'),
(1686438,58,21,8,12,'koskapa syntinen saa tehdä pahaa sata kertaa ja elää kauan; tosin minä tiedän, että Jumalaa pelkääväisille käy hyvin, sentähden että he häntä pelkäävät,'),
(1686439,58,21,8,13,'mutta että jumalattomalle ei käy hyvin eikä hän saa jatkaa päiviään pitkiksi kuin varjo, sentähden ettei hän pelkää Jumalaa.'),
(1686440,58,21,8,14,'On turhuutta sekin, mitä tapahtuu maan päällä, kun vanhurskaita on, joiden käy, niinkuin olisivat jumalattomain tekoja tehneet, ja jumalattomia on, joiden käy, niinkuin olisivat vanhurskaitten tekoja tehneet. Minä sanoin: sekin on turhuutta.'),
(1686441,58,21,8,15,'Ja minä ylistin iloa; koska ei ihmisellä auringon alla ole mitään parempaa kuin syödä ja juoda ja olla iloinen; se seuraa häntä hänen vaivannäkönsä ohessa hänen elämänsä päivinä, jotka Jumala on antanut hänelle auringon alla.'),
(1686442,58,21,8,16,'Kun minä käänsin sydämeni oppimaan viisautta ja katsomaan työtä, jota tehdään maan päällä saamatta untakaan silmiin päivällä tai yöllä,'),
(1686443,58,21,8,17,'niin minä tulin näkemään kaikista Jumalan teoista, että ihminen ei voi käsittää sitä, mitä tapahtuu auringon alla; sillä ihminen saa kyllä nähdä vaivaa etsiessään, mutta ei hän käsitä. Ja jos viisas luuleekin tietävänsä, ei hän kuitenkaan voi käsittää.'),
(1686444,58,21,9,1,'Niin minä painoin mieleeni kaiken tämän ja pyrin saamaan kaikkea tätä selville, kuinka näet vanhurskaat ja viisaat ja heidän tekonsa ovat Jumalan kädessä. Ei rakkauskaan eikä viha ole ihmisen tiedettävissä; kaikkea voi hänellä olla edessä.'),
(1686445,58,21,9,2,'Kaikkea voi tapahtua kaikille. Sama kohtalo on vanhurskaalla ja jumalattomalla, hyvällä, puhtaalla ja saastaisella, uhraajalla ja uhraamattomalla; hyvän käy niinkuin syntisenkin, vannojan niinkuin valaa pelkäävänkin.'),
(1686446,58,21,9,3,'Se on onnettomuus kaikessa, mitä tapahtuu auringon alla, että kaikilla on sama kohtalo, ja myös se, että ihmislasten sydän on täynnä pahaa ja että mielettömyys on heillä sydämessä heidän elinaikansa; ja senjälkeen - vainajien tykö!'),
(1686447,58,21,9,4,'Onhan sillä, jonka vielä on suotu olla kaikkien eläväin seurassa, toivoa. Sillä elävä koira on parempi kuin kuollut leijona.'),
(1686448,58,21,9,5,'Sillä elävät tietävät, että heidän on kuoltava, mutta kuolleet eivät tiedä mitään, eikä heillä ole paikkaa, vaan heidän muistonsa on unhotettu.'),
(1686449,58,21,9,6,'Myös heidän rakkautensa, vihansa ja intohimonsa on jo aikoja mennyt, eikä heillä ole milloinkaan enää osaa missään, mitä tapahtuu auringon alla.'),
(1686450,58,21,9,7,'Tule siis, syö leipäsi ilolla ja juo viinisi hyvillä mielin, sillä jo aikaa on Jumala hyväksynyt nuo tekosi.'),
(1686451,58,21,9,8,'Vaatteesi olkoot aina valkeat, ja öljy älköön puuttuko päästäsi.'),
(1686452,58,21,9,9,'Nauti elämää vaimon kanssa, jota rakastat, kaikkina turhan elämäsi päivinä, jotka Jumala on sinulle antanut auringon alla - kaikkina turhina päivinäsi, sillä se on sinun osasi elämässä ja vaivannäössäsi, jolla vaivaat itseäsi auringon alla.'),
(1686453,58,21,9,10,'Tee kaikki, mitä voimallasi tehdyksi saat, sillä ei ole tekoa, ei ajatusta, ei tietoa eikä viisautta tuonelassa, jonne olet menevä.'),
(1686454,58,21,9,11,'Taas minä tulin näkemään auringon alla, että ei ole juoksu nopsain vallassa, ei sota urhojen, ei leipä viisaitten, ei rikkaus ymmärtäväisten eikä suosio taitavain vallassa, vaan aika ja kohtalo kohtaa kaikkia.'),
(1686455,58,21,9,12,'Sillä ei ihminen tiedä aikaansa, niinkuin eivät kalatkaan, jotka tarttuvat pahaan verkkoon, eivätkä linnut, jotka käyvät kiinni paulaan; niinkuin ne, niin pyydystetään ihmislapsetkin pahana aikana, joka yllättää heidät äkisti.'),
(1686456,58,21,9,13,'Tämänkin minä tulin näkemään viisaudeksi auringon alla, ja se oli minusta suuri:'),
(1686457,58,21,9,14,'Oli pieni kaupunki ja siinä miehiä vähän. Ja suuri kuningas tuli sitä vastaan, saarsi sen ja rakensi sitä vastaan suuria piiritystorneja.'),
(1686458,58,21,9,15,'Mutta siellä oli köyhä, viisas mies, ja hän pelasti kaupungin viisaudellaan. Mutta ei kukaan ihminen muistanut sitä köyhää miestä.'),
(1686459,58,21,9,16,'Niin minä sanoin: Viisaus on parempi kuin voima, mutta köyhän viisautta halveksitaan, eikä hänen sanojansa kuulla.'),
(1686460,58,21,9,17,'Viisaitten sanat, hiljaisuudessa kuullut, ovat paremmat kuin tyhmäin päämiehen huuto.'),
(1686461,58,21,9,18,'Viisaus on parempi kuin sota-aseet, mutta yksi ainoa syntinen saattaa hukkaan paljon hyvää.'),
(1686462,58,21,10,1,'Myrkkykärpäset saavat haisemaan ja käymään voiteentekijän voiteen. Pieni tyhmyys painaa enemmän kuin viisaus ja kunnia.'),
(1686463,58,21,10,2,'Viisaan sydän vetää oikealle, tyhmän vasemmalle.'),
(1686464,58,21,10,3,'Tietä käydessäkin puuttuu tyhmältä mieltä: jokaiselle hän ilmaisee olevansa tyhmä.'),
(1686465,58,21,10,4,'Jos hallitsijassa nousee viha sinua kohtaan, niin älä jätä paikkaasi; sillä sävyisyys pidättää suurista synneistä.'),
(1686466,58,21,10,5,'On onnettomuus se, minkä olen nähnyt auringon alla, vallanpitäjästä lähtenyt erehdys:'),
(1686467,58,21,10,6,'tyhmyys asetetaan arvon korkeuksiin, ja rikkaat saavat istua alhaalla.'),
(1686468,58,21,10,7,'Minä olen nähnyt palvelijat hevosten selässä ja ruhtinaat kävelemässä kuin palvelijat maassa.'),
(1686469,58,21,10,8,'Joka kuopan kaivaa, se siihen putoaa; joka muuria purkaa, sitä puree käärme.'),
(1686470,58,21,10,9,'Joka kiviä louhii, se niihin loukkaantuu; joka puita halkoo, se joutuu siinä vaaraan.'),
(1686471,58,21,10,10,'Jos rauta on tylsynyt eikä teränsuuta tahkota, täytyy ponnistaa voimia; mutta hyödyllinen kuntoonpano on viisautta.'),
(1686472,58,21,10,11,'Jos käärme puree silloin, kun sitä ei ole lumottu, ei lumoojalla ole hyötyä taidostaan.'),
(1686473,58,21,10,12,'Sanat viisaan suusta saavat suosiota, mutta tyhmän nielevät hänen omat huulensa.'),
(1686474,58,21,10,13,'Hänen suunsa sanain alku on tyhmyyttä, ja hänen puheensa loppu pahaa mielettömyyttä.'),
(1686475,58,21,10,14,'Tyhmä puhuu paljon; mutta ihminen ei tiedä, mitä tuleva on. Ja kuka ilmaisee hänelle, mitä hänen jälkeensä tulee?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686476,58,21,10,15,'Oma vaivannäkö väsyttää tyhmän, joka ei osaa kaupunkiinkaan kulkea.'),
(1686477,58,21,10,16,'Voi sinua, maa, jolla on kuninkaana poikanen ja jonka ruhtinaat jo aamulla aterioita pitävät!'),
(1686478,58,21,10,17,'Onnellinen sinä, maa, jolla on jalosukuinen kuningas ja jonka ruhtinaat pitävät aterioita oikeaan aikaan, miehekkäästi eikä juopotellen!'),
(1686479,58,21,10,18,'Missä laiskuus on, siinä vuoliaiset vaipuvat; ja missä kädet velttoina riippuvat, tippuu huoneeseen vettä.'),
(1686480,58,21,10,19,'Hauskuudeksi ateria laitetaan, ja viini ilahuttaa elämän; mutta raha kaiken hankkii.'),
(1686481,58,21,10,20,'Älä ajatuksissasikaan kiroile kuningasta, äläkä makuukammiossasikaan kiroile rikasta, sillä taivaan linnut kuljettavat sinun äänesi ja siivelliset ilmaisevat sinun sanasi.'),
(1686482,58,21,11,1,'Lähetä leipäsi vetten yli, sillä ajan pitkään sinä saat sen jälleen.'),
(1686483,58,21,11,2,'Anna osa seitsemälle, kahdeksallekin, sillä et tiedä, mitä onnettomuutta voi tulla maahan.'),
(1686484,58,21,11,3,'Jos pilvet tulevat täyteen sadetta, valavat ne sen maahan. Ja jos puu kaatuu etelää kohti tai pohjoista, niin mihin paikkaan puu kaatui, siihen se jää.'),
(1686485,58,21,11,4,'Joka tuulta tarkkaa, ei kylvä; ja joka pilviä pälyy, ei leikkaa.'),
(1686486,58,21,11,5,'Niinkuin et tiedä tuulen teitä etkä luitten rakentumista raskaana olevan kohdussa, niin et myöskään tiedä Jumalan tekoja, hänen, joka kaikki tekee.'),
(1686487,58,21,11,6,'Kylvä siemenesi aamulla äläkä hellitä kättäsi ehtoollakaan; sillä et tiedä, tuoko onnistuu vai tämä vai onko kumpikin yhtä hyvä.'),
(1686488,58,21,11,7,'Suloinen on valo, ja silmille tekee hyvää nähdä aurinkoa.'),
(1686489,58,21,11,8,'Niin, jos ihminen elää vuosia paljonkin, iloitkoon hän niistä kaikista, mutta muistakoon pimeitä päiviä, sillä niitä tulee paljon. Kaikki, mikä tulee, on turhuutta.'),
(1686490,58,21,11,9,'Iloitse, nuorukainen, nuoruudessasi, ja sydämesi ilahuttakoon sinua nuoruusikäsi päivinä. Vaella sydämesi teitä ja silmiesi halun mukaan; mutta tiedä: Jumala tuo sinut tuomiolle kaikesta tästä.'),
(1686491,58,21,11,10,'Karkoita suru sydämestäsi ja torju kärsimys ruumiistasi, sillä nuoruus ja aamurusko ovat turhuutta.'),
(1686492,58,21,12,1,'Ja muista Luojaasi nuoruudessasi, ennenkuin pahat päivät tulevat ja joutuvat ne vuodet, joista olet sanova:'),
(1686493,58,21,12,2,'"Nämä eivät minua miellytä"; ennenkuin pimenee aurinko, päivänvalo, kuu ja tähdet, ja pilvet palajavat sateen jälkeenkin -'),
(1686494,58,21,12,3,'jolloin huoneen vartijat vapisevat ja voiman miehet käyvät koukkuisiksi ja jauhajanaiset ovat joutilaina, kun ovat menneet vähiin, ja akkunoista-kurkistelijat jäävät pimeään,'),
(1686495,58,21,12,4,'ja kadulle vievät ovet sulkeutuvat ja myllyn ääni heikkenee ja noustaan linnun lauluun ja kaikki laulun tyttäret hiljentyvät;'),
(1686496,58,21,12,5,'myös peljätään mäkiä, ja tiellä on kauhuja, ja mantelipuu kukkii, ja heinäsirkka kulkee kankeasti, ja kapriisinnuppu on tehoton; sillä ihminen menee iankaikkiseen majaansa, ja valittajat kiertelevät kaduilla -'),
(1686497,58,21,12,6,'ennenkuin hopealanka katkeaa ja kultamalja särkyy ja vesiastia rikkoutuu lähteellä ja ammennuspyörä särkyneenä putoaa kaivoon.'),
(1686498,58,21,12,7,'Ja tomu palajaa maahan, niinkuin on ollutkin, ja henki palajaa Jumalan tykö, joka sen on antanutkin.'),
(1686499,58,21,12,8,'Turhuuksien turhuus, sanoi saarnaaja; kaikki on turhuutta!'),
(1686500,58,21,12,9,'Sen lisäksi, että saarnaaja oli viisas, hän myös opetti kansalle tietoa, punnitsi, harkitsi ja sommitteli sananlaskuja paljon.'),
(1686501,58,21,12,10,'Saarnaaja koki löytää kelvollisia sanoja, oikeassa mielessä kirjoitettuja, totuuden sanoja.'),
(1686502,58,21,12,11,'Viisaitten sanat ovat kuin tutkaimet ja kootut lauseet kuin isketyt naulat; ne ovat saman Paimenen antamia.'),
(1686503,58,21,12,12,'Ja vielä näiden lisäksi: Poikani, ota varoituksesta vaari; paljolla kirjaintekemisellä ei ole loppua, ja paljo tutkistelu väsyttää ruumiin.'),
(1686504,58,21,12,13,'Loppusana kaikesta, mitä on kuultu, on tämä: Pelkää Jumalaa ja pidä hänen käskynsä, sillä niin tulee jokaisen ihmisen tehdä.'),
(1686505,58,22,1,1,'Salomon korkea veisu.'),
(1686506,58,22,1,2,'Hän suudelkoon minua suunsa suudelmilla. Sillä sinun rakkautesi on suloisempi kuin viini.'),
(1686507,58,22,1,3,'Suloinen on voiteittesi tuoksu, vuodatettu öljy on sinun nimesi; sentähden sinua nuoret naiset rakastavat.'),
(1686508,58,22,1,4,'Vedä minut mukaasi, rientäkäämme! Kuningas on tuonut minut kammioihinsa. Me riemuitsemme ja iloitsemme sinusta, me ylistämme sinun rakkauttasi enemmän kuin viiniä; syystä he sinua rakastavat.'),
(1686509,58,22,1,5,'"Minä olen musta, mutta ihana, te Jerusalemin tyttäret, kuin Keedarin teltat, kuin Salomon seinäverhot.'),
(1686510,58,22,1,6,'Älkää katsoko sitä, että minä olen musta, päivän paahtama. Äitini pojat vihastuivat minuun, panivat minut viinitarhain vartijaksi - omaa viinitarhaani en vartioinut."'),
(1686511,58,22,1,7,'"Sano minulle sinä, jota sieluni rakastaa, missä laumaasi paimennat, missä annat sen keskipäivällä levätä. Miksi minä hunnutettuna joutuisin sinun toveriesi laumain luo!"'),
(1686512,58,22,1,8,'"Jos et sitä tiedä, sinä naisista kaunein, käy lammasten jälkiä ja kaitse vohliasi paimenten telttapaikoilla."'),
(1686513,58,22,1,9,'"Tammaani, joka on faraon vaunujen edessä, sinut, armaani, vertaan.'),
(1686514,58,22,1,10,'Ihanat ovat sinun poskesi käätyinensä, kaulasi helminauhoinensa.'),
(1686515,58,22,1,11,'Me teemme sinulle kultakäädyt ynnä hopeasta niihin nastat."'),
(1686516,58,22,1,12,'"Kuninkaan istuessa pöydässään tuoksui minun nardukseni kaiken aikaa.'),
(1686517,58,22,1,13,'Rakkaani on minulle mirhakimppu, joka rintojeni välissä lepää.'),
(1686518,58,22,1,14,'Rakkaani on kooferkukka-terttu Een-Gedin viinitarhoista."'),
(1686519,58,22,1,15,'"Katso, kaunis sinä olet, armaani; katso, kaunis olet, silmäsi ovat kyyhkyläiset."'),
(1686520,58,22,1,16,'"Katso, kaunis sinä olet, rakkaani; kuinka suloinen, kuinka vihanta on vuoteemme!'),
(1686521,58,22,1,17,'Huoneittemme seininä ovat setripuut, kattonamme kypressit."'),
(1686522,58,22,2,1,'"Minä olen Saaronin kukkanen, olen laaksojen lilja."'),
(1686523,58,22,2,2,'"Niinkuin lilja orjantappurain keskellä, niin on minun armaani neitosten keskellä."'),
(1686524,58,22,2,3,'"Niinkuin omenapuu metsäpuitten keskellä, niin on minun rakkaani nuorukaisten keskellä; minä halajan istua sen varjossa, ja sen hedelmä on minun suussani makea.'),
(1686525,58,22,2,4,'Hän on vienyt minut viinimajaan; rakkaus on hänen lippunsa minun ylläni.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686526,58,22,2,5,'Vahvistakaa minua rypälekakuilla, virvoittakaa minua omenilla, sillä minä olen rakkaudesta sairas."'),
(1686527,58,22,2,6,'Hänen vasen kätensä on minun pääni alla, ja hänen oikea kätensä halaa minua.'),
(1686528,58,22,2,7,'Minä vannotan teitä, te Jerusalemin tyttäret, gasellien tai kedon peurojen kautta: älkää herätelkö, älkää häiritkö rakkautta, ennenkuin se itse haluaa.'),
(1686529,58,22,2,8,'Kuule! Rakkaani tulee! Katso, tuolla hän tulee hyppien vuorilla, kiitäen kukkuloilla.'),
(1686530,58,22,2,9,'Rakkaani on gasellin kaltainen tai nuoren peuran. Katso, tuolla hän seisoo seinämme takana, katsellen ikkunasta sisään, kurkistellen ristikoista.'),
(1686531,58,22,2,10,'Rakkaani lausuu ja sanoo minulle: "Nouse, armaani, sinä kaunoiseni, ja tule.'),
(1686532,58,22,2,11,'Sillä katso, talvi on väistynyt, sateet ovat ohitse, ovat menneet menojaan.'),
(1686533,58,22,2,12,'Kukkaset ovat puhjenneet maahan, laulun aika on tullut, ja metsäkyyhkysen ääni kuuluu maassamme.'),
(1686534,58,22,2,13,'Viikunapuu tekee keväthedelmää, viiniköynnökset ovat kukassa ja tuoksuavat. Nouse, armaani, sinä kaunoiseni, ja tule.'),
(1686535,58,22,2,14,'Kyyhkyseni, joka piilet kallionkoloissa, vuorenpengermillä anna minun nähdä kasvosi, anna minun kuulla äänesi, sillä suloinen on sinun äänesi ja ihanat ovat sinun kasvosi."'),
(1686536,58,22,2,15,'Ottakaamme ketut kiinni, pienet ketut, jotka viinitarhoja turmelevat, sillä viinitarhamme ovat kukassa.'),
(1686537,58,22,2,16,'Rakkaani on minun, ja minä hänen - hänen, joka paimentaa liljojen keskellä.'),
(1686538,58,22,2,17,'Kunnes päivä viilenee ja varjot pakenevat, kiertele, rakkaani, kuin gaselli, kuin nuori peura tuoksuisilla vuorilla.'),
(1686539,58,22,3,1,'Yöllä minä vuoteellani etsin häntä, jota minun sieluni rakastaa, minä etsin, mutta en löytänyt häntä.'),
(1686540,58,22,3,2,'"Minä nousen ja kiertelen kaupunkia, katuja ja toreja, etsin häntä, jota minun sieluni rakastaa." Minä etsin, mutta en löytänyt häntä.'),
(1686541,58,22,3,3,'Kohtasivat minut vartijat, jotka kaupunkia kiertävät. "Oletteko nähneet häntä, jota minun sieluni rakastaa?"'),
(1686542,58,22,3,4,'Tuskin olin kulkenut heidän ohitsensa, kun löysin hänet, jota minun sieluni rakastaa; minä tartuin häneen enkä hellittänyt hänestä, ennenkuin olin saattanut hänet äitini taloon, kantajani kammioon.'),
(1686543,58,22,3,5,'Minä vannotan teitä, te Jerusalemin tyttäret, gasellien tai kedon peurojen kautta: älkää herätelkö, älkää häiritkö rakkautta, ennenkuin se itse haluaa.'),
(1686544,58,22,3,6,'Mikä tuolla tulee erämaasta kuin savupatsaat, tuoksuten mirhalta ja suitsukkeelta, kaikkinaisilta kauppiaan hajujauheilta?'),
(1686545,58,22,3,7,'Katso, siinä on Salomon kantotuoli ja sen ympärillä kuusikymmentä urhoa, Israelin urhoja,'),
(1686546,58,22,3,8,'kaikki miekkamiehiä, sotaan harjoitettuja; jokaisella on miekka kupeellansa öitten kauhuja vastaan.'),
(1686547,58,22,3,9,'Kuningas Salomo teetti itsellensä kantotuolin Libanonin puista.'),
(1686548,58,22,3,10,'Sen patsaat hän teetti hopeasta, sen selustan kullasta, sen istuimen purppurasta; sisältä sen koristeli Jerusalemin tyttärien rakkaus.'),
(1686549,58,22,3,11,'Tulkaa ulos, Siionin tyttäret, ja katsokaa kuningas Salomoa, katsokaa kruunua, jolla hänen äitinsä hänet kruunasi hänen hääpäivänänsä, hänen sydämensä ilonpäivänä.'),
(1686550,58,22,4,1,'"Katso, kaunis sinä olet, armaani; katso, kaunis sinä olet. Kyyhkyläiset ovat sinun silmäsi huntusi takana; sinun hiuksesi ovat kuin vuohilauma, joka laskeutuu Gileadin vuorilta.'),
(1686551,58,22,4,2,'Sinun hampaasi ovat kuin lauma kerittyjä lampaita, pesosta nousseita, kaikilla kaksoiset, ei yhtäkään karitsatonta.'),
(1686552,58,22,4,3,'Kuin punainen nauha ovat sinun huulesi, ja suusi on suloinen; kuin granaattiomena, kypsyyttään halkeileva, on sinun ohimosi huntusi takana.'),
(1686553,58,22,4,4,'Sinun kaulasi on niinkuin Daavidin torni, linnaksi rakennettu; tuhat kilpeä riippuu siinä, urhojen varustuksia kaikkia.'),
(1686554,58,22,4,5,'Sinun rintasi ovat kuin kaksi nuorta peuraa, kuin gasellin kaksoiset, jotka käyvät laitumella liljain keskellä.'),
(1686555,58,22,4,6,'Siksi kunnes päivä viilenee ja varjot pakenevat, minä käyn mirhavuorelle ja suitsukekukkulalle.'),
(1686556,58,22,4,7,'Kaikin olet kaunis, armaani, ei ole sinussa ainoatakaan virheä."'),
(1686557,58,22,4,8,'"Tule kanssani Libanonilta, sinä morsiameni, tule kanssani Libanonilta. Lähde pois Amanan huipulta, Senirin ja Hermonin huipuilta, leijonain leposijoilta ja pantterien vuorilta."'),
(1686558,58,22,4,9,'"Olet lumonnut minut, siskoni, morsiameni, lumonnut minut yhdellä ainoalla silmäykselläsi, yhdellä ainoalla kaulakoristeesi käädyllä.'),
(1686559,58,22,4,10,'Kuinka ihana onkaan sinun rakkautesi, siskoni, morsiameni! Kuinka paljon suloisempi viiniä on sinun rakkautesi, suloisempi kaikkia balsameja sinun voiteittesi tuoksu!'),
(1686560,58,22,4,11,'Sinun huulesi tiukkuvat hunajaa, morsiameni; mesi ja maito on sinun kielesi alla, ja sinun vaatteittesi tuoksu on kuin Libanonin tuoksu."'),
(1686561,58,22,4,12,'"Suljettu yrttitarha on siskoni, morsiameni, suljettu kaivo, lukittu lähde.'),
(1686562,58,22,4,13,'Sinä versot kuin paratiisi, jossa on granaattiomenia ynnä kalliita hedelmiä, koofer-kukkia ja narduksia,'),
(1686563,58,22,4,14,'nardusta ja sahramia, kalmoruokoa ja kanelia ynnä kaikkinaisia suitsukepuita, mirhaa ja aloeta ynnä kaikkinaisia parhaita balsamikasveja.'),
(1686564,58,22,4,15,'Sinä olet yrttitarhojen lähde, elävien vetten kaivo, Libanonilta virtaavaisten."'),
(1686565,58,22,4,16,'"Heräjä, pohjatuuli, tule, etelätuuli; puhalla yrttitarhaani, että sen balsamituoksut tulvahtaisivat. Tulkoon puutarhaansa rakkaani ja syököön sen kalliita hedelmiä."'),
(1686566,58,22,5,1,'"Minä tulen yrttitarhaani, siskoni, morsiameni; minä poimin mirhani ja balsamini, minä syön mesileipäni ja hunajani, juon viinini ja maitoni." Syökää, ystävät, juokaa ja juopukaa rakkaudesta.'),
(1686567,58,22,5,2,'Minä nukuin, mutta minun sydämeni valvoi. Kuule, rakkaani kolkuttaa: "Avaa minulle, siskoseni, armaani, kyyhkyseni, puhtoiseni. Sillä pääni on kastetta täynnä, kiharani yön pisaroita."'),
(1686568,58,22,5,3,'"Olen ihokkaani riisunut; pukisinko sen päälleni enää? Olen jalkani pessyt; tahraisinko ne taas?"'),
(1686569,58,22,5,4,'Rakkaani pisti kätensä ovenreiästä sisään. Silloin minun sydämeni liikkui häntä kohden;'),
(1686570,58,22,5,5,'minä nousin avaamaan rakkaalleni, ja minun käteni tiukkuivat mirhaa, sormeni sulaa mirhaa salvan kädensijoihin.'),
(1686571,58,22,5,6,'Minä avasin rakkaalleni, mutta rakkaani oli kadonnut, mennyt menojaan. Hänen puhuessaan oli sieluni vallannut hämmennys. Minä etsin häntä, mutta en häntä löytänyt; minä huusin häntä, mutta ei hän minulle vastannut.'),
(1686572,58,22,5,7,'Kohtasivat minut vartijat, jotka kaupunkia kiertävät, he löivät minua ja haavoittivat minut; päällysharson riistivät yltäni muurien vartijat.'),
(1686573,58,22,5,8,'"Minä vannotan teitä, te Jerusalemin tyttäret: jos löydätte rakkaani, mitä hänelle sanotte? Sanokaa, että minä olen rakkaudesta sairas."'),
(1686574,58,22,5,9,'"Mitä on sinun rakkaasi muita parempi, sinä naisista kaunein? Mitä on sinun rakkaasi muita parempi, ettäs meitä näin vannotat?"'),
(1686575,58,22,5,10,'"Minun rakkaani on valkoinen ja punainen, kymmentä tuhatta jalompi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686576,58,22,5,11,'Hänen päänsä on kultaa, puhtainta kultaa, hänen kiharansa kuin palmunlehvät, mustat kuin kaarne.'),
(1686577,58,22,5,12,'Hänen silmänsä ovat kuin kyyhkyset vesipurojen partaalla, jotka ovat maidossa kylpeneet ja istuvat runsauden ääressä.'),
(1686578,58,22,5,13,'Hänen poskensa ovat kuin balsamilava, kuin höystesäiliöt; hänen huulensa ovat liljat, ne tiukkuvat sulaa mirhaa.'),
(1686579,58,22,5,14,'Hänen käsivartensa ovat kultatangot, krysoliittejä täynnä. Hänen lantionsa on norsunluinen taideteos, safiireilla peitetty.'),
(1686580,58,22,5,15,'Hänen jalkansa ovat marmoripatsaat aitokultaisten jalustain nojassa. Hän on näöltänsä kuin Libanon, uhkea kuin setripuut.'),
(1686581,58,22,5,16,'Hänen suunsa on sula makeus, hän on pelkkää suloisuutta. Sellainen on minun rakkaani, sellainen on ystäväni, te Jerusalemin tyttäret."'),
(1686582,58,22,6,1,'"Minne on mennyt rakkaasi, sinä naisista kaunein? Kunne on kääntynyt rakkaasi? Etsikäämme häntä yhdessä."'),
(1686583,58,22,6,2,'"Rakkaani on mennyt yrttitarhaansa, balsamilavojen luo, paimentamaan yrttitarhoissa ja liljoja poimimaan.'),
(1686584,58,22,6,3,'Minä olen rakkaani oma, ja rakkaani on minun - hän, joka paimentaa liljojen keskellä."'),
(1686585,58,22,6,4,'"Kaunis kuin Tirsa olet sinä, armaani, suloinen kuin Jerusalem, peljättävä kuin sotajoukot.'),
(1686586,58,22,6,5,'Käännä pois silmäsi minusta, sillä ne kiehtovat minut. Sinun hiuksesi ovat kuin vuohilauma, joka laskeutuu Gileadilta.'),
(1686587,58,22,6,6,'Sinun hampaasi ovat kuin lauma uuhia, pesosta nousseita, kaikilla kaksoiset, ei yhtäkään karitsatonta.'),
(1686588,58,22,6,7,'Kuin granaattiomena, kypsyyttään halkeileva, on sinun ohimosi huntusi takana.'),
(1686589,58,22,6,8,'Kuusikymmentä on kuningatarta ja kahdeksankymmentä sivuvaimoa ja nuoria naisia ilman määrää:'),
(1686590,58,22,6,9,'yksi ainoa on minun kyyhkyseni, puhtoiseni, äitinsä ainokainen, synnyttäjänsä valio. Neitoset hänet nähdessään kiittävät hänen onneansa, kuningattaret ja sivuvaimot ylistävät häntä."'),
(1686591,58,22,6,10,'"Kuka on neito, joka ylenee kuin aamunkoi, kauniina kuin kuu, kirkkaana kuin päivänpaiste, peljättävänä kuin sotajoukot?"'),
(1686592,58,22,6,11,'"Pähkinätarhaan minä menin katselemaan laakson vihreyttä, katsomaan, joko viiniköynnös versoo, joko kukkivat granaattipuut.'),
(1686593,58,22,6,12,'Aavistamattani asetti sieluni minut jalon kansani vaunuihin."'),
(1686594,58,22,7,1,'"Palaja, palaja, suulemitar! Palaja, palaja, ihaillaksemme sinua!" "Mitä ihailette suulemittaressa, katselette hänen asekarkelossaan?" (7:1)(7:2) "Kuinka kauniisti astelet kengissäsi, sinä ruhtinaan tytär! Sinun lanteesi kaartuvat kuin kaulakorut, taiturin kätten tekemät.'),
(1686595,58,22,7,2,'(7:3) Sinun povesi on ympyriäinen malja, josta sekoviini älköön puuttuko; sinun uumasi on nisukeko, liljojen ympäröimä.'),
(1686596,58,22,7,3,'Sinun rintasi ovat kuin kaksi nuorta peuraa, kuin gasellin kaksoiset.'),
(1686597,58,22,7,4,'Sinun kaulasi on kuin norsunluinen torni. Sinun silmäsi kuin Hesbonin lammikot Bat-Rabbimin portin luona; sinun nenäsi on kuin Libanonin torni, joka katsoo Damaskoon päin.'),
(1686598,58,22,7,5,'Sinun pääsi kohoaa kuin Karmel, sinun pääsi palmikot ovat kuin purppura; niihin pauloihin on kuningas kiedottu."'),
(1686599,58,22,7,6,'"Kuinka kaunis olet, kuinka suloinen, sinä rakkaus, riemuinesi! -'),
(1686600,58,22,7,7,'Sinun vartesi on kuin palmupuu, ja sinun rintasi niinkuin rypäleet.'),
(1686601,58,22,7,8,'Minä ajattelin: nousen palmupuuhun, tartun sen oksiin; olkoot silloin rintasi niinkuin viinirypäleet ja henkesi tuoksu kuin omenain tuoksu.'),
(1686602,58,22,7,9,'Ja olkoon suusi kuin jalo viini." "Viini, joka helposti valahtaa rakkaaseeni ja kostuttaa nukkuvien huulet!'),
(1686603,58,22,7,10,'Minä olen rakkaani oma, ja minuun on hänen halunsa."'),
(1686604,58,22,7,11,'"Tule, rakkaani, lähtekäämme maalle, kyliin yöpykäämme.'),
(1686605,58,22,7,12,'Käykäämme varhain viinitarhoihin katsomaan, joko viiniköynnös versoo ja ummut aukeavat, joko kukkivat granaattipuut. Siellä annan sinulle rakkauteni.'),
(1686606,58,22,7,13,'(/:14) Lemmenmarjat tuoksuavat, ja oviemme edessä kasvavat kaikkinaiset kalliit hedelmät, uudet ja vanhat: sinulle, rakkaani, olen ne säästänyt."'),
(1686607,58,22,8,1,'"Olisitpa kuin oma veljeni, äitini rintoja imenyt! Tapaisin sinut ulkona, sinua suutelisin, eikä minua kukaan halveksuisi.'),
(1686608,58,22,8,2,'Minä johdattaisin sinut, veisin äitini taloon, ja hän neuvoisi minua. Minä antaisin mausteviiniä juodaksesi, granaattiomenani mehua."'),
(1686609,58,22,8,3,'Hänen vasen kätensä on minun pääni alla, ja hänen oikea kätensä halaa minua.'),
(1686610,58,22,8,4,'Minä vannotan teitä, te Jerusalemin tyttäret: älkää herätelkö, älkää häiritkö rakkautta, ennenkuin se itse haluaa.'),
(1686611,58,22,8,5,'Kuka tuolla tulee erämaasta rakkaaseensa nojaten? "Omenapuun alla sinut herätin. Siellä sai sinut äitisi kerran, siellä sai sinut emosi.'),
(1686612,58,22,8,6,'Pane minut sinetiksi sydämellesi, sinetiksi käsivarrellesi. Sillä rakkaus on väkevä kuin kuolema, tuima kuin tuonela on sen kiivaus, sen hehku on tulen hehku, on Herran liekki.'),
(1686613,58,22,8,7,'Eivät suuret vedet voi rakkautta sammuttaa, eivät virrat sitä tulvaansa upottaa. Jos joku tarjoaisi kaikki talonsa tavarat rakkauden hinnaksi, häntä vain halveksuttaisiin."'),
(1686614,58,22,8,8,'"Meillä on pieni sisko, jolla ei vielä ole rintoja. Mitä teemme siskollemme sinä päivänä, jona häntä kysytään?'),
(1686615,58,22,8,9,'Jos hän on muuri, rakennamme sille hopeasta harjan; jos hän on ovi, sen setrilaudalla suljemme."'),
(1686616,58,22,8,10,'"Minä olen muuri, ja rintani ovat kuin tornit; vaan nyt olen hänen silmissään niinkuin antautuvainen."'),
(1686617,58,22,8,11,'"Salomolla on viinitarha Baal-Haamonissa; hän on jättänyt viinitarhan vartijoiden huostaan; sen hedelmistä saisi tuhat hopeasekeliä.'),
(1686618,58,22,8,12,'Minun viinitarhani on minun omassa hallussani. Sinulle, Salomo, tulkoot ne tuhat, ja sen hedelmän vartijoille kaksisataa."'),
(1686619,58,22,8,13,'"Sinä yrttitarhain asujatar, toverit kuuntelevat ääntäsi; anna minun sitä kuulla."'),
(1686620,58,23,1,1,'Jesajan, Aamoksen pojan, näky, jonka hän näki Juudasta ja Jerusalemista Ussian, Jootamin, Aahaan ja Hiskian, Juudan kuningasten, päivinä.'),
(1686621,58,23,1,2,'Kuulkaa, taivaat, ota korviisi, maa, sillä Herra puhuu: Minä kasvatin lapsia, sain heidät suuriksi, mutta he luopuivat minusta.'),
(1686622,58,23,1,3,'Härkä tuntee omistajansa ja aasi isäntänsä seimen; mutta Israel ei tunne, minun kansani ei ymmärrä.'),
(1686623,58,23,1,4,'Voi syntistä sukua, raskaasti rikkonutta kansaa, pahantekijäin siementä, kelvottomia lapsia! He ovat hyljänneet Herran, pitäneet Israelin Pyhää pilkkanansa, he ovat kääntyneet pois.'),
(1686624,58,23,1,5,'Mihin pitäisi teitä vielä lyödä, kun yhä jatkatte luopumustanne? Koko pää on kipeä, koko sydän sairas.'),
(1686625,58,23,1,6,'Kantapäästä kiireeseen asti ei ole tervettä paikkaa, ainoastaan haavoja, mustelmia ja vereksiä lyömiä, joita ei ole puserrettu, ei sidottu eikä öljyllä pehmitetty.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686626,58,23,1,7,'Teidän maanne on autiona, teidän kaupunkinne ovat tulella poltetut; teidän peltojanne syövät muukalaiset silmäinne edessä; ne ovat autioina niinkuin ainakin muukalaisten hävittämät.'),
(1686627,58,23,1,8,'Jäljellä on tytär Siion yksinänsä niinkuin maja viinitarhassa, niinkuin lehvämaja kurkkumaassa, niinkuin saarrettu kaupunki.'),
(1686628,58,23,1,9,'Ellei Herra Sebaot olisi jättänyt meistä jäännöstä, olisi meidän käynyt pian kuin Sodoman, olisimme tulleet Gomorran kaltaisiksi.'),
(1686629,58,23,1,10,'Kuulkaa Herran sana, te Sodoman päämiehet, ota korviisi meidän Jumalamme opetus, sinä Gomorran kansa.'),
(1686630,58,23,1,11,'Mitä ovat minulle teidän paljot teurasuhrinne? sanoo Herra. Minä olen kyllästynyt oinas-polttouhreihin ja juottovasikkain rasvaan. Mullikkain, karitsain ja kauristen vereen minä en mielisty.'),
(1686631,58,23,1,12,'Kun te tulette minun kasvojeni eteen, kuka sitä teiltä vaatii - minun esikartanoitteni tallaamista?'),
(1686632,58,23,1,13,'Älkää enää tuoko minulle turhaa ruokauhria; suitsutus on minulle kauhistus. En kärsi uuttakuuta enkä sapattia, en kokouksen kuuluttamista, en vääryyttä ynnä juhlakokousta.'),
(1686633,58,23,1,14,'Minun sieluni vihaa teidän uusiakuitanne ja juhla-aikojanne; ne ovat käyneet minulle kuormaksi, jota kantamaan olen väsynyt.'),
(1686634,58,23,1,15,'Kun te ojennatte käsiänne, minä peitän silmäni teiltä; vaikka kuinka paljon rukoilisitte, minä en kuule: teidän kätenne ovat verta täynnä.'),
(1686635,58,23,1,16,'Peseytykää, puhdistautukaa; pankaa pois pahat tekonne minun silmäini edestä, lakatkaa pahaa tekemästä.'),
(1686636,58,23,1,17,'Oppikaa tekemään hyvää; harrastakaa oikeutta, ojentakaa väkivaltaista, hankkikaa orvolle oikeus, ajakaa lesken asiaa.'),
(1686637,58,23,1,18,'Niin tulkaa, käykäämme oikeutta keskenämme, sanoo Herra. Vaikka teidän syntinne ovat veriruskeat, tulevat ne lumivalkeiksi; vaikka ne ovat purppuranpunaiset, tulevat ne villanvalkoisiksi.'),
(1686638,58,23,1,19,'Jos suostutte ja olette kuuliaiset, niin te saatte syödä maan hyvyyttä;'),
(1686639,58,23,1,20,'mutta jos vastustatte ja niskoittelette, niin miekka syö teidät. Sillä Herran suu on puhunut.'),
(1686640,58,23,1,21,'Voi, kuinka onkaan portoksi tullut uskollinen kaupunki! Se oli täynnä oikeutta, siellä asui vanhurskaus, mutta nyt murhamiehet.'),
(1686641,58,23,1,22,'Sinun hopeasi on kuonaksi käynyt, jaloviinisi vedellä laimennettu.'),
(1686642,58,23,1,23,'Sinun päämiehesi ovat niskureita ja varkaiden tovereita; kaikki he lahjuksia rakastavat ja palkkoja tavoittelevat; eivät he hanki orvolle oikeutta, lesken asia ei pääse heidän eteensä.'),
(1686643,58,23,1,24,'Sentähden sanoo Herra, Herra Sebaot, Israelin Väkevä: Voi! Minä viihdytän vihani vastustajissani, minä kostan vihollisilleni;'),
(1686644,58,23,1,25,'minä käännän käteni sinua vastaan ja puhdistan sinusta kuonan niinkuin lipeällä ja poistan sinusta kaiken lyijyn.'),
(1686645,58,23,1,26,'Ja minä palautan sinun tuomarisi muinaiselleen ja sinun neuvonantajasi sellaisiksi, kuin alkuaan olivat. Sitten sinua kutsutaan "vanhurskauden linnaksi", "uskolliseksi kaupungiksi".'),
(1686646,58,23,1,27,'Siion lunastetaan oikeudella ja sen kääntyneet vanhurskaudella.'),
(1686647,58,23,1,28,'Mutta luopiot ja syntiset saavat kaikki turmion, ja ne, jotka hylkäävät Herran, hukkuvat.'),
(1686648,58,23,1,29,'Sillä he saavat häpeän niistä tammista, joita te himoitsitte, ja pettymyksen puutarhoista, jotka te valitsitte.'),
(1686649,58,23,1,30,'Sillä teidän käy kuin tammen, jonka lehdet lakastuvat, ja kuin puutarhan, joka on vailla vettä.'),
(1686650,58,23,1,31,'Ja mahtaja tulee rohtimeksi ja hänen tekonsa kipinäksi, ja molemmat palavat yhdessä, eikä ole sammuttajaa.'),
(1686651,58,23,2,1,'Sana, jonka Jesaja, Aamoksen poika, näki Juudasta ja Jerusalemista.'),
(1686652,58,23,2,2,'Aikojen lopussa on Herran temppelin vuori seisova vahvana, ylimmäisenä vuorista, kukkuloista korkeimpana, ja kaikki pakanakansat virtaavat sinne.'),
(1686653,58,23,2,3,'Monet kansat lähtevät liikkeelle sanoen: "Tulkaa, nouskaamme Herran vuorelle, Jaakobin Jumalan temppeliin, että hän opettaisi meille teitänsä ja me vaeltaisimme hänen polkujansa; sillä Siionista lähtee laki, Jerusalemista Herran sana".'),
(1686654,58,23,2,4,'Ja hän tuomitsee pakanakansojen kesken, säätää oikeutta monille kansoille. Niin he takovat miekkansa vantaiksi ja keihäänsä vesureiksi; kansa ei nosta miekkaa kansaa vastaan, eivätkä he enää opettele sotimaan.'),
(1686655,58,23,2,5,'Jaakobin heimo, tulkaa, vaeltakaamme Herran valkeudessa.'),
(1686656,58,23,2,6,'Sillä sinä olet hyljännyt kansasi, Jaakobin heimon, koska he ovat täynnä Idän menoa, täynnä ennustelijoita niinkuin filistealaiset, ja lyövät kättä muukalaisten kanssa.'),
(1686657,58,23,2,7,'Heidän maansa tuli täyteen hopeata ja kultaa, eikä heidän aarteillaan ole määrää; heidän maansa tuli täyteen hevosia, eikä heidän vaunuillaan ole määrää.'),
(1686658,58,23,2,8,'Heidän maansa tuli täyteen epäjumalia, he kumartavat kättensä tekoa, sitä, minkä heidän sormensa ovat tehneet.'),
(1686659,58,23,2,9,'Silloin ihminen masentuu ja mies painuu maahan, mutta älä anna heille anteeksi.'),
(1686660,58,23,2,10,'Mene kallion kätköön, piiloudu maan peittoon Herran kauhua ja hänen valtansa kirkkautta pakoon.'),
(1686661,58,23,2,11,'Ihmisten ylpeät silmät painuvat maahan, miesten korskeus masentuu, ja sinä päivänä Herra yksinänsä on korkea.'),
(1686662,58,23,2,12,'Sillä Herran Sebaotin päivä kohtaa kaikkea ylpeää ja korskeata ja kaikkea ylhäistä, niin että se maahan painuu,'),
(1686663,58,23,2,13,'kaikkia Libanonin setripuita, noita korkeita ja ylhäisiä, kaikkia Baasanin tammia,'),
(1686664,58,23,2,14,'kaikkia korkeita vuoria ja kaikkia ylhäisiä kukkuloita,'),
(1686665,58,23,2,15,'kaikkia korkeita torneja ja kaikkia vahvoja muureja,'),
(1686666,58,23,2,16,'kaikkia Tarsiin-laivoja ja kaikkea kallista ja ihanaa.'),
(1686667,58,23,2,17,'Silloin masentuu ihmisten ylpeys, ja miesten korskeus painuu maahan, ja sinä päivänä Herra yksinänsä on korkea.'),
(1686668,58,23,2,18,'Mutta epäjumalat katoavat kaikki tyynni.'),
(1686669,58,23,2,19,'Silloin mennään kallioluoliin ja maakuoppiin Herran kauhua ja hänen valtansa kirkkautta pakoon, kun hän nousee maata kauhistuttamaan.'),
(1686670,58,23,2,20,'Sinä päivänä ihmiset viskaavat pois myyrille ja yököille hopea- ja kultajumalansa, jotka he ovat tehneet kumarrettaviksensa.'),
(1686671,58,23,2,21,'Ja he menevät vuorenrotkoihin ja kallionkoloihin Herran kauhua ja hänen valtansa kirkkautta pakoon, kun hän nousee maata kauhistuttamaan.'),
(1686672,58,23,2,22,'Luopukaa siis ihmisistä, joilla on vain henkäys sieraimissa, sillä minkä arvoiset he ovat!'),
(1686673,58,23,3,1,'Sillä katso, Herra, Herra Sebaot ottaa pois Jerusalemilta ja Juudalta varan ja turvan, kaiken leivänvaran ja kaiken vedenvaran,'),
(1686674,58,23,3,2,'sankarin ja soturin, tuomarin ja profeetan, tietäjän ja vanhimman,'),
(1686675,58,23,3,3,'viidenkymmenenpäämiehen ja arvomiehen, neuvonantajan, taitoniekan ja taikurin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686676,58,23,3,4,'Ja minä panen nuorukaiset heille päämiehiksi, ja pahankuriset hallitsevat heitä.'),
(1686677,58,23,3,5,'Kansassa sortaa kukin toistaan, jokainen lähimmäistään; nuorukainen rehentelee vanhusta vastaan, halpa-arvoinen arvollista vastaan.'),
(1686678,58,23,3,6,'Kun veli tarttuu veljeensä isänsä talossa sanoen: "Sinulla on vielä vaatteet, rupea ruhtinaaksemme ja ota huostaasi tämä raunioläjä",'),
(1686679,58,23,3,7,'niin tämä sinä päivänä korottaa äänensä sanoen: "Ei minusta ole haavoja sitomaan; ei ole minun talossani leipää, ei vaatetta, älkää panko minua kansan ruhtinaaksi".'),
(1686680,58,23,3,8,'Sillä Jerusalem kaatuu ja Juuda kukistuu, koska heidän kielensä ja heidän tekonsa ovat Herraa vastaan ja he uhittelevat hänen kunniansa kasvoja.'),
(1686681,58,23,3,9,'Heidän kasvojensa hahmo todistaa heitä vastaan; syntinsä he tuovat julki niinkuin sodomalaiset, he eivät niitä salaa. Voi heitä! Itsellensä he pahaa tekevät.'),
(1686682,58,23,3,10,'Sanokaa hurskaasta, että hänen käy hyvin, sillä he saavat nauttia tekojensa hedelmiä.'),
(1686683,58,23,3,11,'Voi jumalatonta! Hänen käy pahoin, sillä hänen kättensä teot maksetaan hänelle.'),
(1686684,58,23,3,12,'Minun kansani käskijät ovat lapsia, ja naiset sitä hallitsevat. Kansani, sinun johtajasi ovat eksyttäjiä, he ovat hämmentäneet sinun polkujesi suunnan.'),
(1686685,58,23,3,13,'Herra asettuu käymään oikeutta, nousee kansoja tuomitsemaan.'),
(1686686,58,23,3,14,'Herra käy tuomiolle kansansa vanhinten ja sen päämiesten kanssa: Te olette raiskanneet viinitarhan; teidän taloissanne on kurjilta ryöstettyä tavaraa.'),
(1686687,58,23,3,15,'Kuinka saatatte runnella minun kansaani ja ruhjoa kurjien kasvot? sanoo Herra, Herra Sebaot.'),
(1686688,58,23,3,16,'Ja Herra sanoi: Koska Siionin tyttäret korskeilevat, kulkevat kaula kenossa ja silmillään vilkuillen, astua sipsuttelevat ja nilkkarenkaitaan kilistelevät,'),
(1686689,58,23,3,17,'tekee Herra Siionin tytärten päälaen rupiseksi, ja Herra paljastaa heidän häpynsä.'),
(1686690,58,23,3,18,'Sinä päivänä Herra poistaa koreat nilkkarenkaat, otsanauhat, puolikuukorut,'),
(1686691,58,23,3,19,'korvarenkaat, rannerenkaat, hunnut,'),
(1686692,58,23,3,20,'juhlapäähineet, jalkakäädyt, koruvyöt, hajupullot, taikahelyt,'),
(1686693,58,23,3,21,'sormukset, nenärenkaat,'),
(1686694,58,23,3,22,'juhlavaatteet, kaavut, vaipat, kukkarot,'),
(1686695,58,23,3,23,'kuvastimet, aivinapaidat, käärelakit ja päällysharsot.'),
(1686696,58,23,3,24,'Silloin tulee tuoksun sijaan löyhkä, vyön sijaan nuora, käherretyn tukan sijaan kaljuus, korupuvun sijaan säkkiverho, kauneuden sijaan polttomerkki.'),
(1686697,58,23,3,25,'Sinun miehesi kaatuvat miekkaan ja sinun sankarisi sotaan.'),
(1686698,58,23,3,26,'Ja Siionin portit valittavat ja vaikeroivat, ja typötyhjänä hän istuu maassa.'),
(1686699,58,23,4,1,'Sinä päivänä seitsemän naista tarttuu yhteen mieheen sanoen: "Me syömme omaa leipäämme ja vaatetamme itsemme omilla vaatteilla, kunhan vain meidät otetaan sinun nimiisi; poista meidän häpeämme".'),
(1686700,58,23,4,2,'Sinä päivänä on Herran vesa oleva Israelin pelastuneille kaunistus ja kunnia ja maan hedelmä heille korkeus ja loisto.'),
(1686701,58,23,4,3,'Ja ne, jotka Siionissa ovat säilyneet ja Jerusalemissa jäljelle jääneet, kutsutaan pyhiksi, kaikki, jotka ovat kirjoitetut Jerusalemissa elävien lukuun -'),
(1686702,58,23,4,4,'silloin kun Herra on pessyt pois Siionin tytärten saastan ja huuhtonut Jerusalemista sen verenviat tuomion ja puhdistuksen hengellä.'),
(1686703,58,23,4,5,'Ja Herra luo Siionin vuorelle koko asuinsijansa ylle ja sen juhlakokousten ylle pilven päivän ajaksi ja savun ynnä tulenliekin hohteen yöksi, sillä kaiken kirkkauden yllä on oleva peite'),
(1686704,58,23,4,6,'ja verho varjoamassa päivän helteeltä sekä turvaamassa ja suojaamassa rajuilmalta ja sateelta.'),
(1686705,58,23,5,1,'Minä laulan ystävästäni, laulan rakkaani laulun hänen viinitarhastaan. Ystävälläni oli viinitarha lihavalla vuorenrinteellä.'),
(1686706,58,23,5,2,'Hän kuokki ja kivesi sen ja istutti siihen jaloja köynnöksiä, rakensi sen keskelle tornin ja hakkasi sinne myös kuurnan. Ja hän odotti sen kasvavan rypäleitä, mutta se kasvoi villimarjoja.'),
(1686707,58,23,5,3,'Ja nyt, te Jerusalemin asukkaat ja Juudan miehet, tuomitkaa minun ja minun viinitarhani välillä.'),
(1686708,58,23,5,4,'Mitä olisi viinitarhalleni vielä ollut tehtävä, jota en olisi sille tehnyt? Miksi se kasvoi villimarjoja, kun minä odotin sen kasvavan rypäleitä?'),
(1686709,58,23,5,5,'Mutta nyt minä ilmoitan teille, mitä teen viinitarhalleni: minä poistan siitä aidan, niin että se jää hävitettäväksi, särjen siitä muurin, niin että se jää tallattavaksi.'),
(1686710,58,23,5,6,'Minä hävitän sen: ei sitä enää vesota eikä kuokita, vaan se on kasvava ohdaketta ja orjantappuraa, ja minä kiellän pilvet sille vettä satamasta.'),
(1686711,58,23,5,7,'Sillä Israelin heimo on Herran Sebaotin viinitarha, ja Juudan miehet ovat hänen ilo-istutuksensa. Ja hän odotti oikeutta, mutta katso, tuli oikeuttomuus, ja vanhurskautta, mutta katso, tuli vaikerrus.'),
(1686712,58,23,5,8,'Voi niitä, jotka liittävät talon taloon, yhdistävät pellon peltoon, kunnes ei jää enää tilaa ja te yksin asutte maassa!'),
(1686713,58,23,5,9,'Minun korviini kuului Herran Sebaotin sana: Totisesti, ne monet talot tulevat autioiksi, ne suuret ja kauniit asujattomiksi.'),
(1686714,58,23,5,10,'Sillä kymmenen auranalaa viinitarhaa on antava yhden bat-mitan, ja hoomerin kylvö on antava eefan.'),
(1686715,58,23,5,11,'Voi niitä, jotka aamuvarhaisesta väkijuoman jäljessä juoksevat ja iltamyöhään viipyvät viinistä hehkuvina!'),
(1686716,58,23,5,12,'Kanteleet, harput, vaskirummut, huilut ja viinit on heillä pidoissansa, mutta Herran tekoja he eivät tarkkaa, eivät näe hänen kättensä töitä.'),
(1686717,58,23,5,13,'Sentähden minun kansani siirretään maastansa äkkiarvaamatta, sen ylhäiset kärsivät nälkää, ja sen remuava joukko nääntyy janoon.'),
(1686718,58,23,5,14,'Sentähden tuonela levittää kitansa ammolleen, avaa suunsa suunnattomaksi; ja sinne menee sen loisto, sen remuava ja pauhaava joukko, kaikki sen ilonpitäjät.'),
(1686719,58,23,5,15,'Silloin ihminen masentuu ja mies painuu maahan, maahan painuvat ylpeitten silmät;'),
(1686720,58,23,5,16,'mutta Herra Sebaot on oleva korkea tuomiossa, pyhä Jumala on oleva pyhä vanhurskaudessa.'),
(1686721,58,23,5,17,'Ja karitsat käyvät siellä niinkuin laitumillansa, ja vieraat syöttävät rikkaitten rauniosijoja.'),
(1686722,58,23,5,18,'Voi niitä, jotka vetävät perässänsä rangaistusta turhuuden köysillä, synnin palkkaa kuin vaunujen valjailla;'),
(1686723,58,23,5,19,'niitä, jotka sanovat: "Joutukoon pian hänen tekonsa, että me sen näemme; täyttyköön ja tapahtukoon Israelin Pyhän aivoitus, että me sen tiedämme!"'),
(1686724,58,23,5,20,'Voi niitä, jotka sanovat pahan hyväksi ja hyvän pahaksi, jotka tekevät pimeyden valkeudeksi ja valkeuden pimeydeksi, jotka tekevät karvaan makeaksi ja makean karvaaksi!'),
(1686725,58,23,5,21,'Voi niitä, jotka ovat viisaita omissa silmissään ja ymmärtäväisiä omasta mielestänsä!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686726,58,23,5,22,'Voi niitä, jotka ovat urhoja viinin juonnissa ja aimomiehiä väkijuoman sekoittamisessa,'),
(1686727,58,23,5,23,'jotka lahjuksesta julistavat syyllisen syyttömäksi ja ottavat oikeuden siltä, joka oikeassa on!'),
(1686728,58,23,5,24,'Sentähden, niinkuin tulen kieli syö oljet ja kuloheinä raukeaa liekkiin, niin heidän juurensa mätänee, ja heidän kukkansa hajoaa tomuna ilmaan, sillä he ovat ylenkatsoneet Herran Sebaotin lain ja pitäneet pilkkanansa Israelin Pyhän sanaa.'),
(1686729,58,23,5,25,'Sentähden syttyi Herran viha hänen kansaansa kohtaan: hän ojensi kätensä sitä vastaan ja löi sitä, niin että vuoret vapisivat ja heidän raatonsa olivat tunkiona keskellä katuja. Tästä kaikesta ei hänen vihansa asettunut, vaan hänen kätensä on vielä ojennettuna.'),
(1686730,58,23,5,26,'Ja hän pystyttää viirin kaukaiselle kansalle ja viheltää sen luokseen maan äärestä. Ja katso, se tulee viipymättä, nopeasti.'),
(1686731,58,23,5,27,'Ei kukaan heistä väsy eikä kompastu, ei kukaan torku eikä nuku, ei vyö kupeilta aukene, eikä kengänpaula katkea.'),
(1686732,58,23,5,28,'Sen nuolet ovat teroitetut, sen jouset kaikki jännitetyt, sen orhien kaviot ovat kuin pii, ja sen rattaat kuin rajuilma.'),
(1686733,58,23,5,29,'Sen kiljunta on kuin naarasleijonan, se kiljuu kuin nuoret jalopeurat, se ärjyy ja tempaa saaliin ja vie sen pois, eikä pelastajaa ole.'),
(1686734,58,23,5,30,'Se ärjyy sille sinä päivänä, niinkuin meri ärjyy. Silloin tähyillään maata, mutta katso, on pimeys, on ahdistus, ja valo on pimennyt sen synkeyteen.'),
(1686735,58,23,6,1,'Kuningas Ussian kuolinvuotena minä näin Herran istuvan korkealla ja ylhäisellä istuimella, ja hänen vaatteensa liepeet täyttivät temppelin.'),
(1686736,58,23,6,2,'Serafit seisoivat hänen ympärillään; kullakin oli kuusi siipeä: kahdella he peittivät kasvonsa, kahdella he peittivät jalkansa, ja kahdella he lensivät.'),
(1686737,58,23,6,3,'Ja he huusivat toinen toisellensa ja sanoivat: "Pyhä, pyhä, pyhä Herra Sebaot; kaikki maa on täynnä hänen kunniaansa".'),
(1686738,58,23,6,4,'Ja kynnysten perustukset vapisivat heidän huutonsa äänestä, ja huone täyttyi savulla.'),
(1686739,58,23,6,5,'Niin minä sanoin: "Voi minua! Minä hukun, sillä minulla on saastaiset huulet, ja minä asun kansan keskellä, jolla on saastaiset huulet; sillä minun silmäni ovat nähneet kuninkaan, Herran Sebaotin."'),
(1686740,58,23,6,6,'Silloin lensi minun luokseni yksi serafeista, kädessään hehkuva kivi, jonka hän oli pihdeillä ottanut alttarilta,'),
(1686741,58,23,6,7,'ja kosketti sillä minun suutani sanoen: "Katso, tämä on koskettanut sinun huuliasi; niin on sinun velkasi poistettu ja syntisi sovitettu".'),
(1686742,58,23,6,8,'Ja minä kuulin Herran äänen sanovan: "Kenenkä minä lähetän? Kuka menee meidän puolestamme?" Minä sanoin: "Katso, tässä minä olen, lähetä minut".'),
(1686743,58,23,6,9,'Niin hän sanoi: "Mene ja sano tälle kansalle: ''Kuulemalla kuulkaa, älkääkä ymmärtäkö, näkemällä nähkää, älkääkä käsittäkö''.'),
(1686744,58,23,6,10,'Paaduta tämän kansan sydän, koveta sen korvat, sokaise sen silmät, ettei se näkisi silmillään, ei kuulisi korvillaan, ei ymmärtäisi sydämellään eikä kääntyisi ja parannetuksi tulisi."'),
(1686745,58,23,6,11,'Mutta minä sanoin: "Kuinka kauaksi aikaa, Herra?" Hän vastasi: "Siihen asti, kunnes kaupungit tulevat autioiksi, asumattomiksi, ja talot tyhjiksi ihmisistä ja pellot on hävitetty erämaaksi;'),
(1686746,58,23,6,12,'kunnes Herra on karkoittanut ihmiset kauas ja suuri autius tullut keskelle maata.'),
(1686747,58,23,6,13,'Ja jos siellä on jäljellä kymmenes osa, niin hävitetään vielä sekin. Mutta niinkuin tammesta ja rautatammesta jää kaadettaessa kanto, niin siitäkin: se kanto on pyhä siemen."'),
(1686748,58,23,7,1,'Aahaan, Jootamin pojan, Ussian pojanpojan, Juudan kuninkaan, aikana lähtivät Resin, Aramin kuningas, ja Pekah, Remaljan poika, Israelin kuningas, sotimaan Jerusalemia vastaan, mutta he eivät voineet valloittaa sitä.'),
(1686749,58,23,7,2,'Ja kun Daavidin huoneelle ilmoitettiin sanoma: "Aram on leiriytynyt Efraimiin", niin kuninkaan ja hänen kansansa sydän vapisi, niinkuin metsän puut vapisevat tuulessa.'),
(1686750,58,23,7,3,'Silloin Herra sanoi Jesajalle: "Mene Aahasta vastaan, sinä ja sinun poikasi Sear-Jaasub, Ylälammikon vesijohdon päähän, Vanuttajankedon tielle,'),
(1686751,58,23,7,4,'ja sano hänelle: Ole varuillasi ja pysy rauhallisena, älä pelkää, älköönkä sydämesi säikkykö noita kahta savuavaa kekäleenpätkää: Resinin ja Aramin ynnä Remaljan pojan vihanvimmaa.'),
(1686752,58,23,7,5,'Koska Aram, Efraim ja Remaljan poika ovat hankkineet pahaa sinua vastaan sanoen:'),
(1686753,58,23,7,6,'''Lähtekäämme Juudaa vastaan, täyttäkäämme se kauhulla, vallatkaamme se itsellemme ja asettakaamme sinne kuninkaaksi Taabalin poika'','),
(1686754,58,23,7,7,'niin sanoo Herra, Herra näin: Ei se onnistu, eikä se tapahdu.'),
(1686755,58,23,7,8,'Sillä Aramin pää on Damasko, ja Damaskon pää on Resin - mutta kuusikymmentä viisi vuotta vielä, ja Efraim on muserrettu eikä ole enää kansa - ja Efraimin pää on Samaria,'),
(1686756,58,23,7,9,'ja Samarian pää on Remaljan poika. Ellette usko, niin ette kestä."'),
(1686757,58,23,7,10,'Ja Herra puhui jälleen Aahaalle sanoen:'),
(1686758,58,23,7,11,'"Pyydä itsellesi merkki Herralta, Jumalaltasi, pyydä alhaalta syvyydestä taikka ylhäältä korkeudesta".'),
(1686759,58,23,7,12,'Mutta Aahas vastasi: "En pyydä enkä kiusaa Herraa".'),
(1686760,58,23,7,13,'Siihen hän lausui: "Kuulkaa, te Daavidin suku, eikö se riitä, että te ihmiset väsytätte, kun vielä minun Jumalanikin itseenne väsytätte?'),
(1686761,58,23,7,14,'Sentähden Herra itse antaa teille merkin: Katso, neitsyt tulee raskaaksi ja synnyttää pojan ja antaa hänelle nimen Immanuel.'),
(1686762,58,23,7,15,'Voita ja hunajaa hän syö siinä iässä, jolloin hän oppii hylkäämään pahan ja valitsemaan hyvän;'),
(1686763,58,23,7,16,'sillä ennenkuin poika on oppinut hylkäämään pahan ja valitsemaan hyvän, tulee autioksi maa, jonka kahta kuningasta sinä kauhistut.'),
(1686764,58,23,7,17,'Herra antaa tulla sinulle, sinun kansallesi ja isäsi suvulle ne päivät, joita ei ole ollut siitä asti, kun Efraim luopui Juudasta - antaa tulla Assurin kuninkaan.'),
(1686765,58,23,7,18,'Ja sinä päivänä Herra viheltää kärpäset Egyptin virtain suulta ja mehiläiset Assurin maasta,'),
(1686766,58,23,7,19,'ja ne tulevat ja laskeutuvat kaikki vuorenrotkoihin ja kallionkoloihin, kaikkiin orjantappurapensaisiin ja kaikille juottopaikoille.'),
(1686767,58,23,7,20,'Sinä päivänä Herra ajattaa virran tuolta puolen palkatulla partaveitsellä, Assurin kuninkaalla, pään ja häpykarvat; viepä se vielä parrankin.'),
(1686768,58,23,7,21,'Siihen aikaan pitää mies lehmäsen ja pari lammasta,'),
(1686769,58,23,7,22,'mutta runsaan maidon tulon tähden hän syö voita; sillä voita ja hunajaa syövät kaikki maahan jäljelle jääneet.'),
(1686770,58,23,7,23,'Ja siihen aikaan jokainen paikka, jossa kasvaa tuhat viinipuuta, arvoltaan tuhat hopeasekeliä, joutuu orjantappurain ja ohdakkeiden valtaan.'),
(1686771,58,23,7,24,'Sinne on mentävä nuolet ja jousi mukana, sillä koko maa on pelkkää orjantappuraa ja ohdaketta.'),
(1686772,58,23,7,25,'Ei yhdellekään niistä vuorista, joita nyt kuokalla kuokitaan, enää mennä orjantappurain ja ohdakkeiden pelosta; ne jäävät härkien laitumeksi ja lammasten tallattavaksi."'),
(1686773,58,23,8,1,'Ja Herra sanoi minulle: "Ota iso taulu ja kirjoita siihen selkeällä kirjoituksella: Maher-Saalal Haas-Bas.'),
(1686774,58,23,8,2,'Ja minä otan itselleni luotettavat todistajat, pappi Uurian ja Sakarjan, Jeberekjan pojan."'),
(1686775,58,23,8,3,'Sitten minä lähestyin profeetta-vaimoani, ja hän tuli raskaaksi ja synnytti pojan. Niin Herra sanoi minulle: "Pane hänelle nimeksi Maher-Saalal Haas-Bas.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686776,58,23,8,4,'Sillä ennenkuin poika oppii sanomaan: ''isä'' ja ''äiti'', viedään Damaskoon tavarat ja Samarian saalis Assurin kuninkaan eteen."'),
(1686777,58,23,8,5,'Ja Herra puhui jälleen minulle ja sanoi:'),
(1686778,58,23,8,6,'"Koska tämä kansa halveksii Siiloan hiljaa virtaavia vesiä ja iloitsee Resinin ja Remaljan pojan kanssa,'),
(1686779,58,23,8,7,'niin katso, sentähden Herra antaa tulla heidän ylitsensä virran vedet, valtavat ja suuret: Assurin kuninkaan ja kaiken hänen kunniansa; se nousee kaikkien uomiensa yli ja menee kaikkien äyräittensä yli,'),
(1686780,58,23,8,8,'ja se tunkeutuu Juudaan, paisuu ja tulvii ja ulottuu kaulaan saakka. Ja levittäen siipensä se täyttää yliyltään sinun maasi, Immanuel."'),
(1686781,58,23,8,9,'Riehukaa, kansat, kuitenkin kukistutte; kuulkaa, kaikki kaukaiset maat: sonnustautukaa, kuitenkin kukistutte; sonnustautukaa, kuitenkin kukistutte.'),
(1686782,58,23,8,10,'Pitäkää neuvoa: se raukeaa; sopikaa sopimus: ei se pysy. Sillä Jumala on meidän kanssamme.'),
(1686783,58,23,8,11,'Sillä näin sanoi minulle Herra, kun hänen kätensä valtasi minut ja hän varoitti minua vaeltamasta tämän kansan tietä:'),
(1686784,58,23,8,12,'"Älkää sanoko salaliitoksi kaikkea, mitä tämä kansa salaliitoksi sanoo; älkää peljätkö, mitä se pelkää, älkääkä kauhistuko.'),
(1686785,58,23,8,13,'Herra Sebaot pitäkää pyhänä, häntä te peljätkää ja kauhistukaa.'),
(1686786,58,23,8,14,'Ja hän on oleva pyhäkkö, hän loukkauskivi ja kompastuksen kallio molemmille Israelin huonekunnille, paula ja ansa Jerusalemin asukkaille.'),
(1686787,58,23,8,15,'Monet heistä kompastuvat ja kaatuvat ja ruhjoutuvat, monet kiedotaan ja vangitaan.'),
(1686788,58,23,8,16,'Sido todistus talteen, lukitse laki sinetillä minun opetuslapsiini."'),
(1686789,58,23,8,17,'Niin minä odotan Herraa, joka kätkee kasvonsa Jaakobin heimolta, ja panen toivoni häneen.'),
(1686790,58,23,8,18,'Katso, minä ja lapset, jotka Herra on minulle antanut, me olemme Herran Sebaotin merkkeinä ja ihmeinä Israelissa, hänen, joka asuu Siionin vuorella.'),
(1686791,58,23,8,19,'Ja kun he sanovat teille: "Kysykää vainaja- ja tietäjähengiltä, jotka supisevat ja mumisevat", niin eikö kansa kysyisi Jumalaltansa? Kuolleiltako elävien puolesta?'),
(1686792,58,23,8,20,'"Pysykää laissa ja todistuksessa!" Elleivät he näin sano, ei heillä aamunkoittoa ole.'),
(1686793,58,23,8,21,'Ja siellä he kuljeskelevat vaivattuina ja nälkäisinä, ja nälissään he vimmastuvat ja kiroavat kuninkaansa ja Jumalansa. He luovat silmänsä korkeuteen,'),
(1686794,58,23,8,22,'he katsahtavat maan puoleen, mutta katso: ainoastaan ahdistusta ja pimeyttä; he ovat syöstyt tuskan synkeyteen ja pimeyteen.'),
(1686795,58,23,8,23,'Mutta ei jää pimeään se, mikä nyt on vaivan alla. Entiseen aikaan hän saattoi halveksituksi Sebulonin maan ja Naftalin maan, mutta tulevaisuudessa hän saattaa kunniaan merentien, Jordanin tuonpuoleisen maan, pakanain alueen.'),
(1686796,58,23,9,1,'Kansa, joka pimeydessä vaeltaa, näkee suuren valkeuden; jotka asuvat kuoleman varjon maassa, niille loistaa valkeus.'),
(1686797,58,23,9,2,'Sinä lisäät kansan, annat sille suuren ilon; he iloitsevat sinun edessäsi, niinkuin elonaikana iloitaan, niinkuin saaliinjaossa riemuitaan.'),
(1686798,58,23,9,3,'Sillä heidän kuormansa ikeen, heidän olkainsa vitsan ja heidän käskijänsä sauvan sinä särjet niinkuin Midianin päivänä;'),
(1686799,58,23,9,4,'ja kaikki taistelun pauhussa tallatut sotakengät ja verellä tahratut vaipat poltetaan ja tulella kulutetaan.'),
(1686800,58,23,9,5,'Sillä lapsi on meille syntynyt, poika on meille annettu, jonka hartioilla on herraus, ja hänen nimensä on: Ihmeellinen neuvonantaja, Väkevä Jumala, Iankaikkinen isä, Rauhanruhtinas.'),
(1686801,58,23,9,6,'Herraus on oleva suuri ja rauha loppumaton Daavidin valtaistuimella ja hänen valtakunnallansa; se perustetaan ja vahvistetaan tuomiolla ja vanhurskaudella nyt ja iankaikkisesti. Herran Sebaotin kiivaus on sen tekevä.'),
(1686802,58,23,9,7,'Herra lähetti sanan Jaakobia vastaan, ja se iski Israeliin,'),
(1686803,58,23,9,8,'ja sen sai tuntea koko kansa, Efraim ja Samarian asukkaat, mutta he sanoivat ylpeydessään ja sydämensä kopeudessa:'),
(1686804,58,23,9,9,'"Tiilikivet sortuivat maahan, mutta me rakennamme hakatuista kivistä; metsäviikunapuut lyötiin poikki, mutta me panemme setripuita sijaan".'),
(1686805,58,23,9,10,'Silloin Herra nostatti sitä vastaan Resinin ahdistajat ja kiihoitti sen viholliset,'),
(1686806,58,23,9,11,'aramilaiset edestä ja filistealaiset takaa, ja he söivät Israelia suun täydeltä. Kaikesta tästä ei hänen vihansa ole asettunut, ja vielä on hänen kätensä ojennettu.'),
(1686807,58,23,9,12,'Mutta kansa ei palannut kurittajansa tykö, eivätkä he etsineet Herraa Sebaotia.'),
(1686808,58,23,9,13,'Sentähden Herra katkaisi Israelilta pään ja hännän, palmunlehvän ja kaislan, yhtenä päivänä.'),
(1686809,58,23,9,14,'Vanhin ja arvomies on pää, mutta profeetta, joka valhetta opettaa, on häntä.'),
(1686810,58,23,9,15,'Ja tämän kansan johtajat tulivat eksyttäjiksi, ja johdettavat joutuivat hämminkiin.'),
(1686811,58,23,9,16,'Sentähden Herra ei iloitse sen nuorista miehistä eikä armahda sen orpoja ja leskiä, sillä he ovat kaikki jumalattomia ja pahantekijöitä, ja jokainen suu puhuu hulluutta. Kaikesta tästä ei hänen vihansa ole asettunut, ja vielä on hänen kätensä ojennettu.'),
(1686812,58,23,9,17,'Sillä jumalattomuus palaa tulena, kuluttaa orjantappurat ja ohdakkeet ja sytyttää sankan metsän, niin että se savuna tupruaa ilmaan.'),
(1686813,58,23,9,18,'Herran Sebaotin vihasta maa syttyy palamaan, ja kansa on kuin tulen syötävänä; toinen ei sääli toistansa.'),
(1686814,58,23,9,19,'Ahmivat oikealta, mutta on yhä nälkä, syövät vasemmalta, mutta eivät saa kylläänsä; jokainen syö oman käsivartensa lihaa:'),
(1686815,58,23,9,20,'Manasse Efraimia ja Efraim Manassea, molemmat yhdessä käyvät Juudan kimppuun. Kaikesta tästä ei hänen vihansa ole asettunut, ja vielä on hänen kätensä ojennettu.'),
(1686816,58,23,10,1,'Voi niitä, jotka vääriä säädöksiä säätävät, jotka turmiollisia tuomioita kirjoittelevat,'),
(1686817,58,23,10,2,'vääntääksensä vaivaisten asian ja riistääksensä minun kansani kurjilta oikeuden, että lesket joutuisivat heidän saaliiksensa ja orvot heidän ryöstettäviksensä!'),
(1686818,58,23,10,3,'Mutta mitä te teette koston päivänä, rajumyrskyssä, joka tulee kaukaa? Kenen turviin pakenette apua saamaan ja minne talletatte tavaranne?'),
(1686819,58,23,10,4,'Ei muuta kuin vaipua vangittujen joukkoon tai kaatua surmattujen sekaan. Kaikesta tästä ei hänen vihansa ole asettunut, ja vielä on hänen kätensä ojennettu.'),
(1686820,58,23,10,5,'Voi Assuria, joka on minun vihani vitsa ja jolla on kädessään minun suuttumukseni sauva!'),
(1686821,58,23,10,6,'Minä lähetän hänet jumalattoman kansakunnan kimppuun, käsken hänet vihastukseni kansaa vastaan saalista saamaan ja ryöstöä ryöstämään ja tallaamaan sitä kuin katujen lokaa.'),
(1686822,58,23,10,7,'Mutta hän ei ajattele niin, se ei ole hänen sydämensä aivoitus, vaan hänen sydämensä halu on hävittää ja tuhota kansoja paljon.'),
(1686823,58,23,10,8,'Sillä hän sanoo: "Eivätkö minun päämieheni ole kaikki kuninkaita?'),
(1686824,58,23,10,9,'Eikö käynyt Kalnon niinkuin Karkemiin, eikö Hamatin niinkuin Arpadin ja Samarian niinkuin Damaskon?'),
(1686825,58,23,10,10,'Niinkuin minun käteni on saavuttanut epäjumalien valtakunnat, joiden jumalankuvat olivat paremmat kuin Jerusalemin ja Samarian -');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686826,58,23,10,11,'niin enkö minä tekisi Jerusalemille ja sen epäjumalankuville, samoin kuin minä tein Samarialle ja sen epäjumalille?"'),
(1686827,58,23,10,12,'Mutta kun Herra on päättänyt kaiken työnsä Siionin vuorella ja Jerusalemissa, niin minä kostan Assurin kuninkaalle hänen sydämensä ylpeyden hedelmän ja hänen kopeitten silmiensä korskan.'),
(1686828,58,23,10,13,'Sillä hän sanoo: "Oman käteni voimalla minä sen tein ja viisaudellani, sillä minä olen ymmärtäväinen. Minä siirsin kansojen rajat ja ryöstin heidän aarteensa ja puskin kumoon kuin härkä valtaistuimella-istujat.'),
(1686829,58,23,10,14,'Minun käteni tavoitti kansojen rikkaudet niinkuin linnun pesän; ja niinkuin hyljätyt munat kootaan, niin minä olen koonnut kaikki maat, eikä ketään ollut, joka olisi siipeä räpyttänyt tai nokkaa avannut ja piipittänyt."'),
(1686830,58,23,10,15,'Korskeileeko kirves hakkaajaansa vastaan, tai suurenteleeko saha heiluttajaansa vastaan? Ikäänkuin vitsa heiluttaisi kohottajaansa ja sauva saisi koholle sen, joka ei ole puuta!'),
(1686831,58,23,10,16,'Sentähden Herra, Herra Sebaot, lähettää hänen lihavuuteensa näivetystaudin, ja hänen kunniansa alle syttyy tuli niinkuin tulipalo.'),
(1686832,58,23,10,17,'Israelin valkeus on tuleva tuleksi ja hänen Pyhänsä liekiksi, joka polttaa ja kuluttaa hänen ohdakkeensa ja orjantappuransa yhtenä päivänä'),
(1686833,58,23,10,18,'ja hänen metsänsä ja puutarhansa ihanuuden, hamaan luihin ja ytimiin, ja hän tulee riutuvan sairaan kaltaiseksi.'),
(1686834,58,23,10,19,'On helppo lukea ne puut, jotka jäävät hänen metsästänsä jäljelle; poikanen voi ne kirjoittaa muistiin.'),
(1686835,58,23,10,20,'Sinä päivänä ei Israelin jäännös eivätkä Jaakobin heimon pelastuneet enää turvaudu lyöjäänsä, vaan totuudessa he turvautuvat Herraan, Israelin Pyhään.'),
(1686836,58,23,10,21,'Jäännös palajaa, Jaakobin jäännös, väkevän Jumalan tykö.'),
(1686837,58,23,10,22,'Sillä vaikka sinun kansasi, Israel, olisi kuin meren hiekka, on siitä palajava ainoastaan jäännös. Päätetty on hävitys, joka tulee, vanhurskautta tulvillaan.'),
(1686838,58,23,10,23,'Sillä hävityksen ja tuomiopäätöksen panee Herra, Herra Sebaot, toimeen kaikessa maassa.'),
(1686839,58,23,10,24,'Sentähden sanoo Herra, Herra Sebaot, näin: "Älä pelkää, minun kansani, joka Siionissa asut, Assuria, kun hän sinua vitsalla lyö ja kohottaa sauvansa sinua vastaan Egyptin tavalla.'),
(1686840,58,23,10,25,'Sillä lyhyt hetki vielä, niin suuttumus täyttyy, ja minun vihani kääntyy hävittämään heidät."'),
(1686841,58,23,10,26,'Ja Herra Sebaot heiluttaa ruoskaa häntä vastaan, niinkuin silloin, kun Midian lyötiin Oorebin kalliolla, ja hänen sauvansa on ojennettuna meren yli, ja hän kohottaa sen niinkuin muinoin Egyptiä vastaan.'),
(1686842,58,23,10,27,'Sinä päivänä heltiää hänen kuormansa sinun hartioiltasi ja hänen ikeensä sinun niskaltasi, sillä ies särkyy lihavuuden pakosta.'),
(1686843,58,23,10,28,'Hän tulee Aijatiin, kulkee Migronin kautta, jättää kuormastonsa Mikmaaseen;'),
(1686844,58,23,10,29,'he kulkevat solatien poikki: "Geba on yöpaikkamme". Raama vapisee, Saulin Gibea pakenee.'),
(1686845,58,23,10,30,'Huuda kimakasti, tytär Gallim! Kuuntele, Laisa! Poloinen Anatot!'),
(1686846,58,23,10,31,'Madmena menee pakoon, Geebimin asukkaat saattavat tavaransa turviin.'),
(1686847,58,23,10,32,'Vielä samana päivänä hän pysähtyy Noobiin, hän kohottaa kätensä tytär Siionin vuorta, Jerusalemin kukkulaa, vastaan -'),
(1686848,58,23,10,33,'katso, silloin Herra, Herra Sebaot, katkaisee hänen latvansa kauhistavalla voimalla, vartevat rungot kaadetaan, ja korkeat kukistuvat.'),
(1686849,58,23,10,34,'Metsän tiheikkö hakataan kirveellä maahan, ja Libanon kaatuu Voimallisen edessä.'),
(1686850,58,23,11,1,'Mutta Iisain kannosta puhkeaa virpi, ja vesa versoo hänen juuristansa.'),
(1686851,58,23,11,2,'Ja hänen päällänsä lepää Herran Henki, viisauden ja ymmärryksen henki, neuvon ja voiman henki, tiedon ja Herran pelon henki.'),
(1686852,58,23,11,3,'Hän halajaa Herran pelkoa; ei hän tuomitse silmän näöltä eikä jaa oikeutta korvan kuulolta,'),
(1686853,58,23,11,4,'vaan tuomitsee vaivaiset vanhurskaasti ja jakaa oikein oikeutta maan nöyrille; suunsa sauvalla hän lyö maata, surmaa jumalattomat huultensa henkäyksellä.'),
(1686854,58,23,11,5,'Vanhurskaus on hänen kupeittensa vyö ja totuus hänen lanteittensa side.'),
(1686855,58,23,11,6,'Silloin susi asuu karitsan kanssa, ja pantteri makaa vohlan vieressä; vasikka ja nuori leijona ja syöttöhärkä ovat yhdessä, ja pieni poikanen niitä paimentaa.'),
(1686856,58,23,11,7,'Lehmä ja karhu käyvät laitumella, niiden vasikat ja pennut yhdessä makaavat, ja jalopeura syö rehua kuin raavas.'),
(1686857,58,23,11,8,'Imeväinen leikittelee kyykäärmeen kololla, ja vieroitettu kurottaa kätensä myrkkyliskon luolaan.'),
(1686858,58,23,11,9,'Ei missään minun pyhällä vuorellani tehdä pahaa eikä vahinkoa, sillä maa on täynnä Herran tuntemusta, niinkuin vedet peittävät meren.'),
(1686859,58,23,11,10,'Sinä päivänä pakanat etsivät Iisain juurta, joka on kansojen lippuna, ja hänen asumuksensa on oleva kunniata täynnä.'),
(1686860,58,23,11,11,'Ja sinä päivänä Herra vielä toisen kerran ojentaa kätensä hankkiakseen itselleen kansansa jäännöksen, joka on jäljellä Assurissa, Egyptissä, Patroksessa, Etiopiassa, Eelamissa, Sinearissa, Hamatissa ja merensaarilla.'),
(1686861,58,23,11,12,'Hän nostaa viirin pakanakansoille ja kokoaa Israelin karkoitetut miehet; ja Juudan hajoitetut naiset hän kerää maan neljästä äärestä.'),
(1686862,58,23,11,13,'Silloin katoaa Efraimin kateus, ja Juudan vihat häviävät. Efraim ei kadehdi Juudaa, eikä Juuda vihaa Efraimia.'),
(1686863,58,23,11,14,'Ja he lentävät länteen päin filistealaisten niskaan, yhdessä he ryöstävät Idän miehiä. Edom ja Mooab joutuvat heidän käsiinsä, ammonilaiset heidän alamaisikseen.'),
(1686864,58,23,11,15,'Ja Herra vihkii tuhon omaksi Egyptin merenlahden ja vihansa hehkussa kohottaa kätensä Eufrat-virtaa vastaan, lyö sen hajalle seitsemäksi puroksi ja tekee sen kengin kuljettavaksi.'),
(1686865,58,23,11,16,'Siitä tulee valtatie hänen kansansa jäännökselle, joka on jäljellä Assurissa, niinkuin tuli Israelille silloin, kun se Egyptin maasta lähti.'),
(1686866,58,23,12,1,'Sinä päivänä sinä sanot: "Minä kiitän sinua, Herra, sillä sinä olit minuun vihastunut, mutta sinun vihasi asettui, ja sinä lohdutit minua.'),
(1686867,58,23,12,2,'Katso, Jumala on minun pelastukseni; minä olen turvassa enkä pelkää, sillä Herra, Herra on minun väkevyyteni ja ylistysvirteni, hän tuli minulle pelastukseksi."'),
(1686868,58,23,12,3,'Te saatte ilolla ammentaa vettä pelastuksen lähteistä.'),
(1686869,58,23,12,4,'Ja sinä päivänä te sanotte: "Kiittäkää Herraa, julistakaa hänen nimeänsä, tehkää hänen suuret tekonsa tiettäviksi kansain keskuudessa, tunnustakaa, että hänen nimensä on korkea.'),
(1686870,58,23,12,5,'Veisatkaa ylistystä Herralle, sillä jaloja töitä hän on tehnyt; tulkoot ne tunnetuiksi kaikessa maassa.'),
(1686871,58,23,12,6,'Huutakaa ja riemuitkaa, Siionin asukkaat, sillä suuri on teidän keskellänne Israelin Pyhä."'),
(1686872,58,23,13,1,'Ennustus Baabelista, Jesajan, Aamoksen pojan, näkemä.'),
(1686873,58,23,13,2,'Pystyttäkää viiri paljaalle vuoren laelle, korottakaa äänenne heille, viittokaa kädellä heitä menemään sisälle ruhtinasten porteista.'),
(1686874,58,23,13,3,'Minä olen antanut käskyn vihkiytyneilleni ja kutsunut urhoni vihani työhön, ylvääni, riemuitsevaiseni.'),
(1686875,58,23,13,4,'Kuule, vuorilla käy kuin paljon väen pauhina; kuule valtakuntain, kokoontuneitten kansojen kohinaa: Herra Sebaot katsastaa sotajoukkoansa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686876,58,23,13,5,'He tulevat kaukaisesta maasta, taivaan ääristä, Herra ja hänen vihansa aseet, hävittämään kaiken maan.'),
(1686877,58,23,13,6,'Valittakaa, sillä Herran päivä on lähellä, se tulee kuin hävitys Kaikkivaltiaalta.'),
(1686878,58,23,13,7,'Sentähden herpoavat kaikki kädet, ja kaikki ihmissydämet raukeavat.'),
(1686879,58,23,13,8,'He peljästyvät, kivut ja tuskat valtaavat heidät, he vääntelehtivät kuin synnyttäjä, tuijottavat toisiinsa tyrmistyneinä, kasvot tulenkarvaisina.'),
(1686880,58,23,13,9,'Katso, Herran päivä tulee, tulee armottomana, tulee kiivaus ja vihan hehku, tekemään autioksi maan ja hävittämään siitä sen syntiset.'),
(1686881,58,23,13,10,'Sillä taivaan tähdet ja Kalevanmiekat eivät loista valollansa, aurinko on pimeä noustessansa, kuu ei kirkkaana kumota.'),
(1686882,58,23,13,11,'Minä kostan maanpiirille sen pahuuden ja jumalattomille heidän pahat tekonsa; minä lopetan julkeitten kopeuden ja painan maahan väkivaltaisten ylpeyden.'),
(1686883,58,23,13,12,'Minä teen kuolevaiset harvinaisemmiksi kuin puhdas kulta, ihmiset harvinaisemmiksi kuin Oofirin kulta.'),
(1686884,58,23,13,13,'Sentähden minä järisytän taivaat, ja maa järkkyy paikaltansa Herran Sebaotin kiivaudesta, hänen vihansa hehkun päivänä.'),
(1686885,58,23,13,14,'Ja niinkuin säikytetyt gasellit ja niinkuin lampaat, joilla ei ole kokoajaa, he kääntyvät kukin kansansa luo, pakenevat kukin omalle maallensa.'),
(1686886,58,23,13,15,'Kuka ikinä tavataan, se lävistetään, kuka kiinni joutuu, se miekkaan kaatuu.'),
(1686887,58,23,13,16,'Heidän pienet lapsensa murskataan heidän silmäinsä edessä, heidän talonsa ryöstetään, ja heidän vaimonsa raiskataan.'),
(1686888,58,23,13,17,'Katso, minä herätän heitä vastaan meedialaiset, jotka eivät hopeasta huoli eivätkä kullasta välitä.'),
(1686889,58,23,13,18,'Heidän jousensa kaatavat nuoret miehet; he eivät armahda kohdun hedelmää eivätkä lapsia sääli.'),
(1686890,58,23,13,19,'Ja Baabelin, valtakuntain kaunistuksen, kaldealaisten ylpeyden ja loiston, käy niinkuin Sodoman ja Gomorran, jotka Jumala hävitti.'),
(1686891,58,23,13,20,'Ei sitä ikinä enää asuta, autioksi jää se polvesta polveen; ei arabialainen sinne telttaansa tee, eivätkä paimenet siellä laumaansa lepuuta.'),
(1686892,58,23,13,21,'Erämaan eläimet lepäävät siellä, sen huoneet ovat täynnä huuhkajia, kamelikurjet asuvat siellä, ja metsänpeikot siellä hyppelevät.'),
(1686893,58,23,13,22,'Sakaalit ulvovat sen palatseissa, aavikkosudet huvilinnoissa. Sen aika on lähellä, tulemaisillaan, ei sen päiviä pidennetä.'),
(1686894,58,23,14,1,'Sillä Herra armahtaa Jaakobia ja valitsee vielä Israelin ja sijoittaa heidät heidän omaan maahansa; muukalaiset liittyvät heihin ja yhtyvät Jaakobin heimoon.'),
(1686895,58,23,14,2,'Kansat ottavat heidät ja tuovat heidät heidän kotiinsa, ja Israelin heimo saa heidät Herran maassa omiksensa, orjiksi ja orjattariksi, ja he vangitsevat vangitsijansa ja vallitsevat käskijöitänsä.'),
(1686896,58,23,14,3,'Ja sinä päivänä, jona Herra päästää sinut rauhaan vaivastasi, tuskastasi ja siitä kovasta työstä, jota sinulla teetettiin,'),
(1686897,58,23,14,4,'sinä virität tämän pilkkalaulun Baabelin kuninkaasta ja sanot: "Kuinka on käskijästä tullut loppu, tullut loppu ahdistuksesta!'),
(1686898,58,23,14,5,'Herra on murtanut jumalattomain sauvan, valtiaitten vitsan,'),
(1686899,58,23,14,6,'joka kiukussa löi kansoja, löi lakkaamatta, joka vihassa vallitsi kansakuntia, vainosi säälimättä.'),
(1686900,58,23,14,7,'Kaikki maa on saanut levon ja rauhan, he puhkeavat riemuun.'),
(1686901,58,23,14,8,'Kypressitkin sinusta iloa pitävät sekä Libanonin setrit: ''Sinun maata mentyäsi ei nouse kukaan meitä hakkaamaan''.'),
(1686902,58,23,14,9,'Tuonela tuolla alhaalla liikkuu sinun tähtesi, ottaaksensa sinut vastaan, kun tulet. Se herättää haamut sinun tähtesi, kaikki maan johtomiehet, nostattaa valtaistuimiltansa kaikki kansojen kuninkaat.'),
(1686903,58,23,14,10,'Kaikki he lausuvat ja sanovat sinulle: ''Myös sinä olet riutunut niinkuin mekin, olet tullut meidän kaltaiseksemme''.'),
(1686904,58,23,14,11,'Alas tuonelaan on vaipunut sinun komeutesi, sinun harppujesi helinä; sinun allasi ovat vuoteena madot, toukat ovat peittonasi.'),
(1686905,58,23,14,12,'Kuinka olet taivaalta pudonnut, sinä kointähti, aamuruskon poika! Kuinka olet maahan syösty, sinä kansojen kukistaja!'),
(1686906,58,23,14,13,'Sinä sanoit sydämessäsi: ''Minä nousen taivaaseen, korkeammalle Jumalan tähtiä minä istuimeni korotan ja istun ilmestysvuorelle, pohjimmaiseen Pohjolaan.'),
(1686907,58,23,14,14,'Minä nousen pilvien kukkuloille, teen itseni Korkeimman vertaiseksi.'''),
(1686908,58,23,14,15,'Mutta sinut heitettiin alas tuonelaan, pohjimmaiseen hautaan.'),
(1686909,58,23,14,16,'Jotka sinut näkevät, ne katsovat pitkään, tarkastavat sinua: ''Onko tämä se mies, joka järisytti maan, järkytti valtakunnat,'),
(1686910,58,23,14,17,'joka teki maanpiirin erämaaksi ja hävitti sen kaupungit, joka ei päästänyt vankejansa kotiin?'''),
(1686911,58,23,14,18,'Kansojen kuninkaat kaikki lepäävät kunniassa, kukin kammiossansa.'),
(1686912,58,23,14,19,'Mutta sinä olet kaukana haudastasi, poisviskattuna niinkuin hylkyvesa, olet peittynyt surmattujen, miekalla lävistettyjen, kiviseen kuoppaan suistuneitten alle, olet kuin tallattu raato.'),
(1686913,58,23,14,20,'Et sinä saa yhtyä heidän kanssaan haudassa, sillä sinä olet maasi hävittänyt, kansasi tappanut. Ei ikinä enää mainita pahantekijäin sukua.'),
(1686914,58,23,14,21,'Laittakaa hänen lapsillensa verilöyly heidän isiensä pahain tekojen tähden, etteivät he nousisi ottamaan omaksensa maata ja täyttäisi maanpiiriä kaupungeilla."'),
(1686915,58,23,14,22,'Minä nousen heitä vastaan, sanoo Herra Sebaot, ja hävitän Baabelilta nimen ja jäännöksen, suvun ja jälkeläiset, sanoo Herra.'),
(1686916,58,23,14,23,'Minä teen sen tuonenkurkien perinnöksi ja vesirämeeksi, minä lakaisen sen pois hävityksen luudalla, sanoo Herra Sebaot.'),
(1686917,58,23,14,24,'Herra Sebaot on vannonut sanoen: Totisesti, mitä minä olen ajatellut, se tapahtuu, mitä minä olen päättänyt, se toteutuu:'),
(1686918,58,23,14,25,'minä muserran Assurin maassani ja tallaan hänet vuorillani, niin että hänen ikeensä heltiää heidän päältään ja hänen kuormansa heltiää heidän hartioiltansa.'),
(1686919,58,23,14,26,'Tämä on päätös, päätetty kaikesta maasta, tämä on käsi, ojennettu kaikkien kansojen yli.'),
(1686920,58,23,14,27,'Sillä Herra Sebaot on päättänyt, - kuka sen tyhjäksi tekee? Hänen kätensä on ojennettu, - kuka sen torjuu?'),
(1686921,58,23,14,28,'Kuningas Aahaan kuolinvuotena tuli tämä ennustus:'),
(1686922,58,23,14,29,'Älä iloitse, Filistea kaikkinesi, siitä että sauva, joka sinua löi, on murtunut. Sillä käärmeen juuresta kasvaa myrkkylisko, ja sen hedelmä on lentävä käärme.'),
(1686923,58,23,14,30,'Vaivaisista kurjimmat löytävät laitumen, ja köyhät saavat turvassa levätä, mutta sinun juuresi minä tapan nälkään, ja sinun jäännöksesi surmataan.'),
(1686924,58,23,14,31,'Valita, portti, huuda, kaupunki; menehdy pelkoon, Filistea kaikkinesi, sillä pohjoisesta tulee savu; eikä yksikään erkane vihollisen riveistä.'),
(1686925,58,23,14,32,'Ja mitä vastataan pakanakansan sanansaattajille? "Herra on perustanut Siionin, ja hänen kansansa kurjat saavat siinä turvan".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686926,58,23,15,1,'Ennustus Mooabista. Hävityksen yönä tuhoutuu Aar-Mooab; hävityksen yönä tuhoutuu Kiir-Mooab.'),
(1686927,58,23,15,2,'Bait ja Diibon nousevat uhrikukkuloille itkemään, Nebolla ja Meedebassa Mooab valittaa; kaikki päät ovat paljaiksi ajellut, kaikki parrat ovat leikatut.'),
(1686928,58,23,15,3,'Kaduilla he kääriytyvät säkkeihin, katoilla ja toreilla kaikki valittavat, menehtyvät itkuun.'),
(1686929,58,23,15,4,'Hesbon ja Elale huutavat; Jahaaseen asti kuuluu niiden parku. Sentähden Mooabin varustetut miehet vaikeroivat, sen sielu vapisee.'),
(1686930,58,23,15,5,'Minun sydämeni huutaa Mooabin tähden; sen pakolaisia on aina Sooariin, aina Eglat-Selisijjaan asti. Luuhitin solatietä he nousevat itkien, Hooronaimin tiellä he puhkeavat parkuun hävityksen tähden.'),
(1686931,58,23,15,6,'Nimrimin vedet ehtyvät erämaaksi, heinä kuivuu, ruoho lakastuu, vihantaa ei ole.'),
(1686932,58,23,15,7,'Sentähden he kantavat hankkimansa säästön ja tallettamansa tavaran Pajupuron yli.'),
(1686933,58,23,15,8,'Parku kiertää Mooabin rajoja, valitus kuuluu Eglaimiin asti, valitus Beer-Eelimiin asti.'),
(1686934,58,23,15,9,'Sillä Diimonin vedet ovat verta täynnä, ja vielä muutakin minä tuotan Diimonille: leijonan Mooabin pelastettujen ja maahan jääneitten kimppuun.'),
(1686935,58,23,16,1,'"Lähettäkää maanhallitsijalle tulevat lampaat Selasta erämaan kautta tytär Siionin vuorelle."'),
(1686936,58,23,16,2,'Ja niinkuin pakenevat linnut, säikytetty pesue, ovat Mooabin tyttäret Arnonin kahlauspaikoilla.'),
(1686937,58,23,16,3,'"Anna neuvo, käy välittämään, tee varjosi yön kaltaiseksi keskellä päivää, kätke karkoitetut, älä ilmaise pakenevia.'),
(1686938,58,23,16,4,'Salli minun karkoitettujeni asua tykönäsi, ole Mooabille suojana hävittäjää vastaan. Sillä sortajalle tulee loppu, hävitys lakkaa, ja polkija on maasta poissa;'),
(1686939,58,23,16,5,'ja valtaistuin vahvistetaan laupeudella, ja sillä istuu vakaasti Daavidin majassa tuomari, joka harrastaa oikeutta ja vanhurskautta ahkeroitsee."'),
(1686940,58,23,16,6,'"Me olemme kuulleet Mooabin ylpeilyn, tuon ylen korskean, hänen kopeilunsa, ylpeilynsä ja vihansa, hänen väärät puheensa."'),
(1686941,58,23,16,7,'Sentähden Mooab Mooabille valittaa, kaikki he valittavat; Kiir-Haresetin rypälekakkuja te huokailette, ratki murtuneina.'),
(1686942,58,23,16,8,'Sillä kuihtuneet ovat Hesbonin viinitarhat, Sibman viiniköynnökset; niiden jalot rypäleet kaatoivat kansojen valtiaita, ne ulottuivat Jaeseriin asti, harhailivat halki erämaan, niiden vesat levisivät, menivät yli meren.'),
(1686943,58,23,16,9,'Sentähden minä itken Jaeserin kanssa, itken Sibman viiniköynnöksiä, kastelen kyyneleilläni sinua, Hesbon, ja sinua, Elale, sillä hedelmän- ja viininkorjuun keskeen on kajahtanut sotahuuto.'),
(1686944,58,23,16,10,'Ilo ja riemu on tauonnut puutarhasta, viinitarhoissa ei riemuita, ei remahdella; ei poljeta viiniä viinikuurnissa. "Minä olen vaientanut ilohuudon."'),
(1686945,58,23,16,11,'Siksi väräjää minun sisimpäni Mooabin tähden niinkuin kannel, minun sydämeni Kiir-Hereksen tähden.'),
(1686946,58,23,16,12,'Ja vaikka Mooab kuinka astuisi uhrikukkulalle ja sillä itsensä uuvuttaisi ja vaikka kuinka menisi pyhäkköönsä rukoilemaan, ei se häntä auta.'),
(1686947,58,23,16,13,'Tämä on sana, jonka Herra ennen puhui Mooabille.'),
(1686948,58,23,16,14,'Mutta nyt Herra puhuu sanoen: Ennenkuin kolme vuotta on kulunut - kolme palkkalaisen vuotta - painuu halvaksi Mooabin kunnia, sen suuret laumat, ja jäännös on oleva pieni, vähäpätöinen, mitätön.'),
(1686949,58,23,17,1,'Ennustus Damaskosta. Katso, Damasko poistetaan kaupunkien luvusta ja luhistuu raunioiksi.'),
(1686950,58,23,17,2,'Autioiksi jäävät Aroerin kaupungit, karjalaumojen haltuun; ne lepäävät siellä, kenenkään peloittelematta.'),
(1686951,58,23,17,3,'Efraimilta menee suojavarustus ja Damaskolta kuninkuus ja Aramista jäännöskin: niiden käy niinkuin israelilaisten kunnian, sanoo Herra Sebaot.'),
(1686952,58,23,17,4,'Ja sinä päivänä Jaakobin kunnia köyhtyy, ja hänen ruumiinsa lihavuus laihtuu.'),
(1686953,58,23,17,5,'Ja käy niinkuin leikkaajan kouraistessa viljaa ja hänen käsivartensa leikatessa tähkäpäitä, käy niinkuin tähkäpäitä poimittaessa Refaimin tasangolla.'),
(1686954,58,23,17,6,'Se siinä jää jälkikorjuuta, mikä öljypuuta karistettaessa: pari, kolme marjaa korkealle latvaan, neljä, viisi hedelmäpuun oksiin, sanoo Herra, Israelin Jumala.'),
(1686955,58,23,17,7,'Sinä päivänä ihminen luo katseen Luojaansa, ja hänen silmänsä katsovat Israelin Pyhään,'),
(1686956,58,23,17,8,'eikä hän luo katsettaan alttareihin, omain kättensä tekoon, eikä katso niihin, mitä hänen sormensa ovat tehneet, ei asera-karsikkoihin, ei auringonpatsaisiin.'),
(1686957,58,23,17,9,'Sinä päivänä ovat hänen linnakaupunkinsa niinkuin autiopaikat metsissä ja kukkuloilla, jotka jätettiin autioiksi israelilaisten tullessa, ja maa muuttuu erämaaksi.'),
(1686958,58,23,17,10,'Sillä sinä unhotit pelastuksesi Jumalan etkä muistanut suojakalliotasi. Sentähden sinä istutat ihania istutuksia ja kylvät vieraita viiniköynnöksiä;'),
(1686959,58,23,17,11,'istuttamispäivänä sinä saat ne isonemaan, ja aamulla saat kylvösi kukoistamaan - mutta poissa on sato sairauden päivänä, ja parantumaton on kipu.'),
(1686960,58,23,17,12,'Voi paljojen kansojen pauhua - ne pauhaavat, niinkuin meri pauhaa, ja kansakuntien kohinaa - ne kohisevat, niinkuin valtavat vedet kohisevat!'),
(1686961,58,23,17,13,'Kansakunnat kohisevat, niinkuin suuret vedet kohisevat, mutta hän nuhtelee niitä, ja ne pakenevat kauas; ne karkoitetaan niinkuin akanat tuulessa vuorilla, niinkuin lentävät lehdet rajuilmassa.'),
(1686962,58,23,17,14,'Katso, ehtoolla on oleva kauhu, aamun tullen ei heitä enää ole. Tämä on riistäjäimme osa, ryöstäjäimme arpa.'),
(1686963,58,23,18,1,'Voi siipien surinan maata, joka on tuolla puolen Etiopian jokien,'),
(1686964,58,23,18,2,'joka lähettää sanansaattajat virralle, ruokovenheissä vesiä myöten! Lähtekää, te nopeat sanansaattajat, vartevan ja kiiltävä-ihoisen kansan luo, lähellä ja kaukana peljätyn kansan luo, väkevän sortajakansan luo, jonka maata joet halkovat.'),
(1686965,58,23,18,3,'Te kaikki maanpiirin asukkaat, te maata asuvaiset, katsokaa, milloin viiri nostetaan vuorille, ja kuunnelkaa, kun pasunaan puhalletaan.'),
(1686966,58,23,18,4,'Sillä näin on Herra minulle sanonut: "Minä pysyn hiljaa ja katselen asunnostani, niinkuin hehkuva helle päivän paistaessa, niinkuin kastepilvi elonajan helteessä".'),
(1686967,58,23,18,5,'Sillä ennen viininkorjuuta, kun kukinta on lopussa ja kukasta on tullut kypsyvä marja, hän hakkaa vesurilla köynnökset ja hävittää, katkoo varret.'),
(1686968,58,23,18,6,'Ne jätetään kaikki vuorten petolintujen ja maan eläinten haltuun. Petolinnut siellä kesää pitävät, ja kaikkinaiset maan eläimet siellä talvehtivat.'),
(1686969,58,23,18,7,'Siihen aikaan varteva ja kiiltävä-ihoinen kansa, lähellä ja kaukana peljätty kansa, väkevä sortajakansa, jonka maata joet halkovat, tuodaan lahjaksi Herralle Sebaotille siihen paikkaan, missä asuu Herran Sebaotin nimi: Siionin vuorelle.'),
(1686970,58,23,19,1,'Ennustus Egyptistä. Katso, Herra ajaa nopealla pilvellä ja tulee Egyptiin. Silloin vapisevat Egyptin epäjumalat hänen edessään, ja sydän raukeaa Egyptin rinnassa.'),
(1686971,58,23,19,2,'Minä kiihoitan Egyptin Egyptiä vastaan, niin että he keskenänsä sotivat, ystävä ystävää vastaan, kaupunki kaupunkia vastaan, valtakunta valtakuntaa vastaan.'),
(1686972,58,23,19,3,'Egyptiltä katoaa rohkeus rinnasta, ja minä hämmennän hänen neuvonsa; ja he kysyvät epäjumalilta, henkienmanaajilta, vainaja- ja tietäjähengiltä.'),
(1686973,58,23,19,4,'Minä annan Egyptin tylyn herran käsiin, ja kova kuningas on hallitseva heitä, sanoo Herra, Herra Sebaot.'),
(1686974,58,23,19,5,'Vedet virrasta loppuvat, joki ehtyy ja kuivuu.'),
(1686975,58,23,19,6,'Joet levittävät löyhkää, Egyptin kanavat mataloituvat ja ehtyvät, ruoko ja kaisla lakastuvat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1686976,58,23,19,7,'Ruohostot Niilivirran varsilla, virran suussa, ja kaikki Niilivirran kylvömaat kuivuvat, kuihtuvat ja häviävät.'),
(1686977,58,23,19,8,'Kalastajat valittavat ja murehtivat; kaikki, jotka heittävät onkea virtaan ja laskevat verkkoa veteen, nääntyvät.'),
(1686978,58,23,19,9,'Häpeään joutuvat, jotka häkilöityjä pellavia pitelevät ja jotka kutovat pellavakankaita.'),
(1686979,58,23,19,10,'Maan peruspylväät murskataan, ja kaikki palkkalaiset ovat murheellisella mielellä.'),
(1686980,58,23,19,11,'Hulluina ovat Sooanin päämiehet kaikki, viisaimmat faraon neuvonantajista ovat neuvossaan tyhmistyneet. Kuinka voitte sanoa faraolle: "Olen viisaitten poika, muinaisajan kuninkaitten jälkeläinen"?'),
(1686981,58,23,19,12,'Missä ovat viisaasi? Ilmoittakoot sinulle - hehän sen tietävät - mitä Herra Sebaot on Egyptin osalle päättänyt.'),
(1686982,58,23,19,13,'Sooanin päämiehet ovat typertyneet, Noofin päämiehet ovat pettyneet. Egyptiä horjuttavat sen sukukuntain kulmakivet;'),
(1686983,58,23,19,14,'Herra on vuodattanut sen keskuuteen sekasorron hengen, ja niin he saattavat Egyptin horjumaan kaikissa menoissansa, niinkuin juopunut horjahtaa oksennukseensa.'),
(1686984,58,23,19,15,'Eikä menesty Egyptille mikään teko, tekipä sen pää tai häntä, palmunlehvä tai kaisla.'),
(1686985,58,23,19,16,'Sinä päivänä Egypti on oleva naisten kaltainen; se vapisee ja pelkää Herran Sebaotin käden heilutusta, kun hän heiluttaa kättään sitä vastaan.'),
(1686986,58,23,19,17,'Ja Juudan maa on oleva Egyptille kauhuksi; niin usein kuin sitä sille mainitaan, pelkää se Herran Sebaotin päätöstä, jonka hän siitä on päättänyt.'),
(1686987,58,23,19,18,'Sinä päivänä on viisi kaupunkia Egyptin maassa puhuva Kanaanin kieltä ja vannova valan Herralle Sebaotille. Yhtä mainitaan nimellä Iir-Heres.'),
(1686988,58,23,19,19,'Sinä päivänä on oleva Herran alttari keskellä Egyptin maata ja sen rajalla Herran patsas.'),
(1686989,58,23,19,20,'Ja se on oleva merkkinä ja todistuksena Herralle Sebaotille Egyptin maassa; sillä he huutavat Herraa sortajain tähden, ja hän lähettää heille vapauttajan ja puolustajan, joka pelastaa heidät.'),
(1686990,58,23,19,21,'Ja Herra tekee itsensä tunnetuksi egyptiläisille, ja egyptiläiset tuntevat Herran sinä päivänä ja palvelevat häntä teuras- ja ruokauhreilla, ja he tekevät Herralle lupauksia ja täyttävät ne.'),
(1686991,58,23,19,22,'Herra lyö egyptiläisiä, lyö ja parantaa; he palajavat Herran tykö, ja hän kuulee heidän rukouksensa ja parantaa heidät.'),
(1686992,58,23,19,23,'Sinä päivänä on oleva valtatie Egyptistä Assuriin, ja Assur yhtyy Egyptiin ja Egypti Assuriin, ja he, Egypti ynnä Assur, palvelevat Herraa.'),
(1686993,58,23,19,24,'Sinä päivänä on Israel oleva kolmantena Egyptin ja Assurin rinnalla, siunauksena keskellä maata,'),
(1686994,58,23,19,25,'sillä Herra Sebaot siunaa sitä sanoen: "Siunattu olkoon Egypti, minun kansani, ja Assur, minun kätteni teko, ja Israel, minun perintöosani".'),
(1686995,58,23,20,1,'Sinä vuonna, jona Tartan, Sargonin, Assurin kuninkaan, lähettämänä, tuli Asdodiin, ryhtyi taisteluun Asdodia vastaan ja valloitti sen -'),
(1686996,58,23,20,2,'siihen aikaan Herra puhui Jesajan, Aamoksen pojan, kautta sanoen: "Mene, riisu säkkipuku lanteiltasi ja vedä kengät jalastasi". Hän teki niin: kulki vaipatta ja avojaloin.'),
(1686997,58,23,20,3,'Sitten Herra sanoi: "Niinkuin palvelijani Jesaja on kolme vuotta kulkenut vaipatta ja avojaloin, merkiksi ja enteeksi Egyptille ja Etiopialle,'),
(1686998,58,23,20,4,'niin on Assurin kuningas kuljettava Egyptin sotavankeja ja Etiopian pakkosiirtolaisia, sekä nuoria että vanhoja, vaipattomina ja avojaloin, takapuolet paljaina - Egyptin häpeä!'),
(1686999,58,23,20,5,'Silloin he kauhistuvat ja saavat häpeän Etiopiasta, joka oli heidän toivonsa, ja Egyptistä, joka oli heidän ylpeytensä.'),
(1687000,58,23,20,6,'Ja tämän rantamaan asukkaat sanovat sinä päivänä: ''Katso, näin on käynyt meidän toivomme, jonka turviin me pakenimme apua saamaan, vapautuaksemme Assurin kuninkaasta. Kuinka me sitten itse pelastuisimme?''"'),
(1687001,58,23,21,1,'Ennustus meren viereisestä erämaasta. Niinkuin myrskytuulet kiitävät Etelämaassa, niin tulee se erämaasta, peloittavasta maasta.'),
(1687002,58,23,21,2,'Julma näky ilmoitettiin minulle: "Ryöstäjä ryöstää, hävittäjä hävittää. Hyökkää, Eelam! Piiritä, Meedia! Kaiken huokailun minä lopetan."'),
(1687003,58,23,21,3,'Sentähden minun lanteeni ovat täynnä vavistusta, minut valtaavat tuskat, niinkuin synnyttäjän tuskat; minua huimaa, niin etten kuule, kauhistuttaa, niin etten näe.'),
(1687004,58,23,21,4,'Minun sydämeni värisee, kauhu peljästyttää minut. Ikävöimäni iltahämärän se muuttaa minulle vavistukseksi.'),
(1687005,58,23,21,5,'Pöytä katetaan, matto levitetään, syödään, juodaan. Nouskaa, te ruhtinaat, voidelkaa kilvet.'),
(1687006,58,23,21,6,'Sillä näin on Herra minulle sanonut: "Mene, aseta tähystäjä; hän ilmoittakoon, mitä näkee.'),
(1687007,58,23,21,7,'Ja kun hän näkee jonon ratsastajia parittain, jonon aaseja, jonon kameleja, niin kuunnelkoon tarkasti, hyvin tarkasti."'),
(1687008,58,23,21,8,'Ja hän huusi kuin leijona: "Tähystyspaikalla, Herra, minä seison alati, päivät pitkät, pysyn vartiopaikallani kaiket yöt.'),
(1687009,58,23,21,9,'Ja katso, tuolla tulee jonossa miehiä, parivaljakoita." Ja hän lausui sanoen: "Kukistunut, kukistunut on Baabel, ja kaikki sen jumalain kuvat hän on murskannut maahan".'),
(1687010,58,23,21,10,'Maahan puitu kansani, puimatantereella poljettuni! Mitä olen kuullut Herralta Sebaotilta, Israelin Jumalalta, sen minä teille ilmoitan.'),
(1687011,58,23,21,11,'Ennustus Duumasta. Minulle huudetaan Seiristä: "Vartija, mikä hetki yöstä on? Vartija, mikä hetki yöstä on?"'),
(1687012,58,23,21,12,'Vartija vastaa: "Aamu on tullut, mutta silti on yö. Jos vielä kyselette, niin kyselkää; tulkaa uudelleen."'),
(1687013,58,23,21,13,'Ennustus Arabiaa vastaan. Yöpykää Arabian viidakoissa, dedanilaiset matkueet.'),
(1687014,58,23,21,14,'Menkää vastaan, viekää vettä janoaville. Teeman maan asukkaat ottavat pakolaiset vastaan, leipää tariten.'),
(1687015,58,23,21,15,'Sillä he ovat miekkoja paossa, paljastettua miekkaa, jännitettyä jousta ja sodan tuimuutta paossa.'),
(1687016,58,23,21,16,'Sillä näin on Herra minulle sanonut: Vielä vuosi - sellainen kuin on palkkalaisen vuosi - niin kaikki Keedarin kunnia on kadonnut,'),
(1687017,58,23,21,17,'ja Keedarin urhojen jousiluvun jäännös on oleva vähäinen. Sillä Herra, Israelin Jumala, on puhunut.'),
(1687018,58,23,22,1,'Ennustus Näkylaaksosta. Mikä sinun on, kun sinä kaikkinesi katoille nouset,'),
(1687019,58,23,22,2,'sinä humuavainen, pauhaava kaupunki, sinä remuava kylä? Surmattusi eivät ole miekan surmaamia, eivät sotaan kuolleita.'),
(1687020,58,23,22,3,'Kaikki sinun päämiehesi yhdessä pakenivat, joutuivat vangiksi, jousta vailla; keitä ikinä sinun omiasi tavattiin, ne vangittiin kaikki tyynni, kuinka kauas pakenivatkin.'),
(1687021,58,23,22,4,'Sentähden minä sanon: "Kääntäkää katseenne minusta pois: minä itken katkerasti; älkää tunkeilko minua lohduttamaan, kun tytär, minun kansani, tuhoutuu".'),
(1687022,58,23,22,5,'Sillä hämmingin, hävityksen ja häiriön päivän on Herra, Herra Sebaot, pitävä Näkylaaksossa. Muurit murrettiin, vuorille kohosi huuto.'),
(1687023,58,23,22,6,'Eelam nosti viinen, tullen vaunuineen, väkineen ja ratsumiehineen, ja Kiir paljasti kilven.'),
(1687024,58,23,22,7,'Ihanimmat laaksosi täyttyivät vaunuista, ratsumiehet asettuivat asemiin portin eteen.'),
(1687025,58,23,22,8,'Hän riisui Juudalta verhon, ja sinä päivänä sinä loit katseesi Metsätalon asevarastoon.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687026,58,23,22,9,'Te huomasitte monta repeämää Daavidin kaupungin muurissa ja kokositte vedet Alalammikkoon;'),
(1687027,58,23,22,10,'te luitte Jerusalemin talot ja hajotitte taloja vahvistaaksenne muurin,'),
(1687028,58,23,22,11,'ja te teitte molempien muurien välille paikan, johon Vanhan lammikon vedet koottiin. Mutta hänen puoleensa te ette katsoneet, joka tämän tuotti, häntä te ette nähneet, joka tämän kauan sitten valmisti.'),
(1687029,58,23,22,12,'Ja sinä päivänä Herra, Herra Sebaot, kutsui itkuun ja valitukseen, pään paljaaksi ajamaan ja säkkiin vyöttäytymään.'),
(1687030,58,23,22,13,'Mutta katso: on ilo ja riemu, raavaitten tappaminen ja lammasten teurastus, lihan syönti ja viinin juonti! "Syökäämme ja juokaamme, sillä huomenna me kuolemme."'),
(1687031,58,23,22,14,'Niin kuului minun korviini Herran Sebaotin ilmoitus: "Totisesti, ei tämä teidän syntinne tule sovitetuksi, ei kuolemaanne saakka, sanoo Herra, Herra Sebaot".'),
(1687032,58,23,22,15,'Näin sanoo Herra, Herra Sebaot: Mene tuon huoneenhaltijan tykö, Sebnan tykö, joka on linnan päällikkönä.'),
(1687033,58,23,22,16,'"Mitä sinulla täällä on asiaa, ja keitä sinulla täällä on, kun tänne itsellesi haudan hakkautat, hakkautat hautasi korkeuteen, kallioon itsellesi asunnon koverrat?"'),
(1687034,58,23,22,17,'Katso, Herra heittää sinua, mies, rajusti: hän kouraisee sinut kokoon,'),
(1687035,58,23,22,18,'kääräisee sinut keräksi ja paiskaa pallona menemään maahan, jossa on laajuutta joka suuntaan. Sinne sinä kuolet, ja sinne jäävät sinun kunniavaunusi, sinä herrasi huoneen häpeä.'),
(1687036,58,23,22,19,'Minä syöksen sinut pois paikastasi; hän kukistaa sinut asemastasi.'),
(1687037,58,23,22,20,'Mutta sinä päivänä minä kutsun palvelijani Eljakimin, Hilkian pojan,'),
(1687038,58,23,22,21,'ja puetan hänen yllensä sinun ihokkaasi, vyötän hänet sinun vyölläsi ja panen sinun valtasi hänen käteensä, niin että hän on oleva isänä Jerusalemin asukkaille ja Juudan suvulle.'),
(1687039,58,23,22,22,'Ja minä panen Daavidin huoneen avaimen hänen olallensa; ja hän avaa, eikä kukaan sulje, ja hän sulkee, eikä kukaan avaa.'),
(1687040,58,23,22,23,'Minä lyön hänet vaarnaksi vahvaan paikkaan, ja hän tulee kunniaistuimeksi isänsä suvulle.'),
(1687041,58,23,22,24,'Hänen varaansa ripustautuu hänen isänsä suvun kaikki paljous, vesat ja versot, kaikki pienet astiat, maljat ja ruukut kaikki.'),
(1687042,58,23,22,25,'Sinä päivänä, sanoo Herra Sebaot, pettää vahvaan paikkaan lyöty vaarna, se katkeaa ja putoaa, ja kuorma, joka oli sen varassa, särkyy. Sillä Herra on puhunut.'),
(1687043,58,23,23,1,'Ennustus Tyyrosta. Valittakaa, te Tarsiin-laivat, sillä se on hävitetty talottomaksi, käymättömäksi; kittiläisten maasta he saivat tämän tiedon.'),
(1687044,58,23,23,2,'Mykistykää, te rantamaan asukkaat! Siidonin kauppamiehet, merenkulkijat, täyttivät sinut.'),
(1687045,58,23,23,3,'Ja suuria vesiä kulki Siihorin siemen, Niilivirran vilja; se oli Tyyron sato, ja siitä tuli kansojen kauppatavara.'),
(1687046,58,23,23,4,'Häpeä, Siidon, sillä näin sanoo meri, meren linnoitus: "En ole kivuissa ollut, en ole synnyttänyt, en nuorukaisia kasvattanut, en neitoja vartuttanut".'),
(1687047,58,23,23,5,'Kun tämä kuullaan Egyptissä, niin vavistaan Tyyron kuulumisia.'),
(1687048,58,23,23,6,'Menkää Tarsiiseen; valittakaa, te rantamaan asukkaat.'),
(1687049,58,23,23,7,'Onko tämä teidän remuava kaupunkinne, jonka alku on hamasta muinaisajasta, jonka jalat kuljettivat sen kauas muukalaisena asumaan?'),
(1687050,58,23,23,8,'Kuka on tämän päättänyt Tyyron osalle, kruunujen jakelijan, jonka kauppamiehet olivat ruhtinaita, kauppiaat maanmainioita?'),
(1687051,58,23,23,9,'Herra Sebaot on sen päättänyt, häväistäkseen kaiken koreuden korskan, saattaakseen kaikki maanmainiot halveksituiksi.'),
(1687052,58,23,23,10,'Tulvi yli maasi, tytär Tarsis, niinkuin Niilivirta; ei ole patoa enää.'),
(1687053,58,23,23,11,'Hän on ojentanut kätensä meren yli, järkyttänyt valtakunnat. Herra on antanut käskyn Kanaania vastaan, että sen linnoitukset hävitettäköön.'),
(1687054,58,23,23,12,'Hän sanoo: "Älä enää ilakoitse, sinä häväisty neitsyt, tytär Siidon. Nouse, mene kittiläisten maahan; et sinä sielläkään saa levätä.'),
(1687055,58,23,23,13,'Katso, kaldealaisten maa, kansa, jota ei ollut enää olemassa, jonka Assur oli valmistanut erämaan eläimille, - ne pystyttävät vartiotorninsa, ne kukistavat sen palatsit, tekevät sen raunioiksi.'),
(1687056,58,23,23,14,'Valittakaa, te Tarsiin-laivat, sillä hävitetty on teidän linnoituksenne."'),
(1687057,58,23,23,15,'Ja siihen aikaan Tyyro unhotetaan seitsemäksikymmeneksi vuodeksi, jotka ovat kuin saman kuninkaan aikaa. Seitsemänkymmenen vuoden kuluttua käy Tyyron, niinkuin porton laulussa sanotaan:'),
(1687058,58,23,23,16,'"Ota kantele, kierrä kaupunkia, sinä unhotettu portto; soita kauniisti, laula vireästi, että sinut muistettaisiin!"'),
(1687059,58,23,23,17,'Ja seitsemänkymmenen vuoden kuluttua Herra katsoo Tyyron puoleen, ja se pääsee jälleen portonpalkoilleen ja tekee huorin kaikkien maan valtakuntain kanssa, mitä maan päällä on.'),
(1687060,58,23,23,18,'Mutta sen voitto ja palkka on oleva Herralle pyhitetty; ei sitä koota eikä talleteta, vaan sen voitto on tuleva niille, jotka Herran edessä asuvat, runsaaksi ravinnoksi ja jaloksi vaatetukseksi.'),
(1687061,58,23,24,1,'Katso, Herra tekee maan tyhjäksi ja autioksi, mullistaa sen muodon ja hajottaa sen asukkaat.'),
(1687062,58,23,24,2,'Ja niinkuin kansan käy, niin papinkin, niinkuin orjan, niin hänen herransa, niinkuin orjattaren, niin hänen emäntänsä, niinkuin ostajan, niin myyjän, niinkuin lainanottajan, niin lainanantajan, niinkuin velallisen, niin velkojankin.'),
(1687063,58,23,24,3,'Maa tyhjentämällä tyhjennetään ja ryöstämällä ryöstetään. Sillä Herra on tämän sanan puhunut.'),
(1687064,58,23,24,4,'Maa murehtii ja lakastuu, maanpiiri nääntyy ja lakastuu; kansan ylhäiset maassa nääntyvät.'),
(1687065,58,23,24,5,'Maa on saastunut asukkaittensa alla, sillä he ovat rikkoneet lait, muuttaneet käskyt, hyljänneet iankaikkisen liiton.'),
(1687066,58,23,24,6,'Sentähden kirous kalvaa maata, ja sen asukkaat syystänsä kärsivät; sentähden maan asukkaat kuumuudesta korventuvat, ja vähän jää ihmisiä jäljelle.'),
(1687067,58,23,24,7,'Viini murehtii, viiniköynnös kuihtuu, kaikki ilomieliset huokaavat.'),
(1687068,58,23,24,8,'Loppunut on vaskirumpujen riemu, lakannut remuavaisten melu, loppunut kanteleitten riemu.'),
(1687069,58,23,24,9,'Ei laulaen viiniä juoda, väkijuoma käy karvaaksi juojillensa.'),
(1687070,58,23,24,10,'Kukistettu on autio kaupunki, joka talo teljetty, sisään pääsemätön.'),
(1687071,58,23,24,11,'Viinistä on kaduilla valitus, kaikki ilo on mennyt mailleen, riemu maasta paennut.'),
(1687072,58,23,24,12,'Jäljellä on kaupungissa hävitys, portti on pirstaleiksi lyöty.'),
(1687073,58,23,24,13,'Sillä niin on käyvä maan päällä, kansojen keskuudessa, kuin öljypuuta karistettaessa, kuin jälkikorjuussa, viininkorjuun päätyttyä.'),
(1687074,58,23,24,14,'Ne korottavat äänensä ja riemuitsevat, ne huutavat mereltä päin Herran valtasuuruutta:'),
(1687075,58,23,24,15,'"Sentähden kunnioittakaa Herraa valon mailla, ja meren saarilla Herran, Israelin Jumalan, nimeä".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687076,58,23,24,16,'Maan äärestä kuulemme ylistysvirret: "Ihana on vanhurskaan osa!" Mutta minä sanon: "Riutumus, riutumus on minun osani, voi minua: ryöstäjät ryöstävät, raastaen ryöstäjät ryöstävät!"'),
(1687077,58,23,24,17,'Kauhu ja kuoppa ja paula on edessäsi, sinä maan asukas.'),
(1687078,58,23,24,18,'Joka pakenee kauhun ääntä, se putoaa kuoppaan, ja joka kuopasta nousee, se puuttuu paulaan. Sillä korkeuden akkunat aukenevat ja maan perustukset järkkyvät.'),
(1687079,58,23,24,19,'Maa murskaksi musertuu, maa halkee ja hajoaa, maa horjuu ja huojuu.'),
(1687080,58,23,24,20,'Maa hoippuu ja hoipertelee niinkuin juopunut, huojuu niinkuin lehvämaja. Raskaana painaa sitä sen rikkomus, se kaatuu eikä enää nouse.'),
(1687081,58,23,24,21,'Sinä päivänä Herra kostaa korkeuden sotajoukolle korkeudessa ja maan kuninkaille maan päällä.'),
(1687082,58,23,24,22,'Heidät kootaan sidottuina vankikuoppaan ja suljetaan vankeuteen; pitkän ajan kuluttua heitä etsiskellään.'),
(1687083,58,23,24,23,'Ja kuu punastuu, ja aurinko häpeää, sillä Herra Sebaot on kuningas Siionin vuorella ja Jerusalemissa, ja hänen vanhintensa edessä loistaa kirkkaus.'),
(1687084,58,23,25,1,'Herra, sinä olet minun Jumalani; minä kunnioitan sinua, kiitän sinun nimeäsi, sillä sinä olet tehnyt ihmeitä, sinun aivoituksesi kaukaisilta päiviltä ovat todet ja vakaat.'),
(1687085,58,23,25,2,'Sillä sinä olet tehnyt kaupungin kiviroukkioksi, varustetun kaupungin raunioiksi; muukalaisten linna on kadonnut kaupunkien luvusta, ei sitä ikinä enää rakenneta.'),
(1687086,58,23,25,3,'Sentähden sinua kunnioittaa väkevä kansa, väkivaltaisten pakanain kaupunki sinua pelkää.'),
(1687087,58,23,25,4,'Sillä sinä olit turvana vaivaiselle, turvana köyhälle hänen ahdingossansa, suojana rankkasateelta, varjona helteeltä; sillä väkivaltaisten kiukku on kuin rankkasade seinää vastaan.'),
(1687088,58,23,25,5,'Niinkuin helteen kuivassa maassa, niin sinä vaimensit muukalaisten melun. Niinkuin helle pilven varjossa vaipuu väkivaltaisten voittolaulu.'),
(1687089,58,23,25,6,'Ja Herra Sebaot laittaa kaikille kansoille tällä vuorella pidot rasvasta, pidot voimaviinistä, ydinrasvasta, puhtaasta voimaviinistä.'),
(1687090,58,23,25,7,'Ja hän hävittää tällä vuorella verhon, joka verhoaa kaikki kansat, ja peiton, joka peittää kaikki kansakunnat.'),
(1687091,58,23,25,8,'Hän hävittää kuoleman ainiaaksi, ja Herra, Herra pyyhkii kyyneleet kaikkien kasvoilta ja ottaa pois kansansa häväistyksen kaikesta maasta. Sillä Herra on puhunut.'),
(1687092,58,23,25,9,'Ja sinä päivänä sanotaan: "Katso, tämä on meidän Jumalamme, jota me odotimme meitä pelastamaan; tämä on Herra, jota me odotimme: iloitkaamme ja riemuitkaamme pelastuksesta, jonka hän toi".'),
(1687093,58,23,25,10,'Sillä Herran käsi lepää tällä vuorella. Mutta Mooab tallataan siihen paikkaansa, niinkuin oljet tallautuvat lantaveteen.'),
(1687094,58,23,25,11,'Ja hän haroo siinä käsiään, niinkuin uija haroo uidessansa, mutta Herra painaa alas hänen ylpeytensä ynnä hänen kättensä rimpuilut.'),
(1687095,58,23,25,12,'Sinun korkeitten muuriesi varustukset hän kukistaa, painaa alas, syöksee maahan, tomuun asti.'),
(1687096,58,23,26,1,'Sinä päivänä lauletaan Juudan maassa tämä laulu: "Meillä on vahva kaupunki, pelastuksen hän asettaa muuriksi ja varustukseksi.'),
(1687097,58,23,26,2,'Avatkaa portit vanhurskaan kansan käydä sisälle, joka uskollisena pysyy.'),
(1687098,58,23,26,3,'Vakaamieliselle sinä talletat rauhan, rauhan, sillä hän turvaa sinuun.'),
(1687099,58,23,26,4,'Turvatkaa Herraan ainiaan, sillä Herra, Herra on iankaikkinen kallio.'),
(1687100,58,23,26,5,'Sillä hän on kukistanut korkealla asuvaiset, ylhäisen kaupungin, hän painoi sen alas, painoi maan tasalle, syöksi sen tomuun asti.'),
(1687101,58,23,26,6,'Sitä tallaa jalka, kurjan jalat, vaivaisten askeleet.'),
(1687102,58,23,26,7,'Vanhurskaan polku on suora, sinä teet vanhurskaan tien tasaiseksi.'),
(1687103,58,23,26,8,'Niin, sinun tuomioittesi tiellä me odotamme sinua, Herra; sinun nimeäsi ja sinun muistoasi sielu ikävöitsee.'),
(1687104,58,23,26,9,'Minun sieluni ikävöitsee sinua yöllä, minun henkeni sisimmässäni etsii sinua varhain; sillä kun sinun tuomiosi kohtaavat maata, oppivat maanpiirin asukkaat vanhurskautta.'),
(1687105,58,23,26,10,'Jos jumalaton saa armon, ei hän opi vanhurskautta; oikeuden maassa hän tekee vääryyttä eikä näe Herran korkeutta.'),
(1687106,58,23,26,11,'Herra, sinun kätesi on kohotettu, mutta he eivät sitä näe. He saakoot häpeäksensä nähdä sinun kiivautesi kansan puolesta; kuluttakoon heidät tuli, joka sinun vihollisesi kuluttaa.'),
(1687107,58,23,26,12,'Herra, sinä saatat meille rauhan, sillä myös kaikki meidän tekomme olet sinä tehnyt.'),
(1687108,58,23,26,13,'Herra, meidän Jumalamme, meitä ovat vallinneet muut herrat, et sinä; sinua yksin me ylistämme, sinun nimeäsi.'),
(1687109,58,23,26,14,'Kuolleet eivät virkoa eloon, vainajat eivät nouse: niin sinä olet heille kostanut, tuhonnut heidät ja hävittänyt kaiken heidän muistonsa.'),
(1687110,58,23,26,15,'Sinä olet lisännyt kansan, Herra, olet lisännyt kansan, olet kunniasi näyttänyt, olet laajentanut kaikki maan rajat.'),
(1687111,58,23,26,16,'Herra, ahdistuksessa he etsivät sinua, vuodattivat hiljaisia rukouksia, kun sinä heitä kuritit.'),
(1687112,58,23,26,17,'Niinkuin raskas vaimo, joka on synnyttämäisillään, vääntelehtii ja huutaa kivuissansa, niin me olimme sinun edessäsi, Herra.'),
(1687113,58,23,26,18,'Me olimme raskaina, vääntelehdimme, mutta oli niinkuin olisimme synnyttäneet tuulta: emme saaneet aikaan pelastusta maalle, maanpiirin asukkaat eivät ilmoille päässeet.'),
(1687114,58,23,26,19,'Mutta sinun kuolleesi virkoavat eloon, minun ruumiini nousevat ylös. Herätkää ja riemuitkaa, te jotka tomussa lepäätte, sillä sinun kasteesi on valkeuksien kaste, ja maa tuo vainajat ilmoille.'),
(1687115,58,23,26,20,'Mene, kansani, kammioihisi ja sulje ovet jälkeesi, lymyä hetkinen, kunnes viha on ohitse mennyt.'),
(1687116,58,23,26,21,'Sillä katso, Herra lähtee asuinsijastaan kostamaan maan asukkaille heidän pahat tekonsa, ja maa paljastaa verivelkansa eikä surmattujansa enää peitä."'),
(1687117,58,23,27,1,'Sinä päivänä Herra kostaa kovalla, suurella ja väkevällä miekallansa Leviatanille, kiitävälle käärmeelle, ja Leviatanille, kiemurtelevalle käärmeelle, ja tappaa lohikäärmeen, joka on meressä.'),
(1687118,58,23,27,2,'Sinä päivänä sanotaan: "On viinitarha, tulisen viinin tarha; laulakaa siitä:'),
(1687119,58,23,27,3,'''Minä, Herra, olen sen vartija, minä kastelen sitä hetkestä hetkeen; minä vartioitsen sitä öin ja päivin, ettei sitä mikään vahingoita.'),
(1687120,58,23,27,4,'Vihaa minulla ei ole; olisipa vain orjantappuroita ja ohdakkeita, niiden kimppuun minä kävisin sodalla ja polttaisin ne kaikki tyynni -'),
(1687121,58,23,27,5,'kaikki, jotka eivät antaudu minun turviini, eivät tee rauhaa minun kanssani, tee rauhaa minun kanssani.''"'),
(1687122,58,23,27,6,'Tulevina aikoina juurtuu Jaakob, Israel kukkii ja kukoistaa ja täyttää maanpiirin hedelmällänsä.'),
(1687123,58,23,27,7,'Löikö hän sitä, niinkuin sen lyöjät lyötiin, tapettiinko se, niinkuin sen tappajat tapettiin?'),
(1687124,58,23,27,8,'Karkoittamalla sen, lähettämällä sen pois sinä sitä rankaisit. Hän pyyhkäisi sen pois kovalla myrskyllänsä itätuulen päivänä.'),
(1687125,58,23,27,9,'Sentähden sovitetaan Jaakobin pahat teot sillä, ja se on hänen syntiensä poistamisen täysi hedelmä, että hän tekee kaikki alttarikivet rikottujen kalkkikivien kaltaisiksi: eivät kohoa enää asera-karsikot eivätkä auringonpatsaat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687126,58,23,27,10,'Sillä varustettu kaupunki on autio, se on hyljätty maja, jätetty tyhjäksi kuin erämaa. Siellä vasikat käyvät laitumella, siellä makailevat ja kaluavat sieltä vesat kaikki.'),
(1687127,58,23,27,11,'Ja kun oksat kuivuvat, niin ne taitetaan; vaimot tulevat ja tekevät niillä tulta. Sillä se ei ole ymmärtäväistä kansaa; sentähden sen tekijä ei sitä armahda, sen Luoja ei sitä sääli.'),
(1687128,58,23,27,12,'Sinä päivänä Herra karistaa hedelmät maahan, Eufrat-virrasta aina Egyptin puroon asti, ja teidät, te israelilaiset, poimitaan talteen yksitellen.'),
(1687129,58,23,27,13,'Sinä päivänä puhalletaan suureen pasunaan, ja Assurin maahan hävinneet ja Egyptin maahan karkoitetut tulevat ja kumartavat Herraa Pyhällä vuorella Jerusalemissa.'),
(1687130,58,23,28,1,'Voi Efraimin juopuneitten ylvästä kruunua ja sen kunnian loisteen kuihtuvata kukkaa, joka on kukkulan laella, viinistä päihtyneitten lihavan laakson keskellä!'),
(1687131,58,23,28,2,'Katso, Herralta tulee hän, joka on väkevä ja voimallinen, niinkuin raesade, rajumyrsky. Niinkuin rankkasade, väkeväin tulvavetten kuohu, hän voimalla maahan kaataa.'),
(1687132,58,23,28,3,'Jalkoihin tallataan Efraimin juopuneitten ylväs kruunu.'),
(1687133,58,23,28,4,'Ja sen kunnian loisteen kuihtuvan kukan, joka on kukkulan laella, lihavan laakson keskellä, käy niinkuin varhaisviikunan ennen kesää: kuka vain sen näkee, tuskin se on hänen kourassaan, niin hän sen jo nielaisee.'),
(1687134,58,23,28,5,'Sinä päivänä Herra Sebaot on oleva loistava kruunu ja kunnian seppele kansansa jäännökselle'),
(1687135,58,23,28,6,'ja oikeuden henki sille, joka oikeutta istuu, ja väkevyys niille, jotka torjuvat hyökkäyksen takaisin porttia kohden.'),
(1687136,58,23,28,7,'Ja nämäkin horjuvat viinistä ja hoipertelevat väkijuomasta. Väkijuomasta horjuu pappi ja profeetta; he ovat sekaisin viinistä, hoipertelevat väkijuomasta. He horjuvat näyissä, huojuvat tuomioissa.'),
(1687137,58,23,28,8,'Sillä täynnä oksennusta ja saastaa ovat kaikki pöydät - ei puhdasta paikkaa!'),
(1687138,58,23,28,9,'"Keitähän tuokin luulee taitoon neuvovansa, keitä saarnalla opettavansa? Olemmeko me vasta maidolta vieroitettuja, äidin rinnoilta otettuja?'),
(1687139,58,23,28,10,'Käsky käskyn päälle, käsky käskyn päälle, läksy läksyn päälle, läksy läksyn päälle, milloin siellä, milloin täällä!" -'),
(1687140,58,23,28,11,'Niin, sopertavin huulin ja vieraalla kielellä hän on puhuva tälle kansalle,'),
(1687141,58,23,28,12,'hän, joka on sanonut heille: "Tässä on lepo; antakaa väsyneen levätä, tässä on levähdyspaikka". Mutta he eivät ole tahtoneet kuulla.'),
(1687142,58,23,28,13,'Niinpä on Herran sana oleva heille: "Käsky käskyn päälle, käsky käskyn päälle, läksy läksyn päälle, läksy läksyn päälle, milloin siellä, milloin täällä", niin että he kulkiessaan kaatuvat selälleen ja ruhjoutuvat, että heidät kiedotaan ja vangitaan.'),
(1687143,58,23,28,14,'Sentähden kuulkaa Herran sana, te pilkkaajat, te jotka hallitsette tätä kansaa Jerusalemissa.'),
(1687144,58,23,28,15,'Koska te sanotte: "Me olemme tehneet liiton kuoleman kanssa ja tuonelan kanssa sopimuksen; tulkoon vitsaus kuin tulva, ei se meitä saavuta, sillä me olemme tehneet valheen turvaksemme ja piiloutuneet petokseen" -'),
(1687145,58,23,28,16,'sentähden, näin sanoo Herra, Herra: Katso, minä lasken Siioniin peruskiven, koetellun kiven, kalliin kulmakiven, lujasti perustetun; joka uskoo, se ei pakene.'),
(1687146,58,23,28,17,'Ja minä panen oikeuden mittanuoraksi ja vanhurskauden vaa''aksi, ja rakeet hävittävät valheturvan, ja vedet huuhtovat pois piilopaikan.'),
(1687147,58,23,28,18,'Teidän liittonne kuoleman kanssa pyyhkäistään pois, ja teidän sopimuksenne tuonelan kanssa ei kestä; kun vitsaus tulee niinkuin tulva, niin se teidät maahan tallaa.'),
(1687148,58,23,28,19,'Niin usein kuin se tulee, tempaa se teidät valtaansa, sillä aamu aamulta se tulee, tulee päivällä ja yöllä: totisesti, kauhuksi on tämän saarnan opetus.'),
(1687149,58,23,28,20,'Sillä vuode on oleva liian lyhyt ojentautua ja peitto liian kaita kääriytyä.'),
(1687150,58,23,28,21,'Sillä Herra nousee niinkuin Perasimin vuorella, hän kiivastuu niinkuin Gibeonin laaksossa tehdäkseen työnsä, oudon työnsä, ja toimittaakseen tekonsa, kumman tekonsa.'),
(1687151,58,23,28,22,'Älkää siis pilkatko, etteivät teidän siteenne vielä kiristyisi; sillä Herralta Sebaotilta minä olen kuullut hävitys- ja tuomiopäätöksen, joka on kohtaava kaikkea maata.'),
(1687152,58,23,28,23,'Kuunnelkaa ja kuulkaa minun ääntäni, tarkatkaa ja kuulkaa minun sanojani.'),
(1687153,58,23,28,24,'Ainako kyntäjä vain kyntää, kun olisi kylväminen, ainako vakoaa ja äestää maatansa?'),
(1687154,58,23,28,25,'Eikö niin: kun hän on tasoittanut sen pinnan, hän kylvää mustaa kuminaa, sirottelee höystekuminaa, panee nisunjyvät riviin, ohran omaan paikkaansa ja kolmitahkoista vehnää vierelle?'),
(1687155,58,23,28,26,'Hänen Jumalansa on neuvonut hänelle oikean tavan ja opettaa häntä.'),
(1687156,58,23,28,27,'Sillä ei mustaa kuminaa puida puimaäkeellä eikä puimajyrän tela pyöri höystekuminan yli, vaan musta kumina lyödään irti sauvalla ja höystekumina vitsalla.'),
(1687157,58,23,28,28,'Puidaankos leipävilja murskaksi? Ei sitä kukaan iankaiken pui eikä aina aja sen päällitse puimajyrällään ja hevosillaan; ei sitä murskaksi puida.'),
(1687158,58,23,28,29,'Tämäkin on tullut Herralta Sebaotilta; hänen neuvonsa on ihmeellinen ja ymmärryksensä ylen suuri.'),
(1687159,58,23,29,1,'Voi Arielia, Arielia, kaupunkia, jonne Daavid asetti leirinsä! Liittäkää vuosi vuoteen, kiertäkööt juhlat kiertonsa,'),
(1687160,58,23,29,2,'niin minä ahdistan Arielia, ja se on oleva täynnä valitusta ja vaikerrusta, oleva minulle kuin Jumalan uhriliesi.'),
(1687161,58,23,29,3,'Minä asetan leirini yltympäri sinua vastaan ja saarran sinut vartiostoilla ja luon vallit sinua vastaan.'),
(1687162,58,23,29,4,'Silloin sinä puhut maasta matalalta, sanasi tulevat vaimeina tomusta, sinä uikutat kuin vainajahenki maasta, puheesi tulee supisten tomusta.'),
(1687163,58,23,29,5,'Mutta sinun vainolaistesi lauma on oleva niinkuin hieno pöly, ja väkivaltaisten lauma niinkuin lentävät akanat, ja tämä tapahtuu äkkiä, silmänräpäyksessä:'),
(1687164,58,23,29,6,'Herra Sebaot etsiskelee sinua ukkosenjylinässä ja maanjäristyksessä, kovassa pauhinassa, myrskyssä ja rajuilmassa, kuluttavan tulen liekissä.'),
(1687165,58,23,29,7,'Niinkuin yöllinen uninäky on oleva kansain lauma, joka sotii Arielia vastaan, kaikki, jotka sotivat sitä ja sen varustuksia vastaan ja sitä ahdistavat.'),
(1687166,58,23,29,8,'Niinkuin nälkäinen on unissaan syövinänsä, mutta herää hiuka sydämessä, ja niinkuin janoinen on unissaan juovinansa, mutta herää, ja katso, hän on nääntynyt ja himoitsee juoda, niin on oleva kaikki kansain lauma, joka sotii Siionin vuorta vastaan.'),
(1687167,58,23,29,9,'Hämmästykää ja ihmetelkää, tuijottakaa sokeiksi itsenne ja sokeiksi jääkää! He ovat juovuksissa, vaikkeivät viinistä, hoipertelevat, vaikkeivät väkijuomasta.'),
(1687168,58,23,29,10,'Sillä Herra on vuodattanut teidän päällenne raskaan unen hengen ja sulkenut teidän silmänne - profeettanne, ja peittänyt teidän päänne - näkijänne.'),
(1687169,58,23,29,11,'Niin on kaikki ilmoitus teille niinkuin lukitun kirjan sanat; jos se annetaan kirjantaitavalle ja sanotaan: "Lue tämä", niin hän vastaa: "Ei voi, sillä se on lukittu",'),
(1687170,58,23,29,12,'ja jos kirja annetaan kirjantaitamattomalle ja sanotaan: "Lue tämä", niin hän vastaa: "En osaa lukea".'),
(1687171,58,23,29,13,'Ja Herra sanoi: Koska tämä kansa lähestyy minua suullaan ja kunnioittaa minua huulillaan, mutta pitää sydämensä minusta kaukana, ja koska heidän jumalanpelkonsa on vain opittuja ihmiskäskyjä,'),
(1687172,58,23,29,14,'sentähden, katso, minä vielä teen tälle kansalle kummia tekoja - kummia ja ihmeitä, ja sen viisaitten viisaus häviää, ja sen ymmärtäväisten ymmärrys katoaa.'),
(1687173,58,23,29,15,'Voi niitä, jotka syvälle kätkevät hankkeensa Herralta, joiden teot tapahtuvat pimeässä ja jotka sanovat: "Kuka meitä näkee, kuka meistä tietää?"'),
(1687174,58,23,29,16,'Voi mielettömyyttänne! Onko savi savenvalajan veroinen? Ja sanooko työ tekijästään: "Ei hän ole minua tehnyt", tai sanooko kuva kuvaajastaan: "Ei hän mitään ymmärrä"?'),
(1687175,58,23,29,17,'Vain lyhyt hetki enää, niin Libanon muuttuu puutarhaksi, ja puutarha on metsän veroinen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687176,58,23,29,18,'Sinä päivänä kuurot kuulevat kirjan sanat, ja sokeiden silmät näkevät vapaina synkeästä pimeydestä.'),
(1687177,58,23,29,19,'Nöyrät saavat yhä uutta iloa Herrassa, ja ihmisistä köyhimmätkin riemuitsevat Israelin Pyhästä.'),
(1687178,58,23,29,20,'Sillä väkivaltaisista on tullut loppu, pilkkaajat ovat hävinneet, ja kaikki vääryyteen valppaat ovat tuhotut,'),
(1687179,58,23,29,21,'ne, jotka sanallansa langettavat ihmisiä syyhyn ja virittävät pauloja sille, joka oikeutta puolustaa portissa, ja verukkeilla syyttömän asian vääräksi vääntävät.'),
(1687180,58,23,29,22,'Sentähden Herra, joka Aabrahamin vapahti, sanoo Jaakobin heimolle näin: Ei Jaakob enää joudu häpeään, eivätkä hänen kasvonsa enää kalpene.'),
(1687181,58,23,29,23,'Sillä kun hän näkee, kun hänen lapsensa näkevät keskellänsä minun kätteni työn, niin he pyhittävät minun nimeni, pitävät pyhänä Jaakobin Pyhän ja peljästyvät Israelin Jumalaa.'),
(1687182,58,23,29,24,'Ja hengessään eksyväiset käsittävät ymmärryksen, ja napisevaiset ottavat oppia.'),
(1687183,58,23,30,1,'Voi uppiniskaisia lapsia, sanoo Herra, jotka pitävät neuvoa, mikä ei ole minusta, ja hierovat liittoa ilman minun henkeäni, kooten syntiä synnin päälle;'),
(1687184,58,23,30,2,'jotka menevät Egyptiin, kysymättä minulta, turvautuakseen faraon turviin ja etsiäkseen suojaa Egyptin varjossa!'),
(1687185,58,23,30,3,'Faraon turva koituu teille häpeäksi ja suojan etsiminen Egyptin varjosta häväistykseksi.'),
(1687186,58,23,30,4,'Sillä vaikka hänen ruhtinaansa ovat Sooanissa ja hänen sanansaattajansa saapuneet Haanekseen asti,'),
(1687187,58,23,30,5,'joutuvat kaikki häpeään kansan tähden, josta heillä ei ole hyötyä - ei apua, ei hyötyä, vaan häpeätä ja pilkkaa.'),
(1687188,58,23,30,6,'Ennustus Eteläisen maan Behemotia vastaan. Halki ahdingon ja ahdistuksen maan, halki naarasleijonan ja jalopeuran maan, kyykäärmeen ja lentävän käärmeen maan he kuljettavat aasinvarsojen selässä rikkautensa ja kamelien kyttyrällä aarteensa kansan tykö, josta ei hyötyä ole.'),
(1687189,58,23,30,7,'Egyptin apu on turha ja tyhjä; sentähden minä annan sille nimen: "Rahab, joka ei pääse paikaltansa".'),
(1687190,58,23,30,8,'Mene siis nyt ja kirjoita se tauluun heidän läsnäollessaan ja piirrä se kirjaan, että se säilyisi tuleviin aikoihin, ainiaan, iankaikkisesti.'),
(1687191,58,23,30,9,'Sillä he ovat niskoitteleva kansa, ovat vilpillisiä lapsia, lapsia, jotka eivät tahdo kuulla Herran lakia,'),
(1687192,58,23,30,10,'jotka sanovat näkijöille: "Älkää nähkö", ja ennustajille: "Älkää ennustako meille tosia, puhukaa meille mieluisia, ennustakaa silmänlumeita.'),
(1687193,58,23,30,11,'Poiketkaa tieltä, väistykää polulta; viekää pois silmistämme Israelin Pyhä."'),
(1687194,58,23,30,12,'Sentähden, näin sanoo Israelin Pyhä: Koska te halveksitte tätä sanaa ja luotatte väkivaltaan ja vääryyteen ja siihen turvaudutte,'),
(1687195,58,23,30,13,'niin tämä synti on oleva kuin repeämä korkeassa muurissa, joka uhkaa sortua ja pullistuu; se särkyy äkkiä, yhtäkkiä.'),
(1687196,58,23,30,14,'Se särkyy, niinkuin särkyy savenvalajan astia, joka lyödään rikki säälimättä, niin ettei sen sirpaleista löydy palasta, millä ottaa tulta liedestä tai ammentaa vettä altaasta.'),
(1687197,58,23,30,15,'Sillä näin sanoo Herra, Herra, Israelin Pyhä: Kääntymällä ja pysymällä hiljaa te pelastutte, rauhallisuus ja luottamus on teidän väkevyytenne; mutta te ette tahtoneet,'),
(1687198,58,23,30,16,'vaan sanoitte: "Ei! Hevosilla me tahdomme kiitää" - niinpä saatte kiitää pakoon. "Nopean selässä me tahdomme ratsastaa" - niinpä ovat vainoojanne nopeat.'),
(1687199,58,23,30,17,'Tuhat pakenee yhden uhkaa; viiden uhkaa te pakenette, kunnes se, mikä teistä jää, on kuin merkkipuu vuoren huipulla, kuin lipputanko kukkulalla.'),
(1687200,58,23,30,18,'Sentähden Herra odottaa, että voisi olla teille armollinen, sentähden hän nousee armahtaaksensa teitä; sillä Herra on oikeuden Jumala. Autuaita kaikki, jotka häntä odottavat!'),
(1687201,58,23,30,19,'Sinä kansa, joka asut Siionissa, Jerusalemissa, älä itke! Hän on sinulle totisesti armollinen, kun apua huudat; sen kuullessaan hän vastaa sinulle kohta.'),
(1687202,58,23,30,20,'Vaikka Herra antaa teille hädän leipää ja ahdistuksen vettä, niin ei sinun opettajasi sitten enää kätkeydy, vaan sinun silmäsi saavat nähdä sinun opettajasi.'),
(1687203,58,23,30,21,'Ja sinun korvasi kuulevat takaasi tämän sanan, milloin poikkeatte oikealle tai vasemmalle: "Tässä on tie, sitä käykää".'),
(1687204,58,23,30,22,'Silloin sinä havaitset saastaiseksi veistettyjen jumalankuviesi hopeapäällystyksen ja valettujen jumalankuviesi kultakuoren; sinä viskaat ne pois kuin inhotuksen, sinä sanot niille: "Ulos!"'),
(1687205,58,23,30,23,'Niin hän antaa sateen sinun siemenellesi, jonka maahan kylvät, ja maan sadosta leivän, joka on oleva mehevä ja lihava, ja sinun karjasi on sinä päivänä käyvä laajalla laitumella.'),
(1687206,58,23,30,24,'Härät ja aasinvarsat, jotka peltotyötä tekevät, syövät suolaista rehuviljaa, joka on viskattu hangolla ja viskimellä.'),
(1687207,58,23,30,25,'Ja kaikilla korkeilla vuorilla ja kaikilla ylhäisillä kukkuloilla on oleva puroja, vesivirtoja, suuren surmaamisen päivänä, tornien sortuessa.'),
(1687208,58,23,30,26,'Ja kuun valo on oleva kuin auringon valo, ja auringon valo on oleva seitsenkertainen, oleva niinkuin seitsemän päivän valo, sinä päivänä, jona Herra sitoo kansansa vammat ja parantaa siihen isketyt haavat.'),
(1687209,58,23,30,27,'Katso, Herran nimi tulee kaukaa, hänen vihansa leimuaa, ja sankka savu tupruaa; hänen huulensa ovat täynnä hirmuisuutta, ja hänen kielensä on kuin kuluttava tuli.'),
(1687210,58,23,30,28,'Hänen hengityksensä on kuin virta, joka tulvii ja ulottuu kaulaan asti; se seuloo kansakuntia turmion seulassa ja panee eksyttäväiset suitset kansojen suupieliin.'),
(1687211,58,23,30,29,'Silloin te veisaatte niinkuin yöllä, kun pyhä juhla alkaa, ja sydämenne riemuitsee niinkuin sen, joka huilujen soidessa astuu vaeltaen Herran vuorelle, Israelin kallion tykö.'),
(1687212,58,23,30,30,'Herra antaa kuulla äänensä voiman ja nähdä käsivartensa laskeutuvan alas vihan tuimuudessa ja kuluttavan tulen liekissä, pilvenpurkuna, rankkasateena ja raekivinä.'),
(1687213,58,23,30,31,'Sillä Herran äänestä peljästyy Assur. Hän lyö vitsalla.'),
(1687214,58,23,30,32,'Ja jokaisella sallimuksen sauvan iskulla, jonka Herra häneen satuttaa, soivat vaskirummut ja kanteleet, ja hän sotii häntä vastaan, sotii kättä heiluttaen.'),
(1687215,58,23,30,33,'Sillä aikoja sitten on polttopaikka valmistettu; kuninkaallekin se on varattu. Syvä ja leveä on sen liesi, tulta ja polttopuita paljon. Herran henkäys kuin tulikivi-virta sytyttää sen.'),
(1687216,58,23,31,1,'Voi niitä, jotka menevät alas Egyptiin apua etsimään ja turvautuvat hevosiin, luottavat sotavaunuihin, koska niitä on paljon, ja ratsumiehiin, koska niitten luku on ylen suuri, mutta eivät katso Israelin Pyhään, eivät kysy neuvoa Herralta.'),
(1687217,58,23,31,2,'Mutta myös hän on viisas, ja hän tuottaa onnettomuuden; hän ei peruuta sanojansa, vaan nousee pahantekijäin sukua vastaan ja väärintekijäin apuuntuloa vastaan.'),
(1687218,58,23,31,3,'Egypti on ihminen eikä Jumala, ja heidän hevosensa ovat lihaa eivätkä henkeä. Kun Herra ojentaa kätensä, suistuu auttaja, ja autettava kaatuu, ja yhdessä he kumpikin hukkuvat.'),
(1687219,58,23,31,4,'Sillä näin on Herra minulle sanonut: Niinkuin leijona, nuori leijona, murisee saaliinsa ääressä, kun sitä vastaan hälytetään paimenten parvi, eikä peljästy heidän huutoansa, ei huoli heidän hälinästään, niin Herra Sebaot on astuva alas sotimaan Siionin vuorella ja sen kukkulalla.'),
(1687220,58,23,31,5,'Niinkuin liitelevät linnut, niin varjelee Herra Sebaot Jerusalemia - varjelee ja pelastaa, säästää ja vapahtaa.'),
(1687221,58,23,31,6,'Palatkaa, te israelilaiset, hänen tykönsä, josta olette niin kauas luopuneet.'),
(1687222,58,23,31,7,'Sillä sinä päivänä jokainen hylkää hopeaiset ja kultaiset epäjumalansa, jotka kätenne ovat tehneet teille synniksi.'),
(1687223,58,23,31,8,'Ja Assur kaatuu miekkaan, joka ei ole miehen, ja hänet syö miekka, joka ei ole ihmisen; hän pakenee miekkaa, ja hänen nuorukaisensa joutuvat työorjuuteen.'),
(1687224,58,23,31,9,'Hänen kallionsa kukistuu kauhusta, ja hänen ruhtinaansa säikkyvät lipun luota pakoon, sanoo Herra, jonka tuli on Siionissa ja pätsi Jerusalemissa.'),
(1687225,58,23,32,1,'Katso, kuningas on hallitseva vanhurskaudessa, ja valtiaat vallitsevat oikeuden mukaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687226,58,23,32,2,'Silloin on jokainen heistä oleva turvana tuulelta ja suojana rankkasateelta, oleva kuin vesipurot kuivassa maassa, kuin korkean kallion varjo nääntyvässä maassa.'),
(1687227,58,23,32,3,'Silloin eivät näkevien silmät ole soaistut, ja kuulevien korvat kuulevat tarkkaan.'),
(1687228,58,23,32,4,'Ajattelemattomien sydän käsittää taidon, ja änkyttäväin kieli puhuu sujuvasti ja selkeästi.'),
(1687229,58,23,32,5,'Ei houkkaa enää kutsuta jaloksi, eikä petollista enää sanota yleväksi.'),
(1687230,58,23,32,6,'Sillä houkka puhuu houkan lailla, ja hänen sydämensä hankkii turmiota, ja niin hän harjoittaa riettautta ja puhuu eksyttäväisesti Herrasta, jättää tyhjäksi nälkäisen sielun ja janoavaisen juomaa vaille.'),
(1687231,58,23,32,7,'Ja pahat ovat petollisen aseet, hän miettii ilkitöitä, tuhotakseen kurjat valheen sanoilla, vaikka köyhä kuinka oikeata asiaa puhuisi.'),
(1687232,58,23,32,8,'Mutta jalo jaloja miettii ja jaloudessa lujana pysyy.'),
(1687233,58,23,32,9,'Nouskaa, te suruttomat naiset, kuulkaa minun ääntäni; te huolettomat tyttäret, tarkatkaa minun sanojani.'),
(1687234,58,23,32,10,'Vielä vuosi, ja päiviä päälle, niin vapisette, te huolettomat; sillä silloin on viininkorjuusta tullut loppu, hedelmänkorjuuta ei tule.'),
(1687235,58,23,32,11,'Kauhistukaa, te suruttomat, vaviskaa, te huolettomat, riisuutukaa, paljastukaa, vyöttäkää säkki lanteillenne.'),
(1687236,58,23,32,12,'Silloin valitetaan ja lyödään rintoihin ihanien peltojen tähden ja hedelmällisten viiniköynnösten tähden,'),
(1687237,58,23,32,13,'minun kansani maan tähden, joka kasvaa orjantappuraa ja ohdaketta, remuavan kaupungin kaikkien iloisten talojen tähden.'),
(1687238,58,23,32,14,'Sillä palatsi on hyljätty, kaupungin kohina lakannut, Oofel ja vartiotorni ovat jääneet luoliksi iankaikkisesti, villiaasien iloksi ja laumojen laitumeksi.'),
(1687239,58,23,32,15,'Näin on hamaan siihen asti, kunnes meidän päällemme vuodatetaan Henki korkeudesta. Silloin erämaa muuttuu puutarhaksi,'),
(1687240,58,23,32,16,'ja puutarha on metsän veroinen. Ja erämaassa asuu oikeus, ja puutarhassa majailee vanhurskaus.'),
(1687241,58,23,32,17,'Silloin vanhurskauden hedelmä on rauha, vanhurskauden vaikutus lepo ja turvallisuus iankaikkisesti.'),
(1687242,58,23,32,18,'Ja minun kansani asuu rauhan majoissa, turvallisissa asunnoissa, huolettomissa lepopaikoissa.'),
(1687243,58,23,32,19,'Mutta raesade tulee, metsä kaatuu, ja kaupunki alennetaan alhaiseksi.'),
(1687244,58,23,32,20,'Onnelliset te, jotka kylvätte kaikkien vetten vierille ja laskette härän ja aasin jalat valtoimina kulkemaan!'),
(1687245,58,23,33,1,'Voi sinua hävittäjää, joka itse olet hävittämättä, sinua ryöstäjää, jota ei kenkään ole ryöstänyt! Kun olet loppuun asti hävittänyt, hävitetään sinut, kun olet ryöstösi ryöstänyt, ryöstetään sinut.'),
(1687246,58,23,33,2,'Herra, armahda meitä, sinua me odotamme. Ole näitten käsivarsi joka aamu, ole meidän apumme hädän aikana.'),
(1687247,58,23,33,3,'Kansat pakenevat sinun jylinäsi ääntä; kun sinä nouset, hajoavat kansakunnat.'),
(1687248,58,23,33,4,'Teidän saaliinne viedään, niinkuin tuhosirkat vievät; niinkuin hyppysirkat hyökkäävät, niin sen kimppuun hyökätään.'),
(1687249,58,23,33,5,'Herra on korkea, sillä hän asuu korkeudessa. Hän täyttää Siionin oikeudella ja vanhurskaudella.'),
(1687250,58,23,33,6,'Ja hän on sinun aikojesi vakuus, avun runsaus, viisaus ja ymmärrys; Herran pelko on oleva Siionin aarre.'),
(1687251,58,23,33,7,'Katso, sankarit huutavat ulkona, rauhan sanansaattajat itkevät katkerasti.'),
(1687252,58,23,33,8,'Tiet ovat autioina, polulta on kulkija poissa: hän on rikkonut liiton, ylenkatsonut kaupungit, ei ole ihmistä minäkään pitänyt.'),
(1687253,58,23,33,9,'Maa murehtii ja nääntyy, Libanon kuihtuu häpeästä, Saaron on aromaaksi tullut, Baasan ja Karmel varistavat lehtensä.'),
(1687254,58,23,33,10,'Nyt minä nousen, sanoo Herra, nyt minä itseni korotan, nyt minä kohoan korkealle.'),
(1687255,58,23,33,11,'Olkia te kannatte kohdussanne, akanoita synnytätte; teidän kiukkunne on tuli, joka kuluttaa teidät.'),
(1687256,58,23,33,12,'Ja kansat poltetaan kuin kalkki, kuin katkotut orjantappurat, jotka tulessa palavat.'),
(1687257,58,23,33,13,'Kuulkaa, te kaukaiset, mitä minä olen tehnyt; te lähelläolevat, tuntekaa minun voimani.'),
(1687258,58,23,33,14,'Syntiset Siionissa peljästyvät, vavistus valtaa jumalattomat: "Kuka meistä voi asua kuluttavassa tulessa, kuka asua iankaikkisessa hehkussa?"'),
(1687259,58,23,33,15,'Joka vanhurskaudessa vaeltaa ja puhuu sitä, mikä oikein on, joka halveksii väärää voittoa, jonka käsi torjuu lahjukset luotaan, joka tukkii korvansa kuulemasta veritöitä ja sulkee silmänsä näkemästä pahaa,'),
(1687260,58,23,33,16,'hän on asuva kukkuloilla, kalliolinnat ovat hänen turvansa; hänelle annetaan hänen leipänsä, eikä vesi häneltä ehdy.'),
(1687261,58,23,33,17,'Sinun silmäsi saavat katsoa kuningasta hänen ihanuudessaan, saavat nähdä avaran maan.'),
(1687262,58,23,33,18,'Sinun sydämesi muistelee kauhuja: missä on nyt veronlaskija, missä punnitsija, missä tornien lukija?'),
(1687263,58,23,33,19,'Et näe enää sitä röyhkeätä kansaa, kansaa, jolla on outo, käsittämätön puhe, jonka sopertavaa kieltä ei kukaan ymmärrä.'),
(1687264,58,23,33,20,'Katso Siionia, juhliemme kaupunkia. Sinun silmäsi näkevät Jerusalemin, rauhaisan asuinsijan, telttamajan, jota ei muuteta, jonka vaarnoja ei ikinä reväistä irti, jonka köysistä ei yhtäkään katkaista.'),
(1687265,58,23,33,21,'Sillä voimallinen on meillä siellä Herra, siellä on joet, on virrat, leveät rannasta toiseen, joita ei kulje soutualus, joiden poikki ei pääse uljas laiva.'),
(1687266,58,23,33,22,'Sillä Herra on meidän tuomarimme, Herra on johdattajamme, Herra on meidän kuninkaamme; hän pelastaa meidät.'),
(1687267,58,23,33,23,'Nyt ovat köytesi höltyneet, eivät pidä mastoa kannassaan kiinni, eivät vedä lippua liehumaan. Mutta silloin jaetaan riistosaalista runsaasti, rammatkin ryöstävät ja raastavat.'),
(1687268,58,23,33,24,'Eikä yksikään asukas sano: "Minä olen vaivanalainen". Kansa, joka siellä asuu, on saanut syntinsä anteeksi.'),
(1687269,58,23,34,1,'Astukaa esiin, te kansat, ja kuulkaa; te kansakunnat, tarkatkaa. Kuulkoon maa ja kaikki, mitä siinä on, maanpiiri ja kaikki, mikä siitä kasvaa.'),
(1687270,58,23,34,2,'Sillä Herra on vihastunut kaikkiin kansoihin ja kiivastunut kaikkiin heidän joukkoihinsa; hän on vihkinyt heidät tuhon omiksi, jättänyt heidät teurastettaviksi.'),
(1687271,58,23,34,3,'Heidän surmattunsa viskataan pois, ja niitten raadoista nousee löyhkä, ja vuoret valuvat heidän vertansa.'),
(1687272,58,23,34,4,'Kaikki taivaan joukot menehtyvät, taivas kääritään kokoon niinkuin kirja, ja kaikki sen joukot varisevat alas, niinkuin lehdet varisevat viinipuusta, niinkuin viikunapuusta raakaleet.'),
(1687273,58,23,34,5,'Sillä minun miekkani taivaassa on juopunut vimmaan; katso, se iskee alas Edomiin, tuomioksi kansalle, jonka minä olen vihkinyt tuhoon.'),
(1687274,58,23,34,6,'Herran miekka on verta täynnä, rasvaa tiukkuva, karitsain ja kauristen verta, oinasten munuaisrasvaa. Sillä Herralla on uhri Bosrassa, suuri teurastus Edomin maassa.'),
(1687275,58,23,34,7,'Villihärkiä kaatuu yhteen joukkoon, mullikoita härkien mukana. Heidän maansa juopuu verestä, ja heidän multansa tiukkuu rasvaa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687276,58,23,34,8,'Sillä Herralla on koston päivä, maksun vuosi Siionin asian puolesta.'),
(1687277,58,23,34,9,'Edomin purot muuttuvat pieksi ja sen multa tulikiveksi; sen maa tulee palavaksi pieksi.'),
(1687278,58,23,34,10,'Ei sammu se yöllä eikä päivällä, iäti nousee siitä savu; se on oleva raunioina polvesta polveen, ei kulje siellä kukaan, iankaikkisesta iankaikkiseen.'),
(1687279,58,23,34,11,'Sen perivät pelikaanit ja tuonenkurjet, kissapöllöt ja kaarneet asuvat siellä; ja hän vetää sen ylitse autiuden mittanuoran ja tyhjyyden luotilangan.'),
(1687280,58,23,34,12,'Ei ole siellä enää ylimyksiä huutamassa ketään kuninkaaksi, kaikki sen ruhtinaat ovat poissa.'),
(1687281,58,23,34,13,'Ja sen palatsit kasvavat orjantappuroita, sen linnat polttiaisia ja ohdakkeita; siitä tulee aavikkosutten asunto, kamelikurkien tyyssija.'),
(1687282,58,23,34,14,'Siellä erämaan ulvojat ja ulisijat yhtyvät, metsänpeikot toisiansa tapaavat. Siellä yksin öinen syöjätär saa rauhan ja löytää lepopaikan.'),
(1687283,58,23,34,15,'Siellä nuolikäärme pesii ja laskee munansa, kuorii ne ja kiertyy kerälle pimentoonsa. Sinne haarahaukatkin kokoontuvat yhteen.'),
(1687284,58,23,34,16,'Etsikää Herran kirjasta ja lukekaa: ei yhtäkään näistä ole puuttuva, ei yksikään toistansa kaipaava. - "Sillä minun suuni on niin käskenyt." - Hänen henkensä on ne yhteen koonnut.'),
(1687285,58,23,34,17,'Hän on heittänyt arpaa niitten kesken, ja hänen kätensä on sen niille mittanuoralla jakanut; ne perivät sen ikiajoiksi, asuvat siellä polvesta polveen.'),
(1687286,58,23,35,1,'Erämaa ja hietikko iloitsee, aromaa riemuitsee ja kukoistaa kuin lilja.'),
(1687287,58,23,35,2,'Se kauniisti kukoistaa ja iloitsee ilolla ja riemulla. Sille annetaan Libanonin kunnia, Karmelin ja Saaronin ihanuus. He saavat nähdä Herran kunnian, meidän Jumalamme ihanuuden.'),
(1687288,58,23,35,3,'Vahvistakaa hervonneet kädet, voimistakaa horjuvat polvet.'),
(1687289,58,23,35,4,'Sanokaa hätääntyneille sydämille: "Olkaa lujat, älkää peljätkö. Katso, teidän Jumalanne! Kosto tulee, Jumalan rangaistus. Hän tulee ja pelastaa teidät."'),
(1687290,58,23,35,5,'Silloin avautuvat sokeain silmät ja kuurojen korvat aukenevat.'),
(1687291,58,23,35,6,'Silloin rampa hyppii niinkuin peura ja mykän kieli riemuun ratkeaa; sillä vedet puhkeavat erämaahan ja aromaahan purot.'),
(1687292,58,23,35,7,'Hehkuva hiekka tulee lammikoiksi ja kuiva maa vesilähteiksi. Aavikkosutten asunnossa, missä ne makasivat, kasvaa ruoho ynnä ruoko ja kaisla.'),
(1687293,58,23,35,8,'Ja siellä on oleva valtatie, ja sen nimi on "pyhä tie": sitä ei kulje saastainen; se on heitä itseänsä varten. Joka sitä tietä kulkee, ei eksy - eivät hullutkaan.'),
(1687294,58,23,35,9,'Ei ole siellä leijonaa, ei nouse sinne raateleva peto; ei sellaista siellä tavata: lunastetut sitä kulkevat.'),
(1687295,58,23,35,10,'Niin Herran vapahdetut palajavat ja tulevat Siioniin riemuiten, päänsä päällä iankaikkinen ilo. Riemu ja ilo saavuttavat heidät, mutta murhe ja huokaus pakenevat.'),
(1687296,58,23,36,1,'Kuningas Hiskian neljäntenätoista hallitusvuotena hyökkäsi Sanherib, Assurin kuningas, kaikkien Juudan varustettujen kaupunkien kimppuun ja valloitti ne.'),
(1687297,58,23,36,2,'Ja Assurin kuningas lähetti Laakiista Rabsaken suuren sotajoukon kanssa kuningas Hiskiaa vastaan Jerusalemiin, ja hän pysähtyi Ylälammikon vesijohdolle, joka on Vanuttajankedon tien varrella.'),
(1687298,58,23,36,3,'Ja Eljakim, Hilkian poika, joka oli palatsin päällikkönä, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, menivät hänen luoksensa.'),
(1687299,58,23,36,4,'Ja Rabsake sanoi heille: "Sanokaa Hiskialle: Näin sanoo suurkuningas, Assurin kuningas: ''Mitä on tuo luottamus, mikä sinulla on?'),
(1687300,58,23,36,5,'Minä sanon: pelkkää huulten puhetta on moinen neuvo ja voima sodankäyntiin. Keneen sinä oikein luotat, kun kapinoit minua vastaan?'),
(1687301,58,23,36,6,'Katso, sinä luotat Egyptiin, tuohon särkyneeseen ruokosauvaan, joka tunkeutuu sen käteen, joka siihen nojaa, ja lävistää sen. Sellainen on farao, Egyptin kuningas, kaikille, jotka häneen luottavat.'),
(1687302,58,23,36,7,'Vai sanotko ehkä minulle: Me luotamme Herraan, meidän Jumalaamme? Mutta eikö hän ole se, jonka uhrikukkulat ja alttarit Hiskia poisti, kun hän sanoi Juudalle ja Jerusalemille: Tämän alttarin edessä on teidän kumartaen rukoiltava?'''),
(1687303,58,23,36,8,'Mutta lyö nyt vetoa minun herrani, Assurin kuninkaan, kanssa: minä annan sinulle kaksi tuhatta hevosta, jos sinä voit hankkia niille ratsastajat.'),
(1687304,58,23,36,9,'Kuinka sinä sitten voisit torjua ainoankaan käskynhaltijan, ainoankaan minun herrani vähimmän palvelijan, hyökkäyksen? Ja sinä vain luotat Egyptiin, sen vaunuihin ja ratsumiehiin.'),
(1687305,58,23,36,10,'Olenko minä siis Herran sallimatta hyökännyt tähän maahan hävittämään sitä? Herra itse on sanonut minulle: ''Hyökkää tähän maahan ja hävitä se''."'),
(1687306,58,23,36,11,'Niin Eljakim, Sebna ja Jooah sanoivat Rabsakelle: "Puhu palvelijoillesi araminkieltä, sillä me ymmärrämme sitä; älä puhu meille juudankieltä kansan kuullen, jota on muurilla".'),
(1687307,58,23,36,12,'Mutta Rabsake vastasi: "Onko minun herrani lähettänyt minut puhumaan näitä sanoja sinun herrallesi ja sinulle? Eikö juuri niille miehille, jotka istuvat muurilla ja joutuvat teidän kanssanne syömään omaa likaansa ja juomaan omaa vettänsä?"'),
(1687308,58,23,36,13,'Sitten Rabsake astui esiin, huusi kovalla äänellä juudankielellä ja sanoi: "Kuulkaa suurkuninkaan, Assurin kuninkaan, sanoja.'),
(1687309,58,23,36,14,'Näin sanoo kuningas: ''Älkää antako Hiskian pettää itseänne, sillä hän ei voi teitä pelastaa.'),
(1687310,58,23,36,15,'Älköön Hiskia saako teitä luottamaan Herraan, kun hän sanoo: Herra on varmasti pelastava meidät; ei tätä kaupunkia anneta Assurin kuninkaan käsiin.'),
(1687311,58,23,36,16,'Älkää kuulko Hiskiaa.'' Sillä Assurin kuningas sanoo näin: ''Tehkää sovinto minun kanssani ja antautukaa minulle, niin saatte syödä kukin viinipuustanne ja viikunapuustanne ja juoda kukin kaivostanne,'),
(1687312,58,23,36,17,'kunnes minä tulen ja vien teidät maahan, joka on teidän maanne kaltainen, vilja- ja viinimaahan, leivän ja viinitarhojen maahan.'),
(1687313,58,23,36,18,'Älköön vain Hiskia saako vietellä teitä, sanoessaan: Herra pelastaa meidät. Onko muidenkaan kansojen jumalista kukaan pelastanut maatansa Assurin kuninkaan käsistä?'),
(1687314,58,23,36,19,'Missä ovat Hamatin ja Arpadin jumalat? Missä ovat Sefarvaimin jumalat? Ovatko ne pelastaneet Samariaa minun käsistäni?'),
(1687315,58,23,36,20,'Kuka näiden maiden kaikista jumalista on pelastanut maansa minun käsistäni? Kuinka sitten Herra pelastaisi Jerusalemin minun käsistäni?''"'),
(1687316,58,23,36,21,'Mutta he olivat vaiti eivätkä vastanneet hänelle mitään, sillä kuningas oli käskenyt niin ja sanonut: "Älkää vastatko hänelle".'),
(1687317,58,23,36,22,'Sitten palatsin päällikkö Eljakim, Hilkian poika, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, tulivat Hiskian luo vaatteet reväistyinä ja kertoivat hänelle, mitä Rabsake oli sanonut.'),
(1687318,58,23,37,1,'Kun kuningas Hiskia sen kuuli, repäisi hän vaatteensa, pukeutui säkkiin ja meni Herran temppeliin.'),
(1687319,58,23,37,2,'Ja hän lähetti palatsin päällikön Eljakimin ja kirjuri Sebnan sekä pappein vanhimmat, säkkeihin puettuina, profeetta Jesajan, Aamoksen pojan, tykö.'),
(1687320,58,23,37,3,'Ja he sanoivat hänelle: "Näin sanoo Hiskia: ''Hädän, kurituksen ja häväistyksen päivä on tämä päivä, sillä lapset ovat tulleet kohdun suulle saakka, mutta ei ole voimaa synnyttää.'),
(1687321,58,23,37,4,'Ehkä Herra, sinun Jumalasi, kuulee Rabsaken sanat, joilla hänen Herransa, Assurin kuningas, on lähettänyt hänet herjaamaan elävää Jumalaa, ja rankaisee häntä näistä sanoista, jotka Herra, sinun Jumalasi, on kuullut. Niin kohota nyt rukous jäännöksen puolesta, joka vielä on olemassa.''"'),
(1687322,58,23,37,5,'Kun kuningas Hiskian palvelijat tulivat Jesajan tykö,'),
(1687323,58,23,37,6,'sanoi Jesaja heille: "Sanokaa näin herrallenne: ''Näin sanoo Herra: Älä pelkää niitä sanoja, jotka olet kuullut ja joilla Assurin kuninkaan poikaset ovat häväisseet minua.'),
(1687324,58,23,37,7,'Katso, minä annan häneen mennä sellaisen hengen, että hän kuultuaan sanoman palajaa omaan maahansa; ja minä annan hänen kaatua miekkaan omassa maassansa.''"'),
(1687325,58,23,37,8,'Ja Rabsake kääntyi takaisin ja tapasi Assurin kuninkaan sotimassa Libnaa vastaan; sillä hän oli kuullut, että tämä oli lähtenyt Laakiista pois.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687326,58,23,37,9,'Mutta kun Sanherib kuuli Tirhakasta, Etiopian kuninkaasta, sanottavan: "Hän on lähtenyt liikkeelle sotiakseen sinua vastaan", niin hän sen kuultuaan lähetti sanansaattajat Hiskian tykö ja käski sanoa:'),
(1687327,58,23,37,10,'"Sanokaa näin Hiskialle, Juudan kuninkaalle: ''Älä anna Jumalasi, johon sinä luotat, pettää itseäsi äläkä ajattele: Jerusalem ei joudu Assurin kuninkaan käsiin.'),
(1687328,58,23,37,11,'Olethan kuullut, mitä Assurin kuninkaat ovat tehneet kaikille maille, kuinka he ovat vihkineet ne tuhon omiksi. Ja sinäkö pelastuisit!'),
(1687329,58,23,37,12,'Ovatko kansain jumalat pelastaneet niitä, jotka minun isäni ovat tuhonneet: Goosania, Harrania, Resefiä ja Telassarin edeniläisiä?'),
(1687330,58,23,37,13,'Missä on Hamatin kuningas ja Arpadin kuningas, Sefarvaimin kaupungin, Heenan ja Ivvan kuningas?''"'),
(1687331,58,23,37,14,'Kun Hiskia oli ottanut kirjeen sanansaattajilta ja lukenut sen, meni hän Herran temppeliin; ja Hiskia levitti sen Herran eteen.'),
(1687332,58,23,37,15,'Ja Hiskia rukoili Herraa ja sanoi:'),
(1687333,58,23,37,16,'"Herra Sebaot, Israelin Jumala, jonka valtaistuinta kerubit kannattavat, sinä yksin olet maan kaikkien valtakuntain Jumala; sinä olet tehnyt taivaan ja maan.'),
(1687334,58,23,37,17,'Herra, kallista korvasi ja kuule; Herra, avaa silmäsi ja katso. Kuule kaikki Sanheribin sanat, jotka hän lähetti herjatakseen elävää Jumalaa.'),
(1687335,58,23,37,18,'Se on totta, Herra, että Assurin kuninkaat ovat hävittäneet kaikki maat ja omankin maansa.'),
(1687336,58,23,37,19,'Ja he ovat heittäneet niiden jumalat tuleen; sillä ne eivät olleet jumalia, vaan ihmiskätten tekoa, puuta ja kiveä, ja sentähden he voivat hävittää ne.'),
(1687337,58,23,37,20,'Mutta pelasta nyt meidät, Herra, meidän Jumalamme, hänen käsistänsä, että kaikki maan valtakunnat tulisivat tietämään, että sinä, Herra, olet ainoa."'),
(1687338,58,23,37,21,'Niin Jesaja, Aamoksen poika, lähetti Hiskialle tämän sanan: "Näin sanoo Herra, Israelin Jumala: Koska sinä olet rukoillut minua avuksi Sanheribia, Assurin kuningasta, vastaan,'),
(1687339,58,23,37,22,'niin tämä on se sana, jonka Herra on puhunut hänestä: Neitsyt, tytär Siion, halveksii ja pilkkaa sinua; tytär Jerusalem nyökyttää ilkkuen päätänsä sinun jälkeesi.'),
(1687340,58,23,37,23,'Ketä olet herjannut ja häväissyt, ja ketä vastaan olet korottanut äänesi? Korkealle olet kohottanut silmäsi Israelin Pyhää vastaan.'),
(1687341,58,23,37,24,'Palvelijaisi kautta sinä herjasit Herraa ja sanoit: ''Monilla vaunuillani minä nousin vuorten harjalle, Libanonin ääriin saakka; minä hakkasin maahan sen korkeat setrit, sen parhaat kypressit ja tunkeuduin sen etäisimmälle harjalle, sen rehevimpään metsään;'),
(1687342,58,23,37,25,'minä kaivoin kaivoja ja join kuiviin vedet, ja jalkapohjallani minä kuivasin kaikki Egyptin virrat''.'),
(1687343,58,23,37,26,'Etkö ole kuullut: kauan sitten minä olen tätä valmistanut, muinaisuudesta saakka tätä aivoitellut! Nyt minä olen sen toteuttanut, ja niin sinä sait hävittää varustetut kaupungit autioiksi kiviroukkioiksi,'),
(1687344,58,23,37,27,'ja niiden asukkaat olivat voimattomat, he kauhistuivat ja joutuivat häpeään; heidän kävi niinkuin kedon ruohon ja niinkuin vihannan heinän, niinkuin katolla kasvavain kortten ja niinkuin laihon ennen oljelle tulemistaan.'),
(1687345,58,23,37,28,'Istuitpa sinä tai lähdit tai tulit, minä sen tiedän, niinkuin senkin, että sinä raivoat minua vastaan.'),
(1687346,58,23,37,29,'Koska sinä minua vastaan raivoat ja koska sinun ylpeytesi on tullut minun korviini, niin minä panen koukkuni sinun nenääsi ja suitseni sinun suuhusi ja vien sinut takaisin samaa tietä, jota tulitkin.'),
(1687347,58,23,37,30,'Ja tämä on oleva sinulle merkkinä: tänä vuonna syödään jälkikasvua ja toisena vuonna kesanto-aaluvaa, mutta kolmantena vuonna te kylväkää ja leikatkaa, istuttakaa viinitarhoja ja syökää niiden hedelmää.'),
(1687348,58,23,37,31,'Ja Juudan heimon pelastuneet, jotka ovat jäljelle jääneet, tekevät taas juurta alaspäin ja hedelmää ylöspäin.'),
(1687349,58,23,37,32,'Sillä Jerusalemista lähtee kasvamaan jäännös, pelastunut joukko Siionin vuorelta. Herran Sebaotin kiivaus on sen tekevä.'),
(1687350,58,23,37,33,'Sentähden, näin sanoo Herra Assurin kuninkaasta: Hän ei tule tähän kaupunkiin eikä siihen nuolta ammu, ei tuo sitä vastaan kilpeä eikä luo sitä vastaan vallia.'),
(1687351,58,23,37,34,'Samaa tietä, jota hän tuli, hän palajaa, ja tähän kaupunkiin hän ei tule, sanoo Herra.'),
(1687352,58,23,37,35,'Sillä minä varjelen tämän kaupungin ja pelastan sen itseni tähden ja palvelijani Daavidin tähden."'),
(1687353,58,23,37,36,'Niin Herran enkeli lähti ja löi Assurin leirissä sata kahdeksankymmentä viisi tuhatta miestä, ja kun noustiin aamulla varhain, niin katso, he olivat kaikki kuolleina ruumiina.'),
(1687354,58,23,37,37,'Silloin Sanherib, Assurin kuningas, lähti liikkeelle ja meni pois; hän palasi maahansa ja jäi Niiniveen.'),
(1687355,58,23,37,38,'Mutta kun hän oli kerran rukoilemassa jumalansa Nisrokin temppelissä, surmasivat hänen poikansa Adrammelek ja Sareser hänet miekalla; sitten he pakenivat Araratin maahan. Ja hänen poikansa Eesarhaddon tuli kuninkaaksi hänen sijaansa.'),
(1687356,58,23,38,1,'Niihin aikoihin sairastui Hiskia ja oli kuolemaisillaan; ja profeetta Jesaja, Aamoksen poika, tuli hänen tykönsä ja sanoi hänelle: "Näin sanoo Herra: Toimita talosi; sillä sinä kuolet etkä enää parane".'),
(1687357,58,23,38,2,'Niin Hiskia käänsi kasvonsa seinään päin ja rukoili Herraa'),
(1687358,58,23,38,3,'ja sanoi: "Oi Herra, muista, kuinka minä olen vaeltanut sinun edessäsi uskollisesti ja ehyellä sydämellä ja tehnyt sitä, mikä on hyvää sinun silmissäsi!" Ja Hiskia itki katkerasti.'),
(1687359,58,23,38,4,'Mutta Jesajalle tuli tämä Herran sana:'),
(1687360,58,23,38,5,'"Mene ja sano Hiskialle: ''Näin sanoo Herra, sinun isäsi Daavidin Jumala: Minä olen kuullut sinun rukouksesi, olen nähnyt sinun kyyneleesi. Katso, minä lisään sinulle ikää viisitoista vuotta;'),
(1687361,58,23,38,6,'ja minä pelastan sinut ja tämän kaupungin Assurin kuninkaan käsistä ja varjelen tätä kaupunkia.'),
(1687362,58,23,38,7,'Ja tämä on oleva sinulle merkkinä Herralta siitä, että Herra tekee, mitä on sanonut:'),
(1687363,58,23,38,8,'katso, minä annan aurinkokellon varjon siirtyä takaisin kymmenen astetta, jotka se jo on auringon mukana laskeutunut Aahaan aurinkokellossa.''" Ja aurinko siirtyi aurinkokellossa takaisin kymmenen astetta, jotka se jo oli laskeutunut.'),
(1687364,58,23,38,9,'Hiskian, Juudan kuninkaan, kirjoittama laulu, kun hän oli ollut sairaana ja toipunut taudistansa:'),
(1687365,58,23,38,10,'"Minä sanoin: Kesken rauhallisten päivieni minun on mentävä tuonelan porteista; jäljellä olevat vuoteni on minulta riistetty pois.'),
(1687366,58,23,38,11,'Minä sanoin: En saa minä enää nähdä Herraa, Herraa elävien maassa, en enää ihmisiä katsella manalan asukasten joukossa.'),
(1687367,58,23,38,12,'Minun majani puretaan ja viedään minulta pois niinkuin paimenen teltta; olen kutonut loppuun elämäni, niinkuin kankuri kankaansa, minut leikataan irti loimentutkaimista. Ennenkuin päivä yöksi muuttuu, sinä teet minusta lopun.'),
(1687368,58,23,38,13,'Minä viihdyttelin itseäni aamuun asti - niinkuin leijona hän murskaa kaikki minun luuni; ennenkuin päivä yöksi muuttuu, sinä teet minusta lopun.'),
(1687369,58,23,38,14,'Niinkuin pääskynen, niinkuin kurki minä kuikutan, minä kujerran kuin kyyhkynen; hiueten katsovat minun silmäni korkeuteen: Herra, minulla on ahdistus, puolusta minua.'),
(1687370,58,23,38,15,'Mitä nyt sanonkaan? Hän lupasi minulle ja täytti myös: minä vaellan hiljaisesti kaikki elämäni vuodet sieluni murheen tähden.'),
(1687371,58,23,38,16,'Herra, tämänkaltaiset ovat elämäksi, ja niissä on koko minun henkeni elämä. Sinä teet minut terveeksi; anna minun elää.'),
(1687372,58,23,38,17,'Katso, onneksi muuttui minulle katkera murhe: sinä rakastit minun sieluani, nostit sen kadotuksen kuopasta, sillä sinä heitit kaikki minun syntini selkäsi taa.'),
(1687373,58,23,38,18,'Sillä ei tuonela sinua kiitä, ei kuolema sinua ylistä; eivät hautaan vaipuneet pane sinun totuuteesi toivoansa.'),
(1687374,58,23,38,19,'Elävät, elävät sinua kiittävät, niinkuin minä tänä päivänä; isä ilmoittaa lapsillensa sinun totuutesi.'),
(1687375,58,23,38,20,'Herra on minun auttajani. Minun kanteleeni soittoja soittakaamme kaikkina elinpäivinämme Herran temppelissä."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687376,58,23,38,21,'Ja Jesaja käski tuoda viikunakakkua ja hautoa paisetta, että hän tulisi terveeksi.'),
(1687377,58,23,38,22,'Niin Hiskia sanoi: "Mikä on merkkinä siitä, että minä voin mennä Herran temppeliin?"'),
(1687378,58,23,39,1,'Siihen aikaan Merodak-Baladan, Baladanin poika, Baabelin kuningas, lähetti kirjeen ja lahjoja Hiskialle, kun oli kuullut hänen olleen sairaana ja parantuneen.'),
(1687379,58,23,39,2,'Ja Hiskia iloitsi lähettiläistä ja näytti heille varastohuoneensa, hopean ja kullan, hajuaineet ja kalliin öljyn ja koko asehuoneensa ja kaikki, mitä hänen aarrekammioissansa oli. Ei ollut mitään Hiskian talossa eikä koko hänen valtakunnassaan, mitä hän ei olisi heille näyttänyt.'),
(1687380,58,23,39,3,'Mutta profeetta Jesaja tuli kuningas Hiskian tykö ja sanoi hänelle: "Mitä nämä miehet ovat sanoneet, ja mistä he ovat tulleet sinun tykösi?" Hiskia vastasi: "He ovat tulleet minun tyköni kaukaisesta maasta, Baabelista".'),
(1687381,58,23,39,4,'Hän sanoi: "Mitä he ovat nähneet sinun talossasi?" Hiskia vastasi: "Kaiken, mitä talossani on, he ovat nähneet; aarrekammiossani ei ole mitään, mitä en olisi heille näyttänyt".'),
(1687382,58,23,39,5,'Niin Jesaja sanoi Hiskialle: "Kuule Herran Sebaotin sana:'),
(1687383,58,23,39,6,'Katso, päivät tulevat, jolloin kaikki, mitä sinun talossasi on ja mitä sinun isäsi ovat koonneet tähän päivään asti, viedään pois Baabeliin; ei mitään jää jäljelle, sanoo Herra.'),
(1687384,58,23,39,7,'Ja sinun omia poikiasi, jotka sinusta polveutuvat, jotka sinulle syntyvät, viedään hovipalvelijoiksi Baabelin kuninkaan palatsiin."'),
(1687385,58,23,39,8,'Hiskia sanoi Jesajalle: "Herran sana, jonka olet puhunut, on hyvä". Sillä hän ajatteli: "Onpahan rauha ja turvallisuus minun päivinäni".'),
(1687386,58,23,40,1,'"Lohduttakaa, lohduttakaa minun kansaani", sanoo teidän Jumalanne.'),
(1687387,58,23,40,2,'"Puhukaa suloisesti Jerusalemille ja julistakaa sille, että sen vaivanaika on päättynyt, että sen velka on sovitettu, sillä se on saanut Herran kädestä kaksinkertaisesti kaikista synneistänsä."'),
(1687388,58,23,40,3,'Huutavan ääni kuuluu: "Valmistakaa Herralle tie erämaahan, tehkää arolle tasaiset polut meidän Jumalallemme.'),
(1687389,58,23,40,4,'Kaikki laaksot korotettakoon, kaikki vuoret ja kukkulat alennettakoon; koleikot tulkoot tasangoksi ja kalliolouhut lakeaksi maaksi.'),
(1687390,58,23,40,5,'Herran kunnia ilmestyy: kaikki liha saa sen nähdä. Sillä Herran suu on puhunut."'),
(1687391,58,23,40,6,'Ääni sanoo: "Julista!" Toinen vastaa: "Mitä minun pitää julistaman?" Kaikki liha on kuin ruoho, ja kaikki sen kauneus kuin kedon kukkanen:'),
(1687392,58,23,40,7,'ruoho kuivuu, kukkanen lakastuu, kun Herran henkäys puhaltaa siihen. Totisesti, ruohoa on kansa.'),
(1687393,58,23,40,8,'Ruoho kuivuu, kukkanen lakastuu, mutta meidän Jumalamme sana pysyy iankaikkisesti.'),
(1687394,58,23,40,9,'Nouse korkealle vuorelle, Siion, sinä ilosanoman tuoja; korota voimakkaasti äänesi, Jerusalem, sinä ilosanoman tuoja. Korota, älä pelkää, sano Juudan kaupungeille: "Katso, teidän Jumalanne!"'),
(1687395,58,23,40,10,'Katso, Herra, Herra tulee voimallisena, hänen käsivartensa vallitsee. Katso, hänen palkkansa on hänen mukanansa, hänen työnsä ansio käy hänen edellänsä.'),
(1687396,58,23,40,11,'Niinkuin paimen hän kaitsee laumaansa, kokoaa karitsat käsivarrellensa ja kantaa niitä sylissään, johdattelee imettäviä lampaita.'),
(1687397,58,23,40,12,'Kuka on kourallaan mitannut vedet ja vaaksalla määrännyt taivaitten mitat? Kuka on kolmannesmittaan mahduttanut maan tomun, puntarilla punninnut vuoret, vaa''alla kukkulat?'),
(1687398,58,23,40,13,'Kuka on Herran Henkeä ohjannut, ollut hänen neuvonantajansa ja opettajansa?'),
(1687399,58,23,40,14,'Kenen kanssa hän on neuvotellut, joka olisi hänelle ymmärrystä antanut ja opettanut oikean polun, opettanut hänelle tiedon ja osoittanut hänelle ymmärryksen tien?'),
(1687400,58,23,40,15,'Katso, kansakunnat ovat kuin pisara vesisangon uurteessa, ovat kuin tomuhiukkanen vaa''assa. Katso, merensaaret hän nostaa kuin hiekkajyvän.'),
(1687401,58,23,40,16,'Ei Libanon riittäisi polttopuiksi eikä sen riista polttouhriksi.'),
(1687402,58,23,40,17,'Kaikki kansakunnat ovat niinkuin ei mitään hänen edessään, ne ovat hänelle kuin olematon ja tyhjä.'),
(1687403,58,23,40,18,'Keneenkä siis te vertaatte Jumalan, ja minkä muotoiseksi te hänet teette?'),
(1687404,58,23,40,19,'Jumalankuvanko? - Sen valaa valaja, ja kultaseppä kullalla päällystää, sepittää sille hopeaketjut.'),
(1687405,58,23,40,20,'Kenellä ei ole varaa sellaiseen antimeen, se valitsee puun, joka ei lahoa, hakee taitavan tekijän pystyttämään jumalankuvan, joka ei horju.'),
(1687406,58,23,40,21,'Ettekö te tiedä, ettekö kuule, eikö teille ole alusta asti ilmoitettu, ettekö ole maan perustuksista vaaria ottaneet?'),
(1687407,58,23,40,22,'Hän istuu korkealla maanpiirin päällä, kuin heinäsirkkoja ovat sen asukkaat; hän levittää taivaan niinkuin harson, pingoittaa sen niinkuin teltan asuttavaksi.'),
(1687408,58,23,40,23,'Hän tekee ruhtinaat olemattomiksi, saattaa maan tuomarit tyhjän veroisiksi.'),
(1687409,58,23,40,24,'Tuskin he ovat istutetut, tuskin kylvetyt, tuskin on heidän vartensa juurtunut maahan, niin hän puhaltaa heihin, ja he kuivettuvat; myrsky vie heidät kuin oljenkorret.'),
(1687410,58,23,40,25,'"Keneenkä siis te vertaatte minut, jonka kaltainen minä olisin", sanoo Pyhä.'),
(1687411,58,23,40,26,'Nostakaa silmänne korkeuteen ja katsokaa: kuka on nämä luonut? Hän, joka johdattaa esiin niitten joukot täysilukuisina, joka nimeltä kutsuu ne kaikki; suuri on hänen voimansa ja valtainen hänen väkensä: ei yksikään jää häneltä pois.'),
(1687412,58,23,40,27,'Miksi sinä, Jaakob, sanot ja sinä, Israel, puhut: "Minun tieni on Herralta salassa, minun oikeuteni on joutunut pois minun Jumalani huomasta"?'),
(1687413,58,23,40,28,'Etkö tiedä, etkö ole kuullut: Herra on iankaikkinen Jumala, joka on luonut maan ääret? Ei hän väsy eikä näänny, hänen ymmärryksensä on tutkimaton.'),
(1687414,58,23,40,29,'Hän antaa väsyneelle väkeä ja voimattomalle voimaa yltäkyllin.'),
(1687415,58,23,40,30,'Nuorukaiset väsyvät ja nääntyvät, nuoret miehet kompastuvat ja kaatuvat;'),
(1687416,58,23,40,31,'mutta ne, jotka Herraa odottavat, saavat uuden voiman, he kohottavat siipensä kuin kotkat. He juoksevat eivätkä näänny, he vaeltavat eivätkä väsy.'),
(1687417,58,23,41,1,'Vaietkaa minun edessäni, te merensaaret. Kansat verestäkööt voimansa, astukoot esiin ja puhukoot sitten; käykäämme oikeutta keskenämme.'),
(1687418,58,23,41,2,'Kuka herätti päivänkoiton maasta hänet, jota vanhurskaus seuraa joka askeleella? Kuka antaa kansat hänen valtaansa, kukistaa kuninkaat hänen jalkoihinsa? Kuka muuttaa heidän miekkansa tomuksi, heidän jousensa lentäviksi oljenkorsiksi?'),
(1687419,58,23,41,3,'Hän ajaa heitä takaa, samoaa vammatonna polkua, hänen jalkainsa ennen kulkematonta.'),
(1687420,58,23,41,4,'Kuka on tämän tehnyt ja toimittanut? Hän, joka alusta asti kutsuu sukupolvet esiin: minä, Herra, joka olen ensimmäinen ja viimeisten luona vielä sama.'),
(1687421,58,23,41,5,'Merensaaret näkivät sen ja peljästyivät, maan ääret vapisivat. He lähestyivät, he tulivat,'),
(1687422,58,23,41,6,'he auttoivat toinen toistaan ja sanoivat toisillensa: "Ole luja!"'),
(1687423,58,23,41,7,'Valaja rohkaisee kultaseppää, levyn vasaroitsija alasimen iskijää; hän sanoo juotoksesta: "Se on hyvä", ja vahvistaa sen nauloilla, niin ettei se horju.'),
(1687424,58,23,41,8,'Mutta sinä Israel, minun palvelijani, sinä Jaakob, jonka minä olen valinnut, Aabrahamin, minun ystäväni, siemen,'),
(1687425,58,23,41,9,'jonka minä olen ottanut maan ääristä ja kutsunut maan kaukaisimmilta periltä, jolle minä sanoin: "Sinä olet minun palvelijani, sinut minä olen valinnut enkä sinua halpana pitänyt",');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687426,58,23,41,10,'älä pelkää, sillä minä olen sinun kanssasi; älä arkana pälyile, sillä minä olen sinun Jumalasi; minä vahvistan sinua, minä autan sinua, minä tuen sinua vanhurskauteni oikealla kädellä.'),
(1687427,58,23,41,11,'Katso, häpeän ja pilkan saavat kaikki, jotka palavat vihasta sinua vastaan; tyhjiin raukeavat ja hukkuvat, jotka sinun kanssasi riitelevät.'),
(1687428,58,23,41,12,'Hakemallakaan et löydä niitä, jotka sinua vastaan taistelivat; tyhjiin raukeavat ja lopun saavat, jotka sinun kanssasi sotivat.'),
(1687429,58,23,41,13,'Sillä minä, Herra, sinun Jumalasi, tartun sinun oikeaan käteesi, minä sanon sinulle: "Älä pelkää, minä autan sinua".'),
(1687430,58,23,41,14,'Älä pelkää, Jaakob, sinä mato, sinä Israelin vähäinen väki: minä autan sinua, sanoo Herra, ja sinun lunastajasi on Israelin Pyhä.'),
(1687431,58,23,41,15,'Katso, minä panen sinut raastavaksi puimaäkeeksi, uudeksi, monihampaiseksi. Sinä puit ja rouhennat vuoret, muutat kukkulat akanoiksi;'),
(1687432,58,23,41,16,'sinä ne viskaat, ja tuuli ne vie ja myrsky ne hajottaa. Mutta sinä iloitset Herrassa, Israelin Pyhä on sinun kerskauksesi.'),
(1687433,58,23,41,17,'Kurjat ja köyhät etsivät vettä, eikä sitä ole; heidän kielensä kuivuu janosta. Mutta minä, Herra, kuulen heitä, minä, Israelin Jumala, en heitä hylkää.'),
(1687434,58,23,41,18,'Minä puhkaisen purot kalliokukkuloihin, lähteet laaksojen pohjiin; minä muutan erämaan vesilammikoiksi ja hietikon hetteiköksi.'),
(1687435,58,23,41,19,'Minä kasvatan erämaahan setripuita, akasioita, myrttejä ja öljypuita; minä istutan arolle kypressejä, jalavia ynnä hopeakuusia,'),
(1687436,58,23,41,20,'jotta he näkisivät ja tietäisivät, huomaisivat ja myös ymmärtäisivät, että Herran käsi on tämän tehnyt, Israelin Pyhä sen luonut.'),
(1687437,58,23,41,21,'Tuokaa esiin riita-asianne, sanoo Herra, esittäkää todisteenne, sanoo Jaakobin kuningas.'),
(1687438,58,23,41,22,'Esittäkööt ja ilmoittakoot meille, mitä tapahtuva on; ilmoittakaa entiset, mitä ne olivat, tarkataksemme ja tietääksemme, mitä niistä on tullut, tahi antakaa meidän kuulla tulevaisia.'),
(1687439,58,23,41,23,'Ilmoittakaa, mitä vastedes tapahtuu, tietääksemme, oletteko te jumalia. Tehkää hyvää tai tehkää pahaa, niin me katsomme ja ihmettelemme.'),
(1687440,58,23,41,24,'Katso, te olette pelkkää tyhjää, ja teidän tekonne ovat turhat. Kauhistus se, joka teidät valitsee!'),
(1687441,58,23,41,25,'Minä herätin pohjoisesta hänet, ja hän tuli, päivänkoitosta hänet, joka rukoilee minun nimeäni, ja hän tallaa käskynhaltijoita kuin lokaa, niinkuin savenvalaja savea sotkee.'),
(1687442,58,23,41,26,'Kuka on sen alunpitäen ilmoittanut, että olisimme sen tienneet, ja edeltäpäin, niin että voisimme sanoa: "Hän oli oikeassa"? Ei kukaan sitä ilmoittanut, ei kukaan sitä kuuluttanut, ei kukaan kuullut teiltä sanaakaan.'),
(1687443,58,23,41,27,'Minä ensimmäisenä sanon Siionille: "Katso, katso, siinä ne ovat!" ja annan Jerusalemille ilosanomantuojan.'),
(1687444,58,23,41,28,'Minä katselen ympärilleni, mutta ei ole ketään; ei kenkään näistä voi antaa neuvoa, että kysyisin heiltä ja he vastaisivat.'),
(1687445,58,23,41,29,'Katso, kaikki he ovat pelkkää petosta, turhat ovat heidän työnsä; tuulta ja tyhjää ovat heidän valetut kuvansa.'),
(1687446,58,23,42,1,'Katso, minun palvelijani, jota minä tuen, minun valittuni, johon minun sieluni mielistyi. Minä olen pannut Henkeni häneen, hän levittää kansakuntiin oikeuden.'),
(1687447,58,23,42,2,'Ei hän huuda eikä korota ääntään, ei anna sen kuulua kaduilla.'),
(1687448,58,23,42,3,'Särjettyä ruokoa hän ei muserra, ja suitsevaista kynttilänsydäntä hän ei sammuta. Hän levittää oikeutta uskollisesti.'),
(1687449,58,23,42,4,'Hän itse ei sammu eikä murru, kunnes on saattanut oikeuden maan päälle, ja merensaaret odottavat hänen opetustansa.'),
(1687450,58,23,42,5,'Näin sanoo Jumala, Herra, joka on luonut taivaan ja levittänyt sen, joka on tehnyt maan laveuden ja mitä siinä kasvaa, antanut henkäyksensä kansalle, joka siinä on, ja hengen niille, jotka siellä vaeltavat:'),
(1687451,58,23,42,6,'Minä, Herra, olen vanhurskaudessa kutsunut sinut, olen tarttunut sinun käteesi, varjellut sinut ja pannut sinut kansoille liitoksi, pakanoille valkeudeksi,'),
(1687452,58,23,42,7,'avaamaan sokeat silmät, päästämään sidotut vankeudesta, pimeydessä istuvat vankihuoneesta.'),
(1687453,58,23,42,8,'Minä, Herra, se on minun nimeni, minä en anna kunniaani toiselle enkä ylistystäni epäjumalille.'),
(1687454,58,23,42,9,'Katso, entiset ovat toteen käyneet, ja uusia minä ilmoitan; ennenkuin ne puhkeavat taimelle, annan minä teidän ne kuulla.'),
(1687455,58,23,42,10,'Veisatkaa Herralle uusi virsi, veisatkaa hänen ylistystänsä hamasta maan äärestä, te merenkulkijat ja meri täysinensä, te merensaaret ja niissä asuvaiset.'),
(1687456,58,23,42,11,'Korottakoot äänensä erämaa ja sen kaupungit, kylät, joissa Keedar asuu. Riemuitkoot kallioilla asuvaiset, vuorten huipuilta huutakoot ilosta.'),
(1687457,58,23,42,12,'Antakoot Herralle kunnian ja julistakoot hänen ylistystään merensaarissa.'),
(1687458,58,23,42,13,'Herra lähtee sotaan niinkuin sankari, niinkuin soturi hän kiihoittaa kiivautensa; hän nostaa sotahuudon ja karjuu, uhittelee vihollisiansa.'),
(1687459,58,23,42,14,'Minä olen ollut vaiti ikiajoista asti, olen ollut hiljaa ja pidättänyt itseni. Mutta nyt minä huudan kuin lapsensynnyttäjä, puhallan ja puuskun.'),
(1687460,58,23,42,15,'Minä teen autioiksi vuoret ja kukkulat, ja kuihdutan niiltä kaiken ruohon; minä muutan virrat saariksi ja kuivaan vesilammikot.'),
(1687461,58,23,42,16,'Minä johdatan sokeat tietä, jota he eivät tunne; polkuja, joita he eivät tunne, minä kuljetan heidät. Minä muutan pimeyden heidän edellään valkeudeksi ja koleikot tasangoksi. Nämä minä teen enkä niitä tekemättä jätä.'),
(1687462,58,23,42,17,'Mutta ne peräytyvät ja joutuvat häpeään, jotka turvaavat veistettyyn kuvaan, jotka sanovat valetuille kuville: "Te olette meidän jumalamme".'),
(1687463,58,23,42,18,'Te kuurot, kuulkaa, ja te sokeat, katsokaa ja nähkää.'),
(1687464,58,23,42,19,'Kuka on sokea, ellei minun palvelijani, ja kuka niin kuuro kuin minun sanansaattajani, jonka minä lähetän? Kuka on niin sokea kuin minun palkkalaiseni, niin sokea kuin Herran palvelija?'),
(1687465,58,23,42,20,'Paljon sinä olet nähnyt, mutta et ole ottanut varteen; korvat avattiin, mutta ei kuulla.'),
(1687466,58,23,42,21,'Herra on nähnyt hyväksi vanhurskautensa tähden tehdä lain suureksi ja ihanaksi.'),
(1687467,58,23,42,22,'Mutta tämä on raastettu ja ryöstetty kansa kaikki nuoret miehet ovat sidotut ja vankihuoneisiin kätketyt; he ovat joutuneet saaliiksi, eikä ole auttajaa, ryöstetyiksi, eikä ole, kuka sanoisi: "Anna takaisin!"'),
(1687468,58,23,42,23,'Kuka teistä ottaa tämän korviinsa, tarkkaa ja kuulee vastaisen varalta?'),
(1687469,58,23,42,24,'Kuka on antanut Jaakobin ryöstettäväksi ja Israelin raastajain valtaan? Eikö Herra, jota vastaan me olemme syntiä tehneet, jonka teitä he eivät tahtoneet vaeltaa ja jonka lakia he eivät totelleet?'),
(1687470,58,23,42,25,'Niin hän vuodatti Israelin päälle vihansa hehkun ja sodan tuimuuden. Se liekehti hänen ympärillään, mutta hän ei ollut tietääksensä; se poltti häntä, mutta hän ei siitä huolinut.'),
(1687471,58,23,43,1,'Mutta nyt, näin sanoo Herra, joka loi sinut, Jaakob, joka valmisti sinut, Israel: Älä pelkää, sillä minä olen lunastanut sinut, minä olen sinut nimeltä kutsunut; sinä olet minun.'),
(1687472,58,23,43,2,'Jos vetten läpi kuljet, olen minä sinun kanssasi, jos virtojen läpi, eivät ne sinua upota; jos tulen läpi käyt, et sinä kärvenny, eikä liekki sinua polta.'),
(1687473,58,23,43,3,'Sillä minä olen Herra, sinun Jumalasi, Israelin Pyhä, sinun vapahtajasi: minä annan sinun lunnaiksesi Egyptin, sinun sijastasi Etiopian ja Seban.'),
(1687474,58,23,43,4,'Koska sinä olet minun silmissäni kallis ja suuriarvoinen ja koska minä sinua rakastan, annan minä ihmisiä sinun sijastasi ja kansakuntia sinun hengestäsi.'),
(1687475,58,23,43,5,'Älä pelkää, sillä minä olen sinun kanssasi; minä tuon sinun siemenesi päivänkoiton ääriltä, päivän laskemilta minä sinut kokoan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687476,58,23,43,6,'Minä sanon pohjoiselle: Anna tänne! ja etelälle: Älä pidätä! Tuo minun poikani kaukaa ja minun tyttäreni hamasta maan äärestä -'),
(1687477,58,23,43,7,'kaikki, jotka ovat otetut minun nimiini ja jotka minä olen kunniakseni luonut, jotka minä olen valmistanut ja tehnyt.'),
(1687478,58,23,43,8,'Tuo esiin sokea kansa, jolla kuitenkin on silmät, ja kuurot, joilla kuitenkin on korvat.'),
(1687479,58,23,43,9,'Kaikki kansat ovat kokoontuneet yhteen ja kansakunnat tulleet kokoon. Kuka heistä voi ilmoittaa tämänkaltaista? Tai antakoot meidän kuulla entisiä; asettakoot todistajansa ja näyttäkööt, että ovat oikeassa: sittenpä kuullaan ja sanotaan: "Se on totta".'),
(1687480,58,23,43,10,'Te olette minun todistajani, sanoo Herra, minun palvelijani, jonka minä olen valinnut, jotta te tuntisitte minut ja uskoisitte minuun ja ymmärtäisitte, että minä se olen. Ennen minua ei ole luotu yhtäkään jumalaa, eikä minun jälkeeni toista tule.'),
(1687481,58,23,43,11,'Minä, minä olen Herra, eikä ole muuta pelastajaa, kuin minä.'),
(1687482,58,23,43,12,'Minä olen ilmoittanut, olen pelastanut ja julistanut, eikä ollut vierasta jumalaa teidän keskuudessanne. Te olette minun todistajani, sanoo Herra, ja minä olen Jumala.'),
(1687483,58,23,43,13,'Tästedeskin minä olen sama. Ei kukaan voi vapauttaa minun kädestäni; minkä minä teen, kuka sen peruuttaa?'),
(1687484,58,23,43,14,'Näin sanoo Herra, teidän lunastajanne, Israelin Pyhä: Teidän tähtenne minä lähetän sanan Baabeliin, minä syöksen heidät kaikki pakoon, syöksen kaldealaiset laivoihin, jotka olivat heidän ilonsa.'),
(1687485,58,23,43,15,'Minä, Herra, olen teidän Pyhänne, minä, Israelin Luoja, olen teidän kuninkaanne.'),
(1687486,58,23,43,16,'Näin sanoo Herra, joka teki tien mereen ja polun valtaviin vesiin,'),
(1687487,58,23,43,17,'joka vei sotaan vaunut ja hevoset, sotaväen ja sankarit kaikki; he vaipuivat eivätkä nousseet, he raukenivat, sammuivat niinkuin lampunsydän:'),
(1687488,58,23,43,18,'Älkää entisiä muistelko, älkää menneistä välittäkö.'),
(1687489,58,23,43,19,'Katso, minä teen uutta; nyt se puhkeaa taimelle, ettekö sitä huomaa? Niin, minä teen tien korpeen, virrat erämaahan.'),
(1687490,58,23,43,20,'Minua kunnioittavat metsän eläimet, aavikkosudet ja kamelikurjet, koska minä johdan vedet korpeen, virrat erämaahan, antaakseni kansani, minun valittuni, juoda.'),
(1687491,58,23,43,21,'Kansa, jonka minä olen itselleni valmistanut, on julistava minun kiitostani.'),
(1687492,58,23,43,22,'Mutta et ole sinä, Jaakob, minua kutsunut, et ole sinä, Israel, itseäsi minun tähteni vaivannut.'),
(1687493,58,23,43,23,'Et ole tuonut minulle lampaitasi polttouhriksi, et teurasuhreillasi minua kunnioittanut; en ole minä vaivannut sinua ruokauhrilla enkä suitsutusuhrilla sinua rasittanut.'),
(1687494,58,23,43,24,'Et ole minulle kalmoruokoa hopealla ostanut etkä minua teurasuhriesi rasvalla ravinnut - et, vaan sinä olet minua synneilläsi vaivannut, rasittanut minua pahoilla töilläsi.'),
(1687495,58,23,43,25,'Minä, minä pyyhin pois sinun rikkomuksesi itseni tähden, enkä sinun syntejäsi muista.'),
(1687496,58,23,43,26,'Muistuta sinä minua, käykäämme oikeutta keskenämme; puhu sinä ja näytä, että olet oikeassa.'),
(1687497,58,23,43,27,'Jo sinun esi-isäsi teki syntiä, sinun puolusmiehesi luopuivat minusta.'),
(1687498,58,23,43,28,'Niin minä annoin häväistä pyhät ruhtinaat, jätin Jaakobin tuhon omaksi, Israelin alttiiksi pilkalle.'),
(1687499,58,23,44,1,'Mutta nyt kuule, Jaakob, minun palvelijani, ja Israel, jonka minä olen valinnut.'),
(1687500,58,23,44,2,'Näin sanoo Herra, sinun Luojasi, joka on valmistanut sinut hamasta äidin kohdusta, joka sinua auttaa: Älä pelkää, minun palvelijani Jaakob, sinä Jesurun, jonka minä olen valinnut.'),
(1687501,58,23,44,3,'Sillä minä vuodatan vedet janoavaisen päälle ja virrat kuivan maan päälle. Minä vuodatan Henkeni sinun siemenesi päälle ja siunaukseni sinun vesojesi päälle,'),
(1687502,58,23,44,4,'niin että ne kasvavat nurmikossa kuin pajut vesipurojen partaalla.'),
(1687503,58,23,44,5,'Mikä sanoo: "Minä olen Herran oma", mikä nimittää itsensä Jaakobin nimellä, mikä piirtää käteensä: "Herran oma", ja ottaa Israelin kunnianimeksensä.'),
(1687504,58,23,44,6,'Näin sanoo Herra, Israelin kuningas, ja sen lunastaja, Herra Sebaot: Minä olen ensimmäinen, ja minä olen viimeinen, ja paitsi minua ei ole yhtäkään Jumalaa.'),
(1687505,58,23,44,7,'Kuka on minun kaltaiseni? Hän julistakoon ja ilmoittakoon ja osoittakoon sen minulle, siitä alkaen kuin minä perustin ikiaikojen kansan. He ilmoittakoot tulevaiset, ja mitä tapahtuva on.'),
(1687506,58,23,44,8,'Älkää vavisko älkääkä peljätkö. Enkö minä aikoja sitten antanut sinun kuulla ja sinulle ilmoittanut, ja te olette minun todistajani: Onko muuta Jumalaa kuin minä? Ei ole muuta pelastuskalliota, minä en ketään tunne.'),
(1687507,58,23,44,9,'Jumalankuvien tekijät ovat turhia kaikki tyynni, eivätkä nuo heidän rakkaansa mitään auta; niiden todistajat eivät näe eivätkä tiedä mitään, ja niin he joutuvat häpeään.'),
(1687508,58,23,44,10,'Kuka hyvänsä muovatkoon jumalan ja valakoon kuvan, ei se mitään auta.'),
(1687509,58,23,44,11,'Katso, kaikki sen seuraajat joutuvat häpeään, ja sen sepittäjät ovat vain ihmisiä. Tulkoot kokoon kaikki ja astukoot esiin: vaviskoot ja hävetkööt!'),
(1687510,58,23,44,12,'Rautaseppä ottaa työaseen ja työskentelee hiilten hehkussa, muodostelee kuvaa vasaralla ja takoo sitä käsivartensa väellä; hänen tulee nälkä, ja voima menee, hän ei saa vettä juodaksensa, ja hän nääntyy.'),
(1687511,58,23,44,13,'Puuseppä jännittää mittanuoran, kaavailee piirtimellä, vuolee kovertimella, mittailee harpilla ja tekee miehen kuvan, inhimillisen kauneuden mukaan, huoneeseen asumaan.'),
(1687512,58,23,44,14,'Hän hakkaa itselleen setripuita, hän ottaa rautatammen ja tammen ja kasvattaa ne itselleen vahvoiksi metsän puitten seassa, istuttaa lehtikuusen, ja sade kasvattaa sen suureksi.'),
(1687513,58,23,44,15,'Se on ihmisillä polttopuuna; hän ottaa sitä lämmitelläkseen, sytyttää uunin ja paistaa leipää, vieläpä veistää siitä jumalan ja kumartaa sitä, tekee siitä jumalankuvan ja lankeaa maahan sen eteen.'),
(1687514,58,23,44,16,'Osan siitä hän polttaa tulessa, toisen osan ääressä hän syö lihaa, paistaa paistin ja tulee ravituksi; hän myöskin lämmittelee itseänsä ja sanoo: "Hyvä, minun on lämmin, minä näen valkean".'),
(1687515,58,23,44,17,'Ja lopusta hän tekee jumalan, jumalankuvan, jonka eteen hän lankeaa maahan, jota hän kumartaa ja rukoilee sanoen: "Pelasta minut, sillä sinä olet minun Jumalani".'),
(1687516,58,23,44,18,'Eivät he tajua, eivät ymmärrä mitään, sillä suljetut ovat heidän silmänsä, niin etteivät he näe, ja heidän sydämensä, niin etteivät he käsitä.'),
(1687517,58,23,44,19,'Ei tule heidän mieleensä, ei ole heillä järkeä eikä ymmärrystä, että sanoisivat: "Osan siitä olen polttanut tulessa, olen paistanut sen hiilillä leipää, paistanut lihaa ja syönyt; tekisinkö tähteestä kauhistuksen, lankeaisinko maahan puupölkyn eteen!"'),
(1687518,58,23,44,20,'Joka tuhassa kiinni riippuu, sen on petetty sydän harhaan vienyt, ei hän pelasta sieluansa eikä sano: "Eikö ole petosta se, mikä on oikeassa kädessäni?"'),
(1687519,58,23,44,21,'Muista tämä, Jaakob, ja sinä, Israel, sillä sinä olet minun palvelijani. Minä olen sinut valmistanut, sinä olet minun palvelijani: en unhota minä sinua, Israel.'),
(1687520,58,23,44,22,'Minä pyyhin pois sinun rikkomuksesi niinkuin pilven ja sinun syntisi niinkuin sumun. Palaja minun tyköni, sillä minä lunastan sinut.'),
(1687521,58,23,44,23,'Iloitkaa, te taivaat, sillä Herra sen tekee; riemuitkaa, te maan syvyydet, puhjetkaa riemuun, te vuoret, ynnä metsä ja kaikki sen puut; sillä Herra lunastaa Jaakobin, kirkastaa itsensä Israelissa.'),
(1687522,58,23,44,24,'Näin sanoo Herra, sinun lunastajasi, joka on valmistanut sinut hamasta äidin kohdusta: Minä olen Herra, joka teen kaiken, joka yksinäni jännitin taivaan, joka levitin maan - kuka oli minun kanssani? -'),
(1687523,58,23,44,25,'joka teen tyhjäksi valhettelijain merkit, teen taikurit tyhmiksi, joka panen tietäjät peräytymään ja muutan heidän tietonsa typeryydeksi.'),
(1687524,58,23,44,26,'Mutta palvelijani sanan minä toteutan ja saatan täyttymään sanansaattajaini neuvon. Minä olen se, joka Jerusalemille sanon: "Sinussa asuttakoon!" ja Juudan kaupungeille: "Teidät rakennettakoon!" Sen rauniot minä kohotan.'),
(1687525,58,23,44,27,'Minä olen se, joka sanon syvyydelle: "Kuivu; minä kuivutan sinun virtasi!"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687526,58,23,44,28,'joka sanon Koorekselle: "Minun paimeneni!" Hän täyttää kaiken minun tahtoni, hän sanoo Jerusalemille: "Sinut rakennettakoon!" ja temppelille: "Sinut perustettakoon!"'),
(1687527,58,23,45,1,'Näin sanoo Herra voidellulleen Koorekselle, jonka oikeaan käteen minä olen tarttunut kukistaakseni kansat hänen edestään ja riisuakseni kuninkaitten kupeilta vyöt, että ovet hänen edessään avautuisivat eivätkä portit sulkeutuisi:'),
(1687528,58,23,45,2,'Minä käyn sinun edelläsi ja tasoitan kukkulat, minä murran vaskiovet ja rikon rautasalvat.'),
(1687529,58,23,45,3,'Minä annan sinulle aarteet pimeän peitosta, kalleudet kätköistänsä, tietääksesi, että minä, Herra, olen se, joka sinut nimeltä kutsuin, minä, Israelin Jumala.'),
(1687530,58,23,45,4,'Palvelijani Jaakobin ja valittuni Israelin tähden minä kutsuin sinut nimeltä ja annoin sinulle kunnianimen, vaikka sinä et minua tuntenut.'),
(1687531,58,23,45,5,'Minä olen Herra, eikä toista ole, paitsi minua ei ole yhtään jumalaa. Minä vyötän sinut, vaikka sinä et minua tunne,'),
(1687532,58,23,45,6,'jotta tiedettäisiin auringon noususta sen laskemille asti, että paitsi minua ei ole yhtäkään: minä olen Herra, eikä toista ole,'),
(1687533,58,23,45,7,'minä, joka teen valkeuden ja luon pimeyden, joka tuotan onnen ja luon onnettomuuden; minä, Herra, teen kaiken tämän.'),
(1687534,58,23,45,8,'Tiukkukaa, te taivaat, ylhäältä, vuotakoot pilvet vanhurskautta. Avautukoon maa ja antakoon hedelmänänsä pelastuksen, versokoon se myös vanhurskautta. Minä, Herra, olen sen luonut.'),
(1687535,58,23,45,9,'Voi sitä, joka riitelee tekijänsä kanssa, saviastia saviastiain joukossa - maasta tehtyjä kaikki! Sanooko savi valajallensa: "Mitä sinä kelpaat tekemään? Sinun työsi on kädettömän työtä!"'),
(1687536,58,23,45,10,'Voi sitä, joka sanoo isälleen: "Mitä sinä kelpaat siittämään?" ja äidilleen: "Mitä sinä kelpaat synnyttämään?"'),
(1687537,58,23,45,11,'Näin sanoo Herra, Israelin Pyhä, joka on hänet tehnyt: Kysykää tulevaisia minulta ja jättäkää minun haltuuni minun lapseni, minun kätteni teot.'),
(1687538,58,23,45,12,'Minä olen tehnyt maan ja luonut ihmisen maan päälle; minun käteni ovat levittäneet taivaan, minä olen kutsunut koolle kaikki sen joukot.'),
(1687539,58,23,45,13,'Minä herätin hänet vanhurskaudessa, ja minä tasoitin kaikki hänen tiensä. Hän rakentaa minun kaupunkini ja päästää vapaiksi minun pakkosiirtolaiseni ilman maksua ja ilman lahjusta, sanoo Herra Sebaot.'),
(1687540,58,23,45,14,'Näin sanoo Herra: Egyptin työansio ja Etiopian kauppavoitto ja sebalaiset, suurikasvuiset miehet, tulevat sinun tykösi, tulevat sinun omiksesi. Sinun perässäsi he käyvät, kulkevat kahleissa, sinua kumartavat, sinua rukoilevat: "Ainoastaan sinun tykönäsi on Jumala, ei ole toista, ei yhtään muuta jumalaa".'),
(1687541,58,23,45,15,'Totisesti, sinä olet salattu Jumala, sinä Israelin Jumala, sinä Vapahtaja.'),
(1687542,58,23,45,16,'Häpeän ja pilkan he saavat kaikki, pilkan alaisina he kulkevat kaikki, nuo kuvien tekijät.'),
(1687543,58,23,45,17,'Mutta Israelin pelastaa Herra iankaikkisella pelastuksella, te ette joudu häpeään ettekä pilkan alaisiksi, ette ikinä, hamaan iankaikkisuuteen saakka.'),
(1687544,58,23,45,18,'Sillä näin sanoo Herra, joka on luonut taivaan - hän on Jumala - joka on valmistanut maan ja tehnyt sen; hän on sen vahvistanut, ei hän sitä autioksi luonut, asuttavaksi hän sen valmisti: Minä olen Herra, eikä toista ole.'),
(1687545,58,23,45,19,'En ole minä puhunut salassa, en pimeässä maan paikassa; en ole sanonut Jaakobin jälkeläisille: etsikää minua tyhjyydestä. Minä Herra puhun vanhurskautta, ilmoitan, mikä oikein on.'),
(1687546,58,23,45,20,'Kokoontukaa ja tulkaa, lähestykää kaikki, te henkiinjääneet kansakunnista. Eivät ne mitään ymmärrä, jotka kantavat puukuviansa ja rukoilevat jumalaa, joka ei voi auttaa.'),
(1687547,58,23,45,21,'Ilmoittakaa ja esiin tuokaa - neuvotelkoot keskenänsä - kuka on tämän julistanut hamasta muinaisuudesta, aikoja sitten ilmoittanut? Enkö minä, Herra! Paitsi minua ei ole yhtään jumalaa; ei ole vanhurskasta ja auttavaa jumalaa muuta kuin minä.'),
(1687548,58,23,45,22,'Kääntykää minun tyköni ja antakaa pelastaa itsenne, te maan ääret kaikki, sillä minä olen Jumala, eikä toista ole.'),
(1687549,58,23,45,23,'Minä olen vannonut itse kauttani, minun suustani on lähtenyt totuus, peruuttamaton sana: Minun edessäni pitää kaikkien polvien notkistuman, minulle jokaisen kielen valansa vannoman.'),
(1687550,58,23,45,24,'Ainoastaan Herrassa - niin pitää minusta sanottaman - on vanhurskaus ja voima. Hänen tykönsä tulevat häveten kaikki, jotka ovat palaneet vihasta häntä vastaan.'),
(1687551,58,23,45,25,'Herrassa tulee vanhurskaaksi kaikki Israelin siemen, ja hän on heidän kerskauksensa.'),
(1687552,58,23,46,1,'Beel vaipuu, Nebo taipuu; heidän kuvansa joutuvat elukkain ja juhtain selkään; mitä te kulkueessa kannoitte, se sälytetään kuormaksi uupuville.'),
(1687553,58,23,46,2,'He taipuvat, he vaipuvat molemmat; he eivät voi pelastaa kuormaa, ja itse he vaeltavat vankeuteen.'),
(1687554,58,23,46,3,'Kuulkaa minua, te Jaakobin heimo, te kaikki Israelin heimon tähteet, te, joita on pitänyt kantaa äidinkohdusta asti, nostaa hamasta äidinhelmasta.'),
(1687555,58,23,46,4,'Teidän vanhuuteenne asti minä olen sama, hamaan harmaantumiseenne saakka minä kannan; niin minä olen tehnyt, ja vastedeskin minä nostan, minä kannan ja pelastan.'),
(1687556,58,23,46,5,'Keneenkä te vertaatte minut, kenenkä rinnalle minut asetatte, kenenkä kaltaiseksi te minut katsotte, että olisimme toistemme vertaiset?'),
(1687557,58,23,46,6,'He kaatavat kultaa kukkarosta ja punnitsevat hopeata vaa''alla; he palkkaavat kultasepän, ja hän tekee siitä jumalan, jonka eteen he lankeavat maahan ja jota he kumartavat.'),
(1687558,58,23,46,7,'He nostavat sen olallensa, kantavat ja asettavat sen paikoilleen, ja se seisoo eikä liikahda paikaltansa. Sitä huudetaan avuksi, mutta se ei vastaa, hädästä se ei pelasta.'),
(1687559,58,23,46,8,'Muistakaa tämä ja olkaa vahvat. Menkää itseenne, te luopiot.'),
(1687560,58,23,46,9,'Muistakaa entisiä ikiajoista asti, sillä minä olen Jumala, eikä toista ole; minä olen Jumala, eikä ole minun vertaistani.'),
(1687561,58,23,46,10,'Minä ilmoitan alusta asti, mitä tuleva on, ammoisia aikoja ennen, mitä ei vielä ole tapahtunut; minä sanon: minun neuvoni pysyy, kaiken, mitä tahdon, minä teen.'),
(1687562,58,23,46,11,'Minä olen kutsunut kotkan päivänkoitosta, kaukaisesta maasta neuvopäätökseni miehen. Minkä olen puhunut, sen minä myös toteutan; mitä olen aivoitellut, sen minä myös teen.'),
(1687563,58,23,46,12,'Kuulkaa minua, te kovasydämiset, jotka olette kaukana vanhurskaudesta.'),
(1687564,58,23,46,13,'Minä olen antanut vanhurskauteni lähestyä, se ei ole kaukana; ei viivy pelastus, jonka minä tuon. Minä annan Siionissa pelastuksen, annan kirkkauteni Israelille.'),
(1687565,58,23,47,1,'Astu alas ja istu tomuun, sinä neitsyt, tytär Baabel, istu maahan, valtaistuinta vailla, sinä Kaldean tytär; sillä ei sinua enää kutsuta hempeäksi ja hekumalliseksi.'),
(1687566,58,23,47,2,'Tartu käsikiviin ja jauha jauhoja, riisu huntusi, nosta helmuksesi, paljasta sääresi, kahlaa jokien poikki.'),
(1687567,58,23,47,3,'Häpysi paljastuu, häpeäsi näkyy; minä kostan enkä ainoatakaan armahda.'),
(1687568,58,23,47,4,'Meidän lunastajamme nimi on Herra Sebaot, Israelin Pyhä.'),
(1687569,58,23,47,5,'Istu äänetönnä ja väisty pimeään, sinä Kaldean tytär; sillä ei sinua enää kutsuta valtakuntien valtiattareksi.'),
(1687570,58,23,47,6,'Minä vihastuin kansaani, annoin häväistä perintöni, minä annoin heidät sinun käsiisi; et osoittanut sinä heille sääliä, vanhuksellekin sinä teit ikeesi ylen raskaaksi.'),
(1687571,58,23,47,7,'Ja sinä sanoit: "Iäti minä olen valtiatar", niin ettet näitä mieleesi pannut, et loppua ajatellut.'),
(1687572,58,23,47,8,'Mutta nyt kuule tämä, sinä hekumassa-eläjä, joka istut turvallisena, joka sanot sydämessäsi: "Minä, eikä ketään muuta! Minä en ole leskenä istuva enkä lapsettomuudesta tietävä."'),
(1687573,58,23,47,9,'Mutta nämä molemmat tulevat sinun osaksesi äkisti, yhtenä päivänä: lapsettomuus ja leskeys; ne kohtaavat sinua täydeltänsä, huolimatta velhouksiesi paljoudesta, loitsujesi suuresta voimasta.'),
(1687574,58,23,47,10,'Sinä luotit pahuuteesi, sinä sanoit: "Ei kukaan minua näe". Sinun viisautesi ja tietosi, ne sinut eksyttivät, ja niin sinä sanoit sydämessäsi: "Minä, eikä ketään muuta!"'),
(1687575,58,23,47,11,'Sentähden kohtaa sinua onnettomuus, jota et osaa manata pois; sinut yllättää tuho, josta et lunnailla pääse, äkkiä kohtaa sinua perikato, aavistamattasi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687576,58,23,47,12,'Astu esiin loitsuinesi ja paljoine velhouksinesi, joilla olet vaivannut itseäsi nuoruudestasi asti: ehkä hyvinkin saat avun, ehkä herätät pelkoa.'),
(1687577,58,23,47,13,'Sinä olet väsyttänyt itsesi paljolla neuvottelullasi. Astukoot esiin ja auttakoot sinua taivaan mittaajat, tähtien tähystäjät, jotka kuu kuulta ilmoittavat, mitä sinulle tapahtuva on.'),
(1687578,58,23,47,14,'Katso, he ovat kuin kuivat korret: tuli polttaa heidät; he eivät pelasta henkeään liekin vallasta. Se ei ole hiillos heidän lämmitelläkseen eikä valkea, jonka ääressä istutaan.'),
(1687579,58,23,47,15,'Tämän saat sinä niistä, joista olet vaivaa nähnyt: ne, joiden kanssa olet kauppaa käynyt hamasta nuoruudestasi asti, harhailevat kukin haarallensa, ei kukaan sinua pelasta.'),
(1687580,58,23,48,1,'Kuulkaa tämä, Jaakobin heimo, te, joita kutsutaan Israelin nimellä ja jotka olette lähteneet Juudan lähteestä, jotka vannotte Herran nimeen ja tunnustatte Israelin Jumalan, mutta ette totuudessa ettekä vanhurskaudessa -'),
(1687581,58,23,48,2,'sillä heitä kutsutaan pyhän kaupungin mukaan ja he pitävät tukenansa Israelin Jumalaa, jonka nimi on Herra Sebaot:'),
(1687582,58,23,48,3,'Entiset minä olen aikoja ennen ilmoittanut, minun suustani ne ovat lähteneet, ja minä olen ne kuuluttanut. Äkkiä minä panin ne täytäntöön, ja ne tapahtuivat.'),
(1687583,58,23,48,4,'Koska minä tiesin, että sinä olet paatunut, että sinun niskajänteesi on rautaa ja otsasi vaskea,'),
(1687584,58,23,48,5,'niin minä ilmoitin ne sinulle aikoja ennen, kuulutin ne sinulle, ennenkuin ne tapahtuivat, ettet sanoisi: "Epäjumalankuvani on ne tehnyt, veistetty kuvani ja valettu kuvani on niin säätänyt".'),
(1687585,58,23,48,6,'Sinä olet ne kuullut, katso nyt kaikkea: ettekö sitä tunnusta? Tästä lähtien minä kuulutan sinulle uusia, salatuita, joita et ole tietänyt.'),
(1687586,58,23,48,7,'Ne ovat luodut nyt, eikä aikoja sitten, ennen tätä päivää et ole niistä kuullut, ettet saattaisi sanoa: "Katso, jo minä ne tiesin!"'),
(1687587,58,23,48,8,'Et ole sinä niistä kuullut etkä tietänyt, ei ole sinun korvasi niille aikaisemmin auennut; sillä minä tiesin, että sinä olet aivan uskoton ja luopioksi kutsuttu hamasta äidin kohdusta.'),
(1687588,58,23,48,9,'Oman nimeni tähden minä olen pitkämielinen, ylistykseni tähden minä hillitsen vihani, etten sinua tuhoaisi.'),
(1687589,58,23,48,10,'Katso, minä olen sinua sulattanut, hopeata saamatta, minä olen sinua koetellut kärsimyksen pätsissä.'),
(1687590,58,23,48,11,'Itseni, itseni tähden minä sen teen; sillä kuinka onkaan minun nimeäni häväisty! Kunniaani en minä toiselle anna.'),
(1687591,58,23,48,12,'Kuule minua, Jaakob, ja sinä, Israel, jonka minä olen kutsunut: Minä olen aina sama, minä olen ensimmäinen, minä olen myös viimeinen.'),
(1687592,58,23,48,13,'Minun käteni on perustanut maan, minun oikea käteni on levittänyt taivaan; minä kutsun ne, ja siinä ne ovat.'),
(1687593,58,23,48,14,'Kokoontukaa kaikki ja kuulkaa - kuka niistä muista on ilmoittanut tämän: että hän, jota Herra rakastaa, tekee hänen tahtonsa Baabelia vastaan, on hänen käsivartenaan kaldealaisia vastaan.'),
(1687594,58,23,48,15,'Minä, minä olen puhunut, minä olen hänet kutsunut, olen hänet tuonut, ja hän on menestynyt teillänsä.'),
(1687595,58,23,48,16,'Lähestykää minua, kuulkaa tämä: Alkujaankaan minä en ole puhunut salassa; kun nämä tapahtuivat, olin minä jo siellä. Ja nyt Herra, Herra on lähettänyt minut ynnä oman Henkensä.'),
(1687596,58,23,48,17,'Näin sanoo Herra, sinun lunastajasi, Israelin Pyhä: Minä olen Herra, sinun Jumalasi, joka opetan sinulle, mikä hyödyllistä on, johdatan sinua sitä tietä, jota sinun tulee käydä.'),
(1687597,58,23,48,18,'Jospa ottaisit minun käskyistäni vaarin, niin olisi sinun rauhasi niinkuin virta ja sinun vanhurskautesi niinkuin meren aallot;'),
(1687598,58,23,48,19,'sinun lastesi paljous olisi niinkuin hiekka, sinun kohtusi hedelmä niinkuin hiekkajyväset, sen nimi ei häviäisi, ei katoaisi minun kasvojeni edestä.'),
(1687599,58,23,48,20,'Lähtekää Baabelista, paetkaa Kaldeasta; riemuhuudoin ilmoittakaa, kuuluttakaa tämä, viekää tieto siitä maan ääriin asti, sanokaa: "Herra on lunastanut palvelijansa Jaakobin".'),
(1687600,58,23,48,21,'Eivät he janoa kärsineet, kun hän heitä kuljetti erämaitten halki; hän vuodatti heille vettä kalliosta, hän halkaisi kallion, ja vettä virtasi.'),
(1687601,58,23,48,22,'Jumalattomilla ei ole rauhaa, sanoo Herra.'),
(1687602,58,23,49,1,'Kuulkaa minua, te merensaaret, ja tarkatkaa, kaukaiset kansat. Herra on minut kutsunut hamasta äidinkohdusta saakka, hamasta äitini helmasta minun nimeni maininnut.'),
(1687603,58,23,49,2,'Hän teki minun suuni terävän miekan kaltaiseksi, kätki minut kätensä varjoon; hän teki minut hiotuksi nuoleksi, talletti minut viineensä.'),
(1687604,58,23,49,3,'Ja hän sanoi minulle: "Sinä olet minun palvelijani, sinä Israel, jossa minä osoitan kirkkauteni".'),
(1687605,58,23,49,4,'Mutta minä sanoin: "Hukkaan minä olen itseäni vaivannut, kuluttanut voimani turhaan ja tyhjään; kuitenkin on minun oikeuteni Herran huomassa, minun palkkani on Jumalan tykönä".'),
(1687606,58,23,49,5,'Ja nyt sanoo Herra, joka on minut palvelijakseen valmistanut hamasta äitini kohdusta, palauttamaan Jaakobin hänen tykönsä, niin että Israel koottaisiin hänen omaksensa - ja minä olen kallis Herran silmissä, minun Jumalani on tullut minun voimakseni -'),
(1687607,58,23,49,6,'hän sanoo: Liian vähäistä on sinulle, joka olet minun palvelijani, kohottaa ennalleen Jaakobin sukukunnat ja tuoda takaisin Israelin säilyneet: minä panen sinut pakanain valkeudeksi, että minulta tulisi pelastus maan ääriin asti.'),
(1687608,58,23,49,7,'Näin sanoo Herra, Israelin lunastaja, hänen Pyhänsä, syvästi halveksitulle, kansan inhoamalle, valtiaitten orjalle: Kuninkaat näkevät sen ja nousevat seisomaan, ruhtinaat näkevät ja kumartuvat maahan Herran tähden, joka on uskollinen, Israelin Pyhän tähden, joka on sinut valinnut.'),
(1687609,58,23,49,8,'Näin sanoo Herra: Otollisella ajalla minä olen sinua kuullut ja pelastuksen päivänä sinua auttanut; minä olen valmistanut sinut ja pannut sinut kansoille liitoksi, kohottamaan ennalleen maan, jakamaan hävitetyt perintöosat,'),
(1687610,58,23,49,9,'sanomaan vangituille: "Käykää ulos!" ja pimeässä oleville: "Tulkaa esiin!" Teiden varsilta he löytävät laitumen, kaikki kalliokukkulat ovat heillä laidunpaikkoina.'),
(1687611,58,23,49,10,'Ei heidän tule nälkä eikä jano, ei hietikon helle eikä aurinko satu heihin, sillä heidän armahtajansa johdattaa heitä ja vie heidät vesilähteille.'),
(1687612,58,23,49,11,'Minä teen kaikki vuoreni teiksi, ja minun valtatieni kulkevat korkealla.'),
(1687613,58,23,49,12,'Katso heitä, he tulevat kaukaa! Katso, nuo pohjoisesta, nuo lännestä, nuo Siinimin maalta!'),
(1687614,58,23,49,13,'Riemuitkaa, te taivaat, iloitse, sinä maa, puhjetkaa riemuun, te vuoret, sillä Herra lohduttaa kansaansa ja armahtaa kurjiansa.'),
(1687615,58,23,49,14,'Mutta Siion sanoo: "Herra on minut hyljännyt, Herra on minut unhottanut".'),
(1687616,58,23,49,15,'Unhottaako vaimo rintalapsensa, niin ettei hän armahda kohtunsa poikaa? Ja vaikka he unhottaisivatkin, minä en sinua unhota.'),
(1687617,58,23,49,16,'Katso, kätteni hipiään olen minä sinut piirtänyt, sinun muurisi ovat aina minun edessäni.'),
(1687618,58,23,49,17,'Sinun lapsesi tulevat rientäen; sinun hävittäjäsi ja raunioiksi-raastajasi menevät sinun luotasi pois.'),
(1687619,58,23,49,18,'Nosta silmäsi ja katso ympärillesi: he kokoontuvat, he tulevat sinun tykösi kaikki. Niin totta kuin minä elän, sanoo Herra, sinä puet heidät kaikki yllesi niinkuin koristeen ja sidot heidät vyöllesi niinkuin morsian vyönsä.'),
(1687620,58,23,49,19,'Sillä sinä - sinun rauniosi ja autiot paikkasi, sinun hävitetty maasi - sinä käyt silloin ahtaaksi asukkaille, ja kaukana ovat ne, jotka sinua söivät.'),
(1687621,58,23,49,20,'Vielä saavat sinun lapsettomuutesi lapset sanoa korviesi kuullen: "Paikka on minulle ahdas, tee tilaa, että voin asua".'),
(1687622,58,23,49,21,'Silloin sinä sanot sydämessäsi: "Kuka on nämä minulle synnyttänyt? Minä olin lapseton ja hedelmätön, karkoitettu ja hyljätty. Kuka on heidät kasvattanut? Katso, minä olin jätetty yksin. Missä nämä silloin olivat?'),
(1687623,58,23,49,22,'Näin sanoo Herra, Herra: Katso, minä nostan käteni kansakuntien puoleen, kohotan lippuni kansoja kohti, niin he tuovat sinun poikasi sylissänsä ja kantavat sinun tyttäresi olkapäillään.'),
(1687624,58,23,49,23,'Kuninkaista tulee sinulle lastenhoitajat, heidän ruhtinattaristaan sinulle imettäjät. Sinun edessäsi he kumartuvat maahan kasvoillensa ja nuolevat tomun sinun jaloistasi. Silloin sinä tiedät, että minä olen Herra ja että ne, jotka minua odottavat, eivät häpeään joudu.'),
(1687625,58,23,49,24,'Otetaanko sankarilta saalis, tai riistetäänkö vangit vanhurskaalta?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687626,58,23,49,25,'Sillä näin sanoo Herra: Vaikka vangit otettaisiinkin sankarilta ja saalis riistettäisiin väkevältä, niin minä kuitenkin taistelen sitä vastaan, joka sinua vastaan taistelee, ja minä pelastan sinun lapsesi.'),
(1687627,58,23,49,26,'Minä panen sinun sortajasi syömään omaa lihaansa, ja he juopuvat omasta verestään niinkuin rypälemehusta; ja kaikki liha on tietävä, että minä, Herra, olen sinun pelastajasi, että Jaakobin Väkevä on sinun lunastajasi.'),
(1687628,58,23,50,1,'Näin sanoo Herra: Missä on teidän äitinne erokirja, jolla olisin lähettänyt hänet pois? Tai kuka on minun velkojani, jolle minä olisin teidät myynyt? Katso, pahojen tekojenne tähden te olette myydyt, teidän rikkomustenne tähden on äitinne lähetetty pois.'),
(1687629,58,23,50,2,'Miksi ei ollut ketään, kun minä tulin, miksi ei kukaan vastannut, kun minä huusin? Onko minun käteni liian lyhyt vapahtamaan, olenko minä voimaton auttamaan? Katso, nuhtelullani minä kuivaan meren, minä teen virrat erämaaksi, niin että niitten kalat mätänevät, kun ei ole vettä; ne kuolevat janoon.'),
(1687630,58,23,50,3,'Minä puetan taivaat mustiin ja panen murhepuvun niitten verhoksi.'),
(1687631,58,23,50,4,'Herra, Herra on minulle antanut opetuslasten kielen, niin että minä taidan sanalla virvoittaa väsynyttä; hän herättää aamu aamulta, herättää minun korvani kuulemaan opetuslasten tavalla.'),
(1687632,58,23,50,5,'Herra, Herra on avannut minun korvani; minä en ole niskoitellut, en vetäytynyt pois.'),
(1687633,58,23,50,6,'Selkäni minä annoin lyötäväksi, poskieni parran revittäväksi, en peittänyt kasvojani pilkalta ja syljeltä.'),
(1687634,58,23,50,7,'Herra, Herra auttaa minua; sentähden ei minuun pilkka koskenut, sentähden tein kasvoni koviksi kuin piikivi, sillä minä tiedän, etten häpeään joudu.'),
(1687635,58,23,50,8,'Lähellä on hän, joka minut vanhurskaaksi tuomitsee. Kuka voi minun kanssani riidellä? Astukaamme yhdessä esiin! Kuka on minun vastapuoleni? Tulkoon tänne lähelleni!'),
(1687636,58,23,50,9,'Katso, Herra, Herra auttaa minua; kuka minut syylliseksi tuomitsee? Katso, kaikki he hajoavat kuin vaate; koi heidät syö.'),
(1687637,58,23,50,10,'Kuka teistä pelkää Herraa ja kuulee hänen palvelijansa ääntä? Joka vaeltaa pimeydessä ja valoa vailla, se luottakoon Herran nimeen ja turvautukoon Jumalaansa.'),
(1687638,58,23,50,11,'Mutta katso, te kaikki, jotka palon sytytätte, te palavilla nuolilla varustetut, suistukaa oman tulenne liekkeihin, niihin palaviin nuoliin, jotka olette sytyttäneet. Minun kädestäni tämä teille tulee; vaivassa täytyy teidän asua.'),
(1687639,58,23,51,1,'Kuulkaa minua, te jotka vanhurskauteen pyritte, te jotka Herraa etsitte. Katsokaa kalliota, josta olette lohkaistut, ja kaivos-onkaloa, josta olette kaivetut.'),
(1687640,58,23,51,2,'Katsokaa Aabrahamia, isäänne, ja Saaraa, joka teidät synnytti. Sillä hän oli vain yksi, kun minä hänet kutsuin; mutta minä siunasin hänet ja enensin hänet.'),
(1687641,58,23,51,3,'Niin Herra lohduttaa Siionin, lohduttaa kaikki sen rauniot, hän tekee sen erämaasta kuin Eedenin ja sen arosta kuin Herran puutarhan; siellä on oleva riemu ja ilo, kiitos ja ylistysvirren ääni.'),
(1687642,58,23,51,4,'Kuuntele minua, kansani, kuule minua, kansakuntani, sillä minusta lähtee laki, ja minä panen oikeuteni valkeudeksi kansoille.'),
(1687643,58,23,51,5,'Lähellä on minun vanhurskauteni, minun autuuteni ilmestyy, minun käsivarteni tuomitsevat kansat; minua odottavat merensaaret ja panevat toivonsa minun käsivarteeni.'),
(1687644,58,23,51,6,'Nostakaa silmänne taivasta kohti ja katsokaa maata, joka alhaalla on, sillä taivaat katoavat kuin savu ja maa hajoaa kuin vaate ja sen asukkaat kuolevat kuin sääsket, mutta minun autuuteni pysyy iankaikkisesti, ja minun vanhurskauteni ei kukistu.'),
(1687645,58,23,51,7,'Kuulkaa minua, te jotka vanhurskauden tunnette, kansa, jonka sydämessä on minun lakini: älkää peljätkö ihmisten pilkkaa älkääkä kauhistuko heidän herjauksiansa.'),
(1687646,58,23,51,8,'Sillä koi syö heidät niinkuin vaatteen, koiperhonen syö heidät niinkuin villan, mutta minun vanhurskauteni pysyy iankaikkisesti, minun autuuteni polvesta polveen.'),
(1687647,58,23,51,9,'Heräjä, heräjä, pukeudu voimaan, sinä Herran käsivarsi; heräjä niinkuin muinaisina päivinä, ammoisten sukupolvien aikoina. Etkö sinä ole se, joka löit Rahabin kuoliaaksi, joka lävistit lohikäärmeen?'),
(1687648,58,23,51,10,'Etkö sinä ole se, joka kuivasit meren, suuren syvyyden vedet, joka teit meren syvänteet tieksi lunastettujen kulkea?'),
(1687649,58,23,51,11,'Niin Herran vapahdetut palajavat ja tulevat Siioniin riemuiten, päänsä päällä iankaikkinen ilo. Riemu ja ilo saavuttavat heidät, mutta murhe ja huokaus pakenevat.'),
(1687650,58,23,51,12,'Minä, minä olen teidän lohduttajanne; mikä olet sinä, että pelkäät ihmistä, joka on kuolevainen, ihmislasta, jonka käy niinkuin ruohon,'),
(1687651,58,23,51,13,'ja unhotat Herran, joka on sinut tehnyt, joka on levittänyt taivaan ja perustanut maan, ja vapiset alati, kaiket päivät, sortajan vihaa, kun hän tähtää tuhotaksensa? Mutta missä on sortajan viha?'),
(1687652,58,23,51,14,'Pian päästetään kumaraan koukistunut vapaaksi kahleistaan: ei hän kuole, ei kuoppaan jää, eikä häneltä leipä puutu.'),
(1687653,58,23,51,15,'Minä olen Herra, sinun Jumalasi, joka liikutan meren, niin että sen aallot pauhaavat, jonka nimi on Herra Sebaot.'),
(1687654,58,23,51,16,'Ja minä olen pannut sanani sinun suuhusi, minä olen kätkenyt sinut käteni varjoon, pystyttääkseni taivaan ja perustaakseni maan ja sanoakseni Siionille: "Sinä olet minun kansani".'),
(1687655,58,23,51,17,'Heräjä, heräjä, nouse, Jerusalem, sinä joka olet juonut Herran kädestä hänen vihansa maljan, joka olet päihdyttävän pikarin juonut, tyhjäksi särpinyt.'),
(1687656,58,23,51,18,'Ei kukaan kaikista lapsista, jotka hän oli synnyttänyt, ollut häntä taluttamassa; ei kukaan kaikista lapsista, jotka hän oli kasvattanut, hänen käteensä tarttunut.'),
(1687657,58,23,51,19,'Nämä kohtasivat sinua kaksittain - kuka sinua surkuttelee - tuho ja turmio, nälkä ja miekka; millä voin sinua lohduttaa?'),
(1687658,58,23,51,20,'Tajuttomina makasivat sinun poikasi joka kadun kulmassa, niinkuin antiloopit pyydyshaudassa, täynnä Herran vihaa, sinun Jumalasi nuhtelua.'),
(1687659,58,23,51,21,'Sentähden kuule tätä, sinä poloinen, joka olet juopunut, vaikka et viinistä:'),
(1687660,58,23,51,22,'Näin sanoo sinun Herrasi, Herra sinun Jumalasi, joka ajaa kansansa asian: Katso, minä otan sinun kädestäsi päihdyttävän maljan, vihani pikarin; ei tarvitse sinun siitä enää juoda.'),
(1687661,58,23,51,23,'Ja minä panen sen sinun vaivaajaisi käteen, jotka sinulle sanoivat: "Lankea maahan, kulkeaksemme sinun päällitsesi"; ja sinä panit selkäsi maaksi ja kaduksi kulkijoille.'),
(1687662,58,23,52,1,'Heräjä, heräjä, pukeudu voimaasi, Siion; pukeudu juhlapukuusi, Jerusalem, sinä pyhä kaupunki. Sillä ei koskaan enää astu sinun sisällesi ympärileikkaamaton eikä saastainen.'),
(1687663,58,23,52,2,'Pudista päältäsi tomu, nouse istuimellesi, Jerusalem; irroita kahleet kaulastasi, sinä vangittu tytär Siion.'),
(1687664,58,23,52,3,'Sillä näin sanoo Herra: Ilmaiseksi teidät myytiin, rahatta teidät lunastetaan.'),
(1687665,58,23,52,4,'Sillä näin sanoo Herra, Herra: Minun kansani meni ensin alas Egyptiin asumaan siellä muukalaisena, ja sitten Assur sorti sitä ilman syytä.'),
(1687666,58,23,52,5,'Ja nyt, mitä minulla on tekemistä täällä, sanoo Herra, kun minun kansani on viety pois ilmaiseksi? Sen valtiaat elämöivät, sanoo Herra, ja minun nimeäni pilkataan alati, kaiket päivät.'),
(1687667,58,23,52,6,'Sentähden minun kansani on tunteva minun nimeni, sentähden se on tunteva sinä päivänä, että minä olen se, joka sanon: "Katso, tässä minä olen".'),
(1687668,58,23,52,7,'Kuinka suloiset ovat vuorilla ilosanoman tuojan jalat, hänen, joka julistaa rauhaa, ilmoittaa hyvän sanoman, joka julistaa pelastusta, sanoo Siionille: "Sinun Jumalasi on kuningas!"'),
(1687669,58,23,52,8,'Kuule! Vartijasi korottavat äänensä, kaikki he riemuitsevat, sillä he näkevät silmästä silmään, kuinka Herra palajaa Siioniin.'),
(1687670,58,23,52,9,'Huutakaa ilosta, riemuitkaa, kaikki te Jerusalemin rauniot, sillä Herra lohduttaa kansansa, lunastaa Jerusalemin.'),
(1687671,58,23,52,10,'Herra paljastaa pyhän käsivartensa kaikkien kansojen nähden, ja kaikki maan ääret saavat nähdä meidän Jumalamme autuuden.'),
(1687672,58,23,52,11,'Pois, pois! Lähtekää sieltä, älkää koskeko saastaiseen; lähtekää sen keskeltä, puhdistautukaa, te Herran aseenkantajat.'),
(1687673,58,23,52,12,'Sillä ei teidän tarvitse kiiruusti lähteä, ei paeten kulkea; sillä Herra käy teidän edellänne, Israelin Jumala seuraa suojananne.'),
(1687674,58,23,52,13,'Katso, minun palvelijani menestyy, hän on nouseva, kohoava ja sangen korkea oleva.'),
(1687675,58,23,52,14,'Niinkuin monet kauhistuivat häntä - sillä niin runneltu, ei enää ihmisenkaltainen, oli hänen muotonsa, hänen hahmonsa ei ollut ihmislasten hahmo -');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687676,58,23,52,15,'niin hän on saattava ihmetyksiin monet kansat, hänen tähtensä kuninkaat sulkevat suunsa. Sillä mitä heille ei ikinä ole kerrottu, sen he saavat nähdä, mitä he eivät ole kuulleet, sen he saavat havaita.'),
(1687677,58,23,53,1,'Kuka uskoo meidän saarnamme, kenelle Herran käsivarsi ilmoitetaan?'),
(1687678,58,23,53,2,'Hän kasvoi Herran edessä niinkuin vesa, niinkuin juuri kuivasta maasta. Ei ollut hänellä vartta eikä kauneutta; me näimme hänet, mutta ei ollut hänellä muotoa, johon me olisimme mielistyneet.'),
(1687679,58,23,53,3,'Hän oli ylenkatsottu, ihmisten hylkäämä, kipujen mies ja sairauden tuttava, jota näkemästä kaikki kasvonsa peittivät, halveksittu, jota emme minäkään pitäneet.'),
(1687680,58,23,53,4,'Mutta totisesti, meidän sairautemme hän kantoi, meidän kipumme hän sälytti päällensä. Me pidimme häntä rangaistuna, Jumalan lyömänä ja vaivaamana,'),
(1687681,58,23,53,5,'mutta hän on haavoitettu meidän rikkomustemme tähden, runneltu meidän pahain tekojemme tähden. Rangaistus oli hänen päällänsä, että meillä rauha olisi, ja hänen haavainsa kautta me olemme paratut.'),
(1687682,58,23,53,6,'Me vaelsimme kaikki eksyksissä niinkuin lampaat, kukin meistä poikkesi omalle tielleen. Mutta Herra heitti hänen päällensä kaikkien meidän syntivelkamme.'),
(1687683,58,23,53,7,'Häntä piinattiin, ja hän alistui siihen eikä suutansa avannut; niinkuin karitsa, joka teuraaksi viedään, niinkuin lammas, joka on ääneti keritsijäinsä edessä, niin ei hän suutansa avannut.'),
(1687684,58,23,53,8,'Ahdistettuna ja tuomittuna hänet otettiin pois, mutta kuka hänen polvikunnastaan sitä ajatteli? Sillä hänet temmattiin pois elävien maasta; minun kansani rikkomuksen tähden kohtasi rangaistus häntä.'),
(1687685,58,23,53,9,'Hänelle annettiin hauta jumalattomain joukossa; mutta rikkaan tykö hän tuli kuoltuansa, sillä hän ei ollut vääryyttä tehnyt eikä petosta ollut hänen suussansa.'),
(1687686,58,23,53,10,'Mutta Herra näki hyväksi runnella häntä, lyödä hänet sairaudella. Jos sinä panet hänen sielunsa vikauhriksi, saa hän nähdä jälkeläisiä ja elää kauan, ja Herran tahto toteutuu hänen kauttansa.'),
(1687687,58,23,53,11,'Sielunsa vaivan tähden hän saa nähdä sen ja tulee ravituksi. Tuntemuksensa kautta hän, minun vanhurskas palvelijani, vanhurskauttaa monet, sälyttäen päällensä heidän pahat tekonsa.'),
(1687688,58,23,53,12,'Sentähden minä jaan hänelle osan suurten joukossa, ja väkevien kanssa hän saalista jakaa; sillä hän antoi sielunsa alttiiksi kuolemaan, ja hänet luettiin pahantekijäin joukkoon, hän kantoi monien synnit, ja hän rukoili pahantekijäin puolesta.'),
(1687689,58,23,54,1,'Riemuitse, sinä hedelmätön, joka et ole synnyttänyt, huuda ilosta ja riemahda, sinä, joka et ole synnytyskivuissa ollut. Sillä hyljätyllä on lapsia enemmän kuin aviovaimolla, sanoo Herra.'),
(1687690,58,23,54,2,'Tee avaraksi telttasi sija, levennettäköön sinun majojesi seinien kangas. Älä säästele! Pidennä telttaköytesi ja vahvista vaarnasi.'),
(1687691,58,23,54,3,'Sillä sinä olet leviävä oikealle ja vasemmalle, sinun jälkeläisesi ottavat omiksensa kansat ja tekevät autiot kaupungit asutuiksi.'),
(1687692,58,23,54,4,'Älä pelkää, sillä et sinä häpeään joudu; älä ole häpeissäsi, sillä et sinä ole pettyvä. Nuoruutesi häpeän sinä olet unhottava, leskeytesi pilkkaa et ole enää muistava.'),
(1687693,58,23,54,5,'Sillä hän, joka sinut teki, on sinun aviomiehesi, Herra Sebaot on hänen nimensä, sinun lunastajasi on Israelin Pyhä, hän joka kaiken maan Jumalaksi kutsutaan.'),
(1687694,58,23,54,6,'Sillä niinkuin hyljätyn, syvästi murheellisen vaimon on Herra sinut kutsunut - nuoruuden vaimon, joka on ollut halveksittu, sanoo sinun Jumalasi.'),
(1687695,58,23,54,7,'Vähäksi silmänräpäykseksi minä hylkäsin sinut, mutta minä kokoan sinut jälleen suurella laupeudella.'),
(1687696,58,23,54,8,'Ylitsevuotavassa vihassani minä peitin sinulta kasvoni silmänräpäykseksi, mutta minä armahdan sinut iankaikkisella armolla, sanoo Herra, sinun lunastajasi.'),
(1687697,58,23,54,9,'Sillä tämä on minulle, niinkuin olivat Nooan vedet: niinkuin minä vannoin, etteivät Nooan vedet enää tulvi maan ylitse, niin minä vannon, etten enää vihastu sinuun enkä sinua nuhtele.'),
(1687698,58,23,54,10,'Sillä vuoret väistykööt ja kukkulat horjukoot, mutta minun armoni ei sinusta väisty, eikä minun rauhanliittoni horju, sanoo Herra, sinun armahtajasi.'),
(1687699,58,23,54,11,'Sinä kurja, myrskyn raastama, sinä lohduton! Katso, minä muuraan sinun kivesi kiiltokivellä, panen sinun perustuksesi safiireista,'),
(1687700,58,23,54,12,'minä teen sinun harjasi rubiineista ja sinun porttisi kristalleista ja koko sinun ympärysmuurisi jalokivistä.'),
(1687701,58,23,54,13,'Sinun lapsesi ovat kaikki Herran opetuslapsia, ja suuri rauha on sinun lapsillasi oleva.'),
(1687702,58,23,54,14,'Sinut vahvistetaan vanhurskaudella; sinä olet oleva kaukana väkivallasta, sillä ei sinulla ole pelkäämistä, ja kaukana hävityksestä, sillä ei se sinua lähesty.'),
(1687703,58,23,54,15,'Jos sinun kimppuusi karataan, ei se ole minusta; joka kimppuusi karkaa, se eteesi kaatuu.'),
(1687704,58,23,54,16,'Katso, minä olen luonut sepän, joka lietsoo hiilivalkeata ja kuonnuttaa aseen käytäntöönsä; mutta minä olen myös luonut tuhontuottajan hävittämään sen.'),
(1687705,58,23,54,17,'Jokainen ase, joka valmistetaan sinun varallesi, on oleva tehoton; ja jokaisen kielen, joka nousee käymään sinun kanssasi oikeutta, sinä osoitat vääräksi. Tämä on Herran palvelijain perintöosa, tämä heidän vanhurskautensa, minulta saatu, sanoo Herra.'),
(1687706,58,23,55,1,'Kuulkaa, kaikki janoavaiset, tulkaa veden ääreen. Tekin, joilla ei ole rahaa, tulkaa, ostakaa ja syökää; tulkaa, ostakaa ilman rahatta, ilman hinnatta viiniä ja maitoa.'),
(1687707,58,23,55,2,'Miksi annatte rahan siitä, mikä ei ole leipää, ja työnne ansion siitä, mikä ei ravitse? Kuulkaa minua, niin saatte syödä hyvää, ja teidän sielunne virvoittuu lihavuuden ääressä.'),
(1687708,58,23,55,3,'Kallistakaa korvanne ja tulkaa minun tyköni; kuulkaa, niin teidän sielunne saa elää. Ja minä teen teidän kanssanne iankaikkisen liiton, annan lujat Daavidin armot.'),
(1687709,58,23,55,4,'Katso, hänet minä asetin kansoille todistajaksi, kansojen ruhtinaaksi ja käskijäksi.'),
(1687710,58,23,55,5,'Katso, sinä olet kutsuva pakanoita, joita sinä et tunne, ja pakanat, jotka eivät sinua tunne, rientävät sinun tykösi Herran, sinun Jumalasi, tähden, Israelin Pyhän tähden, sillä hän kirkastaa sinut.'),
(1687711,58,23,55,6,'Etsikää Herraa silloin, kun hänet löytää voidaan; huutakaa häntä avuksi, kun hän läsnä on.'),
(1687712,58,23,55,7,'Jumalaton hyljätköön tiensä ja väärintekijä ajatuksensa ja palatkoon Herran tykö, niin hän armahtaa häntä, ja meidän Jumalamme tykö, sillä hänellä on paljon anteeksiantamusta.'),
(1687713,58,23,55,8,'Sillä minun ajatukseni eivät ole teidän ajatuksianne, eivätkä teidän tienne ole minun teitäni, sanoo Herra.'),
(1687714,58,23,55,9,'Vaan niin paljon korkeampi kuin taivas on maata, ovat minun tieni korkeammat teidän teitänne ja minun ajatukseni teidän ajatuksianne.'),
(1687715,58,23,55,10,'Sillä niinkuin sade ja lumi, joka taivaasta tulee, ei sinne palaja, vaan kostuttaa maan, tekee sen hedelmälliseksi ja kasvavaksi, antaa kylväjälle siemenen ja syöjälle leivän,'),
(1687716,58,23,55,11,'niin on myös minun sanani, joka minun suustani lähtee: ei se minun tyköni tyhjänä palaja, vaan tekee sen, mikä minulle otollista on, ja saa menestymään sen, mitä varten minä sen lähetin.'),
(1687717,58,23,55,12,'Sillä iloiten te lähdette, ja rauhassa teitä saatetaan; vuoret ja kukkulat puhkeavat riemuun teidän edessänne, ja kaikki kedon puut paukuttavat käsiänsä.'),
(1687718,58,23,55,13,'Orjantappurain sijaan on kasvava kypressejä, nokkosten sijaan on kasvava myrttipuita; ja se tulee Herran kunniaksi, iankaikkiseksi merkiksi, joka ei häviä.'),
(1687719,58,23,56,1,'Näin sanoo Herra: Noudattakaa oikeutta ja tehkää vanhurskaus, sillä minun autuuteni on lähellä ja minun vanhurskauteni ilmestyy.'),
(1687720,58,23,56,2,'Autuas se ihminen, joka tämän tekee, se ihmislapsi, joka tässä pysyy, joka pitää sapatin eikä sitä riko, joka varoo kätensä tekemästä mitään pahaa!'),
(1687721,58,23,56,3,'Älköön sanoko muukalainen, joka on liittynyt Herraan: "Herra erottaa minut peräti kansastansa", älköönkä kuohittu sanoko: "Minä olen kuiva puu".'),
(1687722,58,23,56,4,'Sillä näin sanoo Herra: Kuohituille, jotka pitävät minun sapattini ja valitsevat sen, mikä minulle otollista on, ja pysyvät minun liitossani,'),
(1687723,58,23,56,5,'heille minä annan huoneessani ja muurieni sisällä muistomerkin ja nimen, joka on poikia ja tyttäriä parempi; minä annan heille iankaikkisen nimen, joka ei häviä.'),
(1687724,58,23,56,6,'Ja muukalaiset, jotka ovat liittyneet Herraan, palvellakseen häntä ja rakastaakseen Herran nimeä, ollakseen hänen palvelijoitansa, kaikki, jotka pitävät sapatin eivätkä sitä riko ja pysyvät minun liitossani,'),
(1687725,58,23,56,7,'ne minä tuon pyhälle vuorelleni ja ilahutan heitä rukoushuoneessani, ja heidän polttouhrinsa ja teurasuhrinsa ovat otolliset minun alttarillani, sillä minun huoneeni on kutsuttava kaikkien kansojen rukoushuoneeksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687726,58,23,56,8,'Herra, Herra sanoo, hän, joka kokoaa Israelin karkoitetut: Minä kokoan vielä muitakin sen koottujen lisäksi.'),
(1687727,58,23,56,9,'Kaikki kedon eläimet, tulkaa syömään, te metsän eläimet kaikki.'),
(1687728,58,23,56,10,'Israelin vartijat ovat kaikki sokeita, eivät he mitään käsitä; he ovat kaikki mykkiä koiria, jotka eivät osaa haukkua. He näkevät unta, makailevat ja nukkuvat mielellään.'),
(1687729,58,23,56,11,'Ja näillä koirilla on vimmainen nälkä, ei niitä mikään täytä. Ja tällaisia ovat paimenet! Eivät pysty mitään huomaamaan, ovat kaikki kääntyneet omille teilleen, etsivät kukin omaa voittoansa, kaikki tyynni.'),
(1687730,58,23,56,12,'"Tulkaa, minä hankin viiniä, ryypätkäämme väkevätä; olkoon huomispäivä niinkuin tämäkin ylenpalttisen ihana."'),
(1687731,58,23,57,1,'Vanhurskas hukkuu, eikä kukaan pane sitä sydämelleen, hurskaat miehet otetaan pois kenenkään siitä välittämättä, sillä vanhurskas otetaan pois pahuutta näkemästä.'),
(1687732,58,23,57,2,'Hän menee rauhaan: jotka vakaasti vaeltavat, he saavat levätä kammioissansa.'),
(1687733,58,23,57,3,'Mutta te tulkaa tänne, te velhottaren lapset, te avionrikkojamiehen ja porttovaimon sikiöt.'),
(1687734,58,23,57,4,'Kenellä te iloanne pidätte? Kenelle avaatte suunne ammolleen ja kieltä pitkälle pistätte? Ettekö te ole rikoksen lapsia, valheen sikiöitä?'),
(1687735,58,23,57,5,'Te, jotka hehkutte himosta tammien varjossa, jokaisen vihreän puun alla, te, jotka teurastatte lapsia laaksoissa, kallionrotkoissa!'),
(1687736,58,23,57,6,'Laakson sileät paadet ovat sinun osasi, siinä se on, sinun arpasi; niille sinä olet juomauhrit vuodattanut, ruokauhrit uhrannut. Siihenkö minä tyytyisin!'),
(1687737,58,23,57,7,'Korkealle ja valtavalle vuorelle sinä valmistit vuoteesi; sinne sinä myös nousit teurasuhria uhraamaan.'),
(1687738,58,23,57,8,'Oven ja pihtipielen taakse sinä panit omat merkkisi. Sillä minusta luopuen sinä paljastit itsesi ja nousit vuoteellesi, teit sen tilavaksi; sinä sovit kaupoista heidän kanssaan, makasit heidän kanssaan mielelläsi, näit heidän häpynsä.'),
(1687739,58,23,57,9,'Sinä kuljit kuninkaan tykö öljyinesi, runsaine voiteinesi; sinä lähetit sanansaattajasi kauas, laskeuduit alas tuonelaan asti.'),
(1687740,58,23,57,10,'Sinä väsyit matkasi pituudesta, et kuitenkaan sanonut: "Turha vaiva!" Sinä sait elpynyttä voimaa, sentähden et heikoksi käynyt.'),
(1687741,58,23,57,11,'Ketä sinä arkailit ja pelkäsit, koska vilpistelit etkä minua muistanut, et minusta välittänyt? Eikö niin: minä olen ollut vaiti aina ikiajoista asti, ja niin et sinä minua pelkää?'),
(1687742,58,23,57,12,'Mutta minä ilmoitan, mitä on sinun vanhurskautesi ja sinun tekosi; ne eivät sinua auta.'),
(1687743,58,23,57,13,'Kun sinä huudat, auttakoon sinua jumaliesi joukko! Mutta tuuli vie ne kaikki, henkäys ottaa ne pois. Mutta joka minuun turvaa, se perii maan ja ottaa omaksensa minun pyhän vuoreni.'),
(1687744,58,23,57,14,'Hän sanoo: Tehkää, tehkää tie, tasoittakaa tie, poistakaa kompastuskivet minun kansani tieltä.'),
(1687745,58,23,57,15,'Sillä näin sanoo Korkea ja Ylhäinen, jonka asumus on iankaikkinen ja jonka nimi on Pyhä: Minä asun korkeudessa ja pyhyydessä ja niitten tykönä, joilla on särjetty ja nöyrä henki, että minä virvoittaisin nöyrien hengen ja saattaisin särjettyjen sydämet eläviksi.'),
(1687746,58,23,57,16,'Sillä en minä iankaiken riitele enkä vihastu ainiaaksi; muutoin henki nääntyisi minun kasvojeni edessä, ne sielut, jotka minä tehnyt olen.'),
(1687747,58,23,57,17,'Hänen ahneutensa synnin tähden minä vihastuin; minä löin häntä, kätkin itseni ja olin vihastunut. Mutta hän luopui minusta ja kulki oman sydämensä tietä.'),
(1687748,58,23,57,18,'Minä olen nähnyt hänen tiensä, mutta minä parannan hänet ja johdatan häntä ja annan jälleen lohdutuksen hänelle ja hänen surevillensa.'),
(1687749,58,23,57,19,'Minä luon huulten hedelmän, rauhan, rauhan kaukaisille ja läheisille, sanoo Herra, ja minä parannan hänet.'),
(1687750,58,23,57,20,'Mutta jumalattomat ovat kuin kuohuva meri, joka ei voi tyyntyä ja jonka aallot kuohuttavat muraa ja mutaa.'),
(1687751,58,23,57,21,'Jumalattomilla ei ole rauhaa, sanoo minun Jumalani.'),
(1687752,58,23,58,1,'Huuda täyttä kurkkua, älä säästä, korota äänesi niinkuin pasuna, ilmoita minun kansalleni heidän rikoksensa ja Jaakobin huoneelle heidän syntinsä.'),
(1687753,58,23,58,2,'Minua he muka etsivät joka päivä ja haluavat tietoa minun teistäni niinkuin kansa, joka tekee vanhurskautta eikä hylkää Jumalansa oikeutta. He vaativat minulta vanhurskaita tuomioita, haluavat, että Jumala heitä lähestyisi:'),
(1687754,58,23,58,3,'"Miksi me paastoamme, kun et sinä sitä näe, kuritamme itseämme, kun et sinä sitä huomaa?" Katso, paastopäivänänne te ajatte omia asioitanne ja ahdistatte työhön kaiken työväkenne.'),
(1687755,58,23,58,4,'Katso, riidaksi ja toraksi te paastoatte, lyödäksenne jumalattomalla nyrkillä. Te ette nyt paastoa niin, että teidän äänenne kuultaisiin korkeudessa.'),
(1687756,58,23,58,5,'Tällainenko on se paasto, johon minä mielistyn, se päivä, jona ihminen kurittaa itseänsä? Jos kallistaa päänsä kuin kaisla ja makaa säkissä ja tuhassa, sitäkö sinä sanot paastoksi ja päiväksi, joka on Herralle otollinen?'),
(1687757,58,23,58,6,'Eikö tämä ole paasto, johon minä mielistyn: että avaatte vääryyden siteet, irroitatte ikeen nuorat, ja päästätte sorretut vapaiksi, että särjette kaikki ikeet?'),
(1687758,58,23,58,7,'Eikö tämä: että taitat leipäsi isoavalle ja viet kurjat kulkijat huoneeseesi, kun näet alastoman, vaatetat hänet etkä kätkeydy siltä, joka on omaa lihaasi?'),
(1687759,58,23,58,8,'Silloin sinun valkeutesi puhkeaa esiin niinkuin aamurusko, ja haavasi kasvavat nopeasti umpeen; sinun vanhurskautesi käy sinun edelläsi, ja Jumalan kunnia seuraa suojanasi.'),
(1687760,58,23,58,9,'Silloin sinä rukoilet, ja Herra vastaa, sinä huudat, ja hän sanoo: "Katso, tässä minä olen". Jos sinä keskuudestasi poistat ikeen, sormella-osoittelun ja vääryyden puhumisen,'),
(1687761,58,23,58,10,'jos taritset elannostasi isoavalle ja ravitset vaivatun sielun, niin valkeus koittaa sinulle pimeydessä, ja sinun pilkkopimeäsi on oleva niinkuin keskipäivä.'),
(1687762,58,23,58,11,'Ja Herra johdattaa sinua alati ja ravitsee sinun sielusi kuivissa erämaissa; hän vahvistaa sinun luusi, ja sinä olet oleva niinkuin runsaasti kasteltu puutarha, niinkuin lähde, josta vesi ei koskaan puutu.'),
(1687763,58,23,58,12,'Sinun jälkeläisesi rakentavat jälleen ikivanhat rauniot, sinä kohotat perusmuurit, muinaisten polvien laskemat; ja sinun nimesi on oleva: "halkeamain umpeenmuuraaja" ja "teitten korjaaja maan asuttamiseksi".'),
(1687764,58,23,58,13,'Jos sinä pidätät jalkasi sapattia rikkomasta, niin ettet toimita omia asioitasi minun pyhäpäivänäni, vaan kutsut sapatin ilopäiväksi, Herran pyhäpäivän kunnioitettavaksi ja kunnioitat sitä, niin ettet toimita omia toimiasi, et aja omia asioitasi etkä puhu joutavia,'),
(1687765,58,23,58,14,'silloin on ilosi oleva Herrassa, ja minä kuljetan sinut maan kukkuloitten ylitse, ja minä annan sinun nauttia isäsi Jaakobin perintöosaa. Sillä Herran suu on puhunut.'),
(1687766,58,23,59,1,'Katso, ei Herran käsi ole liian lyhyt auttamaan, eikä hänen korvansa kuuro kuulemaan:'),
(1687767,58,23,59,2,'vaan teidän pahat tekonne erottavat teidät Jumalastanne, ja teidän syntinne peittävät teiltä hänen kasvonsa, niin ettei hän kuule.'),
(1687768,58,23,59,3,'Sillä teidän kätenne ovat tahratut verellä ja sormenne vääryydellä; teidän huulenne puhuvat valhetta, teidän kielenne latelee petosta.'),
(1687769,58,23,59,4,'Ei kukaan vaadi oikeuteen vanhurskaasti, eikä kukaan käräjöi rehellisesti. He turvautuvat tyhjään ja puhuvat vilppiä, kantavat kohdussaan tuhoa ja synnyttävät turmion.'),
(1687770,58,23,59,5,'Myrkkyliskon munia he hautovat, hämähäkin verkkoja he kutovat; joka niitä munia syö, se kuolee, rikkipoljetusta puhkeaa kyykäärme.'),
(1687771,58,23,59,6,'Heidän verkkonsa eivät kelpaa vaatteeksi, heidän tekemäänsä ei voi verhoutua; heidän työnsä ovat vääryyden töitä, ja heidän kätensä ovat täynnä väkivallan tekoa.'),
(1687772,58,23,59,7,'Heidän jalkansa juoksevat pahuuteen, kiiruhtavat vuodattamaan viatonta verta; heidän ajatuksensa ovat vääryyden ajatuksia, tuho ja turmio on heidän teillänsä.'),
(1687773,58,23,59,8,'Rauhan tietä he eivät tunne, oikeutta ei ole heidän askeleissansa; polkunsa he tekevät mutkaisiksi, ei kukaan, joka niitä käy, tunne rauhaa.'),
(1687774,58,23,59,9,'Sentähden on oikeus meistä kaukana, eikä vanhurskaus saavuta meitä; me odotamme valoa, mutta katso, on pimeä, aamunkoittoa, mutta vaellamme yön synkeydessä.'),
(1687775,58,23,59,10,'Me haparoimme seinää pitkin niinkuin sokeat, haparoimme niinkuin silmiä vailla; me kompastelemme sydänpäivällä niinkuin hämärässä, me olemme terveitten keskellä niinkuin kuolleet.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687776,58,23,59,11,'Me murisemme kaikki kuin karhut ja kujerramme kuin kyyhkyset; me odotamme oikeutta, mutta sitä ei tule, pelastusta, mutta se on kaukana meistä.'),
(1687777,58,23,59,12,'Sillä meidän rikoksemme ovat monilukuiset sinun edessäsi, ja meidän syntimme todistavat meitä vastaan; sillä meidän rikoksemme seuraavat meitä, ja pahat tekomme me tunnemme:'),
(1687778,58,23,59,13,'me olemme luopuneet Herrasta ja kieltäneet hänet, vetäytyneet pois Jumalaamme seuraamasta, puhuneet sortoa ja kapinaa, kantaneet kohdussamme ja purkaneet sisimmästämme valheen sanoja.'),
(1687779,58,23,59,14,'Oikeus työnnetään takaperin, ja vanhurskaus seisoo kaukana, sillä totuus kompastelee torilla, suoruus ei voi sisälle tulla.'),
(1687780,58,23,59,15,'Niin oli totuus kadonnut, ja joka pahasta luopui, se ryöstettiin paljaaksi. Herra näki sen, ja se oli hänen silmissänsä paha, ettei ollut oikeutta.'),
(1687781,58,23,59,16,'Ja hän näki, ettei ollut yhtäkään miestä, ja hän ihmetteli, ettei kukaan astunut väliin. Silloin hänen oma käsivartensa auttoi häntä, ja hänen vanhurskautensa häntä tuki.'),
(1687782,58,23,59,17,'Ja hän puki yllensä vanhurskauden kuin rintahaarniskan ja pani pelastuksen kypärin päähänsä, hän puki koston vaatteet puvuksensa ja verhoutui kiivauteen niinkuin viittaan.'),
(1687783,58,23,59,18,'Tekojen mukaan hän maksaa palkan: vihan vastustajillensa, koston vihollisillensa; merensaarille hän kostaa.'),
(1687784,58,23,59,19,'Ja päivän laskun äärillä he pelkäävät Herran nimeä ja päivän koittamilla hänen kunniaansa. Sillä se tulee kuin padottu virta, jota Herran henki ajaa eteenpäin.'),
(1687785,58,23,59,20,'Mutta Siionille se tulee lunastajana, niille Jaakobissa, jotka synnistä kääntyvät, sanoo Herra.'),
(1687786,58,23,59,21,'Ja tämä on minun liittoni heidän kanssansa, sanoo Herra: minun Henkeni, joka on sinun päälläsi, ja minun sanani, jonka minä suuhusi panen, eivät väisty sinun suustasi, eivät lastesi suusta eivätkä lastesi lasten suusta, sanoo Herra, nyt ja iankaikkisesti.'),
(1687787,58,23,60,1,'Nouse, ole kirkas, sillä sinun valkeutesi tulee, ja Herran kunnia koittaa sinun ylitsesi.'),
(1687788,58,23,60,2,'Sillä katso, pimeys peittää maan ja synkeys kansat, mutta sinun ylitsesi koittaa Herra, ja sinun ylläsi näkyy hänen kunniansa.'),
(1687789,58,23,60,3,'Kansat vaeltavat sinun valkeuttasi kohti, kuninkaat sinun koitteesi kirkkautta kohti.'),
(1687790,58,23,60,4,'Nosta silmäsi, katso ympärillesi: kaikki nämä ovat kokoontuneet, tulevat sinun tykösi; sinun poikasi tulevat kaukaa, sinun tyttäriäsi kainalossa kannetaan.'),
(1687791,58,23,60,5,'Silloin sinä saat sen nähdä, ja sinä loistat ilosta, sinun sydämesi sykkii ja avartuu, kun meren aarteet kääntyvät sinun tykösi, kansojen rikkaudet tulevat sinulle.'),
(1687792,58,23,60,6,'Kamelien paljous peittää sinut, Midianin ja Eefan varsat; kaikki tulevat Sabasta, kantavat kultaa ja suitsutusta ja Herran ylistystä ilmoittavat.'),
(1687793,58,23,60,7,'Kaikki Keedarin laumat kokoontuvat sinun tykösi, Nebajotin oinaat palvelevat sinua; minulle otollisina ne nousevat minun alttarilleni, ja minä kirkastan kirkkauteni huoneen.'),
(1687794,58,23,60,8,'Keitä ovat nuo, jotka lentävät niinkuin pilvet ja niinkuin kyyhkyset lakkoihinsa?'),
(1687795,58,23,60,9,'Merensaaret odottavat minua, ja etumaisina tulevat Tarsiin-laivat tuodakseen sinun lapsesi kaukaa; hopeansa ja kultansa heillä on mukanansa Herran, sinun Jumalasi, nimelle, Israelin Pyhälle, sillä hän kirkastaa sinut.'),
(1687796,58,23,60,10,'Ja muukalaiset rakentavat sinun muurisi, ja heidän kuninkaansa palvelevat sinua; sillä vihassani minä löin sinua, mutta mielisuosiossani minä sinua armahdan.'),
(1687797,58,23,60,11,'Sinun porttisi pidetään aina auki, ei niitä suljeta päivällä eikä yöllä, että kansojen rikkaudet tuotaisiin ja heidän kuninkaansa saatettaisiin sinun tykösi.'),
(1687798,58,23,60,12,'Sillä se kansa tai valtakunta, joka ei sinua palvele, hukkuu, ja ne kansat hävitetään perinjuurin.'),
(1687799,58,23,60,13,'Libanonin kunnia tulee sinun tykösi, kypressit, jalavat ynnä hopeakuuset, kaunistamaan minun pyhäkköni paikkaa, ja minä saatan jalkaini sijan kunniaan.'),
(1687800,58,23,60,14,'Ja kumarassa käyden tulevat sinun tykösi sinun sortajaisi pojat, ja kaikki sinun pilkkaajasi heittäytyvät sinun jalkaisi juureen. He nimittävät sinut "Herran kaupungiksi", "Israelin Pyhän Siioniksi".'),
(1687801,58,23,60,15,'Sen sijaan, että sinä olet ollut hyljätty ja vihattu, niin ettei ollut kauttasi kulkijaa, teen minä sinut korkeaksi iankaikkisesti, iloksi polvesta polveen.'),
(1687802,58,23,60,16,'Ja sinä saat imeä kansojen maidon, imeä kuningasten rintoja, saat tuntea, että minä, Herra, olen sinun auttajasi, että Jaakobin Väkevä on sinun lunastajasi.'),
(1687803,58,23,60,17,'Minä tuon vasken sijaan kultaa, ja raudan sijaan minä tuon hopeata, puun sijaan vaskea ja kiven sijaan rautaa. Ja minä panen sinulle esivallaksi rauhan ja käskijäksi vanhurskauden.'),
(1687804,58,23,60,18,'Ei kuulu enää väkivaltaa sinun maassasi, ei tuhoa, ei turmiota sinun rajaisi sisällä, ja sinä kutsut pelastuksen muuriksesi ja kiitoksen portiksesi.'),
(1687805,58,23,60,19,'Ei ole enää aurinko sinun valonasi päivällä, eikä valaise sinua kuun kumotus, vaan Herra on sinun iankaikkinen valkeutesi, ja sinun Jumalasi sinun kirkkautesi.'),
(1687806,58,23,60,20,'Ei sinun aurinkosi enää laske, eikä sinun kuusi vajene, sillä Herra on sinun iankaikkinen valkeutesi, ja päättyneet ovat sinun murheesi päivät.'),
(1687807,58,23,60,21,'Sinun kansassasi ovat kaikki vanhurskaita, he saavat periä maan iankaikkisesti, he, minun istutukseni vesa, minun kätteni teko, minun kirkkauteni ilmoitukseksi.'),
(1687808,58,23,60,22,'Pienimmästä kasvaa heimo, vähäisimmästä väkevä kansa. Minä, Herra, sen aikanansa nopeasti täytän.'),
(1687809,58,23,61,1,'Herran, Herran Henki on minun päälläni, sillä hän on voidellut minut julistamaan ilosanomaa nöyrille, lähettänyt minut sitomaan särjettyjä sydämiä, julistamaan vangituille vapautusta ja kahlituille kirvoitusta,'),
(1687810,58,23,61,2,'julistamaan Herran otollista vuotta ja meidän Jumalamme kostonpäivää, lohduttamaan kaikkia murheellisia,'),
(1687811,58,23,61,3,'panemaan Siionin murheellisten päähän - antamaan heille - juhlapäähineen tuhkan sijaan, iloöljyä murheen sijaan, ylistyksen vaipan masentuneen hengen sijaan; ja heidän nimensä on oleva "vanhurskauden tammet", "Herran istutus", hänen kirkkautensa ilmoitukseksi.'),
(1687812,58,23,61,4,'Ja he rakentavat jälleen ikivanhat rauniot, kohottavat ennalleen esi-isien autiot paikat; ja he uudistavat rauniokaupungit, jotka ovat olleet autiot polvesta polveen.'),
(1687813,58,23,61,5,'Vieraat ovat teidän laumojenne paimenina, muukalaiset teidän peltomiehinänne ja viinitarhureinanne.'),
(1687814,58,23,61,6,'Mutta teitä kutsutaan Herran papeiksi, sanotaan meidän Jumalamme palvelijoiksi; te saatte nauttia kansain rikkaudet ja periä heidän kunniansa.'),
(1687815,58,23,61,7,'Häpeänne hyvitetään teille kaksin kerroin, ja pilkatut saavat riemuita osastansa. Niin he saavat kaksinkertaisen perinnön maassansa; heillä on oleva iankaikkinen ilo.'),
(1687816,58,23,61,8,'Sillä minä, Herra, rakastan oikeutta, vihaan vääryyttä ja ryöstöä; ja minä annan heille palkan uskollisesti ja teen heidän kanssansa iankaikkisen liiton.'),
(1687817,58,23,61,9,'Heidän siemenensä tulee tunnetuksi kansain keskuudessa ja heidän jälkeläisensä kansakuntien keskellä; kaikki, jotka näkevät heitä, tuntevat heidät Herran siunaamaksi siemeneksi.'),
(1687818,58,23,61,10,'Minä iloitsen suuresti Herrassa, minun sieluni riemuitsee minun Jumalassani, sillä hän pukee minun ylleni autuuden vaatteet ja verhoaa minut vanhurskauden viittaan, yljän kaltaiseksi, joka kantaa juhlapäähinettä niinkuin pappi, ja morsiamen kaltaiseksi, joka on koruillansa kaunistettu.'),
(1687819,58,23,61,11,'Sillä niinkuin maa tuottaa kasvunsa ja niinkuin kasvitarha saa siemenkylvönsä versomaan, niin saattaa Herra, Herra versomaan vanhurskauden ja kiitoksen kaikkien kansojen nähden.'),
(1687820,58,23,62,1,'Siionin tähden minä en voi vaieta, ja Jerusalemin tähden en lepoa saa, ennenkuin sen vanhurskaus nousee kuin aamunkoi ja sen autuus kuin palava tulisoihtu.'),
(1687821,58,23,62,2,'Ja kansat näkevät sinun vanhurskautesi, kaikki kuninkaat sinun kunniasi; ja sinulle annetaan uusi nimi, jonka Herran suu säätää.'),
(1687822,58,23,62,3,'Sinä tulet kauniiksi kruunuksi Herran kädessä ja kuninkaalliseksi päähineeksi Jumalasi kädessä.'),
(1687823,58,23,62,4,'Ei sinua enää sanota "hyljätyksi", eikä sinun maatasi enää sanota "autioksi"; vaan sinua kutsutaan "minun rakkaakseni" ja sinun maatasi "aviovaimoksi", sillä Herra rakastaa sinua, ja sinun maasi otetaan avioksi.'),
(1687824,58,23,62,5,'Sillä niinkuin nuori mies ottaa neitsyen avioksi, niin sinun lapsesi ottavat sinut omaksensa; ja niinkuin ylkä iloitsee morsiamesta, niin sinun Jumalasi iloitsee sinusta.'),
(1687825,58,23,62,6,'Sinun muureillesi, Jerusalem, minä asetan vartijat; älkööt he milloinkaan vaietko, ei päivällä eikä yöllä. Te, jotka ylistätte Herraa, älkää itsellenne lepoa suoko.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687826,58,23,62,7,'Älkää antako hänelle lepoa, ennenkuin hän on asettanut ennallensa Jerusalemin, tehnyt sen ylistykseksi maassa.'),
(1687827,58,23,62,8,'Herra on vannonut oikean kätensä ja väkevyytensä käsivarren kautta: En totisesti minä enää anna jyviäsi sinun vihollistesi ruuaksi, eivätkä juo enää muukalaiset sinun viiniäsi, josta sinä olet vaivan nähnyt.'),
(1687828,58,23,62,9,'Vaan jotka viljan kokoavat, ne sen syövät ja ylistävät Herraa; ja jotka viinin korjaavat, ne sen juovat minun pyhissä esikartanoissani.'),
(1687829,58,23,62,10,'Käykää, käykää ulos porteista, tasoittakaa kansalle tie, tehkää, tehkää valtatie, raivatkaa kivet pois, kohottakaa lippu kansoille.'),
(1687830,58,23,62,11,'Katso, Herra on kuuluttanut maan ääriin asti: Sanokaa tytär Siionille: Katso, sinun pelastuksesi tulee. Katso, hänen palkkansa on hänen mukanansa, hänen työnsä ansio käy hänen edellänsä.'),
(1687831,58,23,62,12,'Ja heitä kutsutaan "pyhäksi kansaksi", "Herran lunastetuiksi"; ja sinua kutsutaan "halutuksi", "kaupungiksi, joka ei ole hyljätty".'),
(1687832,58,23,63,1,'Kuka tuolla tulee Edomista, tulipunaisissa vaatteissa Bosrasta, tuo puvultansa komea, joka uljaana astelee suuressa voimassansa? "Minä, joka puhun vanhurskautta, joka olen voimallinen auttamaan."'),
(1687833,58,23,63,2,'Miksi on punaa sinun puvussasi, miksi ovat vaatteesi kuin viinikuurnan polkijan?'),
(1687834,58,23,63,3,'"Kuurnan minä poljin, minä yksinäni, ei ketään kansojen joukosta ollut minun kanssani; minä poljin heidät vihassani, tallasin heidät kiivaudessani, ja niin pirskui heidän vertansa vaatteilleni, ja minä tahrasin koko pukuni.'),
(1687835,58,23,63,4,'Sillä koston päivä oli minun mielessäni ja minun lunastettujeni vuosi oli tullut.'),
(1687836,58,23,63,5,'Ja minä katselin, mutta ei ollut auttajaa, ja minä ihmettelin, kun ei kukaan tueksi tullut. Silloin minun oma käsivarteni minua auttoi, ja minun vihani minua tuki.'),
(1687837,58,23,63,6,'Ja minä tallasin kansat vihassani ja juovutin heidät kiivaudellani; minä vuodatin maahan heidän verensä."'),
(1687838,58,23,63,7,'Herran armotöitä minä julistan, Herran ylistettäviä tekoja, kaikkea, mitä Herra on meille tehnyt, suurta hyvyyttä Israelin heimoa kohtaan, mitä hän on heille osoittanut laupeudessansa ja suuressa armossansa.'),
(1687839,58,23,63,8,'Ja hän sanoi: "Ovathan he minun kansani, he ovat lapsia, joissa ei ole vilppiä"; ja niin hän tuli heille vapahtajaksi.'),
(1687840,58,23,63,9,'Kaikissa heidän ahdistuksissansa oli hänelläkin ahdistus, ja hänen kasvojensa enkeli vapahti heidät. Rakkaudessaan ja sääliväisyydessään hän lunasti heidät, nosti heitä ja kantoi heitä kaikkina muinaisina päivinä.'),
(1687841,58,23,63,10,'Mutta he niskoittelivat ja saattoivat murheelliseksi hänen Pyhän Henkensä; ja niin hän muuttui heidän viholliseksensa, hän itse soti heitä vastaan.'),
(1687842,58,23,63,11,'Silloin hänen kansansa muisti muinaisia päiviä, muisti Moosesta: Missä on hän, joka toi heidät ylös merestä, heidät ynnä hänen laumansa paimenen? Missä on hän, joka pani tämän sydämeen Pyhän Henkensä;'),
(1687843,58,23,63,12,'hän, joka antoi kunniansa käsivarren kulkea Mooseksen oikealla puolella, joka halkaisi vedet heidän edestänsä tehdäkseen itsellensä iankaikkisen nimen;'),
(1687844,58,23,63,13,'hän, joka kuljetti heitä syvyyksissä niinkuin hevosia erämaassa, eivätkä he kompastelleet?'),
(1687845,58,23,63,14,'Niinkuin karja astuu alas laaksoon, niin vei Herran Henki heidät lepoon. Niin sinä olet kansaasi johdattanut, tehdäksesi itsellesi kunniallisen nimen.'),
(1687846,58,23,63,15,'Katsele taivaasta, katso pyhyytesi ja kirkkautesi asunnosta. Missä on sinun kiivautesi ja voimalliset tekosi? Sinun sydämesi sääli ja sinun armahtavaisuutesi ovat minulta sulkeutuneet.'),
(1687847,58,23,63,16,'Sinähän olet meidän isämme, sillä Aabraham ei meistä tiedä eikä Israel meitä tunne: sinä, Herra, olet meidän isämme; "meidän Lunastajamme" on ikiajoista sinun nimesi.'),
(1687848,58,23,63,17,'Miksi sallit meidän eksyä pois sinun teiltäsi, Herra, ja annoit meidän sydämemme paatua, niin ettemme sinua pelkää? Palaja takaisin palvelijaisi tähden, perintöosasi sukukuntain tähden.'),
(1687849,58,23,63,18,'Vähän aikaa vain sinun pyhä kansasi sai pitää perintönsä; meidän ahdistajamme ovat tallanneet sinun pyhäkkösi.'),
(1687850,58,23,63,19,'Me olemme niinkuin ne, joita sinä et ole ikinä hallinnut, olemme, niinkuin ei meitä olisi otettu sinun nimiisi.'),
(1687851,58,23,64,1,'Oi, jospa sinä halkaisisit taivaat ja astuisit alas, niin että vuoret järkkyisivät sinun edessäsi, niinkuin risut leimahtavat tuleen, niinkuin vesi tulella kiehuu,'),
(1687852,58,23,64,2,'että tekisit nimesi tunnetuksi vastustajillesi ja kansat vapisisivat sinun kasvojesi edessä,'),
(1687853,58,23,64,3,'kun sinä teet peljättäviä tekoja, joita emme odottaa voineet! Oi, jospa astuisit alas, niin että vuoret järkkyisivät sinun edessäsi!'),
(1687854,58,23,64,4,'Ei ole ikiajoista kuultu, ei ole korviin tullut, ei ole silmä nähnyt muuta Jumalaa, paitsi sinut, joka senkaltaisia tekisi häntä odottavalle.'),
(1687855,58,23,64,5,'Sinä käyt niitä kohden, jotka ilolla vanhurskautta tekevät ja jotka sinun teilläsi sinua muistavat. Katso, sinä vihastuit, ja me jouduimme synnin alaisiksi; niin on ollut ikiajoista asti - saammeko avun?'),
(1687856,58,23,64,6,'Kaikki me olimme kuin saastaiset, ja niinkuin tahrattu vaate oli kaikki meidän vanhurskautemme. Ja kaikki me olemme lakastuneet kuin lehdet, ja pahat tekomme heittelevät meitä niinkuin tuuli.'),
(1687857,58,23,64,7,'Ei ole ketään, joka avukseen huutaa sinun nimeäsi, joka herää pitämään sinusta kiinni; sillä sinä olet peittänyt kasvosi meiltä, jättänyt meidät menehtymään syntiemme valtaan.'),
(1687858,58,23,64,8,'Mutta olethan sinä, Herra, meidän isämme; me olemme savi, ja sinä olet meidän valajamme, kaikki me olemme sinun kättesi tekoa.'),
(1687859,58,23,64,9,'Älä, Herra, vihastu ylenmäärin, äläkä ainiaan muistele pahoja tekoja. Katso ja huomaa, että me kaikki olemme sinun kansasi.'),
(1687860,58,23,64,10,'Sinun pyhät kaupunkisi ovat tulleet erämaaksi, Siion on erämaaksi tullut, Jerusalem autioksi.'),
(1687861,58,23,64,11,'Meidän pyhä ja ihana temppelimme, jossa isämme sinua ylistivät, on tulella poltettu, ja rauniona on kaikki meille kallisarvoinen.'),
(1687862,58,23,64,12,'Vaikka nämä näin ovat, voitko, Herra, pidättää itsesi, voitko olla vaiti ja vaivata meitä ylenmäärin?'),
(1687863,58,23,65,1,'Minä olen suostunut niiden etsittäväksi, jotka eivät minua kysyneet, niiden löydettäväksi, jotka eivät minua etsineet; minä olen sanonut kansalle, joka ei ole otettu minun nimiini: Tässä minä olen, tässä minä olen!'),
(1687864,58,23,65,2,'Koko päivän minä olen ojentanut käsiäni uppiniskaista kansaa kohden, joka vaeltaa tietä, mikä ei ole hyvä, omain ajatustensa mukaan;'),
(1687865,58,23,65,3,'kansaa kohden, joka vihoittaa minua alinomaa, vasten kasvojani, uhraa puutarhoissa ja suitsuttaa tiilikivialttareilla.'),
(1687866,58,23,65,4,'He asustavat haudoissa ja yöpyvät salaisiin paikkoihin; he syövät sianlihaa, ja saastaiset liemet on heillä astioissansa.'),
(1687867,58,23,65,5,'He sanovat: "Pysy erilläsi, älä tule minua lähelle, sillä minä olen sinulle pyhä". Nämä ovat savu minun sieramissani, tuli, joka palaa kaiken päivää.'),
(1687868,58,23,65,6,'Katso, se on kirjoitettuna minun edessäni. En ole minä vaiti, vaan minä maksan, maksan heille helmaan'),
(1687869,58,23,65,7,'heidän pahat tekonsa ynnä teidän isienne pahat teot, sanoo Herra, niiden, jotka ovat vuorilla suitsuttaneet ja kukkuloilla minua häväisseet; ja ensiksi minä mittaan heille palkan heidän helmaansa.'),
(1687870,58,23,65,8,'Näin sanoo Herra: Niinkuin sanotaan rypäleestä, jos siinä on mehua: "Älä hävitä sitä, sillä siinä on siunaus", niin teen minä palvelijaini tähden, etten kaikkea hävittäisi.'),
(1687871,58,23,65,9,'Minä tuotan Jaakobista siemenen ja Juudasta vuorteni perillisen; ja minun valittuni saavat periä maan, ja minun palvelijani saavat siinä asua.'),
(1687872,58,23,65,10,'Ja Saaron on oleva lammasten laitumena ja Aakorin laakso karjan lepopaikkana minun kansallani, joka minua etsii.'),
(1687873,58,23,65,11,'Mutta te, jotka hylkäätte Herran ja unhotatte minun pyhän vuoreni, jotka valmistatte Gadille pöydän ja vuodatatte uhrijuomaa Menille -'),
(1687874,58,23,65,12,'teidät minä määrään miekan omiksi, ja kaikki te kumarrutte teurastettaviksi, sentähden ettette vastanneet, kun minä kutsuin, ettekä kuulleet, kun minä puhuin, vaan teitte sitä, mikä on pahaa minun silmissäni, ja valitsitte sen, mikä ei ole minulle otollista.'),
(1687875,58,23,65,13,'Sentähden, näin sanoo Herra, Herra: Katso, minun palvelijani syövät, mutta te näette nälkää; katso, minun palvelijani juovat, mutta te kärsitte janoa; katso, minun palvelijani iloitsevat, mutta te joudutte häpeään.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687876,58,23,65,14,'Katso, minun palvelijani riemuitsevat sydämen onnesta, mutta te huudatte sydämen tuskasta ja voivotatte mielimurteissanne.'),
(1687877,58,23,65,15,'Ja te jätätte nimenne kirouslauseeksi minun valituilleni: "Niin sinut surmatkoon Herra, Herra!" Mutta palvelijoilleen hän on antava toisen nimen.'),
(1687878,58,23,65,16,'Joka maassa itsensä siunaa, siunaa itsensä totisen Jumalan nimeen, ja joka maassa vannoo, vannoo totisen Jumalan nimeen; sillä entiset ahdistukset ovat unhotetut ja peitossa minun silmiltäni.'),
(1687879,58,23,65,17,'Sillä katso, minä luon uudet taivaat ja uuden maan. Entisiä ei enää muisteta, eivätkä ne enää ajatukseen astu;'),
(1687880,58,23,65,18,'vaan te saatte iloita ja riemuita iankaikkisesti siitä, mitä minä luon. Sillä katso, iloksi luon minä Jerusalemin, riemuksi sen kansan.'),
(1687881,58,23,65,19,'Minä iloitsen Jerusalemista ja riemuitsen kansastani; eikä siellä enää kuulla itkun ääntä eikä valituksen ääntä.'),
(1687882,58,23,65,20,'Ei siellä ole enää lasta, joka eläisi vain muutaman päivän, ei vanhusta, joka ei täyttäisi päiviensä määrää; sillä nuorin kuolee satavuotiaana, ja vasta satavuotiaana synnintekijä joutuu kiroukseen.'),
(1687883,58,23,65,21,'He rakentavat taloja ja asuvat niissä, he istuttavat viinitarhoja ja syövät niiden hedelmät;'),
(1687884,58,23,65,22,'he eivät rakenna muitten asua, eivät istuta muitten syödä; sillä niinkuin puitten päivät ovat, niin ovat elinpäivät minun kansassani. Minun valittuni kuluttavat itse kättensä työn.'),
(1687885,58,23,65,23,'He eivät tee työtä turhaan eivätkä lapsia synnytä äkkikuoleman omiksi, sillä he ovat Herran siunattujen siemen, ja heidän vesansa ovat heidän tykönänsä.'),
(1687886,58,23,65,24,'Ennenkuin he huutavat, minä vastaan, heidän vielä puhuessaan minä kuulen.'),
(1687887,58,23,65,25,'Susi ja lammas käyvät yhdessä laitumella, ja leijona syö rehua niinkuin raavas, ja käärmeen ruokana on maan tomu; ei missään minun pyhällä vuorellani tehdä pahaa eikä vahinkoa, sanoo Herra.'),
(1687888,58,23,66,1,'Näin sanoo Herra: Taivas on minun valtaistuimeni, ja maa on minun jalkojeni astinlauta. Mikä olisi huone, jonka te minulle rakentaisitte, mikä paikka olisi minun leposijani?'),
(1687889,58,23,66,2,'Minun käteni on kaikki nämä tehnyt, ja niin ovat kaikki nämä syntyneet, sanoo Herra. Mutta minä katson sen puoleen, joka on nöyrä, jolla on särjetty henki ja arka tunto minun sanani edessä.'),
(1687890,58,23,66,3,'Joka teurastaa härän, mutta myös tappaa miehen, joka uhraa lampaan, mutta myös taittaa koiralta niskan, joka uhraa ruokauhrin, mutta myös sian verta, joka polttaa suitsuketta, mutta myös ylistää epäjumalaa: nämä ovat valinneet omat tiensä. Ja niinkuin heidän sielunsa on mielistynyt heidän iljetyksiinsä,'),
(1687891,58,23,66,4,'niin minäkin valitsen heidän vaivaamisensa ja annan heille tulla sen, mitä he pelkäävät, koska ei kukaan vastannut, kun minä kutsuin, koska he eivät kuulleet, kun minä puhuin, vaan tekivät sitä, mikä on pahaa minun silmissäni, ja valitsivat sen, mikä ei ole minulle otollista.'),
(1687892,58,23,66,5,'Kuulkaa Herran sana, te, jotka olette aralla tunnolla hänen sanansa edessä: Teidän veljenne, jotka vihaavat teitä ja työntävät teidät luotaan minun nimeni tähden, sanovat: "Osoittakoon Herra kunniansa, että me näemme teidän ilonne!" Mutta he joutuvat häpeään.'),
(1687893,58,23,66,6,'Metelin ääni kaupungista! Ääni temppelistä! Herran ääni: hän maksaa palkan vihollisillensa!'),
(1687894,58,23,66,7,'Ennenkuin Siion kipuja tuntee, hän synnyttää; ennenkuin hänelle tuskat tulevat, hän saa poikalapsen.'),
(1687895,58,23,66,8,'Kuka on sellaista kuullut, kuka senkaltaista nähnyt? Syntyykö maa yhden päivän kivulla, tahi synnytetäänkö kansa yhdellä haavaa? Siionhan tunsi kipuja ja samalla jo synnytti lapsensa.'),
(1687896,58,23,66,9,'Minäkö avaisin kohdun sallimatta synnyttää, sanoo Herra, tahi minäkö, joka saatan synnyttämään, sulkisin kohdun?'),
(1687897,58,23,66,10,'Iloitkaa Jerusalemin kanssa ja riemuitkaa hänestä kaikki, jotka häntä rakastatte; iloitsemalla iloitkaa hänen kanssaan, te, jotka olette hänen tähtensä surreet,'),
(1687898,58,23,66,11,'että imisitte ja tulisitte ravituiksi hänen lohdutuksensa rinnoista, että joisitte ja virkistyisitte hänen kunniansa runsaudesta.'),
(1687899,58,23,66,12,'Sillä näin sanoo Herra: Minä ohjaan hänen tykönsä rauhan niinkuin virran ja kansojen kunnian niinkuin tulvajoen. Ja te saatte imeä, kainalossa teitä kannetaan, ja polvilla pitäen teitä hyväillään.'),
(1687900,58,23,66,13,'Niinkuin äiti lohduttaa lastansa, niin minä lohdutan teitä, ja Jerusalemissa te saatte lohdutuksen.'),
(1687901,58,23,66,14,'Te näette sen, ja teidän sydämenne iloitsee, ja teidän luunne virkistyvät kuin vihanta ruoho; ja Herran käsi tulee tunnetuksi hänen palvelijoissansa, mutta vihollistensa hän antaa tuntea vihansa.'),
(1687902,58,23,66,15,'Sillä katso, Herra tulee tulessa, ja hänen vaununsa ovat kuin myrskytuuli; ja hän antaa vihansa purkautua hehkussa ja nuhtelunsa tulenliekeissä.'),
(1687903,58,23,66,16,'Herra käy tuomiolle kaiken lihan kanssa tulella ja miekallaan; ja Herran surmaamia on oleva paljon.'),
(1687904,58,23,66,17,'Jotka pyhittäytyvät ja puhdistautuvat puutarha-menoja varten, seuraten miestä, joka on heidän keskellänsä, jotka syövät sianlihaa ja muuta inhottavaa sekä hiiriä, niistä kaikista tulee loppu, sanoo Herra.'),
(1687905,58,23,66,18,'Minä tunnen heidän tekonsa ja ajatuksensa. Aika tulee, että minä kokoan kaikki kansat ja kielet, ja he tulevat ja näkevät minun kunniani.'),
(1687906,58,23,66,19,'Ja minä teen tunnusteon heidän keskellänsä ja lähetän pakoonpäässeitä heidän joukostansa pakanain tykö Tarsiiseen, Puuliin ja Luudiin, jousenjännittäjäin tykö, Tuubaliin ja Jaavaniin, kaukaisiin merensaariin, jotka eivät ole kuulleet minusta kerrottavan eivätkä nähneet minun kunniaani, ja he ilmoittavat minun kunniani pakanain keskuudessa.'),
(1687907,58,23,66,20,'Ja he tuovat kaikki teidän veljenne kaikista kansoista uhrilahjana Herralle hevosilla, vaunuilla, kantotuoleilla, muuleilla ja ratsukameleilla minun pyhälle vuorelleni Jerusalemiin, sanoo Herra, niinkuin israelilaiset tuovat ruokauhrin puhtaassa astiassa Herran temppeliin.'),
(1687908,58,23,66,21,'Ja heitäkin minä otan leeviläisiksi papeiksi, sanoo Herra.'),
(1687909,58,23,66,22,'Niinkuin uudet taivaat ja uusi maa, jotka minä teen, pysyvät minun kasvojeni edessä, sanoo Herra, niin pysyy teidän siemenenne ja teidän nimenne.'),
(1687910,58,23,66,23,'Joka kuukausi uudenkuun päivänä ja joka viikko sapattina tulee kaikki liha kumartaen rukoilemaan minua, sanoo Herra.'),
(1687911,58,24,1,1,'Jeremian, Hilkian pojan, sanat. Tämä oli Anatotissa, Benjaminin maassa, asuvia pappeja.'),
(1687912,58,24,1,2,'Hänelle tuli Herran sana Juudan kuninkaan Joosian, Aamonin pojan, päivinä, tämän kolmantenatoista hallitusvuotena,'),
(1687913,58,24,1,3,'ja tuli vielä Juudan kuninkaan Joojakimin, Joosian pojan, päivinä ja aina Juudan kuninkaan Sidkian, Joosian pojan, yhdennentoista vuoden loppumiseen asti, jolloin Jerusalemin asukkaat viidentenä kuukautena vietiin pakkosiirtolaisuuteen.'),
(1687914,58,24,1,4,'Minulle tuli tämä Herran sana:'),
(1687915,58,24,1,5,'"Jo ennenkuin minä valmistin sinut äidin kohdussa, minä sinut tunsin, ja ennenkuin sinä äidistä synnyit, minä sinut pyhitin; minä asetin sinut kansojen profeetaksi".'),
(1687916,58,24,1,6,'Mutta minä sanoin: "Voi Herra, Herra! Katso, en minä kykene puhumaan, sillä minä olen nuori."'),
(1687917,58,24,1,7,'Niin Herra sanoi minulle: "Älä sano: ''Minä olen nuori'', vaan mene, kunne ikinä minä sinut lähetän, ja puhu kaikki, mitä minä käsken sinun puhua.'),
(1687918,58,24,1,8,'Älä pelkää heitä, sillä minä olen sinun kanssasi ja pelastan sinut, sanoo Herra."'),
(1687919,58,24,1,9,'Ja Herra ojensi kätensä ja kosketti minun suutani. Ja Herra sanoi minulle: "Katso, minä panen sanani sinun suuhusi.'),
(1687920,58,24,1,10,'Katso, minä asetan sinut tänä päivänä yli kansojen ja valtakuntain, repimään maasta ja hajottamaan, hävittämään ja kukistamaan, rakentamaan ja istuttamaan."'),
(1687921,58,24,1,11,'Minulle tuli tämä Herran sana: "Mitä sinä näet, Jeremia?" Minä vastasin: "Minä näen mantelipuun oksan".'),
(1687922,58,24,1,12,'Herra sanoi minulle: "Sinä olet nähnyt oikein; sillä minä valvon sanaani toteuttaakseni sen".'),
(1687923,58,24,1,13,'Minulle tuli toistamiseen Herran sana, näin kuuluva: "Mitä sinä näet?" Minä vastasin: "Minä näen kiehuvan padan; se näkyy pohjoisen puolelta".'),
(1687924,58,24,1,14,'Ja Herra sanoi minulle: "Pohjoisesta on onnettomuus purkautuva kaikkien maan asukasten yli.'),
(1687925,58,24,1,15,'Sillä katso, minä kutsun kaikki pohjoisten valtakuntain kansanheimot, sanoo Herra, ja ne tulevat ja asettavat kukin valtaistuimensa Jerusalemin porttien oville ja kaikkia sen muureja vastaan, yltympäri, ja kaikkia Juudan kaupunkeja vastaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687926,58,24,1,16,'Sitten minä julistan heille tuomioni kaikesta heidän pahuudestaan, koska he ovat hyljänneet minut, polttaneet uhreja muille jumalille ja kumartaneet kättensä tekoja.'),
(1687927,58,24,1,17,'Mutta sinä, vyötä kupeesi, nouse ja puhu heille kaikki, mitä minä käsken sinun puhua. Älä heitä kauhistu, etten minä kauhistuttaisi sinua heidän edessään.'),
(1687928,58,24,1,18,'Sillä katso, minä teen sinusta tänä päivänä varustetun kaupungin, rautapatsaan ja vaskimuurin koko maata vastaan, Juudan kuninkaita, sen ruhtinaita, sen pappeja vastaan ja maan kansaa vastaan.'),
(1687929,58,24,1,19,'Ja he sotivat sinua vastaan, mutta eivät voita sinua, sillä minä olen sinun kanssasi, sanoo Herra, ja pelastan sinut."'),
(1687930,58,24,2,1,'Ja minulle tuli tämä Herran sana:'),
(1687931,58,24,2,2,'"Mene ja julista Jerusalemin kuullen ja sano: Näin sanoo Herra: Minä muistan sinun nuoruutesi armauden, morsiusaikasi rakkauden, kuinka sinä seurasit minua erämaassa, maassa, jossa ei kylvöä tehdä.'),
(1687932,58,24,2,3,'Herralle pyhitetty oli Israel, hänen satonsa esikoinen. Kaikki, jotka sitä söivät, joutuivat syynalaisiksi; onnettomuus kohtasi heitä, sanoo Herra.'),
(1687933,58,24,2,4,'Kuulkaa Herran sana, Jaakobin heimo ja kaikki Israelin heimon sukukunnat.'),
(1687934,58,24,2,5,'Näin sanoo Herra: Mitä vääryyttä teidän isänne minusta löysivät, koska he erkanivat kauas minusta ja lähtivät seuraamaan turhia jumalia ja turhanpäiväisiksi tulivat.'),
(1687935,58,24,2,6,'He eivät kysyneet: ''Missä on Herra, joka toi meidät pois Egyptin maasta, joka johdatti meitä erämaassa, arojen ja kuilujen maassa, kuivuuden ja synkeyden maassa, maassa, jossa ei kukaan kulje eikä yksikään ihminen asu?'''),
(1687936,58,24,2,7,'Minä toin teidät hedelmätarhojen maahan syömään sen hedelmää ja hyvyyttä, mutta sinne tultuanne te saastutitte minun maani ja teitte minun perintöosani kauhistukseksi.'),
(1687937,58,24,2,8,'Papit eivät kysyneet: ''Missä on Herra?'' Lainkäyttäjät eivät minua tunteneet, ja paimenet luopuivat minusta; profeetat ennustivat Baalin nimessä ja seurasivat niitä, joista ei apua ole.'),
(1687938,58,24,2,9,'Sentähden minä vielä käyn oikeutta teidän kanssanne, sanoo Herra, ja teidän lastenne lasten kanssa minä käyn oikeutta.'),
(1687939,58,24,2,10,'Menkää kittiläisten saarille katsomaan ja lähettäkää Keedariin panemaan tarkoin merkille ja katsomaan, onko senkaltaista tapahtunut.'),
(1687940,58,24,2,11,'Onko mikään pakanakansa vaihtanut jumalia, vaikka ne eivät olekaan jumalia? Mutta minun kansani on vaihtanut kunniansa siihen, josta ei apua ole.'),
(1687941,58,24,2,12,'Hämmästykää tästä, te taivaat, kauhistukaa, peräti tyrmistykää, sanoo Herra.'),
(1687942,58,24,2,13,'Sillä minun kansani on tehnyt kaksinkertaisen synnin: minut, elävän veden lähteen, he ovat hyljänneet, ja ovat hakanneet itselleen vesisäiliöitä, särkyviä säiliöitä, jotka eivät vettä pidä.'),
(1687943,58,24,2,14,'Onko Israel ostettu orja tai kotona syntynyt? Minkätähden hän on joutunut saaliiksi?'),
(1687944,58,24,2,15,'Häntä vastaan kiljuivat nuoret leijonat, antoivat äänensä kuulua; ne tekivät hänen maansa autioksi, hänen kaupunkinsa hävitettiin asujattomiksi.'),
(1687945,58,24,2,16,'Myöskin noofilaiset ja tahpanheelaiset pitivät sinun päälakeasi laitumenansa.'),
(1687946,58,24,2,17,'Eikö tee tätä sinulle se, että sinä hylkäät Herran, sinun Jumalasi, silloin kun hän tahtoo sinua tiellä kuljettaa?'),
(1687947,58,24,2,18,'Ja nyt, mitä menemistä sinulla on Egyptiin juomaan Siihorin vettä? Ja mitä menemistä sinulla on Assuriin juomaan Eufrat-virran vettä?'),
(1687948,58,24,2,19,'Sinun pahuutesi tuottaa sinulle kurituksen, ja luopumuksesi saattaa sinut rangaistukseen; niin tiedä ja näe, kuinka onnetonta ja katkeraa se on, että sinä hylkäät Herran, sinun Jumalasi, etkä minua pelkää, sanoo Herra, Herra Sebaot.'),
(1687949,58,24,2,20,'Sillä jo ammoisista ajoista sinä olet särkenyt ikeesi, katkaissut siteesi ja sanonut: ''En tahdo palvella''. Sillä kaikilla korkeilla kukkuloilla ja kaikkien viheriäin puitten alla sinä porttona viruit.'),
(1687950,58,24,2,21,'Minä olin istuttanut sinut jaloksi viiniköynnökseksi, puhtaimmasta siemenestä; kuinka olet muuttunut minulle vieraan viinipuun villiköynnöksiksi?'),
(1687951,58,24,2,22,'Vaikka pesisit itsesi saippualla ja käyttäisit paljon lipeätä, saastaiseksi jää sittenkin sinun syntisi minun edessäni, sanoo Herra, Herra.'),
(1687952,58,24,2,23,'Kuinka saatat sanoa: ''En ole saastuttanut itseäni, en ole baaleja seurannut''! Katso menoasi laaksossa, huomaa, mitä olet tehnyt, sinä nopea, nuori naaraskameli, joka juokset sinne ja tänne;'),
(1687953,58,24,2,24,'sinä villiaasi, erämaahan tottunut, joka himossasi ilmaa ahmit! Kuka hillitsee sen kiiman? Joka sitä etsii, sen ei tarvitse väsyttää itseään; sen löytää, kun tulee sen kuukausi.'),
(1687954,58,24,2,25,'Varo, ettet juokse jalkaasi anturattomaksi ja kurkkuasi janoiseksi. Mutta sinä sanot: ''Se on turhaa! Ei! Sillä minä rakastan vieraita ja niitä minä seuraan.'''),
(1687955,58,24,2,26,'Niinkuin teosta tavattu varas on häpeissänsä, niin joutuu Israelin heimo häpeään, se ja sen kuninkaat, ruhtinaat, papit ja profeetat,'),
(1687956,58,24,2,27,'he, jotka sanovat puulle: ''Sinä olet minun isäni'' ja kivelle: ''Sinä olet minut synnyttänyt''. Sillä he ovat kääntäneet minulle selkänsä eivätkä kasvojansa; mutta onnettomuutensa aikana he sanovat: ''Nouse ja pelasta meidät''.'),
(1687957,58,24,2,28,'Mutta missä ovat sinun jumalasi, jotka olet itsellesi tehnyt? Nouskoot ne, jos voivat pelastaa sinut onnettomuutesi aikana. Sillä yhtä monta, kuin sinulla on kaupunkeja, on sinulla jumalia, Juuda.'),
(1687958,58,24,2,29,'Miksi riitelette minua vastaan? Olettehan te kaikki luopuneet minusta, sanoo Herra.'),
(1687959,58,24,2,30,'Turhaan minä olen lyönyt teidän lapsianne; he eivät ole ottaneet kuritusta varteen. Teidän miekkanne on syönyt teidän profeettojanne, niinkuin hävittävä leijona.'),
(1687960,58,24,2,31,'Voi sukukuntaa - teitä! Katsokaa Herran sanaa: olenko minä ollut Israelille erämaa, pimeyden maa? Miksi sanoo minun kansani: ''Me juoksemme valtoimina, emme tule enää sinun tykösi''.'),
(1687961,58,24,2,32,'Unhottaako neitsyt koristeensa, morsian koruvyönsä? Mutta minun kansani on unhottanut minut epälukuisina päivinä.'),
(1687962,58,24,2,33,'Kuinka ovelasti sinä kuljet lempeä etsiessäsi! Niinpä oletkin perehtynyt pahuuden teihin.'),
(1687963,58,24,2,34,'Vaatteesi liepeetkin ovat köyhien, viatonten veressä. Et tavannut heitä murtautumasta sisälle, mutta yhtäkaikki -!'),
(1687964,58,24,2,35,'Ja kuitenkin sinä sanot: ''Minä olen syytön; hänen vihansa on kaiketi kääntynyt minusta pois''. Katso, minä käyn oikeutta sinun kanssasi, koska sinä sanot: ''En ole syntiä tehnyt''.'),
(1687965,58,24,2,36,'Kuinka niin kovin kiiruhdat vaihtamaan tiesi! Egyptistäkin olet saava häpeän, niinkuin olet häpeän saanut Assurista.'),
(1687966,58,24,2,37,'Senkin tyköä olet lähtevä kädet pääsi päällä, sillä Herra on hyljännyt ne, joihin sinä luotat, ja heistä ei sinulle menestystä tule."'),
(1687967,58,24,3,1,'Sanottu on: Jos mies lähettää pois vaimonsa ja tämä menee hänen luotansa ja joutuu toisen miehen vaimoksi, saako se mies enää tulla hänen luokseen? Eikö se maa tule saastutetuksi? Mutta sinä olet harjoittanut haureutta monen ystävän kanssa, ja sinäkö saisit palata minun luokseni! sanoo Herra.'),
(1687968,58,24,3,2,'Nosta silmäsi kukkuloihin ja katso: missä ei olisi sinua maattu? Teitten vieressä sinä istuit heitä odotellen, niinkuin arabialainen erämaassa, ja saastutit maan haureellisella menollasi ja pahuudellasi.'),
(1687969,58,24,3,3,'Sadekuurot tyrehtyivät, kevätsade jäi tulematta, mutta sinulla oli porttonaisen otsa, et tahtonut hävetä.'),
(1687970,58,24,3,4,'Kuitenkin sinä nyt huudat minulle: "Isäni! - Sinä olet nuoruuteni ystävä! -'),
(1687971,58,24,3,5,'Pitääkö hän vihaa iankaikkisesti, kantaako hän sitä ainiaan?" Katso, näin sinä puhut, mutta sinä teet pahaa, ja siihen sinä pystyt.'),
(1687972,58,24,3,6,'Ja Herra sanoi minulle kuningas Joosian päivinä: "Oletko nähnyt, mitä tuo luopiovaimo, Israel, on tehnyt? Hän kuljeskeli kaikilla korkeilla vuorilla ja kaikkien viheriäin puitten alla ja harjoitti siellä haureutta.'),
(1687973,58,24,3,7,'Ja minä sanoin, sittenkuin hän oli kaiken tämän tehnyt: ''Palaja minun tyköni''. Mutta hän ei palannut. Ja hänen sisarensa Juuda, tuo uskoton, näki sen.'),
(1687974,58,24,3,8,'Ja minä näin, että, vaikka minä olin lähettänyt pois tuon luopiovaimon, Israelin, juuri sen tähden, että hän oli tehnyt aviorikoksen, ja olin antanut hänelle erokirjan, ei kuitenkaan uskoton Juuda, hänen sisarensa, peljännyt, vaan meni ja harjoitti haureutta hänkin.'),
(1687975,58,24,3,9,'Ja haureutensa huudolla hän saastutti maan, ja hän teki aviorikoksen kiven ja puun kanssa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1687976,58,24,3,10,'Ja kaikesta tästäkään huolimatta hänen sisarensa Juuda, tuo uskoton, ei palannut minun tyköni kaikesta sydämestään, vaan petollisesti, sanoo Herra."'),
(1687977,58,24,3,11,'Ja Herra sanoi minulle: "Luopiovaimo Israel on osoittautunut vanhurskaammaksi kuin Juuda, tuo uskoton.'),
(1687978,58,24,3,12,'Mene ja julista nämä sanat pohjoiseen päin ja sano: Palaja, sinä luopiovaimo Israel, sanoo Herra; minä en enää synkistä teille kasvojani, sillä minä olen armollinen, sanoo Herra, enkä pidä vihaa iankaikkisesti.'),
(1687979,58,24,3,13,'Ainoastaan tunne rikoksesi, että olet luopunut Herrasta, Jumalastasi, ja juossut sinne ja tänne vieraitten jumalain tykö, kaikkien viheriäin puitten alle, ettekä ole kuulleet minun ääntäni, sanoo Herra.'),
(1687980,58,24,3,14,'Palatkaa takaisin, te luopuneet lapset, sanoo Herra, sillä minä olen ottanut teidät omikseni, ja minä noudan teidät, yhden ainoankin kaupungista ja kaksi sukukunnasta, ja tuon teidät Siioniin.'),
(1687981,58,24,3,15,'Ja minä annan teille paimenet oman sydämeni mukaan, ja he kaitsevat teitä ymmärryksellä ja taidolla.'),
(1687982,58,24,3,16,'Ja kun te lisäännytte ja tulette hedelmällisiksi maassa niinä päivinä, sanoo Herra, niin ei enää puhuta Herran liitonarkista, se ei enää ajatukseen astu, eikä sitä enää muisteta; ei sitä enää kaivata, eikä sellaista enää tehdä.'),
(1687983,58,24,3,17,'Siihen aikaan sanotaan Jerusalemia Herran valtaistuimeksi, ja kaikki kansat kokoontuvat sinne, Jerusalemiin, Herran nimen tähden eivätkä enää vaella pahan sydämensä paatumuksessa.'),
(1687984,58,24,3,18,'Niinä päivinä on Juudan heimo kulkeva Israelin heimon kanssa, ja he tulevat yhdessä pohjoisesta maasta siihen maahan, jonka minä annoin teidän isillenne perinnöksi.'),
(1687985,58,24,3,19,'Minä ajattelin: Kuinka asetankaan sinut lasten joukkoon ja annan sinulle suloisen maan, ihanan perintöosan, ihanimman kansojen maista! Ja ajattelin: Sinä olet kutsuva minua isäksi etkä ole koskaan kääntyvä minusta pois.'),
(1687986,58,24,3,20,'Mutta niinkuin vaimo on uskoton puolisollensa, niin olette te, Israelin heimo, olleet uskottomat minulle, sanoo Herra.'),
(1687987,58,24,3,21,'Kuule! Kalliokukkuloilta kuuluu itku, israelilaisten rukous, sillä he ovat vaeltaneet väärää tietä, ovat unhottaneet Herran, Jumalansa.'),
(1687988,58,24,3,22,'Palatkaa takaisin, te luopuneet lapset, niin minä parannan teidän luopumuksenne." - "Katso, me tulemme sinun tykösi, sillä sinä olet Herra, meidän Jumalamme.'),
(1687989,58,24,3,23,'Totisesti, petosta on, mitä kukkuloilta kuuluu, pauhina vuorilla. Totisesti, Herrassa, meidän Jumalassamme, on Israelin pelastus.'),
(1687990,58,24,3,24,'Häpeäjumala on syönyt isiemme vaivannäön nuoruudestamme asti, heidän lampaansa ja raavaansa, poikansa ja tyttärensä.'),
(1687991,58,24,3,25,'Maatkaamme häpeässämme, ja häväistyksemme peittäköön meidät, sillä Herraa, meidän Jumalaamme, vastaan me olemme syntiä tehneet, me ja meidän isämme, hamasta nuoruudestamme tähän päivään asti, emmekä ole kuulleet Herran, meidän Jumalamme, ääntä."'),
(1687992,58,24,4,1,'"Jos sinä käännyt, Israel, sanoo Herra, niin käänny minun tyköni; ja jos sinä poistat iljetyksesi minun kasvojeni edestä, niin et häädy harhailemaan;'),
(1687993,58,24,4,2,'jos sinä vannot: ''Niin totta kuin Herra elää'' uskollisesti, oikein ja vanhurskaasti, niin kansat siunaavat itsensä hänen nimeensä, ja hän on heidän kerskauksensa.'),
(1687994,58,24,4,3,'Sillä näin sanoo Herra Juudan miehille ja Jerusalemille: Raivatkaa itsellenne uudispelto, älkääkä kylväkö orjantappurain sekaan.'),
(1687995,58,24,4,4,'Ympärileikatkaa itsenne Herralle ja poistakaa sydämenne esinahka, te Juudan miehet ja Jerusalemin asukkaat, ettei minun vihani syttyisi kuin tuli ja palaisi, eikä olisi sammuttajaa, teidän tekojenne pahuuden tähden.'),
(1687996,58,24,4,5,'Julistakaa Juudassa ja Jerusalemissa, kuuluttakaa ja sanokaa: Puhaltakaa pasunaan kautta maan; huutakaa täyttä kurkkua ja sanokaa: ''Kokoontukaa, ja menkäämme varustettuihin kaupunkeihin''.'),
(1687997,58,24,4,6,'Nostakaa lippu Siionia kohti, paetkaa pysähtymättä; sillä minä annan tulla pohjoisesta onnettomuuden ja suuren hävityksen.'),
(1687998,58,24,4,7,'Leijona on noussut tiheiköstänsä, kansaintuhooja on lähtenyt liikkeelle, lähtenyt asuinpaikastansa, tekemään sinun maasi autioksi: sinun kaupunkisi hävitetään asujattomiksi.'),
(1687999,58,24,4,8,'Sentähden kääriytykää säkkeihin, valittakaa ja parkukaa, sillä Herran vihan hehku ei ole kääntynyt meistä pois."'),
(1688000,58,24,4,9,'Sinä päivänä, sanoo Herra, katoaa rohkeus kuninkaalta ja päämiehiltä, papit tyrmistyvät ja profeetat hämmästyvät.'),
(1688001,58,24,4,10,'Mutta minä sanoin: "Voi, Herra, Herra! Totisesti, sinä saatoit tämän kansan ja Jerusalemin peräti pettymään, kun sanoit: ''Teillä on oleva rauha!'' Ja kuitenkin miekka koskee sieluun asti."'),
(1688002,58,24,4,11,'Siihen aikaan sanotaan tälle kansalle ja Jerusalemille: Kuuma tuuli tulee erämaan kalliokukkuloilta tytärtä, minun kansaani, kohti - ei elon viskaamiseksi eikä puhdistamiseksi.'),
(1688003,58,24,4,12,'Tuuli, liian tuima sellaisiin, tulee minulta; nyt minä myös julistan heille tuomiot.'),
(1688004,58,24,4,13,'Katso, hän nousee niinkuin pilvi, ja hänen vaununsa ovat kuin tuulispää, hänen hevosensa ovat kotkia nopeammat. Voi meitä, sillä me olemme tuhon omat!'),
(1688005,58,24,4,14,'Pese sydämesi puhtaaksi pahuudesta, sinä Jerusalem, että pelastuisit. Kuinka kauan asuvat sinun sisimmässäsi väärät ajatuksesi?'),
(1688006,58,24,4,15,'Sillä kuule! Sanansaattaja Daanista, onnettomuuden julistaja Efraimin vuorilta!'),
(1688007,58,24,4,16,'Kehoittakaa kansoja. Katso, kuuluttakaa Jerusalemia vastaan: "Piirittäjät tulevat kaukaisesta maasta ja kohottavat huutonsa Juudan kaupunkeja vastaan".'),
(1688008,58,24,4,17,'Niinkuin pellon vartijat he piirittävät sitä yltympäri, koska se niskoitteli minua vastaan, sanoo Herra.'),
(1688009,58,24,4,18,'Sinun vaelluksesi ja tekosi ovat tuottaneet sinulle tämän: tämän saat pahuudestasi; niin, se on katkerata, niin, se koskee sydämeesi asti.'),
(1688010,58,24,4,19,'Voi minun rintaani, voi minun rintaani! Minä vääntelehdin tuskasta. Voi sydämeni kammioita! Sydämeni väräjää minussa; en voi vaieta, sillä minä kuulen pasunan äänen, sotahuudon.'),
(1688011,58,24,4,20,'Hävitys tulee hävityksen päälle, sillä koko maa on tuhottu; äkisti ovat minun majani tuhotut, silmänräpäyksessä minun telttani.'),
(1688012,58,24,4,21,'Kuinka kauan minun täytyy nähdä sotalippua, kuulla pasunan ääntä?'),
(1688013,58,24,4,22,'Sillä minun kansani on hullu; eivät he tunne minua. He ovat tyhmiä lapsia eivätkä ymmärtäväisiä; he ovat viisaita tekemään pahaa, mutta tehdä hyvää he eivät taida.'),
(1688014,58,24,4,23,'Minä katselin maata, ja katso, se oli autio ja tyhjä, ja taivasta, eikä siinä valoa ollut.'),
(1688015,58,24,4,24,'Minä katselin vuoria, ja katso, ne järkkyivät, ja kaikki kukkulat huojuivat.'),
(1688016,58,24,4,25,'Minä katselin, ja katso, ei ollut yhtään ihmistä, ja kaikki taivaan linnut olivat paenneet pois.'),
(1688017,58,24,4,26,'Minä katselin, ja katso, hedelmätarha oli erämaana, ja kaikki sen kaupungit olivat kukistuneet Herran, hänen vihansa hehkun, edessä.'),
(1688018,58,24,4,27,'Sillä näin sanoo Herra: Koko maa tulee autioksi, vaikka minä en siitä peräti loppua tee.'),
(1688019,58,24,4,28,'Sentähden maa suree, ja taivaat ylhäällä pukeutuvat mustiin, sillä minä olen puhunut, olen päättänyt, enkä kadu, en siitä peräydy.'),
(1688020,58,24,4,29,'Ratsu- ja jousimiesten huutoa pakenee koko kaupunki; he menevät metsäntiheikköihin ja nousevat kallioille. Jokainen kaupunki on hyljätty, eikä niissä kukaan asu.'),
(1688021,58,24,4,30,'Ja sinä tuhon oma, mitä teet, kun pukeudut purppuraan, kun koristaudut kultakoristeilla, kun suurennat silmäsi ihomaalilla? Turhaan sinä itsesi kaunistat. Rakastajat ovat hyljänneet sinut, he etsivät sinun henkeäsi.'),
(1688022,58,24,4,31,'Sillä minä kuulen huudon, niinkuin synnyttäjän tuskanhuudon, vaivan, niinkuin ensisynnyttäjän vaivan, tytär Siionin huudon; hän vaikeroitsee, levittää kätensä: "Voi minua, minun sieluni menehtyy murhamiesten käsiin!"'),
(1688023,58,24,5,1,'Kiertäkää Jerusalemin katuja, katsokaa ja tiedustelkaa, ja etsikää sen toreilta: jos löydätte yhdenkään, jos on ainoatakaan, joka tekee oikein, joka noudattaa uskollisuutta, niin minä annan anteeksi Jerusalemille.'),
(1688024,58,24,5,2,'Mutta vaikka he sanovat: "Niin totta kuin Herra elää", he kuitenkin vannovat väärin.'),
(1688025,58,24,5,3,'Herra, eivätkö sinun silmäsi katso uskollisuutta? Sinä olet lyönyt heitä, mutta he eivät tunteneet kipua; sinä olet lopen hävittänyt heidät, mutta he eivät tahtoneet ottaa kuritusta varteen. He ovat kovettaneet kasvonsa kalliota kovemmiksi, eivät ole tahtoneet kääntyä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688026,58,24,5,4,'Silloin minä ajattelin: Sellaisia ovat vain alhaiset; he ovat tyhmiä, sillä he eivät tunne Herran tietä, Jumalansa oikeutta.'),
(1688027,58,24,5,5,'Niinpä menen ylhäisten luo ja puhuttelen heitä, sillä he kyllä tuntevat Herran tien, Jumalansa oikeuden. Mutta he olivat kaikki särkeneet ikeen, katkaisseet siteet.'),
(1688028,58,24,5,6,'Sentähden surmaa heidät metsän leijona, aavikon susi haaskaa heidät, pantteri väijyy heidän kaupunkejansa. Kuka ikinä niistä lähtee, se raadellaan, sillä paljot ovat heidän rikoksensa, suuri heidän luopumustensa luku.'),
(1688029,58,24,5,7,'Kuinka minä antaisin sinulle anteeksi? Sinun lapsesi ovat hyljänneet minut ja vannoneet niiden kautta, jotka eivät jumalia ole. Minä ravitsin heitä, mutta he tekivät aviorikoksen, ja porton huoneeseen he kokoontuivat.'),
(1688030,58,24,5,8,'He ovat hyvinruokittuja, äleitä oriita; he hirnuvat kukin lähimmäisensä vaimoa.'),
(1688031,58,24,5,9,'Enkö minä tällaisista rankaisisi, sanoo Herra, eikö minun sieluni kostaisi tämänkaltaiselle kansalle?'),
(1688032,58,24,5,10,'Nouskaa sen tarhojen pengermille ja hävittäkää, älkää kuitenkaan siitä peräti loppua tehkö; ottakaa pois sen köynnökset, sillä ne eivät ole Herran.'),
(1688033,58,24,5,11,'Sillä he ovat olleet minulle peräti uskottomat, sekä Israelin heimo että Juudan heimo, sanoo Herra.'),
(1688034,58,24,5,12,'He ovat kieltäneet Herran ja sanoneet: "Ei se ole hän! Ei meitä kohtaa onnettomuus, emme tule näkemään miekkaa emmekä nälkää.'),
(1688035,58,24,5,13,'Ja profeetat ovat pelkkää tuulta; Herra, joka puhuu, ei ole heissä - heidän itsensä käyköön niin."'),
(1688036,58,24,5,14,'Sentähden sanoo Herra, Jumala Sebaot, näin: Koska te tällaisia olette puhuneet, niin katso, minä teen sanani sinun suussasi tuleksi ja tämän kansan polttopuiksi, ja se kuluttaa heidät.'),
(1688037,58,24,5,15,'Katso minä tuon teitä vastaan, te Israelin heimo, kansan kaukaa, sanoo Herra; se on horjumaton kansa, se on ikivanha kansa, kansa, jonka kieltä sinä et ymmärrä ja jonka puhetta sinä et tajua.'),
(1688038,58,24,5,16,'Heidän viinensä on kuin avoin hauta, he ovat kaikki sankareita.'),
(1688039,58,24,5,17,'He syövät sinun satosi ja leipäsi, he syövät sinun poikasi ja tyttäresi, syövät sinun lampaasi ja raavaasi, syövät sinun viinipuusi ja viikunapuusi; he miekalla hävittävät sinun varustetut kaupunkisi, joihin sinä luotat.'),
(1688040,58,24,5,18,'Mutta niinäkään päivinä, sanoo Herra, en minä teistä peräti loppua tee.'),
(1688041,58,24,5,19,'Ja kun he kysyvät: "Miksi on Herra, meidän Jumalamme, tehnyt meille kaiken tämän?" niin vastaa heille: "Niinkuin te olette hyljänneet minut ja palvelleet vieraita jumalia maassanne, niin täytyy teidän palvella muukalaisia maassa, joka ei ole teidän".'),
(1688042,58,24,5,20,'Julistakaa tämä Jaakobin huoneessa ja kuuluttakaa se Juudassa sanoen:'),
(1688043,58,24,5,21,'Kuulkaa tämä, te tyhmä ja ymmärtämätön kansa, te, joilla on silmät, mutta ette näe, joilla on korvat, mutta ette kuule.'),
(1688044,58,24,5,22,'Ettekö pelkää minua, sanoo Herra, ettekö vapise minun edessäni, joka olen pannut hiekan meren rajaksi, ikuiseksi määräksi, jonka ylitse se ei pääse; ja vaikka se kuohuu, ei se mitään voi, ja vaikka sen aallot pauhaavat, eivät ne sen ylitse pääse?'),
(1688045,58,24,5,23,'Mutta tällä kansalla on uppiniskainen ja tottelematon sydän; he ovat poikenneet ja menneet pois.'),
(1688046,58,24,5,24,'Eivätkä he sano sydämessänsä: "Peljätkäämme Herraa, Jumalaamme, joka antaa sateen, syyssateen ja kevätsateen ajallansa, ja säilyttää meille elonkorjuun määräviikot".'),
(1688047,58,24,5,25,'Teidän pahat tekonne käänsivät nämä pois, ja teidän syntinne estivät teitä saamasta hyvää.'),
(1688048,58,24,5,26,'Sillä minun kansassani on jumalattomia; he väijyvät, niinkuin linnunpyytäjät kyykistyvät, he asettavat ansoja, pyydystävät ihmisiä.'),
(1688049,58,24,5,27,'Niinkuin häkki on täynnä lintuja, niin heidän huoneensa ovat petosta täynnä. Siitä he ovat tulleet suuriksi ja rikkaiksi,'),
(1688050,58,24,5,28,'ovat tulleet lihaviksi ja kiiltäviksi. Myös käyvät heidän häijyt puheensa yli kaiken määrän; he eivät aja orpojen asiaa, niin että ne voittaisivat, eivätkä hanki köyhille oikeutta.'),
(1688051,58,24,5,29,'Enkö minä näistä tällaisista rankaisisi, sanoo Herra, eikö minun sieluni kostaisi tämänkaltaiselle kansalle?'),
(1688052,58,24,5,30,'Kauheita ja pöyristyttäviä tapahtuu maassa:'),
(1688053,58,24,5,31,'profeetat ennustavat valhetta, ja papit hallitsevat yksissä neuvoin heidän kanssaan, ja sitä minun kansani rakastaa. Mutta mitä te teette, kun tästä tulee loppu?'),
(1688054,58,24,6,1,'Paetkaa, benjaminilaiset, Jerusalemista, puhaltakaa pasunaan Tekoassa ja nostakaa merkki Beet-Keremin kohdalle; sillä pohjoisesta nousee onnettomuus ja suuri hävitys.'),
(1688055,58,24,6,2,'Tytär Siionin, suloisen ja hemmotellun, minä hukutan.'),
(1688056,58,24,6,3,'Hänen tykönsä tulee paimenia laumoinensa, he pystyttävät telttansa häntä vastaan yltympäri, syöttävät alansa kukin.'),
(1688057,58,24,6,4,'Julistakaa häntä vastaan pyhä sota. "Nouskaa ja menkäämme puolipäivän aikaan! Voi meitä, sillä päivä painuu, sillä illan varjot pitenevät!'),
(1688058,58,24,6,5,'Nouskaa ja menkäämme yöllä ja hävittäkäämme hänen linnansa."'),
(1688059,58,24,6,6,'Sillä näin sanoo Herra Sebaot: Kaatakaa puita ja luokaa valli Jerusalemia vastaan. Se on kaupunki, jota on rangaistava; siinä on pelkkää väkivaltaa.'),
(1688060,58,24,6,7,'Niinkuin kaivo pitää vetensä tuoreena, niin sekin pitää pahuutensa tuoreena; sortoa, hävitystä kuuluu sieltä, minun edessäni on aina kipu ja haavat.'),
(1688061,58,24,6,8,'Ota ojentuaksesi, Jerusalem, ettei minun sieluni vieraannu sinusta, etten tee sinua autioksi, asumattomaksi maaksi.'),
(1688062,58,24,6,9,'Näin sanoo Herra Sebaot: Israelin jäännöksestä pidetään jälkikorjuu niinkuin viinipuusta; ojenna kätesi köynnöksiä kohti niinkuin viininkorjaaja.'),
(1688063,58,24,6,10,'Kenelle minä puhuisin, ketä varoittaisin, että he kuulisivat? Katso, heidän korvansa ovat ympärileikkaamattomat, eivät he voi kuunnella. Katso, Herran sana on tullut heille pilkaksi, ei se heille kelpaa.'),
(1688064,58,24,6,11,'Minä olen täynnä Herran vihaa, en jaksa sitä pidättää; vuodata se lapsukaisiin kadulla, niin myös nuorukaisparveen. Sillä niin mies kuin vaimokin vangitaan, niin vanhus kuin ikäloppu.'),
(1688065,58,24,6,12,'Heidän talonsa joutuvat vieraille, niin myös pellot ja vaimot; sillä minä ojennan käteni maan asukkaita vastaan, sanoo Herra.'),
(1688066,58,24,6,13,'Sillä kaikki, niin pienet kuin suuretkin, pyytävät väärää voittoa, kaikki, niin profeetat kuin papitkin, harjoittavat petosta.'),
(1688067,58,24,6,14,'He parantavat minun kansani vamman kepeästi, sanoen: "Rauha, rauha!" vaikka ei rauhaa ole.'),
(1688068,58,24,6,15,'He joutuvat häpeään, sillä he ovat tehneet kauhistuksia; mutta heillä ei ole hävyntuntoa, he eivät osaa hävetä. Sentähden he kaatuvat kaatuvien joukkoon, sortuvat, kun minä heitä rankaisen, sanoo Herra.'),
(1688069,58,24,6,16,'Näin on Herra sanonut: "Astukaa teille ja katsokaa ja kysykää muinaisia polkuja, kysykää, mikä on hyvä tie, ja vaeltakaa sitä, niin te löydätte levon sieluillenne". Mutta he vastasivat: "Emme vaella".'),
(1688070,58,24,6,17,'Ja minä olen asettanut teille vartijat: "Kuunnelkaa pasunan ääntä". Mutta he vastasivat: "Emme kuuntele".'),
(1688071,58,24,6,18,'Sentähden kuulkaa, te kansat, ja tiedä, seurakunta, mitä heille on tapahtuva.'),
(1688072,58,24,6,19,'Kuule, maa! Katso, minä tuotan onnettomuuden tälle kansalle, heidän hankkeittensa hedelmän, sillä he eivät ole kuunnelleet minun sanojani, vaan ovat hyljänneet minun lakini.'),
(1688073,58,24,6,20,'Mitä on minulle suitsutus, joka tulee Sabasta, ja paras kalmoruoko kaukaisesta maasta? Teidän polttouhrinne eivät ole minulle otolliset, eivätkä teidän teurasuhrinne minulle kelpaa.'),
(1688074,58,24,6,21,'Sentähden, näin sanoo Herra: Katso, minä asetan tälle kansalle kompastuskiviä, joihin he kompastuvat, isät ja pojat yhdessä, ja naapuri naapurinsa kanssa hukkuu.'),
(1688075,58,24,6,22,'Näin sanoo Herra: Katso, kansa tulee pohjoisesta maasta, suuri kansa nousee maan perimmäisiltä ääriltä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688076,58,24,6,23,'He käyttävät jousta ja keihästä, ovat julmat ja armahtamattomat. Heidän pauhinansa on kuin pauhaava meri, ja he ratsastavat hevosilla, varustettuina kuin soturi taisteluun sinua vastaan, tytär Siion.'),
(1688077,58,24,6,24,'Kun kuulemme siitä sanoman, niin meidän kätemme herpoavat; ahdistus valtaa meidät, tuska, niinkuin synnyttäväisen.'),
(1688078,58,24,6,25,'Älkää menkö vainiolle, älkää vaeltako tiellä, sillä vihollisen miekka - kauhistus on kaikkialla!'),
(1688079,58,24,6,26,'Tytär, minun kansani! Kääriydy säkkiin, vieriskele tuhassa; pidä itkiäiset, niinkuin ainokaista poikaa itketään, katkerat valittajaiset, sillä äkkiarvaamatta käy kimppuumme hävittäjä.'),
(1688080,58,24,6,27,'Minä olen asettanut sinut kansani koettelijaksi, suojavarustukseksi, että oppisit tuntemaan ja koettelisit heidän vaelluksensa.'),
(1688081,58,24,6,28,'Kaikki he ovat pääniskureita, liikkuvat panettelijoina; he ovat vaskea ja rautaa, ovat kelvottomia kaikki tyynni.'),
(1688082,58,24,6,29,'Palkeet puhkuvat, tulesta lähtee vain lyijyä. Turhaan on sulatettu ja sulatettu: pahat eivät ole erottuneet.'),
(1688083,58,24,6,30,'Hylkyhopeaksi heitä sanotaan, sillä Herra on heidät hyljännyt.'),
(1688084,58,24,7,1,'Tämä on sana, joka tuli Jeremialle Herralta:'),
(1688085,58,24,7,2,'"Asetu Herran huoneen portille ja julista siellä tämä sana ja sano: Kuulkaa Herran sana, koko Juuda, te jotka tulette näistä porteista kumartaen rukoilemaan Herraa.'),
(1688086,58,24,7,3,'Näin sanoo Herra Sebaot, Israelin Jumala: Vaeltakaa hyvin ja tehkää hyviä tekoja, niin minä annan teidän asua tässä paikassa.'),
(1688087,58,24,7,4,'Älkää luottako valheen sanoihin, kun sanotaan: ''Tämä on Herran temppeli, Herran temppeli, Herran temppeli!'''),
(1688088,58,24,7,5,'Vaan jos te todella parannatte vaelluksenne ja tekonne, jos te todella teette oikeuden niin toiselle kuin toisellekin,'),
(1688089,58,24,7,6,'ette sorra muukalaista, orpoa ja leskeä, ette vuodata viatonta verta tässä paikassa ettekä seuraa muita jumalia turmioksenne,'),
(1688090,58,24,7,7,'niin minä annan teidän asua tässä paikassa, maassa, jonka minä olen antanut teidän isillenne, iankaikkisesta iankaikkiseen.'),
(1688091,58,24,7,8,'Mutta katso, te luotatte valheen sanoihin, joista ei ole hyötyä.'),
(1688092,58,24,7,9,'Miten on? Te varastatte, tapatte, rikotte avion, vannotte väärin, poltatte uhreja Baalille ja seuraatte vieraita jumalia, joita te ette tunne.'),
(1688093,58,24,7,10,'Ja te tulette ja astutte minun eteeni tähän huoneeseen, joka on otettu minun nimiini, ja sanotte: ''Me kyllä pelastumme'' - tehdäksenne yhä kaikkia näitä kauhistuksia!'),
(1688094,58,24,7,11,'Ryövärien luolaksiko te katsotte tämän huoneen, joka on otettu minun nimiini? Katso, sellaiseksi minäkin olen sen havainnut, sanoo Herra.'),
(1688095,58,24,7,12,'Menkääpä minun asuinpaikkaani, joka oli Siilossa, jossa minä ensin annoin nimeni asua, ja katsokaa, mitä minä olen sille tehnyt kansani Israelin pahuuden tähden!'),
(1688096,58,24,7,13,'Ja koska te nyt olette kaikkia näitä tekoja tehneet, sanoo Herra, ettekä ole kuulleet, vaikka minä varhaisesta alkaen olen teille puhunut, koska ette vastanneet, vaikka minä teille huusin,'),
(1688097,58,24,7,14,'niin minä teen tälle huoneelle, joka on otettu minun nimiini, johon te luotatte, ja tälle paikalle, jonka minä olen antanut teille ja teidän isillenne, samoin kuin olen tehnyt Siilolle,'),
(1688098,58,24,7,15,'ja heitän teidät pois kasvojeni edestä, niinkuin olen heittänyt pois kaikki teidän veljenne, kaikki Efraimin jälkeläiset.'),
(1688099,58,24,7,16,'Mutta sinä älä rukoile tämän kansan puolesta, älä kohota heidän puolestaan huutoa ja rukousta äläkä niillä minua ahdista; sillä en minä sinua kuule.'),
(1688100,58,24,7,17,'Etkö näe, mitä he tekevät Juudan kaupungeissa ja Jerusalemin kaduilla?'),
(1688101,58,24,7,18,'Lapset kokoavat puita, isät sytyttävät tulen, ja vaimot sotkevat taikinaa valmistaaksensa uhrikakkuja taivaan kuningattarelle, ja he vuodattavat juomauhreja muille jumalille, minulle mielikarvaudeksi.'),
(1688102,58,24,7,19,'Minulleko he tuottavat mielikarvautta, sanoo Herra, eivätkö pikemmin itselleen, omaksi häpeäksensä?'),
(1688103,58,24,7,20,'Sentähden, näin sanoo Herra, Herra: Katso, minun vihani ja kiivauteni on vuotava tämän paikan ylitse, ihmisten, eläinten, kedon puitten ja maan hedelmän ylitse, ja se palaa sammumatta."'),
(1688104,58,24,7,21,'Näin sanoo Herra Sebaot, Israelin Jumala: "Lisätkää polttouhrinne teurasuhreihinne ja syökää lihaa.'),
(1688105,58,24,7,22,'Sillä en minä puhunut enkä antanut käskyä teidän isillenne poltto- ja teurasuhrista silloin, kun minä vein heidät pois Egyptin maasta,'),
(1688106,58,24,7,23,'vaan näin minä käskin heitä ja sanoin: Kuulkaa minun ääntäni, niin minä olen teidän Jumalanne ja te olette minun kansani; ja vaeltakaa aina sitä tietä, jota minä käsken teidän vaeltaa, että menestyisitte.'),
(1688107,58,24,7,24,'Mutta he eivät kuulleet, eivät korvaansa kallistaneet, vaan vaelsivat oman neuvonsa mukaan, pahan sydämensä paatumuksessa, ja käänsivät minulle selkänsä eivätkä kasvojansa.'),
(1688108,58,24,7,25,'Siitä päivästä, jona teidän isänne lähtivät Egyptin maasta, aina tähän päivään asti olen minä lähettänyt teidän tykönne kaikki palvelijani, profeetat - lähettänyt varhaisesta alkaen, päivä päivältä.'),
(1688109,58,24,7,26,'Mutta kukaan ei kuullut minua, ei kallistanut korvaansa, vaan he olivat niskureita, tekivät enemmän pahaa kuin heidän isänsä.'),
(1688110,58,24,7,27,'Ja kun sinä puhut heille kaiken tämän, niin he eivät kuule sinua, ja kun sinä heille huudat, niin he eivät sinulle vastaa.'),
(1688111,58,24,7,28,'Sentähden sano heille: Tämä on kansa, joka ei kuullut Herran, Jumalansa, ääntä eikä ottanut kuritusta varteen. Kadonnut on totuus ja hävinnyt heidän suustansa.'),
(1688112,58,24,7,29,'Leikkaa hiuksesi ja heitä ne pois ja viritä kalliokukkuloilla itkuvirsi, sillä Herra on hyljännyt ja sysännyt pois vihansa alaisen sukupolven.'),
(1688113,58,24,7,30,'Sillä Juudan miehet ovat tehneet sen, mikä on pahaa minun silmissäni, sanoo Herra. He ovat asettaneet iljetyksensä temppeliin, joka on otettu minun nimiini, ja saastuttaneet sen.'),
(1688114,58,24,7,31,'Ja he ovat rakentaneet Toofet-uhrikukkulat Ben-Hinnomin laaksoon, polttaakseen tulessa poikiansa ja tyttäriänsä, mitä minä en ole käskenyt ja mikä ei ole minun mieleeni tullut.'),
(1688115,58,24,7,32,'Sentähden, katso, päivät tulevat, sanoo Herra, jolloin ei enää sanota ''Toofet'' ja ''Ben-Hinnomin laakso'', vaan ''Murha-laakso'', ja Toofetiin haudataan, kun ei ole muualla tilaa.'),
(1688116,58,24,7,33,'Ja tämän kansan ruumiit joutuvat taivaan lintujen ja maan eläinten ruuaksi, eikä näitä kukaan karkoita.'),
(1688117,58,24,7,34,'Ja minä lopetan Juudan kaupungeista ja Jerusalemin kaduilta riemun ja ilon huudon, huudon yljälle ja huudon morsiamelle, sillä maa on tuleva raunioiksi."'),
(1688118,58,24,8,1,'"Siihen aikaan, sanoo Herra, otetaan Juudan kuningasten ja sen ruhtinasten luut, pappien ja profeettain luut sekä Jerusalemin asukasten luut pois heidän haudoistansa'),
(1688119,58,24,8,2,'ja hajotetaan auringon, kuun ja kaiken taivaan joukon eteen, joita he rakastivat ja palvelivat, joita he seurasivat, etsivät ja kumartaen rukoilivat; niitä ei koota eikä haudata, vaan ne tulevat maan lannaksi.'),
(1688120,58,24,8,3,'Ja kuolema on oleva halutumpi kuin elämä koko sille jäännökselle, joka jää jäljelle tästä pahasta sukukunnasta, kaikissa paikoissa, mihin minä karkoitan nämä jäljelle jääneet, sanoo Herra Sebaot.'),
(1688121,58,24,8,4,'Ja sano heille: Näin sanoo Herra: Eikö se, joka lankeaa, nouse jälleen? Eikö se, joka kääntyy pois, käänny takaisin?'),
(1688122,58,24,8,5,'Miksi kääntyy tämä kansa, Jerusalem, pois ainaisessa luopumuksessa? Miksi he pitävät kiinni petoksesta eivätkä tahdo palata?'),
(1688123,58,24,8,6,'Minä olen tarkannut ja kuunnellut: he puhuvat sitä, mikä ei ole oikein; ei kukaan kadu pahuuttansa, ei ajattele: Mitä olen minä tehnyt! Kaikki he kääntyvät pois juosten juoksuansa, niinkuin orhi kiitää taistelussa.'),
(1688124,58,24,8,7,'Haikarakin taivaalla tietää aikansa; metsäkyyhkynen, pääskynen ja kurki pitävät vaarin tuloajastansa, mutta minun kansani ei tunne Herran oikeutta.'),
(1688125,58,24,8,8,'Kuinka saatatte sanoa: ''Me olemme viisaita, ja meillä on Herran laki''? Totisesti! Katso, valheen työtä on tehnyt kirjanoppineiden valhekynä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688126,58,24,8,9,'Viisaat saavat häpeän, kauhistuvat ja joutuvat kiinni. Katso, he ovat hyljänneet Herran sanan - mitä heillä on viisautta?'),
(1688127,58,24,8,10,'Sentähden minä annan heidän vaimonsa vieraille, heidän peltonsa valloittajille. Sillä kaikki, niin pienet kuin suuretkin, pyytävät väärää voittoa, kaikki, niin profeetat kuin papitkin, harjoittavat petosta.'),
(1688128,58,24,8,11,'He parantavat kepeästi tyttären, minun kansani, vamman, sanoen: ''Rauha, rauha!'' vaikka ei rauhaa ole.'),
(1688129,58,24,8,12,'He joutuvat häpeään, sillä he ovat tehneet kauhistuksia; mutta heillä ei ole hävyntuntoa, he eivät osaa hävetä. Sentähden he kaatuvat kaatuvien joukkoon, sortuvat, kun heidän rangaistuksensa tulee, sanoo Herra.'),
(1688130,58,24,8,13,'Minä tempaan heidät peräti pois, sanoo Herra. Ei ole rypäleitä viinipuussa eikä viikunoita viikunapuussa, ja lehtikin lakastuu. Minä saatan hyökkääjät heidän kimppuunsa."'),
(1688131,58,24,8,14,'"Miksi istumme alallamme? Kokoontukaa! Menkäämme varustettuihin kaupunkeihin, ja siellä hukkukaamme! Sillä Herra, meidän Jumalamme, hukuttaa meidät ja juottaa meille myrkkyvettä, sillä me olemme syntiä tehneet Herraa vastaan."'),
(1688132,58,24,8,15,'"Odotetaan rauhaa, mutta hyvää ei tule, paranemisen aikaa, mutta katso, tulee peljästys!'),
(1688133,58,24,8,16,'Daanista kuuluu hänen hevostensa korskunta, hänen orhiensa hirnunnasta vapisee koko maa. Ja he tulevat ja syövät maan ja kaiken, mikä siinä on, kaupungin ja siinä asuvaiset.'),
(1688134,58,24,8,17,'Sillä katso, minä lähetän teidän sekaanne käärmeitä, myrkkyliskoja, joihin ei lumous tehoa, ja ne purevat teitä, sanoo Herra."'),
(1688135,58,24,8,18,'Missä on virvoitus minun murheeseeni? Minun sydämeni on sairas.'),
(1688136,58,24,8,19,'Katso, tyttären, minun kansani, huuto kuuluu kaukaisesta maasta: "Eikö Herra ole Siionissa, eikö ole siellä sen kuningas?" Miksi he ovat vihoittaneet minut jumalankuvillansa, muukalaisten turhilla jumalilla?'),
(1688137,58,24,8,20,'Ohi on elonaika, lopussa kesä, mutta ei ole meille apua tullut.'),
(1688138,58,24,8,21,'Tyttären, minun kansani, murtumisen tähden olen minä murtunut, minä käyn murheasussa, kauhistus on minut vallannut.'),
(1688139,58,24,8,22,'Eikö Gileadissa ole palsamia, eikö siellä ole parantajaa? Vai miksi eivät tyttären, minun kansani, haavat kasva umpeen?'),
(1688140,58,24,9,1,'Oi, jospa minun pääni olisi silkkaa vettä ja minun silmäni kyynellähde, niin minä itkisin päivät ja yöt tyttären, minun kansani, kaatuneita!'),
(1688141,58,24,9,2,'(9:1) Oi, jospa minulla olisi erämaassa matkamiehen yömaja, niin minä jättäisin kansani ja vaeltaisin pois heidän luotaan! Sillä he ovat kaikki avionrikkojia, ovat uskottomain joukkio.'),
(1688142,58,24,9,3,'He jännittävät valheeseen kielensä jousen, eivätkä käytä totuuteen valtaansa maassa; sillä he menevät pahuudesta pahuuteen, mutta minua he eivät tunne, sanoo Herra.'),
(1688143,58,24,9,4,'Varokaa kukin lähimmäistänne, älkää yhteenkään veljeen luottako; sillä jokainen veli viekkaasti pettää ja jokainen lähimmäinen liikkuu panettelijana.'),
(1688144,58,24,9,5,'He pettävät toinen toisensa eivätkä puhu totta; he ovat totuttaneet kielensä puhumaan valhetta, ovat tehneet vääryyttä väsyksiin asti.'),
(1688145,58,24,9,6,'Sinä asut keskellä vilppiä; vilpillisyydessään he eivät tahdo tuntea minua, sanoo Herra.'),
(1688146,58,24,9,7,'Sentähden, näin sanoo Herra Sebaot: Katso, minä sulatan heidät ja koettelen heitä; sillä mitä muuta minä voisin tehdä tyttären, minun kansani, tähden?'),
(1688147,58,24,9,8,'Tappava nuoli on heidän kielensä, vilppiä se puhuu; suullaan he puhuvat rauhaa lähimmäisensä kanssa, mutta sydämessään he juoniansa punovat.'),
(1688148,58,24,9,9,'Enkö minä näistä tällaisista rankaisisi heitä, sanoo Herra, eikö minun sieluni kostaisi tämänkaltaiselle kansalle?'),
(1688149,58,24,9,10,'Vuorten tähden minä puhkean itkuun ja valitukseen, erämaan laitumien tähden minä viritän itkuvirren. Sillä ne ovat poltetut, ei kukaan siellä kulje, eivätkä ne kuule karjan ääntä; paenneet ovat taivaan linnut ja eläimet, ovat menneet pois.'),
(1688150,58,24,9,11,'Ja minä teen Jerusalemin kiviroukkioksi, aavikkosutten asunnoksi, ja Juudan kaupungit minä teen autioiksi, asujattomiksi.'),
(1688151,58,24,9,12,'Kuka on viisas mies, joka tämän ymmärtää ja jolle Herran suu on puhunut, että hän sen ilmoittaisi? Minkätähden on maa hävitetty, poltettu kuin erämaa, jossa ei kukaan kulje?'),
(1688152,58,24,9,13,'Ja Herra sanoi: "Sentähden, että he ovat hyljänneet minun lakini, jonka minä heille annoin, eivätkä ole kuulleet minun ääntäni eivätkä vaeltaneet sen mukaan,'),
(1688153,58,24,9,14,'vaan ovat vaeltaneet sydämensä paatumuksessa ja seuranneet baaleja, niinkuin heidän isänsä olivat heille opettaneet,'),
(1688154,58,24,9,15,'sentähden sanoo Herra Sebaot, Israelin Jumala, näin: Katso, minä syötän heille, tälle kansalle, koiruohoa ja juotan heille myrkkyvettä.'),
(1688155,58,24,9,16,'Ja minä hajotan heidät kansojen sekaan, joita eivät he eivätkä heidän isänsä ole tunteneet, ja lähetän heidän jälkeensä miekan, kunnes minä heidät lopetan.'),
(1688156,58,24,9,17,'Näin sanoo Herra Sebaot: Ottakaa vaari, kutsukaa itkijävaimoja tulemaan tänne. Lähettäkää hakemaan viisaita vaimoja, jotta he tulisivat,'),
(1688157,58,24,9,18,'kiiruhtaisivat ja virittäisivät meistä valitusvirren, niin että silmämme vuotaisivat kyyneleitä ja silmäripsemme tiukkuisivat vettä.'),
(1688158,58,24,9,19,'Sillä valitushuuto kuuluu Siionista: Kuinka olemmekaan hävitetyt! Me olemme peräti häpeään joutuneet, sillä meidän täytyy jättää maa, sillä kukistuneet ovat meidän asuntomme.'),
(1688159,58,24,9,20,'Kuulkaa siis, te naiset, Herran sana, ottakoon korvanne vastaan hänen suunsa puheen; opettakaa tyttärillenne valitusvirsi ja toinen toisellenne itkuvirsi.'),
(1688160,58,24,9,21,'Sillä kuolema on noussut sisään ikkunoistamme, on tullut meidän palatseihimme, tuhotakseen kadulta lapset, toreilta nuorukaiset.'),
(1688161,58,24,9,22,'Puhu: Näin sanoo Herra: Ihmisten ruumiita makaa maassa niinkuin lantaa vainiolla, niinkuin lyhteitä leikkaajan jäljessä, eikä ole niitten korjaajaa.'),
(1688162,58,24,9,23,'Näin sanoo Herra: Älköön viisas kerskatko viisaudestansa, älköön väkevä kerskatko väkevyydestänsä, älköön rikas kerskatko rikkaudestansa;'),
(1688163,58,24,9,24,'vaan joka kerskaa, kerskatkoon siitä, että hän on ymmärtäväinen ja tuntee minut: että minä, Herra, teen laupeuden, oikeuden ja vanhurskauden maan päällä. Sillä senkaltaisiin minä mielistyn, sanoo Herra.'),
(1688164,58,24,9,25,'Katso, päivät tulevat, sanoo Herra, jolloin minä rankaisen kaikkia, jotka ovat ympärileikattuja, mutta kuitenkin ympärileikkaamattomia:'),
(1688165,58,24,9,26,'(9:25) Egyptiä, Juudaa, Edomia, ammonilaisia, Mooabia ja kaikkia päälaen ympäriltä kerittyjä, jotka asuvat erämaassa; sillä kaikki pakanakansat ovat ympärileikkaamattomia, ja koko Israelin heimo on sydämeltään ympärileikkaamaton."'),
(1688166,58,24,10,1,'Kuulkaa sana, jonka Herra on puhunut teitä vastaan, te Israelin heimo.'),
(1688167,58,24,10,2,'Näin sanoo Herra: "Älkää totutelko itseänne pakanain menoon älkääkä kauhistuko taivaan merkkejä, sillä pakanat niitä kauhistuvat.'),
(1688168,58,24,10,3,'Sillä kansat noudattavat turhia jumalia; sillä ne ovat puuta, joka hakataan metsästä, puusepän kätten tekemiä, työaseella tehtyjä.'),
(1688169,58,24,10,4,'Ne koristetaan hopealla ja kullalla sekä kiinnitetään nauloilla ja vasaroilla, niin etteivät ne horju.'),
(1688170,58,24,10,5,'Ne ovat kuin linnunpelätin kurkkumaalla, eivät ne voi puhua; kantamalla täytyy niitä kantaa, sillä eivät ne voi astua. Älkää peljätkö niitä, sillä eivät ne voi pahaa tehdä; mutta eivät ne myöskään voi tehdä hyvää.'),
(1688171,58,24,10,6,'Ei ole ketään sinun vertaistasi, Herra; sinä olet suuri, ja suuri ja voimallinen on sinun nimesi.'),
(1688172,58,24,10,7,'Kuka ei sinua pelkäisi, sinä kansojen kuningas? Sillä siihen sinä olet arvollinen. Sillä kaikissa kansojen viisaissa ja kaikissa heidän valtakunnissansa ei ole yhtäkään sinun vertaistasi.'),
(1688173,58,24,10,8,'He ovat kaikki tyynni järjettömiä, tyhmiä. Turhain jumalien opettamista! Ne ovat puuta,'),
(1688174,58,24,10,9,'ohueksi taottua hopeata, joka tuodaan Tarsiista, ja Uufaan kultaa, taiturin ja kultasepän kätten tekoa. Punasinistä ja punaista purppuraa on niiden puku. Taitajain tekoa ovat ne kaikki.'),
(1688175,58,24,10,10,'Mutta Herra on totinen Jumala; hän on elävä Jumala ja iankaikkinen kuningas. Hänen vihastansa vapisee maa, ja kansat eivät kestä hänen suuttumustansa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688176,58,24,10,11,'Sanokaa heille näin: Jumalat, jotka eivät ole tehneet taivasta eikä maata, ne katoavat maan päältä ja taivaan alta.'),
(1688177,58,24,10,12,'Hän on tehnyt maan voimallansa, vahvistanut maanpiirin viisaudellansa ja levittänyt taivaat taidollansa.'),
(1688178,58,24,10,13,'Kun hän jylisee, käy vetten pauhina taivaalla, ja hän nostaa pilvet maan ääristä, tekee salamat ja sateen ja tuo tuulen sen säilytyspaikoista.'),
(1688179,58,24,10,14,'Järjetön on jokainen ihminen, tietoa vailla, häpeän saa jokainen kultaseppä veistetystä kuvasta, petosta on hänen valamansa kuva, eikä niissä henkeä ole.'),
(1688180,58,24,10,15,'Turhuutta ne ovat, naurettavia tekeleitä; kun niiden rangaistus tulee, ne hukkuvat.'),
(1688181,58,24,10,16,'Näiden kaltainen ei ole hän, joka on Jaakobin osa, sillä hän on kaiken Luoja, ja Israel on hänen perintösukunsa: Herra Sebaot on hänen nimensä.'),
(1688182,58,24,10,17,'Kokoa tavarasi maasta pois, sinä, joka piiritettynä istut.'),
(1688183,58,24,10,18,'Sillä näin sanoo Herra: Katso, tällä haavaa minä linkoan pois maan asukkaat ja ahdistan heitä, niin että saavat tarpeeksensa."'),
(1688184,58,24,10,19,'Voi minua minun vammani tähden! Kipeä on minun haavani; mutta minä sanon: Tämä on minun vaivani, minun on se kannettava.'),
(1688185,58,24,10,20,'Minun telttani on hävitetty, ja kaikki minun telttaköyteni ovat katkotut; minun lapseni ovat lähteneet luotani, eikä niitä enää ole. Ei ole enää, kuka telttani pystyttäisi ja nostaisi seinieni kankaan.'),
(1688186,58,24,10,21,'Sillä paimenet olivat järjettömät eivätkä etsineet Herraa; sentähden he eivät menestyneet, vaan koko heidän laumansa hajotettiin.'),
(1688187,58,24,10,22,'Ääni kuuluu! Katso, se tulee, suuri pauhina pohjoisesta maasta, tekemään Juudan kaupungit autioiksi, aavikkosutten asunnoksi.'),
(1688188,58,24,10,23,'Minä tiedän, Herra, ettei ihmisen tie ole hänen vallassansa, eikä miehen vallassa, kuinka hän vaeltaa ja askeleensa ohjaa.'),
(1688189,58,24,10,24,'Kurita minua, Herra, mutta kohtuudella, äläkä vihassasi, ettet minua ylen vähäiseksi tekisi.'),
(1688190,58,24,10,25,'Vuodata vihasi pakanain ylitse, jotka eivät sinua tunne, ja sukukuntain ylitse, jotka eivät sinun nimeäsi avuksensa huuda. Sillä he ovat syöneet Jaakobin, ovat hänet syöneet ja lopettaneet, ja tehneet autioksi hänen asuinsijansa.'),
(1688191,58,24,11,1,'Sana, joka tuli Herralta Jeremialle ja kuului näin:'),
(1688192,58,24,11,2,'"Kuulkaa tämän liiton sanat ja puhukaa ne Juudan miehille ja Jerusalemin asukkaille;'),
(1688193,58,24,11,3,'sano heille: Näin sanoo Herra, Israelin Jumala: Kirottu olkoon se mies, joka ei kuule tämän liiton sanoja,'),
(1688194,58,24,11,4,'jonka minä sääsin teidän isillenne silloin, kun minä vein heidät pois Egyptin maasta, rautapätsistä, ja sanoin: Kuulkaa minun ääntäni ja tehkää aivan niin, kuin minä käsken teidän tehdä, niin te olette minun kansani ja minä olen teidän Jumalanne'),
(1688195,58,24,11,5,'ja pidän valan, jonka olen vannonut teidän isillenne luvaten antaa heille maan, joka vuotaa maitoa ja mettä, niinkuin se teillä tänäkin päivänä on." Ja minä vastasin ja sanoin: "Amen, Herra!"'),
(1688196,58,24,11,6,'Ja Herra sanoi minulle: "Julista kaikki nämä sanat Juudan kaupungeissa ja Jerusalemin kaduilla ja sano: Kuulkaa tämän liiton sanat ja noudattakaa niitä.'),
(1688197,58,24,11,7,'Sillä minä varoittamalla varoitin teidän isiänne silloin, kun minä johdatin heidät pois Egyptin maasta, ja olen varoittanut varhaisesta alkaen tähän päivään saakka sanoen: ''Kuulkaa minun ääntäni''.'),
(1688198,58,24,11,8,'Mutta he eivät kuulleet eivätkä korvaansa kallistaneet, vaan vaelsivat kukin pahan sydämensä paatumuksessa. Niin minä tuotin heidän päällensä kaikki tämän liiton sanat, joita minä olin käskenyt heidän noudattaa, mutta joita he eivät noudattaneet."'),
(1688199,58,24,11,9,'Ja Herra sanoi minulle: "Juudan miesten ja Jerusalemin asukasten keskuudessa on salaliitto.'),
(1688200,58,24,11,10,'He ovat kääntyneet takaisin ensimmäisten esi-isiensä pahoihin tekoihin, niiden, jotka eivät tahtoneet kuulla minun sanojani, ja he ovat seuranneet muita jumalia ja palvelleet niitä. Israelin heimo ja Juudan heimo ovat rikkoneet minun liittoni, jonka minä tein heidän isiensä kanssa.'),
(1688201,58,24,11,11,'Sentähden, näin sanoo Herra: Katso, minä tuotan heille onnettomuuden, josta heillä ei ole pääsyä; ja kun he minua huutavat, en minä kuule heitä.'),
(1688202,58,24,11,12,'Ja jos Juudan kaupungit ja Jerusalemin asukkaat menevät ja huutavat niitä jumalia, joille he ovat uhreja polttaneet, niin ne eivät heitä pelasta heidän onnettomuutensa aikana.'),
(1688203,58,24,11,13,'Sillä yhtä paljon kuin sinulla on kaupunkeja, on sinulla, Juuda, jumalia, ja yhtä paljon kuin Jerusalemissa on katuja, te olette pystyttäneet alttareja häpeäjumalalle, alttareja polttaaksenne uhreja Baalille.'),
(1688204,58,24,11,14,'Mutta sinä älä rukoile tämän kansan puolesta, älä kohota heidän puolestaan huutoa ja rukousta, sillä en minä kuule, kun he minua avuksi huutavat onnettomuutensa tähden.'),
(1688205,58,24,11,15,'Mitä tekee minun rakkaani minun temppelissäni? Juoniako punoo? Ottavatko mahtimiehet, ottaako uhriliha sinusta pois pahuutesi - silloin sinä riemuitsisit!'),
(1688206,58,24,11,16,'''Vihreä öljypuu, ihana, kaunishedelmäinen'' - sillä nimellä Herra sinua kutsui. Suuren jylinän pauhatessa hän sytytti sen tuleen, ja sen oksat turmeltuivat.'),
(1688207,58,24,11,17,'Ja Herra Sebaot, joka sinut istutti, on päättänyt sinun osaksesi onnettomuuden Israelin heimon ja Juudan heimon pahuuden tähden, jota he ovat harjoittaneet ja jolla ovat vihoittaneet minut, polttamalla uhreja Baalille."'),
(1688208,58,24,11,18,'Ja Herra ilmoitti minulle, ja minä sain tietää, sinä näytit minulle silloin heidän hankkeensa.'),
(1688209,58,24,11,19,'Ja minä olin kuin kesy karitsa, joka viedään teurastettavaksi, enkä tiennyt heidän pitäneen neuvoa minua vastaan: "Tuhotkaamme puu hedelminensä, hävittäkäämme hänet elävien maasta, niin ettei hänen nimeänsä enää muisteta".'),
(1688210,58,24,11,20,'Mutta Herra Sebaot on vanhurskas tuomari, joka tutkii munaskuut ja sydämen. Salli minun nähdä sinun kostavan heille, sillä sinun haltuusi minä olen uskonut asiani.'),
(1688211,58,24,11,21,'Sentähden, näin sanoo Herra Anatotin miehistä, jotka väijyvät sinun henkeäsi sanoen: "Älä ennusta Herran nimeen, ettet kuolisi meidän kättemme kautta" -'),
(1688212,58,24,11,22,'sentähden, näin sanoo Herra Sebaot: "Katso, minä kostan heille; heidän nuoret miehensä kuolevat miekkaan, heidän poikansa ja tyttärensä kuolevat nälkään.'),
(1688213,58,24,11,23,'Heistä ei jäännöstä jää, sillä minä tuotan onnettomuuden Anatotin miehille heidän rangaistusvuotenansa."'),
(1688214,58,24,12,1,'Sinä, Herra, olet vanhurskas; voisinko minä riidellä sinua vastaan? Kuitenkin minä kysyn sinulta, mikä oikeus on. Miksi jumalattomain tie menestyy? Miksi kaikki uskottomat saavat elää rauhassa?'),
(1688215,58,24,12,2,'Sinä heidät istutat, he myös juurtuvat; he kasvavat, kantavat myös hedelmää. Heidän suussansa sinä olet lähellä, mutta kaukana heidän sisimmästään.'),
(1688216,58,24,12,3,'Mutta sinä, Herra, tunnet minut; sinä näet minut ja tutkit minun sydämeni, millainen se on sinun edessäsi. Tempaa heidät pois niinkuin lampaat teuraiksi ja vihi heidät tapon päivää varten.'),
(1688217,58,24,12,4,'Kuinka kauan täytyy maan surra ja kaiken kedon ruohon kuivettua? Eläimet ja linnut hukkuvat siinä asuvaisten pahuuden tähden; sillä nämä sanovat: "Ei tule hän näkemään meidän loppuamme".'),
(1688218,58,24,12,5,'"Jos sinä jalkamiesten kanssa juokset ja ne sinut väsyttävät, kuinka sinä kävisit kilpaan hevosten kanssa? Ja jos sinä vaarattomalla maalla oletkin turvassa, kuinka käy sinun Jordanin rantatiheikössä?'),
(1688219,58,24,12,6,'Sillä omat veljesikin ja isäsi huone ovat petolliset sinua kohtaan, hekin huutavat täyttä kurkkua selkäsi takana. Älä usko heitä, vaikka he sinua ystävällisesti puhuttelevat.'),
(1688220,58,24,12,7,'Minä olen jättänyt huoneeni, hyljännyt perintöosani; olen antanut sieluni rakkaimman hänen vihollistensa käsiin.'),
(1688221,58,24,12,8,'Hän, minun perintöosani, oli minulle kuin leijona metsässä, hän kiljui minua vastaan, sentähden minä vihastuin häneen.'),
(1688222,58,24,12,9,'Onko minun perintöosani kirjava petolintu, jonka ympärillä on petolintuja? Menkää, kootkaa kaikki metsän eläimet, tuokaa ne ruualle.'),
(1688223,58,24,12,10,'Monet paimenet ovat turmelleet minun viinitarhani, tallanneet minun peltopalstani, tehneet ihanan peltopalstani autioksi erämaaksi.'),
(1688224,58,24,12,11,'Se on tehty autioksi, se suree minun edessäni autiona. Koko maa on hävitetty, sillä ei ollut ketään, joka olisi pannut sitä sydämelleen.'),
(1688225,58,24,12,12,'Kaikkien erämaan kalliokukkulain ylitse tulivat hävittäjät, sillä Herran miekka syö maan toisesta äärestä hamaan toiseen; ei pelastu mikään, mikä lihaa on.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688226,58,24,12,13,'He ovat kylväneet nisuja ja niittäneet ohdakkeita; ovat nähneet vaivaa näännyksiin asti, saamatta hyötyä. Niinpä saakaa häpeä sadostanne Herran vihan hehkun tähden."'),
(1688227,58,24,12,14,'Näin sanoo Herra kaikista minun pahoista naapureistani, jotka koskevat siihen perintöosaan, minkä minä olen antanut kansalleni Israelille: "Katso, minä tempaan heidät pois heidän maastansa, ja Juudan heimon minä tempaan pois heidän keskeltänsä.'),
(1688228,58,24,12,15,'Mutta senjälkeen kuin minä olen temmannut heidät pois, minä jälleen armahdan heitä ja palautan heidät, itsekunkin perintöosaansa ja itsekunkin maahansa.'),
(1688229,58,24,12,16,'Ja jos he oppivat minun kansani tiet, niin että vannovat minun nimeeni: ''Niin totta kuin Herra elää'', niinkuin he opettivat minun kansaani vannomaan Baalin kautta, niin heidät rakennetaan minun kansani keskeen.'),
(1688230,58,24,12,17,'Mutta jos he eivät kuule, niin minä tempaan pois ja hukutan sen kansan, sanoo Herra."'),
(1688231,58,24,13,1,'Näin sanoi Herra minulle: "Mene ja osta itsellesi liinainen vyö ja pane se kupeillesi, mutta älä anna sen tulla veteen".'),
(1688232,58,24,13,2,'Ja minä ostin vyön Herran sanan mukaan ja panin sen kupeilleni.'),
(1688233,58,24,13,3,'Sitten Herran sana tuli minulle toisen kerran, tämä sana:'),
(1688234,58,24,13,4,'"Ota vyö, jonka sinä ostit ja joka on kupeillasi, ja nouse, mene Eufratille ja kätke se siellä kallion koloon".'),
(1688235,58,24,13,5,'Ja minä menin ja kätkin sen Eufratiin, niinkuin Herra oli käskenyt minun tehdä.'),
(1688236,58,24,13,6,'Ja pitkän ajan kuluttua Herra sanoi minulle: "Nouse, mene Eufratille ja ota se vyö, jonka minä käskin sinun kätkeä sinne".'),
(1688237,58,24,13,7,'Niin minä menin Eufratille, kaivoin ja otin vyön siitä paikasta, johon olin sen kätkenyt; ja katso, vyö oli turmeltunut eikä kelvannut mihinkään.'),
(1688238,58,24,13,8,'Minulle tuli tämä Herran sana:'),
(1688239,58,24,13,9,'"Näin sanoo Herra: Samalla tavoin minä tuotan turmion Juudan ja Jerusalemin suurelle ylpeydelle.'),
(1688240,58,24,13,10,'Tämä paha kansa, joka ei tahdo kuulla minun sanojani, joka vaeltaa sydämensä paatumuksessa, seuraa muita jumalia, palvelee ja kumartaa niitä, tulee tämän vyön kaltaiseksi, joka ei mihinkään kelpaa.'),
(1688241,58,24,13,11,'Sillä niinkuin vyö liittyy miehen kupeisiin, niin minä liitin koko Israelin heimon ja koko Juudan heimon itseeni, sanoo Herra, että se olisi minun kansani, minulle kunniaksi, ylistykseksi ja kirkkaudeksi; mutta he eivät totelleet.'),
(1688242,58,24,13,12,'Sentähden sano heille tämä sana: Näin sanoo Herra, Israelin Jumala: Jokainen leili täytetään viinillä. Ja jos he sanovat sinulle: ''Emmekö me tietäisi, että jokainen leili täytetään viinillä?'''),
(1688243,58,24,13,13,'niin sano heille: Näin sanoo Herra: Katso, minä täytän kaikki tämän maan asukkaat, kuninkaat, jotka istuvat Daavidin valtaistuimella, papit ja profeetat ja kaikki Jerusalemin asukkaat päihtymyksellä.'),
(1688244,58,24,13,14,'Ja minä murskaan heidät, toisen toistansa vastaan, sekä isät että lapset, sanoo Herra. Minä en sääli, en säästä enkä armahda, niin että jättäisin heidät hävittämättä."'),
(1688245,58,24,13,15,'Kuulkaa, ottakaa korviinne, älkää ylpeilkö, sillä Herra on puhunut.'),
(1688246,58,24,13,16,'Antakaa Herralle, teidän Jumalallenne, kunnia, ennenkuin tulee pimeä ja jalkanne loukkaantuvat vuoriin hämärissä. Silloin te odotatte valoa, mutta hän muuttaa sen pilkkopimeäksi, tekee sen synkeydeksi.'),
(1688247,58,24,13,17,'Mutta ellette kuule tätä, niin minun sieluni salassa itkee sellaista ylpeyttä, itkee katkerasti, ja minun silmäni vuotavat kyyneleitä, kun Herran lauma viedään vankeuteen.'),
(1688248,58,24,13,18,'"Sano kuninkaalle ja kuninkaan äidille: Istukaa alhaiselle sijalle, sillä pudonnut on päästänne teidän kunniankruununne.'),
(1688249,58,24,13,19,'Etelämaan kaupungit ovat suljetut, eikä ole avaajaa; koko Juuda on viety pakkosiirtolaisuuteen, pakkosiirtolaisuuteen kaikki kansa.'),
(1688250,58,24,13,20,'Nostakaa silmänne ja katsokaa, kuinka ne tulevat pohjoisesta. Missä on lauma, joka oli sinun haltuusi annettu, nuo sinun lampaasi, sinun kunniasi?'),
(1688251,58,24,13,21,'Mitä sanot, kun hän panee sinulle päämiehiksi ne, jotka olit ystäviksesi totutellut? Eivätkö tuskat kourista sinua niinkuin synnyttävää vaimoa?'),
(1688252,58,24,13,22,'Ja jos sanot sydämessäsi: ''Minkätähden on minulle näin käynyt?'' - suuren syntisi tähden sinun liepeesi kohotettiin, tehtiin väkivaltaa sinun kantapäillesi.'),
(1688253,58,24,13,23,'Voiko etiopialainen muuttaa ihonsa ja pantteri pilkkunsa? Yhtä vähän te voitte tehdä hyvää, te pahantekoon tottuneet.'),
(1688254,58,24,13,24,'Ja minä hajotan heidät kuin oljenkorret, jotka lentävät erämaan tuulessa.'),
(1688255,58,24,13,25,'Tämä on sinun arpasi, sinun mitattu osasi minulta, sanoo Herra, koska olet unhottanut minut ja luottanut valheeseen.'),
(1688256,58,24,13,26,'Niinpä minäkin nostan sinulta liepeet kasvojen yli, ja sinun häpeäsi näkyy.'),
(1688257,58,24,13,27,'Sinun aviorikoksesi, hirnumisesi, riettaan haureutesi, sinun iljetyksesi kedon kukkuloilla minä olen nähnyt. Voi sinua, Jerusalem! Et sinä puhdistu, et vielä pitkään aikaan."'),
(1688258,58,24,14,1,'Herran sana, joka tuli Jeremialle suuren kuivuuden tähden.'),
(1688259,58,24,14,2,'"Juuda murehtii, sen portit raukeavat, kallistuvat murheasussa maahan; ja Jerusalemista nousee valitushuuto.'),
(1688260,58,24,14,3,'Heidän ylimyksensä lähettävät alaisiansa vedelle. Nämä tulevat kaivoille, eivät löydä vettä, palajavat astiat tyhjinä, ovat pettyneet ja häpeissänsä ja peittävät päänsä.'),
(1688261,58,24,14,4,'Peltomaan tähden, joka pakahtuu, kun ei ole satanut maassa, ovat peltomiehet pettyneinä ja peittävät päänsä.'),
(1688262,58,24,14,5,'Peurakin kedolla poikii ja hylkää vasikkansa, kun ei ole mitään vihantaa.'),
(1688263,58,24,14,6,'Ja villiaasit seisovat kalliokukkuloilla, haukkovat ilmaa niinkuin aavikkosudet; niiden silmät ovat riutuneet, kun ei ruohoa ole."'),
(1688264,58,24,14,7,'Vaikka pahat tekomme todistavat meitä vastaan, tee työsi, Herra, nimesi tähden; sillä meidän luopumuksemme ovat monet, sinua vastaan me olemme syntiä tehneet.'),
(1688265,58,24,14,8,'Sinä Israelin toivo, sen vapahtaja ahdingon aikana, minkätähden sinä olet kuin muukalainen maassa, kuin matkamies, joka poikkeaa majaan vain yöpyäksensä?'),
(1688266,58,24,14,9,'Minkätähden sinä olet kuin tyrmistynyt mies, kuin sankari, joka ei voi auttaa? Ja kuitenkin sinä olet meidän keskellämme, Herra, ja me olemme otetut sinun nimiisi; älä meitä jätä.'),
(1688267,58,24,14,10,'Näin sanoo Herra tästä kansasta: Noin he mielellänsä harhailevat, eivät pidätä jalkojansa. Ei Herra mielisty heihin; hän muistaa nyt heidän pahat tekonsa ja rankaisee heidän syntinsä.'),
(1688268,58,24,14,11,'Ja Herra sanoi minulle: "Älä rukoile tämän kansan puolesta, sen hyväksi.'),
(1688269,58,24,14,12,'Vaikka he paastoavat, en minä kuule heidän huutoansa, ja vaikka he uhraavat polttouhreja ja ruokauhreja, en minä heihin mielisty, vaan miekalla, nälällä ja rutolla minä heidät lopetan."'),
(1688270,58,24,14,13,'Niin minä sanoin: "Voi, Herra, Herra! Katso, profeetat sanovat heille: ''Ei teidän tarvitse nähdä miekkaa eikä kärsiä nälkää, vaan minä annan teille vakaan rauhan tässä paikassa''."'),
(1688271,58,24,14,14,'Mutta Herra sanoi minulle: "Valhetta ennustavat profeetat minun nimessäni; minä en ole lähettänyt heitä, en käskenyt heitä enkä puhunut heille. Valhenäkyjä, turhia ennustuksia ja oman sydämensä petosta he ennustavat teille.'),
(1688272,58,24,14,15,'Sentähden, näin sanoo Herra profeetoista, jotka ennustavat minun nimessäni, vaikka minä en ole heitä lähettänyt, ja jotka sanovat, että miekka ja nälkä ei tule tähän maahan: miekkaan ja nälkään hukkuvat nämä profeetat.'),
(1688273,58,24,14,16,'Ja kansa, jolle he ennustavat, suistuu Jerusalemin kaduilla nälkään ja miekkaan, eikä kukaan heitä hautaa - ei heitä, ei heidän vaimojansa, poikiansa eikä tyttäriänsä. Minä vuodatan heidän pahuutensa heidän päällensä."'),
(1688274,58,24,14,17,'Ja sano heille tämä sana: Minun silmistäni vuotavat kyyneleet yötä päivää, eivät lakkaa; sillä neitsyt, tytär, minun kansani, on raskaasti runneltu, ylen kipeällä iskulla.'),
(1688275,58,24,14,18,'Jos minä kedolle lähden, katso - miekan kaatamia! Jos tulen kaupunkiin, katso - kalvava nälkä! Sillä sekä profeetat että papit kiertävät maata eivätkä mitään tiedä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688276,58,24,14,19,'Oletko sinä kokonaan hyljännyt Juudan, vierooko sielusi Siionia? Minkätähden olet lyönyt meitä, niin ettemme voi parantua? Odotetaan rauhaa, mutta hyvää ei tule, paranemisen aikaa, mutta katso, tulee peljästys!'),
(1688277,58,24,14,20,'Me tunnemme, Herra, jumalattomuutemme, isiemme pahat teot, sillä sinua vastaan me olemme syntiä tehneet.'),
(1688278,58,24,14,21,'Älä hylkää, nimesi tähden! Älä anna kunniasi valtaistuinta häväistäväksi; muista, älä riko, liittoasi meidän kanssamme.'),
(1688279,58,24,14,22,'Onko pakanain turhista jumalista sateen antajiksi, tahi taivasko antaa sadekuurot? Etkö sinä ole Herra, meidän Jumalamme? Sinua me odotamme, sillä sinä olet tehnyt kaiken tämän.'),
(1688280,58,24,15,1,'Ja Herra sanoi minulle: "Vaikka Mooses ja Samuel seisoisivat minun edessäni, ei minun sieluni taipuisi tämän kansan puoleen. Aja heidät pois minun kasvojeni edestä, he menkööt!'),
(1688281,58,24,15,2,'Ja jos he kysyvät sinulta: ''Minne meidän on mentävä?'' niin vastaa heille: Näin sanoo Herra: Joka ruton oma, se ruttoon, joka miekan, se miekkaan, joka nälän, se nälkään, joka vankeuden, se vankeuteen!'),
(1688282,58,24,15,3,'Ja minä asetan heille neljänkaltaiset käskijät, sanoo Herra: miekan surmaamaan, koirat raahaamaan, taivaan linnut ja maan eläimet syömään ja hävittämään.'),
(1688283,58,24,15,4,'Minä panen heidät kauhistukseksi kaikille valtakunnille maan päällä Manassen, Hiskian pojan, Juudan kuninkaan, tähden, kaiken tähden, mitä hän teki Jerusalemissa.'),
(1688284,58,24,15,5,'Kuka säälii sinua, Jerusalem, kuka surkuttelee sinua, kuka poikkeaa kysymään sinun vointiasi?'),
(1688285,58,24,15,6,'Sinä olet hyljännyt minut, sanoo Herra, olet kääntynyt pois; niinpä minä olen ojentanut käteni sinua vastaan, ja minä hävitän sinut. En jaksa enää armahtaa.'),
(1688286,58,24,15,7,'Minä viskaan viskimellä heidät maan porteilla; minä teen lapsettomaksi, minä hukutan kansani, kun he eivät ole teiltänsä kääntyneet.'),
(1688287,58,24,15,8,'Heidän leskiänsä on oleva enemmän kuin meren hiekkaa; minä tuon heidän nuorukaistensa äitien kimppuun hävittäjän keskellä päivää, langetan äkkiä heidän päällensä tuskan ja kauhun.'),
(1688288,58,24,15,9,'Seitsemän pojan synnyttäjä menehtyy ja huokaisee henkensä pois; hänen aurinkonsa laski, kun vielä oli päivä, hän joutui häpeään, sai hävetä. Ja mitä heistä jää, sen minä annan miekalle alttiiksi heidän vihollistensa edessä, sanoo Herra."'),
(1688289,58,24,15,10,'Voi minua, äitini, kun minut synnytit riidan ja toran mieheksi koko maalle! En ole lainaksi antanut enkä lainaksi ottanut; kuitenkin kiroavat minua kaikki.'),
(1688290,58,24,15,11,'Herra sanoi: "Totisesti, minä kirvoitan sinut, niin että sinun käy hyvin; totisesti, minä saatan viholliset pyytämään sinua avuksensa onnettomuuden ja ahdistuksen aikana.'),
(1688291,58,24,15,12,'Murtuuko rauta, pohjoisesta tuotu rauta, ja vaski? -'),
(1688292,58,24,15,13,'Sinun tavarasi ja aarteesi minä annan ryöstettäviksi, ilman hintaa kaikkien sinun syntiesi tähden, kaikkia rajojasi myöten.'),
(1688293,58,24,15,14,'Ja minä panen sinut vihollistesi kanssa kulkemaan maata, jota et tunne. Sillä minun vihani tuli on syttynyt; se leimuaa teitä vastaan."'),
(1688294,58,24,15,15,'Herra, sinä sen tiedät. Muista minua ja pidä minusta huoli ja kosta puolestani minun vainoojilleni; älä tempaa minua pois, sinä, joka olet pitkämielinen. Huomaa, kuinka minä kannan häväistystä sinun tähtesi.'),
(1688295,58,24,15,16,'Sinun sanasi tulivat, ja minä söin ne, ja sinun sanasi olivat minulle riemu ja minun sydämeni ilo; sillä minä olen otettu sinun nimiisi, Herra, Jumala Sebaot.'),
(1688296,58,24,15,17,'En ole minä istunut iloitsemassa ilonpitäjäin seurassa. Sinun kätesi tähden minä olen istunut yksinäni, sillä sinä olet täyttänyt minut vihallasi.'),
(1688297,58,24,15,18,'Miksi kestää minun kipuni ainiaan ja haavani on paha eikä tahdo parantua? Sinä olet minulle kuin ehtyvä puro, kuin vesi, joka ei pysy.'),
(1688298,58,24,15,19,'Sentähden, näin sanoo Herra: "Jos sinä käännyt, niin minä sallin sinun kääntyä, ja sinä saat seisoa minun edessäni. Ja jos sinä tuot esiin jaloa, et arvotonta, niin sinä saat olla minun suunani. He kääntyvät sinun tykösi, mutta sinä et käänny heidän tykönsä.'),
(1688299,58,24,15,20,'Ja minä teen sinut vahvaksi vaskimuuriksi tätä kansaa vastaan, ja he sotivat sinua vastaan, mutta eivät voita sinua; sillä minä olen sinun kanssasi, minä vapahdan ja pelastan sinut, sanoo Herra.'),
(1688300,58,24,15,21,'Minä pelastan sinut pahain käsistä ja päästän sinut väkivaltaisten kourista."'),
(1688301,58,24,16,1,'Minulle tuli tämä Herran sana:'),
(1688302,58,24,16,2,'"Älä ota itsellesi vaimoa, älköönkä sinulle tulko poikia ja tyttäriä tässä paikassa.'),
(1688303,58,24,16,3,'Sillä näin sanoo Herra niistä pojista ja tyttäristä, jotka syntyvät tässä paikassa, ja heidän äideistänsä, jotka heidät synnyttävät, ja heidän isistänsä, jotka heidät siittävät tässä maassa:'),
(1688304,58,24,16,4,'He kuolevat tuskallisiin tauteihin, ei heille pidetä valittajaisia, ei heitä haudata; he tulevat maan lannaksi. He hukkuvat miekkaan ja nälkään, ja heidän ruumiinsa tulevat taivaan lintujen ja maan eläinten ruuaksi.'),
(1688305,58,24,16,5,'Sillä näin sanoo Herra: Älä mene suruhuoneeseen, älä käy valittajaisiin äläkä heitä surkuttele, sillä minä otan rauhani pois tältä kansalta, sanoo Herra, armoni ja laupeuteni.'),
(1688306,58,24,16,6,'He kuolevat, sekä suuret että pienet, tässä maassa; ei heitä haudata eikä heille valittajaisia pidetä, ei kukaan viileskele ihoansa eikä ajele päätänsä paljaaksi heidän tähtensä.'),
(1688307,58,24,16,7,'Ei taiteta heille leipää lohdutukseksi heidän surussansa kuolleen tähden, eikä heille anneta juotavaksi lohdutusmaljaa heidän isänsä ja äitinsä tähden.'),
(1688308,58,24,16,8,'Älä mene pitotaloon istumaan heidän kanssansa, syömään ja juomaan.'),
(1688309,58,24,16,9,'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä lopetan tästä paikasta teidän silmienne edessä ja teidän päivinänne riemun ja ilon huudon, huudon yljälle ja huudon morsiamelle.'),
(1688310,58,24,16,10,'Kun sinä ilmoitat tälle kansalle kaikki nämä sanat ja he sanovat sinulle: ''Minkätähden Herra uhkaa meitä kaikella tällä suurella onnettomuudella, ja mikä on rikoksemme, mikä syntimme, jonka olemme tehneet Herraa, meidän Jumalaamme, vastaan?'''),
(1688311,58,24,16,11,'niin sano heille: Sentähden että teidän isänne hylkäsivät minut, sanoo Herra, ja seurasivat muita jumalia, palvelivat niitä ja kumarsivat niitä, mutta hylkäsivät minut eivätkä noudattaneet minun lakiani.'),
(1688312,58,24,16,12,'Ja te olette tehneet pahemmin kuin teidän isänne, ja katso, te vaellatte kukin pahan sydämenne paatumuksessa, kuulematta minua.'),
(1688313,58,24,16,13,'Niin minä heitän teidät pois tästä maasta maahan, jota te ette tunne eivätkä teidän isänne tunteneet, ja siellä te saatte palvella muita jumalia päivät ja yöt, sillä minä en teille armoa anna.'),
(1688314,58,24,16,14,'Sentähden, katso, päivät tulevat, sanoo Herra, jolloin ei enää sanota: ''Niin totta kuin Herra elää, joka johdatti israelilaiset Egyptin maasta'','),
(1688315,58,24,16,15,'vaan: ''Niin totta kuin Herra elää, joka johdatti israelilaiset pohjoisesta maasta ja kaikista muista maista, joihin hän oli heidät karkoittanut''. Sillä minä palautan heidät heidän omaan maahansa, jonka minä annoin heidän isillensä.'),
(1688316,58,24,16,16,'Katso, minä käsken tulemaan monta kalastajaa, sanoo Herra, ja ne heitä kalastavat, ja sen jälkeen minä käsken tulemaan monta metsästäjää, ja ne heitä metsästävät kaikilta vuorilta ja kaikilta kukkuloilta ja kallioiden rotkoista.'),
(1688317,58,24,16,17,'Sillä minun silmäni tarkkaavat kaikkia heidän teitänsä, ne eivät ole minulta salassa, eikä heidän rikoksensa ole kätketty minun silmäini edestä.'),
(1688318,58,24,16,18,'Ja minä kostan ensin kaksinkertaisesti heidän rikoksensa ja syntinsä, koska he ovat saastuttaneet minun maani iljetystensä raadoilla ja täyttäneet minun perintöosani kauhistuksillansa."'),
(1688319,58,24,16,19,'Herra, minun voimani ja varustukseni, minun pakopaikkani hädän päivänä! Sinun tykösi tulevat pakanat maan ääristä ja sanovat: "Petosta vain perivät meidän isämme, turhia jumalia, joista ei ainoakaan auttaa taida.'),
(1688320,58,24,16,20,'Voiko ihminen tehdä itsellensä jumalia? Eivät ne jumalia ole!"'),
(1688321,58,24,16,21,'"Sentähden, katso, minä saatan heidät tuntemaan - tuntemaan tällä haavaa - minun käteni ja minun voimani, ja he tulevat tietämään, että minun nimeni on Herra."'),
(1688322,58,24,17,1,'"Juudan synti on kirjoitettu rautapiirtimellä, timanttikärjellä, kaiverrettu heidän sydämensä tauluun ja teidän alttarienne sarviin,'),
(1688323,58,24,17,2,'ja niin heidän lapsensa muistavat alttarinsa ja asera-karsikkonsa viheriäin puitten vieressä, korkeilla kukkuloilla.'),
(1688324,58,24,17,3,'Oman vuoreni, joka on kedolla, niin myös sinun tavarasi, kaikki sinun aarteesi ja sinun uhrikukkulasi minä annan ryöstettäviksi synnin tähden kaikkia rajojasi myöten.'),
(1688325,58,24,17,4,'Sinun on luovuttava perintöosastasi, jonka minä olen sinulle antanut; ja minä saatan sinut vihollistesi orjuuteen maassa, jota sinä et tunne. Sillä te olette sytyttäneet minun vihani tulen; se on palava iankaikkisesti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688326,58,24,17,5,'Näin sanoo Herra: Kirottu on se mies, joka turvaa ihmisiin ja tekee lihan käsivarreksensa ja jonka sydän luopuu Herrasta.'),
(1688327,58,24,17,6,'Hän jää alastomaksi arolle eikä näe mitään onnea tulevan; hän asuu poudan polttamissa paikoissa erämaassa, asumattomassa suolamaassa.'),
(1688328,58,24,17,7,'Siunattu on se mies, joka turvaa Herraan, jonka turvana Herra on.'),
(1688329,58,24,17,8,'Hän on kuin veden partaalle istutettu puu, joka ojentaa juurensa puron puoleen; helteen tuloa se ei peljästy, vaan sen lehvä on vihanta, ei poutavuonnakaan sillä ole huolta, eikä se herkeä hedelmää tekemästä.'),
(1688330,58,24,17,9,'Petollinen on sydän ylitse kaiken ja pahanilkinen; kuka taitaa sen tuntea?'),
(1688331,58,24,17,10,'Minä, Herra, tutkin sydämen, koettelen munaskuut, ja annan jokaiselle hänen vaelluksensa mukaan, hänen töittensä hedelmän mukaan.'),
(1688332,58,24,17,11,'Peltokana, joka hautoo, mitä ei ole muninut, on se, joka hankkii rikkautta vääryydellä; päiviensä puolivälissä hänen täytyy se jättää, ja hänen loppunsa on houkan loppu."'),
(1688333,58,24,17,12,'Kunnian valtaistuin, korkea ikiajoista, meidän pyhäkkömme paikka!'),
(1688334,58,24,17,13,'Israelin toivo, sinä Herra! Kaikki, jotka sinut hylkäävät, joutuvat häpeään. "Jotka minusta luopuvat, ne kirjoitetaan tomuun. Sillä he ovat hyljänneet elävän veden lähteen, Herran."'),
(1688335,58,24,17,14,'Paranna minut, Herra, niin minä parannun, auta minua, niin olen autettu. Sillä sinä olet minun ylistykseni.'),
(1688336,58,24,17,15,'Katso, he sanovat minulle: "Missä on Herran sana? Toteutukoon se!"'),
(1688337,58,24,17,16,'Mutta minä en ole vetäytynyt pois olemasta paimenena, sinua seuraamasta, enkä toivonut turmion päivää; sinä tiedät sen. Mitä minun huuliltani on lähtenyt, se on sinun kasvojesi edessä.'),
(1688338,58,24,17,17,'Älä tule minulle peljätykseksi, sinä, minun turvani onnettomuuden päivänä.'),
(1688339,58,24,17,18,'Joutukoot häpeään ne, jotka minua vainoavat, mutta älä anna minun häpeään tulla; peljästykööt he, mutta älä anna minun peljästyä. Tuota heille onnettomuuden päivä ja tuhoa heidät kaksinkertaisella tuholla.'),
(1688340,58,24,17,19,'Näin sanoi Herra minulle: "Mene ja seiso Kansanportissa, josta Juudan kuninkaat tulevat ja josta he menevät, ja kaikissa Jerusalemin porteissa.'),
(1688341,58,24,17,20,'Ja sano heille: Kuulkaa Herran sana, te Juudan kuninkaat ja koko Juuda ja kaikki Jerusalemin asukkaat, jotka tulette näistä porteista.'),
(1688342,58,24,17,21,'Näin sanoo Herra: Ottakaa itsestänne tarkka vaari, älkää sapatinpäivänä mitään kantamusta kantako älkääkä mitään tuoko Jerusalemin porteista.'),
(1688343,58,24,17,22,'Älkää viekö sapatinpäivänä mitään kantamusta taloistanne älkääkä tehkö mitään työtä, vaan pyhittäkää sapatinpäivä, niinkuin minä käskin teidän isienne tehdä.'),
(1688344,58,24,17,23,'Mutta he eivät kuulleet, eivät korvaansa kallistaneet, vaan olivat niskureita, niin etteivät kuulleet eivätkä ottaneet kuritusta varteen.'),
(1688345,58,24,17,24,'Jos kuulette minua, sanoo Herra, niin ettette tuo mitään kantamusta tämän kaupungin porteista sapatinpäivänä, vaan pyhitätte sapatinpäivän, niin ettette silloin tee mitään työtä,'),
(1688346,58,24,17,25,'niin tulee tämän kaupungin porteista sisälle, ajaen vaunuilla ja hevosilla, kuninkaita ja ruhtinaita, jotka istuvat Daavidin valtaistuimella, tulevat he ja heidän ruhtinaansa, Juudan miehet ja Jerusalemin asukkaat, ja tämä kaupunki on oleva asuttu iankaikkisesti.'),
(1688347,58,24,17,26,'Ja Juudan kaupungeista ja Jerusalemin ympäriltä, Benjaminin maasta ja Alankomaasta, Vuoristosta ja Etelämaasta tulee niitä, jotka tuovat polttouhreja ja teurasuhreja, ruokauhreja ja suitsutusuhreja, tuovat kiitosuhreja Herran huoneeseen.'),
(1688348,58,24,17,27,'Mutta jos ette kuule minua ettekä pyhitä sapatinpäivää, vaan kannatte kantamuksia ja kuljette Jerusalemin porteista sapatinpäivänä, niin minä sytytän tuleen sen portit, ja tuli on kuluttava Jerusalemin palatsit, eikä se ole sammuva."'),
(1688349,58,24,18,1,'Sana, joka tuli Jeremialle Herralta ja kuului:'),
(1688350,58,24,18,2,'"Nouse ja mene alas savenvalajan huoneeseen; siellä minä annan sinun kuulla sanani".'),
(1688351,58,24,18,3,'Niin minä menin alas savenvalajan huoneeseen, ja katso, hän teki työtä pyöränsä ääressä.'),
(1688352,58,24,18,4,'Ja jos astia, jota hän valmisti, meni pilalle, niinkuin savi voi mennä savenvalajan käsissä, niin hän teki siitä taas toisen astian, miten vain savenvalaja näki parhaaksi tehdä.'),
(1688353,58,24,18,5,'Silloin tuli minulle tämä Herran sana:'),
(1688354,58,24,18,6,'"Enkö minä voi tehdä teille, te Israelin heimo, niinkuin tekee tuo savenvalaja, sanoo Herra. Katso, niinkuin savi on savenvalajan kädessä, niin te olette minun kädessäni, te Israelin heimo.'),
(1688355,58,24,18,7,'Yhden kerran minä uhkaan temmata pois, hajottaa ja hävittää kansan ja valtakunnan;'),
(1688356,58,24,18,8,'mutta jos se kansa kääntyy pois pahuudestaan, josta minä sitä uhkasin, niin minä kadun sitä pahaa, jota ajattelin tehdä sille.'),
(1688357,58,24,18,9,'Toisen kerran taas minä lupaan rakentaa ja istuttaa kansan ja valtakunnan;'),
(1688358,58,24,18,10,'mutta jos se tekee sitä, mikä on pahaa minun silmissäni, eikä kuule minun ääntäni, niin minä kadun sitä hyvää, jota olin luvannut tehdä sille.'),
(1688359,58,24,18,11,'Sano siis nyt Juudan miehille ja Jerusalemin asukkaille: Näin sanoo Herra: Katso, minä hankin teille onnettomuutta ja pidän neuvoa teitä vastaan. Kääntykää siis kukin pahalta tieltänne ja parantakaa vaelluksenne ja tekonne.'),
(1688360,58,24,18,12,'Mutta he vastaavat: ''Se on turhaa! Sillä me vaellamme omien neuvojemme mukaan, ja me teemme kukin oman pahan sydämensä paatumuksen mukaan.''"'),
(1688361,58,24,18,13,'Sentähden, näin sanoo Herra: "Kysykää kansojen keskuudessa, kuka on tämänkaltaista kuullut? Ylen kauhistuttavia tekoja on tehnyt neitsyt Israel.'),
(1688362,58,24,18,14,'Luopuuko aukealta kalliolta Libanonin lumi? Ehtyvätkö kaukaa virtaavat vedet, kylmät, kuohuvaiset?'),
(1688363,58,24,18,15,'Mutta minun kansani on unhottanut minut, he polttavat uhreja turhille jumalille. Nämä ovat saaneet heidät kompastumaan teillänsä, ikivanhoilla poluilla, niin että he ovat joutuneet kulkemaan syrjäpolkuja, raivaamatonta tietä.'),
(1688364,58,24,18,16,'Niin he tekevät maansa kauhistukseksi, ikuiseksi ivan vihellykseksi. Jokainen, joka ohitse kulkee, kauhistuu ja pudistaa päätänsä.'),
(1688365,58,24,18,17,'Niinkuin itätuuli minä hajotan heidät vihollisen edessä; minä näytän heille selkäni enkä kasvojani heidän hätänsä päivänä."'),
(1688366,58,24,18,18,'Mutta he sanoivat: "Tulkaa, pitäkäämme neuvoa Jeremiaa vastaan. Sillä ei laki lopu papilta, ei neuvo viisaalta eikä sana profeetalta. Tulkaa, lyökäämme hänet kielellä, älkäämme kuunnelko lainkaan hänen puheitansa."'),
(1688367,58,24,18,19,'Kuuntele sinä, Herra, minua ja kuule, mitä minun vastustajani puhuvat.'),
(1688368,58,24,18,20,'Onko hyvä pahalla kostettava, sillä he ovat kaivaneet minulle kuopan? Muista, kuinka minä olen seisonut sinun edessäsi ja puhunut hyvää heidän puolestansa, kääntääkseni pois sinun vihasi heistä.'),
(1688369,58,24,18,21,'Sentähden jätä heidän lapsensa nääntymään nälkään ja anna heidät alttiiksi miekalle, ja tulkoot heidän vaimonsa lapsettomiksi ja leskiksi, heidän miehensä surmatkoon rutto, ja heidän nuorukaisensa kaatakoon sodassa miekka.'),
(1688370,58,24,18,22,'Kuulukoon huuto heidän huoneistansa, kun sinä äkkiä tuot heidän kimppuunsa rosvojoukon. Sillä he ovat kaivaneet kuopan pyydystääkseen minut ja virittäneet salaa pauloja minun jaloilleni.'),
(1688371,58,24,18,23,'Mutta sinä, Herra, tiedät kaikki heidän murha-aikeensa minua vastaan. Älä anna anteeksi heidän rikostansa äläkä pyyhi pois heidän syntiänsä kasvojesi edestä. Kaatukoot he sinun kasvojesi edessä. Tee tämä heille vihasi aikana.'),
(1688372,58,24,19,1,'Herra sanoi näin: "Mene ja osta savenvalajalta ruukku ja ota mukaasi kansan ja pappien vanhimpia.'),
(1688373,58,24,19,2,'Lähde sitten Ben-Hinnomin laaksoon, joka on Sirpaleportin edustalla, ja julista siellä sanat, jotka minä sinulle puhun.'),
(1688374,58,24,19,3,'Ja sano: Kuulkaa Herran sana, te Juudan kuninkaat ja Jerusalemin asukkaat: Näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä annan sellaisen onnettomuuden kohdata tätä paikkaa, että jokaisen korvat soivat, joka sen kuulee,'),
(1688375,58,24,19,4,'sentähden että he ovat hyljänneet minut ja muuttaneet vieraaksi tämän paikan, ovat polttaneet siinä uhreja muille jumalille, joita he eivät tunteneet, eivät he eivätkä heidän isänsä eivätkä Juudan kuninkaat, ja täyttäneet tämän paikan viattomain verellä,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688376,58,24,19,5,'ovat rakentaneet uhrikukkuloita Baalille ja polttaneet tulessa lapsiansa polttouhreiksi Baalille, mitä minä en ole käskenyt enkä puhunut ja mikä ei ole minun mieleeni tullut.'),
(1688377,58,24,19,6,'Sentähden, katso, päivät tulevat, sanoo Herra, jolloin tätä paikkaa ei enää sanota Toofetiksi eikä Ben-Hinnomin laaksoksi, vaan ''Murhalaaksoksi''.'),
(1688378,58,24,19,7,'Ja minä teen tyhjäksi Juudan ja Jerusalemin neuvon tässä paikassa ja annan heidän kaatua miekkaan vihollistensa edessä, annan heidät niiden käsiin, jotka etsivät heidän henkeänsä, ja annan heidän ruumiinsa ruuaksi taivaan linnuille ja maan eläimille.'),
(1688379,58,24,19,8,'Ja minä teen tämän kaupungin kauhistukseksi ja ivan vihellykseksi. Jokainen, joka ohitse kulkee, kauhistuu ja viheltää kaikille sen haavoille.'),
(1688380,58,24,19,9,'Ja minä panen heidät syömään poikiensa ja tyttäriensä lihaa, ja he syövät toinen toisensa lihaa siinä hädässä ja ahdistuksessa, jolla heitä ahdistavat heidän vihollisensa, ne, jotka etsivät heidän henkeänsä.'),
(1688381,58,24,19,10,'Särje ruukku niiden miesten nähden, jotka ovat tulleet sinun kanssasi.'),
(1688382,58,24,19,11,'Ja sano heille: Näin sanoo Herra Sebaot: Niin minä särjen tämän kansan ja tämän kaupungin, kuin särjetään savenvalajan astia, ettei sitä enää eheäksi saa. Ja Toofetiin haudataan, kun ei ole muualla tilaa, minne haudata.'),
(1688383,58,24,19,12,'Niin minä teen tälle paikalle, sanoo Herra, ja sen asukkaille: minä teen tämän kaupungin Toofetin kaltaiseksi.'),
(1688384,58,24,19,13,'Jerusalemin talot ja Juudan kuningasten talot tulevat Toofetin paikan kaltaisiksi - nuo saastaiset talot kaikki tyynni, joiden katoilla he ovat polttaneet uhreja kaikelle taivaan joukolle ja vuodattaneet juomauhreja muille jumalille."'),
(1688385,58,24,19,14,'Ja Jeremia tuli Toofetista, johon Herra oli lähettänyt hänet ennustamaan, ja asettui Herran huoneen esikartanoon ja sanoi kaikelle kansalle:'),
(1688386,58,24,19,15,'"Näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä tuotan tämän kaupungin ylitse ja kaikkien sen alaisten kaupunkien ylitse kaiken sen onnettomuuden, jolla minä olen sitä uhannut, koska ne ovat olleet niskureita eivätkä ole kuulleet minun sanojani".'),
(1688387,58,24,20,1,'Mutta pappi Pashur, Immerin poika, joka oli Herran temppelin ylivalvoja, kuuli Jeremian ennustavan nämä sanat.'),
(1688388,58,24,20,2,'Ja Pashur löi profeetta Jeremiaa ja pani hänet jalkapuuhun, joka oli Herran huoneeseen kuuluvassa Benjaminin yläportissa.'),
(1688389,58,24,20,3,'Kun Pashur seuraavana päivänä päästi Jeremian jalkapuusta, sanoi Jeremia hänelle: "Herra ei kutsu sinua nimellä Pashur, vaan Maagor-Missabib.'),
(1688390,58,24,20,4,'Sillä näin sanoo Herra: Katso, minä teen sinut kauhistukseksi sekä itsellesi että kaikille ystävillesi; he kaatuvat vihollistensa miekkaan sinun silmiesi nähden, ja koko Juudan minä annan Baabelin kuninkaan käsiin, ja hän vie heidät Baabeliin pakkosiirtolaisuuteen ja surmaa heitä miekalla.'),
(1688391,58,24,20,5,'Ja minä annan kaikki tämän kaupungin rikkaudet, kaiken sen vaivannäön ja kaikki sen kalleudet, kaikki Juudan kuningasten aarteet minä annan heidän vihollistensa käsiin; nämä ryöstävät ne ja ottavat ne ja vievät ne Baabeliin.'),
(1688392,58,24,20,6,'Ja sinä, Pashur, ynnä kaikki, jotka talossasi asuvat, te saatte vaeltaa vankeuteen, ja sinä tulet Baabeliin; sinne sinä kuolet ja sinne sinut haudataan, sinut ja kaikki ystäväsi, joille olet valhetta ennustanut."'),
(1688393,58,24,20,7,'Sinä olet taivutellut minua, Herra, ja minä olen taipunut; sinä olet tarttunut minuun ja voittanut. Minä olen ollut nauruna pitkin päivää, kaikki pilkkaavat minua.'),
(1688394,58,24,20,8,'Sillä niin usein kuin minä puhun, täytyy minun parkua, huutaa väkivaltaa ja sortoa; sillä Herran sana on tullut minulle häväistykseksi ja pilkaksi pitkin päivää.'),
(1688395,58,24,20,9,'Mutta kun minä sanoin: "En tahdo ajatella häntä enkä enää puhua hänen nimessään", niin sydämessäni oli kuin polttava tuli, suljettuna minun luihini. Ja väsyksiin asti minä koetin sitä kestää, mutta en voinut.'),
(1688396,58,24,20,10,'Sillä monen minä kuulen parjaavan. Kauhistus yltympäri! "Ilmiantakaa! Ilmiantakaamme hänet!" Kaikki minun ystäväni vaanivat, milloin minä kompastuisin: "Ehkäpä hän antaa viekoitella itsensä, niin että voitamme hänet ja saamme hänelle kostaa".'),
(1688397,58,24,20,11,'Mutta Herra on minun kanssani niinkuin väkevä sankari; sentähden minun vainoojani kompastuvat eivätkä mitään mahda. He saavat suuren häpeän, sillä he ovat olleet ymmärtämättömät, iankaikkisen pilkan, joka ei ole unhottuva.'),
(1688398,58,24,20,12,'Herra Sebaot, sinä joka tutkit vanhurskaan, näet munaskuut ja sydämen, salli minun nähdä, että kostat heille, sillä sinun huomaasi minä olen jättänyt asiani.'),
(1688399,58,24,20,13,'Veisatkaa Herralle, ylistäkää Herraa, sillä hän pelastaa köyhän pahantekijäin käsistä.'),
(1688400,58,24,20,14,'Kirottu olkoon se päivä, jona minä synnyin; älköön se päivä, jona äitini minut synnytti, olko siunattu.'),
(1688401,58,24,20,15,'Kirottu olkoon se mies, joka toi minun isälleni ilosanoman, sanoen: "Sinulle on syntynyt poikalapsi", ja saattoi hänelle suuren ilon.'),
(1688402,58,24,20,16,'Käyköön sen miehen niinkuin niiden kaupunkien, jotka Herra kukisti armahtamatta. Hän kuulkoon huudon aamulla, sotahuudon keskipäivän aikana,'),
(1688403,58,24,20,17,'koska ei surmannut minua äidinkohtuun, niin että äitini olisi ollut minun hautani ja hänen kohtunsa jäänyt iäti kantavaksi.'),
(1688404,58,24,20,18,'Miksi olen äitini kohdusta tullut näkemään tuskaa ja vaivaa, niin että minun päiväni päättyvät häpeässä?'),
(1688405,58,24,21,1,'Sana, joka tuli Jeremialle Herralta, kun kuningas Sidkia lähetti hänen tykönsä Pashurin, Malkian pojan, ja pappi Sefanjan, Maasejan pojan, sanomaan:'),
(1688406,58,24,21,2,'"Kysy neuvoa Herralta meidän puolestamme, sillä Nebukadressar, Baabelin kuningas, sotii meitä vastaan. Ehkäpä Herra tekee meille ihmeen, kaikkien ihmeittensä vertaisen, niin että tämä lähtee pois meidän kimpustamme."'),
(1688407,58,24,21,3,'Jeremia vastasi heille: "Sanokaa Sidkialle näin:'),
(1688408,58,24,21,4,'Näin sanoo Herra, Israelin Jumala: Katso, minä käännän takaisin sota-aseet, jotka ovat teidän käsissänne ja joilla te muurin ulkopuolella taistelette piirittäjiänne, Baabelin kuningasta ja kaldealaisia, vastaan, ja kokoan ne tämän kaupungin keskelle.'),
(1688409,58,24,21,5,'Ja minä itse sodin teitä vastaan ojennetulla kädellä ja väkevällä käsivarrella, vihassa ja kiivastuksessa ja suuressa suuttumuksessa.'),
(1688410,58,24,21,6,'Ja minä tuhoan tämän kaupungin asukkaat, ihmiset ja eläimet; he kuolevat suureen ruttoon.'),
(1688411,58,24,21,7,'Ja sen jälkeen, sanoo Herra, minä annan Sidkian, Juudan kuninkaan, ja hänen palvelijansa ja kansan ja ne, jotka ovat tähän kaupunkiin jääneet jäljelle rutolta, miekalta ja nälältä, Nebukadressarin, Baabelin kuninkaan, käsiin ja heidän vihollistensa käsiin, niiden, jotka etsivät heidän henkeänsä, ja hän surmaa heidät miekan terällä; ei hän säästä heitä, ei sääli eikä armahda.'),
(1688412,58,24,21,8,'Ja sano tälle kansalle: Näin sanoo Herra: Katso, minä panen teidän eteenne elämän tien ja kuoleman tien.'),
(1688413,58,24,21,9,'Joka jää tähän kaupunkiin, se kuolee miekkaan, nälkään ja ruttoon; mutta joka lähtee ulos ja menee kaldealaisten puolelle, jotka teitä piirittävät, se saa elää ja pitää henkensä saaliinansa.'),
(1688414,58,24,21,10,'Sillä minä olen kääntänyt kasvoni tätä kaupunkia vastaan, sen onnettomuudeksi eikä onneksi, sanoo Herra; Baabelin kuninkaan käsiin se annetaan, ja hän polttaa sen tulella.'),
(1688415,58,24,21,11,'Ja sano Juudan kuninkaan huoneelle: Kuulkaa Herran sana:'),
(1688416,58,24,21,12,'Daavidin huone! Näin sanoo Herra: Tuomitkaa joka aamu oikeat tuomiot ja pelastakaa ryöstetty sortajan kädestä, ettei minun vihani syttyisi kuin tuli ja palaisi, eikä olisi sammuttajaa, teidän tekojenne pahuuden tähden.'),
(1688417,58,24,21,13,'Katso, minä käyn sinun kimppuusi, sinä laakson asujatar, sinä tasangon kalliolinna, sanoo Herra, teidän kimppuunne, jotka sanotte: ''Kuka voi astua alas meitä vastaan, kuka tulla meidän asuntoihimme?'''),
(1688418,58,24,21,14,'Minä rankaisen teitä teidän tekojenne hedelmän mukaan, sanoo Herra, ja sytytän tuleen sen kaupungin metsän, ja tuli kuluttaa kaiken, mitä sen ympärillä on."'),
(1688419,58,24,22,1,'Näin sanoo Herra: "Mene alas Juudan kuninkaan linnaan ja puhu siellä tämä sana;'),
(1688420,58,24,22,2,'sano: Kuule Herran sana, sinä Juudan kuningas, joka istut Daavidin valtaistuimella, sinä ja sinun palvelijasi ja kansasi, jotka käytte sisälle näistä porteista.'),
(1688421,58,24,22,3,'Näin sanoo Herra: Tehkää oikeus ja vanhurskaus ja pelastakaa ryöstetty sortajan kädestä; muukalaiselle, orvolle ja leskelle älkää tehkö vääryyttä ja väkivaltaa älkääkä vuodattako viatonta verta tässä paikassa.'),
(1688422,58,24,22,4,'Sillä jos te teette tämän sanan mukaan, niin tulee tämän linnan porteista sisälle, ajaen vaunuilla ja hevosilla, kuninkaita, jotka istuvat Daavidin valtaistuimella, tulee kuningas ynnä hänen palvelijansa ja kansansa.'),
(1688423,58,24,22,5,'Mutta jos te ette kuule näitä sanoja, niin minä vannon itse kauttani, sanoo Herra, että tämä linna on tuleva raunioiksi.'),
(1688424,58,24,22,6,'Sillä näin sanoo Herra Juudan kuninkaan linnasta: Sinä olet minulle Gilead, olet Libanonin huippu; mutta totisesti, minä teen sinut erämaaksi, asumattomiksi kaupungeiksi.'),
(1688425,58,24,22,7,'Minä vihin hävittäjät sinua vastaan, kunkin aseinensa, ja he hakkaavat maahan sinun valiosetrisi ja heittävät ne tuleen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688426,58,24,22,8,'Monet kansat kulkevat tämän kaupungin ohitse ja kysyvät toinen toiseltansa: ''Miksi on Herra tehnyt näin tälle suurelle kaupungille?'''),
(1688427,58,24,22,9,'Ja siihen vastataan: ''Siksi, että he hylkäsivät Herran, Jumalansa, liiton ja kumarsivat muita jumalia ja palvelivat niitä''.'),
(1688428,58,24,22,10,'Älkää kuollutta itkekö älkääkä häntä surkutelko, vaan itkekää tuota poiskulkevaa, sillä hän ei enää palaja eikä saa nähdä synnyinmaatansa.'),
(1688429,58,24,22,11,'Sillä näin sanoo Herra Sallumista, Joosian pojasta, Juudan kuninkaasta, joka tuli kuninkaaksi isänsä Joosian sijaan ja joka on vaeltanut pois tästä paikasta: Hän ei enää tänne palaja;'),
(1688430,58,24,22,12,'vaan mihin hänet on vangiksi viety, sinne hän kuolee eikä näe enää tätä maata.'),
(1688431,58,24,22,13,'Voi häntä, joka ei vanhurskaudella taloansa rakenna eikä yläsalejansa oikeudella; joka ilmaiseksi teettää työtä lähimmäisellään eikä anna hänelle hänen palkkaansa;'),
(1688432,58,24,22,14,'joka sanoo: ''Minä rakennan itselleni tilavan talon ja avarat yläsalit'', joka hakkauttaa siihen ikkunat, laudoittaa sen setripuulla ja maalauttaa punavärillä.'),
(1688433,58,24,22,15,'Siksikö sinä olet kuningas, että sinulla on into setripuuhun? Eikö sinun isäsikin syönyt ja juonut ja kuitenkin ollut oikeuden ja vanhurskauden tekijä? Ja silloin hänen kävi hyvin.'),
(1688434,58,24,22,16,'Hän hankki oikeuden kurjalle ja köyhälle; silloin kaikki kävi hyvin. Eikö tämä juuri ole minun tuntemistani, sanoo Herra?'),
(1688435,58,24,22,17,'Mutta sinun silmäsi ja sydämesi eivät pyydä muuta kuin omaa voittoasi, muuta kuin vuodattaa viatonta verta ja harjoittaa väkivaltaa ja sortoa.'),
(1688436,58,24,22,18,'Sentähden, näin sanoo Herra Joojakimista, Joosian pojasta, Juudan kuninkaasta: Ei hänelle pidetä valittajaisia eikä huudeta: ''Voi veljeni! Voi sisareni!'' Ei hänelle pidetä valittajaisia eikä huudeta: ''Voi herraamme! Voi hänen loistoansa!'''),
(1688437,58,24,22,19,'Hänet haudataan niinkuin aasi haudataan: raahataan pois ja viskataan Jerusalemin porttien tuolle puolen.'),
(1688438,58,24,22,20,'Nouse Libanonille ja huuda, korota äänesi Baasanissa. Huuda Abarimin vuorilta, sillä kaikki sinun rakastajasi ovat murskaksi muserretut.'),
(1688439,58,24,22,21,'Minä puhuin sinulle onnesi päivinä. Sinä vastasit: ''En tahdo kuulla''. Tämä on ollut sinun tapasi nuoruudestasi asti: et ole kuullut minun ääntäni.'),
(1688440,58,24,22,22,'Myrskytuuli on kaitseva kaikkia sinun kaitsijoitasi, ja sinun rakastajasi menevät vankeuteen; silloin sinä saat häpeän ja pilkan kaiken pahuutesi tähden.'),
(1688441,58,24,22,23,'Sinä, joka asut Libanonissa, pidät pesääsi setripuissa: kuinka olet voihkiva, kun sinulle tuskat tulevat, kouristus niinkuin synnyttäväiselle!'),
(1688442,58,24,22,24,'Niin totta kuin minä elän, sanoo Herra: olkoon Konja, Joojakimin poika, Juudan kuningas, vaikka sinettisormus minun oikeassa kädessäni - siitäkin minä sinut repäisen irti.'),
(1688443,58,24,22,25,'Ja minä annan sinut niiden käsiin, jotka etsivät sinun henkeäsi, niiden käsiin, joita sinä kauhistut: Nebukadressarin, Baabelin kuninkaan, ja kaldealaisten käsiin.'),
(1688444,58,24,22,26,'Ja minä heitän sinut ja sinun äitisi, joka on sinut synnyttänyt, vieraalle maalle, missä te ette ole syntyneet, ja sinne te kuolette.'),
(1688445,58,24,22,27,'Mutta maahan, jonne heidän sielunsa halajaa palata, sinne he eivät palaa.'),
(1688446,58,24,22,28,'Onko sitten tämä mies, Konja, arvoton, rikottu astia, kelvoton kapine? Minkätähden on hänet ja hänen jälkeläisensä heitetty pois, viskattu pois - maahan, jota eivät tunne?'),
(1688447,58,24,22,29,'Maa, maa, maa! Kuule Herran sana!'),
(1688448,58,24,22,30,'Näin sanoo Herra: Merkitkää tämä mies lapsettomaksi, mieheksi, jolla ei elinpäivinänsä onnea ole. Sillä ei kenellekään hänen jälkeläisistänsä sitä onnea tule, että istuisi Daavidin valtaistuimella ja hallitsi vielä Juudaa."'),
(1688449,58,24,23,1,'"Voi paimenia, jotka hukuttavat ja hajottavat minun laitumeni lampaat, sanoo Herra.'),
(1688450,58,24,23,2,'Sentähden näin sanoo Herra, Israelin Jumala, paimenista, jotka kaitsevat minun kansaani: Te olette hajottaneet minun lampaani ja karkoittaneet ne pois ettekä ole pitäneet niistä huolta. Katso, minä pidän huolen teidän pahain tekojenne rankaisemisesta, sanoo Herra.'),
(1688451,58,24,23,3,'Ja minä kokoan lampaitteni tähteet kaikista maista, joihin olen ne karkoittanut, ja tuon ne takaisin laitumelleen, ja ne ovat hedelmälliset ja lisääntyvät.'),
(1688452,58,24,23,4,'Ja minä herätän heille paimenia, ja ne kaitsevat heitä; eivät he enää pelkää eivätkä säiky, eikä heistä yhtäkään puutu, sanoo Herra.'),
(1688453,58,24,23,5,'Katso, päivät tulevat, sanoo Herra, jolloin minä herätän Daavidille vanhurskaan vesan; hän on hallitseva kuninkaana ja menestyvä, ja hän on tekevä oikeuden ja vanhurskauden maassa.'),
(1688454,58,24,23,6,'Hänen päivinänsä pelastetaan Juuda ja Israel asuu turvassa. Ja tämä on hänen nimensä, jolla häntä kutsutaan: ''Herra on meidän vanhurskautemme''.'),
(1688455,58,24,23,7,'Sentähden, katso, päivät tulevat, sanoo Herra, jolloin ei enää sanota: ''Niin totta kuin Herra elää, joka johdatti israelilaiset Egyptin maasta'','),
(1688456,58,24,23,8,'vaan: ''Niin totta kuin Herra elää, joka johdatti ja toi Israelin heimon jälkeläiset pohjoisesta maasta ja kaikista muista maista, joihin minä olin heidät karkoittanut''. Ja niin he saavat asua omassa maassansa."'),
(1688457,58,24,23,9,'Profeettoja vastaan. Minun sydämeni on murtunut rinnassani, kaikki luuni raukeavat. Minä olen kuin juopunut mies, kuin sankari, jonka viini on voittanut, Herran edessä ja hänen pyhien sanojensa edessä.'),
(1688458,58,24,23,10,'"Sillä maa on täynnä avionrikkojia, maa murehtii kirouksen tähden, erämaan laitumet kuivuvat; he rientävät pahuuteen, ja heidän väkevyytensä on väärä meno.'),
(1688459,58,24,23,11,'Sillä he ovat jumalattomia, niin profeetta kuin pappikin; omasta huoneestanikin minä olen tavannut heidän pahuutensa, sanoo Herra.'),
(1688460,58,24,23,12,'Sentähden heidän tiensä on oleva heille kuin liukas polku pimeässä, he suistuvat sillä ja kaatuvat; sillä minä tuotan heille onnettomuuden heidän rangaistusvuotenansa, sanoo Herra.'),
(1688461,58,24,23,13,'Samarian profeetoissa minä näin pahennuksen: he ennustivat Baalin nimessä ja eksyttivät minun kansani Israelin.'),
(1688462,58,24,23,14,'Mutta Jerusalemin profeetoissa minä olen nähnyt kauhistuksia: aviorikosta ja valheessa vaeltamista; he vahvistavat pahantekijäin käsiä, niin ettei kukaan käänny pois pahuudestansa. He ovat minun edessäni kaikki kuin Sodoma, ja kaupungin asukkaat kuin Gomorra.'),
(1688463,58,24,23,15,'Sentähden, näin sanoo Herra Sebaot profeetoista: Katso, minä syötän heille koiruohoa ja juotan heille myrkkyvettä; sillä Jerusalemin profeetoista on jumalattomuus levinnyt koko maahan.'),
(1688464,58,24,23,16,'Näin sanoo Herra Sebaot: Älkää kuulko profeettain sanoja, noiden, jotka teille ennustavat täyttäen teidät tyhjillä toiveilla: oman sydämensä näkyjä he puhuvat, mutta eivät sitä, mikä tulee Herran suusta.'),
(1688465,58,24,23,17,'He hokevat minun halveksijoilleni: ''Herra on sen sanonut: Teillä on oleva rauha!'' Ja kaikille, jotka vaeltavat sydämensä paatumuksessa, he sanovat: ''Ei teitä kohtaa onnettomuus''.'),
(1688466,58,24,23,18,'Mutta kuka on seisonut Herran neuvottelussa ja nähnyt ja kuullut hänen sanansa? Kuka on tarkannut ja kuullut hänen sanansa?"'),
(1688467,58,24,23,19,'Katso, Herran myrsky, kiivastus, puhkeaa, pyörremyrsky vyöryy kohti jumalattomien päätä.'),
(1688468,58,24,23,20,'Eikä Herran viha asetu, ennenkuin hän on toteuttanut ja täyttänyt sydämensä aivoitukset. Aikojen lopulla te tulette sen hyvin ymmärtämään.'),
(1688469,58,24,23,21,'"Minä en ole lähettänyt noita profeettoja, mutta silti he juoksevat. Minä en ole puhunut heille, mutta kuitenkin he ennustavat.'),
(1688470,58,24,23,22,'Jos he olisivat seisoneet minun neuvottelussani, niin he julistaisivat minun sanani kansalleni ja kääntäisivät heidät pois heidän pahalta tieltään ja pahoista teoistansa.'),
(1688471,58,24,23,23,'Olenko minä Jumala vain lyhyeltä matkalta, sanoo Herra; enkö ole Jumala myöskin kaukaa?'),
(1688472,58,24,23,24,'Saattaako joku niin piiloon piiloutua, etten minä häntä näe? sanoo Herra. Enkö minä täytä taivasta ja maata? sanoo Herra.'),
(1688473,58,24,23,25,'Minä olen kuullut, mitä sanovat nuo profeetat, jotka ennustavat minun nimessäni valhetta sanoen: ''Minä olen nähnyt unta, olen nähnyt unta''.'),
(1688474,58,24,23,26,'Kuinka kauan? Mitä on mielessä noilla profeetoilla, jotka ennustavat valhetta, ennustavat oman sydämensä petosta?'),
(1688475,58,24,23,27,'Aikovatko he unillaan, joita he kertovat toinen toisellensa, saattaa minun kansani unhottamaan minun nimeni, niinkuin heidän isänsä ovat unhottaneet minun nimeni Baalin tähden?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688476,58,24,23,28,'Se profeetta, jolla on uni, kertokoon unensa; mutta se, jolla on minun sanani, puhukoon minun sanani uskollisesti. Mitä tekevät oljet jyvien seassa? sanoo Herra.'),
(1688477,58,24,23,29,'Eikö minun sanani ole niinkuin tuli, sanoo Herra, ja niinkuin vasara, joka kallion murtaa?'),
(1688478,58,24,23,30,'Katso, sentähden minä käyn niiden profeettain kimppuun, sanoo Herra, jotka varastavat minun sanani toinen toiseltansa.'),
(1688479,58,24,23,31,'Katso, minä käyn niiden profeettain kimppuun, sanoo Herra, jotka ottavat sanansa omalta kieleltään, mutta sanovat: ''Se on Herran sana''.'),
(1688480,58,24,23,32,'Katso, minä käyn niiden kimppuun, jotka ennustavat valheunia, sanoo Herra, ja kertovat niitä ja eksyttävät minun kansaani valheillansa ja kerskumisellansa, vaikka minä en ole heitä lähettänyt enkä käskenyt ja vaikka heistä ei ole mitään hyötyä tälle kansalle, sanoo Herra.'),
(1688481,58,24,23,33,'Ja kun tämä kansa tai profeetta tai pappi sinulta kysyy sanoen: ''Mikä on Herran ennustuksen kuorma?'' niin sano heille: ''Mikä kuorma? - Teidät minä heitän pois'', sanoo Herra.'),
(1688482,58,24,23,34,'Ja sitä profeettaa, pappia ja kansaa, joka sanoo: ''Herran kuorma'' - sitä miestä ja hänen huonettansa minä rankaisen.'),
(1688483,58,24,23,35,'Näin sanokaa keskenänne, toinen toisellenne: ''Mitä on Herra vastannut?'' ja ''Mitä on Herra puhunut?'''),
(1688484,58,24,23,36,'Mutta ''Herran kuormaa'' älkää enää mainitko; sillä kuormaksi on tuleva jokaiselle hänen oma sanansa. Te vääntelette elävän Jumalan, Herran Sebaotin, teidän Jumalanne, sanoja.'),
(1688485,58,24,23,37,'Näin sano profeetalle: ''Mitä on Herra sinulle vastannut? Mitä on Herra puhunut?'''),
(1688486,58,24,23,38,'Mutta jos te sanotte: ''Herran kuorma'', silloin Herra sanoo näin: Koska te sanotte tämän sanan: ''Herran kuorma'', vaikka minä olen lähettänyt teidän tykönne sanomaan: Älkää sanoko: ''Herran kuorma'','),
(1688487,58,24,23,39,'sentähden katso: minä kokonaan unhotan teidät ja heitän pois kasvojeni edestä teidät ja tämän kaupungin, jonka minä annoin teille ja teidän isillenne.'),
(1688488,58,24,23,40,'Ja minä panen teidän päällenne iankaikkisen häpeän ja iankaikkisen pilkan, joka ei ole unhottuva."'),
(1688489,58,24,24,1,'Ja Herra näytti minulle näyn, ja katso, kaksi viikunakoria oli asetettu Herran temppelin edustalle, sen jälkeen kuin Nebukadressar, Baabelin kuningas, oli siirtänyt pois Jekonjan, Joojakimin pojan, Juudan kuninkaan, ja Juudan päämiehet sekä sepät ja lukkosepät Jerusalemista ja vienyt heidät Baabeliin.'),
(1688490,58,24,24,2,'Toisessa korissa oli ylen hyviä viikunoita, uudisviikunain kaltaisia, ja toisessa korissa oli ylen huonoja viikunoita, niin huonoja, ettei niitä voinut syödä.'),
(1688491,58,24,24,3,'Ja Herra sanoi minulle: "Mitä sinä näet, Jeremia?" Minä vastasin: "Viikunoita. Hyvät viikunat ovat ylen hyviä, mutta huonot ovat ylen huonoja, niin huonoja, ettei niitä voi syödä."'),
(1688492,58,24,24,4,'Ja minulle tuli tämä Herran sana:'),
(1688493,58,24,24,5,'"Näin sanoo Herra, Israelin Jumala: Niinkuin näitä hyviä viikunoita, niin minä katselen hyvällä suosiolla Juudan pakkosiirtolaisia, jotka minä lähetin tästä paikasta kaldealaisten maahan.'),
(1688494,58,24,24,6,'Ja minä käännän katseeni heihin, heidän hyväksensä, ja tuon heidät takaisin tähän maahan. Minä rakennan heidät enkä hajota, minä istutan heidät enkä revi pois.'),
(1688495,58,24,24,7,'Ja minä annan heille sydämen, heidän tunteakseen minut, että minä olen Herra; ja he saavat olla minun kansani, ja minä olen heidän Jumalansa; sillä he kääntyvät minun tyköni kaikesta sydämestänsä.'),
(1688496,58,24,24,8,'Mutta niinkuin tehdään huonoille viikunoille, joita ei voi syödä, kun ovat niin huonoja, niin minä, sanoo Herra, teen Sidkialle, Juudan kuninkaalle, ja hänen ruhtinailleen ja Jerusalemin jäännökselle, niille, jotka ovat jääneet jäljelle tähän maahan, ja niille, jotka asuvat Egyptin maassa:'),
(1688497,58,24,24,9,'Minä teen heidät kauhistukseksi ja onnettomuudeksi kaikille valtakunnille maan päällä, häväistykseksi ja sananparreksi, pistopuheeksi ja kiroussanaksi kaikissa paikoissa, mihin minä heidät karkoitan.'),
(1688498,58,24,24,10,'Ja minä lähetän heidän sekaansa miekan, nälän ja ruton, kunnes he ovat hävinneet siitä maasta, jonka minä olen antanut heille ja heidän isillensä."'),
(1688499,58,24,25,1,'Sana, joka tuli Jeremialle, sana koko Juudan kansaa vastaan, Joojakimin, Joosian pojan, Juudan kuninkaan, neljäntenä vuotena, se on Nebukadressarin, Baabelin kuninkaan, ensimmäisenä vuotena -'),
(1688500,58,24,25,2,'sana, jonka profeetta Jeremia lausui koko Juudan kansaa ja kaikkia Jerusalemin asukkaita vastaan sanoen:'),
(1688501,58,24,25,3,'Joosian, Aamonin pojan, Juudan kuninkaan, kolmannestatoista vuodesta alkaen tähän päivään saakka - kaksikymmentä kolme vuotta - on Herran sana tullut minulle, ja minä olen teille puhunut varhaisesta alkaen, mutta te ette ole kuulleet.'),
(1688502,58,24,25,4,'Ja Herra on lähettänyt teidän tykönne kaikki palvelijansa, profeetat, varhaisesta alkaen, mutta te ette ole kuulleet, ette kallistaneet korvaanne kuullaksenne,'),
(1688503,58,24,25,5,'kun he sanoivat: "Kääntykää itsekukin pahalta tieltänne ja pahoista teoistanne, niin saatte asua maassa, jonka Herra on antanut teille ja teidän isillenne, iankaikkisesta iankaikkiseen.'),
(1688504,58,24,25,6,'Älkää seuratko muita jumalia, älkää palvelko ja kumartako niitä älkääkä vihoittako minua kättenne töillä, etten tuottaisi teille onnettomuutta." -'),
(1688505,58,24,25,7,'"Mutta te ette kuulleet minua, sanoo Herra, ja niin te vihoititte minut kättenne töillä, omaksi onnettomuudeksenne.'),
(1688506,58,24,25,8,'Sentähden näin sanoo Herra Sebaot: Koska te ette ole kuulleet minun sanojani,'),
(1688507,58,24,25,9,'niin katso, minä lähetän sanan, minä nostan kaikki pohjanpuolen kansanheimot, sanoo Herra, sanan Nebukadressarille, Baabelin kuninkaalle, palvelijalleni, ja tuon heidät tätä maata ja sen asukkaita vastaan ja kaikkia näitä ympärillä olevia kansoja vastaan. Ja nämä minä vihin tuhon omiksi ja teen heidät kauhistukseksi, ivan vihellykseksi ja ikuisiksi raunioiksi.'),
(1688508,58,24,25,10,'Minä hävitän heidän keskuudestaan riemun ja ilon huudon, huudon yljälle ja huudon morsiamelle, käsikivien äänen ja lampun valon.'),
(1688509,58,24,25,11,'Niin koko tämä maa tulee raunioiksi, autioksi, ja nämä kansat palvelevat Baabelin kuningasta seitsemänkymmentä vuotta.'),
(1688510,58,24,25,12,'Mutta kun seitsemänkymmentä vuotta on täyttynyt, niin minä kostan Baabelin kuninkaalle ja sille kansalle, sanoo Herra, heidän pahat tekonsa, kostan kaldealaisten maalle ja teen sen ikuiseksi erämaaksi.'),
(1688511,58,24,25,13,'Ja minä tuotan sen maan ylitse kaikki sanani, jotka minä olen puhunut sitä vastaan, kaiken, mitä tähän kirjaan on kirjoitettu, mitä Jeremia on ennustanut kaikkia niitä kansoja vastaan.'),
(1688512,58,24,25,14,'Sillä hekin joutuvat palvelemaan monia kansoja ja suuria kuninkaita, ja minä maksan heille heidän tekojensa ja kättensä töiden mukaan."'),
(1688513,58,24,25,15,'Sillä näin sanoi Herra, Israelin Jumala, minulle: "Ota tämä vihan viinin malja minun kädestäni ja juota sillä kaikki kansat, joiden tykö minä sinut lähetän.'),
(1688514,58,24,25,16,'He juovat ja horjuvat ja tulevat mielettömiksi miekan edessä, jonka minä lähetän heidän keskellensä."'),
(1688515,58,24,25,17,'Ja minä otin maljan Herran kädestä ja juotin kaikkia kansoja, joiden tykö Herra minut lähetti:'),
(1688516,58,24,25,18,'Jerusalemia ja Juudan kaupunkeja, sen kuninkaita ja ruhtinaita, tehdäkseni heidät raunioiksi, kauhistukseksi, ivan vihellykseksi ja kiroukseksi, niinkuin tänä päivänä tapahtuu;'),
(1688517,58,24,25,19,'faraota, Egyptin kuningasta, ja hänen palvelijoitansa ja ruhtinaitansa ja koko hänen kansaansa;'),
(1688518,58,24,25,20,'kaikkea sekakansaa ja kaikkia Uusin maan kuninkaita ja kaikkia filistealaisten maan kuninkaita ja Askelonia ja Gassaa ja Ekronia ja Asdodin tähteitä;'),
(1688519,58,24,25,21,'Edomia, Mooabia ja ammonilaisia;'),
(1688520,58,24,25,22,'kaikkia Tyyron kuninkaita ja kaikkia Siidonin kuninkaita ja rantamaan kuninkaita, jotka ovat meren tuolla puolen;'),
(1688521,58,24,25,23,'Dedania, Teemaa ja Buusia ja kaikkia päälaen ympäriltä kerittyjä;'),
(1688522,58,24,25,24,'kaikkia Arabian kuninkaita ja kaikkia sekakansan kuninkaita, jotka asuvat erämaassa;'),
(1688523,58,24,25,25,'kaikkia Simrin kuninkaita ja kaikkia Eelamin kuninkaita ja kaikkia Meedian kuninkaita;'),
(1688524,58,24,25,26,'kaikkia pohjanpuolen kuninkaita, läheisiä ja kaukaisia, toista toisensa jälkeen, ja kaikkia maan valtakuntia, mitä maan päällä on. Ja heidän jälkeensä on Seesakin kuningas juova.'),
(1688525,58,24,25,27,'"Sano heille: Näin sanoo Herra Sebaot, Israelin Jumala: Juokaa ja juopukaa, oksentakaa ja kaatukaa, älkääkä enää nousko, - miekan edessä, jonka minä lähetän teidän keskellenne.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688526,58,24,25,28,'Mutta jos he eivät tahdo ottaa maljaa sinun kädestäsi ja juoda, niin sano heille: Näin sanoo Herra Sebaot: Teidän täytyy juoda.'),
(1688527,58,24,25,29,'Sillä katso, siitä kaupungista alkaen, joka on otettu minun nimiini, minä alotan onnettomuuden tuottamisen; ja tekö jäisitte rankaisematta! Te ette jää rankaisematta, sillä minä kutsun miekan kaikkia maan asukkaita vastaan, sanoo Herra Sebaot.'),
(1688528,58,24,25,30,'Mutta sinä, ennusta heille kaikki nämä sanat ja sano heille: Herra ärjyy korkeudesta, antaa äänensä kaikua pyhästä asunnostansa. Hän ärjyy väkevästi yli laitumensa. Hän nostaa kuin viinikuurnan polkijat huudon kaikkia maan asukkaita vastaan.'),
(1688529,58,24,25,31,'Pauhina käy maan ääriin asti, sillä Herralla on riita-asia kansoja vastaan, hän käy oikeutta kaiken lihan kanssa: jumalattomat hän antaa miekalle alttiiksi, sanoo Herra.'),
(1688530,58,24,25,32,'Näin sanoo Herra Sebaot: Katso, onnettomuus kulkee kansasta kansaan, ja suuri myrsky nousee maan perimmäisistä ääristä.'),
(1688531,58,24,25,33,'Ja Herran surmaamia on oleva sinä päivänä maan äärestä maan ääreen. Ei heille pidetä valittajaisia, ei heitä koota eikä haudata; he tulevat maan lannaksi.'),
(1688532,58,24,25,34,'Parkukaa, te paimenet, ja huutakaa, vieriskelkää tuhassa, te lauman valtiaat; sillä aika on tullut teidän joutua teurastettaviksi. Te hajoatte pirstoiksi, te kaadutte niinkuin kallisarvoinen astia.'),
(1688533,58,24,25,35,'Mennyt on paimenilta pakopaikka ja pelastus lauman valtiailta.'),
(1688534,58,24,25,36,'Kuule paimenten huutoa, lauman valtiaitten valitusta! Sillä Herra hävittää heidän laumansa;'),
(1688535,58,24,25,37,'heidän rauhaisat laitumensa ovat tuhoutuneet Herran vihan hehkusta.'),
(1688536,58,24,25,38,'Hän on lähtenyt niinkuin nuori leijona pensaikostaan: heidän maansa on tullut autioksi hävittäjän vihan hehkusta, Herran vihan hehkusta."'),
(1688537,58,24,26,1,'Joojakimin, Joosian pojan, Juudan kuninkaan, hallituksen alussa tuli Herralta tämä sana:'),
(1688538,58,24,26,2,'"Näin sanoo Herra: Asetu Herran temppelin esipihaan ja puhu kaikkia Juudan kaupunkeja vastaan, jotka tulevat kumartaen rukoilemaan Herran temppeliin, kaikki ne sanat, jotka minä olen käskenyt sinun sanoa heille; älä jätä pois sanaakaan.'),
(1688539,58,24,26,3,'Ehkäpä he kuulevat ja kääntyvät itsekukin pois pahalta tieltään, ja niin minä kadun sitä onnettomuutta, jonka minä olen aikonut heille tuottaa heidän pahojen tekojensa tähden.'),
(1688540,58,24,26,4,'Ja sano heille: Näin sanoo Herra: Jollette kuule minua ja vaella minun lakini mukaan, jonka minä olen teille antanut,'),
(1688541,58,24,26,5,'ettekä kuule palvelijaini, profeettain, sanoja, niiden, jotka minä olen lähettänyt teidän tykönne, varhaisesta alkaen, vaikka ette ole kuulleet heitä,'),
(1688542,58,24,26,6,'niin minä teen tälle temppelille niinkuin Siilolle, ja minä teen tämän kaupungin kiroussanaksi kaikille maan kansoille."'),
(1688543,58,24,26,7,'Ja papit ja profeetat ja koko kansa kuulivat Jeremian puhuvan nämä sanat Herran temppelissä.'),
(1688544,58,24,26,8,'Ja kun Jeremia oli puhunut loppuun kaiken, minkä Herra oli käskenyt hänen puhua kaikelle kansalle, niin papit ja profeetat ja koko kansa ottivat hänet kiinni sanoen: "Sinun on kuolemalla kuoltava!'),
(1688545,58,24,26,9,'Miksi olet ennustanut Herran nimessä sanoen: Tälle temppelille on käyvä niinkuin Siilolle, ja tämä kaupunki on tuleva raunioiksi, asujattomaksi?" Ja kaikki kansa kokoontui Jeremiaa vastaan Herran temppelissä.'),
(1688546,58,24,26,10,'Kun Juudan päämiehet tämän kuulivat, menivät he kuninkaan palatsista Herran temppeliin ja istuivat Herran uuden portin ovelle.'),
(1688547,58,24,26,11,'Silloin papit ja profeetat sanoivat päämiehille ja kaikelle kansalle näin: "Kuoleman tuomio tälle miehelle! Sillä hän on ennustanut tätä kaupunkia vastaan, niinkuin olette omin korvin kuulleet."'),
(1688548,58,24,26,12,'Mutta Jeremia sanoi kaikille päämiehille ja kaikelle kansalle näin: "Herra on lähettänyt minut ennustamaan tätä temppeliä ja tätä kaupunkia vastaan kaikki ne sanat, jotka olette kuulleet.'),
(1688549,58,24,26,13,'Parantakaa siis nyt vaelluksenne ja tekonne ja kuulkaa Herran, teidän Jumalanne, ääntä, niin Herra katuu sitä onnettomuutta, jolla hän on teitä uhannut.'),
(1688550,58,24,26,14,'Mutta katso, minä olen teidän käsissänne; tehkää minulle, mitä katsotte hyväksi ja oikeaksi.'),
(1688551,58,24,26,15,'Mutta se tietäkää, että te, jos minut surmaatte, saatatte viattoman veren päällenne ja tämän kaupungin ja sen asukasten päälle, sillä totisesti on Herra lähettänyt minut teidän tykönne puhumaan kaikki nämä sanat teidän korvienne kuullen."'),
(1688552,58,24,26,16,'Silloin päämiehet ja kaikki kansa sanoivat papeille ja profeetoille: "Ei kuoleman tuomiota tälle miehelle! Sillä hän on puhunut meille Herran, meidän Jumalamme, nimessä."'),
(1688553,58,24,26,17,'Ja muutamat maan vanhimmista nousivat ja sanoivat kaikelle kansan joukolle näin:'),
(1688554,58,24,26,18,'"Miika, mooresetilainen, ennusti Hiskian, Juudan kuninkaan, päivinä ja sanoi kaikelle Juudan kansalle näin: Näin sanoo Herra Sebaot: ''Siion kynnetään pelloksi, ja Jerusalem tulee kiviraunioksi ja temppelivuori metsäkukkulaksi''.'),
(1688555,58,24,26,19,'Surmasivatko hänet silloin Hiskia, Juudan kuningas, ja koko Juuda? Eikö hän peljännyt Herraa ja lepyttänyt häntä, niin että Herra katui sitä onnettomuutta, jolla hän oli heitä uhannut? Mutta mekö tuottaisimme suuren onnettomuuden itsellemme?"'),
(1688556,58,24,26,20,'Mutta oli toinenkin mies, joka ennusti Herran nimessä: Uuria, Semajan poika, Kirjat-Jearimista; hän ennusti tätä kaupunkia ja tätä maata vastaan aivan niinkuin Jeremia.'),
(1688557,58,24,26,21,'Kun kuningas Joojakim ja kaikki hänen urhonsa ja kaikki päämiehet kuulivat hänen sanansa, niin kuningas etsi häntä tappaaksensa. Sen kuultuansa Uuria peljästyi, pakeni ja meni Egyptiin.'),
(1688558,58,24,26,22,'Mutta kuningas Joojakim lähetti miehiä Egyptiin: Elnatanin, Akborin pojan, ja muita hänen kanssansa Egyptiin.'),
(1688559,58,24,26,23,'Ja he toivat Uurian Egyptistä ja veivät hänet kuningas Joojakimin eteen. Tämä surmautti hänet miekalla ja heitätti hänen ruumiinsa rahvaan hautaan.'),
(1688560,58,24,26,24,'Mutta Ahikamin, Saafanin pojan, käsi oli Jeremian suojana, niin ettei häntä jätetty kansan käsiin surmattavaksi.'),
(1688561,58,24,27,1,'Joojakimin, Joosian pojan, Juudan kuninkaan, hallituksen alussa tuli Herralta tämä sana Jeremialle:'),
(1688562,58,24,27,2,'Näin sanoi Herra minulle: "Tee itsellesi ies siteinensä ja pane se kaulaasi.'),
(1688563,58,24,27,3,'Lähetä se Edomin kuninkaalle, Mooabin kuninkaalle, ammonilaisten kuninkaalle, Tyyron kuninkaalle ja Siidonin kuninkaalle niiden lähettiläiden mukana, jotka ovat tulleet Jerusalemiin Sidkian, Juudan kuninkaan, tykö.'),
(1688564,58,24,27,4,'Ja käske heidän sanoa herroillensa: Näin sanoo Herra Sebaot, Israelin Jumala: Näin sanokaa herroillenne:'),
(1688565,58,24,27,5,'Minä olen tehnyt maan sekä ihmiset ja eläimet, jotka maan päällä ovat, suurella voimallani ja ojennetulla käsivarrellani, ja minä annan sen, kenelle hyväksi näen.'),
(1688566,58,24,27,6,'Ja nyt minä annan kaikki nämä maat Nebukadnessarin, Baabelin kuninkaan, palvelijani, käsiin, ja myöskin metsän eläimet minä annan hänelle, palvelemaan häntä.'),
(1688567,58,24,27,7,'Ja kaikki kansat palvelevat häntä ja hänen poikaansa ja hänen poikansa poikaa, kunnes tulee hänenkin maansa aika ja monet kansat ja suuret kuninkaat tekevät hänet palvelijakseen.'),
(1688568,58,24,27,8,'Ja sitä kansaa ja sitä valtakuntaa, joka ei tahdo palvella häntä, Nebukadnessaria, Baabelin kuningasta, ja joka ei anna kaulaansa Baabelin kuninkaan ikeeseen, sitä kansaa minä rankaisen miekalla, nälällä ja rutolla, sanoo Herra, kunnes minä teen heistä lopun hänen kädellänsä.'),
(1688569,58,24,27,9,'Ja te, älkää kuulko profeettojanne, tietäjiänne, unianne, ennustelijoitanne ja velhojanne, jotka sanovat teille näin: ''Ette te joudu palvelemaan Baabelin kuningasta''.'),
(1688570,58,24,27,10,'Sillä valhetta he ennustavat teille ja toimittavat teidät kauas pois maastanne: minä karkoitan teidät, ja te hukutte.'),
(1688571,58,24,27,11,'Mutta sen kansan, joka taivuttaa kaulansa Baabelin kuninkaan ikeen alle ja palvelee häntä, sen minä annan jäädä omaan maahansa, sanoo Herra; se saa sitä viljellä ja siinä asua."'),
(1688572,58,24,27,12,'Sidkialle, Juudan kuninkaalle, minä puhuin aivan samalla tavalla, sanoen: Taivuttakaa kaulanne Baabelin kuninkaan ikeen alle ja palvelkaa häntä ja hänen kansaansa, niin te saatte elää.'),
(1688573,58,24,27,13,'Miksi pitäisi teidän kuolla, sinun ja sinun kansasi, miekkaan, nälkään ja ruttoon, niinkuin Herra on uhannut sitä kansaa, joka ei tahdo palvella Baabelin kuningasta?'),
(1688574,58,24,27,14,'Ja älkää kuulko niiden profeettain sanoja, jotka sanovat teille näin: "Ette te joudu palvelemaan Baabelin kuningasta"; sillä valhetta he ennustavat teille.'),
(1688575,58,24,27,15,'Sillä minä en ole lähettänyt heitä, sanoo Herra, vaan he ennustavat minun nimessäni valhetta ja saattavat minut karkoittamaan teidät, ja te hukutte, te ja nuo profeetat, jotka teille ennustavat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688576,58,24,27,16,'Ja papeille ja koko tälle kansalle minä puhuin sanoen: Näin sanoo Herra: Älkää kuulko profeettainne sanoja, niiden, jotka ennustavat teille sanoen: "Katso, Herran temppelin astiat tuodaan nyt kohta takaisin Baabelista"; sillä valhetta he ennustavat teille.'),
(1688577,58,24,27,17,'Älkää kuulko heitä. Palvelkaa Baabelin kuningasta, niin te saatte elää. Miksi pitäisi tämän kaupungin tulla raunioiksi?'),
(1688578,58,24,27,18,'Mutta jos he ovat profeettoja ja jos heillä on Herran sana, niin rukoilkoot Herraa Sebaotia, etteivät ne astiat, jotka vielä ovat jäljellä Herran temppelissä ja Juudan kuninkaan linnassa ja Jerusalemissa, joutuisi nekin Baabeliin.'),
(1688579,58,24,27,19,'Sillä näin sanoo Herra Sebaot pylväistä, vaskimerestä, altaiden telineistä ja muista kaluista, jotka vielä ovat jäljellä tässä kaupungissa'),
(1688580,58,24,27,20,'ja joita Nebukadnessar, Baabelin kuningas, ei ottanut mukaansa, kun hän vei Jekonjan, Joojakimin pojan, Juudan kuninkaan, sekä kaikki Juudan ja Jerusalemin ylimykset Jerusalemista pakkosiirtolaisuuteen Baabeliin.'),
(1688581,58,24,27,21,'Sillä näin sanoo Herra Sebaot, Israelin Jumala, astioista, jotka vielä ovat jäljellä Herran temppelissä, Juudan kuninkaan linnassa ja Jerusalemissa:'),
(1688582,58,24,27,22,'"Baabeliin ne viedään, ja sinne ne jäävät siihen päivään asti, jolloin minä katson niiden puoleen, sanoo Herra, ja annan tuoda ja palautan ne tähän paikkaan".'),
(1688583,58,24,28,1,'Sinä vuonna, Sidkian, Juudan kuninkaan, hallituksen alussa, hänen neljäntenä hallitusvuotenaan, viidennessä kuussa, sanoi profeetta Hananja, Assurin poika, joka oli kotoisin Gibeonista, minulle Herran temppelissä pappien ja kaiken kansan silmien edessä näin:'),
(1688584,58,24,28,2,'"Näin sanoo Herra Sebaot, Israelin Jumala: Minä särjen Baabelin kuninkaan ikeen.'),
(1688585,58,24,28,3,'Vielä kaksi vuotta, ja minä palautan tähän paikkaan kaikki Herran temppelin astiat, jotka Nebukadnessar, Baabelin kuningas, otti tästä paikasta ja vei Baabeliin.'),
(1688586,58,24,28,4,'Ja Jekonjan, Joojakimin pojan, Juudan kuninkaan, ja kaikki Juudan pakkosiirtolaiset, jotka menivät Baabeliin, minä palautan tähän paikkaan, sanoo Herra; sillä minä särjen Baabelin kuninkaan ikeen."'),
(1688587,58,24,28,5,'Mutta profeetta Jeremia sanoi profeetta Hananjalle pappien ja kaiken Herran temppelissä seisovan kansan silmien edessä;'),
(1688588,58,24,28,6,'profeetta Jeremia sanoi: "Amen. Niin Herra tehköön. Täyttäköön Herra sinun sanasi, jotka olet ennustanut, ja palauttakoon Herran temppelin astiat ja kaikki pakkosiirtolaiset Baabelista tähän paikkaan.'),
(1688589,58,24,28,7,'Kuule kuitenkin tämä sana, jonka minä puhun sinun kuultesi ja kaiken kansan kuullen.'),
(1688590,58,24,28,8,'Ne profeetat, jotka ovat olleet ennen minua ja ennen sinua muinaisuudesta asti, ovat ennustaneet sotaa, onnettomuutta ja ruttoa monia maita ja suuria valtakuntia vastaan.'),
(1688591,58,24,28,9,'Mutta se profeetta, joka ennustaa rauhaa, tunnetaan siitä, että hänen sanansa toteutuu, profeetaksi, jonka Herra totisesti on lähettänyt."'),
(1688592,58,24,28,10,'Silloin profeetta Hananja otti ikeen profeetta Jeremian kaulasta ja särki sen.'),
(1688593,58,24,28,11,'Ja Hananja sanoi kaiken kansan silmien edessä: "Näin sanoo Herra: Näin minä särjen Nebukadnessarin, Baabelin kuninkaan, ikeen kaikkien kansojen kaulasta, ennenkuin kaksi vuotta on kulunut". Mutta profeetta Jeremia meni pois.'),
(1688594,58,24,28,12,'Ja tämä Herran sana tuli Jeremialle, sen jälkeen kuin profeetta Hananja oli särkenyt ikeen profeetta Jeremian kaulasta:'),
(1688595,58,24,28,13,'"Mene ja sano Hananjalle: Näin sanoo Herra: Sinä olet särkenyt puisen ikeen, mutta tehnyt sen sijaan rautaisen ikeen.'),
(1688596,58,24,28,14,'Sillä näin sanoo Herra Sebaot, Israelin Jumala: rautaisen ikeen olen minä pannut kaikkien näiden kansojen kaulaan, että ne palvelisivat Nebukadnessaria, Baabelin kuningasta; ja niiden on palveltava häntä. Metsän eläimetkin minä olen antanut hänelle."'),
(1688597,58,24,28,15,'Ja profeetta Jeremia sanoi profeetta Hananjalle: "Kuule, Hananja! Ei Herra ole sinua lähettänyt, vaan sinä olet saattanut tämän kansan turvaamaan valheeseen.'),
(1688598,58,24,28,16,'Sentähden, näin sanoo Herra: Katso, minä toimitan sinut pois maan päältä: tänä vuonna sinä kuolet, sillä sinä olet julistanut luopumusta Herrasta."'),
(1688599,58,24,28,17,'Ja profeetta Hananja kuoli sinä vuonna, seitsemännessä kuussa.'),
(1688600,58,24,29,1,'Nämä ovat sen kirjeen sanat, jonka profeetta Jeremia lähetti Jerusalemista pakkosiirtolaisten vanhimmille, mikä heitä vielä oli jäljellä, papeille ja profeetoille sekä kaikelle kansalle, jotka Nebukadnessar oli siirtänyt Jerusalemista pois Baabeliin,'),
(1688601,58,24,29,2,'sen jälkeen kuin kuningas Jekonja ja kuninkaan äiti, hoviherrat, Juudan ja Jerusalemin ruhtinaat sekä sepät ja lukkosepät olivat lähteneet Jerusalemista.'),
(1688602,58,24,29,3,'Hän lähetti kirjeen Elasan, Saafanin pojan, ja Gemarjan, Hilkian pojan, mukana, jotka Sidkia, Juudan kuningas, lähetti Nebukadnessarin, Baabelin kuninkaan, tykö Baabeliin; se kuului näin:'),
(1688603,58,24,29,4,'"Näin sanoo Herra Sebaot, Israelin Jumala, kaikille pakkosiirtolaisille, jotka minä olen siirtänyt Jerusalemista pois Baabeliin:'),
(1688604,58,24,29,5,'Rakentakaa taloja ja asukaa niissä, istuttakaa puutarhoja ja syökää niiden hedelmiä.'),
(1688605,58,24,29,6,'Ottakaa itsellenne vaimoja ja siittäkää poikia ja tyttäriä; ottakaa pojillenne vaimoja ja naittakaa tyttärenne, että he synnyttäisivät poikia ja tyttäriä. Lisääntykää siellä älkääkä vähentykö.'),
(1688606,58,24,29,7,'Ja harrastakaa sen kaupungin menestystä, johon minä olen teidät siirtänyt, ja rukoilkaa sen puolesta Herraa, sillä sen menestys on teidän menestyksenne.'),
(1688607,58,24,29,8,'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Älkää antako profeettainne, joita on keskuudessanne, ja tietäjäinne pettää itseänne, älkääkä totelko unianne, joita te uneksutte.'),
(1688608,58,24,29,9,'Sillä valhetta he ennustavat teille minun nimessäni; minä en ole lähettänyt heitä, sanoo Herra.'),
(1688609,58,24,29,10,'Sillä näin sanoo Herra: Vasta kun ne seitsemänkymmentä Baabelin vuotta ovat täyttyneet, minä katson teidän puoleenne ja panen täytäntöön teitä kohtaan hyvän lupaukseni ja palautan teidät tähän paikkaan.'),
(1688610,58,24,29,11,'Sillä minä tunnen ajatukseni, jotka minulla on teitä kohtaan, sanoo Herra: rauhan eikä turmion ajatukset; minä annan teille tulevaisuuden ja toivon.'),
(1688611,58,24,29,12,'Silloin te huudatte minua avuksenne, tulette ja rukoilette minua, ja minä kuulen teitä.'),
(1688612,58,24,29,13,'Te etsitte minua ja löydätte minut, kun te etsitte minua kaikesta sydämestänne.'),
(1688613,58,24,29,14,'Ja niin minä annan teidän löytää itseni, sanoo Herra, ja minä käännän teidän kohtalonne ja kokoan teidät kaikista kansoista ja kaikista paikoista, joihin olen teidät karkoittanut, sanoo Herra, ja palautan teidät tähän paikkaan, josta minä siirsin teidät pois.'),
(1688614,58,24,29,15,'Jos te sanotte: ''Herra on herättänyt meille profeettoja Baabelissa'','),
(1688615,58,24,29,16,'niin sanoo Herra näin kuninkaasta, joka istuu Daavidin valtaistuimella, ja kaikesta kansasta, joka asuu tässä kaupungissa, teidän veljistänne, joiden ei täytynyt lähteä teidän kanssanne pakkosiirtolaisuuteen:'),
(1688616,58,24,29,17,'Näin sanoo Herra Sebaot: Katso, minä lähetän heidän sekaansa miekan, nälän ja ruton ja teen heidät inhottaviksi kuin viikunat, jotka ovat niin huonoja, ettei niitä voi syödä.'),
(1688617,58,24,29,18,'Ja minä ajan heitä takaa miekalla, nälällä ja rutolla ja teen heidät kauhuksi kaikille valtakunnille maan päällä, kiroukseksi ja kauhistukseksi, ivan vihellykseksi ja häväistykseksi kaikkien kansojen keskuudessa, mihin minä heidät karkoitan,'),
(1688618,58,24,29,19,'sentähden etteivät he kuulleet minun sanojani, sanoo Herra, kun minä lähetin heidän tykönsä palvelijoitani, profeettoja, varhaisesta alkaen. Te ette ole kuulleet, sanoo Herra.'),
(1688619,58,24,29,20,'Mutta kuulkaa te Herran sana, kaikki te pakkosiirtolaiset, jotka minä olen lähettänyt Jerusalemista Baabeliin.'),
(1688620,58,24,29,21,'Näin sanoo Herra Sebaot, Israelin Jumala, Ahabista, Koolajan pojasta, ja Sidkiasta, Maasejan pojasta, jotka ennustavat teille minun nimessäni valhetta: Katso, minä annan heidät Nebukadressarin, Baabelin kuninkaan, käsiin, ja hän lyö heidät kuoliaaksi teidän silmäinne edessä.'),
(1688621,58,24,29,22,'Ja heistä tulee kiroussana kaikille Juudan pakkosiirtolaisille, jotka ovat Baabelissa; sanotaan: ''Herra tehköön sinulle niinkuin Sidkialle ja Ahabille, jotka Baabelin kuningas korvensi tulessa''.'),
(1688622,58,24,29,23,'Sillä he ovat tehneet häpeällisen teon Israelissa, ovat tehneet huorin lähimmäistensä vaimojen kanssa ja puhuneet minun nimessäni valhepuhetta, jota minä en ole käskenyt heidän puhua. Minä olen se, joka sen tiedän ja todistan, sanoo Herra."'),
(1688623,58,24,29,24,'Ja nehelamilaiselle Semajalle puhu, sanoen:'),
(1688624,58,24,29,25,'"Näin sanoo Herra Sebaot, Israelin Jumala: Sentähden että sinä olet lähettänyt omassa nimessäsi tämän kirjeen kaikelle kansalle, joka on Jerusalemissa, ja pappi Sefanjalle, Maasejan pojalle, ja kaikille papeille:'),
(1688625,58,24,29,26,'Herra on asettanut sinut papiksi pappi Joojadan sijaan, että olisi järjestyksen valvojia Herran temppelissä kaikkien hullujen ja ennustajain varalle, ja niin sinä voit panna sellaiset jalkapuuhun ja kaularautaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688626,58,24,29,27,'Miksi et siis ole nuhdellut anatotilaista Jeremiaa, joka ennustaa teille?'),
(1688627,58,24,29,28,'Niinpä hän on saattanut lähettää meille Baabeliin tämän sanan: ''Se kestää vielä kauan. Rakentakaa taloja ja asukaa niissä, istuttakaa puutarhoja ja syökää niiden hedelmiä.''"'),
(1688628,58,24,29,29,'Ja pappi Sefanja luki tämän kirjeen profeetta Jeremian kuullen.'),
(1688629,58,24,29,30,'Silloin tuli Jeremialle tämä Herran sana:'),
(1688630,58,24,29,31,'"Lähetä kaikille pakkosiirtolaisille tämä sana: Näin sanoo Herra nehelamilaisesta Semajasta: Koska Semaja on ennustanut teille, vaikka minä en ole lähettänyt häntä, ja saattanut teidät turvaamaan valheeseen,'),
(1688631,58,24,29,32,'sentähden, näin sanoo Herra: Katso, minä kostan nehelamilaiselle Semajalle ja hänen jälkeläisillensä. Hänellä ei ole oleva ketään, joka saa asua tämän kansan keskuudessa, eikä hän ole näkevä sitä hyvää, jonka minä teen kansalleni, sanoo Herra; sillä hän on julistanut luopumusta Herrasta."'),
(1688632,58,24,30,1,'Sana, joka tuli Herralta Jeremialle ja kuului näin:'),
(1688633,58,24,30,2,'"Näin sanoo Herra, Israelin Jumala: Kirjoita kaikki sanat, jotka minä olen sinulle puhunut, kirjaan.'),
(1688634,58,24,30,3,'Sillä katso, tulee aika, sanoo Herra, jolloin minä käännän kansani Israelin ja Juudan kohtalon, sanoo Herra, ja palautan heidät maahan, jonka olen antanut heidän isillensä, ja he saavat periä sen."'),
(1688635,58,24,30,4,'Ja nämä ovat ne sanat, jotka Herra on puhunut Israelista ja Juudasta.'),
(1688636,58,24,30,5,'Näin sanoo Herra: "Pelon huudon me kuulemme: on hirmu, ei rauha!'),
(1688637,58,24,30,6,'Kysykää ja katsokaa: synnyttääkö miehenpuoli? Miksi näen kaikkien miesten pitelevän käsin lanteitansa synnyttäväisten tavalla, ja miksi ovat kaikki kasvot käyneet valjuiksi?'),
(1688638,58,24,30,7,'Voi! Suuri on se päivä, ei ole sen kaltaista. Se on Jaakobille ahdistuksen aika, mutta hän on pelastuva siitä.'),
(1688639,58,24,30,8,'Ja sinä päivänä, sanoo Herra Sebaot, minä särjen ikeen sinun kaulastasi ja katkaisen sinun siteesi. Eivät tee enää muukalaiset heitä palvelijoikseen,'),
(1688640,58,24,30,9,'vaan he saavat palvella Herraa, Jumalaansa, ja Daavidia, kuningastansa, jonka minä heille herätän.'),
(1688641,58,24,30,10,'Mutta sinä, minun palvelijani Jaakob, älä pelkää, sanoo Herra, älä säiky, Israel. Sillä katso, minä pelastan sinut kaukaisesta maasta, sinun jälkeläisesi heidän vankeutensa maasta. Ja Jaakob on palajava, elävä rauhassa ja turvassa, kenenkään peljättämättä.'),
(1688642,58,24,30,11,'Sillä minä olen sinun kanssasi, sanoo Herra, ja pelastan sinut. Minä teen lopun kaikista kansoista, joiden sekaan minä olen sinut hajottanut; ainoastaan sinusta minä en loppua tee: minä kuritan sinua kohtuudella, mutta rankaisematta minä en sinua jätä.'),
(1688643,58,24,30,12,'Sillä näin sanoo Herra: Paha on sinun vammasi, kipeä on saamasi isku.'),
(1688644,58,24,30,13,'Ei kukaan aja sinun asiaasi; sinun haavaasi ei paranneta, se ei kasva umpeen.'),
(1688645,58,24,30,14,'Kaikki sinun rakastajasi ovat sinut unhottaneet, sinua he eivät kysy. Sillä niinkuin vihollista lyödään, olen minä sinua lyönyt, kovalla kurituksella, koska sinun rikoksesi on suuri, sinun syntisi monilukuiset.'),
(1688646,58,24,30,15,'Miksi valitat vammaasi, kipusi kovuutta? Koska sinun rikoksesi on suuri, sinun syntisi monilukuiset, olen minä sinulle tämän tehnyt.'),
(1688647,58,24,30,16,'Niin myös kaikki sinun syöjäsi syödään, ja kaikki sinun ahdistajasi, kaikki tyynni, vaeltavat vankeuteen; sinun ryöstäjäsi joutuvat ryöstetyiksi, ja kaikki saalistajasi minä annan saaliiksi.'),
(1688648,58,24,30,17,'Sillä minä kasvatan umpeen sinun haavasi ja parannan sinut saamistasi iskuista, sanoo Herra, sinut, Siion, jolla on nimenä ''hyljätty'', ''se, josta ei kukaan välitä''.'),
(1688649,58,24,30,18,'Näin sanoo Herra: Katso, minä käännän Jaakobin majojen kohtalon, minä armahdan hänen asuntojansa; kaupunki rakennetaan kukkulallensa, ja linna on oleva oikealla paikallansa.'),
(1688650,58,24,30,19,'Ja niistä on kaikuva ylistyslaulu ja iloitsevaisten ääni. Minä enennän heidät, eivätkä he vähene; minä saatan heidät kunniaan, eivätkä he halvoiksi jää.'),
(1688651,58,24,30,20,'Silloin hänen poikansa ovat niinkuin muinoin, ja hänen seurakuntansa pysyy vahvana minun edessäni; minä rankaisen kaikki hänen sortajansa.'),
(1688652,58,24,30,21,'Ja hänen valtiaansa nousee hänestä itsestänsä, hänen hallitsijansa lähtee hänen keskeltänsä; ja minä sallin hänen käydä tyköni, niin että hän saattaa minua lähestyä. Sillä kuka panee henkensä alttiiksi minua lähestyäkseen? sanoo Herra.'),
(1688653,58,24,30,22,'Ja niin te olette minun kansani, ja minä olen teidän Jumalanne."'),
(1688654,58,24,30,23,'Katso, Herran myrsky, kiivastus, puhkeaa, pyörremyrsky vyöryy kohti jumalattomien päätä.'),
(1688655,58,24,30,24,'Eikä Herran vihan hehku asetu, ennenkuin hän on toteuttanut ja täyttänyt sydämensä aivoitukset. Aikojen lopulla te tulette sen ymmärtämään.'),
(1688656,58,24,31,1,'"Siihen aikaan, sanoo Herra, minä olen kaikkien Israelin sukukuntien Jumala, ja he ovat minun kansani."'),
(1688657,58,24,31,2,'Näin sanoo Herra: "Kansa, miekalta säästynyt, löysi erämaassa armon; minä menen saattamaan sen, Israelin, rauhaan".'),
(1688658,58,24,31,3,'Kaukaa ilmestyy minulle Herra: "Iankaikkisella rakkaudella minä olen sinua rakastanut, sentähden minä olen vetänyt sinua puoleeni armosta.'),
(1688659,58,24,31,4,'Minä rakennan sinut jälleen, ja sinä tulet rakennetuksi, neitsyt Israel. Sinä kaunistat itsesi jälleen käsirummuillasi ja lähdet iloitsevaisten karkeloon.'),
(1688660,58,24,31,5,'Sinä istutat jälleen viinitarhoja Samarian vuorille; ne, jotka istuttavat, saavat korjata hedelmätkin.'),
(1688661,58,24,31,6,'Sillä päivä on tuleva, jolloin vartijat huutavat Efraimin vuorella: ''Nouskaa, lähtekäämme Siioniin Herran, meidän Jumalamme, tykö''.'),
(1688662,58,24,31,7,'Sillä näin sanoo Herra: Riemuitkaa iloiten Jaakobista, kohottakaa riemuhuuto hänelle, joka on kansojen pää; kuuluttakaa, kiittäkää ja sanokaa: ''Auta, Herra, kansaasi, Israelin jäännöstä''.'),
(1688663,58,24,31,8,'Katso, minä tuon heidät pohjoisesta maasta, kokoan heidät maan perimmäisiltä ääriltä. Heissä on sokeita ja rampoja ynnä raskaita ja synnyttäväisiä: suurena joukkona he palajavat tänne.'),
(1688664,58,24,31,9,'Itkien he tulevat, ja minä johdatan heitä, kun he kulkevat rukoillen. Minä vien heidät vesipuroille, tasaista tietä, jolla he eivät kompastu. Sillä minä olen Israelin isä, ja Efraim on minun esikoiseni.'),
(1688665,58,24,31,10,'Kuulkaa Herran sana, te kansat, ilmoittakaa kaukaisissa merensaarissa ja sanokaa: Hän, joka Israelin hajoitti, on sen kokoava ja varjeleva sitä niinkuin paimen laumaansa.'),
(1688666,58,24,31,11,'Sillä Herra on lunastanut Jaakobin ja vapahtanut hänet häntä väkevämmän kädestä.'),
(1688667,58,24,31,12,'Ja he tulevat ja riemuitsevat Siionin kukkulalla, tulevat virtanaan Herran hyvyyden tykö, jyväin, viinin ja öljyn ääreen, karitsain ja karjan ääreen. Ja heidän sielunsa on oleva niinkuin runsaasti kasteltu puutarha, eivätkä he enää näänny.'),
(1688668,58,24,31,13,'Silloin neitsyt iloitsee karkelossa ja nuorukaiset ja vanhukset yhdessä. Minä muutan heidän surunsa riemuksi, annan heille lohdutuksen ja ilon heidän murheensa jälkeen.'),
(1688669,58,24,31,14,'Ja minä virvoitan pappien sielut lihavuuden ääressä, ja minun kansani ravitaan minun hyvyydelläni, sanoo Herra.'),
(1688670,58,24,31,15,'Näin sanoo Herra: Kuule, Raamasta kuuluu valitus, katkera itku: Raakel itkee lapsiansa, hän ei lohdutuksesta huoli surussaan lastensa tähden, sillä niitä ei enää ole.'),
(1688671,58,24,31,16,'Näin sanoo Herra: Pidätä äänesi itkusta, silmäsi kyyneleistä, sillä sinun työstäsi on tuleva palkka, sanoo Herra, ja he palajavat vihollisen maasta.'),
(1688672,58,24,31,17,'Sinulla on tulevaisuuden toivo, sanoo Herra: sinun lapsesi palajavat omalle maalleen.'),
(1688673,58,24,31,18,'Minä olen kyllä kuullut Efraimin valittavan: ''Sinä olet kurittanut minua, olen saanut kuritusta niinkuin vikuroiva vasikka. Palauta minut, niin minä palajan; sillä sinä olet Herra, minun Jumalani.'),
(1688674,58,24,31,19,'Sillä käännyttyäni minä kadun, ja päästyäni ymmärrykseen minä lyön lanteeseeni. Minä häpeän, tunnen häpeätä, sillä minä kannan nuoruuteni pilkkaa.'''),
(1688675,58,24,31,20,'Eikö Efraim ole minun kallis poikani, minun lempilapseni? Sillä niin usein kuin minä puhunkin häntä vastaan, alati minä häntä muistan. Siksi minun sisimpäni väräjää hänen tähtensä: minun täytyy armahtaa häntä, sanoo Herra.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688676,58,24,31,21,'Pystytä itsellesi kivimerkkejä, aseta itsellesi tienviittoja, paina mieleesi tie, polku, jota olet kulkenut. Palaja, neitsyt Israel, palaja näihin kaupunkeihisi.'),
(1688677,58,24,31,22,'Kuinka kauan sinä mutkistelet sinne ja tänne, sinä luopiotytär? Sillä Herra luo maahan uutta: nainen miestä piirittää.'),
(1688678,58,24,31,23,'Näin sanoo Herra Sebaot, Israelin Jumala: Vielä kerran sanotaan Juudan maassa ja sen kaupungeissa, kun minä käännän heidän kohtalonsa, tämä sana: ''Herra siunatkoon sinua, sinä vanhurskauden asuinsija, sinä pyhä vuori''.'),
(1688679,58,24,31,24,'Ja Juuda kaikkine kaupunkeineen asuu siellä yhdessä, peltomiehet ja ne, jotka vaeltavat laumoineen.'),
(1688680,58,24,31,25,'Sillä minä virvoitan väsyneen sielun, ja jokaisen nääntyvän sielun minä ravitsen."'),
(1688681,58,24,31,26,'Siihen minä heräsin ja katselin, ja uneni oli minusta suloinen.'),
(1688682,58,24,31,27,'"Katso, päivät tulevat, sanoo Herra, jolloin minä kylvän Israelin maahan ja Juudan maahan ihmisen siementä ja karjan siementä.'),
(1688683,58,24,31,28,'Ja niinkuin minä olen valvonut repiäkseni ja kukistaakseni heitä, hajottaakseni ja hävittääkseni, tuottaakseni onnettomuutta, niin minä olen valvova rakentaakseni ja istuttaakseni heitä, sanoo Herra.'),
(1688684,58,24,31,29,'Niinä päivinä ei enää sanota: ''Isät söivät raakoja rypäleitä, lasten hampaat heltyivät'';'),
(1688685,58,24,31,30,'vaan jokaisen on kuoltava oman syntivelkansa tähden. Jokaiselta ihmiseltä, joka syö raakoja rypäleitä, heltyvät hänen omat hampaansa.'),
(1688686,58,24,31,31,'Katso, päivät tulevat, sanoo Herra, jolloin minä teen Israelin heimon ja Juudan heimon kanssa uuden liiton;'),
(1688687,58,24,31,32,'en sellaista liittoa kuin se, jonka minä tein heidän isäinsä kanssa silloin, kun minä tartuin heidän käteensä ja vein heidät pois Egyptin maasta, ja jonka liittoni he ovat rikkoneet, vaikka minä olin ottanut heidät omikseni, sanoo Herra.'),
(1688688,58,24,31,33,'Vaan tämä on se liitto, jonka minä teen Israelin heimon kanssa niiden päivien tultua, sanoo Herra: Minä panen lakini heidän sisimpäänsä ja kirjoitan sen heidän sydämiinsä; ja niin minä olen heidän Jumalansa, ja he ovat minun kansani.'),
(1688689,58,24,31,34,'Silloin ei enää toinen opeta toistansa eikä veli veljeänsä sanoen: ''Tuntekaa Herra''. Sillä he kaikki tuntevat minut, pienimmästä suurimpaan, sanoo Herra; sillä minä annan anteeksi heidän rikoksensa enkä enää muista heidän syntejänsä.'),
(1688690,58,24,31,35,'Näin sanoo Herra, joka on pannut auringon valaisemaan päivää, kuun ja tähdet lakiensa mukaan valaisemaan yötä, hän, joka liikuttaa meren, niin että sen aallot pauhaavat - Herra Sebaot on hänen nimensä:'),
(1688691,58,24,31,36,'Jos väistyvät nämä lait minun kasvojeni edestä, silloin myös lakkaavat Israelin jälkeläiset olemasta kansa minun kasvojeni edessä ainiaan.'),
(1688692,58,24,31,37,'Näin sanoo Herra: Jos voidaan mitata taivaat ylhäällä ja tutkia maan perustukset alhaalla, silloin vasta minä hylkään Israelin jälkeläiset kaikki, kaiken sen tähden, mitä he ovat tehneet, sanoo Herra.'),
(1688693,58,24,31,38,'Katso, päivät tulevat, sanoo Herra, jolloin Herran kaupunki rakennetaan jälleen Hananelin-tornista Kulmaporttiin asti.'),
(1688694,58,24,31,39,'Ja edelleen mittanuora kulkee suoraan Gaarebin kukkulalle ja kääntyy sitten Gooaan.'),
(1688695,58,24,31,40,'Ja koko laakso, ruumiineen ja tuhkineen, ja kaikki keto Kidronin puroon asti, Hevosportin kulmaan saakka itään päin, on oleva Herralle pyhitetty. Ei sitä enää ikinä hävitetä eikä kukisteta."'),
(1688696,58,24,32,1,'Sana, joka tuli Jeremialle Herralta Sidkian, Juudan kuninkaan, kymmenentenä vuotena, se on Nebukadressarin kahdeksantenatoista vuotena.'),
(1688697,58,24,32,2,'Silloin Baabelin kuninkaan sotajoukko piiritti Jerusalemia, ja profeetta Jeremia oli suljettuna vankilan pihaan, joka on Juudan kuninkaan linnassa.'),
(1688698,58,24,32,3,'Sinne oli Sidkia, Juudan kuningas, hänet sulkenut sanoen: "Miksi sinä ennustat näin: Näin sanoo Herra: Katso, minä annan tämän kaupungin Baabelin kuninkaan käsiin, ja hän valloittaa sen?'),
(1688699,58,24,32,4,'Ja Sidkia, Juudan kuningas, ei pääse kaldealaisten käsistä, vaan hänet annetaan Baabelin kuninkaan käsiin, ja hänen täytyy puhua hänen kanssaan suusta suuhun ja nähdä hänet silmästä silmään.'),
(1688700,58,24,32,5,'Ja hän kuljettaa Sidkian Baabeliin, ja sinne hän jää, kunnes minä katson hänen puoleensa, sanoo Herra. Kun te taistelette kaldealaisia vastaan, ei teillä ole menestystä."'),
(1688701,58,24,32,6,'Ja Jeremia sanoi: "Minulle tuli tämä Herran sana:'),
(1688702,58,24,32,7,'Katso, Hanamel, setäsi Sallumin poika, tulee sinun luoksesi ja sanoo: ''Osta minun peltoni, joka on Anatotissa, sillä sinulla on lunastusoikeus, niin että saat ostaa sen''."'),
(1688703,58,24,32,8,'Ja Hanamel, setäni poika, tuli Herran sanan mukaan minun luokseni vankilan pihaan ja sanoi minulle: "Osta minun peltoni, joka on Anatotissa, Benjaminin maassa, sillä sinulla on perintöoikeus ja sinulla on lunastusoikeus: osta se itsellesi". Silloin minä ymmärsin, että se oli Herran sana.'),
(1688704,58,24,32,9,'Ja minä ostin Hanamelilta, setäni pojalta, pellon, joka on Anatotissa, ja punnitsin hänelle rahat, seitsemäntoista sekeliä hopeata,'),
(1688705,58,24,32,10,'kirjoitin kauppakirjan ja sinetöin sen, otin todistajat ja punnitsin rahat vaa''alla.'),
(1688706,58,24,32,11,'Sitten minä otin sinetöidyn kauppakirjan, sopimuksen ja määräykset sekä avoimen kirjan,'),
(1688707,58,24,32,12,'ja annoin kauppakirjan Baarukille, Neerian, Mahsejan pojan, pojalle, serkkuni Hanamelin nähden ja todistajain nähden, jotka olivat kirjoittaneet kauppakirjan alle, ja kaikkien juutalaisten nähden, jotka istuivat vankilan pihassa,'),
(1688708,58,24,32,13,'ja minä käskin Baarukia heidän nähtensä sanoen:'),
(1688709,58,24,32,14,'"Näin sanoo Herra Sebaot, Israelin Jumala: Ota nämä kirjat, tämä kauppakirja, sekä sinetöity että tämä avoin kirja, ja pane ne saviastiaan, että ne säilyisivät kauan aikaa.'),
(1688710,58,24,32,15,'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Vielä kerran ostetaan tässä maassa taloja ja peltoja ja viinitarhoja."'),
(1688711,58,24,32,16,'Ja annettuani kauppakirjan Baarukille, Neerian pojalle, minä rukoilin Herraa sanoen:'),
(1688712,58,24,32,17,'"Oi Herra, Herra! Katso, sinä olet tehnyt taivaan ja maan suurella voimallasi ja ojennetulla käsivarrellasi: ei mikään ole sinulle mahdotonta;'),
(1688713,58,24,32,18,'sinä, joka teet laupeuden tuhansille, mutta kostat isäin pahat teot heidän jälkeensä heidän lastensa helmaan; sinä suuri, voimallinen Jumala, jonka nimi on Herra Sebaot,'),
(1688714,58,24,32,19,'suuri neuvossa ja väkevä teossa, sinä, jonka silmät ovat avoimet tarkkaamaan kaikkia ihmislasten teitä, antaaksesi itsekullekin hänen vaelluksensa ja hänen töittensä hedelmän mukaan;'),
(1688715,58,24,32,20,'sinä, joka teit tunnustekoja ja ihmeitä Egyptin maassa ja olet tehnyt niitä hamaan tähän päivään asti sekä Israelissa että muitten ihmisten seassa, ja joka olet tehnyt itsellesi nimen, senkaltaisen kuin se tänäkin päivänä on.'),
(1688716,58,24,32,21,'Sinä veit kansasi Israelin pois Egyptin maasta tunnusteoilla ja ihmeillä, väkevällä kädellä ja ojennetulla käsivarrella, suurella peljätyksellä,'),
(1688717,58,24,32,22,'ja annoit heille tämän maan, jonka sinä heidän isillensä vannotulla valalla olit luvannut antaa heille, maan, joka vuotaa maitoa ja mettä.'),
(1688718,58,24,32,23,'Mutta kun he olivat tulleet ja ottaneet sen omaksensa, eivät he kuulleet sinun ääntäsi eivätkä vaeltaneet sinun lakisi mukaan; he eivät tehneet mitään siitä, mitä sinä olit käskenyt heidän tehdä. Silloin sinä annoit kaiken tämän onnettomuuden kohdata heitä.'),
(1688719,58,24,32,24,'Katso, piiritysvallit ovat edenneet aivan kaupunkiin asti, niin että se valloitetaan, ja kaupunki joutuu miekan, nälän ja ruton pakosta kaldealaisten valtaan, jotka sotivat sitä vastaan. Mitä sinä olet puhunut, on tapahtunut, ja katso, sinä näet sen.'),
(1688720,58,24,32,25,'Mutta kuitenkin sinä, Herra, Herra, sanoit minulle: ''Osta rahalla itsellesi pelto ja ota todistajat'', vaikka kaupunki joutuu kaldealaisten käsiin."'),
(1688721,58,24,32,26,'Ja Jeremialle tuli tämä Herran sana:'),
(1688722,58,24,32,27,'"Katso, minä olen Herra, kaiken lihan Jumala; onko minulle mitään mahdotonta?'),
(1688723,58,24,32,28,'Sentähden, näin sanoo Herra: Katso, minä annan tämän kaupungin kaldealaisten käsiin ja Nebukadressarin, Baabelin kuninkaan, käsiin, ja hän valloittaa sen.'),
(1688724,58,24,32,29,'Ja kaldealaiset, jotka sotivat tätä kaupunkia vastaan, tulevat ja sytyttävät tämän kaupungin tuleen ja polttavat sen niine taloineen, joiden katoilla on poltettu uhreja Baalille ja vuodatettu juomauhreja vieraille jumalille, minulle mielikarvaudeksi.'),
(1688725,58,24,32,30,'Sillä Israelin ja Juudan miehet ovat hamasta nuoruudestaan tehneet vain sitä, mikä on pahaa minun silmissäni, sillä israelilaiset ovat tuottaneet minulle ainoastaan mielikarvautta kättensä teoilla, sanoo Herra.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688726,58,24,32,31,'Sillä tämä kaupunki on ollut minulle vihaksi ja kiivastukseksi hamasta siitä päivästä, jona he sen rakensivat, aina tähän päivään asti; ja niin minä heitän sen pois kasvojeni edestä'),
(1688727,58,24,32,32,'kaiken sen pahan tähden, minkä israelilaiset ja Juudan miehet ovat tehneet minulle mielikarvaudeksi - he, heidän kuninkaansa, ruhtinaansa, pappinsa ja profeettansa sekä Juudan miehet ja Jerusalemin asukkaat.'),
(1688728,58,24,32,33,'He ovat kääntäneet minulle selkänsä eivätkä kasvojansa; ja vaikka minä olen opettanut heitä varhaisesta alkaen, he eivät ole kuulleet eivätkä ottaneet varteen kuritusta.'),
(1688729,58,24,32,34,'He ovat asettaneet iljetyksensä temppeliin, joka on otettu minun nimiini, ja saastuttaneet sen.'),
(1688730,58,24,32,35,'Ja he ovat rakentaneet Baalille uhrikukkulat, jotka ovat Ben-Hinnomin laaksossa, polttaakseen poikiansa ja tyttäriänsä uhrina Molokille, mitä minä en ole käskenyt ja mikä ei ole minun mieleeni tullut. Tällaisia kauhistuksia he tekivät ja saivat Juudan syntiä tekemään.'),
(1688731,58,24,32,36,'Mutta nyt sanoo Herra, Israelin Jumala, näin tästä kaupungista, jonka te sanotte joutuvan Baabelin kuninkaan käsiin miekan, nälän ja ruton pakosta:'),
(1688732,58,24,32,37,'Katso, minä kokoan heidät jälleen kaikista maista, joihin minä heidät vihassani, kiivastuksessani ja suuressa suuttumuksessani karkoitan, ja palautan heidät tähän paikkaan ja annan heidän asua turvassa.'),
(1688733,58,24,32,38,'Silloin he ovat minun kansani, ja minä olen heidän Jumalansa.'),
(1688734,58,24,32,39,'Ja minä annan heille yhden sydämen ja yhden tien, niin että he pelkäävät minua kaiken elinaikansa, ja niin heidän käy hyvin ja heidän lastensa heidän jälkeensä.'),
(1688735,58,24,32,40,'Ja minä teen heidän kanssansa iankaikkisen liiton, niin etten käänny heistä pois, vaan teen heille hyvää; ja minä annan pelkoni heidän sydämiinsä, niin etteivät he minusta luovu.'),
(1688736,58,24,32,41,'Ja minä iloitsen heistä, siitä että teen heille hyvää; minä istutan heidät tähän maahan uskollisesti, kaikesta sydämestäni ja kaikesta sielustani.'),
(1688737,58,24,32,42,'Sillä näin sanoo Herra: Niinkuin minä olen tuottanut tälle kansalle kaiken tämän suuren onnettomuuden, niin minä myös tuotan heille kaiken sen hyvän, minkä minä heille lupaan.'),
(1688738,58,24,32,43,'Vielä ostetaan peltoja tässä maassa, josta te sanotte: ''Se on oleva autio, vailla ihmisiä ja eläimiä, kaldealaisten käsiin annettu''.'),
(1688739,58,24,32,44,'Peltoja ostetaan rahalla, kauppakirjoja kirjoitetaan ja sinetöidään ja todistajia otetaan Benjaminin maassa, Jerusalemin ympäristössä ja Juudan kaupungeissa, Vuoriston, Alankomaan ja Etelämaan kaupungeissa, sillä minä käännän heidän kohtalonsa, sanoo Herra."'),
(1688740,58,24,33,1,'Herran sana tuli Jeremialle toistamiseen, kun hän vielä oli suljettuna vankilan pihaan; se kuului näin:'),
(1688741,58,24,33,2,'"Näin sanoo Herra, joka sen myös tekee, Herra, joka valmistaa sen ja vahvistaa sen - Herra on hänen nimensä:'),
(1688742,58,24,33,3,'Huuda minua avuksesi, niin minä vastaan sinulle ja ilmoitan sinulle suuria ja salattuja asioita, joita sinä et tiedä.'),
(1688743,58,24,33,4,'Sillä näin sanoo Herra, Israelin Jumala, tämän kaupungin taloista ja Juudan kuningasten linnoista, jotka sortuvat piiritysvallien ja miekan edessä,'),
(1688744,58,24,33,5,'ja niistä, jotka ovat tulleet taistelemaan kaldealaisia vastaan, ja täyttämään talot ihmisten ruumiilla, jotka minä surmaan vihassani ja kiivastuksessani ja joiden kaiken pahuuden tähden minä olen kätkenyt kasvoni tältä kaupungilta:'),
(1688745,58,24,33,6,'Katso, minä kasvatan umpeen ja lääkitsen sen haavat, ja minä parannan heidät ja avaan heille rauhan ja totuuden runsauden.'),
(1688746,58,24,33,7,'Minä käännän Juudan kohtalon ja Israelin kohtalon ja rakennan heidät muinaiselleen.'),
(1688747,58,24,33,8,'Ja minä puhdistan heidät kaikista heidän pahoista teoistansa, joilla he ovat rikkoneet minua vastaan, ja minä annan anteeksi kaikki heidän pahat tekonsa, joilla he ovat rikkoneet minua vastaan ja minusta luopuneet.'),
(1688748,58,24,33,9,'Ja tämä kaupunki on oleva minulle kunniaksi ja iloksi, ylistykseksi ja kirkkaudeksi kaikkien maan kansojen edessä, jotka kuulevat kaiken sen hyvän, minkä minä sille teen; he peljästyvät ja vapisevat kaikkea sitä hyvää ja kaikkea sitä onnea, jonka minä sille annan.'),
(1688749,58,24,33,10,'Näin sanoo Herra: Vielä kerran kuullaan tässä paikassa, josta te sanotte: ''Se on oleva rauniona, vailla ihmisiä ja eläimiä''. Juudan kaupungeissa ja Jerusalemin autioilla kaduilla, joilla ei ihmistä, ei asukasta, ei eläintä ole,'),
(1688750,58,24,33,11,'riemun ja ilon huuto, huuto yljälle ja huuto morsiamelle, niiden huuto, jotka sanovat: ''Kiittäkää Herraa Sebaotia, sillä Herra on hyvä, sillä hänen armonsa pysyy iankaikkisesti'', ja niiden, jotka tuovat Herran huoneeseen kiitosuhreja. Sillä minä käännän maan kohtalon muinaiselleen, sanoo Herra.'),
(1688751,58,24,33,12,'Näin sanoo Herra Sebaot: Vielä kerran on tässä paikassa, joka on rauniona, vailla ihmisiä ja eläimiä, ja kaikilla sen kaupungeilla oleva laitumia, joilla paimenet lepuuttavat lampaitansa.'),
(1688752,58,24,33,13,'Vuoriston kaupungeissa, Alankomaan kaupungeissa ja Etelämaan kaupungeissa, Benjaminin maassa, Jerusalemin ympäristössä ja Juudan kaupungeissa on vielä kerran lampaita kulkeva laskijan kätten ohi, sanoo Herra.'),
(1688753,58,24,33,14,'Katso, päivät tulevat, sanoo Herra, jolloin minä täytän sen hyvän lupauksen, jonka minä olen lausunut Israelin heimosta ja Juudan heimosta.'),
(1688754,58,24,33,15,'Niinä päivinä ja siihen aikaan minä kasvatan Daavidille vanhurskauden vesan, ja hän on tekevä oikeuden ja vanhurskauden maassa.'),
(1688755,58,24,33,16,'Niinä päivinä Juuda pelastetaan, ja Jerusalem asuu turvassa, ja tämä on se nimi, jolla sitä kutsutaan: ''Herra, meidän vanhurskautemme''.'),
(1688756,58,24,33,17,'Sillä näin sanoo Herra: Aina on mies Daavidin suvusta istuva Israelin heimon valtaistuimella.'),
(1688757,58,24,33,18,'Ja aina on mies leeviläisten pappien suvusta oleva minun edessäni uhraamassa polttouhria ja sytyttämässä ruokauhria ja toimittamassa teurasuhria joka päivä."'),
(1688758,58,24,33,19,'Ja Jeremialle tuli tämä Herran sana:'),
(1688759,58,24,33,20,'"Näin sanoo Herra: Jos saatte rikotuksi minun liittoni päivän kanssa ja minun liittoni yön kanssa, niin että päivä ja yö eivät enää tule ajallansa,'),
(1688760,58,24,33,21,'niin rikkoutuu myös minun liittoni palvelijani Daavidin kanssa, niin ettei hänellä enää ole poikaa, joka istuu kuninkaana hänen valtaistuimellansa, ja minun liittoni leeviläisten pappien, minun palvelijaini, kanssa.'),
(1688761,58,24,33,22,'Niinkuin taivaan joukkoa ei voida lukea eikä meren hiekkaa mitata, niin monilukuisiksi minä teen palvelijani Daavidin jälkeläiset ja leeviläiset, jotka minua palvelevat."'),
(1688762,58,24,33,23,'Ja Jeremialle tuli tämä Herran sana:'),
(1688763,58,24,33,24,'"Etkö ole huomannut, mitä tämä kansa puhuu sanoen: ''Ne kaksi sukukuntaa, jotka Herra valitsi, hän on hyljännyt''? Ja he halveksivat minun kansaani, niinkuin se ei enää olisikaan kansa heidän silmissänsä.'),
(1688764,58,24,33,25,'Näin sanoo Herra: Jos minun liittoni päivän ja yön kanssa on olematon, jos en ole säätänyt taivaan ja maan lakeja,'),
(1688765,58,24,33,26,'niin minä myös hylkään Jaakobin ja palvelijani Daavidin jälkeläiset, niin etten ota hänen jälkeläisistänsä hallitsijoita Aabrahamin, Iisakin ja Jaakobin jälkeläisille. Sillä minä käännän heidän kohtalonsa ja armahdan heitä."'),
(1688766,58,24,34,1,'Sana, joka tuli Jeremialle Herralta, kun Nebukadnessar, Baabelin kuningas, ja koko hänen sotajoukkonsa ja kaikki hänen valtansa alaisen maan valtakunnat ja kaikki kansat sotivat Jerusalemia ja kaikkia sen alaisia kaupunkeja vastaan; se kuului näin:'),
(1688767,58,24,34,2,'"Näin sanoo Herra, Israelin Jumala: Mene ja sano Sidkialle, Juudan kuninkaalle, sano hänelle: Näin sanoo Herra: Katso, minä annan tämän kaupungin Baabelin kuninkaan käsiin, ja hän polttaa sen tulella.'),
(1688768,58,24,34,3,'Ja sinä et pääse hänen käsistään, vaan sinut otetaan kiinni ja annetaan hänen käsiinsä, ja sinun täytyy nähdä Baabelin kuningas silmästä silmään, ja hän puhuu sinun kanssasi suusta suuhun, ja sinä joudut Baabeliin.'),
(1688769,58,24,34,4,'Mutta kuule Herran sana, Sidkia, Juudan kuningas: Näin sanoo Herra sinusta: Sinä et ole kuoleva miekkaan.'),
(1688770,58,24,34,5,'Sinä saat kuolla rauhassa; ja niinkuin sinun isillesi, aikaisemmille kuninkaille, jotka olivat ennen sinua, niin poltetaan sinun kunniaksesi kuolinsuitsutus ja sinulle pidetään valittajaiset ja huudetaan: ''Voi herraamme!'' Sillä minä olen sen sanonut, sanoo Herra."'),
(1688771,58,24,34,6,'Ja profeetta Jeremia puhui Sidkialle, Juudan kuninkaalle, kaikki nämä sanat Jerusalemissa,'),
(1688772,58,24,34,7,'kun Baabelin kuninkaan sotajoukko taisteli Jerusalemia vastaan ja kaikkia vielä jäljellä olevia Juudan kaupunkeja vastaan, Laakista ja Asekaa vastaan, sillä nämä olivat jääneet jäljelle Juudan kaupungeista, varustetuista kaupungeista.'),
(1688773,58,24,34,8,'Sana, joka tuli Jeremialle Herralta, sen jälkeen kuin kuningas Sidkia oli tehnyt liiton kaiken kansan kanssa, joka oli Jerusalemissa, ja heille julistanut vapautuksen,'),
(1688774,58,24,34,9,'että jokaisen tuli päästää vapaaksi orjansa ja orjattarensa, hebrealainen mies ja hebrealainen nainen, niin etteivät heitä orjinansa pitäisi, ei kukaan juutalaista veljeänsä.'),
(1688775,58,24,34,10,'Ja sen kuulivat kaikki päämiehet ja kaikki kansa, jotka olivat menneet tähän liittoon, että jokaisen tuli päästää vapaaksi orjansa ja orjattarensa eikä enää pitää heitä orjinansa; ja he tottelivat ja päästivät heidät.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688776,58,24,34,11,'Mutta jälkeenpäin he peräytyivät liitosta ja ottivat takaisin ne orjat ja orjattaret, jotka he olivat päästäneet vapaiksi, ja pakottivat heidät orjikseen ja orjattarikseen.'),
(1688777,58,24,34,12,'Silloin tuli Jeremialle Herralta tämä Herran sana:'),
(1688778,58,24,34,13,'"Näin sanoo Herra, Israelin Jumala: Minä tein teidän isäinne kanssa liiton silloin, kun minä vein heidät pois Egyptin maasta, orjuuden pesästä, sanoen:'),
(1688779,58,24,34,14,'Seitsemän vuoden kuluttua päästäkää veljenne, hebrealainen: joka on myynyt itsensä sinulle ja palvellut sinua kuusi vuotta, se päästä luotasi vapaaksi. Mutta teidän isänne eivät kuulleet minua, eivät korvaansa kallistaneet.'),
(1688780,58,24,34,15,'Vaan nyt te olette kääntyneet ja tehneet teon, joka on oikea minun silmissäni, julistaessanne vapautuksen kukin lähimmäisellensä, ja olette tehneet liiton minun kasvojeni edessä temppelissä, joka on otettu minun nimiini.'),
(1688781,58,24,34,16,'Mutta sitten te olette jälleen kääntyneet pois ja häväisseet minun nimeni: olette ottaneet takaisin jokainen orjansa ja orjattarensa, jotka olitte päästäneet vapaiksi omiin valtoihinsa, ja olette pakottaneet heidät olemaan orjinanne ja orjattarinanne.'),
(1688782,58,24,34,17,'Sentähden näin sanoo Herra: Te ette kuulleet minua ettekä julistaneetkaan vapautusta kukin veljellensä ja lähimmäisellensä; katso, minä julistan teille vapautuksen, sanoo Herra: menon miekkaan, ruttoon ja nälkään. Ja minä teen teidät kauhistukseksi kaikille valtakunnille maan päällä.'),
(1688783,58,24,34,18,'Ja minä annan ne miehet, jotka ovat rikkoneet minun liittoni, jotka eivät ole pitäneet sen liiton sanoja, jonka he tekivät minun edessäni halkaisten kahtia uhrivasikan ja käyden sen puolikkaiden välitse, nämä miehet -'),
(1688784,58,24,34,19,'Juudan ruhtinaat ja Jerusalemin ruhtinaat, hoviherrat ja papit sekä kaiken maan kansan, jotka kävivät vasikan puolikkaiden välitse -'),
(1688785,58,24,34,20,'ne minä annan heidän vihollistensa käsiin, niiden käsiin, jotka etsivät heidän henkeänsä; ja heidän ruumiinsa joutuvat taivaan lintujen ja maan eläinten ruuaksi.'),
(1688786,58,24,34,21,'Ja Sidkian, Juudan kuninkaan, ja hänen ruhtinaansa minä annan heidän vihollistensa käsiin, niiden käsiin, jotka etsivät heidän henkeänsä, Baabelin kuninkaan sotajoukon käsiin, joka on lähtenyt pois teidän kimpustanne.'),
(1688787,58,24,34,22,'Katso, minä käsken heitä, sanoo Herra, ja palautan heidät tämän kaupungin kimppuun, ja he sotivat sitä vastaan, valloittavat sen ja polttavat sen tulella; ja Juudan kaupungit minä teen autioiksi, asujattomiksi."'),
(1688788,58,24,35,1,'Sana, joka tuli Jeremialle Herralta Juudan kuninkaan Joojakimin, Joosian pojan, päivinä; se kuului:'),
(1688789,58,24,35,2,'"Mene reekabilaisten tykö ja puhuttele heitä ja vie heidät Herran temppeliin, yhteen sen kammioista, ja anna heille viiniä juoda".'),
(1688790,58,24,35,3,'Ja minä otin Jaasanjan, joka oli Jeremian, Habassinjan pojan, poika, sekä hänen veljensä ja kaikki hänen poikansa ja kaikki reekabilaiset'),
(1688791,58,24,35,4,'ja vein heidät Herran temppeliin, Jumalan miehen Haananin, Jigdaljan pojan, poikien kammioon, joka on päämiesten kammion vieressä, ovenvartija Maasejan, Sallumin pojan, kammion yläpuolella.'),
(1688792,58,24,35,5,'Ja minä asetin reekabilaisten eteen täysiä viiniruukkuja ynnä maljoja ja sanoin heille: "Juokaa viiniä".'),
(1688793,58,24,35,6,'Mutta he vastasivat: "Me emme juo viiniä; sillä meidän isämme Joonadab, Reekabin poika, on antanut meille tämän käskyn: Älkää, te ja teidän lapsenne, ikinä viiniä juoko;'),
(1688794,58,24,35,7,'älkää rakentako taloja älkääkä kylväkö siementä; älkää istuttako viinitarhoja, älköönkä niitä teillä olko, vaan asukaa teltoissa kaikkina elämänne päivinä, että kauan eläisitte siinä maassa, jossa te olette muukalaisina.'),
(1688795,58,24,35,8,'Ja me olemme kuuliaiset isällemme Joonadabille, Reekabin pojalle, kaikessa, mitä hän on käskenyt meidän tehdä, niin että emme koskaan juo viiniä elämämme päivinä, emme me eivätkä vaimomme, eivät poikamme eivätkä tyttäremme,'),
(1688796,58,24,35,9,'emmekä rakenna taloja asuaksemme, eikä meillä ole viinitarhoja, ei peltoa eikä kylvöä.'),
(1688797,58,24,35,10,'Vaan me asumme teltoissa ja olemme kuuliaiset ja teemme kaiken, mitä isämme Joonadab on käskenyt meidän tehdä.'),
(1688798,58,24,35,11,'Mutta kun Nebukadressar, Baabelin kuningas, hyökkäsi maahan, niin me sanoimme: ''Tulkaa, menkäämme Jerusalemiin kaldealaisten sotajoukkoa ja aramilaisten sotajoukkoa pakoon'', ja me asetuimme Jerusalemiin."'),
(1688799,58,24,35,12,'Ja Jeremialle tuli tämä Herran sana:'),
(1688800,58,24,35,13,'"Näin sanoo Herra Sebaot, Israelin Jumala: Mene ja sano Juudan miehille ja Jerusalemin asukkaille: Ettekö ota kuritusta varteen ja kuule minun sanojani? sanoo Herra.'),
(1688801,58,24,35,14,'Joonadabin, Reekabin pojan, sanat, joilla hän kielsi poikiansa juomasta viiniä, pidetään voimassa, ja niin he eivät ole juoneet tähän päivään asti, sillä he ovat kuuliaiset isänsä käskylle. Mutta minä olen puhunut teille varhaisesta alkaen, ja te ette ole kuulleet minua.'),
(1688802,58,24,35,15,'Ja minä olen lähettänyt teidän tykönne kaikki palvelijani, profeetat, varhaisesta alkaen, sanoen: Kääntykää kukin pahalta tieltänne ja parantakaa tekonne, älkää seuratko muita jumalia älkääkä niitä palvelko, niin te saatte asua siinä maassa, jonka minä olen antanut teille ja teidän isillenne; mutta te ette ole kallistaneet korvaanne, ette ole kuulleet minua.'),
(1688803,58,24,35,16,'Joonadabin, Reekabin pojan, jälkeläiset ovat siis pitäneet voimassa isänsä käskyn, jonka hän heille antoi, mutta tämä kansa ei ole kuullut minua.'),
(1688804,58,24,35,17,'Sentähden, näin sanoo Herra, Jumala Sebaot, Israelin Jumala: Katso, minä annan tulla Juudalle ja kaikille Jerusalemin asukkaille kaiken sen onnettomuuden, jolla minä olen heitä uhannut, koska he eivät kuulleet, kun minä heille puhuin, eivät vastanneet, kun minä heitä kutsuin."'),
(1688805,58,24,35,18,'Ja reekabilaisille sanoi Jeremia: "Näin sanoo Herra Sebaot, Israelin Jumala: Koska te olette olleet kuuliaiset isänne Joonadabin käskylle ja noudattaneet kaikkia hänen käskyjänsä ja tehneet kaiken, mitä hän käski teidän tehdä,'),
(1688806,58,24,35,19,'sentähden, näin sanoo Herra Sebaot, Israelin Jumala: Joonadabin, Reekabin pojan, suvussa on aina oleva mies, joka seisoo minun kasvojeni edessä".'),
(1688807,58,24,36,1,'Juudan kuninkaan Joojakimin, Joosian pojan, neljäntenä hallitusvuotena tuli tämä sana Jeremialle Herralta; se kuului:'),
(1688808,58,24,36,2,'"Ota kirjakäärö ja kirjoita siihen kaikki ne sanat, jotka minä olen puhunut sinulle Israelista ja Juudasta ja kaikista pakanakansoista siitä päivästä asti, jolloin minä aloin sinulle puhua, Joosian päivistä, aina tähän päivään saakka.'),
(1688809,58,24,36,3,'Ehkäpä Juudan heimo, kuultuaan kaiken sen onnettomuuden, jonka minä aion heille tuottaa, kääntyy, kukin pahalta tieltään, ja niin minä annan anteeksi heidän pahat tekonsa ja syntinsä."'),
(1688810,58,24,36,4,'Silloin Jeremia kutsui Baarukin, Neerian pojan, ja Baaruk kirjoitti kirjakääröön Jeremian suusta kaikki ne sanat, jotka Herra oli hänelle puhunut.'),
(1688811,58,24,36,5,'Sitten Jeremia käski Baarukia sanoen: "Minä olen estetty, en voi mennä Herran temppeliin.'),
(1688812,58,24,36,6,'Mene sinä ja lue kirjakääröstä, jonka olet kirjoittanut suoraan minun suustani, Herran sanat kansan kuullen Herran temppelissä paastopäivänä; myöskin koko Juudan kuullen, kaikkien, jotka tulevat kaupungeistansa, on sinun ne luettava.'),
(1688813,58,24,36,7,'Ehkäpä he rukouksessa lankeavat alas Herran eteen ja kääntyvät kukin pahalta tieltään. Sillä suuri on viha ja kiivastus, jolla Herra on uhannut tätä kansaa."'),
(1688814,58,24,36,8,'Ja Baaruk, Neerian poika, teki kaikki, niinkuin profeetta Jeremia oli käskenyt hänen tehdä, ja luki kirjasta Herran sanat Herran temppelissä.'),
(1688815,58,24,36,9,'Mutta Juudan kuninkaan Joojakimin, Joosian pojan, viidentenä hallitusvuotena, yhdeksännessä kuussa, oli kaikki Jerusalemin kansa ja kaikki se kansa, joka oli tullut Juudan kaupungeista Jerusalemiin, kutsuttu pitämään paastoa Herran edessä.'),
(1688816,58,24,36,10,'Silloin Baaruk luki kirjasta Jeremian sanat Herran temppelissä, kirjuri Gemarjan, Saafanin pojan, kammiossa, ylemmässä esipihassa, Herran temppelin uuden portin ovella, kaiken kansan kuullen.'),
(1688817,58,24,36,11,'Kun Miika, Gemarjan, Saafanin pojan, poika, oli kuullut kaikki Herran sanat kirjasta,'),
(1688818,58,24,36,12,'niin hän meni alas kuninkaan linnaan, kirjurin kammioon, ja katso, siellä istuivat kaikki päämiehet: kirjuri Elisama ja Delaja, Semajan poika, ja Elnatan, Akborin poika, ja Gemarja, Saafanin poika, ja Sidkia, Hananjan poika, ja kaikki muut päämiehet.'),
(1688819,58,24,36,13,'Heille Miika ilmoitti kaikki sanat, jotka hän oli kuullut Baarukin lukevan kirjasta kansan kuullen.'),
(1688820,58,24,36,14,'Silloin kaikki päämiehet lähettivät Baarukin tykö Jehudin, joka oli Netanjan poika, joka Selemjan poika, joka Kuusin poika, ja käskivät sanoa: "Ota käteesi kirjakäärö, josta luit kansan kuullen, ja tule tänne". Ja Baaruk, Neerian poika, otti kirjakäärön käteensä ja meni heidän tykönsä.'),
(1688821,58,24,36,15,'Ja he sanoivat hänelle: "Istu ja lue meidän kuultemme", ja Baaruk luki heidän kuultensa.'),
(1688822,58,24,36,16,'Mutta kun he olivat kuulleet kaikki sanat, katsoivat he toisiinsa peljästyneinä ja sanoivat Baarukille: "Meidän täytyy ilmoittaa kuninkaalle kaikki nämä sanat".'),
(1688823,58,24,36,17,'Ja he kysyivät Baarukilta sanoen: "Ilmoita meille, kuinka sinä kirjoitit kaikki nämä sanat hänen suustansa".'),
(1688824,58,24,36,18,'Baaruk vastasi heille: "Hän saneli minulle suustansa kaikki nämä sanat, ja minä kirjoitin ne musteella kirjaan".'),
(1688825,58,24,36,19,'Silloin päämiehet sanoivat Baarukille: "Mene ja piiloudu, sinä ja Jeremia, älköönkä kukaan saako tietää, missä te olette".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688826,58,24,36,20,'Niin he menivät kuninkaan tykö esipihaan, mutta kirjakäärön he jättivät talteen kirjuri Elisaman kammioon. Ja he ilmoittivat kuninkaalle kaikki.'),
(1688827,58,24,36,21,'Silloin kuningas lähetti Jehudin hakemaan kirjakääröä, ja hän haki sen kirjuri Elisaman kammiosta. Sitten Jehudi luki sen kuninkaan kuullen ja kaikkien päämiesten kuullen, jotka seisoivat kuninkaan edessä.'),
(1688828,58,24,36,22,'Mutta kuningas istui talvihuoneessa - oli yhdeksäs kuukausi - ja hänen edessään oli palamassa hiilipannu.'),
(1688829,58,24,36,23,'Ja aina kun Jehudi oli lukenut kolme tai neljä palstaa, leikkasi kuningas ne pois kirjurinveitsellä ja viskasi tuleen, joka oli hiilipannussa, kunnes koko kirjakäärö oli palanut loppuun tulessa, joka oli hiilipannussa.'),
(1688830,58,24,36,24,'Mutta ei kuningas eikä kukaan hänen palvelijoistaan, jotka kuulivat kaikki nämä sanat, peljästynyt eikä reväissyt vaatteitansa.'),
(1688831,58,24,36,25,'Ja vaikka Elnatan ja Delaja ja Gemarja pyysivät hartaasti kuningasta, ettei hän polttaisi kirjakääröä, ei hän heitä kuullut.'),
(1688832,58,24,36,26,'Ja kuningas käski Jerahmeelin, kuninkaan pojan, ja Serajan, Asrielin pojan, ja Selemjan, Abdeelin pojan, ottaa kiinni kirjuri Baarukin ja profeetta Jeremian; mutta Herra kätki heidät.'),
(1688833,58,24,36,27,'Mutta sen jälkeen kuin kuningas oli polttanut kirjakäärön ynnä sanat, jotka Baaruk oli kirjoittanut Jeremian suusta, tuli Jeremialle tämä Herran sana:'),
(1688834,58,24,36,28,'"Ota taas itsellesi toinen kirjakäärö ja kirjoita siihen kaikki entiset sanat, jotka olivat edellisessäkin kirjakäärössä, jonka Juudan kuningas Joojakim poltti.'),
(1688835,58,24,36,29,'Ja sano Juudan kuninkaasta Joojakimista: Näin sanoo Herra: Sinä olet polttanut tämän kirjakäärön sanoen: ''Miksi olet kirjoittanut siihen näin: Baabelin kuningas on tuleva ja hävittävä tämän maan ja lopettava siitä ihmiset ja eläimet?'''),
(1688836,58,24,36,30,'Sentähden sanoo Herra Juudan kuninkaasta Joojakimista näin: Hänellä ei ole oleva jälkeläistä, joka istuisi Daavidin valtaistuimella; ja hänen ruumiinsa viskataan pois, virumaan päivän helteessä ja yön kylmässä.'),
(1688837,58,24,36,31,'Ja minä rankaisen häntä ja hänen jälkeläisiänsä ja hänen palvelijoitansa heidän pahojen tekojensa tähden. Ja minä annan tulla heille ja Jerusalemin asukkaille ja Juudan miehille kaiken sen onnettomuuden, jolla minä olen heitä uhannut, vaikka he eivät ole kuulleet."'),
(1688838,58,24,36,32,'Sitten Jeremia otti toisen kirjakäärön ja antoi sen kirjuri Baarukille, Neerian pojalle; ja tämä kirjoitti siihen Jeremian suusta kaikki sen kirjan sanat, jonka Juudan kuningas Joojakim oli tulessa polttanut. Ja niihin lisättiin vielä paljon samankaltaisia sanoja.'),
(1688839,58,24,37,1,'Ja Sidkia, Joosian poika, tuli kuninkaaksi Konjan, Joojakimin pojan, sijaan; sillä Nebukadressar, Baabelin kuningas, asetti hänet kuninkaaksi Juudan maahan.'),
(1688840,58,24,37,2,'Mutta ei hän eivätkä hänen palvelijansa eikä maan kansa totelleet Herran sanoja, jotka hän puhui profeetta Jeremian kautta.'),
(1688841,58,24,37,3,'Ja kuningas Sidkia lähetti Juukalin, Selemjan pojan, ja pappi Sefanjan, Maasejan pojan, profeetta Jeremian tykö ja käski sanoa: "Rukoile meidän puolestamme Herraa, meidän Jumalaamme".'),
(1688842,58,24,37,4,'Silloin vielä Jeremia sai tulla ja mennä kansan keskellä, sillä häntä ei oltu pantu vankeuteen.'),
(1688843,58,24,37,5,'Mutta faraon sotajoukko oli lähtenyt liikkeelle Egyptistä; ja kun kaldealaiset, jotka piirittivät Jerusalemia, kuulivat siitä sanoman, lähtivät he pois Jerusalemin kimpusta.'),
(1688844,58,24,37,6,'Silloin tuli profeetta Jeremialle tämä Herran sana:'),
(1688845,58,24,37,7,'"Näin sanoo Herra, Israelin Jumala: Sanokaa näin Juudan kuninkaalle, joka on lähettänyt teidät minun tyköni kysymään minulta neuvoa: Katso, faraon sotajoukko, joka on lähtenyt teidän avuksenne, on palaava takaisin maahansa Egyptiin.'),
(1688846,58,24,37,8,'Sitten kaldealaiset tulevat takaisin ja sotivat tätä kaupunkia vastaan, valloittavat sen ja polttavat tulella.'),
(1688847,58,24,37,9,'Näin sanoo Herra: Älkää pettäkö itseänne sanoen: ''Kaldealaiset lähtevät pois meidän kimpustamme''. Sillä he eivät lähde.'),
(1688848,58,24,37,10,'Ja vaikka te voittaisitte koko kaldealaisten sotajoukon, joka sotii teitä vastaan, niin ettei heistä jäisi jäljelle kuin muutamia haavoitettuja miehiä, niin nämä nousisivat pystyyn, kukin teltassansa, ja tulella polttaisivat tämän kaupungin."'),
(1688849,58,24,37,11,'Mutta kun kaldealaisten sotajoukko faraon sotajoukon tähden oli lähtenyt pois Jerusalemia piirittämästä,'),
(1688850,58,24,37,12,'yritti Jeremia lähteä Jerusalemista mennäkseen Benjaminin maahan ottamaan perintömaan jaossa osansa siellä, kansan keskuudessa.'),
(1688851,58,24,37,13,'Mutta kun hän oli tullut Benjaminin portille, niin siinä oleva vartionpäällikkö, jonka nimi oli Jiiria, Selemjan, Hananjan pojan, poika, otti kiinni profeetta Jeremian sanoen: "Sinä aiot karata kaldealaisten puolelle".'),
(1688852,58,24,37,14,'Jeremia vastasi: "Se on valhe! Minä en aio karata kaldealaisten puolelle." Mutta Jiiria ei kuunnellut häntä, vaan otti Jeremian kiinni ja vei hänet päämiesten tykö.'),
(1688853,58,24,37,15,'Ja ruhtinaat vihastuivat Jeremiaan ja löivät häntä ja panivat hänet vankeuteen kirjuri Joonatanin taloon, sillä sen he olivat laittaneet vankilaksi.'),
(1688854,58,24,37,16,'Niin Jeremia joutui vankiluolaan ja holveihin, ja Jeremia jäi sinne kauaksi aikaa.'),
(1688855,58,24,37,17,'Sitten kuningas Sidkia lähetti hakemaan hänet, ja kuningas kysyi häneltä salaa linnassansa ja sanoi: "Onko sanaa Herralta?" Jeremia vastasi: "On". Ja hän sanoi: "Sinut annetaan Baabelin kuninkaan käsiin".'),
(1688856,58,24,37,18,'Ja Jeremia sanoi kuningas Sidkialle: "Mitä minä olen rikkonut sinua ja sinun palvelijoitasi vastaan ja tätä kansaa vastaan, koska te olette panneet minut vankeuteen?'),
(1688857,58,24,37,19,'Ja missä ovat teidän profeettanne, jotka ennustivat teille sanoen: ''Ei tule Baabelin kuningas teidän kimppuunne eikä tämän maan kimppuun''?'),
(1688858,58,24,37,20,'Ja kuule nyt, herrani, kuningas, salli minun rukoukseni langeta sinun eteesi äläkä lähetä minua takaisin kirjuri Joonatanin taloon, etten kuolisi siellä."'),
(1688859,58,24,37,21,'Silloin kuningas Sidkia käski säilyttää Jeremiaa vankilan pihassa, ja hänelle annettiin leipäkakku päivässä Leipurienkadulta, kunnes kaikki leipä oli kaupungista loppunut. Ja Jeremia jäi vankilan pihaan.'),
(1688860,58,24,38,1,'Mutta Sefatja, Mattanin poika, ja Gedalja, Pashurin poika, ja Juukal, Selemjan poika, ja Pashur, Malkian poika, kuulivat ne sanat, jotka Jeremia puhui kaikelle kansalle sanoen:'),
(1688861,58,24,38,2,'"Näin sanoo Herra: Joka jää tähän kaupunkiin, se kuolee miekkaan, nälkään ja ruttoon; mutta joka menee kaldealaisten luo, se saa elää, pitää henkensä saaliinansa ja jää eloon.'),
(1688862,58,24,38,3,'Näin sanoo Herra: Tämä kaupunki annetaan Baabelin kuninkaan sotajoukon käsiin, ja hän valloittaa sen."'),
(1688863,58,24,38,4,'Silloin päämiehet sanoivat kuninkaalle: "Tämä mies on kuolemalla rangaistava, sillä hän herpaisee niiden sotamiesten kädet, jotka ovat jäljellä tässä kaupungissa, ja kaiken kansan kädet, kun hän heille puhuu tällaisia sanoja. Sillä ei tämä mies etsi tämän kansan menestystä, vaan onnettomuutta."'),
(1688864,58,24,38,5,'Kuningas Sidkia vastasi: "Katso, hän on teidän käsissänne. Sillä eihän kuningas voi mitään teitä vastaan."'),
(1688865,58,24,38,6,'Silloin he ottivat Jeremian ja heittivät hänet Malkian, kuninkaan pojan, kaivoon, joka oli vankilan pihassa; he laskivat Jeremian köysillä alas. Mutta kaivossa ei ollut vettä, vaan liejua, ja Jeremia vajosi liejuun.'),
(1688866,58,24,38,7,'Mutta etiopialainen Ebed-Melek, hoviherra, joka oli kuninkaan linnassa, kuuli, että he olivat panneet Jeremian kaivoon; mutta kuningas istui Benjaminin portissa.'),
(1688867,58,24,38,8,'Niin Ebed-Melek meni kuninkaan linnasta ja puhutteli kuningasta sanoen:'),
(1688868,58,24,38,9,'"Herrani, kuningas! Nuo miehet ovat pahoin tehneet kaikessa, mitä ovat tehneet profeetta Jeremialle: he ovat heittäneet hänet kaivoon, kuolemaan nälkään siihen paikkaansa." Sillä kaupungissa ei ollut enää leipää.'),
(1688869,58,24,38,10,'Silloin kuningas käski etiopialaista Ebed-Melekiä sanoen: "Ota mukaasi täältä kolmekymmentä miestä ja nosta profeetta Jeremia kaivosta, ennenkuin hän kuolee".'),
(1688870,58,24,38,11,'Ja Ebed-Melek otti miehet mukaansa ja meni kuninkaan linnaan, aarrekammion alla olevaan paikkaan, ja otti sieltä rikkinäisiä ja kuluneita vaateriepuja ja laski ne köysillä Jeremialle kaivoon.'),
(1688871,58,24,38,12,'Sitten etiopialainen Ebed-Melek sanoi Jeremialle: "Pane nämä rikkinäiset ja kuluneet vaaterievut kainaloihisi köytten alle", ja Jeremia teki niin.'),
(1688872,58,24,38,13,'Sitten he vetivät Jeremian köysillä ylös ja nostivat hänet kaivosta. Ja Jeremia jäi vankilan pihaan.'),
(1688873,58,24,38,14,'Mutta kuningas Sidkia lähetti hakemaan profeetta Jeremian tykönsä Herran temppelin kolmanteen sisäänkäytävään. Ja kuningas sanoi Jeremialle: "Minä kysyn sinulta jotakin; älä salaa minulta mitään".'),
(1688874,58,24,38,15,'Mutta Jeremia vastasi Sidkialle: "Jos minä sinulle jotakin ilmoitan, niin sinähän surmautat minut. Ja jos minä sinua neuvon, et sinä minua kuule."'),
(1688875,58,24,38,16,'Silloin kuningas Sidkia vannoi salaa Jeremialle sanoen: "Niin totta kuin Herra elää, joka on luonut tämän meidän elämämme: minä en sinua surmauta enkä jätä sinua näiden miesten käsiin, jotka etsivät sinun henkeäsi".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688876,58,24,38,17,'Silloin Jeremia sanoi Sidkialle: "Näin sanoo Herra, Jumala Sebaot, Israelin Jumala: Jos sinä menet Baabelin kuninkaan päämiesten tykö, niin sinun henkesi säilyy, eikä tätä kaupunkia tulella polteta, ja sinä ja sinun huoneesi saatte elää.'),
(1688877,58,24,38,18,'Mutta jos sinä et mene Baabelin kuninkaan päämiesten tykö, niin tämä kaupunki annetaan kaldealaisten käsiin, ja he polttavat sen tulella, etkä sinäkään pelastu heidän käsistänsä."'),
(1688878,58,24,38,19,'Silloin kuningas Sidkia sanoi Jeremialle: "Minä pelkään niitä juutalaisia, jotka ovat menneet kaldealaisten puolelle, pelkään, että minut jätetään heidän käsiinsä ja he pitävät minua pilkkanansa".'),
(1688879,58,24,38,20,'Mutta Jeremia sanoi: "Ei jätetä. Kuule vain Herran ääntä, kuule, mitä minä sinulle puhun, niin sinun käy hyvin, ja sinun henkesi säilyy.'),
(1688880,58,24,38,21,'Mutta jos sinä et tahdo mennä, niin tämä on se sana, jonka Herra on minulle näyttänyt:'),
(1688881,58,24,38,22,'Katso, kaikki naiset, jotka ovat jäljellä Juudan kuninkaan linnassa, viedään Baabelin kuninkaan päämiesten luokse, ja katso, he sanovat: ''Sinun ystäväsi ovat sinut viekoitelleet ja saaneet sinut valtaansa; sinun jalkasi vajosivat liejuun - he vetäytyivät pois''.'),
(1688882,58,24,38,23,'Ja kaikki sinun vaimosi ja lapsesi viedään kaldealaisten luokse, etkä sinä pelastu näiden käsistä, vaan Baabelin kuninkaan käsi tarttuu sinuun, ja sinä saatat tämän kaupungin tulella poltettavaksi."'),
(1688883,58,24,38,24,'Silloin Sidkia sanoi Jeremialle: "Älköön kukaan saako tietää tästä puhelusta, muutoin sinä kuolet.'),
(1688884,58,24,38,25,'Mutta jos päämiehet kuulevat, että minä olen puhunut sinun kanssasi, ja tulevat sinun luoksesi ja sanovat sinulle: ''Ilmoita meille, mitä olet puhunut kuninkaalle ja mitä kuningas on puhunut sinulle - älä salaa sitä meiltä, muutoin me surmaamme sinut'' -'),
(1688885,58,24,38,26,'niin sano heille: ''Minä annoin rukoukseni langeta kuninkaan eteen, ettei hän lähettäisi minua takaisin Joonatanin taloon, kuolemaan sinne''."'),
(1688886,58,24,38,27,'Ja kaikki ruhtinaat tulivat Jeremian tykö ja kysyivät häneltä, ja hän ilmoitti heille kaiken, mitä kuningas oli käskenyt hänen ilmoittaa. Niin he jättivät hänet rauhaan, sillä asiasta ei oltu mitään kuultu.'),
(1688887,58,24,38,28,'Ja Jeremia jäi olemaan vankilan pihassa siihen päivään asti, jona Jerusalem valloitettiin.'),
(1688888,58,24,39,1,'Kun Jerusalem oli valloitettu - sillä Juudan kuninkaan Sidkian yhdeksäntenä hallitusvuotena, kymmenennessä kuussa, oli Nebukadressar, Baabelin kuningas, kaikkine sotajoukkoineen hyökännyt Jerusalemin kimppuun ja saartanut sen,'),
(1688889,58,24,39,2,'ja Sidkian yhdentenätoista hallitusvuotena, neljännessä kuussa, kuukauden yhdeksäntenä päivänä, oli kaupunki vallattu'),
(1688890,58,24,39,3,'- niin kaikki Baabelin kuninkaan päämiehet tulivat ja asettuivat Keskiporttiin: Neergal-Sareser, Samgar-Nebo, Sarsekim, ylimmäinen hoviherra, Neergal-Sareser, ylimmäinen tietäjä, ja kaikki muut Baabelin kuninkaan päämiehet.'),
(1688891,58,24,39,4,'Kun Sidkia, Juudan kuningas, ja kaikki sotilaat näkivät heidät, niin he pakenivat ja lähtivät yöllä kaupungista kuninkaan puutarhaa kohti molempain muurien välisestä portista, ja hän lähti Aromaahan päin.'),
(1688892,58,24,39,5,'Mutta kaldealaisten sotajoukko ajoi heitä takaa, ja he saavuttivat Sidkian Jerikon aroilla. Ja he ottivat hänet kiinni ja veivät hänet Nebukadressarin, Baabelin kuninkaan, eteen Riblaan, joka on Hamatin maassa, ja tämä julisti hänelle tuomion.'),
(1688893,58,24,39,6,'Ja Baabelin kuningas teurastutti Sidkian pojat Riblassa hänen silmiensä edessä; ja kaikki Juudan ylimykset Baabelin kuningas teurastutti.'),
(1688894,58,24,39,7,'Sitten hän sokaisutti Sidkian silmät ja kytketti hänet vaskikahleisiin viedäkseen hänet Baabeliin.'),
(1688895,58,24,39,8,'Kuninkaan linnan ja kansan talot kaldealaiset polttivat tulella, ja Jerusalemin muurit he repivät maahan.'),
(1688896,58,24,39,9,'Ja loput kansasta, jotka olivat jäljellä kaupungissa, sekä ne, jotka olivat menneet hänen puolellensa - loput kansasta, jotka olivat jäljellä - vei Nebusaradan, henkivartijain päällikkö, pakkosiirtolaisuuteen Baabeliin.'),
(1688897,58,24,39,10,'Mutta köyhimmät kansasta, joilla ei ollut mitään, Nebusaradan, henkivartijain päällikkö, jätti Juudan maahan ja antoi heille sinä päivänä viinitarhoja ja peltoja.'),
(1688898,58,24,39,11,'Ja Nebukadressar, Baabelin kuningas, oli antanut Nebusaradanille, henkivartijain päällikölle, Jeremiasta tämän käskyn:'),
(1688899,58,24,39,12,'"Ota hänet ja pidä hänestä huoli; älä tee hänelle mitään pahaa, vaan tee hänelle niin, kuin hän itse sinulle sanoo".'),
(1688900,58,24,39,13,'Silloin lähettivät Nebusaradan, henkivartijain päällikkö, Nebusasban, ylimmäinen hoviherra, Neergal-Sareser, ylimmäinen tietäjä, ja kaikki muut Baabelin kuninkaan ylimmäiset'),
(1688901,58,24,39,14,'- nämä lähettivät noutamaan Jeremian vankilan pihasta ja antoivat hänet Gedaljalle, Saafanin pojan Ahikamin pojalle, että tämä veisi hänet kotiin, ja niin hän jäi kansan keskuuteen.'),
(1688902,58,24,39,15,'Jeremialle oli tullut tämä Herran sana hänen ollessaan suljettuna vankilan pihaan:'),
(1688903,58,24,39,16,'"Mene ja sano etiopialaiselle Ebed-Melekille näin: Näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä toteutan sanani tälle kaupungille onnettomuudeksi eikä onneksi; ja tämä tapahtuu sinun edessäsi sinä päivänä.'),
(1688904,58,24,39,17,'Mutta sinut minä pelastan sinä päivänä, sanoo Herra, etkä sinä ole joutuva niiden miesten käsiin, joita sinä pelkäät.'),
(1688905,58,24,39,18,'Sillä minä pelastan sinut, niin ettet kaadu miekkaan, vaan saat pitää henkesi saaliinasi, koska sinä turvasit minuun, sanoo Herra."'),
(1688906,58,24,40,1,'Sana, joka tuli Jeremialle Herralta, sen jälkeen kuin Nebusaradan, henkivartijain päällikkö, oli päästänyt hänet menemään Raamasta, jonne hän oli haettanut hänet, kun hän oli kahleilla sidottuna kaikkien Baabeliin vietävien Jerusalemin ja Juudan pakkosiirtolaisten joukossa.'),
(1688907,58,24,40,2,'Henkivartijain päällikkö haetti Jeremian ja sanoi hänelle: "Herra, sinun Jumalasi, on uhannut tällä onnettomuudella tätä paikkaa,'),
(1688908,58,24,40,3,'ja Herra on antanut sen tulla ja on tehnyt, niinkuin hän on puhunut; sillä te olette tehneet syntiä Herraa vastaan ettekä ole kuulleet hänen ääntänsä, ja niin on tämä tapahtunut teille.'),
(1688909,58,24,40,4,'Ja katso, nyt minä tänä päivänä päästän sinut kahleista, jotka ovat käsissäsi. Jos näet hyväksi tulla minun kanssani Baabeliin, niin tule, ja minä pidän sinusta huolen. Mutta jos et näe hyväksi tulla minun kanssani Baabeliin, niin älä tule. Katso, koko maa on edessäsi; minne näet hyväksi ja oikeaksi mennä, sinne mene."'),
(1688910,58,24,40,5,'Mutta kun tämä vielä viivytteli palaamistaan, sanoi hän: "Palaa Gedaljan tykö, joka on Saafanin pojan Ahikamin poika, hänen, jonka Baabelin kuningas on asettanut Juudan kaupunkien käskynhaltijaksi, ja jää hänen luoksensa kansan keskuuteen; tahi mene, minne vain näet oikeaksi mennä". Ja henkivartijain päällikkö antoi hänelle evästä ja lahjoja ja päästi hänet menemään.'),
(1688911,58,24,40,6,'Niin Jeremia meni Gedaljan, Ahikamin pojan, tykö Mispaan ja asui hänen luonaan maahan jääneen kansan keskuudessa.'),
(1688912,58,24,40,7,'Kun kaikki sotaväen päälliköt, jotka olivat maaseudulla, he ja heidän miehensä, kuulivat, että Baabelin kuningas oli asettanut Gedaljan, Ahikamin pojan, käskynhaltijaksi maahan ja jättänyt hänen haltuunsa ne miehet, vaimot ja lapset sekä ne maan köyhät, joita ei oltu siirretty Baabeliin,'),
(1688913,58,24,40,8,'niin he tulivat Gedaljan luo Mispaan: Ismael, Netanjan poika, Joohanan ja Joonatan, Kaareahin pojat, Seraja, Tanhumetin poika, netofalaisen Eefain pojat ja Jesanja, maakatilaisen poika, he ja heidän miehensä.'),
(1688914,58,24,40,9,'Ja Gedalja, Saafanin pojan Ahikamin poika, vannoi heille ja heidän miehilleen sanoen: "Älkää peljätkö palvella kaldealaisia; asukaa maassa ja palvelkaa Baabelin kuningasta, niin teidän käy hyvin.'),
(1688915,58,24,40,10,'Katso, minä itse asun Mispassa palvellakseni niitä kaldealaisia, jotka tulevat meidän luoksemme; mutta te kootkaa viiniä ja hedelmiä ja öljyä ja pankaa astioihinne ja asukaa kaupungeissanne, jotka olette ottaneet haltuunne."'),
(1688916,58,24,40,11,'Ja kaikki nekin juutalaiset, jotka olivat Mooabissa ja ammonilaisten keskuudessa ja Edomissa sekä kaikissa muissa maissa, saivat kuulla, että Baabelin kuningas oli jättänyt Juudaan jäännöksen ja asettanut näille käskynhaltijaksi Gedaljan, joka oli Saafanin pojan Ahikamin poika.'),
(1688917,58,24,40,12,'Ja niin kaikki juutalaiset palasivat takaisin kaikista paikoista, joihin heitä oli karkoitettu, ja tulivat Juudan maahan Mispaan, Gedaljan tykö, ja he korjasivat viiniä ja hedelmiä ylen runsaasti.'),
(1688918,58,24,40,13,'Mutta Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt, jotka olivat maaseudulla, tulivat Gedaljan tykö Mispaan'),
(1688919,58,24,40,14,'ja sanoivat hänelle: "Tiedätkö, että ammonilaisten kuningas Baalis on lähettänyt Ismaelin, Netanjan pojan, lyömään sinut kuoliaaksi?" Mutta Gedalja, Ahikamin poika, ei uskonut heitä.'),
(1688920,58,24,40,15,'Silloin Joohanan, Kaareahin poika, sanoi Gedaljalle Mispassa salaa näin: "Minäpä menen ja lyön kuoliaaksi Ismaelin, Netanjan pojan, kenenkään tietämättä! Miksi hän saa lyödä sinut kuoliaaksi, niin että kaikki juutalaiset, jotka ovat kokoontuneet sinun luoksesi, hajaantuvat ja Juudan jäännös hukkuu?"'),
(1688921,58,24,40,16,'Mutta Gedalja, Ahikamin poika, vastasi Joohananille, Kaareahin pojalle: "Älä tee sitä, sillä sinä puhut valhetta Ismaelista".'),
(1688922,58,24,41,1,'Mutta seitsemännessä kuussa Ismael, Elisaman pojan Netanjan poika, joka oli kuninkaallista sukua ja kuninkaan ylimmäisiä, tuli Gedaljan, Ahikamin pojan, tykö Mispaan, mukanaan kymmenen miestä. Siellä Mispassa he sitten aterioivat yhdessä.'),
(1688923,58,24,41,2,'Silloin nousi Ismael, Netanjan poika, ynnä ne kymmenen miestä, jotka olivat hänen kanssaan, ja he löivät miekalla kuoliaaksi Gedaljan, joka oli Saafanin pojan Ahikamin poika. Niin Ismael surmasi hänet, jonka Baabelin kuningas oli asettanut käskynhaltijaksi maahan.'),
(1688924,58,24,41,3,'Myöskin kaikki juutalaiset, jotka olivat Gedaljan luona Mispassa, sekä kaldealaiset, jotka sieltä tavattiin, sotamiehet, Ismael löi kuoliaaksi.'),
(1688925,58,24,41,4,'Toisena päivänä, sen jälkeen kuin hän oli surmannut Gedaljan, kun ei kukaan sitä vielä tietänyt,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688926,58,24,41,5,'tuli Sikemistä, Siilosta ja Samariasta kahdeksankymmentä miestä, parta ajettuna, vaatteet revittyinä ja iho viileskeltynä, ja heillä oli käsissään ruokauhreja ja suitsutusta, vietäväksi Herran temppeliin.'),
(1688927,58,24,41,6,'Ja Ismael, Netanjan poika, meni Mispasta heitä vastaan, lakkaamatta itkien käydessänsä. Ja kun hän kohtasi heidät, sanoi hän heille: "Tulkaa Gedaljan, Ahikamin pojan, tykö".'),
(1688928,58,24,41,7,'Mutta kun he olivat tulleet keskelle kaupunkia, teurastivat heidät Ismael, Netanjan poika, ja ne miehet, jotka olivat hänen kanssaan, ja heittivät heidät kaivoon.'),
(1688929,58,24,41,8,'Mutta heidän joukossaan oli kymmenen miestä, jotka sanoivat Ismaelille: "Älä surmaa meitä, sillä meillä on kedolla kätkössä nisuja, ohria, öljyä ja hunajaa". Niin hän herkesi eikä surmannut heitä heidän veljiensä joukkoon.'),
(1688930,58,24,41,9,'Ja kaivo, johon Ismael heitti kaikkien niiden miesten ruumiit, jotka hän oli lyönyt kuoliaaksi, samoin kuin Gedaljan, oli se, jonka kuningas Aasa oli teettänyt Baesan, Israelin kuninkaan, hyökkäyksen varalta; sen täytti nyt Ismael, Netanjan poika, murhatuilla.'),
(1688931,58,24,41,10,'Sitten Ismael otti vangeiksi kaikki kansan tähteet, mitä Mispassa oli, kuninkaan tyttäret ja kaiken Mispaan jäljelle jääneen kansan, jonka käskynhaltijaksi Nebusaradan, henkivartijain päällikkö, oli asettanut Gedaljan, Ahikamin pojan - ne Ismael, Netanjan poika, otti vangeiksi ja lähti kulkemaan pois ammonilaisten luo.'),
(1688932,58,24,41,11,'Mutta kun Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt, jotka olivat hänen kanssaan, saivat kuulla kaiken sen pahan, minkä Ismael, Netanjan poika, oli tehnyt,'),
(1688933,58,24,41,12,'niin he ottivat kaikki miehensä ja lähtivät taistelemaan Ismaelia, Netanjan poikaa, vastaan; ja he tapasivat hänet suuren vesilammikon luona, joka on Gibeonissa.'),
(1688934,58,24,41,13,'Mutta kun kaikki kansa, joka oli Ismaelin mukana, näki Joohananin, Kaareahin pojan, ja kaikki sotaväen päälliköt, jotka olivat hänen kanssaan, niin he ihastuivat;'),
(1688935,58,24,41,14,'ja kaikki kansa, jonka Ismael oli ottanut vangiksi Mispasta, kääntyi takaisin ja meni Joohananin, Kaareahin pojan, puolelle.'),
(1688936,58,24,41,15,'Mutta Ismael, Netanjan poika, pääsi kahdeksan miehen kanssa Joohanania pakoon ja lähti ammonilaisten luo.'),
(1688937,58,24,41,16,'Ja Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt, jotka olivat hänen kanssaan, ottivat kaikki kansan tähteet, jotka hän oli palauttanut Ismaelin, Netanjan pojan, tyköä Mispasta, sen jälkeen kuin tämä oli lyönyt Gedaljan, Ahikamin pojan, kuoliaaksi: miehiä, sotilaita, naisia ja lapsia ja hoviherroja, jotka hän oli palauttanut Gibeonista.'),
(1688938,58,24,41,17,'Ja he kulkivat, mutta pysähtyivät Kimhamin majapaikkaan, joka on lähellä Beetlehemiä, lähteäkseen sitten Egyptiin'),
(1688939,58,24,41,18,'kaldealaisia pakoon, sillä he pelkäsivät heitä, koska Ismael, Netanjan poika, oli lyönyt kuoliaaksi Gedaljan, Ahikamin pojan, jonka Baabelin kuningas oli asettanut käskynhaltijaksi maahan.'),
(1688940,58,24,42,1,'Silloin astuivat esiin kaikki sotaväen päälliköt ja Joohanan, Kaareahin poika, ja Jesanja, Hoosajan poika, ynnä kaikki kansa, pienimmästä suurimpaan,'),
(1688941,58,24,42,2,'ja sanoivat profeetta Jeremialle: "Langetkoon rukouksemme sinun eteesi, ja rukoile puolestamme Herraa, Jumalaasi, kaiken tämän jäännöksen puolesta; sillä suuresta luvusta on meitä jäänyt jäljelle vähän, niinkuin omat silmäsi näkevät meitä olevan.'),
(1688942,58,24,42,3,'Ja Herra, sinun Jumalasi, ilmoittakoon meille, mitä tietä meidän on kuljettava, ja mitä meidän on tehtävä."'),
(1688943,58,24,42,4,'Silloin profeetta Jeremia vastasi heille: "Minä kuulen. Katso, minä rukoilen Herraa, teidän Jumalaanne, niinkuin sanotte, ja kaiken sen, mitä Herra teille vastaa, minä ilmoitan teille; en salaa teiltä mitään."'),
(1688944,58,24,42,5,'Ja he sanoivat Jeremialle: "Olkoon Herra totinen ja luotettava todistaja meitä vastaan, jollemme tee aivan sen sanan mukaan, jonka Herra, sinun Jumalasi, lähettää sinut meille tuomaan.'),
(1688945,58,24,42,6,'Olkoon se hyvä tahi paha: Herran ääntä, meidän Jumalamme, jonka tykö me sinut lähetämme, me tottelemme, että meidän hyvin kävisi, kun tottelemme Herran, meidän Jumalamme, ääntä."'),
(1688946,58,24,42,7,'Kymmenen päivän kuluttua tuli Herran sana Jeremialle,'),
(1688947,58,24,42,8,'ja hän kutsui Joohananin, Kaareahin pojan, ja kaikki sotaväen päälliköt, jotka olivat tämän kanssa, ynnä kaiken kansan, pienimmästä suurimpaan.'),
(1688948,58,24,42,9,'Ja hän sanoi heille: "Näin sanoo Herra, Israelin Jumala, jonka tykö te lähetitte minut laskemaan rukouksenne hänen eteensä:'),
(1688949,58,24,42,10,'Jos te jäätte tähän maahan, niin minä rakennan teidät enkä hajota maahan, istutan teidät enkä revi pois, sillä minä kadun sitä onnettomuutta, jonka olen tuottanut teille.'),
(1688950,58,24,42,11,'Älkää peljätkö Baabelin kuningasta, jota te nyt pelkäätte. Älkää peljätkö häntä, sanoo Herra; sillä minä olen teidän kanssanne, minä autan teitä ja pelastan teidät hänen käsistänsä.'),
(1688951,58,24,42,12,'Ja minä annan teille armon, niin että hän teitä armahtaa ja antaa teidän palata takaisin maahanne.'),
(1688952,58,24,42,13,'Mutta jos te sanotte: ''Me emme jää tähän maahan'', ettekä tottele Herran, teidän Jumalanne, ääntä,'),
(1688953,58,24,42,14,'vaan sanotte: ''Ei! Me lähdemme Egyptiin, jossa meidän ei tarvitse nähdä sotaa, ei kuulla pasunan ääntä eikä kärsiä leivän nälkää, ja sinne me jäämme asumaan'' -'),
(1688954,58,24,42,15,'niin kuulkaa siis nyt Herran sana, te Juudan tähteet: Näin sanoo Herra Sebaot, Israelin Jumala: Jos te todella käännätte kasvonne Egyptiä kohti ja menette sinne asumaan muukalaisina,'),
(1688955,58,24,42,16,'niin miekka, jota te pelkäätte, on saavuttava teidät siellä Egyptin maassa, ja nälkä, joka teitä huolettaa, seuraa kintereillänne Egyptiin, ja sinne te kuolette.'),
(1688956,58,24,42,17,'Ja kaikki ne miehet, jotka kääntävät kasvonsa Egyptiä kohti asuakseen siellä muukalaisina, kuolevat miekkaan, nälkään ja ruttoon, eikä ainoakaan heistä pääse pakoon eikä pelastu siitä onnettomuudesta, jonka minä annan heille tulla.'),
(1688957,58,24,42,18,'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Niinkuin minun vihani ja kiivastukseni on vuodatettu Jerusalemin asukasten ylitse, niin minun kiivastukseni on vuotava teidän ylitsenne, jos te menette Egyptiin, ja te tulette kiroukseksi ja kauhistukseksi, kiroussanaksi ja häväistykseksi ettekä enää saa nähdä tätä paikkaa.'),
(1688958,58,24,42,19,'Herra sanoo teille, te Juudan tähteet: Älkää menkö Egyptiin." Se tietäkää, että minä olen tänä päivänä teitä varoittanut.'),
(1688959,58,24,42,20,'Te eksytitte itsenne, kun lähetitte minut Herran, teidän Jumalanne, tykö sanoen: "Rukoile puolestamme Herraa, meidän Jumalaamme; ja kaikki, mitä Herra, meidän Jumalamme, sanoo, ilmoita meille, niin me teemme sen".'),
(1688960,58,24,42,21,'Minä olen sen tänä päivänä teille ilmoittanut, mutta te olette tottelemattomat Herran, teidän Jumalanne, äänelle kaikessa, mitä varten hän on lähettänyt minut teidän tykönne.'),
(1688961,58,24,42,22,'Nyt siis tietäkää, että te kuolette miekkaan, nälkään ja ruttoon siinä paikassa, johon te haluatte mennä, siellä muukalaisina asumaan.'),
(1688962,58,24,43,1,'Mutta kun Jeremia oli loppuun asti puhunut kaikelle kansalle kaikki Herran, heidän Jumalansa, sanat, jotka Herra, heidän Jumalansa, oli lähettänyt hänet tuomaan heille - kaikki ne sanat, -'),
(1688963,58,24,43,2,'niin Asarja, Hoosajan poika, ja Joohanan, Kaareahin poika, ja kaikki julkeat miehet sanoivat Jeremialle: "Sinä puhut valhetta; Herra, meidän Jumalamme, ei ole lähettänyt sinua sanomaan: ''Älkää menkö Egyptiin, siellä muukalaisina asumaan'';'),
(1688964,58,24,43,3,'vaan Baaruk, Neerian poika, kiihoittaa sinua meitä vastaan antaakseen meidät kaldealaisten käsiin tapettaviksi tai vietäviksi pakkosiirtolaisuuteen Baabeliin".'),
(1688965,58,24,43,4,'Ja Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt ja kaikki kansa olivat tottelemattomat Herran äänelle eivätkä jääneet Juudan maahan,'),
(1688966,58,24,43,5,'niin Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt ottivat kaikki Juudan tähteet, jotka olivat kaikista kansakunnista, jonne heidät oli karkoitettu, palanneet asumaan Juudan maahan:'),
(1688967,58,24,43,6,'miehet, naiset ja lapset, kuninkaan tyttäret ja kaiken sen väen, jonka Nebusaradan, henkivartijain päällikkö, oli jättänyt Gedaljan huostaan, joka oli Saafanin pojan Ahikamin poika, sekä profeetta Jeremian ja Baarukin, Neerian pojan.'),
(1688968,58,24,43,7,'Ja he menivät Egyptin maahan, sillä he eivät kuulleet Herran ääntä. Ja niin he tulivat Tahpanheeseen.'),
(1688969,58,24,43,8,'Ja tämä Herran sana tuli Jeremialle Tahpanheessa:'),
(1688970,58,24,43,9,'"Ota käsiisi suuria kiviä ja kätke ne muurilaastiin, tiilikivipenkereeseen, joka on faraon linnan oven edustalla Tahpanheessa, juutalaisten miesten nähden.'),
(1688971,58,24,43,10,'Ja sano heille: Näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä lähetän hakemaan palvelijani Nebukadressarin, Baabelin kuninkaan, ja asetan hänen valtaistuimensa näiden kivien päälle, jotka minä olen kätkenyt, ja hän on levittävä loistomattonsa niiden yli.'),
(1688972,58,24,43,11,'Ja hän tulee ja lyö Egyptin maata: joka ruton oma, se ruttoon, joka vankeuden, se vankeuteen, joka miekan, se miekkaan!'),
(1688973,58,24,43,12,'Ja minä sytytän Egyptin jumalien temppelit tuleen, ja hän polttaa ne ja vie jumalat pois saaliinansa. Ja hän puhdistaa Egyptin maan syöpäläisistä, niinkuin paimen puhdistaa vaatteensa syöpäläisistä, ja lähtee sieltä vammatonna.'),
(1688974,58,24,43,13,'Ja hän murskaa patsaat Egyptin maan Beet-Semeksestä, ja Egyptin jumalien temppelit hän polttaa tulella."'),
(1688975,58,24,44,1,'Sana, joka tuli Jeremialle kaikkia niitä juutalaisia vastaan, jotka asuivat Egyptin maassa, asuivat Migdolissa, Tahpanheessa, Noofissa ja Patroksen maakunnassa; se kuului:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1688976,58,24,44,2,'"Näin sanoo Herra Sebaot, Israelin Jumala: Te olette nähneet kaiken sen onnettomuuden, jonka minä olen antanut tulla Jerusalemille ja kaikille Juudan kaupungeille. Katso, ne ovat nyt raunioina, eikä niissä asukasta ole,'),
(1688977,58,24,44,3,'heidän pahuutensa tähden, jota he tekivät, vihoittaen minut, kun menivät ja polttivat uhreja muille jumalille, palvelivat niitä, joita he eivät tunteneet, eivät he ettekä te eivätkä teidän isänne.'),
(1688978,58,24,44,4,'Ja varhaisesta alkaen minä lähetin teidän tykönne kaikki palvelijani, profeetat, sanomaan: ''Älkää tehkö näitä kauhistuksia, joita minä vihaan''.'),
(1688979,58,24,44,5,'Mutta he eivät kuulleet, eivät korvaansa kallistaneet, niin että olisivat kääntyneet pois pahuudestansa ja lakanneet polttamasta uhreja muille jumalille.'),
(1688980,58,24,44,6,'Ja niin vuoti minun kiivastukseni ja vihani alas ja paloi Juudan kaupungeissa ja Jerusalemin kaduilla, ja ne tulivat raunioiksi, autioiksi, niinkuin ne tänä päivänä ovat.'),
(1688981,58,24,44,7,'Ja nyt sanoo Herra, Jumala Sebaot, Israelin Jumala, näin: Miksi tuotatte itsellenne suuren onnettomuuden, hävitätte miehet ja vaimot, lapset ja imeväiset Juudasta, niin ettette jätä itsestänne jäännöstäkään?'),
(1688982,58,24,44,8,'Te vihoitatte minut kättenne töillä, kun poltatte uhreja muille jumalille Egyptin maassa, johon te olette tulleet, täällä muukalaisina asumaan. Niin te tuotatte itsellenne häviön ja tulette kiroussanaksi ja häväistykseksi kaikissa maan kansoissa.'),
(1688983,58,24,44,9,'Oletteko unhottaneet isäinne pahat teot ja Juudan kuningasten pahat teot ja heidän vaimojensa pahat teot, omat pahat tekonne ja vaimojenne pahat teot, mitä he ovat tehneet Juudan maassa ja Jerusalemin kaduilla?'),
(1688984,58,24,44,10,'He eivät ole murtuneet tähän päivään asti, eivät pelkää, eivät vaella minun lakini ja minun käskyjeni mukaan, jotka minä olen antanut teille ja teidän isillenne.'),
(1688985,58,24,44,11,'Sentähden, näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä käännän kasvoni teitä vastaan onnettomuudeksi, hävittääkseni koko Juudan.'),
(1688986,58,24,44,12,'Ja minä tempaan pois Juudan jäännöksen, ne jotka käänsivät kasvonsa Egyptin maata kohti mennäkseen siellä muukalaisina asumaan, ja he hukkuvat kaikki. Egyptin maassa he kaatuvat miekkaan, hukkuvat nälkään, pienimmästä suurimpaan asti he kuolevat miekkaan ja nälkään; ja he tulevat kiroukseksi ja kauhistukseksi, kiroussanaksi ja häväistykseksi.'),
(1688987,58,24,44,13,'Ja minä rankaisen niitä, jotka asuvat Egyptin maassa, niinkuin minä rankaisin Jerusalemia, miekalla, nälällä ja rutolla.'),
(1688988,58,24,44,14,'Ei jää pakoonpäässeitä, ei pelastuneita Juudan jäännöksestä, niistä, jotka ovat tulleet asumaan muukalaisina täällä Egyptin maassa, eivätkä he palaa Juudan maahan, jonne heidän sielunsa halajaa jälleen, heidän siellä asuaksensa; sillä sinne on palaava vain muutamia pakolaisia."'),
(1688989,58,24,44,15,'Mutta kaikki miehet, jotka tiesivät vaimojensa polttavan uhreja muille jumalille, ja kaikki naiset, jotka seisoivat siellä suurena joukkona, ja kaikki kansa, joka asui Egyptin maassa, Patroksessa, vastasivat Jeremialle sanoen:'),
(1688990,58,24,44,16,'"Mitä sinä olet Herran nimessä meille puhunut, siinä me emme sinua tottele;'),
(1688991,58,24,44,17,'vaan me täytämme joka lupauksen, mikä suustamme on lähtenyt, poltamme uhreja taivaan kuningattarelle ja vuodatamme hänelle juomauhreja, niinkuin teimme me ja meidän isämme, meidän kuninkaamme ja ruhtinaamme Juudan kaupungeissa ja Jerusalemin kaduilla; ja silloin meillä oli leipää yltäkyllin, ja meidän oli hyvä olla emmekä nähneet onnettomuutta.'),
(1688992,58,24,44,18,'Mutta siitä asti, kun me lakkasimme polttamasta uhreja taivaan kuningattarelle ja vuodattamasta hänelle juomauhreja, on osanamme ollut kaiken puute ja hukkuminen miekkaan ja nälkään.'),
(1688993,58,24,44,19,'Ja kun me poltamme uhreja taivaan kuningattarelle ja vuodatamme hänelle juomauhreja, niin miestemme luvattako teemme hänelle uhrikakkuja, hänen kuvansa muotoisia, ja vuodatamme hänelle juomauhreja?"'),
(1688994,58,24,44,20,'Silloin Jeremia sanoi kaikelle kansalle, miehille ja naisille, kaikelle kansalle, joka oli hänelle näin vastannut:'),
(1688995,58,24,44,21,'"Eikö sitä uhrisavua, jota te olette suitsuttaneet Juudan kaupungeissa ja Jerusalemin kaduilla, te ja teidän isänne, teidän kuninkaanne ja ruhtinaanne ja maan kansa, Herra muista ja pidä mielessänsä?'),
(1688996,58,24,44,22,'Eikä Herra voinut sitä enää kärsiä teidän tekojenne pahuuden tähden, kauhistusten tähden, joita te teitte, ja niin teidän maanne tuli raunioiksi ja autioksi ja kiroussanaksi, tuli asujattomaksi, niinkuin se tänä päivänä on.'),
(1688997,58,24,44,23,'Sentähden että te poltitte uhreja ja teitte syntiä Herraa vastaan, ette totelleet Herran ääntä ettekä vaeltaneet hänen lakinsa, käskyjensä ja säädöksiensä mukaan, sentähden tämä onnettomuus on kohdannut teitä, niinkuin nyt on tapahtunut."'),
(1688998,58,24,44,24,'Jeremia sanoi vielä kaikelle kansalle ja kaikille naisille: "Kuulkaa Herran sana, kaikki Juuda, joka olet Egyptin maassa.'),
(1688999,58,24,44,25,'Näin sanoo Herra Sebaot, Israelin Jumala: Mitä te ja teidän vaimonne olette suullanne puhuneet, sen te panette käsillänne täytäntöön, sanoen: ''Me täytämme lupauksemme, joilla olemme luvanneet polttaa uhreja taivaan kuningattarelle ja vuodattaa hänelle juomauhreja''. Niinpä pitäkää lupauksenne, pankaa lupauksenne täytäntöön!'),
(1689000,58,24,44,26,'Sentähden kuulkaa Herran sana, kaikki Juuda, te jotka asutte Egyptin maassa: Katso, minä vannon suuren nimeni kautta, sanoo Herra: Totisesti, ei ole ainoakaan Juudan mies enää mainitseva suullaan minun nimeäni, niin että sanoisi: ''Niin totta kuin Herra, Herra elää'' - ei koko Egyptin maassa.'),
(1689001,58,24,44,27,'Katso, minä valvon, mutta heille onnettomuudeksi, ei onneksi; ja jokainen Juudan mies, joka on Egyptin maassa, on hukkuva miekkaan ja nälkään, kunnes heistä on tullut loppu.'),
(1689002,58,24,44,28,'Vain vähäinen joukko miekasta pelastuneita on palajava Egyptin maasta Juudan maahan; ja Juudan koko jäännös, ne jotka tulivat Egyptin maahan, siellä muukalaisina asumaan, tulevat tietämään, kumpaisenko sana toteutuu, minun vai heidän.'),
(1689003,58,24,44,29,'Ja tämä on oleva sen merkkinä, sanoo Herra, että minä rankaisen teitä tässä paikassa, tietääksenne, että minun sanani teitä vastaan toteutuvat, teille onnettomuudeksi:'),
(1689004,58,24,44,30,'Näin sanoo Herra: Katso, minä annan farao Hofran, Egyptin kuninkaan, hänen vihollistensa käsiin, niiden käsiin, jotka etsivät hänen henkeänsä, niinkuin minä olen antanut Sidkian, Juudan kuninkaan, Nebukadressarin, Baabelin kuninkaan, käsiin, joka oli hänen vihollisensa ja etsi hänen henkeänsä."'),
(1689005,58,24,45,1,'Sana, jonka profeetta Jeremia puhui Baarukille, Neerian pojalle, kun tämä kirjoitti nämä sanat kirjaan Jeremian suusta Juudan kuninkaan Joojakimin, Joosian pojan, neljäntenä hallitusvuotena; se kuului:'),
(1689006,58,24,45,2,'"Näin sanoo Herra, Israelin Jumala, sinusta, Baaruk:'),
(1689007,58,24,45,3,'Sinä sanot: ''Voi minua! Sillä Herra on antanut minulle murhetta kipuni lisäksi; minä olen uupunut huokaamisestani enkä lepoa löydä''.'),
(1689008,58,24,45,4,'Sano hänelle näin: Näin sanoo Herra: Katso, minkä olen rakentanut, sen minä hajotan, ja minkä olen istuttanut, sen minä revin irti; ja tämä kohtaa koko maata.'),
(1689009,58,24,45,5,'Sinä pyydät itsellesi suuria! Älä pyydä; sillä katso, minä tuotan onnettomuuden kaikelle lihalle, sanoo Herra. Mutta sinulle minä annan henkesi saaliiksi, mihin paikkaan sinä menetkin."'),
(1689010,58,24,46,1,'Herran sana, joka tuli profeetta Jeremialle pakanakansoja vastaan.'),
(1689011,58,24,46,2,'Egyptiä vastaan: Farao Nekon, Egyptin kuninkaan, sotajoukkoa vastaan, joka oli Eufrat-virran rannalla Karkemiissa ja jonka Nebukadressar, Baabelin kuningas, voitti Juudan kuninkaan Joojakimin, Joosian pojan, neljäntenä hallitusvuotena.'),
(1689012,58,24,46,3,'"Varustakaa pienet ja suuret kilvet, käykää tänne taisteluun.'),
(1689013,58,24,46,4,'Valjastakaa hevoset, nouskaa ratsujen selkään, käykää esiin kypärit päässä. Kiilloittakaa keihäät, pukekaa yllenne rintahaarniskat.'),
(1689014,58,24,46,5,'Miksi minä näen heidän peljästyvän, peräytyvän? Heidän sankarinsa sortuvat. He syöksyvät pakoon eivätkä käänny; kauhistus on kaikkialla, sanoo Herra.'),
(1689015,58,24,46,6,'Ei pääse nopea pakoon, ei sankari pelastu; pohjan puolella, Eufrat-virran vierellä he kompastuvat ja kaatuvat.'),
(1689016,58,24,46,7,'Kuka on tuo, joka nousee niinkuin Niilivirta, jonka vedet vyöryvät kuin virrat?'),
(1689017,58,24,46,8,'Egypti nousee niinkuin Niilivirta, sen vedet vyöryvät kuin virrat; se sanoo: ''Minä nousen ja peitän maan, hävitän kaupungin ja siinä asuvaiset''.'),
(1689018,58,24,46,9,'Hyökätkää, hevoset, ajakaa hurjasti, vaunut! Lähtekööt liikkeelle sankarit, etiopialaiset ja puutilaiset, kilven käyttäjät, ja luudilaiset, jousen käyttäjät, jousen jännittäjät!'),
(1689019,58,24,46,10,'Tämä päivä on Herran, Herran Sebaotin, päivä, koston päivä, jona hän kostaa vihollisillensa; miekka syö ja tulee kylläiseksi, juopuu heidän verestänsä, kun Herralla, Herralla Sebaotilla, on uhriteurastus pohjoisessa maassa, Eufrat-virran varrella.'),
(1689020,58,24,46,11,'Mene Gileadiin, hae balsamia, sinä neitsyt, tytär Egypti - turhaan sinä paljon lääkkeitä hankit: ei kasva haavasi umpeen.'),
(1689021,58,24,46,12,'Kansat kuulevat sinun häpeäsi, ja sinun valitushuutosi täyttää maan, sillä sankari kompastuu sankariin, yhdessä he kaatuvat molemmat."'),
(1689022,58,24,46,13,'Tämä on se sana, jonka Herra puhui profeetta Jeremialle, ilmoittaen Nebukadressarin, Baabelin kuninkaan, tulevan lyömään Egyptin maata.'),
(1689023,58,24,46,14,'"Julistakaa Egyptissä ja kuuluttakaa Migdolissa, kuuluttakaa Noofissa ja Tahpanheessa, ja sanokaa: ''Astu esiin, ole valmis, sillä miekka syö sinun ympärilläsi''.'),
(1689024,58,24,46,15,'Miksi ovat sinun urhosi maahan syöstyt? He eivät pysyneet pystyssä, sillä Herra heidät nujersi.'),
(1689025,58,24,46,16,'Hän saattoi monet kompastumaan, ja he kaatuivat toinen toisensa päälle ja sanoivat: ''Nouse! Palatkaamme kansamme luo ja synnyinmaahamme hävittäjän miekkaa pakoon.''');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689026,58,24,46,17,'Siellä huudetaan: ''Farao, Egyptin kuningas, on hukassa! Hän on lyönyt laimin aikansa.'''),
(1689027,58,24,46,18,'Niin totta kuin minä elän, sanoo kuningas - Herra Sebaot on hänen nimensä: hän tulee, hän joka on kuin Taabor vuorten joukossa, kuin merestä ylenevä Karmel.'),
(1689028,58,24,46,19,'Tee itsellesi matkavarusteet, sinä valtiatar, tytär Egypti; sillä Noof tulee autioksi, hävitetään asujattomaksi.'),
(1689029,58,24,46,20,'Kaunis hieho on Egypti. Paarma tulee, tulee pohjoisesta!'),
(1689030,58,24,46,21,'Palkkasoturitkin, jotka sillä on keskellänsä, nuo syöttövasikkain kaltaiset, nekin kääntyvät pakoon kaikki tyynni: he eivät kestä; sillä heidän hätänsä päivä on tullut heidän päällensä, heidän rangaistuksensa aika.'),
(1689031,58,24,46,22,'Se sähisee kuin käärme mennessänsä, sillä ne tulevat sotavoimilla ja käyvät sen kimppuun kirveillä, niinkuin puiden hakkaajat.'),
(1689032,58,24,46,23,'He kaatavat siltä metsän, sanoo Herra, tuon määrättömän suuren, sillä heitä on enemmän kuin heinäsirkkoja, he ovat lukemattomat.'),
(1689033,58,24,46,24,'Häpeään joutuu tytär Egypti, hänet annetaan pohjoisen kansan käsiin.'),
(1689034,58,24,46,25,'Herra Sebaot, Israelin Jumala, sanoo: Katso, minä rankaisen Aamonia, joka on Noossa, niin myös faraota ja Egyptiä, sen jumalia ja sen kuninkaita, sekä faraota että niitä, jotka häneen turvaavat.'),
(1689035,58,24,46,26,'Ja minä annan heidät niiden käsiin, jotka etsivät heidän henkeänsä, Nebukadressarin, Baabelin kuninkaan, käsiin ja hänen palvelijainsa käsiin. Mutta sen jälkeen siellä asutaan niinkuin muinaisina aikoina, sanoo Herra.'),
(1689036,58,24,46,27,'Mutta sinä, minun palvelijani Jaakob, älä pelkää, älä säiky, Israel. Sillä katso, minä pelastan sinut kaukaisesta maasta, sinun jälkeläisesi heidän vankeutensa maasta. Ja Jaakob on palajava, elävä rauhassa ja turvassa, kenenkään peljättämättä.'),
(1689037,58,24,46,28,'Sinä, minun palvelijani Jaakob, älä pelkää, sanoo Herra, sillä minä olen sinun kanssasi. Minä teen lopun kaikista kansoista, joiden sekaan minä olen sinut karkoittanut; mutta sinusta minä en loppua tee: minä kuritan sinua kohtuudella, mutta rankaisematta minä en sinua jätä."'),
(1689038,58,24,47,1,'Herran sana filistealaisia vastaan, joka tuli profeetta Jeremialle, ennenkuin farao valloitti Gassan:'),
(1689039,58,24,47,2,'"Näin sanoo Herra: Katso, vedet nousevat pohjoisesta, ja niistä tulee tulvavirta; ne tulvivat yli maan ja kaiken, mitä siinä on, yli kaupungin ja siinä asuvaisten. Ja ihmiset huutavat, kaikki maan asukkaat valittavat.'),
(1689040,58,24,47,3,'Kun kuuluu hänen orhiensa kavioitten töminä, hänen vaunujensa jyrinä, hänen rattaittensa ryske, eivät isät käänny lapsiansa auttamaan, sillä hervottomat ovat heidän kätensä'),
(1689041,58,24,47,4,'päivän tähden, joka tulee ja tuhoaa kaikki filistealaiset, hävittää Tyyrolta ja Siidonilta kaikki auttajat, mitä jäljellä on; sillä Herra on tuhoava filistealaiset, mitä on tähteenä Kaftorin saarelta tulleista.'),
(1689042,58,24,47,5,'Kaljuksi tullut on Gassa, hävitetty on Askelon, se mitä oli jäljellä heidän laaksossansa. Kuinka kauan sinä ihoasi viileskelet?'),
(1689043,58,24,47,6,'Voi, Herran miekka! Milloinka vihdoinkin lepäät? Mene takaisin tuppeesi, taltu ja ole hiljaa.'),
(1689044,58,24,47,7,'Mutta kuinka saisi se levätä, kun Herra on sille käskyn antanut? Askelonia ja meren rantaa vastaan hän on sen asettanut."'),
(1689045,58,24,48,1,'Mooabia vastaan. Näin sanoo Herra Sebaot, Israelin Jumala: "Voi Neboa, sillä se on hävitetty! Häpeään joutunut, valloitettu on Kirjataim, häpeään joutunut, kauhistunut on linnoitus.'),
(1689046,58,24,48,2,'Mennyt on Mooabin maine, Hesbonissa hankitaan sille pahaa: ''Tulkaa, hävittäkäämme se kansojen luvusta''. Myöskin sinä, Madmena, kukistut, miekka on sinun kintereilläsi.'),
(1689047,58,24,48,3,'Kuule! Huuto Hooronaimista! Tuho ja suuri hävitys!'),
(1689048,58,24,48,4,'Hävitetty on Mooab, sen pienokaisten parku kuuluu.'),
(1689049,58,24,48,5,'Luuhitin solatietä noustaan itkien, Hooronaimin rinteeltä kuuluu tuskan huuto hävityksen tähden.'),
(1689050,58,24,48,6,'Paetkaa, pelastakaa henkenne ja olkaa kuin alaston puu erämaassa.'),
(1689051,58,24,48,7,'Sillä koska sinä turvaat omiin töihisi ja aarteisiisi, niin sinutkin valloitetaan, ja Kemos lähtee pakkosiirtolaisuuteen ja hänen pappinsa ja ruhtinaansa hänen kanssaan.'),
(1689052,58,24,48,8,'Hävittäjä tulee jokaiseen kaupunkiin, ei pelastu yksikään kaupunki; laakso hävitetään ja tasanko tuhotaan, niinkuin Herra on puhunut.'),
(1689053,58,24,48,9,'Antakaa siivet Mooabille, sillä lentämällä on hänen lähdettävä pois. Hänen kaupunkinsa tulevat autioiksi, niin ettei niissä yhtään asukasta ole.'),
(1689054,58,24,48,10,'Kirottu olkoon se, joka Herran työn laiskasti tekee, kirottu olkoon se, joka pidättää miekkansa verestä.'),
(1689055,58,24,48,11,'Surutonna on Mooab ollut nuoruudestaan asti ja levännyt rauhassa sakkansa päällä; ei sitä ole tyhjennetty astiasta astiaan, eikä se ole pakkosiirtolaisuuteen vaeltanut. Sentähden siihen on jäänyt sen oma maku, eikä sen haju ole muuttunut.'),
(1689056,58,24,48,12,'Sentähden, katso, päivät tulevat, sanoo Herra, jolloin minä lähetän sille viininlaskijat, jotka sen laskevat ja tyhjentävät sen astiat ja rikkovat sen leilit.'),
(1689057,58,24,48,13,'Ja Mooab joutuu häpeään Kemoksen tähden, niinkuin Israelin heimo joutui häpeään Beetelin tähden, johon se turvasi.'),
(1689058,58,24,48,14,'Kuinka te sanotte: ''Me olemme sankareita ja aimomiehiä taisteluun''?'),
(1689059,58,24,48,15,'Mooab hävitetään, sen kaupunkeihin hyökätään, ja sen valionuorukaiset vaipuvat teurastettaviksi, sanoo kuningas - Herra Sebaot on hänen nimensä.'),
(1689060,58,24,48,16,'Lähellä, tulossa on Mooabin turmio, sen onnettomuus kiiruhtaa kovin.'),
(1689061,58,24,48,17,'Surkutelkaa sitä, kaikki sen naapurit, kaikki, jotka tunnette sen nimen. Sanokaa: ''Voi, kuinka onkaan murrettu voiman valtikka, kunnian sauva!'''),
(1689062,58,24,48,18,'Astu alas kunniasta ja istu janoiseen erämaahan, sinä valtiatar, tytär Diibon; sillä Mooabin hävittäjä hyökkää sinun kimppuusi, kukistaa sinun linnoituksesi.'),
(1689063,58,24,48,19,'Seiso tiellä ja tähystele, sinä Aroerin asukas; kysy pakolaisilta ja pelastuneilta, sano: ''Mitä on tapahtunut?'''),
(1689064,58,24,48,20,'Häpeään on joutunut Mooab, sillä se on kukistettu. Valittakaa ja huutakaa, julistakaa Arnonin äyräillä, että Mooab on hävitetty.'),
(1689065,58,24,48,21,'Tuomio on tullut tasangon maalle, Hoolonille, Jahaalle ja Meefaatille,'),
(1689066,58,24,48,22,'Diibonille, Nebolle ja Beet-Diblataimille,'),
(1689067,58,24,48,23,'Kirjataimille, Beet-Gaamulille ja Beet-Meonille,'),
(1689068,58,24,48,24,'Kerijotille, Bosralle ja kaikille Mooabin maan kaupungeille, kaukaisille ja läheisille.'),
(1689069,58,24,48,25,'Katkaistu on Mooabin sarvi ja murskattu hänen käsivartensa, sanoo Herra.'),
(1689070,58,24,48,26,'Juovuttakaa hänet, sillä hän on ylpeillyt Herraa vastaan, niin että Mooab suistuu omaan oksennukseensa ja tulee nauruksi hänkin.'),
(1689071,58,24,48,27,'Vai eikö Israel ollut sinulle nauruksi? Onko hänet tavattu varasten joukosta, koska sinä, milloin vain hänestä puhuit, pudistit päätäsi?'),
(1689072,58,24,48,28,'Jättäkää kaupungit ja asukaa kallioilla, te Mooabin asukkaat, ja olkaa kuin kyyhkynen, joka tekee pesänsä ammottavan kuilun taakse.'),
(1689073,58,24,48,29,'Me olemme kuulleet Mooabin ylpeilyn, tuon ylen ylpeän, hänen korskeutensa, ylpeilynsä ja kopeilunsa ja hänen sydämensä pöyhkeyden.'),
(1689074,58,24,48,30,'Minä tunnen, sanoo Herra, hänen vihansa ja hänen väärät puheensa; väärin he ovat tehneet.'),
(1689075,58,24,48,31,'Siksi minä valitan Mooabin tähden, koko Mooabin tähden minä huudan; Kiir-Hereksen miesten tähden huokaillaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689076,58,24,48,32,'Enemmän kuin Jaeser itkee, itken minä sinua, Sibman viinipuu; sinun köynnöksesi menivät yli meren, ulottuivat Jaeserin mereen asti. Sinun hedelmän- ja viininkorjuusi keskeen on hävittäjä hyökännyt.'),
(1689077,58,24,48,33,'Ilo ja riemu on tauonnut hedelmätarhoista ja Mooabin maasta. Viinin minä olen lopettanut viinikuurnista; ei poljeta enää viiniä ilohuudoin, ilohuuto ei ole enää ilohuuto.'),
(1689078,58,24,48,34,'Hesbonin parku kuuluu Elaleen, Jahaaseen asti, he antavat äänensä kuulua Sooarista Hooronaimiin, Eglat-Selisijjaan asti, sillä Nimrimin vedet ehtyvät erämaaksi.'),
(1689079,58,24,48,35,'Minä lopetan Mooabista, sanoo Herra, kukkuloilla-uhraajat, ne, jotka polttavat uhreja jumalillensa.'),
(1689080,58,24,48,36,'Siksi minun sydämeni väräjää Mooabin tähden niinkuin huilu, minun sydämeni väräjää Kiir-Hereksen miesten tähden niinkuin huilu, sillä mennyttä on heidän hankkimansa säästö.'),
(1689081,58,24,48,37,'Kaikki päät ovat paljaiksi ajellut ja kaikki parrat leikatut, kaikki kädet viileskellyt, ja lanteilla on säkit.'),
(1689082,58,24,48,38,'Kaikilla Mooabin katoilla ja toreilla on pelkkää valitusta, sillä minä olen murskannut Mooabin kuin kelpaamattoman astian, sanoo Herra.'),
(1689083,58,24,48,39,'Kuinka se on kauhuissansa! Valittakaa! Kuinka Mooab kääntyikään selin ja häpesi! Mooab on tullut nauruksi ja kauhuksi kaikille naapureilleen.'),
(1689084,58,24,48,40,'Sillä näin sanoo Herra: Katso, kotkan kaltainen liitää siivet levällään Mooabia kohti.'),
(1689085,58,24,48,41,'Kerijot valloitetaan ja vuorilinnoitukset vallataan; sinä päivänä on Mooabin sankarien sydän niinkuin synnytystuskissa olevan vaimon sydän.'),
(1689086,58,24,48,42,'Ja Mooab hävitetään kansojen luvusta, sillä se on ylpeillyt Herraa vastaan.'),
(1689087,58,24,48,43,'Kauhu ja kuoppa ja paula on edessäsi, sinä Mooabin asukas, sanoo Herra.'),
(1689088,58,24,48,44,'Joka pakenee kauhua, se putoaa kuoppaan, ja joka kuopasta nousee, se puuttuu paulaan; sillä minä tuotan Mooabille heidän rangaistusvuotensa, sanoo Herra.'),
(1689089,58,24,48,45,'Hesbonin varjossa seisovat pakolaiset voimaa vailla. Sillä tuli lähti Hesbonista, liekki Siihonin vaiheilta; ja se kulutti Mooabin ohimon ja melskeen miesten päälaen.'),
(1689090,58,24,48,46,'Voi sinua, Mooab! Hukkunut on Kemoksen kansa, sillä sinun poikasi ovat vangeiksi otetut ja tyttäresi viedyt vankeuteen.'),
(1689091,58,24,48,47,'Mutta minä käännän Mooabin kohtalon aikojen lopulla, sanoo Herra." Tähän asti Mooabin tuomiosta.'),
(1689092,58,24,49,1,'Ammonilaisia vastaan. Näin sanoo Herra: "Eikö Israelilla olekaan lapsia, tahi eikö hänellä ole perillistä? Miksi Malkam on perinyt Gaadin ja hänen kansansa asettunut sen kaupunkeihin?'),
(1689093,58,24,49,2,'Sentähden, katso, päivät tulevat, sanoo Herra, jolloin minä annan sotahuudon kuulua ammonilaisten Rabbaa vastaan, ja siitä on tuleva rauniokumpu, autio, ja sen tytärkaupungit tulessa palavat. Silloin Israel on perivä perijänsä, sanoo Herra.'),
(1689094,58,24,49,3,'Valita, Hesbon, sillä Ai on hävitetty; huutakaa, te Rabban tyttäret, kääriytykää säkkeihin, pitäkää valittajaiset ja harhailkaa ympäri karjatarhoissa, sillä Malkam menee pakkosiirtolaisuuteen ja hänen pappinsa ja ruhtinaansa hänen kanssaan.'),
(1689095,58,24,49,4,'Miksi kerskaat laaksoistasi, laaksosi yltäkylläisyydestä, sinä luopiotytär, joka luotat aarteisiisi sanoen: ''Kuka käy minun kimppuuni?'''),
(1689096,58,24,49,5,'Katso, minä tuotan sinulle peljätyksen joka taholta, sanoo Herra, Herra Sebaot, ja teidät karkoitetaan, mikä minnekin, eikä ole pakenevilla kokoajaa.'),
(1689097,58,24,49,6,'Mutta sen jälkeen minä käännän ammonilaisten kohtalon, sanoo Herra."'),
(1689098,58,24,49,7,'Edomia vastaan. Näin sanoo Herra Sebaot: "Eikö ole enää viisautta Teemanissa? Loppunut on ymmärtäväisiltä neuvo, rauennut heidän viisautensa.'),
(1689099,58,24,49,8,'Paetkaa, kääntykää, piiloutukaa syvälle, te Dedanin asukkaat; sillä minä tuotan Eesaulle turmion, hänen rangaistuksensa ajan.'),
(1689100,58,24,49,9,'Jos viininkorjaajat käyvät kimppuusi, eivät he jälkikorjuuta jätä; jos varkaat tulevat yöllä, hävittävät he tarpeeksensa.'),
(1689101,58,24,49,10,'Sillä minä paljastan Eesaun, tuon ilmi hänen kätkönsä, eikä hän voi lymytä; hänen lapsensa, veljensä ja naapurinsa hävitetään, niin ettei häntä enää ole.'),
(1689102,58,24,49,11,'Jätä orposi minun elätettävikseni, ja sinun leskesi turvatkoot minuun.'),
(1689103,58,24,49,12,'Sillä näin sanoo Herra: Katso, niidenkin, jotka eivät ole vikapäät siitä maljasta juomaan, täytyy siitä juoda; ja sinäkö jäisit rankaisematta? Sinä et jää rankaisematta, vaan sinun täytyy juoda.'),
(1689104,58,24,49,13,'Sillä minä olen vannonut itse kauttani, sanoo Herra, että Bosra on tuleva kauhistukseksi, häpeäksi, tyrmistykseksi ja kiroussanaksi, ja kaikki sen tytärkaupungit tulevat ikuisiksi raunioiksi."'),
(1689105,58,24,49,14,'Minä olen kuullut sanoman Herralta, ja sanansaattaja on lähetetty kansakuntiin: "Kokoontukaa ja käykää sitä vastaan ja nouskaa sotaan". -'),
(1689106,58,24,49,15,'"Sillä katso, minä teen sinut vähäiseksi kansojen seassa, ylenkatsotuksi ihmisten kesken.'),
(1689107,58,24,49,16,'Sinun peljättävyytesi, sinun sydämesi ylpeys on pettänyt sinut, joka asut kallionrotkoissa, vallitset kukkulain korkeudet. Vaikka tekisit pesäsi korkealle niinkuin kotka, minä syöksen sinut sieltä alas, sanoo Herra.'),
(1689108,58,24,49,17,'Ja Edom tulee kauhistukseksi; jokainen, joka ohitse kulkee, kauhistuu ja viheltää kaikille sen haavoille.'),
(1689109,58,24,49,18,'Niinkuin oli silloin, kun Sodoma ja Gomorra ja niiden naapurit hävitettiin, sanoo Herra, niin ei sielläkään ole kenkään asuva, ei yksikään ihmislapsi oleskeleva.'),
(1689110,58,24,49,19,'Katso, niinkuin leijona karkaa Jordanin rantatiheiköstä lakastumattomalle laitumelle, niin minä äkisti karkoitan heidät sieltä pois. Ja hänet, joka valittu on, minä asetan sinne kaitsijaksi. Sillä kuka on minun vertaiseni, ja kuka vetää minut tilille? Ja kuka on se paimen, joka voi kestää minun edessäni?'),
(1689111,58,24,49,20,'Sentähden kuulkaa Herran päätös, jonka hän on päättänyt Edomia vastaan, ja hänen aivoituksensa, jotka hän on aivoitellut Teemanin asukkaita vastaan: Totisesti, ne raastetaan pois, nuo lauman vähäiset; totisesti, niiden laidun kauhistuu niiden tähden.'),
(1689112,58,24,49,21,'Heidän sortumisensa pauhusta vapisee maa; huudetaan, niin että ääni kuuluu Kaislamerelle asti.'),
(1689113,58,24,49,22,'Katso, kotkan kaltainen kohoaa ja liitää siivet levällään Bosraa kohti; sinä päivänä on Edomin sankarien sydän niinkuin synnytystuskissa olevan vaimon sydän."'),
(1689114,58,24,49,23,'Damaskoa vastaan. "Hamat ja Arpad joutuvat häpeään, sillä he kuulevat pahan sanoman, he menehtyvät pelkoon - levottomuus kuin meressä, joka ei voi tyyntyä!'),
(1689115,58,24,49,24,'Damasko lannistuu, kääntyy pakoon, hirmu on sen vallannut; sitä kouristaa ahdistus ja tuska niinkuin synnyttäväistä!'),
(1689116,58,24,49,25,'Kuinka hyljätty onkaan ylistetty kaupunki, minun iloni kaupunki!'),
(1689117,58,24,49,26,'Sentähden sen nuorukaiset kaatuvat sen kaduilla, ja kaikki sotamiehet saavat surmansa sinä päivänä, sanoo Herra Sebaot.'),
(1689118,58,24,49,27,'Ja minä sytytän Damaskon muurit tuleen, ja se on kuluttava Benhadadin palatsit."'),
(1689119,58,24,49,28,'Keedaria ja Haasorin valtakuntia vastaan, jotka Nebukadressar, Baabelin kuningas, voitti. Näin sanoo Herra: "Nouskaa, käykää Keedarin kimppuun ja hävittäkää Idän miehet.'),
(1689120,58,24,49,29,'Heidän majansa ja lampaansa otetaan pois, heidän telttansa ja kaikki heidän tavaransa ja heidän kamelinsa viedään heiltä, ja heistä huudetaan: ''Kauhistus kaikkialta!'''),
(1689121,58,24,49,30,'Lähtekää pakoon, paetkaa nopeasti, piiloutukaa syvälle, te Haasorin asukkaat, sanoo Herra, sillä Nebukadressar, Baabelin kuningas, on päättänyt teistä päätöksen, on pitänyt neuvoa teitä vastaan.'),
(1689122,58,24,49,31,'Nouskaa, käykää kansan kimppuun, joka asuu rauhassa ja turvallisena, sanoo Herra; ei ole sillä ovia eikä salpoja, he asuvat yksinänsä.'),
(1689123,58,24,49,32,'Ja heidän kamelinsa joutuvat ryöstettäviksi ja heidän karjansa paljous saaliiksi; ja minä hajotan heidät kaikkiin tuuliin, nuo päälaen ympäriltä kerityt, ja joka puolelta minä tuotan heille turmion, sanoo Herra.'),
(1689124,58,24,49,33,'Ja Haasor tulee aavikkosutten asunnoksi, autioksi iankaikkisesti; ei kenkään ole siellä asuva, ei yksikään ihmislapsi siellä oleskeleva."'),
(1689125,58,24,49,34,'Herran sana, joka tuli profeetta Jeremialle Eelamia vastaan Juudan kuninkaan Sidkian hallituksen alussa; se kuului:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689126,58,24,49,35,'"Näin sanoo Herra Sebaot: Katso, minä murran Eelamin jousen, heidän väkevyytensä parhaimmat.'),
(1689127,58,24,49,36,'Ja minä tuotan Eelamia vastaan neljä tuulta taivaan neljältä ääreltä ja hajotan heidät kaikkiin näihin tuuliin; eikä ole oleva kansaa, johon ei tulisi Eelamin karkoitettuja.'),
(1689128,58,24,49,37,'Ja minä saatan Eelamin kauhistumaan vihollistensa edessä, niiden edessä, jotka etsivät heidän henkeänsä, ja minä annan onnettomuuden kohdata heitä, vihani hehkun, sanoo Herra, ja minä lähetän heidän jälkeensä miekan, kunnes minä heidät lopetan.'),
(1689129,58,24,49,38,'Ja minä asetan valtaistuimeni Eelamiin ja hävitän sieltä kuninkaan ja ruhtinaat, sanoo Herra.'),
(1689130,58,24,49,39,'Mutta aikojen lopulla minä käännän Eelamin kohtalon, sanoo Herra."'),
(1689131,58,24,50,1,'Sana, jonka Herra puhui Baabelia vastaan, kaldealaisten maata vastaan, profeetta Jeremian kautta.'),
(1689132,58,24,50,2,'"Julistakaa kansojen keskuudessa ja kuuluttakaa, nostakaa lippu; kuuluttakaa, älkää salatko. Sanokaa: Baabel on valloitettu, Beel on joutunut häpeään, kauhistunut on Merodak; sen jumalankuvat ovat joutuneet häpeään, kauhistuneet ovat sen kivijumalat.'),
(1689133,58,24,50,3,'Sillä sen kimppuun käy kansa pohjoisesta ja tekee sen maan autioksi, niin ettei siellä asukasta ole: niin ihmiset kuin eläimet pakenevat, menevät pois.'),
(1689134,58,24,50,4,'Niinä päivinä ja siihen aikaan, sanoo Herra, tulevat israelilaiset yhdessä Juudan miesten kanssa; he kulkevat itkien lakkaamatta ja etsivät Herraa, Jumalaansa.'),
(1689135,58,24,50,5,'Siionia he kysyvät, sitä kohden ovat heidän kasvonsa käännetyt. Tulkaa! He liittyvät Herran kanssa iankaikkiseen liittoon, jota ei pidä unhotettaman.'),
(1689136,58,24,50,6,'Kadonnut lammaslauma oli minun kansani. Heidän paimenensa olivat vieneet heidät harhaan eksyttäville vuorille; he kulkivat vuorelta kukkulalle, unhottivat lepopaikkansa.'),
(1689137,58,24,50,7,'Kaikki, jotka heitä tapasivat, söivät heitä, ja heidän vihollisensa sanoivat: ''Emme joudu syynalaisiksi''. Sillä he olivat tehneet syntiä Herraa vastaan, vanhurskauden asumusta, Herraa, heidän isiensä toivoa, vastaan.'),
(1689138,58,24,50,8,'Paetkaa Baabelista, lähtekää pois kaldealaisten maasta, ja käykää kuin johtokauriit lauman edellä.'),
(1689139,58,24,50,9,'Sillä katso, minä herätän ja tuon Baabelia vastaan suurten kansojen joukon pohjoisesta maasta, ja ne asettuvat sotarintaan sitä vastaan. Sieltäkäsin se valloitetaan; heidän nuolensa ovat kuin voitollisen sankarin, joka ei tyhjänä palaja.'),
(1689140,58,24,50,10,'Ja Kaldea joutuu ryöstettäväksi, kaikki sen ryöstäjät saavat yltäkyllin, sanoo Herra.'),
(1689141,58,24,50,11,'Iloitkaa vain, riemuitkaa vain, te minun perintöosani riistäjät, hypelkää kuin puiva hieho, ja hirnukaa kuin orhit:'),
(1689142,58,24,50,12,'kuitenkin joutuu äitinne suureen häpeään, synnyttäjänne saa hävetä. Katso, pakanakansoista vihoviimeinen! Erämaa, kuiva maa ja aromaa!'),
(1689143,58,24,50,13,'Herran vihan tähden se on oleva asumaton, aivan autio. Jokainen, joka kulkee Baabelin ohitse, kauhistuu ja viheltää kaikille sen haavoille.'),
(1689144,58,24,50,14,'Asettukaa sotarintaan Baabelia vastaan, yltympäri, kaikki jousenjännittäjät. Ampukaa sitä, älkää nuolia säästäkö; sillä se on tehnyt syntiä Herraa vastaan.'),
(1689145,58,24,50,15,'Nostakaa sotahuuto sitä vastaan joka taholta. Se antautuu, sen pylväät kaatuvat, sen muurit sortuvat. Sillä tämä on Herran kosto. Kostakaa sille, tehkää sille, niinkuin sekin on tehnyt.'),
(1689146,58,24,50,16,'Tuhotkaa kylväjät Baabelista ja ne, jotka elonaikana sirppiin tarttuvat. Hävittäjän miekkaa pakoon he kääntyvät kukin oman kansansa tykö, pakenevat kukin omaan maahansa.'),
(1689147,58,24,50,17,'Eksynyt lammas on Israel, leijonat ovat sen eksyksiin saaneet. Ensiksi Assurin kuningas söi sen, ja nyt viimeksi Nebukadressar, Baabelin kuningas, kalusi sen luut.'),
(1689148,58,24,50,18,'Sentähden, näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä rankaisen Baabelin kuningasta ja hänen maatansa, niinkuin minä rankaisin Assurin kuningasta.'),
(1689149,58,24,50,19,'Ja minä tuon Israelin takaisin sen omille laidunmaille, ja se on käyvä laitumella Karmelilla ja Baasanissa ja tyydyttävä nälkänsä Efraimin vuorilla ja Gileadissa.'),
(1689150,58,24,50,20,'Niinä päivinä ja siihen aikaan, sanoo Herra, etsitään Israelin rikkomusta, eikä sitä enää ole, ja Juudan syntiä, eikä sitä löydetä; sillä minä annan anteeksi niille, jotka minä jäännökseksi jätän.'),
(1689151,58,24,50,21,'Käy Merataimin maan kimppuun ja Pekodin asukasten kimppuun. Aja heitä takaa, hävitä, vihi tuhon omaksi heidät, sanoo Herra, ja tee kaikki, mitä minä olen käskenyt sinun tehdä.'),
(1689152,58,24,50,22,'Sotahuuto kuuluu maassa, suuri hävityksen melske!'),
(1689153,58,24,50,23,'Kuinka rikottu ja särjetty onkaan se vasara, joka löi koko maanpiiriä! Kuinka onkaan Baabel tullut kauhistukseksi kansojen seassa!'),
(1689154,58,24,50,24,'Minä viritin sinulle pyydyksen, ja niin sinut, Baabel, vangittiin tietämättäsi. Sinut tavattiin ja otettiin kiinni, sillä Herraa vastaan sinä ryhdyit taisteluun.'),
(1689155,58,24,50,25,'Herra avasi asehuoneensa ja toi ulos vihansa aseet. Sillä Herra, Herra Sebaot, on tekevä työnsä kaldealaisten maassa.'),
(1689156,58,24,50,26,'Käykää sen kimppuun kaikilta ääriltä, avatkaa sen aitat, heittäkää ulos, mitä siinä on, läjään niinkuin lyhteet. Vihkikää se tuhon omaksi, älköön siitä tähdettä jääkö.'),
(1689157,58,24,50,27,'Hävittäkää kaikki sen härät, astukoot ne teurastettaviksi. Voi heitä! Sillä heidän päivänsä on tullut, heidän rangaistuksensa aika.'),
(1689158,58,24,50,28,'Kuule! Pakenevia ja pakolaisia tulee Baabelin maasta Siioniin ilmoittamaan Herran, meidän Jumalamme, kostoa, kostoa Hänen temppelinsä puolesta.'),
(1689159,58,24,50,29,'Kutsukaa ampujat kokoon Baabelia vastaan, kaikki jousenjännittäjät: leiriytykää sen ympärille, älköön pääskö pakoon ainoakaan. Maksakaa sille sen tekojen mukaan; kaiken sen mukaan, mitä se on tehnyt, tehkää sillekin. Sillä se on uhitellut Herraa, Israelin Pyhää.'),
(1689160,58,24,50,30,'Sentähden sen nuorukaiset kaatuvat sen kaduilla, ja kaikki sotamiehet saavat surmansa sinä päivänä, sanoo Herra.'),
(1689161,58,24,50,31,'Katso, minä käyn sinun kimppuusi, sinä ylpeä, sanoo Herra, Herra Sebaot, sillä sinun päiväsi on tullut, sinun rangaistuksesi aika.'),
(1689162,58,24,50,32,'Ylpeä kompastuu ja kaatuu, eikä ole hänen nostajaansa. Ja minä sytytän hänen kaupunkinsa tuleen, ja se kuluttaa ne ja kaiken, mitä hänen ympärillänsä on.'),
(1689163,58,24,50,33,'Näin sanoo Herra Sebaot: Sorrettuja ovat niin israelilaiset kuin Juudan miehet, ja kaikki heidän vangitsijansa pitävät heitä kiinni, he eivät tahdo päästää heitä irti.'),
(1689164,58,24,50,34,'Mutta heidän lunastajansa on väkevä, Herra Sebaot on hänen nimensä. Hän ajaa heidän asiansa, tuo rauhan maan päälle, mutta Baabelin asukkaille vavistuksen.'),
(1689165,58,24,50,35,'Miekka kaldealaisten kimppuun, sanoo Herra, ja Baabelin asukasten kimppuun, sen ruhtinasten ja tietäjäin kimppuun!'),
(1689166,58,24,50,36,'Miekka valhettelijain kimppuun, ja he typertyvät! Miekka sen sankarien kimppuun, ja he kauhistuvat!'),
(1689167,58,24,50,37,'Miekka sen hevosten ja vaunujen kimppuun ja kaiken sekakansan kimppuun, joka on sen keskellä, ja he muuttuvat naisiksi! Miekka sen aarteiden kimppuun, ja ne ryöstetään!'),
(1689168,58,24,50,38,'Helle sen vetten kimppuun, ja ne kuivuvat! Sillä se on jumalankuvien maa, ja hirmujumaliinsa he uskaltavat mielettömästi.'),
(1689169,58,24,50,39,'Sentähden tulevat sen asukkaiksi erämaan ulvojat ja ulisijat, ja kamelikurjet siellä asustavat. Ei sitä ikinä enää asuta, autioksi jää se polvesta polveen.'),
(1689170,58,24,50,40,'Niinkuin oli silloin, kun Jumala hävitti Sodoman ja Gomorran ja niiden naapurit, sanoo Herra, niin ei sielläkään ole kenkään asuva, ei yksikään ihmislapsi oleskeleva.'),
(1689171,58,24,50,41,'Katso, kansa tulee pohjoisesta; suuri kansa ja monet kuninkaat nousevat maan perimmäisiltä ääriltä.'),
(1689172,58,24,50,42,'He käyttävät jousta ja keihästä, ovat julmat ja armahtamattomat. Heidän pauhinansa on kuin pauhaava meri, ja he ratsastavat hevosilla, varustettuina kuin soturi taisteluun sinua vastaan, tytär Baabel.'),
(1689173,58,24,50,43,'Kun Baabelin kuningas kuulee sanoman heistä, niin hänen kätensä herpoavat; ahdistus valtaa hänet, tuska, niinkuin synnyttäväisen.'),
(1689174,58,24,50,44,'Katso, niinkuin leijona karkaa Jordanin rantatiheiköstä lakastumattomalle laitumelle, niin minä äkisti karkoitan heidät sieltä pois. Ja hänet, joka valittu on, minä asetan sinne kaitsijaksi. Sillä kuka on minun vertaiseni, ja kuka vetää minut tilille? Ja kuka on se paimen, joka voi kestää minun edessäni?'),
(1689175,58,24,50,45,'Sentähden kuulkaa Herran päätös, jonka hän on päättänyt Baabelia vastaan, ja hänen aivoituksensa, jotka hän on aivoitellut kaldealaisten maata vastaan: Totisesti, ne raastetaan pois, nuo lauman vähäiset; totisesti, laidun kauhistuu niiden tähden.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689176,58,24,50,46,'Huuto käy: ''Baabel on valloitettu!'' ja maa vapisee, parku kuuluu kansoissa."'),
(1689177,58,24,51,1,'Näin sanoo Herra: "Katso, minä herätän Baabelia vastaan, Leeb-Kaamain asukkaita vastaan hävittäjän hengen.'),
(1689178,58,24,51,2,'Ja minä lähetän Baabeliin muukalaisia, jotka hajottavat sen ja tyhjentävät sen maan, sillä joka taholta he tulevat sitä vastaan onnettomuuden päivänä.'),
(1689179,58,24,51,3,'Jousimies jännittäköön jousensa sitä vastaan, joka jousen jännittää, ja sitä vastaan, joka uljastelee rintahaarniskassaan. Älkää säälikö sen nuorukaisia, vihkikää tuhon omaksi koko sen sotajoukko.'),
(1689180,58,24,51,4,'Haavoitettuja kaatuu kaldealaisten maassa ja lävistettyjä sen kaduilla.'),
(1689181,58,24,51,5,'Sillä ei Israel eikä Juuda ole Jumalansa, Herran Sebaotin, hylkäämä, vaan noiden maa on täynnä syntivelkaa Israelin Pyhän edessä.'),
(1689182,58,24,51,6,'Paetkaa Baabelista ja pelastakoon kukin henkensä, älkää hukkuko sen syntiin. Sillä tämä on Herran koston aika, hän maksaa sille, mitä se on ansainnut.'),
(1689183,58,24,51,7,'Baabel oli Herran kädessä kultainen malja, joka juovutti kaiken maan. Sen viinistä joivat kansat; sentähden kansat tulivat mielettömiksi.'),
(1689184,58,24,51,8,'Äkisti on Baabel kaatunut ja murskaantunut. Valittakaa hänen tähtensä! Hakekaa balsamia hänen kipuunsa, ehkä hän paranee.'),
(1689185,58,24,51,9,'''Me olemme koettaneet parantaa Baabelia, mutta ei hän ole parantunut. Jättäkää hänet ja menkäämme pois, kukin omaan maahansa; sillä hänen tuomionsa ulottuu taivaaseen asti, kohoaa pilviin saakka.'),
(1689186,58,24,51,10,'Herra on tuonut ilmi meidän vanhurskautemme; tulkaa, julistakaamme Siionissa Herran, meidän Jumalamme, tekoja.'''),
(1689187,58,24,51,11,'Teroittakaa nuolet, täyttäkää viinet! Herra on herättänyt Meedian kuningasten hengen, sillä hänen ajatuksensa käy Baabelia vastaan, sen hävittämiseksi. Tämä on Herran kosto, kosto hänen temppelinsä puolesta.'),
(1689188,58,24,51,12,'Kohottakaa lippu Baabelin muureja vastaan, vahvistakaa vartiosto, asettakaa vartijat, valmistakaa väijytykset; sillä mitä Herra on ajatellut, sen hän tekeekin, sen minkä hän on puhunut Baabelin asukkaita vastaan.'),
(1689189,58,24,51,13,'Sinä, joka asut suurten vetten partailla, joka olet aarteista rikas, sinun loppusi on tullut, sinun väärän voittosi raja.'),
(1689190,58,24,51,14,'Herra Sebaot on vannonut itse kauttansa: Totisesti, minä täytän sinut ihmisillä niinkuin heinäsirkoilla, ja he virittävät sinusta viininkorjuulaulun.'),
(1689191,58,24,51,15,'Hän on tehnyt maan voimallansa, vahvistanut maanpiirin viisaudellansa ja levittänyt taivaat taidollansa.'),
(1689192,58,24,51,16,'Kun hän jylisee, käy vetten pauhina taivaalla, ja hän nostaa pilvet maan ääristä, tekee salamat ja sateen ja tuo tuulen sen säilytyspaikoista.'),
(1689193,58,24,51,17,'Järjetön on jokainen ihminen, tietoa vailla, häpeän saa jokainen kultaseppä veistetystä kuvasta, petosta on hänen valamansa kuva, eikä niissä henkeä ole.'),
(1689194,58,24,51,18,'Turhuutta ne ovat, naurettavia tekeleitä; kun niiden rangaistus tulee, ne hukkuvat.'),
(1689195,58,24,51,19,'Näiden kaltainen ei ole hän, joka on Jaakobin osa, sillä hän on kaiken luoja, ja Jaakob on hänen perintösukunsa: Herra Sebaot on hänen nimensä.'),
(1689196,58,24,51,20,'Sinä olit minun vasarani, minun sota-aseeni, sinulla minä musersin kansoja, sinulla minä hävitin valtakuntia.'),
(1689197,58,24,51,21,'Sinulla minä musersin hevosen ja ratsastajan, sinulla minä musersin vaunut ja ajajan.'),
(1689198,58,24,51,22,'Sinulla minä musersin miehen ja vaimon, sinulla minä musersin vanhan ja nuoren, sinulla minä musersin nuorukaisen ja neitosen.'),
(1689199,58,24,51,23,'Sinulla minä musersin paimenen ja hänen laumansa, sinulla minä musersin peltomiehen ja hänen juhtaparinsa, sinulla minä musersin käskynhaltijat ja päämiehet.'),
(1689200,58,24,51,24,'Minä maksan Baabelille ja kaikille Kaldean asukkaille kaiken sen pahan, minkä he ovat tehneet Siionille teidän silmäinne edessä, sanoo Herra.'),
(1689201,58,24,51,25,'Katso, minä käyn sinun kimppuusi, sinä hävityksen vuori, joka hävitit koko maan, sanoo Herra. Ja minä ojennan käteni sinua vastaan ja vieritän sinut alas kalliolta ja teen sinusta poltetun vuoren.'),
(1689202,58,24,51,26,'Eikä sinusta oteta enää kulmakiveä eikä perustuskiveä, vaan sinä jäät ikuiseksi erämaaksi, sanoo Herra.'),
(1689203,58,24,51,27,'Nostakaa lippu maassa, puhaltakaa pasunaan kansoissa, vihkikää kansat häntä vastaan, kutsukaa häntä vastaan Araratin, Minnin ja Askenaan valtakunnat, asettakaa päämies häntä vastaan, antakaa tulla hevosia kuin pörheitä heinäsirkkoja.'),
(1689204,58,24,51,28,'Vihkikää kansat häntä vastaan, Meedian kuninkaat, sen käskynhaltijat ja kaikki päämiehet ja koko sen vallan alainen maa.'),
(1689205,58,24,51,29,'Ja maa vapisee ja vääntelehtii tuskasta, sillä Herran aivoitukset täyttyvät Baabelia vastaan: hän tekee Baabelin maasta asumattoman erämaan.'),
(1689206,58,24,51,30,'Baabelin sankarit lakkaavat taistelemasta, he istuvat linnoituksissaan, heidän voimansa on kuihtunut, he ovat naisiksi muuttuneet; sen asunnot ovat poltetut, sen salvat rikotut.'),
(1689207,58,24,51,31,'Juoksija juoksee juoksijaa vastaan, sanansaattaja sanansaattajaa vastaan, ilmoittamaan Baabelin kuninkaalle, että hänen kaupunkinsa on valloitettu äärestä toiseen,'),
(1689208,58,24,51,32,'kahlauspaikat vallatut, linnoitukset tulella poltetut ja sotamiehet kauhun vallassa.'),
(1689209,58,24,51,33,'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Tytär Baabel on kuin puimatanner poljettaessa; vielä vähän aikaa, niin hänen elonaikansa tulee.'),
(1689210,58,24,51,34,'Nebukadressar, Baabelin kuningas, on minut syönyt, hävittänyt minut, pannut syrjään kuin tyhjän astian; hän on niellyt minut niinkuin lohikäärme, täyttänyt vatsansa minun herkuillani ja huuhtonut minut pois.'),
(1689211,58,24,51,35,'''Kärsimäni väkivalta ja minun raadeltu lihani tulkoon Baabelin päälle'', sanoo Siionin asukas. ''Minun vereni tulkoon Kaldean asukasten päälle'', sanoo Jerusalem.'),
(1689212,58,24,51,36,'Sentähden näin sanoo Herra: Katso, minä ajan sinun asiasi ja kostan sinun kostosi. Minä kuivaan hänen virtansa ja ehdytän hänen lähteensä.'),
(1689213,58,24,51,37,'Ja Baabel tulee kiviroukkioksi, aavikkosutten asunnoksi, kauhistukseksi ja ivan vihellykseksi, aivan asujattomaksi.'),
(1689214,58,24,51,38,'He kiljuvat kaikki kuin nuoret leijonat, murisevat kuin naarasleijonain pennut.'),
(1689215,58,24,51,39,'Kun he ovat himossansa kiihkeimmillään, teen minä heille juomingit ja juovutan heidät, että he riemastuvat ja nukkuvat ikuiseen uneen eivätkä enää heräjä, sanoo Herra.'),
(1689216,58,24,51,40,'Minä vien heidät teurastettaviksi, niinkuin karitsat, niinkuin oinaat ja kauriit.'),
(1689217,58,24,51,41,'Kuinka onkaan valloitettu Seesak, vallattu se, jota ylisti kaikki maa! Kuinka onkaan Baabelista tullut kauhistus kansojen seassa!'),
(1689218,58,24,51,42,'Meri nousi Baabelin yli, sen aaltojen pauhuun se peittyi.'),
(1689219,58,24,51,43,'Sen kaupungit ovat tulleet autiomaaksi, kuivaksi maaksi ja aromaaksi, maaksi, jossa ei asu kenkään, jossa ei ihmislapsi kulje.'),
(1689220,58,24,51,44,'Minä kostan Beelille Baabelissa ja vedän ulos hänen kidastaan sen, mitä hän on niellyt; eivätkä kansat enää virtaa hänen tykönsä. Baabelin muurikin on kaatunut.'),
(1689221,58,24,51,45,'Lähde pois sen keskeltä, minun kansani, ja pelastakoon kukin henkensä Herran vihan hehkusta.'),
(1689222,58,24,51,46,'Älköön sydämenne säikkykö, älkää peljätkö sitä sanomaa, joka kuuluu maassa, kun tulee tänä vuonna tämä sanoma ja sitten toisena vuonna tuo sanoma, kun maassa on väkivalta ja hallitsija hallitsijaa vastaan.'),
(1689223,58,24,51,47,'Sentähden katso, päivät tulevat, jolloin minä kostan Baabelin jumalankuville, jolloin koko sen maa joutuu häpeään ja kaikki kaatuvat surmattuina sen keskellä.'),
(1689224,58,24,51,48,'Silloin riemuitsevat Baabelin kohtalosta taivas ja maa ja kaikki, mitä niissä on, kun pohjoisesta tulevat sen hävittäjät, sanoo Herra.'),
(1689225,58,24,51,49,'Baabelinkin on kaatuminen, te Israelin surmatut, niinkuin Baabelin tähden kaatui surmatuita kautta kaiken maan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689226,58,24,51,50,'Te miekasta pelastuneet, menkää, älkää pysähtykö, muistakaa Herraa kaukaisella maalla ja pitäkää mielessänne Jerusalem.'),
(1689227,58,24,51,51,'''Me häpeämme, sillä me kuulemme pilkkaa; häpeä peittää meidän kasvomme, sillä muukalaiset ovat käyneet Herran temppelin pyhyyksien kimppuun.'''),
(1689228,58,24,51,52,'Sentähden katso, päivät tulevat, sanoo Herra, jolloin minä kostan sen jumalankuville ja sen maa on täynnä haavoitettujen voihkinaa.'),
(1689229,58,24,51,53,'Vaikka Baabel astuisi ylös taivaaseen, vaikka se korkeuteen linnansa vahvistaisi, sittenkin tulevat sille minulta hävittäjät, sanoo Herra.'),
(1689230,58,24,51,54,'Kuule, huuto Baabelista, suuri hävityksen melske kaldealaisten maasta!'),
(1689231,58,24,51,55,'Sillä Herra hävittää Baabelin ja lopettaa sieltä suuren äänten melun. Heidän aaltonsa pauhaavat kuin suuret vedet, korkea on heidän äänensä kohina.'),
(1689232,58,24,51,56,'Sillä hävittäjä käy Baabelin kimppuun, ja sen sankarit vangitaan, heidän jousensa murretaan; sillä Herra on koston Jumala: hän maksaa tarkoin.'),
(1689233,58,24,51,57,'Minä juovutan sen ruhtinaat ja tietäjät, sen käskynhaltijat, päämiehet ja sankarit; ja he nukkuvat ikuiseen uneen eivätkä enää heräjä, sanoo Kuningas; Herra Sebaot on hänen nimensä.'),
(1689234,58,24,51,58,'Näin sanoo Herra Sebaot: Baabelin leveä muuri hajotetaan maahan, ja sen korkeat portit poltetaan tulella. Niin tekevät kansat työtä tyhjän tähden, kansakunnat tulen hyväksi, ja vaivaavat itsensä väsyksiin."'),
(1689235,58,24,51,59,'Asia, jonka profeetta Jeremia antoi Serajalle, Neerian, Mahsejan pojan, pojalle toimitettavaksi, kun tämä lähti Sidkian, Juudan kuninkaan, kanssa Baabeliin hänen neljäntenä hallitusvuotenansa. Seraja oli majoituspäällikkö.'),
(1689236,58,24,51,60,'Jeremia kirjoitti kaiken sen onnettomuuden, joka oli tuleva Baabelille, erityiseen kirjaan, kaikki nämä sanat, jotka ovat kirjoitetut Baabelia vastaan.'),
(1689237,58,24,51,61,'Ja Jeremia sanoi Serajalle: "Kun tulet Baabeliin, niin katso, että luet kaikki nämä sanat.'),
(1689238,58,24,51,62,'Ja sano: Herra, sinä olet puhunut tätä paikkaa vastaan: sinä olet hävittävä sen, niin ettei siinä asukasta ole, ei ihmistä eikä eläintä, vaan että se jää ikuiseksi erämaaksi.'),
(1689239,58,24,51,63,'Ja kun olet lukenut tämän kirjan loppuun, sido siihen kivi ja viskaa se keskelle Eufratia,'),
(1689240,58,24,51,64,'ja sano: Näin uppoaa Baabel eikä nouse enää siitä onnettomuudesta, jonka minä sille tuotan, vaan he vaipuvat." Näin pitkälle Jeremian sanat.'),
(1689241,58,24,52,1,'Sidkia oli kahdenkymmenen yhden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa yksitoista vuotta. Hänen äitinsä oli nimeltään Hamutal, Jeremian tytär, Libnasta.'),
(1689242,58,24,52,2,'Hän teki sitä, mikä on pahaa Herran silmissä, aivan samoin kuin Joojakim oli tehnyt.'),
(1689243,58,24,52,3,'Sillä Herran vihan tähden kävi näin Jerusalemille ja Juudalle, kunnes hän vihdoin heitti heidät pois kasvojensa edestä.'),
(1689244,58,24,52,4,'Sidkia kapinoi Baabelin kuningasta vastaan. Hänen yhdeksäntenä hallitusvuotenaan, sen kymmenennessä kuussa, kuukauden kymmenentenä päivänä, hyökkäsi Nebukadressar, Baabelin kuningas, koko sotajoukollaan Jerusalemin kimppuun; ja he asettuivat leiriin sitä vastaan ja rakensivat saartovarusteet sitä vastaan yltympäri.'),
(1689245,58,24,52,5,'Näin kaupunkia piiritettiin kuningas Sidkian yhdenteentoista hallitusvuoteen asti.'),
(1689246,58,24,52,6,'Mutta neljännessä kuussa, kuukauden yhdeksäntenä päivänä, kun nälänhätä ahdisti kaupunkia eikä maakansallakaan ollut leipää,'),
(1689247,58,24,52,7,'valloitettiin kaupunki, ja kaikki sotilaat pakenivat ja lähtivät ulos kaupungista yöllä molempien muurien välitse vievää porttitietä, joka on kuninkaan puutarhan puolella, kaldealaisten ollessa kaupungin ympärillä, ja he kulkivat Aromaahan päin.'),
(1689248,58,24,52,8,'Mutta kaldealaisten sotajoukko ajoi kuningasta takaa, ja he saavuttivat Sidkian Jerikon aroilla; ja kaikki hänen sotaväkensä oli jättänyt hänet ja hajaantunut.'),
(1689249,58,24,52,9,'Ja he ottivat kuninkaan kiinni ja veivät hänet Baabelin kuninkaan eteen Riblaan, joka on Hamatin maassa, ja tämä julisti hänelle tuomion.'),
(1689250,58,24,52,10,'Ja Baabelin kuningas teurastutti Sidkian pojat hänen silmiensä edessä, ja myöskin kaikki Juudan ruhtinaat hän teurastutti Riblassa.'),
(1689251,58,24,52,11,'Ja Sidkialta Baabelin kuningas sokaisutti silmät, kytketti hänet vaskikahleisiin ja vei hänet Baabeliin, ja hän pani hänet vankihuoneeseen, jossa hän oli kuolinpäiväänsä asti.'),
(1689252,58,24,52,12,'Viidennessä kuussa, kuukauden kymmenentenä päivänä, Baabelin kuninkaan Nebukadressarin yhdeksäntenätoista hallitusvuotena, tuli Nebusaradan, henkivartijain päällikkö, joka palveli Baabelin kuningasta, Jerusalemiin.'),
(1689253,58,24,52,13,'Hän poltti Herran temppelin ja kuninkaan linnan ja kaikki Jerusalemin talot; kaikki ylhäisten talot hän poltti tulella.'),
(1689254,58,24,52,14,'Ja koko kaldealaisten sotajoukko, joka henkivartijain päälliköllä oli mukanaan, repi maahan kaikki Jerusalemin muurit, yltympäri.'),
(1689255,58,24,52,15,'Ja Nebusaradan, henkivartijain päällikkö, siirsi maasta pois osan kansan köyhiä ja kansan tähteitä, mitä oli jäljellä kaupungissa, sekä ne, jotka olivat menneet Baabelin kuninkaan puolelle, ja loput käsityöläisistä.'),
(1689256,58,24,52,16,'Mutta osan maan köyhiä Nebusaradan, henkivartijain päällikkö, jätti jäljelle viinitarhureiksi ja peltomiehiksi.'),
(1689257,58,24,52,17,'Vaskipylväät, jotka olivat Herran temppelissä, altaiden telineet ja vaskimeren, jotka olivat Herran temppelissä, kaldealaiset särkivät ja veivät kaiken niiden vasken Baabeliin.'),
(1689258,58,24,52,18,'Ja kattilat, lapiot, veitset, maljat, kupit ja kaikki vaskikalut, joita oli käytetty jumalanpalveluksessa, he ottivat pois.'),
(1689259,58,24,52,19,'Samoin otti henkivartijain päällikkö vadit, hiilipannut, maljat, kattilat, lampunjalat, kupit ja kulhot, jotka olivat läpeensä kultaa tai hopeata.'),
(1689260,58,24,52,20,'Molempien pylväiden, meren ja niiden kahdentoista vaskiraavaan, jotka olivat telineiden alla - kaikkien niiden esineiden, jotka Salomo oli teettänyt Herran temppeliin - niiden vaski ei ollut punnittavissa.'),
(1689261,58,24,52,21,'Pylväistä oli toisen pylvään korkeus kahdeksantoista kyynärää, ja kahdentoista kyynärän pituinen nauha ulottui sen ympäri. Sen vahvuus oli neljä sormenleveyttä; se oli ontto.'),
(1689262,58,24,52,22,'Ja sen päässä oli pylväänpää vaskesta; toisen pylväänpään korkeus oli viisi kyynärää, ja pylväänpään päällä oli ristikkokoriste ja granaattiomenia yltympäri, kaikki vaskea; ja samanlaiset oli toisessa pylväässä ynnä granaattiomenat.'),
(1689263,58,24,52,23,'Granaattiomenia oli yhdeksänkymmentä kuusi ulospäin; kaikkiaan oli granaattiomenia sata ristikkokoristeen päällä yltympäri.'),
(1689264,58,24,52,24,'Ja henkivartijain päällikkö otti ylimmäisen papin Serajan ja häntä lähimmän papin Sefanjan sekä kolme ovenvartijaa,'),
(1689265,58,24,52,25,'ja kaupungista hän otti yhden hoviherran, joka oli sotaväen tarkastaja, ja seitsemän kuninkaan lähintä miestä, jotka tavattiin kaupungista, sekä sotapäällikön kirjurin, jonka tehtävänä oli ottaa maan kansaa sotapalvelukseen, ja kuusikymmentä miestä maakansasta, jotka tavattiin kaupungista.'),
(1689266,58,24,52,26,'Nämä otti Nebusaradan, henkivartijain päällikkö, ja vei heidät Baabelin kuninkaan eteen Riblaan.'),
(1689267,58,24,52,27,'Ja Baabelin kuningas antoi lyödä heidät kuoliaaksi Riblassa Hamatin maassa. Ja niin Juuda siirrettiin pois maastansa.'),
(1689268,58,24,52,28,'Tämä on se kansa, jonka Nebukadressar vei pakkosiirtolaisuuteen: seitsemäntenä vuotena kolmetuhatta kaksikymmentä kolme juutalaista,'),
(1689269,58,24,52,29,'Nebukadressarin kahdeksantenatoista hallitusvuotena kahdeksansataa kolmekymmentä kaksi henkeä Jerusalemista,'),
(1689270,58,24,52,30,'Nebukadressarin kahdentenakymmenentenä kolmantena hallitusvuotena vei Nebusaradan, henkivartijain päällikkö, seitsemänsataa neljäkymmentä viisi juutalaista pakkosiirtolaisuuteen - yhteensä neljätuhatta kuusisataa henkeä.'),
(1689271,58,24,52,31,'Mutta kolmantenakymmenentenä seitsemäntenä vuotena siitä, kun Joojakim, Juudan kuningas, oli viety pakkosiirtolaisuuteen, kahdennessatoista kuussa, kuukauden kahdentenakymmenentenä viidentenä päivänä, korotti Evil-Merodak, Baabelin kuningas, samana vuonna, jona hän tuli kuninkaaksi, Juudan kuninkaan Joojakinin pään ja päästi hänet pois vankilasta.'),
(1689272,58,24,52,32,'Ja hän puhutteli häntä ystävällisesti ja asetti hänen istuimensa ylemmäksi muitten kuningasten istuimia, jotka olivat hänen tykönänsä Baabelissa.'),
(1689273,58,24,52,33,'Hän sai panna pois vanginpuvun ja aina aterioida hänen luonaan, niin kauan kuin eli.'),
(1689274,58,25,1,1,'Kuinka istuukaan yksinänsä tuo väkirikas kaupunki! Kuinka onkaan lesken kaltaiseksi tullut se, joka oli suuri kansakuntien joukossa! Ruhtinatar maakuntien joukossa on tullut työveron alaiseksi.'),
(1689275,58,25,1,2,'Se katkerasti itkee yössä, ja sillä on kyyneleet poskillansa. Ei ole sillä lohduttajaa kaikkien sen rakastajain seassa. Uskottomia ovat sille olleet kaikki sen ystävät, ovat sille vihamiehiksi tulleet.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689276,58,25,1,3,'Juuda on siirtynyt maastansa kurjuutta ja työn kovuutta pakoon. Se istuu pakanakansain seassa eikä lepoa löydä. Kaikki sen vainoojat saavuttivat sen, kun se oli ahdistuksien keskellä.'),
(1689277,58,25,1,4,'Siionin tiet surevat, sillä juhlilletulijoita ei ole. Kaikki sen portit ovat autioina, sen papit huokailevat, sen neitsyet ovat murheissaan, ja sillä itsellään on katkera mieli.'),
(1689278,58,25,1,5,'Sen viholliset ovat voitolle päässeet, sen vihamiehet menestyvät. Sillä Herra on saattanut sen murheelliseksi sen rikkomusten paljouden tähden. Sen pienet lapset ovat menneet vankeuteen vihollisen vieminä.'),
(1689279,58,25,1,6,'Mennyt on tytär Siionilta kaikki hänen kauneutensa. Hänen ruhtinaansa ovat kuin peurat, jotka eivät laidunta löydä; he kulkivat voimattomina vainoojan edessä.'),
(1689280,58,25,1,7,'Jerusalem muistelee kurjuutensa päivinä ja kodittomuudessaan kaikkea kallisarvoista, mitä sillä oli muinaisista päivistä asti. Kun sen kansa sortui vihollisen käsiin eikä sillä ollut auttajaa, katsoivat viholliset sitä ja nauroivat sen turmiota.'),
(1689281,58,25,1,8,'Jerusalem on raskaasti syntiä tehnyt, sentähden se on saastaksi tullut. Kaikki, jotka sitä kunnioittivat, halveksivat sitä nyt, kun ovat nähneet sen alastomuuden. Itsekin se huokaa ja kääntyy poispäin.'),
(1689282,58,25,1,9,'Sen tahrat ovat sen liepeissä. Se ei ajatellut, mikä sille tuleva oli, ja niin se sortui hämmästyttävästi. Ei ole sillä lohduttajaa. Katso, Herra, minun kurjuuttani, sillä vihamies ylvästelee.'),
(1689283,58,25,1,10,'Vihollinen levitti kätensä kaikkia sen kalleuksia kohti. Niin, sen täytyi nähdä, kuinka pakanat tunkeutuivat sen pyhäkköön, ne, jotka sinä olit kieltänyt tulemasta sinun seurakuntaasi.'),
(1689284,58,25,1,11,'Kaikki sen kansa huokaa etsiessänsä leipää: he antavat, mitä heillä kallista on, ruuasta, saadakseen nälkänsä tyydytetyksi. Katso, Herra, ja näe, kuinka halveksittu minä olen.'),
(1689285,58,25,1,12,'Eikö tämä koske teihin, kaikki ohikulkijat? Katsokaa ja nähkää: onko kipua, minun kipuni vertaista, joka on minun kannettavakseni pantu, jolla Herra on murehduttanut minut vihansa hehkun päivänä?'),
(1689286,58,25,1,13,'Hän lähetti tulen korkeudesta minun luihini ja kuritti niitä. Hän viritti verkon minun jalkaini varalle, hän pani minut peräytymään, hän teki minut autioksi, ainiaan sairaaksi.'),
(1689287,58,25,1,14,'Hänen kätensä sitoi minun rikosteni ikeen: ne kiedottiin yhteen, tulivat minun niskalleni; hän saattoi horjumaan minun voimani. Herra antoi minut niiden käsiin, joita minä en voi vastustaa.'),
(1689288,58,25,1,15,'Herra hylkäsi kaikki minun urhoni, joita minun keskuudessani oli; hän kutsui kokoon juhlan minua vastaan murskatakseen minun nuorukaiseni. Herra polki viinikuurnan neitsyelle, tytär Juudalle.'),
(1689289,58,25,1,16,'Näitä minä itken, minun silmäni, silmäni vuotaa vettä; sillä kaukana on minusta lohduttaja, joka virvoittaisi minun sieluani. Hävitetyt ovat minun lapseni, sillä vihamies on väkevä.'),
(1689290,58,25,1,17,'Siion levittää käsiänsä: ei ole hänellä lohduttajaa. Herra on nostattanut Jaakobia vastaan sen viholliset joka taholta; Jerusalem on tullut saastaksi heidän keskellänsä.'),
(1689291,58,25,1,18,'Vanhurskas on hän, Herra; sillä hänen käskyänsä vastaan minä olen niskoitellut. Kuulkaa, te kansat kaikki, ja katsokaa minun kipuani: minun neitsyeni ja nuorukaiseni ovat vankeuteen menneet.'),
(1689292,58,25,1,19,'Minä kutsuin rakastajiani: ne pettivät minut. Minun pappini ja vanhimpani ovat kuolleet kaupungissa, kun he etsivät ruokaa tyydyttääkseen nälkäänsä.'),
(1689293,58,25,1,20,'Katso, Herra, kuinka ahdistettu minä olen, minun sisukseni kuohuvat, sydämeni vääntyy rinnassani, sillä minä olen ollut ylen uppiniskainen. Ulkona on miekka minulta riistänyt lapset, sisällä rutto.'),
(1689294,58,25,1,21,'He ovat kuulleet, kuinka minä huokailen. Ei ole minulla lohduttajaa. Kaikki minun vihamieheni ovat kuulleet minun onnettomuuteni; he iloitsevat, kun sinä olet tämän tehnyt: sinä olet antanut tulla sen päivän, jonka olit ilmoittanut. Mutta käyköön heidän samoin kuin minun.'),
(1689295,58,25,1,22,'Tulkoon kaikki heidän pahuutensa sinun kasvojesi eteen, ja pane heille kannettavaksi se, minkä olet minulle pannut kaikkien minun rikoksieni tähden. Sillä monet ovat minun huokaukseni, ja minun sydämeni on sairas.'),
(1689296,58,25,2,1,'Kuinka onkaan Herra vihassaan pilvillä peittänyt tytär Siionin! Hän heitti taivaasta maahan Israelin kunnian eikä muistanut jalkainsa astinlautaa vihansa päivänä.'),
(1689297,58,25,2,2,'Herra on hävittänyt säälimättä kaikki Jaakobin majat, on hajottanut vihastuksissaan tytär Juudan linnoitukset, pannut ne maan tasalle. Hän on häväissyt valtakunnan ja sen ruhtinaat.'),
(1689298,58,25,2,3,'Hän on vihan hehkussa hakannut poikki Israelin sarven kokonansa. Hän veti oikean kätensä takaisin vihamiehen edestä ja poltti Jaakobia kuin liekitsevä tuli, joka kuluttaa kaiken yltympäri.'),
(1689299,58,25,2,4,'Hän jännitti jousensa kuin vihamies, seisoi oikea käsi koholla kuin vihollinen ja tappoi kaiken, mihin silmä oli ihastunut. Tytär Siionin majaan hän vuodatti kiivautensa kuin tulen.'),
(1689300,58,25,2,5,'Herra on ollut niinkuin vihamies, on hävittänyt Israelin: hän hävitti kaikki sen palatsit, turmeli sen linnoitukset ja antoi tytär Juudalle paljon valitusta ja vaikerrusta.'),
(1689301,58,25,2,6,'Hän särki aitauksensa niinkuin puutarhan aidan, hävitti juhlanviettopaikkansa. Herra on saattanut unhotuksiin Siionissa juhla-ajat ja sapatit ja on kiivaassa suuttumuksessaan pitänyt halpana kuninkaat ja papit.'),
(1689302,58,25,2,7,'Herra on hyljännyt alttarinsa, syössyt häväistykseen pyhäkkönsä, luovuttanut vihamiehen käteen palatsiensa muurit. He nostivat huudon Herran huoneessa, huudon kuin juhlapäivänä.'),
(1689303,58,25,2,8,'Herra oli päättänyt turmella tytär Siionin muurit: hän jännitti mittanuoran, ei pidättänyt kättänsä hävittämästä, saattoi murheeseen varustukset ja muurit; ne yhdessä nääntyvät.'),
(1689304,58,25,2,9,'Sen portit ovat vajonneet maahan, hän poisti ja särki sen salvat. Sen kuningas ja ruhtinaat ovat pakanain seassa; lakia ei ole, eivätkä sen profeetat saa näkyjä Herralta.'),
(1689305,58,25,2,10,'Maassa istuvat ääneti tytär Siionin vanhimmat. He ovat heittäneet tomua päänsä päälle, vyöttäytyneet säkkeihin; maata kohden ovat painaneet päänsä Jerusalemin neitsyet.'),
(1689306,58,25,2,11,'Minun silmäni ovat itkusta hiuenneet, minun sisukseni kuohuvat, minun maksani on maahan vuodatettu tyttären, minun kansani, sortumisen tähden. Sillä lapset ja imeväiset nääntyvät kaupungin kaduilla.'),
(1689307,58,25,2,12,'He sanovat äideillensä: "Missä on leipää ja viiniä?" kun he nääntyvät niinkuin kaatuneet kaupungin kaduilla, heittävät henkensä äitiensä syliin.'),
(1689308,58,25,2,13,'Minkä sinulle mainitsisin, mihin vertaisin sinua, tytär Jerusalem? Minkä asettaisin rinnallesi lohduttaakseni sinua, neitsyt, tytär Siion? Sillä suuri niinkuin meri on sinun sortumisesi; kuka voi sinut parantaa?'),
(1689309,58,25,2,14,'Profeettasi ovat sinulle nähneet petollisia, äiteliä näkyjä. Eivät he ole paljastaneet sinun syntiäsi, niin että olisivat kääntäneet sinun kohtalosi, vaan ovat nähneet sinulle petollisia, eksyttäväisiä ennustuksia.'),
(1689310,58,25,2,15,'Sinulle paukuttavat kämmeniänsä kaikki ohikulkijat, he viheltävät ja nyökyttävät ilkkuen päätänsä tytär Jerusalemille: "Tämäkö on kaupunki, jota sanottiin kauneuden täydellisyydeksi, kaiken maan ihastukseksi?"'),
(1689311,58,25,2,16,'Suu ammollaan sinua vastaan ovat kaikki sinun vihamiehesi. He viheltävät, kiristelevät hampaitaan ja sanovat: "Me olemme sen hävittäneet. Tämä on juuri se päivä, jota olemme toivoneet; se on meille tullut, olemme sen nähneet."'),
(1689312,58,25,2,17,'Herra on tehnyt, mitä oli aikonut. Hän on täyttänyt sanansa, sen, mitä oli päättänyt muinaisista päivistä asti: hän on repinyt alas säälimättä, on antanut vihamiesten iloita sinusta ja kohottanut sinun vihollistesi sarven.'),
(1689313,58,25,2,18,'Heidän sydämensä huutaa Herran puoleen. Sinä, tytär Siionin muuri, anna kyyneltesi virtana vuotaa yötä päivää! Älä suo itsellesi lepoa, älköön silmäteräsi ummistuko.'),
(1689314,58,25,2,19,'Nouse, kohota valitushuuto yöllä, kun alkavat yövartiot. Anna sydämesi vuotaa kuin vesi Herran kasvojen edessä. Kohota kätesi häntä kohden pienten lastesi elämän puolesta, kun ne nääntyvät nälkään kaikkien katujen kulmissa.'),
(1689315,58,25,2,20,'Katso, Herra, ja tarkkaa, ketä olet antanut tämän kohdata: pitäisikö vaimojen syödä oma hedelmänsä, vaalimansa pienet lapset; pitäisikö Herran pyhäkössä tapettaman papit ja profeetat?'),
(1689316,58,25,2,21,'Maassa, kaduilla, makaa nuorta ja vanhaa; minun neitsyeni ja nuorukaiseni ovat kaatuneet miekkaan. Sinä olet surmannut vihasi päivänä, olet teurastanut säälimättä.'),
(1689317,58,25,2,22,'Sinä kutsuit kuin juhlapäivän viettoon minun peljättäjäni joka taholta; eikä jäänyt Herran vihan päivänä pelastunutta, ei pakoonpäässyttä. Jotka minä olin vaalinut ja isoiksi saanut, ne minun vihamieheni lopetti.'),
(1689318,58,25,3,1,'Minä olen se mies, joka olen kurjuutta nähnyt hänen vihastuksensa vitsan alla.'),
(1689319,58,25,3,2,'Minut hän on johdattanut ja kuljettanut pimeyteen eikä valkeuteen.'),
(1689320,58,25,3,3,'Juuri minua vastaan hän kääntää kätensä, yhäti, kaiken päivää.'),
(1689321,58,25,3,4,'Hän on kalvanut minun lihani ja nahkani, musertanut minun luuni.'),
(1689322,58,25,3,5,'Hän on rakentanut varustukset minua vastaan ja piirittänyt minut myrkyllä ja vaivalla.'),
(1689323,58,25,3,6,'Hän on pannut minut asumaan pimeydessä niinkuin ikiaikojen kuolleet.'),
(1689324,58,25,3,7,'Hän on tehnyt muurin minun ympärilleni, niin etten pääse ulos, on pannut minut raskaisiin vaskikahleisiin.'),
(1689325,58,25,3,8,'Vaikka minä huudan ja parun, hän vaientaa minun rukoukseni.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689326,58,25,3,9,'Hakatuista kivistä hän on tehnyt minun teilleni muurin, on mutkistanut minun polkuni.'),
(1689327,58,25,3,10,'Vaaniva karhu on hän minulle, piilossa väijyvä leijona.'),
(1689328,58,25,3,11,'Hän on vienyt harhaan minun tieni ja repinyt minut kappaleiksi, hän on minut autioksi tehnyt.'),
(1689329,58,25,3,12,'Hän on jännittänyt jousensa ja asettanut minut nuoltensa maalitauluksi.'),
(1689330,58,25,3,13,'Hän on ampunut munuaisiini nuolet, viinensä lapset.'),
(1689331,58,25,3,14,'Minä olen joutunut koko kansani nauruksi, heidän jokapäiväiseksi pilkkalauluksensa.'),
(1689332,58,25,3,15,'Hän on ravinnut minua katkeruudella, juottanut minua koiruoholla.'),
(1689333,58,25,3,16,'Hän on purettanut minulla hampaat rikki soraan, painanut minut alas tomuun.'),
(1689334,58,25,3,17,'Sinä olet syössyt minun sieluni ulos, rauhasta pois, minä olen unhottanut onnen.'),
(1689335,58,25,3,18,'Ja minä sanon: mennyt on minulta kunnia ja Herran odotus.'),
(1689336,58,25,3,19,'Muista minun kurjuuttani ja kodittomuuttani, koiruohoa ja myrkkyä.'),
(1689337,58,25,3,20,'Sinä kyllä muistat sen, että minun sieluni on alaspainettu.'),
(1689338,58,25,3,21,'Tämän minä painan sydämeeni, sentähden minä toivon.'),
(1689339,58,25,3,22,'Herran armoa on, ettemme ole aivan hävinneet, sillä hänen laupeutensa ei ole loppunut:'),
(1689340,58,25,3,23,'se on joka aamu uusi, ja suuri on hänen uskollisuutensa.'),
(1689341,58,25,3,24,'Minun osani on Herra, sanoo minun sieluni; sentähden minä panen toivoni häneen.'),
(1689342,58,25,3,25,'Hyvä on Herra häntä odottaville, sille sielulle, joka häntä etsii.'),
(1689343,58,25,3,26,'Hyvä on hiljaisuudessa toivoa Herran apua.'),
(1689344,58,25,3,27,'Hyvä on miehelle, että hän kantaa iestä nuoruudessaan.'),
(1689345,58,25,3,28,'Istukoon hän yksin ja hiljaa, kun Herra on sen hänen päällensä pannut.'),
(1689346,58,25,3,29,'Laskekoon suunsa tomuun - ehkä on vielä toivoa.'),
(1689347,58,25,3,30,'Ojentakoon hän posken sille, joka häntä lyö, saakoon kyllälti häväistystä.'),
(1689348,58,25,3,31,'Sillä ei Herra hylkää iankaikkisesti;'),
(1689349,58,25,3,32,'vaan jos hän on murheelliseksi saattanut, hän osoittaa laupeutta suuressa armossansa.'),
(1689350,58,25,3,33,'Sillä ei hän sydämensä halusta vaivaa eikä murehduta ihmislapsia.'),
(1689351,58,25,3,34,'Kun jalkojen alle poljetaan kaikki vangit maassa,'),
(1689352,58,25,3,35,'kun väännetään miehen oikeutta Korkeimman kasvojen edessä,'),
(1689353,58,25,3,36,'kun ihmiselle tehdään vääryyttä hänen riita-asiassaan - eikö Herra sitä näkisi?'),
(1689354,58,25,3,37,'Onko kukaan sanonut, ja se on tapahtunut, jos ei Herra ole käskenyt?'),
(1689355,58,25,3,38,'Eikö lähde Korkeimman suusta paha ja hyvä?'),
(1689356,58,25,3,39,'Miksi tuskittelee ihminen eläessään, mies syntiensä palkkaa?'),
(1689357,58,25,3,40,'Koetelkaamme teitämme, tutkikaamme niitä ja palatkaamme Herran tykö.'),
(1689358,58,25,3,41,'Kohottakaamme sydämemme ynnä kätemme Jumalan puoleen, joka on taivaassa.'),
(1689359,58,25,3,42,'Me olemme luopuneet pois ja olleet kapinalliset; sinä et ole antanut anteeksi,'),
(1689360,58,25,3,43,'olet peittänyt itsesi vihassasi, ajanut meitä takaa, surmannut säälimättä;'),
(1689361,58,25,3,44,'olet peittänyt itsesi pilvellä, niin ettei rukous pääse lävitse.'),
(1689362,58,25,3,45,'Tunkioksi ja hylyksi sinä olet meidät tehnyt kansojen seassa.'),
(1689363,58,25,3,46,'Suut ammollaan meitä vastaan ovat kaikki meidän vihamiehemme.'),
(1689364,58,25,3,47,'Osaksemme on tullut kauhu ja kuoppa, turmio ja sortuminen.'),
(1689365,58,25,3,48,'Vesipurot juoksevat minun silmistäni tyttären, minun kansani, sortumisen tähden.'),
(1689366,58,25,3,49,'Minun silmäni vuotaa lakkaamatta, hellittämättä'),
(1689367,58,25,3,50,'siihen asti, kunnes katsoo, kunnes näkee Herra taivaasta.'),
(1689368,58,25,3,51,'Silmäni tuottaa tuskaa minun sielulleni kaikkien minun kaupunkini tyttärien tähden.'),
(1689369,58,25,3,52,'Kiihkeästi pyydystivät minua kuin lintua ne, jotka syyttä ovat vihamiehiäni.'),
(1689370,58,25,3,53,'He sulkivat kuoppaan minun elämäni ja heittivät päälleni kiviä.'),
(1689371,58,25,3,54,'Vedet tulvivat minun pääni ylitse; minä sanoin: olen hukassa.'),
(1689372,58,25,3,55,'Minä huusin sinun nimeäsi, Herra, kuopan syvyydestä.'),
(1689373,58,25,3,56,'Sinä kuulit minun huutoni: "Älä peitä korvaasi minun avunhuudoltani, että saisin hengähtää".'),
(1689374,58,25,3,57,'Sinä olit läsnä silloin, kun minä sinua huusin; sinä sanoit: "Älä pelkää".'),
(1689375,58,25,3,58,'Sinä, Herra, ajoit minun riita-asiani, lunastit minun henkeni.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689376,58,25,3,59,'Olethan nähnyt, Herra, minun kärsimäni sorron: hanki minulle oikeus.'),
(1689377,58,25,3,60,'Olethan nähnyt kaiken heidän kostonhimonsa, kaikki heidän juonensa minua vastaan.'),
(1689378,58,25,3,61,'Sinä olet kuullut heidän häväistyksensä, Herra, kaikki heidän juonensa minua vastaan.'),
(1689379,58,25,3,62,'Minun vastustajaini huulet ja heidän aikeensa ovat minua vastaan kaiken päivää.'),
(1689380,58,25,3,63,'Istuivatpa he tai nousivat, katso: minä olen heillä pilkkalauluna.'),
(1689381,58,25,3,64,'Kosta heille, Herra, heidän kättensä teot.'),
(1689382,58,25,3,65,'Paaduta heidän sydämensä, kohdatkoon heitä sinun kirouksesi.'),
(1689383,58,25,3,66,'Aja heitä takaa vihassasi ja hävitä heidät Herran taivaan alta.'),
(1689384,58,25,4,1,'Kuinka onkaan kulta tummunut, muuttunut hyvä kulta; kuinka ovat pyhät kivet viskeltyinä kaikkien katujen kulmiin!'),
(1689385,58,25,4,2,'Siionin pojat, nuo kalliit, punnitut puhtaimman kullan arvoisiksi - kuinka he ovatkaan saviastiain arvossa, savenvalajan kätten tekojen!'),
(1689386,58,25,4,3,'Aavikkosudetkin taritsevat nisiänsä, imettävät pentujansa; mutta tytär, minun kansani, on tullut tylyksi kuin kamelikurki erämaassa.'),
(1689387,58,25,4,4,'Imeväisen kieli tarttuu suulakeen janon tähden. Lapsukaiset pyytävät leipää; ei ole, kuka sitä heille taittaisi.'),
(1689388,58,25,4,5,'Jotka herkkuja söivät, ne nääntyvät kaduilla. Joita punapurppuran päällä kanneltiin, ne tunkioita syleilevät.'),
(1689389,58,25,4,6,'Tyttären, minun kansani, syntivelka on Sodoman syntiä suurempi; Sodoma hävitettiin yhtäkkiä kätten siellä riehumatta.'),
(1689390,58,25,4,7,'Siionin ruhtinaat olivat lunta puhtaammat, maitoa valkoisemmat, heidän ruumiinsa oli koralleja rusottavampi, heidän hahmonsa oli kuin safiiri.'),
(1689391,58,25,4,8,'Nyt on heidän muotonsa nokea mustempi, ei voi heitä tuntea kaduilla. Rypyssä on heillä nahka luitten päällä, se on kuivettunut kuin puu.'),
(1689392,58,25,4,9,'Parempi oli miekan kaatamien kuin nälän kaatamien, jotka menehtyivät, kuin lävitsepistetyt, pellon viljaa vailla.'),
(1689393,58,25,4,10,'Armeliaat vaimot keittivät omin käsin lapsiansa: ne tulivat heille ruuaksi tyttären, minun kansani, sortuessa.'),
(1689394,58,25,4,11,'Herra on pannut täytäntöön kiivautensa, vuodattanut vihansa hehkun; hän on sytyttänyt Siioniin tulen, joka on kuluttanut sen perustukset.'),
(1689395,58,25,4,12,'Eivät olisi uskoneet maan kuninkaat, ei maanpiirin asukkaista kenkään, että vihollinen ja vainomies hyökkää sisään Jerusalemin porteista.'),
(1689396,58,25,4,13,'Sen profeettain syntien tähden kävi näin, sen pappien pahain tekojen tähden, niiden, jotka siellä olivat vuodattaneet vanhurskaitten verta.'),
(1689397,58,25,4,14,'He harhailivat sokeina kaduilla, verellä tahrattuina, niin ettei voinut koskea heidän vaatteisiinsa.'),
(1689398,58,25,4,15,'"Väistykää! Saastainen!" huudettiin heistä. "Väistykää, väistykää, älkää koskeko!" Paettuaankin he yhä harhailivat; pakanain seassa sanottiin: "Eivät he saa kauemmin asustaa täällä".'),
(1689399,58,25,4,16,'Herran kasvot ovat hajottaneet heidät, hän ei heihin enää katso. Papeista ei välitetty, vanhimpia ei armahdettu.'),
(1689400,58,25,4,17,'Vieläkin me, silmät rauenneina, turhaan odotimme apua; tähystyspaikastamme me tähyilimme kansaa, josta ei pelastusta tullut.'),
(1689401,58,25,4,18,'Meidän askeleitamme vaanittiin, niin ettemme voineet kulkea kaduillamme. Meidän loppumme lähestyi, päivämme täyttyivät - niin, loppumme tuli.'),
(1689402,58,25,4,19,'Meidän vainoojamme olivat nopeammat kuin kotkat taivaalla. Vuorilla he ajoivat meitä takaa, väijyivät meitä erämaassa.'),
(1689403,58,25,4,20,'Hän, meidän elämänhenkemme, Herran voideltu, joutui vangiksi heidän kuoppiinsa, hän, josta me olimme sanoneet: hänen varjossaan me saamme elää pakanakansain seassa.'),
(1689404,58,25,4,21,'Iloitse ja riemuitse, tytär Edom, joka asut Uusin maassa! Mutta malja on tuleva sinunkin kohdallesi: sinä juovut ja paljastat itsesi.'),
(1689405,58,25,4,22,'Sinun syntivelkasi, tytär Siion, on loppunut: ei Herra ole enää siirtävä sinua pois. Sinun syntivelkasi, tytär Edom, hän on etsiskelevä, on paljastava sinun syntisi.'),
(1689406,58,25,5,1,'Muista, Herra, mitä meille on tapahtunut; katso ja näe meidän häväistyksemme.'),
(1689407,58,25,5,2,'Meidän perintöosamme on siirtynyt vieraille, meidän talomme muukalaisille.'),
(1689408,58,25,5,3,'Me olemme tulleet orvoiksi, isättömiksi, meidän äitimme ovat kuin lesket.'),
(1689409,58,25,5,4,'Oman juomavetemme me ostamme rahalla; omat puumme saamme, jos maksamme hinnan.'),
(1689410,58,25,5,5,'Vainoojamme ovat meidän niskassamme; kun uuvumme, ei meille lepoa suoda.'),
(1689411,58,25,5,6,'Egyptille me lyömme kättä ja Assurille saadaksemme leipää ravinnoksi.'),
(1689412,58,25,5,7,'Meidän isämme ovat syntiä tehneet; heitä ei enää ole. Me kannamme heidän syntivelkaansa.'),
(1689413,58,25,5,8,'Orjat hallitsevat meitä; ei ole sitä, joka tempaisi meidät heidän käsistänsä.'),
(1689414,58,25,5,9,'Henkemme kaupalla me noudamme leipämme, väistäen miekkaa erämaassa.'),
(1689415,58,25,5,10,'Meidän ihomme halkeilee kuin uuni nälän poltteiden takia.'),
(1689416,58,25,5,11,'Naisia raiskataan Siionissa, neitsyitä Juudan kaupungeissa.'),
(1689417,58,25,5,12,'Ruhtinaita heidän kätensä hirttävät, vanhinten kasvoja ei pidetä arvossa.'),
(1689418,58,25,5,13,'Nuorukaiset kantavat myllynkiviä, poikaset kompastelevat puutaakkojen alla.'),
(1689419,58,25,5,14,'Poissa ovat vanhukset porteista, nuorukaiset kielisoittimiensa äärestä.'),
(1689420,58,25,5,15,'Poissa on ilo sydämistämme, karkelomme on valitukseksi muuttunut.'),
(1689421,58,25,5,16,'Pudonnut on päästämme kruunu. Voi meitä, sillä me olemme syntiä tehneet!'),
(1689422,58,25,5,17,'Tästä syystä on sydämemme tullut sairaaksi, näitten tähden ovat silmämme pimenneet -'),
(1689423,58,25,5,18,'Siionin vuoren tähden, joka on autiona, jolla ketut juoksentelevat.'),
(1689424,58,25,5,19,'Sinä, Herra, hallitset iankaikkisesti, sinun valtaistuimesi pysyy suvusta sukuun.'),
(1689425,58,25,5,20,'Miksi unhotat meidät ainiaaksi, hylkäät meidät ikipäiviksi?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689426,58,25,5,21,'Palauta meidät, Herra, tykösi, niin me palajamme; uudista meidän päivämme muinaiselleen.'),
(1689427,58,26,1,1,'Kolmantenakymmenentenä vuotena, neljännessä kuussa, kuukauden viidentenä päivänä, kun minä olin pakkosiirtolaisten joukossa Kebar-joen varrella, aukenivat taivaat, ja minä näin Jumalan näkyjä.'),
(1689428,58,26,1,2,'Kuukauden viidentenä päivänä, kuningas Joojakinin pakkosiirtolaisuuden viidentenä vuotena,'),
(1689429,58,26,1,3,'tuli Jumalan sana pappi Hesekielille, Buusin pojalle, Kaldean maassa Kebar-joen varrella, ja hänen päällensä tuli siellä Herran käsi.'),
(1689430,58,26,1,4,'Ja minä näin, ja katso: myrskytuuli tuli pohjoisesta, suuri pilvi ja leimahteleva tuli, ja pilveä ympäröitsi hohde, ja tulen keskeltä näkyi ikäänkuin hehkuvaa malmia, keskeltä tulta.'),
(1689431,58,26,1,5,'Ja sen keskeltä näkyivät neljän olennon hahmot. Ja näöltänsä ne olivat tällaiset: niillä oli ihmisen hahmo.'),
(1689432,58,26,1,6,'Ja niillä oli neljät kasvot kullakin ja neljä siipeä kullakin.'),
(1689433,58,26,1,7,'Ja säärivarret niillä oli suorat ja jalkaterät kuin vasikansorkat, ja ne välkkyivät kuin kiiltävä vaski.'),
(1689434,58,26,1,8,'Ja siipiensä alla niillä oli, neljällä eri puolellansa, ihmiskädet. Kasvot ja siivet niillä neljällä olivat näin:'),
(1689435,58,26,1,9,'Niiden siivet koskettivat toisiansa. Kulkiessaan ne eivät kääntyneet: ne kulkivat kukin suoraan eteenpäin.'),
(1689436,58,26,1,10,'Ja niiden kasvot olivat ihmiskasvojen kaltaiset; mutta oikealla puolen oli niillä neljällä leijonankasvot, vasemmalla puolen oli niillä neljällä häränkasvot, myös oli niillä neljällä kotkankasvot.'),
(1689437,58,26,1,11,'Niin niiden kasvot. Mutta siivet niillä oli levällään ylöspäin. Kullakin oli kaksi, jotka koskettivat toisen siipiä, ja kaksi, joilla ne peittivät ruumistansa.'),
(1689438,58,26,1,12,'Ja ne kulkivat suoraan eteenpäin. Minne henki vaati kulkemaan, sinne ne kulkivat. Kulkiessaan ne eivät kääntyneet.'),
(1689439,58,26,1,13,'Ja olentojen hahmo oli näöltänsä kuin tuliset hiilet, jotka paloivat tulisoihtujen näköisinä. Tulta liekehti olentojen välissä, ja tuli hohti, ja tulesta lähti salamoita.'),
(1689440,58,26,1,14,'Ja olennot kiitivät edestakaisin ja olivat nähdä kuin salamanleimaus.'),
(1689441,58,26,1,15,'Mutta kun minä katselin olentoja, niin katso: yksi pyörä oli maassa olentojen kohdalla, kunkin niiden neljän etupuolella.'),
(1689442,58,26,1,16,'Pyörät olivat näöltään ja teoltaan niinkuin krysoliitti, ja niillä neljällä oli sama muoto, ja ne olivat näöltään ja teoltaan, kuin olisi ollut sisäkkäin pyörä pyörässä.'),
(1689443,58,26,1,17,'Ne kulkivat neljään eri suuntaansa, kun kulkivat.'),
(1689444,58,26,1,18,'Kulkiessaan ne eivät kääntyneet. Ja niiden kehät olivat korkeat ja peljättävät; ja niiden kehät olivat täynnä silmiä, yltympäri, niissä neljässä.'),
(1689445,58,26,1,19,'Ja kun olennot kulkivat, kulkivat pyörät niiden ohella; ja kun olennot kohosivat ylös maasta, kohosivat myös pyörät.'),
(1689446,58,26,1,20,'Minne henki vaati kulkemaan, sinne ne kulkivat - minne vain henki kulkemaan vaati. Ja pyörät kohosivat samalla kuin nekin, sillä olentojen henki oli pyörissä.'),
(1689447,58,26,1,21,'Kun olennot kulkivat, kulkivat nämäkin; kun ne seisoivat, seisoivat nämäkin; kun ne kohosivat ylös maasta, kohosivat pyörät samalla kuin nekin, sillä olentojen henki oli pyörissä.'),
(1689448,58,26,1,22,'Ja olentojen päitten ylle hahmottui taivaanvahvuus, niinkuin peljättävä kristalli, kaartuen ylös niiden päitten ylitse.'),
(1689449,58,26,1,23,'Ja taivaanvahvuuden alla oli niillä siivet suorina, toisen siipi toisen siipeä kohti. Kullakin oli kaksi, jotka sitä peittivät - kaksi, jotka peittivät sen ruumista.'),
(1689450,58,26,1,24,'Ja minä kuulin niiden siipien kohinan niinkuin paljojen vetten kohinan, niinkuin Kaikkivaltiaan jylinän, kun ne kulkivat; pauhinan ääni oli niinkuin sotaleirin pauhu. Kun ne seisoivat, laskivat ne siipensä alas.'),
(1689451,58,26,1,25,'Ja kuului ääni taivaanvahvuuden yläpuolelta, joka oli niitten pään päällä. - Kun ne seisoivat, laskivat ne siipensä alas.'),
(1689452,58,26,1,26,'Ja taivaanvahvuuden yläpuolella, joka oli niitten pään päällä, oli valtaistuimen muotoinen, näöltään kuin safiirikiveä. Ja valtaistuimen muotoisella istui hahmo, ihmisen näköinen, kohoten korkealle.'),
(1689453,58,26,1,27,'Ja minä näin ikäänkuin hehkuvaa malmia, tulen näköistä, jota ympäröi kehä ylöspäin siitä, mikä näytti hänen lanteiltansa; ja alaspäin siitä, mikä näytti hänen lanteiltansa, minä näin kuin tulen näköistä, ja sitä ympäröitsi hohde.'),
(1689454,58,26,1,28,'Kuin kaari, joka on pilvessä sadepäivänä, niin oli näöltään sitä ympäröivä hohde. Senkaltainen oli katsoa Herran kirkkauden hahmo. Ja kun minä sen näin, lankesin minä kasvoilleni. Ja minä kuulin äänen, kun joku puhui.'),
(1689455,58,26,2,1,'Ja hän sanoi minulle: "Ihmislapsi, nouse jaloillesi, niin minä puhuttelen sinua".'),
(1689456,58,26,2,2,'Niin minuun tuli henki, kun hän puhui minulle, ja se nosti minut jaloilleni, ja minä kuulin hänen puhuvan minulle.'),
(1689457,58,26,2,3,'Ja hän sanoi minulle: "Ihmislapsi, minä lähetän sinut israelilaisten tykö, kapinallisten pakanain tykö, jotka ovat kapinoineet minua vastaan; he ja heidän isänsä ovat luopuneet minusta, hamaan tähän päivään asti.'),
(1689458,58,26,2,4,'Nuo lapset, joilla on kovat kasvot ja paatuneet sydämet - niitten luokse minä sinut lähetän, ja sinun on sanottava heille: Näin sanoo Herra, Herra.'),
(1689459,58,26,2,5,'Kuulkoot tai olkoot kuulematta - sillä uppiniskainen suku he ovat - he tulevat kuitenkin tietämään, että profeetta on ollut heidän keskellänsä.'),
(1689460,58,26,2,6,'Mutta sinä, ihmislapsi, älä pelkää heitä, äläkä pelkää heidän sanojansa, vaikka edessäsi on ohdakkeita ja orjantappuroita ja sinä asut skorpionien seassa; älä pelkää heidän sanojansa äläkä arkaile heidän kasvojansa, sillä he ovat uppiniskainen suku.'),
(1689461,58,26,2,7,'Vaan puhu heille minun sanani, kuulkoot tai olkoot kuulematta; sillä uppiniskaisia he ovat.'),
(1689462,58,26,2,8,'Mutta sinä, ihmislapsi, kuule, mitä minä sinulle sanon. Älä ole uppiniskainen, niinkuin uppiniskainen suku on. Avaa suusi ja syö, mitä minä sinulle annan."'),
(1689463,58,26,2,9,'Niin minä näin, ja katso: käsi ojennettiin minua kohti, ja katso: siinä oli kirjakäärö.'),
(1689464,58,26,2,10,'Ja hän levitti sen minun eteeni, ja katso: se oli kirjoitettu täyteen sisältä ja päältä. Ja siihen oli kirjoitettu itkuvirret ja huokaukset ja voi-huudot.'),
(1689465,58,26,3,1,'Ja hän sanoi minulle: "Ihmislapsi, syö, minkä tässä saat; syö tämä kirjakäärö, mene ja puhu Israelin heimolle".'),
(1689466,58,26,3,2,'Niin minä avasin suuni, ja hän antoi tämän kirjakäärön minun syödäkseni.'),
(1689467,58,26,3,3,'Ja hän sanoi minulle: "Ihmislapsi, ravitse vatsasi ja täytä sisälmyksesi tällä kirjakääröllä, jonka minä sinulle annan". Niin minä söin, ja se oli minun suussani makea kuin hunaja.'),
(1689468,58,26,3,4,'Ja hän sanoi minulle: "Ihmislapsi, mene nyt Israelin heimon tykö ja puhu heille minun sanani.'),
(1689469,58,26,3,5,'Sillä ei sinua lähetetä outokielisen ja kankeapuheisen kansan tykö, vaan Israelin heimon tykö;'),
(1689470,58,26,3,6,'ei monien kansojen tykö, outokielisten ja kankeapuheisten, joiden puhetta et ymmärrä. Jos niiden tykö lähettäisin sinut, he sinua kuulisivat.'),
(1689471,58,26,3,7,'Mutta Israelin heimo ei tahdo sinua kuulla, koska he eivät tahdo minua kuulla. Sillä koko Israelin heimolla on kova otsa ja paatunut sydän.'),
(1689472,58,26,3,8,'Katso, minä teen sinun kasvosi yhtä koviksi kuin heidän kasvonsa ja sinun otsasi yhtä kovaksi kuin heidän otsansa.'),
(1689473,58,26,3,9,'Timantin kaltaiseksi, kiveä kovemmaksi minä teen sinun otsasi. Älä pelkää heitä äläkä arkaile heidän kasvojansa, sillä he ovat uppiniskainen suku."'),
(1689474,58,26,3,10,'Ja hän sanoi minulle: "Ihmislapsi, kaikki minun sanani, jotka minä sinulle puhun, ota sydämeesi ja kuule korvillasi.'),
(1689475,58,26,3,11,'Ja nyt mene pakkosiirtolaisten tykö, kansasi lasten tykö; puhu heille ja sano heille: Näin sanoo Herra, Herra - kuulkoot he tai olkoot kuulematta."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689476,58,26,3,12,'Niin henki nosti minut, ja minä kuulin takaani suuren, jylisevän äänen: "Kiitetty olkoon Herran kirkkaus, siinä kussa se on!"'),
(1689477,58,26,3,13,'ja olentojen siipien kohinan, kun ne löivät toisiinsa, samalla pyöräin jyrinän ja suuren, jylisevän äänen.'),
(1689478,58,26,3,14,'Ja henki nosti minut ja otti minut, ja minä kuljin murheellisena henkeni kiivaudessa, ja Herran käsi oli väkevänä minun päälläni.'),
(1689479,58,26,3,15,'Ja minä tulin Tell-Aabibiin pakkosiirtolaisten tykö, jotka asuivat Kebar-joen varrella; ja siellä, missä he asuivat, minä istuin jäykistyneenä heidän keskuudessaan seitsemän päivää.'),
(1689480,58,26,3,16,'Mutta seitsemän päivän kuluttua tuli minulle tämä Herran sana:'),
(1689481,58,26,3,17,'"Ihmislapsi, minä olen asettanut sinut Israelin heimolle vartijaksi. Kun kuulet sanan minun suustani, on sinun varoitettava heitä minun puolestani.'),
(1689482,58,26,3,18,'Jos minä sanon jumalattomalle: sinun on kuolemalla kuoltava, mutta sinä et häntä varoita etkä puhu varoittaaksesi jumalatonta hänen jumalattomasta tiestänsä, että pelastaisit hänen henkensä, niin jumalaton kuolee synnissänsä, mutta hänen verensä minä vaadin sinun kädestäsi.'),
(1689483,58,26,3,19,'Mutta jos sinä varoitat jumalatonta ja hän ei käänny jumalattomuudestansa eikä jumalattomalta tieltänsä, niin hän kuolee synnissänsä, mutta sinä olet sielusi pelastanut.'),
(1689484,58,26,3,20,'Ja jos vanhurskas kääntyy pois vanhurskaudestansa ja tekee vääryyttä ja minä panen kompastuksen hänen eteensä, niin hän kuolee - kun et sinä häntä varoittanut, niin hän synnissänsä kuolee, ja vanhurskautta, jota hän oli harjoittanut, ei muisteta - mutta hänen verensä minä vaadin sinun kädestäsi.'),
(1689485,58,26,3,21,'Mutta jos sinä vanhurskasta varoitat, ettei vanhurskas tekisi syntiä, ja hän ei tee syntiä, niin hän totisesti saa elää, koska otti varoituksesta vaarin, ja sinä olet sielusi pelastanut."'),
(1689486,58,26,3,22,'Herran käsi tuli siellä minun päälleni, ja hän sanoi minulle: "Nouse ja mene laaksoon, niin minä siellä puhuttelen sinua".'),
(1689487,58,26,3,23,'Niin minä nousin ja menin laaksoon, ja katso, siellä seisoi Herran kirkkaus, samankaltainen kuin kirkkaus, jonka minä olin nähnyt Kebar-joen varrella. Ja minä lankesin kasvoilleni.'),
(1689488,58,26,3,24,'Mutta minuun tuli henki ja nosti minut jaloilleni, ja hän puhutteli minua ja sanoi minulle: "Mene, sulkeudu sisälle huoneeseesi.'),
(1689489,58,26,3,25,'Ja sinä, ihmislapsi! Katso, sinut pannaan köysiin ja sidotaan niillä, niin ettet voi mennä ulos heidän keskuuteensa.'),
(1689490,58,26,3,26,'Ja minä tartutan sinun kielesi suusi lakeen, niin että mykistyt etkä voi olla heille nuhtelijana, sillä he ovat uppiniskainen suku.'),
(1689491,58,26,3,27,'Mutta kun minä puhuttelen sinua, avaan minä sinun suusi, ja sinun on sanottava heille: Näin sanoo Herra, Herra. Kuulkoon, joka kuulee, ja olkoon kuulematta, joka ei kuule; sillä he ovat uppiniskainen suku."'),
(1689492,58,26,4,1,'"Ja sinä, ihmislapsi, ota itsellesi tiilikivi ja aseta se eteesi ja piirrä siihen kaupunki, Jerusalem.'),
(1689493,58,26,4,2,'Ja pane se piirityksiin, rakenna sitä vastaan saartovarusteet, luo sitä vastaan valli, aseta sitä vastaan sotaleirejä ja pane sitä vastaan yltympäri muurinmurtajia.'),
(1689494,58,26,4,3,'Ota sitten itsellesi rautainen leivinlevy ja aseta se rautamuuriksi itsesi ja kaupungin väliin ja suuntaa kasvosi kaupunkia kohti, niin että se tulee piirityksiin, ja piiritä sitä. Tämä on oleva merkki Israelin heimolle.'),
(1689495,58,26,4,4,'Ja sinä pane maata vasemmalle kyljellesi ja aseta sitä painamaan Israelin heimon syntivelka. Yhtä monta päivää, kuin sinä makaat sillä, on sinun kannettava heidän syntivelkaansa.'),
(1689496,58,26,4,5,'Ja minä panen sinulle saman luvun päiviä, kuin on heidän syntivelkansa vuosia: kolmesataa yhdeksänkymmentä päivää; niin sinun on kannettava Israelin heimon syntivelkaa.'),
(1689497,58,26,4,6,'Ja kun olet saanut ne päättymään, on sinun pantava maata toistamiseen, oikealle kyljellesi, ja kannettava Juudan heimon syntivelkaa neljäkymmentä päivää; päivän kutakin vuotta kohti minä olen sinulle pannut.'),
(1689498,58,26,4,7,'Ja suuntaa kasvosi ja paljastettu käsivartesi piiritettyä Jerusalemia kohti ja ennusta sitä vastaan.'),
(1689499,58,26,4,8,'Ja katso, minä panen sinut köysiin, niin ettet voi kääntyä kyljeltä toiselle, kunnes olet saanut päättymään piirityspäiväsi.'),
(1689500,58,26,4,9,'Ota sinä myös itsellesi nisuja, ohria, papuja, herneitä, hirssiä ja kolmitahkoista vehnää, pane ne samaan astiaan ja tee niistä itsellesi leipää. Yhtä monta päivää, kuin makaat kyljelläsi, kolmesataa yhdeksänkymmentä päivää, on sinun syötävä sitä.'),
(1689501,58,26,4,10,'Ja ruoka, jota syöt, on sinun syötävä painon mukaan: kaksikymmentä sekeliä päivässä; sinun on syötävä se määräaikana.'),
(1689502,58,26,4,11,'Ja vettä sinun on juotava mitan mukaan: kuudennes hiin-mittaa; sinun on juotava määräaikana.'),
(1689503,58,26,4,12,'Ja ohrakaltiaisena on sinun se syötävä, ja ihmisulostuksella on sinun se paistettava heidän silmäinsä edessä."'),
(1689504,58,26,4,13,'Ja Herra sanoi: "Näin tulevat israelilaiset syömään leipänsä saastaisena pakanain joukossa, jonne minä heidät karkoitan".'),
(1689505,58,26,4,14,'Mutta minä sanoin: "Voi Herra, Herra! Katso, ei milloinkaan ole minun sieluni ollut saastutettu, minä en ole syönyt itsestään kuollutta enkä kuoliaaksi raadeltua nuoruudestani tähän asti, eikä ole mitään saastaista lihaa minun suuhuni tullut."'),
(1689506,58,26,4,15,'Niin hän sanoi minulle: "Katso, minä annan sinulle eläimen lannan ihmisen jäljen sijaan; valmista leipäsi sen päällä".'),
(1689507,58,26,4,16,'Ja hän sanoi minulle: "Ihmislapsi, katso, minä murran leivän tuen Jerusalemilta, ja he saavat syödä leipää painon mukaan ja huolissansa sekä juoda vettä mitan mukaan ja kauhuissansa,'),
(1689508,58,26,4,17,'niin että he joutuvat leivän ja veden puutteeseen ja yhdessä nääntyvät ja riutuvat syntivelkansa tähden".'),
(1689509,58,26,5,1,'"Ja sinä, ihmislapsi, ota itsellesi terävä miekka; ota se partaveitseksesi, ja ajele sillä hiuksesi ja partasi. Ota sitten vaaka ja jaa ne.'),
(1689510,58,26,5,2,'Polta kolmannes tulessa keskellä kaupunkia, sittenkuin piirityspäivät ovat lopussa. Kolmannes ota ja lyö miekalla sen ympärillä. Kolmannes hajota tuuleen, ja minä ajan niitä takaa paljastetulla miekalla;'),
(1689511,58,26,5,3,'ota niistä sitten vähäinen määrä ja sido ne helmukseesi,'),
(1689512,58,26,5,4,'ja ota niistä vielä osa, viskaa ne tuleen ja polta ne tulessa. Siitä lähtee tuli koko Israelin heimoon.'),
(1689513,58,26,5,5,'Näin sanoo Herra, Herra: Tämä on Jerusalem; pakanain keskelle minä olen sen asettanut, ja niiden maat ovat sen ympärillä.'),
(1689514,58,26,5,6,'Mutta se on niskoitellut minun oikeuksiani vastaan jumalattomammin kuin pakanat ja minun käskyjäni vastaan jumalattomammin kuin maat, jotka ovat sen ympärillä; sillä minun oikeuteni he ovat pitäneet halpoina ja minun käskyjeni mukaan he eivät ole vaeltaneet.'),
(1689515,58,26,5,7,'Sentähden, näin sanoo Herra, Herra: Koska teidän metelinne on ollut pahempi kuin pakanain, jotka ympärillänne ovat, ja koska te ette ole vaeltaneet minun käskyjeni mukaan, ette ole noudattaneet minun oikeuksiani ettekä ole tehneet niiden pakanainkaan oikeuksien mukaan, jotka ympärillänne ovat,'),
(1689516,58,26,5,8,'sentähden, näin sanoo Herra, Herra: Katso, myös minä käyn sinun kimppuusi ja teen tuomiot sinun keskelläsi pakanain silmien edessä'),
(1689517,58,26,5,9,'ja teen sinulle kaikkien kauhistustesi tähden, mitä en ole ennen tehnyt ja minkäkaltaista en vasta ole tekevä.'),
(1689518,58,26,5,10,'Sentähden tulevat sinun keskelläsi isät syömään lapsiansa, ja lapset tulevat syömään isiänsä, ja minä teen sinussa tuomiot ja hajotan sinun jäännöksesi kaikkiin tuuliin.'),
(1689519,58,26,5,11,'Sentähden, niin totta kuin minä elän, sanoo Herra, Herra: Totisesti, koska olet saastuttanut minun pyhäkköni kaikilla iljetyksilläsi ja kaikilla kauhistuksillasi, käännyn minäkin pois, en sääli enkä armahda.'),
(1689520,58,26,5,12,'Kolmannes sinusta kuolee ruttoon ja nääntyy nälkään sinun keskelläsi. Kolmannes kaatuu miekkaan sinun ympärilläsi. Kolmanneksen minä hajotan kaikkiin tuuliin, ja minä ajan niitä takaa paljastetulla miekalla.'),
(1689521,58,26,5,13,'Ja minun vihani täyttyy, ja minä tyydytän kiivauteni heissä ja kostan. Ja he tulevat tietämään, että minä, Herra, olen puhunut kiivaudessani, kun minä panen vihani täytäntöön heissä.'),
(1689522,58,26,5,14,'Ja minä teen sinut raunioksi ja häväistyksi pakanain kesken, jotka sinun ympärilläsi ovat, jokaisen ohikulkijan silmäin edessä.'),
(1689523,58,26,5,15,'Ja se on oleva häväistys ja herjaus, varoitus ja peljätys pakanain seassa, jotka ympärilläsi ovat, kun minä teen sinussa tuomiot vihassa ja kiivaudessa ja kiivailla rangaistuksilla - minä, Herra, olen puhunut -'),
(1689524,58,26,5,16,'kun minä lähetän heidän kimppuunsa nälän pahat nuolet, joista tulee tuhooja ja jotka minä lähetän teitä tuhoamaan; ja minä vielä lisään teille nälkää ja murran teiltä leivän tuen.'),
(1689525,58,26,5,17,'Ja minä lähetän teidän kimppuunne nälän ja pahat petoeläimet, jotka riistävät sinulta lapset; rutto ja veri käyvät sinun ylitsesi, ja minä annan miekan tulla sinun ylitsesi. Minä, Herra, olen puhunut."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689526,58,26,6,1,'Minulle tuli tämä Herran sana:'),
(1689527,58,26,6,2,'"Ihmislapsi, käännä kasvosi Israelin vuoria kohti ja ennusta niitä vastaan'),
(1689528,58,26,6,3,'ja sano: Israelin vuoret, kuulkaa Herran, Herran sana. Näin sanoo Herra, Herra vuorille ja kukkuloille, puronotkoille ja laaksoille: Katso, minä annan miekan tulla teidän ylitsenne ja hävitän teidän uhrikukkulanne.'),
(1689529,58,26,6,4,'Teidän alttarinne jäävät autioiksi, auringonpatsaanne murskataan, ja teidän surmattujenne minä annan kaatua teidän kivijumalainne eteen.'),
(1689530,58,26,6,5,'Minä panen israelilaisten ruumiit heidän kivijumalainsa eteen ja hajotan heidän luunsa heidän alttariensa ympärille.'),
(1689531,58,26,6,6,'Kaikilla teidän asuinpaikoillanne tulevat kaupungit raunioiksi ja uhrikukkulat autioiksi; niin jäävät teidän alttarinne raunioiksi ja autioiksi, teidän kivijumalanne murskataan ja hävitetään, teidän auringonpatsaanne särjetään, ja teidän tekeleenne pyyhkäistään pois,'),
(1689532,58,26,6,7,'surmattuja kaatuu teidän keskellänne, ja te tulette tietämään, että minä olen Herra.'),
(1689533,58,26,6,8,'Mutta minä jätän jäännöksen: teillä on oleva miekasta pelastuneita pakanain seassa, kun teidät on hajotettu niiden maihin;'),
(1689534,58,26,6,9,'ja ne teistä, jotka pelastuvat, muistavat minut pakanain seassa, mihin ovat vangeiksi viedyt, sillä minä särjen heidän haureellisen sydämensä, joka poikkesi minusta pois, ja heidän silmänsä, jotka haureellisina kulkivat heidän kivijumalainsa jäljessä. Ja heitä kyllästyttää oma itsensä pahain töitten tähden, joita he ovat tehneet, kaikkien heidän kauhistustensa tähden.'),
(1689535,58,26,6,10,'Ja he tulevat tietämään, että minä olen Herra; en ole turhaan puhunut, että minä tuotan teille tämän onnettomuuden.'),
(1689536,58,26,6,11,'Näin sanoo Herra, Herra: Paukuta käsiäsi ja polje jalkaasi ja sano: ''voi!'' kaikista Israelin heimon häijyistä kauhistuksista, heidän, jotka kaatuvat miekkaan, nälkään ja ruttoon.'),
(1689537,58,26,6,12,'Kaukainen kuolee ruttoon, läheinen kaatuu miekkaan, jäljellejäänyt ja säilynyt kuolee nälkään, ja minä panen vihani täytäntöön heissä.'),
(1689538,58,26,6,13,'Ja te tulette tietämään, että minä olen Herra, kun heitä on surmattuina heidän kivijumalainsa keskellä, heidän alttariensa ympärillä, jokaisella korkealla kukkulalla, kaikilla vuorten huipuilla, jokaisen viheriän puun alla ja jokaisen tuuhean tammen alla, missä paikassa vain he ovat tarinneet suloista tuoksua kaikille kivijumalillensa.'),
(1689539,58,26,6,14,'Ja minä ojennan käteni heitä vastaan ja teen maan autiommaksi ja hävitetymmäksi, kuin on Diblatan erämaa, kaikilla heidän asuinpaikoillansa; ja he tulevat tietämään, että minä olen Herra."'),
(1689540,58,26,7,1,'Minulle tuli tämä Herran sana:'),
(1689541,58,26,7,2,'"Sinä, ihmislapsi, näin sanoo Herra, Herra Israelin maalle: Loppu! Maan neljälle äärelle tulee loppu.'),
(1689542,58,26,7,3,'Nyt tulee sinulle loppu, ja minä lähetän vihani sinua vastaan, tuomitsen sinut vaelluksesi mukaan ja annan kaikkien kauhistustesi kohdata sinua.'),
(1689543,58,26,7,4,'En sääli sinua enkä armahda, vaan annan vaelluksesi kohdata sinua, ja kauhistuksesi tulevat sinun keskellesi, ja te tulette tietämään, että minä olen Herra.'),
(1689544,58,26,7,5,'Näin sanoo Herra, Herra: Onnettomuus! Yksi ja ainoa onnettomuus! Katso, se tulee!'),
(1689545,58,26,7,6,'Loppu tulee, tulee loppu! Se heräjää sinua vastaan! Katso, se tulee!'),
(1689546,58,26,7,7,'Vuoro tulee sinulle, maan asuja. Aika tulee, päivä on lähellä: hämminki, ei ilohuuto vuorilta.'),
(1689547,58,26,7,8,'Nyt minä kohta vuodatan kiivauteni sinun ylitsesi, panen vihani täytäntöön sinussa, tuomitsen sinut vaelluksesi mukaan ja annan kaikkien kauhistustesi kohdata sinua.'),
(1689548,58,26,7,9,'En sääli enkä armahda; minä annan vaelluksesi kohdata sinua, ja kauhistuksesi tulevat sinun keskellesi, ja te tulette tietämään, että minä, Herra, olen se, joka lyön.'),
(1689549,58,26,7,10,'Katso, päivä! Katso, se tulee! Vuoro on tullut, vitsa kukkii, julkeus versoo.'),
(1689550,58,26,7,11,'Väkivalta on noussut vitsaksi jumalattomuudelle, ei mitään jää heistä, ei heidän pauhaavasta joukostansa, ei heidän melustansa; poissa on heidän komeutensa.'),
(1689551,58,26,7,12,'Tullut on aika, joutunut päivä, älköön ostaja iloitko, älköön myyjä murehtiko, sillä viha tulee kaiken siellä pauhaavan joukon ylitse.'),
(1689552,58,26,7,13,'Sillä myyjä ei enää palaja myynnöksillensä, vaikka he vielä jäisivätkin henkiin, sillä näky kaikkea sen pauhaavaa joukkoa vastaan ei peräydy, eikä kukaan synnillänsä vahvista elämäänsä.'),
(1689553,58,26,7,14,'Puhalletaan torviin, varustetaan kaikki, mutta ei ole lähtijää sotaan, sillä minun vihani tulee kaiken siellä pauhaavan joukon ylitse.'),
(1689554,58,26,7,15,'Miekka on ulkona, sisällä rutto ja nälkä. Kedolla oleva kuolee miekkaan, kaupungissa olevan syö nälkä ja rutto.'),
(1689555,58,26,7,16,'Ja jos heitä joitakin pelastuu ja pääsee pakoon, ovat he vuorilla kuin laaksojen kyyhkyset, ja he vaikertelevat kaikki, syntiänsä kukin.'),
(1689556,58,26,7,17,'Kaikki kädet herpoavat, kaikki polvet käyvät veltoiksi kuin vesi.'),
(1689557,58,26,7,18,'He kääriytyvät säkkeihin, heidät peittää vavistus, kaikilla kasvoilla on häpeä, ja kaikki päät ovat paljaiksi ajellut.'),
(1689558,58,26,7,19,'Hopeansa he viskaavat kaduille, ja heidän kultansa tulee heille saastaksi. Heidän kultansa ja hopeansa eivät voi heitä pelastaa Herran vihan päivänä, eivät he sillä nälkäänsä tyydytä eivätkä vatsaansa täytä; sillä siitä tuli heille kompastus syntiin.'),
(1689559,58,26,7,20,'Siitä tehtyjen korujen loistolla he ylpeilivät, siitä he tekivät kauhistavat kuvansa, iljetyksensä; sentähden minä teen sen heille saastaksi.'),
(1689560,58,26,7,21,'Ja minä annan sen vieraitten käsiin ryöstettäväksi ja maan jumalattomien saaliiksi, ja ne häpäisevät sen.'),
(1689561,58,26,7,22,'Minä käännän kasvoni heistä pois, niin että minun aarteeni häväistään: väkivaltaiset menevät sinne ja häpäisevät sen.'),
(1689562,58,26,7,23,'Valmista kahle, sillä maa on täynnä verivelkain tuomiota, ja kaupunki on täynnä väkivaltaa.'),
(1689563,58,26,7,24,'Ja minä tuon pakanoista pahimmat, ja ne ottavat omiksensa teidän talonne. Minä teen lopun voimallisten ylpeydestä, ja heidän pyhäkkönsä häväistään.'),
(1689564,58,26,7,25,'Tulee hätä, ja he etsivät pelastusta, mutta sitä ei ole.'),
(1689565,58,26,7,26,'Häviö tulee häviön jälkeen, sanoma tulee sanoman jälkeen. He havittelevat näkyä profeetalta; papilta katoaa opetus ja vanhimmilta neuvo.'),
(1689566,58,26,7,27,'Kuningas murehtii, päämies pukeutuu kauhuun, ja maan kansan kädet pelosta vapisevat. Minä teen heille heidän teittensä mukaan, ja tuomitsen heidät heidän tuomioittensa mukaan, ja he tulevat tietämään, että minä olen Herra."'),
(1689567,58,26,8,1,'Kuudentena vuotena, kuudennessa kuussa, kuukauden viidentenä päivänä minä istuin huoneessani, ja Juudan vanhimmat istuivat minun edessäni; silloin Herran, Herran käsi laskeutui siellä minun päälleni.'),
(1689568,58,26,8,2,'Ja minä näin, ja katso: tulennäköinen hahmo! Ja alaspäin siitä, mikä näytti sen lanteilta, oli tulta, ja ylöspäin sen lanteista näkyi loiste, joka oli nähdä niinkuin hehkuva malmi.'),
(1689569,58,26,8,3,'Hän ojensi ikäänkuin käden ja otti minua pääni hiussuortuvasta, ja henki nosti minut maan ja taivaan välille ja vei minut Jerusalemiin Jumalan näyissä, sisemmän portin ovelle, joka on pohjoista kohden, sinne missä oli kiivauspatsas, joka oli herättänyt Herran kiivauden.'),
(1689570,58,26,8,4,'Ja katso, siellä oli Israelin Jumalan kirkkaus, samankaltainen nähdä kuin se, minkä minä olin nähnyt laaksossa.'),
(1689571,58,26,8,5,'Hän sanoi minulle: "Ihmislapsi, nosta silmäsi pohjoista kohti". Niin minä nostin silmäni pohjoista kohti, ja katso: pohjoiseen päin alttariportista oli tuo kiivauspatsas sisäänkäytävässä.'),
(1689572,58,26,8,6,'Ja hän sanoi minulle: "Ihmislapsi, näetkö sinä, mitä he tekevät - suuria kauhistuksia, joita Israelin heimo tekee täällä, että minä menisin kauas pois pyhäköstäni? Mutta sinä saat nähdä vielä suurempia kauhistuksia."'),
(1689573,58,26,8,7,'Ja hän vei minut esipihan ovelle, ja minä näin, ja katso: seinässä oli jokin aukko.'),
(1689574,58,26,8,8,'Ja hän sanoi minulle: "Ihmislapsi, murtaudu läpi seinän".'),
(1689575,58,26,8,9,'Niin minä murtauduin läpi seinän, ja katso: jokin ovi! Ja hän sanoi minulle: "Mene ja katso häijyjä kauhistuksia, joita he täällä tekevät".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689576,58,26,8,10,'Niin minä menin ja näin, ja katso: kaikenkaltaisia inhottavia matelijain ja karjaeläinten kuvia ja kaikenkaltaisia Israelin heimon kivijumalia oli piirretty seinään yltympäri.'),
(1689577,58,26,8,11,'Ja niiden edessä seisoi seitsemänkymmentä miestä, Israelin heimon vanhimpia, ja näiden keskellä seisoi Jaasanja, Saafanin poika; ja kullakin heillä oli suitsutusastiansa kädessään, ja suitsutuspilvestä nousi tuoksu.'),
(1689578,58,26,8,12,'Niin hän sanoi minulle: "Näetkö, ihmislapsi, mitä Israelin heimon vanhimmat tekevät pimeässä, itsekukin kuvakammiossansa? Sillä he sanovat:'),
(1689579,58,26,8,13,'''Ei Herra meitä näe; Herra on hyljännyt tämän maan''." Ja hän sanoi minulle: "Sinä saat nähdä vieläkin suurempia kauhistuksia, joita he tekevät".'),
(1689580,58,26,8,14,'Ja hän vei minut Herran huoneen portin ovelle, joka on pohjoista kohden, ja katso: siellä istui naisia itkemässä Tammusta.'),
(1689581,58,26,8,15,'Ja hän sanoi minulle: "Näetkö, ihmislapsi? Vieläkin sinä saat nähdä kauhistuksia, vielä suurempia kuin nämä."'),
(1689582,58,26,8,16,'Ja hän vei minut Herran huoneen sisemmälle esipihalle, ja katso: Herran temppelin ovella, eteisen ja alttarin välillä, oli noin kaksikymmentä viisi miestä. Heillä oli selät Herran temppeliin päin ja kasvot itään päin, ja päin itää he kumarsivat aurinkoa.'),
(1689583,58,26,8,17,'Ja hän sanoi minulle: "Näitkö, ihmislapsi? Eikö ole Juudan heimolle kylliksi, että he tekevät kauhistuksia, joita täällä on tehty, koska he täyttävät maan väkivallalla ja niin aina uudelleen vihoittavat minut? Katso, kuinka he vievät viiniköynnöksen lehvää nenänsä eteen!'),
(1689584,58,26,8,18,'Mutta minäkin teen, minkä teen, vihassani: en sääli enkä armahda; ja vaikka he huutavat minun korviini suurella äänellä, minä en heitä kuule."'),
(1689585,58,26,9,1,'Sitten hän huusi suurella äänellä minun korviini ja sanoi: "Tulkaa, kaupungin rankaisijat, ja kullakin olkoon tuhoaseensa kädessään!"'),
(1689586,58,26,9,2,'Ja katso, kuusi miestä tuli Yläportilta päin, joka on pohjoista kohden, ja kullakin oli kädessä hävitysaseensa. Mutta yksi mies oli heidän keskellään, puettu pellavavaatteisiin ja vyöllänsä kirjoitusneuvot. Ja he tulivat ja asettuivat seisomaan vaskialttarin ääreen.'),
(1689587,58,26,9,3,'Mutta Israelin Jumalan kirkkaus oli kohonnut yläpuolelta kerubin, jonka yllä se oli ollut, huoneen kynnykselle ja huusi pellavavaatteisiin puetulle miehelle, jolla oli kirjoitusneuvot vyöllänsä;'),
(1689588,58,26,9,4,'ja Herra sanoi hänelle: "Kierrä kaupungin, Jerusalemin, läpi ja tee merkki niitten miesten otsiin, jotka huokaavat ja valittavat kaikkia kauhistuksia, mitä sen keskuudessa tehdään".'),
(1689589,58,26,9,5,'Ja niille toisille hän sanoi minun kuulteni: "Kiertäkää kaupungin läpi hänen jäljessään ja surmatkaa. Älkää säälikö, älkää armahtako,'),
(1689590,58,26,9,6,'tappakaa tyyten vanhukset, nuorukaiset, neitsyet, lapset ja vaimot, mutta älkää koskeko keneenkään, jolla on otsassaan merkki; ja alottakaa minun pyhäköstäni." Niin he alottivat niistä miehistä, vanhimmista, jotka olivat temppelin edessä.'),
(1689591,58,26,9,7,'Ja hän sanoi heille: "Saastuttakaa temppeli ja täyttäkää esipihat surmatuilla. Menkää!" Niin he menivät ja surmasivat kaupungissa.'),
(1689592,58,26,9,8,'Mutta kun minä heidän surmatessaan olin jäänyt jäljelle, lankesin minä kasvoilleni, huusin ja sanoin: "Voi Herra, Herra! Hävitätkö sinä Israelin koko jäännöksen, kun vuodatat vihasi Jerusalemin ylitse?"'),
(1689593,58,26,9,9,'Niin hän sanoi minulle: "Israelin ja Juudan heimon syntivelka on ylen suuri; maa on täynnä verivelkoja, ja kaupunki on täynnä oikeuden vääristelyä, sillä he sanovat: ''Herra on hyljännyt tämän maan, ei Herra näe''.'),
(1689594,58,26,9,10,'Niinpä minäkään en sääli enkä armahda. Minä annan heidän vaelluksensa tulla heidän oman päänsä päälle."'),
(1689595,58,26,9,11,'Ja katso, pellavavaatteisiin puettu mies, jolla oli kirjoitusneuvot vyöllänsä, toi tämän sanan: "Minä olen tehnyt, niinkuin sinä käskit minun tehdä".'),
(1689596,58,26,10,1,'Sitten minä näin, ja katso: taivaanvahvuuden yläpuolella, joka oli kerubien pään päällä, oli ikäänkuin safiirikivi, näöltään valtaistuimen kaltainen; se näkyi heidän yläpuolellansa.'),
(1689597,58,26,10,2,'Ja hän sanoi pellavavaatteisiin puetulle miehelle näin: "Mene rattaiden väliin, kerubin alle ja täytä kahmalosi tulisilla hiilillä kerubien välistä ja sirottele ne yli kaupungin". Niin hän meni minun silmäini edessä.'),
(1689598,58,26,10,3,'Ja kerubit seisoivat temppelin oikealla puolella, kun mies meni; ja pilvi peitti sisemmän esipihan.'),
(1689599,58,26,10,4,'Ja Herran kirkkaus kohosi kerubin yltä temppelin kynnykselle, ja pilvi täytti temppelin, ja esipiha tuli täyteen Herran kirkkauden hohdetta.'),
(1689600,58,26,10,5,'Ja kerubien siipien kohina kuului ulompaan esipihaan asti kuin kaikkivaltiaan Jumalan ääni, kun hän puhuu.'),
(1689601,58,26,10,6,'Ja kun hän käski pellavavaatteisiin puettua miestä sanoen: "Ota tulta rattaiden välistä, kerubien välistä", niin tämä meni ja seisahtui pyörän ääreen.'),
(1689602,58,26,10,7,'Ja kerubi ojensi kätensä kerubien välitse tuleen, joka oli kerubien välissä, otti sitä ja antoi pellavavaatteisiin puetun kahmaloon. Tämä otti sen ja meni ulos.'),
(1689603,58,26,10,8,'Silloin näkyi kerubeilla ikäänkuin ihmiskäsi heidän siipiensä alta.'),
(1689604,58,26,10,9,'Ja minä näin, ja katso: kerubien kohdalla oli neljä pyörää, yksi pyörä aina yhden kerubin ohella, ja pyörät olivat näöltään niinkuin krysoliittikivi.'),
(1689605,58,26,10,10,'Ja niillä neljällä näytti olevan sama muoto, niinkuin olisi ollut sisäkkäin pyörä pyörässä.'),
(1689606,58,26,10,11,'Ne kulkivat neljään eri suuntaansa, kun kulkivat. Kulkiessaan ne eivät kääntyneet, sillä minnepäin etumainen meni, sinne ne kulkivat sen jäljessä; ne eivät kääntyneet kulkiessaan.'),
(1689607,58,26,10,12,'Ja niillä oli koko ruumis ja selät ja kädet ja siivet ja pyörät täynnä silmiä, yltympäri.'),
(1689608,58,26,10,13,'Niillä neljällä oli pyöränsä; ja pyöriä nimitettiin minun kuulteni "rattaiksi".'),
(1689609,58,26,10,14,'Ja kullakin oli neljät kasvot: yhdet kerubinkasvot, toiset ihmiskasvot, kolmannet leijonankasvot ja neljännet kotkankasvot.'),
(1689610,58,26,10,15,'Ja kerubit kohosivat - ne olivat samat olennot, jotka minä olin nähnyt Kebar-joen varrella. -'),
(1689611,58,26,10,16,'Kun kerubit kulkivat, kulkivat pyörät niiden ohella, ja kun kerubit nostivat siipensä kohotaksensa ylös maasta, eivät myöskään pyörät kääntyneet pois niiden ohelta.'),
(1689612,58,26,10,17,'Kun ne seisahtuivat, seisahtuivat nämäkin, ja kun ne kohosivat, kohosivat nämä niiden kanssa, sillä olentojen henki oli näissä.'),
(1689613,58,26,10,18,'Sitten Herran kirkkaus lähti temppelin kynnykseltä ja asettui kerubien ylle.'),
(1689614,58,26,10,19,'Ja lähtiessään kerubit nostivat siipensä ja kohosivat maasta minun silmäini edessä, ja pyörät samalla kuin ne; ja ne seisahtuivat Herran huoneen itäportin ovelle, ja niiden yläpuolella oli Israelin Jumalan kirkkaus.'),
(1689615,58,26,10,20,'Nämä olivat samat olennot, jotka minä olin nähnyt Israelin Jumalan alla Kebar-joen varrella; ja minä tulin tietämään, että ne olivat kerubeja.'),
(1689616,58,26,10,21,'Neljät kasvot oli kullakin ja neljä siipeä kullakin, ja niiden siipien alla oli ikäänkuin ihmiskädet.'),
(1689617,58,26,10,22,'Ja niiden kasvot olivat muodoltaan samat, jotka minä olin nähnyt - sekä niiden näön että ne itsensä - Kebar-joen varrella. Ne kulkivat kukin suoraan eteenpäin.'),
(1689618,58,26,11,1,'Sitten Henki nosti minut ja vei minut Herran huoneen itäportille, joka on itään päin. Ja katso: portin ovella oli kaksikymmentä viisi miestä, ja minä näin niitten keskellä Jaasanjan, Assurin pojan, ja Pelatjan, Benajan pojan, kansan päämiehet.'),
(1689619,58,26,11,2,'Ja hän sanoi minulle: "Ihmislapsi, nämä ovat ne miehet, jotka miettivät turmiota ja pitävät pahaa neuvoa tätä kaupunkia vastaan,'),
(1689620,58,26,11,3,'jotka sanovat: ''Ei ole nyt kohta rakennettava taloja: se on pata, me olemme liha''.'),
(1689621,58,26,11,4,'Sentähden ennusta heitä vastaan, ennusta, ihmislapsi."'),
(1689622,58,26,11,5,'Niin Herran Henki laskeutui minun päälleni ja sanoi minulle: "Sano: Näin sanoo Herra: Näin te, Israelin heimo, sanotte, ja minä tunnen, mitä teidän hengestänne nousee.'),
(1689623,58,26,11,6,'Paljon on teidän surmaamianne tässä kaupungissa, ja sen kadut te olette surmatuilla täyttäneet.'),
(1689624,58,26,11,7,'Sentähden, näin sanoo Herra, Herra: Surmattunne, jotka te olette heittäneet sen keskelle, ne ovat liha, ja tämä kaupunki on pata, mutta teidät minä sen keskeltä vien pois.'),
(1689625,58,26,11,8,'Miekkaa te pelkäätte, mutta miekan minä annan tulla teidän päällenne, sanoo Herra, Herra.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689626,58,26,11,9,'Pois minä vien teidät sen keskeltä ja annan teidät muukalaisten käsiin ja teen teidän seassanne tuomiot.'),
(1689627,58,26,11,10,'Te kaadutte miekkaan, Israelin rajalla minä teidät tuomitsen; ja te tulette tietämään, että minä olen Herra.'),
(1689628,58,26,11,11,'Ei tämä tule teille padaksi ettekä te siihen lihaksi: Israelin rajalla minä teidät tuomitsen.'),
(1689629,58,26,11,12,'Ja te tulette tietämään, että minä olen Herra - te, jotka ette ole vaeltaneet minun käskyjeni mukaan ettekä ole tehneet minun oikeuksieni mukaan, vaan olette tehneet niiden pakanain oikeuksien mukaan, jotka ovat teidän ympärillänne."'),
(1689630,58,26,11,13,'Kun minä ennustin, niin Pelatja, Benajan poika, kuoli. Niin minä lankesin kasvoilleni, huusin kovalla äänellä ja sanoin: "Voi Herra, Herra! Aivanko sinä teet lopun Israelin jäännöksestä?"'),
(1689631,58,26,11,14,'Sitten tuli minulle tämä Herran sana:'),
(1689632,58,26,11,15,'"Ihmislapsi, sinun veljesi, sinun veljesi, sukulaisesi ja koko Israelin heimo, kaikki, joille Jerusalemin asukkaat sanovat: ''Olkaa te vain kaukana Herrasta, meille on tämä maa annettu perinnöksi!'''),
(1689633,58,26,11,16,'Sano sentähden: Näin sanoo Herra, Herra: Koska minä olen vienyt heidät kauas pakanain sekaan ja hajottanut heidät muihin maihin, olen minä ollut heille pyhäkkönä vähän aikaa niissä maissa, joihin he ovat joutuneet.'),
(1689634,58,26,11,17,'Sano sentähden: Näin sanoo Herra, Herra: Minä kokoan teidät kansojen seasta ja kerään teidät maista, joihin teidät on hajotettu, ja annan teille Israelin maan.'),
(1689635,58,26,11,18,'Ja he tulevat sinne ja poistavat siitä kaikki sen iljetykset ja kaikki sen kauhistukset.'),
(1689636,58,26,11,19,'Ja minä annan heille yhden sydämen, ja uuden hengen minä annan teidän sisimpäänne, ja minä poistan kivisydämen heidän ruumiistansa ja annan heille lihasydämen,'),
(1689637,58,26,11,20,'niin että he vaeltavat minun käskyjeni mukaan ja noudattavat minun oikeuksiani ja pitävät ne; ja he ovat minun kansani, ja minä olen heidän Jumalansa.'),
(1689638,58,26,11,21,'Mutta joitten sydän vaeltaa heidän iljetystensä ja kauhistustensa mieltä myöten, niitten vaelluksen minä annan tulla heidän oman päänsä päälle, sanoo Herra, Herra."'),
(1689639,58,26,11,22,'Sitten kerubit nostivat siipensä ja pyörät samalla kuin ne, ja Israelin Jumalan kirkkaus oli heidän yläpuolellansa;'),
(1689640,58,26,11,23,'ja Herran kirkkaus kohosi ylös, pois kaupungin keskeltä, ja asettui vuorelle, joka on itään päin kaupungista.'),
(1689641,58,26,11,24,'Mutta Henki nosti ja vei minut Kaldeaan pakkosiirtolaisten tykö, näyssä, Jumalan Hengen voimalla; ja näky, jonka olin nähnyt, katosi minulta.'),
(1689642,58,26,11,25,'Ja minä puhuin pakkosiirtolaisille kaikki Herran sanat, jotka hän oli minulle näyttänyt.'),
(1689643,58,26,12,1,'Ja minulle tuli tämä Herran sana:'),
(1689644,58,26,12,2,'"Ihmislapsi, sinä asut uppiniskaisen suvun keskellä, niiden, joilla on silmät nähdä, mutta eivät näe, ja korvat kuulla, mutta eivät kuule; sillä he ovat uppiniskainen suku.'),
(1689645,58,26,12,3,'Sinä, ihmislapsi, tee itsellesi matkavarusteet ja mene päiväiseen aikaan heidän silmäinsä edessä pakkosiirtolaisuuteen; sinun on mentävä pakkosiirtolaisuuteen omalta paikkakunnaltasi toiseen paikkakuntaan heidän silmäinsä edessä. Ehkäpä he näkevät sen, sillä he ovat uppiniskainen suku.'),
(1689646,58,26,12,4,'Ja vie ulos varusteesi, niinkuin pakkosiirtolaiset varusteensa, päiväiseen aikaan heidän silmäinsä edessä; mutta lähde itse illalla heidän silmäinsä edessä, niinkuin pakkosiirtolaiset lähtevät.'),
(1689647,58,26,12,5,'Murtaudu läpi seinän heidän silmäinsä edessä ja vie ne siitä ulos.'),
(1689648,58,26,12,6,'Nosta ne hartioillesi heidän silmäinsä edessä ja vie ulos pilkkopimeässä; peitä kasvosi, niin ettet näe maata. Sillä ennusmerkiksi minä olen sinut pannut Israelin heimolle."'),
(1689649,58,26,12,7,'Ja minä tein, niinkuin minua oli käsketty: minä vein ulos päiväiseen aikaan varusteeni, niinkuin pakkosiirtolaiset varusteensa, mutta illalla minä murtauduin käsin läpi seinän; pilkkopimeässä minä ne vein ulos, minä nostin ne hartioilleni heidän silmäinsä edessä.'),
(1689650,58,26,12,8,'Mutta aamulla minulle tuli tämä Herran sana:'),
(1689651,58,26,12,9,'"Ihmislapsi, eikö ole Israelin heimo, uppiniskainen suku, sinulle sanonut: ''Mitä sinä teet?'''),
(1689652,58,26,12,10,'Sano heille: Näin sanoo Herra, Herra: Ruhtinasta, joka on Jerusalemissa, koskee tämä ennustus ja kaikkea Israelin heimoa, mikä on heidän keskuudessaan.'),
(1689653,58,26,12,11,'Sano: Minä olen teille ennusmerkki: niinkuin minä tein, niin heille tehdään, pakkosiirtolaisuuteen, vankeuteen he menevät.'),
(1689654,58,26,12,12,'Ruhtinas, joka on heidän keskellänsä, nostaa nostettavansa hartioilleen ja lähtee ulos pilkkopimeässä; seinästä he murtautuvat läpi, viedäkseen siitä ulos vietävänsä. Kasvonsa hän peittää, koska hän ei ole silmillänsä näkevä maata.'),
(1689655,58,26,12,13,'Minä levitän verkkoni hänen ylitsensä, ja hän takertuu minun pyydykseeni; minä vien hänet Baabeliin, kaldealaisten maahan, mutta sitä hän ei saa nähdä, ja sinne hän kuolee.'),
(1689656,58,26,12,14,'Ja kaikki, keitä hänellä on ympärillään apunansa, ja kaikki hänen sotajoukkonsa minä hajotan kaikkiin tuuliin, ja minä ajan niitä takaa paljastetulla miekalla.'),
(1689657,58,26,12,15,'Ja he tulevat tietämään, että minä olen Herra, kun minä hajotan heidät pakanain sekaan ja sirotan heidät muihin maihin.'),
(1689658,58,26,12,16,'Mutta vähäisen määrän heitä minä jätän miekasta, nälästä ja rutosta jäljelle kertomaan pakanain seassa, siellä, minne he joutuvat, kaikista kauhistuksistansa; ja ne tulevat tietämään, että minä olen Herra."'),
(1689659,58,26,12,17,'Ja minulle tuli tämä Herran sana:'),
(1689660,58,26,12,18,'"Ihmislapsi, syö leipäsi vavisten, juo vetesi väristen ja huolenalaisena'),
(1689661,58,26,12,19,'ja sano maan kansalle: Näin sanoo Herra, Herra Jerusalemin asukkaista Israelin maassa: He tulevat syömään leipänsä huolenalaisina ja juomaan vetensä kauhun vallassa, ja sen maa tulee autioksi kaikesta, mitä siinä on, kaikkien siinä asuvaisten väkivaltaisuuden tähden.'),
(1689662,58,26,12,20,'Asutut kaupungit joutuvat raunioiksi, ja maa tulee autioksi; ja te tulette tietämään, että minä olen Herra."'),
(1689663,58,26,12,21,'Ja minulle tuli tämä Herran sana:'),
(1689664,58,26,12,22,'"Ihmislapsi, miksi teillä on tämä pilkkalause Israelin maasta, kun sanotte: ''Aika venyy pitkälle, ja tyhjään raukeavat kaikki näyt?'''),
(1689665,58,26,12,23,'Sentähden sano heille: Näin sanoo Herra, Herra: Minä teen lopun tästä pilkkalauseesta, niin ettei sitä enää lausuta Israelissa. Sano heille päinvastoin: Lähellä on aika ja kaikkien näkyjen täyttymys.'),
(1689666,58,26,12,24,'Sillä ei ole oleva enää petollista näkyä, ei liukasta ennustelua Israelin heimon keskuudessa.'),
(1689667,58,26,12,25,'Sillä minä, Herra, minä puhun; ja minkä sanan minä puhun, se tapahtuu eikä enää viivy. Sillä teidän aikananne, uppiniskainen suku, minä sanan puhun ja sen myös täytän, sanoo Herra, Herra."'),
(1689668,58,26,12,26,'Ja minulle tuli tämä Herran sana:'),
(1689669,58,26,12,27,'"Ihmislapsi, katso, Israelin heimo sanoo: ''Niihin näkyihin, joita tämä näkee, on päiviä paljon, ja hän ennustaa kaukaisista ajoista''.'),
(1689670,58,26,12,28,'Sentähden sano heille: Näin sanoo Herra, Herra: Ei viivy enää yksikään minun sanani: Minkä sanan minä puhun, se tapahtuu, sanoo Herra, Herra."'),
(1689671,58,26,13,1,'Ja minulle tuli tämä Herran sana:'),
(1689672,58,26,13,2,'"Ihmislapsi, ennusta Israelin ennustavista profeetoista ja sano noille, jotka ovat profeettoja oman sydämensä voimasta: Kuulkaa Herran sana.'),
(1689673,58,26,13,3,'Näin sanoo Herra, Herra: Voi profeettahoukkia, jotka seuraavat omaa henkeänsä ja sitä, mitä eivät ole nähneet!'),
(1689674,58,26,13,4,'Niinkuin ketut raunioissa ovat sinun profeettasi, Israel.'),
(1689675,58,26,13,5,'Te ette ole nousseet muurin aukkoihin ettekä korjanneet muuria Israelin heimon ympärillä, että se kestäisi sodassa, Herran päivänä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689676,58,26,13,6,'Mitä he ovat nähneet, on petosta, ja heidän ennustelunsa on valhetta, kun he sanovat: ''Näin sanoo Herra'', vaikka Herra ei ole heitä lähettänyt; ja he muka odottavat, että hän toteuttaisi heidän sanansa.'),
(1689677,58,26,13,7,'Ettekö ole petollisia näkyjä nähneet ja valhe-ennusteluja puhuneet, kun olette sanoneet: ''Näin sanoo Herra'', vaikka minä en ole puhunut?'),
(1689678,58,26,13,8,'Sentähden, näin sanoo Herra, Herra: Koska te olette puhuneet petosta ja nähneet valhenäkyjä, niin sentähden, katso, minä käyn teidän kimppuunne, sanoo Herra, Herra.'),
(1689679,58,26,13,9,'Minun käteni on profeettoja vastaan, jotka petosnäkyjä näkevät ja valhetta ennustelevat. Ei pidä heidän oleman minun kansani yhteydessä, ei heitä kirjoiteta Israelin heimon kirjaan, eivätkä he tule Israelin maahan; ja te tulette tietämään, että minä olen Herra, Herra.'),
(1689680,58,26,13,10,'Koska he, koska he vievät minun kansani harhaan, sanoen: ''rauha!'', vaikka ei rauhaa ole, ja katso, koska he, kun kansa rakentaa seinän, valkaisevat sen kalkilla,'),
(1689681,58,26,13,11,'niin sano noille kalkilla-valkaisijoille, että se kaatuu. Tulee kaatosade, te syöksytte alas, raekivet, ja sinä pusket puhki, myrskynpuuska,'),
(1689682,58,26,13,12,'ja katso, seinä kaatuu! Eikö silloin teiltä kysytä: ''Missä on valkaisu, jonka olette sivelleet?'''),
(1689683,58,26,13,13,'Sentähden, näin sanoo Herra, Herra: Minä kiivaudessani annan myrskynpuuskan puhjeta, kaatosade tulee minun vihastani ja raekivet minun kiivaudestani, niin että tulee loppu.'),
(1689684,58,26,13,14,'Minä hajotan seinän, jonka te olitte kalkilla valkaisseet, ja syöksen sen maahan, niin että sen perustus paljastuu; niin se kaatuu, ja te saatte siinä lopun. Ja te tulette tietämään, että minä olen Herra.'),
(1689685,58,26,13,15,'Niin minä panen kiivauteni täytäntöön seinässä ja niissä, jotka sen kalkilla valkaisivat, ja sanon teille: Ei ole enää seinää eikä sen valkaisijoita,'),
(1689686,58,26,13,16,'Israelin profeettoja, jotka ennustivat Jerusalemista ja näkivät sille rauhan näkyjä, vaikka ei rauhaa ollut; sanoo Herra, Herra.'),
(1689687,58,26,13,17,'Ja sinä, ihmislapsi, käännä kasvosi kansasi tyttäriä vastaan, jotka joutuvat hurmoksiin oman sydämensä voimasta, ja ennusta heitä vastaan'),
(1689688,58,26,13,18,'ja sano: Näin sanoo Herra, Herra: Voi niitä naisia, jotka sitovat taikasiteet kaikkiin ranteisiin ja tekevät hunnut kaikenkorkuisiin päihin pyydystääksensä sieluja! Toisia sieluja te pyydystätte minun kansaltani pois, toisten sielujen annatte elää omaksi eduksenne.'),
(1689689,58,26,13,19,'Ja te häpäisette minut kansani edessä muutamista ohrakourallisista ja leipäpalasista, kun kuoletatte sieluja, joiden ei olisi kuoltava, ja annatte elää sielujen, jotka eivät saisi elää; kun valhettelette minun kansalleni, joka kuuntelee valhetta.'),
(1689690,58,26,13,20,'Sentähden, näin sanoo Herra, Herra: Minä käyn käsiksi teidän taikasiteisiinne, joilla olette pyydystäneet sieluja niinkuin lintuja, ja revin ne teidän käsivarsistanne ja lasken ne sielut irti - sielut, jotka te olette pyydystäneet - niinkuin linnut.'),
(1689691,58,26,13,21,'Ja minä revin teidän huntunne ja pelastan kansani teidän käsistänne, niin etteivät he enää joudu teidän kätenne saaliiksi; ja te tulette tietämään, että minä olen Herra.'),
(1689692,58,26,13,22,'Koska olette valheella murehduttaneet vanhurskaan sydämen, vaikka minä en tahtonut häntä murehduttaa, ja olette vahvistaneet jumalattoman käsiä, ettei hän kääntyisi pahalta tieltänsä ja saisi elää,'),
(1689693,58,26,13,23,'sentähden ette enää saa petosnäkyjä nähdä ettekä ennustella ennustelujanne, vaan minä pelastan kansani teidän käsistänne; ja te tulette tietämään, että minä olen Herra."'),
(1689694,58,26,14,1,'Minun luokseni tuli miehiä Israelin vanhinten joukosta, ja he istuivat minun eteeni.'),
(1689695,58,26,14,2,'Niin minulle tuli tämä Herran sana:'),
(1689696,58,26,14,3,'"Ihmislapsi, nämä miehet ovat sulkeneet kivijumalansa sydämeensä ja asettaneet kasvojensa eteen sen, mikä heille oli kompastukseksi syntiin. Antaisinko minä heidän kysyä minulta neuvoa?'),
(1689697,58,26,14,4,'Sentähden puhuttele heitä ja sano heille: Näin sanoo Herra, Herra: Kuka ikinä israelilainen sulkee kivijumalansa sydämeensä ja asettaa kasvojensa eteen sen, mikä hänelle oli kompastukseksi syntiin, ja sitten menee profeetan tykö, hänelle minä, Herra, kyllä annan vastauksen - hänelle ja hänen monille kivijumalilleen,'),
(1689698,58,26,14,5,'ja tartun Israelin heimoa sydämeen, koska he ovat kääntyneet minusta pois kaikki tyynni seuraamalla kivijumaliansa.'),
(1689699,58,26,14,6,'Sentähden sano Israelin heimolle: Näin sanoo Herra, Herra: Kääntykää, ja kääntykää pois kivijumalistanne ja kääntäkää kasvonne pois kaikista kauhistuksistanne.'),
(1689700,58,26,14,7,'Sillä kuka ikinä israelilainen tai muukalainen, joka asuu Israelissa, luopuu minusta ja sulkee kivijumalansa sydämeensä ja asettaa kasvojensa eteen sen, mikä hänelle oli kompastukseksi syntiin, ja sitten menee profeetan tykö kysymään itsellensä neuvoa minulta, hänelle minä, Herra, itse annan vastauksen.'),
(1689701,58,26,14,8,'Minä käännän kasvoni sitä miestä vastaan, teen hänet merkiksi ja sananlaskuksi ja hävitän hänet kansastani; ja te tulette tietämään, että minä olen Herra.'),
(1689702,58,26,14,9,'Mutta jos profeetta antaa viekoitella itsensä ja sanoo sanan, niin minä, Herra, olen sen profeetan viekoitellut; ja minä ojennan käteni häntä vastaan ja hävitän hänet kansastani Israelista.'),
(1689703,58,26,14,10,'Heidän on kannettava syntinsä - niinkuin kysyjän synti, niin on profeetankin synti -'),
(1689704,58,26,14,11,'etteivät he, Israelin heimo, enää eksyisi minusta pois eivätkä enää saastuttaisi itseänsä kaikilla rikkomuksillaan, vaan olisivat minun kansani ja minä olisin heidän Jumalansa; sanoo Herra, Herra."'),
(1689705,58,26,14,12,'Ja minulle tuli tämä Herran sana:'),
(1689706,58,26,14,13,'"Ihmislapsi! Jos maa tekisi syntiä minua vastaan olemalla uskoton ja minä ojentaisin sitä vastaan käteni ja murtaisin siltä leivän tuen ja lähettäisin siihen nälän ja hävittäisin siitä ihmiset ja eläimet,'),
(1689707,58,26,14,14,'ja sen keskellä olisivat nämä kolme miestä: Nooa, Daniel ja Job, niin oman henkensä he vanhurskaudellaan pelastaisivat; sanoo Herra, Herra.'),
(1689708,58,26,14,15,'Jos minä antaisin pahain petoeläinten käydä halki maan ja ne riistäisivät siltä lapset ja se tulisi autioksi, niin ettei kukaan siellä kulkisi petoeläinten tähden,'),
(1689709,58,26,14,16,'niin nämä kolme miestä, jos olisivat sen keskellä, eivät voisi - niin totta kuin minä elän, sanoo Herra, Herra - pelastaa poikiansa eikä tyttäriänsä; ainoastaan he itse pelastuisivat, mutta maa tulisi autioksi.'),
(1689710,58,26,14,17,'Taikka jos minä antaisin miekan tulla tämän maan yli ja sanoisin: ''Miekka, käy halki maan!'' ja hävittäisin siitä ihmiset ja eläimet,'),
(1689711,58,26,14,18,'ja sen keskellä olisivat nämä kolme miestä, eivät he voisi - niin totta kuin minä elän, sanoo Herra, Herra - pelastaa poikiansa eikä tyttäriänsä, vaan ainoastaan he itse pelastuisivat.'),
(1689712,58,26,14,19,'Taikka, jos minä lähettäisin ruton tähän maahan ja vuodattaisin vihani sen ylitse verenä, niin että hävittäisin siitä ihmiset ja eläimet,'),
(1689713,58,26,14,20,'ja Nooa ja Daniel ja Job olisivat sen keskellä, eivät he voisi - niin totta kuin minä elän, sanoo Herra, Herra - pelastaa poikaansa eikä tytärtänsä; vain itse he vanhurskaudellaan pelastaisivat henkensä.'),
(1689714,58,26,14,21,'Mutta näin sanoo Herra, Herra: Mitä sitten, kun minä lähetän Jerusalemin yli neljä kovaa tuomiotani: miekan, nälän, pahat petoeläimet ja ruton hävittämään siitä ihmiset ja eläimet!'),
(1689715,58,26,14,22,'Mutta katso, sinne on jäävä jäljelle pelastuneita, poikia ja tyttäriä, jotka viedään pois. Katso, ne tulevat teidän luoksenne, ja te näette heidän vaelluksensa ja tekonsa ja tulette lohdutetuiksi siitä onnettomuudesta, jonka minä olen tuottanut Jerusalemille, kaikesta, minkä olen sille tuottanut.'),
(1689716,58,26,14,23,'He lohduttavat teitä, kun näette heidän vaelluksensa ja tekonsa. Ja te tulette tietämään, etten minä syyttä ole tehnyt sitä kaikkea, minkä olen sille tehnyt; sanoo Herra, Herra."'),
(1689717,58,26,15,1,'Ja minulle tuli tämä Herran sana:'),
(1689718,58,26,15,2,'"Ihmislapsi, mikä parempi on viinipuu kuin kaikki muut puut, tuo köynnös, joka on metsän puitten seassa?'),
(1689719,58,26,15,3,'Otetaanko siitä puuta, josta tehdään tarviskalu? Otetaanko siitä vaarnaakaan, johon ripustetaan kaikkea tavaraa?'),
(1689720,58,26,15,4,'Katso, se annetaan tulen kulutettavaksi. Sen molemmat päät on tuli kuluttanut, ja sen keskus on kärventynyt - kelpaako se tarviskaluksi?'),
(1689721,58,26,15,5,'Katso, silloinkaan, kun se eheä oli, ei siitä voinut tarviskalua tehdä, saati sitten, kun tuli on sen kuluttanut ja se on kärventynyt - silloinko siitä tehtäisiin tarviskalu?'),
(1689722,58,26,15,6,'Sentähden, näin sanoo Herra, Herra: Niinkuin metsän puitten seassa käy viinipuulle, jonka minä olen antanut tulen kulutettavaksi, niin minä annan käydä myös Jerusalemin asukkaille.'),
(1689723,58,26,15,7,'Minä käännän kasvoni heitä vastaan: tulesta he ovat päässeet, mutta tuli heidät kuluttaa; ja te tulette tietämään, että minä olen Herra, kun minä käännän kasvoni heitä vastaan.'),
(1689724,58,26,15,8,'Ja minä teen maan autioksi, koska he ovat olleet uskottomat; sanoo Herra, Herra."'),
(1689725,58,26,16,1,'Ja minulle tuli tämä Herran sana:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689726,58,26,16,2,'"Ihmislapsi, ilmoita Jerusalemille sen kauhistukset'),
(1689727,58,26,16,3,'ja sano: Näin sanoo Jerusalemille Herra, Herra: Sinun sukusi ja syntysi on kanaanilaisten maasta; isäsi oli amorilainen ja äitisi heettiläinen.'),
(1689728,58,26,16,4,'Ja näin oli sinun syntymäsi: sinä päivänä, jona synnyit, sinulta ei leikattu napanuoraa, sinua ei pesty vedellä, että olisit puhdistunut, sinua ei hierottu suolalla eikä sinua kääritty kapaloihin.'),
(1689729,58,26,16,5,'Ei kenkään sinua säälinyt, niin että olisi tehnyt sinulle mitään tällaista ja armahtanut sinua, vaan sinut pantiin heitteille kedolle: niin halpana pidettiin sinun henkesi sinä päivänä, jona synnyit.'),
(1689730,58,26,16,6,'Mutta minä kuljin ohitsesi ja näin sinut, kun sätkyttelit verissäsi. Ja minä sanoin sinulle, kun olit siinä verissäsi: ''Sinun pitää elämän'' - niin sanoin minä sinulle, kun olit siinä verissäsi: ''Sinun pitää elämän,'),
(1689731,58,26,16,7,'minä teen sinut kymmentuhansiksi kuin pellon laihon''. Sitten sinä vartuit, tulit isoksi ja ehdit kauneimpaan kukoistukseesi, rintasi paisuivat, ja hiuksesi kasvoivat; mutta vielä sinä olit alaston ja paljas.'),
(1689732,58,26,16,8,'Niin minä kuljin ohitsesi ja näin sinut, ja katso, sinun aikasi oli lemmen aika. Ja minä levitin liepeeni sinun ylitsesi ja peitin häpysi. Ja minä vannoin sinulle ja menin liittoon sinun kanssasi, sanoo Herra, Herra; ja sinä tulit minun omakseni.'),
(1689733,58,26,16,9,'Minä pesin sinut vedellä, huuhtelin sinut verestäsi ja voitelin sinut öljyllä.'),
(1689734,58,26,16,10,'Minä puetin sinut kirjaeltuihin vaatteisiin, kengitsin sinut sireeninnahkakenkiin, sidoin päähäsi hienopellavaisen siteen ja hunnutin sinut silkillä.'),
(1689735,58,26,16,11,'Minä koristin sinut koruilla, panin rannerenkaat käsiisi ja käädyt kaulaasi,'),
(1689736,58,26,16,12,'panin nenärenkaan nenääsi, korvarenkaat korviisi ja päähäsi kauniin kruunun.'),
(1689737,58,26,16,13,'Niin koristettiin sinut kullalla ja hopealla, sinun pukusi oli hienoa pellavaa, silkkiä ja kirjaeltua vaatetta, ja sinä sait syödä lestyjä jauhoja, hunajata ja öljyä. Sinusta tuli ylenmäärin kaunis, ja sinä kelpasit kuninkaalliseen arvoon.'),
(1689738,58,26,16,14,'Ja sinun maineesi kulki pakanakansoihin kauneutesi tähden, sillä se oli täydellinen niiden kaunistusten takia, jotka minä sinun yllesi panin; sanoo Herra, Herra.'),
(1689739,58,26,16,15,'Mutta sinä luotit kauneuteesi ja harjoitit haureutta maineesi nojalla ja vuodatit haureuttasi jokaiselle ohikulkijalle: ''Saakoon tuokin!'''),
(1689740,58,26,16,16,'Sinä otit vaatteitasi ja teit itsellesi kirjavia uhrikukkuloita ja harjoitit haureutta niiden päällä - moista ei ole tapahtunut eikä ole tapahtuva -'),
(1689741,58,26,16,17,'Sinä otit korukalujasi, minun kultaani ja hopeatani, jota minä olin sinulle antanut, ja teit itsellesi miehenkuvia ja harjoitit haureutta niiden kanssa.'),
(1689742,58,26,16,18,'Sinä otit kirjaeltuja vaatteitasi ja verhosit ne niillä; ja minun öljyni ja suitsukkeeni sinä panit niiden eteen.'),
(1689743,58,26,16,19,'Ruokani, jota minä sinulle annoin - minähän syötin sinua lestyillä jauhoilla, öljyllä ja hunajalla - sinä panit niiden eteen suloiseksi tuoksuksi. Näin tapahtui, sanoo Herra, Herra.'),
(1689744,58,26,16,20,'Sinä otit poikasi ja tyttäresi, jotka olit minulle synnyttänyt, ja teurastit heidät niiden syödä. Eikö riittänyt sinulle haureutesi,'),
(1689745,58,26,16,21,'kun vielä teurastit minun poikani ja annoit heidät poltettaviksi uhrina niille?'),
(1689746,58,26,16,22,'Ja kaikkien kauhistustesi ja haureutesi ohessa sinä et muistanut nuoruutesi päiviä, jolloin olit alaston ja paljas ja sätkyttelit verissäsi.'),
(1689747,58,26,16,23,'Ja kaiken muun pahuutesi lisäksi - voi, voi sinua! sanoo Herra, Herra -'),
(1689748,58,26,16,24,'sinä rakensit itsellesi korokkeita ja teit itsellesi kumpuja kaikille toreille;'),
(1689749,58,26,16,25,'kaikkiin kadunkulmiin sinä rakensit kumpujasi ja häpäisit kauneutesi, levitit sääresi jokaiselle ohikulkijalle ja yhä lisäsit haureuttasi.'),
(1689750,58,26,16,26,'Sinä harjoitit haureutta naapuriesi, Egyptin suurijäsenisten poikain, kanssa ja yhä lisäsit haureuttasi ja niin vihoitit minut.'),
(1689751,58,26,16,27,'Ja katso, minä ojensin käteni sinua vastaan ja vähensin sinun määräosasi ja jätin sinut vihollistesi, filistealaisten tyttärien, raivon valtaan, jotka häpesivät sinun iljettävää vaellustasi.'),
(1689752,58,26,16,28,'Sitten sinä harjoitit haureutta Assurin poikain kanssa, koska et voinut saada kyllääsi; ja vaikka harjoitit haureutta heidän kanssansa, et sittenkään kyllääsi saanut.'),
(1689753,58,26,16,29,'Sitten sinä yhä enensit haureuttasi kauppiasten maahan päin, Kaldeaan, mutta et siitäkään saanut kyllääsi.'),
(1689754,58,26,16,30,'Kuinka himosta hiukeava olikaan sinun sydämesi, sanoo Herra, Herra, kun teit tämän kaiken, niinkuin tekee itse pääportto;'),
(1689755,58,26,16,31,'kun rakensit korokkeesi kaikkiin kadunkulmiin ja teit kumpusi kaikille toreille! Mutta siinä sinä olit erilainen kuin muut portot, että halveksuit portonpalkkaa -'),
(1689756,58,26,16,32,'avionrikkoja-vaimo, joka miehensä sijaan ottaa vieraita!'),
(1689757,58,26,16,33,'Kaikille muille portoille annetaan lahja, mutta sinä annoit portonlahjojasi kaikille rakastajillesi ja haureudessasi lahjoit heitä tulemaan luoksesi joka taholta.'),
(1689758,58,26,16,34,'Sinun oli haureudessasi laita päinvastoin kuin muitten naisten: sinun perässäsi ei juostu haureuteen, ja sinä maksoit portonpalkkaa, mutta sinulle portonpalkkaa ei maksettu; näin se oli päinvastoin.'),
(1689759,58,26,16,35,'Sentähden, sinä portto, kuule Herran sana:'),
(1689760,58,26,16,36,'Näin sanoo Herra, Herra: Koska olet antanut riettautesi vuotaa ja olet paljastanut häpysi haureudessasi kaikille rakastajillesi ja kaikille kauhistaville kivijumalillesi, sekä lastesi veren tähden, jonka olet niille antanut,'),
(1689761,58,26,16,37,'sentähden, katso, minä kokoan kaikki sinun rakastajasi, jotka olivat sinulle mieleen, kaikki, joita sinä rakastit, ja kaikki, joihin kyllästyit, ne minä kokoan sinua vastaan joka taholta ja paljastan heille sinun häpysi, niin että he näkevät koko häpysi.'),
(1689762,58,26,16,38,'Minä tuomitsen sinut sen mukaan, mitä on säädetty avionrikkoja- ja verenvuodattaja-naisista, ja annan vihassa ja kiivaudessa sinun veresi vuotaa.'),
(1689763,58,26,16,39,'Ja minä annan sinut heidän käsiinsä, ja he hajottavat sinun korokkeesi, kukistavat sinun kumpusi, raastavat sinulta vaatteesi, ottavat korukalusi ja jättävät sinut alastomaksi ja paljaaksi.'),
(1689764,58,26,16,40,'He nostattavat kansanjoukon sinua vastaan, ja ne kivittävät sinut, hakkaavat sinut maahan miekoillansa,'),
(1689765,58,26,16,41,'polttavat tulella sinun talosi ja panevat sinussa toimeen tuomiot paljojen naisten silmäin edessä. Minä teen lopun sinun porttona-olostasi, etkä sinä enää sitten portonpalkkoja maksa.'),
(1689766,58,26,16,42,'Niin minä tyydytän vihani sinussa, niin että minun kiivauteni sinusta väistyy, ja minä tyynnyn enkä enää ole vihastunut.'),
(1689767,58,26,16,43,'Koska et muistanut nuoruutesi päiviä, vaan ärsytit minut kaikilla näillä, niin katso: minäkin annan sinun vaelluksesi tulla oman pääsi päälle, sanoo Herra, Herra. Etkö sinä tehnyt näitä iljetyksiä kaikkien kauhistustesi lisäksi?'),
(1689768,58,26,16,44,'Katso, jokainen, joka sananlaskuja lausuu, on lausuva sinusta: ''Tytär tulee äitiinsä''.'),
(1689769,58,26,16,45,'Sinä olet äitisi tytär, hänen, joka vieroi miestään ja lapsiansa, ja olet sisartesi sisar, heidän, jotka vieroivat miehiään ja lapsiansa: teidän äitinne oli heettiläinen ja isänne amorilainen.'),
(1689770,58,26,16,46,'Isompi sisaresi oli Samaria tyttärineen, joka asui vasemmalla puolellasi, ja pienempi sisaresi, joka asui oikealla puolellasi, oli Sodoma tyttärineen.'),
(1689771,58,26,16,47,'Mutta sinä et vaeltanut heidän teitänsä etkä tehnyt kauhistuksia samalla tavoin kuin he: vähän aikaa vain, niin sinä jo teit kelvottomammin kuin he kaikilla teilläsi.'),
(1689772,58,26,16,48,'Niin totta kuin minä elän, sanoo Herra, Herra: ei totisesti sisaresi Sodoma tyttärineen tehnyt sitä, mitä sinä tyttärinesi olet tehnyt.'),
(1689773,58,26,16,49,'Katso, tämä oli sisaresi Sodoman synti: ylpeys, leivän yltäkylläisyys ja huoleton lepo hänellä ja hänen tyttärillään; mutta kurjaa ja köyhää hän ei kädestä ottanut.'),
(1689774,58,26,16,50,'He korskeilivat ja tekivät kauhistuksia minun edessäni, ja minä, kun sen näin, toimitin heidät pois.'),
(1689775,58,26,16,51,'Ja Samaria ei tehnyt puoltakaan sinun syntiesi vertaa; mutta sinä olet tehnyt kauhistuksia paljon enemmän kuin he, niin että olet kaikilla kauhistuksillasi, joita olet tehnyt, saanut sisaresi näyttämään vanhurskailta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689776,58,26,16,52,'Niinpä kanna myös sinä häpeäsi, kun olet hankkinut moisen hyvityksen sisarillesi: sinun syntiesi takia, kun olet menetellyt vielä kauhistavammin kuin he, ovat he vanhurskaampia kuin sinä. Häpeä sinäkin ja kanna häpeäsi, kun olet saanut sisaresi näyttämään vanhurskailta.'),
(1689777,58,26,16,53,'Ja minä tahdon kääntää heidän kohtalonsa: Sodoman ja hänen tyttäriensä kohtalon sekä Samarian ja hänen tyttäriensä kohtalon; ja minä tahdon kääntää sinun kohtalosi, sinun, joka olet heidän keskellänsä,'),
(1689778,58,26,16,54,'että kantaisit häpeäsi ja olisit häpeissäsi kaikesta, mitä teit, kun lohdutit heidät.'),
(1689779,58,26,16,55,'Sinun sisaresi - Sodoma tyttärineen saa palata entisellensä, ja Samaria tyttärineen saa palata entisellensä. Ja sinä tyttärinesi saat palata entisellesi.'),
(1689780,58,26,16,56,'Eikö ollut sisaresi Sodoma huhupuheena sinun suussasi sinun ylpeytesi aikana,'),
(1689781,58,26,16,57,'ennenkuin sinun oma pahuutesi paljastui, silloin kun jouduit Aramin tyttärien ja kaikkien heidän ympärillään asuvaisten, filistealaisten tyttärien, häväistäväksi, jotka joka taholta pilkkaavat sinua?'),
(1689782,58,26,16,58,'Sinä saat kantaa iljetyksesi ja kauhistuksesi, sanoo Herra.'),
(1689783,58,26,16,59,'Sillä näin sanoo Herra, Herra: Minä olen tehnyt sinulle sen mukaan, kuin sinä olet tehnyt, kun olet pitänyt valan halpana ja rikkonut liiton.'),
(1689784,58,26,16,60,'Mutta minä muistan liittoni, jonka tein sinun kanssasi sinun nuoruutesi päivinä, ja minä teen sinun kanssasi iankaikkisen liiton.'),
(1689785,58,26,16,61,'Ja sinä muistat vaelluksesi ja häpeät, kun otat vastaan sisaresi, ne, jotka ovat sinua isommat, ynnä ne, jotka ovat sinua pienemmät, ja minä annan heidät sinulle tyttäriksi; mutta en sinun liittosi voimasta.'),
(1689786,58,26,16,62,'Ja minä teen liittoni sinun kanssasi, ja sinä tulet tietämään, että minä olen Herra.'),
(1689787,58,26,16,63,'Niin sinä muistat ja häpeät etkä voi häpeäsi tähden suutasi avata, kun minä annan sinulle anteeksi kaikki, mitä sinä tehnyt olet; sanoo Herra, Herra."'),
(1689788,58,26,17,1,'Ja minulle tuli tämä Herran sana:'),
(1689789,58,26,17,2,'"Ihmislapsi, esitä arvoitus ja lausu vertaus Israelin heimolle'),
(1689790,58,26,17,3,'ja sano: Näin sanoo Herra, Herra: Suuri kotka, suurisiipinen, pitkäsulkainen, täysihöyheninen, kirjava, tuli Libanonille ja otti latvuksen setripuusta.'),
(1689791,58,26,17,4,'Hän taittoi siitä latvalehvän ja vei sen kauppiasten maahan, asetti sen kauppurien kaupunkiin.'),
(1689792,58,26,17,5,'Sitten hän otti siitä maasta taimen ja pani sen kylvöpeltoon. Hän otti sen ja pani pajuksi runsaan veden ääreen.'),
(1689793,58,26,17,6,'Se versoi, ja siitä tuli rehevä viinipuu, matalakasvuinen; sen oksien tuli kääntyä kotkaan päin ja sen juurten olla hänen allansa. Siitä tuli viinipuu, se teki haaroja, työnsi oksia.'),
(1689794,58,26,17,7,'Mutta oli toinen suuri kotka, suurisiipinen, runsashöyheninen; ja katso, tämä viinipuu ojensi juurensa sitä kotkaa kohti ja työnsi oksansa siihen päin, sen kasteltaviksi, siitä penkereestä, johon se oli istutettu.'),
(1689795,58,26,17,8,'Se oli istutettu hyvään peltoon, runsaan veden ääreen, että se tekisi lehviä, kantaisi hedelmää ja tulisi ihanaksi viinipuuksi.'),
(1689796,58,26,17,9,'Sano: Näin sanoo Herra, Herra: Menestyyköhän se? Eiköhän kotka kisko ylös sen juuria ja raasta sen hedelmiä; niin että kaikki siitä versoneet lehdet kuivuvat ja puu kuivuu? Eikä tarvita suurta voimaa, ei paljoa väkeä sen nostamiseksi juuriltansa.'),
(1689797,58,26,17,10,'Katso, istutettu se on - menestyyköhän se? Eiköhän se kuivu, kun siihen käy itätuuli, kuivu penkereessä, jossa se versoi?"'),
(1689798,58,26,17,11,'Ja minulle tuli tämä Herran sana:'),
(1689799,58,26,17,12,'"Sano uppiniskaiselle suvulle: Ettekö te tiedä, mitä tämä tarkoittaa? Sano: Katso, Baabelin kuningas tuli Jerusalemiin, otti sen kuninkaan ja päämiehet ja vei heidät luoksensa Baabeliin.'),
(1689800,58,26,17,13,'Ja hän otti yhden kuninkaallisesta suvusta, teki hänen kanssansa liiton ja otti häneltä valan, mutta maan mahtavat hän vei mukanaan,'),
(1689801,58,26,17,14,'että valtakunta tulisi vähäpätöiseksi eikä kohoaisi, että se pitäisi liittonsa ja liitto pysyisi.'),
(1689802,58,26,17,15,'Mutta hän kapinoi häntä vastaan ja laittoi lähettiläänsä Egyptiin, että hänelle annettaisiin hevosia ja paljon väkeä. Menestyyköhän se, pelastuukohan se, joka tällaista tekee? Pelastuuko se, joka liiton rikkoo?'),
(1689803,58,26,17,16,'Niin totta kuin minä elän, sanoo Herra, Herra: sen kuninkaan asuinpaikalla, joka hänet kuninkaaksi teki, jonka valan hän on halpana pitänyt ja jonka liiton hän on rikkonut, sen luona, keskellä Baabelia, hänen totisesti on kuoltava.'),
(1689804,58,26,17,17,'Ja farao suurella sotajoukollaan ja paljolla väellään ei tee mitään hänen hyväkseen sodassa, kun luodaan valli ja rakennetaan saartovarusteet paljojen ihmisten hävittämiseksi.'),
(1689805,58,26,17,18,'Hän piti halpana valan ja rikkoi liiton; katso, vaikka oli kättä lyönyt, hän teki kaiken tämän - ei hän pelastu.'),
(1689806,58,26,17,19,'Sentähden, näin sanoo Herra, Herra: Niin totta kuin minä elän, niin valani, jonka hän halpana piti, ja liittoni, jonka hän rikkoi, minä annan totisesti tulla hänen päänsä päälle.'),
(1689807,58,26,17,20,'Minä levitän verkkoni hänen ylitsensä, ja hän takertuu minun pyydykseeni. Minä vien hänet Baabeliin ja käyn siellä oikeutta hänen kanssansa hänen uskottomuudestaan, jota hän on osoittanut minua kohtaan.'),
(1689808,58,26,17,21,'Ja kaikki hänen pakolaisensa kaikista hänen sotajoukoistaan kaatuvat miekkaan, ja jäljellejääneet hajotetaan kaikkiin tuuliin. Ja te tulette tietämään, että minä, Herra, olen puhunut.'),
(1689809,58,26,17,22,'Näin sanoo Herra, Herra: Mutta minä otan yhden latvuksen siitä korkeasta setripuusta ja istutan sen; hennon latvalehvän minä siitä taitan ja istutan korkealle ja jyrkälle vuorelle.'),
(1689810,58,26,17,23,'Israelin vuoren korkeuteen minä sen istutan: ja se kantaa lehviä ja tekee hedelmää, ja siitä tulee mahtava setri. Ja sen alla asuvat kaikki linnut, kaikki, mitä siivekästä on; ne asuvat sen oksain varjossa.'),
(1689811,58,26,17,24,'Ja kaikki metsän puut tulevat tietämään, että minä olen Herra, joka teen korkean puun matalaksi ja matalan puun korkeaksi, tuoreen puun kuivaksi ja kuivan puun kukoistavaksi. Minä, Herra, Herra, olen puhunut, ja minä sen teen."'),
(1689812,58,26,18,1,'Ja minulle tuli tämä Herran sana:'),
(1689813,58,26,18,2,'"Mikä teillä on, kun te lausutte tätä pilkkalausetta Israelin maasta: ''Isät söivät raakoja rypäleitä, lasten hampaat heltyivät''?'),
(1689814,58,26,18,3,'Niin totta kuin minä elän, sanoo Herra, Herra, ei tule teidän enää lausua tätä pilkkalausetta Israelissa.'),
(1689815,58,26,18,4,'Katso, kaikki sielut ovat minun: niinkuin isän sielu, niin pojankin sielu - ne ovat minun. Se sielu, joka syntiä tekee - sen on kuoltava.'),
(1689816,58,26,18,5,'Jos mies on vanhurskas ja tekee oikeuden ja vanhurskauden:'),
(1689817,58,26,18,6,'ei syö uhrivuorilla, ei luo silmiänsä Israelin heimon kivijumaliin, ei saastuta lähimmäisensä vaimoa, ei ryhdy naiseen, joka on kuukautistilassa,'),
(1689818,58,26,18,7,'ei sorra toista, vaan antaa takaisin velanpantin, ei riistä eikä raasta, vaan antaa leipäänsä nälkäiselle, verhoaa vaatteella alastonta,'),
(1689819,58,26,18,8,'ei anna rahaansa korolle, ei ota voittoa, vaan pidättää kätensä vääryydestä, tekee oikean tuomion miesten välillä,'),
(1689820,58,26,18,9,'vaeltaa minun käskyjeni mukaan ja noudattaa minun oikeuksiani, niin että tekee sitä, mikä oikein on - hän on vanhurskas, hän totisesti saa elää, sanoo Herra, Herra.'),
(1689821,58,26,18,10,'Mutta jos hänelle on syntynyt poika, väkivaltainen, verenvuodattaja, joka tekee yhtäkin näistä,'),
(1689822,58,26,18,11,'mitä hän itse ei ole tehnyt: syö uhrivuorilla, saastuttaa lähimmäisensä vaimon,'),
(1689823,58,26,18,12,'sortaa kurjaa ja köyhää, riistää ja raastaa, ei anna takaisin panttia, luo silmänsä kivijumaliin, tekee kauhistuksia,'),
(1689824,58,26,18,13,'antaa rahansa korolle ja ottaa voittoa - saisiko tämä elää? Ei hän saa elää: kaikkia näitä kauhistuksia hän on tehnyt, hänet on kuolemalla rangaistava; hän on verivelan alainen.'),
(1689825,58,26,18,14,'Mutta katso, jos tälle on syntynyt poika ja hän näkee kaikki isänsä synnit, jotka tämä on tehnyt - näkee ne eikä tee sellaisia:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689826,58,26,18,15,'ei syö uhrivuorilla, ei luo silmiänsä Israelin heimon kivijumaliin, ei saastuta lähimmäisensä vaimoa,'),
(1689827,58,26,18,16,'ei sorra toista, ei ota panttia, ei riistä eikä raasta, vaan antaa leipäänsä nälkäiselle, verhoaa vaatteella alastonta,'),
(1689828,58,26,18,17,'pidättää kätensä kurjasta, ei ota korkoa eikä voittoa, vaan tekee minun oikeuksieni mukaan, vaeltaa käskyjeni mukaan - hänen ei ole kuoltava isänsä syntivelan tähden, hän totisesti saa elää.'),
(1689829,58,26,18,18,'Hänen isänsä taas kun teki väkivallan töitä, riisti ja raastoi veljeltänsä ja teki kansansa keskuudessa sitä, mikä ei ole hyvää, niin katso, hänen oli kuoltava syntivelkansa tähden.'),
(1689830,58,26,18,19,'Ja vielä te kysytte: ''Minkätähden ei poika kanna isän syntivelkaa?'' Kun poika on tehnyt oikeuden ja vanhurskauden, noudattanut kaikkia minun käskyjäni ja tehnyt niitten mukaan, hän totisesti saa elää. Se sielu, joka syntiä tekee - sen on kuoltava.'),
(1689831,58,26,18,20,'Poika ei kanna isän syntivelkaa, eikä isä kanna pojan syntivelkaa. Vanhurskaan ylitse on tuleva hänen vanhurskautensa, ja jumalattoman ylitse on tuleva hänen jumalattomuutensa.'),
(1689832,58,26,18,21,'Ja jos jumalaton kääntyy pois kaikesta synnistänsä, mitä hän on tehnyt, ja noudattaa kaikkia minun käskyjäni ja tekee oikeuden ja vanhurskauden, hän totisesti saa elää; ei hänen ole kuoltava.'),
(1689833,58,26,18,22,'Ei yhtäkään hänen synneistänsä, jotka hän on tehnyt, muisteta; vanhurskautensa tähden, jota hän on noudattanut, hän saa elää.'),
(1689834,58,26,18,23,'Olisiko minulle mieleen jumalattoman kuolema, sanoo Herra, Herra; eikö se, että hän kääntyy pois teiltänsä ja elää?'),
(1689835,58,26,18,24,'Ja jos vanhurskas kääntyy pois vanhurskaudestansa ja tekee vääryyttä, tekee kaikkien niiden kauhistusten kaltaisia, joita jumalaton tekee - saisiko hän tehdä niin ja elää? Ei yhtäkään hänen vanhurskasta tekoansa, jonka hän on tehnyt, muisteta. Uskottomuutensa tähden, johon hän on langennut, ja syntinsä tähden, jota on tehnyt, niiden tähden hänen on kuoltava.'),
(1689836,58,26,18,25,'Ja vielä te sanotte: ''Herran tie ei ole oikea''. Kuulkaa siis, te Israelin heimo! Minunko tieni ei olisi oikea? Eikö niin: teidän omat tienne eivät ole oikeat!'),
(1689837,58,26,18,26,'Jos vanhurskas kääntyy pois vanhurskaudestansa ja tekee vääryyttä, sentähden hänen on kuoltava; vääryytensä tähden, jota on tehnyt, hänen on kuoltava.'),
(1689838,58,26,18,27,'Ja jos jumalaton kääntyy pois jumalattomuudestaan, jota on harjoittanut, ja tekee oikeuden ja vanhurskauden, hän säilyttää sielunsa elossa.'),
(1689839,58,26,18,28,'Koska hän näki ja kääntyi pois kaikista synneistänsä, joita oli tehnyt, hän totisesti saa elää; ei hänen ole kuoltava.'),
(1689840,58,26,18,29,'Mutta Israelin heimo sanoo: ''Herran tie ei ole oikea''. Minunko tieni eivät olisi oikeat, te Israelin heimo? Eikö niin: teidän omat tienne eivät ole oikeat!'),
(1689841,58,26,18,30,'Niinpä minä tuomitsen teidät, te Israelin heimo, itsekunkin hänen teittensä mukaan, sanoo Herra, Herra. Kääntykää, palatkaa pois kaikista synneistänne, ja älköön syntivelka tulko teille lankeemukseksi.'),
(1689842,58,26,18,31,'Heittäkää pois päältänne kaikki syntinne, joilla te olette rikkoneet, ja tehkää itsellenne uusi sydän ja uusi henki. Ja minkätähden te kuolisitte, Israelin heimo?'),
(1689843,58,26,18,32,'Sillä ei ole minulle mieleen kuolevan kuolema, sanoo Herra, Herra. Siis kääntykää, niin te saatte elää."'),
(1689844,58,26,19,1,'"Mutta sinä, viritä itkuvirsi Israelin ruhtinaista'),
(1689845,58,26,19,2,'ja sano: Mikä naarasleijona olikaan sinun äitisi leijonain joukossa! Se makasi nuorten jalopeurain keskellä, kasvatti poikasiansa'),
(1689846,58,26,19,3,'ja sai ylenemään yhden poikasistaan: siitä tuli nuori jalopeura, se oppi saalista raatelemaan, se söi ihmisiä.'),
(1689847,58,26,19,4,'Mutta kansat kuulivat siitä: se pyydystettiin heidän kuoppaansa ja vietiin turpakoukussa Egyptin maahan.'),
(1689848,58,26,19,5,'Kun emo näki, että viipyi, että hukkui hänen toivonsa, otti se toisen poikasistaan, sai sen nuoreksi jalopeuraksi.'),
(1689849,58,26,19,6,'Se käyskenteli leijonain keskellä, siitä tuli nuori jalopeura, se oppi saalista raatelemaan, se söi ihmisiä.'),
(1689850,58,26,19,7,'Se ryhtyi heidän leskiinsä ja teki autioiksi heidän kaupunkinsa, ja maa ja kaikki, mitä siinä on, kauhistui sen ärjynnän äänestä.'),
(1689851,58,26,19,8,'Silloin kansat maakunnista yltympäri asettivat ja virittivät sille verkkonsa; se pyydystettiin heidän kuoppaansa.'),
(1689852,58,26,19,9,'Ja se pantiin häkkiin, turpakoukkuun ja vietiin Baabelin kuninkaan eteen. Se vietiin vuorilinnoihin, ettei sen ääni enää kuuluisi Israelin vuorille.'),
(1689853,58,26,19,10,'Sinun äitisi oli sinulle kuin verevä viinipuu, veden ääreen istutettu. Se tuli runsaasta vedestä hedelmöitseväksi ja tuuhealehväiseksi.'),
(1689854,58,26,19,11,'Siihen tuli ylväitä oksia hallitsijain valtikoiksi, ja sen runko kohosi korkealle tiheän lehvistön keskellä ja näkyi kauas korkeana ja runsas-oksaisena.'),
(1689855,58,26,19,12,'Mutta se temmattiin vihaisesti irti, viskattiin maahan, ja itätuuli kuivasi sen hedelmät, ne revittiin hajalleen, ja sen ylväät oksat kuivuivat, ne kulutti tuli.'),
(1689856,58,26,19,13,'Nyt se on istutettuna erämaahan, kuivaan ja janoiseen maahan.'),
(1689857,58,26,19,14,'Ja sen valtaoksasta on lähtenyt tuli, se on kuluttanut sen hedelmät, ja ylvästä oksaa hallitusvaltikaksi ei siinä enää ole." Itkuvirsi tämä oli oleva, ja itkuvirsi siitä on tullut.'),
(1689858,58,26,20,1,'Seitsemäntenä vuotena, viidennessä kuussa, kuukauden kymmenentenä päivänä tuli miehiä Juudan vanhinten joukosta kysymään neuvoa Herralta, ja he istuivat minun eteeni.'),
(1689859,58,26,20,2,'Niin minulle tuli tämä Herran sana:'),
(1689860,58,26,20,3,'"Ihmislapsi, puhu Israelin vanhimmille ja sano heille: Näin sanoo Herra, Herra: Tekö tulette minulta neuvoa kysymään? Niin totta kuin minä elän, en anna minä teidän kysyä minulta neuvoa, sanoo Herra, Herra.'),
(1689861,58,26,20,4,'Etkö tuomitse heitä, etkö tuomitse, ihmislapsi? Tee heille tiettäviksi heidän isiensä kauhistukset'),
(1689862,58,26,20,5,'ja sano heille: Näin sanoo Herra, Herra: Sinä päivänä, jona minä Israelin valitsin, minä kättä kohottaen lupasin Jaakobin heimon jälkeläisille, minä tein itseni heille tunnetuksi Egyptin maassa ja kättä kohottaen lupasin heille sanoen: ''Minä olen Herra, teidän Jumalanne''.'),
(1689863,58,26,20,6,'Sinä päivänä minä kättä kohottaen lupasin heille, että vien heidät pois Egyptin maasta siihen maahan, jonka olin heille katsonut ja joka vuotaa maitoa ja mettä - se on kaunistus kaikkien maitten joukossa. -'),
(1689864,58,26,20,7,'Ja minä sanoin heille: ''Heittäkää, itsekukin, pois silmienne iljetykset älkääkä saastuttako itseänne Egyptin kivijumalilla: minä olen Herra, teidän Jumalanne''.'),
(1689865,58,26,20,8,'Mutta he niskoittelivat minua vastaan eivätkä tahtoneet minua kuulla; eivät heittäneet pois itsekukin silmiensä iljetyksiä eivätkä hyljänneet Egyptin kivijumalia. Niin minä ajattelin vuodattaa kiivauteni heidän ylitsensä ja panna vihani täytäntöön heissä keskellä Egyptin maata.'),
(1689866,58,26,20,9,'Mutta minä tein, minkä tein, oman nimeni tähden, ettei se tulisi häväistyksi pakanain silmissä, joitten keskellä he olivat ja joitten silmäin edessä minä olin tehnyt itseni heille tunnetuksi viemällä heidät pois Egyptin maasta.'),
(1689867,58,26,20,10,'Ja kun olin vienyt heidät pois Egyptin maasta ja tuonut heidät erämaahan,'),
(1689868,58,26,20,11,'niin minä annoin heille käskyni ja tein heille tiettäviksi oikeuteni: se ihminen, joka ne pitää, on niistä elävä.'),
(1689869,58,26,20,12,'Myöskin sapattini minä annoin heille, olemaan merkkinä minun ja heidän välillään, että he tulisivat tietämään, että minä olen Herra, joka pyhitän heidät.'),
(1689870,58,26,20,13,'Mutta Israelin heimo niskoitteli minua vastaan erämaassa: he eivät vaeltaneet minun käskyjeni mukaan, ylenkatsoivat minun oikeuteni, jotka ihmisen on pidettävä, että hän niistä eläisi, ja minun sapattini he kovin rikkoivat. Niin minä ajattelin vuodattaa kiivauteni heidän ylitsensä erämaassa ja lopettaa heidät.'),
(1689871,58,26,20,14,'Mutta minä tein, minkä tein, oman nimeni tähden, ettei se tulisi häväistyksi pakanain silmissä, joitten silmäin edessä minä olin vienyt heidät pois.'),
(1689872,58,26,20,15,'Kuitenkin minä kättä kohottaen vannoin heille erämaassa, etten heitä tuo siihen maahan, jonka olin antanut heille, joka vuotaa maitoa ja mettä - se on kaunistus kaikkien maitten joukossa -'),
(1689873,58,26,20,16,'koska he pitivät minun oikeuteni halpoina, eivät vaeltaneet minun käskyjeni mukaan, vaan rikkoivat minun sapattini; sillä heidän sydämensä vaelsi heidän kivijumalainsa jäljessä.'),
(1689874,58,26,20,17,'Mutta minä säälin heitä, niin etten heitä hävittänyt enkä tehnyt heistä loppua erämaassa.'),
(1689875,58,26,20,18,'Sitten minä sanoin heidän lapsillensa erämaassa: Älkää vaeltako isäinne käskyjen mukaan, heidän oikeuksiansa älkää noudattako älkääkä saastuttako itseänne heidän kivijumalillansa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689876,58,26,20,19,'Minä olen Herra, teidän Jumalanne; minun käskyjeni mukaan vaeltakaa, minun oikeuksiani noudattakaa, ne pitäkää'),
(1689877,58,26,20,20,'ja pyhittäkää minun sapattini; ne olkoot merkkinä välillämme, minun ja teidän, että tulisitte tietämään, että minä olen Herra, teidän Jumalanne.'),
(1689878,58,26,20,21,'Mutta lapset niskoittelivat minua vastaan: he eivät vaeltaneet minun käskyjeni mukaan, eivät noudattaneet minun oikeuksiani, niin että olisivat ne pitäneet, - jotka ihmisen on pidettävä, että hän niistä eläisi - ja rikkoivat minun sapattini. Niin minä ajattelin vuodattaa kiivauteni heidän ylitsensä ja panna vihani heissä täytäntöön erämaassa.'),
(1689879,58,26,20,22,'Mutta minä pidätin käteni ja tein, minkä tein, oman nimeni tähden, ettei se tulisi häväistyksi pakanain silmissä, joitten silmäin edessä minä olin vienyt heidät pois.'),
(1689880,58,26,20,23,'Kuitenkin minä kättä kohottaen vannoin heille erämaassa, että minä hajotan heidät pakanain sekaan ja sirotan heidät muihin maihin,'),
(1689881,58,26,20,24,'koska he eivät pitäneet minun käskyjäni, vaan ylenkatsoivat minun käskyni, rikkoivat minun sapattini ja heidän silmänsä pälyivät heidän isiensä kivijumalain perään.'),
(1689882,58,26,20,25,'Niinpä minäkin annoin heille käskyjä, jotka eivät olleet hyviä, ja oikeuksia, joista he eivät voineet elää,'),
(1689883,58,26,20,26,'ja annoin heidän saastua lahjoistansa, siitä, että polttivat uhrina kaiken, mikä avasi äidinkohdun, jotta saattaisin heidät kauhun valtaan ja he tulisivat tietämään, että minä olen Herra.'),
(1689884,58,26,20,27,'Sentähden puhu Israelin heimolle, ihmislapsi, ja sano heille: Näin sanoo Herra, Herra: Vielä niinkin ovat isänne minua herjanneet, että ovat olleet uskottomat minua kohtaan.'),
(1689885,58,26,20,28,'Kun minä toin heidät maahan, jonka olin kättä kohottaen luvannut heille antaa, niin missä vain he näkivät korkean kukkulan tai tuuhean puun, siinä he uhrasivat teurasuhrinsa ja antoivat vihastuttavat uhrilahjansa, siinä panivat esiin suloisesti tuoksuvat uhrinsa ja siinä vuodattivat juomauhrinsa.'),
(1689886,58,26,20,29,'Niin minä sanoin heille: ''Mikä tämä uhrikukkula on, jolle te menette?'' ja niin sai sellainen nimen uhrikukkula aina tähän päivään asti.'),
(1689887,58,26,20,30,'Sentähden sano Israelin heimolle: Näin sanoo Herra, Herra: Ettekö te saastuta itseänne isienne tiellä? Ettekö kulje uskottomina heidän iljetystensä jäljessä?'),
(1689888,58,26,20,31,'Ettekö ole saastuttaneet itseänne kaikilla kivijumalillanne aina tähän päivään asti, kun tuotte lahjojanne ja panette lapsenne käymään tulen läpi? Ja minäkö antaisin teidän kysyä minulta neuvoa, te Israelin heimo? Niin totta kuin minä elän, sanoo Herra, Herra, en anna minä teidän kysyä minulta neuvoa.'),
(1689889,58,26,20,32,'Se, mikä on tullut teidän mieleenne, ei totisesti ole tapahtuva - se, mitä sanotte: ''Me tahdomme olla pakanain kaltaisia, muitten maitten sukukuntain kaltaisia, niin että palvelemme puuta ja kiveä''.'),
(1689890,58,26,20,33,'Niin totta kuin minä elän, sanoo Herra, Herra: totisesti minä olen hallitseva teitä väkevällä kädellä, ojennetulla käsivarrella ja vuodatetulla vihalla.'),
(1689891,58,26,20,34,'Ja minä vien teidät pois kansojen seasta ja kokoan teidät maista, joihin olitte hajotetut, väkevällä kädellä, ojennetulla käsivarrella ja vuodatetulla vihalla.'),
(1689892,58,26,20,35,'Ja minä tuon teidät kansojen erämaahan, ja siellä minä käyn oikeutta teidän kanssanne kasvoista kasvoihin.'),
(1689893,58,26,20,36,'Niinkuin minä kävin oikeutta isienne kanssa Egyptinmaan erämaassa, niin minä käyn oikeutta teidän kanssanne, sanoo Herra, Herra.'),
(1689894,58,26,20,37,'Minä panen teidät kulkemaan sauvan alitse ja saatan teidät liiton siteeseen.'),
(1689895,58,26,20,38,'Ja minä erotan teistä ne, jotka kapinoivat minua vastaan ja luopuvat minusta: muukalaisuutensa maasta minä vien heidät pois, mutta Israelin maahan he eivät tule; ja te tulette tietämään, että minä olen Herra.'),
(1689896,58,26,20,39,'Mutta te, Israelin heimo! Näin sanoo Herra, Herra: Menkää vain ja palvelkaa itsekukin omia kivijumalianne. Mutta vastedes te totisesti kuulette minua ettekä enää häpäise minun pyhää nimeäni lahjoillanne ynnä kivijumalillanne.'),
(1689897,58,26,20,40,'Sillä minun pyhällä vuorellani, Israelin korkealla vuorella, sanoo Herra, Herra, siellä he palvelevat minua, koko Israelin heimo, kaikki tyynni, mitä maassa on. Siellä minä heihin mielistyn, siellä minä halajan teidän antimianne, uutisverojanne, kaikkinaisia teidän pyhiä lahjojanne.'),
(1689898,58,26,20,41,'Niinkuin suloisesti tuoksuvaan uhriin minä teihin mielistyn, kun minä vien teidät pois kansojen seasta ja kokoan teidät maista, joihin olette hajotetut, ja osoitan teissä pyhyyteni pakanain silmien edessä.'),
(1689899,58,26,20,42,'Ja te tulette tietämään, että minä olen Herra, kun minä tuon teidät Israelin maahan, siihen maahan, jonka minä kättä kohottaen olin luvannut antaa teidän isillenne.'),
(1689900,58,26,20,43,'Ja te muistatte siellä vaelluksenne ja kaikki tekonne, joilla olette itsenne saastuttaneet, ja teitä kyllästyttää oma itsenne kaikkien pahain töittenne tähden, mitä olette tehneet.'),
(1689901,58,26,20,44,'Ja te tulette tietämään, että minä olen Herra, kun minä teen teille, minkä teen, oman nimeni tähden, en teidän pahan vaelluksenne enkä riettaiden tekojenne ansion mukaan, te Israelin heimo; sanoo Herra, Herra."'),
(1689902,58,26,20,45,'Ja minulle tuli tämä Herran sana:'),
(1689903,58,26,20,46,'"Ihmislapsi, käännä kasvosi etelää kohti, vuodata sanasi etelää vastaan ja ennusta kedon metsikköä vastaan, joka on Etelämaassa.'),
(1689904,58,26,20,47,'Ja sano Etelämaan metsikölle: Kuule Herran sana. Näin sanoo Herra, Herra: Katso, minä sytytän sinut tuleen, ja se kuluttaa kaikki sinun tuoreet puusi ja kuivat puusi. Ei sammu leimuava liekki, ja siitä kärventyvät kaikki kasvot, etelästä pohjoiseen asti;'),
(1689905,58,26,20,48,'ja kaikki liha on näkevä, että minä, Herra, olen sen sytyttänyt: se ei sammu."'),
(1689906,58,26,20,49,'Niin minä sanoin: "Voi Herra, Herra! Ne sanovat minusta: ''Tämähän puhuu pelkkiä vertauksia''."'),
(1689907,58,26,21,1,'Ja minulle tuli tämä Herran sana:'),
(1689908,58,26,21,2,'"Ihmislapsi, käännä kasvosi Jerusalemia kohti, vuodata sanasi pyhäköitä vastaan ja ennusta Israelin maata vastaan ja sano Israelin maalle:'),
(1689909,58,26,21,3,'Näin sanoo Herra: Katso, minä käyn sinun kimppuusi, vedän miekkani tupestaan ja hävitän sinusta vanhurskaan ja jumalattoman.'),
(1689910,58,26,21,4,'Koska minä tahdon hävittää sinusta vanhurskaan ja jumalattoman, sentähden lähtee tupestaan minun miekkani kaiken lihan kimppuun, etelästä pohjoiseen asti.'),
(1689911,58,26,21,5,'Ja kaikki liha tulee tietämään, että minä, Herra, olen vetänyt miekkani tupestaan; eikä se siihen enää palaja.'),
(1689912,58,26,21,6,'Mutta sinä, ihmislapsi, huokaile! Lanteet murtuneina, katkerassa tuskassa huokaile heidän silmiensä edessä.'),
(1689913,58,26,21,7,'Ja kun he sinulta kysyvät: ''Minkätähden sinä huokailet?'' niin sano: Sanoman tähden, sillä se saapuu, ja kaikki sydämet raukeavat, kaikki kädet herpoavat, kaikkien henki tyrmistyy, kaikki polvet käyvät veltoiksi kuin vesi. Katso, se tulee, se tapahtuu; sanoo Herra, Herra."'),
(1689914,58,26,21,8,'Ja minulle tuli tämä Herran sana:'),
(1689915,58,26,21,9,'"Ihmislapsi, ennusta ja sano: Näin sanoo Herra. Sano: Miekka, miekka on teroitettu, on myös kirkkaaksi hiottu.'),
(1689916,58,26,21,10,'Teurasta teurastamaan se on teroitettu, salamoitsevaksi se on hiottu. Vai iloitsisimmeko? Vitsa, joka lyö minun poikaani, pitää halpana kaiken, mikä puuta on.'),
(1689917,58,26,21,11,'Ja hän on antanut sen hioa otettavaksi käteen; se miekka on teroitettu, on hiottu annettavaksi surmaajan käteen.'),
(1689918,58,26,21,12,'Huuda ja valita, ihmislapsi, sillä tämä tapahtuu minun kansaani vastaan, kaikkia Israelin ruhtinaita vastaan: he ovat annetut alttiiksi miekalle, he ynnä minun kansani; lyö sentähden lanteeseesi.'),
(1689919,58,26,21,13,'Sillä vitsaa on jo koeteltu. Mutta entäpä, jos vitsa pitääkin halpana tämän kaiken? Se ei tapahdu, sanoo Herra, Herra.'),
(1689920,58,26,21,14,'Mutta sinä, ihmislapsi, ennusta ja lyö käsiäsi yhteen; tulkoon miekasta kaksi miekkaa, tulkoon kolme; se on surmattujen surmamiekka, miekka, joka surmaa suuretkin, joka kiertää heitä yltympäri,'),
(1689921,58,26,21,15,'että sydän pelkoon menehtyisi, että kompastuksia olisi paljon. Kaikille heidän porteillensa minä olen asettanut miekan välkkymään. Voi, se on tehty salamaksi, on hiottu teurastukseen!'),
(1689922,58,26,21,16,'Lyö terävästi oikealle, ojennu vasemmalle, mihin vain teräsi suunnataan.'),
(1689923,58,26,21,17,'Minäkin lyön käsiäni yhteen ja tyydytän kiivauteni. Minä, Herra, olen puhunut."'),
(1689924,58,26,21,18,'Ja minulle tuli tämä Herran sana:'),
(1689925,58,26,21,19,'"Sinä, ihmislapsi, laita kaksi tietä, Baabelin kuninkaan miekan tulla. Samasta maasta lähtekööt molemmat. Ja veistä viitta; veistä se kaupunkiin vievän tien suuhun.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689926,58,26,21,20,'Laita tie miekan tulla ammonilaisten Rabbaan sekä Juudaan, varustettuun Jerusalemiin.'),
(1689927,58,26,21,21,'Sillä Baabelin kuningas seisahtuu tien haaraan, molempain teitten suuhun, taikojansa taikomaan: hän pudistaa nuolia, kysyy kotijumalilta, tarkkaa maksaa.'),
(1689928,58,26,21,22,'Hänen oikeaan käteensä tulee Jerusalemin arpa: panna muurinmurtajia, avata suu ärjyntään, kohottaa sotahuuto, panna muurinmurtajia portteja vastaan, luoda valli, rakentaa saartovarusteet.'),
(1689929,58,26,21,23,'Mutta Jerusalemin asukkaiden silmissä tämä on pettävää taikomista: heillähän on valojen valat; mutta hän saattaa muistoon syntivelan, että he joutuisivat kiinni.'),
(1689930,58,26,21,24,'Sentähden, näin sanoo Herra, Herra: Koska te olette saattaneet muistoon syntivelkanne, kun rikkomuksenne ovat tulleet julki, niin että teidän syntinne on näkyvissä kaikissa teidän teoissanne, niin - koska te olette saatetut muistoon - teidät otetaan käsin kiinni.'),
(1689931,58,26,21,25,'Ja sinä saastutettu, jumalaton, sinä Israelin ruhtinas, jonka päivä on silloin tullut, kun syntivelka on loppumäärässään!'),
(1689932,58,26,21,26,'Näin sanoo Herra, Herra: Ota pois käärelakki, nosta pois kruunu.'),
(1689933,58,26,21,27,'Tämä ei jää tällensä: alhainen korotetaan, korkea alennetaan. Raunioiksi, raunioiksi, raunioiksi minä panen tämän; eikä tästä ole jäävä mitään, kunnes tulee hän, jolla on oikeus, ja minä annan sen hänelle.'),
(1689934,58,26,21,28,'Ja sinä, ihmislapsi, ennusta ja sano: Näin sanoo Herra, Herra ammonilaisia ja heidän herjauksiansa vastaan: Sano näin: Miekka, miekka on paljastettu, teurastukseen hiottu, saamaan kyllänsä, salamoitsemaan,'),
(1689935,58,26,21,29,'vaikka sinulle petollisia näkyjä nähdään, valheita ennustellaan, että sinut muka pannaan tallaamaan saastaisten, jumalattomain niskaa, joitten päivä on silloin tullut, kun syntivelka on loppumäärässään.'),
(1689936,58,26,21,30,'Pane se tuppeensa takaisin. Paikassa, jossa olet luotu, synnyinmaassasi, minä tahdon sinut tuomita.'),
(1689937,58,26,21,31,'Minä vuodatan sinun ylitsesi kiivastukseni, puhallan sinuun vihani tulen ja annan sinut raakain miesten käsiin, turmiontekijäin.'),
(1689938,58,26,21,32,'Tulen kulutettavaksi sinut annetaan, sinun veresi on oleva keskellä maata, ei sinua enää muisteta. Sillä minä, Herra, olen puhunut."'),
(1689939,58,26,22,1,'Ja minulle tuli tämä Herran sana:'),
(1689940,58,26,22,2,'"Sinä, ihmislapsi, etkö tuomitse, etkö tuomitse verivelkojen kaupunkia? Tee sille tiettäviksi kaikki sen kauhistukset'),
(1689941,58,26,22,3,'ja sano: Näin sanoo Herra, Herra: Voi kaupunkia, joka on vuodattanut keskuudessaan verta, että tulisi sen aika, ja tehnyt itselleen kivijumalia, että se siitä saastuisi!'),
(1689942,58,26,22,4,'Verestäsi, jonka olet vuodattanut, sinä olet tullut vikapääksi, ja kivijumalistasi, jotka olet tehnyt, sinä olet saastunut; sinä olet jouduttanut päiviäsi ja olet vuottesi määrään päässyt. Sentähden minä annan sinut pakanain häväistäväksi ja kaikkien maitten pilkaksi.'),
(1689943,58,26,22,5,'Läheiset ja kaukaiset pilkkaavat sinua, jonka nimi on saastutettu ja jossa on hämminkiä paljon.'),
(1689944,58,26,22,6,'Katso, Israelin ruhtinaat sinussa luottavat kukin omaan käsivarteensa vuodattaaksensa verta.'),
(1689945,58,26,22,7,'Isää ja äitiä sinussa ylenkatsotaan, muukalaiselle sinun keskelläsi tehdään väkivaltaa, orpoa ja leskeä sinussa sorretaan.'),
(1689946,58,26,22,8,'Mikä on minulle pyhitettyä, sitä sinä halveksit, minun sapattini sinä rikot.'),
(1689947,58,26,22,9,'Sinussa on niitä, jotka panettelevat vuodattaaksensa verta. Uhrivuorilla sinussa syödään. Ilkitöitä sinun keskelläsi tehdään.'),
(1689948,58,26,22,10,'Isän häpy sinussa paljastetaan. Naiselle, joka on saastainen kuukautistilansa tähden, tehdään sinussa väkivaltaa.'),
(1689949,58,26,22,11,'Toinen harjoittaa kauhistusta toisensa vaimon kanssa, mies saastuttaa sukurutsauksessa miniänsä, mies tekee sinussa väkivaltaa sisarelleen, isänsä tyttärelle.'),
(1689950,58,26,22,12,'Sinussa otetaan lahjuksia veren vuodattamiseksi, sinä otat korkoa ja voittoa, kiskot väkivaltaisesti lähimmäistäsi, mutta minut sinä unhotat, sanoo Herra, Herra.'),
(1689951,58,26,22,13,'Mutta katso, minä lyön käsiäni yhteen sinun väärän voittosi tähden, jota olet hankkinut, ja sinun verivelkojesi tähden, joita keskuudessasi on.'),
(1689952,58,26,22,14,'Kestääköhän rohkeutesi, pysyvätköhän kätesi lujina niinä päivinä, joina minä sinulle teen, minkä teen? Minä, Herra, olen puhunut, ja minä teen sen.'),
(1689953,58,26,22,15,'Minä hajotan sinut pakanain sekaan ja sirotan sinut muihin maihin ja poistan sinusta saastaisuutesi.'),
(1689954,58,26,22,16,'Sinä tulit saastaiseksi oman itsesi tähden kansojen silmissä, mutta sinä tulet tietämään, että minä olen Herra."'),
(1689955,58,26,22,17,'Ja minulle tuli tämä Herran sana:'),
(1689956,58,26,22,18,'"Ihmislapsi, Israelin heimo on kuonaksi tullut. He ovat kaikki tyynni vaskea, tinaa, rautaa ja lyijyä ahjossa; he ovat tulleet hopean kuonaksi.'),
(1689957,58,26,22,19,'Sentähden, näin sanoo Herra, Herra: Koska te kaikki tyynni olette tulleet kuonaksi, sentähden, katso, minä kokoan teidät keskelle Jerusalemia.'),
(1689958,58,26,22,20,'Niinkuin hopea, vaski, rauta, lyijy ja tina kootaan keskelle ahjoa, että niihin lietsottaisiin tulta ja ne sulatettaisiin, niin minä vihassani ja kiivaudessani teidät kokoan ja asetan ahjoon ja sulatan.'),
(1689959,58,26,22,21,'Minä kerään teidät ja lietson teihin vihani tulta, ja te sulatte keskellä Jerusalemia.'),
(1689960,58,26,22,22,'Niinkuin hopea sulatetaan keskellä ahjoa, niin sulatetaan teidät sen keskellä. Ja te tulette tietämään, että minä, Herra, olen vuodattanut kiivauteni teidän ylitsenne."'),
(1689961,58,26,22,23,'Ja minulle tuli tämä Herran sana:'),
(1689962,58,26,22,24,'"Ihmislapsi, sano sille: Sinä olet maa, jota ei ole puhdistettu, joka ei ole saanut sadetta vihan päivänä.'),
(1689963,58,26,22,25,'Profeettain salaliitto sen keskellä on niinkuin ärjyvä, saalista raateleva leijona: he syövät sieluja, ottavat aarteet ja kalleudet ja lisäävät sen keskuudessa sen leskien lukua.'),
(1689964,58,26,22,26,'Sen papit tekevät väkivaltaa minun lailleni ja häpäisevät sitä, mikä on minulle pyhitetty, eivät tee erotusta pyhän ja epäpyhän välillä, eivät tee tiettäväksi, mikä on saastaista, mikä puhdasta, ja sulkevat silmänsä minun sapateiltani, niin että minä tulen häväistyksi heidän keskellänsä.'),
(1689965,58,26,22,27,'Sen päämiehet siellä ovat niinkuin saalista raatelevaiset sudet: he vuodattavat verta, hukuttavat sieluja kiskoaksensa väärää voittoa.'),
(1689966,58,26,22,28,'Sen profeetat valkaisevat heille kaiken kalkilla, kun näkevät petollisia näkyjä ja ennustelevat heille valheita sanoen: ''Näin sanoo Herra, Herra'', vaikka Herra ei ole puhunut.'),
(1689967,58,26,22,29,'Maan kansa harjoittaa väkivaltaa, riistää ja raastaa: kurjaa ja köyhää he sortavat, muukalaiselle tekevät väkivaltaa oikeudesta välittämättä.'),
(1689968,58,26,22,30,'Minä etsin heidän joukostansa miestä, joka korjaisi muurin ja seisoisi muurinaukossa minun edessäni maan puolesta, etten minä sitä hävittäisi, mutta en löytänyt.'),
(1689969,58,26,22,31,'Sentähden minä vuodatan heidän ylitsensä kiivauteni, hukutan heidät vihani tulella ja annan heidän vaelluksensa tulla heidän päänsä päälle, sanoo Herra, Herra."'),
(1689970,58,26,23,1,'Ja minulle tuli tämä Herran sana:'),
(1689971,58,26,23,2,'"Ihmislapsi, oli kaksi naista, saman äidin tyttäriä.'),
(1689972,58,26,23,3,'He harjoittivat haureutta Egyptissä; nuoruudessaan he haureutta harjoittivat. Siellä heidän rintojansa likisteltiin ja heidän neitsyellisiä nisiänsä puristeltiin.'),
(1689973,58,26,23,4,'Heidän nimensä olivat: vanhemman Ohola ja hänen sisarensa Oholiba. Sitten he tulivat minun omikseni ja synnyttivät poikia ja tyttäriä. - Heidän nimensä: Samaria on Ohola ja Jerusalem Oholiba.'),
(1689974,58,26,23,5,'Mutta Ohola harjoitti haureutta, vaikka oli minun, ja himoitsi rakastajiansa, assurilaisia, naapureita,'),
(1689975,58,26,23,6,'jotka olivat punasiniseen purppuraan puettuja ja olivat käskynhaltijoita ja päämiehiä, komeita nuorukaisia kaikki, ratsumiehiä, hevosen selässä ajajia.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1689976,58,26,23,7,'Ja hän antautui haureuteen näiden kanssa, jotka olivat Assurin valiopoikia kaikki; ja keitä vain hän himoitsi, niiden kaikkien kanssa hän saastutti itsensä kaikilla heidän kivijumalillaan.'),
(1689977,58,26,23,8,'Mutta Egyptin-aikaista haureuttansa hän ei jättänyt, sillä he olivat maanneet hänen kanssansa hänen nuoruudessaan, olivat puristelleet hänen neitsyellisiä nisiänsä ja vuodattaneet hänen ylitsensä haureuttaan.'),
(1689978,58,26,23,9,'Sentähden minä annoin hänet rakastajainsa käsiin, Assurin poikain käsiin, joita hän oli himoinnut.'),
(1689979,58,26,23,10,'He paljastivat hänen häpynsä ja ottivat hänen poikansa ja tyttärensä ja tappoivat hänet itsensä miekalla, niin että hänestä tuli varoittava esimerkki muille naisille, ja panivat hänessä toimeen tuomiot.'),
(1689980,58,26,23,11,'Mutta hänen sisarensa Oholiba, vaikka näki tämän, oli himossaan vielä häntäkin riettaampi ja oli haureudessaan vielä riettaampi, kuin hänen sisarensa oli ollut haureudessaan.'),
(1689981,58,26,23,12,'Hän himoitsi Assurin poikia, jotka olivat käskynhaltijoita, päämiehiä, naapureita, pulskasti puettuja, ratsumiehiä, hevosen selässä ajajia, komeita nuorukaisia kaikki.'),
(1689982,58,26,23,13,'Silloin minä näin, että hän saastutti itsensä: sama oli tie kumpaisellakin.'),
(1689983,58,26,23,14,'Mutta hän meni vielä pitemmälle haureudessaan; kun hän näki seinään piirrettyjä miehiä, kaldealaisten kuvia, punavärillä piirrettyjä,'),
(1689984,58,26,23,15,'vyö vyötettynä kupeille, päässä muhkea päähine, sankarien näköisiä kaikki, Baabelin poikain muotoisia, joiden synnyinmaa on Kaldea,'),
(1689985,58,26,23,16,'niin hän silmän näkemältä sai himon heihin ja lähetti lähettiläitä heidän luoksensa Kaldeaan.'),
(1689986,58,26,23,17,'Niin Baabelin pojat tulivat ja makasivat hänen kanssaan hekumassa ja saastuttivat hänet haureudellaan, niin että hän saastui heistä. Sitten hänen sielunsa vieraantui heistä.'),
(1689987,58,26,23,18,'Mutta kun hän paljasti haureutensa ja paljasti häpynsä, niin minun sieluni vieraantui hänestä, niinkuin minun sieluni oli vieraantunut hänen sisarestansa.'),
(1689988,58,26,23,19,'Mutta hän yhä enensi haureuttaan, kun muisti nuoruutensa päivät, jolloin oli haureutta harjoittanut Egyptin maassa.'),
(1689989,58,26,23,20,'Ja hän sai himon heidän hekumoitsijoihinsa, joilla on jäsen kuin aaseilla ja vuoto kuin orheilla.'),
(1689990,58,26,23,21,'Ja sinä etsit nuoruutesi iljettävyyttä, jolloin egyptiläiset puristelivat nisiäsi nuorekkaiden rintojesi tähden.'),
(1689991,58,26,23,22,'Sentähden, Oholiba, näin sanoo Herra, Herra: Katso, minä nostatan sinun kimppuusi rakastajasi, joista sielusi on vieraantunut, ja tuon heidät sinun kimppuusi joka taholta:'),
(1689992,58,26,23,23,'Baabelin pojat ja kaikki kaldealaiset, Pekodin, Sooan ja Kooan ja heidän kanssaan kaikki Assurin pojat - komeita nuorukaisia, käskynhaltijoita ja päämiehiä kaikki, sankareita ja mainioita miehiä, ratsumiehiä, hevosten selässä ajajia kaikki.'),
(1689993,58,26,23,24,'He tulevat sinun kimppuusi, mukanaan paljon vaunuja ja rattaita ja suuret joukot kansoja; suurine ja pienine kilpineen ja kypäreineen he käyvät sinua vastaan joka taholta. Minä annan heille tuomiovallan, ja he tuomitsevat sinut oikeuksiensa mukaan.'),
(1689994,58,26,23,25,'Minä osoitan sinussa kiivauteni, niin että he kohtelevat sinua tuimasti: he leikkaavat sinulta pois nenän ja korvat, ja sinun jälkeläisesi kaatuvat miekkaan. He ottavat sinun poikasi ja tyttäresi, ja sinun jälkeläisesi kuluttaa tuli.'),
(1689995,58,26,23,26,'He raastavat sinulta vaatteesi ja ottavat korukalusi.'),
(1689996,58,26,23,27,'Niin minä teen lopun sinun iljettävyydestäsi, jo Egyptin-aikaisesta haureudestasi; etkä sinä sitten luo silmiäsi heihin etkä enää muistele Egyptiä.'),
(1689997,58,26,23,28,'Sillä näin sanoo Herra, Herra: Katso, minä annan sinut niitten käsiin, joita vihaat, niitten käsiin, joista sielusi on vieraantunut.'),
(1689998,58,26,23,29,'Ja he kohtelevat sinua vihamielisesti, ottavat kaiken vaivannäkösi ja jättävät sinut alastomaksi ja paljaaksi; ja sinun haureellinen häpysi ja iljettävyytesi ja haureutesi paljastuu.'),
(1689999,58,26,23,30,'Näin sinulle tehdään sentähden, että uskottomana juoksit pakanain perässä, että saastutit itsesi heidän kivijumalillansa.'),
(1690000,58,26,23,31,'Sinä vaelsit sisaresi tietä, ja minä annan hänen maljansa sinun käteesi.'),
(1690001,58,26,23,32,'Näin sanoo Herra, Herra: Sisaresi maljan sinä juot, syvän ja laajan ja paljon vetävän. Sinä tulet nauruksi ja pilkaksi.'),
(1690002,58,26,23,33,'Tulet juopumusta ja murhetta täyteen: kauhun ja häviön malja on sinun sisaresi Samarian malja.'),
(1690003,58,26,23,34,'Sen sinä juot ja särvit, sen sirpaleita sinä kaluat ja niillä rintasi revit. Sillä minä olen puhunut, sanoo Herra, Herra.'),
(1690004,58,26,23,35,'Sentähden, näin sanoo Herra, Herra: Koska sinä olet minut unhottanut, minut selkäsi taakse heittänyt, niin kanna myös iljettävyytesi ja haureutesi."'),
(1690005,58,26,23,36,'Ja Herra sanoi minulle: "Ihmislapsi, etkö tuomitse Oholaa ja Oholibaa? Ilmoita heille heidän kauhistuksensa.'),
(1690006,58,26,23,37,'Sillä he ovat rikkoneet avion, ja heidän käsissään on verta; kivijumalainsa kanssa he ovat avion rikkoneet, ja myös lapsensa, jotka he olivat minulle synnyttäneet, he ovat polttaneet, ruuaksi niille.'),
(1690007,58,26,23,38,'Vielä tämänkin he ovat minulle tehneet: ovat samana päivänä saastuttaneet minun pyhäkköni ja rikkoneet minun sapattini.'),
(1690008,58,26,23,39,'Teurastettuaan lapsiansa kivijumalilleen he samana päivänä tulivat minun pyhäkkööni ja niin häpäisivät sen. Katso, näin he ovat tehneet keskellä minun huonettani.'),
(1690009,58,26,23,40,'Vieläpä he lähettivät sanan miehille, jotka tulivat kaukaa: katso, ne tulivat siinä samassa, kun sana oli lähetetty, nuo, joita varten sinä peseydyit ja maalasit silmäluomesi ja panit päällesi korut.'),
(1690010,58,26,23,41,'Ja sinä istuit komealle vuoteelle, sen ääressä oli katettu pöytä, ja sille sinä panit minun suitsukkeeni ja öljyni.'),
(1690011,58,26,23,42,'Sitten sieltä kuului suruton melu. Ihmisjoukosta otettujen miesten lisäksi tuotiin erämaasta juomareita, ja ne panivat noiden naisten käsiin rannerenkaat ja heidän päähänsä kauniit kruunut.'),
(1690012,58,26,23,43,'Mutta minä sanoin: ''Tuollekin kuihtuneelle kelpaa aviorikos! Hänen kanssaan nyt harjoitetaan haureutta - ja vielä hänkin!'''),
(1690013,58,26,23,44,'Hänen luoksensa tultiin, aivan kuin tullaan porttonaisen luo: niin tultiin Oholan ja Oholiban luokse - noiden iljettävien naisten.'),
(1690014,58,26,23,45,'Mutta vanhurskaat miehet tulevat tuomitsemaan heidät sen mukaan, mitä on säädetty avionrikkoja-naisista ja mitä on säädetty verenvuodattaja-naisista; sillä he ovat rikkoneet avion, ja heidän käsissään on verta.'),
(1690015,58,26,23,46,'Sillä näin sanoo Herra, Herra: Nostatettakoon kansanjoukko heitä vastaan, ja heidät pantakoon kauhistukseksi ja ryöstettäköön.'),
(1690016,58,26,23,47,'Ja kansanjoukko kivittäköön heidät ja hakatkoon kappaleiksi miekoillansa; tappakoot ne heidän poikansa ja tyttärensä ja polttakoot heidän talonsa tulella.'),
(1690017,58,26,23,48,'Niin minä lopetan iljettävän menon maasta. Ja kaikki naiset ottavat siitä ojentuakseen, niin etteivät harjoita iljettävää menoa, niinkuin te.'),
(1690018,58,26,23,49,'Teidän iljettävyytenne pannaan teidän päällenne, ja te saatte kantaa kivijumalainne kanssa tehdyt syntinne. Ja te tulette tietämään, että minä olen Herra, Herra."'),
(1690019,58,26,24,1,'Tämä Herran sana tuli minulle yhdeksäntenä vuotena, kymmenennessä kuussa, kuukauden kymmenentenä päivänä:'),
(1690020,58,26,24,2,'"Ihmislapsi, kirjoita muistiisi päivän nimi - juuri tämän päivän nimi: Baabelin kuningas rynnistää Jerusalemia vastaan juuri tänä päivänä.'),
(1690021,58,26,24,3,'Lausu uppiniskaiselle suvulle vertaus ja sano heille: Näin sanoo Herra, Herra: Pane pata liedelle, pane. Kaada myös siihen vettä.'),
(1690022,58,26,24,4,'Kokoile siihen lihakappaleet - kaikki hyvät kappaleet, reittä ja lapaa - ja täytä se valituilla luilla.'),
(1690023,58,26,24,5,'Ota valiolampaita, lado myös halkoja sen alle. Anna sen kiehumistaan kiehua, niin että siinä luutkin tulevat keitetyiksi.'),
(1690024,58,26,24,6,'Sentähden, näin sanoo Herra, Herra: Voi verivelkojen kaupunkia, pataa, joka on ruostunut ja josta ei lähde sen ruoste! Tyhjennä se kappale kappaleelta: sille ei ole langennut arpaosaa.'),
(1690025,58,26,24,7,'Sillä sen vuodattama veri on sen keskellä, paljaalle kalliolle se on sen koonnut, ei ole vuodattanut sitä maahan, tomun peitettäväksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690026,58,26,24,8,'Nostattaakseni kiivauden, tuottaakseni koston minä olen pannut sen veren paljaalle kalliolle, ettei se peittyisi.'),
(1690027,58,26,24,9,'Sentähden, näin sanoo Herra, Herra: Voi verivelkojen kaupunkia! Minäkin suurennan liettä.'),
(1690028,58,26,24,10,'Lisää halkoja, viritä tulta, keitä liha loppuun, kiehuta liemi kuiviin, polta luut karreksi.'),
(1690029,58,26,24,11,'Anna sen sitten olla tyhjänä hiiltensä päällä, niin että se kuumenee, sen vaski hehkuu ja sen saastat siitä sulavat, sen ruosteesta tulee loppu.'),
(1690030,58,26,24,12,'Siitä on ollut vaivaa väsymykseen asti, mutta ei ole lähtenyt siitä sen ruosteen paljous. Tuleen sen ruoste!'),
(1690031,58,26,24,13,'Sinun iljettävän saastaisuutesi takia - koska minä tahdoin puhdistaa sinut, mutta sinä et puhdistunut saastaisuudestasi - sinä et enää puhdistu, ennenkuin minä olen tyydyttänyt kiivauteni sinussa.'),
(1690032,58,26,24,14,'Minä, Herra, olen puhunut. Se tapahtuu, ja minä teen sen. Minä en hellitä, en säästä enkä kadu: teittesi ja tekojesi mukaan sinut tuomitaan, sanoo Herra, Herra."'),
(1690033,58,26,24,15,'Ja minulle tuli tämä Herran sana:'),
(1690034,58,26,24,16,'"Ihmislapsi, katso, minä otan sinulta äkkikuolemalla pois silmiesi ihastuksen, mutta älä valita, älä itke, älköönkä tulko sinulta kyyneltä.'),
(1690035,58,26,24,17,'Huokaile hiljaa, mutta älä pane toimeen kuolleenvalittajaisia. Sido juhlapäähine päähäsi, pane kengät jalkaasi, älä peitä partaasi äläkä syö suruleipää."'),
(1690036,58,26,24,18,'Ja minä puhuin kansalle aamulla, mutta illalla kuoli minun vaimoni; sitten aamulla minä tein, niinkuin minun oli käsketty tehdä.'),
(1690037,58,26,24,19,'Niin kansa sanoi minulle: "Etkö meille ilmoita, mitä se tietää meille, kun sinä noin teet?"'),
(1690038,58,26,24,20,'Minä sanoin heille: "Minulle tuli tämä Herran sana: Sano Israelin heimolle:'),
(1690039,58,26,24,21,'Näin sanoo Herra, Herra: Katso, minä häpäisen pyhäkköni, joka on teidän varustuksenne ja ylpeytenne, teidän silmienne ihastus ja sielujenne ikävä; ja teidän poikanne ja tyttärenne, jotka teidän on ollut jätettävä, kaatuvat miekkaan.'),
(1690040,58,26,24,22,'Sitten te teette, niinkuin minä olen tehnyt: ette peitä partaanne ettekä syö suruleipää,'),
(1690041,58,26,24,23,'juhlapäähineen pidätte päässänne ja kengät jalassanne, ette valita ettekä itke, mutta te riudutte syntivelkanne tähden ja huokailette toinen toisellenne.'),
(1690042,58,26,24,24,'Hesekiel on oleva teille ennusmerkki: aivan niin, kuin hän on tehnyt, niin tekin teette. Kun tämä tapahtuu, te tulette tietämään, että minä olen Herra, Herra.'),
(1690043,58,26,24,25,'Ja sinä, ihmislapsi! Sinä päivänä, jona minä otan heiltä heidän varustuksensa, ihanan ilonsa, silmiensä ihastuksen, sielujensa halajamisen, heidän poikansa ja tyttärensä,'),
(1690044,58,26,24,26,'sinä päivänä tulee pakolainen sinun luoksesi ilmoittamaan tätä korvaisi kuullen.'),
(1690045,58,26,24,27,'Sinä päivänä avautuu sinun suusi yhtaikaa kuin pakolaisen, ja sinä puhut etkä enää ole mykkänä. Sinä olet oleva heille ennusmerkki, ja he tulevat tietämään, että minä olen Herra."'),
(1690046,58,26,25,1,'Minulle tuli tämä Herran sana:'),
(1690047,58,26,25,2,'"Ihmislapsi, käännä kasvosi ammonilaisia kohti ja ennusta heitä vastaan'),
(1690048,58,26,25,3,'ja sano ammonilaisille: Kuulkaa Herran, Herran sana: Näin sanoo Herra, Herra: Koska sinä sanoit: ''Kas niin!'' minun pyhäköstäni, kun se häväistiin, ja Israelin maasta, kun se hävitettiin, ja Juudan heimosta, kun he menivät pakkosiirtolaisuuteen,'),
(1690049,58,26,25,4,'sentähden, katso, minä annan sinut Idän miehille omaksi, ja he laittavat sinuun leiripaikkansa ja asettavat sinuun asuntonsa. He syövät sinun hedelmäsi ja juovat maitosi.'),
(1690050,58,26,25,5,'Ja Rabban minä panen kamelien laitumeksi ja ammonilaisten maan lammaslaumojen leposijaksi. Ja te tulette tietämään, että minä olen Herra.'),
(1690051,58,26,25,6,'Sillä näin sanoo Herra, Herra: Koska sinä käsiä taputit ja jalkaa poljit ja, sielu täynnä ylenkatsetta, pidit iloa Israelin maasta,'),
(1690052,58,26,25,7,'sentähden, katso, minä ojennan käteni sinua vastaan ja annan sinut pakanain ryöstettäväksi ja hävitän sinut kansojen joukosta ja hukutan sinut maitten luvusta ja tuhoan sinut. Ja sinä tulet tietämään, että minä olen Herra.'),
(1690053,58,26,25,8,'Näin sanoo Herra, Herra: Koska Mooab ja Seir ovat sanoneet: ''Katso, Juudan heimon käy samoin kuin kaikkien muitten kansain'','),
(1690054,58,26,25,9,'sentähden, katso, minä teen avonaiseksi Mooabin vuoriselänteen, paljaaksi kaupungeista - kaupungeista sen rajasta toiseen - jotka ovat maan kaunistus: Beet-Jesimot, Baal-Meon ja Kirjataim.'),
(1690055,58,26,25,10,'Idän miehille omaksi minä annan sen ynnä ammonilaiset, niin ettei ammonilaisia enää muisteta kansojen seassa,'),
(1690056,58,26,25,11,'ja Mooabissa minä panen toimeen tuomiot. Ja he tulevat tietämään, että minä olen Herra.'),
(1690057,58,26,25,12,'Näin sanoo Herra, Herra: Koska Edom menetteli kovin kostonhimoisesti Juudan heimoa kohtaan ja tuli suuresti syynalaiseksi, kostaessansa heille,'),
(1690058,58,26,25,13,'sentähden, näin sanoo Herra, Herra: Minä ojennan käteni Edomia vastaan ja hävitän siitä ihmiset ja eläimet. Teemanista lähtien minä panen sen raunioiksi, ja Dedania myöten he kaatuvat miekkaan.'),
(1690059,58,26,25,14,'Ja kostoni, joka Edomia kohtaa, minä annan kansani Israelin käteen, ja he tekevät Edomia kohtaan minun vihani ja kiivauteni mukaan. Ja Edom saa tuntea minun kostoni, sanoo Herra, Herra.'),
(1690060,58,26,25,15,'Näin sanoo Herra, Herra: Koska filistealaiset menettelivät kostonhimoisesti ja, ylenkatse sielussaan, kostivat kovasti, ikivihassa tuottaaksensa tuhon,'),
(1690061,58,26,25,16,'sentähden, näin sanoo Herra, Herra: Katso, minä ojennan käteni filistealaisia vastaan, hävitän kreetit, hukutan, mitä on jäljellä meren rannikolla,'),
(1690062,58,26,25,17,'ja teen heille suuret kostoteot, rangaisten kiivaudessa. Ja he tulevat tietämään, että minä olen Herra, kun minä annan kostoni heitä kohdata."'),
(1690063,58,26,26,1,'Yhdentenätoista vuotena, kuukauden ensimmäisenä päivänä, tuli minulle tämä Herran sana:'),
(1690064,58,26,26,2,'"Ihmislapsi, koska Tyyro sanoi Jerusalemista: ''Kas niin! Murrettu on kansojen ovi, minuun päin se on kääntynyt, minä tulen täyteen - se on rauniona!'''),
(1690065,58,26,26,3,'sentähden, näin sanoo Herra, Herra: Katso, minä käyn sinun kimppuusi, Tyyro, ja nostatan monet kansat sinua vastaan, niinkuin meri nostaa aaltonsa.'),
(1690066,58,26,26,4,'Ne hävittävät Tyyron muurit, repivät maahan sen tornit, ja minä lakaisen siitä pois sen tomutkin ja panen sen paljaaksi kallioksi.'),
(1690067,58,26,26,5,'Siitä tulee verkkojen kuivauspaikka keskelle merta. Sillä minä olen puhunut, sanoo Herra, Herra; ja se joutuu kansojen ryöstettäväksi.'),
(1690068,58,26,26,6,'Sen tytärkaupungit, jotka ovat mantereella, surmataan miekalla, ja he tulevat tietämään, että minä olen Herra.'),
(1690069,58,26,26,7,'Sillä näin sanoo Herra, Herra: Katso, minä tuon Tyyron kimppuun Nebukadressarin, Baabelin kuninkaan pohjoisesta, kuninkaitten kuninkaan, hevosten ja vaunujen ja ratsumiesten ja suuren väenpaljouden kanssa.'),
(1690070,58,26,26,8,'Sinun tytärkaupunkisi, jotka ovat mantereella, hän surmaa miekalla ja asettaa sinua vastaan saartovarusteet, luo sinua vastaan vallin, nostaa sinua vastaan kilpikatoksen,'),
(1690071,58,26,26,9,'suuntaa sinun muureihisi murtajansa iskut ja kukistaa tornisi rauta-aseillansa.'),
(1690072,58,26,26,10,'Hänen hevostensa paljous peittää sinut pölyyn. Ratsumiesten, pyöräin ja vaunujen ryskeestä sinun muurisi vapisevat, kun hän hyökkää sisälle sinun porteistasi, niinkuin valloitettuun kaupunkiin hyökätään.'),
(1690073,58,26,26,11,'Hevostensa kavioilla hän tallaa rikki sinun katusi kaikki, surmaa miekalla sinun kansasi, ja sinun mahtavat patsaasi kaatuvat maahan.'),
(1690074,58,26,26,12,'He riistävät sinun rikkautesi ja ryöstävät kauppatavarasi, repivät muurisi maahan ja kukistavat kauniit talosi, ja kivesi, puusi, tomusi he heittävät meren syvyyteen.'),
(1690075,58,26,26,13,'Minä lakkautan laulujesi helinän, eikä kuulu enää kanneltesi soitto.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690076,58,26,26,14,'Minä panen sinut paljaaksi kallioksi, sinusta tulee verkkojen kuivauspaikka, eikä sinua enää rakenneta. Sillä minä, Herra, olen puhunut, sanoo Herra, Herra.'),
(1690077,58,26,26,15,'Näin sanoo Herra, Herra Tyyrolle: Eivätkö sinun kukistumisesi pauhusta, kun haavoitetut voihkivat, kun surman omat surmataan sinun keskelläsi, saaret vapise?'),
(1690078,58,26,26,16,'Valtaistuimiltaan astuvat alas kaikki meren ruhtinaat. He heittävät pois viittansa ja riisuvat kirjaellut vaatteensa, he pukeutuvat kauhuun ja istuvat maahan, värisevät joka hetki, tyrmistyneinä sinun tähtesi.'),
(1690079,58,26,26,17,'He virittävät sinusta itkuvirren ja sanovat sinulle: ''Kuinka olet sinä, joka olit asuttu, hävinnyt meriltä, sinä ylistetty kaupunki, väkevä merellä, sinä ja sinun asukkaasi, jotka levittivät kauhuansa kaikkiin siellä asuvaisiin.'),
(1690080,58,26,26,18,'Nyt värisevät saaret sinun kukistumisesi päivänä, merensaaret kauhistuvat sinun loppuasi.'''),
(1690081,58,26,26,19,'Sillä näin sanoo Herra, Herra: Kun minä teen sinusta aution kaupungin, niinkuin asumattomat kaupungit ovat, kun minä annan syvyyden käydä sinun ylitsesi ja paljot vedet peittävät sinut,'),
(1690082,58,26,26,20,'silloin minä syöksen sinut alas hautaanvaipuneitten pariin, ikiaikojen kansan tykö, ja annan sinulle asunnon maan syvyyksissä, niinkuin siellä ovat ikiaikojen rauniot, hautaanvaipuneitten parissa, ettei sinussa asuttaisi; mutta ihanuuden minä annan elävien maahan.'),
(1690083,58,26,26,21,'Sinut minä panen kauhuksi, sinua ei sitten enää ole; ja jos sinua etsitään, ei sinua enää löydy, hamaan ikiaikoihin asti, sanoo Herra, Herra."'),
(1690084,58,26,27,1,'Ja minulle tuli tämä Herran sana:'),
(1690085,58,26,27,2,'"Sinä, ihmislapsi! Viritä itkuvirsi Tyyrosta'),
(1690086,58,26,27,3,'ja sano Tyyrolle, joka asuu meren porteilla ja käy kauppaa kansojen kanssa, monilukuisilla saarilla: Näin sanoo Herra, Herra: Tyyro, sinä sanot: ''Minä olen kauneuden täydellisyys!'''),
(1690087,58,26,27,4,'Meren sydämessä on sinun alueesi, rakentajasi tekivät sinun kauneutesi täydelliseksi,'),
(1690088,58,26,27,5,'Senirin kypresseistä he rakensivat sinuun kaiken, mikä laudoista on, ottivat Libanonin setrin tehdäkseen sinuun maston,'),
(1690089,58,26,27,6,'tekivät Baasanin tammista airosi, kantesi tekivät norsunluusta ja Kittiläis-saarten hopeakuusesta.'),
(1690090,58,26,27,7,'Kirjaeltua Egyptin pellavaa oli purjeesi, ja se oli sinulla lippuna. Katoksesi oli punasinistä ja purppuranpunaista Elisa-saarten kangasta.'),
(1690091,58,26,27,8,'Siidonin ja Arvadin asukkaat olivat sinulla soutajina; omat viisaasi, Tyyro, olivat sinussa - he olivat laivureinasi.'),
(1690092,58,26,27,9,'Gebalin vanhimmat ja viisaat olivat sinussa vuotokohtain korjaajina. Meren kaikki laivat merimiehineen olivat sinussa tavaroitasi vaihtamassa.'),
(1690093,58,26,27,10,'Persia ja Luud ja Puut olivat sotajoukossasi, sinun sotureinasi. He ripustivat sinuun kypäreitä ja kilpiä; ne sinua koristivat.'),
(1690094,58,26,27,11,'Arvadilaiset ja muu sotajoukkosi olivat muureillasi yltympäri ja gammadilaiset torneissasi. He ripustivat varustuksensa sinun muureillesi yltympäri; ne tekivät sinun kauneutesi täydelliseksi.'),
(1690095,58,26,27,12,'Tarsis oli kauppatuttusi sinun kaikkinaisten rikkauksiesi runsauden takia: hopealla, raudalla, tinalla ja lyijyllä he maksoivat sinun tavarasi.'),
(1690096,58,26,27,13,'Jaavan, Tuubal ja Mesek kävivät kauppaa sinun kanssasi: orjilla ja vaskikaluilla he maksoivat sinun vaihtotavarasi.'),
(1690097,58,26,27,14,'Toogarman heimo maksoi sinun tavarasi hevosilla, sotaratsuilla ja muuleilla.'),
(1690098,58,26,27,15,'Dedanilaiset kävivät kauppaa sinun kanssasi. Monilukuiset saaret olivat kauppatuttujasi, sinun käskysi alaisia; norsunhampaita ja mustaa puuta ne toivat sinulle verona.'),
(1690099,58,26,27,16,'Aram oli kauppatuttusi sinun tuotteittesi runsauden takia: rubiineilla, punapurppuralla, kirjaellulla kankaalla, valkopellavalla, koralleilla ja jaspiksella he maksoivat sinun tavarasi.'),
(1690100,58,26,27,17,'Juuda ja Israelin maa kävivät kauppaa sinun kanssasi: Minnitin nisulla, leivoksilla, hunajalla, öljyllä ja balsamilla he maksoivat sinun vaihtotavarasi.'),
(1690101,58,26,27,18,'Damasko oli kauppatuttusi sinun tuotteittesi runsauden ja kaikkinaisten rikkauksiesi runsauden takia: Helbonin viiniä ja Saharin villoja.'),
(1690102,58,26,27,19,'Vedan ja Jaavan maksoivat sinun tavarasi kehruuteoksilla; taottua rautaa, kassiaa ja kalmoruokoa tuli sinulle vaihtotavarana.'),
(1690103,58,26,27,20,'Dedan kävi kauppaa sinun kanssasi ratsastussatulain loimilla.'),
(1690104,58,26,27,21,'Arabia ja kaikki Keedarin ruhtinaat olivat kauppatuttaviasi, sinun käskysi alaisia: lampaita, oinaita ja vuohipukkeja he sinulle kauppasivat.'),
(1690105,58,26,27,22,'Saban ja Raman kauppiaat kävivät kauppaa sinun kanssasi: kaikkinaisilla parhailla balsameilla, kaikilla kalliilla kivillä ja kullalla he maksoivat sinun tavarasi.'),
(1690106,58,26,27,23,'Haaran ja Kanne ja Eden, Saban kauppiaat, Assur ja Kilmad kävivät kauppaa sinun kanssasi;'),
(1690107,58,26,27,24,'he kävivät kanssasi kauppaa sinun markkinoillasi kauniilla vaatteilla, punasinisillä ja kirjaelluilla vaipoilla, kirjavakuteisilla matoilla ja punotuilla, kestävillä köysillä.'),
(1690108,58,26,27,25,'Tarsiin-laivat kuljettivat sinun vaihtotavaroitasi. Niin sinä tulit täpötäyteen ja ylen raskaaseen lastiin merten sydämessä.'),
(1690109,58,26,27,26,'Soutajasi veivät sinut suurille vesille. - Itätuuli särkee sinut merten sydämessä.'),
(1690110,58,26,27,27,'Sinun rikkautesi, tavarasi, vaihtotavarasi, merimiehesi ja laivurisi, vuotokohtaisi korjaajat, tavaranvaihtajasi ja kaikki sotamiehesi, jotka ovat sinussa ja koko suuressa joukossasi, joka sinun keskelläsi on, vaipuvat merten sydämeen sinun kukistumisesi päivänä.'),
(1690111,58,26,27,28,'Laivuriesi parkunan äänestä vapisevat tantereet.'),
(1690112,58,26,27,29,'Alas haaksistansa astuvat kaikki aironpitelijät, merimiehet ja kaikki meren laivurit astuvat maihin,'),
(1690113,58,26,27,30,'huutavat sinun tähtesi suurella äänellä ja parkuvat haikeasti, heittävät tomua päänsä päälle ja vieriskelevät tuhassa.'),
(1690114,58,26,27,31,'He ajelevat sinun tähtesi päänsä paljaaksi, kääriytyvät säkkeihin ja itkevät sinun tähtesi, mieli murheellisena, valittaen haikeasti.'),
(1690115,58,26,27,32,'He valittaessaan virittävät sinusta itkuvirren ja laulavat sinusta: ''Kuka oli Tyyron vertainen, hänen, joka nyt on niin hiljaa keskellä merta?'),
(1690116,58,26,27,33,'Kun sinun tavarasi saapuivat meriltä, ravitsit sinä monet kansat. Rikkauksiesi ja vaihtotavaraisi runsaudella sinä teit rikkaiksi maan kuninkaat.'),
(1690117,58,26,27,34,'Nyt, kun jouduit haaksirikkoon, pois meriltä, vetten syvyyksiin, vaipuivat sinun mukanasi sinne vaihtotavarasi ja koko sinun suuri joukkosi.'''),
(1690118,58,26,27,35,'Sinun tähtesi tyrmistyvät kaikki saarten asukkaat, ja heidän kuninkaansa ovat kauhun vallassa, vavistus kasvoillansa.'),
(1690119,58,26,27,36,'Sinulle viheltävät kauppatutut kansojen joukossa. Kauhuksi olet sinä tullut, eikä sinua enää ole, hamaan ikiaikoihin asti."'),
(1690120,58,26,28,1,'Ja minulle tuli tämä Herran sana:'),
(1690121,58,26,28,2,'"Ihmislapsi, sano Tyyron ruhtinaalle: Näin sanoo Herra, Herra: Koska sinun sydämesi on ylpistynyt ja sinä sanot: ''Minä olen jumala, jumalain istuimella minä istun merten sydämessä'', ja olet kuitenkin ihminen, et jumala, vaikka omasta mielestäsi olet jumalan vertainen -'),
(1690122,58,26,28,3,'ja katso, viisaampi sinä oletkin kuin Daniel, ei mikään salaisuus ole sinulta pimitetty;'),
(1690123,58,26,28,4,'viisaudessasi ja ymmärtäväisyydessäsi olet hankkinut itsellesi rikkautta, hankkinut kultaa ja hopeata aarreaittoihisi,'),
(1690124,58,26,28,5,'ja suuressa viisaudessasi olet kaupankäynnillä kartuttanut rikkautesi, ja niin sinun sydämesi on ylpistynyt rikkaudestasi -'),
(1690125,58,26,28,6,'sentähden, näin sanoo Herra, Herra: Koska omasta mielestäsi olet jumalan vertainen,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690126,58,26,28,7,'sentähden, katso, minä tuon sinun kimppuusi muukalaiset, julmimmat pakanoista; he paljastavat miekkansa sinun viisautesi kauneutta vastaan ja häpäisevät sinun ihanuutesi.'),
(1690127,58,26,28,8,'He syöksevät sinut alas kuoppaan, ja sinä kuolet, niinkuin kaadetut kuolevat, merten sydämessä.'),
(1690128,58,26,28,9,'Vieläköhän sanot surmaajasi edessä: ''Minä olen jumala'', kun kuitenkin olet ihminen, et jumala, kaatajaisi käsissä?'),
(1690129,58,26,28,10,'Niinkuin kuolevat ympärileikkaamattomat, niin sinä kuolet muukalaisten käden kautta. Sillä minä olen puhunut, sanoo Herra, Herra."'),
(1690130,58,26,28,11,'Ja minulle tuli tämä Herran sana:'),
(1690131,58,26,28,12,'"Ihmislapsi, viritä itkuvirsi Tyyron kuninkaasta ja sano hänelle: Näin sanoo Herra, Herra: Sinä olet sopusuhtaisuuden sinetti, täynnä viisautta, täydellinen kauneudessa.'),
(1690132,58,26,28,13,'Eedenissä, Jumalan puutarhassa, sinä olit. Peitteenäsi olivat kaikkinaiset kalliit kivet; karneolia, topaasia ja jaspista, krysoliittia, onyksia ja berylliä, safiiria, rubiinia ja smaragdia sekä kultaa olivat upotus- ja syvennystyöt sinussa, valmistetut sinä päivänä, jona sinut luotiin.'),
(1690133,58,26,28,14,'Sinä olit kerubi, laajalti suojaavainen, ja minä asetin sinut pyhälle vuorelle; sinä olit jumal''olento ja käyskentelit säihkyväin kivien keskellä.'),
(1690134,58,26,28,15,'Nuhteeton sinä olit vaellukseltasi siitä päivästä, jona sinut luotiin, siihen saakka, kunnes sinussa löydettiin vääryys.'),
(1690135,58,26,28,16,'Suuressa kaupankäynnissäsi tuli sydämesi täyteen väkivaltaa, ja sinä teit syntiä. Niin minä karkoitin sinut häväistynä Jumalan vuorelta ja hävitin sinut, suojaava kerubi, pois säihkyväin kivien keskeltä.'),
(1690136,58,26,28,17,'Sinun sydämesi ylpistyi sinun kauneudestasi, ihanuutesi tähden sinä kadotit viisautesi. Minä viskasin sinut maahan, annoin sinut alttiiksi kuninkaille, heidän silmänherkukseen.'),
(1690137,58,26,28,18,'Paljoilla synneilläsi, tekemällä vääryyttä kaupoissasi, sinä olet häväissyt pyhäkkösi. Niin minä annoin sinun keskeltäsi puhjeta tulen; se kulutti sinut. Ja minä panin sinut tuhaksi maahan kaikkien silmäin edessä, jotka sinut näkivät.'),
(1690138,58,26,28,19,'Kaikki tuttavasi kansojen seassa ovat tyrmistyneet sinun tähtesi. Kauhuksi olet sinä tullut, eikä sinua enää ole, hamaan ikiaikoihin asti."'),
(1690139,58,26,28,20,'Ja minulle tuli tämä Herran sana:'),
(1690140,58,26,28,21,'"Ihmislapsi, käännä kasvosi Siidonia kohti ja ennusta sitä vastaan'),
(1690141,58,26,28,22,'ja sano: Näin sanoo Herra, Herra: Katso, minä käyn sinun kimppuusi, Siidon, ja näytän kunniani sinun keskuudessasi. Ja he tulevat tietämään, että minä olen Herra, kun minä siinä panen toimeen tuomiot ja näytän siinä pyhyyteni.'),
(1690142,58,26,28,23,'Minä lähetän sinne ruton ja verta sen kaduille, ja kaatuneita on viruva sen keskellä, kaatuneita miekkaan, joka käy sen kimppuun joka taholta. Ja he tulevat tietämään, että minä olen Herra.'),
(1690143,58,26,28,24,'Sitten ei Israelin heimolle enää ole pistävänä orjantappurana eikä vaivaavana ohdakkeena yksikään sen naapureista, jotka ovat heitä halveksineet. Ja he tulevat tietämään, että minä olen Herra, Herra.'),
(1690144,58,26,28,25,'Näin sanoo Herra, Herra: Kun minä kokoan Israelin heimon kansoista, joitten sekaan he ovat hajotetut, silloin minä näytän pyhyyteni heissä pakanakansain silmien edessä, ja he saavat asua maassansa, jonka minä annoin palvelijalleni Jaakobille.'),
(1690145,58,26,28,26,'He asuvat siinä turvallisesti ja rakentavat taloja ja istuttavat viinitarhoja. Turvallisesti he asuvat, kun minä panen toimeen tuomiot kaikille heidän naapureillensa, jotka ovat heitä halveksineet. Ja he tulevat tietämään, että minä olen Herra, heidän Jumalansa."'),
(1690146,58,26,29,1,'Kymmenentenä vuotena, kymmenennessä kuussa, kuukauden kahdentenatoista päivänä tuli minulle tämä Herran sana:'),
(1690147,58,26,29,2,'"Ihmislapsi, käännä kasvosi faraota, Egyptin kuningasta, kohti ja ennusta häntä ja koko Egyptiä vastaan.'),
(1690148,58,26,29,3,'Puhu ja sano: Näin sanoo Herra, Herra: Katso, minä käyn sinun kimppuusi, farao, Egyptin kuningas - suuri krokodiili, joka makaat virtojesi keskellä, joka sanot: ''Niilivirtani on minun, ja minä olen sen itselleni tehnyt''.'),
(1690149,58,26,29,4,'Minä panen koukut sinun leukoihisi, tartutan virtojesi kalat sinun suomuihisi ja nostan sinut ylös virtojesi keskeltä sekä kaikki virtojesi kalat, jotka ovat suomuihisi tarttuneet.'),
(1690150,58,26,29,5,'Minä viskaan erämaahan sinut ja kaikki virtojesi kalat. Sinä putoat kedolle, ei sinua korjata, ei koota. Metsän pedoille ja taivaan linnuille minä annan sinut ruuaksi.'),
(1690151,58,26,29,6,'Ja kaikki Egyptin asukkaat tulevat tietämään, että minä olen Herra. Sillä he ovat ruokosauva Israelin heimolle:'),
(1690152,58,26,29,7,'kun he kädellä tarttuvat sinuun, niin sinä säryt ja lävistät heiltä olkapäät kaikki; ja kun he nojaavat sinuun, niin sinä murrut ja jäykistät heiltä lanteet kaikki.'),
(1690153,58,26,29,8,'Sentähden, näin sanoo Herra, Herra: Katso, minä tuon sinun kimppuusi miekan ja hävitän sinusta ihmiset ja eläimet,'),
(1690154,58,26,29,9,'ja Egyptin maa tulee autioksi ja raunioksi. Ja he tulevat tietämään, että minä olen Herra. Sillä hän on sanonut: ''Niilivirta on minun, ja minä olen sen tehnyt''.'),
(1690155,58,26,29,10,'Sentähden, katso, minä käyn sinun ja sinun virtojesi kimppuun ja teen Egyptin maan raunioiksi, kuivaksi ja autioksi Migdolista Seveneen ja hamaan Etiopian rajaan saakka.'),
(1690156,58,26,29,11,'Ei käy siellä ihmisjalka, ei käy siellä eläimen jalka, eikä asuta siellä neljäänkymmeneen vuoteen.'),
(1690157,58,26,29,12,'Autioksi minä teen Egyptin maan autioiksi tehtyjen maitten joukossa, ja sen kaupungit tulevat olemaan autioina raunioiksi pantujen kaupunkien joukossa neljäkymmentä vuotta, ja egyptiläiset minä hajotan kansojen sekaan ja sirotan heidät muihin maihin.'),
(1690158,58,26,29,13,'Sillä näin sanoo Herra, Herra: Neljänkymmenen vuoden kuluttua minä kokoan egyptiläiset kansoista, joiden sekaan he olivat hajotetut,'),
(1690159,58,26,29,14,'käännän Egyptin kohtalon ja tuon heidät takaisin Patroksen maahan, synnyinmaahansa. Siellä he tulevat olemaan vähäpätöisenä valtakuntana.'),
(1690160,58,26,29,15,'He tulevat olemaan vähäpätöisin valtakunnista, eivätkä enää kohoa kansakuntien ylitse. Minä vähennän heidät niin, etteivät he enää kansoja vallitse.'),
(1690161,58,26,29,16,'Eivätkä he enää kelpaa turvaksi Israelin heimolle: he saattavat muistoon Israelin syntivelan, jos se kääntyy heitä seuraamaan. Ja he tulevat tietämään, että minä olen Herra, Herra."'),
(1690162,58,26,29,17,'Kahdentenakymmenentenä seitsemäntenä vuotena, ensimmäisessä kuussa, kuukauden ensimmäisenä päivänä tuli minulle tämä Herran sana:'),
(1690163,58,26,29,18,'"Ihmislapsi, Baabelin kuningas Nebukadressar on teettänyt sotajoukoillansa raskasta työtä Tyyroa vastaan: kaikki päät ovat käyneet kaljuiksi ja kaikki olkapäät lyöpyneet; mutta palkkaa ei Tyyrosta ole tullut hänelle eikä hänen sotajoukoilleen työstä, jota ovat tehneet sitä vastaan.'),
(1690164,58,26,29,19,'Sentähden, näin sanoo Herra, Herra: Katso, minä annan Baabelin kuninkaalle Nebukadressarille Egyptin maan. Hän vie sen tavaran paljouden, saa sen saaliit, ryöstää sen ryöstökset: se on oleva hänen sotajoukkojensa palkka.'),
(1690165,58,26,29,20,'Palkaksi, jonka toivossa hän on työtä tehnyt, minä annan hänelle Egyptin maan; sillä minun hyväkseni he ovat sitä tehneet, sanoo Herra, Herra.'),
(1690166,58,26,29,21,'Sinä päivänä minä annan puhjeta Israelin heimolle sarven, ja sinulle minä annan voiman avata suusi heidän keskellänsä. Ja he tulevat tietämään, että minä olen Herra."'),
(1690167,58,26,30,1,'Ja minulle tuli tämä Herran sana:'),
(1690168,58,26,30,2,'"Ihmislapsi, ennusta ja sano: Näin sanoo Herra, Herra: Valittakaa: ''Voi sitä päivää!'''),
(1690169,58,26,30,3,'Sillä lähellä on päivä, lähellä Herran päivä; se on pilvinen päivä, pakanakansojen aika.'),
(1690170,58,26,30,4,'Miekka yllättää Egyptin, ja Etiopialla on tuska, kun surmattuja kaatuu Egyptissä, kun siltä otetaan pois tavarain paljous ja revitään perustukset.'),
(1690171,58,26,30,5,'Etiopia, Puut ja Luud, kaikki sekakansa, Kuub ja liittoutuneen maan miehet kaatuvat heidän kanssansa miekkaan.'),
(1690172,58,26,30,6,'Näin sanoo Herra: Egyptin tuet kaatuvat, ja sen ylpeä uhma alenee. Migdolista Seveneen asti he siellä kaatuvat miekkaan, sanoo Herra, Herra.'),
(1690173,58,26,30,7,'Autioiksi he joutuvat autioiksi tehtyjen maitten joukossa, ja heidän kaupunkinsa tulevat olemaan raunioiksi pantujen kaupunkien joukossa.'),
(1690174,58,26,30,8,'Ja he tulevat tietämään, että minä olen Herra, kun minä sytytän Egyptin tuleen ja kaikki sen auttajat murtuvat.'),
(1690175,58,26,30,9,'Sinä päivänä lähtee minun tyköäni laivoilla lähettiläitä peljästyttämään levossa elävää Etiopiaa, ja heille tulee tuska niinkuin Egyptin päivänä; sillä katso, se tulee.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690176,58,26,30,10,'Näin sanoo Herra, Herra: Minä teen lopun Egyptin meluavista joukoista Baabelin kuninkaan Nebukadressarin käden kautta.'),
(1690177,58,26,30,11,'Hän ja hänen väkensä hänen kanssaan, julmimmat pakanoista, tuodaan hävittämään maata, ja he paljastavat miekkansa Egyptiä vastaan ja täyttävät maan surmatuilla.'),
(1690178,58,26,30,12,'Minä panen virrat kuiville ja myyn maan pahojen käsiin ja teen autioksi maan ja kaiken, mitä siinä on, muukalaisten käden kautta. Minä, Herra, olen puhunut.'),
(1690179,58,26,30,13,'Näin sanoo Herra, Herra: Minä tuhoan kivijumalat ja lopetan epäjumalat Noofista ja ruhtinaat Egyptistä: niitä ei ole enää oleva; ja minä saatan Egyptin maan pelon valtaan.'),
(1690180,58,26,30,14,'Minä teen Patroksen autioksi, sytytän Sooanin tuleen ja panen toimeen tuomiot Noossa.'),
(1690181,58,26,30,15,'Minä vuodatan kiivauteni Siiniin, Egyptin linnoitukseen, hävitän Noon meluavat joukot'),
(1690182,58,26,30,16,'ja sytytän Egyptin tuleen. Siin kierii tuskassa, Noo valloitetaan, ja Noof - ahdistajia selvällä päivällä!'),
(1690183,58,26,30,17,'Aavenin ja Piibesetin nuorukaiset kaatuvat miekkaan, ja ne itse menevät vankeuteen.'),
(1690184,58,26,30,18,'Tehafneheessa päivä pimenee, kun minä siellä särjen Egyptin ikeen, ja siinä saa lopun sen ylpeä uhma. Sen itsensä peittää pilvi, ja sen tyttäret menevät vankeuteen.'),
(1690185,58,26,30,19,'Niin minä panen tuomiot toimeen Egyptissä, ja he tulevat tietämään, että minä olen Herra."'),
(1690186,58,26,30,20,'Yhdentenätoista vuotena, ensimmäisessä kuussa, kuukauden seitsemäntenä päivänä tuli minulle tämä Herran sana:'),
(1690187,58,26,30,21,'"Ihmislapsi, minä olen murskannut faraon, Egyptin kuninkaan, käsivarren, ja katso, sitä ei sidota, ei parannella, ei panna kääreeseen, että se sidottuna vahvistuisi tarttuaksensa miekkaan.'),
(1690188,58,26,30,22,'Sentähden, näin sanoo Herra, Herra: Katso, minä käyn faraon, Egyptin kuninkaan, kimppuun ja murskaan häneltä käsivarret, sekä voimakkaan että murskatun käden, ja pudotan miekan hänen kädestänsä.'),
(1690189,58,26,30,23,'Minä hajotan egyptiläiset kansojen sekaan ja sirotan heidät muihin maihin.'),
(1690190,58,26,30,24,'Baabelin kuninkaan käsivarret minä vahvistan ja annan miekkani hänen käteensä; mutta faraolta minä murskaan käsivarret, ja hän voihkii hänen edessänsä, niinkuin kaadettu voihkii.'),
(1690191,58,26,30,25,'Niin, minä vahvistan Baabelin kuninkaan käsivarret, mutta faraon käsivarret vaipuvat alas. Ja he tulevat tietämään, että minä olen Herra, kun minä annan miekkani Baabelin kuninkaan käteen, että hän ojentaa sen Egyptin maata vastaan.'),
(1690192,58,26,30,26,'Ja minä hajotan egyptiläiset kansojen sekaan ja sirotan heidät muihin maihin. Ja he tulevat tietämään, että minä olen Herra."'),
(1690193,58,26,31,1,'Yhdentenätoista vuotena, kolmannessa kuussa, kuukauden ensimmäisenä päivänä tuli minulle tämä Herran sana:'),
(1690194,58,26,31,2,'"Ihmislapsi, sano faraolle, Egyptin kuninkaalle, ja hänen meluaville joukoillensa: Kenen kaltainen sinä olet suuruudessasi?'),
(1690195,58,26,31,3,'Katso, Assur oli setri Libanonilla, kaunislehväinen, taajavarjoinen, korkeakasvuinen, ja sen latva oli tiheän lehvistön keskellä.'),
(1690196,58,26,31,4,'Vedet olivat sen suureksi kasvattaneet, korkeaksi oli sen saanut syvyys, joka virtoinensa kiersi sen istutusmaata ja lähetti ojiansa kaikille metsän puille.'),
(1690197,58,26,31,5,'Sentähden siitä tuli korkeakasvuisin kaikista metsän puista, se sai haaroja paljon, ja oksat, joita se levitti, venyivät pitkiksi runsaista vesistä.'),
(1690198,58,26,31,6,'Sen lehvillä pesivät kaikki taivaan linnut, sen oksien alla synnyttivät kaikki metsän eläimet, ja sen varjossa asuivat kaikki suuret kansat.'),
(1690199,58,26,31,7,'Kaunis se oli suuruudessaan, oksiensa pituudessa, sillä sen juuri oli runsasten vetten ääressä.'),
(1690200,58,26,31,8,'Eivät olleet setrit sen vertaiset Jumalan puutarhassa, eivät kypressit sen oksien veroiset, eivät plataanit niinkuin sen haarat. Ei yksikään puu Jumalan puutarhassa ollut sen veroinen kauneudessa.'),
(1690201,58,26,31,9,'Minä tein sen niin kauniiksi oksarunsaudessaan, että kaikki Eedenin puut Jumalan puutarhassa sitä kadehtivat.'),
(1690202,58,26,31,10,'Sentähden, näin sanoo Herra, Herra: Koska se tuli korkeakasvuiseksi ja sen latva oli tiheän lehvistön keskellä ja sen sydän ylpistyi sen korkeudesta,'),
(1690203,58,26,31,11,'annan minä sen pakanoista mahtavimman käsiin, ja hän tekee sille, minkä tekee; jumalattomuutensa tähden minä sen olen karkoittanut.'),
(1690204,58,26,31,12,'Ja sen hakkasivat muukalaiset, julmimmat pakanoista, ja heittivät sen maahan. Vuorille ja kaikkiin laaksoihin kaatuivat sen haarat, ja sen oksat murskaantuivat kaikkiin maan puronotkoihin. Kaikki maan kansat laskeutuivat alas sen varjosta ja jättivät sen.'),
(1690205,58,26,31,13,'Sen kaatuneella rungolla asuvat kaikki taivaan linnut, ja sen oksien ääressä oleskelevat kaikki metsän eläimet -'),
(1690206,58,26,31,14,'ettei yksikään puu vetten vierellä kasvaisi niin korkeaksi eikä ojentaisi latvaansa pilvien väliin ja etteivät mahtavimmatkaan niistä, ei mitkään, jotka vettä juovat, olisi pysyväisiä korkeudessaan, sillä ne ovat kaikki annetut alttiiksi kuolemalle, menemään maan syvyyteen, hautaanvaipuneitten pariin yhdessä ihmislasten kanssa.'),
(1690207,58,26,31,15,'Näin sanoo Herra, Herra: Sinä päivänä, jona hän astui alas tuonelaan, minä verhosin syvyyden suruun hänen tähtensä, pidätin virrat, niin että paljot vedet pysähtyivät juoksussaan, ja puin Libanonin hänen tähtensä mustiin, ja kaikki metsän puut nääntyivät hänen tähtensä.'),
(1690208,58,26,31,16,'Hänen kaatumisensa ryskeestä minä panin kansakunnat vapisemaan, kun minä syöksin hänet alas tuonelaan, hautaanvaipuneitten pariin. Mutta lohdutetuiksi tulivat maan syvyydessä kaikki Eedenin puut, Libanonin valiot ja parhaat, kaikki, jotka vettä juovat.'),
(1690209,58,26,31,17,'Myöskin ne olivat hänen kanssansa astuneet alas tuonelaan, miekalla kaadettujen pariin; samoin hänen auttajansa, ne, jotka istuivat hänen varjossaan kansojen joukossa.'),
(1690210,58,26,31,18,'Oliko yhtään Eedenin puista sinun vertaistasi kunniassa ja suuruudessa? Mutta sinut on Eedenin puitten kanssa syösty alas maan syvyyteen; ympärileikkaamattomien keskellä sinä makaat miekallakaadettujen parissa. Näin käy faraon ja koko hänen meluavan joukkonsa, sanoo Herra, Herra."'),
(1690211,58,26,32,1,'Kahdentenatoista vuotena, kahdennessatoista kuussa, kuukauden ensimmäisenä päivänä tuli minulle tämä Herran sana:'),
(1690212,58,26,32,2,'"Ihmislapsi, viritä itkuvirsi faraosta, Egyptin kuninkaasta, ja sano hänelle: Nuori leijona kansojen seassa, sinä olet hukassa! Sinä olit kuin krokodiili virroissa: sinä kuohutit virtojasi, sotkit vettä jaloillasi ja hämmensit sen virtoja.'),
(1690213,58,26,32,3,'Näin sanoo Herra, Herra: Minä levitytän verkkoni sinun ylitsesi monien kansojen suurella joukolla, ja ne vetävät sinut ylös minun pyydykselläni.'),
(1690214,58,26,32,4,'Minä viskaan sinut maalle, heitän sinut kedolle, panen asustamaan sinun ylläsi kaikki taivaan linnut ja syötän sinusta kylläisiksi kaiken maan eläimet.'),
(1690215,58,26,32,5,'Minä jätän sinun lihasi vuorten hyviksi ja täytän raatokasallasi laaksot,'),
(1690216,58,26,32,6,'juotan maan sillä, mikä sinusta valuu, sinun verelläsi aina vuorille asti, ja purojen uomat tulevat sinusta täyteen.'),
(1690217,58,26,32,7,'Minä peitän taivaan, kun sinut sammutan, ja puen mustiin sen tähdet; auringon minä peitän pilviin, eikä kuu anna valonsa loistaa.'),
(1690218,58,26,32,8,'Kaikki taivaan loistavat valot minä puen mustiin sinun tähtesi ja peitän sinun maasi pimeyteen, sanoo Herra, Herra.'),
(1690219,58,26,32,9,'Minä murehdutan monien kansain sydämet, kun saatan tiedoksi sinun perikatosi kansakunnille, maihin, joita sinä et tuntenut;'),
(1690220,58,26,32,10,'ja minä tyrmistytän sinun tähtesi monet kansat, ja heidän kuninkaansa kovin värisevät sinun tähtesi, kun minä heilutan miekkaani heidän nähtensä, ja he vapisevat joka hetki kukin omaa henkeänsä sinun kukistumisesi päivänä.'),
(1690221,58,26,32,11,'Sillä näin sanoo Herra, Herra: Baabelin kuninkaan miekka yllättää sinut.'),
(1690222,58,26,32,12,'Minä kaadan sinun meluisan joukkosi sankarien miekoilla; ne ovat julmimpia pakanoista kaikki tyynni. He kukistavat Egyptin komeuden, kaikki sen meluisa joukko tuhotaan.'),
(1690223,58,26,32,13,'Ja minä hävitän siitä kaiken karjan runsasten vetten ääriltä. Eikä niitä enää sotke ihmisen jalka, eivätkä sotke niitä karjan sorkat.'),
(1690224,58,26,32,14,'Silloin minä annan sen vetten laskeutua kirkkaiksi, ja minä panen sen virrat juoksemaan kuin öljyn, sanoo Herra, Herra.'),
(1690225,58,26,32,15,'Kun minä teen Egyptin maan autioksi, kun maa tulee autioksi kaikesta, mitä siinä on, ja kun minä surmaan kaikki sen asukkaat, tulevat he tietämään, että minä olen Herra.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690226,58,26,32,16,'Itkuvirsi tämä on, ja sitä kyllä viritetään. Pakanakansain tyttäret sitä virittävät - virittävät sitä Egyptistä ja kaikesta sen meluisasta joukosta, sanoo Herra, Herra."'),
(1690227,58,26,32,17,'Kahdentenatoista vuotena, kuukauden viidentenätoista päivänä tuli minulle tämä Herran sana:'),
(1690228,58,26,32,18,'"Ihmislapsi, veisaa kuolinvalitus Egyptin meluisasta joukosta, saata se ja mahtavain pakanakansojen tyttäret alas maan syvyyksiin, hautaanvaipuneitten pariin.'),
(1690229,58,26,32,19,'Oletko vielä kaikkia muita ihanampi? Astu alas ja anna laittaa makuusijasi ympärileikkaamattomien pariin.'),
(1690230,58,26,32,20,'He kaatuvat miekallasurmattujen joukkoon. Miekka on jo annettu! Temmatkaa pois Egypti kaikkine meluisine joukkoineen.'),
(1690231,58,26,32,21,'Mahtavimmat sankareista puhuvat tuonelan keskeltä sille ynnä sen auttajille: ''Alas ovat astuneet, siellä makaavat ympärileikkaamattomat, miekalla surmatut''.'),
(1690232,58,26,32,22,'Siellä on Assur kaikkine joukkoinensa. Niitten haudat ovat hänen ympärillänsä. Kaikki tyynni ovat surmattuja, miekkaan kaatuneita.'),
(1690233,58,26,32,23,'Hänen hautansa ovat pohjimmaisessa kuopassa, ja hänen joukkonsa on hänen hautansa ympärillä; ne ovat kaikki tyynni surmattuja, miekkaan kaatuneita, nuo, jotka levittivät kauhua elävien maassa.'),
(1690234,58,26,32,24,'Siellä on Eelam, ja koko hänen meluisa joukkonsa on hänen hautansa ympärillä; kaikki tyynni surmattuja, miekkaan kaatuneita, jotka ympärileikkaamattomina astuivat alas maan syvyyksiin, nuo, jotka levittivät kauhuansa elävien maassa, mutta saavat kantaa häpeänsä hautaanvaipuneitten parissa.'),
(1690235,58,26,32,25,'Surmattujen keskellä on makuusija annettu hänelle ynnä kaikelle hänen meluisalle joukolleen. Niitten haudat ovat hänen ympärillänsä. Kaikki tyynni ne ovat ympärileikkaamattomia, miekalla surmattuja, sillä he olivat kauhuna elävien maassa, mutta saavat kantaa häpeänsä hautaanvaipuneitten parissa. Surmattujen keskelle on hänet pantu.'),
(1690236,58,26,32,26,'Siellä on Mesek-Tuubal kaikkine meluisine joukkoineen. Niitten haudat ovat hänen ympärillänsä; ne ovat kaikki tyynni ympärileikkaamattomia, miekalla surmattuja, sillä ne levittivät kauhuansa elävien maassa.'),
(1690237,58,26,32,27,'He eivät makaa sankarien parissa, jotka ovat kaatuneet ympärileikkaamattomien joukosta, jotka ovat astuneet alas tuonelaan sota-aseinensa, joitten pään alle on pantu heidän miekkansa ja joitten luiden yllä on heidän syntivelkansa, sillä sankarien kauhu oli elävien maassa.'),
(1690238,58,26,32,28,'Sinutkin muserretaan ympärileikkaamattomien joukossa, ja sinä saat maata miekallasurmattujen parissa.'),
(1690239,58,26,32,29,'Siellä on Edom, sen kuninkaat ja kaikki sen ruhtinaat, jotka sankaruudessaan pantiin miekallasurmattujen pariin. He makaavat ympärileikkaamattomien ja hautaanvaipuneitten parissa.'),
(1690240,58,26,32,30,'Siellä ovat kaikki pohjoisen maan ruhtinaat ja kaikki siidonilaiset, jotka ovat astuneet surmattujen pariin kauhistavaisuudessaan, ovat tulleet häpeään sankaruudessaan ja makaavat ympärileikkaamattomina miekallasurmattujen parissa ja saavat kantaa häpeänsä hautaanvaipuneitten parissa. -'),
(1690241,58,26,32,31,'Ne on farao näkevä ja tuleva lohdutetuksi kaikesta meluisasta joukostansa. Miekalla on surmattu farao kaikkine sotaväkineen, sanoo Herra, Herra.'),
(1690242,58,26,32,32,'Sillä minä levitin hänen kauhuansa elävien maassa, mutta faraolle ynnä kaikelle hänen meluisalle joukolleen laitetaan makuusija ympärileikkaamattomien sekaan, miekallasurmattujen pariin, sanoo Herra, Herra."'),
(1690243,58,26,33,1,'Minulle tuli tämä Herran sana:'),
(1690244,58,26,33,2,'"Ihmislapsi, puhu kansasi lapsille ja sano heille: Jos minä annan miekan tulla maan kimppuun ja maan kansa on ottanut yhden miehen joukostansa ja asettanut hänet vartijakseen'),
(1690245,58,26,33,3,'ja jos hän näkee miekan tulevan maan kimppuun ja puhaltaa pasunaan ja varoittaa kansaa,'),
(1690246,58,26,33,4,'ja joku kuulee pasunan äänen, mutta ei ota varoituksesta vaaria, ja miekka tulee ja ottaa hänet pois, niin hänen verensä tulee hänen oman päänsä päälle:'),
(1690247,58,26,33,5,'hän kuuli pasunan äänen, mutta ei ottanut varoituksesta vaaria; hänen verensä tulee hänen päällensä. Jos olisi ottanut varoituksesta vaarin, olisi hän pelastanut sielunsa.'),
(1690248,58,26,33,6,'Jos taas vartija näkee miekan tulevan, mutta ei puhalla pasunaan eikä kansa saa varoitusta, ja miekka tulee ja ottaa pois jonkun sielun heistä, on hän otettu pois synnissänsä, mutta hänen verensä minä vaadin vartijan kädestä.'),
(1690249,58,26,33,7,'Ja sinä, ihmislapsi! Minä olen asettanut sinut Israelin heimolle vartijaksi. Kun kuulet sanan minun suustani, on sinun varoitettava heitä minun puolestani.'),
(1690250,58,26,33,8,'Jos minä sanon jumalattomalle: jumalaton, sinun on kuolemalla kuoltava, mutta sinä et puhu varoittaaksesi jumalatonta hänen tiestänsä, niin se jumalaton kuolee synnissänsä, mutta hänen verensä minä vaadin sinun kädestäsi.'),
(1690251,58,26,33,9,'Mutta jos sinä varoitat jumalatonta hänen tiestänsä, että hän kääntyisi siltä pois, eikä hän tieltänsä käänny, niin hän kuolee synnissänsä, mutta sinä olet sielusi pelastanut.'),
(1690252,58,26,33,10,'Ja sinä, ihmislapsi! Sano Israelin heimolle: Näin te sanotte: ''Niin, rikoksemme ja syntimme ovat meidän päällämme, ja me riudumme niiden tähden. Kuinka me voisimme pysyä elossa?'''),
(1690253,58,26,33,11,'Sano heille: Niin totta kuin minä elän, sanoo Herra, Herra, ei ole minulle mieleen jumalattoman kuolema, vaan se, että jumalaton kääntyy tieltänsä ja elää. Kääntykää, kääntykää pois pahoilta teiltänne; ja minkätähden te kuolisitte, Israelin heimo!'),
(1690254,58,26,33,12,'Ja sinä, ihmislapsi! Sano kansasi lapsille: Vanhurskasta ei pelasta hänen vanhurskautensa sinä päivänä, jona hän rikkoo, ja jumalaton pääsee suistumasta turmioon jumalattomuutensa tähden sinä päivänä, jona hän kääntyy pois jumalattomuudestaan, ja vanhurskas ei voi elää vanhurskautensa turvin sinä päivänä, jona hän syntiä tekee.'),
(1690255,58,26,33,13,'Jos minä sanon vanhurskaalle, että hän totisesti saa elää, mutta hän sitten luottaa vanhurskauteensa ja tekee vääryyttä, niin hänen vanhurskauttansa ei ensinkään muisteta, vaan hän kuolee vääryydessään, jota on tehnyt.'),
(1690256,58,26,33,14,'Ja jos minä sanon jumalattomalle, että hänen totisesti on kuoltava, mutta hän kääntyy pois synnistänsä ja tekee oikeuden ja vanhurskauden'),
(1690257,58,26,33,15,'- antaa takaisin, tuo jumalaton, pantin, korvaa riistämänsä ja vaeltaa elämän käskyjen mukaan, niin ettei vääryyttä tee - niin totisesti hän saa elää; ei hänen ole kuoltava.'),
(1690258,58,26,33,16,'Hänen syntejänsä, jotka hän on tehnyt, ei ensinkään muisteta: hän on tehnyt oikeuden ja vanhurskauden, hän totisesti saa elää.'),
(1690259,58,26,33,17,'Ja vielä sinun kansasi lapset sanovat: ''Herran tie ei ole oikea''. Juuri heidän omat tiensä eivät ole oikeat.'),
(1690260,58,26,33,18,'Jos vanhurskas kääntyy pois vanhurskaudestansa ja vääryyttä tekee, on hänen sentähden kuoltava.'),
(1690261,58,26,33,19,'Ja jos jumalaton kääntyy pois jumalattomuudestansa ja tekee oikeuden ja vanhurskauden, saa hän sentähden elää.'),
(1690262,58,26,33,20,'Ja vielä te sanotte: ''Herran tie ei ole oikea'': minä tuomitsen teidät, te Israelin heimo, itsekunkin hänen teittensä mukaan."'),
(1690263,58,26,33,21,'Kahdentenatoista meidän pakkosiirtolaisuutemme vuotena, kymmenennessä kuussa, kuukauden viidentenä päivänä tuli minun luokseni pakolainen Jerusalemista ja sanoi: "Kaupunki on valloitettu".'),
(1690264,58,26,33,22,'Herran käsi oli tullut minun päälleni jo illalla, ennen pakolaisen tuloa, ja hän avasi minun suuni ennen tämän tuloa aamulla. Niin avautui minun suuni, enkä minä enää ollut mykkänä.'),
(1690265,58,26,33,23,'Ja minulle tuli tämä Herran sana:'),
(1690266,58,26,33,24,'"Ihmislapsi, ne, jotka asuvat noilla raunioilla Israelin maassa, sanovat näin: ''Aabraham oli vain yksi, ja hän peri maan; meitä on paljon, meille on maa perinnöksi annettu''.'),
(1690267,58,26,33,25,'Sano sentähden heille: Näin sanoo Herra, Herra: Te syötte lihaa verinensä, luotte silmänne kivijumaliinne ja vuodatatte verta; ja tekö perisitte maan?'),
(1690268,58,26,33,26,'Te seisotte miekkanne varassa, harjoitatte kauhistuksia ja saastutatte toistenne vaimoja; ja tekö perisitte maan?'),
(1690269,58,26,33,27,'Näin on sinun heille sanottava: Näin sanoo Herra, Herra: Niin totta kuin minä elän, niin ne, jotka ovat raunioilla, kaatuvat miekkaan, ja ne, jotka ovat kedolla, minä annan petoeläimille syötäväksi, ja ne, jotka ovat vuorenhuipuilla ja luolissa, kuolevat ruttoon.'),
(1690270,58,26,33,28,'Ja minä teen maan autioksi ja hävitetyksi, ja heidän ylpeästä uhmastaan tulee loppu, ja Israelin vuoret joutuvat autioiksi, niin ettei siellä kenkään kulje.'),
(1690271,58,26,33,29,'Ja he tulevat tietämään, että minä olen Herra, kun minä teen maan autioksi ja hävitetyksi kaikkien kauhistusten tähden, joita he ovat harjoittaneet.'),
(1690272,58,26,33,30,'Ja sinä, ihmislapsi! Sinun kansasi lapset puhuvat sinusta seinänvierustoilla ja talojen ovilla ja sanovat keskenään, toinen toisellensa, näin: ''Lähtekää kuulemaan, millainen sana nyt on tullut Herralta''.'),
(1690273,58,26,33,31,'He tulevat sinun luoksesi joukoittain, istuvat edessäsi minun kansanani ja kuuntelevat sinun sanojasi, mutta he eivät tee niitten mukaan, sillä he osoittavat rakkautta suullansa, mutta heidän sydämensä kulkee väärän voiton perässä.'),
(1690274,58,26,33,32,'Ja katso, sinä olet heille kuin rakkauslaulu, kauniisti laulettu ja hyvin soitettu: he sanojasi kyllä kuuntelevat, mutta eivät tee niitten mukaan.'),
(1690275,58,26,33,33,'Mutta kun se toteutuu - ja katso, se toteutuu - silloin he tulevat tietämään, että heidän keskuudessansa on ollut profeetta."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690276,58,26,34,1,'Minulle tuli tämä Herran sana:'),
(1690277,58,26,34,2,'"Ihmislapsi, ennusta Israelin paimenia vastaan, ennusta ja sano heille - paimenille: Näin sanoo Herra, Herra: Voi Israelin paimenia, jotka ovat itseänsä kainneet! Eikö paimenten ole kaittava lampaita?'),
(1690278,58,26,34,3,'Te olette syöneet rasvat, pukeneet päällenne villat, teurastaneet lihavat; mutta ette ole kainneet laumaa,'),
(1690279,58,26,34,4,'ette ole vahvistaneet heikkoja, ette ole parantaneet sairaita, sitoneet haavoittuneita, tuoneet takaisin eksyneitä, etsineet kadonneita, vaan te olette vallinneet niitä tylysti ja väkivaltaisesti.'),
(1690280,58,26,34,5,'Ja niin ne ovat hajaantuneet paimenta vailla ja joutuneet kaikkien metsän petojen syötäviksi - hajaantuneet ne ovat.'),
(1690281,58,26,34,6,'Minun lampaani harhailevat kaikilla vuorilla ja kaikilla korkeilla kukkuloilla; pitkin koko maata ovat minun lampaani hajallaan, eikä kenkään niistä välitä eikä niitä etsi.'),
(1690282,58,26,34,7,'Sentähden, paimenet, kuulkaa Herran sana:'),
(1690283,58,26,34,8,'Niin totta kuin minä elän, sanoo Herra, Herra, totisesti, koska minun lampaani ovat ryöstettävinä ja koska minun lampaani ovat kaikkien metsän petojen syötävinä, kun paimenta ei ole ja kun minun paimeneni eivät välitä minun lampaistani, vaan minun paimeneni kaitsevat itseänsä, eivätkä kaitse minun lampaitani,'),
(1690284,58,26,34,9,'sentähden, paimenet, kuulkaa Herran sana:'),
(1690285,58,26,34,10,'Näin sanoo Herra, Herra: Katso, minä käyn paimenten kimppuun, vaadin lampaani heidän kädestänsä ja teen lopun heidän lammasten-kaitsennastaan, eivätkä paimenet saa enää kaita itseänsä. Minä pelastan lampaani heidän kidastansa, eivätkä ne sitten enää ole heidän syötävinänsä.'),
(1690286,58,26,34,11,'Sillä näin sanoo Herra, Herra: Katso, minä itse etsin lampaani ja pidän niistä huolen.'),
(1690287,58,26,34,12,'Niinkuin paimen pitää huolen laumastaan, kun hän on lampaittensa keskellä ja ne ovat hajallaan, niin minä pidän huolen lampaistani, ja minä pelastan ne joka paikasta, minne ne ovat hajaantuneet pilvisenä ja pimeänä päivänä.'),
(1690288,58,26,34,13,'Minä vien ne pois kansojen seasta ja kokoan ne muista maista, tuon ne omaan maahansa ja kaitsen niitä Israelin vuorilla, puronotkoissa ja kaikissa maan asuttavissa paikoissa.'),
(1690289,58,26,34,14,'Hyvillä ruokamailla minä niitä kaitsen, ja Israelin korkeilla vuorilla on niillä oleva laitumensa. Siellä ne saavat levätä hyvällä laitumella, ja lihava ruokamaa niillä on oleva Israelin vuorilla.'),
(1690290,58,26,34,15,'Minä itse kaitsen lampaani ja vien itse ne lepäämään, sanoo Herra, Herra.'),
(1690291,58,26,34,16,'Kadonneet minä tahdon etsiä, eksyneet tuoda takaisin, haavoittuneet sitoa, heikkoja vahvistaa; mutta lihavat ja väkevät minä hävitän. Minä kaitsen niitä niin, kuin oikein on.'),
(1690292,58,26,34,17,'Mutta te, minun lampaani! Näin sanoo Herra, Herra: Katso, minä tahdon tuomita lampaan ja lampaan, oinasten ja vuohipukkien välillä.'),
(1690293,58,26,34,18,'Eikö teille riitä, että olette hyvällä laitumella, kun vielä tallaatte jaloillanne loput laitumestanne, ja että saatte juoda kirkasta vettä, kun vielä hämmennätte jaloillanne loput?'),
(1690294,58,26,34,19,'Ja onko minun lampaitteni oltava laitumella siinä, mitä jalkanne ovat tallanneet, ja juotava sitä, mitä jalkanne ovat hämmentäneet?'),
(1690295,58,26,34,20,'Sentähden sanoo Herra, Herra niille näin: Katso, minä, minä tuomitsen lihavan lampaan ja laihan lampaan välillä.'),
(1690296,58,26,34,21,'Koska te olette kylki- ja niskavoimalla sysineet ja sarvillanne puskeneet kaikkia heikkoja, kunnes olette saaneet ne ajetuiksi ulos ja hajallensa,'),
(1690297,58,26,34,22,'niin minä tahdon vapauttaa lampaani, etteivät ne enää jää ryöstettäviksi; ja minä tahdon tuomita lampaan ja lampaan välillä.'),
(1690298,58,26,34,23,'Ja minä herätän heille yhden paimenen heitä kaitsemaan, palvelijani Daavidin; hän on kaitseva heitä ja oleva heidän paimenensa.'),
(1690299,58,26,34,24,'Ja minä, Herra, olen heidän Jumalansa, ja minun palvelijani Daavid on ruhtinas heidän keskellänsä. Minä, Herra, olen puhunut.'),
(1690300,58,26,34,25,'Ja minä teen heidän kanssansa rauhan liiton; minä lopetan maasta pahat eläimet, niin että he asuvat turvallisesti erämaassa ja nukkuvat metsiköissä;'),
(1690301,58,26,34,26,'ja minä teen siunatuiksi heidät ja kaiken, mitä minun kukkulani ympärillä on, ja vuodatan sateen ajallansa - ne ovat siunauksen sateita.'),
(1690302,58,26,34,27,'Ja kedon puut kantavat hedelmänsä, ja maa antaa satonsa, ja he saavat olla turvassa maassansa. Ja he tulevat tietämään, että minä olen Herra, kun minä särjen heidän ikeensä puut ja pelastan heidät heidän orjuuttajainsa käsistä.'),
(1690303,58,26,34,28,'Eivätkä he enää ole pakanain ryöstettävinä, eivätkä metsän pedot heitä syö, vaan he asuvat turvassa, kenenkään peloittelematta.'),
(1690304,58,26,34,29,'Ja minä annan nousta heille istutuksen, joka on oleva kunniaksi, niin ettei heidän tarvitse siinä maassa menehtyä nälkään eikä enää kärsiä pakanain pilkkaa.'),
(1690305,58,26,34,30,'Ja he tulevat tietämään, että minä, Herra, heidän Jumalansa, olen heidän kanssansa ja että he, Israelin heimo, ovat minun kansani, sanoo Herra, Herra.'),
(1690306,58,26,34,31,'Niin, te olette minun lampaani, minun laitumeni lampaat, te ihmiset; minä olen teidän Jumalanne, sanoo Herra, Herra."'),
(1690307,58,26,35,1,'Minulle tuli tämä Herran sana:'),
(1690308,58,26,35,2,'"Ihmislapsi, käännä kasvosi Seirin vuorta kohti ja ennusta sitä vastaan'),
(1690309,58,26,35,3,'ja sano sille: Näin sanoo Herra, Herra: Katso, minä käyn sinun kimppuusi, Seirin vuori, ojennan käteni sinua vastaan ja teen sinut autioksi ja hävitetyksi.'),
(1690310,58,26,35,4,'Sinun kaupunkisi minä teen raunioiksi ja sinä itse tulet autioksi. Ja sinä tulet tietämään, että minä olen Herra.'),
(1690311,58,26,35,5,'Koska sinä pidit ikuista vihaa ja annoit israelilaiset alttiiksi miekalle heidän onnettomuutensa aikana, aikana, jolloin syntivelka tuli loppumääräänsä,'),
(1690312,58,26,35,6,'sentähden, niin totta kuin minä elän, sanoo Herra, Herra, minä teen sinut verivirraksi, ja veri on sinua vainoava: totisesti, vereen saakka sinä olet vihannut, ja veri on sinua vainoava.'),
(1690313,58,26,35,7,'Minä teen Seirin vuoren tyhjäksi ja autioksi ja hävitän sieltä menijän ja tulijan.'),
(1690314,58,26,35,8,'Sen vuoret minä täytän sen surmatuilla. Miekalla surmattuja kaatuu sinun kukkuloillasi ja laaksoissasi ja kaikissa puronotkoissasi.'),
(1690315,58,26,35,9,'Minä teen sinut ikiautioksi, ja sinun kaupunkisi jäävät asumattomiksi. Ja te tulette tietämään, että minä olen Herra.'),
(1690316,58,26,35,10,'Koska sinä olet sanonut: ''Ne kaksi kansaa ja kaksi maata ovat minun, me otamme ne omiksemme'', vaikka siellä on Herra,'),
(1690317,58,26,35,11,'sentähden, niin totta kuin minä elän, sanoo Herra, Herra, minä teen sinun kiukkusi ja kiivautesi mukaan, teen sen, minkä sinä vihassasi olet heille tehnyt. Ja minä teen itseni heille tunnetuksi, kun niin tuomitsen sinut,'),
(1690318,58,26,35,12,'ja sinä tulet tietämään, että minä olen Herra. Minä olen kuullut kaikki sinun pilkkasi, jotka olet puhunut Israelin vuoria vastaan, kun olet sanonut: ''Ne ovat autioina, ne ovat annetut meidän syötäviksemme''.'),
(1690319,58,26,35,13,'Te suurentelitte minua vastaan suullanne, ja ylenpalttiset olivat teidän puheenne minua vastaan: minä olen ne kuullut.'),
(1690320,58,26,35,14,'Näin sanoo Herra, Herra: Iloksi kaikelle maalle minä teen sinut autioksi.'),
(1690321,58,26,35,15,'Niinkuin sinä iloitsit Israelin heimon perintöosasta, kun se tuli autioksi, niin teen minäkin sinulle: autioksi tulet sinä, Seirin vuori, samoin koko Edom kaikkinensa. Ja niin he tulevat tietämään, että minä olen Herra."'),
(1690322,58,26,36,1,'"Ja sinä, ihmislapsi, ennusta Israelin vuorista ja sano:'),
(1690323,58,26,36,2,'Israelin vuoret, kuulkaa Herran sana: Näin sanoo Herra, Herra: Koska vihollinen on sanonut teistä: ''Kas niin!'' ja: ''Ikuiset kukkulat ovat tulleet meille perinnöksi'','),
(1690324,58,26,36,3,'sentähden ennusta ja sano: Näin sanoo Herra, Herra: Koska - niin, koska teitä on hävitetty ja poljettu joka taholta, että joutuisitte muiden kansain omaisuudeksi, ja koska te olette joutuneet pahain kielten ja kansan panettelun alaisiksi,'),
(1690325,58,26,36,4,'sentähden, Israelin vuoret, kuulkaa Herran, Herran sana: Näin sanoo Herra, Herra vuorille ja kukkuloille, puronotkoille ja laaksoille, autioille raunioille ja hyljätyille kaupungeille, jotka ovat joutuneet saaliiksi ja pilkaksi muille kansoille, mitä ympärillä on.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690326,58,26,36,5,'Sentähden sanoo Herra, Herra näin: Totisesti, kiivauteni tulessa minä puhun muita kansoja vastaan ja koko Edomia vastaan, jotka ovat kaikesta sydämestään iloiten ja sielu täynnä ylenkatsetta ottaneet omakseen minun maani karkoittaaksensa siitä ihmiset ja ryöstääksensä sen.'),
(1690327,58,26,36,6,'Sentähden ennusta Israelin maasta ja sano vuorille ja kukkuloille, puronotkoille ja laaksoille: Näin sanoo Herra, Herra: Katso, kiivaudessani ja vihassani minä puhun, koska teidän täytyy kärsiä pakanakansain pilkkaa.'),
(1690328,58,26,36,7,'Sentähden, näin sanoo Herra, Herra: Minä kohotan käteni: totisesti saavat pakanakansat, jotka teidän ympärillänne ovat, itse kärsiä oman pilkkansa.'),
(1690329,58,26,36,8,'Mutta te, Israelin vuoret, teette lehvänne ja kannatte hedelmänne minun kansalleni Israelille, sillä he ovat aivan lähellä, ovat tulossa.'),
(1690330,58,26,36,9,'Sillä katso, minä tulen teidän tykönne ja käännyn teidän puoleenne, ja teidät viljellään ja teihin kylvetään.'),
(1690331,58,26,36,10,'Ja minä lisään teille ihmisiä runsaasti - kaiken Israelin heimon kokonansa - ja kaupungit asutetaan ja rauniot rakennetaan.'),
(1690332,58,26,36,11,'Ja minä lisään teille ihmisiä ja karjaa runsaasti, ja ne lisääntyvät ja ovat hedelmälliset. Minä teen teidät asutuiksi, niinkuin olitte muinaisina päivinänne, ja teen hyvää vielä enemmän kuin alkuaikoinanne. Ja te tulette tietämään, että minä olen Herra.'),
(1690333,58,26,36,12,'Minä annan teidän kukkuloillanne kulkea ihmisten, kansani Israelin; ja he ottavat sinut omaksensa, ja sinä tulet heille perintöosaksi, ja sinä et enää tästälähin riistä heidän lapsiansa.'),
(1690334,58,26,36,13,'Näin sanoo Herra, Herra: Koska teille on sanottu: ''Sinä olet ihmissyöjätär, oman kansasi lasten riistäjätär'','),
(1690335,58,26,36,14,'sentähden et sinä ole enää syövä ihmisiä etkä enää riistävä lapsia omalta kansaltasi, sanoo Herra, Herra.'),
(1690336,58,26,36,15,'Enkä minä enää anna sinun joutua kuulemaan pakanakansojen pilkkaa, eikä tarvitse sinun enää kärsiä kansojen herjauksia, et myöskään sinä enää omaa kansaasi kaada, sanoo Herra, Herra."'),
(1690337,58,26,36,16,'Ja minulle tuli tämä Herran sana:'),
(1690338,58,26,36,17,'"Ihmislapsi, kun Israelin heimo asui maassansa, he saastuttivat sen vaelluksellaan ja teoillaan. Niinkuin kuukautistilan saastaisuus oli minun edessäni heidän vaelluksensa.'),
(1690339,58,26,36,18,'Niin minä vuodatin kiivauteni heidän ylitsensä veren tähden, jota he olivat vuodattaneet maassa, ja heidän kivijumalainsa tähden, joilla he olivat sen saastuttaneet.'),
(1690340,58,26,36,19,'Ja minä hajotin heidät pakanakansojen sekaan, ja heidät siroteltiin muihin maihin. Vaelluksensa ja tekojensa mukaan minä heidät tuomitsin.'),
(1690341,58,26,36,20,'Niin he tulivat pakanakansain sekaan; minne tulivatkin, he häpäisivät minun pyhän nimeni, kun heistä sanottiin: ''Nämä ovat Herran kansa, mutta heidän on täytynyt lähteä pois hänen maastansa''.'),
(1690342,58,26,36,21,'Niin minun tuli sääli pyhää nimeäni, jonka Israelin heimo saastutti pakanakansain seassa, minne tulivatkin.'),
(1690343,58,26,36,22,'Sentähden sano Israelin heimolle: Näin sanoo Herra, Herra: En tee minä teidän tähtenne, Israelin heimo, sitä minkä teen, vaan oman pyhän nimeni tähden, jonka te olette häväisseet pakanakansain seassa, minne tulittekin.'),
(1690344,58,26,36,23,'Minä pyhitän suuren nimeni, joka on häväisty pakanakansain seassa, jonka te olette häväisseet heidän keskellänsä. Ja pakanakansat tulevat tietämään, että minä olen Herra, sanoo Herra, Herra, kun minä osoitan teissä pyhyyteni heidän silmäinsä edessä.'),
(1690345,58,26,36,24,'Minä otan teidät pois pakanakansoista ja kokoan teidät kaikista maista ja tuon teidät omaan maahanne.'),
(1690346,58,26,36,25,'Ja minä vihmon teidän päällenne puhdasta vettä, niin että te puhdistutte; kaikista saastaisuuksistanne ja kaikista kivijumalistanne minä teidät puhdistan.'),
(1690347,58,26,36,26,'Ja minä annan teille uuden sydämen, ja uuden hengen minä annan teidän sisimpäänne. Minä poistan teidän ruumiistanne kivisydämen ja annan teille lihasydämen.'),
(1690348,58,26,36,27,'Henkeni minä annan teidän sisimpäänne ja vaikutan sen, että te vaellatte minun käskyjeni mukaan, noudatatte minun oikeuksiani ja pidätte ne.'),
(1690349,58,26,36,28,'Niin te saatte asua maassa, jonka minä annoin teidän isillenne; ja te olette minun kansani, ja minä olen teidän Jumalanne.'),
(1690350,58,26,36,29,'Minä vapahdan teidät kaikista saastaisuuksistanne. Ja minä kutsun esiin viljan ja teen sen runsaaksi enkä anna teille nälänhätää.'),
(1690351,58,26,36,30,'Minä teen runsaaksi puitten hedelmän ja pellon sadon, niin ettette enää joudu kärsimään kansojen seassa herjausta nälän takia.'),
(1690352,58,26,36,31,'Niin te muistatte huonon vaelluksenne ja tekonne, jotka eivät olleet hyvät, ja teitä kyllästyttää oma itsenne rikostenne ja kauhistustenne tähden.'),
(1690353,58,26,36,32,'En minä teidän tähtenne sitä tee, sanoo Herra, Herra: se olkoon teille tiettävä. Hävetkää ja tuntekaa häpeätä vaelluksenne tähden, te Israelin heimo.'),
(1690354,58,26,36,33,'Näin sanoo Herra, Herra: Sinä päivänä, jona minä teidät puhdistan kaikista pahoista teoistanne, minä asutan kaupungit, ja rauniot rakennetaan jälleen,'),
(1690355,58,26,36,34,'ja autiomaa viljellään, sen sijaan että se on ollut autiona jokaisen ohitsekulkijan silmäin edessä.'),
(1690356,58,26,36,35,'Silloin sanotaan: ''Tästä maasta, joka oli autiona, on tullut kuin Eedenin puutarha; ja raunioina olleet, autiot ja maahan revityt kaupungit ovat varustettuja ja asuttuja''.'),
(1690357,58,26,36,36,'Niin tulevat pakanakansat, joita on jäljellä teidän ympärillänne, tietämään, että minä, Herra, rakennan jälleen alasrevityn ja istutan aution: minä, Herra, olen puhunut, ja minä teen sen.'),
(1690358,58,26,36,37,'Näin sanoo Herra, Herra: Vielä tätäkin annan Israelin heimon minulta anoa, että tekisin heille sen: minä lisään heille ihmisiä runsaasti kuin lammaslaumaa.'),
(1690359,58,26,36,38,'Niinkuin on pyhitettyjen uhrilammasten laumaa, niinkuin Jerusalemin lammaslaumaa sen juhlissa, niin tulevat raunioina olleet kaupungit täyteen ihmislaumaa. Ja niin he tulevat tietämään, että minä olen Herra."'),
(1690360,58,26,37,1,'Herran käsi tuli minun päälleni ja vei minut pois Herran hengessä ja laski minut keskelle laaksoa. Ja se oli täynnä luita.'),
(1690361,58,26,37,2,'Ja hän kuljetti minua ympäri niitten ohitse; ja katso, niitä oli hyvin paljon laakson kamaralla, ja katso, ne olivat hyvin kuivia.'),
(1690362,58,26,37,3,'Niin hän sanoi minulle: "Ihmislapsi, voivatkohan nämä luut tulla eläviksi?" Mutta minä sanoin: "Herra, Herra, sinä sen tiedät".'),
(1690363,58,26,37,4,'Niin hän sanoi minulle: "Ennusta näistä luista ja sano niille: Kuivat luut, kuulkaa Herran sana.'),
(1690364,58,26,37,5,'Näin sanoo Herra, Herra näille luille: Katso, minä annan tulla teihin hengen, ja te tulette eläviksi.'),
(1690365,58,26,37,6,'Minä panen teihin jänteet, kasvatan teihin lihan, vedän yllenne nahan ja annan teihin hengen, ja te tulette eläviksi. Ja te tulette tietämään, että minä olen Herra."'),
(1690366,58,26,37,7,'Minä ennustin, niinkuin minua oli käsketty. Ja kävi humahdus, kun minä ennustin; ja katso, kuului kolina, ja luut lähenivät toisiaan, luu luutansa.'),
(1690367,58,26,37,8,'Minä näin, ja katso: niihin tulivat jänteet ja kasvoi liha, ja päälle vetäytyi niihin nahka; mutta henkeä niissä ei ollut.'),
(1690368,58,26,37,9,'Niin hän sanoi minulle: "Ennusta hengestä, ennusta, ihmislapsi, ja sano hengelle: Näin sanoo Herra, Herra: Tule, henki, neljästä tuulesta ja puhalla näihin surmattuihin, että ne tulisivat eläviksi."'),
(1690369,58,26,37,10,'Minä ennustin, niinkuin hän oli minua käskenyt, ja niihin tuli henki, ja ne tulivat eläviksi ja nousivat ylös jaloillensa: ylenmäärin suuri joukko.'),
(1690370,58,26,37,11,'Ja hän sanoi minulle: "Ihmislapsi, nämä luut ovat koko Israelin heimo. Katso, he sanovat: ''Meidän luumme ovat kuivettuneet, toivomme on mennyttä, me olemme hukassa''.'),
(1690371,58,26,37,12,'Sentähden ennusta ja sano heille: Näin sanoo Herra, Herra: Katso, minä avaan teidän hautanne ja nostan teidät, minun kansani, ylös haudoistanne ja vien teidät Israelin maahan.'),
(1690372,58,26,37,13,'Ja siitä te tulette tietämään, että minä olen Herra, kun minä avaan teidän hautanne ja nostan teidät, minun kansani, ylös haudoistanne.'),
(1690373,58,26,37,14,'Ja minä annan teihin henkeni, niin että te tulette eläviksi, ja sijoitan teidät omaan maahanne. Ja te tulette tietämään, että minä olen Herra: minä olen puhunut, ja minä sen teen, sanoo Herra."'),
(1690374,58,26,37,15,'Ja minulle tuli tämä Herran sana:'),
(1690375,58,26,37,16,'"Sinä, ihmislapsi, ota puusauva ja kirjoita siihen: ''Juudalle ja häneen liittyneille israelilaisille''. Ota sitten toinen puusauva ja kirjoita siihen: ''Joosefille; Efraimin ja kaiken häneen liittyneen Israelin heimon sauva''.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690376,58,26,37,17,'Ja pane ne lähekkäin, pääksytysten, niin että ne tulevat yhdeksi sinun kädessäsi.'),
(1690377,58,26,37,18,'Kun sitten kansasi lapset sanovat sinulle näin: ''Etkö selitä meille, mitä sinä tällä tarkoitat?'''),
(1690378,58,26,37,19,'niin puhu heille: Näin sanoo Herra, Herra: Katso, minä otan Joosefin sauvan, joka on Efraimin kädessä, ja häneen liittyneet Israelin sukukunnat, ja minä asetan ne yhteen Juudan sauvan kanssa ja teen niistä yhden sauvan, niin että ne tulevat yhdeksi minun kädessäni.'),
(1690379,58,26,37,20,'Ja kun sauvat, joihin olet kirjoittanut, ovat sinun kädessäsi, heidän silmäinsä edessä,'),
(1690380,58,26,37,21,'niin puhu heille: Näin sanoo Herra, Herra: Katso, minä otan israelilaiset pois pakanakansojen keskuudesta, minne vain he ovat kulkeutuneet, kokoan heidät joka taholta ja tuon heidät omaan maahansa.'),
(1690381,58,26,37,22,'Minä teen heidät yhdeksi kansaksi siinä maassa, Israelin vuorilla, ja yksi kuningas on oleva kuninkaana heillä kaikilla. Eivätkä he enää ole kahtena kansana eivätkä enää jakaantuneina kahdeksi valtakunnaksi.'),
(1690382,58,26,37,23,'Eivät myöskään he enää saastuta itseänsä kivijumalillaan, iljetyksillään eivätkä millään rikkomuksillansa, vaan minä vapautan heidät kaikista asuinpaikoistaan, joissa ovat syntiä tehneet, ja puhdistan heidät. Ja he ovat minun kansani, ja minä olen heidän Jumalansa.'),
(1690383,58,26,37,24,'Minun palvelijani Daavid on oleva heidän kuninkaansa, ja heillä kaikilla on oleva yksi paimen. Ja he vaeltavat minun oikeuksieni mukaan ja noudattavat minun käskyjäni ja pitävät ne.'),
(1690384,58,26,37,25,'He saavat asua maassa, jonka minä annoin palvelijalleni Jaakobille ja jossa teidän isänne ovat asuneet. Siinä saavat asua he, heidän lapsensa ja lastensa lapset iankaikkisesti, ja minun palvelijani Daavid on oleva heidän ruhtinaansa iankaikkisesti.'),
(1690385,58,26,37,26,'Minä teen heidän kanssansa rauhan liiton - se on oleva iankaikkinen liitto heidän kanssansa - istutan ja runsaasti kartutan heidät ja asetan pyhäkköni olemaan heidän keskellänsä iankaikkisesti.'),
(1690386,58,26,37,27,'Minun asumukseni on oleva heidän yllänsä, ja minä olen heidän Jumalansa, ja he ovat minun kansani.'),
(1690387,58,26,37,28,'Ja pakanakansat tulevat tietämään, että minä olen Herra, joka pyhitän Israelin, kun minun pyhäkköni on heidän keskellänsä iankaikkisesti."'),
(1690388,58,26,38,1,'Minulle tuli tämä Herran sana:'),
(1690389,58,26,38,2,'"Ihmislapsi, käännä kasvosi kohti Googia Maagogin maassa, Roosin, Mesekin ja Tuubalin ruhtinasta, ja ennusta häntä vastaan'),
(1690390,58,26,38,3,'ja sano: Näin sanoo Herra, Herra: Katso, minä käyn sinun kimppuusi, Goog, sinä Roosin, Mesekin ja Tuubalin ruhtinas.'),
(1690391,58,26,38,4,'Minä kuljetan sinua, panen koukut sinun leukoihisi ja nostatan sotaan sinut ja kaiken sinun sotaväkesi: hevoset ja ratsumiehet, kaikki pulskasti puettuja, suuren joukon suurine ja pienine kilpineen, miekankantajia kaikki.'),
(1690392,58,26,38,5,'Persia, Etiopia ja Puut ovat heidän kanssansa, kilvet ja kypärit on heillä kaikilla.'),
(1690393,58,26,38,6,'Goomer ja kaikki sen sotalaumat, Toogarman heimo pohjan periltä ja kaikki sen sotalaumat - lukuisat kansat ovat sinun kanssasi.'),
(1690394,58,26,38,7,'Ole valmis, varustaudu, sinä ja kaikki joukkosi, jotka ovat kokoontuneet sinun luoksesi, ja ole sinä varalla heitä varten.'),
(1690395,58,26,38,8,'Pitkien aikojen perästä sinä saat määräyksen, vuotten lopulla sinun on karattava maahan, joka on tointunut miekan jäljiltä, koottu monien kansain seasta, - mentävä Israelin vuorille, jotka kauan aikaa olivat olleet rauniomaana; se on tuotu pois kansojen seasta, ja he asuvat turvallisina kaikki tyynni.'),
(1690396,58,26,38,9,'Sinä hyökkäät kuin rajuilma, tulet kuin pilvi, pettääksesi maan, sinä ja kaikki sotalaumasi ja lukuisat kansat, jotka ovat sinun kanssasi.'),
(1690397,58,26,38,10,'Näin sanoo Herra, Herra: Mutta sinä päivänä tulee mieleesi jotakin, ja sinä mietit pahan juonen'),
(1690398,58,26,38,11,'ja sanot: Minä hyökkään suojattomaan maahan, karkaan rauhallisten ihmisten kimppuun, jotka asuvat turvallisina - asuvat muuria vailla kaikki tyynni, ja joilla ei ole salpoja, ei ovia.'),
(1690399,58,26,38,12,'Sinä aiot saalista saada, ryöstettävää ryöstää, ojentaa kätesi raunioita kohti, jotka on saatu asutuiksi, ja kansaa kohti, joka on koottu pakanakansain seasta, joka on hankkinut karjaa ja omaisuutta ja asuu maan navassa.'),
(1690400,58,26,38,13,'Saba ja Dedan ja Tarsiin kauppiaat ja kaikki heidän nuoret jalopeuransa kyselevät sinulta: ''Oletko sinä menossa saalista saamaan, ryöstettävää ryöstämään? Oletko koonnut joukkosi kantamaan hopeata ja kultaa, ottamaan karjaa ja omaisuutta, suurta saalista saamaan?'''),
(1690401,58,26,38,14,'Sentähden ennusta, ihmislapsi, ja sano Googille: Näin sanoo Herra, Herra: Sinä päivänä sinä kyllä huomaat, että minun kansani Israel asuu turvallisena,'),
(1690402,58,26,38,15,'ja lähdet asuinpaikastasi pohjan periltä, sinä ja sinun kanssasi lukuisat kansat, jotka kaikki ratsastavat hevosilla: suuri joukko, lukuisa sotaväki.'),
(1690403,58,26,38,16,'Sinä hyökkäät minun kansani Israelin kimppuun kuin pilvi, peittääksesi maan. Päivien lopulla on tämä tapahtuva. Ja minä annan sinun karata maahani, että pakanakansat tulisivat tuntemaan minut, kun minä osoitan pyhyyteni sinussa, Goog, heidän silmäinsä edessä.'),
(1690404,58,26,38,17,'Näin sanoo Herra, Herra: Etkö se ole sinä, josta minä muinaisina päivinä puhuin palvelijaini, Israelin profeettain, kautta, jotka niinä päivinä ennustivat, vuodesta vuoteen, että minä annan sinun karata heidän kimppuunsa?'),
(1690405,58,26,38,18,'Mutta sinä päivänä, jona Goog karkaa Israelin maahan, sanoo Herra, Herra, nousee minun vihani hehku.'),
(1690406,58,26,38,19,'Kiivaudessani, tuimuuteni tulessa minä sanon: Totisesti tulee sinä päivänä suuri maanjäristys Israelin maahan.'),
(1690407,58,26,38,20,'Ja minun edessäni vapisevat meren kalat ja taivaan linnut ja metsän eläimet ja kaikki maassa liikkuvat matelijat ja kaikki ihmiset, jotka maan pinnalla ovat; ja vuoret luhistuvat, ja vuorenpengermät sortuvat, ja kaikki muurit sortuvat maahan.'),
(1690408,58,26,38,21,'Ja minä kutsun häntä vastaan kaikille vuorilleni miekan, sanoo Herra, Herra: toisen miekka on oleva toista vastaan.'),
(1690409,58,26,38,22,'Minä käyn oikeutta hänen kanssansa rutolla ja verellä. Ja minä annan sataa kaatosadetta, raekiviä, tulta ja tulikiveä hänen päällensä, hänen sotalaumojensa päälle ja lukuisain kansojen päälle, jotka hänen kanssansa ovat.'),
(1690410,58,26,38,23,'Niin minä osoitan suuruuteni ja pyhyyteni sekä teen itseni tunnetuksi lukuisain pakanakansain silmien edessä. Ja he tulevat tietämään, että minä olen Herra."'),
(1690411,58,26,39,1,'"Ja sinä, ihmislapsi, ennusta Googia vastaan ja sano: Näin sanoo Herra, Herra: Katso, minä tulen sinun tykösi, Goog, sinä Roosin, Mesekin ja Tuubalin ruhtinas.'),
(1690412,58,26,39,2,'Minä kuljetan sinua, talutan sinua, nostatan sinut pohjan periltä ja annan sinun hyökätä Israelin vuorille.'),
(1690413,58,26,39,3,'Mutta minä lyön pois jousesi sinun vasemmasta kädestäsi ja pudotan nuolesi sinun oikeasta kädestäsi.'),
(1690414,58,26,39,4,'Israelin vuorille sinä olet kaatuva, samoin kaikki sinun sotalaumasi ja kansat, jotka sinun kanssasi ovat: minä annan sinut petolinnuille, kaikille siivekkäille ja metsän eläimille ruuaksi.'),
(1690415,58,26,39,5,'Kentälle sinä kaadut. Sillä minä olen puhunut, sanoo Herra, Herra.'),
(1690416,58,26,39,6,'Ja minä lähetän tulen Maagogiin ja rantamaalla turvassa asuvien keskeen. Ja he tulevat tietämään, että minä olen Herra.'),
(1690417,58,26,39,7,'Ja pyhän nimeni minä teen tunnetuksi kansani Israelin keskuudessa enkä enää salli häväistävän pyhää nimeäni. Ja pakanakansat tulevat tietämään, että minä olen Herra, Israelin Pyhä.'),
(1690418,58,26,39,8,'Katso, se tulee, se tapahtuu, sanoo Herra, Herra: Tämä on se päivä, josta minä olen puhunut.'),
(1690419,58,26,39,9,'Israelin kaupunkien asukkaat menevät ulos ja sytyttävät ja polttavat aseita, pieniä ja suuria kilpiä, jousia, nuolia, käsikarttuja ja keihäitä. He pitävät niitä polttoaineina seitsemän vuotta;'),
(1690420,58,26,39,10,'eivät he kanna puita kedolta eivätkä hakkaa metsistä, vaan pitävät polttoaineina aseita. Näin he saalistavat saalistajiaan ja ryöstävät ryöstäjiään, sanoo Herra, Herra.'),
(1690421,58,26,39,11,'Sinä päivänä minä annan Googille siellä, Israelissa, hautasijan, ''Kulkijain laakson'', itää kohden merestä; se sulkee tien noilta kulkijoilta. Sinne haudataan Goog ja koko hänen meluisa joukkonsa, ja sille pannaan nimeksi: ''Googin meluisan joukon laakso''.'),
(1690422,58,26,39,12,'Niitä hautaa Israelin heimo seitsemän kuukautta puhdistaaksensa maan.'),
(1690423,58,26,39,13,'Koko maan kansa hautaa heitä, ja se on koituva heille kiitokseksi sinä päivänä, jona minä näytän kunniani, sanoo Herra, Herra.'),
(1690424,58,26,39,14,'Valitaan vakinaiset miehet, jotka kulkevat maata ja hautaavat noita kulkijoita, mitä niitä vielä on jäljellä maan pinnalla, puhdistaaksensa sen; seitsemän kuukauden kuluttua he sen tutkivat läpikotaisin.'),
(1690425,58,26,39,15,'Kun nämä kulkijat kulkevat maata ja joku heistä näkee ihmisen luut, laittaa hän niitten ääreen kivimerkin, siihen asti että haudankaivajat saavat ne haudatuiksi ''Googin meluisan joukon laaksoon''.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690426,58,26,39,16,'Onpa eräällä kaupungillakin nimenä Hamona. - Niin he puhdistavat maan.'),
(1690427,58,26,39,17,'Ja sinä, ihmislapsi! Näin sanoo Herra, Herra: Käske lintuja, kaikkia siivekkäitä, ja kaikkia metsän eläimiä: Kokoontukaa, tulkaa, yhtykää joka taholta minun teurasuhrilleni jonka minä teitä varten uhraan, suurelle teurasuhrille Israelin vuorille; syökää lihaa ja juokaa verta.'),
(1690428,58,26,39,18,'Syökää sankarien lihaa ja juokaa maan ruhtinaitten verta - oinaita, lampaita, kauriita ja härkiä, kaikki tyynni Baasanissa syötettyjä.'),
(1690429,58,26,39,19,'Syökää itsenne kylläisiksi rasvasta ja juokaa itsenne juovuksiin verestä, teurasuhrista, jonka minä teitä varten uhraan.'),
(1690430,58,26,39,20,'Tulkaa kylläisiksi minun pöydässäni ratsuista ja vaunuhevosista, sankareista ja kaikenkaltaisista sotamiehistä, sanoo Herra, Herra.'),
(1690431,58,26,39,21,'Minä asetan kunniani pakanakansojen keskeen, ja kaikki pakanakansat saavat nähdä minun tuomioni, jonka minä toimitan, ja käteni, jonka minä lasken heidän päällensä.'),
(1690432,58,26,39,22,'Mutta Israelin heimo tulee tietämään, että minä, Herra, olen heidän Jumalansa siitä päivästä lähtien ja aina eteenpäin.'),
(1690433,58,26,39,23,'Ja pakanakansat tulevat tietämään, että Israelin heimo joutui pakkosiirtolaisuuteen syntivelkansa tähden, koska olivat olleet minulle uskottomat, ja minä kätkin heiltä kasvoni, ja niin minä annoin heidät heidän vihollistensa käsiin, ja he kaatuivat miekkaan kaikki tyynni.'),
(1690434,58,26,39,24,'Minä tein heille heidän saastaisuutensa ja rikkomustensa mukaan ja kätkin heiltä kasvoni.'),
(1690435,58,26,39,25,'Sentähden, näin sanoo Herra, Herra: Nyt minä käännän Jaakobin kohtalon ja armahdan kaikkea Israelin heimoa ja kiivailen pyhän nimeni puolesta.'),
(1690436,58,26,39,26,'Ja häpeänsä ja kaiken uskottomuutensa, jota he ovat minulle osoittaneet, he unhottavat, asuessaan nyt maassansa turvallisina, kenenkään peloittelematta.'),
(1690437,58,26,39,27,'Kun minä tuon heidät takaisin kansojen seasta ja kokoan heidät heidän vihamiestensä maista, niin minä osoitan heissä pyhyyteni lukuisain pakanakansain silmien edessä.'),
(1690438,58,26,39,28,'Ja he tulevat tietämään, että minä, Herra, olen heidän Jumalansa, kun minä, vietyäni heidät pakkosiirtolaisuuteen pakanakansojen luokse, kokoan heidät omaan maahansa enkä jätä sinne jäljelle ainoatakaan heistä.'),
(1690439,58,26,39,29,'Enkä minä enää kätke heiltä kasvojani, sillä minä vuodatan Henkeni Israelin heimon päälle, sanoo Herra, Herra."'),
(1690440,58,26,40,1,'Meidän pakkosiirtolaisuutemme kahdentenakymmenentenä viidentenä vuotena, vuoden alussa, kuukauden kymmenentenä päivänä, neljäntenätoista vuotena kaupungin valloituksen jälkeen, juuri sinä päivänä tuli minun päälleni Herran käsi, ja hän vei minut sinne.'),
(1690441,58,26,40,2,'Jumalan näyissä hän vei minut Israelin maahan ja laski minut hyvin korkealle vuorelle, jolla oli ikäänkuin kaupunki rakennettuna, etelään päin.'),
(1690442,58,26,40,3,'Hän vei minut sinne. Ja katso, oli mies, näöltänsä vasken kaltainen, ja pellavanuora oli hänellä kädessänsä sekä mittaruoko, ja hän seisoi portilla.'),
(1690443,58,26,40,4,'Ja mies puhui minulle: "Ihmislapsi, katso silmilläsi, kuule korvillasi ja ota huomioosi kaikki, mitä minä sinulle näytän; sillä sinut on tuotu tänne sitä varten, että nämä sinulle näytettäisiin. Ilmoita kaikki, mitä näet, Israelin heimolle.'),
(1690444,58,26,40,5,'Ja katso, oli muuri temppelin ulkopuolella, yltympäri sen. Ja miehen kädessä oli mittaruoko, kuusikyynäräinen, kyynärään luettuna kyynärä ja kämmenenleveys. Ja hän mittasi muurirakennuksen leveyden: yksi ruoko, ja korkeuden: yksi ruoko.'),
(1690445,58,26,40,6,'Sitten hän meni portille, jonka etupuoli oli itää kohden, nousi ylös sen portaita ja mittasi portin kynnyksen: se oli yhden ruovon levyinen - ensimmäinen kynnys: yhden ruovon levyinen.'),
(1690446,58,26,40,7,'Sivuhuone oli aina yhden ruovon pituinen ja yhden ruovon levyinen, ja sivuhuoneitten väliä oli viisi kyynärää. Portin kynnys porttieteisen laidassa, sisäpuolella: yksi ruoko.'),
(1690447,58,26,40,8,'Ja hän mittasi porttieteisen, joka oli sisäpuolella: yksi ruoko.'),
(1690448,58,26,40,9,'Ja hän mittasi porttieteisen: kahdeksan kyynärää, ja sen seinäpatsaat: kaksi kyynärää. Ja porttieteinen oli sisemmällä puolen.'),
(1690449,58,26,40,10,'Itää kohden antavan portin sivuhuoneita oli kolme kummallakin puolella. Ne kolme olivat yhtä suuria, ja niiden seinäpatsaat kummallakin puolella olivat yhtä suuria.'),
(1690450,58,26,40,11,'Ja hän mittasi portin oviaukon leveyden: kymmenen kyynärää, ja portin pituuden: kolmetoista kyynärää.'),
(1690451,58,26,40,12,'Mutta sivuhuoneitten edessä oli aitaus: yksi kyynärä, samoin toisella puolella oleva aitaus: yksi kyynärä; ja kukin sivuhuone kummallakin puolella: kuusi kyynärää.'),
(1690452,58,26,40,13,'Ja hän mittasi portin, yhden sivuhuoneen katosta toisen kattoon: leveys oli kaksikymmentä viisi kyynärää, ovet vastatusten.'),
(1690453,58,26,40,14,'Sitten hän otti mitan seinäpatsaista: kaksikymmentä kyynärää. Seinäpatsaisiin liittyi esipiha portin ympärillä.'),
(1690454,58,26,40,15,'Ja sisäänkäyntiportin edestä sisäportin eteisen eteen oli viisikymmentä kyynärää.'),
(1690455,58,26,40,16,'Portissa yltympäri oli sisäänpäin, sivuhuoneisiin ja niitten seinäpatsaisiin päin, avartuvia ikkuna-aukkoja; samoin eteisissä. Ikkuna-aukot ympärinsä laajenivat sisäänpäin. Ja seinäpatsaissa oli palmukoristeita.'),
(1690456,58,26,40,17,'Sitten hän vei minut ulompaan esipihaan. Ja katso: ympäri esipihan oli kammioita ja kivillä laskettu permanto. Kivillä lasketun permannon laidassa oli kolmekymmentä kammiota.'),
(1690457,58,26,40,18,'Kivillä laskettu permanto oli porttien sivuseinämillä, porttien pituuden mukaisesti; tämä oli alempi kivillä laskettu permanto.'),
(1690458,58,26,40,19,'Ja hän mittasi leveyden alemman portin edestä sisemmän esipihan edustalle, ulkopuolelle: sata kyynärää sekä itä- että pohjoispuolella.'),
(1690459,58,26,40,20,'Sitten hän mittasi sen portin pituuden ja leveyden, jonka etupuoli oli pohjoista kohden ja joka vei ulompaan esipihaan.'),
(1690460,58,26,40,21,'Siinä oli kolme sivuhuonetta kummallakin puolella, ja sen seinäpatsaat ja eteinen olivat yhtä suuret kuin ensimmäisessä portissa. Sen pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.'),
(1690461,58,26,40,22,'Ja sen ikkuna-aukot, eteinen ja palmukoristeet olivat yhtä suuret kuin portin, jonka etupuoli oli itää kohden, ja sinne noustiin seitsemää porrasta, ja niistä eteenpäin oli sen eteinen.'),
(1690462,58,26,40,23,'Sisemmällä esipihalla oli portti porttia vastassa pohjoista ja itää kohden. Ja hän mittasi portista porttiin: sata kyynärää.'),
(1690463,58,26,40,24,'Sitten hän kuljetti minua etelää kohden, ja katso, tuli portti, joka antoi etelää kohden. Ja hän mittasi sen seinäpatsaat ja eteisen: ne olivat yhtä suuret kuin nuo toiset.'),
(1690464,58,26,40,25,'Ja siinä ja sen eteisessä oli ikkuna-aukkoja ympärinsä, samanlaisia kuin nuo toiset ikkuna-aukot. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.'),
(1690465,58,26,40,26,'Sen ylöskäytävässä oli seitsemän porrasta, ja niistä eteenpäin oli sen eteinen. Ja siinä oli palmukoristeet, yksi kummallakin puolella, sen seinäpatsaissa.'),
(1690466,58,26,40,27,'Sisemmässä esipihassa oli portti etelää kohden. Ja hän mittasi portista porttiin etelää kohden: sata kyynärää.'),
(1690467,58,26,40,28,'Sitten hän vei minut sisempään esipihaan eteläportin kautta. Ja hän mittasi eteläportin: se oli yhtä suuri kuin nuo toiset.'),
(1690468,58,26,40,29,'Ja sen sivuhuoneet, seinäpatsaat ja eteinen olivat yhtä suuret kuin nuo toiset. Ja siinä ja sen eteisessä oli ikkuna-aukkoja ympärinsä. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.'),
(1690469,58,26,40,30,'Ja eteisiä oli ympärinsä; pituus kaksikymmentä viisi kyynärää, leveys viisi kyynärää.'),
(1690470,58,26,40,31,'Sen eteinen oli ulompaan esipihaan päin, ja sen seinäpatsaissa oli palmukoristeita. Sen portaissa oli kahdeksan porrasta.'),
(1690471,58,26,40,32,'Sitten hän vei minut sisempään esipihaan itää kohden. Ja hän mittasi portin: se oli yhtä suuri kuin nuo toiset.'),
(1690472,58,26,40,33,'Ja sen sivuhuoneet, seinäpatsaat ja eteinen olivat yhtä suuret kuin nuo toiset. Ja siinä ja sen eteisessä oli ikkuna-aukkoja ympärinsä. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.'),
(1690473,58,26,40,34,'Sen eteinen oli ulompaan esipihaan päin, ja sen seinäpatsaissa oli palmukoristeita kummallakin puolella. Sen portaissa oli kahdeksan porrasta.'),
(1690474,58,26,40,35,'Sitten hän vei minut pohjoisportille ja mittasi: yhtä suuret kuin nuo toiset'),
(1690475,58,26,40,36,'olivat sen sivuhuoneet, seinäpatsaat ja eteinen. Ja ikkuna-aukkoja oli siinä ympärinsä. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690476,58,26,40,37,'Sen eteinen oli ulompaan esipihaan päin, ja sen seinäpatsaissa oli palmukoristeita kummallakin puolella. Sen portaissa oli kahdeksan porrasta.'),
(1690477,58,26,40,38,'Ja oli kammio, jonka ovi oli seinäpatsaissa, porteissa. Siellä oli polttouhri huuhdottava.'),
(1690478,58,26,40,39,'Ja porttieteisessä oli kaksi pöytää kummallakin puolella; niillä oli polttouhri, syntiuhri ja vikauhri teurastettava.'),
(1690479,58,26,40,40,'Ja ulkopuolisella sivuseinämällä, portin ovelle noustessa, pohjoispuolella, oli kaksi pöytää; samoin porttieteisen toisella sivuseinämällä kaksi pöytää:'),
(1690480,58,26,40,41,'neljä pöytää portin sivuseinämillä kummallakin puolella, siis kahdeksan pöytää. Niillä oli teurastettava.'),
(1690481,58,26,40,42,'Ja ylöskäytävän ääressä oli neljä pöytää hakatuista kivistä. Ne olivat puolentoista kyynärän pituisia, puolentoista kyynärän levyisiä ja yhden kyynärän korkuisia. Niille oli laskettava ne aseet, joilla teurastettiin polttouhri ja teurasuhri.'),
(1690482,58,26,40,43,'Ja haarukkakoukkuja, kämmenenleveyttä pitkiä, oli kiinnitetty ympäri huonetta, mutta uhriliha pantiin pöydille.'),
(1690483,58,26,40,44,'Sisemmän portin ulkopuolella oli kaksi kammiota sisemmässä esipihassa, toinen pohjoisen portin sivuseinämällä, etupuoli etelää kohden, ja toinen eteläisen portin sivuseinämällä, etupuoli pohjoista kohden.'),
(1690484,58,26,40,45,'Ja hän puhui minulle: "Tämä kammio, jonka etupuoli on etelää kohden, on pappeja varten, jotka hoitavat temppelitehtäviä.'),
(1690485,58,26,40,46,'Ja kammio, jonka etupuoli on pohjoista kohden, on pappeja varten, jotka hoitavat alttaritehtäviä. Ne ovat Saadokin jälkeläiset, ne leeviläisistä, jotka saavat lähestyä Herraa häntä palvellakseen."'),
(1690486,58,26,40,47,'Ja hän mittasi esipihan: pituus oli sata kyynärää ja leveys sata kyynärää; se oli neliön muotoinen. Ja alttari oli temppelin edustalla.'),
(1690487,58,26,40,48,'Sitten hän vei minut temppelin eteiseen ja mittasi eteisen seinäpatsaan: viisi kyynärää kummallakin puolella, ja portin leveyden: kolme kyynärää kummallakin puolella.'),
(1690488,58,26,40,49,'Eteisen pituus oli kaksikymmentä kyynärää ja leveys yksitoista kyynärää. Sinne noustiin kymmentä porrasta. Ja seinäpatsaitten ääressä oli pylväät, yksi kummallakin puolella.'),
(1690489,58,26,41,1,'Sitten hän vei minut temppelisaliin ja mittasi seinäpatsaat; ne olivat kuutta kyynärää leveitä kummallakin puolella: ilmestysmajan leveys.'),
(1690490,58,26,41,2,'Ja oviaukko oli kymmentä kyynärää leveä, ja oviaukon sivuseinät kummallakin puolella olivat viisikyynäräiset. Hän mittasi temppelisalin pituuden: neljäkymmentä kyynärää, ja leveyden: kaksikymmentä kyynärää.'),
(1690491,58,26,41,3,'Sitten hän meni sisimpään ja mittasi oviaukon seinäpatsaan: kaksi kyynärää, oviaukon: kuusi kyynärää, ja oviaukon leveyden: seitsemän kyynärää.'),
(1690492,58,26,41,4,'Ja hän mittasi sen pituuden: kaksikymmentä kyynärää, ja leveyden: kaksikymmentä kyynärää temppelisalin puolelta. Ja hän sanoi minulle: "Tämä on kaikkeinpyhin".'),
(1690493,58,26,41,5,'Sitten hän mittasi temppelin seinän: kuusi kyynärää, ja sivukammion leveyden: neljä kyynärää, yltympäri temppelin.'),
(1690494,58,26,41,6,'Ja sivukammioita oli: kolme sivukammiota päällekkäin, kolmeenkymmeneen kertaan; ja ne kulkivat ympärinsä sen temppeliseinän varassa, joka oli sivukammioihin päin, niin että pysyivät siinä kiinni, mutta ne eivät olleet kiinnitetyt temppelinseinän sisään.'),
(1690495,58,26,41,7,'Ja sivukammiot olivat aina sitä leveämpiä kiertäessään, mitä ylempänä olivat, sillä temppelin ympäryskammiot ulottuivat ylemmäksi ja ylemmäksi ympäri temppelin, ollen siten ylhäällä leveämmät sisäänpäin. Ja alakerrasta noustiin yläkertaan keskikerroksen kautta.'),
(1690496,58,26,41,8,'Ja minä näin, että temppelillä oli koroke ympärinsä: sivukammioitten perustukset, koko ruovon korkuiset, kuusi kyynärää, reunustaan asti.'),
(1690497,58,26,41,9,'Sivukammioitten ulkoseinän paksuus oli viisi kyynärää; yhtä leveä oli avoin tila sivukammiorakennuksen ääressä, joka temppeliin kuului.'),
(1690498,58,26,41,10,'Välimatkaa pihakammiorakennuksiin oli kahtakymmentä kyynärää leveälti ympäri temppelin - yltympäri.'),
(1690499,58,26,41,11,'Ja sivukammioista vei ovi avoimeen tilaan: yksi ovi pohjoista kohden ja toinen ovi etelää kohden. Ja avoimen tilan leveys oli viisi kyynärää yltympäri.'),
(1690500,58,26,41,12,'Ja rakennus, joka oli eristetyn alueen laidassa lännen puoleisella sivulla, oli seitsemääkymmentä kyynärää leveä. Rakennuksen seinän paksuus oli viisi kyynärää, ympärinsä, ja sen pituus oli yhdeksänkymmentä kyynärää.'),
(1690501,58,26,41,13,'Sitten hän mittasi temppelin: pituus oli sata kyynärää, sekä eristetyn alueen ja rakennuksen seininensä: pituus sata kyynärää.'),
(1690502,58,26,41,14,'Temppelin etupuolen ja eristetyn alueen leveys itään päin oli sata kyynärää.'),
(1690503,58,26,41,15,'Sitten hän mittasi sen rakennuksen pituuden, joka oli eristetyn alueen laidassa, sen takana, ynnä sen käytävät, kummallakin puolella: sata kyynärää; ja sisemmän temppelisalin, esipihan eteiset,'),
(1690504,58,26,41,16,'kynnykset, sisäänpäin avartuvat ikkuna-aukot, käytävät niitten kolmen ympärillä - kynnyksen edessä oli puulaudoitus yltympäri - ja välin maasta ikkuna-aukkoihin. Ja ikkuna-aukot olivat peitetyt.'),
(1690505,58,26,41,17,'Oviaukkojen yläpuolelta lähtien sekä sisempään temppeliin asti että ulos asti, koko seinällä yltympäri, sisä- ja ulkopuolella, oli mitatut alat,'),
(1690506,58,26,41,18,'ja niihin oli tehty kerubeja ja palmuja, palmu aina kahden kerubin väliin. Ja kullakin kerubilla oli kahdet kasvot:'),
(1690507,58,26,41,19,'ihmisen kasvot palmuun päin toisaalle ja leijonan kasvot palmuun päin toisaalle. Niin oli tehty koko temppelissä yltympäri:'),
(1690508,58,26,41,20,'maasta alkaen ja aina oviaukkojen yläpuolelle oli tehty kerubeja ja palmuja, samoin temppelisalin seinälle.'),
(1690509,58,26,41,21,'Temppelisalissa oli nelikulmaiset ovenpielet. Mutta pyhimmän edessä näkyi'),
(1690510,58,26,41,22,'ikäänkuin alttari, puinen, kolmea kyynärää korkea, ja sen pituus oli kaksi kyynärää. Siinä oli nurkkaukset, ja sen jalusta ja seinät olivat puuta. Ja hän sanoi minulle: "Tämä on pöytä, joka on Herran edessä".'),
(1690511,58,26,41,23,'Sekä temppelisalissa että pyhimmässä oli kaksoisovet.'),
(1690512,58,26,41,24,'Ja ovissa oli kaksi ovipuoliskoa, kaksi kääntyvää ovipuoliskoa: kumpaisessakin ovessa oli kaksi ovipuoliskoa.'),
(1690513,58,26,41,25,'Ja niihin, temppelisalin oviin, oli tehty kerubeja ja palmuja, samoin kuin oli tehty seiniin. Ulkona, eteisen edessä, oli puinen porraskatos.'),
(1690514,58,26,41,26,'Ja eteisen sivuseinissä, kummallakin puolella, oli sisäänpäin avartuvia ikkuna-aukkoja ja palmuja; samoin temppelin sivukammioissa ja porraskatoksissa.'),
(1690515,58,26,42,1,'Sitten hän vei minut ulompaan esipihaan pohjoista kohden viepää tietä myöten, vei minut pihakammio-rakennuksen luo, joka oli eristettyä aluetta vastassa ja pohjoispuolista muurirakennusta vastassa,'),
(1690516,58,26,42,2,'satakyynäräisen pitkänsivun edustalle, jossa oli oviaukko pohjoiseen päin; leveys taas oli viisikymmentä kyynärää.'),
(1690517,58,26,42,3,'Sen kaksikymmenkyynäräisen paikan edustalla, joka kuului sisempään esipihaan, ja vastapäätä sitä kivillä laskettua permantoa, joka oli ulommassa esipihassa, oli käytävä käytävää vastassa, kolmessa kerroksessa.'),
(1690518,58,26,42,4,'Kammioiden editse meni kulkutie, kymmentä kyynärää leveä, sisempään esipihaan, sataa kyynärää pitkä, ja oviaukot olivat pohjoiseen päin.'),
(1690519,58,26,42,5,'Mutta ylimmät kammiot olivat kapeimmat, sillä käytävät ottivat niiltä tilaa enemmän kuin alimmilta ja keskimmäisiltä kammioilta rakennuksessa.'),
(1690520,58,26,42,6,'Sillä nämä olivat kolmikertaiset, mutta niissä ei ollut pylväitä, niinkuin esipihoissa oli pylväät; sentähden ne tulivat olemaan kaitaisemmat kuin alimmat ja keskimmäiset, maasta lukien.'),
(1690521,58,26,42,7,'Oli myös muuri, joka ulkopuolella kulki yhtä suuntaa kammioiden kanssa ulompaa esipihaa kohden kammioiden editse; sen pituus oli viisikymmentä kyynärää.'),
(1690522,58,26,42,8,'Sillä niiden kammioiden pituus, jotka olivat ulompaan esipihaan päin, oli yhteensä viisikymmentä kyynärää; mutta, katso, temppelisalin puolella sata kyynärää.'),
(1690523,58,26,42,9,'Ja näiden kammioiden alapuolella oli sisäänkäynti idästäpäin, kun tultiin niitten luokse ulommasta esipihasta,'),
(1690524,58,26,42,10,'esipihaa ympäröivän muurin leveyspuolella. Etelää kohden, eristetyn alan edustalla ja rakennuksen edustalla, oli kammioita,'),
(1690525,58,26,42,11,'ja niiden editse kävi tie. Ne olivat samanmuotoisia kuin ne kammiot, jotka olivat pohjoista kohden: yhtä pitkiä ja leveitä. Samanlaisia olivat kaikki näitten uloskäytävät, laitteet ja oviaukot.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690526,58,26,42,12,'Ja samoin kuin olivat niiden kammioiden oviaukot, jotka olivat etelää kohden, oli se oviaukko, joka oli tien päässä - tien, joka kulki senpuolisen muurin viertä itää kohden, sinne tultaessa.'),
(1690527,58,26,42,13,'Ja hän sanoi minulle: "Pohjoiskammiot ja eteläkammiot, jotka ovat eristetyn alan edustalla, ne ovat pyhiä kammioita, joissa papit, jotka lähestyvät Herraa, syövät sitä, mikä on korkeasti-pyhää. Sinne he pankoot korkeasti-pyhän: ruokauhrin, syntiuhrin ja vikauhrin; sillä se paikka on pyhä.'),
(1690528,58,26,42,14,'Kun papit ovat tulleet, älkööt he menkö pyhäköstä ulos esipihaan muutoin, kuin että tänne panevat vaatteensa, joissa toimittavat virkaansa, sillä ne ovat pyhät, ja pukeutuvat toisiin vaatteisiin; sitten lähestykööt paikkaa, mikä on kansaa varten."'),
(1690529,58,26,42,15,'Kun hän oli saanut loppuun sisemmän temppelin mittaamisen, vei hän minut ulos sille portille, jonka etupuoli oli itää kohden. Ja hän mittasi sen ympärinsä.'),
(1690530,58,26,42,16,'Hän mittasi itäilmalta mittaruovolla: viisi sataa ruokoa mittaruovon mukaan. Hän kääntyi'),
(1690531,58,26,42,17,'ja mittasi pohjoisilmalta: viisisataa ruokoa mittaruovon mukaan. Hän kääntyi'),
(1690532,58,26,42,18,'ja mittasi eteläilmalta: viisisataa ruokoa mittaruovon mukaan.'),
(1690533,58,26,42,19,'Hän kääntyi ja mittasi länsi-ilmalta: viisisataa ruokoa mittaruovon mukaan.'),
(1690534,58,26,42,20,'Neljältä ilmansuunnalta hän sen mittasi. Siinä oli muuri yltympäri; pituutta viisisataa ja leveyttä viisisataa. Sen tuli erottaa pyhä epäpyhästä.'),
(1690535,58,26,43,1,'Sitten hän kuljetti minut portille - sille portille, joka antoi itää kohden.'),
(1690536,58,26,43,2,'Ja katso: Israelin Jumalan kunnia tuli idästä päin. Sen kohina oli niinkuin paljojen vetten kohina, ja maa kirkastui hänen kunniastansa.'),
(1690537,58,26,43,3,'Ja näky, jonka minä näin, oli samanlainen kuin se näky, jonka olin nähnyt tullessani hävittämään kaupunkia; samanlaiset olivat näyt kuin se näky, jonka olin nähnyt Kebar-joen varrella. Niin minä lankesin kasvoilleni.'),
(1690538,58,26,43,4,'Ja Herran kunnia kulki temppeliin sen portin kautta, jonka etupuoli oli itää kohden.'),
(1690539,58,26,43,5,'Ja henki nosti minut ja vei minut sisempään esipihaan. Ja katso: Herran kunnia täytti temppelin.'),
(1690540,58,26,43,6,'Ja minä kuulin jonkun puhuttelevan minua temppelistä; mutta mies seisoi minun vieressäni.'),
(1690541,58,26,43,7,'Se ääni sanoi minulle: "Ihmislapsi, tämä on minun valtaistuimeni sija ja minun jalkapohjaini sija, jossa minä tahdon asua israelilaisten keskellä iankaikkisesti. Ja Israelin heimo ei ole enää saastuttava minun pyhää nimeäni - eivät he eivätkä heidän kuninkaansa - haureudellansa, kuninkaittensa ruumiilla ja uhrikukkuloillansa.'),
(1690542,58,26,43,8,'Kun he asettivat kynnyksensä minun kynnykseni ääreen, ovenpielensä minun ovenpielteni ääreen, niin että muuri vain oli minun ja heidän välillään, niin he saastuttivat minun pyhän nimeni kauhistuksillansa, joita harjoittivat, ja minä lopetin heidät vihassani.'),
(1690543,58,26,43,9,'Nyt he vievät haureutensa ja kuninkaittensa ruumiit kauas minusta, ja minä asun heidän keskellänsä iankaikkisesti.'),
(1690544,58,26,43,10,'Sinä, ihmislapsi, saata Israelin heimolle sanoma tästä temppelistä, että he häpeäisivät rikkomuksiansa; ja he mitatkoot sen sopusuhtaisuuden.'),
(1690545,58,26,43,11,'Ja jos he häpeävät kaikkea, mitä ovat tehneet, niin tee heille tiettäväksi temppelin muoto sekä sen sisustus, uloskäytävät, sisäänkäytävät, kaikki muodot, kaikki säädökset, kaikki muodot ja kaikki lait; kirjoita ne heidän silmiensä eteen, että he ottaisivat vaarin sen koko muodosta ja kaikista säädöksistä ja tekisivät niiden mukaan.'),
(1690546,58,26,43,12,'Tämä on temppelin laki: sen koko alue vuoren laella yltympäri on korkeastipyhä. Katso, tämä on temppelin laki."'),
(1690547,58,26,43,13,'Ja nämä olivat alttarin mitat kyynärissä, kyynärään luettuna kyynärä ja kämmenenleveys: sen alusta oli kyynärän korkuinen ja kyynärän levyinen, ja sen reunusta ympäri sen laidan oli yhden vaaksan mittainen. Tämä oli alttarin koroke.'),
(1690548,58,26,43,14,'Alustasta, joka oli maassa, alimmalle välireunalle: kaksi kyynärää sekä leveyttä yksi kyynärä; ja pienemmältä välireunalta suuremmalle välireunalle: neljä kyynärää sekä leveyttä kyynärä.'),
(1690549,58,26,43,15,'Jumalan lieteen oli neljä kyynärää, ja Jumalan liedestä ylöspäin olivat ne neljä sarvea.'),
(1690550,58,26,43,16,'Jumalan lieden pituus oli kaksitoista kyynärää ja leveys kaksitoista, niin että sen neljästä sivusta tuli neliö.'),
(1690551,58,26,43,17,'Välireunan pituus oli neljätoista kyynärää ja leveys neljätoista, sen neljältä sivulta. Sitä ympäröivä reunusta oli puolikyynäräinen, ja sen alusta oli kyynäräinen ympärinsä. Ja sen portaat olivat itäisellä puolella.'),
(1690552,58,26,43,18,'Ja hän sanoi minulle: "Ihmislapsi, näin sanoo Herra, Herra: Nämä ovat alttaria koskevat säädökset: Sinä päivänä, jona se on saatu tehdyksi, niin että voidaan sillä uhrata polttouhria ja vihmoa sille verta,'),
(1690553,58,26,43,19,'anna papeille, leeviläisille, jotka ovat Saadokin jälkeläisiä ja saavat minua lähestyä palvellaksensa minua, sanoo Herra, Herra, mullikka syntiuhriksi.'),
(1690554,58,26,43,20,'Ota sen verta ja sivele alttarin neljään sarveen ja välireunan neljään kulmaan ja reunustaan yltympäri; niin on sinun puhdistettava se ja toimitettava sen sovitus.'),
(1690555,58,26,43,21,'Ota sitten syntiuhri-mullikka ja polta se säädetyssä, temppelille kuuluvassa paikassa, pyhäkön ulkopuolella.'),
(1690556,58,26,43,22,'Tuo toisena päivänä virheetön kauris syntiuhriksi; alttari on puhdistettava, samoin kuin se puhdistettiin mullikalla.'),
(1690557,58,26,43,23,'Suoritettuasi loppuun puhdistuksen tuo virheetön mullikka ja virheetön oinas pikkukarjasta.'),
(1690558,58,26,43,24,'Tuo ne Herran eteen, ja papit heittäkööt niiden päälle suolaa ja uhratkoot ne polttouhriksi Herralle.'),
(1690559,58,26,43,25,'Uhraa joka päivä, seitsemänä päivänä, syntiuhri-kauris; myös on uhrattava mullikka ja oinas pikkukarjasta, virheettömät.'),
(1690560,58,26,43,26,'Seitsemänä päivänä toimitettakoon alttarin sovitus ja puhdistettakoon ja vihittäköön se.'),
(1690561,58,26,43,27,'Niiden päivien kuluttua papit kahdeksantena päivänä ja aina edelleen uhratkoot alttarilla polttouhrejansa ja yhteysuhrejansa. Ja niin minä teihin mielistyn, sanoo Herra, Herra."'),
(1690562,58,26,44,1,'Sitten hän vei minut takaisin pyhäkön ulommalle portille, sille, joka antoi itään päin; mutta se oli suljettu.'),
(1690563,58,26,44,2,'Niin Herra sanoi minulle: "Tämä portti on oleva suljettuna: sitä ei saa avata, eikä kenkään saa käydä siitä sisälle, sillä Herra, Israelin Jumala, on käynyt siitä sisälle. Se on oleva suljettu.'),
(1690564,58,26,44,3,'Ruhtinas ainoastaan saakoon ruhtinaana istua siellä ja aterioida Herran edessä; käyköön hän sisään porttieteisen kautta ja tulkoon ulos samaa tietä."'),
(1690565,58,26,44,4,'Sitten hän vei minut pohjoisportin kautta temppelin edustalle, ja minä näin, ja katso: Herran kunnia täytti Herran temppelin. Niin minä lankesin kasvoilleni.'),
(1690566,58,26,44,5,'Ja Herra sanoi minulle: "Ihmislapsi, ota huomioosi, katso silmilläsi ja kuule korvillasi kaikki, mitä minä sinulle puhun kaikista Herran temppelin säädöksistä ja kaikista sen laeista, ja ota huomioosi, kuinka temppeliin on mentävä kustakin pyhäkön uloskäytävästä.'),
(1690567,58,26,44,6,'Ja sano niille uppiniskaisille, sano Israelin heimolle: Näin sanoo Herra, Herra: Jo riittävät kaikki teidän kauhistuksenne, te Israelin heimo,'),
(1690568,58,26,44,7,'te kun olette tuoneet muukalaisia, sydämeltään ja ruumiiltaan ympärileikkaamattomia, minun pyhäkkööni olemaan siellä ja häpäisemään minun temppeliäni, samalla kuin olette uhranneet minun leipääni ja rasvaa ja verta; ja niin te olette rikkoneet minun liittoni - kaikkien muitten kauhistustenne lisäksi.'),
(1690569,58,26,44,8,'Te ette ole itse hoitaneet minulle suoritettavia pyhiä tehtäviä, vaan olette panneet heitä puolestanne hoitamaan minulle pyhäkössäni suoritettavia tehtäviä.'),
(1690570,58,26,44,9,'Näin sanoo Herra, Herra: ei yksikään muukalainen, sydämeltään ja ruumiiltaan ympärileikkaamaton, saa tulla minun pyhäkkööni, olkoon se kuka tahansa muukalainen, joka israelilaisten keskuudessa on.'),
(1690571,58,26,44,10,'Vaan ne leeviläiset, jotka menivät minun luotani kauas, silloin kun Israel oli joutunut eksyksiin, nuo, jotka eksyivät pois minusta kivijumalainsa jälkeen, kantakoot syntinsä;'),
(1690572,58,26,44,11,'he toimittakoot minun pyhäkössäni vartioinnin temppelin porteilla ja toimittakoot temppelipalveluksen: he teurastakoot polttouhrit ja teurasuhrit kansalle ja seisokoot heidän edessään heitä palvelemassa.'),
(1690573,58,26,44,12,'Koska he ovat heitä palvelleet heidän kivijumalainsa edessä ja olleet Israelin heimolle kompastuksena syntiin, sentähden minä kättä kohottaen vakuutan heistä, sanoo Herra, Herra, että heidän on kannettava syntinsä.'),
(1690574,58,26,44,13,'He eivät saa lähestyä minua, niin että toimittaisivat minun edessäni papinvirkaa ja lähestyisivät mitään minulle pyhitettyä, mitään korkeasti-pyhää, vaan heidän on kannettava häpeänsä ja kauhistuksensa, joita ovat tehneet.'),
(1690575,58,26,44,14,'Ja minä panen heidät hoitamaan temppelissä suoritettavia tehtäviä, mitä siellä vain on palvelijantyötä ja toimitettavaa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690576,58,26,44,15,'Mutta ne leeviläiset papit, Saadokin jälkeläiset, jotka hoitivat minun pyhäkössäni suoritettavat tehtävät silloin, kun israelilaiset olivat eksyneet minusta pois, he saavat lähestyä minua, palvella minua ja seisoa minun edessäni uhraamassa minulle rasvaa ja verta, sanoo Herra, Herra.'),
(1690577,58,26,44,16,'He saavat tulla minun pyhäkkööni ja saavat lähestyä minun pöytääni, palvellen minua ja hoitaen minulle suoritettavat tehtävät.'),
(1690578,58,26,44,17,'Ja tullessaan sisemmän esipihan porteille he pukeutukoot pellavavaatteisiin älköötkä pitäkö yllänsä villaista toimittaessaan virkaansa sisemmän esipihan porteissa ja sisällä temppelissä.'),
(1690579,58,26,44,18,'Pellavaiset juhlapäähineet olkoon heillä päässä ja pellavakaatiot lanteilla. Älkööt he panko vyötäisillensä mitään hiostuttavaa.'),
(1690580,58,26,44,19,'Kun he sitten menevät pois ulompaan esipihaan, kansan tykö ulompaan esipihaan, riisukoot vaatteensa, joissa ovat virkaa toimittaneet, jättäkööt ne pyhäkön kammioihin ja pukekoot yllensä toiset vaatteet, etteivät pyhittäisi kansaa vaatteillansa.'),
(1690581,58,26,44,20,'Älkööt he ajelko päätänsä, mutta älkööt myöskään antako tukkansa valtoinaan kasvaa: heidän on leikattava hiuksensa.'),
(1690582,58,26,44,21,'Viiniä älköön kukaan pappi juoko tultuansa sisempään esipihaan.'),
(1690583,58,26,44,22,'Leskeä ja hyljättyä älkööt he ottako vaimoksensa, vaan ottakoot neitsyen Israelin heimon jälkeläisistä tai lesken, joka on leskenä papin jälkeen.'),
(1690584,58,26,44,23,'Ja opettakoot he minun kansalleni erotuksen pyhän ja epäpyhän välillä sekä tehkööt heille tiettäväksi, mikä on saastaista, mikä puhdasta.'),
(1690585,58,26,44,24,'Riita-asioissa he seisokoot tuomitsemassa ja tuomitkoot niissä minun oikeuksieni mukaan. Minun lakejani ja käskyjäni he noudattakoot kaikkien minun juhlieni vietossa ja pyhittäkööt minun sapattini.'),
(1690586,58,26,44,25,'Älköön hän menkö kuolleen ihmisen luo ja siten tulko saastaiseksi; ainoastaan isästä ja äidistä, pojasta ja tyttärestä, veljestä ja sisaresta, jos tämä ei ollut naitu, hän saa näin saattaa itsensä saastaiseksi.'),
(1690587,58,26,44,26,'Mutta puhdistuksensa jälkeen luettakoon hänelle vielä seitsemän päivää;'),
(1690588,58,26,44,27,'ja sinä päivänä, jona hän tulee pyhäkköön, sisempään esipihaan, toimittamaan virkaansa pyhäkössä, hän uhratkoon syntiuhrinsa, sanoo Herra, Herra.'),
(1690589,58,26,44,28,'Ja tämä on oleva heidän perintöosansa: minä olen heidän perintöosansa. Teidän ei tule antaa heille perintömaata Israelissa: minä olen heidän perintömaansa.'),
(1690590,58,26,44,29,'Ruokauhrin, syntiuhrin ja vikauhrin he saavat syödä, ja kaikki, mikä on tuhon omaksi vihittyä Israelissa, on tuleva heille.'),
(1690591,58,26,44,30,'Paras kaikesta uutisesta, kaikenlaatuisesta, ja kaikki annit, mitä laatua hyvänsä antinne ovatkin, tulevat papeille; ja parhaat jyvärouheistanne on teidän annettava papille, että sinä tuottaisit siunauksen huoneellesi.'),
(1690592,58,26,44,31,'Papit älkööt syökö mitään itsestään kuollutta tai kuoliaaksi raadeltua, ei lintua eikä raavasta."'),
(1690593,58,26,45,1,'"Kun te arvotte maata perintöosiksi, niin antakaa Herralle anti, pyhä osa maasta, kahtakymmentäviittä tuhatta pitkä ja kahtakymmentä tuhatta leveä. Se olkoon pyhä koko alueeltaan, yltympäri.'),
(1690594,58,26,45,2,'Siitä tulkoon pyhäkölle neliö, viisisataa ja viisisataa joka taholta, ja sen lisäksi avointa tilaa viisikymmentä joka taholta.'),
(1690595,58,26,45,3,'Ja mittaa tästä mitatusta alueesta kahtakymmentäviittä tuhatta pitkälti ja kymmentätuhatta leveälti, ja siinä olkoon pyhäkkö, korkeasti-pyhä.'),
(1690596,58,26,45,4,'Se olkoon pyhä osa maasta papeille, jotka palvelevat pyhäkössä, jotka lähestyvät ja palvelevat Herraa; se olkoon talojen sijana heitä varten ja pyhänä paikkana pyhäkköä varten.'),
(1690597,58,26,45,5,'Kahtakymmentäviittä tuhatta pitkälti ja kymmentätuhatta leveälti on tuleva leeviläisille, jotka toimittavat palvelusta pyhäkössä, heille perintömaaksi - kaksikymmentä kammiota -.'),
(1690598,58,26,45,6,'Kaupungille antakaa perintömaata viittätuhatta leveälti ja kahtakymmentäviittä tuhatta pitkälti, pyhän antimaan viereltä; se olkoon kaiken Israelin heimon oma.'),
(1690599,58,26,45,7,'Ja ruhtinaalle: molemmilta puolin pyhää antimaata ja kaupungin perintömaata, pyhän antimaan sivusta ja kaupungin perintömaan sivusta, lännen puolelta länteen päin ja idän puolelta itään päin, maata yhtä pitkälti kuin on yhden sukukuntaosan pituus länsirajasta itärajaan.'),
(1690600,58,26,45,8,'Se olkoon hänellä maana, perintömaana Israelissa; ja älkööt minun ruhtinaani enää sortako minun kansaani, vaan jättäkööt muun maan Israelin heimolle sukukunnittain.'),
(1690601,58,26,45,9,'Näin sanoo Herra, Herra: Jo riittää, te Israelin ruhtinaat! Heittäkää pois väkivalta ja sorto, noudattakaa oikeutta ja vanhurskautta, heretkää häätämästä mailtansa minun kansaani, sanoo Herra, Herra.'),
(1690602,58,26,45,10,'Olkoon teillä oikea paino, oikea eefa-mitta ja oikea bat-mitta.'),
(1690603,58,26,45,11,'Eefa- ja bat-mitta olkoot tarkoin yhtä suuret: bat vetäköön kymmenenneksen hoomer-mittaa ja eefa kymmenenneksen hoomer-mittaa; hoomerin mukaan määrättäköön kumpaisenkin suuruus.'),
(1690604,58,26,45,12,'Sekelissä olkoon kaksikymmentä geeraa; miina olkoon teillä kaksikymmentä sekeliä, kaksikymmentäviisi sekeliä, viisitoista sekeliä.'),
(1690605,58,26,45,13,'Tämä on anti, joka teidän on annettava: kuudennes eefaa nisuhoomerista ja kuudennes eefaa ohrahoomerista;'),
(1690606,58,26,45,14,'öljyn määrä bat-mitasta öljyä: kymmenennes batia koor-mitasta - kymmenestä batista, hoomerista - sillä hoomer on kymmenen batia;'),
(1690607,58,26,45,15,'pikkukarjasta: kahdestasadasta yksi lammas Israelin runsasvetisiltä laitumilta ruokauhriksi, polttouhriksi ja yhteysuhriksi, että voitaisiin toimittaa heille sovitus, sanoo Herra, Herra.'),
(1690608,58,26,45,16,'Kaikki maan kansa on velvoitettu tähän antiin Israelin ruhtinaalle.'),
(1690609,58,26,45,17,'Mutta ruhtinas toimittakoon polttouhrit, ruokauhrin ja juomauhrin juhlina, uusinakuina ja sapatteina, kaikkina Israelin heimon juhla-aikoina; hän uhratkoon syntiuhrin, ruokauhrin, polttouhrin ja yhteysuhrin toimittaakseen sovituksen Israelin heimolle.'),
(1690610,58,26,45,18,'Näin sanoo Herra, Herra: Ota ensimmäisessä kuussa, kuukauden ensimmäisenä päivänä virheetön mullikka ja puhdista pyhäkkö.'),
(1690611,58,26,45,19,'Ja pappi ottakoon syntiuhrin verta ja sivelköön sitä temppelin ovenpieliin ja alttarin välireunan neljään kulmaan ja sisemmän esipihan portin ovenpieliin.'),
(1690612,58,26,45,20,'Samoin tee kuukauden seitsemäntenä päivänä sen varalta, että joku olisi erehdyksestä tai tietämättömyydestä rikkonut. Ja niin te toimitatte temppelin sovituksen.'),
(1690613,58,26,45,21,'Ensimmäisessä kuussa, kuukauden neljäntenätoista päivänä, on teillä pääsiäinen. Se on seitsenpäiväinen juhla. Syötäköön silloin happamatonta leipää.'),
(1690614,58,26,45,22,'Sinä päivänä uhratkoon ruhtinas omasta puolestansa ja maan kaiken kansan puolesta mullikan syntiuhriksi.'),
(1690615,58,26,45,23,'Ja seitsemänä juhlapäivänä hän uhratkoon polttouhriksi Herralle seitsemän mullikkaa ja seitsemän oinasta, virheettömiä, joka päivä seitsemänä päivänä, ja syntiuhriksi kauriin joka päivä.'),
(1690616,58,26,45,24,'Ja ruokauhriksi hän uhratkoon eefa-mitan mullikkaa ja eefa-mitan oinasta kohti sekä öljyä hiin-mitan eefaa kohti.'),
(1690617,58,26,45,25,'Seitsemännessä kuussa, kuukauden viidentenätoista päivänä, juhlana, hän uhratkoon samalla tavoin - niin seitsemänä päivänä - samankaltaisen syntiuhrin, polttouhrin ja ruokauhrin sekä saman määrän öljyä."'),
(1690618,58,26,46,1,'"Näin sanoo Herra, Herra: Sisemmän esipihan portti, se, joka antaa itään päin, olkoon suljettuna kuusi työpäivää. Mutta sapatinpäivänä se avattakoon; myös avattakoon se uudenkuun päivänä.'),
(1690619,58,26,46,2,'Silloin tulkoon ruhtinas porttieteisen kautta ulkoa ja asettukoon portin ovenpieleen; ja kun papit uhraavat hänen polttouhriansa ja yhteysuhriansa, niin hän kumartaen rukoilkoon portin kynnyksellä ja menköön sitten ulos. Mutta porttia älköön suljettako ennen iltaa.'),
(1690620,58,26,46,3,'Ja maan kansa kumartaen rukoilkoon sen portin ovella sapatteina ja uusinakuina Herran edessä.'),
(1690621,58,26,46,4,'Ja polttouhrina, joka ruhtinaan on uhrattava Herralle sapatinpäivänä, olkoon: kuusi virheetöntä karitsaa ja virheetön oinas;'),
(1690622,58,26,46,5,'ja ruokauhrina: eefa-mitta oinasta kohti, mutta ruokauhrina karitsoita kohti se, mitä hän voi ja tahtoo antaa, ynnä hiin-mitta öljyä eefaa kohti.'),
(1690623,58,26,46,6,'Uudenkuun päivänä olkoon polttouhrina: virheetön mullikka, kuusi karitsaa ja oinas, virheettömiä;'),
(1690624,58,26,46,7,'ja ruokauhrina hän uhratkoon eefan mullikkaa kohti ja eefan oinasta kohti sekä karitsoita kohti sen, mitä hän saa hankituksi, ynnä öljyä hiin-mitan eefaa kohti.'),
(1690625,58,26,46,8,'Ja kun ruhtinas tulee, niin tulkoon porttieteisen kautta ja menköön ulos samaa tietä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690626,58,26,46,9,'Mutta kun maan kansa tulee juhlina Herran eteen, niin se, joka pohjoisportin kautta tuli kumartaen rukoilemaan, menköön ulos eteläportin kautta, ja joka tuli eteläportin kautta, se menköön ulos pohjoisportin kautta; älköön kenkään palatko sen portin kautta, josta tuli, vaan menköön ulos vastakkaisesta.'),
(1690627,58,26,46,10,'Ja ruhtinas tulkoon heidän joukossansa, kun he tulevat, ja menköön ulos, kun he menevät.'),
(1690628,58,26,46,11,'Juhlina ja juhla-aikoina olkoon ruokauhri: eefa mullikkaa kohti ja eefa oinasta kohti sekä karitsoita kohti se, mitä mikin voi ja tahtoo antaa, ynnä öljyä hiin-mitta eefaa kohti.'),
(1690629,58,26,46,12,'Milloin ruhtinas uhraa vapaaehtoisia lahjoja, polttouhrin tai yhteysuhrin vapaaehtoisena lahjana Herralle, avattakoon hänelle portti, joka antaa itään päin, ja hän uhratkoon polttouhrinsa sekä yhteysuhrinsa samoin, kuin hän uhraa sapatinpäivänä, ja menköön ulos; ja hänen mentyänsä suljettakoon portti.'),
(1690630,58,26,46,13,'Uhraa vuoden vanha virheetön karitsa joka päivä polttouhriksi Herralle: uhraa se joka aamu.'),
(1690631,58,26,46,14,'Ja sen lisäksi uhraa ruokauhriksi joka aamu kuudennes eefaa ynnä öljyä kolmannes hiin-mittaa lestyjen jauhojen kostuttamiseksi. Tämä on ruokauhri Herralle - ikuinen, pysyvä säädös.'),
(1690632,58,26,46,15,'Niin uhratkaa joka aamu karitsa, ruokauhri ja öljy jokapäiväiseksi polttouhriksi.'),
(1690633,58,26,46,16,'Näin sanoo Herra, Herra: Jos ruhtinas antaa jollekin pojistansa lahjan, on se tämän perintöosa. Se on tuleva hänen pojillensa: se on perintöosana heidän omaisuuttansa.'),
(1690634,58,26,46,17,'Mutta jos hän antaa lahjan perintöosastaan jollekin palvelijoistansa, olkoon se tämän omana vapautusvuoteen saakka, mutta sitten tulkoon takaisin ruhtinaalle: sehän on hänen perintöosaansa ja on tuleva hänen pojilleen.'),
(1690635,58,26,46,18,'Älköönkä ruhtinas ottako kansan perintöosia, niin että sortaisi heitä pois heidän perintömaaltansa. Omasta perintömaastaan hän antakoon perintöosia pojillensa, ettei kukaan minun kansastani tulisi häädetyksi pois omalta perintömaaltansa."'),
(1690636,58,26,46,19,'Sitten hän vei minut siitä sisäänkäytävästä, joka oli portin sivuseinämällä, niiden kammioiden luo, jotka olivat pyhitettyjä papeille ja jotka antoivat pohjoiseen päin. Ja katso, siellä oli eräs paikka kauimpana länttä kohti.'),
(1690637,58,26,46,20,'Ja hän sanoi minulle: "Tämä on paikka, missä pappien on keitettävä vikauhri ja syntiuhri sekä leivottava ruokauhri, etteivät veisi ulos sitä ulompaan esipihaan ja siten tulisi pyhittäneeksi kansaa".'),
(1690638,58,26,46,21,'Sitten hän vei minut ulompaan esipihaan ja johdatti minut esipihan neljän nurkkauksen ohitse, ja katso, esipihan joka nurkkauksessa oli piha.'),
(1690639,58,26,46,22,'Esipihan neljässä nurkkauksessa oli suljetut pihat, neljänkymmenen pituiset ja kolmenkymmenen levyiset; nämä neljä nurkka-alaa olivat yhtä suuret.'),
(1690640,58,26,46,23,'Ja niissä neljässä oli ympärinsä kivikehä, ja alas kivikehään oli tehty keittoliesiä ympärinsä.'),
(1690641,58,26,46,24,'Ja hän sanoi minulle: "Nämä ovat keittäjäin suojat, joissa temppelipalvelijat keittävät kansan teurasuhrit".'),
(1690642,58,26,47,1,'Sitten hän vei minut takaisin temppelin ovelle. Ja katso, vettä kumpusi temppelin kynnyksen alta itään päin, sillä temppelin etusivu oli itää kohti. Ja vesi juoksi alas temppelin oikeanpuolisen sivuseinämän alitse, alttarin eteläpuolitse.'),
(1690643,58,26,47,2,'Sitten hän toi minut ulos pohjoisportin kautta ja kierrätti minut ulkopuolitse ulkoportille, joka antoi itää kohden; ja katso, vesi virtasi oikeanpuoliselta sivuseinämältä päin.'),
(1690644,58,26,47,3,'Mennessänsä itää kohti mies, mittanuora kädessään, mittasi tuhat kyynärää ja antoi minun käydä veden poikki: vettä oli nilkkoihin asti.'),
(1690645,58,26,47,4,'Sitten hän mittasi tuhat ja antoi minun käydä veden poikki: vettä oli polviin asti. Sitten hän mittasi tuhat ja antoi minun käydä poikki: vettä oli lanteisiin asti.'),
(1690646,58,26,47,5,'Sitten hän mittasi tuhat: tuli virta, jonka poikki minä en voinut käydä, sillä vesi nousi uimavedeksi, virraksi, josta ei voinut käydä poikki.'),
(1690647,58,26,47,6,'Niin hän kysyi minulta: "Oletko nähnyt, ihmislapsi?" ja kuljetti minua ja toi takaisin pitkin virran rantaa.'),
(1690648,58,26,47,7,'Mutta kun minä tulin takaisin, niin katso: virran rannalla kasvoi hyvin paljon puita molemmilla puolin.'),
(1690649,58,26,47,8,'Ja hän sanoi minulle: "Nämä vedet juoksevat itäiselle alueelle, virtaavat alas Aromaahan ja tulevat mereen; niiden jouduttua mereen vesi siinä paranee.'),
(1690650,58,26,47,9,'Ja kaikki elolliset, kaikki, jotka liikkuvat, virkoavat elämään kaikkialla, mihin tämä kaksoisvirta tulee. Ja kaloja on oleva hyvin paljon; sillä kun nämä vedet sinne tulevat ja vesi paranee, niin kaikki virkoaa elämään, minne vain virta tulee.'),
(1690651,58,26,47,10,'Ja kalastajia seisoo sen rannalla. Een-Gedistä Een-Eglaimiin asti se on oleva yhtä verkkoapajaa. Siinä on kaikenlaisia kaloja, aivan kuin suuren meren kaloja, hyvin paljon.'),
(1690652,58,26,47,11,'Sen rämeet ja lätäköt eivät parane: ne jätetään suolan valtaan.'),
(1690653,58,26,47,12,'Mutta virran varrella, sen molemmilla rannoilla, kasvaa kaikkinaisia hedelmäpuita. Niistä eivät lakastu lehdet eivätkä lopu hedelmät: joka kuukausi ne kantavat tuoreet hedelmät, sillä niitten vedet juoksevat pyhäköstä, ja niitten hedelmät ovat ravitsevaiset ja niitten lehdet parantavaiset.'),
(1690654,58,26,47,13,'Näin sanoo Herra, Herra: Tämä on raja, jonka mukaan teidän on jaettava maa perintöosiksi kahdelletoista Israelin sukukunnalle - Joosef saakoon kaksi osaa -.'),
(1690655,58,26,47,14,'Ja te saatte siitä perintöosan jokainen kohdaltansa; sillä minä olen kättä kohottaen luvannut antaa sen teidän isillenne, ja niin tämä maa tulee teille perintöosaksi.'),
(1690656,58,26,47,15,'Tämä on maan pohjoispuolinen raja: Suuresta merestä Hetlonin tietä siihen asti, mistä mennään Sedadiin.'),
(1690657,58,26,47,16,'Hamat, Beerota, Sibraim, joka on Damaskon alueen ja Hamatin alueen välissä, keskimmäinen Haaser, joka on Hauranin rajalla;'),
(1690658,58,26,47,17,'ja näin menee raja merestä Hasar-Eenoniin - Damaskon alue jää pohjoiseen ja pohjoiseen myös Hamatin alue. Tämä on pohjoispuoli.'),
(1690659,58,26,47,18,'Sitten itäpuoli: Hauranin ja Damaskon välistä sekä Gileadin ja Israelin maan välistä, Jordania pitkin. Mitatkaa se rajasta Idänmereen. Tämä on itäpuoli.'),
(1690660,58,26,47,19,'Sitten eteläpuoli, päivään päin: Taamarista Meriban veteen, joka on Kaadeksessa, Puroon ja Suureen mereen. Tämä on päivänpuoli, etelään päin.'),
(1690661,58,26,47,20,'Sitten länsipuoli: Suuri meri rajasta sen paikan kohdalle, mistä mennään Hamatiin. Tämä on länsipuoli.'),
(1690662,58,26,47,21,'Jakakaa tämä maa keskenänne Israelin sukukuntien mukaan.'),
(1690663,58,26,47,22,'Ja arpokaa se perintöosiksi itsellenne ja muukalaisille, jotka asuvat teidän keskuudessanne ja ovat synnyttäneet lapsia teidän keskuudessanne. Olkoot he teille saman arvoisia kuin maassa syntyneet israelilaiset: he saakoot arvalla perintöosan Israelin sukukuntain keskuudessa teidän kanssanne.'),
(1690664,58,26,47,23,'Missä sukukunnassa muukalainen asuu, siinä antakaa hänelle perintöosa, sanoo Herra, Herra."'),
(1690665,58,26,48,1,'"Ja nämä ovat sukukuntien nimet: Pohjois-äärellä, pitkin Hetlonin tien vartta siihen asti, mistä mennään Hamatiin, ja siitä Hasar-Eenaniin - Damaskon alue jää pohjoiseen Hamatin sivulle -; tämä tulee hänelle idän puolelta lännen puolelle asti: Daan, yksi osa.'),
(1690666,58,26,48,2,'Daanin alueen sivussa, idän puolelta lännen puolelle asti: Asser, yksi osa.'),
(1690667,58,26,48,3,'Asserin alueen sivussa, idän puolelta lännen puolelle asti: Naftali, yksi osa.'),
(1690668,58,26,48,4,'Naftalin alueen sivussa, idän puolelta lännen puolelle asti: Manasse, yksi osa.'),
(1690669,58,26,48,5,'Manassen alueen sivussa, idän puolelta lännen puolelle asti: Efraim, yksi osa.'),
(1690670,58,26,48,6,'Efraimin alueen sivussa, idän puolelta lännen puolelle asti: Ruuben, yksi osa.'),
(1690671,58,26,48,7,'Ruubenin alueen sivussa, idän puolelta lännen puolelle asti: Juuda, yksi osa.'),
(1690672,58,26,48,8,'Juudan alueen sivussa, idän puolelta lännen puolelle asti, on oleva se antimaa, joka teidän on annettava, kahtakymmentäviittä tuhatta leveä ja niin pitkä kuin yksi sukukuntaosa idän puolelta lännen puolelle; ja pyhäkkö olkoon sen keskellä.'),
(1690673,58,26,48,9,'Antimaa, joka teidän on annettava Herralle, olkoon kahtakymmentäviittä tuhatta pitkä ja kahtakymmentä tuhatta leveä.'),
(1690674,58,26,48,10,'Ja pyhää antimaata tulkoon seuraaville: papeille pohjoisesta kahtakymmentäviittä tuhatta, lännestä kymmentätuhatta leveälti, idästä kymmentätuhatta leveälti ja etelästä kahtakymmentäviittä tuhatta pitkälti; ja Herran pyhäkkö olkoon siinä keskellä.'),
(1690675,58,26,48,11,'Papeille, niille Saadokin jälkeläisistä, jotka ovat pyhitettyjä, jotka ovat hoitaneet minulle suoritettavat tehtävät ja jotka eivät eksyneet, niinkuin leeviläiset eksyivät, silloin kun israelilaiset joutuivat eksyksiin,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690676,58,26,48,12,'heille se tulkoon verona antimaasta, korkeasti-pyhänä; tulkoon leeviläisten alueen vierestä.'),
(1690677,58,26,48,13,'Leeviläiset saakoot samanlaisen alueen kuin papit, kahtakymmentäviittä tuhatta pitkän ja kymmentätuhatta leveän. Koko pituus olkoon kaksikymmentäviisi tuhatta ja leveys kaksikymmentä tuhatta.'),
(1690678,58,26,48,14,'Älkööt he myykö siitä mitään, älköönkä parasta maata vaihdettako tai luovutettako, sillä se on pyhitetty Herralle.'),
(1690679,58,26,48,15,'Mutta viittätuhatta leveä maa, mikä jää yli kahdenkymmenenviiden tuhannen sivusta, on kaupungin yhteisomaisuutta asumuksia ja avointa tilaa varten; ja kaupunki olkoon sen keskellä.'),
(1690680,58,26,48,16,'Ja nämä olkoot sen mitat: pohjoispuoli neljätuhatta viisisataa, eteläpuoli neljätuhatta viisisataa, itäpuoli neljätuhatta viisisataa ja länsipuoli neljätuhatta viisisataa.'),
(1690681,58,26,48,17,'Ja kaupungilla olkoon avoin tila: pohjoiseen päin kaksisataa viisikymmentä, etelään päin kaksisataa viisikymmentä, itään päin kaksisataa viisikymmentä ja länteen päin kaksisataa viisikymmentä.'),
(1690682,58,26,48,18,'Mutta niin pitkälti kuin jää yli pyhän antimaan viereltä, kymmenentuhatta itään päin ja kymmenentuhatta länteen päin, se olkoon pyhän antimaan vierellä, ja sen sato tulkoon leiväksi kaupungin työmiehille;'),
(1690683,58,26,48,19,'ja sitä viljelkööt kaupungin työmiehet kaikista Israelin sukukunnista.'),
(1690684,58,26,48,20,'Koko antimaa on kahtakymmentäviittä tuhatta ja kahtakymmentäviittä tuhatta. Neliönmuotoisena on teidän annettava pyhä antimaa ynnä kaupungin perintömaa.'),
(1690685,58,26,48,21,'Mikä jää yli, se tulkoon ruhtinaalle: molemmilta puolilta pyhää antimaata ja kaupungin perintömaata, niitten kahdenkymmenenviiden tuhannen - antimaan - sivusta itärajaan asti, ynnä länteen päin niitten kahdenkymmenen viiden tuhannen sivusta länsirajaan asti, on ruhtinaalle tuleva sukukuntaosia vastaava maa; ja pyhä antimaa sekä temppelipyhäkkö olkoot sen keskellä.'),
(1690686,58,26,48,22,'Leeviläisten perintömaasta ja kaupungin perintömaasta asti, jotka ovat ruhtinaalle tulevan maan keskellä, tulee ruhtinaalle se, mikä on Juudan alueen ja Benjaminin alueen välissä.'),
(1690687,58,26,48,23,'Sitten muut sukukunnat: Idän puolelta lännen puolelle asti: Benjamin, yksi osa.'),
(1690688,58,26,48,24,'Benjaminin alueen sivussa, idän puolelta lännen puolelle asti: Simeon, yksi osa.'),
(1690689,58,26,48,25,'Simeonin alueen sivussa, idän puolelta lännen puolelle asti: Isaskar, yksi osa.'),
(1690690,58,26,48,26,'Isaskarin alueen sivussa, idän puolelta lännen puolelle asti: Sebulon, yksi osa.'),
(1690691,58,26,48,27,'Sebulonin alueen sivussa, idän puolelta lännen puolelle asti: Gaad, yksi osa.'),
(1690692,58,26,48,28,'Ja Gaadin alueen sivua, etelän puolella, päivään päin, menee raja Taamarista Meriban veteen, Kaadekseen, Puroon ja Suureen mereen.'),
(1690693,58,26,48,29,'Tämä on maa, joka teidän on arvottava perintöosiksi Israelin sukukunnille, ja nämä ovat heidän osuutensa, sanoo Herra, Herra.'),
(1690694,58,26,48,30,'Ja nämä ovat kaupungin uloskäytävät: Pohjoispuolella on mitta neljätuhatta viisisataa.'),
(1690695,58,26,48,31,'Ja kaupungin portteja, jotka ovat nimitetyt Israelin sukukuntain mukaan, on pohjoisessa kolme: Ruubenin portti yksi, Juudan portti toinen ja Leevin portti kolmas.'),
(1690696,58,26,48,32,'Itäpuolella: neljätuhatta viisisataa, ja portteja kolme: Joosefin portti yksi, Benjaminin portti toinen ja Daanin portti kolmas.'),
(1690697,58,26,48,33,'Eteläpuolella on mitta neljätuhatta viisisataa, ja portteja kolme: Simeonin portti yksi, Isaskarin portti toinen ja Sebulonin portti kolmas.'),
(1690698,58,26,48,34,'Länsipuolella: neljätuhatta viisisataa, ja portteja kolme: Gaadin portti yksi, Asserin portti toinen ja Naftalin portti kolmas.'),
(1690699,58,27,1,1,'Joojakimin, Juudan kuninkaan, kolmantena hallitusvuotena tuli Nebukadnessar, Baabelin kuningas, Jerusalemin edustalle ja piiritti sitä.'),
(1690700,58,27,1,2,'Ja Herra antoi hänen käsiinsä Joojakimin, Juudan kuninkaan, sekä osan Jumalan huoneen astioita, ja hän vei ne Sinearin maahan, jumalansa huoneeseen. Ja hän vei astiat jumalansa aarrekammioon.'),
(1690701,58,27,1,3,'Ja kuningas käski ylimmäisen hoviherransa Aspenaan tuoda israelilaisia poikia, jotka olivat kuninkaallista sukua tai ylimysperheistä,'),
(1690702,58,27,1,4,'nuorukaisia, joissa ei ollut mitään virheä ja jotka olivat kaunismuotoisia, jotka kykenivät käsittämään kaikkea viisautta, olivat terävä-älyisiä ja hyväoppisia ja jotka olisivat kelvollisia palvelemaan kuninkaan hovissa; heille hänen tuli opettaa kaldealaisten kirjoitusta ja kieltä.'),
(1690703,58,27,1,5,'Ja kuningas määräsi heille jokapäiväiseksi ravinnoksi ruokaa kuninkaan pöydästä ja viiniä, jota hän itse joi. Niin heitä oli kasvatettava kolme vuotta, ja niiden kuluttua heidän tuli astua kuninkaan palvelukseen.'),
(1690704,58,27,1,6,'Heidän joukossaan olivat juutalaiset pojat Daniel, Hananja, Miisael ja Asarja.'),
(1690705,58,27,1,7,'Ja hoviherrain päällikkö pani heille nimet: Danielille hän pani nimen Beltsassar, Hananjalle nimen Sadrak, Miisaelille nimen Meesak ja Asarjalle nimen Abednego.'),
(1690706,58,27,1,8,'Mutta Daniel päätti lujasti olla saastuttamatta itseään kuninkaan pöydän ruualla ja viinillä, jota tämä joi, ja anoi hoviherrain päälliköltä, ettei hänen tarvitsisi itseään saastuttaa.'),
(1690707,58,27,1,9,'Ja Jumala salli Danielin saada suosion ja armon hoviherrain päällikön edessä.'),
(1690708,58,27,1,10,'Mutta hoviherrain päällikkö sanoi Danielille: "Minä pelkään, että jos herrani, kuningas, joka on määrännyt teidän ruokanne ja juomanne, huomaa teidän kasvonne laihemmiksi kuin muiden ikäistenne nuorukaisten, niin te saatatte minun pääni vaaraan kuninkaan edessä".'),
(1690709,58,27,1,11,'Silloin Daniel sanoi katsastajalle, jonka hoviherrain päällikkö oli määrännyt pitämään silmällä Danielia, Hananjaa, Miisaelia ja Asarjaa:'),
(1690710,58,27,1,12,'"Koettele palvelijoitasi kymmenen päivää, ja annettakoon meille vihannesruokaa syödäksemme ja vettä juodaksemme.'),
(1690711,58,27,1,13,'Sitten tarkastettakoon sinun edessäsi, miltä me näytämme ja miltä näyttävät ne nuorukaiset, jotka syövät kuninkaan pöydän ruokaa; ja tee sitten palvelijoillesi sen mukaan, mitä silloin havaitset."'),
(1690712,58,27,1,14,'Ja hän kuuli heitä tässä asiassa ja koetteli heitä kymmenen päivää.'),
(1690713,58,27,1,15,'Mutta kymmenen päivän kuluttua havaittiin heidät muodoltaan kauniimmiksi ja ruumiiltaan lihavammiksi kuin yksikään niistä nuorukaisista, jotka söivät kuninkaan pöydän ruokaa.'),
(1690714,58,27,1,16,'Ja niin katsastaja jätti pois heille määrätyn ruuan ja heidän juotavansa viinin ja antoi heille vihannesruokaa.'),
(1690715,58,27,1,17,'Ja Jumala antoi näille neljälle nuorukaiselle taidon käsittää kaikki kirjoitukset ja kaiken viisauden; ja Daniel ymmärsi myös kaikkinaiset näyt ja unet.'),
(1690716,58,27,1,18,'Kun sitten ne päivät olivat kuluneet, joiden jälkeen kuningas oli käskenyt tuoda heidät esiin, niin hoviherrain päällikkö toi heidät Nebukadnessarin eteen.'),
(1690717,58,27,1,19,'Kun nyt kuningas keskusteli heidän kanssaan, ei ollut heidän joukossansa yhtäkään Danielin, Hananjan, Miisaelin ja Asarjan vertaista. Niin he tulivat kuninkaan palvelijoiksi.'),
(1690718,58,27,1,20,'Ja kaikissa viisautta ja ymmärrystä vaativissa asioissa, joita kuningas heiltä kyseli, hän havaitsi heidät kymmentä vertaa etevämmiksi kuin kaikki tietäjät ja noidat, mitä koko hänen valtakunnassaan oli.'),
(1690719,58,27,1,21,'Ja Daniel oli siellä kuningas Kooreksen ensimmäiseen vuoteen asti.'),
(1690720,58,27,2,1,'Nebukadnessarin toisena hallitusvuotena näki Nebukadnessar unia, ja hänen mielensä oli levoton eikä hän enää saanut unta.'),
(1690721,58,27,2,2,'Silloin kuningas käski kutsua tietäjät ja noidat, velhot ja kaldealaiset ilmoittamaan kuninkaalle hänen unensa; ja he tulivat ja astuivat kuninkaan eteen.'),
(1690722,58,27,2,3,'Ja kuningas sanoi heille: "Minä olen nähnyt unen, ja mieleni on levoton, kunnes saan tietää sen unen.'),
(1690723,58,27,2,4,'Silloin kaldealaiset puhuivat kuninkaalle araminkielellä: "Eläköön kuningas iankaikkisesti! Sano uni palvelijoillesi, niin me ilmoitamme sen selityksen."'),
(1690724,58,27,2,5,'Kuningas vastasi ja sanoi kaldealaisille: "Tämä minun sanani on peruuttamaton: Ellette ilmoita minulle unta ja sen selitystä, niin teidät hakataan kappaleiksi ja teidän talonne tehdään soraläjiksi.'),
(1690725,58,27,2,6,'Mutta jos te ilmoitatte minulle unen ja sen selityksen, niin te saatte minulta lahjoja ja antimia ja suuren kunnian. Sentähden ilmoittakaa minulle uni ja sen selitys."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690726,58,27,2,7,'He vastasivat toistamiseen ja sanoivat: "Kuningas sanokoon unen palvelijoilleen, niin me ilmoitamme sen selityksen".'),
(1690727,58,27,2,8,'Kuningas vastasi ja sanoi: "Minä huomaan selvästi, että te vain koetatte voittaa aikaa, koska näette peruuttamattomaksi tämän minun sanani,'),
(1690728,58,27,2,9,'että ellette ilmoita minulle unta, on teillä edessä vain yksi tuomio. Sillä te olette sopineet keskenänne, että puhutte minun edessäni valheellista ja turmiollista puhetta toivoen, että aika muuttuu. Sentähden sanokaa minulle uni; silloin minä tiedän, että te osaatte ilmoittaa minulle selityksen siihen."'),
(1690729,58,27,2,10,'Kaldealaiset vastasivat kuninkaan edessä ja sanoivat: "Ei ole maan päällä ihmistä, joka kykenisi selittämään sen, mitä kuningas sanoi. Eikä yksikään suuri ja voimallinen kuningas ole koskaan vaatinut tämänkaltaista asiaa keneltäkään tietäjältä, noidalta tai kaldealaiselta.'),
(1690730,58,27,2,11,'Sillä asia, jota kuningas vaatii, on vaikea, eikä ole ketään, joka voisi sen kuninkaalle selittää, paitsi jumalat, joiden asuinsija ei ole ihmisten tykönä."'),
(1690731,58,27,2,12,'Tästä kuningas suuttui ja julmistui kovin ja käski tappaa kaikki Baabelin viisaat.'),
(1690732,58,27,2,13,'Kun tästä oli käsky annettu ja viisaat piti tapettaman, etsittiin Danielia ja hänen tovereitaan tapettaviksi.'),
(1690733,58,27,2,14,'Silloin Daniel antoi viisaan ja taitavan vastauksen Arjokille, kuninkaan henkivartioväen päällikölle, joka oli lähtenyt tappamaan Baabelin viisaita.'),
(1690734,58,27,2,15,'Hän vastasi ja sanoi Arjokille, kuninkaan päällikölle: "Miksi on kuningas antanut niin ankaran käskyn?" Silloin Arjok kertoi Danielille asian.'),
(1690735,58,27,2,16,'Niin Daniel meni palatsiin ja pyysi kuningasta antamaan hänelle aikaa, että hän saisi ilmoittaa kuninkaalle selityksen.'),
(1690736,58,27,2,17,'Sitten Daniel meni kotiinsa ja kertoi asian tovereillensa Hananjalle, Miisaelille ja Asarjalle'),
(1690737,58,27,2,18,'kehoittaen heitä rukoilemaan armoa taivaan Jumalalta tämän salatun asian tähden, ettei Danielia ja hänen tovereitansa tapettaisi muiden Baabelin viisaitten kanssa.'),
(1690738,58,27,2,19,'Silloin salaisuus ilmoitettiin Danielille yöllisessä näyssä. Niin Daniel kiitti taivaan Jumalaa.'),
(1690739,58,27,2,20,'Daniel lausui ja sanoi: "Olkoon Jumalan nimi kiitetty iankaikkisesta iankaikkiseen, sillä hänen on viisaus ja voima.'),
(1690740,58,27,2,21,'Hän muuttaa ajat ja hetket, hän syöksee kuninkaat vallasta ja korottaa kuninkaat valtaan, hän antaa viisaille viisauden ja taidollisille ymmärryksen.'),
(1690741,58,27,2,22,'Hän paljastaa syvät ja salatut asiat, hän tietää, mitä pimeydessä on, ja valkeus asuu hänen tykönänsä.'),
(1690742,58,27,2,23,'Sinua, minun isieni Jumala, minä kiitän ja ylistän siitä, että olet antanut minulle viisauden ja voiman ja että nyt annoit minun tietää, mitä me sinulta rukoilimme. Sillä sinä annoit meidän tietää kuninkaan asian."'),
(1690743,58,27,2,24,'Sitten Daniel meni Arjokin tykö, jolla oli kuninkaan määräys tappaa Baabelin viisaat. Hän meni ja sanoi hänelle näin: "Älä tapa Baabelin viisaita; vie minut kuninkaan eteen, niin minä ilmoitan kuninkaalle selityksen".'),
(1690744,58,27,2,25,'Silloin Arjok vei kiiruusti Danielin kuninkaan eteen ja sanoi tälle näin: "Minä olen löytänyt juutalaisten pakkosiirtolaisten joukosta miehen, joka ilmoittaa kuninkaalle selityksen".'),
(1690745,58,27,2,26,'Kuningas vastasi ja sanoi Danielille, jonka nimenä oli Beltsassar: "Voitko sinä ilmoittaa minulle unen, jonka minä näin, ja sen selityksen?"'),
(1690746,58,27,2,27,'Daniel vastasi kuninkaalle ja sanoi: "Salaisuutta, jonka kuningas tahtoo tietää, eivät viisaat, noidat, tietäjät eivätkä tähtienselittäjät voi ilmoittaa kuninkaalle.'),
(1690747,58,27,2,28,'Mutta on Jumala taivaassa; hän paljastaa salaisuudet ja ilmoittaa kuningas Nebukadnessarille, mitä on tapahtuva aikojen lopussa. Tämä on sinun unesi, sinun pääsi näky, joka sinulla oli vuoteessasi.'),
(1690748,58,27,2,29,'Kun sinä, kuningas, olit vuoteessasi, nousi mieleesi ajatus, mitä tämän jälkeen on tapahtuva; ja hän, joka paljastaa salaisuudet, ilmoitti sinulle, mitä tapahtuva on.'),
(1690749,58,27,2,30,'Ja tämä salaisuus on paljastettu minulle, ei oman viisauteni voimasta, ikäänkuin minulla olisi sitä enemmän kuin kenelläkään muulla ihmisellä, vaan sentähden että selitys ilmoitettaisiin kuninkaalle ja sinä saisit selville sydämesi ajatukset.'),
(1690750,58,27,2,31,'Sinä näit, kuningas, katso, oli iso kuvapatsas. Se kuvapatsas oli suuri, ja sen kirkkaus oli ylenpalttinen. Se seisoi sinun edessäsi, ja se oli hirvittävä nähdä.'),
(1690751,58,27,2,32,'Kuvan pää oli parasta kultaa, sen rinta ja käsivarret hopeata, sen vatsa ja lanteet vaskea.'),
(1690752,58,27,2,33,'Sen sääret olivat rautaa, sen jalat osaksi rautaa, osaksi savea.'),
(1690753,58,27,2,34,'Sinun sitä katsellessasi irtautui kivilohkare - ei ihmiskäden voimasta - ja iski kuvapatsasta jalkoihin, jotka olivat rautaa ja savea, ja murskasi ne.'),
(1690754,58,27,2,35,'Silloin musertuivat yhdellä haavaa rauta, savi, vaski, hopea ja kulta, ja niiden kävi kuin akanain kesäisillä puimatantereilla: tuuli vei ne, eikä niistä löydetty jälkeäkään. Mutta kivestä, joka oli kuvapatsaan murskannut, tuli suuri vuori, ja se täytti koko maan.'),
(1690755,58,27,2,36,'Tämä oli se uni, ja nyt sanomme kuninkaalle sen selityksen.'),
(1690756,58,27,2,37,'Sinä, kuningas, olet kuningasten kuningas, jolle taivaan Jumala on antanut vallan, voiman, väkevyyden ja kunnian'),
(1690757,58,27,2,38,'ja jonka käteen hän on antanut ihmiset, missä ikinä heitä asuu, ja kedon eläimet ja taivaan linnut, asettaen sinut kaikkien niiden valtiaaksi: sinä olet se kultainen pää.'),
(1690758,58,27,2,39,'Mutta sinun jälkeesi nousee toinen valtakunta, joka on halvempi kuin sinun; ja sitten kolmas valtakunta, joka on vaskea ja joka hallitsee kaikkea maata.'),
(1690759,58,27,2,40,'Ja neljäs valtakunta on tuleva, luja kuin rauta; niinkuin rauta musertaa ja särkee kaiken, niinkuin rauta murskaa, niin se on musertava ja murskaava ne kaikki.'),
(1690760,58,27,2,41,'Ja että sinä näit jalkain ja varvasten olevan osittain savenvalajan savea, osittain rautaa, se merkitsee, että se on oleva hajanainen valtakunta; kuitenkin on siinä oleva raudan lujuutta, niinkuin sinä näit rautaa olevan saven seassa.'),
(1690761,58,27,2,42,'Ja että jalkojen varpaat olivat osaksi rautaa, osaksi savea, se merkitsee, että osa sitä valtakuntaa on oleva luja, osa sitä on oleva hauras.'),
(1690762,58,27,2,43,'Että sinä näit rautaa olevan saven seassa, se merkitsee, että vaikka ne sekaantuvat toisiinsa ihmissiemenellä, ne eivät yhdisty toinen toiseensa, niinkuin ei rautakaan sekaannu saveen.'),
(1690763,58,27,2,44,'Mutta niiden kuningasten päivinä on taivaan Jumala pystyttävä valtakunnan, joka on kukistumaton iankaikkisesti ja jonka valtaa ei toiselle kansalle anneta. Se on musertava kaikki ne muut valtakunnat ja tekevä niistä lopun, mutta se itse on pysyvä iankaikkisesti,'),
(1690764,58,27,2,45,'niinkuin sinä näit, että kivilohkare irtautui vuoresta - ei ihmiskäden voimasta - ja murskasi raudan, vasken, saven, hopean ja kullan. Suuri Jumala on ilmoittanut kuninkaalle, mitä tämän jälkeen on tapahtuva. Ja uni on tosi ja sen selitys luotettava."'),
(1690765,58,27,2,46,'Silloin kuningas Nebukadnessar lankesi kasvoillensa ja kumartui maahan Danielin edessä ja käski uhrata hänelle ruokauhria ja suitsutusta.'),
(1690766,58,27,2,47,'Kuningas vastasi Danielille ja sanoi: "Totisesti on teidän Jumalanne jumalien Jumala ja kuningasten herra ja se, joka paljastaa salaisuudet; sillä sinä olet voinut paljastaa tämän salaisuuden".'),
(1690767,58,27,2,48,'Sitten kuningas korotti Danielin ja antoi hänelle paljon suuria lahjoja ja asetti hänet koko Baabelin maakunnan herraksi ja kaikkien Baabelin viisaitten ylimmäiseksi päämieheksi.'),
(1690768,58,27,2,49,'Ja Danielin anomuksesta kuningas antoi Sadrakin, Meesakin ja Abednegon hoitoon Baabelin maakunnan hallinnon. Mutta Daniel jäi kuninkaan hoviin.'),
(1690769,58,27,3,1,'Kuningas Nebukadnessar teetti kultaisen kuvapatsaan, jonka korkeus oli kuusikymmentä kyynärää ja leveys kuusi kyynärää, ja pystytti sen Duuran lakeudelle Baabelin maakuntaan.'),
(1690770,58,27,3,2,'Ja kuningas Nebukadnessar lähetti kokoamaan satraapit, maaherrat, käskynhaltijat, neuvonantajat, aarteiden hoitajat, lainoppineet, tuomarit ja kaikki muut maakuntain virkamiehet, että he tulisivat sen kuvapatsaan vihkiäisiin, jonka kuningas Nebukadnessar oli pystyttänyt.'),
(1690771,58,27,3,3,'Silloin kokoontuivat satraapit, maaherrat, käskynhaltijat, neuvonantajat, aarteiden hoitajat, lainoppineet, tuomarit ja kaikki muut maakuntain virkamiehet sen kuvapatsaan vihkiäisiin, jonka kuningas Nebukadnessar oli pystyttänyt, ja he asettuivat sen kuvapatsaan eteen, jonka Nebukadnessar oli pystyttänyt.'),
(1690772,58,27,3,4,'Ja kuuluttaja huusi voimallisesti: "Teille, kansat, sukukunnat ja kielet, julistetaan:'),
(1690773,58,27,3,5,'heti kun te kuulette torvien, huilujen, kitarain, harppujen, psalttarien, säkkipillien ja kaikkinaisten muiden soittimien äänen, langetkaa maahan ja kumartaen rukoilkaa kultaista kuvapatsasta, jonka kuningas Nebukadnessar on pystyttänyt.'),
(1690774,58,27,3,6,'Mutta joka ei lankea maahan ja kumarra, se heitetään sillä hetkellä tuliseen pätsiin."'),
(1690775,58,27,3,7,'Sentähden, heti kun kaikki kansat kuulivat torvien, huilujen, kitarain, harppujen, psalttarien, säkkipillien ja kaikkinaisten muiden soittimien äänen, lankesivat kaikki kansat, sukukunnat ja kielet maahan ja kumartaen rukoilivat kultaista kuvapatsasta, jonka kuningas Nebukadnessar oli pystyttänyt.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690776,58,27,3,8,'Silloin astui heti kaldealaisia miehiä esiin syyttämään juutalaisia.'),
(1690777,58,27,3,9,'He lausuivat ja sanoivat kuningas Nebukadnessarille: "Kuningas eläköön iankaikkisesti!'),
(1690778,58,27,3,10,'Sinä, kuningas, olet antanut käskyn, että jokainen, joka kuulee torvien, huilujen, kitarain, harppujen, psalttarien, säkkipillien ja kaikkinaisten muiden soittimien äänen, langetkoon maahan ja kumartaen rukoilkoon kultaista kuvapatsasta,'),
(1690779,58,27,3,11,'ja että joka ei lankea maahan ja kumarra, se heitetään tuliseen pätsiin.'),
(1690780,58,27,3,12,'On juutalaisia miehiä, joiden hoitoon sinä olet antanut Baabelin maakunnan hallinnon, Sadrak, Meesak ja Abednego: nämä miehet eivät välitä sinun käskystäsi, kuningas; he eivät palvele sinun jumaliasi eivätkä kumartaen rukoile kultaista kuvapatsasta, jonka sinä olet pystyttänyt."'),
(1690781,58,27,3,13,'Silloin Nebukadnessar vihan vimmassa käski tuoda Sadrakin, Meesakin ja Abednegon. Kun nämä miehet oli tuotu kuninkaan eteen,'),
(1690782,58,27,3,14,'lausui Nebukadnessar ja sanoi heille: "Aivanko tahallanne te, Sadrak, Meesak ja Abednego, ette tahdo palvella minun jumalaani ettekä kumartaen rukoilla kultaista kuvapatsasta, jonka minä olen pystyttänyt?'),
(1690783,58,27,3,15,'Nyt, jos te siinä silmänräpäyksessä, kun kuulette torvien, huilujen, kitarain, harppujen, psalttarien, säkkipillien ja kaikkinaisten muiden soittimien äänen, olette valmiit lankeamaan maahan ja kumartaen rukoilemaan kuvapatsasta, jonka minä olen teettänyt, niin hyvä! Mutta ellette kumarra, niin teidät heti paikalla heitetään tuliseen pätsiin; ja kuka on se jumala, joka pelastaa teidät minun kädestäni?"'),
(1690784,58,27,3,16,'Sadrak, Meesak ja Abednego vastasivat ja sanoivat kuninkaalle: "Nebukadnessar! Ei ole tarpeellista meidän vastata sinulle tähän sanaakaan.'),
(1690785,58,27,3,17,'Jos niin käy, voi meidän Jumalamme kyllä pelastaa meidät tulisesta pätsistä, ja hän pelastaa myös sinun kädestäsi, kuningas.'),
(1690786,58,27,3,18,'Ja vaikka ei pelastaisikaan, niin tiedä se, kuningas, että me emme palvele sinun jumaliasi emmekä kumartaen rukoile kultaista kuvapatsasta, jonka sinä olet pystyttänyt."'),
(1690787,58,27,3,19,'Silloin Nebukadnessar tuli kiukkua täyteen Sadrakia, Meesakia ja Abednegoa kohtaan ja hänen hahmonsa muuttui. Ja hän käski ja sanoi, että pätsi oli kuumennettava seitsemän kertaa kuumemmaksi kuin tavallisesti.'),
(1690788,58,27,3,20,'Ja hän käski sotajoukkonsa väkevimpien miesten sitoa Sadrakin, Meesakin ja Abednegon ja heittää heidät tuliseen pätsiin.'),
(1690789,58,27,3,21,'Silloin nämä sidottiin vaippoineen, takkeineen, päähineineen ja muine vaatteineen ja heitettiin tuliseen pätsiin.'),
(1690790,58,27,3,22,'Koska nyt kuninkaan sana oli niin ankara ja pätsi niin kovin kuumennettu, tappoi tulen liekki ne miehet, jotka veivät ylös Sadrakin, Meesakin ja Abednegon.'),
(1690791,58,27,3,23,'Mutta nämä kolme miestä, Sadrak, Meesak ja Abednego, suistuivat sidottuina tuliseen pätsiin.'),
(1690792,58,27,3,24,'Silloin kuningas Nebukadnessar hämmästyi ja nousi kiiruusti ylös ja lausui hallitusmiehilleen sanoen: "Emmekö heittäneet kolme miestä sidottuina tuleen?" He vastasivat ja sanoivat kuninkaalle: "Totisesti, kuningas!"'),
(1690793,58,27,3,25,'Hän vastasi ja sanoi: "Katso, minä näen neljä miestä kävelevän vapaina tulessa, eivätkä he ole vahingoittuneet, ja neljäs on näöltänsä niinkuin jumalan poika".'),
(1690794,58,27,3,26,'Silloin Nebukadnessar meni tulisen pätsin aukolle, lausui ja sanoi: "Sadrak, Meesak ja Abednego, te korkeimman Jumalan palvelijat, astukaa ulos ja tulkaa tänne". Sadrak, Meesak ja Abednego astuivat silloin ulos tulesta.'),
(1690795,58,27,3,27,'Satraapit, maaherrat, käskynhaltijat ja kuninkaan hallitusmiehet kokoontuivat ja näkivät, ettei tuli ollut voinut mitään näiden miesten ruumiille, etteivät heidän päänsä hiukset olleet kärventyneet eivätkä heidän vaatteensa vioittuneet; eikä heissä tuntunut tulen käryä.'),
(1690796,58,27,3,28,'Silloin Nebukadnessar lausui ja sanoi: "Kiitetty olkoon Sadrakin, Meesakin ja Abednegon Jumala, joka lähetti enkelinsä ja pelasti palvelijansa, jotka häneen turvasivat eivätkä totelleet kuninkaan käskyä, vaan antoivat ruumiinsa alttiiksi, ennemmin kuin palvelivat kumartaen rukoilivat muuta jumalaa kuin omaa Jumalaansa.'),
(1690797,58,27,3,29,'Ja minä annan käskyn, että jokainen, olkoon hän mitä kansaa, kansakuntaa ja kieltä tahansa, joka puhuu pilkaten Sadrakin, Meesakin ja Abednegon Jumalasta, hakattakoon kappaleiksi, ja hänen talonsa tehtäköön soraläjäksi; sillä ei ole muuta jumalaa, joka niin voi pelastaa kuin tämä."'),
(1690798,58,27,3,30,'Sitten kuningas asetti Sadrakin, Meesakin ja Abednegon suureen valtaan Baabelin maakunnassa.'),
(1690799,58,27,3,31,'"Kuningas Nebukadnessar kaikille kansoille, kansakunnille ja kielille, jotka asuvat kaiken maan päällä: suuri olkoon teidän rauhanne!'),
(1690800,58,27,3,32,'Minä olen nähnyt hyväksi ilmoittaa ne tunnusteot ja ihmeet, jotka korkein Jumala on minulle tehnyt.'),
(1690801,58,27,3,33,'Kuinka suuret ovat hänen tunnustekonsa ja kuinka voimalliset hänen ihmeensä! Hänen valtakuntansa on iankaikkinen valtakunta ja hänen valtansa pysyy suvusta sukuun."'),
(1690802,58,27,4,1,'"Minä Nebukadnessar elin rauhassa huoneessani ja onnellisena palatsissani.'),
(1690803,58,27,4,2,'Minä näin unen, ja se peljästytti minut; ja unikuvat, joita minulla oli vuoteessani, minun pääni näyt, kauhistuttivat minut.'),
(1690804,58,27,4,3,'Niin minä annoin käskyn tuoda eteeni kaikki Baabelin viisaat, että he ilmoittaisivat minulle unen selityksen.'),
(1690805,58,27,4,4,'Silloin tulivat tietäjät, noidat, kaldealaiset ja tähtienselittäjät, ja minä kerroin heille unen, mutta he eivät voineet ilmoittaa minulle sen selitystä.'),
(1690806,58,27,4,5,'Mutta viimein tuli minun eteeni Daniel, jonka nimi on minun jumalani nimen mukaan Beltsassar ja jossa on pyhien jumalien henki; ja minä kerroin hänelle unen:'),
(1690807,58,27,4,6,'''Beltsassar, sinä tietäjäin päämies, jossa minä tiedän olevan pyhien jumalien hengen ja jolle mikään salaisuus ei ole liian vaikea! Sano, mitä olivat ne näyt, jotka minä unessani näin, ja mikä on sen selitys.'),
(1690808,58,27,4,7,'Nämä olivat minun pääni näyt, jotka minulla oli vuoteessani. Minä näin: Katso, oli puu keskellä maata, ja sen korkeus oli suuri.'),
(1690809,58,27,4,8,'Puu kasvoi ja vahvistui, niin että sen latva ulottui taivaaseen ja se näkyi kaiken maan ääriin.'),
(1690810,58,27,4,9,'Sen lehvät olivat kauniit ja sen hedelmät suuret, ja siinä oli ravintoa kaikille. Sen alla etsivät varjoa kedon eläimet, ja sen oksilla asuivat taivaan linnut, ja kaikki liha sai siitä ravintonsa.'),
(1690811,58,27,4,10,'Minä näin pääni näyissä, joita minulla oli vuoteessani: katso, pyhä enkeli astui alas taivaasta.'),
(1690812,58,27,4,11,'Hän huusi voimallisesti ja sanoi näin: hakatkaa puu poikki ja karsikaa sen oksat, riipikää sen lehvät ja hajottakaa sen hedelmät. Paetkoot eläimet sen alta ja linnut sen oksilta.'),
(1690813,58,27,4,12,'Mutta sen kanto juurineen jättäkää maahan, rauta- ja vaskikahleissa kedon ruohikkoon. Taivaan kasteesta hän kastukoon, ja niinkuin eläinten olkoon hänen osansa maan ruoho.'),
(1690814,58,27,4,13,'Hänen sydämensä muutetaan, niin ettei se ole ihmisen sydän, ja hänelle annetaan eläimen sydän. Ja niin kulukoon häneltä seitsemän aikaa.'),
(1690815,58,27,4,14,'Tämä on säädetty enkelien päätöksellä, ja niin ovat tästä asiasta pyhät sanoneet, että elävät tietäisivät Korkeimman hallitsevan ihmisten valtakuntaa ja antavan sen, kenelle hän tahtoo, ja asettavan sen päämieheksi ihmisistä halvimman.'''),
(1690816,58,27,4,15,'Tämän unen näin minä, kuningas Nebukadnessar. Ja sinä, Beltsassar, sano sen selitys, koska ei yksikään minun valtakuntani viisaista voi minulle ilmoittaa sen selitystä. Mutta sinä sen voit, sillä sinussa on pyhien jumalien henki."'),
(1690817,58,27,4,16,'Silloin Daniel, jonka nimenä oli Beltsassar, hämmästyi hetkeksi, ja hänen ajatuksensa peljästyttivät häntä. Kuningas lausui ja sanoi: "Beltsassar, älköön uni ja sen selitys sinua peljästyttäkö". Beltsassar vastasi ja sanoi: "Herrani, koskekoon uni sinun vihollisiasi ja sen selitys sinun vastustajiasi.'),
(1690818,58,27,4,17,'Puu, jonka sinä näit ja joka kasvoi ja vahvistui, niin että sen latva ulottui taivaaseen ja se näkyi kaikkeen maahan,'),
(1690819,58,27,4,18,'jonka lehvät olivat kauniit ja hedelmät suuret ja jossa oli ravintoa kaikille, jonka alla kedon eläimet asuivat ja jonka oksilla taivaan linnut oleskelivat,'),
(1690820,58,27,4,19,'- se puu olet sinä, kuningas, joka olet kasvanut ja vahvistunut; sinun suuruutesi on kasvanut ja ulottuu taivaaseen ja sinun valtasi maan ääriin.'),
(1690821,58,27,4,20,'Ja että kuningas näki pyhän enkelin astuvan alas taivaasta ja sanovan: ''Hakatkaa puu poikki ja turmelkaa se, mutta jättäkää sen kanto juurineen maahan, rauta- ja vaskikahleissa kedon ruohikkoon; taivaan kasteesta hän kastukoon, ja niinkuin kedon eläinten olkoon hänen osansa, kunnes häneltä on kulunut seitsemän aikaa'','),
(1690822,58,27,4,21,'sen selitys, oi kuningas, ja Ylimmäisen päätös, joka on kohdannut minun herraani, kuningasta, on tämä:'),
(1690823,58,27,4,22,'Sinut ajetaan pois ihmisten seasta, ja kedon eläinten parissa on sinun asuinpaikkasi oleva; sinä joudut syömään ruohoa niinkuin raavaat, ja sinä olet kastuva taivaan kasteesta; ja niin on sinulta kuluva seitsemän aikaa, kunnes tulet tuntemaan, että Korkein hallitsee ihmisten valtakuntaa ja antaa sen, kenelle hän tahtoo.'),
(1690824,58,27,4,23,'Mutta että käskettiin jättää maahan puun kanto juurineen, se tietää, että sinun valtakuntasi pysytetään sinulla, ja sinä saat sen, niin pian kuin tulet tuntemaan, että valta on taivaan.'),
(1690825,58,27,4,24,'Sentähden, kuningas, kelvatkoon sinulle minun neuvoni: kirvoita synnit itsestäsi almuilla ja pahat tekosi vaivaisia armahtamalla; ehkäpä silloin onnesi kestäisi."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690826,58,27,4,25,'Tämä kaikki kohtasi kuningas Nebukadnessaria.'),
(1690827,58,27,4,26,'Kaksitoista kuukautta tämän jälkeen, kun kuningas oli kävelemässä kuninkaallisen palatsinsa katolla Baabelissa,'),
(1690828,58,27,4,27,'hän puhkesi puhumaan sanoen: "Eikö tämä ole se suuri Baabel, jonka minä väkevällä voimallani olen rakentanut kuninkaalliseksi linnaksi, valtasuuruuteni kunniaksi!"'),
(1690829,58,27,4,28,'Vielä oli sana kuninkaan suussa, kun taivaasta tuli ääni: "Sinulle, kuningas Nebukadnessar, julistetaan: Sinun valtakuntasi on otettu sinulta pois.'),
(1690830,58,27,4,29,'Sinut ajetaan pois ihmisten seasta, ja kedon eläinten parissa on sinun asuinpaikkasi oleva; sinä joudut syömään ruohoa niinkuin raavaat, ja niin on sinulta kuluva seitsemän aikaa, kunnes tulet tuntemaan, että Korkein hallitsee ihmisten valtakuntaa ja antaa sen, kenelle hän tahtoo."'),
(1690831,58,27,4,30,'Sillä hetkellä se sana toteutui Nebukadnessarissa: hänet ajettiin pois ihmisten seasta, ja hän söi ruohoa niinkuin raavaat, ja hänen ruumiinsa kastui taivaan kasteesta, kunnes hänen hiuksensa kasvoivat pitkiksi kuin kotkan sulat ja hänen kyntensä kuin lintujen kynnet.'),
(1690832,58,27,4,31,'"Mutta sen ajan kuluttua minä, Nebukadnessar, nostin silmäni taivasta kohti, ja minun järkeni palasi. Ja minä kiitin Korkeinta, minä ylistin ja kunnioitin häntä, joka elää iankaikkisesti, jonka hallitus on iankaikkinen hallitus ja jonka valtakunta pysyy suvusta sukuun.'),
(1690833,58,27,4,32,'Kaikki maan asukkaat ovat tyhjänveroiset; ja hän tekee, niinkuin hän tahtoo, taivaan joukoille ja maan asukkaille, eikä ole sitä, joka pidättää hänen kätensä ja sanoo hänelle: ''Mitäs teet?'''),
(1690834,58,27,4,33,'Siihen aikaan palasi minun järkeni, ja palasi minun valtasuuruuteni ja loistoni, minun valtakuntani kunniaksi. Ja minun hallitusmieheni ja ylimykseni etsivät minut, ja minut pantiin jälleen hallitsemaan valtakuntaani, ja minun valtani lisääntyi ylenpalttisesti.'),
(1690835,58,27,4,34,'Nyt minä, Nebukadnessar, kiitän, ylistän ja kunnioitan taivaan kuningasta; sillä kaikki hänen työnsä ovat totiset ja hänen tiensä oikeat. Ja hän voi nöyryyttää ne, jotka ylpeydessä vaeltavat."'),
(1690836,58,27,5,1,'Kuningas Belsassar laittoi suuret pidot tuhannelle ylimyksellensä, ja hän joi viiniä näiden tuhannen edessä.'),
(1690837,58,27,5,2,'Kun viini oli makeimmillaan, käski Belsassar tuoda ne kulta- ja hopea-astiat, jotka hänen isänsä Nebukadnessar oli ottanut Jerusalemin temppelistä, että kuningas ja hänen ylimyksensä, hänen puolisonsa ja sivuvaimonsa joisivat niistä.'),
(1690838,58,27,5,3,'Silloin tuotiin ne kulta-astiat, jotka oli otettu temppelistä, Jumalan huoneesta, Jerusalemista, ja niistä joivat kuningas ja hänen ylimyksensä, hänen puolisonsa ja sivuvaimonsa.'),
(1690839,58,27,5,4,'He joivat viiniä ja ylistivät kultaisia ja hopeisia, vaskisia, rautaisia, puisia ja kivisiä jumalia.'),
(1690840,58,27,5,5,'Sillä hetkellä ilmestyivät ihmiskäden sormet ja kirjoittivat kuninkaan palatsin kalkitulle seinälle, vastapäätä lampunjalkaa, ja kuningas näki käden, joka kirjoitti.'),
(1690841,58,27,5,6,'Silloin kuninkaan kasvot kalpenivat, ja hänen ajatuksensa peljästyttivät hänet; hänen lanteittensa nivelet herposivat, ja hänen polvensa tutisivat.'),
(1690842,58,27,5,7,'Kuningas huusi kovalla äänellä ja käski tuoda noidat, kaldealaiset ja tähtienselittäjät. Kuningas lausui ja sanoi Baabelin tietäjille: "Kuka ikinä voi lukea tämän kirjoituksen ja ilmoittaa minulle sen selityksen, hänet puetaan purppuraan, ja hänen kaulaansa pannaan kultakäädyt, ja hän on oleva yksi valtakunnan kolmesta valtamiehestä".'),
(1690843,58,27,5,8,'Silloin tulivat kaikki kuninkaan viisaat, mutta he eivät voineet lukea kirjoitusta eivätkä ilmoittaa kuninkaalle sen selitystä.'),
(1690844,58,27,5,9,'Kuningas Belsassar peljästyi silloin suuresti, ja hänen kasvonsa kalpenivat, ja hänen ylimyksensä tyrmistyivät.'),
(1690845,58,27,5,10,'Kuninkaan äiti tuli kuninkaan ja hänen ylimystensä puheen tähden pitohuoneeseen. Kuninkaan äiti lausui ja sanoi: "Eläköön kuningas iankaikkisesti! Älkööt sinun ajatuksesi peljättäkö sinua, älköötkä kasvosi kalvetko.'),
(1690846,58,27,5,11,'Sinun valtakunnassasi on mies, jossa on pyhien jumalien henki ja jolla sinun isäsi päivinä havaittiin olevan valistus ja ymmärrys ynnä viisaus, samankaltainen kuin jumalien; hänet asetti isäsi, kuningas Nebukadnessar, tietäjäin, noitien, kaldealaisten ja tähtienselittäjäin päämieheksi - sinun isäsi, kuningas -'),
(1690847,58,27,5,12,'sentähden, että erinomainen henki ja tieto ynnä myös taito selittää unia, arvata arvoituksia ja ratkaista ongelmia havaittiin juuri hänessä, Danielissa, jolle kuningas oli antanut nimen Beltsassar. Kutsuttakoon nyt Daniel, niin hän ilmoittaa selityksen."'),
(1690848,58,27,5,13,'Silloin Daniel tuotiin kuninkaan eteen. Kuningas lausui ja sanoi Danielille: "Oletko sinä Daniel, joka on niitä juutalaisia pakkosiirtolaisia, mitkä minun isäni, kuningas, on tuonut Juudasta?'),
(1690849,58,27,5,14,'Minä olen kuullut sinusta, että sinussa on jumalien henki ja että sinussa on havaittu valistus, taito ja erinomainen viisaus.'),
(1690850,58,27,5,15,'Ja nyt tuotiin minun eteeni viisaat ja noidat lukemaan tätä kirjoitusta ja ilmoittamaan minulle sen selitys, mutta he eivät voineet sen selitystä ilmoittaa.'),
(1690851,58,27,5,16,'Mutta sinun minä olen kuullut voivan antaa selityksiä ja ratkaista ongelmia. Nyt siis, jos voit lukea kirjoituksen ja ilmoittaa minulle sen selityksen, niin sinut puetaan purppuraan, ja kultakäädyt pannaan sinun kaulaasi, ja sinä olet oleva yksi valtakunnan kolmesta valtamiehestä."'),
(1690852,58,27,5,17,'Silloin Daniel vastasi ja sanoi kuninkaalle: "Lahjasi pidä itse, ja antimesi anna toiselle. Mutta kirjoituksen minä luen kuninkaalle ja ilmoitan hänelle sen selityksen.'),
(1690853,58,27,5,18,'Sinä kuningas! Korkein Jumala antoi sinun isällesi Nebukadnessarille kuninkuuden, voiman, kunnian ja valtasuuruuden.'),
(1690854,58,27,5,19,'Ja sen voiman tähden, jonka hän oli hänelle antanut, vapisivat kaikki kansat, kansakunnat ja kielet ja pelkäsivät hänen edessään. Hän tappoi, kenen hän tahtoi, hän jätti henkiin, kenen hän tahtoi, hän ylensi, kenen hän tahtoi, hän alensi, kenen hän tahtoi.'),
(1690855,58,27,5,20,'Mutta kun hänen sydämensä paisui ja hänen henkensä kävi korskeaksi ja ylpeäksi, syöstiin hänet kuninkaalliselta valtaistuimeltansa, ja hänen kunniansa otettiin häneltä pois.'),
(1690856,58,27,5,21,'Hänet ajettiin pois ihmisten seasta, ja hänen sydämensä tuli eläinten sydämen kaltaiseksi; hänen asuntonsa oli villiaasien parissa, ja hän joutui syömään ruohoa niinkuin raavaat; hänen ruumiinsa kastui taivaan kasteesta, kunnes hän tuli tuntemaan, että korkein Jumala hallitsee ihmisten valtakuntaa ja asettaa sen päämieheksi, kenen hän tahtoo.'),
(1690857,58,27,5,22,'Mutta sinä, hänen poikansa Belsassar, et ole nöyryyttänyt sydäntäsi, vaikka tämän kaiken tiesit;'),
(1690858,58,27,5,23,'vaan sinä olet korottanut itsesi taivaan Herraa vastaan: hänen huoneensa astiat on tuotu sinun eteesi, ja sinä ja sinun ylimyksesi, sinun puolisosi ja sivuvaimosi olette juoneet niistä viiniä, ja sinä olet ylistänyt hopeisia ja kultaisia, vaskisia, rautaisia, puisia ja kivisiä jumalia, jotka eivät näe, eivät kuule eivätkä mitään tiedä. Mutta sitä Jumalaa, jonka kädessä on sinun henkesi ja kaikki sinun tiesi, sinä et ole kunnioittanut.'),
(1690859,58,27,5,24,'Sentähden on tämä käsi lähetetty hänen tyköänsä ja tämä kirjoitus kirjoitettu.'),
(1690860,58,27,5,25,'Ja tämä on kirjoitus, joka on tuonne kirjoitettu: ''Mene, mene, tekel, ufarsin''.'),
(1690861,58,27,5,26,'Ja tämä on sen selitys: mene merkitsee: Jumala on laskenut sinun valtakuntasi luvun ja on tehnyt siitä lopun.'),
(1690862,58,27,5,27,'Tekel: sinut on vaa''alla punnittu ja köykäiseksi havaittu.'),
(1690863,58,27,5,28,'Peres: sinun valtakuntasi on pirstottu ja annettu meedialaisille ja persialaisille."'),
(1690864,58,27,5,29,'Silloin Belsassar antoi käskyn, että Daniel oli puettava purppuraan ja kultakäädyt pantava hänen kaulaansa ja julistettava, että hän oli oleva yksi valtakunnan kolmesta valtamiehestä.'),
(1690865,58,27,5,30,'Samana yönä tapettiin Belsassar, kaldealaisten kuningas,'),
(1690866,58,27,5,31,'ja Daarejaves, meedialainen, sai haltuunsa valtakunnan ollessaan noin kuudenkymmenen kahden vuoden ikäinen.'),
(1690867,58,27,6,1,'Daarejaves näki hyväksi asettaa valtakuntaansa sata kaksikymmentä satraappia, että heitä olisi kaikkialla valtakunnassa.'),
(1690868,58,27,6,2,'Ja heitä ylempänä oli kolme valtaherraa, joista Daniel oli yksi. Heille tuli satraappien tehdä tili, ettei kuningas kärsisi vahinkoa.'),
(1690869,58,27,6,3,'Mutta Daniel oli etevämpi muita valtaherroja sekä satraappeja, sillä hänessä oli erinomainen henki; ja kuningas aikoi asettaa hänet koko valtakunnan päämieheksi.'),
(1690870,58,27,6,4,'Silloin toiset valtaherrat sekä satraapit etsivät Danielia vastaan syytä valtakunnan hallinnossa. Mutta he eivät voineet löytää mitään syytä eikä rikkomusta, sillä hän oli uskollinen, eikä hänestä laiminlyöntiä eikä rikkomusta löydetty.'),
(1690871,58,27,6,5,'Silloin nämä miehet sanoivat: "Me emme löydä tuossa Danielissa mitään syytä - ellemme löydä sitä hänen jumalanpalveluksessaan".'),
(1690872,58,27,6,6,'Senjälkeen nämä valtaherrat ja satraapit riensivät kiiruusti kuninkaan tykö ja sanoivat hänelle näin: "Kuningas Daarejaves eläköön iankaikkisesti!'),
(1690873,58,27,6,7,'Kaikki kuninkaalliset valtaherrat, maaherrat, satraapit, hallitusmiehet ja käskynhaltijat ovat keskenänsä neuvotelleet, että olisi annettava kuninkaallinen julistus ja vahvistettava kielto, että kuka ikinä kolmenkymmenen päivän kuluessa rukoilee jotakin yhdeltäkään jumalalta tai ihmiseltä, paitsi sinulta, kuningas, se heitettäköön jalopeurain luolaan.'),
(1690874,58,27,6,8,'Nyt, kuningas! Säädä kielto ja kirjoita kirjoitus, jota meedialaisten ja persialaisten peruuttamattoman lain mukaan ei voida muuttaa."'),
(1690875,58,27,6,9,'Niin kuningas Daarejaves kirjoitti kirjoituksen ja kiellon.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690876,58,27,6,10,'Niin pian kuin Daniel oli saanut tietää, että kirjoitus oli kirjoitettu, meni hän taloonsa, jonka yläsalin ikkunat olivat avatut Jerusalemiin päin. Ja hän lankesi kolmena hetkenä päivässä polvillensa, rukoili ja kiitti Jumalaansa, aivan niinkuin hän ennenkin oli tehnyt.'),
(1690877,58,27,6,11,'Silloin nuo miehet riensivät kiiruusti sinne ja tapasivat Danielin rukoilemasta ja avuksi huutamasta Jumalaansa.'),
(1690878,58,27,6,12,'Sitten he astuivat kuninkaan eteen ja muistuttivat kuninkaan kiellosta: "Etkö ole kirjoittanut kieltoa, että kuka ikinä kolmenkymmenen päivän kuluessa rukoilee jotakin yhdeltäkään jumalalta tai ihmiseltä, paitsi sinulta, kuningas, se heitettäköön jalopeurain luolaan?" Kuningas vastasi ja sanoi: "Kielto on luja, meedialaisten ja persialaisten peruuttamattoman lain mukaan".'),
(1690879,58,27,6,13,'Silloin he vastasivat ja sanoivat kuninkaalle: "Daniel, joka on juutalaisia pakkosiirtolaisia, ei välitä sinusta, kuningas, eikä kiellosta, jonka olet kirjoittanut, vaan kolmena hetkenä päivässä hän toimittaa rukouksensa".'),
(1690880,58,27,6,14,'Mutta kun kuningas sen kuuli, tuli hän sangen murheelliseksi, ja hän mietti, miten voisi pelastaa Danielin; auringon laskuun asti hän vaivasi itseään vapauttaaksensa hänet.'),
(1690881,58,27,6,15,'Silloin ne miehet riensivät kiiruusti kuninkaan tykö ja sanoivat kuninkaalle: "Tiedä, kuningas, meedialaisten ja persialaisten laki on, ettei mitään kuninkaan vahvistamaa kieltoa tai julistusta peruuteta".'),
(1690882,58,27,6,16,'Silloin kuningas käski tuoda Danielin ja heittää hänet jalopeurain luolaan. Ja kuningas puhui Danielille ja sanoi: "Sinun Jumalasi, jota sinä lakkaamatta palvelet, pelastakoon sinut". Sitten tuotiin kivi ja pantiin luolan suulle,'),
(1690883,58,27,6,17,'ja kuningas sinetöi sen omallaan ja ylimystensä sineteillä, ettei Danielin asiassa muutosta tapahtuisi.'),
(1690884,58,27,6,18,'Sitten kuningas meni palatsiinsa ja vietti yönsä paastoten eikä sallinut tuoda eteensä naisia, ja hänen unensa pakeni häneltä.'),
(1690885,58,27,6,19,'Aamun sarastaessa kuningas sitten nousi ja meni kiiruusti jalopeurain luolalle.'),
(1690886,58,27,6,20,'Ja lähestyessään luolaa hän huusi Danielille murheellisella äänellä, ja kuningas lausui ja sanoi Danielille: "Daniel, sinä elävän Jumalan palvelija, onko sinun Jumalasi, jota lakkaamatta palvelet, voinut pelastaa sinut jalopeuroilta?"'),
(1690887,58,27,6,21,'Silloin Daniel vastasi kuninkaalle: "Kuningas eläköön iankaikkisesti!'),
(1690888,58,27,6,22,'Minun Jumalani on lähettänyt enkelinsä ja sulkenut jalopeurain kidat, niin etteivät ne ole minua vahingoittaneet, sillä minut on havaittu nuhteettomaksi hänen edessänsä, enkä minä ole sinuakaan vastaan, kuningas, rikosta tehnyt."'),
(1690889,58,27,6,23,'Silloin kuningas ihastui suuresti ja käski ottaa Danielin ylös luolasta. Ja kun Daniel oli otettu ylös luolasta, ei hänessä havaittu mitään vammaa; sillä hän oli turvannut Jumalaansa.'),
(1690890,58,27,6,24,'Ja kuningas käski tuoda ne miehet, jotka olivat syyttäneet Danielia, ja heittää heidät lapsineen ja vaimoineen jalopeurain luolaan; eivätkä he ehtineet luolan pohjaan, ennenkuin jalopeurat hyökkäsivät heidän kimppuunsa ja murskasivat kaikki heidän luunsa.'),
(1690891,58,27,6,25,'Sitten kuningas Daarejaves kirjoitti kaikille kansoille, kansakunnille ja kielille, mitä koko maan päällä asuu: "Suuri olkoon teidän rauhanne!'),
(1690892,58,27,6,26,'Minä olen antanut käskyn, että minun valtakuntani koko valtapiirissä vavistakoon ja peljättäköön Danielin Jumalaa. Sillä hän on elävä Jumala ja pysyy iankaikkisesti. Hänen valtakuntansa ei häviä, eikä hänen herrautensa lopu.'),
(1690893,58,27,6,27,'Hän pelastaa ja vapahtaa, hän tekee tunnustekoja ja ihmeitä taivaassa ja maan päällä, hän, joka pelasti Danielin jalopeurain kynsistä."'),
(1690894,58,27,6,28,'Ja tämä Daniel oli korkeassa arvossa ja kunniassa Daarejaveksen valtakunnassa sekä persialaisen Kooreksen valtakunnassa.'),
(1690895,58,27,7,1,'Belsassarin, Baabelin kuninkaan, ensimmäisenä hallitusvuotena Daniel näki unen, päänsä näyn, vuoteessansa. Sitten hän kirjoitti tämän unen.'),
(1690896,58,27,7,2,'Kertomuksen alku on tämä: Daniel lausui ja sanoi: Minä näin yöllä näyssäni, ja katso, taivaan neljä tuulta kuohutti suurta merta.'),
(1690897,58,27,7,3,'Ja merestä nousi neljä suurta petoa, kukin erilainen kuin toinen.'),
(1690898,58,27,7,4,'Ensimmäinen oli kuin leijona, mutta sillä oli kotkan siivet. Minun sitä katsellessani reväistiin siltä siivet, ja se nostettiin maasta pystyyn ja asetettiin kahdelle jalalle niinkuin ihminen, ja sille annettiin ihmisen sydän.'),
(1690899,58,27,7,5,'Ja katso, oli toinen peto, joka oli karhun näköinen. Se nostettiin toiselle kyljellensä, ja sillä oli suussa kolme kylkiluuta, hammasten välissä; ja sille sanottiin näin: "Nouse ja syö paljon lihaa".'),
(1690900,58,27,7,6,'Tämän jälkeen minä näin, ja katso, oli taas toinen peto, pantterin kaltainen, ja sen selässä oli neljä linnunsiipeä. Sillä pedolla oli neljä päätä, ja sille annettiin valta.'),
(1690901,58,27,7,7,'Sen jälkeen minä näin yöllisessä näyssäni, ja katso, oli neljäs peto, kauhea, hirmuinen ja ylen väkevä; sillä oli suuret rautaiset hampaat, ja se söi ja murskasi ja tallasi tähteet jalkoihinsa. Se oli erilainen kuin kaikki edelliset pedot, ja sillä oli kymmenen sarvea.'),
(1690902,58,27,7,8,'Minä tarkkasin sarvea, ja katso, eräs muu pieni sarvi puhkesi niiden välistä, ja kolme edellisistä sarvista reväistiin pois sen edestä. Ja katso, sillä sarvella oli silmät kuin ihmisen silmät, ja suu, joka herjaten puhui.'),
(1690903,58,27,7,9,'Minun sitä katsellessani valtaistuimet asetettiin, ja Vanhaikäinen istuutui. Hänen vaatteensa olivat valkeat kuin lumi ja hänen päänsä hiukset kuin puhdas villa. Hänen valtaistuimensa oli tulen liekkejä, ja sen pyörät olivat palavaa tulta.'),
(1690904,58,27,7,10,'Tulivirta vuoti, se kävi ulos hänestä; tuhannen tuhatta palveli häntä, ja kymmenen tuhatta kertaa kymmenen tuhatta seisoi hänen edessänsä. Oikeus istui tuomiolle, ja kirjat avattiin.'),
(1690905,58,27,7,11,'Minä katselin, ja silloin, niiden herjaavien sanojen tähden, joita sarvi puhui, minun katsellessani peto tapettiin, ja sen ruumis hävitettiin ja heitettiin tuleen palamaan.'),
(1690906,58,27,7,12,'Ja muiltakin pedoilta otettiin valta pois; niiden elämän pituus oli määrätty aikaa ja hetkeä myöten.'),
(1690907,58,27,7,13,'Minä näin yöllisessä näyssä, ja katso, taivaan pilvissä tuli Ihmisen Pojan kaltainen; ja hän saapui Vanhaikäisen tykö, ja hänet saatettiin tämän eteen.'),
(1690908,58,27,7,14,'Ja hänelle annettiin valta, kunnia ja valtakunta, ja kaikki kansat, kansakunnat ja kielet palvelivat häntä. Hänen valtansa on iankaikkinen valta, joka ei lakkaa, ja hänen valtakuntansa on valtakunta, joka ei häviä.'),
(1690909,58,27,7,15,'Minä, Daniel, tunsin henkeni tulevan murheelliseksi ruumiissani, ja minun näkemäni näyt peljättivät minua.'),
(1690910,58,27,7,16,'Minä lähestyin yhtä siellä seisovista ja pyysin häneltä varmaa tietoa kaikista näistä asioista. Niin hän vastasi minulle ja ilmoitti minulle niiden selityksen:'),
(1690911,58,27,7,17,'"Nuo suuret pedot, joita on neljä, ovat neljä kuningasta, jotka nousevat maasta.'),
(1690912,58,27,7,18,'Mutta Korkeimman pyhät saavat valtakunnan ja omistavat valtakunnan iankaikkisesti - iankaikkisesta iankaikkiseen."'),
(1690913,58,27,7,19,'Senjälkeen minä tahdoin saada varmuuden neljännestä pedosta, joka oli erilainen kuin kaikki muut ja ylen hirmuinen; jolla oli rautaiset hampaat ja vaskiset kynnet, joka söi ja murskasi ja tallasi tähteet jalkoihinsa;'),
(1690914,58,27,7,20,'sekä pedon pään kymmenestä sarvesta ynnä siitä sarvesta, joka puhkesi ja jonka edestä kolme putosi; jolla sarvella oli silmät ja herjauksia puhuva suu ja joka näytti suuremmalta kuin ne muut;'),
(1690915,58,27,7,21,'se sarvi, jonka minä näin sotivan pyhiä vastaan ja voittavan heidät,'),
(1690916,58,27,7,22,'siihen asti kunnes Vanhaikäinen tuli ja oikeus annettiin Korkeimman pyhille ja aika joutui ja pyhät saivat omaksensa valtakunnan.'),
(1690917,58,27,7,23,'Hän vastasi näin: "Neljäs peto on neljäs valtakunta, joka syntyy maan päälle, erilainen kuin kaikki muut valtakunnat. Se syö kaiken maan ja tallaa ja murskaa sen.'),
(1690918,58,27,7,24,'Ja ne kymmenen sarvea ovat kymmenen kuningasta, jotka nousevat siitä valtakunnasta. Ja heidän jälkeensä nousee eräs muu, ja hän on erilainen kuin edelliset, ja hän kukistaa kolme kuningasta.'),
(1690919,58,27,7,25,'Hän puhuu sanoja Korkeinta vastaan ja hävittää Korkeimman pyhiä. Hän pyrkii muuttamaan ajat ja lain, ja ne annetaan hänen käteensä ajaksi ja kahdeksi ajaksi ja puoleksi ajaksi.'),
(1690920,58,27,7,26,'Sitten oikeus istuu tuomiolle, ja hänen valtansa otetaan pois ja hävitetään ja tuhotaan loppuun asti.'),
(1690921,58,27,7,27,'Ja valtakunta ja valta ja valtakuntien voima kaiken taivaan alla annetaan Korkeimman pyhien kansalle. Hänen valtakuntansa on iankaikkinen valtakunta, ja kaikki vallat palvelevat häntä ja ovat hänelle alamaiset."'),
(1690922,58,27,7,28,'Tähän loppuu kertomus. Minua, Danielia, peljättivät minun ajatukseni suuresti, ja minun kasvoni kalpenivat, ja minä kätkin asian sydämeeni.'),
(1690923,58,27,8,1,'Kuningas Belsassarin kolmantena hallitusvuotena näin minä, Daniel, näyn, senjälkeen kuin minulla jo ennen oli ollut näky.'),
(1690924,58,27,8,2,'Kun minä näyssä katselin, havaitsin minä olevani Suusanin linnassa, Eelamin maakunnassa; ja kun minä näyssä katselin, olin minä Uulai-joen rannalla.'),
(1690925,58,27,8,3,'Minä nostin silmäni ja katsoin. Ja katso, oinas seisoi päin jokea, ja sillä oli kaksi sarvea; ja sarvet olivat korkeat, ja toinen oli toista korkeampi; ja korkeampi puhkesi esiin myöhemmin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690926,58,27,8,4,'Minä näin oinaan puskevan länteen, pohjoiseen ja etelään päin, eikä yksikään eläin kestänyt sen edessä, eikä kukaan voinut pelastaa sen vallasta. Se teki, mitä tahtoi; ja se tuli suureksi.'),
(1690927,58,27,8,5,'Sitten minä tarkkasin, ja katso: tuli kauris päivän laskun puolelta, kulki koko maan ylitse eikä maata koskettanut; ja kauriilla oli keskellä otsaa uhkea sarvi.'),
(1690928,58,27,8,6,'Ja se tuli aivan sen kaksisarvisen oinaan luokse, jonka minä olin nähnyt seisovan päin jokea, ja karkasi sen kimppuun vihansa väessä.'),
(1690929,58,27,8,7,'Ja minä näin sen käyvän kiinni oinaaseen ja kiukuissaan puskevan oinasta ja murskaavan sen molemmat sarvet. Eikä oinaalla ollut voimaa kestää sen edessä, vaan kauris heitti sen maahan ja tallasi sitä; eikä ollut ketään, joka olisi voinut pelastaa oinaan sen vallasta.'),
(1690930,58,27,8,8,'Ja kauris tuli ylen suureksi; mutta kun se oli väkevimmillään, särkyi suuri sarvi, ja sen sijalle kasvoi neljä uhkeata sarvea, taivaan neljää tuulta kohti.'),
(1690931,58,27,8,9,'Ja yhdestä niistä puhkesi esiin sarvi, alussa vähäpätöinen. Se kasvoi suuresti etelään päin ja itään päin ja Ihanaan maahan päin.'),
(1690932,58,27,8,10,'Ja se kasvoi taivaan sotajoukkoon asti ja pudotti maahan osan siitä sotajoukosta ja tähdistä ja tallasi niitä.'),
(1690933,58,27,8,11,'Hän ylpeili sotajoukon ruhtinastakin vastaan, ja tältä otettiin pois jokapäiväinen uhri, ja hänen pyhäkkönsä paikka kukistettiin.'),
(1690934,58,27,8,12,'Myös sotajoukko jokapäiväisen uhrin lisäksi annettiin rikollisesti alttiiksi tuholle. Se sarvi heitti totuuden maahan, ja mitä se teki, siinä se menestyi.'),
(1690935,58,27,8,13,'Sitten minä kuulin yhden pyhän puhuvan, ja toinen pyhä sanoi sille, joka puhui: "Kuinka pitkää aikaa tarkoittaa näky jokapäiväisestä uhrista ja kauhistavasta rikoksesta: pyhäkön ja sotajoukon alttiiksi antamisesta tallattavaksi?"'),
(1690936,58,27,8,14,'Ja hän sanoi minulle: "Kahtatuhatta kolmeasataa iltaa ja aamua; sitten pyhäkkö asetetaan jälleen oikeuteensa".'),
(1690937,58,27,8,15,'Kun minä, Daniel, olin nähnyt tämän näyn ja koetin sitä ymmärtää, niin katso, minun edessäni seisoi miehen muotoinen olento.'),
(1690938,58,27,8,16,'Ja minä kuulin ihmisen äänen Uulain keskeltä, ja se huusi ja sanoi: "Gabriel, selitä tälle se näky!"'),
(1690939,58,27,8,17,'Silloin hän tuli aivan lähelle sitä paikkaa, jossa minä seisoin; ja hänen tullessansa minut valtasi pelko, ja minä lankesin kasvoilleni. Ja hän sanoi minulle: "Tarkkaa, ihmislapsi, sillä näky tarkoittaa lopun aikaa".'),
(1690940,58,27,8,18,'Ja kun hän puhui minulle, olin minä horroksissa, kasvot maata vasten; mutta hän tarttui minuun ja nosti minut seisomaan.'),
(1690941,58,27,8,19,'Sitten hän sanoi: "Katso, minä ilmoitan sinulle, mitä on tapahtuva viimeisenä vihan aikana; sillä lopun aikaa tämä tarkoittaa.'),
(1690942,58,27,8,20,'Kaksisarvinen oinas, jonka sinä näit, on: Meedian ja Persian kuninkaat.'),
(1690943,58,27,8,21,'Ja kauris on Jaavanin kuningas, ja suuri sarvi, joka sillä oli keskellä otsaa, on ensimmäinen kuningas.'),
(1690944,58,27,8,22,'Ja että se särkyi ja neljä nousi sen sijalle, se on: neljä valtakuntaa nousee siitä kansasta, ei kuitenkaan niin väkevää kuin hän.'),
(1690945,58,27,8,23,'Ja heidän valtansa lopulla, kun luopiot ovat täyttäneet syntiensä mitan, nousee kuningas, kasvoilta röyhkeä ja juonissa taitava.'),
(1690946,58,27,8,24,'Ja väkevä on hänen voimansa, vaikka ei tosin hänen omasta voimastaan, ja ihmeellisen paljon hän saa aikaan hävitystä; ja hän menestyy siinä, mitä hän tekee, ja hän tuottaa turmion väkeville ja pyhien kansalle.'),
(1690947,58,27,8,25,'Ja hänen oveluutensa tähden onnistuu petos hänen kädessään. Hän hautoo suuria sydämessään, ja keskellä rauhaa hän tuottaa turmion monille. Ruhtinasten ruhtinastakin vastaan hän nousee, mutta ilman ihmiskättä hänet muserretaan.'),
(1690948,58,27,8,26,'Ja näky illoista ja aamuista, josta oli puhe, on tosi. Mutta sinä lukitse näky, sillä se tarkoittaa kaukaista aikaa."'),
(1690949,58,27,8,27,'Ja minä, Daniel, olin raukea ja sairastin jonkin aikaa. Sitten minä nousin ja toimitin palvelusta kuninkaan tykönä; ja minä olin hämmästyksissäni näyn tähden enkä sitä ymmärtänyt.'),
(1690950,58,27,9,1,'Daarejaveksen, Ahasveroksen pojan, ensimmäisenä hallitusvuotena, hänen, joka oli meedialaista sukua ja oli tullut kaldealaisten valtakunnan kuninkaaksi -'),
(1690951,58,27,9,2,'hänen ensimmäisenä hallitusvuotenaan, minä, Daniel, kirjoituksista huomasin vuosien luvun, josta Herran sana oli tullut profeetta Jeremialle, että Jerusalem oli oleva raunioina seitsemänkymmentä vuotta.'),
(1690952,58,27,9,3,'Ja minä käänsin kasvoni Herran Jumalan puoleen hartaassa rukouksessa ja anomisessa, paastossa, säkissä ja tuhassa.'),
(1690953,58,27,9,4,'Minä rukoilin Herraa, Jumalaani, tunnustin ja sanoin: "Oi Herra, sinä suuri ja peljättävä Jumala, joka pidät liiton ja säilytät laupeuden niille, jotka sinua rakastavat ja noudattavat sinun käskyjäsi.'),
(1690954,58,27,9,5,'Me olemme syntiä tehneet, olemme väärin tehneet, olleet jumalattomat ja uppiniskaiset; me olemme poikenneet pois sinun käskyistäsi ja oikeuksistasi'),
(1690955,58,27,9,6,'emmekä ole kuulleet sinun palvelijoitasi, profeettoja, jotka puhuivat sinun nimessäsi kuninkaillemme, ruhtinaillemme ja isillemme ja kaikelle maan kansalle.'),
(1690956,58,27,9,7,'Sinun, Herra, on vanhurskaus, mutta meidän on häpeä, niinkuin se on tänä päivänä Juudan miesten ja Jerusalemin asukasten ja koko Israelin, läheisten ja kaukaisten, kaikissa maissa, joihin sinä olet heidät karkoittanut heidän uskottomuutensa tähden, jota he ovat sinulle osoittaneet.'),
(1690957,58,27,9,8,'Herra, meidän on häpeä, meidän kuninkaittemme, ruhtinaittemme ja isiemme, koska me olemme tehneet syntiä sinua vastaan.'),
(1690958,58,27,9,9,'Herran, meidän Jumalamme, on armo ja anteeksiantamus, sillä me olemme olleet hänelle uppiniskaiset;'),
(1690959,58,27,9,10,'me emme ole kuulleet Herran, meidän Jumalamme, ääntä emmekä vaeltaneet hänen laissansa, jonka hän asetti meidän eteemme palvelijainsa, profeettain, kautta.'),
(1690960,58,27,9,11,'Vaan koko Israel rikkoi sinun lakisi ja poikkesi pois eikä kuullut sinun ääntäsi, ja niin vuodatettiin meidän päällemme se kirous ja vala, joka on kirjoitettu Mooseksen, Jumalan palvelijan, laissa; sillä me olimme tehneet syntiä häntä vastaan.'),
(1690961,58,27,9,12,'Ja hän toteutti sanansa, jonka hän on puhunut meitä ja meidän tuomareitamme vastaan, jotka meitä tuomitsivat, ja antoi meidän päällemme tulla niin suuren onnettomuuden, ettei senkaltaista ole tapahtunut koko taivaan alla, kuin Jerusalemissa tapahtui.'),
(1690962,58,27,9,13,'Niinkuin on kirjoitettu Mooseksen laissa, niin tuli kaikki tämä onnettomuus meidän päällemme. Mutta me emme koettaneet lepyttää Herraa, meidän Jumalaamme, niin että olisimme kääntyneet pois synneistämme ja ottaneet vaarin sinun totuudestasi.'),
(1690963,58,27,9,14,'Sentähden Herra valvoi ja antoi tämän onnettomuuden tulla meidän päällemme; sillä Herra, meidän Jumalamme, on vanhurskas kaikissa töissänsä, jotka hän tekee, mutta me emme ole kuulleet hänen ääntänsä.'),
(1690964,58,27,9,15,'Ja nyt, Herra, meidän Jumalamme, joka toit kansasi pois Egyptin maasta väkevällä kädellä ja teit itsellesi nimen, niinkuin se vielä tänä päivänä on: me olemme syntiä tehneet ja olleet jumalattomat.'),
(1690965,58,27,9,16,'Herra, kaiken vanhurskautesi tähden, kääntyköön sinun vihasi ja kiivastuksesi pois sinun kaupungistasi Jerusalemista, sinun pyhästä vuorestasi; sillä meidän syntiemme tähden ja meidän isäimme pahojen tekojen tähden on Jerusalem ja sinun kansasi tullut kaikkien häväistäväksi, jotka meidän ympärillämme ovat.'),
(1690966,58,27,9,17,'Ja nyt, meidän Jumalamme, kuule palvelijasi rukous ja hänen anomisensa ja valista kasvosi pyhäkkösi ylitse, joka on autiona; Herran tähden.'),
(1690967,58,27,9,18,'Minun Jumalani, kallista korvasi ja kuule, avaa silmäsi ja katso meidän hävitystämme ja sitä kaupunkia, joka on otettu sinun nimiisi; sillä me annamme rukouksiemme langeta sinun eteesi, emme omaan vanhurskauteemme, vaan sinun suureen armoosi luottaen.'),
(1690968,58,27,9,19,'Herra, kuule, Herra, anna anteeksi, Herra, huomaa ja tee tekosi itsesi tähden, älä viivyttele, minun Jumalani; sillä sinun kaupunkisi ja sinun kansasi ovat sinun nimiisi otetut."'),
(1690969,58,27,9,20,'Ja vielä minä puhuin ja rukoilin ja tunnustin syntini ja kansani Israelin synnit ja annoin rukoukseni langeta Herran, Jumalani, eteen minun Jumalani pyhän vuoren puolesta.'),
(1690970,58,27,9,21,'Ja kun minä vielä puhuin rukouksessa, tuli se mies, Gabriel, jonka minä olin nähnyt ennen näyssä, kiiruusti kiitäen minun tyköni ehtoouhrin aikana.'),
(1690971,58,27,9,22,'Ja hän opetti minua, puhui minulle ja sanoi: "Daniel, nyt minä olen lähtenyt neuvomaan sinua ymmärrykseen.'),
(1690972,58,27,9,23,'Kun sinä aloit rukoilla, lähti liikkeelle sana, ja minä olen tullut sitä ilmoittamaan; sillä sinä olet otollinen. Käsitä siis se sana ja ymmärrä näky.'),
(1690973,58,27,9,24,'Seitsemänkymmentä viikkoa on säädetty sinun kansallesi ja pyhälle kaupungillesi; silloin luopumus päättyy, ja synti sinetillä lukitaan, ja pahat teot sovitetaan, ja iankaikkinen vanhurskaus tuodaan, ja näky ja profeetta sinetillä vahvistetaan, ja kaikkeinpyhin voidellaan.'),
(1690974,58,27,9,25,'Ja tiedä ja käsitä: siitä ajasta, jolloin tuli se sana, että Jerusalem on jälleen rakennettava, voideltuun, ruhtinaaseen, asti, on kuluva seitsemän vuosiviikkoa; ja kuusikymmentäkaksi vuosiviikkoa, niin se jälleen rakennetaan toreinensa ja vallihautoinensa, mutta keskellä ahtaita aikoja.'),
(1690975,58,27,9,26,'Ja kuudenkymmenen kahden vuosiviikon mentyä tuhotaan voideltu, eikä häneltä jää ketään. Ja kaupungin ja pyhäkön hävittää hyökkäävän ruhtinaan väki, mutta hän itse saa loppunsa tulvassa. Ja loppuun asti on oleva sota: hävitys on säädetty.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1690976,58,27,9,27,'Ja hän tekee liiton raskaaksi monille yhden vuosiviikon ajaksi, ja puoleksi vuosiviikoksi hän lakkauttaa teurasuhrin ja ruokauhrin; ja hävittäjä tulee kauhistuksen siivillä. Tämä loppuu vasta, kun säädetty tuomio vuodatetaan hävittäjän ylitse."'),
(1690977,58,27,10,1,'Persian kuninkaan Kooreksen kolmantena hallitusvuotena ilmoitettiin sana Danielille, jota kutsuttiin Beltsassariksi; ja se sana on totuus ja merkitsee suurta vaivaa. Ja hän ymmärsi sanan, ja hän käsitti näyn.'),
(1690978,58,27,10,2,'Niinä päivinä minä, Daniel, murehdin kolmen viikon päivät.'),
(1690979,58,27,10,3,'Herkullista ruokaa minä en syönyt, ei liha eikä viini tullut minun suuhuni, enkä minä voidellut itseäni öljyllä, ennenkuin kolmen viikon päivät olivat loppuun kuluneet.'),
(1690980,58,27,10,4,'Ensimmäisen kuun kahdentenakymmenentenä neljäntenä päivänä minä olin suuren virran, Hiddekelin, rannalla.'),
(1690981,58,27,10,5,'Minä nostin silmäni ja näin, ja katso: oli eräs mies, puettuna pellavavaatteisiin ja kupeet vyötettyinä Uufaan kullalla.'),
(1690982,58,27,10,6,'Hänen ruumiinsa oli kuin krysoliitti, hänen kasvonsa olivat kuin salaman leimaus, hänen silmänsä kuin tulisoihdut, hänen käsivartensa ja jalkansa kuin kiiltävän vasken välke; ja hänen sanojensa ääni oli kuin suuren kansanjoukon pauhina.'),
(1690983,58,27,10,7,'Ja minä, Daniel, yksin näin sen näyn, mutta miehet, jotka olivat minun kanssani, eivät näkyä nähneet; kuitenkin valtasi heidät suuri pelko, ja he pakenivat ja lymysivät.'),
(1690984,58,27,10,8,'Ja minä jäin yksin. Ja kun minä näin tämän suuren näyn, meni minulta kaikki voima; minun verevä muotoni muuttui kaamean näköiseksi, eikä minussa ollut voimaa mihinkään.'),
(1690985,58,27,10,9,'Ja minä kuulin hänen sanainsa äänen; ja kuullessani hänen sanainsa äänen minä vaivuin horroksiin kasvoilleni, kasvot maata vasten.'),
(1690986,58,27,10,10,'Ja katso, käsi kosketti minua ja ravisti minut hereille, polvieni ja kätteni varaan.'),
(1690987,58,27,10,11,'Ja hän sanoi minulle: "Daniel, sinä otollinen mies, ota vaari niistä sanoista, jotka minä sinulle puhun, ja nouse seisomaan, sillä minut on nyt lähetetty sinun tykösi". Ja hänen puhuessansa minulle tämän sanan minä nousin vavisten.'),
(1690988,58,27,10,12,'Ja hän sanoi minulle: "Älä pelkää, Daniel, sillä ensimmäisestä päivästä asti, jona sinä taivutit sydämesi ymmärrykseen ja nöyryyteen Jumalasi edessä, ovat sinun sanasi tulleet kuulluiksi; ja sinun sanojesi tähden minä olen tullut.'),
(1690989,58,27,10,13,'Persian valtakunnan enkeliruhtinas seisoi vastustamassa minua kaksikymmentäyksi päivää, mutta katso, Miikael, yksi ensimmäisistä enkeliruhtinaista, tuli minun avukseni, sillä minä olin jäänyt yksin sinne, Persian kuningasten tykö.'),
(1690990,58,27,10,14,'Ja minä tulin opettamaan sinulle, mitä on tapahtuva sinun kansallesi päivien lopulla; sillä vielä tämäkin näky koskee niitä päiviä."'),
(1690991,58,27,10,15,'Ja hänen näitä minulle puhuessansa minä käänsin kasvoni maahan päin ja olin ääneti.'),
(1690992,58,27,10,16,'Ja katso, olento, ihmislasten muotoinen, kosketti minun huuliani; silloin minä avasin suuni ja puhuin ja sanoin edessäni seisovalle: "Herrani, nähdessäni näyn valtasi minut tuska, ja minulta meni kaikki voima.'),
(1690993,58,27,10,17,'Ja kuinka voi herrani palvelija, tällainen kuin minä, puhutella sellaista, kuin minun herrani on? Sillä siitä asti ei minussa ole voimaa, tuskin enää henkeäkään."'),
(1690994,58,27,10,18,'Silloin kosketti minua jälleen se ihmisen muotoinen ja vahvisti minua.'),
(1690995,58,27,10,19,'Ja hän sanoi: "Älä pelkää, sinä otollinen mies, rauha olkoon sinulle. Vahvistu! Vahvistu!" Ja hänen puhuessaan minulle minä vahvistuin ja sanoin: "Puhukoon herrani, sillä sinä olet minua vahvistanut".'),
(1690996,58,27,10,20,'Ja hän sanoi: "Tiedätkö, mitä varten minä olen tullut sinun tykösi? Nyt minä käyn jälleen sotimaan Persian enkeliruhtinasta vastaan, ja kun minä olen päässyt hänestä, niin katso: tulee Jaavanin enkeliruhtinas.'),
(1690997,58,27,10,21,'Mutta minä ilmoitan sinulle, mitä on kirjoitettuna totuuden kirjassa. Eikä ole ketään muuta vahvistamassa minua heitä vastaan paitsi teidän enkeliruhtinaanne Miikael.'),
(1690998,58,27,11,1,'Ja minä seisoin meedialaisen Daarejaveksen ensimmäisenä hallitusvuotena häntä vahvistamassa ja suojelemassa."'),
(1690999,58,27,11,2,'Ja nyt minä ilmoitan sinulle totuuden: Katso, vielä nousee kolme kuningasta Persiassa, ja neljäs rikastuu kaikkia muita rikkaammaksi. Ja kun hän on vahvistunut rikkaudessaan, panee hän kaiken liikkeelle Jaavanin valtakuntaa vastaan.'),
(1691000,58,27,11,3,'Sitten nousee sankarikuningas; hän hallitsee suurella vallalla ja tekee, mitä tahtoo.'),
(1691001,58,27,11,4,'Mutta juuri kun hän on noussut, hajoaa hänen valtakuntansa ja jakautuu neljään taivaan tuuleen. Se ei joudu hänen jälkeläisilleen eikä ole niin mahtava kuin hänen hallitessaan. Sillä hänen valtakuntansa kukistuu ja joutuu muille, ei heille.'),
(1691002,58,27,11,5,'Ja Etelän kuningas on voimistuva sekä yksi hänen ruhtinaistaan; tämä on voimistuva vielä enemmän kuin hän, ja hänen valtansa on oleva suuri valta.'),
(1691003,58,27,11,6,'Ja vuosien kuluttua he tekevät keskenään liiton, ja Etelän kuninkaan tytär menee Pohjan kuninkaan tykö saadakseen aikaan sopimuksen. Mutta häneltä menee hänen käsivartensa voima; eikä pysy Pohjan kuningas, ei hänen käsivartensa. Ja tytär itse annetaan alttiiksi ja ne, jotka olivat hänet tuoneet, ja hänen isänsä ja se, joka häntä aikoinaan auttoi.'),
(1691004,58,27,11,7,'Sitten hänen juurtensa vesoista nousee eräs hänen sijaansa ja tulee sotajoukkoa vastaan, tulee Pohjan kuninkaan linnoitukseen ja tekee heille mielensä mukaan ja on väkevä.'),
(1691005,58,27,11,8,'Myöskin heidän jumalansa ja valetut kuvansa ja kallisarvoiset astiansa, hopeat ja kullat hän vie saaliinansa Egyptiin; sitten hän muutamia vuosia pysyy Pohjan kuninkaasta erillään.'),
(1691006,58,27,11,9,'Tämä hyökkää Etelän kuninkaan valtakuntaan, mutta palajaa takaisin maahansa.'),
(1691007,58,27,11,10,'Ja hänen poikansa varustautuvat ja kokoavat suuret sotavoimat. Ja hän hyökkää ja kuohuu ja tulvii, hän tulee toistamiseen ja tunkeutuu hänen linnoitukseensa asti.'),
(1691008,58,27,11,11,'Silloin Etelän kuningas kiukustuu ja lähtee sotimaan häntä vastaan, Pohjan kuningasta vastaan. Tämä nostattaa suuren joukon, mutta se joukko joutuu hänen valtaansa.'),
(1691009,58,27,11,12,'Ja kun se joukko on raivattu pois, paisuu hänen sydämensä. Hän kaataa kymmeniä tuhansia, mutta ei ole kyllin vahva.'),
(1691010,58,27,11,13,'Pohjan kuningas nostattaa jälleen joukon, entistä suuremman, ja muutaman ajan, muutaman vuoden kuluttua hyökkää suurella sotavoimalla ja runsailla varustuksilla.'),
(1691011,58,27,11,14,'Niinä aikoina monet nousevat Etelän kuningasta vastaan; ja sinun omasta kansastasi nousee väkivallan miehiä, että näky kävisi toteen, mutta he itse lankeavat.'),
(1691012,58,27,11,15,'Ja Pohjan kuningas hyökkää ja luo vallin ja valloittaa varustetun kaupungin. Eivät kestä Etelän käsivarret, ei sen valioväki, ei ole sillä voimaa seisoa vastaan.'),
(1691013,58,27,11,16,'Ja hän, joka hyökkää sitä vastaan, tekee, mitä tahtoo, eikä kukaan voi seisoa häntä vastaan. Hän asettuu Ihanaan maahan, ja hävitys tulee hänen kätensä kautta.'),
(1691014,58,27,11,17,'Ja nyt hän aikoo hyökätä valtakuntansa koko voimalla; mutta sopimus on hänellä mielessä, ja hän saa sen aikaan. Hän antaa hänelle yhden tyttäristään, tälle turmioksi. Mutta siitä ei tule pysyväistä eikä ole hänelle etua.'),
(1691015,58,27,11,18,'Sitten hän kääntyy rantamaita vastaan ja ottaa valtaansa monet. Mutta eräs sotapäällikkö tekee hänen herjauksistaan lopun ja kostaa hänelle hänen herjauksensa.'),
(1691016,58,27,11,19,'Silloin hän kääntyy oman maansa linnoituksiin, mutta kompastuu ja kaatuu, eikä häntä enää ole.'),
(1691017,58,27,11,20,'Ja hänen sijaansa nousee eräs, joka antaa veronvaatijan käydä läpi valtakunnan ihanimman maan. Mutta muutamien päivien kuluttua hänet tuhotaan, ei kuitenkaan vihan väellä eikä sodalla.'),
(1691018,58,27,11,21,'Ja hänen sijaansa nousee kelvoton, joka ei ollut saapa kuninkaan arvoa. Hän tulee keskellä rauhaa ja anastaa juonilla kuninkuuden.'),
(1691019,58,27,11,22,'Ja sotajoukkojen tulva huuhtoutuu pois hänen edestänsä ja menee murskaksi, niin myös liiton ruhtinas.'),
(1691020,58,27,11,23,'Siitä saakka kun liittoudutaan hänen kanssansa, hän harjoittaa petosta. Hän lähtee liikkeelle ja saa ylivallan vähällä väellä.'),
(1691021,58,27,11,24,'Keskellä rauhaa hän hyökkää maakunnan lihavimpiin seutuihin ja tekee, mitä eivät hänen isänsä eivätkä hänen isiensä isät olleet tehneet: ryöstösaalista ja tavaraa hän jakelee omilleen; ja linnoituksia vastaan hän hankitsee juoniansa, säädettyyn aikaan asti.'),
(1691022,58,27,11,25,'Ja hän panee liikkeelle voimansa ja rohkeutensa Etelän kuningasta vastaan, hyökäten suurella sotajoukolla. Mutta Etelän kuningas varustautuu sotaan suurella ja ylen väkevällä sotajoukolla. Hän ei kuitenkaan kestä, sillä häntä vastaan hankitaan juonia.'),
(1691023,58,27,11,26,'Ja ne, jotka syövät hänen pöydästään, tuhoavat hänet, ja hänen sotajoukkonsa huuhdotaan pois, ja on paljon kaatuneita ja haavoitettuja.'),
(1691024,58,27,11,27,'Ja kumpaisellakin kuninkaalla on paha mielessä toistansa vastaan. Samassa pöydässä he puhuvat valhetta; mutta se ei onnistu; sillä säädetty aika ei ole vielä lopussa.'),
(1691025,58,27,11,28,'Silloin hän palaa maahansa paljoine tavaroineen, miettien hankkeita pyhää liittoa vastaan; hän toteuttaa ne ja palaa maahansa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691026,58,27,11,29,'Määräaikana hän hyökkää jälleen Etelämaahan, mutta tällä viimeisellä retkellä ei käy niinkuin ensimmäisellä.'),
(1691027,58,27,11,30,'Häntä vastaan hyökkäävät kittiläisten laivat, ja hän menettää rohkeutensa, kääntyy takaisin ja purkaa kiukkunsa pyhää liittoa vastaan. Kotiin palattuaan hän suo huomiota niille, jotka hylkäävät pyhän liiton.'),
(1691028,58,27,11,31,'Hänen lähettämänsä sotajoukot nousevat ja häväisevät pyhäkön linnoituksineen, poistavat jokapäiväisen uhrin ja asettavat sinne hävityksen kauhistuksen.'),
(1691029,58,27,11,32,'Ja liitonrikkojat hän viettelee luopumukseen houkutuksillaan, mutta niitten joukko, jotka tuntevat Jumalansa, pysyy lujana ja tekee tehtävänsä.'),
(1691030,58,27,11,33,'Ja taidolliset kansan seassa opettavat monta, mutta heitä sorretaan miekalla, tulella, vankeudella ja ryöstöllä, jonkun aikaa.'),
(1691031,58,27,11,34,'Ja keskellä sortoa heille suodaan pieni menestys, ja monet liittyvät heihin teeskennellen.'),
(1691032,58,27,11,35,'Ja taidollisista jotkut kompastuvat, että heidän joukkonsa koeteltaisiin, seulottaisiin ja puhdistettaisiin lopun ajaksi, sillä vielä kestää, ennenkuin määräaika on.'),
(1691033,58,27,11,36,'Ja kuningas tekee, mitä hän tahtoo, ja korottaa itsensä ja uhittelee jokaista jumalaa, itse jumalien Jumalaa vastaan hän puhuu kauheita. Ja hän menestyy, kunnes vihan aika on lopussa; sillä mikä on säädetty, se tapahtuu.'),
(1691034,58,27,11,37,'Hän ei välitä isäinsä jumalista, ei naisten lempijumalasta, eikä hän välitä mistään muustakaan jumalasta, sillä hän uhittelee niitä kaikkia.'),
(1691035,58,27,11,38,'Mutta sen sijaan hän kunnioittaa linnoitusten jumalaa. Sitä jumalaa, jota hänen isänsä eivät tunteneet, hän kunnioittaa kullalla ja hopealla, kalliilla kivillä ja muilla kalleuksilla.'),
(1691036,58,27,11,39,'Ja tätä hän tekee vahvoille linnoituksille - hän vieraine jumalineen. Niille, jotka hän omikseen tuntee, hän osoittaa suurta kunniaa ja panee heidät monien hallitsijaksi ja jakaa heille maata palkaksi.'),
(1691037,58,27,11,40,'Mutta lopun ajalla Etelän kuningas iskee yhteen hänen kanssansa. Ja Pohjan kuningas käy tämän kimppuun vaunuilla ja ratsuilla ja monilla laivoilla, hyökkää hänen maihinsa, tulvana leviten niiden ylitse.'),
(1691038,58,27,11,41,'Hän hyökkää myös Ihanaan maahan, ja monta kaatuu. Mutta hänen kädestänsä pelastuvat nämä: Edom ja Mooab ja ammonilaisten pääosa.'),
(1691039,58,27,11,42,'Ja hän ojentaa kätensä maita kohti; Egyptin maa ei ole säästyvä.'),
(1691040,58,27,11,43,'Hän valtaa kulta- ja hopea-aarteet ja kaikki Egyptin kalleudet, ja liibyalaiset ja etiopialaiset liittyvät häntä seuraamaan.'),
(1691041,58,27,11,44,'Mutta sanomat idästä ja pohjoisesta säikähdyttävät häntä, ja hän lähtee täynnä kiukkua hävittämään monia ja vihkimään heitä tuhon omiksi.'),
(1691042,58,27,11,45,'Hän pystyttää hovitelttansa meren ja pyhäkön ihanan vuoren välille. Mutta hänen loppunsa tulee, eikä häntä kukaan auta.'),
(1691043,58,27,12,1,'Siihen aikaan nousee Miikael, se suuri enkeliruhtinas, joka seisoo sinun kansasi lasten suojana. Ja se on oleva ahdistuksen aika, jonka kaltaista ei ole ollut siitä saakka, kuin kansoja on ollut, hamaan siihen aikaan asti. Mutta siihen aikaan pelastetaan sinun kansasi, kaikki, jotka kirjaan kirjoitetut ovat.'),
(1691044,58,27,12,2,'Ja monet maan tomussa makaavista heräjävät, toiset iankaikkiseen elämään, toiset häpeään ja iankaikkiseen kauhistukseen.'),
(1691045,58,27,12,3,'Ja taidolliset loistavat, niinkuin taivaanvahvuus loistaa, ja ne, jotka monta vanhurskauteen saattavat, niinkuin tähdet, aina ja iankaikkisesti.'),
(1691046,58,27,12,4,'Mutta sinä, Daniel, lukitse nämä sanat ja sinetöi tämä kirja lopun aikaan asti. Monet sitä tutkivat, ja ymmärrys lisääntyy.'),
(1691047,58,27,12,5,'Ja minä, Daniel, näin, ja katso, siellä seisoi kaksi muuta, toinen virran tällä rannalla, toinen virran tuolla rannalla.'),
(1691048,58,27,12,6,'Ja toinen sanoi pellavapukuiselle miehelle, joka oli virran vetten yläpuolella: "Kuinka kauan on vielä näitten ihmeellisten asiain loppuun?"'),
(1691049,58,27,12,7,'Ja minä kuuntelin pellavapukuista miestä, joka oli virran vetten yläpuolella, ja hän nosti oikean ja vasemman kätensä taivasta kohti ja vannoi hänen kauttansa, joka elää iankaikkisesti: "Siihen on vielä aika, kaksi aikaa ja puoli aikaa. Ja kun pyhän kansan yhden osan hajotus on loppunut, silloin nämä kaikki täyttyvät."'),
(1691050,58,27,12,8,'Ja minä kuulin, mutta en ymmärtänyt, ja minä sanoin: "Herrani, mikä on oleva näitten päätös?"'),
(1691051,58,27,12,9,'Niin hän sanoi: "Mene, Daniel, sillä ne sanat pysyvät lukittuina ja sinetöityinä lopun aikaan asti.'),
(1691052,58,27,12,10,'Monet puhdistetaan, kirkastetaan ja koetellaan, mutta jumalattomat pysyvät jumalattomina, eikä yksikään jumalaton ymmärrä tätä, mutta taidolliset ymmärtävät.'),
(1691053,58,27,12,11,'Ja siitä ajasta, jolloin jokapäiväinen uhri poistetaan ja hävityksen kauhistus asetetaan, on oleva tuhat kaksisataa yhdeksänkymmentä päivää.'),
(1691054,58,27,12,12,'Autuas se, joka odottaa ja saavuttaa tuhat kolmesataa kolmekymmentä viisi päivää.'),
(1691055,58,28,1,1,'Herran sana, joka tuli Hoosealle, Beerin pojalle, Juudan kuningasten Ussian, Jootamin, Aahaan ja Hiskian päivinä ja Israelin kuninkaan Jerobeamin, Jooaan pojan, päivinä.'),
(1691056,58,28,1,2,'Kun Herra alkoi Hoosealle puhua, sanoi Herra Hoosealle: "Mene, ota itsellesi haureellinen vaimo ja haureudesta syntyneet lapset, sillä maa on peräti rikkonut avion luopumalla Herrasta".'),
(1691057,58,28,1,3,'Niin hän meni ja otti Goomerin, Diblaimin tyttären. Ja tämä tuli raskaaksi ja synnytti hänelle pojan.'),
(1691058,58,28,1,4,'Ja Herra sanoi hänelle: "Pane hänelle nimeksi Jisreel, sillä vähän aikaa vielä, ja minä kostan Jisreelin verivelat Jeehun suvulle ja teen lopun Israelin heimon kuningaskunnasta.'),
(1691059,58,28,1,5,'Ja sinä päivänä minä särjen Israelin jousen Jisreelin laaksossa."'),
(1691060,58,28,1,6,'Ja vaimo tuli jälleen raskaaksi ja synnytti tyttären, ja Herra sanoi Hoosealle: "Pane hänelle nimeksi Loo-Ruhama, sillä en minä enää tästedes armahda Israelin heimoa, niin että antaisin heille anteeksi.'),
(1691061,58,28,1,7,'Mutta Juudan heimoa minä armahdan: minä pelastan heidät Herran, heidän Jumalansa, avulla, mutta en pelasta heitä jousella, miekalla enkä sodalla, en hevosilla enkä ratsumiehillä."'),
(1691062,58,28,1,8,'Kun vaimo oli vieroittanut Loo-Ruhaman, tuli hän raskaaksi ja synnytti pojan.'),
(1691063,58,28,1,9,'Ja Herra sanoi: "Pane hänelle nimeksi Loo-Ammi, sillä te ette ole minun kansani, enkä minä tahdo olla teidän omanne.'),
(1691064,58,28,1,10,'(2:1) Mutta israelilaisten luku on oleva niinkuin meren hiekka, jota ei voi mitata eikä lukea. Ja siinä paikassa, jossa heille on sanottu: ''Te ette ole minun kansani'', heille sanotaan: ''Elävän Jumalan lapset!'''),
(1691065,58,28,1,11,'Ja Juudan miehet ja Israelin miehet kokoontuvat yhteen ja asettavat itsellensä yhteisen pään; ja he lähtevät sotaan siitä maasta, sillä suuri on Jisreelin päivä.'),
(1691066,58,28,2,1,'Sanokaa veljiänne Ammiksi ja sisarianne Ruhamaksi."'),
(1691067,58,28,2,2,'"Riidelkää äitinne kanssa, riidelkää, sillä ei hän ole minun vaimoni, enkä minä ole hänen miehensä. Poistakoon hän haureutensa kasvoistansa ja aviorikoksensa rintainsa välistä,'),
(1691068,58,28,2,3,'(2:5) etten minä riisuisi häntä alasti ja asettaisi häntä, niinkuin hän oli syntymänsä päivänä, etten tekisi häntä erämaan kaltaiseksi, saattaisi häntä kuivan maan kaltaiseksi ja kuolettaisi häntä janoon.'),
(1691069,58,28,2,4,'Ja hänen lapsiansa minä en armahda, sillä he ovat haureudesta syntyneitä lapsia.'),
(1691070,58,28,2,5,'Sillä heidän äitinsä on harjoittanut haureutta, heidän kantajansa on häpeällisesti elänyt, hän on sanonut: ''Minä kuljen rakastajaini perässä, jotka antavat minulle leipäni ja veteni, villani ja pellavani, öljyni ja juomani''.'),
(1691071,58,28,2,6,'Sentähden, katso, minä aitaan sinun tiesi orjantappuroilla, minä muuraan muurin hänen eteensä, niin ettei hän löydä polkujansa.'),
(1691072,58,28,2,7,'Ja hän ajaa takaa rakastajiansa, mutta ei heitä saavuta; etsii heitä, mutta ei löydä. Ja hän on sanova: ''Minä menen takaisin entisen mieheni luokse, sillä parempi oli minulla olo silloin kuin nyt''.'),
(1691073,58,28,2,8,'Hän ei ole tajunnut, että minä olen hänelle antanut jyvät ja viinin ja öljyn, olen kartuttanut hänelle hopeata ja myös kultaa, joka on käytetty Baalin hyväksi.'),
(1691074,58,28,2,9,'Sentähden minä otan takaisin jyväni ajallansa ja viinini määräaikanansa ja tempaan pois villani ja pellavani, jonka piti peittää hänen alastomuutensa.'),
(1691075,58,28,2,10,'Nyt minä paljastan hänen häpynsä hänen rakastajainsa silmäin eteen, eikä kukaan ole pelastava häntä minun kädestäni.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691076,58,28,2,11,'Minä teen lopun kaikesta hänen ilonpidostansa: hänen juhlistansa, uusistakuistansa ja sapateistansa ja kaikista hänen pyhäpäivistänsä.'),
(1691077,58,28,2,12,'Ja minä hävitän hänen viiniköynnöksensä ja viikunapuunsa, joista hän on sanonut: ''Ne ovat minun portonpalkkani, jonka rakastajani ovat minulle antaneet''. Minä teen ne metsäksi, ja metsän eläimet syövät niitä.'),
(1691078,58,28,2,13,'Ja minä kostan hänelle baalien päivät, joina hän niille poltti uhreja, koristi itsensä renkaillaan ja kaulakäädyillään ja kulki rakastajainsa jäljessä, mutta unhotti minut, sanoo Herra.'),
(1691079,58,28,2,14,'Sentähden, katso, minä taivuttelen hänet, kuljetan hänet erämaahan ja viihdyttelen häntä.'),
(1691080,58,28,2,15,'Minä annan hänelle sieltä alkaen hänen viinimäkensä ynnä Aakorin laakson toivon oveksi, ja hän on oleva siellä kuuliainen niinkuin nuoruutensa päivinä, niinkuin sinä päivänä, jona hän Egyptin maasta läksi.'),
(1691081,58,28,2,16,'Sinä päivänä, sanoo Herra, sinä puhuttelet minua: ''Minun mieheni'', etkä enää puhuttele minua: ''Minun Baalini'';'),
(1691082,58,28,2,17,'ja minä poistan baalien nimet hänen suustansa, eikä niiden nimiä enää mainita.'),
(1691083,58,28,2,18,'Ja sinä päivänä minä teen heidän hyväksensä liiton metsän eläinten ja taivaan lintujen kanssa ja maan matelevaisten kanssa; ja jousen ja miekan ja sodan minä särjen maasta ja annan heidän asua turvassa.'),
(1691084,58,28,2,19,'Ja minä kihlaan sinut itselleni ikiajoiksi, kihlaan sinut itselleni vanhurskaudella ja tuomiolla, armolla ja laupeudella,'),
(1691085,58,28,2,20,'kihlaan sinut itselleni uskollisuudella, ja sinä olet tunteva Herran.'),
(1691086,58,28,2,21,'Sinä päivänä minä kuulen, sanoo Herra, minä kuulen taivasta, ja se kuulee maata,'),
(1691087,58,28,2,22,'ja maa kuulee jyviä, viiniä ja öljyä, ja nämä kuulevat Jisreeliä.'),
(1691088,58,28,2,23,'(2:25) Ja minä kylvän hänet itselleni tähän maahan, minä armahdan Loo-Ruhamaa ja sanon Loo-Ammille: ''Sinä olet minun kansani''; ja hän vastaa: ''Minun Jumalani''."'),
(1691089,58,28,3,1,'Sitten sanoi Herra minulle: "Mene vielä ja rakasta naista, jota hänen puolisonsa rakastaa, mutta joka rikkoo avion, niinkuin Herra rakastaa israelilaisia, mutta nämä kääntyvät muiden jumalien puoleen ja rakastavat rypälekakkuja".'),
(1691090,58,28,3,2,'Niin minä hankin hänet itselleni viidellätoista sekelillä hopeata ynnä hoomer-mitalla ja letek-mitalla ohria.'),
(1691091,58,28,3,3,'Ja minä sanoin hänelle: "Ole kauan aikaa minua varten; älä harjoita haureutta äläkä mene muille miehille. Minä myös teen samoin sinua kohtaan."'),
(1691092,58,28,3,4,'Sillä kauan aikaa saavat israelilaiset olla ilman kuningasta ja ruhtinasta, ilman uhria ja patsasta, ilman kasukkaa ja kotijumalia.'),
(1691093,58,28,3,5,'Senjälkeen israelilaiset kääntyvät ja etsivät Herraa, Jumalaansa, ja Daavidia, kuningastansa. Vavisten he lähestyvät Herraa ja hänen hyvyyttänsä päivien lopulla.'),
(1691094,58,28,4,1,'Kuulkaa Herran sana, te israelilaiset, sillä Herralla on oikeudenkäynti maan asukasten kanssa; sillä ei ole uskollisuutta, ei laupeutta eikä Jumalan tuntemusta maassa.'),
(1691095,58,28,4,2,'Vannotaan ja valhetellaan, murhataan, varastetaan ja rikotaan aviot, murtaudutaan taloihin, ja verityö verityötä seuraa.'),
(1691096,58,28,4,3,'Sentähden maa murehtii, ja kaikki siinä asuvaiset nääntyvät, metsän eläimet ja taivaan linnut; myöskin kalat merestä katoavat.'),
(1691097,58,28,4,4,'Älköön vain kukaan nuhdelko, älköön kukaan ojentako, vaikka sinun kansasi on kuin pappien nuhtelijoita!'),
(1691098,58,28,4,5,'Niin sinä kompastut päivällä, myös profeetta kompastuu yhdessä sinun kanssasi yöllä; ja minä hävitän sinun äitisi.'),
(1691099,58,28,4,6,'Minun kansani joutuu häviöön, sillä se on taitoa vailla. Koska sinä olet hyljännyt taidon, hylkään minä sinut, niin ettet saa olla minun pappinani. Koska olet unhottanut Jumalasi lain, unhotan myös minä sinun lapsesi.'),
(1691100,58,28,4,7,'Niin paljon kuin heitä on, niin paljon he ovat tehneet syntiä minua vastaan. Minä muutan heidän kunniansa häpeäksi.'),
(1691101,58,28,4,8,'Minun kansani synnistä he saavat ruokansa, heidän pahoja tekojansa heidän sielunsa himoitsee.'),
(1691102,58,28,4,9,'Mutta papin on käyvä niinkuin kansankin: minä rankaisen häntä hänen vaelluksestansa ja kostan hänelle hänen tekonsa.'),
(1691103,58,28,4,10,'He syövät, mutta eivät tule ravituiksi, he harjoittavat haureutta, mutta eivät lisäänny, sillä he eivät ole tahtoneet ottaa vaaria Herrasta.'),
(1691104,58,28,4,11,'Haureus ja viini ja rypälemehu vievät järjen.'),
(1691105,58,28,4,12,'Minun kansani kysyy puultansa, ja sen sauva sille vastaa; sillä haureuden henki on eksyttäväinen: haureudessa he ovat luopuneet tottelemasta Jumalaansa.'),
(1691106,58,28,4,13,'Vuorten huipuilla he uhraavat, polttavat uhreja kukkuloilla, rautatammen, haavan ja tammen alla, sillä niiden varjo on suloinen. Sentähden tulee teidän tyttäristänne porttoja, ja teidän miniänne rikkovat avion.'),
(1691107,58,28,4,14,'En minä rankaise teidän tyttäriänne siitä, että he porttoja ovat, enkä miniöitänne siitä, että he avion rikkovat, sillä miehet itse poikkeavat syrjään porttojen kanssa ja uhraavat pyhäkköporttojen kanssa; ja ymmärtämätön kansa kukistuu.'),
(1691108,58,28,4,15,'Jos sinä, Israel, harjoitatkin haureutta, älköön Juuda saattako itseänsä syynalaiseksi: älkää lähtekö Gilgaliin, älkää menkö ylös Beet-Aaveniin älkääkä vannoko: "Niin totta kuin Herra elää".'),
(1691109,58,28,4,16,'Sillä niinkuin niskuri lehmä on Israel niskoitellut; nyt on Herra kaitseva heitä niinkuin karitsaa laajalla laitumella.'),
(1691110,58,28,4,17,'Efraim on liitossa epäjumalain kanssa - anna hänen olla.'),
(1691111,58,28,4,18,'Kun heidän juopottelunsa on lopussa, he harjoittavat törkeätä haureutta. Ne, jotka ovat hänen kilpensä, rakastavat häpeätä.'),
(1691112,58,28,4,19,'Tuuli siivillänsä ahdistaa häntä, he saavat häpeän uhriaterioistansa.'),
(1691113,58,28,5,1,'Kuulkaa tämä, te papit, tarkatkaa, Israelin heimo, ja ottakaa korviinne, kuninkaan huone: teille on tämä tuomio; sillä te olette olleet paula Mispalle, verkko, joka on levitetty Taaborille.'),
(1691114,58,28,5,2,'Luopiot ovat syvälle vajonneet turmiontekoon, mutta minä olen kuritus heille kaikille.'),
(1691115,58,28,5,3,'Minä tunnen Efraimin, eikä Israel ole minulta kätkössä; sillä nyt sinä, Efraim, olet haureutta harjoittanut, Israel on saastuttanut itsensä.'),
(1691116,58,28,5,4,'Heidän tekonsa eivät salli heidän kääntyä Jumalansa puoleen, sillä haureuden henki on heidän sisimmässänsä eivätkä he tunne Herraa.'),
(1691117,58,28,5,5,'Israelin ylpeys syyttää häntä vasten silmiä, ja Israel ja Efraim kompastuvat syntivelkaansa; myös Juuda kompastuu heidän kanssansa.'),
(1691118,58,28,5,6,'Lampainensa ja raavainensa he tulevat, etsiäksensä Herraa, mutta eivät löydä: hän on vetäytynyt heistä pois.'),
(1691119,58,28,5,7,'He ovat olleet uskottomat Herralle, sillä he ovat synnyttäneet vieraita lapsia. Nyt uudenkuun juhla syö heidät ja heidän peltonsa.'),
(1691120,58,28,5,8,'Puhaltakaa pasunaan Gibeassa, vaskitorveen Raamassa, nostakaa sotahuuto Beet-Aavenissa. Ovat jo sinun kintereilläsi, Benjamin!'),
(1691121,58,28,5,9,'Efraim on tuleva autioksi kurituksen päivänä. Israelin heimokuntia vastaan minä ilmoitan, mikä totta on.'),
(1691122,58,28,5,10,'Juudan ruhtinaat ovat tulleet rajan siirtäjäin kaltaisiksi. Minä vuodatan heidän päällensä vihani niinkuin vedet.'),
(1691123,58,28,5,11,'Sorrettu on Efraim, loukattu hänen oikeutensa, sillä hän tahtoi vaeltaa ihmiskäskyjen mukaan.'),
(1691124,58,28,5,12,'Minä olen Efraimille kuin koi ja Juudan heimolle kuin mätä.'),
(1691125,58,28,5,13,'Mutta kun Efraim näki sairautensa ja Juuda paiseensa, meni Efraim Assuriin, lähetti sanan sotaiselle kuninkaalle; mutta tämä ei voinut teitä parantaa, ei tehdä terveeksi teidän paisettanne.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691126,58,28,5,14,'Sillä minä olen Efraimille kuin leijona, Juudan heimolle kuin nuori jalopeura: minä, minä raatelen, menen ja kannan pois, eikä pelastajaa ole.'),
(1691127,58,28,5,15,'Minä menen takaisin paikoilleni, kunnes he ovat syystänsä kärsineet ja etsivät minun kasvojani: ahdistuksessansa he minua etsivät.'),
(1691128,58,28,6,1,'Tulkaa, palatkaamme Herran tykö, sillä hän on raadellut meitä, ja parantaa meidät, hän on lyönyt meitä, ja sitoo meidät.'),
(1691129,58,28,6,2,'Hän tekee meidät eläviksi kahden päivän kuluttua, kolmantena päivänä hän meidät herättää, ja me saamme elää hänen edessänsä.'),
(1691130,58,28,6,3,'Niin tuntekaamme, pyrkikäämme tuntemaan Herra: hänen nousunsa on varma kuin aamurusko, hän tulee meille kuin sade, kuin kevätsade, joka kostuttaa maan.'),
(1691131,58,28,6,4,'Mitä on minun tehtävä sinulle, Efraim, mitä on minun tehtävä sinulle, Juuda, kun teidän rakkautenne on kuin aamun pilvi, kuin varhain haihtuva kaste?'),
(1691132,58,28,6,5,'Sentähden minä olen antanut heille iskuja profeettain kautta, olen kuolettanut heitä suuni sanoilla. Ja sinun tuomiosi nousevat kuin aamun valo.'),
(1691133,58,28,6,6,'Sillä laupeutta minä haluan enkä uhria, ja Jumalan tuntemista enemmän kuin polttouhreja;'),
(1691134,58,28,6,7,'mutta he ovat ihmisten tavalla rikkoneet liiton: siinä he ovat olleet minulle uskottomat.'),
(1691135,58,28,6,8,'Gilead on pahantekijäin kaupunki, täynnä veren jälkiä.'),
(1691136,58,28,6,9,'Ja väijyväisten rosvojen kaltainen on pappien joukko: he murhaavat Sikemin tiellä; ilkitöitä he tekevät.'),
(1691137,58,28,6,10,'Israelin heimon keskuudessa minä olen nähnyt kauhistuttavia tekoja: siellä on Efraimin haureus, Israel on itsensä saastuttanut.'),
(1691138,58,28,6,11,'Myös sinun varallesi, Juuda, on asetettu elonleikkuu, silloin kun minä käännän kansani kohtalon.'),
(1691139,58,28,7,1,'Kun minä Israelia parannan, silloin tulevat julki Efraimin rikokset ja Samarian pahuudet; sillä he harjoittavat petosta, varas tunkeutuu sisään, ja rosvojoukko ryöstää ulkona.'),
(1691140,58,28,7,2,'Eivät he ajattele sydämessään, että minä muistan kaiken heidän pahuutensa. Nyt heidän tekonsa piirittävät heidät, ne ovat tulleet minun kasvojeni eteen.'),
(1691141,58,28,7,3,'He ilahuttavat pahuudellansa kuningasta ja valheillansa ruhtinaita.'),
(1691142,58,28,7,4,'Kaikki he ovat avionrikkojia; he ovat kuin leipojan sytyttämä uuni: hän jättää tulen kohentamatta taikinan sotkemisesta sen happanemiseen asti.'),
(1691143,58,28,7,5,'Meidän kuninkaamme päivänä ovat ruhtinaat sairaina viinin hehkusta. Hän lyö kättä pilkkaajain kanssa.'),
(1691144,58,28,7,6,'Sillä he ovat juonillaan saattaneet sydämensä kuumaksi kuin uuni; koko yön heidän leipojansa nukkuu, aamulla se palaa kuin liekitsevä tuli.'),
(1691145,58,28,7,7,'He ovat kaikki kuumia kuin uuni, he syövät tuomarinsa: kaikki heidän kuninkaansa ovat kaatuneet, ei yksikään niistä ole minua avuksi huutanut.'),
(1691146,58,28,7,8,'Efraim sekaantuu kansojen joukkoon. Efraim on tullut leivän kaltaiseksi, jota ei ole käännetty.'),
(1691147,58,28,7,9,'Muukalaiset syövät hänen voimansa, mutta ei hän sitä ymmärrä. Hänen hiuksensakin ovat jo harmaiksi käyneet, mutta hän ei ymmärrä.'),
(1691148,58,28,7,10,'Israelin ylpeys syyttää häntä vasten silmiä, eivätkä he palaja Herran, Jumalansa, tykö, eivät etsi häntä, vaikka kaikki näin on.'),
(1691149,58,28,7,11,'Efraim on tullut kyyhkysen kaltaiseksi, joka on tyhmä ja taitamaton: he huutavat avuksi Egyptiä, he menevät Assuriin.'),
(1691150,58,28,7,12,'Juuri kun ovat menossa, minä levitän verkkoni heidän päällensä ja pudotan heidät alas kuin taivaan linnut; minä kuritan heitä, niinkuin on julistettu heidän seurakunnallensa.'),
(1691151,58,28,7,13,'Voi heitä, sillä he ovat menneet minua pakoon! Häviö heille, sillä he ovat minusta luopuneet! Minä tahdoin lunastaa heidät, mutta he puhuivat minua vastaan valheita.'),
(1691152,58,28,7,14,'Eivät he huuda minun puoleeni sydämestänsä, vaan ulvovat vuoteissansa. Jyvien ja viinin tähden he kokoontuvat. Minua vastaan he niskoittelevat.'),
(1691153,58,28,7,15,'Minä olen heitä kurittanut, minä olen vahvistanut heidän käsivartensa, mutta minua vastaan he ovat aikoneet pahaa.'),
(1691154,58,28,7,16,'He kääntyvät, mutta eivät korkeutta kohti. He ovat kuin pettävä jousi. Heidän ruhtinaittensa pitää kaatuman miekkaan kieltensä kiukkuisuuden tähden. Tästä he saavat pilkan Egyptin maassa.'),
(1691155,58,28,8,1,'Suuhusi pasuna! Kotkan lailla Herran temppeliä vastaan - sillä he ovat rikkoneet minun liittoni, ovat luopuneet minun laistani!'),
(1691156,58,28,8,2,'Minun puoleeni he huutavat: "Minun Jumalani!" - "Me Israel, me tunnemme sinut".'),
(1691157,58,28,8,3,'Israel on hyljännyt hyvän. Vihollinen sitä vainotkoon.'),
(1691158,58,28,8,4,'He ovat asettaneet kuninkaita, mutta ei se ole ollut minusta; ovat asettaneet ruhtinaita, mutta minä en ole siitä tiennyt. Hopeansa ja kultansa he ovat tehneet epäjumalikseen, että tulisi hävitys.'),
(1691159,58,28,8,5,'Inhottava on sinun vasikkasi, Samaria; minun vihani on syttynyt heitä vastaan. Kuinka kauan? - Eivät he voi päästä rankaisematta.'),
(1691160,58,28,8,6,'Sillä Israelista se on tullut: seppä sen on tehnyt, eikä se ole jumala, vaan pirstaleiksi on menevä Samarian vasikka.'),
(1691161,58,28,8,7,'Sillä tuulta he kylvävät, ja myrskyä he leikkaavat. Ei se pääse korrelle, laiho ei tuota jauhoja; ja minkä ehkä tuottaa, sen muukalaiset nielevät.'),
(1691162,58,28,8,8,'Nielty on Israel. He ovat nyt pakanain seassa kelpaamattoman astian arvoiset.'),
(1691163,58,28,8,9,'Sillä Assuriin ovat he menneet - villiaasi, joka kulkee yksinänsä. Efraim ostelee lahjoilla rakasteluja.'),
(1691164,58,28,8,10,'Ostelkoot vain pakanain seassa, minä heidät nyt kokoan, ja he alkavat käydä vähäpätöisiksi ruhtinasten kuninkaan verojen painosta.'),
(1691165,58,28,8,11,'Koska Efraim on rakentanut paljon alttareita tehdäkseen syntiä, ovat alttarit tulleetkin hänelle synniksi.'),
(1691166,58,28,8,12,'Kirjoitinpa minä hänelle lakejani vaikka kymmentuhansin, muukalaisina niitä pidetään.'),
(1691167,58,28,8,13,'Minun uhrilahjoikseni he uhraavat lihaa ja syövät. Ei Herra niihin mielisty. Nyt hän muistaa heidän rikoksensa ja rankaisee heidän syntinsä: Egyptiin on heidän palattava.'),
(1691168,58,28,8,14,'Israel on unhottanut tekijänsä ja rakentanut palatseja, ja Juuda on rakentanut paljon varustettuja kaupunkeja; mutta minä lähetän tulen hänen kaupunkeihinsa, ja se kuluttaa niiden palatsit.'),
(1691169,58,28,9,1,'Älä iloitse, Israel, älä riemuitse, niinkuin muut kansat, sillä sinä olet haureudessa luopunut Jumalastasi, olet rakastanut portonpalkkoja kaikilla viljan puimatanterilla.'),
(1691170,58,28,9,2,'Puimatanner ja viinikuurna eivät heitä elätä, rypälemehu hänet pettää.'),
(1691171,58,28,9,3,'Eivät he saa asua Herran maassa, vaan Efraimin on palattava Egyptiin, ja Assurissa he syövät saastaista.'),
(1691172,58,28,9,4,'Eivät he vuodata viiniä juomauhriksi Herralle, eivätkä heidän teurasuhrinsa hänelle kelpaa. Ne ovat heille kuin murheen leipä: kaikki, jotka sitä syövät, saastuttavat itsensä; sillä heidän leipänsä tulee heidän omaan nälkäänsä, ei tule se Herran temppeliin.'),
(1691173,58,28,9,5,'Mitä teette, kun tulee juhla-aika, Herran juhlapäivä?'),
(1691174,58,28,9,6,'Sillä katso, heidän on mentävä hävitystä pakoon: Egypti heidät kokoaa, Moof heidät hautaa. Orjantappurat valtaavat heidän hopeakalleutensa, ohdakkeita on oleva heidän majoissansa.'),
(1691175,58,28,9,7,'Rangaistuksen päivät tulevat, koston päivät tulevat, Israel saa tuntea sen. Hulluna on oleva profeetta, mieletönnä hengen mies sinun paljojen rikoksiesi ja paljon vainoamisen tähden.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691176,58,28,9,8,'Efraim on väijyjä minun Jumalaani vastaan. Profeetta - hänen kaikilla teillään on pyydystäjän paula, vainoamista on hänen Jumalansa temppelissä.'),
(1691177,58,28,9,9,'He ovat syvälle vajonneet turmiontekoon niinkuin Gibean päivinä. Hän muistaa heidän rikoksensa, rankaisee heidän syntinsä.'),
(1691178,58,28,9,10,'Niinkuin rypäleet erämaassa minä löysin Israelin; niinkuin varhaishedelmät viikunapuussa, sen alkurunsaudessa, minä näin teidän isänne. He tulivat Baal-Peoriin, vihkiytyivät häpeäjumalalle ja tulivat kauhistaviksi, niinkuin tuo heidän rakastettunsa.'),
(1691179,58,28,9,11,'Efraim - lintuna lentää pois heidän kunniansa: ei synnyttämistä, ei raskautta, ei sikiämistä enää.'),
(1691180,58,28,9,12,'Ja vaikka he saisivat lapsensa isoiksi, teen minä heidät lapsettomiksi, niin ettei ihmisiä jää. Voi heitä itseänsäkin, kun minä heistä luovun!'),
(1691181,58,28,9,13,'Efraim on, kun minä sitä katson Tyyroon päin, istutettu laidunmaalle; mutta Efraimin täytyy viedä lapsensa surmaajalle.'),
(1691182,58,28,9,14,'Anna heille, Herra - mitä antaisitkaan? - anna heille hedelmätön kohtu ja kuivettuneet rinnat.'),
(1691183,58,28,9,15,'Kaikki heidän pahuutensa on Gilgalissa, sillä siellä minä rupesin heitä vihaamaan. Heidän tekojensa pahuuden tähden minä karkoitan heidät temppelistäni pois. En minä enää heitä rakasta: kaikki heidän ruhtinaansa ovat niskureita.'),
(1691184,58,28,9,16,'Efraim on hakattu maahan, heidän juurensa on kuivettunut: hedelmää he eivät tee. Ja jos synnyttävätkin, kuoletan minä heidän kohtunsa kalleimmat.'),
(1691185,58,28,9,17,'Minun Jumalani on hylkäävä heidät, sillä he eivät ole häntä totelleet. He joutuvat pakolaisiksi pakanain sekaan.'),
(1691186,58,28,10,1,'Israel oli rehevä viiniköynnös, joka teki hedelmiä. Mitä runsaampi sen hedelmä oli, sitä runsaammin se teki alttareita; mitä parempi sen maa oli, sitä parempia patsaita se pystytti.'),
(1691187,58,28,10,2,'Liukas oli heidän sydämensä; nyt he saavat siitä kärsiä: hän särkee heidän alttarinsa, hävittää heidän patsaansa.'),
(1691188,58,28,10,3,'Nyt he saavat sanoa: "Ei ole meillä kuningasta, sillä me emme ole peljänneet Herraa; ja mitä hyvää kuningas meille tekisi?"'),
(1691189,58,28,10,4,'He puheita pitävät, väärin vannovat, liittoja tekevät; mutta tuomio versoo kuin koiruoho pellon vaosta.'),
(1691190,58,28,10,5,'Beet-Aavenin vasikkain tähden joutuvat pelkoon Samarian asukkaat. Sillä vasikan tähden vaikeroi sen kansa, ja vasikan tähden sen papit vapisevat, sen kunnian tähden, kun se siltä vaeltaa pois.'),
(1691191,58,28,10,6,'Se itsekin viedään Assuriin lahjaksi sotaisalle kuninkaalle. Häpeän saa Efraim, ja häpeään joutuu Israel neuvonpiteistänsä,'),
(1691192,58,28,10,7,'Hukassa on Samaria kuninkaineen, on kuin vaahto veden pinnalla.'),
(1691193,58,28,10,8,'Aavenin uhrikukkulat, Israelin synti, hävitetään; orjantappuraa ja ohdaketta on kasvava heidän alttareillansa. Ja he sanovat vuorille: "Peittäkää meidät", ja kukkuloille: "Langetkaa meidän päällemme".'),
(1691194,58,28,10,9,'Gibean päivistä asti sinä olet syntiä tehnyt, Israel. Sinne he ovat asettuneet. Eikö saavuttaisi heitä Gibeassa sota, sota vääryyden miehiä vastaan?'),
(1691195,58,28,10,10,'Haluni mukaan minä olen heitä kurittava, ja heitä vastaan kokoontuvat kansat, kun minä kytken heidät kiinni heidän kahteen rikokseensa.'),
(1691196,58,28,10,11,'Efraim on lehmä, joka on totutettu mielellänsä puimaan, mutta minä käyn käsiksi hänen kauniiseen kaulaansa. Minä valjastan Efraimin: Juuda saa kyntää, Jaakob äestää.'),
(1691197,58,28,10,12,'Kylväkää itsellenne vanhurskauden kylvö, niin saatte leikata laupeuden leikkuun. Raivatkaa itsellenne uudispelto, silloin kun on aika etsiä Herraa, kunnes hän tulee ja antaa sataa, teille vanhurskautta.'),
(1691198,58,28,10,13,'Te olette kyntäneet jumalattomuutta, leikanneet vääryyttä ja syöneet valheen hedelmää; sillä sinä olet luottanut omaan tiehesi, sankariesi paljouteen.'),
(1691199,58,28,10,14,'On nouseva pauhina sinun kansojesi kesken, ja kaikki sinun linnoituksesi hävitetään, niinkuin Salman hävitti Beet-Arbelin sodan päivänä: äiti ruhjotaan lastensa päälle.'),
(1691200,58,28,10,15,'Tämän tekee teille Beetel teidän ylenpalttisen pahuutenne tähden: aamunkoitossa Israelin kuningas tuhotaan.'),
(1691201,58,28,11,1,'Kun Israel oli nuori, rakastin minä sitä, ja Egyptistä minä kutsuin poikani.'),
(1691202,58,28,11,2,'Aina kun kutsujat heitä kutsuivat, he menivät pois heidän kasvojensa edestä, uhrasivat baaleille ja polttivat uhreja epäjumalille.'),
(1691203,58,28,11,3,'Minä opetin Efraimin kävelemään. - Hän otti heidät käsivarsillensa. - Mutta he eivät ymmärtäneet, että minä heidät paransin.'),
(1691204,58,28,11,4,'Ihmissiteillä minä heitä vedin, rakkauden köysillä; minä ikäänkuin nostin ikeen heidän leukapieliltänsä, kumarruin heidän puoleensa ja syötin.'),
(1691205,58,28,11,5,'Eivätkö he joutuisi jälleen Egyptin maahan, eikö Assur tulisi heille kuninkaaksi, koska he eivät ole tahtoneet kääntyä?'),
(1691206,58,28,11,6,'Miekka on riehuva hänen kaupungeissansa, on hävittävä hänen salpansa, on syövä syötävänsä, heidän neuvonpiteittensä takia.'),
(1691207,58,28,11,7,'Minun kansallani on halu kääntyä minusta pois; ja kun sitä kutsutaan korkeutta kohti, ei kenkään heistä ylenny.'),
(1691208,58,28,11,8,'Kuinka minä jättäisin sinut, Efraim, heittäisin sinut, Israel? Kuinka jättäisin sinut niinkuin Adman, tekisin sinulle niinkuin Seboimille? Minun sydämeni kääntyy, minun säälini herää.'),
(1691209,58,28,11,9,'En minä pane täytäntöön vihani hehkua, en enää hävitä Efraimia. Sillä minä olen Jumala enkä ihminen, olen Pyhä sinun keskelläsi; en tule minä vihan tuimuudessa.'),
(1691210,58,28,11,10,'Ja he vaeltavat Herran jäljessä. Hän ärjyy kuin leijona - niin, hän ärjyy, ja vavisten tulevat lapset mereltä päin.'),
(1691211,58,28,11,11,'Vavisten he tulevat Egyptistä kuin linnut, Assurin maasta kuin kyyhkyset, ja minä saatan heidät asumaan kodeissansa, sanoo Herra.'),
(1691212,58,28,12,1,'Efraim on ympäröinyt minut valheella ja Israelin huone vilpillä. Juuda juoksee yhä valtoimena, välittämättä Jumalasta, Pyhästä, Totisesta.'),
(1691213,58,28,12,2,'Efraim tavoittelee tuulta, ajaa takaa itätuulta ja kartuttaa kaiken aikaa valhetta ja hävitystä; tehdään liittoja Assurin kanssa, ja viedään öljyä Egyptiin.'),
(1691214,58,28,12,3,'Mutta Herralla on oikeudenkäynti Juudan kanssa, ja hän tahtoo rangaista Jaakobia sen teitten mukaan, hän on kostava sille sen tekojen mukaan.'),
(1691215,58,28,12,4,'Äidin kohdussa tämä petti veljensä, ja miehuutensa voimassa hän taisteli Jumalan kanssa.'),
(1691216,58,28,12,5,'Hän taisteli enkelin kanssa ja voitti, hän itki ja rukoili tätä. Beetelissä tämä löysi hänet ja puhui siellä meidän kanssamme.'),
(1691217,58,28,12,6,'Herra, Jumala Sebaot - Herra on hänen nimensä.'),
(1691218,58,28,12,7,'Ja sinä - käänny Jumalasi tykö, noudata laupeutta ja oikeutta ja pane alati toivosi Jumalaasi.'),
(1691219,58,28,12,8,'Kanaan - hänen kädessänsä on petollinen vaaka, halusta hän tekee vääryyttä.'),
(1691220,58,28,12,9,'Efraim sanoo: "Olenpas rikastunut, olen saanut itselleni omaisuutta; ei mikään minun työansioni tuota minulle syyllisyyttä, joka olisi syntiä".'),
(1691221,58,28,12,10,'Mutta minä, joka olen Herra, sinun Jumalasi, hamasta Egyptin maasta lähtien, minä saatan vielä sinut asumaan teltoissa niinkuin juhlapäivinä.'),
(1691222,58,28,12,11,'Minä olen puhunut profeetoille, olen antanut paljon näkyjä ja puhunut vertauksia profeettain kautta.'),
(1691223,58,28,12,12,'Jos Gilead on pelkkää petosta ollutkin, niin he pelkäksi turhuudeksi tulevatkin. Gilgalissa on uhrattu härkiä, niinpä tuleekin heidän alttareistansa kuin kiviröykkiöitä, joita on pellon vaoilla.'),
(1691224,58,28,12,13,'Jaakob pakeni Aramin kedoille, ja Israel palveli naisen tähden, naisen tähden hän paimensi.'),
(1691225,58,28,12,14,'Mutta profeetan kautta vei Herra Israelin Egyptistä pois, ja profeetta sitä paimensi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691226,58,28,12,15,'Efraim nosti katkeran mielikarvauden. Hänen Herransa on heittävä hänen verivelkansa hänen päällensä ja kääntävä hänen häpäisevän menonsa häneen itseensä.'),
(1691227,58,28,13,1,'Milloin Efraim puhui, syntyi kauhu: korkealle kohosi hän Israelissa. Mutta hän joutui syynalaiseksi Baalin takia, ja hän kuoli.'),
(1691228,58,28,13,2,'Nyt he jatkavat synnintekoa, tekevät itselleen valettuja kuvia hopeastansa, epäjumalankuvia ymmärryksensä mukaan, taitoniekkain tekemiä kaikki tyynni. Niille he puhuvat; ihmisiä teurastavat, vasikoita suutelevat.'),
(1691229,58,28,13,3,'Sentähden he ovat kuin aamupilvi, kuin kaste, joka varhain haihtuu, kuin akanat, jotka puimatantereelta lentävät, kuin savu, joka häipyy ikkunasta.'),
(1691230,58,28,13,4,'Mutta minä olen Herra, sinun Jumalasi, hamasta Egyptin maasta lähtien; muuta Jumalaa sinä et tunne kuin minut, eikä ole muuta auttajaa kuin minä.'),
(1691231,58,28,13,5,'Minä tunsin sinut erämaassa, kuivassa maassa.'),
(1691232,58,28,13,6,'Sen mukaan kuin heidän laitumensa olivat, he kylläisiksi tulivat. He tulivat kylläisiksi, ja heidän sydämensä tuli ylpeäksi; sentähden he unhottivat minut.'),
(1691233,58,28,13,7,'Niin minusta tuli heille ikäänkuin leijona, niinkuin pantteri tien ohessa minä heitä väijyin.'),
(1691234,58,28,13,8,'Minä käyn heidän kimppuunsa kuin karhu, jolta on riistetty poikaset, revin heidän sydänkalvonsa ja syön heidät siinä paikassa kuin naarasleijona. Metsän pedot raatelevat heidät.'),
(1691235,58,28,13,9,'Se on sinun turmiosi, Israel, että olet minua vastaan, joka olen sinun apusi.'),
(1691236,58,28,13,10,'Missä on nyt sinun kuninkaasi, että hän auttaisi sinua kaikissa kaupungeissasi, ja sinun tuomarisi, joista olet sanonut: "Anna minulle kuningas ja ruhtinaat"?'),
(1691237,58,28,13,11,'Kuninkaan minä annan sinulle vihassani ja otan pois kiivastuksessani.'),
(1691238,58,28,13,12,'Efraimin rikos on sidottu kokoon, talteen on pantu hänen syntinsä.'),
(1691239,58,28,13,13,'Hänelle tulee synnyttäjän tuskat. Hän on älytön lapsi, sillä hän ei aikanansa tule esiin kohdusta.'),
(1691240,58,28,13,14,'Tuonelan kädestä minä heidät päästän, kuolemasta minä heidät lunastan. Missä on sinun ruttosi, kuolema, missä sinun surmasi, tuonela? Katumus on peitetty minun silmiltäni.'),
(1691241,58,28,13,15,'Vaikka hän veljien seassa on hedelmöitseväinen, on itätuuli tuleva, on nouseva Herran tuuli erämaasta, ja hänen kaivonsa kuivuu, ja hänen lähteensä ehtyy: se on ryöstävä hänen aarteensa, kaikki hänen kallisarvoiset kalunsa.'),
(1691242,58,28,14,1,'Samaria joutuu syystänsä kärsimään, koska se on niskoitellut Jumalaansa vastaan: he kaatuvat miekkaan, heidän pienet lapsensa ruhjotaan, ja heidän raskaat vaimonsa halkaistaan.'),
(1691243,58,28,14,2,'Palaja Israel, Herran, sinun Jumalasi tykö, sillä sinä olet kompastunut rikoksiisi.'),
(1691244,58,28,14,3,'Ottakaa mukaanne sanoja ja palatkaa Herran tykö ja sanokaa hänelle: "Anna anteeksi kaikki rikokset, ota armoihisi, niin me tuomme sinulle uhrimulleiksi huultemme uhrit.'),
(1691245,58,28,14,4,'Assur ei ole meitä auttava, hevosilla emme tahdo ratsastaa, emmekä enää sano kättemme teoille: ''Meidän jumalamme''; sillä sinussa saa orpo armon."'),
(1691246,58,28,14,5,'Minä parannan teidän luopumuksenne, omasta halustani minä teitä rakastan; sillä minun vihani on kääntynyt hänestä pois.'),
(1691247,58,28,14,6,'Minä olen oleva Israelille kuin kaste, se on kukoistava kuin lilja ja juurtuva syvälle kuin Libanon.'),
(1691248,58,28,14,7,'Sen vesat leviävät, sen kauneus on oleva kuin öljypuun ja sen tuoksu kuin Libanonin.'),
(1691249,58,28,14,8,'Sen varjossa asuvaiset kasvattavat jälleen viljaa ja kukoistavat kuin viiniköynnös. Sen maine on oleva kuin Libanonin viinin.'),
(1691250,58,28,14,9,'Efraim! Mitä on minulla enää tekemistä epäjumalien kanssa? Minä kuulen häntä, minä katson hänen puoleensa, minä, joka olen kuin viheriöitsevä kypressi: minusta on sinun hedelmäsi.'),
(1691251,58,29,1,1,'Herran sana, joka tuli Jooelille, Petuelin pojalle.'),
(1691252,58,29,1,2,'Kuulkaa tämä, te vanhimmat, ja ottakaa korviinne, kaikki maan asukkaat. Onko tällaista tapahtunut teidän päivinänne taikka teidän isienne päivinä?'),
(1691253,58,29,1,3,'Kertokaa tämä lapsillenne, ja teidän lapsenne kertokoot sen lapsillensa ja heidän lapsensa tulevalle polvelle:'),
(1691254,58,29,1,4,'Mitä kalvajasirkalta jäi, sen söi heinäsirkka. Ja mitä heinäsirkalta jäi, sen söi syöjäsirkka. Ja mitä syöjäsirkalta jäi, sen söi tuhosirkka.'),
(1691255,58,29,1,5,'Herätkää, te juopuneet, ja itkekää, valittakaa, kaikki viininjuojat, rypälemehun tähden, sillä se on otettu pois teidän suustanne.'),
(1691256,58,29,1,6,'Sillä minun maahani on hyökännyt kansa, väkevä ja epälukuinen. Sen hampaat ovat leijonan hampaat, ja sillä on naarasleijonan leukaluut.'),
(1691257,58,29,1,7,'Se on raastanut minun viiniköynnökseni ja katkonut minun viikunapuuni, on ne paljaiksi kuorinut ja karsinut; niiden oksat ovat valjenneet.'),
(1691258,58,29,1,8,'Valita niinkuin neitsyt, joka on vyöttäytynyt säkkiin nuoruutensa yljän tähden.'),
(1691259,58,29,1,9,'Pois on otettu ruokauhri ja juomauhri Herran huoneesta. Papit, jotka toimittavat Herran palvelusta, murehtivat.'),
(1691260,58,29,1,10,'Hävitetty on pelto, maa murehtii; sillä vilja on hävitetty, viinistä on tullut kato, öljy on kuivunut.'),
(1691261,58,29,1,11,'Peltomiehet ovat joutuneet häpeään, viinitarhurit valittavat nisun ja ohran tähden, sillä mennyt on pellon sato.'),
(1691262,58,29,1,12,'Viiniköynnöstä on kohdannut kato, viikunapuu on kuihtunut, granaattipuu ja myös palmu ja omenapuu; kaikki kedon puut ovat kuivettuneet. Niin, häpeään on joutunut ilo, ihmislasten joukosta pois.'),
(1691263,58,29,1,13,'Vyöttäytykää säkkiin, pitäkää valittajaiset, te papit; valittakaa, te jotka toimitatte palvelusta alttarilla. Käykää sisälle, viettäkää yö säkkeihin puettuina, te jotka toimitatte minun Jumalani palvelusta. Sillä poissa on teidän Jumalanne huoneesta ruokauhri ja juomauhri.'),
(1691264,58,29,1,14,'Kuuluttakaa pyhä paasto, kutsukaa koolle juhlakokous, kootkaa vanhimmat ja kaikki maan asukkaat Herran, teidän Jumalanne, huoneeseen ja huutakaa Herran puoleen.'),
(1691265,58,29,1,15,'Voi sitä päivää! Sillä lähellä on Herran päivä, ja se tulee niinkuin hävitys Kaikkivaltiaalta.'),
(1691266,58,29,1,16,'Eikö ole otettu meiltä ruoka silmäimme edestä sekä meidän Jumalamme huoneesta ilo ja riemu?'),
(1691267,58,29,1,17,'Surkastuneet ovat siemenjyvät multiensa alla, varastohuoneet autiot, aitat puretut, kun viljasta on kato.'),
(1691268,58,29,1,18,'Kuinka huokaa karja, kuinka hädissään ovat raavaslaumat, sillä ei ole niillä laidunta! Myös lammaslaumat joutuvat perikatoon.'),
(1691269,58,29,1,19,'Sinua, Herra, minä huudan, sillä tuli on kuluttanut erämaan laitumet ja liekki polttanut kaikki kedon puut.'),
(1691270,58,29,1,20,'Metsän eläimetkin sinua ikävöivät, sillä vesipurot ovat kuivuneet ja tuli on kuluttanut erämaan laitumet.'),
(1691271,58,29,2,1,'Puhaltakaa pasunaan Siionissa, toitottakaa torvia minun pyhällä vuorellani. Jokainen maan asukas on vapiseva, sillä Herran päivä tulee. Niin, se on lähellä:'),
(1691272,58,29,2,2,'pimeyden ja synkeyden päivä, pilvien ja pilkkopimeän päivä. Vuorille levinneenä niinkuin aamurusko on lukuisa ja väkevä kansa, jonka vertaista ei ole ollut ikiajoista asti eikä tämän jälkeen enää tule, tulevaisten polvien vuosiin saakka.'),
(1691273,58,29,2,3,'Sen edellä käy kuluttava tuli, sen jäljissä polttava liekki. Niinkuin Eedenin puutarha on maa sen edessä, sen jäljissä on autio erämaa, eikä jää ketään, joka olisi siltä pelastunut.'),
(1691274,58,29,2,4,'Ne ovat näöltänsä kuin hevoset, ja niinkuin ratsut ne juoksevat.'),
(1691275,58,29,2,5,'Ryskyen kuin sotavaunut ne hyppivät vuorten huipuilla, räiskyen kuin tulen liekki, joka kuluttaa oljet; ne ovat kuin väkevä kansa, sotarintaan asettunut.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691276,58,29,2,6,'Niitten edessä kansat vapisevat, kaikki kasvot kalpenevat.'),
(1691277,58,29,2,7,'Ne juoksevat kuin sankarit, kuin soturit ne nousevat muurille. Jokainen kulkee tietänsä suoraan, ei mutkittele polullansa.'),
(1691278,58,29,2,8,'Toinen ei sysi toistansa: jokainen kulkee omaa suuntaansa. Heittoaseitten välitse ne syöksyvät pysähtymättä.'),
(1691279,58,29,2,9,'Kaupunkiin ne hyökkäävät, ryntäävät muurille, nousevat taloihin, tulevat ikkunoista sisään kuin varas.'),
(1691280,58,29,2,10,'Niitten edessä maa vapisee, ja taivaat järkkyvät; aurinko ja kuu käyvät mustiksi, ja tähdet kadottavat valonsa.'),
(1691281,58,29,2,11,'Ja Herra antaa äänensä jylistä sotajoukkonsa edellä, sillä ylen lukuisa on hänen väkensä, sillä väkevä on hänen käskynsä täyttäjä, sillä suuri on Herran päivä ja sangen peljättävä; kuka voi sitä kestää?'),
(1691282,58,29,2,12,'Mutta vielä nytkin, sanoo Herra, kääntykää minun tyköni kaikesta sydämestänne, paastoten, itkien ja valittaen.'),
(1691283,58,29,2,13,'Reväiskää rikki sydämenne, älkää vaatteitanne, ja kääntykää Herran, teidän Jumalanne, tykö; sillä hän on armahtavainen ja laupias, pitkämielinen ja armosta rikas, ja hän katuu pahaa.'),
(1691284,58,29,2,14,'Ehkä hän vielä katuu ja jättää jälkeensä siunauksen: ruokauhrin ja juomauhrin Herralle, teidän Jumalallenne.'),
(1691285,58,29,2,15,'Puhaltakaa pasunaan Siionissa, kuuluttakaa pyhä paasto, kutsukaa koolle juhlakokous.'),
(1691286,58,29,2,16,'Kootkaa kansa, pitäkää pyhä seurakuntakokous, kerätkää vanhukset, kootkaa lapset ja rintoja imeväiset; lähteköön ylkä huoneestansa ja morsian kammiostansa.'),
(1691287,58,29,2,17,'Eteisen ja alttarin välillä itkekööt papit, jotka toimittavat Herran palvelusta, ja sanokoot: "Säästä, Herra, kansaasi äläkä anna perintöosaasi häväistäväksi, pakanain pilkattavaksi. Miksi pitäisi sanottaman kansain seassa: ''Missä on heidän Jumalansa?''"'),
(1691288,58,29,2,18,'Niin Herra kiivaili maansa puolesta ja sääli kansaansa.'),
(1691289,58,29,2,19,'Ja Herra vastasi ja sanoi kansalleen: Katso, minä lähetän teille viljaa, viiniä ja öljyä, niin että te tulette niistä ravituiksi. Enkä minä anna enää häväistä teitä pakanain seassa.'),
(1691290,58,29,2,20,'Ja mikä pohjoisesta tulee, sen minä karkoitan teistä kauas ja syöksen sen kuivaan ja autioon maahan, sen alkupään Idänmereen ja sen loppupään Länsimereen. Ja siitä nousee löyhkä, nousee katku. Sillä suuria se on yrittänyt.'),
(1691291,58,29,2,21,'Älä pelkää, maa. Iloitse ja riemuitse, sillä Herra on tehnyt suuria.'),
(1691292,58,29,2,22,'Älkää peljätkö, metsän eläimet, sillä erämaan laitumet viheriöivät, sillä puu kantaa hedelmänsä, viikunapuu ja viiniköynnös antavat voimansa.'),
(1691293,58,29,2,23,'Ja te, Siionin lapset, iloitkaa ja riemuitkaa Herrassa, teidän Jumalassanne, sillä hän antaa teille syyssateen, vanhurskauden mukaan, vuodattaa teille sateen, syyssateen ja kevätsateen, niinkuin entisaikaan.'),
(1691294,58,29,2,24,'Ja puimatantereet tulevat jyviä täyteen, ja kuurna-altaat pursuvat viiniä ja öljyä.'),
(1691295,58,29,2,25,'Ja minä korvaan teille ne vuodentulot, jotka heinäsirkka, syöjäsirkka, tuhosirkka ja kalvajasirkka söivät, minun suuri sotajoukkoni, jonka minä lähetin teitä vastaan.'),
(1691296,58,29,2,26,'Ja te syötte kyllälti ja tulette ravituiksi ja kiitätte Herran, teidän Jumalanne, nimeä, hänen, joka on tehnyt ihmeitä teitä kohtaan. Eikä minun kansani joudu häpeään, iankaikkisesti.'),
(1691297,58,29,2,27,'Ja te tulette tietämään, että Israelin keskellä olen minä. Ja minä olen Herra, teidän Jumalanne, eikä toista ole. Eikä minun kansani joudu häpeään, iankaikkisesti.'),
(1691298,58,29,2,28,'Näitten jälkeen minä olen vuodattava Henkeni kaiken lihan päälle, ja teidän poikanne ja tyttärenne ennustavat, vanhuksenne unia uneksuvat, nuorukaisenne näkyjä näkevät.'),
(1691299,58,29,2,29,'Ja myös palvelijain ja palvelijattarien päälle minä niinä päivinä vuodatan Henkeni.'),
(1691300,58,29,2,30,'Minä annan näkyä ihmeitä taivaalla ja maassa: verta ja tulta ja savupatsaita;'),
(1691301,58,29,2,31,'aurinko muuttuu pimeydeksi ja kuu vereksi, ennenkuin Herran päivä tulee, se suuri ja peljättävä.'),
(1691302,58,29,2,32,'Ja jokainen, joka huutaa avuksi Herran nimeä, pelastuu. Sillä Siionin vuorella ja Jerusalemissa ovat pelastuneet, niinkuin Herra on sanonut; ja pakoonpäässeitten joukossa ovat ne, jotka Herra kutsuu.'),
(1691303,58,29,3,1,'Sillä katso, niinä päivinä ja siihen aikaan, kun minä käännän Juudan ja Jerusalemin kohtalon,'),
(1691304,58,29,3,2,'minä kokoan kaikki pakanakansat, vien ne alas Joosafatin laaksoon ja käyn siellä oikeutta niitten kanssa kansani ja perintöosani, Israelin, tähden. Sillä he ovat hajottaneet sen pakanakansain sekaan, ovat jakaneet minun maani'),
(1691305,58,29,3,3,'ja heittäneet minun kansastani arpaa; ovat antaneet pojan porttoa vastaan sekä myyneet tytön viinistä, jonka ovat juoneet.'),
(1691306,58,29,3,4,'Mitä on teillä sanomista minulle, teilläkin, Tyyro ja Siidon ja kaikki filistealaisten alueet? Tahdotteko te kostaa minulle, mitä minä olen tehnyt, vai itse tehdä minulle jotakin? Nopeasti, kiiruusti minä annan koston kohdata teidän päätänne siitä, mitä olette tehneet,'),
(1691307,58,29,3,5,'te, jotka olette ottaneet minun hopeani ja kultani, vieneet minun ihanat kalleuteni temppeleihinne'),
(1691308,58,29,3,6,'sekä myyneet Juudan ja Jerusalemin lapsia jaavanilaisille, poistaaksenne heidät kauas omalta maaltansa.'),
(1691309,58,29,3,7,'Katso, minä herätän heidät liikkeelle siitä paikasta, johon te olette heidät myyneet, ja annan koston teostanne kohdata teidän päätänne:'),
(1691310,58,29,3,8,'minä myyn teidän poikianne ja tyttäriänne Juudan poikien käsiin, ja he myyvät ne sabalaisille, kaukaiselle kansalle. Sillä Herra on puhunut.'),
(1691311,58,29,3,9,'Julistakaa tämä pakanakansain seassa, alkakaa pyhä sota, innostakaa sankareita, lähestykööt, hyökätkööt kaikki soturit.'),
(1691312,58,29,3,10,'Takokaa vantaanne miekoiksi ja vesurinne keihäiksi. Sanokoon heikko: "Minä olen sankari".'),
(1691313,58,29,3,11,'Käykää avuksi, tulkaa, kaikki kansakunnat joka taholta. He kokoontuvat sinne. Anna, Herra, sankariesi astua sinne alas.'),
(1691314,58,29,3,12,'Lähtekööt liikkeelle, hyökätkööt kansakunnat Joosafatin laaksoon; sillä siellä hän istuu tuomitsemassa kaikkia pakanakansoja, joka taholta tulleita.'),
(1691315,58,29,3,13,'Lähettäkää sirppi, sillä sato on kypsynyt. Tulkaa polkemaan, sillä kuurna on täynnä ja kuurna-altaat pursuvat ylitse; sillä heidän pahuutensa on suuri.'),
(1691316,58,29,3,14,'Meluavia joukkoja, meluavia joukkoja ratkaisulaaksossa! Sillä lähellä on Herran päivä ratkaisulaaksossa.'),
(1691317,58,29,3,15,'Aurinko ja kuu käyvät mustiksi, ja tähdet kadottavat valonsa.'),
(1691318,58,29,3,16,'Herra ärjyy Siionista ja antaa äänensä kuulua Jerusalemista, ja taivaat ja maa järkkyvät; mutta Herra on kansansa suoja, Israelin lasten turva.'),
(1691319,58,29,3,17,'Ja te tulette tietämään, että minä olen Herra, teidän Jumalanne, joka asun Siionissa, pyhällä vuorellani. Ja Jerusalem on oleva pyhä, ja vieraat eivät enää kulje sen läpi.'),
(1691320,58,29,3,18,'Sinä päivänä vuoret tiukkuvat rypälemehua, ja kukkulat vuotavat maitoa; kaikissa Juudan puronotkoissa virtaa vettä, ja Herran huoneesta juoksee lähde, ja se kastelee Akasialaakson.'),
(1691321,58,29,3,19,'Egypti tulee autioksi, ja Edom tulee autioksi erämaaksi väkivallan tähden, jota ne ovat tehneet Juudan lapsille, kun ovat vuodattaneet viatonta verta heidän maassansa.'),
(1691322,58,29,3,20,'Mutta Juuda on oleva asuttu iankaikkisesti ja Jerusalem polvesta polveen.'),
(1691323,58,30,1,1,'Aamoksen sanat, hänen, jolla oli lammaslaumoja Tekoassa; mitä hän näyssä näki Israelista Ussian, Juudan kuninkaan, päivinä ja Jerobeamin, Jooaan pojan, Israelin kuninkaan, päivinä, kaksi vuotta ennen maanjäristystä.'),
(1691324,58,30,1,2,'Ja hän sanoi: Herra ärjyy Siionista, hän jylisee Jerusalemista, ja paimenten laitumet lakastuvat, ja Karmelin laki kuivuu.'),
(1691325,58,30,1,3,'Näin sanoo Herra: Damaskon kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Koska he ovat puineet Gileadin rautaisilla puimaäkeillä,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691326,58,30,1,4,'sentähden minä lähetän tulen Hasaelin linnaa vastaan, ja se kuluttaa Benhadadin palatsit.'),
(1691327,58,30,1,5,'Minä särjen Damaskon salvat, ja minä hävitän Bikat-Aavenin asukkaat ja Beet-Edenin valtikanpitäjät, ja Aramin kansa viedään pakkosiirtolaisuuteen Kiiriin, sanoo Herra.'),
(1691328,58,30,1,6,'Näin sanoo Herra: Gassan kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Koska he ovat vieneet pakkosiirtolaisuuteen ja luovuttaneet Edomille kaiken väen,'),
(1691329,58,30,1,7,'sentähden minä lähetän tulen Gassan muuria vastaan, ja se kuluttaa sen palatsit.'),
(1691330,58,30,1,8,'Minä hävitän Asdodin asukkaat ja Askelonin valtikanpitäjät, ja minä käännän käteni Ekronia vastaan, ja filistealaisten tähteet hukkuvat, sanoo Herra, Herra.'),
(1691331,58,30,1,9,'Näin sanoo Herra: Tyyron kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Koska he ovat luovuttaneet kaiken väen pakkosiirtolaisina Edomille eivätkä ole muistaneet veljesliittoa,'),
(1691332,58,30,1,10,'sentähden minä lähetän tulen Tyyron muuria vastaan, ja se kuluttaa sen palatsit.'),
(1691333,58,30,1,11,'Näin sanoo Herra: Edomin kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Koska se on vainonnut miekalla veljeänsä ja tukahduttanut kaiken armahtavaisuuden ja pitänyt ikuista vihaa ja säilyttänyt kiukkunsa ainaisesti,'),
(1691334,58,30,1,12,'sentähden minä lähetän tulen Teemania vastaan, ja se kuluttaa Bosran palatsit.'),
(1691335,58,30,1,13,'Näin sanoo Herra: Ammonilaisten kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Koska he ovat halkaisseet Gileadin raskaat vaimot, laajentaakseen aluettansa,'),
(1691336,58,30,1,14,'sentähden minä sytytän tulen Rabban muuria vastaan, ja se kuluttaa sen palatsit, sotahuudon kaikuessa sodan päivänä, myrskyn pauhatessa rajuilman päivänä.'),
(1691337,58,30,1,15,'Ja heidän kuninkaansa vaeltaa pakkosiirtolaisuuteen, hän ja hänen ruhtinaansa kaikki tyynni, sanoo Herra.'),
(1691338,58,30,2,1,'Näin sanoo Herra: Mooabin kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Koska se on polttanut Edomin kuninkaan luut kalkiksi,'),
(1691339,58,30,2,2,'sentähden minä lähetän tulen Mooabia vastaan, ja se kuluttaa Kerijotin palatsit. Ja Mooab kuolee sodan melskeessä, sotahuudon ja pasunan pauhinassa.'),
(1691340,58,30,2,3,'Ja minä hävitän tuomarin sen keskeltä, ja kaikki sen päämiehet minä tapan yhdessä sen kanssa, sanoo Herra.'),
(1691341,58,30,2,4,'Näin sanoo Herra: Juudan kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Koska he ovat hyljänneet Herran lain eivätkä ole pitäneet hänen käskyjänsä, vaan heidän valhejumalansa, joiden perässä jo heidän isänsä kulkivat, ovat heidät vietelleet,'),
(1691342,58,30,2,5,'sentähden minä lähetän tulen Juudaa vastaan, ja se kuluttaa Jerusalemin palatsit.'),
(1691343,58,30,2,6,'Näin sanoo Herra: Israelin kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Sillä he myyvät hurskaan rahasta ja köyhän kenkäparista,'),
(1691344,58,30,2,7,'polkevat maan tomuun vaivaisten pään ja vääntävät mutkaiseksi nöyrien tien. Ja poika ja isä käyvät saman naisen pariin häväisten minun pyhän nimeni.'),
(1691345,58,30,2,8,'He loikovat pantiksi otetuilla vaatteilla jokaisen alttarin ääressä ja juovat sakotettujen viiniä jumalansa huoneessa.'),
(1691346,58,30,2,9,'Ja kuitenkin minä hävitin heidän edestänsä amorilaiset, jotka olivat korkeakasvuiset kuin setrit ja vahvat kuin tammet, ja minä hävitin niiden hedelmän ylhäältä ja niiden juuret alhaalta.'),
(1691347,58,30,2,10,'Ja minä johdatin teidät Egyptin maasta ja kuljetin teitä erämaassa neljäkymmentä vuotta, että saisitte ottaa omaksenne amorilaisten maan.'),
(1691348,58,30,2,11,'Ja minä herätin teidän pojistanne profeettoja ja nuorukaisistanne nasiireja. Vai eikö niin ole, te israelilaiset? sanoo Herra.'),
(1691349,58,30,2,12,'Mutta te juotitte nasiireille viiniä, ja profeettoja te kielsitte sanoen: "Älkää ennustako".'),
(1691350,58,30,2,13,'Katso, minä rusennan teidät alallenne, niinkuin täyteen kuormattu puimajyrä rusentaa lyhteet.'),
(1691351,58,30,2,14,'Silloin nopeakaan ei pääse pakoon, ei väkevällä ole apua voimastaan, eikä sankari pelasta henkeänsä;'),
(1691352,58,30,2,15,'jousimies ei kestä paikallansa, nopeajalkainen ei pelastu, eikä ratsumies pelasta henkeänsä.'),
(1691353,58,30,2,16,'Ja sankareista rohkein pakenee alasti sinä päivänä, sanoo Herra.'),
(1691354,58,30,3,1,'Kuulkaa tämä sana, jonka Herra on puhunut teitä vastaan, te israelilaiset, koko sitä sukukuntaa vastaan, jonka minä olen johdattanut Egyptin maasta, sanoen:'),
(1691355,58,30,3,2,'Ainoastaan teidät minä olen valinnut kaikista maan sukukunnista; sentähden minä kostan teille kaikki teidän pahat tekonne.'),
(1691356,58,30,3,3,'Kulkeeko kaksi yhdessä, elleivät ole keskenänsä sopineet?'),
(1691357,58,30,3,4,'Ärjyykö leijona metsässä, ellei sillä ole raadeltavaa? Kiljuuko nuori leijona luolastansa, ellei se ole saalista saanut?'),
(1691358,58,30,3,5,'Käykö lintu maassa paulaan, ellei sen varalle ole pyydystä pantu? Nouseeko paula maasta saaliin siihen tarttumatta?'),
(1691359,58,30,3,6,'Puhalletaanko pasunaan kaupungissa, niin ettei kansa peljästy? Tahi tapahtuuko kaupungissa onnettomuutta, jota ei Herra ole tuottanut?'),
(1691360,58,30,3,7,'Sillä ei Herra, Herra, tee mitään ilmoittamatta salaisuuttaan palvelijoillensa profeetoille.'),
(1691361,58,30,3,8,'Leijona ärjyy: kuka ei pelkäisi? Herra, Herra puhuu: kuka ei ennustaisi?'),
(1691362,58,30,3,9,'Julistakaa Asdodin palatseille ja Egyptin maan palatseille ja sanokaa: Kokoontukaa Samarian vuorille ja katsokaa, mikä suuri meteli on sen keskellä ja mikä sorto sen sisällä.'),
(1691363,58,30,3,10,'He eivät ymmärrä tehdä sitä, mikä oikein on, sanoo Herra; he kokoovat väkivaltaa ja sortoa palatseihinsa.'),
(1691364,58,30,3,11,'Sentähden, näin sanoo Herra, Herra: Vihollinen on oleva kaikkialla maassa, ja hän kukistaa sinun linnoituksesi, ja sinun palatsisi ryöstetään.'),
(1691365,58,30,3,12,'Näin sanoo Herra: Niinkuin paimen saa pelastetuksi leijonan kidasta pari sääriluuta tai kappaleen korvaa, niin pelastuu israelilaisiakin, niitä, jotka istuvat Samariassa sohvankulmassa ja kirjosilkkisellä leposijalla.'),
(1691366,58,30,3,13,'Kuulkaa ja todistakaa Jaakobin heimoa vastaan, sanoo Herra, Herra, Jumala Sebaot:'),
(1691367,58,30,3,14,'Sinä päivänä, jona minä kostan Israelille hänen rikoksensa, minä kostan myös Beetelin alttareille, niin että alttarinsarvet hakataan irti ja putoavat maahan.'),
(1691368,58,30,3,15,'Ja minä sorran maahan talvihuoneen ja kesähuoneen, ja norsunluuhuoneet kukistuvat, ja paljoista huoneista tulee loppu, sanoo Herra.'),
(1691369,58,30,4,1,'Kuulkaa tämä sana, te Baasanin lehmät, jotka olette Samarian vuorella, jotka sorratte vaivaisia ja runtelette köyhiä, jotka sanotte herroillenne: "Tuokaa meille juomista".'),
(1691370,58,30,4,2,'Herra, Herra on vannonut pyhyytensä kautta: Totisesti, katso, päivät tulevat teille, jolloin teidät temmataan ylös koukuilla ja viimeisetkin teistä kalaongilla.'),
(1691371,58,30,4,3,'Ja muurin halkeamista te lähdette ulos, kukin suorinta tietä, ja teidät heitetään Harmoniin päin, sanoo Herra.'),
(1691372,58,30,4,4,'Menkää Beeteliin ja tehkää syntiä, ja Gilgaliin ja tehkää vielä enemmän syntiä; tuokaa aamulla teurasuhrinne, kolmantena päivänä kymmenyksenne.'),
(1691373,58,30,4,5,'Uhratkaa hapanta kiitosuhriksi, kuuluttakaa, julistakaa vapaaehtoisia lahjoja, sillä niinhän te haluatte, te israelilaiset, sanoo Herra, Herra.'),
(1691374,58,30,4,6,'Minä kyllä tein teidän hampaanne joutilaiksi kaikissa teidän kaupungeissanne ja tuotin leivän puutteen kaikkiin teidän paikkakuntiinne. Mutta te ette kääntyneet minun tyköni, sanoo Herra.'),
(1691375,58,30,4,7,'Minä pidätin teiltä sateen, kun vielä oli kolme kuukautta elonkorjuuseen. Minä annoin sataa toiselle kaupungille, mutta toiselle kaupungille en antanut sataa; toinen pelto sai sadetta, ja toinen, jolle ei satanut, kuivui.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691376,58,30,4,8,'Ja niin kaksi, kolme kaupunkia hoippui yhteen kaupunkiin vettä juomaan, saamatta kyllikseen. Mutta te ette kääntyneet minun tyköni, sanoo Herra.'),
(1691377,58,30,4,9,'Minä rankaisin teitä nokitähkillä ja viljanruosteella; teidän monet puutarhanne, viinimäkenne, viikunapuunne ja öljypuunne söi kalvajasirkka. Mutta te ette kääntyneet minun tyköni, sanoo Herra.'),
(1691378,58,30,4,10,'Minä lähetin teihin ruton niinkuin Egyptiin; minä tapoin miekalla teidän nuoret miehenne, ja teidän ratsunne otettiin saaliiksi; ja minä annoin löyhkän teidän leireistänne nousta teidän sieramiinne. Mutta te ette kääntyneet minun tyköni, sanoo Herra.'),
(1691379,58,30,4,11,'Minä panin toimeen hävityksen teidän seassanne, niinkuin Jumala hävitti Sodoman ja Gomorran, ja te olitte kuin tulesta temmattu kekäle. Mutta te ette kääntyneet minun tyköni, sanoo Herra.'),
(1691380,58,30,4,12,'Sentähden minä teen sinulle, Israel, näin. Koska minä tämän sinulle teen, niin valmistaudu, Israel, kohtaamaan Jumalaasi.'),
(1691381,58,30,4,13,'Sillä katso: hän on se, joka on tehnyt vuoret ja luonut tuulen, joka ilmoittaa ihmiselle, mikä hänen aivoituksensa on, joka tekee aamuruskon ja pimeyden ja joka kulkee maan kukkulain ylitse - Herra, Jumala Sebaot, on hänen nimensä.'),
(1691382,58,30,5,1,'Kuulkaa tämä Herran sana, itkuvirsi, jonka minä viritän teistä, te Israelin heimo.'),
(1691383,58,30,5,2,'Kaatunut on neitsyt Israel eikä enää nouse; hän viruu kaadettuna maassansa, eikä ole, kuka hänet nostaisi.'),
(1691384,58,30,5,3,'Sillä näin sanoo Herra, Herra: Kaupunkiin, josta ennen lähti tuhat, jää jäljelle sata; ja josta lähti sata, siihen jää kymmenen jäljelle, Israelin heimoa.'),
(1691385,58,30,5,4,'Sillä näin sanoo Herra Israelin heimolle: Etsikää minua, niin te saatte elää.'),
(1691386,58,30,5,5,'Älkää etsikö Beeteliä, älkää menkö Gilgaliin älkääkä vaeltako Beersebaan. Sillä Gilgal viedään pakkosiirtolaisuuteen, ja Beetel joutuu tuhon omaksi.'),
(1691387,58,30,5,6,'Etsikää Herraa, niin te saatte elää, ettei hän tulena tunkeutuisi Joosefin huoneeseen ja kuluttaisi sitä eikä olisi sammuttajaa Beetelillä -'),
(1691388,58,30,5,7,'te, jotka muutatte oikeuden koiruohoksi ja vanhurskauden maahan kukistatte.'),
(1691389,58,30,5,8,'Hän, joka on tehnyt Otavan ja Kalevanmiekan ja muuttaa synkeyden aamuksi ja pimentää päivän yöksi ja kutsuu kokoon meren vedet ja vuodattaa ne maan pinnalle - Herra on hänen nimensä,'),
(1691390,58,30,5,9,'hänen, joka äkisti tuottaa väkevälle hävityksen, ja niin tulee hävitys linnoitukseen.'),
(1691391,58,30,5,10,'He vihaavat sitä, joka portissa oikeutta puoltaa, ja totuuden puhuja on heille kauhistus.'),
(1691392,58,30,5,11,'Sentähden, koska te poljette vaivaista ja otatte häneltä viljaveroa, niin vaikka te rakennatte taloja hakatusta kivestä, te ette niissä asu; vaikka te istutatte ihania viinitarhoja, te ette niistä viiniä juo.'),
(1691393,58,30,5,12,'Sillä minä tiedän, että teidän rikoksenne ovat monet ja teidän syntinne raskaat: te vainoatte vanhurskasta ja otatte lahjuksia ja väännätte vääräksi portissa köyhäin asian.'),
(1691394,58,30,5,13,'Sentähden ymmärtäväinen vaikenee tänä aikana, sillä se on paha aika.'),
(1691395,58,30,5,14,'Etsikää hyvää, älkääkä pahaa, että te eläisitte. Silloin Herra, Jumala Sebaot, on oleva teidän kanssanne, niinkuin te sanotte.'),
(1691396,58,30,5,15,'Vihatkaa pahaa ja rakastakaa hyvää ja saattakaa oikeus voimaan portissa: ehkäpä Herra, Jumala Sebaot, armahtaa Joosefin jäännöstä.'),
(1691397,58,30,5,16,'Sillä näin sanoo Herra, Jumala Sebaot, Herra: Kaikilla toreilla on valitus, kaikilla kaduilla sanotaan: "Voi! Voi!" Peltomiehiä kutsutaan surun viettoon ja itkuvirren taitajia valittajaisiin.'),
(1691398,58,30,5,17,'Ja kaikissa viinitarhoissa on valitus, sillä minä käyn sinun keskitsesi, sanoo Herra.'),
(1691399,58,30,5,18,'Voi teitä, jotka toivotte Herran päivän tulemista. Miksi hyväksi on teille Herran päivä? Se on oleva pimeys, eikä valkeus -'),
(1691400,58,30,5,19,'ikäänkuin jos joku pakenisi leijonaa ja häntä kohtaisi karhu, tahi joku tulisi kotiin ja nojaisi kätensä seinään ja häntä pistäisi käärme.'),
(1691401,58,30,5,20,'Eikö Herran päivä ole pimeys, eikä valkeus, eikö se ole synkeys, jossa ei valoa ole?'),
(1691402,58,30,5,21,'Minä vihaan, minä halveksin teidän juhlianne enkä mielisty teidän juhlakokouksiinne.'),
(1691403,58,30,5,22,'Sillä vaikka te tuotte minulle polttouhreja ja ruokauhrejanne, eivät ne minulle kelpaa, enkä minä katso teidän yhteysuhrienne, syöttövasikkainne, puoleen.'),
(1691404,58,30,5,23,'Vie pois minun edestäni virttesi pauhina, en tahdo kuulla sinun harppujesi soittoa.'),
(1691405,58,30,5,24,'Mutta oikeus virratkoon kuin vesi ja vanhurskaus niinkuin ehtymätön puro.'),
(1691406,58,30,5,25,'Toitteko te teurasuhreja ja ruokauhreja minulle erämaassa neljänäkymmenenä vuotena, te Israelin heimo?'),
(1691407,58,30,5,26,'Te olette kantaneet kuningastanne Sikkutia ja Kijjunin-kuvianne, tähtijumalaanne, sitä, jonka te olette itsellenne tehneet.'),
(1691408,58,30,5,27,'Sentähden minä vien teidät pakkosiirtolaisuuteen tuolle puolelle Damaskon, sanoo Herra. Jumala Sebaot on hänen nimensä.'),
(1691409,58,30,6,1,'Voi suruttomia Siionissa, huolettomia Samarian vuorella, kansoista ensimmäisen ylimyksiä, joiden tykö Israelin heimo tulee!'),
(1691410,58,30,6,2,'Menkää Kalneen ja katsokaa, sieltä kulkekaa Suureen Hamatiin ja käykää filistealaisten Gatiin: ovatko ne paremmat kuin nämä valtakunnat, onko niiden alue suurempi kuin teidän alueenne?'),
(1691411,58,30,6,3,'Voi teitä, jotka lykkäätte kauas pahan päivän, mutta vedätte luoksenne väkivallan, valtaistuimelle istumaan;'),
(1691412,58,30,6,4,'jotka makaatte norsunluusohvilla ja venytte leposijoillanne, syötte karitsoita laumasta ja vasikoita navetasta;'),
(1691413,58,30,6,5,'jotka sepustatte lauluja harpulla säestäen ja sommittelette soittimia kuin mikäkin Daavid;'),
(1691414,58,30,6,6,'jotka juotte viiniä maljoista ja voitelette itsenne parhaalla öljyllä, mutta ette murehdi Joosefin sortumista!'),
(1691415,58,30,6,7,'Sentähden heidän nyt täytyy mennä pakkosiirtolaisuuteen pakkosiirtolaisten etunenässä. Silloin lakkaavat venyjäin ilohuudot.'),
(1691416,58,30,6,8,'Herra, Herra on vannonut itse kauttansa, sanoo Herra, Jumala Sebaot: Jaakobin ylpeys on minulle kauhistus, minä vihaan hänen palatsejansa, ja minä jätän alttiiksi kaupungin kaikkinensa.'),
(1691417,58,30,6,9,'Ja jos silloin kymmenen miestä jää jäljelle yhteen taloon, niin he kuolevat.'),
(1691418,58,30,6,10,'Ja jos kuolleen korjaa hänen omaisensa ja polttajansa, viedäkseen luut pois talosta, ja jos hän kysyy joltakin, joka on talon perimmäisessä sopessa: "Onko sinun tykönäsi vielä ketään?" niin tämä vastaa: "Ei ole", ja toinen sanoo: "Hiljaa!" - sillä Herran nimeä ei saa mainita.'),
(1691419,58,30,6,11,'Sillä katso, Herra antaa käskyn, ja hän lyö suuren talon kappaleiksi ja pienen talon pirstaleiksi.'),
(1691420,58,30,6,12,'Juoksevatko hevoset kallionseinää, kynnetäänkö sitä härjillä? Sillä te muutatte oikeuden myrkyksi ja vanhurskauden hedelmän koiruohoksi,'),
(1691421,58,30,6,13,'te, jotka iloitsette Loodabarista ja jotka sanotte: "Emmekö omalla voimallamme valloittaneet Karnaimia?"'),
(1691422,58,30,6,14,'Sillä katso, minä nostatan teitä vastaan, te Israelin heimo, sanoo Herra, Jumala Sebaot, kansan, joka on ahdistava teitä siitä asti, mistä mennään Hamatiin, hamaan Pajupuroon saakka.'),
(1691423,58,30,7,1,'Tämän näytti minulle Herra, Herra: Katso, hän loi heinäsirkkoja, kun äpäreheinä alkoi nousta; ja katso, se oli äpäreheinä kuninkaan niitosten jälkeen.'),
(1691424,58,30,7,2,'Ja kun ne olivat syöneet loppuun maan kasvit, sanoin minä: "Herra, Herra, anna anteeksi. Kuinka voi Jaakob pysyä, sillä hän on vähäinen?"'),
(1691425,58,30,7,3,'Niin Herra katui sitä. "Ei se ole tapahtuva", sanoi Herra.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691426,58,30,7,4,'Tämän näytti minulle Herra, Herra: Katso, Herra, Herra kutsui tulen toimittamaan tuomiota, ja se kulutti suuren syvyyden, ja se kulutti peltomaan.'),
(1691427,58,30,7,5,'Niin minä sanoin: "Herra, Herra, lakkaa jo. Kuinka voi Jaakob pysyä, sillä hän on vähäinen?"'),
(1691428,58,30,7,6,'Niin Herra katui sitä. "Ei sekään ole tapahtuva", sanoi Herra, Herra.'),
(1691429,58,30,7,7,'Tämän hän näytti minulle: Katso, Herra seisoi pystysuoralla muurilla, kädessänsä luotilanka.'),
(1691430,58,30,7,8,'Ja Herra sanoi minulle: "Mitä sinä näet, Aamos?" Minä vastasin: "Luotilangan". Ja Herra sanoi minulle: "Katso, minä olen laskenut luotilangan kansani Israelin keskelle. Minä en enää mene säästäen sen ohitse,'),
(1691431,58,30,7,9,'vaan Iisakin uhrikukkulat tulevat autioiksi ja Israelin pyhäköt raunioiksi. Ja minä nousen ja nostan miekan Jerobeamin sukua vastaan."'),
(1691432,58,30,7,10,'Silloin Amasja, Beetelin pappi, lähetti Jerobeamille, Israelin kuninkaalle, tämän sanan: "Aamos on tehnyt salaliiton sinua vastaan Israelin heimon keskuudessa. Ei maa kestä kaikkea, mitä hän puhuu.'),
(1691433,58,30,7,11,'Sillä näin on Aamos sanonut: ''Jerobeam kuolee miekkaan, ja Israel viedään pakkosiirtolaisuuteen, pois omasta maastansa''."'),
(1691434,58,30,7,12,'Ja Amasja sanoi Aamokselle: "Sinä näkijä, mene matkaasi ja pakene Juudan maahan, syö leipäsi siellä ja ennusta siellä.'),
(1691435,58,30,7,13,'Mutta Beetelissä älä ennusta enää, sillä se on kuninkaan pyhäkkö ja valtakunnan temppeli."'),
(1691436,58,30,7,14,'Niin Aamos vastasi ja sanoi Amasjalle: "En minä ole profeetta enkä profeetanoppilas, vaan minä olen paimen ja metsäviikunapuiden viljelijä.'),
(1691437,58,30,7,15,'Ja Herra otti minut laumojeni äärestä, ja Herra sanoi minulle: ''Mene ja ennusta minun kansaani Israelia vastaan''.'),
(1691438,58,30,7,16,'Kuule siis nyt Herran sana: Sinä sanot: ''Älä ennusta Israelia vastaan, äläkä saarnaa Iisakin heimoa vastaan''.'),
(1691439,58,30,7,17,'Sentähden, näin sanoo Herra: Sinun vaimosi joutuu portoksi kaupungissa, sinun poikasi ja tyttäresi kaatuvat miekkaan, sinun maasi jaetaan mittanuoralla, sinä itse kuolet saastaisessa maassa, ja Israel viedään pakkosiirtolaisuuteen, pois omasta maastansa."'),
(1691440,58,30,8,1,'Tämän näytti minulle Herra, Herra: Katso, oli korillinen kypsiä hedelmiä.'),
(1691441,58,30,8,2,'Ja hän sanoi: "Mitä sinä näet, Aamos?" Minä vastasin: "Korillisen kypsiä hedelmiä". Ja Herra sanoi minulle: "Minun kansani Israel on kypsä saamaan loppunsa: en minä enää mene säästäen sen ohitse.'),
(1691442,58,30,8,3,'Ja sinä päivänä palatsin laulut muuttuvat valitukseksi, sanoo Herra, Herra. Paljon on oleva ruumiita, joka paikkaan heitettyjä. Hiljaa!"'),
(1691443,58,30,8,4,'Kuulkaa tämä, te jotka poljette köyhiä ja tahdotte tehdä lopun maan nöyristä,'),
(1691444,58,30,8,5,'sanoen: "Milloin loppuu uusikuu, että saamme myydä viljaa, ja milloin sapatti, että saamme avata jyväaitan, pienentää eefa-mitan ja suurentaa painon ja pettää väärällä vaa''alla,'),
(1691445,58,30,8,6,'että saamme ostaa vaivaiset rahasta ja köyhän kenkäparista ja myydä akanoita jyvinä?"'),
(1691446,58,30,8,7,'Herra on vannonut hänen kauttansa, joka on Jaakobin kunnia: Totisesti, minä en ikinä unhota yhtäkään heidän tekoansa.'),
(1691447,58,30,8,8,'Eikö senkaltaisesta maa jo vapise ja kaikki sen asukkaat murehdi? Eikö se nouse kaikkinensa niinkuin Niili, kuohu ja alene niinkuin Egyptin virta?'),
(1691448,58,30,8,9,'Ja on tapahtuva sinä päivänä, sanoo Herra, Herra, että minä annan auringon laskea sydänpäivällä ja teen maan pimeäksi keskellä kirkasta päivää.'),
(1691449,58,30,8,10,'Minä muutan teidän juhlanne murheeksi ja kaikki teidän laulunne valitusvirsiksi. Minä panen kaikkien lanteille säkkipuvun ja teen kaljuksi jokaisen pään. Ja minä saatan teidät suremaan, niinkuin ainokaista poikaa surraan, ja se päättyy, niinkuin päättyy katkera päivä.'),
(1691450,58,30,8,11,'Katso, päivät tulevat, sanoo Herra, Herra, jolloin minä lähetän nälän maahan: en leivän nälkää enkä veden janoa, vaan Herran sanojen kuulemisen nälän.'),
(1691451,58,30,8,12,'Silloin he hoippuvat merestä mereen, pohjoisesta itään; he samoavat etsien Herran sanaa, mutta eivät löydä.'),
(1691452,58,30,8,13,'Sinä päivänä nääntyvät janoon kauniit neitsyet ja nuorukaiset,'),
(1691453,58,30,8,14,'ne, jotka vannovat sen nimeen, joka on Samarian syntivelka, ja sanovat: "Niin totta kuin sinun jumalasi elää, Daan, ja niin totta kuin elävät Beerseban menot!" - He kaatuvat eivätkä enää nouse.'),
(1691454,58,30,9,1,'Minä näin Herran seisovan alttarin ääressä, ja hän sanoi: Lyö pylväänpäihin, niin että kynnykset vapisevat, lyö ne pirstaleiksi kaikkien heidän päähänsä. Sitten minä tapan miekalla heistä viimeisetkin. Ei yksikään heistä pääse pakoon, ei yksikään heistä pelastu.'),
(1691455,58,30,9,2,'Vaikka he tuonelaan murtautuisivat, sieltäkin minun käteni heidät tempaa. Vaikka he taivaaseen nousisivat, sieltäkin minä syöksen heidät alas.'),
(1691456,58,30,9,3,'Vaikka he Karmelin laelle kätkeytyisivät, sieltäkin minä etsin ja tempaan heidät. Ja vaikka he meren pohjaan lymyäisivät minun silmieni edestä, sielläkin minä käsken käärmeen heitä pistämään.'),
(1691457,58,30,9,4,'Ja vaikka he vankeuteen vaeltaisivat vihollistensa edessä, sielläkin minä käsken miekan heidät tappamaan. Sillä minä kiinnitän katseeni heihin, heille pahaksi, ei hyväksi.'),
(1691458,58,30,9,5,'Herra, Herra Sebaot, hän, joka koskettaa maata, niin että se sulaa, että kaikki sen asukkaat murehtivat, että se nousee kaikkinensa niinkuin Niili ja alenee niinkuin Egyptin virta,'),
(1691459,58,30,9,6,'hän, joka rakentaa yliskammionsa taivaisiin ja perustaa holvinsa maan päälle, joka kutsuu meren vedet ja vuodattaa ne maan pinnalle - Herra on hänen nimensä.'),
(1691460,58,30,9,7,'Ettekö te, israelilaiset, ole minulle niinkuin etiopialaisetkin? sanoo Herra. Enkö minä johdattanut israelilaisia Egyptin maasta ja filistealaisia Kaftorista ja aramilaisia Kiiristä?'),
(1691461,58,30,9,8,'Katso, Herran, Herran silmät ovat syntistä valtakuntaa vastaan, ja minä hävitän sen maan pinnalta; kuitenkaan en minä Jaakobin heimoa kokonaan hävitä, sanoo Herra.'),
(1691462,58,30,9,9,'Sillä katso, minä käsken seuloa Israelin heimoa kaikkien kansain seassa, niinkuin seulalla seulotaan: ei jyvääkään putoa maahan.'),
(1691463,58,30,9,10,'Miekkaan kuolevat kaikki minun kansani syntiset, jotka sanovat: "Ei saavuta, ei kohtaa meitä onnettomuus".'),
(1691464,58,30,9,11,'Sinä päivänä minä pystytän jälleen Daavidin sortuneen majan ja korjaan sen repeämät ja pystytän sen luhistumat, ja rakennan sen sellaiseksi, kuin se oli muinaisina päivinä,'),
(1691465,58,30,9,12,'niin että he saavat omiksensa Edomin jäännöksen ja kaikki pakanakansat, jotka minun nimiini otetaan, sanoo Herra, joka tämän tekee.'),
(1691466,58,30,9,13,'Katso, päivät tulevat, sanoo Herra, jolloin kyntäjä tavoittaa leikkaajan ja rypäleitten polkija siemenenkylväjän, jolloin vuoret tiukkuvat rypälemehua ja kaikki kukkulat kuohkeiksi muuttuvat.'),
(1691467,58,30,9,14,'Silloin minä käännän kansani Israelin kohtalon, ja he rakentavat jälleen autiot kaupungit ja asuvat niissä, he istuttavat viinitarhoja ja juovat niiden viiniä, he tekevät puutarhoja ja syövät niiden hedelmiä.'),
(1691468,58,31,1,1,'Obadjan näky. Herra, Herra sanoo Edomista näin: Me olemme kuulleet sanoman Herralta, ja sanansaattaja on lähetetty kansakuntiin: "Nouskaa, nouskaamme sotaan sitä vastaan!"'),
(1691469,58,31,1,2,'Katso, vähäiseksi minä teen sinut kansojen seassa, ylen halveksittu olet sinä oleva.'),
(1691470,58,31,1,3,'Sinun sydämesi ylpeys on pettänyt sinut, joka asut kallionrotkoissa, istut korkealla ja sanot sydämessäsi: "Kuka voi syöstä minut maahan?"'),
(1691471,58,31,1,4,'Vaikka tekisit pesäsi korkealle niinkuin kotka ja vaikka sen sija olisi tähtien välissä, minä syöksen sinut sieltä alas, sanoo Herra.'),
(1691472,58,31,1,5,'Jos varkaat tulisivat kimppuusi, jos yölliset rosvot, kuinka voisit tulla niin hävitetyksi: eivätkö he varastaisi vain sen, mitä tarvitsevat? Jos viininkorjaajat tulisivat luoksesi, eivätkö he jättäisi jälkikorjuuta?'),
(1691473,58,31,1,6,'Mutta kuinka onkaan Eesau läpikotaisin etsitty, hänen kätkönsä pengotut!'),
(1691474,58,31,1,7,'Sinut on ajettu rajalle asti, kaikki liittolaisesi ovat sinut pettäneet. Ystäväsi ovat vieneet sinusta voiton, ovat panneet taritsemasi leivän paulaksi sinun eteesi. - Ei ole hänessä taitoa.'),
(1691475,58,31,1,8,'Totisesti, sinä päivänä, sanoo Herra, minä lopetan viisaat Edomista ja taidon Eesaun vuorelta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691476,58,31,1,9,'Ja sinun sankarisi, Teeman, kauhistuvat, niin että viimeinenkin mies häviää Eesaun vuorelta murhatöitten tähden.'),
(1691477,58,31,1,10,'Väkivallan tähden veljeäsi Jaakobia kohtaan peittää sinut häpeä, ja sinut hävitetään ikiajoiksi.'),
(1691478,58,31,1,11,'Sinä päivänä, jona sinäkin olit läsnä, päivänä, jona vieraat veivät pois hänen rikkautensa, jona muukalaiset tunkeutuivat sisään hänen porteistaan ja heittivät Jerusalemista arpaa, olit myöskin sinä niinkuin yksi heistä.'),
(1691479,58,31,1,12,'Mutta älä katso iloiten veljesi päivää, hänen onnettomuutensa päivää; älä ilku juutalaisia heidän turmionsa päivänä äläkä suullasi suurentele ahdistuksen päivänä.'),
(1691480,58,31,1,13,'Älä tunkeudu sisään minun kansani portista heidän hätäpäivänänsä. Älä katso iloiten, myös sinä, hänen onnettomuuttansa hänen hätäpäivänänsä. Älä ojenna kättäsi hänen rikkauteensa hänen hätäpäivänänsä.'),
(1691481,58,31,1,14,'Älä seiso tienhaarassa hävittämässä hänen pelastuneitansa. Älä luovuta hänen pakoonpäässeitänsä ahdistuksen päivänä.'),
(1691482,58,31,1,15,'Sillä lähellä on Herran päivä kaikkia pakanakansoja: Niinkuin sinä olet tehnyt, niin sinulle tehdään; kosto sinun teostasi kohtaa sinun omaa päätäsi.'),
(1691483,58,31,1,16,'Sillä niinkuin te olette juoneet minun pyhällä vuorellani, niin tulevat kaikki pakanakansat juomaan ainiaan: he juovat ja särpivät ja ovat, niinkuin ei heitä olisi ollutkaan.'),
(1691484,58,31,1,17,'Mutta Siionin vuorella saavat olla pelastuneet, ja se on oleva pyhä, ja Jaakobin heimo on perivä perintönsä.'),
(1691485,58,31,1,18,'Jaakobin heimo on oleva tuli ja Joosefin heimo liekki, mutta Eesaun heimo kuin olki, ja ne polttavat sen ja kuluttavat sen; eikä jää pakoonpäässyttä Eesaun heimosta. Sillä Herra on puhunut.'),
(1691486,58,31,1,19,'Ja he ottavat perinnöksensä Etelämaan ynnä Eesaun vuoren, Alankomaan ynnä filistealaiset; he ottavat perinnöksensä Efraimin maan ja Samarian maan, Benjaminin ynnä Gileadin.'),
(1691487,58,31,1,20,'Ja tästä väestä, israelilaisista, viedyt pakkosiirtolaiset ottavat perinnöksensä kanaanilaiset Sarpatiin asti. Ja Jerusalemin pakkosiirtolaiset, jotka ovat Sefaradissa, ottavat perinnöksensä Etelämaan kaupungit.'),
(1691488,58,32,1,1,'Joonalle, Amittain pojalle, tuli tämä Herran sana:'),
(1691489,58,32,1,2,'"Nouse, mene Niiniveen, siihen suureen kaupunkiin, ja saarnaa sitä vastaan; sillä heidän pahuutensa on noussut minun kasvojeni eteen".'),
(1691490,58,32,1,3,'Mutta Joona nousi paetaksensa Tarsiiseen Herran kasvojen edestä ja meni alas Jaafoon ja löysi laivan, joka oli lähtevä Tarsiiseen. Ja hän suoritti laivamaksun ja astui siihen mennäkseen heidän kanssansa Tarsiiseen, pois Herran kasvojen edestä.'),
(1691491,58,32,1,4,'Mutta Herra heitti suuren tuulen merelle, niin että merellä nousi suuri myrsky ja laiva oli särkymäisillään.'),
(1691492,58,32,1,5,'Niin merimiehet pelkäsivät ja huusivat avuksi itsekukin jumalaansa. Ja he heittivät mereen tavarat, mitä laivassa oli, keventääkseen sitä. Mutta Joona oli mennyt alas laivan pohjalle ja pannut maata, ja hän nukkui raskaasti.'),
(1691493,58,32,1,6,'Niin laivuri tuli hänen luoksensa ja sanoi hänelle: "Mitäs nukut? Nouse ja huuda jumalaasi. Ehkäpä se jumala muistaa meitä, niin ettemme huku."'),
(1691494,58,32,1,7,'Ja he sanoivat toisillensa: "Tulkaa, heittäkäämme arpaa, saadaksemme tietää, kenen tähden tämä onnettomuus on meille tullut". Mutta kun he heittivät arpaa, lankesi arpa Joonalle.'),
(1691495,58,32,1,8,'Niin he sanoivat hänelle: "Ilmoita meille, kenen tähden tämä onnettomuus on meille tullut. Mikä on toimesi ja mistä tulet? Mikä on sinun maasi ja mistä kansasta olet?"'),
(1691496,58,32,1,9,'Hän vastasi heille: "Minä olen hebrealainen, ja minä pelkään Herraa, taivaan Jumalaa, joka on tehnyt meren ja kuivan maan".'),
(1691497,58,32,1,10,'Niin miehet peljästyivät suuresti ja sanoivat hänelle: "Miksi olet tehnyt näin?" Sillä miehet tiesivät, että hän oli pakenemassa Herran kasvojen edestä; hän oli näet ilmaissut sen heille.'),
(1691498,58,32,1,11,'He sanoivat hänelle: "Mitä on meidän tehtävä sinulle, että meri tulisi meille tyveneksi?" Sillä meri myrskysi myrskyämistänsä.'),
(1691499,58,32,1,12,'Hän vastasi heille: "Ottakaa minut ja heittäkää minut mereen, niin meri teille tyventyy. Sillä minä tiedän, että tämä suuri myrsky on tullut teille minun tähteni."'),
(1691500,58,32,1,13,'Miehet soutivat päästäkseen jälleen kuivalle maalle, mutta eivät voineet, sillä meri myrskysi vastaan myrskyämistänsä.'),
(1691501,58,32,1,14,'Ja he huusivat Herraa ja sanoivat: "Voi, Herra, älä anna meidän hukkua tämän miehen hengen tähden äläkä lue syyksemme viatonta verta, sillä sinä, Herra, teet, niinkuin sinulle otollista on".'),
(1691502,58,32,1,15,'Sitten he ottivat Joonan ja heittivät hänet mereen, ja meri asettui raivostansa.'),
(1691503,58,32,1,16,'Ja miehet pelkäsivät suuresti Herraa, uhrasivat Herralle teurasuhrin ja tekivät lupauksia.'),
(1691504,58,32,2,1,'Mutta Herra toimitti suuren kalan nielaisemaan Joonan. Ja Joona oli kalan sisässä kolme päivää ja kolme yötä.'),
(1691505,58,32,2,2,'Ja Joona rukoili Herraa, Jumalaansa, kalan sisässä'),
(1691506,58,32,2,3,'ja sanoi: "Minä huusin ahdistuksessani Herraa, ja hän vastasi minulle. Tuonelan kohdussa minä huusin apua, ja sinä kuulit minun ääneni.'),
(1691507,58,32,2,4,'Sinä syöksit minut syvyyteen, merten sydämeen, ja virta ympäröitsi minut, kaikki sinun kuohusi ja aaltosi vyöryivät minun ylitseni.'),
(1691508,58,32,2,5,'Minä ajattelin: Olen karkoitettu pois sinun silmiesi edestä. Kuitenkin minä saan vielä katsella sinun pyhää temppeliäsi.'),
(1691509,58,32,2,6,'Vedet piirittivät minut aina sieluun asti, syvyys ympäröitsi minut, kaisla kietoutui päähäni.'),
(1691510,58,32,2,7,'Minä vajosin alas vuorten perustuksiin asti, maan salvat sulkeutuivat minun ylitseni iankaikkisesti. Mutta sinä nostit minun henkeni ylös haudasta, Herra, minun Jumalani.'),
(1691511,58,32,2,8,'Kun sieluni nääntyi minussa, minä muistin Herraa, ja minun rukoukseni tuli sinun tykösi, sinun pyhään temppeliisi.'),
(1691512,58,32,2,9,'Ne, jotka kunnioittavat vääriä jumalia, hylkäävät armonantajansa.'),
(1691513,58,32,2,10,'Mutta minä tahdon uhrata sinulle kiitoksen kaikuessa. Mitä olen luvannut, sen minä täytän. Herrassa on pelastus."'),
(1691514,58,32,2,11,'Sitten Herra käski kalaa, ja se oksensi Joonan kuivalle maalle.'),
(1691515,58,32,3,1,'Joonalle tuli toistamiseen tämä Herran sana:'),
(1691516,58,32,3,2,'"Nouse ja mene Niiniveen, siihen suureen kaupunkiin, ja saarnaa sille se saarna, minkä minä sinulle puhun".'),
(1691517,58,32,3,3,'Niin Joona nousi ja meni Niiniveen Herran sanan mukaan. Ja Niinive oli suuri kaupunki Jumalan edessä: kolme päivänmatkaa.'),
(1691518,58,32,3,4,'Ja Joona käveli kaupungissa aluksi yhden päivänmatkan ja saarnasi sanoen: "Vielä neljäkymmentä päivää, ja Niinive hävitetään".'),
(1691519,58,32,3,5,'Niin Niiniven miehet uskoivat Jumalaan, kuuluttivat paaston ja pukeutuivat säkkeihin, niin suuret kuin pienet.'),
(1691520,58,32,3,6,'Ja kun tieto tästä tuli Niiniven kuninkaalle, nousi hän valtaistuimeltaan, riisui yltään vaippansa, verhoutui säkkiin ja istui tuhkaan.'),
(1691521,58,32,3,7,'Ja hän huudatti Niinivessä: "Kuninkaan ja hänen ylimystensä määräys kuuluu: Älkööt ihmiset älköötkä eläimet - raavaat ja lampaat - maistako mitään, käykö laitumella tai vettä juoko.'),
(1691522,58,32,3,8,'Verhoutukoot ihmiset ja eläimet säkkeihin, huutakoot väkevästi Jumalaa ja kääntykööt itsekukin pois pahalta tieltänsä sekä väkivallasta, mikä heidän käsiänsä tahraa.'),
(1691523,58,32,3,9,'Ehkäpä Jumala jälleen katuu ja kääntyy vihansa hehkusta, niin ettemme huku."'),
(1691524,58,32,3,10,'Kun Jumala näki heidän tekonsa, että he kääntyivät pois pahalta tieltänsä, niin Jumala katui sitä pahaa, minkä hän oli sanonut tekevänsä heille, eikä tehnyt sitä.'),
(1691525,58,32,4,1,'Mutta Joona pahastui tästä kovin, ja hän vihastui.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691526,58,32,4,2,'Ja hän rukoili Herraa ja sanoi: "Voi Herra! Enkö minä sitä sanonut, kun olin vielä omassa maassani? Siksihän minä ehätin pakenemaan Tarsiiseen. Sillä minä tiesin, että sinä olet armahtavainen ja laupias Jumala, pitkämielinen ja armosta rikas, ja että sinä kadut pahaa.'),
(1691527,58,32,4,3,'Ja nyt, Herra, ota minun henkeni, sillä kuolema on minulle parempi kuin elämä."'),
(1691528,58,32,4,4,'Mutta Herra sanoi: "Onko vihastumisesi oikea?"'),
(1691529,58,32,4,5,'Niin Joona lähti kaupungista ja asettui kaupungin itäpuolelle. Hän teki itsellensä sinne lehtimajan ja kävi istumaan sen alle varjoon, kunnes näkisi, miten kaupungin oli käyvä.'),
(1691530,58,32,4,6,'Mutta Herra Jumala toimitti risiinikasvin kasvamaan Joonan pään ylitse, varjostamaan hänen päätänsä ja päästämään häntä hänen mielipahastaan. Ja Joona iloitsi suuresti risiinikasvista.'),
(1691531,58,32,4,7,'Mutta seuraavana päivänä, aamun sarastaessa, Jumala toimitti madon kalvamaan risiinikasvia, niin että se kuivui.'),
(1691532,58,32,4,8,'Ja auringon noustua Jumala toimitti tulikuuman itätuulen, ja aurinko paahtoi Joonaa päähän, niin että häntä näännytti. Niin hän toivotti itsellensä kuolemaa ja sanoi: "Parempi on minulle kuolema kuin elämä".'),
(1691533,58,32,4,9,'Mutta Jumala sanoi Joonalle: "Onko vihastumisesi risiinikasvin tähden oikea?" Tämä vastasi: "Oikea on vihastumiseni kuolemaan asti".'),
(1691534,58,32,4,10,'Niin Herra sanoi: "Sinä armahdat risiinikasvia, josta et ole vaivaa nähnyt ja jota et ole kasvattanut, joka yhden yön lapsena syntyi ja yhden yön lapsena kuoli.'),
(1691535,58,33,1,1,'Herran sana, joka tuli mooresetilaiselle Miikalle Jootamin, Aahaan ja Hiskian, Juudan kuningasten, päivinä; se, mitä hän näki Samariaa ja Jerusalemia vastaan.'),
(1691536,58,33,1,2,'Kuulkaa, kaikki kansat; ota korviisi, maa, ja kaikki, mitä maassa on. Ja olkoon Herra, Herra todistaja teitä vastaan, Herra pyhästä temppelistänsä.'),
(1691537,58,33,1,3,'Sillä katso, Herra lähtee asumuksestaan, astuu alas ja polkee maan kukkuloita.'),
(1691538,58,33,1,4,'Vuoret sulavat hänen allansa, ja laaksot halkeavat niinkuin vaha tulen hohteessa, niinkuin vedet, jotka syöksyvät jyrkännettä alas.'),
(1691539,58,33,1,5,'Jaakobin rikoksen tähden tapahtuu tämä kaikki ja Israelin heimon syntien tähden. Mistä on Jaakobin rikos? Eikö Samariasta! Ja mistä Juudan uhrikukkulat? Eivätkö Jerusalemista!'),
(1691540,58,33,1,6,'Niinpä minä panen Samarian kiviraunioksi kedolle, viinitarhan istutusmaaksi, syöksen laaksoon sen kivet ja paljastan sen perustukset.'),
(1691541,58,33,1,7,'Kaikki sen jumalankuvat särjetään, kaikki sen portonpalkat poltetaan tulessa, ja kaikki sen epäjumalankuvat minä hävitän; sillä portonpalkoista se on ne koonnut, ja portonpalkoiksi pitää niitten jälleen tuleman.'),
(1691542,58,33,1,8,'Tämän tähden minä tahdon valittaa ja voivotella, käydä avojaloin ja vaipatta, virittää valituslaulun kuin aavikkosudet, suruhuudon kuin kamelikurjet.'),
(1691543,58,33,1,9,'Sillä parantumaton on sen haava; se ulottuu Juudaan asti, se käy minun kansani porttiin saakka, aina Jerusalemiin saakka.'),
(1691544,58,33,1,10,'Älkää ilmoittako sitä Gatissa, älkää, älkää itkekö. Minä vieriskelen tuhassa Beet-Leafrassa.'),
(1691545,58,33,1,11,'Käy matkaan, Saafirin asujatar, häpeällisesti paljastettuna! Saananin asujatar ei lähde. Beet-Eselin valitus riistää teiltä pysähdyspaikan.'),
(1691546,58,33,1,12,'Onnea odottaa tuskaisesti Maarotin asujatar; mutta onnettomuus tulee Herralta Jerusalemin portille.'),
(1691547,58,33,1,13,'Valjasta hevoset vaunujen eteen, Laakiin asujatar; sieltä on alku tytär Siionin syntiin, sillä sinussa tavattiin Israelin rikokset.'),
(1691548,58,33,1,14,'Sentähden sinä annat eron Mooreset-Gatille. Aksibin talot tulevat olemaan pettymys Israelin kuninkaille.'),
(1691549,58,33,1,15,'Minä tuon vieläkin perijän sinulle, Maaresan asujatar. Adullamiin asti kulkee Israelin kunnia.'),
(1691550,58,33,1,16,'Ajele ja keritse pääsi paljaaksi lasten tähden, jotka olivat sinun ilosi. Ajele pääsi leveälti paljaaksi, niinkuin on korppikotkalla, sillä he menevät luotasi pois pakkosiirtolaisuuteen.'),
(1691551,58,33,2,1,'Voi niitä, jotka miettivät turmiota ja valmistelevat pahaa vuoteillansa! Aamun valjettua he sen tekevät, sillä heillä on siihen valta.'),
(1691552,58,33,2,2,'He himoitsevat peltoja ja ryöstävät ne, taloja, ja ottavat ne; he sortavat miestä ja hänen taloansa, miestä ja hänen perintöosaansa.'),
(1691553,58,33,2,3,'Sentähden, näin sanoo Herra: Katso, minä mietin tätä sukua vastaan onnettomuutta: siitä te ette saa kaulaanne irti ettekä voi ylpeästi astella; sillä se on oleva paha aika.'),
(1691554,58,33,2,4,'Sinä päivänä viritetään teistä pilkkalaulu ja veisataan valitusvirsi. "Se on tapahtunut", sanotaan, "me olemme perin hävitetyt, hän on vaihtanut pois minun kansani osan. Kuinka hän siirtää sen minulta pois! Hän jakaa meidän peltomme luopioille."'),
(1691555,58,33,2,5,'Sentähden ei sinulla ole oleva ketään, joka heittäisi arpaa maaosuudesta Herran seurakunnassa.'),
(1691556,58,33,2,6,'"Älkää saarnatko", saarnaavat he, "sellaisista ei pidä saarnata; eikö väisty pois häpäiseminen?"'),
(1691557,58,33,2,7,'Onko tämä Jaakobin heimon puhetta? Onko Herra pikavihainen? Ovatko sellaisia hänen tekonsa? Eivätkö hänen puheensa ole hyvät sitä kohtaan, joka oikein vaeltaa?'),
(1691558,58,33,2,8,'Mutta aikoja sitten on minun kansani asettunut viholliseksi; vaatteiden päältä te kiskotte vaipan niiltä, jotka huoleti kulkevat, jotka sotaa väistävät.'),
(1691559,58,33,2,9,'Minun kansani naiset te ajatte pois heidän kodeistansa, jotka ovat heidän ilonsa; heidän pieniltä lapsiltansa te otatte minun kunniani ainiaaksi.'),
(1691560,58,33,2,10,'Nouskaa ja menkää pois: ei tässä ole leposijaa saastutuksen tähden, joka on saanut aikaan turmion, parantumattoman turmion.'),
(1691561,58,33,2,11,'Jos tulisi mies, joka tuulta tavoittelisi ja petollisuudessaan valhettelisi: "Minä saarnaan sinulle viinistä ja väkijuomasta", siinä olisi saarnaaja tälle kansalle.'),
(1691562,58,33,2,12,'Minä tahdon tarkoin koota sinut, Jaakob, kaikkinesi, visusti kerätä Israelin jääneet, saattaa heidät yhteen, niinkuin lampaat tarhaan, niinkuin lauman laitumellensa: on oleva ihmisten kohina!'),
(1691563,58,33,2,13,'Tien aukaisija käy heidän edellänsä; he aukaisevat tiensä, kulkevat portille ja lähtevät siitä ulos. Heidän kuninkaansa käy heidän edellään, ja Herra heitä johdattaa.'),
(1691564,58,33,3,1,'Ja minä sanoin: Kuulkaa, Jaakobin päämiehet ja Israelin heimon ruhtinaat! Eikö teidän tulisi tuntea oikeus,'),
(1691565,58,33,3,2,'teidän, jotka vihaatte hyvää ja rakastatte pahaa, jotka raastatte ihmisten nahan heidän päältänsä ja lihan irti heidän luistansa?'),
(1691566,58,33,3,3,'Ne, jotka syövät minun kansani lihan ja nylkevät nahan heidän päältänsä ja murskaavat heidän luunsa, paloittelevat niinkuin pataan, niinkuin lihan kattilaan -'),
(1691567,58,33,3,4,'kerran he huutavat Herran puoleen, mutta hän ei vastaa heille, vaan kätkee heiltä kasvonsa sinä aikana, koska he ovat pahoja töitä tehneet.'),
(1691568,58,33,3,5,'Näin sanoo Herra niitä profeettoja vastaan, jotka eksyttävät minun kansaani, jotka huutavat: "Rauha!", kun heidän hampaissaan on purtavaa, mutta julistavat pyhän sodan sille, joka ei anna mitään heidän suuhunsa:'),
(1691569,58,33,3,6,'Sentähden tulee teille yö, näkyjä vailla, teille tulee pimeys, ennustelua vailla. Aurinko laskee näiltä profeetoilta, ja päivä heiltä pimenee.'),
(1691570,58,33,3,7,'Näkijät joutuvat häpeään, ja ennustelijat punastuvat. Kaikki he peittävät partansa, sillä Jumalan vastausta ei tule.'),
(1691571,58,33,3,8,'Mutta minä olen täynnä voimaa, Herran Henkeä, oikeutta ja väkevyyttä ilmoittaakseni Jaakobille sen rikokset ja Israelille sen synnit.'),
(1691572,58,33,3,9,'Kuulkaa tämä, Jaakobin heimon päämiehet ja Israelin heimon ruhtinaat, te, jotka halveksitte oikeutta ja vääristätte kaiken suoran,'),
(1691573,58,33,3,10,'rakennatte Siionia veritöillä ja Jerusalemia vääryydellä.'),
(1691574,58,33,3,11,'Sen päämiehet jakavat oikeutta lahjuksia vastaan, sen papit opettavat maksusta, ja sen profeetat ennustelevat rahasta. Mutta Herraan he turvautuvat, sanoen: "Eikö Herra ole meidän keskellämme? Ei tule meille onnettomuutta."'),
(1691575,58,33,3,12,'Siitä syystä, teidän tähtenne, Siion kynnetään pelloksi, Jerusalem tulee kiviraunioksi ja temppelivuori metsäkukkulaksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691576,58,33,4,1,'Aikojen lopussa on Herran temppelin vuori seisova vahvana, ylimmäisenä vuorista, ja se on oleva korkein kukkuloista, ja sinne virtaavat kansat.'),
(1691577,58,33,4,2,'Monet pakanakansat lähtevät liikkeelle sanoen: "Tulkaa, nouskaamme Herran vuorelle, Jaakobin Jumalan temppeliin, että hän opettaisi meille teitänsä ja me vaeltaisimme hänen polkujansa; sillä Siionista lähtee laki, Jerusalemista Herran sana."'),
(1691578,58,33,4,3,'Ja hän tuomitsee monien kansojen kesken, säätää oikeutta väkeville pakanakansoille, kaukaisiin maihin saakka. Niin he takovat miekkansa vantaiksi ja keihäänsä vesureiksi; kansa ei nosta miekkaa kansaa vastaan, eivätkä he enää opettele sotimaan.'),
(1691579,58,33,4,4,'He istuvat kukin oman viinipuunsa ja viikunapuunsa alla kenenkään peljättämättä. Sillä Herran Sebaotin suu on puhunut.'),
(1691580,58,33,4,5,'Sillä kaikki kansat vaeltavat jumalansa nimessä kukin, mutta me vaellamme Herran, meidän Jumalamme, nimessä aina ja iankaikkisesti.'),
(1691581,58,33,4,6,'Sinä päivänä, sanoo Herra, minä tahdon koota ontuvat ja kerätä hajalleen-ajetut ja ne, joille minä olin tuottanut onnettomuutta.'),
(1691582,58,33,4,7,'Minä teen ontuvista talteenjäävät ja kauasjoutuneista väkevän kansan. Ja Herra on oleva heidän kuninkaansa Siionin vuorella siitä alkaen ja iankaikkisesti.'),
(1691583,58,33,4,8,'Ja sinä Karjatorni, tytär Siionin kukkula! Sinun luoksesi on tuleva, on saapuva entinen hallitus, tytär Jerusalemia vallinnut kuninkuus.'),
(1691584,58,33,4,9,'Ja nyt - miksi sinä ääneen vaikeroit? Eikö sinulla ole kuningasta, onko sinun neuvonantajasi kadonnut, koska kipu on vallannut sinut niinkuin synnyttäväisen?'),
(1691585,58,33,4,10,'Vääntelehdi vain kouristuksissasi, tytär Siion, niinkuin synnyttäjä, sillä nyt sinun on lähdettävä ulos kaupungista ja asuttava kedolla ja mentävä Baabeliin asti: siellä sinut pelastetaan; siellä lunastaa sinut Herra vihamiestesi käsistä.'),
(1691586,58,33,4,11,'Nyt kokoontuu sinua vastaan paljon pakanoita, jotka sanovat: "Se saastutettakoon; katselkoot meidän silmämme iloksensa Siionia!"'),
(1691587,58,33,4,12,'Mutta he eivät tunne Herran aivoituksia eivätkä ymmärrä hänen neuvoansa, sillä hän kokoaa heidät niinkuin lyhteet puimatantereelle.'),
(1691588,58,33,4,13,'Nouse ja pui, tytär Siion, sillä minä annan sinulle rautasarvet ja vaskisorkat minä sinulle annan, ja sinä survot murskaksi monet kansat. Ja minä vihin Herralle, tuhon omaksi, heidän väärän voittonsa, kaiken maan Herralle heidän rikkautensa.'),
(1691589,58,33,5,1,'Nyt yhdy laumaksi, sinä hyökkääjäin ahdistama tytär! Meitä piiritetään, he lyövät sauvalla poskelle Israelin tuomaria. (5:1) Mutta sinä, Beetlehem Efrata, joka olet vähäinen olemaan Juudan sukujen joukossa, sinusta minulle tulee se, joka on oleva hallitsija Israelissa, jonka alkuperä on muinaisuudesta, iankaikkisista ajoista.'),
(1691590,58,33,5,2,'Sentähden Herra antaa heidät alttiiksi siihen aikaan asti, jolloin synnyttäjä on synnyttänyt; silloin jäljellejääneet hänen veljistänsä palajavat israelilaisten luokse.'),
(1691591,58,33,5,3,'Ja hän on astuva esiin ja kaitseva Herran voimassa, Herran, Jumalansa, nimen valtasuuruudessa. Ja he asuvat alallansa, sillä silloin on hän oleva suuri hamaan maan ääriin saakka.'),
(1691592,58,33,5,4,'Ja hän on oleva rauha: jos Assur hyökkää maahamme, jos se astuu palatseihimme, niin me asetamme sitä vastaan seitsemän paimenta ja kahdeksan ruhtinasta.'),
(1691593,58,33,5,5,'Nämä kaitsevat miekalla Assurin maata, Nimrodin maata sen omain ovien ääressä. Hän on pelastava meidät Assurin vallasta, jos se hyökkää meidän maahamme, jos se astuu meidän alueellemme.'),
(1691594,58,33,5,6,'Ja ne, jotka ovat jäljellä Jaakobista monien kansain seassa, ovat niinkuin kaste, joka tulee Herralta, niinkuin sadekuuro ruohikolle; se ei odota miestä, ei varro ihmislapsia.'),
(1691595,58,33,5,7,'Ja ne, jotka ovat jäljellä Jaakobista, pakanain seassa, monien kansain keskellä, ovat niinkuin leijona metsäneläinten seassa, niinkuin nuori jalopeura lammaslaumain keskellä: jos se hyökkää, tallaa maahan ja raatelee, ei pelastajaa ole.'),
(1691596,58,33,5,8,'Kohotkoon sinun kätesi vihollisiasi vastaan, ja sinun vihamiehesi hävitkööt.'),
(1691597,58,33,5,9,'Sinä päivänä, sanoo Herra, minä hävitän sinulta hevosesi ja teen lopun sinun vaunuistasi.'),
(1691598,58,33,5,10,'Minä hävitän sinun maasi kaupungit ja hajotan maahan kaikki sinun varustuksesi.'),
(1691599,58,33,5,11,'Minä hävitän loitsut sinun käsistäsi, eikä sinulle enää jää ennustelijoita.'),
(1691600,58,33,5,12,'Minä hävitän sinun jumalankuvasi ja patsaasi, etkä sinä enää kumarra kättesi tekoa.'),
(1691601,58,33,5,13,'Minä kukistan asera-karsikkosi sinun keskuudestasi ja tuhoan sinun kaupunkisi.'),
(1691602,58,33,5,14,'Ja minä kostan vihassa ja kiivaudessa pakanakansoille, jotka eivät olleet kuuliaisia.'),
(1691603,58,33,6,1,'Kuulkaa, mitä Herra sanoo: Nouse ja käy oikeutta vuorten kanssa, ja kukkulat kuulkoot sinun äänesi.'),
(1691604,58,33,6,2,'Kuulkaa Herran oikeudenkäyntiä, vuoret, te iäti kestävät, maan perustukset; sillä oikeudenkäynti on Herralla kansaansa vastaan, ja Israelin kanssa hän käy tuomiolle:'),
(1691605,58,33,6,3,'"Minun kansani, mitä minä olen sinulle tehnyt, ja millä olen sinut väsyttänyt? Vastaa minulle!'),
(1691606,58,33,6,4,'Minähän olen johdattanut sinut Egyptin maasta, vapahtanut sinut orjuuden pesästä; ja minä lähetin Mooseksen, Aaronin ja Mirjamin käymään sinun edelläsi.'),
(1691607,58,33,6,5,'Muista, kansani, mitä oli mielessä Baalakilla, Mooabin kuninkaalla, ja mitä Bileam, Beorin poika, hänelle vastasi, Sittimistä lähtien Gilgaliin asti, että käsittäisit Herran vanhurskaat teot." -'),
(1691608,58,33,6,6,'"Mitä tuoden minä voisin käydä Herran eteen, kumartua korkeuden Jumalan eteen? Käynkö hänen eteensä tuoden polttouhreja, vuodenvanhoja vasikoita?'),
(1691609,58,33,6,7,'Ovatko Herralle mieleen tuhannet oinaat, kymmenettuhannet öljyvirrat? Annanko esikoiseni rikoksestani, ruumiini hedelmän sieluni syntiuhriksi?" -'),
(1691610,58,33,6,8,'Hän on ilmoittanut sinulle, ihminen, mikä hyvä on; ja mitä muuta Herra sinulta vaatii, kuin että teet sitä, mikä oikein on, rakastat laupeutta ja vaellat nöyrästi Jumalasi edessä?'),
(1691611,58,33,6,9,'Herran ääni huutaa kaupungille - ja ymmärtäväisyyttä on, että sinun nimestäsi otetaan vaari. Totelkaa vitsaa ja häntä, joka on sen määrännyt.'),
(1691612,58,33,6,10,'Vieläkö ovat jumalattoman talossa vääryyden aarteet ja vajaa, kirottu eefa-mitta?'),
(1691613,58,33,6,11,'Olisinko minä puhdas, jos minulla olisi väärä vaaka ja kukkarossa petolliset punnuskivet?'),
(1691614,58,33,6,12,'Sen rikkaat ovat täynnä väkivaltaa, sen asukkaat puhuvat valhetta, kieli heidän suussansa on pelkkää petosta.'),
(1691615,58,33,6,13,'Niinpä minäkin lyön sinut sairaaksi, teen sinut autioksi sinun syntiesi tähden.'),
(1691616,58,33,6,14,'Sinä syöt, mutta et tule ravituksi, ja sinun vatsassasi on tyhjyys. Minkä viet pois, sitä et saa pelastetuksi; ja minkä pelastetuksi saat, sen minä annan alttiiksi miekalle.'),
(1691617,58,33,6,15,'Sinä kylvät, mutta et leikkaa. Sinä puserrat öljyä, mutta et öljyllä itseäsi voitele, ja rypälemehua, mutta et viiniä juo.'),
(1691618,58,33,6,16,'Mutta Omrin ohjeita noudatetaan ja kaikkia Ahabin suvun tekoja; ja heidän neuvojensa mukaan te vaellatte, että minä saattaisin sinut autioksi ja sen asukkaat pilkaksi; ja te saatte kantaa minun kansani häväistyksen.'),
(1691619,58,33,7,1,'Voi minua, sillä minun käy niinkuin hedelmänkorjuussa, niinkuin viinisadon jälkikorjuussa: ei ole rypälettä syödäkseni, ei varhaisviikunaa, jota minun sieluni himoitsee.'),
(1691620,58,33,7,2,'Poissa ovat hurskaat maasta, eikä oikeamielistä ole ihmisten seassa. Kaikki he väijyvät verta, pyydystävät verkolla toinen toistansa.'),
(1691621,58,33,7,3,'Pahantekoon molemmin käsin! Sitä taidolla tekemään! Päämies vaatii, tuomari maksusta tuomitsee, ja mahtava puhuu julki sielunsa himon; senkaltaista he punovat.'),
(1691622,58,33,7,4,'Paras heistä on kuin orjantappura, oikeamielisin pahempi kuin teräväokainen aita. Sinun tähystäjäisi ilmoittama päivä, kosto sinulle, tulee. Silloin he joutuvat sekasortoon.'),
(1691623,58,33,7,5,'Älkää uskoko ystävää, älkää luottako uskottuun; vaimolta, joka sylissäsi lepää, varo suusi ovet.'),
(1691624,58,33,7,6,'Sillä poika halveksii isää, tytär nousee äitiänsä vastaan, miniä anoppiansa vastaan; ihmisen vihamiehiä ovat hänen omat perhekuntalaisensa.'),
(1691625,58,33,7,7,'Mutta minä panen toivoni Herraan, odotan pelastukseni Jumalaa: minun Jumalani on minua kuuleva.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691626,58,33,7,8,'Älkää iloitko, minun viholliseni, minusta: jos minä olen langennut, niin minä nousen; jos istun pimeydessä, on Herra minun valkeuteni.'),
(1691627,58,33,7,9,'Minä tahdon kantaa Herran vihaa, sillä minä olen tehnyt syntiä häntä vastaan, siihen asti että hän minun asiani toimittaa ja hankkii minulle oikeuden. Hän tuo minut valkeuteen, minä saan nähdä hänen vanhurskautensa.'),
(1691628,58,33,7,10,'Minun viholliseni saavat nähdä sen, ja häpeä on peittävä heidät, jotka sanovat minulle: "Missä on Herra, sinun Jumalasi?" Minun silmäni saavat ilokseen katsoa heitä: silloin he joutuvat tallattaviksi kuin katujen loka.'),
(1691629,58,33,7,11,'Tulee päivä, jolloin sinun muurisi rakennetaan; sinä päivänä on raja oleva kaukana:'),
(1691630,58,33,7,12,'sinä päivänä tullaan sinun tykösi Assurista ja Egyptin kaupungeista, kaikkialta, Egyptistä aina Eufrat-virtaan, merestä mereen, vuoresta vuoreen.'),
(1691631,58,33,7,13,'Ja maa tulee autioksi asukkaittensa tähden, heidän töittensä hedelmäin takia.'),
(1691632,58,33,7,14,'Kaitse kansaasi sauvallasi, perintölaumaasi, joka erillänsä asuu metsässä, keskellä Karmelia. Käykööt he laitumella Baasanissa ja Gileadissa niinkuin ikiaikoina ennen. -'),
(1691633,58,33,7,15,'"Niinkuin sinun lähtösi päivinä Egyptin maasta minä annan hänen nähdä ihmeitä". -'),
(1691634,58,33,7,16,'Sen näkevät pakanakansat ja saavat häpeän kaikesta väkevyydestänsä. He panevat käden suullensa, heidän korvansa menevät lumpeen.'),
(1691635,58,33,7,17,'He nuolevat tomua kuin käärme, kuin maan matelijat. Vavisten he tulevat varustuksistansa, lähestyvät väristen Herraa, meidän Jumalaamme; he pelkäävät sinua.'),
(1691636,58,33,7,18,'Kuka on Jumala, niinkuin sinä olet, joka annat pahat teot anteeksi ja käyt ohitse perintösi jäännöksen rikosten? Ei hän pidä vihaa iäti, sillä hänellä on halu laupeuteen.'),
(1691637,58,33,7,19,'Hän armahtaa meitä jälleen, polkee maahan meidän pahat tekomme. Kaikki heidän syntinsä sinä heität meren syvyyteen.'),
(1691638,58,34,1,1,'Ennustus Niinivestä. Elkosilaisen Naahumin näyn kirja.'),
(1691639,58,34,1,2,'Kiivas Jumala ja kostaja on Herra. Herra on kostaja ja vihastuvainen. Herra kostaa vihollisilleen ja pitää vihaa vihamiehillensä.'),
(1691640,58,34,1,3,'Herra on pitkämielinen ja suuri voimassansa, mutta Herra ei jätä rankaisematta. Hänen tiensä käy tuulispäässä ja myrskyssä, ja pilvi on hänen jalkojensa tomu.'),
(1691641,58,34,1,4,'Hän nuhtelee merta ja kuivaa sen, ja kaikki virrat hän ehdyttää. Baasan ja Karmel kuihtuvat, ja Libanonin kukoistus kuihtuu.'),
(1691642,58,34,1,5,'Vuoret järkkyvät hänen edessänsä ja kukkulat sulavat. Hänen kasvojensa voimasta kohoaa maa, maanpiiri ja kaikki sen asuvaiset.'),
(1691643,58,34,1,6,'Kuka seisoo hänen tuimuutensa edessä, ja kuka kestää hänen vihansa hehkua? Hänen vihastuksensa vuotaa niinkuin tuli, ja kalliot halkeilevat hänen edessänsä.'),
(1691644,58,34,1,7,'Hyvä on Herra, turva ahdistuksen päivänä, ja hän tuntee ne, jotka häneen luottavat.'),
(1691645,58,34,1,8,'Mutta paisuvalla tulvalla hän tekee lopun sen paikasta; ja vihamiehiänsä hän ahdistaa pimeydellä.'),
(1691646,58,34,1,9,'Mitä teillä on mielessä Herraa vastaan? Lopun hän tekee: ei nouse ahdistus kahta kertaa.'),
(1691647,58,34,1,10,'Sillä vaikka he olisivat yhteenkietoutuneita kuin orjantappurat ja yhtä märkiä viinistä kuin itse heidän viininsä, heidät syö tuli niinkuin kuivat oljet - kokonansa.'),
(1691648,58,34,1,11,'Sinusta on lähtenyt se, jolla on paha mielessä Herraa vastaan, turmion hankitsija.'),
(1691649,58,34,1,12,'Näin sanoo Herra: Olkoot he kuinka täysissä voimissa, olkoon heitä miten paljon tahansa, heidät tuhotaan; mennyttä he ovat. Mutta jos minä olenkin vaivannut sinua en minä sinua enää vaivaa.'),
(1691650,58,34,1,13,'Nyt minä särjen hänen ikeensä painamasta sinua ja katkaisen sinun kahleesi.'),
(1691651,58,34,1,14,'Mutta sinusta on Herra antanut käskyn: Ei kasva enää sinun nimellesi siementä. Minä hävitän sinun jumalasi temppelistä veistetyt ja valetut jumalankuvat. Minä teen sinulle haudan, sillä sinä olet rauennut tyhjiin.'),
(1691652,58,34,1,15,'Katso, jo ovat vuorilla ilosanoman tuojan jalat, hänen, joka julistaa rauhaa: "Juhli, Juuda, juhliasi, maksa lupauksesi; sillä ei tule enää sinun kimppuusi turmiontuoja, hän on hävitetty kokonansa".'),
(1691653,58,34,2,1,'Hajottaja hyökkää sinua vastaan! Vartioitse varustuksia, tähystä tietä, vahvista vyötäiset, kokoa kaikki voimasi.'),
(1691654,58,34,2,2,'Sillä Herra saattaa entiselleen Jaakobin korkeuden niinkuin myös Israelin korkeuden, sillä ryöstäjät ovat niitä ryöstäneet ja turmelleet niiden viiniköynnökset.'),
(1691655,58,34,2,3,'Hänen sankariensa kilvet ovat punaiset, urhot purppurapukuiset, sotavaunut säihkyvät teräksen tulta hänen varustautumispäivänänsä, ja kypressikeihäät heiluvat.'),
(1691656,58,34,2,4,'Sotavaunut karkaavat hurjasti kaduilla, syöksyvät sekaisin toreilla; ne ovat nähdä kuin tulenliekit, ne kiitävät kuin salamat.'),
(1691657,58,34,2,5,'Hän muistaa ylhäisensä. Ne tulevat niin, että kaatuilevat, kiiruhtavat sen muurille. Mutta suojakatos on pantu kuntoon.'),
(1691658,58,34,2,6,'Virranpuoleiset portit on aukaistu, palatsi menehtyy pelkoon.'),
(1691659,58,34,2,7,'Päätös on tullut: se on paljastettu, viety pois; ja sen orjattaret huokailevat, kujertaen kuin kyyhkyset, lyöden rintoihinsa.'),
(1691660,58,34,2,8,'Niinive on ollut kuin vetten täyttämä lammikko päiviensä alusta asti. Nyt ne pakenevat! - "Seis! Seiskää!" Mutta yksikään ei käänny.'),
(1691661,58,34,2,9,'Ryöstäkää hopeata, ryöstäkää kultaa. Loppumattomat ovat varat, ylen paljon kaikkinaisia kalliita kaluja. -'),
(1691662,58,34,2,10,'Tyhjänä kaikki, typötyhjänä, hävitettynä! Sydämet raukeavat, polvet tutisevat, kaikki lanteet vapisevat, ja kaikkien kasvot ovat kalpeat.'),
(1691663,58,34,2,11,'Missä on nyt leijonain tyyssija, nuorten jalopeurain syöntipaikka, jossa leijona käyskenteli, naarasleijona ja leijonanpentu, kenenkään peloittelematta?'),
(1691664,58,34,2,12,'Leijona raateli, mitä sen pennut tarvitsivat, ja surmasi naarasleijonillensa, täytti luolansa saaliilla ja tyyssijansa raatelemallaan.'),
(1691665,58,34,2,13,'Katso, minä käyn sinun kimppuusi, sanoo Herra Sebaot, poltan savuksi sinun sotavaunusi, ja sinun nuoret jalopeurasi syö miekka. Minä lopetan maan päältä sinun raatelusi, eikä kuulla enää sinun sanansaattajaisi ääntä.'),
(1691666,58,34,3,1,'Voi verivelkojen kaupunkia, joka on täpötäynnä valhetta ja raastosaalista; ei taukoa ryöstäminen!'),
(1691667,58,34,3,2,'Kuule! Ruoskat läiskyvät, pyörät ryskyvät, hevoset kiitävät, vaunut hyppivät,'),
(1691668,58,34,3,3,'ratsut karkaavat pystyyn, miekat välkkyvät, keihäät salamoivat. Paljon kaatuneita, läjittäin ruumiita, loppumatta raatoja! Heidän raatoihinsa lankeillaan.'),
(1691669,58,34,3,4,'Kaikki tämä porton suuren haureuden tähden, tuon ihanan sulottaren, ovelan velhottaren, joka myi kansakunnat haureudellaan, sukukunnat velhouksillansa.'),
(1691670,58,34,3,5,'Katso, minä käyn sinun kimppuusi, sanoo Herra Sebaot, nostan sinun liepeesi kasvojesi yli ja näytän kansakunnille sinun alastomuutesi, valtakunnille sinun häpeäsi.'),
(1691671,58,34,3,6,'Ja minä viskaan likaa sinun päällesi, häpäisen sinut ja panen sinut julkinähtäväksi.'),
(1691672,58,34,3,7,'Ja kaikki, jotka näkevät sinut, kaikkoavat sinusta kauas ja sanovat: "Hävitetty on Niinive! Kuka sitä surkuttelisi, mistä minä etsisin sinulle lohduttajia?"'),
(1691673,58,34,3,8,'Oletko sinä parempi, kuin oli Noo-Ammon, joka istui hallitsijana virtojen ääressä, vetten ympäröimänä, jolla oli virta varustuksena ja virta muurina?'),
(1691674,58,34,3,9,'Sen väkevyytenä oli Etiopia ja egyptiläiset, joilla ei ollut määrää. Auttajinasi olivat Puut ja liibyalaiset.'),
(1691675,58,34,3,10,'Sekin meni pakkosiirtolaisuuteen, vankeuteen. Senkin pienet lapset murskattiin kaikkien katujen kulmissa, sen ylhäisistä heitettiin arpaa, ja kaikki sen suurmiehet pantiin kahleisiin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691676,58,34,3,11,'Myös sinä olet juopuva ja vaipuva pimeyteen; myös sinä olet etsivä suojaa vihamiehen uhatessa.'),
(1691677,58,34,3,12,'Kaikki sinun varustuksesi ovat viikunapuita, joissa on varhaisviikunoita: jos niitä pudistellaan, ne putoavat syöjän suuhun.'),
(1691678,58,34,3,13,'Katso, sotaväkesi, mikä sinulla on, on naisia. Sinun maasi portit ovat selkoselällään sinun vihamiehillesi. Tuli kuluttaa sinun salpasi.'),
(1691679,58,34,3,14,'Ammenna itsellesi vettä piirityksen varalta, vahvista varustuksiasi, astu liejuun, polje savea, käy kiinni tiilenmuottiin.'),
(1691680,58,34,3,15,'Siinä on tuli sinut kuluttava, miekka on sinut tuhoava, se on syövä sinut niinkuin syöjäsirkat, vaikka lisääntyisit kuin syöjäsirkat, vaikka lisääntyisit heinäsirkkojen tavoin.'),
(1691681,58,34,3,16,'Sinä olet lisännyt kauppiaasi lukuisammiksi kuin taivaan tähdet: syöjäsirkat ryöstävät ja lentävät pois.'),
(1691682,58,34,3,17,'Sinulla on ennusmiehiä kuin heinäsirkkoja, kirjureita kuin sirkkaparvea, joka asettuu aidoille kylmänä päivänä; kun aurinko on noussut, ne pakenevat, eikä kukaan tiedä paikkaa, missä ne ovat.'),
(1691683,58,34,3,18,'Sinun paimenesi, Assurin kuningas, ovat nukkuneet, sinun ylhäisesi jääneet liikkumattomiksi. Sinun väkesi on hajaantunut vuorille, eikä ole kokoajaa.'),
(1691684,58,35,1,1,'Ennustus, jonka profeetta Habakuk näki.'),
(1691685,58,35,1,2,'Kuinka kauan, Herra, minun täytyy apua huutaa, ja sinä et kuule, parkua sinulle: "Väkivaltaa!" ja sinä et auta?'),
(1691686,58,35,1,3,'Minkätähden sinä annat minun nähdä vääryyttä ja itse katselet turmiota? Minun edessäni on hävitys ja väkivalta; on syntynyt riita, ja on noussut tora.'),
(1691687,58,35,1,4,'Sentähden on laki heikko, ja oikeus ei tule milloinkaan voimaan. Sillä jumalaton saartaa vanhurskaan; sentähden oikeus vääristetään.'),
(1691688,58,35,1,5,'Katsokaa kansojen joukkoon, katselkaa ja kauhistukaa, sillä minä teen teidän päivinänne teon, jota ette uskoisi, jos siitä kerrottaisiin.'),
(1691689,58,35,1,6,'Sillä katso, minä nostan kaldealaiset, tuiman ja rajun kansan, joka kulkee maata lavealti ja ottaa omaksensa asuinsijat, jotka eivät ole sen.'),
(1691690,58,35,1,7,'Se on hirmuinen ja peljättävä, siitä itsestään tulee sen oikeus ja sen korkeus.'),
(1691691,58,35,1,8,'Sen hevoset ovat nopeammat kuin pantterit, ne juoksevat kiivaammin kuin sudet illoin. Sen ratsumiehet kiidättävät - kaukaa tulevat sen ratsumiehet, ne lentävät, niinkuin kotka syöksyy syönnökselleen.'),
(1691692,58,35,1,9,'Se tulee kaikkinensa väkivallan tekoon, heidän kasvojensa suunta on suoraan eteenpäin; se kokoaa vankeja kuin hietaa.'),
(1691693,58,35,1,10,'Pilkkanaan pitää se kuninkaat ja naurunansa ruhtinaat. Se nauraa kaikille varustuksille, kasaa kokoon hiekkaa ja valloittaa ne.'),
(1691694,58,35,1,11,'Sitten se tuulena kiitää ja hyökkää, mutta joutuu syynalaiseksi, tuo, jolla oma voimansa on jumalana.'),
(1691695,58,35,1,12,'Etkö sinä ole ikiajoista asti Herra, minun pyhä Jumalani? Me emme kuole! Sinä, Herra, olet pannut sen tuomioksi; sinä, kallio, olet asettanut sen kuritukseksi.'),
(1691696,58,35,1,13,'Sinun silmäsi ovat puhtaat, niin ettet voi katsoa pahaa etkä saata katsella turmiota. Minkätähden sinä katselet uskottomia, olet vaiti, kun jumalaton nielee hurskaampansa,'),
(1691697,58,35,1,14,'teet ihmiset samankaltaisiksi kuin meren kalat, kuin matelevaiset, joilla ei ole hallitsijaa?'),
(1691698,58,35,1,15,'Se nostaa heidät kaikki ylös koukulla, vetää heidät pyydyksessään ja kokoaa heidät verkkoonsa. Sentähden se iloitsee ja riemuitsee.'),
(1691699,58,35,1,16,'Sentähden se uhraa pyydykselleen ja polttaa uhreja verkollensa, sillä niitten turvin sen osa on rasvainen, sen ruoka lihava.'),
(1691700,58,35,1,17,'Saako se sentähden tyhjentää pyydyksensä, aina surmata kansoja säälimättä?'),
(1691701,58,35,2,1,'Minä seison vartiopaikallani, asetun varustukseen ja tähystän, nähdäkseni, mitä hän minulle puhuu, mitä hän valitukseeni vastaa.'),
(1691702,58,35,2,2,'Ja Herra vastasi minulle ja sanoi: "Kirjoita näky ja piirrä selvästi tauluihin, niin että sen voi juostessa lukea".'),
(1691703,58,35,2,3,'Sillä näky odottaa vielä aikaansa, mutta se rientää määränsä päähän, eikä se petä. Jos se viipyy, odota sitä; sillä varmasti se toteutuu, eikä se myöhästy.'),
(1691704,58,35,2,4,'Katso, sen kansan sielu on kopea eikä ole suora; mutta vanhurskas on elävä uskostansa.'),
(1691705,58,35,2,5,'Ja vielä: viini on petollista, urho on röyhkeä; mutta hän ei ole pysyväinen, hän, joka levittää kitansa kuin tuonela ja on täyttymätön kuin kuolema, kokoaa itselleen kaikki kansakunnat ja kerää itselleen kaikki kansat.'),
(1691706,58,35,2,6,'Mutta ne kaikki virittävät hänestä pilkkalaulun, ivarunon, arvoituslaulun; he sanovat: "Voi sitä, joka hankkii paljon omaisuutta, mikä ei ole hänen - ja kuinkahan pitkäksi aikaa? - ja kasaa päällensä pantteja!'),
(1691707,58,35,2,7,'Eivätkö nouse äkisti sinun vaivaajasi, eivätkö heräjä sinun ravistajasi? Ja sinä joudut niiden ryöstettäväksi.'),
(1691708,58,35,2,8,'Sillä niinkuin sinä olet riistänyt monia kansakuntia, niin riistävät sinua kaikki jäljellejääneet kansat ihmisveren tähden ja väkivallan tähden, joka on tehty maalle, kaupungille ja kaikille sen asukkaille.'),
(1691709,58,35,2,9,'Voi sitä, joka kiskoo väärää voittoa huoneensa hyväksi laittaakseen pesänsä korkealle, pelastuakseen kovan onnen kourista!'),
(1691710,58,35,2,10,'Sinä olet neuvoillasi tuottanut häpeätä huoneellesi, tuhoamalla paljon kansoja, ja olet oman henkesi rikkonut.'),
(1691711,58,35,2,11,'Sillä kivi seinästä on huutava ja orsi katosta on vastaava.'),
(1691712,58,35,2,12,'Voi sitä, joka rakentaa kaupungin verivelkojen varaan ja perustaa linnan vääryyden varaan!'),
(1691713,58,35,2,13,'Katso, eikö tule se Herralta Sebaotilta, että kansat näkevät vaivaa tulen hyväksi ja kansakunnat väsyttävät itseänsä tyhjän hyväksi?'),
(1691714,58,35,2,14,'Sillä maa on oleva täynnä Herran kunnian tuntemusta, niinkuin vedet peittävät meren.'),
(1691715,58,35,2,15,'Voi sitä, joka juottaa lähimmäistänsä, joka sekoittaa juoman sinun vihallasi ja juovuttaa hänet nähdäkseen hänen alastomuutensa!'),
(1691716,58,35,2,16,'Sinä ravitset itsesi häpeällä, et kunnialla: niinpä juo sinäkin ja paljasta ympärileikkaamattomuutesi. Sinun kohdallesi on kiertyvä Herran oikean käden malja ja häväistys kunnian sijaan.'),
(1691717,58,35,2,17,'Sillä sinut on peittävä Libanonille tekemäsi väkivalta ja eläimiä kohdannut hävitys, joka on ne säikyttänyt, ihmisveren tähden ja väkivallan tähden, joka on tehty maalle, kaupungille ja kaikille sen asukkaille.'),
(1691718,58,35,2,18,'Mitä hyötyä on veistetystä kuvasta, että sen valmistaja veistää sen, ja valetusta kuvasta ja valheen opettajasta, että sen valmistaja siihen luottaa ja tekee mykkiä epäjumalia?'),
(1691719,58,35,2,19,'Voi sitä, joka sanoo puulle: ''Heräjä!'' ja mykälle kivelle: ''Nouse!'' Sekö voisi opettaa? Katso, se on silattu kullalla ja hopealla, ja henkeä siinä ei ole, ei ensinkään.'),
(1691720,58,35,2,20,'Mutta Herra on pyhässä temppelissänsä, hänen edessään vaietkoon kaikki maa."'),
(1691721,58,35,3,1,'Profeetta Habakukin rukous; virren tapaan.'),
(1691722,58,35,3,2,'Herra, minä olen kuullut sinulta sanoman, ja olen peljästynyt. Herra, herätä eloon tekosi jo kesken vuotten, tee se jo kesken vuotten tiettäväksi. Muista vihassasi laupeutta.'),
(1691723,58,35,3,3,'Jumala tulee Teemanista, Pyhä Paaranin vuorelta. Sela. Hänen valtasuuruutensa peittää taivaat, hänen ylistystänsä on maa täynnä.'),
(1691724,58,35,3,4,'Hänen hohteensa on kuin aurinko, hänestä käyvät säteet joka taholle; se on hänen voimansa verho.'),
(1691725,58,35,3,5,'Hänen edellänsä käy rutto ja polttotauti tulee hänen jäljessänsä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691726,58,35,3,6,'Hän seisahtuu ja mittaa maan, hän katsahtaa ja saa kansat vapisemaan. Ikivuoret särkyvät, ikuiset kukkulat vaipuvat, hänen polkunsa ovat iankaikkiset.'),
(1691727,58,35,3,7,'Vaivan alaisina minä näen Kuusanin majat, Midianin maan telttavaatteet vapisevat.'),
(1691728,58,35,3,8,'Virtoihinko Herra on vihastunut? Kohtaako sinun vihasi virtoja, merta sinun kiivastuksesi, koska ajat hevosillasi, pelastuksesi vaunuilla?'),
(1691729,58,35,3,9,'Paljas, paljastettu on sinun jousesi: valat, vitsat, sana. Sela. Virroilla sinä halkaiset maan.'),
(1691730,58,35,3,10,'Vuoret näkevät sinut ja järkkyvät, rankkasade purkaa vettä, syvyys antaa äänensä, kohottaa kätensä korkealle.'),
(1691731,58,35,3,11,'Aurinko ja kuu astuvat majaansa sinun kiitävien nuoltesi valossa, sinun keihääsi salaman hohteessa.'),
(1691732,58,35,3,12,'Kiivastuksessa sinä astut maata, puit kansoja vihassa.'),
(1691733,58,35,3,13,'Sinä olet lähtenyt auttamaan kansaasi, auttamaan voideltuasi. Sinä murskaat pään jumalattoman huoneesta, paljastat perustukset kaulan tasalle. Sela.'),
(1691734,58,35,3,14,'Sinä lävistät heidän omilla keihäillään pään heidän johtajiltansa, jotka hyökkäävät hajottamaan minua - se on heidän ilonsa - aivan kuin pääsisivät syömään kurjaa salassa.'),
(1691735,58,35,3,15,'Sinä ajat hevosillasi merta, paljojen vetten kuohua.'),
(1691736,58,35,3,16,'Minä kuulin tämän, ja minun ruumiini vapisee, minun huuleni värisevät huudosta, mätä menee minun luihini, minä seison paikallani ja tutisen, kun minun täytyy hiljaa odottaa ahdistuksen päivää, jolloin kansan kimppuun käy hyökkääjä.'),
(1691737,58,35,3,17,'Sillä ei viikunapuu kukoista, eikä viiniköynnöksissä ole rypäleitä; öljypuun sato pettää, eivätkä pellot tuota syötävää. Lampaat ovat kadonneet tarhasta, eikä ole karjaa vajoissa.'),
(1691738,58,35,3,18,'Mutta minä riemuitsen Herrassa, iloitsen autuuteni Jumalassa.'),
(1691739,58,36,1,1,'Herran sana, joka tuli Sefanjalle, Kuusin pojalle, joka oli Gedaljan poika, joka Amarjan poika, joka Hiskian poika, Juudan kuninkaan Joosian, Aamonin pojan, päivinä.'),
(1691740,58,36,1,2,'Totisesti minä otan kaiken pois maan pinnalta, sanoo Herra.'),
(1691741,58,36,1,3,'Minä otan pois ihmiset ja eläimet, otan pois taivaan linnut ja meren kalat, viettelykset ja jumalattomat. Minä hävitän ihmiset maan pinnalta, sanoo Herra.'),
(1691742,58,36,1,4,'Minä ojennan käteni Juudaa vastaan ja kaikkia Jerusalemin asukkaita vastaan, ja minä hävitän tästä paikasta Baalin jätteet, epäjumalain pappien nimet ynnä myös Herran papit,'),
(1691743,58,36,1,5,'ne, jotka katoilla kumartaen rukoilevat taivaan joukkoa, sekä ne, jotka kumartaen rukoilevat Herraa ja vannovat hänen kauttansa, mutta myös vannovat Melekinsä kautta,'),
(1691744,58,36,1,6,'ynnä ne, jotka ovat luopuneet seuraamasta Herraa, eivät etsi Herraa eivätkä häntä kysy.'),
(1691745,58,36,1,7,'Vaiti Herran, Herran edessä! Sillä Herran päivä on lähellä; sillä Herra on laittanut teurasuhrin, on vihkinyt kutsuttunsa.'),
(1691746,58,36,1,8,'Ja Herran teurasuhrin päivänä minä rankaisen päämiehiä ja kuninkaan poikia ja kaikkia muukalaispukuun puettuja.'),
(1691747,58,36,1,9,'Ja minä rankaisen sinä päivänä kaikkia kynnyksen yli hyppääjiä, jotka täyttävät herransa huoneen väkivallalla ja petoksella.'),
(1691748,58,36,1,10,'Sinä päivänä, sanoo Herra, kuuluu huuto Kalaportilta ja valitus toisesta kaupunginosasta ja suuri hävitys kukkuloilta.'),
(1691749,58,36,1,11,'Valittakaa, te Huhmaren asukkaat, sillä tuhottu on kaikki kauppaakäypä väki, hävitetty kaikki hopean punnitsijat.'),
(1691750,58,36,1,12,'Siihen aikaan minä tutkin lampuilla Jerusalemin ja rankaisen ne miehet, jotka rauhassa makaavat pohjasakkansa päällä ja sanovat sydämessään: "Ei Herra tee hyvää eikä pahaa".'),
(1691751,58,36,1,13,'Heidän rikkautensa joutuu ryöstettäväksi, ja heidän talonsa jäävät autioiksi. He ovat rakentaneet taloja, mutta eivät saa niissä asua; ovat istuttaneet viinitarhoja, mutta eivät saa niistä viiniä juoda.'),
(1691752,58,36,1,14,'Lähellä on Herran suuri päivä, se on lähellä ja tulee sangen kiiruusti. Kuule, Herran päivä! Silloin sankarit haikeasti huutavat.'),
(1691753,58,36,1,15,'Vihan päivä on se päivä, tuskan ja ahdistuksen päivä, häviön ja hävityksen päivä, pimeyden ja synkeyden päivä, pilven ja sankan sumun päivä,'),
(1691754,58,36,1,16,'pasunan ja sotahuudon päivä varustettuja kaupunkeja ja korkeita muurinkulmia vastaan.'),
(1691755,58,36,1,17,'Minä saatan ihmiset ahdistukseen, niin että he kulkevat kuin sokeat, sillä he ovat tehneet syntiä Herraa vastaan. Ja heidän verensä vuodatetaan niinkuin tomu, ja heidän elinnesteensä niinkuin saasta.'),
(1691756,58,36,1,18,'Eivätkä voi pelastaa heitä heidän hopeansa ja kultansa Herran vihan päivänä: hänen kiivautensa tulessa kuluu koko maa. Sillä lopun, äkkilopun, hän tekee kaikista maan asukkaista.'),
(1691757,58,36,2,1,'Menkää itseenne, kootkaa ajatuksenne, te häpeämätön kansa,'),
(1691758,58,36,2,2,'ennenkuin neuvopäätös on synnyttänyt - päivä kiitää pois kuin akanat - ennenkuin teidän päällenne tulee Herran vihan hehku, ennenkuin teidän päällenne tulee Herran vihan päivä.'),
(1691759,58,36,2,3,'Etsikää Herraa, kaikki maan nöyrät, te, jotka pidätte hänen oikeutensa. Etsikää vanhurskautta, etsikää nöyryyttä; ehkä te saatte suojan Herran vihan päivänä.'),
(1691760,58,36,2,4,'Sillä Gassa on oleva hyljätty ja Askelon autio, Asdod ajetaan pois keskipäivällä, ja Ekron hävitetään.'),
(1691761,58,36,2,5,'Voi meren rannikon asukkaita, kreettien kansaa! Herran sana on teitä vastaan, Kanaan, filistealaisten maa; ja minä hävitän sinut asujattomaksi.'),
(1691762,58,36,2,6,'Ja meren rannikko on oleva laitumina, joilla on paimenten vesikuoppia ja lammastarhoja.'),
(1691763,58,36,2,7,'Ja rannikko joutuu Juudan heimon jäännökselle. Siellä he laiduntavat; Askelonin huoneisiin he asettuvat makaamaan illoin. Sillä Herra, heidän Jumalansa, on pitävä heistä huolen ja kääntävä heidän kohtalonsa.'),
(1691764,58,36,2,8,'Minä olen kuullut Mooabin häväistykset ja ammonilaisten pilkat, joilla he ovat häväisseet minun kansaani ja ylvästelleet sen aluetta vastaan.'),
(1691765,58,36,2,9,'Sentähden, niin totta kuin minä elän, sanoo Herra Sebaot, Israelin Jumala, on Mooab tuleva Sodoman kaltaiseksi ja ammonilaiset Gomorran kaltaisiksi, nokkospehkojen maaksi, suolakuopaksi, autioksi iankaikkisesti. Jääneet minun kansastani ryöstävät heitä, ja minun kansakuntani jäännökset ottavat heidät perintöosaksensa.'),
(1691766,58,36,2,10,'Tämä tulee heille heidän ylpeydestään, siitä, että ovat herjanneet, ovat ylvästelleet Herran Sebaotin kansaa vastaan.'),
(1691767,58,36,2,11,'Peljättävä on Herra heille oleva, sillä hän tekee voimattomiksi kaikki maan jumalat; ja kaikki pakanain saaret, kukin paikastansa, tulevat häntä kumartaen rukoilemaan.'),
(1691768,58,36,2,12,'Myöskin teidät, etiopialaiset, on minun miekkani kaatava - heidätkin!'),
(1691769,58,36,2,13,'Ja hän on ojentava kätensä pohjoista kohden ja on hukuttava Assurin, tekevä Niiniven autioksi, kuivaksi kuin erämaa.'),
(1691770,58,36,2,14,'Sen keskellä makaa laumoja, kaikkia villieläimiä joukoittain. Pelikaani ja tuonenkurki yöpyvät sen patsaanpäissä. Kuule, kuinka ne laulavat akkuna-aukossa! Kynnyksellä on tyhjyys. Setrilaudoituksen hän on paljastanut.'),
(1691771,58,36,2,15,'Tämä oli se riemuisa kaupunki, joka asui turvallisena, joka sanoi sydämessään: "Minä, eikä ketään muuta!" Kuinka autioksi se on tullut, villieläinten makuusijaksi! Jokainen, joka käy siitä ohitse, viheltää ja huiskuttaa kättä.'),
(1691772,58,36,3,1,'Voi uppiniskaista ja saastutettua, voi väkivaltaista kaupunkia!'),
(1691773,58,36,3,2,'Se ei ole totellut ääntä, ei huolinut kurituksesta, ei luottanut Herraan, ei lähestynyt Jumalaansa.'),
(1691774,58,36,3,3,'Sen päämiehet sen keskellä ovat ärjyviä leijonia. Sen tuomarit ovat kuin sudet illalla, jotka eivät säästä mitään aamuksi.'),
(1691775,58,36,3,4,'Sen profeetat ovat huikentelijoita, uskottomia miehiä. Sen papit saastuttavat pyhän ja tekevät väkivaltaa laille.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691776,58,36,3,5,'Herra on vanhurskas sen keskellä, hän ei tee väärin. Joka aamu hän tuo valoon oikeutensa, ei se tulematta jää. Mutta väärintekijä ei tunne häpeätä.'),
(1691777,58,36,3,6,'Minä olen hävittänyt pakanakansat, niiden muurinkulmat ovat autioina. Minä olen tehnyt niiden kadut raunioiksi, kulkijattomiksi; niiden kaupungit ovat hävitetyt ihmisettömiksi, asujattomiksi.'),
(1691778,58,36,3,7,'Minä olen sanonut: Ainoastaan pelkää minua ja ota varteen kuritus, niin ei hävitetä tytär Siionin asumusta, ei mitään siitä, mitä minä olen hänelle säätänyt. Kuitenkin he varhaisesta alkaen ovat aina pahemmin tehneet.'),
(1691779,58,36,3,8,'Sentähden odottakaa minua, sanoo Herra, odottakaa sitä päivää, jona minä nousen saaliille. Sillä minun tuomioni on, että minä kokoan pakanakansat, saatan kokoon valtakunnat vuodattaakseni heidän päällensä tuimuuteni, vihani kaiken hehkun; sillä minun kiivauteni tuli kuluttaa koko maan.'),
(1691780,58,36,3,9,'Silloin minä muutan puhtaiksi kansain huulet, niin että ne kaikki rukoilevat Herran nimeä, palvelevat häntä yksimielisesti.'),
(1691781,58,36,3,10,'Tuolta puolen Etiopian virtain tuovat minun rukoilijani - tytär, minun hajoitettu joukkoni - minulle ruokauhreja.'),
(1691782,58,36,3,11,'Sinä päivänä ei sinun tarvitse hävetä yhtäkään niistä teoistasi, joilla olet rikkonut minua vastaan, sillä silloin minä poistan sinun keskuudestasi sinun ylvääsi, riemuitsevaisesi, etkä sinä sitten enää ylpeile minun pyhällä vuorellani.'),
(1691783,58,36,3,12,'Mutta minä jätän jäljelle sinun keskuuteesi kurjan ja vaivaisen kansan, ja he luottavat Herran nimeen.'),
(1691784,58,36,3,13,'Israelin jäännökset eivät tee väärin, eivät puhu valhetta, eikä heidän suussaan tavata vilpillistä kieltä. Sillä he kaitsevat kaittaviansa ja makaavat kenenkään peloittelematta.'),
(1691785,58,36,3,14,'Iloitse, tytär Siion, puhkea huutoon, Israel; ihastu ja ratkea riemuun kaikesta sydämestäsi, tytär Jerusalem.'),
(1691786,58,36,3,15,'Herra on poistanut sinun tuomiosi, kääntänyt pois sinun vihollisesi. Israelin kuningas, Herra, on sinun keskelläsi. Ei tarvitse sinun enää onnettomuutta nähdä.'),
(1691787,58,36,3,16,'Sinä päivänä sanotaan Jerusalemille: "Älä pelkää, Siion, älkööt kätesi hervotko.'),
(1691788,58,36,3,17,'Herra, sinun Jumalasi, on sinun keskelläsi, sankari, joka auttaa. Hän ilolla iloitsee sinusta, hän on ääneti, sillä hän rakastaa sinua, hän sinusta riemulla riemuitsee."'),
(1691789,58,36,3,18,'Jotka murehtivat, kaukana juhlakokouksista, ne minä kokoan: nehän ovat sinusta, niitä häväistys kuormana painaa.'),
(1691790,58,36,3,19,'Katso, siihen aikaan minä teen tekoni kaikille sinun nöyryyttäjillesi. Minä pelastan ontuvat ja kokoan karkoitetut ja teen heidät ylistetyiksi ja mainehikkaiksi jokaisessa maassa, jossa he olivat häpeänalaisina.'),
(1691791,58,37,1,1,'Kuningas Daarejaveksen toisena vuotena, kuudennessa kuussa, kuukauden ensimmäisenä päivänä, tuli tämä Herran sana profeetta Haggain kautta Juudan käskynhaltijalle Serubbaabelille, Sealtielin pojalle, ja ylimmäiselle papille Joosualle, Joosadakin pojalle:'),
(1691792,58,37,1,2,'"Näin sanoo Herra Sebaot: Tämä kansa sanoo: Aika ei ole tullut rakentaa Herran huonetta".'),
(1691793,58,37,1,3,'Mutta profeetta Haggain kautta tuli tämä Herran sana:'),
(1691794,58,37,1,4,'"Onko sitten aika teidän asua panelilla kaunistetuissa huoneissanne, kun tämä huone on rauniona?'),
(1691795,58,37,1,5,'Ja nyt sanoo Herra Sebaot näin: Ottakaa vaari teistänne.'),
(1691796,58,37,1,6,'Te kylvätte paljon, mutta saatte vähän. Te syötte, mutta ette tule ravituiksi. Te juotte, mutta jano ei sammu. Te vaatetatte itsenne, mutta ei tule lämmin. Ja palkkatyöläinen panee työpalkan reikäiseen kukkaroon.'),
(1691797,58,37,1,7,'Näin sanoo Herra Sebaot: Ottakaa vaari teistänne.'),
(1691798,58,37,1,8,'Nouskaa vuorille, tuokaa puita ja rakentakaa temppeli, niin minä siihen mielistyn ja näytän kunniani, sanoo Herra.'),
(1691799,58,37,1,9,'Te odotatte paljoa, mutta se menee vähiin. Te tuotte kotiin, mutta minä puhallan sen pois. Minkätähden? sanoo Herra Sebaot. Minun huoneeni tähden, kun se on rauniona ja te juoksette kukin oman huoneenne hyväksi.'),
(1691800,58,37,1,10,'Sentähden teiltä taivas pidättää kasteen ja maa pidättää satonsa.'),
(1691801,58,37,1,11,'Ja minä olen kutsunut kuivuuden maahan ja vuorille, viljalle, viinille ja öljylle, ja mitä vain maa tuottaa, ja ihmisille ja eläimille ja kaikelle kätten vaivannäölle."'),
(1691802,58,37,1,12,'Niin Serubbaabel, Sealtielin poika, ja ylimmäinen pappi Joosua, Joosadakin poika, ja kansan koko jäännös kuuli Herran, Jumalansa ääntä ja profeetta Haggain sanoja, jota varten Herra, heidän Jumalansa, oli hänet lähettänytkin, ja kansa pelkäsi Herraa.'),
(1691803,58,37,1,13,'Haggai, Herran sanansaattaja, sanoi, saattaen Herran sanan, kansalle näin: "Minä olen teidän kanssanne, sanoo Herra".'),
(1691804,58,37,1,14,'Ja Herra herätti Juudan käskynhaltijan Serubbaabelin, Sealtielin pojan, hengen ja ylimmäisen papin Joosuan, Joosadakin pojan, hengen ja kansan koko jäännöksen hengen, ja he tulivat ja ryhtyivät rakentamaan Herran Sebaotin, heidän Jumalansa, temppeliä'),
(1691805,58,37,1,15,'kahdentenakymmenentenä neljäntenä päivänä kuudennessa kuussa, kuningas Daarejaveksen toisena vuotena.'),
(1691806,58,37,2,1,'Seitsemännessä kuussa, kuukauden kahdentenakymmenentenä ensimmäisenä päivänä tuli profeetta Haggain kautta tämä Herran sana:'),
(1691807,58,37,2,2,'"Sano Juudan käskynhaltijalle Serubbaabelille, Sealtielin pojalle, ja ylimmäiselle papille Joosualle, Joosadakin pojalle, ja kansan jäännökselle näin:'),
(1691808,58,37,2,3,'Kuka teidän joukossanne on jäljelle jäänyt, joka on nähnyt tämän temppelin sen entisessä kunniassa? Ja miltä näyttää se teistä nyt? Eikö se ole tyhjän veroinen teidän silmissänne?'),
(1691809,58,37,2,4,'Mutta nyt ole luja, Serubbaabel, sanoo Herra, ja ole luja, Joosua, Joosadakin poika, ylimmäinen pappi, ja ole luja, maan koko kansa, sanoo Herra, ja tehkää työtä; sillä minä olen teidän kanssanne, sanoo Herra Sebaot.'),
(1691810,58,37,2,5,'Sen liiton sana, jonka minä tein teidän kanssanne, kun te läksitte Egyptistä, ja minun Henkeni pysyy teidän keskellänne. Älkää peljätkö.'),
(1691811,58,37,2,6,'Sillä näin sanoo Herra Sebaot: Vielä vähän aikaa, ja minä liikutan taivaat ja maan, meren ja kuivan.'),
(1691812,58,37,2,7,'Ja minä liikutan kaikki pakanakansat, ja kaikkien pakanakansojen kalleudet tulevat, ja minä täytän tämän temppelin kunnialla, sanoo Herra Sebaot.'),
(1691813,58,37,2,8,'Minun on hopea, ja minun on kulta, sanoo Herra Sebaot.'),
(1691814,58,37,2,9,'Tämän temppelin myöhempi kunnia on oleva suurempi kuin aikaisempi, sanoo Herra Sebaot. Ja tässä paikassa minä annan vallita rauhan, sanoo Herra Sebaot."'),
(1691815,58,37,2,10,'Yhdeksännen kuun kahdentenakymmenentenä neljäntenä päivänä, Daarejaveksen toisena vuotena, tuli profeetta Haggain kautta tämä Herran sana:'),
(1691816,58,37,2,11,'"Näin sanoo Herra Sebaot: Pyydä papeilta opetusta ja sano:'),
(1691817,58,37,2,12,'Katso, mies kantaa pyhää lihaa vaatteensa liepeessä ja koskettaa liepeellänsä leipää tai keittoa, viiniä, öljyä tai muuta ruokaa, mitä hyvänsä; tuleeko se siitä pyhäksi?" Niin papit vastasivat ja sanoivat: "Ei".'),
(1691818,58,37,2,13,'Ja Haggai sanoi: "Jos joku, joka on kuolleesta saastunut, koskettaa jotakin näistä, tuleeko se saastaiseksi?" Niin papit vastasivat: "Tulee saastaiseksi".'),
(1691819,58,37,2,14,'Silloin Haggai lausui ja sanoi: "Sellaista on tämä väki, sellaista tämä kansa minun edessäni, sanoo Herra. Sellaiset ovat kaikki heidän kättensä työt ja se, mitä he siellä uhriksi tuovat: se on saastaista.'),
(1691820,58,37,2,15,'Ja nyt ottakaa vaari, kuinka käy tästä päivästä lähtien eteenpäin. Kun ei vielä oltu pantu kiveä kiven päälle Herran temppelissä,'),
(1691821,58,37,2,16,'sitä ennen, mentiin kahdenkymmenen mitan viljakasalle, mutta oli vain kymmenen; mentiin viinikuurnalle ammentamaan viisikymmentä mittaa, mutta oli kaksikymmentä.'),
(1691822,58,37,2,17,'Minä löin teitä, kaikkia teidän kättenne töitä, nokitähkällä ja viljanruosteella ja rakeilla, mutta ei kenkään teistä kääntynyt minun puoleeni, sanoo Herra.'),
(1691823,58,37,2,18,'Ottakaa vaari, kuinka käy tästä päivästä lähtien eteenpäin, yhdeksännen kuun kahdennestakymmenennestä neljännestä päivästä, Herran temppelin perustamispäivästä, lähtien. Ottakaa vaari!'),
(1691824,58,37,2,19,'Onko aitassa enää siementä? Ja viiniköynnös, viikunapuu, granaattiomenapuu ja öljypuu, nekään eivät ole kantaneet hedelmää. Tästä päivästä lähtien minä annan siunauksen."'),
(1691825,58,37,2,20,'Ja Herran sana tuli toistamiseen Haggaille kuukauden kahdentenakymmenentenä neljäntenä päivänä; se kuului:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691826,58,37,2,21,'"Sano Juudan käskynhaltijalle Serubbaabelille: Minä liikutan taivaat ja maan.'),
(1691827,58,37,2,22,'Ja minä kukistan kuningaskuntien valtaistuimet, hävitän pakanain kuningaskuntien väkevyyden ja kukistan vaunut ajajineen; ja hevoset ja niiden ratsastajat kaatuvat, mies toisensa miekkaan.'),
(1691828,58,38,1,1,'Kahdeksannessa kuussa Daarejaveksen toisena vuotena tuli profeetta Sakarjalle, Berekjan pojalle, joka oli Iddon poika, tämä Herran sana:'),
(1691829,58,38,1,2,'"Herra on tuimasti vihastunut teidän isiinne.'),
(1691830,58,38,1,3,'Sano heille: Näin sanoo Herra Sebaot: Kääntykää minun tyköni, sanoo Herra Sebaot, niin minä käännyn teidän tykönne, sanoo Herra Sebaot.'),
(1691831,58,38,1,4,'Älkää olko isienne kaltaiset, joille entiset profeetat ovat saarnanneet sanoen: Näin sanoo Herra Sebaot: Kääntykää pois pahoilta teiltänne ja pahoista teoistanne; mutta he eivät kuulleet, eivät kuunnelleet minua.'),
(1691832,58,38,1,5,'Teidän isänne - missä he ovat? Ja profeetat - ovatko he eläneet iäti?'),
(1691833,58,38,1,6,'Mutta minun sanani ja käskyni, jotka minä olen säätänyt palvelijoilleni profeetoille - eivätkö ne ole kohdanneet teidän isiänne: ja niin he kääntyivät ja sanoivat: ''Niinkuin Herra Sebaot aikoi meille tehdä, meidän vaelluksemme ja tekojemme mukaan, niin hän on meille tehnyt''."'),
(1691834,58,38,1,7,'Kahdentenakymmenentenä neljäntenä päivänä yhdennessätoista kuussa, joka on sebat-kuu, Daarejaveksen toisena vuotena, tuli profeetta Sakarjalle, Berekjan pojalle, joka oli Iddon poika, tämä Herran sana:'),
(1691835,58,38,1,8,'Minä näin yöllä, katso, mies ratsasti punaisenruskealla hevosella, ja hän seisahtui myrttien keskelle laaksoon, ja hänen jäljessänsä oli punaisenruskeita ja punaisia ja valkeita hevosia.'),
(1691836,58,38,1,9,'Niin minä kysyin: "Mitä nämä ovat, Herra?" Enkeli, joka puhutteli minua, vastasi minulle: "Minä näytän sinulle, mitä ne ovat".'),
(1691837,58,38,1,10,'Ja mies, joka seisoi myrttien keskellä, lausui ja sanoi: "Nämä ovat ne, jotka Herra on lähettänyt maata kuljeksimaan".'),
(1691838,58,38,1,11,'Niin ne vastasivat Herran enkelille, joka seisoi myrttien keskellä, ja sanoivat: "Me olemme kuljeksineet maata, ja katso, koko maa on alallansa ja rauhassa".'),
(1691839,58,38,1,12,'Ja Herran enkeli lausui ja sanoi: "Herra Sebaot, kuinka kauan sinä viivyt etkä armahda Jerusalemia ja Juudan kaupunkeja, joille olet ollut vihainen nämä seitsemänkymmentä vuotta?"'),
(1691840,58,38,1,13,'Niin Herra vastasi enkelille, joka puhutteli minua, ja lausui hyviä, lohdullisia sanoja.'),
(1691841,58,38,1,14,'Ja enkeli, joka puhutteli minua, sanoi minulle: "Saarnaa ja sano: Näin sanoo Herra Sebaot: Minä kiivailen Jerusalemin ja Siionin puolesta suurella kiivaudella.'),
(1691842,58,38,1,15,'Suurella vihalla minä olen vihastunut suruttomiin pakanoihin, jotka, kun minä vähän vihastuin, auttoivat onnettomuutta tapahtumaan.'),
(1691843,58,38,1,16,'Sentähden sanoo Herra näin: Minä käännyn Jerusalemin puoleen armahtavaisuudessa. Minun temppelini siellä rakennetaan, sanoo Herra Sebaot, ja mittanuora jännitetään Jerusalemin ylitse.'),
(1691844,58,38,1,17,'Saarnaa vielä ja sano: Näin sanoo Herra Sebaot: Vielä minun kaupunkini ovat hyvyydestä ylitsevuotavaiset, ja vielä Herra lohduttaa Siionin ja valitsee vielä Jerusalemin."'),
(1691845,58,38,1,18,'Ja minä nostin silmäni ja katsoin. Ja katso: neljä sarvea.'),
(1691846,58,38,1,19,'Ja minä sanoin enkelille, joka puhutteli minua: "Mitä nämä ovat?" Niin hän sanoi minulle: "Nämä ovat ne sarvet, jotka ovat hajottaneet Juudan ja Israelin ja Jerusalemin".'),
(1691847,58,38,1,20,'Sitten Herra näytti minulle neljä seppää.'),
(1691848,58,38,1,21,'Minä sanoin: "Mitä nämä ovat tulleet tekemään?" Ja hän vastasi näin: "Nuo sarvet ovat ne, jotka ovat hajottaneet Juudan, niin ettei yksikään mies voi päätänsä nostaa; ja nämä ovat tulleet saattamaan ne pelkoon ja heittämään maahan niiden pakanakansain sarvet, jotka ovat nostaneet sarven Juudan maata vastaan hajottaaksensa sen".'),
(1691849,58,38,2,1,'Ja minä nostin silmäni ja katsoin. Ja katso, oli mies ja hänen kädessänsä mittanuora.'),
(1691850,58,38,2,2,'Minä sanoin hänelle: "Mihin sinä olet menossa?" Ja hän vastasi minulle: "Mittaamaan Jerusalemia, nähdäkseni, kuinka leveä ja kuinka pitkä se on oleva".'),
(1691851,58,38,2,3,'Ja katso, enkeli, joka puhutteli minua, lähti liikkeelle, ja toinen enkeli lähti häntä vastaan.'),
(1691852,58,38,2,4,'Ja hän sanoi tälle: "Juokse, puhu tälle nuorukaiselle ja sano: Jerusalem on oleva muuriton paikkakunta, sillä niin paljon siinä on ihmisiä ja eläimiä.'),
(1691853,58,38,2,5,'Mutta minä olen oleva, sanoo Herra, tulimuuri sen ympärillä ja kunnia sen keskellä.'),
(1691854,58,38,2,6,'Voi, voi, paetkaa pohjoisesta maasta, sanoo Herra! Sillä minä olen hajottanut teidät neljään taivaan tuuleen, sanoo Herra.'),
(1691855,58,38,2,7,'Voi, Siion, pelastaudu, sinä, joka asut tytär Baabelin luona!'),
(1691856,58,38,2,8,'Sillä näin sanoo Herra Sebaot: Kunniaksensa hän on lähettänyt minut pakanakansojen luokse, jotka ovat teitä saalistaneet. Sillä joka teihin koskee, se koskee hänen silmäteräänsä.'),
(1691857,58,38,2,9,'Sillä katso, minä heilutan kättäni heitä vastaan, ja he joutuvat orjiensa saaliiksi. Ja te tulette tietämään, että Herra Sebaot on lähettänyt minut.'),
(1691858,58,38,2,10,'Riemuitse ja iloitse, tytär Siion! Sillä minä tulen ja asun sinun keskelläsi, sanoo Herra.'),
(1691859,58,38,2,11,'Sinä päivänä liittyy paljon pakanakansoja Herraan, ja he tulevat hänen kansaksensa, ja minä asun sinun keskelläsi, ja sinä tulet tietämään, että Herra Sebaot on lähettänyt minut sinun tykösi.'),
(1691860,58,38,2,12,'Ja Herra ottaa Juudan perintöosaksensa pyhässä maassa ja valitsee vielä Jerusalemin.'),
(1691861,58,38,2,13,'Vaiti Herran edessä, kaikki liha! Sillä hän on noussut pyhästä asuinsijastansa."'),
(1691862,58,38,3,1,'Ja hän näytti minulle ylimmäisen papin Joosuan seisomassa Herran enkelin edessä ja saatanan seisomassa hänen oikealla puolellaan, häntä syyttämässä.'),
(1691863,58,38,3,2,'Ja Herra sanoi saatanalle: "Herra nuhdelkoon sinua, saatana. Nuhdelkoon sinua Herra, joka on valinnut Jerusalemin. Eikö tämä ole kekäle, joka on tulesta temmattu?"'),
(1691864,58,38,3,3,'Ja Joosua oli puettu saastaisiin vaatteisiin, ja hän seisoi enkelin edessä.'),
(1691865,58,38,3,4,'Niin tämä lausui ja sanoi näin niille, jotka seisoivat hänen edessänsä: "Riisukaa pois saastaiset vaatteet hänen yltänsä". Ja hän sanoi hänelle: "Katso, minä olen ottanut sinulta pois pahat tekosi, ja minä puetan sinut juhlavaatteisiin".'),
(1691866,58,38,3,5,'Minä sanoin: "Pantakoon puhdas käärelakki hänen päähänsä". Niin he panivat puhtaan käärelakin hänen päähänsä ja pukivat hänet vaatteisiin. Ja Herran enkeli seisoi siinä.'),
(1691867,58,38,3,6,'Ja Herran enkeli todisti Joosualle sanoen:'),
(1691868,58,38,3,7,'"Näin sanoo Herra Sebaot: Jos sinä vaellat minun teilläni ja hoidat minun säätämäni tehtävät, saat sinä myös tuomita minun huonettani ja vartioida minun esikartanoitani, ja minä annan sinulle pääsyn näiden joukkoon, jotka tässä seisovat.'),
(1691869,58,38,3,8,'Kuule, Joosua, ylimmäinen pappi, sinä ja sinun ystäväsi, jotka edessäsi istuvat. Sillä ennusmerkin miehiä he ovat; sillä katso, minä annan tulla palvelijani, Vesan.'),
(1691870,58,38,3,9,'Sillä katso: kivi, jonka minä olen asettanut Joosuan eteen - siihen yhteen kiveen päin on seitsemän silmää! Katso, minä kaiverran kaiverrukset siihen, sanoo Herra Sebaot, ja otan pois tämän maan pahat teot yhtenä päivänä.'),
(1691871,58,38,3,10,'Sinä päivänä te kutsutte, kukin ystävänsä, viinipuun ja viikunapuun alle."'),
(1691872,58,38,4,1,'Ja Herran enkeli, joka puhutteli minua, palasi ja herätti minut, niinkuin joku herätetään unestansa.'),
(1691873,58,38,4,2,'Ja hän sanoi minulle: "Mitä sinä näet?" Minä vastasin: "Minä näen, katso: lampunjalka, kokonansa kultaa, ja sen yläpuolella sen öljyastia, ja lampunjalassa sen seitsemän lamppua, ja seitsemän öljyputkea lamppuihin, jotka ovat siinä ylimpänä.'),
(1691874,58,38,4,3,'Ja kaksi öljypuuta sen ääressä, toinen öljyastian oikealla, toinen vasemmalla puolella."'),
(1691875,58,38,4,4,'Minä lausuin ja sanoin näin enkelille, joka puhutteli minua: "Mitä nämä ovat, Herra?"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691876,58,38,4,5,'Niin enkeli, joka puhutteli minua, vastasi ja sanoi minulle: "Etkö tiedä, mitä ne ovat?" Minä sanoin: "En, Herra".'),
(1691877,58,38,4,6,'Ja hän lausui ja sanoi minulle näin: "Tämä on Herran sana Serubbaabelille, näin kuuluva: Ei sotaväellä eikä voimalla, vaan minun Hengelläni, sanoo Herra Sebaot.'),
(1691878,58,38,4,7,'Mikä olet sinä, suuri vuori, Serubbaabelin edessä? Lakeudeksi sinä! Hän on paneva paikoillensa huippukiven huutojen kaikuessa: "Suosio, suosio sille!"'),
(1691879,58,38,4,8,'Ja minulle tuli tämä Herran sana:'),
(1691880,58,38,4,9,'"Serubbaabelin kädet ovat tämän temppelin perustaneet, ja hänen kätensä sen valmiiksi saattavat. Ja sinä tulet tietämään, että Herra Sebaot on lähettänyt minut teidän luoksenne.'),
(1691881,58,38,4,10,'Sillä kuka pitää halpana pienten alkujen päivän, kun nuo seitsemän Herran silmää, jotka tarkastavat koko maata, iloitsevat nähdessään luotilangan Serubbaabelin kädessä?"'),
(1691882,58,38,4,11,'Ja minä lausuin ja sanoin hänelle: "Mitä ovat nämä kaksi öljypuuta lampunjalan oikealla ja vasemmalla puolella?"'),
(1691883,58,38,4,12,'Sitten minä toistamiseen lausuin ja sanoin hänelle: "Mitä ovat nuo kaksi öljypuun terttua kahden kultaisen putken kohdalla, jotka vuodattavat sisästänsä öljynkultaa?"'),
(1691884,58,38,4,13,'Niin hän sanoi minulle näin: "Etkö tiedä, mitä ne ovat?" Minä vastasin: "En, Herra".'),
(1691885,58,38,4,14,'Hän sanoi: "Nämä ovat ne molemmat öljyllä voidellut, jotka seisovat kaiken maan Herran edessä".'),
(1691886,58,38,5,1,'Minä nostin jälleen silmäni, ja katso: oli lentävä kirjakäärö.'),
(1691887,58,38,5,2,'Ja hän sanoi minulle: "Mitä sinä näet?" Minä vastasin: "Minä näen lentävän kirjakäärön, kahtakymmentä kyynärää pitkän ja kymmentä kyynärää leveän".'),
(1691888,58,38,5,3,'Hän sanoi minulle: "Tämä on kirous, joka käy yli kaiken maan. Sillä tämän kirouksen mukaisesti siitä puhdistetaan pois jokainen varas, ja jokainen vannoskelija puhdistetaan siitä pois.'),
(1691889,58,38,5,4,'Minä lasken sen irti, sanoo Herra Sebaot, ja se menee varkaan kotiin ja sen kotiin, joka vannoo väärin minun nimeeni. Se jää sisälle hänen kotiinsa ja kalvaa sen loppuun asti, sekä sen puut että sen kivet."'),
(1691890,58,38,5,5,'Sitten enkeli, joka puhutteli minua, lähti liikkeelle ja sanoi minulle: "Nosta silmäsi ja katso: mikä tuo on, joka lähtee liikkeelle?"'),
(1691891,58,38,5,6,'Minä sanoin: "Mikä se sitten on?" Ja hän vastasi: "Tämä on eefa-mitta, joka lähtee liikkeelle". Ja hän sanoi: "Tämän näköisiä ne ovat koko maan päällä";'),
(1691892,58,38,5,7,'ja katso, lyijykansi kohosi, ja siinä istui eräs nainen eefa-mitan sisällä.'),
(1691893,58,38,5,8,'Ja hän sanoi: "Tämä on jumalattomuus". Ja hän paiskasi hänet sisälle eefa-mittaan ja paiskasi lyijypainon sen suulle.'),
(1691894,58,38,5,9,'Ja kun minä nostin silmäni, näin minä, katso, kaksi naista lähtevän liikkeelle, ja niillä oli tuulta siivissään, ja niiden siivet olivat kuin haikaran siivet; ja ne kantoivat eefa-mittaa taivaan ja maan välitse.'),
(1691895,58,38,5,10,'Niin minä sanoin enkelille, joka puhutteli minua: "Mihin ne kuljettavat eefa-mittaa?"'),
(1691896,58,38,5,11,'Ja hän vastasi minulle: "Ne menevät rakentamaan hänelle huonetta Sinearin maahan. Ja kun se on valmis, lasketaan hänet sinne paikoillensa."'),
(1691897,58,38,6,1,'Minä nostin jälleen silmäni ja näin, katso, neljät vaunut, jotka lähtivät liikkeelle kahden vuoren välistä; ja ne vuoret olivat vaskivuoria.'),
(1691898,58,38,6,2,'Ensimmäisten vaunujen edessä oli punaisenruskeat hevoset, toisten vaunujen edessä oli mustat hevoset,'),
(1691899,58,38,6,3,'kolmansien vaunujen edessä oli valkeat hevoset, ja neljänsien vaunujen edessä oli täplikkäät, väkevät hevoset.'),
(1691900,58,38,6,4,'Minä lausuin ja sanoin enkelille, joka puhutteli minua: "Mitä nämä ovat, Herra?"'),
(1691901,58,38,6,5,'Enkeli vastasi ja sanoi minulle: "Ne ovat neljä taivaan tuulta, jotka lähtevät liikkeelle seisottuansa kaiken maan Herran edessä.'),
(1691902,58,38,6,6,'Ne, joitten edessä on mustat hevoset, lähtevät pohjoiseen maahan, ja valkeat lähtevät niiden jäljessä. Täplikkäät lähtevät eteläiseen maahan.'),
(1691903,58,38,6,7,'Ne väkevät lähtevät, ja menevät halusta, kuljeksimaan maata." Ja hän sanoi: "Menkää, kuljeksikaa maata". Ja ne kuljeksivat maata.'),
(1691904,58,38,6,8,'Sitten hän huusi minut ja sanoi minulle näin: "Katso, ne, jotka lähtivät pohjoiseen maahan, saattavat minun Henkeni lepäämään pohjoisessa maassa".'),
(1691905,58,38,6,9,'Minulle tuli tämä Herran sana:'),
(1691906,58,38,6,10,'"Ota vastaan siirtolaisuudessa eläviltä Heldailta, Tobialta ja Jedajalta - mene tänä päivänä, mene Joosian, Sefanjan pojan, taloon, johon he ovat tulleet Baabelista, -'),
(1691907,58,38,6,11,'ja ota vastaan hopea ja kulta, tee kruunu ja pane se ylimmäisen papin Joosuan, Joosadakin pojan, päähän'),
(1691908,58,38,6,12,'ja sano hänelle näin: "Näin sanoo Herra Sebaot: Katso, mies nimeltä Vesa! Omalta pohjaltansa hän on kasvava, ja hän on rakentava Herran temppelin.'),
(1691909,58,38,6,13,'Herran temppelin hän on rakentava, ja valtasuuruutta hän on kantava, ja hän on istuva ja hallitseva valtaistuimellansa; hän on oleva pappi valtaistuimellansa, ja rauhan neuvo on vallitseva niitten molempien välillä.'),
(1691910,58,38,6,14,'Ja kruunu on oleva muistona Herran temppelissä Helemistä ja Tobiasta ja Jedajasta ja Sefanjan pojan suosiollisuudesta.'),
(1691911,58,38,6,15,'Ja kaukana asuvaiset tulevat ja rakentavat Herran temppeliä. Ja te tulette tietämään, että Herra Sebaot on lähettänyt minut teidän tykönne. Näin on tapahtuva, jos te hartaasti kuulette Herran, teidän Jumalanne, ääntä."'),
(1691912,58,38,7,1,'Kuningas Daarejaveksen neljäntenä vuotena tuli Herran sana Sakarjalle, neljäntenä päivänä yhdeksännessä kuussa, kislev-kuussa.'),
(1691913,58,38,7,2,'Beetel oli lähettänyt Sareserin ja Regem-Melekin miehinensä etsimään Herran mielisuosiota'),
(1691914,58,38,7,3,'ja kysymään Herran Sebaotin temppelin papeilta ynnä profeetoilta näin: "Onko minun viidennessä kuussa itkettävä ja noudatettava pidättyväisyyttä, niin kuin minä olen tehnyt jo kuinka monina vuosina?"'),
(1691915,58,38,7,4,'Niin minulle tuli tämä Herran Sebaotin sana:'),
(1691916,58,38,7,5,'"Sano kaikelle maan kansalle ja papeille näin: Kun te olette paastonneet ja valittaneet viidennessä ja seitsemännessä kuussa, ja jo seitsemänäkymmenenä vuotena, niin minulleko te olette paastonne paastonneet?'),
(1691917,58,38,7,6,'Ja kun olette syöneet ja juoneet, niin ettekö te ole itsellenne syöneet ja juoneet?'),
(1691918,58,38,7,7,'Eikö niin: pitäkää ne sanat, jotka Herra on julistanut entisten profeettain kautta, kun Jerusalem vielä oli asuttuna ja levossa, ympärillään alaisensa kaupungit, ja Etelämaa ja Alankomaa olivat asutut?"'),
(1691919,58,38,7,8,'Ja Sakarjalle tuli tämä Herran sana:'),
(1691920,58,38,7,9,'"Näin sanoo Herra Sebaot: Tuomitkaa oikea tuomio, tehkää laupeus ja olkaa armahtavaiset kukin veljellenne,'),
(1691921,58,38,7,10,'leskeä, orpoa, muukalaista ja kurjaa älkää sortako, älkääkä miettikö mielessänne pahaa, kukin veljeänsä vastaan.'),
(1691922,58,38,7,11,'Mutta he eivät tahtoneet ottaa vaaria, vaan käänsivät uppiniskaisina selkänsä ja kovettivat korvansa, etteivät kuulisi.'),
(1691923,58,38,7,12,'Ja he tekivät sydämensä kovaksi kuin timantti, etteivät kuulisi lakia eikä niitä sanoja, mitkä Herra Sebaot on lähettänyt Henkensä voimalla entisten profeettain kautta; ja niin on Herralta Sebaotilta tullut suuri vihastus.'),
(1691924,58,38,7,13,'Samoin kuin hän huusi, mutta he eivät kuulleet, samoin he huutavat, mutta minä en kuule, sanoo Herra Sebaot.'),
(1691925,58,38,7,14,'Ja minä myrskynä karkoitan heidät kaikkien pakanakansojen sekaan, joita he eivät tunne, ja maa jää heidän jälkeensä autioksi menijöistä ja tulijoista. Ihanan maan he tekevät autioksi."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691926,58,38,8,1,'Sitten tuli tämä Herran Sebaotin sana:'),
(1691927,58,38,8,2,'"Näin sanoo Herra Sebaot: Minä kiivailen Siionin puolesta suurella kiivaudella, suurella vihalla minä sen puolesta kiivailen.'),
(1691928,58,38,8,3,'Näin sanoo Herra: Minä käännyn jälleen Siionin puoleen ja tulen asumaan Jerusalemin keskelle, ja Jerusalemia kutsutaan Uskolliseksi Kaupungiksi ja Herran Sebaotin vuorta Pyhäksi Vuoreksi.'),
(1691929,58,38,8,4,'Näin sanoo Herra Sebaot: Vielä on Jerusalemin toreilla istuva vanhuksia ja vanhoja vaimoja, sauvansa kädessään kullakin päivien paljouden vuoksi.'),
(1691930,58,38,8,5,'Ja kaupungin torit tulevat olemaan täynnä poikasia ja tyttösiä, jotka leikkivät sen toreilla.'),
(1691931,58,38,8,6,'Näin sanoo Herra Sebaot: Jos tämä onkin ihmeellistä tämän kansan jäännöksen silmissä niinä päivinä, pitäisikö sen olla ihmeellistä myös minun silmissäni, sanoo Herra Sebaot?'),
(1691932,58,38,8,7,'Näin sanoo Herra Sebaot: Katso, minä olen vapauttava kansani auringon nousun maasta ja laskun maasta.'),
(1691933,58,38,8,8,'Ja minä tuon heidät asumaan Jerusalemin keskelle. Ja he ovat minun kansani, ja minä olen heidän Jumalansa, uskollinen ja vanhurskas.'),
(1691934,58,38,8,9,'Näin sanoo Herra Sebaot: Olkoot lujat teidän kätenne, teidän, jotka tähän aikaan olette kuulleet nämä sanat profeettain suusta, sinä päivänä, jona laskettiin Herran Sebaotin huoneen, rakennettavan temppelin, perustus.'),
(1691935,58,38,8,10,'Sillä ennen sitä aikaa ei saatu palkkaa ihmisen työstä, ei palkkaa juhdan työstä, eikä ollut menijällä, ei tulijalla rauhaa ahdistajalta, ja minä laskin irti kaikki ihmiset, toisen toisensa kimppuun.'),
(1691936,58,38,8,11,'Mutta nyt minä en ole tämän kansan jäännökselle samanlainen, kuin olin entisinä päivinä, sanoo Herra Sebaot.'),
(1691937,58,38,8,12,'Sillä rauhan kylvö kylvetään, viiniköynnös antaa hedelmänsä, maa antaa satonsa, taivas antaa kasteensa, ja tämän kansan jäännökselle minä annan perintöosaksi kaiken tämän.'),
(1691938,58,38,8,13,'Ja niinkuin te olette olleet kirouksena pakanakansain seassa, te Juudan heimo ja Israelin heimo, niin te, kun minä teidät vapahdan, tulette olemaan siunauksena. Älkää peljätkö, olkoot teidän kätenne lujat.'),
(1691939,58,38,8,14,'Sillä näin sanoo Herra Sebaot: Niinkuin minulla oli mielessä tehdä teille pahaa, kun teidän isänne vihoittivat minut, sanoo Herra Sebaot, enkä minä sitä katunut,'),
(1691940,58,38,8,15,'niin on taas tähän aikaan minulla mielessä tehdä hyvää Jerusalemille ja Juudan heimolle. Älkää peljätkö.'),
(1691941,58,38,8,16,'Näitä te tehkää: Puhukaa totta toinen toisellenne. Tuomitkaa porteissanne oikein, tuomitkaa rauhan tuomio.'),
(1691942,58,38,8,17,'Älkää hautoko mielessänne pahaa toinen toisellenne, älkääkä rakastako väärää valaa. Sillä kaikkia näitä minä vihaan, sanoo Herra."'),
(1691943,58,38,8,18,'Ja minulle tuli tämä Herran Sebaotin sana:'),
(1691944,58,38,8,19,'"Näin sanoo Herra Sebaot: Neljännen kuun paasto ja viidennen paasto ja seitsemännen paasto ja kymmenennen paasto on oleva Juudan heimolle ilo ja riemu ja mieluinen juhla. Mutta rakastakaa totuutta ja rauhaa.'),
(1691945,58,38,8,20,'Näin sanoo Herra Sebaot: Vielä tulee kansoja, monien kaupunkien asukkaita,'),
(1691946,58,38,8,21,'ja toisen asukkaat menevät toiseen ja sanovat: ''Lähtekäämme, käykäämme etsimään Herran mielisuosiota, etsimään Herraa Sebaotia''. - ''Minäkin lähden.'''),
(1691947,58,38,8,22,'Ja monet kansat, väkevät pakanakansat, tulevat Jerusalemiin etsimään Herraa Sebaotia, etsimään Herran mielisuosiota.'),
(1691948,58,38,8,23,'Näin sanoo Herra Sebaot: Niinä päivinä tarttuu kymmenen miestä kaikista pakanakansain kielistä, tarttuu Juudan miestä liepeeseen sanoen: ''Me tahdomme käydä teidän kanssanne, sillä me olemme kuulleet, että Jumala on teidän kanssanne''."'),
(1691949,58,38,9,1,'Ennustus, Herran sana, Hadrakin maata vastaan, ja Damaskoon se laskeutuu. Sillä Herran silmä katsoo ihmisiä, kaikkia Israelin sukukuntia'),
(1691950,58,38,9,2,'ja myös Hamatia, joka on sen kanssa rajatusten, sekä Tyyroa ja Siidonia, sillä ne ovat sangen viisaat.'),
(1691951,58,38,9,3,'Tyyro on rakentanut itsellensä linnoituksia ja kasannut kokoon hopeata kuin tomua ja kultaa kuin katujen lokaa.'),
(1691952,58,38,9,4,'Katso, Herra köyhdyttää sen ja syöksee mereen sen voiman, ja se itse poltetaan tulella.'),
(1691953,58,38,9,5,'Sen näkee Askelon ja peljästyy, ja Gassa, ja vapisee kovin, ja Ekron, sillä sen toivo joutuu häpeään. Ja Gassasta hukkuu kuningas, eikä Askelonissa enää asuta.'),
(1691954,58,38,9,6,'Asdodissa asuu sekasikiöitä, ja minä hävitän filistealaisten ylpeyden.'),
(1691955,58,38,9,7,'Mutta minä poistan veret hänen suustansa ja heidän iljetyksensä hänen hampaittensa välistä, ja hänestäkin jää jäännös meidän Jumalallemme; hän on oleva niinkuin sukuruhtinas Juudassa, ja Ekron on oleva niinkuin jebusilainen.'),
(1691956,58,38,9,8,'Minä teen leirini temppelini suojaksi sotajoukoilta, jotka tulevat ja menevät, eikä tule käskijä enää heidän kimppuunsa, sillä nyt olen minä sen omin silmin nähnyt.'),
(1691957,58,38,9,9,'Iloitse suuresti, tytär Siion, riemuitse, tytär Jerusalem, sillä sinun kuninkaasi tulee sinulle! Vanhurskas ja auttaja hän on, on nöyrä ja ratsastaa aasilla, aasintamman varsalla.'),
(1691958,58,38,9,10,'Ja minä hävitän vaunut Efraimista ja hevoset Jerusalemista. Sodan jousi hävitetään, ja hän julistaa rauhan kansoille. Ja hänen hallituksensa ulottuu merestä mereen, Eufrat-virrasta hamaan maan ääriin.'),
(1691959,58,38,9,11,'Ja myös sinun vankisi minä sinun liittosi veren tähden päästän pois vedettömästä kuopasta.'),
(1691960,58,38,9,12,'Tulkaa takaisin varustukseen, te vangit, joilla on toivo; myös tänä päivänä minä julistan: kaksin verroin minä sinulle korvaan.'),
(1691961,58,38,9,13,'Sillä minä jännitän Juudan jousekseni, panen siihen nuoleksi Efraimin ja nostan sinun poikasi, Siion, sinun poikiasi vastaan, Jaavan, ja teen sinut sankarin miekan kaltaiseksi.'),
(1691962,58,38,9,14,'Herra on näkyvä heidän yllänsä, ja hänen nuolensa lähtee kuin salama. Herra, Herra puhaltaa pasunaan ja kulkee etelän myrskytuulissa.'),
(1691963,58,38,9,15,'Herra Sebaot on suojaava heitä, ja he syövät, ja he tallaavat linkokiviä, he juovat ja pauhaavat niinkuin viinistä ja ovat täynnä, niinkuin uhrimaljat, niinkuin alttarin kulmat.'),
(1691964,58,38,9,16,'Ja Herra, heidän Jumalansa, on sinä päivänä auttava heitä, kansaansa, joka on kuin hänen lammaslaumansa; sillä he ovat kruunuun kiinnitettyjä kiviä, jotka kohoavat yli hänen maansa.'),
(1691965,58,38,9,17,'Sillä kuinka suuri onkaan oleva heidän onnensa, heidän ihanuutensa: vilja saa kasvamaan nuorukaiset ja rypälemehu neitsyet!'),
(1691966,58,38,10,1,'Rukoilkaa Herralta sadetta kevätsateen aikana: Herra tekee ukkospilvet ja antaa heille sadekuurot, antaa kasvit joka miehen pellolle.'),
(1691967,58,38,10,2,'Sillä kotijumalat puhuvat tyhjiä, ja tietäjät näkevät petosnäkyjä, puhuvat valheunia, lohduttelevat turhilla. Sentähden he saavat lähteä matkaan kuin lammaslauma ja kärsivät vaivaa, kun ei ole paimenta.'),
(1691968,58,38,10,3,'Paimenia kohtaan syttyy minun vihani, ja johtomiehiä minä rankaisen; sillä Herra Sebaot pitää huolen laumastansa, Juudan heimosta, ja asettaa sen ikäänkuin kunniaratsuksensa sodassa.'),
(1691969,58,38,10,4,'Siitä on lähtevä kulmakivi, siitä kiinnityspaalu, siitä sotajousi, siitä lähtevät käskijät kaikki.'),
(1691970,58,38,10,5,'Ja he ovat niinkuin sankarit, jotka polkevat katujen lokaa sodassa. He sotivat, sillä Herra on heidän kanssansa; ja häpeään joutuvat hevosilla-ratsastajat.'),
(1691971,58,38,10,6,'Minä teen väkeväksi Juudan heimon ja autan Joosefin heimoa. Minä saatan heidät kotiin, sillä minä armahdan heitä, ja he tulevat olemaan, niinkuin en minä olisi heitä hyljännytkään. Sillä minä olen Herra, heidän Jumalansa, ja kuulen heidän rukouksensa.'),
(1691972,58,38,10,7,'Efraim on oleva niinkuin sankari, ja heidän sydämensä on iloitseva niinkuin viinistä. Heidän lapsensa näkevät sen ja iloitsevat; heidän sydämensä riemuitsee Herrassa.'),
(1691973,58,38,10,8,'Minä olen viheltävä heille ja kokoava heidät, sillä minä lunastan heidät, ja he lisääntyvät, niinkuin lisääntyivät ennen.'),
(1691974,58,38,10,9,'Kun minä sirotan heidät kansojen sekaan, muistavat he minua kaukaisissa maissa; ja he lastensa kanssa saavat elää ja palata takaisin.'),
(1691975,58,38,10,10,'Minä tuon heidät takaisin Egyptin maasta ja kokoan heidät Assurista; minä vien heidät Gileadin maahan ja Libanonille, eikä heille ole riittävästi tilaa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1691976,58,38,10,11,'Hän käy ahdistuksen meren lävitse, hän lyö meren aaltoja, ja kaikki Niilivirran syvyydet kuivuvat, Assurin ylpeys painuu alas, ja Egyptin valtikka väistyy pois.'),
(1691977,58,38,10,12,'Mutta heidät minä teen väkeviksi Herrassa, ja hänen nimensä on heidän kerskauksensa, sanoo Herra.'),
(1691978,58,38,11,1,'Avaa ovesi, Libanon! Tuli on kuluttava sinun setrisi.'),
(1691979,58,38,11,2,'Valittakoon kypressi, sillä setri on kaatunut, hävitetyt ovat nuo mahtavat. Valittakaa, te Baasanin tammet, sillä sankka metsä on sortunut.'),
(1691980,58,38,11,3,'Kuule paimenten valitusta, kun on hävitetty nuo heidän mahtavansa. Kuule nuorten leijonain ärjyntää, kun on hävitetty Jordanin rantatiheikkö.'),
(1691981,58,38,11,4,'Näin sanoi Herra, minun Jumalani:'),
(1691982,58,38,11,5,'"Kaitse teuraslampaita, joita niiden ostajat teurastavat tuntematta syynalaisuutta, ja joista niiden myyjät sanovat: ''Kiitetty olkoon Herra, minä olen rikastunut'', ja joita niiden paimenet eivät sääli.'),
(1691983,58,38,11,6,'Sillä minä en enää sääli maan asukkaita, sanoo Herra. Katso, minä annan ihmisten joutua toistensa käsiin ja kuninkaansa käsiin, ja he hävittävät maan, enkä minä pelasta ketään heidän käsistänsä."'),
(1691984,58,38,11,7,'Niin minä siis kaitsin teuraslampaita, lampaista kurjimpia. Ja minä otin itselleni kaksi sauvaa; minä nimitin toisen "Suloudeksi", toisen minä nimitin "Yhteydeksi", ja niin minä kaitsin lampaita.'),
(1691985,58,38,11,8,'Ja minä hävitin kolme paimenta yhtenä kuukautena, mutta minä kävin kärsimättömäksi lampaille, ja hekin kyllästyivät minuun.'),
(1691986,58,38,11,9,'Niin minä sanoin: "Minä en tahdo enää teitä kaita. Kuolkoon, joka kuolee; hävitköön, joka häviää; ja jäljellejäävät syökööt kukin toisensa lihaa."'),
(1691987,58,38,11,10,'Ja minä otin sauvani Sulouden ja katkaisin sen purkaakseni liittoni, jonka olin tehnyt kaikkien kansojen kanssa.'),
(1691988,58,38,11,11,'Ja sinä päivänä se purkautui, ja niin lampaista kurjimmat, jotka ottivat minusta vaarin, tulivat tietämään, että se oli Herran sana.'),
(1691989,58,38,11,12,'Sitten minä sanoin heille: "Jos teille hyväksi näkyy, niin antakaa minulle palkkani; jollei, niin olkaa antamatta". Niin he punnitsivat minun palkakseni kolmekymmentä hopearahaa.'),
(1691990,58,38,11,13,'Ja Herra sanoi minulle: "Viskaa se savenvalajalle, tuo kallis hinta, jonka arvoiseksi he ovat minut arvioineet". Niin minä otin ne kolmekymmentä hopearahaa ja viskasin ne Herran huoneeseen savenvalajalle.'),
(1691991,58,38,11,14,'Sitten minä katkaisin toisen sauvani, Yhteyden, purkaakseni veljeyden Juudan ja Israelin väliltä.'),
(1691992,58,38,11,15,'Sitten Herra sanoi minulle: "Ota vielä itsellesi hullun paimenen kapineet.'),
(1691993,58,38,11,16,'Sillä katso, minä olen herättävä maahan paimenen: hukkaantuneista hän ei pidä huolta, hajaantunutta hän ei etsi, ruhjoutunutta hän ei paranna, pystyssäpysyvää hän ei tue; mutta hän syö lihavien lihaa ja halkaisee niiden sorkat.'),
(1691994,58,38,11,17,'Voi hullua paimenta, joka lampaat hylkää! Käyköön miekka hänen käsivarteensa ja oikeaan silmäänsä. Hänen käsivartensa kuivettukoon, ja hänen oikea silmänsä soetkoon."'),
(1691995,58,38,12,1,'Ennustus, Herran sana Israelista. Näin sanoo Herra, joka on jännittänyt taivaan ja perustanut maan ja joka on luonut ihmisen hengen hänen sisimpäänsä:'),
(1691996,58,38,12,2,'Katso, minä teen Jerusalemin juovuttavaksi maljaksi kaikille kansoille yltympäri, ja myös Juudan kohdalle se on tuleva Jerusalemia piiritettäessä.'),
(1691997,58,38,12,3,'Ja sinä päivänä minä teen Jerusalemin väkikiveksi kaikille kansoille: kaikki, jotka sitä nostavat, repivät pahoin itsensä; ja kaikki maan kansakunnat kokoontuvat sitä vastaan.'),
(1691998,58,38,12,4,'Sinä päivänä, sanoo Herra, minä lyön kaikki hevoset vauhkoudella ja niiden ratsastajat hulluudella. Mutta Juudan heimoa kohti minä avaan silmäni, ja kaikki kansojen hevoset minä lyön sokeudella.'),
(1691999,58,38,12,5,'Silloin Juudan sukuruhtinaat sanovat sydämessään: "Minun väkevyyteni ovat Jerusalemin asukkaat Herrassa Sebaotissa, heidän Jumalassansa".'),
(1692000,58,38,12,6,'Sinä päivänä minä teen Juudan sukuruhtinaat ikäänkuin tulipannuksi puitten sekaan ja ikäänkuin tulisoihduksi lyhteitten sekaan, ja he kuluttavat oikealta ja vasemmalta, kuluttavat kaikki kansat yltympäri. Ja Jerusalem saa yhäti asua paikoillansa - Jerusalemissa.'),
(1692001,58,38,12,7,'Ja Herra on ensiksi vapauttava Juudan majat, ettei Daavidin suvun kunnia ja Jerusalemin asukasten kunnia ylvästelisi Juudaa vastaan.'),
(1692002,58,38,12,8,'Sinä päivänä on Herra suojaava Jerusalemin asukkaita; ja kompastuvainen heidän seassansa on sinä päivänä oleva niinkuin Daavid, ja Daavidin suku on oleva niinkuin jumal''olento, niinkuin Herran enkeli heidän edessänsä.'),
(1692003,58,38,12,9,'Mutta sinä päivänä minä tahdon hävittää kaikki pakanakansat, jotka hyökkäävät Jerusalemia vastaan.'),
(1692004,58,38,12,10,'Ja minä vuodatan Daavidin suvun päälle ja Jerusalemin asukasten päälle armon ja rukouksen hengen. He katsovat minuun, jonka he ovat lävistäneet. Ja he valittavat häntä, niinkuin valitetaan ainokaista, murehtivat häntä katkerasti, niinkuin murehditaan katkerasti esikoista.'),
(1692005,58,38,12,11,'Sinä päivänä pidetään Jerusalemissa suuret valittajaiset, niinkuin olivat Hadadrimmonin valittajaiset Megiddon laaksossa.'),
(1692006,58,38,12,12,'Ja maa pitää valittajaisia, kukin sukukunta erikseen: Daavidin huoneen sukukunta erikseen ja heidän naisensa erikseen, Naatanin huoneen sukukunta erikseen ja heidän naisensa erikseen,'),
(1692007,58,38,12,13,'Leevin huoneen sukukunta erikseen ja heidän naisensa erikseen, siimeiläisten sukukunta erikseen ja heidän naisensa erikseen. Kaikki muut sukukunnat, kukin sukukunta erikseen ja heidän naisensa erikseen.'),
(1692008,58,38,13,1,'Sinä päivänä on Daavidin suvulla ja Jerusalemin asukkailla oleva avoin lähde syntiä ja saastaisuutta vastaan.'),
(1692009,58,38,13,2,'Ja sinä päivänä, sanoo Herra Sebaot, minä hävitän epäjumalain nimet maasta, eikä niitä enää muisteta. Myöskin profeetat ja saastaisuuden hengen minä ajan maasta pois.'),
(1692010,58,38,13,3,'Ja jos joku vielä ennustaa, sanovat hänen isänsä ja äitinsä, hänen vanhempansa, hänelle: "Sinä et saa elää, koska olet puhunut valhetta Herran nimeen". Ja hänen isänsä ja äitinsä, hänen vanhempansa, lävistävät hänet hänen ennustamisensa tähden.'),
(1692011,58,38,13,4,'Sinä päivänä häpeävät profeetat itsekukin näkyään, kun he ennustavat, eivätkä he valhetellakseen pue yllensä karvaista vaippaa.'),
(1692012,58,38,13,5,'Hän sanoo: "En ole profeetta, vaan peltomies, sillä eräs mies on ostanut minut orjaksi jo nuoruudessani".'),
(1692013,58,38,13,6,'Ja jos häneltä kysytään: "Mitä ovat nuo haavat sinun rinnassasi?" vastaa hän: "Ne lyötiin minun ystäväini huoneessa".'),
(1692014,58,38,13,7,'Heräjä, miekka, minun paimentani vastaan ja minun lähintä miestäni vastaan, sanoo Herra Sebaot. Lyö paimenta, ja joutukoot lampaat hajallensa; mutta minä käännän jälleen käteni pienimpiä kohden.'),
(1692015,58,38,13,8,'Ja näin on käyvä koko maassa, sanoo Herra: kaksi osaa siitä hävitetään ja saa surmansa, mutta kolmas osa siitä jää jäljelle.'),
(1692016,58,38,13,9,'Ja sen kolmannen osan minä vien tuleen; minä sulatan heidät, niinkuin hopea sulatetaan, ja koettelen heitä, niinkuin kulta koetellaan. He huutavat avuksi minun nimeäni, ja minä vastaan heille. Minä sanon: "Se on minun kansani", ja se sanoo: "Herra, minun Jumalani".'),
(1692017,58,38,14,1,'Katso, Herran päivä on tuleva, ja sinun saaliisi jaetaan sinun keskelläsi.'),
(1692018,58,38,14,2,'Minä kokoan kaikki pakanat sotaan Jerusalemia vastaan. Kaupunki valloitetaan, talot ryöstetään, naiset raiskataan, ja puoli kaupunkia lähtee pakkosiirtolaisuuteen, mutta jäljelle jäävää kansaa ei hävitetä kaupungista.'),
(1692019,58,38,14,3,'Ja Herra on lähtevä liikkeelle ja sotiva näitä pakanoita vastaan, niinkuin sotimispäivänänsä, taistelun päivänä.'),
(1692020,58,38,14,4,'Hänen jalkansa seisovat sinä päivänä Öljymäellä, joka on Jerusalemin edustalla itää kohti. Ja Öljymäki halkeaa kahtia idästä länteen hyvin suureksi laaksoksi: toinen puoli mäkeä siirtyy pohjoiseen ja toinen puoli etelään päin.'),
(1692021,58,38,14,5,'Ja te pakenette minun mäkieni väliseen laaksoon, sillä mäkien välinen laakso on ulottuva Asaliin asti. Te pakenette, niinkuin pakenitte maanjäristystä Ussian, Juudan kuninkaan, päivinä. Ja Herra, minun Jumalani, tulee; kaikki pyhät sinun kanssasi.'),
(1692022,58,38,14,6,'Sinä päivänä ei ole valoa: loistavat tähdet sammuvat.'),
(1692023,58,38,14,7,'Se on oleva yhtämittaista päivää - Herralle on se tunnettu - ei vaihdu päivä ja yö; ja ehtoolla on oleva valoisata.'),
(1692024,58,38,14,8,'Sinä päivänä elävät vedet virtaavat Jerusalemista: toiset puolet niistä Idänmerta kohti, toiset puolet Länsimerta kohti. Niin on tapahtuva kesät ja talvet.'),
(1692025,58,38,14,9,'Herra on oleva koko maan kuningas. Sinä päivänä on Herra oleva yksi ja hänen nimensä yksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692026,58,38,14,10,'Koko maa muuttuu tasaiseksi kuin Aromaa Gebasta Rimmoniin asti, Jerusalemin eteläpuolelle. Ja tämä on oleva korkea ja oleva asuttu, paikallansa, Benjaminin portista entisen portin sijaan asti, Kulmaporttiin ja Hananelin-torniin asti, kuninkaan viinikuurniin asti.'),
(1692027,58,38,14,11,'He asuvat siellä, eikä vihitä sitä enää tuhon omaksi, ja Jerusalem on oleva asuttu, oleva turvassa.'),
(1692028,58,38,14,12,'Ja tämä on oleva vitsaus, jolla Herra rankaisee niitä kansoja, jotka sotivat Jerusalemia vastaan: hän mädättää siltä kansalta lihan, kun se vielä seisoo jaloillaan, sen silmät mätänevät kuopissansa, ja sen kieli mätänee sen suussa.'),
(1692029,58,38,14,13,'Sinä päivänä on tuleva Herralta suuri hämminki heidän sekaansa, niin että he käyvät kiinni toinen toisensa käteen ja toisen käsi kohoaa toisen kättä vastaan.'),
(1692030,58,38,14,14,'Myös Juuda on sotiva Jerusalemissa, ja kaikkien pakanakansojen rikkaudet kootaan joka taholta: kullat ja hopeat ja ylen paljon vaatteita.'),
(1692031,58,38,14,15,'Samoin on vitsaus kohtaava hevosia ja muuleja ja kameleja ja aaseja ja kaikkea karjaa, mitä niissä leireissä on - samankaltainen vitsaus.'),
(1692032,58,38,14,16,'Mutta kaikki niiden pakanakansain tähteet, jotka ovat hyökänneet Jerusalemia vastaan, käyvät vuosi vuodelta sinne ylös kumartaen rukoilemaan kuningasta, Herraa Sebaotia, ja viettämään lehtimajanjuhlaa.'),
(1692033,58,38,14,17,'Ja mitkä maan sukukunnista eivät käy ylös Jerusalemiin kumartaen rukoilemaan kuningasta, Herraa Sebaotia, niille ei tule sadetta.'),
(1692034,58,38,14,18,'Ja jos egyptiläisten sukukunta ei käy eikä tule sinne ylös, ei tule sitä heillekään; vaan heitä on kohtaava se vitsaus, millä Herra rankaisee niitä pakanakansoja, jotka eivät tule sinne ylös viettämään lehtimajanjuhlaa.'),
(1692035,58,38,14,19,'Tämä on oleva egyptiläisten synnin palkka ja kaikkien niiden pakanakansojen synnin palkka, jotka eivät käy sinne ylös viettämään lehtimajanjuhlaa.'),
(1692036,58,38,14,20,'Sinä päivänä on oleva hevosten kulkusissa kirjoitus: "Pyhitetty Herralle". Ja padat Herran temppelissä ovat uhrimaljain vertaisia, jotka ovat alttarin edessä.'),
(1692037,58,39,1,1,'Ennustus, Herran sana Israelille, Malakian kautta.'),
(1692038,58,39,1,2,'Minä olen teitä rakastanut, sanoo Herra. Mutta te sanotte: "Missä sinä olet osoittanut rakkautesi meihin?" Eikö Eesau ollut Jaakobin veli, sanoo Herra, ja Jaakobia minä rakastin,'),
(1692039,58,39,1,3,'mutta Eesauta minä vihasin; ja minä tein hänen vuorensa autioiksi ja annoin hänen perintöosansa erämaan aavikkosusille.'),
(1692040,58,39,1,4,'Jos Edom sanoo: "Me olemme ruhjotut, mutta me rakennamme rauniot jälleen", niin Herra Sebaot sanoo näin: He rakentakoot, mutta minä revin maahan; ja heidän nimensä olkoon: "jumalattomuuden maa" ja "kansa, johon Herra on vihastunut iankaikkisesti".'),
(1692041,58,39,1,5,'Ja teidän silmänne saavat nähdä sen, ja te sanotte: "Herra on suuri Israelin rajojen ulkopuolellakin".'),
(1692042,58,39,1,6,'Poika kunnioittakoon isää ja palvelija herraansa. Mutta jos minä olen isä, missä on minun kunnioitukseni? Ja jos minä olen Herra, missä on minun pelkoni? sanoo Herra Sebaot teille, te papit, jotka pidätte halpana minun nimeni. Mutta te sanotte: "Miten me olemme pitäneet halpana sinun nimesi?"'),
(1692043,58,39,1,7,'Siten, että tuotte minun alttarilleni saastutettua leipää. Mutta te sanotte: "Miten me olemme sinut saastuttaneet?" Siten, että sanotte: "Herran pöytä on halpana pidettävä".'),
(1692044,58,39,1,8,'Ja kun te tuotte uhriksi sokean eläimen, niin se muka ei ole paha! Ja kun tuotte ontuvan ja sairaan, niin se muka ei ole paha! Vie se maaherrallesi: mielistyykö hän sinuun, ja onko hän sinulle suosiollinen? sanoo Herra Sebaot.'),
(1692045,58,39,1,9,'Ja nyt: lepyttäkää Jumalaa, että hän meitä armahtaisi. Tällaista on teidän kädestänne tullut: olisiko hän teille suosiollinen? sanoo Herra Sebaot.'),
(1692046,58,39,1,10,'Jospa olisi teidän joukossanne joku, joka sulkisi ovet, ettette pitäisi tulta minun alttarillani turhaan! Ei ole minulla mielisuosiota teihin, sanoo Herra Sebaot, enkä minä mielisty ruokauhriin, joka tulee teidän kädestänne.'),
(1692047,58,39,1,11,'Sillä auringon noususta hamaan sen laskuun on minun nimeni oleva suuri pakanain seassa, ja joka paikassa uhrataan ja tuodaan minun nimeni kunniaksi puhdas ruokauhri. Sillä minun nimeni on oleva suuri pakanain seassa, sanoo Herra Sebaot.'),
(1692048,58,39,1,12,'Mutta te häpäisette sen, kun sanotte: "Herran pöytä on saastutettu, ja sen hedelmän syönti on halpana pidettävä".'),
(1692049,58,39,1,13,'Ja te sanotte: "Mikä vaiva!" ja ylenkatsotte sen, sanoo Herra Sebaot, ja tuotte ryöstettyä, ontuvaa ja sairasta - tuotte uhrilahjaksi. - Minäkö mielistyisin ottamaan sen teidän kädestänne? sanoo Herra.'),
(1692050,58,39,1,14,'Kirottu olkoon pettäjä, jolla on laumassaan koiraspuoli ja joka on luvannut sen, mutta uhraakin Herralle viallisen. Sillä suuri kuningas olen minä, sanoo Herra Sebaot, ja minun nimeni on peljättävä pakanain seassa.'),
(1692051,58,39,2,1,'Ja nyt teille tämä käsky, te papit!'),
(1692052,58,39,2,2,'Jos ette kuule ja paina sydämeenne, niin että annatte kunnian minun nimelleni, sanoo Herra Sebaot, lähetän minä teitä vastaan kirouksen ja kiroan teille suodut siunaukset. Minä olenkin ne jo kironnut, sillä te ette ole painaneet tätä sydämeenne.'),
(1692053,58,39,2,3,'Minä kiellän teiltä jälkeläiset, ja minä viskelen rapaa teidän kasvoihinne, teidän juhlauhrienne rapaa, ja siihen teidät itsenne kannetaan.'),
(1692054,58,39,2,4,'Ja te tulette tietämään, että minä olen lähettänyt teille tämän käskyn, jotta minun liittoni Leevin kanssa pysyisi, sanoo Herra Sebaot.'),
(1692055,58,39,2,5,'Minun liittoni hänen kanssansa oli elämä ja rauha, ja minä annoin sen hänelle peloksi; ja hän pelkäsi minua, vapisi minun nimeni edessä.'),
(1692056,58,39,2,6,'Oikea opetus oli hänen suussansa, eikä vääryyttä tavattu hänen huuliltansa. Rauhassa ja vakaasti hän vaelsi minun kanssani, ja monet hän käänsi pois pahoista töistä.'),
(1692057,58,39,2,7,'Sillä papin huulten pitää tallettaman tieto, ja hänen suustansa etsitään opetus; sillä hän on Herran Sebaotin sanansaattaja.'),
(1692058,58,39,2,8,'Mutta te olette poikenneet tieltä, olette opetuksellanne saattaneet monet kompastumaan, olette turmelleet Leevin liiton, sanoo Herra Sebaot.'),
(1692059,58,39,2,9,'Niinpä minäkin teen teidät halpana pidetyiksi ja alhaisiksi kaiken kansan edessä, koska te ette ole pitäneet minun teitäni, vaan olette olleet puolueelliset opetuksessa.'),
(1692060,58,39,2,10,'Eikö meillä kaikilla ole sama Isä? Eikö sama Jumala ole meitä luonut? Miksi me olemme uskottomat toinen toisellemme ja rikomme isiemme liiton?'),
(1692061,58,39,2,11,'Juuda on ollut uskoton, Israelissa ja Jerusalemissa on tehty kauhistus. Sillä Juuda on häväissyt Herran pyhäkön, jota Herra rakastaa, ja on ottanut avioksi vieraan jumalan tyttäriä.'),
(1692062,58,39,2,12,'Hävittäköön Herra siltä mieheltä, joka tämän tekee, Jaakobin majoista valvojan ja vastaajan ja Herran Sebaotin uhrilahjan tuojan.'),
(1692063,58,39,2,13,'Ja toiseksi te olette tehneet tämän: olette saattaneet Herran alttarin peitetyksi kyynelillä ja itkulla ja huokauksilla, niin ettei hän enää käänny uhrilahjojen puoleen eikä mielisty ottamaan mitään teidän kädestänne.'),
(1692064,58,39,2,14,'Mutta te sanotte: "Minkätähden niin?" Sentähden, että Herra on todistaja sinun ja sinun nuoruutesi vaimon välillä, jolle sinä olet ollut uskoton, vaikka hän on sinun puolisosi, sinun aviovaimosi.'),
(1692065,58,39,2,15,'Niin ei tee yksikään, jolla on jäännöskään Hengestä. "Mutta kuinkas se yksi - ?" Hän pyrki saamaan Jumalan lupaamia jälkeläisiä. - Ottakaa siis vaari hengestänne älkääkä olko uskottomat nuoruutenne vaimolle.'),
(1692066,58,39,2,16,'Sillä minä vihaan hylkäämistä, sanoo Herra, Israelin Jumala, ja sitä, joka verhoaa vaatteensa vääryydellä, sanoo Herra Sebaot. Siis ottakaa vaari hengestänne älkääkä olko uskottomat.'),
(1692067,58,39,2,17,'Te väsytätte Herran puheillanne. Mutta te sanotte: "Miten väsytämme?" Siten, että sanotte: "Jokainen, joka pahaa tekee, on hyvä Herran silmissä, ja niihin hänellä on mielisuosio"; tahi: "Missä on tuomion Jumala?"'),
(1692068,58,39,3,1,'Katso, minä lähetän sanansaattajani, ja hän on valmistava tien minun eteeni. Ja äkisti on tuleva temppeliinsä Herra, jota te etsitte, ja liiton enkeli, jota te halajatte. Katso, hän tulee, sanoo Herra Sebaot.'),
(1692069,58,39,3,2,'Mutta kuka kestää hänen tulemisensa päivän, ja kuka voi pysyä, kun hän ilmestyy? Sillä hän on niinkuin kultasepän tuli ja niinkuin pesijäin saippua.'),
(1692070,58,39,3,3,'Ja hän istuu ja sulattaa ja puhdistaa hopean, hän puhdistaa Leevin pojat, saa ne puhtaiksi kuin kullan ja hopean ja sitten he tuovat Herralle uhrilahjoja vanhurskaudessa.'),
(1692071,58,39,3,4,'Ja Herralle ovat otollisia Juudan ja Jerusalemin uhrilahjat niinkuin ammoin menneinä päivinä ja muinaisina vuosina.'),
(1692072,58,39,3,5,'Ja minä lähestyn teitä pitääkseni tuomion ja tulen kiiruusti todistajaksi velhoja ja avionrikkojia ja väärinvannojia vastaan ja niitä vastaan, jotka sortavat palkkalaista palkanmaksussa, leskeä ja orpoa ja vääntävät vääräksi muukalaisen asian eivätkä pelkää minua, sanoo Herra Sebaot.'),
(1692073,58,39,3,6,'Sillä minä, Herra, en muutu, ettekä te, Jaakobin lapset, herkeä:'),
(1692074,58,39,3,7,'isienne päivistä asti te olette poikenneet minun käskyistäni ettekä noudata niitä. Kääntykää minun tyköni, niin minä käännyn teidän tykönne, sanoo Herra Sebaot. Mutta te sanotte: "Missä asiassa meidän on käännyttävä?"'),
(1692075,58,39,3,8,'Riistääkö ihminen Jumalalta? Te kuitenkin riistätte minulta. Mutta te sanotte: "Missä asiassa me sinulta riistämme?" Kymmenyksissä ja antimissa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692076,58,39,3,9,'Te olette kirouksella kirotut, kun te, koko kansa, riistätte minulta.'),
(1692077,58,39,3,10,'Tuokaa täydet kymmenykset varastohuoneeseen, että minun huoneessani olisi ravintoa, ja siten koetelkaa minua, sanoo Herra Sebaot: totisesti minä avaan teille taivaan akkunat ja vuodatan teille siunausta ylenpalttisesti.'),
(1692078,58,39,3,11,'Ja minä karkoitan nuhtelullani teiltä syöjäsirkat turmelemasta teidän maanne hedelmää, eikä teidän viiniköynnöksenne kedolla ole hedelmätön, sanoo Herra Sebaot.'),
(1692079,58,39,3,12,'Ja teidän onneanne kiittävät kaikki pakanat, sillä te tulette olemaan ihasteltu maa, sanoo Herra Sebaot.'),
(1692080,58,39,3,13,'Ynseät ovat teidän puheenne minua vastaan, sanoo Herra. Mutta te sanotte: "Mitä me olemme puhuneet sinua vastaan?"'),
(1692081,58,39,3,14,'Te sanotte: "Herran palveleminen on turha; ja mitä hyötyä siitä on ollut, että me olemme hänelle suorittaneet säädetyt tehtävät ja että olemme vaeltaneet murheellisina Herran Sebaotin kasvojen edessä.'),
(1692082,58,39,3,15,'Nyt me kiitämme julkeitten onnea. Ne, jotka tekevät sitä, mikä jumalatonta on, ne tulevat raketuiksi. He kiusaavat Jumalaa, mutta pelastuvat."'),
(1692083,58,39,3,16,'Silloin myös Herraa pelkääväiset puhuvat toinen toisensa kanssa, ja Herra tarkkaa ja kuulee; ja muistokirja kirjoitetaan hänen edessänsä niiden hyväksi, jotka Herraa pelkäävät ja hänen nimensä kunniassa pitävät.'),
(1692084,58,39,3,17,'Ja he ovat, sanoo Herra Sebaot, sinä päivänä, jonka minä teen, minun omaisuuteni. Ja minä olen heille laupias, niinkuin mies on laupias pojallensa, joka häntä palvelee.'),
(1692085,58,39,3,18,'Ja te näette jälleen, mikä on ero vanhurskaan ja jumalattoman välillä, sen välillä, joka palvelee Jumalaa, ja sen, joka ei häntä palvele.'),
(1692086,58,39,4,1,'Sillä katso: se päivä on tuleva, joka palaa kuin pätsi. Ja kaikki julkeat ja kaikki, jotka tekevät sitä, mikä jumalatonta on, ovat oljenkorsia; ja heidät polttaa se päivä, joka tuleva on, sanoo Herra Sebaot, niin ettei se jätä heistä juurta eikä oksaa.'),
(1692087,58,39,4,2,'Mutta teille, jotka minun nimeäni pelkäätte, on koittava vanhurskauden aurinko ja parantuminen sen siipien alla, ja te käytte ulos ja hypitte kuin syöttövasikat'),
(1692088,58,39,4,3,'ja tallaatte jumalattomat; sillä he tulevat tomuksi teidän jalkapohjienne alle sinä päivänä, jonka minä teen, sanoo Herra Sebaot.'),
(1692089,58,39,4,4,'Muistakaa minun palvelijani Mooseksen laki, jonka minä Hoorebilla hänelle säädin koko Israelia varten käskyiksi ja oikeuksiksi.'),
(1692090,58,39,4,5,'Katso, minä lähetän teille profeetta Elian, ennenkuin tulee Herran päivä, se suuri ja peljättävä.'),
(1692091,58,40,1,1,'Jeesuksen Kristuksen, Daavidin pojan, Aabrahamin pojan, syntykirja.'),
(1692092,58,40,1,2,'Aabrahamille syntyi Iisak, Iisakille syntyi Jaakob, Jaakobille syntyi Juuda ja tämän veljet;'),
(1692093,58,40,1,3,'Juudalle syntyi Faares ja Sera Taamarista, Faareelle syntyi Esrom, Esromille syntyi Aram;'),
(1692094,58,40,1,4,'Aramille syntyi Aminadab, Aminadabille syntyi Nahasson, Nahassonille syntyi Salmon;'),
(1692095,58,40,1,5,'Salmonille syntyi Booas Raahabista, Booaalle syntyi Oobed Ruutista, Oobedille syntyi Iisai;'),
(1692096,58,40,1,6,'Iisaille syntyi Daavid, kuningas. Daavidille syntyi Salomo Uurian vaimosta;'),
(1692097,58,40,1,7,'Salomolle syntyi Rehabeam, Rehabeamille syntyi Abia, Abialle syntyi Aasa;'),
(1692098,58,40,1,8,'Aasalle syntyi Joosafat, Joosafatille syntyi Jooram, Jooramille syntyi Ussia;'),
(1692099,58,40,1,9,'Ussialle syntyi Jootam, Jootamille syntyi Aahas, Aahaalle syntyi Hiskia;'),
(1692100,58,40,1,10,'Hiskialle syntyi Manasse, Manasselle syntyi Aamon, Aamonille syntyi Joosia;'),
(1692101,58,40,1,11,'Joosialle syntyi Jekonja ja tämän veljet Babyloniin siirtämisen aikoina.'),
(1692102,58,40,1,12,'Babyloniin siirtämisen jälkeen Jekonjalle syntyi Sealtiel, Sealtielille syntyi Serubbaabel;'),
(1692103,58,40,1,13,'Serubbaabelille syntyi Abiud, Abiudille syntyi Eljakim, Eljakimille syntyi Asor;'),
(1692104,58,40,1,14,'Asorille syntyi Saadok, Saadokille syntyi Akim, Akimille syntyi Eliud;'),
(1692105,58,40,1,15,'Eliudille syntyi Eleasar, Eleasarille syntyi Mattan, Mattanille syntyi Jaakob;'),
(1692106,58,40,1,16,'Jaakobille syntyi Joosef, Marian mies, hänen, josta syntyi Jeesus, jota kutsutaan Kristukseksi.'),
(1692107,58,40,1,17,'Näin on sukupolvia Aabrahamista Daavidiin kaikkiaan neljätoista polvea, ja Daavidista Babyloniin siirtämiseen neljätoista polvea, ja Babyloniin siirtämisestä Kristukseen asti neljätoista polvea.'),
(1692108,58,40,1,18,'Jeesuksen Kristuksen syntyminen oli näin. Kun hänen äitinsä Maria oli kihlattu Joosefille, huomattiin hänen ennen heidän yhteenmenoaan olevan raskaana Pyhästä Hengestä.'),
(1692109,58,40,1,19,'Mutta kun Joosef, hänen miehensä, oli hurskas, ja koska hän ei tahtonut saattaa häntä häpeään, aikoi hän salaisesti hyljätä hänet.'),
(1692110,58,40,1,20,'Mutta kun hän tätä ajatteli, niin katso, hänelle ilmestyi unessa Herran enkeli, joka sanoi: "Joosef, Daavidin poika, älä pelkää ottaa tykösi Mariaa, vaimoasi; sillä se, mikä hänessä on siinnyt, on Pyhästä Hengestä.'),
(1692111,58,40,1,21,'Ja hän on synnyttävä pojan, ja sinun on annettava hänelle nimi Jeesus, sillä hän on vapahtava kansansa heidän synneistänsä."'),
(1692112,58,40,1,22,'Tämä kaikki on tapahtunut, että kävisi toteen, minkä Herra on puhunut profeetan kautta, joka sanoo:'),
(1692113,58,40,1,23,'"Katso, neitsyt tulee raskaaksi ja synnyttää pojan, ja tälle on annettava nimi Immanuel", mikä käännettynä on: Jumala meidän kanssamme.'),
(1692114,58,40,1,24,'Herättyään unesta Joosef teki, niinkuin Herran enkeli oli käskenyt hänen tehdä, ja otti vaimonsa tykönsä'),
(1692115,58,40,1,25,'eikä yhtynyt häneen, ennenkuin hän oli synnyttänyt pojan. Ja hän antoi hänelle nimen Jeesus.'),
(1692116,58,40,2,1,'Kun Jeesus oli syntynyt Juudean Beetlehemissä kuningas Herodeksen aikana, niin katso, tietäjiä tuli itäisiltä mailta Jerusalemiin,'),
(1692117,58,40,2,2,'ja he sanoivat: "Missä on se äsken syntynyt juutalaisten kuningas? Sillä me näimme hänen tähtensä itäisillä mailla ja olemme tulleet häntä kumartamaan."'),
(1692118,58,40,2,3,'Kun kuningas Herodes sen kuuli, hämmästyi hän ja koko Jerusalem hänen kanssaan.'),
(1692119,58,40,2,4,'Ja hän kokosi kaikki kansan ylipapit ja kirjanoppineet ja kyseli heiltä, missä Kristus oli syntyvä.'),
(1692120,58,40,2,5,'He sanoivat hänelle: "Juudean Beetlehemissä; sillä näin on kirjoitettu profeetan kautta:'),
(1692121,58,40,2,6,'''Ja sinä Beetlehem, sinä Juudan seutu, et suinkaan ole vähäisin Juudan ruhtinasten joukossa, sillä sinusta on lähtevä hallitsija, joka kaitsee minun kansaani Israelia''."'),
(1692122,58,40,2,7,'Silloin Herodes kutsui salaa tietäjät tykönsä ja tutkiskeli heiltä tarkoin, mihin aikaan tähti oli ilmestynyt.'),
(1692123,58,40,2,8,'Ja hän lähetti heidät Beetlehemiin sanoen: "Menkää ja tiedustelkaa tarkasti lasta; ja kun sen löydätte, niin ilmoittakaa minulle, että minäkin tulisin häntä kumartamaan".'),
(1692124,58,40,2,9,'Kuultuaan kuninkaan sanat he lähtivät matkalle; ja katso, tähti, jonka he olivat itäisillä mailla nähneet, kulki heidän edellään, kunnes se tuli sen paikan päälle, jossa lapsi oli, ja pysähtyi siihen.'),
(1692125,58,40,2,10,'Nähdessään tähden he ihastuivat ylen suuresti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692126,58,40,2,11,'Niin he menivät huoneeseen ja näkivät lapsen ynnä Marian, hänen äitinsä. Ja he lankesivat maahan ja kumarsivat häntä, avasivat aarteensa ja antoivat hänelle lahjoja: kultaa ja suitsuketta ja mirhaa.'),
(1692127,58,40,2,12,'Ja Jumala kielsi heitä unessa Herodeksen tykö palaamasta, ja he menivät toista tietä takaisin omaan maahansa.'),
(1692128,58,40,2,13,'Mutta kun he olivat menneet, niin katso, Herran enkeli ilmestyi Joosefille unessa ja sanoi: "Nouse, ota lapsi ja hänen äitinsä ja pakene Egyptiin, ja ole siellä siihen asti, kuin minä sinulle sanon; sillä Herodes on etsivä lasta surmatakseen hänet".'),
(1692129,58,40,2,14,'Niin hän nousi, otti yöllä lapsen ja hänen äitinsä ja lähti Egyptiin.'),
(1692130,58,40,2,15,'Ja hän oli siellä Herodeksen kuolemaan asti; että kävisi toteen, minkä Herra on puhunut profeetan kautta, joka sanoo: "Egyptistä minä kutsuin poikani".'),
(1692131,58,40,2,16,'Silloin Herodes, nähtyään, että tietäjät olivat hänet pettäneet, vihastui kovin ja lähetti tappamaan kaikki poikalapset Beetlehemistä ja koko sen ympäristöstä, kaksivuotiaat ja nuoremmat, sen mukaan kuin hän oli aikaa tietäjiltä tarkoin tiedustellut.'),
(1692132,58,40,2,17,'Silloin kävi toteen, mikä on puhuttu profeetta Jeremiaan kautta, joka sanoo:'),
(1692133,58,40,2,18,'"Ääni kuuluu Raamasta, itku ja iso parku; Raakel itkee lapsiansa eikä lohdutuksesta huoli, kun heitä ei enää ole".'),
(1692134,58,40,2,19,'Mutta kun Herodes oli kuollut, niin katso, Herran enkeli ilmestyi unessa Joosefille Egyptissä'),
(1692135,58,40,2,20,'ja sanoi: "Nouse, ota lapsi ja hänen äitinsä ja mene Israelin maahan, sillä ne ovat kuolleet, jotka väijyivät lapsen henkeä".'),
(1692136,58,40,2,21,'Niin hän nousi, otti lapsen ja hänen äitinsä ja meni Israelin maahan.'),
(1692137,58,40,2,22,'Mutta kun hän kuuli, että Arkelaus hallitsi Juudeaa isänsä Herodeksen jälkeen, niin hän pelkäsi mennä sinne. Ja hän sai unessa Jumalalta käskyn ja lähti Galilean alueelle.'),
(1692138,58,40,2,23,'Ja sinne tultuaan hän asettui asumaan kaupunkiin, jonka nimi on Nasaret; että kävisi toteen, mikä profeettain kautta on puhuttu: "Hän on kutsuttava Nasaretilaiseksi".'),
(1692139,58,40,3,1,'Niinä päivinä tuli Johannes Kastaja ja saarnasi Juudean erämaassa'),
(1692140,58,40,3,2,'ja sanoi: "Tehkää parannus, sillä taivasten valtakunta on tullut lähelle".'),
(1692141,58,40,3,3,'Sillä hän on se, josta profeetta Esaias puhuu sanoen: "Huutavan ääni kuuluu erämaassa: ''Valmistakaa Herralle tie, tehkää polut hänelle tasaisiksi''."'),
(1692142,58,40,3,4,'Ja Johanneksella oli puku kamelinkarvoista ja vyötäisillään nahkavyö; ja hänen ruokanaan oli heinäsirkat ja metsähunaja.'),
(1692143,58,40,3,5,'Silloin vaelsi hänen tykönsä Jerusalem ja koko Juudea ja kaikki Jordanin ympäristö,'),
(1692144,58,40,3,6,'ja hän kastoi heidät Jordanin virrassa, kun he tunnustivat syntinsä.'),
(1692145,58,40,3,7,'Mutta nähdessään paljon fariseuksia ja saddukeuksia tulevan kasteelle hän sanoi heille: "Te kyykäärmeitten sikiöt, kuka on neuvonut teitä pakenemaan tulevaista vihaa?'),
(1692146,58,40,3,8,'Tehkää sentähden parannuksen soveliaita hedelmiä,'),
(1692147,58,40,3,9,'älkääkä luulko saattavanne sanoa mielessänne: ''Onhan meillä isänä Aabraham''; sillä minä sanon teille, että Jumala voi näistä kivistä herättää lapsia Aabrahamille.'),
(1692148,58,40,3,10,'Jo on kirves pantu puitten juurelle; jokainen puu, joka ei tee hyvää hedelmää, siis hakataan pois ja heitetään tuleen.'),
(1692149,58,40,3,11,'Minä kastan teidät vedellä parannukseen, mutta se, joka minun jäljessäni tulee, on minua väkevämpi, jonka kenkiäkään minä en ole kelvollinen kantamaan; hän kastaa teidät Pyhällä Hengellä ja tulella.'),
(1692150,58,40,3,12,'Hänellä on viskimensä kädessään, ja hän puhdistaa puimatanterensa ja kokoaa nisunsa aittaan, mutta ruumenet hän polttaa sammumattomassa tulessa."'),
(1692151,58,40,3,13,'Silloin Jeesus tuli Galileasta Jordanille Johanneksen tykö hänen kastettavakseen.'),
(1692152,58,40,3,14,'Mutta tämä esteli häntä sanoen: "Minun tarvitsee saada sinulta kaste, ja sinä tulet minun tyköni!"'),
(1692153,58,40,3,15,'Jeesus vastasi ja sanoi hänelle: "Salli nyt; sillä näin meidän sopii täyttää kaikki vanhurskaus". Silloin hän salli sen hänelle.'),
(1692154,58,40,3,16,'Kun Jeesus oli kastettu, nousi hän kohta vedestä, ja katso, taivaat aukenivat, ja hän näki Jumalan Hengen tulevan alas niinkuin kyyhkysen ja laskeutuvan hänen päällensä.'),
(1692155,58,40,3,17,'Ja katso, taivaista kuului ääni, joka sanoi: "Tämä on minun rakas Poikani, johon minä olen mielistynyt".'),
(1692156,58,40,4,1,'Sitten Henki vei Jeesuksen ylös erämaahan perkeleen kiusattavaksi.'),
(1692157,58,40,4,2,'Ja kun Jeesus oli paastonnut neljäkymmentä päivää ja neljäkymmentä yötä, tuli hänen lopulta nälkä.'),
(1692158,58,40,4,3,'Silloin kiusaaja tuli hänen luoksensa ja sanoi hänelle: "Jos sinä olet Jumalan Poika, niin käske näiden kivien muuttua leiviksi".'),
(1692159,58,40,4,4,'Mutta hän vastasi ja sanoi: "Kirjoitettu on: ''Ei ihminen elä ainoastaan leivästä, vaan jokaisesta sanasta, joka Jumalan suusta lähtee''."'),
(1692160,58,40,4,5,'Silloin perkele otti hänet kanssansa pyhään kaupunkiin ja asetti hänet pyhäkön harjalle'),
(1692161,58,40,4,6,'ja sanoi hänelle: "Jos sinä olet Jumalan Poika, niin heittäydy tästä alas; sillä kirjoitettu on: ''Hän antaa enkeleilleen käskyn sinusta'', ja: ''He kantavat sinua käsillänsä, ettet jalkaasi kiveen loukkaisi''."'),
(1692162,58,40,4,7,'Jeesus sanoi hänelle: "Taas on kirjoitettu: ''Älä kiusaa Herraa, sinun Jumalaasi''."'),
(1692163,58,40,4,8,'Taas perkele otti hänet kanssansa sangen korkealle vuorelle ja näytti hänelle kaikki maailman valtakunnat ja niiden loiston'),
(1692164,58,40,4,9,'ja sanoi hänelle: "Tämän kaiken minä annan sinulle, jos lankeat maahan ja kumarrat minua".'),
(1692165,58,40,4,10,'Silloin Jeesus sanoi hänelle: "Mene pois, saatana; sillä kirjoitettu on: ''Herraa, sinun Jumalaasi, pitää sinun kumartaman ja häntä ainoata palveleman''."'),
(1692166,58,40,4,11,'Silloin perkele jätti hänet; ja katso, enkeleitä tuli hänen tykönsä, ja he tekivät hänelle palvelusta.'),
(1692167,58,40,4,12,'Mutta kun Jeesus kuuli, että Johannes oli pantu vankeuteen, poistui hän Galileaan.'),
(1692168,58,40,4,13,'Ja hän jätti Nasaretin ja meni asumaan Kapernaumiin, joka on meren rannalla, Sebulonin ja Naftalin alueella;'),
(1692169,58,40,4,14,'että kävisi toteen, mikä on puhuttu profeetta Esaiaan kautta, joka sanoo:'),
(1692170,58,40,4,15,'"Sebulonin maa ja Naftalin maa, meren tie, Jordanin tuonpuoleinen maa, pakanain Galilea -'),
(1692171,58,40,4,16,'kansa, joka pimeydessä istui, näki suuren valkeuden, ja jotka istuivat kuoleman maassa ja varjossa, niille koitti valkeus".'),
(1692172,58,40,4,17,'Siitä lähtien Jeesus rupesi saarnaamaan ja sanomaan: "Tehkää parannus, sillä taivasten valtakunta on tullut lähelle".'),
(1692173,58,40,4,18,'Ja kulkiessaan Galilean järven rantaa hän näki kaksi veljestä, Simonin, jota kutsutaan Pietariksi, ja Andreaan, hänen veljensä, heittämässä verkkoa järveen; sillä he olivat kalastajia.'),
(1692174,58,40,4,19,'Ja hän sanoi heille: "Seuratkaa minua, niin minä teen teistä ihmisten kalastajia".'),
(1692175,58,40,4,20,'Niin he jättivät kohta verkot ja seurasivat häntä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692176,58,40,4,21,'Ja käydessään siitä eteenpäin hän näki toiset kaksi veljestä, Jaakobin, Sebedeuksen pojan, ja Johanneksen, hänen veljensä, venheessä isänsä Sebedeuksen kanssa laittamassa verkkojaan kuntoon; ja hän kutsui heidät.'),
(1692177,58,40,4,22,'Niin he jättivät kohta venheen ja isänsä ja seurasivat häntä.'),
(1692178,58,40,4,23,'Ja hän kierteli kautta koko Galilean ja opetti heidän synagoogissaan ja saarnasi valtakunnan evankeliumia ja paransi kaikkinaisia tauteja ja kaikkinaista raihnautta, mitä kansassa oli.'),
(1692179,58,40,4,24,'Ja maine hänestä levisi koko Syyriaan, ja hänen luoksensa tuotiin kaikki sairastavaiset, monenlaisten tautien ja vaivojen rasittamat, riivatut, kuunvaihetautiset ja halvatut; ja hän paransi heidät.'),
(1692180,58,40,4,25,'Ja häntä seurasi suuri kansan paljous Galileasta ja Dekapolista ja Jerusalemista ja Juudeasta ja Jordanin tuolta puolen.'),
(1692181,58,40,5,1,'Kun hän näki kansanjoukot, nousi hän vuorelle; ja kun hän oli istuutunut, tulivat hänen opetuslapsensa hänen tykönsä.'),
(1692182,58,40,5,2,'Niin hän avasi suunsa ja opetti heitä ja sanoi:'),
(1692183,58,40,5,3,'"Autuaita ovat hengellisesti köyhät, sillä heidän on taivasten valtakunta.'),
(1692184,58,40,5,4,'Autuaita ovat murheelliset, sillä he saavat lohdutuksen.'),
(1692185,58,40,5,5,'Autuaita ovat hiljaiset, sillä he saavat maan periä.'),
(1692186,58,40,5,6,'Autuaita ovat ne, jotka isoavat ja janoavat vanhurskautta, sillä heidät ravitaan.'),
(1692187,58,40,5,7,'Autuaita ovat laupiaat, sillä he saavat laupeuden.'),
(1692188,58,40,5,8,'Autuaita ovat puhdassydämiset, sillä he saavat nähdä Jumalan.'),
(1692189,58,40,5,9,'Autuaita ovat rauhantekijät, sillä heidät pitää Jumalan lapsiksi kutsuttaman.'),
(1692190,58,40,5,10,'Autuaita ovat ne, joita vanhurskauden tähden vainotaan, sillä heidän on taivasten valtakunta.'),
(1692191,58,40,5,11,'Autuaita olette te, kun ihmiset minun tähteni teitä solvaavat ja vainoavat ja valhetellen puhuvat teistä kaikkinaista pahaa.'),
(1692192,58,40,5,12,'Iloitkaa ja riemuitkaa, sillä teidän palkkanne on suuri taivaissa. Sillä samoin he vainosivat profeettoja, jotka olivat ennen teitä.'),
(1692193,58,40,5,13,'Te olette maan suola; mutta jos suola käy mauttomaksi, millä se saadaan suolaiseksi? Se ei enää kelpaa mihinkään muuhun kuin pois heitettäväksi ja ihmisten tallattavaksi.'),
(1692194,58,40,5,14,'Te olette maailman valkeus. Ei voi ylhäällä vuorella oleva kaupunki olla kätkössä;'),
(1692195,58,40,5,15,'eikä lamppua sytytetä ja panna vakan alle, vaan lampunjalkaan, ja niin se loistaa kaikille huoneessa oleville.'),
(1692196,58,40,5,16,'Niin loistakoon teidän valonne ihmisten edessä, että he näkisivät teidän hyvät tekonne ja ylistäisivät teidän Isäänne, joka on taivaissa.'),
(1692197,58,40,5,17,'Älkää luulko, että minä olen tullut lakia tai profeettoja kumoamaan; en minä ole tullut kumoamaan, vaan täyttämään.'),
(1692198,58,40,5,18,'Sillä totisesti minä sanon teille: kunnes taivas ja maa katoavat, ei laista katoa pieninkään kirjain, ei ainoakaan piirto, ennenkuin kaikki on tapahtunut.'),
(1692199,58,40,5,19,'Sentähden, joka purkaa yhdenkään näistä pienimmistä käskyistä ja sillä tavalla opettaa ihmisiä, se pitää pienimmäksi taivasten valtakunnassa kutsuttaman; mutta joka niitä noudattaa ja niin opettaa, se pitää kutsuttaman suureksi taivasten valtakunnassa.'),
(1692200,58,40,5,20,'Sillä minä sanon teille: ellei teidän vanhurskautenne ole paljoa suurempi kuin kirjanoppineiden ja fariseusten, niin te ette pääse taivasten valtakuntaan.'),
(1692201,58,40,5,21,'Te olette kuulleet sanotuksi vanhoille: ''Älä tapa'', ja: ''Joka tappaa, se on ansainnut oikeuden tuomion''.'),
(1692202,58,40,5,22,'Mutta minä sanon teille: jokainen, joka vihastuu veljeensä, on ansainnut oikeuden tuomion; ja joka sanoo veljelleen: ''Sinä tyhjänpäiväinen'', on ansainnut suuren neuvoston tuomion; ja joka sanoo: ''Sinä hullu'', on ansainnut helvetin tulen.'),
(1692203,58,40,5,23,'Sentähden, jos tuot lahjaasi alttarille ja siellä muistat, että veljelläsi on jotakin sinua vastaan,'),
(1692204,58,40,5,24,'niin jätä lahjasi siihen alttarin eteen, ja käy ensin sopimassa veljesi kanssa, ja tule sitten uhraamaan lahjasi.'),
(1692205,58,40,5,25,'Suostu pian sopimaan riitapuolesi kanssa, niin kauan kuin vielä olet hänen kanssaan tiellä, ettei riitapuolesi vetäisi sinua tuomarin eteen ja tuomari antaisi sinua oikeudenpalvelijalle, ja ettei sinua pantaisi vankeuteen.'),
(1692206,58,40,5,26,'Totisesti minä sanon sinulle: sieltä et pääse, ennenkuin maksat viimeisenkin rovon.'),
(1692207,58,40,5,27,'Te olette kuulleet sanotuksi: ''Älä tee huorin''.'),
(1692208,58,40,5,28,'Mutta minä sanon teille: jokainen, joka katsoo naista himoiten häntä, on jo sydämessään tehnyt huorin hänen kanssansa.'),
(1692209,58,40,5,29,'Jos sinun oikea silmäsi viettelee sinua, repäise se pois ja heitä luotasi; sillä parempi on sinulle, että yksi jäsenistäsi joutuu hukkaan, kuin että koko ruumiisi heitetään helvettiin.'),
(1692210,58,40,5,30,'Ja jos sinun oikea kätesi viettelee sinua, hakkaa se poikki ja heitä luotasi; sillä parempi on sinulle, että yksi jäsenistäsi joutuu hukkaan, kuin että koko ruumiisi menee helvettiin.'),
(1692211,58,40,5,31,'On sanottu: ''Joka hylkää vaimonsa, antakoon hänelle erokirjan''.'),
(1692212,58,40,5,32,'Mutta minä sanon teille: jokainen, joka hylkää vaimonsa muun kuin huoruuden tähden, saattaa hänet tekemään huorin, ja joka nai hyljätyn, tekee huorin.'),
(1692213,58,40,5,33,'Vielä olette kuulleet sanotuksi vanhoille: ''Älä vanno väärin'', ja: ''Täytä Herralle valasi''.'),
(1692214,58,40,5,34,'Mutta minä sanon teille: älkää ensinkään vannoko, älkää taivaan kautta, sillä se on Jumalan valtaistuin,'),
(1692215,58,40,5,35,'älkääkä maan kautta, sillä se on hänen jalkojensa astinlauta, älkää myöskään Jerusalemin kautta, sillä se on suuren Kuninkaan kaupunki;'),
(1692216,58,40,5,36,'äläkä vanno pääsi kautta, sillä et sinä voi yhtäkään hiusta tehdä valkeaksi etkä mustaksi;'),
(1692217,58,40,5,37,'vaan olkoon teidän puheenne: ''On, on'', tahi: ''ei, ei''. Mitä siihen lisätään, se on pahasta.'),
(1692218,58,40,5,38,'Te olette kuulleet sanotuksi: ''Silmä silmästä ja hammas hampaasta''.'),
(1692219,58,40,5,39,'Mutta minä sanon teille: älkää tehkö pahalle vastarintaa; vaan jos joku lyö sinua oikealle poskelle, käännä hänelle toinenkin;'),
(1692220,58,40,5,40,'ja jos joku tahtoo sinun kanssasi käydä oikeutta ja ottaa ihokkaasi, anna hänen saada vaippasikin;'),
(1692221,58,40,5,41,'ja jos joku pakottaa sinua yhden virstan matkalle, kulje hänen kanssaan kaksi.'),
(1692222,58,40,5,42,'Anna sille, joka sinulta anoo, äläkä käännä selkääsi sille, joka sinulta lainaa pyytää.'),
(1692223,58,40,5,43,'Te olette kuulleet sanotuksi: ''Rakasta lähimmäistäsi ja vihaa vihollistasi''.'),
(1692224,58,40,5,44,'Mutta minä sanon teille: rakastakaa vihollisianne ja rukoilkaa niiden puolesta, jotka teitä vainoavat,'),
(1692225,58,40,5,45,'että olisitte Isänne lapsia, joka on taivaissa; sillä hän antaa aurinkonsa koittaa niin pahoille kuin hyvillekin, ja antaa sataa niin väärille kuin vanhurskaillekin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692226,58,40,5,46,'Sillä jos te rakastatte niitä, jotka teitä rakastavat, mikä palkka teille siitä on tuleva? Eivätkö publikaanitkin tee samoin?'),
(1692227,58,40,5,47,'Ja jos te osoitatte ystävällisyyttä ainoastaan veljillenne, mitä erinomaista te siinä teette? Eivätkö pakanatkin tee samoin?'),
(1692228,58,40,5,48,'Olkaa siis te täydelliset, niinkuin teidän taivaallinen Isänne täydellinen on."'),
(1692229,58,40,6,1,'"Kavahtakaa, ettette harjoita vanhurskauttanne ihmisten nähden, että he teitä katselisivat; muutoin ette saa palkkaa Isältänne, joka on taivaissa.'),
(1692230,58,40,6,2,'Sentähden, kun annat almuja, älä soitata torvea edelläsi, niinkuin ulkokullatut tekevät synagoogissa ja kaduilla saadakseen ylistystä ihmisiltä. Totisesti minä sanon teille: he ovat saaneet palkkansa.'),
(1692231,58,40,6,3,'Vaan kun sinä almua annat, älköön vasen kätesi tietäkö, mitä oikea kätesi tekee,'),
(1692232,58,40,6,4,'että almusi olisi salassa; ja sinun Isäsi, joka salassa näkee, maksaa sinulle.'),
(1692233,58,40,6,5,'Ja kun rukoilette, älkää olko niinkuin ulkokullatut; sillä he mielellään seisovat ja rukoilevat synagoogissa ja katujen kulmissa, että ihmiset heidät näkisivät. Totisesti minä sanon teille: he ovat saaneet palkkansa.'),
(1692234,58,40,6,6,'Vaan sinä, kun rukoilet, mene kammioosi ja sulje ovesi ja rukoile Isääsi, joka on salassa; ja sinun Isäsi, joka salassa näkee, maksaa sinulle.'),
(1692235,58,40,6,7,'Ja kun rukoilette, niin älkää tyhjiä hokeko niinkuin pakanat, jotka luulevat, että heitä heidän monisanaisuutensa tähden kuullaan.'),
(1692236,58,40,6,8,'Älkää siis olko heidän kaltaisiaan; sillä teidän Isänne kyllä tietää, mitä te tarvitsette, ennenkuin häneltä anottekaan.'),
(1692237,58,40,6,9,'Rukoilkaa siis te näin: Isä meidän, joka olet taivaissa! Pyhitetty olkoon sinun nimesi;'),
(1692238,58,40,6,10,'tulkoon sinun valtakuntasi; tapahtukoon sinun tahtosi myös maan päällä niinkuin taivaassa;'),
(1692239,58,40,6,11,'anna meille tänä päivänä meidän jokapäiväinen leipämme;'),
(1692240,58,40,6,12,'ja anna meille meidän velkamme anteeksi, niinkuin mekin annamme anteeksi meidän velallisillemme;'),
(1692241,58,40,6,13,'äläkä saata meitä kiusaukseen; vaan päästä meidät pahasta, <sillä sinun on valtakunta ja voima ja kunnia iankaikkisesti. Amen.>'),
(1692242,58,40,6,14,'Sillä jos te annatte anteeksi ihmisille heidän rikkomuksensa, niin teidän taivaallinen Isänne myös antaa teille anteeksi;'),
(1692243,58,40,6,15,'mutta jos te ette anna ihmisille anteeksi, niin ei myöskään teidän Isänne anna anteeksi teidän rikkomuksianne.'),
(1692244,58,40,6,16,'Ja kun paastoatte, älkää olko synkännäköisiä niinkuin ulkokullatut; sillä he tekevät kasvonsa surkeiksi, että ihmiset näkisivät heidän paastoavan. Totisesti minä sanon teille: he ovat saaneet palkkansa.'),
(1692245,58,40,6,17,'Vaan kun sinä paastoat, niin voitele pääsi ja pese kasvosi,'),
(1692246,58,40,6,18,'etteivät paastoamistasi näkisi ihmiset, vaan sinun Isäsi, joka on salassa; ja sinun Isäsi, joka salassa näkee, maksaa sinulle.'),
(1692247,58,40,6,19,'Älkää kootko itsellenne aarteita maan päälle, missä koi ja ruoste raiskaa ja missä varkaat murtautuvat sisään ja varastavat.'),
(1692248,58,40,6,20,'Vaan kootkaa itsellenne aarteita taivaaseen, missä ei koi eikä ruoste raiskaa ja missä eivät varkaat murtaudu sisään eivätkä varasta.'),
(1692249,58,40,6,21,'Sillä missä sinun aarteesi on, siellä on myös sinun sydämesi.'),
(1692250,58,40,6,22,'Silmä on ruumiin lamppu. Jos siis silmäsi on terve, niin koko sinun ruumiisi on valaistu.'),
(1692251,58,40,6,23,'Mutta jos silmäsi on viallinen, niin koko ruumiisi on pimeä. Jos siis se valo, joka sinussa on, on pimeyttä, kuinka suuri onkaan pimeys!'),
(1692252,58,40,6,24,'Ei kukaan voi palvella kahta herraa; sillä hän on joko tätä vihaava ja toista rakastava, taikka tähän liittyvä ja toista halveksiva. Ette voi palvella Jumalaa ja mammonaa.'),
(1692253,58,40,6,25,'Sentähden minä sanon teille: älkää murehtiko hengestänne, mitä söisitte tai mitä joisitte, älkääkä ruumiistanne, mitä päällenne pukisitte. Eikö henki ole enemmän kuin ruoka ja ruumis enemmän kuin vaatteet?'),
(1692254,58,40,6,26,'Katsokaa taivaan lintuja: eivät ne kylvä eivätkä leikkaa eivätkä kokoa aittoihin, ja teidän taivaallinen Isänne ruokkii ne. Ettekö te ole paljoa suurempiarvoiset kuin ne?'),
(1692255,58,40,6,27,'Ja kuka teistä voi murehtimisellaan lisätä ikäänsä kyynäränkään vertaa?'),
(1692256,58,40,6,28,'Ja mitä te murehditte vaatteista? Katselkaa kedon kukkia, kuinka ne kasvavat; eivät ne työtä tee eivätkä kehrää.'),
(1692257,58,40,6,29,'Kuitenkin minä sanon teille: ei Salomo kaikessa loistossansa ollut niin vaatetettu kuin yksi niistä.'),
(1692258,58,40,6,30,'Jos siis Jumala näin vaatettaa kedon ruohon, joka tänään kasvaa ja huomenna uuniin heitetään, eikö paljoa ennemmin teitä, te vähäuskoiset?'),
(1692259,58,40,6,31,'Älkää siis murehtiko sanoen: ''Mitä me syömme?'' tahi: ''Mitä me juomme?'' tahi: ''Millä me itsemme vaatetamme?'''),
(1692260,58,40,6,32,'Sillä tätä kaikkea pakanat tavoittelevat. Teidän taivaallinen Isänne kyllä tietää teidän kaikkea tätä tarvitsevan.'),
(1692261,58,40,6,33,'Vaan etsikää ensin Jumalan valtakuntaa ja hänen vanhurskauttansa, niin myös kaikki tämä teille annetaan.'),
(1692262,58,40,6,34,'Älkää siis murehtiko huomisesta päivästä, sillä huominen päivä pitää murheen itsestään. Riittää kullekin päivälle oma vaivansa."'),
(1692263,58,40,7,1,'"Älkää tuomitko, ettei teitä tuomittaisi;'),
(1692264,58,40,7,2,'sillä millä tuomiolla te tuomitsette, sillä teidät tuomitaan; ja millä mitalla te mittaatte, sillä teille mitataan.'),
(1692265,58,40,7,3,'Kuinka näet rikan, joka on veljesi silmässä, mutta et huomaa malkaa omassa silmässäsi?'),
(1692266,58,40,7,4,'Taikka kuinka saatat sanoa veljellesi: ''Annas, minä otan rikan silmästäsi'', ja katso, malka on omassa silmässäsi?'),
(1692267,58,40,7,5,'Sinä ulkokullattu, ota ensin malka omasta silmästäsi, ja sitten sinä näet ottaa rikan veljesi silmästä.'),
(1692268,58,40,7,6,'Älkää antako pyhää koirille, älkääkä heittäkö helmiänne sikojen eteen, etteivät ne tallaisi niitä jalkoihinsa ja kääntyisi ja repisi teitä.'),
(1692269,58,40,7,7,'Anokaa, niin teille annetaan; etsikää, niin te löydätte; kolkuttakaa, niin teille avataan.'),
(1692270,58,40,7,8,'Sillä jokainen anova saa, ja etsivä löytää, ja kolkuttavalle avataan.'),
(1692271,58,40,7,9,'Vai kuka teistä on se ihminen, joka antaa pojallensa kiven, kun tämä pyytää häneltä leipää,'),
(1692272,58,40,7,10,'taikka, kun hän pyytää kalaa, antaa hänelle käärmeen?'),
(1692273,58,40,7,11,'Jos siis te, jotka olette pahoja, osaatte antaa lapsillenne hyviä lahjoja, kuinka paljoa ennemmin teidän Isänne, joka on taivaissa, antaa sitä, mikä hyvää on, niille, jotka sitä häneltä anovat!'),
(1692274,58,40,7,12,'Sentähden, kaikki, mitä te tahdotte ihmisten teille tekevän, tehkää myös te samoin heille; sillä tämä on laki ja profeetat.'),
(1692275,58,40,7,13,'Menkää ahtaasta portista sisälle. Sillä se portti on avara ja tie lavea, joka vie kadotukseen, ja monta on, jotka siitä sisälle menevät;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692276,58,40,7,14,'mutta se portti on ahdas ja tie kaita, joka vie elämään, ja harvat ovat ne, jotka sen löytävät.'),
(1692277,58,40,7,15,'Kavahtakaa vääriä profeettoja, jotka tulevat teidän luoksenne lammastenvaatteissa, mutta sisältä ovat raatelevaisia susia.'),
(1692278,58,40,7,16,'Heidän hedelmistään te tunnette heidät. Eihän orjantappuroista koota viinirypäleitä eikä ohdakkeista viikunoita?'),
(1692279,58,40,7,17,'Näin jokainen hyvä puu tekee hyviä hedelmiä, mutta huono puu tekee pahoja hedelmiä.'),
(1692280,58,40,7,18,'Ei saata hyvä puu kasvaa pahoja hedelmiä eikä huono puu kasvaa hyviä hedelmiä.'),
(1692281,58,40,7,19,'Jokainen puu, joka ei tee hyvää hedelmää, hakataan pois ja heitetään tuleen.'),
(1692282,58,40,7,20,'Niin te siis tunnette heidät heidän hedelmistään.'),
(1692283,58,40,7,21,'Ei jokainen, joka sanoo minulle: ''Herra, Herra!'', pääse taivasten valtakuntaan, vaan se, joka tekee minun taivaallisen Isäni tahdon.'),
(1692284,58,40,7,22,'Moni sanoo minulle sinä päivänä: ''Herra, Herra, emmekö me sinun nimesi kautta ennustaneet ja sinun nimesi kautta ajaneet ulos riivaajia ja sinun nimesi kautta tehneet monta voimallista tekoa?'''),
(1692285,58,40,7,23,'Ja silloin minä lausun heille julki: ''Minä en ole koskaan teitä tuntenut; menkää pois minun tyköäni, te laittomuuden tekijät''.'),
(1692286,58,40,7,24,'Sentähden on jokainen, joka kuulee nämä minun sanani ja tekee niiden mukaan, verrattava ymmärtäväiseen mieheen, joka huoneensa kalliolle rakensi.'),
(1692287,58,40,7,25,'Ja rankkasade lankesi, ja virrat tulvivat, ja tuulet puhalsivat ja syöksyivät sitä huonetta vastaan, mutta se ei sortunut, sillä se oli kalliolle perustettu.'),
(1692288,58,40,7,26,'Ja jokainen, joka kuulee nämä minun sanani eikä tee niiden mukaan, on verrattava tyhmään mieheen, joka huoneensa hiekalle rakensi.'),
(1692289,58,40,7,27,'Ja rankkasade lankesi, ja virrat tulvivat, ja tuulet puhalsivat ja syöksähtivät sitä huonetta vastaan, ja se sortui, ja sen sortuminen oli suuri."'),
(1692290,58,40,7,28,'Ja kun Jeesus lopetti nämä puheet, olivat kansanjoukot hämmästyksissään hänen opetuksestansa,'),
(1692291,58,40,7,29,'sillä hän opetti heitä niinkuin se, jolla valta on, eikä niinkuin heidän kirjanoppineensa.'),
(1692292,58,40,8,1,'Kun hän astui alas vuorelta, seurasi häntä suuri kansan paljous.'),
(1692293,58,40,8,2,'Ja katso, tuli pitalinen mies ja kumartui maahan hänen eteensä ja sanoi: "Herra, jos tahdot, niin sinä voit minut puhdistaa".'),
(1692294,58,40,8,3,'Niin hän ojensi kätensä, kosketti häntä ja sanoi: "Minä tahdon; puhdistu". Ja kohta hän puhdistui pitalistaan.'),
(1692295,58,40,8,4,'Ja Jeesus sanoi hänelle: "Katso, ettet puhu tästä kenellekään; vaan mene ja näytä itsesi papille, ja uhraa lahja, jonka Mooses on säätänyt, todistukseksi heille".'),
(1692296,58,40,8,5,'Ja kun hän saapui Kapernaumiin, tuli hänen tykönsä sadanpäämies ja rukoili häntä'),
(1692297,58,40,8,6,'ja sanoi: "Herra, minun palvelijani makaa kotona halvattuna ja on kovissa vaivoissa".'),
(1692298,58,40,8,7,'Hän sanoi hänelle: "Minä tulen ja parannan hänet".'),
(1692299,58,40,8,8,'Mutta sadanpäämies vastasi ja sanoi: "Herra, en minä ole sen arvoinen, että tulisit minun kattoni alle; vaan sano ainoastaan sana, niin minun palvelijani paranee.'),
(1692300,58,40,8,9,'Sillä minä itsekin olen toisen vallan alainen, ja minulla on sotamiehiä käskyni alaisina, ja minä sanon tälle: ''Mene'', ja hän menee, ja toiselle: ''Tule'', ja hän tulee, ja palvelijalleni: ''Tee tämä'', ja hän tekee."'),
(1692301,58,40,8,10,'Tämän kuultuaan Jeesus ihmetteli ja sanoi niille, jotka häntä seurasivat: "Totisesti minä sanon teille: en ole kenelläkään Israelissa löytänyt näin suurta uskoa.'),
(1692302,58,40,8,11,'Ja minä sanon teille: monet tulevat idästä ja lännestä ja aterioitsevat Aabrahamin ja Iisakin ja Jaakobin kanssa taivasten valtakunnassa;'),
(1692303,58,40,8,12,'mutta valtakunnan lapset heitetään ulos pimeyteen; siellä on oleva itku ja hammasten kiristys."'),
(1692304,58,40,8,13,'Ja Jeesus sanoi sadanpäämiehelle: "Mene. Niinkuin sinä uskot, niin sinulle tapahtukoon." Ja palvelija parani sillä hetkellä.'),
(1692305,58,40,8,14,'Kun Jeesus tuli Pietarin kotiin, näki hän hänen anoppinsa makaavan sairaana kuumeessa.'),
(1692306,58,40,8,15,'Niin hän koski tämän käteen, ja kuume lähti hänestä; ja hän nousi ja palveli häntä.'),
(1692307,58,40,8,16,'Mutta illan tultua tuotiin hänen tykönsä monta riivattua. Ja hän ajoi henget ulos sanalla, ja kaikki sairaat hän paransi;'),
(1692308,58,40,8,17,'että kävisi toteen, mikä on puhuttu profeetta Esaiaan kautta, joka sanoo: "Hän otti päällensä meidän sairautemme ja kantoi meidän tautimme".'),
(1692309,58,40,8,18,'Mutta kun Jeesus näki paljon kansaa ympärillään, käski hän lähteä toiselle rannalle.'),
(1692310,58,40,8,19,'Ja eräs kirjanoppinut tuli ja sanoi hänelle: "Opettaja, minä seuraan sinua, mihin ikinä menet".'),
(1692311,58,40,8,20,'Niin Jeesus sanoi hänelle: "Ketuilla on luolat ja taivaan linnuilla pesät, mutta Ihmisen Pojalla ei ole, mihin hän päänsä kallistaisi".'),
(1692312,58,40,8,21,'Ja eräs toinen hänen opetuslapsistaan sanoi hänelle: "Herra, salli minun ensin käydä hautaamassa isäni".'),
(1692313,58,40,8,22,'Mutta Jeesus sanoi hänelle: "Seuraa sinä minua, ja anna kuolleitten haudata kuolleensa".'),
(1692314,58,40,8,23,'Ja hän astui venheeseen, ja hänen opetuslapsensa seurasivat häntä.'),
(1692315,58,40,8,24,'Ja katso, järvellä nousi kova myrsky, niin että venhe peittyi aaltoihin; mutta hän nukkui.'),
(1692316,58,40,8,25,'Niin he menivät ja herättivät hänet sanoen: "Herra, auta, me hukumme".'),
(1692317,58,40,8,26,'Hän sanoi heille: "Te vähäuskoiset, miksi olette pelkureita?" Silloin hän nousi ja nuhteli tuulia ja järveä, ja tuli aivan tyven.'),
(1692318,58,40,8,27,'Ja ihmiset ihmettelivät ja sanoivat: "Millainen tämä on, kun sekä tuulet että meri häntä tottelevat?"'),
(1692319,58,40,8,28,'Kun hän tuli toiselle rannalle, gadaralaisten alueelle, tuli häntä vastaan kaksi riivattua, jotka olivat haudoista lähteneet ja olivat kovin raivoisia, niin ettei kukaan voinut sitä tietä kulkea.'),
(1692320,58,40,8,29,'Ja katso, he huusivat sanoen: "Mitä sinulla on meidän kanssamme tekemistä, sinä Jumalan Poika? Oletko tullut tänne vaivaamaan meitä ennen aikaa?"'),
(1692321,58,40,8,30,'Ja etäällä heistä kävi suuri sikalauma laitumella.'),
(1692322,58,40,8,31,'Niin riivaajahenget pyysivät häntä sanoen: "Jos ajat meidät pois, niin lähetä meidät sikalaumaan".'),
(1692323,58,40,8,32,'Ja hän sanoi niille: "Menkää". Silloin ne lähtivät heistä ja menivät sikoihin. Ja katso, koko lauma syöksyi jyrkännettä alas järveen ja hukkui veteen.'),
(1692324,58,40,8,33,'Mutta paimentajat pakenivat; ja he menivät kaupunkiin ja ilmoittivat kaikki, myöskin sen, miten riivattujen oli käynyt.'),
(1692325,58,40,8,34,'Ja katso, koko kaupunki lähti Jeesusta vastaan; ja kun he hänet näkivät, pyysivät he häntä menemään pois heidän alueeltaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692326,58,40,9,1,'Ja hän astui venheeseen, meni jälleen toiselle rannalle ja tuli omaan kaupunkiinsa.'),
(1692327,58,40,9,2,'Ja katso, hänen tykönsä tuotiin halvattu mies, joka makasi vuoteella. Kun Jeesus näki heidän uskonsa, sanoi hän halvatulle: "Poikani, ole turvallisella mielellä; sinun syntisi annetaan sinulle anteeksi".'),
(1692328,58,40,9,3,'Ja katso, muutamat kirjanoppineista sanoivat mielessään: "Tämä pilkkaa Jumalaa".'),
(1692329,58,40,9,4,'Mutta Jeesus ymmärsi heidän ajatuksensa ja sanoi: "Miksi te ajattelette pahaa sydämessänne?'),
(1692330,58,40,9,5,'Sillä kumpi on helpompaa, sanoako: ''Sinun syntisi annetaan sinulle anteeksi'', vai sanoa: ''Nouse ja käy''?'),
(1692331,58,40,9,6,'Mutta tietääksenne, että Ihmisen Pojalla on valta maan päällä antaa syntejä anteeksi, niin" - hän sanoi halvatulle - "nouse, ota vuoteesi ja mene kotiisi."'),
(1692332,58,40,9,7,'Ja hän nousi ja lähti kotiinsa.'),
(1692333,58,40,9,8,'Mutta kun kansanjoukot sen näkivät, peljästyivät he ja ylistivät Jumalaa, joka oli antanut senkaltaisen vallan ihmisille.'),
(1692334,58,40,9,9,'Ja sieltä kulkiessaan ohi Jeesus näki miehen, jonka nimi oli Matteus, istumassa tulliasemalla ja sanoi hänelle: "Seuraa minua". Niin tämä nousi ja seurasi häntä.'),
(1692335,58,40,9,10,'Ja kun hän aterioi hänen kodissaan, niin katso, tuli monta publikaania ja syntistä, ja he aterioivat Jeesuksen ja hänen opetuslastensa kanssa.'),
(1692336,58,40,9,11,'Ja kun fariseukset sen näkivät, sanoivat he hänen opetuslapsilleen: "Miksi teidän opettajanne syö publikaanien ja syntisten kanssa?"'),
(1692337,58,40,9,12,'Mutta kun Jeesus sen kuuli, sanoi hän: "Eivät terveet tarvitse parantajaa, vaan sairaat.'),
(1692338,58,40,9,13,'Mutta menkää ja oppikaa, mitä tämä on: ''Laupeutta minä tahdon enkä uhria''. Sillä en minä ole tullut kutsumaan vanhurskaita, vaan syntisiä."'),
(1692339,58,40,9,14,'Silloin Johanneksen opetuslapset tulivat hänen tykönsä ja sanoivat: "Me ja fariseukset paastoamme paljon; miksi sinun opetuslapsesi eivät paastoa?"'),
(1692340,58,40,9,15,'Niin Jeesus sanoi heille: "Eiväthän häävieraat voi surra, niinkauan kuin ylkä on heidän kanssaan? Mutta päivät tulevat, jolloin ylkä otetaan heiltä pois, ja silloin he paastoavat.'),
(1692341,58,40,9,16,'Ei kukaan pane vanuttamattomasta kankaasta paikkaa vanhaan vaippaan, sillä semmoinen täytetilkku repii palasen vaipasta, ja reikä tulee pahemmaksi.'),
(1692342,58,40,9,17,'Eikä nuorta viiniä lasketa vanhoihin nahkaleileihin; muutoin leilit pakahtuvat, ja viini juoksee maahan, ja leilit turmeltuvat; vaan nuori viini lasketaan uusiin leileihin, ja niin molemmat säilyvät."'),
(1692343,58,40,9,18,'Kun hän tätä heille puhui, niin katso, eräs päämies tuli ja kumartui maahan hänen eteensä ja sanoi: "Minun tyttäreni kuoli juuri ikään, mutta tule ja pane kätesi hänen päällensä, niin hän virkoaa eloon".'),
(1692344,58,40,9,19,'Niin Jeesus nousi ja seurasi häntä opetuslapsinensa.'),
(1692345,58,40,9,20,'Ja katso, nainen, joka oli sairastanut verenjuoksua kaksitoista vuotta, tuli takaapäin ja kosketti hänen vaippansa tupsua.'),
(1692346,58,40,9,21,'Sillä hän sanoi itsekseen: "Jos vain saan koskettaa hänen vaippaansa, niin minä tulen terveeksi".'),
(1692347,58,40,9,22,'Silloin Jeesus kääntyi, näki hänet ja sanoi: "Tyttäreni, ole turvallisella mielellä; sinun uskosi on tehnyt sinut terveeksi". Ja sillä hetkellä nainen tuli terveeksi.'),
(1692348,58,40,9,23,'Ja kun Jeesus tuli päämiehen taloon ja näki huilunsoittajat ja hälisevän väkijoukon,'),
(1692349,58,40,9,24,'sanoi hän: "Menkää pois, sillä tyttö ei ole kuollut, vaan nukkuu". Niin he nauroivat häntä.'),
(1692350,58,40,9,25,'Mutta kun väkijoukko oli ajettu ulos, meni hän sisälle ja tarttui hänen käteensä; ja tyttö nousi.'),
(1692351,58,40,9,26,'Ja sanoma tästä levisi koko siihen maahan.'),
(1692352,58,40,9,27,'Ja kun Jeesus kulki sieltä, seurasi häntä kaksi sokeaa huutaen ja sanoen: "Daavidin poika, armahda meitä".'),
(1692353,58,40,9,28,'Ja hänen mentyänsä huoneeseen sokeat tulivat hänen tykönsä; ja Jeesus sanoi heille: "Uskotteko, että minä voin sen tehdä?" He sanoivat hänelle: "Uskomme, Herra".'),
(1692354,58,40,9,29,'Silloin hän kosketti heidän silmiänsä ja sanoi: "Tapahtukoon teille uskonne mukaan".'),
(1692355,58,40,9,30,'Ja heidän silmänsä aukenivat. Ja Jeesus varoitti heitä vakavasti sanoen: "Katsokaa, ettei kukaan saa tästä tietää".'),
(1692356,58,40,9,31,'Mutta he menivät pois ja levittivät sanomaa hänestä koko siihen maahan.'),
(1692357,58,40,9,32,'Ja katso, näiden lähdettyä tuotiin hänen tykönsä mykkä mies, joka oli riivattu.'),
(1692358,58,40,9,33,'Ja kun riivaaja oli ajettu ulos, niin mykkä puhui, ja kansa ihmetteli sanoen: "Tällaista ei ole Israelissa ikinä nähty".'),
(1692359,58,40,9,34,'Mutta fariseukset sanoivat: "Riivaajain päämiehen voimalla hän ajaa ulos riivaajia".'),
(1692360,58,40,9,35,'Ja Jeesus vaelsi kaikki kaupungit ja kylät ja opetti heidän synagoogissaan ja saarnasi valtakunnan evankeliumia ja paransi kaikkinaisia tauteja ja kaikkinaista raihnautta.'),
(1692361,58,40,9,36,'Ja nähdessään kansanjoukot hänen tuli heitä sääli, kun he olivat nääntyneet ja hyljätyt niinkuin lampaat, joilla ei ole paimenta.'),
(1692362,58,40,9,37,'Silloin hän sanoi opetuslapsillensa: "Eloa on paljon, mutta työmiehiä vähän.'),
(1692363,58,40,9,38,'Rukoilkaa siis elon Herraa, että hän lähettäisi työmiehiä elonkorjuuseensa."'),
(1692364,58,40,10,1,'Ja hän kutsui tykönsä ne kaksitoista opetuslastaan ja antoi heille vallan ajaa ulos saastaisia henkiä ja parantaa kaikkinaisia tauteja ja kaikkinaista raihnautta.'),
(1692365,58,40,10,2,'Ja nämä ovat niiden kahdentoista apostolin nimet: ensimmäinen oli Simon, jota kutsuttiin Pietariksi, ja Andreas, hänen veljensä, sitten Jaakob Sebedeuksen poika, ja Johannes, hänen veljensä,'),
(1692366,58,40,10,3,'Filippus ja Bartolomeus, Tuomas ja Matteus, publikaani, Jaakob, Alfeuksen poika, ja Lebbeus, lisänimeltä Taddeus,'),
(1692367,58,40,10,4,'Simon Kananeus ja Juudas Iskariot, sama, joka hänet kavalsi.'),
(1692368,58,40,10,5,'Nämä kaksitoista Jeesus lähetti ja käski heitä sanoen: "Älköön tienne viekö pakanain luokse, älkääkä menkö mihinkään samarialaisten kaupunkiin,'),
(1692369,58,40,10,6,'vaan menkää ennemmin Israelin huoneen kadonneitten lammasten tykö.'),
(1692370,58,40,10,7,'Ja missä kuljette, saarnatkaa ja sanokaa: ''Taivasten valtakunta on tullut lähelle''.'),
(1692371,58,40,10,8,'Parantakaa sairaita, herättäkää kuolleita, puhdistakaa pitalisia, ajakaa ulos riivaajia. Lahjaksi olette saaneet, lahjaksi antakaa.'),
(1692372,58,40,10,9,'Älkää varustako itsellenne kultaa, älkää hopeata älkääkä vaskea vyöhönne,'),
(1692373,58,40,10,10,'älkää laukkua matkalle, älkää kahta ihokasta, älkää kenkiä, älkääkä sauvaa; sillä työmies on ruokansa ansainnut.'),
(1692374,58,40,10,11,'Ja mihin kaupunkiin tai kylään te tulettekin, tiedustelkaa, kuka siellä on arvollinen, ja jääkää hänen luokseen, kunnes sieltä lähdette.'),
(1692375,58,40,10,12,'Ja tullessanne taloon tervehtikää sitä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692376,58,40,10,13,'Ja jos talo on arvollinen, tulkoon sille teidän rauhanne; mutta jos se ei ole arvollinen, palatkoon teidän rauhanne teille takaisin.'),
(1692377,58,40,10,14,'Ja missä teitä ei oteta vastaan eikä teidän sanojanne kuulla, lähtekää pois siitä talosta tai siitä kaupungista ja pudistakaa tomu jaloistanne.'),
(1692378,58,40,10,15,'Totisesti minä sanon teille: Sodoman ja Gomorran maan on tuomiopäivänä oleva helpompi kuin sen kaupungin.'),
(1692379,58,40,10,16,'Katso, minä lähetän teidät niinkuin lampaat susien keskelle; olkaa siis älykkäät kuin käärmeet ja viattomat kuin kyyhkyset.'),
(1692380,58,40,10,17,'Kavahtakaa ihmisiä, sillä he vetävät teidät oikeuksiin, ja synagoogissaan he teitä ruoskivat;'),
(1692381,58,40,10,18,'ja teidät viedään maaherrain ja kuningasten eteen minun tähteni, todistukseksi heille ja pakanoille.'),
(1692382,58,40,10,19,'Mutta kun he vetävät teitä oikeuteen, älkää huolehtiko siitä, miten tahi mitä puhuisitte, sillä teille annetaan sillä hetkellä, mitä teidän on puhuminen.'),
(1692383,58,40,10,20,'Sillä ette te itse puhu, vaan teidän Isänne Henki puhuu teissä.'),
(1692384,58,40,10,21,'Ja veli antaa veljensä kuolemaan ja isä lapsensa, ja lapset nousevat vanhempiansa vastaan ja tappavat heidät.'),
(1692385,58,40,10,22,'Ja te joudutte kaikkien vihattaviksi minun nimeni tähden; mutta joka vahvana pysyy loppuun asti, se pelastuu.'),
(1692386,58,40,10,23,'Ja kun teitä vainotaan yhdessä kaupungissa, paetkaa toiseen; sillä totisesti minä sanon teille: te ette ehdi loppuun käydä Israelin kaupunkeja, ennenkuin Ihmisen Poika tulee.'),
(1692387,58,40,10,24,'Ei ole opetuslapsi opettajaansa parempi, eikä palvelija parempi isäntäänsä.'),
(1692388,58,40,10,25,'Opetuslapselle riittää, että hänelle käy niinkuin hänen opettajalleen, ja palvelijalle, että hänelle käy niinkuin hänen isännälleen. Jos he perheenisäntää ovat sanoneet Beelsebuliksi, kuinka paljoa enemmän hänen perheväkeään!'),
(1692389,58,40,10,26,'Älkää siis peljätkö heitä. Sillä ei ole mitään peitettyä, mitä ei tule paljastetuksi, eikä mitään salattua, mikä ei tule tunnetuksi.'),
(1692390,58,40,10,27,'Minkä minä sanon teille pimeässä, se puhukaa päivän valossa. Ja minkä kuulette kuiskattavan korvaanne, se julistakaa katoilta.'),
(1692391,58,40,10,28,'Älkääkä peljätkö niitä, jotka tappavat ruumiin, mutta eivät voi tappaa sielua; vaan ennemmin peljätkää häntä, joka voi sekä sielun että ruumiin hukuttaa helvettiin.'),
(1692392,58,40,10,29,'Eikö kahta varpusta myydä yhteen ropoon? Eikä yksikään niistä putoa maahan teidän Isänne sallimatta.'),
(1692393,58,40,10,30,'Ovatpa teidän päänne hiuksetkin kaikki luetut.'),
(1692394,58,40,10,31,'Älkää siis peljätkö; te olette suurempiarvoiset kuin monta varpusta.'),
(1692395,58,40,10,32,'Sentähden, jokaisen, joka tunnustaa minut ihmisten edessä, minäkin tunnustan Isäni edessä, joka on taivaissa.'),
(1692396,58,40,10,33,'Mutta joka kieltää minut ihmisten edessä, sen minäkin kiellän Isäni edessä, joka on taivaissa.'),
(1692397,58,40,10,34,'Älkää luulko, että minä olen tullut tuomaan rauhaa maan päälle; en ole tullut tuomaan rauhaa, vaan miekan.'),
(1692398,58,40,10,35,'Sillä minä olen tullut ''nostamaan pojan riitaan isäänsä vastaan ja tyttären äitiänsä vastaan ja miniän anoppiansa vastaan;'),
(1692399,58,40,10,36,'ja ihmisen vihamiehiksi tulevat hänen omat perhekuntalaisensa''.'),
(1692400,58,40,10,37,'Joka rakastaa isäänsä taikka äitiänsä enemmän kuin minua, se ei ole minulle sovelias; ja joka rakastaa poikaansa taikka tytärtänsä enemmän kuin minua, se ei ole minulle sovelias;'),
(1692401,58,40,10,38,'ja joka ei ota ristiänsä ja seuraa minua, se ei ole minulle sovelias.'),
(1692402,58,40,10,39,'Joka löytää elämänsä, kadottaa sen; ja joka kadottaa elämänsä minun tähteni, hän löytää sen.'),
(1692403,58,40,10,40,'Joka ottaa tykönsä teidät, se ottaa tykönsä minut; ja joka ottaa minut tykönsä, ottaa tykönsä hänet, joka on minut lähettänyt.'),
(1692404,58,40,10,41,'Joka profeetan ottaa tykönsä profeetan nimen tähden, saa profeetan palkan; ja joka vanhurskaan ottaa tykönsä vanhurskaan nimen tähden, saa vanhurskaan palkan.'),
(1692405,58,40,10,42,'Ja kuka hyvänsä antaa yhdelle näistä pienistä maljallisen kylmää vettä, hänen juodaksensa, opetuslapsen nimen tähden, totisesti minä sanon teille: hän ei jää palkkaansa vaille."'),
(1692406,58,40,11,1,'Ja kun Jeesus oli antanut kahdelletoista opetuslapselleen kaikki nämä käskyt, niin hän lähti sieltä opettamaan ja saarnaamaan heidän kaupunkeihinsa.'),
(1692407,58,40,11,2,'Mutta kun Johannes vankilassa ollessaan kuuli Kristuksen teot, lähetti hän opetuslapsiansa'),
(1692408,58,40,11,3,'sanomaan hänelle: "Oletko sinä se tuleva, vai pitääkö meidän toista odottaman?"'),
(1692409,58,40,11,4,'Niin Jeesus vastasi ja sanoi heille: "Menkää ja kertokaa Johannekselle, mitä kuulette ja näette:'),
(1692410,58,40,11,5,'sokeat saavat näkönsä, ja rammat kävelevät, pitaliset puhdistuvat, ja kuurot kuulevat, ja kuolleet herätetään, ja köyhille julistetaan evankeliumia.'),
(1692411,58,40,11,6,'Ja autuas on se, joka ei loukkaannu minuun."'),
(1692412,58,40,11,7,'Kun he olivat menneet, rupesi Jeesus puhumaan kansalle Johanneksesta: "Mitä te lähditte erämaahan katselemaan? Ruokoako, jota tuuli huojuttaa?'),
(1692413,58,40,11,8,'Vai mitä lähditte katsomaan? Ihmistäkö, hienoihin vaatteisiin puettua? Katso, hienopukuiset ovat kuningasten kartanoissa.'),
(1692414,58,40,11,9,'Vai mitä te lähditte? Profeettaako katsomaan? Totisesti, minä sanon teille: hän on enemmän kuin profeetta.'),
(1692415,58,40,11,10,'Tämä on se, josta on kirjoitettu: ''Katso, minä lähetän enkelini sinun edelläsi, ja hän on valmistava tiesi sinun eteesi''.'),
(1692416,58,40,11,11,'Totisesti minä sanon teille: ei ole vaimoista syntyneitten joukosta noussut suurempaa kuin Johannes Kastaja; mutta vähäisin taivasten valtakunnassa on suurempi kuin hän.'),
(1692417,58,40,11,12,'Mutta Johannes Kastajan päivistä tähän asti hyökätään taivasten valtakuntaa vastaan, ja hyökkääjät tempaavat sen itselleen.'),
(1692418,58,40,11,13,'Sillä kaikki profeetat ja laki ovat ennustaneet Johannekseen asti;'),
(1692419,58,40,11,14,'ja jos tahdotte ottaa vastaan: hän on Elias, joka oli tuleva.'),
(1692420,58,40,11,15,'Jolla on korvat, se kuulkoon.'),
(1692421,58,40,11,16,'Mutta mihin minä vertaan tämän sukupolven? Se on lasten kaltainen, jotka istuvat toreilla ja huutavat toisilleen'),
(1692422,58,40,11,17,'sanoen: ''Me soitimme teille huilua, ja te ette karkeloineet; me veisasimme itkuvirsiä, ja te ette valittaneet''.'),
(1692423,58,40,11,18,'Sillä Johannes tuli, hän ei syö eikä juo, ja he sanovat: ''Hänessä on riivaaja''.'),
(1692424,58,40,11,19,'Ihmisen Poika tuli, hän syö ja juo, ja he sanovat: ''Katso syömäriä ja viininjuojaa, publikaanien ja syntisten ystävää!'' Ja viisaus on oikeaksi näytetty teoissansa."'),
(1692425,58,40,11,20,'Sitten hän rupesi nuhtelemaan niitä kaupunkeja, joissa useimmat hänen voimalliset tekonsa olivat tapahtuneet, siitä, etteivät ne olleet tehneet parannusta:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692426,58,40,11,21,'"Voi sinua, Korasin! Voi sinua, Beetsaida! Sillä jos ne voimalliset teot, jotka ovat tapahtuneet teissä, olisivat tapahtuneet Tyyrossa ja Siidonissa, niin nämä jo aikaa sitten olisivat säkissä ja tuhassa tehneet parannuksen.'),
(1692427,58,40,11,22,'Mutta minä sanon teille: Tyyron ja Siidonin on tuomiopäivänä oleva helpompi kuin teidän.'),
(1692428,58,40,11,23,'Ja sinä, Kapernaum, korotetaankohan sinut hamaan taivaaseen? Hamaan tuonelaan on sinun astuttava alas. Sillä jos ne voimalliset teot, jotka ovat tapahtuneet sinussa, olisivat tapahtuneet Sodomassa, niin se seisoisi vielä tänäkin päivänä.'),
(1692429,58,40,11,24,'Mutta minä sanon teille: Sodoman maan on tuomiopäivänä oleva helpompi kuin sinun."'),
(1692430,58,40,11,25,'Siihen aikaan Jeesus johtui puhumaan sanoen: "Minä ylistän sinua, Isä, taivaan ja maan Herra, että olet salannut nämä viisailta ja ymmärtäväisiltä ja ilmoittanut ne lapsenmielisille.'),
(1692431,58,40,11,26,'Niin, Isä, sillä näin on sinulle hyväksi näkynyt.'),
(1692432,58,40,11,27,'Kaikki on minun Isäni antanut minun haltuuni, eikä kukaan muu tunne Poikaa kuin Isä, eikä Isää tunne kukaan muu kuin Poika ja se, kenelle Poika tahtoo hänet ilmoittaa.'),
(1692433,58,40,11,28,'Tulkaa minun tyköni, kaikki työtätekeväiset ja raskautetut, niin minä annan teille levon.'),
(1692434,58,40,11,29,'Ottakaa minun ikeeni päällenne ja oppikaa minusta, sillä minä olen hiljainen ja nöyrä sydämeltä; niin te löydätte levon sielullenne.'),
(1692435,58,40,11,30,'Sillä minun ikeeni on sovelias, ja minun kuormani on keveä."'),
(1692436,58,40,12,1,'Siihen aikaan Jeesus kulki sapattina viljavainioiden halki; ja hänen opetuslastensa oli nälkä, ja he rupesivat katkomaan tähkäpäitä ja syömään.'),
(1692437,58,40,12,2,'Mutta kun fariseukset sen näkivät, sanoivat he hänelle: "Katso, sinun opetuslapsesi tekevät, mitä ei ole lupa tehdä sapattina".'),
(1692438,58,40,12,3,'Niin hän sanoi heille: "Ettekö ole lukeneet, mitä Daavid teki, kun hänen ja hänen seuralaistensa oli nälkä,'),
(1692439,58,40,12,4,'kuinka hän meni Jumalan huoneeseen, ja kuinka he söivät näkyleivät, joita ei hänen eikä hänen seuralaistensa ollut lupa syödä, vaan ainoastaan pappien?'),
(1692440,58,40,12,5,'Tai ettekö ole lukeneet laista, että papit sapattina pyhäkössä rikkovat sapatin ja ovat kuitenkin syyttömät?'),
(1692441,58,40,12,6,'Mutta minä sanon teille: tässä on se, joka on pyhäkköä suurempi.'),
(1692442,58,40,12,7,'Mutta jos tietäisitte, mitä tämä on: ''Laupeutta minä tahdon enkä uhria'', niin te ette tuomitsisi syyttömiä.'),
(1692443,58,40,12,8,'Sillä Ihmisen Poika on sapatin herra."'),
(1692444,58,40,12,9,'Ja hän lähti sieltä ja tuli heidän synagoogaansa.'),
(1692445,58,40,12,10,'Ja katso, siellä oli mies, jonka käsi oli kuivettunut. Niin he kysyivät häneltä sanoen: "Onko luvallista sapattina parantaa?" voidaksensa nostaa syytteen häntä vastaan.'),
(1692446,58,40,12,11,'Niin hän sanoi heille: "Kuka teistä on se mies, joka ei, jos hänen ainoa lampaansa putoaa sapattina kuoppaan, tartu siihen ja nosta sitä ylös?'),
(1692447,58,40,12,12,'Kuinka paljon suurempiarvoinen onkaan ihminen kuin lammas! Sentähden on lupa tehdä sapattina hyvää."'),
(1692448,58,40,12,13,'Sitten hän sanoi miehelle: "Ojenna kätesi!" Ja hän ojensi; ja se tuli entiselleen, terveeksi niinkuin toinenkin.'),
(1692449,58,40,12,14,'Niin fariseukset lähtivät ulos ja pitivät neuvoa häntä vastaan, surmataksensa hänet.'),
(1692450,58,40,12,15,'Mutta kun Jeesus huomasi sen, väistyi hän sieltä pois. Ja monet seurasivat häntä, ja hän paransi heidät kaikki,'),
(1692451,58,40,12,16,'ja hän varoitti vakavasti heitä saattamasta häntä julki;'),
(1692452,58,40,12,17,'että kävisi toteen, mikä on puhuttu profeetta Esaiaan kautta, joka sanoo:'),
(1692453,58,40,12,18,'"Katso, minun palvelijani, jonka minä olen valinnut, minun rakkaani, johon minun sieluni on mielistynyt; minä panen Henkeni häneen, ja hän on saattava oikeuden sanomaa pakanoille.'),
(1692454,58,40,12,19,'Ei hän riitele eikä huuda, ei hänen ääntänsä kuule kukaan kaduilla.'),
(1692455,58,40,12,20,'Särjettyä ruokoa hän ei muserra, ja suitsevaista kynttilänsydäntä hän ei sammuta, kunnes hän saattaa oikeuden voittoon.'),
(1692456,58,40,12,21,'Ja hänen nimeensä pakanat panevat toivonsa."'),
(1692457,58,40,12,22,'Silloin tuotiin hänen tykönsä riivattu mies, joka oli sokea ja mykkä, ja hän paransi hänet, niin että mykkä puhui ja näki.'),
(1692458,58,40,12,23,'Ja kaikki kansa hämmästyi ja sanoi: "Eiköhän tämä ole Daavidin poika?"'),
(1692459,58,40,12,24,'Mutta kun fariseukset sen kuulivat, sanoivat he: "Tämä ei aja riivaajia ulos kenenkään muun kuin Beelsebulin, riivaajain päämiehen, voimalla".'),
(1692460,58,40,12,25,'Mutta hän tiesi heidän ajatuksensa ja sanoi heille: "Jokainen valtakunta, joka riitautuu itsensä kanssa, joutuu autioksi, eikä mikään kaupunki tai talo, joka riitautuu itsensä kanssa, pysy pystyssä.'),
(1692461,58,40,12,26,'Jos nyt saatana ajaa ulos saatanan, niin hän on riitautunut itsensä kanssa; kuinka siis hänen valtakuntansa pysyy pystyssä?'),
(1692462,58,40,12,27,'Ja jos minä Beelsebulin voimalla ajan ulos riivaajia, kenenkä voimalla sitten teidän lapsenne ajavat niitä ulos? Niinpä he tulevat olemaan teidän tuomarinne.'),
(1692463,58,40,12,28,'Mutta jos minä Jumalan Hengen voimalla ajan ulos riivaajia, niin on Jumalan valtakunta tullut teidän tykönne.'),
(1692464,58,40,12,29,'Taikka kuinka voi kukaan tunkeutua väkevän taloon ja ryöstää hänen tavaroitansa, ellei hän ensin sido sitä väkevää? Vasta sitten hän ryöstää tyhjäksi hänen talonsa.'),
(1692465,58,40,12,30,'Joka ei ole minun kanssani, se on minua vastaan; ja joka ei minun kanssani kokoa, se hajottaa.'),
(1692466,58,40,12,31,'Sentähden minä sanon teille: jokainen synti ja pilkka annetaan ihmisille anteeksi, mutta Hengen pilkkaamista ei anteeksi anneta.'),
(1692467,58,40,12,32,'Ja jos joku sanoo sanan Ihmisen Poikaa vastaan, niin hänelle annetaan anteeksi; mutta jos joku sanoo jotakin Pyhää Henkeä vastaan, niin hänelle ei anteeksi anneta, ei tässä maailmassa eikä tulevassa.'),
(1692468,58,40,12,33,'Joko tehkää puu hyväksi ja sen hedelmä hyväksi, tahi tehkää puu huonoksi ja sen hedelmä huonoksi; sillä hedelmästä puu tunnetaan.'),
(1692469,58,40,12,34,'Te kyykäärmeitten sikiöt, kuinka te saattaisitte hyvää puhua, kun itse olette pahoja? Sillä sydämen kyllyydestä suu puhuu.'),
(1692470,58,40,12,35,'Hyvä ihminen tuo hyvän runsaudesta esille hyvää, ja paha ihminen tuo pahan runsaudesta esille pahaa.'),
(1692471,58,40,12,36,'Mutta minä sanon teille: jokaisesta turhasta sanasta, minkä ihmiset puhuvat, pitää heidän tekemän tili tuomiopäivänä.'),
(1692472,58,40,12,37,'Sillä sanoistasi sinut julistetaan vanhurskaaksi, ja sanoistasi sinut tuomitaan syylliseksi."'),
(1692473,58,40,12,38,'Silloin muutamat kirjanoppineista ja fariseuksista vastasivat hänelle sanoen: "Opettaja, me tahdomme nähdä sinulta merkin".'),
(1692474,58,40,12,39,'Mutta hän vastasi heille ja sanoi: "Tämä paha ja avionrikkoja sukupolvi tavoittelee merkkiä, mutta sille ei anneta muuta merkkiä kuin profeetta Joonaan merkki.'),
(1692475,58,40,12,40,'Sillä niinkuin Joonas oli meripedon vatsassa kolme päivää ja kolme yötä, niin on myös Ihmisen Poika oleva maan povessa kolme päivää ja kolme yötä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692476,58,40,12,41,'Niiniven miehet nousevat tuomiolle yhdessä tämän sukupolven kanssa ja tulevat sille tuomioksi; sillä he tekivät parannuksen Joonaan saarnan vaikutuksesta, ja katso, tässä on enempi kuin Joonas.'),
(1692477,58,40,12,42,'Etelän kuningatar on heräjävä tuomiolle tämän sukupolven kanssa ja tuleva sille tuomioksi; sillä hän tuli maan ääristä kuulemaan Salomon viisautta, ja katso, tässä on enempi kuin Salomo.'),
(1692478,58,40,12,43,'Kun saastainen henki lähtee ihmisestä, kuljeksii se autioita paikkoja ja etsii lepoa, eikä löydä.'),
(1692479,58,40,12,44,'Silloin se sanoo: ''Minä palaan huoneeseeni, josta lähdin''. Ja kun se tulee, tapaa se huoneen tyhjänä ja lakaistuna ja kaunistettuna.'),
(1692480,58,40,12,45,'Silloin se menee ja ottaa mukaansa seitsemän muuta henkeä, pahempaa kuin se itse, ja ne tulevat sisään ja asuvat siellä. Ja sen ihmisen viimeiset tulevat pahemmiksi kuin ensimmäiset. Niin käy myös tälle pahalle sukupolvelle."'),
(1692481,58,40,12,46,'Hänen vielä puhuessaan kansalle, katso, hänen äitinsä ja veljensä seisoivat ulkona, tahtoen häntä puhutella.'),
(1692482,58,40,12,47,'Niin joku sanoi hänelle: "Katso, sinun äitisi ja veljesi seisovat ulkona ja tahtovat sinua puhutella".'),
(1692483,58,40,12,48,'Mutta hän vastasi ja sanoi sille, joka sen hänelle ilmoitti: "Kuka on minun äitini, ja ketkä ovat minun veljeni?"'),
(1692484,58,40,12,49,'Ja hän ojensi kätensä opetuslastensa puoleen ja sanoi: "Katso, minun äitini ja veljeni!'),
(1692485,58,40,12,50,'Sillä jokainen, joka tekee minun taivaallisen Isäni tahdon, on minun veljeni ja sisareni ja äitini."'),
(1692486,58,40,13,1,'Sinä päivänä Jeesus lähti asunnostaan ja istui järven rannalle.'),
(1692487,58,40,13,2,'Ja hänen tykönsä kokoontui paljon kansaa, jonka tähden hän astui venheeseen ja istuutui, ja kaikki kansa seisoi rannalla.'),
(1692488,58,40,13,3,'Ja hän puhui heille paljon vertauksilla ja sanoi: "Katso, kylväjä meni kylvämään.'),
(1692489,58,40,13,4,'Ja hänen kylväessään putosivat muutamat siemenet tien oheen, ja linnut tulivat ja söivät ne.'),
(1692490,58,40,13,5,'Toiset putosivat kallioperälle, jossa niillä ei ollut paljon maata, ja ne nousivat kohta oraalle, kun niillä ei ollut syvää maata.'),
(1692491,58,40,13,6,'Mutta auringon noustua ne paahtuivat, ja kun niillä ei ollut juurta, niin ne kuivettuivat.'),
(1692492,58,40,13,7,'Toiset taas putosivat orjantappuroihin, ja orjantappurat nousivat ja tukahuttivat ne.'),
(1692493,58,40,13,8,'Ja toiset putosivat hyvään maahan ja antoivat sadon, mitkä sata, mitkä kuusikymmentä, mitkä kolmekymmentä jyvää.'),
(1692494,58,40,13,9,'Jolla on korvat, se kuulkoon."'),
(1692495,58,40,13,10,'Niin hänen opetuslapsensa tulivat ja sanoivat hänelle: "Minkätähden sinä puhut heille vertauksilla?"'),
(1692496,58,40,13,11,'Hän vastasi ja sanoi: "Sentähden, että teidän on annettu tuntea taivasten valtakunnan salaisuudet, mutta heidän ei ole annettu.'),
(1692497,58,40,13,12,'Sillä sille, jolla on, annetaan, ja hänellä on oleva yltäkyllin; mutta siltä, jolla ei ole, otetaan pois sekin, mikä hänellä on.'),
(1692498,58,40,13,13,'Sentähden minä puhun heille vertauksilla, että he näkevin silmin eivät näe ja kuulevin korvin eivät kuule, eivätkä ymmärrä.'),
(1692499,58,40,13,14,'Ja heissä käy toteen Esaiaan ennustus, joka sanoo: ''Kuulemalla kuulkaa, älkääkä ymmärtäkö, ja näkemällä nähkää, älkääkä käsittäkö.'),
(1692500,58,40,13,15,'Sillä paatunut on tämän kansan sydän, ja korvillaan he työläästi kuulevat, ja silmänsä he ovat ummistaneet, etteivät he näkisi silmillään, eivät kuulisi korvillaan, eivät ymmärtäisi sydämellään eivätkä kääntyisi ja etten minä heitä parantaisi.'''),
(1692501,58,40,13,16,'Mutta autuaat ovat teidän silmänne, koska ne näkevät, ja teidän korvanne, koska ne kuulevat.'),
(1692502,58,40,13,17,'Sillä totisesti minä sanon teille: monet profeetat ja vanhurskaat ovat halunneet nähdä, mitä te näette, eivätkä ole nähneet, ja kuulla, mitä te kuulette, eivätkä ole kuulleet.'),
(1692503,58,40,13,18,'Kuulkaa siis te vertaus kylväjästä:'),
(1692504,58,40,13,19,'Kun joku kuulee valtakunnan sanan eikä ymmärrä, niin tulee paha ja tempaa pois sen, mikä hänen sydämeensä kylvettiin. Tämä on se, mikä kylvettiin tien oheen.'),
(1692505,58,40,13,20,'Mikä kallioperälle kylvettiin, on se, joka kuulee sanan ja heti ottaa sen ilolla vastaan;'),
(1692506,58,40,13,21,'mutta hänellä ei ole juurta itsessään, vaan hän kestää ainoastaan jonkun aikaa, ja kun tulee ahdistus tai vaino sanan tähden, niin hän heti lankeaa pois.'),
(1692507,58,40,13,22,'Mikä taas orjantappuroihin kylvettiin, on se, joka kuulee sanan, mutta tämän maailman huoli ja rikkauden viettelys tukahuttavat sanan, ja hän jää hedelmättömäksi.'),
(1692508,58,40,13,23,'Mutta mikä hyvään maahan kylvettiin, on se, joka kuulee sanan ja ymmärtää sen ja myös tuottaa hedelmän ja tekee, mikä sata jyvää, mikä kuusikymmentä, mikä kolmekymmentä."'),
(1692509,58,40,13,24,'Toisen vertauksen hän puhui heille sanoen: "Taivasten valtakunta on verrattava mieheen, joka kylvi hyvän siemenen peltoonsa.'),
(1692510,58,40,13,25,'Mutta ihmisten nukkuessa hänen vihamiehensä tuli ja kylvi lustetta nisun sekaan ja meni pois.'),
(1692511,58,40,13,26,'Ja kun laiho kasvoi ja teki hedelmää, silloin lustekin tuli näkyviin.'),
(1692512,58,40,13,27,'Niin perheenisännän palvelijat tulivat ja sanoivat hänelle: ''Herra, etkö kylvänyt peltoosi hyvää siementä? Mistä siihen sitten on tullut lustetta?'''),
(1692513,58,40,13,28,'Hän sanoi heille: ''Sen on vihamies tehnyt''. Niin palvelijat sanoivat hänelle: ''Tahdotko, että menemme ja kokoamme sen?'''),
(1692514,58,40,13,29,'Mutta hän sanoi: ''En, ettette lustetta kootessanne nyhtäisi sen mukana nisuakin.'),
(1692515,58,40,13,30,'Antakaa molempain kasvaa yhdessä elonleikkuuseen asti; ja elonaikana minä sanon leikkuumiehille: Kootkaa ensin luste ja sitokaa se kimppuihin poltettavaksi, mutta nisu korjatkaa minun aittaani.''"'),
(1692516,58,40,13,31,'Vielä toisen vertauksen hän puhui heille sanoen: "Taivasten valtakunta on sinapinsiemenen kaltainen, jonka mies otti ja kylvi peltoonsa.'),
(1692517,58,40,13,32,'Se on kaikista siemenistä pienin, mutta kun se on kasvanut, on se suurin vihanneskasveista ja tulee puuksi, niin että taivaan linnut tulevat ja tekevät pesänsä sen oksille."'),
(1692518,58,40,13,33,'Taas toisen vertauksen hän puhui heille: "Taivasten valtakunta on hapatuksen kaltainen, jonka nainen otti ja sekoitti kolmeen vakalliseen jauhoja, kunnes kaikki happani".'),
(1692519,58,40,13,34,'Tämän kaiken Jeesus puhui kansalle vertauksilla, ja ilman vertausta hän ei puhunut heille mitään;'),
(1692520,58,40,13,35,'että kävisi toteen, mikä on puhuttu profeetan kautta, joka sanoo: "Minä avaan suuni vertauksiin, minä tuon ilmi sen, mikä on ollut salassa maailman perustamisesta asti".'),
(1692521,58,40,13,36,'Sitten hän laski luotaan kansanjoukot ja meni asuntoonsa. Ja hänen opetuslapsensa tulivat hänen tykönsä ja sanoivat: "Selitä meille vertaus pellon lusteesta".'),
(1692522,58,40,13,37,'Niin hän vastasi ja sanoi: "Hyvän siemenen kylväjä on Ihmisen Poika.'),
(1692523,58,40,13,38,'Pelto on maailma; hyvä siemen ovat valtakunnan lapset, mutta lusteet ovat pahan lapset.'),
(1692524,58,40,13,39,'Vihamies, joka ne kylvi, on perkele; elonaika on maailman loppu, ja leikkuumiehet ovat enkelit.'),
(1692525,58,40,13,40,'Niinkuin lusteet kootaan ja tulessa poltetaan, niin on tapahtuva maailman lopussa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692526,58,40,13,41,'Ihmisen Poika lähettää enkelinsä, ja he kokoavat hänen valtakunnastaan kaikki, jotka ovat pahennukseksi ja jotka tekevät laittomuutta,'),
(1692527,58,40,13,42,'ja heittävät heidät tuliseen pätsiin; siellä on oleva itku ja hammasten kiristys.'),
(1692528,58,40,13,43,'Silloin vanhurskaat loistavat Isänsä valtakunnassa niinkuin aurinko. Jolla on korvat, se kuulkoon.'),
(1692529,58,40,13,44,'Taivasten valtakunta on peltoon kätketyn aarteen kaltainen, jonka mies löysi ja kätki; ja siitä iloissaan hän meni ja myi kaikki, mitä hänellä oli, ja osti sen pellon.'),
(1692530,58,40,13,45,'Vielä taivasten valtakunta on kuin kauppias, joka etsi kalliita helmiä,'),
(1692531,58,40,13,46,'ja löydettyään yhden kallisarvoisen helmen hän meni ja myi kaikki, mitä hänellä oli, ja osti sen.'),
(1692532,58,40,13,47,'Vielä taivasten valtakunta on nuotan kaltainen, joka heitettiin mereen ja kokosi kaikkinaisia kaloja.'),
(1692533,58,40,13,48,'Ja kun se tuli täyteen, vetivät he sen rannalle, istuutuivat ja kokosivat hyvät astioihin, mutta kelvottomat he viskasivat pois.'),
(1692534,58,40,13,49,'Näin on käyvä maailman lopussa; enkelit lähtevät ja erottavat pahat vanhurskaista'),
(1692535,58,40,13,50,'ja heittävät heidät tuliseen pätsiin; siellä on oleva itku ja hammasten kiristys.'),
(1692536,58,40,13,51,'Oletteko ymmärtäneet tämän kaiken?" He vastasivat hänelle: "Olemme".'),
(1692537,58,40,13,52,'Ja hän sanoi heille: "Niin on jokainen kirjanoppinut, joka on tullut taivasten valtakunnan opetuslapseksi, perheenisännän kaltainen, joka tuo aarrekammiostaan esille uutta ja vanhaa".'),
(1692538,58,40,13,53,'Ja kun Jeesus oli lopettanut nämä vertaukset, lähti hän sieltä.'),
(1692539,58,40,13,54,'Ja hän tuli kotikaupunkiinsa ja opetti heitä heidän synagoogassaan, niin että he hämmästyivät ja sanoivat: "Mistä hänellä on tämä viisaus ja nämä voimalliset teot?'),
(1692540,58,40,13,55,'Eikö tämä ole se rakentajan poika? Eikö hänen äitinsä ole nimeltään Maria ja hänen veljensä Jaakob ja Joosef ja Simon ja Juudas?'),
(1692541,58,40,13,56,'Ja eivätkö hänen sisarensa ole kaikki meidän parissamme? Mistä sitten hänellä on tämä kaikki?"'),
(1692542,58,40,13,57,'Ja he loukkaantuivat häneen. Mutta Jeesus sanoi heille: "Ei ole profeetta halveksittu muualla kuin kotikaupungissaan ja kodissaan".'),
(1692543,58,40,13,58,'Ja heidän epäuskonsa tähden hän ei tehnyt siellä monta voimallista tekoa.'),
(1692544,58,40,14,1,'Siihen aikaan neljännysruhtinas Herodes kuuli maineen Jeesuksesta.'),
(1692545,58,40,14,2,'Ja hän sanoi palvelijoilleen: "Se on Johannes Kastaja; hän on noussut kuolleista, ja sentähden nämä voimat hänessä vaikuttavat".'),
(1692546,58,40,14,3,'Sillä Herodes oli ottanut Johanneksen kiinni ja sitonut hänet ja pannut vankeuteen veljensä Filippuksen vaimon, Herodiaan, tähden.'),
(1692547,58,40,14,4,'Sillä Johannes oli sanonut hänelle: "Sinun ei ole lupa pitää häntä".'),
(1692548,58,40,14,5,'Ja Herodes olisi tahtonut tappaa Johanneksen, mutta pelkäsi kansaa, sillä he pitivät häntä profeettana.'),
(1692549,58,40,14,6,'Mutta kun Herodeksen syntymäpäivä tuli, tanssi Herodiaan tytär heidän edessään, ja se miellytti Herodesta;'),
(1692550,58,40,14,7,'sentähden hän valalla vannoen lupasi antaa hänelle, mitä ikinä hän anoisi.'),
(1692551,58,40,14,8,'Niin hän äitinsä yllytyksestä sanoi: "Anna tuoda minulle tänne lautasella Johannes Kastajan pää".'),
(1692552,58,40,14,9,'Silloin kuningas tuli murheelliseksi, mutta valansa ja pöytävierasten tähden hän käski antaa sen.'),
(1692553,58,40,14,10,'Ja hän lähetti lyömään Johannekselta pään poikki vankilassa.'),
(1692554,58,40,14,11,'Ja hänen päänsä tuotiin lautasella ja annettiin tytölle; ja tämä vei sen äidilleen.'),
(1692555,58,40,14,12,'Ja hänen opetuslapsensa tulivat ja ottivat hänen ruumiinsa ja hautasivat hänet; ja he menivät ja ilmoittivat asian Jeesukselle.'),
(1692556,58,40,14,13,'Kun Jeesus sen kuuli, lähti hän sieltä venheellä autioon paikkaan, yksinäisyyteen. Ja tämän kuultuaan kansa meni jalkaisin kaupungeista hänen jälkeensä.'),
(1692557,58,40,14,14,'Ja astuessaan maihin Jeesus näki paljon kansaa, ja hänen kävi heitä sääliksi, ja hän paransi heidän sairaansa.'),
(1692558,58,40,14,15,'Mutta kun ilta tuli, menivät hänen opetuslapsensa hänen tykönsä ja sanoivat: "Tämä paikka on autio, ja päivä on jo pitkälle kulunut; laske siis kansa luotasi, että he menisivät kyliin ostamaan itsellensä ruokaa".'),
(1692559,58,40,14,16,'Mutta Jeesus sanoi heille: "Ei heidän tarvitse mennä pois; antakaa te heille syödä".'),
(1692560,58,40,14,17,'He sanoivat hänelle: "Meillä ei ole täällä muuta kuin viisi leipää ja kaksi kalaa".'),
(1692561,58,40,14,18,'Mutta hän sanoi: "Tuokaa ne tänne minulle".'),
(1692562,58,40,14,19,'Ja hän käski kansan asettua ruohikkoon, otti ne viisi leipää ja kaksi kalaa, katsoi ylös taivaaseen ja siunasi, mursi ja antoi leivät opetuslapsillensa, ja opetuslapset antoivat kansalle.'),
(1692563,58,40,14,20,'Ja kaikki söivät ja tulivat ravituiksi. Sitten he keräsivät jääneet palaset, kaksitoista täyttä vakallista.'),
(1692564,58,40,14,21,'Ja niitä, jotka aterioivat, oli noin viisituhatta miestä, paitsi naisia ja lapsia.'),
(1692565,58,40,14,22,'Ja kohta hän vaati opetuslapsiansa astumaan venheeseen ja kulkemaan edeltä toiselle rannalle, sillä aikaa kuin hän laski kansan luotansa.'),
(1692566,58,40,14,23,'Ja laskettuaan kansan hän nousi vuorelle yksinäisyyteen, rukoilemaan. Ja kun ilta tuli, oli hän siellä yksinänsä.'),
(1692567,58,40,14,24,'Mutta venhe oli jo monen vakomitan päässä maasta, aaltojen ahdistamana, sillä tuuli oli vastainen.'),
(1692568,58,40,14,25,'Ja neljännellä yövartiolla Jeesus tuli heidän tykönsä kävellen järven päällä.'),
(1692569,58,40,14,26,'Kun opetuslapset näkivät hänen kävelevän järven päällä, peljästyivät he ja sanoivat: "Se on aave", ja huusivat pelosta.'),
(1692570,58,40,14,27,'Mutta Jeesus puhutteli heitä kohta ja sanoi: "Olkaa turvallisella mielellä, minä se olen; älkää peljätkö".'),
(1692571,58,40,14,28,'Pietari vastasi hänelle ja sanoi: "Jos se olet sinä, Herra, niin käske minun tulla tykösi vettä myöten".'),
(1692572,58,40,14,29,'Hän sanoi: "Tule". Ja Pietari astui ulos venheestä ja käveli vetten päällä mennäkseen Jeesuksen tykö.'),
(1692573,58,40,14,30,'Mutta nähdessään, kuinka tuuli, hän peljästyi ja rupesi vajoamaan ja huusi sanoen: "Herra, auta minua".'),
(1692574,58,40,14,31,'Niin Jeesus kohta ojensi kätensä, tarttui häneen ja sanoi hänelle: "Sinä vähäuskoinen, miksi epäilit?"'),
(1692575,58,40,14,32,'Ja kun he olivat astuneet venheeseen, asettui tuuli.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692576,58,40,14,33,'Niin venheessä-olijat kumarsivat häntä ja sanoivat: "Totisesti sinä olet Jumalan Poika".'),
(1692577,58,40,14,34,'Ja kuljettuaan yli he tulivat maihin Gennesaretiin.'),
(1692578,58,40,14,35,'Ja kun sen paikkakunnan miehet tunsivat hänet, lähettivät he sanan kaikkeen ympäristöön, ja hänen tykönsä tuotiin kaikki sairaat.'),
(1692579,58,40,14,36,'Ja he pyysivät häneltä, että vain saisivat koskea hänen vaippansa tupsuun; ja kaikki, jotka koskivat, paranivat.'),
(1692580,58,40,15,1,'Silloin tuli fariseuksia ja kirjanoppineita Jerusalemista Jeesuksen luo, ja he sanoivat:'),
(1692581,58,40,15,2,'"Miksi sinun opetuslapsesi rikkovat vanhinten perinnäissääntöä? Sillä he eivät pese käsiään ruvetessaan aterialle."'),
(1692582,58,40,15,3,'Mutta hän vastasi ja sanoi heille: "Miksi te itse rikotte Jumalan käskyn perinnäissääntönne tähden?'),
(1692583,58,40,15,4,'Sillä Jumala on sanonut: ''Kunnioita isääsi ja äitiäsi'', ja: ''Joka kiroaa isäänsä tai äitiänsä, sen pitää kuolemalla kuoleman''.'),
(1692584,58,40,15,5,'Mutta te sanotte: Joka sanoo isälleen tai äidilleen: ''Se, minkä sinä olisit ollut minulta saapa, on annettu uhrilahjaksi'', sen ei tarvitse kunnioittaa isäänsä eikä äitiänsä.'),
(1692585,58,40,15,6,'Ja niin te olette tehneet Jumalan sanan tyhjäksi perinnäissääntönne tähden.'),
(1692586,58,40,15,7,'Te ulkokullatut, oikein teistä Esaias ennusti, sanoen:'),
(1692587,58,40,15,8,'''Tämä kansa kunnioittaa minua huulillaan, mutta heidän sydämensä on minusta kaukana,'),
(1692588,58,40,15,9,'mutta turhaan he palvelevat minua opettaen oppeja, jotka ovat ihmiskäskyjä''."'),
(1692589,58,40,15,10,'Ja hän kutsui kansan tykönsä ja sanoi heille: "Kuulkaa ja ymmärtäkää.'),
(1692590,58,40,15,11,'Ei saastuta ihmistä se, mikä menee suusta sisään; vaan mikä suusta käy ulos, se saastuttaa ihmisen."'),
(1692591,58,40,15,12,'Silloin opetuslapset tulivat ja sanoivat hänelle: "Tiedätkö, että fariseukset loukkaantuivat kuullessaan tuon puheen?"'),
(1692592,58,40,15,13,'Mutta hän vastasi ja sanoi: "Jokainen istutus, jota minun taivaallinen Isäni ei ole istuttanut, on juurineen revittävä pois.'),
(1692593,58,40,15,14,'Älkää heistä välittäkö: he ovat sokeita sokeain taluttajia; mutta jos sokea sokeaa taluttaa, niin he molemmat kuoppaan lankeavat."'),
(1692594,58,40,15,15,'Niin Pietari vastasi ja sanoi hänelle: "Selitä meille tämä vertaus".'),
(1692595,58,40,15,16,'Mutta Jeesus sanoi: "Vieläkö tekin olette ymmärtämättömiä?'),
(1692596,58,40,15,17,'Ettekö käsitä, että kaikki, mikä käy suusta sisään, menee vatsaan ja ulostuu?'),
(1692597,58,40,15,18,'Mutta mikä käy suusta ulos, se tulee sydämestä, ja se saastuttaa ihmisen.'),
(1692598,58,40,15,19,'Sillä sydämestä lähtevät pahat ajatukset, murhat, aviorikokset, haureudet, varkaudet, väärät todistukset, jumalanpilkkaamiset.'),
(1692599,58,40,15,20,'Nämä ihmisen saastuttavat; mutta pesemättömin käsin syöminen ei saastuta ihmistä."'),
(1692600,58,40,15,21,'Ja Jeesus lähti sieltä ja vetäytyi Tyyron ja Siidonin tienoille.'),
(1692601,58,40,15,22,'Ja katso, kanaanilainen vaimo tuli niiltä seuduilta ja huusi sanoen: "Herra, Daavidin poika, armahda minua. Riivaaja vaivaa kauheasti minun tytärtäni."'),
(1692602,58,40,15,23,'Mutta hän ei vastannut hänelle sanaakaan. Niin hänen opetuslapsensa tulivat ja rukoilivat häntä sanoen: "Päästä hänet menemään, sillä hän huutaa meidän jälkeemme".'),
(1692603,58,40,15,24,'Hän vastasi ja sanoi: "Minua ei ole lähetetty muitten kuin Israelin huoneen kadonneitten lammasten tykö".'),
(1692604,58,40,15,25,'Mutta vaimo tuli ja kumarsi häntä ja sanoi: "Herra, auta minua".'),
(1692605,58,40,15,26,'Mutta hän vastasi ja sanoi: "Ei ole soveliasta ottaa lasten leipää ja heittää penikoille".'),
(1692606,58,40,15,27,'Mutta vaimo sanoi: "Niin, Herra; mutta syöväthän penikatkin niitä muruja, jotka heidän herrainsa pöydältä putoavat".'),
(1692607,58,40,15,28,'Silloin Jeesus vastasi ja sanoi hänelle: "Oi vaimo, suuri on sinun uskosi, tapahtukoon sinulle, niinkuin tahdot". Ja hänen tyttärensä oli siitä hetkestä terve.'),
(1692608,58,40,15,29,'Ja Jeesus lähti sieltä ja tuli Galilean järven rannalle; ja hän nousi vuorelle ja istui sinne.'),
(1692609,58,40,15,30,'Ja hänen tykönsä tuli paljon kansaa, ja he toivat mukanaan rampoja, raajarikkoja, sokeita, mykkiä ja paljon muita, ja laskivat heidät hänen jalkojensa juureen; ja hän paransi heidät,'),
(1692610,58,40,15,31,'niin että kansa ihmetteli nähdessään mykkäin puhuvan, raajarikkojen olevan terveitä, rampojen kävelevän ja sokeain näkevän; ja he ylistivät Israelin Jumalaa.'),
(1692611,58,40,15,32,'Ja Jeesus kutsui opetuslapsensa tykönsä ja sanoi: "Minun käy sääliksi kansaa, sillä he ovat jo kolme päivää olleet minun tykönäni, eikä heillä ole mitään syötävää; enkä minä tahdo laskea heitä syömättä menemään, etteivät nääntyisi matkalla".'),
(1692612,58,40,15,33,'Niin opetuslapset sanoivat hänelle: "Mistä me saamme täällä erämaassa niin paljon leipää, että voimme ravita noin suuren kansanjoukon?"'),
(1692613,58,40,15,34,'Jeesus sanoi heille: "Montako leipää teillä on?" He sanoivat: "Seitsemän, ja muutamia kalasia".'),
(1692614,58,40,15,35,'Niin hän käski kansan asettua maahan.'),
(1692615,58,40,15,36,'Ja hän otti ne seitsemän leipää ja kalat, kiitti, mursi ja antoi opetuslapsillensa, ja opetuslapset antoivat kansalle.'),
(1692616,58,40,15,37,'Ja kaikki söivät ja tulivat ravituiksi. Sitten he keräsivät jääneet palaset, seitsemän täyttä vasullista.'),
(1692617,58,40,15,38,'Ja niitä, jotka aterioivat, oli neljätuhatta miestä, paitsi naisia ja lapsia.'),
(1692618,58,40,15,39,'Ja laskettuaan kansan tyköänsä hän astui venheeseen ja meni Magadanin alueelle.'),
(1692619,58,40,16,1,'Ja fariseukset ja saddukeukset tulivat hänen luoksensa ja kiusasivat häntä pyytäen häntä näyttämään heille merkin taivaasta.'),
(1692620,58,40,16,2,'Mutta hän vastasi ja sanoi heille: "Kun ilta tulee, sanotte te: ''Tulee selkeä ilma, sillä taivas ruskottaa'','),
(1692621,58,40,16,3,'ja aamulla: ''Tänään tulee rajuilma, sillä taivas ruskottaa ja on synkkä''. Taivaan muodon te osaatte arvioida, mutta aikain merkkejä ette osaa.'),
(1692622,58,40,16,4,'Tämä paha ja avionrikkoja sukupolvi tavoittelee merkkiä, mutta sille ei anneta muuta merkkiä kuin Joonaan merkki." Ja hän jätti heidät ja meni pois.'),
(1692623,58,40,16,5,'Kun opetuslapset saapuivat toiselle rannalle, olivat he unhottaneet ottaa leipää mukaansa.'),
(1692624,58,40,16,6,'Ja Jeesus sanoi heille: "Varokaa ja kavahtakaa fariseusten ja saddukeusten hapatusta".'),
(1692625,58,40,16,7,'Niin he puhuivat keskenään sanoen: "Emme ottaneet leipää mukaamme".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692626,58,40,16,8,'Mutta kun Jeesus sen huomasi, sanoi hän: "Te vähäuskoiset, mitä puhutte keskenänne siitä, ettei teillä ole leipää mukananne?'),
(1692627,58,40,16,9,'Ettekö vielä käsitä? Ja ettekö muista niitä viittä leipää viidelletuhannelle ja kuinka monta vakallista otitte talteen,'),
(1692628,58,40,16,10,'ettekä niitä seitsemää leipää neljälletuhannelle ja kuinka monta vasullista otitte talteen?'),
(1692629,58,40,16,11,'Kuinka te ette käsitä, etten minä puhunut teille leivästä? Vaan kavahtakaa fariseusten ja saddukeusten hapatusta."'),
(1692630,58,40,16,12,'Silloin he ymmärsivät, ettei hän käskenyt kavahtamaan leivän hapatusta, vaan fariseusten ja saddukeusten oppia.'),
(1692631,58,40,16,13,'Kun Jeesus tuli Filippuksen Kesarean tienoille, kysyi hän opetuslapsiltaan sanoen: "Kenen ihmiset sanovat Ihmisen Pojan olevan?"'),
(1692632,58,40,16,14,'Niin he sanoivat: "Muutamat Johannes Kastajan, toiset Eliaan, toiset taas Jeremiaan tahi jonkun muun profeetoista".'),
(1692633,58,40,16,15,'Hän sanoi heille: "Kenenkä te sanotte minun olevan?"'),
(1692634,58,40,16,16,'Simon Pietari vastasi ja sanoi: "Sinä olet Kristus, elävän Jumalan Poika".'),
(1692635,58,40,16,17,'Jeesus vastasi ja sanoi hänelle: "Autuas olet sinä, Simon, Joonaan poika, sillä ei liha eikä veri ole sitä sinulle ilmoittanut, vaan minun Isäni, joka on taivaissa.'),
(1692636,58,40,16,18,'Ja minä sanon sinulle: sinä olet Pietari, ja tälle kalliolle minä rakennan seurakuntani, ja tuonelan portit eivät sitä voita.'),
(1692637,58,40,16,19,'Minä olen antava sinulle taivasten valtakunnan avaimet, ja minkä sinä sidot maan päällä, se on oleva sidottu taivaissa, ja minkä sinä päästät maan päällä, se on oleva päästetty taivaissa."'),
(1692638,58,40,16,20,'Silloin hän varoitti vakavasti opetuslapsiaan kenellekään sanomasta, että hän on Kristus.'),
(1692639,58,40,16,21,'Siitä lähtien Jeesus alkoi ilmoittaa opetuslapsilleen, että hänen piti menemän Jerusalemiin ja kärsimän paljon vanhimmilta ja ylipapeilta ja kirjanoppineilta ja tuleman tapetuksi ja kolmantena päivänä nouseman ylös.'),
(1692640,58,40,16,22,'Silloin Pietari otti hänet erilleen ja rupesi nuhtelemaan häntä sanoen: "Jumala varjelkoon, Herra, älköön se sinulle tapahtuko".'),
(1692641,58,40,16,23,'Mutta hän kääntyi ja sanoi Pietarille: "Mene pois minun edestäni, saatana; sinä olet minulle pahennukseksi, sillä sinä et ajattele sitä, mikä on Jumalan, vaan sitä, mikä on ihmisten".'),
(1692642,58,40,16,24,'Silloin Jeesus sanoi opetuslapsillensa: "Jos joku tahtoo minun perässäni kulkea, hän kieltäköön itsensä ja ottakoon ristinsä ja seuratkoon minua.'),
(1692643,58,40,16,25,'Sillä joka tahtoo pelastaa elämänsä, hän kadottaa sen, mutta joka kadottaa elämänsä minun tähteni, hän löytää sen.'),
(1692644,58,40,16,26,'Sillä mitä se hyödyttää ihmistä, vaikka hän voittaisi omaksensa koko maailman, mutta saisi sielullensa vahingon? Taikka mitä voi ihminen antaa sielunsa lunnaiksi?'),
(1692645,58,40,16,27,'Sillä Ihmisen Poika on tuleva Isänsä kirkkaudessa enkeliensä kanssa, ja silloin hän maksaa kullekin hänen tekojensa mukaan.'),
(1692646,58,40,16,28,'Totisesti minä sanon teille: tässä seisovien joukossa on muutamia, jotka eivät maista kuolemaa, ennenkuin näkevät Ihmisen Pojan tulevan kuninkuudessaan."'),
(1692647,58,40,17,1,'Ja kuuden päivän kuluttua Jeesus otti mukaansa Pietarin sekä Jaakobin ja hänen veljensä Johanneksen ja vei heidät korkealle vuorelle, yksinäisyyteen.'),
(1692648,58,40,17,2,'Ja hänen muotonsa muuttui heidän edessään, ja hänen kasvonsa loistivat niinkuin aurinko, ja hänen vaatteensa tulivat valkoisiksi niinkuin valo.'),
(1692649,58,40,17,3,'Ja katso, heille ilmestyivät Mooses ja Elias, jotka puhuivat hänen kanssansa.'),
(1692650,58,40,17,4,'Niin Pietari rupesi puhumaan ja sanoi Jeesukselle: "Herra, meidän on tässä hyvä olla; jos tahdot, niin minä teen tähän kolme majaa, sinulle yhden ja Moosekselle yhden ja Eliaalle yhden".'),
(1692651,58,40,17,5,'Hänen vielä puhuessaan, katso, heidät varjosi valoisa pilvi; ja katso, pilvestä kuului ääni, joka sanoi: "Tämä on minun rakas Poikani, johon minä olen mielistynyt; kuulkaa häntä".'),
(1692652,58,40,17,6,'Kun opetuslapset sen kuulivat, lankesivat he kasvoilleen ja peljästyivät kovin.'),
(1692653,58,40,17,7,'Niin Jeesus tuli heidän tykönsä, koski heihin ja sanoi: "Nouskaa, älkääkä peljätkö".'),
(1692654,58,40,17,8,'Ja kun he nostivat silmänsä, eivät he nähneet ketään muuta kuin Jeesuksen yksinään.'),
(1692655,58,40,17,9,'Ja heidän kulkiessaan alas vuorelta Jeesus varoitti heitä sanoen: "Älkää kenellekään kertoko tätä näkyä, ennenkuin Ihmisen Poika on noussut kuolleista".'),
(1692656,58,40,17,10,'Ja hänen opetuslapsensa kysyivät häneltä sanoen: "Miksi sitten kirjanoppineet sanovat, että Eliaan pitää tulla ensin?"'),
(1692657,58,40,17,11,'Jeesus vastasi ja sanoi: "Elias tosin tulee ja asettaa kaikki kohdalleen.'),
(1692658,58,40,17,12,'Mutta minä sanon teille, että Elias on jo tullut. Mutta he eivät tunteneet häntä, vaan tekivät hänelle, mitä tahtoivat. Samoin myös Ihmisen Poika saa kärsiä heiltä."'),
(1692659,58,40,17,13,'Silloin opetuslapset ymmärsivät hänen puhuneen heille Johannes Kastajasta.'),
(1692660,58,40,17,14,'Ja kun he saapuivat kansan luo, tuli hänen tykönsä muuan mies, polvistui hänen eteensä'),
(1692661,58,40,17,15,'ja sanoi: "Herra, armahda minun poikaani, sillä hän on kuunvaihetautinen ja kärsii kovin; usein hän kaatuu, milloin tuleen, milloin veteen.'),
(1692662,58,40,17,16,'Ja minä toin hänet sinun opetuslastesi tykö, mutta he eivät voineet häntä parantaa."'),
(1692663,58,40,17,17,'Niin Jeesus vastasi ja sanoi: "Voi sinä epäuskoinen ja nurja sukupolvi, kuinka kauan minun täytyy olla teidän kanssanne? Kuinka kauan kärsiä teitä? Tuokaa hänet tänne minun tyköni."'),
(1692664,58,40,17,18,'Ja Jeesus nuhteli riivaajaa, ja se lähti pojasta, ja poika oli siitä hetkestä terve.'),
(1692665,58,40,17,19,'Sitten opetuslapset menivät Jeesuksen tykö eriksensä ja sanoivat: "Miksi emme me voineet ajaa sitä ulos?"'),
(1692666,58,40,17,20,'Niin hän sanoi heille: "Teidän epäuskonne tähden; sillä totisesti minä sanon teille: jos teillä olisi uskoa sinapinsiemenenkään verran, niin te voisitte sanoa tälle vuorelle: ''Siirry täältä tuonne'', ja se siirtyisi, eikä mikään olisi teille mahdotonta".'),
(1692667,58,40,17,22,'Ja kun he yhdessä vaelsivat Galileassa, sanoi Jeesus heille: "Ihmisen Poika annetaan ihmisten käsiin,'),
(1692668,58,40,17,23,'ja he tappavat hänet, ja kolmantena päivänä hän nousee ylös". Ja he tulivat kovin murheellisiksi.'),
(1692669,58,40,17,24,'Ja kun he saapuivat Kapernaumiin, tulivat temppeliveron kantajat Pietarin luo ja sanoivat: "Eikö teidän opettajanne maksa temppeliveroa?"'),
(1692670,58,40,17,25,'Hän sanoi: "Maksaa". Ja kun hän tuli huoneeseen, kysyi Jeesus häneltä ensi sanaksi: "Mitä arvelet, Simon? Keiltä maan kuninkaat ottavat tullia tai veroa? Lapsiltaanko vai vierailta?"'),
(1692671,58,40,17,26,'Ja kun hän vastasi: "Vierailta", sanoi Jeesus hänelle: "Lapset ovat siis vapaat.'),
(1692672,58,40,17,27,'Mutta ettemme heitä loukkaisi, niin mene ja heitä onki järveen. Ota sitten ensiksi saamasi kala, ja kun avaat sen suun, löydät hopearahan. Ota se ja anna heille minun puolestani ja omasta puolestasi."'),
(1692673,58,40,18,1,'Sillä hetkellä opetuslapset tulivat Jeesuksen tykö ja sanoivat: "Kuka on suurin taivasten valtakunnassa?"'),
(1692674,58,40,18,2,'Niin hän kutsui tykönsä lapsen, asetti sen heidän keskellensä'),
(1692675,58,40,18,3,'ja sanoi: "Totisesti minä sanon teille: ellette käänny ja tule lasten kaltaisiksi, ette pääse taivasten valtakuntaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692676,58,40,18,4,'Sentähden, joka nöyrtyy tämän lapsen kaltaiseksi, se on suurin taivasten valtakunnassa.'),
(1692677,58,40,18,5,'Ja joka ottaa tykönsä yhden tämänkaltaisen lapsen minun nimeeni, se ottaa tykönsä minut.'),
(1692678,58,40,18,6,'Mutta joka viettelee yhden näistä pienistä, jotka uskovat minuun, sen olisi parempi, että myllynkivi ripustettaisiin hänen kaulaansa ja hänet upotettaisiin meren syvyyteen.'),
(1692679,58,40,18,7,'Voi maailmaa viettelysten tähden! Viettelysten täytyy kyllä tulla; mutta voi sitä ihmistä, jonka kautta viettelys tulee!'),
(1692680,58,40,18,8,'Mutta jos sinun kätesi tai jalkasi viettelee sinua, hakkaa se poikki ja heitä luotasi; parempi on sinulle, että käsipuolena tai jalkapuolena pääset elämään sisälle, kuin että sinut, molemmat kädet tai molemmat jalat tallella, heitetään iankaikkiseen tuleen.'),
(1692681,58,40,18,9,'Ja jos sinun silmäsi viettelee sinua, repäise se pois ja heitä luotasi; parempi on sinun silmäpuolena mennä elämään sisälle, kuin että sinut, molemmat silmät tallella, heitetään helvetin tuleen.'),
(1692682,58,40,18,10,'Katsokaa, ettette halveksu yhtäkään näistä pienistä; sillä minä sanon teille, että heidän enkelinsä taivaissa näkevät aina minun Isäni kasvot, joka on taivaissa.'),
(1692683,58,40,18,12,'Mitä arvelette? Jos jollakin ihmisellä on sata lammasta ja yksi niistä eksyy, eikö hän jätä niitä yhdeksääkymmentä yhdeksää vuorille ja mene etsimään eksynyttä?'),
(1692684,58,40,18,13,'Ja jos hän sen löytää, totisesti minä sanon teille: hän iloitsee enemmän siitä kuin niistä yhdeksästäkymmenestä yhdeksästä, jotka eivät olleet eksyneet.'),
(1692685,58,40,18,14,'Niin ei myöskään teidän taivaallisen Isänne tahto ole, että yksikään näistä pienistä joutuisi kadotukseen.'),
(1692686,58,40,18,15,'Mutta jos veljesi rikkoo sinua vastaan, niin mene ja nuhtele häntä kahdenkesken; jos hän sinua kuulee, niin olet voittanut veljesi.'),
(1692687,58,40,18,16,'Mutta jos hän ei sinua kuule, niin ota vielä yksi tai kaksi kanssasi, ''että jokainen asia vahvistettaisiin kahden tai kolmen todistajan sanalla''.'),
(1692688,58,40,18,17,'Mutta jos hän ei kuule heitä, niin ilmoita seurakunnalle. Mutta jos hän ei seurakuntaakaan kuule, niin olkoon hän sinulle, niinkuin olisi pakana ja publikaani.'),
(1692689,58,40,18,18,'Totisesti minä sanon teille: kaikki, minkä te sidotte maan päällä, on oleva sidottu taivaassa, ja kaikki, minkä te päästätte maan päällä, on oleva päästetty taivaassa.'),
(1692690,58,40,18,19,'Vielä minä sanon teille: jos kaksi teistä maan päällä keskenään sopii mistä asiasta tahansa, että he sitä anovat, niin he saavat sen minun Isältäni, joka on taivaissa.'),
(1692691,58,40,18,20,'Sillä missä kaksi tahi kolme on kokoontunut minun nimeeni, siinä minä olen heidän keskellänsä."'),
(1692692,58,40,18,21,'Silloin Pietari meni hänen tykönsä ja sanoi hänelle: "Herra, kuinka monta kertaa minun on annettava anteeksi veljelleni, joka rikkoo minua vastaan? Ihanko seitsemän kertaa?"'),
(1692693,58,40,18,22,'Jeesus vastasi hänelle: "Minä sanon sinulle: ei seitsemän kertaa, vaan seitsemänkymmentä kertaa seitsemän.'),
(1692694,58,40,18,23,'Sentähden taivasten valtakunta on verrattava kuninkaaseen, joka vaati palvelijoiltansa tiliä.'),
(1692695,58,40,18,24,'Ja kun hän rupesi tilintekoon, tuotiin hänen eteensä eräs, joka oli hänelle velkaa kymmenentuhatta leiviskää.'),
(1692696,58,40,18,25,'Mutta kun tällä ei ollut, millä maksaa, niin hänen herransa määräsi myytäväksi hänet ja hänen vaimonsa ja lapsensa ja kaikki, mitä hänellä oli, ja velan maksettavaksi.'),
(1692697,58,40,18,26,'Silloin palvelija lankesi maahan ja rukoili häntä sanoen: ''Ole pitkämielinen minua kohtaan, niin minä maksan sinulle kaikki''.'),
(1692698,58,40,18,27,'Niin herran kävi sääliksi sitä palvelijaa, ja hän päästi hänet ja antoi hänelle velan anteeksi.'),
(1692699,58,40,18,28,'Mutta mentyään ulos se palvelija tapasi erään kanssapalvelijoistaan, joka oli hänelle velkaa sata denaria; ja hän tarttui häneen, kuristi häntä kurkusta ja sanoi: ''Maksa, minkä olet velkaa''.'),
(1692700,58,40,18,29,'Niin hänen kanssapalvelijansa lankesi maahan ja pyysi häntä sanoen: ''Ole pitkämielinen minua kohtaan, niin minä maksan sinulle''.'),
(1692701,58,40,18,30,'Mutta hän ei tahtonut, vaan meni ja heitti hänet vankeuteen, kunnes hän maksaisi velkansa.'),
(1692702,58,40,18,31,'Kun nyt hänen kanssapalvelijansa näkivät, mitä tapahtui, tulivat he kovin murheellisiksi ja menivät ja ilmoittivat herrallensa kaiken, mitä oli tapahtunut.'),
(1692703,58,40,18,32,'Silloin hänen herransa kutsui hänet eteensä ja sanoi hänelle: ''Sinä paha palvelija! Minä annoin sinulle anteeksi kaiken sen velan, koska sitä minulta pyysit;'),
(1692704,58,40,18,33,'eikö sinunkin olisi pitänyt armahtaa kanssapalvelijaasi, niinkuin minäkin sinua armahdin?'''),
(1692705,58,40,18,34,'Ja hänen herransa vihastui ja antoi hänet vanginvartijan käsiin, kunnes hän maksaisi kaiken, minkä oli hänelle velkaa.'),
(1692706,58,40,18,35,'Näin myös minun taivaallinen Isäni tekee teille, ellette anna kukin veljellenne sydämestänne anteeksi."'),
(1692707,58,40,19,1,'Ja kun Jeesus oli lopettanut nämä puheet, lähti hän Galileasta ja kulki Jordanin tuota puolta Juudean alueelle.'),
(1692708,58,40,19,2,'Ja suuri kansan paljous seurasi häntä, ja hän paransi heitä siellä.'),
(1692709,58,40,19,3,'Ja fariseuksia tuli hänen luoksensa, ja he kiusasivat häntä sanoen: "Onko miehen lupa hyljätä vaimonsa mistä syystä tahansa?"'),
(1692710,58,40,19,4,'Hän vastasi ja sanoi: "Ettekö ole lukeneet, että Luoja jo alussa ''loi heidät mieheksi ja naiseksi'''),
(1692711,58,40,19,5,'ja sanoi: ''Sentähden mies luopukoon isästänsä ja äidistänsä ja liittyköön vaimoonsa, ja ne kaksi tulevat yhdeksi lihaksi''?'),
(1692712,58,40,19,6,'Niin eivät he enää ole kaksi, vaan yksi liha. Minkä siis Jumala on yhdistänyt, sitä älköön ihminen erottako."'),
(1692713,58,40,19,7,'He sanoivat hänelle: "Miksi sitten Mooses käski antaa erokirjan ja hyljätä hänet?"'),
(1692714,58,40,19,8,'Hän sanoi heille: "Teidän sydämenne kovuuden tähden Mooses salli teidän hyljätä vaimonne, mutta alusta ei niin ollut.'),
(1692715,58,40,19,9,'Mutta minä sanon teille: joka hylkää vaimonsa muun kuin huoruuden tähden ja nai toisen, se tekee huorin; ja joka nai hyljätyn, se tekee huorin."'),
(1692716,58,40,19,10,'Opetuslapset sanoivat hänelle: "Jos miehen on näin laita vaimoonsa nähden, niin ei ole hyvä naida".'),
(1692717,58,40,19,11,'Mutta hän sanoi heille: "Ei tämä sana kaikkiin sovellu, vaan ainoastaan niihin, joille se on suotu.'),
(1692718,58,40,19,12,'Sillä on niitä, jotka syntymästään, äitinsä kohdusta saakka, ovat avioon kelpaamattomia, ja on niitä, jotka ihmiset ovat tehneet avioon kelpaamattomiksi, ja niitä, jotka taivasten valtakunnan tähden ovat tehneet itsensä avioon kelpaamattomiksi. Joka voi sen itseensä sovittaa, se sovittakoon."'),
(1692719,58,40,19,13,'Silloin tuotiin hänen tykönsä lapsia, että hän panisi kätensä heidän päälleen ja rukoilisi; mutta opetuslapset nuhtelivat tuojia.'),
(1692720,58,40,19,14,'Niin Jeesus sanoi: "Antakaa lasten olla, älkääkä estäkö heitä tulemasta minun tyköni, sillä senkaltaisten on taivasten valtakunta".'),
(1692721,58,40,19,15,'Ja hän pani kätensä heidän päälleen ja lähti sieltä pois.'),
(1692722,58,40,19,16,'Ja katso, eräs mies tuli ja sanoi hänelle: "Opettaja, mitä hyvää minun pitää tekemän, että minä saisin iankaikkisen elämän?"'),
(1692723,58,40,19,17,'Niin hän sanoi hänelle: "Miksi kysyt minulta, mikä on hyvää? On ainoastaan yksi, joka on hyvä. Mutta jos tahdot päästä elämään sisälle, niin pidä käskyt."'),
(1692724,58,40,19,18,'Hän sanoi hänelle: "Mitkä?" Jeesus sanoi: "Nämä: ''Älä tapa'', ''Älä tee huorin'', ''Älä varasta'', ''Älä sano väärää todistusta'','),
(1692725,58,40,19,19,'''Kunnioita isääsi ja äitiäsi'', ja: ''Rakasta lähimmäistäsi niinkuin itseäsi''".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692726,58,40,19,20,'Nuorukainen sanoi hänelle: "Kaikkia niitä minä olen noudattanut; mitä minulta vielä puuttuu?"'),
(1692727,58,40,19,21,'Jeesus sanoi hänelle: "Jos tahdot olla täydellinen, niin mene, myy, mitä sinulla on, ja anna köyhille, niin sinulla on oleva aarre taivaissa; ja tule ja seuraa minua".'),
(1692728,58,40,19,22,'Mutta kun nuorukainen kuuli tämän sanan, meni hän pois murheellisena, sillä hänellä oli paljon omaisuutta.'),
(1692729,58,40,19,23,'Silloin Jeesus sanoi opetuslapsillensa: "Totisesti minä sanon teille: rikkaan on vaikea päästä taivasten valtakuntaan.'),
(1692730,58,40,19,24,'Ja vielä minä sanon teille: helpompi on kamelin käydä neulansilmän läpi kuin rikkaan päästä Jumalan valtakuntaan."'),
(1692731,58,40,19,25,'Kun opetuslapset sen kuulivat, hämmästyivät he kovin ja sanoivat: "Kuka sitten voi pelastua?"'),
(1692732,58,40,19,26,'Niin Jeesus katsoi heihin ja sanoi heille: "Ihmisille se on mahdotonta, mutta Jumalalle on kaikki mahdollista".'),
(1692733,58,40,19,27,'Silloin Pietari vastasi ja sanoi hänelle: "Katso, me olemme luopuneet kaikesta ja seuranneet sinua; mitä me siitä saamme?"'),
(1692734,58,40,19,28,'Niin Jeesus sanoi heille: "Totisesti minä sanon teille: siinä uudestisyntymisessä, jolloin Ihmisen Poika istuu kirkkautensa valtaistuimella, saatte tekin, jotka olette minua seuranneet, istua kahdellatoista valtaistuimella ja tuomita Israelin kahtatoista sukukuntaa.'),
(1692735,58,40,19,29,'Ja jokainen, joka on luopunut taloista tai veljistä tai sisarista tai isästä tai äidistä tai lapsista tai pelloista minun nimeni tähden, on saava monin verroin takaisin ja perivä iankaikkisen elämän.'),
(1692736,58,40,19,30,'Mutta monet ensimmäiset tulevat viimeisiksi, ja monet viimeiset ensimmäisiksi."'),
(1692737,58,40,20,1,'"Sillä taivasten valtakunta on perheenisännän kaltainen, joka varhain aamulla lähti ulos palkkaamaan työmiehiä viinitarhaansa.'),
(1692738,58,40,20,2,'Ja kun hän oli sopinut työmiesten kanssa denarista päivältä, lähetti hän heidät viinitarhaansa.'),
(1692739,58,40,20,3,'Ja hän lähti ulos kolmannen hetken vaiheilla ja näki toisia seisomassa torilla joutilaina;'),
(1692740,58,40,20,4,'ja hän sanoi heille: ''Menkää tekin minun viinitarhaani, ja mikä kohtuus on, sen minä annan teille''.'),
(1692741,58,40,20,5,'Niin he menivät. Taas hän lähti ulos kuudennen ja yhdeksännen hetken vaiheilla ja teki samoin.'),
(1692742,58,40,20,6,'Ja kun hän lähti ulos yhdennentoista hetken vaiheilla, tapasi hän vielä toisia siellä seisomassa; ja hän sanoi heille: ''Miksi seisotte täällä kaiken päivää joutilaina?'''),
(1692743,58,40,20,7,'He sanoivat hänelle: ''Kun ei kukaan ole meitä palkannut''. Hän sanoi heille: ''Menkää tekin minun viinitarhaani''.'),
(1692744,58,40,20,8,'Mutta kun ilta tuli, sanoi viinitarhan herra tilansa hoitajalle: ''Kutsu työmiehet ja maksa heille palkka, viimeisistä alkaen ensimmäisiin asti''.'),
(1692745,58,40,20,9,'Kun nyt tulivat ne, jotka olivat saapuneet yhdennentoista hetken vaiheilla, saivat he kukin denarin.'),
(1692746,58,40,20,10,'Ja kun ensimmäiset tulivat, luulivat he saavansa enemmän; mutta hekin saivat kukin denarin.'),
(1692747,58,40,20,11,'Kun he sen saivat, napisivat he perheen isäntää vastaan'),
(1692748,58,40,20,12,'ja sanoivat: ''Nämä viimeiset ovat tehneet työtä vain yhden hetken, ja sinä teit heidät meidän vertaisiksemme, jotka olemme kantaneet päivän kuorman ja helteen''.'),
(1692749,58,40,20,13,'Niin hän vastasi eräälle heistä ja sanoi: ''Ystäväni, en minä tee sinulle vääryyttä; etkö sopinut minun kanssani denarista?'),
(1692750,58,40,20,14,'Ota omasi ja mene. Mutta minä tahdon tälle viimeiselle antaa saman verran kuin sinullekin.'),
(1692751,58,40,20,15,'Enkö saa tehdä omallani, mitä tahdon? Vai onko silmäsi nurja sentähden, että minä olen hyvä?'''),
(1692752,58,40,20,16,'Näin viimeiset tulevat ensimmäisiksi ja ensimmäiset viimeisiksi."'),
(1692753,58,40,20,17,'Ja kun Jeesus lähti kulkemaan ylös Jerusalemiin, otti hän ne kaksitoista erilleen ja sanoi matkalla heille:'),
(1692754,58,40,20,18,'"Katso, me menemme ylös Jerusalemiin, ja Ihmisen Poika annetaan ylipappien ja kirjanoppineitten käsiin, ja he tuomitsevat hänet kuolemaan'),
(1692755,58,40,20,19,'ja antavat hänet pakanoille pilkattavaksi ja ruoskittavaksi ja ristiinnaulittavaksi, ja kolmantena päivänä hän on nouseva ylös".'),
(1692756,58,40,20,20,'Silloin Sebedeuksen poikain äiti tuli poikineen hänen tykönsä ja kumarsi häntä, aikoen anoa häneltä jotakin.'),
(1692757,58,40,20,21,'Niin hän sanoi vaimolle: "Mitä tahdot?" Tämä sanoi hänelle: "Sano, että nämä minun kaksi poikaani saavat istua, toinen sinun oikealla ja toinen vasemmalla puolellasi, sinun valtakunnassasi".'),
(1692758,58,40,20,22,'Mutta Jeesus vastasi ja sanoi: "Te ette tiedä, mitä anotte. Voitteko juoda sen maljan, jonka minä olen juova?" He sanoivat hänelle: "Voimme".'),
(1692759,58,40,20,23,'Hän sanoi heille: "Minun maljani te tosin juotte, mutta minun oikealla ja vasemmalla puolellani istuminen ei ole minun annettavissani, vaan se annetaan niille, joille minun Isäni on sen valmistanut".'),
(1692760,58,40,20,24,'Kun ne kymmenen sen kuulivat, närkästyivät he näihin kahteen veljekseen.'),
(1692761,58,40,20,25,'Mutta Jeesus kutsui heidät tykönsä ja sanoi: "Te tiedätte, että kansojen ruhtinaat herroina niitä hallitsevat, ja että mahtavat käyttävät valtaansa niitä kohtaan.'),
(1692762,58,40,20,26,'Näin älköön olko teillä keskenänne, vaan joka teidän keskuudessanne tahtoo suureksi tulla, se olkoon teidän palvelijanne,'),
(1692763,58,40,20,27,'ja joka teidän keskuudessanne tahtoo olla ensimmäinen, se olkoon teidän orjanne;'),
(1692764,58,40,20,28,'niinkuin ei Ihmisen Poikakaan tullut palveltavaksi, vaan palvelemaan ja antamaan henkensä lunnaiksi monen edestä."'),
(1692765,58,40,20,29,'Ja heidän lähtiessään Jerikosta seurasi häntä suuri kansan paljous.'),
(1692766,58,40,20,30,'Ja katso, kaksi sokeaa istui tien vieressä; ja kun he kuulivat, että Jeesus kulki ohitse, huusivat he sanoen: "Herra, Daavidin poika, armahda meitä".'),
(1692767,58,40,20,31,'Niin kansa nuhteli heitä saadakseen heidät vaikenemaan; mutta he huusivat sitä enemmän sanoen: "Herra, Daavidin poika, armahda meitä".'),
(1692768,58,40,20,32,'Silloin Jeesus seisahtui ja kutsui heidät tykönsä ja sanoi: "Mitä tahdotte, että minä teille tekisin?"'),
(1692769,58,40,20,33,'He sanoivat hänelle: "Herra, että meidän silmämme aukenisivat".'),
(1692770,58,40,20,34,'Niin Jeesuksen tuli heitä sääli, ja hän kosketti heidän silmiänsä, ja kohta he saivat näkönsä ja seurasivat häntä.'),
(1692771,58,40,21,1,'Ja kun he lähestyivät Jerusalemia ja saapuivat Beetfageen, Öljymäelle, silloin Jeesus lähetti kaksi opetuslasta'),
(1692772,58,40,21,2,'ja sanoi heille: "Menkää kylään, joka on edessänne, niin te kohta löydätte aasintamman sidottuna ja varsan sen kanssa; päästäkää ne ja tuokaa minulle.'),
(1692773,58,40,21,3,'Ja jos joku teille jotakin sanoo, niin vastatkaa: ''Herra tarvitsee niitä''; ja kohta hän lähettää ne."'),
(1692774,58,40,21,4,'Mutta tämä tapahtui, että kävisi toteen, mikä on puhuttu profeetan kautta, joka sanoo:'),
(1692775,58,40,21,5,'"Sanokaa tytär Siionille: ''Katso, sinun kuninkaasi tulee sinulle hiljaisena ja ratsastaen aasilla, ikeenalaisen aasin varsalla''."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692776,58,40,21,6,'Niin opetuslapset menivät ja tekivät, niinkuin Jeesus oli heitä käskenyt,'),
(1692777,58,40,21,7,'ja toivat aasintamman varsoineen ja panivat niiden selkään vaatteensa, ja hän istuutui niiden päälle.'),
(1692778,58,40,21,8,'Ja suurin osa kansasta levitti vaatteensa tielle, ja toiset karsivat oksia puista ja hajottivat tielle.'),
(1692779,58,40,21,9,'Ja kansanjoukot, jotka kulkivat hänen edellään ja jotka seurasivat, huusivat sanoen: "Hoosianna Daavidin pojalle! Siunattu olkoon hän, joka tulee Herran nimeen. Hoosianna korkeuksissa!"'),
(1692780,58,40,21,10,'Ja kun hän tuli Jerusalemiin, joutui koko kaupunki liikkeelle ja sanoi: "Kuka tämä on?"'),
(1692781,58,40,21,11,'Niin kansa sanoi: "Tämä on se profeetta, Jeesus, Galilean Nasaretista".'),
(1692782,58,40,21,12,'Ja Jeesus meni pyhäkköön; ja hän ajoi ulos kaikki, jotka myivät ja ostivat pyhäkössä, ja kaatoi kumoon rahanvaihtajain pöydät ja kyyhkysten myyjäin istuimet.'),
(1692783,58,40,21,13,'Ja hän sanoi heille: "Kirjoitettu on: ''Minun huoneeni pitää kutsuttaman rukoushuoneeksi'', mutta te teette siitä ryövärien luolan."'),
(1692784,58,40,21,14,'Ja hänen tykönsä pyhäkössä tuli sokeita ja rampoja, ja hän paransi heidät.'),
(1692785,58,40,21,15,'Mutta kun ylipapit ja kirjanoppineet näkivät ne ihmeet, joita hän teki, ja lapset, jotka huusivat pyhäkössä ja sanoivat: "Hoosianna Daavidin pojalle", niin he närkästyivät'),
(1692786,58,40,21,16,'ja sanoivat hänelle: "Kuuletko, mitä nämä sanovat?" Niin Jeesus sanoi heille: "Kuulen; ettekö ole koskaan lukeneet: ''Lasten ja imeväisten suusta sinä olet valmistanut itsellesi kiitoksen''?"'),
(1692787,58,40,21,17,'Ja hän jätti heidät ja meni ulos kaupungista Betaniaan ja oli siellä yötä.'),
(1692788,58,40,21,18,'Kun hän varhain aamulla palasi kaupunkiin, oli hänen nälkä.'),
(1692789,58,40,21,19,'Ja nähdessään tien vieressä viikunapuun hän meni sen luo, mutta ei löytänyt siitä muuta kuin pelkkiä lehtiä; ja hän sanoi sille: "Älköön sinusta ikinä enää hedelmää kasvako". Ja kohta viikunapuu kuivettui.'),
(1692790,58,40,21,20,'Kun opetuslapset tämän näkivät, ihmettelivät he ja sanoivat: "Kuinka viikunapuu niin äkisti kuivettui?"'),
(1692791,58,40,21,21,'Jeesus vastasi ja sanoi heille: "Totisesti minä sanon teille: jos teillä olisi uskoa ettekä epäilisi, niin ette ainoastaan voisi tehdä sitä, mikä viikunapuussa tapahtui, vaan vieläpä, jos sanoisitte tälle vuorelle: ''Kohoa ja heittäydy mereen'', niin se tapahtuisi.'),
(1692792,58,40,21,22,'Ja kaiken, mitä te anotte rukouksessa, uskoen, te saatte."'),
(1692793,58,40,21,23,'Ja kun hän oli mennyt pyhäkköön, tulivat hänen opettaessaan ylipapit ja kansan vanhimmat hänen luoksensa ja sanoivat: "Millä vallalla sinä näitä teet? Ja kuka sinulle on antanut tämän vallan?"'),
(1692794,58,40,21,24,'Jeesus vastasi ja sanoi heille: "Minä myös teen teille yhden kysymyksen; jos te minulle siihen vastaatte, niin minäkin sanon teille, millä vallalla minä näitä teen.'),
(1692795,58,40,21,25,'Mistä Johanneksen kaste oli? Taivaastako vai ihmisistä?" Niin he neuvottelivat keskenänsä sanoen: "Jos sanomme: ''Taivaasta'', niin hän sanoo meille: ''Miksi ette siis uskoneet häntä?'''),
(1692796,58,40,21,26,'Mutta jos sanomme: ''Ihmisistä'', niin meidän täytyy peljätä kansaa, sillä kaikki pitävät Johannesta profeettana."'),
(1692797,58,40,21,27,'Ja he vastasivat Jeesukselle ja sanoivat: "Emme tiedä". Niin hänkin sanoi heille: "Niinpä en minäkään sano teille, millä vallalla minä näitä teen.'),
(1692798,58,40,21,28,'Mutta miten teistä on? Miehellä oli kaksi poikaa; ja hän meni ensimmäisen luo ja sanoi: ''Poikani, mene tänään tekemään työtä minun viinitarhaani''.'),
(1692799,58,40,21,29,'Tämä vastasi ja sanoi: ''En tahdo''; mutta jäljestäpäin hän katui ja meni.'),
(1692800,58,40,21,30,'Niin hän meni toisen luo ja sanoi samoin. Tämä taas vastasi ja sanoi: ''Minä menen, herra'', mutta ei mennytkään.'),
(1692801,58,40,21,31,'Kumpi näistä kahdesta teki isänsä tahdon?" He sanoivat: "Ensimmäinen". Jeesus sanoi heille: "Totisesti minä sanon teille: publikaanit ja portot menevät ennen teitä Jumalan valtakuntaan.'),
(1692802,58,40,21,32,'Sillä Johannes tuli teidän tykönne vanhurskauden tietä, ja te ette uskoneet häntä, mutta publikaanit ja portot uskoivat häntä; ja vaikka te sen näitte, ette jäljestäpäinkään katuneet, niin että olisitte häntä uskoneet.'),
(1692803,58,40,21,33,'Kuulkaa toinen vertaus: Oli perheenisäntä, joka istutti viinitarhan ja teki aidan sen ympärille ja kaivoi siihen viinikuurnan ja rakensi tornin; ja hän vuokrasi sen viinitarhureille ja matkusti muille maille.'),
(1692804,58,40,21,34,'Ja kun hedelmäin aika lähestyi, lähetti hän palvelijoitansa viinitarhurien luokse perimään hänelle tulevat hedelmät.'),
(1692805,58,40,21,35,'Mutta viinitarhurit ottivat kiinni hänen palvelijansa; minkä he pieksivät, minkä tappoivat, minkä kivittivät.'),
(1692806,58,40,21,36,'Vielä hän lähetti toisia palvelijoita, useampia kuin ensimmäiset; ja näille he tekivät samoin.'),
(1692807,58,40,21,37,'Mutta viimein hän lähetti heidän luokseen poikansa sanoen: ''Minun poikaani he kavahtavat''.'),
(1692808,58,40,21,38,'Mutta kun viinitarhurit näkivät pojan, sanoivat he keskenänsä: ''Tämä on perillinen; tulkaa, tappakaamme hänet, niin me saamme hänen perintönsä''.'),
(1692809,58,40,21,39,'Ja he ottivat hänet kiinni ja heittivät ulos viinitarhasta ja tappoivat.'),
(1692810,58,40,21,40,'Kun viinitarhan herra tulee, mitä hän tekee noille viinitarhureille?"'),
(1692811,58,40,21,41,'He sanoivat hänelle: "Nuo pahat hän pahoin tuhoaa ja vuokraa viinitarhan toisille viinitarhureille, jotka antavat hänelle hedelmät ajallansa".'),
(1692812,58,40,21,42,'Jeesus sanoi heille: "Ettekö ole koskaan lukeneet kirjoituksista: ''Se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi; Herralta tämä on tullut ja on ihmeellinen meidän silmissämme''?'),
(1692813,58,40,21,43,'Sentähden minä sanon teille: Jumalan valtakunta otetaan teiltä pois ja annetaan kansalle, joka tekee sen hedelmiä.'),
(1692814,58,40,21,44,'Ja joka tähän kiveen kaatuu, se ruhjoutuu, mutta jonka päälle se kaatuu, sen se murskaa."'),
(1692815,58,40,21,45,'Kun ylipapit ja fariseukset kuulivat nämä hänen vertauksensa, ymmärsivät he, että hän puhui heistä.'),
(1692816,58,40,21,46,'Ja he olisivat tahtoneet ottaa hänet kiinni, mutta pelkäsivät kansaa, koska se piti häntä profeettana.'),
(1692817,58,40,22,1,'Ja Jeesus rupesi taas puhumaan heille vertauksilla ja sanoi:'),
(1692818,58,40,22,2,'"Taivasten valtakunta on verrattava kuninkaaseen, joka laittoi häät pojallensa.'),
(1692819,58,40,22,3,'Ja hän lähetti palvelijansa kutsumaan häihin kutsuvieraita, mutta nämä eivät tahtoneet tulla.'),
(1692820,58,40,22,4,'Vielä hän lähetti toisia palvelijoita lausuen: ''Sanokaa kutsutuille: Katso, minä olen valmistanut ateriani, minun härkäni ja syöttilääni ovat teurastetut, ja kaikki on valmiina; tulkaa häihin''.'),
(1692821,58,40,22,5,'Mutta he eivät siitä välittäneet, vaan menivät pois, mikä pellolleen, mikä kaupoilleen;'),
(1692822,58,40,22,6,'ja toiset ottivat kiinni hänen palvelijansa, pitelivät pahoin ja tappoivat.'),
(1692823,58,40,22,7,'Mutta kuningas vihastui ja lähetti sotajoukkonsa ja tuhosi nuo murhamiehet ja poltti heidän kaupunkinsa.'),
(1692824,58,40,22,8,'Sitten hän sanoi palvelijoillensa: ''Häät ovat valmistetut, mutta kutsutut eivät olleet arvollisia.'),
(1692825,58,40,22,9,'Menkää siis teiden risteyksiin ja kutsukaa häihin, keitä tapaatte.''');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692826,58,40,22,10,'Ja palvelijat menivät ulos teille ja kokosivat kaikki, keitä vain tapasivat, sekä pahat että hyvät, ja häähuone tuli täyteen pöytävieraita.'),
(1692827,58,40,22,11,'Mutta kun kuningas meni katsomaan pöytävieraita, näki hän siellä miehen, joka ei ollut puettu häävaatteisiin.'),
(1692828,58,40,22,12,'Ja hän sanoi hänelle: ''Ystävä, kuinka sinä olet tullut tänne sisälle, vaikka sinulla ei ole häävaatteita?'' Mutta hän jäi sanattomaksi.'),
(1692829,58,40,22,13,'Silloin kuningas sanoi palvelijoille: ''Sitokaa hänen jalkansa ja kätensä ja heittäkää hänet ulos pimeyteen''. Siellä on oleva itku ja hammasten kiristys.'),
(1692830,58,40,22,14,'Sillä monet ovat kutsutut, mutta harvat valitut."'),
(1692831,58,40,22,15,'Silloin fariseukset menivät ja neuvottelivat, kuinka saisivat hänet sanoissa solmituksi.'),
(1692832,58,40,22,16,'Ja he lähettivät hänen luoksensa opetuslapsensa herodilaisten kanssa sanomaan: "Opettaja, me tiedämme, että sinä olet totinen ja opetat Jumalan tietä totuudessa, kenestäkään välittämättä, sillä sinä et katso henkilöön.'),
(1692833,58,40,22,17,'Sano siis meille: miten arvelet? Onko luvallista antaa keisarille veroa vai ei?"'),
(1692834,58,40,22,18,'Mutta Jeesus ymmärsi heidän pahuutensa ja sanoi: "Miksi kiusaatte minua, te ulkokullatut?'),
(1692835,58,40,22,19,'Näyttäkää minulle veroraha." Niin he toivat hänelle denarin.'),
(1692836,58,40,22,20,'Hän sanoi heille: "Kenen kuva ja päällekirjoitus tämä on?"'),
(1692837,58,40,22,21,'He vastasivat: "Keisarin". Silloin hän sanoi heille: "Antakaa siis keisarille, mikä keisarin on, ja Jumalalle, mikä Jumalan on".'),
(1692838,58,40,22,22,'Kun he sen kuulivat, ihmettelivät he ja jättivät hänet ja menivät pois.'),
(1692839,58,40,22,23,'Sinä päivänä tuli hänen luoksensa saddukeuksia, jotka sanovat, ettei ylösnousemusta ole, ja he kysyivät häneltä'),
(1692840,58,40,22,24,'sanoen: "Opettaja, Mooses on sanonut: ''Jos joku kuolee lapsetonna, niin hänen veljensä naikoon hänen vaimonsa ja herättäköön siemenen veljelleen''.'),
(1692841,58,40,22,25,'Keskuudessamme oli seitsemän veljestä. Ensimmäinen otti vaimon ja kuoli; ja koska hänellä ei ollut jälkeläistä, jätti hän vaimonsa veljelleen.'),
(1692842,58,40,22,26,'Niin myös toinen ja kolmas, ja samoin kaikki seitsemän.'),
(1692843,58,40,22,27,'Viimeiseksi kaikista kuoli vaimo.'),
(1692844,58,40,22,28,'Kenen vaimo noista seitsemästä hän siis ylösnousemuksessa on oleva? Sillä kaikkien vaimona hän on ollut."'),
(1692845,58,40,22,29,'Jeesus vastasi ja sanoi heille: "Te eksytte, koska te ette tunne kirjoituksia ettekä Jumalan voimaa.'),
(1692846,58,40,22,30,'Sillä ylösnousemuksessa ei naida eikä mennä miehelle; vaan he ovat niinkuin enkelit taivaassa.'),
(1692847,58,40,22,31,'Mutta mitä kuolleitten ylösnousemukseen tulee, ettekö ole lukeneet, mitä Jumala on puhunut teille, sanoen:'),
(1692848,58,40,22,32,'''Minä olen Aabrahamin Jumala ja Iisakin Jumala ja Jaakobin Jumala''? Ei hän ole kuolleitten Jumala, vaan elävien."'),
(1692849,58,40,22,33,'Ja sen kuullessaan kansa hämmästyi hänen oppiansa.'),
(1692850,58,40,22,34,'Mutta kun fariseukset kuulivat, että hän oli tukkinut saddukeuksilta suun, kokoontuivat he yhteen;'),
(1692851,58,40,22,35,'ja eräs heistä, joka oli lainoppinut, kysyi häneltä kiusaten:'),
(1692852,58,40,22,36,'"Opettaja, mikä on suurin käsky laissa?"'),
(1692853,58,40,22,37,'Niin Jeesus sanoi hänelle: "''Rakasta Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi ja kaikesta mielestäsi''.'),
(1692854,58,40,22,38,'Tämä on suurin ja ensimmäinen käsky.'),
(1692855,58,40,22,39,'Toinen, tämän vertainen, on: ''Rakasta lähimmäistäsi niinkuin itseäsi''.'),
(1692856,58,40,22,40,'Näissä kahdessa käskyssä riippuu kaikki laki ja profeetat."'),
(1692857,58,40,22,41,'Ja fariseusten ollessa koolla Jeesus kysyi heiltä'),
(1692858,58,40,22,42,'sanoen: "Mitä arvelette Kristuksesta? Kenen poika hän on?" He sanoivat hänelle: "Daavidin".'),
(1692859,58,40,22,43,'Hän sanoi heille: "Kuinka sitten Daavid Hengessä kutsuu häntä Herraksi, sanoen:'),
(1692860,58,40,22,44,'''Herra sanoi minun Herralleni: Istu minun oikealle puolelleni, kunnes minä panen sinun vihollisesi sinun jalkojesi alle''.'),
(1692861,58,40,22,45,'Jos siis Daavid kutsuu häntä Herraksi, kuinka hän on hänen poikansa?"'),
(1692862,58,40,22,46,'Ja kukaan ei voinut vastata hänelle sanaakaan; eikä siitä päivästä lähtien yksikään enää rohjennut kysyä häneltä mitään.'),
(1692863,58,40,23,1,'Silloin Jeesus puhui kansalle ja opetuslapsilleen'),
(1692864,58,40,23,2,'sanoen: "Mooseksen istuimella istuvat kirjanoppineet ja fariseukset.'),
(1692865,58,40,23,3,'Sentähden, kaikki, mitä he sanovat teille, se tehkää ja pitäkää; mutta heidän tekojensa mukaan älkää tehkö, sillä he sanovat, mutta eivät tee.'),
(1692866,58,40,23,4,'He sitovat kokoon raskaita ja vaikeasti kannettavia taakkoja ja panevat ne ihmisten hartioille, mutta itse he eivät tahdo niitä sormellaankaan liikuttaa.'),
(1692867,58,40,23,5,'Ja kaikki tekonsa he tekevät sitä varten, että ihmiset heitä katselisivat. He tekevät raamatunlausekotelonsa leveiksi ja vaippansa tupsut suuriksi'),
(1692868,58,40,23,6,'ja rakastavat ensimmäistä sijaa pidoissa ja etumaisia istuimia synagoogissa,'),
(1692869,58,40,23,7,'ja tahtovat mielellään, että heitä tervehditään toreilla, ja että ihmiset kutsuvat heitä nimellä ''rabbi''.'),
(1692870,58,40,23,8,'Mutta te älkää antako kutsua itseänne rabbiksi, sillä yksi on teidän opettajanne, ja te olette kaikki veljiä.'),
(1692871,58,40,23,9,'Ja isäksenne älkää kutsuko ketään maan päällä, sillä yksi on teidän Isänne, hän, joka on taivaissa.'),
(1692872,58,40,23,10,'Älkääkä antako kutsua itseänne mestareiksi, sillä yksi on teidän mestarinne, Kristus.'),
(1692873,58,40,23,11,'Vaan joka teistä on suurin, se olkoon teidän palvelijanne.'),
(1692874,58,40,23,12,'Mutta joka itsensä ylentää, se alennetaan; ja joka itsensä alentaa, se ylennetään.'),
(1692875,58,40,23,13,'Mutta voi teitä, kirjanoppineet ja fariseukset, te ulkokullatut, kun suljette taivasten valtakunnan ihmisiltä! Sillä itse te ette mene sisälle, ettekä salli meneväisten sisälle mennä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692876,58,40,23,15,'Voi teitä, kirjanoppineet ja fariseukset, te ulkokullatut, kun te kierrätte meret ja mantereet tehdäksenne yhden käännynnäisen; ja kun joku on siksi tullut, niin teette hänestä helvetin lapsen, kahta vertaa pahemman, kuin te itse olette!'),
(1692877,58,40,23,16,'Voi teitä, te sokeat taluttajat, jotka sanotte: ''Jos joku vannoo temppelin kautta, niin se ei ole mitään; mutta jos joku vannoo temppelin kullan kautta, niin hän on valaansa sidottu''!'),
(1692878,58,40,23,17,'Te tyhmät ja sokeat! Kumpi on suurempi, kultako vai temppeli, joka kullan pyhittää?'),
(1692879,58,40,23,18,'Ja: ''Jos joku vannoo alttarin kautta, niin se ei ole mitään; mutta jos joku vannoo sen päällä olevan uhrilahjan kautta, niin hän on valaansa sidottu''.'),
(1692880,58,40,23,19,'Te sokeat! Kumpi on suurempi, uhrilahjako vai alttari, joka uhrilahjan pyhittää?'),
(1692881,58,40,23,20,'Sentähden, joka vannoo alttarin kautta, vannoo sen kautta ja kaiken kautta, mitä sen päällä on.'),
(1692882,58,40,23,21,'Ja joka vannoo temppelin kautta, vannoo sen kautta ja hänen kauttansa, joka siinä asuu.'),
(1692883,58,40,23,22,'Ja joka vannoo taivaan kautta, vannoo Jumalan valtaistuimen kautta ja hänen kauttansa, joka sillä istuu.'),
(1692884,58,40,23,23,'Voi teitä, kirjanoppineet ja fariseukset, te ulkokullatut, kun te annatte kymmenykset mintuista ja tilleistä ja kuminoista, mutta jätätte sikseen sen, mikä laissa on tärkeintä: oikeuden ja laupeuden ja uskollisuuden! Näitä tulisi noudattaa, eikä noitakaan sikseen jättää.'),
(1692885,58,40,23,24,'Te sokeat taluttajat, jotka siivilöitte hyttysen, mutta nielette kamelin!'),
(1692886,58,40,23,25,'Voi teitä, kirjanoppineet ja fariseukset, te ulkokullatut, kun te puhdistatte maljan ja vadin ulkopuolen, mutta sisältä ne ovat täynnä ryöstöä ja hillittömyyttä!'),
(1692887,58,40,23,26,'Sinä sokea fariseus, puhdista ensin maljan sisus, että sen ulkopuolikin tulisi puhtaaksi!'),
(1692888,58,40,23,27,'Voi teitä, kirjanoppineet ja fariseukset, te ulkokullatut, kun te olette valkeiksi kalkittujen hautojen kaltaisia: ulkoa ne kyllä näyttävät kauniilta, mutta ovat sisältä täynnä kuolleitten luita ja kaikkea saastaa!'),
(1692889,58,40,23,28,'Samoin tekin ulkoa kyllä näytätte ihmisten silmissä hurskailta, mutta sisältä te olette täynnä ulkokultaisuutta ja laittomuutta.'),
(1692890,58,40,23,29,'Voi teitä, kirjanoppineet ja fariseukset, te ulkokullatut, kun te rakennatte profeettain hautoja ja kaunistatte vanhurskasten hautakammioita,'),
(1692891,58,40,23,30,'ja sanotte: ''Jos me olisimme eläneet isäimme päivinä, emme olisi olleet osallisia heidän kanssaan profeettain vereen''!'),
(1692892,58,40,23,31,'Niin te siis todistatte itsestänne, että olette niiden lapsia, jotka tappoivat profeetat.'),
(1692893,58,40,23,32,'Täyttäkää siis te isäinne mitta.'),
(1692894,58,40,23,33,'Te käärmeet, te kyykäärmeitten sikiöt, kuinka te pääsisitte helvetin tuomiota pakoon?'),
(1692895,58,40,23,34,'Sentähden, katso, minä lähetän teidän tykönne profeettoja ja viisaita ja kirjanoppineita. Muutamat heistä te tapatte ja ristiinnaulitsette, ja toisia heistä te ruoskitte synagoogissanne ja vainoatte kaupungista kaupunkiin;'),
(1692896,58,40,23,35,'että teidän päällenne tulisi kaikki se vanhurskas veri, joka maan päällä on vuodatettu vanhurskaan Aabelin verestä Sakariaan, Barakiaan pojan, vereen asti, jonka te tapoitte temppelin ja alttarin välillä.'),
(1692897,58,40,23,36,'Totisesti minä sanon teille: tämä kaikki on tuleva tämän sukupolven päälle.'),
(1692898,58,40,23,37,'Jerusalem, Jerusalem, sinä, joka tapat profeetat ja kivität ne, jotka ovat sinun tykösi lähetetyt, kuinka usein minä olenkaan tahtonut koota sinun lapsesi, niinkuin kana kokoaa poikansa siipiensä alle! Mutta te ette ole tahtoneet.'),
(1692899,58,40,23,38,'Katso, ''teidän huoneenne on jäävä hyljätyksi''.'),
(1692900,58,40,23,39,'Sillä minä sanon teille: tästedes te ette näe minua, ennenkuin sanotte: ''Siunattu olkoon hän, joka tulee Herran nimeen''."'),
(1692901,58,40,24,1,'Ja Jeesus lähti ulos pyhäköstä ja meni pois; ja hänen opetuslapsensa tulivat hänen tykönsä näyttämään hänelle pyhäkön rakennuksia.'),
(1692902,58,40,24,2,'Niin hän vastasi ja sanoi heille: "Ettekö näe näitä kaikkia? Totisesti minä sanon teille: tähän ei ole jäävä kiveä kiven päälle, maahan jaottamatta."'),
(1692903,58,40,24,3,'Ja kun hän istui Öljymäellä, tulivat opetuslapset erikseen hänen tykönsä ja sanoivat: "Sano meille: milloin se tapahtuu, ja mikä on sinun tulemuksesi ja maailman lopun merkki?"'),
(1692904,58,40,24,4,'Silloin Jeesus vastasi ja sanoi heille: "Katsokaa, ettei kukaan teitä eksytä.'),
(1692905,58,40,24,5,'Sillä monta tulee minun nimessäni sanoen: ''Minä olen Kristus'', ja he eksyttävät monta.'),
(1692906,58,40,24,6,'Ja te saatte kuulla sotien melskettä ja sanomia sodista; katsokaa, ettette peljästy. Sillä näin täytyy tapahtua, mutta tämä ei ole vielä loppu.'),
(1692907,58,40,24,7,'Sillä kansa nousee kansaa vastaan ja valtakunta valtakuntaa vastaan, ja nälänhätää ja maanjäristyksiä tulee monin paikoin.'),
(1692908,58,40,24,8,'Mutta kaikki tämä on synnytystuskien alkua.'),
(1692909,58,40,24,9,'Silloin teidät annetaan vaivaan, ja teitä tapetaan, ja te joudutte kaikkien kansojen vihattaviksi minun nimeni tähden.'),
(1692910,58,40,24,10,'Ja silloin monet lankeavat pois, ja he antavat toisensa alttiiksi ja vihaavat toinen toistaan.'),
(1692911,58,40,24,11,'Ja monta väärää profeettaa nousee, ja he eksyttävät monta.'),
(1692912,58,40,24,12,'Ja sentähden, että laittomuus pääsee valtaan, kylmenee useimpien rakkaus.'),
(1692913,58,40,24,13,'Mutta joka vahvana pysyy loppuun asti, se pelastuu.'),
(1692914,58,40,24,14,'Ja tämä valtakunnan evankeliumi pitää saarnattaman kaikessa maailmassa, todistukseksi kaikille kansoille; ja sitten tulee loppu.'),
(1692915,58,40,24,15,'Kun te siis näette hävityksen kauhistuksen, josta on puhuttu profeetta Danielin kautta, seisovan pyhässä paikassa - joka tämän lukee, se tarkatkoon -'),
(1692916,58,40,24,16,'silloin ne, jotka Juudeassa ovat, paetkoot vuorille;'),
(1692917,58,40,24,17,'joka on katolla, älköön astuko alas noutamaan, mitä hänen huoneessansa on,'),
(1692918,58,40,24,18,'ja joka on pellolla, älköön palatko takaisin noutamaan vaippaansa.'),
(1692919,58,40,24,19,'Voi raskaita ja imettäväisiä niinä päivinä!'),
(1692920,58,40,24,20,'Mutta rukoilkaa, ettei teidän pakonne tapahtuisi talvella eikä sapattina.'),
(1692921,58,40,24,21,'Sillä silloin on oleva suuri ahdistus, jonka kaltaista ei ole ollut maailman alusta hamaan tähän asti eikä milloinkaan tule.'),
(1692922,58,40,24,22,'Ja ellei niitä päiviä olisi lyhennetty, ei mikään liha pelastuisi; mutta valittujen tähden ne päivät lyhennetään.'),
(1692923,58,40,24,23,'Jos silloin joku sanoo teille: ''Katso, täällä on Kristus'', tahi: ''Tuolla'', niin älkää uskoko.'),
(1692924,58,40,24,24,'Sillä vääriä kristuksia ja vääriä profeettoja nousee, ja he tekevät suuria tunnustekoja ja ihmeitä, niin että eksyttävät, jos mahdollista, valitutkin.'),
(1692925,58,40,24,25,'Katso, minä olen sen teille edeltä sanonut.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692926,58,40,24,26,'Sentähden, jos teille sanotaan: ''Katso, hän on erämaassa'', niin älkää menkö sinne, tahi: ''Katso, hän on kammiossa'', niin älkää uskoko.'),
(1692927,58,40,24,27,'Sillä niinkuin salama leimahtaa idästä ja näkyy hamaan länteen, niin on oleva Ihmisen Pojan tulemus.'),
(1692928,58,40,24,28,'Missä raato on, sinne kotkat kokoontuvat.'),
(1692929,58,40,24,29,'Mutta kohta niiden päivien ahdistuksen jälkeen aurinko pimenee, eikä kuu anna valoansa, ja tähdet putoavat taivaalta, ja taivaitten voimat järkkyvät.'),
(1692930,58,40,24,30,'Ja silloin Ihmisen Pojan merkki näkyy taivaalla, ja silloin kaikki maan sukukunnat parkuvat; ja he näkevät Ihmisen Pojan tulevan taivaan pilvien päällä suurella voimalla ja kirkkaudella.'),
(1692931,58,40,24,31,'Ja hän lähettää enkelinsä suuren pasunan pauhatessa, ja he kokoavat hänen valittunsa neljältä ilmalta, taivasten ääristä hamaan toisiin ääriin.'),
(1692932,58,40,24,32,'Mutta oppikaa viikunapuusta vertaus: kun sen oksa jo on tuore ja lehdet puhkeavat, niin te tiedätte, että kesä on lähellä.'),
(1692933,58,40,24,33,'Samoin te myös, kun näette tämän kaiken, tietäkää, että se on lähellä, oven edessä.'),
(1692934,58,40,24,34,'Totisesti minä sanon teille: tämä sukupolvi ei katoa, ennenkuin kaikki nämä tapahtuvat.'),
(1692935,58,40,24,35,'Taivas ja maa katoavat, mutta minun sanani eivät koskaan katoa.'),
(1692936,58,40,24,36,'Mutta siitä päivästä ja hetkestä ei tiedä kukaan, eivät taivasten enkelit, eikä myöskään Poika, vaan Isä yksin.'),
(1692937,58,40,24,37,'Sillä niinkuin oli Nooan päivinä, niin on Ihmisen Pojan tulemus oleva.'),
(1692938,58,40,24,38,'Sillä niinkuin ihmiset olivat niinä päivinä ennen vedenpaisumusta: söivät ja joivat, naivat ja naittivat, aina siihen päivään asti, jona Nooa meni arkkiin,'),
(1692939,58,40,24,39,'eivätkä tienneet, ennenkuin vedenpaisumus tuli ja vei heidät kaikki; niin on myös Ihmisen Pojan tulemus oleva.'),
(1692940,58,40,24,40,'Silloin on kaksi miestä pellolla; toinen korjataan talteen, ja toinen jätetään.'),
(1692941,58,40,24,41,'Kaksi naista on jauhamassa käsikivillä; toinen korjataan talteen, ja toinen jätetään.'),
(1692942,58,40,24,42,'Valvokaa siis, sillä ette tiedä, minä päivänä teidän Herranne tulee.'),
(1692943,58,40,24,43,'Mutta se tietäkää: jos perheenisäntä tietäisi, millä yövartiolla varas tulee, totta hän valvoisi, eikä sallisi taloonsa murtauduttavan.'),
(1692944,58,40,24,44,'Sentähden olkaa tekin valmiit, sillä sinä hetkenä, jona ette luule, Ihmisen Poika tulee.'),
(1692945,58,40,24,45,'Kuka siis on se uskollinen ja ymmärtäväinen palvelija, jonka hänen herransa on asettanut pitämään huolta palvelusväestään, antamaan heille ruokaa ajallansa?'),
(1692946,58,40,24,46,'Autuas se palvelija, jonka hänen herransa tullessaan havaitsee näin tekevän!'),
(1692947,58,40,24,47,'Totisesti minä sanon teille: hän asettaa hänet kaiken omaisuutensa hoitajaksi.'),
(1692948,58,40,24,48,'Mutta jos paha palvelija sanoo sydämessään: ''Minun herrani viipyy'','),
(1692949,58,40,24,49,'ja rupeaa lyömään kanssapalvelijoitaan ja syö ja juo juopuneiden kanssa,'),
(1692950,58,40,24,50,'niin sen palvelijan herra tulee päivänä, jona hän ei odota, ja hetkenä, jota hän ei arvaa,'),
(1692951,58,40,24,51,'ja hakkaa hänet kappaleiksi ja määrää hänelle saman osan kuin ulkokullatuille. Siellä on oleva itku ja hammasten kiristys."'),
(1692952,58,40,25,1,'"Silloin on taivasten valtakunta oleva kymmenen neitsyen kaltainen, jotka ottivat lamppunsa ja lähtivät ylkää vastaan.'),
(1692953,58,40,25,2,'Mutta viisi heistä oli tyhmää ja viisi ymmärtäväistä.'),
(1692954,58,40,25,3,'Tyhmät ottivat lamppunsa, mutta eivät ottaneet öljyä mukaansa.'),
(1692955,58,40,25,4,'Mutta ymmärtäväiset ottivat öljyä astioihinsa ynnä lamppunsa.'),
(1692956,58,40,25,5,'Yljän viipyessä tuli heille kaikille uni, ja he nukkuivat.'),
(1692957,58,40,25,6,'Mutta yösydännä kuului huuto: ''Katso, ylkä tulee! Menkää häntä vastaan.'''),
(1692958,58,40,25,7,'Silloin kaikki nämä neitsyet nousivat ja laittoivat lamppunsa kuntoon.'),
(1692959,58,40,25,8,'Ja tyhmät sanoivat ymmärtäväisille: ''Antakaa meille öljyänne, sillä meidän lamppumme sammuvat''.'),
(1692960,58,40,25,9,'Mutta ymmärtäväiset vastasivat ja sanoivat: ''Emme voi, se ei riitä meille ja teille. Menkää ennemmin myyjäin luo ostamaan itsellenne.'''),
(1692961,58,40,25,10,'Mutta heidän lähdettyään ostamaan ylkä tuli; ja ne, jotka olivat valmiit, menivät hänen kanssansa häihin, ja ovi suljettiin.'),
(1692962,58,40,25,11,'Ja myöhemmin toisetkin neitsyet tulivat ja sanoivat: ''Herra, Herra, avaa meille!'''),
(1692963,58,40,25,12,'Mutta hän vastasi ja sanoi: ''Totisesti minä sanon teille: minä en tunne teitä''.'),
(1692964,58,40,25,13,'Valvokaa siis, sillä ette tiedä päivää ettekä hetkeä.'),
(1692965,58,40,25,14,'Sillä tapahtuu, niinkuin tapahtui, kun mies matkusti muille maille: hän kutsui palvelijansa ja uskoi heille omaisuutensa;'),
(1692966,58,40,25,15,'yhdelle hän antoi viisi leiviskää, toiselle kaksi ja kolmannelle yhden, kullekin hänen kykynsä mukaan, ja lähti muille maille.'),
(1692967,58,40,25,16,'Se, joka oli saanut viisi leiviskää, meni kohta ja asioitsi niillä ja voitti toiset viisi leiviskää.'),
(1692968,58,40,25,17,'Samoin kaksi leiviskää saanut voitti toiset kaksi.'),
(1692969,58,40,25,18,'Mutta yhden leiviskän saanut meni pois ja kaivoi kuopan maahan ja kätki siihen herransa rahan.'),
(1692970,58,40,25,19,'Pitkän ajan kuluttua näiden palvelijain herra palasi ja ryhtyi tilintekoon heidän kanssansa.'),
(1692971,58,40,25,20,'Silloin tuli se, joka oli saanut viisi leiviskää, ja toi toiset viisi leiviskää ja sanoi: ''Herra, viisi leiviskää sinä minulle uskoit, katso, toiset viisi leiviskää minä olen voittanut''.'),
(1692972,58,40,25,21,'Hänen herransa sanoi hänelle: ''Hyvä on, sinä hyvä ja uskollinen palvelija. Vähässä sinä olet ollut uskollinen, minä panen sinut paljon haltijaksi. Mene herrasi iloon.'''),
(1692973,58,40,25,22,'Myös se, joka oli saanut kaksi leiviskää, tuli ja sanoi: ''Herra, kaksi leiviskää sinä minulle uskoit, katso, toiset kaksi leiviskää minä olen voittanut''.'),
(1692974,58,40,25,23,'Hänen herransa sanoi hänelle: ''Hyvä on, sinä hyvä ja uskollinen palvelija. Vähässä sinä olet ollut uskollinen, minä panen sinut paljon haltijaksi. Mene herrasi iloon.'''),
(1692975,58,40,25,24,'Sitten myös se, joka oli saanut yhden leiviskän, tuli ja sanoi: ''Herra, minä tiesin sinut kovaksi mieheksi; sinä leikkaat sieltä, mihin et ole kylvänyt, ja kokoat sieltä, missä et ole eloa viskannut.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1692976,58,40,25,25,'Ja peloissani minä menin ja kätkin sinun leiviskäsi maahan; katso, tässä on omasi.'''),
(1692977,58,40,25,26,'Mutta hänen herransa vastasi ja sanoi hänelle: ''Sinä paha ja laiska palvelija! Sinä tiesit minun leikkaavan sieltä, mihin en ole kylvänyt, ja kokoavan sieltä, missä en ole viskannut.'),
(1692978,58,40,25,27,'Sinun olisi siis pitänyt jättää minun rahani rahanvaihtajille, niin minä tultuani olisin saanut omani takaisin korkoineen.'),
(1692979,58,40,25,28,'Ottakaa sentähden leiviskä häneltä pois ja antakaa sille, jolla on kymmenen leiviskää.'),
(1692980,58,40,25,29,'Sillä jokaiselle, jolla on, annetaan, ja hänellä on oleva yltäkyllin; mutta jolla ei ole, siltä otetaan pois sekin, mikä hänellä on.'),
(1692981,58,40,25,30,'Ja heittäkää tuo kelvoton palvelija ulos pimeyteen; siellä on oleva itku ja hammasten kiristys.'''),
(1692982,58,40,25,31,'Mutta kun Ihmisen Poika tulee kirkkaudessaan ja kaikki enkelit hänen kanssaan, silloin hän istuu kirkkautensa valtaistuimelle.'),
(1692983,58,40,25,32,'Ja hänen eteensä kootaan kaikki kansat, ja hän erottaa toiset toisista, niinkuin paimen erottaa lampaat vuohista.'),
(1692984,58,40,25,33,'Ja hän asettaa lampaat oikealle puolelleen, mutta vuohet vasemmalle.'),
(1692985,58,40,25,34,'Silloin Kuningas sanoo oikealla puolellaan oleville: ''Tulkaa, minun Isäni siunatut, ja omistakaa se valtakunta, joka on ollut teille valmistettuna maailman perustamisesta asti.'),
(1692986,58,40,25,35,'Sillä minun oli nälkä, ja te annoitte minulle syödä; minun oli jano, ja te annoitte minulle juoda; minä olin outo, ja te otitte minut huoneeseenne;'),
(1692987,58,40,25,36,'minä olin alaston, ja te vaatetitte minut; minä sairastin, ja te kävitte minua katsomassa; minä olin vankeudessa, ja te tulitte minun tyköni.'''),
(1692988,58,40,25,37,'Silloin vanhurskaat vastaavat hänelle sanoen: ''Herra, milloin me näimme sinut nälkäisenä ja ruokimme sinua, tai janoisena ja annoimme sinulle juoda?'),
(1692989,58,40,25,38,'Ja milloin me näimme sinut outona ja otimme sinut huoneeseemme, tai alastonna ja vaatetimme sinut?'),
(1692990,58,40,25,39,'Ja milloin me näimme sinun sairastavan tai olevan vankeudessa ja tulimme sinun tykösi?'''),
(1692991,58,40,25,40,'Niin Kuningas vastaa ja sanoo heille: ''Totisesti minä sanon teille: kaikki, mitä olette tehneet yhdelle näistä minun vähimmistä veljistäni, sen te olette tehneet minulle''.'),
(1692992,58,40,25,41,'Sitten hän myös sanoo vasemmalla puolellaan oleville: ''Menkää pois minun tyköäni, te kirotut, siihen iankaikkiseen tuleen, joka on valmistettu perkeleelle ja hänen enkeleillensä.'),
(1692993,58,40,25,42,'Sillä minun oli nälkä, ja te ette antaneet minulle syödä; minun oli jano, ja te ette antaneet minulle juoda;'),
(1692994,58,40,25,43,'minä olin outo, ja te ette ottaneet minua huoneeseenne; minä olin alaston, ja te ette vaatettaneet minua; sairaana ja vankeudessa, ja te ette käyneet minua katsomassa.'''),
(1692995,58,40,25,44,'Silloin hekin vastaavat sanoen: ''Herra, milloin me näimme sinut nälkäisenä tai janoisena tai outona tai alastonna tai sairaana tai vankeudessa, emmekä sinua palvelleet?'''),
(1692996,58,40,25,45,'Silloin hän vastaa heille ja sanoo: ''Totisesti minä sanon teille: kaiken, minkä olette jättäneet tekemättä yhdelle näistä vähimmistä, sen te olette jättäneet tekemättä minulle''.'),
(1692997,58,40,25,46,'Ja nämä menevät pois iankaikkiseen rangaistukseen, mutta vanhurskaat iankaikkiseen elämään."'),
(1692998,58,40,26,1,'Ja kun Jeesus oli lopettanut kaikki nämä puheet, sanoi hän opetuslapsillensa:'),
(1692999,58,40,26,2,'"Te tiedätte, että kahden päivän perästä on pääsiäinen; silloin Ihmisen Poika annetaan ristiinnaulittavaksi".'),
(1693000,58,40,26,3,'Silloin ylipapit ja kansan vanhimmat kokoontuivat Kaifas nimisen ylimmäisen papin palatsiin'),
(1693001,58,40,26,4,'ja neuvottelivat, kuinka ottaisivat Jeesuksen kiinni kavaluudella ja tappaisivat hänet.'),
(1693002,58,40,26,5,'Mutta he sanoivat: "Ei juhlan aikana, ettei syntyisi meteliä kansassa".'),
(1693003,58,40,26,6,'Kun Jeesus oli Betaniassa pitalisen Simonin asunnossa,'),
(1693004,58,40,26,7,'tuli hänen luoksensa nainen, mukanaan alabasteripullo täynnä kallisarvoista voidetta, minkä hän vuodatti Jeesuksen päähän hänen ollessaan aterialla.'),
(1693005,58,40,26,8,'Mutta sen nähdessään hänen opetuslapsensa närkästyivät ja sanoivat: "Mitä varten tämä haaskaus?'),
(1693006,58,40,26,9,'Olisihan sen voinut myydä kalliista hinnasta ja antaa rahat köyhille."'),
(1693007,58,40,26,10,'Kun Jeesus sen huomasi, sanoi hän heille: "Miksi pahoitatte tämän naisen mieltä? Sillä hän teki hyvän työn minulle.'),
(1693008,58,40,26,11,'Köyhät teillä on aina keskuudessanne, mutta minua teillä ei ole aina.'),
(1693009,58,40,26,12,'Sillä kun hän valoi tämän voiteen minun ruumiilleni, teki hän sen minun hautaamistani varten.'),
(1693010,58,40,26,13,'Totisesti minä sanon teille: missä ikinä kaikessa maailmassa tätä evankeliumia saarnataan, siellä sekin, minkä hän teki, on mainittava hänen muistoksensa."'),
(1693011,58,40,26,14,'Silloin meni yksi niistä kahdestatoista, nimeltä Juudas Iskariot, ylipappien luo'),
(1693012,58,40,26,15,'ja sanoi: "Mitä tahdotte antaa minulle, niin minä saatan hänet teidän käsiinne?" Ja he maksoivat hänelle kolmekymmentä hopearahaa.'),
(1693013,58,40,26,16,'Ja siitä hetkestä hän etsi sopivaa tilaisuutta kavaltaaksensa hänet.'),
(1693014,58,40,26,17,'Mutta ensimmäisenä happamattoman leivän päivänä opetuslapset tulivat Jeesuksen tykö ja sanoivat: "Mihin tahdot, että valmistamme pääsiäislampaan sinun syödäksesi?"'),
(1693015,58,40,26,18,'Niin hän sanoi: "Menkää kaupunkiin sen ja sen luo ja sanokaa hänelle: ''Opettaja sanoo: Minun aikani on lähellä; sinun luonasi minä syön pääsiäisaterian opetuslasteni kanssa''."'),
(1693016,58,40,26,19,'Ja opetuslapset tekivät, niinkuin Jeesus oli heitä käskenyt, ja valmistivat pääsiäislampaan.'),
(1693017,58,40,26,20,'Ja kun ehtoo tuli, asettui hän aterialle kahdentoista opetuslapsensa kanssa.'),
(1693018,58,40,26,21,'Ja heidän syödessään hän sanoi: "Totisesti minä sanon teille: yksi teistä kavaltaa minut".'),
(1693019,58,40,26,22,'Silloin he tulivat kovin murheellisiksi ja rupesivat toinen toisensa perästä sanomaan hänelle: "Herra, en kai minä ole se?"'),
(1693020,58,40,26,23,'Hän vastasi ja sanoi: "Joka minun kanssani pisti kätensä vatiin, se kavaltaa minut.'),
(1693021,58,40,26,24,'Ihmisen Poika tosin menee pois, niinkuin hänestä on kirjoitettu, mutta voi sitä ihmistä, jonka kautta Ihmisen Poika kavalletaan! Parempi olisi sille ihmiselle, että hän ei olisi syntynyt."'),
(1693022,58,40,26,25,'Niin Juudas, joka hänet kavalsi, vastasi ja sanoi: "Rabbi, en kai minä ole se?" Hän sanoi hänelle: "Sinäpä sen sanoit".'),
(1693023,58,40,26,26,'Ja heidän syödessään Jeesus otti leivän, siunasi, mursi ja antoi opetuslapsillensa ja sanoi: "Ottakaa ja syökää; tämä on minun ruumiini".'),
(1693024,58,40,26,27,'Ja hän otti maljan, kiitti ja antoi heille ja sanoi: "Juokaa tästä kaikki;'),
(1693025,58,40,26,28,'sillä tämä on minun vereni, liiton veri, joka monen edestä vuodatetaan syntien anteeksiantamiseksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693026,58,40,26,29,'Ja minä sanon teille: tästedes minä en juo tätä viinipuun antia, ennenkuin sinä päivänä, jona juon sitä uutena teidän kanssanne Isäni valtakunnassa."'),
(1693027,58,40,26,30,'Ja veisattuaan kiitosvirren he lähtivät Öljymäelle.'),
(1693028,58,40,26,31,'Silloin Jeesus sanoi heille: "Tänä yönä te kaikki loukkaannutte minuun; sillä kirjoitettu on: ''Minä lyön paimenta, ja lauman lampaat hajotetaan''.'),
(1693029,58,40,26,32,'Mutta ylösnoustuani minä menen teidän edellänne Galileaan."'),
(1693030,58,40,26,33,'Niin Pietari vastasi ja sanoi hänelle: "Vaikka kaikki loukkaantuisivat sinuun, niin minä en koskaan loukkaannu".'),
(1693031,58,40,26,34,'Jeesus sanoi hänelle: "Totisesti minä sanon sinulle: tänä yönä, ennenkuin kukko laulaa, sinä kolmesti minut kiellät".'),
(1693032,58,40,26,35,'Pietari sanoi hänelle: "Vaikka minun pitäisi kuolla sinun kanssasi, en sittenkään minä sinua kiellä". Samoin sanoivat myös kaikki muut opetuslapset.'),
(1693033,58,40,26,36,'Sitten Jeesus tuli heidän kanssaan Getsemane nimiselle maatilalle; ja hän sanoi opetuslapsillensa: "Istukaa tässä, sillä aikaa kuin minä menen ja rukoilen tuolla".'),
(1693034,58,40,26,37,'Ja hän otti mukaansa Pietarin ja ne kaksi Sebedeuksen poikaa; ja hän alkoi murehtia ja tulla tuskaan.'),
(1693035,58,40,26,38,'Silloin hän sanoi heille: "Minun sieluni on syvästi murheellinen, kuolemaan asti; olkaa tässä ja valvokaa minun kanssani".'),
(1693036,58,40,26,39,'Ja hän meni vähän edemmäksi, lankesi kasvoilleen ja rukoili sanoen: "Isäni, jos mahdollista on, niin menköön minulta pois tämä malja; ei kuitenkaan niinkuin minä tahdon, vaan niinkuin sinä".'),
(1693037,58,40,26,40,'Ja hän tuli opetuslasten tykö ja tapasi heidät nukkumasta ja sanoi Pietarille: "Niin ette siis jaksaneet yhtä hetkeä valvoa minun kanssani!'),
(1693038,58,40,26,41,'Valvokaa ja rukoilkaa, ettette joutuisi kiusaukseen; henki tosin on altis, mutta liha on heikko."'),
(1693039,58,40,26,42,'Taas hän meni pois toisen kerran ja rukoili sanoen: "Isäni, jos tämä malja ei voi mennä minun ohitseni, minun sitä juomattani, niin tapahtukoon sinun tahtosi".'),
(1693040,58,40,26,43,'Ja tullessaan hän taas tapasi heidät nukkumasta, sillä heidän silmänsä olivat käyneet raukeiksi.'),
(1693041,58,40,26,44,'Ja hän jätti heidät, meni taas ja rukoili kolmannen kerran ja sanoi samat sanat uudestaan.'),
(1693042,58,40,26,45,'Sitten hän tuli opetuslasten tykö ja sanoi heille: "Te nukutte vielä ja lepäätte! Katso, hetki on lähellä, ja Ihmisen Poika annetaan syntisten käsiin.'),
(1693043,58,40,26,46,'Nouskaa, lähtekäämme; katso, se on lähellä, joka minut kavaltaa."'),
(1693044,58,40,26,47,'Ja katso, hänen vielä puhuessaan tuli Juudas, yksi niistä kahdestatoista, ja hänen kanssaan lukuisa joukko ylipappien ja kansan vanhinten luota miekat ja seipäät käsissä.'),
(1693045,58,40,26,48,'Ja se, joka hänet kavalsi, oli antanut heille merkin sanoen: "Se, jolle minä suuta annan, hän se on; ottakaa hänet kiinni".'),
(1693046,58,40,26,49,'Ja kohta hän meni Jeesuksen luo ja sanoi: "Terve, rabbi!" ja antoi hänelle suuta.'),
(1693047,58,40,26,50,'Niin Jeesus sanoi hänelle: "Ystäväni, mitä varten sinä tänne tulit?" Silloin he tulivat Jeesuksen luo, kävivät häneen käsiksi ja ottivat hänet kiinni.'),
(1693048,58,40,26,51,'Ja katso, eräs niistä, jotka olivat Jeesuksen kanssa, ojensi kätensä, veti miekkansa ja iski ylimmäisen papin palvelijaa ja sivalsi häneltä pois korvan.'),
(1693049,58,40,26,52,'Silloin Jeesus sanoi hänelle: "Pistä miekkasi tuppeen; sillä kaikki, jotka miekkaan tarttuvat, ne miekkaan hukkuvat.'),
(1693050,58,40,26,53,'Vai luuletko, etten voisi rukoilla Isääni, niin että hän lähettäisi heti minulle enemmän kuin kaksitoista legionaa enkeleitä?'),
(1693051,58,40,26,54,'Mutta kuinka silloin kävisivät toteen kirjoitukset, jotka sanovat, että näin pitää tapahtuman?"'),
(1693052,58,40,26,55,'Sillä hetkellä Jeesus sanoi joukolle: "Niinkuin ryöväriä vastaan te olette lähteneet minua miekoilla ja seipäillä vangitsemaan. Joka päivä minä olen istunut pyhäkössä opettamassa, ettekä ole ottaneet minua kiinni.'),
(1693053,58,40,26,56,'Mutta tämä kaikki on tapahtunut, että profeettain kirjoitukset kävisivät toteen." Silloin kaikki opetuslapset jättivät hänet ja pakenivat.'),
(1693054,58,40,26,57,'Mutta Jeesuksen kiinniottajat veivät hänet ylimmäisen papin, Kaifaan, eteen, jonne kirjanoppineet ja vanhimmat olivat kokoontuneet.'),
(1693055,58,40,26,58,'Ja Pietari seurasi häntä taampana ylimmäisen papin esipihaan asti; ja hän meni sinne ja istui palvelijain joukkoon nähdäksensä, kuinka lopulta kävisi.'),
(1693056,58,40,26,59,'Mutta ylipapit ja koko neuvosto etsivät väärää todistusta Jeesusta vastaan tappaaksensa hänet,'),
(1693057,58,40,26,60,'mutta eivät löytäneet, vaikka monta väärää todistajaa oli tullut esille. Mutta vihdoin tuli kaksi,'),
(1693058,58,40,26,61,'ja he sanoivat: "Tämä on sanonut: ''Minä voin hajottaa maahan Jumalan temppelin ja kolmessa päivässä sen rakentaa''."'),
(1693059,58,40,26,62,'Silloin ylimmäinen pappi nousi ja sanoi hänelle: "Etkö vastaa mitään siihen, mitä nämä todistavat sinua vastaan?"'),
(1693060,58,40,26,63,'Mutta Jeesus oli vaiti. Niin ylimmäinen pappi sanoi hänelle: "Minä vannotan sinua elävän Jumalan kautta, että sanot meille, oletko sinä Kristus, Jumalan Poika".'),
(1693061,58,40,26,64,'Jeesus sanoi hänelle: "Sinäpä sen sanoit. Mutta minä sanon teille: tästedes te saatte nähdä Ihmisen Pojan istuvan Voiman oikealla puolella ja tulevan taivaan pilvien päällä."'),
(1693062,58,40,26,65,'Silloin ylimmäinen pappi repäisi vaatteensa ja sanoi: "Hän on pilkannut Jumalaa. Mitä me enää todistajia tarvitsemme? Katso, nyt kuulitte hänen pilkkaamisensa.'),
(1693063,58,40,26,66,'Miten teistä on?" He vastasivat sanoen: "Hän on vikapää kuolemaan".'),
(1693064,58,40,26,67,'Silloin he sylkivät häntä silmille ja löivät häntä nyrkillä kasvoihin; ja toiset sivalsivat häntä poskelle'),
(1693065,58,40,26,68,'ja sanoivat: "Profetoi meille, Kristus, kuka se on, joka sinua löi".'),
(1693066,58,40,26,69,'Mutta Pietari istui ulkopuolella esipihassa. Ja hänen luoksensa tuli muuan palvelijatar ja sanoi: "Sinäkin olit Jeesuksen, galilealaisen, seurassa".'),
(1693067,58,40,26,70,'Mutta hän kielsi kaikkien kuullen ja sanoi: "En ymmärrä, mitä sanot".'),
(1693068,58,40,26,71,'Ja kun hän oli mennyt ulos portille, näki hänet toinen nainen ja sanoi sielläoleville: "Tämäkin oli Jeesuksen, Nasaretilaisen, seurassa".'),
(1693069,58,40,26,72,'Ja taas hän kielsi valalla vannoen: "En tunne sitä miestä".'),
(1693070,58,40,26,73,'Vähän sen jälkeen tulivat ne, jotka siinä seisoivat, ja sanoivat Pietarille: "Totisesti, sinä myös olet yksi heistä, sillä kielimurteesikin ilmaisee sinut".'),
(1693071,58,40,26,74,'Silloin hän rupesi sadattelemaan ja vannomaan: "En tunne sitä miestä". Ja samassa lauloi kukko.'),
(1693072,58,40,26,75,'Niin Pietari muisti Jeesuksen sanat, jotka hän oli sanonut: "Ennenkuin kukko laulaa, sinä kolmesti minut kiellät". Ja hän meni ulos ja itki katkerasti.'),
(1693073,58,40,27,1,'Mutta aamun koittaessa kaikki ylipapit ja kansan vanhimmat pitivät neuvoa Jeesusta vastaan tappaaksensa hänet;'),
(1693074,58,40,27,2,'ja he sitoivat hänet ja veivät pois ja antoivat hänet maaherran, Pilatuksen, käsiin.'),
(1693075,58,40,27,3,'Kun Juudas, hänen kavaltajansa, näki, että hänet oli tuomittu, silloin hän katui ja toi takaisin ne kolmekymmentä hopearahaa ylipapeille ja vanhimmille');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693076,58,40,27,4,'ja sanoi: "Minä tein synnin, kun kavalsin viattoman veren". Mutta he sanoivat: "Mitä se meihin koskee? Katso itse eteesi."'),
(1693077,58,40,27,5,'Ja hän viskasi hopearahat temppeliin, lähti sieltä, meni pois ja hirttäytyi.'),
(1693078,58,40,27,6,'Niin ylipapit ottivat hopearahat ja sanoivat: "Ei ole luvallista panna näitä temppelirahastoon, koska ne ovat veren hinta".'),
(1693079,58,40,27,7,'Ja neuvoteltuaan he ostivat niillä savenvalajan pellon muukalaisten hautausmaaksi.'),
(1693080,58,40,27,8,'Sentähden sitä peltoa vielä tänäkin päivänä kutsutaan Veripelloksi.'),
(1693081,58,40,27,9,'Silloin kävi toteen, mikä on puhuttu profeetta Jeremiaan kautta, joka sanoo: "Ja he ottivat ne kolmekymmentä hopearahaa, hinnan siitä arvioidusta miehestä, jonka he olivat israelilaisten puolesta arvioineet,'),
(1693082,58,40,27,10,'ja antoivat ne savenvalajan pellosta, niinkuin Herra oli minun kauttani käskenyt".'),
(1693083,58,40,27,11,'Mutta Jeesus seisoi maaherran edessä. Ja maaherra kysyi häneltä sanoen: "Oletko sinä juutalaisten kuningas?" Niin Jeesus sanoi: "Sinäpä sen sanot".'),
(1693084,58,40,27,12,'Ja kun ylipapit ja vanhimmat häntä syyttivät, ei hän mitään vastannut.'),
(1693085,58,40,27,13,'Silloin Pilatus sanoi hänelle: "Etkö kuule, kuinka paljon he todistavat sinua vastaan?"'),
(1693086,58,40,27,14,'Mutta hän ei vastannut yhteenkään hänen kysymykseensä, niin että maaherra suuresti ihmetteli.'),
(1693087,58,40,27,15,'Oli tapana, että maaherra juhlan aikana päästi kansalle yhden vangin irti, kenenkä he tahtoivat.'),
(1693088,58,40,27,16,'Ja heillä oli silloin kuuluisa vanki, jota sanottiin Barabbaaksi.'),
(1693089,58,40,27,17,'Kun he nyt olivat koolla, sanoi Pilatus heille: "Kummanko tahdotte, että minä teille päästän, Barabbaanko vai Jeesuksen, jota sanotaan Kristukseksi?"'),
(1693090,58,40,27,18,'Sillä hän tiesi, että he kateudesta olivat antaneet hänet hänen käsiinsä.'),
(1693091,58,40,27,19,'Mutta kun hän istui tuomarinistuimella, lähetti hänen vaimonsa hänelle sanan: "Älä puutu siihen vanhurskaaseen mieheen, sillä minä olen tänä yönä unessa paljon kärsinyt hänen tähtensä".'),
(1693092,58,40,27,20,'Mutta ylipapit ja vanhimmat yllyttivät kansaa anomaan Barabbasta, mutta surmauttamaan Jeesuksen.'),
(1693093,58,40,27,21,'Ja maaherra puhui heille ja sanoi: "Kummanko näistä kahdesta tahdotte, että minä teille päästän?" Niin he sanoivat: "Barabbaan".'),
(1693094,58,40,27,22,'Pilatus sanoi heille: "Mitä minun sitten on tehtävä Jeesukselle, jota sanotaan Kristukseksi?" He sanoivat kaikki: "Ristiinnaulittakoon!"'),
(1693095,58,40,27,23,'Niin maaherra sanoi: "Mitä pahaa hän sitten on tehnyt?" Mutta he huusivat vielä kovemmin sanoen: "Ristiinnaulittakoon!"'),
(1693096,58,40,27,24,'Ja kun Pilatus näki, ettei mikään auttanut, vaan että meteli yhä yltyi, otti hän vettä ja pesi kätensä kansan nähden ja sanoi: "Viaton olen minä tämän miehen vereen. Katsokaa itse eteenne."'),
(1693097,58,40,27,25,'Niin kaikki kansa vastasi ja sanoi: "Tulkoon hänen verensä meidän päällemme ja meidän lastemme päälle".'),
(1693098,58,40,27,26,'Silloin hän päästi heille Barabbaan, mutta Jeesuksen hän ruoskitti ja luovutti ristiinnaulittavaksi.'),
(1693099,58,40,27,27,'Silloin maaherran sotamiehet veivät Jeesuksen mukanaan palatsiin ja keräsivät hänen ympärilleen koko sotilasjoukon.'),
(1693100,58,40,27,28,'Ja he riisuivat hänet ja panivat hänen päällensä tulipunaisen vaipan'),
(1693101,58,40,27,29,'ja väänsivät orjantappuroista kruunun, panivat sen hänen päähänsä ja ruovon hänen oikeaan käteensä, polvistuivat hänen eteensä ja pilkkasivat häntä ja sanoivat: "Terve, juutalaisten kuningas!"'),
(1693102,58,40,27,30,'Ja he sylkivät häntä, ottivat ruovon ja löivät häntä päähän.'),
(1693103,58,40,27,31,'Ja kun he olivat häntä pilkanneet, riisuivat he häneltä vaipan, pukivat hänet hänen omiin vaatteisiinsa ja veivät hänet pois ristiinnaulittavaksi.'),
(1693104,58,40,27,32,'Ja matkalla he tapasivat kyreneläisen miehen, jonka nimi oli Simon. Hänet he pakottivat kantamaan hänen ristiänsä.'),
(1693105,58,40,27,33,'Ja tultuaan paikalle, jota sanotaan Golgataksi - se on: pääkallon paikaksi -'),
(1693106,58,40,27,34,'he tarjosivat hänelle juotavaksi katkeralla nesteellä sekoitettua viiniä; mutta maistettuaan hän ei tahtonut sitä juoda.'),
(1693107,58,40,27,35,'Ja kun he olivat hänet ristiinnaulinneet, jakoivat he keskenään hänen vaatteensa heittäen niistä arpaa.'),
(1693108,58,40,27,36,'Sitten he istuutuivat ja vartioivat häntä siellä.'),
(1693109,58,40,27,37,'Ja he olivat panneet hänen päänsä yläpuolelle hänen syynsä julki, näin kirjoitettuna: "Tämä on Jeesus, juutalaisten kuningas".'),
(1693110,58,40,27,38,'Silloin ristiinnaulittiin hänen kanssansa kaksi ryöväriä, toinen oikealle ja toinen vasemmalle puolelle.'),
(1693111,58,40,27,39,'Ja ne, jotka kulkivat ohitse, herjasivat häntä, nyökyttivät päätänsä'),
(1693112,58,40,27,40,'ja sanoivat: "Sinä, joka hajotat maahan temppelin ja kolmessa päivässä sen rakennat, auta itseäsi, jos olet Jumalan Poika, ja astu alas ristiltä".'),
(1693113,58,40,27,41,'Samoin ylipapit ja kirjanoppineet ja vanhimmat pilkkasivat häntä ja sanoivat:'),
(1693114,58,40,27,42,'"Muita hän on auttanut, itseään ei voi auttaa. Onhan hän Israelin kuningas; astukoon nyt alas ristiltä, niin me uskomme häneen.'),
(1693115,58,40,27,43,'Hän on luottanut Jumalaan; vapahtakoon nyt Jumala hänet, jos on häneen mielistynyt; sillä hän on sanonut: ''Minä olen Jumalan Poika''."'),
(1693116,58,40,27,44,'Ja samalla tavalla herjasivat häntä ryöväritkin, jotka olivat ristiinnaulitut hänen kanssansa.'),
(1693117,58,40,27,45,'Mutta kuudennesta hetkestä alkaen tuli pimeys yli kaiken maan, ja sitä kesti hamaan yhdeksänteen hetkeen.'),
(1693118,58,40,27,46,'Ja yhdeksännen hetken vaiheilla Jeesus huusi suurella äänellä sanoen: "Eeli, Eeli, lama sabaktani?" Se on: Jumalani, Jumalani, miksi minut hylkäsit?'),
(1693119,58,40,27,47,'Sen kuullessaan sanoivat muutamat niistä, jotka siinä seisoivat: "Hän huutaa Eliasta".'),
(1693120,58,40,27,48,'Ja kohta muuan heistä juoksi ja otti sienen, täytti sen hapanviinillä, pani sen ruovon päähän ja antoi hänelle juoda.'),
(1693121,58,40,27,49,'Mutta muut sanoivat: "Annas, katsokaamme, tuleeko Elias häntä pelastamaan".'),
(1693122,58,40,27,50,'Niin Jeesus taas huusi suurella äänellä ja antoi henkensä.'),
(1693123,58,40,27,51,'Ja katso, temppelin esirippu repesi kahtia ylhäältä alas asti, ja maa järisi, ja kalliot halkesivat,'),
(1693124,58,40,27,52,'ja haudat aukenivat, ja monta nukkuneiden pyhien ruumista nousi ylös.'),
(1693125,58,40,27,53,'Ja he lähtivät haudoistaan ja tulivat hänen ylösnousemisensa jälkeen pyhään kaupunkiin ja ilmestyivät monelle.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693126,58,40,27,54,'Mutta kun sadanpäämies ja ne, jotka hänen kanssaan vartioitsivat Jeesusta, näkivät maanjäristyksen ja mitä muuta tapahtui, peljästyivät he suuresti ja sanoivat: "Totisesti tämä oli Jumalan Poika".'),
(1693127,58,40,27,55,'Ja siellä oli monta naista, jotka olivat Galileasta seuranneet Jeesusta ja palvelleet häntä; he seisoivat taampana katselemassa.'),
(1693128,58,40,27,56,'Heidän joukossaan oli Maria Magdaleena ja Maria, Jaakobin ja Joosefin äiti, ja Sebedeuksen poikain äiti.'),
(1693129,58,40,27,57,'Mutta illan tultua saapui rikas mies, Arimatiasta kotoisin, nimeltä Joosef, joka hänkin oli Jeesuksen opetuslapsi.'),
(1693130,58,40,27,58,'Hän meni Pilatuksen luo ja pyysi Jeesuksen ruumista. Silloin Pilatus käski antaa sen hänelle.'),
(1693131,58,40,27,59,'Ja Joosef otti ruumiin, kääri sen puhtaaseen liinavaatteeseen'),
(1693132,58,40,27,60,'ja pani sen uuteen hautakammioonsa, jonka oli hakkauttanut kallioon. Ja hän vieritti suuren kiven hautakammion ovelle ja lähti pois.'),
(1693133,58,40,27,61,'Ja siellä olivat Maria Magdaleena ja toinen Maria, jotka istuivat vastapäätä hautaa.'),
(1693134,58,40,27,62,'Seuraavana päivänä, joka oli valmistuspäivän jälkeinen, ylipapit ja fariseukset kokoontuivat Pilatuksen luo'),
(1693135,58,40,27,63,'ja sanoivat: "Herra, me muistamme sen villitsijän vielä eläessään sanoneen: ''Kolmen päivän kuluttua minä nousen ylös''.'),
(1693136,58,40,27,64,'Käske siis tarkasti vartioida hautaa kolmanteen päivään asti, etteivät hänen opetuslapsensa tulisi ja varastaisi häntä ja sanoisi kansalle: ''Hän nousi kuolleista'', ja niin viimeinen villitys olisi pahempi kuin ensimmäinen."'),
(1693137,58,40,27,65,'Niin Pilatus sanoi heille: "Tuossa on vartijaväkeä, menkää, vartioikaa niin hyvin kuin taidatte".'),
(1693138,58,40,27,66,'Niin he menivät ja turvasivat haudan lukitsemalla kiven sinetillä ja asettamalla vartijat.'),
(1693139,58,40,28,1,'Ja kun sapatti oli päättynyt ja viikon ensimmäisen päivän aamu koitti, tulivat Maria Magdaleena ja se toinen Maria katsomaan hautaa.'),
(1693140,58,40,28,2,'Ja katso, tapahtui suuri maanjäristys, sillä Herran enkeli astui alas taivaasta, tuli ja vieritti kiven pois ja istui sille.'),
(1693141,58,40,28,3,'Hän oli näöltään niinkuin salama, ja hänen vaatteensa olivat valkeat kuin lumi.'),
(1693142,58,40,28,4,'Ja häntä peljästyen vartijat vapisivat ja kävivät ikäänkuin kuolleiksi.'),
(1693143,58,40,28,5,'Mutta enkeli puhutteli naisia ja sanoi heille: "Älkää te peljätkö; sillä minä tiedän teidän etsivän Jeesusta, joka oli ristiinnaulittu.'),
(1693144,58,40,28,6,'Ei hän ole täällä, sillä hän on noussut ylös, niinkuin hän sanoi. Tulkaa, katsokaa paikkaa, jossa hän on maannut.'),
(1693145,58,40,28,7,'Ja menkää kiiruusti ja sanokaa hänen opetuslapsillensa, että hän on noussut kuolleista. Ja katso, hän menee teidän edellänne Galileaan; siellä te saatte hänet nähdä. Katso, minä olen sen teille sanonut."'),
(1693146,58,40,28,8,'Ja he menivät kiiruusti haudalta peloissaan ja suuresti iloiten ja juoksivat viemään sanaa hänen opetuslapsillensa.'),
(1693147,58,40,28,9,'Mutta katso, Jeesus tuli heitä vastaan ja sanoi: "Terve teille!" Ja he menivät hänen tykönsä, syleilivät hänen jalkojaan ja kumartaen rukoilivat häntä.'),
(1693148,58,40,28,10,'Silloin Jeesus sanoi heille: "Älkää peljätkö; menkää ja viekää sana minun veljilleni, että he menisivät Galileaan: siellä he saavat minut nähdä".'),
(1693149,58,40,28,11,'Mutta heidän mennessään, katso, muutamat vartijaväestä tulivat kaupunkiin ja ilmoittivat ylipapeille kaikki, mitä oli tapahtunut.'),
(1693150,58,40,28,12,'Ja nämä kokoontuivat vanhinten kanssa ja pitivät neuvoa ja antoivat sotamiehille runsaat rahat'),
(1693151,58,40,28,13,'ja sanoivat: "Sanokaa, että hänen opetuslapsensa tulivat yöllä ja veivät hänet varkain meidän nukkuessamme.'),
(1693152,58,40,28,14,'Ja jos tämä tulee maaherran korviin, niin me lepytämme hänet ja toimitamme niin, että saatte olla huoletta."'),
(1693153,58,40,28,15,'Niin he ottivat rahat ja tekivät, niinkuin heitä oli neuvottu. Ja tätä puhetta on levitetty juutalaisten kesken, ja sitä kerrotaan vielä tänäkin päivänä.'),
(1693154,58,40,28,16,'Ja ne yksitoista opetuslasta vaelsivat Galileaan sille vuorelle, jonne Jeesus oli käskenyt heidän mennä.'),
(1693155,58,40,28,17,'Ja kun he näkivät hänet, niin he kumartaen rukoilivat häntä, mutta muutamat epäilivät.'),
(1693156,58,40,28,18,'Ja Jeesus tuli heidän tykönsä ja puhui heille ja sanoi: "Minulle on annettu kaikki valta taivaassa ja maan päällä.'),
(1693157,58,40,28,19,'Menkää siis ja tehkää kaikki kansat minun opetuslapsikseni, kastamalla heitä Isän ja Pojan ja Pyhän Hengen nimeen'),
(1693158,58,40,28,20,'ja opettamalla heitä pitämään kaikki, mitä minä olen käskenyt teidän pitää. Ja katso, minä olen teidän kanssanne joka päivä maailman loppuun asti."'),
(1693159,58,41,1,1,'Jeesuksen Kristuksen, Jumalan Pojan, evankeliumin alku.'),
(1693160,58,41,1,2,'Niinkuin on kirjoitettuna profeetta Esaiaan kirjassa: "Katso, minä lähetän enkelini sinun edelläsi, ja hän on valmistava sinun tiesi".'),
(1693161,58,41,1,3,'"Huutavan ääni kuuluu erämaassa: ''Valmistakaa Herralle tie, tehkää polut hänelle tasaisiksi''",'),
(1693162,58,41,1,4,'niin Johannes Kastaja saarnasi erämaassa parannuksen kastetta syntien anteeksisaamiseksi.'),
(1693163,58,41,1,5,'Ja koko Juudean maa ja kaikki jerusalemilaiset vaelsivat hänen tykönsä, ja hän kastoi heidät Jordanin virrassa, kun he tunnustivat syntinsä.'),
(1693164,58,41,1,6,'Ja Johanneksella oli puku kamelinkarvoista ja vyötäisillään nahkavyö; ja hän söi heinäsirkkoja ja metsähunajaa.'),
(1693165,58,41,1,7,'Ja hän saarnasi sanoen: "Minun jälkeeni tulee minua väkevämpi, jonka kengänpaulaa minä en ole kelvollinen maahan kumartuneena päästämään.'),
(1693166,58,41,1,8,'Minä kastan teidät vedellä, mutta hän kastaa teidät Pyhällä Hengellä."'),
(1693167,58,41,1,9,'Ja niinä päivinä Jeesus tuli Galilean Nasaretista, ja Johannes kastoi hänet Jordanissa.'),
(1693168,58,41,1,10,'Ja heti, vedestä noustessaan, hän näki taivasten aukeavan ja Hengen niinkuin kyyhkysen laskeutuvan häneen.'),
(1693169,58,41,1,11,'Ja taivaista tuli ääni: "Sinä olet minun rakas Poikani; sinuun minä olen mielistynyt".'),
(1693170,58,41,1,12,'Kohta sen jälkeen Henki ajoi hänet erämaahan.'),
(1693171,58,41,1,13,'Ja hän oli erämaassa neljäkymmentä päivää, ja saatana kiusasi häntä, ja hän oli petojen seassa; ja enkelit tekivät hänelle palvelusta.'),
(1693172,58,41,1,14,'Mutta sittenkuin Johannes oli pantu vankeuteen, meni Jeesus Galileaan ja saarnasi Jumalan evankeliumia'),
(1693173,58,41,1,15,'ja sanoi: "Aika on täyttynyt, ja Jumalan valtakunta on tullut lähelle; tehkää parannus ja uskokaa evankeliumi".'),
(1693174,58,41,1,16,'Ja kulkiessaan Galilean järven rantaa hän näki Simonin ja Andreaan, Simonin veljen, heittävän verkkoa järveen; sillä he olivat kalastajia.'),
(1693175,58,41,1,17,'Ja Jeesus sanoi heille: "Seuratkaa minua, niin minä teen teistä ihmisten kalastajia".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693176,58,41,1,18,'Kohta he jättivät verkot ja seurasivat häntä.'),
(1693177,58,41,1,19,'Ja käytyään siitä vähän eteenpäin hän näki Jaakobin, Sebedeuksen pojan, ja Johanneksen, hänen veljensä, heidätkin venheessä, laittamassa verkkojaan kuntoon.'),
(1693178,58,41,1,20,'Ja kohta hän kutsui heidät; ja he jättivät isänsä, Sebedeuksen, palkkalaisineen venheeseen ja lähtivät seuraamaan häntä.'),
(1693179,58,41,1,21,'Ja he saapuivat Kapernaumiin; ja hän meni kohta sapattina synagoogaan ja opetti.'),
(1693180,58,41,1,22,'Ja he olivat hämmästyksissään hänen opetuksestansa, sillä hän opetti heitä niinkuin se, jolla valta on, eikä niinkuin kirjanoppineet.'),
(1693181,58,41,1,23,'Ja heidän synagoogassaan oli juuri silloin mies, jossa oli saastainen henki; ja se huusi'),
(1693182,58,41,1,24,'sanoen: "Mitä sinulla on meidän kanssamme tekemistä, Jeesus Nasaretilainen? Oletko tullut meitä tuhoamaan? Minä tunnen sinut, kuka olet, sinä Jumalan Pyhä."'),
(1693183,58,41,1,25,'Niin Jeesus nuhteli sitä sanoen: "Vaikene ja lähde hänestä".'),
(1693184,58,41,1,26,'Ja saastainen henki kouristi häntä ja lähti hänestä huutaen suurella äänellä.'),
(1693185,58,41,1,27,'Ja he hämmästyivät kaikki, niin että kyselivät toisiltaan sanoen: "Mitä tämä on? Uusi, voimallinen oppi! Hän käskee saastaisia henkiäkin, ja ne tottelevat häntä."'),
(1693186,58,41,1,28,'Ja hänen maineensa levisi kohta koko ympäristöön, kaikkialle Galileaan.'),
(1693187,58,41,1,29,'Ja tultuaan ulos synagoogasta he menivät kohta Simonin ja Andreaan taloon Jaakobin ja Johanneksen kanssa.'),
(1693188,58,41,1,30,'Ja Simonin anoppi makasi sairaana kuumeessa, ja kohta he puhuivat hänestä Jeesukselle.'),
(1693189,58,41,1,31,'Ja hän meni hänen luoksensa ja nosti hänet ylös, tarttuen hänen käteensä; ja kuume lähti hänestä, ja hän palveli heitä.'),
(1693190,58,41,1,32,'Mutta illan tultua, kun aurinko oli laskenut, tuotiin hänen tykönsä kaikki sairaat ja riivatut,'),
(1693191,58,41,1,33,'ja koko kaupunki oli koolla oven edessä.'),
(1693192,58,41,1,34,'Ja hän paransi monta, jotka sairastivat moninaisia tauteja, ja paljon riivaajia hän ajoi ulos eikä sallinut riivaajien puhua, koska ne tunsivat hänet.'),
(1693193,58,41,1,35,'Ja varhain aamulla, kun vielä oli pimeä, hän nousi, lähti ulos ja meni autioon paikkaan; ja siellä hän rukoili.'),
(1693194,58,41,1,36,'Mutta Simon ja ne, jotka olivat hänen kanssaan, riensivät hänen jälkeensä;'),
(1693195,58,41,1,37,'ja löydettyään hänet he sanoivat hänelle: "Kaikki etsivät sinua".'),
(1693196,58,41,1,38,'Ja hän sanoi heille: "Menkäämme muualle, läheisiin kyliin, että minä sielläkin saarnaisin, sillä sitä varten minä olen tullut".'),
(1693197,58,41,1,39,'Ja hän meni ja saarnasi heidän synagoogissaan koko Galileassa ja ajoi ulos riivaajat.'),
(1693198,58,41,1,40,'Ja hänen tykönsä tuli pitalinen mies, rukoili häntä, polvistui ja sanoi hänelle: "Jos tahdot, niin sinä voit minut puhdistaa".'),
(1693199,58,41,1,41,'Niin Jeesuksen kävi häntä sääliksi, ja ojentaen kätensä hän kosketti häntä ja sanoi hänelle: "Minä tahdon; puhdistu".'),
(1693200,58,41,1,42,'Ja kohta pitali lähti hänestä, ja hän puhdistui.'),
(1693201,58,41,1,43,'Ja varoittaen häntä ankarasti hän laski hänet heti menemään'),
(1693202,58,41,1,44,'ja sanoi hänelle: "Katso, ettet puhu tästä kenellekään mitään, vaan mene ja näytä itsesi papille ja uhraa puhdistumisestasi se, minkä Mooses on säätänyt, todistukseksi heille".'),
(1693203,58,41,1,45,'Mutta mentyään pois tämä rupesi laajalti julistamaan ja asiasta tietoa levittämään, niin ettei Jeesus enää saattanut julkisesti mennä kaupunkeihin, vaan oleskeli niiden ulkopuolella autioissa paikoissa; ja kaikkialta tultiin hänen tykönsä.'),
(1693204,58,41,2,1,'Ja muutamien päivien perästä hän taas meni Kapernaumiin; ja kun kuultiin hänen olevan kotona,'),
(1693205,58,41,2,2,'kokoontui paljon väkeä, niin etteivät he enää mahtuneet oven edustallekaan. Ja hän puhui heille sanaa.'),
(1693206,58,41,2,3,'Ja he tulivat tuoden hänen tykönsä halvattua, jota kantamassa oli neljä miestä.'),
(1693207,58,41,2,4,'Ja kun he väentungokselta eivät päässeet häntä tuomaan hänen tykönsä, purkivat he katon siltä kohdalta, missä hän oli, ja kaivettuaan aukon laskivat alas vuoteen, jossa halvattu makasi.'),
(1693208,58,41,2,5,'Kun Jeesus näki heidän uskonsa, sanoi hän halvatulle: "Poikani, sinun syntisi annetaan anteeksi".'),
(1693209,58,41,2,6,'Mutta siellä istui muutamia kirjanoppineita, ja he ajattelivat sydämessään:'),
(1693210,58,41,2,7,'"Kuinka tämä näin puhuu? Hän pilkkaa Jumalaa. Kuka voi antaa syntejä anteeksi paitsi Jumala yksin?"'),
(1693211,58,41,2,8,'Ja heti Jeesus tunsi hengessänsä, että he mielessään niin ajattelivat, ja sanoi heille: "Miksi ajattelette sellaista sydämessänne?'),
(1693212,58,41,2,9,'Kumpi on helpompaa, sanoako halvatulle: ''Sinun syntisi annetaan anteeksi'', vai sanoa: ''Nouse, ota vuoteesi ja käy''?'),
(1693213,58,41,2,10,'Mutta tietääksenne, että Ihmisen Pojalla on valta maan päällä antaa syntejä anteeksi, niin" - hän sanoi halvatulle -'),
(1693214,58,41,2,11,'"minä sanon sinulle: nouse, ota vuoteesi ja mene kotiisi."'),
(1693215,58,41,2,12,'Silloin hän nousi, otti kohta vuoteensa ja meni ulos kaikkien nähden, niin että kaikki hämmästyivät ja ylistivät Jumalaa sanoen: "Tämänkaltaista emme ole ikinä nähneet".'),
(1693216,58,41,2,13,'Ja taas hän lähti pois ja kulki järven rantaa. Ja kaikki kansa tuli hänen tykönsä, ja hän opetti heitä.'),
(1693217,58,41,2,14,'Ja ohi kulkiessaan hän näki Leevin, Alfeuksen pojan, istumassa tulliasemalla ja sanoi hänelle: "Seuraa minua". Niin tämä nousi ja seurasi häntä.'),
(1693218,58,41,2,15,'Ja kun hän aterioi hänen kodissaan, aterioi myös monta publikaania ja syntistä Jeesuksen ja hänen opetuslastensa kanssa; sillä heitä oli paljon häntä seuraamassa.'),
(1693219,58,41,2,16,'Kun fariseusten kirjanoppineet näkivät, että hän söi syntisten ja publikaanien kanssa, sanoivat he hänen opetuslapsilleen: "Publikaanien ja syntistenkö kanssa hän syö?"'),
(1693220,58,41,2,17,'Sen kuullessaan Jeesus sanoi heille: "Eivät terveet tarvitse parantajaa, vaan sairaat. En minä ole tullut kutsumaan vanhurskaita, vaan syntisiä."'),
(1693221,58,41,2,18,'Ja Johanneksen opetuslapset ja fariseukset pitivät paastoa. Niin tultiin ja sanottiin hänelle: "Johanneksen opetuslapset ja fariseusten opetuslapset paastoavat; miksi sinun opetuslapsesi eivät paastoa?"'),
(1693222,58,41,2,19,'Jeesus sanoi heille: "Eiväthän häävieraat voi paastota silloin, kun ylkä on heidän kanssaan? Niin kauan kuin heillä on ylkä seurassaan, eivät he voi paastota.'),
(1693223,58,41,2,20,'Mutta päivät tulevat, jolloin ylkä otetaan heiltä pois, ja silloin, sinä päivänä, he paastoavat.'),
(1693224,58,41,2,21,'Ei kukaan ompele vanuttamattomasta kankaasta paikkaa vanhaan vaippaan; muutoin uusi täytetilkku repii palasen vanhasta vaipasta, ja reikä tulee pahemmaksi.'),
(1693225,58,41,2,22,'Eikä kukaan laske nuorta viiniä vanhoihin nahkaleileihin; muutoin viini pakahuttaa leilit, ja viini menee hukkaan, ja leilit turmeltuvat; vaan nuori viini on laskettava uusiin leileihin."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693226,58,41,2,23,'Ja tapahtui, että hän sapattina kulki viljavainioiden halki, ja hänen opetuslapsensa rupesivat kulkiessaan katkomaan tähkäpäitä.'),
(1693227,58,41,2,24,'Niin fariseukset sanoivat hänelle: "Katso, miksi he tekevät sapattina sitä, mikä ei ole luvallista?"'),
(1693228,58,41,2,25,'Hän sanoi heille: "Ettekö ole koskaan lukeneet, mitä Daavid teki, kun hän ja hänen seuralaisensa olivat puutteessa ja heidän oli nälkä,'),
(1693229,58,41,2,26,'kuinka hän meni Jumalan huoneeseen ylimmäisen papin Abjatarin aikana ja söi näkyleivät, joita ei ollut lupa syödä muiden kuin pappien, ja antoi myös niille, jotka hänen kanssansa olivat?"'),
(1693230,58,41,2,27,'Ja hän sanoi heille: "Sapatti on asetettu ihmistä varten eikä ihminen sapattia varten.'),
(1693231,58,41,2,28,'Niin Ihmisen Poika siis on sapatinkin herra."'),
(1693232,58,41,3,1,'Ja hän meni taas synagoogaan, ja siellä oli mies, jonka käsi oli kuivettunut.'),
(1693233,58,41,3,2,'Ja voidakseen nostaa syytteen häntä vastaan he pitivät häntä silmällä, parantaisiko hän miehen sapattina.'),
(1693234,58,41,3,3,'Niin hän sanoi miehelle, jonka käsi oli kuivettunut: "Nouse ja astu esille".'),
(1693235,58,41,3,4,'Ja hän sanoi heille: "Kumpiko on luvallista sapattina: hyvääkö tehdä vai pahaa, pelastaako henki vai tappaa se?" Mutta he olivat vaiti.'),
(1693236,58,41,3,5,'Silloin hän katsahtaen ympärilleen loi vihassa silmänsä heihin, murheellisena heidän sydämensä paatumuksesta, ja sanoi sille miehelle: "Ojenna kätesi". Ja hän ojensi, ja hänen kätensä tuli jälleen terveeksi.'),
(1693237,58,41,3,6,'Ja fariseukset lähtivät ulos ja pitivät kohta herodilaisten kanssa neuvoa häntä vastaan, surmataksensa hänet.'),
(1693238,58,41,3,7,'Mutta Jeesus vetäytyi opetuslapsineen järven rannalle, ja häntä seurasi suuri joukko kansaa Galileasta. Ja Juudeasta'),
(1693239,58,41,3,8,'ja Jerusalemista ja Idumeasta ja Jordanin tuolta puolen ja Tyyron ja Siidonin ympäristöltä tuli paljon kansaa hänen tykönsä, kun he kuulivat, kuinka suuria tekoja hän teki.'),
(1693240,58,41,3,9,'Ja hän sanoi opetuslapsillensa, että hänelle oli pidettävä venhe varalla väentungoksen tähden, etteivät he ahdistaisi häntä;'),
(1693241,58,41,3,10,'sillä hän paransi monta, jonka tähden kaikki, joilla oli vaivoja, tunkeutuivat hänen päälleen koskettaaksensa häntä.'),
(1693242,58,41,3,11,'Ja kun saastaiset henget näkivät hänet, lankesivat he maahan hänen eteensä ja huusivat sanoen: "Sinä olet Jumalan Poika".'),
(1693243,58,41,3,12,'Ja hän varoitti ankarasti heitä saattamasta häntä julki.'),
(1693244,58,41,3,13,'Ja hän nousi vuorelle ja kutsui tykönsä ne, jotka hän itse tahtoi, ja he menivät hänen tykönsä.'),
(1693245,58,41,3,14,'Niin hän asetti kaksitoista olemaan kanssansa ja lähettääksensä heidät saarnaamaan,'),
(1693246,58,41,3,15,'ja heillä oli oleva valta ajaa ulos riivaajia.'),
(1693247,58,41,3,16,'Ja nämä kaksitoista hän asetti: Pietarin - tämän nimen hän antoi Simonille -'),
(1693248,58,41,3,17,'ja Jaakobin, Sebedeuksen pojan, ja Johanneksen, Jaakobin veljen, joille hän antoi nimen Boanerges, se on: ukkosenjylinän pojat,'),
(1693249,58,41,3,18,'ja Andreaan ja Filippuksen ja Bartolomeuksen ja Matteuksen ja Tuomaan ja Jaakobin, Alfeuksen pojan, ja Taddeuksen ja Simon Kananeuksen'),
(1693250,58,41,3,19,'ja Juudas Iskariotin, saman, joka hänet kavalsi.'),
(1693251,58,41,3,20,'Ja hän tuli kotiin. Ja taas kokoontui kansaa, niin etteivät he päässeet syömäänkään.'),
(1693252,58,41,3,21,'Kun hänen omaisensa sen kuulivat, menivät he ottamaan häntä huostaansa; sillä he sanoivat: "Hän on poissa suunniltaan".'),
(1693253,58,41,3,22,'Ja kirjanoppineet, jotka olivat tulleet Jerusalemista, sanoivat: "Hänessä on Beelsebul", ja: "Riivaajien päämiehen voimalla hän ajaa ulos riivaajia".'),
(1693254,58,41,3,23,'Niin hän kutsui heidät luoksensa ja sanoi heille vertauksilla: "Kuinka saatana voi ajaa ulos saatanan?'),
(1693255,58,41,3,24,'Ja jos jokin valtakunta riitautuu itsensä kanssa, ei se valtakunta voi pysyä pystyssä.'),
(1693256,58,41,3,25,'Ja jos jokin talo riitautuu itsensä kanssa, ei se talo voi pysyä pystyssä.'),
(1693257,58,41,3,26,'Ja jos saatana nousee itseänsä vastaan ja riitautuu itsensä kanssa, ei hän voi pysyä, vaan hänen loppunsa on tullut.'),
(1693258,58,41,3,27,'Eihän kukaan voi tunkeutua väkevän taloon ja ryöstää hänen tavaraansa, ellei hän ensin sido sitä väkevää; vasta sitten hän ryöstää tyhjäksi hänen talonsa.'),
(1693259,58,41,3,28,'Totisesti minä sanon teille: kaikki synnit annetaan ihmisten lapsille anteeksi, pilkkaamisetkin, kuinka paljon pilkannevatkin;'),
(1693260,58,41,3,29,'mutta joka pilkkaa Pyhää Henkeä, se ei saa ikinä anteeksi, vaan on vikapää iankaikkiseen syntiin."'),
(1693261,58,41,3,30,'Sillä he sanoivat: "Hänessä on saastainen henki".'),
(1693262,58,41,3,31,'Ja hänen äitinsä ja veljensä tulivat, seisahtuivat ulkopuolelle ja lähettivät hänen luoksensa kutsumaan häntä.'),
(1693263,58,41,3,32,'Ja kansanjoukko istui hänen ympärillään, ja he sanoivat hänelle: "Katso, sinun äitisi ja veljesi tuolla ulkona kysyvät sinua".'),
(1693264,58,41,3,33,'Hän vastasi heille ja sanoi: "Kuka on minun äitini, ja ketkä ovat minun veljeni?"'),
(1693265,58,41,3,34,'Ja katsellen ympärilleen niihin, jotka istuivat hänen ympärillään, hän sanoi: "Katso, minun äitini ja veljeni!'),
(1693266,58,41,3,35,'Sillä joka tekee Jumalan tahdon, se on minun veljeni ja sisareni ja äitini."'),
(1693267,58,41,4,1,'Ja hän rupesi taas opettamaan järven rannalla. Ja hänen luoksensa kokoontui hyvin paljon kansaa, jonka tähden hän astui venheeseen ja istui siinä järvellä, ja kaikki kansa oli maalla järven rannalla.'),
(1693268,58,41,4,2,'Ja hän opetti heitä paljon vertauksilla ja sanoi heille opettaessaan:'),
(1693269,58,41,4,3,'"Kuulkaa! Katso, kylväjä lähti kylvämään.'),
(1693270,58,41,4,4,'Ja hänen kylväessään osa putosi tien oheen, ja linnut tulivat ja söivät sen.'),
(1693271,58,41,4,5,'Ja osa putosi kallioperälle, jossa sillä ei ollut paljon maata, ja se nousi kohta oraalle, kun sillä ei ollut syvää maata.'),
(1693272,58,41,4,6,'Mutta auringon noustua se paahtui, ja kun sillä ei ollut juurta, niin se kuivettui.'),
(1693273,58,41,4,7,'Ja osa putosi orjantappuroihin; ja orjantappurat nousivat ja tukahuttivat sen, eikä se tehnyt hedelmää.'),
(1693274,58,41,4,8,'Ja osa putosi hyvään maahan; ja se nousi oraalle, kasvoi ja antoi sadon ja kantoi kolmeenkymmeneen ja kuuteenkymmeneen ja sataan jyvään asti."'),
(1693275,58,41,4,9,'Ja hän sanoi: "Jolla on korvat kuulla, se kuulkoon".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693276,58,41,4,10,'Ja kun hän oli jäänyt yksin, niin ne, jotka olivat hänen ympärillään, ynnä ne kaksitoista kysyivät häneltä näitä vertauksia.'),
(1693277,58,41,4,11,'Niin hän sanoi heille: "Teille on annettu Jumalan valtakunnan salaisuus, mutta noille ulkopuolella oleville kaikki tulee vertauksissa,'),
(1693278,58,41,4,12,'että he näkemällä näkisivät, eivätkä huomaisi, ja kuulemalla kuulisivat, eivätkä ymmärtäisi, niin etteivät kääntyisi ja saisi anteeksi".'),
(1693279,58,41,4,13,'Ja hän sanoi heille: "Ette käsitä tätä vertausta; kuinka sitten voitte ymmärtää kaikki muut vertaukset?'),
(1693280,58,41,4,14,'Kylväjä kylvää sanan.'),
(1693281,58,41,4,15,'Mitkä tien oheen putosivat, ovat ne, joihin sana kylvetään, mutta kun he sen kuulevat, niin saatana heti tulee ja ottaa pois heihin kylvetyn sanan.'),
(1693282,58,41,4,16,'Ja mitkä kallioperälle kylvettiin, ovat niinikään ne, jotka, kun kuulevat sanan, heti ottavat sen ilolla vastaan,'),
(1693283,58,41,4,17,'mutta heillä ei ole juurta itsessään, vaan he kestävät ainoastaan jonkun aikaa; kun sitten tulee ahdistus tai vaino sanan tähden, niin he kohta lankeavat pois.'),
(1693284,58,41,4,18,'Ja toisia ovat orjantappuroihin kylvetyt; nämä ovat ne, jotka kuulevat sanan,'),
(1693285,58,41,4,19,'mutta maailman huolet ja rikkauden viettelys ja muut himot pääsevät valtaan ja tukahuttavat sanan, ja se jää hedelmättömäksi.'),
(1693286,58,41,4,20,'Ja mitkä hyvään maahan kylvettiin, ovat ne, jotka kuulevat sanan ja ottavat sen vastaan ja kantavat hedelmän, mikä kolmikymmen-, mikä kuusikymmen-, mikä satakertaisen."'),
(1693287,58,41,4,21,'Ja hän sanoi heille: "Eihän lamppua oteta esiin, pantavaksi vakan alle tai vuoteen alle? Eiköhän lampunjalkaan pantavaksi?'),
(1693288,58,41,4,22,'Sillä ei mikään ole salattuna muuta varten, kuin että se tulisi ilmi, eikä kätkettynä muuta varten, kuin tullakseen julki.'),
(1693289,58,41,4,23,'Jos jollakin on korvat kuulla, hän kuulkoon."'),
(1693290,58,41,4,24,'Ja hän sanoi heille: "Ottakaa vaari siitä, mitä kuulette; millä mitalla te mittaatte, sillä teille mitataan, vieläpä teille lisätäänkin.'),
(1693291,58,41,4,25,'Sillä sille jolla on, sille annetaan; mutta siltä, jolla ei ole, otetaan pois sekin, mikä hänellä on."'),
(1693292,58,41,4,26,'Ja hän sanoi: "Niin on Jumalan valtakunta, kuin jos mies kylvää siemenen maahan;'),
(1693293,58,41,4,27,'ja hän nukkuu, ja hän nousee, öin ja päivin; ja siemen orastaa ja kasvaa, hän ei itse tiedä, miten.'),
(1693294,58,41,4,28,'Sillä itsestään maa tuottaa viljan: ensin korren, sitten tähkän, sitten täyden jyvän tähkään.'),
(1693295,58,41,4,29,'Mutta kun hedelmä on kypsynyt, lähettää hän kohta sinne sirpin, sillä elonaika on käsissä."'),
(1693296,58,41,4,30,'Ja hän sanoi: "Mihin vertaamme Jumalan valtakunnan, eli mitä vertausta siitä käytämme?'),
(1693297,58,41,4,31,'Se on niinkuin sinapinsiemen, joka, kun se kylvetään maahan, on pienin kaikista siemenistä maan päällä;'),
(1693298,58,41,4,32,'mutta kun se on kylvetty, niin se nousee ja tulee suurimmaksi kaikista vihanneskasveista ja tekee suuria oksia, niin että taivaan linnut voivat tehdä pesänsä sen varjoon."'),
(1693299,58,41,4,33,'Monilla tämänkaltaisilla vertauksilla hän puhui heille sanaa, sen mukaan kuin he kykenivät kuulemaan;'),
(1693300,58,41,4,34,'ja ilman vertausta hän ei puhunut heille. Mutta opetuslapsillensa hän selitti kaikki, kun he olivat yksikseen.'),
(1693301,58,41,4,35,'Ja sinä päivänä hän illan tultua sanoi heille: "Lähtekäämme yli toiselle rannalle".'),
(1693302,58,41,4,36,'Niin he laskivat kansan luotaan ja ottivat hänet mukaansa, niinkuin hän venheessä oli; ja muitakin venheitä oli hänen seurassaan.'),
(1693303,58,41,4,37,'Ja nousi kova myrskytuuli, ja aallot syöksyivät venheeseen, niin että venhe jo täyttyi.'),
(1693304,58,41,4,38,'Ja itse hän oli peräkeulassa ja nukkui nojaten päänaluseen. Ja he herättivät hänet ja sanoivat hänelle: "Opettaja, etkö välitä siitä, että me hukumme?"'),
(1693305,58,41,4,39,'Ja herättyään hän nuhteli tuulta ja sanoi järvelle: "Vaikene, ole hiljaa". Niin tuuli asettui, ja tuli aivan tyven.'),
(1693306,58,41,4,40,'Ja hän sanoi heille: "Miksi olette niin pelkureita? Kuinka teillä ei ole uskoa?"'),
(1693307,58,41,4,41,'Ja suuri pelko valtasi heidät, ja he sanoivat toisillensa: "Kuka onkaan tämä, kun sekä tuuli että meri häntä tottelevat?"'),
(1693308,58,41,5,1,'Ja he tulivat toiselle puolelle järveä gerasalaisten alueelle.'),
(1693309,58,41,5,2,'Ja kohta kun hän lähti venheestä, tuli häntä vastaan haudoista mies, joka oli saastaisen hengen vallassa.'),
(1693310,58,41,5,3,'Hän asusti haudoissa, eikä kukaan enää voinut häntä kahleillakaan sitoa;'),
(1693311,58,41,5,4,'sillä hän oli monta kertaa ollut sidottuna jalkanuoriin ja kahleisiin, mutta oli särkenyt kahleet ja katkonut jalkanuorat, eikä kukaan kyennyt häntä hillitsemään.'),
(1693312,58,41,5,5,'Ja hän oleskeli aina, yötä ja päivää, haudoissa ja vuorilla, huutaen ja runnellen itseään kivillä.'),
(1693313,58,41,5,6,'Kun hän kaukaa näki Jeesuksen, juoksi hän ja kumartui maahan hänen eteensä'),
(1693314,58,41,5,7,'ja huutaen suurella äänellä sanoi: "Mitä sinulla on minun kanssani tekemistä, Jeesus, Jumalan, Korkeimman, Poika? Minä vannotan sinua Jumalan kautta, älä vaivaa minua."'),
(1693315,58,41,5,8,'Sillä hän oli sanomaisillaan sille: "Lähde ulos miehestä, sinä saastainen henki".'),
(1693316,58,41,5,9,'Ja Jeesus kysyi siltä: "Mikä on nimesi?" Niin se sanoi hänelle: "Legio on minun nimeni, sillä meitä on monta".'),
(1693317,58,41,5,10,'Ja se pyysi pyytämällä häntä, ettei hän lähettäisi niitä pois siitä seudusta.'),
(1693318,58,41,5,11,'Niin siellä oli lähellä vuorta suuri sikalauma laitumella.'),
(1693319,58,41,5,12,'Ja ne pyysivät häntä sanoen: "Lähetä meidät sikoihin, että menisimme niihin".'),
(1693320,58,41,5,13,'Ja hän antoi niille luvan. Niin saastaiset henget lähtivät miehestä ja menivät sikoihin. Silloin lauma, noin kaksituhatta sikaa, syöksyi jyrkännettä alas järveen; ja ne hukkuivat järveen.'),
(1693321,58,41,5,14,'Ja niiden paimentajat pakenivat ja kertoivat siitä kaupungissa ja maataloissa. Ja kansa lähti katsomaan, mitä oli tapahtunut.'),
(1693322,58,41,5,15,'Ja he tulivat Jeesuksen luo ja näkivät riivatun, jossa legio oli ollut, istuvan puettuna ja täydessä ymmärryksessään; ja he peljästyivät.'),
(1693323,58,41,5,16,'Näille kertoivat näkijät, mitä oli tapahtunut riivatulle ja kuinka sikojen oli käynyt.'),
(1693324,58,41,5,17,'Ja he alkoivat pyytää häntä poistumaan heidän alueeltaan.'),
(1693325,58,41,5,18,'Ja hänen astuessaan venheeseen se riivattuna ollut pyysi häneltä saada olla hänen kanssaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693326,58,41,5,19,'Mutta hän ei sitä sallinut, vaan sanoi hänelle: "Mene kotiisi omaistesi luo ja kerro heille, kuinka suuria tekoja Herra on sinulle tehnyt ja kuinka hän on sinua armahtanut".'),
(1693327,58,41,5,20,'Niin hän lähti ja rupesi Dekapolin alueella julistamaan, kuinka suuria tekoja Jeesus oli hänelle tehnyt; ja kaikki ihmettelivät.'),
(1693328,58,41,5,21,'Kun Jeesus oli venheellä kulkenut takaisin toiselle puolelle, kokoontui paljon kansaa hänen luoksensa, ja hän oli järven rannalla.'),
(1693329,58,41,5,22,'Niin tuli muuan synagoogan esimies, nimeltä Jairus, ja lankesi hänet nähdessään hänen jalkojensa juureen,'),
(1693330,58,41,5,23,'pyysi häntä hartaasti ja sanoi: "Pieni tyttäreni on kuolemaisillaan; tule ja pane kätesi hänen päällensä, että hän tulisi terveeksi ja jäisi eloon".'),
(1693331,58,41,5,24,'Niin hän lähti hänen kanssansa. Ja häntä seurasi suuri kansan paljous, ja he tunkeutuivat hänen ympärilleen.'),
(1693332,58,41,5,25,'Ja siellä oli nainen, joka oli sairastanut verenjuoksua kaksitoista vuotta'),
(1693333,58,41,5,26,'ja paljon kärsinyt monen lääkärin käsissä ja kuluttanut kaiken omaisuutensa saamatta mitään apua, pikemminkin käyden huonommaksi.'),
(1693334,58,41,5,27,'Tämä oli kuullut Jeesuksesta ja tuli kansanjoukossa takaapäin ja koski hänen vaippaansa;'),
(1693335,58,41,5,28,'sillä hän sanoi: "Kunhan vain saan koskettaa edes hänen vaatteitaan, niin tulen terveeksi".'),
(1693336,58,41,5,29,'Ja heti hänen verensä lähde kuivui, ja hän tunsi ruumiissansa, että oli parantunut vaivastaan.'),
(1693337,58,41,5,30,'Ja heti kun Jeesus itsessään tunsi, että voimaa oli hänestä lähtenyt, kääntyi hän väkijoukossa ja sanoi: "Kuka koski minun vaatteisiini?"'),
(1693338,58,41,5,31,'Niin hänen opetuslapsensa sanoivat hänelle: "Sinä näet kansanjoukon tungeskelevan ympärilläsi ja sanot: ''Kuka minuun koski?''"'),
(1693339,58,41,5,32,'Mutta hän katseli ympärilleen nähdäksensä, kuka sen oli tehnyt.'),
(1693340,58,41,5,33,'Niin nainen pelkäsi ja vapisi, koska hän tiesi, mitä hänelle oli tapahtunut, ja tuli ja lankesi maahan hänen eteensä ja sanoi hänelle koko totuuden.'),
(1693341,58,41,5,34,'Mutta Jeesus sanoi hänelle: "Tyttäreni, sinun uskosi on tehnyt sinut terveeksi. Mene rauhaan ja ole terve vaivastasi."'),
(1693342,58,41,5,35,'Hänen vielä puhuessaan tultiin synagoogan esimiehen kotoa sanomaan: "Tyttäresi kuoli; miksi enää opettajaa vaivaat?"'),
(1693343,58,41,5,36,'Mutta Jeesus ei ottanut kuullakseen, mitä puhuttiin, vaan sanoi synagoogan esimiehelle: "Älä pelkää, usko ainoastaan".'),
(1693344,58,41,5,37,'Ja hän ei sallinut kenenkään muun seurata mukanansa kuin Pietarin ja Jaakobin ja Johanneksen, Jaakobin veljen.'),
(1693345,58,41,5,38,'Ja he tulivat synagoogan esimiehen taloon; ja hän näki hälisevän joukon ja ääneensä itkeviä ja vaikeroivia.'),
(1693346,58,41,5,39,'Ja käydessään sisään hän sanoi heille: "Mitä te hälisette ja itkette? Lapsi ei ole kuollut, vaan nukkuu."'),
(1693347,58,41,5,40,'Niin he nauroivat häntä. Mutta hän ajoi kaikki ulos ja otti mukaansa lapsen isän ja äidin sekä ne, jotka olivat hänen kanssaan, ja meni sisälle sinne, missä lapsi makasi.'),
(1693348,58,41,5,41,'Ja hän tarttui lapsen käteen ja sanoi hänelle: "Talita kuum!" Se on käännettynä: Tyttö, minä sanon sinulle, nouse.'),
(1693349,58,41,5,42,'Ja heti tyttö nousi ja käveli. Sillä hän oli kaksitoistavuotias. Ja he joutuivat suuren hämmästyksen valtaan.'),
(1693350,58,41,5,43,'Ja hän kielsi ankarasti heitä antamasta kenellekään tietoa tästä ja käski antaa tytölle syötävää.'),
(1693351,58,41,6,1,'Ja hän lähti sieltä ja meni kotikaupunkiinsa, ja hänen opetuslapsensa seurasivat häntä.'),
(1693352,58,41,6,2,'Ja kun tuli sapatti, rupesi hän opettamaan synagoogassa; ja häntä kuullessaan monet hämmästyivät ja sanoivat: "Mistä tällä on kaikki tämä, ja mikä on se viisaus, joka on hänelle annettu? Ja mitä senkaltaiset voimalliset teot, jotka tapahtuvat hänen kättensä kautta?'),
(1693353,58,41,6,3,'Eikö tämä ole se rakentaja, Marian poika ja Jaakobin ja Jooseen ja Juudaan ja Simonin veli? Ja eivätkö hänen sisarensa ole täällä meidän parissamme?" Ja he loukkaantuivat häneen.'),
(1693354,58,41,6,4,'Niin Jeesus sanoi heille: "Ei ole profeetta halveksittu muualla kuin kotikaupungissaan ja sukulaistensa kesken ja kodissaan".'),
(1693355,58,41,6,5,'Ja hän ei voinut siellä tehdä mitään voimallista tekoa, paitsi että paransi joitakuita sairaita panemalla kätensä heidän päälleen.'),
(1693356,58,41,6,6,'Ja hän ihmetteli heidän epäuskoansa. Ja hän vaelsi ympäristössä, kulkien kylästä kylään, ja opetti.'),
(1693357,58,41,6,7,'Ja hän kutsui tykönsä ne kaksitoista ja alkoi lähettää heitä kaksittain ja antoi heille vallan saastaisia henkiä vastaan.'),
(1693358,58,41,6,8,'Ja hän sääti heille, etteivät saaneet ottaa matkalle muuta kuin ainoastaan sauvan; ei leipää, ei laukkua, ei rahaa vyöhönsä.'),
(1693359,58,41,6,9,'He saivat kuitenkin sitoa paula-anturat jalkaansa; "mutta älkää pukeko kahta ihokasta yllenne".'),
(1693360,58,41,6,10,'Ja hän sanoi heille: "Missä tulette taloon, jääkää siihen, kunnes lähdette pois siltä paikkakunnalta.'),
(1693361,58,41,6,11,'Ja missä paikassa teitä ei oteta vastaan eikä teitä kuulla, sieltä menkää pois ja pudistakaa tomu jalkojenne alta, todistukseksi heille."'),
(1693362,58,41,6,12,'Niin he lähtivät ja saarnasivat, että oli tehtävä parannus.'),
(1693363,58,41,6,13,'Ja he ajoivat ulos monta riivaajaa ja voitelivat monta sairasta öljyllä ja paransivat heidät.'),
(1693364,58,41,6,14,'Ja kuningas Herodes sai kuulla hänestä, sillä hänen nimensä oli tullut tunnetuksi, ja ihmiset sanoivat: "Johannes Kastaja on noussut kuolleista, ja sentähden nämä voimat hänessä vaikuttavat".'),
(1693365,58,41,6,15,'Mutta toiset sanoivat: "Se on Elias"; toiset taas sanoivat: "Se on profeetta, niinkuin joku muukin profeetoista".'),
(1693366,58,41,6,16,'Mutta kun Herodes sen kuuli, sanoi hän: "Johannes, jonka minä mestautin, on noussut kuolleista".'),
(1693367,58,41,6,17,'Sillä hän, Herodes, oli lähettänyt ottamaan kiinni Johanneksen, sitonut ja pannut hänet vankeuteen veljensä Filippuksen vaimon, Herodiaan, tähden. Sillä Herodes oli nainut hänet,'),
(1693368,58,41,6,18,'ja Johannes oli sanonut Herodekselle: "Sinun ei ole lupa pitää veljesi vaimoa".'),
(1693369,58,41,6,19,'Ja Herodias piti vihaa häntä vastaan ja tahtoi tappaa hänet, mutta ei voinut.'),
(1693370,58,41,6,20,'Sillä Herodes pelkäsi Johannesta, koska tiesi hänet vanhurskaaksi ja pyhäksi mieheksi, ja suojeli häntä. Ja kun hän kuunteli häntä, tuli hän epäröivälle mielelle monesta asiasta; ja hän kuunteli häntä mielellään.'),
(1693371,58,41,6,21,'Niin tuli sopiva päivä, kun Herodes syntymäpäivänään piti pitoja ylimyksilleen ja sotapäälliköille ja Galilean ensimmäisille miehille.'),
(1693372,58,41,6,22,'Ja Herodiaan tytär tuli sisälle ja tanssi, ja se miellytti Herodesta ja hänen pöytävieraitaan. Niin kuningas sanoi tytölle: "Ano minulta, mitä ikinä tahdot, niin minä annan sinulle".'),
(1693373,58,41,6,23,'Ja hän vannoi tytölle: "Mitä ikinä minulta anot, sen minä annan sinulle, vaikka puolet valtakuntaani".'),
(1693374,58,41,6,24,'Niin hän meni ulos ja sanoi äidilleen: "Mitä minä anon?" Tämä sanoi: "Johannes Kastajan päätä".'),
(1693375,58,41,6,25,'Ja hän meni kohta kiiruusti sisälle kuninkaan luo, pyysi ja sanoi: "Minä tahdon, että nyt heti annat minulle lautasella Johannes Kastajan pään".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693376,58,41,6,26,'Silloin kuningas tuli hyvin murheelliseksi, mutta valansa ja pöytävierasten tähden hän ei tahtonut hyljätä hänen pyyntöään.'),
(1693377,58,41,6,27,'Ja kohta kuningas lähetti henkivartijan ja käski tuoda Johanneksen pään.'),
(1693378,58,41,6,28,'Niin vartija meni ja löi häneltä pään poikki vankilassa ja toi hänen päänsä lautasella ja antoi sen tytölle, ja tyttö antoi sen äidillensä.'),
(1693379,58,41,6,29,'Kun hänen opetuslapsensa sen kuulivat, tulivat he ja ottivat hänen ruumiinsa ja panivat sen hautaan.'),
(1693380,58,41,6,30,'Ja apostolit kokoontuivat Jeesuksen tykö ja kertoivat hänelle kaikki, mitä olivat tehneet ja mitä olivat opettaneet.'),
(1693381,58,41,6,31,'Niin hän sanoi heille: "Tulkaa te yksinäisyyteen, autioon paikkaan, ja levähtäkää vähän". Sillä tulijoita ja menijöitä oli paljon, ja heillä ei ollut aikaa syödäkään.'),
(1693382,58,41,6,32,'Ja he lähtivät venheellä autioon paikkaan, yksinäisyyteen.'),
(1693383,58,41,6,33,'Ja he näkivät heidän lähtevän, ja monet saivat siitä tiedon ja riensivät sinne jalkaisin kaikista kaupungeista ja saapuivat ennen heitä.'),
(1693384,58,41,6,34,'Ja astuessaan maihin hän näki paljon kansaa, ja hänen kävi heitä sääliksi, koska he olivat niinkuin lampaat, joilla ei ole paimenta, ja hän rupesi opettamaan heille moninaisia.'),
(1693385,58,41,6,35,'Ja kun päivä jo oli pitkälle kulunut, menivät hänen opetuslapsensa hänen tykönsä ja sanoivat: "Tämä paikka on autio, ja aika on jo myöhäinen;'),
(1693386,58,41,6,36,'laske heidät luotasi, että he menisivät ympäristöllä oleviin maataloihin ja kyliin ostamaan itsellensä syötävää".'),
(1693387,58,41,6,37,'Mutta hän vastasi heille ja sanoi: "Antakaa te heille syödä". Niin he sanoivat hänelle: "Lähdemmekö ostamaan leipää kahdellasadalla denarilla antaaksemme heille syödä?"'),
(1693388,58,41,6,38,'Mutta hän sanoi heille: "Montako leipää teillä on? Menkää katsomaan." Otettuaan siitä selvän he sanoivat: "Viisi, ja kaksi kalaa".'),
(1693389,58,41,6,39,'Niin hän määräsi heille, että kaikkien oli asetuttava ruokakunnittain vihantaan ruohikkoon.'),
(1693390,58,41,6,40,'Ja he laskeutuivat ryhmä ryhmän viereen, toisiin sata, toisiin viisikymmentä.'),
(1693391,58,41,6,41,'Ja hän otti ne viisi leipää ja kaksi kalaa, katsoi ylös taivaaseen ja siunasi ja mursi leivät ja antoi ne opetuslapsilleen kansan eteen pantaviksi; myöskin ne kaksi kalaa hän jakoi kaikille.'),
(1693392,58,41,6,42,'Ja kaikki söivät ja tulivat ravituiksi.'),
(1693393,58,41,6,43,'Sitten he keräsivät palaset, kaksitoista täyttä vakallista, ja tähteet kaloista.'),
(1693394,58,41,6,44,'Ja niitä, jotka olivat syöneet näitä leipiä, oli viisituhatta miestä.'),
(1693395,58,41,6,45,'Ja kohta hän vaati opetuslapsiansa astumaan venheeseen ja kulkemaan edeltä toiselle rannalle, Beetsaidaan, sillä aikaa kuin hän laski kansan luotansa.'),
(1693396,58,41,6,46,'Ja sanottuaan heille jäähyväiset hän meni pois vuorelle rukoilemaan.'),
(1693397,58,41,6,47,'Ja kun ilta tuli, oli venhe keskellä järveä, ja hän oli yksinään maalla.'),
(1693398,58,41,6,48,'Ja kun hän näki heidän soutaessaan olevan hädässä, sillä tuuli oli heille vastainen, tuli hän neljännen yövartion vaiheilla heidän luoksensa kävellen järven päällä ja aikoi kulkea heidän ohitsensa.'),
(1693399,58,41,6,49,'Mutta nähdessään hänen kävelevän järven päällä he luulivat häntä aaveeksi ja rupesivat huutamaan;'),
(1693400,58,41,6,50,'sillä kaikki näkivät hänet ja peljästyivät. Mutta heti hän puhutteli heitä ja sanoi heille: "Olkaa turvallisella mielellä, minä se olen; älkää peljätkö".'),
(1693401,58,41,6,51,'Ja hän astui venheeseen heidän tykönsä, ja tuuli asettui. Niin he hämmästyivät ylen suuresti sydämessään.'),
(1693402,58,41,6,52,'Sillä he eivät olleet noista leivistäkään päässeet ymmärrykseen, vaan heidän sydämensä oli paatunut.'),
(1693403,58,41,6,53,'Ja kuljettuaan yli toiselle rannalle he tulivat Gennesaretiin ja laskivat maihin.'),
(1693404,58,41,6,54,'Ja heidän noustessaan venheestä kansa heti tunsi hänet;'),
(1693405,58,41,6,55,'ja he riensivät kiertämään koko sitä paikkakuntaa ja rupesivat vuoteilla kantamaan sairaita sinne, missä kuulivat hänen olevan.'),
(1693406,58,41,6,56,'Ja missä vain hän meni kyliin tai kaupunkeihin tai maataloihin, asetettiin sairaat aukeille paikoille ja pyydettiin häneltä, että he saisivat koskea edes hänen vaippansa tupsuun. Ja kaikki, jotka koskivat häneen, tulivat terveiksi.'),
(1693407,58,41,7,1,'Ja fariseukset ja muutamat kirjanoppineet, jotka olivat tulleet Jerusalemista, kokoontuivat hänen luoksensa.'),
(1693408,58,41,7,2,'Ja he näkivät, että muutamat hänen opetuslapsistaan söivät leipää epäpuhtailla, se on pesemättömillä, käsillä.'),
(1693409,58,41,7,3,'Sillä eivät fariseukset eivätkä ketkään juutalaiset syö, ennenkuin ovat tarkoin pesseet kätensä, noudattaen vanhinten perinnäissääntöä,'),
(1693410,58,41,7,4,'ja torilta tultuaan he eivät syö, ennenkuin ovat itseään vedellä vihmoneet; ja paljon muuta on, mitä he ovat ottaneet noudattaakseen, niinkuin maljain ja kiviastiain ja vaskiastiain pesemisiä.'),
(1693411,58,41,7,5,'Niin fariseukset ja kirjanoppineet kysyivät häneltä: "Miksi sinun opetuslapsesi eivät vaella vanhinten perinnäissäännön mukaan, vaan syövät leipää epäpuhtailla käsillä?"'),
(1693412,58,41,7,6,'Mutta hän sanoi heille: "Oikein Esaias on ennustanut teistä, ulkokullatuista, niinkuin kirjoitettu on: ''Tämä kansa kunnioittaa minua huulillaan, mutta heidän sydämensä on minusta kaukana;'),
(1693413,58,41,7,7,'mutta turhaan he palvelevat minua opettaen oppeja, jotka ovat ihmiskäskyjä''.'),
(1693414,58,41,7,8,'Te hylkäätte Jumalan käskyn ja noudatatte ihmisten perinnäissääntöä."'),
(1693415,58,41,7,9,'Ja hän sanoi heille: "Hyvin te kumoatte Jumalan käskyn noudattaaksenne omaa perinnäissääntöänne.'),
(1693416,58,41,7,10,'Sillä Mooses on sanonut: ''Kunnioita isääsi ja äitiäsi'', ja: ''Joka kiroaa isäänsä tai äitiänsä, sen pitää kuolemalla kuoleman''.'),
(1693417,58,41,7,11,'Mutta te sanotte, että jos ihminen sanoo isälleen tai äidilleen: ''Se, minkä sinä olisit saava minulta hyväksesi, on korban'' - se on uhrilahja --'),
(1693418,58,41,7,12,'ja niin te ette enää salli hänen antaa mitään avustusta isälleen tai äidilleen.'),
(1693419,58,41,7,13,'Te teette Jumalan sanan tyhjäksi perinnäissäännöllänne, jonka olette säätäneet. Ja paljon muuta samankaltaista te teette."'),
(1693420,58,41,7,14,'Ja hän kutsui taas kansan tykönsä ja sanoi heille: "Kuulkaa minua kaikki ja ymmärtäkää:'),
(1693421,58,41,7,15,'ei mikään, mikä ihmisen ulkopuolelta menee hänen sisäänsä, voi häntä saastuttaa, vaan mikä ihmisestä lähtee ulos, se saastuttaa ihmisen.'),
(1693422,58,41,7,16,'Jos jollakin on korvat kuulla, hän kuulkoon."'),
(1693423,58,41,7,17,'Ja kun hän kansasta erottuaan oli mennyt erääseen taloon, kysyivät hänen opetuslapsensa häneltä sitä vertausta.'),
(1693424,58,41,7,18,'Ja hän sanoi heille: "Niinkö ymmärtämättömiä tekin olette? Ettekö käsitä, ettei mikään, mikä ulkoapäin menee ihmiseen, voi häntä saastuttaa?'),
(1693425,58,41,7,19,'Sillä se ei mene hänen sydämeensä, vaan vatsaan, ja ulostuu." Näin hän sanoi kaikki ruuat puhtaiksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693426,58,41,7,20,'Ja hän sanoi: "Mikä ihmisestä lähtee ulos, se saastuttaa ihmisen.'),
(1693427,58,41,7,21,'Sillä sisästä, ihmisten sydämestä, lähtevät pahat ajatukset, haureudet, varkaudet, murhat,'),
(1693428,58,41,7,22,'aviorikokset, ahneus, häijyys, petollisuus, irstaus, pahansuonti, jumalanpilkka, ylpeys, mielettömyys.'),
(1693429,58,41,7,23,'Kaikki tämä paha lähtee sisästä ulos ja saastuttaa ihmisen."'),
(1693430,58,41,7,24,'Ja hän nousi ja lähti sieltä Tyyron ja Siidonin alueelle. Ja hän meni erääseen taloon eikä tahtonut, että kukaan saisi sitä tietää; mutta hän ei saanut olla salassa,'),
(1693431,58,41,7,25,'vaan heti kun eräs vaimo, jonka pienessä tyttäressä oli saastainen henki, kuuli hänestä, tuli hän ja lankesi hänen jalkojensa juureen.'),
(1693432,58,41,7,26,'Ja se vaimo oli kreikatar, syntyään syyrofoinikialainen; ja hän pyysi häntä ajamaan ulos riivaajan hänen tyttärestään.'),
(1693433,58,41,7,27,'Niin Jeesus sanoi hänelle: "Anna ensin lasten tulla ravituiksi; sillä ei ole soveliasta ottaa lasten leipää ja heittää penikoille".'),
(1693434,58,41,7,28,'Mutta hän vastasi ja sanoi hänelle: "Niin, Herra; mutta syöväthän penikatkin pöydän alla lasten muruja".'),
(1693435,58,41,7,29,'Ja hän sanoi vaimolle: "Tämän sanan tähden, mene; riivaaja on lähtenyt sinun tyttärestäsi".'),
(1693436,58,41,7,30,'Ja vaimo meni kotiinsa ja havaitsi lapsen makaavan vuoteella ja riivaajan lähteneen hänestä.'),
(1693437,58,41,7,31,'Ja hän lähti jälleen Tyyron alueelta ja kulkien Siidonin kautta tuli Galilean järven ääreen Dekapolin alueen keskitse.'),
(1693438,58,41,7,32,'Ja hänen tykönsä tuotiin kuuro, joka oli melkein mykkä, ja he pyysivät häntä panemaan kätensä hänen päälleen.'),
(1693439,58,41,7,33,'Niin hän otti hänet erilleen kansasta, pisti sormensa hänen korviinsa, sylki ja koski hänen kieleensä'),
(1693440,58,41,7,34,'ja katsahti ylös taivaaseen, huokasi ja sanoi hänelle: "Effata", se on: aukene.'),
(1693441,58,41,7,35,'Niin hänen korvansa aukenivat, ja hänen kielensä side irtautui, ja hän puhui selkeästi.'),
(1693442,58,41,7,36,'Ja Jeesus kielsi heitä sitä kenellekään sanomasta; mutta mitä enemmän hän heitä kielsi, sitä enemmän he julistivat.'),
(1693443,58,41,7,37,'Ja ihmiset hämmästyivät ylenmäärin ja sanoivat: "Hyvin hän on kaikki tehnyt: kuurot hän saa kuulemaan ja mykät puhumaan".'),
(1693444,58,41,8,1,'Niinä päivinä, kun paljon kansaa taas oli koolla eikä heillä ollut mitään syötävää, kutsui hän opetuslapsensa tykönsä ja sanoi heille:'),
(1693445,58,41,8,2,'"Minun käy sääliksi kansaa, sillä he ovat jo kolme päivää olleet minun tykönäni, eikä heillä ole mitään syötävää.'),
(1693446,58,41,8,3,'Ja jos minä lasken heidät menemään syömättä kotiinsa, niin he nääntyvät matkalla; sillä muutamat heistä ovat tulleet kaukaa."'),
(1693447,58,41,8,4,'Niin hänen opetuslapsensa vastasivat hänelle: "Mistä täällä erämaassa kukaan voi saada leipää näiden ravitsemiseksi?"'),
(1693448,58,41,8,5,'Hän kysyi heiltä: "Montako leipää teillä on?" He sanoivat: "Seitsemän".'),
(1693449,58,41,8,6,'Silloin hän käski kansan asettua maahan. Ja hän otti ne seitsemän leipää, kiitti, mursi ja antoi opetuslapsillensa, että he panisivat ne kansan eteen. Ja he panivat.'),
(1693450,58,41,8,7,'Heillä oli myös joitakuita kalasia; ja siunattuaan ne hän käski panna nekin kansan eteen.'),
(1693451,58,41,8,8,'Niin he söivät ja tulivat ravituiksi. Sitten he keräsivät jääneet palaset, seitsemän vasullista.'),
(1693452,58,41,8,9,'Ja heitä oli noin neljätuhatta. Ja hän laski heidät luotansa.'),
(1693453,58,41,8,10,'Ja kohta hän astui opetuslapsineen venheeseen ja meni Dalmanutan seuduille.'),
(1693454,58,41,8,11,'Ja fariseukset lähtivät sinne ja rupesivat väittelemään hänen kanssaan ja vaativat häneltä merkkiä taivaasta, kiusaten häntä.'),
(1693455,58,41,8,12,'Niin hän huokasi hengessään ja sanoi: "Miksi tämä sukupolvi vaatii merkkiä? Totisesti minä sanon teille: tälle sukupolvelle ei anneta merkkiä."'),
(1693456,58,41,8,13,'Ja hän jätti heidät ja astui taas venheeseen ja lähti pois toiselle rannalle.'),
(1693457,58,41,8,14,'Ja he olivat unhottaneet ottaa mukaansa leipää, eikä heillä ollut muassaan venheessä enempää kuin yksi leipä.'),
(1693458,58,41,8,15,'Ja hän käski heitä sanoen: "Varokaa ja kavahtakaa fariseusten hapatusta ja Herodeksen hapatusta".'),
(1693459,58,41,8,16,'Niin he puhuivat keskenään siitä, ettei heillä ollut leipää.'),
(1693460,58,41,8,17,'Kun Jeesus huomasi sen, sanoi hän heille: "Mitä puhutte siitä, ettei teillä ole leipää? Ettekö vielä käsitä ettekä ymmärrä? Onko teidän sydämenne paatunut?'),
(1693461,58,41,8,18,'Silmät teillä on, ettekö näe? Ja korvat teillä on, ettekö kuule? Ja ettekö muista:'),
(1693462,58,41,8,19,'kun minä mursin ne viisi leipää viidelletuhannelle, kuinka monta vakan täyttä palasia te keräsitte?" He sanoivat hänelle: "Kaksitoista".'),
(1693463,58,41,8,20,'"Ja kun minä mursin ne seitsemän leipää neljälletuhannelle, kuinka monta vasun täyttä palasia te keräsitte?" He sanoivat: "Seitsemän".'),
(1693464,58,41,8,21,'Niin hän sanoi heille: "Ettekö vieläkään ymmärrä?"'),
(1693465,58,41,8,22,'Ja he tulivat Beetsaidaan. Ja hänen tykönsä tuotiin sokea, ja he pyysivät, että hän koskisi häneen.'),
(1693466,58,41,8,23,'Niin hän tarttui sokean käteen, talutti hänet kylän ulkopuolelle, sylki hänen silmiinsä ja pani kätensä hänen päälleen ja kysyi häneltä: "Näetkö mitään?"'),
(1693467,58,41,8,24,'Tämä katsahti ylös ja sanoi: "Näen ihmiset, sillä minä erotan käveleviä, ne ovat puiden näköisiä".'),
(1693468,58,41,8,25,'Sitten hän taas pani kätensä hänen silmilleen; ja nyt mies näki tarkkaan ja oli parantunut ja näki kaikki aivan selvästi.'),
(1693469,58,41,8,26,'Ja hän lähetti hänet hänen kotiinsa sanoen: "Älä edes poikkea kylään".'),
(1693470,58,41,8,27,'Ja Jeesus lähti opetuslapsinensa Filippuksen Kesarean kyliin. Ja tiellä hän kysyi opetuslapsiltaan ja sanoi heille: "Kenen ihmiset sanovat minun olevan?"'),
(1693471,58,41,8,28,'He vastasivat hänelle sanoen: "Johannes Kastajan, ja toiset Eliaan, toiset taas jonkun profeetoista".'),
(1693472,58,41,8,29,'Niin hän kysyi heiltä: "Kenenkä te sanotte minun olevan?" Pietari vastasi ja sanoi hänelle: "Sinä olet Kristus".'),
(1693473,58,41,8,30,'Ja hän varoitti vakavasti heitä puhumasta kenellekään hänestä.'),
(1693474,58,41,8,31,'Ja hän alkoi opettaa heille, että Ihmisen Pojan piti kärsimän paljon ja joutuman vanhinten ja ylipappien ja kirjanoppineiden hyljittäväksi ja tuleman tapetuksi, ja kolmen päivän perästä nouseman ylös.'),
(1693475,58,41,8,32,'Ja tämän hän puhui peittelemättä. Silloin Pietari otti hänet erilleen ja rupesi häntä nuhtelemaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693476,58,41,8,33,'Mutta hän kääntyi, katsoi opetuslapsiinsa ja nuhteli Pietaria sanoen: "Mene pois minun edestäni, saatana, sillä sinä et ajattele sitä, mikä on Jumalan, vaan sitä, mikä on ihmisten".'),
(1693477,58,41,8,34,'Ja hän kutsui tykönsä kansan ynnä opetuslapsensa ja sanoi heille: "Jos joku tahtoo minun perässäni kulkea, hän kieltäköön itsensä ja ottakoon ristinsä ja seuratkoon minua.'),
(1693478,58,41,8,35,'Sillä joka tahtoo pelastaa elämänsä, hän kadottaa sen, mutta joka kadottaa elämänsä minun ja evankeliumin tähden, hän pelastaa sen.'),
(1693479,58,41,8,36,'Sillä mitä se hyödyttää ihmistä, vaikka hän voittaisi omaksensa koko maailman, mutta saisi vahingon sielullensa?'),
(1693480,58,41,8,37,'Sillä mitä voi ihminen antaa sielunsa lunnaiksi?'),
(1693481,58,41,8,38,'Sillä joka häpeää minua ja minun sanojani tässä avionrikkojassa ja syntisessä sukupolvessa, sitä myös Ihmisen Poika on häpeävä, kun hän tulee Isänsä kirkkaudessa pyhien enkelien kanssa."'),
(1693482,58,41,9,1,'Ja hän sanoi heille: "Totisesti minä sanon teille: tässä seisovien joukossa on muutamia, jotka eivät maista kuolemaa, ennenkuin näkevät Jumalan valtakunnan tulevan voimassansa".'),
(1693483,58,41,9,2,'Ja kuuden päivän kuluttua Jeesus otti mukaansa Pietarin ja Jaakobin ja Johanneksen ja vei heidät erilleen muista korkealle vuorelle, yksinäisyyteen. Ja hänen muotonsa muuttui heidän edessään;'),
(1693484,58,41,9,3,'ja hänen vaatteensa tulivat hohtaviksi, niin ylen valkoisiksi, ettei kukaan vaatteenvalkaisija maan päällä taida semmoiseksi valkaista.'),
(1693485,58,41,9,4,'Ja heille ilmestyivät Elias ynnä Mooses, ja nämä puhuivat Jeesuksen kanssa.'),
(1693486,58,41,9,5,'Niin Pietari rupesi puhumaan ja sanoi Jeesukselle: "Rabbi, meidän on tässä hyvä olla; tehkäämme siis kolme majaa, sinulle yksi ja Moosekselle yksi ja Eliaalle yksi".'),
(1693487,58,41,9,6,'Sillä hän ei tiennyt, mitä sanoa, koska he olivat peljästyksissään.'),
(1693488,58,41,9,7,'Ja tuli pilvi, joka peitti heidät varjoonsa, ja pilvestä kuului ääni: "Tämä on minun rakas Poikani; kuulkaa häntä".'),
(1693489,58,41,9,8,'Ja yhtäkkiä, kun he katsahtivat ympärilleen, eivät he enää nähneet ketään muuta kuin Jeesuksen, joka yksinänsä oli heidän kanssaan.'),
(1693490,58,41,9,9,'Ja heidän kulkiessaan alas vuorelta hän teroitti heille, etteivät kenellekään kertoisi, mitä olivat nähneet, ennenkuin vasta sitten, kun Ihmisen Poika oli noussut kuolleista.'),
(1693491,58,41,9,10,'Ja he pitivät mielessään sen sanan ja tutkistelivat keskenään, mitä kuolleista nouseminen oli.'),
(1693492,58,41,9,11,'Ja he kysyivät häneltä sanoen: "Kirjanoppineethan sanovat, että Eliaan pitää tuleman ensin?"'),
(1693493,58,41,9,12,'Niin hän sanoi heille: "Elias tosin tulee ensin ja asettaa kaikki kohdalleen. Mutta kuinka sitten on kirjoitettu Ihmisen Pojasta, että hän on paljon kärsivä ja tuleva halveksituksi?'),
(1693494,58,41,9,13,'Mutta minä sanon teille: Elias onkin tullut, ja he tekivät hänelle, mitä tahtoivat, niinkuin hänestä on kirjoitettu."'),
(1693495,58,41,9,14,'Ja kun he tulivat opetuslasten luo, näkivät he paljon kansaa heidän ympärillään ja kirjanoppineita väittelemässä heidän kanssaan.'),
(1693496,58,41,9,15,'Ja kohta kun kaikki kansa hänet näki, hämmästyivät he ja riensivät hänen luoksensa ja tervehtivät häntä.'),
(1693497,58,41,9,16,'Ja hän kysyi heiltä: "Mitä te väittelette heidän kanssaan?"'),
(1693498,58,41,9,17,'Silloin vastasi eräs mies kansanjoukosta hänelle: "Opettaja, minä toin sinun tykösi poikani, jossa on mykkä henki.'),
(1693499,58,41,9,18,'Ja missä vain se käy hänen kimppuunsa, riuhtoo se häntä, ja hänestä lähtee vaahto, ja hän kiristelee hampaitaan; ja hän kuihtuu. Ja minä sanoin sinun opetuslapsillesi, että he ajaisivat sen ulos, mutta he eivät kyenneet."'),
(1693500,58,41,9,19,'Hän vastasi heille sanoen: "Voi, sinä epäuskoinen sukupolvi, kuinka kauan minun täytyy olla teidän luonanne? Kuinka kauan kärsiä teitä? Tuokaa hänet minun tyköni."'),
(1693501,58,41,9,20,'Niin he toivat hänet hänen tykönsä. Ja heti kun hän näki Jeesuksen, kouristi henki häntä, ja hän kaatui maahan, kieritteli itseään, ja hänestä lähti vaahto.'),
(1693502,58,41,9,21,'Ja Jeesus kysyi hänen isältään: "Kuinka kauan aikaa tätä on hänessä ollut?" Niin hän sanoi: "Pienestä pitäen.'),
(1693503,58,41,9,22,'Ja monesti se on heittänyt hänet milloin tuleen, milloin veteen, tuhotakseen hänet. Mutta jos sinä jotakin voit, niin armahda meitä ja auta meitä."'),
(1693504,58,41,9,23,'Niin Jeesus sanoi hänelle: "''Jos voit!'' Kaikki on mahdollista sille, joka uskoo".'),
(1693505,58,41,9,24,'Ja heti lapsen isä huusi ja sanoi: "Minä uskon; auta minun epäuskoani".'),
(1693506,58,41,9,25,'Mutta kun Jeesus näki, että kansaa riensi sinne, nuhteli hän saastaista henkeä ja sanoi sille: "Sinä mykkä ja kuuro henki, minä käsken sinua: lähde ulos hänestä, äläkä enää häneen mene".'),
(1693507,58,41,9,26,'Niin se huusi ja kouristi häntä kovasti ja lähti ulos. Ja hän kävi ikäänkuin kuolleeksi, niin että monet sanoivat: "Hän kuoli".'),
(1693508,58,41,9,27,'Mutta Jeesus tarttui hänen käteensä ja nosti hänet ylös. Ja hän nousi.'),
(1693509,58,41,9,28,'Ja kun Jeesus oli mennyt huoneeseen, niin hänen opetuslapsensa kysyivät häneltä eriksensä: "Miksi emme me voineet ajaa sitä ulos?"'),
(1693510,58,41,9,29,'Hän sanoi heille: "Tätä lajia ei saa lähtemään ulos muulla kuin rukouksella ja paastolla".'),
(1693511,58,41,9,30,'Ja he lähtivät sieltä ja kulkivat Galilean läpi; ja hän ei tahtonut, että kukaan saisi sitä tietää.'),
(1693512,58,41,9,31,'Sillä hän opetti opetuslapsiaan ja sanoi heille: "Ihmisen Poika annetaan ihmisten käsiin, ja he tappavat hänet; ja kun hän on tapettu, nousee hän kolmen päivän perästä ylös".'),
(1693513,58,41,9,32,'Mutta he eivät käsittäneet sitä puhetta ja pelkäsivät häneltä kysyä.'),
(1693514,58,41,9,33,'Ja he saapuivat Kapernaumiin. Ja kotiin tultuaan hän kysyi heiltä: "Mistä te tiellä keskustelitte?"'),
(1693515,58,41,9,34,'Mutta he olivat vaiti; sillä he olivat tiellä keskustelleet toistensa kanssa siitä, kuka oli suurin.'),
(1693516,58,41,9,35,'Ja hän istuutui, kutsui ne kaksitoista ja sanoi heille: "Jos joku tahtoo olla ensimmäinen, on hänen oltava kaikista viimeinen ja kaikkien palvelija".'),
(1693517,58,41,9,36,'Ja hän otti lapsen ja asetti sen heidän keskellensä; ja otettuaan sen syliinsä hän sanoi heille:'),
(1693518,58,41,9,37,'"Joka ottaa tykönsä yhden tämänkaltaisen lapsen minun nimeeni, se ottaa tykönsä minut; ja joka minut ottaa tykönsä, se ei ota tykönsä minua, vaan hänet, joka on minut lähettänyt".'),
(1693519,58,41,9,38,'Johannes sanoi hänelle: "Opettaja, me näimme erään, joka ei seuraa meitä, sinun nimessäsi ajavan ulos riivaajia; ja me kielsimme häntä, koska hän ei seurannut meitä".'),
(1693520,58,41,9,39,'Mutta Jeesus sanoi: "Älkää häntä kieltäkö; sillä ei kukaan, joka tekee voimallisen teon minun nimeeni, voi kohta sen jälkeen puhua minusta pahaa.'),
(1693521,58,41,9,40,'Sillä joka ei ole meitä vastaan, se on meidän puolellamme.'),
(1693522,58,41,9,41,'Sillä joka antaa teille juodaksenne maljallisen vettä siinä nimessä, että te olette Kristuksen omia, totisesti minä sanon teille: se ei jää palkkaansa vaille.'),
(1693523,58,41,9,42,'Ja joka viettelee yhden näistä pienistä, jotka uskovat, sen olisi parempi, että myllynkivi olisi pantu hänen kaulaansa ja hänet olisi heitetty mereen.'),
(1693524,58,41,9,43,'Ja jos sinun kätesi viettelee sinua, hakkaa se poikki. Parempi on sinulle, että käsipuolena menet elämään sisälle, kuin että, molemmat kädet tallella, joudut helvettiin, sammumattomaan tuleen.'),
(1693525,58,41,9,45,'Ja jos sinun jalkasi viettelee sinua, hakkaa se poikki. Parempi on sinulle, että jalkapuolena menet elämään sisälle, kuin että sinut, molemmat jalat tallella, heitetään helvettiin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693526,58,41,9,47,'Ja jos sinun silmäsi viettelee sinua, heitä se pois. Parempi on sinulle, että silmäpuolena menet sisälle Jumalan valtakuntaan, kuin että sinut, molemmat silmät tallella, heitetään helvettiin,'),
(1693527,58,41,9,48,'jossa heidän matonsa ei kuole eikä tuli sammu.'),
(1693528,58,41,9,49,'Sillä jokainen ihminen on tulella suolattava, ja jokainen uhri on suolalla suolattava.'),
(1693529,58,41,9,50,'Suola on hyvä; mutta jos suola käy suolattomaksi, millä te sen maustatte? Olkoon teillä suola itsessänne, ja pitäkää keskenänne rauha."'),
(1693530,58,41,10,1,'Ja hän nousi sieltä ja tuli Juudean alueelle, kulkien Jordanin toista puolta. Ja taas kokoontui paljon kansaa hänen luoksensa, ja tapansa mukaan hän taas opetti heitä.'),
(1693531,58,41,10,2,'Ja fariseuksia tuli hänen luoksensa, ja kiusaten häntä he kysyivät häneltä, oliko miehen lupa hyljätä vaimonsa.'),
(1693532,58,41,10,3,'Hän vastasi ja sanoi heille: "Mitä Mooses on teille säätänyt?"'),
(1693533,58,41,10,4,'He sanoivat: "Mooses salli kirjoittaa erokirjan ja hyljätä vaimon".'),
(1693534,58,41,10,5,'Niin Jeesus sanoi heille: "Teidän sydämenne kovuuden tähden hän kirjoitti teille tämän säädöksen.'),
(1693535,58,41,10,6,'Mutta luomakunnan alusta Jumala ''on luonut heidät mieheksi ja naiseksi.'),
(1693536,58,41,10,7,'Sentähden mies luopukoon isästänsä ja äidistänsä ja liittyköön vaimoonsa.'),
(1693537,58,41,10,8,'Ja ne kaksi tulevat yhdeksi lihaksi.'' Niin eivät he enää ole kaksi, vaan yksi liha.'),
(1693538,58,41,10,9,'Minkä siis Jumala on yhdistänyt, sitä älköön ihminen erottako."'),
(1693539,58,41,10,10,'Ja heidän mentyään huoneeseen opetuslapset taas kysyivät häneltä tätä asiaa.'),
(1693540,58,41,10,11,'Ja hän sanoi heille: "Joka hylkää vaimonsa ja nai toisen, se tekee huorin häntä vastaan.'),
(1693541,58,41,10,12,'Ja jos vaimo hylkää miehensä ja menee naimisiin toisen kanssa, niin hän tekee huorin."'),
(1693542,58,41,10,13,'Ja he toivat hänen tykönsä lapsia, että hän koskisi heihin; mutta opetuslapset nuhtelivat tuojia.'),
(1693543,58,41,10,14,'Mutta kun Jeesus sen näki, närkästyi hän ja sanoi heille: "Sallikaa lasten tulla minun tyköni, älkääkä estäkö heitä, sillä senkaltaisten on Jumalan valtakunta.'),
(1693544,58,41,10,15,'Totisesti minä sanon teille: joka ei ota vastaan Jumalan valtakuntaa niinkuin lapsi, se ei pääse sinne sisälle."'),
(1693545,58,41,10,16,'Ja hän otti heitä syliinsä, pani kätensä heidän päällensä ja siunasi heitä.'),
(1693546,58,41,10,17,'Ja hänen sieltä tielle mennessään juoksi muuan hänen luoksensa, polvistui hänen eteensä ja kysyi häneltä: "Hyvä opettaja, mitä minun pitää tekemän, että minä iankaikkisen elämän perisin?"'),
(1693547,58,41,10,18,'Mutta Jeesus sanoi hänelle: "Miksi sanot minua hyväksi? Ei kukaan ole hyvä paitsi Jumala yksin.'),
(1693548,58,41,10,19,'Käskyt sinä tiedät: ''Älä tapa'', ''Älä tee huorin'', ''Älä varasta'', ''Älä sano väärää todistusta'', ''Älä toiselta anasta'', ''Kunnioita isääsi ja äitiäsi''."'),
(1693549,58,41,10,20,'Mutta hän sanoi hänelle: "Opettaja, niitä kaikkia minä olen noudattanut nuoruudestani asti".'),
(1693550,58,41,10,21,'Niin Jeesus katsoi häneen ja rakasti häntä ja sanoi hänelle: "Yksi sinulta puuttuu: mene, myy kaikki, mitä sinulla on, ja anna köyhille, niin sinulla on oleva aarre taivaassa; ja tule ja seuraa minua".'),
(1693551,58,41,10,22,'Mutta hän synkistyi siitä puheesta ja meni pois murheellisena, sillä hänellä oli paljon omaisuutta.'),
(1693552,58,41,10,23,'Silloin Jeesus katsoi ympärilleen ja sanoi opetuslapsillensa: "Kuinka vaikea onkaan niiden, joilla on tavaraa, päästä Jumalan valtakuntaan!"'),
(1693553,58,41,10,24,'Niin opetuslapset hämmästyivät hänen sanoistaan. Mutta Jeesus rupesi taas puhumaan ja sanoi heille: "Lapset, kuinka vaikea onkaan niiden, jotka luottavat tavaraansa, päästä Jumalan valtakuntaan!'),
(1693554,58,41,10,25,'Helpompi on kamelin käydä neulansilmän läpi kuin rikkaan päästä Jumalan valtakuntaan."'),
(1693555,58,41,10,26,'Niin he hämmästyivät yhä enemmän ja sanoivat toisillensa: "Kuka sitten voi pelastua?"'),
(1693556,58,41,10,27,'Jeesus katsoi heihin ja sanoi: "Ihmisille se on mahdotonta, mutta ei Jumalalle; sillä Jumalalle on kaikki mahdollista".'),
(1693557,58,41,10,28,'Niin Pietari rupesi puhumaan sanoen hänelle: "Katso, me olemme luopuneet kaikesta ja seuranneet sinua".'),
(1693558,58,41,10,29,'Jeesus sanoi: "Totisesti minä sanon teille: ei ole ketään, joka minun tähteni ja evankeliumin tähden on luopunut talosta tai veljistä tai sisarista tai äidistä tai isästä tai lapsista tai pelloista,'),
(1693559,58,41,10,30,'ja joka ei saisi satakertaisesti: nyt tässä ajassa taloja ja veljiä ja sisaria ja äitejä ja lapsia ja peltoja, vainojen keskellä, ja tulevassa maailmassa iankaikkista elämää.'),
(1693560,58,41,10,31,'Mutta monet ensimmäiset tulevat viimeisiksi ja viimeiset ensimmäisiksi."'),
(1693561,58,41,10,32,'Ja he olivat matkalla, menossa ylös Jerusalemiin, ja Jeesus kulki heidän edellään; ja heidät valtasi hämmästys, ja ne, jotka seurasivat, olivat peloissaan. Ja hän otti taas tykönsä ne kaksitoista ja rupesi heille puhumaan, mitä hänelle oli tapahtuva:'),
(1693562,58,41,10,33,'"Katso, me menemme ylös Jerusalemiin, ja Ihmisen Poika annetaan ylipappien ja kirjanoppineitten käsiin, ja he tuomitsevat hänet kuolemaan ja antavat hänet pakanain käsiin;'),
(1693563,58,41,10,34,'ja ne pilkkaavat häntä ja sylkevät häntä ja ruoskivat häntä ja tappavat hänet; ja kolmen päivän perästä hän on nouseva ylös".'),
(1693564,58,41,10,35,'Ja Jaakob ja Johannes, Sebedeuksen pojat, menivät hänen luoksensa ja sanoivat hänelle: "Opettaja, me tahtoisimme, että tekisit meille, mitä sinulta anomme".'),
(1693565,58,41,10,36,'Hän sanoi heille: "Mitä tahdotte, että minä teille tekisin?"'),
(1693566,58,41,10,37,'Niin he sanoivat hänelle: "Anna meidän istua, toisen oikealla ja toisen vasemmalla puolellasi, sinun kirkkaudessasi".'),
(1693567,58,41,10,38,'Mutta Jeesus sanoi heille: "Te ette tiedä, mitä anotte. Voitteko juoda sen maljan, jonka minä juon, tahi tulla kastetuiksi sillä kasteella, jolla minut kastetaan?"'),
(1693568,58,41,10,39,'He sanoivat hänelle: "Voimme". Niin Jeesus sanoi heille: "Sen maljan, jonka minä juon, te tosin juotte, ja sillä kasteella, jolla minut kastetaan, kastetaan teidätkin;'),
(1693569,58,41,10,40,'mutta minun oikealla tai vasemmalla puolellani istuminen ei ole minun annettavissani, vaan se annetaan niille, joille se on valmistettu".'),
(1693570,58,41,10,41,'Kun ne kymmenen sen kuulivat, alkoivat he närkästyä Jaakobiin ja Johannekseen.'),
(1693571,58,41,10,42,'Mutta Jeesus kutsui heidät tykönsä ja sanoi heille: "Te tiedätte, että ne, joita kansojen ruhtinaiksi katsotaan, herroina niitä hallitsevat, ja että kansojen mahtavat käyttävät valtaansa niitä kohtaan.'),
(1693572,58,41,10,43,'Mutta näin ei ole teidän kesken, vaan joka teidän keskuudessanne tahtoo suureksi tulla, se olkoon teidän palvelijanne;'),
(1693573,58,41,10,44,'ja joka teidän keskuudessanne tahtoo olla ensimmäinen, se olkoon kaikkien orja.'),
(1693574,58,41,10,45,'Sillä ei Ihmisen Poikakaan tullut palveltavaksi, vaan palvelemaan ja antamaan henkensä lunnaiksi monen edestä."'),
(1693575,58,41,10,46,'Ja he tulivat Jerikoon. Ja kun hän vaelsi Jerikosta opetuslastensa ja suuren väkijoukon seuraamana, istui sokea kerjäläinen, Bartimeus, Timeuksen poika, tien vieressä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693576,58,41,10,47,'Ja kun hän kuuli, että se oli Jeesus Nasaretilainen, rupesi hän huutamaan ja sanomaan: "Jeesus, Daavidin poika, armahda minua".'),
(1693577,58,41,10,48,'Ja monet nuhtelivat häntä saadakseen hänet vaikenemaan. Mutta hän huusi vielä enemmän: "Daavidin poika, armahda minua".'),
(1693578,58,41,10,49,'Silloin Jeesus seisahtui ja sanoi: "Kutsukaa hänet tänne". Ja he kutsuivat sokean, sanoen hänelle: "Ole turvallisella mielellä, nouse; hän kutsuu sinua".'),
(1693579,58,41,10,50,'Niin hän heitti vaippansa päältään, kavahti seisomaan ja tuli Jeesuksen tykö.'),
(1693580,58,41,10,51,'Ja Jeesus puhutteli häntä sanoen: "Mitä tahdot, että minä sinulle tekisin?" Niin sokea sanoi hänelle: "Rabbuuni, että saisin näköni jälleen".'),
(1693581,58,41,10,52,'Niin Jeesus sanoi hänelle: "Mene, sinun uskosi on sinut pelastanut". Ja kohta hän sai näkönsä ja seurasi häntä tiellä.'),
(1693582,58,41,11,1,'Ja kun he lähestyivät Jerusalemia, tullen Beetfageen ja Betaniaan Öljymäelle, lähetti hän kaksi opetuslastaan'),
(1693583,58,41,11,2,'ja sanoi heille: "Menkää kylään, joka on edessänne, niin te kohta, kun sinne tulette, löydätte sidottuna varsan, jonka selässä ei yksikään ihminen vielä ole istunut; päästäkää se ja tuokaa tänne.'),
(1693584,58,41,11,3,'Ja jos joku teille sanoo: ''Miksi te noin teette?'', niin sanokaa: ''Herra tarvitsee sitä ja lähettää sen kohta tänne takaisin''."'),
(1693585,58,41,11,4,'Niin he menivät ja löysivät oven eteen ulos kujalle sidotun varsan ja päästivät sen.'),
(1693586,58,41,11,5,'Ja muutamat niistä, jotka siellä seisoivat, sanoivat heille: "Mitä te teette, kun päästätte varsan?"'),
(1693587,58,41,11,6,'Niin he sanoivat heille, niinkuin Jeesus oli käskenyt; ja he antoivat heidän mennä.'),
(1693588,58,41,11,7,'Ja he toivat varsan Jeesuksen luo ja heittivät vaatteensa sen päälle, ja hän istui sen selkään.'),
(1693589,58,41,11,8,'Ja monet levittivät vaatteensa tielle, ja toiset lehviä, joita katkoivat kedoilta.'),
(1693590,58,41,11,9,'Ja ne, jotka kulkivat edellä, ja jotka seurasivat, huusivat: "Hoosianna, siunattu olkoon hän, joka tulee Herran nimeen!'),
(1693591,58,41,11,10,'Siunattu olkoon isämme Daavidin valtakunta, joka tulee. Hoosianna korkeuksissa!"'),
(1693592,58,41,11,11,'Ja hän kulki sisälle Jerusalemiin ja meni pyhäkköön; ja katseltuaan kaikkea hän lähti niiden kahdentoista kanssa Betaniaan, sillä aika oli jo myöhäinen.'),
(1693593,58,41,11,12,'Kun he seuraavana päivänä lähtivät Betaniasta, oli hänen nälkä.'),
(1693594,58,41,11,13,'Ja kun hän kaukaa näki viikunapuun, jossa oli lehtiä, meni hän katsomaan, löytäisikö ehkä jotakin siitä; mutta tultuaan sen luo hän ei löytänyt muuta kuin lehtiä. Sillä silloin ei ollut viikunain aika.'),
(1693595,58,41,11,14,'Niin hän puhui ja sanoi sille: "Älköön ikinä enää kukaan sinusta hedelmää syökö". Ja hänen opetuslapsensa kuulivat sen.'),
(1693596,58,41,11,15,'Ja he tulivat Jerusalemiin. Ja hän meni pyhäkköön ja rupesi ajamaan ulos niitä, jotka myivät ja ostivat pyhäkössä, ja kaatoi kumoon rahanvaihtajain pöydät ja kyyhkysten myyjäin istuimet,'),
(1693597,58,41,11,16,'eikä sallinut kenenkään kantaa mitään astiaa pyhäkön kautta.'),
(1693598,58,41,11,17,'Ja hän opetti ja sanoi heille: "Eikö ole kirjoitettu: ''Minun huoneeni on kutsuttava kaikkien kansojen rukoushuoneeksi''? Mutta te olette tehneet siitä ryövärien luolan."'),
(1693599,58,41,11,18,'Ja ylipapit ja kirjanoppineet kuulivat sen ja miettivät, kuinka saisivat hänet surmatuksi; sillä he pelkäsivät häntä, koska kaikki kansa oli hämmästyksissään hänen opetuksestansa.'),
(1693600,58,41,11,19,'Illan tultua he menivät kaupungin ulkopuolelle.'),
(1693601,58,41,11,20,'Ja kun he varhain aamulla kulkivat ohi, näkivät he viikunapuun kuivettuneen juuria myöten.'),
(1693602,58,41,11,21,'Silloin Pietari muisti Jeesuksen sanat ja sanoi hänelle: "Rabbi, katso, viikunapuu, jonka sinä kirosit, on kuivettunut".'),
(1693603,58,41,11,22,'Jeesus vastasi ja sanoi heille: "Pitäkää usko Jumalaan.'),
(1693604,58,41,11,23,'Totisesti minä sanon teille: jos joku sanoisi tälle vuorelle: ''Kohoa ja heittäydy mereen'', eikä epäilisi sydämessään, vaan uskoisi sen tapahtuvan, minkä hän sanoo, niin se hänelle tapahtuisi.'),
(1693605,58,41,11,24,'Sentähden minä sanon teille: kaikki, mitä te rukoilette ja anotte, uskokaa saaneenne, niin se on teille tuleva.'),
(1693606,58,41,11,25,'Ja kun te seisotte ja rukoilette, niin antakaa anteeksi, jos kenellä teistä on jotakin toistansa vastaan, että myös teidän Isänne, joka on taivaissa, antaisi teille anteeksi teidän rikkomuksenne."'),
(1693607,58,41,11,27,'Ja he tulivat taas Jerusalemiin. Ja kun hän käveli pyhäkössä, tulivat ylipapit ja kirjanoppineet ja vanhimmat hänen luoksensa'),
(1693608,58,41,11,28,'ja sanoivat hänelle: "Millä vallalla sinä näitä teet? Tahi kuka sinulle on antanut vallan näitä tehdä?"'),
(1693609,58,41,11,29,'Mutta Jeesus vastasi heille: "Minä myös teen teille yhden kysymyksen; vastatkaa te minulle, niin minä sanon teille, millä vallalla minä näitä teen.'),
(1693610,58,41,11,30,'Oliko Johanneksen kaste taivaasta vai ihmisistä? Vastatkaa minulle."'),
(1693611,58,41,11,31,'Niin he neuvottelivat keskenään sanoen: "Jos sanomme: ''Taivaasta'', niin hän sanoo: ''Miksi ette siis uskoneet häntä?'''),
(1693612,58,41,11,32,'Vai sanommeko: ''Ihmisistä''?" - sitä he kansan tähden pelkäsivät sanoa, sillä kaikkien mielestä Johannes totisesti oli profeetta.'),
(1693613,58,41,11,33,'Ja he vastasivat ja sanoivat Jeesukselle: "Emme tiedä". Silloin Jeesus sanoi heille: "Niinpä en minäkään sano teille, millä vallalla minä näitä teen".'),
(1693614,58,41,12,1,'Ja hän rupesi puhumaan heille vertauksilla: "Mies istutti viinitarhan ja teki aidan sen ympärille ja kaivoi viinikuurnan ja rakensi tornin; ja hän vuokrasi sen viinitarhureille ja matkusti muille maille.'),
(1693615,58,41,12,2,'Ja kun aika tuli, lähetti hän palvelijan viinitarhurien luo perimään tarhureilta viinitarhan hedelmiä.'),
(1693616,58,41,12,3,'Mutta he ottivat hänet kiinni, pieksivät ja lähettivät tyhjin käsin pois.'),
(1693617,58,41,12,4,'Ja vielä hän lähetti heidän luoksensa toisen palvelijan. Ja häntä he löivät päähän ja häpäisivät.'),
(1693618,58,41,12,5,'Ja hän lähetti vielä toisen, ja sen he tappoivat; ja samoin useita muita: toisia he pieksivät, toisia tappoivat.'),
(1693619,58,41,12,6,'Vielä hänellä oli ainoa rakas poikansa. Hänet hän lähetti viimeiseksi heidän luoksensa sanoen: ''Kavahtavat kaiketi minun poikaani''.'),
(1693620,58,41,12,7,'Mutta viinitarhurit sanoivat toisilleen: ''Tämä on perillinen; tulkaa, tappakaamme hänet, niin perintö jää meille''.'),
(1693621,58,41,12,8,'Ja he ottivat hänet kiinni, tappoivat ja heittivät hänet ulos viinitarhasta.'),
(1693622,58,41,12,9,'Mitä nyt viinitarhan herra on tekevä? Hän tulee ja tuhoaa viinitarhurit ja antaa viinitarhan muille.'),
(1693623,58,41,12,10,'Ettekö ole lukeneet tätä kirjoitusta: ''Se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi;'),
(1693624,58,41,12,11,'Herralta tämä on tullut ja on ihmeellinen meidän silmissämme''?"'),
(1693625,58,41,12,12,'Silloin he olisivat tahtoneet ottaa hänet kiinni, mutta pelkäsivät kansaa; sillä he ymmärsivät, että hän oli puhunut tämän vertauksen heistä. Ja he jättivät hänet ja menivät pois.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693626,58,41,12,13,'Ja he lähettivät hänen luoksensa muutamia fariseuksia ja herodilaisia kietomaan häntä sanoilla.'),
(1693627,58,41,12,14,'Nämä tulivat ja sanoivat hänelle: "Opettaja, me tiedämme, että sinä olet totinen etkä välitä kenestäkään, sillä sinä et katso henkilöön, vaan opetat Jumalan tietä totuudessa. Onko luvallista antaa keisarille veroa vai ei? Tuleeko meidän antaa vai ei?"'),
(1693628,58,41,12,15,'Mutta hän tiesi heidän ulkokultaisuutensa ja sanoi heille: "Miksi kiusaatte minua? Tuokaa denari minun nähdäkseni."'),
(1693629,58,41,12,16,'Niin he toivat. Ja hän sanoi heille: "Kenen kuva ja päällekirjoitus tämä on?" He vastasivat hänelle: "Keisarin".'),
(1693630,58,41,12,17,'Jeesus sanoi heille: "Antakaa keisarille, mikä keisarin on, ja Jumalalle, mikä Jumalan on". Ja he ihmettelivät häntä suuresti.'),
(1693631,58,41,12,18,'Ja hänen luoksensa tuli saddukeuksia, jotka sanovat, ettei ylösnousemusta ole; ja he kysyivät häneltä sanoen:'),
(1693632,58,41,12,19,'"Opettaja, Mooses on säätänyt meille: ''Jos joltakin kuolee veli, joka jättää jälkeensä vaimon, mutta ei jätä lasta, niin ottakoon hän veljensä lesken ja herättäköön veljellensä siemenen''.'),
(1693633,58,41,12,20,'Oli seitsemän veljestä. Ensimmäinen otti vaimon, ja kun hän kuoli, ei häneltä jäänyt jälkeläistä.'),
(1693634,58,41,12,21,'Silloin toinen otti hänet, ja hänkin kuoli jättämättä jälkeläistä. Niin myös kolmas.'),
(1693635,58,41,12,22,'Samoin kävi kaikille seitsemälle: heiltä ei jäänyt jälkeläistä. Viimeiseksi kaikista vaimokin kuoli.'),
(1693636,58,41,12,23,'Ylösnousemuksessa siis, kun he nousevat ylös, kenelle heistä hän joutuu vaimoksi, sillä hän oli ollut kaikkien noiden seitsemän vaimona?"'),
(1693637,58,41,12,24,'Jeesus sanoi heille: "Ettekö te siitä syystä eksy, kun ette tunne kirjoituksia ettekä Jumalan voimaa?'),
(1693638,58,41,12,25,'Sillä kun kuolleista noustaan, ei naida eikä mennä miehelle; vaan he ovat niinkuin enkelit taivaissa.'),
(1693639,58,41,12,26,'Mutta mitä siihen tulee, että kuolleet nousevat ylös, ettekö ole lukeneet Mooseksen kirjasta, kertomuksessa orjantappurapensaasta, kuinka Jumala puhui hänelle sanoen: ''Minä olen Aabrahamin Jumala ja Iisakin Jumala ja Jaakobin Jumala''?'),
(1693640,58,41,12,27,'Ei hän ole kuolleitten Jumala, vaan elävien. Suuresti te eksytte."'),
(1693641,58,41,12,28,'Silloin tuli hänen luoksensa eräs kirjanoppinut, joka oli kuullut heidän keskustelunsa ja huomannut hänen hyvin vastanneen heille, ja kysyi häneltä: "Mikä on ensimmäinen kaikista käskyistä?"'),
(1693642,58,41,12,29,'Jeesus vastasi: "Ensimmäinen on tämä: ''Kuule, Israel: Herra, meidän Jumalamme, Herra on yksi ainoa;'),
(1693643,58,41,12,30,'ja rakasta Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi ja kaikesta mielestäsi ja kaikesta voimastasi''.'),
(1693644,58,41,12,31,'Toinen on tämä: ''Rakasta lähimmäistäsi niinkuin itseäsi''. Ei ole mitään käskyä, suurempaa kuin nämä."'),
(1693645,58,41,12,32,'Niin kirjanoppinut sanoi hänelle: "Oikein sanoit, opettaja, totuuden mukaan, että yksi hän on, ja ettei ketään muuta ole, paitsi hän.'),
(1693646,58,41,12,33,'Ja rakastaa häntä kaikesta sydämestään ja kaikesta ymmärryksestään ja kaikesta voimastaan, ja rakastaa lähimmäistään niinkuin itseänsä, se on enemmän kuin kaikki polttouhrit ja muut uhrit."'),
(1693647,58,41,12,34,'Kun Jeesus näki, että hän vastasi ymmärtäväisesti, sanoi hän hänelle: "Sinä et ole kaukana Jumalan valtakunnasta". Eikä kukaan enää rohjennut häneltä kysyä.'),
(1693648,58,41,12,35,'Ja opettaessaan pyhäkössä Jeesus puhui edelleen ja sanoi: "Kuinka kirjanoppineet sanovat, että Kristus on Daavidin poika?'),
(1693649,58,41,12,36,'Onhan Daavid itse sanonut Pyhässä Hengessä: ''Herra sanoi minun Herralleni: Istu minun oikealle puolelleni, kunnes minä panen sinun vihollisesi sinun jalkojesi alle''.'),
(1693650,58,41,12,37,'Daavid itse sanoo häntä Herraksi; kuinka hän sitten on hänen poikansa?" Ja suuri kansanjoukko kuunteli häntä mielellään.'),
(1693651,58,41,12,38,'Ja opettaessaan hän sanoi: "Varokaa kirjanoppineita, jotka mielellään käyskelevät pitkissä vaipoissa ja haluavat tervehdyksiä toreilla'),
(1693652,58,41,12,39,'ja etumaisia istuimia synagoogissa ja ensimmäisiä sijoja pidoissa,'),
(1693653,58,41,12,40,'noita, jotka syövät leskien huoneet ja näön vuoksi pitävät pitkiä rukouksia; he saavat sitä kovemman tuomion".'),
(1693654,58,41,12,41,'Ja hän istui vastapäätä uhriarkkua ja katseli, kuinka kansa pani rahaa uhriarkkuun. Ja monet rikkaat panivat paljon.'),
(1693655,58,41,12,42,'Niin tuli köyhä leski ja pani kaksi ropoa, yhteensä muutamia pennejä.'),
(1693656,58,41,12,43,'Ja hän kutsui opetuslapsensa tykönsä ja sanoi heille: "Totisesti minä sanon teille: tämä köyhä leski pani enemmän kuin kaikki muut, jotka panivat uhriarkkuun.'),
(1693657,58,41,12,44,'Sillä he kaikki panivat liiastaan, mutta tämä pani puutteestaan kaiken, mitä hänellä oli, koko elämisensä."'),
(1693658,58,41,13,1,'Ja kun hän meni ulos pyhäköstä, sanoi eräs hänen opetuslapsistaan hänelle: "Opettaja, katso, millaiset kivet ja millaiset rakennukset!"'),
(1693659,58,41,13,2,'Jeesus vastasi hänelle: "Sinä näet nämä suuret rakennukset. Niistä ei ole jäävä kiveä kiven päälle maahan jaottamatta."'),
(1693660,58,41,13,3,'Ja kun hän istui Öljymäellä, vastapäätä pyhäkköä, kysyivät Pietari ja Jaakob ja Johannes ja Andreas häneltä eriksensä:'),
(1693661,58,41,13,4,'"Sano meille: milloin tämä tapahtuu, ja mikä on merkki siitä, että kaikki tämä alkaa lopullisesti toteutua?"'),
(1693662,58,41,13,5,'Niin Jeesus rupesi puhumaan heille: "Katsokaa, ettei kukaan teitä eksytä.'),
(1693663,58,41,13,6,'Monta tulee minun nimessäni sanoen: ''Minä se olen'', ja he eksyttävät monta.'),
(1693664,58,41,13,7,'Ja kun te kuulette sotien melskettä ja sanomia sodista, älkää peljästykö. Näin täytyy tapahtua, mutta se ei ole vielä loppu.'),
(1693665,58,41,13,8,'Sillä kansa nousee kansaa vastaan ja valtakunta valtakuntaa vastaan, tulee maanjäristyksiä monin paikoin, tulee nälänhätää. Tämä on synnytystuskien alkua.'),
(1693666,58,41,13,9,'Mutta pitäkää te vaari itsestänne. Teidät vedetään oikeuksiin, ja teitä piestään synagoogissa, ja teidät asetetaan maaherrain ja kuningasten eteen, minun tähteni, todistukseksi heille.'),
(1693667,58,41,13,10,'Ja sitä ennen pitää evankeliumi saarnattaman kaikille kansoille.'),
(1693668,58,41,13,11,'Ja kun he vievät teitä ja vetävät oikeuteen, älkää edeltäpäin huolehtiko siitä, mitä puhuisitte; vaan mitä teille sillä hetkellä annetaan, se puhukaa. Sillä ette te ole puhumassa, vaan Pyhä Henki.'),
(1693669,58,41,13,12,'Ja veli antaa veljensä kuolemaan ja isä lapsensa, ja lapset nousevat vanhempiansa vastaan ja tappavat heidät.'),
(1693670,58,41,13,13,'Ja te joudutte kaikkien vihattaviksi minun nimeni tähden; mutta joka vahvana pysyy loppuun asti, se pelastuu.'),
(1693671,58,41,13,14,'Mutta kun näette hävityksen kauhistuksen seisovan siinä, missä ei tulisi - joka tämän lukee, se tarkatkoon - silloin ne, jotka Juudeassa ovat, paetkoot vuorille;'),
(1693672,58,41,13,15,'joka on katolla, älköön astuko alas älköönkä menkö sisään noutamaan mitään huoneestansa;'),
(1693673,58,41,13,16,'ja joka on mennyt pellolle, älköön palatko takaisin noutamaan vaippaansa.'),
(1693674,58,41,13,17,'Voi raskaita ja imettäväisiä niinä päivinä!'),
(1693675,58,41,13,18,'Mutta rukoilkaa, ettei se tapahtuisi talvella.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693676,58,41,13,19,'Sillä niinä päivinä on oleva ahdistus, jonka kaltaista ei ole ollut hamasta luomakunnan alusta, jonka Jumala on luonut, tähän asti, eikä milloinkaan tule.'),
(1693677,58,41,13,20,'Ja ellei Herra lyhentäisi niitä päiviä, ei mikään liha pelastuisi; mutta valittujen tähden, jotka hän on valinnut, hän on lyhentänyt ne päivät.'),
(1693678,58,41,13,21,'Ja jos silloin joku sanoo teille: ''Katso, täällä on Kristus'', tai: ''Katso, tuolla'', niin älkää uskoko.'),
(1693679,58,41,13,22,'Sillä vääriä kristuksia ja vääriä profeettoja nousee, ja he tekevät tunnustekoja ja ihmeitä, eksyttääkseen, jos mahdollista, valitut.'),
(1693680,58,41,13,23,'Mutta olkaa te varuillanne. Minä olen edeltä sanonut teille kaikki.'),
(1693681,58,41,13,24,'Mutta niinä päivinä, sen ahdistuksen jälkeen, aurinko pimenee, eikä kuu anna valoansa,'),
(1693682,58,41,13,25,'ja tähdet putoilevat taivaalta, ja voimat, jotka taivaissa ovat, järkkyvät.'),
(1693683,58,41,13,26,'Ja silloin he näkevät Ihmisen Pojan tulevan pilvissä suurella voimalla ja kirkkaudella.'),
(1693684,58,41,13,27,'Ja silloin hän lähettää enkelinsä ja kokoaa valittunsa neljältä ilmalta, maan äärestä hamaan taivaan ääreen.'),
(1693685,58,41,13,28,'Mutta oppikaa viikunapuusta vertaus: Kun sen oksa jo on tuore ja lehdet puhkeavat, niin te tiedätte, että kesä on lähellä.'),
(1693686,58,41,13,29,'Samoin te myös, kun näette tämän tapahtuvan, tietäkää, että se on lähellä, oven edessä.'),
(1693687,58,41,13,30,'Totisesti minä sanon teille: tämä sukupolvi ei katoa, ennenkuin nämä kaikki tapahtuvat.'),
(1693688,58,41,13,31,'Taivas ja maa katoavat, mutta minun sanani eivät katoa.'),
(1693689,58,41,13,32,'Mutta siitä päivästä tai hetkestä ei tiedä kukaan, eivät enkelit taivaassa, eikä myöskään Poika, vaan ainoastaan Isä.'),
(1693690,58,41,13,33,'Olkaa varuillanne, valvokaa ja rukoilkaa, sillä ette tiedä, milloin se aika tulee.'),
(1693691,58,41,13,34,'On niinkuin muille maille matkustaneen miehen: kun hän jätti talonsa ja antoi palvelijoilleen vallan, kullekin oman tehtävänsä, käski hän myös ovenvartijan valvoa.'),
(1693692,58,41,13,35,'Valvokaa siis, sillä ette tiedä, milloin talon herra tulee, iltamyöhälläkö vai yösydännä vai kukonlaulun aikaan vai varhain aamulla,'),
(1693693,58,41,13,36,'ettei hän, äkkiarvaamatta tullessaan, tapaisi teitä nukkumasta.'),
(1693694,58,41,13,37,'Mutta minkä minä teille sanon, sen minä sanon kaikille: valvokaa."'),
(1693695,58,41,14,1,'Niin oli kahden päivän perästä pääsiäinen ja happamattoman leivän juhla, ja ylipapit ja kirjanoppineet miettivät, kuinka saisivat hänet otetuksi kavaluudella kiinni ja tapetuksi.'),
(1693696,58,41,14,2,'Sillä he sanoivat: "Ei juhlan aikana, ettei syntyisi meteliä kansassa".'),
(1693697,58,41,14,3,'Ja kun hän oli Betaniassa, pitalisen Simonin asunnossa, tuli hänen aterialla ollessaan nainen, mukanaan alabasteripullo täynnä oikeata, kallista nardusvoidetta. Hän rikkoi alabasteripullon ja vuodatti voiteen hänen päähänsä.'),
(1693698,58,41,14,4,'Niin oli muutamia, jotka närkästyivät ja sanoivat keskenään: "Mitä varten tämä voiteen haaskaus?'),
(1693699,58,41,14,5,'Olisihan voinut myydä tämän voiteen enempään kuin kolmeensataan denariin ja antaa ne köyhille." Ja he toruivat häntä.'),
(1693700,58,41,14,6,'Mutta Jeesus sanoi: "Antakaa hänen olla. Miksi pahoitatte hänen mieltään? Hän teki hyvän työn minulle.'),
(1693701,58,41,14,7,'Köyhät teillä on aina keskuudessanne, ja milloin tahdotte, voitte heille tehdä hyvää, mutta minua teillä ei ole aina.'),
(1693702,58,41,14,8,'Hän teki, minkä voi. Edeltäkäsin hän voiteli minun ruumiini hautaamista varten.'),
(1693703,58,41,14,9,'Totisesti minä sanon teille: missä ikinä kaikessa maailmassa evankeliumia saarnataan, siellä sekin, minkä tämä teki, on mainittava hänen muistoksensa."'),
(1693704,58,41,14,10,'Ja Juudas Iskariot, yksi niistä kahdestatoista, meni ylipappien luo kavaltaakseen hänet heille.'),
(1693705,58,41,14,11,'Kun nämä sen kuulivat, ihastuivat he ja lupasivat antaa hänelle rahaa. Ja hän mietti, kuinka hänet sopivassa tilaisuudessa kavaltaisi.'),
(1693706,58,41,14,12,'Ja ensimmäisenä happamattoman leivän päivänä, kun pääsiäislammas teurastettiin, hänen opetuslapsensa sanoivat hänelle: "Mihin tahdot, että menemme valmistamaan pääsiäislampaan sinun syödäksesi?"'),
(1693707,58,41,14,13,'Niin hän lähetti kaksi opetuslastaan ja sanoi heille: "Menkää kaupunkiin, niin teitä vastaan tulee mies kantaen vesiastiaa; seuratkaa häntä.'),
(1693708,58,41,14,14,'Ja mihin hän menee, sen talon isännälle sanokaa: ''Opettaja sanoo: Missä on minun vierashuoneeni, syödäkseni siinä pääsiäislampaan opetuslasteni kanssa?'''),
(1693709,58,41,14,15,'Ja hän näyttää teille suuren huoneen yläkerrassa, valmiiksi laitetun; valmistakaa meille sinne."'),
(1693710,58,41,14,16,'Niin opetuslapset lähtivät ja tulivat kaupunkiin ja havaitsivat niin olevan, kuin Jeesus oli heille sanonut, ja valmistivat pääsiäislampaan.'),
(1693711,58,41,14,17,'Ja kun ehtoo tuli, saapui hän sinne niiden kahdentoista kanssa.'),
(1693712,58,41,14,18,'Ja kun he olivat aterialla ja söivät, sanoi Jeesus: "Totisesti minä sanon teille: yksi teistä kavaltaa minut, yksi, joka syö minun kanssani".'),
(1693713,58,41,14,19,'He tulivat murheellisiksi ja rupesivat toinen toisensa perästä sanomaan hänelle: "En kaiketi minä?"'),
(1693714,58,41,14,20,'Hän sanoi heille: "Yksi teistä kahdestatoista, se, joka kastaa vatiin minun kanssani.'),
(1693715,58,41,14,21,'Niin, Ihmisen Poika tosin menee pois, niinkuin hänestä on kirjoitettu, mutta voi sitä ihmistä, jonka kautta Ihmisen Poika kavalletaan! Parempi olisi sille ihmiselle, että hän ei olisi syntynyt."'),
(1693716,58,41,14,22,'Ja heidän syödessään Jeesus otti leivän, siunasi, mursi ja antoi heille ja sanoi: "Ottakaa, tämä on minun ruumiini".'),
(1693717,58,41,14,23,'Ja hän otti maljan, kiitti ja antoi heille; ja he kaikki joivat siitä.'),
(1693718,58,41,14,24,'Ja hän sanoi heille: "Tämä on minun vereni, liiton veri, joka vuodatetaan monen edestä.'),
(1693719,58,41,14,25,'Totisesti minä sanon teille: minä en juo enää viinipuun antia, ennenkuin sinä päivänä, jona juon sitä uutena Jumalan valtakunnassa."'),
(1693720,58,41,14,26,'Ja veisattuaan kiitosvirren he lähtivät Öljymäelle.'),
(1693721,58,41,14,27,'Ja Jeesus sanoi heille: "Kaikki te loukkaannutte, sillä kirjoitettu on: ''Minä lyön paimenta, ja lampaat hajotetaan''.'),
(1693722,58,41,14,28,'Mutta ylösnoustuani minä menen teidän edellänne Galileaan."'),
(1693723,58,41,14,29,'Niin Pietari sanoi hänelle: "Vaikka kaikki loukkaantuisivat, en kuitenkaan minä".'),
(1693724,58,41,14,30,'Jeesus sanoi hänelle: "Totisesti minä sanon sinulle: tänään, tänä yönä, ennenkuin kukko kahdesti laulaa, sinä kolmesti minut kiellät".'),
(1693725,58,41,14,31,'Mutta hän vakuutti vielä lujemmin: "Vaikka minun pitäisi kuolla sinun kanssasi, en sittenkään minä sinua kiellä". Ja samoin sanoivat kaikki muutkin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693726,58,41,14,32,'Ja he tulivat maatilalle, jonka nimi on Getsemane; ja hän sanoi opetuslapsillensa: "Istukaa tässä, sillä aikaa kuin minä rukoilen".'),
(1693727,58,41,14,33,'Ja hän otti mukaansa Pietarin ja Jaakobin ja Johanneksen; ja hän alkoi kauhistua ja tulla tuskaan.'),
(1693728,58,41,14,34,'Ja hän sanoi heille: "Minun sieluni on syvästi murheellinen, kuolemaan asti; olkaa tässä ja valvokaa".'),
(1693729,58,41,14,35,'Ja hän meni vähän edemmäksi, lankesi maahan ja rukoili, että, jos mahdollista, se hetki menisi häneltä ohi,'),
(1693730,58,41,14,36,'ja sanoi: "Abba, Isä, kaikki on mahdollista sinulle; ota pois minulta tämä malja. Mutta ei, mitä minä tahdon, vaan mitä sinä!"'),
(1693731,58,41,14,37,'Ja hän tuli ja tapasi heidät nukkumasta ja sanoi Pietarille: "Simon, nukutko? Etkö jaksanut yhtä hetkeä valvoa?'),
(1693732,58,41,14,38,'Valvokaa ja rukoilkaa, ettette joutuisi kiusaukseen; henki tosin on altis, mutta liha on heikko."'),
(1693733,58,41,14,39,'Ja taas hän meni pois ja rukoili sanoen samat sanat.'),
(1693734,58,41,14,40,'Ja tullessaan hän taas tapasi heidät nukkumasta, sillä heidän silmänsä olivat käyneet kovin raukeiksi; ja he eivät tienneet, mitä hänelle vastaisivat.'),
(1693735,58,41,14,41,'Ja hän tuli kolmannen kerran ja sanoi heille: "Te nukutte vielä ja lepäätte! Jo riittää! Hetki on tullut; katso, Ihmisen Poika annetaan syntisten käsiin.'),
(1693736,58,41,14,42,'Nouskaa, lähtekäämme; katso, se, joka kavaltaa minut, on lähellä."'),
(1693737,58,41,14,43,'Ja heti, hänen vielä puhuessaan, Juudas, yksi niistä kahdestatoista, saapui, ja hänen mukanaan joukko ylipappien ja kirjanoppineiden ja vanhinten luota, miekat ja seipäät käsissä.'),
(1693738,58,41,14,44,'Mutta se, joka hänet kavalsi, oli sopinut heidän kanssaan merkistä, sanoen: "Se, jolle minä suuta annan, hän se on; ottakaa hänet kiinni ja viekää tarkasti vartioituna pois".'),
(1693739,58,41,14,45,'Ja tultuaan hän kohta astui hänen luoksensa ja sanoi: "Rabbi!" ja antoi hänelle suuta.'),
(1693740,58,41,14,46,'Silloin he kävivät häneen käsiksi ja ottivat hänet kiinni.'),
(1693741,58,41,14,47,'Mutta eräs niistä, jotka lähellä seisoivat, veti miekkansa, iski ylimmäisen papin palvelijaa ja sivalsi häneltä pois korvan.'),
(1693742,58,41,14,48,'Niin Jeesus puhui heille ja sanoi: "Niinkuin ryöväriä vastaan te olette lähteneet minua miekoilla ja seipäillä vangitsemaan.'),
(1693743,58,41,14,49,'Joka päivä minä olen ollut teidän luonanne opettaen pyhäkössä, ettekä ole ottaneet minua kiinni. Mutta tämä tapahtuu, että kirjoitukset kävisivät toteen."'),
(1693744,58,41,14,50,'Niin he kaikki jättivät hänet ja pakenivat.'),
(1693745,58,41,14,51,'Ja häntä seurasi eräs nuorukainen, jolla oli ympärillään liinavaate paljaalle iholle heitettynä; ja he ottivat hänet kiinni.'),
(1693746,58,41,14,52,'Mutta hän jätti liinavaatteen ja pakeni alastonna.'),
(1693747,58,41,14,53,'Ja he veivät Jeesuksen ylimmäisen papin eteen, jonne kaikki ylipapit ja vanhimmat ja kirjanoppineet kokoontuivat.'),
(1693748,58,41,14,54,'Ja Pietari seurasi häntä taampana ylimmäisen papin palatsin esipihaan asti ja istui palvelijain joukkoon ja lämmitteli tulen ääressä.'),
(1693749,58,41,14,55,'Mutta ylipapit ja koko neuvosto etsivät todistusta Jeesusta vastaan tappaaksensa hänet, mutta eivät löytäneet.'),
(1693750,58,41,14,56,'Useat kyllä todistivat väärin häntä vastaan, mutta todistukset eivät olleet yhtäpitäviä.'),
(1693751,58,41,14,57,'Niin muutamat nousivat ja todistivat väärin häntä vastaan, sanoen:'),
(1693752,58,41,14,58,'"Me olemme kuulleet hänen sanovan: ''Minä hajotan maahan tämän käsillä tehdyn temppelin ja rakennan kolmessa päivässä toisen, joka ei ole käsillä tehty''."'),
(1693753,58,41,14,59,'Mutta eivät näinkään heidän todistuksensa olleet yhtäpitäviä.'),
(1693754,58,41,14,60,'Silloin ylimmäinen pappi nousi ja astui esille ja kysyi Jeesukselta sanoen: "Etkö vastaa mitään? Mitä nämä todistavat sinua vastaan?"'),
(1693755,58,41,14,61,'Mutta hän oli vaiti eikä vastannut mitään. Taas ylimmäinen pappi kysyi häneltä ja sanoi hänelle: "Oletko sinä Kristus, sen Ylistetyn Poika?"'),
(1693756,58,41,14,62,'Jeesus sanoi: "Olen; ja te saatte nähdä Ihmisen Pojan istuvan Voiman oikealla puolella ja tulevan taivaan pilvissä".'),
(1693757,58,41,14,63,'Niin ylimmäinen pappi repäisi vaatteensa ja sanoi: "Mitä me enää todistajia tarvitsemme?'),
(1693758,58,41,14,64,'Te kuulitte hänen pilkkaamisensa. Mitä arvelette?" Niin he kaikki tuomitsivat hänet vikapääksi kuolemaan.'),
(1693759,58,41,14,65,'Ja muutamat rupesivat sylkemään häntä ja peittivät hänen kasvonsa ja löivät häntä nyrkillä ja sanoivat hänelle: "Profetoi!" Oikeudenpalvelijatkin löivät häntä poskelle.'),
(1693760,58,41,14,66,'Kun nyt Pietari oli alhaalla esipihassa, tuli sinne muuan ylimmäisen papin palvelijattarista;'),
(1693761,58,41,14,67,'ja nähdessään Pietarin lämmittelevän hän katsoi häneen ja sanoi: "Sinäkin olit Nasaretilaisen, tuon Jeesuksen, kanssa".'),
(1693762,58,41,14,68,'Mutta hän kielsi sanoen: "En tiedä enkä käsitä, mitä sanot". Ja hän meni ulos pihalle. Ja kukko lauloi.'),
(1693763,58,41,14,69,'Ja nähdessään hänet siellä palvelijatar rupesi taas sanomaan lähellä seisoville: "Tämä on yksi niistä".'),
(1693764,58,41,14,70,'Mutta hän kielsi uudestaan. Ja vähän sen jälkeen lähellä seisovat taas sanoivat Pietarille: "Totisesti, sinä olet yksi niistä, sillä olethan sinä galilealainenkin".'),
(1693765,58,41,14,71,'Mutta hän rupesi sadattelemaan itseänsä ja vannomaan: "En tunne sitä miestä, josta te puhutte".'),
(1693766,58,41,14,72,'Ja samassa kukko lauloi toisen kerran. Niin Pietari muisti Jeesuksen sanat, jotka hän oli sanonut hänelle: "Ennenkuin kukko kahdesti laulaa, sinä kolmesti minut kiellät". Ja hän ratkesi itkuun.'),
(1693767,58,41,15,1,'Ja heti aamulla ylipapit ynnä vanhimmat ja kirjanoppineet ja koko neuvosto tekivät päätöksen, sitoivat Jeesuksen, veivät hänet pois ja antoivat Pilatuksen käsiin.'),
(1693768,58,41,15,2,'Niin Pilatus kysyi häneltä: "Oletko sinä juutalaisten kuningas?" Hän vastasi ja sanoi hänelle: "Sinäpä sen sanot".'),
(1693769,58,41,15,3,'Ja ylipapit tekivät monta syytöstä häntä vastaan.'),
(1693770,58,41,15,4,'Niin Pilatus taas kysyi häneltä sanoen: "Etkö vastaa mitään? Katso, kuinka paljon syytöksiä he tekevät sinua vastaan."'),
(1693771,58,41,15,5,'Mutta Jeesus ei enää vastannut mitään, niin että Pilatus ihmetteli.'),
(1693772,58,41,15,6,'Mutta juhlan aikana hän tavallisesti päästi heille yhden vangin irti, sen, jota he anoivat.'),
(1693773,58,41,15,7,'Niin siellä oli eräs mies, jota sanottiin Barabbaaksi, vangittu muiden kapinoitsijain kanssa, jotka kapinassa olivat tehneet murhan.'),
(1693774,58,41,15,8,'Ja kansa meni sinne ylös ja rupesi pyytämään, että hän tekisi heille, niinkuin hänen tapansa oli.'),
(1693775,58,41,15,9,'Pilatus vastasi heille sanoen: "Tahdotteko, että päästän teille juutalaisten kuninkaan?"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693776,58,41,15,10,'Sillä hän tiesi, että ylipapit kateudesta olivat antaneet hänet hänen käsiinsä.'),
(1693777,58,41,15,11,'Mutta ylipapit kiihoittivat kansaa anomaan, että hän ennemmin päästäisi heille Barabbaan.'),
(1693778,58,41,15,12,'Ja Pilatus puhui taas heille ja sanoi: "Mitä minun sitten on tehtävä hänelle, jota te sanotte juutalaisten kuninkaaksi?"'),
(1693779,58,41,15,13,'Niin he taas huusivat: "Ristiinnaulitse hänet!"'),
(1693780,58,41,15,14,'Mutta Pilatus sanoi heille: "Mitä pahaa hän sitten on tehnyt?" Mutta he huusivat vielä kovemmin: "Ristiinnaulitse hänet!"'),
(1693781,58,41,15,15,'Ja kun Pilatus tahtoi tehdä kansalle mieliksi, päästi hän heille Barabbaan, mutta Jeesuksen hän ruoskitti ja luovutti ristiinnaulittavaksi.'),
(1693782,58,41,15,16,'Niin sotamiehet veivät hänet sisälle linnaan, se on palatsiin, ja kutsuivat siihen koko sotilasjoukon.'),
(1693783,58,41,15,17,'Ja he pukivat hänen yllensä purppuravaipan, väänsivät orjantappuroista kruunun ja panivat sen hänen päähänsä'),
(1693784,58,41,15,18,'ja rupesivat tervehtimään häntä: "Terve, juutalaisten kuningas!"'),
(1693785,58,41,15,19,'Ja he löivät häntä päähän ruovolla, sylkivät häntä ja laskeutuen polvilleen kumarsivat häntä.'),
(1693786,58,41,15,20,'Ja kun he olivat häntä pilkanneet, riisuivat he häneltä purppuravaipan ja pukivat hänet hänen omiin vaatteisiinsa. Ja he veivät hänet pois, ristiinnaulitakseen hänet.'),
(1693787,58,41,15,21,'Ja he pakottivat erään ohikulkevan miehen, Simonin, kyreneläisen, joka tuli vainiolta, Aleksanterin ja Rufuksen isän, kantamaan hänen ristiänsä.'),
(1693788,58,41,15,22,'Ja he veivät hänet paikalle, jonka nimi on Golgata, se on käännettynä: pääkallonpaikka.'),
(1693789,58,41,15,23,'Ja he tarjosivat hänelle mirhalla sekoitettua viiniä, mutta hän ei sitä ottanut.'),
(1693790,58,41,15,24,'Ja he ristiinnaulitsivat hänet ja jakoivat keskenään hänen vaatteensa heittäen niistä arpaa, mitä kukin oli saava.'),
(1693791,58,41,15,25,'Oli kolmas hetki, kun he hänet ristiinnaulitsivat.'),
(1693792,58,41,15,26,'Ja päällekirjoitukseksi oli merkitty hänen syynsä: "Juutalaisten kuningas".'),
(1693793,58,41,15,27,'Ja he ristiinnaulitsivat hänen kanssaan kaksi ryöväriä, toisen hänen oikealle ja toisen hänen vasemmalle puolellensa.'),
(1693794,58,41,15,29,'Ja ne, jotka kulkivat ohitse, herjasivat häntä ja nyökyttivät päätään ja sanoivat: "Voi sinua, joka hajotat maahan temppelin ja kolmessa päivässä sen rakennat!'),
(1693795,58,41,15,30,'Auta itseäsi ja astu alas ristiltä."'),
(1693796,58,41,15,31,'Samoin ylipapitkin ynnä kirjanoppineet keskenään pilkkasivat häntä ja sanoivat: "Muita hän on auttanut, itseään ei voi auttaa.'),
(1693797,58,41,15,32,'Astukoon hän, Kristus, Israelin kuningas, nyt alas ristiltä, että me näkisimme ja uskoisimme." Myöskin ne, jotka olivat ristiinnaulitut hänen kanssaan, herjasivat häntä.'),
(1693798,58,41,15,33,'Ja kuudennella hetkellä tuli pimeys yli kaiken maan, ja sitä kesti hamaan yhdeksänteen hetkeen.'),
(1693799,58,41,15,34,'Ja yhdeksännellä hetkellä Jeesus huusi suurella äänellä: "Eeli, Eeli, lama sabaktani?" Se on käännettynä: Jumalani, Jumalani, miksi minut hylkäsit?'),
(1693800,58,41,15,35,'Sen kuullessaan sanoivat muutamat niistä, jotka siinä seisoivat: "Katso, hän huutaa Eliasta".'),
(1693801,58,41,15,36,'Ja muuan juoksi ja täytti sienen hapanviinillä, pani sen ruovon päähän ja antoi hänelle juoda sanoen: "Annas, katsokaamme, tuleeko Elias ottamaan hänet alas".'),
(1693802,58,41,15,37,'Mutta Jeesus huusi suurella äänellä ja antoi henkensä.'),
(1693803,58,41,15,38,'Ja temppelin esirippu repesi kahtia ylhäältä alas asti.'),
(1693804,58,41,15,39,'Mutta kun sadanpäämies, joka seisoi häntä vastapäätä, näki hänen näin antavan henkensä, sanoi hän: "Totisesti tämä ihminen oli Jumalan Poika".'),
(1693805,58,41,15,40,'Ja siellä oli myös naisia taampaa katselemassa. Näiden joukossa olivat Maria Magdaleena ja Maria, Jaakob nuoremman ja Jooseen äiti, ja Salome,'),
(1693806,58,41,15,41,'jotka hänen ollessaan Galileassa olivat seuranneet ja palvelleet häntä, sekä useita muita, jotka olivat tulleet hänen kanssaan ylös Jerusalemiin.'),
(1693807,58,41,15,42,'Ja kun jo oli tullut ilta, ja koska oli valmistuspäivä, se on sapatin aattopäivä,'),
(1693808,58,41,15,43,'tuli Joosef, arimatialainen, arvossapidetty neuvoston jäsen, joka hänkin odotti Jumalan valtakuntaa, rohkaisi mielensä ja meni sisälle Pilatuksen luo ja pyysi Jeesuksen ruumista.'),
(1693809,58,41,15,44,'Niin Pilatus ihmetteli, oliko hän jo kuollut, ja kutsuttuaan luoksensa sadanpäämiehen kysyi tältä, oliko hän jo kauan sitten kuollut.'),
(1693810,58,41,15,45,'Ja saatuaan sadanpäämieheltä siitä tiedon hän lahjoitti ruumiin Joosefille.'),
(1693811,58,41,15,46,'Tämä osti liinavaatteen ja otti hänet alas, kääri hänet liinavaatteeseen ja pani hautaan, joka oli hakattu kallioon, ja vieritti kiven hautakammion ovelle.'),
(1693812,58,41,15,47,'Ja Maria Magdaleena ja Maria, Jooseen äiti, katselivat, mihin hänet pantiin.'),
(1693813,58,41,16,1,'Ja kun sapatti oli ohi, ostivat Maria Magdaleena ja Maria, Jaakobin äiti, ja Salome hyvänhajuisia yrttejä mennäkseen voitelemaan häntä.'),
(1693814,58,41,16,2,'Ja viikon ensimmäisenä päivänä he tulivat haudalle ani varhain, auringon noustessa.'),
(1693815,58,41,16,3,'Ja he sanoivat toisilleen: "Kuka meille vierittää kiven hautakammion ovelta?"'),
(1693816,58,41,16,4,'Ja katsahtaessaan ylös he näkivät kiven poisvieritetyksi; se oli näet hyvin suuri.'),
(1693817,58,41,16,5,'Ja mentyään hautakammion sisään he näkivät nuorukaisen istuvan oikealla puolella, puettuna pitkään, valkeaan vaatteeseen; ja he peljästyivät suuresti.'),
(1693818,58,41,16,6,'Mutta hän sanoi heille: "Älkää peljästykö; te etsitte Jeesusta, Nasaretilaista, joka oli ristiinnaulittu. Hän on noussut ylös; ei hän ole täällä. Katso, tässä on paikka, johon he hänet panivat.'),
(1693819,58,41,16,7,'Mutta menkää ja sanokaa hänen opetuslapsillensa ja Pietarille: ''Hän menee teidän edellänne Galileaan; siellä te saatte hänet nähdä, niinkuin hän teille sanoi''."'),
(1693820,58,41,16,8,'Niin he tulivat ulos ja pakenivat haudalta, sillä heidät oli vallannut vavistus ja hämmästys, eivätkä sanoneet kenellekään mitään, sillä he pelkäsivät.'),
(1693821,58,41,16,9,'Mutta ylösnousemisensa jälkeen hän varhain aamulla viikon ensimmäisenä päivänä ilmestyi ensiksi Maria Magdaleenalle, josta hän oli ajanut ulos seitsemän riivaajaa.'),
(1693822,58,41,16,10,'Tämä meni ja vei sanan niille, jotka olivat olleet Jeesuksen kanssa ja jotka nyt murehtivat ja itkivät.'),
(1693823,58,41,16,11,'Mutta kun he kuulivat, että hän eli ja että Maria oli hänet nähnyt, eivät he uskoneet.'),
(1693824,58,41,16,12,'Ja sen jälkeen hän toisenmuotoisena ilmestyi kahdelle heistä, heidän kävellessään, matkalla maakylään.'),
(1693825,58,41,16,13,'Hekin menivät ja veivät sanan toisille; mutta nämä eivät uskoneet heitäkään.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693826,58,41,16,14,'Vihdoin hän ilmestyi myöskin niille yhdelletoista heidän ollessaan aterialla; ja hän nuhteli heidän epäuskoaan ja heidän sydämensä kovuutta, kun he eivät olleet uskoneet niitä, jotka olivat nähneet hänet ylösnousseeksi.'),
(1693827,58,41,16,15,'Ja hän sanoi heille: "Menkää kaikkeen maailmaan ja saarnatkaa evankeliumia kaikille luoduille.'),
(1693828,58,41,16,16,'Joka uskoo ja kastetaan, se pelastuu; mutta joka ei usko, se tuomitaan kadotukseen.'),
(1693829,58,41,16,17,'Ja nämä merkit seuraavat niitä, jotka uskovat: minun nimessäni he ajavat ulos riivaajia, puhuvat uusilla kielillä,'),
(1693830,58,41,16,18,'nostavat käsin käärmeitä, ja jos he juovat jotakin kuolettavaa, ei se heitä vahingoita; he panevat kätensä sairasten päälle, ja ne tulevat terveiksi."'),
(1693831,58,41,16,19,'Kun nyt Herra Jeesus oli puhunut heille, otettiin hänet ylös taivaaseen, ja hän istui Jumalan oikealle puolelle.'),
(1693832,58,41,16,20,'Mutta he lähtivät ja saarnasivat kaikkialla, ja Herra vaikutti heidän kanssansa ja vahvisti sanan sitä seuraavien merkkien kautta.'),
(1693833,58,42,1,1,'Koska monet ovat ryhtyneet tekemään kertomusta meidän keskuudessamme tosiksi tunnetuista tapahtumista,'),
(1693834,58,42,1,2,'sen mukaisesti kuin meille ovat kertoneet ne, jotka alusta asti ovat omin silmin ne nähneet ja olleet sanan palvelijoita,'),
(1693835,58,42,1,3,'niin olen minäkin, tarkkaan tutkittuani alusta alkaen kaikki, päättänyt kirjoittaa ne järjestyksessään sinulle, korkea-arvoinen Teofilus,'),
(1693836,58,42,1,4,'että oppisit tuntemaan, kuinka varmat ne asiat ovat, jotka sinulle on opetettu.'),
(1693837,58,42,1,5,'Herodeksen, Juudean kuninkaan, aikana oli pappi, nimeltä Sakarias, Abian osastoa. Ja hänen vaimonsa oli Aaronin tyttäriä, ja tämän nimi oli Elisabet.'),
(1693838,58,42,1,6,'He olivat molemmat hurskaita Jumalan edessä, vaeltaen kaikissa Herran käskyissä ja säädöksissä nuhteettomina.'),
(1693839,58,42,1,7,'Mutta heillä ei ollut lasta, sillä Elisabet oli hedelmätön; ja he olivat molemmat tulleet iällisiksi.'),
(1693840,58,42,1,8,'Niin tapahtui, kun hänen osastonsa palvelusvuoro tuli ja hän toimitti papillisia tehtäviä Jumalan edessä,'),
(1693841,58,42,1,9,'että hän tavanmukaisessa pappistehtävien arpomisessa sai osaksensa mennä Herran temppeliin suitsuttamaan.'),
(1693842,58,42,1,10,'Ja kaikki kansa oli suitsuttamisen aikana ulkopuolella rukoilemassa.'),
(1693843,58,42,1,11,'Silloin ilmestyi hänelle Herran enkeli seisoen suitsutusalttarin oikealla puolella.'),
(1693844,58,42,1,12,'Ja hänet nähdessään Sakarias hämmästyi, ja hänet valtasi pelko.'),
(1693845,58,42,1,13,'Mutta enkeli sanoi hänelle: "Älä pelkää, Sakarias; sillä sinun rukouksesi on kuultu, ja vaimosi Elisabet on synnyttävä sinulle pojan, ja sinun on annettava hänelle nimi Johannes.'),
(1693846,58,42,1,14,'Ja hän on oleva sinulle iloksi ja riemuksi, ja monet iloitsevat hänen syntymisestään.'),
(1693847,58,42,1,15,'Sillä hän on oleva suuri Herran edessä; viiniä ja väkijuomaa hän ei juo, ja hän on oleva täytetty Pyhällä Hengellä hamasta äitinsä kohdusta.'),
(1693848,58,42,1,16,'Ja hän kääntää monta Israelin lapsista Herran, heidän Jumalansa, tykö.'),
(1693849,58,42,1,17,'Ja hän käy hänen edellään Eliaan hengessä ja voimassa, kääntääksensä isien sydämet lasten puoleen ja tottelemattomat vanhurskasten mielenlaatuun, näin Herralle toimittaaksensa valmistetun kansan."'),
(1693850,58,42,1,18,'Niin Sakarias sanoi enkelille: "Kuinka minä tämän käsittäisin? Sillä minä olen vanha, ja minun vaimoni on iälliseksi tullut."'),
(1693851,58,42,1,19,'Enkeli vastasi ja sanoi hänelle: "Minä olen Gabriel, joka seison Jumalan edessä, ja minä olen lähetetty puhumaan sinulle ja julistamaan sinulle tämän ilosanoman.'),
(1693852,58,42,1,20,'Ja katso, sinä tulet mykäksi etkä kykene mitään puhumaan siihen päivään saakka, jona tämä tapahtuu, sentähden ettet uskonut minun sanojani, jotka käyvät aikanansa toteen."'),
(1693853,58,42,1,21,'Ja kansa oli odottamassa Sakariasta, ja he ihmettelivät, että hän niin kauan viipyi temppelissä.'),
(1693854,58,42,1,22,'Mutta ulos tullessaan hän ei kyennyt puhumaan heille; silloin he ymmärsivät, että hän oli nähnyt näyn temppelissä. Ja hän viittoi heille ja jäi mykäksi.'),
(1693855,58,42,1,23,'Ja kun hänen virkatoimensa päivät olivat päättyneet, meni hän kotiinsa.'),
(1693856,58,42,1,24,'Ja niiden päiväin perästä Elisabet, hänen vaimonsa, tuli raskaaksi ja pysytteli salassa viisi kuukautta, sanoen:'),
(1693857,58,42,1,25,'"Näin on Herra tehnyt minulle niinä päivinä, jolloin hän katsoi minun puoleeni poistaaksensa minusta ihmisten ylenkatseen".'),
(1693858,58,42,1,26,'Kuudentena kuukautena sen jälkeen Jumala lähetti enkeli Gabrielin Galilean kaupunkiin, jonka nimi on Nasaret,'),
(1693859,58,42,1,27,'neitsyen tykö, joka oli kihlattu Joosef nimiselle miehelle Daavidin suvusta; ja neitsyen nimi oli Maria.'),
(1693860,58,42,1,28,'Ja tullessaan sisälle hänen tykönsä enkeli sanoi: "Terve, armoitettu! Herra olkoon sinun kanssasi."'),
(1693861,58,42,1,29,'Mutta hän hämmästyi suuresti siitä puheesta ja mietti, mitä tämä tervehdys mahtoi tarkoittaa.'),
(1693862,58,42,1,30,'Niin enkeli sanoi hänelle: "Älä pelkää, Maria; sillä sinä olet saanut armon Jumalan edessä.'),
(1693863,58,42,1,31,'Ja katso, sinä tulet raskaaksi ja synnytät pojan, ja sinun on annettava hänelle nimi Jeesus.'),
(1693864,58,42,1,32,'Hän on oleva suuri, ja hänet pitää kutsuttaman Korkeimman Pojaksi, ja Herra Jumala antaa hänelle Daavidin, hänen isänsä, valtaistuimen,'),
(1693865,58,42,1,33,'ja hän on oleva Jaakobin huoneen kuningas iankaikkisesti, ja hänen valtakunnallansa ei pidä loppua oleman."'),
(1693866,58,42,1,34,'Niin Maria sanoi enkelille: "Kuinka tämä voi tapahtua, kun minä en miehestä mitään tiedä?"'),
(1693867,58,42,1,35,'Enkeli vastasi ja sanoi hänelle: "Pyhä Henki tulee sinun päällesi, ja Korkeimman voima varjoaa sinut; sentähden myös se pyhä, mikä syntyy, pitää kutsuttaman Jumalan Pojaksi.'),
(1693868,58,42,1,36,'Ja katso, sinun sukulaisesi Elisabet, hänkin kantaa kohdussaan poikaa vanhalla iällään, ja tämä on kuudes kuukausi hänellä, jota sanottiin hedelmättömäksi;'),
(1693869,58,42,1,37,'sillä Jumalalle ei mikään ole mahdotonta."'),
(1693870,58,42,1,38,'Silloin Maria sanoi: "Katso, minä olen Herran palvelijatar; tapahtukoon minulle sinun sanasi mukaan". Ja enkeli lähti hänen tyköänsä.'),
(1693871,58,42,1,39,'Niinä päivinä Maria nousi ja kulki kiiruusti vuorimaahan erääseen Juudan kaupunkiin'),
(1693872,58,42,1,40,'ja meni Sakariaan kotiin ja tervehti Elisabetia.'),
(1693873,58,42,1,41,'Ja kun Elisabet kuuli Marian tervehdyksen, hypähti lapsi hänen kohdussansa; ja Elisabet täytettiin Pyhällä Hengellä.'),
(1693874,58,42,1,42,'Ja hän puhkesi puhumaan suurella äänellä ja sanoi: "Siunattu sinä vaimojen joukossa, ja siunattu sinun kohtusi hedelmä!'),
(1693875,58,42,1,43,'Ja kuinka minulle tapahtuu tämä, että minun Herrani äiti tulee minun tyköni?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693876,58,42,1,44,'Sillä katso, kun sinun tervehdyksesi ääni tuli minun korviini, hypähti lapsi ilosta minun kohdussani.'),
(1693877,58,42,1,45,'Ja autuas se, joka uskoi, sillä se sana on täyttyvä, mikä hänelle on tullut Herralta!"'),
(1693878,58,42,1,46,'Ja Maria sanoi: "Minun sieluni suuresti ylistää Herraa,'),
(1693879,58,42,1,47,'ja minun henkeni riemuitsee Jumalasta, vapahtajastani;'),
(1693880,58,42,1,48,'sillä hän on katsonut palvelijattarensa alhaisuuteen. Katso, tästedes kaikki sukupolvet ylistävät minua autuaaksi.'),
(1693881,58,42,1,49,'Sillä Voimallinen on tehnyt minulle suuria, ja hänen nimensä on pyhä,'),
(1693882,58,42,1,50,'ja hänen laupeutensa pysyy polvesta polveen niille, jotka häntä pelkäävät.'),
(1693883,58,42,1,51,'Hän on osoittanut voimansa käsivarrellaan; hän on hajottanut ne, joilla oli ylpeät ajatukset sydämessään.'),
(1693884,58,42,1,52,'Hän on kukistanut valtiaat valtaistuimilta ja korottanut alhaiset.'),
(1693885,58,42,1,53,'Nälkäiset hän on täyttänyt hyvyyksillä, ja rikkaat hän on lähettänyt tyhjinä pois.'),
(1693886,58,42,1,54,'Hän on ottanut huomaansa palvelijansa Israelin, muistaaksensa laupeuttaan'),
(1693887,58,42,1,55,'Aabrahamia ja hänen siementänsä kohtaan iankaikkisesti, niinkuin hän on meidän isillemme puhunut."'),
(1693888,58,42,1,56,'Ja Maria oli hänen tykönänsä noin kolme kuukautta ja palasi jälleen kotiinsa.'),
(1693889,58,42,1,57,'Mutta Elisabetin synnyttämisen aika tuli; ja hän synnytti pojan.'),
(1693890,58,42,1,58,'Ja kun hänen naapurinsa ja sukulaisensa kuulivat, että Herra oli tehnyt hänelle suuren laupeuden, iloitsivat he hänen kanssansa.'),
(1693891,58,42,1,59,'Ja kahdeksantena päivänä he tulivat ympärileikkaamaan lasta ja tahtoivat antaa hänelle hänen isänsä mukaan nimen Sakarias.'),
(1693892,58,42,1,60,'Mutta hänen äitinsä vastasi ja sanoi: "Ei suinkaan, vaan hänen nimensä on oleva Johannes".'),
(1693893,58,42,1,61,'Niin he sanoivat hänelle: "Eihän sinun suvussasi ole ketään, jolla on se nimi".'),
(1693894,58,42,1,62,'Ja he kysyivät viittomalla lapsen isältä, minkä nimen hän tahtoi hänelle annettavaksi.'),
(1693895,58,42,1,63,'Niin hän pyysi taulun ja kirjoitti siihen nämä sanat: "Johannes on hänen nimensä". Ja kaikki ihmettelivät.'),
(1693896,58,42,1,64,'Ja kohta hänen suunsa aukeni, ja hänen kielensä vapautui, ja hän puhui kiittäen Jumalaa.'),
(1693897,58,42,1,65,'Ja tuli pelko kaikille heidän ympärillään asuvaisille, ja koko Juudean vuorimaassa puhuttiin kaikista näistä tapahtumista;'),
(1693898,58,42,1,66,'ja kaikki, jotka niistä kuulivat, panivat ne mieleensä ja sanoivat: "Mikähän tästä lapsesta tulee?" Sillä Herran käsi oli hänen kanssansa.'),
(1693899,58,42,1,67,'Ja Sakarias, hänen isänsä, täytettiin Pyhällä Hengellä, ja hän ennusti sanoen:'),
(1693900,58,42,1,68,'"Kiitetty olkoon Herra, Israelin Jumala, sillä hän on katsonut kansansa puoleen ja valmistanut sille lunastuksen'),
(1693901,58,42,1,69,'ja kohottanut meille pelastuksen sarven palvelijansa Daavidin huoneesta'),
(1693902,58,42,1,70,'- niinkuin hän on puhunut hamasta ikiajoista pyhäin profeettainsa suun kautta -'),
(1693903,58,42,1,71,'pelastukseksi vihollisistamme ja kaikkien niiden kädestä, jotka meitä vihaavat,'),
(1693904,58,42,1,72,'tehdäkseen laupeuden meidän isillemme ja muistaakseen pyhän liittonsa,'),
(1693905,58,42,1,73,'sen valan, jonka hän vannoi Aabrahamille, meidän isällemme;'),
(1693906,58,42,1,74,'suodakseen meidän, vapahdettuina vihollistemme kädestä, pelkäämättä palvella häntä'),
(1693907,58,42,1,75,'pyhyydessä ja vanhurskaudessa hänen edessään kaikkina elinpäivinämme.'),
(1693908,58,42,1,76,'Ja sinä, lapsukainen, olet kutsuttava Korkeimman profeetaksi, sillä sinä olet käyvä Herran edellä valmistaaksesi hänen teitään,'),
(1693909,58,42,1,77,'antaaksesi hänen kansalleen pelastuksen tuntemisen heidän syntiensä anteeksisaamisessa,'),
(1693910,58,42,1,78,'meidän Jumalamme sydämellisen laupeuden tähden, jonka kautta meidän puoleemme katsoo aamun koitto korkeudesta,'),
(1693911,58,42,1,79,'loistaen meille, jotka istumme pimeydessä ja kuoleman varjossa, ja ohjaten meidän jalkamme rauhan tielle."'),
(1693912,58,42,1,80,'Ja lapsi kasvoi ja vahvistui hengessä. Ja hän oli erämaassa siihen päivään asti, jona hän oli astuva Israelin eteen.'),
(1693913,58,42,2,1,'Ja tapahtui niinä päivinä, että keisari Augustukselta kävi käsky, että kaikki maailma oli verolle pantava.'),
(1693914,58,42,2,2,'Tämä verollepano oli ensimmäinen ja tapahtui Kyreniuksen ollessa Syyrian maaherrana.'),
(1693915,58,42,2,3,'Ja kaikki menivät verolle pantaviksi, kukin omaan kaupunkiinsa.'),
(1693916,58,42,2,4,'Niin Joosefkin lähti Galileasta, Nasaretin kaupungista, ylös Juudeaan, Daavidin kaupunkiin, jonka nimi on Beetlehem, hän kun oli Daavidin huonetta ja sukua,'),
(1693917,58,42,2,5,'verolle pantavaksi Marian, kihlattunsa, kanssa, joka oli raskaana.'),
(1693918,58,42,2,6,'Niin tapahtui heidän siellä ollessaan, että Marian synnyttämisen aika tuli.'),
(1693919,58,42,2,7,'Ja hän synnytti pojan, esikoisensa, ja kapaloi hänet ja pani hänet seimeen, koska heille ei ollut sijaa majatalossa.'),
(1693920,58,42,2,8,'Ja sillä seudulla oli paimenia kedolla vartioimassa yöllä laumaansa.'),
(1693921,58,42,2,9,'Niin heidän edessään seisoi Herran enkeli, ja Herran kirkkaus loisti heidän ympärillään, ja he peljästyivät suuresti.'),
(1693922,58,42,2,10,'Mutta enkeli sanoi heille: "Älkää peljätkö; sillä katso, minä ilmoitan teille suuren ilon, joka on tuleva kaikelle kansalle:'),
(1693923,58,42,2,11,'teille on tänä päivänä syntynyt Vapahtaja, joka on Kristus, Herra, Daavidin kaupungissa.'),
(1693924,58,42,2,12,'Ja tämä on teille merkkinä: te löydätte lapsen kapaloituna ja seimessä makaamassa."'),
(1693925,58,42,2,13,'Ja yhtäkkiä oli enkelin kanssa suuri joukko taivaallista sotaväkeä, ja he ylistivät Jumalaa ja sanoivat:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693926,58,42,2,14,'"Kunnia Jumalalle korkeuksissa, ja maassa rauha ihmisten kesken, joita kohtaan hänellä on hyvä tahto!"'),
(1693927,58,42,2,15,'Ja kun enkelit olivat menneet paimenten luota taivaaseen, niin nämä puhuivat toisillensa: "Menkäämme nyt Beetlehemiin katsomaan sitä, mikä on tapahtunut ja minkä Herra meille ilmoitti".'),
(1693928,58,42,2,16,'Ja he menivät kiiruhtaen ja löysivät Marian ja Joosefin ja lapsen, joka makasi seimessä.'),
(1693929,58,42,2,17,'Ja kun he tämän olivat nähneet, ilmoittivat he sen sanan, joka oli puhuttu heille tästä lapsesta.'),
(1693930,58,42,2,18,'Ja kaikki, jotka sen kuulivat, ihmettelivät sitä, mitä paimenet heille puhuivat.'),
(1693931,58,42,2,19,'Mutta Maria kätki kaikki nämä sanat ja tutkisteli niitä sydämessänsä.'),
(1693932,58,42,2,20,'Ja paimenet palasivat kiittäen ja ylistäen Jumalaa kaikesta, minkä olivat kuulleet ja nähneet, sen mukaan kuin heille oli puhuttu.'),
(1693933,58,42,2,21,'Kun sitten kahdeksan päivää oli kulunut ja lapsi oli ympärileikattava, annettiin hänelle nimi Jeesus, jonka enkeli oli hänelle antanut, ennenkuin hän sikisi äitinsä kohdussa.'),
(1693934,58,42,2,22,'Ja kun heidän puhdistuspäivänsä, Mooseksen lain mukaan, olivat täyttyneet, veivät he hänet ylös Jerusalemiin asettaaksensa hänet Herran eteen'),
(1693935,58,42,2,23,'- niinkuin on kirjoitettuna Herran laissa: "Jokainen miehenpuoli, joka avaa äidinkohdun, luettakoon Herralle pyhitetyksi" -'),
(1693936,58,42,2,24,'ja uhrataksensa, niinkuin Herran laissa on säädetty, parin metsäkyyhkysiä tai kaksi kyyhkysenpoikaa.'),
(1693937,58,42,2,25,'Ja katso, Jerusalemissa oli mies, nimeltä Simeon; hän oli hurskas ja jumalinen mies, joka odotti Israelin lohdutusta, ja Pyhä Henki oli hänen päällänsä.'),
(1693938,58,42,2,26,'Ja Pyhä Henki oli hänelle ilmoittanut, ettei hän ollut näkevä kuolemaa, ennenkuin oli nähnyt Herran Voidellun.'),
(1693939,58,42,2,27,'Ja hän tuli Hengen vaikutuksesta pyhäkköön. Ja kun vanhemmat toivat Jeesus-lasta sisälle tehdäkseen hänelle, niinkuin tapa oli lain mukaan,'),
(1693940,58,42,2,28,'otti hänkin hänet syliinsä ja kiitti Jumalaa ja sanoi:'),
(1693941,58,42,2,29,'"Herra, nyt sinä lasket palvelijasi rauhaan menemään, sanasi mukaan;'),
(1693942,58,42,2,30,'sillä minun silmäni ovat nähneet sinun autuutesi,'),
(1693943,58,42,2,31,'jonka sinä olet valmistanut kaikkien kansojen nähdä,'),
(1693944,58,42,2,32,'valkeudeksi, joka on ilmestyvä pakanoille, ja kirkkaudeksi kansallesi Israelille".'),
(1693945,58,42,2,33,'Ja hänen isänsä ja äitinsä ihmettelivät sitä, mitä hänestä sanottiin.'),
(1693946,58,42,2,34,'Ja Simeon siunasi heitä ja sanoi Marialle, hänen äidilleen: "Katso, tämä on pantu lankeemukseksi ja nousemukseksi monelle Israelissa ja merkiksi, jota vastaan sanotaan'),
(1693947,58,42,2,35,'- ja myös sinun sielusi lävitse on miekka käyvä - että monen sydämen ajatukset tulisivat ilmi".'),
(1693948,58,42,2,36,'Ja oli naisprofeetta, Hanna, Fanuelin tytär, Asserin sukukuntaa. Hän oli jo tullut iälliseksi. Mentyään neitsyenä naimisiin hän oli elänyt miehensä kanssa seitsemän vuotta,'),
(1693949,58,42,2,37,'ja oli nyt leski, kahdeksankymmenen neljän vuoden ikäinen. Hän ei poistunut pyhäköstä, vaan palveli siellä Jumalaa paastoilla ja rukouksilla yötä ja päivää.'),
(1693950,58,42,2,38,'Ja juuri sillä hetkellä hän tuli siihen, ylisti Jumalaa ja puhui lapsesta kaikille, jotka odottivat Jerusalemin lunastusta.'),
(1693951,58,42,2,39,'Ja täytettyään kaiken, mikä Herran lain mukaan oli tehtävä, he palasivat Galileaan, kaupunkiinsa Nasaretiin.'),
(1693952,58,42,2,40,'Ja lapsi kasvoi ja vahvistui ja täyttyi viisaudella, ja Jumalan armo oli hänen päällänsä.'),
(1693953,58,42,2,41,'Ja hänen vanhempansa matkustivat joka vuosi Jerusalemiin pääsiäisjuhlille.'),
(1693954,58,42,2,42,'Hänen ollessaan kaksitoistavuotias he niinikään vaelsivat ylös sinne juhlan tavan mukaan.'),
(1693955,58,42,2,43,'Ja kun ne päivät olivat kuluneet ja he lähtivät kotiin, jäi poikanen Jeesus Jerusalemiin, eivätkä hänen vanhempansa sitä huomanneet.'),
(1693956,58,42,2,44,'He luulivat hänen olevan matkaseurueessa ja kulkivat päivänmatkan ja etsivät häntä sukulaisten ja tuttavien joukosta;'),
(1693957,58,42,2,45,'mutta kun eivät löytäneet, palasivat he Jerusalemiin etsien häntä.'),
(1693958,58,42,2,46,'Ja kolmen päivän kuluttua he löysivät hänet pyhäköstä, jossa hän istui opettajain keskellä kuunnellen heitä ja kysellen heiltä.'),
(1693959,58,42,2,47,'Ja kaikki, jotka häntä kuulivat, ihmettelivät hänen ymmärrystänsä ja vastauksiansa.'),
(1693960,58,42,2,48,'Ja hänet nähdessään hänen vanhempansa hämmästyivät, ja hänen äitinsä sanoi hänelle: "Poikani, miksi meille näin teit? Katso, sinun isäsi ja minä olemme huolestuneina etsineet sinua."'),
(1693961,58,42,2,49,'Niin hän sanoi heille: "Mitä te minua etsitte? Ettekö tienneet, että minun pitää niissä oleman, mitkä minun Isäni ovat?"'),
(1693962,58,42,2,50,'Mutta he eivät ymmärtäneet sitä sanaa, jonka hän heille puhui.'),
(1693963,58,42,2,51,'Ja hän lähti heidän kanssansa ja tuli Nasaretiin ja oli heille alamainen. Ja hänen äitinsä kätki kaikki nämä sanat sydämeensä.'),
(1693964,58,42,2,52,'Ja Jeesus varttui viisaudessa ja iässä ja armossa Jumalan ja ihmisten edessä.'),
(1693965,58,42,3,1,'Viidentenätoista keisari Tiberiuksen hallitusvuotena, kun Pontius Pilatus oli Juudean maaherrana ja Herodes Galilean neljännysruhtinaana ja hänen veljensä Filippus Iturean ja Trakonitiinmaan neljännysruhtinaana ja Lysanias Abilenen neljännysruhtinaana,'),
(1693966,58,42,3,2,'siihen aikaan kun Hannas oli ylimmäisenä pappina, ynnä myös Kaifas, tuli Jumalan sana Johannekselle, Sakariaan pojalle, erämaassa.'),
(1693967,58,42,3,3,'Ja hän vaelsi kaikissa seuduissa Jordanin varrella ja saarnasi parannuksen kastetta syntien anteeksisaamiseksi,'),
(1693968,58,42,3,4,'niinkuin on kirjoitettuna profeetta Esaiaan sanojen kirjassa: "Huutavan ääni kuuluu erämaassa: ''Valmistakaa Herralle tie, tehkää polut hänelle tasaisiksi''.'),
(1693969,58,42,3,5,'Kaikki laaksot täytettäköön, ja kaikki vuoret ja kukkulat alennettakoon, ja mutkat tulkoot suoriksi ja koleikot tasaisiksi teiksi,'),
(1693970,58,42,3,6,'ja kaikki liha on näkevä Jumalan autuuden."'),
(1693971,58,42,3,7,'Niin hän sanoi kansalle, joka vaelsi hänen kastettavakseen: "Te kyykäärmeitten sikiöt, kuka on teitä neuvonut pakenemaan tulevaista vihaa?'),
(1693972,58,42,3,8,'Tehkää sentähden parannuksen soveliaita hedelmiä, älkääkä ruvetko sanomaan mielessänne: ''Onhan meillä isänä Aabraham'', sillä minä sanon teille, että Jumala voi näistä kivistä herättää lapsia Aabrahamille.'),
(1693973,58,42,3,9,'Jo on myös kirves pantu puitten juurelle; jokainen puu, joka ei tee hyvää hedelmää, siis hakataan pois ja heitetään tuleen."'),
(1693974,58,42,3,10,'Ja kansa kysyi häneltä sanoen: "Mitä meidän siis pitää tekemän?"'),
(1693975,58,42,3,11,'Hän vastasi ja sanoi heille: "Jolla on kaksi ihokasta, antakoon toisen sille, joka on ilman; ja jolla on ruokaa, tehköön samoin".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1693976,58,42,3,12,'Niin tuli myös publikaaneja kastettaviksi, ja he sanoivat hänelle: "Opettaja, mitä meidän pitää tekemän?"'),
(1693977,58,42,3,13,'Hän sanoi heille: "Älkää vaatiko enempää, kuin mikä teille on säädetty".'),
(1693978,58,42,3,14,'Myös sotamiehet kysyivät häneltä sanoen: "Mitäs meidän pitää tekemän?" Ja hän sanoi heille: "Älkää kiskoko keneltäkään älkääkä kiristäkö, vaan tyytykää palkkaanne".'),
(1693979,58,42,3,15,'Mutta kun kansa yhä odotti ja kaikki ajattelivat sydämessään Johanneksesta, eikö hän itse ehkä ollut Kristus,'),
(1693980,58,42,3,16,'niin Johannes vastasi kaikille sanoen: "Minä kastan teidät vedellä, mutta on tuleva minua väkevämpi, jonka kengänpaulaakaan minä en ole kelvollinen päästämään; hän kastaa teidät Pyhällä Hengellä ja tulella.'),
(1693981,58,42,3,17,'Hänellä on viskimensä kädessään, ja hän puhdistaa puimatanterensa ja kokoaa nisut aittaansa, mutta ruumenet hän polttaa sammumattomassa tulessa."'),
(1693982,58,42,3,18,'Antaen myös monia muita kehoituksia hän julisti kansalle evankeliumia.'),
(1693983,58,42,3,19,'Mutta kun Herodes, neljännysruhtinas, sai häneltä nuhteita veljensä vaimon, Herodiaan, tähden ja kaiken sen pahan tähden, mitä hän, Herodes, oli tehnyt,'),
(1693984,58,42,3,20,'niin hän kaiken muun lisäksi teki senkin, että sulki Johanneksen vankeuteen.'),
(1693985,58,42,3,21,'Kun siis kaikkea kansaa kastettiin ja myöskin Jeesus oli saanut kasteen ja rukoili, niin tapahtui, että taivas aukeni'),
(1693986,58,42,3,22,'ja Pyhä Henki laskeutui hänen päällensä ruumiillisessa muodossa, niinkuin kyyhkynen, ja taivaasta tuli ääni: "Sinä olet minun rakas Poikani; sinuun minä olen mielistynyt".'),
(1693987,58,42,3,23,'Ja hän, Jeesus, oli alottaessaan vaikutuksensa noin kolmenkymmenen vuoden vanha, ja oli, niinkuin luultiin, Joosefin poika. Joosef oli Eelin poika,'),
(1693988,58,42,3,24,'Eeli Mattatin, tämä Leevin, tämä Melkin, tämä Jannain, tämä Joosefin,'),
(1693989,58,42,3,25,'tämä Mattatiaan, tämä Aamoksen, tämä Naahumin, tämä Eslin, tämä Naggain,'),
(1693990,58,42,3,26,'tämä Maahatin, tämä Mattatiaan, tämä Semeinin, tämä Joosekin, tämä Joodan,'),
(1693991,58,42,3,27,'tämä Johananin, tämä Reesan, tämä Serubbaabelin, tämä Sealtielin, tämä Neerin,'),
(1693992,58,42,3,28,'tämä Melkin, tämä Addin, tämä Koosamin, tämä Elmadamin, tämä Eerin,'),
(1693993,58,42,3,29,'tämä Jeesuksen, tämä Elieserin, tämä Joorimin, tämä Mattatin, tämä Leevin,'),
(1693994,58,42,3,30,'tämä Simeonin, tämä Juudan, tämä Joosefin, tämä Joonamin, tämä Eliakimin,'),
(1693995,58,42,3,31,'tämä Melean, tämä Mennan, tämä Mattatan, tämä Naatanin, tämä Daavidin,'),
(1693996,58,42,3,32,'tämä Iisain, tämä Oobedin, tämä Booaan, tämä Saalan, tämä Nahassonin,'),
(1693997,58,42,3,33,'tämä Aminadabin, tämä Adminin, tämä Arnin, tämä Esromin, tämä Faareen, tämä Juudan,'),
(1693998,58,42,3,34,'tämä Jaakobin, tämä Iisakin, tämä Aabrahamin, tämä Taaran, tämä Naahorin,'),
(1693999,58,42,3,35,'tämä Serukin, tämä Ragaun, tämä Faalekin, tämä Eberin, tämä Saalan,'),
(1694000,58,42,3,36,'tämä Kainamin, tämä Arfaksadin, tämä Seemin, tämä Nooan, tämä Laamekin,'),
(1694001,58,42,3,37,'tämä Metusalan, tämä Eenokin, tämä Jaaretin, tämä Mahalalelin, tämä Keenanin,'),
(1694002,58,42,3,38,'tämä Enoksen, tämä Seetin, tämä Aadamin, tämä Jumalan.'),
(1694003,58,42,4,1,'Sitten Jeesus täynnä Pyhää Henkeä palasi Jordanilta; ja Henki kuljetti häntä erämaassa,'),
(1694004,58,42,4,2,'ja perkele kiusasi häntä neljäkymmentä päivää. Eikä hän syönyt mitään niinä päivinä, mutta kun ne olivat päättyneet, tuli hänen nälkä.'),
(1694005,58,42,4,3,'Niin perkele sanoi hänelle: "Jos sinä olet Jumalan Poika, niin sano tälle kivelle, että se muuttuu leiväksi".'),
(1694006,58,42,4,4,'Jeesus vastasi hänelle: "Kirjoitettu on: ''Ei ihminen elä ainoastaan leivästä''."'),
(1694007,58,42,4,5,'Ja perkele vei hänet korkealle vuorelle ja näytti hänelle yhdessä tuokiossa kaikki maailman valtakunnat'),
(1694008,58,42,4,6,'ja sanoi hänelle: "Sinulle minä annan kaiken tämän valtapiirin ja sen loiston, sillä minun haltuuni se on annettu, ja minä annan sen, kenelle tahdon.'),
(1694009,58,42,4,7,'Jos sinä siis kumarrut minun eteeni, niin tämä kaikki on oleva sinun."'),
(1694010,58,42,4,8,'Jeesus vastasi ja sanoi hänelle: "Kirjoitettu on: ''Sinun pitää kumartaman Herraa, sinun Jumalaasi, ja häntä ainoata palveleman''."'),
(1694011,58,42,4,9,'Niin hän vei hänet Jerusalemiin ja asetti hänet pyhäkön harjalle ja sanoi hänelle: "Jos sinä olet Jumalan Poika, niin heittäydy tästä alas;'),
(1694012,58,42,4,10,'sillä kirjoitettu on: ''Hän antaa enkeleilleen käskyn sinusta, että he varjelevat sinua'','),
(1694013,58,42,4,11,'ja: ''He kantavat sinua käsillänsä, ettet jalkaasi kiveen loukkaisi''."'),
(1694014,58,42,4,12,'Jeesus vastasi ja sanoi hänelle: "Sanottu on: ''Älä kiusaa Herraa, sinun Jumalaasi''."'),
(1694015,58,42,4,13,'Ja kun oli kaiken kiusattavansa kiusannut, poistui perkele hänen luotaan ajaksi.'),
(1694016,58,42,4,14,'Ja Jeesus palasi Hengen voimassa Galileaan; ja sanoma hänestä levisi kaikkiin ympärillä oleviin seutuihin.'),
(1694017,58,42,4,15,'Ja hän opetti heidän synagoogissaan, ja kaikki ylistivät häntä.'),
(1694018,58,42,4,16,'Ja hän saapui Nasaretiin, jossa hänet oli kasvatettu, ja meni tapansa mukaan sapatinpäivänä synagoogaan ja nousi lukemaan.'),
(1694019,58,42,4,17,'Niin hänelle annettiin profeetta Esaiaan kirja, ja kun hän avasi kirjan, löysi hän sen paikan, jossa oli kirjoitettuna:'),
(1694020,58,42,4,18,'"Herran Henki on minun päälläni, sillä hän on voidellut minut julistamaan evankeliumia köyhille; hän on lähettänyt minut saarnaamaan vangituille vapautusta ja sokeille näkönsä saamista, päästämään sorretut vapauteen,'),
(1694021,58,42,4,19,'saarnaamaan Herran otollista vuotta".'),
(1694022,58,42,4,20,'Ja käärittyään kirjan kokoon hän antoi sen palvelijalle ja istuutui; ja kaikkien synagoogassa olevien silmät olivat häneen kiinnitetyt.'),
(1694023,58,42,4,21,'Niin hän rupesi puhumaan heille: "Tänä päivänä tämä kirjoitus on käynyt toteen teidän korvainne kuullen".'),
(1694024,58,42,4,22,'Ja kaikki lausuivat hänestä hyvän todistuksen ja ihmettelivät niitä armon sanoja, jotka hänen suustansa lähtivät; ja he sanoivat: "Eikö tämä ole Joosefin poika?"'),
(1694025,58,42,4,23,'Niin hän sanoi heille: "Kaiketi aiotte sanoa minulle tämän sananlaskun: ''Parantaja, paranna itsesi''; ''tee täälläkin, kotikaupungissasi, niitä suuria tekoja, joita olemme kuulleet tapahtuneen Kapernaumissa''."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694026,58,42,4,24,'Ja hän sanoi: "Totisesti minä sanon teille: ei kukaan profeetta ole otollinen kotikaupungissaan.'),
(1694027,58,42,4,25,'Minä sanon teille totuudessa: monta leskeä oli Eliaan aikana Israelissa, kun taivas oli suljettuna kolme vuotta ja kuusi kuukautta ja suuri nälkä tuli kaikkeen maahan,'),
(1694028,58,42,4,26,'eikä Eliasta lähetetty kenenkään tykö heistä, vaan ainoastaan leskivaimon tykö Siidonin-maan Sareptaan.'),
(1694029,58,42,4,27,'Ja monta pitalista miestä oli Israelissa profeetta Elisan aikana, eikä kukaan heistä tullut puhdistetuksi, vaan ainoastaan Naiman, syyrialainen."'),
(1694030,58,42,4,28,'Tämän kuullessaan kaikki, jotka olivat synagoogassa, tulivat kiukkua täyteen'),
(1694031,58,42,4,29,'ja nousivat ja ajoivat hänet ulos kaupungista ja veivät hänet sen vuoren jyrkänteelle asti, jolle heidän kaupunkinsa oli rakennettu, syöstäkseen hänet alas.'),
(1694032,58,42,4,30,'Mutta hän lähti pois käyden heidän keskitsensä.'),
(1694033,58,42,4,31,'Ja hän meni alas Kapernaumiin, Galilean kaupunkiin, ja opetti kansaa sapattina.'),
(1694034,58,42,4,32,'Ja he olivat hämmästyksissään hänen opetuksestansa, sillä hänen puheessansa oli voima.'),
(1694035,58,42,4,33,'Ja synagoogassa oli mies, jossa oli saastaisen riivaajan henki. Tämä huusi suurella äänellä:'),
(1694036,58,42,4,34,'"Voi, mitä sinulla on meidän kanssamme tekemistä, Jeesus Nasaretilainen? Oletko tullut meitä tuhoamaan? Minä tunnen sinut, kuka olet, sinä Jumalan Pyhä."'),
(1694037,58,42,4,35,'Niin Jeesus nuhteli häntä sanoen: "Vaikene ja lähde hänestä". Ja riivaaja viskasi hänet maahan heidän keskelleen ja lähti hänestä, häntä ollenkaan vahingoittamatta.'),
(1694038,58,42,4,36,'Ja heidät kaikki valtasi hämmästys, ja he puhuivat keskenään sanoen: "Mitä tämä puhe on, sillä hän käskee vallalla ja voimalla saastaisia henkiä, ja ne lähtevät ulos?"'),
(1694039,58,42,4,37,'Ja maine hänestä levisi kaikkialle ympäristön seutuihin.'),
(1694040,58,42,4,38,'Niin hän nousi ja meni synagoogasta Simonin kotiin. Ja Simonin anoppi sairasti kovaa kuumetta, ja he rukoilivat Jeesusta hänen puolestansa.'),
(1694041,58,42,4,39,'Niin hän meni ja kumartui hänen ylitsensä ja nuhteli kuumetta, ja se lähti hänestä; ja heti vaimo nousi ja palveli heitä.'),
(1694042,58,42,4,40,'Auringon laskiessa kaikki, joilla oli sairaita, mikä missäkin taudissa, veivät ne hänen tykönsä. Ja hän pani kätensä heidän itsekunkin päälle ja paransi heidät.'),
(1694043,58,42,4,41,'Myös lähtivät riivaajat ulos monesta, huutaen ja sanoen: "Sinä olet Jumalan Poika!" Mutta hän nuhteli niitä eikä sallinut niiden puhua, koska ne tiesivät hänen olevan Kristuksen.'),
(1694044,58,42,4,42,'Ja päivän tultua hän lähti pois ja meni autioon paikkaan; mutta kansa etsi häntä, ja saavuttuaan hänen luokseen he pidättelivät häntä lähtemästä heidän luotansa.'),
(1694045,58,42,4,43,'Mutta hän sanoi heille: "Minun tulee muillekin kaupungeille julistaa Jumalan valtakunnan evankeliumia, sillä sitä varten minä olen lähetetty".'),
(1694046,58,42,4,44,'Ja hän saarnasi Galilean synagoogissa.'),
(1694047,58,42,5,1,'Kun kansa tunkeutui hänen ympärilleen kuulemaan Jumalan sanaa ja hän seisoi Gennesaretin järven rannalla,'),
(1694048,58,42,5,2,'niin hän näki järven rannassa kaksi venhettä; mutta kalastajat olivat niistä lähteneet ja huuhtoivat verkkojaan.'),
(1694049,58,42,5,3,'Ja hän astui toiseen niistä, joka oli Simonin, ja pyysi häntä viemään sen vähän matkaa maasta; ja hän istui ja opetti kansaa venheestä.'),
(1694050,58,42,5,4,'Mutta puhumasta lakattuaan hän sanoi Simonille: "Vie venhe syvälle ja heittäkää verkkonne apajalle".'),
(1694051,58,42,5,5,'Niin Simon vastasi ja sanoi hänelle: "Mestari, koko yön me olemme tehneet työtä emmekä ole mitään saaneet; mutta sinun käskystäsi minä heitän verkot".'),
(1694052,58,42,5,6,'Ja sen tehtyään he saivat kierretyksi suuren joukon kaloja, ja heidän verkkonsa repeilivät.'),
(1694053,58,42,5,7,'Niin he viittasivat toisessa venheessä oleville tovereilleen, että nämä tulisivat auttamaan heitä; ja he tulivat. Ja he täyttivät molemmat venheet, niin että ne olivat uppoamaisillaan.'),
(1694054,58,42,5,8,'Kun Simon Pietari sen näki, lankesi hän Jeesuksen polvien eteen ja sanoi: "Mene pois minun tyköäni, Herra, sillä minä olen syntinen ihminen".'),
(1694055,58,42,5,9,'Sillä kalansaaliin tähden, jonka he olivat saaneet, oli hämmästys vallannut hänet ja kaikki ne, jotka olivat hänen kanssaan,'),
(1694056,58,42,5,10,'ja samoin myös Simonin kalastuskumppanit, Jaakobin ja Johanneksen, Sebedeuksen pojat. Mutta Jeesus sanoi Simonille: "Älä pelkää, tästedes sinä saat saaliiksi ihmisiä".'),
(1694057,58,42,5,11,'Ja he veivät venheet maihin, jättivät kaikki ja seurasivat häntä.'),
(1694058,58,42,5,12,'Ja kun hän oli eräässä kaupungissa, niin katso, siellä oli mies, yltänsä pitalissa. Ja nähdessään Jeesuksen hän lankesi kasvoilleen ja rukoili häntä sanoen: "Herra, jos tahdot, niin sinä voit minut puhdistaa".'),
(1694059,58,42,5,13,'Niin hän ojensi kätensä, kosketti häntä ja sanoi: "Minä tahdon; puhdistu". Ja kohta pitali lähti hänestä.'),
(1694060,58,42,5,14,'Ja hän kielsi häntä siitä kenellekään puhumasta ja sanoi: "Mene, näytä itsesi papille, ja uhraa puhdistumisestasi, niinkuin Mooses on säätänyt, todistukseksi heille".'),
(1694061,58,42,5,15,'Mutta sanoma hänestä levisi vielä enemmän; ja paljon kansaa kokoontui kuulemaan häntä ja parantuakseen vaivoistansa.'),
(1694062,58,42,5,16,'Mutta hän vetäytyi pois ja oleskeli erämaassa ja rukoili.'),
(1694063,58,42,5,17,'Ja eräänä päivänä, kun hän opetti, istui siinä fariseuksia ja lainopettajia, joita oli tullut kaikista Galilean ja Juudean kylistä ja Jerusalemista; ja Herran voima vaikutti, niin että hän paransi sairaat.'),
(1694064,58,42,5,18,'Ja katso, muutamat miehet kantoivat vuoteella miestä, joka oli halvattu; ja he koettivat viedä hänet sisään ja asettaa Jeesuksen eteen.'),
(1694065,58,42,5,19,'Ja kun he väentungokselta eivät saaneet viedyksi häntä sisään muuta tietä, nousivat he katolle ja laskivat hänet vuoteineen tiilikaton läpi heidän keskellensä Jeesuksen eteen.'),
(1694066,58,42,5,20,'Ja nähdessään heidän uskonsa hän sanoi: "Ihminen, sinun syntisi ovat sinulle anteeksi annetut".'),
(1694067,58,42,5,21,'Niin kirjanoppineet ja fariseukset rupesivat ajattelemaan ja sanomaan: "Kuka tämä on, joka puhuu Jumalan pilkkaa? Kuka voi antaa syntejä anteeksi, paitsi Jumala yksin?"'),
(1694068,58,42,5,22,'Mutta kun Jeesus tiesi heidän ajatuksensa, vastasi hän ja sanoi heille: "Mitä te ajattelette sydämessänne?'),
(1694069,58,42,5,23,'Kumpi on helpompaa, sanoako: ''Sinun syntisi ovat sinulle anteeksi annetut'', vai sanoa: ''Nouse ja käy''?'),
(1694070,58,42,5,24,'Mutta tietääksenne, että Ihmisen Pojalla on valta maan päällä antaa syntejä anteeksi," - hän sanoi halvatulle - "minä sanon sinulle: nouse, ota vuoteesi ja mene kotiisi."'),
(1694071,58,42,5,25,'Ja kohta hän nousi heidän nähtensä, otti vuoteen, jolla oli maannut, ja lähti kotiinsa ylistäen Jumalaa.'),
(1694072,58,42,5,26,'Ja heidät kaikki valtasi hämmästys, ja he ylistivät Jumalaa; ja pelkoa täynnä he sanoivat: "Me olemme tänään nähneet ihmeellisiä".'),
(1694073,58,42,5,27,'Ja sen jälkeen hän lähti sieltä ja näki tulliasemalla istumassa publikaanin, jonka nimi oli Leevi, ja sanoi hänelle: "Seuraa minua".'),
(1694074,58,42,5,28,'Niin tämä jätti kaikki, nousi ja seurasi häntä.'),
(1694075,58,42,5,29,'Ja Leevi valmisti hänelle suuret pidot kodissaan; ja siellä oli suuri joukko publikaaneja ja muita aterioimassa heidän kanssaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694076,58,42,5,30,'Niin fariseukset ja heidän kirjanoppineensa napisivat hänen opetuslapsiansa vastaan ja sanoivat: "Miksi te syötte ja juotte publikaanien ja syntisten kanssa?"'),
(1694077,58,42,5,31,'Jeesus vastasi ja sanoi heille: "Eivät terveet tarvitse parantajaa, vaan sairaat.'),
(1694078,58,42,5,32,'En minä ole tullut kutsumaan vanhurskaita, vaan syntisiä parannukseen."'),
(1694079,58,42,5,33,'Niin he sanoivat hänelle: "Johanneksen opetuslapset paastoavat usein ja pitävät rukouksia, samoin fariseustenkin, mutta sinun opetuslapsesi syövät ja juovat".'),
(1694080,58,42,5,34,'Jeesus sanoi heille: "Ettehän voi vaatia häävieraita paastoamaan silloin, kun ylkä on heidän kanssaan?'),
(1694081,58,42,5,35,'Mutta päivät tulevat, jolloin ylkä otetaan heiltä pois, ja silloin, niinä päivinä, he paastoavat."'),
(1694082,58,42,5,36,'Ja hän sanoi heille myös vertauksen: "Ei kukaan leikkaa uudesta vaipasta paikkaa ja pane vanhaan vaippaan; muutoin hän rikkoo uuden vaipan, eikä uudesta vaipasta otettu paikka vanhaan sovi.'),
(1694083,58,42,5,37,'Eikä kukaan laske nuorta viiniä vanhoihin nahkaleileihin; muutoin nuori viini pakahuttaa leilit, ja viini juoksee maahan, ja leilit turmeltuvat.'),
(1694084,58,42,5,38,'Vaan nuori viini on laskettava uusiin leileihin.'),
(1694085,58,42,5,39,'Eikä kukaan, joka juo vanhaa viiniä, halua nuorta, sillä hän sanoo: ''Vanha on hyvää''."'),
(1694086,58,42,6,1,'Niin tapahtui eräänä sapattina, että hän kulki viljavainioiden halki, ja hänen opetuslapsensa katkoivat tähkäpäitä, hiersivät niitä käsissään ja söivät.'),
(1694087,58,42,6,2,'Silloin muutamat fariseuksista sanoivat: "Miksi teette, mitä ei ole lupa tehdä sapattina?"'),
(1694088,58,42,6,3,'Mutta Jeesus vastasi heille ja sanoi: "Ettekö ole lukeneet, mitä Daavid teki, kun hänen ja hänen seuralaistensa oli nälkä,'),
(1694089,58,42,6,4,'kuinka hän meni Jumalan huoneeseen, otti näkyleivät ja söi ja antoi seuralaisilleenkin, vaikkei niitä ollut lupa syödä muiden kuin ainoastaan pappien?"'),
(1694090,58,42,6,5,'Ja hän sanoi heille: "Ihmisen Poika on sapatin herra".'),
(1694091,58,42,6,6,'Ja toisena sapattina hän meni synagoogaan ja opetti; ja siellä oli mies, jonka oikea käsi oli kuivettunut.'),
(1694092,58,42,6,7,'Ja keksiäkseen jotakin, mistä häntä syyttäisivät, kirjanoppineet ja fariseukset pitivät häntä silmällä, parantaisiko hän sapattina.'),
(1694093,58,42,6,8,'Mutta hän tiesi heidän ajatuksensa ja sanoi miehelle, jonka käsi oli kuivettunut: "Nouse ja astu esille". Ja hän nousi ja astui esille.'),
(1694094,58,42,6,9,'Niin Jeesus sanoi heille: "Minä kysyn teiltä: kumpi on luvallista sapattina: hyvääkö tehdä, vai tehdä pahaa, pelastaako henki, vai hukuttaa?"'),
(1694095,58,42,6,10,'Ja hän katsoi ympärilleen heihin kaikkiin ja sanoi miehelle: "Ojenna kätesi". Mies teki niin, ja hänen kätensä tuli jälleen terveeksi.'),
(1694096,58,42,6,11,'Mutta he vimmastuivat kovin ja puhelivat keskenään, mitä heidän olisi tehtävä Jeesukselle.'),
(1694097,58,42,6,12,'Niin tapahtui niinä päivinä, että hän lähti vuorelle rukoilemaan; ja hän oli siellä kaiken yötä rukoillen Jumalaa.'),
(1694098,58,42,6,13,'Ja päivän tultua hän kutsui tykönsä opetuslapsensa ja valitsi heistä kaksitoista, joille hän myös antoi apostolin nimen:'),
(1694099,58,42,6,14,'Simonin, jolle hän myös antoi nimen Pietari, ja Andreaan, hänen veljensä, ja Jaakobin ja Johanneksen, ja Filippuksen ja Bartolomeuksen,'),
(1694100,58,42,6,15,'ja Matteuksen ja Tuomaan, ja Jaakobin, Alfeuksen pojan, ja Simonin, jota kutsuttiin Kiivailijaksi,'),
(1694101,58,42,6,16,'ja Juudaan, Jaakobin pojan, sekä Juudas Iskariotin, josta tuli kavaltaja.'),
(1694102,58,42,6,17,'Ja hän astui alas heidän kanssaan ja seisahtui lakealle paikalle; ja siellä oli suuri joukko hänen opetuslapsiaan ja paljon kansaa kaikesta Juudeasta ja Jerusalemista ja Tyyron ja Siidonin rantamaasta. Nämä olivat saapuneet kuulemaan häntä ja parantuakseen taudeistansa.'),
(1694103,58,42,6,18,'Ja myös ne, jotka olivat saastaisten henkien vaivaamia, tulivat terveiksi.'),
(1694104,58,42,6,19,'Ja kaikki kansa tahtoi päästä koskettamaan häntä, koska hänestä lähti voima, joka paransi kaikki.'),
(1694105,58,42,6,20,'Ja hän nosti silmänsä opetuslastensa puoleen ja sanoi: "Autuaita olette te, köyhät, sillä teidän on Jumalan valtakunta.'),
(1694106,58,42,6,21,'Autuaita te, jotka nyt isoatte, sillä teidät ravitaan! Autuaita te, jotka nyt itkette, sillä te saatte nauraa!'),
(1694107,58,42,6,22,'Autuaita olette te, kun ihmiset vihaavat teitä ja erottavat teidät yhteydestään ja herjaavat teitä ja pyyhkivät pois teidän nimenne ikäänkuin jonkin pahan - Ihmisen Pojan tähden.'),
(1694108,58,42,6,23,'Iloitkaa sinä päivänä, riemuun ratketkaa; sillä katso, teidän palkkanne on suuri taivaassa; sillä näin tekivät heidän isänsä profeetoille.'),
(1694109,58,42,6,24,'Mutta voi teitä, te rikkaat, sillä te olette jo saaneet lohdutuksenne!'),
(1694110,58,42,6,25,'Voi teitä, jotka nyt olette kylläiset, sillä teidän on oleva nälkä! Voi teitä, jotka nyt nauratte, sillä te saatte murehtia ja itkeä!'),
(1694111,58,42,6,26,'Voi teitä, kun kaikki ihmiset puhuvat teistä hyvää! Sillä niin tekivät heidän isänsä väärille profeetoille.'),
(1694112,58,42,6,27,'Mutta teille, jotka kuulette, minä sanon: rakastakaa vihollisianne, tehkää hyvää niille, jotka teitä vihaavat,'),
(1694113,58,42,6,28,'siunatkaa niitä, jotka teitä kiroavat, rukoilkaa niiden edestä, jotka teitä parjaavat.'),
(1694114,58,42,6,29,'Jos joku lyö sinua poskelle, tarjoa hänelle toinenkin, ja jos joku ottaa sinulta vaipan, älä häneltä kiellä ihokastasikaan.'),
(1694115,58,42,6,30,'Anna jokaiselle, joka sinulta anoo, äläkä vaadi takaisin siltä, joka sinun omaasi ottaa.'),
(1694116,58,42,6,31,'Ja niinkuin te tahdotte ihmisten teille tekevän, niin tehkää tekin heille.'),
(1694117,58,42,6,32,'Ja jos te rakastatte niitä, jotka teitä rakastavat, mitä kiitosta teille siitä tulee? Rakastavathan syntisetkin niitä, jotka heitä rakastavat.'),
(1694118,58,42,6,33,'Ja jos teette hyvää niille, jotka teille hyvää tekevät, mitä kiitosta teille siitä tulee? Niinhän syntisetkin tekevät.'),
(1694119,58,42,6,34,'Ja jos te lainaatte niille, joilta toivotte saavanne takaisin, mitä kiitosta teille siitä tulee? Syntisetkin lainaavat syntisille saadakseen saman verran takaisin.'),
(1694120,58,42,6,35,'Vaan rakastakaa vihollisianne ja tehkää hyvää ja lainatkaa, toivomatta saavanne mitään takaisin; niin teidän palkkanne on oleva suuri, ja te tulette Korkeimman lapsiksi, sillä hän on hyvä kiittämättömille ja pahoille.'),
(1694121,58,42,6,36,'Olkaa armahtavaiset, niinkuin teidän Isänne on armahtavainen.'),
(1694122,58,42,6,37,'Älkääkä tuomiko, niin ei teitäkään tuomita; älkää kadotustuomiota lausuko, niin ei teillekään kadotustuomiota lausuta. Antakaa anteeksi, niin teillekin anteeksi annetaan.'),
(1694123,58,42,6,38,'Antakaa, niin teille annetaan. Hyvä mitta, sullottu, pudistettu ja kukkurainen, annetaan teidän helmaanne; sillä millä mitalla te mittaatte, sillä mitataan teille takaisin."'),
(1694124,58,42,6,39,'Hän sanoi heille myös vertauksen: "Eihän sokea voi sokeaa taluttaa? Eivätkö molemmat lankea kuoppaan?'),
(1694125,58,42,6,40,'Ei ole opetuslapsi opettajaansa parempi; täysin oppineena jokainen on oleva niinkuin hänen opettajansa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694126,58,42,6,41,'Kuinka näet rikan, joka on veljesi silmässä, mutta et huomaa malkaa omassa silmässäsi?'),
(1694127,58,42,6,42,'Kuinka saatat sanoa veljellesi: ''Veljeni, annas, minä otan pois rikan, joka on silmässäsi'', sinä, joka et näe malkaa omassa silmässäsi? Sinä ulkokullattu, ota ensin malka omasta silmästäsi, sitten sinä näet ottaa pois rikan, joka on veljesi silmässä.'),
(1694128,58,42,6,43,'Sillä ei ole hyvää puuta, joka tekee huonon hedelmän, eikä taas huonoa puuta, joka tekee hyvän hedelmän;'),
(1694129,58,42,6,44,'sillä jokainen puu tunnetaan hedelmästään. Eihän viikunoita koota orjantappuroista, eikä viinirypäleitä korjata orjanruusupensaasta.'),
(1694130,58,42,6,45,'Hyvä ihminen tuo sydämensä hyvän runsaudesta esiin hyvää, ja paha tuo pahastansa esiin pahaa; sillä sydämen kyllyydestä suu puhuu.'),
(1694131,58,42,6,46,'Miksi te huudatte minulle: ''Herra, Herra!'' ettekä tee, mitä minä sanon?'),
(1694132,58,42,6,47,'Jokainen, joka tulee minun tyköni ja kuulee minun sanani ja tekee niiden mukaan - minä osoitan teille, kenen kaltainen hän on.'),
(1694133,58,42,6,48,'Hän on miehen kaltainen, joka huonetta rakentaessaan kaivoi syvään ja laski perustuksen kalliolle; kun sitten tulva tuli, syöksähti virta sitä huonetta vastaan, mutta ei voinut sitä horjuttaa, sillä se oli hyvästi rakennettu.'),
(1694134,58,42,6,49,'Mutta joka kuulee eikä tee, se on miehen kaltainen, joka perustusta panematta rakensi huoneensa maan pinnalle; ja virta syöksähti sitä vastaan, ja heti se sortui, ja sen huoneen kukistuminen oli suuri."'),
(1694135,58,42,7,1,'Kun hän oli kansan kuullen kaikki nämä puheensa puhunut, meni hän Kapernaumiin.'),
(1694136,58,42,7,2,'Ja eräällä sadanpäämiehellä oli palvelija, joka sairasti ja oli kuolemaisillaan ja jota hän piti suuressa arvossa.'),
(1694137,58,42,7,3,'Ja kuultuaan Jeesuksesta hän lähetti juutalaisten vanhimpia hänen tykönsä ja pyysi, että hän tulisi parantamaan hänen palvelijansa.'),
(1694138,58,42,7,4,'Kun nämä saapuivat Jeesuksen tykö, pyysivät he häntä hartaasti ja sanoivat: "Hän ansaitsee, että teet hänelle tämän;'),
(1694139,58,42,7,5,'sillä hän rakastaa meidän kansaamme, ja hän on rakentanut meille synagoogan".'),
(1694140,58,42,7,6,'Niin Jeesus lähti heidän kanssansa. Mutta kun hän ei enää ollut kaukana talosta, lähetti sadanpäämies ystäviänsä sanomaan hänelle: "Herra, älä vaivaa itseäsi, sillä en minä ole sen arvoinen, että tulisit minun kattoni alle;'),
(1694141,58,42,7,7,'sentähden en katsonutkaan itseäni arvolliseksi tulemaan sinun luoksesi; vaan sano sana, niin minun palvelijani paranee.'),
(1694142,58,42,7,8,'Sillä minä itsekin olen toisen vallan alaiseksi asetettu, ja minulla on sotamiehiä käskettävinäni, ja minä sanon tälle: ''Mene'', ja hän menee, ja toiselle: ''Tule'', ja hän tulee, ja palvelijalleni: ''Tee tämä'', ja hän tekee."'),
(1694143,58,42,7,9,'Tämän kuultuaan Jeesus ihmetteli häntä, kääntyi ja sanoi kansalle, joka häntä seurasi: "Minä sanon teille: en ole Israelissakaan löytänyt näin suurta uskoa."'),
(1694144,58,42,7,10,'Ja taloon palatessaan lähettiläät tapasivat palvelijan terveenä.'),
(1694145,58,42,7,11,'Sen jälkeen hän vaelsi Nain nimiseen kaupunkiin, ja hänen kanssaan vaelsivat hänen opetuslapsensa ynnä suuri kansanjoukko.'),
(1694146,58,42,7,12,'Kun hän nyt lähestyi kaupungin porttia, katso, silloin kannettiin ulos kuollutta, äitinsä ainokaista poikaa. Ja äiti oli leski, ja hänen kanssaan kulki paljon kaupungin kansaa.'),
(1694147,58,42,7,13,'Ja hänet nähdessään Herra armahti häntä ja sanoi hänelle: "Älä itke".'),
(1694148,58,42,7,14,'Ja hän meni ja kosketti paareja; niin kantajat seisahtuivat. Ja hän sanoi: "Nuorukainen, minä sanon sinulle: nouse."'),
(1694149,58,42,7,15,'Niin kuollut nousi istualleen ja rupesi puhumaan. Ja hän antoi hänet hänen äidillensä.'),
(1694150,58,42,7,16,'Ja heidät kaikki valtasi pelko, ja he ylistivät Jumalaa sanoen: "Suuri profeetta on noussut meidän keskellemme", ja: "Jumala on katsonut kansansa puoleen".'),
(1694151,58,42,7,17,'Ja tämä puhe hänestä levisi koko Juudeaan ja kaikkiin ympärillä oleviin seutuihin.'),
(1694152,58,42,7,18,'Ja Johannekselle kertoivat hänen opetuslapsensa tästä kaikesta.'),
(1694153,58,42,7,19,'Niin Johannes kutsui luoksensa opetuslapsistaan kaksi ja lähetti heidät Herran tykö kysymään: "Oletko sinä se tuleva, vai pitääkö meidän toista odottaman?"'),
(1694154,58,42,7,20,'Miehet saapuivat hänen tykönsä ja sanoivat: "Johannes Kastaja on lähettänyt meidät sinun tykösi ja kysyy: ''Oletko sinä se tuleva, vai pitääkö meidän toista odottaman?''"'),
(1694155,58,42,7,21,'Sillä hetkellä hän juuri paransi useita taudeista ja vitsauksista ja pahoista hengistä, ja monelle sokealle hän antoi näön.'),
(1694156,58,42,7,22,'Niin hän vastasi ja sanoi heille: "Menkää ja kertokaa Johannekselle, mitä olette nähneet ja kuulleet: sokeat saavat näkönsä, rammat kävelevät, pitaliset puhdistuvat, kuurot kuulevat, kuolleet herätetään, köyhille julistetaan evankeliumia.'),
(1694157,58,42,7,23,'Ja autuas on se, joka ei loukkaannu minuun."'),
(1694158,58,42,7,24,'Kun Johanneksen lähettiläät olivat menneet, rupesi hän puhumaan kansalle Johanneksesta: "Mitä te lähditte erämaahan katselemaan? Ruokoako, jota tuuli huojuttaa?'),
(1694159,58,42,7,25,'Vai mitä lähditte katsomaan? Ihmistäkö, hienoihin vaatteisiin puettua? Katso, ne jotka koreissa vaatteissa käyvät ja herkullisesti elävät, ne ovat kuningasten linnoissa.'),
(1694160,58,42,7,26,'Vai mitä lähditte katsomaan? Profeettaako? Totisesti, minä sanon teille: hän on enemmän kuin profeetta.'),
(1694161,58,42,7,27,'Tämä on se, josta on kirjoitettu: ''Katso, minä lähetän enkelini sinun edelläsi, ja hän on valmistava tiesi sinun eteesi''.'),
(1694162,58,42,7,28,'Minä sanon teille: ei ole vaimoista syntyneitten joukossa yhtäkään suurempaa kuin Johannes; mutta vähäisin Jumalan valtakunnassa on suurempi kuin hän.'),
(1694163,58,42,7,29,'Ja kaikki kansa, joka häntä kuuli, publikaanitkin, tunnustivat Jumalan vanhurskaaksi ja antoivat kastaa itsensä Johanneksen kasteella.'),
(1694164,58,42,7,30,'Mutta fariseukset ja lainoppineet tekivät turhaksi Jumalan aivoituksen heitä kohtaan eivätkä ottaneet Johannekselta kastetta.'),
(1694165,58,42,7,31,'Mihin minä siis vertaan tämän sukupolven ihmiset, ja kenen kaltaisia he ovat?'),
(1694166,58,42,7,32,'He ovat lasten kaltaisia, jotka istuvat torilla ja huutavat toisilleen ja sanovat: ''Me soitimme teille huilua, ja te ette karkeloineet; me veisasimme itkuvirsiä, ja te ette itkeneet''.'),
(1694167,58,42,7,33,'Sillä Johannes Kastaja on tullut, ei syö leipää eikä juo viiniä, ja te sanotte: ''Hänessä on riivaaja''.'),
(1694168,58,42,7,34,'Ihmisen Poika on tullut, syö ja juo, ja te sanotte: ''Katso syömäriä ja viininjuojaa, publikaanien ja syntisten ystävää!'''),
(1694169,58,42,7,35,'Ja viisaus on kaikkien lastensa puolelta oikeaksi näytetty."'),
(1694170,58,42,7,36,'Niin eräs fariseuksista pyysi häntä ruualle kanssaan; ja hän meni fariseuksen taloon ja asettui aterialle.'),
(1694171,58,42,7,37,'Ja katso, siinä kaupungissa oli nainen, joka eli syntisesti; ja kun hän sai tietää, että Jeesus oli aterialla fariseuksen talossa, toi hän alabasteripullon täynnä hajuvoidetta'),
(1694172,58,42,7,38,'ja asettui hänen taakseen hänen jalkojensa kohdalle, itki ja rupesi kastelemaan hänen jalkojansa kyynelillään ja kuivasi ne päänsä hiuksilla ja suuteli hänen jalkojaan ja voiteli ne hajuvoiteella.'),
(1694173,58,42,7,39,'Mutta kun fariseus, joka oli hänet kutsunut, sen näki, ajatteli hän mielessään näin: "Jos tämä olisi profeetta, tietäisi hän, mikä ja millainen tuo nainen on, joka häneen koskee: että hän on syntinen."'),
(1694174,58,42,7,40,'Niin Jeesus vastasi ja sanoi hänelle: "Simon, minulla on jotakin sanomista sinulle". Hän virkkoi: "Opettaja, sano". -'),
(1694175,58,42,7,41,'"Lainanantajalla oli kaksi velallista; toinen oli velkaa viisisataa denaria, toinen viisikymmentä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694176,58,42,7,42,'Kun heillä ei ollut, millä maksaa, antoi hän molemmille velan anteeksi. Kumpi heistä siis rakastaa häntä enemmän?"'),
(1694177,58,42,7,43,'Simon vastasi ja sanoi: "Minun mielestäni se, jolle hän antoi enemmän anteeksi". Hän sanoi hänelle: "Oikein sinä ratkaisit".'),
(1694178,58,42,7,44,'Ja naiseen kääntyen hän sanoi Simonille: "Näetkö tämän naisen? Minä tulin sinun taloosi; et sinä antanut vettä minun jaloilleni, mutta tämä kasteli kyynelillään minun jalkani ja kuivasi ne hiuksillaan.'),
(1694179,58,42,7,45,'Et sinä antanut minulle suudelmaa, mutta tämä ei ole lakannut suutelemasta minun jalkojani siitä asti, kuin tulin sisään.'),
(1694180,58,42,7,46,'Et sinä voidellut öljyllä minun päätäni, mutta tämä voiteli hajuvoiteella minun jalkani.'),
(1694181,58,42,7,47,'Sentähden minä sanon sinulle: tämän paljot synnit ovat anteeksi annetut: hänhän näet rakasti paljon; mutta jolle vähän anteeksi annetaan, se rakastaa vähän."'),
(1694182,58,42,7,48,'Sitten hän sanoi naiselle: "Sinun syntisi ovat anteeksi annetut".'),
(1694183,58,42,7,49,'Niin ateriakumppanit rupesivat ajattelemaan mielessänsä: "Kuka tämä on, joka synnitkin anteeksi antaa?"'),
(1694184,58,42,7,50,'Mutta hän sanoi naiselle: "Sinun uskosi on sinut pelastanut; mene rauhaan".'),
(1694185,58,42,8,1,'Ja sen jälkeen hän vaelsi kaupungista kaupunkiin ja kylästä kylään ja saarnasi ja julisti Jumalan valtakunnan evankeliumia; ja ne kaksitoista olivat hänen kanssansa,'),
(1694186,58,42,8,2,'niin myös muutamia naisia, jotka olivat parannetut pahoista hengistä ja taudeista: Maria, Magdaleenaksi kutsuttu, josta seitsemän riivaajaa oli lähtenyt ulos,'),
(1694187,58,42,8,3,'ja Johanna, Herodeksen taloudenhoitajan Kuusaan vaimo, ja Susanna ja useita muita, jotka palvelivat heitä varoillansa.'),
(1694188,58,42,8,4,'Kun paljon kansaa kokoontui ja ihmisiä kulki joka kaupungista hänen tykönsä, puhui hän vertauksella:'),
(1694189,58,42,8,5,'"Kylväjä meni kylvämään siementänsä. Ja hänen kylväessään putosi osa tien oheen ja tallautui, ja taivaan linnut söivät sen.'),
(1694190,58,42,8,6,'Ja osa putosi kalliolle, ja oraalle noustuaan se kuivettui, kun sillä ei ollut kosteutta.'),
(1694191,58,42,8,7,'Ja osa putosi orjantappurain sekaan, ja orjantappurat kasvoivat mukana ja tukahuttivat sen.'),
(1694192,58,42,8,8,'Ja osa putosi hyvään maahan, kasvoi ja teki satakertaisen hedelmän." Tämän sanottuaan hän lausui suurella äänellä: "Jolla on korvat kuulla, se kuulkoon".'),
(1694193,58,42,8,9,'Niin hänen opetuslapsensa kysyivät häneltä, mitä tämä vertaus merkitsi.'),
(1694194,58,42,8,10,'Hän sanoi: "Teidän on annettu tuntea Jumalan valtakunnan salaisuudet, mutta muille ne esitetään vertauksissa, että he, vaikka näkevät, eivät näkisi, ja vaikka kuulevat, eivät ymmärtäisi.'),
(1694195,58,42,8,11,'Vertaus on tämä: siemen on Jumalan sana.'),
(1694196,58,42,8,12,'Mitkä tien oheen putosivat, ovat ne, jotka kuulevat, mutta sitten perkele tulee ja ottaa sanan pois heidän sydämestään, etteivät he uskoisi ja pelastuisi.'),
(1694197,58,42,8,13,'Ja mitkä kalliolle putosivat, ovat ne, jotka kuullessaan sanan ottavat sen ilolla vastaan, mutta joilla ei ole juurta: ainoastaan ajaksi he uskovat ja kiusauksen hetkellä luopuvat.'),
(1694198,58,42,8,14,'Mikä taas orjantappuroihin putosi, ne ovat ne, jotka kuulevat, mutta vaeltaessaan tukehtuvat tämän elämän huoliin, rikkauteen ja hekumoihin, eivätkä tuota kypsää hedelmää.'),
(1694199,58,42,8,15,'Mutta mikä hyvään maahan putosi, ne ovat ne, jotka sanan kuultuansa säilyttävät sen vilpittömässä ja hyvässä sydämessä ja tuottavat hedelmän kärsivällisyydessä.'),
(1694200,58,42,8,16,'Ei kukaan joka sytyttää lampun, peitä sitä astialla tai pane vuoteen alle, vaan panee sen lampunjalkaan, että sisälletulijat näkisivät valon.'),
(1694201,58,42,8,17,'Sillä ei ole mitään salattua, mikä ei tule ilmi, eikä kätkettyä, mikä ei tule tunnetuksi ja joudu päivän valoon.'),
(1694202,58,42,8,18,'Katsokaa siis, miten kuulette; sillä sille, jolla on, annetaan, mutta siltä, jolla ei ole, otetaan pois sekin, minkä hän luulee itsellään olevan."'),
(1694203,58,42,8,19,'Ja hänen äitinsä ja veljensä tulivat häntä tapaamaan, mutta eivät väentungokselta päässeet hänen tykönsä.'),
(1694204,58,42,8,20,'Niin hänelle ilmoitettiin: "Sinun äitisi ja veljesi seisovat ulkona ja tahtovat nähdä sinua".'),
(1694205,58,42,8,21,'Mutta hän vastasi ja sanoi heille: "Minun äitini ja veljeni ovat nämä, jotka kuulevat Jumalan sanan ja sen mukaan tekevät".'),
(1694206,58,42,8,22,'Niin tapahtui eräänä päivänä, että hän astui opetuslapsinensa venheeseen ja sanoi heille: "Menkäämme järven tuolle puolen". Ja he lähtivät vesille.'),
(1694207,58,42,8,23,'Ja heidän purjehtiessaan hän nukkui. Mutta alas järvelle syöksyi myrskytuuli, ja venhe tuli vettä täyteen, ja he olivat vaarassa.'),
(1694208,58,42,8,24,'Niin he menivät ja herättivät hänet sanoen: "Mestari, mestari, me hukumme!" Ja herättyään hän nuhteli tuulta ja veden aallokkoa; ja ne asettuivat, ja tuli tyven.'),
(1694209,58,42,8,25,'Ja hän sanoi heille: "Missä on teidän uskonne?" Mutta pelko oli vallannut heidät, ja he ihmettelivät, sanoen toisilleen: "Kuka onkaan tämä, kun hän käskee sekä tuulia että vettä, ja ne tottelevat häntä?"'),
(1694210,58,42,8,26,'Ja he purjehtivat gerasalaisten alueelle, joka on vastapäätä Galileaa.'),
(1694211,58,42,8,27,'Ja kun hän oli noussut maihin, tuli häntä vastaan kaupungista mies, jossa oli riivaajia; ja hän ei ollut pitkään aikaan pukenut vaatteita ylleen eikä asunut huoneessa, vaan haudoissa.'),
(1694212,58,42,8,28,'Kun hän näki Jeesuksen, parkaisi hän ja lankesi maahan hänen eteensä ja huusi suurella äänellä: "Mitä sinulla on minun kanssani tekemistä, Jeesus, Jumalan, Korkeimman, Poika? Minä rukoilen sinua: älä minua vaivaa."'),
(1694213,58,42,8,29,'Sillä hän oli käskemäisillään saastaista henkeä menemään ulos siitä miehestä. Sillä pitkät ajat se oli temponut häntä mukaansa; hänet oli sidottu kahleisiin ja jalkanuoriin, ja häntä oli vartioitu, mutta hän oli katkaissut siteet ja kulkeutunut riivaajan ajamana erämaihin.'),
(1694214,58,42,8,30,'Niin Jeesus kysyi siltä sanoen: "Mikä on nimesi?" Hän vastasi: "Legio"; sillä monta riivaajaa oli mennyt häneen.'),
(1694215,58,42,8,31,'Ja ne pyysivät häntä, ettei hän käskisi heidän mennä syvyyteen.'),
(1694216,58,42,8,32,'Niin siellä oli vuorella suuri sikalauma laitumella; ja ne pyysivät häntä, että hän antaisi heille luvan mennä sikoihin. Ja hän antoi niille luvan.'),
(1694217,58,42,8,33,'Niin riivaajat lähtivät ulos miehestä ja menivät sikoihin. Silloin lauma syöksyi jyrkännettä alas järveen ja hukkui.'),
(1694218,58,42,8,34,'Mutta nähtyään, mitä oli tapahtunut, paimentajat pakenivat ja kertoivat siitä kaupungissa ja maataloissa.'),
(1694219,58,42,8,35,'Niin kansa lähti katsomaan, mitä oli tapahtunut, ja he tulivat Jeesuksen luo ja tapasivat miehen, josta riivaajat olivat lähteneet, istumassa Jeesuksen jalkojen juuressa puettuna ja täydessä ymmärryksessä; ja he peljästyivät.'),
(1694220,58,42,8,36,'Mutta silminnäkijät kertoivat heille, kuinka riivattu oli tullut terveeksi.'),
(1694221,58,42,8,37,'Ja koko gerasalaisten seutukunnan kansa pyysi häntä poistumaan heidän luotansa, sillä suuri pelko oli vallannut heidät; niin hän astui venheeseen ja palasi takaisin.'),
(1694222,58,42,8,38,'Ja mies, josta riivaajat olivat lähteneet, pyysi häneltä saada olla hänen kanssaan. Mutta Jeesus lähetti hänet luotansa sanoen:'),
(1694223,58,42,8,39,'"Palaja kotiisi ja kerro, kuinka suuria töitä Jumala on sinulle tehnyt". Ja hän meni ja julisti kaikkialla kaupungissa, kuinka suuria töitä Jeesus oli hänelle tehnyt.'),
(1694224,58,42,8,40,'Kun Jeesus palasi, oli kansa häntä vastassa; sillä kaikki odottivat häntä.'),
(1694225,58,42,8,41,'Ja katso, silloin tuli mies, nimeltä Jairus, joka oli synagoogan esimies. Ja hän lankesi Jeesuksen jalkojen juureen ja pyysi häntä tulemaan kotiinsa,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694226,58,42,8,42,'sillä hänellä oli tytär, ainoa lapsi, noin kaksitoistavuotias, ja se oli kuolemaisillaan. Mutta hänen sinne mennessään väentungos ahdisti häntä.'),
(1694227,58,42,8,43,'Ja siellä oli nainen, joka kaksitoista vuotta oli sairastanut verenjuoksua ja lääkäreille kuluttanut kaiken omaisuutensa, eikä kukaan ollut voinut häntä parantaa.'),
(1694228,58,42,8,44,'Tämä lähestyi takaapäin ja kosketti hänen vaippansa tupsua, ja heti hänen verenjuoksunsa asettui.'),
(1694229,58,42,8,45,'Ja Jeesus sanoi: "Kuka minuun koski?" Mutta kun kaikki kielsivät, sanoi Pietari ja ne, jotka olivat hänen kanssaan: "Mestari, väentungos ahdistaa ja pusertaa sinua".'),
(1694230,58,42,8,46,'Mutta Jeesus sanoi: "Joku minuun koski; sillä minä tunsin, että voimaa lähti minusta".'),
(1694231,58,42,8,47,'Kun nainen näki, ettei hän pysynyt salassa, tuli hän vavisten, lankesi hänen eteensä ja ilmoitti kaiken kansan kuullen, mistä syystä hän oli koskenut häneen ja kuinka hän oli kohta tullut terveeksi.'),
(1694232,58,42,8,48,'Niin hän sanoi hänelle: "Tyttäreni, uskosi on sinut pelastanut; mene rauhaan".'),
(1694233,58,42,8,49,'Hänen vielä puhuessaan tuli joku synagoogan esimiehen kotoa ja sanoi: "Tyttäresi on kuollut; älä enää opettajaa vaivaa".'),
(1694234,58,42,8,50,'Mutta sen kuultuaan Jeesus sanoi hänelle: "Älä pelkää; usko ainoastaan, niin hän paranee".'),
(1694235,58,42,8,51,'Ja kun hän tuli taloon, ei hän sallinut kenenkään muun käydä sisälle kanssaan kuin Pietarin ja Johanneksen ja Jaakobin sekä lapsen isän ja äidin.'),
(1694236,58,42,8,52,'Ja kaikki itkivät ja vaikeroivat tyttöä. Mutta Jeesus sanoi: "Älkää itkekö, sillä hän ei ole kuollut, vaan nukkuu".'),
(1694237,58,42,8,53,'Niin he nauroivat häntä, tietäen tytön kuolleeksi.'),
(1694238,58,42,8,54,'Mutta hän tarttui hänen käteensä ja huusi sanoen: "Lapsi, nouse!"'),
(1694239,58,42,8,55,'Niin hänen henkensä palasi, ja hän nousi heti ylös; ja Jeesus käski antaa hänelle syötävää.'),
(1694240,58,42,8,56,'Ja hänen vanhempansa hämmästyivät; mutta Jeesus kielsi heitä kenellekään sanomasta, mitä oli tapahtunut.'),
(1694241,58,42,9,1,'Niin hän kutsui kokoon ne kaksitoista ja antoi heille voiman ja vallan kaikkia riivaajia vastaan ja voiman parantaa tauteja.'),
(1694242,58,42,9,2,'Ja hän lähetti heidät julistamaan Jumalan valtakuntaa ja parantamaan sairaita.'),
(1694243,58,42,9,3,'Ja hän sanoi heille: "Älkää ottako mitään matkalle, ei sauvaa, ei laukkua, ei leipää, ei rahaa, älköön myös kenelläkään olko kahta ihokasta.'),
(1694244,58,42,9,4,'Ja mihin taloon tulette, siihen jääkää, ja siitä lähtekää matkallenne.'),
(1694245,58,42,9,5,'Ja missä eivät ota teitä vastaan, siitä kaupungista lähtekää pois, ja pudistakaa tomu jaloistanne, todistukseksi heitä vastaan."'),
(1694246,58,42,9,6,'Niin he lähtivät ja kulkivat kylästä kylään julistaen evankeliumia ja parantaen sairaita kaikkialla.'),
(1694247,58,42,9,7,'Ja neljännysruhtinas Herodes sai kuulla kaikki, mitä tapahtui, eikä tiennyt, mitä ajatella; sillä muutamat sanoivat: "Johannes on noussut kuolleista",'),
(1694248,58,42,9,8,'mutta toiset: "Elias on ilmestynyt", toiset taas: "Joku vanhoista profeetoista on noussut ylös".'),
(1694249,58,42,9,9,'Ja Herodes sanoi: "Johanneksen minä olen mestauttanut; mutta kuka tämä on, josta minä tuollaista kuulen?" Ja hän etsi tilaisuutta saadakseen nähdä hänet.'),
(1694250,58,42,9,10,'Ja apostolit palasivat ja kertoivat Jeesukselle kaikki, mitä olivat tehneet. Niin hän otti heidät mukaansa ja vetäytyi yksinäisyyteen lähelle Beetsaida nimistä kaupunkia.'),
(1694251,58,42,9,11,'Mutta kun kansa sai sen tietää, seurasivat he häntä; ja hän otti heidät vastaan ja puhui heille Jumalan valtakunnasta ja teki terveiksi ne, jotka parantamista tarvitsivat.'),
(1694252,58,42,9,12,'Ja päivä alkoi laskea. Niin ne kaksitoista tulivat ja sanoivat hänelle: "Laske kansa luotasi, että he menisivät ympärillä oleviin kyliin ja maataloihin majoittumaan ja saamaan ravintoa, sillä täällä me olemme autiossa paikassa".'),
(1694253,58,42,9,13,'Mutta hän sanoi heille: "Antakaa te heille syödä". Niin he sanoivat: "Meillä ei ole enempää kuin viisi leipää ja kaksi kalaa, ellemme lähde ostamaan ruokaa kaikelle tälle kansalle".'),
(1694254,58,42,9,14,'Sillä heitä oli noin viisituhatta miestä. Niin hän sanoi opetuslapsilleen: "Asettakaa heidät aterioimaan ruokakunnittain, noin viisikymmentä kuhunkin".'),
(1694255,58,42,9,15,'Ja he tekivät niin ja asettivat kaikki aterioimaan.'),
(1694256,58,42,9,16,'Niin hän otti ne viisi leipää ja kaksi kalaa, katsoi ylös taivaaseen ja siunasi ne ja mursi ja antoi opetuslapsilleen kansan eteen pantaviksi.'),
(1694257,58,42,9,17,'Ja kaikki söivät ja tulivat ravituiksi; ja heiltä jääneet tähteet kerättiin, kaksitoista vakallista palasia.'),
(1694258,58,42,9,18,'Ja tapahtui, kun hän oli yksinäisessä paikassa rukoilemassa ja hänen opetuslapsensa olivat hänen kanssaan, että hän kysyi heiltä ja sanoi: "Kenen kansa sanoo minun olevan?"'),
(1694259,58,42,9,19,'He vastasivat sanoen: "Johannes Kastajan, mutta toiset Eliaan, toiset taas sanovat, että joku vanhoista profeetoista on noussut ylös".'),
(1694260,58,42,9,20,'Niin hän sanoi heille: "Kenenkä te sanotte minun olevan?" Pietari vastasi ja sanoi: "Sinä olet Jumalan Kristus".'),
(1694261,58,42,9,21,'Niin hän vakavasti varoittaen kielsi heitä kenellekään tästä puhumasta'),
(1694262,58,42,9,22,'ja sanoi: "Ihmisen Pojan pitää kärsimän paljon ja joutuman vanhinten ja ylipappien ja kirjanoppineiden hyljittäväksi ja tuleman tapetuksi ja kolmantena päivänä nouseman ylös".'),
(1694263,58,42,9,23,'Ja hän sanoi kaikille: "Jos joku tahtoo minun perässäni kulkea, hän kieltäköön itsensä ja ottakoon joka päivä ristinsä ja seuratkoon minua.'),
(1694264,58,42,9,24,'Sillä joka tahtoo pelastaa elämänsä, hän kadottaa sen, mutta joka kadottaa elämänsä minun tähteni, hän pelastaa sen.'),
(1694265,58,42,9,25,'Sillä mitä se hyödyttää ihmistä, vaikka hän voittaisi omaksensa koko maailman, mutta saattaisi itsensä kadotukseen tai turmioon?'),
(1694266,58,42,9,26,'Sillä joka häpeää minua ja minun sanojani, sitä Ihmisen Poika on häpeävä, kun hän tulee omassa ja Isänsä ja pyhäin enkelien kirkkaudessa.'),
(1694267,58,42,9,27,'Totisesti minä sanon teille: tässä seisovien joukossa on muutamia, jotka eivät maista kuolemaa, ennenkuin näkevät Jumalan valtakunnan."'),
(1694268,58,42,9,28,'Noin kahdeksan päivää sen jälkeen kuin hän oli tämän puhunut, hän otti mukaansa Pietarin ja Johanneksen ja Jaakobin ja nousi vuorelle rukoilemaan.'),
(1694269,58,42,9,29,'Ja hänen rukoillessaan hänen kasvojensa näkö muuttui, ja hänen vaatteensa tulivat säteilevän valkoisiksi.'),
(1694270,58,42,9,30,'Ja katso, hänen kanssaan puhui kaksi miestä, ja ne olivat Mooses ja Elias.'),
(1694271,58,42,9,31,'He näkyivät kirkkaudessa ja puhuivat hänen poismenostansa, jonka hän oli saattava täytäntöön Jerusalemissa.'),
(1694272,58,42,9,32,'Mutta Pietari ja ne, jotka olivat hänen kanssansa, olivat unen raskauttamia; mutta kun he siitä heräsivät, näkivät he hänen kirkkautensa ja ne kaksi miestä, jotka seisoivat hänen luonansa.'),
(1694273,58,42,9,33,'Ja kun nämä olivat eroamassa hänestä, sanoi Pietari Jeesukselle: "Mestari, meidän on tässä hyvä olla; tehkäämme kolme majaa, sinulle yksi ja Moosekselle yksi ja Elialle yksi". Mutta hän ei tiennyt, mitä sanoi.'),
(1694274,58,42,9,34,'Ja hänen tätä sanoessaan tuli pilvi ja peitti heidät varjoonsa; ja he peljästyivät joutuessaan pilveen.'),
(1694275,58,42,9,35,'Ja pilvestä kuului ääni, joka sanoi: "Tämä on minun Poikani, se valittu; kuulkaa häntä".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694276,58,42,9,36,'Ja äänen kuuluessa he huomasivat Jeesuksen olevan yksin. Ja he olivat siitä vaiti eivätkä niinä päivinä ilmoittaneet kenellekään mitään siitä, mitä olivat nähneet.'),
(1694277,58,42,9,37,'Kun he seuraavana päivänä menivät alas vuorelta, tuli paljon kansaa häntä vastaan.'),
(1694278,58,42,9,38,'Ja katso, kansanjoukosta huusi eräs mies sanoen: "Opettaja, minä rukoilen sinua, katsahda minun poikani puoleen, sillä hän on minun ainokaiseni;'),
(1694279,58,42,9,39,'ja katso, hänen kimppuunsa käy henki, ja heti hän parkaisee, ja se kouristaa häntä, niin että vaahto lähtee; ja vaivoin se hänestä poistuu, runnellen häntä.'),
(1694280,58,42,9,40,'Ja minä pyysin sinun opetuslapsiasi ajamaan sitä ulos, mutta he eivät voineet."'),
(1694281,58,42,9,41,'Jeesus vastasi ja sanoi: "Voi, sinä epäuskoinen ja nurja sukupolvi; kuinka kauan minun täytyy olla teidän luonanne ja kärsiä teitä? Tuo poikasi tänne."'),
(1694282,58,42,9,42,'Ja vielä pojan tullessakin riivaaja repi häntä ja kouristi kovin. Mutta Jeesus nuhteli saastaista henkeä ja paransi pojan ja antoi hänet takaisin hänen isällensä.'),
(1694283,58,42,9,43,'Ja kaikki hämmästyivät Jumalan valtasuuruutta. Mutta kun kaikki ihmettelivät kaikkea sitä, mitä Jeesus teki, sanoi hän opetuslapsillensa:'),
(1694284,58,42,9,44,'"Ottakaa korviinne nämä sanat: Ihmisen Poika annetaan ihmisten käsiin".'),
(1694285,58,42,9,45,'Mutta he eivät käsittäneet tätä puhetta, ja se oli heiltä peitetty, niin etteivät he sitä ymmärtäneet, ja he pelkäsivät kysyä häneltä, mitä se puhe oli.'),
(1694286,58,42,9,46,'Ja heidän mieleensä tuli ajatus, kuka heistä mahtoi olla suurin.'),
(1694287,58,42,9,47,'Mutta kun Jeesus tiesi heidän sydämensä ajatuksen, otti hän lapsen ja asetti sen viereensä'),
(1694288,58,42,9,48,'ja sanoi heille: "Joka ottaa tykönsä tämän lapsen minun nimeeni, se ottaa tykönsä minut; ja joka ottaa tykönsä minut, ottaa tykönsä hänet, joka on minut lähettänyt. Sillä joka teistä kaikista on pienin, se on suuri."'),
(1694289,58,42,9,49,'Silloin Johannes rupesi puhumaan ja sanoi: "Mestari, me näimme erään miehen sinun nimessäsi ajavan ulos riivaajia, ja me kielsimme häntä, koska hän ei seuraa meidän mukanamme".'),
(1694290,58,42,9,50,'Mutta Jeesus sanoi hänelle: "Älkää kieltäkö; sillä joka ei ole teitä vastaan, se on teidän puolellanne".'),
(1694291,58,42,9,51,'Ja kun hänen ylösottamisensa aika oli täyttymässä, käänsi hän kasvonsa Jerusalemia kohti, vaeltaaksensa sinne.'),
(1694292,58,42,9,52,'Ja hän lähetti edellänsä sanansaattajia; ja he lähtivät matkalle ja menivät erääseen samarialaisten kylään valmistaakseen hänelle majaa.'),
(1694293,58,42,9,53,'Mutta siellä ei otettu häntä vastaan, koska hän oli vaeltamassa kohti Jerusalemia.'),
(1694294,58,42,9,54,'Kun hänen opetuslapsensa Jaakob ja Johannes sen näkivät, sanoivat he: "Herra, tahdotko, niin sanomme, että tuli taivaasta tulkoon alas ja hävittäköön heidät?"'),
(1694295,58,42,9,55,'Mutta hän kääntyi ja nuhteli heitä.'),
(1694296,58,42,9,56,'Ja he vaelsivat toiseen kylään.'),
(1694297,58,42,9,57,'Ja heidän tietä vaeltaessaan eräs mies sanoi hänelle: "Minä seuraan sinua, mihin ikinä menet".'),
(1694298,58,42,9,58,'Niin Jeesus sanoi hänelle: "Ketuilla on luolat ja taivaan linnuilla pesät, mutta Ihmisen Pojalla ei ole, mihin hän päänsä kallistaisi".'),
(1694299,58,42,9,59,'Toiselle hän sanoi: "Seuraa minua". Mutta tämä sanoi: "Herra, salli minun ensin käydä hautaamassa isäni".'),
(1694300,58,42,9,60,'Mutta Jeesus sanoi hänelle: "Anna kuolleitten haudata kuolleensa, mutta mene sinä ja julista Jumalan valtakuntaa".'),
(1694301,58,42,9,61,'Vielä eräs toinen sanoi: "Minä tahdon seurata sinua, Herra; mutta salli minun ensin käydä ottamassa jäähyväiset kotiväeltäni".'),
(1694302,58,42,9,62,'Mutta Jeesus sanoi hänelle: "Ei kukaan, joka laskee kätensä auraan ja katsoo taaksensa, ole sovelias Jumalan valtakuntaan".'),
(1694303,58,42,10,1,'Sen jälkeen Herra valitsi seitsemänkymmentä muuta ja lähetti heidät kaksittain edellänsä jokaiseen kaupunkiin ja paikkaan, jonne hän itse aikoi mennä.'),
(1694304,58,42,10,2,'Ja hän sanoi heille: "Eloa on paljon, mutta työmiehiä vähän. Rukoilkaa siis elon Herraa, että hän lähettäisi työmiehiä elonkorjuuseensa.'),
(1694305,58,42,10,3,'Menkää; katso, minä lähetän teidät niinkuin lampaat susien keskelle.'),
(1694306,58,42,10,4,'Älkää ottako mukaanne rahakukkaroa, älkää laukkua, älkää kenkiä, älkääkä tervehtikö ketään tiellä.'),
(1694307,58,42,10,5,'Kun tulette johonkin taloon, niin sanokaa ensiksi: ''Rauha tälle talolle!'''),
(1694308,58,42,10,6,'Ja jos siellä on rauhan lapsi, niin teidän rauhanne on lepäävä hänen päällänsä; mutta jos ei ole, niin se palajaa teille.'),
(1694309,58,42,10,7,'Ja olkaa siinä talossa ja syökää ja juokaa, mitä heillä on tarjota, sillä työmies on palkkansa ansainnut. Älkää siirtykö talosta taloon.'),
(1694310,58,42,10,8,'Ja mihin kaupunkiin te tulettekin, missä teidät otetaan vastaan, syökää, mitä eteenne pannaan,'),
(1694311,58,42,10,9,'ja parantakaa sairaat siellä ja sanokaa heille: ''Jumalan valtakunta on tullut teitä lähelle''.'),
(1694312,58,42,10,10,'Mutta kun tulette kaupunkiin, jossa teitä ei oteta vastaan, niin menkää sen kaduille ja sanokaa:'),
(1694313,58,42,10,11,'''Tomunkin, joka teidän kaupungistanne on jalkoihimme tarttunut, me pudistamme teille takaisin; mutta se tietäkää, että Jumalan valtakunta on tullut lähelle''.'),
(1694314,58,42,10,12,'Minä sanon teille: Sodoman on oleva sinä päivänä helpompi kuin sen kaupungin.'),
(1694315,58,42,10,13,'Voi sinua, Korasin! Voi sinua, Beetsaida! Sillä jos ne voimalliset teot, jotka teissä ovat tapahtuneet, olisivat tapahtuneet Tyyrossa ja Siidonissa, niin nämä jo aikaa sitten olisivat säkissä ja tuhassa istuen tehneet parannuksen.'),
(1694316,58,42,10,14,'Mutta Tyyron ja Siidonin on oleva tuomiolla helpompi kuin teidän.'),
(1694317,58,42,10,15,'Ja sinä, Kapernaum, korotetaankohan sinut hamaan taivaaseen? Hamaan tuonelaan on sinun astuttava alas.'),
(1694318,58,42,10,16,'Joka kuulee teitä, se kuulee minua, ja joka hylkää teidät, hylkää minut; mutta joka minut hylkää, hylkää hänet, joka on minut lähettänyt."'),
(1694319,58,42,10,17,'Niin ne seitsemänkymmentä palasivat iloiten ja sanoivat: "Herra, riivaajatkin ovat meille alamaiset sinun nimesi tähden".'),
(1694320,58,42,10,18,'Silloin hän sanoi heille: "Minä näin saatanan lankeavan taivaasta niinkuin salaman.'),
(1694321,58,42,10,19,'Katso, minä olen antanut teille vallan tallata käärmeitä ja skorpioneja ja kaikkea vihollisen voimaa, eikä mikään ole teitä vahingoittava.'),
(1694322,58,42,10,20,'Älkää kuitenkaan siitä iloitko, että henget ovat teille alamaiset, vaan iloitkaa siitä, että teidän nimenne ovat kirjoitettuina taivaissa."'),
(1694323,58,42,10,21,'Sillä hetkellä hän riemuitsi Pyhässä Hengessä ja sanoi: "Minä ylistän sinua, Isä, taivaan ja maan Herra, että olet salannut nämä viisailta ja ymmärtäväisiltä ja ilmoittanut ne lapsenmielisille. Niin, Isä, sillä näin on sinulle hyväksi näkynyt.'),
(1694324,58,42,10,22,'Kaikki on minun Isäni antanut minun haltuuni, eikä kukaan muu tunne, kuka Poika on, kuin Isä; eikä kukaan muu tunne, kuka Isä on, kuin Poika ja se, kenelle Poika tahtoo hänet ilmoittaa."'),
(1694325,58,42,10,23,'Ja hän kääntyi opetuslapsiinsa erikseen ja sanoi: "Autuaat ovat ne silmät, jotka näkevät, mitä te näette.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694326,58,42,10,24,'Sillä minä sanon teille: monet profeetat ja kuninkaat ovat tahtoneet nähdä, mitä te näette, eivätkä ole nähneet, ja kuulla, mitä te kuulette, eivätkä ole kuulleet."'),
(1694327,58,42,10,25,'Ja katso, eräs lainoppinut nousi ja kysyi kiusaten häntä: "Opettaja, mitä minun pitää tekemän, että minä iankaikkisen elämän perisin?"'),
(1694328,58,42,10,26,'Niin hän sanoi hänelle: "Mitä laissa on kirjoitettuna? Kuinkas luet?"'),
(1694329,58,42,10,27,'Hän vastasi ja sanoi: "Rakasta Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi ja kaikesta voimastasi ja kaikesta mielestäsi, ja lähimmäistäsi niinkuin itseäsi".'),
(1694330,58,42,10,28,'Hän sanoi hänelle: "Oikein vastasit; tee se, niin sinä saat elää".'),
(1694331,58,42,10,29,'Mutta hän tahtoi näyttää olevansa vanhurskas ja sanoi Jeesukselle: "Kuka sitten on minun lähimmäiseni?"'),
(1694332,58,42,10,30,'Jeesus vastasi ja sanoi: "Eräs mies vaelsi Jerusalemista alas Jerikoon ja joutui ryövärien käsiin, jotka riisuivat hänet alasti ja löivät haavoille ja menivät pois jättäen hänet puolikuolleeksi.'),
(1694333,58,42,10,31,'Niin vaelsi sattumalta eräs pappi sitä tietä ja näki hänet ja meni ohitse.'),
(1694334,58,42,10,32,'Samoin leeviläinenkin: kun hän tuli sille paikalle ja näki hänet, meni hän ohitse.'),
(1694335,58,42,10,33,'Mutta kun eräs samarialainen, joka matkusti sitä tietä, tuli hänen kohdalleen ja näki hänet, niin hän armahti häntä.'),
(1694336,58,42,10,34,'Ja hän meni hänen luokseen ja sitoi hänen haavansa ja vuodatti niihin öljyä ja viiniä, pani hänet juhtansa selkään ja vei hänet majataloon ja hoiti häntä.'),
(1694337,58,42,10,35,'Ja seuraavana aamuna hän otti esiin kaksi denaria ja antoi majatalon isännälle ja sanoi: ''Hoida häntä, ja mitä sinulta lisää kuluu, sen minä palatessani sinulle maksan''.'),
(1694338,58,42,10,36,'Kuka näistä kolmesta sinun mielestäsi osoitti olevansa sen lähimmäinen, joka oli joutunut ryövärien käsiin?"'),
(1694339,58,42,10,37,'Hän sanoi: "Se, joka osoitti hänelle laupeutta". Niin Jeesus sanoi hänelle: "Mene ja tee sinä samoin".'),
(1694340,58,42,10,38,'Ja heidän vaeltaessaan hän meni muutamaan kylään. Niin eräs nainen, nimeltä Martta, otti hänet kotiinsa.'),
(1694341,58,42,10,39,'Ja hänellä oli sisar, Maria niminen, joka asettui istumaan Herran jalkojen juureen ja kuunteli hänen puhettansa.'),
(1694342,58,42,10,40,'Mutta Martta puuhasi monissa palvelustoimissa; ja hän tuli ja sanoi: "Herra, etkö sinä välitä mitään siitä, että sisareni on jättänyt minut yksinäni palvelemaan? Sano siis hänelle, että hän minua auttaisi."'),
(1694343,58,42,10,41,'Herra vastasi ja sanoi hänelle: "Martta, Martta, moninaisista sinä huolehdit ja hätäilet,'),
(1694344,58,42,10,42,'mutta tarpeellisia on vähän, tahi yksi ainoa. Maria on valinnut hyvän osan, jota ei häneltä oteta pois."'),
(1694345,58,42,11,1,'Ja kun hän oli eräässä paikassa rukoilemassa ja oli lakannut, sanoi eräs hänen opetuslapsistansa hänelle: "Herra, opeta meitä rukoilemaan, niinkuin Johanneskin opetti opetuslapsiansa".'),
(1694346,58,42,11,2,'Niin hän sanoi heille: "Kun rukoilette, sanokaa: Isä, pyhitetty olkoon sinun nimesi; tulkoon sinun valtakuntasi; (tapahtukoon sinun tahtosi myös maan päällä niinkuin taivaassa;)'),
(1694347,58,42,11,3,'anna meille joka päivä meidän jokapäiväinen leipämme;'),
(1694348,58,42,11,4,'ja anna meille meidän syntimme anteeksi, sillä mekin annamme anteeksi jokaiselle velallisellemme; äläkä saata meitä kiusaukseen; (vaan päästä meidät pahasta)."'),
(1694349,58,42,11,5,'Ja hän sanoi heille: "Jos jollakin teistä on ystävä ja hän menee hänen luoksensa yösydännä ja sanoo hänelle: ''Ystäväni, lainaa minulle kolme leipää,'),
(1694350,58,42,11,6,'sillä eräs ystäväni on matkallaan tullut minun luokseni, eikä minulla ole, mitä panna hänen eteensä'';'),
(1694351,58,42,11,7,'ja toinen sisältä vastaa ja sanoo: ''Älä minua vaivaa; ovi on jo suljettu, ja lapseni ovat minun kanssani vuoteessa; en minä voi nousta antamaan sinulle'' -'),
(1694352,58,42,11,8,'minä sanon teille: vaikka hän ei nousekaan antamaan hänelle sentähden, että hän on hänen ystävänsä, nousee hän kuitenkin sentähden, että toinen ei hellitä, ja antaa hänelle niin paljon, kuin hän tarvitsee.'),
(1694353,58,42,11,9,'Niinpä minäkin sanon teille: anokaa, niin teille annetaan; etsikää, niin te löydätte; kolkuttakaa, niin teille avataan.'),
(1694354,58,42,11,10,'Sillä jokainen anova saa, ja etsivä löytää, ja kolkuttavalle avataan.'),
(1694355,58,42,11,11,'Ja kuka teistä on se isä, joka poikansa häneltä pyytäessä kalaa antaa hänelle kalan sijasta käärmeen,'),
(1694356,58,42,11,12,'taikka joka hänen pyytäessään munaa antaa hänelle skorpionin?'),
(1694357,58,42,11,13,'Jos siis te, jotka olette pahoja, osaatte antaa lapsillenne hyviä lahjoja, kuinka paljoa ennemmin taivaallinen Isä antaa Pyhän Hengen niille, jotka sitä häneltä anovat!"'),
(1694358,58,42,11,14,'Ja hän ajoi ulos riivaajan, ja se oli mykkä; ja kun riivaaja oli lähtenyt, niin tapahtui, että mykkä mies puhui; ja kansa ihmetteli.'),
(1694359,58,42,11,15,'Mutta muutamat heistä sanoivat: "Beelsebulin, riivaajain päämiehen, voimalla hän ajaa ulos riivaajia".'),
(1694360,58,42,11,16,'Toiset taas kiusasivat häntä ja pyysivät häneltä merkkiä taivaasta.'),
(1694361,58,42,11,17,'Mutta hän tiesi heidän ajatuksensa ja sanoi heille: "Jokainen valtakunta, joka riitautuu itsensä kanssa, joutuu autioksi, ja talo kaatuu talon päälle.'),
(1694362,58,42,11,18,'Jos nyt saatanakin on riitautunut itsensä kanssa, kuinka hänen valtakuntansa pysyy pystyssä? Tehän sanotte minun Beelsebulin voimalla ajavan ulos riivaajia.'),
(1694363,58,42,11,19,'Mutta jos minä Beelsebulin voimalla ajan ulos riivaajia, kenenkä voimalla sitten teidän lapsenne ajavat niitä ulos? Sentähden he tulevat olemaan teidän tuomarinne.'),
(1694364,58,42,11,20,'Mutta jos minä Jumalan sormella ajan ulos riivaajia, niin onhan Jumalan valtakunta tullut teidän tykönne.'),
(1694365,58,42,11,21,'Kun väkevä aseellisena vartioitsee kartanoaan, on hänen omaisuutensa turvassa.'),
(1694366,58,42,11,22,'Mutta kun häntä väkevämpi karkaa hänen päällensä ja voittaa hänet, ottaa hän häneltä kaikki aseet, joihin hän luotti, ja jakaa häneltä riistämänsä saaliin.'),
(1694367,58,42,11,23,'Joka ei ole minun kanssani, se on minua vastaan, ja joka ei minun kanssani kokoa, se hajottaa.'),
(1694368,58,42,11,24,'Kun saastainen henki lähtee ihmisestä, kuljeksii se autioita paikkoja ja etsii lepoa; ja kun ei löydä, sanoo se: ''Minä palaan huoneeseeni, josta lähdin''.'),
(1694369,58,42,11,25,'Ja kun se tulee, tapaa se sen lakaistuna ja kaunistettuna.'),
(1694370,58,42,11,26,'Silloin se menee ja ottaa mukaansa seitsemän muuta henkeä, pahempaa kuin se itse, ja ne tulevat sisään ja asuvat siellä. Ja sen ihmisen viimeiset tulevat pahemmiksi kuin ensimmäiset."'),
(1694371,58,42,11,27,'Niin hänen tätä puhuessaan eräs nainen kansanjoukosta korotti äänensä ja sanoi hänelle: "Autuas on se kohtu, joka on kantanut sinut, ja ne rinnat, joita olet imenyt".'),
(1694372,58,42,11,28,'Mutta hän sanoi: "Niin, autuaat ovat ne, jotka kuulevat Jumalan sanan ja sitä noudattavat".'),
(1694373,58,42,11,29,'Kun kansaa yhä kokoontui, rupesi hän puhumaan: "Tämä sukupolvi on paha sukupolvi: se tavoittelee merkkiä, mutta sille ei anneta muuta merkkiä kuin Joonaan merkki.'),
(1694374,58,42,11,30,'Sillä niinkuin Joonas tuli niiniveläisille merkiksi, niin Ihmisen Poikakin on oleva merkkinä tälle sukupolvelle.'),
(1694375,58,42,11,31,'Etelän kuningatar on heräjävä tuomiolle yhdessä tämän sukupolven miesten kanssa ja tuleva heille tuomioksi; sillä hän tuli maan ääristä kuulemaan Salomon viisautta, ja katso, tässä on enempi kuin Salomo.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694376,58,42,11,32,'Niiniven miehet nousevat tuomiolle yhdessä tämän sukupolven kanssa ja tulevat sille tuomioksi; sillä he tekivät parannuksen Joonaan saarnan vaikutuksesta, ja katso, tässä on enempi kuin Joonas.'),
(1694377,58,42,11,33,'Ei kukaan, joka sytyttää lampun, pane sitä kätköön eikä vakan alle, vaan panee sen lampunjalkaan, että sisälletulijat näkisivät valon.'),
(1694378,58,42,11,34,'Sinun silmäsi on ruumiin lamppu. Kun silmäsi on terve, on koko sinun ruumiisi valaistu, mutta kun se on viallinen, on myös sinun ruumiisi pimeä.'),
(1694379,58,42,11,35,'Katso siis, ettei valo, joka sinussa on, ole pimeyttä.'),
(1694380,58,42,11,36,'Jos siis koko sinun ruumiisi on valoisa eikä miltään osaltaan pimeä, on se oleva kokonaan valoisa, niinkuin lampun valaistessa sinua kirkkaalla loisteellaan."'),
(1694381,58,42,11,37,'Hänen näin puhuessaan pyysi eräs fariseus häntä luoksensa aterioimaan; niin hän meni sinne ja asettui aterialle.'),
(1694382,58,42,11,38,'Mutta kun fariseus näki, ettei hän peseytynyt ennen ateriaa, ihmetteli hän.'),
(1694383,58,42,11,39,'Silloin Herra sanoi hänelle: "Kyllä te, fariseukset, puhdistatte maljan ja vadin ulkopuolen, mutta sisäpuoli teissä on täynnä ryöstöä ja pahuutta.'),
(1694384,58,42,11,40,'Te mielettömät, eikö se, joka on tehnyt ulkopuolen, ole tehnyt sisäpuoltakin?'),
(1694385,58,42,11,41,'Mutta antakaa almuksi se, mikä sisällä on; katso, silloin kaikki on teille puhdasta.'),
(1694386,58,42,11,42,'Mutta voi teitä, te fariseukset, kun te annatte kymmenykset mintuista ja ruuduista ja kaikenlaisista vihanneksista, mutta sivuutatte oikeuden ja Jumalan rakkauden! Näitä olisi tullut noudattaa eikä noitakaan laiminlyödä.'),
(1694387,58,42,11,43,'Voi teitä, te fariseukset, kun te rakastatte etumaista istuinta synagoogissa ja tervehdyksiä toreilla!'),
(1694388,58,42,11,44,'Voi teitä, kun te olette niinkuin merkittömät haudat, joiden päällitse ihmiset kävelevät niistä tietämättä!"'),
(1694389,58,42,11,45,'Silloin eräs lainoppineista rupesi puhumaan ja sanoi hänelle: "Opettaja, kun noin puhut, niin sinä häpäiset myös meitä".'),
(1694390,58,42,11,46,'Mutta hän sanoi: "Voi teitäkin, te lainoppineet, kun te sälytätte ihmisten päälle vaikeasti kannettavia taakkoja ettekä itse sormellannekaan koske niihin taakkoihin!'),
(1694391,58,42,11,47,'Voi teitä, kun te rakennatte profeettain hautakammioita, ja teidän isänne ovat heidät tappaneet!'),
(1694392,58,42,11,48,'Näin te siis olette isäinne tekojen todistajia ja suostutte niihin: sillä he tappoivat profeetat, ja te rakennatte niille hautakammioita.'),
(1694393,58,42,11,49,'Sentähden Jumalan viisaus sanookin: ''Minä lähetän heille profeettoja ja apostoleja, ja muutamat niistä he tappavat ja toisia vainoavat,'),
(1694394,58,42,11,50,'että tältä sukukunnalta vaadittaisiin kaikkien profeettain veri, mikä on vuodatettu maailman perustamisesta asti,'),
(1694395,58,42,11,51,'hamasta Aabelin verestä Sakariaan vereen saakka, hänen, joka surmattiin alttarin ja temppelin välillä''. Niin, minä sanon teille, se pitää tältä sukukunnalta vaadittaman.'),
(1694396,58,42,11,52,'Voi teitä, te lainoppineet, kun te olette vieneet tiedon avaimen! Itse te ette ole menneet sisälle, ja sisälle meneviä te olette estäneet."'),
(1694397,58,42,11,53,'Ja hänen sieltä lähtiessään kirjanoppineet ja fariseukset rupesivat kovasti ahdistamaan häntä ja urkkimaan häneltä moninaisia,'),
(1694398,58,42,11,54,'väijyen, miten saisivat hänet hänen sanoistaan ansaan.'),
(1694399,58,42,12,1,'Kun sillä välin kansaa oli kokoontunut tuhatmäärin, niin että he polkivat toisiaan, rupesi hän puhumaan opetuslapsillensa: "Ennen kaikkea kavahtakaa fariseusten hapatusta, se on: ulkokultaisuutta.'),
(1694400,58,42,12,2,'Ei ole mitään peitettyä, mikä ei tule paljastetuksi, eikä mitään salattua, mikä ei tule tunnetuksi.'),
(1694401,58,42,12,3,'Sentähden, kaikki, mitä te pimeässä sanotte, joutuu päivänvalossa kuultavaksi, ja mitä korvaan puhutte kammioissa, se katoilta julistetaan.'),
(1694402,58,42,12,4,'Mutta minä sanon teille, ystävilleni: älkää peljätkö niitä, jotka tappavat ruumiin, eivätkä sen jälkeen voi mitään enempää tehdä.'),
(1694403,58,42,12,5,'Vaan minä osoitan teille, ketä teidän on pelkääminen: peljätkää häntä, jolla on valta tapettuansa syöstä helvettiin. Niin, minä sanon teille, häntä te peljätkää.'),
(1694404,58,42,12,6,'Eikö viittä varpusta myydä kahteen ropoon? Eikä Jumala ole yhtäkään niistä unhottanut.'),
(1694405,58,42,12,7,'Ovatpa teidän päänne hiuksetkin kaikki luetut. Älkää peljätkö; te olette suurempiarvoiset kuin monta varpusta.'),
(1694406,58,42,12,8,'Mutta minä sanon teille: jokaisen, joka tunnustaa minut ihmisten edessä, myös Ihmisen Poika tunnustaa Jumalan enkelien edessä.'),
(1694407,58,42,12,9,'Mutta joka kieltää minut ihmisten edessä, se kielletään Jumalan enkelien edessä.'),
(1694408,58,42,12,10,'Ja jokaiselle, joka sanoo sanan Ihmisen Poikaa vastaan, annetaan anteeksi; mutta sille, joka Pyhää Henkeä pilkkaa, ei anteeksi anneta.'),
(1694409,58,42,12,11,'Mutta kun he vievät teitä synagoogain ja hallitusten ja esivaltojen eteen, älkää huolehtiko siitä, miten tai mitä vastaisitte puolestanne tahi mitä sanoisitte;'),
(1694410,58,42,12,12,'sillä Pyhä Henki opettaa teille sillä hetkellä, mitä teidän on sanottava."'),
(1694411,58,42,12,13,'Niin muuan mies kansanjoukosta sanoi hänelle: "Opettaja, sano minun veljelleni, että hän jakaisi kanssani perinnön".'),
(1694412,58,42,12,14,'Mutta hän vastasi hänelle: "Ihminen, kuka on minut asettanut teille tuomariksi tai jakomieheksi?"'),
(1694413,58,42,12,15,'Ja hän sanoi heille: "Katsokaa eteenne ja kavahtakaa kaikkea ahneutta, sillä ei ihmisen elämä riipu hänen omaisuudestaan, vaikka sitä ylenpalttisesti olisi".'),
(1694414,58,42,12,16,'Ja hän puhui heille vertauksen sanoen: "Rikkaan miehen maa kasvoi hyvin.'),
(1694415,58,42,12,17,'Niin hän mietti mielessään ja sanoi: ''Mitä minä teen, kun ei minulla ole, mihin viljani kokoaisin?'''),
(1694416,58,42,12,18,'Ja hän sanoi: ''Tämän minä teen: minä revin maahan aittani ja rakennan suuremmat ja kokoan niihin kaiken eloni ja hyvyyteni;'),
(1694417,58,42,12,19,'ja sanon sielulleni: sielu, sinulla on paljon hyvää tallessa moneksi vuodeksi; nauti lepoa, syö, juo ja iloitse''.'),
(1694418,58,42,12,20,'Mutta Jumala sanoi hänelle: ''Sinä mieletön, tänä yönä sinun sielusi vaaditaan sinulta pois; kenelle sitten joutuu se, minkä sinä olet hankkinut?'''),
(1694419,58,42,12,21,'Näin käy sen, joka kokoaa aarteita itselleen, mutta jolla ei ole rikkautta Jumalan tykönä."'),
(1694420,58,42,12,22,'Ja hän sanoi opetuslapsillensa: "Sentähden minä sanon teille: älkää murehtiko hengestänne, mitä söisitte, älkääkä ruumiistanne, mitä päällenne pukisitte.'),
(1694421,58,42,12,23,'Sillä henki on enemmän kuin ruoka, ja ruumis enemmän kuin vaatteet.'),
(1694422,58,42,12,24,'Katselkaa kaarneita: eivät ne kylvä eivätkä leikkaa, eikä niillä ole säilytyshuonetta eikä aittaa; ja Jumala ruokkii ne. Kuinka paljoa suurempiarvoiset te olette kuin linnut!'),
(1694423,58,42,12,25,'Ja kuka teistä voi murehtimisellaan lisätä ikäänsä kyynäränkään vertaa?'),
(1694424,58,42,12,26,'Jos siis ette voi sitäkään, mikä vähintä on, mitä te murehditte muusta?'),
(1694425,58,42,12,27,'Katselkaa kukkia, kuinka ne kasvavat: eivät ne työtä tee eivätkä kehrää. Kuitenkin minä sanon teille: ei Salomo kaikessa loistossansa ollut niin vaatetettu kuin yksi niistä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694426,58,42,12,28,'Jos siis Jumala näin vaatettaa kedon ruohon, joka tänään kasvaa ja huomenna uuniin heitetään, kuinka paljoa ennemmin teidät, te vähäuskoiset!'),
(1694427,58,42,12,29,'Älkää siis tekään etsikö, mitä söisitte ja mitä joisitte, älkääkä korkeita tavoitelko.'),
(1694428,58,42,12,30,'Sillä näitä kaikkia maailman pakanakansat tavoittelevat; mutta teidän Isänne kyllä tietää teidän näitä tarvitsevan.'),
(1694429,58,42,12,31,'Vaan etsikää Jumalan valtakuntaa, niin myös nämä teille annetaan sen ohessa.'),
(1694430,58,42,12,32,'Älä pelkää, sinä piskuinen lauma; sillä teidän Isänne on nähnyt hyväksi antaa teille valtakunnan.'),
(1694431,58,42,12,33,'Myykää, mitä teillä on, ja antakaa almuja; hankkikaa itsellenne kulumattomat kukkarot, loppumaton aarre taivaisiin, mihin ei varas ulotu ja missä koi ei turmele.'),
(1694432,58,42,12,34,'Sillä missä teidän aarteenne on, siellä on myös teidän sydämenne.'),
(1694433,58,42,12,35,'Olkoot teidän kupeenne vyötetyt ja lamppunne palamassa;'),
(1694434,58,42,12,36,'ja olkaa te niiden ihmisten kaltaiset, jotka herraansa odottavat, milloin hän palajaa häistä, että he hänen tullessaan ja kolkuttaessaan heti avaisivat hänelle.'),
(1694435,58,42,12,37,'Autuaat ne palvelijat, jotka heidän herransa tullessaan tapaa valvomasta! Totisesti minä sanon teille: hän vyöttäytyy ja asettaa heidät aterioimaan ja menee ja palvelee heitä.'),
(1694436,58,42,12,38,'Ja jos hän tulee toisella yövartiolla tai kolmannella ja havaitsee heidän näin tekevän, niin autuaat ovat ne palvelijat.'),
(1694437,58,42,12,39,'Mutta se tietäkää: jos perheenisäntä tietäisi, millä hetkellä varas tulee, hän ei sallisi taloonsa murtauduttavan.'),
(1694438,58,42,12,40,'Niin olkaa tekin valmiit, sillä sinä hetkenä, jona ette luule, Ihmisen Poika tulee."'),
(1694439,58,42,12,41,'Niin Pietari sanoi: "Herra, meistäkö sinä sanot tämän vertauksen vai myös kaikista muista?"'),
(1694440,58,42,12,42,'Ja Herra sanoi: "Kuka siis on se uskollinen ja ymmärtäväinen huoneenhaltija, jonka hänen herransa asettaa pitämään huolta hänen palvelusväestään, antamaan heille ajallaan heidän ruokaosansa?'),
(1694441,58,42,12,43,'Autuas se palvelija, jonka hänen herransa tullessaan havaitsee näin tekevän!'),
(1694442,58,42,12,44,'Totisesti minä sanon teille: hän asettaa hänet kaiken omaisuutensa hoitajaksi.'),
(1694443,58,42,12,45,'Mutta jos palvelija sanoo sydämessään: ''Herrani tulo viivästyy'', ja rupeaa lyömään palvelijoita ja palvelijattaria sekä syömään ja juomaan ja päihdyttämään itseänsä,'),
(1694444,58,42,12,46,'niin sen palvelijan herra tulee päivänä, jona hän ei odota, ja hetkenä, jota hän ei arvaa, ja hakkaa hänet kappaleiksi ja määrää hänelle saman osan kuin uskottomille.'),
(1694445,58,42,12,47,'Ja sitä palvelijaa, joka tiesi herransa tahdon, mutta ei tehnyt valmistuksia eikä toiminut hänen tahtonsa mukaan, rangaistaan monilla lyönneillä.'),
(1694446,58,42,12,48,'Sitä taas, joka ei tiennyt, mutta teki semmoista, mikä lyöntejä ansaitsee, rangaistaan vain muutamilla lyönneillä. Sillä jokaiselta, jolle on paljon annettu, myös paljon vaaditaan; ja jolle on paljon uskottu, siltä sitä enemmän kysytään.'),
(1694447,58,42,12,49,'Tulta minä olen tullut heittämään maan päälle; ja kuinka minä tahtoisinkaan, että se jo olisi syttynyt!'),
(1694448,58,42,12,50,'Mutta minä olen kasteella kastettava, ja kuinka minä olenkaan ahdistettu, kunnes se on täytetty!'),
(1694449,58,42,12,51,'Luuletteko, että minä olen tullut tuomaan maan päälle rauhaa? Ei, sanon minä teille, vaan eripuraisuutta.'),
(1694450,58,42,12,52,'Sillä tästedes riitautuu viisi samassa talossa keskenään, kolme joutuu riitaan kahta vastaan ja kaksi kolmea vastaan,'),
(1694451,58,42,12,53,'isä poikaansa vastaan ja poika isäänsä vastaan, äiti tytärtänsä vastaan ja tytär äitiänsä vastaan, anoppi miniäänsä vastaan ja miniä anoppiansa vastaan."'),
(1694452,58,42,12,54,'Ja hän sanoi myöskin kansalle: "Kun näette pilven nousevan lännestä, sanotte kohta: ''Tulee sade''; ja niin tuleekin.'),
(1694453,58,42,12,55,'Ja kun näette etelätuulen puhaltavan, sanotte: ''Tulee helle''; ja niin tuleekin.'),
(1694454,58,42,12,56,'Te ulkokullatut, maan ja taivaan muodon te osaatte arvioida; mutta kuinka ette arvioitse tätä aikaa?'),
(1694455,58,42,12,57,'Miksi ette jo itsestänne päätä, mikä oikeata on?'),
(1694456,58,42,12,58,'Kun kuljet riitapuolesi kanssa hallitusmiehen eteen, niin tee matkalla voitavasi päästäksesi hänestä sovussa eroon, ettei hän raastaisi sinua tuomarin eteen ja tuomari antaisi sinua oikeudenpalvelijalle, ja ettei oikeudenpalvelija heittäisi sinua vankeuteen.'),
(1694457,58,42,12,59,'Minä sanon sinulle: sieltä et pääse, ennenkuin maksat viimeisenkin rovon."'),
(1694458,58,42,13,1,'Samaan aikaan oli saapuvilla muutamia, jotka kertoivat hänelle niistä galilealaisista, joiden veren Pilatus oli sekoittanut heidän uhriensa vereen.'),
(1694459,58,42,13,2,'Niin Jeesus vastasi ja sanoi heille: "Luuletteko, että nämä galilealaiset olivat syntisemmät kuin kaikki muut galilealaiset, koska he saivat kärsiä tämän?'),
(1694460,58,42,13,3,'Eivät olleet, sanon minä teille, mutta ellette tee parannusta, niin samoin te kaikki hukutte.'),
(1694461,58,42,13,4,'Taikka ne kahdeksantoista, jotka saivat surmansa, kun torni Siloassa kaatui heidän päällensä, luuletteko, että he olivat syyllisemmät kuin kaikki muut ihmiset, jotka Jerusalemissa asuvat?'),
(1694462,58,42,13,5,'Eivät olleet, sanon minä teille, mutta ellette tee parannusta, niin samoin te kaikki hukutte."'),
(1694463,58,42,13,6,'Ja hän puhui tämän vertauksen: "Eräällä miehellä oli viikunapuu istutettuna viinitarhassaan; ja hän tuli etsimään hedelmää siitä, mutta ei löytänyt.'),
(1694464,58,42,13,7,'Niin hän sanoi viinitarhurille: ''Katso, kolmena vuotena minä olen käynyt etsimässä hedelmää tästä viikunapuusta, mutta en ole löytänyt. Hakkaa se pois; mitä varten se vielä maata laihduttaa?'''),
(1694465,58,42,13,8,'Mutta tämä vastasi ja sanoi hänelle: ''Herra, anna sen olla vielä tämä vuosi; sillä aikaa minä kuokin ja lannoitan maan sen ympäriltä.'),
(1694466,58,42,13,9,'Ehkä se ensi vuonna tekee hedelmää; mutta jos ei, niin hakkaa se pois''."'),
(1694467,58,42,13,10,'Ja hän oli opettamassa eräässä synagoogassa sapattina.'),
(1694468,58,42,13,11,'Ja katso, siellä oli nainen, jossa oli ollut heikkouden henki kahdeksantoista vuotta, ja hän oli koukistunut ja täydelleen kykenemätön oikaisemaan itseänsä.'),
(1694469,58,42,13,12,'Hänet nähdessään Jeesus kutsui hänet luoksensa ja sanoi hänelle: "Nainen, sinä olet päässyt heikkoudestasi",'),
(1694470,58,42,13,13,'ja pani kätensä hänen päälleen. Ja heti hän oikaisi itsensä suoraksi ja ylisti Jumalaa.'),
(1694471,58,42,13,14,'Mutta synagoogan esimies, joka närkästyi siitä, että Jeesus paransi sapattina, rupesi puhumaan ja sanoi kansalle: "Kuusi päivää on, joina tulee työtä tehdä; tulkaa siis niinä päivinä parannuttamaan itseänne, älkääkä sapatinpäivänä".'),
(1694472,58,42,13,15,'Mutta Herra vastasi hänelle ja sanoi: "Te ulkokullatut, eikö jokainen teistä sapattina päästä härkäänsä tai aasiansa seimestä ja vie sitä juomaan?'),
(1694473,58,42,13,16,'Ja tätä naista, joka on Aabrahamin tytär ja jota saatana on pitänyt sidottuna, katso, jo kahdeksantoista vuotta, tätäkö ei olisi pitänyt päästää siitä siteestä sapatinpäivänä?"'),
(1694474,58,42,13,17,'Ja hänen näin sanoessaan kaikki hänen vastustajansa häpesivät, ja kaikki kansa iloitsi kaikista niistä ihmeellisistä teoista, joita hän teki.'),
(1694475,58,42,13,18,'Niin hän sanoi: "Minkä kaltainen on Jumalan valtakunta, ja mihin minä sen vertaisin?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694476,58,42,13,19,'Se on sinapinsiemenen kaltainen, jonka mies otti ja kylvi puutarhaansa; ja se kasvoi, ja siitä tuli puu, ja taivaan linnut tekivät pesänsä sen oksille."'),
(1694477,58,42,13,20,'Ja taas hän sanoi: "Mihin minä vertaisin Jumalan valtakunnan?'),
(1694478,58,42,13,21,'Se on hapatuksen kaltainen, jonka nainen otti ja sekoitti kolmeen vakalliseen jauhoja, kunnes kaikki happani."'),
(1694479,58,42,13,22,'Ja hän vaelsi kaupungista kaupunkiin ja kylästä kylään ja opetti, kulkien Jerusalemia kohti.'),
(1694480,58,42,13,23,'Ja joku kysyi häneltä: "Herra, onko niitä vähän, jotka pelastuvat? Niin hän sanoi heille:'),
(1694481,58,42,13,24,'"Kilvoitelkaa päästäksenne sisälle ahtaasta ovesta, sillä monet, sanon minä teille, koettavat päästä sisälle, mutta eivät voi.'),
(1694482,58,42,13,25,'Sen jälkeen kuin perheenisäntä on noussut ja sulkenut oven ja te rupeatte seisomaan ulkona ja kolkuttamaan ovea sanoen: ''Herra, avaa meille'', vastaa hän ja sanoo teille: ''En minä tunne teitä enkä tiedä, mistä te olette''.'),
(1694483,58,42,13,26,'Silloin te rupeatte sanomaan: ''Mehän söimme ja joimme sinun seurassasi, ja meidän kaduillamme sinä opetit''.'),
(1694484,58,42,13,27,'Mutta hän on lausuva: ''Minä sanon teille: en tiedä, mistä te olette. Menkää pois minun tyköäni, kaikki te vääryyden tekijät.'''),
(1694485,58,42,13,28,'Siellä on oleva itku ja hammasten kiristys, kun näette Aabrahamin ja Iisakin ja Jaakobin ja kaikkien profeettain olevan Jumalan valtakunnassa, mutta huomaatte itsenne heitetyiksi ulos.'),
(1694486,58,42,13,29,'Ja tulijoita saapuu idästä ja lännestä ja pohjoisesta ja etelästä, ja he aterioitsevat Jumalan valtakunnassa.'),
(1694487,58,42,13,30,'Ja katso, on viimeisiä, jotka tulevat ensimmäisiksi, ja on ensimmäisiä, jotka tulevat viimeisiksi."'),
(1694488,58,42,13,31,'Samalla hetkellä tuli hänen luoksensa muutamia fariseuksia, ja he sanoivat hänelle: "Lähde ja mene täältä pois, sillä Herodes tahtoo tappaa sinut".'),
(1694489,58,42,13,32,'Niin hän sanoi heille: "Menkää ja sanokaa sille ketulle: ''Katso, minä ajan ulos riivaajia ja parannan sairaita tänään ja huomenna, ja kolmantena päivänä minä pääsen määräni päähän''.'),
(1694490,58,42,13,33,'Kuitenkin minun pitää vaeltaman tänään ja huomenna ja ylihuomenna, sillä ei sovi, että profeetta saa surmansa muualla kuin Jerusalemissa.'),
(1694491,58,42,13,34,'Jerusalem, Jerusalem, sinä, joka tapat profeetat ja kivität ne, jotka ovat sinun tykösi lähetetyt, kuinka usein minä olenkaan tahtonut koota sinun lapsesi, niinkuin kana kokoaa poikansa siipiensä alle! Mutta te ette ole tahtoneet.'),
(1694492,58,42,13,35,'Katso, ''teidän huoneenne on jäävä hyljätyksi''. Mutta minä sanon teille: te ette näe minua, ennenkuin se aika tulee, jolloin te sanotte: ''Siunattu olkoon hän, joka tulee Herran nimeen''."'),
(1694493,58,42,14,1,'Ja kun hän sapattina tuli erään fariseusten johtomiehen taloon aterialle, pitivät he häntä silmällä.'),
(1694494,58,42,14,2,'Ja katso, siellä oli vesitautinen mies hänen edessään.'),
(1694495,58,42,14,3,'Niin Jeesus rupesi puhumaan lainoppineille ja fariseuksille ja sanoi: "Onko luvallista parantaa sapattina, vai eikö?" Mutta he olivat vaiti.'),
(1694496,58,42,14,4,'Ja hän koski mieheen, paransi hänet ja laski menemään.'),
(1694497,58,42,14,5,'Ja hän sanoi heille: "Jos joltakin teistä putoaa poika tai härkä kaivoon, eikö hän heti vedä sitä ylös sapatinpäivänäkin?"'),
(1694498,58,42,14,6,'Eivätkä he kyenneet vastaamaan tähän.'),
(1694499,58,42,14,7,'Ja huomatessaan, kuinka kutsutut valitsivat itselleen ensimmäisiä sijoja, hän puhui heille vertauksen ja sanoi heille:'),
(1694500,58,42,14,8,'"Kun joku on kutsunut sinut häihin, älä asetu aterioimaan ensimmäiselle sijalle; sillä, jos hän on kutsunut jonkun sinua arvollisemman,'),
(1694501,58,42,14,9,'niin hän, joka on sinut ja hänet kutsunut, ehkä tulee ja sanoo sinulle: ''Anna tälle sija'', ja silloin sinä saat häveten siirtyä viimeiselle paikalle.'),
(1694502,58,42,14,10,'Vaan kun olet kutsuttu, mene ja asetu viimeiselle sijalle, ja niin on se, joka on sinut kutsunut, sisään tullessaan sanova sinulle: ''Ystäväni, astu ylemmäksi''. Silloin tulee sinulle kunnia kaikkien pöytäkumppaniesi edessä.'),
(1694503,58,42,14,11,'Sillä jokainen, joka itsensä ylentää, alennetaan, ja joka itsensä alentaa, se ylennetään."'),
(1694504,58,42,14,12,'Ja hän sanoi myös sille, joka oli hänet kutsunut: "Kun laitat päivälliset tai illalliset, älä kutsu ystäviäsi, älä veljiäsi, älä sukulaisiasi äläkä rikkaita naapureita, etteivät hekin vuorostaan kutsuisi sinua, ja ettet sinä siten saisi maksua.'),
(1694505,58,42,14,13,'Vaan kun laitat pidot, kutsu köyhiä, raajarikkoja, rampoja, sokeita;'),
(1694506,58,42,14,14,'niin sinä olet oleva autuas, koska he eivät voi maksaa sinulle; sillä sinulle maksetaan vanhurskasten ylösnousemuksessa."'),
(1694507,58,42,14,15,'Tämän kuullessaan eräs pöytäkumppaneista sanoi hänelle: "Autuas se, joka saa olla aterialla Jumalan valtakunnassa!"'),
(1694508,58,42,14,16,'Niin hän sanoi hänelle: "Eräs mies laittoi suuret illalliset ja kutsui monta.'),
(1694509,58,42,14,17,'Ja illallisajan tullessa hän lähetti palvelijansa sanomaan kutsutuille: ''Tulkaa, sillä kaikki on jo valmiina''.'),
(1694510,58,42,14,18,'Mutta he rupesivat kaikki järjestään estelemään. Ensimmäinen sanoi hänelle: ''Minä ostin pellon, ja minun täytyy lähteä sitä katsomaan; pyydän sinua, pidä minut estettynä''.'),
(1694511,58,42,14,19,'Toinen sanoi: ''Minä ostin viisi paria härkiä ja menen niitä koettelemaan; pyydän sinua, pidä minut estettynä''.'),
(1694512,58,42,14,20,'Vielä toinen sanoi: ''Minä otin vaimon, ja sentähden en voi tulla''.'),
(1694513,58,42,14,21,'Ja palvelija tuli takaisin ja ilmoitti herralleen tämän. Silloin isäntä vihastui ja sanoi palvelijalleen: ''Mene kiiruusti kaupungin kaduille ja kujille ja tuo köyhät ja raajarikot, sokeat ja rammat tänne sisälle''.'),
(1694514,58,42,14,22,'Ja palvelija sanoi: ''Herra, on tehty, minkä käskit, ja vielä on tilaa''.'),
(1694515,58,42,14,23,'Niin Herra sanoi palvelijalle: ''Mene teille ja aitovierille ja pakota heitä tulemaan sisälle, että minun taloni täyttyisi;'),
(1694516,58,42,14,24,'sillä minä sanon teille, ettei yksikään niistä miehistä, jotka olivat kutsutut, ole maistava minun illallisiani''."'),
(1694517,58,42,14,25,'Ja hänen mukanaan kulki paljon kansaa; ja hän kääntyi ja sanoi heille:'),
(1694518,58,42,14,26,'"Jos joku tulee minun tyköni eikä vihaa isäänsä ja äitiänsä ja vaimoaan ja lapsiaan ja veljiään ja sisariaan, vieläpä omaa elämäänsäkin, hän ei voi olla minun opetuslapseni.'),
(1694519,58,42,14,27,'Ja joka ei kanna ristiänsä ja seuraa minua, se ei voi olla minun opetuslapseni.'),
(1694520,58,42,14,28,'Sillä jos joku teistä tahtoo rakentaa tornin, eikö hän ensin istu laskemaan kustannuksia, nähdäkseen, onko hänellä varoja rakentaa se valmiiksi,'),
(1694521,58,42,14,29,'etteivät, kun hän on pannut perustuksen, mutta ei kykene saamaan rakennusta valmiiksi, kaikki, jotka sen näkevät, rupeaisi pilkkaamaan häntä'),
(1694522,58,42,14,30,'sanoen: ''Tuo mies ryhtyi rakentamaan, mutta ei kyennyt saamaan valmiiksi''?'),
(1694523,58,42,14,31,'Tahi jos joku kuningas tahtoo lähteä sotimaan toista kuningasta vastaan, eikö hän ensin istu ja pidä neuvoa, kykeneekö hän kymmenellä tuhannella kohtaamaan sitä, joka tulee häntä vastaan kahdellakymmenellä tuhannella?'),
(1694524,58,42,14,32,'Ja ellei kykene, niin hän, toisen vielä ollessa kaukana, lähettää hänen luoksensa lähettiläät hieromaan rauhaa.'),
(1694525,58,42,14,33,'Niin ei myös teistä yksikään, joka ei luovu kaikesta, mitä hänellä on, voi olla minun opetuslapseni.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694526,58,42,14,34,'Suola on hyvä; mutta jos suolakin käy mauttomaksi, millä se saadaan suolaiseksi?'),
(1694527,58,42,14,35,'Ei se kelpaa maahan eikä lantaan; se heitetään pois. Jolla on korvat kuulla, se kuulkoon!"'),
(1694528,58,42,15,1,'Ja kaikki publikaanit ja syntiset tulivat hänen tykönsä kuulemaan häntä.'),
(1694529,58,42,15,2,'Mutta fariseukset ja kirjanoppineet nurisivat ja sanoivat: "Tämä ottaa vastaan syntisiä ja syö heidän kanssaan".'),
(1694530,58,42,15,3,'Niin hän puhui heille tämän vertauksen sanoen:'),
(1694531,58,42,15,4,'"Jos jollakin teistä on sata lammasta ja hän kadottaa yhden niistä, eikö hän jätä niitä yhdeksääkymmentä yhdeksää erämaahan ja mene etsimään kadonnutta, kunnes hän sen löytää?'),
(1694532,58,42,15,5,'Ja löydettyään hän panee sen hartioillensa iloiten.'),
(1694533,58,42,15,6,'Ja kun hän tulee kotiin, kutsuu hän kokoon ystävänsä ja naapurinsa ja sanoo heille: ''Iloitkaa minun kanssani, sillä minä löysin lampaani, joka oli kadonnut''.'),
(1694534,58,42,15,7,'Minä sanon teille: samoin on ilo taivaassa suurempi yhdestä syntisestä, joka tekee parannuksen, kuin yhdeksästäkymmenestä yhdeksästä vanhurskaasta, jotka eivät parannusta tarvitse.'),
(1694535,58,42,15,8,'Tahi jos jollakin naisella on kymmenen hopearahaa ja hän kadottaa yhden niistä, eikö hän sytytä lamppua ja lakaise huonetta ja etsi visusti, kunnes hän sen löytää?'),
(1694536,58,42,15,9,'Ja löydettyään hän kutsuu kokoon ystävättärensä ja naapurinaiset ja sanoo: ''Iloitkaa minun kanssani, sillä minä löysin rahan, jonka olin kadottanut''.'),
(1694537,58,42,15,10,'Niin myös, sanon minä teille, on ilo Jumalan enkeleillä yhdestä syntisestä, joka tekee parannuksen."'),
(1694538,58,42,15,11,'Vielä hän sanoi: "Eräällä miehellä oli kaksi poikaa.'),
(1694539,58,42,15,12,'Ja nuorempi heistä sanoi isälleen: ''Isä, anna minulle se osa tavaroista, mikä minulle on tuleva''. Niin hän jakoi heille omaisuutensa.'),
(1694540,58,42,15,13,'Eikä kulunut montakaan päivää, niin nuorempi poika kokosi kaiken omansa ja matkusti pois kaukaiseen maahan; ja siellä hän hävitti tavaransa eläen irstaasti.'),
(1694541,58,42,15,14,'Mutta kun hän oli kaikki tuhlannut, tuli kova nälkä koko siihen maahan, ja hän alkoi kärsiä puutetta.'),
(1694542,58,42,15,15,'Ja hän meni ja yhtyi erääseen sen maan kansalaiseen, ja tämä lähetti hänet tiluksilleen kaitsemaan sikoja.'),
(1694543,58,42,15,16,'Ja hän halusi täyttää vatsansa niillä palkohedelmillä, joita siat söivät, mutta niitäkään ei kukaan hänelle antanut.'),
(1694544,58,42,15,17,'Niin hän meni itseensä ja sanoi: ''Kuinka monella minun isäni palkkalaisella on yltäkyllin leipää, mutta minä kuolen täällä nälkään!'),
(1694545,58,42,15,18,'Minä nousen ja menen isäni tykö ja sanon hänelle: Isä, minä olen tehnyt syntiä taivasta vastaan ja sinun edessäsi'),
(1694546,58,42,15,19,'enkä enää ansaitse, että minua sinun pojaksesi kutsutaan; tee minut yhdeksi palkkalaisistasi.'''),
(1694547,58,42,15,20,'Ja hän nousi ja meni isänsä tykö. Mutta kun hän vielä oli kaukana, näki hänen isänsä hänet ja armahti häntä, juoksi häntä vastaan ja lankesi hänen kaulaansa ja suuteli häntä hellästi.'),
(1694548,58,42,15,21,'Mutta poika sanoi hänelle: ''Isä, minä olen tehnyt syntiä taivasta vastaan ja sinun edessäsi enkä enää ansaitse, että minua sinun pojaksesi kutsutaan''.'),
(1694549,58,42,15,22,'Silloin isä sanoi palvelijoilleen: ''Tuokaa pian parhaat vaatteet ja pukekaa hänet niihin, ja pankaa sormus hänen sormeensa ja kengät hänen jalkaansa;'),
(1694550,58,42,15,23,'ja noutakaa syötetty vasikka ja teurastakaa. Ja syökäämme ja pitäkäämme iloa,'),
(1694551,58,42,15,24,'sillä tämä minun poikani oli kuollut ja virkosi eloon, hän oli kadonnut ja on jälleen löytynyt.'' Ja he rupesivat iloa pitämään.'),
(1694552,58,42,15,25,'Mutta hänen vanhempi poikansa oli pellolla. Ja kun hän tuli ja lähestyi kotia, kuuli hän laulun ja karkelon.'),
(1694553,58,42,15,26,'Ja hän kutsui luoksensa yhden palvelijoista ja tiedusteli, mitä se oli.'),
(1694554,58,42,15,27,'Tämä sanoi hänelle: ''Sinun veljesi on tullut, ja isäsi teurastutti syötetyn vasikan, kun sai hänet terveenä takaisin''.'),
(1694555,58,42,15,28,'Niin hän vihastui eikä tahtonut mennä sisälle; mutta hänen isänsä tuli ulos ja puhutteli häntä leppeästi.'),
(1694556,58,42,15,29,'Mutta hän vastasi ja sanoi isälleen: ''Katso, niin monta vuotta minä olen sinua palvellut enkä ole milloinkaan sinun käskyäsi laiminlyönyt, ja kuitenkaan et ole minulle koskaan antanut vohlaakaan, pitääkseni iloa ystävieni kanssa.'),
(1694557,58,42,15,30,'Mutta kun tämä sinun poikasi tuli, joka on tuhlannut sinun omaisuutesi porttojen kanssa, niin hänelle sinä teurastit syötetyn vasikan.'''),
(1694558,58,42,15,31,'Niin hän sanoi hänelle: ''Poikani, sinä olet aina minun tykönäni, ja kaikki, mikä on minun omaani, on sinun.'),
(1694559,58,42,15,32,'Mutta pitihän nyt riemuita ja iloita, sillä tämä sinun veljesi oli kuollut ja virkosi eloon, hän oli kadonnut ja on jälleen löytynyt.''"'),
(1694560,58,42,16,1,'Ja hän puhui myös opetuslapsilleen: "Oli rikas mies, jolla oli huoneenhaltija, ja hänelle kanneltiin, että tämä hävitti hänen omaisuuttansa.'),
(1694561,58,42,16,2,'Ja hän kutsui hänet eteensä ja sanoi hänelle: ''Mitä minä kuulenkaan sinusta? Tee tili huoneenhallituksestasi; sillä sinä et saa enää minun huonettani hallita.'''),
(1694562,58,42,16,3,'Niin huoneenhaltija sanoi mielessään: ''Mitä minä teen, kun isäntäni ottaa minulta pois huoneenhallituksen? Kaivaa minä en jaksa, kerjuuta häpeän.'),
(1694563,58,42,16,4,'Minä tiedän, mitä teen, että ottaisivat minut taloihinsa, kun minut pannaan pois huoneenhallituksesta.'''),
(1694564,58,42,16,5,'Ja hän kutsui luoksensa jokaisen herransa velallisista ja sanoi ensimmäiselle: ''Paljonko sinä olet velkaa minun herralleni?'''),
(1694565,58,42,16,6,'Tämä sanoi: ''Sata astiaa öljyä''. Niin hän sanoi hänelle: ''Tässä on velkakirjasi, istu ja kirjoita pian viisikymmentä''.'),
(1694566,58,42,16,7,'Sitten hän sanoi toiselle: ''Entä sinä, paljonko sinä olet velkaa?'' Tämä sanoi: ''Sata tynnyriä nisuja''. Hän sanoi hänelle: ''Tässä on velkakirjasi, kirjoita kahdeksankymmentä''.'),
(1694567,58,42,16,8,'Ja herra kehui väärää huoneenhaltijaa siitä, että hän oli menetellyt ovelasti. Sillä tämän maailman lapset ovat omaa sukukuntaansa kohtaan ovelampia kuin valkeuden lapset.'),
(1694568,58,42,16,9,'Ja minä sanon teille: tehkää itsellenne ystäviä väärällä mammonalla, että he, kun se loppuu, ottaisivat teidät iäisiin majoihin.'),
(1694569,58,42,16,10,'Joka vähimmässä on uskollinen, on paljossakin uskollinen, ja joka vähimmässä on väärä, on paljossakin väärä.'),
(1694570,58,42,16,11,'Jos siis ette ole olleet uskolliset väärässä mammonassa, kuka teille uskoo sitä, mikä oikeata on?'),
(1694571,58,42,16,12,'Ja jos ette ole olleet uskolliset siinä, mikä on toisen omaa, kuka teille antaa sitä, mikä teidän omaanne on?'),
(1694572,58,42,16,13,'Ei kukaan palvelija voi palvella kahta herraa; sillä hän on joko tätä vihaava ja toista rakastava, taikka tähän liittyvä ja toista halveksiva. Ette voi palvella Jumalaa ja mammonaa."'),
(1694573,58,42,16,14,'Tämän kaiken kuulivat fariseukset, jotka olivat rahanahneita, ja he ivasivat häntä.'),
(1694574,58,42,16,15,'Ja hän sanoi heille: "Te juuri olette ne, jotka teette itsenne vanhurskaiksi ihmisten edessä, mutta Jumala tuntee teidän sydämenne; sillä mikä ihmisten kesken on korkeata, se on Jumalan edessä kauhistus.'),
(1694575,58,42,16,16,'Laki ja profeetat olivat Johannekseen asti; siitä lähtien julistetaan Jumalan valtakuntaa, ja jokainen tunkeutuu sinne väkisin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694576,58,42,16,17,'Mutta ennemmin taivas ja maa katoavat, kuin yksikään lain piirto häviää.'),
(1694577,58,42,16,18,'Jokainen, joka hylkää vaimonsa ja nai toisen, tekee huorin; ja joka nai miehensä hylkäämän, tekee huorin.'),
(1694578,58,42,16,19,'Oli rikas mies, joka pukeutui purppuraan ja hienoihin pellavavaatteisiin ja eli joka päivä ilossa loisteliaasti.'),
(1694579,58,42,16,20,'Mutta eräs köyhä, nimeltä Lasarus, makasi hänen ovensa edessä täynnä paiseita'),
(1694580,58,42,16,21,'ja halusi ravita itseään niillä muruilla, jotka putosivat rikkaan pöydältä. Ja koiratkin tulivat ja nuolivat hänen paiseitansa.'),
(1694581,58,42,16,22,'Niin tapahtui, että köyhä kuoli, ja enkelit veivät hänet Aabrahamin helmaan. Ja rikaskin kuoli, ja hänet haudattiin.'),
(1694582,58,42,16,23,'Ja kun hän nosti silmänsä tuonelassa, vaivoissa ollessaan, näki hän kaukana Aabrahamin ja Lasaruksen hänen helmassaan.'),
(1694583,58,42,16,24,'Ja hän huusi sanoen: ''Isä Aabraham, armahda minua ja lähetä Lasarus kastamaan sormensa pää veteen ja jäähdyttämään minun kieltäni, sillä minulla on kova tuska tässä liekissä!'''),
(1694584,58,42,16,25,'Mutta Aabraham sanoi: ''Poikani, muista, että sinä eläessäsi sait hyväsi, ja Lasarus samoin sai pahaa; mutta nyt hän täällä saa lohdutusta, sinä taas kärsit tuskaa.'),
(1694585,58,42,16,26,'Ja kaiken tämän lisäksi on meidän välillemme ja teidän vahvistettu suuri juopa, että ne, jotka tahtovat mennä täältä teidän luoksenne, eivät voisi, eivätkä ne, jotka siellä ovat, pääsisi yli meidän luoksemme.'''),
(1694586,58,42,16,27,'Hän sanoi: ''Niin minä siis rukoilen sinua, isä, että lähetät hänet isäni taloon'),
(1694587,58,42,16,28,'- sillä minulla on viisi veljeä - todistamaan heille, etteivät hekin joutuisi tähän vaivan paikkaan''.'),
(1694588,58,42,16,29,'Mutta Aabraham sanoi: ''Heillä on Mooses ja profeetat; kuulkoot niitä''.'),
(1694589,58,42,16,30,'Niin hän sanoi: ''Ei, isä Aabraham; vaan jos joku kuolleista menisi heidän tykönsä, niin he tekisivät parannuksen''.'),
(1694590,58,42,16,31,'Mutta Aabraham sanoi hänelle: ''Jos he eivät kuule Moosesta ja profeettoja, niin eivät he usko, vaikka joku kuolleistakin nousisi ylös''."'),
(1694591,58,42,17,1,'Ja hän sanoi opetuslapsillensa: "Mahdotonta on, että viettelykset jäisivät tulematta; mutta voi sitä, jonka kautta ne tulevat!'),
(1694592,58,42,17,2,'Hänen olisi parempi, että myllynkivi pantaisiin hänen kaulaansa ja hänet heitettäisiin mereen, kuin että hän viettelee yhden näistä pienistä.'),
(1694593,58,42,17,3,'Pitäkää itsestänne vaari! Jos sinun veljesi tekee syntiä, niin nuhtele häntä, ja jos hän katuu, anna hänelle anteeksi.'),
(1694594,58,42,17,4,'Ja jos hän seitsemän kertaa päivässä tekee syntiä sinua vastaan ja seitsemän kertaa kääntyy sinun puoleesi ja sanoo: ''Minä kadun'', niin anna hänelle anteeksi."'),
(1694595,58,42,17,5,'Ja apostolit sanoivat Herralle: "Lisää meille uskoa".'),
(1694596,58,42,17,6,'Niin Herra sanoi: "Jos teillä olisi uskoa sinapinsiemenenkään verran, niin te voisitte sanoa tälle silkkiäispuulle: ''Nouse juurinesi ja istuta itsesi mereen'', ja se tottelisi teitä.'),
(1694597,58,42,17,7,'Jos jollakin teistä on palvelija kyntämässä tai paimentamassa, sanooko hän tälle tämän tullessa pellolta: ''Käy heti aterialle''?'),
(1694598,58,42,17,8,'Eikö hän pikemminkin sano hänelle: ''Valmista minulle ateria, vyöttäydy ja palvele minua, sillä aikaa kuin minä syön ja juon; ja sitten syö ja juo sinä''?'),
(1694599,58,42,17,9,'Ei kaiketi hän kiitä palvelijaa siitä, että tämä teki, mitä oli käsketty?'),
(1694600,58,42,17,10,'Niin myös te, kun olette tehneet kaiken, mitä teidän on käsketty tehdä, sanokaa: ''Me olemme ansiottomia palvelijoita; olemme tehneet vain sen, minkä olimme velvolliset tekemään''."'),
(1694601,58,42,17,11,'Ja kun hän oli matkalla Jerusalemiin, kulki hän Samarian ja Galilean välistä rajaa.'),
(1694602,58,42,17,12,'Ja hänen mennessään erääseen kylään kohtasi häntä kymmenen pitalista miestä, jotka jäivät seisomaan loitommaksi;'),
(1694603,58,42,17,13,'ja he korottivat äänensä ja sanoivat: "Jeesus, mestari, armahda meitä!"'),
(1694604,58,42,17,14,'Ja heidät nähdessään hän sanoi heille: "Menkää ja näyttäkää itsenne papeille". Ja tapahtui heidän mennessään, että he puhdistuivat.'),
(1694605,58,42,17,15,'Mutta yksi heistä, kun näki olevansa parannettu, palasi takaisin ja ylisti Jumalaa suurella äänellä'),
(1694606,58,42,17,16,'ja lankesi kasvoilleen hänen jalkojensa juureen ja kiitti häntä; ja se mies oli samarialainen.'),
(1694607,58,42,17,17,'Niin Jeesus vastasi ja sanoi: "Eivätkö kaikki kymmenen puhdistuneet? Missä ne yhdeksän ovat?'),
(1694608,58,42,17,18,'Eikö ollut muita, jotka olisivat palanneet Jumalaa ylistämään, kuin tämä muukalainen?"'),
(1694609,58,42,17,19,'Ja hän sanoi hänelle: "Nouse ja mene; sinun uskosi on sinut pelastanut".'),
(1694610,58,42,17,20,'Ja kun fariseukset kysyivät häneltä, milloin Jumalan valtakunta oli tuleva, vastasi hän heille ja sanoi: "Ei Jumalan valtakunta tule nähtävällä tavalla,'),
(1694611,58,42,17,21,'eikä voida sanoa: ''Katso, täällä se on'', tahi: ''Tuolla''; sillä katso, Jumalan valtakunta on sisällisesti teissä".'),
(1694612,58,42,17,22,'Ja hän sanoi opetuslapsillensa: "Tulee aika, jolloin te halajaisitte nähdä edes yhtä Ihmisen Pojan päivää, mutta ette saa nähdä.'),
(1694613,58,42,17,23,'Ja teille sanotaan: ''Katso, tuolla hän on!'' ''Katso, täällä!'' Älkää menkö sinne älkääkä juosko perässä.'),
(1694614,58,42,17,24,'Sillä niinkuin salaman leimaus loistaa taivaan äärestä taivaan ääreen, niin on Ihmisen Poika päivänänsä oleva.'),
(1694615,58,42,17,25,'Mutta sitä ennen pitää hänen kärsimän paljon ja joutuman tämän sukupolven hyljittäväksi.'),
(1694616,58,42,17,26,'Ja niinkuin kävi Nooan päivinä, niin käy myöskin Ihmisen Pojan päivinä:'),
(1694617,58,42,17,27,'he söivät, joivat, naivat ja menivät miehelle, aina siihen päivään asti, jona Nooa meni arkkiin; ja vedenpaisumus tuli ja hukutti heidät kaikki.'),
(1694618,58,42,17,28,'Niin myös, samoin kuin kävi Lootin päivinä: he söivät, joivat, ostivat, myivät, istuttivat ja rakensivat,'),
(1694619,58,42,17,29,'mutta sinä päivänä, jona Loot lähti Sodomasta, satoi tulta ja tulikiveä taivaasta, ja se hukutti heidät kaikki,'),
(1694620,58,42,17,30,'samoin käy sinä päivänä, jona Ihmisen Poika ilmestyy.'),
(1694621,58,42,17,31,'Sinä päivänä älköön se, joka katolla on ja jolla on tavaransa huoneessa, astuko alas niitä noutamaan; ja älköön myös se, joka pellolla on, palatko takaisin.'),
(1694622,58,42,17,32,'Muistakaa Lootin vaimoa!'),
(1694623,58,42,17,33,'Joka tahtoo tallettaa elämänsä itselleen, hän kadottaa sen; mutta joka sen kadottaa, pelastaa sen.'),
(1694624,58,42,17,34,'Minä sanon teille: sinä yönä on kaksi miestä yhdellä vuoteella; toinen korjataan talteen, ja toinen jätetään.'),
(1694625,58,42,17,35,'Kaksi naista jauhaa yhdessä; toinen korjataan talteen, mutta toinen jätetään."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694626,58,42,17,37,'Ja he vastasivat ja sanoivat hänelle: "Missä, Herra?" Niin hän sanoi heille: "Missä raato on, sinne myös kotkat kokoontuvat".'),
(1694627,58,42,18,1,'Ja hän puhui heille vertauksen siitä, että heidän tuli aina rukoilla eikä väsyä.'),
(1694628,58,42,18,2,'Hän sanoi: "Eräässä kaupungissa oli tuomari, joka ei peljännyt Jumalaa eikä hävennyt ihmisiä.'),
(1694629,58,42,18,3,'Ja siinä kaupungissa oli leskivaimo, joka vähän väliä tuli hänen luoksensa ja sanoi: ''Auta minut oikeuteeni riitapuoltani vastaan''.'),
(1694630,58,42,18,4,'Mutta pitkään aikaan hän ei tahtonut. Vaan sitten hän sanoi mielessään: ''Vaikka en pelkää Jumalaa enkä häpeä ihmisiä,'),
(1694631,58,42,18,5,'niin kuitenkin, koska tämä leski tuottaa minulle vaivaa, minä autan hänet oikeuteensa, ettei hän lopulta tulisi ja kävisi minun silmilleni''."'),
(1694632,58,42,18,6,'Niin Herra sanoi: "Kuulkaa, mitä tuo väärä tuomari sanoo!'),
(1694633,58,42,18,7,'Eikö sitten Jumala toimittaisi oikeutta valituillensa, jotka häntä yötä päivää avuksi huutavat, ja viivyttäisikö hän heiltä apuansa?'),
(1694634,58,42,18,8,'Minä sanon teille: hän toimittaa heille oikeuden pian. Kuitenkin, kun Ihmisen Poika tulee, löytäneekö hän uskoa maan päältä?"'),
(1694635,58,42,18,9,'Niin hän puhui vielä muutamille, jotka luottivat itseensä, luullen olevansa vanhurskaita, ja ylenkatsoivat muita, tämän vertauksen:'),
(1694636,58,42,18,10,'"Kaksi miestä meni ylös pyhäkköön rukoilemaan, toinen fariseus ja toinen publikaani.'),
(1694637,58,42,18,11,'Fariseus seisoi ja rukoili itsekseen näin: ''Jumala, minä kiitän sinua, etten minä ole niinkuin muut ihmiset, riistäjät, väärämieliset, huorintekijät, enkä myöskään niinkuin tuo publikaani.'),
(1694638,58,42,18,12,'Minä paastoan kahdesti viikossa; minä annan kymmenykset kaikista tuloistani.'''),
(1694639,58,42,18,13,'Mutta publikaani seisoi taampana eikä edes tahtonut nostaa silmiään taivasta kohti, vaan löi rintaansa ja sanoi: ''Jumala, ole minulle syntiselle armollinen''.'),
(1694640,58,42,18,14,'Minä sanon teille: tämä meni kotiinsa vanhurskaampana kuin se toinen; sillä jokainen, joka itsensä ylentää, alennetaan, mutta joka itsensä alentaa, se ylennetään."'),
(1694641,58,42,18,15,'Ja he toivat hänen tykönsä myös pieniä lapsia, että hän koskisi heihin; mutta sen nähdessään opetuslapset nuhtelivat tuojia.'),
(1694642,58,42,18,16,'Mutta Jeesus kutsui lapset tykönsä ja sanoi: "Sallikaa lasten tulla minun tyköni älkääkä estäkö heitä, sillä senkaltaisten on Jumalan valtakunta.'),
(1694643,58,42,18,17,'Totisesti minä sanon teille: joka ei ota vastaan Jumalan valtakuntaa niinkuin lapsi, se ei pääse sinne sisälle."'),
(1694644,58,42,18,18,'Ja eräs hallitusmies kysyi häneltä sanoen: "Hyvä opettaja, mitä minun pitää tekemän, että minä iankaikkisen elämän perisin?"'),
(1694645,58,42,18,19,'Jeesus sanoi hänelle: "Miksi sanot minua hyväksi? Ei kukaan ole hyvä, paitsi Jumala yksin.'),
(1694646,58,42,18,20,'Käskyt sinä tiedät: ''Älä tee huorin'', ''Älä tapa'', ''Älä varasta'', ''Älä sano väärää todistusta'', ''Kunnioita isääsi ja äitiäsi''."'),
(1694647,58,42,18,21,'Mutta hän sanoi: "Tätä kaikkea minä olen noudattanut nuoruudestani asti".'),
(1694648,58,42,18,22,'Kun Jeesus sen kuuli, sanoi hän hänelle: "Yksi sinulta vielä puuttuu: myy kaikki, mitä sinulla on, ja jakele köyhille, niin sinulla on oleva aarre taivaissa; ja tule ja seuraa minua".'),
(1694649,58,42,18,23,'Mutta tämän kuullessaan hän tuli kovin murheelliseksi, sillä hän oli sangen rikas.'),
(1694650,58,42,18,24,'Kun Jeesus näki hänen olevan murheissaan, sanoi hän: "Kuinka vaikea onkaan niiden, joilla on tavaraa, päästä Jumalan valtakuntaan!'),
(1694651,58,42,18,25,'Helpompi on kamelin käydä neulansilmän läpi kuin rikkaan päästä Jumalan valtakuntaan."'),
(1694652,58,42,18,26,'Niin ne, jotka sen kuulivat, sanoivat: "Kuka sitten voi pelastua?"'),
(1694653,58,42,18,27,'Mutta hän sanoi: "Mikä ihmisille on mahdotonta, se on Jumalalle mahdollista".'),
(1694654,58,42,18,28,'Silloin Pietari sanoi: "Katso, me olemme luopuneet siitä, mitä meillä oli, ja seuranneet sinua".'),
(1694655,58,42,18,29,'Niin hän sanoi heille: "Totisesti minä sanon teille: ei ole ketään, joka Jumalan valtakunnan tähden on luopunut talosta tai vaimosta tai veljistä tai vanhemmista tai lapsista,'),
(1694656,58,42,18,30,'ja joka ei saisi monin verroin takaisin tässä ajassa, ja tulevassa maailmassa iankaikkista elämää".'),
(1694657,58,42,18,31,'Ja hän otti tykönsä ne kaksitoista ja sanoi heille: "Katso, me menemme ylös Jerusalemiin, ja kaikki on täysin toteutuva, mitä profeettain kautta on kirjoitettu Ihmisen Pojasta.'),
(1694658,58,42,18,32,'Sillä hänet annetaan pakanain käsiin, ja häntä pilkataan ja häväistään ja syljetään;'),
(1694659,58,42,18,33,'ja ruoskittuaan he tappavat hänet, ja kolmantena päivänä hän nousee ylös."'),
(1694660,58,42,18,34,'Mutta he eivät ymmärtäneet tästä mitään, ja tämä puhe oli heiltä niin salattu, etteivät he käsittäneet, mitä sanottiin.'),
(1694661,58,42,18,35,'Ja hänen lähestyessään Jerikoa eräs sokea istui tien vieressä kerjäten.'),
(1694662,58,42,18,36,'Ja kuullessaan, että siitä kulki kansaa ohi, hän kyseli, mitä se oli.'),
(1694663,58,42,18,37,'He ilmoittivat hänelle Jeesuksen, Nasaretilaisen, menevän ohitse.'),
(1694664,58,42,18,38,'Niin hän huusi sanoen: "Jeesus, Daavidin poika, armahda minua!"'),
(1694665,58,42,18,39,'Ja edelläkulkijat nuhtelivat häntä saadakseen hänet vaikenemaan; mutta hän huusi vielä enemmän: "Daavidin poika, armahda minua!"'),
(1694666,58,42,18,40,'Silloin Jeesus seisahtui ja käski taluttaa hänet tykönsä. Ja hänen tultuaan lähelle Jeesus kysyi häneltä:'),
(1694667,58,42,18,41,'"Mitä tahdot, että minä sinulle tekisin?" Hän sanoi: "Herra, että saisin näköni jälleen".'),
(1694668,58,42,18,42,'Niin Jeesus sanoi hänelle: "Saa näkösi; sinun uskosi on sinut pelastanut".'),
(1694669,58,42,18,43,'Ja heti hän sai näkönsä ja seurasi häntä ylistäen Jumalaa. Ja sen nähdessään kaikki kansa kiitti Jumalaa.'),
(1694670,58,42,19,1,'Ja hän tuli Jerikon kaupunkiin ja kulki sen läpi.'),
(1694671,58,42,19,2,'Ja katso, siellä oli mies, nimeltä Sakkeus; ja hän oli publikaanien päämies ja oli rikas.'),
(1694672,58,42,19,3,'Ja hän koetti saada nähdä Jeesusta, kuka hän oli, mutta ei voinut kansalta, kun oli varreltansa vähäinen.'),
(1694673,58,42,19,4,'Niin hän juoksi edelle ja nousi metsäviikunapuuhun nähdäkseen hänet, sillä Jeesus oli kulkeva siitä ohitse.'),
(1694674,58,42,19,5,'Ja tultuaan sille paikalle Jeesus katsahti ylös ja sanoi hänelle: "Sakkeus, tule nopeasti alas, sillä tänään minun pitää oleman sinun huoneessasi".'),
(1694675,58,42,19,6,'Ja hän tuli nopeasti alas ja otti hänet iloiten vastaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694676,58,42,19,7,'Ja sen nähdessään kaikki nurisivat sanoen: "Syntisen miehen luokse hän meni majailemaan".'),
(1694677,58,42,19,8,'Mutta Sakkeus astui esiin ja sanoi Herralle: "Katso, Herra, puolet omaisuudestani minä annan köyhille, ja jos joltakulta olen jotakin petoksella ottanut, niin annan nelinkertaisesti takaisin".'),
(1694678,58,42,19,9,'Niin Jeesus sanoi hänestä: "Tänään on pelastus tullut tälle huoneelle, koska hänkin on Aabrahamin poika;'),
(1694679,58,42,19,10,'sillä Ihmisen Poika on tullut etsimään ja pelastamaan sitä, mikä kadonnut on".'),
(1694680,58,42,19,11,'Ja heidän tätä kuunnellessaan hän puhui vielä vertauksen, koska hän oli lähellä Jerusalemia ja he luulivat, että Jumalan valtakunta oli kohta ilmestyvä.'),
(1694681,58,42,19,12,'Hän sanoi näin: "Eräs jalosukuinen mies lähti matkalle kaukaiseen maahan saadakseen itsellensä kuninkuuden ja sitten palatakseen.'),
(1694682,58,42,19,13,'Ja hän kutsui luoksensa kymmenen palvelijaansa, antoi heille kymmenen leiviskää ja sanoi heille: ''Asioikaa näillä, kunnes minä tulen''.'),
(1694683,58,42,19,14,'Mutta hänen kansalaisensa vihasivat häntä ja lähettivät lähettiläät hänen jälkeensä sanomaan: ''Emme tahdo tätä kuninkaaksemme''.'),
(1694684,58,42,19,15,'Ja saatuansa kuninkuuden ja palattuansa hän käski kutsua eteensä ne palvelijat, joille hän oli antanut rahat, saadakseen tietää, mitä kukin oli asioimisellaan ansainnut.'),
(1694685,58,42,19,16,'Niin ensimmäinen tuli esiin ja sanoi: ''Herra, sinun leiviskäsi on tuottanut kymmenen leiviskää''.'),
(1694686,58,42,19,17,'Ja hän sanoi hänelle: ''Hyvä on, sinä hyvä palvelija; koska vähimmässä olet ollut uskollinen, niin saat vallita kymmentä kaupunkia''.'),
(1694687,58,42,19,18,'Ja toinen tuli ja sanoi: ''Herra, sinun leiviskäsi on tuottanut viisi leiviskää''.'),
(1694688,58,42,19,19,'Niin hän sanoi tällekin: ''Sinä, vallitse sinä viittä kaupunkia''.'),
(1694689,58,42,19,20,'Vielä tuli yksi ja sanoi: ''Herra, katso, tässä on sinun leiviskäsi, jota olen säilyttänyt liinasessa.'),
(1694690,58,42,19,21,'Sillä minä pelkäsin sinua, koska olet ankara mies: sinä otat, mitä et ole talteen pannut, ja leikkaat, mitä et ole kylvänyt.'''),
(1694691,58,42,19,22,'Hän sanoi hänelle: ''Oman sanasi mukaan minä sinut tuomitsen, sinä paha palvelija. Sinä tiesit minut ankaraksi mieheksi, joka otan, mitä en ole talteen pannut, ja leikkaan, mitä en ole kylvänyt;'),
(1694692,58,42,19,23,'miksi et siis antanut rahojani rahanvaihtajan pöytään, että minä tultuani olisin saanut periä ne korkoineen?'''),
(1694693,58,42,19,24,'Ja hän sanoi vieressä seisoville: ''Ottakaa häneltä pois se leiviskä ja antakaa sille, jolla on kymmenen leiviskää''.'),
(1694694,58,42,19,25,'- Niin he sanoivat hänelle: ''Herra, hänellä on jo kymmenen leiviskää''. -'),
(1694695,58,42,19,26,'''Minä sanon teille: jokaiselle, jolla on, annetaan; mutta jolla ei ole, siltä otetaan pois sekin, mikä hänellä on.'),
(1694696,58,42,19,27,'Mutta viholliseni, jotka eivät tahtoneet minua kuninkaaksensa, tuokaa tänne ja teloittakaa minun edessäni.''"'),
(1694697,58,42,19,28,'Ja tämän sanottuaan hän kulki edellä vaeltaen ylös Jerusalemiin.'),
(1694698,58,42,19,29,'Ja tapahtui, kun hän tuli lähelle Beetfagea ja Betaniaa, sille vuorelle, jota kutsutaan Öljymäeksi, että hän lähetti kaksi opetuslastaan'),
(1694699,58,42,19,30,'sanoen: "Menkää edessä olevaan kylään, niin sinne tullessanne te löydätte sidottuna varsan, jonka selässä ei vielä yksikään ihminen ole istunut; päästäkää se ja tuokaa tänne.'),
(1694700,58,42,19,31,'Ja jos joku kysyy teiltä: ''Miksi te sen päästätte?'' niin sanokaa näin: ''Herra tarvitsee sitä''."'),
(1694701,58,42,19,32,'Ja lähetetyt menivät ja havaitsivat niin olevan, kuin hän oli heille sanonut.'),
(1694702,58,42,19,33,'Ja heidän päästäessään varsaa sen omistajat sanoivat heille: "Miksi te päästätte varsan?"'),
(1694703,58,42,19,34,'Niin he sanoivat: "Herra tarvitsee sitä".'),
(1694704,58,42,19,35,'Ja he veivät sen Jeesuksen luo ja heittivät vaatteensa varsan selkään ja istuttivat Jeesuksen niiden päälle.'),
(1694705,58,42,19,36,'Ja hänen kulkiessaan kansa levitti vaatteensa tielle.'),
(1694706,58,42,19,37,'Ja kun hän jo oli lähellä, laskeutuen Öljymäen rinnettä, rupesi koko opetuslasten joukko iloiten kiittämään Jumalaa suurella äänellä kaikista voimallisista teoista, jotka he olivat nähneet,'),
(1694707,58,42,19,38,'sanoen: "Siunattu olkoon hän, joka tulee, Kuningas Herran nimessä; rauha taivaassa ja kunnia korkeuksissa!"'),
(1694708,58,42,19,39,'Ja muutamat fariseukset kansanjoukosta sanoivat hänelle: "Opettaja, nuhtele opetuslapsiasi".'),
(1694709,58,42,19,40,'Mutta hän vastasi ja sanoi: "Minä sanon teille: jos nämä olisivat vaiti, niin kivet huutaisivat".'),
(1694710,58,42,19,41,'Ja kun hän tuli lähemmäksi ja näki kaupungin, itki hän sitä'),
(1694711,58,42,19,42,'ja sanoi: "Jospa tietäisit sinäkin tänä päivänä, mikä rauhaasi sopii! Mutta nyt se on sinun silmiltäsi salattu.'),
(1694712,58,42,19,43,'Sillä sinulle tulevat ne päivät, jolloin sinun vihollisesi sinut vallilla saartavat ja piirittävät sinut ja ahdistavat sinua joka puolelta;'),
(1694713,58,42,19,44,'ja he kukistavat sinut maan tasalle ja surmaavat lapsesi, jotka sinussa ovat, eivätkä jätä sinuun kiveä kiven päälle, sentähden ettet etsikkoaikaasi tuntenut."'),
(1694714,58,42,19,45,'Ja hän meni pyhäkköön ja rupesi ajamaan myyjiä ulos'),
(1694715,58,42,19,46,'ja sanoi heille: "Kirjoitettu on: ''Minun huoneeni on oleva rukoushuone'', mutta te olette tehneet siitä ryövärien luolan."'),
(1694716,58,42,19,47,'Ja hän opetti joka päivä pyhäkössä. Mutta ylipapit ja kirjanoppineet sekä kansan ensimmäiset miettivät, miten saisivat hänet surmatuksi;'),
(1694717,58,42,19,48,'mutta he eivät keksineet, mitä tekisivät, sillä kaikki kansa riippui hänessä ja kuunteli häntä.'),
(1694718,58,42,20,1,'Ja tapahtui eräänä päivänä, kun hän opetti kansaa pyhäkössä ja julisti evankeliumia, että ylipapit ja kirjanoppineet astuivat yhdessä vanhinten kanssa esiin'),
(1694719,58,42,20,2,'ja puhuivat hänelle sanoen: "Sano meille, millä vallalla sinä näitä teet, tahi kuka on se, joka on antanut sinulle tämän vallan?"'),
(1694720,58,42,20,3,'Hän vastasi ja sanoi heille: "Minä myös teen teille kysymyksen; sanokaa minulle:'),
(1694721,58,42,20,4,'oliko Johanneksen kaste taivaasta vai ihmisistä?"'),
(1694722,58,42,20,5,'Niin he neuvottelivat keskenänsä sanoen: "Jos sanomme: ''Taivaasta'', niin hän sanoo: ''Miksi ette siis uskoneet häntä?'''),
(1694723,58,42,20,6,'Mutta jos sanomme: ''Ihmisistä'', niin kaikki kansa kivittää meidät, sillä se uskoo vahvasti, että Johannes oli profeetta."'),
(1694724,58,42,20,7,'Ja he vastasivat, etteivät tienneet, mistä se oli.'),
(1694725,58,42,20,8,'Niin Jeesus sanoi heille: "Niinpä en minäkään sano teille, millä vallalla minä näitä teen".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694726,58,42,20,9,'Ja hän rupesi puhumaan kansalle ja puhui tämän vertauksen: "Mies istutti viinitarhan ja vuokrasi sen viinitarhureille ja matkusti muille maille kauaksi aikaa.'),
(1694727,58,42,20,10,'Ja ajan tullen hän lähetti palvelijan viinitarhurien luokse, että he antaisivat tälle osan viinitarhan hedelmistä; mutta viinitarhurit pieksivät hänet ja lähettivät tyhjin käsin pois.'),
(1694728,58,42,20,11,'Ja hän lähetti vielä toisen palvelijan; mutta hänetkin he pieksivät ja häpäisivät ja lähettivät tyhjin käsin pois.'),
(1694729,58,42,20,12,'Ja hän lähetti vielä kolmannen; mutta tämänkin he haavoittivat ja heittivät ulos.'),
(1694730,58,42,20,13,'Niin viinitarhan herra sanoi: ''Mitä minä teen? Minä lähetän rakkaan poikani; häntä he kaiketi kavahtavat.'''),
(1694731,58,42,20,14,'Mutta kun viinitarhurit näkivät hänet, neuvottelivat he keskenään ja sanoivat: ''Tämä on perillinen; tappakaamme hänet, että perintö tulisi meidän omaksemme''.'),
(1694732,58,42,20,15,'Ja he heittivät hänet ulos viinitarhasta ja tappoivat. Mitä nyt viinitarhan herra on tekevä heille?'),
(1694733,58,42,20,16,'Hän tulee ja tuhoaa nämä viinitarhurit ja antaa viinitarhan muille." Niin he sen kuullessaan sanoivat: "Pois se!"'),
(1694734,58,42,20,17,'Mutta hän katsahti heihin ja sanoi: "Mitä siis on tämä kirjoitus: ''Se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi''?'),
(1694735,58,42,20,18,'Jokainen, joka kaatuu siihen kiveen, ruhjoutuu, mutta jonka päälle se kaatuu, sen se murskaa."'),
(1694736,58,42,20,19,'Ja kirjanoppineet ja ylipapit tahtoivat ottaa hänet sillä hetkellä kiinni, mutta he pelkäsivät kansaa; sillä he ymmärsivät, että hän oli puhunut sen vertauksen heistä.'),
(1694737,58,42,20,20,'Ja he vartioivat häntä ja lähettivät hänen luokseen hurskaiksi tekeytyviä urkkijoita, saadakseen hänet kiinni jostakin sanasta, niin että voisivat antaa hänet esivallalle ja maaherran käsiin.'),
(1694738,58,42,20,21,'Ja ne kysyivät häneltä sanoen: "Opettaja, me tiedämme, että sinä puhut ja opetat oikein etkä katso henkilöön, vaan opetat Jumalan tietä totuudessa.'),
(1694739,58,42,20,22,'Onko meidän lupa antaa keisarille veroa vai eikö?"'),
(1694740,58,42,20,23,'Mutta hän havaitsi heidän kavaluutensa ja sanoi heille:'),
(1694741,58,42,20,24,'"Näyttäkää minulle denari. Kenen kuva ja päällekirjoitus siinä on?" He vastasivat: "Keisarin".'),
(1694742,58,42,20,25,'Niin hän sanoi heille: "Antakaa siis keisarille, mikä keisarin on, ja Jumalalle, mikä Jumalan on".'),
(1694743,58,42,20,26,'Ja he eivät kyenneet saamaan häntä hänen puheestaan kiinni kansan edessä; ja he ihmettelivät hänen vastaustaan ja vaikenivat.'),
(1694744,58,42,20,27,'Niin astui esiin muutamia saddukeuksia, jotka väittävät, ettei ylösnousemusta ole, ja he kysyivät häneltä'),
(1694745,58,42,20,28,'sanoen: "Opettaja, Mooses on säätänyt meille: ''Jos joltakin kuolee veli, jolla on vaimo, mutta ei ole lapsia, niin ottakoon hän veljensä vaimon ja herättäköön siemenen veljelleen''.'),
(1694746,58,42,20,29,'Nyt oli seitsemän veljestä. Ensimmäinen otti vaimon ja kuoli lapsetonna.'),
(1694747,58,42,20,30,'Niin toinen otti sen vaimon,'),
(1694748,58,42,20,31,'ja sitten kolmas, ja samoin kaikki seitsemän; ja he kuolivat jättämättä lapsia.'),
(1694749,58,42,20,32,'Viimeiseksi vaimokin kuoli.'),
(1694750,58,42,20,33,'Kenelle heistä siis tämä vaimo ylösnousemuksessa joutuu vaimoksi? Sillä kaikkien seitsemän vaimona hän oli ollut."'),
(1694751,58,42,20,34,'Niin Jeesus sanoi heille: "Tämän maailmanajan lapset naivat ja menevät miehelle.'),
(1694752,58,42,20,35,'Mutta ne, jotka on arvollisiksi nähty pääsemään toiseen maailmaan ja ylösnousemukseen kuolleista, eivät nai eivätkä mene miehelle.'),
(1694753,58,42,20,36,'Sillä he eivät enää voi kuolla, kun ovat enkelien kaltaisia; ja he ovat Jumalan lapsia, koska ovat ylösnousemuksen lapsia.'),
(1694754,58,42,20,37,'Mutta että kuolleet nousevat ylös, sen Mooseskin on osoittanut kertomuksessa orjantappurapensaasta, kun hän sanoo Herraa Aabrahamin Jumalaksi ja Iisakin Jumalaksi ja Jaakobin Jumalaksi.'),
(1694755,58,42,20,38,'Mutta hän ei ole kuolleitten Jumala, vaan elävien; sillä kaikki hänelle elävät."'),
(1694756,58,42,20,39,'Niin muutamat kirjanoppineista vastasivat ja sanoivat: "Opettaja, oikein sinä sanoit".'),
(1694757,58,42,20,40,'Ja he eivät enää rohjenneet kysyä häneltä mitään.'),
(1694758,58,42,20,41,'Niin hän sanoi heille: "Kuinka he voivat sanoa, että Kristus on Daavidin poika?'),
(1694759,58,42,20,42,'Sanoohan Daavid itse psalmien kirjassa: ''Herra sanoi minun Herralleni: Istu minun oikealle puolelleni,'),
(1694760,58,42,20,43,'kunnes minä panen sinun vihollisesi sinun jalkojesi astinlaudaksi.'''),
(1694761,58,42,20,44,'Daavid siis kutsuu häntä Herraksi; kuinka hän sitten on hänen poikansa?"'),
(1694762,58,42,20,45,'Ja kaiken kansan kuullen hän sanoi opetuslapsillensa:'),
(1694763,58,42,20,46,'"Kavahtakaa kirjanoppineita, jotka mielellään käyskelevät pitkissä vaipoissa ja haluavat tervehdyksiä toreilla ja etumaisia istuimia synagoogissa ja ensimmäisiä sijoja pidoissa,'),
(1694764,58,42,20,47,'noita, jotka syövät leskien huoneet ja näön vuoksi pitävät pitkiä rukouksia; he saavat sitä kovemman tuomion".'),
(1694765,58,42,21,1,'Ja hän katsahti ja näki rikkaiden panevan lahjoja uhriarkkuun.'),
(1694766,58,42,21,2,'Niin hän näki myös köyhän lesken panevan siihen kaksi ropoa.'),
(1694767,58,42,21,3,'Silloin hän sanoi: "Totisesti minä sanon teille: tämä köyhä leski pani enemmän kuin kaikki muut.'),
(1694768,58,42,21,4,'Sillä kaikki nuo panivat lahjansa liiastaan, mutta tämä pani puutteestaan, koko elämisensä, mikä hänellä oli."'),
(1694769,58,42,21,5,'Ja kun muutamat puhuivat pyhäköstä, kuinka se oli kauniilla kivillä ja temppelilahjoilla kaunistettu, sanoi hän:'),
(1694770,58,42,21,6,'"Päivät tulevat, jolloin tästä, mitä katselette, ei ole jäävä kiveä kiven päälle, maahan jaottamatta".'),
(1694771,58,42,21,7,'Niin he kysyivät häneltä sanoen: "Opettaja, milloin tämä sitten tapahtuu? Ja mikä on oleva merkki tämän tulemisesta?"'),
(1694772,58,42,21,8,'Niin hän sanoi: "Katsokaa, ettei teitä eksytetä. Sillä monta tulee minun nimessäni sanoen: ''Minä olen se'', ja: ''Aika on lähellä''. Mutta älkää menkö heidän perässään.'),
(1694773,58,42,21,9,'Ja kun kuulette sotien ja kapinain melskettä, älkää peljästykö. Sillä näitten täytyy ensin tapahtua, mutta loppu ei tule vielä heti."'),
(1694774,58,42,21,10,'Sitten hän sanoi heille: "Kansa nousee kansaa vastaan ja valtakunta valtakuntaa vastaan,'),
(1694775,58,42,21,11,'ja tulee suuria maanjäristyksiä, tulee ruttoa ja nälänhätää monin paikoin, ja taivaalla on oleva peljättäviä näkyjä ja suuria merkkejä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694776,58,42,21,12,'Mutta ennen tätä kaikkea he käyvät teihin käsiksi ja vainoavat teitä ja vetävät teidät synagoogiin ja heittävät vankiloihin ja vievät teidät kuningasten ja maaherrain eteen minun nimeni tähden.'),
(1694777,58,42,21,13,'Ja näin te joudutte todistamaan.'),
(1694778,58,42,21,14,'Pankaa siis sydämellenne, ettette edeltäpäin huolehdi, miten te vastaatte puolestanne.'),
(1694779,58,42,21,15,'Sillä minä annan teille suun ja viisauden, jota vastaan eivät ketkään teidän vastustajanne kykene asettumaan tai väittämään.'),
(1694780,58,42,21,16,'Omat vanhemmatkin ja veljet ja sukulaiset ja ystävät antavat teidät alttiiksi; ja muutamia teistä tapetaan,'),
(1694781,58,42,21,17,'ja te joudutte kaikkien vihattaviksi minun nimeni tähden.'),
(1694782,58,42,21,18,'Mutta ei hiuskarvaakaan teidän päästänne katoa.'),
(1694783,58,42,21,19,'Kestäväisyydellänne te voitatte omaksenne elämän.'),
(1694784,58,42,21,20,'Mutta kun te näette Jerusalemin sotajoukkojen ympäröimänä, silloin tietäkää, että sen hävitys on lähellä.'),
(1694785,58,42,21,21,'Silloin ne, jotka Juudeassa ovat, paetkoot vuorille, ja jotka ovat kaupungissa, lähtekööt sieltä pois, ja jotka maalla ovat, älkööt sinne menkö.'),
(1694786,58,42,21,22,'Sillä ne ovat koston päiviä, että kaikki täyttyisi, mikä kirjoitettu on.'),
(1694787,58,42,21,23,'Voi raskaita ja imettäväisiä niinä päivinä! Sillä suuri hätä on oleva maan päällä ja viha tätä kansaa vastaan;'),
(1694788,58,42,21,24,'ja he kaatuvat miekan terään, heidät viedään vangeiksi kaikkien kansojen sekaan, ja Jerusalem on oleva pakanain tallattavana, kunnes pakanain ajat täyttyvät.'),
(1694789,58,42,21,25,'Ja on oleva merkit auringossa ja kuussa ja tähdissä, ja ahdistus kansoilla maan päällä ja epätoivo, kun meri ja aallot pauhaavat.'),
(1694790,58,42,21,26,'Ja ihmiset menehtyvät peljätessään ja odottaessaan sitä, mikä maanpiiriä kohtaa; sillä taivaitten voimat järkkyvät.'),
(1694791,58,42,21,27,'Ja silloin he näkevät Ihmisen Pojan tulevan pilvessä suurella voimalla ja kirkkaudella.'),
(1694792,58,42,21,28,'Mutta kun nämä alkavat tapahtua, niin rohkaiskaa itsenne ja nostakaa päänne, sillä teidän vapautuksenne on lähellä."'),
(1694793,58,42,21,29,'Ja hän puhui heille vertauksen: "Katsokaa viikunapuuta ja kaikkia puita.'),
(1694794,58,42,21,30,'Kun ne jo puhkeavat lehteen, niin siitä te näette ja itsestänne ymmärrätte, että kesä jo on lähellä.'),
(1694795,58,42,21,31,'Samoin te myös, kun näette tämän tapahtuvan, tietäkää, että Jumalan valtakunta on lähellä.'),
(1694796,58,42,21,32,'Totisesti minä sanon teille: tämä sukupolvi ei katoa, ennenkuin kaikki tapahtuu.'),
(1694797,58,42,21,33,'Taivas ja maa katoavat, mutta minun sanani eivät katoa.'),
(1694798,58,42,21,34,'Mutta pitäkää vaari itsestänne, ettei teidän sydämiänne raskauta päihtymys ja juoppous eikä elatuksen murheet, niin että se päivä yllättää teidät äkkiarvaamatta'),
(1694799,58,42,21,35,'niinkuin paula; sillä se on saavuttava kaikki, jotka koko maan päällä asuvat.'),
(1694800,58,42,21,36,'Valvokaa siis joka aika ja rukoilkaa, että saisitte voimaa paetaksenne tätä kaikkea, mikä tuleva on, ja seisoaksenne Ihmisen Pojan edessä."'),
(1694801,58,42,21,37,'Ja hän opetti päivät pyhäkössä, mutta öiksi hän lähti pois ja vietti ne vuorella, jota kutsutaan Öljymäeksi.'),
(1694802,58,42,21,38,'Ja kaikki kansa tuli varhain aamuisin hänen tykönsä pyhäkköön kuulemaan häntä.'),
(1694803,58,42,22,1,'Mutta happamattoman leivän juhla, jota pääsiäiseksi sanotaan, oli lähellä.'),
(1694804,58,42,22,2,'Ja ylipapit ja kirjanoppineet miettivät, kuinka saisivat hänet surmatuksi; sillä he pelkäsivät kansaa.'),
(1694805,58,42,22,3,'Niin saatana meni Juudaaseen, jota kutsuttiin Iskariotiksi ja joka oli yksi niistä kahdestatoista.'),
(1694806,58,42,22,4,'Ja tämä meni ja puhui ylipappien ja pyhäkön vartioston päällikköjen kanssa, miten hän saattaisi hänet heidän käsiinsä.'),
(1694807,58,42,22,5,'Ja he ihastuivat ja sitoutuivat antamaan hänelle rahaa.'),
(1694808,58,42,22,6,'Ja hän lupautui ja etsi sopivaa tilaisuutta kavaltaakseen hänet heille ilman melua.'),
(1694809,58,42,22,7,'Niin tuli se happamattoman leivän päivistä, jona pääsiäislammas oli teurastettava.'),
(1694810,58,42,22,8,'Ja hän lähetti Pietarin ja Johanneksen sanoen: "Menkää ja valmistakaa meille pääsiäislammas syödäksemme".'),
(1694811,58,42,22,9,'Niin he kysyivät häneltä: "Mihin tahdot, että valmistamme sen?"'),
(1694812,58,42,22,10,'Hän vastasi heille: "Katso, saapuessanne kaupunkiin tulee teitä vastaan mies kantaen vesiastiaa; seuratkaa häntä siihen taloon, johon hän menee,'),
(1694813,58,42,22,11,'ja sanokaa talon isännälle: ''Opettaja sanoo sinulle: Missä on vierashuone, syödäkseni siinä pääsiäislampaan opetuslasteni kanssa?'''),
(1694814,58,42,22,12,'Niin hän näyttää teille suuren, aterioiville varustetun huoneen yläkerrassa; sinne valmistakaa."'),
(1694815,58,42,22,13,'Ja he menivät ja havaitsivat niin olevan, kuin Jeesus oli heille sanonut, ja valmistivat pääsiäislampaan.'),
(1694816,58,42,22,14,'Ja kun hetki tuli, asettui hän aterialle ja apostolit hänen kanssansa.'),
(1694817,58,42,22,15,'Ja hän sanoi heille: "Minä olen halajamalla halannut syödä tämän pääsiäislampaan teidän kanssanne, ennenkuin minä kärsin;'),
(1694818,58,42,22,16,'sillä minä sanon teille, etten minä sitä enää syö, ennenkuin sen täyttymys tapahtuu Jumalan valtakunnassa".'),
(1694819,58,42,22,17,'Ja hän otti maljan, kiitti ja sanoi: "Ottakaa tämä ja jakakaa keskenänne.'),
(1694820,58,42,22,18,'Sillä minä sanon teille: tästedes minä en juo viinipuun antia, ennenkuin Jumalan valtakunta tulee."'),
(1694821,58,42,22,19,'Ja hän otti leivän, kiitti, mursi ja antoi heille ja sanoi: "Tämä on minun ruumiini, joka teidän edestänne annetaan. Tehkää se minun muistokseni."'),
(1694822,58,42,22,20,'Samoin myös maljan, aterian jälkeen, ja sanoi: "Tämä malja on uusi liitto minun veressäni, joka teidän edestänne vuodatetaan.'),
(1694823,58,42,22,21,'Mutta, katso, minun kavaltajani käsi on minun kanssani pöydällä.'),
(1694824,58,42,22,22,'Sillä Ihmisen Poika tosin menee pois, niinkuin säädetty on; mutta voi sitä ihmistä, jonka kautta hänet kavalletaan!"'),
(1694825,58,42,22,23,'Ja he rupesivat keskenänsä kyselemään, kuka heistä mahtoi olla se, joka oli tämän tekevä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694826,58,42,22,24,'Ja heidän välillään syntyi myös kiista siitä, kuka heistä oli katsottava suurimmaksi.'),
(1694827,58,42,22,25,'Niin hän sanoi heille: "Kansojen kuninkaat herroina niitä hallitsevat, ja niiden valtiaita sanotaan hyväntekijöiksi.'),
(1694828,58,42,22,26,'Mutta älkää te niin; vaan joka teidän keskuudessanne on suurin, se olkoon niinkuin nuorin, ja johtaja niinkuin se, joka palvelee.'),
(1694829,58,42,22,27,'Sillä kumpi on suurempi, sekö, joka aterioi, vai se, joka palvelee? Eikö se, joka aterioi? Mutta minä olen teidän keskellänne niinkuin se, joka palvelee.'),
(1694830,58,42,22,28,'Mutta te olette pysyneet minun kanssani minun kiusauksissani;'),
(1694831,58,42,22,29,'ja minä säädän teille, niinkuin minun Isäni on minulle säätänyt, kuninkaallisen vallan,'),
(1694832,58,42,22,30,'niin että te saatte syödä ja juoda minun pöydässäni minun valtakunnassani ja istua valtaistuimilla ja tuomita Israelin kahtatoista sukukuntaa.'),
(1694833,58,42,22,31,'Simon, Simon, katso, saatana on tavoitellut teitä valtaansa, seuloakseen teitä niinkuin nisuja;'),
(1694834,58,42,22,32,'mutta minä olen rukoillut sinun puolestasi, ettei sinun uskosi raukeaisi tyhjään. Ja kun sinä kerran palajat, niin vahvista veljiäsi."'),
(1694835,58,42,22,33,'Niin Simon sanoi hänelle: "Herra, sinun kanssasi minä olen valmis menemään sekä vankeuteen että kuolemaan".'),
(1694836,58,42,22,34,'Mutta hän sanoi: "Minä sanon sinulle, Pietari: ei laula tänään kukko, ennenkuin sinä kolmesti kiellät tuntevasi minua."'),
(1694837,58,42,22,35,'Ja hän sanoi heille: "Kun minä lähetin teidät ilman rahakukkaroa ja laukkua ja kenkiä, puuttuiko teiltä mitään?" He vastasivat: "Ei mitään".'),
(1694838,58,42,22,36,'Niin hän sanoi heille: "Mutta nyt, jolla on kukkaro, ottakoon sen mukaansa; niin myös laukun. Ja jolla ei ole, myyköön vaippansa ja ostakoon miekan.'),
(1694839,58,42,22,37,'Sillä minä sanon teille, että minussa pitää käymän toteen tämän, mikä kirjoitettu on: ''Ja hänet luettiin pahantekijäin joukkoon''. Sillä se, mikä minusta on sanottu, on täyttynyt."'),
(1694840,58,42,22,38,'Niin he sanoivat: "Herra, katso, tässä on kaksi miekkaa". Mutta hän vastasi heille: "Riittää".'),
(1694841,58,42,22,39,'Ja hän meni ulos ja lähti tapansa mukaan Öljymäelle, ja hänen opetuslapsensa seurasivat häntä.'),
(1694842,58,42,22,40,'Ja tultuaan siihen paikkaan hän sanoi heille: "Rukoilkaa, ettette joutuisi kiusaukseen".'),
(1694843,58,42,22,41,'Ja hän vetäytyi heistä noin kivenheiton päähän, laskeutui polvilleen ja rukoili'),
(1694844,58,42,22,42,'sanoen: "Isä, jos sinä tahdot, niin ota pois minulta tämä malja; älköön kuitenkaan tapahtuko minun tahtoni, vaan sinun".'),
(1694845,58,42,22,43,'Niin hänelle ilmestyi taivaasta enkeli, joka vahvisti häntä.'),
(1694846,58,42,22,44,'Ja kun hän oli suuressa tuskassa, rukoili hän yhä hartaammin. Ja hänen hikensä oli niinkuin veripisarat, jotka putosivat maahan.'),
(1694847,58,42,22,45,'Ja kun hän nousi rukoilemasta ja meni opetuslastensa tykö, tapasi hän heidät murheen tähden nukkumasta.'),
(1694848,58,42,22,46,'Niin hän sanoi heille: "Miksi te nukutte? Nouskaa ja rukoilkaa, ettette joutuisi kiusaukseen."'),
(1694849,58,42,22,47,'Ja katso, hänen vielä puhuessaan tuli joukko kansaa, ja yksi niistä kahdestatoista, se, jonka nimi oli Juudas, kulki heidän edellään. Ja hän tuli Jeesuksen luo antamaan hänelle suuta.'),
(1694850,58,42,22,48,'Mutta Jeesus sanoi hänelle: "Juudas, suunantamisellako sinä Ihmisen Pojan kavallat?"'),
(1694851,58,42,22,49,'Kun nyt ne, jotka olivat hänen ympärillään, näkivät, mitä oli tulossa, sanoivat he: "Herra, iskemmekö miekalla?"'),
(1694852,58,42,22,50,'Ja eräs heistä iski ylimmäisen papin palvelijaa ja sivalsi häneltä pois oikean korvan.'),
(1694853,58,42,22,51,'Mutta Jeesus vastasi sanoen: "Sallikaa vielä tämäkin". Ja hän koski hänen korvaansa ja paransi hänet.'),
(1694854,58,42,22,52,'Niin Jeesus sanoi ylipapeille ja pyhäkön vartioston päälliköille ja vanhimmille, jotka olivat tulleet häntä vastaan: "Niinkuin ryöväriä vastaan te olette lähteneet miekat ja seipäät käsissä.'),
(1694855,58,42,22,53,'Minä olen joka päivä ollut teidän kanssanne pyhäkössä, ettekä ole ojentaneet käsiänne minua vastaan. Mutta tämä on teidän hetkenne ja pimeyden valta."'),
(1694856,58,42,22,54,'Niin he ottivat hänet kiinni ja kuljettivat pois ja veivät hänet ylimmäisen papin taloon. Ja Pietari seurasi taampana.'),
(1694857,58,42,22,55,'Ja he virittivät valkean keskelle esipihaa ja asettuivat yhdessä istumaan, ja Pietari istui heidän joukkoonsa.'),
(1694858,58,42,22,56,'Niin eräs palvelijatar, nähdessään hänen istuvan tulen ääressä, katseli häntä kiinteästi ja sanoi: "Tämäkin oli hänen kanssaan".'),
(1694859,58,42,22,57,'Mutta hän kielsi sanoen: "Nainen, en tunne häntä".'),
(1694860,58,42,22,58,'Ja hetkisen perästä näki hänet toinen, eräs mies, ja sanoi: "Sinäkin olet yksi niistä". Mutta Pietari sanoi: "Mies, en ole".'),
(1694861,58,42,22,59,'Ja noin yhden hetken kuluttua vakuutti vielä toinen sanoen: "Totisesti, tämä oli myös hänen kanssaan; sillä onhan hän galilealainenkin".'),
(1694862,58,42,22,60,'Mutta Pietari sanoi: "En ymmärrä, mies, mitä sanot". Ja samassa, hänen vielä puhuessaan, lauloi kukko.'),
(1694863,58,42,22,61,'Ja Herra kääntyi ja katsoi Pietariin; ja Pietari muisti Herran sanat, kuinka hän oli hänelle sanonut: "Ennenkuin kukko tänään laulaa, sinä kolmesti minut kiellät".'),
(1694864,58,42,22,62,'Ja hän meni ulos ja itki katkerasti.'),
(1694865,58,42,22,63,'Ja miehet, jotka pitivät Jeesusta kiinni, pilkkasivat häntä ja pieksivät häntä.'),
(1694866,58,42,22,64,'Ja he peittivät hänen kasvonsa ja kysyivät häneltä sanoen: "Profetoi, kuka se on, joka sinua löi!"'),
(1694867,58,42,22,65,'Ja paljon muita herjaussanoja he puhuivat häntä vastaan.'),
(1694868,58,42,22,66,'Ja päivän valjetessa kansan vanhimmat ja ylipapit ja kirjanoppineet kokoontuivat ja veivät hänet neuvostonsa eteen'),
(1694869,58,42,22,67,'ja sanoivat: "Jos sinä olet Kristus, niin sano se meille". Hän vastasi heille: "Jos minä teille sanon, niin te ette usko;'),
(1694870,58,42,22,68,'ja jos kysyn, ette vastaa.'),
(1694871,58,42,22,69,'Mutta tästedes Ihmisen Poika on istuva Jumalan voiman oikealla puolella."'),
(1694872,58,42,22,70,'Silloin he kaikki sanoivat: "Sinä siis olet Jumalan Poika?" Hän vastasi heille: "Tepä sen sanotte, että minä olen".'),
(1694873,58,42,22,71,'Niin he sanoivat: "Mitä me enää todistusta tarvitsemme? Sillä me itse olemme kuulleet sen hänen omasta suustansa."'),
(1694874,58,42,23,1,'Ja he nousivat, koko joukko, ja veivät hänet Pilatuksen eteen.'),
(1694875,58,42,23,2,'Ja he alkoivat syyttää häntä sanoen: "Tämän me olemme havainneet villitsevän kansaamme, kieltävän antamasta veroja keisarille ja sanovan itseään Kristukseksi, kuninkaaksi".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694876,58,42,23,3,'Niin Pilatus kysyi häneltä sanoen: "Oletko sinä juutalaisten kuningas?" Hän vastasi hänelle ja sanoi: "Sinäpä sen sanot".'),
(1694877,58,42,23,4,'Pilatus sanoi ylipapeille ja kansalle: "En minä löydä mitään syytä tässä miehessä".'),
(1694878,58,42,23,5,'Mutta he ahdistivat yhä enemmän ja sanoivat: "Hän yllyttää kansaa opettaen kaikkialla Juudeassa, Galileasta alkaen tänne asti".'),
(1694879,58,42,23,6,'Mutta kun Pilatus sen kuuli, kysyi hän, oliko mies galilealainen.'),
(1694880,58,42,23,7,'Ja saatuaan tietää hänen olevan Herodeksen hallintoalueelta hän lähetti hänet Herodeksen eteen, joka hänkin niinä päivinä oli Jerusalemissa.'),
(1694881,58,42,23,8,'Kun Herodes näki Jeesuksen, ihastui hän suuresti; sillä hän oli jo kauan aikaa halunnut nähdä häntä, koska oli kuullut hänestä, ja hän toivoi saavansa nähdä häneltä jonkin ihmeen.'),
(1694882,58,42,23,9,'Ja hän teki Jeesukselle monia kysymyksiä; mutta tämä ei vastannut hänelle mitään.'),
(1694883,58,42,23,10,'Ja ylipapit ja kirjanoppineet seisoivat siinä ja syyttivät häntä kiivaasti.'),
(1694884,58,42,23,11,'Mutta Herodes joukkoineen kohteli häntä halveksivasti ja pilkkasi häntä; ja puetettuaan hänet loistavaan pukuun hän lähetti hänet takaisin Pilatuksen eteen.'),
(1694885,58,42,23,12,'Ja Herodes ja Pilatus tulivat sinä päivänä ystäviksi keskenään; he olivat näet ennen olleet toistensa vihamiehiä.'),
(1694886,58,42,23,13,'Niin Pilatus kutsui kokoon ylipapit ja hallitusmiehet ja kansan'),
(1694887,58,42,23,14,'ja sanoi heille: "Te olette tuoneet minulle tämän miehen kansan yllyttäjänä; ja katso, minä olen teidän läsnäollessanne häntä tutkinut enkä ole havainnut tätä miestä syylliseksi mihinkään, mistä te häntä syytätte,'),
(1694888,58,42,23,15,'eikä Herodeskaan, sillä hän lähetti hänet takaisin meille. Ja katso, hän ei ole tehnyt mitään, mikä ansaitsee kuoleman.'),
(1694889,58,42,23,16,'Kuritettuani häntä minä siis hänet päästän."'),
(1694890,58,42,23,18,'Niin he huusivat kaikki yhdessä, sanoen: "Vie pois tämä, mutta päästä meille Barabbas!"'),
(1694891,58,42,23,19,'Tämä oli heitetty vankeuteen kaupungissa tehdystä kapinasta sekä murhasta.'),
(1694892,58,42,23,20,'Niin Pilatus taas puhui heille, koska hän tahtoi päästää Jeesuksen irti.'),
(1694893,58,42,23,21,'Mutta he huusivat vastaan ja sanoivat: "Ristiinnaulitse, ristiinnaulitse hänet!"'),
(1694894,58,42,23,22,'Niin hän puhui heille kolmannen kerran: "Mitä pahaa hän sitten on tehnyt? En ole havainnut hänessä mitään, mistä hän ansaitsisi kuoleman. Kuritettuani häntä minä siis hänet päästän."'),
(1694895,58,42,23,23,'Mutta he ahdistivat häntä suurilla huudoilla, vaatien Jeesusta ristiinnaulittavaksi; ja heidän huutonsa pääsivät voitolle.'),
(1694896,58,42,23,24,'Niin Pilatus tuomitsi heidän vaatimuksensa täytettäväksi.'),
(1694897,58,42,23,25,'Ja hän päästi irti sen, joka kapinasta ja murhasta oli vankeuteen heitetty ja jota he vaativat, mutta Jeesuksen hän antoi alttiiksi heidän mielivallallensa.'),
(1694898,58,42,23,26,'Ja viedessään häntä pois he saivat käsiinsä Simonin, erään kyreneläisen, joka tuli vainiolta; ja hänen olalleen he panivat ristin kannettavaksi Jeesuksen jäljessä.'),
(1694899,58,42,23,27,'Ja häntä seurasi suuri joukko kansaa, myös naisia, jotka valittivat ja itkivät häntä.'),
(1694900,58,42,23,28,'Niin Jeesus kääntyi heihin ja sanoi: "Jerusalemin tyttäret, älkää minua itkekö, vaan itkekää itseänne ja lapsianne.'),
(1694901,58,42,23,29,'Sillä katso, päivät tulevat, jolloin sanotaan: ''Autuaita ovat hedelmättömät ja ne kohdut, jotka eivät ole synnyttäneet, ja rinnat, jotka eivät ole imettäneet''.'),
(1694902,58,42,23,30,'Silloin ruvetaan sanomaan vuorille: ''Langetkaa meidän päällemme'', ja kukkuloille: ''Peittäkää meidät''.'),
(1694903,58,42,23,31,'Sillä jos tämä tehdään tuoreelle puulle, mitä sitten kuivalle tapahtuu?"'),
(1694904,58,42,23,32,'Myös kaksi muuta, kaksi pahantekijää, vietiin hänen kanssaan surmattaviksi.'),
(1694905,58,42,23,33,'Ja kun saavuttiin paikalle, jota sanotaan Pääkallonpaikaksi, niin siellä he ristiinnaulitsivat hänet sekä pahantekijät, toisen oikealle ja toisen vasemmalle puolelle.'),
(1694906,58,42,23,34,'Mutta Jeesus sanoi: "Isä, anna heille anteeksi, sillä he eivät tiedä, mitä he tekevät". Ja he jakoivat keskenään hänen vaatteensa ja heittivät niistä arpaa.'),
(1694907,58,42,23,35,'Ja kansa seisoi ja katseli. Ja hallitusmiehetkin ivasivat häntä ja sanoivat: "Muita hän on auttanut; auttakoon itseänsä, jos hän on Jumalan Kristus, se valittu".'),
(1694908,58,42,23,36,'Myös sotamiehet pilkkasivat häntä, menivät hänen luoksensa ja tarjosivat hänelle hapanviiniä'),
(1694909,58,42,23,37,'ja sanoivat: "Jos sinä olet juutalaisten kuningas, niin auta itseäsi".'),
(1694910,58,42,23,38,'Oli myös hänen päänsä päällä kirjoitus: "Tämä on juutalaisten kuningas".'),
(1694911,58,42,23,39,'Niin toinen pahantekijöistä, jotka siinä riippuivat, herjasi häntä: "Etkö sinä ole Kristus? Auta itseäsi ja meitä."'),
(1694912,58,42,23,40,'Mutta toinen vastasi ja nuhteli häntä sanoen: "Etkö sinä edes pelkää Jumalaa, sinä, joka olet saman rangaistuksen alainen?'),
(1694913,58,42,23,41,'Me tosin kärsimme oikeuden mukaan, sillä me saamme, mitä meidän tekomme ansaitsevat; mutta tämä ei ole mitään pahaa tehnyt."'),
(1694914,58,42,23,42,'Ja hän sanoi: "Jeesus, muista minua, kun tulet valtakuntaasi".'),
(1694915,58,42,23,43,'Niin Jeesus sanoi hänelle: "Totisesti minä sanon sinulle: tänä päivänä pitää sinun oleman minun kanssani paratiisissa."'),
(1694916,58,42,23,44,'Ja oli jo noin kuudes hetki. Niin yli kaiken maan tuli pimeys, jota kesti hamaan yhdeksänteen hetkeen,'),
(1694917,58,42,23,45,'sillä aurinko oli pimentynyt. Ja temppelin esirippu repesi keskeltä kahtia.'),
(1694918,58,42,23,46,'Ja Jeesus huusi suurella äänellä ja sanoi: "Isä, sinun käsiisi minä annan henkeni". Ja sen sanottuaan hän antoi henkensä.'),
(1694919,58,42,23,47,'Mutta kun sadanpäämies näki, mitä tapahtui, kunnioitti hän Jumalaa ja sanoi: "Totisesti, tämä oli vanhurskas mies".'),
(1694920,58,42,23,48,'Ja kun kaikki kansa, ne, jotka olivat kokoontuneet tätä katselemaan, näkivät, mitä tapahtui, löivät he rintoihinsa ja palasivat kukin kotiinsa.'),
(1694921,58,42,23,49,'Mutta kaikki hänen tuttavansa seisoivat taampana, myöskin naiset, jotka olivat seuranneet häntä Galileasta, ja katselivat tätä.'),
(1694922,58,42,23,50,'Ja katso, oli neuvoston jäsen, nimeltä Joosef, hyvä ja hurskas mies, joka ei ollut suostunut heidän neuvoonsa ja tekoonsa.'),
(1694923,58,42,23,51,'Tämä oli kotoisin juutalaisten kaupungista Arimatiasta, ja hän odotti Jumalan valtakuntaa.'),
(1694924,58,42,23,52,'Hän meni Pilatuksen luo ja pyysi Jeesuksen ruumista.'),
(1694925,58,42,23,53,'Ja otettuaan sen alas hän kääri sen liinavaatteeseen. Ja hän pani hänet hautaan, joka oli hakattu kallioon ja johon ei oltu vielä ketään pantu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694926,58,42,23,54,'Ja silloin oli valmistuspäivä, ja sapatti oli alkamaisillaan.'),
(1694927,58,42,23,55,'Ja naiset, jotka olivat tulleet hänen kanssaan Galileasta, seurasivat jäljessä ja katselivat hautaa ja kuinka hänen ruumiinsa sinne pantiin.'),
(1694928,58,42,23,56,'Ja palattuaan kotiinsa he valmistivat hyvänhajuisia yrttejä ja voiteita; mutta sapatin he viettivät hiljaisuudessa lain käskyn mukaan.'),
(1694929,58,42,24,1,'Mutta viikon ensimmäisenä päivänä ani varhain he tulivat haudalle, tuoden mukanaan valmistamansa hyvänhajuiset yrtit.'),
(1694930,58,42,24,2,'Ja he havaitsivat kiven vieritetyksi pois haudalta.'),
(1694931,58,42,24,3,'Niin he menivät sisään, mutta eivät löytäneet Herran Jeesuksen ruumista.'),
(1694932,58,42,24,4,'Ja kun he olivat tästä ymmällä, niin katso, kaksi miestä seisoi heidän edessään säteilevissä vaatteissa.'),
(1694933,58,42,24,5,'Ja he peljästyivät ja kumartuivat kasvoillensa maahan. Niin miehet sanoivat heille: "Miksi te etsitte elävää kuolleitten joukosta?'),
(1694934,58,42,24,6,'Ei hän ole täällä, hän on noussut ylös. Muistakaa, kuinka hän puhui teille vielä ollessaan Galileassa,'),
(1694935,58,42,24,7,'sanoen: ''Ihmisen Poika pitää annettaman syntisten ihmisten käsiin ja ristiinnaulittaman, ja hänen pitää kolmantena päivänä nouseman ylös''."'),
(1694936,58,42,24,8,'Niin he muistivat hänen sanansa.'),
(1694937,58,42,24,9,'Ja he palasivat haudalta ja veivät sanan tästä kaikesta niille yhdelletoista ja kaikille muille.'),
(1694938,58,42,24,10,'Ja ne, jotka kertoivat tämän apostoleille, olivat Maria Magdaleena ja Johanna ja Maria, Jaakobin äiti, ja muut naiset heidän kanssansa.'),
(1694939,58,42,24,11,'Mutta näiden puheet näyttivät heistä turhilta, eivätkä he uskoneet heitä.'),
(1694940,58,42,24,12,'Mutta Pietari nousi ja juoksi haudalle; ja kun hän kurkisti sisään, näki hän siellä ainoastaan käärinliinat. Ja hän meni pois ihmetellen itsekseen sitä, mikä oli tapahtunut.'),
(1694941,58,42,24,13,'Ja katso, kaksi heistä kulki sinä päivänä Emmaus nimiseen kylään, joka on kuudenkymmenen vakomitan päässä Jerusalemista.'),
(1694942,58,42,24,14,'Ja he puhelivat keskenään kaikesta tästä, mikä oli tapahtunut.'),
(1694943,58,42,24,15,'Ja heidän keskustellessaan ja tutkistellessaan tapahtui, että Jeesus itse lähestyi heitä ja kulki heidän kanssansa.'),
(1694944,58,42,24,16,'Mutta heidän silmänsä olivat pimitetyt, niin etteivät he tunteneet häntä.'),
(1694945,58,42,24,17,'Ja hän sanoi heille: "Mistä te siinä kävellessänne puhutte keskenänne?" Niin he seisahtuivat murheellisina muodoltansa.'),
(1694946,58,42,24,18,'Ja toinen heistä, nimeltä Kleopas, vastasi ja sanoi hänelle: "Oletko sinä ainoa muukalainen Jerusalemissa, joka et tiedä, mitä siellä näinä päivinä on tapahtunut?"'),
(1694947,58,42,24,19,'Hän sanoi heille: "Mitä?" Niin he sanoivat hänelle: "Sitä, mikä tapahtui Jeesukselle, Nasaretilaiselle, joka oli profeetta, voimallinen teossa ja sanassa Jumalan ja kaiken kansan edessä,'),
(1694948,58,42,24,20,'kuinka meidän ylipappimme ja hallitusmiehemme antoivat hänet tuomittavaksi kuolemaan ja ristiinnaulitsivat hänet.'),
(1694949,58,42,24,21,'Mutta me toivoimme hänen olevan sen, joka oli lunastava Israelin. Ja onhan kaiken tämän lisäksi nyt jo kolmas päivä siitä, kuin nämä tapahtuivat.'),
(1694950,58,42,24,22,'Ovatpa vielä muutamat naiset joukostamme saattaneet meidät hämmästyksiin. He kävivät aamulla varhain haudalla'),
(1694951,58,42,24,23,'eivätkä löytäneet hänen ruumistaan, ja tulivat ja sanoivat myös nähneensä enkelinäyn, ja enkelit olivat sanoneet hänen elävän.'),
(1694952,58,42,24,24,'Ja muutamat niistä, jotka olivat meidän kanssamme, menivät haudalle ja havaitsivat niin olevan, kuin naiset olivat sanoneet; mutta häntä he eivät nähneet."'),
(1694953,58,42,24,25,'Niin hän sanoi heille: "Oi, te ymmärtämättömät ja hitaat sydämeltä uskomaan kaikkea sitä, minkä profeetat ovat puhuneet!'),
(1694954,58,42,24,26,'Eikö Kristuksen pitänyt tätä kärsimän ja sitten menemän kirkkauteensa?"'),
(1694955,58,42,24,27,'Ja hän alkoi Mooseksesta ja kaikista profeetoista ja selitti heille, mitä hänestä oli kaikissa kirjoituksissa sanottu.'),
(1694956,58,42,24,28,'Ja kun he lähestyivät kylää, johon olivat menossa, niin hän oli aikovinaan kulkea edemmäksi.'),
(1694957,58,42,24,29,'Mutta he vaativat häntä sanoen: "Jää meidän luoksemme, sillä ilta joutuu ja päivä on jo laskemassa". Ja hän meni sisään ja jäi heidän luoksensa.'),
(1694958,58,42,24,30,'Ja tapahtui, kun hän oli aterialla heidän kanssaan, että hän otti leivän, siunasi, mursi ja antoi heille.'),
(1694959,58,42,24,31,'Silloin heidän silmänsä aukenivat, ja he tunsivat hänet. Ja hän katosi heidän näkyvistään.'),
(1694960,58,42,24,32,'Ja he sanoivat toisillensa: "Eikö sydämemme ollut meissä palava, kun hän puhui meille tiellä ja selitti meille kirjoitukset?"'),
(1694961,58,42,24,33,'Ja he nousivat sillä hetkellä ja palasivat Jerusalemiin ja tapasivat ne yksitoista kokoontuneina ja ne, jotka olivat heidän kanssansa.'),
(1694962,58,42,24,34,'Ja nämä sanoivat: "Herra on totisesti noussut ylös ja on ilmestynyt Simonille".'),
(1694963,58,42,24,35,'Ja itse he kertoivat, mitä oli tapahtunut tiellä ja kuinka he olivat hänet tunteneet, kun hän mursi leivän.'),
(1694964,58,42,24,36,'Mutta heidän tätä puhuessaan Jeesus itse seisoi heidän keskellään ja sanoi heille: "Rauha teille!"'),
(1694965,58,42,24,37,'Niin heidät valtasi säikähdys ja pelko, ja he luulivat näkevänsä hengen.'),
(1694966,58,42,24,38,'Mutta hän sanoi heille: "Miksi olette hämmästyneet, ja miksi nousee sellaisia ajatuksia teidän sydämeenne?'),
(1694967,58,42,24,39,'Katsokaa minun käsiäni ja jalkojani ja nähkää, että minä itse tässä olen. Kosketelkaa minua ja katsokaa, sillä ei hengellä ole lihaa eikä luita, niinkuin te näette minulla olevan."'),
(1694968,58,42,24,40,'Ja tämän sanottuaan hän näytti heille kätensä ja jalkansa.'),
(1694969,58,42,24,41,'Mutta kun he eivät vielä uskoneet, ilon tähden, vaan ihmettelivät, sanoi hän heille: "Onko teillä täällä jotakin syötävää?"'),
(1694970,58,42,24,42,'Niin he antoivat hänelle palasen paistettua kalaa.'),
(1694971,58,42,24,43,'Ja hän otti ja söi heidän nähtensä.'),
(1694972,58,42,24,44,'Ja hän sanoi heille: "Tätä tarkoittivat minun sanani, kun minä puhuin teille ollessani vielä teidän kanssanne, että kaiken pitää käymän toteen, mikä minusta on kirjoitettu Mooseksen laissa ja profeetoissa ja psalmeissa".'),
(1694973,58,42,24,45,'Silloin hän avasi heidän ymmärryksensä käsittämään kirjoitukset.'),
(1694974,58,42,24,46,'Ja hän sanoi heille: "Niin on kirjoitettu, että Kristus oli kärsivä ja kolmantena päivänä nouseva kuolleista,'),
(1694975,58,42,24,47,'ja että parannusta syntien anteeksisaamiseksi on saarnattava hänen nimessänsä kaikille kansoille, alkaen Jerusalemista.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1694976,58,42,24,48,'Te olette tämän todistajat.'),
(1694977,58,42,24,49,'Ja katso, minä lähetän teille sen, jonka minun Isäni on luvannut; mutta te pysykää tässä kaupungissa, kunnes teidän päällenne puetaan voima korkeudesta."'),
(1694978,58,42,24,50,'Sitten hän vei heidät pois, lähes Betaniaan asti, ja nosti kätensä ja siunasi heidät.'),
(1694979,58,42,24,51,'Ja tapahtui, että hän siunatessaan heitä erkani heistä, ja hänet otettiin ylös taivaaseen.'),
(1694980,58,42,24,52,'Ja he kumarsivat häntä ja palasivat Jerusalemiin suuresti iloiten.'),
(1694981,58,42,24,53,'Ja he olivat alati pyhäkössä ja ylistivät Jumalaa.'),
(1694982,58,43,1,1,'Alussa oli Sana, ja Sana oli Jumalan tykönä, ja Sana oli Jumala.'),
(1694983,58,43,1,2,'Hän oli alussa Jumalan tykönä.'),
(1694984,58,43,1,3,'Kaikki on saanut syntynsä hänen kauttaan, ja ilman häntä ei ole syntynyt mitään, mikä syntynyt on.'),
(1694985,58,43,1,4,'Hänessä oli elämä, ja elämä oli ihmisten valkeus.'),
(1694986,58,43,1,5,'Ja valkeus loistaa pimeydessä, ja pimeys ei sitä käsittänyt.'),
(1694987,58,43,1,6,'Oli mies, Jumalan lähettämä; hänen nimensä oli Johannes.'),
(1694988,58,43,1,7,'Hän tuli todistamaan, todistaaksensa valkeudesta, että kaikki uskoisivat hänen kauttansa.'),
(1694989,58,43,1,8,'Ei hän ollut se valkeus, mutta hän tuli valkeudesta todistamaan.'),
(1694990,58,43,1,9,'Totinen valkeus, joka valistaa jokaisen ihmisen, oli tulossa maailmaan.'),
(1694991,58,43,1,10,'Maailmassa hän oli, ja maailma on hänen kauttaan saanut syntynsä, ja maailma ei häntä tuntenut.'),
(1694992,58,43,1,11,'Hän tuli omiensa tykö, ja hänen omansa eivät ottaneet häntä vastaan.'),
(1694993,58,43,1,12,'Mutta kaikille, jotka ottivat hänet vastaan, hän antoi voiman tulla Jumalan lapsiksi, niille, jotka uskovat hänen nimeensä,'),
(1694994,58,43,1,13,'jotka eivät ole syntyneet verestä eikä lihan tahdosta eikä miehen tahdosta, vaan Jumalasta.'),
(1694995,58,43,1,14,'Ja Sana tuli lihaksi ja asui meidän keskellämme, ja me katselimme hänen kirkkauttansa, senkaltaista kirkkautta, kuin ainokaisella Pojalla on Isältä; ja hän oli täynnä armoa ja totuutta.'),
(1694996,58,43,1,15,'Johannes todisti hänestä ja huusi sanoen: "Tämä on se, josta minä sanoin: se, joka minun jälkeeni tulee, on ollut minun edelläni, sillä hän on ollut ennen kuin minä."'),
(1694997,58,43,1,16,'Ja hänen täyteydestään me kaikki olemme saaneet, ja armoa armon päälle.'),
(1694998,58,43,1,17,'Sillä laki on annettu Mooseksen kautta; armo ja totuus on tullut Jeesuksen Kristuksen kautta.'),
(1694999,58,43,1,18,'Ei kukaan ole Jumalaa milloinkaan nähnyt; ainokainen Poika, joka on Isän helmassa, on hänet ilmoittanut.'),
(1695000,58,43,1,19,'Ja tämä on Johanneksen todistus, kun juutalaiset lähettivät hänen luoksensa Jerusalemista pappeja ja leeviläisiä kysymään häneltä: "Kuka sinä olet?"'),
(1695001,58,43,1,20,'Ja hän tunnusti eikä kieltänyt; ja hän tunnusti: "Minä en ole Kristus".'),
(1695002,58,43,1,21,'Ja he kysyivät häneltä: "Mikä sitten? Oletko sinä Elias?" Hän sanoi: "En ole". "Se profeettako olet?" Hän vastasi: "En".'),
(1695003,58,43,1,22,'Niin he sanoivat hänelle: "Kuka olet, että voisimme antaa vastauksen niille, jotka meidät lähettivät? Mitä sanot itsestäsi?"'),
(1695004,58,43,1,23,'Hän sanoi: "Minä olen huutavan ääni erämaassa: ''Tehkää tie tasaiseksi Herralle'', niinkuin profeetta Esaias on sanonut."'),
(1695005,58,43,1,24,'Ja lähetetyt olivat fariseuksia;'),
(1695006,58,43,1,25,'ja he kysyivät häneltä ja sanoivat hänelle: "Miksi sitten kastat, jos et ole Kristus etkä Elias etkä se profeetta?"'),
(1695007,58,43,1,26,'Johannes vastasi heille sanoen: "Minä kastan vedellä; mutta teidän keskellänne seisoo hän, jota te ette tunne.'),
(1695008,58,43,1,27,'Hän on se, joka tulee minun jälkeeni ja jonka kengänpaulaa minä en ole arvollinen päästämään."'),
(1695009,58,43,1,28,'Tämä tapahtui Betaniassa, Jordanin tuolla puolella, jossa Johannes oli kastamassa.'),
(1695010,58,43,1,29,'Seuraavana päivänä hän näki Jeesuksen tulevan tykönsä ja sanoi: "Katso, Jumalan Karitsa, joka ottaa pois maailman synnin!'),
(1695011,58,43,1,30,'Tämä on se, josta minä sanoin: ''Minun jälkeeni tulee mies, joka on ollut minun edelläni, sillä hän on ollut ennen kuin minä''.'),
(1695012,58,43,1,31,'Ja minä en tuntenut häntä; mutta sitä varten, että hän tulisi julki Israelille, minä olen tullut vedellä kastamaan."'),
(1695013,58,43,1,32,'Ja Johannes todisti sanoen: "Minä näin Hengen laskeutuvan taivaasta alas niinkuin kyyhkysen, ja se jäi hänen päällensä.'),
(1695014,58,43,1,33,'Ja minä en tuntenut häntä; mutta hän, joka lähetti minut vedellä kastamaan, sanoi minulle: ''Se, jonka päälle sinä näet Hengen laskeutuvan ja jäävän, hän on se, joka kastaa Pyhällä Hengellä''.'),
(1695015,58,43,1,34,'Ja minä olen sen nähnyt ja olen todistanut, että tämä on Jumalan Poika."'),
(1695016,58,43,1,35,'Seuraavana päivänä Johannes taas seisoi siellä ja kaksi hänen opetuslapsistansa.'),
(1695017,58,43,1,36,'Ja kiinnittäen katseensa Jeesukseen, joka siellä käveli, hän sanoi: "Katso, Jumalan Karitsa!"'),
(1695018,58,43,1,37,'Ja ne kaksi opetuslasta kuulivat hänen näin puhuvan ja seurasivat Jeesusta.'),
(1695019,58,43,1,38,'Niin Jeesus kääntyi ja nähdessään heidän seuraavan sanoi heille: "Mitä te etsitte?" He vastasivat hänelle: "Rabbi" - se on käännettynä: opettaja - "missä sinä majailet?"'),
(1695020,58,43,1,39,'Hän sanoi heille: "Tulkaa ja katsokaa". Niin he menivät ja näkivät, missä hän majaili, ja viipyivät hänen tykönään sen päivän. Silloin oli noin kymmenes hetki.'),
(1695021,58,43,1,40,'Andreas, Simon Pietarin veli, oli toinen niistä kahdesta, jotka olivat kuulleet, mitä Johannes sanoi, ja seuranneet Jeesusta.'),
(1695022,58,43,1,41,'Hän tapasi ensin veljensä Simonin ja sanoi hänelle: "Me olemme löytäneet Messiaan", se on käännettynä: Kristus.'),
(1695023,58,43,1,42,'Ja hän vei hänet Jeesuksen tykö. Jeesus kiinnitti katseensa häneen ja sanoi: "Sinä olet Simon, Johanneksen poika; sinun nimesi on oleva Keefas", joka käännettynä on Pietari.'),
(1695024,58,43,1,43,'Seuraavana päivänä Jeesus tahtoi lähteä Galileaan; ja hän tapasi Filippuksen ja sanoi hänelle: "Seuraa minua".'),
(1695025,58,43,1,44,'Ja Filippus oli Beetsaidasta, Andreaan ja Pietarin kaupungista.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695026,58,43,1,45,'Filippus tapasi Natanaelin ja sanoi hänelle: "Me olemme löytäneet sen, josta Mooses laissa ja profeetat ovat kirjoittaneet, Jeesuksen, Joosefin pojan, Nasaretista".'),
(1695027,58,43,1,46,'Natanael sanoi hänelle: "Voiko Nasaretista tulla mitään hyvää?" Filippus sanoi hänelle: "Tule ja katso".'),
(1695028,58,43,1,47,'Jeesus näki Natanaelin tulevan tykönsä ja sanoi hänestä: "Katso, oikea israelilainen, jossa ei vilppiä ole!"'),
(1695029,58,43,1,48,'Natanael sanoi hänelle: "Mistä minut tunnet?" Jeesus vastasi ja sanoi hänelle: "Ennenkuin Filippus sinua kutsui, kun olit viikunapuun alla, näin minä sinut".'),
(1695030,58,43,1,49,'Natanael vastasi ja sanoi hänelle: "Rabbi, sinä olet Jumalan Poika, sinä olet Israelin kuningas".'),
(1695031,58,43,1,50,'Jeesus vastasi ja sanoi hänelle: "Sentähden, että minä sanoin sinulle: ''minä näin sinut viikunapuun alla'', sinä uskot. Sinä saat nähdä suurempia, kuin nämä ovat."'),
(1695032,58,43,1,51,'Ja hän sanoi hänelle: "Totisesti, totisesti minä sanon teille: te saatte nähdä taivaan avoinna ja Jumalan enkelien nousevan ylös ja laskeutuvan alas Ihmisen Pojan päälle."'),
(1695033,58,43,2,1,'Ja kolmantena päivänä oli häät Galilean Kaanassa, ja Jeesuksen äiti oli siellä.'),
(1695034,58,43,2,2,'Ja myös Jeesus ja hänen opetuslapsensa olivat kutsutut häihin.'),
(1695035,58,43,2,3,'Ja kun viini loppui, sanoi Jeesuksen äiti hänelle: "Heillä ei ole viiniä".'),
(1695036,58,43,2,4,'Jeesus sanoi hänelle: "Mitä sinä tahdot minusta, vaimo? Minun aikani ei ole vielä tullut."'),
(1695037,58,43,2,5,'Hänen äitinsä sanoi palvelijoille: "Mitä hän teille sanoo, se tehkää".'),
(1695038,58,43,2,6,'Niin oli siinä juutalaisten puhdistamistavan mukaan kuusi kivistä vesiastiaa, kukin kahden tai kolmen mitan vetoinen.'),
(1695039,58,43,2,7,'Jeesus sanoi heille: "Täyttäkää astiat vedellä". Ja he täyttivät ne reunoja myöten.'),
(1695040,58,43,2,8,'Ja hän sanoi heille: "Ammentakaa nyt ja viekää edeskäyvälle". Ja he veivät.'),
(1695041,58,43,2,9,'Mutta kun edeskäypä maistoi vettä, joka oli muuttunut viiniksi, eikä tiennyt, mistä se oli tullut - mutta palvelijat, jotka veden olivat ammentaneet, tiesivät sen - kutsui edeskäypä yljän'),
(1695042,58,43,2,10,'ja sanoi hänelle: "Jokainen panee ensin esille hyvän viinin ja sitten, kun juopuvat, huonomman. Sinä olet säästänyt hyvän viinin tähän asti."'),
(1695043,58,43,2,11,'Tämän ensimmäisen tunnustekonsa Jeesus teki Galilean Kaanassa ja ilmoitti kirkkautensa; ja hänen opetuslapsensa uskoivat häneen.'),
(1695044,58,43,2,12,'Sen jälkeen hän meni alas Kapernaumiin, hän ja hänen äitinsä ja veljensä ja opetuslapsensa; ja siellä he eivät viipyneet monta päivää.'),
(1695045,58,43,2,13,'Ja juutalaisten pääsiäinen oli lähellä, ja Jeesus meni ylös Jerusalemiin.'),
(1695046,58,43,2,14,'Niin hän tapasi pyhäkössä ne, jotka myivät härkiä ja lampaita ja kyyhkysiä, ja rahanvaihtajat istumassa.'),
(1695047,58,43,2,15,'Ja hän teki nuorista ruoskan ja ajoi ulos pyhäköstä heidät kaikki lampaineen ja härkineen ja kaasi vaihtajain rahat maahan ja työnsi heidän pöytänsä kumoon.'),
(1695048,58,43,2,16,'Ja hän sanoi kyyhkysten myyjille: "Viekää pois nämä täältä. Älkää tehkö minun Isäni huonetta markkinahuoneeksi."'),
(1695049,58,43,2,17,'Silloin hänen opetuslapsensa muistivat, että on kirjoitettu: "Kiivaus sinun huoneesi puolesta kuluttaa minut".'),
(1695050,58,43,2,18,'Niin juutalaiset vastasivat ja sanoivat hänelle: "Minkä merkin sinä näytät meille, koska näitä teet?"'),
(1695051,58,43,2,19,'Jeesus vastasi ja sanoi heille: "Hajottakaa maahan tämä temppeli, niin minä pystytän sen kolmessa päivässä".'),
(1695052,58,43,2,20,'Niin juutalaiset sanoivat: "Neljäkymmentä kuusi vuotta on tätä temppeliä rakennettu, ja sinäkö pystytät sen kolmessa päivässä?"'),
(1695053,58,43,2,21,'Mutta hän puhui ruumiinsa temppelistä.'),
(1695054,58,43,2,22,'Kun hän sitten oli noussut kuolleista, muistivat hänen opetuslapsensa, että hän oli tämän sanonut; ja he uskoivat Raamatun ja sen sanan, jonka Jeesus oli sanonut.'),
(1695055,58,43,2,23,'Mutta kun hän oli Jerusalemissa pääsiäisenä, juhlan aikana, uskoivat monet hänen nimeensä, nähdessään hänen tunnustekonsa, jotka hän teki.'),
(1695056,58,43,2,24,'Mutta Jeesus itse ei uskonut itseänsä heille, sentähden että hän tunsi kaikki'),
(1695057,58,43,2,25,'eikä tarvinnut kenenkään todistusta ihmisestä, sillä hän tiesi itse, mitä ihmisessä on.'),
(1695058,58,43,3,1,'Mutta oli mies, fariseusten joukosta, nimeltä Nikodeemus, juutalaisten hallitusmiehiä.'),
(1695059,58,43,3,2,'Hän tuli Jeesuksen tykö yöllä ja sanoi hänelle: "Rabbi, me tiedämme, että sinun opettajaksi tulemisesi on Jumalasta, sillä ei kukaan voi tehdä niitä tunnustekoja, joita sinä teet, ellei Jumala ole hänen kanssansa."'),
(1695060,58,43,3,3,'Jeesus vastasi ja sanoi hänelle: "Totisesti, totisesti minä sanon sinulle: joka ei synny uudesti, ylhäältä, se ei voi nähdä Jumalan valtakuntaa".'),
(1695061,58,43,3,4,'Nikodeemus sanoi hänelle: "Kuinka voi ihminen vanhana syntyä? Eihän hän voi jälleen mennä äitinsä kohtuun ja syntyä?"'),
(1695062,58,43,3,5,'Jeesus vastasi: "Totisesti, totisesti minä sanon sinulle: jos joku ei synny vedestä ja Hengestä, ei hän voi päästä sisälle Jumalan valtakuntaan.'),
(1695063,58,43,3,6,'Mikä lihasta on syntynyt, on liha; ja mikä Hengestä on syntynyt, on henki.'),
(1695064,58,43,3,7,'Älä ihmettele, että minä sanoin sinulle: teidän täytyy syntyä uudesti, ylhäältä.'),
(1695065,58,43,3,8,'Tuuli puhaltaa, missä tahtoo, ja sinä kuulet sen huminan, mutta et tiedä, mistä se tulee ja minne se menee; niin on jokaisen, joka on Hengestä syntynyt."'),
(1695066,58,43,3,9,'Nikodeemus vastasi ja sanoi hänelle: "Kuinka tämä voi tapahtua?"'),
(1695067,58,43,3,10,'Jeesus vastasi ja sanoi hänelle: "Sinä olet Israelin opettaja etkä tätä tiedä!'),
(1695068,58,43,3,11,'Totisesti, totisesti minä sanon sinulle: me puhumme, mitä tiedämme, ja todistamme, mitä olemme nähneet, ettekä te ota vastaan meidän todistustamme.'),
(1695069,58,43,3,12,'Jos ette usko, kun minä puhun teille maallisista, kuinka te uskoisitte, jos minä puhun teille taivaallisista?'),
(1695070,58,43,3,13,'Ei kukaan ole noussut ylös taivaaseen, paitsi hän, joka taivaasta tuli alas, Ihmisen Poika, joka on taivaassa.'),
(1695071,58,43,3,14,'Ja niinkuin Mooses ylensi käärmeen erämaassa, niin pitää Ihmisen Poika ylennettämän,'),
(1695072,58,43,3,15,'että jokaisella, joka häneen uskoo, olisi iankaikkinen elämä.'),
(1695073,58,43,3,16,'Sillä niin on Jumala maailmaa rakastanut, että hän antoi ainokaisen Poikansa, ettei yksikään, joka häneen uskoo, hukkuisi, vaan hänellä olisi iankaikkinen elämä.'),
(1695074,58,43,3,17,'Sillä ei Jumala lähettänyt Poikaansa maailmaan tuomitsemaan maailmaa, vaan sitä varten, että maailma hänen kauttansa pelastuisi.'),
(1695075,58,43,3,18,'Joka uskoo häneen, sitä ei tuomita; mutta joka ei usko, se on jo tuomittu, koska hän ei ole uskonut Jumalan ainokaisen Pojan nimeen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695076,58,43,3,19,'Mutta tämä on tuomio, että valkeus on tullut maailmaan, ja ihmiset rakastivat pimeyttä enemmän kuin valkeutta; sillä heidän tekonsa olivat pahat.'),
(1695077,58,43,3,20,'Sillä jokainen, joka pahaa tekee, vihaa valkeutta eikä tule valkeuteen, ettei hänen tekojansa nuhdeltaisi.'),
(1695078,58,43,3,21,'Mutta joka totuuden tekee, se tulee valkeuteen, että hänen tekonsa tulisivat julki, sillä ne ovat Jumalassa tehdyt."'),
(1695079,58,43,3,22,'Sen jälkeen Jeesus meni opetuslapsineen Juudean maaseudulle ja oleskeli siellä heidän kanssaan ja kastoi.'),
(1695080,58,43,3,23,'Mutta Johanneskin kastoi Ainonissa lähellä Salimia, koska siellä oli paljon vettä; ja ihmiset tulivat ja antoivat kastaa itsensä.'),
(1695081,58,43,3,24,'Sillä Johannesta ei vielä oltu heitetty vankeuteen.'),
(1695082,58,43,3,25,'Niin Johanneksen opetuslapset rupesivat väittelemään erään juutalaisen kanssa puhdistuksesta.'),
(1695083,58,43,3,26,'Ja he tulivat Johanneksen luo ja sanoivat hänelle: "Rabbi, se, joka oli sinun kanssasi Jordanin tuolla puolella ja josta sinä olet todistanut, katso, hän kastaa, ja kaikki menevät hänen tykönsä".'),
(1695084,58,43,3,27,'Johannes vastasi ja sanoi: "Ei ihminen voi ottaa mitään, ellei hänelle anneta taivaasta.'),
(1695085,58,43,3,28,'Te olette itse minun todistajani, että minä sanoin: en minä ole Kristus, vaan minä olen hänen edellänsä lähetetty.'),
(1695086,58,43,3,29,'Jolla on morsian, se on ylkä; mutta yljän ystävä, joka seisoo ja kuuntelee häntä, iloitsee suuresti yljän äänestä. Tämä minun iloni on nyt tullut täydelliseksi.'),
(1695087,58,43,3,30,'Hänen tulee kasvaa, mutta minun vähetä.'),
(1695088,58,43,3,31,'Hän, joka ylhäältä tulee, on yli kaikkien. Joka on syntyisin maasta, se on maasta, ja maasta on, mitä hän puhuu; hän, joka taivaasta tulee, on yli kaikkien.'),
(1695089,58,43,3,32,'Ja mitä hän on nähnyt ja kuullut, sitä hän todistaa; ja hänen todistustansa ei kukaan ota vastaan.'),
(1695090,58,43,3,33,'Joka ottaa vastaan hänen todistuksensa, se sinetillä vahvistaa, että Jumala on totinen.'),
(1695091,58,43,3,34,'Sillä hän, jonka Jumala on lähettänyt, puhuu Jumalan sanoja; sillä ei Jumala anna Henkeä mitalla.'),
(1695092,58,43,3,35,'Isä rakastaa Poikaa ja on antanut kaikki hänen käteensä.'),
(1695093,58,43,3,36,'Joka uskoo Poikaan, sillä on iankaikkinen elämä; mutta joka ei ole kuuliainen Pojalle, se ei ole elämää näkevä, vaan Jumalan viha pysyy hänen päällänsä."'),
(1695094,58,43,4,1,'Kun nyt Herra sai tietää fariseusten kuulleen, että Jeesus teki opetuslapsiksi ja kastoi useampia kuin Johannes'),
(1695095,58,43,4,2,'- vaikka Jeesus ei itse kastanut, vaan hänen opetuslapsensa -'),
(1695096,58,43,4,3,'jätti hän Juudean ja meni taas Galileaan.'),
(1695097,58,43,4,4,'Mutta hänen oli kuljettava Samarian kautta.'),
(1695098,58,43,4,5,'Niin hän tuli Sykar nimiseen Samarian kaupunkiin, joka on lähellä sitä maa-aluetta, minkä Jaakob oli antanut pojalleen Joosefille.'),
(1695099,58,43,4,6,'Ja siellä oli Jaakobin lähde. Kun nyt Jeesus oli matkasta väsynyt, istui hän lähteen reunalle. Ja oli noin kuudes hetki.'),
(1695100,58,43,4,7,'Niin tuli eräs Samarian nainen ammentamaan vettä. Jeesus sanoi hänelle: "Anna minulle juoda".'),
(1695101,58,43,4,8,'Sillä hänen opetuslapsensa olivat lähteneet kaupunkiin ruokaa ostamaan.'),
(1695102,58,43,4,9,'Niin Samarian nainen sanoi hänelle: "Kuinka sinä, joka olet juutalainen, pyydät juotavaa minulta, samarialaiselta naiselta?" Sillä juutalaiset eivät seurustele samarialaisten kanssa.'),
(1695103,58,43,4,10,'Jeesus vastasi ja sanoi hänelle: "Jos sinä tietäisit Jumalan lahjan, ja kuka se on, joka sinulle sanoo: ''Anna minulle juoda'', niin sinä pyytäisit häneltä, ja hän antaisi sinulle elävää vettä."'),
(1695104,58,43,4,11,'Nainen sanoi hänelle: "Herra, eipä sinulla ole ammennusastiaa, ja kaivo on syvä; mistä sinulla sitten on se elävä vesi?'),
(1695105,58,43,4,12,'Et kai sinä ole suurempi kuin meidän isämme Jaakob, joka antoi meille tämän kaivon ja joi siitä, hän itse sekä hänen poikansa ja karjansa?"'),
(1695106,58,43,4,13,'Jeesus vastasi ja sanoi hänelle: "Jokainen, joka juo tätä vettä, janoaa jälleen,'),
(1695107,58,43,4,14,'mutta joka juo sitä vettä, jota minä hänelle annan, se ei ikinä janoa; vaan se vesi, jonka minä hänelle annan, tulee hänessä sen veden lähteeksi, joka kumpuaa iankaikkiseen elämään".'),
(1695108,58,43,4,15,'Nainen sanoi hänelle: "Herra, anna minulle sitä vettä, ettei minun tulisi jano eikä minun tarvitsisi käydä täällä ammentamassa".'),
(1695109,58,43,4,16,'Jeesus sanoi hänelle: "Mene, kutsu miehesi ja tule tänne".'),
(1695110,58,43,4,17,'Nainen vastasi ja sanoi: "Ei minulla ole miestä". Jeesus sanoi hänelle: "Oikein sinä sanoit: ''Ei minulla ole miestä'','),
(1695111,58,43,4,18,'sillä viisi miestä sinulla on ollut, ja se, joka sinulla nyt on, ei ole sinun miehesi; siinä sanoit totuuden."'),
(1695112,58,43,4,19,'Nainen sanoi hänelle: "Herra, minä näen, että sinä olet profeetta.'),
(1695113,58,43,4,20,'Meidän isämme ovat kumartaen rukoilleet tällä vuorella; ja te sanotte, että Jerusalemissa on se paikka, jossa tulee kumartaen rukoilla."'),
(1695114,58,43,4,21,'Jeesus sanoi hänelle: "Vaimo, usko minua! Tulee aika, jolloin ette rukoile Isää tällä vuorella ettekä Jerusalemissa.'),
(1695115,58,43,4,22,'Te kumarratte sitä, mitä ette tunne; me kumarramme sitä, minkä me tunnemme. Sillä pelastus on juutalaisista.'),
(1695116,58,43,4,23,'Mutta tulee aika ja on jo, jolloin totiset rukoilijat rukoilevat Isää hengessä ja totuudessa; sillä senkaltaisia rukoilijoita myös Isä tahtoo.'),
(1695117,58,43,4,24,'Jumala on Henki; ja jotka häntä rukoilevat, niiden tulee rukoilla hengessä ja totuudessa."'),
(1695118,58,43,4,25,'Nainen sanoi hänelle: "Minä tiedän, että Messias on tuleva, hän, jota sanotaan Kristukseksi; kun hän tulee, ilmoittaa hän meille kaikki".'),
(1695119,58,43,4,26,'Jeesus sanoi hänelle: "Minä olen se, minä, joka puhun sinun kanssasi".'),
(1695120,58,43,4,27,'Samassa hänen opetuslapsensa tulivat; ja he ihmettelivät, että hän puhui naisen kanssa. Kuitenkaan ei kukaan sanonut: "Mitä pyydät?" tai: "Mitä puhelet hänen kanssaan?"'),
(1695121,58,43,4,28,'Niin nainen jätti vesiastiansa ja meni kaupunkiin ja sanoi ihmisille:'),
(1695122,58,43,4,29,'"Tulkaa katsomaan miestä, joka on sanonut minulle kaikki, mitä minä olen tehnyt. Eihän se vain liene Kristus?"'),
(1695123,58,43,4,30,'Niin he lähtivät kaupungista ja menivät hänen luoksensa.'),
(1695124,58,43,4,31,'Sillävälin opetuslapset pyysivät häntä sanoen: "Rabbi, syö!"'),
(1695125,58,43,4,32,'Mutta hän sanoi heille: "Minulla on syötävänä ruokaa, josta te ette tiedä".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695126,58,43,4,33,'Niin opetuslapset sanoivat keskenään: "Lieneekö joku tuonut hänelle syötävää?"'),
(1695127,58,43,4,34,'Jeesus sanoi heille: "Minun ruokani on se, että minä teen lähettäjäni tahdon ja täytän hänen tekonsa.'),
(1695128,58,43,4,35,'Ettekö sano: ''Vielä on neljä kuukautta, niin elonleikkuu joutuu''? Katso, minä sanon teille: nostakaa silmänne ja katselkaa vainioita, kuinka ne ovat valjenneet leikattaviksi.'),
(1695129,58,43,4,36,'Jo nyt saa leikkaaja palkan ja kokoaa hedelmää iankaikkiseen elämään, että kylväjä ja leikkaaja saisivat yhdessä iloita.'),
(1695130,58,43,4,37,'Sillä tässä on se sana tosi, että toinen on kylväjä, ja leikkaaja toinen.'),
(1695131,58,43,4,38,'Minä olen lähettänyt teidät leikkaamaan sitä, josta te ette ole vaivaa nähneet; toiset ovat vaivan nähneet, ja te olette päässeet heidän vaivansa hedelmille."'),
(1695132,58,43,4,39,'Ja monet samarialaiset siitä kaupungista uskoivat häneen naisen puheen tähden, kun tämä todisti: "Hän on sanonut minulle kaikki, mitä minä olen tehnyt".'),
(1695133,58,43,4,40,'Kun nyt samarialaiset tulivat hänen luoksensa, pyysivät he häntä viipymään heidän luonaan; ja hän viipyi siellä kaksi päivää.'),
(1695134,58,43,4,41,'Ja vielä paljoa useammat uskoivat hänen sanansa tähden,'),
(1695135,58,43,4,42,'ja he sanoivat naiselle: "Emme enää usko sinun puheesi tähden, sillä me itse olemme kuulleet ja tiedämme, että tämä totisesti on maailman Vapahtaja".'),
(1695136,58,43,4,43,'Mutta niiden kahden päivän kuluttua hän lähti sieltä Galileaan.'),
(1695137,58,43,4,44,'Sillä Jeesus itse todisti, ettei profeetalla ole arvoa omassa isiensä maassa.'),
(1695138,58,43,4,45,'Kun hän siis tuli Galileaan, ottivat galilealaiset hänet vastaan, koska olivat nähneet kaikki, mitä hän oli tehnyt Jerusalemissa juhlan aikana; sillä hekin olivat tulleet juhlille.'),
(1695139,58,43,4,46,'Niin hän tuli taas Galilean Kaanaan, jossa hän oli tehnyt veden viiniksi. Ja Kapernaumissa oli eräs kuninkaan virkamies, jonka poika sairasti.'),
(1695140,58,43,4,47,'Kun hän kuuli Jeesuksen tulleen Juudeasta Galileaan, meni hän hänen luoksensa ja pyysi häntä tulemaan ja parantamaan hänen poikansa; sillä tämä oli kuolemaisillaan.'),
(1695141,58,43,4,48,'Niin Jeesus sanoi hänelle: "Ellette näe merkkejä ja ihmeitä, te ette usko".'),
(1695142,58,43,4,49,'Kuninkaan virkamies sanoi hänelle: "Herra, tule, ennenkuin minun lapseni kuolee".'),
(1695143,58,43,4,50,'Jeesus sanoi hänelle: "Mene, sinun poikasi elää". Ja mies uskoi sanan, jonka Jeesus sanoi hänelle, ja meni.'),
(1695144,58,43,4,51,'Ja jo hänen ollessaan paluumatkalla hänen palvelijansa kohtasivat hänet ja sanoivat, että hänen poikansa eli.'),
(1695145,58,43,4,52,'Niin hän tiedusteli heiltä, millä hetkellä hän oli alkanut toipua. Ja he sanoivat hänelle: "Eilen seitsemännellä hetkellä kuume lähti hänestä".'),
(1695146,58,43,4,53,'Niin isä ymmärsi, että se oli tapahtunut sillä hetkellä, jolloin Jeesus oli sanonut hänelle: "Sinun poikasi elää". Ja hän uskoi, hän ja koko hänen huonekuntansa.'),
(1695147,58,43,4,54,'Tämä oli taas tunnusteko, toinen, jonka Jeesus teki, tultuaan Juudeasta Galileaan.'),
(1695148,58,43,5,1,'Sen jälkeen oli juutalaisten juhla, ja Jeesus meni ylös Jerusalemiin.'),
(1695149,58,43,5,2,'Ja Jerusalemissa on Lammasportin luona lammikko, jonka nimi hebreankielellä on Betesda, ja sen reunalla on viisi pylväskäytävää.'),
(1695150,58,43,5,3,'Niissä makasi suuri joukko sairaita, sokeita, rampoja ja näivetystautisia, jotka odottivat veden liikuttamista.'),
(1695151,58,43,5,5,'Ja siellä oli mies, joka oli sairastanut kolmekymmentä kahdeksan vuotta.'),
(1695152,58,43,5,6,'Kun Jeesus näki hänen siinä makaavan ja tiesi hänen jo kauan aikaa sairastaneen, sanoi hän hänelle: "Tahdotko tulla terveeksi?"'),
(1695153,58,43,5,7,'Sairas vastasi hänelle: "Herra, minulla ei ole ketään, joka veisi minut lammikkoon, kun vesi on kuohutettu; ja kun minä olen menemässä, astuu toinen sinne ennen minua".'),
(1695154,58,43,5,8,'Jeesus sanoi hänelle: "Nouse, ota vuoteesi ja käy".'),
(1695155,58,43,5,9,'Ja mies tuli kohta terveeksi ja otti vuoteensa ja kävi. Mutta se päivä oli sapatti.'),
(1695156,58,43,5,10,'Sentähden juutalaiset sanoivat parannetulle: "Nyt on sapatti, eikä sinun ole lupa kantaa vuodetta".'),
(1695157,58,43,5,11,'Hän vastasi heille: "Se, joka teki minut terveeksi, sanoi minulle: ''Ota vuoteesi ja käy''."'),
(1695158,58,43,5,12,'He kysyivät häneltä: "Kuka on se mies, joka sanoi sinulle: ''Ota vuoteesi ja käy''?"'),
(1695159,58,43,5,13,'Mutta parannettu ei tiennyt, kuka se oli; sillä Jeesus oli poistunut, kun siinä paikassa oli paljon kansaa.'),
(1695160,58,43,5,14,'Sen jälkeen Jeesus tapasi hänet pyhäkössä ja sanoi hänelle: "Katso, sinä olet tullut terveeksi; älä enää syntiä tee, ettei sinulle jotakin pahempaa tapahtuisi".'),
(1695161,58,43,5,15,'Niin mies meni ja ilmoitti juutalaisille, että Jeesus oli hänet terveeksi tehnyt.'),
(1695162,58,43,5,16,'Ja sentähden juutalaiset vainosivat Jeesusta, koska hän semmoista teki sapattina.'),
(1695163,58,43,5,17,'Mutta Jeesus vastasi heille: "Minun Isäni tekee yhäti työtä, ja minä myös teen työtä".'),
(1695164,58,43,5,18,'Sentähden juutalaiset vielä enemmän tavoittelivat häntä tappaaksensa, kun hän ei ainoastaan kumonnut sapattia, vaan myös sanoi Jumalaa Isäksensä, tehden itsensä Jumalan vertaiseksi.'),
(1695165,58,43,5,19,'Niin Jeesus vastasi ja sanoi heille: "Totisesti, totisesti minä sanon teille: Poika ei voi itsestänsä mitään tehdä, vaan ainoastaan sen, minkä hän näkee Isän tekevän; sillä mitä Isä tekee, sitä myös Poika samoin tekee.'),
(1695166,58,43,5,20,'Sillä Isä rakastaa Poikaa ja näyttää hänelle kaikki, mitä hän itse tekee; ja hän on näyttävä hänelle suurempia tekoja kuin nämä, niin että te ihmettelette.'),
(1695167,58,43,5,21,'Sillä niinkuin Isä herättää kuolleita ja tekee eläviksi, niin myös Poika tekee eläviksi, ketkä hän tahtoo.'),
(1695168,58,43,5,22,'Sillä Isä ei myöskään tuomitse ketään, vaan hän on antanut kaiken tuomion Pojalle,'),
(1695169,58,43,5,23,'että kaikki kunnioittaisivat Poikaa, niinkuin he kunnioittavat Isää. Joka ei kunnioita Poikaa, se ei kunnioita Isää, joka on hänet lähettänyt.'),
(1695170,58,43,5,24,'Totisesti, totisesti minä sanon teille: joka kuulee minun sanani ja uskoo häneen, joka on minut lähettänyt, sillä on iankaikkinen elämä, eikä hän joudu tuomittavaksi, vaan on siirtynyt kuolemasta elämään.'),
(1695171,58,43,5,25,'Totisesti, totisesti minä sanon teille: aika tulee ja on jo, jolloin kuolleet kuulevat Jumalan Pojan äänen, ja jotka sen kuulevat ne saavat elää.'),
(1695172,58,43,5,26,'Sillä niinkuin Isällä on elämä itsessänsä, niin hän on antanut elämän myös Pojalle, niin että myös hänellä on elämä itsessänsä.'),
(1695173,58,43,5,27,'Ja hän on antanut hänelle vallan tuomita, koska hän on Ihmisen Poika.'),
(1695174,58,43,5,28,'Älkää ihmetelkö tätä, sillä hetki tulee, jolloin kaikki, jotka haudoissa ovat, kuulevat hänen äänensä'),
(1695175,58,43,5,29,'ja tulevat esiin, ne, jotka ovat hyvää tehneet, elämän ylösnousemukseen, mutta ne, jotka ovat pahaa tehneet, tuomion ylösnousemukseen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695176,58,43,5,30,'En minä itsestäni voi mitään tehdä. Niinkuin minä kuulen, niin minä tuomitsen; ja minun tuomioni on oikea, sillä minä en kysy omaa tahtoani, vaan hänen tahtoaan, joka on minut lähettänyt.'),
(1695177,58,43,5,31,'Jos minä itsestäni todistan, ei minun todistukseni ole pätevä.'),
(1695178,58,43,5,32,'On toinen, joka todistaa minusta, ja minä tiedän, että se todistus, jonka hän minusta todistaa, on pätevä.'),
(1695179,58,43,5,33,'Te lähetitte lähettiläät Johanneksen luo, ja hän todisti sen, mikä totta on.'),
(1695180,58,43,5,34,'Mutta minä en ota ihmiseltä todistusta, vaan puhun tämän, että te pelastuisitte.'),
(1695181,58,43,5,35,'Hän oli palava ja loistava lamppu, mutta te tahdoitte ainoastaan hetken iloitella hänen valossansa.'),
(1695182,58,43,5,36,'Mutta minulla on todistus, joka on suurempi kuin Johanneksen; sillä ne teot, jotka Isä on antanut minun täytettävikseni, ne teot, jotka minä teen, todistavat minusta, että Isä on minut lähettänyt.'),
(1695183,58,43,5,37,'Ja Isä, joka on minut lähettänyt, hän on todistanut minusta. Te ette ole koskaan kuulleet hänen ääntänsä ettekä nähneet hänen muotoansa,'),
(1695184,58,43,5,38,'eikä teillä ole hänen sanaansa teissä pysyväisenä; sillä te ette usko sitä, jonka hän on lähettänyt.'),
(1695185,58,43,5,39,'Te tutkitte kirjoituksia, sillä teillä on mielestänne niissä iankaikkinen elämä, ja ne juuri todistavat minusta;'),
(1695186,58,43,5,40,'ja te ette tahdo tulla minun tyköni, että saisitte elämän.'),
(1695187,58,43,5,41,'En minä ota vastaan kunniaa ihmisiltä;'),
(1695188,58,43,5,42,'mutta minä tunnen teidät, ettei teillä ole Jumalan rakkautta itsessänne.'),
(1695189,58,43,5,43,'Minä olen tullut Isäni nimessä, ja te ette ota minua vastaan; jos toinen tulee omassa nimessään, niin hänet te otatte vastaan.'),
(1695190,58,43,5,44,'Kuinka te voisitte uskoa, te, jotka otatte vastaan kunniaa toinen toiseltanne, ettekä etsi sitä kunniaa, mikä tulee häneltä, joka yksin on Jumala?'),
(1695191,58,43,5,45,'Älkää luulko, että minä olen syyttävä teitä Isän tykönä; teillä on syyttäjänne, Mooses, johon te panette toivonne.'),
(1695192,58,43,5,46,'Sillä jos te Moosesta uskoisitte, niin te uskoisitte minua; sillä minusta hän on kirjoittanut.'),
(1695193,58,43,5,47,'Mutta jos te ette usko hänen kirjoituksiaan, kuinka te uskoisitte minun sanojani?"'),
(1695194,58,43,6,1,'Sen jälkeen Jeesus meni Galileaan, se on Tiberiaan, järven tuolle puolelle.'),
(1695195,58,43,6,2,'Ja häntä seurasi paljon kansaa, koska he näkivät ne tunnusteot, joita hän teki sairaille.'),
(1695196,58,43,6,3,'Ja Jeesus nousi vuorelle ja istui sinne opetuslapsinensa.'),
(1695197,58,43,6,4,'Ja pääsiäinen, juutalaisten juhla, oli lähellä.'),
(1695198,58,43,6,5,'Kun Jeesus nosti silmänsä ja näki paljon kansaa tulevan tykönsä, sanoi hän Filippukselle: "Mistä ostamme leipää näiden syödä?"'),
(1695199,58,43,6,6,'Mutta sen hän sanoi koetellakseen häntä, sillä itse hän tiesi, mitä aikoi tehdä.'),
(1695200,58,43,6,7,'Filippus vastasi hänelle: "Eivät kahdensadan denarin leivät heille riittäisi, niin että kukin saisi edes vähän".'),
(1695201,58,43,6,8,'Niin toinen hänen opetuslapsistansa, Andreas, Simon Pietarin veli, sanoi hänelle:'),
(1695202,58,43,6,9,'"Täällä on poikanen, jolla on viisi ohraleipää ja kaksi kalaa, mutta mitä ne ovat näin monelle?"'),
(1695203,58,43,6,10,'Jeesus sanoi: "Asettakaa kansa aterioimaan". Ja siinä paikassa oli paljon ruohoa. Niin miehet, luvultaan noin viisituhatta, laskeutuivat maahan.'),
(1695204,58,43,6,11,'Ja Jeesus otti leivät ja kiitti ja jakeli istuville; samoin kaloistakin, niin paljon kuin he tahtoivat.'),
(1695205,58,43,6,12,'Mutta kun he olivat ravitut, sanoi hän opetuslapsillensa: "Kootkaa tähteeksi jääneet palaset, ettei mitään joutuisi hukkaan".'),
(1695206,58,43,6,13,'Niin he kokosivat ne ja täyttivät kaksitoista vakkaa palasilla, mitkä olivat viidestä ohraleivästä jääneet tähteeksi niiltä, jotka olivat aterioineet.'),
(1695207,58,43,6,14,'Kun nyt ihmiset näkivät sen tunnusteon, jonka Jeesus oli tehnyt, sanoivat he: "Tämä on totisesti se profeetta, joka oli maailmaan tuleva".'),
(1695208,58,43,6,15,'Kun nyt Jeesus huomasi, että he aikoivat tulla ja väkisin ottaa hänet, tehdäkseen hänet kuninkaaksi, väistyi hän taas pois vuorelle, hän yksinänsä.'),
(1695209,58,43,6,16,'Mutta kun ilta tuli, menivät hänen opetuslapsensa alas järven rantaan,'),
(1695210,58,43,6,17,'astuivat venheeseen ja lähtivät menemään järven toiselle puolelle, Kapernaumiin. Ja oli jo tullut pimeä, eikä Jeesus ollut vielä saapunut heidän luokseen;'),
(1695211,58,43,6,18,'ja järvi aaltoili ankarasti kovan tuulen puhaltaessa.'),
(1695212,58,43,6,19,'Kun he olivat soutaneet noin viisikolmatta tai kolmekymmentä vakomittaa, näkivät he Jeesuksen kävelevän järven päällä ja tulevan lähelle venhettä; ja he peljästyivät.'),
(1695213,58,43,6,20,'Mutta hän sanoi heille: "Minä se olen; älkää peljätkö".'),
(1695214,58,43,6,21,'Niin he tahtoivat ottaa hänet venheeseen, ja kohta venhe saapui sen maan rantaan, jonne he olivat matkalla.'),
(1695215,58,43,6,22,'Seuraavana päivänä kansa yhä vielä oli järven toisella puolella, sillä he olivat nähneet, ettei siellä ollut muuta venhettä kuin se yksi ja ettei Jeesus mennyt opetuslastensa kanssa venheeseen, vaan että hänen opetuslapsensa lähtivät yksinään pois.'),
(1695216,58,43,6,23,'Kuitenkin oli muita venheitä tullut Tiberiaasta lähelle sitä paikkaa, jossa he olivat syöneet leipää, sittenkuin Herra oli lausunut kiitoksen.'),
(1695217,58,43,6,24,'Kun siis kansa näki, ettei Jeesus ollut siellä eivätkä hänen opetuslapsensa, astuivat hekin venheisiin ja menivät Kapernaumiin ja etsivät Jeesusta.'),
(1695218,58,43,6,25,'Ja kun he löysivät hänet järven toiselta puolelta, sanoivat he hänelle: "Rabbi, milloin tulit tänne?"'),
(1695219,58,43,6,26,'Jeesus vastasi heille ja sanoi: "Totisesti, totisesti minä sanon teille: ette te minua sentähden etsi, että olette nähneet tunnustekoja, vaan sentähden, että saitte syödä niitä leipiä ja tulitte ravituiksi.'),
(1695220,58,43,6,27,'Älkää hankkiko sitä ruokaa, joka katoaa, vaan sitä ruokaa, joka pysyy hamaan iankaikkiseen elämään ja jonka Ihmisen Poika on teille antava; sillä häneen on Isä, Jumala itse, sinettinsä painanut."'),
(1695221,58,43,6,28,'Niin he sanoivat hänelle: "Mitä meidän pitää tekemän, että me Jumalan tekoja tekisimme?"'),
(1695222,58,43,6,29,'Jeesus vastasi ja sanoi heille: "Se on Jumalan teko, että te uskotte häneen, jonka Jumala on lähettänyt".'),
(1695223,58,43,6,30,'He sanoivat hänelle: "Minkä tunnusteon sinä sitten teet, että me näkisimme sen ja uskoisimme sinua? Minkä teon sinä teet?'),
(1695224,58,43,6,31,'Meidän isämme söivät mannaa erämaassa, niinkuin kirjoitettu on: ''Hän antoi leipää taivaasta heille syötäväksi''."'),
(1695225,58,43,6,32,'Niin Jeesus sanoi heille: "Totisesti, totisesti minä sanon teille: ei Mooses antanut teille sitä leipää taivaasta, vaan minun Isäni antaa teille taivaasta totisen leivän.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695226,58,43,6,33,'Sillä Jumalan leipä on se, joka tulee alas taivaasta ja antaa maailmalle elämän."'),
(1695227,58,43,6,34,'Niin he sanoivat hänelle: "Herra, anna meille aina sitä leipää".'),
(1695228,58,43,6,35,'Jeesus sanoi heille: "Minä olen elämän leipä; joka tulee minun tyköni, se ei koskaan isoa, ja joka uskoo minuun, se ei koskaan janoa.'),
(1695229,58,43,6,36,'Mutta minä olen sanonut teille, että te olette nähneet minut, ettekä kuitenkaan usko.'),
(1695230,58,43,6,37,'Kaikki, minkä Isä antaa minulle, tulee minun tyköni; ja sitä, joka minun tyköni tulee, minä en heitä ulos.'),
(1695231,58,43,6,38,'Sillä minä olen tullut taivaasta, en tekemään omaa tahtoani, vaan hänen tahtonsa, joka on minut lähettänyt.'),
(1695232,58,43,6,39,'Ja minun lähettäjäni tahto on se, että minä kaikista niistä, jotka hän on minulle antanut, en kadota yhtäkään, vaan herätän heidät viimeisenä päivänä.'),
(1695233,58,43,6,40,'Sillä minun Isäni tahto on se, että jokaisella, joka näkee Pojan ja uskoo häneen, on iankaikkinen elämä; ja minä herätän hänet viimeisenä päivänä."'),
(1695234,58,43,6,41,'Niin juutalaiset nurisivat häntä vastaan, koska hän sanoi: "Minä olen se leipä, joka on tullut alas taivaasta";'),
(1695235,58,43,6,42,'ja he sanoivat: "Eikö tämä ole Jeesus, Joosefin poika, jonka isän ja äidin me tunnemme? Kuinka hän sitten sanoo: ''Minä olen tullut alas taivaasta''?"'),
(1695236,58,43,6,43,'Jeesus vastasi ja sanoi heille: "Älkää nurisko keskenänne.'),
(1695237,58,43,6,44,'Ei kukaan voi tulla minun tyköni, ellei Isä, joka on minut lähettänyt, häntä vedä; ja minä herätän hänet viimeisenä päivänä.'),
(1695238,58,43,6,45,'Profeetoissa on kirjoitettuna: ''Ja he tulevat kaikki Jumalan opettamiksi''. Jokainen, joka on Isältä kuullut ja oppinut, tulee minun tyköni.'),
(1695239,58,43,6,46,'Ei niin, että kukaan olisi Isää nähnyt; ainoastaan hän, joka on Jumalasta, on nähnyt Isän.'),
(1695240,58,43,6,47,'Totisesti, totisesti minä sanon teille: joka uskoo, sillä on iankaikkinen elämä.'),
(1695241,58,43,6,48,'Minä olen elämän leipä.'),
(1695242,58,43,6,49,'Teidän isänne söivät mannaa erämaassa, ja he kuolivat.'),
(1695243,58,43,6,50,'Mutta tämä on se leipä, joka tulee alas taivaasta, että se, joka sitä syö, ei kuolisi.'),
(1695244,58,43,6,51,'Minä olen se elävä leipä, joka on tullut alas taivaasta. Jos joku syö tätä leipää, hän elää iankaikkisesti. Ja se leipä, jonka minä annan, on minun lihani, maailman elämän puolesta."'),
(1695245,58,43,6,52,'Silloin juutalaiset riitelivät keskenään sanoen: "Kuinka tämä voi antaa lihansa meille syötäväksi?"'),
(1695246,58,43,6,53,'Niin Jeesus sanoi heille: "Totisesti, totisesti minä sanon teille: ellette syö Ihmisen Pojan lihaa ja juo hänen vertansa, ei teillä ole elämää itsessänne.'),
(1695247,58,43,6,54,'Joka syö minun lihani ja juo minun vereni, sillä on iankaikkinen elämä, ja minä herätän hänet viimeisenä päivänä.'),
(1695248,58,43,6,55,'Sillä minun lihani on totinen ruoka, ja minun vereni on totinen juoma.'),
(1695249,58,43,6,56,'Joka syö minun lihani ja juo minun vereni, se pysyy minussa, ja minä hänessä.'),
(1695250,58,43,6,57,'Niinkuin Isä, joka elää, on minut lähettänyt, ja minä elän Isän kautta, niin myös se, joka minua syö, elää minun kauttani.'),
(1695251,58,43,6,58,'Tämä on se leipä, joka tuli alas taivaasta. Ei ole, niinkuin oli teidän isienne: he söivät ja kuolivat; joka tätä leipää syö, se elää iankaikkisesti."'),
(1695252,58,43,6,59,'Tämän hän puhui synagoogassa opettaessaan Kapernaumissa.'),
(1695253,58,43,6,60,'Niin monet hänen opetuslapsistansa, sen kuultuaan, sanoivat: "Tämä on kova puhe, kuka voi sitä kuulla?"'),
(1695254,58,43,6,61,'Mutta kun Jeesus sydämessään tiesi, että hänen opetuslapsensa siitä nurisivat, sanoi hän heille: "Loukkaako tämä teitä?'),
(1695255,58,43,6,62,'Mitä sitten, jos saatte nähdä Ihmisen Pojan nousevan sinne, missä hän oli ennen!'),
(1695256,58,43,6,63,'Henki on se, joka eläväksi tekee; ei liha mitään hyödytä. Ne sanat, jotka minä olen teille puhunut, ovat henki ja ovat elämä.'),
(1695257,58,43,6,64,'Mutta teissä on muutamia, jotka eivät usko." Sillä Jeesus tiesi alusta asti, ketkä ne olivat, jotka eivät uskoneet, ja kuka se oli, joka oli kavaltava hänet.'),
(1695258,58,43,6,65,'Ja hän sanoi: "Sentähden minä olen sanonut teille, ettei kukaan voi tulla minun tyköni, ellei minun Isäni sitä hänelle anna".'),
(1695259,58,43,6,66,'Tämän tähden monet hänen opetuslapsistaan vetäytyivät pois eivätkä enää vaeltaneet hänen kanssansa.'),
(1695260,58,43,6,67,'Niin Jeesus sanoi niille kahdelletoista: "Tahdotteko tekin mennä pois?"'),
(1695261,58,43,6,68,'Simon Pietari vastasi hänelle: "Herra, kenen tykö me menisimme? Sinulla on iankaikkisen elämän sanat;'),
(1695262,58,43,6,69,'ja me uskomme ja ymmärrämme, että sinä olet Jumalan Pyhä."'),
(1695263,58,43,6,70,'Jeesus vastasi heille: "Enkö minä ole valinnut teitä, te kaksitoista? Ja yksi teistä on perkele."'),
(1695264,58,43,6,71,'Mutta sen hän sanoi Juudaasta, Simon Iskariotin pojasta; sillä tämä oli hänet kavaltava ja oli yksi niistä kahdestatoista.'),
(1695265,58,43,7,1,'Ja sen jälkeen Jeesus vaelsi ympäri Galileassa; sillä hän ei tahtonut vaeltaa Juudeassa, koska juutalaiset tavoittelivat häntä tappaaksensa.'),
(1695266,58,43,7,2,'Ja juutalaisten juhla, lehtimajanjuhla, oli lähellä.'),
(1695267,58,43,7,3,'Niin hänen veljensä sanoivat hänelle: "Lähde täältä ja mene Juudeaan, että myös sinun opetuslapsesi näkisivät sinun tekosi, joita sinä teet;'),
(1695268,58,43,7,4,'sillä ei kukaan, joka itse tahtoo tulla julki, tee mitään salassa. Koska sinä näitä tekoja teet, niin ilmoita itsesi maailmalle."'),
(1695269,58,43,7,5,'Sillä hänen veljensäkään eivät häneen uskoneet.'),
(1695270,58,43,7,6,'Niin Jeesus sanoi heille: "Minun aikani ei ole vielä tullut; mutta teille aika on aina sovelias.'),
(1695271,58,43,7,7,'Teitä ei maailma voi vihata, mutta minua se vihaa, sillä minä todistan siitä, että sen teot ovat pahat.'),
(1695272,58,43,7,8,'Menkää te ylös juhlille; minä en vielä mene näille juhlille, sillä minun aikani ei ole vielä täyttynyt.'),
(1695273,58,43,7,9,'Tämän hän sanoi heille ja jäi Galileaan.'),
(1695274,58,43,7,10,'Mutta kun hänen veljensä olivat menneet juhlille, silloin hänkin meni sinne, ei julki, vaan ikäänkuin salaa.'),
(1695275,58,43,7,11,'Niin juutalaiset etsivät häntä juhlan aikana ja sanoivat: "Missä hän on?"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695276,58,43,7,12,'Ja hänestä oli paljon kiistelyä kansassa; muutamat sanoivat: "Hän on hyvä", mutta toiset sanoivat: "Ei ole, vaan hän villitsee kansan".'),
(1695277,58,43,7,13,'Ei kuitenkaan kukaan puhunut hänestä julkisesti, koska he pelkäsivät juutalaisia.'),
(1695278,58,43,7,14,'Mutta kun jo puoli juhlaa oli kulunut, meni Jeesus ylös pyhäkköön ja opetti.'),
(1695279,58,43,7,15,'Niin juutalaiset ihmettelivät ja sanoivat: "Kuinka tämä osaa kirjoituksia, vaikkei ole oppia saanut?"'),
(1695280,58,43,7,16,'Jeesus vastasi heille ja sanoi: "Minun oppini ei ole minun, vaan hänen, joka on minut lähettänyt.'),
(1695281,58,43,7,17,'Jos joku tahtoo tehdä hänen tahtonsa, tulee hän tuntemaan, onko tämä oppi Jumalasta, vai puhunko minä omiani.'),
(1695282,58,43,7,18,'Joka omiaan puhuu, se pyytää omaa kunniaansa, mutta joka pyytää lähettäjänsä kunniaa, se on totinen, eikä hänessä ole vääryyttä.'),
(1695283,58,43,7,19,'Eikö Mooses ole antanut teille lakia? Ja kukaan teistä ei lakia täytä. Miksi tavoittelette minua tappaaksenne?"'),
(1695284,58,43,7,20,'Kansa vastasi: "Sinussa on riivaaja; kuka sinua tavoittelee tappaaksensa?"'),
(1695285,58,43,7,21,'Jeesus vastasi ja sanoi heille: "Yhden teon minä tein, ja te kaikki kummastelette.'),
(1695286,58,43,7,22,'Mooses antoi teille ympärileikkauksen - ei niin, että se olisi Moosekselta, vaan se on isiltä - ja sapattinakin te ympärileikkaatte ihmisen.'),
(1695287,58,43,7,23,'Sentähden: jos ihminen saa ympärileikkauksen sapattina, ettei Mooseksen lakia rikottaisi, miksi te olette vihoissanne minulle siitä, että minä tein koko ihmisen terveeksi sapattina?'),
(1695288,58,43,7,24,'Älkää tuomitko näön mukaan, vaan tuomitkaa oikea tuomio."'),
(1695289,58,43,7,25,'Niin muutamat jerusalemilaisista sanoivat: "Eikö tämä ole se, jota he tavoittelevat tappaaksensa?'),
(1695290,58,43,7,26,'Ja katso, hän puhuu vapaasti, eivätkä he sano hänelle mitään. Olisivatko hallitusmiehet tosiaan saaneet tietoonsa, että tämä on Kristus?'),
(1695291,58,43,7,27,'Kuitenkin, me tiedämme, mistä tämä on; mutta kun Kristus tulee, niin ei kukaan tiedä, mistä hän on."'),
(1695292,58,43,7,28,'Niin Jeesus puhui pyhäkössä suurella äänellä, opetti ja sanoi: "Te tunnette minut ja tiedätte, mistä minä olen; ja itsestäni minä en ole tullut, vaan hän, joka minut on lähettänyt, on oikea lähettäjä, ja häntä te ette tunne.'),
(1695293,58,43,7,29,'Minä tunnen hänet, sillä hänestä minä olen, ja hän on minut lähettänyt."'),
(1695294,58,43,7,30,'Niin heillä oli halu ottaa hänet kiinni; mutta ei kukaan käynyt häneen käsiksi, sillä hänen hetkensä ei ollut vielä tullut.'),
(1695295,58,43,7,31,'Mutta monet kansasta uskoivat häneen ja sanoivat: "Kun Kristus tulee, tehneekö hän enemmän tunnustekoja, kuin tämä on tehnyt?"'),
(1695296,58,43,7,32,'Fariseukset kuulivat kansan näin kiistelevän hänestä; niin ylipapit ja fariseukset lähettivät palvelijoita ottamaan häntä kiinni.'),
(1695297,58,43,7,33,'Mutta Jeesus sanoi: "Minä olen vielä vähän aikaa teidän kanssanne, ja sitten minä menen pois hänen tykönsä, joka on minut lähettänyt.'),
(1695298,58,43,7,34,'Silloin te etsitte minua, mutta ette löydä; ja missä minä olen, sinne te ette voi tulla."'),
(1695299,58,43,7,35,'Niin juutalaiset sanoivat keskenään: "Minne tämä aikoo mennä, koska emme voi löytää häntä? Eihän vain aikone mennä niiden luo, jotka asuvat hajallaan kreikkalaisten keskellä, ja opettaa kreikkalaisia?'),
(1695300,58,43,7,36,'Mitä tämä sana on, jonka hän sanoi: ''Te etsitte minua, mutta ette löydä'', ja: ''Missä minä olen, sinne te ette voi tulla''?"'),
(1695301,58,43,7,37,'Mutta juhlan viimeisenä, suurena päivänä Jeesus seisoi ja huusi ja sanoi: "Jos joku janoaa, niin tulkoon minun tyköni ja juokoon.'),
(1695302,58,43,7,38,'Joka uskoo minuun, hänen sisimmästään on, niinkuin Raamattu sanoo, juokseva elävän veden virrat."'),
(1695303,58,43,7,39,'Mutta sen hän sanoi Hengestä, joka niiden piti saaman, jotka uskoivat häneen; sillä Henki ei ollut vielä tullut, koska Jeesus ei vielä ollut kirkastettu.'),
(1695304,58,43,7,40,'Niin muutamat kansasta, kuultuaan nämä sanat, sanoivat: "Tämä on totisesti se profeetta".'),
(1695305,58,43,7,41,'Toiset sanoivat: "Tämä on Kristus". Mutta toiset sanoivat: "Ei suinkaan Kristus tule Galileasta?'),
(1695306,58,43,7,42,'Eikö Raamattu sano, että Kristus on oleva Daavidin jälkeläisiä ja tuleva pienestä Beetlehemin kaupungista, jossa Daavid oli?"'),
(1695307,58,43,7,43,'Niin syntyi kansassa eripuraisuutta hänen tähtensä.'),
(1695308,58,43,7,44,'Ja muutamat heistä tahtoivat ottaa hänet kiinni. Mutta ei kukaan käynyt häneen käsiksi.'),
(1695309,58,43,7,45,'Niin palvelijat palasivat ylipappien ja fariseusten luo, ja nämä sanoivat heille: "Miksi ette tuoneet häntä tänne?"'),
(1695310,58,43,7,46,'Palvelijat vastasivat: "Ei ole koskaan ihminen puhunut niin, kuin se mies puhuu".'),
(1695311,58,43,7,47,'Niin fariseukset vastasivat heille: "Oletteko tekin eksytetyt?'),
(1695312,58,43,7,48,'Onko kukaan hallitusmiehistä uskonut häneen tai kukaan fariseuksista?'),
(1695313,58,43,7,49,'Mutta tuo kansa, joka ei lakia tunne, on kirottu."'),
(1695314,58,43,7,50,'Niin Nikodeemus, joka ennen oli käynyt Jeesuksen luona ja joka oli yksi heistä, sanoi heille:'),
(1695315,58,43,7,51,'"Tuomitseeko lakimme ketään, ennenkuin häntä on kuulusteltu ja saatu tietää, mitä hän on tehnyt?"'),
(1695316,58,43,7,52,'He vastasivat ja sanoivat hänelle: "Oletko sinäkin Galileasta? Tutki ja näe, ettei Galileasta nouse profeettaa."'),
(1695317,58,43,7,53,'Ja he menivät kukin kotiinsa.'),
(1695318,58,43,8,1,'Mutta Jeesus meni Öljymäelle.'),
(1695319,58,43,8,2,'Ja varhain aamulla hän taas saapui pyhäkköön, ja kaikki kansa tuli hänen luoksensa; ja hän istuutui ja opetti heitä.'),
(1695320,58,43,8,3,'Silloin kirjanoppineet ja fariseukset toivat hänen luoksensa aviorikoksesta kiinniotetun naisen, asettivat hänet keskelle'),
(1695321,58,43,8,4,'ja sanoivat Jeesukselle: "Opettaja, tämä nainen on tavattu itse teosta, aviorikosta tekemästä.'),
(1695322,58,43,8,5,'Ja Mooses on laissa antanut meille käskyn, että tuommoiset on kivitettävä. Mitäs sinä sanot?"'),
(1695323,58,43,8,6,'Mutta sen he sanoivat kiusaten häntä, päästäkseen häntä syyttämään. Silloin Jeesus kumartui alas ja kirjoitti sormellaan maahan.'),
(1695324,58,43,8,7,'Mutta kun he yhä edelleen kysyivät häneltä, ojensi hän itsensä ja sanoi heille: "Joka teistä on synnitön, se heittäköön häntä ensimmäisenä kivellä".'),
(1695325,58,43,8,8,'Ja taas hän kumartui alas ja kirjoitti maahan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695326,58,43,8,9,'Kun he tämän kuulivat ja heidän omatuntonsa todisti heidät syyllisiksi, menivät he pois, toinen toisensa perästä, vanhimmista alkaen viimeisiin asti; ja siihen jäi ainoastaan Jeesus sekä nainen, joka seisoi hänen edessään.'),
(1695327,58,43,8,10,'Ja kun Jeesus ojensi itsensä eikä nähnyt ketään muuta kuin naisen, sanoi hän hänelle: "Nainen, missä ne ovat, sinun syyttäjäsi? Eikö kukaan ole sinua tuominnut?"'),
(1695328,58,43,8,11,'Hän vastasi: "Herra, ei kukaan". Niin Jeesus sanoi hänelle: "En minäkään sinua tuomitse; mene, äläkä tästedes enää syntiä tee".'),
(1695329,58,43,8,12,'Niin Jeesus taas puhui heille sanoen: "Minä olen maailman valkeus; joka minua seuraa, se ei pimeydessä vaella, vaan hänellä on oleva elämän valkeus".'),
(1695330,58,43,8,13,'Niin fariseukset sanoivat hänelle: "Sinä todistat itsestäsi; sinun todistuksesi ei ole pätevä".'),
(1695331,58,43,8,14,'Jeesus vastasi ja sanoi heille: "Vaikka minä todistankin itsestäni, on todistukseni pätevä, sillä minä tiedän, mistä minä olen tullut ja mihin minä menen; mutta te ette tiedä, mistä minä tulen, ettekä, mihin minä menen.'),
(1695332,58,43,8,15,'Te tuomitsette lihan mukaan; minä en tuomitse ketään.'),
(1695333,58,43,8,16,'Ja vaikka minä tuomitsisinkin, niin minun tuomioni olisi oikea, sillä minä en ole yksinäni, vaan minä ja hän, joka on minut lähettänyt.'),
(1695334,58,43,8,17,'Onhan teidän laissannekin kirjoitettuna, että kahden ihmisen todistus on pätevä.'),
(1695335,58,43,8,18,'Minä olen se, joka todistan itsestäni, ja minusta todistaa myös Isä, joka on minut lähettänyt."'),
(1695336,58,43,8,19,'Niin he sanoivat hänelle: "Missä sinun isäsi on?" Jeesus vastasi: "Te ette tunne minua ettekä minun Isääni; jos te tuntisitte minut, niin te tuntisitte myös minun Isäni".'),
(1695337,58,43,8,20,'Nämä sanat Jeesus puhui uhriarkun ääressä, opettaessaan pyhäkössä; eikä kukaan ottanut häntä kiinni, sillä hänen hetkensä ei ollut vielä tullut.'),
(1695338,58,43,8,21,'Niin Jeesus taas sanoi heille: "Minä menen pois, ja te etsitte minua, ja te kuolette syntiinne. Mihin minä menen, sinne te ette voi tulla."'),
(1695339,58,43,8,22,'Niin juutalaiset sanoivat: "Ei kai hän aikone tappaa itseänsä, koska sanoo: ''Mihin minä menen, sinne te ette voi tulla''?"'),
(1695340,58,43,8,23,'Ja hän sanoi heille: "Te olette alhaalta, minä olen ylhäältä; te olette tästä maailmasta, minä en ole tästä maailmasta.'),
(1695341,58,43,8,24,'Sentähden minä sanoin teille, että te kuolette synteihinne; sillä ellette usko minua siksi, joka minä olen, niin te kuolette synteihinne."'),
(1695342,58,43,8,25,'Niin he sanoivat hänelle: "Kuka sinä olet?" Jeesus sanoi heille: "Juuri se, mitä minä puhunkin teille.'),
(1695343,58,43,8,26,'Paljon on minulla teistä puhuttavaa ja teissä tuomittavaa; mutta hän, joka on minut lähettänyt, on totinen, ja minkä minä olen kuullut häneltä, sen minä puhun maailman kuulla."'),
(1695344,58,43,8,27,'Mutta he eivät ymmärtäneet, että hän puhui heille Isästä.'),
(1695345,58,43,8,28,'Niin Jeesus sanoi heille: "Kun olette ylentäneet Ihmisen Pojan, silloin te ymmärrätte, että minä olen se, joka minä olen, ja etten minä itsestäni tee mitään, vaan puhun tätä sen mukaan, kuin minun Isäni on minulle opettanut.'),
(1695346,58,43,8,29,'Ja hän, joka on minut lähettänyt, on minun kanssani; hän ei ole jättänyt minua yksinäni, koska minä aina teen sitä, mikä hänelle on otollista."'),
(1695347,58,43,8,30,'Kun hän näin puhui, uskoivat monet häneen.'),
(1695348,58,43,8,31,'Niin Jeesus sanoi niille juutalaisille, jotka uskoivat häneen: "Jos te pysytte minun sanassani, niin te totisesti olette minun opetuslapsiani;'),
(1695349,58,43,8,32,'ja te tulette tuntemaan totuuden, ja totuus on tekevä teidät vapaiksi".'),
(1695350,58,43,8,33,'He vastasivat hänelle: "Me olemme Aabrahamin jälkeläisiä emmekä ole koskaan olleet kenenkään orjia. Kuinka sinä sitten sanot: ''Te tulette vapaiksi''?"'),
(1695351,58,43,8,34,'Jeesus vastasi heille: "Totisesti, totisesti minä sanon teille: jokainen, joka tekee syntiä, on synnin orja.'),
(1695352,58,43,8,35,'Mutta orja ei pysy talossa iäti; Poika pysyy iäti.'),
(1695353,58,43,8,36,'Jos siis Poika tekee teidät vapaiksi, niin te tulette todellisesti vapaiksi.'),
(1695354,58,43,8,37,'Minä tiedän, että te olette Aabrahamin jälkeläisiä; mutta te tavoittelette minua tappaaksenne, koska minun sanani ei saa tilaa teissä.'),
(1695355,58,43,8,38,'Minä puhun, mitä minä olen nähnyt Isäni tykönä; niin tekin teette, mitä olette kuulleet omalta isältänne."'),
(1695356,58,43,8,39,'He vastasivat ja sanoivat hänelle: "Aabraham on meidän isämme". Jeesus sanoi heille: "Jos olisitte Aabrahamin lapsia, niin te tekisitte Aabrahamin tekoja.'),
(1695357,58,43,8,40,'Mutta nyt te tavoittelette minua tappaaksenne, miestä, joka on puhunut teille totuuden, jonka hän on kuullut Jumalalta. Niin ei Aabraham tehnyt.'),
(1695358,58,43,8,41,'Te teette isänne tekoja." He sanoivat hänelle: "Me emme ole aviorikoksesta syntyneitä; meillä on yksi Isä, Jumala".'),
(1695359,58,43,8,42,'Jeesus sanoi heille: "Jos Jumala olisi teidän Isänne, niin te rakastaisitte minua, sillä minä olen Jumalasta lähtenyt ja tullut; en minä ole itsestäni tullut, vaan hän on minut lähettänyt.'),
(1695360,58,43,8,43,'Minkätähden te ette ymmärrä minun puhettani? Sentähden, että te ette kärsi kuulla minun sanaani.'),
(1695361,58,43,8,44,'Te olette isästä perkeleestä, ja isänne himoja te tahdotte noudattaa. Hän on ollut murhaaja alusta asti, ja totuudessa hän ei pysy, koska hänessä ei totuutta ole. Kun hän puhuu valhetta, niin hän puhuu omaansa, sillä hän on valhettelija ja sen isä.'),
(1695362,58,43,8,45,'Mutta minua te ette usko, sentähden että minä sanon totuuden.'),
(1695363,58,43,8,46,'Kuka teistä voi näyttää minut syypääksi syntiin? Jos minä totuutta puhun, miksi ette minua usko?'),
(1695364,58,43,8,47,'Joka on Jumalasta, se kuulee Jumalan sanat. Sentähden te ette kuule, koska ette ole Jumalasta."'),
(1695365,58,43,8,48,'Niin juutalaiset vastasivat ja sanoivat hänelle: "Emmekö ole oikeassa, kun sanomme, että sinä olet samarialainen ja että sinussa on riivaaja?"'),
(1695366,58,43,8,49,'Jeesus vastasi: "Minussa ei ole riivaajaa, vaan minä kunnioitan Isääni, ja te häpäisette minua.'),
(1695367,58,43,8,50,'Mutta minä en etsi omaa kunniaani; yksi on, joka etsii ja tuomitsee.'),
(1695368,58,43,8,51,'Totisesti, totisesti minä sanon teille: jos joku pitää minun sanani, hän ei ikinä näe kuolemaa."'),
(1695369,58,43,8,52,'Juutalaiset sanoivat hänelle: "Nyt me ymmärrämme, että sinussa on riivaaja. Aabraham on kuollut ja profeetat, ja sinä sanot: ''Jos joku pitää minun sanani, hän ei ikinä maista kuolemaa''.'),
(1695370,58,43,8,53,'Oletko sinä suurempi kuin isämme Aabraham, joka on kuollut? Ja profeetat ovat kuolleet; keneksi sinä itsesi teet?"'),
(1695371,58,43,8,54,'Jeesus vastasi: "Jos minä itse itselleni otan kunnian, niin minun kunniani ei ole mitään. Minun Isäni on se, joka minulle kunnian antaa, hän, josta te sanotte: ''Hän on meidän Jumalamme'','),
(1695372,58,43,8,55,'ettekä tunne häntä; mutta minä tunnen hänet. Ja jos sanoisin, etten tunne häntä, niin minä olisin valhettelija niinkuin tekin; mutta minä tunnen hänet ja pidän hänen sanansa.'),
(1695373,58,43,8,56,'Aabraham, teidän isänne, riemuitsi siitä, että hän oli näkevä minun päiväni; ja hän näki sen ja iloitsi."'),
(1695374,58,43,8,57,'Niin juutalaiset sanoivat hänelle: "Et ole vielä viidenkymmenen vuoden vanha, ja olet nähnyt Aabrahamin!"'),
(1695375,58,43,8,58,'Jeesus sanoi heille: "Totisesti, totisesti minä sanon teille: ennenkuin Aabraham syntyi, olen minä ollut".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695376,58,43,8,59,'Silloin he poimivat kiviä heittääksensä häntä niillä; mutta Jeesus lymysi ja lähti pyhäköstä.'),
(1695377,58,43,9,1,'Ja ohi kulkiessaan hän näki miehen, joka syntymästään saakka oli ollut sokea.'),
(1695378,58,43,9,2,'Ja hänen opetuslapsensa kysyivät häneltä sanoen: "Rabbi, kuka teki syntiä, tämäkö vai hänen vanhempansa, että hänen piti sokeana syntymän?"'),
(1695379,58,43,9,3,'Jeesus vastasi: "Ei tämä tehnyt syntiä eivätkä hänen vanhempansa, vaan Jumalan tekojen piti tuleman hänessä julki.'),
(1695380,58,43,9,4,'Niin kauan kuin päivä on, tulee meidän tehdä hänen tekojansa, joka on minut lähettänyt; tulee yö, jolloin ei kukaan voi työtä tehdä.'),
(1695381,58,43,9,5,'Niin kauan kuin minä maailmassa olen, olen minä maailman valkeus."'),
(1695382,58,43,9,6,'Tämän sanottuaan hän sylki maahan ja teki syljestä tahtaan ja siveli tahtaan hänen silmilleen'),
(1695383,58,43,9,7,'ja sanoi hänelle: "Mene ja peseydy Siiloan lammikossa" - se on käännettynä: lähetetty. - Niin hän meni ja peseytyi ja palasi näkevänä.'),
(1695384,58,43,9,8,'Silloin naapurit ja ne, jotka ennen olivat nähneet hänet kerjääjänä, sanoivat: "Eikö tämä ole se, joka istui ja kerjäsi?"'),
(1695385,58,43,9,9,'Toiset sanoivat: "Hän se on", toiset sanoivat: "Ei ole, vaan hän on hänen näköisensä". Hän itse sanoi: "Minä se olen".'),
(1695386,58,43,9,10,'Niin he sanoivat hänelle: "Miten sinun silmäsi ovat auenneet?"'),
(1695387,58,43,9,11,'Hän vastasi: "Se mies, jota kutsutaan Jeesukseksi, teki tahtaan ja voiteli minun silmäni ja sanoi minulle: ''Mene ja peseydy Siiloan lammikossa''; niin minä menin ja peseydyin ja sain näköni".'),
(1695388,58,43,9,12,'He sanoivat hänelle: "Missä hän on?" Hän vastasi: "En tiedä".'),
(1695389,58,43,9,13,'Niin he veivät hänet, joka ennen oli ollut sokea, fariseusten luo.'),
(1695390,58,43,9,14,'Ja se päivä, jona Jeesus teki tahtaan ja avasi hänen silmänsä, oli sapatti.'),
(1695391,58,43,9,15,'Niin myöskin fariseukset kysyivät häneltä, miten hän oli saanut näkönsä. Ja hän sanoi heille: "Hän siveli tahtaan minun silmilleni, ja minä peseydyin, ja nyt minä näen".'),
(1695392,58,43,9,16,'Niin muutamat fariseuksista sanoivat: "Se mies ei ole Jumalasta, koska hän ei pidä sapattia". Toiset sanoivat: "Kuinka voi syntinen ihminen tehdä senkaltaisia tunnustekoja?" Ja he olivat keskenänsä eri mieltä.'),
(1695393,58,43,9,17,'Niin he taas sanoivat sokealle: "Mitä sinä sanot hänestä, koskapa hän avasi sinun silmäsi?" Ja hän sanoi: "Hän on profeetta".'),
(1695394,58,43,9,18,'Mutta juutalaiset eivät uskoneet hänestä, että hän oli ollut sokea ja saanut näkönsä, ennenkuin kutsuivat sen näkönsä saaneen vanhemmat'),
(1695395,58,43,9,19,'ja kysyivät heiltä sanoen: "Onko tämä teidän poikanne, jonka sanotte sokeana syntyneen? Kuinka hän sitten nyt näkee?"'),
(1695396,58,43,9,20,'Hänen vanhempansa vastasivat ja sanoivat: "Me tiedämme, että tämä on meidän poikamme ja että hän on sokeana syntynyt;'),
(1695397,58,43,9,21,'mutta kuinka hän nyt näkee, emme tiedä; emme myöskään tiedä, kuka on avannut hänen silmänsä. Kysykää häneltä; hänellä on kyllin ikää, puhukoon itse puolestansa."'),
(1695398,58,43,9,22,'Näin hänen vanhempansa sanoivat, koska pelkäsivät juutalaisia. Sillä juutalaiset olivat jo sopineet keskenään, että se, joka tunnusti hänet Kristukseksi, oli erotettava synagoogasta.'),
(1695399,58,43,9,23,'Sentähden hänen vanhempansa sanoivat: "Hänellä on kyllin ikää, kysykää häneltä".'),
(1695400,58,43,9,24,'Niin he kutsuivat toistamiseen miehen, joka oli ollut sokea, ja sanoivat hänelle: "Anna kunnia Jumalalle; me tiedämme, että se mies on syntinen".'),
(1695401,58,43,9,25,'Hän vastasi: "Onko hän syntinen, sitä en tiedä; sen vain tiedän, että minä, joka olin sokea, nyt näen".'),
(1695402,58,43,9,26,'Niin he sanoivat hänelle: "Mitä hän sinulle teki? Miten hän avasi sinun silmäsi?"'),
(1695403,58,43,9,27,'Hän vastasi heille: "Johan minä teille sanoin, ettekä te kuulleet. Miksi taas tahdotte sitä kuulla? Tahdotteko tekin ruveta hänen opetuslapsiksensa?"'),
(1695404,58,43,9,28,'Niin he herjasivat häntä ja sanoivat: "Sinä olet hänen opetuslapsensa, mutta me olemme Mooseksen opetuslapsia.'),
(1695405,58,43,9,29,'Me tiedämme Jumalan puhuneen Moosekselle, mutta mistä tämä on, sitä emme tiedä."'),
(1695406,58,43,9,30,'Mies vastasi ja sanoi heille: "Sehän tässä on ihmeellistä, että te ette tiedä, mistä hän on, ja kuitenkin hän on avannut minun silmäni.'),
(1695407,58,43,9,31,'Me tiedämme, ettei Jumala kuule syntisiä; vaan joka on jumalaapelkääväinen ja tekee hänen tahtonsa, sitä hän kuulee.'),
(1695408,58,43,9,32,'Ei ole maailman alusta kuultu, että kukaan on avannut sokeana syntyneen silmät.'),
(1695409,58,43,9,33,'Jos hän ei olisi Jumalasta, ei hän voisi mitään tehdä."'),
(1695410,58,43,9,34,'He vastasivat ja sanoivat hänelle: "Sinä olet kokonaan synneissä syntynyt, ja sinä tahdot opettaa meitä!" Ja he ajoivat hänet ulos.'),
(1695411,58,43,9,35,'Ja Jeesus sai kuulla heidän ajaneen hänet ulos; ja hänet tavatessaan hän sanoi hänelle: "Uskotko sinä Jumalan Poikaan?"'),
(1695412,58,43,9,36,'Hän vastasi ja sanoi: "Herra, kuka hän on, että minä häneen uskoisin?"'),
(1695413,58,43,9,37,'Jeesus sanoi hänelle: "Sinä olet hänet nähnyt, ja hän on se, joka sinun kanssasi puhuu".'),
(1695414,58,43,9,38,'Niin hän sanoi: "Herra, minä uskon"; ja hän kumartaen rukoili häntä.'),
(1695415,58,43,9,39,'Ja Jeesus sanoi: "Tuomioksi minä olen tullut tähän maailmaan, että ne, jotka eivät näe, näkisivät, ja ne, jotka näkevät, tulisivat sokeiksi".'),
(1695416,58,43,9,40,'Ja muutamat fariseukset, jotka olivat siinä häntä lähellä, kuulivat tämän ja sanoivat hänelle: "Olemmeko mekin sokeat?"'),
(1695417,58,43,9,41,'Jeesus sanoi heille: "Jos te olisitte sokeat, ei teillä olisi syntiä; mutta nyt te sanotte: ''Me näemme''; sentähden teidän syntinne pysyy".'),
(1695418,58,43,10,1,'"Totisesti, totisesti minä sanon teille: joka ei mene ovesta lammastarhaan, vaan nousee sinne muualta, se on varas ja ryöväri.'),
(1695419,58,43,10,2,'Mutta joka menee ovesta sisälle, se on lammasten paimen.'),
(1695420,58,43,10,3,'Hänelle ovenvartija avaa, ja lampaat kuulevat hänen ääntänsä; ja hän kutsuu omat lampaansa nimeltä ja vie heidät ulos.'),
(1695421,58,43,10,4,'Ja laskettuaan kaikki omansa ulos hän kulkee niiden edellä, ja lampaat seuraavat häntä, sillä ne tuntevat hänen äänensä.'),
(1695422,58,43,10,5,'Mutta vierasta ne eivät seuraa, vaan pakenevat häntä, koska eivät tunne vierasten ääntä."'),
(1695423,58,43,10,6,'Tämän kuvauksen Jeesus puhui heille; mutta he eivät ymmärtäneet, mitä hänen puheensa tarkoitti.'),
(1695424,58,43,10,7,'Niin Jeesus vielä sanoi heille: "Totisesti, totisesti minä sanon teille: minä olen lammasten ovi.'),
(1695425,58,43,10,8,'Kaikki, jotka ovat tulleet ennen minua, ovat varkaita ja ryöväreitä; mutta lampaat eivät ole heitä kuulleet.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695426,58,43,10,9,'Minä olen ovi; jos joku minun kauttani menee sisälle, niin hän pelastuu, ja hän on käyvä sisälle ja käyvä ulos ja löytävä laitumen.'),
(1695427,58,43,10,10,'Varas ei tule muuta kuin varastamaan ja tappamaan ja tuhoamaan. Minä olen tullut, että heillä olisi elämä ja olisi yltäkylläisyys.'),
(1695428,58,43,10,11,'Minä olen se hyvä paimen. Hyvä paimen antaa henkensä lammasten edestä.'),
(1695429,58,43,10,12,'Mutta palkkalainen, joka ei ole paimen ja jonka omia lampaat eivät ole, kun hän näkee suden tulevan, niin hän jättää lampaat ja pakenee; ja susi ryöstää ja hajottaa ne.'),
(1695430,58,43,10,13,'Hän pakenee, sillä hän on palkattu eikä välitä lampaista.'),
(1695431,58,43,10,14,'Minä olen se hyvä paimen, ja minä tunnen omani, ja minun omani tuntevat minut,'),
(1695432,58,43,10,15,'niinkuin Isä tuntee minut ja minä tunnen Isän; ja minä annan henkeni lammasten edestä.'),
(1695433,58,43,10,16,'Minulla on myös muita lampaita, jotka eivät ole tästä lammastarhasta; myös niitä tulee minun johdattaa, ja ne saavat kuulla minun ääneni, ja on oleva yksi lauma ja yksi paimen.'),
(1695434,58,43,10,17,'Sentähden Isä minua rakastaa, koska minä annan henkeni, että minä sen jälleen ottaisin.'),
(1695435,58,43,10,18,'Ei kukaan sitä minulta ota, vaan minä annan sen itsestäni. Minulla on valta antaa se, ja minulla on valta ottaa se jälleen; sen käskyn minä olen saanut Isältäni."'),
(1695436,58,43,10,19,'Niin syntyi taas erimielisyys juutalaisten kesken näiden sanain tähden.'),
(1695437,58,43,10,20,'Ja useat heistä sanoivat: "Hänessä on riivaaja, ja hän on järjiltään; mitä te häntä kuuntelette?"'),
(1695438,58,43,10,21,'Toiset sanoivat: "Nämä eivät ole riivatun sanoja; eihän riivaaja voi avata sokeain silmiä?"'),
(1695439,58,43,10,22,'Sitten oli temppelin vihkimisen muistojuhla Jerusalemissa, ja oli talvi.'),
(1695440,58,43,10,23,'Ja Jeesus käyskeli pyhäkössä, Salomon pylväskäytävässä.'),
(1695441,58,43,10,24,'Niin juutalaiset ympäröivät hänet ja sanoivat hänelle: "Kuinka kauan sinä pidät meidän mieltämme kiihdyksissä? Jos sinä olet Kristus, niin sano se meille suoraan."'),
(1695442,58,43,10,25,'Jeesus vastasi heille: "Minä olen sanonut sen teille, ja te ette usko. Ne teot, joita minä teen Isäni nimessä, ne todistavat minusta.'),
(1695443,58,43,10,26,'Mutta te ette usko, sillä te ette ole minun lampaitani.'),
(1695444,58,43,10,27,'Minun lampaani kuulevat minun ääntäni, ja minä tunnen ne, ja ne seuraavat minua.'),
(1695445,58,43,10,28,'Ja minä annan heille iankaikkisen elämän, ja he eivät ikinä huku, eikä kukaan ryöstä heitä minun kädestäni.'),
(1695446,58,43,10,29,'Minun Isäni, joka on heidät minulle antanut, on suurempi kaikkia, eikä kukaan voi ryöstää heitä minun Isäni kädestä.'),
(1695447,58,43,10,30,'Minä ja Isä olemme yhtä."'),
(1695448,58,43,10,31,'Niin juutalaiset ottivat taas kiviä maasta kivittääksensä hänet.'),
(1695449,58,43,10,32,'Jeesus vastasi heille: "Minä olen näyttänyt teille monta hyvää tekoa, jotka ovat Isästä; mikä niistä on se, jonka tähden te tahdotte minut kivittää?"'),
(1695450,58,43,10,33,'Juutalaiset vastasivat hänelle: "Hyvän teon tähden me emme sinua kivitä, vaan jumalanpilkan tähden, ja koska sinä, joka olet ihminen, teet itsesi Jumalaksi".'),
(1695451,58,43,10,34,'Jeesus vastasi heille: "Eikö teidän laissanne ole kirjoitettuna: ''Minä sanoin: te olette jumalia''?'),
(1695452,58,43,10,35,'Jos hän sanoo jumaliksi niitä, joille Jumalan sana tuli - ja Raamattu ei voi raueta tyhjiin -'),
(1695453,58,43,10,36,'niin kuinka te sanotte sille, jonka Isä on pyhittänyt ja lähettänyt maailmaan: ''Sinä pilkkaat Jumalaa'', sentähden että minä sanoin: ''Minä olen Jumalan Poika''?'),
(1695454,58,43,10,37,'Jos minä en tee Isäni tekoja, älkää uskoko minua.'),
(1695455,58,43,10,38,'Mutta jos minä niitä teen, niin, vaikka ette uskoisikaan minua, uskokaa minun tekojani, että tulisitte tuntemaan ja ymmärtäisitte Isän olevan minussa ja minun olevan Isässä."'),
(1695456,58,43,10,39,'Niin he taas tahtoivat ottaa hänet kiinni, mutta hän lähti pois heidän käsistänsä.'),
(1695457,58,43,10,40,'Ja hän meni taas Jordanin tuolle puolelle siihen paikkaan, missä Johannes ensin kastoi, ja viipyi siellä.'),
(1695458,58,43,10,41,'Ja monet tulivat hänen tykönsä ja sanoivat: "Johannes ei tehnyt yhtäkään tunnustekoa; mutta kaikki, mitä Johannes sanoi tästä, on totta".'),
(1695459,58,43,10,42,'Ja monet siellä uskoivat häneen.'),
(1695460,58,43,11,1,'Ja eräs mies, Lasarus, Betaniasta, Marian ja hänen sisarensa Martan kylästä, oli sairaana.'),
(1695461,58,43,11,2,'Ja tämä Maria oli se, joka hajuvoiteella voiteli Herran ja pyyhki hiuksillaan hänen jalkansa; ja Lasarus, joka sairasti, oli hänen veljensä.'),
(1695462,58,43,11,3,'Niin sisaret lähettivät Jeesukselle tämän sanan: "Herra, katso, se, joka on sinulle rakas, sairastaa".'),
(1695463,58,43,11,4,'Mutta sen kuultuaan Jeesus sanoi: "Ei tämä tauti ole kuolemaksi, vaan Jumalan kunniaksi, että Jumalan Poika sen kautta kirkastuisi".'),
(1695464,58,43,11,5,'Ja Jeesus rakasti Marttaa ja hänen sisartaan ja Lasarusta.'),
(1695465,58,43,11,6,'Kun hän siis kuuli hänen sairastavan, viipyi hän siinä paikassa, missä hän oli, vielä kaksi päivää;'),
(1695466,58,43,11,7,'mutta niiden kuluttua hän sanoi opetuslapsilleen: "Menkäämme taas Juudeaan".'),
(1695467,58,43,11,8,'Opetuslapset sanoivat hänelle: "Rabbi, äsken juutalaiset yrittivät kivittää sinut, ja taas sinä menet sinne!"'),
(1695468,58,43,11,9,'Jeesus vastasi: "Eikö päivässä ole kaksitoista hetkeä? Joka vaeltaa päivällä, se ei loukkaa itseänsä, sillä hän näkee tämän maailman valon.'),
(1695469,58,43,11,10,'Mutta joka vaeltaa yöllä, se loukkaa itsensä, sillä ei hänessä ole valoa."'),
(1695470,58,43,11,11,'Näin hän puhui, ja sitten hän sanoi heille: "Ystävämme Lasarus nukkuu, mutta minä menen herättämään hänet unesta".'),
(1695471,58,43,11,12,'Niin opetuslapset sanoivat hänelle: "Herra, jos hän nukkuu, niin hän tulee terveeksi".'),
(1695472,58,43,11,13,'Mutta Jeesus puhui hänen kuolemastaan; he taas luulivat hänen puhuneen unessa-nukkumisesta.'),
(1695473,58,43,11,14,'Silloin Jeesus sanoi heille suoraan: "Lasarus on kuollut,'),
(1695474,58,43,11,15,'ja minä iloitsen teidän tähtenne siitä, etten ollut siellä, jotta te uskoisitte; mutta menkäämme hänen tykönsä".'),
(1695475,58,43,11,16,'Niin Tuomas, jota sanottiin Didymukseksi, sanoi toisille opetuslapsille: "Menkäämme mekin sinne, kuollaksemme hänen kanssansa".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695476,58,43,11,17,'Niin Jeesus tuli ja sai tietää, että hän jo neljä päivää oli ollut haudassa.'),
(1695477,58,43,11,18,'Ja Betania oli lähellä Jerusalemia, noin viidentoista vakomitan päässä.'),
(1695478,58,43,11,19,'Ja useita juutalaisia oli tullut Martan ja Marian luokse lohduttamaan heitä heidän veljensä kuolemasta.'),
(1695479,58,43,11,20,'Kun Martta kuuli, että Jeesus oli tulossa, meni hän häntä vastaan; mutta Maria istui kotona.'),
(1695480,58,43,11,21,'Ja Martta sanoi Jeesukselle: "Herra, jos sinä olisit ollut täällä, niin minun veljeni ei olisi kuollut.'),
(1695481,58,43,11,22,'Mutta nytkin minä tiedän, että Jumala antaa sinulle kaiken, mitä sinä Jumalalta anot."'),
(1695482,58,43,11,23,'Jeesus sanoi hänelle: "Sinun veljesi on nouseva ylös".'),
(1695483,58,43,11,24,'Martta sanoi hänelle: "Minä tiedän hänen nousevan ylösnousemuksessa, viimeisenä päivänä".'),
(1695484,58,43,11,25,'Jeesus sanoi hänelle: "Minä olen ylösnousemus ja elämä; joka uskoo minuun, se elää, vaikka olisi kuollut.'),
(1695485,58,43,11,26,'Eikä yksikään, joka elää ja uskoo minuun, ikinä kuole. Uskotko sen?"'),
(1695486,58,43,11,27,'Hän sanoi hänelle: "Uskon, Herra; minä uskon, että sinä olet Kristus, Jumalan Poika, se, joka oli tuleva maailmaan".'),
(1695487,58,43,11,28,'Ja tämän sanottuaan hän meni ja kutsui salaa sisarensa Marian sanoen: "Opettaja on täällä ja kutsuu sinua".'),
(1695488,58,43,11,29,'Kun Maria sen kuuli, nousi hän nopeasti ja meni hänen luoksensa.'),
(1695489,58,43,11,30,'Mutta Jeesus ei ollut vielä saapunut kylään, vaan oli yhä siinä paikassa, missä Martta oli hänet kohdannut.'),
(1695490,58,43,11,31,'Kun nyt juutalaiset, jotka olivat Marian kanssa huoneessa häntä lohduttamassa, näkivät hänen nopeasti nousevan ja lähtevän ulos, seurasivat he häntä, luullen hänen menevän haudalle, itkemään siellä.'),
(1695491,58,43,11,32,'Kun siis Maria saapui sinne, missä Jeesus oli, ja näki hänet, lankesi hän hänen jalkojensa eteen ja sanoi hänelle: "Herra, jos sinä olisit ollut täällä, ei minun veljeni olisi kuollut".'),
(1695492,58,43,11,33,'Kun Jeesus näki hänen itkevän ja hänen kanssaan tulleiden juutalaisten itkevän, joutui hän hengessään syvän liikutuksen valtaan ja vapisi;'),
(1695493,58,43,11,34,'ja hän sanoi: "Mihin te panitte hänet?" He sanoivat hänelle: "Herra, tule ja katso".'),
(1695494,58,43,11,35,'Ja Jeesus itki.'),
(1695495,58,43,11,36,'Niin juutalaiset sanoivat: "Katso, kuinka rakas hän oli hänelle!"'),
(1695496,58,43,11,37,'Mutta muutamat heistä sanoivat: "Eikö hän, joka avasi sokean silmät, olisi voinut tehdä sitäkin, ettei tämä olisi kuollut?"'),
(1695497,58,43,11,38,'Niin Jeesus joutui taas liikutuksen valtaan ja meni haudalle; ja se oli luola, ja sen suulla oli kivi.'),
(1695498,58,43,11,39,'Jeesus sanoi: "Ottakaa kivi pois". Martta, kuolleen sisar, sanoi hänelle: "Herra, hän haisee jo, sillä hän on ollut haudassa neljättä päivää".'),
(1695499,58,43,11,40,'Jeesus sanoi hänelle: "Enkö minä sanonut sinulle, että jos uskoisit, niin sinä näkisit Jumalan kirkkauden?"'),
(1695500,58,43,11,41,'Niin he ottivat kiven pois. Ja Jeesus loi silmänsä ylös ja sanoi: "Isä, minä kiitän sinua, että olet minua kuullut.'),
(1695501,58,43,11,42,'Minä kyllä tiesin, että sinä minua aina kuulet; mutta kansan tähden, joka seisoo tässä ympärillä, minä tämän sanon, että he uskoisivat sinun lähettäneen minut."'),
(1695502,58,43,11,43,'Ja sen sanottuansa hän huusi suurella äänellä: "Lasarus, tule ulos!"'),
(1695503,58,43,11,44,'Ja kuollut tuli ulos, jalat ja kädet siteisiin käärittyinä, ja hänen kasvojensa ympärille oli kääritty hikiliina. Jeesus sanoi heille: "Päästäkää hänet ja antakaa hänen mennä".'),
(1695504,58,43,11,45,'Niin useat juutalaisista, jotka olivat tulleet Marian luokse ja nähneet, mitä Jeesus teki, uskoivat häneen.'),
(1695505,58,43,11,46,'Mutta muutamat heistä menivät fariseusten luo ja puhuivat heille, mitä Jeesus oli tehnyt.'),
(1695506,58,43,11,47,'Niin ylipapit ja fariseukset kokosivat neuvoston ja sanoivat: "Mitä me teemme, sillä tuo mies tekee paljon tunnustekoja?'),
(1695507,58,43,11,48,'Jos annamme hänen näin olla, niin kaikki uskovat häneen, ja roomalaiset tulevat ja ottavat meiltä sekä maan että kansan."'),
(1695508,58,43,11,49,'Mutta eräs heistä, Kaifas, joka sinä vuonna oli ylimmäinen pappi, sanoi heille: "Te ette tiedä mitään'),
(1695509,58,43,11,50,'ettekä ajattele, että teille on parempi, että yksi ihminen kuolee kansan edestä, kuin että koko kansa hukkuu".'),
(1695510,58,43,11,51,'Mutta sitä hän ei sanonut itsestään, vaan koska hän oli sinä vuonna ylimmäinen pappi, hän ennusti, että Jeesus oli kuoleva kansan edestä,'),
(1695511,58,43,11,52,'eikä ainoastaan tämän kansan edestä, vaan myös kootakseen yhdeksi hajalla olevat Jumalan lapset.'),
(1695512,58,43,11,53,'Siitä päivästä lähtien oli heillä siis tehtynä päätös tappaa hänet.'),
(1695513,58,43,11,54,'Sentähden Jeesus ei enää vaeltanut julkisesti juutalaisten keskellä, vaan lähti sieltä lähellä erämaata olevaan paikkaan, Efraim nimiseen kaupunkiin; ja siellä hän oleskeli opetuslapsineen.'),
(1695514,58,43,11,55,'Mutta juutalaisten pääsiäinen oli lähellä, ja monet menivät maaseudulta ylös Jerusalemiin ennen pääsiäisjuhlaa, puhdistamaan itsensä.'),
(1695515,58,43,11,56,'Ja he etsivät Jeesusta ja sanoivat toisilleen seisoessaan pyhäkössä: "Mitä arvelette? Eikö hän tullekaan juhlille?"'),
(1695516,58,43,11,57,'Mutta ylipapit ja fariseukset olivat antaneet käskyjä, että jos joku tietäisi, missä hän oli, hänen oli annettava se ilmi, jotta he ottaisivat hänet kiinni.'),
(1695517,58,43,12,1,'Kuusi päivää ennen pääsiäistä Jeesus saapui Betaniaan, jossa Lasarus asui, hän, jonka Jeesus oli herättänyt kuolleista.'),
(1695518,58,43,12,2,'Siellä valmistettiin hänelle ateria, ja Martta palveli, mutta Lasarus oli yksi niistä, jotka olivat aterialla hänen kanssaan.'),
(1695519,58,43,12,3,'Niin Maria otti naulan oikeata, kallisarvoista nardusvoidetta ja voiteli Jeesuksen jalat ja pyyhki ne hiuksillaan; ja huone tuli täyteen voiteen tuoksua.'),
(1695520,58,43,12,4,'Silloin sanoi yksi hänen opetuslapsistaan, Juudas Iskariot, joka oli hänet kavaltava:'),
(1695521,58,43,12,5,'"Miksi ei tätä voidetta myyty kolmeensataan denariin ja niitä annettu köyhille?"'),
(1695522,58,43,12,6,'Mutta tätä hän ei sanonut sentähden, että olisi pitänyt huolta köyhistä, vaan sentähden, että hän oli varas ja että hän rahakukkaron hoitajana otti itselleen, mitä siihen oli pantu.'),
(1695523,58,43,12,7,'Niin Jeesus sanoi: "Anna hänen olla, että hän saisi toimittaa tämän minun hautaamispäiväni varalle.'),
(1695524,58,43,12,8,'Sillä köyhät teillä aina on keskuudessanne, mutta minua teillä ei ole aina."'),
(1695525,58,43,12,9,'Silloin suuri joukko juutalaisia sai tietää, että hän oli siellä; ja he menivät sinne, ei ainoastaan Jeesuksen tähden, vaan myöskin nähdäkseen Lasaruksen, jonka hän oli herättänyt kuolleista.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695526,58,43,12,10,'Mutta ylipapit päättivät tappaa Lasaruksenkin,'),
(1695527,58,43,12,11,'koska monet juutalaiset hänen tähtensä menivät sinne ja uskoivat Jeesukseen.'),
(1695528,58,43,12,12,'Seuraavana päivänä, kun suuri kansanjoukko, joka oli saapunut juhlille, kuuli, että Jeesus oli tulossa Jerusalemiin,'),
(1695529,58,43,12,13,'ottivat he palmupuiden oksia ja menivät häntä vastaan ja huusivat: "Hoosianna, siunattu olkoon hän, joka tulee Herran nimeen, Israelin kuningas!"'),
(1695530,58,43,12,14,'Ja saatuansa nuoren aasin Jeesus istui sen selkään, niinkuin kirjoitettu on:'),
(1695531,58,43,12,15,'"Älä pelkää, tytär Siion; katso, sinun kuninkaasi tulee istuen aasin varsan selässä".'),
(1695532,58,43,12,16,'Tätä hänen opetuslapsensa eivät aluksi ymmärtäneet; mutta kun Jeesus oli kirkastettu, silloin he muistivat, että tämä oli hänestä kirjoitettu ja että he olivat tämän hänelle tehneet.'),
(1695533,58,43,12,17,'Niin kansa, joka oli ollut hänen kanssansa, kun hän kutsui Lasaruksen haudasta ja herätti hänet kuolleista, todisti hänestä.'),
(1695534,58,43,12,18,'Sentähden kansa menikin häntä vastaan, koska he kuulivat, että hän oli tehnyt sen tunnusteon.'),
(1695535,58,43,12,19,'Niin fariseukset sanoivat keskenään: "Te näette, ettette saa mitään aikaan; katso, koko maailma juoksee hänen perässään".'),
(1695536,58,43,12,20,'Ja oli muutamia kreikkalaisia niiden joukosta, jotka tulivat ylös juhlaan rukoilemaan.'),
(1695537,58,43,12,21,'Nämä menivät Filippuksen luo, joka oli Galilean Beetsaidasta, ja pyysivät häntä sanoen: "Herra, me haluamme nähdä Jeesuksen".'),
(1695538,58,43,12,22,'Filippus meni ja sanoi sen Andreaalle; Andreas ja Filippus menivät ja sanoivat Jeesukselle.'),
(1695539,58,43,12,23,'Mutta Jeesus vastasi heille sanoen: "Hetki on tullut, että Ihmisen Poika kirkastetaan.'),
(1695540,58,43,12,24,'Totisesti, totisesti minä sanon teille: jos ei nisun jyvä putoa maahan ja kuole, niin se jää yksin; mutta jos se kuolee, niin se tuottaa paljon hedelmää.'),
(1695541,58,43,12,25,'Joka elämäänsä rakastaa, kadottaa sen; mutta joka vihaa elämäänsä tässä maailmassa, hän on säilyttävä sen iankaikkiseen elämään.'),
(1695542,58,43,12,26,'Jos joku minua palvelee, seuratkoon hän minua; ja missä minä olen, siellä on myös minun palvelijani oleva. Ja jos joku minua palvelee, niin Isä on kunnioittava häntä.'),
(1695543,58,43,12,27,'Nyt minun sieluni on järkytetty; ja mitä pitäisi minun sanoman? Isä, pelasta minut tästä hetkestä. Kuitenkin: sitä varten minä olen tähän hetkeen tullut.'),
(1695544,58,43,12,28,'Isä, kirkasta nimesi!" Niin taivaasta tuli ääni: "Minä olen sen kirkastanut, ja olen sen vielä kirkastava".'),
(1695545,58,43,12,29,'Niin kansa, joka seisoi ja kuuli sen, sanoi ukkosen jylisseen. Toiset sanoivat: "Häntä puhutteli enkeli".'),
(1695546,58,43,12,30,'Jeesus vastasi ja sanoi: "Ei tämä ääni tullut minun tähteni, vaan teidän tähtenne.'),
(1695547,58,43,12,31,'Nyt käy tuomio tämän maailman ylitse; nyt tämän maailman ruhtinas pitää heitettämän ulos.'),
(1695548,58,43,12,32,'Ja kun minut ylennetään maasta, niin minä vedän kaikki tyköni."'),
(1695549,58,43,12,33,'Mutta sen hän sanoi antaen tietää, minkäkaltaisella kuolemalla hän oli kuoleva.'),
(1695550,58,43,12,34,'Kansa vastasi hänelle: "Me olemme laista kuulleet, että Kristus pysyy iankaikkisesti; kuinka sinä sitten sanot, että Ihmisen Poika pitää ylennettämän? Kuka on se Ihmisen Poika?"'),
(1695551,58,43,12,35,'Niin Jeesus sanoi heille: "Vielä vähän aikaa valkeus on teidän keskuudessanne. Vaeltakaa, niin kauan kuin teillä valkeus on, ettei pimeys saisi teitä valtaansa. Joka pimeässä vaeltaa, se ei tiedä, mihin hän menee.'),
(1695552,58,43,12,36,'Niin kauan kuin teillä valkeus on, uskokaa valkeuteen, että te valkeuden lapsiksi tulisitte." Tämän Jeesus puhui ja meni pois ja kätkeytyi heiltä.'),
(1695553,58,43,12,37,'Ja vaikka hän oli tehnyt niin monta tunnustekoa heidän nähtensä, eivät he uskoneet häneen,'),
(1695554,58,43,12,38,'että kävisi toteen profeetta Esaiaan sana, jonka hän on sanonut: "Herra, kuka uskoo meidän saarnamme, ja kenelle Herran käsivarsi ilmoitetaan?"'),
(1695555,58,43,12,39,'Sentähden he eivät voineet uskoa, koska Esaias on vielä sanonut:'),
(1695556,58,43,12,40,'"Hän on sokaissut heidän silmänsä ja paaduttanut heidän sydämensä, että he eivät näkisi silmillään eivätkä ymmärtäisi sydämellään eivätkä kääntyisi ja etten minä heitä parantaisi".'),
(1695557,58,43,12,41,'Tämän Esaias sanoi, kun hän näki hänen kirkkautensa ja puhui hänestä.'),
(1695558,58,43,12,42,'Kuitenkin useat hallitusmiehistäkin uskoivat häneen, mutta fariseusten tähden he eivät sitä tunnustaneet, etteivät joutuisi synagoogasta erotetuiksi.'),
(1695559,58,43,12,43,'Sillä he rakastivat ihmiskunniaa enemmän kuin Jumalan kunniaa.'),
(1695560,58,43,12,44,'Mutta Jeesus huusi ja sanoi: "Joka uskoo minuun, se ei usko minuun, vaan häneen, joka on minut lähettänyt.'),
(1695561,58,43,12,45,'Ja joka näkee minut, näkee hänet, joka on minut lähettänyt.'),
(1695562,58,43,12,46,'Minä olen tullut valkeudeksi maailmaan, ettei yksikään, joka minuun uskoo, jäisi pimeyteen.'),
(1695563,58,43,12,47,'Ja jos joku kuulee minun sanani eikä niitä noudata, niin häntä en minä tuomitse; sillä en minä ole tullut maailmaa tuomitsemaan, vaan pelastamaan maailman.'),
(1695564,58,43,12,48,'Joka katsoo minut ylen eikä ota vastaan minun sanojani, hänellä on tuomitsijansa: se sana, jonka minä olen puhunut, se on tuomitseva hänet viimeisenä päivänä.'),
(1695565,58,43,12,49,'Sillä en minä itsestäni ole puhunut, vaan Isä, joka on minut lähettänyt, on itse antanut minulle käskyn, mitä minun pitää sanoman ja mitä puhuman.'),
(1695566,58,43,12,50,'Ja minä tiedän, että hänen käskynsä on iankaikkinen elämä. Sentähden, minkä minä puhun, sen minä puhun niin, kuin Isä on minulle sanonut."'),
(1695567,58,43,13,1,'Mutta ennen pääsiäisjuhlaa, kun Jeesus tiesi hetkensä tulleen, että hän oli siirtyvä tästä maailmasta Isän tykö, niin hän, joka oli rakastanut omiansa, jotka maailmassa olivat, osoitti heille rakkautta loppuun asti.'),
(1695568,58,43,13,2,'Ja ehtoollisella oltaessa, kun perkele jo oli pannut Juudas Iskariotin, Simonin pojan, sydämeen, että hän kavaltaisi Jeesuksen,'),
(1695569,58,43,13,3,'niin Jeesus, tietäen, että Isä oli antanut kaikki hänen käsiinsä ja että hän oli lähtenyt Jumalan tyköä ja oli menevä Jumalan tykö,'),
(1695570,58,43,13,4,'nousi ehtoolliselta ja riisui vaippansa, otti liinavaatteen ja vyötti sillä itsensä.'),
(1695571,58,43,13,5,'Sitten hän kaatoi vettä pesumaljaan ja rupesi pesemään opetuslastensa jalkoja ja pyyhkimään niitä liinavaatteella, jolla oli vyöttäytynyt.'),
(1695572,58,43,13,6,'Niin hän tuli Simon Pietarin kohdalle, ja tämä sanoi hänelle: "Herra, sinäkö peset minun jalkani?"'),
(1695573,58,43,13,7,'Jeesus vastasi ja sanoi hänelle: "Mitä minä teen, sitä et nyt käsitä, mutta vastedes sinä sen ymmärrät".'),
(1695574,58,43,13,8,'Pietari sanoi hänelle: "Et ikinä sinä saa pestä minun jalkojani". Jeesus vastasi hänelle: "Ellen minä sinua pese, ei sinulla ole osuutta minun kanssani".'),
(1695575,58,43,13,9,'Simon Pietari sanoi hänelle: "Herra, älä pese ainoastaan minun jalkojani, vaan myös kädet ja pää".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695576,58,43,13,10,'Jeesus sanoi hänelle: "Joka on kylpenyt, ei tarvitse muuta, kuin että jalat pestään, ja niin hän on kokonaan puhdas; ja te olette puhtaat, ette kuitenkaan kaikki".'),
(1695577,58,43,13,11,'Sillä hän tiesi kavaltajansa; sentähden hän sanoi: "Ette kaikki ole puhtaat".'),
(1695578,58,43,13,12,'Kun hän siis oli pessyt heidän jalkansa ja ottanut vaippansa ja taas asettunut aterialle, sanoi hän heille: "Ymmärrättekö, mitä minä olen teille tehnyt?'),
(1695579,58,43,13,13,'Te puhuttelette minua opettajaksi ja Herraksi, ja oikein te sanotte, sillä se minä olen.'),
(1695580,58,43,13,14,'Jos siis minä, teidän Herranne ja opettajanne, olen pessyt teidän jalkanne, olette tekin velvolliset pesemään toistenne jalat.'),
(1695581,58,43,13,15,'Sillä minä annoin teille esikuvan, että myös te niin tekisitte, kuin minä olen teille tehnyt.'),
(1695582,58,43,13,16,'Totisesti, totisesti minä sanon teille: ei ole palvelija herraansa suurempi eikä lähettiläs lähettäjäänsä suurempi.'),
(1695583,58,43,13,17,'Jos te tämän tiedätte, niin olette autuaat, jos te sen teette.'),
(1695584,58,43,13,18,'En minä puhu teistä kaikista: minä tiedän, ketkä olen valinnut; mutta tämän kirjoituksen piti käymän toteen: ''Joka minun leipääni syö, on nostanut kantapäänsä minua vastaan''.'),
(1695585,58,43,13,19,'Jo nyt minä sanon sen teille, ennenkuin se tapahtuu, että te, kun se tapahtuu, uskoisitte, että minä olen se.'),
(1695586,58,43,13,20,'Totisesti, totisesti minä sanon teille: joka ottaa vastaan sen, jonka minä lähetän, se ottaa vastaan minut; mutta joka ottaa vastaan minut, se ottaa vastaan hänet, joka on minut lähettänyt.'),
(1695587,58,43,13,21,'Tämän sanottuaan Jeesus tuli järkytetyksi hengessään ja todisti ja sanoi: "Totisesti, totisesti minä sanon teille: yksi teistä on minut kavaltava".'),
(1695588,58,43,13,22,'Niin opetuslapset katsoivat toisiinsa epätietoisina, kenestä hän puhui.'),
(1695589,58,43,13,23,'Ja eräs hänen opetuslapsistaan, se, jota Jeesus rakasti, lepäsi aterioitaessa Jeesuksen syliä vasten.'),
(1695590,58,43,13,24,'Simon Pietari nyökäytti hänelle päätään ja sanoi hänelle: "Sano, kuka se on, josta hän puhuu".'),
(1695591,58,43,13,25,'Niin tämä, nojautuen Jeesuksen rintaa vasten, sanoi hänelle: "Herra, kuka se on?"'),
(1695592,58,43,13,26,'Jeesus vastasi: "Se on se, jolle minä kastan ja annan tämän palan". Niin hän otti palan, kastoi sen ja antoi Juudaalle, Simon Iskariotin pojalle.'),
(1695593,58,43,13,27,'Ja silloin, sen palan jälkeen, meni häneen saatana. Niin Jeesus sanoi hänelle: "Minkä teet, se tee pian".'),
(1695594,58,43,13,28,'Mutta ei kukaan aterioivista ymmärtänyt, mitä varten hän sen hänelle sanoi.'),
(1695595,58,43,13,29,'Sillä muutamat luulivat, koska rahakukkaro oli Juudaalla, Jeesuksen sanoneen hänelle: "Osta, mitä tarvitsemme juhlaksi", tai että hän antaisi jotakin köyhille.'),
(1695596,58,43,13,30,'Niin hän, otettuaan sen palan, meni kohta ulos; ja oli yö.'),
(1695597,58,43,13,31,'Kun hän oli mennyt ulos, sanoi Jeesus: "Nyt Ihmisen Poika on kirkastettu, ja Jumala on kirkastettu hänessä.'),
(1695598,58,43,13,32,'Jos Jumala on kirkastettu hänessä, niin kirkastaa myös Jumala hänet itsessään ja kirkastaa hänet pian.'),
(1695599,58,43,13,33,'Lapsukaiset, vielä vähän aikaa minä olen teidän kanssanne. Te tulette minua etsimään, ja niinkuin sanoin juutalaisille: ''Mihin minä menen, sinne te ette voi tulla'', niin minä sanon nyt myös teille.'),
(1695600,58,43,13,34,'Uuden käskyn minä annan teille, että rakastatte toisianne, niinkuin minä olen teitä rakastanut - että tekin niin rakastatte toisianne.'),
(1695601,58,43,13,35,'Siitä kaikki tuntevat teidät minun opetuslapsikseni, jos teillä on keskinäinen rakkaus."'),
(1695602,58,43,13,36,'Simon Pietari sanoi hänelle: "Herra, mihin sinä menet?" Jeesus vastasi hänelle: "Mihin minä menen, sinne sinä et voi nyt minua seurata, mutta vastedes olet minua seuraava".'),
(1695603,58,43,13,37,'Pietari sanoi hänelle: "Herra, miksi en nyt voi seurata sinua? Henkeni minä annan sinun edestäsi."'),
(1695604,58,43,13,38,'Jeesus vastasi: "Sinäkö annat henkesi minun edestäni? Totisesti, totisesti minä sanon sinulle: ei laula kukko, ennenkuin sinä minut kolmesti kiellät."'),
(1695605,58,43,14,1,'"Älköön teidän sydämenne olko murheellinen. Uskokaa Jumalaan, ja uskokaa minuun.'),
(1695606,58,43,14,2,'Minun Isäni kodissa on monta asuinsijaa. Jos ei niin olisi, sanoisinko minä teille, että minä menen valmistamaan teille sijaa?'),
(1695607,58,43,14,3,'Ja vaikka minä menen valmistamaan teille sijaa, tulen minä takaisin ja otan teidät tyköni, että tekin olisitte siellä, missä minä olen.'),
(1695608,58,43,14,4,'Ja mihin minä menen - tien sinne te tiedätte."'),
(1695609,58,43,14,5,'Tuomas sanoi hänelle: "Herra, me emme tiedä, mihin sinä menet; kuinka sitten tietäisimme tien?"'),
(1695610,58,43,14,6,'Jeesus sanoi hänelle: "Minä olen tie ja totuus ja elämä; ei kukaan tule Isän tykö muutoin kuin minun kauttani.'),
(1695611,58,43,14,7,'Jos te olisitte tunteneet minut, niin te tuntisitte myös minun Isäni; tästälähin te tunnette hänet, ja te olette nähneet hänet."'),
(1695612,58,43,14,8,'Filippus sanoi hänelle: "Herra, näytä meille Isä, niin me tyydymme".'),
(1695613,58,43,14,9,'Jeesus sanoi hänelle: "Niin kauan aikaa minä olen ollut teidän kanssanne, etkä sinä tunne minua, Filippus! Joka on nähnyt minut, on nähnyt Isän; kuinka sinä sitten sanot: ''Näytä meille Isä''?'),
(1695614,58,43,14,10,'Etkö usko, että minä olen Isässä, ja että Isä on minussa? Niitä sanoja, jotka minä teille puhun, minä en puhu itsestäni; ja Isä, joka minussa asuu, tekee teot, jotka ovat hänen.'),
(1695615,58,43,14,11,'Uskokaa minua, että minä olen Isässä, ja että Isä on minussa; mutta jos ette, niin uskokaa itse tekojen tähden.'),
(1695616,58,43,14,12,'Totisesti, totisesti minä sanon teille: joka uskoo minuun, myös hän on tekevä niitä tekoja, joita minä teen, ja suurempiakin, kuin ne ovat, hän on tekevä; sillä minä menen Isän tykö,'),
(1695617,58,43,14,13,'ja mitä hyvänsä te anotte minun nimessäni, sen minä teen, että Isä kirkastettaisiin Pojassa.'),
(1695618,58,43,14,14,'Jos te anotte minulta jotakin minun nimessäni, niin minä sen teen.'),
(1695619,58,43,14,15,'Jos te minua rakastatte, niin te pidätte minun käskyni.'),
(1695620,58,43,14,16,'Ja minä olen rukoileva Isää, ja hän antaa teille toisen Puolustajan olemaan teidän kanssanne iankaikkisesti,'),
(1695621,58,43,14,17,'totuuden Hengen, jota maailma ei voi ottaa vastaan, koska se ei näe häntä eikä tunne häntä; mutta te tunnette hänet, sillä hän pysyy teidän tykönänne ja on teissä oleva.'),
(1695622,58,43,14,18,'En minä jätä teitä orvoiksi; minä tulen teidän tykönne.'),
(1695623,58,43,14,19,'Vielä vähän aikaa, niin maailma ei enää minua näe, mutta te näette minut; koska minä elän, niin tekin saatte elää.'),
(1695624,58,43,14,20,'Sinä päivänä te ymmärrätte, että minä olen Isässäni, ja että te olette minussa ja minä teissä.'),
(1695625,58,43,14,21,'Jolla on minun käskyni ja joka ne pitää, hän on se, joka minua rakastaa; mutta joka minua rakastaa, häntä minun Isäni rakastaa, ja minä rakastan häntä ja ilmoitan itseni hänelle."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695626,58,43,14,22,'Juudas, ei se Iskariot, sanoi hänelle: "Herra, mistä syystä sinä aiot ilmoittaa itsesi meille etkä maailmalle?"'),
(1695627,58,43,14,23,'Jeesus vastasi ja sanoi hänelle: "Jos joku rakastaa minua, niin hän pitää minun sanani, ja minun Isäni rakastaa häntä, ja me tulemme hänen tykönsä ja jäämme hänen tykönsä asumaan.'),
(1695628,58,43,14,24,'Joka ei minua rakasta, se ei pidä minun sanojani; ja se sana, jonka te kuulette, ei ole minun, vaan Isän, joka on minut lähettänyt.'),
(1695629,58,43,14,25,'Tämän minä olen teille puhunut ollessani teidän tykönänne.'),
(1695630,58,43,14,26,'Mutta Puolustaja, Pyhä Henki, jonka Isä on lähettävä minun nimessäni, hän opettaa teille kaikki ja muistuttaa teitä kaikesta, minkä minä olen teille sanonut.'),
(1695631,58,43,14,27,'Rauhan minä jätän teille: minun rauhani - sen minä annan teille. En minä anna teille, niinkuin maailma antaa. Älköön teidän sydämenne olko murheellinen älköönkä peljätkö.'),
(1695632,58,43,14,28,'Te kuulitte minun sanovan teille: ''Minä menen pois ja palajan jälleen teidän tykönne''. Jos te minua rakastaisitte, niin te iloitsisitte siitä, että minä menen Isän tykö, sillä Isä on minua suurempi.'),
(1695633,58,43,14,29,'Ja nyt minä olen sanonut sen teille, ennenkuin se on tapahtunut, että te uskoisitte, kun se tapahtuu.'),
(1695634,58,43,14,30,'En minä enää puhu paljoa teidän kanssanne, sillä maailman ruhtinas tulee, ja minussa hänellä ei ole mitään.'),
(1695635,58,43,14,31,'Mutta että maailma ymmärtäisi minun rakastavan Isää ja tekevän, niinkuin Isä on minua käskenyt: nouskaa, lähtekäämme täältä."'),
(1695636,58,43,15,1,'"Minä olen totinen viinipuu, ja minun Isäni on viinitarhuri.'),
(1695637,58,43,15,2,'Jokaisen oksan minussa, joka ei kanna hedelmää, hän karsii pois; ja jokaisen, joka kantaa hedelmää, hän puhdistaa, että se kantaisi runsaamman hedelmän.'),
(1695638,58,43,15,3,'Te olette jo puhtaat sen sanan tähden, jonka minä olen teille puhunut.'),
(1695639,58,43,15,4,'Pysykää minussa, niin minä pysyn teissä. Niinkuin oksa ei voi kantaa hedelmää itsestään, ellei se pysy viinipuussa, niin ette tekään, ellette pysy minussa.'),
(1695640,58,43,15,5,'Minä olen viinipuu, te olette oksat. Joka pysyy minussa ja jossa minä pysyn, se kantaa paljon hedelmää; sillä ilman minua te ette voi mitään tehdä.'),
(1695641,58,43,15,6,'Jos joku ei pysy minussa, niin hänet heitetään pois niinkuin oksa, ja hän kuivettuu; ja ne kootaan yhteen ja heitetään tuleen, ja ne palavat.'),
(1695642,58,43,15,7,'Jos te pysytte minussa ja minun sanani pysyvät teissä, niin anokaa, mitä ikinä tahdotte, ja te saatte sen.'),
(1695643,58,43,15,8,'Siinä minun Isäni kirkastetaan, että te kannatte paljon hedelmää ja tulette minun opetuslapsikseni.'),
(1695644,58,43,15,9,'Niinkuin Isä on minua rakastanut, niin minäkin olen rakastanut teitä; pysykää minun rakkaudessani.'),
(1695645,58,43,15,10,'Jos te pidätte minun käskyni, niin te pysytte minun rakkaudessani, niinkuin minä olen pitänyt Isäni käskyt ja pysyn hänen rakkaudessaan.'),
(1695646,58,43,15,11,'Tämän minä olen teille puhunut, että minun iloni olisi teissä ja teidän ilonne tulisi täydelliseksi.'),
(1695647,58,43,15,12,'Tämä on minun käskyni, että te rakastatte toisianne, niinkuin minä olen teitä rakastanut.'),
(1695648,58,43,15,13,'Sen suurempaa rakkautta ei ole kenelläkään, kuin että hän antaa henkensä ystäväinsä edestä.'),
(1695649,58,43,15,14,'Te olette minun ystäväni, jos teette, mitä minä käsken teidän tehdä.'),
(1695650,58,43,15,15,'En minä enää sano teitä palvelijoiksi, sillä palvelija ei tiedä, mitä hänen herransa tekee; vaan ystäviksi minä sanon teitä, sillä minä olen ilmoittanut teille kaikki, mitä minä olen kuullut Isältäni.'),
(1695651,58,43,15,16,'Te ette valinneet minua, vaan minä valitsin teidät ja asetin teidät, että te menisitte ja kantaisitte hedelmää ja että teidän hedelmänne pysyisi: että mitä ikinä te anotte Isältä minun nimessäni, hän sen teille antaisi.'),
(1695652,58,43,15,17,'Sen käskyn minä teille annan, että rakastatte toisianne.'),
(1695653,58,43,15,18,'Jos maailma teitä vihaa, niin tietäkää, että se on vihannut minua ennen kuin teitä.'),
(1695654,58,43,15,19,'Jos te maailmasta olisitte, niin maailma omaansa rakastaisi; mutta koska te ette ole maailmasta, vaan minä olen teidät maailmasta valinnut, sentähden maailma teitä vihaa.'),
(1695655,58,43,15,20,'Muistakaa se sana, jonka minä teille sanoin: ''Ei ole palvelija herraansa suurempi''. Jos he ovat minua vainonneet, niin he teitäkin vainoavat; jos he ovat ottaneet vaarin minun sanastani, niin he ottavat vaarin teidänkin sanastanne.'),
(1695656,58,43,15,21,'Mutta kaiken tämän he tekevät teille minun nimeni tähden, koska he eivät tunne häntä, joka on minut lähettänyt.'),
(1695657,58,43,15,22,'Jos minä en olisi tullut ja puhunut heille, ei heillä olisi syntiä; mutta nyt heillä ei ole, millä syntiänsä puolustaisivat.'),
(1695658,58,43,15,23,'Joka vihaa minua, se vihaa myös minun Isääni.'),
(1695659,58,43,15,24,'Jos minä en olisi tehnyt heidän keskuudessaan niitä tekoja, joita ei kukaan muu ole tehnyt, ei heillä olisi syntiä; mutta nyt he ovat nähneet ja ovat vihanneet sekä minua että minun Isääni.'),
(1695660,58,43,15,25,'Mutta se sana oli käyvä toteen, joka on kirjoitettuna heidän laissaan: ''He ovat vihanneet minua syyttä''.'),
(1695661,58,43,15,26,'Mutta kun Puolustaja tulee, jonka minä lähetän teille Isän tyköä, totuuden Henki, joka lähtee Isän tyköä, niin hän on todistava minusta.'),
(1695662,58,43,15,27,'Ja te myös todistatte, sillä te olette alusta asti olleet minun kanssani."'),
(1695663,58,43,16,1,'"Tämän minä olen teille puhunut, ettette loukkaantuisi.'),
(1695664,58,43,16,2,'He erottavat teidät synagoogasta; ja tulee aika, jolloin jokainen, joka tappaa teitä, luulee tekevänsä uhripalveluksen Jumalalle.'),
(1695665,58,43,16,3,'Ja sen he tekevät teille, koska he eivät tunne Isää eivätkä minua.'),
(1695666,58,43,16,4,'Mutta tämän minä olen puhunut teille, että, kun se aika tulee, te muistaisitte minun sen teille sanoneen. Tätä minä en ole sanonut teille alusta, koska minä olin teidän kansanne.'),
(1695667,58,43,16,5,'Mutta nyt minä menen hänen tykönsä, joka on minut lähettänyt, eikä kukaan teistä kysy minulta: ''Mihin sinä menet?'''),
(1695668,58,43,16,6,'Mutta koska minä olen tämän teille puhunut, täyttää murhe teidän sydämenne.'),
(1695669,58,43,16,7,'Kuitenkin minä sanon teille totuuden: teille on hyväksi, että minä menen pois. Sillä ellen minä mene pois, ei Puolustaja tule teidän tykönne; mutta jos minä menen, niin minä hänet teille lähetän.'),
(1695670,58,43,16,8,'Ja kun hän tulee, niin hän näyttää maailmalle todeksi synnin ja vanhurskauden ja tuomion:'),
(1695671,58,43,16,9,'synnin, koska he eivät usko minuun;'),
(1695672,58,43,16,10,'vanhurskauden, koska minä menen Isän tykö, ettekä te enää minua näe;'),
(1695673,58,43,16,11,'ja tuomion, koska tämän maailman ruhtinas on tuomittu.'),
(1695674,58,43,16,12,'Minulla on vielä paljon sanottavaa teille, mutta te ette voi nyt sitä kantaa.'),
(1695675,58,43,16,13,'Mutta kun hän tulee, totuuden Henki, johdattaa hän teidät kaikkeen totuuteen. Sillä se, mitä hän puhuu, ei ole hänestä itsestään; vaan minkä hän kuulee, sen hän puhuu, ja tulevaiset hän teille julistaa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695676,58,43,16,14,'Hän on minut kirkastava, sillä hän ottaa minun omastani ja julistaa teille.'),
(1695677,58,43,16,15,'Kaikki, mitä Isällä on, on minun; sentähden minä sanoin, että hän ottaa minun omastani ja julistaa teille.'),
(1695678,58,43,16,16,'Vähän aikaa, niin te ette enää minua näe, ja taas vähän aikaa, niin te näette minut."'),
(1695679,58,43,16,17,'Silloin muutamat hänen opetuslapsistansa sanoivat toisilleen: "Mitä se tarkoittaa, kun hän sanoo meille: ''Vähän aikaa, niin te ette minua näe, ja taas vähän aikaa, niin te näette minut'', ja: ''Minä menen Isän tykö''?"'),
(1695680,58,43,16,18,'Niin he sanoivat: "Mitä se tarkoittaa, kun hän sanoo: ''Vähän aikaa''? Emme ymmärrä, mitä hän puhuu."'),
(1695681,58,43,16,19,'Jeesus huomasi heidän tahtovan kysyä häneltä ja sanoi heille: "Sitäkö te kyselette keskenänne, että minä sanoin: ''Vähän aikaa, niin te ette minua näe, ja taas vähän aikaa, niin te näette minut''?'),
(1695682,58,43,16,20,'Totisesti, totisesti minä sanon teille: te joudutte itkemään ja valittamaan, mutta maailma on iloitseva; te tulette murheellisiksi, mutta teidän murheenne on muuttuva iloksi.'),
(1695683,58,43,16,21,'Kun vaimo synnyttää, on hänellä murhe, koska hänen hetkensä on tullut; mutta kun hän on synnyttänyt lapsen, ei hän enää muista ahdistustaan sen ilon tähden, että ihminen on syntynyt maailmaan.'),
(1695684,58,43,16,22,'Niin on myös teillä nyt murhe; mutta minä olen taas näkevä teidät, ja teidän sydämenne on iloitseva, eikä kukaan ota teiltä pois teidän iloanne.'),
(1695685,58,43,16,23,'Ja sinä päivänä te ette minulta mitään kysy. Totisesti, totisesti minä sanon teille: jos te anotte jotakin Isältä, on hän sen teille antava minun nimessäni.'),
(1695686,58,43,16,24,'Tähän asti te ette ole anoneet mitään minun nimessäni; anokaa, niin te saatte, että teidän ilonne olisi täydellinen.'),
(1695687,58,43,16,25,'Tämän minä olen puhunut teille kuvauksilla; mutta tulee aika, jolloin minä en puhu teille enää kuvauksilla, vaan avonaisesti julistan teille sanomaa Isästä.'),
(1695688,58,43,16,26,'Sinä päivänä te anotte minun nimessäni; enkä minä sano teille, että minä olen rukoileva Isää teidän edestänne;'),
(1695689,58,43,16,27,'sillä Isä itse rakastaa teitä, sentähden että te olette minua rakastaneet ja uskoneet minun lähteneen Jumalan tyköä.'),
(1695690,58,43,16,28,'Minä olen lähtenyt Isästä ja tullut maailmaan; jälleen minä jätän maailman ja menen Isän tykö."'),
(1695691,58,43,16,29,'Hänen opetuslapsensa sanoivat: "Katso, nyt sinä puhut avonaisesti etkä käytä mitään kuvausta.'),
(1695692,58,43,16,30,'Nyt me tiedämme, että sinä tiedät kaikki, etkä tarvitse, että kukaan sinulta kysyy; sentähden me uskomme sinun Jumalan tyköä lähteneen."'),
(1695693,58,43,16,31,'Jeesus vastasi heille: "Nyt te uskotte.'),
(1695694,58,43,16,32,'Katso, tulee hetki ja on jo tullut, jona teidät hajotetaan kukin tahollensa ja te jätätte minut yksin; en minä kuitenkaan yksin ole, sillä Isä on minun kanssani.'),
(1695695,58,43,16,33,'Tämän minä olen teille puhunut, että teillä olisi minussa rauha. Maailmassa teillä on ahdistus; mutta olkaa turvallisella mielellä: minä olen voittanut maailman."'),
(1695696,58,43,17,1,'Tämän Jeesus puhui ja nosti silmänsä taivasta kohti ja sanoi: "Isä, hetki on tullut, kirkasta Poikasi, että Poikasi kirkastaisi sinut;'),
(1695697,58,43,17,2,'koska sinä olet antanut hänen valtaansa kaiken lihan, että hän antaisi iankaikkisen elämän kaikille, jotka sinä olet hänelle antanut.'),
(1695698,58,43,17,3,'Mutta tämä on iankaikkinen elämä, että he tuntevat sinut, joka yksin olet totinen Jumala, ja hänet, jonka sinä olet lähettänyt, Jeesuksen Kristuksen.'),
(1695699,58,43,17,4,'Minä olen kirkastanut sinut maan päällä: minä olen täyttänyt sen työn, jonka sinä annoit minun tehtäväkseni.'),
(1695700,58,43,17,5,'Ja nyt, Isä, kirkasta sinä minut tykönäsi sillä kirkkaudella, joka minulla oli sinun tykönäsi, ennenkuin maailma olikaan.'),
(1695701,58,43,17,6,'Minä olen ilmoittanut sinun nimesi ihmisille, jotka sinä annoit minulle maailmasta. He olivat sinun, ja sinä annoit heidät minulle, ja he ovat ottaneet sinun sanastasi vaarin.'),
(1695702,58,43,17,7,'Nyt he tietävät, että kaikki, minkä olet minulle antanut, on sinulta.'),
(1695703,58,43,17,8,'Sillä ne sanat, jotka sinä minulle annoit, minä olen antanut heille; ja he ovat ottaneet ne vastaan ja tietävät totisesti minun lähteneen sinun tyköäsi ja uskovat, että sinä olet minut lähettänyt.'),
(1695704,58,43,17,9,'Minä rukoilen heidän edestänsä; en minä maailman edestä rukoile, vaan niiden edestä, jotka sinä olet minulle antanut, koska he ovat sinun -'),
(1695705,58,43,17,10,'ja kaikki minun omani ovat sinun, ja sinun omasi ovat minun - ja minä olen kirkastettu heissä.'),
(1695706,58,43,17,11,'Ja minä en enää ole maailmassa, mutta he ovat maailmassa, ja minä tulen sinun tykösi. Pyhä Isä, varjele heidät nimessäsi, jonka sinä olet minulle antanut, että he olisivat yhtä niinkuin mekin.'),
(1695707,58,43,17,12,'Kun minä olin heidän kanssansa, varjelin minä heidät sinun nimessäsi, jonka sinä olet minulle antanut, ja suojelin heitä, eikä heistä joutunut kadotetuksi yksikään muu kuin se kadotuksen lapsi, että kirjoitus kävisi toteen.'),
(1695708,58,43,17,13,'Mutta nyt minä tulen sinun tykösi ja puhun tätä maailmassa, että heillä olisi minun iloni täydellisenä heissä itsessään.'),
(1695709,58,43,17,14,'Minä olen antanut heille sinun sanasi, ja maailma vihaa heitä, koska he eivät ole maailmasta, niinkuin en minäkään maailmasta ole.'),
(1695710,58,43,17,15,'En minä rukoile, että ottaisit heidät pois maailmasta, vaan että sinä varjelisit heidät pahasta.'),
(1695711,58,43,17,16,'He eivät ole maailmasta, niinkuin en minäkään maailmasta ole.'),
(1695712,58,43,17,17,'Pyhitä heidät totuudessa; sinun sanasi on totuus.'),
(1695713,58,43,17,18,'Niinkuin sinä olet lähettänyt minut maailmaan, niin olen minäkin lähettänyt heidät maailmaan;'),
(1695714,58,43,17,19,'ja minä pyhitän itseni heidän tähtensä, että myös he olisivat pyhitetyt totuudessa.'),
(1695715,58,43,17,20,'Mutta en minä rukoile ainoastaan näiden edestä, vaan myös niiden edestä, jotka heidän sanansa kautta uskovat minuun,'),
(1695716,58,43,17,21,'että he kaikki olisivat yhtä, niinkuin sinä, Isä, olet minussa ja minä sinussa, että hekin meissä olisivat, niin että maailma uskoisi, että sinä olet minut lähettänyt.'),
(1695717,58,43,17,22,'Ja sen kirkkauden, jonka sinä minulle annoit, minä olen antanut heille, että he olisivat yhtä, niinkuin me olemme yhtä -'),
(1695718,58,43,17,23,'minä heissä, ja sinä minussa - että he olisivat täydellisesti yhtä, niin että maailma ymmärtäisi, että sinä olet minut lähettänyt ja rakastanut heitä, niinkuin sinä olet minua rakastanut.'),
(1695719,58,43,17,24,'Isä, minä tahdon, että missä minä olen, siellä nekin, jotka sinä olet minulle antanut, olisivat minun kanssani, että he näkisivät minun kirkkauteni, jonka sinä olet minulle antanut, koska olet rakastanut minua jo ennen maailman perustamista.'),
(1695720,58,43,17,25,'Vanhurskas Isä, maailma ei ole sinua tuntenut, mutta minä tunnen sinut, ja nämä ovat tulleet tuntemaan, että sinä olet minut lähettänyt.'),
(1695721,58,43,17,26,'Ja minä olen tehnyt sinun nimesi heille tunnetuksi ja teen vastakin, että se rakkaus, jolla sinä olet minua rakastanut, olisi heissä ja minä olisin heissä."'),
(1695722,58,43,18,1,'Kun Jeesus oli tämän puhunut, lähti hän pois opetuslastensa kanssa Kedronin puron tuolle puolelle; siellä oli puutarha, johon hän meni opetuslapsinensa.'),
(1695723,58,43,18,2,'Mutta myös Juudas, joka hänet kavalsi, tiesi sen paikan, koska Jeesus ja hänen opetuslapsensa usein olivat kokoontuneet sinne.'),
(1695724,58,43,18,3,'Niin Juudas otti sotilasjoukon sekä ylipappien ja fariseusten palvelijoita ja tuli sinne soihdut ja lamput ja aseet mukanaan.'),
(1695725,58,43,18,4,'Silloin Jeesus, joka tiesi kaiken, mikä oli häntä kohtaava, astui esiin ja sanoi heille: "Ketä te etsitte?"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695726,58,43,18,5,'He vastasivat hänelle: "Jeesusta, Nasaretilaista". Jeesus sanoi heille: "Minä se olen". Ja Juudas, joka hänet kavalsi, seisoi myös heidän kanssaan.'),
(1695727,58,43,18,6,'Kun hän siis sanoi heille: "Minä se olen", peräytyivät he ja kaatuivat maahan.'),
(1695728,58,43,18,7,'Niin hän taas kysyi heiltä: "Ketä te etsitte?" He sanoivat: "Jeesusta, Nasaretilaista".'),
(1695729,58,43,18,8,'Jeesus vastasi: "Minähän sanoin teille, että minä se olen. Jos te siis minua etsitte, niin antakaa näiden mennä";'),
(1695730,58,43,18,9,'että se sana kävisi toteen, jonka hän oli sanonut: "En minä ole kadottanut ketään niistä, jotka sinä olet minulle antanut".'),
(1695731,58,43,18,10,'Niin Simon Pietari, jolla oli miekka, veti sen ja iski ylimmäisen papin palvelijaa ja sivalsi häneltä pois oikean korvan; ja palvelijan nimi oli Malkus.'),
(1695732,58,43,18,11,'Niin Jeesus sanoi Pietarille: "Pistä miekkasi tuppeen. Enkö minä joisi sitä maljaa, jonka Isä on minulle antanut?"'),
(1695733,58,43,18,12,'Niin sotilasjoukko ja päällikkö ja juutalaisten palvelijat ottivat Jeesuksen kiinni ja sitoivat hänet'),
(1695734,58,43,18,13,'ja veivät ensin Hannaan luo, sillä hän oli Kaifaan appi, ja Kaifas oli sinä vuonna ylimmäisenä pappina.'),
(1695735,58,43,18,14,'Ja Kaifas oli se, joka neuvottelussa oli juutalaisille sanonut: "On hyödyllistä, että yksi ihminen kuolee kansan edestä."'),
(1695736,58,43,18,15,'Ja Jeesusta seurasi Simon Pietari ja eräs toinen opetuslapsi. Tämä opetuslapsi oli ylimmäisen papin tuttava ja meni Jeesuksen kanssa sisälle ylimmäisen papin kartanoon.'),
(1695737,58,43,18,16,'Mutta Pietari seisoi portilla ulkona. Niin se toinen opetuslapsi, joka oli ylimmäisen papin tuttava, meni ulos ja puhutteli portinvartijatarta ja toi Pietarin sisälle.'),
(1695738,58,43,18,17,'Niin palvelijatar, joka vartioi porttia, sanoi Pietarille: "Etkö sinäkin ole tuon miehen opetuslapsia?" Hän sanoi: "En ole".'),
(1695739,58,43,18,18,'Mutta palvelijat ja käskyläiset olivat tehneet hiilivalkean, koska oli kylmä, ja seisoivat ja lämmittelivät. Ja myös Pietari seisoi heidän kanssaan lämmittelemässä.'),
(1695740,58,43,18,19,'Niin ylimmäinen pappi kysyi Jeesukselta hänen opetuslapsistaan ja opistaan.'),
(1695741,58,43,18,20,'Jeesus vastasi hänelle: "Minä olen julkisesti puhunut maailmalle; minä olen aina opettanut synagoogissa ja pyhäkössä, joihin kaikki juutalaiset kokoontuvat, enkä ole salassa puhunut mitään.'),
(1695742,58,43,18,21,'Miksi minulta kysyt? Kysy niiltä, jotka ovat kuulleet, mitä minä olen heille puhunut; katso, he tietävät, mitä minä olen sanonut."'),
(1695743,58,43,18,22,'Mutta kun Jeesus oli tämän sanonut, antoi eräs palvelija, joka seisoi vieressä, hänelle korvapuustin sanoen: "Niinkö sinä vastaat ylimmäiselle papille?"'),
(1695744,58,43,18,23,'Jeesus vastasi hänelle: "Jos minä pahasti puhuin, niin näytä toteen, että se on pahaa; mutta jos minä puhuin oikein, miksi minua lyöt?"'),
(1695745,58,43,18,24,'Niin Hannas lähetti hänet sidottuna ylimmäisen papin Kaifaan luo.'),
(1695746,58,43,18,25,'Mutta Simon Pietari seisoi lämmittelemässä. Niin he sanoivat hänelle: "Etkö sinäkin ole hänen opetuslapsiaan?" Hän kielsi ja sanoi: "En ole".'),
(1695747,58,43,18,26,'Silloin eräs ylimmäisen papin palvelijoista, sen sukulainen, jolta Pietari oli sivaltanut korvan pois, sanoi: "Enkö minä nähnyt sinua puutarhassa hänen kanssaan?"'),
(1695748,58,43,18,27,'Niin Pietari taas kielsi, ja samassa lauloi kukko.'),
(1695749,58,43,18,28,'Niin he veivät Jeesuksen Kaifaan luota palatsiin; ja oli varhainen aamu. Ja itse he eivät menneet sisälle palatsiin, etteivät saastuisi, vaan saattaisivat syödä pääsiäislammasta.'),
(1695750,58,43,18,29,'Niin Pilatus meni ulos heidän luokseen ja sanoi: "Mikä syytös ja kanne teillä on tätä miestä vastaan?"'),
(1695751,58,43,18,30,'He vastasivat ja sanoivat hänelle: "Jos tämä ei olisi pahantekijä, emme olisi antaneet häntä sinun käsiisi".'),
(1695752,58,43,18,31,'Niin Pilatus sanoi heille: "Ottakaa te hänet ja tuomitkaa hänet lakinne mukaan". Juutalaiset sanoivat hänelle: "Meidän ei ole lupa ketään tappaa";'),
(1695753,58,43,18,32,'että Jeesuksen sana kävisi toteen, jonka hän oli sanonut, antaen tietää, minkälaisella kuolemalla hän oli kuoleva.'),
(1695754,58,43,18,33,'Niin Pilatus meni taas sisälle palatsiin ja kutsui Jeesuksen ja sanoi hänelle: "Oletko sinä juutalaisten kuningas?"'),
(1695755,58,43,18,34,'Jeesus vastasi hänelle: "Itsestäsikö sen sanot, vai ovatko muut sen sinulle minusta sanoneet?"'),
(1695756,58,43,18,35,'Pilatus vastasi: "Olenko minä juutalainen? Oma kansasi ja ylipapit ovat antaneet sinut minun käsiini. Mitä olet tehnyt?"'),
(1695757,58,43,18,36,'Jeesus vastasi: "Minun kuninkuuteni ei ole tästä maailmasta; jos minun kuninkuuteni olisi tästä maailmasta, niin minun palvelijani olisivat taistelleet, ettei minua olisi annettu juutalaisten käsiin; mutta nyt minun kuninkuuteni ei ole täältä".'),
(1695758,58,43,18,37,'Niin Pilatus sanoi hänelle: "Sinä siis kuitenkin olet kuningas?" Jeesus vastasi: "Sinäpä sen sanot, että minä olen kuningas. Sitä varten minä olen syntynyt ja sitä varten maailmaan tullut, että minä todistaisin totuuden puolesta. Jokainen, joka on totuudesta, kuulee minun ääneni."'),
(1695759,58,43,18,38,'Pilatus sanoi hänelle: "Mikä on totuus?" Ja sen sanottuaan hän taas meni ulos juutalaisten luo ja sanoi heille: "Minä en löydä hänessä yhtäkään syytä.'),
(1695760,58,43,18,39,'Mutta te olette tottuneet siihen, että minä päästän teille yhden vangin irti pääsiäisenä; tahdotteko siis, että päästän teille juutalaisten kuninkaan?"'),
(1695761,58,43,18,40,'Niin he taas huusivat sanoen: "Älä häntä, vaan Barabbas!" Mutta Barabbas oli ryöväri.'),
(1695762,58,43,19,1,'Silloin Pilatus otti Jeesuksen ja ruoskitti hänet.'),
(1695763,58,43,19,2,'Ja sotamiehet väänsivät kruunun orjantappuroista, panivat sen hänen päähänsä ja pukivat hänen ylleen purppuraisen vaipan'),
(1695764,58,43,19,3,'ja tulivat hänen luoksensa ja sanoivat: "Terve, juutalaisten kuningas"; ja he antoivat hänelle korvapuusteja.'),
(1695765,58,43,19,4,'Pilatus meni taas ulos ja sanoi heille: "Katso, minä tuon hänet ulos teille, tietääksenne, etten minä löydä hänessä yhtäkään syytä".'),
(1695766,58,43,19,5,'Niin Jeesus tuli ulos, orjantappurakruunu päässään ja purppurainen vaippa yllään. Ja Pilatus sanoi heille: "Katso ihmistä!"'),
(1695767,58,43,19,6,'Kun siis ylipapit ja palvelijat näkivät hänet, huusivat he sanoen: "Ristiinnaulitse, ristiinnaulitse!" Pilatus sanoi heille: "Ottakaa te hänet ja ristiinnaulitkaa, sillä minä en löydä hänessä mitään syytä".'),
(1695768,58,43,19,7,'Juutalaiset vastasivat hänelle: "Meillä on laki, ja lain mukaan hänen pitää kuoleman, koska hän on tehnyt itsensä Jumalan Pojaksi".'),
(1695769,58,43,19,8,'Kun nyt Pilatus kuuli tämän sanan, pelkäsi hän vielä enemmän'),
(1695770,58,43,19,9,'ja meni taas sisälle palatsiin ja sanoi Jeesukselle: "Mistä sinä olet?" Mutta Jeesus ei hänelle vastannut.'),
(1695771,58,43,19,10,'Niin Pilatus sanoi hänelle: "Etkö puhu minulle? Etkö tiedä, että minulla on valta sinut päästää ja minulla on valta sinut ristiinnaulita?"'),
(1695772,58,43,19,11,'Jeesus vastasi: "Sinulla ei olisi mitään valtaa minuun, ellei sitä olisi annettu sinulle ylhäältä. Sentähden on sen synti suurempi, joka jätti minut sinun käsiisi."'),
(1695773,58,43,19,12,'Tämän tähden Pilatus koetti päästää hänet irti. Mutta juutalaiset huusivat sanoen: "Jos päästät hänet, et ole keisarin ystävä; jokainen, joka tekee itsensä kuninkaaksi, asettuu keisaria vastaan".'),
(1695774,58,43,19,13,'Kun Pilatus kuuli nämä sanat, antoi hän viedä Jeesuksen ulos ja istui tuomarinistuimelle, paikalle, jonka nimi on Litostroton, hebreaksi Gabbata.'),
(1695775,58,43,19,14,'Ja oli pääsiäisen valmistuspäivä, noin kuudes hetki. Ja hän sanoi juutalaisille: "Katso, teidän kuninkaanne!"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695776,58,43,19,15,'Niin he huusivat: "Vie pois, vie pois, ristiinnaulitse hänet!" Pilatus sanoi heille: "Onko minun ristiinnaulittava teidän kuninkaanne?" Ylipapit vastasivat: "Ei meillä ole kuningasta, vaan keisari".'),
(1695777,58,43,19,16,'Silloin hän luovutti hänet heille ja antoi ristiinnaulittavaksi. Ja he ottivat Jeesuksen.'),
(1695778,58,43,19,17,'Ja kantaen itse omaa ristiänsä hän meni ulos niin sanotulle Pääkallonpaikalle, jota kutsutaan hebreankielellä Golgataksi.'),
(1695779,58,43,19,18,'Siellä he hänet ristiinnaulitsivat ja hänen kanssaan kaksi muuta, yhden kummallekin puolelle, ja Jeesuksen keskelle.'),
(1695780,58,43,19,19,'Ja Pilatus kirjoitti myös päällekirjoituksen ja kiinnitti sen ristiin; ja se oli näin kirjoitettu: "Jeesus Nasaretilainen, juutalaisten kuningas".'),
(1695781,58,43,19,20,'Tämän päällekirjoituksen lukivat monet juutalaiset, sillä paikka, jossa Jeesus ristiinnaulittiin, oli lähellä kaupunkia; ja se oli kirjoitettu hebreaksi, latinaksi ja kreikaksi.'),
(1695782,58,43,19,21,'Niin juutalaisten ylipapit sanoivat Pilatukselle: "Älä kirjoita: ''Juutalaisten kuningas'', vaan että hän on sanonut: ''Minä olen juutalaisten kuningas''."'),
(1695783,58,43,19,22,'Pilatus vastasi: "Minkä minä kirjoitin, sen minä kirjoitin".'),
(1695784,58,43,19,23,'Kun sotamiehet olivat ristiinnaulinneet Jeesuksen, ottivat he hänen vaatteensa ja jakoivat ne neljään osaan, kullekin sotamiehelle osansa, sekä ihokkaan. Mutta ihokas oli saumaton, kauttaaltaan ylhäältä asti kudottu.'),
(1695785,58,43,19,24,'Sentähden he sanoivat toisillensa: "Älkäämme leikatko sitä rikki, vaan heittäkäämme siitä arpaa, kenen se on oleva"; että tämä kirjoitus kävisi toteen: "He jakoivat keskenänsä minun vaatteeni ja heittivät minun puvustani arpaa". Ja sotamiehet tekivät niin.'),
(1695786,58,43,19,25,'Mutta Jeesuksen ristin ääressä seisoivat hänen äitinsä ja hänen äitinsä sisar ja Maria, Kloopaan vaimo, ja Maria Magdaleena.'),
(1695787,58,43,19,26,'Kun Jeesus näki äitinsä ja sen opetuslapsen, jota hän rakasti, seisovan siinä vieressä, sanoi hän äidillensä: "Vaimo, katso, poikasi!"'),
(1695788,58,43,19,27,'Sitten hän sanoi opetuslapselle: "Katso, äitisi!" Ja siitä hetkestä opetuslapsi otti hänet kotiinsa.'),
(1695789,58,43,19,28,'Sen jälkeen, kun Jeesus tiesi, että kaikki jo oli täytetty, sanoi hän, että kirjoitus kävisi toteen: "Minun on jano".'),
(1695790,58,43,19,29,'Siinä oli astia, hapanviiniä täynnä; niin he täyttivät sillä hapanviinillä sienen ja panivat sen isoppikorren päähän ja ojensivat sen hänen suunsa eteen.'),
(1695791,58,43,19,30,'Kun nyt Jeesus oli ottanut hapanviinin, sanoi hän: "Se on täytetty", ja kallisti päänsä ja antoi henkensä.'),
(1695792,58,43,19,31,'Koska silloin oli valmistuspäivä, niin - etteivät ruumiit jäisi ristille sapatiksi, sillä se sapatinpäivä oli suuri - juutalaiset pyysivät Pilatukselta, että ristiinnaulittujen sääriluut rikottaisiin ja ruumiit otettaisiin alas.'),
(1695793,58,43,19,32,'Niin sotamiehet tulivat ja rikkoivat sääriluut ensin toiselta ja sitten toiselta hänen kanssaan ristiinnaulitulta.'),
(1695794,58,43,19,33,'Mutta kun he tulivat Jeesuksen luo ja näkivät hänet jo kuolleeksi, eivät he rikkoneet hänen luitaan,'),
(1695795,58,43,19,34,'vaan yksi sotamiehistä puhkaisi keihäällä hänen kylkensä, ja heti vuoti siitä verta ja vettä.'),
(1695796,58,43,19,35,'Ja joka sen näki, on sen todistanut, ja hänen todistuksensa on tosi, ja hän tietää totta puhuvansa, että tekin uskoisitte.'),
(1695797,58,43,19,36,'Sillä tämä tapahtui, että kirjoitus kävisi toteen: "Älköön häneltä luuta rikottako".'),
(1695798,58,43,19,37,'Ja vielä sanoo toinen kirjoitus: "He luovat katseensa häneen, jonka he ovat lävistäneet".'),
(1695799,58,43,19,38,'Mutta sen jälkeen Joosef, arimatialainen, joka oli Jeesuksen opetuslapsi, vaikka salaa, juutalaisten pelosta, pyysi Pilatukselta saada ottaa Jeesuksen ruumiin; ja Pilatus myöntyi siihen. Niin hän tuli ja otti Jeesuksen ruumiin.'),
(1695800,58,43,19,39,'Tuli myös Nikodeemus, joka ensi kerran oli yöllä tullut Jeesuksen tykö, ja toi mirhan ja aloen seosta noin sata naulaa.'),
(1695801,58,43,19,40,'Niin he ottivat Jeesuksen ruumiin ja käärivät sen hyvänhajuisten yrttien kanssa käärinliinoihin, niinkuin juutalaisilla on tapana haudata.'),
(1695802,58,43,19,41,'Ja sillä paikalla, missä hänet ristiinnaulittiin, oli puutarha, ja puutarhassa uusi hauta, johon ei vielä oltu ketään pantu.'),
(1695803,58,43,19,42,'Siihen he nyt panivat Jeesuksen, koska oli juutalaisten valmistuspäivä ja se hauta oli lähellä.'),
(1695804,58,43,20,1,'Mutta viikon ensimmäisenä päivänä Maria Magdaleena meni varhain, kun vielä oli pimeä, haudalle ja näki kiven otetuksi pois haudan suulta.'),
(1695805,58,43,20,2,'Niin hän riensi pois ja tuli Simon Pietarin luo ja sen toisen opetuslapsen luo, joka oli Jeesukselle rakas, ja sanoi heille: "Ovat ottaneet Herran pois haudasta, emmekä tiedä, mihin ovat hänet panneet".'),
(1695806,58,43,20,3,'Niin Pietari ja se toinen opetuslapsi lähtivät ja menivät haudalle.'),
(1695807,58,43,20,4,'Ja he juoksivat molemmat yhdessä; mutta se toinen opetuslapsi juoksi edellä, nopeammin kuin Pietari, ja saapui ensin haudalle.'),
(1695808,58,43,20,5,'Ja kun hän kurkisti sisään, näki hän käärinliinat siellä; kuitenkaan hän ei mennyt sisälle.'),
(1695809,58,43,20,6,'Niin Simon Pietarikin tuli hänen perässään ja meni sisälle hautaan ja näki käärinliinat siellä'),
(1695810,58,43,20,7,'ja hikiliinan, joka oli ollut hänen päässään, ei pantuna yhteen käärinliinojen kanssa, vaan toiseen paikkaan erikseen kokoonkäärittynä.'),
(1695811,58,43,20,8,'Silloin toinenkin opetuslapsi, joka ensimmäisenä oli tullut haudalle, meni sisään ja näki ja uskoi.'),
(1695812,58,43,20,9,'Sillä he eivät vielä ymmärtäneet Raamattua, että hän oli kuolleista nouseva.'),
(1695813,58,43,20,10,'Niin opetuslapset menivät takaisin kotiinsa.'),
(1695814,58,43,20,11,'Mutta Maria seisoi haudan edessä ulkopuolella ja itki. Kun hän näin itki, kurkisti hän hautaan'),
(1695815,58,43,20,12,'ja näki kaksi enkeliä valkeissa vaatteissa istuvan, toisen pääpuolessa ja toisen jalkapuolessa, siinä, missä Jeesuksen ruumis oli maannut.'),
(1695816,58,43,20,13,'Nämä sanoivat hänelle: "Vaimo, mitä itket?" Hän sanoi heille: "Ovat ottaneet pois minun Herrani, enkä tiedä, mihin ovat hänet panneet".'),
(1695817,58,43,20,14,'Tämän sanottuaan hän kääntyi taaksepäin ja näki Jeesuksen siinä seisovan, eikä tiennyt, että se oli Jeesus.'),
(1695818,58,43,20,15,'Jeesus sanoi hänelle: "Vaimo, mitä itket? Ketä etsit?" Tämä luuli häntä puutarhuriksi ja sanoi hänelle: "Herra, jos sinä olet kantanut hänet pois, sano minulle, mihin olet hänet pannut, niin minä otan hänet".'),
(1695819,58,43,20,16,'Jeesus sanoi hänelle: "Maria!" Tämä kääntyi ja sanoi hänelle hebreankielellä: "Rabbuuni!" se on: opettaja.'),
(1695820,58,43,20,17,'Jeesus sanoi hänelle: "Älä minuun koske, sillä en minä ole vielä mennyt ylös Isäni tykö; mutta mene minun veljieni tykö ja sano heille, että minä menen ylös, minun Isäni tykö ja teidän Isänne tykö, ja minun Jumalani tykö ja teidän Jumalanne tykö".'),
(1695821,58,43,20,18,'Maria Magdaleena meni ja ilmoitti opetuslapsille, että hän oli nähnyt Herran ja että Herra oli hänelle näin sanonut.'),
(1695822,58,43,20,19,'Samana päivänä, viikon ensimmäisenä, myöhään illalla, kun opetuslapset olivat koolla lukittujen ovien takana, juutalaisten pelosta, tuli Jeesus ja seisoi heidän keskellään ja sanoi heille: "Rauha teille!"'),
(1695823,58,43,20,20,'Ja sen sanottuaan hän näytti heille kätensä ja kylkensä. Niin opetuslapset iloitsivat nähdessään Herran.'),
(1695824,58,43,20,21,'Niin Jeesus sanoi heille jälleen: "Rauha teille! Niinkuin Isä on lähettänyt minut, niin lähetän minäkin teidät."'),
(1695825,58,43,20,22,'Ja tämän sanottuaan hän puhalsi heidän päällensä ja sanoi heille: "Ottakaa Pyhä Henki.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695826,58,43,20,23,'Joiden synnit te anteeksi annatte, niille ne ovat anteeksi annetut; joiden synnit te pidätätte, niille ne ovat pidätetyt."'),
(1695827,58,43,20,24,'Mutta Tuomas, jota sanottiin Didymukseksi, yksi niistä kahdestatoista, ei ollut heidän kanssansa, kun Jeesus tuli.'),
(1695828,58,43,20,25,'Niin muut opetuslapset sanoivat hänelle: "Me näimme Herran". Mutta hän sanoi heille: "Ellen näe hänen käsissään naulojen jälkiä ja pistä sormeani naulojen sijoihin ja pistä kättäni hänen kylkeensä, en minä usko".'),
(1695829,58,43,20,26,'Ja kahdeksan päivän perästä hänen opetuslapsensa taas olivat huoneessa, ja Tuomas oli heidän kanssansa. Niin Jeesus tuli, ovien ollessa lukittuina, ja seisoi heidän keskellään ja sanoi: "Rauha teille!"'),
(1695830,58,43,20,27,'Sitten hän sanoi Tuomaalle: "Ojenna sormesi tänne ja katso minun käsiäni, ja ojenna kätesi ja pistä se minun kylkeeni, äläkä ole epäuskoinen, vaan uskovainen".'),
(1695831,58,43,20,28,'Tuomas vastasi ja sanoi hänelle: "Minun Herrani ja minun Jumalani!"'),
(1695832,58,43,20,29,'Jeesus sanoi hänelle: "Sentähden, että minut näit, sinä uskot. Autuaat ne, jotka eivät näe ja kuitenkin uskovat!"'),
(1695833,58,43,20,30,'Paljon muitakin tunnustekoja, joita ei ole kirjoitettu tähän kirjaan, Jeesus teki opetuslastensa nähden;'),
(1695834,58,43,20,31,'mutta nämä ovat kirjoitetut, että te uskoisitte, että Jeesus on Kristus, Jumalan Poika, ja että teillä uskon kautta olisi elämä hänen nimessänsä.'),
(1695835,58,43,21,1,'Sen jälkeen Jeesus taas ilmestyi opetuslapsilleen Tiberiaan järven rannalla; ja hän ilmestyi näin:'),
(1695836,58,43,21,2,'Simon Pietari ja Tuomas, jota sanottiin Didymukseksi, ja Natanael, joka oli Galilean Kaanasta, ja Sebedeuksen pojat sekä kaksi muuta hänen opetuslapsistaan olivat yhdessä.'),
(1695837,58,43,21,3,'Simon Pietari sanoi heille: "Minä menen kalaan". He sanoivat hänelle: "Me lähdemme myös sinun kanssasi". Niin he lähtivät ja astuivat venheeseen; mutta eivät sinä yönä saaneet mitään.'),
(1695838,58,43,21,4,'Ja kun jo oli aamu, seisoi Jeesus rannalla. Opetuslapset eivät kuitenkaan tienneet, että se oli Jeesus.'),
(1695839,58,43,21,5,'Niin Jeesus sanoi heille: "Lapset, onko teillä mitään syötävää?" He vastasivat hänelle: "Ei ole".'),
(1695840,58,43,21,6,'Hän sanoi heille: "Heittäkää verkko oikealle puolelle venhettä, niin saatte". He heittivät verkon, mutta eivät jaksaneet vetää sitä ylös kalojen paljouden tähden.'),
(1695841,58,43,21,7,'Silloin se opetuslapsi, jota Jeesus rakasti, sanoi Pietarille: "Se on Herra". Kun Simon Pietari kuuli, että se oli Herra, vyötti hän vaippansa ympärilleen, sillä hän oli ilman vaatteita, ja heittäytyi järveen.'),
(1695842,58,43,21,8,'Mutta muut opetuslapset tulivat venheellä ja vetivät perässään verkkoa kaloineen, sillä he eivät olleet maasta kauempana kuin noin kahdensadan kyynärän päässä.'),
(1695843,58,43,21,9,'Kun he astuivat maalle, näkivät he siellä hiilloksen ja kalan pantuna sen päälle, sekä leipää.'),
(1695844,58,43,21,10,'Jeesus sanoi heille: "Tuokaa tänne niitä kaloja, joita nyt saitte".'),
(1695845,58,43,21,11,'Niin Simon Pietari astui venheeseen ja veti maalle verkon, täynnä suuria kaloja, sata viisikymmentä kolme. Ja vaikka niitä oli niin paljon, ei verkko revennyt.'),
(1695846,58,43,21,12,'Jeesus sanoi heille: "Tulkaa einehtimään". Mutta ei kukaan opetuslapsista uskaltanut kysyä häneltä: "Kuka sinä olet?", koska he tiesivät, että se oli Herra.'),
(1695847,58,43,21,13,'Niin Jeesus meni ja otti leivän ja antoi heille, ja samoin kalan.'),
(1695848,58,43,21,14,'Tämä oli jo kolmas kerta, jolloin Jeesus noustuaan kuolleista ilmestyi opetuslapsillensa.'),
(1695849,58,43,21,15,'Kun he olivat einehtineet, sanoi Jeesus Simon Pietarille: "Simon, Johanneksen poika, rakastatko sinä minua enemmän kuin nämä?" Hän vastasi hänelle: "Rakastan, Herra; sinä tiedät, että olet minulle rakas". Hän sanoi hänelle: "Ruoki minun karitsoitani".'),
(1695850,58,43,21,16,'Hän sanoi hänelle taas toistamiseen: "Simon, Johanneksen poika, rakastatko minua?" Hän vastasi hänelle: "Rakastan, Herra; sinä tiedät, että olet minulle rakas". Hän sanoi hänelle: "Kaitse minun lampaitani".'),
(1695851,58,43,21,17,'Hän sanoi hänelle kolmannen kerran: "Simon, Johanneksen poika, olenko minä sinulle rakas?" Pietari tuli murheelliseksi siitä, että hän kolmannen kerran sanoi hänelle: "Olenko minä sinulle rakas?" ja vastasi hänelle: "Herra, sinä tiedät kaikki; sinä tiedät, että olet minulle rakas". Jeesus sanoi hänelle: "Ruoki minun lampaitani.'),
(1695852,58,43,21,18,'Totisesti, totisesti minä sanon sinulle: kun olit nuori, niin sinä vyötit itsesi ja kuljit, minne tahdoit; mutta kun vanhenet, niin sinä ojennat kätesi, ja sinut vyöttää toinen ja vie sinut, minne et tahdo."'),
(1695853,58,43,21,19,'Mutta sen hän sanoi antaakseen tietää, minkäkaltaisella kuolemalla Pietari oli kirkastava Jumalaa. Ja tämän sanottuaan hän lausui hänelle: "Seuraa minua".'),
(1695854,58,43,21,20,'Niin Pietari kääntyi ja näki sen opetuslapsen seuraavan, jota Jeesus rakasti ja joka myös oli aterioitaessa nojannut hänen rintaansa vasten ja sanonut: "Herra, kuka on sinun kavaltajasi?"'),
(1695855,58,43,21,21,'Kun Pietari hänet näki, sanoi hän Jeesukselle: "Herra, kuinka sitten tämän käy?"'),
(1695856,58,43,21,22,'Jeesus sanoi hänelle: "Jos minä tahtoisin, että hän jää tänne siihen asti, kunnes minä tulen, mitä se sinuun koskee? Seuraa sinä minua."'),
(1695857,58,43,21,23,'Niin semmoinen puhe levisi veljien keskuuteen, ettei se opetuslapsi kuole; mutta ei Jeesus sanonut hänelle, ettei hän kuole, vaan: "Jos minä tahtoisin, että hän jää tänne siihen asti, kunnes minä tulen, mitä se sinuun koskee?"'),
(1695858,58,43,21,24,'Tämä on se opetuslapsi, joka todistaa näistä ja on nämä kirjoittanut; ja me tiedämme, että hänen todistuksensa on tosi.'),
(1695859,58,43,21,25,'On paljon muutakin, mitä Jeesus teki; ja jos se kohta kohdalta kirjoitettaisiin. luulen, etteivät koko maailmaan mahtuisi ne kirjat, jotka pitäisi kirjoittaa.'),
(1695860,58,44,1,1,'Edellisessä kertomuksessani kirjoitin, oi Teofilus, kaikesta, mitä Jeesus alkoi tehdä ja opettaa,'),
(1695861,58,44,1,2,'hamaan siihen päivään asti, jona hänet otettiin ylös, sittenkun hän Pyhän Hengen kautta oli antanut käskynsä apostoleille, jotka hän oli valinnut,'),
(1695862,58,44,1,3,'ja joille hän myös kärsimisensä jälkeen moninaisten epäämättömien todistusten kautta osoitti elävänsä, ilmestyen heille neljänkymmenen päivän aikana ja puhuen Jumalan valtakunnasta.'),
(1695863,58,44,1,4,'Ja kun hän oli yhdessä heidän kanssansa, käski hän heitä ja sanoi: "Älkää lähtekö Jerusalemista, vaan odottakaa Isältä sen lupauksen täyttymistä, jonka te olette minulta kuulleet.'),
(1695864,58,44,1,5,'Sillä Johannes kastoi vedellä, mutta teidät kastetaan Pyhällä Hengellä, ei kauan näitten päivien jälkeen."'),
(1695865,58,44,1,6,'Niin he ollessansa koolla kysyivät häneltä sanoen: "Herra, tälläkö ajalla sinä jälleen rakennat Israelille valtakunnan?"'),
(1695866,58,44,1,7,'Hän sanoi heille: "Ei ole teidän asianne tietää aikoja eikä hetkiä, jotka Isä oman valtansa voimalla on asettanut,'),
(1695867,58,44,1,8,'vaan, kun Pyhä Henki tulee teihin, niin te saatte voiman, ja te tulette olemaan minun todistajani sekä Jerusalemissa että koko Juudeassa ja Samariassa ja aina maan ääriin saakka".'),
(1695868,58,44,1,9,'Kun hän oli tämän sanonut, kohotettiin hänet ylös heidän nähtensä, ja pilvi vei hänet pois heidän näkyvistään.'),
(1695869,58,44,1,10,'Ja kun he katselivat taivaalle hänen mennessään, niin katso, heidän tykönänsä seisoi kaksi miestä valkeissa vaatteissa;'),
(1695870,58,44,1,11,'ja nämä sanoivat: "Galilean miehet, mitä te seisotte ja katsotte taivaalle? Tämä Jeesus, joka otettiin teiltä ylös taivaaseen, on tuleva samalla tavalla, kuin te näitte hänen taivaaseen menevän."'),
(1695871,58,44,1,12,'Silloin he palasivat Jerusalemiin vuorelta, jota kutsutaan Öljymäeksi ja joka on lähellä Jerusalemia, sapatinmatkan päässä.'),
(1695872,58,44,1,13,'Ja kun he olivat tulleet kaupunkiin, menivät he siihen yläsaliin, jossa he tavallisesti oleskelivat: Pietari ja Johannes ja Jaakob ja Andreas, Filippus ja Tuomas, Bartolomeus ja Matteus, Jaakob Alfeuksen poika ja Simon, kiivailija, ja Juudas Jaakobin poika.'),
(1695873,58,44,1,14,'Nämä kaikki pysyivät yksimielisesti rukouksessa vaimojen kanssa ja Marian, Jeesuksen äidin, kanssa ja Jeesuksen veljien kanssa.'),
(1695874,58,44,1,15,'Ja niinä päivinä Pietari nousi veljien keskellä, kun oli väkeä koolla noin sata kaksikymmentä henkeä, ja sanoi:'),
(1695875,58,44,1,16,'"Miehet, veljet, sen raamatunsanan piti käymän toteen, jonka Pyhä Henki on Daavidin suun kautta edeltä puhunut Juudaasta, joka rupesi niiden oppaaksi, jotka ottivat kiinni Jeesuksen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695876,58,44,1,17,'Sillä hän oli meidän joukkoomme luettu ja oli saanut osalleen tämän viran.'),
(1695877,58,44,1,18,'Hän hankki itsellensä pellon väärintekonsa palkalla, ja hän suistui alas ja pakahtui keskeltä, niin että kaikki hänen sisälmyksensä valuivat ulos.'),
(1695878,58,44,1,19,'Ja se tuli kaikkien Jerusalemin asukasten tietoon; ja niin sitä peltoa kutsutaan heidän kielellään Akeldamaksi, se on: Veripelloksi.'),
(1695879,58,44,1,20,'Sillä psalmien kirjassa on kirjoitettuna: ''Tulkoon hänen talonsa autioksi, älköönkä siinä asukasta olko'', ja: Ottakoon toinen hänen kaitsijatoimensa''.'),
(1695880,58,44,1,21,'Niin pitää siis yhden niistä miehistä, jotka ovat vaeltaneet meidän kanssamme kaiken sen ajan, jona Herra Jeesus kävi sisälle ja ulos meidän tykönämme,'),
(1695881,58,44,1,22,'Johanneksen kasteesta alkaen hamaan siihen päivään, jona hänet meiltä otettiin ylös, tuleman hänen ylösnousemisensa todistajaksi meidän kanssamme."'),
(1695882,58,44,1,23,'Ja he asettivat ehdolle kaksi, Joosefin, jota kutsuttiin Barsabbaaksi, lisänimeltä Justukseksi, ja Mattiaan.'),
(1695883,58,44,1,24,'Ja he rukoilivat ja sanoivat: "Herra, sinä, joka kaikkien sydämet tunnet, osoita, kummanko näistä kahdesta sinä olet valinnut'),
(1695884,58,44,1,25,'ottamaan sen paikan tässä palveluksessa ja apostolinvirassa, josta Juudas vilpistyi pois, mennäkseen omaan paikkaansa".'),
(1695885,58,44,1,26,'Ja he heittivät heistä arpaa, ja arpa lankesi Mattiaalle, ja hänet luettiin niiden yhdentoista kanssa apostolien joukkoon.'),
(1695886,58,44,2,1,'Ja kun helluntaipäivä oli tullut, olivat he kaikki yhdessä koolla.'),
(1695887,58,44,2,2,'Ja tuli yhtäkkiä humaus taivaasta, niinkuin olisi käynyt väkevä tuulispää, ja täytti koko huoneen, jossa he istuivat.'),
(1695888,58,44,2,3,'Ja he näkivät ikäänkuin tulisia kieliä, jotka jakaantuivat ja asettuivat heidän itsekunkin päälle.'),
(1695889,58,44,2,4,'Ja he tulivat kaikki Pyhällä Hengellä täytetyiksi ja alkoivat puhua muilla kielillä, sen mukaan mitä Henki heille puhuttavaksi antoi.'),
(1695890,58,44,2,5,'Ja Jerusalemissa asui juutalaisia, jumalaapelkääväisiä miehiä, kaikkinaisista kansoista, mitä taivaan alla on.'),
(1695891,58,44,2,6,'Ja kun tämä ääni kuului, niin kokoontui paljon kansaa; ja he tulivat ymmälle, sillä kukin kuuli heidän puhuvan hänen omaa kieltänsä.'),
(1695892,58,44,2,7,'Ja he hämmästyivät ja ihmettelivät sanoen: "Katso, eivätkö nämä kaikki, jotka puhuvat, ole galilealaisia?'),
(1695893,58,44,2,8,'Kuinka me sitten kuulemme kukin sen maan kieltä, jossa olemme syntyneet?'),
(1695894,58,44,2,9,'Me parttilaiset ja meedialaiset ja eelamilaiset ja me, jotka asumme Mesopotamiassa, Juudeassa ja Kappadokiassa, Pontossa ja Aasiassa,'),
(1695895,58,44,2,10,'Frygiassa ja Pamfyliassa, Egyptissä ja Kyrenen puoleisen Liibyan alueilla, ja täällä oleskelevat roomalaiset, juutalaiset ja käännynnäiset,'),
(1695896,58,44,2,11,'kreetalaiset ja arabialaiset, me kuulemme kukin heidän puhuvan omalla kielellämme Jumalan suuria tekoja."'),
(1695897,58,44,2,12,'Ja he olivat kaikki hämmästyksissään eivätkä tienneet, mitä ajatella, ja sanoivat toinen toisellensa: "Mitä tämä mahtaakaan olla?"'),
(1695898,58,44,2,13,'Mutta toiset pilkkasivat heitä ja sanoivat: "He ovat täynnä makeata viiniä".'),
(1695899,58,44,2,14,'Niin Pietari astui esiin niiden yhdentoista kanssa, korotti äänensä ja puhui heille: "Miehet, juutalaiset ja kaikki Jerusalemissa asuvaiset, olkoon tämä teille tiettävä, ja ottakaa minun sanani korviinne.'),
(1695900,58,44,2,15,'Eivät nämä ole juovuksissa, niinkuin te luulette; sillä nyt on vasta kolmas hetki päivästä.'),
(1695901,58,44,2,16,'Vaan tämä on se, mikä on sanottu profeetta Jooelin kautta:'),
(1695902,58,44,2,17,'''Ja on tapahtuva viimeisinä päivinä, sanoo Jumala, että minä vuodatan Henkeni kaiken lihan päälle, ja teidän poikanne ja tyttärenne ennustavat, ja nuorukaisenne näkyjä näkevät, ja vanhuksenne unia uneksuvat.'),
(1695903,58,44,2,18,'Ja myös palvelijaini ja palvelijattarieni päälle minä niinä päivinä vuodatan Henkeni, ja he ennustavat.'),
(1695904,58,44,2,19,'Ja minä annan näkyä ihmeitä ylhäällä taivaalla ja merkkejä alhaalla maan päällä, verta ja tulta ja savupatsaita.'),
(1695905,58,44,2,20,'Aurinko muuttuu pimeydeksi ja kuu vereksi, ennenkuin Herran päivä tulee, se suuri ja julkinen.'),
(1695906,58,44,2,21,'Ja on tapahtuva, että jokainen, joka huutaa avuksi Herran nimeä, pelastuu.'''),
(1695907,58,44,2,22,'Te Israelin miehet, kuulkaa nämä sanat: Jeesuksen, Nasaretilaisen, sen miehen, josta Jumala todisti teille voimallisilla teoilla ja ihmeillä ja merkeillä, joita Jumala hänen kauttansa teki teidän keskellänne, niinkuin te itse tiedätte,'),
(1695908,58,44,2,23,'hänet, joka teille luovutettiin, Jumalan ennaltamäärätyn päätöksen ja edeltätietämyksen mukaan, te laista tietämättömien miesten kätten kautta naulitsitte ristille ja tapoitte.'),
(1695909,58,44,2,24,'Hänet Jumala herätti ja päästi kuoleman kivuista, niinkuin ei ollutkaan mahdollista, että kuolema olisi voinut hänet pitää.'),
(1695910,58,44,2,25,'Sillä Daavid sanoo hänestä: ''Minä näen alati edessäni Herran, sillä hän on minun oikealla puolellani, etten horjahtaisi.'),
(1695911,58,44,2,26,'Sentähden minun sydämeni iloitsee ja kieleni riemuitsee, ja myös minun ruumiini on lepäävä toivossa;'),
(1695912,58,44,2,27,'sillä sinä et hylkää minun sieluani tuonelaan etkä salli Pyhäsi nähdä katoavaisuutta.'),
(1695913,58,44,2,28,'Sinä teet minulle tiettäviksi elämän tiet, sinä täytät minut ilolla kasvojesi edessä.'''),
(1695914,58,44,2,29,'Te miehet, veljet, on lupa teille rohkeasti sanoa, mitä kantaisäämme Daavidiin tulee, että hän on sekä kuollut että haudattu; onhan hänen hautansa meidän keskellämme vielä tänäkin päivänä.'),
(1695915,58,44,2,30,'Koska hän nyt oli profeetta ja tiesi, että Jumala oli valalla vannoen hänelle luvannut asettavansa hänen kupeittensa hedelmän hänen valtaistuimelleen,'),
(1695916,58,44,2,31,'niin hän edeltä nähden puhui Kristuksen ylösnousemuksesta, sanoen, ettei Kristus ollut jäävä hyljätyksi tuonelaan eikä hänen ruumiinsa näkevä katoavaisuutta.'),
(1695917,58,44,2,32,'Tämän Jeesuksen on Jumala herättänyt, minkä todistajia me kaikki olemme.'),
(1695918,58,44,2,33,'Koska hän siis on Jumalan oikean käden voimalla korotettu ja on Isältä saanut Pyhän Hengen lupauksen, on hän vuodattanut sen, minkä te nyt näette ja kuulette.'),
(1695919,58,44,2,34,'Sillä ei Daavid ole astunut ylös taivaisiin, vaan hän sanoo itse: ''Herra sanoi minun Herralleni: Istu minun oikealle puolelleni,'),
(1695920,58,44,2,35,'kunnes minä panen sinun vihollisesi sinun jalkojesi astinlaudaksi.'''),
(1695921,58,44,2,36,'Varmasti tietäköön siis koko Israelin huone, että Jumala on hänet Herraksi ja Kristukseksi tehnyt, tämän Jeesuksen, jonka te ristiinnaulitsitte."'),
(1695922,58,44,2,37,'Kun he tämän kuulivat, saivat he piston sydämeensä ja sanoivat Pietarille ja muille apostoleille: "Miehet, veljet, mitä meidän pitää tekemän?"'),
(1695923,58,44,2,38,'Niin Pietari sanoi heille: "Tehkää parannus ja ottakoon kukin teistä kasteen Jeesuksen Kristuksen nimeen syntienne anteeksisaamiseksi, niin te saatte Pyhän Hengen lahjan.'),
(1695924,58,44,2,39,'Sillä teille ja teidän lapsillenne tämä lupaus on annettu ja kaikille, jotka kaukana ovat, ketkä ikinä Herra, meidän Jumalamme, kutsuu."'),
(1695925,58,44,2,40,'Ja monilla muillakin sanoilla hän vakaasti todisti; ja hän kehoitti heitä sanoen: "Antakaa pelastaa itsenne tästä nurjasta sukupolvesta".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695926,58,44,2,41,'Jotka nyt ottivat hänen sanansa vastaan, ne kastettiin, ja niin heitä lisääntyi sinä päivänä noin kolmetuhatta sielua.'),
(1695927,58,44,2,42,'Ja he pysyivät apostolien opetuksessa ja keskinäisessä yhteydessä ja leivän murtamisessa ja rukouksissa.'),
(1695928,58,44,2,43,'Ja jokaiselle sielulle tuli pelko; ja monta ihmettä ja tunnustekoa tapahtui apostolien kautta.'),
(1695929,58,44,2,44,'Ja kaikki, jotka uskoivat, olivat yhdessä ja pitivät kaikkea yhteisenä,'),
(1695930,58,44,2,45,'ja he myivät maansa ja tavaransa ja jakelivat kaikille, sen mukaan kuin kukin tarvitsi.'),
(1695931,58,44,2,46,'Ja he olivat alati, joka päivä, yksimielisesti pyhäkössä ja mursivat kodeissa leipää ja nauttivat ruokansa riemulla ja sydämen yksinkertaisuudella,'),
(1695932,58,44,2,47,'kiittäen Jumalaa ja ollen kaiken kansan suosiossa. Ja Herra lisäsi heidän yhteyteensä joka päivä niitä, jotka saivat pelastuksen.'),
(1695933,58,44,3,1,'Ja Pietari ja Johannes menivät pyhäkköön yhdeksännellä hetkellä, rukoushetkellä.'),
(1695934,58,44,3,2,'Silloin kannettiin esille miestä, joka oli ollut rampa hamasta äitinsä kohdusta ja jonka he joka päivä panivat pyhäkön niin kutsutun Kauniin portin pieleen anomaan almua pyhäkköön meneviltä.'),
(1695935,58,44,3,3,'Nähdessään Pietarin ja Johanneksen, kun he olivat menossa pyhäkköön, hän pyysi heiltä almua.'),
(1695936,58,44,3,4,'Niin Pietari ja Johannes katsoivat häneen kiinteästi, ja Pietari sanoi: "Katso meihin".'),
(1695937,58,44,3,5,'Ja hän tarkkasi heitä odottaen heiltä jotakin saavansa.'),
(1695938,58,44,3,6,'Niin Pietari sanoi: "Hopeaa ja kultaa ei minulla ole, mutta mitä minulla on, sitä minä sinulle annan: Jeesuksen Kristuksen, Nasaretilaisen, nimessä, nouse ja käy."'),
(1695939,58,44,3,7,'Ja hän tarttui hänen oikeaan käteensä ja nosti hänet ylös; ja heti hänen jalkansa ja nilkkansa vahvistuivat,'),
(1695940,58,44,3,8,'ja hän hypähti pystyyn, seisoi ja käveli; ja hän meni heidän kanssansa pyhäkköön, käyden ja hypellen ja ylistäen Jumalaa.'),
(1695941,58,44,3,9,'Ja kaikki kansa näki hänen kävelevän ja ylistävän Jumalaa;'),
(1695942,58,44,3,10,'ja he tunsivat hänet siksi, joka almuja saadakseen oli istunut pyhäkön Kauniin portin pielessä, ja he olivat täynnä hämmästystä ja ihmettelyä siitä, mikä hänelle oli tapahtunut.'),
(1695943,58,44,3,11,'Ja kun hän yhä pysyttäytyi Pietarin ja Johanneksen seurassa, riensi kaikki kansa hämmästyksen vallassa heidän luoksensa niin sanottuun Salomon pylväskäytävään.'),
(1695944,58,44,3,12,'Sen nähdessään Pietari rupesi puhumaan kansalle ja sanoi: "Israelin miehet, mitä te tätä ihmettelette, tai mitä te meitä noin katselette, ikäänkuin me omalla voimallamme tai hurskaudellamme olisimme saaneet hänet kävelemään.'),
(1695945,58,44,3,13,'Aabrahamin ja Iisakin ja Jaakobin Jumala, meidän isiemme Jumala, on kirkastanut Poikansa Jeesuksen, jonka te annoitte alttiiksi ja kielsitte Pilatuksen edessä, kun tämä oli päättänyt hänet päästää.'),
(1695946,58,44,3,14,'Te kielsitte Pyhän ja Vanhurskaan ja anoitte, että teille annettaisiin murhamies,'),
(1695947,58,44,3,15,'mutta elämän ruhtinaan te tapoitte; hänet Jumala on herättänyt kuolleista, ja me olemme sen todistajat.'),
(1695948,58,44,3,16,'Ja uskon kautta hänen nimeensä on hänen nimensä vahvistanut tämän miehen, jonka te näette ja tunnette, ja usko, jonka Jeesus vaikuttaa, on hänelle antanut hänen jäsentensä terveyden kaikkien teidän nähtenne.'),
(1695949,58,44,3,17,'Ja nyt, veljet, minä tiedän, että te olette tietämättömyydestä sen tehneet, te niinkuin teidän hallitusmiehennekin.'),
(1695950,58,44,3,18,'Mutta näin on Jumala täyttänyt sen, minkä hän oli edeltä ilmoittanut kaikkien profeettain suun kautta, että nimittäin hänen Voideltunsa piti kärsimän.'),
(1695951,58,44,3,19,'Tehkää siis parannus ja kääntykää, että teidän syntinne pyyhittäisiin pois,'),
(1695952,58,44,3,20,'että virvoituksen ajat tulisivat Herran kasvoista ja hän lähettäisi hänet, joka on teille edeltämäärätty, Kristuksen Jeesuksen.'),
(1695953,58,44,3,21,'Taivaan piti omistaman hänet niihin aikoihin asti, jolloin kaikki jälleen kohdallensa asetetaan, mistä Jumala on ikiajoista saakka puhunut pyhäin profeettainsa suun kautta.'),
(1695954,58,44,3,22,'Sillä Mooses on sanonut: ''Profeetan, minun kaltaiseni, Herra Jumala on teille herättävä veljienne joukosta; häntä kuulkaa kaikessa, mitä hän teille puhuu.'),
(1695955,58,44,3,23,'Ja on tapahtuva, että jokainen, joka ei sitä profeettaa kuule, hävitetään kansasta.'''),
(1695956,58,44,3,24,'Ja kaikki profeetat Samuelista alkaen ja kaikki järjestään, jotka puhuneet ovat, ovat myös ennustaneet näitä päiviä.'),
(1695957,58,44,3,25,'Te olette profeettain ja sen liiton lapsia, jonka Jumala teki meidän isiemme kanssa sanoen Aabrahamille: ''Ja sinun siemenessäsi tulevat siunatuiksi kaikki maan sukukunnat''.'),
(1695958,58,44,3,26,'Teille ensiksi Jumala on herättänyt Poikansa ja lähettänyt hänet siunaamaan teitä, kun käännytte itsekukin pois pahuudestanne."'),
(1695959,58,44,4,1,'Mutta kun he puhuivat kansalle, astuivat papit ja pyhäkön vartioston päällikkö ja saddukeukset heidän eteensä,'),
(1695960,58,44,4,2,'närkästyneinä siitä, että he opettivat kansaa ja julistivat Jeesuksessa ylösnousemusta kuolleista.'),
(1695961,58,44,4,3,'Ja he kävivät heihin käsiksi ja panivat heidät vankeuteen seuraavaan päivään asti, sillä oli jo ehtoo.'),
(1695962,58,44,4,4,'Mutta monet niistä, jotka olivat kuulleet sanan, uskoivat, ja miesten luku nousi noin viiteentuhanteen.'),
(1695963,58,44,4,5,'Seuraavana päivänä heidän hallitusmiehensä ja vanhimpansa ja kirjanoppineensa kokoontuivat Jerusalemissa,'),
(1695964,58,44,4,6,'niin myös ylimmäinen pappi Hannas ja Kaifas ja Johannes ja Aleksander sekä kaikki, jotka olivat ylimmäispapillista sukua.'),
(1695965,58,44,4,7,'Ja he asettivat heidät eteensä ja kysyivät: "Millä voimalla tai kenen nimeen te tämän teitte?"'),
(1695966,58,44,4,8,'Silloin Pietari, Pyhää Henkeä täynnä, sanoi heille: "Kansan hallitusmiehet ja vanhimmat!'),
(1695967,58,44,4,9,'Jos meitä tänään kuulustellaan sairaalle miehelle tehdystä hyvästä työstä ja siitä, kenen kautta hän on parantunut,'),
(1695968,58,44,4,10,'niin olkoon teille kaikille ja koko Israelin kansalle tiettävä, että Jeesuksen Kristuksen, Nasaretilaisen, nimen kautta, hänen, jonka te ristiinnaulitsitte, mutta jonka Jumala kuolleista herätti, hänen nimensä kautta tämä seisoo terveenä teidän edessänne.'),
(1695969,58,44,4,11,'Hän on ''se kivi, jonka te, rakentajat, hylkäsitte, mutta joka on kulmakiveksi tullut''.'),
(1695970,58,44,4,12,'Eikä ole pelastusta yhdessäkään toisessa; sillä ei ole taivaan alla muuta nimeä ihmisille annettu, jossa meidän pitäisi pelastuman."'),
(1695971,58,44,4,13,'Mutta kun he näkivät Pietarin ja Johanneksen rohkeuden ja havaitsivat heidän olevan koulunkäymättömiä ja oppimattomia miehiä, he ihmettelivät; ja he tunsivat heidät niiksi, jotka olivat olleet Jeesuksen kanssa.'),
(1695972,58,44,4,14,'Ja nähdessään parannetun miehen seisovan heidän kanssansa he eivät voineet mitään vastaansanoa,'),
(1695973,58,44,4,15,'vaan käskettyään heidän astua ulos neuvostosta he pitivät keskenänsä neuvoa'),
(1695974,58,44,4,16,'ja sanoivat: "Mitä me teemme näille miehille? Sillä että heidän kauttansa on tapahtunut ilmeinen ihme, sen kaikki Jerusalemin asukkaat tietävät, emmekä me voi sitä kieltää.'),
(1695975,58,44,4,17,'Mutta ettei se leviäisi laajemmalle kansaan, niin kieltäkäämme ankarasti heitä enää tähän nimeen puhumasta yhdellekään ihmiselle."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1695976,58,44,4,18,'Niin he kutsuivat heidät ja kielsivät heitä mitään puhumasta ja opettamasta Jeesuksen nimeen.'),
(1695977,58,44,4,19,'Mutta Pietari ja Johannes vastasivat heille ja sanoivat: "Päättäkää itse, onko oikein Jumalan edessä kuulla teitä enemmän kuin Jumalaa;'),
(1695978,58,44,4,20,'mutta me emme voi olla puhumatta siitä, mitä olemme nähneet ja kuulleet".'),
(1695979,58,44,4,21,'Niin he uhkasivat heitä vielä enemmän ja päästivät heidät, koska eivät kansan tähden keksineet, miten rangaista heitä, sillä kaikki ylistivät Jumalaa siitä, mitä tapahtunut oli.'),
(1695980,58,44,4,22,'Sillä sivu neljänkymmenen oli jo vuosiltaan se mies, jossa tämä parantumisen ihme oli tapahtunut.'),
(1695981,58,44,4,23,'Ja päästyään vapaiksi he menivät omiensa tykö ja kertoivat kaiken, mitä ylipapit ja vanhimmat olivat heille sanoneet.'),
(1695982,58,44,4,24,'Sen kuultuansa he yksimielisesti korottivat äänensä Jumalan puoleen ja sanoivat: "Herra, sinä, joka olet tehnyt taivaan ja maan ja meren ja kaikki, mitä niissä on!'),
(1695983,58,44,4,25,'Sinä, joka Pyhän Hengen kautta, isämme Daavidin, sinun palvelijasi, suun kautta, olet puhunut: ''Miksi pakanat pauhaavat ja kansat turhia ajattelevat?'),
(1695984,58,44,4,26,'Maan kuninkaat nousevat, ja ruhtinaat kokoontuvat yhteen Herraa ja hänen Voideltuansa vastaan.'''),
(1695985,58,44,4,27,'Sillä totisesti, tässä kaupungissa kokoontuivat sinun pyhää Poikaasi Jeesusta vastaan, jonka sinä olet voidellut, sekä Herodes että Pontius Pilatus pakanain ja Israelin sukukuntain kanssa,'),
(1695986,58,44,4,28,'tekemään kaiken, minkä sinun kätesi ja päätöksesi oli edeltämäärännyt tapahtuvaksi.'),
(1695987,58,44,4,29,'Ja nyt, Herra, katso heidän uhkauksiansa ja anna palvelijaisi kaikella rohkeudella puhua sinun sanaasi;'),
(1695988,58,44,4,30,'ja ojenna kätesi, niin että sairaat parantuvat ja tunnustekoja ja ihmeitä tapahtuu sinun pyhän Poikasi Jeesuksen nimen kautta."'),
(1695989,58,44,4,31,'Ja kun he olivat rukoilleet, vapisi se paikka, jossa he olivat koolla, ja he tulivat kaikki Pyhällä Hengellä täytetyiksi ja puhuivat Jumalan sanaa rohkeasti.'),
(1695990,58,44,4,32,'Ja uskovaisten suuressa joukossa oli yksi sydän ja yksi sielu; eikä kenkään heistä sanonut omaksensa mitään siitä, mitä hänellä oli, vaan kaikki oli heillä yhteistä.'),
(1695991,58,44,4,33,'Ja apostolit todistivat suurella voimalla Herran Jeesuksen ylösnousemuksesta, ja suuri armo oli heillä kaikilla.'),
(1695992,58,44,4,34,'Ei myöskään ollut heidän seassaan ketään puutteenalaista; sillä kaikki, joilla oli maatiloja tai taloja, myivät ne ja toivat myytyjen hinnan'),
(1695993,58,44,4,35,'ja panivat apostolien jalkojen juureen; ja jokaiselle jaettiin sen mukaan, kuin hän tarvitsi.'),
(1695994,58,44,4,36,'Niinpä Joosef, jota apostolit kutsuivat Barnabaaksi - se on käännettynä: kehoittaja - leeviläinen, syntyisin Kyprosta,'),
(1695995,58,44,4,37,'myi omistamansa pellon, toi rahat ja pani ne apostolien jalkojen juureen.'),
(1695996,58,44,5,1,'Mutta eräs mies, nimeltä Ananias, ja hänen vaimonsa Safiira myivät maatilan,'),
(1695997,58,44,5,2,'ja mies kätki vaimonsa tieten osan hinnasta, ja osan hän toi ja pani apostolien jalkojen eteen.'),
(1695998,58,44,5,3,'Mutta Pietari sanoi: "Ananias, miksi on saatana täyttänyt sinun sydämesi, niin että koetit pettää Pyhää Henkeä ja kätkit osan maatilan hinnasta?'),
(1695999,58,44,5,4,'Eikö se myymätönnä ollut sinun omasi, ja eikö myynnin jälkeenkin sen hinta ollut sinun? Miksi päätit sydämessäsi tämän tehdä? Et sinä ole valhetellut ihmisille, vaan Jumalalle."'),
(1696000,58,44,5,5,'Kun Ananias kuuli nämä sanat, kaatui hän maahan ja heitti henkensä. Ja suuri pelko valtasi kaikki, jotka sen kuulivat.'),
(1696001,58,44,5,6,'Ja nuoret miehet nousivat ja korjasivat hänet ja kantoivat hänet pois ja hautasivat.'),
(1696002,58,44,5,7,'Noin kolmen hetken kuluttua hänen vaimonsa tuli sisään eikä tiennyt, mitä oli tapahtunut.'),
(1696003,58,44,5,8,'Niin Pietari kysyi häneltä: "Sano minulle: siihenkö hintaan te myitte maatilan?" Hän vastasi: "Kyllä, juuri siihen hintaan".'),
(1696004,58,44,5,9,'Mutta Pietari sanoi hänelle: "Miksi olette yksissä neuvoin käyneet kiusaamaan Herran Henkeä? Katso, niiden jalat, jotka hautasivat sinun miehesi, ovat oven takana, ja he kantavat sinutkin pois."'),
(1696005,58,44,5,10,'Niin hän heti kaatui hänen jalkojensa eteen ja heitti henkensä; ja kun nuorukaiset tulivat sisään, tapasivat he hänet kuolleena, kantoivat pois ja hautasivat hänet hänen miehensä viereen.'),
(1696006,58,44,5,11,'Ja suuri pelko valtasi koko seurakunnan ja kaikki ne, jotka tämän kuulivat.'),
(1696007,58,44,5,12,'Ja apostolien kätten kautta tapahtui kansassa monta tunnustekoa ja ihmettä; ja he olivat kaikki yksimielisesti koolla Salomon pylväskäytävässä.'),
(1696008,58,44,5,13,'Eikä muista kukaan uskaltanut heihin liittyä, mutta kansa piti heitä suuressa kunniassa.'),
(1696009,58,44,5,14,'Ja yhä enemmän karttui niitä, jotka uskoivat Herraan, sekä miehiä että naisia suuret joukot.'),
(1696010,58,44,5,15,'Kannettiinpa sairaita kaduillekin ja pantiin vuoteille ja paareille, että Pietarin kulkiessa edes hänen varjonsa sattuisi johonkuhun heistä.'),
(1696011,58,44,5,16,'Myöskin kaupungeista Jerusalemin ympäriltä tuli paljon kansaa, ja he toivat sairaita ja saastaisten henkien vaivaamia, ja ne kaikki tulivat parannetuiksi.'),
(1696012,58,44,5,17,'Silloin nousi ylimmäinen pappi ja kaikki, jotka olivat hänen puolellansa, saddukeusten lahko, ja he tulivat kiihkoa täyteen'),
(1696013,58,44,5,18,'ja kävivät käsiksi apostoleihin ja panivat heidät yleiseen vankihuoneeseen.'),
(1696014,58,44,5,19,'Mutta yöllä avasi Herran enkeli vankilan ovet ja vei heidät ulos ja sanoi:'),
(1696015,58,44,5,20,'"Menkää ja astukaa esiin ja puhukaa pyhäkössä kansalle kaikki tämän elämän sanat".'),
(1696016,58,44,5,21,'Sen kuultuansa he menivät päivän koittaessa pyhäkköön ja opettivat. Niin saapui ylimmäinen pappi ja ne, jotka olivat hänen puolellansa, ja he kutsuivat koolle neuvoston ja israelilaisten vanhinten kokouksen; ja he lähettivät noutamaan heitä vankilasta.'),
(1696017,58,44,5,22,'Mutta kun oikeudenpalvelijat tulivat vankilaan, eivät he löytäneet heitä sieltä, vaan palasivat takaisin ja kertoivat,'),
(1696018,58,44,5,23,'sanoen: "Vankilan me kyllä huomasimme hyvin tarkasti suljetuksi ja vartijat seisomassa ovien edessä; mutta kun avasimme, emme sisältä ketään löytäneet".'),
(1696019,58,44,5,24,'Kun pyhäkön vartioston päällikkö ja ylipapit kuulivat nämä sanat, eivät he tienneet, mitä heistä ajatella ja mitä tästä tulisi.'),
(1696020,58,44,5,25,'Niin tuli joku ja kertoi heille: "Katso, ne miehet, jotka te panitte vankilaan, seisovat pyhäkössä ja opettavat kansaa".'),
(1696021,58,44,5,26,'Silloin päällikkö meni oikeudenpalvelijain kanssa ja nouti heidät; ei kuitenkaan väkisin, sillä he pelkäsivät, että kansa heidät kivittäisi.'),
(1696022,58,44,5,27,'Ja he toivat heidät ja asettivat neuvoston eteen. Ja ylimmäinen pappi kuulusteli heitä'),
(1696023,58,44,5,28,'ja sanoi: "Me olemme kieltämällä kieltäneet teitä opettamasta tähän nimeen; ja katso, te olette täyttäneet Jerusalemin opetuksellanne ja tahdotte saattaa meidän päällemme tuon miehen veren".'),
(1696024,58,44,5,29,'Mutta Pietari ja muut apostolit vastasivat ja sanoivat: "Enemmän tulee totella Jumalaa kuin ihmisiä.'),
(1696025,58,44,5,30,'Meidän isiemme Jumala on herättänyt Jeesuksen, jonka te ripustitte puuhun ja surmasitte.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696026,58,44,5,31,'Hänet on Jumala oikealla kädellänsä korottanut Päämieheksi ja Vapahtajaksi, antamaan Israelille parannusta ja syntien anteeksiantamusta.'),
(1696027,58,44,5,32,'Ja me olemme kaiken tämän todistajat, niin myös Pyhä Henki, jonka Jumala on antanut niille, jotka häntä tottelevat."'),
(1696028,58,44,5,33,'Kun he sen kuulivat, viilsi se heidän sydäntänsä, ja he tahtoivat tappaa heidät.'),
(1696029,58,44,5,34,'Mutta neuvostossa nousi eräs fariseus, nimeltä Gamaliel, lainopettaja, jota koko kansa piti arvossa, ja hän käski viedä miehet vähäksi aikaa ulos.'),
(1696030,58,44,5,35,'Sitten hän sanoi neuvostolle: "Israelin miehet, kavahtakaa, mitä aiotte tehdä näille miehille.'),
(1696031,58,44,5,36,'Sillä ennen näitä päiviä nousi Teudas, sanoen jokin olevansa, ja häneen liittyi noin neljäsataa miestä; hänet tapettiin, ja kaikki, jotka olivat häneen suostuneet, hajotettiin, ja he joutuivat häviöön.'),
(1696032,58,44,5,37,'Hänen jälkeensä nousi Juudas, galilealainen, verollepanon päivinä ja vietteli kansaa luopumaan puolellensa; hänkin hukkui, ja kaikki, jotka olivat suostuneet häneen, hajotettiin.'),
(1696033,58,44,5,38,'Ja nyt minä sanon teille: pysykää erillänne näistä miehistä ja antakaa heidän olla; sillä jos tämä hanke eli tämä teko on ihmisistä, niin se tyhjään raukeaa;'),
(1696034,58,44,5,39,'mutta jos se on Jumalasta, niin te ette voi heitä kukistaa. Varokaa, ettei teitä ehkä havaittaisi sotiviksi itse Jumalaa vastaan."'),
(1696035,58,44,5,40,'Niin he noudattivat hänen neuvoansa. Ja he kutsuivat apostolit sisään ja pieksättivät heitä ja kielsivät heitä puhumasta Jeesuksen nimeen ja päästivät heidät menemään.'),
(1696036,58,44,5,41,'Niin he lähtivät pois neuvostosta iloissaan siitä, että olivat katsotut arvollisiksi kärsimään häväistystä Jeesuksen nimen tähden.'),
(1696037,58,44,5,42,'Eivätkä he lakanneet, vaan opettivat joka päivä pyhäkössä ja kodeissa ja julistivat evankeliumia Kristuksesta Jeesuksesta.'),
(1696038,58,44,6,1,'Niinä päivinä, kun opetuslasten luku lisääntyi, syntyi hellenisteissä nurinaa hebrealaisia vastaan siitä, että heidän leskiänsä syrjäytettiin jokapäiväisessä avunannossa.'),
(1696039,58,44,6,2,'Niin ne kaksitoista kutsuivat kokoon opetuslasten joukon ja sanoivat: "Ei ole soveliasta, että me laiminlyömme Jumalan sanan toimittaaksemme pöytäpalvelusta.'),
(1696040,58,44,6,3,'Valitkaa sentähden, veljet, keskuudestanne seitsemän miestä, joista on hyvä todistus ja jotka ovat Henkeä ja viisautta täynnä, niin me asetamme heidät tähän toimeen.'),
(1696041,58,44,6,4,'Mutta me tahdomme pysyä rukouksessa ja sanan palveluksessa."'),
(1696042,58,44,6,5,'Ja se puhe kelpasi kaikelle joukolle; ja he valitsivat Stefanuksen, miehen, joka oli täynnä uskoa ja Pyhää Henkeä, ja Filippuksen ja Prokoruksen ja Nikanorin ja Timonin ja Parmenaan ja Nikolauksen, antiokialaisen käännynnäisen,'),
(1696043,58,44,6,6,'ja asettivat heidät apostolien eteen, ja nämä rukoilivat ja panivat kätensä heidän päällensä.'),
(1696044,58,44,6,7,'Ja Jumalan sana menestyi, ja opetuslasten luku lisääntyi suuresti Jerusalemissa. Ja lukuisa joukko pappeja tuli uskolle kuuliaisiksi.'),
(1696045,58,44,6,8,'Ja Stefanus, täynnä armoa ja voimaa, teki suuria ihmeitä ja tunnustekoja kansassa.'),
(1696046,58,44,6,9,'Niin nousi muutamia niin kutsutusta libertiinien ja kyreniläisten ja aleksandrialaisten synagoogasta sekä niiden joukosta, jotka olivat Kilikiasta ja Aasiasta, väittelemään Stefanuksen kanssa,'),
(1696047,58,44,6,10,'mutta he eivät kyenneet pitämään puoliaan sitä viisautta ja henkeä vastaan, jolla hän puhui.'),
(1696048,58,44,6,11,'Silloin he salaa hankkivat miehiä sanomaan: "Me olemme kuulleet hänen puhuvan pilkkasanoja Moosesta ja Jumalaa vastaan".'),
(1696049,58,44,6,12,'Ja he yllyttivät kansan ja vanhimmat ja kirjanoppineet ja astuivat esiin, raastoivat hänet mukaansa ja veivät neuvoston eteen.'),
(1696050,58,44,6,13,'Ja he toivat esiin vääriä todistajia, jotka sanoivat: "Tämä mies ei lakkaa puhumasta tätä pyhää paikkaa vastaan ja lakia vastaan;'),
(1696051,58,44,6,14,'sillä me olemme kuulleet hänen sanovan, että Jeesus, tuo Nasaretilainen, on hajottava maahan tämän paikan ja muuttava ne säädökset, jotka Mooses on meille antanut".'),
(1696052,58,44,6,15,'Ja kaikki, jotka neuvostossa istuivat, loivat katseensa häneen, ja hänen kasvonsa olivat heistä niinkuin enkelin kasvot.'),
(1696053,58,44,7,1,'Niin ylimmäinen pappi sanoi: "Onko niin?"'),
(1696054,58,44,7,2,'Stefanus sanoi: "Miehet, veljet ja isät, kuulkaa! Kirkkauden Jumala ilmestyi meidän isällemme Aabrahamille hänen ollessaan Mesopotamiassa, ennenkuin hän oli asettunut asumaan Harraniin,'),
(1696055,58,44,7,3,'ja sanoi hänelle: ''Lähde maastasi ja suvustasi ja mene siihen maahan, jonka minä sinulle osoitan''.'),
(1696056,58,44,7,4,'Silloin hän lähti kaldealaisten maasta ja asettui asumaan Harraniin. Ja kun hänen isänsä oli kuollut, siirsi Jumala hänet tähän maahan, jossa te nyt asutte.'),
(1696057,58,44,7,5,'Eikä hän antanut hänelle siinä perintöosaa, ei jalan leveyttäkään, vaan lupasi, Aabrahamin vielä lapsetonna ollessa, antaa sen hänelle ja hänen siemenelleen hänen jälkeensä.'),
(1696058,58,44,7,6,'Ja Jumala puhui näin: ''Hänen jälkeläisensä tulevat olemaan muukalaisina vieraalla maalla, ja siellä ne tekevät heidät orjiksensa ja sortavat heitä neljäsataa vuotta;'),
(1696059,58,44,7,7,'ja sen kansan, jonka orjiksi he tulevat, minä olen tuomitseva'', sanoi Jumala, ''ja sen jälkeen he lähtevät sieltä ja palvelevat minua tässä paikassa''.'),
(1696060,58,44,7,8,'Ja hän antoi hänelle ympärileikkauksen liiton; ja niin Aabrahamille syntyi Iisak, ja hän ympärileikkasi hänet kahdeksantena päivänä, ja Iisakille syntyi Jaakob, ja Jaakobille ne kaksitoista kantaisää.'),
(1696061,58,44,7,9,'Ja kantaisät kadehtivat Joosefia ja myivät hänet Egyptiin. Mutta Jumala oli hänen kanssansa'),
(1696062,58,44,7,10,'ja pelasti hänet kaikista hänen ahdistuksistansa. Ja hän antoi hänelle armon ja viisauden faraon, Egyptin kuninkaan, edessä; ja tämä pani hänet Egyptin ja kaiken huoneensa haltijaksi.'),
(1696063,58,44,7,11,'Ja tuli nälänhätä koko Egyptiin ja Kanaaniin ja suuri vaiva, eivätkä meidän isämme saaneet mistään ravintoa.'),
(1696064,58,44,7,12,'Mutta kun Jaakob kuuli Egyptissä olevan viljaa, lähetti hän meidän isämme sinne ensimmäisen kerran.'),
(1696065,58,44,7,13,'Ja toisella kerralla veljet tunsivat Joosefin, ja farao sai tietää Joosefin sukuperän.'),
(1696066,58,44,7,14,'Niin Joosef lähetti kutsumaan luokseen isänsä Jaakobin ja koko sukunsa, seitsemänkymmentä viisi henkeä.'),
(1696067,58,44,7,15,'Ja Jaakob meni Egyptiin ja kuoli siellä, niin myös kuolivat isämme,'),
(1696068,58,44,7,16,'ja heidät siirrettiin Sikemiin ja pantiin siihen hautaan, jonka Aabraham oli rahalla ostanut Emmorin lapsilta Sikemissä.'),
(1696069,58,44,7,17,'Mutta sitä mukaa kuin lähestyi sen lupauksen aika, jonka Jumala oli Aabrahamille antanut, kasvoi kansa ja lisääntyi Egyptissä,'),
(1696070,58,44,7,18,'kunnes Egyptiä hallitsemaan nousi toinen kuningas, joka ei Joosefista mitään tiennyt.'),
(1696071,58,44,7,19,'Tämä kohteli kavalasti meidän kansaamme ja sorti meidän isiämme ja pakotti heidät panemaan heitteille pienet lapsensa, etteivät ne jäisi eloon.'),
(1696072,58,44,7,20,'Siihen aikaan syntyi Mooses, ja hän oli Jumalalle otollinen. Häntä elätettiin kolme kuukautta isänsä kodissa.'),
(1696073,58,44,7,21,'Mutta kun hänet oli pantu heitteille, otti faraon tytär hänet ja kasvatti hänet pojaksensa.'),
(1696074,58,44,7,22,'Ja Mooses kasvatettiin kaikkeen egyptiläisten viisauteen, ja hän oli voimallinen sanoissa ja teoissa.'),
(1696075,58,44,7,23,'Mutta kun hän oli täyttänyt neljäkymmentä vuotta, heräsi hänen sydämessään ajatus mennä katsomaan veljiänsä, israelilaisia.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696076,58,44,7,24,'Ja nähdessään eräälle heistä vääryyttä tehtävän hän puolusti häntä ja kosti pahoinpidellyn puolesta ja löi egyptiläisen kuoliaaksi.'),
(1696077,58,44,7,25,'Ja hän luuli veljiensä ymmärtävän, että Jumala hänen kätensä kautta oli antava heille pelastuksen; mutta he eivät sitä ymmärtäneet.'),
(1696078,58,44,7,26,'Seuraavana päivänä hän ilmestyi heidän luoksensa, heidän riidellessään, ja koetti saada heitä sopimaan sanoen: ''Tehän olette veljiä, miehet; miksi teette vääryyttä toisillenne?'''),
(1696079,58,44,7,27,'Mutta se, joka teki lähimmäisellensä vääryyttä, työnsi hänet pois ja sanoi: ''Kuka on asettanut sinut meidän päämieheksemme ja tuomariksemme?'),
(1696080,58,44,7,28,'Aiotko tappaa minutkin, niinkuin eilen tapoit egyptiläisen?'''),
(1696081,58,44,7,29,'Tämän puheen tähden Mooses pakeni ja oli muukalaisena Midianin maassa, ja siellä hänelle syntyi kaksi poikaa.'),
(1696082,58,44,7,30,'Ja kun neljäkymmentä vuotta oli kulunut, ilmestyi hänelle Siinain vuoren erämaassa enkeli palavan orjantappurapensaan liekissä.'),
(1696083,58,44,7,31,'Kun Mooses sen näki, ihmetteli hän tätä näkyä; ja kun hän meni tarkemmin katsomaan, kuului Herran ääni, joka sanoi:'),
(1696084,58,44,7,32,'''Minä olen sinun isiesi Jumala, Aabrahamin ja Iisakin ja Jaakobin Jumala''. Niin Mooses alkoi vapista eikä tohtinut katsoa sinne.'),
(1696085,58,44,7,33,'Mutta Herra sanoi hänelle: ''Riisu kengät jalastasi; sillä paikka, jossa seisot, on pyhä maa.'),
(1696086,58,44,7,34,'Minä olen nähnyt kansani kurjuuden Egyptissä ja kuullut heidän huokauksensa, ja minä olen astunut alas vapauttamaan heidät. Ja nyt, tule tänne, minä lähetän sinut Egyptiin.'''),
(1696087,58,44,7,35,'Tämän Mooseksen, jonka he kielsivät sanoen: ''Kuka sinut on asettanut päämieheksi ja tuomariksi?'', hänet Jumala lähetti päämieheksi ja lunastajaksi sen enkelin kautta, joka hänelle orjantappurapensaassa oli ilmestynyt.'),
(1696088,58,44,7,36,'Hän johdatti heidät sieltä pois, tehden ihmeitä ja tunnustekoja Egyptin maassa ja Punaisessa meressä ja erämaassa neljänäkymmenenä vuotena.'),
(1696089,58,44,7,37,'Tämä on se Mooses, joka sanoi israelilaisille: ''Profeetan, minun kaltaiseni, Jumala on teille herättävä teidän veljienne joukosta''.'),
(1696090,58,44,7,38,'Hän on se, joka seurakunnassa, erämaassa, oli enkelin kanssa, joka puhui hänelle Siinain vuorella, ja oli myös isiemme kanssa; ja hän sai eläviä sanoja meille annettaviksi.'),
(1696091,58,44,7,39,'Mutta häntä meidän isämme eivät tahtoneet totella, vaan työnsivät hänet pois ja kääntyivät sydämessänsä jälleen Egyptiin,'),
(1696092,58,44,7,40,'sanoen Aaronille: ''Tee meille jumalia, jotka käyvät meidän edellämme, sillä me emme tiedä, mitä on tapahtunut Moosekselle, hänelle, joka johdatti meidät Egyptin maasta''.'),
(1696093,58,44,7,41,'Ja he tekivät niinä päivinä vasikan ja toivat uhreja epäjumalalleen ja riemuitsivat kättensä töistä.'),
(1696094,58,44,7,42,'Mutta Jumala kääntyi heistä pois ja hylkäsi heidät palvelemaan taivaan sotajoukkoa, niinkuin on kirjoitettu profeettain kirjassa: ''Toitteko te teurasuhreja ja muita uhreja minulle erämaassa neljänäkymmenenä vuotena, te, Israelin heimo?'),
(1696095,58,44,7,43,'Ette; vaan te kannoitte Molokin majaa ja Romfa jumalan tähteä, niitä kuvia, jotka te olitte tehneet kumarrettaviksenne. Sentähden minä siirrän teidät toiselle puolelle Babylonin.'''),
(1696096,58,44,7,44,'Todistuksen maja oli meidän isillämme erämaassa, niinkuin hän, joka puhui Moosekselle, oli määrännyt sen tehtäväksi, sen kaavan mukaan, minkä Mooses oli nähnyt.'),
(1696097,58,44,7,45,'Ja meidän isämme ottivat sen perintönä vastaan ja toivat sen Joosuan johdolla maahan, minkä he valtasivat pakanoilta, jotka Jumala karkoitti meidän isiemme tieltä. Näin oli Daavidin päiviin saakka.'),
(1696098,58,44,7,46,'Hän sai armon Jumalan edessä ja anoi, että hän saisi valmistaa majan Jaakobin Jumalalle.'),
(1696099,58,44,7,47,'Mutta Salomo hänelle huoneen rakensi.'),
(1696100,58,44,7,48,'Korkein ei kuitenkaan asu käsillä tehdyissä huoneissa; sillä näin sanoo profeetta:'),
(1696101,58,44,7,49,'''Taivas on minun valtaistuimeni ja maa minun jalkojeni astinlauta; minkäkaltaisen huoneen te minulle rakentaisitte, sanoo Herra, tai mikä paikka olisi minun leposijani?'),
(1696102,58,44,7,50,'Eikö minun käteni ole tätä kaikkea tehnyt?'''),
(1696103,58,44,7,51,'Te niskurit ja ympärileikkaamattomat sydämeltä ja korvilta, aina te vastustatte Pyhää Henkeä - niinkuin teidän isänne, niin tekin.'),
(1696104,58,44,7,52,'Ketä profeetoista eivät teidän isänne vainonneet? He tappoivat ne, jotka ennustivat sen Vanhurskaan tulemista, jonka kavaltajiksi ja murhaajiksi te nyt olette tulleet,'),
(1696105,58,44,7,53,'te, jotka enkelien toimen kautta saitte lain, mutta ette sitä pitäneet."'),
(1696106,58,44,7,54,'Mutta kun he tämän kuulivat, viilsi se heidän sydäntänsä, ja he kiristelivät hänelle hampaitansa.'),
(1696107,58,44,7,55,'Mutta täynnä Pyhää Henkeä hän loi katseensa taivaaseen päin ja näki Jumalan kirkkauden ja Jeesuksen seisovan Jumalan oikealla puolella'),
(1696108,58,44,7,56,'ja sanoi: "Katso, minä näen taivaat auenneina ja Ihmisen Pojan seisovan Jumalan oikealla puolella".'),
(1696109,58,44,7,57,'Niin he huusivat suurella äänellä ja tukkivat korvansa ja karkasivat kaikki yhdessä hänen päällensä'),
(1696110,58,44,7,58,'ja ajoivat hänet ulos kaupungista ja kivittivät. Ja todistajat riisuivat vaippansa Saulus nimisen nuorukaisen jalkojen juureen.'),
(1696111,58,44,7,59,'Ja niin he kivittivät Stefanuksen, joka rukoili ja sanoi: "Herra Jeesus, ota minun henkeni!"'),
(1696112,58,44,7,60,'Ja hän laskeutui polvilleen ja huusi suurella äänellä: "Herra, älä lue heille syyksi tätä syntiä!" Ja sen sanottuaan hän nukkui pois.'),
(1696113,58,44,8,1,'Myös Saulus hyväksyi Stefanuksen surmaamisen. Ja sinä päivänä nousi suuri vaino Jerusalemin seurakuntaa vastaan; ja kaikki hajaantuivat ympäri Juudean ja Samarian paikkakuntia, paitsi apostolit.'),
(1696114,58,44,8,2,'Ja muutamat jumalaapelkääväiset miehet hautasivat Stefanuksen ja pitivät hänelle suuret valittajaiset.'),
(1696115,58,44,8,3,'Mutta Saulus raateli seurakuntaa, kulki talosta taloon ja raastoi ulos miehiä ja naisia ja panetti heidät vankeuteen.'),
(1696116,58,44,8,4,'Ne, jotka näin olivat hajaantuneet, vaelsivat paikasta toiseen ja julistivat evankeliumin sanaa.'),
(1696117,58,44,8,5,'Ja Filippus meni Samarian kaupunkiin ja saarnasi heille Kristusta.'),
(1696118,58,44,8,6,'Ja kansa otti yksimielisesti vaarin siitä, mitä Filippus puhui, kun he kuulivat hänen sanansa ja näkivät ne tunnusteot, jotka hän teki.'),
(1696119,58,44,8,7,'Sillä monista, joissa oli saastaisia henkiä, ne lähtivät pois huutaen suurella äänellä; ja moni halvattu ja rampa parani.'),
(1696120,58,44,8,8,'Ja syntyi suuri ilo siinä kaupungissa.'),
(1696121,58,44,8,9,'Mutta ennestään oli kaupungissa muuan mies, nimeltä Simon, joka harjoitti noituutta ja hämmästytti Samarian kansaa sanoen olevansa jokin suuri;'),
(1696122,58,44,8,10,'ja häntä kuuntelivat kaikki, pienet ja suuret, ja sanoivat: "Tämä mies on se Jumalan voima, jota kutsutaan ''suureksi''".'),
(1696123,58,44,8,11,'Ja he kuuntelivat häntä sentähden, että hän kauan aikaa oli noituuksillaan heitä hämmästyttänyt.'),
(1696124,58,44,8,12,'Mutta kun he nyt uskoivat Filippusta, joka julisti evankeliumia Jumalan valtakunnasta ja Jeesuksen Kristuksen nimestä, niin he ottivat kasteen, sekä miehet että naiset.'),
(1696125,58,44,8,13,'Ja Simon itsekin uskoi, ja kasteen saatuansa hän pysytteli Filippuksen seurassa; ja nähdessään ihmeitä ja suuria, voimallisia tekoja hän hämmästyi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696126,58,44,8,14,'Mutta kun apostolit, jotka olivat Jerusalemissa, kuulivat, että Samaria oli ottanut vastaan Jumalan sanan, lähettivät he heidän tykönsä Pietarin ja Johanneksen.'),
(1696127,58,44,8,15,'Ja tultuaan sinne nämä rukoilivat heidän edestänsä, että he saisivat Pyhän Hengen;'),
(1696128,58,44,8,16,'sillä hän ei ollut vielä tullut yhteenkään heistä, vaan he olivat ainoastaan kastetut Herran Jeesuksen nimeen.'),
(1696129,58,44,8,17,'Silloin he panivat kätensä heidän päällensä, ja he saivat Pyhän Hengen.'),
(1696130,58,44,8,18,'Mutta kun Simon näki, että Henki annettiin sille, jonka päälle apostolit panivat kätensä, toi hän heille rahaa'),
(1696131,58,44,8,19,'ja sanoi: "Antakaa minullekin se valta, että kenen päälle minä käteni panen, se saa Pyhän Hengen".'),
(1696132,58,44,8,20,'Mutta Pietari sanoi hänelle: "Menkööt rahasi sinun kanssasi kadotukseen, koska luulet Jumalan lahjan olevan rahalla saatavissa.'),
(1696133,58,44,8,21,'Ei sinulla ole osaa eikä arpaa tähän sanaan, sillä sinun sydämesi ei ole oikea Jumalan edessä.'),
(1696134,58,44,8,22,'Tee siis parannus ja käänny tästä pahuudestasi ja rukoile Herraa - jos ehkä vielä sinun sydämesi ajatus sinulle anteeksi annetaan.'),
(1696135,58,44,8,23,'Sillä minä näen sinun olevan täynnä katkeruuden sappea ja kiinni vääryyden siteissä."'),
(1696136,58,44,8,24,'Niin Simon vastasi ja sanoi: "Rukoilkaa te minun edestäni Herraa, ettei minulle tapahtuisi mitään siitä, mitä te olette sanoneet".'),
(1696137,58,44,8,25,'Ja kun he olivat todistaneet ja Herran sanaa puhuneet, palasivat he Jerusalemiin ja julistivat evankeliumia monessa Samarian kylässä.'),
(1696138,58,44,8,26,'Mutta Filippukselle puhui Herran enkeli sanoen: "Nouse ja mene puolipäivään päin sille tielle, joka vie Jerusalemista alas Gassaan ja on autio".'),
(1696139,58,44,8,27,'Ja hän nousi ja lähti. Ja katso, siellä kulki etiopialainen mies, Etiopian kuningattaren Kandaken hoviherra, mahtava mies ja koko hänen aarteistonsa hoitaja; hän oli tullut Jerusalemiin rukoilemaan'),
(1696140,58,44,8,28,'ja oli nyt paluumatkalla ja istui vaunuissaan ja luki profeetta Esaiasta.'),
(1696141,58,44,8,29,'Niin Henki sanoi Filippukselle: "Käy luo ja pysyttele lähellä noita vaunuja".'),
(1696142,58,44,8,30,'Niin Filippus juoksi luo ja kuuli hänen lukevan profeetta Esaiasta ja sanoi: "Ymmärrätkö myös, mitä luet?"'),
(1696143,58,44,8,31,'Niin hän sanoi: "Kuinka minä voisin ymmärtää, ellei kukaan minua opasta?" Ja hän pyysi Filippusta nousemaan ja istumaan viereensä.'),
(1696144,58,44,8,32,'Ja se kirjoitus, jota hän luki, oli tämä: "Niinkuin lammas hänet viedään teuraaksi; ja niinkuin karitsa on ääneti keritsijänsä edessä, niin ei hänkään suutansa avaa.'),
(1696145,58,44,8,33,'Hänen alentumisensa kautta hänen tuomionsa otetaan pois. Kuka kertoo hänen syntyperänsä? Sillä hänen elämänsä otetaan pois maan päältä."'),
(1696146,58,44,8,34,'Ja hoviherra kysyi Filippukselta sanoen: "Minä pyydän sinua: sano, kenestä profeetta puhuu näin, itsestäänkö vai jostakin toisesta?"'),
(1696147,58,44,8,35,'Niin Filippus avasi suunsa ja lähtien tästä kirjoituksesta julisti hänelle evankeliumia Jeesuksesta.'),
(1696148,58,44,8,36,'Ja kulkiessaan tietä he tulivat veden ääreen; ja hoviherra sanoi: "Katso, tässä on vettä. Mikä estää kastamasta minua?"'),
(1696149,58,44,8,38,'Ja hän käski pysäyttää vaunut, ja he astuivat kumpikin veteen, sekä Filippus että hoviherra, ja Filippus kastoi hänet.'),
(1696150,58,44,8,39,'Ja kun he olivat astuneet ylös vedestä, tempasi Herran Henki Filippuksen pois, eikä hoviherra häntä enää nähnyt. Ja hän jatkoi matkaansa iloiten.'),
(1696151,58,44,8,40,'Mutta Filippus tavattiin Asdodissa; ja hän vaelsi ympäri ja julisti evankeliumia kaikissa kaupungeissa, kunnes tuli Kesareaan.'),
(1696152,58,44,9,1,'Mutta Saulus puuskui yhä uhkaa ja murhaa Herran opetuslapsia vastaan ja meni ylimmäisen papin luo'),
(1696153,58,44,9,2,'ja pyysi häneltä kirjeitä Damaskon synagoogille, että keitä hän vain löytäisi sen tien vaeltajia, miehiä tai naisia, ne hän saisi tuoda sidottuina Jerusalemiin.'),
(1696154,58,44,9,3,'Ja kun hän oli matkalla, tapahtui hänen lähestyessään Damaskoa, että yhtäkkiä valo taivaasta leimahti hänen ympärillänsä;'),
(1696155,58,44,9,4,'ja hän kaatui maahan ja kuuli äänen, joka sanoi hänelle: "Saul, Saul, miksi vainoat minua?"'),
(1696156,58,44,9,5,'Hän sanoi: "Kuka olet, herra?" Hän vastasi: "Minä olen Jeesus, jota sinä vainoat.'),
(1696157,58,44,9,6,'Mutta nouse ja mene kaupunkiin, niin sinulle sanotaan, mitä sinun pitää tekemän."'),
(1696158,58,44,9,7,'Ja miehet, jotka matkustivat hänen kanssansa, seisoivat mykistyneinä: he kuulivat kyllä äänen, mutta eivät ketään nähneet.'),
(1696159,58,44,9,8,'Niin Saulus nousi maasta; mutta kun hän avasi silmänsä, ei hän nähnyt mitään, vaan he taluttivat häntä kädestä ja veivät hänet Damaskoon.'),
(1696160,58,44,9,9,'Ja hän oli kolme päivää näkemätönnä, ei syönyt eikä juonut.'),
(1696161,58,44,9,10,'Ja Damaskossa oli eräs opetuslapsi, nimeltä Ananias. Hänelle Herra sanoi näyssä: "Ananias!" Hän vastasi: "Katso, tässä olen, Herra".'),
(1696162,58,44,9,11,'Niin Herra sanoi hänelle: "Nouse ja mene sille kadulle, jota sanotaan Suoraksi kaduksi, ja kysy Juudaan talosta Saulus nimistä tarsolaista miestä. Sillä katso, hän rukoilee;'),
(1696163,58,44,9,12,'ja hän on nähnyt näyssä miehen, Ananias nimisen, tulevan sisälle ja panevan kätensä hänen päällensä, että hän saisi näkönsä jälleen."'),
(1696164,58,44,9,13,'Mutta Ananias vastasi: "Herra, minä olen monelta kuullut siitä miehestä, kuinka paljon pahaa hän on tehnyt sinun pyhillesi Jerusalemissa;'),
(1696165,58,44,9,14,'ja täälläkin hänellä on ylipapeilta valtuus vangita kaikki, jotka sinun nimeäsi avuksi huutavat".'),
(1696166,58,44,9,15,'Mutta Herra sanoi hänelle: "Mene; sillä hän on minulle valittu ase, kantamaan minun nimeäni pakanain ja kuningasten ja Israelin lasten eteen.'),
(1696167,58,44,9,16,'Sillä minä tahdon näyttää hänelle, kuinka paljon hänen pitää kärsimän minun nimeni tähden."'),
(1696168,58,44,9,17,'Niin Ananias meni ja astui huoneeseen, pani molemmat kätensä hänen päälleen ja sanoi: "Veljeni Saul, Herra lähetti minut - Jeesus, joka ilmestyi sinulle tiellä, jota tulit - että saisit näkösi jälleen ja tulisit täytetyksi Pyhällä Hengellä".'),
(1696169,58,44,9,18,'Ja heti putosivat hänen silmistään ikäänkuin suomukset, ja hän sai näkönsä ja nousi ja otti kasteen.'),
(1696170,58,44,9,19,'Ja kun hän nautti ruokaa, niin hän vahvistui. Ja hän oli opetuslasten seurassa Damaskossa jonkun aikaa.'),
(1696171,58,44,9,20,'Ja kohta hän saarnasi synagoogissa Jeesusta, julistaen, että hän on Jumalan Poika.'),
(1696172,58,44,9,21,'Ja kaikki, jotka kuulivat, hämmästyivät ja sanoivat: "Eikö tämä ole se, joka Jerusalemissa tuhosi ne, jotka tätä nimeä avuksi huutavat? Ja eikö hän ole tullut tänne viedäksensä ne vangittuina ylipappien käsiin?"'),
(1696173,58,44,9,22,'Mutta Saulus sai yhä enemmän voimaa ja saattoi Damaskossa asuvat juutalaiset ymmälle näyttäen toteen, että Jeesus on Kristus.'),
(1696174,58,44,9,23,'Ja pitkän ajan kuluttua juutalaiset pitivät keskenään neuvoa tappaaksensa hänet.'),
(1696175,58,44,9,24,'Mutta heidän salahankkeensa tuli Sauluksen tietoon. Ja he vartioivat porttejakin yöt päivät, saadakseen hänet tapetuksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696176,58,44,9,25,'Mutta hänen opetuslapsensa ottivat hänet yöllä, päästivät hänet muurin aukosta ja laskivat alas vasussa.'),
(1696177,58,44,9,26,'Ja kun hän oli tullut Jerusalemiin, yritti hän liittyä opetuslapsiin; mutta he kaikki pelkäsivät häntä, koska eivät uskoneet, että hän oli opetuslapsi.'),
(1696178,58,44,9,27,'Mutta Barnabas otti hänet turviinsa ja vei hänet apostolien tykö ja kertoi heille, kuinka Saulus tiellä oli nähnyt Herran, ja että Herra oli puhunut hänelle, ja kuinka hän Damaskossa oli rohkeasti julistanut Jeesuksen nimeä.'),
(1696179,58,44,9,28,'Ja niin hän kävi heidän keskuudessaan sisälle ja ulos Jerusalemissa ja julisti rohkeasti Herran nimeä.'),
(1696180,58,44,9,29,'Ja hän puhui ja väitteli hellenistien kanssa; mutta he koettivat tappaa hänet.'),
(1696181,58,44,9,30,'Kun veljet sen huomasivat, veivät he hänet Kesareaan ja lähettivät hänet sieltä Tarsoon.'),
(1696182,58,44,9,31,'Niin oli nyt seurakunnalla koko Juudeassa ja Galileassa ja Samariassa rauha; ja se rakentui ja vaelsi Herran pelossa ja lisääntyi Pyhän Hengen virvoittavasta vaikutuksesta.'),
(1696183,58,44,9,32,'Ja tapahtui, että Pietari, kiertäessään kaikkien luona, tuli myöskin niiden pyhien tykö, jotka asuivat Lyddassa.'),
(1696184,58,44,9,33,'Siellä hän tapasi Aineas nimisen miehen, joka kahdeksan vuotta oli maannut vuoteessaan ja oli halvattu.'),
(1696185,58,44,9,34,'Ja Pietari sanoi hänelle: "Aineas, Jeesus Kristus parantaa sinut; nouse ja korjaa vuoteesi". Ja kohta hän nousi.'),
(1696186,58,44,9,35,'Ja kaikki Lyddan ja Saaronin asukkaat näkivät hänet; ja he kääntyivät Herran tykö.'),
(1696187,58,44,9,36,'Mutta Joppessa oli naisopetuslapsi, nimeltä Tabita, mikä kreikaksi käännettynä on: Dorkas; hän teki paljon hyviä töitä ja antoi runsaasti almuja.'),
(1696188,58,44,9,37,'Ja tapahtui niinä päivinä, että hän sairastui ja kuoli; ja he pesivät hänet ja panivat yläsaliin.'),
(1696189,58,44,9,38,'Ja koska Lydda oli lähellä Joppea, niin opetuslapset, kun kuulivat Pietarin olevan siellä, lähettivät kaksi miestä hänen luoksensa pyytämään: "Tule viipymättä meidän tykömme".'),
(1696190,58,44,9,39,'Niin Pietari nousi ja meni heidän kanssansa. Ja hänen sinne saavuttuaan he veivät hänet yläsaliin, ja kaikki lesket tulivat hänen luoksensa itkien ja näytellen hänelle ihokkaita ja vaippoja, joita Dorkas oli tehnyt, ollessaan heidän kanssansa.'),
(1696191,58,44,9,40,'Mutta Pietari toimitti kaikki ulos ja laskeutui polvilleen ja rukoili; ja hän kääntyi ruumiin puoleen ja sanoi: "Tabita, nouse ylös!" Niin tämä avasi silmänsä, ja nähdessään Pietarin hän nousi istumaan.'),
(1696192,58,44,9,41,'Ja Pietari ojensi hänelle kätensä ja nosti hänet seisomaan ja kutsui sisään pyhät ja lesket ja asetti hänet elävänä heidän eteensä.'),
(1696193,58,44,9,42,'Ja se tuli tiedoksi koko Joppessa, ja monet uskoivat Herraan.'),
(1696194,58,44,9,43,'Ja Pietari viipyi Joppessa jonkun aikaa erään nahkuri Simonin luona.'),
(1696195,58,44,10,1,'Ja Kesareassa oli mies, nimeltä Kornelius, sadanpäämies niin kutsutussa italialaisessa sotaväenosastossa.'),
(1696196,58,44,10,2,'Hän oli hurskas ja Jumalaa pelkääväinen, niinkuin koko hänen perhekuntansakin, ja antoi paljon almuja kansalle ja rukoili alati Jumalaa.'),
(1696197,58,44,10,3,'Hän näki selvästi näyssä, noin yhdeksännellä hetkellä päivästä, Jumalan enkelin, joka tuli sisään hänen tykönsä ja sanoi hänelle: "Kornelius!"'),
(1696198,58,44,10,4,'Tämä loi katseensa häneen ja sanoi peljästyneenä: "Mikä on, Herra?" Enkeli sanoi hänelle: "Sinun rukouksesi ja almusi ovat tulleet muistoon Jumalan edessä.'),
(1696199,58,44,10,5,'Niin lähetä nyt miehiä Joppeen noutamaan eräs Simon, jota myös Pietariksi kutsutaan;'),
(1696200,58,44,10,6,'hän majailee nahkuri Simonin luona, jonka talo on meren rannalla."'),
(1696201,58,44,10,7,'Ja kun enkeli, joka Korneliusta puhutteli, oli mennyt pois, kutsui tämä kaksi palvelijaansa ja hurskaan sotamiehen uskollisimpiensa joukosta'),
(1696202,58,44,10,8,'ja kertoi heille kaikki ja lähetti heidät Joppeen.'),
(1696203,58,44,10,9,'Ja seuraavana päivänä, kun he olivat matkalla ja lähestyivät kaupunkia, nousi Pietari noin kuudennen hetken vaiheilla katolle rukoilemaan.'),
(1696204,58,44,10,10,'Ja hänen tuli nälkä, ja hän halusi ruokaa. Mutta sitä valmistettaessa hän joutui hurmoksiin.'),
(1696205,58,44,10,11,'Ja hän näki taivaan avoinna ja tulevan alas astian, ikäänkuin suuren liinavaatteen, joka neljästä kulmastaan laskettiin maahan.'),
(1696206,58,44,10,12,'Ja siinä oli kaikkinaisia maan nelijalkaisia ja matelijoita ja taivaan lintuja.'),
(1696207,58,44,10,13,'Ja tuli ääni, joka sanoi hänelle: "Nouse, Pietari, teurasta ja syö".'),
(1696208,58,44,10,14,'Mutta Pietari sanoi: "En suinkaan, Herra; sillä en minä ole ikinä syönyt mitään epäpyhää enkä saastaista".'),
(1696209,58,44,10,15,'Ja taas ääni sanoi hänelle toistamiseen: "Minkä Jumala on puhdistanut, sitä älä sinä sano epäpyhäksi".'),
(1696210,58,44,10,16,'Tämä tapahtui kolme kertaa; sitten astia otettiin kohta ylös taivaaseen.'),
(1696211,58,44,10,17,'Ja kun Pietari oli epätietoinen siitä, mitä hänen näkemänsä näky mahtoi merkitä, niin katso, ne miehet, jotka Kornelius oli lähettänyt ja jotka kyselemällä olivat löytäneet Simonin talon, seisoivat portilla'),
(1696212,58,44,10,18,'ja tiedustelivat kuuluvalla äänellä, majailiko siellä Simon, jota myös Pietariksi kutsuttiin.'),
(1696213,58,44,10,19,'Kun Pietari yhä mietti tuota näkyä, sanoi Henki hänelle: "Katso, kaksi miestä etsii sinua;'),
(1696214,58,44,10,20,'niin nouse nyt, astu alas ja mene arvelematta heidän kanssaan, sillä minä olen heidät lähettänyt".'),
(1696215,58,44,10,21,'Niin Pietari meni alas miesten tykö ja sanoi: "Katso, minä olen se, jota te etsitte; mitä varten te olette tulleet?"'),
(1696216,58,44,10,22,'He sanoivat: "Sadanpäämies Kornelius, hurskas ja Jumalaa pelkääväinen mies, josta koko Juudan kansa todistaa hyvää, on pyhältä enkeliltä ilmestyksessä saanut käskyn haettaa sinut kotiinsa ja kuulla, mitä sinulla on sanottavaa".'),
(1696217,58,44,10,23,'Niin hän kutsui heidät sisään ja piti heitä vierainansa. Seuraavana päivänä Pietari nousi ja lähti heidän kanssaan, ja muutamat veljet Joppesta seurasivat hänen mukanaan.'),
(1696218,58,44,10,24,'Ja sen jälkeisenä päivänä he saapuivat Kesareaan; ja Kornelius odotti heitä ja oli kutsunut koolle sukulaisensa ja lähimmät ystävänsä.'),
(1696219,58,44,10,25,'Ja kun Pietari oli astumassa sisään, meni Kornelius häntä vastaan, lankesi hänen jalkojensa juureen ja kumartui maahan.'),
(1696220,58,44,10,26,'Mutta Pietari nosti hänet ylös sanoen: "Nouse; minäkin olen ihminen".'),
(1696221,58,44,10,27,'Ja puhellen hänen kanssaan hän meni sisään ja tapasi monta koolla.'),
(1696222,58,44,10,28,'Ja hän sanoi heille: "Te tiedätte, että on luvatonta juutalaisen miehen seurustella vierasheimoisen kanssa tai mennä hänen tykönsä; mutta minulle Jumala on osoittanut, etten saa sanoa ketään ihmistä epäpyhäksi enkä saastaiseksi.'),
(1696223,58,44,10,29,'Sentähden minä vastaansanomatta tulinkin, kun minua noudettiin. Ja nyt minä kysyn: mitä varten te olette minut noutaneet?"'),
(1696224,58,44,10,30,'Ja Kornelius sanoi: "Neljä päivää sitten, juuri tähän aikaan päivästä, minä kotonani rukoilin tällä yhdeksännellä hetkellä, ja katso, edessäni seisoi mies loistavissa vaatteissa'),
(1696225,58,44,10,31,'ja sanoi: ''Kornelius, sinun rukouksesi on kuultu, ja sinun almusi ovat tulleet muistoon Jumalan edessä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696226,58,44,10,32,'Niin lähetä nyt Joppeen ja kutsu tykösi Simon, jota myös Pietariksi kutsutaan; hän majailee nahkuri Simonin talossa meren rannalla.'''),
(1696227,58,44,10,33,'Sentähden minä lähetin heti sinulle sanan, ja sinä teit hyvin, kun tulit. Nyt olemme siis tässä kaikki Jumalan edessä, kuullaksemme kaiken, mitä Herra on käskenyt sinun puhua."'),
(1696228,58,44,10,34,'Niin Pietari avasi suunsa ja sanoi: "Nyt minä totisesti käsitän, ettei Jumala katso henkilöön,'),
(1696229,58,44,10,35,'vaan että jokaisessa kansassa se, joka häntä pelkää ja tekee vanhurskautta, on hänelle otollinen.'),
(1696230,58,44,10,36,'Sen sanan, jonka hän lähetti Israelin lapsille, julistaen evankeliumia rauhasta Jeesuksessa Kristuksessa, joka on kaikkien Herra,'),
(1696231,58,44,10,37,'sen sanan, joka lähtien Galileasta on levinnyt koko Juudeaan, sen kasteen jälkeen, jota Johannes saarnasi, sen te tiedätte;'),
(1696232,58,44,10,38,'te tiedätte, kuinka Jumala Pyhällä Hengellä ja voimalla oli voidellut Jeesuksen Nasaretilaisen, hänet, joka vaelsi ympäri ja teki hyvää ja paransi kaikki perkeleen valtaan joutuneet; sillä Jumala oli hänen kanssansa.'),
(1696233,58,44,10,39,'Ja me olemme kaiken sen todistajat, mitä hän teki juutalaisten maassa ja Jerusalemissa; ja hänet he ripustivat puuhun ja tappoivat.'),
(1696234,58,44,10,40,'Hänet Jumala herätti kolmantena päivänä ja antoi hänen ilmestyä,'),
(1696235,58,44,10,41,'ei kaikelle kansalle, vaan Jumalan ennen valitsemille todistajille, meille, jotka söimme ja joimme hänen kanssaan sen jälkeen, kuin hän oli kuolleista noussut.'),
(1696236,58,44,10,42,'Ja hän käski meidän saarnata kansalle ja todistaa, että hän on se, jonka Jumala on asettanut elävien ja kuolleitten tuomariksi.'),
(1696237,58,44,10,43,'Hänestä kaikki profeetat todistavat, että jokainen, joka uskoo häneen, saa synnit anteeksi hänen nimensä kautta."'),
(1696238,58,44,10,44,'Kun Pietari vielä näitä puhui, tuli Pyhä Henki kaikkien päälle, jotka puheen kuulivat.'),
(1696239,58,44,10,45,'Ja kaikki ne uskovaiset, jotka olivat ympärileikatut ja olivat tulleet Pietarin mukana, hämmästyivät sitä, että Pyhän Hengen lahja vuodatettiin pakanoihinkin,'),
(1696240,58,44,10,46,'sillä he kuulivat heidän puhuvan kielillä ja ylistävän Jumalaa. Silloin Pietari vastasi:'),
(1696241,58,44,10,47,'"Ei kaiketi kukaan voi kieltää kastamasta vedellä näitä, jotka ovat saaneet Pyhän Hengen niinkuin mekin?"'),
(1696242,58,44,10,48,'Ja hän käski kastaa heidät Jeesuksen Kristuksen nimeen. Silloin he pyysivät häntä viipymään siellä muutamia päiviä.'),
(1696243,58,44,11,1,'Ja apostolit ja veljet ympäri Juudeaa kuulivat, että pakanatkin olivat ottaneet vastaan Jumalan sanan.'),
(1696244,58,44,11,2,'Ja kun Pietari tuli Jerusalemiin, ahdistelivat ympärileikatut häntä'),
(1696245,58,44,11,3,'sanoen: "Sinä olet käynyt ympärileikkaamattomien miesten luona ja syönyt heidän kanssansa".'),
(1696246,58,44,11,4,'Niin Pietari selitti heille alusta alkaen asiat järjestänsä ja sanoi:'),
(1696247,58,44,11,5,'"Minä olin Joppen kaupungissa ja rukoilin; silloin minä näin hurmoksissa näyn: tuli alas astia, ikäänkuin suuri liinavaate, joka neljästä kulmastaan laskettiin taivaasta, ja se tuli aivan minun eteeni.'),
(1696248,58,44,11,6,'Ja kun minä katsoin sitä tarkasti, näin minä siinä maan nelijalkaisia ja petoja ja matelijoita ja taivaan lintuja.'),
(1696249,58,44,11,7,'Ja minä kuulin myös äänen, joka sanoi minulle: ''Nouse, Pietari, teurasta ja syö''.'),
(1696250,58,44,11,8,'Mutta minä sanoin: ''En suinkaan, Herra; sillä ei mitään epäpyhää eikä saastaista ole koskaan minun suuhuni tullut''.'),
(1696251,58,44,11,9,'Niin vastasi ääni taivaasta toistamiseen ja sanoi: ''Minkä Jumala on puhdistanut, sitä älä sinä sano epäpyhäksi''.'),
(1696252,58,44,11,10,'Ja tämä tapahtui kolme kertaa; sitten vedettiin kaikki taas ylös taivaaseen.'),
(1696253,58,44,11,11,'Ja katso, samassa seisoi sen talon edessä, jossa me olimme, kolme miestä, jotka Kesareasta oli lähetetty minun luokseni.'),
(1696254,58,44,11,12,'Ja Henki käski minun mennä arvelematta heidän kanssansa; ja myös nämä kuusi veljeä lähtivät minun kanssani. Me menimme sen miehen taloon,'),
(1696255,58,44,11,13,'ja hän kertoi meille, kuinka hän oli nähnyt enkelin seisovan hänen huoneessaan ja sanovan: ''Lähetä Joppeen noutamaan Simon, jota myös Pietariksi kutsutaan;'),
(1696256,58,44,11,14,'hän on puhuva sinulle sanoja, joiden kautta sinä pelastut, ja koko sinun perhekuntasi''.'),
(1696257,58,44,11,15,'Ja kun minä rupesin puhumaan, tuli Pyhä Henki heidän päällensä, niinkuin alussa meidänkin päällemme.'),
(1696258,58,44,11,16,'Silloin minä muistin Herran sanan, jonka hän sanoi: ''Johannes kastoi vedellä, mutta teidät kastetaan Pyhällä Hengellä''.'),
(1696259,58,44,11,17,'Koska siis Jumala antoi yhtäläisen lahjan heille kuin meillekin, kun olimme uskoneet Herraan Jeesukseen Kristukseen, niin mikä olin minä voidakseni estää Jumalaa?"'),
(1696260,58,44,11,18,'Tämän kuultuansa he rauhoittuivat ja ylistivät Jumalaa sanoen: "Niin on siis Jumala pakanoillekin antanut parannuksen elämäksi".'),
(1696261,58,44,11,19,'Ne, jotka olivat hajaantuneet sen ahdingon vuoksi, joka oli syntynyt Stefanuksen tähden, vaelsivat ympäri hamaan Foinikiaan ja Kyproon ja Antiokiaan saakka, mutta eivät puhuneet sanaa muille kuin ainoastaan juutalaisille.'),
(1696262,58,44,11,20,'Heidän joukossaan oli kuitenkin muutamia kyprolaisia ja kyreneläisiä miehiä, jotka, tultuaan Antiokiaan, puhuivat kreikkalaisillekin ja julistivat evankeliumia Herrasta Jeesuksesta.'),
(1696263,58,44,11,21,'Ja Herran käsi oli heidän kanssansa, ja suuri oli se joukko, joka uskoi ja kääntyi Herran puoleen.'),
(1696264,58,44,11,22,'Ja sanoma heistä tuli Jerusalemin seurakunnan korviin, ja he lähettivät Barnabaan Antiokiaan.'),
(1696265,58,44,11,23,'Ja kun hän saapui sinne ja näki Jumalan armon, niin hän iloitsi ja kehoitti kaikkia vakaalla sydämellä pysymään Herrassa.'),
(1696266,58,44,11,24,'Sillä hän oli hyvä mies ja täynnä Pyhää Henkeä ja uskoa. Ja Herralle lisääntyi paljon kansaa.'),
(1696267,58,44,11,25,'Niin hän lähti Tarsoon etsimään Saulusta, ja kun hän oli hänet löytänyt, toi hän hänet Antiokiaan.'),
(1696268,58,44,11,26,'Ja he vaikuttivat yhdessä kokonaisen vuoden seurakunnassa, ja niitä oli paljon, jotka saivat heiltä opetusta; ja Antiokiassa ruvettiin opetuslapsia ensiksi nimittämään kristityiksi.'),
(1696269,58,44,11,27,'Siihen aikaan tuli profeettoja Jerusalemista Antiokiaan.'),
(1696270,58,44,11,28,'Ja eräs heistä, nimeltä Agabus, nousi ja antoi Hengen vaikutuksesta tiedoksi, että oli tuleva suuri nälkä kaikkeen maailmaan; ja se tulikin Klaudiuksen aikana.'),
(1696271,58,44,11,29,'Niin opetuslapset päättivät kukin varojensa mukaan lähettää avustusta Juudeassa asuville veljille.'),
(1696272,58,44,11,30,'Ja niin he tekivätkin ja lähettivät sen vanhimmille Barnabaan ja Sauluksen kätten kautta.'),
(1696273,58,44,12,1,'Siihen aikaan kuningas Herodes otatti muutamia seurakunnan jäseniä kiinni kiduttaaksensa heitä.'),
(1696274,58,44,12,2,'Ja hän mestautti miekalla Jaakobin, Johanneksen veljen.'),
(1696275,58,44,12,3,'Ja kun hän näki sen olevan juutalaisille mieleen, niin hän sen lisäksi vangitutti Pietarinkin. Silloin olivat happamattoman leivän päivät.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696276,58,44,12,4,'Ja otettuaan hänet kiinni hän pani hänet vankeuteen ja jätti neljän nelimiehisen sotilasvartioston vartioitavaksi, aikoen pääsiäisen jälkeen asettaa hänet kansan eteen.'),
(1696277,58,44,12,5,'Niin pidettiin siis Pietaria vankeudessa; mutta seurakunta rukoili lakkaamatta Jumalaa hänen edestänsä.'),
(1696278,58,44,12,6,'Ja yöllä sitä päivää vasten, jona Herodeksella oli aikomus viedä hänet oikeuden eteen, Pietari nukkui kahden sotamiehen välissä, sidottuna kaksilla kahleilla; ja vartijat vartioitsivat oven edessä vankilaa.'),
(1696279,58,44,12,7,'Ja katso, hänen edessään seisoi Herran enkeli, ja huoneessa loisti valo, ja enkeli sysäsi Pietaria kylkeen ja herätti hänet sanoen: "Nouse nopeasti!" Ja kahleet putosivat hänen käsistään.'),
(1696280,58,44,12,8,'Ja enkeli sanoi hänelle: "Vyötä itsesi ja sido paula-anturat jalkaasi". Ja hän teki niin. Vielä enkeli sanoi hänelle: "Heitä vaippa yllesi ja seuraa minua".'),
(1696281,58,44,12,9,'Ja Pietari lähti ja seurasi häntä, mutta ei tiennyt, että se, mikä enkelin vaikutuksesta tapahtui, oli totta, vaan luuli näkevänsä näyn.'),
(1696282,58,44,12,10,'Ja he kulkivat läpi ensimmäisen vartion ja toisen ja tulivat rautaportille, joka vei kaupunkiin. Se aukeni heille itsestään, ja he menivät ulos ja kulkivat eteenpäin muutamaa katua; ja yhtäkkiä enkeli erkani hänestä.'),
(1696283,58,44,12,11,'Kun Pietari tointui, sanoi hän: "Nyt minä totisesti tiedän, että Herra on lähettänyt enkelinsä ja pelastanut minut Herodeksen käsistä ja kaikesta, mitä Juudan kansa odotti".'),
(1696284,58,44,12,12,'Ja päästyään siitä selville hän kulki kohti Marian, Johanneksen äidin, taloa, sen Johanneksen, jota myös Markukseksi kutsuttiin. Siellä oli monta koolla rukoilemassa.'),
(1696285,58,44,12,13,'Ja kun Pietari kolkutti eteisen ovea, tuli siihen palvelijatar, nimeltä Rode, kuulostamaan;'),
(1696286,58,44,12,14,'ja tunnettuaan Pietarin äänen hän ilossansa ei avannut eteistä vaan juoksi sisään ja kertoi Pietarin seisovan portin takana.'),
(1696287,58,44,12,15,'He sanoivat hänelle: "Sinä hourit". Mutta hän vakuutti puheensa todeksi. Niin he sanoivat: "Se on hänen enkelinsä".'),
(1696288,58,44,12,16,'Mutta Pietari kolkutti yhä; ja kun he avasivat, näkivät he hänet ja hämmästyivät.'),
(1696289,58,44,12,17,'Niin hän viittasi kädellään heitä vaikenemaan ja kertoi heille, kuinka Herra oli vienyt hänet ulos vankeudesta, ja sanoi: "Ilmoittakaa tämä Jaakobille ja veljille". Ja hän lähti pois ja meni toiseen paikkaan.'),
(1696290,58,44,12,18,'Mutta kun päivä koitti, tuli sotamiehille kova hätä siitä, mihin Pietari oli joutunut.'),
(1696291,58,44,12,19,'Ja kun Herodes oli haettanut häntä eikä löytänyt, tutki hän vartijoita ja käski viedä heidät rangaistaviksi. Sitten hän meni Juudeasta Kesareaan ja oleskeli siellä.'),
(1696292,58,44,12,20,'Ja Herodes oli vihoissansa tyyrolaisille ja siidonilaisille. Mutta nämä tulivat yksissä neuvoin hänen luoksensa, ja suostutettuaan puolelleen Blastuksen, kuninkaan kamaripalvelijan, he anoivat rauhaa; sillä heidän maakuntansa sai elatuksensa kuninkaan maasta.'),
(1696293,58,44,12,21,'Niin Herodes määrättynä päivänä pukeutui kuninkaalliseen pukuun, istui istuimelleen ja piti heille puheen;'),
(1696294,58,44,12,22,'siihen kansa huusi: "Jumalan ääni, eikä ihmisen!"'),
(1696295,58,44,12,23,'Mutta heti löi häntä Herran enkeli, sentähden ettei hän antanut kunniaa Jumalalle; ja madot söivät hänet, ja hän heitti henkensä.'),
(1696296,58,44,12,24,'Mutta Jumalan sana menestyi ja levisi.'),
(1696297,58,44,12,25,'Ja Barnabas ja Saulus palasivat Jerusalemista toimitettuansa avustustehtävän ja toivat sieltä mukanaan Johanneksen, jota myös Markukseksi kutsuttiin.'),
(1696298,58,44,13,1,'Ja Antiokian seurakunnassa oli profeettoja ja opettajia: Barnabas ja Simeon, jota kutsuttiin Nigeriksi, ja Lukius, kyreneläinen, ja Manaen, neljännysruhtinas Herodeksen kasvinkumppani, ja Saulus.'),
(1696299,58,44,13,2,'Ja heidän toimittaessaan palvelusta Herralle ja paastotessaan Pyhä Henki sanoi: "Erottakaa minulle Barnabas ja Saulus siihen työhön, johon minä olen heidät kutsunut".'),
(1696300,58,44,13,3,'Silloin he paastosivat ja rukoilivat ja panivat kätensä heidän päällensä ja laskivat heidät menemään.'),
(1696301,58,44,13,4,'Niin he Pyhän Hengen lähettäminä menivät Seleukiaan ja purjehtivat sieltä Kyproon.'),
(1696302,58,44,13,5,'Ja tultuaan Salamiiseen he julistivat Jumalan sanaa juutalaisten synagoogissa, ja heillä oli mukanaan myös Johannes, palvelijana.'),
(1696303,58,44,13,6,'Ja kun he olivat vaeltaneet kautta koko saaren Pafoon asti, tapasivat he erään juutalaisen miehen, noidan ja väärän profeetan, jonka nimi oli Barjeesus.'),
(1696304,58,44,13,7,'Hän oleskeli käskynhaltijan, Sergius Pauluksen, luona, joka oli ymmärtäväinen mies. Tämä kutsui luoksensa Barnabaan ja Sauluksen ja halusi kuulla Jumalan sanaa.'),
(1696305,58,44,13,8,'Mutta Elymas, noita - sillä niin tulkitaan hänen nimensä - vastusti heitä, koettaen kääntää käskynhaltijaa pois uskosta.'),
(1696306,58,44,13,9,'Niin Saulus, myös Paavaliksi kutsuttu, täynnä Pyhää Henkeä loi katseensa häneen'),
(1696307,58,44,13,10,'ja sanoi: "Voi sinua, joka olet kaikkea vilppiä ja kavaluutta täynnä, sinä perkeleen sikiö, kaiken vanhurskauden vihollinen, etkö lakkaa vääristelemästä Herran suoria teitä?'),
(1696308,58,44,13,11,'Ja nyt, katso, Herran käsi on sinun päälläsi, ja sinä tulet sokeaksi etkä aurinkoa näe säädettyyn aikaan asti." Ja heti lankesi hänen päällensä synkeys ja pimeys, ja hän kävi ympäri ja etsi taluttajaa.'),
(1696309,58,44,13,12,'Kun nyt käskynhaltija näki, mitä oli tapahtunut, niin hän uskoi, ihmetellen Herran oppia.'),
(1696310,58,44,13,13,'Ja kun Paavali seuralaisineen oli purjehtinut Pafosta, tulivat he Pamfylian Pergeen; siellä Johannes erosi heistä ja palasi Jerusalemiin.'),
(1696311,58,44,13,14,'Mutta he vaelsivat Pergestä eteenpäin ja saapuivat Pisidian Antiokiaan; ja he menivät synagoogaan sapatinpäivänä ja istuutuivat.'),
(1696312,58,44,13,15,'Ja sittenkuin lakia ja profeettoja oli luettu, lähettivät synagoogan esimiehet sanomaan heille: "Miehet, veljet, jos teillä on jokin kehoituksen sana kansalle, niin puhukaa".'),
(1696313,58,44,13,16,'Niin Paavali nousi ja viittasi kädellään ja sanoi: "Te Israelin miehet ja te, jotka Jumalaa pelkäätte, kuulkaa!'),
(1696314,58,44,13,17,'Tämän Israelin kansan Jumala valitsi meidän isämme ja korotti tämän kansan, heidän muukalaisina ollessaan Egyptin maassa, ja vei heidät sieltä ulos kohotetulla käsivarrella,'),
(1696315,58,44,13,18,'ja hän kärsi heidän tapojansa noin neljäkymmentä vuotta erämaassa'),
(1696316,58,44,13,19,'ja hävitti seitsemän kansaa Kanaanin maasta ja jakoi niiden maan heille perinnöksi.'),
(1696317,58,44,13,20,'Näin kului noin neljäsataa viisikymmentä vuotta. Sen jälkeen hän antoi heille tuomareita profeetta Samueliin saakka.'),
(1696318,58,44,13,21,'Ja sitten he anoivat kuningasta, ja Jumala antoi heille Saulin, Kiisin pojan, miehen Benjaminin sukukunnasta, neljäksikymmeneksi vuodeksi.'),
(1696319,58,44,13,22,'Mutta hän pani hänet viralta ja herätti heille kuninkaaksi Daavidin, josta hän myös todisti ja sanoi: ''Minä olen löytänyt Daavidin, Iisain pojan, sydämeni mukaisen miehen, joka on tekevä kaikessa minun tahtoni''.'),
(1696320,58,44,13,23,'Tämän jälkeläisistä on Jumala lupauksensa mukaan antanut tulla Jeesuksen Israelille Vapahtajaksi,'),
(1696321,58,44,13,24,'sittenkuin Johannes ennen hänen tuloansa oli saarnannut parannuksen kastetta kaikelle Israelin kansalle.'),
(1696322,58,44,13,25,'Mutta kun Johannes oli juoksunsa päättävä, sanoi hän: ''En minä ole se, joksi minua luulette; mutta katso, minun jälkeeni tulee se, jonka kenkiä minä en ole arvollinen jaloista riisumaan''.'),
(1696323,58,44,13,26,'Miehet, veljet, te Aabrahamin suvun lapset, ja te, jotka Jumalaa pelkäätte, meille on tämän pelastuksen sana lähetetty.'),
(1696324,58,44,13,27,'Sillä koska Jerusalemin asukkaat ja heidän hallitusmiehensä eivät Jeesusta tunteneet, niin he tuomitessaan hänet myös toteuttivat profeettain sanat, joita kunakin sapattina luetaan;'),
(1696325,58,44,13,28,'ja vaikka he eivät löytäneet mitään, mistä hän olisi kuoleman ansainnut, anoivat he Pilatukselta, että hänet surmattaisiin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696326,58,44,13,29,'Ja kun he olivat täyttäneet kaiken, mikä hänestä on kirjoitettu, ottivat he hänet alas puusta ja panivat hautaan.'),
(1696327,58,44,13,30,'Mutta Jumala herätti hänet kuolleista.'),
(1696328,58,44,13,31,'Ja hän ilmestyi useina päivinä niille, jotka olivat tulleet hänen kanssansa Galileasta Jerusalemiin ja jotka nyt ovat hänen todistajansa kansan edessä.'),
(1696329,58,44,13,32,'Ja me julistamme teille sen hyvän sanoman, että Jumala on isille annetun lupauksen täyttänyt meidän lapsillemme, herättäen Jeesuksen,'),
(1696330,58,44,13,33,'niinkuin myös toisessa psalmissa on kirjoitettu: ''Sinä olet minun Poikani, tänä päivänä minä olen sinut synnyttänyt''.'),
(1696331,58,44,13,34,'Ja että hän herätti hänet kuolleista, niin ettei hän enää palaja katoavaisuuteen, siitä hän on sanonut näin: ''Minä annan teille pyhät ja lujat Daavidin armot''.'),
(1696332,58,44,13,35,'Sentähden hän myös toisessa paikassa sanoo: ''Sinä et salli Pyhäsi nähdä katoavaisuutta''.'),
(1696333,58,44,13,36,'Sillä kun Daavid oli aikanansa Jumalan tahtoa palvellut, nukkui hän ja tuli otetuksi isiensä tykö ja näki katoavaisuuden.'),
(1696334,58,44,13,37,'Mutta hän, jonka Jumala herätti, ei nähnyt katoavaisuutta.'),
(1696335,58,44,13,38,'Olkoon siis teille tiettävä, miehet ja veljet, että hänen kauttansa julistetaan teille syntien anteeksiantamus'),
(1696336,58,44,13,39,'ja että jokainen, joka uskoo, tulee hänessä vanhurskaaksi, vapaaksi kaikesta, mistä te ette voineet Mooseksen lain kautta vanhurskaiksi tulla.'),
(1696337,58,44,13,40,'Kavahtakaa siis, ettei teitä kohtaa se, mikä on puhuttu profeetoissa:'),
(1696338,58,44,13,41,'''Katsokaa, te halveksijat, ja ihmetelkää ja hukkukaa; sillä minä teen teidän päivinänne teon, teon, jota ette uskoisi, jos joku sen kertoisi teille''."'),
(1696339,58,44,13,42,'Kun he lähtivät ulos, pyydettiin heitä puhumaan näitä asioita tulevanakin sapattina.'),
(1696340,58,44,13,43,'Kun synagoogasta hajaannuttiin, seurasivat monet juutalaiset ja jumalaapelkääväiset käännynnäiset Paavalia ja Barnabasta, jotka puhuivat heille ja kehoittivat heitä pysymään Jumalan armossa.'),
(1696341,58,44,13,44,'Seuraavana sapattina kokoontui lähes koko kaupunki kuulemaan Jumalan sanaa.'),
(1696342,58,44,13,45,'Mutta nähdessään kansanjoukot juutalaiset tulivat kiihkoa täyteen ja väittelivät Paavalin puheita vastaan ja herjasivat.'),
(1696343,58,44,13,46,'Silloin Paavali ja Barnabas puhuivat rohkeasti ja sanoivat: "Teille oli Jumalan sana ensiksi puhuttava; mutta koska te työnnätte sen luotanne ettekä katso itseänne mahdollisiksi iankaikkiseen elämään, niin katso, me käännymme pakanain puoleen.'),
(1696344,58,44,13,47,'Sillä näin on Herra meitä käskenyt: ''Minä olen pannut sinut pakanain valkeudeksi, että sinä olisit pelastukseksi maan ääriin asti''."'),
(1696345,58,44,13,48,'Sen kuullessansa pakanat iloitsivat ja ylistivät Herran sanaa ja uskoivat, kaikki, jotka olivat säädetyt iankaikkiseen elämään.'),
(1696346,58,44,13,49,'Ja Herran sanaa levitettiin kaikkeen siihen maakuntaan.'),
(1696347,58,44,13,50,'Mutta juutalaiset yllyttivät jumalaapelkääväisiä ylhäisiä naisia ja kaupungin ensimmäisiä miehiä ja nostivat vainon Paavalia ja Barnabasta vastaan, ja ne ajoivat heidät pois alueiltansa.'),
(1696348,58,44,13,51,'Niin he pudistivat tomun jaloistansa heitä vastaan ja menivät Ikonioniin.'),
(1696349,58,44,13,52,'Ja opetuslapset tulivat täytetyiksi ilolla ja Pyhällä Hengellä.'),
(1696350,58,44,14,1,'Ikonionissa he samoin menivät juutalaisten synagoogaan ja puhuivat niin, että suuri joukko sekä juutalaisia että kreikkalaisia uskoi.'),
(1696351,58,44,14,2,'Mutta ne juutalaiset, jotka eivät uskoneet, yllyttivät ja kiihdyttivät pakanain mieltä veljiä vastaan.'),
(1696352,58,44,14,3,'Niin he oleskelivat siellä kauan aikaa ja puhuivat rohkeasti, luottaen Herraan, joka armonsa sanan todistukseksi antoi tapahtua tunnustekoja ja ihmeitä heidän kättensä kautta.'),
(1696353,58,44,14,4,'Ja kaupungin väestö jakaantui: toiset olivat juutalaisten puolella, toiset taas apostolien puolella.'),
(1696354,58,44,14,5,'Mutta kun pakanat ja juutalaiset ynnä heidän hallitusmiehensä mielivät ryhtyä pahoinpitelemään ja kivittämään heitä,'),
(1696355,58,44,14,6,'ja he sen huomasivat, pakenivat he Lykaonian kaupunkeihin, Lystraan ja Derbeen, ja niiden ympäristöön.'),
(1696356,58,44,14,7,'Ja siellä he julistivat evankeliumia.'),
(1696357,58,44,14,8,'Ja Lystrassa oli mies, joka istui siellä, hervoton jaloistaan ja rampa äitinsä kohdusta saakka, eikä ollut koskaan kävellyt.'),
(1696358,58,44,14,9,'Hän kuunteli Paavalin puhetta. Ja kun Paavali loi katseensa häneen ja näki hänellä olevan uskon, että hän voi tulla terveeksi,'),
(1696359,58,44,14,10,'sanoi hän suurella äänellä: "Nouse pystyyn jaloillesi". Ja hän kavahti ylös ja käveli.'),
(1696360,58,44,14,11,'Kun kansa näki, mitä Paavali oli tehnyt, korottivat he äänensä ja sanoivat lykaoniankielellä: "Jumalat ovat ihmishahmossa astuneet alas meidän luoksemme".'),
(1696361,58,44,14,12,'Ja he sanoivat Barnabasta Zeukseksi ja Paavalia Hermeeksi, koska hän oli se, joka puhui.'),
(1696362,58,44,14,13,'Ja kaupungin edustalla olevan Zeuksen temppelin pappi toi härkiä ja seppeleitä porttien eteen ja tahtoi väkijoukon kanssa uhrata.'),
(1696363,58,44,14,14,'Mutta kun apostolit Barnabas ja Paavali sen kuulivat, repäisivät he vaatteensa ja juoksivat ulos kansanjoukkoon, huusivat'),
(1696364,58,44,14,15,'ja sanoivat: "Miehet, miksi te näin teette? Mekin olemme ihmisiä, yhtä vajavaisia kuin te, ja julistamme teille evankeliumia, että te kääntyisitte noista turhista jumalista elävän Jumalan puoleen, joka on tehnyt taivaan ja maan ja meren ja kaikki, mitä niissä on.'),
(1696365,58,44,14,16,'Menneitten sukupolvien aikoina hän on sallinut kaikkien pakanain vaeltaa omia teitänsä;'),
(1696366,58,44,14,17,'ja kuitenkaan hän ei ole ollut antamatta todistusta itsestään, sillä hän on tehnyt teille hyvää, antaen teille taivaasta sateita ja hedelmällisiä aikoja ja raviten teidän sydämenne ruualla ja ilolla."'),
(1696367,58,44,14,18,'Näin puhuen he vaivoin saivat kansan hillityksi uhraamasta heille.'),
(1696368,58,44,14,19,'Mutta sinne tuli Antiokiasta ja Ikonionista juutalaisia, ja he suostuttivat kansan puolellensa ja kivittivät Paavalia ja raastoivat hänet kaupungin ulkopuolelle, luullen hänet kuolleeksi.'),
(1696369,58,44,14,20,'Mutta kun opetuslapset olivat kokoontuneet hänen ympärilleen, nousi hän ja meni kaupunkiin. Ja seuraavana päivänä hän lähti Barnabaan kanssa Derbeen.'),
(1696370,58,44,14,21,'Ja julistettuaan evankeliumia siinä kaupungissa ja tehtyään monta opetuslapsiksi he palasivat Lystraan ja Ikonioniin ja Antiokiaan'),
(1696371,58,44,14,22,'ja vahvistivat opetuslasten sieluja ja kehoittivat heitä pysymään uskossa ja sanoivat: "Monen ahdistuksen kautta meidän pitää menemän sisälle Jumalan valtakuntaan".'),
(1696372,58,44,14,23,'Ja kun he olivat valinneet heille vanhimmat jokaisessa seurakunnassa, niin he rukoillen ja paastoten jättivät heidät Herran haltuun, johon he nyt uskoivat.'),
(1696373,58,44,14,24,'Ja he kulkivat läpi Pisidian ja tulivat Pamfyliaan;'),
(1696374,58,44,14,25,'ja julistettuaan sanaa Pergessä he menivät Attaliaan.'),
(1696375,58,44,14,26,'Ja sieltä he purjehtivat Antiokiaan, josta he olivat lähteneet, annettuina Jumalan armon haltuun sitä työtä varten, jonka he nyt olivat suorittaneet.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696376,58,44,14,27,'Ja sinne saavuttuaan he kutsuivat seurakunnan koolle ja kertoivat, kuinka Jumala oli ollut heidän kanssansa ja tehnyt suuria ja kuinka hän oli avannut pakanoille uskon oven.'),
(1696377,58,44,14,28,'Ja he viipyivät pitkän aikaa opetuslasten tykönä.'),
(1696378,58,44,15,1,'Ja Juudeasta tuli sinne muutamia, jotka opettivat veljiä: "Ellette ympärileikkauta itseänne, niinkuin Mooses on säätänyt, ette voi pelastua".'),
(1696379,58,44,15,2,'Kun siitä syntyi riita ja kun Paavali ja Barnabas kiivaasti väittelivät heitä vastaan, niin päätettiin, että Paavalin ja Barnabaan ja muutamien muiden heistä tuli mennä tämän riitakysymyksen tähden apostolien ja vanhinten tykö Jerusalemiin.'),
(1696380,58,44,15,3,'Niin seurakunta varusti heidät matkalle, ja he kulkivat Foinikian ja Samarian kautta ja kertoivat pakanain kääntymyksestä ja ilahuttivat sillä suuresti kaikkia veljiä.'),
(1696381,58,44,15,4,'Ja kun he saapuivat Jerusalemiin, niin seurakunta ja apostolit ja vanhimmat ottivat heidät vastaan; ja he kertoivat, kuinka Jumala oli ollut heidän kanssansa ja tehnyt suuria.'),
(1696382,58,44,15,5,'Mutta fariseusten lahkosta nousivat muutamat, jotka olivat tulleet uskoon, ja sanoivat: "Heidät on ympärileikattava ja heitä on käskettävä noudattamaan Mooseksen lakia".'),
(1696383,58,44,15,6,'Niin apostolit ja vanhimmat kokoontuivat tutkimaan tätä asiaa.'),
(1696384,58,44,15,7,'Ja kun oli paljon väitelty, nousi Pietari ja sanoi heille: "Miehet, veljet, te tiedätte, että Jumala jo kauan aikaa sitten teki teidän keskuudessanne sen valinnan, että pakanat minun suustani saisivat kuulla evankeliumin sanan ja tulisivat uskoon.'),
(1696385,58,44,15,8,'Ja Jumala, sydänten tuntija, todisti heidän puolestansa, antaen heille Pyhän Hengen samoinkuin meillekin.'),
(1696386,58,44,15,9,'eikä tehnyt mitään erotusta meidän ja heidän kesken, sillä hän puhdisti heidän sydämensä uskolla.'),
(1696387,58,44,15,10,'Miksi te siis nyt kiusaatte Jumalaa ja tahdotte panna opetuslasten niskaan ikeen, jota eivät meidän isämme emmekä mekään ole jaksaneet kantaa?'),
(1696388,58,44,15,11,'Mutta me uskomme Herran Jeesuksen armon kautta pelastuvamme, samalla tapaa kuin hekin."'),
(1696389,58,44,15,12,'Niin koko joukko vaikeni, ja he kuuntelivat Barnabasta ja Paavalia, jotka kertoivat, kuinka suuria tunnustekoja ja ihmeitä Jumala oli tehnyt pakanain keskuudessa heidän kauttansa.'),
(1696390,58,44,15,13,'Kun he olivat lakanneet puhumasta, lausui Jaakob: "Miehet, veljet, kuulkaa minua!'),
(1696391,58,44,15,14,'Simeon on kertonut, kuinka Jumala ensi kerran katsoi pakanain puoleen ottaakseen heistä kansan omalle nimellensä.'),
(1696392,58,44,15,15,'Ja tämän kanssa pitävät yhtä profeettain sanat, sillä näin on kirjoitettu:'),
(1696393,58,44,15,16,'''Sen jälkeen minä palajan ja pystytän jälleen Daavidin sortuneen majan; minä korjaan sen repeämät ja nostan sen jälleen pystyyn,'),
(1696394,58,44,15,17,'että jäljelle jääneet ihmiset etsisivät Herraa, ynnä kaikki pakanat, jotka ovat minun nimiini otetut, sanoo Herra, joka tämän tekee,'),
(1696395,58,44,15,18,'mikä on ollut tunnettua hamasta ikiajoista''.'),
(1696396,58,44,15,19,'Sentähden minä olen sitä mieltä, ettei tule rasittaa niitä, jotka pakanuudesta kääntyvät Jumalan puoleen,'),
(1696397,58,44,15,20,'vaan heille kirjoitettakoon, että heidän pitää karttaman epäjumalien saastuttamaa ja haureutta ja lihaa, josta ei veri ole laskettu, sekä verta.'),
(1696398,58,44,15,21,'Sillä Mooseksella on ammoisista ajoista asti joka kaupungissa julistajansa; luetaanhan häntä synagoogissa jokaisena sapattina."'),
(1696399,58,44,15,22,'Silloin apostolit ja vanhimmat ja koko seurakunta näkivät hyväksi valita keskuudestaan muutamia miehiä ja lähettää heidät Antiokiaan Paavalin ja Barnabaan mukana, nimittäin Juudaan, jota kutsuttiin Barsabbaaksi, ja Silaan, jotka olivat johtavia miehiä veljien joukossa;'),
(1696400,58,44,15,23,'ja kirjoittivat heidän mukaansa näin kuuluvan kirjeen: "Me apostolit ja vanhimmat, teidän veljenne, lähetämme teille, pakanuudesta kääntyneille veljille Antiokiassa ja Syyriassa ja Kilikiassa, tervehdyksen.'),
(1696401,58,44,15,24,'Koska olemme kuulleet, että muutamat meistä lähteneet, joille emme ole mitään käskyä antaneet, ovat puheillaan tehneet teidät levottomiksi ja saattaneet teidän sielunne hämmennyksiin,'),
(1696402,58,44,15,25,'niin me olemme yksimielisesti nähneet hyväksi valita miehiä ja lähettää heidät teidän tykönne rakkaiden veljiemme Barnabaan ja Paavalin kanssa,'),
(1696403,58,44,15,26,'jotka ovat panneet henkensä alttiiksi meidän Herramme Jeesuksen Kristuksen nimen tähden.'),
(1696404,58,44,15,27,'Me lähetämme siis Juudaan ja Silaan, jotka myös suusanalla ilmoittavat teille saman.'),
(1696405,58,44,15,28,'Sillä Pyhä Henki ja me olemme nähneet hyväksi, ettei teidän päällenne ole pantava enempää kuormaa kuin nämä välttämättömät:'),
(1696406,58,44,15,29,'että kartatte epäjumalille uhrattua ja verta ja lihaa, josta ei veri ole laskettu, ja haureutta. Jos te näitä vältätte, niin teidän käy hyvin. Jääkää hyvästi!"'),
(1696407,58,44,15,30,'Niin heidät lähetettiin matkalle, ja he tulivat Antiokiaan; siellä he kutsuivat koolle seurakunnan ja antoivat heille kirjeen.'),
(1696408,58,44,15,31,'Ja kun he olivat sen lukeneet, iloitsivat he tästä lohdutuksesta.'),
(1696409,58,44,15,32,'Ja Juudas ja Silas, jotka itsekin olivat profeettoja, kehoittivat veljiä monin sanoin ja vahvistivat heitä.'),
(1696410,58,44,15,33,'Ja heidän viivyttyään siellä jonkin aikaa veljet laskivat heidät rauhassa palaamaan niiden tykö, jotka olivat heidät lähettäneet.'),
(1696411,58,44,15,35,'Ja Paavali ja Barnabas viipyivät Antiokiassa opettaen ja julistaen useiden muidenkin kanssa Herran sanaa.'),
(1696412,58,44,15,36,'Mutta muutamien päivien kuluttua Paavali sanoi Barnabaalle: "Lähtekäämme takaisin kaikkiin niihin kaupunkeihin, joissa olemme julistaneet Herran sanaa, katsomaan veljiä, miten heidän on".'),
(1696413,58,44,15,37,'Niin Barnabas tahtoi ottaa mukaan Johanneksenkin, jota kutsuttiin Markukseksi.'),
(1696414,58,44,15,38,'Mutta Paavali katsoi oikeaksi olla ottamatta häntä mukaan, koska hän oli luopunut heistä Pamfyliassa eikä ollut heidän kanssaan lähtenyt työhön.'),
(1696415,58,44,15,39,'Ja he kiivastuivat niin, että erkanivat toisistaan, ja Barnabas otti mukaansa Markuksen ja purjehti Kyproon.'),
(1696416,58,44,15,40,'Mutta Paavali valitsi Silaan, ja veljet jättivät hänet Herran armon haltuun, ja hän lähti matkalle.'),
(1696417,58,44,15,41,'Ja hän vaelsi läpi Syyrian ja Kilikian vahvistaen seurakuntia.'),
(1696418,58,44,16,1,'Niin hän saapui myös Derbeen ja Lystraan. Ja katso, siellä oli eräs opetuslapsi, nimeltä Timoteus, joka oli uskovaisen juutalaisvaimon poika, mutta isä oli kreikkalainen.'),
(1696419,58,44,16,2,'Hänestä veljet, jotka olivat Lystrassa ja Ikonionissa, todistivat hyvää.'),
(1696420,58,44,16,3,'Paavali tahtoi häntä mukaansa matkalle ja otti hänet ja ympärileikkasi hänet juutalaisten tähden, joita oli niillä paikkakunnilla; sillä kaikki tiesivät, että hänen isänsä oli kreikkalainen.'),
(1696421,58,44,16,4,'Ja sitä mukaa kuin he vaelsivat kaupungista kaupunkiin, antoivat he heille noudatettaviksi ne säädökset, jotka apostolit ja Jerusalemin vanhimmat olivat hyväksyneet.'),
(1696422,58,44,16,5,'Niin seurakunnat vahvistuivat uskossa ja saivat päivä päivältä yhä enemmän jäseniä.'),
(1696423,58,44,16,6,'Ja he kulkivat Frygian ja Galatian maan kautta, sillä Pyhä Henki esti heitä julistamasta sanaa Aasiassa.'),
(1696424,58,44,16,7,'Ja tultuaan Mysian kohdalle he yrittivät lähteä Bityniaan, mutta Jeesuksen Henki ei sallinut heidän sitä tehdä.'),
(1696425,58,44,16,8,'Niin he vaelsivat ohi Mysian ja menivät Trooaaseen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696426,58,44,16,9,'Ja Paavali näki yöllä näyn: makedonialainen mies seisoi ja pyysi häntä sanoen: "Tule yli Makedoniaan ja auta meitä".'),
(1696427,58,44,16,10,'Ja kun hän oli nähnyt sen näyn, niin me kohta tahdoimme päästä lähtemään Makedoniaan, sillä me käsitimme, että Jumala oli kutsunut meitä julistamaan heille evankeliumia.'),
(1696428,58,44,16,11,'Kun nyt olimme purjehtineet Trooaasta, kuljimme suoraan Samotrakeen, ja seuraavana päivänä Neapoliin,'),
(1696429,58,44,16,12,'ja sieltä Filippiin, joka on ensimmäinen kaupunki siinä osassa Makedoniaa, siirtokunta. Siinä kaupungissa me viivyimme muutamia päiviä.'),
(1696430,58,44,16,13,'Ja sapatinpäivänä me menimme kaupungin portin ulkopuolelle, joen rannalle, jossa arvelimme olevan rukouspaikan, ja istuimme sinne ja puhuimme kokoontuneille naisille.'),
(1696431,58,44,16,14,'Ja eräs Lyydia niminen purppuranmyyjä Tyatiran kaupungista, jumalaapelkääväinen nainen, oli kuulemassa; ja Herra avasi hänen sydämensä ottamaan vaarin siitä, mitä Paavali puhui.'),
(1696432,58,44,16,15,'Ja kun hänet ja hänen perhekuntansa oli kastettu, pyysi hän meitä sanoen: "Jos te pidätte minua Herraan uskovaisena, niin tulkaa minun kotiini ja majailkaa siellä". Ja hän vaati meitä.'),
(1696433,58,44,16,16,'Ja tapahtui meidän mennessämme rukouspaikkaan, että meitä vastaan tuli eräs palvelijatar, jossa oli tietäjähenki ja joka tuotti paljon tuloja isännilleen ennustamisellaan.'),
(1696434,58,44,16,17,'Hän seurasi Paavalia ja meitä ja huusi sanoen: "Nämä miehet ovat korkeimman Jumalan palvelijoita, jotka julistavat teille pelastuksen tien".'),
(1696435,58,44,16,18,'Ja tätä hän teki monta päivää. Mutta se vaivasi Paavalia, ja hän kääntyi ja sanoi hengelle: "Jeesuksen Kristuksen nimessä minä käsken sinun lähteä hänestä". Ja se lähti sillä hetkellä.'),
(1696436,58,44,16,19,'Mutta kun hänen isäntänsä näkivät, että tulojen toivo oli heiltä kadonnut, ottivat he Paavalin ja Silaan kiinni ja vetivät heidät torille hallitusmiesten eteen.'),
(1696437,58,44,16,20,'Ja vietyänsä heidät päällikköjen eteen he sanoivat: "Nämä miehet häiritsevät meidän kaupunkimme rauhaa; he ovat juutalaisia'),
(1696438,58,44,16,21,'ja opettavat tapoja, joita meidän ei ole lupa omaksua eikä noudattaa, koska me olemme roomalaisia".'),
(1696439,58,44,16,22,'Ja kansakin nousi heitä vastaan, ja päälliköt revittivät heiltä vaatteet ja käskivät lyödä heitä raipoilla.'),
(1696440,58,44,16,23,'Ja kun olivat heitä paljon pieksättäneet, heittivät he heidät vankeuteen ja käskivät vanginvartijan tarkasti vartioida heitä.'),
(1696441,58,44,16,24,'Sellaisen käskyn saatuaan tämä heitti heidät sisimpään vankihuoneeseen ja pani heidät jalkapuuhun.'),
(1696442,58,44,16,25,'Mutta keskiyön aikaan Paavali ja Silas olivat rukouksissa ja veisasivat ylistystä Jumalalle; ja vangit kuuntelivat heitä.'),
(1696443,58,44,16,26,'Silloin tapahtui yhtäkkiä suuri maanjäristys, niin että vankilan perustukset järkkyivät, ja samassa kaikki ovet aukenivat, ja kaikkien kahleet irtautuivat.'),
(1696444,58,44,16,27,'Kun vanginvartija heräsi ja näki vankilan ovien olevan auki, veti hän miekkansa ja aikoi surmata itsensä, luullen vankien karanneen.'),
(1696445,58,44,16,28,'Mutta Paavali huusi suurella äänellä sanoen: "Älä tee itsellesi mitään pahaa, sillä me kaikki olemme täällä".'),
(1696446,58,44,16,29,'Niin hän pyysi valoa, juoksi sisälle ja lankesi vavisten Paavalin ja Silaan eteen.'),
(1696447,58,44,16,30,'Ja hän vei heidät ulos ja sanoi: "Herrat, mitä minun pitää tekemän, että minä pelastuisin?"'),
(1696448,58,44,16,31,'Niin he sanoivat: "Usko Herraan Jeesukseen, niin sinä pelastut, niin myös sinun perhekuntasi".'),
(1696449,58,44,16,32,'Ja he puhuivat Jumalan sanaa hänelle ynnä kaikille, jotka hänen kodissansa olivat.'),
(1696450,58,44,16,33,'Ja hän otti heidät mukaansa samalla yön hetkellä ja pesi heidän haavansa, ja hänet ja kaikki hänen omaisensa kastettiin kohta.'),
(1696451,58,44,16,34,'Ja hän vei heidät ylös asuntoonsa, laittoi heille aterian ja riemuitsi siitä, että hän ja koko hänen perheensä oli tullut Jumalaan uskovaksi.'),
(1696452,58,44,16,35,'Päivän tultua päälliköt lähettivät oikeudenpalvelijat sanomaan: "Päästä irti ne miehet".'),
(1696453,58,44,16,36,'Niin vanginvartija ilmoitti tämän Paavalille sanoen: "Päälliköt ovat lähettäneet sanan, että teidät on päästettävä irti; lähtekää siis nyt ulos ja menkää rauhassa".'),
(1696454,58,44,16,37,'Mutta Paavali sanoi heille: "He ovat julkisesti, vieläpä ilman tuomiota, ruoskineet meitä, jotka olemme Rooman kansalaisia, ja ovat heittäneet meidät vankeuteen; ja nytkö he salaa ajaisivat meidät tiehemme! Ei niin, vaan tulkoot itse ja viekööt meidät ulos."'),
(1696455,58,44,16,38,'Ja oikeudenpalvelijat kertoivat ne sanat päälliköille; niin nämä peljästyivät kuullessaan heidän olevan roomalaisia,'),
(1696456,58,44,16,39,'ja he tulivat ja suostuttelivat heitä ja veivät heidät ulos ja pyysivät heitä lähtemään pois kaupungista.'),
(1696457,58,44,16,40,'Niin he lähtivät vankilasta ja menivät Lyydian tykö; ja nähtyään veljet ja rohkaistuaan heitä he lähtivät pois.'),
(1696458,58,44,17,1,'Ja he matkustivat Amfipolin ja Apollonian kautta ja tulivat Tessalonikaan, jossa oli juutalaisten synagooga.'),
(1696459,58,44,17,2,'Ja tapansa mukaan Paavali meni sisälle heidän luoksensa ja keskusteli kolmena sapattina heidän kanssansa, lähtien kirjoituksista,'),
(1696460,58,44,17,3,'selitti ne ja osoitti, että Kristuksen piti kärsimän ja nouseman kuolleista, ja sanoi: "Tämä Jeesus, jota minä teille julistan, on Kristus".'),
(1696461,58,44,17,4,'Ja muutamat heistä tulivat uskoon ja liittyivät Paavaliin ja Silaaseen, niin myös suuri joukko jumalaapelkääväisiä kreikkalaisia sekä useat ylhäiset naiset.'),
(1696462,58,44,17,5,'Mutta juutalaiset joutuivat kiihkoon ja ottivat avukseen muutamia pahanilkisiä miehiä joutoväestä, haalivat kansaa kokoon ja nostivat kaupungissa metelin. He asettuivat Jaasonin talon edustalle ja hakivat Paavalia ja Silasta viedäkseen heidät kansan eteen.'),
(1696463,58,44,17,6,'Mutta kun he eivät heitä löytäneet, raastoivat he Jaasonin ja muutamia veljiä kaupungin hallitusmiesten eteen ja huusivat: "Nuo koko maailman villitsijät ovat tännekin tulleet,'),
(1696464,58,44,17,7,'ja heidät Jaason on ottanut vastaan; ja nämä kaikki tekevät vastoin keisarin asetuksia, sanoen erään toisen, Jeesuksen, olevan kuninkaan".'),
(1696465,58,44,17,8,'Kun kansa ja hallitusmiehet tämän kuulivat, tulivat he levottomiksi.'),
(1696466,58,44,17,9,'Ja nämä ottivat takauksen Jaasonilta ja muilta ja päästivät heidät.'),
(1696467,58,44,17,10,'Mutta veljet lähettivät heti yötä myöten Paavalin ja Silaan Bereaan. Ja kun he olivat saapuneet sinne, menivät he juutalaisten synagoogaan.'),
(1696468,58,44,17,11,'Nämä olivat jalompia kuin Tessalonikan juutalaiset; he ottivat sanan vastaan hyvin halukkaasti ja tutkivat joka päivä kirjoituksia, oliko asia niin.'),
(1696469,58,44,17,12,'Ja monet heistä uskoivat, niin myös useat ylhäiset kreikkalaiset naiset ja miehet.'),
(1696470,58,44,17,13,'Mutta kun Tessalonikan juutalaiset saivat tietää, että Paavali Bereassakin julisti Jumalan sanaa, tulivat he sinnekin yllyttämään ja kiihoittamaan kansaa.'),
(1696471,58,44,17,14,'Silloin veljet heti lähettivät Paavalin menemään meren rantaan; mutta sekä Silas että Timoteus jäivät Bereaan.'),
(1696472,58,44,17,15,'Ja Paavalin saattajat veivät hänet Ateenaan saakka, ja saatuaan vietäväksi Silaalle ja Timoteukselle käskyn mitä pikimmin tulla hänen luoksensa, he lähtivät sieltä pois.'),
(1696473,58,44,17,16,'Mutta Paavalin odottaessa heitä Ateenassa hänen henkensä hänessä kiivastui, kun hän näki, että kaupunki oli täynnä epäjumalankuvia.'),
(1696474,58,44,17,17,'Niin hän keskusteli synagoogassa juutalaisten ja jumalaapelkääväisten kanssa ja torilla joka päivä niiden kanssa, joita hän siellä tapasi.'),
(1696475,58,44,17,18,'Ja muutamat epikurolaiset ja stoalaiset filosofit väittelivät hänen kanssansa; ja toiset sanoivat: "Mitähän tuo lavertelija oikein tahtoo sanoa?" Toiset taas sanoivat: "Näkyy olevan vieraiden jumalien julistaja", koska hän julisti heille evankeliumia Jeesuksesta ja ylösnousemuksesta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696476,58,44,17,19,'Ja he ottivat hänet ja veivät Areiopagille ja sanoivat: "Voimmeko saada tietää, mikä se uusi oppi on, jota sinä ilmoitat?'),
(1696477,58,44,17,20,'Sillä outoja asioita sinä tuot meidän korvaimme kuulla. Me siis tahdomme tietää, mitä ne oikein ovat."'),
(1696478,58,44,17,21,'Sillä ateenalaisilla ja siellä oleskelevilla muukalaisilla ei kenelläkään ollut aikaa muuhun kuin uutta puhumaan ja uutta kuulemaan.'),
(1696479,58,44,17,22,'Niin Paavali astui keskelle Areiopagia ja sanoi: "Ateenan miehet, minä näen kaikesta, että te suuresti kunnioitatte jumalia.'),
(1696480,58,44,17,23,'Sillä kävellessäni ympäri ja katsellessani teidän pyhiä paikkojanne minä löysin myös alttarin, johon oli kirjoitettu: ''Tuntemattomalle jumalalle''. Mitä te siis tuntemattanne palvelette, sen minä teille ilmoitan.'),
(1696481,58,44,17,24,'Jumala, joka on tehnyt maailman ja kaikki, mitä siinä on, hän, joka on taivaan ja maan Herra, ei asu käsillä tehdyissä temppeleissä,'),
(1696482,58,44,17,25,'eikä häntä voida ihmisten käsillä palvella, ikäänkuin hän jotakin tarvitsisi, hän, joka itse antaa kaikille elämän ja hengen ja kaiken.'),
(1696483,58,44,17,26,'Ja hän on tehnyt koko ihmissuvun yhdestä ainoasta asumaan kaikkea maanpiiriä ja on säätänyt heille määrätyt ajat ja heidän asumisensa rajat,'),
(1696484,58,44,17,27,'että he etsisivät Jumalaa, jos ehkä voisivat hapuilemalla hänet löytää - hänet, joka kuitenkaan ei ole kaukana yhdestäkään meistä;'),
(1696485,58,44,17,28,'sillä hänessä me elämme ja liikumme ja olemme, niinkuin myös muutamat teidän runoilijoistanne ovat sanoneet: ''Sillä me olemme myös hänen sukuansa''.'),
(1696486,58,44,17,29,'Koska me siis olemme Jumalan sukua, emme saa luulla, että jumaluus on samankaltainen kuin kulta tai hopea tai kivi, sellainen kuin inhimillisen taiteen ja ajatuksen kuvailema.'),
(1696487,58,44,17,30,'Noita tietämättömyyden aikoja Jumala on kärsinyt, mutta nyt hän tekee tiettäväksi, että kaikkien ihmisten kaikkialla on tehtävä parannus.'),
(1696488,58,44,17,31,'Sillä hän on säätänyt päivän, jona hän on tuomitseva maanpiirin vanhurskaudessa sen miehen kautta, jonka hän siihen on määrännyt; ja hän on antanut kaikille siitä vakuuden, herättämällä hänet kuolleista."'),
(1696489,58,44,17,32,'Kuullessaan kuolleitten ylösnousemuksesta toiset ivasivat, toiset taas sanoivat: "Me tahdomme kuulla sinulta tästä vielä toistekin".'),
(1696490,58,44,17,33,'Ja niin Paavali lähti heidän keskeltänsä.'),
(1696491,58,44,17,34,'Mutta muutamat liittyivät häneen ja uskoivat; niiden joukossa oli Dionysius, Areiopagin jäsen, ja eräs nainen, nimeltä Damaris, sekä muita heidän kanssansa.'),
(1696492,58,44,18,1,'Sen jälkeen Paavali lähti Ateenasta ja meni Korinttoon.'),
(1696493,58,44,18,2,'Siellä hän tapasi erään Akylas nimisen juutalaisen, joka oli Pontosta syntyisin ja äsken tullut Italiasta, ja hänen vaimonsa Priskillan. Klaudius oli näet käskenyt kaikkien juutalaisten poistua Roomasta. Ja Paavali meni heidän luoksensa.'),
(1696494,58,44,18,3,'Ja kun hänellä oli sama ammatti kuin heillä, jäi hän heidän luoksensa, ja he tekivät työtä yhdessä; sillä he olivat ammatiltaan teltantekijöitä.'),
(1696495,58,44,18,4,'Ja hän keskusteli synagoogassa jokaisena sapattina ja sai sekä juutalaisia että kreikkalaisia uskomaan.'),
(1696496,58,44,18,5,'Ja kun Silas ja Timoteus tulivat Makedoniasta, oli Paavali kokonaan antautunut sanan julistamiseen ja todisti juutalaisille, että Jeesus on Kristus.'),
(1696497,58,44,18,6,'Mutta kun he vastustivat ja herjasivat, pudisti hän vaatteitansa ja sanoi heille: "Tulkoon teidän verenne oman päänne päälle! Viaton olen minä; tästedes minä menen pakanain tykö."'),
(1696498,58,44,18,7,'Ja hän lähti sieltä ja meni erään Titius Justus nimisen jumalaapelkääväisen miehen tykö, jonka talo oli aivan synagoogan vieressä.'),
(1696499,58,44,18,8,'Mutta synagoogan esimies Krispus ja koko hänen perhekuntansa uskoivat Herraan; ja myöskin monet korinttolaiset, jotka olivat kuulemassa, uskoivat, ja heidät kastettiin.'),
(1696500,58,44,18,9,'Ja Herra sanoi yöllä näyssä Paavalille: "Älä pelkää, vaan puhu, äläkä vaikene,'),
(1696501,58,44,18,10,'sillä minä olen sinun kanssasi, eikä kukaan ole ryhtyvä sinuun tehdäkseen sinulle pahaa, sillä minulla on paljon kansaa tässä kaupungissa".'),
(1696502,58,44,18,11,'Niin hän viipyi siellä vuoden ja kuusi kuukautta opettaen heidän keskuudessaan Jumalan sanaa.'),
(1696503,58,44,18,12,'Mutta Gallionin ollessa Akaian käskynhaltijana juutalaiset yksimielisesti nousivat Paavalia vastaan ja veivät hänet tuomioistuimen eteen'),
(1696504,58,44,18,13,'ja sanoivat: "Tämä viettelee ihmisiä palvelemaan Jumalaa lainvastaisella tavalla".'),
(1696505,58,44,18,14,'Ja kun Paavali aikoi avata suunsa, sanoi Gallion juutalaisille: "Jos olisi tehty rikos tai häijy ilkityö, olisi kohtuullista, että minä kärsivällisesti kuuntelisin teitä, juutalaiset.'),
(1696506,58,44,18,15,'Mutta jos teillä on riitakysymyksiä opista ja nimistä ja teidän laistanne, olkoot ne teidän huolenanne; niiden tuomari minä en tahdo olla."'),
(1696507,58,44,18,16,'Ja hän ajoi heidät pois tuomioistuimen edestä.'),
(1696508,58,44,18,17,'Niin he kaikki ottivat kiinni Soosteneen, synagoogan esimiehen, ja löivät häntä tuomioistuimen edessä, eikä Gallion välittänyt siitä mitään.'),
(1696509,58,44,18,18,'Mutta Paavali viipyi siellä vielä jonkun aikaa; sitten hän sanoi veljille jäähyväiset ja purjehti Syyriaan, mukanansa Priskilla ja Akylas; hän oli leikkauttanut tukkansa Kenkreassa, sillä hän oli tehnyt lupauksen.'),
(1696510,58,44,18,19,'Ja he saapuivat Efesoon; sinne hän jätti heidät. Ja hän meni synagoogaan ja keskusteli juutalaisten kanssa.'),
(1696511,58,44,18,20,'Ja he pyysivät häntä viipymään kauemmin, mutta hän ei suostunut,'),
(1696512,58,44,18,21,'vaan sanoi heille jäähyväiset ja lausui: "Minä palaan jälleen teidän tykönne, jos Jumala suo". Ja hän lähti purjehtimaan Efesosta.'),
(1696513,58,44,18,22,'Ja noustuaan maihin Kesareassa hän vaelsi ylös Jerusalemiin ja tervehti seurakuntaa ja meni sitten alas Antiokiaan.'),
(1696514,58,44,18,23,'Kun hän oli viettänyt siellä jonkun aikaa, lähti hän matkalle ja kulki järjestään kautta Galatian maakunnan ja Frygian, vahvistaen kaikkia opetuslapsia.'),
(1696515,58,44,18,24,'Ja Efesoon saapui eräs juutalainen, nimeltä Apollos, syntyisin Aleksandriasta, puhetaitoinen mies ja väkevä raamatuissa.'),
(1696516,58,44,18,25,'Tälle oli opetettu Herran tie, ja hän puhui palavana hengessä ja opetti tarkoin Jeesuksesta, mutta tunsi ainoastaan Johanneksen kasteen.'),
(1696517,58,44,18,26,'Hän rupesi rohkeasti puhumaan synagoogassa. Mutta kun Priskilla ja Akylas olivat häntä kuunnelleet, ottivat he hänet luokseen ja selvittivät hänelle tarkemmin Jumalan tien.'),
(1696518,58,44,18,27,'Ja kun hän tahtoi mennä Akaiaan, niin veljet kehoittivat häntä siihen ja kirjoittivat opetuslapsille, että nämä ottaisivat hänet vastaan. Ja sinne saavuttuaan hän armon kautta oli suureksi hyödyksi uskoon tulleille.'),
(1696519,58,44,18,28,'Sillä hän kumosi suurella voimalla julkisesti juutalaisten väitteet ja näytti kirjoituksista toteen, että Jeesus on Kristus.'),
(1696520,58,44,19,1,'Kun Apollos oli Korintossa, tuli Paavali, kuljettuaan läpi ylämaakuntien, Efesoon ja tapasi siellä muutamia opetuslapsia.'),
(1696521,58,44,19,2,'Ja hän sanoi heille: "Saitteko Pyhän Hengen silloin, kun te tulitte uskoon?" Niin he sanoivat hänelle: "Emme ole edes kuulleet, että Pyhää Henkeä on olemassakaan".'),
(1696522,58,44,19,3,'Ja hän sanoi: "Millä kasteella te sitten olette kastetut?" He vastasivat: "Johanneksen kasteella".'),
(1696523,58,44,19,4,'Niin Paavali sanoi: "Johannes kastoi parannuksen kasteella, kehoittaen kansaa uskomaan häneen, joka oli tuleva hänen jälkeensä, se on, Jeesukseen".'),
(1696524,58,44,19,5,'Sen kuultuaan he ottivat kasteen Herran Jeesuksen nimeen.'),
(1696525,58,44,19,6,'Ja kun Paavali pani kätensä heidän päälleen, tuli heidän päällensä Pyhä Henki, ja he puhuivat kielillä ja ennustivat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696526,58,44,19,7,'Heitä oli kaikkiaan noin kaksitoista miestä.'),
(1696527,58,44,19,8,'Ja hän meni synagoogaan, ja kolmen kuukauden ajan hän puhui heidän kanssansa rohkeasti ja vakuuttavasti Jumalan valtakunnasta.'),
(1696528,58,44,19,9,'Mutta kun muutamat paaduttivat itsensä eivätkä uskoneet, vaan puhuivat pahaa Herran tiestä kansan edessä, niin hän meni pois heidän luotaan ja erotti opetuslapset heistä ja piti joka päivä keskusteluja Tyrannuksen koulussa.'),
(1696529,58,44,19,10,'Ja sitä kesti kaksi vuotta, niin että kaikki Aasian asukkaat, sekä juutalaiset että kreikkalaiset, saivat kuulla Herran sanan.'),
(1696530,58,44,19,11,'Ja Jumala teki ylen voimallisia tekoja Paavalin kätten kautta,'),
(1696531,58,44,19,12,'niin että vieläpä hikiliinoja ja esivaatteita hänen iholtansa vietiin sairasten päälle, ja taudit lähtivät heistä ja pahat henget pakenivat pois.'),
(1696532,58,44,19,13,'Myöskin muutamat kuljeksivat juutalaiset loitsijat rupesivat lausumaan Herran Jeesuksen nimeä niiden ylitse, joissa oli pahoja henkiä, sanoen: "Minä vannotan teitä sen Jeesuksen kautta, jota Paavali julistaa".'),
(1696533,58,44,19,14,'Ja niiden joukossa, jotka näin tekivät, oli myös erään juutalaisen ylipapin, Skeuaan, seitsemän poikaa;'),
(1696534,58,44,19,15,'mutta paha henki vastasi heille sanoen: "Jeesuksen minä tunnen, ja Paavalin minä tiedän, mutta keitä te olette?"'),
(1696535,58,44,19,16,'Ja se mies, jossa paha henki oli, karkasi heidän kimppuunsa, voitti heidät toisen toisensa perästä ja runteli heitä, niin että he alastomina ja haavoitettuina pakenivat siitä huoneesta.'),
(1696536,58,44,19,17,'Ja tämän saivat tietää kaikki Efeson asukkaat, sekä juutalaiset että kreikkalaiset; ja heidät kaikki valtasi pelko, ja Herran Jeesuksen nimeä ylistettiin suuresti.'),
(1696537,58,44,19,18,'Ja monet niistä, jotka olivat tulleet uskoon, menivät ja tunnustivat ja ilmoittivat tekonsa.'),
(1696538,58,44,19,19,'Ja useat niistä, jotka olivat taikuutta harjoittaneet, kantoivat kirjansa kokoon ja polttivat ne kaikkien nähden; ja kun niiden arvo laskettiin yhteen, huomattiin sen olevan viisikymmentä tuhatta hopearahaa.'),
(1696539,58,44,19,20,'Näin Herran sana voimallisesti kasvoi ja vahvistui.'),
(1696540,58,44,19,21,'Kun kaikki tämä oli tapahtunut, niin Paavali hengessä päätti kulkea Makedonian ja Akaian kautta ja matkustaa Jerusalemiin ja sanoi: "Käytyäni siellä minun pitää nähdä myös Rooma".'),
(1696541,58,44,19,22,'Ja hän lähetti Makedoniaan kaksi apumiehistänsä, Timoteuksen ja Erastuksen, mutta jäi itse joksikin aikaa Aasiaan.'),
(1696542,58,44,19,23,'Tähän aikaan syntyi sangen suuri melu siitä tiestä.'),
(1696543,58,44,19,24,'Sillä eräs hopeaseppä, nimeltä Demetrius, joka valmisti hopeaisia Artemiin temppeleitä, hankki sillä ammattilaisille melkoisia tuloja.'),
(1696544,58,44,19,25,'Hän kutsui kokoon nämä sekä muut, jotka sellaista työtä tekivät, ja sanoi: "Miehet, te tiedätte, että meillä on hyvä toimeentulomme tästä työstä;'),
(1696545,58,44,19,26,'mutta nyt te näette ja kuulette, että tuo Paavali on, ei ainoastaan Efesossa, vaan melkein koko Aasiassa, uskotellut ja vietellyt paljon kansaa, sanoen, etteivät ne ole jumalia, jotka käsillä tehdään.'),
(1696546,58,44,19,27,'Ja nyt uhkaa se vaara, että ei ainoastaan tämä meidän elinkeinomme joudu halveksituksi, vaan myöskin, että suuren Artemis jumalattaren temppeliä ei pidetä minäkään ja että hän menettää mahtavuutensa, hän, jota koko Aasia ja koko maanpiiri palvelee."'),
(1696547,58,44,19,28,'Kun he sen kuulivat, tulivat he vihaa täyteen ja huusivat sanoen: "Suuri on efesolaisten Artemis!"'),
(1696548,58,44,19,29,'Ja koko kaupunki joutui sekasortoon, ja he ryntäsivät kaikki yhdessä näytelmäpaikkaan ja tempasivat mukaansa Gaiuksen ja Aristarkuksen, kaksi makedonialaista, jotka olivat Paavalin matkatovereita.'),
(1696549,58,44,19,30,'Ja kun Paavali tahtoi mennä kansanjoukkoon, eivät opetuslapset sitä sallineet.'),
(1696550,58,44,19,31,'Ja myös muutamat Aasian hallitusmiehistä, jotka olivat hänen ystäviään, lähettivät hänelle sanan ja pyysivät, ettei hän menisi näytelmäpaikkaan.'),
(1696551,58,44,19,32,'Ja he huusivat, mikä mitäkin; sillä kokous oli sekasortoinen, ja useimmat eivät tienneet, minkätähden he olivat tulleet kokoon.'),
(1696552,58,44,19,33,'Silloin vedettiin joukosta esille Aleksander, jota juutalaiset työnsivät esiin; niin Aleksander viittasi kädellään merkiksi, että hän tahtoi pitää puolustuspuheen kansan edessä.'),
(1696553,58,44,19,34,'Mutta kun he huomasivat, että hän oli juutalainen, rupesivat he kaikki yhteen ääneen huutamaan ja kirkuivat noin kaksi hetkeä: "Suuri on efesolaisten Artemis!"'),
(1696554,58,44,19,35,'Mutta kun kaupungin kansleri oli saanut kansan rauhoittumaan, sanoi hän: "Efeson miehet, onko ketään, joka ei tiedä, että efesolaisten kaupunki on suuren Artemiin temppelin ja hänen taivaasta pudonneen kuvansa vaalija?'),
(1696555,58,44,19,36,'Koska ei kukaan voi tätä kieltää, tulee teidän siis pysyä rauhallisina eikä tehdä mitään harkitsematonta.'),
(1696556,58,44,19,37,'Te olette kuitenkin tuoneet tänne nämä miehet, jotka eivät ole temppelin ryöstäjiä eivätkä ole meidän jumalatartamme pilkanneet.'),
(1696557,58,44,19,38,'Jos siis Demetriuksella ja hänen ammattiveljillänsä on riita-asiaa jotakuta vastaan, niin pidetäänhän oikeudenistuntoja ja onhan käskynhaltijoita; vetäkööt toisensa oikeuteen.'),
(1696558,58,44,19,39,'Ja jos teillä on vielä jotakin muuta vaadittavaa, niin ratkaistakoon asia laillisessa kansankokouksessa.'),
(1696559,58,44,19,40,'Sillä tämänpäiväisen tapahtuman tähden me olemme vaarassa joutua syytteeseen jopa kapinasta, vaikkei mitään aihetta olekaan; ja silloin me emme voi vastata tästä mellakasta." Näin puhuen hän sai kokouksen hajaantumaan.'),
(1696560,58,44,20,1,'Kun meteli oli asettunut, kutsui Paavali opetuslapset luoksensa; ja rohkaistuaan heitä hän jätti heidät hyvästi ja lähti matkustamaan Makedoniaan.'),
(1696561,58,44,20,2,'Ja kuljettuaan niiden paikkakuntien läpi ja puhuttuaan siellä monta kehoituksen sanaa hän tuli Kreikkaan.'),
(1696562,58,44,20,3,'Siellä hän oleskeli kolme kuukautta. Ja kun juutalaiset olivat tehneet häntä vastaan salahankkeen hänen aikoessaan lähteä meritse Syyriaan, päätti hän tehdä paluumatkansa Makedonian kautta.'),
(1696563,58,44,20,4,'Ja häntä seurasivat berealainen Soopater, Pyrruksen poika, ja tessalonikalaisista Aristarkus ja Sekundus, derbeläinen Gaius, Timoteus sekä aasialaiset Tykikus ja Trofimus.'),
(1696564,58,44,20,5,'Nämä menivät edeltä ja odottivat meitä Trooaassa;'),
(1696565,58,44,20,6,'mutta me purjehdimme happamattoman leivän juhlan jälkeen Filippistä ja tulimme viidentenä päivänä heidän luoksensa Trooaaseen ja viivyimme siellä seitsemän päivää.'),
(1696566,58,44,20,7,'Ja kun viikon ensimmäisenä päivänä olimme kokoontuneet murtamaan leipää, niin Paavali, joka seuraavana päivänä aikoi matkustaa pois, keskusteli heidän kanssansa ja pitkitti puhettaan puoliyöhön saakka.'),
(1696567,58,44,20,8,'Ja monta lamppua oli palamassa yläsalissa, jossa me olimme koolla.'),
(1696568,58,44,20,9,'Niin eräs nuorukainen, nimeltä Eutykus, istui ikkunalla, ja kun Paavalin puhe kesti niin kauan, vaipui hän sikeään uneen ja putosi unen vallassa kolmannesta kerroksesta maahan; ja hänet nostettiin ylös kuolleena.'),
(1696569,58,44,20,10,'Mutta Paavali meni alas, heittäytyi hänen ylitsensä, kiersi kätensä hänen ympärilleen ja sanoi: "Älkää hätäilkö, sillä hänessä on vielä henki".'),
(1696570,58,44,20,11,'Niin hän meni jälleen ylös, mursi leipää ja söi; ja hän puhui kauan heidän kanssansa, päivän koittoon asti, ja lähti sitten matkalle.'),
(1696571,58,44,20,12,'Ja he veivät pojan sieltä elävänä ja tulivat suuresti lohdutetuiksi.'),
(1696572,58,44,20,13,'Mutta me menimme edeltäpäin ja astuimme laivaan ja purjehdimme Assoon. Sieltä aioimme ottaa Paavalin laivaan, sillä hän oli niin määrännyt, aikoen itse kulkea maitse.'),
(1696573,58,44,20,14,'Ja kun hän yhtyi meihin Assossa, otimme hänet laivaan ja kuljimme Mityleneen.'),
(1696574,58,44,20,15,'Sieltä me purjehdimme ja saavuimme toisena päivänä Kion kohdalle; seuraavana päivänä laskimme Samoon ja tulimme sen jälkeisenä päivänä Miletoon.'),
(1696575,58,44,20,16,'Sillä Paavali oli päättänyt purjehtia Efeson ohitse, ettei häneltä kuluisi aikaa Aasiassa; sillä hän kiiruhti joutuakseen, jos suinkin mahdollista, helluntaiksi Jerusalemiin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696576,58,44,20,17,'Mutta Miletosta hän lähetti sanan Efesoon ja kutsui tykönsä seurakunnan vanhimmat.'),
(1696577,58,44,20,18,'Ja kun he saapuivat hänen tykönsä, sanoi hän heille: "Te tiedätte ensimmäisestä päivästä asti, kun minä Aasiaan tulin, miten minä kaiken aikaa olen ollut teidän kanssanne;'),
(1696578,58,44,20,19,'kuinka minä olen palvellut Herraa kaikella nöyryydellä ja kyynelillä, koettelemuksissa, jotka ovat kohdanneet minua juutalaisten salahankkeiden tähden;'),
(1696579,58,44,20,20,'kuinka minä en ole vetäytynyt pois julistamasta teille sitä, mikä hyödyllistä on, ja opettamasta teitä sekä julkisesti että huone huoneelta,'),
(1696580,58,44,20,21,'vaan olen todistanut sekä juutalaisille että kreikkalaisille parannusta kääntymyksessä Jumalan puoleen ja uskoa meidän Herraamme Jeesukseen Kristukseen.'),
(1696581,58,44,20,22,'Ja nyt, katso, minä matkustan, sidottuna hengessä, Jerusalemiin, enkä tiedä, mikä minua siellä kohtaa.'),
(1696582,58,44,20,23,'Sen vain tiedän, että Pyhä Henki jokaisessa kaupungissa todistaa minulle ja sanoo, että kahleet ja ahdistukset minua odottavat.'),
(1696583,58,44,20,24,'En minä kuitenkaan pidä henkeäni itselleni minkään arvoisena, kunhan vain täytän juoksuni ja sen viran, jonka minä Herralta Jeesukselta olen saanut: Jumalan armon evankeliumin todistamisen.'),
(1696584,58,44,20,25,'Ja nyt, katso, minä tiedän, ettette enää saa nähdä minun kasvojani, ei kukaan teistä, joiden keskuudessa minä olen vaeltanut ja saarnannut valtakuntaa.'),
(1696585,58,44,20,26,'Sentähden minä todistan teille tänä päivänä, että minä olen viaton kaikkien vereen.'),
(1696586,58,44,20,27,'Sillä minä en ole vetäytynyt pois julistamasta teille kaikkea Jumalan tahtoa.'),
(1696587,58,44,20,28,'Ottakaa siis itsestänne vaari ja kaikesta laumasta, johon Pyhä Henki on teidät pannut kaitsijoiksi, paimentamaan Herran seurakuntaa, jonka hän omalla verellänsä on itselleen ansainnut.'),
(1696588,58,44,20,29,'Minä tiedän, että minun lähtöni jälkeen teidän keskuuteenne tulee julmia susia, jotka eivät laumaa säästä,'),
(1696589,58,44,20,30,'ja teidän omasta joukostanne nousee miehiä, jotka väärää puhetta puhuvat, vetääkseen opetuslapset mukaansa.'),
(1696590,58,44,20,31,'Valvokaa sentähden ja muistakaa, että minä olen kolme vuotta lakkaamatta yötä ja päivää kyynelin neuvonut teitä itsekutakin.'),
(1696591,58,44,20,32,'Ja nyt minä uskon teidät Jumalan ja hänen armonsa sanan haltuun, hänen, joka on voimallinen rakentamaan teitä ja antamaan teille perintöosan kaikkien pyhitettyjen joukossa.'),
(1696592,58,44,20,33,'En minä ole halunnut kenenkään hopeata tai kultaa tai vaatteita;'),
(1696593,58,44,20,34,'te tiedätte itse, että nämä minun käteni ovat työllänsä hankkineet, mitä minä ja seuralaiseni olemme tarvinneet.'),
(1696594,58,44,20,35,'Kaikessa minä olen osoittanut teille, että näin työtä tehden tulee huolehtia heikoista ja muistaa nämä Herran Jeesuksen sanat, jotka hän itse sanoi: ''Autuaampi on antaa kuin ottaa''."'),
(1696595,58,44,20,36,'Ja tämän sanottuaan hän polvistui ja rukoili kaikkien heidän kanssansa.'),
(1696596,58,44,20,37,'Ja he ratkesivat kaikki haikeasti itkemään ja lankesivat Paavalin kaulaan ja suutelivat häntä,'),
(1696597,58,44,20,38,'ja enimmän suretti heitä se sana, jonka hän oli sanonut, etteivät he enää saisi nähdä hänen kasvojansa. Ja he saattoivat hänet laivaan.'),
(1696598,58,44,21,1,'Kun olimme eronneet heistä ja lähteneet purjehtimaan, laskimme suoraan Koossaareen ja seuraavana päivänä Rodoon ja sieltä Pataraan.'),
(1696599,58,44,21,2,'Siellä tapasimme Foinikiaan menevän laivan, astuimme siihen ja lähdimme purjehtimaan.'),
(1696600,58,44,21,3,'Ja kun Kypro rupesi näkymään ja oli jäänyt meistä vasemmalle, purjehdimme Syyriaan ja nousimme maihin Tyyrossa; siellä näet laivan oli määrä purkaa lastinsa.'),
(1696601,58,44,21,4,'Ja tavattuamme opetuslapset me viivyimme siellä seitsemän päivää. Ja Hengen vaikutuksesta he varoittivat Paavalia menemästä Jerusalemiin.'),
(1696602,58,44,21,5,'Mutta kun olimme viettäneet loppuun ne päivät, lähdimme matkalle, ja kaikki saattoivat vaimoineen ja lapsineen meitä kaupungin ulkopuolelle saakka. Ja me laskeuduimme rannalla polvillemme ja rukoilimme;'),
(1696603,58,44,21,6,'ja sanottuamme jäähyväiset toisillemme astuimme laivaan, ja he palasivat kotiinsa.'),
(1696604,58,44,21,7,'Tyyrosta me saavuimme Ptolemaikseen, ja siihen päättyi purjehduksemme. Ja me tervehdimme veljiä siellä ja viivyimme päivän heidän luonansa.'),
(1696605,58,44,21,8,'Mutta seuraavana päivänä me lähdimme sieltä ja tulimme Kesareaan, jossa menimme evankelista Filippuksen tykö, joka oli yksi niistä seitsemästä, ja jäimme hänen tykönsä.'),
(1696606,58,44,21,9,'Ja hänellä oli neljä tytärtä, neitsyttä, joilla oli profetoimisen lahja.'),
(1696607,58,44,21,10,'Siellä me viivyimme useita päiviä. Niin tuli sinne Juudeasta eräs profeetta, nimeltä Agabus.'),
(1696608,58,44,21,11,'Ja tultuaan meidän luoksemme hän otti Paavalin vyön, sitoi sillä jalkansa ja kätensä ja lausui: "Näin sanoo Pyhä Henki: ''Sen miehen, jonka vyö tämä on, juutalaiset näin sitovat Jerusalemissa ja antavat pakanain käsiin''."'),
(1696609,58,44,21,12,'Kun sen kuulimme, pyysimme, sekä me että ne, jotka siellä asuivat, ettei hän menisi Jerusalemiin.'),
(1696610,58,44,21,13,'Silloin Paavali vastasi ja sanoi: "Mitä te teette, kun itkette ja särjette minun sydäntäni. Sillä minä olen valmis, en ainoastaan käymään sidottavaksi vaan myöskin kuolemaan Jerusalemissa Herran Jeesuksen nimen tähden."'),
(1696611,58,44,21,14,'Ja kun hän ei taipunut, niin me rauhoituimme ja sanoimme: "Tapahtukoon Herran tahto".'),
(1696612,58,44,21,15,'Niiden päivien kuluttua me hankkiuduimme ja menimme ylös Jerusalemiin.'),
(1696613,58,44,21,16,'Ja meidän kanssamme tuli myös opetuslapsia Kesareasta, jotka veivät meidät majapaikkaamme, erään vanhan opetuslapsen, kyprolaisen Mnasonin, tykö.'),
(1696614,58,44,21,17,'Ja saavuttuamme Jerusalemiin veljet ottivat meidät iloiten vastaan.'),
(1696615,58,44,21,18,'Seuraavana päivänä Paavali meni meidän kanssamme Jaakobin tykö, ja kaikki vanhimmat tulivat sinne saapuville.'),
(1696616,58,44,21,19,'Ja kun hän oli heitä tervehtinyt, kertoi hän kohta kohdalta kaikki, mitä Jumala hänen palveluksensa kautta oli tehnyt pakanain keskuudessa.'),
(1696617,58,44,21,20,'Sen kuultuaan he ylistivät Jumalaa ja sanoivat Paavalille: "Sinä näet, veli, kuinka monta tuhatta juutalaista on tullut uskoon, ja he ovat kaikki lainkiivailijoita.'),
(1696618,58,44,21,21,'Mutta heille on kerrottu sinusta, että sinä opetat kaikkia pakanain seassa asuvia juutalaisia luopumaan Mooseksesta ja kiellät heitä ympärileikkaamasta lapsiaan ja vaeltamasta säädettyjen tapojen mukaan.'),
(1696619,58,44,21,22,'Mitä siis on tehtävä? Varmaankin on suuri joukko kokoontuva, sillä he saavat kuulla sinun tulleen.'),
(1696620,58,44,21,23,'Tee siis tämä, minkä me nyt sinulle sanomme. Meillä on täällä neljä miestä, joilla on lupaus täytettävänä.'),
(1696621,58,44,21,24,'Ota ne luoksesi ja puhdista itsesi heidän kanssansa ja maksa kulut heidän puolestaan, että he saisivat leikkauttaa tukkansa; siitä kaikki huomaavat, ettei ole mitään perää siinä, mitä heille on kerrottu sinusta, vaan että sinäkin vaellat lain mukaan ja noudatat sitä.'),
(1696622,58,44,21,25,'Mutta uskoon tulleista pakanoista me olemme päättäneet ja kirjoittaneet, että heidän on välttäminen epäjumalille uhrattua ja verta ja lihaa, josta ei veri ole laskettu, ja haureutta."'),
(1696623,58,44,21,26,'Silloin Paavali otti ne miehet luokseen, ja kun hän seuraavana päivänä oli puhdistanut itsensä heidän kanssaan, meni hän pyhäkköön ja ilmoitti, milloin heidän puhdistumispäivänsä tulisivat päättymään, jota ennen heidän kunkin edestä oli tuotava uhri.'),
(1696624,58,44,21,27,'Mutta kun ne seitsemän päivää olivat päättymässä, näkivät Aasiasta tulleet juutalaiset hänet pyhäkössä, kiihoittivat kaiken kansan ja kävivät häneen käsiksi'),
(1696625,58,44,21,28,'ja huusivat: "Israelin miehet, auttakaa! Tämä on se mies, joka kaikkialla opettaa kaikkia ihmisiä meidän kansaamme ja lakiamme ja tätä paikkaa vastaan, onpa vielä tuonut kreikkalaisia pyhäkköönkin ja saastuttanut tämän pyhän paikan."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696626,58,44,21,29,'Sillä he olivat ennen nähneet efesolaisen Trofimuksen kaupungilla hänen kanssaan ja luulivat, että Paavali oli tuonut hänet pyhäkköön.'),
(1696627,58,44,21,30,'Ja koko kaupunki tuli liikkeelle, ja väkeä juoksi kokoon; ja he ottivat Paavalin kiinni, raastoivat hänet ulos pyhäköstä, ja heti portit suljettiin.'),
(1696628,58,44,21,31,'Ja kun he tahtoivat hänet tappaa, sai sotaväenosaston päällikkö sanan, että koko Jerusalem oli kuohuksissa.'),
(1696629,58,44,21,32,'Tämä otti heti paikalla mukaansa sotilaita ja sadanpäämiehiä ja riensi alas heidän luoksensa. Kun he näkivät päällikön ja sotilaat, lakkasivat he lyömästä Paavalia.'),
(1696630,58,44,21,33,'Silloin päällikkö astui esiin, otatti hänet kiinni ja käski sitoa hänet kaksilla kahleilla ja kysyi, kuka hän oli ja mitä hän oli tehnyt.'),
(1696631,58,44,21,34,'Mutta kansanjoukosta huusivat toiset sitä, toiset tätä. Ja koska hän melun tähden ei voinut saada varmaa selkoa, käski hän viedä hänet kasarmiin.'),
(1696632,58,44,21,35,'Ja kun Paavali tuli portaille, täytyi sotamiesten kantaa häntä kansan väkivallan tähden;'),
(1696633,58,44,21,36,'sillä suuri kansanpaljous seurasi perässä ja huusi: "Vie pois hänet!"'),
(1696634,58,44,21,37,'Ja kun oltiin kuljettamassa Paavalia sisälle kasarmiin, sanoi hän päällikölle: "Onko minun lupa sanoa sinulle jotakin?" Niin tämä sanoi: "Osaatko sinä siis kreikkaa?'),
(1696635,58,44,21,38,'Etkö sitten olekaan se egyptiläinen, joka hiljakkoin villitsi ne neljätuhatta murhamiestä ja vei heidät erämaahan?"'),
(1696636,58,44,21,39,'Niin Paavali sanoi: "Minä olen juutalainen mies, Tarson, tunnetun Kilikian kaupungin, kansalainen; pyydän sinua, salli minun puhua kansalle".'),
(1696637,58,44,21,40,'Ja kun hän sen salli, niin Paavali, seisoen portailla, viittasi kädellään kansalle; ja kun oli syntynyt syvä hiljaisuus, puhui hän heille hebreankielellä ja sanoi:'),
(1696638,58,44,22,1,'"Miehet, veljet ja isät, kuulkaa, mitä minä nyt teille puolustuksekseni puhun".'),
(1696639,58,44,22,2,'Kun he kuulivat hänen puhuvan heille hebreankielellä, syntyi vielä suurempi hiljaisuus. Ja hän sanoi:'),
(1696640,58,44,22,3,'"Minä olen juutalainen, syntynyt Kilikian Tarsossa, mutta kasvatettu tässä kaupungissa ja Gamalielin jalkojen juuressa opetettu tarkkaan noudattamaan isien lakia; ja minä kiivailin Jumalan puolesta, niinkuin te kaikki tänä päivänä kiivailette.'),
(1696641,58,44,22,4,'Ja minä vainosin tätä tietä aina kuolemaan asti, sitoen ja heittäen vankeuteen sekä miehiä että naisia,'),
(1696642,58,44,22,5,'niinkuin myös ylimmäinen pappi voi minusta todistaa, ja kaikki vanhimmat. Minä sain heiltä myös kirjeitä veljille Damaskoon, ja minä matkustin sinne tuodakseni nekin, jotka siellä olivat, sidottuina Jerusalemiin rangaistaviksi.'),
(1696643,58,44,22,6,'Niin tapahtui, kun minä matkalla ollessani lähestyin Damaskoa, että keskipäivän aikaan yhtäkkiä taivaasta leimahti suuri valo minun ympärilläni;'),
(1696644,58,44,22,7,'ja minä kaaduin maahan ja kuulin äänen sanovan minulle: ''Saul, Saul, miksi vainoat minua?'''),
(1696645,58,44,22,8,'Niin minä vastasin: ''Kuka olet, herra?'' Ja hän sanoi minulle: ''Minä olen Jeesus Nasaretilainen, jota sinä vainoat''.'),
(1696646,58,44,22,9,'Ja minun seuralaiseni näkivät kyllä valon, mutta eivät kuulleet sen ääntä, joka minulle puhui.'),
(1696647,58,44,22,10,'Ja minä sanoin: ''Herra, mitä minun pitää tekemän?'' Herra sanoi minulle: ''Nouse ja mene Damaskoon, niin siellä sinulle sanotaan kaikki, mikä sinulle on tehtäväksi asetettu''.'),
(1696648,58,44,22,11,'Ja kun minä sen valon kirkkaudesta tulin näkemättömäksi, taluttivat seuralaiseni minua kädestä, ja niin minä tulin Damaskoon.'),
(1696649,58,44,22,12,'Ja eräs mies, hurskas lain mukaan, nimeltä Ananias, josta kaikki siellä asuvat juutalaiset todistivat hyvää,'),
(1696650,58,44,22,13,'tuli minun tyköni, astui eteeni ja sanoi minulle: ''Saul, veljeni, saa näkösi jälleen''. Ja sillä hetkellä minä sain näköni ja katsoin häneen.'),
(1696651,58,44,22,14,'Niin hän sanoi: ''Meidän isiemme Jumala on valinnut sinut tuntemaan hänen tahtonsa ja näkemään Vanhurskaan ja kuulemaan hänen suunsa äänen;'),
(1696652,58,44,22,15,'sillä sinä olet oleva hänen todistajansa kaikkien ihmisten edessä, sen todistaja, mitä olet nähnyt ja kuullut.'),
(1696653,58,44,22,16,'Ja nyt, mitä viivyttelet? Nouse, huuda avuksi hänen nimeänsä ja anna kastaa itsesi ja pestä pois syntisi.'''),
(1696654,58,44,22,17,'Kun olin palannut Jerusalemiin, tapahtui minun rukoillessani pyhäkössä, että minä jouduin hurmoksiin'),
(1696655,58,44,22,18,'ja näin hänet. Ja hän sanoi minulle: ''Riennä ja lähde pian pois Jerusalemista, sillä he eivät ota vastaan sinun todistustasi minusta''.'),
(1696656,58,44,22,19,'Ja minä sanoin: ''Herra, he tietävät itse, että minä panin vankeuteen ja ruoskitin jokaisessa synagoogassa niitä, jotka uskoivat sinuun.'),
(1696657,58,44,22,20,'Ja kun Stefanuksen, sinun todistajasi, veri vuodatettiin, olin minäkin läsnä, hyväksyin sen ja vartioin hänen surmaajainsa vaatteita.'''),
(1696658,58,44,22,21,'Ja hän sanoi minulle: ''Mene, sillä minä lähetän sinut kauas pakanain tykö''."'),
(1696659,58,44,22,22,'Tähän sanaan asti he kuuntelivat häntä; mutta silloin he korottivat äänensä ja sanoivat: "Pois maan päältä tuommoinen! Sillä ei hän saa elää."'),
(1696660,58,44,22,23,'Ja kun he huusivat ja heittelivät vaatteitaan ja viskoivat tomua ilmaan,'),
(1696661,58,44,22,24,'käski päällikkö viedä hänet kasarmiin, ja saadakseen tietää, mistä syystä he niin hänelle huusivat, hän määräsi hänet ruoskimalla tutkittavaksi.'),
(1696662,58,44,22,25,'Mutta kun he olivat oikaisseet hänet ruoskittavaksi, sanoi Paavali siinä seisovalle sadanpäämiehelle: "Onko teidän lupa ruoskia Rooman kansalaista, vieläpä ilman tuomiota?"'),
(1696663,58,44,22,26,'Kun sadanpäämies sen kuuli, meni hän päällikölle ilmoittamaan ja sanoi: "Mitä aiot tehdä? Tämä mies on Rooman kansalainen."'),
(1696664,58,44,22,27,'Niin päällikkö meni Paavalin luo ja sanoi hänelle: "Sano minulle: oletko sinä Rooman kansalainen?" Hän vastasi: "Olen".'),
(1696665,58,44,22,28,'Niin päällikkö sanoi: "Minä olen paljolla rahalla hankkinut itselleni tämän kansalaisoikeuden". Paavali sanoi: "Mutta minulla se on syntymästäni asti".'),
(1696666,58,44,22,29,'Silloin ne, joiden piti häntä tutkia, lähtivät heti hänen luotaan. Ja myös päällikkö peljästyi saatuaan tietää, että Paavali oli Rooman kansalainen, kun oli sidottanut hänet.'),
(1696667,58,44,22,30,'Mutta seuraavana päivänä, koska hän tahtoi saada varman tiedon, mistä juutalaiset häntä syyttivät, päästi hän hänet siteistä ja käski ylipappien ja koko neuvoston kokoontua, vei Paavalin alas ja asetti hänet heidän eteensä.'),
(1696668,58,44,23,1,'Niin Paavali loi katseensa neuvostoon ja sanoi: "Miehet, veljet, minä olen kaikessa hyvällä omallatunnolla vaeltanut Jumalan edessä tähän päivään asti".'),
(1696669,58,44,23,2,'Mutta ylimmäinen pappi Ananias käski lähellä seisovia lyömään häntä vasten suuta.'),
(1696670,58,44,23,3,'Silloin Paavali sanoi hänelle: "Jumala on lyövä sinua, sinä valkeaksi kalkittu seinä; istutko sinä tuomitsemassa minua lain mukaan ja käsket vastoin lakia lyödä minua?"'),
(1696671,58,44,23,4,'Niin ne, jotka seisoivat lähellä, sanoivat: "Herjaatko sinä Jumalan ylimmäistä pappia?"'),
(1696672,58,44,23,5,'Ja Paavali sanoi: "En tiennyt, veljet, että hän on ylimmäinen pappi; sillä kirjoitettu on: ''Kansasi ruhtinasta älä kiroa''".'),
(1696673,58,44,23,6,'Mutta koska Paavali tiesi osan heistä olevan saddukeuksia ja toisen osan fariseuksia, huusi hän neuvoston edessä: "Miehet, veljet, minä olen fariseus, fariseusten jälkeläinen; toivon ja kuolleitten ylösnousemuksen tähden minä olen tuomittavana".'),
(1696674,58,44,23,7,'Tuskin hän oli tämän sanonut, niin nousi riita fariseusten ja saddukeusten kesken, ja kokous jakautui.'),
(1696675,58,44,23,8,'Sillä saddukeukset sanovat, ettei ylösnousemusta ole, ei enkeliä eikä henkeä, mutta fariseukset tunnustavat kumpaisetkin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696676,58,44,23,9,'Ja syntyi suuri huuto, ja muutamat kirjanoppineet fariseusten puolueesta nousivat ja väittelivät kiivaasti ja sanoivat: "Emme löydä mitään pahaa tässä miehessä; entäpä jos henki tai enkeli on hänelle puhunut?"'),
(1696677,58,44,23,10,'Ja kun riita yhä kiihtyi, pelkäsi päällikkö, että he repisivät Paavalin kappaleiksi, ja käski sotaväen tulla alas ja temmata hänet heidän keskeltään ja viedä hänet kasarmiin.'),
(1696678,58,44,23,11,'Mutta seuraavana yönä Herra seisoi Paavalin tykönä ja sanoi: "Ole turvallisella mielellä, sillä niinkuin sinä olet todistanut minusta Jerusalemissa, niin sinun pitää todistaman minusta myös Roomassa".'),
(1696679,58,44,23,12,'Mutta päivän tultua juutalaiset tekivät salaliiton ja vannoivat valan, etteivät söisi eivätkä joisi, ennenkuin olivat tappaneet Paavalin.'),
(1696680,58,44,23,13,'Ja niitä oli viidettäkymmentä miestä, jotka yhtyivät tähän valaan.'),
(1696681,58,44,23,14,'He menivät ylipappien ja vanhinten luo ja sanoivat: "Me olemme kirouksen uhalla vannoneet, ettemme mitään maista, ennenkuin olemme tappaneet Paavalin.'),
(1696682,58,44,23,15,'Pyytäkää te siis nyt yhdessä neuvoston kanssa päälliköltä, että hän toisi hänet alas teidän luoksenne, ikäänkuin aikoisitte tarkemmin tutkia hänen asiaansa. Mutta me olemme valmiit tappamaan hänet, ennenkuin hän pääsee perille."'),
(1696683,58,44,23,16,'Mutta Paavalin sisarenpoika, joka oli saanut kuulla väijytyksestä, saapui kasarmille, meni sisälle ja ilmoitti sen Paavalille.'),
(1696684,58,44,23,17,'Niin Paavali kutsui luoksensa erään sadanpäämiehen ja sanoi: "Vie tämä nuorukainen päällikön luo, sillä hänellä on jotakin hänelle ilmoitettavaa".'),
(1696685,58,44,23,18,'Niin hän otti hänet mukaansa, vei hänet päällikön luo ja sanoi: "Vanki Paavali kutsui minut luokseen ja pyysi tuomaan sinun luoksesi tämän nuorukaisen, jolla on jotakin puhuttavaa sinulle".'),
(1696686,58,44,23,19,'Niin päällikkö tarttui hänen käteensä, vei hänet erikseen ja kysyi: "Mitä sinulla on minulle ilmoitettavaa?"'),
(1696687,58,44,23,20,'Hän sanoi: "Juutalaiset ovat päättäneet anoa sinulta, että huomenna veisit Paavalin alas neuvostoon, ikäänkuin aikoisit vielä tarkemmin tutkia hänen asiaansa.'),
(1696688,58,44,23,21,'Mutta älä sinä siihen suostu, sillä viidettäkymmentä miestä heidän joukostaan on häntä väijymässä, ja he ovat vannoneet valan, etteivät syö eivätkä juo, ennenkuin ovat tappaneet hänet. Ja nyt he ovat valmiina ja odottavat sinun suostumustasi."'),
(1696689,58,44,23,22,'Niin päällikkö päästi nuorukaisen menemään ja sanoi hänelle: "Älä virka kenellekään, että olet ilmaissut tämän minulle".'),
(1696690,58,44,23,23,'Sitten hän kutsui luoksensa kaksi sadanpäämiestä ja sanoi heille: "Pitäkää yön kolmannesta hetkestä lähtien kaksisataa sotamiestä valmiina lähtemään Kesareaan ja seitsemänkymmentä ratsumiestä ja kaksisataa keihäsmiestä,'),
(1696691,58,44,23,24,'ja varatkaa ratsuja pannaksenne Paavalin ratsaille ja viedäksenne hänet vahingoittumatonna maaherra Feeliksin luo".'),
(1696692,58,44,23,25,'Ja hän kirjoitti kirjeen, joka kuului näin:'),
(1696693,58,44,23,26,'"Klaudius Lysias lausuu tervehdyksen korkea-arvoiselle maaherralle Feeliksille.'),
(1696694,58,44,23,27,'Tämän miehen ottivat juutalaiset kiinni ja olivat vähällä hänet tappaa; silloin minä tulin saapuville sotaväen kanssa ja pelastin hänet, saatuani tietää, että hän on Rooman kansalainen.'),
(1696695,58,44,23,28,'Ja koska tahdoin tietää, mistä asiasta he häntä syyttivät, vein hänet heidän neuvostoonsa'),
(1696696,58,44,23,29,'ja havaitsin, että häntä syytettiin heidän lakiaan koskevista riitakysymyksistä, mutta ettei ollut kannetta mistään, mikä ansaitsisi kuoleman tai kahleet.'),
(1696697,58,44,23,30,'Mutta kun minulle on annettu ilmi, että miestä vastaan on tekeillä salahanke, lähetän hänet nyt heti sinun luoksesi; olen myös kehoittanut hänen syyttäjiään sanomaan sanottavansa häntä vastaan sinun edessäsi."'),
(1696698,58,44,23,31,'Niin sotamiehet, saamansa käskyn mukaan, ottivat Paavalin ja veivät hänet yötä myöten Antipatrikseen.'),
(1696699,58,44,23,32,'Seuraavana päivänä he antoivat ratsumiesten jatkaa hänen kanssaan matkaa, mutta itse he palasivat kasarmiin.'),
(1696700,58,44,23,33,'Kun ratsumiehet tulivat Kesareaan, antoivat he kirjeen maaherralle ja veivät myös Paavalin hänen eteensä.'),
(1696701,58,44,23,34,'Luettuaan kirjeen hän kysyi, mistä maakunnasta Paavali oli; ja saatuaan tietää, että hän oli Kilikiasta,'),
(1696702,58,44,23,35,'hän sanoi: "Minä kuulustelen sinua, kun syyttäjäsikin saapuvat". Ja hän käski vartioida häntä Herodeksen linnassa.'),
(1696703,58,44,24,1,'Viiden päivän kuluttua ylimmäinen pappi Ananias meni sinne alas muutamien vanhinten ja erään asianajajan, Tertulluksen, kanssa, ja he ilmoittivat maaherralle syyttävänsä Paavalia.'),
(1696704,58,44,24,2,'Ja kun Paavali oli kutsuttu esille, rupesi Tertullus syyttämään ja sanoi:'),
(1696705,58,44,24,3,'"Runsasta rauhaa me olemme sinun kauttasi, korkea-arvoinen Feeliks, saaneet nauttia, ja sinun huolenpidostasi on parannuksia aikaansaatu tämän kansan hyväksi, sen me kaikin puolin ja kaikkialla ja kaikella kiitollisuudella tunnustamme.'),
(1696706,58,44,24,4,'Mutta etten aivan kauan sinua viivyttäisi, pyydän sinua hetkisen meitä suosiollisesti kuulemaan.'),
(1696707,58,44,24,5,'Me olemme havainneet, että tämä mies on ruttotauti ja metelinnostaja kaikkien koko maailman juutalaisten keskuudessa ja nasaretilaisten lahkon päämies,'),
(1696708,58,44,24,6,'ja hän on koettanut pyhäkönkin saastuttaa. Sentähden me otimme hänet kiinni.'),
(1696709,58,44,24,8,'Voit itse häntä tutkimalla saada tietää kaiken, mistä me häntä syytämme."'),
(1696710,58,44,24,9,'Ja myös juutalaiset yhtyivät syyttämään häntä ja väittivät asian niin olevan.'),
(1696711,58,44,24,10,'Paavali vastasi, kun maaherra oli viitannut, että hän sai puhua: "Koska tiedän sinun monta vuotta olleen tämän kansan tuomarina, puhun luottamuksella asiani puolesta.'),
(1696712,58,44,24,11,'Niinkuin voit saada tietää, ei ole kuin kaksitoista päivää siitä, kun menin Jerusalemiin rukoilemaan.'),
(1696713,58,44,24,12,'Eivät he ole tavanneet minua kenenkään kanssa väittelemästä eikä väentungoksia aikaansaamasta, ei pyhäkössä, ei synagoogissa eikä kaupungilla,'),
(1696714,58,44,24,13,'eivätkä myöskään voi näyttää sinulle toteen sitä, mistä he nyt minua syyttävät.'),
(1696715,58,44,24,14,'Mutta sen minä sinulle tunnustan, että minä sitä tietä vaeltaen, jota he lahkoksi sanovat, niin palvelen isieni Jumalaa, että minä uskon kaiken, mitä on kirjoitettuna laissa ja profeetoissa,'),
(1696716,58,44,24,15,'ja pidän sen toivon Jumalaan, että on oleva ylösnousemus, jota nämä itsekin odottavat, sekä vanhurskasten että vääräin.'),
(1696717,58,44,24,16,'Sentähden minä myös ahkeroitsen, että minulla aina olisi loukkaamaton omatunto Jumalan ja ihmisten edessä.'),
(1696718,58,44,24,17,'Niin minä nyt useampien vuosien kuluttua tulin tuomaan almuja kansalleni ja toimittamaan uhreja.'),
(1696719,58,44,24,18,'Näitä toimittaessani muutamat Aasiasta tulleet juutalaiset tapasivat minut puhdistautuneena pyhäkössä, eikä ollut mitään väentungosta tai meteliä;'),
(1696720,58,44,24,19,'heidän tulisi nyt olla saapuvilla sinun edessäsi ja syyttää, jos heillä olisi jotakin minua vastaan.'),
(1696721,58,44,24,20,'Tai sanokoot nämä läsnäolevat, mitä rikollista he minussa huomasivat, kun minä seisoin neuvoston edessä;'),
(1696722,58,44,24,21,'jollei siksi luettane tätä ainoata lausetta, jonka huusin seisoessani heidän keskellään: ''Kuolleitten ylösnousemuksen tähden minä tänään olen teidän tuomittavananne''."'),
(1696723,58,44,24,22,'Mutta Feeliks, jolla oli hyvin tarkka tieto tästä tiestä, lykkäsi heidän asiansa toistaiseksi, sanoen: "Kun päällikkö Lysias tulee tänne, tutkin minä teidän asianne".'),
(1696724,58,44,24,23,'Ja hän käski sadanpäämiehen pitää Paavalia vartioituna, mutta lievässä vankeudessa, estämättä ketään hänen omaisistaan tekemästä hänelle palvelusta.'),
(1696725,58,44,24,24,'Muutamien päivien kuluttua Feeliks tuli vaimonsa Drusillan kanssa, joka oli juutalainen, haetti Paavalin ja kuunteli hänen puhettaan uskosta Kristukseen Jeesukseen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696726,58,44,24,25,'Mutta kun Paavali puhui vanhurskaudesta ja itsensähillitsemisestä ja tulevasta tuomiosta, peljästyi Feeliks ja sanoi: "Mene tällä haavaa pois, mutta kun minulle sopii, kutsutan sinut taas".'),
(1696727,58,44,24,26,'Sen ohessa hän myös toivoi saavansa Paavalilta rahaa, jonka tähden hän useita kertoja haetti hänet luokseen ja puheli hänen kanssansa.'),
(1696728,58,44,24,27,'Mutta kahden vuoden kuluttua Porkius Festus tuli Feeliksin sijaan; ja kun Feeliks tavoitteli juutalaisten suosiota, jätti hän Paavalin kahleisiin.'),
(1696729,58,44,25,1,'Kun nyt Festus oli astunut maaherranvirkaan, meni hän kolmen päivän kuluttua Kesareasta ylös Jerusalemiin.'),
(1696730,58,44,25,2,'Niin ylipapit ja juutalaisten ensimmäiset miehet ilmoittivat hänelle syyttävänsä Paavalia ja pyysivät häneltä'),
(1696731,58,44,25,3,'ja anoivat sitä suosionosoitusta itsellensä, Paavalia vastaan, että hän haettaisi hänet Jerusalemiin; sillä he valmistivat väijytystä tappaakseen hänet tiellä.'),
(1696732,58,44,25,4,'Mutta Festus vastasi, että Paavalia pidettiin vartioituna Kesareassa ja että hän itse aikoi piakkoin lähteä sinne.'),
(1696733,58,44,25,5,'Ja hän lisäsi: "Tulkoot siis teidän johtomiehenne minun mukanani sinne alas, ja jos siinä miehessä on jotakin väärää, syyttäkööt häntä".'),
(1696734,58,44,25,6,'Ja viivyttyään heidän luonansa ainoastaan kahdeksan tai kymmenen päivää hän meni alas Kesareaan. Seuraavana päivänä hän istui tuomarinistuimelle ja käski tuoda Paavalin eteensä.'),
(1696735,58,44,25,7,'Ja kun hän oli saapunut, asettuivat ne juutalaiset, jotka olivat tulleet Jerusalemista, hänen ympärilleen ja tekivät useita ja raskaita syytöksiä, joita he eivät kuitenkaan kyenneet näyttämään toteen;'),
(1696736,58,44,25,8,'sillä Paavali torjui syytökset ja sanoi: "Minä en ole mitään rikkonut juutalaisten lakia enkä pyhäkköä enkä keisaria vastaan".'),
(1696737,58,44,25,9,'Niin Festus, joka tavoitteli juutalaisten suosiota, vastasi Paavalille ja sanoi: "Tahdotko lähteä Jerusalemiin ja siellä vastata näihin syytöksiin minun edessäni?"'),
(1696738,58,44,25,10,'Mutta Paavali sanoi: "Minä seison keisarin tuomioistuimen edessä, ja sen edessä minut tuomittakoon. Juutalaisia vastaan en ole mitään rikkonut, niinkuin sinäkin aivan hyvin tiedät.'),
(1696739,58,44,25,11,'Vaan jos muuten olen rikkonut ja tehnyt jotakin, mikä ansaitsee kuoleman, en pyri pääsemään kuolemasta; mutta jos se, mistä nämä minua syyttävät, on perätöntä, niin ei kukaan voi luovuttaa minua heille. Minä vetoan keisariin."'),
(1696740,58,44,25,12,'Silloin Festus, neuvoteltuaan neuvoskuntansa kanssa, vastasi: "Keisariin sinä olet vedonnut, niinpä mene keisarin eteen".'),
(1696741,58,44,25,13,'Muutamien päivien kuluttua kuningas Agrippa ja Bernike saapuivat Kesareaan tervehtimään Festusta.'),
(1696742,58,44,25,14,'Ja kun he viipyivät siellä useampia päiviä, kertoi Festus Paavalin asian kuninkaalle ja sanoi: "Täällä on eräs mies, jonka Feeliks on jättänyt vankeuteen;'),
(1696743,58,44,25,15,'käydessäni Jerusalemissa juutalaisten ylipapit ja vanhimmat ilmoittivat syyttävänsä häntä ja pyysivät, että hänet tuomittaisiin.'),
(1696744,58,44,25,16,'Mutta minä vastasin heille: ''Ei ole roomalaisten tapa antaa ketään alttiiksi, ennenkuin syytetty on asetettu vastakkain syyttäjäinsä kanssa ja on saanut puolustautua syytöstä vastaan''.'),
(1696745,58,44,25,17,'Kun he olivat kokoontuneet tänne, niin minä viivyttelemättä seuraavana päivänä istuin tuomarinistuimelle ja käskin tuoda miehen eteeni.'),
(1696746,58,44,25,18,'Mutta kun hänen syyttäjänsä seisoivat hänen ympärillään, eivät he syyttäneet häntä mistään sellaisesta rikoksesta, kuin minä olin odottanut,'),
(1696747,58,44,25,19,'vaan heillä oli häntä vastaan riitaa joistakin heidän uskonasioistaan ja jostakin Jeesuksesta, joka oli kuollut, mutta jonka Paavali väitti elävän.'),
(1696748,58,44,25,20,'Ja kun olin epätietoinen, miten tällainen asia oli tutkittava, kysyin, tahtoiko hän mennä Jerusalemiin ja siellä vastata näihin syytöksiin.'),
(1696749,58,44,25,21,'Mutta kun Paavali vetosi ja vaati, että hänet oli säilytettävä majesteetin tutkittavaksi, käskin minä vartioida häntä, kunnes lähetän hänet keisarin eteen."'),
(1696750,58,44,25,22,'Niin Agrippa sanoi Festukselle: "Minäkin tahtoisin kuulla sitä miestä". Tämä sanoi: "Huomenna saat kuulla häntä".'),
(1696751,58,44,25,23,'Seuraavana päivänä Agrippa ja Bernike tulivat suurella komeudella ja menivät oikeussaliin päällikköjen ja kaupungin ylhäisten miesten kanssa; ja Paavali tuotiin Festuksen käskystä sinne.'),
(1696752,58,44,25,24,'Ja Festus sanoi: "Kuningas Agrippa ja kaikki muut, jotka meidän kanssamme olette läsnä, tässä näette sen miehen, jonka tähden koko juutalaisten joukko sekä Jerusalemissa että täällä on ahdistanut minua huutaen, ettei hänen pidä enää saaman elää.'),
(1696753,58,44,25,25,'Minä kuitenkin huomasin, ettei hän ole tehnyt mitään, mikä ansaitsisi kuoleman; mutta kun hän itse vetosi majesteettiin, niin minä päätin lähettää hänet sinne.'),
(1696754,58,44,25,26,'Mitään varmaa minulla ei kuitenkaan ole, mitä hänestä herralleni kirjoittaisin. Sen vuoksi tuotin hänet teidän eteenne ja varsinkin sinun eteesi, kuningas Agrippa, että minulla tutkinnon tapahduttua olisi, mitä kirjoittaa.'),
(1696755,58,44,25,27,'Sillä mielettömältä näyttää minusta lähettää vanki, antamatta samalla tietää häntä vastaan tehtyjä syytöksiä."'),
(1696756,58,44,26,1,'Niin Agrippa sanoi Paavalille: "Sinun on lupa puhua puolestasi". Silloin Paavali ojensi kätensä ja lausui puolustuksekseen:'),
(1696757,58,44,26,2,'"Pidän itseäni onnellisena, kuningas Agrippa, kun sinun edessäsi tänä päivänä saan puolustautua kaikesta siitä, mistä juutalaiset minua syyttävät,'),
(1696758,58,44,26,3,'olletikin, koska sinä tarkkaan tunnet kaikki juutalaisten tavat ja riitakysymykset. Sentähden pyydän sinua kärsivällisesti minua kuulemaan.'),
(1696759,58,44,26,4,'Kaikki juutalaiset tuntevat minun elämäni nuoruudestani asti, koska alusta alkaen olen elänyt kansani keskuudessa ja Jerusalemissa.'),
(1696760,58,44,26,5,'He tuntevat minut jo entuudestaan, jos tahtovat sen todistaa, että minä meidän uskontomme ankarimman lahkon mukaan olen elänyt fariseuksena.'),
(1696761,58,44,26,6,'Ja nyt minä seison oikeuden edessä sentähden, että panen toivoni siihen lupaukseen, jonka Jumala on meidän isillemme antanut'),
(1696762,58,44,26,7,'ja jonka meidän kaksitoista sukukuntaamme, yötä ja päivää herkeämättä palvellen Jumalaa, toivovat heille toteutuvan; tämän toivon tähden, kuningas, juutalaiset minua syyttävät.'),
(1696763,58,44,26,8,'Miksi on teistä uskomatonta, että Jumala herättää kuolleet?'),
(1696764,58,44,26,9,'Luulin minäkin, että minun tuli paljon taistella Jeesuksen, Nasaretilaisen, nimeä vastaan,'),
(1696765,58,44,26,10,'ja niin minä teinkin Jerusalemissa. Paljon pyhiä minä suljin vankiloihin, saatuani ylipapeilta siihen valtuuden, ja kun heitä tapettiin, annoin minä ääneni sen puolesta.'),
(1696766,58,44,26,11,'Ja kaikkialla synagoogissa minä usein koetin rankaisemalla pakottaa heitä herjaamaan Jeesusta, ja menin niin pitkälle vimmassani heitä vastaan, että vainosin heitä aina ulkomaan kaupunkeihin saakka.'),
(1696767,58,44,26,12,'Kun näissä asioissa matkustin Damaskoon ylipappien valtuudella ja suostumuksella,'),
(1696768,58,44,26,13,'näin minä, oi kuningas, tiellä keskellä päivää taivaasta valon, auringon paistetta kirkkaamman, leimahtavan minun ja matkatoverieni ympärillä,'),
(1696769,58,44,26,14,'ja me kaaduimme kaikki maahan, ja minä kuulin äänen sanovan minulle hebreankielellä: ''Saul, Saul, miksi vainoat minua? Työläs on sinun potkia tutkainta vastaan.'''),
(1696770,58,44,26,15,'Niin minä sanoin: ''Kuka olet, herra?'' Ja Herra sanoi: ''Minä olen Jeesus, jota sinä vainoat.'),
(1696771,58,44,26,16,'Mutta nouse ja seiso jaloillasi; sillä sitä varten minä olen sinulle ilmestynyt, että asettaisin sinut palvelijakseni ja sen todistajaksi, mitä varten sinä olet minut nähnyt, niin myös sen, mitä varten minä sinulle vastedes ilmestyn.'),
(1696772,58,44,26,17,'Ja minä pelastan sinut sekä oman kansasi että pakanain käsistä, joitten tykö minä sinut lähetän'),
(1696773,58,44,26,18,'avaamaan heidän silmänsä, että he kääntyisivät pimeydestä valkeuteen ja saatanan vallasta Jumalan tykö ja saisivat uskomalla minuun synnit anteeksi ja perintöosan pyhitettyjen joukossa.'''),
(1696774,58,44,26,19,'Sentähden, kuningas Agrippa, minä en voinut olla tottelematta taivaallista näkyä,'),
(1696775,58,44,26,20,'vaan saarnasin ensin sekä Damaskon että Jerusalemin asukkaille, ja sitten koko Juudean maalle ja pakanoille parannusta ja kääntymystä Jumalan puoleen, ja että he tekisivät parannuksen soveliaita tekoja.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696776,58,44,26,21,'Tämän tähden juutalaiset ottivat minut kiinni pyhäkössä ja yrittivät surmata minut.'),
(1696777,58,44,26,22,'Mutta Jumalan avulla, jota olen saanut tähän päivään asti, minä seison ja todistan sekä pienille että suurille, enkä puhu mitään muuta, kuin minkä profeetat ja Mooses ovat sanoneet tulevan tapahtumaan,'),
(1696778,58,44,26,23,'että nimittäin Kristuksen piti kärsimän ja kuolleitten ylösnousemuksen esikoisena julistaman valkeutta sekä tälle kansalle että pakanoille."'),
(1696779,58,44,26,24,'Mutta kun hän näin puolustautui, sanoi Festus suurella äänellä: "Sinä olet hullu, Paavali, suuri oppi hulluttaa sinut".'),
(1696780,58,44,26,25,'Mutta Paavali sanoi: "En ole hullu, korkea-arvoinen Festus, vaan puhun totuuden ja toimen sanoja.'),
(1696781,58,44,26,26,'Kuningas kyllä nämä tietää, jonka tähden minä puhunkin hänelle rohkeasti. Sillä minä en usko minkään näistä asioista olevan häneltä salassa; eiväthän nämä ole missään syrjäsopessa tapahtuneet.'),
(1696782,58,44,26,27,'Uskotko, kuningas Agrippa, profeettoja? Minä tiedän, että uskot."'),
(1696783,58,44,26,28,'Niin Agrippa sanoi Paavalille: "Vähälläpä luulet taivuttavasi minut kristityksi".'),
(1696784,58,44,26,29,'Mutta Paavali sanoi: "Toivoisin Jumalalta, että, olipa vähällä tai paljolla, et ainoastaan sinä, vaan myös kaikki te, jotka minua tänään kuulette, tulisitte semmoisiksi, kuin minä olen, näitä kahleita lukuunottamatta".'),
(1696785,58,44,26,30,'Niin kuningas nousi ja maaherra ja Bernike sekä ne, jotka istuivat heidän kanssansa.'),
(1696786,58,44,26,31,'Ja mennessään he puhuivat keskenänsä sanoen: "Tämä mies ei ole tehnyt mitään, mikä ansaitsisi kuoleman tai kahleet".'),
(1696787,58,44,26,32,'Ja Agrippa sanoi Festukselle: "Tämän miehen olisi voinut päästää irti, jos hän ei olisi vedonnut keisariin".'),
(1696788,58,44,27,1,'Kun oli päätetty, että meidän oli purjehtiminen Italiaan, annettiin Paavali ja muutamat muut vangit erään Julius nimisen, keisarilliseen sotaväenosastoon kuuluvan sadanpäämiehen haltuun.'),
(1696789,58,44,27,2,'Ja me astuimme adramyttiläiseen laivaan, jonka oli määrä purjehtia Aasian rannikkopaikkoihin, ja lähdimme merelle, ja seurassamme oli Aristarkus, makedonialainen Tessalonikasta.'),
(1696790,58,44,27,3,'Seuraavana päivänä laskimme Siidoniin. Ja Julius kohteli Paavalia ystävällisesti ja salli hänen mennä ystäviensä luo hoitoa saamaan.'),
(1696791,58,44,27,4,'Ja sieltä laskettuamme merelle purjehdimme Kypron suojaan, koska tuulet olivat vastaiset.'),
(1696792,58,44,27,5,'Ja kun olimme merta purjehtien sivuuttaneet Kilikian ja Pamfylian, tulimme Myrraan, joka on Lykiassa.'),
(1696793,58,44,27,6,'Siellä sadanpäämies tapasi aleksandrialaisen laivan, jonka oli määrä purjehtia Italiaan, ja siirsi meidät siihen.'),
(1696794,58,44,27,7,'Ja monta päivää me purjehdimme hitaasti ja pääsimme vaivoin Knidon kohdalle. Ja kun tuulelta emme päässeet sinne, purjehdimme Salmonen nenitse Kreetan suojaan.'),
(1696795,58,44,27,8,'Ja vaivoin kuljettuamme liki sen rantaa saavuimme erääseen paikkaan, jonka nimi oli Kauniit Satamat ja jonka lähellä Lasaian kaupunki oli.'),
(1696796,58,44,27,9,'Mutta kun paljon aikaa oli kulunut ja purjehtiminen jo oli vaarallista, sillä paastonaikakin oli jo ohi, varoitti Paavali heitä'),
(1696797,58,44,27,10,'ja sanoi: "Miehet, minä näen, että purjehtiminen käy vaivalloiseksi ja vaaralliseksi, ei ainoastaan lastille ja laivalle, vaan myös meidän hengellemme".'),
(1696798,58,44,27,11,'Mutta sadanpäämies uskoi enemmän perämiestä ja laivanisäntää kuin Paavalin sanoja.'),
(1696799,58,44,27,12,'Ja koska satama oli sopimaton talvehtimiseen, olivat useimmat sitä mieltä, että heidän oli sieltä lähdettävä, voidakseen ehkä päästä talvehtimaan Foiniksiin, erääseen Kreetan satamaan, joka antaa lounaaseen ja luoteeseen päin.'),
(1696800,58,44,27,13,'Ja kun etelätuuli alkoi puhaltaa, luulivat he pääsevänsä tarkoituksensa perille, nostivat ankkurin ja kulkivat aivan likitse Kreetaa.'),
(1696801,58,44,27,14,'Mutta ennen pitkää syöksyi saaren päällitse raju tuuli, niin sanottu koillismyrsky.'),
(1696802,58,44,27,15,'Kun laiva ryöstäytyi sen mukaan eikä voinut nousta tuuleen, jätimme sen valtoihinsa ja jouduimme tuuliajolle.'),
(1696803,58,44,27,16,'Ja päästyämme erään pienen, Klauda nimisen saaren suojaan me töintuskin saimme venheen korjuuseen.'),
(1696804,58,44,27,17,'Vedettyään sen ylös he ryhtyivät varokeinoihin ja sitoivat laivan ympäri köysiä, ja kun pelkäsivät ajautuvansa Syrtteihin, laskivat he purjeet alas, ja niin he ajelehtivat.'),
(1696805,58,44,27,18,'Mutta kun rajuilma ankarasti ahdisti meitä, heittivät he seuraavana päivänä lastia mereen,'),
(1696806,58,44,27,19,'ja kolmantena päivänä he omin käsin viskasivat mereen laivan kaluston.'),
(1696807,58,44,27,20,'Mutta kun ei aurinkoa eikä tähtiä näkynyt moneen päivään ja kova myrsky painoi, katosi meiltä viimein kaikki pelastumisen toivo.'),
(1696808,58,44,27,21,'Kun oli oltu kauan syömättä, niin Paavali nousi heidän keskellään ja sanoi: "Miehet, teidän olisi pitänyt noudattaa minun neuvoani eikä lähteä Kreetasta; siten olisitte säästyneet tästä vaivasta ja vahingosta.'),
(1696809,58,44,27,22,'Mutta nyt minä kehoitan teitä olemaan rohkealla mielellä, sillä ei yksikään teistä huku, ainoastaan laiva hukkuu.'),
(1696810,58,44,27,23,'Sillä tänä yönä seisoi minun tykönäni sen Jumalan enkeli, jonka oma minä olen ja jota minä myös palvelen,'),
(1696811,58,44,27,24,'ja sanoi: ''Älä pelkää, Paavali, keisarin eteen sinun pitää menemän; ja katso, Jumala on lahjoittanut sinulle kaikki, jotka sinun kanssasi purjehtivat''.'),
(1696812,58,44,27,25,'Olkaa sentähden rohkealla mielellä, miehet; sillä minulla on se usko Jumalaan, että niin käy, kuin minulle on puhuttu.'),
(1696813,58,44,27,26,'Mutta jollekin saarelle meidän täytyy viskautua."'),
(1696814,58,44,27,27,'Ja kun tuli neljästoista yö meidän ajelehtiessamme Adrianmerellä, tuntui merimiehistä keskiyön aikaan, että lähestyttiin jotakin maata.'),
(1696815,58,44,27,28,'Ja luodattuaan he huomasivat syvyyden olevan kaksikymmentä syltä, ja vähän matkaa kuljettuaan he taas luotasivat ja huomasivat syvyyden viideksitoista syleksi.'),
(1696816,58,44,27,29,'Ja kun he pelkäsivät meidän viskautuvan karille, laskivat he laivan perästä neljä ankkuria ja odottivat ikävöiden päivän tuloa.'),
(1696817,58,44,27,30,'Mutta merimiehet yrittivät paeta laivasta ja laskivat venheen mereen sillä tekosyyllä, että muka aikoivat keulapuolesta viedä ulos ankkureita.'),
(1696818,58,44,27,31,'Silloin Paavali sanoi sadanpäämiehelle ja sotilaille: "Jos nuo eivät pysy laivassa, niin te ette voi pelastua".'),
(1696819,58,44,27,32,'Silloin sotamiehet hakkasivat poikki venheen köydet ja päästivät sen menemään.'),
(1696820,58,44,27,33,'Vähää ennen päivän tuloa Paavali kehoitti kaikkia nauttimaan ruokaa, sanoen: "Tänään olette jo neljättätoista päivää odottaneet ja olleet syömättä ettekä ole mitään ravintoa ottaneet.'),
(1696821,58,44,27,34,'Sentähden minä kehoitan teitä nauttimaan ruokaa, sillä se on tarpeen meidän pelastuaksemme; sillä ei yhdeltäkään teistä ole hiuskarvaakaan päästä katoava."'),
(1696822,58,44,27,35,'Tämän sanottuaan hän otti leivän ja kiitti Jumalaa kaikkien nähden, mursi ja rupesi syömään.'),
(1696823,58,44,27,36,'Silloin kaikki tulivat rohkealle mielelle ja ottivat hekin ruokaa.'),
(1696824,58,44,27,37,'Ja meitä oli laivassa kaikkiaan kaksisataa seitsemänkymmentä kuusi henkeä.'),
(1696825,58,44,27,38,'Ja kun he olivat tulleet ravituiksi, kevensivät he laivaa heittämällä viljan mereen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696826,58,44,27,39,'Päivän tultua he eivät tunteneet maata, mutta huomasivat lahden, jossa oli sopiva ranta; siihen he päättivät, jos mahdollista, laskea laivan.'),
(1696827,58,44,27,40,'Ja he hakkasivat ankkuriköydet poikki ja jättivät ankkurit mereen; samalla he päästivät peräsinten nuorat, nostivat keulapurjeen tuuleen ja ohjasivat rantaa kohti.'),
(1696828,58,44,27,41,'Mutta he joutuivat riutalle ja antoivat laivan törmätä siihen; keulapuoli tarttui kiinni ja jäi liikkumattomaksi, mutta peräpuoli hajosi aaltojen voimasta.'),
(1696829,58,44,27,42,'Niin sotamiehillä oli aikomus tappaa vangit, ettei kukaan pääsisi uimalla karkuun.'),
(1696830,58,44,27,43,'Mutta sadanpäämies, joka tahtoi pelastaa Paavalin, esti heidät siitä aikeesta ja käski uimataitoisten ensiksi heittäytyä veteen ja lähteä maihin'),
(1696831,58,44,27,44,'ja sitten muiden, minkä laudoilla, minkä laivankappaleilla. Ja näin kaikki pelastuivat maalle.'),
(1696832,58,44,28,1,'Kun olimme pelastuneet, niin me sitten saimme tietää, että saaren nimi oli Melite.'),
(1696833,58,44,28,2,'Ja sen asukkaat osoittivat meille suurta ystävällisyyttä: he sytyttivät nuotion ja ottivat meidät kaikki sen ääreen, kun oli ruvennut satamaan ja oli kylmä.'),
(1696834,58,44,28,3,'Mutta Paavali kokosi kasan risuja, ja kun hän pani ne nuotioon, tuli kyykäärme kuumuuden tähden esiin ja kävi kiinni hänen käteensä.'),
(1696835,58,44,28,4,'Kun asukkaat näkivät tuon elukan riippuvan kiinni hänen kädessään, sanoivat he toisilleen: "Varmaan tuo mies on murhaaja, koska kostotar ei sallinut hänen elää, vaikka hän pelastuikin merestä".'),
(1696836,58,44,28,5,'Mutta hän pudisti elukan tuleen, eikä hänelle tullut mitään vahinkoa.'),
(1696837,58,44,28,6,'Ja he odottivat hänen ajettuvan tai äkisti kaatuvan kuolleena maahan. Mutta kun he olivat kauan odottaneet ja näkivät, ettei hänelle mitään pahaa tapahtunut, muuttivat he mielensä ja sanoivat hänen olevan jumalan.'),
(1696838,58,44,28,7,'Lähellä sitä paikkaa oli saaren ensimmäisellä miehellä, jonka nimi oli Publius, maatiloja. Hän otti meidät vastaan ja piti meitä ystävällisesti kolme päivää vierainansa.'),
(1696839,58,44,28,8,'Ja Publiuksen isä makasi sairaana kuumeessa ja punataudissa; ja Paavali meni hänen luoksensa, rukoili ja pani kätensä hänen päälleen ja paransi hänet.'),
(1696840,58,44,28,9,'Kun tämä oli tapahtunut, tulivat muutkin sairaat, mitä saarella oli, ja heidät parannettiin.'),
(1696841,58,44,28,10,'He osoittivat meille myös monin tavoin kunniaa, ja lähtiessämme merelle he panivat mukaan, mitä tarvitsimme.'),
(1696842,58,44,28,11,'Kolmen kuukauden kuluttua me purjehdimme sieltä aleksandrialaisessa laivassa, joka oli talvehtinut saarella ja jolla oli merkkinä Kastorin ja Polluksin kuva.'),
(1696843,58,44,28,12,'Ja me laskimme maihin Syrakuusassa ja viivyimme siellä kolme päivää,'),
(1696844,58,44,28,13,'ja sieltä me kierrettyämme saavuimme Reegioniin, ja kun yhden päivän perästä nousi etelätuuli, tulimme seuraavana päivänä Puteoliin.'),
(1696845,58,44,28,14,'Siellä tapasimme veljiä, jotka pyysivät meitä viipymään heidän tykönänsä seitsemän päivää. Ja sitten me lähdimme Roomaan.'),
(1696846,58,44,28,15,'Ja kun veljet siellä saivat kuulla meistä, tulivat he meitä vastaan Appii Forumiin ja Tres Tabernaen kohdalle saakka; ja heidät nähdessään Paavali kiitti Jumalaa ja sai rohkeutta.'),
(1696847,58,44,28,16,'Ja kun tulimme Roomaan, sallittiin Paavalin asua erikseen häntä vartioivan sotamiehen kanssa.'),
(1696848,58,44,28,17,'Kolmen päivän kuluttua Paavali kutsui kokoon juutalaisten ensimmäiset. Ja kun he olivat kokoontuneet, sanoi hän heille: "Miehet, veljet! Vaikka en ole mitään tehnyt kansaamme tai isiemme tapoja vastaan, annettiin minut kuitenkin Jerusalemista vankina roomalaisten käsiin.'),
(1696849,58,44,28,18,'Ja kun he olivat minua tutkineet, tahtoivat he päästää minut irti, koska en ollut tehnyt mitään kuoleman rikosta.'),
(1696850,58,44,28,19,'Mutta kun juutalaiset sitä vastustivat, oli minun pakko vedota keisariin; ei kuitenkaan niin, että minulla olisi mitään kannetta kansaani vastaan.'),
(1696851,58,44,28,20,'Tästä syystä minä nyt olen kutsunut teidät, saadakseni nähdä ja puhutella teitä; sillä Israelin toivon tähden minä kannan tätä kahletta."'),
(1696852,58,44,28,21,'Niin he sanoivat hänelle: "Emme ole saaneet kirjeitä sinusta Juudean maalta, eikä kukaan tänne saapunut veli ole ilmoittanut eikä puhunut sinusta mitään pahaa.'),
(1696853,58,44,28,22,'Katsomme kuitenkin syytä olevan kuulla sinulta, mitä sinun mielessäsi on; sillä tästä lahkosta on meillä tiedossamme, että sitä vastaan kaikkialla kiistetään."'),
(1696854,58,44,28,23,'Ja he määräsivät hänelle päivän, ja silloin tuli heitä vielä useampia hänen luoksensa majapaikkaan. Ja näille hän aamuvarhaisesta iltaan saakka selitti ja todisti Jumalan valtakunnasta, lähtien Mooseksen laista ja profeetoista, saadakseen heidät vakuutetuiksi Jeesuksesta.'),
(1696855,58,44,28,24,'Niin se, mitä sanottiin, sai toiset vakuutetuiksi, mutta toiset eivät uskoneet.'),
(1696856,58,44,28,25,'Ja kun he olivat keskenään erimielisiä, erosivat he toisistaan, Paavalin sanoessa ainoastaan nämä sanat: "Oikein on Pyhä Henki puhunut profeetta Esaiaan kautta teidän isillenne,'),
(1696857,58,44,28,26,'sanoen: ''Mene tämän kansan luo ja sano: Kuulemalla kuulkaa älkääkä ymmärtäkö, näkemällä nähkää älkääkä käsittäkö.'),
(1696858,58,44,28,27,'Sillä paatunut on tämän kansan sydän, ja korvillaan he työläästi kuulevat, ja silmänsä he ovat ummistaneet, että he eivät näkisi silmillään, eivät kuulisi korvillaan, eivät ymmärtäisi sydämellään eivätkä kääntyisi ja etten minä heitä parantaisi.'''),
(1696859,58,44,28,28,'Olkoon siis teille tiettävä, että tämä Jumalan pelastussanoma on lähetetty pakanoille; ja he kuulevat sen."'),
(1696860,58,44,28,30,'Ja Paavali asui omassa vuokra-asunnossaan kaksi täyttä vuotta ja otti vastaan kaikki, jotka hänen tykönsä tulivat;'),
(1696861,58,44,28,31,'ja hän julisti Jumalan valtakuntaa ja opetti Herran Jeesuksen Kristuksen tuntemista kaikella rohkeudella, kenenkään estämättä.'),
(1696862,58,45,1,1,'Paavali, Jeesuksen Kristuksen palvelija, kutsuttu apostoli, erotettu julistamaan Jumalan evankeliumia,'),
(1696863,58,45,1,2,'jonka Jumala on edeltä luvannut profeettainsa kautta pyhissä kirjoituksissa,'),
(1696864,58,45,1,3,'hänen Pojastansa - joka lihan puolesta on syntynyt Daavidin siemenestä'),
(1696865,58,45,1,4,'ja pyhyyden hengen puolesta kuolleistanousemisen kautta asetettu Jumalan Pojaksi voimassa - Jeesuksesta Kristuksesta, meidän Herrastamme,'),
(1696866,58,45,1,5,'jonka kautta me olemme saaneet armon ja apostolinviran, että syntyisi uskon kuuliaisuus hänen nimeänsä kohtaan kaikissa pakanakansoissa,'),
(1696867,58,45,1,6,'joihin tekin, Jeesuksen Kristuksen kutsumat, kuulutte:'),
(1696868,58,45,1,7,'kaikille Roomassa oleville Jumalan rakkaille, kutsutuille pyhille. Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!'),
(1696869,58,45,1,8,'Ensiksikin minä kiitän Jumalaani Jeesuksen Kristuksen kautta teidän kaikkien tähden, koska teidän uskoanne mainitaan kaikessa maailmassa.'),
(1696870,58,45,1,9,'Sillä Jumala, jota minä hengessäni palvelen julistaen hänen Poikansa evankeliumia, on minun todistajani, kuinka minä teitä lakkaamatta muistan,'),
(1696871,58,45,1,10,'aina rukouksissani anoen, että minä jo vihdoinkin, jos Jumala tahtoo, pääsisin tulemaan teidän tykönne.'),
(1696872,58,45,1,11,'Sillä minä ikävöitsen teitä nähdä, voidakseni antaa teille jonkun hengellisen lahjan, että te vahvistuisitte,'),
(1696873,58,45,1,12,'se on, että me yhdessä ollessamme virkistyisimme yhteisestä uskostamme, teidän ja minun.'),
(1696874,58,45,1,13,'Ja minä en tahdo, veljet, teiltä salata, että jo monesti olen päättänyt tulla teidän tykönne saadakseni jonkin hedelmän teidänkin keskuudestanne, niinkuin muidenkin pakanain, mutta olen ollut estetty tähän saakka.'),
(1696875,58,45,1,14,'Kreikkalaisille ja barbaareille, viisaille ja tyhmille minä olen velassa;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696876,58,45,1,15,'omasta puolestani minä siis olen altis teillekin, Roomassa asuvaisille, julistamaan evankeliumia.'),
(1696877,58,45,1,16,'Sillä minä en häpeä evankeliumia; sillä se on Jumalan voima, itsekullekin uskovalle pelastukseksi, juutalaiselle ensin, sitten myös kreikkalaiselle.'),
(1696878,58,45,1,17,'Sillä siinä Jumalan vanhurskaus ilmestyy uskosta uskoon, niinkuin kirjoitettu on: "Vanhurskas on elävä uskosta".'),
(1696879,58,45,1,18,'Sillä Jumalan viha ilmestyy taivaasta kaikkea ihmisten jumalattomuutta ja vääryyttä vastaan, niiden, jotka pitävät totuutta vääryyden vallassa,'),
(1696880,58,45,1,19,'sentähden että se, mikä Jumalasta voidaan tietää, on ilmeistä heidän keskuudessaan; sillä Jumala on sen heille ilmoittanut.'),
(1696881,58,45,1,20,'Sillä hänen näkymätön olemuksensa, hänen iankaikkinen voimansa ja jumalallisuutensa, ovat, kun niitä hänen teoissansa tarkataan, maailman luomisesta asti nähtävinä, niin etteivät he voi millään itseänsä puolustaa,'),
(1696882,58,45,1,21,'koska he, vaikka ovat tunteneet Jumalan, eivät ole häntä Jumalana kunnioittaneet eivätkä kiittäneet, vaan ovat ajatuksiltansa turhistuneet, ja heidän ymmärtämätön sydämensä on pimentynyt.'),
(1696883,58,45,1,22,'Kehuessaan viisaita olevansa he ovat tyhmiksi tulleet'),
(1696884,58,45,1,23,'ja ovat katoamattoman Jumalan kirkkauden muuttaneet katoavaisen ihmisen ja lintujen ja nelijalkaisten ja matelevaisten kuvan kaltaiseksi.'),
(1696885,58,45,1,24,'Sentähden Jumala on heidät, heidän sydämensä himoissa, hyljännyt saastaisuuteen, häpäisemään itse omat ruumiinsa,'),
(1696886,58,45,1,25,'nuo, jotka ovat vaihtaneet Jumalan totuuden valheeseen ja kunnioittaneet ja palvelleet luotua enemmän kuin Luojaa, joka on ylistetty iankaikkisesti, amen.'),
(1696887,58,45,1,26,'Sentähden Jumala on hyljännyt heidät häpeällisiin himoihin; sillä heidän naispuolensa ovat vaihtaneet luonnollisen yhteyden luonnonvastaiseen;'),
(1696888,58,45,1,27,'samoin miespuoletkin, luopuen luonnollisesta yhteydestä naispuolen kanssa, ovat kiimoissaan syttyneet toisiinsa ja harjoittaneet, miespuolet miespuolten kanssa, riettautta ja villiintymisestään saaneet itseensä sen palkan, mikä saada piti.'),
(1696889,58,45,1,28,'Ja niinkuin heille ei kelvannut pitää kiinni Jumalan tuntemisesta, niin Jumala hylkäsi heidät heidän kelvottoman mielensä valtaan, tekemään sopimattomia.'),
(1696890,58,45,1,29,'He ovat täynnänsä kaikkea vääryyttä, pahuutta, ahneutta, häijyyttä, täynnä kateutta, murhaa, riitaa, petosta, pahanilkisyyttä;'),
(1696891,58,45,1,30,'ovat korvaankuiskuttelijoita, panettelijoita, Jumalaa vihaavaisia, väkivaltaisia, ylpeitä, kerskailijoita, pahankeksijöitä, vanhemmilleen tottelemattomia,'),
(1696892,58,45,1,31,'vailla ymmärrystä, luotettavuutta, rakkautta ja laupeutta;'),
(1696893,58,45,1,32,'jotka, vaikka tuntevat Jumalan vanhurskaan säädöksen, että ne, jotka senkaltaisia tekevät, ovat kuoleman ansainneet, eivät ainoastaan itse niitä tee, vaan vieläpä osoittavat hyväksymistä niille, jotka niitä tekevät.'),
(1696894,58,45,2,1,'Sentähden sinä, oi ihminen, et voi millään itseäsi puolustaa, olitpa kuka hyvänsä, joka tuomitset. Sillä mistä toista tuomitset, siihen sinä itsesi syypääksi tuomitset, koska sinä, joka tuomitset, teet samoja tekoja.'),
(1696895,58,45,2,2,'Ja me tiedämme, että Jumalan tuomio on totuuden mukainen niille, jotka senkaltaista tekevät.'),
(1696896,58,45,2,3,'Vai luuletko, ihminen, sinä, joka tuomitset niitä, jotka senkaltaisia tekevät, ja itse samoja teet, että sinä vältät Jumalan tuomion?'),
(1696897,58,45,2,4,'Vai halveksitko hänen hyvyytensä ja kärsivällisyytensä ja pitkämielisyytensä runsautta, etkä tiedä, että Jumalan hyvyys vetää sinua parannukseen?'),
(1696898,58,45,2,5,'Kovuudellasi ja sydämesi katumattomuudella sinä kartutat päällesi vihaa vihan ja Jumalan vanhurskaan tuomion ilmestymisen päiväksi,'),
(1696899,58,45,2,6,'hänen, "joka antaa kullekin hänen tekojensa mukaan":'),
(1696900,58,45,2,7,'niille, jotka hyvässä työssä kestävinä etsivät kirkkautta ja kunniaa ja katoamattomuutta, iankaikkisen elämän,'),
(1696901,58,45,2,8,'mutta niiden osaksi, jotka ovat itsekkäitä eivätkä tottele totuutta, vaan tottelevat vääryyttä, tulee viha ja kiivastus.'),
(1696902,58,45,2,9,'Tuska ja ahdistus jokaisen ihmisen sielulle, joka pahaa tekee, juutalaisen ensin, sitten myös kreikkalaisen;'),
(1696903,58,45,2,10,'mutta kirkkaus ja kunnia ja rauha jokaiselle, joka tekee sitä, mikä hyvä on, juutalaiselle ensin, sitten myös kreikkalaiselle!'),
(1696904,58,45,2,11,'Sillä Jumala ei katso henkilöön.'),
(1696905,58,45,2,12,'Sillä kaikki, jotka ilman lakia ovat syntiä tehneet, ne myös ilman lakia hukkuvat, ja kaikki, jotka lain alaisina ovat syntiä tehneet, ne lain mukaan tuomitaan;'),
(1696906,58,45,2,13,'sillä eivät lain kuulijat ole vanhurskaita Jumalan edessä, vaan lain noudattajat vanhurskautetaan.'),
(1696907,58,45,2,14,'Sillä kun pakanat, joilla ei lakia ole, luonnostansa tekevät, mitä laki vaatii, niin he, vaikka heillä ei lakia ole, ovat itse itsellensä laki'),
(1696908,58,45,2,15,'ja osoittavat, että lain teot ovat kirjoitetut heidän sydämiinsä, kun heidän omatuntonsa myötä-todistaa ja heidän ajatuksensa keskenään syyttävät tai myös puolustavat heitä -'),
(1696909,58,45,2,16,'sinä päivänä, jona Jumala on tuomitseva ihmisten salaisuudet Kristuksen Jeesuksen kautta, minun evankeliumini mukaan.'),
(1696910,58,45,2,17,'Mutta jos sinä kutsut itseäsi juutalaiseksi ja luotat lakiin ja Jumala on sinun kerskauksesi'),
(1696911,58,45,2,18,'ja tunnet hänen tahtonsa ja, opetettuna laissa, tutkit, mikä parasta on,'),
(1696912,58,45,2,19,'ja luulet kykeneväsi olemaan sokeain taluttaja, pimeydessä olevien valkeus,'),
(1696913,58,45,2,20,'ymmärtämättömien kasvattaja, alaikäisten opettaja, sinulla kun laissa on tiedon ja totuuden muoto:'),
(1696914,58,45,2,21,'niin sinäkö, joka toista opetat, et itseäsi opeta; joka julistat, ettei saa varastaa, itse varastat;'),
(1696915,58,45,2,22,'joka sanot, ettei saa tehdä huorin, itse teet huorin; joka kauhistut epäjumalia, kuitenkin olet temppelin ryöstäjä;'),
(1696916,58,45,2,23,'joka laista kerskaat, häväiset lainrikkomisella Jumalaa?'),
(1696917,58,45,2,24,'Sillä "teidän tähtenne Jumalan nimi tulee pilkatuksi pakanain seassa", niinkuin kirjoitettu on.'),
(1696918,58,45,2,25,'Ympärileikkaus kyllä on hyödyllinen, jos sinä lakia noudatat; mutta jos olet lainrikkoja, niin sinun ympärileikkauksesi on tullut ympärileikkaamattomuudeksi.'),
(1696919,58,45,2,26,'Jos siis ympärileikkaamaton noudattaa lain säädöksiä, eikö hänen ympärileikkaamattomuutensa ole luettava ympärileikkaukseksi?'),
(1696920,58,45,2,27,'Ja luonnostaan ympärileikkaamaton, joka täyttää lain, on tuomitseva sinut, joka lainkirjaiminesi ja ympärileikkauksinesi olet lainrikkoja.'),
(1696921,58,45,2,28,'Sillä ei se ole juutalainen, joka vain ulkonaisesti on juutalainen, eikä ympärileikkaus se, joka ulkonaisesti lihassa tapahtuu;'),
(1696922,58,45,2,29,'vaan se on juutalainen, joka sisällisesti on juutalainen, ja oikea ympärileikkaus on sydämen ympärileikkaus Hengessä, ei kirjaimessa; ja hän saa kiitoksensa, ei ihmisiltä, vaan Jumalalta.'),
(1696923,58,45,3,1,'Mitä etuuksia on siis juutalaisilla, tai mitä hyötyä ympärileikkauksesta?'),
(1696924,58,45,3,2,'Paljonkin, kaikin tavoin; ennen kaikkea se, että heille on uskottu, mitä Jumala on puhunut.'),
(1696925,58,45,3,3,'Mutta kuinka? Jos jotkut ovat olleet epäuskoisia, ei kaiketi heidän epäuskonsa ole Jumalan uskollisuutta tyhjäksi tekevä?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696926,58,45,3,4,'Pois se! Olkoon Jumala totinen, mutta jokainen ihminen valhettelija, niinkuin kirjoitettu on: "Että sinut havaittaisiin vanhurskaaksi sanoissasi ja että voittaisit, kun sinun kanssasi oikeutta käydään".'),
(1696927,58,45,3,5,'Mutta jos meidän vääryytemme tuo ilmi Jumalan vanhurskauden, mitä me siihen sanomme? Ei kaiketi Jumala ole väärä, kun hän rankaisee vihassansa? Minä puhun ihmisten tavalla.'),
(1696928,58,45,3,6,'Pois se! Sillä kuinka Jumala silloin voisi tuomita maailman?'),
(1696929,58,45,3,7,'Sillä jos Jumalan totuus tulee minun valheeni kautta selvemmin julki hänen kirkkaudekseen, miksi sitten minutkin vielä syntisenä tuomitaan?'),
(1696930,58,45,3,8,'Ja miksi emme tekisi, niinkuin herjaten syyttävät meidän tekevän ja niinkuin muutamat väittävät meidän sanovan: "Tehkäämme pahaa, että siitä hyvää tulisi"? Niiden tuomio on oikea.'),
(1696931,58,45,3,9,'Miten siis on? Olemmeko me parempia? Emme suinkaan. Mehän olemme edellä osoittaneet, että kaikki, niin hyvin juutalaiset kuin kreikkalaiset, ovat synnin alla,'),
(1696932,58,45,3,10,'niinkuin kirjoitettu on: "Ei ole ketään vanhurskasta, ei ainoatakaan,'),
(1696933,58,45,3,11,'ei ole ketään ymmärtäväistä, ei ketään, joka etsii Jumalaa;'),
(1696934,58,45,3,12,'kaikki ovat poikenneet pois, kaikki tyynni kelvottomiksi käyneet; ei ole ketään, joka tekee sitä, mikä hyvä on, ei yhden yhtäkään.'),
(1696935,58,45,3,13,'Heidän kurkkunsa on avoin hauta, kielellänsä he pettävät, kyykäärmeen myrkkyä on heidän huultensa alla;'),
(1696936,58,45,3,14,'heidän suunsa on täynnä kirousta ja katkeruutta.'),
(1696937,58,45,3,15,'Heidän jalkansa ovat nopeat vuodattamaan verta,'),
(1696938,58,45,3,16,'hävitys ja kurjuus on heidän teillänsä,'),
(1696939,58,45,3,17,'ja rauhan tietä he eivät tunne.'),
(1696940,58,45,3,18,'Ei ole Jumalan pelko heidän silmäinsä edessä."'),
(1696941,58,45,3,19,'Mutta me tiedämme, että kaiken, minkä laki sanoo, sen se puhuu lain alaisille, että jokainen suu tukittaisiin ja koko maailma tulisi syylliseksi Jumalan edessä;'),
(1696942,58,45,3,20,'sentähden, ettei mikään liha tule hänen edessään vanhurskaaksi lain teoista; sillä lain kautta tulee synnin tunto.'),
(1696943,58,45,3,21,'Mutta nyt Jumalan vanhurskaus, josta laki ja profeetat todistavat, on ilmoitettu ilman lakia,'),
(1696944,58,45,3,22,'se Jumalan vanhurskaus, joka uskon kautta Jeesukseen Kristukseen tulee kaikkiin ja kaikille, jotka uskovat; sillä ei ole yhtään erotusta.'),
(1696945,58,45,3,23,'Sillä kaikki ovat syntiä tehneet ja ovat Jumalan kirkkautta vailla'),
(1696946,58,45,3,24,'ja saavat lahjaksi vanhurskauden hänen armostaan sen lunastuksen kautta, joka on Kristuksessa Jeesuksessa,'),
(1696947,58,45,3,25,'jonka Jumala on asettanut armoistuimeksi uskon kautta hänen vereensä, osoittaaksensa vanhurskauttaan, koska hän oli jättänyt rankaisematta ennen tehdyt synnit'),
(1696948,58,45,3,26,'jumalallisessa kärsivällisyydessään, osoittaaksensa vanhurskauttaan nykyajassa, sitä, että hän itse on vanhurskas ja vanhurskauttaa sen, jolla on usko Jeesukseen.'),
(1696949,58,45,3,27,'Missä siis on kerskaaminen? Se on suljettu pois. Minkä lain kautta? Tekojenko lain? Ei, vaan uskon lain kautta.'),
(1696950,58,45,3,28,'Niin päätämme siis, että ihminen vanhurskautetaan uskon kautta, ilman lain tekoja.'),
(1696951,58,45,3,29,'Vai onko Jumala yksistään juutalaisten Jumala? Eikö pakanainkin? On pakanainkin,'),
(1696952,58,45,3,30,'koskapa Jumala on yksi, joka vanhurskauttaa ympärileikatut uskosta ja ympärileikkaamattomat uskon kautta.'),
(1696953,58,45,3,31,'Teemmekö siis lain mitättömäksi uskon kautta? Pois se! Vaan me vahvistamme lain.'),
(1696954,58,45,4,1,'Mitä me siis sanomme esi-isämme Aabrahamin saavuttaneen lihan mukaan?'),
(1696955,58,45,4,2,'Sillä jos Aabraham on teoista vanhurskautettu, on hänellä kerskaamista, mutta ei Jumalan edessä.'),
(1696956,58,45,4,3,'Sillä mitä Raamattu sanoo? "Aabraham uskoi Jumalaa, ja se luettiin hänelle vanhurskaudeksi".'),
(1696957,58,45,4,4,'Mutta töitä tekevälle ei lueta palkkaa armosta, vaan ansiosta,'),
(1696958,58,45,4,5,'mutta joka ei töitä tee, vaan uskoo häneen, joka vanhurskauttaa jumalattoman, sille luetaan hänen uskonsa vanhurskaudeksi;'),
(1696959,58,45,4,6,'niinkuin myös Daavid ylistää autuaaksi sitä ihmistä, jolle Jumala lukee vanhurskauden ilman tekoja:'),
(1696960,58,45,4,7,'"Autuaat ne, joiden rikokset ovat anteeksi annetut ja joiden synnit ovat peitetyt!'),
(1696961,58,45,4,8,'Autuas se mies, jolle Herra ei lue syntiä!"'),
(1696962,58,45,4,9,'Koskeeko sitten tämä autuaaksi ylistäminen ainoastaan ympärileikattuja, vai eikö ympärileikkaamattomiakin? Sanommehan: "Aabrahamille luettiin usko vanhurskaudeksi".'),
(1696963,58,45,4,10,'Kuinka se sitten siksi luettiin? Hänen ollessaanko ympärileikattuna vai ympärileikkaamatonna? Ei ympärileikattuna, vaan ympärileikkaamatonna.'),
(1696964,58,45,4,11,'Ja hän sai ympärileikkauksen merkin sen uskonvanhurskauden sinetiksi, joka hänellä oli ympärileikkaamatonna, että hänestä tulisi kaikkien isä, jotka ympärileikkaamattomina uskovat, niin että vanhurskaus heillekin luettaisiin;'),
(1696965,58,45,4,12,'ja että hänestä tulisi myöskin ympärileikattujen isä, niiden, jotka eivät ainoastaan ole ympärileikattuja, vaan myös vaeltavat sen uskon jälkiä, mikä meidän isällämme Aabrahamilla oli jo ympärileikkaamatonna.'),
(1696966,58,45,4,13,'Sillä se lupaus, että Aabraham oli perivä maailman, ei tullut hänelle eikä hänen siemenelleen lain kautta, vaan uskonvanhurskauden kautta.'),
(1696967,58,45,4,14,'Sillä jos ne, jotka pitäytyvät lakiin, ovat perillisiä, niin usko on tyhjäksi tehty ja lupaus käynyt mitättömäksi.'),
(1696968,58,45,4,15,'Sillä laki saa aikaan vihaa; mutta missä lakia ei ole, siellä ei ole rikkomustakaan.'),
(1696969,58,45,4,16,'Sentähden se on uskosta, että se olisi armosta; että lupaus pysyisi lujana kaikelle siemenelle, ei ainoastaan sille, joka pitäytyy lakiin, vaan myös sille, jolla on Aabrahamin usko, hänen, joka on meidän kaikkien isä'),
(1696970,58,45,4,17,'- niinkuin kirjoitettu on: "Monen kansan isäksi minä olen sinut asettanut" - sen Jumalan edessä, johon hän uskoi ja joka kuolleet eläviksi tekee ja kutsuu olemattomat, ikäänkuin ne olisivat.'),
(1696971,58,45,4,18,'Ja Aabraham toivoi, vaikka ei toivoa ollut, ja uskoi tulevansa monen kansan isäksi, tämän sanan mukaan: "Niin on sinun jälkeläistesi luku oleva",'),
(1696972,58,45,4,19,'eikä hän heikontunut uskossansa, vaikka näki, että hänen ruumiinsa oli kuolettunut - sillä hän oli jo noin satavuotias - ja että Saaran kohtu oli kuolettunut;'),
(1696973,58,45,4,20,'mutta Jumalan lupausta hän ei epäuskossa epäillyt, vaan vahvistui uskossa, antaen kunnian Jumalalle,'),
(1696974,58,45,4,21,'ja oli täysin varma siitä, että minkä Jumala on luvannut, sen hän voi myös täyttää.'),
(1696975,58,45,4,22,'Sentähden se luettiinkin hänelle vanhurskaudeksi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1696976,58,45,4,23,'Mutta ei ainoastaan hänen tähtensä ole kirjoitettu, että se hänelle luettiin,'),
(1696977,58,45,4,24,'vaan myös meidän tähtemme, joille se on luettava, kun uskomme häneen, joka kuolleista herätti Jeesuksen, meidän Herramme,'),
(1696978,58,45,4,25,'joka on alttiiksi annettu meidän rikostemme tähden ja kuolleista herätetty meidän vanhurskauttamisemme tähden.'),
(1696979,58,45,5,1,'Koska me siis olemme uskosta vanhurskaiksi tulleet, niin meillä on rauha Jumalan kanssa meidän Herramme Jeesuksen Kristuksen kautta,'),
(1696980,58,45,5,2,'jonka kautta myös olemme uskossa saaneet pääsyn tähän armoon, jossa me nyt olemme, ja meidän kerskauksemme on Jumalan kirkkauden toivo.'),
(1696981,58,45,5,3,'Eikä ainoastaan se, vaan meidän kerskauksenamme ovat myös ahdistukset, sillä me tiedämme, että ahdistus saa aikaan kärsivällisyyttä,'),
(1696982,58,45,5,4,'mutta kärsivällisyys koettelemuksen kestämistä, ja koettelemuksen kestäminen toivoa;'),
(1696983,58,45,5,5,'mutta toivo ei saata häpeään; sillä Jumalan rakkaus on vuodatettu meidän sydämiimme Pyhän Hengen kautta, joka on meille annettu.'),
(1696984,58,45,5,6,'Sillä meidän vielä ollessamme heikot kuoli Kristus oikeaan aikaan jumalattomien edestä.'),
(1696985,58,45,5,7,'Tuskinpa kukaan käy kuolemaan jonkun vanhurskaan edestä; hyvän edestä joku mahdollisesti uskaltaa kuolla.'),
(1696986,58,45,5,8,'Mutta Jumala osoittaa rakkautensa meitä kohtaan siinä, että Kristus, kun me vielä olimme syntisiä, kuoli meidän edestämme.'),
(1696987,58,45,5,9,'Paljoa ennemmin me siis nyt, kun olemme vanhurskautetut hänen veressään, pelastumme hänen kauttansa vihasta.'),
(1696988,58,45,5,10,'Sillä jos me silloin, kun vielä olimme Jumalan vihollisia, tulimme sovitetuiksi hänen kanssaan hänen Poikansa kuoleman kautta, paljoa ennemmin me pelastumme hänen elämänsä kautta nyt, kun olemme sovitetut;'),
(1696989,58,45,5,11,'emmekä ainoastaan sovitetut, vaan vieläpä on Jumala meidän kerskauksemme meidän Herramme Jeesuksen Kristuksen kautta, jonka kautta me nyt olemme sovituksen saaneet.'),
(1696990,58,45,5,12,'Sentähden, niinkuin yhden ihmisen kautta synti tuli maailmaan, ja synnin kautta kuolema, niin kuolema on tullut kaikkien ihmisten osaksi, koska kaikki ovat syntiä tehneet -'),
(1696991,58,45,5,13,'sillä jo ennen lakiakin oli synti maailmassa, mutta syntiä ei lueta, missä lakia ei ole;'),
(1696992,58,45,5,14,'kuitenkin kuolema hallitsi Aadamista Moosekseen asti niitäkin, jotka eivät olleet syntiä tehneet samankaltaisella rikkomuksella kuin Aadam, joka on sen esikuva, joka oli tuleva.'),
(1696993,58,45,5,15,'Mutta armolahjan laita ei ole sama kuin lankeemuksen; sillä joskin yhden lankeemuksesta monet ovat kuolleet, niin paljoa enemmän on Jumalan armo ja lahja yhden ihmisen, Jeesuksen Kristuksen, armon kautta ylenpalttisesti tullut monien osaksi.'),
(1696994,58,45,5,16,'Eikä lahjan laita ole, niinkuin on sen, mikä tuli yhden synnintekijän kautta; sillä tuomio tuli yhdestä ihmisestä kadotukseksi, mutta armolahja tulee monesta rikkomuksesta vanhurskauttamiseksi.'),
(1696995,58,45,5,17,'Ja jos yhden ihmisen lankeemuksen tähden kuolema on hallinnut yhden kautta, niin paljoa enemmän ne, jotka saavat armon ja vanhurskauden lahjan runsauden, tulevat elämässä hallitsemaan yhden, Jeesuksen Kristuksen, kautta. -'),
(1696996,58,45,5,18,'Niinpä siis, samoin kuin yhden ihmisen lankeemus on koitunut kaikille ihmisille kadotukseksi, niin myös yhden ihmisen vanhurskauden teko koituu kaikille ihmisille elämän vanhurskauttamiseksi;'),
(1696997,58,45,5,19,'sillä niinkuin yhden ihmisen tottelemattomuuden kautta monet ovat joutuneet syntisiksi, niin myös yhden kuuliaisuuden kautta monet tulevat vanhurskaiksi.'),
(1696998,58,45,5,20,'Mutta laki tuli väliin, että rikkomus suureksi tulisi; mutta missä synti on suureksi tullut, siinä armo on tullut ylenpalttiseksi,'),
(1696999,58,45,5,21,'että niinkuin synti on hallinnut kuolemassa, samoin armokin hallitsisi vanhurskauden kautta iankaikkiseksi elämäksi Jeesuksen Kristuksen, meidän Herramme, kautta.'),
(1697000,58,45,6,1,'Mitä siis sanomme? Onko meidän pysyttävä synnissä, että armo suureksi tulisi?'),
(1697001,58,45,6,2,'Pois se! Me, jotka olemme kuolleet pois synnistä, kuinka me vielä eläisimme siinä?'),
(1697002,58,45,6,3,'Vai ettekö tiedä, että me kaikki, jotka olemme kastetut Kristukseen Jeesukseen, olemme hänen kuolemaansa kastetut?'),
(1697003,58,45,6,4,'Niin olemme siis yhdessä hänen kanssaan haudatut kasteen kautta kuolemaan, että niinkuin Kristus herätettiin kuolleista Isän kirkkauden kautta, samoin pitää meidänkin uudessa elämässä vaeltaman.'),
(1697004,58,45,6,5,'Sillä jos me olemme hänen kanssaan yhteenkasvaneita yhtäläisessä kuolemassa, niin olemme samoin myös yhtäläisessä ylösnousemuksessa,'),
(1697005,58,45,6,6,'kun tiedämme sen, että meidän vanha ihmisemme on hänen kanssaan ristiinnaulittu, että synnin ruumis kukistettaisiin, niin ettemme enää syntiä palvelisi;'),
(1697006,58,45,6,7,'sillä joka on kuollut, se on vanhurskautunut pois synnistä.'),
(1697007,58,45,6,8,'Mutta jos olemme kuolleet Kristuksen kanssa, niin me uskomme saavamme myös elää hänen kanssaan,'),
(1697008,58,45,6,9,'tietäen, että Kristus, sittenkuin hänet kuolleista herätettiin, ei enää kuole: kuolema ei enää häntä vallitse.'),
(1697009,58,45,6,10,'Sillä minkä hän kuoli, sen hän kerta kaikkiaan kuoli pois synnistä; mutta minkä hän elää, sen hän elää Jumalalle.'),
(1697010,58,45,6,11,'Niin tekin pitäkää itsenne synnille kuolleina, mutta Jumalalle elävinä Kristuksessa Jeesuksessa.'),
(1697011,58,45,6,12,'Älköön siis synti hallitko teidän kuolevaisessa ruumiissanne, niin että olette kuuliaiset sen himoille,'),
(1697012,58,45,6,13,'älkääkä antako jäseniänne vääryyden aseiksi synnille, vaan antakaa itsenne, kuolleista eläviksi tulleina, Jumalalle, ja jäsenenne vanhurskauden aseiksi Jumalalle.'),
(1697013,58,45,6,14,'Sillä synnin ei pidä teitä vallitseman, koska ette ole lain alla, vaan armon alla.'),
(1697014,58,45,6,15,'Kuinka siis on? Saammeko tehdä syntiä, koska emme ole lain alla, vaan armon alla? Pois se!'),
(1697015,58,45,6,16,'Ettekö tiedä, että kenen palvelijoiksi, ketä tottelemaan, te antaudutte, sen palvelijoita te olette, jota te tottelette, joko synnin palvelijoita, kuolemaksi, tahi kuuliaisuuden, vanhurskaudeksi?'),
(1697016,58,45,6,17,'Mutta kiitos Jumalalle, että te, jotka ennen olitte synnin palvelijoita, nyt olette tulleet sydämestänne kuuliaisiksi sille opin muodolle, jonka johtoon te olette annetut,'),
(1697017,58,45,6,18,'ja että te synnistä vapautettuina olette tulleet vanhurskauden palvelijoiksi!'),
(1697018,58,45,6,19,'Minä puhun ihmisten tavalla teidän lihanne heikkouden tähden. Sillä niinkuin te ennen annoitte jäsenenne saastaisuuden ja laittomuuden palvelijoiksi laittomuuteen, niin antakaa nyt jäsenenne vanhurskauden palvelijoiksi pyhitykseen.'),
(1697019,58,45,6,20,'Sillä kun olitte synnin palvelijoita, niin te olitte vapaat vanhurskaudesta.'),
(1697020,58,45,6,21,'Minkä hedelmän te siitä silloin saitte? Sen, jota te nyt häpeätte. Sillä sen loppu on kuolema.'),
(1697021,58,45,6,22,'Mutta nyt, kun olette synnistä vapautetut ja Jumalan palvelijoiksi tulleet, on teidän hedelmänne pyhitys, ja sen loppu on iankaikkinen elämä.'),
(1697022,58,45,6,23,'Sillä synnin palkka on kuolema, mutta Jumalan armolahja on iankaikkinen elämä Kristuksessa Jeesuksessa, meidän Herrassamme.'),
(1697023,58,45,7,1,'Vai ettekö tiedä, veljet - minä puhun lain tunteville - että laki vallitsee ihmistä, niin kauan kuin hän elää?'),
(1697024,58,45,7,2,'Niinpä sitoo laki naidun vaimon hänen elossa olevaan mieheensä; mutta jos mies kuolee, on vaimo irti tästä miehen laista.'),
(1697025,58,45,7,3,'Sentähden hän saa avionrikkojan nimen, jos miehensä eläessä antautuu toiselle miehelle; mutta jos mies kuolee, on hän vapaa siitä laista, niin ettei hän ole avionrikkoja, jos menee toiselle miehelle.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697026,58,45,7,4,'Niin, veljeni, teidätkin on kuoletettu laista Kristuksen ruumiin kautta, tullaksenne toisen omiksi, hänen, joka on kuolleista herätetty, että me kantaisimme hedelmää Jumalalle.'),
(1697027,58,45,7,5,'Sillä kun olimme lihan vallassa, niin synnin himot, jotka laki herättää, vaikuttivat meidän jäsenissämme, niin että me kannoimme hedelmää kuolemalle,'),
(1697028,58,45,7,6,'mutta nyt me olemme irti laista ja kuolleet pois siitä, mikä meidät piti vankeina, niin että me palvelemme Jumalaa Hengen uudessa tilassa emmekä kirjaimen vanhassa.'),
(1697029,58,45,7,7,'Mitä siis sanomme? Onko laki syntiä? Pois se! Mutta syntiä en olisi tullut tuntemaan muuten kuin lain kautta; sillä en minä olisi tiennyt himosta, ellei laki olisi sanonut: "Älä himoitse".'),
(1697030,58,45,7,8,'Mutta kun synti otti käskysanasta aiheen, herätti se minussa kaikkinaisia himoja; sillä ilman lakia on synti kuollut.'),
(1697031,58,45,7,9,'Minä elin ennen ilman lakia; mutta kun käskysana tuli, niin synti virkosi,'),
(1697032,58,45,7,10,'ja minä kuolin. Niin kävi ilmi, että käskysana, joka oli oleva minulle elämäksi, olikin minulle kuolemaksi.'),
(1697033,58,45,7,11,'Sillä kun synti otti käskysanasta aiheen, petti se minut ja kuoletti minut käskysanan kautta.'),
(1697034,58,45,7,12,'Niin, laki on kuitenkin pyhä ja käskysana pyhä, vanhurskas ja hyvä.'),
(1697035,58,45,7,13,'Onko siis hyvä tullut minulle kuolemaksi? Pois se! Vaan synti, että se synniksi nähtäisiin, on hyvän kautta tuottanut minulle kuoleman, että synti tulisi ylenmäärin synnilliseksi käskysanan kautta.'),
(1697036,58,45,7,14,'Sillä me tiedämme, että laki on hengellinen, mutta minä olen lihallinen, myyty synnin alaisuuteen.'),
(1697037,58,45,7,15,'Sillä minä en tunne omakseni sitä, mitä teen; sillä minä en toteuta sitä, mitä tahdon, vaan mitä minä vihaan, sitä minä teen.'),
(1697038,58,45,7,16,'Mutta jos minä teen sitä, mitä en tahdo, niin minä myönnän, että laki on hyvä.'),
(1697039,58,45,7,17,'Niin en nyt enää tee sitä minä, vaan synti, joka minussa asuu.'),
(1697040,58,45,7,18,'Sillä minä tiedän, ettei minussa, se on minun lihassani, asu mitään hyvää. Tahto minulla kyllä on, mutta voimaa hyvän toteuttamiseen ei;'),
(1697041,58,45,7,19,'sillä sitä hyvää, mitä minä tahdon, minä en tee, vaan sitä pahaa, mitä en tahdo, minä teen.'),
(1697042,58,45,7,20,'Jos minä siis teen sitä, mitä en tahdo, niin sen tekijä en enää ole minä, vaan synti, joka minussa asuu.'),
(1697043,58,45,7,21,'Niin huomaan siis itsessäni, minä, joka tahdon hyvää tehdä, sen lain, että paha riippuu minussa kiinni;'),
(1697044,58,45,7,22,'sillä sisällisen ihmiseni puolesta minä ilolla yhdyn Jumalan lakiin,'),
(1697045,58,45,7,23,'mutta jäsenissäni minä näen toisen lain, joka sotii minun mieleni lakia vastaan ja pitää minut vangittuna synnin laissa, joka minun jäsenissäni on.'),
(1697046,58,45,7,24,'Minä viheliäinen ihminen, kuka pelastaa minut tästä kuoleman ruumiista?'),
(1697047,58,45,7,25,'Kiitos Jumalalle Jeesuksen Kristuksen, meidän Herramme, kautta! Niin minä siis tämmöisenäni palvelen mielellä Jumalan lakia, mutta lihalla synnin lakia.'),
(1697048,58,45,8,1,'Niin ei nyt siis ole mitään kadotustuomiota niille, jotka Kristuksessa Jeesuksessa ovat.'),
(1697049,58,45,8,2,'Sillä elämän hengen laki Kristuksessa Jeesuksessa on vapauttanut sinut synnin ja kuoleman laista.'),
(1697050,58,45,8,3,'Sillä mikä laille oli mahdotonta, koska se oli lihan kautta heikoksi tullut, sen Jumala teki, lähettämällä oman Poikansa syntisen lihan kaltaisuudessa ja synnin tähden ja tuomitsemalla synnin lihassa,'),
(1697051,58,45,8,4,'että lain vanhurskaus täytettäisiin meissä, jotka emme vaella lihan mukaan, vaan Hengen.'),
(1697052,58,45,8,5,'Sillä niillä, jotka elävät lihan mukaan, on lihan mieli, mutta niillä, jotka elävät Hengen mukaan, on Hengen mieli.'),
(1697053,58,45,8,6,'Sillä lihan mieli on kuolema, mutta hengen mieli on elämä ja rauha;'),
(1697054,58,45,8,7,'sentähden että lihan mieli on vihollisuus Jumalaa vastaan, sillä se ei alistu Jumalan lain alle, eikä se voikaan.'),
(1697055,58,45,8,8,'Jotka lihan vallassa ovat, ne eivät voi olla Jumalalle otolliset.'),
(1697056,58,45,8,9,'Mutta te ette ole lihan vallassa, vaan Hengen, jos kerran Jumalan Henki teissä asuu. Mutta jolla ei ole Kristuksen Henkeä, se ei ole hänen omansa.'),
(1697057,58,45,8,10,'Mutta jos Kristus on teissä, niin ruumis tosin on kuollut synnin tähden, mutta henki on elämä vanhurskauden tähden.'),
(1697058,58,45,8,11,'Jos nyt hänen Henkensä, hänen, joka herätti Jeesuksen kuolleista, asuu teissä, niin hän, joka herätti kuolleista Kristuksen Jeesuksen, on eläväksitekevä myös teidän kuolevaiset ruumiinne Henkensä kautta, joka teissä asuu.'),
(1697059,58,45,8,12,'Niin me siis, veljet, olemme velassa, mutta emme lihalle, lihan mukaan elääksemme.'),
(1697060,58,45,8,13,'Sillä jos te lihan mukaan elätte, pitää teidän kuoleman; mutta jos te Hengellä kuoletatte ruumiin teot, niin saatte elää.'),
(1697061,58,45,8,14,'Sillä kaikki, joita Jumalan Henki kuljettaa, ovat Jumalan lapsia.'),
(1697062,58,45,8,15,'Sillä te ette ole saaneet orjuuden henkeä ollaksenne jälleen pelossa, vaan te olette saaneet lapseuden hengen, jossa me huudamme: "Abba! Isä!"'),
(1697063,58,45,8,16,'Henki itse todistaa meidän henkemme kanssa, että me olemme Jumalan lapsia.'),
(1697064,58,45,8,17,'Mutta jos olemme lapsia, niin olemme myöskin perillisiä, Jumalan perillisiä ja Kristuksen kanssaperillisiä, jos kerran yhdessä hänen kanssaan kärsimme, että me yhdessä myös kirkastuisimme.'),
(1697065,58,45,8,18,'Sillä minä päätän, että tämän nykyisen ajan kärsimykset eivät ole verrattavat siihen kirkkauteen, joka on ilmestyvä meihin.'),
(1697066,58,45,8,19,'Sillä luomakunnan harras ikävöitseminen odottaa Jumalan lasten ilmestymistä.'),
(1697067,58,45,8,20,'Sillä luomakunta on alistettu katoavaisuuden alle - ei omasta tahdostaan, vaan alistajan - kuitenkin toivon varaan,'),
(1697068,58,45,8,21,'koska itse luomakuntakin on tuleva vapautetuksi turmeluksen orjuudesta Jumalan lasten kirkkauden vapauteen.'),
(1697069,58,45,8,22,'Sillä me tiedämme, että koko luomakunta yhdessä huokaa ja on synnytystuskissa hamaan tähän asti;'),
(1697070,58,45,8,23,'eikä ainoastaan se, vaan myös me, joilla on Hengen esikoislahja, mekin huokaamme sisimmässämme, odottaen lapseksi-ottamista, meidän ruumiimme lunastusta.'),
(1697071,58,45,8,24,'Sillä toivossa me olemme pelastetut, mutta toivo, jonka näkee täyttyneen, ei ole mikään toivo; kuinka kukaan sitä toivoo, minkä näkee?'),
(1697072,58,45,8,25,'Mutta jos toivomme, mitä emme näe, niin me odotamme sitä kärsivällisyydellä.'),
(1697073,58,45,8,26,'Samoin myös Henki auttaa meidän heikkouttamme. Sillä me emme tiedä, mitä meidän pitää rukoileman, niinkuin rukoilla tulisi, mutta Henki itse rukoilee meidän puolestamme sanomattomilla huokauksilla.'),
(1697074,58,45,8,27,'Mutta sydänten tutkija tietää, mikä Hengen mieli on, sillä Henki rukoilee Jumalan tahdon mukaan pyhien edestä.'),
(1697075,58,45,8,28,'Mutta me tiedämme, että kaikki yhdessä vaikuttaa niiden parhaaksi, jotka Jumalaa rakastavat, niiden, jotka hänen aivoituksensa mukaan ovat kutsutut.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697076,58,45,8,29,'Sillä ne, jotka hän on edeltätuntenut, hän on myös edeltämäärännyt Poikansa kuvan kaltaisiksi, että hän olisi esikoinen monien veljien joukossa;'),
(1697077,58,45,8,30,'mutta jotka hän on edeltämäärännyt, ne hän on myös kutsunut; ja jotka hän on kutsunut, ne hän on myös vanhurskauttanut; mutta jotka hän on vanhurskauttanut, ne hän on myös kirkastanut.'),
(1697078,58,45,8,31,'Mitä me siis tähän sanomme? Jos Jumala on meidän puolellamme, kuka voi olla meitä vastaan?'),
(1697079,58,45,8,32,'Hän, joka ei säästänyt omaa Poikaansakaan, vaan antoi hänet alttiiksi kaikkien meidän edestämme, kuinka hän ei lahjoittaisi meille kaikkea muutakin hänen kanssansa?'),
(1697080,58,45,8,33,'Kuka voi syyttää Jumalan valittuja? Jumala on se, joka vanhurskauttaa.'),
(1697081,58,45,8,34,'Kuka voi tuomita kadotukseen? Kristus Jeesus on se, joka on kuollut, onpa vielä herätettykin, ja hän on Jumalan oikealla puolella, ja hän myös rukoilee meidän edestämme.'),
(1697082,58,45,8,35,'Kuka voi meidät erottaa Kristuksen rakkaudesta? Tuskako, vai ahdistus, vai vaino, vai nälkä, vai alastomuus, vai vaara, vai miekka?'),
(1697083,58,45,8,36,'Niinkuin kirjoitettu on: "Sinun tähtesi meitä surmataan kaiken päivää; meitä pidetään teuraslampaina".'),
(1697084,58,45,8,37,'Mutta näissä kaikissa me saamme jalon voiton hänen kauttansa, joka meitä on rakastanut.'),
(1697085,58,45,8,38,'Sillä minä olen varma siitä, ettei kuolema eikä elämä, ei enkelit eikä henkivallat, ei nykyiset eikä tulevaiset, ei voimat,'),
(1697086,58,45,8,39,'ei korkeus eikä syvyys, eikä mikään muu luotu voi meitä erottaa Jumalan rakkaudesta, joka on Kristuksessa Jeesuksessa, meidän Herrassamme.'),
(1697087,58,45,9,1,'Minä sanon totuuden Kristuksessa, en valhettele - sen todistaa minulle omatuntoni Pyhässä Hengessä -'),
(1697088,58,45,9,2,'että minulla on suuri murhe ja ainainen kipu sydämessäni.'),
(1697089,58,45,9,3,'Sillä minä soisin itse olevani kirottu pois Kristuksesta veljieni hyväksi, jotka ovat minun sukulaisiani lihan puolesta,'),
(1697090,58,45,9,4,'ovat israelilaisia: heidän on lapseus ja kirkkaus ja liitot ja lain antaminen ja jumalanpalvelus ja lupaukset;'),
(1697091,58,45,9,5,'heidän ovat isät, ja heistä on Kristus lihan puolesta, hän, joka on yli kaiken, Jumala, ylistetty iankaikkisesti, amen!'),
(1697092,58,45,9,6,'Mutta ei niin, että Jumalan sana olisi harhaan mennyt. Sillä eivät kaikki ne, jotka ovat Israelista, ole silti Israel,'),
(1697093,58,45,9,7,'eivät kaikki ole lapsia sentähden, että ovat Aabrahamin siementä, vaan: "Iisakista sinä saat nimellesi jälkeläiset";'),
(1697094,58,45,9,8,'se on: eivät ne, jotka lihan puolesta ovat lapsia, ole Jumalan lapsia, vaan lupauksen lapset, ne luetaan siemeneksi.'),
(1697095,58,45,9,9,'Sillä lupauksen sana oli tämä: "Minä palaan tulevana vuonna tähän aikaan, ja silloin Saaralla on oleva poika".'),
(1697096,58,45,9,10,'Eikä ainoastaan hänelle näin käynyt, vaan samoin kävi Rebekallekin, joka oli tullut raskaaksi yhdestä, meidän isästämme Iisakista;'),
(1697097,58,45,9,11,'ja ennenkuin kaksoset olivat syntyneetkään ja ennenkuin olivat tehneet mitään, hyvää tai pahaa, niin - että Jumalan valinnan mukainen aivoitus pysyisi, ei tekojen tähden, vaan kutsujan tähden -'),
(1697098,58,45,9,12,'sanottiin hänelle: "Vanhempi on palveleva nuorempaa",'),
(1697099,58,45,9,13,'niinkuin kirjoitettu on: "Jaakobia minä rakastin, mutta Eesauta minä vihasin".'),
(1697100,58,45,9,14,'Mitä siis sanomme? Ei kaiketi Jumalassa ole vääryyttä? Pois se!'),
(1697101,58,45,9,15,'Sillä Moosekselle hän sanoo: "Minä olen armollinen, kenelle olen armollinen, ja armahdan, ketä armahdan".'),
(1697102,58,45,9,16,'Niin se ei siis ole sen vallassa, joka tahtoo, eikä sen, joka juoksee, vaan Jumalan, joka on armollinen.'),
(1697103,58,45,9,17,'Sillä Raamattu sanoo faraolle: "Juuri sitä varten minä nostin sinut esiin, että näyttäisin sinussa voimani ja että minun nimeni julistettaisiin kaiken maan päällä".'),
(1697104,58,45,9,18,'Niin hän siis on armollinen, kenelle tahtoo, ja paaduttaa, kenen tahtoo.'),
(1697105,58,45,9,19,'Sinä kaiketi sanot minulle: "Miksi hän sitten vielä soimaa? Sillä kuka voi vastustaa hänen tahtoansa?"'),
(1697106,58,45,9,20,'Niinpä niin, oi ihminen, mutta mikä sinä olet riitelemään Jumalaa vastaan? Ei kaiketi tehty sano tekijälleen: "Miksi minusta tällaisen teit?"'),
(1697107,58,45,9,21,'Vai eikö savenvalajalla ole valta tehdä samasta savensa seoksesta toinen astia jaloa, toinen halpaa käyttöä varten?'),
(1697108,58,45,9,22,'Entä jos Jumala, vaikka hän tahtoo näyttää vihansa ja tehdä voimansa tiettäväksi, on suurella pitkämielisyydellä kärsinyt vihan astioita, jotka olivat valmiit häviöön,'),
(1697109,58,45,9,23,'ja on tehnyt sen saattaakseen kirkkautensa runsauden ilmi laupeuden astioissa, jotka hän on edeltävalmistanut kirkkauteen?'),
(1697110,58,45,9,24,'Ja sellaisiksi hän myös on kutsunut meidät, ei ainoastaan juutalaisista, vaan myös pakanoista,'),
(1697111,58,45,9,25,'niinkuin hän myös Hoosean kirjassa sanoo: "Minä olen kutsuva kansakseni sen, joka ei ollut minun kansani, ja rakkaakseni sen, joka ei ollut minun rakkaani.'),
(1697112,58,45,9,26,'Ja on tapahtuva, että siinä paikassa, jossa heille on sanottu: ''Te ette ole minun kansani'', siinä heitä kutsutaan elävän Jumalan lapsiksi."'),
(1697113,58,45,9,27,'Mutta Esaias huudahtaa Israelista: "Vaikka Israelin lapset olisivat luvultaan kuin meren hiekka, niin pelastuu heistä vain jäännös.'),
(1697114,58,45,9,28,'Sillä sanansa on Herra toteuttava maan päällä lopullisesti ja rutosti."'),
(1697115,58,45,9,29,'Niinkuin Esaias myös on ennustanut: "Ellei Herra Sebaot olisi jättänyt meille siementä, niin meidän olisi käynyt niinkuin Sodoman, ja me olisimme tulleet Gomorran kaltaisiksi".'),
(1697116,58,45,9,30,'Mitä me siis sanomme? Että pakanat, jotka eivät tavoitelleet vanhurskautta, ovat saavuttaneet vanhurskauden, mutta sen vanhurskauden, joka tulee uskosta;'),
(1697117,58,45,9,31,'mutta Israel, joka tavoitteli vanhurskauden lakia, ei ole sitä lakia saavuttanut.'),
(1697118,58,45,9,32,'Minkätähden? Sentähden, ettei se tapahtunut uskosta, vaan ikäänkuin teoista; sillä he loukkautuivat loukkauskiveen,'),
(1697119,58,45,9,33,'niinkuin kirjoitettu on: "Katso, minä panen Siioniin loukkauskiven ja kompastuksen kallion, ja joka häneen uskoo, se ei häpeään joudu".'),
(1697120,58,45,10,1,'Veljet, minä toivon sydämestäni ja rukoilen Jumalaa heidän edestänsä, että he pelastuisivat.'),
(1697121,58,45,10,2,'Sillä minä todistan heistä, että heillä on kiivaus Jumalan puolesta, mutta ei taidon mukaan;'),
(1697122,58,45,10,3,'sillä kun he eivät tunne Jumalan vanhurskautta, vaan koettavat pystyttää omaa vanhurskauttaan, eivät he ole alistuneet Jumalan vanhurskauden alle.'),
(1697123,58,45,10,4,'Sillä Kristus on lain loppu, vanhurskaudeksi jokaiselle, joka uskoo.'),
(1697124,58,45,10,5,'Kirjoittaahan Mooses siitä vanhurskaudesta, joka laista tulee, että ihminen, joka sen täyttää, on siitä elävä.'),
(1697125,58,45,10,6,'Mutta se vanhurskaus, joka uskosta tulee, sanoo näin: "Älä sano sydämessäsi: Kuka nousee taivaaseen?" se on: tuomaan Kristusta alas,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697126,58,45,10,7,'tahi: "Kuka astuu alas syvyyteen?" se on: nostamaan Kristusta kuolleista.'),
(1697127,58,45,10,8,'Mutta mitä se sanoo? "Sana on sinua lähellä, sinun suussasi ja sinun sydämessäsi"; se on se uskon sana, jota me saarnaamme.'),
(1697128,58,45,10,9,'Sillä jos sinä tunnustat suullasi Jeesuksen Herraksi ja uskot sydämessäsi, että Jumala on hänet kuolleista herättänyt, niin sinä pelastut;'),
(1697129,58,45,10,10,'sillä sydämen uskolla tullaan vanhurskaaksi ja suun tunnustuksella pelastutaan.'),
(1697130,58,45,10,11,'Sanoohan Raamattu: "Ei yksikään, joka häneen uskoo, joudu häpeään".'),
(1697131,58,45,10,12,'Tässä ei ole erotusta juutalaisen eikä kreikkalaisen välillä; sillä yksi ja sama on kaikkien Herra, rikas antaja kaikille, jotka häntä avuksi huutavat.'),
(1697132,58,45,10,13,'Sillä "jokainen, joka huutaa avuksi Herran nimeä, pelastuu".'),
(1697133,58,45,10,14,'Mutta kuinka he huutavat avuksensa sitä, johon eivät usko? Ja kuinka he voivat uskoa siihen, josta eivät ole kuulleet? Ja kuinka he voivat kuulla, ellei ole julistajaa?'),
(1697134,58,45,10,15,'Ja kuinka kukaan voi julistaa, ellei ketään lähetetä? Niinkuin kirjoitettu on: "Kuinka suloiset ovat niiden jalat, jotka hyvää sanomaa julistavat!"'),
(1697135,58,45,10,16,'Mutta eivät kaikki ole olleet kuuliaisia evankeliumille. Sillä Esaias sanoo: "Herra, kuka uskoo meidän saarnamme?"'),
(1697136,58,45,10,17,'Usko tulee siis kuulemisesta, mutta kuuleminen Kristuksen sanan kautta.'),
(1697137,58,45,10,18,'Mutta minä kysyn: eivätkö he ole kuulleet? Kyllä ovat: "Heidän äänensä on kulkenut kaikkiin maihin, ja heidän sanansa maan piirin ääriin".'),
(1697138,58,45,10,19,'Minä kysyn: eikö Israelilla ole ollut siitä tietoa? Ensiksi jo Mooses sanoo: "Minä herätän teidän kiivautenne kansan kautta, joka ei ole kansa, ymmärtämättömän kansan kautta minä teitä kiihoitan".'),
(1697139,58,45,10,20,'Ja Esaias on rohkea ja sanoo: "Minut ovat löytäneet ne, jotka eivät minua etsineet; minä olen ilmestynyt niille, jotka eivät minua kysyneet".'),
(1697140,58,45,10,21,'Mutta Israelista hän sanoo: "Koko päivän minä olen ojentanut käsiäni tottelematonta ja uppiniskaista kansaa kohden".'),
(1697141,58,45,11,1,'Minä sanon siis: ei kaiketi Jumala ole hyljännyt kansaansa? Pois se! Sillä olenhan minäkin israelilainen, Aabrahamin siementä, Benjaminin sukukuntaa.'),
(1697142,58,45,11,2,'Ei Jumala ole hyljännyt kansaansa, jonka hän on edeltätuntenut. Vai ettekö tiedä, mitä Raamattu sanoo kertomuksessa Eliaasta, kuinka hän Jumalan edessä syyttää Israelia:'),
(1697143,58,45,11,3,'"Herra, he ovat tappaneet sinun profeettasi ja hajottaneet sinun alttarisi, ja minä yksin olen jäänyt jäljelle, ja he väijyvät minun henkeäni"?'),
(1697144,58,45,11,4,'Mutta mitä sanoo hänelle Jumalan vastaus? "Minä olen jättänyt itselleni seitsemäntuhatta miestä, jotka eivät ole notkistaneet polvea Baalille."'),
(1697145,58,45,11,5,'Samoin on nyt tänäkin aikana olemassa jäännös armon valinnan mukaan.'),
(1697146,58,45,11,6,'Mutta jos valinta on armosta, niin se ei ole enää teoista, sillä silloin armo ei enää olisikaan armo.'),
(1697147,58,45,11,7,'Miten siis on? Mitä Israel tavoittelee, sitä se ei ole saavuttanut, mutta valitut ovat sen saavuttaneet; muut ovat paatuneet,'),
(1697148,58,45,11,8,'niinkuin kirjoitettu on: "Jumala on antanut heille uneliaisuuden hengen, silmät, etteivät he näkisi, ja korvat, etteivät he kuulisi, tähän päivään asti".'),
(1697149,58,45,11,9,'Ja Daavid sanoo: "Tulkoon heidän pöytänsä heille paulaksi ja ansaksi ja lankeemukseksi ja kostoksi,'),
(1697150,58,45,11,10,'soetkoot heidän silmänsä, etteivät he näkisi; ja paina yhäti heidän selkänsä kumaraan".'),
(1697151,58,45,11,11,'Minä siis sanon: eivät kaiketi he ole sitä varten kompastuneet, että lankeaisivat? Pois se! Vaan heidän lankeemuksensa kautta tuli pelastus pakanoille, että he itse syttyisivät kiivauteen.'),
(1697152,58,45,11,12,'Mutta jos heidän lankeemuksensa on maailmalle rikkaudeksi ja heidän vajautensa pakanoille rikkaudeksi, kuinka paljoa enemmän heidän täyteytensä!'),
(1697153,58,45,11,13,'Teille, pakanoille, minä sanon: Koska olen pakanain apostoli, pidän minä virkaani kunniassa,'),
(1697154,58,45,11,14,'sytyttääkseni, jos mahdollista, kiivauteen niitä, jotka ovat minun heimolaisiani, ja pelastaakseni edes muutamia heistä.'),
(1697155,58,45,11,15,'Sillä jos heidän hylkäämisensä on maailmalle sovitukseksi, mitä heidän armoihin-ottamisensa on muuta kuin elämä kuolleista?'),
(1697156,58,45,11,16,'Mutta jos uutisleipä on pyhä, niin on myös koko taikina, ja jos juuri on pyhä, niin ovat myös oksat.'),
(1697157,58,45,11,17,'Mutta jos muutamat oksista ovat taitetut pois ja sinä, joka olet metsäöljypuu, olet oksastettu oikeiden oksien joukkoon ja olet päässyt niiden kanssa osalliseksi öljypuun mehevästä juuresta,'),
(1697158,58,45,11,18,'niin älä ylpeile oksien rinnalla; mutta jos ylpeilet, niin et sinä kuitenkaan kannata juurta, vaan juuri kannattaa sinua.'),
(1697159,58,45,11,19,'Sinä kaiketi sanonet: "Ne oksat taitettiin pois, että minut oksastettaisiin".'),
(1697160,58,45,11,20,'Oikein; epäuskonsa tähden ne taitettiin pois, mutta sinä pysyt uskosi kautta. Älä ole ylpeä, vaan pelkää.'),
(1697161,58,45,11,21,'Sillä jos Jumala ei ole säästänyt luonnollisia oksia, ei hän ole säästävä sinuakaan.'),
(1697162,58,45,11,22,'Katso siis Jumalan hyvyyttä ja ankaruutta: Jumalan ankaruutta langenneita kohtaan, mutta hänen hyvyyttänsä sinua kohtaan, jos hänen hyvyydessänsä pysyt; muutoin sinutkin hakataan pois.'),
(1697163,58,45,11,23,'Mutta nuo toisetkin, jos eivät jää epäuskoonsa, tulevat oksastettaviksi, sillä Jumala on voimallinen oksastamaan ne jälleen.'),
(1697164,58,45,11,24,'Sillä jos sinä olet leikattu luonnollisesta metsäöljypuusta ja vasten luontoa oksastettu jaloon öljypuuhun, kuinka paljoa ennemmin nämä luonnolliset oksat tulevat oksastettaviksi omaan öljypuuhunsa!'),
(1697165,58,45,11,25,'Sillä minä en tahdo, veljet - ettette olisi oman viisautenne varassa - pitää teitä tietämättöminä tästä salaisuudesta, että Israelia on osaksi kohdannut paatumus - hamaan siihen asti, kunnes pakanain täysi luku on sisälle tullut,'),
(1697166,58,45,11,26,'ja niin kaikki Israel on pelastuva, niinkuin kirjoitettu on: "Siionista on tuleva pelastaja, hän poistaa jumalattoman menon Jaakobista.'),
(1697167,58,45,11,27,'Ja tämä on oleva minun liittoni heidän kanssaan, kun minä otan pois heidän syntinsä."'),
(1697168,58,45,11,28,'Evankeliumin kannalta he kyllä ovat vihollisia teidän tähtenne, mutta valinnan kannalta he ovat rakastettuja isien tähden.'),
(1697169,58,45,11,29,'Sillä ei Jumala armolahjojansa ja kutsumistansa kadu.'),
(1697170,58,45,11,30,'Samoin kuin te ennen olitte Jumalalle tottelemattomia, mutta nyt olette saaneet laupeuden näiden tottelemattomuuden kautta,'),
(1697171,58,45,11,31,'samoin nämäkin nyt ovat olleet tottelemattomia, että myös he teille tulleen armahtamisen kautta nyt saisivat laupeuden.'),
(1697172,58,45,11,32,'Sillä Jumala on sulkenut kaikki tottelemattomuuteen, että hän kaikkia armahtaisi.'),
(1697173,58,45,11,33,'Oi sitä Jumalan rikkauden ja viisauden ja tiedon syvyyttä! Kuinka tutkimattomat ovat hänen tuomionsa ja käsittämättömät hänen tiensä!'),
(1697174,58,45,11,34,'Sillä kuka on tuntenut Herran mielen? Tai kuka on ollut hänen neuvonantajansa?'),
(1697175,58,45,11,35,'Tai kuka on ensin antanut hänelle jotakin, joka olisi tälle korvattava?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697176,58,45,11,36,'Sillä hänestä ja hänen kauttansa ja häneen on kaikki; hänelle kunnia iankaikkisesti! Amen.'),
(1697177,58,45,12,1,'Niin minä Jumalan armahtavan laupeuden kautta kehoitan teitä, veljet, antamaan ruumiinne eläväksi, pyhäksi, Jumalalle otolliseksi uhriksi; tämä on teidän järjellinen jumalanpalveluksenne.'),
(1697178,58,45,12,2,'Älkääkä mukautuko tämän maailmanajan mukaan, vaan muuttukaa mielenne uudistuksen kautta, tutkiaksenne, mikä on Jumalan tahto, mikä hyvää ja otollista ja täydellistä.'),
(1697179,58,45,12,3,'Sillä sen armon kautta, mikä minulle on annettu, minä sanon teille jokaiselle, ettei tule ajatella itsestänsä enempää, kuin ajatella sopii, vaan ajatella kohtuullisesti, sen uskonmäärän mukaan, minkä Jumala on kullekin suonut.'),
(1697180,58,45,12,4,'Sillä niinkuin meillä yhdessä ruumiissa on monta jäsentä, mutta kaikilla jäsenillä ei ole sama tehtävä,'),
(1697181,58,45,12,5,'niin me, vaikka meitä on monta, olemme yksi ruumis Kristuksessa, mutta itsekukin olemme toistemme jäseniä;'),
(1697182,58,45,12,6,'ja meillä on erilaisia armolahjoja sen armon mukaan, mikä meille on annettu; jos jollakin on profetoimisen lahja, käyttäköön sitä sen mukaan, kuin hänellä uskoa on;'),
(1697183,58,45,12,7,'Jos virka, pitäköön virastaan vaarin; jos joku opettaa, olkoon uskollinen opettamisessaan;'),
(1697184,58,45,12,8,'jos kehoittaa, niin kehoittamisessaan; joka antaa, antakoon vakaasta sydämestä; joka on johtaja, johtakoon toimellisesti; joka laupeutta harjoittaa, tehköön sen iloiten.'),
(1697185,58,45,12,9,'Olkoon rakkaus vilpitön, kammokaa pahaa, riippukaa hyvässä kiinni.'),
(1697186,58,45,12,10,'Olkaa veljellisessä rakkaudessa helläsydämiset toisianne kohtaan; toinen toisenne kunnioittamisessa kilpailkaa keskenänne.'),
(1697187,58,45,12,11,'Älkää harrastuksessanne olko veltot; olkaa hengessä palavat; palvelkaa Herraa.'),
(1697188,58,45,12,12,'Olkaa toivossa iloiset, ahdistuksessa kärsivälliset, rukouksessa kestävät.'),
(1697189,58,45,12,13,'Pitäkää pyhien tarpeet ominanne; harrastakaa vieraanvaraisuutta.'),
(1697190,58,45,12,14,'Siunatkaa vainoojianne, siunatkaa, älkääkä kirotko.'),
(1697191,58,45,12,15,'Iloitkaa iloitsevien kanssa, itkekää itkevien kanssa.'),
(1697192,58,45,12,16,'Olkaa keskenänne yksimieliset. Älkää korkeita mielitelkö, vaan tyytykää alhaisiin oloihin. Älkää olko itsemielestänne viisaita.'),
(1697193,58,45,12,17,'Älkää kenellekään pahaa pahalla kostako. Ahkeroikaa sitä, mikä on hyvää kaikkien ihmisten edessä.'),
(1697194,58,45,12,18,'Jos mahdollista on ja mikäli teistä riippuu, eläkää rauhassa kaikkien ihmisten kanssa.'),
(1697195,58,45,12,19,'Älkää itse kostako, rakkaani, vaan antakaa sijaa Jumalan vihalle, sillä kirjoitettu on: "Minun on kosto, minä olen maksava, sanoo Herra".'),
(1697196,58,45,12,20,'Vaan "jos vihamiehelläsi on nälkä, ruoki häntä, jos hänellä on jano, juota häntä, sillä näin tehden sinä kokoat tulisia hiiliä hänen päänsä päälle".'),
(1697197,58,45,12,21,'Älä anna pahan itseäsi voittaa, vaan voita sinä paha hyvällä.'),
(1697198,58,45,13,1,'Jokainen olkoon alamainen sille esivallalle, jonka vallan alla hän on. Sillä ei ole esivaltaa muutoin kuin Jumalalta; ne, jotka ovat, ovat Jumalan asettamat.'),
(1697199,58,45,13,2,'Sentähden, joka asettuu esivaltaa vastaan, se nousee Jumalan säätämystä vastaan; mutta jotka nousevat vastaan, tuottavat itsellensä tuomion.'),
(1697200,58,45,13,3,'Sillä hallitusmiehet eivät ole niiden pelkona, jotka tekevät hyvää, vaan niiden, jotka tekevät pahaa. Jos siis tahdot olla esivaltaa pelkäämättä, niin tee sitä, mikä hyvää on, ja sinä saat siltä kiitoksen;'),
(1697201,58,45,13,4,'sillä se on Jumalan palvelija, sinulle hyväksi. Mutta jos pahaa teet, niin pelkää; sillä se ei miekkaa turhaan kanna, koska se on Jumalan palvelija, kostaja sen rankaisemiseksi, joka pahaa tekee.'),
(1697202,58,45,13,5,'Siksi tulee olla alamainen, ei ainoastaan rangaistuksen tähden, vaan myös omantunnon tähden.'),
(1697203,58,45,13,6,'Sentähdenhän te verojakin maksatte. Sillä he ovat Jumalan palvelusmiehiä, ahkeroiden virassansa juuri sitä varten.'),
(1697204,58,45,13,7,'Antakaa kaikille, mitä annettava on: kenelle vero, sille vero, kenelle tulli, sille tulli, kenelle pelko, sille pelko, kenelle kunnia, sille kunnia.'),
(1697205,58,45,13,8,'Älkää olko kenellekään mitään velkaa, muuta kuin että toisianne rakastatte; sillä joka toistansa rakastaa, se on lain täyttänyt.'),
(1697206,58,45,13,9,'Sillä nämä: "Älä tee huorin, älä tapa, älä varasta, älä himoitse", ja mikä muu käsky tahansa, ne sisältyvät kaikki tähän sanaan: "Rakasta lähimmäistäsi niinkuin itseäsi".'),
(1697207,58,45,13,10,'Rakkaus ei tee lähimmäiselle mitään pahaa. Sentähden on rakkaus lain täyttämys.'),
(1697208,58,45,13,11,'Ja tehkää tämä, koska tunnette tämän ajan, että jo on hetki teidän unesta nousta; sillä pelastus on nyt meitä lähempänä kuin silloin, kun uskoon tulimme.'),
(1697209,58,45,13,12,'Yö on pitkälle kulunut, ja päivä on lähellä. Pankaamme sentähden pois pimeyden teot, ja pukeutukaamme valkeuden varuksiin.'),
(1697210,58,45,13,13,'Vaeltakaamme säädyllisesti, niin kuin päivällä, ei mässäyksissä ja juomingeissa, ei haureudessa ja irstaudessa, ei riidassa ja kateudessa,'),
(1697211,58,45,13,14,'vaan pukekaa päällenne Herra Jeesus Kristus, älkääkä niin pitäkö lihastanne huolta, että himot heräävät.'),
(1697212,58,45,14,1,'Heikkouskoista hoivatkaa, rupeamatta väittelemään mielipiteistä.'),
(1697213,58,45,14,2,'Toinen uskoo saavansa syödä kaikkea, mutta toinen, joka on heikko, syö vihanneksia.'),
(1697214,58,45,14,3,'Joka syö, älköön halveksiko sitä, joka ei syö; ja joka ei syö, älköön tuomitko sitä, joka syö, sillä Jumala on ottanut hänet hoivaansa.'),
(1697215,58,45,14,4,'Mikä sinä olet tuomitsemaan toisen palvelijaa? Oman isäntänsä edessä hän seisoo tai kaatuu; mutta hän on pysyvä pystyssä, sillä Herra on voimallinen hänet pystyssä pitämään.'),
(1697216,58,45,14,5,'Toinen pitää yhden päivän toista parempana, toinen pitää kaikki päivät yhtä hyvinä; kukin olkoon omassa mielessään täysin varma.'),
(1697217,58,45,14,6,'Joka valikoi päiviä, se valikoi Herran tähden; ja joka syö, se syö Herran tähden, sillä hän kiittää Jumalaa; ja joka ei syö, se on Herran tähden syömättä ja kiittää Jumalaa.'),
(1697218,58,45,14,7,'Sillä ei kukaan meistä elä itsellensä, eikä kukaan kuole itsellensä.'),
(1697219,58,45,14,8,'Jos me elämme, niin elämme Herralle, ja jos kuolemme, niin kuolemme Herralle. Sentähden, elimmepä tai kuolimme, niin me olemme Herran omat.'),
(1697220,58,45,14,9,'Sillä sitä varten Kristus kuoli ja heräsi eloon, että hän olisi sekä kuolleitten että elävien Herra.'),
(1697221,58,45,14,10,'Mutta sinä, minkätähden sinä tuomitset veljeäsi? Taikka sinä toinen, minkätähden sinä halveksit veljeäsi? Sillä kaikki meidät asetetaan Jumalan tuomioistuimen eteen.'),
(1697222,58,45,14,11,'Sillä kirjoitettu on: "Niin totta kuin minä elän, sanoo Herra, minun edessäni pitää jokaisen polven notkistuman ja jokaisen kielen ylistämän Jumalaa".'),
(1697223,58,45,14,12,'Niin on siis meidän jokaisen tehtävä Jumalalle tili itsestämme.'),
(1697224,58,45,14,13,'Älkäämme siis enää toisiamme tuomitko, vaan päättäkää pikemmin olla panematta veljenne eteen loukkauskiveä tai langetusta.'),
(1697225,58,45,14,14,'Minä tiedän ja olen varma Herrassa Jeesuksessa, ettei mikään ole epäpyhää itsessään; vaan ainoastaan sille, joka pitää jotakin epäpyhänä, sille se on epäpyhää.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697226,58,45,14,15,'Mutta jos veljesi tulee murheelliseksi ruokasi tähden, niin sinä et enää vaella rakkauden mukaan. Älä saata ruuallasi turmioon sitä, jonka edestä Kristus on kuollut.'),
(1697227,58,45,14,16,'Älkää siis antako sen hyvän, mikä teillä on, joutua herjattavaksi;'),
(1697228,58,45,14,17,'sillä ei Jumalan valtakunta ole syömistä ja juomista, vaan vanhurskautta ja rauhaa ja iloa Pyhässä Hengessä.'),
(1697229,58,45,14,18,'Joka tässä kohden palvelee Kristusta, se on Jumalalle otollinen ja ihmisille kelvollinen.'),
(1697230,58,45,14,19,'Niin tavoitelkaamme siis sitä, mikä edistää rauhaa ja keskinäistä rakentumistamme.'),
(1697231,58,45,14,20,'Älä ruuan tähden turmele Jumalan työtä. Kaikki tosin on puhdasta, mutta sille ihmiselle, joka syö tuntoansa loukaten, se on pahaa.'),
(1697232,58,45,14,21,'Hyvä on olla lihaa syömättä ja viiniä juomatta ja karttaa sitä, mistä veljesi loukkaantuu tai joutuu lankeemukseen tai heikoksi tulee.'),
(1697233,58,45,14,22,'Pidä sinä itselläsi Jumalan edessä se usko, mikä sinulla on. Onnellinen on se, joka ei tuomitse itseään siitä, minkä hän oikeaksi havaitsee;'),
(1697234,58,45,14,23,'mutta joka epäröi ja kuitenkin syö, on tuomittu, koska se ei tapahdu uskosta; sillä kaikki, mikä ei ole uskosta, on syntiä.'),
(1697235,58,45,15,1,'Mutta meidän, vahvojen, tulee kantaa heikkojen vajavaisuuksia, eikä elää itsellemme mieliksi.'),
(1697236,58,45,15,2,'Olkoon kukin meistä lähimmäiselleen mieliksi hänen parhaaksensa, että hän rakentuisi.'),
(1697237,58,45,15,3,'Sillä ei Kristuskaan elänyt itsellensä mieliksi, vaan niinkuin kirjoitettu on: "Niiden herjaukset, jotka sinua herjaavat, ovat sattuneet minuun".'),
(1697238,58,45,15,4,'Sillä kaikki, mikä ennen on kirjoitettu, on kirjoitettu meille opiksi, että meillä kärsivällisyyden ja Raamatun lohdutuksen kautta olisi toivo.'),
(1697239,58,45,15,5,'Mutta kärsivällisyyden ja lohdutuksen Jumala suokoon teille, että olisitte yksimieliset keskenänne, Kristuksen Jeesuksen mielen mukaan,'),
(1697240,58,45,15,6,'niin että te yksimielisesti ja yhdestä suusta ylistäisitte Jumalaa ja meidän Herramme Jeesuksen Kristuksen isää.'),
(1697241,58,45,15,7,'Hoivatkaa sentähden toinen toistanne, niinkuin Kristuskin on teidät hoivaansa ottanut Jumalan kunniaksi.'),
(1697242,58,45,15,8,'Sillä minä sanon, että Kristus on tullut ympärileikattujen palvelijaksi Jumalan totuuden tähden, vahvistaaksensa isille annetut lupaukset,'),
(1697243,58,45,15,9,'mutta että pakanat laupeuden tähden ovat ylistäneet Jumalaa, niinkuin kirjoitettu on: "Sentähden minä ylistän sinua pakanain seassa ja veisaan kiitosta sinun nimellesi".'),
(1697244,58,45,15,10,'Ja vielä on sanottu: "Riemuitkaa, te pakanat, hänen kansansa kanssa".'),
(1697245,58,45,15,11,'Ja taas: "Kiittäkää Herraa, kaikki pakanat, ja ylistäkööt häntä kaikki kansat".'),
(1697246,58,45,15,12,'Ja myös Esaias sanoo: "On tuleva Iisain juurivesa, hän, joka nousee hallitsemaan pakanoita; häneen pakanat panevat toivonsa".'),
(1697247,58,45,15,13,'Mutta toivon Jumala täyttäköön teidät kaikella ilolla ja rauhalla uskossa, niin että teillä olisi runsas toivo Pyhän Hengen voiman kautta.'),
(1697248,58,45,15,14,'Veljeni, minä kyllä olen varma teistä, että te jo ilmankin olette täynnä hyvyyttä ja kaikkinaista tietoa, niin että myös kykenette neuvomaan toinen toistanne.'),
(1697249,58,45,15,15,'Kuitenkin olen paikka paikoin jotenkin rohkeasti teille kirjoittanut, uudestaan muistuttaakseni teille näitä asioita, sen armon kautta, jonka Jumala on minulle antanut'),
(1697250,58,45,15,16,'sitä varten, että minä olisin Kristuksen Jeesuksen palvelija pakanain keskuudessa, papillisesti toimittaakseni Jumalan evankeliumin palvelusta, niin että pakanakansoista tulisi otollinen ja Pyhässä Hengessä pyhitetty uhri.'),
(1697251,58,45,15,17,'Minulla on siis kerskaukseni Kristuksessa Jeesuksessa palvellessani Jumalaa;'),
(1697252,58,45,15,18,'sillä minä en rohkene puhua mistään muusta kuin siitä, mitä Kristus, saattaakseen pakanat kuuliaisiksi, on minun kauttani vaikuttanut sanalla ja teolla,'),
(1697253,58,45,15,19,'tunnustekojen ja ihmeiden voimalla, Pyhän Hengen voimalla, niin että minä Jerusalemista ja sen ympäristöstä alkaen Illyrikoniin saakka olen suorittanut Kristuksen evankeliumin julistamisen,'),
(1697254,58,45,15,20,'ja sillä tavoin, että olen pitänyt kunnianani olla julistamatta evankeliumia siellä, missä Kristuksen nimi jo on mainittu, etten rakentaisi toisen laskemalle perustukselle,'),
(1697255,58,45,15,21,'vaan niinkuin kirjoitettu on: "Ne, joille ei ole julistettu hänestä, saavat hänet nähdä, ja jotka eivät ole kuulleet, ne ymmärtävät".'),
(1697256,58,45,15,22,'Sentähden olenkin niin usein ollut estetty tulemasta teidän tykönne.'),
(1697257,58,45,15,23,'Mutta koska minulla nyt ei enää ole tilaa näissä paikkakunnissa ja kun jo monta vuotta olen halunnut tulla teidän tykönne,'),
(1697258,58,45,15,24,'niin minä, jos milloin Hispaniaan matkustan, tulen luoksenne, sillä minä toivon sieltä kautta matkustaessani näkeväni teidät ja teidän avullanne pääseväni sinne, kunhan ensin olen vähän saanut iloita teidän seurastanne.'),
(1697259,58,45,15,25,'Mutta nyt minä matkustan Jerusalemiin viemään pyhille avustusta.'),
(1697260,58,45,15,26,'Sillä Makedonia ja Akaia ovat halunneet kerätä yhteisen lahjan niille Jerusalemin pyhille, jotka ovat köyhyydessä.'),
(1697261,58,45,15,27,'Niin he ovat halunneet, ja he ovatkin sen heille velkaa; sillä jos pakanat ovat tulleet osallisiksi heidän hengellisistä aarteistaan, niin he puolestaan ovat velvolliset auttamaan heitä maallisilla.'),
(1697262,58,45,15,28,'Kun olen tehtäväni suorittanut ja heille tämän hedelmän perille vienyt, lähden teidän kauttanne Hispaniaan;'),
(1697263,58,45,15,29,'ja minä tiedän, että tullessani teidän tykönne tulen Kristuksen täydellinen siunaus mukanani.'),
(1697264,58,45,15,30,'Mutta minä kehoitan teitä, veljet, Herramme Jeesuksen Kristuksen kautta ja Hengen rakkauden kautta auttamaan minua taistelussani, rukoilemalla minun puolestani Jumalaa,'),
(1697265,58,45,15,31,'että minä pelastuisin joutumasta Juudean uskottomien käsiin ja että Jerusalemia varten tuomani avustus olisi pyhille otollinen,'),
(1697266,58,45,15,32,'niin että minä, jos Jumala niin tahtoo, ilolla saapuisin teidän tykönne ja virkistyisin teidän seurassanne.'),
(1697267,58,45,15,33,'Rauhan Jumala olkoon kaikkien teidän kanssanne. Amen.'),
(1697268,58,45,16,1,'Minä suljen teidän suosioonne sisaremme Foiben, joka on Kenkrean seurakunnan palvelija,'),
(1697269,58,45,16,2,'että otatte hänet vastaan Herrassa, niinkuin pyhien sopii, ja autatte häntä kaikessa, missä hän teitä tarvitsee; sillä hän on ollut monelle avuksi ja myöskin minulle.'),
(1697270,58,45,16,3,'Tervehdys Priskalle ja Akylaalle, työkumppaneilleni Kristuksessa Jeesuksessa,'),
(1697271,58,45,16,4,'jotka minun henkeni puolesta ovat panneet oman kaulansa alttiiksi ja joita en ainoastaan minä kiitä, vaan myös kaikki pakanain seurakunnat,'),
(1697272,58,45,16,5,'ja seurakunnalle, joka kokoontuu heidän kodissansa. Tervehdys Epainetukselle, rakkaalleni, joka on Aasian ensi hedelmä Kristukselle.'),
(1697273,58,45,16,6,'Tervehdys Marialle, joka on nähnyt paljon vaivaa teidän tähtenne.'),
(1697274,58,45,16,7,'Tervehdys Andronikukselle ja Juniaalle, heimolaisilleni ja vankeustovereilleni, joilla on suuri arvo apostolien joukossa ja jotka jo ennen minua ovat olleet Kristuksessa.'),
(1697275,58,45,16,8,'Tervehdys Ampliatukselle, rakkaalleni Herrassa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697276,58,45,16,9,'Tervehdys Urbanukselle, meidän työtoverillemme Kristuksessa, ja Stakykselle, rakkaalleni.'),
(1697277,58,45,16,10,'Tervehdys Apelleelle, koetuksenkestäneelle Kristuksessa. Tervehdys Aristobuluksen perhekuntalaisille.'),
(1697278,58,45,16,11,'Tervehdys Herodionille, heimolaiselleni. Tervehdys Narkissuksen perhekuntalaisille, jotka ovat Herrassa.'),
(1697279,58,45,16,12,'Tervehdys Tryfainalle ja Tryfosalle, jotka ovat nähneet vaivaa Herrassa. Tervehdys Persikselle, rakkaalle sisarelle, joka on nähnyt paljon vaivaa Herrassa.'),
(1697280,58,45,16,13,'Tervehdys Rufukselle, valitulle Herrassa, ja hänen äidilleen, joka on kuin äiti minullekin.'),
(1697281,58,45,16,14,'Tervehdys Asynkritukselle, Flegonille, Hermeelle, Patrobaalle, Hermaalle ja veljille, jotka ovat heidän kanssansa.'),
(1697282,58,45,16,15,'Tervehdys Filologukselle ja Julialle, Nereukselle ja hänen sisarelleen ja Olympaalle ja kaikille pyhille, jotka ovat heidän kanssansa.'),
(1697283,58,45,16,16,'Tervehtikää toisianne pyhällä suunannolla. Kaikki Kristuksen seurakunnat tervehtivät teitä.'),
(1697284,58,45,16,17,'Mutta minä kehoitan teitä, veljet, pitämään silmällä niitä, jotka saavat aikaan erimielisyyttä ja pahennusta vastoin sitä oppia, jonka te olette saaneet; vetäytykää pois heistä.'),
(1697285,58,45,16,18,'Sillä sellaiset eivät palvele meidän Herraamme Kristusta, vaan omaa vatsaansa, ja he pettävät suloisilla sanoilla ja kauniilla puheilla vilpittömien sydämet.'),
(1697286,58,45,16,19,'Onhan teidän kuuliaisuutenne tullut kaikkien tietoon; sentähden minä iloitsen teistä, mutta minä tahtoisin teidän olevan viisaita hyvään, mutta taitamattomia pahaan.'),
(1697287,58,45,16,20,'Ja rauhan Jumala on pian musertava saatanan teidän jalkojenne alle. Herramme Jeesuksen armo olkoon teidän kanssanne.'),
(1697288,58,45,16,21,'Teitä tervehtivät Timoteus, minun työtoverini, ja heimolaiseni Lukius, Jaason ja Soosipater.'),
(1697289,58,45,16,22,'Minä Tertius, joka olen kirjoittanut tämän kirjeen, sanon teille tervehdyksen Herrassa.'),
(1697290,58,45,16,23,'Gaius, minun ja koko seurakunnan majanantaja, tervehtii teitä. Erastus, kaupungin rahainhoitaja, ja veli Kvartus tervehtivät teitä.'),
(1697291,58,45,16,24,'Herramme Jeesuksen Kristuksen armo olkoon teidän kanssanne. Amen.'),
(1697292,58,45,16,25,'Mutta hänen, joka voi teitä vahvistaa minun evankeliumini ja Jeesuksen Kristuksen saarnan mukaan, sen ilmoitetun salaisuuden mukaan, joka kautta ikuisten aikojen on ollut ilmoittamatta,'),
(1697293,58,45,16,26,'mutta joka nyt on julkisaatettu ja profeetallisten kirjoitusten kautta iankaikkisen Jumalan käskystä tiettäväksi tehty kaikille kansoille uskon kuuliaisuuden aikaansaamiseksi,'),
(1697294,58,45,16,27,'Jumalan, ainoan viisaan, olkoon kunnia Jeesuksen Kristuksen kautta, aina ja iankaikkisesti. Amen.'),
(1697295,58,46,1,1,'Paavali, Kristuksen Jeesuksen kutsuttu apostoli Jumalan tahdosta, ja veli Soostenes'),
(1697296,58,46,1,2,'Korintossa olevalle Jumalan seurakunnalle, Kristuksessa Jeesuksessa pyhitetyille, jotka ovat kutsutut ja pyhät, ynnä kaikille, jotka avuksi huutavat meidän Herramme Jeesuksen Kristuksen nimeä kaikissa paikkakunnissa, niin omissaan kuin meidänkin.'),
(1697297,58,46,1,3,'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!'),
(1697298,58,46,1,4,'Minä kiitän Jumalaani aina teidän tähtenne siitä Jumalan armosta, joka on annettu teille Kristuksessa Jeesuksessa,'),
(1697299,58,46,1,5,'että kaikessa olette rikastuneet hänessä, kaikessa puheessa ja kaikessa tiedossa,'),
(1697300,58,46,1,6,'sen mukaan kuin todistus Kristuksesta on teissä vahvistettu,'),
(1697301,58,46,1,7,'niin ettei teiltä mitään puutu missään armolahjassa, teidän odottaessanne meidän Herramme Jeesuksen Kristuksen ilmestystä.'),
(1697302,58,46,1,8,'Hän on myös vahvistava teitä loppuun asti, niin että te olette nuhteettomat meidän Herramme Jeesuksen Kristuksen päivänä.'),
(1697303,58,46,1,9,'Jumala on uskollinen, hän, jonka kautta te olette kutsutut hänen Poikansa Jeesuksen Kristuksen, meidän Herramme, yhteyteen.'),
(1697304,58,46,1,10,'Mutta minä kehoitan teitä, veljet, meidän Herramme Jeesuksen Kristuksen nimeen, että kaikki olisitte puheessa yksimieliset ettekä suvaitsisi riitaisuuksia keskuudessanne, vaan pysyisitte sovinnossa ja teillä olisi sama mieli ja sama ajatus.'),
(1697305,58,46,1,11,'Sillä Kloen perheväeltä olen saanut teistä kuulla, veljeni, että teillä on riitoja keskuudessanne.'),
(1697306,58,46,1,12,'Tarkoitan sitä, että yksi teistä sanoo: "Minä olen Paavalin puolta", toinen: "Minä Apolloksen", joku taas: "Minä Keefaan", joku vielä: "Minä Kristuksen".'),
(1697307,58,46,1,13,'Onko Kristus jaettu? Ei kaiketi Paavali ole ristiinnaulittu teidän edestänne? Vai oletteko te kastetut Paavalin nimeen?'),
(1697308,58,46,1,14,'Minä kiitän Jumalaa, etten ole kastanut teistä ketään muita kuin Krispuksen ja Gaiuksen,'),
(1697309,58,46,1,15,'niin ettei kukaan saata sanoa, että te olette minun nimeeni kastetut.'),
(1697310,58,46,1,16,'Kastoinhan tosin Stefanaankin perhekunnan; sitten en tiedä, olenko ketään muuta kastanut.'),
(1697311,58,46,1,17,'Sillä Kristus ei lähettänyt minua kastamaan, vaan evankeliumia julistamaan - ei puheen viisaudella, ettei Kristuksen risti menisi mitättömäksi.'),
(1697312,58,46,1,18,'Sillä sana rististä on hullutus niille, jotka kadotukseen joutuvat, mutta meille, jotka pelastumme, se on Jumalan voima.'),
(1697313,58,46,1,19,'Onhan kirjoitettu: "Minä hävitän viisasten viisauden, ja ymmärtäväisten ymmärryksen minä teen mitättömäksi".'),
(1697314,58,46,1,20,'Missä ovat viisaat? Missä kirjanoppineet? Missä tämän maailman älyniekat? Eikö Jumala ole tehnyt maailman viisautta hullutukseksi?'),
(1697315,58,46,1,21,'Sillä kun, Jumalan viisaudesta, maailma ei oppinut viisauden avulla tuntemaan Jumalaa, niin Jumala näki hyväksi saarnauttamansa hullutuksen kautta pelastaa ne, jotka uskovat,'),
(1697316,58,46,1,22,'koskapa juutalaiset vaativat tunnustekoja ja kreikkalaiset etsivät viisautta,'),
(1697317,58,46,1,23,'me taas saarnaamme ristiinnaulittua Kristusta, joka on juutalaisille pahennus ja pakanoille hullutus,'),
(1697318,58,46,1,24,'mutta joka niille, jotka ovat kutsutut, olkootpa juutalaisia tai kreikkalaisia, on Kristus, Jumalan voima ja Jumalan viisaus.'),
(1697319,58,46,1,25,'Sillä Jumalan hulluus on viisaampi kuin ihmiset, ja Jumalan heikkous on väkevämpi kuin ihmiset.'),
(1697320,58,46,1,26,'Sillä katsokaa, veljet, omaa kutsumistanne: ei ole monta inhimillisesti viisasta, ei monta mahtavaa, ei monta jalosukuista,'),
(1697321,58,46,1,27,'vaan sen, mikä on hulluutta maailmalle, sen Jumala valitsi saattaaksensa viisaat häpeään, ja sen, mikä on heikkoa maailmassa, sen Jumala valitsi saattaaksensa sen, mikä väkevää on, häpeään,'),
(1697322,58,46,1,28,'ja sen, mikä maailmassa on halpasukuista ja halveksittua, sen Jumala valitsi, sen, joka ei mitään ole, tehdäksensä mitättömäksi sen, joka jotakin on,'),
(1697323,58,46,1,29,'ettei mikään liha voisi kerskata Jumalan edessä.'),
(1697324,58,46,1,30,'Mutta hänestä on teidän olemisenne Kristuksessa Jeesuksessa, joka on tullut meille viisaudeksi Jumalalta ja vanhurskaudeksi ja pyhitykseksi ja lunastukseksi,'),
(1697325,58,46,1,31,'että kävisi, niinkuin kirjoitettu on: "Joka kerskaa, sen kerskauksena olkoon Herra".');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697326,58,46,2,1,'Niinpä, kun minä tulin teidän tykönne, veljet, en tullut puheen tai viisauden loistolla teille Jumalan todistusta julistamaan.'),
(1697327,58,46,2,2,'Sillä minä olin päättänyt olla teidän tykönänne tuntematta mitään muuta paitsi Jeesuksen Kristuksen, ja hänet ristiinnaulittuna.'),
(1697328,58,46,2,3,'Ja ollessani teidän tykönänne minä olin heikkouden vallassa ja pelossa ja suuressa vavistuksessa,'),
(1697329,58,46,2,4,'ja minun puheeni ja saarnani ei ollut kiehtovia viisauden sanoja, vaan Hengen ja voiman osoittamista,'),
(1697330,58,46,2,5,'ettei teidän uskonne perustuisi ihmisten viisauteen, vaan Jumalan voimaan.'),
(1697331,58,46,2,6,'Kuitenkin me puhumme viisautta täydellisten seurassa, mutta emme tämän maailman viisautta emmekä tämän maailman valtiasten, jotka kukistuvat,'),
(1697332,58,46,2,7,'vaan me puhumme salattua Jumalan viisautta, sitä kätkettyä, jonka Jumala on edeltämäärännyt ennen maailmanaikoja meidän kirkkaudeksemme,'),
(1697333,58,46,2,8,'sitä, jota ei kukaan tämän maailman valtiaista ole tuntenut - sillä jos he olisivat sen tunteneet, eivät he olisi kirkkauden Herraa ristiinnaulinneet -'),
(1697334,58,46,2,9,'vaan, niinkuin kirjoitettu on: "mitä silmä ei ole nähnyt eikä korva kuullut, mikä ei ole ihmisen sydämeen noussut ja minkä Jumala on valmistanut niille, jotka häntä rakastavat".'),
(1697335,58,46,2,10,'Mutta meille Jumala on sen ilmoittanut Henkensä kautta, sillä Henki tutkii kaikki, Jumalan syvyydetkin.'),
(1697336,58,46,2,11,'Sillä kuka ihminen tietää, mitä ihmisessä on, paitsi ihmisen henki, joka hänessä on? Samoin ei myös kukaan tiedä, mitä Jumalassa on, paitsi Jumalan Henki.'),
(1697337,58,46,2,12,'Mutta me emme ole saaneet maailman henkeä, vaan sen Hengen, joka on Jumalasta, että tietäisimme, mitä Jumala on meille lahjoittanut;'),
(1697338,58,46,2,13,'ja siitä me myös puhumme, emme inhimillisen viisauden opettamilla sanoilla, vaan Hengen opettamilla, selittäen hengelliset hengellisesti.'),
(1697339,58,46,2,14,'Mutta luonnollinen ihminen ei ota vastaan sitä, mikä Jumalan Hengen on; sillä se on hänelle hullutus, eikä hän voi sitä ymmärtää, koska se on tutkisteltava hengellisesti.'),
(1697340,58,46,2,15,'Hengellinen ihminen sitä vastoin tutkistelee kaiken, mutta häntä itseään ei kukaan kykene tutkistelemaan.'),
(1697341,58,46,2,16,'Sillä: "kuka on tullut tuntemaan Herran mielen, niin että voisi neuvoa häntä?" Mutta meillä on Kristuksen mieli.'),
(1697342,58,46,3,1,'Niinpä, veljet, minun ei käynyt puhuminen teille niinkuin hengellisille, vaan niinkuin lihallisille, niinkuin pienille lapsille Kristuksessa.'),
(1697343,58,46,3,2,'Maitoa minä juotin teille, en antanut ruokaa, sillä sitä ette silloin sietäneet, ettekä vielä nytkään siedä;'),
(1697344,58,46,3,3,'olettehan vielä lihallisia. Sillä kun keskuudessanne on kateutta ja riitaa, ettekö silloin ole lihallisia ja vaella ihmisten tavoin?'),
(1697345,58,46,3,4,'Kun toinen sanoo: "Minä olen Paavalin puolta", ja toinen: "Minä olen Apolloksen", ettekö silloin ole niinkuin ihmiset ainakin?'),
(1697346,58,46,3,5,'Mikä Apollos sitten on? Ja mikä Paavali on? Palvelijoita, joiden kautta te olette tulleet uskoviksi, palvelijoita sen kykynsä mukaan, minkä Herra on heille kullekin antanut.'),
(1697347,58,46,3,6,'Minä istutin, Apollos kasteli, mutta Jumala on antanut kasvun.'),
(1697348,58,46,3,7,'Niin ei siis istuttaja ole mitään, eikä kastelijakaan, vaan Jumala, joka kasvun antaa.'),
(1697349,58,46,3,8,'Mutta istuttaja ja kastelija ovat yhtä; kuitenkin on kumpikin saava oman palkkansa oman työnsä mukaan.'),
(1697350,58,46,3,9,'Sillä me olemme Jumalan työtovereita; te olette Jumalan viljelysmaa, olette Jumalan rakennus.'),
(1697351,58,46,3,10,'Sen Jumalan armon mukaan, joka on minulle annettu, minä olen taitavan rakentajan tavoin pannut perustuksen, ja toinen sille rakentaa, mutta katsokoon kukin, kuinka hän sille rakentaa.'),
(1697352,58,46,3,11,'Sillä muuta perustusta ei kukaan voi panna, kuin mikä pantu on, ja se on Jeesus Kristus.'),
(1697353,58,46,3,12,'Mutta jos joku rakentaa tälle perustukselle, rakensipa kullasta, hopeasta, jalokivistä, puusta, heinistä tai oljista,'),
(1697354,58,46,3,13,'niin kunkin teko on tuleva näkyviin; sillä sen on saattava ilmi se päivä, joka tulessa ilmestyy, ja tuli on koetteleva, minkälainen kunkin teko on.'),
(1697355,58,46,3,14,'Jos jonkun tekemä rakennus kestää, on hän saava palkan;'),
(1697356,58,46,3,15,'mutta jos jonkun tekemä palaa, joutuu hän vahinkoon; mutta hän itse on pelastuva, kuitenkin ikäänkuin tulen läpi.'),
(1697357,58,46,3,16,'Ettekö tiedä, että te olette Jumalan temppeli ja että Jumalan Henki asuu teissä?'),
(1697358,58,46,3,17,'Jos joku turmelee Jumalan temppelin, on Jumala turmeleva hänet; sillä Jumalan temppeli on pyhä, ja sellaisia te olette.'),
(1697359,58,46,3,18,'Älköön kukaan pettäkö itseään. Jos joku teidän joukossanne luulee olevansa viisas tässä maailmassa, tulkoon hän tyhmäksi, että hänestä tulisi viisas.'),
(1697360,58,46,3,19,'Sillä tämän maailman viisaus on hullutus Jumalan silmissä. Sillä kirjoitettu on: "Hän vangitsee viisaat heidän viekkauteensa";'),
(1697361,58,46,3,20,'ja vielä: "Herra tuntee viisasten ajatukset, hän tietää ne turhiksi".'),
(1697362,58,46,3,21,'Älköön siis kukaan kerskatko ihmisistä; sillä kaikki on teidän,'),
(1697363,58,46,3,22,'teidän on Paavali ja Apollos ja Keefas, teidän on maailma ja elämä ja kuolema, nykyiset ja tulevaiset, kaikki on teidän.'),
(1697364,58,46,3,23,'Mutta te olette Kristuksen, ja Kristus on Jumalan.'),
(1697365,58,46,4,1,'Niin pitäköön jokainen meitä Kristuksen käskyläisinä ja Jumalan salaisuuksien huoneenhaltijoina.'),
(1697366,58,46,4,2,'Sitä tässä huoneenhaltijoilta ennen muuta vaaditaan, että heidät havaitaan uskollisiksi.'),
(1697367,58,46,4,3,'Mutta siitä minä hyvin vähän välitän, että te minua tuomitsette tai joku inhimillinen oikeus; en minä itsekään tuomitse itseäni,'),
(1697368,58,46,4,4,'sillä ei minulla ole mitään tunnollani, mutta en minä silti ole vanhurskautettu, vaan minun tuomitsijani on Herra.'),
(1697369,58,46,4,5,'Älkää sentähden lausuko mitään tuomiota, ennenkuin aika on, ennenkuin Herra tulee, joka myös on saattava valoon pimeyden kätköt ja tuova ilmi sydänten aivoitukset; ja silloin kukin saa kiitoksensa Jumalalta.'),
(1697370,58,46,4,6,'Tämän olen, veljet, sovittanut itseeni ja Apollokseen, teidän tähtenne, että meistä oppisitte tämän: "Ei yli sen, mikä kirjoitettu on", ettette pöyhkeillen asettuisi mikä minkin puolelle toista vastaan.'),
(1697371,58,46,4,7,'Sillä kuka antaa sinulle etusijan? Ja mitä sinulla on, jota et ole lahjaksi saanut? Mutta jos olet sen saanut, niin miksi kerskaat, ikäänkuin se ei olisi saatua?'),
(1697372,58,46,4,8,'Te olette jo ravitut, teistä on tullut jo rikkaita, ilman meitä teistä on tullut kuninkaita! Kunpa teistä olisikin tullut kuninkaita, niin että mekin pääsisimme kuninkaiksi teidän kanssanne!'),
(1697373,58,46,4,9,'Sillä minusta näyttää, että Jumala on asettanut meidät apostolit vihoviimeisiksi, ikäänkuin kuolemaan tuomituiksi; meistä on tullut kaiken maailman katseltava, sekä enkelien että ihmisten,'),
(1697374,58,46,4,10,'me olemme houkkia Kristuksen tähden, mutta te älykkäitä Kristuksessa, me olemme heikkoja, mutta te väkeviä; te kunnioitettuja, mutta me halveksittuja.'),
(1697375,58,46,4,11,'Vielä tänäkin hetkenä me kärsimme sekä nälkää että janoa, olemme alasti, meitä piestään, ja me kuljemme kodittomina,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697376,58,46,4,12,'me näemme vaivaa tehden työtä omin käsin. Meitä herjataan, mutta me siunaamme; meitä vainotaan, mutta me kestämme;'),
(1697377,58,46,4,13,'meitä parjataan, mutta me puhumme leppeästi; meistä on tullut kuin mikäkin maailman tunkio, kaikkien hylkimiä, aina tähän päivään asti.'),
(1697378,58,46,4,14,'En kirjoita tätä häväistäkseni teitä, vaan niinkuin rakkaita lapsiani neuvoen.'),
(1697379,58,46,4,15,'Sillä vaikka teillä olisi kymmenentuhatta kasvattajaa Kristuksessa, niin ei teillä kuitenkaan ole monta isää; sillä minä teidät synnytin evankeliumin kautta Kristuksessa Jeesuksessa.'),
(1697380,58,46,4,16,'Kehoitan siis teitä: olkaa minun seuraajiani.'),
(1697381,58,46,4,17,'Juuri sentähden minä lähetin teille Timoteuksen, joka on minun rakas ja uskollinen poikani Herrassa; hän on muistuttava teitä minun vaelluksestani Kristuksessa Jeesuksessa, sen mukaan kuin minä kaikkialla, joka seurakunnassa, opetan.'),
(1697382,58,46,4,18,'Muutamat teistä ovat paisuneet pöyhkeiksi, aivan niinkuin minä en tulisikaan teidän tykönne.'),
(1697383,58,46,4,19,'Mutta minä tulen pian teidän tykönne, jos Herra tahtoo, ja silloin minä otan selon, en noiden pöyhkeiden sanoista, vaan voimasta.'),
(1697384,58,46,4,20,'Sillä Jumalan valtakunta ei ole sanoissa, vaan voimassa.'),
(1697385,58,46,4,21,'Kummanko tahdotte? Tulenko luoksenne vitsa kädessä vaiko rakkaudessa ja sävyisyyden hengessä?'),
(1697386,58,46,5,1,'Yleensä kuuluu, että teidän keskuudessanne harjoitetaan haureutta, jopa semmoista haureutta, jota ei ole pakanainkaan keskuudessa, että eräskin pitää isänsä vaimoa.'),
(1697387,58,46,5,2,'Ja te olette paisuneet pöyhkeiksi! Eikö teidän pikemminkin olisi pitänyt tulla murheellisiksi, että se, joka on tuommoisen teon tehnyt, poistettaisiin teidän keskuudestanne?'),
(1697388,58,46,5,3,'Sillä minä, joka tosin ruumiillisesti olen poissa, mutta hengessä kuitenkin läsnä, olen jo, niinkuin läsnäollen, puolestani päättänyt, että se, joka tuommoisen teon on tehnyt, on'),
(1697389,58,46,5,4,'- sittenkuin olemme, te ja minun henkeni ynnä meidän Herramme Jeesuksen voima, tulleet yhteen -'),
(1697390,58,46,5,5,'Herran Jeesuksen nimessä hyljättävä saatanan haltuun lihan turmioksi, että hänen henkensä pelastuisi Herran päivänä.'),
(1697391,58,46,5,6,'Ei ole hyvä, että kerskaatte. Ettekö tiedä, että vähäinen hapatus hapattaa koko taikinan?'),
(1697392,58,46,5,7,'Peratkaa pois vanha hapatus, että teistä tulisi uusi taikina, niinkuin te olettekin happamattomat; sillä onhan meidän pääsiäislampaamme, Kristus, teurastettu.'),
(1697393,58,46,5,8,'Viettäkäämme siis juhlaa, ei vanhassa hapatuksessa eikä ilkeyden ja pahuuden hapatuksessa, vaan puhtauden ja totuuden happamattomuudessa.'),
(1697394,58,46,5,9,'Minä kirjoitin teille kirjeessäni, ettette seurustelisi huorintekijäin kanssa;'),
(1697395,58,46,5,10,'en tarkoittanut yleensä tämän maailman huorintekijöitä tai ahneita tai anastajia tai epäjumalanpalvelijoita, sillä silloinhan teidän täytyisi lähteä pois maailmasta.'),
(1697396,58,46,5,11,'Vaan minä kirjoitin teille, että jos joku, jota kutsutaan veljeksi, on huorintekijä tai ahne tai epäjumalanpalvelija tai pilkkaaja tai juomari tai anastaja, te ette seurustelisi ettekä söisikään semmoisen kanssa.'),
(1697397,58,46,5,12,'Sillä onko minun asiani tuomita niitä, jotka ovat ulkopuolella? Ettekö tekin tuomitse vain niitä, jotka ovat sisäpuolella?'),
(1697398,58,46,5,13,'Mutta ulkopuolella olevat tuomitsee Jumala. "Poistakaa keskuudestanne se, joka on paha."'),
(1697399,58,46,6,1,'Kuinka rohkenee kukaan teistä, jolla on riita-asia toisen kanssa, käydä oikeutta vääräin edessä? Miksei pyhien edessä?'),
(1697400,58,46,6,2,'Vai ettekö tiedä, että pyhät tulevat maailman tuomitsemaan? Ja jos te tuomitsette maailman, niin ettekö kelpaa ratkaisemaan aivan vähäpätöisiä asioita?'),
(1697401,58,46,6,3,'Ettekö tiedä, että me tulemme tuomitsemaan enkeleitä, emmekö sitten maallisia asioita?'),
(1697402,58,46,6,4,'Jos teillä siis on maallisia asioita ratkaistavina, nekö te asetatte tuomareiksi, jotka ovat halveksittuja seurakunnassa?'),
(1697403,58,46,6,5,'Teidän häpeäksenne minä tämän sanon. Eikö teidän joukossanne sitten ole yhtäkään viisasta, joka voisi ratkaista veljien välin?'),
(1697404,58,46,6,6,'Vaan veli käy oikeutta veljen kanssa, vieläpä uskottomain edessä!'),
(1697405,58,46,6,7,'Teille on jo yleensä vaurioksi, että käräjöitte keskenänne. Miksi ette ennemmin salli tehdä vääryyttä itsellenne? Miksi ette ennemmin anna riistää omaanne?'),
(1697406,58,46,6,8,'Sen sijaan te itse teette vääryyttä ja riistätte toisen omaa, vieläpä veljien.'),
(1697407,58,46,6,9,'Vai ettekö tiedä, etteivät väärät saa periä Jumalan valtakuntaa? Älkää eksykö. Eivät huorintekijät, ei epäjumalanpalvelijat, ei avionrikkojat, ei hekumoitsijat eikä miehimykset,'),
(1697408,58,46,6,10,'eivät varkaat, ei ahneet, ei juomarit, ei pilkkaajat eivätkä anastajat saa periä Jumalan valtakuntaa.'),
(1697409,58,46,6,11,'Ja tuommoisia te olitte, jotkut teistä; mutta te olette vastaanottaneet peson, te olette pyhitetyt, te olette vanhurskautetut meidän Herramme Jeesuksen Kristuksen nimessä ja meidän Jumalamme Hengessä.'),
(1697410,58,46,6,12,'Kaikki on minulle luvallista, mutta ei kaikki ole hyödyksi; kaikki on minulle luvallista, mutta minä en saa antaa minkään itseäni vallita.'),
(1697411,58,46,6,13,'Ruoka on vatsaa varten ja vatsa ruokaa varten; ja Jumala on tekevä lopun niin toisesta kuin toisestakin. Mutta ruumis ei ole haureutta varten, vaan Herraa varten, ja Herra ruumista varten;'),
(1697412,58,46,6,14,'ja Jumala, joka herätti kuolleista Herran, on herättävä meidätkin voimallansa.'),
(1697413,58,46,6,15,'Ettekö tiedä, että teidän ruumiinne ovat Kristuksen jäseniä? Ottaisinko siis Kristuksen jäsenet ja tekisin ne porton jäseniksi? Pois se!'),
(1697414,58,46,6,16,'Vai ettekö tiedä, että joka yhtyy porttoon, tulee yhdeksi ruumiiksi hänen kanssaan? Onhan sanottu: "Ne kaksi tulevat yhdeksi lihaksi".'),
(1697415,58,46,6,17,'Mutta joka yhtyy Herraan, on yksi henki hänen kanssaan.'),
(1697416,58,46,6,18,'Paetkaa haureutta. Kaikki muu synti, mitä ikinä ihminen tekee, on ruumiin ulkopuolella; mutta haureuden harjoittaja tekee syntiä omaa ruumistansa vastaan.'),
(1697417,58,46,6,19,'Vai ettekö tiedä, että teidän ruumiinne on Pyhän Hengen temppeli, joka Henki teissä on ja jonka te olette saaneet Jumalalta, ja ettette ole itsenne omat?'),
(1697418,58,46,6,20,'Sillä te olette kalliisti ostetut. Kirkastakaa siis Jumala ruumiissanne.'),
(1697419,58,46,7,1,'Mutta mitä siihen tulee, mistä kirjoititte, niin hyvä on miehelle olla naiseen ryhtymättä;'),
(1697420,58,46,7,2,'mutta haureuden syntien välttämiseksi olkoon kullakin miehellä oma vaimonsa, ja kullakin naisella aviomiehensä.'),
(1697421,58,46,7,3,'Täyttäköön mies velvollisuutensa vaimoansa kohtaan, ja samoin vaimo miestänsä kohtaan.'),
(1697422,58,46,7,4,'Vaimon ruumis ei ole hänen omassa, vaan hänen miehensä vallassa; samoin ei miehenkään ruumis ole hänen omassa, vaan vaimon vallassa.'),
(1697423,58,46,7,5,'Älkää vetäytykö pois toisistanne, paitsi ehkä keskinäisestä sopimuksesta joksikin ajaksi, niin että olisitte vapaat rukoukseen ja sitten taas tulisitte yhteen, ettei saatana teitä kiusaisi teidän hillittömyytenne tähden.'),
(1697424,58,46,7,6,'Mutta tämän minä sanon myönnytyksenä, en käskynä.'),
(1697425,58,46,7,7,'Soisin kaikkien ihmisten olevan niinkuin minäkin; mutta kullakin on oma lahjansa Jumalalta, yhdellä yksi, toisella toinen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697426,58,46,7,8,'Naimattomille ja leskille minä taas sanon: heille on hyvä, jos pysyvät sellaisina kuin minäkin;'),
(1697427,58,46,7,9,'mutta jos eivät voi itseään hillitä, niin menkööt naimisiin; sillä parempi on naida kuin palaa.'),
(1697428,58,46,7,10,'Mutta naimisissa oleville minä julistan, en kuitenkaan minä, vaan Herra, ettei vaimo saa erota miehestään;'),
(1697429,58,46,7,11,'mutta jos hän eroaa, niin pysyköön naimatonna tai sopikoon miehensä kanssa; eikä mies saa hyljätä vaimoansa.'),
(1697430,58,46,7,12,'Mutta muille sanon minä, eikä Herra: jos jollakin veljellä on vaimo, joka ei usko, ja tämä suostuu asumaan hänen kanssaan, niin älköön mies häntä hyljätkö;'),
(1697431,58,46,7,13,'samoin älköön vaimokaan, jos hänellä on mies, joka ei usko, ja tämä suostuu asumaan hänen kanssaan, hyljätkö miestänsä.'),
(1697432,58,46,7,14,'Sillä mies, joka ei usko, on pyhitetty vaimonsa kautta, ja vaimo, joka ei usko, on pyhitetty miehensä, uskonveljen, kautta; muutoinhan teidän lapsenne olisivat saastaisia, mutta nyt he ovat pyhiä.'),
(1697433,58,46,7,15,'Mutta jos se, joka ei usko, eroaa, niin erotkoon; veli ja sisar eivät ole semmoisissa tapauksissa orjuutetut; sillä rauhaan on Jumala teidät kutsunut.'),
(1697434,58,46,7,16,'Sillä mistä tiedät, vaimo, voitko pelastaa miehesi? Tai mistä tiedät, mies, voitko pelastaa vaimosi?'),
(1697435,58,46,7,17,'Vaeltakoon vain kukin sen mukaan, kuin Herra on hänelle hänen osansa antanut, ja siinä asemassa, missä hänet Jumala on kutsunut; näin minä säädän kaikissa seurakunnissa.'),
(1697436,58,46,7,18,'Jos joku on kutsuttu ympärileikattuna, älköön hän pyrkikö ympärileikkaamattomaksi; jos joku on kutsuttu ympärileikkaamatonna, älköön ympärileikkauttako itseään.'),
(1697437,58,46,7,19,'Ei ympärileikkaus ole mitään, eikä ympärileikkaamattomuus ole mitään, vaan Jumalan käskyjen pitäminen.'),
(1697438,58,46,7,20,'Pysyköön kukin siinä asemassa, missä hänet on kutsuttu.'),
(1697439,58,46,7,21,'Jos olet kutsuttu orjana, älä siitä murehdi; mutta vaikka voisitkin päästä vapaaksi, niin ole ennemmin siinä osassasi.'),
(1697440,58,46,7,22,'Sillä joka orjana on kutsuttu Herrassa, on Herran vapaa; samoin vapaana kutsuttu on Kristuksen orja.'),
(1697441,58,46,7,23,'Te olette kalliisti ostetut; älkää olko ihmisten orjia.'),
(1697442,58,46,7,24,'Pysyköön kukin, veljet, Jumalan edessä siinä asemassa, missä hänet on kutsuttu.'),
(1697443,58,46,7,25,'Mutta neitsyistä minulla ei ole Herran käskyä, vaan minä sanon ajatukseni niinkuin se, joka on Herralta saanut sen laupeuden, että hän on luotettava.'),
(1697444,58,46,7,26,'Olen siis sitä mieltä, että lähestyvän ahdingon tähden jokaisen on hyvä pysyä entisellään.'),
(1697445,58,46,7,27,'Jos olet sidottu vaimoon, älä pyydä eroa; jos et ole sidottu vaimoon, älä pyydä itsellesi vaimoa.'),
(1697446,58,46,7,28,'Mutta jos menetkin naimisiin, et syntiä tee; ja jos neitsyt menee naimisiin, ei hänkään tee syntiä; mutta ne, jotka niin tekevät, joutuvat kärsimään ruumiillista vaivaa, ja siitä minä tahtoisin teidät säästää.'),
(1697447,58,46,7,29,'Mutta sen minä sanon, veljet: aika on lyhyt; olkoot tästedes nekin, joilla on vaimot, niinkuin ei heillä niitä olisikaan,'),
(1697448,58,46,7,30,'ja ne, jotka itkevät, niinkuin eivät itkisi, ja ne, jotka iloitsevat, niinkuin eivät iloitsisi, ja ne, jotka ostavat, niinkuin eivät saisi omanansa pitää,'),
(1697449,58,46,7,31,'ja ne, jotka tätä maailmaa hyödyksensä käyttävät, niinkuin eivät sitä käyttäisi; sillä tämän maailman muoto on katoamassa.'),
(1697450,58,46,7,32,'Soisin, ettei teillä olisi huolia. Naimaton mies huolehtii siitä, mikä on Herran, kuinka olisi Herralle mieliksi;'),
(1697451,58,46,7,33,'mutta nainut huolehtii maailmallisista, kuinka olisi vaimolleen mieliksi,'),
(1697452,58,46,7,34,'ja hänen harrastuksensa käy kahtaanne. Samoin vaimo, jolla ei enää ole miestä, ja neitsyt huolehtivat siitä, mikä on Herran, että olisivat pyhät sekä ruumiin että hengen puolesta; mutta naimisissa oleva huolehtii maailmallisista, kuinka olisi mieliksi miehellensä.'),
(1697453,58,46,7,35,'Tämän minä sanon teidän omaksi hyödyksenne, en pannakseni kytkyttä kaulaanne, vaan sitä varten, että eläisitte säädyllisesti ja häiriytymättä pysyisitte Herrassa.'),
(1697454,58,46,7,36,'Mutta jos joku arvelee tekevänsä väärin tytärtänsä kohtaan, joka on täydessä naima-iässä, ja jos kerran sen pitää tapahtua, niin tehköön, niinkuin tahtoo; ei hän syntiä tee: menkööt naimisiin.'),
(1697455,58,46,7,37,'Joka taas pysyy sydämessään lujana eikä ole minkään pakon alainen, vaan voi noudattaa omaa tahtoansa ja on sydämessään päättänyt pitää tyttärensä naimattomana, se tekee hyvin.'),
(1697456,58,46,7,38,'Siis, joka naittaa tyttärensä, tekee hyvin, ja joka ei naita, tekee paremmin.'),
(1697457,58,46,7,39,'Vaimo on sidottu, niin kauan kuin hänen miehensä elää, mutta jos mies kuolee, on hän vapaa menemään naimisiin, kenen kanssa tahtoo, kunhan se vain tapahtuu Herrassa.'),
(1697458,58,46,7,40,'Mutta hän on onnellisempi, jos pysyy entisellään; se on minun mielipiteeni, ja minä luulen, että minullakin on Jumalan Henki.'),
(1697459,58,46,8,1,'Mitä sitten epäjumalille uhrattuun lihaan tulee, niin tiedämme, että meillä kaikilla on tieto. Tieto paisuttaa, mutta rakkaus rakentaa.'),
(1697460,58,46,8,2,'Jos joku luulee jotakin tietävänsä, ei hän vielä tiedä, niinkuin tietää tulee;'),
(1697461,58,46,8,3,'mutta joka rakastaa Jumalaa, sen Jumala tuntee.'),
(1697462,58,46,8,4,'Mitä nyt epäjumalille uhratun lihan syömiseen tulee, niin tiedämme, ettei maailmassa ole yhtään epäjumalaa ja ettei ole muuta Jumalaa kuin yksi.'),
(1697463,58,46,8,5,'Sillä vaikka olisikin niin sanottuja jumalia, olipa heitä sitten taivaassa tai maassa, ja niitä on paljon semmoisia jumalia ja herroja,'),
(1697464,58,46,8,6,'niin on meillä kuitenkin ainoastaan yksi Jumala, Isä, josta kaikki on ja johon me olemme luodut, ja yksi Herra, Jeesus Kristus, jonka kautta kaikki on, niin myös me hänen kauttansa.'),
(1697465,58,46,8,7,'Mutta ei ole kaikilla tätä tietoa, vaan tottumuksesta epäjumaliin muutamat vielä nytkin syövät uhrilihaa ikäänkuin epäjumalille uhrattuna, ja heidän omatuntonsa, joka on heikko, tahraantuu siitä.'),
(1697466,58,46,8,8,'Mutta ruoka ei lähennä meitä Jumalaan; jos olemme syömättä, emme siitä vahingoitu; jos syömme, emme siitä hyödy.'),
(1697467,58,46,8,9,'Katsokaa kuitenkin, ettei tämä vapautenne koidu heikoille loukkaukseksi.'),
(1697468,58,46,8,10,'Sillä jos joku näkee sinun, jolla on tieto, aterioivan epäjumalan huoneessa, eikö hänen omatuntonsa, kun hän on heikko, vahvistu epäjumalille uhratun syömiseen?'),
(1697469,58,46,8,11,'Sinun tietosi kautta turmeltuu silloin tuo heikko, sinun veljesi, jonka tähden Kristus on kuollut.'),
(1697470,58,46,8,12,'Mutta kun te näin teette syntiä veljiä vastaan ja haavoitatte heidän heikkoa omaatuntoaan, niin teette syntiä Kristusta vastaan.'),
(1697471,58,46,8,13,'Sentähden, jos ruoka on viettelykseksi veljelleni, en minä ikinä enää syö lihaa, etten olisi viettelykseksi veljelleni.'),
(1697472,58,46,9,1,'Enkö minä ole vapaa? Enkö minä ole apostoli? Enkö ole nähnyt Jeesusta, meidän Herraamme? Ettekö te ole minun tekoni Herrassa?'),
(1697473,58,46,9,2,'Jos en olekaan apostoli muille, olen ainakin teille; sillä te olette minun apostolinvirkani sinetti Herrassa.'),
(1697474,58,46,9,3,'Tämä on minun puolustukseni niitä vastaan, jotka asettuvat minua tutkimaan.'),
(1697475,58,46,9,4,'Eikö meillä olisi oikeus saada ruokamme ja juomamme?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697476,58,46,9,5,'Eikö meillä olisi oikeus kuljettaa muassamme vaimoa, uskonsisarta, niinkuin muutkin apostolit ja Herran veljet ja Keefas tekevät?'),
(1697477,58,46,9,6,'Vai ainoastaanko minulla ja Barnabaalla ei ole oikeutta olla ruumiillista työtä tekemättä?'),
(1697478,58,46,9,7,'Kuka tekee koskaan sotapalvelusta omalla kustannuksellaan? Kuka istuttaa viinitarhan, eikä syö sen hedelmää? Tai kuka kaitsee karjaa, eikä nauti karjansa maitoa?'),
(1697479,58,46,9,8,'Puhunko tätä vain ihmisten tavalla? Eikö myös laki sano samaa?'),
(1697480,58,46,9,9,'Onhan Mooseksen laissa kirjoitettuna: "Älä sido puivan härän suuta". Eihän Jumala häristä näin huolta pitäne?'),
(1697481,58,46,9,10,'Eikö hän sano sitä kaiketikin meidän tähtemme? Meidän tähtemmehän on kirjoitettu, että kyntäjän tulee kyntää toivossa ja puivan puida osansa saamisen toivossa.'),
(1697482,58,46,9,11,'Jos me olemme kylväneet teille hengellistä hyvää, onko paljon, jos me niitämme teiltä aineellista?'),
(1697483,58,46,9,12,'Jos muilla on teihin tällainen oikeus, eikö paljoa enemmän meillä? Mutta me emme ole käyttäneet tätä oikeutta, vaan kestämme kaikki, ettemme panisi mitään estettä Kristuksen evankeliumille.'),
(1697484,58,46,9,13,'Ettekö tiedä, että ne, jotka hoitavat pyhäkön toimia, saavat ravintonsa pyhäköstä, ja jotka ovat asetetut uhrialttarin palvelukseen, saavat osansa silloin kuin alttarikin?'),
(1697485,58,46,9,14,'Samoin myös Herra on säätänyt, että evankeliumin julistajain tulee saada evankeliumista elatuksensa.'),
(1697486,58,46,9,15,'Mutta minä en ole ainoatakaan näistä oikeuksistani hyväkseni käyttänyt. Enkä kirjoitakaan tätä siinä tarkoituksessa, että niitä minuun sovitettaisiin, sillä mieluummin minä kuolen. Ei kukaan ole minun kerskaustani tyhjäksi tekevä.'),
(1697487,58,46,9,16,'Sillä siitä, että julistan evankeliumia, ei minulla ole kerskaamista; minun täytyy se tehdä. Voi minua, ellen evankeliumia julista!'),
(1697488,58,46,9,17,'Sillä jos vapaasta tahdostani sitä teen, niin minulla on palkka; mutta jos en tee sitä vapaasta tahdostani, niin on huoneenhaltijan toimi kuitenkin minulle uskottu.'),
(1697489,58,46,9,18,'Mikä siis on minun palkkani? Se, että kun julistan evankeliumia, teen sen ilmaiseksi, niin etten käytä oikeutta, jonka evankeliumi minulle myöntää.'),
(1697490,58,46,9,19,'Sillä vaikka minä olen riippumaton kaikista, olen tehnyt itseni kaikkien palvelijaksi, voittaakseni niin monta kuin suinkin,'),
(1697491,58,46,9,20,'ja olen ollut juutalaisille ikäänkuin juutalainen, voittaakseni juutalaisia; lain alaisille ikäänkuin lain alainen, vaikka itse en ole lain alainen, voittaakseni lain alaiset;'),
(1697492,58,46,9,21,'ilman lakia oleville ikäänkuin olisin ilman lakia - vaikka en ole ilman Jumalan lakia, vaan olen Kristuksen laissa - voittaakseni ne, jotka ovat ilman lakia;'),
(1697493,58,46,9,22,'heikoille minä olen ollut heikko, voittaakseni heikot; kaikille minä olen ollut kaikkea, pelastaakseni edes muutamia.'),
(1697494,58,46,9,23,'Mutta kaiken minä teen evankeliumin tähden, että minäkin tulisin siitä osalliseksi.'),
(1697495,58,46,9,24,'Ettekö tiedä, että jotka kilparadalla juoksevat, ne tosin kaikki juoksevat, mutta yksi saa voittopalkinnon? Juoskaa niinkuin hän, että sen saavuttaisitte.'),
(1697496,58,46,9,25,'Mutta jokainen kilpailija noudattaa itsensähillitsemistä kaikessa; he saadakseen vain katoavaisen seppeleen, mutta me katoamattoman.'),
(1697497,58,46,9,26,'Minä en siis juokse umpimähkään, en taistele niinkuin ilmaan hosuen,'),
(1697498,58,46,9,27,'vaan minä kuritan ruumistani ja masennan sitä, etten minä, joka muille saarnaan, itse ehkä joutuisi hyljättäväksi.'),
(1697499,58,46,10,1,'Sillä minä en tahdo, veljet, pitää teitä tietämättöminä siitä, että isämme olivat kaikki pilven alla ja kulkivat kaikki meren läpi'),
(1697500,58,46,10,2,'ja saivat kaikki kasteen Moosekseen pilvessä ja meressä'),
(1697501,58,46,10,3,'ja söivät kaikki samaa hengellistä ruokaa'),
(1697502,58,46,10,4,'ja joivat kaikki samaa hengellistä juomaa. Sillä he joivat hengellisestä kalliosta, joka heitä seurasi; ja se kallio oli Kristus.'),
(1697503,58,46,10,5,'Mutta useimpiin heistä Jumala ei mielistynyt, koskapa he hukkuivat erämaassa.'),
(1697504,58,46,10,6,'Tämä tapahtui varoittavaksi esimerkiksi meille, että me emme pahaa himoitsisi, niinkuin he himoitsivat.'),
(1697505,58,46,10,7,'Älkää myöskään ruvetko epäjumalanpalvelijoiksi kuten muutamat heistä, niinkuin kirjoitettu on: "Kansa istui syömään ja juomaan, ja he nousivat iloa pitämään".'),
(1697506,58,46,10,8,'Älkäämmekä harjoittako haureutta, niinkuin muutamat heistä haureutta harjoittivat, ja heitä kaatui yhtenä päivänä kaksikymmentä kolme tuhatta.'),
(1697507,58,46,10,9,'Älkäämme myöskään kiusatko Herraa, niinkuin muutamat heistä kiusasivat ja saivat käärmeiltä surmansa.'),
(1697508,58,46,10,10,'Älkääkä napisko, niinkuin muutamat heistä napisivat ja saivat surmansa tuhoojalta.'),
(1697509,58,46,10,11,'Tämä, mikä tapahtui heille, on esikuvallista ja on kirjoitettu varoitukseksi meille, joille maailmanaikojen loppukausi on tullut.'),
(1697510,58,46,10,12,'Sentähden, joka luulee seisovansa, katsokoon, ettei lankea.'),
(1697511,58,46,10,13,'Teitä ei ole kohdannut muu kuin inhimillinen kiusaus; ja Jumala on uskollinen, hän ei salli teitä kiusattavan yli voimienne, vaan salliessaan kiusauksen hän valmistaa myös pääsyn siitä, niin että voitte sen kestää.'),
(1697512,58,46,10,14,'Sentähden, rakkaani, paetkaa epäjumalanpalvelusta.'),
(1697513,58,46,10,15,'Minä puhun niinkuin ymmärtäväisille; arvostelkaa itse, mitä minä sanon.'),
(1697514,58,46,10,16,'Siunauksen malja, jonka me siunaamme, eikö se ole osallisuus Kristuksen vereen? Se leipä, jonka murramme, eikö se ole osallisuus Kristuksen ruumiiseen?'),
(1697515,58,46,10,17,'Koska leipä on yksi, niin me monet olemme yksi ruumis; sillä me olemme kaikki tuosta yhdestä leivästä osalliset.'),
(1697516,58,46,10,18,'Katsokaa luonnollista Israelia; eivätkö ne, jotka syövät uhreja, ole alttarista osalliset?'),
(1697517,58,46,10,19,'Mitä siis sanon? Ettäkö epäjumalanuhri on jotakin, tai että epäjumala on jotakin?'),
(1697518,58,46,10,20,'Ei, vaan että, mitä pakanat uhraavat, sen he uhraavat riivaajille eivätkä Jumalalle; mutta minä en tahdo, että te tulette osallisiksi riivaajista.'),
(1697519,58,46,10,21,'Ette voi juoda Herran maljasta ja riivaajien maljasta, ette voi olla osalliset Herran pöydästä ja riivaajien pöydästä.'),
(1697520,58,46,10,22,'Vai tahdommeko herättää Herran kiivauden? Emme kaiketi me ole häntä väkevämmät?'),
(1697521,58,46,10,23,'"Kaikki on luvallista", mutta ei kaikki ole hyödyksi; "kaikki on luvallista", mutta ei kaikki rakenna.'),
(1697522,58,46,10,24,'Älköön kukaan katsoko omaa parastaan, vaan toisen parasta.'),
(1697523,58,46,10,25,'Syökää kaikkea, mitä lihakaupassa myydään, kyselemättä mitään omantunnon tähden,'),
(1697524,58,46,10,26,'sillä: "Herran on maa ja kaikki, mitä siinä on".'),
(1697525,58,46,10,27,'Jos joku, joka ei usko, kutsuu teitä ja te tahdotte mennä hänen luokseen, niin syökää kaikkea, mitä eteenne pannaan, kyselemättä mitään omantunnon tähden.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697526,58,46,10,28,'Mutta jos joku sanoo teille: "Tämä on epäjumalille uhrattua", niin jättäkää se syömättä hänen tähtensä, joka sen ilmaisi, ja omantunnon tähden;'),
(1697527,58,46,10,29,'en tarkoita sinun omaatuntoasi, vaan tuon toisen; sillä miksi minun vapauteni joutuisi toisen omantunnon tuomittavaksi?'),
(1697528,58,46,10,30,'Jos minä sen kiittäen nautin, miksi minua herjataan siitä, mistä kiitän?'),
(1697529,58,46,10,31,'Söittepä siis tai joitte tai teittepä mitä hyvänsä, tehkää kaikki Jumalan kunniaksi.'),
(1697530,58,46,10,32,'Älkää olko pahennukseksi juutalaisille, älkää kreikkalaisille älkääkä Jumalan seurakunnalle,'),
(1697531,58,46,10,33,'niinkuin minäkin koetan kelvata kaikille kaikessa enkä katso omaa hyötyäni, vaan monien hyötyä, että he pelastuisivat.'),
(1697532,58,46,11,1,'Olkaa minun seuraajiani, niinkuin minä olen Kristuksen seuraaja.'),
(1697533,58,46,11,2,'Minä kiitän teitä, että minua kaikessa muistatte ja noudatatte minun opetuksiani, niinkuin minä ne teille olen antanut.'),
(1697534,58,46,11,3,'Mutta minä tahdon, että te tiedätte sen, että Kristus on jokaisen miehen pää ja että mies on vaimon pää ja että Jumala on Kristuksen pää.'),
(1697535,58,46,11,4,'Jokainen mies, joka rukoilee tai profetoi pää peitettynä, häpäisee päänsä.'),
(1697536,58,46,11,5,'Mutta jokainen vaimo, joka rukoilee tai profetoi pää peittämätönnä, häpäisee päänsä, sillä se on aivan sama, kuin jos hänen päänsä olisi paljaaksi ajeltu.'),
(1697537,58,46,11,6,'Sillä jos vaimo ei verhoa päätään, leikkauttakoon hiuksensakin; mutta koska on häpeäksi vaimolle, että hän leikkauttaa tai ajattaa hiuksensa, niin verhotkoon itsensä.'),
(1697538,58,46,11,7,'Miehen ei tule peittää päätänsä, koska hän on Jumalan kuva ja kunnia; mutta vaimo on miehen kunnia.'),
(1697539,58,46,11,8,'Sillä mies ei ole alkuisin vaimosta, vaan vaimo miehestä;'),
(1697540,58,46,11,9,'eikä miestä luotu vaimoa varten, vaan vaimo miestä varten.'),
(1697541,58,46,11,10,'Sentähden vaimon tulee pitää päässään vallanalaisuuden merkki enkelien tähden.'),
(1697542,58,46,11,11,'Herrassa ei kuitenkaan ole vaimoa ilman miestä eikä miestä ilman vaimoa.'),
(1697543,58,46,11,12,'Sillä samoin kuin vaimo on alkuisin miehestä, samoin myös mies on vaimon kautta; mutta kaikki on Jumalasta.'),
(1697544,58,46,11,13,'Päättäkää itse: sopiiko vaimon rukoilla Jumalaa pää peittämätönnä?'),
(1697545,58,46,11,14,'Eikö itse luontokin opeta teille, että jos miehellä on pitkät hiukset, se on hänelle häpeäksi;'),
(1697546,58,46,11,15,'ja että jos vaimolla on pitkät hiukset, se on hänelle kunniaksi? Sillä ovathan hiukset annetut hänelle hunnuksi.'),
(1697547,58,46,11,16,'Mutta jos joku haluaa väittää vastaan, niin tietäköön, että meillä ei ole sellaista tapaa eikä Jumalan seurakunnilla.'),
(1697548,58,46,11,17,'Mutta tätä käskiessäni en kiitä sitä, että kokoontumisenne ei tee teitä paremmiksi, vaan pahemmiksi.'),
(1697549,58,46,11,18,'Sillä ensiksikin olen kuullut, että kun kokoonnutte seurakunnankokoukseen, teillä on riitaisuuksia keskenänne, ja osittain sen uskonkin.'),
(1697550,58,46,11,19,'Täytyyhän teidän keskuudessanne olla puolueitakin, että kävisi ilmi, ketkä teistä kestävät koetuksen.'),
(1697551,58,46,11,20,'Kun te näin kokoonnutte yhteen, niin ei se ole Herran aterian nauttimista,'),
(1697552,58,46,11,21,'sillä syömään ruvettaessa kukin rientää ottamaan eteensä omat ruokansa, ja niin toinen on nälissään ja toinen juovuksissa.'),
(1697553,58,46,11,22,'Eikö teillä sitten ole muita huoneita, niissä syödäksenne ja juodaksenne? Vai halveksitteko Jumalan seurakuntaa ja tahdotteko häväistä niitä, joilla ei mitään ole? Mitä minun on teille sanominen? Onko minun teitä kiittäminen? Tässä kohden en kiitä.'),
(1697554,58,46,11,23,'Sillä minä olen saanut Herralta sen, minkä myös olen teille tiedoksi antanut, että Herra Jeesus sinä yönä, jona hänet kavallettiin, otti leivän,'),
(1697555,58,46,11,24,'kiitti, mursi ja sanoi: "Tämä on minun ruumiini, joka teidän edestänne annetaan; tehkää tämä minun muistokseni".'),
(1697556,58,46,11,25,'Samoin hän otti myös maljan aterian jälkeen ja sanoi: "Tämä malja on uusi liitto minun veressäni; niin usein kuin te juotte, tehkää se minun muistokseni".'),
(1697557,58,46,11,26,'Sillä niin usein kuin te syötte tätä leipää ja juotte tämän maljan, te julistatte Herran kuolemaa, siihen asti kuin hän tulee.'),
(1697558,58,46,11,27,'Sentähden, joka kelvottomasti syö tätä leipää tai juo Herran maljan, hän on oleva vikapää Herran ruumiiseen ja vereen.'),
(1697559,58,46,11,28,'Koetelkoon siis ihminen itseänsä, ja niin syököön tätä leipää ja juokoon tästä maljasta;'),
(1697560,58,46,11,29,'sillä joka syö ja juo erottamatta Herran ruumista muusta, syö ja juo tuomioksensa.'),
(1697561,58,46,11,30,'Sentähden onkin teidän joukossanne paljon heikkoja ja sairaita, ja moni on nukkunut pois.'),
(1697562,58,46,11,31,'Mutta jos me tutkisimme itseämme, ei meitä tuomittaisi;'),
(1697563,58,46,11,32,'mutta kun meitä tuomitaan, niin se on meille Herran kuritusta, ettei meitä maailman kanssa kadotukseen tuomittaisi.'),
(1697564,58,46,11,33,'Sentähden, veljeni, kun kokoonnutte aterioimaan, odottakaa toisianne.'),
(1697565,58,46,11,34,'Jos kenellä on nälkä, syököön kotonaan, ettette kokoontuisi tuomioksenne. Muista seikoista minä säädän, sitten kuin tulen.'),
(1697566,58,46,12,1,'Mutta mitä hengellisiin lahjoihin tulee, niin en tahdo, veljet, pitää teitä niistä tietämättöminä.'),
(1697567,58,46,12,2,'Te tiedätte, että kun olitte pakanoita, teitä vietiin mykkien epäjumalien luo, miten vain tahdottiin.'),
(1697568,58,46,12,3,'Sentähden minä teen teille tiettäväksi, ettei kukaan, joka puhuu Jumalan Hengessä, sano: "Jeesus olkoon kirottu", ja ettei kukaan voi sanoa: "Jeesus olkoon Herra", paitsi Pyhässä Hengessä.'),
(1697569,58,46,12,4,'Armolahjat ovat moninaiset, mutta Henki on sama;'),
(1697570,58,46,12,5,'ja seurakuntavirat ovat moninaiset, mutta Herra on sama;'),
(1697571,58,46,12,6,'ja voimavaikutukset ovat moninaiset, mutta Jumala, joka kaikki kaikissa vaikuttaa, on sama.'),
(1697572,58,46,12,7,'Mutta kullekin annetaan Hengen ilmoitus yhteiseksi hyödyksi.'),
(1697573,58,46,12,8,'Niinpä saa Hengen kautta toinen viisauden sanat, toinen tiedon sanat saman Hengen vaikutuksesta;'),
(1697574,58,46,12,9,'toinen saa uskon samassa Hengessä, toinen taas terveeksitekemisen lahjat siinä yhdessä Hengessä;'),
(1697575,58,46,12,10,'toinen lahjan tehdä voimallisia tekoja; toinen profetoimisen lahjan, toinen lahjan arvostella henkiä; toinen eri kielillä puhumisen lahjan, toinen taas lahjan selittää kieliä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697576,58,46,12,11,'Mutta kaiken tämän vaikuttaa yksi ja sama Henki, jakaen kullekin erikseen, niinkuin tahtoo.'),
(1697577,58,46,12,12,'Sillä niinkuin ruumis on yksi ja siinä on monta jäsentä, mutta kaikki ruumiin jäsenet, vaikka niitä on monta, ovat yksi ruumis, niin on Kristuskin;'),
(1697578,58,46,12,13,'sillä me olemme kaikki yhdessä Hengessä kastetut yhdeksi ruumiiksi, olimmepa juutalaisia tai kreikkalaisia, orjia tai vapaita, ja kaikki olemme saaneet juoda samaa Henkeä.'),
(1697579,58,46,12,14,'Sillä eihän ruumiskaan ole yksi jäsen, vaan niitä on siinä monta.'),
(1697580,58,46,12,15,'Jos jalka sanoisi: "Koska en ole käsi, en kuulu ruumiiseen", niin ei se silti olisi ruumiiseen kuulumaton.'),
(1697581,58,46,12,16,'Ja jos korva sanoisi: "Koska en ole silmä, en kuulu ruumiiseen", niin ei se silti olisi ruumiiseen kuulumaton.'),
(1697582,58,46,12,17,'Jos koko ruumis olisi silmänä, missä sitten olisi kuulo? Jos taas kokonaan kuulona, missä silloin haisti?'),
(1697583,58,46,12,18,'Mutta nyt Jumala on asettanut jäsenet, itsekunkin niistä, ruumiiseen, niinkuin hän on tahtonut.'),
(1697584,58,46,12,19,'Vaan jos ne kaikki olisivat yhtenä jäsenenä, missä sitten ruumis olisi?'),
(1697585,58,46,12,20,'Mutta nytpä onkin monta jäsentä, ja ainoastaan yksi ruumis.'),
(1697586,58,46,12,21,'Silmä ei saata sanoa kädelle: "En tarvitse sinua", eikä myöskään pää jaloille: "En tarvitse teitä".'),
(1697587,58,46,12,22,'Päinvastoin ne ruumiin jäsenet, jotka näyttävät olevan heikompia, ovat välttämättömiä;'),
(1697588,58,46,12,23,'ja ne ruumiin jäsenet, jotka meistä ovat vähemmän kunniakkaita, me verhoamme sitä kunniallisemmin, ja niitä, joita häpeämme, me sitä häveliäämmin peitämme;'),
(1697589,58,46,12,24,'mutta ne, joita emme häpeä, eivät sitä tarvitse. Mutta Jumala on liittänyt ruumiin yhteen niin, että antoi halvempiarvoiselle suuremman kunnian,'),
(1697590,58,46,12,25,'ettei ruumiissa olisi eripuraisuutta, vaan että jäsenet pitäisivät yhtäläistä huolta toinen toisestaan.'),
(1697591,58,46,12,26,'Ja jos yksi jäsen kärsii, niin kaikki jäsenet kärsivät sen kanssa; tai jos jollekulle jäsenelle annetaan kunnia, niin kaikki jäsenet iloitsevat sen kanssa.'),
(1697592,58,46,12,27,'Mutta te olette Kristuksen ruumis ja kukin osaltanne hänen jäseniänsä.'),
(1697593,58,46,12,28,'Niinpä Jumala asetti seurakuntaan ensiksi muutamia apostoleiksi, toisia profeetoiksi, kolmansia opettajiksi, sitten hän antoi voimallisia tekoja, sitten armolahjoja parantaa tauteja, avustaa, hallita, puhua eri kielillä.'),
(1697594,58,46,12,29,'Eivät suinkaan kaikki ole apostoleja? Eivät kaikki profeettoja? Eivät kaikki opettajia? Eiväthän kaikki tee voimallisia tekoja?'),
(1697595,58,46,12,30,'Eihän kaikilla ole parantamisen armolahjoja? Eiväthän kaikki puhu kielillä? Eiväthän kaikki kykene niitä selittämään?'),
(1697596,58,46,12,31,'Pyrkikää osallisiksi parhaimmista armolahjoista. Ja vielä minä osoitan teille tien, verrattoman tien.'),
(1697597,58,46,13,1,'Vaikka minä puhuisin ihmisten ja enkelien kielillä, mutta minulla ei olisi rakkautta, olisin minä vain helisevä vaski tai kilisevä kulkunen.'),
(1697598,58,46,13,2,'Ja vaikka minulla olisi profetoimisen lahja ja minä tietäisin kaikki salaisuudet ja kaiken tiedon, ja vaikka minulla olisi kaikki usko, niin että voisin vuoria siirtää, mutta minulla ei olisi rakkautta, en minä mitään olisi.'),
(1697599,58,46,13,3,'Ja vaikka minä jakelisin kaiken omaisuuteni köyhäin ravinnoksi, ja vaikka antaisin ruumiini poltettavaksi, mutta minulla ei olisi rakkautta, ei se minua mitään hyödyttäisi.'),
(1697600,58,46,13,4,'Rakkaus on pitkämielinen, rakkaus on lempeä; rakkaus ei kadehdi, ei kerskaa, ei pöyhkeile,'),
(1697601,58,46,13,5,'ei käyttäydy sopimattomasti, ei etsi omaansa, ei katkeroidu, ei muistele kärsimäänsä pahaa,'),
(1697602,58,46,13,6,'ei iloitse vääryydestä, vaan iloitsee yhdessä totuuden kanssa;'),
(1697603,58,46,13,7,'kaikki se peittää, kaikki se uskoo, kaikki se toivoo, kaikki se kärsii.'),
(1697604,58,46,13,8,'Rakkaus ei koskaan häviä; mutta profetoiminen, se katoaa, ja kielillä puhuminen lakkaa, ja tieto katoaa.'),
(1697605,58,46,13,9,'Sillä tietomme on vajavaista, ja profetoimisemme on vajavaista.'),
(1697606,58,46,13,10,'Mutta kun tulee se, mikä täydellistä on, katoaa se, mikä on vajavaista.'),
(1697607,58,46,13,11,'Kun minä olin lapsi, niin minä puhuin kuin lapsi, minulla oli lapsen mieli, ja minä ajattelin kuin lapsi; kun tulin mieheksi, hylkäsin minä sen, mikä lapsen on.'),
(1697608,58,46,13,12,'Sillä nyt me näemme kuin kuvastimessa, arvoituksen tavoin, mutta silloin kasvoista kasvoihin; nyt minä tunnen vajavaisesti, mutta silloin minä olen tunteva täydellisesti, niinkuin minut itsenikin täydellisesti tunnetaan.'),
(1697609,58,46,13,13,'Niin pysyvät nyt usko, toivo, rakkaus, nämä kolme; mutta suurin niistä on rakkaus.'),
(1697610,58,46,14,1,'Tavoitelkaa rakkautta ja pyrkikää saamaan hengellisiä lahjoja, mutta varsinkin profetoimisen lahjaa.'),
(1697611,58,46,14,2,'Sillä kielillä puhuva ei puhu ihmisille, vaan Jumalalle; ei häntä näet kukaan ymmärrä, sillä hän puhuu salaisuuksia hengessä.'),
(1697612,58,46,14,3,'Mutta profetoiva puhuu ihmisille rakennukseksi ja kehoitukseksi ja lohdutukseksi.'),
(1697613,58,46,14,4,'Kielillä puhuva rakentaa itseään, mutta profetoiva rakentaa seurakuntaa.'),
(1697614,58,46,14,5,'Soisin teidän kaikkien puhuvan kielillä, mutta vielä mieluummin soisin teidän profetoivan; sillä profetoiva on suurempi kuin kielillä puhuva, ellei tämä samalla selitä, niin että seurakunta siitä rakentuu.'),
(1697615,58,46,14,6,'Jos minä nyt, veljet, tulisin luoksenne kielillä puhuen, mitä minä teitä sillä hyödyttäisin, ellen puhuisi teille ilmestyksen tai tiedon tai profetian tai opetuksen sanoja?'),
(1697616,58,46,14,7,'Niinhän on elottomain soittimienkin laita, huilujen tai kitarain: kuinka tiedetään, mitä huilulla tai kitaralla soitetaan, elleivät ne soi toisistaan erottuvin sävelin?'),
(1697617,58,46,14,8,'Niinikään, jos pasuna antaa epäselvän äänen, kuka silloin valmistautuu taisteluun?'),
(1697618,58,46,14,9,'Samoin tekin: jos ette kielellänne saa esiin selvää puhetta, kuinka voidaan sellainen puhe ymmärtää? Tehän puhutte silloin tuuleen.'),
(1697619,58,46,14,10,'Maailmassa on, kuka tietää, kuinka monta eri kieltä, mutta ei ainoatakaan, jonka äänet eivät ole ymmärrettävissä.'),
(1697620,58,46,14,11,'Mutta jos en tiedä sanojen merkitystä, olen minä puhujalle muukalainen, ja puhuja on minulle muukalainen.'),
(1697621,58,46,14,12,'Samoin tekin, koska tavoittelette henkilahjoja, niin pyrkikää seurakunnan rakennukseksi saamaan niitä runsaasti.'),
(1697622,58,46,14,13,'Sentähden rukoilkoon se, joka kielillä puhuu, että hän taitaisi selittää.'),
(1697623,58,46,14,14,'Sillä jos minä rukoilen kielillä puhuen, niin minun henkeni kyllä rukoilee, mutta ymmärrykseni on hedelmätön.'),
(1697624,58,46,14,15,'Kuinka siis on? Minun on rukoiltava hengelläni, mutta minun on rukoiltava myöskin ymmärrykselläni; minun on veisattava kiitosta hengelläni, mutta minun on veisattava myöskin ymmärrykselläni.'),
(1697625,58,46,14,16,'Sillä jos ylistät Jumalaa hengessä, kuinka oppimattoman paikalla istuva saattaa sanoa "amen" sinun kiitokseesi? Eihän hän ymmärrä, mitä sanot.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697626,58,46,14,17,'Sinä kyllä kiität hyvin, mutta toinen ei siitä rakennu.'),
(1697627,58,46,14,18,'Minä kiitän Jumalaa, että puhun kielillä enemmän kuin teistä kukaan;'),
(1697628,58,46,14,19,'mutta seurakunnassa tahdon mieluummin puhua viisi sanaa ymmärrykselläni, opettaakseni muitakin, kuin kymmenentuhatta sanaa kielillä.'),
(1697629,58,46,14,20,'Veljet, älkää olko lapsia ymmärrykseltänne, vaan pahuudessa olkaa lapsia; mutta ymmärrykseltä olkaa täysi-ikäisiä.'),
(1697630,58,46,14,21,'Laissa on kirjoitettuna: "Vieraskielisten kautta ja muukalaisten huulilla minä olen puhuva tälle kansalle, eivätkä he sittenkään minua kuule, sanoo Herra".'),
(1697631,58,46,14,22,'Kielet eivät siis ole merkiksi uskoville, vaan niille, jotka eivät usko; mutta profetoiminen ei ole merkiksi uskottomille, vaan uskoville.'),
(1697632,58,46,14,23,'Jos nyt koko seurakunta kokoontuisi yhteen ja kaikki siellä puhuisivat kielillä ja sinne tulisi opetuksesta tai uskosta osattomia, eivätkö he sanoisi teidän olevan järjiltänne?'),
(1697633,58,46,14,24,'Mutta jos kaikki profetoisivat ja joku uskosta tai opetuksesta osaton tulisi sisään, niin kaikki paljastaisivat hänet ja kaikki langettaisivat hänestä tuomion,'),
(1697634,58,46,14,25,'hänen sydämensä salaisuudet tulisivat ilmi, ja niin hän kasvoilleen langeten rukoilisi Jumalaa ja julistaisi, että Jumala totisesti on teissä.'),
(1697635,58,46,14,26,'Kuinka siis on, veljet? Kun tulette yhteen, on jokaisella jotakin annettavaa: millä on virsi, millä opetus, millä ilmestys, mikä puhuu kielillä, mikä selittää; kaikki tapahtukoon rakennukseksi.'),
(1697636,58,46,14,27,'Jos kielillä puhutaan, niin puhukoon kullakin kertaa vain kaksi tai enintään kolme, ja yksi kerrallaan, ja yksi selittäköön;'),
(1697637,58,46,14,28,'mutta jos ei ole selittäjää, niin olkoot vaiti seurakunnassa ja puhukoot itselleen ja Jumalalle.'),
(1697638,58,46,14,29,'Profeetoista saakoon kaksi tai kolme puhua, ja muut arvostelkoot;'),
(1697639,58,46,14,30,'mutta jos joku toinen siinä istuva saa ilmestyksen, vaietkoon ensimmäinen.'),
(1697640,58,46,14,31,'Sillä te saatatte kaikki profetoida, toinen toisenne jälkeen, että kaikki saisivat opetusta ja kaikki kehoitusta.'),
(1697641,58,46,14,32,'Ja profeettain henget ovat profeetoille alamaiset;'),
(1697642,58,46,14,33,'sillä ei Jumala ole epäjärjestyksen, vaan rauhan Jumala. Niinkuin kaikissa pyhien seurakunnissa,'),
(1697643,58,46,14,34,'olkoot vaimot vaiti teidänkin seurakunnankokouksissanne, sillä heidän ei ole lupa puhua, vaan olkoot alamaisia, niinkuin lakikin sanoo.'),
(1697644,58,46,14,35,'Mutta jos he tahtovat tietoa jostakin, niin kysykööt kotonaan omilta miehiltään, sillä häpeällistä on naisen puhua seurakunnassa.'),
(1697645,58,46,14,36,'Vai teistäkö Jumalan sana on lähtenyt? Vai ainoastaan teidänkö tykönne se on tullut?'),
(1697646,58,46,14,37,'Jos joku luulee olevansa profeetta tai hengellinen, niin tietäköön, että mitä minä kirjoitan teille, se on Herran käsky.'),
(1697647,58,46,14,38,'Mutta jos joku ei sitä ymmärrä, niin olkoon ymmärtämättä.'),
(1697648,58,46,14,39,'Sentähden, veljeni, harrastakaa profetoimista älkääkä estäkö kielillä puhumasta.'),
(1697649,58,46,14,40,'Mutta kaikki tapahtukoon säädyllisesti ja järjestyksessä.'),
(1697650,58,46,15,1,'Veljet, minä johdatan teidät tuntemaan sen evankeliumin, jonka minä teille julistin, jonka te myöskin olette ottaneet vastaan ja jossa myös pysytte'),
(1697651,58,46,15,2,'ja jonka kautta te myös pelastutte, jos pidätte siitä kiinni semmoisena, kuin minä sen teille julistin, ellette turhaan ole uskoneet.'),
(1697652,58,46,15,3,'Sillä minä annoin teille ennen kaikkea tiedoksi sen, minkä itse olin saanut: että Kristus on kuollut meidän syntiemme tähden, kirjoitusten mukaan,'),
(1697653,58,46,15,4,'ja että hänet haudattiin ja että hän nousi kuolleista kolmantena päivänä, kirjoitusten mukaan,'),
(1697654,58,46,15,5,'ja että hän näyttäytyi Keefaalle, sitten niille kahdelletoista.'),
(1697655,58,46,15,6,'Sen jälkeen hän näyttäytyi yhtä haavaa enemmälle kuin viidellesadalle veljelle, joista useimmat vielä nytkin ovat elossa, mutta muutamat ovat nukkuneet pois.'),
(1697656,58,46,15,7,'Sen jälkeen hän näyttäytyi Jaakobille, sitten kaikille apostoleille.'),
(1697657,58,46,15,8,'Mutta kaikkein viimeiseksi hän näyttäytyi minullekin, joka olen ikäänkuin keskensyntynyt.'),
(1697658,58,46,15,9,'Sillä minä olen apostoleista halvin enkä ole sen arvoinen, että minua apostoliksi kutsutaan, koska olen vainonnut Jumalan seurakuntaa.'),
(1697659,58,46,15,10,'Mutta Jumalan armosta minä olen se, mikä olen, eikä hänen armonsa minua kohtaan ole ollut turha, vaan enemmän kuin he kaikki minä olen työtä tehnyt, en kuitenkaan minä, vaan Jumalan armo, joka on minun kanssani.'),
(1697660,58,46,15,11,'Olinpa siis minä tai olivatpa he: näin me saarnaamme, ja näin te olette uskoon tulleet.'),
(1697661,58,46,15,12,'Mutta jos Kristuksesta saarnataan, että hän on noussut kuolleista, kuinka muutamat teistä saattavat sanoa, ettei kuolleitten ylösnousemusta ole?'),
(1697662,58,46,15,13,'Vaan jos ei ole kuolleitten ylösnousemusta, ei Kristuskaan ole noussut.'),
(1697663,58,46,15,14,'Mutta jos Kristus ei ole noussut kuolleista, turha on silloin meidän saarnamme, turha myös teidän uskonne;'),
(1697664,58,46,15,15,'ja silloin meidät myös havaitaan vääriksi Jumalan todistajiksi, koska olemme todistaneet Jumalaa vastaan, että hän on herättänyt Kristuksen, jota hän ei ole herättänyt, jos kerran kuolleita ei herätetä.'),
(1697665,58,46,15,16,'Sillä jos kuolleita ei herätetä, ei Kristuskaan ole herätetty.'),
(1697666,58,46,15,17,'Mutta jos Kristus ei ole herätetty, niin teidän uskonne on turha, ja te olette vielä synneissänne.'),
(1697667,58,46,15,18,'Ja silloinhan Kristuksessa nukkuneetkin olisivat kadotetut.'),
(1697668,58,46,15,19,'Jos olemme panneet toivomme Kristukseen ainoastaan tämän elämän ajaksi, niin olemme kaikkia muita ihmisiä surkuteltavammat.'),
(1697669,58,46,15,20,'Mutta nytpä Kristus on noussut kuolleista, esikoisena kuoloon nukkuneista.'),
(1697670,58,46,15,21,'Sillä koska kuolema on tullut ihmisen kautta, niin on myöskin kuolleitten ylösnousemus tullut ihmisen kautta.'),
(1697671,58,46,15,22,'Sillä niinkuin kaikki kuolevat Aadamissa, niin myös kaikki tehdään eläviksi Kristuksessa,'),
(1697672,58,46,15,23,'mutta jokainen vuorollaan: esikoisena Kristus, sitten Kristuksen omat hänen tulemuksessaan;'),
(1697673,58,46,15,24,'sitten tulee loppu, kun hän antaa valtakunnan Jumalan ja Isän haltuun, kukistettuaan kaiken hallituksen ja kaiken vallan ja voiman.'),
(1697674,58,46,15,25,'Sillä hänen pitää hallitseman "siihen asti, kunnes hän on pannut kaikki viholliset jalkojensa alle".'),
(1697675,58,46,15,26,'Vihollisista viimeisenä kukistetaan kuolema.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697676,58,46,15,27,'Sillä: "kaikki hän on alistanut hänen jalkojensa alle". Mutta kun hän sanoo: "kaikki on alistettu", niin ei tietenkään ole alistettu se, joka on alistanut kaiken hänen allensa.'),
(1697677,58,46,15,28,'Ja kun kaikki on alistettu Pojan valtaan, silloin itse Poikakin alistetaan sen valtaan, joka on alistanut hänen valtaansa kaiken, että Jumala olisi kaikki kaikissa.'),
(1697678,58,46,15,29,'Mitä muutoin ne, jotka kastattavat itsensä kuolleitten puolesta, sillä saavat aikaan? Jos kuolleet eivät heräjä, miksi nämä sitten kastattavat itsensä heidän puolestaan?'),
(1697679,58,46,15,30,'Ja miksi mekään antaudumme joka hetki vaaraan?'),
(1697680,58,46,15,31,'Joka päivä minä olen kuoleman kidassa, niin totta kuin te, veljet, olette minun kerskaukseni Kristuksessa Jeesuksessa, meidän Herrassamme.'),
(1697681,58,46,15,32,'Jos minä ihmisten tavoin olen taistellut petojen kanssa Efesossa, mitä hyötyä minulle siitä on? Jos kuolleet eivät heräjä, niin: "syökäämme ja juokaamme, sillä huomenna me kuolemme".'),
(1697682,58,46,15,33,'Älkää eksykö. "Huono seura hyvät tavat turmelee."'),
(1697683,58,46,15,34,'Raitistukaa oikealla tavalla, älkääkä syntiä tehkö; sillä niitä on, joilla ei ole mitään tietoa Jumalasta. Teidän häpeäksenne minä tämän sanon.'),
(1697684,58,46,15,35,'Mutta joku ehkä kysyy: "Millä tavoin kuolleet heräjävät, ja millaisessa ruumiissa he tulevat?"'),
(1697685,58,46,15,36,'Sinä mieletön, se, minkä kylvät, ei virkoa eloon, ellei se ensin kuole!'),
(1697686,58,46,15,37,'Ja kun kylvät, et kylvä sitä vartta, joka on nouseva, vaan paljaan jyvän, nisun jyvän tai muun minkä tahansa.'),
(1697687,58,46,15,38,'Mutta Jumala antaa sille varren, sellaisen kuin tahtoo, ja kullekin siemenelle sen oman varren.'),
(1697688,58,46,15,39,'Ei kaikki liha ole samaa lihaa, vaan toista on ihmisten, toista taas karjan liha, toista on lintujen liha, toista kalojen.'),
(1697689,58,46,15,40,'Ja on taivaallisia ruumiita ja maallisia ruumiita; mutta toinen on taivaallisten kirkkaus, toinen taas maallisten.'),
(1697690,58,46,15,41,'Toinen on auringon kirkkaus ja toinen kuun kirkkaus ja toinen tähtien kirkkaus, ja toinen tähti voittaa toisen kirkkaudessa.'),
(1697691,58,46,15,42,'Niin on myös kuolleitten ylösnousemus: kylvetään katoavaisuudessa, nousee katoamattomuudessa;'),
(1697692,58,46,15,43,'kylvetään alhaisuudessa, nousee kirkkaudessa; kylvetään heikkoudessa, nousee voimassa;'),
(1697693,58,46,15,44,'kylvetään sielullinen ruumis, nousee hengellinen ruumis. Jos kerran on sielullinen ruumis, niin on myös hengellinen.'),
(1697694,58,46,15,45,'Niin on myös kirjoitettu: "Ensimmäisestä ihmisestä, Aadamista, tuli elävä sielu"; viimeisestä Aadamista tuli eläväksitekevä henki.'),
(1697695,58,46,15,46,'Mutta mikä on hengellistä, se ei ole ensimmäinen, vaan se, mikä on sielullista, on ensimmäinen; sitten on se, mikä on hengellistä.'),
(1697696,58,46,15,47,'Ensimmäinen ihminen oli maasta, maallinen, toinen ihminen on taivaasta.'),
(1697697,58,46,15,48,'Minkäkaltainen maallinen oli, senkaltaisia ovat myös maalliset; ja minkäkaltainen taivaallinen on, senkaltaisia ovat myös taivaalliset.'),
(1697698,58,46,15,49,'Ja niinkuin meissä on ollut maallisen kuva, niin meissä on myös oleva taivaallisen kuva.'),
(1697699,58,46,15,50,'Mutta tämän minä sanon, veljet, ettei liha ja veri voi periä Jumalan valtakuntaa, eikä katoavaisuus peri katoamattomuutta.'),
(1697700,58,46,15,51,'Katso, minä sanon teille salaisuuden: emme kaikki kuolemaan nuku, mutta kaikki me muutumme,'),
(1697701,58,46,15,52,'yhtäkkiä, silmänräpäyksessä, viimeisen pasunan soidessa; sillä pasuna soi, ja kuolleet nousevat katoamattomina, ja me muutumme.'),
(1697702,58,46,15,53,'Sillä tämän katoavaisen pitää pukeutuman katoamattomuuteen, ja tämän kuolevaisen pitää pukeutuman kuolemattomuuteen.'),
(1697703,58,46,15,54,'Mutta kun tämä katoavainen pukeutuu katoamattomuuteen ja tämä kuolevainen pukeutuu kuolemattomuuteen, silloin toteutuu se sana, joka on kirjoitettu: "Kuolema on nielty ja voitto saatu".'),
(1697704,58,46,15,55,'"Kuolema, missä on sinun voittosi? Kuolema, missä on sinun otasi?"'),
(1697705,58,46,15,56,'Mutta kuoleman ota on synti, ja synnin voima on laki.'),
(1697706,58,46,15,57,'Mutta kiitos olkoon Jumalan, joka antaa meille voiton meidän Herramme Jeesuksen Kristuksen kautta!'),
(1697707,58,46,15,58,'Sentähden, rakkaat veljeni, olkaa lujat, järkähtämättömät, aina innokkaat Herran työssä, tietäen, että teidän vaivannäkönne ei ole turha Herrassa.'),
(1697708,58,46,16,1,'Mitä tulee keräykseen pyhiä varten, niin tehkää tekin samalla tavoin, kuin minä olen määrännyt Galatian seurakunnille.'),
(1697709,58,46,16,2,'Kunkin viikon ensimmäisenä päivänä pankoon jokainen teistä kotonaan jotakin talteen, säästäen menestymisensä mukaan, ettei keräyksiä tehtäisi vasta minun tultuani.'),
(1697710,58,46,16,3,'Mutta kun olen saapunut teidän tykönne, lähetän minä ne henkilöt, jotka siihen sopiviksi katsotte, kirjeet mukanaan, viemään teidän rakkaudenlahjanne Jerusalemiin;'),
(1697711,58,46,16,4,'ja jos asia on sen arvoinen, että minunkin on lähteminen, niin saavat he lähteä minun kanssani.'),
(1697712,58,46,16,5,'Aion nimittäin tulla teidän tykönne kuljettuani läpi Makedonian, sillä minä kuljen Makedonian kautta;'),
(1697713,58,46,16,6,'mutta teidän luonanne viivyn ehkä jonkin aikaa, kenties vietän talvenkin, että te sitten auttaisitte minua eteenpäin, minne matkustanenkin.'),
(1697714,58,46,16,7,'Sillä en tahdo nyt vain ohimennen käydä teitä katsomassa, toivon näet saavani viipyä jonkin aikaa teidän luonanne, jos Herra sallii.'),
(1697715,58,46,16,8,'Mutta Efesossa minä viivyn helluntaihin saakka;'),
(1697716,58,46,16,9,'sillä minulle on avautunut ovi suureen ja hedelmälliseen työhön, ja vastustajia on paljon.'),
(1697717,58,46,16,10,'Mutta jos Timoteus saapuu, niin katsokaa, että hän pelotta voi olla teidän luonanne, sillä Herran työtä hän toimittaa niinkuin minäkin.'),
(1697718,58,46,16,11,'Älköön siis kukaan häntä halveksiko, vaan auttakaa häntä lähtemään rauhassa matkalle, että hän tulisi minun tyköni; sillä minä ja veljet odotamme häntä.'),
(1697719,58,46,16,12,'Mitä veli Apollokseen tulee, olen hartaasti kehoittanut häntä lähtemään veljien kanssa teidän tykönne; mutta hän ei ole ollenkaan halukas lähtemään nyt, vaan tulee, kun hänelle sopii.'),
(1697720,58,46,16,13,'Valvokaa, pysykää lujina uskossa, olkaa miehuulliset, olkaa väkevät.'),
(1697721,58,46,16,14,'Kaikki, mitä teette, tapahtukoon rakkaudessa.'),
(1697722,58,46,16,15,'Mutta minä kehoitan teitä, veljet: te tunnette Stefanaan perhekunnan ja tiedätte, että se on Akaian ensi hedelmä ja että he ovat antautuneet pyhien palvelukseen.'),
(1697723,58,46,16,16,'Olkaa tekin kuuliaisia heidän kaltaisilleen ja jokaiselle, joka heidän kanssaan työtä tekee ja vaivaa näkee.'),
(1697724,58,46,16,17,'Minä iloitsen Stefanaan ja Fortunatuksen ja Akaikuksen tännetulosta, koska he korvaavat minulle teidän poissaolonne;'),
(1697725,58,46,16,18,'he ovat virkistäneet minun henkeäni niinkuin teidänkin. Antakaa siis täysi tunnustus sellaisille miehille.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697726,58,46,16,19,'Aasian seurakunnat tervehtivät teitä. Monet tervehdykset Herrassa lähettävät teille Akylas ja Priska sekä heidän kodissaan kokoontuva seurakunta.'),
(1697727,58,46,16,20,'Kaikki veljet lähettävät teille tervehdyksen. Tervehtikää toisianne pyhällä suunannolla.'),
(1697728,58,46,16,21,'Tervehdys minulta, Paavalilta, omakätisesti.'),
(1697729,58,46,16,22,'Jos joku ei pidä Herraa rakkaana, hän olkoon kirottu! Maran ata.'),
(1697730,58,46,16,23,'Herran Jeesuksen armo olkoon teidän kanssanne.'),
(1697731,58,46,16,24,'Minun rakkauteni on teidän kaikkien kanssa Kristuksessa Jeesuksessa.'),
(1697732,58,47,1,1,'Paavali, Jumalan tahdosta Kristuksen Jeesuksen apostoli, ja veli Timoteus Korintossa olevalle Jumalan seurakunnalle ynnä kaikille pyhille koko Akaiassa.'),
(1697733,58,47,1,2,'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!'),
(1697734,58,47,1,3,'Kiitetty olkoon meidän Herramme Jeesuksen Kristuksen Jumala ja Isä, laupeuden Isä ja kaiken lohdutuksen Jumala,'),
(1697735,58,47,1,4,'joka lohduttaa meitä kaikessa ahdistuksessamme, että me sillä lohdutuksella, jolla Jumala meitä itseämme lohduttaa, voisimme lohduttaa niitä, jotka kaikkinaisessa ahdistuksessa ovat.'),
(1697736,58,47,1,5,'Sillä samoin kuin Kristuksen kärsimykset runsaina tulevat meidän osaksemme, samoin tulee meidän osaksemme myöskin lohdutus runsaana Kristuksen kautta.'),
(1697737,58,47,1,6,'Mutta jos olemme ahdistuksessa, niin tapahtuu se teille lohdutukseksi ja pelastukseksi; jos taas saamme lohdutusta, niin tapahtuu sekin teille lohdutukseksi, ja se vaikuttaa, että te kestätte samat kärsimykset, joita mekin kärsimme; ja toivomme teistä on vahva,'),
(1697738,58,47,1,7,'koska me tiedämme, että samoin kuin olette osalliset kärsimyksistä, samoin olette osalliset myöskin lohdutuksesta.'),
(1697739,58,47,1,8,'Sillä me emme tahdo, veljet, pitää teitä tietämättöminä siitä ahdistuksesta, jossa me olimme Aasiassa, kuinka ylenpalttiset, yli voimiemme käyvät, meidän rasituksemme olivat, niin että jo olimme epätoivossa hengestämmekin,'),
(1697740,58,47,1,9,'ja itse me jo luulimme olevamme kuolemaan tuomitut, ettemme luottaisi itseemme, vaan Jumalaan, joka kuolleet herättää.'),
(1697741,58,47,1,10,'Ja hän pelasti meidät niin suuresta kuolemanvaarasta, ja yhä pelastaa, ja häneen me olemme panneet toivomme, että hän vielä vastakin pelastaa,'),
(1697742,58,47,1,11,'kun tekin autatte meitä rukouksillanne, että monesta suusta meidän tähtemme kohoaisi runsas kiitos siitä armosta, joka on osaksemme tullut.'),
(1697743,58,47,1,12,'Sillä meidän kerskauksemme on tämä: meidän omantuntomme todistus siitä, että me maailmassa ja varsinkin teidän luonanne olemme vaeltaneet Jumalan pyhyydessä ja puhtaudessa, emme lihallisessa viisaudessa, vaan Jumalan armossa.'),
(1697744,58,47,1,13,'Sillä eihän siinä, mitä teille kirjoitamme, ole muuta, kuin mikä siinä on luettavana ja minkä te myös ymmärrätte; ja minä toivon teidän loppuun asti ymmärtävän'),
(1697745,58,47,1,14,'- niinkuin meitä osaksi myös olette oppineet ymmärtämään - että me olemme teidän kerskauksenne, samoin kuin tekin meidän, Herramme Jeesuksen päivänä.'),
(1697746,58,47,1,15,'Ja tässä luottamuksessa minä aioin ensin tulla teidän tykönne, että saisitte vielä toisenkin todistuksen minun suosiostani,'),
(1697747,58,47,1,16,'ja sitten teidän kauttanne matkustaa Makedoniaan, ja taas Makedoniasta palata teidän tykönne ja teidän varustamananne matkata Juudeaan.'),
(1697748,58,47,1,17,'Kun minulla siis oli tämä aikomus, en kaiketi ole menetellyt kevytmielisesti? Vai päätänkö lihan mukaan, minkä päätän, niin että puheeni on sekä "on, on", että "ei, ei"?'),
(1697749,58,47,1,18,'Mutta Jumala sen takaa, että puheemme teille ei ole "on" ja "ei".'),
(1697750,58,47,1,19,'Sillä Jumalan Poika, Kristus Jeesus, jota me, minä ja Silvanus ja Timoteus, olemme teidän keskellänne saarnanneet, ei tullut ollakseen "on" ja "ei", vaan hänessä tuli "on".'),
(1697751,58,47,1,20,'Sillä niin monta kuin Jumalan lupausta on, kaikki ne ovat hänessä "on"; sentähden tulee hänen kauttaan myös niiden "amen", Jumalalle kunniaksi meidän kauttamme.'),
(1697752,58,47,1,21,'Mutta se, joka lujittaa meidät yhdessä teidän kanssanne Kristukseen ja joka on voidellut meidät, on Jumala,'),
(1697753,58,47,1,22,'joka myös on painanut meihin sinettinsä ja antanut Hengen vakuudeksi meidän sydämiimme.'),
(1697754,58,47,1,23,'Mutta minä kutsun Jumalan sieluni todistajaksi, että minä teitä säästääkseni en vielä tullut Korinttoon;'),
(1697755,58,47,1,24,'ei niin, että tahdomme vallita teidän uskoanne, vaan me yhdessä autamme teitä teidän iloonne; sillä uskossa te olette lujat.'),
(1697756,58,47,2,1,'Olin nimittäin mielessäni päättänyt, etten tullessani teidän tykönne taas toisi murhetta mukanani.'),
(1697757,58,47,2,2,'Sillä jos minä saatan teidät murheellisiksi, niin eihän minua voi saada iloiseksi kukaan muu kuin se, jonka minä olen murheelliseksi saattanut.'),
(1697758,58,47,2,3,'Ja juuri sen minä kirjoitin sitä varten, etten tullessani saisi murhetta niistä, joista minun piti saada iloa, koska minulla on teihin kaikkiin se luottamus, että minun iloni on kaikkien teidän ilonne.'),
(1697759,58,47,2,4,'Sillä suuressa sydämen ahdistuksessa ja hädässä minä kirjoitin teille monin kyynelin, en sitä varten, että te murheellisiksi tulisitte, vaan että tuntisitte sen erinomaisen rakkauden, joka minulla on teihin.'),
(1697760,58,47,2,5,'Mutta jos eräs on tuottanut murhetta, ei hän ole tuottanut murhetta minulle, vaan teille kaikille, jossakin määrin, etten liikaa sanoisi.'),
(1697761,58,47,2,6,'Semmoiselle riittää se rangaistus, minkä hän useimmilta on saanut;'),
(1697762,58,47,2,7,'niin että teidän päinvastoin ennemmin tulee antaa anteeksi ja lohduttaa, ettei hän ehkä menehtyisi liian suureen murheeseen.'),
(1697763,58,47,2,8,'Sentähden minä kehoitan teitä, että päätätte ruveta osoittamaan rakkautta häntä kohtaan;'),
(1697764,58,47,2,9,'sillä sitä varten minä kirjoitinkin, että saisin nähdä, kuinka te kestätte koetuksen, oletteko kaikessa kuuliaiset.'),
(1697765,58,47,2,10,'Mutta kenelle te jotakin anteeksi annatte, sille minäkin; sillä mitä minä olen anteeksi antanut - jos minulla on ollut jotakin anteeksiannettavaa - sen olen anteeksi antanut teidän tähtenne Kristuksen kasvojen edessä,'),
(1697766,58,47,2,11,'ettei saatana pääsisi meistä voitolle; sillä hänen juonensa eivät ole meille tuntemattomat.'),
(1697767,58,47,2,12,'Tultuani Trooaaseen julistamaan Kristuksen evankeliumia avautui minulle ovi työhön Herrassa,'),
(1697768,58,47,2,13,'mutta minä en saanut lepoa hengessäni, kun en tavannut Tiitusta, veljeäni. Sentähden sanoin heille jäähyväiset ja lähdin Makedoniaan.'),
(1697769,58,47,2,14,'Mutta kiitos olkoon Jumalan, joka aina kuljettaa meitä voittosaatossa Kristuksessa ja meidän kauttamme joka paikassa tuo ilmi hänen tuntemisensa tuoksun!'),
(1697770,58,47,2,15,'Sillä me olemme Kristuksen tuoksu Jumalalle sekä pelastuvien että kadotukseen joutuvien joukossa:'),
(1697771,58,47,2,16,'näille tosin kuoleman haju kuolemaksi, mutta noille elämän tuoksu elämäksi. Ja kuka on tällaiseen kelvollinen?'),
(1697772,58,47,2,17,'Sillä me emme ole niinkuin nuo monet, jotka myyskentelevät Jumalan sanaa; vaan puhtaasta mielestä, niinkuin Jumalan vaikutuksesta, Jumalan edessä, me Kristuksessa puhumme.'),
(1697773,58,47,3,1,'Alammeko taas suositella itseämme? Vai tarvinnemmeko, niinkuin muutamat, suosituskirjeitä teille tai teiltä?'),
(1697774,58,47,3,2,'Te itse olette meidän kirjeemme, joka on sydämeemme kirjoitettu ja jonka kaikki ihmiset tuntevat ja lukevat.'),
(1697775,58,47,3,3,'Sillä ilmeistä on, että te olette Kristuksen kirje, meidän palvelustyöllämme kirjoitettu, ei musteella, vaan elävän Jumalan Hengellä, ei kivitauluihin, vaan sydämen lihatauluihin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697776,58,47,3,4,'Tämmöinen luottamus meillä on Kristuksen kautta Jumalaan;'),
(1697777,58,47,3,5,'ei niin, että meillä itsellämme olisi kykyä ajatella jotakin, ikäänkuin se tulisi meistä itsestämme, vaan se kyky, mikä meillä on, on Jumalasta,'),
(1697778,58,47,3,6,'joka myös on tehnyt meidät kykeneviksi olemaan uuden liiton palvelijoita, ei kirjaimen, vaan Hengen; sillä kirjain kuolettaa, mutta Henki tekee eläväksi.'),
(1697779,58,47,3,7,'Mutta jos jo kuoleman virka, joka oli kirjaimin kaiverrettu kiviin, ilmestyi kirkkaudessa, niin etteivät Israelin lapset kärsineet katsella Mooseksen kasvoja hänen kasvojensa kirkkauden tähden, joka kuitenkin oli katoavaista,'),
(1697780,58,47,3,8,'kuinka paljoa enemmän onkaan Hengen virka oleva kirkkaudessa!'),
(1697781,58,47,3,9,'Sillä jos kadotustuomion virka jo oli kirkkautta, niin on vanhurskauden virka vielä paljoa runsaammassa määrin kirkkautta.'),
(1697782,58,47,3,10,'Sillä se, millä ennen oli kirkkaus, on tämän rinnalla kirkkautta vailla, tämän ylenpalttisen kirkkauden tähden.'),
(1697783,58,47,3,11,'Jos sillä, mikä on katoavaista, oli kirkkaus, niin vielä paljoa enemmän on sillä, mikä on pysyväistä, oleva kirkkautta.'),
(1697784,58,47,3,12,'Koska meillä siis on tämmöinen toivo, niin me olemme aivan rohkeat'),
(1697785,58,47,3,13,'emmekä tee niinkuin Mooses, joka pani peitteen kasvoillensa, etteivät Israelin lapset näkisi sen loppua, mikä on katoavaista.'),
(1697786,58,47,3,14,'Mutta heidän mielensä paatuivat, sillä vielä tänäkin päivänä sama peite, vanhan liiton kirjoituksia luettaessa, pysyy poisottamatta, sillä vasta Kristuksessa se katoaa.'),
(1697787,58,47,3,15,'Vielä tänäkin päivänä, kun Moosesta luetaan, on peite heidän sydämensä päällä;'),
(1697788,58,47,3,16,'mutta kun heidän sydämensä kääntyy Herran tykö, otetaan peite pois.'),
(1697789,58,47,3,17,'Sillä Herra on Henki, ja missä Herran Henki on, siinä on vapaus.'),
(1697790,58,47,3,18,'Mutta me kaikki, jotka peittämättömin kasvoin katselemme Herran kirkkautta kuin kuvastimesta, muutumme saman kuvan kaltaisiksi kirkkaudesta kirkkauteen, niinkuin muuttaa Herra, joka on Henki.'),
(1697791,58,47,4,1,'Sentähden, kun meillä on tämä virka sen laupeuden mukaan, joka on osaksemme tullut, me emme lannistu,'),
(1697792,58,47,4,2,'vaan olemme hyljänneet kaikki häpeälliset salatiet, niin ettemme vaella kavaluudessa emmekä väärennä Jumalan sanaa, vaan julkituomalla totuuden me suositamme itseämme jokaisen ihmisen omalletunnolle Jumalan edessä.'),
(1697793,58,47,4,3,'Mutta jos meidän evankeliumimme on peitossa, niin se peite on niissä, jotka kadotukseen joutuvat,'),
(1697794,58,47,4,4,'niissä uskottomissa, joiden mielet tämän maailman jumala on niin sokaissut, ettei heille loista valkeus, joka lähtee Kristuksen kirkkauden evankeliumista, hänen, joka on Jumalan kuva.'),
(1697795,58,47,4,5,'Sillä me emme julista itseämme, vaan Kristusta Jeesusta, että hän on Herra ja me teidän palvelijanne Jeesuksen tähden.'),
(1697796,58,47,4,6,'Sillä Jumala, joka sanoi: "Loistakoon valkeus pimeydestä", on se, joka loisti sydämiimme, että Jumalan kirkkauden tunteminen, sen kirkkauden, joka loistaa Kristuksen kasvoissa, levittäisi valoansa.'),
(1697797,58,47,4,7,'Mutta tämä aarre on meillä saviastioissa, että tuo suunnattoman suuri voima olisi Jumalan eikä näyttäisi tulevan meistä.'),
(1697798,58,47,4,8,'Me olemme kaikin tavoin ahdingossa, mutta emme umpikujassa, neuvottomat, mutta emme toivottomat,'),
(1697799,58,47,4,9,'vainotut, mutta emme hyljätyt, maahan kukistetut, mutta emme tuhotut.'),
(1697800,58,47,4,10,'Me kuljemme, aina kantaen Jeesuksen kuolemaa ruumiissamme, että Jeesuksen elämäkin tulisi meidän ruumiissamme näkyviin.'),
(1697801,58,47,4,11,'Sillä me, jotka elämme, olemme alati annetut kuolemaan Jeesuksen tähden, että Jeesuksen elämäkin tulisi kuolevaisessa lihassamme näkyviin.'),
(1697802,58,47,4,12,'Niinpä siis kuolema tekee työtään meissä, mutta elämä teissä.'),
(1697803,58,47,4,13,'Mutta koska meillä on sama uskon Henki, niinkuin kirjoitettu on: "Minä uskon, sentähden minä puhun", niin mekin uskomme, ja sentähden me myös puhumme,'),
(1697804,58,47,4,14,'tietäen, että hän, joka herätti Herran Jeesuksen, on herättävä meidätkin Jeesuksen kanssa ja asettava esiin yhdessä teidän kanssanne.'),
(1697805,58,47,4,15,'Sillä kaikki tapahtuu teidän tähtenne, että aina enenevä armo yhä useampien kautta saisi aikaan yhä runsaampaa kiitosta Jumalan kunniaksi.'),
(1697806,58,47,4,16,'Sentähden me emme lannistu; vaan vaikka ulkonainen ihmisemme menehtyykin, niin sisällinen kuitenkin päivä päivältä uudistuu.'),
(1697807,58,47,4,17,'Sillä tämä hetkisen kestävä ja kevyt ahdistuksemme tuottaa meille iankaikkisen ja määrättömän kirkkauden, ylenpalttisesti,'),
(1697808,58,47,4,18,'meille, jotka emme katso näkyväisiä, vaan näkymättömiä; sillä näkyväiset ovat ajallisia, mutta näkymättömät iankaikkisia.'),
(1697809,58,47,5,1,'Sillä me tiedämme, että vaikka tämä meidän maallinen majamme hajotetaankin maahan, meillä on asumus Jumalalta, iankaikkinen maja taivaissa, joka ei ole käsin tehty.'),
(1697810,58,47,5,2,'Sentähden me huokaammekin ikävöiden, että saisimme pukeutua taivaalliseen majaamme,'),
(1697811,58,47,5,3,'sillä kun me kerran olemme siihen pukeutuneet, ei meitä enää havaita alastomiksi.'),
(1697812,58,47,5,4,'Sillä me, jotka olemme tässä majassa, huokaamme raskautettuina, koska emme tahdo riisuutua, vaan pukeutua, että elämä nielisi sen, mikä on kuolevaista.'),
(1697813,58,47,5,5,'Mutta se, joka on valmistanut meidät juuri tähän, on Jumala, joka on antanut meille Hengen vakuudeksi.'),
(1697814,58,47,5,6,'Sentähden me aina olemme turvallisella mielellä ja tiedämme, että, niin kauan kuin olemme kotona tässä ruumiissamme, me olemme poissa Herrasta;'),
(1697815,58,47,5,7,'sillä me vaellamme uskossa emmekä näkemisessä.'),
(1697816,58,47,5,8,'Mutta me olemme turvallisella mielellä ja haluaisimme mieluummin muuttaa pois ruumiista ja päästä kotiin Herran tykö.'),
(1697817,58,47,5,9,'Sentähden me, olimmepa kotona tai olimmepa poissa, ahkeroitsemme olla hänelle mieliksi.'),
(1697818,58,47,5,10,'Sillä kaikkien meidän pitää ilmestymän Kristuksen tuomioistuimen eteen, että kukin saisi sen mukaan, kuin hän ruumiissa ollessaan on tehnyt, joko hyvää tai pahaa.'),
(1697819,58,47,5,11,'Kun siis tiedämme, mitä Herran pelko on, niin me koetamme saada ihmisiä uskomaan, mutta Jumala kyllä meidät tuntee; ja minä toivon, että tekin omissatunnoissanne meidät tunnette.'),
(1697820,58,47,5,12,'Emme nyt taas suosittele itseämme teille, vaan tahdomme antaa teille aihetta kerskata meistä, että teillä olisi mitä vastata niille, jotka kerskaavat siitä, mikä silmään näkyy, eikä siitä, mikä sydämessä on.'),
(1697821,58,47,5,13,'Sillä jos me olemme olleet suunniltamme, niin olemme olleet Jumalan tähden; jos taas maltamme mielemme, teemme sen teidän tähtenne.'),
(1697822,58,47,5,14,'Sillä Kristuksen rakkaus vaatii meitä, jotka olemme tulleet tähän päätökseen: yksi on kuollut kaikkien edestä, siis myös kaikki ovat kuolleet;'),
(1697823,58,47,5,15,'ja hän on kuollut kaikkien edestä, että ne, jotka elävät, eivät enää eläisi itselleen, vaan hänelle, joka heidän edestään on kuollut ja ylösnoussut.'),
(1697824,58,47,5,16,'Sentähden me emme tästä lähtien tunne ketään lihan mukaan; jos olemmekin tunteneet Kristuksen lihan mukaan, emme kuitenkaan nyt enää tunne.'),
(1697825,58,47,5,17,'Siis, jos joku on Kristuksessa, niin hän on uusi luomus; se, mikä on vanhaa, on kadonnut, katso, uusi on sijaan tullut.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697826,58,47,5,18,'Mutta kaikki on Jumalasta, joka on sovittanut meidät itsensä kanssa Kristuksen kautta ja antanut meille sovituksen viran.'),
(1697827,58,47,5,19,'Sillä Jumala oli Kristuksessa ja sovitti maailman itsensä kanssa eikä lukenut heille heidän rikkomuksiaan, ja hän uskoi meille sovituksen sanan.'),
(1697828,58,47,5,20,'Kristuksen puolesta me siis olemme lähettiläinä, ja Jumala kehoittaa meidän kauttamme. Me pyydämme Kristuksen puolesta: antakaa sovittaa itsenne Jumalan kanssa.'),
(1697829,58,47,5,21,'Sen, joka ei synnistä tiennyt, hän meidän tähtemme teki synniksi, että me hänessä tulisimme Jumalan vanhurskaudeksi.'),
(1697830,58,47,6,1,'Hänen työtovereinaan me myös kehoitamme teitä vastaanottamaan Jumalan armon niin, ettei se jää turhaksi.'),
(1697831,58,47,6,2,'Sillä hän sanoo: "Otollisella ajalla minä olen sinua kuullut ja pelastuksen päivänä sinua auttanut". Katso, nyt on otollinen aika, katso, nyt on pelastuksen päivä.'),
(1697832,58,47,6,3,'Me emme missään kohden anna aihetta pahennukseen, ettei virkaamme moitittaisi,'),
(1697833,58,47,6,4,'vaan kaikessa me osoittaudumme Jumalan palvelijoiksi: suuressa kärsivällisyydessä, vaivoissa, hädissä, ahdistuksissa,'),
(1697834,58,47,6,5,'ruoskittaessa, vankeudessa, meteleissä, vaivannäöissä, valvomisissa, paastoissa;'),
(1697835,58,47,6,6,'puhtaudessa, tiedossa, pitkämielisyydessä, ystävällisyydessä, Pyhässä Hengessä, vilpittömässä rakkaudessa,'),
(1697836,58,47,6,7,'totuuden sanassa, Jumalan voimassa, vanhurskauden sota-aseet oikeassa kädessä ja vasemmassa;'),
(1697837,58,47,6,8,'kunniassa ja häpeässä, pahassa maineessa ja hyvässä, villitsijöinä ja kuitenkin totta puhuvina,'),
(1697838,58,47,6,9,'tuntemattomina ja kuitenkin hyvin tunnettuina; kuolemaisillamme, ja katso, me elämme, kuritettuina emmekä kuitenkaan tapettuina,'),
(1697839,58,47,6,10,'murheellisina, mutta aina iloisina, köyhinä, mutta kuitenkin monia rikkaiksi tekevinä, mitään omistamatta, mutta kuitenkin omistaen kaiken.'),
(1697840,58,47,6,11,'Suumme on auennut puhumaan teille, korinttolaiset, sydämemme on avartunut.'),
(1697841,58,47,6,12,'Ei ole teillä ahdasta meidän sydämessämme, mutta ahdas on teidän oma sydämenne.'),
(1697842,58,47,6,13,'Antakaa verta verrasta - puhun kuin lapsilleni - avartukaa tekin.'),
(1697843,58,47,6,14,'Älkää antautuko kantamaan vierasta iestä yhdessä uskottomien kanssa; sillä mitä yhteistä on vanhurskaudella ja vääryydellä? Tai mitä yhteyttä on valkeudella ja pimeydellä?'),
(1697844,58,47,6,15,'Ja miten sopivat yhteen Kristus ja Beliar? Tai mitä yhteistä osaa uskovaisella on uskottoman kanssa?'),
(1697845,58,47,6,16,'Ja miten soveltuvat yhteen Jumalan temppeli ja epäjumalat? Sillä me olemme elävän Jumalan temppeli, niinkuin Jumala on sanonut: "Minä olen heissä asuva ja vaeltava heidän keskellään ja oleva heidän Jumalansa, ja he ovat minun kansani".'),
(1697846,58,47,6,17,'Sentähden: "Lähtekää pois heidän keskeltänsä ja erotkaa heistä, sanoo Herra, älkääkä saastaiseen koskeko; niin minä otan teidät huostaani'),
(1697847,58,47,6,18,'ja olen teidän Isänne, ja te tulette minun pojikseni ja tyttärikseni, sanoo Herra, Kaikkivaltias".'),
(1697848,58,47,7,1,'Koska meillä siis on nämä lupaukset, rakkaani, niin puhdistautukaamme kaikesta lihan ja hengen saastutuksesta, saattaen pyhityksemme täydelliseksi Jumalan pelossa.'),
(1697849,58,47,7,2,'Antakaa meille tilaa sydämessänne. Emme ole tehneet kenellekään vääryyttä, emme ole olleet kenellekään turmioksi, emme kenellekään vahinkoa tuottaneet.'),
(1697850,58,47,7,3,'En sano tätä tuomitakseni teitä, sillä olenhan jo sanonut, että te olette meidän sydämessämme, yhdessä kuollaksemme ja yhdessä elääksemme.'),
(1697851,58,47,7,4,'Paljon minulla on luottamusta teihin, paljon minulla on kerskaamista teistä; olen täynnä lohdutusta, minulla on ylenpalttinen ilo kaikessa ahdingossamme.'),
(1697852,58,47,7,5,'Sillä ei Makedoniaan tultuammekaan lihamme saanut mitään rauhaa, vaan me olimme kaikin tavoin ahdistetut: ulkoapäin taisteluja, sisältäpäin pelkoa.'),
(1697853,58,47,7,6,'Mutta Jumala, joka masentuneita lohduttaa, lohdutti meitä Tiituksen tulolla,'),
(1697854,58,47,7,7,'eikä ainoastaan hänen tulollansa, vaan myöskin sillä lohdutuksella, jonka hän oli teistä saanut, sillä hän on kertonut meille teidän ikävöimisestänne, valittelustanne ja innostanne minun hyväkseni, niin että minä iloitsin vielä enemmän.'),
(1697855,58,47,7,8,'Sillä vaikka murehutinkin teitä kirjeelläni, en sitä kadu, ja jos kaduinkin, niin minä - kun näen, että tuo kirje on, vaikkapa vain vähäksi aikaa, murehuttanut teitä -'),
(1697856,58,47,7,9,'nyt iloitsen, en siitä, että tulitte murheellisiksi, vaan siitä, että murheenne oli teille parannukseksi; sillä te tulitte murheellisiksi Jumalan mielen mukaan, ettei teillä olisi mitään vahinkoa meistä.'),
(1697857,58,47,7,10,'Sillä Jumalan mielen mukainen murhe saa aikaan parannuksen, joka koituu pelastukseksi ja jota ei kukaan kadu; mutta maailman murhe tuottaa kuoleman.'),
(1697858,58,47,7,11,'Sillä katsokaa, kuinka suurta intoa juuri tuo Jumalan mielen mukainen murehtimisenne on saanut teissä aikaan, mitä puolustautumista, mitä paheksumista, mitä pelkoa, ikävöimistä, kiivautta, mitä kurittamista! Olette kaikin tavoin osoittaneet olevanne puhtaat tässä asiassa.'),
(1697859,58,47,7,12,'Vaikka minä siis kirjoitinkin teille, en kirjoittanut vääryyttä tehneen enkä vääryyttä kärsineen vuoksi, vaan sentähden, että teidän intonne meidän hyväksemme tulisi julki teidän keskuudessanne Jumalan edessä.'),
(1697860,58,47,7,13,'Sentähden me olemme nyt lohdutetut. Mutta tämän lohdutuksemme ohessa on meitä vielä paljoa enemmän ilahuttanut Tiituksen ilo, sillä hänen henkensä on saanut virvoitusta teiltä kaikilta.'),
(1697861,58,47,7,14,'Sillä jos olenkin jossakin kohden teitä hänelle kehunut, en ole joutunut häpeään, vaan niinkuin kaikki, mitä olemme teille puhuneet, on totta, niin on myös se, mistä olemme teitä Tiitukselle kehuneet, osoittautunut todeksi.'),
(1697862,58,47,7,15,'Ja hänen sydämensä heltyy yhä enemmän teitä kohtaan, kun hän muistelee kaikkien teidän kuuliaisuuttanne, kuinka te pelolla ja vavistuksella otitte hänet vastaan.'),
(1697863,58,47,7,16,'Minä iloitsen, että kaikessa voin olla teistä turvallisella mielellä.'),
(1697864,58,47,8,1,'Mutta me saatamme teidän tietoonne, veljet, mitä Jumalan armo on vaikuttanut Makedonian seurakunnissa:'),
(1697865,58,47,8,2,'että, vaikka he olivatkin monessa ahdistuksen koetuksessa, niin oli heidän ilonsa heidän suuressa köyhyydessäänkin niin ylenpalttinen, että he alttiisti antoivat runsaita lahjoja.'),
(1697866,58,47,8,3,'Sillä voimiensa mukaan, sen minä todistan, jopa yli voimiensakin he antoivat omasta halustansa,'),
(1697867,58,47,8,4,'paljolla pyytämisellä anoen meiltä sitä suosiota, että pääsisivät osallisiksi pyhien avustamiseen;'),
(1697868,58,47,8,5,'eivätkä he vain tehneet, niinkuin me olimme toivoneet, vaan antoivat itsensäkin, ennen kaikkea Herralle ja sitten meille, Jumalan tahdosta,'),
(1697869,58,47,8,6,'niin että me kehoitimme Tiitusta, niinkuin hän jo oli alkanut, saattamaan teidän keskuudessanne päätökseen tämänkin rakkaudentyön.'),
(1697870,58,47,8,7,'Mutta niinkuin teillä on ylenpalttisesti kaikkea: uskoa, sanaa, tietoa, kaikkinaista intoa ja meistä teihin tullutta rakkautta, niin olkaa ylenpalttiset tässäkin rakkaudentyössä.'),
(1697871,58,47,8,8,'En sano tätä käskien, vaan viittaamalla muiden intoon minä tahdon koetella teidänkin rakkautenne vilpittömyyttä.'),
(1697872,58,47,8,9,'Sillä te tunnette meidän Herramme Jeesuksen Kristuksen armon, että hän, vaikka oli rikas, tuli teidän tähtenne köyhäksi, että te hänen köyhyydestään rikastuisitte.'),
(1697873,58,47,8,10,'Minä annan vain neuvon tässä asiassa; sillä se on hyödyksi teille, jotka jo viime vuonna olitte ensimmäiset, ette ainoastaan tekemässä, vaan myös tahtomassa.'),
(1697874,58,47,8,11,'Täyttäkää nyt siis tekonne, niin että, yhtä alttiisti kuin olitte sen päättäneet, sen myös täyttäisitte, varojenne mukaan.'),
(1697875,58,47,8,12,'Sillä jos on alttiutta, niin se on otollinen sen mukaan, kuin on varoja, eikä sen mukaan, kuin niitä ei ole.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697876,58,47,8,13,'Sillä ei ole tarkoitus, että muilla olisi huojennus, teillä rasitus, vaan tasauksen vuoksi tulkoon tätä nykyä teidän yltäkylläisyytenne heidän puutteensa hyväksi,'),
(1697877,58,47,8,14,'että heidänkin yltäkylläisyytensä tulisi teidän puutteenne hyväksi, niin että syntyisi tasaus,'),
(1697878,58,47,8,15,'niinkuin kirjoitettu on: "Joka oli paljon koonnut, sille ei jäänyt liikaa, ja joka oli koonnut vähän, siltä ei mitään puuttunut".'),
(1697879,58,47,8,16,'Mutta kiitos Jumalalle, joka antaa Tiituksen sydämeen saman innon teidän hyväksenne!'),
(1697880,58,47,8,17,'Sillä hän otti varteen minun kehoitukseni, innostuipa niinkin, että lähtee omasta halustaan teidän tykönne.'),
(1697881,58,47,8,18,'Ja me lähetämme hänen kanssaan veljen, jota evankeliumin julistamisesta kiitetään kaikissa seurakunnissa'),
(1697882,58,47,8,19,'ja jonka seurakunnat vielä sen lisäksi myös ovat valinneet matkatoveriksemme viemään tätä rakkauden lahjaa, joka on meidän toimitettavanamme itse Herran kunniaksi ja oman alttiutemme osoitukseksi.'),
(1697883,58,47,8,20,'Näin me teemme, ettei kukaan pääsisi moittimaan meitä mistään, mikä koskee tätä runsasta avustusta, joka on meidän toimitettavanamme.'),
(1697884,58,47,8,21,'Sillä me ahkeroitsemme sitä, mikä on hyvää ei ainoastaan Herran, vaan myös ihmisten edessä.'),
(1697885,58,47,8,22,'Ja näiden kanssa me lähetämme vielä erään veljemme, jonka intoa usein ja monessa asiassa olemme koetelleet ja joka nyt on entistä paljon innokkaampi, koska hänellä on niin suuri luottamus teihin.'),
(1697886,58,47,8,23,'Jos siis on puhe Tiituksesta, niin hän on minun toverini ja työkumppanini teidän hyväksenne; meidän veljemme taas ovat seurakuntien lähettiläitä, ovat Kristuksen kunnia.'),
(1697887,58,47,8,24,'Kun te siis osoitatte heille rakkauttanne ja näytätte todeksi sen, mistä me olemme teitä kehuneet, niin teette sen seurakuntien edessä.'),
(1697888,58,47,9,1,'Pyhien avustamisesta minun tosin on tarpeetonta kirjoittaa teille;'),
(1697889,58,47,9,2,'sillä minä tunnen teidän alttiutenne, ja siitä minä kehun teitä makedonialaisille, että näet Akaia on ollut valmiina menneestä vuodesta alkaen, ja niin on teidän intonne saanut sangen monta innostumaan.'),
(1697890,58,47,9,3,'Lähetän nyt kuitenkin nämä veljet, ettei kerskaamisemme teistä tässä kohden näyttäytyisi tyhjäksi, vaan että olisitte valmiit, niinkuin olen sanonut teidän olevan;'),
(1697891,58,47,9,4,'muutoin, jos makedonialaisia tulee minun kanssani ja he tapaavat teidät valmistumattomina, me - ettemme sanoisi te - ehkä joutuisimme häpeään tässä luottamuksessamme.'),
(1697892,58,47,9,5,'Olen siis katsonut tarpeelliseksi kehoittaa veljiä edeltäpäin lähtemään teidän tykönne ja toimittamaan valmiiksi ennen lupaamanne runsaan lahjan, niin että se olisi valmis runsaana eikä kitsaana.'),
(1697893,58,47,9,6,'Huomatkaa tämä: joka niukasti kylvää, se myös niukasti niittää, ja joka runsaasti kylvää, se myös runsaasti niittää.'),
(1697894,58,47,9,7,'Antakoon kukin, niinkuin hänen sydämensä vaatii, ei surkeillen eikä pakosta; sillä iloista antajaa Jumala rakastaa.'),
(1697895,58,47,9,8,'Ja Jumala on voimallinen antamaan teille ylenpalttisesti kaikkea armoa, että teillä kaikessa aina olisi kaikkea riittävästi, voidaksenne ylenpalttisesti tehdä kaikkinaista hyvää;'),
(1697896,58,47,9,9,'niinkuin kirjoitettu on: "Hän sirottelee, hän antaa köyhille, hänen vanhurskautensa pysyy iankaikkisesti".'),
(1697897,58,47,9,10,'Ja hän, joka antaa siemenen kylväjälle ja leivän ruuaksi, on antava teillekin ja enentävä kylvönne ja kasvattava teidän vanhurskautenne hedelmät,'),
(1697898,58,47,9,11,'niin että te kaikessa vaurastuen voitte vilpittömästi harjoittaa kaikkinaista anteliaisuutta, joka meidän kauttamme saa aikaan kiitosta Jumalalle.'),
(1697899,58,47,9,12,'Sillä tämä avustamispalvelus ei ainoastaan poista pyhien puutteita, vaan käy vieläkin hedelmällisemmäksi Jumalalle annettujen monien kiitosten kautta,'),
(1697900,58,47,9,13,'kun he, tästä teidän palveluksestanne huomattuaan, kuinka taattu teidän mielenne on, ylistävät Jumalaa siitä, että te näin alistuvaisesti tunnustaudutte Kristuksen evankeliumiin ja näin vilpittömästi olette ruvenneet yhteyteen heidän kanssaan ja kaikkien kanssa.'),
(1697901,58,47,9,14,'Ja hekin rukoilevat teidän edestänne ja ikävöivät teitä sen ylen runsaan Jumalan armon tähden, joka on teidän osaksenne tullut.'),
(1697902,58,47,10,1,'Minä, Paavali, itse kehoitan teitä Kristuksen laupeuden ja lempeyden kautta, minä, joka olen muka nöyrä kasvotusten teidän kanssanne, mutta poissa ollessani rohkea teitä kohtaan,'),
(1697903,58,47,10,2,'ja pyydän, ettei minun, kun tulen teidän tykönne, tarvitsisi käyttää sitä rohkeutta, millä aion luottavaisesti uskaltaa käydä eräiden kimppuun, jotka ajattelevat meistä, aivan kuin vaeltaisimme lihan mukaan.'),
(1697904,58,47,10,3,'Vaikka me vaellammekin lihassa, emme kuitenkaan lihan mukaan sodi;'),
(1697905,58,47,10,4,'sillä meidän sota-aseemme eivät ole lihalliset, vaan ne ovat voimalliset Jumalan edessä hajottamaan maahan linnoituksia.'),
(1697906,58,47,10,5,'Me hajotamme maahan järjen päätelmät ja jokaisen varustuksen, joka nostetaan Jumalan tuntemista vastaan, ja vangitsemme jokaisen ajatuksen kuuliaiseksi Kristukselle'),
(1697907,58,47,10,6,'ja olemme valmiit rankaisemaan kaikkea tottelemattomuutta, kunhan te ensin olette täysin kuuliaisiksi tulleet.'),
(1697908,58,47,10,7,'Nähkää, mitä silmäin edessä on. Jos joku on mielessään varma siitä, että hän on Kristuksen oma, ajatelkoon hän edelleen mielessään, että samoin kuin hän on Kristuksen, samoin olemme mekin.'),
(1697909,58,47,10,8,'Ja vaikka minä jonkun verran enemmänkin kerskaisin siitä vallastamme, jonka Herra on antanut teitä rakentaaksemme eikä kukistaaksemme, en ole häpeään joutuva.'),
(1697910,58,47,10,9,'Tämän minä sanon, ettei näyttäisi siltä, kuin peloittelisin teitä kirjeilläni.'),
(1697911,58,47,10,10,'Sillä hänen kirjeensä ovat, sanotaan, kyllä mahtavat ja pontevat, mutta ruumiillisesti läsnäollessaan hän on heikko, eikä hänen puheensa ole minkään arvoista.'),
(1697912,58,47,10,11,'Joka niin sanoo, ajatelkoon, että samaa, mitä me poissaolevina olemme kirjeissämme sanoissa, samaa me myös olemme läsnäolevina teoissa.'),
(1697913,58,47,10,12,'Sillä me emme rohkene lukeutua emmekä verrata itseämme eräisiin, jotka itseänsä suosittelevat; mutta he ovat ymmärtämättömiä, kun mittaavat itsensä omalla itsellään ja vertailevat itseään omaan itseensä.'),
(1697914,58,47,10,13,'Me taas emme rupea kerskaamaan yli määrän, vaan ainoastaan sen määrätyn vaikutusalan mukaan, minkä Jumala on asettanut meille määräksi, ulottuaksemme teihinkin asti.'),
(1697915,58,47,10,14,'Sillä me emme kurota itseämme liiaksi, ikäänkuin emme teihin ulottuisikaan, sillä olemmehan ehtineet Kristuksen evankeliumin julistamisessa teihinkin asti.'),
(1697916,58,47,10,15,'Emme kerskaa yli määrän, emme muiden vaivannäöistä, mutta meillä on se toivo, että teidän uskonne lisääntyessä me oman vaikutusalamme mukaan kasvamme teidän keskuudessanne niin suuriksi,'),
(1697917,58,47,10,16,'että saamme viedä evankeliumin myöskin tuolla puolen teitä oleviin maihin - tahtomatta kerskata siitä, mikä jo on valmista toisten vaikutusalalla.'),
(1697918,58,47,10,17,'Mutta joka kerskaa, hänen kerskauksenaan olkoon Herra.'),
(1697919,58,47,10,18,'Sillä ei se ole koetuksen kestävä, joka itse itseään suosittelee, vaan se, jota Herra suosittelee.'),
(1697920,58,47,11,1,'Jospa kärsisitte minulta hiukan mielettömyyttäkin! Ja kyllähän te minua kärsittekin.'),
(1697921,58,47,11,2,'Sillä minä kiivailen teidän puolestanne Jumalan kiivaudella; minähän olen kihlannut teidät miehelle, yhdelle ainoalle, asettaakseni Kristuksen eteen puhtaan neitsyen.'),
(1697922,58,47,11,3,'Mutta minä pelkään, että niinkuin käärme kavaluudellaan petti Eevan, niin teidän mielenne ehkä turmeltuu pois vilpittömyydestä ja puhtaudesta, joka teissä on Kristusta kohtaan.'),
(1697923,58,47,11,4,'Sillä jos joku tulee ja saarnaa jotakin toista Jeesusta kuin sitä, jota me olemme saarnanneet, tai jos te saatte toisen hengen, kuin minkä olette saaneet, tai toisen evankeliumin, kuin minkä olette vastaanottaneet, niin sen te hyvin kärsitte.'),
(1697924,58,47,11,5,'Mutta minä en katso itseäni missään suhteessa noita isoisia apostoleja huonommaksi.'),
(1697925,58,47,11,6,'Jos olenkin oppimaton puheessa, en kuitenkaan tiedossa; olemmehan tuoneet sen teille kaikin tavoin ilmi kaikissa asioissa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697926,58,47,11,7,'Vai olenko tehnyt syntiä siinä, että - alentaessani itseni, jotta te ylenisitte - olen ilmaiseksi julistanut teille Jumalan evankeliumia?'),
(1697927,58,47,11,8,'Muita seurakuntia minä riistin, ottaessani heiltä palkkaa palvellakseni teitä. Kun olin teidän luonanne ja kärsin puutetta, en rasittanut ketään.'),
(1697928,58,47,11,9,'Sillä mitä minulta puuttui, sen täyttivät veljet, jotka tulivat Makedoniasta; ja kaikessa minä varoin olemasta teille rasitukseksi, ja olen vastakin varova.'),
(1697929,58,47,11,10,'Niin totta kuin Kristuksen totuus on minussa, ei tätä kerskausta minulta riistetä Akaian maanäärissä.'),
(1697930,58,47,11,11,'Minkätähden? Senkötähden, etten muka rakasta teitä? Jumala tietää sen.'),
(1697931,58,47,11,12,'Mutta mitä minä teen, sen olen vastakin tekevä, riistääkseni aiheen niiltä, jotka aihetta etsivät, että heidät siinä, missä kerskaavat, havaittaisiin samankaltaisiksi kuin mekin.'),
(1697932,58,47,11,13,'Sillä semmoiset ovat valheapostoleja, petollisia työntekijöitä, jotka tekeytyvät Kristuksen apostoleiksi.'),
(1697933,58,47,11,14,'Eikä ihme; sillä itse saatana tekeytyy valkeuden enkeliksi.'),
(1697934,58,47,11,15,'Ei ole siis paljon, jos hänen palvelijansakin tekeytyvät vanhurskauden palvelijoiksi, mutta heidän loppunsa on oleva heidän tekojensa mukainen.'),
(1697935,58,47,11,16,'Vielä minä sanon: älköön kukaan luulko minua mielettömäksi; mutta vaikka olisinkin, ottakaa minut mieletönnäkin vastaan, että minäkin saisin hiukan kerskata.'),
(1697936,58,47,11,17,'Mitä nyt puhun, kun näin suurella luottamuksella kerskaan, sitä en puhu Herran mielen mukaan, vaan niinkuin mieletön.'),
(1697937,58,47,11,18,'Koska niin monet kerskaavat lihan mukaan, niin kerskaan minäkin.'),
(1697938,58,47,11,19,'Tehän hyvin suvaitsette mielettömiä, kun itse olette niin mieleviä.'),
(1697939,58,47,11,20,'Tehän suvaitsette, että joku teidät orjuuttaa, että joku teidät syö puhtaaksi, että joku teidät saa saaliiksensa, että joku itsensä korottaa, että joku lyö teitä kasvoihin.'),
(1697940,58,47,11,21,'Häpeäkseni sanon: tähän me kyllä olemme olleet liian heikkoja. Mutta minkä joku toinen uskaltaa - puhun kuin mieletön - sen uskallan minäkin.'),
(1697941,58,47,11,22,'He ovat hebrealaisia; minä myös. He ovat israelilaisia; minä myös. He ovat Aabrahamin siementä; minä myös.'),
(1697942,58,47,11,23,'He ovat Kristuksen palvelijoita - puhun kuin mieltä vailla - minä vielä enemmän. Olen nähnyt vaivaa enemmän, olen ollut useammin vankeudessa, minua on ruoskittu ylen paljon, olen monta kertaa ollut kuoleman vaarassa.'),
(1697943,58,47,11,24,'Juutalaisilta olen viidesti saanut neljäkymmentä lyöntiä, yhtä vaille;'),
(1697944,58,47,11,25,'kolmesti olen saanut raippoja, kerran minua kivitettiin, kolmesti olen joutunut haaksirikkoon, vuorokauden olen meressä ajelehtinut;'),
(1697945,58,47,11,26,'olen usein ollut matkoilla, vaaroissa virtojen vesillä, vaaroissa rosvojen keskellä, vaaroissa heimoni puolelta, vaaroissa pakanain puolelta, vaaroissa kaupungeissa, vaaroissa erämaassa, vaaroissa merellä, vaaroissa valheveljien keskellä;'),
(1697946,58,47,11,27,'ollut työssä ja vaivassa; paljon valvonut, kärsinyt nälkää ja janoa, paljon paastonnut, kärsinyt vilua ja alastomuutta.'),
(1697947,58,47,11,28,'Ja kaiken muun lisäksi jokapäiväistä tunkeilua luonani, huolta kaikista seurakunnista.'),
(1697948,58,47,11,29,'Kuka on heikko, etten minäkin olisi heikko? Kuka lankeaa, ettei se minua polttaisi?'),
(1697949,58,47,11,30,'Jos minun kerskata täytyy, niin kerskaan heikkoudestani.'),
(1697950,58,47,11,31,'Herran Jeesuksen Jumala ja Isä, joka on ylistetty iankaikkisesti, tietää, etten valhettele.'),
(1697951,58,47,11,32,'Damaskossa kuningas Aretaan käskynhaltija vartioi damaskolaisten kaupunkia ottaaksensa minut kiinni,'),
(1697952,58,47,11,33,'ja muurin ikkuna-aukosta minut laskettiin korissa maahan, ja niin minä pääsin hänen käsistänsä.'),
(1697953,58,47,12,1,'Minun täytyy kerskata; se tosin ei ole hyödyllistä, mutta minä siirryn nyt näkyihin ja Herran ilmestyksiin.'),
(1697954,58,47,12,2,'Tunnen miehen, joka on Kristuksessa: neljätoista vuotta sitten hänet temmattiin kolmanteen taivaaseen - oliko hän ruumiissaan, en tiedä, vai poissa ruumiista, en tiedä, Jumala sen tietää.'),
(1697955,58,47,12,3,'Ja minä tiedän, että tämä mies - oliko hän ruumiissaan vai poissa ruumiista, en tiedä, Jumala sen tietää -'),
(1697956,58,47,12,4,'temmattiin paratiisiin ja kuuli sanomattomia sanoja, joita ihmisen ei ole lupa puhua.'),
(1697957,58,47,12,5,'Tästä miehestä minä kerskaan, mutta itsestäni en kerskaa, paitsi heikkoudestani.'),
(1697958,58,47,12,6,'Sillä jos tahtoisinkin kerskata, en olisi mieletön, sillä minä puhuisin totta; mutta minä pidättäydyn siitä, ettei kukaan ajattelisi minusta enempää, kuin mitä näkee minun olevan tai mitä hän minusta kuulee.'),
(1697959,58,47,12,7,'Ja etten niin erinomaisten ilmestysten tähden ylpeilisi, on minulle annettu lihaani pistin, saatanan enkeli, rusikoimaan minua, etten ylpeilisi.'),
(1697960,58,47,12,8,'Tämän tähden olen kolmesti rukoillut Herraa, että se erkanisi minusta.'),
(1697961,58,47,12,9,'Ja hän sanoi minulle: "Minun armossani on sinulle kyllin; sillä minun voimani tulee täydelliseksi heikkoudessa". Sentähden minä mieluimmin kerskaan heikkoudestani, että Kristuksen voima asettuisi minuun asumaan.'),
(1697962,58,47,12,10,'Sentähden minä olen mielistynyt heikkouteen, pahoinpitelyihin, hätään, vainoihin, ahdistuksiin, Kristuksen tähden; sillä kun olen heikko, silloin minä olen väkevä.'),
(1697963,58,47,12,11,'Olen joutunut mielettömyyksiin; te olette minut siihen pakottaneet. Minunhan olisi pitänyt saada suositusta teiltä, sillä en ole missään ollut noita isoisia apostoleja huonompi, vaikka en olekaan mitään.'),
(1697964,58,47,12,12,'Onhan apostolin tunnusteot teidän keskuudessanne tehty kaikella kestävyydellä, tunnusmerkeillä ja ihmeillä ja voimateoilla.'),
(1697965,58,47,12,13,'Sillä missä muussa te olette jääneet muita seurakuntia vähemmälle kuin siinä, etten minä puolestani ole rasittanut teitä? Antakaa minulle anteeksi tämä vääryys.'),
(1697966,58,47,12,14,'Katso, kolmannen kerran minä nyt olen valmis tulemaan teidän tykönne, enkä ole oleva teille rasitukseksi; sillä minä en etsi teidän omaanne, vaan teitä itseänne. Eiväthän lapset ole velvolliset kokoamaan tavaraa vanhemmilleen, vaan vanhemmat lapsilleen.'),
(1697967,58,47,12,15,'Ja minä olen mielelläni uhraava kaikki, uhraava itsenikin, teidän sielujenne hyväksi. Senkötähden, että teitä näin suuresti rakastan, minä saan teiltä vähemmän vastarakkautta?'),
(1697968,58,47,12,16,'Olkoonpa niin, etten minä ole teitä rasittanut; mutta entä jos olen viekas ja olen kavaluudella kietonut teidät pauloihini!'),
(1697969,58,47,12,17,'Olenkohan minä kenenkään kautta, joita olen luoksenne lähettänyt, pyrkinyt teistä hyötymään?'),
(1697970,58,47,12,18,'Kehoitin Tiitusta menemään ja lähetin veljen hänen kanssaan; ei kai Tiitus ole pyrkinyt teistä hyötymään? Emmekö ole vaeltaneet samassa hengessä? Emmekö samoja jälkiä?'),
(1697971,58,47,12,19,'Olette kai jo kauan sitten luulleet, että me puolustaudumme teidän edessänne. Jumalan edessä, Kristuksessa me puhumme; mutta kaikki teille rakennukseksi, rakkaani.'),
(1697972,58,47,12,20,'Sillä minä pelkään, että tullessani ehkä en tapaa teitä semmoisina, kuin tahdon, ja että te tapaatte minut semmoisena, kuin te ette tahdo. Minä pelkään, että teidän keskuudessanne ehkä on riitaa, kateutta, vihaa, juonia, panetteluja, juoruja, pöyhkeilyä, epäjärjestyksiä;'),
(1697973,58,47,12,21,'ja että, kun tulen, Jumalani on taas nöyryyttävä minua teidän tykönänne, ja että joudun suremaan monen tähden, jotka ennen ovat synnissä eläneet eivätkä ole katuneet sitä saastaisuutta ja haureutta ja irstautta, jota ovat harjoittaneet.'),
(1697974,58,47,13,1,'Kolmannen kerran minä nyt tulen teidän tykönne. Kahden tai kolmen todistajan sanalla on jokainen asia vahvistettava.'),
(1697975,58,47,13,2,'Olen edeltäpäin sanonut ja sanon edeltäpäin niille, jotka ennen ovat syntiä tehneet, ja kaikille muille - niinkuin silloin sanoin, kun olin toista kertaa tykönänne, samoin nytkin, kun olen poissa - etten, kun taas tulen, ole teitä säästävä,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1697976,58,47,13,3,'koska te etsitte todistetta siitä, että minussa puhuu Kristus, joka ei ole heikko teitä kohtaan, vaan on teissä voimallinen.'),
(1697977,58,47,13,4,'Sillä vaikka hänet ristiinnaulittiin, kun hän oli heikko, elää hän kuitenkin Jumalan voimasta; olemmehan mekin hänessä heikot, mutta me elämme hänen kanssaan Jumalan voimasta teitä kohtaan.'),
(1697978,58,47,13,5,'Koetelkaa itseänne, oletteko uskossa; tutkikaa itseänne. Vai ettekö tunne itseänne, että Jeesus Kristus on teissä? Ellei, niin ette kestä koetusta.'),
(1697979,58,47,13,6,'Minä toivon teidän tulevan tuntemaan, että me emme ole niitä, jotka eivät koetusta kestä.'),
(1697980,58,47,13,7,'Mutta me rukoilemme Jumalaa, ettette tekisi mitään pahaa, emme sitä varten, että näyttäisi siltä, kuin me olisimme koetuksen kestäviä, vaan että te tekisitte hyvää ja me olisimme ikäänkuin ne, jotka eivät koetusta kestä.'),
(1697981,58,47,13,8,'Sillä me emme voi mitään totuutta vastaan, vaan totuuden puolesta.'),
(1697982,58,47,13,9,'Sillä me iloitsemme, kun me olemme heikot, mutta te olette voimalliset; sitä me rukoilemmekin, että te täydellisiksi tulisitte.'),
(1697983,58,47,13,10,'Sentähden minä kirjoitan tämän poissa ollessani, ettei minun teidän luonanne ollessani tarvitsisi käyttää ankaruutta sen vallan nojalla, minkä Herra on minulle antanut rakentamiseksi, ei kukistamiseksi.'),
(1697984,58,47,13,11,'Lopuksi, veljet, iloitkaa, tulkaa täydellisiksi, ottakaa vastaan kehoituksia, olkaa yhtä mieltä, eläkää sovussa, niin rakkauden ja rauhan Jumala on oleva teidän kanssanne.'),
(1697985,58,47,13,12,'Tervehtikää toisianne pyhällä suunannolla. Kaikki pyhät lähettävät teille tervehdyksen.'),
(1697986,58,47,13,13,'Herran Jeesuksen Kristuksen armo ja Jumalan rakkaus ja Pyhän Hengen osallisuus olkoon kaikkien teidän kanssanne.'),
(1697987,58,47,19,15,'Kiitos Jumalalle hänen sanomattomasta lahjastaan!'),
(1697988,58,48,1,1,'Paavali, apostoli, virkansa saanut, ei ihmisiltä eikä ihmisen kautta, vaan Jeesuksen Kristuksen kautta ja Isän Jumalan, joka on hänet kuolleista herättänyt,'),
(1697989,58,48,1,2,'ja kaikki veljet, jotka ovat minun kanssani, Galatian seurakunnille.'),
(1697990,58,48,1,3,'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta,'),
(1697991,58,48,1,4,'joka antoi itsensä alttiiksi meidän syntiemme tähden, pelastaaksensa meidät nykyisestä pahasta maailmanajasta meidän Jumalamme ja Isämme tahdon mukaan!'),
(1697992,58,48,1,5,'Hänen olkoon kunnia aina ja iankaikkisesti! Amen.'),
(1697993,58,48,1,6,'Minua kummastuttaa, että te niin äkkiä käännytte hänestä, joka on kutsunut teidät Kristuksen armossa, pois toisenlaiseen evankeliumiin,'),
(1697994,58,48,1,7,'joka kuitenkaan ei ole mikään toinen; on vain eräitä, jotka hämmentävät teitä ja tahtovat vääristellä Kristuksen evankeliumin.'),
(1697995,58,48,1,8,'Mutta vaikka me, tai vaikka enkeli taivaasta julistaisi teille evankeliumia, joka on vastoin sitä, minkä me olemme teille julistaneet, hän olkoon kirottu.'),
(1697996,58,48,1,9,'Niinkuin ennenkin olemme sanoneet, niin sanon nytkin taas: jos joku julistaa teille evankeliumia, joka on vastoin sitä, minkä te olette saaneet, hän olkoon kirottu.'),
(1697997,58,48,1,10,'Ihmistenkö suosiota minä nyt etsin vai Jumalan? Tai ihmisillekö pyydän olla mieliksi? Jos minä vielä tahtoisin olla ihmisille mieliksi, en olisi Kristuksen palvelija.'),
(1697998,58,48,1,11,'Sillä minä teen teille tiettäväksi, veljet, että minun julistamani evankeliumi ei ole ihmisten mukaista;'),
(1697999,58,48,1,12,'enkä minä olekaan sitä ihmisiltä saanut, eikä sitä ole minulle opetettu, vaan Jeesus Kristus on sen minulle ilmoittanut.'),
(1698000,58,48,1,13,'Olettehan kuulleet minun entisestä vaelluksestani juutalaisuudessa, että minä ylenmäärin vainosin Jumalan seurakuntaa ja sitä hävitin'),
(1698001,58,48,1,14,'ja että edistyin juutalaisuudessa pitemmälle kuin monet samanikäiset heimossani ja ylen innokkaasti kiivailin isieni perinnäissääntöjen puolesta.'),
(1698002,58,48,1,15,'Mutta kun hän, joka äitini kohdusta saakka on minut erottanut ja kutsunut armonsa kautta, näki hyväksi'),
(1698003,58,48,1,16,'ilmaista minussa Poikansa, että minä julistaisin evankeliumia hänestä pakanain seassa, niin minä heti alunpitäenkään en kysynyt neuvoa lihalta ja vereltä,'),
(1698004,58,48,1,17,'enkä lähtenyt ylös Jerusalemiin niiden luo, jotka ennen minua olivat apostoleja, vaan menin pois Arabiaan ja palasin taas takaisin Damaskoon.'),
(1698005,58,48,1,18,'Sitten, kolmen vuoden kuluttua, minä menin ylös Jerusalemiin tutustuakseni Keefaaseen ja jäin hänen tykönsä viideksitoista päiväksi.'),
(1698006,58,48,1,19,'Mutta muita apostoleja minä en nähnyt; näin ainoastaan Jaakobin, Herran veljen.'),
(1698007,58,48,1,20,'Ja mitä kirjoitan teille, katso, Jumalan kasvojen edessä minä sanon, etten valhettele.'),
(1698008,58,48,1,21,'Sitten menin Syyrian ja Kilikian paikkakuntiin.'),
(1698009,58,48,1,22,'Mutta olin kasvoiltani tuntematon Juudean seurakunnille, jotka ovat Kristuksessa.'),
(1698010,58,48,1,23,'Heidän kuuloonsa oli vain tullut: "Meidän entinen vainoojamme julistaa nyt sitä uskoa, jota hän ennen hävitti";'),
(1698011,58,48,1,24,'ja he ylistivät Jumalaa minun tähteni.'),
(1698012,58,48,2,1,'Sitten, neljäntoista vuoden kuluttua, minä taas menin ylös Jerusalemiin Barnabaan kanssa ja otin Tiituksenkin mukaani.'),
(1698013,58,48,2,2,'Mutta minä menin sinne ilmestyksen johdosta ja esitin heille sen evankeliumin, jota julistan pakanain keskuudessa; esitin sen yksityisesti arvokkaimmille heistä, etten ehkä juoksisi tai olisi juossut turhaan.'),
(1698014,58,48,2,3,'Mutta ei edes seuralaistani Tiitusta, joka oli kreikkalainen, pakotettu ympärileikkauttamaan itseänsä.'),
(1698015,58,48,2,4,'Noiden pariimme luikertaneiden valheveljien tähden, jotka orjuuttaakseen meitä olivat hiipineet vakoilemaan vapauttamme, mikä meillä on Kristuksessa Jeesuksessa,'),
(1698016,58,48,2,5,'me emme hetkeksikään alistuneet antamaan heille myöten, että evankeliumin totuus säilyisi teidän keskuudessanne.'),
(1698017,58,48,2,6,'Ja nuo, joita jonakin pidettiin - millaisia lienevät olleet, ei kuulu minuun; Jumala ei katso henkilöön - nuo arvossapidetyt eivät velvoittaneet minua mihinkään enempään,'),
(1698018,58,48,2,7,'vaan päinvastoin, kun näkivät, että minulle oli uskottu evankeliumin julistaminen ympärileikkaamattomille, samoin kuin Pietarille sen julistaminen ympärileikatuille -'),
(1698019,58,48,2,8,'sillä hän, joka antoi Pietarille voimaa hänen apostolintoimeensa ympärileikattujen keskuudessa, antoi minullekin siihen voimaa pakanain keskuudessa -'),
(1698020,58,48,2,9,'ja kun olivat tulleet tuntemaan sen armon, mikä oli minulle annettu, niin Jaakob ja Keefas ja Johannes, joita pidettiin pylväinä, antoivat minulle ja Barnabaalle yhteisen työn merkiksi kättä, mennäksemme, me pakanain keskuuteen ja he ympärileikattujen.'),
(1698021,58,48,2,10,'Meidän oli vain muistaminen köyhiä, ja juuri sitä minä olenkin ahkeroinut tehdä.'),
(1698022,58,48,2,11,'Mutta kun Keefas tuli Antiokiaan, vastustin minä häntä vasten kasvoja, koska hän oli herättänyt suurta paheksumista.'),
(1698023,58,48,2,12,'Sillä ennenkuin Jaakobin luota oli tullut muutamia miehiä, oli hän syönyt yhdessä pakanain kanssa; mutta heidän tultuaan hän vetäytyi pois ja pysytteli erillään peläten ympärileikattuja,'),
(1698024,58,48,2,13,'ja hänen kanssaan lankesivat ulkokultaisuuteen muutkin juutalaiset, niin että heidän ulkokultaisuutensa tempasi mukaansa Barnabaankin.'),
(1698025,58,48,2,14,'Mutta kun minä näin, etteivät he vaeltaneet suoraan evankeliumin totuuden mukaan, sanoin minä Keefaalle kaikkien kuullen: "Jos sinä, joka olet juutalainen, noudatat pakanain tapoja etkä juutalaisten, miksi sinä pakotat pakanoita noudattamaan juutalaisten tapoja?"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698026,58,48,2,15,'Me olemme luonnostamme juutalaisia, emmekä pakanasyntisiä;'),
(1698027,58,48,2,16,'mutta koska tiedämme, ettei ihminen tule vanhurskaaksi lain teoista, vaan uskon kautta Jeesukseen Kristukseen, niin olemme mekin uskoneet Kristukseen Jeesukseen tullaksemme vanhurskaiksi uskosta Kristukseen eikä lain teoista, koska ei mikään liha tule vanhurskaaksi lain teoista.'),
(1698028,58,48,2,17,'Mutta jos meidät itsemmekin, pyrkiessämme vanhurskautumaan Kristuksessa, on havaittu syntisiksi, onko sitten Kristus synnin palvelija? Pois se!'),
(1698029,58,48,2,18,'Sillä jos minä uudestaan rakennan sen, minkä olen hajottanut maahan, osoitan minä olevani lain rikkoja.'),
(1698030,58,48,2,19,'Sillä minä olen lain kautta kuollut pois laista, elääkseni Jumalalle. Minä olen Kristuksen kanssa ristiinnaulittu,'),
(1698031,58,48,2,20,'ja minä elän, en enää minä, vaan Kristus elää minussa; ja minkä nyt elän lihassa, sen minä elän Jumalan Pojan uskossa, hänen, joka on rakastanut minua ja antanut itsensä minun edestäni.'),
(1698032,58,48,2,21,'En minä tee mitättömäksi Jumalan armoa, sillä jos vanhurskaus on saatavissa lain kautta, silloinhan Kristus on turhaan kuollut.'),
(1698033,58,48,3,1,'Oi te älyttömät galatalaiset! Kuka on lumonnut teidät, joiden silmäin eteen Jeesus Kristus oli kuvattu ristiinnaulittuna?'),
(1698034,58,48,3,2,'Tämän vain tahdon saada teiltä tietää: lain teoistako saitte Hengen vai uskossa kuulemisesta?'),
(1698035,58,48,3,3,'Niinkö älyttömiä olette? Te alotitte Hengessä, lihassako nyt lopetatte?'),
(1698036,58,48,3,4,'Niin paljonko olette turhaan kärsineet? - jos se on turhaa ollut.'),
(1698037,58,48,3,5,'Joka siis antaa teille Hengen ja tekee voimallisia tekoja teidän keskuudessanne, saako hän sen aikaan lain tekojen vai uskossa kuulemisen kautta,'),
(1698038,58,48,3,6,'samalla tavalla kuin "Aabraham uskoi Jumalaa, ja se luettiin hänelle vanhurskaudeksi"?'),
(1698039,58,48,3,7,'Tietäkää siis, että ne, jotka uskoon perustautuvat, ovat Aabrahamin lapsia.'),
(1698040,58,48,3,8,'Ja koska Raamattu edeltäpäin näki, että Jumala vanhurskauttaa pakanat uskosta, julisti se Aabrahamille edeltäpäin tämän hyvän sanoman: "Sinussa kaikki kansat tulevat siunatuiksi".'),
(1698041,58,48,3,9,'Niinmuodoin ne, jotka perustautuvat uskoon, siunataan uskovan Aabrahamin kanssa.'),
(1698042,58,48,3,10,'Sillä kaikki, jotka perustautuvat lain tekoihin, ovat kirouksen alaisia; sillä kirjoitettu on: "Kirottu olkoon jokainen, joka ei pysy kaikessa, mikä on kirjoitettuna lain kirjassa, niin että hän sen tekee".'),
(1698043,58,48,3,11,'Ja selvää on, ettei kukaan tule vanhurskaaksi Jumalan edessä lain kautta, koska "vanhurskas on elävä uskosta".'),
(1698044,58,48,3,12,'Mutta laki ei perustaudu uskoon, vaan: "Joka ne täyttää, on niistä elävä".'),
(1698045,58,48,3,13,'Kristus on lunastanut meidät lain kirouksesta, kun hän tuli kiroukseksi meidän edestämme - sillä kirjoitettu on: "Kirottu on jokainen, joka on puuhun ripustettu" -'),
(1698046,58,48,3,14,'että Aabrahamin siunaus tulisi Jeesuksessa Kristuksessa pakanain osaksi ja me niin uskon kautta saisimme luvatun Hengen.'),
(1698047,58,48,3,15,'Veljet, minä puhun ihmisten tavalla. Eihän kukaan voi kumota ihmisenkään vahvistettua testamenttia eikä siihen mitään lisätä.'),
(1698048,58,48,3,16,'Mutta nyt lausuttiin lupaukset Aabrahamille ja hänen siemenelleen. Hän ei sano: "Ja siemenille", ikäänkuin monesta, vaan ikäänkuin yhdestä: "Ja sinun siemenellesi", joka on Kristus.'),
(1698049,58,48,3,17,'Minä tarkoitan tätä: Jumalan ennen vahvistamaa testamenttia ei neljänsadan kolmenkymmenen vuoden perästä tullut laki voi kumota, niin että se tekisi lupauksen mitättömäksi.'),
(1698050,58,48,3,18,'Sillä jos perintö tulisi laista, niin se ei enää tulisikaan lupauksesta. Mutta Aabrahamille Jumala on sen lahjoittanut lupauksen kautta.'),
(1698051,58,48,3,19,'Mitä varten sitten on laki? Se on rikkomusten tähden jäljestäpäin lisätty olemaan siihen asti, kunnes oli tuleva se siemen, jolle lupaus oli annettu; ja se säädettiin enkelien kautta, välimiehen kädellä.'),
(1698052,58,48,3,20,'Välimies taas ei ole yhtä varten; mutta Jumala on yksi.'),
(1698053,58,48,3,21,'Onko sitten laki vastoin Jumalan lupauksia? Pois se! Sillä jos olisi annettu laki, joka voisi eläväksi tehdä, niin vanhurskaus todella tulisi laista.'),
(1698054,58,48,3,22,'Mutta Raamattu on sulkenut kaikki synnin alle, että se, mikä luvattu oli, annettaisiin uskosta Jeesukseen Kristukseen niille, jotka uskovat.'),
(1698055,58,48,3,23,'Mutta ennenkuin usko tuli, vartioitiin meitä lain alle suljettuina uskoa varten, joka oli vastedes ilmestyvä.'),
(1698056,58,48,3,24,'Niinmuodoin on laista tullut meille kasvattaja Kristukseen, että me uskosta vanhurskaiksi tulisimme.'),
(1698057,58,48,3,25,'Mutta uskon tultua me emme enää ole kasvattajan alaisia.'),
(1698058,58,48,3,26,'Sillä te olette kaikki uskon kautta Jumalan lapsia Kristuksessa Jeesuksessa.'),
(1698059,58,48,3,27,'Sillä kaikki te, jotka olette Kristukseen kastetut, olette Kristuksen päällenne pukeneet.'),
(1698060,58,48,3,28,'Ei ole tässä juutalaista eikä kreikkalaista, ei ole orjaa eikä vapaata, ei ole miestä eikä naista; sillä kaikki te olette yhtä Kristuksessa Jeesuksessa.'),
(1698061,58,48,3,29,'Mutta jos te olette Kristuksen omat, niin te siis olette Aabrahamin siementä, perillisiä lupauksen mukaan.'),
(1698062,58,48,4,1,'Mutta minä sanon: niin kauan kuin perillinen on alaikäinen, ei hän missään kohden eroa orjasta, vaikka hän onkin kaiken herra;'),
(1698063,58,48,4,2,'vaan hän on holhoojain ja huoneenhaltijain alainen isän määräämään aikaan asti.'),
(1698064,58,48,4,3,'Samoin mekin; kun olimme alaikäisiä, olimme orjuutetut maailman alkeisvoimien alle.'),
(1698065,58,48,4,4,'Mutta kun aika oli täytetty, lähetti Jumala Poikansa, vaimosta syntyneen, lain alaiseksi syntyneen,'),
(1698066,58,48,4,5,'lunastamaan lain alaiset, että me pääsisimme lapsen asemaan.'),
(1698067,58,48,4,6,'Ja koska te olette lapsia, on Jumala lähettänyt meidän sydämeemme Poikansa Hengen, joka huutaa: "Abba! Isä!"'),
(1698068,58,48,4,7,'Niinpä sinä et siis enää ole orja, vaan lapsi; mutta jos olet lapsi, olet myös perillinen Jumalan kautta.'),
(1698069,58,48,4,8,'Mutta silloin, kun ette tunteneet Jumalaa, te palvelitte jumalia, jotka luonnostaan eivät jumalia ole.'),
(1698070,58,48,4,9,'Nyt sitävastoin, kun olette tulleet tuntemaan Jumalan ja, mikä enemmän on, kun Jumala tuntee teidät, kuinka te jälleen käännytte noiden heikkojen ja köyhien alkeisvoimien puoleen, joiden orjiksi taas uudestaan tahdotte tulla?'),
(1698071,58,48,4,10,'Te otatte vaarin päivistä ja kuukausista ja juhla-ajoista ja vuosista.'),
(1698072,58,48,4,11,'Minä pelkään teidän tähtenne, että olen ehkä turhaan teistä vaivaa nähnyt.'),
(1698073,58,48,4,12,'Tulkaa minun kaltaisikseni, koska minäkin olen tullut teidän kaltaiseksenne, veljet, minä pyydän sitä teiltä. Ette ole minua mitenkään loukanneet.'),
(1698074,58,48,4,13,'Tiedättehän, että ruumiillinen heikkous oli syynä siihen, että minä ensi kerralla julistin teille evankeliumia,'),
(1698075,58,48,4,14,'ja tiedätte, mikä kiusaus teillä oli minun ruumiillisesta tilastani; ette minua halveksineet ettekä vieroneet, vaan otitte minut vastaan niinkuin Jumalan enkelin, jopa niinkuin Kristuksen Jeesuksen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698076,58,48,4,15,'Missä on nyt teiltä kerskaaminen onnestanne? Sillä minä annan teistä sen todistuksen, että te, jos se olisi ollut mahdollista, olisitte kaivaneet silmät päästänne ja antaneet minulle.'),
(1698077,58,48,4,16,'Onko minusta siis tullut teidän vihamiehenne sentähden, että minä puhun teille totuuden?'),
(1698078,58,48,4,17,'Heillä on intoa teidän hyväksenne, mutta ei oikeata; vaan he tahtovat eristää teidät, että teillä olisi intoa heidän hyväksensä.'),
(1698079,58,48,4,18,'On hyvä, jos osoitetaan intoa hyvässä asiassa aina, eikä ainoastaan silloin, kun minä olen teidän tykönänne.'),
(1698080,58,48,4,19,'Lapsukaiseni, jotka minun jälleen täytyy kivulla synnyttää, kunnes Kristus saa muodon teissä,'),
(1698081,58,48,4,20,'tahtoisinpa nyt olla teidän tykönänne ja äänenikin muuttaa! Sillä minä olen aivan ymmällä teistä.'),
(1698082,58,48,4,21,'Sanokaa minulle te, jotka tahdotte lain alaisia olla, ettekö kuule, mitä laki sanoo?'),
(1698083,58,48,4,22,'Onhan kirjoitettu, että Aabrahamilla oli kaksi poikaa, toinen orjattaresta, toinen vapaasta.'),
(1698084,58,48,4,23,'Mutta orjattaren poika oli syntynyt lihan mukaan, vapaan taas lupauksen voimasta.'),
(1698085,58,48,4,24,'Tämä on kuvannollista puhetta; nämä naiset ovat kaksi liittoa: toinen on Siinain vuorelta, joka synnyttää orjuuteen, ja se on Haagar;'),
(1698086,58,48,4,25,'sillä Haagar on Siinain vuori Arabiassa ja vastaa nykyistä Jerusalemia, joka elää orjuudessa lapsineen.'),
(1698087,58,48,4,26,'Mutta se Jerusalem, joka ylhäällä on, on vapaa, ja se on meidän äitimme.'),
(1698088,58,48,4,27,'Sillä kirjoitettu on: "Iloitse, sinä hedelmätön, joka et synnytä, riemahda ja huuda sinä, jolla ei ole synnytyskipuja. Sillä yksinäisellä on paljon lapsia, enemmän kuin sillä, jolla on mies."'),
(1698089,58,48,4,28,'Ja te, veljet, olette lupauksen lapsia, niinkuin Iisak oli.'),
(1698090,58,48,4,29,'Mutta niinkuin lihan mukaan syntynyt silloin vainosi Hengen mukaan syntynyttä, niin nytkin.'),
(1698091,58,48,4,30,'Mutta mitä sanoo Raamattu? "Aja pois orjatar poikinensa; sillä orjattaren poika ei saa periä vapaan vaimon pojan kanssa."'),
(1698092,58,48,4,31,'Niin me siis, veljet, emme ole orjattaren lapsia, vaan vapaan.'),
(1698093,58,48,5,1,'Vapauteen Kristus vapautti meidät. Pysykää siis lujina, älkääkä antako uudestaan sitoa itseänne orjuuden ikeeseen.'),
(1698094,58,48,5,2,'Katso, minä, Paavali, sanon teille, että jos ympärileikkautatte itsenne, niin Kristus ei ole oleva teille miksikään hyödyksi.'),
(1698095,58,48,5,3,'Ja minä todistan taas jokaiselle ihmiselle, joka ympärileikkauttaa itsensä, että hän on velvollinen täyttämään kaiken lain.'),
(1698096,58,48,5,4,'Te olette joutuneet pois Kristuksesta, te, jotka tahdotte lain kautta tulla vanhurskaiksi; te olette langenneet pois armosta.'),
(1698097,58,48,5,5,'Sillä me odotamme uskosta vanhurskauden toivoa Hengen kautta.'),
(1698098,58,48,5,6,'Sillä Kristuksessa Jeesuksessa ei auta ympärileikkaus eikä ympärileikkaamattomuus, vaan rakkauden kautta vaikuttava usko.'),
(1698099,58,48,5,7,'Te juoksitte hyvin; kuka esti teitä olemasta totuudelle kuuliaisia?'),
(1698100,58,48,5,8,'Houkutus siihen ei ole hänestä, joka teitä kutsuu.'),
(1698101,58,48,5,9,'Vähäinen hapatus hapattaa koko taikinan.'),
(1698102,58,48,5,10,'Minulla on teihin se luottamus Herrassa, että te ette missään kohden tule ajattelemaan toisin; mutta teidän häiritsijänne saa kantaa tuomionsa, olkoon kuka hyvänsä.'),
(1698103,58,48,5,11,'Mutta jos minä, veljet, vielä saarnaan ympärileikkausta, miksi minua vielä vainotaan? Silloinhan olisi ristin pahennus poistettu.'),
(1698104,58,48,5,12,'Kunpa aivan silpoisivat itsensä, nuo teidän kiihoittajanne!'),
(1698105,58,48,5,13,'Te olette näet kutsutut vapauteen, veljet; älkää vain salliko vapauden olla yllykkeeksi lihalle, vaan palvelkaa toisianne rakkaudessa.'),
(1698106,58,48,5,14,'Sillä kaikki laki on täytetty yhdessä käskysanassa, tässä: "Rakasta lähimmäistäsi niinkuin itseäsi".'),
(1698107,58,48,5,15,'Mutta jos te purette ja syötte toisianne, katsokaa, ettette toinen toistanne perin hävitä.'),
(1698108,58,48,5,16,'Minä sanon: vaeltakaa Hengessä, niin ette lihan himoa täytä.'),
(1698109,58,48,5,17,'Sillä liha himoitsee Henkeä vastaan, ja Henki lihaa vastaan; nämä ovat nimittäin toisiansa vastaan, niin että te ette tee sitä, mitä tahdotte.'),
(1698110,58,48,5,18,'Mutta jos te olette Hengen kuljetettavina, niin ette ole lain alla.'),
(1698111,58,48,5,19,'Mutta lihan teot ovat ilmeiset, ja ne ovat: haureus, saastaisuus, irstaus,'),
(1698112,58,48,5,20,'epäjumalanpalvelus, noituus, vihamielisyys, riita, kateellisuus, vihat, juonet, eriseurat, lahkot,'),
(1698113,58,48,5,21,'kateus, juomingit, mässäykset ja muut senkaltaiset, joista teille edeltäpäin sanon, niinkuin jo ennenkin olen sanonut, että ne, jotka semmoista harjoittavat, eivät peri Jumalan valtakuntaa.'),
(1698114,58,48,5,22,'Mutta Hengen hedelmä on rakkaus, ilo, rauha, pitkämielisyys, ystävällisyys, hyvyys, uskollisuus, sävyisyys, itsensähillitseminen.'),
(1698115,58,48,5,23,'Sellaista vastaan ei ole laki.'),
(1698116,58,48,5,24,'Ja ne, jotka ovat Kristuksen Jeesuksen omat, ovat ristiinnaulinneet lihansa himoineen ja haluineen.'),
(1698117,58,48,5,25,'Jos me Hengessä elämme, niin myös Hengessä vaeltakaamme.'),
(1698118,58,48,5,26,'Älkäämme olko turhan kunnian pyytäjiä, niin että toisiamme ärsyttelemme, toisiamme kadehdimme.'),
(1698119,58,48,6,1,'Veljet, jos joku tavataan jostakin rikkomuksesta, niin ojentakaa te, hengelliset, häntä sävyisyyden hengessä; ja ole varuillasi, ettet sinäkin joutuisi kiusaukseen.'),
(1698120,58,48,6,2,'Kantakaa toistenne kuormia, ja niin te täytätte Kristuksen lain.'),
(1698121,58,48,6,3,'Sillä jos joku luulee jotakin olevansa, vaikka ei ole mitään, niin hän pettää itsensä.'),
(1698122,58,48,6,4,'Mutta tutkikoon kukin omat tekonsa, ja silloin hänen kerskaamisensa on vain siinä, mitä hän itse on, ei siinä, mitä toinen on;'),
(1698123,58,48,6,5,'sillä kunkin on kannettava oma taakkansa.'),
(1698124,58,48,6,6,'Jolle sanaa opetetaan, se jakakoon kaikkea hyvää opettajallensa.'),
(1698125,58,48,6,7,'Älkää eksykö, Jumala ei salli itseänsä pilkata; sillä mitä ihminen kylvää, sitä hän myös niittää.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698126,58,48,6,8,'Joka lihaansa kylvää, se lihasta turmeluksen niittää; mutta joka Henkeen kylvää, se Hengestä iankaikkisen elämän niittää.'),
(1698127,58,48,6,9,'Ja kun hyvää teemme, älkäämme lannistuko, sillä me saamme ajan tullen niittää, jos emme väsy.'),
(1698128,58,48,6,10,'Sentähden, kun meillä vielä aikaa on, tehkäämme hyvää kaikille, mutta varsinkin uskonveljille.'),
(1698129,58,48,6,11,'Katsokaa, kuinka suurilla kirjaimilla minä omakätisesti teille kirjoitan!'),
(1698130,58,48,6,12,'Kaikki, jotka pyrkivät lihassa olemaan mieliksi, ne pakottavat teitä ympärileikkauttamaan itsenne vain siksi, ettei heitä Kristuksen ristin tähden vainottaisi.'),
(1698131,58,48,6,13,'Eiväthän nekään, jotka ympärileikkauttavat itsensä, itse noudata lakia, vaan he tahtovat teitä ympärileikkauttamaan itsenne saadakseen kerskata teidän lihastanne.'),
(1698132,58,48,6,14,'Mutta pois se minusta, että minä muusta kerskaisin kuin meidän Herramme Jeesuksen Kristuksen rististä, jonka kautta maailma on ristiinnaulittu minulle, ja minä maailmalle!'),
(1698133,58,48,6,15,'Sillä ei ympärileikkaus ole mitään eikä ympärileikkaamattomuus, vaan uusi luomus.'),
(1698134,58,48,6,16,'Ja kaikille, jotka tämän säännön mukaan vaeltavat, kaikille heille rauha ja laupeus, ja Jumalan Israelille!'),
(1698135,58,48,6,17,'Älköön tästedes kukaan minulle vaivoja tuottako; sillä minä kannan Jeesuksen arvet ruumiissani.'),
(1698136,58,48,6,18,'Meidän Herramme Jeesuksen Kristuksen armo olkoon teidän henkenne kanssa, veljet. Amen.'),
(1698137,58,49,1,1,'Paavali, Jumalan tahdosta Kristuksen Jeesuksen apostoli, Efesossa oleville pyhille ja uskoville Kristuksessa Jeesuksessa.'),
(1698138,58,49,1,2,'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!'),
(1698139,58,49,1,3,'Ylistetty olkoon meidän Herramme Jeesuksen Kristuksen Jumala ja Isä, joka on siunannut meitä taivaallisissa kaikella hengellisellä siunauksella Kristuksessa,'),
(1698140,58,49,1,4,'niinkuin hän ennen maailman perustamista oli hänessä valinnut meidät olemaan pyhät ja nuhteettomat hänen edessään, rakkaudessa,'),
(1698141,58,49,1,5,'edeltäpäin määräten meidät lapseuteen, hänen yhteyteensä Jeesuksen Kristuksen kautta, hänen oman tahtonsa mielisuosion mukaan,'),
(1698142,58,49,1,6,'sen armonsa kirkkauden kiitokseksi, minkä hän on lahjoittanut meille siinä rakastetussa,'),
(1698143,58,49,1,7,'jossa meillä on lunastus hänen verensä kautta, rikkomusten anteeksisaaminen, hänen armonsa rikkauden mukaan.'),
(1698144,58,49,1,8,'Tätä armoa hän on ylenpalttisesti antanut meille kaikkinaiseksi viisaudeksi ja ymmärrykseksi,'),
(1698145,58,49,1,9,'tehden meille tiettäväksi sen tahtonsa salaisuuden, että hän, päätöksensä mukaan, jonka hän oli nähnyt hyväksi itsessään tehdä -'),
(1698146,58,49,1,10,'siitä armotaloudesta, minkä hän aikojen täyttyessä aikoi toteuttaa, - oli yhdistävä Kristuksessa yhdeksi kaikki, mitä on taivaissa ja mitä on maan päällä.'),
(1698147,58,49,1,11,'Hänessä me myös olemme saaneet perintöosan, ollen siihen edeltämäärätyt hänen aivoituksensa mukaan, hänen, joka vaikuttaa kaikki oman tahtonsa päättämän mukaan,'),
(1698148,58,49,1,12,'että me olisimme hänen kirkkautensa kiitokseksi, me, jotka jo edeltä olimme panneet toivomme Kristukseen.'),
(1698149,58,49,1,13,'Hänessä on teihinkin, sittenkuin olitte kuulleet totuuden sanan, pelastuksenne evankeliumin, uskoviksi tultuanne pantu luvatun Pyhän Hengen sinetti,'),
(1698150,58,49,1,14,'sen, joka on meidän perintömme vakuutena, hänen omaisuutensa lunastamiseksi - hänen kirkkautensa kiitokseksi.'),
(1698151,58,49,1,15,'Sentähden, kun kuulin siitä uskosta, joka teillä on Herrassa Jeesuksessa, ja teidän rakkaudestanne kaikkia pyhiä kohtaan,'),
(1698152,58,49,1,16,'en minäkään lakkaa kiittämästä teidän tähtenne, kun muistelen teitä rukouksissani,'),
(1698153,58,49,1,17,'anoen, että meidän Herramme Jeesuksen Kristuksen Jumala, kirkkauden Isä, antaisi teille viisauden ja ilmestyksen Hengen hänen tuntemisessaan'),
(1698154,58,49,1,18,'ja valaisisi teidän sydämenne silmät, että tietäisitte, mikä on se toivo, johon hän on teidät kutsunut, kuinka suuri hänen perintönsä kirkkaus hänen pyhissään'),
(1698155,58,49,1,19,'ja mikä hänen voimansa ylenpalttinen suuruus meitä kohtaan, jotka uskomme - sen hänen väkevyytensä voiman vaikutuksen mukaan,'),
(1698156,58,49,1,20,'jonka hän vaikutti Kristuksessa, kun hän herätti hänet kuolleista ja asetti hänet oikealle puolellensa taivaissa,'),
(1698157,58,49,1,21,'korkeammalle kaikkea hallitusta ja valtaa ja voimaa ja herrautta ja jokaista nimeä, mikä mainitaan, ei ainoastaan tässä maailmanajassa, vaan myös tulevassa.'),
(1698158,58,49,1,22,'Ja kaikki hän on asettanut hänen jalkainsa alle ja antanut hänet kaiken pääksi seurakunnalle,'),
(1698159,58,49,1,23,'joka on hänen ruumiinsa, hänen täyteytensä, joka kaikki kaikissa täyttää.'),
(1698160,58,49,2,1,'Ja Jumala on eläviksi tehnyt teidät, jotka olitte kuolleet rikoksiinne ja synteihinne,'),
(1698161,58,49,2,2,'joissa te ennen vaelsitte tämän maailman menon mukaan, ilmavallan hallitsijan, sen hengen hallitsijan, mukaan, joka nyt tekee työtään tottelemattomuuden lapsissa,'),
(1698162,58,49,2,3,'joiden joukossa mekin kaikki ennen vaelsimme lihamme himoissa, noudattaen lihan ja ajatusten mielitekoja, ja olimme luonnostamme vihan lapsia niinkuin muutkin;'),
(1698163,58,49,2,4,'mutta Jumala, joka on laupeudesta rikas, suuren rakkautensa tähden, jolla hän on meitä rakastanut,'),
(1698164,58,49,2,5,'on tehnyt meidät, jotka olimme kuolleet rikoksiimme, eläviksi Kristuksen kanssa - armosta te olette pelastetut -'),
(1698165,58,49,2,6,'ja yhdessä hänen kanssaan herättänyt ja yhdessä hänen kanssaan asettanut meidät taivaallisiin Kristuksessa Jeesuksessa,'),
(1698166,58,49,2,7,'osoittaakseen tulevina maailmanaikoina armonsa ylenpalttista runsautta, hyvyydessään meitä kohtaan Kristuksessa Jeesuksessa.'),
(1698167,58,49,2,8,'Sillä armosta te olette pelastetut uskon kautta, ette itsenne kautta - se on Jumalan lahja -'),
(1698168,58,49,2,9,'ette tekojen kautta, ettei kukaan kerskaisi.'),
(1698169,58,49,2,10,'Sillä me olemme hänen tekonsa, luodut Kristuksessa Jeesuksessa hyviä töitä varten, jotka Jumala on edeltäpäin valmistanut, että me niissä vaeltaisimme.'),
(1698170,58,49,2,11,'Muistakaa sentähden, että te ennen, te lihanne puolesta pakanat, jotka olette saaneet ympärileikkaamattomien nimen niiltä, joita, lihaan käsillä tehdyn ympärileikkauksen mukaisesti, sanotaan ympärileikatuiksi -'),
(1698171,58,49,2,12,'että te siihen aikaan olitte ilman Kristusta, olitte vailla Israelin kansalaisoikeutta ja vieraat lupauksen liitoille, ilman toivoa ja ilman Jumalaa maailmassa;'),
(1698172,58,49,2,13,'mutta nyt, kun olette Kristuksessa Jeesuksessa, olette te, jotka ennen olitte kaukana, päässeet lähelle Kristuksen veressä.'),
(1698173,58,49,2,14,'Sillä hän on meidän rauhamme, hän, joka teki molemmat yhdeksi ja purki erottavan väliseinän, nimittäin vihollisuuden,'),
(1698174,58,49,2,15,'kun hän omassa lihassaan teki tehottomaksi käskyjen lain säädöksinensä, luodakseen itsessänsä nuo kaksi yhdeksi uudeksi ihmiseksi, tehden rauhan,'),
(1698175,58,49,2,16,'ja yhdessä ruumiissa sovittaakseen molemmat Jumalan kanssa ristin kautta, kuolettaen itsensä kautta vihollisuuden.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698176,58,49,2,17,'Ja hän tuli ja julisti rauhaa teille, jotka kaukana olitte, ja rauhaa niille, jotka lähellä olivat;'),
(1698177,58,49,2,18,'sillä hänen kauttansa on meillä molemmilla pääsy yhdessä Hengessä Isän tykö.'),
(1698178,58,49,2,19,'Niin ette siis enää ole vieraita ettekä muukalaisia, vaan te olette pyhien kansalaisia ja Jumalan perhettä,'),
(1698179,58,49,2,20,'apostolien ja profeettain perustukselle rakennettuja, kulmakivenä itse Kristus Jeesus,'),
(1698180,58,49,2,21,'jossa koko rakennus liittyy yhteen ja kasvaa pyhäksi temppeliksi Herrassa;'),
(1698181,58,49,2,22,'ja hänessä tekin yhdessä muitten kanssa rakennutte Jumalan asumukseksi Hengessä.'),
(1698182,58,49,3,1,'Sen takia minä, Paavali, teidän, pakanain, tähden Kristuksen Jeesuksen vanki, notkistan polveni -'),
(1698183,58,49,3,2,'olette kaiketi kuulleet siitä Jumalan armon taloudenhoidosta, mikä on minulle teitä varten annettu,'),
(1698184,58,49,3,3,'että näet tämä salaisuus on ilmestyksen kautta tehty minulle tiettäväksi, niinkuin olen siitä edellä lyhyesti kirjoittanut;'),
(1698185,58,49,3,4,'josta te sitä lukiessanne voitte huomata, kuinka perehtynyt minä olen Kristuksen salaisuuteen,'),
(1698186,58,49,3,5,'jota menneiden sukupolvien aikana ei ole ihmisten lapsille tiettäväksi tehty, niinkuin se nyt Hengessä on ilmoitettu hänen pyhille apostoleilleen ja profeetoille:'),
(1698187,58,49,3,6,'että näet pakanatkin ovat kanssaperillisiä ja yhtä ruumista ja osallisia lupaukseen Kristuksessa Jeesuksessa evankeliumin kautta,'),
(1698188,58,49,3,7,'jonka palvelijaksi minä olen tullut Jumalan armon lahjan kautta, joka minulle on annettu hänen voimansa vaikutuksesta.'),
(1698189,58,49,3,8,'Minulle, kaikista pyhistä halvimmalle, on annettu tämä armo: julistaa pakanoille evankeliumia Kristuksen tutkimattomasta rikkaudesta'),
(1698190,58,49,3,9,'ja saattaa kaikille ilmeiseksi, mitä on sen salaisuuden taloudenhoito, joka ikuisista ajoista asti on ollut kätkettynä Jumalassa, kaiken Luojassa,'),
(1698191,58,49,3,10,'että Jumalan moninainen viisaus seurakunnan kautta nyt tulisi taivaallisten hallitusten ja valtojen tietoon'),
(1698192,58,49,3,11,'sen iankaikkisen aivoituksen mukaisesti, jonka hän oli säätänyt Kristuksessa Jeesuksessa, meidän Herrassamme,'),
(1698193,58,49,3,12,'jossa meillä, uskon kautta häneen, on uskallus ja luottavainen pääsy Jumalan tykö.'),
(1698194,58,49,3,13,'Siksi minä pyydän, ettette lannistuisi niiden ahdistusten vuoksi, joita minä teidän tähtenne kärsin, sillä ne ovat teidän kunnianne.'),
(1698195,58,49,3,14,'Sentähden minä notkistan polveni Isän edessä,'),
(1698196,58,49,3,15,'josta kaikki, millä isä on, taivaissa ja maan päällä, saa nimensä,'),
(1698197,58,49,3,16,'että hän kirkkautensa runsauden mukaisesti antaisi teidän, sisällisen ihmisenne puolesta, voimassa vahvistua hänen Henkensä kautta'),
(1698198,58,49,3,17,'ja Kristuksen asua uskon kautta teidän sydämissänne,'),
(1698199,58,49,3,18,'niin että te, rakkauteen juurtuneina ja perustuneina, voisitte kaikkien pyhien kanssa käsittää, mikä leveys ja pituus ja korkeus ja syvyys on,'),
(1698200,58,49,3,19,'ja oppia tuntemaan Kristuksen rakkauden, joka on kaikkea tietoa ylempänä; että tulisitte täyteen Jumalan kaikkea täyteyttä.'),
(1698201,58,49,3,20,'Mutta hänelle, joka voi tehdä enemmän, monin verroin enemmän kuin kaikki, mitä me anomme tai ymmärrämme, sen voiman mukaan, joka meissä vaikuttaa,'),
(1698202,58,49,3,21,'hänelle kunnia seurakunnassa ja Kristuksessa Jeesuksessa kautta kaikkien sukupolvien, aina ja iankaikkisesti! Amen.'),
(1698203,58,49,4,1,'Niin kehoitan siis minä, joka olen vankina Herrassa, teitä vaeltamaan, niinkuin saamanne kutsumuksen arvo vaatii,'),
(1698204,58,49,4,2,'kaikessa nöyryydessä ja hiljaisuudessa ja pitkämielisyydessä kärsien toinen toistanne rakkaudessa'),
(1698205,58,49,4,3,'ja pyrkien säilyttämään hengen yhteyden rauhan yhdyssiteellä:'),
(1698206,58,49,4,4,'yksi ruumis ja yksi henki, niinkuin te olette kutsututkin yhteen ja samaan toivoon, jonka te kutsumuksessanne saitte;'),
(1698207,58,49,4,5,'yksi Herra, yksi usko, yksi kaste;'),
(1698208,58,49,4,6,'yksi Jumala ja kaikkien Isä, joka on yli kaikkien ja kaikkien kautta ja kaikissa.'),
(1698209,58,49,4,7,'Mutta itsekullekin meistä on armo annettu Kristuksen lahjan mitan mukaan.'),
(1698210,58,49,4,8,'Sentähden on sanottu: "Hän astui ylös korkeuteen, hän otti vankeja saaliikseen, hän antoi lahjoja ihmisille".'),
(1698211,58,49,4,9,'Mutta että hän astui ylös, mitä se on muuta, kuin että hän oli astunut alaskin, maan alimpiin paikkoihin?'),
(1698212,58,49,4,10,'Hän, joka on astunut alas, on se, joka myös astui ylös, kaikkia taivaita ylemmäksi, täyttääkseen kaikki.'),
(1698213,58,49,4,11,'Ja hän antoi muutamat apostoleiksi, toiset profeetoiksi, toiset evankelistoiksi, toiset paimeniksi ja opettajiksi,'),
(1698214,58,49,4,12,'tehdäkseen pyhät täysin valmiiksi palveluksen työhön, Kristuksen ruumiin rakentamiseen,'),
(1698215,58,49,4,13,'kunnes me kaikki pääsemme yhteyteen uskossa ja Jumalan Pojan tuntemisessa, täyteen miehuuteen, Kristuksen täyteyden täyden iän määrään,'),
(1698216,58,49,4,14,'ettemme enää olisi alaikäisiä, jotka ajelehtivat ja joita viskellään kaikissa opintuulissa ja ihmisten arpapelissä ja eksytyksen kavalissa juonissa;'),
(1698217,58,49,4,15,'vaan että me, totuutta noudattaen rakkaudessa, kaikin tavoin kasvaisimme häneen, joka on pää, Kristus,'),
(1698218,58,49,4,16,'josta koko ruumis, yhteen liitettynä ja koossa pysyen jokaisen jänteensä avulla, kasvaa rakentuakseen rakkaudessa sen voiman määrän mukaan, mikä kullakin osalla on.'),
(1698219,58,49,4,17,'Sen minä siis sanon ja varoitan Herrassa: älkää enää vaeltako, niinkuin pakanat vaeltavat mielensä turhuudessa,'),
(1698220,58,49,4,18,'nuo, jotka, pimentyneinä ymmärrykseltään ja vieraantuneina Jumalan elämästä heissä olevan tietämättömyyden tähden ja sydämensä paatumuksen tähden,'),
(1698221,58,49,4,19,'ovat päästäneet tuntonsa turtumaan ja heittäytyneet irstauden valtaan, harjoittamaan kaikkinaista saastaisuutta, ahneudessa.'),
(1698222,58,49,4,20,'Mutta näin te ette ole oppineet Kristusta tuntemaan,'),
(1698223,58,49,4,21,'jos muutoin olette hänestä kuulleet ja hänessä opetusta saaneet, niinkuin totuus on Jeesuksessa:'),
(1698224,58,49,4,22,'että teidän tulee panna pois vanha ihmisenne, jonka mukaan te ennen vaelsitte ja joka turmelee itsensä petollisia himoja seuraten,'),
(1698225,58,49,4,23,'ja uudistua mielenne hengeltä');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698226,58,49,4,24,'ja pukea päällenne uusi ihminen, joka Jumalan mukaan on luotu totuuden vanhurskauteen ja pyhyyteen.'),
(1698227,58,49,4,25,'Pankaa sentähden pois valhe ja puhukaa totta, kukin lähimmäisensä kanssa, sillä me olemme toinen toisemme jäseniä.'),
(1698228,58,49,4,26,'"Vihastukaa, mutta älkää syntiä tehkö." Älkää antako auringon laskea vihanne yli,'),
(1698229,58,49,4,27,'älkääkä antako perkeleelle sijaa.'),
(1698230,58,49,4,28,'Joka on varastanut, älköön enää varastako, vaan tehköön ennemmin työtä ja toimittakoon käsillään sitä, mikä hyvää on, että hänellä olisi, mitä antaa tarvitsevalle.'),
(1698231,58,49,4,29,'Mikään rietas puhe älköön suustanne lähtekö, vaan ainoastaan sellainen, mikä on rakentavaista ja tarpeellista ja on mieluista niille, jotka kuulevat.'),
(1698232,58,49,4,30,'Älkääkä saattako murheelliseksi Jumalan Pyhää Henkeä, joka on teille annettu sinetiksi lunastuksen päivään saakka.'),
(1698233,58,49,4,31,'Kaikki katkeruus ja kiivastus ja viha ja huuto ja herjaus, kaikki pahuus olkoon kaukana teistä.'),
(1698234,58,49,4,32,'Olkaa sen sijaan toisianne kohtaan ystävällisiä, hyväsydämisiä, anteeksiantavaisia toinen toisellenne, niinkuin Jumalakin on Kristuksessa teille anteeksi antanut.'),
(1698235,58,49,5,1,'Olkaa siis Jumalan seuraajia, niinkuin rakkaat lapset,'),
(1698236,58,49,5,2,'ja vaeltakaa rakkaudessa, niinkuin Kristuskin rakasti teitä ja antoi itsensä meidän edestämme lahjaksi ja uhriksi, Jumalalle "suloiseksi tuoksuksi".'),
(1698237,58,49,5,3,'Mutta haureutta ja minkäänlaista saastaisuutta tai ahneutta älköön edes mainittako teidän keskuudessanne - niinkuin pyhien sopii -'),
(1698238,58,49,5,4,'älköön myös rivoutta tai tyhmää lorua tai ilvehtimistä, jotka ovat sopimattomia, vaan paremmin kiitosta.'),
(1698239,58,49,5,5,'Sillä sen te tiedätte ja tunnette, ettei yhdelläkään haureellisella eikä saastaisella eikä ahneella - sillä hän on epäjumalanpalvelija - ole perintöosaa Kristuksen ja Jumalan valtakunnassa.'),
(1698240,58,49,5,6,'Älköön kukaan pettäkö teitä tyhjillä puheilla, sillä semmoisten tähden kohtaa Jumalan viha tottelemattomuuden lapsia;'),
(1698241,58,49,5,7,'älkää siis olko niihin osallisia heidän kanssaan.'),
(1698242,58,49,5,8,'Ennen te olitte pimeys, mutta nyt te olette valkeus Herrassa. Vaeltakaa valkeuden lapsina'),
(1698243,58,49,5,9,'- sillä kaikkinainen hyvyys ja vanhurskaus ja totuus on valkeuden hedelmä -'),
(1698244,58,49,5,10,'ja tutkikaa, mikä on otollista Herralle;'),
(1698245,58,49,5,11,'älköönkä teillä olko mitään osallisuutta pimeyden hedelmättömiin tekoihin, vaan päinvastoin nuhdelkaakin niistä.'),
(1698246,58,49,5,12,'Sillä häpeällistä on jo sanoakin, mitä he salassa tekevät;'),
(1698247,58,49,5,13,'mutta tämä kaikki tulee ilmi, kun valkeus sen paljastaa, sillä kaikki, mikä tulee ilmi, on valkeutta.'),
(1698248,58,49,5,14,'Sentähden sanotaan: "Heräjä sinä, joka nukut, ja nouse kuolleista, niin Kristus sinua valaisee!"'),
(1698249,58,49,5,15,'Katsokaa siis tarkoin, kuinka vaellatte: ei niinkuin tyhmät, vaan niinkuin viisaat,'),
(1698250,58,49,5,16,'ja ottakaa vaari oikeasta hetkestä, sillä aika on paha.'),
(1698251,58,49,5,17,'Älkää sentähden olko mielettömät, vaan ymmärtäkää, mikä Herran tahto on.'),
(1698252,58,49,5,18,'Älkääkä juopuko viinistä, sillä siitä tulee irstas meno, vaan täyttykää Hengellä,'),
(1698253,58,49,5,19,'puhuen keskenänne psalmeilla ja kiitosvirsillä ja hengellisillä lauluilla, veisaten ja laulaen sydämessänne Herralle,'),
(1698254,58,49,5,20,'kiittäen aina Jumalaa ja Isää kaikesta meidän Herramme Jeesuksen Kristuksen nimessä.'),
(1698255,58,49,5,21,'Ja olkaa toinen toisellenne alamaiset Kristuksen pelossa.'),
(1698256,58,49,5,22,'Vaimot, olkaa omille miehillenne alamaiset niinkuin Herralle;'),
(1698257,58,49,5,23,'sillä mies on vaimon pää, niinkuin myös Kristus on seurakunnan pää, hän, ruumiin vapahtaja.'),
(1698258,58,49,5,24,'Mutta niinkuin seurakunta on Kristukselle alamainen, niin olkoot vaimotkin miehillensä kaikessa alamaiset.'),
(1698259,58,49,5,25,'Miehet, rakastakaa vaimojanne, niinkuin Kristuskin rakasti seurakuntaa ja antoi itsensä alttiiksi sen edestä,'),
(1698260,58,49,5,26,'että hän sen pyhittäisi, puhdistaen sen, vedellä pesten, sanan kautta,'),
(1698261,58,49,5,27,'saadakseen asetetuksi eteensä kirkastettuna seurakunnan, jossa ei olisi tahraa eikä ryppyä eikä mitään muuta sellaista, vaan joka olisi pyhä ja nuhteeton.'),
(1698262,58,49,5,28,'Samalla tavoin tulee myös miesten rakastaa vaimojansa niinkuin omia ruumiitaan; joka rakastaa vaimoansa, hän rakastaa itseänsä.'),
(1698263,58,49,5,29,'Sillä eihän kukaan koskaan ole vihannut omaa lihaansa, vaan hän ravitsee ja vaalii sitä, niinkuin Kristuskin seurakuntaa,'),
(1698264,58,49,5,30,'sillä me olemme hänen ruumiinsa jäseniä.'),
(1698265,58,49,5,31,'"Sentähden mies luopukoon isästänsä ja äidistänsä ja liittyköön vaimoonsa, ja ne kaksi tulevat yhdeksi lihaksi."'),
(1698266,58,49,5,32,'Tämä salaisuus on suuri; minä tarkoitan Kristusta ja seurakuntaa.'),
(1698267,58,49,5,33,'Mutta myös teistä kukin kohdaltaan rakastakoon vaimoaan niinkuin itseänsä; mutta vaimo kunnioittakoon miestänsä.'),
(1698268,58,49,6,1,'Lapset, olkaa vanhemmillenne kuuliaiset Herrassa, sillä se on oikein.'),
(1698269,58,49,6,2,'"Kunnioita isääsi ja äitiäsi" - tämä on ensimmäinen käsky, jota seuraa lupaus -'),
(1698270,58,49,6,3,'"että menestyisit ja kauan eläisit maan päällä".'),
(1698271,58,49,6,4,'Ja te isät, älkää kiihoittako lapsianne vihaan, vaan kasvattakaa heitä Herran kurissa ja nuhteessa.'),
(1698272,58,49,6,5,'Palvelijat, olkaa kuuliaiset maallisille isännillenne, pelossa ja vavistuksessa, sydämenne yksinkertaisuudessa, niinkuin Kristukselle,'),
(1698273,58,49,6,6,'ei silmänpalvelijoina, ihmisille mieliksi, vaan Kristuksen palvelijoina, sydämestänne tehden, mitä Jumala tahtoo,'),
(1698274,58,49,6,7,'hyvällä mielellä palvellen, niinkuin palvelisitte Herraa ettekä ihmisiä,'),
(1698275,58,49,6,8,'tietäen, että mitä hyvää kukin tekee, sen hän saa takaisin Herralta, olkoonpa orja tai vapaa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698276,58,49,6,9,'Ja te isännät, tehkää samoin heille, jättäkää pois uhkaileminen, sillä tiedättehän, että sekä heidän että teidän Herranne on taivaissa ja ettei hän katso henkilöön.'),
(1698277,58,49,6,10,'Lopuksi, vahvistukaa Herrassa ja hänen väkevyytensä voimassa.'),
(1698278,58,49,6,11,'Pukekaa yllenne Jumalan koko sota-asu, voidaksenne kestää perkeleen kavalat juonet.'),
(1698279,58,49,6,12,'Sillä meillä ei ole taistelu verta ja lihaa vastaan, vaan hallituksia vastaan, valtoja vastaan, tässä pimeydessä hallitsevia maailmanvaltiaita vastaan, pahuuden henkiolentoja vastaan taivaan avaruuksissa.'),
(1698280,58,49,6,13,'Sentähden ottakaa päällenne Jumalan koko sota-asu, voidaksenne pahana päivänä tehdä vastarintaa ja kaikki suoritettuanne pysyä pystyssä.'),
(1698281,58,49,6,14,'Seisokaa siis kupeet totuuteen vyötettyinä, ja olkoon pukunanne vanhurskauden haarniska,'),
(1698282,58,49,6,15,'ja kenkinä jaloissanne alttius rauhan evankeliumille.'),
(1698283,58,49,6,16,'Kaikessa ottakaa uskon kilpi, jolla voitte sammuttaa kaikki pahan palavat nuolet,'),
(1698284,58,49,6,17,'ja ottakaa vastaan pelastuksen kypäri ja Hengen miekka, joka on Jumalan sana.'),
(1698285,58,49,6,18,'Ja tehkää tämä kaikella rukouksella ja anomisella, rukoillen joka aika Hengessä ja sitä varten valvoen kaikessa kestäväisyydessä ja anomisessa kaikkien pyhien puolesta;'),
(1698286,58,49,6,19,'ja minunkin puolestani, että minulle, kun suuni avaan, annettaisiin oikeat sanat rohkeasti julistaakseni evankeliumin salaisuutta,'),
(1698287,58,49,6,20,'jonka tähden minä olen lähettiläänä kahleissa, että minä siitä rohkeasti puhuisin, niinkuin minun puhua tulee.'),
(1698288,58,49,6,21,'Mutta että tekin tietäisitte tilani, kuinka minun on, niin on Tykikus, rakas veljeni ja uskollinen palvelija Herrassa, antava teille siitä kaikesta tiedon.'),
(1698289,58,49,6,22,'Minä lähetän hänet teidän tykönne juuri sitä varten, että saisitte tietää meidän tilamme ja että hän lohduttaisi teidän sydämiänne.'),
(1698290,58,49,6,23,'Rauha veljille ja rakkaus, uskon kanssa, Isältä Jumalalta ja Herralta Jeesukselta Kristukselta!'),
(1698291,58,49,6,24,'Armo olkoon kaikkien kanssa, jotka rakastavat meidän Herraamme Jeesusta Kristusta - katoamattomuudessa.'),
(1698292,58,50,1,1,'Paavali ja Timoteus, Kristuksen Jeesuksen palvelijat, kaikille pyhille Kristuksessa Jeesuksessa, jotka ovat Filippissä, sekä myös seurakunnan kaitsijoille ja seurakuntapalvelijoille.'),
(1698293,58,50,1,2,'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!'),
(1698294,58,50,1,3,'Minä kiitän Jumalaani, niin usein kuin teitä muistan,'),
(1698295,58,50,1,4,'aina kaikissa rukouksissani ilolla rukoillen teidän kaikkien puolesta,'),
(1698296,58,50,1,5,'kiitän siitä, että olette olleet osallisia evankeliumiin ensi päivästä alkaen tähän päivään saakka,'),
(1698297,58,50,1,6,'varmasti luottaen siihen, että hän, joka on alkanut teissä hyvän työn, on sen täyttävä Kristuksen Jeesuksen päivään saakka.'),
(1698298,58,50,1,7,'Ja oikein onkin, että minä näin ajattelen teitä kaikkia, koska te olette minun sydämessäni, te, jotka sekä ollessani kahleissa että evankeliumia puolustaessani ja vahvistaessani olette kaikki minun kanssani armosta osalliset.'),
(1698299,58,50,1,8,'Sillä Jumala on minun todistajani, kuinka minä teitä kaikkia ikävöitsen Kristuksen Jeesuksen sydämellisellä rakkaudella.'),
(1698300,58,50,1,9,'Ja sitä minä rukoilen, että teidän rakkautenne tulisi yhä runsaammaksi tiedossa ja kaikessa käsittämisessä,'),
(1698301,58,50,1,10,'voidaksenne tutkia, mikä paras on, että te Kristuksen päivään saakka olisitte puhtaat ettekä kenellekään loukkaukseksi,'),
(1698302,58,50,1,11,'täynnä vanhurskauden hedelmää, jonka Jeesus Kristus saa aikaan, Jumalan kunniaksi ja ylistykseksi.'),
(1698303,58,50,1,12,'Mutta minä tahdon, että te, veljet, tietäisitte, että se, mitä minulle on tapahtunut, on koitunutkin evankeliumin menestykseksi,'),
(1698304,58,50,1,13,'niin että koko henkivartioston ja kaikkien muiden tietoon on tullut, että minä olen kahleissa Kristuksen tähden,'),
(1698305,58,50,1,14,'ja että useimmat veljistä, saaden Herrassa uskallusta minun kahleistani, yhä enemmän rohkenevat pelkäämättä puhua Jumalan sanaa.'),
(1698306,58,50,1,15,'Muutamat tosin julistavat Kristusta kateudestakin ja riidan halusta, mutta toiset hyvässä tarkoituksessa:'),
(1698307,58,50,1,16,'nämä tekevät sitä rakkaudesta, koska tietävät, että minut on pantu evankeliumia puolustamaan,'),
(1698308,58,50,1,17,'nuo toiset taas julistavat Kristusta itsekkyydestä, epäpuhtaalla mielellä, luullen tuottavansa minulle murhetta kahleissani.'),
(1698309,58,50,1,18,'Vaan mitäpä tuosta, kunhan Kristusta vain tavalla tai toisella julistetaan, joko näön vuoksi tai totuudessa! Ja siitä minä iloitsen, ja olen vastakin iloitseva.'),
(1698310,58,50,1,19,'Sillä minä tiedän, että tämä on päättyvä minulle pelastukseksi teidän rukoustenne kautta ja Jeesuksen Kristuksen Hengen avulla,'),
(1698311,58,50,1,20,'minun hartaan odotukseni ja toivoni mukaan, etten ole missään häpeään joutuva, vaan että Kristus nytkin, niinkuin aina, on tuleva ylistetyksi minun ruumiissani kaikella rohkeudella, joko elämän tai kuoleman kautta.'),
(1698312,58,50,1,21,'Sillä elämä on minulle Kristus, ja kuolema on voitto.'),
(1698313,58,50,1,22,'Mutta jos minun on eläminen täällä lihassa, niin siitä koituu hedelmää työlleni, ja silloin en tiedä, minkä valitsisin.'),
(1698314,58,50,1,23,'Ahtaalla minä olen näiden kahden välissä: halu minulla on täältä eritä ja olla Kristuksen kanssa, sillä se olisi monin verroin parempi;'),
(1698315,58,50,1,24,'mutta teidän tähtenne on lihassa viipymiseni tarpeellisempi.'),
(1698316,58,50,1,25,'Ja kun olen tästä varma, niin minä tiedän jääväni eloon ja viipyväni kaikkien teidän luonanne teidän edistymiseksenne ja iloksenne uskossa,'),
(1698317,58,50,1,26,'että teidän kerskaamisenne minusta olisi yhä runsaampi Kristuksessa Jeesuksessa, kun minä taas tulen teidän tykönne.'),
(1698318,58,50,1,27,'Käyttäytykää vain Kristuksen evankeliumin arvon mukaisesti, että minä, tulinpa sitten teidän tykönne ja näin teidät tai olin tulematta, saan kuulla teistä, että te pysytte samassa hengessä ja yksimielisinä taistelette minun kanssani evankeliumin uskon puolesta,'),
(1698319,58,50,1,28,'vastustajia missään kohden säikähtämättä; ja se on heille kadotuksen, mutta teille pelastuksen merkki, merkki Jumalalta.'),
(1698320,58,50,1,29,'Sillä teidän on suotu, Kristuksen tähden, ei ainoastaan uskoa häneen, vaan myös kärsiä hänen tähtensä,'),
(1698321,58,50,1,30,'teidän, joilla on sama taistelu, mitä näitte ja nyt kuulette minun taistelevan.'),
(1698322,58,50,2,1,'Jos siis on jotakin kehoitusta Kristuksessa, jos jotakin rakkauden lohdutusta, jos jotakin Hengen yhteyttä, jos jotakin sydämellisyyttä ja laupeutta,'),
(1698323,58,50,2,2,'niin tehkää minun iloni täydelliseksi siten, että olette samaa mieltä, että teillä on sama rakkaus, että olette sopuisat ja yksimieliset'),
(1698324,58,50,2,3,'ettekä tee mitään itsekkyydestä tai turhan kunnian pyynnöstä, vaan että nöyryydessä pidätte toista parempana kuin itseänne'),
(1698325,58,50,2,4,'ja että katsotte kukin, ette vain omaanne, vaan toistenkin parasta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698326,58,50,2,5,'Olkoon teillä se mieli, joka myös Kristuksella Jeesuksella oli,'),
(1698327,58,50,2,6,'joka ei, vaikka hänellä olikin Jumalan muoto, katsonut saaliiksensa olla Jumalan kaltainen,'),
(1698328,58,50,2,7,'vaan tyhjensi itsensä ja otti orjan muodon, tuli ihmisten kaltaiseksi, ja hänet havaittiin olennaltaan sellaiseksi kuin ihminen;'),
(1698329,58,50,2,8,'hän nöyryytti itsensä ja oli kuuliainen kuolemaan asti, hamaan ristin kuolemaan asti.'),
(1698330,58,50,2,9,'Sentähden onkin Jumala hänet korkealle korottanut ja antanut hänelle nimen, kaikkia muita nimiä korkeamman,'),
(1698331,58,50,2,10,'niin että kaikkien polvien pitää Jeesuksen nimeen notkistuman, sekä niitten, jotka taivaissa ovat, että niitten, jotka maan päällä ovat, ja niitten, jotka maan alla ovat,'),
(1698332,58,50,2,11,'ja jokaisen kielen pitää tunnustaman Isän Jumalan kunniaksi, että Jeesus Kristus on Herra.'),
(1698333,58,50,2,12,'Siis, rakkaani, samoin kuin aina olette olleet kuuliaiset, niin ahkeroikaa, ei ainoastaan niinkuin silloin, kun minä olin teidän tykönänne, vaan paljoa enemmän nyt, kun olen poissa, pelolla ja vavistuksella, että pelastuisitte;'),
(1698334,58,50,2,13,'sillä Jumala on se, joka teissä vaikuttaa sekä tahtomisen että tekemisen, että hänen hyvä tahtonsa tapahtuisi.'),
(1698335,58,50,2,14,'Tehkää kaikki nurisematta ja epäröimättä,'),
(1698336,58,50,2,15,'että olisitte moitteettomat ja puhtaat, olisitte tahrattomat Jumalan lapset kieron ja nurjan sukukunnan keskellä, joiden joukossa te loistatte niinkuin tähdet maailmassa,'),
(1698337,58,50,2,16,'tarjolla pitäessänne elämän sanaa, ollen minulle kerskaukseksi Kristuksen päivänä siitä, etten ole turhaan juossut enkä turhaan vaivaa nähnyt.'),
(1698338,58,50,2,17,'Vaan jos minut uhrataankin tehdessäni teidän uskonne uhri- ja palvelustoimitusta, niin minä kuitenkin iloitsen, ja iloitsen kaikkien teidän kanssanne;'),
(1698339,58,50,2,18,'samoin iloitkaa tekin, ja iloitkaa minun kanssani!'),
(1698340,58,50,2,19,'Toivon Herrassa Jeesuksessa pian voivani lähettää Timoteuksen teidän tykönne, että minäkin tulisin rohkaistuksi, saatuani tietää, kuinka teidän on.'),
(1698341,58,50,2,20,'Sillä minulla ei ole ketään samanmielistä, joka vilpittömästi huolehtisi teidän tilastanne;'),
(1698342,58,50,2,21,'sillä kaikki he etsivät omaansa eivätkä sitä, mikä Kristuksen Jeesuksen on.'),
(1698343,58,50,2,22,'Mutta hänen koetellun mielensä te tunnette, että hän, niinkuin poika isäänsä, on minua palvellut evankeliumin työssä.'),
(1698344,58,50,2,23,'Hänet minä siis toivon voivani lähettää heti, kun olen saanut nähdä, miten minun käy.'),
(1698345,58,50,2,24,'Ja minä luotan Herrassa siihen, että itsekin pian olen tuleva.'),
(1698346,58,50,2,25,'Katson kuitenkin välttämättömäksi palauttaa luoksenne veljeni, työkumppanini ja taistelutoverini Epafrodituksen, teidän lähettinne ja auttajan minun tarpeissani.'),
(1698347,58,50,2,26,'Sillä hän ikävöi teitä kaikkia ja on kovin levoton siitä, että olitte kuulleet hänen sairastavan.'),
(1698348,58,50,2,27,'Ja hän olikin sairaana, kuoleman kielissä; mutta Jumala armahti häntä, eikä ainoastaan häntä, vaan myös minua, etten saisi murhetta murheen päälle.'),
(1698349,58,50,2,28,'Lähetän hänet sentähden kiiruimmiten, että te hänet nähdessänne taas iloitsisitte ja minäkin olisin murheettomampi.'),
(1698350,58,50,2,29,'Ottakaa siis hänet vastaan Herrassa kaikella ilolla, ja pitäkää semmoisia kunniassa;'),
(1698351,58,50,2,30,'sillä Kristuksen työn tähden hän joutui aivan kuoleman partaalle, kun pani henkensä alttiiksi tehdäkseen minulle sen palveluksen, mitä te ette voineet tehdä.'),
(1698352,58,50,3,1,'Sitten vielä, veljeni, iloitkaa Herrassa! Samoista asioista teille kirjoittaminen ei minua kyllästytä, ja teille se on turvaksi.'),
(1698353,58,50,3,2,'Kavahtakaa noita koiria, kavahtakaa noita pahoja työntekijöitä, kavahtakaa noita pilalleleikattuja.'),
(1698354,58,50,3,3,'Sillä oikeita ympärileikattuja olemme me, jotka Jumalan Hengessä palvelemme Jumalaa ja kerskaamme Kristuksessa Jeesuksessa, emmekä luota lihaan,'),
(1698355,58,50,3,4,'vaikka minulla on, mihin luottaa lihassakin. Jos kuka muu luulee voivansa luottaa lihaan, niin voin vielä enemmän minä,'),
(1698356,58,50,3,5,'joka olen ympärileikattu kahdeksanpäiväisenä ja olen Israelin kansaa, Benjaminin sukukuntaa, hebrealainen hebrealaisista syntynyt, ollut lakiin nähden fariseus,'),
(1698357,58,50,3,6,'intoon nähden seurakunnan vainooja, lain vanhurskauteen nähden nuhteeton.'),
(1698358,58,50,3,7,'Mutta mikä minulle oli voitto, sen minä olen Kristuksen tähden lukenut tappioksi.'),
(1698359,58,50,3,8,'Niinpä minä todella luen kaikki tappioksi tuon ylen kalliin, Kristuksen Jeesuksen, minun Herrani, tuntemisen rinnalla, sillä hänen tähtensä minä olen menettänyt kaikki ja pidän sen roskana - että voittaisin omakseni Kristuksen'),
(1698360,58,50,3,9,'ja minun havaittaisiin olevan hänessä ja omistavan, ei omaa vanhurskautta, sitä, joka laista tulee, vaan sen, joka tulee Kristuksen uskon kautta, sen vanhurskauden, joka tulee Jumalasta uskon perusteella;'),
(1698361,58,50,3,10,'tunteakseni hänet ja hänen ylösnousemisensa voiman ja hänen kärsimyksiensä osallisuuden, tullessani hänen kaltaisekseen samankaltaisen kuoleman kautta,'),
(1698362,58,50,3,11,'jos minä ehkä pääsen ylösnousemiseen kuolleista.'),
(1698363,58,50,3,12,'Ei niin, että jo olisin sen saavuttanut tai että jo olisin tullut täydelliseksi, vaan minä riennän sitä kohti, että minä sen omakseni voittaisin, koskapa Kristus Jeesus on voittanut minut.'),
(1698364,58,50,3,13,'Veljet, minä en vielä katso sitä voittaneeni; mutta yhden minä teen: unhottaen sen, mikä on takana, ja kurottautuen sitä kohti, mikä on edessäpäin,'),
(1698365,58,50,3,14,'minä riennän kohti päämäärää, voittopalkintoa, johon Jumala on minut taivaallisella kutsumisella kutsunut Kristuksessa Jeesuksessa.'),
(1698366,58,50,3,15,'Olkoon siis meillä, niin monta kuin meitä on täydellistä, tämä mieli; ja jos teillä jossakin kohden on toinen mieli, niin Jumala on siinäkin teille ilmoittava, kuinka asia on.'),
(1698367,58,50,3,16,'Kunhan vain, mihin saakka olemme ehtineetkin, vaellamme samaa tietä!'),
(1698368,58,50,3,17,'Olkaa minun seuraajiani, veljet, ja katselkaa niitä, jotka näin vaeltavat, niinkuin me olemme teille esikuvana.'),
(1698369,58,50,3,18,'Sillä monet, joista usein olen sen teille sanonut ja nyt aivan itkien sanon, vaeltavat Kristuksen ristin vihollisina;'),
(1698370,58,50,3,19,'heidän loppunsa on kadotus, vatsa on heidän jumalansa, heidän kunnianaan on heidän häpeänsä, ja maallisiin on heidän mielensä.'),
(1698371,58,50,3,20,'Mutta meillä on yhdyskuntamme taivaissa, ja sieltä me myös odotamme Herraa Jeesusta Kristusta Vapahtajaksi,'),
(1698372,58,50,3,21,'joka on muuttava meidän alennustilamme ruumiin kirkkautensa ruumiin kaltaiseksi sillä voimallaan, jolla hän myös voi tehdä kaikki itsellensä alamaiseksi.'),
(1698373,58,50,4,1,'Sentähden, rakkaat ja ikävöidyt veljeni, te minun iloni ja kruununi, seisokaa näin Herrassa lujina, rakkaat!'),
(1698374,58,50,4,2,'Euodiaa minä kehoitan ja Syntykeä minä kehoitan olemaan yksimielisiä Herrassa.'),
(1698375,58,50,4,3,'Myös sinua, sinä minun oikea Synsygukseni, minä pyydän: ole näille vaimoille avullinen, sillä he ovat taistelleet minun kanssani evankeliumin hyväksi, yhdessä sekä Klemensin että muiden työtoverieni kanssa, joiden nimet ovat elämän kirjassa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698376,58,50,4,4,'Iloitkaa aina Herrassa! Vieläkin minä sanon: iloitkaa!'),
(1698377,58,50,4,5,'Tulkoon teidän lempeytenne kaikkien ihmisten tietoon. Herra on lähellä.'),
(1698378,58,50,4,6,'Älkää mistään murehtiko, vaan kaikessa saattakaa pyyntönne rukouksella ja anomisella kiitoksen kanssa Jumalalle tiettäväksi,'),
(1698379,58,50,4,7,'ja Jumalan rauha, joka on kaikkea ymmärrystä ylempi, on varjeleva teidän sydämenne ja ajatuksenne Kristuksessa Jeesuksessa.'),
(1698380,58,50,4,8,'Ja vielä, veljet, kaikki, mikä on totta, mikä kunnioitettavaa, mikä oikeaa, mikä puhdasta, mikä rakastettavaa, mikä hyvältä kuuluvaa, jos on jokin avu ja jos on jotakin kiitettävää, sitä ajatelkaa;'),
(1698381,58,50,4,9,'mitä myös olette oppineet ja saaneet ja minulta kuulleet ja minussa nähneet, sitä tehkää, niin rauhan Jumala on oleva teidän kanssanne.'),
(1698382,58,50,4,10,'Minä ihastuin suuresti Herrassa, että te jo vihdoinkin olitte elpyneet pitämään minusta huolta, johon teillä ennenkin oli ollut halua, vaikka ei tilaisuutta.'),
(1698383,58,50,4,11,'Ei niin, että minä puutteen vuoksi tätä sanon; sillä minä olen oppinut oloihini tyytymään.'),
(1698384,58,50,4,12,'Osaan elää niukkuudessa, osaan myös elää runsaudessa; kaikkeen ja kaikenlaisiin oloihin minä olen tottunut; sekä olemaan ravittuna että näkemään nälkää, elämään sekä runsaudessa että puutteessa.'),
(1698385,58,50,4,13,'Kaikki minä voin hänessä, joka minua vahvistaa.'),
(1698386,58,50,4,14,'Kuitenkin teitte hyvin, kun otitte osaa minun ahdinkooni.'),
(1698387,58,50,4,15,'Tiedättehän tekin, filippiläiset, että evankeliumin alkuaikoina, kun lähdin Makedoniasta, ei mikään muu seurakunta kuin te yksin käynyt minun kanssani tiliyhteyteen annetusta ja vastaanotetusta.'),
(1698388,58,50,4,16,'Sillä Tessalonikaankin te minulle kerran, jopa kahdesti, lähetitte, mitä tarvitsin.'),
(1698389,58,50,4,17,'Ei niin, että haluaisin lahjaa, vaan minä haluan teidän hyväksenne karttuvaa hedelmää.'),
(1698390,58,50,4,18,'Olen nyt saanut kaikkea, jopa ylenpalttisesti; minulla on yllinkyllin, saatuani Epafroditukselta teidän lähetyksenne, joka on "suloinen tuoksu", otollinen, Jumalalle mieluinen uhri.'),
(1698391,58,50,4,19,'Mutta minun Jumalani on rikkautensa mukaisesti täyttävä kaikki teidän tarpeenne kirkkaudessa, Kristuksessa Jeesuksessa.'),
(1698392,58,50,4,20,'Mutta meidän Jumalallemme ja Isällemme kunnia aina ja iankaikkisesti! Amen.'),
(1698393,58,50,4,21,'Tervehdys jokaiselle pyhälle Kristuksessa Jeesuksessa. Tervehdyksen lähettävät teille minun kanssani olevat veljet.'),
(1698394,58,50,4,22,'Tervehdyksen lähettävät teille kaikki pyhät, mutta varsinkin ne, jotka ovat keisarin huoneväkeä.'),
(1698395,58,50,4,23,'Herran Jeesuksen Kristuksen armo olkoon teidän henkenne kanssa.'),
(1698396,58,51,1,1,'Paavali, Jumalan tahdosta Kristuksen Jeesuksen apostoli, ja veli Timoteus'),
(1698397,58,51,1,2,'Kolossassa asuville pyhille ja uskoville veljille Kristuksessa. Armo teille ja rauha Jumalalta, meidän Isältämme!'),
(1698398,58,51,1,3,'Me kiitämme Jumalaa, Herramme Jeesuksen Kristuksen Isää, aina kun rukoilemme teidän edestänne,'),
(1698399,58,51,1,4,'sillä me olemme saaneet kuulla teidän uskostanne Kristuksessa Jeesuksessa ja rakkaudesta, mikä teillä on kaikkia pyhiä kohtaan;'),
(1698400,58,51,1,5,'me kiitämme häntä sen toivon tähden, joka teille on talletettuna taivaissa ja josta jo ennen olette kuulleet sen evankeliumin totuuden sanassa,'),
(1698401,58,51,1,6,'joka on tullut teidän tykönne, niinkuin se on myös kaikessa maailmassa, missä se kantaa hedelmää ja kasvaa, samoin kuin teidänkin keskuudessanne siitä päivästä alkaen, jona te kuulitte ja opitte tuntemaan Jumalan armon totuudessa,'),
(1698402,58,51,1,7,'niinkuin te sen opitte Epafraalta, meidän rakkaalta kanssapalvelijaltamme, joka on uskollinen Kristuksen palvelija teidän hyväksenne'),
(1698403,58,51,1,8,'ja joka myös on kertonut meille teidän rakkaudestanne Hengessä.'),
(1698404,58,51,1,9,'Sentähden emme mekään, siitä päivästä alkaen, jona sen kuulimme, ole lakanneet teidän edestänne rukoilemasta ja anomasta, että tulisitte täyteen hänen tahtonsa tuntemista kaikessa hengellisessä viisaudessa ja ymmärtämisessä,'),
(1698405,58,51,1,10,'vaeltaaksenne Herran edessä arvollisesti, hänelle kaikessa otollisesti, kaikessa hyvässä työssä hedelmää kantaen ja kasvaen Jumalan tuntemisen kautta,'),
(1698406,58,51,1,11,'ja hänen kirkkautensa väkevyyden mukaan kaikella voimalla vahvistettuina olemaan kaikessa kestäviä ja pitkämielisiä, ilolla'),
(1698407,58,51,1,12,'kiittäen Isää, joka on tehnyt teidät soveliaiksi olemaan osalliset siitä perinnöstä, mikä pyhillä on valkeudessa,'),
(1698408,58,51,1,13,'häntä, joka on pelastanut meidät pimeyden vallasta ja siirtänyt meidät rakkaan Poikansa valtakuntaan.'),
(1698409,58,51,1,14,'Hänessä meillä on lunastus, syntien anteeksisaaminen,'),
(1698410,58,51,1,15,'ja hän on näkymättömän Jumalan kuva, esikoinen ennen kaikkea luomakuntaa.'),
(1698411,58,51,1,16,'Sillä hänessä luotiin kaikki, mikä taivaissa ja mikä maan päällä on, näkyväiset ja näkymättömät, olkoot ne valtaistuimia tai herrauksia, hallituksia tai valtoja, kaikki on luotu hänen kauttansa ja häneen,'),
(1698412,58,51,1,17,'ja hän on ennen kaikkia, ja hänessä pysyy kaikki voimassa.'),
(1698413,58,51,1,18,'Ja hän on ruumiin, se on: seurakunnan, pää; hän, joka on alku, esikoinen kuolleista nousseitten joukossa, että hän olisi kaikessa ensimmäinen.'),
(1698414,58,51,1,19,'Sillä Jumala näki hyväksi, että kaikki täyteys hänessä asuisi'),
(1698415,58,51,1,20,'ja että hän, tehden rauhan hänen ristinsä veren kautta, hänen kauttaan sovittaisi itsensä kanssa kaikki, hänen kauttaan kaikki sekä maan päällä että taivaissa.'),
(1698416,58,51,1,21,'Teidätkin, jotka ennen olitte vieraantuneet ja mieleltänne hänen vihamiehiänsä pahoissa teoissanne, hän nyt on sovittanut'),
(1698417,58,51,1,22,'Poikansa lihan ruumiissa kuoleman kautta, asettaakseen teidät pyhinä ja nuhteettomina ja moitteettomina eteensä,'),
(1698418,58,51,1,23,'jos te vain pysytte uskossa, siihen perustuneina ja siinä lujina, horjahtamatta pois sen evankeliumin toivosta, jonka olette kuulleet, jota on julistettu kaikessa luomakunnassa taivaan alla ja jonka palvelijaksi minä, Paavali, olen tullut.'),
(1698419,58,51,1,24,'Nyt minä iloitsen kärsiessäni teidän tähtenne, ja mikä vielä puuttuu Kristuksen ahdistuksista, sen minä täytän lihassani hänen ruumiinsa hyväksi, joka on seurakunta,'),
(1698420,58,51,1,25,'jonka palvelijaksi minä olen tullut Jumalan armotalouden mukaan, joka minulle on annettu teitä varten, täydellisesti julistaakseni Jumalan sanan,'),
(1698421,58,51,1,26,'sen salaisuuden, joka on ollut kätkettynä ikuisista ajoista ja polvesta polveen, mutta joka nyt on ilmoitettu hänen pyhillensä,'),
(1698422,58,51,1,27,'joille Jumala tahtoi tehdä tiettäväksi, kuinka suuri pakanain keskuudessa on tämän salaisuuden kirkkaus: Kristus teissä, kirkkauden toivo.'),
(1698423,58,51,1,28,'Ja häntä me julistamme, neuvoen jokaista ihmistä ja opettaen jokaista ihmistä kaikella viisaudella, asettaaksemme esiin jokaisen ihmisen täydellisenä Kristuksessa.'),
(1698424,58,51,1,29,'Sitä varten minä vaivaa näenkin, taistellen hänen vaikutuksensa mukaan, joka minussa voimallisesti vaikuttaa.'),
(1698425,58,51,2,1,'Sillä minä tahdon, että te tiedätte, kuinka suuri kilvoittelu minulla on teidän tähtenne ja laodikealaisten ja kaikkien tähden, jotka eivät ole minun ruumiillisia kasvojani nähneet,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698426,58,51,2,2,'että heidän sydämensä, yhteenliittyneinä rakkaudessa, saisivat kehoitusta omistamaan täyden ymmärtämyksen koko rikkauden ja pääsisivät tuntemaan Jumalan salaisuuden, Kristuksen,'),
(1698427,58,51,2,3,'jossa kaikki viisauden ja tiedon aarteet ovat kätkettyinä.'),
(1698428,58,51,2,4,'Tämän minä sanon, ettei kukaan teitä pettäisi suostuttelevilla puheilla.'),
(1698429,58,51,2,5,'Sillä jos ruumiillisesti olenkin poissa, olen kuitenkin teidän kanssanne hengessä ja iloitsen nähdessäni järjestyksen, joka teidän keskuudessanne vallitsee, ja teidän lujan uskonne Kristukseen.'),
(1698430,58,51,2,6,'Niinkuin te siis olette omaksenne ottaneet Kristuksen Jeesuksen, Herran, niin vaeltakaa hänessä,'),
(1698431,58,51,2,7,'juurtuneina häneen ja hänessä rakentuen ja uskossa vahvistuen, niinkuin teille on opetettu; ja olkoon teidän kiitoksenne ylitsevuotavainen.'),
(1698432,58,51,2,8,'Katsokaa, ettei kukaan saa teitä saaliikseen järkeisopilla ja tyhjällä petoksella, pitäytyen ihmisten perinnäissääntöihin ja maailman alkeisvoimiin eikä Kristukseen.'),
(1698433,58,51,2,9,'Sillä hänessä asuu jumaluuden koko täyteys ruumiillisesti,'),
(1698434,58,51,2,10,'ja te olette täytetyt hänessä, joka on kaiken hallituksen ja vallan pää,'),
(1698435,58,51,2,11,'ja hänessä te myös olette ympärileikatut, ette käsintehdyllä ympärileikkauksella, vaan lihan ruumiin poisriisumisella, Kristuksen ympärileikkauksella:'),
(1698436,58,51,2,12,'ollen haudattuina hänen kanssaan kasteessa, jossa te myös hänen kanssaan olette herätetyt uskon kautta, jonka vaikuttaa Jumala, joka herätti hänet kuolleista.'),
(1698437,58,51,2,13,'Ja teidät, jotka olitte kuolleet rikoksiinne ja lihanne ympärileikkaamattomuuteen, teidät hän teki eläviksi yhdessä hänen kanssaan, antaen meille anteeksi kaikki rikokset,'),
(1698438,58,51,2,14,'ja pyyhki pois sen kirjoituksen säädöksineen, joka oli meitä vastaan ja oli meidän vastustajamme; sen hän otti meidän tieltämme pois ja naulitsi ristiin.'),
(1698439,58,51,2,15,'Hän riisui aseet hallituksilta ja valloilta ja asetti heidät julkisen häpeän alaisiksi; hän sai heistä hänen kauttaan voiton riemun.'),
(1698440,58,51,2,16,'Älköön siis kukaan teitä tuomitko syömisestä tai juomisesta, älköön myös minkään juhlan tai uudenkuun tai sapatin johdosta,'),
(1698441,58,51,2,17,'jotka vain ovat tulevaisten varjo, mutta ruumis on Kristuksen.'),
(1698442,58,51,2,18,'Älköön teiltä riistäkö voittopalkintoanne kukaan, joka on mieltynyt nöyryyteen ja enkelien palvelemiseen ja pöyhkeilee näyistään ja on lihallisen mielensä turhaan paisuttama'),
(1698443,58,51,2,19,'eikä pitäydy häneen, joka on pää ja josta koko ruumis, nivelten ja jänteiden avulla koossa pysyen, kasvaa Jumalan antamaa kasvua.'),
(1698444,58,51,2,20,'Jos te olette Kristuksen kanssa kuolleet pois maailman alkeisvoimista, miksi te, ikäänkuin eläisitte maailmassa, sallitte määrätä itsellenne säädöksiä:'),
(1698445,58,51,2,21,'"Älä tartu, älä maista, älä koske!"'),
(1698446,58,51,2,22,'- sehän on kaikki tarkoitettu katoamaan käyttämisen kautta - ihmisten käskyjen ja oppien mukaan?'),
(1698447,58,51,2,23,'Tällä kaikella tosin on viisauden maine itsevalitun jumalanpalveluksen ja nöyryyden vuoksi ja sentähden, ettei se ruumista säästä; mutta se on ilman mitään arvoa, ja se tapahtuu lihan tyydyttämiseksi.'),
(1698448,58,51,3,1,'Jos te siis olette herätetyt Kristuksen kanssa, niin etsikää sitä, mikä on ylhäällä, jossa Kristus on, istuen Jumalan oikealla puolella.'),
(1698449,58,51,3,2,'Olkoon mielenne siihen, mikä ylhäällä on, älköön siihen, mikä on maan päällä.'),
(1698450,58,51,3,3,'Sillä te olette kuolleet, ja teidän elämänne on kätkettynä Kristuksen kanssa Jumalassa;'),
(1698451,58,51,3,4,'kun Kristus, meidän elämämme, ilmestyy, silloin tekin hänen kanssaan ilmestytte kirkkaudessa.'),
(1698452,58,51,3,5,'Kuolettakaa siis maalliset jäsenenne: haureus, saastaisuus, kiihko, paha himo ja ahneus, joka on epäjumalanpalvelusta,'),
(1698453,58,51,3,6,'sillä niiden tähden tulee Jumalan viha,'),
(1698454,58,51,3,7,'ja niissä tekin ennen vaelsitte, kun niissä elitte.'),
(1698455,58,51,3,8,'Mutta nyt pankaa tekin pois ne kaikki: viha, kiivastus, pahuus, herjaus ja häpeällinen puhe suustanne.'),
(1698456,58,51,3,9,'Älkää puhuko valhetta toisistanne, te, jotka olette riisuneet pois vanhan ihmisen tekoinensa'),
(1698457,58,51,3,10,'ja pukeutuneet uuteen, joka uudistuu tietoon, Luojansa kuvan mukaan.'),
(1698458,58,51,3,11,'Ja tässä ei ole kreikkalaista eikä juutalaista, ei ympärileikkausta eikä ympärileikkaamattomuutta, ei barbaaria, ei skyyttalaista, ei orjaa, ei vapaata, vaan kaikki ja kaikissa on Kristus.'),
(1698459,58,51,3,12,'Pukeutukaa siis te, jotka olette Jumalan valituita, pyhiä ja rakkaita, sydämelliseen armahtavaisuuteen, ystävällisyyteen, nöyryyteen, sävyisyyteen, pitkämielisyyteen,'),
(1698460,58,51,3,13,'kärsikää toinen toistanne ja antakaa toisillenne anteeksi, jos kenellä on moitetta toista vastaan. Niinkuin Herrakin on antanut teille anteeksi, niin myös te antakaa.'),
(1698461,58,51,3,14,'Mutta kaiken tämän lisäksi pukeutukaa rakkauteen, mikä on täydellisyyden side.'),
(1698462,58,51,3,15,'Ja vallitkoon teidän sydämissänne Kristuksen rauha, johon te olette kutsututkin yhdessä ruumiissa, ja olkaa kiitolliset.'),
(1698463,58,51,3,16,'Runsaasti asukoon teissä Kristuksen sana; opettakaa ja neuvokaa toinen toistanne kaikessa viisaudessa, psalmeilla, kiitosvirsillä ja hengellisillä lauluilla, veisaten kiitollisesti Jumalalle sydämissänne.'),
(1698464,58,51,3,17,'Ja kaikki, minkä teette sanalla tai työllä, kaikki tehkää Herran Jeesuksen nimessä, kiittäen Isää Jumalaa hänen kauttansa.'),
(1698465,58,51,3,18,'Vaimot, olkaa miehillenne alamaiset, niinkuin sopii Herrassa.'),
(1698466,58,51,3,19,'Miehet, rakastakaa vaimojanne, älkääkä olko heitä kohtaan katkerat.'),
(1698467,58,51,3,20,'Lapset, olkaa vanhemmillenne kuuliaiset kaikessa, sillä se on otollista Herrassa.'),
(1698468,58,51,3,21,'Isät, älkää kiihoittako lapsianne, etteivät he kävisi aroiksi.'),
(1698469,58,51,3,22,'Palvelijat, olkaa maallisille isännillenne kaikessa kuuliaiset, ei silmänpalvelijoina, ihmisille mieliksi, vaan sydämen yksinkertaisuudessa peljäten Herraa.'),
(1698470,58,51,3,23,'Kaikki, mitä teette, se tehkää sydämestänne, niinkuin Herralle eikä ihmisille,'),
(1698471,58,51,3,24,'tietäen, että te saatte Herralta palkaksi perinnön; te palvelette Herraa Kristusta.'),
(1698472,58,51,3,25,'Sillä se, joka tekee väärin, on saava takaisin, mitä on väärin tehnyt; ja henkilöön ei katsota.'),
(1698473,58,51,4,1,'Isännät, tehkää palvelijoillenne, mitä oikeus ja kohtuus vaatii, sillä te tiedätte, että teilläkin on Herra taivaassa.'),
(1698474,58,51,4,2,'Olkaa kestäväiset rukouksessa ja siinä kiittäen valvokaa,'),
(1698475,58,51,4,3,'rukoillen samalla meidänkin edestämme, että Jumala avaisi meille sanan oven puhuaksemme Kristuksen salaisuutta, jonka tähden minä myös olen sidottuna,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698476,58,51,4,4,'että minä sen ilmoittaisin, niinkuin minun tulee puhua.'),
(1698477,58,51,4,5,'Vaelluksessanne olkaa viisaat ulkopuolella olevia kohtaan, ja ottakaa vaari oikeasta hetkestä.'),
(1698478,58,51,4,6,'Olkoon puheenne aina suloista, suolalla höystettyä, ja tietäkää, kuinka teidän tulee itsekullekin vastata.'),
(1698479,58,51,4,7,'Kaikista minun oloistani antaa teille tiedon Tykikus, rakas veli ja uskollinen palvelija, minun kanssapalvelijani Herrassa.'),
(1698480,58,51,4,8,'Hänet minä lähetän teidän tykönne juuri sitä varten, että saisitte tietää tilamme ja että hän lohduttaisi teidän sydämiänne;'),
(1698481,58,51,4,9,'ja myös Onesimuksen, uskollisen ja rakkaan veljen, joka on teikäläisiä; he ilmoittavat teille, kuinka täällä kaikki on.'),
(1698482,58,51,4,10,'Teille lähettää tervehdyksen Aristarkus, minun vankitoverini, ja Markus, Barnabaan serkku, josta olette saaneet ohjeita - jos hän tulee teidän tykönne, niin ottakaa hänet vastaan -'),
(1698483,58,51,4,11,'ja Jeesus, jota sanotaan Justukseksi; nämä ovat ympärileikatuista ainoat, jotka ovat olleet minun auttajani työssä Jumalan valtakunnan hyväksi, ja he ovat olleet minulle lohdutukseksi.'),
(1698484,58,51,4,12,'Tervehdyksen lähettää teille teikäläinen Epafras, Kristuksen Jeesuksen palvelija, joka rukouksissaan aina taistelee teidän puolestanne, että te pysyisitte täydellisinä ja täysin vahvoina kaikessa, mikä on Jumalan tahto.'),
(1698485,58,51,4,13,'Sillä minä annan hänestä sen todistuksen, että hän näkee paljon vaivaa teidän hyväksenne ja niiden hyväksi, jotka ovat Laodikeassa, sekä niiden, jotka ovat Hierapolissa.'),
(1698486,58,51,4,14,'Luukas, rakas lääkäri, lähettää teille tervehdyksen, niin myös Deemas.'),
(1698487,58,51,4,15,'Tervehdys Laodikeassa oleville veljille ja Nymfalle sekä hänen kodissaan kokoontuvalle seurakunnalle.'),
(1698488,58,51,4,16,'Ja kun tämä kirje on luettu teille, niin toimittakaa, että se luetaan Laodikeankin seurakunnassa ja että myös te luette Laodikeasta tulevan kirjeen.'),
(1698489,58,51,4,17,'Ja sanokaa Arkippukselle: "Ota vaari virasta, jonka olet saanut Herrassa, että sen täysin toimitat".'),
(1698490,58,51,4,18,'Tervehdys minulta, Paavalilta, omakätisesti. Muistakaa minun kahleitani. Armo olkoon teidän kanssanne.'),
(1698491,58,52,1,1,'Paavali ja Silvanus ja Timoteus tessalonikalaisten seurakunnalle Isässä Jumalassa ja Herrassa Jeesuksessa Kristuksessa. Armo teille ja rauha!'),
(1698492,58,52,1,2,'Me kiitämme Jumalaa aina kaikkien teidän tähtenne, mainiten teitä rukouksissamme, sillä lakkaamatta'),
(1698493,58,52,1,3,'me Jumalamme ja Isämme edessä muistamme teidän työtänne uskossa ja vaivannäköänne rakkaudessa ja kärsivällisyyttänne toivossa Herraamme Jeesukseen Kristukseen,'),
(1698494,58,52,1,4,'tietäen, veljet, te Jumalan rakastetut, teidän valitsemisenne:'),
(1698495,58,52,1,5,'että meidän evankeliumimme tuli teidän tykönne, ei ainoastaan sanana, vaan myös voimana ja Pyhässä Hengessä ja suurella varmuudella - niinkuin tiedätte, millaisia me olimme teidän keskuudessanne, teidän tähtenne -'),
(1698496,58,52,1,6,'ja teistä tuli meidän seuraajiamme ja Herran, kun suuressa ahdingossa otitte sanan vastaan ilolla Pyhässä Hengessä,'),
(1698497,58,52,1,7,'niin että te olette tulleet esikuviksi kaikille uskoville Makedoniassa ja Akaiassa.'),
(1698498,58,52,1,8,'Sillä teidän tyköänne on Herran sana kaikunut; ei ainoastaan Makedoniaan ja Akaiaan, vaan kaikkialle on teidän uskonne Jumalaan levinnyt, niin ettei meidän tarvitse siitä mitään puhua.'),
(1698499,58,52,1,9,'Sillä itse he kertovat meistä, millainen meidän tulomme teidän tykönne oli ja kuinka te epäjumalista käännyitte Jumalan tykö, palvelemaan elävää ja totista Jumalaa'),
(1698500,58,52,1,10,'ja odottamaan taivaista hänen Poikaansa, jonka hän on herättänyt kuolleista, Jeesusta, joka pelastaa meidät tulevasta vihasta.'),
(1698501,58,52,2,1,'Tiedättehän itsekin, veljet, ettei tulomme teidän tykönne ollut turha;'),
(1698502,58,52,2,2,'vaan, vaikka me ennen, niinkuin tiedätte, olimme kärsineet Filippissä ja meitä siellä oli pahoin pidelty, oli meillä kuitenkin Jumalassamme rohkeutta puhua teille Jumalan evankeliumia, suuressa kilvoituksessa.'),
(1698503,58,52,2,3,'Sillä meidän kehoituspuheemme ei lähde eksymyksestä eikä epäpuhtaasta mielestä eikä ole kavaluudessa puhuttua;'),
(1698504,58,52,2,4,'vaan niinkuin Jumala on katsonut meidän kelpaavan siihen, että meille uskottiin evankeliumi, niin me puhumme, emme, niinkuin tahtoisimme olla mieliksi ihmisille, vaan Jumalalle, joka koettelee meidän sydämemme.'),
(1698505,58,52,2,5,'Sillä me emme koskaan ole liikkuneet liehakoivin sanoin, sen te tiedätte, emmekä millään tekosyyllä voittoa ahnehtineet; Jumala on todistajamme,'),
(1698506,58,52,2,6,'emmekä ole etsineet kunniaa ihmisiltä, emme teiltä emmekä muilta,'),
(1698507,58,52,2,7,'vaikka me Kristuksen apostoleina olisimme voineet vaatia arvonantoa; vaan me olimme lempeät teidän keskuudessanne, niinkuin imettävä äiti, joka vaalii lapsiansa;'),
(1698508,58,52,2,8,'niin mekin, teitä hellien, halusimme antaa teille, ei ainoastaan Jumalan evankeliumia, vaan oman henkemmekin, sillä te olitte meille rakkaiksi tulleet.'),
(1698509,58,52,2,9,'Muistattehan, veljet, meidän työmme ja vaivamme: yöt ja päivät työtä tehden, ettemme ketään teistä rasittaisi, me julistimme teille Jumalan evankeliumia.'),
(1698510,58,52,2,10,'Te olette meidän todistajamme, ja Jumala, kuinka pyhät ja oikeamieliset ja nuhteettomat me olimme teitä kohtaan, jotka uskotte,'),
(1698511,58,52,2,11,'samoinkuin te tiedätte, kuinka me, niinkuin isä lapsiansa, kehoitimme itsekutakin teistä ja rohkaisimme teitä,'),
(1698512,58,52,2,12,'ja teroitimme teille, että teidän on vaeltaminen arvollisesti Jumalan edessä, joka kutsuu teitä valtakuntaansa ja kirkkauteensa.'),
(1698513,58,52,2,13,'Ja sentähden me myös lakkaamatta kiitämme Jumalaa siitä, että te, kun saitte meiltä kuulemanne Jumalan sanan, otitte sen vastaan, ette ihmisten sanana, vaan, niinkuin se totisesti on, Jumalan sanana, joka myös vaikuttaa teissä, jotka uskotte.'),
(1698514,58,52,2,14,'Sillä teistä, veljet, on tullut niiden Kristuksessa Jeesuksessa olevien Jumalan seurakuntain seuraajia, jotka ovat Juudeassa, sillä tekin olette kärsineet omilta kansalaisiltanne samaa kuin he juutalaisilta,'),
(1698515,58,52,2,15,'jotka tappoivat Herran Jeesuksenkin ja profeetat ja ovat vainonneet meitä, eivätkä ole Jumalalle otollisia, vaan ovat kaikkien ihmisten vihollisia,'),
(1698516,58,52,2,16,'kun estävät meitä puhumasta pakanoille heidän pelastumiseksensa. Näin he yhäti täyttävät syntiensä mittaa. Viha onkin jo saavuttanut heidät, viimeiseen määräänsä asti.'),
(1698517,58,52,2,17,'Mutta kun meidät nyt, veljet, on hetkeksi aikaa erotettu teistä, ulkonaisesti, ei sydämeltä, niin on meille tullut yhä suurempi halu päästä näkemään teidän kasvojanne.'),
(1698518,58,52,2,18,'Sentähden olemme tahtoneet tulla teidän tykönne, minä, Paavali, puolestani, en vain kerran, vaan kahdestikin, mutta saatana on meidät estänyt.'),
(1698519,58,52,2,19,'Sillä kuka on meidän toivomme tai ilomme tai meidän kerskauksemme kruunu? Ettekö myös te, meidän Herramme Jeesuksen edessä hänen tulemuksessaan?'),
(1698520,58,52,2,20,'Sillä te olette meidän kunniamme ja meidän ilomme.'),
(1698521,58,52,3,1,'Sentähden me, kun emme enää voineet kestää kauemmin, päätimme jäädä yksinämme Ateenaan,'),
(1698522,58,52,3,2,'ja lähetimme Timoteuksen, veljemme ja Jumalan palvelijan Kristuksen evankeliumissa, vahvistamaan teitä ja rohkaisemaan teitä uskossanne,'),
(1698523,58,52,3,3,'ettei kukaan horjuisi näissä ahdingoissa. Sillä itse te tiedätte, että meidät on semmoisiin pantu.'),
(1698524,58,52,3,4,'Sanoimmehan, kun olimme teidän tykönänne, teille jo edeltäpäin, että meidän oli ahdinkoon joutuminen, niinkuin on käynytkin ja te tiedätte käyneen.'),
(1698525,58,52,3,5,'Sentähden minä, kun en enää jaksanut kestää kauemmin, lähetinkin tiedustelemaan teidän uskoanne, ettei vain kiusaaja liene teitä kiusannut ja meidän vaivannäkömme mennyt hukkaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698526,58,52,3,6,'Mutta nyt, kun Timoteus tuli teidän tyköänne meidän tykömme ja toi meille ilosanoman teidän uskostanne ja rakkaudestanne ja siitä, että te aina pidätte meitä rakkaassa muistossa ikävöiden meitä nähdäksenne niinkuin mekin teitä:'),
(1698527,58,52,3,7,'sentähden olemme teidän uskostanne, veljet, saaneet lohdutusta teihin nähden kaikessa hädässämme ja ahdistuksessamme;'),
(1698528,58,52,3,8,'sillä nyt me elämme, jos te seisotte lujina Herrassa.'),
(1698529,58,52,3,9,'Kuinka voimmekaan kyllin kiittää Jumalaa teidän tähtenne kaikesta siitä ilosta, mikä meillä teistä on Jumalamme edessä!'),
(1698530,58,52,3,10,'Öin ja päivin me mitä hartaimmin rukoilemme saadaksemme nähdä teidän kasvonne ja täyttää sen, mitä teidän uskostanne puuttuu.'),
(1698531,58,52,3,11,'Mutta hän itse, meidän Jumalamme ja Isämme, ja meidän Herramme Jeesus ohjatkoon meidän tiemme teidän tykönne.'),
(1698532,58,52,3,12,'Ja teille Herra antakoon yhä enemmän ja runsaammin rakkautta toisianne kohtaan ja kaikkia kohtaan, niinkuin meilläkin on teitä kohtaan,'),
(1698533,58,52,3,13,'vahvistaaksensa teidän sydämenne nuhteettomiksi pyhyydessä meidän Jumalamme ja Isämme edessä, meidän Herramme Jeesuksen tulemuksessa, kun hän tulee kaikkien pyhiensä kanssa.'),
(1698534,58,52,4,1,'Sitten vielä, veljet, me pyydämme teitä ja kehoitamme Herrassa Jeesuksessa, että te, niinkuin olette meiltä oppineet, miten teidän tulee vaeltaa ja olla Jumalalle otolliset, niinkuin vaellattekin, siinä yhä enemmän varttuisitte.'),
(1698535,58,52,4,2,'Tiedättehän, mitkä käskyt me olemme Herran Jeesuksen kautta teille antaneet.'),
(1698536,58,52,4,3,'Sillä tämä on Jumalan tahto, teidän pyhityksenne, että kartatte haureutta,'),
(1698537,58,52,4,4,'että kukin teistä tietää ottaa oman vaimon pyhyydessä ja kunniassa,'),
(1698538,58,52,4,5,'ei himon kiihkossa niinkuin pakanat, jotka eivät Jumalaa tunne;'),
(1698539,58,52,4,6,'ettei kukaan sorra veljeänsä eikä tuota hänelle vahinkoa missään asiassa, sillä Herra on kaiken tämän kostaja, niinkuin myös ennen olemme teille sanoneet ja todistaneet.'),
(1698540,58,52,4,7,'Sillä ei Jumala ole kutsunut meitä saastaisuuteen, vaan pyhitykseen.'),
(1698541,58,52,4,8,'Sentähden, joka nämä hylkää, ei hylkää ihmistä, vaan Jumalan, joka myös antaa Pyhän Henkensä teihin.'),
(1698542,58,52,4,9,'Veljellisestä rakkaudesta ei ole tarvis teille kirjoittaa; sillä itse te olette Jumalalta oppineet rakastamaan toisianne;'),
(1698543,58,52,4,10,'niin te myös teette kaikkia veljiä kohtaan koko Makedoniassa. Mutta me kehoitamme teitä, veljet, siinä varttumaan yhä enemmän'),
(1698544,58,52,4,11,'ja katsomaan kunniaksenne, että elätte hiljaisuudessa ja toimitatte omia tehtäviänne ja teette työtä käsillänne, niinkuin olemme teitä käskeneet,'),
(1698545,58,52,4,12,'että vaelluksessanne olisitte säädylliset ulkopuolella olevia kohtaan ettekä olisi kenenkään avun tarpeessa.'),
(1698546,58,52,4,13,'Mutta me emme tahdo pitää teitä, veljet, tietämättöminä siitä, kuinka poisnukkuneiden on, ettette murehtisi niinkuin muut, joilla ei toivoa ole.'),
(1698547,58,52,4,14,'Sillä jos uskomme, että Jeesus on kuollut ja noussut ylös, niin samoin on Jumala Jeesuksen kautta myös tuova poisnukkuneet esiin yhdessä hänen kanssaan.'),
(1698548,58,52,4,15,'Sillä sen me sanomme teille Herran sanana, että me, jotka olemme elossa, jotka jäämme tänne Herran tulemukseen, emme suinkaan ehdi ennen niitä, jotka ovat nukkuneet.'),
(1698549,58,52,4,16,'Sillä itse Herra on tuleva alas taivaasta käskyhuudon, ylienkelin äänen ja Jumalan pasunan kuuluessa, ja Kristuksessa kuolleet nousevat ylös ensin;'),
(1698550,58,52,4,17,'sitten meidät, jotka olemme elossa, jotka olemme jääneet tänne, temmataan yhdessä heidän kanssaan pilvissä Herraa vastaan yläilmoihin; ja niin me saamme aina olla Herran kanssa.'),
(1698551,58,52,4,18,'Niin lohduttakaa siis toisianne näillä sanoilla.'),
(1698552,58,52,5,1,'Mutta aikakausista ja määrähetkistä ei teille, veljet, ole tarvis kirjoittaa;'),
(1698553,58,52,5,2,'sillä itse te varsin hyvin tiedätte, että Herran päivä tulee niinkuin varas yöllä.'),
(1698554,58,52,5,3,'Kun he sanovat: "Nyt on rauha, ei hätää mitään", silloin yllättää heidät yhtäkkiä turmio, niinkuin synnytyskipu raskaan vaimon, eivätkä he pääse pakoon.'),
(1698555,58,52,5,4,'Mutta te, veljet, ette ole pimeydessä, niin että se päivä voisi yllättää teidät niinkuin varas;'),
(1698556,58,52,5,5,'sillä kaikki te olette valkeuden lapsia ja päivän lapsia; me emme ole yön emmekä pimeyden lapsia.'),
(1698557,58,52,5,6,'Älkäämme siis nukkuko niinkuin muut, vaan valvokaamme ja olkaamme raittiit.'),
(1698558,58,52,5,7,'Sillä ne, jotka nukkuvat, ne yöllä nukkuvat, ja jotka juovat itsensä juovuksiin, ne yöllä juovuksissa ovat.'),
(1698559,58,52,5,8,'Mutta me, jotka olemme päivän lapsia, olkaamme raittiit, ja olkoon pukunamme uskon ja rakkauden haarniska ja kypärinämme pelastuksen toivo.'),
(1698560,58,52,5,9,'Sillä ei Jumala ole määrännyt meitä vihaan, vaan saamaan pelastuksen Herramme Jeesuksen Kristuksen kautta,'),
(1698561,58,52,5,10,'joka on kuollut meidän edestämme, että me, valvoimmepa tai nukuimme, eläisimme yhdessä hänen kanssaan.'),
(1698562,58,52,5,11,'Sentähden kehoittakaa toisianne ja rakentakaa toinen toistanne, niinkuin teettekin.'),
(1698563,58,52,5,12,'Mutta me pyydämme teitä, veljet, antamaan tunnustuksenne niille, jotka tekevät työtä teidän keskuudessanne ja ovat teidän johtajanne Herrassa ja neuvovat teitä,'),
(1698564,58,52,5,13,'sekä pitämään heitä erinomaisen rakkaina heidän työnsä tähden. Eläkää rauhassa keskenänne.'),
(1698565,58,52,5,14,'Me kehoitamme teitä, veljet: nuhdelkaa kurittomia, rohkaiskaa alakuloisia, holhotkaa heikkoja, olkaa pitkämieliset kaikkia kohtaan.'),
(1698566,58,52,5,15,'Katsokaa, ettei kukaan kosta kenellekään pahaa pahalla, vaan pyrkikää aina tekemään hyvää toinen toisellenne ja kaikille.'),
(1698567,58,52,5,16,'Olkaa aina iloiset.'),
(1698568,58,52,5,17,'Rukoilkaa lakkaamatta.'),
(1698569,58,52,5,18,'Kiittäkää joka tilassa. Sillä se on Jumalan tahto teihin nähden Kristuksessa Jeesuksessa.'),
(1698570,58,52,5,19,'Henkeä älkää sammuttako,'),
(1698571,58,52,5,20,'profetoimista älkää halveksuko,'),
(1698572,58,52,5,21,'mutta koetelkaa kaikki, pitäkää se, mikä hyvää on;'),
(1698573,58,52,5,22,'karttakaa kaikenkaltaista pahaa.'),
(1698574,58,52,5,23,'Mutta itse rauhan Jumala pyhittäköön teidät kokonansa, ja säilyköön koko teidän henkenne ja sielunne ja ruumiinne nuhteettomana meidän Herramme Jeesuksen Kristuksen tulemukseen.'),
(1698575,58,52,5,24,'Hän, joka teitä kutsuu, on uskollinen, ja hän on sen myös tekevä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698576,58,52,5,25,'Veljet, rukoilkaa meidän edestämme.'),
(1698577,58,52,5,26,'Tervehtikää kaikkia veljiä pyhällä suunannolla.'),
(1698578,58,52,5,27,'Minä vannotan teitä Herran kautta, että luetatte tämän kirjeen kaikille veljille.'),
(1698579,58,52,5,28,'Meidän Herramme Jeesuksen Kristuksen armo olkoon teidän kanssanne.'),
(1698580,58,53,1,1,'Paavali ja Silvanus ja Timoteus tessalonikalaisten seurakunnalle Jumalassa, meidän Isässämme, ja Herrassa Jeesuksessa Kristuksessa.'),
(1698581,58,53,1,2,'Armo teille ja rauha Isältä Jumalalta ja Herralta Jeesukselta Kristukselta!'),
(1698582,58,53,1,3,'Me olemme velvolliset aina kiittämään Jumalaa teidän tähtenne, veljet, niinkuin oikein onkin, koska teidän uskonne runsaasti kasvaa ja keskinäinen rakkautenne lisääntyy itsekussakin, kaikissa teissä,'),
(1698583,58,53,1,4,'niin että me itsekin Jumalan seurakunnissa kerskaamme teistä, teidän kärsivällisyydestänne ja uskostanne kaikissa vainoissanne ja ahdistuksissa, joita teillä on kestettävänä'),
(1698584,58,53,1,5,'ja jotka ovat osoituksena Jumalan vanhurskaasta tuomiosta, että teidät katsottaisiin arvollisiksi Jumalan valtakuntaan, jonka tähden kärsittekin,'),
(1698585,58,53,1,6,'koskapa Jumala katsoo oikeaksi kostaa ahdistuksella niille, jotka teitä ahdistavat,'),
(1698586,58,53,1,7,'ja antaa teille, joita ahdistetaan, levon yhdessä meidän kanssamme, kun Herra Jeesus ilmestyy taivaasta voimansa enkelien kanssa'),
(1698587,58,53,1,8,'tulen liekissä ja kostaa niille, jotka eivät tunne Jumalaa eivätkä ole kuuliaisia meidän Herramme Jeesuksen evankeliumille.'),
(1698588,58,53,1,9,'Heitä kohtaa silloin rangaistukseksi iankaikkinen kadotus Herran kasvoista ja hänen voimansa kirkkaudesta,'),
(1698589,58,53,1,10,'kun hän sinä päivänä tulee, että hän kirkastuisi pyhissänsä ja olisi ihmeteltävä kaikissa uskovissa, sillä te olette uskoneet meidän todistuksemme.'),
(1698590,58,53,1,11,'Sitä varten me aina rukoilemmekin teidän puolestanne, että meidän Jumalamme katsoisi teidät kutsumisensa arvoisiksi ja voimallisesti saattaisi täydelliseksi kaiken teidän halunne hyvään ja teidän uskonne teot,'),
(1698591,58,53,1,12,'että meidän Herramme Jeesuksen nimi teissä kirkastuisi ja te hänessä, meidän Jumalamme ja Herran Jeesuksen Kristuksen armon mukaan.'),
(1698592,58,53,2,1,'Mutta mitä tulee meidän Herramme Jeesuksen Kristuksen tulemukseen ja meidän kokoontumiseemme hänen tykönsä, niin me pyydämme teitä, veljet,'),
(1698593,58,53,2,2,'ettette anna minkään hengen ettekä sanan ettekä minkään muka meidän lähettämämme kirjeen heti järkyttää itseänne, niin että menetätte mielenne maltin, ettekä anna niiden itseänne peljästyttää, ikäänkuin Herran päivä jo olisi käsissä.'),
(1698594,58,53,2,3,'Älkää antako kenenkään vietellä itseänne millään tavalla. Sillä se päivä ei tule, ennenkuin luopumus ensin tapahtuu ja laittomuuden ihminen ilmestyy, kadotuksen lapsi,'),
(1698595,58,53,2,4,'tuo vastustaja, joka korottaa itsensä yli kaiken, mitä jumalaksi tai jumaloitavaksi kutsutaan, niin että hän asettuu Jumalan temppeliin ja julistaa olevansa Jumala.'),
(1698596,58,53,2,5,'Ettekö muista, että minä, kun vielä olin teidän tykönänne, sanoin tämän teille?'),
(1698597,58,53,2,6,'Ja nyt te tiedätte, mikä pidättää, niin että hän vasta ajallansa ilmestyy.'),
(1698598,58,53,2,7,'Sillä laittomuuden salaisuus on jo vaikuttamassa; jahka vain tulee tieltä poistetuksi se, joka nyt vielä pidättää,'),
(1698599,58,53,2,8,'niin silloin ilmestyy tuo laiton, jonka Herra Jeesus on surmaava suunsa henkäyksellä ja tuhoava tulemuksensa ilmestyksellä,'),
(1698600,58,53,2,9,'tuo, jonka tulemus tapahtuu saatanan vaikutuksesta valheen kaikella voimalla ja tunnusteoilla ja ihmeillä'),
(1698601,58,53,2,10,'ja kaikilla vääryyden viettelyksillä niille, jotka joutuvat kadotukseen, sentähden etteivät ottaneet vastaan rakkautta totuuteen, voidaksensa pelastua.'),
(1698602,58,53,2,11,'Ja sentähden Jumala lähettää heille väkevän eksytyksen, niin että he uskovat valheen,'),
(1698603,58,53,2,12,'että kaikki ne tuomittaisiin, jotka eivät ole uskoneet totuutta, vaan mielistyneet vääryyteen.'),
(1698604,58,53,2,13,'Mutta me olemme velvolliset aina kiittämään Jumalaa teidän tähtenne, veljet, te Herran rakastetut, sentähden että Jumala alusta alkaen valitsi teidät pelastukseen Hengen pyhityksessä ja uskossa totuuteen.'),
(1698605,58,53,2,14,'Siihen hän on myös kutsunut teidät meidän evankeliumimme kautta, omistamaan meidän Herramme Jeesuksen Kristuksen kirkkauden.'),
(1698606,58,53,2,15,'Niin seisokaa siis, veljet, lujina ja pitäkää kiinni niistä opetuksista, joita olette oppineet joko meidän puheestamme tai kirjeestämme.'),
(1698607,58,53,2,16,'Ja meidän Herramme Jeesus Kristus itse ja Jumala, meidän Isämme, joka on rakastanut meitä ja armossa antanut meille iankaikkisen lohdutuksen ja hyvän toivon,'),
(1698608,58,53,2,17,'lohduttakoon teidän sydämiänne ja vahvistakoon teitä kaikessa hyvässä työssä ja puheessa.'),
(1698609,58,53,3,1,'Sitten vielä, veljet, rukoilkaa meidän edestämme, että Herran sana nopeasti leviäisi ja tulisi kirkastetuksi muuallakin niinkuin teidän keskuudessanne,'),
(1698610,58,53,3,2,'ja että me pelastuisimme nurjista ja häijyistä ihmisistä; sillä usko ei ole joka miehen.'),
(1698611,58,53,3,3,'Mutta Herra on uskollinen, ja hän on vahvistava teitä ja varjeleva teidät pahasta.'),
(1698612,58,53,3,4,'Ja me luotamme teihin Herrassa, että te sekä nyt että vasta teette, mitä me käskemme.'),
(1698613,58,53,3,5,'Ja Herra ohjatkoon teidän sydämenne Jumalan rakkauteen ja Kristuksen kärsivällisyyteen.'),
(1698614,58,53,3,6,'Mutta Herran Jeesuksen Kristuksen nimessä me käskemme teitä, veljet, vetäytymään pois jokaisesta veljestä, joka vaeltaa kurittomasti eikä sen opetuksen mukaan, jonka olette meiltä saaneet.'),
(1698615,58,53,3,7,'Tiedättehän itse, kuinka meidän jälkiämme on seurattava, sillä me emme ole olleet kurittomia teidän keskuudessanne,'),
(1698616,58,53,3,8,'emmekä ilmaiseksi syöneet kenenkään leipää, vaan työssä ja vaivassa me ahkeroitsimme yöt ja päivät, ettemme olisi kenellekään teistä rasitukseksi;'),
(1698617,58,53,3,9,'ei niin, ettei meillä olisi siihen valtaa, vaan me tahdomme olla teille esikuvaksi, että te kulkisitte meidän jälkiämme.'),
(1698618,58,53,3,10,'Sillä jo silloin, kun olimme teidän tykönänne, me sääsimme teille, että kuka ei tahdo työtä tehdä, ei hänen syömänkään pidä.'),
(1698619,58,53,3,11,'Sillä me olemme kuulleet, että muutamat teidän keskuudessanne vaeltavat kurittomasti, eivät tee työtä, vaan puuhailevat sellaisessa, mikä ei heille kuulu.'),
(1698620,58,53,3,12,'Semmoisia me käskemme ja kehoitamme Herrassa Jeesuksessa Kristuksessa, tekemään työtä hiljaisuudessa ja syömään omaa leipäänsä.'),
(1698621,58,53,3,13,'Mutta te, veljet, älkää väsykö tekemästä sitä, mikä hyvää on.'),
(1698622,58,53,3,14,'Mutta jos kuka ei tottele sitä, mitä me tässä kirjeessä olemme sanoneet, niin merkitkää hänet älkääkä seurustelko hänen kanssaan, että hän häpeäisi.'),
(1698623,58,53,3,15,'Älkää kuitenkaan pitäkö häntä vihollisena, vaan neuvokaa niinkuin veljeä.'),
(1698624,58,53,3,16,'Mutta itse rauhan Herra antakoon teille rauhan, aina ja kaikella tavalla. Herra olkoon kaikkien teidän kanssanne.'),
(1698625,58,53,3,17,'Tervehdys minulta, Paavalilta, omakätisesti. Tämä on merkkinä jokaisessa kirjeessäni; näin minä kirjoitan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698626,58,53,3,18,'Meidän Herramme Jeesuksen Kristuksen armo olkoon kaikkien teidän kanssanne.'),
(1698627,58,54,1,1,'Paavali, Kristuksen Jeesuksen apostoli, Jumalan, meidän vapahtajamme, ja Kristuksen Jeesuksen, meidän toivomme, asettama,'),
(1698628,58,54,1,2,'Timoteukselle, oikealle pojallensa uskossa. Armo, laupeus ja rauha Isältä Jumalalta ja Kristukselta Jeesukselta, meidän Herraltamme!'),
(1698629,58,54,1,3,'Niinkuin minä Makedoniaan lähtiessäni kehoitin sinua jäämään Efesoon, käskeäksesi eräitä kavahtamaan, etteivät vieraita oppeja opettaisi'),
(1698630,58,54,1,4,'eivätkä puuttuisi taruihin ja loppumattomiin sukuluetteloihin, jotka pikemmin edistävät turhaa mietiskelyä kuin Jumalan armotaloutta, joka perustuu uskoon, niin kehoitan nytkin.'),
(1698631,58,54,1,5,'Mutta käskyn päämäärä on rakkaus, joka tulee puhtaasta sydämestä ja hyvästä omastatunnosta ja vilpittömästä uskosta.'),
(1698632,58,54,1,6,'Muutamat ovat hairahtuneet niistä pois ja poikenneet turhiin jaarituksiin,'),
(1698633,58,54,1,7,'tahtoen olla lainopettajia, vaikka eivät ymmärrä, mitä puhuvat ja minkä varmaksi väittävät.'),
(1698634,58,54,1,8,'Mutta me tiedämme, että laki on hyvä, kun sitä lain mukaisesti käytetään'),
(1698635,58,54,1,9,'ja tiedetään, että lakia ei ole pantu vanhurskaalle, vaan laittomille ja niskoitteleville, jumalattomille ja syntisille, epähurskaille ja epäpyhille, isänsä tappajille ja äitinsä tappajille, murhamiehille,'),
(1698636,58,54,1,10,'haureellisille, miehimyksille, ihmiskauppiaille, valhettelijoille, valapattoisille ja kaikelle muulle, mikä on tervettä oppia vastaan -'),
(1698637,58,54,1,11,'autuaan Jumalan kirkkauden evankeliumin mukaisesti, joka on minulle uskottu.'),
(1698638,58,54,1,12,'Minä kiitän häntä, joka minulle on voimaa antanut, Kristusta Jeesusta, meidän Herraamme, siitä, että hän katsoi minut uskolliseksi ja asetti palvelukseensa'),
(1698639,58,54,1,13,'minut, entisen pilkkaajan ja vainoojan ja väkivallantekijän. Mutta minä sain laupeuden, koska olin tehnyt sitä tietämättömänä, epäuskossa;'),
(1698640,58,54,1,14,'ja meidän Herramme armo oli ylen runsas, vaikuttaen uskoa ja rakkautta, joka on Kristuksessa Jeesuksessa.'),
(1698641,58,54,1,15,'Varma on se sana ja kaikin puolin vastaanottamisen arvoinen, että Kristus Jeesus on tullut maailmaan syntisiä pelastamaan, joista minä olen suurin.'),
(1698642,58,54,1,16,'Mutta sentähden minä sain laupeuden, että Jeesus Kristus minussa ennen muita osoittaisi kaiken pitkämielisyytensä, esikuvaksi niille, jotka tulevat uskomaan häneen, itsellensä iankaikkiseksi elämäksi.'),
(1698643,58,54,1,17,'Mutta iankaikkiselle kuninkaalle, katoamattomalle, näkymättömälle, ainoalle Jumalalle, kunnia ja kirkkaus aina ja iankaikkisesti! Amen.'),
(1698644,58,54,1,18,'Tämän käskyn minä annan sinun toimitettavaksesi, poikani Timoteus, aikaisempien, sinusta lausuttujen ennustusten mukaisesti, että niiden nojalla taistelisit jalon taistelun,'),
(1698645,58,54,1,19,'säilyttäen uskon ja hyvän omantunnon, jonka eräät ovat hyljänneet ja uskossaan haaksirikkoon joutuneet.'),
(1698646,58,54,1,20,'Niitä ovat Hymeneus ja Aleksander, jotka minä olen antanut saatanan haltuun, kuritettaviksi, etteivät enää pilkkaisi.'),
(1698647,58,54,2,1,'Minä kehoitan siis ennen kaikkea anomaan, rukoilemaan, pitämään esirukouksia ja kiittämään kaikkien ihmisten puolesta,'),
(1698648,58,54,2,2,'kuningasten ja kaiken esivallan puolesta, että saisimme viettää rauhallista ja hiljaista elämää kaikessa jumalisuudessa ja kunniallisuudessa.'),
(1698649,58,54,2,3,'Sillä se on hyvää ja otollista Jumalalle, meidän vapahtajallemme,'),
(1698650,58,54,2,4,'joka tahtoo, että kaikki ihmiset pelastuisivat ja tulisivat tuntemaan totuuden.'),
(1698651,58,54,2,5,'Sillä yksi on Jumala, yksi myös välimies Jumalan ja ihmisten välillä, ihminen Kristus Jeesus,'),
(1698652,58,54,2,6,'joka antoi itsensä lunnaiksi kaikkien edestä, josta todistus oli annettava aikanansa,'),
(1698653,58,54,2,7,'ja sitä varten minä olen saarnaajaksi ja apostoliksi asetettu - minä puhun totta, en valhettele - pakanain opettajaksi uskossa ja totuudessa.'),
(1698654,58,54,2,8,'Minä tahdon siis, että miehet rukoilevat, joka paikassa kohottaen pyhät kädet ilman vihaa ja epäilystä;'),
(1698655,58,54,2,9,'niin myös, että naiset ovat säädyllisessä puvussa, kaunistavat itseään kainosti ja siveästi, ei palmikoiduilla hiuksilla, ei kullalla, ei helmillä eikä kallisarvoisilla vaatteilla,'),
(1698656,58,54,2,10,'vaan hyvillä teoilla, niinkuin sopii naisille, jotka tunnustautuvat jumalaapelkääviksi.'),
(1698657,58,54,2,11,'Oppikoon nainen hiljaisuudessa, kaikin puolin alistuvaisena;'),
(1698658,58,54,2,12,'mutta minä en salli, että vaimo opettaa, enkä että hän vallitsee miestänsä, vaan eläköön hän hiljaisuudessa.'),
(1698659,58,54,2,13,'Sillä Aadam luotiin ensin, sitten Eeva;'),
(1698660,58,54,2,14,'eikä Aadamia petetty, vaan nainen petettiin ja joutui rikkomukseen.'),
(1698661,58,54,2,15,'Mutta hän on pelastuva lastensynnyttämisen kautta, jos hän pysyy uskossa ja rakkaudessa ja pyhityksessä ynnä siveydessä.'),
(1698662,58,54,3,1,'Varma on tämä sana: jos joku pyrkii seurakunnan kaitsijan virkaan, niin hän haluaa jaloon toimeen.'),
(1698663,58,54,3,2,'Niin tulee siis seurakunnan kaitsijan olla nuhteeton, yhden vaimon mies, raitis, maltillinen, säädyllinen, vieraanvarainen, taitava opettamaan,'),
(1698664,58,54,3,3,'ei juomari, ei tappelija, vaan lempeä, ei riitaisa, ei rahanahne,'),
(1698665,58,54,3,4,'vaan sellainen, joka oman kotinsa hyvin hallitsee ja kaikella kunniallisuudella pitää lapsensa kuuliaisina;'),
(1698666,58,54,3,5,'sillä jos joku ei osaa hallita omaa kotiansa, kuinka hän voi pitää huolta Jumalan seurakunnasta?'),
(1698667,58,54,3,6,'Älköön hän olko äsken kääntynyt, ettei hän paisuisi ja joutuisi perkeleen tuomion alaiseksi.'),
(1698668,58,54,3,7,'Ja hänellä tulee myös olla hyvä todistus ulkopuolella olevilta, ettei hän joutuisi häväistyksen alaiseksi eikä perkeleen paulaan.'),
(1698669,58,54,3,8,'Niin myös seurakuntapalvelijain tulee olla arvokkaita, ei kaksikielisiä, ei paljon viinin nauttijoita, ei häpeällisen voiton pyytäjiä,'),
(1698670,58,54,3,9,'vaan sellaisia, jotka pitävät uskon salaisuuden puhtaassa omassatunnossa.'),
(1698671,58,54,3,10,'Mutta heitäkin koeteltakoon ensin, sitten palvelkoot, jos ovat nuhteettomat.'),
(1698672,58,54,3,11,'Samoin tulee vaimojen olla arvokkaita, ei panettelijoita, vaan raittiita, uskollisia kaikessa.'),
(1698673,58,54,3,12,'Seurakuntapalvelija olkoon yhden vaimon mies, lapsensa ja kotinsa hyvin hallitseva.'),
(1698674,58,54,3,13,'Sillä ne, jotka ovat hyvin palvelleet, saavuttavat itselleen kunnioitettavan aseman ja suuren pelottomuuden uskossa, Kristuksessa Jeesuksessa.'),
(1698675,58,54,3,14,'Vaikka toivon pian pääseväni sinun tykösi, kirjoitan sinulle tämän,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698676,58,54,3,15,'että, jos viivyn, tietäisit, miten tulee olla Jumalan huoneessa, joka on elävän Jumalan seurakunta, totuuden pylväs ja perustus.'),
(1698677,58,54,3,16,'Ja tunnustetusti suuri on jumalisuuden salaisuus: Hän, joka on ilmestynyt lihassa, vanhurskautunut Hengessä, näyttäytynyt enkeleille, saarnattu pakanain keskuudessa, uskottu maailmassa, otettu ylös kirkkauteen.'),
(1698678,58,54,4,1,'Mutta Henki sanoo selvästi, että tulevina aikoina moniaat luopuvat uskosta ja noudattavat villitseviä henkiä ja riivaajien oppeja'),
(1698679,58,54,4,2,'valheenpuhujain ulkokultaisuuden vaikutuksesta, joiden omatunto on poltinraudalla merkitty'),
(1698680,58,54,4,3,'ja jotka kieltävät menemästä naimisiin ja nauttimasta ruokia, mitkä Jumala on luonut niiden nautittavaksi kiitoksella, jotka uskovat ja ovat tulleet totuuden tuntemaan.'),
(1698681,58,54,4,4,'Sillä kaikki, minkä Jumala on luonut, on hyvää, eikä mikään ole hyljättävää, kun se kiitoksella vastaanotetaan;'),
(1698682,58,54,4,5,'sillä se pyhitetään Jumalan sanalla ja rukouksella.'),
(1698683,58,54,4,6,'Kun tätä veljille opetat, niin olet hyvä Kristuksen Jeesuksen palvelija, joka ravitset itseäsi uskon ja sen hyvän opin sanoilla, jota olet noudattanut.'),
(1698684,58,54,4,7,'Mutta epäpyhiä ämmäin taruja karta ja harjoita itseäsi jumalisuuteen.'),
(1698685,58,54,4,8,'Sillä ruumiillisesta harjoituksesta on hyötyä vain vähään; mutta jumalisuudesta on hyötyä kaikkeen, koska sillä on elämän lupaus, sekä nykyisen että tulevaisen.'),
(1698686,58,54,4,9,'Varma on se sana ja kaikin puolin vastaanottamisen arvoinen.'),
(1698687,58,54,4,10,'Sillä siksi me vaivaa näemme ja kilvoittelemme, että olemme panneet toivomme elävään Jumalaan, joka on kaikkien ihmisten vapahtaja, varsinkin uskovien.'),
(1698688,58,54,4,11,'Tätä käske ja opeta.'),
(1698689,58,54,4,12,'Älköön kukaan nuoruuttasi katsoko ylen, vaan ole sinä uskovaisten esikuva puheessa, vaelluksessa, rakkaudessa, uskossa, puhtaudessa.'),
(1698690,58,54,4,13,'Lue, kehoita ja opeta ahkerasti, kunnes minä tulen.'),
(1698691,58,54,4,14,'Älä laiminlyö armolahjaa, joka sinussa on ja joka sinulle annettiin profetian kautta, vanhinten pannessa kätensä sinun päällesi.'),
(1698692,58,54,4,15,'Harrasta näitä, elä näissä, että edistymisesi olisi kaikkien nähtävissä.'),
(1698693,58,54,4,16,'Valvo itseäsi ja opetustasi, ole siinä kestävä; sillä jos sen teet, olet pelastava sekä itsesi että ne, jotka sinua kuulevat.'),
(1698694,58,54,5,1,'Älä nuhtele kovasti vanhaa miestä, vaan neuvo niinkuin isää, nuorempia niinkuin veljiä,'),
(1698695,58,54,5,2,'vanhoja naisia niinkuin äitejä, nuorempia niinkuin sisaria, kaikessa puhtaudessa.'),
(1698696,58,54,5,3,'Kunnioita leskiä, jotka ovat oikeita leskiä.'),
(1698697,58,54,5,4,'Mutta jos jollakin leskellä on lapsia tai lapsenlapsia, oppikoot nämä ensin hurskaasti hoitamaan omaa perhekuntaansa ja maksamaan, mitä ovat velkaa vanhemmilleen, sillä se on otollista Jumalan edessä.'),
(1698698,58,54,5,5,'Oikea leski ja yksinäiseksi jäänyt panee toivonsa Jumalaan ja anoo ja rukoilee alinomaa, yötä päivää;'),
(1698699,58,54,5,6,'mutta hekumoitseva on jo eläessään kuollut.'),
(1698700,58,54,5,7,'Teroita tätäkin, että he olisivat nuhteettomat.'),
(1698701,58,54,5,8,'Mutta jos joku ei pidä huolta omaisistaan ja varsinkaan ei perhekuntalaisistaan, niin hän on kieltänyt uskon ja on uskotonta pahempi.'),
(1698702,58,54,5,9,'Luetteloon otettakoon ainoastaan semmoinen leski, joka ei ole kuuttakymmentä vuotta nuorempi ja joka on ollut yhden miehen vaimo,'),
(1698703,58,54,5,10,'josta on todistettu, että hän on tehnyt hyviä töitä, on lapsia kasvattanut, vieraita holhonnut, pyhien jalkoja pessyt, ahdistettuja auttanut ja kaiken hyvän tekemistä harrastanut.'),
(1698704,58,54,5,11,'Mutta nuoret lesket hylkää; sillä kun he himokkaiksi käyden vieraantuvat Kristuksesta, tahtovat he mennä naimisiin,'),
(1698705,58,54,5,12,'ja ovat tuomion alaisia, koska ovat ensimmäisen uskonsa hyljänneet.'),
(1698706,58,54,5,13,'He oppivat kylää kierrellessään vielä laiskoiksikin, eikä ainoastaan laiskoiksi, vaan myös juoruisiksi ja monitouhuisiksi ja sopimattomia puhumaan.'),
(1698707,58,54,5,14,'Minä tahdon sentähden, että nuoret lesket menevät naimisiin, synnyttävät lapsia, hoitavat kotiansa eivätkä anna vastustajalle mitään aihetta solvaamiseen.'),
(1698708,58,54,5,15,'Sillä muutamat ovat jo kääntyneet pois seuraamaan saatanaa.'),
(1698709,58,54,5,16,'Jos jollakin uskovaisella naisella on leskiä, niin pitäköön niistä huolen, älköönkä seurakuntaa rasitettako, että se voisi pitää huolta oikeista leskistä.'),
(1698710,58,54,5,17,'Vanhimpia, jotka seurakuntaa hyvin hoitavat, pidettäköön kahdenkertaisen kunnian ansainneina, varsinkin niitä, jotka sanassa ja opetuksessa työtä tekevät.'),
(1698711,58,54,5,18,'Sillä Raamattu sanoo: "Älä sido puivan härän suuta", ja: "Työmies on palkkansa ansainnut".'),
(1698712,58,54,5,19,'Älä ota huomioosi syytettä vanhinta vastaan, ellei ole kahta tai kolmea todistajaa.'),
(1698713,58,54,5,20,'Syntiä tekeviä nuhtele kaikkien kuullen, että muutkin pelkäisivät.'),
(1698714,58,54,5,21,'Minä vannotan sinua Jumalan ja Kristuksen Jeesuksen ja valittujen enkelien edessä, että noudatat tätä, tekemättä ennakolta päätöstä ja ketään suosimatta.'),
(1698715,58,54,5,22,'Älä ole liian kerkeä panemaan käsiäsi kenenkään päälle, äläkä antaudu osalliseksi muiden synteihin. Pidä itsesi puhtaana.'),
(1698716,58,54,5,23,'Älä enää juo vain vettä, vaan käytä vähän viiniä vatsasi tähden ja usein uudistuvien vaivojesi vuoksi.'),
(1698717,58,54,5,24,'Muutamien ihmisten synnit ovat ilmeiset ja joutuvat ennen tuomittaviksi, toisten taas seuraavat jäljestäpäin;'),
(1698718,58,54,5,25,'samoin myös hyvät teot ovat ilmeiset, eivätkä nekään, jotka eivät ole ilmeisiä, voi salassa pysyä.'),
(1698719,58,54,6,1,'Kaikki, jotka ovat orjina ikeen alla, pitäkööt isäntiänsä kaikkea kunnioitusta ansaitsevina, ettei Jumalan nimi ja oppi tulisi häväistyksi.'),
(1698720,58,54,6,2,'Mutta ne, joilla on uskovaiset isännät, älkööt pitäkö heitä vähemmässä arvossa sentähden, että he ovat veljiä, vaan palvelkoot heitä sitä mieluummin, koska he ovat uskovia ja rakastettuja ja harrastavat hyväntekemistä. Tätä opeta ja tähän kehoita.'),
(1698721,58,54,6,3,'Jos joku muuta oppia opettaa eikä pitäydy meidän Herramme Jeesuksen Kristuksen terveisiin sanoihin eikä siihen oppiin, joka on jumalisuuden mukainen,'),
(1698722,58,54,6,4,'niin hän on paisunut eikä ymmärrä mitään, vaan on riitakysymyksien ja sanakiistojen kipeä, joista syntyy kateutta, riitaa, herjauksia, pahoja epäluuloja,'),
(1698723,58,54,6,5,'alituisia kinastuksia niiden ihmisten kesken, jotka ovat turmeltuneet mieleltään ja totuuden menettäneet ja jotka pitävät jumalisuutta keinona voiton saamiseen.'),
(1698724,58,54,6,6,'Ja suuri voitto onkin jumalisuus yhdessä tyytyväisyyden kanssa.'),
(1698725,58,54,6,7,'Sillä me emme ole maailmaan mitään tuoneet, emme myös voi täältä mitään viedä;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698726,58,54,6,8,'mutta kun meillä on elatus ja vaatteet, niin tyytykäämme niihin.'),
(1698727,58,54,6,9,'Mutta ne, jotka rikastua tahtovat, lankeavat kiusaukseen ja paulaan ja moniin mielettömiin ja vahingollisiin himoihin, jotka upottavat ihmiset turmioon ja kadotukseen.'),
(1698728,58,54,6,10,'Sillä rahan himo on kaiken pahan juuri; sitä haluten monet ovat eksyneet pois uskosta ja lävistäneet itsensä monella tuskalla.'),
(1698729,58,54,6,11,'Mutta sinä, Jumalan ihminen, pakene semmoista, ja tavoita vanhurskautta, jumalisuutta, uskoa, rakkautta, kärsivällisyyttä, hiljaisuutta.'),
(1698730,58,54,6,12,'Kilvoittele hyvä uskon kilvoitus, tartu kiinni iankaikkiseen elämään, johon olet kutsuttu ja johon hyvällä tunnustuksella olet tunnustautunut monen todistajan edessä.'),
(1698731,58,54,6,13,'Jumalan edessä, joka kaikki eläväksi tekee, ja Kristuksen Jeesuksen edessä, joka Pontius Pilatuksen edessä todisti, tunnustaen hyvän tunnustuksen, minä kehoitan sinua,'),
(1698732,58,54,6,14,'että tahrattomasti ja moitteettomasti pidät käskyn meidän Herramme Jeesuksen Kristuksen ilmestymiseen saakka,'),
(1698733,58,54,6,15,'jonka aikanansa on antava meidän nähdä se autuas ja ainoa valtias, kuningasten Kuningas ja herrain Herra,'),
(1698734,58,54,6,16,'jolla ainoalla on kuolemattomuus; joka asuu valkeudessa, mihin ei kukaan taida tulla; jota yksikään ihminen ei ole nähnyt eikä voi nähdä - hänen olkoon kunnia ja iankaikkinen valta. Amen.'),
(1698735,58,54,6,17,'Kehoita niitä, jotka nykyisessä maailmanajassa ovat rikkaita, etteivät ylpeilisi eivätkä panisi toivoansa epävarmaan rikkauteen, vaan Jumalaan, joka runsaasti antaa meille kaikkea nautittavaksemme,'),
(1698736,58,54,6,18,'kehoita heitä, että tekevät hyvää, hyvissä töissä rikastuvat, ovat anteliaita ja omastansa jakelevat,'),
(1698737,58,54,6,19,'kooten itsellensä aarteen, hyvän perustuksen tulevaisuuden varalle, että saisivat todellisen elämän.'),
(1698738,58,54,6,20,'Oi Timoteus, talleta se, mikä sinulle on uskottu, ja vältä tiedon nimellä kulkevan valhetiedon epäpyhiä ja tyhjiä puheita ja vastaväitteitä,'),
(1698739,58,54,6,21,'johon tunnustautuen muutamat ovat uskosta hairahtuneet. Armo olkoon teidän kanssanne!'),
(1698740,58,55,1,1,'Paavali, Jumalan tahdosta Kristuksen Jeesuksen apostoli, lähetetty julistamaan lupausta siitä elämästä, joka on Kristuksessa Jeesuksessa,'),
(1698741,58,55,1,2,'rakkaalle pojalleni Timoteukselle. Armo, laupeus ja rauha Isältä Jumalalta ja Kristukselta Jeesukselta, meidän Herraltamme!'),
(1698742,58,55,1,3,'Minä kiitän Jumalaa, jota esivanhemmistani asti palvelen puhtaalla omallatunnolla - samoinkuin minä lakkaamatta muistan sinua rukouksissani öin ja päivin,'),
(1698743,58,55,1,4,'haluten, muistaessani kyyneleitäsi, saada sinua nähdä, että täyttyisin ilolla -'),
(1698744,58,55,1,5,'kun mieleeni muistuu se vilpitön usko, joka sinulla on, joka ensin oli isoäidilläsi Looiksella ja äidilläsi Eunikellä ja joka, siitä olen varma, on sinullakin.'),
(1698745,58,55,1,6,'Siitä syystä minä sinua muistutan virittämään palavaksi Jumalan armolahjan, joka sinussa on minun kätteni päällepanemisen kautta.'),
(1698746,58,55,1,7,'Sillä Jumala ei ole antanut meille pelkuruuden henkeä, vaan voiman ja rakkauden ja raittiuden hengen.'),
(1698747,58,55,1,8,'Älä siis häpeä todistusta Herrastamme äläkä minua, hänen vankiaan, vaan kärsi yhdessä minun kanssani vaivaa evankeliumin tähden, sen mukaan kuin Jumala antaa voimaa,'),
(1698748,58,55,1,9,'hän, joka on meidät pelastanut ja kutsunut pyhällä kutsumuksella, ei meidän tekojemme mukaan, vaan oman aivoituksensa ja armonsa mukaan, joka meille on annettu Kristuksessa Jeesuksessa ennen ikuisia aikoja,'),
(1698749,58,55,1,10,'mutta nyt ilmisaatettu meidän Vapahtajamme Kristuksen Jeesuksen ilmestymisen kautta, joka kukisti kuoleman ja toi valoon elämän ja katoamattomuuden evankeliumin kautta,'),
(1698750,58,55,1,11,'jonka julistajaksi ja apostoliksi ja opettajaksi minä olen asetettu.'),
(1698751,58,55,1,12,'Siitä syystä minä myös näitä kärsin, enkä sitä häpeä; sillä minä tunnen hänet, johon minä uskon, ja olen varma siitä, että hän on voimallinen siihen päivään asti säilyttämään sen, mikä minulle on uskottu.'),
(1698752,58,55,1,13,'Ota esikuvaksi ne terveelliset sanat, jotka olet minulta kuullut, uskossa ja rakkaudessa, joka on Kristuksessa Jeesuksessa.'),
(1698753,58,55,1,14,'Säilytä se hyvä, mikä sinulle on uskottu, Pyhän Hengen kautta, joka meissä asuu.'),
(1698754,58,55,1,15,'Sinä tiedät, että kaikki aasialaiset ovat kääntyneet minusta pois; niiden joukossa ovat Fygelus ja Hermogenes.'),
(1698755,58,55,1,16,'Antakoon Herra laupeutta Onesiforuksen huonekunnalle, sillä usein hän on minua virvoittanut, eikä ole kahleitani hävennyt;'),
(1698756,58,55,1,17,'vaan kun hän tuli Roomaan, etsi hän minua innokkaasti ja löysi minut.'),
(1698757,58,55,1,18,'Suokoon Herra, että hän löytää laupeuden Herran tykönä sinä päivänä. Ja kuinka suuria ne palvelukset olivat, joita hän teki Efesossa, sen sinä parhaiten tiedät.'),
(1698758,58,55,2,1,'Vahvistu siis, poikani, siinä armossa, joka on Kristuksessa Jeesuksessa.'),
(1698759,58,55,2,2,'Ja minkä olet kuullut minulta ja minkä monet ovat todistaneet, usko se luotettaville miehille, jotka sitten ovat soveliaita muitakin opettamaan.'),
(1698760,58,55,2,3,'Kärsi vaivaa niinkuin ainakin jalo Kristuksen Jeesuksen sotamies.'),
(1698761,58,55,2,4,'Ei kukaan, joka sodassa palvelee, sekaannu elatuksen toimiin, sillä hän tahtoo olla mieliksi sille, joka on hänet palkannut.'),
(1698762,58,55,2,5,'Eihän sitäkään, joka kilpailee, seppelöidä, ellei hän kilpaile sääntöjen mukaisesti.'),
(1698763,58,55,2,6,'Peltomiehen, joka vaivaa näkee, tulee ennen muita päästä osalliseksi hedelmistä.'),
(1698764,58,55,2,7,'Tarkkaa, mitä sanon; Herra on antava sinulle ymmärrystä kaikkeen.'),
(1698765,58,55,2,8,'Muista Jeesusta Kristusta, joka on kuolleista herätetty ja on Daavidin siementä minun evankeliumini mukaan,'),
(1698766,58,55,2,9,'jonka julistamisessa minä kärsin vaivaa, kahleisiin asti, niinkuin pahantekijä; mutta Jumalan sana ei ole kahlehdittu.'),
(1698767,58,55,2,10,'Siitä syystä minä kärsin kaikki valittujen tähden, että hekin saavuttaisivat pelastuksen, joka on Kristuksessa Jeesuksessa, ynnä iankaikkisen kirkkauden.'),
(1698768,58,55,2,11,'Varma on tämä sana; sillä: jos olemme kuolleet yhdessä hänen kanssaan, saamme myös hänen kanssaan elää;'),
(1698769,58,55,2,12,'jos kärsimme yhdessä, saamme hänen kanssaan myös hallita; jos kiellämme hänet, on hänkin kieltävä meidät;'),
(1698770,58,55,2,13,'jos me olemme uskottomat, pysyy kuitenkin hän uskollisena; sillä itseänsä kieltää hän ei saata.'),
(1698771,58,55,2,14,'Muistuta tästä, ja teroita heille Jumalan edessä, etteivät kiistelisi sanoista, mikä ei ole miksikään hyödyksi, vaan niiden turmioksi, jotka kuulevat.'),
(1698772,58,55,2,15,'Pyri osoittautumaan Jumalalle semmoiseksi, joka koetukset kestää, työntekijäksi, joka ei työtään häpeä, joka oikein jakelee totuuden sanaa.'),
(1698773,58,55,2,16,'Mutta pysy erilläsi epäpyhistä ja tyhjistä puheista, sillä niiden puhujat menevät yhä pitemmälle jumalattomuudessa,'),
(1698774,58,55,2,17,'ja heidän puheensa jäytää ympäristöään niinkuin syöpä. Niitä ovat Hymeneus ja Filetus,'),
(1698775,58,55,2,18,'jotka ovat totuudesta eksyneet, kun sanovat, että ylösnousemus jo on tapahtunut, ja he turmelevat useiden uskon.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698776,58,55,2,19,'Kuitenkin Jumalan vahva perustus pysyy lujana, ja siinä on tämä sinetti: "Herra tuntee omansa", ja: "Luopukoon vääryydestä jokainen, joka Herran nimeä mainitsee".'),
(1698777,58,55,2,20,'Mutta suuressa talossa ei ole ainoastaan kulta- ja hopea-astioita, vaan myös puu- ja saviastioita, ja toiset ovat jaloa, toiset halpaa käyttöä varten.'),
(1698778,58,55,2,21,'Jos nyt joku puhdistaa itsensä tämänkaltaisista, tulee hänestä astia jaloa käyttöä varten, pyhitetty, isännälleen hyödyllinen, kaikkiin hyviin tekoihin valmis.'),
(1698779,58,55,2,22,'Pakene nuoruuden himoja, harrasta vanhurskautta, uskoa, rakkautta, rauhaa niiden kanssa, jotka huutavat avuksensa Herraa puhtaasta sydämestä.'),
(1698780,58,55,2,23,'Mutta vältä tyhmiä ja taitamattomia väittelyjä, sillä tiedäthän, että ne synnyttävät riitoja.'),
(1698781,58,55,2,24,'Mutta Herran palvelijan ei sovi riidellä, vaan hänen tulee olla lempeä kaikkia kohtaan, kyetä opettamaan ja pahaa kärsimään;'),
(1698782,58,55,2,25,'hänen tulee sävyisästi ojentaa vastustelijoita; ehkäpä Jumala antaa heille mielenmuutoksen, niin että tulevat tuntemaan totuuden'),
(1698783,58,55,2,26,'ja selviävät perkeleen pauloista, joka on heidät vanginnut tahtoansa tekemään.'),
(1698784,58,55,3,1,'Mutta tiedä se, että viimeisinä päivinä on tuleva vaikeita aikoja.'),
(1698785,58,55,3,2,'Sillä ihmiset ovat silloin itserakkaita, rahanahneita, kerskailijoita, ylpeitä, herjaajia, vanhemmilleen tottelemattomia, kiittämättömiä, epähurskaita,'),
(1698786,58,55,3,3,'rakkaudettomia, epäsopuisia, panettelijoita, hillittömiä, raakoja, hyvän vihamiehiä,'),
(1698787,58,55,3,4,'pettureita, väkivaltaisia, pöyhkeitä, hekumaa enemmän kuin Jumalaa rakastavia;'),
(1698788,58,55,3,5,'heissä on jumalisuuden ulkokuori, mutta he kieltävät sen voiman. Senkaltaisia karta.'),
(1698789,58,55,3,6,'Sillä niitä ovat ne, jotka tungettelevat taloihin ja pauloihinsa kietovat syntien rasittamia ja monenlaisten himojen heiteltäviä naisparkoja,'),
(1698790,58,55,3,7,'jotka aina ovat opetusta ottamassa, eivätkä koskaan voi päästä totuuden tuntemiseen.'),
(1698791,58,55,3,8,'Ja niinkuin Jannes ja Jambres vastustivat Moosesta, niin nuokin vastustavat totuutta, nuo mieleltään turmeltuneet ihmiset, jotka eivät uskonkoetuksissa kestä.'),
(1698792,58,55,3,9,'Mutta he eivät pitemmälle edisty, sillä heidän mielettömyytensä on käyvä ilmeiseksi kaikille, niinkuin noidenkin mielettömyys kävi ilmi.'),
(1698793,58,55,3,10,'Mutta sinä olet seurannut minun opetustani, vaellustani, aivoitustani, uskoani, pitkämielisyyttäni, rakkauttani, kärsivällisyyttäni,'),
(1698794,58,55,3,11,'vainoissa ja kärsimyksissä, samanlaisissa kuin minun osakseni tuli Antiokiassa, Ikonionissa ja Lystrassa. Mimmoisia vainoja olenkaan kärsinyt, ja kaikista Herra on minut pelastanut!'),
(1698795,58,55,3,12,'Ja kaikki, jotka tahtovat elää jumalisesti Kristuksessa Jeesuksessa, joutuvat vainottaviksi.'),
(1698796,58,55,3,13,'Mutta pahat ihmiset ja petturit menevät yhä pitemmälle pahuudessa, eksyttäen ja eksyen.'),
(1698797,58,55,3,14,'Mutta pysy sinä siinä, minkä olet oppinut ja mistä olet varma, koska tiedät, keiltä olet sen oppinut,'),
(1698798,58,55,3,15,'ja koska jo lapsuudestasi saakka tunnet pyhät kirjoitukset, jotka voivat tehdä sinut viisaaksi, niin että pelastut uskon kautta, joka on Kristuksessa Jeesuksessa.'),
(1698799,58,55,3,16,'Jokainen kirjoitus, joka on syntynyt Jumalan Hengen vaikutuksesta, on myös hyödyllinen opetukseksi, nuhteeksi, ojennukseksi, kasvatukseksi vanhurskaudessa,'),
(1698800,58,55,3,17,'että Jumalan ihminen olisi täydellinen, kaikkiin hyviin tekoihin valmistunut.'),
(1698801,58,55,4,1,'Minä vannotan sinua Jumalan ja Kristuksen Jeesuksen edessä, joka on tuomitseva eläviä ja kuolleita, sekä hänen ilmestymisensä että hänen valtakuntansa kautta:'),
(1698802,58,55,4,2,'saarnaa sanaa, astu esiin sopivalla ja sopimattomalla ajalla, nuhtele, varoita, kehoita, kaikella pitkämielisyydellä ja opetuksella.'),
(1698803,58,55,4,3,'Sillä aika tulee, jolloin he eivät kärsi tervettä oppia, vaan omien himojensa mukaan korvasyyhyynsä haalivat itselleen opettajia'),
(1698804,58,55,4,4,'ja kääntävät korvansa pois totuudesta ja kääntyvät taruihin.'),
(1698805,58,55,4,5,'Mutta ole sinä raitis kaikessa, kärsi vaivaa, tee evankelistan työ, toimita virkasi täydellisesti.'),
(1698806,58,55,4,6,'Sillä minut jo uhrataan, ja minun lähtöni aika on jo tullut.'),
(1698807,58,55,4,7,'Minä olen hyvän kilvoituksen kilvoitellut, juoksun päättänyt, uskon säilyttänyt.'),
(1698808,58,55,4,8,'Tästedes on minulle talletettuna vanhurskauden seppele, jonka Herra, vanhurskas tuomari, on antava minulle sinä päivänä, eikä ainoastaan minulle, vaan myös kaikille, jotka hänen ilmestymistään rakastavat.'),
(1698809,58,55,4,9,'Koeta päästä pian tulemaan luokseni.'),
(1698810,58,55,4,10,'Sillä tähän nykyiseen maailmaan rakastuneena jätti minut Deemas ja matkusti Tessalonikaan, Kreskes meni Galatiaan ja Tiitus Dalmatiaan.'),
(1698811,58,55,4,11,'Luukas yksin on minun kanssani. Ota Markus mukaasi ja tuo hänet tänne, sillä hän on minulle hyvin tarpeellinen palvelukseen.'),
(1698812,58,55,4,12,'Mutta Tykikuksen minä olen lähettänyt Efesoon.'),
(1698813,58,55,4,13,'Tuo tullessasi päällysvaippa, jonka jätin Trooaaseen Karpuksen luo, ja kirjat, ennen kaikkea pergamentit.'),
(1698814,58,55,4,14,'Aleksander, vaskiseppä, on tehnyt minulle paljon pahaa; Herra on maksava hänelle hänen tekojensa mukaan.'),
(1698815,58,55,4,15,'Kavahda sinäkin häntä, sillä hän on kovin vastustanut meidän sanojamme.'),
(1698816,58,55,4,16,'Ensi kertaa puolustautuessani ei kukaan tullut avukseni, vaan kaikki jättivät minut; älköön sitä heille syyksi luettako.'),
(1698817,58,55,4,17,'Mutta Herra auttoi minua ja vahvisti minua, että sanan julistaminen minun kauttani tulisi täydelleen suoritetuksi, ja kaikki pakanat sen kuulisivat; ja minä pelastuin jalopeuran kidasta.'),
(1698818,58,55,4,18,'Ja Herra on vapahtava minut kaikesta ilkivallasta ja pelastava minut taivaalliseen valtakuntaansa; hänelle kunnia aina ja iankaikkisesti! Amen.'),
(1698819,58,55,4,19,'Tervehdys Priskalle ja Akylaalle ja Onesiforuksen huonekunnalle.'),
(1698820,58,55,4,20,'Erastus jäi Korinttoon, mutta Trofimuksen minä jätin Miletoon sairastamaan.'),
(1698821,58,55,4,21,'Koeta päästä tulemaan ennen talvea. Tervehdyksen lähettävät sinulle Eubulus ja Pudes ja Linus ja Klaudia ja kaikki veljet.'),
(1698822,58,55,4,22,'Herra olkoon sinun henkesi kanssa. Armo olkoon teidän kanssanne.'),
(1698823,58,56,1,1,'Paavali, Jumalan palvelija ja Jeesuksen Kristuksen apostoli Jumalan valittujen uskoa ja sen totuuden tuntemista varten, joka on jumalisuuden mukainen,'),
(1698824,58,56,1,2,'apostoli sen iankaikkisen elämän toivon perusteella, jonka Jumala, joka ei valhettele, on luvannut ennen ikuisia aikoja -'),
(1698825,58,56,1,3,'mutta kun aika oli tullut, ilmoitti hän sanansa saarnassa, joka on uskottu minulle Jumalan, meidän vapahtajamme, käskyn mukaan:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698826,58,56,1,4,'Tiitukselle, oikealle pojalleni yhteisen uskomme perusteella. Armo ja rauha Isältä Jumalalta ja meidän Vapahtajaltamme Kristukselta Jeesukselta!'),
(1698827,58,56,1,5,'Minä jätin sinut Kreettaan sitä varten, että järjestäisit, mitä vielä jäi järjestämättä, ja että asettaisit, niinkuin minä sinulle määräsin, joka kaupunkiin vanhimmat,'),
(1698828,58,56,1,6,'jos missä olisi joku nuhteeton, yhden vaimon mies, jonka lapset ovat uskovia, eivät irstaudesta syytettyjä eivätkä niskoittelevia.'),
(1698829,58,56,1,7,'Sillä seurakunnan kaitsijan on, niinkuin Jumalan huoneenhaltijan tulee, oltava nuhteeton, ei itserakas, ei pikavihainen, ei juomari, ei tappelija, ei häpeällisen voiton pyytäjä,'),
(1698830,58,56,1,8,'vaan vieraanvarainen, hyvää rakastava, maltillinen, oikeamielinen, pyhä, itsensähillitseväinen;'),
(1698831,58,56,1,9,'hänen tulee pysyä kiinni opinmukaisessa, luotettavassa sanassa, että olisi kykenevä sekä neuvomaan terveellä opilla että kumoamaan vastaansanojain väitteet.'),
(1698832,58,56,1,10,'Sillä paljon on niskoittelevia, turhanpuhujia ja eksyttäjiä, varsinkin ympärileikattujen joukossa;'),
(1698833,58,56,1,11,'semmoisilta on suu tukittava, sillä he kääntävät ylösalaisin kokonaisia huonekuntia opettamalla sopimattomia häpeällisen voiton vuoksi.'),
(1698834,58,56,1,12,'Eräs heistä, heidän oma profeettansa, on sanonut: "Petturi Kreetan mies, peto ilkeä, laiskurivatsa".'),
(1698835,58,56,1,13,'Tämä todistus on tosi; sentähden nuhtele heitä ankarasti, että tulisivat uskossa terveiksi'),
(1698836,58,56,1,14,'eivätkä kiinnittäisi huomiotansa juutalaisiin taruihin eikä totuudesta pois kääntyvien ihmisten käskyihin.'),
(1698837,58,56,1,15,'Kaikki on puhdasta puhtaille; mutta saastaisille ja uskottomille ei mikään ole puhdasta, vaan heidän sekä mielensä että omatuntonsa on saastainen.'),
(1698838,58,56,1,16,'He väittävät tuntevansa Jumalan, mutta teoillaan he hänet kieltävät, sillä he ovat inhottavia ja tottelemattomia ja kaikkiin hyviin tekoihin kelvottomia.'),
(1698839,58,56,2,1,'Mutta sinä puhu sitä, mikä terveeseen oppiin soveltuu:'),
(1698840,58,56,2,2,'vanhat miehet olkoot raittiit, arvokkaat, siveät ja uskossa, rakkaudessa ja kärsivällisyydessä terveet;'),
(1698841,58,56,2,3,'niin myös vanhat naiset olkoot käytöksessään niinkuin pyhien sopii, ei panettelijoita, ei paljon viinin orjia, vaan hyvään neuvojia,'),
(1698842,58,56,2,4,'voidakseen ohjata nuoria vaimoja rakastamaan miehiänsä ja lapsiansa,'),
(1698843,58,56,2,5,'olemaan siveitä, puhtaita, kotinsa hoitajia, hyviä, miehilleen alamaisia, ettei Jumalan sana pilkatuksi tulisi.'),
(1698844,58,56,2,6,'Nuorempia miehiä samoin kehoita käyttäytymään siveästi.'),
(1698845,58,56,2,7,'Aseta itsesi kaikessa hyvien tekojen esikuvaksi, olkoon opetuksesi puhdasta ja arvokasta'),
(1698846,58,56,2,8,'ja puheesi tervettä ja moitteetonta, että vastustaja häpeäisi, kun hänellä ei ole meistä mitään pahaa sanottavana.'),
(1698847,58,56,2,9,'Kehoita palvelijoita olemaan isännilleen kaikessa alamaisia, heille mieliksi, etteivät vastustele,'),
(1698848,58,56,2,10,'etteivät näpistele, vaan kaikin tavoin osoittavat vilpitöntä uskollisuutta, että he Jumalan, meidän vapahtajamme, opin kaikessa kaunistaisivat.'),
(1698849,58,56,2,11,'Sillä Jumalan armo on ilmestynyt pelastukseksi kaikille ihmisille'),
(1698850,58,56,2,12,'ja kasvattaa meitä, että me, hyljäten jumalattomuuden ja maailmalliset himot, eläisimme siveästi ja vanhurskaasti ja jumalisesti nykyisessä maailmanajassa,'),
(1698851,58,56,2,13,'odottaessamme autuaallisen toivon täyttymistä ja suuren Jumalan ja Vapahtajamme Kristuksen Jeesuksen kirkkauden ilmestymistä,'),
(1698852,58,56,2,14,'hänen, joka antoi itsensä meidän edestämme lunastaakseen meidät kaikesta laittomuudesta ja puhdistaakseen itselleen omaisuudeksi kansan, joka hyviä tekoja ahkeroitsee.'),
(1698853,58,56,2,15,'Puhu tätä ja kehoita ja nuhtele kaikella käskyvallalla. Älköön kukaan sinua halveksiko.'),
(1698854,58,56,3,1,'Muistuta heitä olemaan hallituksille ja esivalloille alamaiset, kuuliaiset, kaikkiin hyviin tekoihin valmiit,'),
(1698855,58,56,3,2,'etteivät ketään herjaa, eivät riitele, vaan ovat lempeitä ja osoittavat kaikkea sävyisyyttä kaikkia ihmisiä kohtaan.'),
(1698856,58,56,3,3,'Olimmehan mekin ennen ymmärtämättömiä, tottelemattomia, eksyksissä, moninaisten himojen ja hekumain orjia, elimme pahuudessa ja kateudessa, olimme inhottavia ja vihasimme toisiamme.'),
(1698857,58,56,3,4,'Mutta kun Jumalan, meidän vapahtajamme, hyvyys ja ihmisrakkaus ilmestyi,'),
(1698858,58,56,3,5,'pelasti hän meidät, ei vanhurskaudessa tekemiemme tekojen ansiosta, vaan laupeutensa mukaan uudestisyntymisen peson ja Pyhän Hengen uudistuksen kautta,'),
(1698859,58,56,3,6,'jonka Hengen hän runsaasti vuodatti meihin meidän Vapahtajamme Jeesuksen Kristuksen kautta,'),
(1698860,58,56,3,7,'että me vanhurskautettuina hänen armonsa kautta tulisimme iankaikkisen elämän perillisiksi toivon mukaan.'),
(1698861,58,56,3,8,'Tämä sana on varma, ja minä tahdon, että sinä näitä teroitat, niin että ne, jotka Jumalaan uskovat, ahkeroisivat hyvien tekojen harjoittamista. Nämä ovat hyviä ja hyödyllisiä ihmisille.'),
(1698862,58,56,3,9,'Mutta vältä mielettömiä riitakysymyksiä ja sukuluetteloita ja kinastelua ja kiistoja laista, sillä ne ovat hyödyttömiä ja turhia.'),
(1698863,58,56,3,10,'Harhaoppista ihmistä karta, varoitettuasi häntä kerran tai kahdesti,'),
(1698864,58,56,3,11,'sillä sinä tiedät, että semmoinen ihminen on joutunut harhaan ja tekee syntiä, ja hän on itse itsensä tuominnut.'),
(1698865,58,56,3,12,'Kun lähetän luoksesi Artemaan tai Tykikuksen, niin tule viipymättä minun tyköni Nikopoliin, sillä siellä olen päättänyt viettää talven.'),
(1698866,58,56,3,13,'Varusta huolellisesti matkalle Zeenas, lainoppinut, ja Apollos, ettei heiltä mitään puuttuisi.'),
(1698867,58,56,3,14,'Oppikoot meikäläisetkin, tarpeen vaatiessa, harjoittamaan hyviä tekoja, etteivät jäisi hedelmättömiksi.'),
(1698868,58,56,3,15,'Tervehdyksen lähettävät sinulle kaikki, jotka ovat minun kanssani. Sano tervehdys niille, jotka pitävät meitä rakkaina uskossa. Armo olkoon kaikkien teidän kanssanne.'),
(1698869,58,57,1,1,'Paavali, Kristuksen Jeesuksen vanki, ja veli Timoteus rakkaalle Filemonille, työtoverillemme,'),
(1698870,58,57,1,2,'ja Appialle, sisarellemme, ja Arkippukselle, taistelutoverillemme, ja sinun kodissasi kokoontuvalle seurakunnalle.'),
(1698871,58,57,1,3,'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!'),
(1698872,58,57,1,4,'Minä kiitän Jumalaani aina, muistaessani sinua rukouksissani,'),
(1698873,58,57,1,5,'sillä minä olen kuullut sinun rakkaudestasi ja uskostasi, joka sinulla on Herraan Jeesukseen ja kaikkia pyhiä kohtaan;'),
(1698874,58,57,1,6,'ja rukoukseni on, että sinun uskosi, se usko, joka on meille yhteinen, olisi väkevä kaiken hyvän tuntemisessa, mikä meillä Kristuksessa on.'),
(1698875,58,57,1,7,'Sillä minä olen saanut paljon iloa ja lohdutusta sinun rakkaudestasi, koska pyhien sydämet ovat virvoittuneet sinun kauttasi, veljeni.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698876,58,57,1,8,'Sentähden, vaikka minulla Kristuksessa on paljon rohkeutta käskeä sinua tekemään, mitä tehdä tulee,'),
(1698877,58,57,1,9,'niin rakkauden tähden minä kuitenkin mieluummin pyydän, ollen tämmöinen kuin olen, minä vanha Paavali, ja nyt myös Kristuksen Jeesuksen vanki -'),
(1698878,58,57,1,10,'pyydän sinua poikani puolesta, jonka minä kahleissani synnytin, Onesimuksen puolesta,'),
(1698879,58,57,1,11,'sinulle ennen hyödyttömän, mutta nyt sekä sinulle että minulle hyödyllisen;'),
(1698880,58,57,1,12,'hänet minä lähetän sinulle takaisin, hänet, se on: oman sydämeni.'),
(1698881,58,57,1,13,'Olisin tahtonut pidättää hänet tykönäni, että hän sinun sijassasi olisi palvellut minua, joka olen evankeliumin tähden kahleissa;'),
(1698882,58,57,1,14,'mutta ilman sinun suostumustasi en tahtonut tehdä mitään, ettei hyvyytesi olisi ikäänkuin pakollinen, vaan vapaaehtoinen.'),
(1698883,58,57,1,15,'Sillä ehkäpä hän sentähden joutui eroamaan sinusta ajaksi, että saisit hänet takaisin iäksi,'),
(1698884,58,57,1,16,'ei enää orjana, vaan orjaa enempänä: rakkaana veljenä, ylen rakkaana jo minulle, kuinka paljoa enemmän sitten sinulle, sekä ihmisenä että Herran omana!'),
(1698885,58,57,1,17,'Jos siis pidät minua toverinasi, niin ota hänet luoksesi niinkuin minut;'),
(1698886,58,57,1,18,'mutta jos hän on tehnyt sinulle jotakin vääryyttä tai on sinulle jotakin velkaa, niin pane se minun laskuuni.'),
(1698887,58,57,1,19,'Minä, Paavali, kirjoitan omalla kädelläni: "Minä sen maksan"; saattaisinpa sanoa: pane se omaan laskuusi; sillä sinä olet minulle velkaa oman itsesikin.'),
(1698888,58,57,1,20,'Niin, veljeni, jospa saisin sinusta hyötyä Herrassa; virvoita sydäntäni Kristuksessa.'),
(1698889,58,57,1,21,'Luottaen kuuliaisuuteesi minä kirjoitan sinulle, ja minä tiedän, että sinä teet enemmänkin, kuin mitä sanon.'),
(1698890,58,57,1,22,'Lisäksi vielä: valmista minulle maja luonasi; toivon näet, että minut rukoustenne kautta lahjoitetaan teille.'),
(1698891,58,57,1,23,'Tervehdyksen lähettävät sinulle Epafras, minun vankitoverini Kristuksessa Jeesuksessa,'),
(1698892,58,57,1,24,'Markus, Aristarkus, Deemas ja Luukas, jotka ovat minun työtovereitani.'),
(1698893,58,57,1,25,'Herran Jeesuksen Kristuksen armo olkoon teidän henkenne kanssa.'),
(1698894,58,58,1,1,'Sittenkuin Jumala muinoin monesti ja monella tapaa oli puhunut isille profeettain kautta,'),
(1698895,58,58,1,2,'on hän näinä viimeisinä päivinä puhunut meille Pojan kautta, jonka hän on pannut kaiken perilliseksi, jonka kautta hän myös on maailman luonut'),
(1698896,58,58,1,3,'ja joka, ollen hänen kirkkautensa säteily ja hänen olemuksensa kuva ja kantaen kaikki voimansa sanalla, on, toimitettuaan puhdistuksen synneistä, istunut Majesteetin oikealle puolelle korkeuksissa,'),
(1698897,58,58,1,4,'tullen enkeleitä niin paljoa korkeammaksi, kuin hänen perimänsä nimi on jalompi kuin heidän.'),
(1698898,58,58,1,5,'Sillä kenelle enkeleistä hän koskaan on sanonut: "Sinä olet minun Poikani, tänä päivänä minä sinut synnytin"; ja taas: "Minä olen oleva hänen Isänsä, ja hän on oleva minun Poikani"?'),
(1698899,58,58,1,6,'Ja siitä, kun hän jälleen tuo esikoisensa maailmaan, hän sanoo: "Ja kumartakoot häntä kaikki Jumalan enkelit".'),
(1698900,58,58,1,7,'Ja enkeleistä hän sanoo: "Hän tekee enkelinsä tuuliksi ja palvelijansa tulen liekiksi";'),
(1698901,58,58,1,8,'mutta Pojasta: "Jumala, sinun valtaistuimesi pysyy aina ja iankaikkisesti, ja sinun valtakuntasi valtikka on oikeuden valtikka.'),
(1698902,58,58,1,9,'Sinä rakastit vanhurskautta ja vihasit laittomuutta; sentähden on Jumala, sinun Jumalasi, voidellut sinua iloöljyllä, enemmän kuin sinun osaveljiäsi."'),
(1698903,58,58,1,10,'Ja: "Sinä, Herra, olet alussa maan perustanut, ja taivaat ovat sinun kättesi tekoja;'),
(1698904,58,58,1,11,'ne katoavat, mutta sinä pysyt, ja ne vanhenevat kaikki niinkuin vaate,'),
(1698905,58,58,1,12,'ja niinkuin vaipan sinä ne käärit, niinkuin vaatteen, ja ne muuttuvat; mutta sinä olet sama, eivätkä sinun vuotesi lopu".'),
(1698906,58,58,1,13,'Kenelle enkeleistä hän koskaan on sanonut: "Istu minun oikealle puolelleni, kunnes minä panen sinun vihollisesi sinun jalkojesi astinlaudaksi"?'),
(1698907,58,58,1,14,'Eivätkö he kaikki ole palvelevia henkiä, palvelukseen lähetettyjä niitä varten, jotka saavat autuuden periä?'),
(1698908,58,58,2,1,'Sentähden tulee meidän sitä tarkemmin ottaa vaari siitä, mitä olemme kuulleet, ettemme vain kulkeutuisi sen ohitse.'),
(1698909,58,58,2,2,'Sillä jos enkelien kautta puhuttu sana pysyi lujana, ja jokainen rikkomus ja tottelemattomuus sai oikeudenmukaisen palkkansa,'),
(1698910,58,58,2,3,'kuinka me voimme päästä pakoon, jos emme välitä tuosta niin suuresta pelastuksesta, jonka Herra alkuaan julisti ja joka niiden vahvistamana, jotka olivat sen kuulleet, saatettiin meille,'),
(1698911,58,58,2,4,'kun Jumala yhdessä heidän kanssaan todisti tunnusmerkeillä ja ihmeillä ja moninaisilla väkevillä teoilla ja jakamalla Pyhää Henkeä tahtonsa mukaan?'),
(1698912,58,58,2,5,'Sillä enkelien alle hän ei alistanut tulevaa maailmaa, josta me puhumme.'),
(1698913,58,58,2,6,'Vaan joku on jossakin paikassa todistanut, sanoen: "Mikä on ihminen, että sinä häntä muistat, tai ihmisen poika, että pidät hänestä huolen?'),
(1698914,58,58,2,7,'Sinä teit hänet vähäksi aikaa enkeleitä halvemmaksi, kirkkaudella ja kunnialla sinä hänet seppelöitsit, ja sinä panit hänet hallitsemaan kättesi tekoja;'),
(1698915,58,58,2,8,'asetit kaikki hänen jalkojensa alle." Sillä, asettaessaan kaikki hänen valtansa alle, hän ei jättänyt mitään hänen allensa alistamatta. Mutta nyt emme vielä näe kaikkea hänen valtansa alle asetetuksi.'),
(1698916,58,58,2,9,'Mutta hänet, joka vähäksi aikaa oli tehty enkeleitä halvemmaksi, Jeesuksen, me näemme hänen kuolemansa kärsimyksen tähden kirkkaudella ja kunnialla seppelöidyksi, että hän Jumalan armosta olisi kaikkien edestä joutunut maistamaan kuolemaa.'),
(1698917,58,58,2,10,'Sillä hänen, jonka tähden kaikki on ja jonka kautta kaikki on, sopi, saattaessaan paljon lapsia kirkkauteen, kärsimysten kautta tehdä heidän pelastuksensa päämies täydelliseksi.'),
(1698918,58,58,2,11,'Sillä sekä hän, joka pyhittää, että ne, jotka pyhitetään, ovat kaikki alkuisin yhdestä. Sentähden hän ei häpeä kutsua heitä veljiksi,'),
(1698919,58,58,2,12,'kun hän sanoo: "Minä julistan sinun nimeäsi veljilleni, ylistän sinua seurakunnan keskellä";'),
(1698920,58,58,2,13,'ja taas: "Minä panen uskallukseni häneen"; ja taas: "Katso, minä ja lapset, jotka Jumala on minulle antanut!"'),
(1698921,58,58,2,14,'Koska siis lapsilla on veri ja liha, tuli hänkin niistä yhtäläisellä tavalla osalliseksi, että hän kuoleman kautta kukistaisi sen, jolla oli kuolema vallassaan, se on: perkeleen,'),
(1698922,58,58,2,15,'ja vapauttaisi kaikki ne, jotka kuoleman pelosta kautta koko elämänsä olivat olleet orjuuden alaisia.'),
(1698923,58,58,2,16,'Sillä ei hän ota huomaansa enkeleitä, vaan Aabrahamin siemenen hän ottaa huomaansa.'),
(1698924,58,58,2,17,'Sentähden piti hänen kaikessa tuleman veljiensä kaltaiseksi, että hänestä tulisi laupias ja uskollinen ylimmäinen pappi tehtävissään Jumalan edessä, sovittaakseen kansan synnit.'),
(1698925,58,58,2,18,'Sillä sentähden, että hän itse on kärsinyt ja ollut kiusattu, voi hän kiusattuja auttaa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698926,58,58,3,1,'Sentähden, pyhät veljet, jotka olette taivaallisesta kutsumuksesta osalliset, kiinnittäkää mielenne meidän tunnustuksemme apostoliin ja ylimmäiseen pappiin, Jeesukseen,'),
(1698927,58,58,3,2,'joka on uskollinen asettajalleen, niinkuin Mooseskin oli "uskollinen koko hänen huoneessansa".'),
(1698928,58,58,3,3,'Sillä hänen on Moosekseen verraten katsottu ansaitsevan niin paljoa suuremman kirkkauden, kuin huoneen rakentajan kunnia on suurempi kuin huoneen.'),
(1698929,58,58,3,4,'Sillä jokainen huone on jonkun rakentama, mutta kaiken rakentaja on Jumala.'),
(1698930,58,58,3,5,'Ja Mooses tosin oli "palvelijana uskollinen koko hänen huoneessansa", todistukseksi siitä, mikä vastedes piti sanottaman,'),
(1698931,58,58,3,6,'mutta Kristus on uskollinen Poikana, hänen huoneensa haltijana; ja hänen huoneensa olemme me, jos loppuun asti pidämme vahvana toivon rohkeuden ja kerskauksen.'),
(1698932,58,58,3,7,'Sentähden, niinkuin Pyhä Henki sanoo: "Tänä päivänä, jos te kuulette hänen äänensä,'),
(1698933,58,58,3,8,'älkää paaduttako sydämiänne, niinkuin teitte katkeroituksessa, kiusauksen päivänä erämaassa,'),
(1698934,58,58,3,9,'jossa teidän isänne minua kiusasivat ja koettelivat, vaikka olivat nähneet minun tekojani neljäkymmentä vuotta;'),
(1698935,58,58,3,10,'sentähden minä vihastuin tähän sukupolveen ja sanoin: ''Aina he eksyvät sydämessään''; mutta he eivät oppineet tuntemaan minun teitäni;'),
(1698936,58,58,3,11,'ja niin minä vihassani vannoin: ''He eivät pääse minun lepooni''."'),
(1698937,58,58,3,12,'Katsokaa, veljet, ettei vain kenelläkään teistä ole paha, epäuskoinen sydän, niin että hän luopuu elävästä Jumalasta,'),
(1698938,58,58,3,13,'vaan kehoittakaa toisianne joka päivä, niin kauan kuin sanotaan: "tänä päivänä", ettei teistä kukaan synnin pettämänä paatuisi;'),
(1698939,58,58,3,14,'sillä me olemme tulleet osallisiksi Kristuksesta, kunhan vain pysymme luottamuksessa, joka meillä alussa oli, vahvoina loppuun asti.'),
(1698940,58,58,3,15,'Kun sanotaan: "Tänä päivänä, jos te kuulette hänen äänensä, älkää paaduttako sydämiänne, niinkuin teitte katkeroituksessa",'),
(1698941,58,58,3,16,'ketkä sitten, vaikka kuulivat, katkeroittivat hänet? Eivätkö kaikki, jotka olivat Mooseksen johdolla lähteneet Egyptistä?'),
(1698942,58,58,3,17,'Mutta keihin hän oli vihastunut neljäkymmentä vuotta? Eikö niihin, jotka olivat syntiä tehneet, joiden ruumiit kaatuivat erämaahan?'),
(1698943,58,58,3,18,'Ja keille hän vannoi, etteivät he pääse hänen lepoonsa? Eikö tottelemattomille?'),
(1698944,58,58,3,19,'Ja niin me näemme, että he epäuskon tähden eivät voineet siihen päästä.'),
(1698945,58,58,4,1,'Varokaamme siis, koska lupaus päästä hänen lepoonsa vielä pysyy varmana, ettei vain havaittaisi kenenkään teistä jääneen taipaleelle.'),
(1698946,58,58,4,2,'Sillä hyvä sanoma on julistettu meille niinkuin heillekin; mutta heidän kuulemansa sana ei heitä hyödyttänyt, koska se ei uskossa sulautunut niihin, jotka sen kuulivat.'),
(1698947,58,58,4,3,'Sillä me pääsemme lepoon, me, jotka tulimme uskoon, niinkuin hän on sanonut: "Ja niin minä vihassani vannoin: ''He eivät pääse minun lepooni''", vaikka hänen tekonsa olivat valmiina maailman perustamisesta asti.'),
(1698948,58,58,4,4,'Sillä hän on jossakin sanonut seitsemännestä päivästä näin: "Ja Jumala lepäsi seitsemäntenä päivänä kaikista teoistansa";'),
(1698949,58,58,4,5,'ja tässä taas: "He eivät pääse minun lepooni".'),
(1698950,58,58,4,6,'Koska siis varmana pysyy, että muutamat pääsevät siihen, ja ne, joille hyvä sanoma ensin julistettiin, eivät päässeet siihen tottelemattomuuden tähden,'),
(1698951,58,58,4,7,'niin hän taas määrää päivän, "tämän päivän", sanomalla Daavidin kautta niin pitkän ajan jälkeen, niinkuin ennen on sanottu: "Tänä päivänä, jos te kuulette hänen äänensä, älkää paaduttako sydämiänne".'),
(1698952,58,58,4,8,'Sillä jos Joosua olisi saattanut heidät lepoon, niin hän ei puhuisi toisesta, senjälkeisestä päivästä.'),
(1698953,58,58,4,9,'Niin on Jumalan kansalle sapatinlepo varmasti tuleva.'),
(1698954,58,58,4,10,'Sillä joka on päässyt hänen lepoonsa, on saanut levon teoistaan, hänkin, niinkuin Jumala omista teoistansa.'),
(1698955,58,58,4,11,'Ahkeroikaamme siis päästä siihen lepoon, ettei kukaan lankeaisi seuraamaan samaa tottelemattomuuden esimerkkiä.'),
(1698956,58,58,4,12,'Sillä Jumalan sana on elävä ja voimallinen ja terävämpi kuin mikään kaksiteräinen miekka ja tunkee lävitse, kunnes se erottaa sielun ja hengen, nivelet sekä ytimet, ja on sydämen ajatusten ja aivoitusten tuomitsija;'),
(1698957,58,58,4,13,'eikä mikään luotu ole hänelle näkymätön, vaan kaikki on alastonta ja paljastettua hänen silmäinsä edessä, jolle meidän on tehtävä tili.'),
(1698958,58,58,4,14,'Kun meillä siis on suuri ylimmäinen pappi, läpi taivasten kulkenut, Jeesus, Jumalan Poika, niin pitäkäämme kiinni tunnustuksesta.'),
(1698959,58,58,4,15,'Sillä ei meillä ole sellainen ylimmäinen pappi, joka ei voi sääliä meidän heikkouksiamme, vaan joka on ollut kaikessa kiusattu samalla lailla kuin mekin, kuitenkin ilman syntiä.'),
(1698960,58,58,4,16,'Käykäämme sentähden uskalluksella armon istuimen eteen, että saisimme laupeuden ja löytäisimme armon, avuksemme oikeaan aikaan.'),
(1698961,58,58,5,1,'Sillä jokainen ylimmäinen pappi, ollen ihmisten joukosta otettu, asetetaan ihmisten puolesta toimittamaan sitä, mikä Jumalalle tulee, uhraamaan lahjoja ja uhreja syntien edestä,'),
(1698962,58,58,5,2,'ja hän voi säälien kohdella tietämättömiä ja eksyviä, koska hän itsekin on heikkouden alainen,'),
(1698963,58,58,5,3,'ja tämän heikkoutensa tähden hänen täytyy, samoinkuin kansan puolesta, niin itsensäkin puolesta uhrata syntien edestä.'),
(1698964,58,58,5,4,'Eikä kukaan sitä arvoa itselleen ota, vaan Jumala kutsuu hänet niinkuin Aaroninkin.'),
(1698965,58,58,5,5,'Niinpä Kristuskaan ei itse korottanut itseänsä ylimmäisen papin kunniaan, vaan hän, joka sanoi hänelle: "Sinä olet minun Poikani, tänä päivänä minä sinut synnytin";'),
(1698966,58,58,5,6,'niinkuin hän toisessakin paikassa sanoo: "Sinä olet pappi iankaikkisesti Melkisedekin järjestyksen mukaan".'),
(1698967,58,58,5,7,'Ja lihansa päivinä hän väkevällä huudolla ja kyynelillä uhrasi rukouksia ja anomuksia sille, joka voi hänet kuolemasta pelastaa; ja hänen rukouksensa kuultiin hänen jumalanpelkonsa tähden.'),
(1698968,58,58,5,8,'Ja niin hän, vaikka oli Poika, oppi siitä, mitä hän kärsi, kuuliaisuuden,'),
(1698969,58,58,5,9,'ja kun oli täydelliseksi tullut, tuli hän iankaikkisen autuuden aikaansaajaksi kaikille, jotka ovat hänelle kuuliaiset,'),
(1698970,58,58,5,10,'hän, jota Jumala nimittää "ylimmäiseksi papiksi Melkisedekin järjestyksen mukaan".'),
(1698971,58,58,5,11,'Tästä meillä on paljon sanottavaa, ja sitä on vaikea selittää, koska olette käyneet hitaiksi kuulemaan.'),
(1698972,58,58,5,12,'Sillä te, joiden olisi jo aika olla opettajia, olette taas sen tarpeessa, että teille opetetaan Jumalan sanojen ensimmäisiä alkeita; te olette tulleet maitoa tarvitseviksi, ei vahvaa ruokaa.'),
(1698973,58,58,5,13,'Sillä jokainen, joka vielä nauttii maitoa, on kokematon vanhurskauden sanassa, sillä hän on lapsi;'),
(1698974,58,58,5,14,'mutta vahva ruoka on täysi-ikäisiä varten, niitä varten, joiden aistit tottumuksesta ovat harjaantuneet erottamaan hyvän pahasta.'),
(1698975,58,58,6,1,'Jättäkäämme sentähden Kristuksen opin alkeet ja pyrkikäämme täydellisyyteen, ryhtymättä taas uudestaan laskemaan perustusta: parannusta kuolleista töistä ja uskoa Jumalaan,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1698976,58,58,6,2,'oppia kasteista ja kätten päällepanemisesta, kuolleitten ylösnousemisesta ja iankaikkisesta tuomiosta.'),
(1698977,58,58,6,3,'Ja niin me tahdomme tehdä, jos vain Jumala sallii.'),
(1698978,58,58,6,4,'Sillä mahdotonta on niitä, jotka kerran ovat valistetut ja taivaallista lahjaa maistaneet ja Pyhästä Hengestä osallisiksi tulleet'),
(1698979,58,58,6,5,'ja maistaneet Jumalan hyvää sanaa ja tulevan maailmanajan voimia,'),
(1698980,58,58,6,6,'ja sitten ovat luopuneet - taas uudistaa parannukseen, he kun jälleen itsellensä ristiinnaulitsevat Jumalan Pojan ja häntä julki häpäisevät.'),
(1698981,58,58,6,7,'Sillä maa, joka särpii sisäänsä sen päälle usein tulevan sateen ja kantaa kasvun hyödyksi niille, joita varten sitä viljelläänkin, saa siunauksen Jumalalta;'),
(1698982,58,58,6,8,'mutta se, joka tuottaa orjantappuroita ja ohdakkeita, on kelvoton ja lähellä kirousta, ja sen loppu on, että se poltetaan.'),
(1698983,58,58,6,9,'Mutta teistä, rakkaat, uskomme sitä, mikä on parempaa ja mikä koituu teille pelastukseksi - vaikka puhummekin näin.'),
(1698984,58,58,6,10,'Sillä Jumala ei ole väärämielinen, niin että hän unhottaisi teidän työnne ja rakkautenne, jota olette osoittaneet hänen nimeänsä kohtaan, kun olette palvelleet pyhiä ja vielä palvelette.'),
(1698985,58,58,6,11,'Mutta me halajamme sitä, että kukin teistä osoittaa samaa intoa, säilyttääkseen toivon varmuuden loppuun asti,'),
(1698986,58,58,6,12,'ettette kävisi veltoiksi, vaan että teistä tulisi niiden seuraajia, jotka uskon ja kärsivällisyyden kautta perivät sen, mikä luvattu on.'),
(1698987,58,58,6,13,'Sillä kun Jumala oli antanut lupauksen Aabrahamille, vannoi hän itse kauttansa, koska hänellä ei ollut ketään suurempaa, kenen kautta vannoa,'),
(1698988,58,58,6,14,'ja sanoi: "Totisesti, siunaamalla minä sinut siunaan, ja enentämällä minä sinut enennän";'),
(1698989,58,58,6,15,'ja näin Aabraham, kärsivällisesti odotettuaan, sai, mitä luvattu oli.'),
(1698990,58,58,6,16,'Sillä ihmiset vannovat suurempansa kautta, ja vala on heille asian vahvistus ja tekee lopun kaikista vastaväitteistä.'),
(1698991,58,58,6,17,'Sentähden, kun Jumala lupauksen perillisille vielä tehokkaammin tahtoi osoittaa, että hänen päätöksensä on muuttumaton, vakuutti hän sen valalla,'),
(1698992,58,58,6,18,'että me näistä kahdesta muuttumattomasta asiasta, joissa Jumala ei ole voinut valhetella, saisimme voimallisen kehoituksen, me, jotka olemme paenneet pitämään kiinni edessämme olevasta toivosta.'),
(1698993,58,58,6,19,'Se toivo meille on ikäänkuin sielun ankkuri, varma ja luja, joka ulottuu esiripun sisäpuolelle asti,'),
(1698994,58,58,6,20,'jonne Jeesus edelläjuoksijana meidän puolestamme on mennyt, tultuaan ylimmäiseksi papiksi Melkisedekin järjestyksen mukaan, iankaikkisesti.'),
(1698995,58,58,7,1,'Sillä tämä Melkisedek, Saalemin kuningas, Jumalan, Korkeimman, pappi, joka meni Aabrahamia vastaan, hänen palatessaan kuninkaita voittamasta, ja siunasi hänet;'),
(1698996,58,58,7,2,'jolle Aabraham myös antoi kymmenykset kaikesta ja joka ensiksi, niinkuin hänen nimensäkin merkitsee, on "vanhurskauden kuningas" ja sen lisäksi vielä "Saalemin kuningas", se on "rauhan kuningas";'),
(1698997,58,58,7,3,'jolla ei ole isää, ei äitiä, ei sukua, ei päivien alkua eikä elämän loppua, mutta joka on Jumalan Poikaan verrattava - hän pysyy pappina ainaisesti.'),
(1698998,58,58,7,4,'Katsokaa, kuinka suuri hän on, jolle itse kantaisä Aabraham antoi kymmenykset parhaimmasta saaliistaan.'),
(1698999,58,58,7,5,'Onhan niillä Leevin pojista, jotka saavat pappeuden, käsky lain mukaan ottaa kymmenyksiä kansalta, se on veljiltään, vaikka nämä ovatkin Aabrahamin kupeista lähteneet;'),
(1699000,58,58,7,6,'mutta hän, jonka sukua ei johdeta heistä, otti kymmenykset Aabrahamilta ja siunasi sen, jolla oli lupaukset.'),
(1699001,58,58,7,7,'Mutta kieltämätöntä on, että halvempi saa siunauksen paremmaltaan.'),
(1699002,58,58,7,8,'Ja täällä kuolevaiset ihmiset ottavat kymmenyksiä, mutta siellä se, jonka todistetaan elävän.'),
(1699003,58,58,7,9,'Ja Aabrahamin kautta, niin sanoakseni, on Leevikin, joka kymmenyksiä ottaa, maksanut kymmenyksiä;'),
(1699004,58,58,7,10,'sillä hän oli vielä isänsä kupeissa, kun Melkisedek meni tätä vastaan.'),
(1699005,58,58,7,11,'Jos siis täydellisyys olisi saavutettu leeviläisen pappeuden kautta, sillä tähän on kansa laissa sidottu, miksi sitten oli tarpeen, että nousi toinen pappi Melkisedekin järjestyksen mukaan eikä tullut nimitetyksi Aaronin järjestyksen mukaan?'),
(1699006,58,58,7,12,'Sillä pappeuden muuttuessa tapahtuu välttämättä myös lain muutos.'),
(1699007,58,58,7,13,'Sillä se, josta tämä sanotaan, oli toista sukukuntaa, josta ei kukaan ole alttaritointa hoitanut.'),
(1699008,58,58,7,14,'Onhan tunnettua, että meidän Herramme on noussut Juudasta, jonka sukukunnan pappeudesta Mooses ei ole mitään puhunut.'),
(1699009,58,58,7,15,'Ja tämä käy vielä paljoa selvemmäksi, kun nousee toinen pappi, Melkisedekin kaltainen,'),
(1699010,58,58,7,16,'joka ei ole siksi tullut lihallisen käskyn lain mukaan, vaan katoamattoman elämän voimasta.'),
(1699011,58,58,7,17,'Sillä hänestä todistetaan: "Sinä olet pappi iankaikkisesti Melkisedekin järjestyksen mukaan".'),
(1699012,58,58,7,18,'Täten kyllä entinen säädös kumotaan, koska se oli voimaton ja hyödytön'),
(1699013,58,58,7,19,'- sillä laki ei tehnyt mitään täydelliseksi - mutta sijaan tulee parempi toivo, jonka kautta me lähestymme Jumalaa.'),
(1699014,58,58,7,20,'Ja niinkuin tämä ei tapahtunut ilman valan vannomista - nuo taas ovat papeiksi tulleet ilman heistä vannottua valaa,'),
(1699015,58,58,7,21,'mutta tämä hänestä vannotulla valalla, sen asettamana, joka hänelle sanoi: "Herra on vannonut eikä ole katuva: ''Sinä olet pappi iankaikkisesti''" -'),
(1699016,58,58,7,22,'niin on myös se liitto parempi, jonka takaajaksi Jeesus on tullut.'),
(1699017,58,58,7,23,'Ja noita toisia pappeja on tullut useampia, koska kuolema ei sallinut heidän pysyä;'),
(1699018,58,58,7,24,'mutta tällä on katoamaton pappeus, sentähden että hän pysyy iankaikkisesti,'),
(1699019,58,58,7,25,'jonka tähden hän myös voi täydellisesti pelastaa ne, jotka hänen kauttaan Jumalan tykö tulevat, koska hän aina elää rukoillakseen heidän puolestansa.'),
(1699020,58,58,7,26,'Senkaltainen ylimmäinen pappi meille sopikin: pyhä, viaton, tahraton, syntisistä erotettu ja taivaita korkeammaksi tullut,'),
(1699021,58,58,7,27,'jonka ei joka päivä ole tarvis, niinkuin ylimmäisten pappien, ensiksi uhrata omien syntiensä edestä ja sitten kansan; sillä tämän hän teki kerta kaikkiaan, uhratessaan itsensä.'),
(1699022,58,58,7,28,'Sillä laki asettaa ylimmäisiksi papeiksi ihmisiä, jotka ovat heikkoja, mutta valan sana, joka on myöhäisempi kuin laki, asettaa Pojan, iankaikkisesti täydelliseksi tulleen.'),
(1699023,58,58,8,1,'Mutta pääkohta siinä, mistä me puhumme, on tämä: meillä on sellainen ylimmäinen pappi, joka istuu Majesteetin valtaistuimen oikealla puolella taivaissa,'),
(1699024,58,58,8,2,'tehdäkseen pappispalvelusta kaikkeinpyhimmässä, siinä oikeassa majassa, jonka on rakentanut Herra eikä ihminen.'),
(1699025,58,58,8,3,'Sillä jokainen ylimmäinen pappi asetetaan uhraamaan lahjoja ja uhreja, jonka tähden on välttämätöntä, että tälläkin on jotakin uhraamista.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699026,58,58,8,4,'Jos hän siis olisi maan päällä, ei hän olisikaan pappi, koska jo ovat olemassa ne, jotka lain mukaan esiinkantavat lahjoja,'),
(1699027,58,58,8,5,'ja jotka palvelevat siinä, mikä on taivaallisten kuva ja varjo, niinkuin ilmoitettiin Moosekselle, kun hänen oli valmistettava maja. Sillä hänelle sanottiin: "Katso, että teet kaikki sen kaavan mukaan, joka sinulle vuorella näytettiin".'),
(1699028,58,58,8,6,'Mutta tämä taas on saanut niin paljoa jalomman viran, kuin hän on myös paremman liiton välimies, liiton, joka on paremmille lupauksille perustettu.'),
(1699029,58,58,8,7,'Sillä jos ensimmäinen liitto olisi ollut moitteeton, ei olisi etsitty sijaa toiselle.'),
(1699030,58,58,8,8,'Sillä moittien heitä hän sanoo: "Katso, päivät tulevat, sanoo Herra, jolloin minä teen Israelin heimon ja Juudan heimon kanssa uuden liiton,'),
(1699031,58,58,8,9,'en sellaista liittoa kuin se, jonka minä tein heidän isäinsä kanssa silloin, kun minä tartuin heidän käteensä ja vein heidät pois Egyptin maasta. Sillä he eivät pysyneet minun liitossani, ja niin en minäkään heistä huolinut, sanoo Herra.'),
(1699032,58,58,8,10,'Sillä tämä on se liitto, jonka minä teen Israelin heimon kanssa näiden päivien jälkeen, sanoo Herra: Minä panen lakini heidän mieleensä, ja kirjoitan ne heidän sydämiinsä, ja niin minä olen heidän Jumalansa, ja he ovat minun kansani.'),
(1699033,58,58,8,11,'Ja silloin ei enää kukaan opeta kansalaistaan eikä veli veljeään sanoen: ''Tunne Herra''; sillä he kaikki, pienimmästä suurimpaan, tuntevat minut.'),
(1699034,58,58,8,12,'Sillä minä annan anteeksi heidän vääryytensä enkä enää muista heidän syntejänsä."'),
(1699035,58,58,8,13,'Sanoessaan "uuden" hän on julistanut ensimmäisen liiton vanhentuneeksi; mutta se, mikä vanhenee ja käy iälliseksi, on lähellä häviämistään.'),
(1699036,58,58,9,1,'Olihan tosin ensimmäiselläkin liitolla jumalanpalvelussäännöt ja maallinen pyhäkkö.'),
(1699037,58,58,9,2,'Sillä maja oli valmistettu niin, että siinä oli etumainen maja, jossa oli sekä lampunjalka että pöytä ja näkyleivät, ja sen nimi on "pyhä".'),
(1699038,58,58,9,3,'Mutta toisen esiripun takana oli se maja, jonka nimi on "kaikkeinpyhin";'),
(1699039,58,58,9,4,'siinä oli kultainen suitsutusalttari ja liiton arkki, yltympäri kullalla päällystetty, jossa säilytettiin kultainen mannaa sisältävä astia ja Aaronin viheriöinyt sauva ja liiton taulut,'),
(1699040,58,58,9,5,'ja arkin päällä kirkkauden kerubit varjostamassa armoistuinta. Mutta näistä nyt ei ole syytä puhua kustakin erikseen.'),
(1699041,58,58,9,6,'Kun nyt kaikki on näin järjestetty, menevät papit joka aika etumaiseen majaan jumalanpalvelusta toimittamaan,'),
(1699042,58,58,9,7,'mutta toiseen majaan menee ainoastaan ylimmäinen pappi kerran vuodessa, ei ilman verta, jonka hän uhraa itsensä edestä ja kansan tahattomien syntien edestä.'),
(1699043,58,58,9,8,'Näin Pyhä Henki osoittaa, että tie kaikkeinpyhimpään vielä on ilmoittamatta, niin kauan kuin etumainen maja vielä seisoo.'),
(1699044,58,58,9,9,'Tämä on nykyistä aikaa tarkoittava vertauskuva, ja sen mukaisesti uhrataan lahjoja ja uhreja, jotka eivät kykene tekemään täydelliseksi omassatunnossaan sitä, joka jumalanpalvelusta toimittaa,'),
(1699045,58,58,9,10,'vaan jotka, niinkuin ruuat ja juomat ja erilaiset pesotkin, ovat ainoastaan lihan sääntöjä, jotka ovat voimassa uuden järjestyksen aikaan asti.'),
(1699046,58,58,9,11,'Mutta kun Kristus tuli tulevaisen hyvän ylimmäiseksi papiksi, niin hän suuremman ja täydellisemmän majan kautta, joka ei ole käsillä tehty, se on: joka ei ole tätä luomakuntaa,'),
(1699047,58,58,9,12,'meni, ei kauristen ja vasikkain veren kautta, vaan oman verensä kautta kerta kaikkiaan kaikkeinpyhimpään ja sai aikaan iankaikkisen lunastuksen.'),
(1699048,58,58,9,13,'Sillä jos kauristen ja härkäin veri ja hiehon tuhka, saastaisten päälle vihmottuna, pyhittää lihanpuhtauteen,'),
(1699049,58,58,9,14,'kuinka paljoa enemmän on Kristuksen veri, hänen, joka iankaikkisen Hengen kautta uhrasi itsensä viattomana Jumalalle, puhdistava meidän omantuntomme kuolleista teoista palvelemaan elävää Jumalaa!'),
(1699050,58,58,9,15,'Ja sentähden hän on uuden liiton välimies, että, koska hänen kuolemansa on tapahtunut lunastukseksi ensimmäisen liiton aikuisista rikkomuksista, ne, jotka ovat kutsutut, saisivat luvatun iankaikkisen perinnön.'),
(1699051,58,58,9,16,'Sillä missä on testamentti, siinä on sen tekijän kuolema toteennäytettävä;'),
(1699052,58,58,9,17,'sillä vasta kuoleman jälkeen testamentti on pitävä, koska se ei milloinkaan ole voimassa tekijänsä eläessä.'),
(1699053,58,58,9,18,'Sentähden ei myöskään ensimmäistä liittoa verettä vihitty.'),
(1699054,58,58,9,19,'Sillä kun Mooses oli kaikelle kansalle julkilukenut kaikki käskyt, niinkuin ne laissa kuuluvat, otti hän vasikkain ja kauristen veren ynnä vettä ja purppuravillaa ja isopin ja vihmoi sekä itse kirjan että kaiken kansan,'),
(1699055,58,58,9,20,'sanoen: "Tämä on sen liiton veri, jonka Jumala on teille säätänyt".'),
(1699056,58,58,9,21,'Ja samoin hän verellä vihmoi myös majan ja kaikki palvelukseen kuuluvat esineet.'),
(1699057,58,58,9,22,'Niin puhdistetaan lain mukaan miltei kaikki verellä, ja ilman verenvuodatusta ei tapahdu anteeksiantamista.'),
(1699058,58,58,9,23,'On siis välttämätöntä, että taivaallisten kuvat tällä tavalla puhdistetaan, mutta että taivaalliset itse puhdistetaan paremmilla uhreilla kuin nämä.'),
(1699059,58,58,9,24,'Sillä Kristus ei mennyt käsillä tehtyyn kaikkeinpyhimpään, joka vain on sen oikean kuva, vaan itse taivaaseen, nyt ilmestyäkseen Jumalan kasvojen eteen meidän hyväksemme.'),
(1699060,58,58,9,25,'Eikä hän mennyt uhratakseen itseänsä monta kertaa, niinkuin ylimmäinen pappi joka vuosi menee kaikkeinpyhimpään, vierasta verta mukanaan,'),
(1699061,58,58,9,26,'sillä muutoin hänen olisi pitänyt kärsimän monta kertaa maailman perustamisesta asti; mutta nyt hän on yhden ainoan kerran maailmanaikojen lopulla ilmestynyt, poistaakseen synnin uhraamalla itsensä.'),
(1699062,58,58,9,27,'Ja samoinkuin ihmisille on määrätty, että heidän kerran on kuoleminen, mutta senjälkeen tulee tuomio,'),
(1699063,58,58,9,28,'samoin Kristuskin, kerran uhrattuna ottaakseen pois monien synnit, on toistamiseen ilman syntiä ilmestyvä pelastukseksi niille, jotka häntä odottavat.'),
(1699064,58,58,10,1,'Sillä koska laissa on vain tulevan hyvän varjo, ei itse asiain olemusta, ei se koskaan voi samoilla jokavuotisilla uhreilla, joita he alinomaa kantavat esiin, tehdä niiden tuojia täydellisiksi.'),
(1699065,58,58,10,2,'Sillä eikö muutoin olisi lakattu niitä uhraamasta, koska näillä, jotka jumalanpalvelustaan toimittavat, kerran puhdistettuina, ei enää olisi ollut mitään tuntoa synneistä?'),
(1699066,58,58,10,3,'Mutta niissä on jokavuotinen muistutus synneistä.'),
(1699067,58,58,10,4,'Sillä mahdotonta on, että härkäin ja kauristen veri voi ottaa pois syntejä.'),
(1699068,58,58,10,5,'Sentähden hän maailmaan tullessaan sanoo: "Uhria ja antia sinä et tahtonut, mutta ruumiin sinä minulle valmistit;'),
(1699069,58,58,10,6,'polttouhreihin ja syntiuhreihin sinä et mielistynyt.'),
(1699070,58,58,10,7,'Silloin minä sanoin: ''Katso, minä tulen - kirjakääröön on minusta kirjoitettu - tekemään sinun tahtosi, Jumala''."'),
(1699071,58,58,10,8,'Kun hän ensin sanoo: "Uhreja ja anteja ja polttouhreja ja syntiuhreja sinä et tahtonut etkä niihin mielistynyt", vaikka niitä lain mukaan uhrataankin,'),
(1699072,58,58,10,9,'sanoo hän sitten: "Katso, minä tulen tekemään sinun tahtosi". Hän poistaa ensimmäisen, pystyttääkseen toisen.'),
(1699073,58,58,10,10,'Ja tämän tahdon perusteella me olemme pyhitetyt Jeesuksen Kristuksen ruumiin uhrilla kerta kaikkiaan.'),
(1699074,58,58,10,11,'Ja kaikki papit seisovat päivä päivältä palvelustaan toimittamassa ja usein uhraamassa, aina samoja uhreja, jotka eivät ikinä voi syntejä poistaa;'),
(1699075,58,58,10,12,'mutta tämä on, uhrattuaan yhden ainoan uhrin syntien edestä, ainiaaksi istuutunut Jumalan oikealle puolelle,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699076,58,58,10,13,'ja odottaa nyt vain, kunnes hänen vihollisensa pannaan hänen jalkojensa astinlaudaksi.'),
(1699077,58,58,10,14,'Sillä hän on yhdellä ainoalla uhrilla ainiaaksi tehnyt täydellisiksi ne, jotka pyhitetään.'),
(1699078,58,58,10,15,'Todistaahan sen meille myös Pyhä Henki; sillä sanottuaan:'),
(1699079,58,58,10,16,'"Tämä on se liitto, jonka minä näiden päivien jälkeen teen heidän kanssaan", sanoo Herra: "Minä panen lakini heidän sydämiinsä ja kirjoitan ne heidän mieleensä";'),
(1699080,58,58,10,17,'ja: "heidän syntejänsä ja laittomuuksiansa en minä enää muista".'),
(1699081,58,58,10,18,'Mutta missä nämä ovat anteeksi annetut, siinä ei uhria synnin edestä enää tarvita.'),
(1699082,58,58,10,19,'Koska meillä siis, veljet, on luja luottamus siihen, että meillä Jeesuksen veren kautta on pääsy kaikkeinpyhimpään,'),
(1699083,58,58,10,20,'jonka pääsyn hän on vihkinyt meille uudeksi ja eläväksi tieksi, joka käy esiripun, se on hänen lihansa, kautta,'),
(1699084,58,58,10,21,'ja koska meillä on "suuri pappi, Jumalan huoneen haltija",'),
(1699085,58,58,10,22,'niin käykäämme esiin totisella sydämellä, täydessä uskon varmuudessa, sydän vihmottuna puhtaaksi pahasta omastatunnosta ja ruumis puhtaalla vedellä pestynä;'),
(1699086,58,58,10,23,'pysykäämme järkähtämättä toivon tunnustuksessa, sillä hän, joka antoi lupauksen, on uskollinen;'),
(1699087,58,58,10,24,'ja valvokaamme toinen toistamme rohkaisuksi toisillemme rakkauteen ja hyviin tekoihin;'),
(1699088,58,58,10,25,'älkäämme jättäkö omaa seurakunnankokoustamme, niinkuin muutamien on tapana, vaan kehoittakaamme toisiamme, sitä enemmän, kuta enemmän näette tuon päivän lähestyvän.'),
(1699089,58,58,10,26,'Sillä jos me tahallamme teemme syntiä, päästyämme totuuden tuntoon, niin ei ole enää uhria meidän syntiemme edestä,'),
(1699090,58,58,10,27,'vaan hirmuinen tuomion odotus ja tulen kiivaus, joka on kuluttava vastustajat.'),
(1699091,58,58,10,28,'Joka hylkää Mooseksen lain, sen pitää armotta kahden tai kolmen todistajan todistuksen nojalla kuoleman:'),
(1699092,58,58,10,29,'kuinka paljoa ankaramman rangaistuksen luulettekaan sen ansaitsevan, joka tallaa jalkoihinsa Jumalan Pojan ja pitää epäpyhänä liiton veren, jossa hänet on pyhitetty, ja pilkkaa armon Henkeä!'),
(1699093,58,58,10,30,'Sillä me tunnemme hänet, joka on sanonut: "Minun on kosto, minä olen maksava"; ja vielä: "Herra on tuomitseva kansansa".'),
(1699094,58,58,10,31,'Hirmuista on langeta elävän Jumalan käsiin.'),
(1699095,58,58,10,32,'Mutta muistakaa entisiä päiviä, jolloin te, valistetuiksi tultuanne, kestitte monet kärsimysten kilvoitukset,'),
(1699096,58,58,10,33,'kun te toisaalta olitte häväistysten ja ahdistusten alaisina, kaikkien katseltavina, toisaalta taas tulitte niiden osaveljiksi, joiden kävi samalla tavalla.'),
(1699097,58,58,10,34,'Sillä vankien kanssa te olette kärsineet ja ilolla pitäneet hyvänänne omaisuutenne ryöstön, tietäen, että teillä on parempi tavara, joka pysyy.'),
(1699098,58,58,10,35,'Älkää siis heittäkö pois uskallustanne, jonka palkka on suuri.'),
(1699099,58,58,10,36,'Sillä te tarvitsette kestäväisyyttä, tehdäksenne Jumalan tahdon ja saadaksenne sen, mikä luvattu on.'),
(1699100,58,58,10,37,'Sillä "vähän, aivan vähän aikaa vielä, niin tulee hän, joka tuleva on, eikä viivyttele;'),
(1699101,58,58,10,38,'mutta minun vanhurskaani on elävä uskosta, ja jos hän vetäytyy pois, ei minun sieluni mielisty häneen".'),
(1699102,58,58,10,39,'Mutta me emme ole niitä, jotka vetäytyvät pois omaksi kadotuksekseen, vaan niitä, jotka uskovat sielunsa pelastukseksi.'),
(1699103,58,58,11,1,'Mutta usko on luja luottamus siihen, mitä toivotaan, ojentautuminen sen mukaan, mikä ei näy.'),
(1699104,58,58,11,2,'Sillä sen kautta saivat vanhat todistuksen.'),
(1699105,58,58,11,3,'Uskon kautta me ymmärrämme, että maailma on rakennettu Jumalan sanalla, niin että se, mikä nähdään, ei ole syntynyt näkyväisestä.'),
(1699106,58,58,11,4,'Uskon kautta uhrasi Aabel Jumalalle paremman uhrin kuin Kain, ja uskon kautta hän sai todistuksen, että hän oli vanhurskas, kun Jumala antoi todistuksen hänen uhrilahjoistaan; ja uskonsa kautta hän vielä kuoltuaankin puhuu.'),
(1699107,58,58,11,5,'Uskon kautta otettiin Eenok pois, näkemättä kuolemaa, "eikä häntä enää ollut, koska Jumala oli ottanut hänet pois". Sillä ennen poisottamistaan hän oli saanut todistuksen, että hän oli otollinen Jumalalle.'),
(1699108,58,58,11,6,'Mutta ilman uskoa on mahdoton olla otollinen; sillä sen, joka Jumalan tykö tulee, täytyy uskoa, että Jumala on ja että hän palkitsee ne, jotka häntä etsivät.'),
(1699109,58,58,11,7,'Uskon kautta rakensi Nooa, saatuaan ilmoituksen siitä, mikä ei vielä näkynyt, pyhässä pelossa arkin perhekuntansa pelastukseksi; ja uskonsa kautta hän tuomitsi maailman, ja hänestä tuli sen vanhurskauden perillinen, joka uskosta tulee.'),
(1699110,58,58,11,8,'Uskon kautta oli Aabraham kuuliainen, kun hänet kutsuttiin lähtemään siihen maahan, jonka hän oli saava perinnöksi, ja hän lähti tietämättä, minne oli saapuva.'),
(1699111,58,58,11,9,'Uskon kautta hän eli muukalaisena lupauksen maassa niinkuin vieraassa maassa, asuen teltoissa Iisakin ja Jaakobin kanssa, jotka olivat saman lupauksen perillisiä;'),
(1699112,58,58,11,10,'sillä hän odotti sitä kaupunkia, jolla on perustukset ja jonka rakentaja ja luoja on Jumala.'),
(1699113,58,58,11,11,'Uskon kautta sai Saarakin voimaa suvun perustamiseen, vieläpä yli-ikäisenä, koska hän piti luotettavana sen, joka oli antanut lupauksen.'),
(1699114,58,58,11,12,'Sentähden syntyikin yhdestä miehestä, vieläpä kuolettuneesta, niin suuri paljous, kuin on tähtiä taivaalla ja kuin meren rannalla hiekkaa, epälukuisesti.'),
(1699115,58,58,11,13,'Uskossa nämä kaikki kuolivat eivätkä luvattua saavuttaneet, vaan kaukaa he olivat sen nähneet ja sitä tervehtineet ja tunnustaneet olevansa vieraita ja muukalaisia maan päällä.'),
(1699116,58,58,11,14,'Sillä jotka näin puhuvat, ilmaisevat etsivänsä isänmaata.'),
(1699117,58,58,11,15,'Ja jos he olisivat tarkoittaneet sitä maata, josta olivat lähteneet, niin olisihan heillä ollut tilaisuus palata takaisin;'),
(1699118,58,58,11,16,'mutta nyt he pyrkivät parempaan, se on taivaalliseen. Sentähden Jumala ei heitä häpeä, vaan sallii kutsua itseään heidän Jumalaksensa; sillä hän on valmistanut heille kaupungin.'),
(1699119,58,58,11,17,'Uskon kautta uhrasi Aabraham, koetukselle pantuna, Iisakin, uhrasi ainoan poikansa, hän, joka oli lupaukset vastaanottanut'),
(1699120,58,58,11,18,'ja jolle oli sanottu: "Iisakista sinä saat nimellesi jälkeläisen",'),
(1699121,58,58,11,19,'sillä hän päätti, että Jumala on voimallinen kuolleistakin herättämään; ja sen vertauskuvana hän saikin hänet takaisin.'),
(1699122,58,58,11,20,'Uskon kautta antoi Iisak Jaakobille ja Eesaulle siunauksen, joka koski tulevaisiakin.'),
(1699123,58,58,11,21,'Uskon kautta siunasi Jaakob kuollessaan kumpaisenkin Joosefin pojista ja rukoili sauvansa päähän nojaten.'),
(1699124,58,58,11,22,'Uskon kautta muistutti Joosef loppunsa lähetessä Israelin lasten lähdöstä ja antoi määräyksen luistansa.'),
(1699125,58,58,11,23,'Uskon kautta pitivät Mooseksen vanhemmat häntä heti hänen syntymänsä jälkeen kätkössä kolme kuukautta, sillä he näkivät, että lapsi oli ihana; eivätkä he peljänneet kuninkaan käskyä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699126,58,58,11,24,'Uskon kautta kieltäytyi Mooses suureksi tultuaan kantamasta faraon tyttären pojan nimeä.'),
(1699127,58,58,11,25,'Hän otti mieluummin kärsiäkseen vaivaa yhdessä Jumalan kansan kanssa kuin saadakseen synnistä lyhytaikaista nautintoa,'),
(1699128,58,58,11,26,'katsoen "Kristuksen pilkan" suuremmaksi rikkaudeksi kuin Egyptin aarteet; sillä hän käänsi katseensa palkintoa kohti.'),
(1699129,58,58,11,27,'Uskon kautta hän jätti Egyptin pelkäämättä kuninkaan vihaa; sillä koska hän ikäänkuin näki sen, joka on näkymätön, niin hän kesti.'),
(1699130,58,58,11,28,'Uskon kautta hän pani toimeen pääsiäisenvieton ja verensivelyn, ettei esikoisten surmaaja koskisi heihin.'),
(1699131,58,58,11,29,'Uskon kautta he kulkivat poikki Punaisen meren ikäänkuin kuivalla maalla; jota yrittäessään egyptiläiset hukkuivat.'),
(1699132,58,58,11,30,'Uskon kautta kaatuivat Jerikon muurit, sittenkuin niiden ympäri oli kuljettu seitsemän päivää.'),
(1699133,58,58,11,31,'Uskon kautta pelastui portto Raahab joutumasta perikatoon yhdessä uppiniskaisten kanssa, kun oli, rauha mielessään, ottanut vakoojat luoksensa.'),
(1699134,58,58,11,32,'Ja mitä minä vielä sanoisin? Sillä minulta loppuisi aika, jos kertoisin Gideonista, Baarakista, Simsonista, Jeftasta, Daavidista ja Samuelista ja profeetoista,'),
(1699135,58,58,11,33,'jotka uskon kautta kukistivat valtakuntia, pitivät vanhurskautta voimassa, saivat kokea lupauksien toteutumista, tukkivat jalopeurain kidat,'),
(1699136,58,58,11,34,'sammuttivat tulen voiman, pääsivät miekanteriä pakoon, voimistuivat heikkoudesta, tulivat väkeviksi sodassa, ajoivat pakoon muukalaisten sotajoukot.'),
(1699137,58,58,11,35,'On ollut vaimoja, jotka ylösnousemuksen kautta ovat saaneet kuolleensa takaisin. Toiset ovat antaneet kiduttaa itseään eivätkä ole ottaneet vastaan vapautusta, että saisivat paremman ylösnousemuksen;'),
(1699138,58,58,11,36,'toiset taas ovat saaneet kokea pilkkaa ja ruoskimista, vieläpä kahleita ja vankeutta;'),
(1699139,58,58,11,37,'heitä on kivitetty, kiusattu, rikki sahattu, miekalla surmattu; he ovat kierrelleet ympäri lampaannahoissa ja vuohennahoissa, puutteenalaisina, ahdistettuina, pahoinpideltyinä -'),
(1699140,58,58,11,38,'he, jotka olivat liian hyviä tälle maailmalle -; he ovat harhailleet erämaissa ja vuorilla ja luolissa ja maakuopissa.'),
(1699141,58,58,11,39,'Ja vaikka nämä kaikki uskon kautta olivat todistuksen saaneet, eivät he kuitenkaan saavuttaneet sitä, mikä oli luvattu;'),
(1699142,58,58,11,40,'sillä Jumala oli varannut meitä varten jotakin parempaa, etteivät he ilman meitä pääsisi täydellisyyteen.'),
(1699143,58,58,12,1,'Sentähden, kun meillä on näin suuri pilvi todistajia ympärillämme, pankaamme mekin pois kaikki, mikä meitä painaa, ja synti, joka niin helposti meidät kietoo, ja juoskaamme kestävinä edessämme olevassa kilvoituksessa,'),
(1699144,58,58,12,2,'silmät luotuina uskon alkajaan ja täyttäjään, Jeesukseen, joka hänelle tarjona olevan ilon sijasta kärsi ristin, häpeästä välittämättä, ja istui Jumalan valtaistuimen oikealle puolelle.'),
(1699145,58,58,12,3,'Ajatelkaa häntä, joka syntisiltä on saanut kärsiä sellaista vastustusta itseänsä kohtaan, ettette väsyisi ja menettäisi toivoanne.'),
(1699146,58,58,12,4,'Ette vielä ole verille asti tehneet vastarintaa, taistellessanne syntiä vastaan,'),
(1699147,58,58,12,5,'ja te olette unhottaneet kehoituksen, joka puhuu teille niinkuin lapsille: "Poikani, älä pidä halpana Herran kuritusta, äläkä menetä toivoasi, kun hän sinua nuhtelee;'),
(1699148,58,58,12,6,'sillä jota Herra rakastaa, sitä hän kurittaa; ja hän ruoskii jokaista lasta, jonka hän ottaa huomaansa".'),
(1699149,58,58,12,7,'Kuritukseksenne te kärsitte; Jumala kohtelee teitä niinkuin lapsia. Sillä mikä on se lapsi, jota isä ei kurita?'),
(1699150,58,58,12,8,'Mutta jos te olette ilman kuritusta, josta kaikki ovat osallisiksi tulleet, silloinhan te olette äpäriä ettekä lapsia.'),
(1699151,58,58,12,9,'Ja vielä: meillä oli ruumiilliset isämme kurittajina, ja heitä me kavahdimme; emmekö paljoa ennemmin olisi alamaiset henkien Isälle, että eläisimme?'),
(1699152,58,58,12,10,'Sillä nuo kurittivat meitä vain muutamia päiviä varten, oman ymmärryksensä mukaan, mutta tämä kurittaa meitä tosi parhaaksemme, että me pääsisimme osallisiksi hänen pyhyydestään.'),
(1699153,58,58,12,11,'Mikään kuritus ei tosin sillä kertaa näytä olevan iloksi, vaan murheeksi, mutta jälkeenpäin se antaa vanhurskauden rauhanhedelmän niille, jotka sen kautta ovat harjoitetut.'),
(1699154,58,58,12,12,'Sentähden: "Ojentakaa hervonneet kätenne ja rauenneet polvenne";'),
(1699155,58,58,12,13,'ja: "tehkää polut suoriksi jaloillenne", ettei ontuvan jalka nyrjähtäisi, vaan ennemmin parantuisi.'),
(1699156,58,58,12,14,'Pyrkikää rauhaan kaikkien kanssa ja pyhitykseen, sillä ilman sitä ei kukaan ole näkevä Herraa;'),
(1699157,58,58,12,15,'ja pitäkää huoli siitä, ettei kukaan jää osattomaksi Jumalan armosta, "ettei mikään katkeruuden juuri pääse kasvamaan ja tekemään häiriötä", ja monet sen kautta tule saastutetuiksi,'),
(1699158,58,58,12,16,'ja ettei kukaan olisi haureellinen tahi epäpyhä niinkuin Eesau, joka yhdestä ateriasta myi esikoisuutensa.'),
(1699159,58,58,12,17,'Sillä te tiedätte, että hänet sittemminkin, kun hän tahtoi päästä siunausta perimään, hyljättiin; sillä hän ei löytänyt tilaa peruutukselle, vaikka hän kyynelin sitä pyysi.'),
(1699160,58,58,12,18,'Sillä te ette ole käyneet sen vuoren tykö, jota voidaan käsin koskea ja joka tulessa palaa, ettekä synkeyden, ette pimeyden, ette myrskyn,'),
(1699161,58,58,12,19,'ette pasunan kaiun ettekä äänen tykö, joka puhui niin, että ne, jotka sen kuulivat, pyysivät, ettei heille enää puhuttaisi;'),
(1699162,58,58,12,20,'sillä he eivät voineet kestää tätä käskyä: "Koskettakoon vuorta vaikka eläinkin, se kivitettäköön";'),
(1699163,58,58,12,21,'ja niin hirmuinen oli se näky, että Mooses sanoi: "Minä olen peljästynyt ja vapisen";'),
(1699164,58,58,12,22,'vaan te olette käyneet Siionin vuoren tykö ja elävän Jumalan kaupungin, taivaallisen Jerusalemin tykö, ja kymmenien tuhansien enkelien tykö,'),
(1699165,58,58,12,23,'taivaissa kirjoitettujen esikoisten juhlajoukon ja seurakunnan tykö, ja tuomarin tykö, joka on kaikkien Jumala, ja täydellisiksi tulleitten vanhurskasten henkien tykö,'),
(1699166,58,58,12,24,'ja uuden liiton välimiehen, Jeesuksen, tykö, ja vihmontaveren tykö, joka puhuu parempaa kuin Aabelin veri.'),
(1699167,58,58,12,25,'Katsokaa, ettette torju luotanne häntä, joka puhuu; sillä jos nuo, jotka torjuivat luotaan hänet, joka ilmoitti Jumalan tahdon maan päällä, eivät voineet päästä pakoon, niin paljoa vähemmän me, jos käännymme pois hänestä, joka ilmoittaa sen taivaista.'),
(1699168,58,58,12,26,'Silloin hänen äänensä järkytti maata, mutta nyt hän on luvannut sanoen: "Vielä kerran minä liikutan maan, jopa taivaankin".'),
(1699169,58,58,12,27,'Mutta tuo "vielä kerran" osoittaa, että ne, mitkä järkkyvät, koska ovat luotuja, tulevat muuttumaan, että ne, jotka eivät järky, pysyisivät.'),
(1699170,58,58,12,28,'Sentähden, koska me saamme valtakunnan, joka ei järky, olkaamme kiitolliset ja siten palvelkaamme Jumalaa, hänelle mielihyväksi, pyhällä arkuudella ja pelolla;'),
(1699171,58,58,12,29,'sillä meidän Jumalamme on kuluttavainen tuli.'),
(1699172,58,58,13,1,'Pysyköön veljellinen rakkaus.'),
(1699173,58,58,13,2,'Älkää unhottako vieraanvaraisuutta; sillä sitä osoittamalla muutamat ovat tietämättään saaneet pitää enkeleitä vierainaan.'),
(1699174,58,58,13,3,'Muistakaa vankeja, niinkuin olisitte itsekin heidän kanssaan vangittuina; muistakaa pahoinpideltyjä, sillä onhan teillä itsellännekin ruumis.'),
(1699175,58,58,13,4,'Avioliitto pidettäköön kunniassa kaikkien kesken, ja aviovuode saastuttamatonna; sillä haureelliset ja avionrikkojat Jumala tuomitsee.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699176,58,58,13,5,'Älkää olko vaelluksessanne ahneita; tyytykää siihen, mitä teillä on; sillä hän itse on sanonut: "En minä sinua hylkää enkä sinua jätä";'),
(1699177,58,58,13,6,'niin että me turvallisin mielin sanomme: "Herra on minun auttajani, en minä pelkää; mitä voi ihminen minulle tehdä?"'),
(1699178,58,58,13,7,'Muistakaa johtajianne, jotka ovat puhuneet teille Jumalan sanaa; katsokaa, kuinka heidän vaelluksensa on päättynyt, ja seuratkaa heidän uskoansa.'),
(1699179,58,58,13,8,'Jeesus Kristus on sama eilen ja tänään ja iankaikkisesti.'),
(1699180,58,58,13,9,'Älkää antako monenlaisten ja vieraiden oppien itseänne vietellä; sillä on hyvä, että sydän saa vahvistusta armosta eikä ruuista, joista ne, jotka niitä menoja ovat noudattaneet, eivät ole mitään hyötyneet.'),
(1699181,58,58,13,10,'Meillä on uhrialttari, josta majassa palvelevilla ei ole valta syödä.'),
(1699182,58,58,13,11,'Sillä niiden eläinten ruumiit, joiden veren ylimmäinen pappi syntien sovitukseksi kantaa kaikkeinpyhimpään, poltetaan ulkopuolella leirin.'),
(1699183,58,58,13,12,'Sentähden myös Jeesus, pyhittääkseen omalla verellänsä kansan, kärsi portin ulkopuolella.'),
(1699184,58,58,13,13,'Niin menkäämme siis hänen tykönsä "ulkopuolelle leirin", hänen pilkkaansa kantaen;'),
(1699185,58,58,13,14,'sillä ei meillä ole täällä pysyväistä kaupunkia, vaan tulevaista me etsimme.'),
(1699186,58,58,13,15,'Uhratkaamme siis hänen kauttansa Jumalalle joka aika kiitosuhria, se on: niiden huulten hedelmää, jotka hänen nimeänsä ylistävät.'),
(1699187,58,58,13,16,'Mutta älkää unhottako tehdä hyvää ja jakaa omastanne, sillä senkaltaisiin uhreihin Jumala mielistyy.'),
(1699188,58,58,13,17,'Olkaa kuuliaiset johtajillenne ja tottelevaiset, sillä he valvovat teidän sielujanne niinkuin ne, joiden on tehtävä tili, että he voisivat tehdä sitä ilolla eikä huokaillen; sillä se ei ole teille hyödyllistä.'),
(1699189,58,58,13,18,'Rukoilkaa meidän edestämme; sillä me tiedämme, että meillä on hyvä omatunto, koska tahdomme kaikessa hyvin vaeltaa.'),
(1699190,58,58,13,19,'Vielä hartaammin kehoitan teitä näin tekemään, että minut sitä pikemmin annettaisiin teille takaisin.'),
(1699191,58,58,13,20,'Mutta rauhan Jumala, joka on kuolleista nostanut hänet, joka iankaikkisen liiton veren kautta on se suuri lammasten paimen, meidän Herramme Jeesuksen,'),
(1699192,58,58,13,21,'hän tehköön teidät kykeneviksi kaikkeen hyvään, voidaksenne toteuttaa hänen tahtonsa, ja vaikuttakoon teissä sen, mikä on hänelle otollista, Jeesuksen Kristuksen kautta; hänelle kunnia aina ja iankaikkisesti! Amen.'),
(1699193,58,58,13,22,'Minä pyydän teitä, veljet: kestäkää tämä kehoituksen sana; sillä lyhykäisesti minä olen teille kirjoittanut.'),
(1699194,58,58,13,23,'Tietäkää, että veljemme Timoteus on päästetty vapaaksi; ja jos hän pian tulee, saan minä hänen kanssaan nähdä teidät.'),
(1699195,58,58,13,24,'Sanokaa tervehdys kaikille johtajillenne ja kaikille pyhille. Tervehdyksen lähettävät teille ne, jotka ovat Italiasta.'),
(1699196,58,58,13,25,'Armo olkoon kaikkien teidän kanssanne.'),
(1699197,58,59,1,1,'Jaakob, Jumalan ja Herran Jeesuksen Kristuksen palvelija, lähettää tervehdyksen kahdelletoista hajalla asuvalle sukukunnalle.'),
(1699198,58,59,1,2,'Veljeni, pitäkää pelkkänä ilona, kun joudutte moninaisiin kiusauksiin,'),
(1699199,58,59,1,3,'tietäen, että teidän uskonne kestäväisyys koetuksissa saa aikaan kärsivällisyyttä.'),
(1699200,58,59,1,4,'Ja kärsivällisyys tuottakoon täydellisen teon, että te olisitte täydelliset ja eheät ettekä missään puuttuvaiset.'),
(1699201,58,59,1,5,'Mutta jos joltakin teistä puuttuu viisautta, anokoon sitä Jumalalta, joka antaa kaikille alttiisti ja soimaamatta, niin se hänelle annetaan.'),
(1699202,58,59,1,6,'Mutta anokoon uskossa, ollenkaan epäilemättä; sillä joka epäilee, on meren aallon kaltainen, jota tuuli ajaa ja heittelee.'),
(1699203,58,59,1,7,'Älköön sellainen ihminen luulko Herralta mitään saavansa,'),
(1699204,58,59,1,8,'kaksimielinen mies, epävakainen kaikilla teillään.'),
(1699205,58,59,1,9,'Alhainen veli kerskatkoon ylhäisyydestään,'),
(1699206,58,59,1,10,'mutta rikas alhaisuudestaan, sillä hän on katoava niinkuin ruohon kukka.'),
(1699207,58,59,1,11,'Aurinko nousee helteineen ja kuivaa ruohon, ja sen kukka varisee, ja sen muodon sulous häviää; niin on rikaskin lakastuva retkillänsä.'),
(1699208,58,59,1,12,'Autuas se mies, joka kiusauksen kestää, sillä kun hänet on koeteltu, on hän saava elämän kruunun, jonka Herra on luvannut niille, jotka häntä rakastavat!'),
(1699209,58,59,1,13,'Älköön kukaan, kiusauksessa ollessaan, sanoko: "Jumala minua kiusaa"; sillä Jumala ei ole pahan kiusattavissa, eikä hän ketään kiusaa.'),
(1699210,58,59,1,14,'Vaan jokaista kiusaa hänen oma himonsa, joka häntä vetää ja houkuttelee;'),
(1699211,58,59,1,15,'kun sitten himo on tullut raskaaksi, synnyttää se synnin, mutta kun synti on täytetty, synnyttää se kuoleman.'),
(1699212,58,59,1,16,'Älkää eksykö, rakkaat veljeni.'),
(1699213,58,59,1,17,'Jokainen hyvä anti ja jokainen täydellinen lahja tulee ylhäältä, valkeuksien Isältä, jonka tykönä ei ole muutosta, ei vaihteen varjoa.'),
(1699214,58,59,1,18,'Tahtonsa mukaan hän synnytti meidät totuuden sanalla, ollaksemme hänen luotujensa esikoiset.'),
(1699215,58,59,1,19,'Te tiedätte sen, rakkaat veljeni. Mutta olkoon jokainen ihminen nopea kuulemaan, hidas puhumaan, hidas vihaan;'),
(1699216,58,59,1,20,'sillä miehen viha ei tee sitä, mikä on oikein Jumalan edessä.'),
(1699217,58,59,1,21,'Sentähden pankaa pois kaikki saastaisuus ja kaikkinainen pahuus ja ottakaa hiljaisuudella vastaan sana, joka on teihin istutettu ja joka voi teidän sielunne pelastaa.'),
(1699218,58,59,1,22,'Mutta olkaa sanan tekijöitä, eikä vain sen kuulijoita, pettäen itsenne.'),
(1699219,58,59,1,23,'Sillä jos joku on sanan kuulija eikä sen tekijä, niin hän on miehen kaltainen, joka katselee kuvastimessa luonnollisia kasvojaan;'),
(1699220,58,59,1,24,'hän katselee itseään, lähtee pois ja unhottaa heti, millainen hän oli.'),
(1699221,58,59,1,25,'Mutta joka katsoo täydelliseen lakiin, vapauden lakiin, ja pysyy siinä, eikä ole muistamaton kuulija, vaan todellinen tekijä, hän on oleva autuas tekemisessään.'),
(1699222,58,59,1,26,'Jos joku luulee olevansa jumalanpalvelija, mutta ei hillitse kieltään, vaan pettää sydämensä, niin hänen jumalanpalveluksensa on turha.'),
(1699223,58,59,1,27,'Puhdas ja tahraton jumalanpalvelus Jumalan ja Isän silmissä on käydä katsomassa orpoja ja leskiä heidän ahdistuksessaan ja varjella itsensä niin, ettei maailma saastuta.'),
(1699224,58,59,2,1,'Veljeni, älköön teidän uskonne meidän kirkastettuun Herraamme, Jeesukseen Kristukseen, olko sellainen, joka katsoo henkilöön.'),
(1699225,58,59,2,2,'Sillä jos kokoukseenne tulee mies, kultasormus sormessa ja loistavassa puvussa, ja tulee myös köyhä ryysyissä,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699226,58,59,2,3,'ja te katsotte loistavapukuisen puoleen ja sanotte: "Istu sinä tähän mukavasti", ja köyhälle sanotte: "Seiso sinä tuossa", tahi: "Istu tähän jalkajakkarani viereen",'),
(1699227,58,59,2,4,'niin ettekö ole joutuneet ristiriitaan itsenne kanssa, ja eikö teistä ole tullut väärämielisiä tuomareita?'),
(1699228,58,59,2,5,'Kuulkaa, rakkaat veljeni. Eikö Jumala ole valinnut niitä, jotka maailman silmissä ovat köyhiä, olemaan rikkaita uskossa ja sen valtakunnan perillisiä, jonka hän on luvannut niille, jotka häntä rakastavat?'),
(1699229,58,59,2,6,'Mutta te olette häväisseet köyhän. Eivätkö juuri rikkaat teitä sorra, ja eivätkö juuri he vedä teitä tuomioistuimien eteen?'),
(1699230,58,59,2,7,'Eivätkö juuri he pilkkaa sitä jaloa nimeä, joka on lausuttu teidän ylitsenne?'),
(1699231,58,59,2,8,'Vaan jos täytätte kuninkaallisen lain Raamatun mukaan: "Rakasta lähimmäistäsi niinkuin itseäsi", niin te hyvin teette;'),
(1699232,58,59,2,9,'mutta jos te henkilöön katsotte, niin teette syntiä, ja laki näyttää teille, että olette lainrikkojia.'),
(1699233,58,59,2,10,'Sillä joka pitää koko lain, mutta rikkoo yhtä kohtaa vastaan, se on syypää kaikissa kohdin.'),
(1699234,58,59,2,11,'Sillä hän, joka on sanonut: "Älä tee huorin", on myös sanonut: "Älä tapa"; jos et teekään huorin, mutta tapat, olet lainrikkoja.'),
(1699235,58,59,2,12,'Puhukaa niin ja tehkää niin kuin ne, jotka vapauden laki on tuomitseva.'),
(1699236,58,59,2,13,'Sillä tuomio on laupeudeton sille, joka ei ole laupeutta tehnyt; laupeudelle tuomio koituu kerskaukseksi.'),
(1699237,58,59,2,14,'Mitä hyötyä, veljeni, siitä on, jos joku sanoo itsellään olevan uskon, mutta hänellä ei ole tekoja? Ei kaiketi usko voi häntä pelastaa?'),
(1699238,58,59,2,15,'Jos veli tai sisar on alaston ja jokapäiväistä ravintoa vailla'),
(1699239,58,59,2,16,'ja joku teistä sanoo heille: "Menkää rauhassa, lämmitelkää ja ravitkaa itsenne", mutta ette anna heille ruumiin tarpeita, niin mitä hyötyä siitä on?'),
(1699240,58,59,2,17,'Samoin uskokin, jos sillä ei ole tekoja, on itsessään kuollut.'),
(1699241,58,59,2,18,'Joku ehkä sanoo: "Sinulla on usko, ja minulla on teot"; näytä sinä minulle uskosi ilman tekoja, niin minä teoistani näytän sinulle uskon.'),
(1699242,58,59,2,19,'Sinä uskot, että Jumala on yksi. Siinä teet oikein; riivaajatkin sen uskovat ja vapisevat.'),
(1699243,58,59,2,20,'Mutta tahdotko tietää, sinä turha ihminen, että usko ilman tekoja on voimaton?'),
(1699244,58,59,2,21,'Eikö Aabraham, meidän isämme, tullut vanhurskaaksi teoista, kun vei poikansa Iisakin uhrialttarille?'),
(1699245,58,59,2,22,'Sinä näet, että usko vaikutti hänen tekojensa mukana, ja teoista usko tuli täydelliseksi;'),
(1699246,58,59,2,23,'ja niin toteutui Raamatun sana: "Aabraham uskoi Jumalaa, ja se luettiin hänelle vanhurskaudeksi", ja häntä sanottiin Jumalan ystäväksi.'),
(1699247,58,59,2,24,'Te näette, että ihminen tulee vanhurskaaksi teoista eikä ainoastaan uskosta.'),
(1699248,58,59,2,25,'Eikö samoin myös portto Raahab tullut vanhurskaaksi teoista, kun hän otti lähettiläät luokseen ja päästi heidät toista tietä pois?'),
(1699249,58,59,2,26,'Sillä niinkuin ruumis ilman henkeä on kuollut, niin myös usko ilman tekoja on kuollut.'),
(1699250,58,59,3,1,'Veljeni, älkööt aivan monet teistä pyrkikö opettajiksi, sillä te tiedätte, että me saamme sitä kovemman tuomion.'),
(1699251,58,59,3,2,'Sillä monessa kohden me kaikki hairahdumme. Jos joku ei hairahdu puheessa, niin hän on täydellinen mies ja kykenee hillitsemään myös koko ruumiinsa.'),
(1699252,58,59,3,3,'Kun panemme suitset hevosten suuhun, että ne meitä tottelisivat, niin voimme ohjata niiden koko ruumiin.'),
(1699253,58,59,3,4,'Katso, laivatkin, vaikka ovat niin suuria ja tuimain tuulten kuljetettavia, ohjataan varsin pienellä peräsimellä, minne perämiehen mieli tekee.'),
(1699254,58,59,3,5,'Samoin myös kieli on pieni jäsen ja voi kuitenkin kerskata suurista asioista. Katso, kuinka pieni tuli, ja kuinka suuren metsän se sytyttää!'),
(1699255,58,59,3,6,'Myös kieli on tuli, on vääryyden maailma; kieli on se meidän jäsenistämme, joka tahraa koko ruumiin, sytyttää tuleen elämän pyörän, itse syttyen helvetistä.'),
(1699256,58,59,3,7,'Sillä kaiken luonnon, sekä petojen että lintujen, sekä matelijain että merieläinten luonnon, voi ihmisluonto kesyttää ja onkin kesyttänyt;'),
(1699257,58,59,3,8,'mutta kieltä ei kukaan ihminen voi kesyttää; se on levoton ja paha, täynnä kuolettavaa myrkkyä.'),
(1699258,58,59,3,9,'Kielellä me kiitämme Herraa ja Isää, ja sillä me kiroamme ihmisiä, Jumalan kaltaisiksi luotuja;'),
(1699259,58,59,3,10,'samasta suusta lähtee kiitos ja kirous. Näin ei saa olla, veljeni.'),
(1699260,58,59,3,11,'Uhkuuko lähde samasta silmästä makeaa ja karvasta vettä?'),
(1699261,58,59,3,12,'Eihän, veljeni, viikunapuu voi tuottaa öljymarjoja eikä viinipuu viikunoita? Eikä myöskään suolainen lähde voi antaa makeata vettä.'),
(1699262,58,59,3,13,'Kuka on viisas ja ymmärtäväinen teidän joukossanne? Tuokoon hän näkyviin tekonsa hyvällä vaelluksellaan viisauden sävyisyydessä.'),
(1699263,58,59,3,14,'Mutta jos teillä on katkera kiivaus ja riitaisuus sydämessänne, niin älkää kerskatko älkääkä valhetelko totuutta vastaan.'),
(1699264,58,59,3,15,'Tämä ei ole se viisaus, joka ylhäältä tulee, vaan se on maallista, sielullista, riivaajien viisautta.'),
(1699265,58,59,3,16,'Sillä missä kiivaus ja riitaisuus on, siellä on epäjärjestys ja kaikkinainen paha meno.'),
(1699266,58,59,3,17,'Mutta ylhäältä tuleva viisaus on ensiksikin puhdas, sitten rauhaisa, lempeä, taipuisa, täynnä laupeutta ja hyviä hedelmiä, se ei epäile, ei teeskentele.'),
(1699267,58,59,3,18,'Vanhurskauden hedelmä kylvetään rauhassa rauhan tekijöille.'),
(1699268,58,59,4,1,'Mistä tulevat taistelut ja mistä riidat teidän keskuudessanne? Eikö teidän himoistanne, jotka sotivat jäsenissänne?'),
(1699269,58,59,4,2,'Te himoitsette, eikä teillä kuitenkaan ole; te tapatte ja kiivailette, ettekä voi saavuttaa; te riitelette ja taistelette. Teillä ei ole, sentähden ettette ano.'),
(1699270,58,59,4,3,'Te anotte, ettekä saa, sentähden että anotte kelvottomasti, kuluttaaksenne sen himoissanne.'),
(1699271,58,59,4,4,'Te avionrikkojat, ettekö tiedä, että maailman ystävyys on vihollisuutta Jumalaa vastaan? Joka siis tahtoo olla maailman ystävä, siitä tulee Jumalan vihollinen.'),
(1699272,58,59,4,5,'Vai luuletteko, että Raamattu turhaan sanoo: "Kateuteen asti hän halajaa henkeä, jonka hän on pannut meihin asumaan"?'),
(1699273,58,59,4,6,'Mutta hän antaa sitä suuremman armon. Sentähden sanotaan: "Jumala on ylpeitä vastaan, mutta nöyrille hän antaa armon".'),
(1699274,58,59,4,7,'Olkaa siis Jumalalle alamaiset; mutta vastustakaa perkelettä, niin se teistä pakenee.'),
(1699275,58,59,4,8,'Lähestykää Jumalaa, niin hän lähestyy teitä. Puhdistakaa kätenne, te syntiset, ja tehkää sydämenne puhtaiksi, te kaksimieliset.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699276,58,59,4,9,'Tuntekaa kurjuutenne ja murehtikaa ja itkekää; naurunne muuttukoon murheeksi ja ilonne suruksi.'),
(1699277,58,59,4,10,'Nöyrtykää Herran edessä, niin hän teidät korottaa.'),
(1699278,58,59,4,11,'Älkää panetelko toisianne, veljet. Joka veljeään panettelee tai veljensä tuomitsee, se panettelee lakia ja tuomitsee lain; mutta jos sinä tuomitset lain, niin et ole lain noudattaja, vaan sen tuomari.'),
(1699279,58,59,4,12,'Yksi on lainsäätäjä ja tuomari, hän, joka voi pelastaa ja hukuttaa; mutta kuka olet sinä, joka tuomitset lähimmäisesi?'),
(1699280,58,59,4,13,'Kuulkaa nyt, te, jotka sanotte: "Tänään tai huomenna lähdemme siihen ja siihen kaupunkiin ja viivymme siellä vuoden ja teemme kauppaa ja saamme voittoa" -'),
(1699281,58,59,4,14,'te, jotka ette tiedä, mitä huomenna tapahtuu; sillä mikä on teidän elämänne? Savu te olette, joka hetkisen näkyy ja sitten haihtuu -'),
(1699282,58,59,4,15,'sen sijaan, että teidän tulisi sanoa: "Jos Herra tahtoo ja me elämme, niin teemme tämän tai tuon".'),
(1699283,58,59,4,16,'Mutta nyt te kerskaatte ylvästelyssänne. Kaikki sellainen kerskaaminen on paha.'),
(1699284,58,59,4,17,'Joka siis ymmärtää tehdä sitä, mikä hyvää on, eikä tee, hänelle se on synniksi.'),
(1699285,58,59,5,1,'Kuulkaa nyt, te rikkaat: itkekää ja vaikeroikaa sitä kurjuutta, joka on teille tulossa.'),
(1699286,58,59,5,2,'Teidän rikkautenne on mädännyt, ja teidän vaatteenne ovat koin syömät;'),
(1699287,58,59,5,3,'teidän kultanne ja hopeanne on ruostunut, ja niiden ruoste on oleva todistuksena teitä vastaan ja syövä teidän lihanne niinkuin tuli. Te olette koonneet aarteita viimeisinä päivinä.'),
(1699288,58,59,5,4,'Katso, työmiesten palkka, jonka te vainioittenne niittäjiltä olette pidättäneet, huutaa, ja leikkuumiesten valitukset ovat tulleet Herran Sebaotin korviin.'),
(1699289,58,59,5,5,'Te olette herkutelleet maan päällä ja hekumoineet, te olette sydäntänne syötelleet teurastuspäivänä.'),
(1699290,58,59,5,6,'Vanhurskaan te olette tuominneet ja tappaneet; hän ei vastusta teitä.'),
(1699291,58,59,5,7,'Niin olkaa kärsivällisiä, veljet, Herran tulemukseen asti. Katso, peltomies odottaa maan kallista hedelmää, kärsivällisesti sitä vartoen, kunnes saa syksyisen sateen ja keväisen.'),
(1699292,58,59,5,8,'Olkaa tekin kärsivällisiä, vahvistakaa sydämenne, sillä Herran tulemus on lähellä.'),
(1699293,58,59,5,9,'Älkää huokailko, veljet, toisianne vastaan, ettei teitä tuomittaisi; katso, tuomari seisoo ovella.'),
(1699294,58,59,5,10,'Ottakaa, veljet, vaivankestämisen ja kärsivällisyyden esikuvaksi profeetat, jotka ovat puhuneet Herran nimessä.'),
(1699295,58,59,5,11,'Katso, me ylistämme autuaiksi niitä, jotka ovat kestäneet; Jobin kärsivällisyyden te olette kuulleet, ja lopun, jonka Herra antaa, te olette nähneet. Sillä Herra on laupias ja armahtavainen.'),
(1699296,58,59,5,12,'Mutta ennen kaikkea, veljeni, älkää vannoko, älkää taivaan kautta älkääkä maan, älkää mitään muutakaan valaa; vaan "on" olkoon teillä "on", ja "ei" olkoon teillä "ei", ettette joutuisi tuomion alle.'),
(1699297,58,59,5,13,'Jos joku teistä kärsii vaivaa, niin rukoilkoon; jos joku on hyvillä mielin, veisatkoon kiitosta.'),
(1699298,58,59,5,14,'Jos joku teistä sairastaa, kutsukoon tykönsä seurakunnan vanhimmat, ja he rukoilkoot hänen edestään, voidellen häntä öljyllä Herran nimessä.'),
(1699299,58,59,5,15,'Ja uskon rukous pelastaa sairaan, ja Herra antaa hänen nousta jälleen; ja jos hän on syntejä tehnyt, niin ne annetaan hänelle anteeksi.'),
(1699300,58,59,5,16,'Tunnustakaa siis toisillenne syntinne ja rukoilkaa toistenne puolesta, että te parantuisitte; vanhurskaan rukous voi paljon, kun se on harras.'),
(1699301,58,59,5,17,'Elias oli ihminen, yhtä vajavainen kuin mekin, ja hän rukoili rukoilemalla, ettei sataisi; eikä satanut maan päällä kolmeen vuoteen ja kuuteen kuukauteen.'),
(1699302,58,59,5,18,'Ja hän rukoili uudestaan, ja taivas antoi sateen, ja maa kasvoi hedelmänsä.'),
(1699303,58,59,5,19,'Veljeni, jos joku teistä eksyy totuudesta ja hänet joku palauttaa,'),
(1699304,58,59,5,20,'niin tietäkää, että joka palauttaa syntisen hänen eksymyksensä tieltä, se pelastaa hänen sielunsa kuolemasta ja peittää syntien paljouden.'),
(1699305,58,60,1,1,'Pietari, Jeesuksen Kristuksen apostoli, valituille muukalaisille, jotka asuvat hajallaan Pontossa, Galatiassa, Kappadokiassa, Aasiassa ja Bityniassa,'),
(1699306,58,60,1,2,'ja jotka Isän Jumalan edeltätietämisen mukaan ovat Hengen pyhittämisen kautta valitut Jeesuksen Kristuksen kuuliaisuuteen ja hänen verellänsä vihmottaviksi. Lisääntyköön teille armo ja rauha.'),
(1699307,58,60,1,3,'Ylistetty olkoon meidän Herramme Jeesuksen Kristuksen Jumala ja Isä, joka suuren laupeutensa mukaan on uudestisynnyttänyt meidät elävään toivoon Jeesuksen Kristuksen kuolleistanousemisen kautta,'),
(1699308,58,60,1,4,'turmeltumattomaan ja saastumattomaan ja katoamattomaan perintöön, joka taivaissa on säilytettynä teitä varten,'),
(1699309,58,60,1,5,'jotka Jumalan voimasta uskon kautta varjellutte pelastukseen, joka on valmis ilmoitettavaksi viimeisenä aikana.'),
(1699310,58,60,1,6,'Sentähden te riemuitsette, vaikka te nyt, jos se on tarpeellista, vähän aikaa kärsittekin murhetta moninaisissa kiusauksissa,'),
(1699311,58,60,1,7,'että teidän uskonne kestäväisyys koetuksissa havaittaisiin paljoa kallisarvoisemmaksi kuin katoava kulta, joka kuitenkin tulessa koetellaan, ja koituisi kiitokseksi, ylistykseksi ja kunniaksi Jeesuksen Kristuksen ilmestyessä.'),
(1699312,58,60,1,8,'Häntä te rakastatte, vaikka ette ole häntä nähneet, häneen te uskotte, vaikka ette nyt häntä näe, ja riemuitsette sanomattomalla ja kirkastuneella ilolla,'),
(1699313,58,60,1,9,'sillä te saavutatte uskon päämäärän, sielujen pelastuksen.'),
(1699314,58,60,1,10,'Sitä pelastusta ovat etsineet ja tutkineet profeetat, jotka ovat ennustaneet teidän osaksenne tulevasta armosta,'),
(1699315,58,60,1,11,'ovat tutkineet, mihin tai millaiseen aikaan heissä oleva Kristuksen Henki viittasi, edeltäpäin todistaessaan Kristusta kohtaavista kärsimyksistä ja niiden jälkeen tulevasta kunniasta.'),
(1699316,58,60,1,12,'Ja heille, koska he eivät palvelleet itseänsä, vaan teitä, ilmoitettiin se, mikä nyt on teille julistettu niiden kautta, jotka taivaasta lähetetyssä Pyhässä Hengessä ovat teille evankeliumia julistaneet; ja siihen enkelitkin halajavat katsahtaa.'),
(1699317,58,60,1,13,'Vyöttäkää sentähden mielenne kupeet ja olkaa raittiit; ja pankaa täysi toivonne siihen armoon, joka teille tarjotaan Jeesuksen Kristuksen ilmestymisessä.'),
(1699318,58,60,1,14,'Niinkuin kuuliaisten lasten tulee, älkää mukautuko niiden himojen mukaan, joissa te ennen, tietämättömyytenne aikana, elitte,'),
(1699319,58,60,1,15,'vaan sen Pyhän mukaan, joka on teidät kutsunut, tulkaa tekin kaikessa vaelluksessanne pyhiksi.'),
(1699320,58,60,1,16,'Sillä kirjoitettu on: "Olkaa pyhät, sillä minä olen pyhä".'),
(1699321,58,60,1,17,'Ja jos te Isänänne huudatte avuksi häntä, joka henkilöön katsomatta tuomitsee kunkin hänen tekojensa mukaan, niin vaeltakaa pelossa tämä muukalaisuutenne aika,'),
(1699322,58,60,1,18,'tietäen, ettette ole millään katoavaisella, ette hopealla ettekä kullalla, lunastetut turhasta, isiltä peritystä vaelluksestanne,'),
(1699323,58,60,1,19,'vaan Kristuksen kalliilla verellä, niinkuin virheettömän ja tahrattoman karitsan,'),
(1699324,58,60,1,20,'hänen, joka tosin oli edeltätiedetty jo ennen maailman perustamista, mutta vasta viimeisinä aikoina on ilmoitettu teitä varten,'),
(1699325,58,60,1,21,'jotka hänen kauttansa uskotte Jumalaan, joka herätti hänet kuolleista ja antoi hänelle kirkkauden, niin että teidän uskonne on myös toivo Jumalaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699326,58,60,1,22,'Puhdistakaa sielunne totuuden kuuliaisuudessa vilpittömään veljenrakkauteen ja rakastakaa toisianne hartaasti puhtaasta sydämestä,'),
(1699327,58,60,1,23,'te, jotka olette uudestisyntyneet, ette katoavasta, vaan katoamattomasta siemenestä, Jumalan elävän ja pysyvän sanan kautta.'),
(1699328,58,60,1,24,'Sillä: "kaikki liha on kuin ruoho, ja kaikki sen kauneus kuin ruohon kukkanen; ruoho kuivuu, ja kukkanen varisee,'),
(1699329,58,60,1,25,'mutta Herran sana pysyy iankaikkisesti". Ja tämä on se sana, joka on teille ilosanomana julistettu.'),
(1699330,58,60,2,1,'Pankaa siis pois kaikki pahuus ja kaikki vilppi ja ulkokultaisuus ja kateus ja kaikki panettelu,'),
(1699331,58,60,2,2,'ja halatkaa niinkuin vastasyntyneet lapset sanan väärentämätöntä maitoa, että te sen kautta kasvaisitte pelastukseen,'),
(1699332,58,60,2,3,'jos "olette maistaneet, että Herra on hyvä".'),
(1699333,58,60,2,4,'Ja tulkaa hänen tykönsä, elävän kiven tykö, jonka ihmiset tosin ovat hyljänneet, mutta joka Jumalan edessä on valittu, kallis,'),
(1699334,58,60,2,5,'ja rakentukaa itsekin elävinä kivinä hengelliseksi huoneeksi, pyhäksi papistoksi, uhraamaan hengellisiä uhreja, jotka Jeesuksen Kristuksen kautta ovat Jumalalle mieluisia.'),
(1699335,58,60,2,6,'Sillä Raamatussa sanotaan: "Katso, minä lasken Siioniin valitun kiven, kalliin kulmakiven; ja joka häneen uskoo, ei ole häpeään joutuva".'),
(1699336,58,60,2,7,'Teille siis, jotka uskotte, se on kallis, mutta niille, jotka eivät usko, "on se kivi, jonka rakentajat hylkäsivät, tullut kulmakiveksi"'),
(1699337,58,60,2,8,'ja "kompastuskiveksi ja loukkauskallioksi". Koska he eivät tottele sanaa, niin he kompastuvat; ja siihen heidät on pantukin.'),
(1699338,58,60,2,9,'Mutta te olette "valittu suku, kuninkaallinen papisto, pyhä heimo, omaisuuskansa, julistaaksenne sen jaloja tekoja", joka on pimeydestä kutsunut teidät ihmeelliseen valkeuteensa;'),
(1699339,58,60,2,10,'te, jotka ennen "ette olleet kansa", mutta nyt olette "Jumalan kansa", jotka ennen "ette olleet armahdetut", mutta nyt "olette armahdetut".'),
(1699340,58,60,2,11,'Rakkaani, niinkuin outoja ja muukalaisia minä kehoitan teitä pidättymään lihallisista himoista, jotka sotivat sielua vastaan,'),
(1699341,58,60,2,12,'ja vaeltamaan nuhteettomasti pakanain keskuudessa, että he siitä, mistä he parjaavat teitä niinkuin pahantekijöitä, teidän hyvien tekojenne tähden, niitä tarkatessaan, ylistäisivät Jumalaa etsikkopäivänä.'),
(1699342,58,60,2,13,'Olkaa alamaiset kaikelle inhimilliselle järjestykselle Herran tähden, niin hyvin kuninkaalle, joka on ylin,'),
(1699343,58,60,2,14,'kuin käskynhaltijoille, jotka hän on lähettänyt pahaa tekeville rangaistukseksi, mutta hyvää tekeville kiitokseksi;'),
(1699344,58,60,2,15,'sillä se on Jumalan tahto, että te hyvää tekemällä tukitte suun mielettömäin ihmisten ymmärtämättömyydeltä -'),
(1699345,58,60,2,16,'niinkuin vapaat, ei niinkuin ne, joilla vapaus on pahuuden verhona, vaan niinkuin Jumalan palvelijat.'),
(1699346,58,60,2,17,'Kunnioittakaa kaikkia, rakastakaa veljiä, peljätkää Jumalaa, kunnioittakaa kuningasta.'),
(1699347,58,60,2,18,'Palvelijat, olkaa kaikella pelolla isännillenne alamaiset, ei ainoastaan hyville ja lempeille, vaan nurjillekin.'),
(1699348,58,60,2,19,'Sillä se on armoa, että joku omantunnon tähden Jumalan edessä kestää vaivoja, syyttömästi kärsien.'),
(1699349,58,60,2,20,'Sillä mitä kiitettävää siinä on, jos te olette kärsivällisiä silloin, kun teitä syntienne tähden piestään? Mutta jos olette kärsivällisiä, kun hyvien tekojenne tähden saatte kärsiä, niin se on Jumalan armoa.'),
(1699350,58,60,2,21,'Sillä siihen te olette kutsutut, koska Kristuskin kärsi teidän puolestanne, jättäen teille esikuvan, että te noudattaisitte hänen jälkiänsä,'),
(1699351,58,60,2,22,'joka "ei syntiä tehnyt ja jonka suussa ei petosta ollut",'),
(1699352,58,60,2,23,'joka häntä herjattaessa ei herjannut takaisin, joka kärsiessään ei uhannut, vaan jätti asiansa sen haltuun, joka oikein tuomitsee,'),
(1699353,58,60,2,24,'joka "itse kantoi meidän syntimme" ruumiissansa ristinpuuhun, että me, synneistä pois kuolleina, eläisimme vanhurskaudelle; ja hänen "haavainsa kautta te olette paratut".'),
(1699354,58,60,2,25,'Sillä te olitte "eksyksissä niinkuin lampaat", mutta nyt te olette palanneet sielujenne paimenen ja kaitsijan tykö.'),
(1699355,58,60,3,1,'Samoin te, vaimot, olkaa alamaiset miehillenne, että nekin, jotka ehkä eivät ole sanalle kuuliaisia, vaimojen vaelluksen kautta sanoittakin voitettaisiin,'),
(1699356,58,60,3,2,'kun he katselevat, kuinka te vaellatte puhtaina ja pelossa.'),
(1699357,58,60,3,3,'Älköön teidän kaunistuksenne olko ulkonaista, ei hiusten palmikoimista eikä kultien ympärillenne ripustamista eikä koreihin vaatteisiin pukeutumista,'),
(1699358,58,60,3,4,'vaan se olkoon salassa oleva sydämen ihminen, hiljaisen ja rauhaisan hengen katoamattomuudessa; tämä on Jumalan silmissä kallis.'),
(1699359,58,60,3,5,'Sillä näin myös muinoin pyhät vaimot, jotka panivat toivonsa Jumalaan, kaunistivat itsensä ja olivat miehillensä alamaiset;'),
(1699360,58,60,3,6,'niin oli Saara kuuliainen Aabrahamille, kutsuen häntä herraksi; ja hänen lapsikseen te olette tulleet, kun teette sitä, mikä hyvää on, ettekä anna minkään itseänne peljättää.'),
(1699361,58,60,3,7,'Samoin te, miehet, eläkää taidollisesti kukin vaimonne kanssa, niinkuin heikomman astian kanssa, ja osoittakaa heille kunnioitusta, koska he ovat elämän armon perillisiä niinkuin tekin; etteivät teidän rukouksenne estyisi.'),
(1699362,58,60,3,8,'Ja lopuksi: olkaa kaikki yksimielisiä, helläsydämisiä, veljiä kohtaan rakkaita, armahtavaisia, nöyriä.'),
(1699363,58,60,3,9,'Älkää kostako pahaa pahalla, älkää herjausta herjauksella, vaan päinvastoin siunatkaa; sillä siihen te olette kutsututkin, että siunauksen perisitte.'),
(1699364,58,60,3,10,'Sillä: "joka tahtoo rakastaa elämää ja nähdä hyviä päiviä, varjelkoon kielensä pahasta ja huulensa vilppiä puhumasta,'),
(1699365,58,60,3,11,'kääntyköön pois pahasta ja tehköön hyvää, etsiköön rauhaa ja pyrkiköön siihen.'),
(1699366,58,60,3,12,'Sillä Herran silmät tarkkaavat vanhurskaita ja hänen korvansa heidän rukouksiansa, mutta Herran kasvot ovat pahantekijöitä vastaan."'),
(1699367,58,60,3,13,'Ja kuka on, joka voi teitä vahingoittaa, jos teillä on kiivaus hyvään?'),
(1699368,58,60,3,14,'Vaan vaikka saisittekin kärsiä vanhurskauden tähden, olette kuitenkin autuaita. "Mutta älkää antako heidän pelkonsa peljättää itseänne, älkääkä hämmästykö",'),
(1699369,58,60,3,15,'vaan pyhittäkää Herra Kristus sydämissänne ja olkaa aina valmiit vastaamaan jokaiselle, joka teiltä kysyy sen toivon perustusta, joka teissä on, kuitenkin sävyisyydellä ja pelolla,'),
(1699370,58,60,3,16,'pitäen hyvän omantunnon, että ne, jotka parjaavat teidän hyvää vaellustanne Kristuksessa, joutuisivat häpeään siinä, mistä he teitä panettelevat.'),
(1699371,58,60,3,17,'Sillä parempi on hyvää tehden kärsiä, jos niin on Jumalan tahto, kuin pahaa tehden.'),
(1699372,58,60,3,18,'Sillä myös Kristus kärsi kerran kuoleman syntien tähden, vanhurskas vääräin puolesta, johdattaaksensa meidät Jumalan tykö; hän, joka tosin kuoletettiin lihassa, mutta tehtiin eläväksi hengessä,'),
(1699373,58,60,3,19,'jossa hän myös meni pois ja saarnasi vankeudessa oleville hengille,'),
(1699374,58,60,3,20,'jotka muinoin eivät olleet kuuliaiset, kun Jumalan pitkämielisyys odotti Nooan päivinä, silloin kun valmistettiin arkkia, jossa vain muutamat, se on kahdeksan sielua, pelastuivat veden kautta.'),
(1699375,58,60,3,21,'Tämän vertauskuvan mukaan vesi nyt teidätkin pelastaa, kasteena - joka ei ole lihan saastan poistamista, vaan hyvän omantunnon pyytämistä Jumalalta - Jeesuksen Kristuksen ylösnousemuksen kautta,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699376,58,60,3,22,'hänen, joka on mennyt taivaaseen ja on Jumalan oikealla puolella; ja hänen allensa ovat enkelit ja vallat ja voimat alistetut.'),
(1699377,58,60,4,1,'Koska siis Kristus on kärsinyt lihassa, niin ottakaa tekin aseeksenne sama mieli - sillä joka lihassa kärsii, se lakkaa synnistä -'),
(1699378,58,60,4,2,'ettette enää eläisi tätä lihassa vielä elettävää aikaa ihmisten himojen mukaan, vaan Jumalan tahdon mukaan.'),
(1699379,58,60,4,3,'Riittäähän, että menneen ajan olette täyttäneet pakanain tahtoa vaeltaessanne irstaudessa, himoissa, juoppoudessa, mässäyksissä, juomingeissa ja kauheassa epäjumalain palvelemisessa.'),
(1699380,58,60,4,4,'Sentähden he oudoksuvat sitä, ettette juokse heidän mukanansa samaan riettauden lätäkköön, ja herjaavat.'),
(1699381,58,60,4,5,'Mutta heidän on tehtävä tili hänelle, joka on valmis tuomitsemaan eläviä ja kuolleita.'),
(1699382,58,60,4,6,'Sillä sitä varten kuolleillekin on julistettu evankeliumi, että he tosin olisivat tuomitut lihassa niinkuin ihmiset, mutta että heillä hengessä olisi elämä, niinkuin Jumala elää.'),
(1699383,58,60,4,7,'Mutta kaiken loppu on lähellä. Sentähden olkaa maltilliset ja raittiit rukoilemaan.'),
(1699384,58,60,4,8,'Ennen kaikkea olkoon teidän rakkautenne toisianne kohtaan harras, sillä "rakkaus peittää syntien paljouden".'),
(1699385,58,60,4,9,'Olkaa vieraanvaraisia toinen toistanne kohtaan, nurkumatta.'),
(1699386,58,60,4,10,'Palvelkaa toisianne, kukin sillä armolahjalla, minkä on saanut, Jumalan moninaisen armon hyvinä huoneenhaltijoina.'),
(1699387,58,60,4,11,'Jos joku puhuu, puhukoon niinkuin Jumalan sanoja; jos joku palvelee, palvelkoon sen voiman mukaan, minkä Jumala antaa, että Jumala tulisi kaikessa kirkastetuksi Jeesuksen Kristuksen kautta. Hänen on kunnia ja valta aina ja iankaikkisesti. Amen.'),
(1699388,58,60,4,12,'Rakkaani, älkää oudoksuko sitä hellettä, jossa olette ja joka on teille koetukseksi, ikäänkuin teille tapahtuisi jotakin outoa,'),
(1699389,58,60,4,13,'vaan iloitkaa, sitä myöten kuin olette osallisia Kristuksen kärsimyksistä, että te myös hänen kirkkautensa ilmestymisessä saisitte iloita ja riemuita.'),
(1699390,58,60,4,14,'Jos teitä solvataan Kristuksen nimen tähden, niin te olette autuaat, sillä kirkkauden ja Jumalan Henki lepää teidän päällänne.'),
(1699391,58,60,4,15,'Älköön näet kukaan teistä kärsikö murhaajana tai varkaana tai pahantekijänä tahi sentähden, että sekaantuu hänelle kuulumattomiin;'),
(1699392,58,60,4,16,'mutta jos hän kärsii kristittynä, älköön hävetkö, vaan ylistäköön sen nimensä tähden Jumalaa.'),
(1699393,58,60,4,17,'Sillä aika on tuomion alkaa Jumalan huoneesta; mutta jos se alkaa ensiksi meistä, niin mikä on niiden loppu, jotka eivät ole Jumalan evankeliumille kuuliaiset?'),
(1699394,58,60,4,18,'Ja "jos vanhurskas vaivoin pelastuu, niin mihinkä joutuukaan jumalaton ja syntinen?"'),
(1699395,58,60,4,19,'Sentähden, uskokoot myös ne, jotka Jumalan tahdon mukaan kärsivät, sielunsa uskolliselle Luojalle, tehden sitä, mikä hyvää on.'),
(1699396,58,60,5,1,'Vanhimpia teidän joukossanne minä siis kehoitan, minä, joka myös olen vanhin ja Kristuksen kärsimysten todistaja ja osallinen myös siihen kirkkauteen, joka vastedes on ilmestyvä:'),
(1699397,58,60,5,2,'kaitkaa teille uskottua Jumalan laumaa, ei pakosta, vaan vapaaehtoisesti, Jumalan tahdon mukaan, ei häpeällisen voiton tähden, vaan sydämen halusta,'),
(1699398,58,60,5,3,'ei herroina halliten niitä, jotka ovat teidän osallenne tulleet, vaan ollen laumalle esikuvina,'),
(1699399,58,60,5,4,'niin te, ylipaimenen ilmestyessä, saatte kirkkauden kuihtumattoman seppeleen.'),
(1699400,58,60,5,5,'Samoin te, nuoremmat, olkaa vanhemmille alamaiset ja pukeutukaa kaikki keskinäiseen nöyryyteen, sillä "Jumala on ylpeitä vastaan, mutta nöyrille hän antaa armon".'),
(1699401,58,60,5,6,'Nöyrtykää siis Jumalan väkevän käden alle, että hän ajallansa teidät korottaisi,'),
(1699402,58,60,5,7,'ja "heittäkää kaikki murheenne hänen päällensä, sillä hän pitää teistä huolen".'),
(1699403,58,60,5,8,'Olkaa raittiit, valvokaa. Teidän vastustajanne, perkele, käy ympäri niinkuin kiljuva jalopeura, etsien, kenen hän saisi niellä.'),
(1699404,58,60,5,9,'Vastustakaa häntä lujina uskossa, tietäen, että samat kärsimykset täytyy teidän veljiennekin maailmassa kestää.'),
(1699405,58,60,5,10,'Mutta kaiken armon Jumala, joka on kutsunut teidät iankaikkiseen kirkkauteensa Kristuksessa, vähän aikaa kärsittyänne, hän on teidät valmistava, teitä tukeva, vahvistava ja lujittava.'),
(1699406,58,60,5,11,'Hänen olkoon valta aina ja iankaikkisesti! Amen.'),
(1699407,58,60,5,12,'Silvanuksen, uskollisen veljen, kautta - jona häntä pidän - olen lyhyesti teille tämän kirjoittanut, kehoittaen teitä ja vakuuttaen, että se armo, jossa te olette, on Jumalan totinen armo.'),
(1699408,58,60,5,13,'Tervehdyksen lähettää teille Babylonissa oleva seurakunta, valittu niinkuin tekin, ja minun poikani Markus.'),
(1699409,58,60,5,14,'Tervehtikää toisianne rakkauden suunannolla. Rauha teille kaikille, jotka Kristuksessa olette!'),
(1699410,58,61,1,1,'Simeon Pietari, Jeesuksen Kristuksen palvelija ja apostoli, niille, jotka ovat saaneet yhtä kalliin uskon kuin mekin meidän Jumalamme ja Vapahtajan Jeesuksen Kristuksen vanhurskaudessa.'),
(1699411,58,61,1,2,'Armo ja rauha lisääntyköön teille Jumalan ja meidän Herramme Jeesuksen tuntemisen kautta.'),
(1699412,58,61,1,3,'Koska hänen jumalallinen voimansa on lahjoittanut meille kaiken, mikä elämään ja jumalisuuteen tarvitaan, hänen tuntemisensa kautta, joka on kutsunut meidät kirkkaudellaan ja täydellisyydellään,'),
(1699413,58,61,1,4,'joiden kautta hän on lahjoittanut meille kalliit ja mitä suurimmat lupaukset, että te niiden kautta tulisitte jumalallisesta luonnosta osallisiksi ja pelastuisitte siitä turmeluksesta, joka maailmassa himojen tähden vallitsee,'),
(1699414,58,61,1,5,'niin pyrkikää juuri sentähden kaikella ahkeruudella osoittamaan uskossanne avuja, avuissa ymmärtäväisyyttä,'),
(1699415,58,61,1,6,'ymmärtäväisyydessä itsenne hillitsemistä, itsenne hillitsemisessä kärsivällisyyttä, kärsivällisyydessä jumalisuutta,'),
(1699416,58,61,1,7,'jumalisuudessa veljellistä rakkautta, veljellisessä rakkaudessa yhteistä rakkautta.'),
(1699417,58,61,1,8,'Sillä jos teillä on nämä ja ne yhä enenevät, niin ne eivät salli teidän olla toimettomia eikä hedelmättömiä meidän Herramme Jeesuksen Kristuksen tuntemisessa.'),
(1699418,58,61,1,9,'Jolla sitävastoin ei niitä ole, se on sokea, likinäköinen, on unhottanut puhdistuneensa entisistä synneistänsä.'),
(1699419,58,61,1,10,'Pyrkikää sentähden, veljet, sitä enemmän tekemään kutsumisenne ja valitsemisenne lujaksi; sillä jos sen teette, ette koskaan lankea;'),
(1699420,58,61,1,11,'sillä näin teille runsain määrin tarjotaan pääsy meidän Herramme ja Vapahtajamme Jeesuksen Kristuksen iankaikkiseen valtakuntaan.'),
(1699421,58,61,1,12,'Sentähden minä aina aion muistuttaa teitä tästä, vaikka sen tiedättekin ja olette vahvistetut siinä totuudessa, joka teillä on.'),
(1699422,58,61,1,13,'Ja minä katson oikeaksi, niin kauan kuin tässä majassa olen, näin muistuttamalla herättää teitä.'),
(1699423,58,61,1,14,'Sillä minä tiedän, että tämän majani poispaneminen tapahtuu äkisti, niinkuin myös meidän Herramme Jeesus Kristus minulle ilmoitti.'),
(1699424,58,61,1,15,'Mutta minä olen huolehtiva siitä, että te minun lähtöni jälkeenkin aina voisitte tämän muistaa.'),
(1699425,58,61,1,16,'Sillä me emme seuranneet viekkaasti sommiteltuja taruja tehdessämme teille tiettäväksi Herramme Jeesuksen Kristuksen voimaa ja tulemusta, vaan me olimme omin silmin nähneet hänen valtasuuruutensa.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699426,58,61,1,17,'Sillä hän sai Isältä Jumalalta kunnian ja kirkkauden, kun tältä ylhäisimmältä kirkkaudelta tuli hänelle tämä ääni: "Tämä on minun rakas Poikani, johon minä olen mielistynyt".'),
(1699427,58,61,1,18,'Ja tämän äänen me kuulimme tulevan taivaasta, kun olimme hänen kanssaan pyhällä vuorella.'),
(1699428,58,61,1,19,'Ja sitä lujempi on meille nyt profeetallinen sana, ja te teette hyvin, jos otatte siitä vaarin, niinkuin pimeässä paikassa loistavasta lampusta, kunnes päivä valkenee ja kointähti koittaa teidän sydämissänne.'),
(1699429,58,61,1,20,'Ja tietäkää ennen kaikkea se, ettei yksikään Raamatun profetia ole kenenkään omin neuvoin selitettävissä;'),
(1699430,58,61,1,21,'sillä ei koskaan ole mitään profetiaa tuotu esiin ihmisen tahdosta, vaan Pyhän Hengen johtamina ihmiset ovat puhuneet sen, minkä saivat Jumalalta.'),
(1699431,58,61,2,1,'Mutta myös valheprofeettoja oli kansan seassa, niinkuin teidänkin keskuudessanne on oleva valheenopettajia, jotka salaa kuljettavat sisään turmiollisia harhaoppeja, kieltävätpä Herrankin, joka on heidät ostanut, ja tuottavat itselleen äkillisen perikadon.'),
(1699432,58,61,2,2,'Ja moni on seuraava heidän irstauksiaan, ja heidän tähtensä totuuden tie tulee häväistyksi;'),
(1699433,58,61,2,3,'ja ahneudessaan he valheellisilla sanoilla kiskovat teistä hyötyä; mutta jo ammoisista ajoista heidän tuomionsa valvoo, eikä heidän perikatonsa torku.'),
(1699434,58,61,2,4,'Sillä ei Jumala säästänyt enkeleitä, jotka syntiä tekivät, vaan syöksi heidät syvyyteen, pimeyden kuiluihin, ja hylkäsi heidät tuomiota varten säilytettäviksi.'),
(1699435,58,61,2,5,'Eikä hän säästänyt muinaista maailmaa, vaikka varjelikin Nooan, vanhurskauden saarnaajan, ynnä seitsemän muuta, vaan antoi vedenpaisumuksen tulla jumalattomain maailman päälle.'),
(1699436,58,61,2,6,'Ja hän poltti poroksi Sodoman ja Gomorran kaupungit ja tuomitsi ne häviöön, asettaen ne varoitukseksi niille, jotka vastedes jumalattomasti elävät.'),
(1699437,58,61,2,7,'Kuitenkin hän pelasti hurskaan Lootin, jota rietasten vaellus irstaudessa vaivasi;'),
(1699438,58,61,2,8,'sillä asuessaan heidän keskuudessansa tuo hurskas mies kiusaantui hurskaassa sielussaan joka päivä heidän pahain tekojensa tähden, joita hänen täytyi nähdä ja kuulla.'),
(1699439,58,61,2,9,'Näin Herra tietää pelastaa jumaliset kiusauksesta, mutta tuomion päivään säilyttää rangaistuksen alaisina väärät,'),
(1699440,58,61,2,10,'ja varsinkin ne, jotka lihan jäljessä kulkevat saastaisissa himoissa ja ylenkatsovat herrauden. Nuo uhkarohkeat, itserakkaat eivät kammo herjata henkivaltoja,'),
(1699441,58,61,2,11,'vaikka enkelitkään, jotka väkevyydeltään ja voimaltaan ovat suuremmat, eivät lausu heitä vastaan herjaavaa tuomiota Herran edessä.'),
(1699442,58,61,2,12,'Mutta niinkuin järjettömät, luonnostaan pyydystettäviksi ja häviämään syntyneet eläimet, niin joutuvat myös nämä, kun herjaavat sitä, mitä eivät tunne, häviämään omaan turmelukseensa,'),
(1699443,58,61,2,13,'saaden vääryyden palkan; he pitävät nautintonaan elää päivänsä hekumassa; he ovat tahra- ja häpeäpilkkuja; he herkuttelevat petoksissaan, kemuillessaan teidän kanssanne;'),
(1699444,58,61,2,14,'heidän silmänsä ovat täynnä haureutta eivätkä saa kylläänsä synnistä; he viekoittelevat horjuvia sieluja, heillä on ahneuteen harjaantunut sydän; he ovat kirouksen lapsia.'),
(1699445,58,61,2,15,'He ovat hyljänneet suoran tien, ovat eksyneet ja seuranneet Bileamin, Beorin pojan, tietä, hänen, joka rakasti vääryyden palkkaa,'),
(1699446,58,61,2,16,'mutta sai rikkomuksestaan ojennuksen: mykkä juhta puhui ihmisen äänellä ja esti profeetan mielettömyyden.'),
(1699447,58,61,2,17,'Sellaiset ovat vedettömiä lähteitä ja myrskytuulen ajamia hattaroita, ja pimeyden synkeys on heille varattu.'),
(1699448,58,61,2,18,'Sillä he puhuvat pöyhkeitä turhuuden sanoja ja viekoittelevat lihan himoissa irstauksilla niitä, jotka tuskin ovat päässeet eksyksissä vaeltavia pakoon,'),
(1699449,58,61,2,19,'ja lupaavat heille vapautta, vaikka itse ovat turmeluksen orjia; sillä kenen voittama joku on, sen orja hän on.'),
(1699450,58,61,2,20,'Sillä jos he meidän Herramme ja Vapahtajan Jeesuksen Kristuksen tuntemisen kautta ovat päässeetkin maailman saastutuksia pakoon, mutta niihin taas kietoutuvat ja tulevat voitetuiksi, niin on viimeinen tullut heille ensimmäistä pahemmaksi.'),
(1699451,58,61,2,21,'Parempi olisi heille ollut, etteivät olisi tulleet tuntemaan vanhurskauden tietä, kuin että sen tunnettuaan kääntyvät pois heille annetusta pyhästä käskystä.'),
(1699452,58,61,2,22,'Heille on tapahtunut, mitä tosi sananlasku sanoo: "Koira palaa oksennukselleen", ja: "Pesty sika rypee rapakossa".'),
(1699453,58,61,3,1,'Tämä on jo toinen kirje, jonka minä kirjoitan teille, rakkaani, ja näissä molemmissa minä muistuttamalla herätän teidän puhdasta mieltänne,'),
(1699454,58,61,3,2,'että muistaisitte niitä sanoja, joita pyhät profeetat ennen ovat puhuneet, ja Herran ja Vapahtajan käskyä, jonka te apostoleiltanne olette saaneet.'),
(1699455,58,61,3,3,'Ja ennen kaikkea tietäkää se, että viimeisinä päivinä tulee pilkkapuheinensa pilkkaajia, jotka vaeltavat omien himojensa mukaan'),
(1699456,58,61,3,4,'ja sanovat: "Missä on lupaus hänen tulemuksestansa? Sillä onhan siitä asti, kuin isät nukkuivat pois, kaikki pysynyt, niinkuin se on ollut luomakunnan alusta."'),
(1699457,58,61,3,5,'Sillä tietensä he eivät ole tietävinään, että taivaat ja samoin maa, vedestä ja veden kautta rakennettu, olivat ikivanhastaan olemassa Jumalan sanan voimasta'),
(1699458,58,61,3,6,'ja että niiden kautta silloinen maailma hukkui vedenpaisumukseen.'),
(1699459,58,61,3,7,'Mutta nykyiset taivaat ja maa ovat samalla sanalla talletetut tulelle, säästetyt jumalattomain ihmisten tuomion ja kadotuksen päivään.'),
(1699460,58,61,3,8,'Mutta tämä yksi älköön olko teiltä, rakkaani, salassa, että "yksi päivä on Herran edessä niinkuin tuhat vuotta ja tuhat vuotta niinkuin yksi päivä".'),
(1699461,58,61,3,9,'Ei Herra viivytä lupauksensa täyttämistä, niinkuin muutamat pitävät sitä viivyttelemisenä, vaan hän on pitkämielinen teitä kohtaan, sillä hän ei tahdo, että kukaan hukkuu, vaan että kaikki tulevat parannukseen.'),
(1699462,58,61,3,10,'Mutta Herran päivä on tuleva niinkuin varas, ja silloin taivaat katoavat pauhinalla, ja alkuaineet kuumuudesta hajoavat, ja maa ja kaikki, mitä siihen on tehty, palavat.'),
(1699463,58,61,3,11,'Kun siis nämä kaikki näin hajoavat, millaisia tuleekaan teidän olla pyhässä vaelluksessa ja jumalisuudessa,'),
(1699464,58,61,3,12,'teidän, jotka odotatte ja joudutatte Jumalan päivän tulemista, jonka voimasta taivaat hehkuen hajoavat ja alkuaineet kuumuudesta sulavat!'),
(1699465,58,61,3,13,'Mutta hänen lupauksensa mukaan me odotamme uusia taivaita ja uutta maata, joissa vanhurskaus asuu.'),
(1699466,58,61,3,14,'Sentähden, rakkaani, pyrkikää tätä odottaessanne siihen, että teidät havaittaisiin tahrattomiksi ja nuhteettomiksi, rauhassa, hänen edessänsä;'),
(1699467,58,61,3,15,'ja lukekaa meidän Herramme pitkämielisyys pelastukseksi, josta myös meidän rakas veljemme Paavali hänelle annetun viisauden mukaan teille on kirjoittanut;'),
(1699468,58,61,3,16,'niinkuin hän tekee kaikissa kirjeissään, kun hän niissä puhuu näistä asioista, vaikka niissä tosin on yhtä ja toista vaikeatajuista, jota tietämättömät ja vakaantumattomat vääntävät kieroon niinkuin muitakin kirjoituksia, omaksi kadotuksekseen.'),
(1699469,58,61,3,17,'Koska te siis, rakkaani, tämän jo edeltäpäin tiedätte, niin olkaa varuillanne, ettette rietasten eksymyksen mukaansa tempaamina lankeaisi pois omalta lujalta pohjaltanne,'),
(1699470,58,61,3,18,'ja kasvakaa meidän Herramme ja Vapahtajamme Jeesuksen Kristuksen armossa ja tuntemisessa. Hänen olkoon kunnia sekä nyt että hamaan iankaikkisuuden päivään.'),
(1699471,58,62,1,1,'Mikä on alusta ollut, minkä olemme kuulleet, minkä omin silmin nähneet, mitä katselimme ja käsin kosketimme, siitä me puhumme: elämän Sanasta -'),
(1699472,58,62,1,2,'ja elämä ilmestyi, ja me olemme nähneet sen ja todistamme siitä ja julistamme teille sen iankaikkisen elämän, joka oli Isän tykönä ja ilmestyi meille -'),
(1699473,58,62,1,3,'minkä olemme nähneet ja kuulleet, sen me myös teille julistamme, että teilläkin olisi yhteys meidän kanssamme; ja meillä on yhteys Isän ja hänen Poikansa, Jeesuksen Kristuksen, kanssa.'),
(1699474,58,62,1,4,'Ja tämän me kirjoitamme, että meidän ilomme olisi täydellinen.'),
(1699475,58,62,1,5,'Ja tämä on se sanoma, jonka olemme häneltä kuulleet ja jonka me teille julistamme: että Jumala on valkeus ja ettei hänessä ole mitään pimeyttä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699476,58,62,1,6,'Jos sanomme, että meillä on yhteys hänen kanssaan, mutta vaellamme pimeydessä, niin me valhettelemme emmekä tee totuutta.'),
(1699477,58,62,1,7,'Mutta jos me valkeudessa vaellamme, niinkuin hän on valkeudessa, niin meillä on yhteys keskenämme, ja Jeesuksen Kristuksen, hänen Poikansa, veri puhdistaa meidät kaikesta synnistä.'),
(1699478,58,62,1,8,'Jos sanomme, ettei meillä ole syntiä, niin me eksytämme itsemme, ja totuus ei ole meissä.'),
(1699479,58,62,1,9,'Jos me tunnustamme syntimme, on hän uskollinen ja vanhurskas, niin että hän antaa meille synnit anteeksi ja puhdistaa meidät kaikesta vääryydestä.'),
(1699480,58,62,1,10,'Jos sanomme, ettemme ole syntiä tehneet, niin me teemme hänet valhettelijaksi, ja hänen sanansa ei ole meissä.'),
(1699481,58,62,2,1,'Lapsukaiseni, tämän minä kirjoitan teille, ettette syntiä tekisi; mutta jos joku syntiä tekeekin, niin meillä on puolustaja Isän tykönä, Jeesus Kristus, joka on vanhurskas.'),
(1699482,58,62,2,2,'Ja hän on meidän syntiemme sovitus; eikä ainoastaan meidän, vaan myös koko maailman syntien.'),
(1699483,58,62,2,3,'Ja siitä me tiedämme hänet tuntevamme, että pidämme hänen käskynsä.'),
(1699484,58,62,2,4,'Joka sanoo: "Minä tunnen hänet", eikä pidä hänen käskyjänsä, se on valhettelija, ja totuus ei ole hänessä.'),
(1699485,58,62,2,5,'Mutta joka pitää hänen sanansa, hänessä on Jumalan rakkaus totisesti täydelliseksi tullut. Siitä me tiedämme, että me hänessä olemme.'),
(1699486,58,62,2,6,'Joka sanoo hänessä pysyvänsä, on velvollinen vaeltamaan, niinkuin hän vaelsi.'),
(1699487,58,62,2,7,'Rakkaani, en minä kirjoita teille uutta käskyä, vaan vanhan käskyn, joka teillä on alusta ollut; tämä vanha käsky on se sana, jonka te olette kuulleet.'),
(1699488,58,62,2,8,'Ja kuitenkin minä kirjoitan teille uuden käskyn, sen, mikä on totta hänessä ja teissä; sillä pimeys katoaa, ja totinen valkeus jo loistaa.'),
(1699489,58,62,2,9,'Joka sanoo valkeudessa olevansa, mutta vihaa veljeänsä, se on yhä vielä pimeydessä.'),
(1699490,58,62,2,10,'Joka rakastaa veljeänsä, se pysyy valkeudessa, ja hänessä ei ole pahennusta.'),
(1699491,58,62,2,11,'Mutta joka vihaa veljeänsä, se on pimeydessä ja vaeltaa pimeydessä, eikä hän tiedä, mihin menee; sillä pimeys on sokaissut hänen silmänsä.'),
(1699492,58,62,2,12,'Minä kirjoitan teille, lapsukaiset, sillä synnit ovat teille anteeksi annetut hänen nimensä tähden.'),
(1699493,58,62,2,13,'Minä kirjoitan teille, isät, sillä te olette oppineet tuntemaan hänet, joka alusta on ollut. Minä kirjoitan teille, nuorukaiset, sillä te olette voittaneet sen, joka on paha. Minä olen kirjoittanut teille, lapsukaiset, sillä te olette oppineet tuntemaan Isän.'),
(1699494,58,62,2,14,'Minä olen kirjoittanut teille, isät, sillä te olette oppineet tuntemaan hänet, joka alusta on ollut. Minä olen kirjoittanut teille, nuorukaiset, sillä te olette väkevät, ja Jumalan sana pysyy teissä, ja te olette voittaneet sen, joka on paha.'),
(1699495,58,62,2,15,'Älkää rakastako maailmaa älkääkä sitä, mikä maailmassa on. Jos joku maailmaa rakastaa, niin Isän rakkaus ei ole hänessä.'),
(1699496,58,62,2,16,'Sillä kaikki, mikä maailmassa on, lihan himo, silmäin pyyntö ja elämän korskeus, se ei ole Isästä, vaan maailmasta.'),
(1699497,58,62,2,17,'Ja maailma katoaa ja sen himo; mutta joka tekee Jumalan tahdon, se pysyy iankaikkisesti.'),
(1699498,58,62,2,18,'Lapsukaiset, nyt on viimeinen aika. Ja niinkuin te olette kuulleet, että antikristus tulee, niin onkin nyt monta antikristusta ilmaantunut; siitä me tiedämme, että nyt on viimeinen aika.'),
(1699499,58,62,2,19,'Meistä he ovat lähteneet, mutta he eivät olleet yhtä meidän kanssamme; sillä jos he olisivat olleet yhtä meidän kanssamme, niin he olisivat meidän kanssamme pysyneet; mutta heissä oli tuleva ilmi, että kaikki eivät ole yhtä meidän kanssamme.'),
(1699500,58,62,2,20,'Teillä on voitelu Pyhältä, ja kaikilla teillä on tieto.'),
(1699501,58,62,2,21,'En minä ole kirjoittanut teille sentähden, ettette totuutta tiedä, vaan sentähden, että te tiedätte sen ja ettei mikään valhe ole totuudesta.'),
(1699502,58,62,2,22,'Kuka on valhettelija, ellei se, joka kieltää sen, että Jeesus on Kristus? Hän on antikristus, se, joka kieltää Isän ja Pojan.'),
(1699503,58,62,2,23,'Kuka ikinä kieltää Pojan, hänellä ei ole Isääkään. Joka tunnustaa Pojan, hänellä on myös Isä.'),
(1699504,58,62,2,24,'Minkä te olette alusta asti kuulleet, se pysyköön teissä. Jos teissä pysyy se, minkä olette alusta asti kuulleet, niin tekin pysytte Pojassa ja Isässä.'),
(1699505,58,62,2,25,'Ja tämä on se lupaus, minkä hän on meille luvannut: iankaikkinen elämä.'),
(1699506,58,62,2,26,'Tämän minä olen kirjoittanut teille niistä, jotka teitä eksyttävät.'),
(1699507,58,62,2,27,'Mutta te - teissä pysyy se voitelu, jonka olette häneltä saaneet, ja te ette ole kenenkään opetuksen tarpeessa; vaan niinkuin hänen voitelunsa opettaa teitä kaikessa, niin se opetus on myös totta eikä ole valhetta; ja niinkuin se on opettanut teitä, niin pysykää hänessä.'),
(1699508,58,62,2,28,'Ja nyt, lapsukaiset, pysykää hänessä, että meillä hänen ilmestyessään olisi turva eikä meitä häpeällä karkoitettaisi pois hänen tyköänsä hänen tulemuksessaan.'),
(1699509,58,62,2,29,'Jos tiedätte, että hän on vanhurskas, niin te ymmärrätte, että myös jokainen, joka vanhurskauden tekee, on hänestä syntynyt.'),
(1699510,58,62,3,1,'Katsokaa, minkäkaltaisen rakkauden Isä on meille antanut, että meitä kutsutaan Jumalan lapsiksi, joita me olemmekin. Sentähden ei maailma tunne meitä, sillä se ei tunne häntä.'),
(1699511,58,62,3,2,'Rakkaani, nyt me olemme Jumalan lapsia, eikä ole vielä käynyt ilmi, mitä meistä tulee. Me tiedämme tulevamme hänen kaltaisikseen, kun hän ilmestyy, sillä me saamme nähdä hänet sellaisena, kuin hän on.'),
(1699512,58,62,3,3,'Ja jokainen, joka panee häneen tämän toivon, puhdistaa itsensä, niinkuin hän on puhdas.'),
(1699513,58,62,3,4,'Jokainen, joka tekee synnin, tekee myös laittomuuden; ja synti on laittomuus.'),
(1699514,58,62,3,5,'Ja te tiedätte hänen ilmestyneen ottamaan pois synnit; ja hänessä ei ole syntiä.'),
(1699515,58,62,3,6,'Kuka ikinä hänessä pysyy, hän ei tee syntiä; kuka ikinä syntiä tekee, hän ei ole häntä nähnyt eikä häntä tuntenut.'),
(1699516,58,62,3,7,'Lapsukaiset, älköön kukaan saako teitä eksyttää. Se, joka vanhurskauden tekee, on vanhurskas, niinkuin hän on vanhurskas.'),
(1699517,58,62,3,8,'Joka syntiä tekee, se on perkeleestä, sillä perkele on tehnyt syntiä alusta asti. Sitä varten Jumalan Poika ilmestyi, että hän tekisi tyhjäksi perkeleen teot.'),
(1699518,58,62,3,9,'Ei yksikään Jumalasta syntynyt tee syntiä, sillä Jumalan siemen pysyy hänessä; eikä hän saata syntiä tehdä, sillä hän on Jumalasta syntynyt.'),
(1699519,58,62,3,10,'Siitä käy ilmi, ketkä ovat Jumalan lapsia ja ketkä perkeleen lapsia. Kuka ikinä ei tee vanhurskautta, hän ei ole Jumalasta, ei myöskään se, joka ei veljeänsä rakasta.'),
(1699520,58,62,3,11,'Sillä tämä on se sanoma, jonka te olette alusta asti kuulleet, että meidän tulee rakastaa toinen toistamme'),
(1699521,58,62,3,12,'eikä olla Kainin kaltaisia, joka oli pahasta ja tappoi veljensä. Ja minkätähden hän tappoi hänet? Sentähden, että hänen tekonsa olivat pahat, mutta hänen veljensä teot vanhurskaat.'),
(1699522,58,62,3,13,'Älkää ihmetelkö, veljeni, jos maailma teitä vihaa.'),
(1699523,58,62,3,14,'Me tiedämme siirtyneemme kuolemasta elämään, sillä me rakastamme veljiä. Joka ei rakasta, pysyy kuolemassa.'),
(1699524,58,62,3,15,'Jokainen, joka vihaa veljeänsä, on murhaaja; ja te tiedätte, ettei kenessäkään murhaajassa ole iankaikkista elämää, joka hänessä pysyisi.'),
(1699525,58,62,3,16,'Siitä me olemme oppineet tuntemaan rakkauden, että hän antoi henkensä meidän edestämme; meidänkin tulee antaa henkemme veljiemme edestä.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699526,58,62,3,17,'Jos nyt jollakin on tämän maailman hyvyyttä ja hän näkee veljensä olevan puutteessa, mutta sulkee häneltä sydämensä, kuinka Jumalan rakkaus saattaa pysyä hänessä?'),
(1699527,58,62,3,18,'Lapsukaiset, älkäämme rakastako sanalla tai kielellä, vaan teossa ja totuudessa.'),
(1699528,58,62,3,19,'Siitä me tiedämme, että olemme totuudesta, ja me saatamme hänen edessään rauhoittaa sydämemme sillä,'),
(1699529,58,62,3,20,'että jos sydämemme syyttää meitä, niin Jumala on suurempi kuin meidän sydämemme ja tietää kaikki.'),
(1699530,58,62,3,21,'Rakkaani, jos sydämemme ei syytä meitä, niin meillä on uskallus Jumalaan,'),
(1699531,58,62,3,22,'ja mitä ikinä anomme, sen me häneltä saamme, koska pidämme hänen käskynsä ja teemme sitä, mikä on hänelle otollista.'),
(1699532,58,62,3,23,'Ja tämä on hänen käskynsä, että meidän tulee uskoa hänen Poikansa Jeesuksen Kristuksen nimeen ja rakastaa toinen toistamme, niinkuin hän on meille käskyn antanut.'),
(1699533,58,62,3,24,'Ja joka pitää hänen käskynsä, se pysyy Jumalassa ja Jumala hänessä. Ja siitä me tiedämme hänen meissä pysyvän, siitä Hengestä, jonka hän on meille antanut.'),
(1699534,58,62,4,1,'Rakkaani, älkää jokaista henkeä uskoko, vaan koetelkaa henget, ovatko ne Jumalasta; sillä monta väärää profeettaa on lähtenyt maailmaan.'),
(1699535,58,62,4,2,'Tästä te tunnette Jumalan Hengen: jokainen henki, joka tunnustaa Jeesuksen Kristukseksi, lihaan tulleeksi, on Jumalasta;'),
(1699536,58,62,4,3,'ja yksikään henki, joka ei tunnusta Jeesusta, ei ole Jumalasta; se on antikristuksen henki, jonka olette kuulleet olevan tulossa, ja se on jo nyt maailmassa.'),
(1699537,58,62,4,4,'Lapsukaiset, te olette Jumalasta ja olette voittaneet heidät; sillä hän, joka teissä on, on suurempi kuin se, joka on maailmassa.'),
(1699538,58,62,4,5,'He ovat maailmasta; sentähden he puhuvat, niinkuin maailma puhuu, ja maailma kuulee heitä.'),
(1699539,58,62,4,6,'Me olemme Jumalasta. Joka tuntee Jumalan, se kuulee meitä; joka ei ole Jumalasta, se ei kuule meitä. Siitä me tunnemme totuuden hengen ja eksytyksen hengen.'),
(1699540,58,62,4,7,'Rakkaani, rakastakaamme toinen toistamme, sillä rakkaus on Jumalasta; ja jokainen, joka rakastaa, on Jumalasta syntynyt ja tuntee Jumalan.'),
(1699541,58,62,4,8,'Joka ei rakasta, se ei tunne Jumalaa, sillä Jumala on rakkaus.'),
(1699542,58,62,4,9,'Siinä ilmestyi meille Jumalan rakkaus, että Jumala lähetti ainokaisen Poikansa maailmaan, että me eläisimme hänen kauttansa.'),
(1699543,58,62,4,10,'Siinä on rakkaus - ei siinä, että me rakastimme Jumalaa, vaan siinä, että hän rakasti meitä ja lähetti Poikansa meidän syntiemme sovitukseksi.'),
(1699544,58,62,4,11,'Rakkaani, jos Jumala on näin meitä rakastanut, niin mekin olemme velvolliset rakastamaan toinen toistamme.'),
(1699545,58,62,4,12,'Jumalaa ei kukaan ole koskaan nähnyt. Jos me rakastamme toinen toistamme, niin Jumala pysyy meissä, ja hänen rakkautensa on tullut täydelliseksi meissä.'),
(1699546,58,62,4,13,'Siitä me tiedämme pysyvämme hänessä ja hänen pysyvän meissä, että hän on antanut meille Henkeänsä.'),
(1699547,58,62,4,14,'Ja me olemme nähneet ja todistamme, että Isä on lähettänyt Poikansa maailman Vapahtajaksi.'),
(1699548,58,62,4,15,'Joka tunnustaa, että Jeesus on Jumalan Poika, hänessä Jumala pysyy, ja hän Jumalassa.'),
(1699549,58,62,4,16,'Ja me olemme oppineet tuntemaan ja me uskomme sen rakkauden, mikä Jumalalla on meihin. Jumala on rakkaus, ja joka pysyy rakkaudessa, se pysyy Jumalassa, ja Jumala pysyy hänessä.'),
(1699550,58,62,4,17,'Näin on rakkaus tullut täydelliseksi meissä, että meillä olisi turva tuomiopäivänä; sillä sellainen kuin hän on, sellaisia mekin olemme tässä maailmassa.'),
(1699551,58,62,4,18,'Pelkoa ei rakkaudessa ole, vaan täydellinen rakkaus karkoittaa pelon, sillä pelossa on rangaistusta; ja joka pelkää, se ei ole päässyt täydelliseksi rakkaudessa.'),
(1699552,58,62,4,19,'Me rakastamme, sillä hän on ensin rakastanut meitä.'),
(1699553,58,62,4,20,'Jos joku sanoo: "Minä rakastan Jumalaa", mutta vihaa veljeänsä, niin hän on valhettelija. Sillä joka ei rakasta veljeänsä, jonka hän on nähnyt, se ei voi rakastaa Jumalaa, jota hän ei ole nähnyt.'),
(1699554,58,62,4,21,'Ja tämä käsky meillä on häneltä, että joka rakastaa Jumalaa, se rakastakoon myös veljeänsä.'),
(1699555,58,62,5,1,'Jokainen, joka uskoo, että Jeesus on Kristus, on Jumalasta syntynyt; ja jokainen, joka rakastaa häntä, joka on synnyttänyt, rakastaa myöskin sitä, joka hänestä on syntynyt.'),
(1699556,58,62,5,2,'Siitä me tiedämme, että rakastamme Jumalan lapsia, kun rakastamme Jumalaa ja noudatamme hänen käskyjänsä.'),
(1699557,58,62,5,3,'Sillä rakkaus Jumalaan on se, että pidämme hänen käskynsä. Ja hänen käskynsä eivät ole raskaat;'),
(1699558,58,62,5,4,'sillä kaikki, mikä on syntynyt Jumalasta, voittaa maailman; ja tämä on se voitto, joka on maailman voittanut, meidän uskomme.'),
(1699559,58,62,5,5,'Kuka on se, joka voittaa maailman, ellei se, joka uskoo, että Jeesus on Jumalan Poika?'),
(1699560,58,62,5,6,'Hän on se, joka on tullut veden ja veren kautta, Jeesus Kristus, ei ainoastaan vedessä, vaan vedessä ja veressä; ja Henki on se, joka todistaa, sillä Henki on totuus.'),
(1699561,58,62,5,7,'Sillä kolme on, jotka todistavat:'),
(1699562,58,62,5,8,'Henki ja vesi ja veri, ja ne kolme pitävät yhtä.'),
(1699563,58,62,5,9,'Jos me otamme vastaan ihmisten todistuksen, niin onhan Jumalan todistus suurempi. Ja tämä on Jumalan todistus, sillä hän on todistanut Pojastansa.'),
(1699564,58,62,5,10,'Joka uskoo Jumalan Poikaan, hänellä on todistus itsessänsä; joka ei usko Jumalaa, tekee hänet valhettelijaksi, koska hän ei usko sitä todistusta, jonka Jumala on todistanut Pojastansa.'),
(1699565,58,62,5,11,'Ja tämä on se todistus: Jumala on antanut meille iankaikkisen elämän, ja tämä elämä on hänen Pojassansa.'),
(1699566,58,62,5,12,'Jolla Poika on, sillä on elämä; jolla Jumalan Poikaa ei ole, sillä ei ole elämää.'),
(1699567,58,62,5,13,'Tämän minä olen kirjoittanut teille, jotka uskotte Jumalan Pojan nimeen, tietääksenne, että teillä on iankaikkinen elämä.'),
(1699568,58,62,5,14,'Ja tämä on se uskallus, joka meillä on häneen, että jos me jotakin anomme hänen tahtonsa mukaan, niin hän kuulee meitä.'),
(1699569,58,62,5,15,'Ja jos me tiedämme hänen kuulevan meitä, mitä ikinä anommekin, niin tiedämme, että meillä myös on kaikki se, mitä olemme häneltä anoneet.'),
(1699570,58,62,5,16,'Jos joku näkee veljensä tekevän syntiä, joka ei ole kuolemaksi, niin rukoilkoon, ja hän on antava hänelle elämän, niille nimittäin, jotka eivät tee syntiä kuolemaksi. On syntiä, joka on kuolemaksi; siitä minä en sano, että olisi rukoiltava.'),
(1699571,58,62,5,17,'Kaikki vääryys on syntiä. Ja on syntiä, joka ei ole kuolemaksi.'),
(1699572,58,62,5,18,'Me tiedämme, ettei yksikään Jumalasta syntynyt tee syntiä; vaan Jumalasta syntynyt pitää itsestänsä vaarin, eikä häneen ryhdy se paha.'),
(1699573,58,62,5,19,'Me tiedämme, että olemme Jumalasta, ja koko maailma on pahan vallassa.'),
(1699574,58,62,5,20,'Mutta me tiedämme, että Jumalan Poika on tullut ja antanut meille ymmärryksen, tunteaksemme sen Totisen; ja me olemme siinä Totisessa, hänen Pojassansa, Jeesuksessa Kristuksessa. Hän on totinen Jumala ja iankaikkinen elämä.'),
(1699575,58,62,5,21,'Lapsukaiset, kavahtakaa epäjumalia.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699576,58,63,1,1,'Vanhin valitulle rouvalle ja hänen lapsillensa, joita minä totuudessa rakastan - enkä ainoastaan minä, vaan myös kaikki, jotka ovat tulleet totuuden tuntemaan -'),
(1699577,58,63,1,2,'totuuden tähden, joka meissä pysyy ja on oleva meidän kanssamme iankaikkisesti.'),
(1699578,58,63,1,3,'Armo, laupeus ja rauha Isältä Jumalalta ja Jeesukselta Kristukselta, Isän Pojalta, on oleva meidän kanssamme, totuudessa ja rakkaudessa.'),
(1699579,58,63,1,4,'Minua on suuresti ilahuttanut, että olen lastesi joukossa havainnut olevan niitä, jotka totuudessa vaeltavat sen käskyn mukaan, jonka me olemme saaneet Isältä.'),
(1699580,58,63,1,5,'Ja nyt, rouva, minulla on sinulle pyyntö, ei niinkuin kirjoittaisin sinulle uuden käskyn, vaan minä kirjoitan sen, joka meillä alusta asti on ollut: että meidän tulee rakastaa toinen toistamme.'),
(1699581,58,63,1,6,'Ja tämä on rakkaus, että me vaellamme hänen käskyjensä mukaan. Tämä on käsky, että teidän, niinkuin olette alusta kuulleet, tulee siinä vaeltaa.'),
(1699582,58,63,1,7,'Sillä monta villitsijää on lähtenyt maailmaan, jotka eivät tunnusta Jeesusta Kristukseksi, joka oli lihaan tuleva; tämä tämmöinen on villitsijä ja antikristus.'),
(1699583,58,63,1,8,'Ottakaa vaari itsestänne, ettette menetä sitä, minkä me olemme työllämme aikaansaaneet, vaan että saatte täyden palkan.'),
(1699584,58,63,1,9,'Kuka ikinä menee edemmäksi eikä pysy Kristuksen opissa, hänellä ei ole Jumalaa; joka siinä opissa pysyy, hänellä on sekä Isä että Poika.'),
(1699585,58,63,1,10,'Jos joku tulee teidän luoksenne eikä tuo mukanaan tätä oppia, niin älkää ottako häntä huoneeseenne älkääkä sanoko häntä tervetulleeksi;'),
(1699586,58,63,1,11,'sillä joka sanoo hänet tervetulleeksi, joutuu osalliseksi hänen pahoihin tekoihinsa.'),
(1699587,58,63,1,12,'Minulla olisi paljon kirjoittamista teille, mutta en tahdo tehdä sitä paperilla ja musteella; vaan toivon pääseväni teidän tykönne ja saavani puhutella teitä suullisesti, että meidän ilomme olisi täydellinen.'),
(1699588,58,63,1,13,'Valitun sisaresi lapset lähettävät sinulle tervehdyksen.'),
(1699589,58,64,1,1,'Vanhin rakkaalle Gaiukselle, jota minä totuudessa rakastan.'),
(1699590,58,64,1,2,'Rakkaani, minä toivotan sinulle, että kaikessa menestyt ja pysyt terveenä, niinkuin sielusikin menestyy.'),
(1699591,58,64,1,3,'Minua ilahutti suuresti, kun veljet tulivat ja antoivat todistuksen sinun totuudestasi, niinkuin sinä totuudessa vaellatkin.'),
(1699592,58,64,1,4,'Minulla ei ole suurempaa iloa kuin se, että kuulen lasteni vaeltavan totuudessa.'),
(1699593,58,64,1,5,'Rakkaani, sinä toimit uskollisesti kaikessa, mitä teet veljien, vieläpä vieraittenkin hyväksi.'),
(1699594,58,64,1,6,'He ovat seurakunnan edessä antaneet todistuksen sinun rakkaudestasi; ja sinä teet hyvin, kun autat heitä eteenpäin heidän matkallaan, niinkuin Jumalan edessä arvollista on.'),
(1699595,58,64,1,7,'Sillä hänen nimensä tähden he ovat matkalle lähteneet eivätkä ota pakanoilta mitään.'),
(1699596,58,64,1,8,'Me olemme siis velvolliset ottamaan semmoisia vastaan, auttaaksemme yhdessä totuutta eteenpäin.'),
(1699597,58,64,1,9,'Minä kirjoitin seurakunnalle; mutta Diotrefes, joka haluaa olla ensimmäinen heidän joukossaan, ei ota meitä vastaan.'),
(1699598,58,64,1,10,'Sentähden minä, jos tulen, muistutan hänen teoistansa, mitä hän tekee, kun pahoilla sanoilla meistä juoruaa; ja vielä siihenkään tyytymättä, hän ei itse ota veljiä vastaan, vaan estää niitäkin, jotka tahtovat sen tehdä, ja ajaa heidät pois seurakunnasta.'),
(1699599,58,64,1,11,'Rakkaani, älä seuraa pahaa, vaan hyvää. Joka hyvin tekee, se on Jumalasta; joka pahoin tekee, se ei ole Jumalaa nähnyt.'),
(1699600,58,64,1,12,'Demetrius on kaikilta, jopa itse totuudeltakin, saanut hyvän todistuksen; ja mekin todistamme hänestä samaa, ja sinä tiedät, että meidän todistuksemme on tosi.'),
(1699601,58,64,1,13,'Minulla olisi paljon kirjoittamista sinulle, mutta en tahdo kirjoittaa sinulle musteella ja kynällä,'),
(1699602,58,64,1,14,'sillä minä toivon pian näkeväni sinut, ja silloin saamme suullisesti puhella.'),
(1699603,58,64,1,15,'Rauha sinulle! Ystävät tervehtivät sinua. Tervehdys ystäville, kullekin erikseen.'),
(1699604,58,65,1,1,'Juudas, Jeesuksen Kristuksen palvelija ja Jaakobin veli, kutsutuille, jotka ovat Isässä Jumalassa rakastetut ja Jeesukselle Kristukselle varjellut.'),
(1699605,58,65,1,2,'Lisääntyköön teille laupeus ja rauha ja rakkaus.'),
(1699606,58,65,1,3,'Rakkaani! Kun minulla on ollut harras halu kirjoittaa teille yhteisestä pelastuksestamme, tuli minulle pakko kirjoittaa ja kehoittaa teitä kilvoittelemaan sen uskon puolesta, joka kerta kaikkiaan on pyhille annettu.'),
(1699607,58,65,1,4,'Sillä teidän keskuuteenne on pujahtanut eräitä ihmisiä, joiden jo aikoja sitten on kirjoitettu tulevan tähän tuomioon, jumalattomia, jotka kääntävät meidän Jumalamme armon irstaudeksi ja kieltävät meidän ainoan valtiaamme ja Herramme, Jeesuksen Kristuksen.'),
(1699608,58,65,1,5,'Vaikka jo kerran olette saaneet tietää kaiken, tahdon kuitenkin muistuttaa teitä siitä, että Herra, joka oli pelastanut kansan Egyptistä, toisella kertaa hukutti ne, jotka eivät uskoneet;'),
(1699609,58,65,1,6,'ja että hän ne enkelit, jotka eivät säilyttäneet valta-asemaansa, vaan jättivät oman asumuksensa, pani pimeyteen iankaikkisissa kahleissa säilytettäviksi suuren päivän tuomioon;'),
(1699610,58,65,1,7,'samoin kuin Sodoma ja Gomorra ja niiden ympärillä olevat kaupungit, jotka samalla tavalla kuin nekin harjoittivat haureutta ja eksyivät luonnottomiin lihanhimoihin, ovat varoittavana esimerkkinä, kärsiessään iankaikkisen tulen rangaistusta.'),
(1699611,58,65,1,8,'Yhtäkaikki nämä uneksijat samoin saastuttavat lihan; he halveksivat herrautta, herjaavat kirkkauden henkiolentoja.'),
(1699612,58,65,1,9,'Mutta ei ylienkeli Miikaelkaan, kun riiteli ja väitteli perkeleen kanssa Mooseksen ruumiista, rohjennut lausua herjaavaa tuomiota, vaan sanoi: "Rangaiskoon sinua Herra!"'),
(1699613,58,65,1,10,'Nämä sitävastoin herjaavat sitä, mitä eivät tunne; mutta minkä he järjettömäin eläinten tavoin luonnostaan ymmärtävät, sillä he turmelevat itsensä.'),
(1699614,58,65,1,11,'Voi heitä, sillä he kulkevat Kainin tietä ja heittäytyvät palkan tähden Bileamin eksytykseen ja hukkuvat niskoitteluunsa niinkuin Koora!'),
(1699615,58,65,1,12,'He likapilkkuina teidän rakkausaterioillanne julkeasti kemuilevat ja itseään kestitsevät. He ovat vedettömiä, tuulten ajeltavia pilviä, paljaita, syksyisiä puita, hedelmättömiä, kahdesti kuolleita, juurineen maasta reväistyjä,'),
(1699616,58,65,1,13,'rajuja meren aaltoja, jotka vaahtoavat omia häpeitään, harhailevia tähtiä, joille pimeyden synkeys ikuisiksi ajoiksi on varattu.'),
(1699617,58,65,1,14,'Heistäkin Eenok, Aadamista seitsemäs, on ennustanut, sanoen: "Katso, Herra tulee tuhannen tuhansine pyhinensä'),
(1699618,58,65,1,15,'tuomitsemaan kaikkia ja rankaisemaan kaikkia jumalattomia kaikista heidän jumalattomista teoistansa, joita he jumalattomuudessaan ovat tehneet, ja kaikesta julkeasta, mitä nuo jumalattomat syntiset ovat häntä vastaan puhuneet".'),
(1699619,58,65,1,16,'He ovat napisijoita, kohtalonsa nurkujia ja vaeltavat himojensa mukaan; heidän suunsa puhuu pöyhkeitä, ja he mielistelevät ihmisiä oman etunsa tähden.'),
(1699620,58,65,1,17,'Mutta te, rakkaani, muistakaa nämä sanat, mitkä meidän Herramme Jeesuksen Kristuksen apostolit ovat edeltäpäin puhuneet,'),
(1699621,58,65,1,18,'sanoen teille: "Viimeisenä aikana tulee pilkkaajia, jotka vaeltavat jumalattomuutensa himojen mukaan".'),
(1699622,58,65,1,19,'Nämä juuri saavat aikaan hajaannusta, he ovat sielullisia, henkeä heillä ei ole.'),
(1699623,58,65,1,20,'Mutta te, rakkaani, rakentakaa itseänne pyhimmän uskonne perustukselle, rukoilkaa Pyhässä Hengessä'),
(1699624,58,65,1,21,'ja pysyttäkää niin itsenne Jumalan rakkaudessa, odottaessanne meidän Herramme Jeesuksen Kristuksen laupeutta iankaikkiseksi elämäksi.'),
(1699625,58,65,1,22,'Ja armahtakaa toisia, niitä, jotka epäilevät, pelastakaa heidät, tulesta temmaten;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699626,58,65,1,23,'toisia taas armahtakaa pelolla, inhoten lihan tahraamaa ihokastakin.'),
(1699627,58,65,1,24,'Mutta hänelle, joka voi varjella teidät lankeamasta ja asettaa teidät nuhteettomina, riemuitsevina, kirkkautensa eteen,'),
(1699628,58,65,1,25,'hänelle, ainoalle Jumalalle ja meidän pelastajallemme Herramme Jeesuksen Kristuksen kautta, hänelle kunnia, majesteetti, voima ja valta ennen kaikkia aikoja ja nyt ja iankaikkisesti! Amen.'),
(1699629,58,66,1,1,'Jeesuksen Kristuksen ilmestys, jonka Jumala antoi hänelle, näyttääkseen palvelijoillensa, mitä pian tapahtuman pitää; ja sen hän lähettämänsä enkelin kautta antoi tiedoksi palvelijalleen Johannekselle,'),
(1699630,58,66,1,2,'joka tässä todistaa Jumalan sanan ja Jeesuksen Kristuksen todistuksen, kaiken sen, minkä hän on nähnyt.'),
(1699631,58,66,1,3,'Autuas se, joka lukee, ja autuaat ne, jotka kuulevat tämän profetian sanat ja ottavat vaarin siitä, mitä siihen kirjoitettu on; sillä aika on lähellä!'),
(1699632,58,66,1,4,'Johannes seitsemälle Aasian seurakunnalle: Armo teille ja rauha häneltä, joka on ja joka oli ja joka tuleva on, ja niiltä seitsemältä hengeltä, jotka ovat hänen valtaistuimensa edessä,'),
(1699633,58,66,1,5,'ja Jeesukselta Kristukselta, uskolliselta todistajalta, häneltä, joka on kuolleitten esikoinen ja maan kuningasten hallitsija! Hänelle, joka meitä rakastaa ja on päästänyt meidät synneistämme verellänsä'),
(1699634,58,66,1,6,'ja tehnyt meidät kuningaskunnaksi, papeiksi Jumalalleen ja Isälleen, hänelle kunnia ja voima aina ja iankaikkisesti! Amen.'),
(1699635,58,66,1,7,'Katso, hän tulee pilvissä, ja kaikki silmät saavat nähdä hänet, niidenkin, jotka hänet lävistivät, ja kaikki maan sukukunnat vaikeroitsevat hänen tullessansa. Totisesti, amen.'),
(1699636,58,66,1,8,'"Minä olen A ja O", sanoo Herra Jumala, joka on ja joka oli ja joka tuleva on, Kaikkivaltias.'),
(1699637,58,66,1,9,'Minä, Johannes, teidän veljenne, joka teidän kanssanne olen osallinen ahdistukseen ja valtakuntaan ja kärsivällisyyteen Jeesuksessa, minä olin Jumalan sanan ja Jeesuksen todistuksen tähden saaressa, jonka nimi on Patmos.'),
(1699638,58,66,1,10,'Minä olin hengessä Herran päivänä, ja kuulin takaani suuren äänen, ikäänkuin pasunan äänen,'),
(1699639,58,66,1,11,'joka sanoi: "Kirjoita kirjaan, mitä näet, ja lähetä niille seitsemälle seurakunnalle, Efesoon ja Smyrnaan ja Pergamoon ja Tyatiraan ja Sardeeseen ja Filadelfiaan ja Laodikeaan".'),
(1699640,58,66,1,12,'Ja minä käännyin katsomaan, mikä ääni minulle puhui; ja kääntyessäni minä näin seitsemän kultaista lampunjalkaa,'),
(1699641,58,66,1,13,'ja lampunjalkain keskellä Ihmisen Pojan muotoisen, pitkäliepeiseen viittaan puetun ja rinnan kohdalta kultaisella vyöllä vyötetyn.'),
(1699642,58,66,1,14,'Ja hänen päänsä ja hiuksensa olivat valkoiset niinkuin valkoinen villa, niinkuin lumi, ja hänen silmänsä niinkuin tulen liekki;'),
(1699643,58,66,1,15,'hänen jalkansa olivat ahjossa hehkuvan, kiiltävän vasken kaltaiset, ja hänen äänensä oli niinkuin paljojen vetten pauhina.'),
(1699644,58,66,1,16,'Ja hänellä oli oikeassa kädessään seitsemän tähteä, ja hänen suustaan lähti kaksiteräinen, terävä miekka, ja hänen kasvonsa olivat niinkuin aurinko, kun se täydeltä terältä paistaa.'),
(1699645,58,66,1,17,'Ja kun minä hänet näin, kaaduin minä kuin kuolleena hänen jalkojensa juureen. Ja hän pani oikean kätensä minun päälleni sanoen: "Älä pelkää! Minä olen ensimmäinen ja viimeinen,'),
(1699646,58,66,1,18,'ja minä elän; ja minä olin kuollut, ja katso, minä elän aina ja iankaikkisesti, ja minulla on kuoleman ja tuonelan avaimet.'),
(1699647,58,66,1,19,'Kirjoita siis, mitä olet nähnyt ja mikä nyt on ja mitä tämän jälkeen on tapahtuva.'),
(1699648,58,66,1,20,'Niiden seitsemän tähden salaisuus, jotka näit minun oikeassa kädessäni, ja niiden seitsemän kultaisen lampunjalan salaisuus on tämä: ne seitsemän tähteä ovat niiden seitsemän seurakunnan enkelit, ja ne seitsemän lampunjalkaa ovat ne seitsemän seurakuntaa."'),
(1699649,58,66,2,1,'"Efeson seurakunnan enkelille kirjoita: ''Näin sanoo hän, joka pitää niitä seitsemää tähteä oikeassa kädessään, hän, joka käyskelee niiden seitsemän kultaisen lampunjalan keskellä:'),
(1699650,58,66,2,2,'Minä tiedän sinun tekosi ja vaivannäkösi ja kärsivällisyytesi, ja ettet voi pahoja sietää; sinä olet koetellut niitä, jotka sanovat itseänsä apostoleiksi, eivätkä ole, ja olet havainnut heidät valhettelijoiksi;'),
(1699651,58,66,2,3,'ja sinulla on kärsivällisyyttä, ja paljon sinä olet saanut kantaa minun nimeni tähden, etkä ole uupunut.'),
(1699652,58,66,2,4,'Mutta se minulla on sinua vastaan, että olet hyljännyt ensimmäisen rakkautesi.'),
(1699653,58,66,2,5,'Muista siis, mistä olet langennut, ja tee parannus, ja tee niitä ensimmäisiä tekoja; mutta jos et, niin minä tulen sinun tykösi ja työnnän sinun lampunjalkasi pois paikaltaan, ellet tee parannusta.'),
(1699654,58,66,2,6,'Mutta se sinulla on, että sinä vihaat nikolaiittain tekoja, joita myös minä vihaan.'),
(1699655,58,66,2,7,'Jolla on korva, se kuulkoon, mitä Henki seurakunnille sanoo. Sen, joka voittaa, minä annan syödä elämän puusta, joka on Jumalan paratiisissa.'''),
(1699656,58,66,2,8,'Ja Smyrnan seurakunnan enkelille kirjoita: ''Näin sanoo ensimmäinen ja viimeinen, joka kuoli ja virkosi elämään:'),
(1699657,58,66,2,9,'Minä tiedän sinun ahdistuksesi ja köyhyytesi - sinä olet kuitenkin rikas - ja mitä pilkkaa sinä kärsit niiltä, jotka sanovat olevansa juutalaisia, eivätkä ole, vaan ovat saatanan synagooga.'),
(1699658,58,66,2,10,'Älä pelkää sitä, mitä tulet kärsimään. Katso, perkele on heittävä muutamia teistä vankeuteen, että teidät pantaisiin koetukselle, ja teidän on oltava ahdistuksessa kymmenen päivää. Ole uskollinen kuolemaan asti, niin minä annan sinulle elämän kruunun.'),
(1699659,58,66,2,11,'Jolla on korva, se kuulkoon, mitä Henki seurakunnille sanoo. Sitä, joka voittaa, ei toinen kuolema vahingoita.'''),
(1699660,58,66,2,12,'Ja Pergamon seurakunnan enkelille kirjoita: ''Näin sanoo hän, jolla on se kaksiteräinen, terävä miekka:'),
(1699661,58,66,2,13,'Minä tiedän, missä sinä asut: siellä, missä saatanan valtaistuin on; ja sinä pidät minun nimestäni kiinni etkä ole kieltänyt minun uskoani niinäkään päivinä, jolloin Antipas, minun todistajani, minun uskolliseni, tapettiin teidän luonanne, siellä, missä saatana asuu.'),
(1699662,58,66,2,14,'Mutta minulla on vähän sinua vastaan: sinulla on siellä niitä, jotka pitävät kiinni Bileamin opista, hänen, joka opetti Baalakia virittämään Israelin lapsille sen viettelyksen, että söisivät epäjumalille uhrattua ja haureutta harjoittaisivat.'),
(1699663,58,66,2,15,'Niin on myös sinulla niitä, jotka samoin pitävät kiinni nikolaiittain opista.'),
(1699664,58,66,2,16,'Tee siis parannus; mutta jos et, niin minä tulen sinun tykösi pian ja sodin heitä vastaan suuni miekalla.'),
(1699665,58,66,2,17,'Jolla on korva, se kuulkoon, mitä Henki seurakunnille sanoo. Sille, joka voittaa, minä annan salattua mannaa ja annan hänelle valkoisen kiven ja siihen kiveen kirjoitetun uuden nimen, jota ei tiedä kukaan muu kuin sen saaja.'''),
(1699666,58,66,2,18,'Ja Tyatiran seurakunnan enkelille kirjoita: ''Näin sanoo Jumalan Poika, jolla on silmät niinkuin tulen liekki ja jonka jalat ovat niinkuin kiiltävä vaski:'),
(1699667,58,66,2,19,'Minä tiedän sinun tekosi ja rakkautesi ja uskosi ja palveluksesi ja kärsivällisyytesi ja että sinun viimeiset tekosi ovat useammat kuin ensimmäiset.'),
(1699668,58,66,2,20,'Mutta se minulla on sinua vastaan, että sinä suvaitset tuota naista, Iisebeliä, joka sanoo itseään profeetaksi ja opettaa ja eksyttää minun palvelijoitani harjoittamaan haureutta ja syömään epäjumalille uhrattua.'),
(1699669,58,66,2,21,'Ja minä olen antanut hänelle aikaa parannuksen tekoon, mutta hän ei tahdo parannusta tehdä eikä luopua haureudestaan.'),
(1699670,58,66,2,22,'Katso, minä syöksen hänet tautivuoteeseen, ja ne, jotka hänen kanssaan tekevät huorin, minä syöksen suureen ahdistukseen, jos eivät tee parannusta ja luovu hänen teoistansa;'),
(1699671,58,66,2,23,'ja hänen lapsensa minä tappamalla tapan, ja kaikki seurakunnat saavat tuntea, että minä olen se, joka tutkin munaskuut ja sydämet; ja minä annan teille kullekin tekojenne mukaan.'),
(1699672,58,66,2,24,'Mutta teille muille Tyatirassa oleville, kaikille, joilla ei ole tätä oppia, teille, jotka ette ole tulleet tuntemaan, niinkuin ne sanovat, saatanan syvyyksiä, minä sanon: en minä pane teidän päällenne muuta kuormaa;'),
(1699673,58,66,2,25,'pitäkää vain, mitä teillä on, siihen asti kuin minä tulen.'),
(1699674,58,66,2,26,'Ja joka voittaa ja loppuun asti ottaa minun teoistani vaarin, sille minä annan vallan hallita pakanoita,'),
(1699675,58,66,2,27,'ja hän on kaitseva heitä rautaisella valtikalla, niinkuin saviastiat heidät särjetään - niinkuin minäkin sen vallan Isältäni sain -');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699676,58,66,2,28,'ja minä annan hänelle kointähden.'),
(1699677,58,66,2,29,'Jolla on korva, se kuulkoon, mitä Henki seurakunnille sanoo.''"'),
(1699678,58,66,3,1,'"Ja Sardeen seurakunnan enkelille kirjoita: ''Näin sanoo hän, jolla on ne Jumalan seitsemän henkeä ja ne seitsemän tähteä: Minä tiedän sinun tekosi: sinulla on se nimi, että elät, mutta sinä olet kuollut.'),
(1699679,58,66,3,2,'Heräjä valvomaan ja vahvista jäljellejääneitä, niitä, jotka ovat olleet kuolemaisillaan; sillä minä en ole havainnut sinun tekojasi täydellisiksi Jumalani edessä.'),
(1699680,58,66,3,3,'Muista siis, mitä olet saanut ja kuullut, ja ota siitä vaari ja tee parannus. Jos et valvo, niin minä tulen kuin varas, etkä sinä tiedä, millä hetkellä minä sinun päällesi tulen.'),
(1699681,58,66,3,4,'Kuitenkin on sinulla Sardeessa muutamia harvoja nimiä, jotka eivät ole tahranneet vaatteitaan, ja he saavat käyskennellä minun kanssani valkeissa vaatteissa, sillä he ovat siihen arvolliset.'),
(1699682,58,66,3,5,'Joka voittaa, se näin puetaan valkeihin vaatteisiin, enkä minä pyyhi pois hänen nimeänsä elämän kirjasta, ja minä olen tunnustava hänen nimensä Isäni edessä ja hänen enkeliensä edessä.'),
(1699683,58,66,3,6,'Jolla on korva, se kuulkoon, mitä Henki seurakunnille sanoo.'''),
(1699684,58,66,3,7,'Ja Filadelfian seurakunnan enkelille kirjoita: ''Näin sanoo Pyhä, Totinen, jolla on Daavidin avain, hän, joka avaa, eikä kukaan sulje, ja joka sulkee, eikä kukaan avaa:'),
(1699685,58,66,3,8,'Minä tiedän sinun tekosi. Katso, minä olen avannut sinun eteesi oven, eikä kukaan voi sitä sulkea; sillä tosin on sinun voimasi vähäinen, mutta sinä olet ottanut vaarin minun sanastani etkä ole minun nimeäni kieltänyt.'),
(1699686,58,66,3,9,'Katso, minä annan sinulle saatanan synagoogasta niitä, jotka sanovat olevansa juutalaisia, eivätkä ole, vaan valhettelevat; katso, minä olen saattava heidät siihen, että he tulevat ja kumartuvat sinun jalkojesi eteen ja ymmärtävät, että minä sinua rakastan.'),
(1699687,58,66,3,10,'Koska sinä olet ottanut minun kärsivällisyyteni sanasta vaarin, niin minä myös otan sinusta vaarin ja pelastan sinut koetuksen hetkestä, joka on tuleva yli koko maanpiirin koettelemaan niitä, jotka maan päällä asuvat.'),
(1699688,58,66,3,11,'Minä tulen pian; pidä, mitä sinulla on, ettei kukaan ottaisi sinun kruunuasi.'),
(1699689,58,66,3,12,'Joka voittaa, sen minä teen pylvääksi Jumalani temppeliin, eikä hän koskaan enää lähde sieltä ulos, ja minä kirjoitan häneen Jumalani nimen ja Jumalani kaupungin nimen, sen uuden Jerusalemin, joka laskeutuu alas taivaasta minun Jumalani tyköä, ja oman uuden nimeni.'),
(1699690,58,66,3,13,'Jolla on korva, se kuulkoon, mitä Henki seurakunnille sanoo.'''),
(1699691,58,66,3,14,'Ja Laodikean seurakunnan enkelille kirjoita: ''Näin sanoo Amen, se uskollinen ja totinen todistaja, Jumalan luomakunnan alku:'),
(1699692,58,66,3,15,'Minä tiedän sinun tekosi: sinä et ole kylmä etkä palava; oi, jospa olisit kylmä tai palava!'),
(1699693,58,66,3,16,'Mutta nyt, koska olet penseä, etkä ole palava etkä kylmä, olen minä oksentava sinut suustani ulos.'),
(1699694,58,66,3,17,'Sillä sinä sanot: Minä olen rikas, minä olen rikastunut enkä mitään tarvitse; etkä tiedä, että juuri sinä olet viheliäinen ja kurja ja köyhä ja sokea ja alaston.'),
(1699695,58,66,3,18,'Minä neuvon sinua ostamaan minulta kultaa, tulessa puhdistettua, että rikastuisit, ja valkeat vaatteet, että niihin pukeutuisit eikä alastomuutesi häpeä näkyisi, ja silmävoidetta voidellaksesi silmäsi, että näkisit.'),
(1699696,58,66,3,19,'Kaikkia niitä, joita minä pidän rakkaina, minä nuhtelen ja kuritan; ahkeroitse siis ja tee parannus.'),
(1699697,58,66,3,20,'Katso, minä seison ovella ja kolkutan; jos joku kuulee minun ääneni ja avaa oven, niin minä käyn hänen tykönsä sisälle ja aterioitsen hänen kanssaan, ja hän minun kanssani.'),
(1699698,58,66,3,21,'Joka voittaa, sen minä annan istua kanssani valtaistuimellani, niinkuin minäkin olen voittanut ja istunut Isäni kanssa hänen valtaistuimellensa.'),
(1699699,58,66,3,22,'Jolla on korva, se kuulkoon, mitä Henki seurakunnille sanoo.''"'),
(1699700,58,66,4,1,'Sen jälkeen minä näin, ja katso: taivaassa oli ovi avoinna, ja ensimmäinen ääni, jonka minä olin kuullut ikäänkuin pasunan puhuvan minulle, sanoi: "Nouse ylös tänne, niin minä näytän sinulle, mitä tämän jälkeen on tapahtuva".'),
(1699701,58,66,4,2,'Ja kohta minä olin hengessä. Ja katso, taivaassa oli valtaistuin, ja valtaistuimella oli istuja.'),
(1699702,58,66,4,3,'Ja istuja oli näöltänsä jaspis- ja sardionkiven kaltainen; ja valtaistuimen ympärillä oli taivaankaari, näöltänsä smaragdin kaltainen.'),
(1699703,58,66,4,4,'Ja valtaistuimen ympärillä oli kaksikymmentä neljä valtaistuinta, ja niillä valtaistuimilla istui kaksikymmentä neljä vanhinta, puettuina valkeihin vaatteisiin, ja heillä oli päässänsä kultaiset kruunut.'),
(1699704,58,66,4,5,'Ja valtaistuimesta lähti salamoita ja ääniä ja ukkosen jylinää; ja valtaistuimen edessä paloi seitsemän tulisoihtua, jotka ovat ne seitsemän Jumalan henkeä.'),
(1699705,58,66,4,6,'Ja valtaistuimen edessä oli ikäänkuin lasinen meri, kristallin näköinen; ja valtaistuimen keskellä ja valtaistuimen ympärillä oli neljä olentoa, edestä ja takaa silmiä täynnä.'),
(1699706,58,66,4,7,'Ja ensimmäinen olento oli leijonan näköinen, ja toinen olento nuoren härän näköinen, ja kolmannella olennolla oli ikäänkuin ihmisen kasvot, ja neljäs olento oli lentävän kotkan näköinen.'),
(1699707,58,66,4,8,'Ja niillä neljällä olennolla oli kullakin kuusi siipeä, ja ne olivat yltympäri ja sisältä silmiä täynnä. Ja ne sanoivat lakkaamatta yötä päivää: "Pyhä, pyhä, pyhä on Herra Jumala, Kaikkivaltias, joka oli ja joka on ja joka tuleva on".'),
(1699708,58,66,4,9,'Ja niin usein kuin olennot antavat ylistyksen, kunnian ja kiitoksen hänelle, joka valtaistuimella istuu, joka elää aina ja iankaikkisesti,'),
(1699709,58,66,4,10,'lankeavat ne kaksikymmentä neljä vanhinta hänen eteensä, joka valtaistuimella istuu, ja kumartaen rukoilevat häntä, joka elää aina ja iankaikkisesti, ja heittävät kruununsa valtaistuimen eteen sanoen:'),
(1699710,58,66,4,11,'"Sinä, meidän Herramme ja meidän Jumalamme, olet arvollinen saamaan ylistyksen ja kunnian ja voiman, sillä sinä olet luonut kaikki, ja sinun tahdostasi ne ovat olemassa ja ovat luodut".'),
(1699711,58,66,5,1,'Ja minä näin valtaistuimella-istuvan oikeassa kädessä kirjakäärön, sisältä ja päältä täyteen kirjoitetun, seitsemällä sinetillä suljetun.'),
(1699712,58,66,5,2,'Ja minä näin väkevän enkelin, joka suurella äänellä kuulutti: "Kuka on arvollinen avaamaan tämän kirjan ja murtamaan sen sinetit?"'),
(1699713,58,66,5,3,'Eikä kukaan taivaassa eikä maan päällä eikä maan alla voinut avata kirjaa eikä katsoa siihen.'),
(1699714,58,66,5,4,'Ja minä itkin kovin sitä, ettei ketään havaittu arvolliseksi avaamaan kirjaa eikä katsomaan siihen.'),
(1699715,58,66,5,5,'Ja yksi vanhimmista sanoi minulle: "Älä itke; katso, jalopeura Juudan sukukunnasta, Daavidin juurivesa, on voittanut, niin että hän voi avata kirjan ja sen seitsemän sinettiä".'),
(1699716,58,66,5,6,'Ja minä näin, että valtaistuimen ja niiden neljän olennon ja vanhinten keskellä seisoi Karitsa, ikäänkuin teurastettu; sillä oli seitsemän sarvea ja seitsemän silmää, jotka ovat ne seitsemän Jumalan henkeä, lähetetyt kaikkeen maailmaan.'),
(1699717,58,66,5,7,'Ja se tuli ja otti kirjan valtaistuimella-istuvan oikeasta kädestä.'),
(1699718,58,66,5,8,'Ja kun se oli ottanut kirjan, niin ne neljä olentoa ja kaksikymmentä neljä vanhinta lankesivat Karitsan eteen, ja heillä oli kantele kullakin, ja heillä oli kultaiset maljat täynnä suitsutuksia, jotka ovat pyhien rukoukset,'),
(1699719,58,66,5,9,'ja he veisasivat uutta virttä, sanoen: "Sinä olet arvollinen ottamaan kirjan ja avaamaan sen sinetit, sillä sinä olet tullut teurastetuksi ja olet verelläsi ostanut Jumalalle ihmiset kaikista sukukunnista ja kielistä ja kansoista ja kansanheimoista'),
(1699720,58,66,5,10,'ja tehnyt heidät meidän Jumalallemme kuningaskunnaksi ja papeiksi, ja he tulevat hallitsemaan maan päällä".'),
(1699721,58,66,5,11,'Ja minä näin, ja minä kuulin monien enkelien äänen valtaistuimen ja olentojen ja vanhinten ympäriltä, ja heidän lukunsa oli kymmenentuhatta kertaa kymmenentuhatta ja tuhat kertaa tuhat,'),
(1699722,58,66,5,12,'ja he sanoivat suurella äänellä: "Karitsa, joka on teurastettu, on arvollinen saamaan voiman ja rikkauden ja viisauden ja väkevyyden ja kunnian ja kirkkauden ja ylistyksen".'),
(1699723,58,66,5,13,'Ja kaikkien luotujen, jotka ovat taivaassa ja maan päällä ja maan alla ja meren päällä, ja kaikkien niissä olevain minä kuulin sanovan: "Hänelle, joka valtaistuimella istuu, ja Karitsalle ylistys ja kunnia ja kirkkaus ja valta aina ja iankaikkisesti!"'),
(1699724,58,66,5,14,'Ja ne neljä olentoa sanoivat: "Amen", ja vanhimmat lankesivat kasvoilleen ja kumartaen rukoilivat.'),
(1699725,58,66,6,1,'Ja minä näin, kuinka Karitsa avasi yhden niistä seitsemästä sinetistä, ja kuulin yhden niistä neljästä olennosta sanovan niinkuin ukkosen äänellä: "Tule!"');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699726,58,66,6,2,'Ja minä näin, ja katso: valkea hevonen; ja sen selässä istuvalla oli jousi, ja hänelle annettiin seppele, ja hän lähti voittajana ja voittamaan.'),
(1699727,58,66,6,3,'Ja kun Karitsa avasi toisen sinetin, kuulin minä toisen olennon sanovan: "Tule!"'),
(1699728,58,66,6,4,'Niin lähti toinen hevonen, tulipunainen, ja sen selässä istuvalle annettiin valta ottaa pois rauha maasta, että ihmiset surmaisivat toisiaan; ja hänelle annettiin suuri miekka.'),
(1699729,58,66,6,5,'Ja kun Karitsa avasi kolmannen sinetin, kuulin minä kolmannen olennon sanovan: "Tule!" Ja minä näin, ja katso: musta hevonen; ja sen selässä istuvalla oli kädessään vaaka.'),
(1699730,58,66,6,6,'Ja minä kuulin ikäänkuin äänen niiden neljän olennon keskeltä sanovan: "Koiniks-mitta nisuja yhden denarin, ja kolme koiniksia ohria yhden denarin! Mutta älä turmele öljyä äläkä viiniä."'),
(1699731,58,66,6,7,'Ja kun Karitsa avasi neljännen sinetin, kuulin minä neljännen olennon äänen sanovan: "Tule!"'),
(1699732,58,66,6,8,'Ja minä näin, ja katso: hallava hevonen; ja sen selässä istuvan nimi oli Kuolema, ja Tuonela seurasi hänen mukanaan, ja heidän valtaansa annettiin neljäs osa maata, annettiin valta tappaa miekalla ja nälällä ja rutolla ja maan petojen kautta.'),
(1699733,58,66,6,9,'Ja kun Karitsa avasi viidennen sinetin, näin minä alttarin alla niiden sielut, jotka olivat surmatut Jumalan sanan tähden ja sen todistuksen tähden, joka heillä oli.'),
(1699734,58,66,6,10,'Ja he huusivat suurella äänellä sanoen: "Kuinka kauaksi sinä, pyhä ja totinen Valtias, siirrät tuomiosi ja jätät kostamatta meidän veremme niille, jotka maan päällä asuvat?"'),
(1699735,58,66,6,11,'Ja heille kullekin annettiin pitkä valkoinen vaippa, ja heille sanottiin, että vielä vähän aikaa pysyisivät levollisina, kunnes oli täyttyvä myös heidän kanssapalvelijainsa ja veljiensä luku, joiden tuli joutua tapettaviksi niinkuin hekin.'),
(1699736,58,66,6,12,'Ja minä näin, kuinka Karitsa avasi kuudennen sinetin; ja tuli suuri maanjäristys, ja aurinko meni mustaksi niinkuin karvainen säkkipuku, ja kuu muuttui kokonaan kuin vereksi,'),
(1699737,58,66,6,13,'ja taivaan tähdet putosivat maahan, niinkuin viikunapuu varistaa raakaleensa, kun suuri tuuli sitä pudistaa,'),
(1699738,58,66,6,14,'ja taivas väistyi pois niinkuin kirja, joka kääritään kokoon, ja kaikki vuoret ja saaret siirtyivät sijoiltansa.'),
(1699739,58,66,6,15,'Ja maan kuninkaat ja ylimykset ja sotapäälliköt ja rikkaat ja väkevät ja kaikki orjat ja vapaat kätkeytyivät luoliin ja vuorten rotkoihin'),
(1699740,58,66,6,16,'ja sanoivat vuorille ja kallioille: "Langetkaa meidän päällemme ja kätkekää meidät hänen kasvoiltansa, joka valtaistuimella istuu, ja Karitsan vihalta!'),
(1699741,58,66,6,17,'Sillä heidän vihansa suuri päivä on tullut, ja kuka voi kestää?"'),
(1699742,58,66,7,1,'Senjälkeen minä näin neljä enkeliä seisovan maan neljällä kulmalla ja pitävän kiinni maan neljää tuulta, ettei mikään tuuli pääsisi puhaltamaan maan päälle eikä meren päälle eikä yhteenkään puuhun.'),
(1699743,58,66,7,2,'Ja minä näin erään muun enkelin kohoavan auringonnoususta, ja hänellä oli elävän Jumalan sinetti, ja hän huusi suurella äänellä niille neljälle enkelille, joille oli annettu valta vahingoittaa maata ja merta,'),
(1699744,58,66,7,3,'ja sanoi: "Älkää vahingoittako maata älkääkä merta, älkää myös puita, ennenkuin me olemme painaneet sinetin Jumalamme palvelijain otsaan".'),
(1699745,58,66,7,4,'Ja minä kuulin sinetillä merkittyjen luvun, sata neljäkymmentä neljä tuhatta merkittyä kaikista Israelin lasten sukukunnista:'),
(1699746,58,66,7,5,'Juudan sukukunnasta kaksitoista tuhatta merkittyä, Ruubenin sukukunnasta kaksitoista tuhatta, Gaadin sukukunnasta kaksitoista tuhatta,'),
(1699747,58,66,7,6,'Asserin sukukunnasta kaksitoista tuhatta, Naftalin sukukunnasta kaksitoista tuhatta, Manassen sukukunnasta kaksitoista tuhatta,'),
(1699748,58,66,7,7,'Simeonin sukukunnasta kaksitoista tuhatta, Leevin sukukunnasta kaksitoista tuhatta, Isaskarin sukukunnasta kaksitoista tuhatta,'),
(1699749,58,66,7,8,'Sebulonin sukukunnasta kaksitoista tuhatta, Joosefin sukukunnasta kaksitoista tuhatta, Benjaminin sukukunnasta kaksitoista tuhatta merkittyä.'),
(1699750,58,66,7,9,'Tämän jälkeen minä näin, ja katso, oli suuri joukko, jota ei kukaan voinut lukea, kaikista kansanheimoista ja sukukunnista ja kansoista ja kielistä, ja ne seisoivat valtaistuimen edessä ja Karitsan edessä puettuina pitkiin valkeihin vaatteisiin, ja heillä oli palmut käsissään,'),
(1699751,58,66,7,10,'ja he huusivat suurella äänellä sanoen: "Pelastus tulee meidän Jumalaltamme, joka valtaistuimella istuu, ja Karitsalta".'),
(1699752,58,66,7,11,'Ja kaikki enkelit seisoivat piirissä valtaistuimen ja vanhinten ja neljän olennon ympärillä ja lankesivat kasvoilleen valtaistuimen eteen ja kumartaen rukoilivat Jumalaa,'),
(1699753,58,66,7,12,'sanoen: "Amen! Ylistys ja kirkkaus ja viisaus ja kiitos ja kunnia ja voima ja väkevyys meidän Jumalallemme aina ja iankaikkisesti, amen!"'),
(1699754,58,66,7,13,'Ja yksi vanhimmista puhui minulle ja sanoi: "Keitä ovat nämä pitkiin valkeihin vaatteisiin puetut, ja mistä he ovat tulleet?"'),
(1699755,58,66,7,14,'Ja minä sanoin hänelle: "Herrani, sinä tiedät sen". Ja hän sanoi minulle: "Nämä ovat ne, jotka siitä suuresta ahdistuksesta tulevat, ja he ovat pesseet vaatteensa ja valkaisseet ne Karitsan veressä.'),
(1699756,58,66,7,15,'Sentähden he ovat Jumalan valtaistuimen edessä ja palvelevat häntä päivät ja yöt hänen temppelissään, ja hän, joka valtaistuimella istuu, on levittävä telttamajansa heidän ylitsensä.'),
(1699757,58,66,7,16,'Ei heidän enää tule nälkä eikä enää jano, eikä aurinko ole sattuva heihin, eikä mikään helle,'),
(1699758,58,66,7,17,'sillä Karitsa, joka on valtaistuimen keskellä, on kaitseva heitä ja johdattava heidät elämän vetten lähteille, ja Jumala on pyyhkivä pois kaikki kyyneleet heidän silmistänsä."'),
(1699759,58,66,8,1,'Ja kun Karitsa avasi seitsemännen sinetin, tuli taivaassa äänettömyys, jota kesti noin puoli hetkeä.'),
(1699760,58,66,8,2,'Ja minä näin ne seitsemän enkeliä, jotka seisoivat Jumalan edessä, ja heille annettiin seitsemän pasunaa.'),
(1699761,58,66,8,3,'Ja tuli eräs muu enkeli ja asettui alttarin ääreen pitäen kultaista suitsutusastiaa, ja hänelle annettiin paljon suitsukkeita pantavaksi kaikkien pyhien rukouksiin kultaiselle alttarille, joka oli valtaistuimen edessä.'),
(1699762,58,66,8,4,'Ja suitsukkeiden savu nousi pyhien rukousten kanssa enkelin kädestä Jumalan eteen.'),
(1699763,58,66,8,5,'Ja enkeli otti suitsutusastian ja täytti sen alttarin tulella ja heitti maan päälle; silloin syntyi ukkosenjylinää ja ääniä ja salamoita ja maanjäristystä.'),
(1699764,58,66,8,6,'Ja ne seitsemän enkeliä, joilla oli ne seitsemän pasunaa, hankkiutuivat puhaltamaan pasunoihin.'),
(1699765,58,66,8,7,'Ja ensimmäinen enkeli puhalsi pasunaan; niin tuli rakeita ja tulta, verellä sekoitettuja, ja ne heitettiin maan päälle; ja kolmas osa maata paloi, ja kolmas osa puita paloi, ja kaikki vihanta ruoho paloi.'),
(1699766,58,66,8,8,'Ja toinen enkeli puhalsi pasunaan; niin heitettiin mereen ikäänkuin suuri, tulena palava vuori; ja kolmas osa merta muuttui vereksi,'),
(1699767,58,66,8,9,'ja kolmas osa luoduista, mitä meressä on ja joissa henki on, kuoli, ja kolmas osa laivoista hukkui.'),
(1699768,58,66,8,10,'Ja kolmas enkeli puhalsi pasunaan; niin putosi taivaasta suuri tähti, palava kuin tulisoihtu, ja se putosi virtoihin, kolmanteen osaan niistä, ja vesilähteisiin.'),
(1699769,58,66,8,11,'Ja tähden nimi oli Koiruoho. Ja kolmas osa vesistä muuttui koiruohoksi, ja paljon ihmisiä kuoli vedestä, koska se oli karvaaksi käynyt.'),
(1699770,58,66,8,12,'Ja neljäs enkeli puhalsi pasunaan; niin kolmas osa auringosta ja kolmas osa kuusta ja kolmas osa tähdistä lyötiin vitsauksella, niin että kolmas osa niistä pimeni ja päivä kolmannelta osaltaan oli valoton, ja niin myös yö.'),
(1699771,58,66,8,13,'Ja minä näin, ja minä kuulin kotkan, joka lensi keskitaivaalla, sanovan suurella äänellä: "Voi, voi, voi maan päällä asuvaisia niiden jäljellä olevain pasunain äänten tähden, joihin kolmen enkelin vielä on määrä puhaltaa!"'),
(1699772,58,66,9,1,'Ja viides enkeli puhalsi pasunaan; niin minä näin tähden, taivaasta maan päälle pudonneen, ja sille annettiin syvyyden kaivon avain;'),
(1699773,58,66,9,2,'ja se avasi syvyyden kaivon, ja kaivosta nousi savu, niinkuin savu suuresta pätsistä, ja kaivon savu pimitti auringon ja ilman.'),
(1699774,58,66,9,3,'Ja savusta lähti heinäsirkkoja maan päälle, ja niille annettiin valta, niinkuin maan skorpioneilla on valta;'),
(1699775,58,66,9,4,'ja niille sanottiin, etteivät ne saa vahingoittaa maan ruohoa eikä mitään vihantaa eikä yhtään puuta, vaan ainoastaan niitä ihmisiä, joilla ei ole Jumalan sinettiä otsassaan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699776,58,66,9,5,'Ja niille annettiin valta vaivata heitä viisi kuukautta, vaan ei tappaa heitä; ja ne vaivasivat, niinkuin vaivaa skorpioni, kun se ihmistä pistää.'),
(1699777,58,66,9,6,'Ja niinä päivinä ihmiset etsivät kuolemaa, eivätkä sitä löydä; he haluavat kuolla, mutta kuolema pakenee heitä.'),
(1699778,58,66,9,7,'Ja heinäsirkat olivat sotaan varustettujen hevosten kaltaiset, ja niillä oli päässään ikäänkuin seppeleet, kullan näköiset, ja niiden kasvot olivat ikäänkuin ihmisten kasvot;'),
(1699779,58,66,9,8,'ja niillä oli hiukset niinkuin naisten hiukset, ja niiden hampaat olivat niinkuin leijonain hampaat.'),
(1699780,58,66,9,9,'Ja niillä oli haarniskat ikäänkuin rautahaarniskat, ja niiden siipien kohina oli kuin sotavaunujen ryske monien hevosten kiitäessä taisteluun.'),
(1699781,58,66,9,10,'Ja niillä oli pyrstöt niinkuin skorpioneilla ja pistimet, ja pyrstöissänsä niillä oli voima vahingoittaa ihmisiä viisi kuukautta.'),
(1699782,58,66,9,11,'Niillä oli kuninkaanaan syvyyden enkeli, jonka nimi hebreaksi on Abaddon ja kreikaksi Apollyon.'),
(1699783,58,66,9,12,'Ensimmäinen "voi!" on mennyt; katso, tulee vielä kaksi "voi!"-huutoa tämän jälkeen.'),
(1699784,58,66,9,13,'Ja kuudes enkeli puhalsi pasunaan; niin minä kuulin äänen tulevan kultaisen alttarin neljästä sarvesta, Jumalan edestä,'),
(1699785,58,66,9,14,'ja se sanoi kuudennelle enkelille, jolla oli pasuna: "Päästä ne neljä enkeliä, jotka ovat sidottuina suuren Eufrat-virran varrella".'),
(1699786,58,66,9,15,'Silloin päästettiin ne neljä enkeliä, jotka hetkelleen, päivälleen, kuukaudelleen ja vuodelleen olivat valmiina tappamaan kolmannen osan ihmisistä.'),
(1699787,58,66,9,16,'Ja ratsuväen joukkojen luku oli kaksikymmentä tuhatta kertaa kymmenen tuhatta; minä kuulin niiden luvun.'),
(1699788,58,66,9,17,'Ja tämänkaltaisilta minusta näyttivät hevoset ja niiden selässä istujat näyssä: ratsastajilla oli tulipunaiset ja tummansinervät ja tulikivenkeltaiset haarniskat; ja hevosten päät olivat kuin leijonain päät, ja niiden suusta lähti tuli ja savu ja tulikivi.'),
(1699789,58,66,9,18,'Näistä kolmesta vitsauksesta sai kolmas osa ihmisiä surmansa: tulesta ja savusta ja tulikivestä, jotka lähtivät niiden suusta.'),
(1699790,58,66,9,19,'Sillä hevosten voima oli niiden suussa ja niiden hännässä; niiden hännät näet olivat käärmeitten kaltaiset, ja niissä oli päät, joilla ne vahingoittivat.'),
(1699791,58,66,9,20,'Ja jäljelle jääneet ihmiset, ne, joita ei tapettu näillä vitsauksilla, eivät tehneet parannusta kättensä teoista, niin että olisivat lakanneet kumartamasta riivaajia ja kultaisia ja hopeaisia ja vaskisia ja kivisiä ja puisia epäjumalankuvia, jotka eivät voi nähdä eikä kuulla eikä kävellä.'),
(1699792,58,66,9,21,'He eivät tehneet parannusta murhistaan eikä velhouksistaan eikä haureudestaan eikä varkauksistaan.'),
(1699793,58,66,10,1,'Ja minä näin erään toisen, väkevän enkelin tulevan alas taivaasta; hänen verhonaan oli pilvi, ja taivaankaari oli hänen päänsä päällä, ja hänen kasvonsa olivat niinkuin aurinko, ja hänen jalkansa niinkuin tulipatsaat,'),
(1699794,58,66,10,2,'ja hänellä oli kädessään avattu kirjanen. Ja hän laski oikean jalkansa meren päälle ja vasemman maan päälle'),
(1699795,58,66,10,3,'ja huusi suurella äänellä, niinkuin leijona ärjyy; ja kun hän huusi, antoivat ne seitsemän ukkosen jylinää ääntensä puhua.'),
(1699796,58,66,10,4,'Ja kun ne seitsemän ukkosenjylinää olivat puhuneet, yritin minä kirjoittaa, mutta minä kuulin äänen taivaasta sanovan: "Pane sinetin taakse, mitä ne seitsemän ukkosenjylinää puhuivat, äläkä sitä kirjoita".'),
(1699797,58,66,10,5,'Ja enkeli, jonka minä näin seisovan meren päällä ja maan päällä, kohotti oikean kätensä taivasta kohti'),
(1699798,58,66,10,6,'ja vannoi hänen kauttansa, joka elää aina ja iankaikkisesti, hänen, joka on luonut taivaan ja mitä siinä on, ja maan ja mitä siinä on, ja meren ja mitä siinä on, ettei enää ole oleva aikaa,'),
(1699799,58,66,10,7,'vaan että niinä päivinä, jolloin seitsemännen enkelin ääni kuuluu hänen puhaltaessaan pasunaan, Jumalan salaisuus käy täytäntöön sen hyvän sanoman mukaan, jonka hän on ilmoittanut palvelijoillensa profeetoille.'),
(1699800,58,66,10,8,'Ja sen äänen, jonka minä olin kuullut taivaasta, kuulin taas puhuvan minulle ja sanovan: "Mene ja ota tuo avattu kirjakäärö, joka on meren ja maan päällä seisovan enkelin kädessä".'),
(1699801,58,66,10,9,'Ja minä menin enkelin tykö ja pyysin, että hän antaisi minulle sen kirjasen. Ja hän sanoi minulle: "Ota ja syö se; se on karvasteleva vatsassasi, mutta suussasi se on oleva makea kuin hunaja".'),
(1699802,58,66,10,10,'Niin minä otin kirjasen enkelin kädestä ja söin sen; se oli minun suussani makea kuin hunaja; mutta sen syötyäni minun vatsaani karvasteli.'),
(1699803,58,66,10,11,'Ja minulle sanottiin: "Sinun tulee taas profetoida monista kansoista ja kansanheimoista ja kielistä ja kuninkaista".'),
(1699804,58,66,11,1,'Ja minulle annettiin sauvan kaltainen ruoko ja sanottiin: "Nouse ja mittaa Jumalan temppeli ja alttari ja ne, jotka siinä kumartaen rukoilevat.'),
(1699805,58,66,11,2,'Mutta temppelin ulkopuolella oleva esikartano erota pois, äläkä sitä mittaa, sillä se on annettu pakanakansoille; ja he tallaavat pyhää kaupunkia neljäkymmentäkaksi kuukautta.'),
(1699806,58,66,11,3,'Ja minä annan kahdelle todistajalleni toimeksi säkkipukuihin puettuina profetoida tuhannen kahdensadan kuudenkymmenen päivän ajan."'),
(1699807,58,66,11,4,'Nämä ovat ne kaksi öljypuuta ja ne kaksi lampunjalkaa, jotka seisovat maan Herran edessä.'),
(1699808,58,66,11,5,'Ja jos joku tahtoo heitä vahingoittaa, lähtee tuli heidän suustaan ja kuluttaa heidän vihollisensa; ja jos joku tahtoo heitä vahingoittaa, on hän saava surmansa sillä tavalla.'),
(1699809,58,66,11,6,'Heillä on valta sulkea taivas, niin ettei sadetta tule heidän profetoimisensa päivinä, ja heillä on valta muuttaa vedet vereksi ja lyödä maata kaikkinaisilla vitsauksilla, niin usein kuin tahtovat.'),
(1699810,58,66,11,7,'Ja kun he ovat lopettaneet todistamisensa, on peto, se, joka nousee syvyydestä, käyvä sotaa heitä vastaan ja voittava heidät ja tappava heidät.'),
(1699811,58,66,11,8,'Ja heidän ruumiinsa viruvat sen suuren kaupungin kadulla, jota hengellisesti puhuen kutsutaan Sodomaksi ja Egyptiksi ja jossa myös heidän Herransa ristiinnaulittiin.'),
(1699812,58,66,11,9,'Ja ihmiset eri kansoista ja sukukunnista ja kielistä ja kansanheimoista näkevät heidän ruumiinsa kolme ja puoli päivää, eivätkä salli, että heidän ruumiinsa pannaan hautaan.'),
(1699813,58,66,11,10,'Ja ne, jotka maan päällä asuvat, iloitsevat heidän kohtalostaan ja riemuitsevat ja lähettävät lahjoja toisilleen; sillä nämä kaksi profeettaa olivat vaivanneet niitä, jotka maan päällä asuvat.'),
(1699814,58,66,11,11,'Ja niiden kolmen ja puolen päivän kuluttua meni heihin Jumalasta elämän henki, ja he nousivat jaloilleen, ja suuri pelko valtasi ne, jotka näkivät heidät.'),
(1699815,58,66,11,12,'Ja he kuulivat suuren äänen taivaasta sanovan heille: "Nouskaa tänne!" Niin he nousivat taivaaseen pilvessä, ja heidän vihollisensa näkivät heidät.'),
(1699816,58,66,11,13,'Ja sillä hetkellä tapahtui suuri maanjäristys, ja kymmenes osa kaupunkia kukistui, ja maanjäristyksessä sai surmansa seitsemäntuhatta henkeä, ja muut peljästyivät ja antoivat taivaan Jumalalle kunnian.'),
(1699817,58,66,11,14,'Toinen "voi!" on mennyt; katso, kolmas "voi!" tulee pian.'),
(1699818,58,66,11,15,'Ja seitsemäs enkeli puhalsi pasunaan; niin kuului taivaassa suuria ääniä, jotka sanoivat: "Maailman kuninkuus on tullut meidän Herrallemme ja hänen Voidellullensa, ja hän on hallitseva aina ja iankaikkisesti".'),
(1699819,58,66,11,16,'Ja ne kaksikymmentä neljä vanhinta, jotka istuivat valtaistuimillaan Jumalan edessä, lankesivat kasvoillensa ja kumartaen rukoilivat Jumalaa,'),
(1699820,58,66,11,17,'sanoen: "Me kiitämme sinua, Herra Jumala, Kaikkivaltias, joka olet ja joka olit, siitä, että olet ottanut suuren voimasi ja ottanut hallituksen.'),
(1699821,58,66,11,18,'Ja pakanakansat ovat vihastuneet, mutta sinun vihasi on tullut, ja tullut on aika tuomita kuolleet ja maksaa palkka sinun palvelijoillesi profeetoille ja pyhille ja niille, jotka sinun nimeäsi pelkäävät, pienille ja suurille, ja turmella ne, jotka maan turmelevat."'),
(1699822,58,66,11,19,'Ja Jumalan temppeli taivaassa aukeni, ja hänen liittonsa arkki näkyi hänen temppelissään, ja tuli salamoita ja ääniä ja ukkosenjylinää ja maanjäristystä ja suuria rakeita.'),
(1699823,58,66,12,1,'Ja näkyi suuri merkki taivaassa: vaimo, vaatetettu auringolla, ja kuu hänen jalkojensa alla, ja hänen päässään seppeleenä kaksitoista tähteä.'),
(1699824,58,66,12,2,'Hän oli raskaana ja huusi synnytyskivuissaan, ja hänen oli vaikea synnyttää.'),
(1699825,58,66,12,3,'Ja näkyi toinen merkki taivaassa, ja katso: suuri, tulipunainen lohikäärme, jolla oli seitsemän päätä ja kymmenen sarvea, ja sen päissä seitsemän kruunua;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699826,58,66,12,4,'ja sen pyrstö pyyhkäisi pois kolmannen osan taivaan tähtiä ja heitti ne maan päälle. Ja lohikäärme seisoi synnyttämäisillään olevan vaimon edessä nielläkseen hänen lapsensa, kun hän sen synnyttäisi.'),
(1699827,58,66,12,5,'Ja hän synnytti poikalapsen, joka on kaitseva kaikkia pakanakansoja rautaisella valtikalla; ja hänen lapsensa temmattiin Jumalan tykö ja hänen valtaistuimensa tykö.'),
(1699828,58,66,12,6,'Ja vaimo pakeni erämaahan, jossa hänellä oli Jumalan valmistama paikka, että häntä elätettäisiin siellä tuhat kaksisataa kuusikymmentä päivää.'),
(1699829,58,66,12,7,'Ja syttyi sota taivaassa: Miikael ja hänen enkelinsä sotivat lohikäärmettä vastaan; ja lohikäärme ja hänen enkelinsä sotivat,'),
(1699830,58,66,12,8,'mutta eivät voittaneet, eikä heillä enää ollut sijaa taivaassa.'),
(1699831,58,66,12,9,'Ja suuri lohikäärme, se vanha käärme, jota perkeleeksi ja saatanaksi kutsutaan, koko maanpiirin villitsijä, heitettiin maan päälle, ja hänen enkelinsä heitettiin hänen kanssansa.'),
(1699832,58,66,12,10,'Ja minä kuulin suuren äänen taivaassa sanovan: "Nyt on tullut pelastus ja voima ja meidän Jumalamme valtakunta ja hänen Voideltunsa valta, sillä meidän veljiemme syyttäjä, joka yöt ja päivät syytti heitä meidän Jumalamme edessä, on heitetty ulos.'),
(1699833,58,66,12,11,'Ja he ovat voittaneet hänet Karitsan veren kautta ja todistuksensa sanan kautta, eivätkä ole henkeänsä rakastaneet, vaan olleet alttiit kuolemaan asti.'),
(1699834,58,66,12,12,'Sentähden riemuitkaa, taivaat, ja te, jotka niissä asutte! Voi maata ja merta, sillä perkele on astunut alas teidän luoksenne pitäen suurta vihaa, koska hän tietää, että hänellä on vähän aikaa!"'),
(1699835,58,66,12,13,'Ja kun lohikäärme näki olevansa heitetty maan päälle, ajoi hän takaa sitä vaimoa, joka oli poikalapsen synnyttänyt.'),
(1699836,58,66,12,14,'Mutta vaimolle annettiin sen suuren kotkan kaksi siipeä hänen lentääksensä erämaahan sille paikalleen, jossa häntä elätetään aika ja kaksi aikaa ja puoli aikaa poissa käärmeen näkyvistä.'),
(1699837,58,66,12,15,'Ja käärme syöksi kidastansa vaimon jälkeen vettä niinkuin virran, saattaakseen hänet virran vietäväksi.'),
(1699838,58,66,12,16,'Mutta maa auttoi vaimoa: maa avasi suunsa ja nieli virran, jonka lohikäärme oli syössyt kidastansa.'),
(1699839,58,66,12,17,'Ja lohikäärme vihastui vaimoon ja lähti käymään sotaa muita hänen jälkeläisiänsä vastaan, jotka pitävät Jumalan käskyt ja joilla on Jeesuksen todistus.'),
(1699840,58,66,12,18,'Ja se asettui seisomaan meren hiekalle.'),
(1699841,58,66,13,1,'Ja minä näin pedon nousevan merestä; sillä oli kymmenen sarvea ja seitsemän päätä, ja sarvissansa kymmenen kruunua, ja sen päihin oli kirjoitettu pilkkaavia nimiä.'),
(1699842,58,66,13,2,'Ja peto, jonka minä näin, oli leopardin näköinen, ja sen jalat ikäänkuin karhun, ja sen kita niinkuin leijonan kita. Ja lohikäärme antoi sille voimansa ja valtaistuimensa ja suuren vallan.'),
(1699843,58,66,13,3,'Ja minä näin yhden sen päistä olevan ikäänkuin kuoliaaksi haavoitetun, mutta sen kuolinhaava parantui. Ja koko maa seurasi ihmetellen petoa.'),
(1699844,58,66,13,4,'Ja he kumarsivat lohikäärmettä, koska se oli antanut sellaisen vallan pedolle, ja kumarsivat petoa sanoen: "Kuka on pedon vertainen, ja kuka voi sotia sitä vastaan?"'),
(1699845,58,66,13,5,'Ja sille annettiin suu puhua suuria sanoja ja pilkkapuheita, ja sille annettiin valta tehdä sitä neljäkymmentä kaksi kuukautta.'),
(1699846,58,66,13,6,'Ja se avasi suunsa Jumalaa pilkkaamaan, pilkatakseen hänen nimeänsä ja hänen majaansa, niitä, jotka taivaassa asuvat.'),
(1699847,58,66,13,7,'Ja sille annettiin valta käydä sotaa pyhiä vastaan ja voittaa heidät, ja sen valtaan annettiin kaikki sukukunnat ja kansat ja kielet ja kansanheimot.'),
(1699848,58,66,13,8,'Ja kaikki maan päällä asuvaiset kumartavat sitä, jokainen, jonka nimi ei ole kirjoitettu teurastetun Karitsan elämänkirjaan, hamasta maailman perustamisesta.'),
(1699849,58,66,13,9,'Jos kenellä on korva, hän kuulkoon.'),
(1699850,58,66,13,10,'Jos kuka vankeuteen vie, niin hän itse vankeuteen joutuu; jos kuka miekalla tappaa, hänet pitää miekalla tapettaman. Tässä on pyhien kärsivällisyys ja usko.'),
(1699851,58,66,13,11,'Ja minä näin toisen pedon nousevan maasta, ja sillä oli kaksi sarvea niinkuin karitsan sarvet, ja se puhui niinkuin lohikäärme.'),
(1699852,58,66,13,12,'Ja se käyttää kaikkea ensimmäisen pedon valtaa sen nähden ja saattaa maan ja siinä asuvaiset kumartamaan ensimmäistä petoa, sitä, jonka kuolinhaava parani.'),
(1699853,58,66,13,13,'Ja se tekee suuria ihmeitä, niin että saa tulenkin taivaasta lankeamaan maahan ihmisten nähden.'),
(1699854,58,66,13,14,'Ja se villitsee maan päällä asuvaiset niillä ihmeillä, joita sen sallittiin tehdä pedon nähden; se yllyttää maan päällä asuvaiset tekemään sen pedon kuvan, jossa oli miekanhaava ja joka virkosi.'),
(1699855,58,66,13,15,'Ja sille annettiin valta antaa pedon kuvalle henki, että pedon kuva puhuisikin ja saisi aikaan, että ketkä vain eivät kumartaneet pedon kuvaa, ne tapettaisiin.'),
(1699856,58,66,13,16,'Ja se saa kaikki, pienet ja suuret, sekä rikkaat että köyhät, sekä vapaat että orjat, panemaan merkin oikeaan käteensä tai otsaansa,'),
(1699857,58,66,13,17,'ettei kukaan muu voisi ostaa eikä myydä kuin se, jossa on merkki: pedon nimi tai sen nimen luku.'),
(1699858,58,66,13,18,'Tässä on viisaus. Jolla ymmärrys on, se laskekoon pedon luvun; sillä se on ihmisen luku. Ja sen luku on kuusisataa kuusikymmentä kuusi.'),
(1699859,58,66,14,1,'Ja minä näin, ja katso, Karitsa seisoi Siionin vuorella, ja hänen kanssaan sata neljäkymmentä neljä tuhatta, joiden otsaan oli kirjoitettu hänen nimensä ja hänen Isänsä nimi.'),
(1699860,58,66,14,2,'Ja minä kuulin äänen taivaasta ikäänkuin paljojen vetten pauhinan ja ikäänkuin suuren ukkosenjylinän, ja ääni, jonka minä kuulin, oli ikäänkuin kanteleensoittajain, kun he kanteleitaan soittavat.'),
(1699861,58,66,14,3,'Ja he veisasivat uutta virttä valtaistuimen edessä ja neljän olennon ja vanhinten edessä; eikä kukaan voinut oppia sitä virttä, paitsi ne sata neljäkymmentä neljä tuhatta, jotka ovat ostetut maasta.'),
(1699862,58,66,14,4,'Nämä ovat ne, jotka eivät ole saastuttaneet itseään naisten kanssa; sillä he ovat niinkuin neitsyet. Nämä ovat ne, jotka seuraavat Karitsaa, mihin ikinä hän menee. Nämä ovat ostetut ihmisistä esikoiseksi Jumalalle ja Karitsalle,'),
(1699863,58,66,14,5,'eikä heidän suussaan ole valhetta havaittu; he ovat tahrattomat.'),
(1699864,58,66,14,6,'Ja minä näin lentävän keskitaivaalla erään toisen enkelin, jolla oli iankaikkinen evankeliumi julistettavana maan päällä asuvaisille, kaikille kansanheimoille ja sukukunnille ja kielille ja kansoille.'),
(1699865,58,66,14,7,'Ja hän sanoi suurella äänellä: "Peljätkää Jumalaa ja antakaa hänelle kunnia, sillä hänen tuomionsa hetki on tullut, ja kumartakaa häntä, joka on tehnyt taivaan ja maan ja meren ja vetten lähteet".'),
(1699866,58,66,14,8,'Ja seurasi vielä toinen enkeli, joka sanoi: "Kukistunut, kukistunut on se suuri Babylon, joka haureutensa vihan viinillä on juottanut kaikki kansat".'),
(1699867,58,66,14,9,'Ja heitä seurasi vielä kolmas enkeli, joka sanoi suurella äänellä: "Jos joku kumartaa petoa ja sen kuvaa ja ottaa sen merkin otsaansa tai käteensä,'),
(1699868,58,66,14,10,'niin hänkin on juova Jumalan vihan viiniä, joka sekoittamattomana on kaadettu hänen vihansa maljaan, ja häntä pitää tulella ja tulikivellä vaivattaman pyhien enkelien edessä ja Karitsan edessä.'),
(1699869,58,66,14,11,'Ja heidän vaivansa savu on nouseva aina ja iankaikkisesti, eikä heillä ole lepoa päivällä eikä yöllä, heillä, jotka petoa ja sen kuvaa kumartavat, eikä kenelläkään, joka ottaa sen nimen merkin.'),
(1699870,58,66,14,12,'Tässä on pyhien kärsivällisyys, niiden, jotka pitävät Jumalan käskyt ja Jeesuksen uskon.'),
(1699871,58,66,14,13,'Ja minä kuulin äänen taivaasta sanovan: "Kirjoita: Autuaat ovat ne kuolleet, jotka Herrassa kuolevat tästedes. Totisesti - sanoo Henki - he saavat levätä vaivoistansa, sillä heidän tekonsa seuraavat heitä."'),
(1699872,58,66,14,14,'Ja minä näin, ja katso: valkoinen pilvi, ja pilvellä istui Ihmisen Pojan muotoinen, päässänsä kultainen kruunu ja kädessänsä terävä sirppi.'),
(1699873,58,66,14,15,'Ja temppelistä tuli eräs toinen enkeli huutaen suurella äänellä pilvellä istuvalle: "Lähetä sirppisi ja leikkaa, sillä leikkuuaika on tullut, ja maan elo on kypsynyt".'),
(1699874,58,66,14,16,'Ja pilvellä istuva heitti sirppinsä maan päälle, ja maa tuli leikatuksi.'),
(1699875,58,66,14,17,'Ja taivaan temppelistä lähti eräs toinen enkeli, ja hänelläkin oli terävä sirppi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699876,58,66,14,18,'Ja alttarista lähti vielä toinen enkeli, jolla oli tuli vallassaan, ja hän huusi suurella äänellä sille, jolla oli se terävä sirppi, sanoen: "Lähetä terävä sirppisi ja korjaa tertut maan viinipuusta, sillä sen rypäleet ovat kypsyneet".'),
(1699877,58,66,14,19,'Ja enkeli heitti sirppinsä alas maahan ja korjasi maan viinipuun hedelmät ja heitti ne Jumalan vihan suureen kuurnaan.'),
(1699878,58,66,14,20,'Ja kuurna poljettiin kaupungin ulkopuolella, ja kuurnasta kuohui veri hevosten kuolaimiin asti, tuhannen kuudensadan vakomitan päähän.'),
(1699879,58,66,15,1,'Ja minä näin toisen tunnusmerkin taivaassa, suuren ja ihmeellisen: seitsemän enkeliä, joilla oli seitsemän viimeistä vitsausta, sillä niissä Jumalan viha täyttyy.'),
(1699880,58,66,15,2,'Ja minä näin ikäänkuin lasisen meren, tulella sekoitetun, ja niiden, jotka olivat saaneet voiton pedosta ja sen kuvasta ja sen nimen luvusta, seisovan sillä lasisella merellä, ja heillä oli Jumalan kanteleet.'),
(1699881,58,66,15,3,'Ja he veisasivat Mooseksen, Jumalan palvelijan, virttä ja Karitsan virttä, sanoen: "Suuret ja ihmeelliset ovat sinun tekosi, Herra Jumala, Kaikkivaltias; vanhurskaat ja totiset ovat sinun tiesi, sinä kansojen kuningas.'),
(1699882,58,66,15,4,'Kuka ei pelkäisi, Herra, ja ylistäisi sinun nimeäsi? Sillä sinä yksin olet Pyhä; sillä kaikki kansat tulevat ja kumartavat sinua, koska sinun vanhurskaat tuomiosi ovat julki tulleet."'),
(1699883,58,66,15,5,'Ja sen jälkeen minä näin: todistuksen majan temppeli taivaassa avattiin;'),
(1699884,58,66,15,6,'ja ne seitsemän enkeliä, joilla oli ne seitsemän vitsausta, lähtivät temppelistä, puettuina puhtaisiin, hohtaviin pellavavaatteisiin ja rinnoilta vyötettyinä kultaisilla vöillä.'),
(1699885,58,66,15,7,'Ja yksi niistä neljästä olennosta antoi niille seitsemälle enkelille seitsemän kultaista maljaa, täynnä Jumalan vihaa, hänen, joka elää aina ja iankaikkisesti.'),
(1699886,58,66,15,8,'Ja temppeli tuli savua täyteen Jumalan kirkkaudesta ja hänen voimastansa, eikä kukaan voinut mennä sisälle temppeliin, ennenkuin niiden seitsemän enkelin seitsemän vitsausta oli käynyt täytäntöön.'),
(1699887,58,66,16,1,'Ja minä kuulin suuren äänen temppelistä sanovan niille seitsemälle enkelille: "Menkää ja vuodattakaa ne seitsemän Jumalan vihan maljaa maan päälle".'),
(1699888,58,66,16,2,'Ja ensimmäinen lähti ja vuodatti maljansa maan päälle; ja tuli pahoja ja ilkeitä paiseita niihin ihmisiin, joissa oli pedon merkki ja jotka kumarsivat sen kuvaa.'),
(1699889,58,66,16,3,'Ja toinen enkeli vuodatti maljansa mereen, ja se tuli vereksi, ikäänkuin kuolleen vereksi, ja jokainen elävä olento kuoli, mitä meressä oli.'),
(1699890,58,66,16,4,'Ja kolmas enkeli vuodatti maljansa jokiin ja vesilähteisiin, ja ne tulivat vereksi.'),
(1699891,58,66,16,5,'Ja minä kuulin vetten enkelin sanovan: "Vanhurskas olet sinä, joka olet ja joka olit, sinä Pyhä, kun näin olet tuominnut.'),
(1699892,58,66,16,6,'Sillä pyhien ja profeettain verta he ovat vuodattaneet, ja verta sinä olet antanut heille juoda; sen he ovat ansainneet."'),
(1699893,58,66,16,7,'Ja minä kuulin alttarin sanovan: "Totisesti, Herra Jumala, Kaikkivaltias, totiset ja vanhurskaat ovat sinun tuomiosi".'),
(1699894,58,66,16,8,'Ja neljäs enkeli vuodatti maljansa aurinkoon, ja sille annettiin valta paahtaa ihmisiä tulella.'),
(1699895,58,66,16,9,'Ja ihmiset paahtuivat kovassa helteessä ja pilkkasivat Jumalan nimeä, hänen, jolla on vallassaan nämä vitsaukset; mutta he eivät tehneet parannusta, niin että olisivat antaneet hänelle kunnian.'),
(1699896,58,66,16,10,'Ja viides enkeli vuodatti maljansa pedon valtaistuimelle, ja sen valtakunta pimeni; ja he pureskelivat kielensä rikki tuskissansa'),
(1699897,58,66,16,11,'ja pilkkasivat taivaan Jumalaa tuskiensa ja paiseittensa tähden, mutta eivät tehneet parannusta teoistansa.'),
(1699898,58,66,16,12,'Ja kuudes enkeli vuodatti maljansa suureen Eufrat-virtaan, ja sen vesi kuivui, että tie valmistuisi auringon noususta tuleville kuninkaille.'),
(1699899,58,66,16,13,'Ja minä näin lohikäärmeen suusta ja pedon suusta ja väärän profeetan suusta lähtevän kolme saastaista henkeä, sammakon muotoista.'),
(1699900,58,66,16,14,'Sillä ne ovat riivaajain henkiä, jotka tekevät ihmeitä; ne lähtevät koko maanpiirin kuningasten luo kokoamaan heidät sotaan Jumalan, Kaikkivaltiaan, suurena päivänä.'),
(1699901,58,66,16,15,'- Katso, minä tulen niinkuin varas; autuas se, joka valvoo ja pitää vaatteistansa vaarin, ettei hän kulkisi alastomana eikä hänen häpeätänsä nähtäisi! -'),
(1699902,58,66,16,16,'Ja ne kokosivat heidät siihen paikkaan, jonka nimi hebreaksi on Harmagedon.'),
(1699903,58,66,16,17,'Ja seitsemäs enkeli vuodatti maljansa ilmaan, ja temppelistä, valtaistuimelta, lähti suuri ääni, joka sanoi: "Se on tapahtunut".'),
(1699904,58,66,16,18,'Ja tuli salamoita ja ääniä ja ukkosenjylinää; ja tuli suuri maanjäristys, niin ankara ja suuri maanjäristys, ettei sen vertaista ole ollut siitä asti, kuin ihmisiä on ollut maan päällä.'),
(1699905,58,66,16,19,'Ja se suuri kaupunki meni kolmeen osaan, ja kansojen kaupungit kukistuivat. Ja se suuri Babylon tuli muistetuksi Jumalan edessä, niin että hän antoi sille vihansa kiivauden viinimaljan.'),
(1699906,58,66,16,20,'Ja kaikki saaret pakenivat, eikä vuoria enää ollut.'),
(1699907,58,66,16,21,'Ja suuria rakeita, leiviskän painoisia, satoi taivaasta ihmisten päälle; ja ihmiset pilkkasivat Jumalaa raesateen vitsauksen tähden, sillä se vitsaus oli ylen suuri.'),
(1699908,58,66,17,1,'Ja tuli yksi niistä seitsemästä enkelistä, joilla oli ne seitsemän maljaa, ja puhui minulle sanoen: "Tule, minä näytän sinulle sen suuren porton tuomion, joka istuu paljojen vetten päällä,'),
(1699909,58,66,17,2,'hänen, jonka kanssa maan kuninkaat ovat haureutta harjoittaneet ja jonka haureuden viinistä maan asukkaat ovat juopuneet".'),
(1699910,58,66,17,3,'Ja hän vei minut hengessä erämaahan. Siellä minä näin naisen istuvan helakanpunaisen pedon selässä; peto oli täynnä pilkkaavia nimiä, ja sillä oli seitsemän päätä ja kymmenen sarvea.'),
(1699911,58,66,17,4,'Ja nainen oli puettu purppuraan ja helakanpunaan ja koristettu kullalla ja jalokivillä ja helmillä ja piti kädessään kultaista maljaa, joka oli täynnä kauhistuksia ja hänen haureutensa riettauksia.'),
(1699912,58,66,17,5,'Ja hänen otsaansa oli kirjoitettu nimi, salaisuus: "Suuri Babylon, maan porttojen ja kauhistuksien äiti".'),
(1699913,58,66,17,6,'Ja minä näin sen naisen olevan juovuksissa pyhien verestä ja Jeesuksen todistajain verestä; ja nähdessäni hänet minä suuresti ihmettelin.'),
(1699914,58,66,17,7,'Ja enkeli sanoi minulle: "Miksi ihmettelet? Minä sanon sinulle tuon naisen salaisuuden ja tuon pedon salaisuuden, joka häntä kantaa ja jolla on seitsemän päätä ja kymmenen sarvea.'),
(1699915,58,66,17,8,'Peto, jonka sinä näit, on ollut, eikä sitä enää ole, mutta se on nouseva syvyydestä ja menevä kadotukseen; ja ne maan päällä asuvaiset, joiden nimet eivät ole kirjoitetut elämän kirjaan, hamasta maailman perustamisesta, ihmettelevät, kun he näkevät pedon, että se on ollut eikä sitä enää ole, mutta se on tuleva.'),
(1699916,58,66,17,9,'Tässä on ymmärrys, jossa viisaus on: Ne seitsemän päätä ovat seitsemän vuorta, joiden päällä nainen istuu; ne ovat myös seitsemän kuningasta;'),
(1699917,58,66,17,10,'heistä on viisi kaatunut, yksi on, viimeinen ei ole vielä tullut, ja kun hän tulee, pitää hänen vähän aikaa pysymän.'),
(1699918,58,66,17,11,'Ja peto, joka on ollut ja jota ei enää ole, on itse kahdeksas, ja on yksi noista seitsemästä, ja menee kadotukseen.'),
(1699919,58,66,17,12,'Ja ne kymmenen sarvea, jotka sinä näit, ovat kymmenen kuningasta, jotka eivät vielä ole saaneet kuninkuutta, mutta saavat vallan niinkuin kuninkaat yhdeksi hetkeksi pedon kanssa.'),
(1699920,58,66,17,13,'Näillä on yksi ja sama mieli, ja he antavat voimansa ja valtansa pedolle.'),
(1699921,58,66,17,14,'He sotivat Karitsaa vastaan, mutta Karitsa on voittava heidät, sillä hän on herrain Herra ja kuningasten Kuningas; ja kutsutut ja valitut ja uskolliset voittavat hänen kanssansa."'),
(1699922,58,66,17,15,'Ja hän sanoi minulle: "Vedet, jotka sinä näit, tuolla, missä portto istuu, ovat kansoja ja väkijoukkoja ja kansanheimoja ja kieliä.'),
(1699923,58,66,17,16,'Ja ne kymmenen sarvea, jotka sinä näit, ja peto, ne vihaavat porttoa ja riisuvat hänet paljaaksi ja alastomaksi ja syövät hänen lihansa ja polttavat hänet tulessa.'),
(1699924,58,66,17,17,'Sillä Jumala on pannut heidän sydämeensä, että he täyttävät hänen aivoituksensa, yksimielisesti, ja antavat kuninkuutensa pedolle, kunnes Jumalan sanat täyttyvät.'),
(1699925,58,66,17,18,'Ja nainen, jonka sinä näit, on se suuri kaupunki, jolla on maan kuninkaitten kuninkuus."');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699926,58,66,18,1,'Sen jälkeen minä näin tulevan taivaasta alas erään toisen enkelin, jolla oli suuri valta, ja maa valkeni hänen kirkkaudestaan.'),
(1699927,58,66,18,2,'Ja hän huusi voimallisella äänellä sanoen: "Kukistunut, kukistunut on suuri Babylon ja tullut riivaajain asuinpaikaksi ja kaikkien saastaisten henkien tyyssijaksi ja kaikkien saastaisten ja vihattavain lintujen tyyssijaksi.'),
(1699928,58,66,18,3,'Sillä hänen haureutensa vihan viiniä ovat kaikki kansat juoneet, ja maan kuninkaat ovat haureutta harjoittaneet hänen kanssansa, ja maan kauppiaat ovat rikastuneet hänen hekumansa runsaudesta."'),
(1699929,58,66,18,4,'Ja minä kuulin toisen äänen taivaasta sanovan: "Lähtekää siitä ulos, te minun kansani, ettette tulisi hänen synteihinsä osallisiksi ja saisi tekin kärsiä hänen vitsauksistansa.'),
(1699930,58,66,18,5,'Sillä hänen syntinsä ulottuvat taivaaseen asti, ja Jumala on muistanut hänen rikoksensa.'),
(1699931,58,66,18,6,'Kostakaa hänelle sen mukaan, kuin hän on tehnyt, ja antakaa hänelle kaksinkertaisesti hänen teoistansa; siihen maljaan, johon hän on kaatanut, kaatakaa te hänelle kaksin verroin.'),
(1699932,58,66,18,7,'Niin paljon kuin hän on itselleen kunniaa ja hekumaa hankkinut, niin paljon antakaa hänelle vaivaa ja surua. Koska hän sanoo sydämessään: ''Minä istun kuningattarena enkä ole leski enkä ole surua näkevä'','),
(1699933,58,66,18,8,'sentähden hänen vitsauksensa tulevat yhtenä päivänä: kuolema ja suru ja nälkä, ja hän joutuu tulessa poltettavaksi, sillä väkevä on Herra Jumala, joka on hänet tuominnut."'),
(1699934,58,66,18,9,'Ja maanpiirin kuninkaat, jotka hänen kanssansa ovat haureutta harjoittaneet ja hekumallisesti eläneet, itkevät ja parkuvat häntä, kun näkevät hänen palonsa savun;'),
(1699935,58,66,18,10,'he seisovat loitolla kauhistuen hänen vaivaansa ja sanovat: "Voi, voi sinua, Babylon, sinä suuri kaupunki, sinä vahva kaupunki, sillä sinun tuomiosi tuli yhdessä hetkessä!"'),
(1699936,58,66,18,11,'Ja maanpiirin kauppiaat itkevät ja surevat häntä, kun ei kukaan enää osta heidän tavaraansa,'),
(1699937,58,66,18,12,'kaupaksi tuotua kultaa ja hopeata ja jalokiviä ja helmiä ja pellavakangasta ja purppuraa ja silkkiä ja helakanpunaa ja kaikkinaista hajupuuta ja kaikenlaisia norsunluu-esineitä ja kaikenlaisia kalleimmasta puusta ja vaskesta ja raudasta ja marmorista tehtyjä esineitä,'),
(1699938,58,66,18,13,'ja kanelia ja hiusvoidetta ja suitsuketta ja hajuvoidetta ja suitsutuspihkaa ja viiniä ja öljyä ja lestyjä jauhoja ja viljaa ja karjaa ja lampaita ja hevosia ja vaunuja ja orjia ja ihmissieluja.'),
(1699939,58,66,18,14,'Ja hedelmät, joita sinun sielusi himoitsi, ovat sinulta menneet, ja kaikki kalleutesi ja komeutesi ovat sinulta hävinneet, eikä niitä enää koskaan löydetä.'),
(1699940,58,66,18,15,'Niiden kauppiaat, ne, jotka rikastuivat tästä kaupungista, seisovat loitolla kauhistuen hänen vaivaansa, itkien ja surren,'),
(1699941,58,66,18,16,'ja sanovat: "Voi, voi sitä suurta kaupunkia, joka oli puettu pellavaan ja purppuraan ja helakanpunaan ja koristettu kullalla ja jalokivillä ja helmillä, kun semmoinen rikkaus yhdessä hetkessä tuhoutui!"'),
(1699942,58,66,18,17,'Ja kaikki laivurit ja kaikki rannikkopurjehtijat ja merimiehet ja kaikki merenkulkijat seisoivat loitolla'),
(1699943,58,66,18,18,'ja huusivat nähdessään hänen palonsa savun ja sanoivat: "Mikä on tämän suuren kaupungin vertainen?"'),
(1699944,58,66,18,19,'Ja he heittivät tomua päänsä päälle ja huusivat itkien ja surren ja sanoivat: "Voi, voi sitä suurta kaupunkia, jonka kalleuksista rikastuivat kaikki, joilla oli laivoja merellä, kun se yhdessä hetkessä tuhoutui!"'),
(1699945,58,66,18,20,'Riemuitse hänestä, taivas, ja te pyhät ja apostolit ja profeetat; sillä Jumala on hänet tuominnut ja kostanut hänelle teidän tuomionne.'),
(1699946,58,66,18,21,'Ja väkevä enkeli otti kiven, niinkuin suuren myllynkiven, ja heitti sen mereen sanoen: "Näin heitetään kiivaasti pois Babylon, se suuri kaupunki, eikä sitä enää löydetä".'),
(1699947,58,66,18,22,'Ei kuulla sinussa enää kanteleensoittajain ja laulajain, huilun- ja torvensoittajain ääntä; ei löydetä sinusta enää minkään ammatin taituria; ei kuulla sinussa enää myllyn jyrinää;'),
(1699948,58,66,18,23,'ei loista sinussa enää lampun valo; ei kuulla sinussa enää huutoa yljälle eikä huutoa morsiamelle; sillä sinun kauppiaasi olivat maan mahtavia, ja sinun velhoutesi villitsi kaikki kansat;'),
(1699949,58,66,18,24,'ja hänestä on löydetty profeettain ja pyhien veri ja kaikkien veri, jotka maan päällä ovat tapetut.'),
(1699950,58,66,19,1,'Sen jälkeen minä kuulin ikäänkuin kansan paljouden suuren äänen taivaassa sanovan: "Halleluja! Pelastus ja kunnia ja voima on Jumalan, meidän Jumalamme.'),
(1699951,58,66,19,2,'Sillä totiset ja vanhurskaat ovat hänen tuomionsa; sillä hän on tuominnut sen suuren porton, joka turmeli maan haureudellaan, ja on kostanut ja on vaatinut hänen kädestänsä palvelijainsa veren."'),
(1699952,58,66,19,3,'Ja he sanoivat toistamiseen: "Halleluja!" Ja hänen savunsa nousee aina ja iankaikkisesti.'),
(1699953,58,66,19,4,'Ja ne kaksikymmentä neljä vanhinta ja neljä olentoa lankesivat maahan ja kumartaen rukoilivat Jumalaa, joka valtaistuimella istuu, ja sanoivat: "Amen, halleluja!"'),
(1699954,58,66,19,5,'Ja valtaistuimelta lähti ääni, joka sanoi: "Ylistäkää meidän Jumalaamme, kaikki hänen palvelijansa, te, jotka häntä pelkäätte, sekä pienet että suuret".'),
(1699955,58,66,19,6,'Ja minä kuulin ikäänkuin kansan paljouden äänen ja ikäänkuin paljojen vetten pauhinan ja ikäänkuin suuren ukkosenjylinän sanovan: "Halleluja! Sillä Herra, meidän Jumalamme, Kaikkivaltias, on ottanut hallituksen.'),
(1699956,58,66,19,7,'Iloitkaamme ja riemuitkaamme ja antakaamme kunnia hänelle, sillä Karitsan häät ovat tulleet, ja hänen vaimonsa on itsensä valmistanut.'),
(1699957,58,66,19,8,'Ja hänen annettiin pukeutua liinavaatteeseen, hohtavaan ja puhtaaseen: se liina on pyhien vanhurskautus."'),
(1699958,58,66,19,9,'Ja hän sanoi minulle: "Kirjoita: Autuaat ne, jotka ovat kutsutut Karitsan hääaterialle!" Vielä hän sanoi minulle: "Nämä sanat ovat totiset Jumalan sanat".'),
(1699959,58,66,19,10,'Ja minä lankesin hänen jalkojensa juureen, kumartaen rukoillakseni häntä. Mutta hän sanoi minulle: "Varo, ettet sitä tee; minä olen sinun ja sinun veljiesi kanssapalvelija, niiden, joilla on Jeesuksen todistus; kumarra ja rukoile Jumalaa. Sillä Jeesuksen todistus on profetian henki."'),
(1699960,58,66,19,11,'Ja minä näin taivaan auenneena. Ja katso: valkoinen hevonen, ja sen selässä istuvan nimi on Uskollinen ja Totinen, ja hän tuomitsee ja sotii vanhurskaudessa.'),
(1699961,58,66,19,12,'Ja hänen silmänsä olivat niinkuin tulen liekit, ja hänen päässään oli monta kruunua, ja hänellä oli kirjoitettuna nimi, jota ei tiedä kukaan muu kuin hän itse,'),
(1699962,58,66,19,13,'ja hänellä oli yllään vereen kastettu vaippa, ja nimi, jolla häntä kutsutaan, on Jumalan Sana.'),
(1699963,58,66,19,14,'Ja häntä seurasivat ratsastaen valkoisilla hevosilla taivaan sotajoukot, puettuina valkeaan ja puhtaaseen pellavavaatteeseen.'),
(1699964,58,66,19,15,'Ja hänen suustaan lähtee terävä miekka, että hän sillä löisi kansoja. Ja hän on kaitseva heitä rautaisella valtikalla, ja hän polkee kaikkivaltiaan Jumalan vihan kiivauden viinikuurnan.'),
(1699965,58,66,19,16,'Ja hänellä on vaipassa kupeellaan kirjoitettuna nimi: "Kuningasten Kuningas ja herrain Herra".'),
(1699966,58,66,19,17,'Ja minä näin enkelin seisovan auringossa, ja hän huusi suurella äänellä sanoen kaikille keskitaivaalla lentäville linnuille: "Tulkaa, kokoontukaa Jumalan suurelle aterialle'),
(1699967,58,66,19,18,'syömään kuningasten lihaa ja sotapäällikköjen lihaa ja väkevien lihaa ja hevosten sekä niiden selässä istuvien lihaa ja kaikkien vapaitten ja orjien lihaa, sekä pienten että suurten".'),
(1699968,58,66,19,19,'Ja minä näin pedon ja maan kuninkaat ja heidän sotajoukkonsa kokoontuneina sotiaksensa hevosen selässä istuvaa vastaan ja hänen sotajoukkoansa vastaan.'),
(1699969,58,66,19,20,'Ja peto otettiin kiinni, ja sen kanssa väärä profeetta, joka sen nähden oli tehnyt ihmetekonsa, joilla hän oli eksyttänyt ne, jotka olivat ottaneet pedon merkin, ja ne, jotka olivat sen kuvaa kumartaneet; ne molemmat heitettiin elävältä tuliseen järveen, joka tulikiveä palaa.'),
(1699970,58,66,19,21,'Ja ne muut saivat surmansa hevosen selässä istuvan miekasta, joka lähti hänen suustaan; ja kaikki linnut tulivat ravituiksi heidän lihastansa.'),
(1699971,58,66,20,1,'Ja minä näin tulevan taivaasta alas enkelin, jolla oli syvyyden avain ja suuret kahleet kädessään.'),
(1699972,58,66,20,2,'Ja hän otti kiinni lohikäärmeen, sen vanhan käärmeen, joka on perkele ja saatana, ja sitoi hänet tuhanneksi vuodeksi'),
(1699973,58,66,20,3,'ja heitti hänet syvyyteen ja sulki ja lukitsi sen sinetillä hänen jälkeensä, ettei hän enää kansoja villitsisi, siihen asti kuin ne tuhat vuotta ovat loppuun kuluneet; sen jälkeen hänet pitää päästettämän irti vähäksi aikaa.'),
(1699974,58,66,20,4,'Ja minä näin valtaistuimia, ja he istuivat niille, ja heille annettiin tuomiovalta; ja minä näin niiden sielut, jotka olivat teloitetut Jeesuksen todistuksen ja Jumalan sanan tähden, ja niiden, jotka eivät olleet kumartaneet petoa eikä sen kuvaa eivätkä ottaneet sen merkkiä otsaansa eikä käteensä; ja he virkosivat eloon ja hallitsivat Kristuksen kanssa tuhannen vuotta.'),
(1699975,58,66,20,5,'Muut kuolleet eivät vironneet eloon, ennenkuin ne tuhat vuotta olivat loppuun kuluneet. Tämä on ensimmäinen ylösnousemus.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1699976,58,66,20,6,'Autuas ja pyhä on se, jolla on osa ensimmäisessä ylösnousemuksessa; heihin ei toisella kuolemalla ole valtaa, vaan he tulevat olemaan Jumalan ja Kristuksen pappeja ja hallitsevat hänen kanssaan ne tuhannen vuotta.'),
(1699977,58,66,20,7,'Ja kun ne tuhat vuotta ovat loppuun kuluneet, päästetään saatana vankeudestaan,'),
(1699978,58,66,20,8,'ja hän lähtee villitsemään maan neljällä kulmalla olevia kansoja, Googia ja Maagogia, kootakseen heidät sotaan, ja niiden luku on kuin meren hiekka.'),
(1699979,58,66,20,9,'Ja he nousevat yli maan avaruuden ja piirittävät pyhien leirin ja sen rakastetun kaupungin. Mutta tuli lankeaa taivaasta ja kuluttaa heidät.'),
(1699980,58,66,20,10,'Ja perkele, heidän villitsijänsä, heitetään tuli- ja tulikivijärveen, jossa myös peto ja väärä profeetta ovat, ja heitä vaivataan yöt päivät, aina ja iankaikkisesti.'),
(1699981,58,66,20,11,'Ja minä näin suuren, valkean valtaistuimen ja sillä istuvaisen, jonka kasvoja maa ja taivas pakenivat, eikä niille sijaa löytynyt.'),
(1699982,58,66,20,12,'Ja minä näin kuolleet, suuret ja pienet, seisomassa valtaistuimen edessä, ja kirjat avattiin; ja avattiin toinen kirja, joka on elämän kirja; ja kuolleet tuomittiin sen perusteella, mitä kirjoihin oli kirjoitettu, tekojensa mukaan.'),
(1699983,58,66,20,13,'Ja meri antoi ne kuolleet, jotka siinä olivat, ja Kuolema ja Tuonela antoivat ne kuolleet, jotka niissä olivat, ja heidät tuomittiin, kukin tekojensa mukaan.'),
(1699984,58,66,20,14,'Ja Kuolema ja Tuonela heitettiin tuliseen järveen. Tämä on toinen kuolema, tulinen järvi.'),
(1699985,58,66,20,15,'Ja joka ei ollut elämän kirjaan kirjoitettu, se heitettiin tuliseen järveen.'),
(1699986,58,66,21,1,'Ja minä näin uuden taivaan ja uuden maan; sillä ensimmäinen taivas ja ensimmäinen maa ovat kadonneet, eikä merta enää ole.'),
(1699987,58,66,21,2,'Ja pyhän kaupungin, uuden Jerusalemin, minä näin laskeutuvan alas taivaasta Jumalan tyköä, valmistettuna niinkuin morsian, miehellensä kaunistettu.'),
(1699988,58,66,21,3,'Ja minä kuulin suuren äänen valtaistuimelta sanovan: "Katso, Jumalan maja ihmisten keskellä! Ja hän on asuva heidän keskellänsä, ja he ovat hänen kansansa, ja Jumala itse on oleva heidän kanssaan, heidän Jumalansa;'),
(1699989,58,66,21,4,'ja hän on pyyhkivä pois kaikki kyyneleet heidän silmistänsä, eikä kuolemaa ole enää oleva, eikä murhetta eikä parkua eikä kipua ole enää oleva, sillä kaikki entinen on mennyt."'),
(1699990,58,66,21,5,'Ja valtaistuimella istuva sanoi: "Katso, uudeksi minä teen kaikki". Ja hän sanoi: "Kirjoita, sillä nämä sanat ovat vakaat ja todet".'),
(1699991,58,66,21,6,'Ja hän sanoi minulle: "Se on tapahtunut. Minä olen A ja O, alku ja loppu. Minä annan janoavalle elämän veden lähteestä lahjaksi.'),
(1699992,58,66,21,7,'Joka voittaa, on tämän perivä, ja minä olen oleva hänen Jumalansa, ja hän on oleva minun poikani.'),
(1699993,58,66,21,8,'Mutta pelkurien ja epäuskoisten ja saastaisten ja murhaajien ja huorintekijäin ja velhojen ja epäjumalanpalvelijain ja kaikkien valhettelijain osa on oleva siinä järvessä, joka tulta ja tulikiveä palaa; tämä on toinen kuolema."'),
(1699994,58,66,21,9,'Ja tuli yksi niistä seitsemästä enkelistä, joilla oli ne seitsemän maljaa täynnä seitsemää viimeistä vitsausta, ja puhui minun kanssani sanoen: "Tule tänne, minä näytän sinulle morsiamen, Karitsan vaimon".'),
(1699995,58,66,21,10,'Ja hän vei minut hengessä suurelle ja korkealle vuorelle ja näytti minulle pyhän kaupungin, Jerusalemin, joka laskeutui alas taivaasta Jumalan tyköä,'),
(1699996,58,66,21,11,'ja siinä oli Jumalan kirkkaus; sen hohto oli kaikkein kalleimman kiven kaltainen, niinkuin kristallinkirkas jaspis-kivi;'),
(1699997,58,66,21,12,'siinä oli suuri ja korkea muuri, jossa oli kaksitoista porttia ja porteilla kaksitoista enkeliä, ja niihin oli kirjoitettu nimiä, ja ne ovat Israelin lasten kahdentoista sukukunnan nimet;'),
(1699998,58,66,21,13,'idässä kolme porttia ja pohjoisessa kolme porttia ja etelässä kolme porttia ja lännessä kolme porttia.'),
(1699999,58,66,21,14,'Ja kaupungin muurilla oli kaksitoista perustusta, ja niissä Karitsan kahdentoista apostolin kaksitoista nimeä.'),
(1700000,58,66,21,15,'Ja sillä, joka minulle puhui, oli mittasauvana kultainen ruoko, mitatakseen kaupungin ja sen portit ja sen muurin.'),
(1700001,58,66,21,16,'Ja kaupunki oli neliskulmainen, ja sen pituus oli yhtä suuri kuin sen leveys. Ja hän mittasi sillä ruovolla kaupungin: se oli kaksitoista tuhatta vakomittaa. Sen pituus ja leveys ja korkeus olivat yhtä suuret.'),
(1700002,58,66,21,17,'Ja hän mittasi sen muurin: se oli sata neljäkymmentä neljä kyynärää, ihmismitan mukaan, joka on enkelin mitta.'),
(1700003,58,66,21,18,'Ja sen muuri oli rakennettu jaspiksesta, ja kaupunki oli puhdasta kultaa, puhtaan lasin kaltaista.'),
(1700004,58,66,21,19,'Ja kaupungin muurin perustukset olivat kaunistetut kaikkinaisilla kalleilla kivillä; ensimmäinen perustus oli jaspis, toinen safiiri, kolmas kalkedon, neljäs smaragdi,'),
(1700005,58,66,21,20,'viides sardonyks, kuudes sardion, seitsemäs krysoliitti, kahdeksas berylli, yhdeksäs topaasi, kymmenes krysoprasi, yhdestoista hyasintti, kahdestoista ametisti.'),
(1700006,58,66,21,21,'Ja ne kaksitoista porttia olivat kaksitoista helmeä; kukin portti oli yhdestä helmestä; ja kaupungin katu oli puhdasta kultaa, ikäänkuin läpikuultavaa lasia.'),
(1700007,58,66,21,22,'Mutta temppeliä minä en siinä nähnyt; sillä Herra Jumala, Kaikkivaltias, on sen temppeli, ja Karitsa.'),
(1700008,58,66,21,23,'Eikä kaupunki tarvitse valoksensa aurinkoa eikä kuuta; sillä Jumalan kirkkaus valaisee sen, ja sen lamppu on Karitsa.'),
(1700009,58,66,21,24,'Ja kansat tulevat vaeltamaan sen valkeudessa, ja maan kuninkaat vievät sinne kunniansa.'),
(1700010,58,66,21,25,'Eikä sen portteja suljeta päivällä, ja yötä ei siellä ole,'),
(1700011,58,66,21,26,'ja sinne viedään kansojen kunnia ja kalleudet.'),
(1700012,58,66,21,27,'Eikä sinne ole pääsevä mitään epäpyhää eikä ketään kauhistusten tekijää eikä valhettelijaa, vaan ainoastaan ne, jotka ovat kirjoitetut Karitsan elämänkirjaan.'),
(1700013,58,66,22,1,'Ja hän näytti minulle elämän veden virran, joka kirkkaana kuin kristalli juoksi Jumalan ja Karitsan valtaistuimesta.'),
(1700014,58,66,22,2,'Keskellä sen katua ja virran molemmilla puolilla oli elämän puu, joka kantoi kahdettoista hedelmät, antaen joka kuukausi hedelmänsä, ja puun lehdet ovat kansojen tervehtymiseksi.'),
(1700015,58,66,22,3,'Eikä mitään kirousta ole enää oleva. Ja Jumalan ja Karitsan valtaistuin on siellä oleva, ja hänen palvelijansa palvelevat häntä'),
(1700016,58,66,22,4,'ja näkevät hänen kasvonsa, ja hänen nimensä on heidän otsissansa.'),
(1700017,58,66,22,5,'Eikä yötä ole enää oleva, eivätkä he tarvitse lampun valoa eikä auringon valoa, sillä Herra Jumala on valaiseva heitä, ja he hallitsevat aina ja iankaikkisesti.'),
(1700018,58,66,22,6,'Ja hän sanoi minulle: "Nämä sanat ovat vakaat ja todet, ja Herra, profeettain henkien Jumala, on lähettänyt enkelinsä näyttämään palvelijoilleen, mitä pian tapahtuman pitää.'),
(1700019,58,66,22,7,'Ja katso, minä tulen pian. Autuas se, joka ottaa tämän kirjan ennustuksen sanoista vaarin!"'),
(1700020,58,66,22,8,'Ja minä, Johannes, olen se, joka tämän kuulin ja näin. Ja kun olin sen kuullut ja nähnyt, minä lankesin maahan kumartuakseni sen enkelin jalkojen eteen, joka tämän minulle näytti.'),
(1700021,58,66,22,9,'Ja hän sanoi minulle: "Varo, ettet sitä tee; minä olen sinun ja sinun veljiesi, profeettain, kanssapalvelija, ja niiden, jotka ottavat tämän kirjan sanoista vaarin; kumartaen rukoile Jumalaa".'),
(1700022,58,66,22,10,'Ja hän sanoi minulle: "Älä lukitse tämän kirjan profetian sanoja; sillä aika on lähellä.'),
(1700023,58,66,22,11,'Vääryyden tekijä tehköön edelleen vääryyttä, ja joka on saastainen, saastukoon edelleen, ja joka on vanhurskas, tehköön edelleen vanhurskautta, ja joka on pyhä, pyhittyköön edelleen.'),
(1700024,58,66,22,12,'Katso, minä tulen pian, ja minun palkkani on minun kanssani, antaakseni kullekin hänen tekojensa mukaan.'),
(1700025,58,66,22,13,'Minä olen A ja O, ensimmäinen ja viimeinen, alku ja loppu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1700026,58,66,22,14,'Autuaat ne, jotka pesevät vaatteensa, että heillä olisi valta syödä elämän puusta ja he pääsisivät porteista sisälle kaupunkiin!'),
(1700027,58,66,22,15,'Ulkopuolella ovat koirat ja velhot ja huorintekijät ja murhaajat ja epäjumalanpalvelijat ja kaikki, jotka valhetta rakastavat ja tekevät.'),
(1700028,58,66,22,16,'Minä, Jeesus, lähetin enkelini todistamaan näitä teille seurakunnissa. Minä olen Daavidin juurivesa ja hänen suvustansa, se kirkas kointähti."'),
(1700029,58,66,22,17,'Ja Henki ja morsian sanovat: "Tule!" Ja joka kuulee, sanokoon: "Tule!" Ja joka janoaa, tulkoon, ja joka tahtoo, ottakoon elämän vettä lahjaksi.'),
(1700030,58,66,22,18,'Minä todistan jokaiselle, joka tämän kirjan profetian sanat kuulee: Jos joku panee niihin jotakin lisää, niin Jumala on paneva hänen päällensä ne vitsaukset, jotka ovat kirjoitetut tähän kirjaan;'),
(1700031,58,66,22,19,'ja jos joku ottaa pois jotakin tämän profetian kirjan sanoista, niin Jumala on ottava pois sen osan, mikä hänellä on elämän puuhun ja pyhään kaupunkiin, joista tässä kirjassa on kirjoitettu.'),
(1700032,58,66,22,20,'Hän, joka näitä todistaa, sanoo: "Totisesti, minä tulen pian". Amen, tule, Herra Jeesus!');
